INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('echo-3', 'Echo 3', 'Echo 3', 'https://phimimg.com/upload/vod/20240418-1/cbc3f30179a223d102f8d5178f4c2799.jpg', 'https://phimimg.com/upload/vod/20240418-1/5cb9cd262ebe50350bca3f24672416f6.jpg', '<p>Khi nhà khoa học lỗi lạc Amber Chesborough biến mất dọc biên giới Colombia-Venezuela, anh trai cô và chồng cô - cả hai đều là đặc công tinh nhuệ của Quân đội Hoa Kỳ—đấu tranh để tìm cô giữa một cuộc chiến tranh du kích, khám phá ra rằng người phụ nữ họ yêu có thể có một bí mật.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324303);
