INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-phieu-bi-mac-ket', 'Cổ Phiếu Bị Mắc Kẹt', 'Stockstruck', 'https://phimimg.com/upload/vod/20240409-1/615e29abdf4c5ee2b5cdbb712b4622e1.jpg', 'https://phimimg.com/upload/vod/20240409-1/60a7563489ad4870ce6412cc294eff8c.jpg', '<p>Cổ Phiếu Bị Mắc Kẹt - Stockstruck là câu chuyện về tình bạn, tình yêu qua cổ phiếu. Năm nhà đầu tư đã đến một cuộc họp chứng khoán bí ẩn. Mỗi người tham dự đều mang một lý do riêng. Tuy nhiên, thông qua các giao dịch chứng khoán, mỗi người đều có thêm kinh nghiệm về cuộc sống, tình yêu và tình bạn của riêng mình.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Ji Eun","avatar":""},{"name":"Hong Jong-Hyun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324303);
