INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-ve-nhung-anh-hung-dai-ngan-ha-die-neue-these-dot-kich', 'Huyền Thoại Về Những Anh Hùng Dải Ngân Hà: Die Neue These - Đột Kích', 'Legend Of The Galactic Heroes: Die Neue These - Collision, Ginga Eiyuu Densetsu: Die Neue These - Gekitotsu', 'https://phimimg.com/upload/vod/20240409-1/ef34c89671ddf48692b32a5abc3c2983.jpg', 'https://phimimg.com/upload/vod/20240409-1/5f97e4aeb390f71cef365aeb8f552246.jpg', '<p>Sau hơn 150 năm rơi vào bế tắc giữ hai siêu cường liên sao, Đế Quốc Ngân Hà và Liên Minh Các Tiểu Hành Tinh Tự Do, một thế hệ lãnh đạo mới đã xuất hiện: Thiên tài quân sự Reinhard von Lohengramm của phe Đế Quốc, và nhà sử học của phe Liên Minh, Yang Wen-li. Nhờ sự giúp đỡ của người bạn thân Kircheis Siegfried, Reinhard ngày càng thăng tiến trong Đế Quốc. Reinhard không chỉ vừa chiến đấu trên các trận chiến mà còn phải chiến đấu chống lại tàn dư của Vương Triều Goldenbaum sụp đổ để giải thoát em gái mình khỏi Kaiser và thống nhất nhân loại thành một thể thống nhất. Trong khi đó, bên kia ngân hà, Yang lại là người ủng hộ mạnh mẽ lý tưởng dân chủ bất chấp sự phản đối của Liên minh tự do. Anh cũng muốn chứng minh cho người học trò Minci Julian thấy rằng chế độ quân chủ chuyên chế không phải là cách duy nhất giải quyết vấn đề. Khi chiến tranh nổ ra, cả Reinhard và Yang đều cố gắng chiến đấu cho lý tưởng của mình với tư cách là người lãnh đạo trong kỷ nguyên mới của các anh hùng dải ngân hà. Đây là phần 3 của bộ phim.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324303);
