INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uu-tu-phan-6', 'Ưu Tú (Phần 6)', 'Elite (Season 6)', 'https://phimimg.com/upload/vod/20240409-1/3816e37fe3465a520b66293a3a4d64d3.jpg', 'https://phimimg.com/upload/vod/20240409-1/8085c295232f8c1ba7e8bbe72310108b.jpg', '<p>Mọi người đều tìm kiếm điều gì đó trong năm nay ở Las Encinas, bất kể là tình yêu, cơ hội trả thù hay hàng triệu người theo dõi. Nhưng liệu rằng tất cả đều sẽ thành công?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Itzan Escamilla","avatar":""},{"name":"Miguel Bernardeau","avatar":""},{"name":"Danna Paola","avatar":""},{"name":"Arón Piper","avatar":""},{"name":"Omar Ayuso","avatar":""},{"name":"Claudia Salas","avatar":""},{"name":"Georgina Amorós","avatar":""},{"name":"Álvaro Rico","avatar":""},{"name":"Ester Expósito","avatar":""},{"name":"Manu Ríos","avatar":""},{"name":"Carla Díaz","avatar":""},{"name":"Martina Cariddi","avatar":""},{"name":"Mina El Hammani","avatar":""},{"name":"Jorge López","avatar":""},{"name":"María Pedraza","avatar":""},{"name":"Miguel Herrán","avatar":""},{"name":"Jaime","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324303);
