INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('farzar', 'Farzar', 'Farzar', 'https://phimimg.com/upload/vod/20240409-1/545735147c5a40ed6873cf92229629f7.jpg', 'https://phimimg.com/upload/vod/20240409-1/fc2da5c2c34387b1b8c80480144942a6.jpg', '<p>Sống ở thuộc địa của con người trên thế giới ngoài hành tinh và thề cứu hành tinh này khỏi cái xấu, nhưng rồi hoàng tử Fichael biết được bố mình là ác nhân xấu xa nhất.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Kaye","avatar":""},{"name":"Jerry Minor","avatar":""},{"name":"Lance Reddick","avatar":""},{"name":"Dana Snyder","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"Roger Black","avatar":""},{"name":"Grey Griffin","avatar":""},{"name":"Waco O''Guin","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324303);
