INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('farzar', 'Farzar', 'Farzar', 'farzar farzar david kaye jerry minor lance reddick dana snyder kari wahlgren carlos alazraqui roger black grey griffin waco o''guin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('orient', 'Orient', 'Orient', 'https://phimimg.com/upload/vod/20240409-1/6b0d77ceaa5f1da580d50c234110fd03.jpg', 'https://phimimg.com/upload/vod/20240409-1/c473d90dd5fbf050f98ef5bfdd11daa4.jpg', '<p>5 năm trước, Musashi đã hứa với người bạn Kojirou Kanemaki của mình rằng một khi lớn lên, họ sẽ trở thành samurai (Võ Sĩ), thành lập liên minh (Võ Sĩ Đoàn) và thực hiện các nhiệm vụ tiêu diệt quỷ. Nhưng kể từ đó, mọi thứ đã thay đổi. Với việc ma quỷ ngày nay được xã hội ca tụng và tôn thờ, các samurai bị xa lánh và miệt thị. Sợ để lộ ước mơ trở thành samurai, Musashi hòa mình vào giáo điều của thị trấn bằng cách trở thành một thợ mỏ trong khi bí mật đánh bóng kiếm thuật của mình. Trong khi đó, mặc dù là hậu duệ trực tiếp của một samurai, Kojirou từ bỏ lời hứa với người bạn cũ của mình. Tuy nhiên, sau khi cứu Musashi khỏi trải nghiệm cận kề cái chết, quan điểm của anh ấy đã thay đổi. Mặc dù vẫn còn mâu thuẫn, Kojirou bắt đầu một cuộc hành trình với Musashi với hy vọng tìm ra cảm xúc thực sự của mình. Chiến đấu chống lại tất cả các tỷ lệ cược, bộ đôi lao đầu vào thế giới vô danh của những con thú giết người, không biết cuộc sống có gì dành cho họ. Giờ đây, cưỡi ngựa sắt, các anh hùng 15 tuổi lên kế hoạch khôi phục danh tiếng đã bị hoen ố của các samurai và thanh trừng thế giới của quỷ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324303);
