INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cua-mua-he', 'Bí Mật Của Mùa Hè', 'Secrets Of Summer', 'https://phimimg.com/upload/vod/20240409-1/48348f7a89d332ba6528fb8af688632c.jpg', 'https://phimimg.com/upload/vod/20240409-1/5204928b895cc993b508ed86c43b1365.jpg', '<p>Khu nghỉ dưỡng xa xôi ở Argentina tổ chức lại một cuộc thi lướt ván và thu hút vận động viên người Mexico Steffi, người quyết tâm lật mở một bí mật gia đình.</p>', 'Full', 11, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pilar Pascual","avatar":""},{"name":"Abril Di Yorio","avatar":""},{"name":"Víctor Varona","avatar":""},{"name":"Guido Messina","avatar":""},{"name":"Francisco Bass","avatar":""},{"name":"Giulia Guerrini","avatar":""},{"name":"Thais Rippel","avatar":""},{"name":"Luan Brum","avatar":""},{"name":"Fernando Monzo","avatar":""},{"name":"Juan Monzo","avatar":""},{"name":"Agustín Pardella","avatar":""},{"name":"Mariel Percossi","avatar":""},{"name":"Byron Barbieri","avatar":""},{"name":"Martín Tecchi","avatar":""},{"name":"Débora Nishimoto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324304);
