INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-luat-su', 'Bác Sĩ Luật Sư', 'Doctor Lawyer', 'https://phimimg.com/upload/vod/20240409-1/472bec706b8bc54521edcb428ddd9e51.jpg', 'https://phimimg.com/upload/vod/20240409-1/bbafc58d5a7bb2e48a9cea2451a9d4d9.jpg', '<p>Một bác sĩ phẫu thuật thiên tài, người đã trở thành một luật sư chuyên về kiện tụng y tế sau khi mất tất cả mọi thứ thông qua một cuộc phẫu thuật gian lận, và một công tố viên phụ trách tội phạm y tế, người đã mất gia đình và người yêu duy nhất của cô ấy vì cuộc phẫu thuật đó, làm việc cùng nhau để trừng phạt những người tin rằng sự giàu có và quyền lực cũng có thể xếp hạng cuộc sống và an ủi các nạn nhân của sự bất công.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 18, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"So Ji Sub","avatar":""},{"name":"Im Soo Hyang","avatar":""},{"name":"Shin Sung Rok","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324304);
