INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-si-luat-su', 'Bác Sĩ Luật Sư', 'Doctor Lawyer', 'bác sĩ luật sư doctor lawyer so ji sub im soo hyang shin sung rok ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-vinh-du', 'Cảnh Sát Vinh Dự', 'Ordinary Greatness', 'https://phimimg.com/upload/vod/20240409-1/b93fe6a20aafe20906a4b743a11152ba.jpg', 'https://phimimg.com/upload/vod/20240409-1/0ca863874aefd8e1f0cfd58c00af8f3c.jpg', '<p>Cảnh Sát Vinh Dự là bộ phim xoay quanh câu chuyện về bốn cảnh sát trẻ mới gia nhập đồn cảnh sát Bát Lí Hà. Lý Đại Vi vì quá cứng đầu, nghich ngợm nên bị bố mẹ ép đến viện cảnh sát. Dương Thụ thạc sĩ luật Đại học Bắc Kinh cứng nhắc và chính trực. Hạ Khiêt thừa hưởng ý chí của cha quyết tâm trở thành một nữ cảnh sát. Triệu Kế Vỹ đến từ vùng nông thôn, luôn cố gắng để bản thân trở lên xuất sắc. Theo đặc điểm của bốn cảnh sát mới, sở trưởng Vương Thủ Nhất đã sắp xếp bốn vị tiền bối để giúp đỡ chỉ dẫn họ. Trong thời gian một năm thực tập, bốn cảnh sát mới nhận ra rằng công việc ở đây khác với những gì họ tưởng tượng. Cùng với sự giúp đỡ của các tiền bối, bốn người họ đã nhanh chóng vượt qua được những thách thức, có được những thành công và trở thành những cảnh sát nhân dân xuất sắc.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Ruo Yun","avatar":""},{"name":"Bạch Lộc","avatar":""},{"name":"Vương Cảnh Xuân","avatar":""},{"name":"Ninh Lý","avatar":""},{"name":"Từ Khai Sính","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324304);
