INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('romesh-ranganathan-nguoi-hoai-nghi', 'Romesh Ranganathan: Người Hoài Nghi', 'Romesh Ranganathan: The Cynic', 'https://phimimg.com/upload/vod/20240409-1/1554d5d7a4f0fdd6f03ebf03730da7f2.jpg', 'https://phimimg.com/upload/vod/20240409-1/41feac56468f632af13a80b08042cb3e.jpg', '<p>Trở lại quê nhà ở Crawley, Anh, Romesh Ranganathan bông đùa về chủ nghĩa thuần chay, các con và hé lộ quá trình thực hiện chương trình hài đặc biệt của mình.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Romesh Ranganathan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324304);
