INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-don-doc', 'Hành Trình Đơn Độc', 'Walker Independence', 'https://phimimg.com/upload/vod/20240409-1/384d502f13ab2a29d83c8c8a6f137d7e.jpg', 'https://phimimg.com/upload/vod/20240409-1/3a9de29c985fe9e25b352c5ccb560d79.jpg', '<p>Bối cảnh của phim diễn ra vào cuối thế kỷ 19, kể về Abby Walker, một người phụ nữ giàu có đến từ Boston. Trên hành trình đi về phía Tây, chồng của Abby bị giết ngay trước mắt cô. Sau đó, Abby tình cờ gặp Hoyt Rawlins, một tên lưu manh tìm kiếm ý nghĩa cuộc đời. Hành trình của Abby và Hoyt đưa họ đến Independence, Texas - một thị trấn nhỏ với tương lai lớn. Đó là câu chuyện khởi đầu của Abby trên con đường tìm kiếm công lý và Hoyt tìm ra mục đích sống của mình.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 19, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Katherine McNamara","avatar":""},{"name":"Matt Barr","avatar":""},{"name":"Justin Johnson Cortez","avatar":""},{"name":"Greg Hovanessian","avatar":""},{"name":"Lawrence Kao","avatar":""},{"name":"Philemon Chambers","avatar":""},{"name":"Katie Findlay","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324304);
