INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-dem-sao', 'Đêm Đếm Sao', 'Astrophile', 'https://phimimg.com/upload/vod/20240409-1/aea8f085844868cebbd25c6a57d182d9.jpg', 'https://phimimg.com/upload/vod/20240409-1/c4e0ef4f4ddf1b2e6c352ed12e5885b5.jpg', '<p>Đêm Đếm Sao - Astrophile kể về câu chuyện tình yêu đầy thú vị của anh chàng Mater (Bright Vachiravit) và MC bán hàng Nubdao (Mai Davika). Dù phải lòng Nubdao đã lâu, Mater không đủ dũng cảm để thổ lộ tình cảm của mình. Bẵng đi vài năm, Mater gặp lại Nubdao và quyết định theo đuổi cô, nhưng lúc này anh phải đối đầu với tình địch do Off Jumpol thủ vai.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Mai Davika","avatar":""},{"name":"Bright Vachirawit","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324304);
