INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lat-lat-dot-nhien-nghi-toi-2', 'Lạt Lạt Đột Nhiên Nghĩ Tới 2', 'Tata''s  Rainbow Brainstorm 2', 'https://phimimg.com/upload/vod/20240409-1/0504dde0637f285d1c41ae32f935920b.jpg', 'https://phimimg.com/upload/vod/20240409-1/7c2d679ed1140db6f425714ebaf535c6.jpg', '<p>Lạt Lạt thích uống cô ca, tính cách lười biếng tiếp tục mở mang đầu óc, trong cuộc sống thường ngày vô cùng chân thật, lại thăng cấp ảo tưởng rồi. Lạt Lạt cùng bạn của cậu dẫn bạn cùng đi phát hiện các loại khả năng đặc sắc, nhẹ nhàng đối diện với các thử thách chân thật của cuộc sống. Chú Marmot của Lạt Lạt, bạn của Lạt Lạt và Lạt Lạt cùng nhay vui vẻ high lên nào.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324304);
