INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-o-vinh-lon-phan-2', 'Đêm Ở Vịnh Lớn (Phần 2)', 'Night In The Greater Bay (Season 2)', 'https://phimimg.com/upload/vod/20240409-1/3ca87e909f5479300633aae241c39678.jpg', 'https://phimimg.com/upload/vod/20240409-1/1bbca19fbb6d0c7a960a21dace64c5ce.jpg', '<p>Tiếp tục đổi mới và nâng cấp tường thuật của chương trình, kết hợp giữa văn hóa hộp đuôi phổ biến và nền kinh tế chợ đêm, đồng thời cùng vận hành một xe bán đồ ăn đêm kiểu Hồng Kông di động. Bằng cách quảng bá văn hóa ẩm thực của Khu Vịnh Lớn ở nhiều nơi, nó khéo léo kết hợp việc quan sát và trình bày của các nhóm xã hội như những người xây dựng Khu Vịnh Lớn Quảng Đông-Hồng Kông-Macao, những người quảng bá văn hóa ẩm thực tuyệt vời của Trung Quốc, và những người đấu tranh ở những cương vị khác nhau trong thời đại mới. Lấy thức ăn làm sợi chỉ và con người làm tấm gương, nó kết nối và phản chiếu những bức tranh về đất nước Trung Quốc tươi đẹp và cuộc sống hạnh phúc của người dân trong mười năm qua.</p>', 'Hoàn Tất (7/7)', 7, 'tvshows', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324304);
