INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-xa-3-long-xa-dai-chien', 'Đại Xà 3: Long Xà Đại Chiến', 'Snake 3: Dinosaur vs Python', 'https://phimimg.com/upload/vod/20240502-1/e1bfc7acd0b40954fe318db78f9f9f8f.jpg', 'https://phimimg.com/upload/vod/20240502-1/d08d0c6cf42ddba84c114563eac37fc9.jpg', '<p>Khi khí hậu toàn cầu ấm lên, các sông băng tan chảy và một hòn đang tan chảy và một hòn đảo biệt lập xuất hiện. Một nhóm du lịch vô tình đáp xuống hòn đảo, làm phiền con thú thời tiền sử đang ẩn náu. Xiao Nan và con trai Xiao Kai đã bị chia cắt để tìm kiếm Xiao Kai, đội cứu hộ vô tình vướng vào cuộc chiến giữa hai chúa tể rắn lớn và khủng long hung bạo.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Zihan","avatar":""},{"name":"Luo Liqun","avatar":""},{"name":"Li Ruoxi","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Zhong Lei","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324304);
