INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dang-hinh-tinh-yeu', 'Dáng Hình Tình Yêu', 'Love The Way You Are', 'https://phimimg.com/upload/vod/20240409-1/7524dae911f99ac3c657f3ae0c0fbe65.jpg', 'https://phimimg.com/upload/vod/20240409-1/36a5a4e76d04bd27fbe01a6093b6c9bd.jpg', '<p>Doãn Diệc Khả người dường như có một cuộc sống hoàn hảo, dù ở văn phòng hay ở nhà, cô gái ngoài 30 tuổi ấy giống như Wonder Woman. Cô ấy rất quan tâm đến mọi người xung quanh, nhưng đã quên giữ sự ấm áp trong trái tim mình. Cho đến khi ở một góc cửa hàng tiện lợi cô gặp lại cậu bé hay đến nhà mình ăn cơm lúc nhỏ Từ Quang Tây thì mọi chuyện đã thay đổi. Từ Quang Tây bây giờ đã là một chàng trai tràn đầy ánh nắng, anh đã sưởi ấm trái tim cô. Gặp lại cô sau khi du học về, sự dựa dẫm của Từ Quang Tây đối với cô khi còn nhỏ đã phát triển thành tình cảm không thể cưỡng lại. Nhưng theo đuổi Doãn Diệc Khả không phải là một việc dễ dàng. Điều đó có nghĩa là Quảng Tây sẽ phải trưởng thành nhanh chóng và chịu những áp lực của thực tế. Vì tình yêu, anh dần trưởng thành và học cách điều chỉnh tốc độ của mình để tiến về phía cô một cách dễ dàng. Sau khi trải qua một số chuyện, họ hiểu ra ý nghĩa của tình yêu. Đó không phải là hi sinh cho nhau mà là thu hút lẫn nhau, tôn trọng lẫn nhau và khiến đối phương trưởng thành hơn.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Angelababy","avatar":""},{"name":"Eddie Edward","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324304);
