INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-tam-than-joseon-yoo-se-poong', 'Bác Sĩ Tâm Thần Joseon Yoo Se Poong', 'Poong, The Joseon Psychiatrist', 'https://phimimg.com/upload/vod/20240409-1/359d5ca5bd50d1fa912ff020993e9270.jpg', 'https://phimimg.com/upload/vod/20240409-1/7605ffa257275401faec38ba6ecfa2f5.jpg', '<p>Bộ phim dựa trên cuốn tiểu thuyết cùng tên đã đoạt giải Xuất sắc trong Cuộc thi Câu chuyện Hàn Quốc năm 2016, nó mô tả câu chuyện của các bác sĩ tâm thần ở Joseon.Yoo Se Poong (Kim Min Jae), một bác sĩ thiên tài, người bị cuốn vào một âm mưu hoàng gia và bị đuổi ra ngoài, gặp một giáo viên lập dị, Gye Ji Han (Kim Sang kyung) và một góa phụ, Seo Eun Woo (Kim Hyang gi ) của Làng Gyesu bí ẩn và xinh đẹp, và được tái sinh thành một bác sĩ thực thụ.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Min Jae","avatar":""},{"name":"Kim Hyang Gi","avatar":""},{"name":"Kim Sang kyung","avatar":""},{"name":"Ahn Chang Hwan","avatar":""},{"name":"Yoo Sung Joo","avatar":""},{"name":"Jung Won Chang","avatar":""},{"name":"Lee Seo Hwan","avatar":""},{"name":"Jeon Guk Hyang","avatar":""},{"name":"Yeon Bora","avatar":""},{"name":"Kim Soo Ann","avatar":""},{"name":"Han Chang Min","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324304);
