INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-dau-muay-thai', 'Nỗi Đau Muay Thái', 'Hurts Like Hell', 'https://phimimg.com/upload/vod/20240409-1/f8fbefa18978e5671bb5368c88d349cc.jpg', 'https://phimimg.com/upload/vod/20240409-1/23152660536fd31c79ca8fa167f5e2ce.jpg', '<p>Từ cá cược bất hợp pháp đến dàn xếp tỷ số, hãy khám phá thế giới ngầm đáng sợ đằng sau môn thể thao Muay Thái từng được ca tụng. Phim chính kịch dựa trên sự kiện có thật.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Nat Kitcharit","avatar":""},{"name":"Thaneth Warakulnukroh","avatar":""},{"name":"Vithaya Pansringarm","avatar":""},{"name":"Phuripat Poonsuk","avatar":""},{"name":"Nopachai Jayanama","avatar":""},{"name":"Supakorn Kitsuwon","avatar":""},{"name":"Kiartwaran Piboonsin","avatar":""},{"name":"Chonnikan Netjui","avatar":""},{"name":"Narueworn Iamcharoen","avatar":""},{"name":"Udomsak Onkaew","avatar":""},{"name":"Phumphat Chartsuriyakiat","avatar":""},{"name":"Seadthawut Porntanawut","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324304);
