INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('noi-dau-muay-thai', 'Nỗi Đau Muay Thái', 'Hurts Like Hell', 'nỗi đau muay thái hurts like hell nat kitcharit thaneth warakulnukroh vithaya pansringarm phuripat poonsuk nopachai jayanama supakorn kitsuwon kiartwaran piboonsin chonnikan netjui narueworn iamcharoen udomsak onkaew phumphat chartsuriyakiat seadthawut porntanawut ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-tan-binh', 'Cảnh Sát Tân Binh', 'Rookie Cops', 'https://phimimg.com/upload/vod/20240409-1/84835533f1bb61f84548f0196a031360.jpg', 'https://phimimg.com/upload/vod/20240409-1/0ac71b7e713e6ec252b16c7d0a00d392.jpg', '<p>Phim miêu tả về cuộc sống trong khuôn viên trường đại học cảnh sát của những người trẻ tuổi đầy nhiệt huyết, đam mê, nơi chứa đựng tuổi 20 vụng về và đầy sai lầm nhưng lại tỏa sáng hơn ai hết. Tấm vé xuất cảnh đầy tham vọng của những cảnh sát tay mơ sẽ làm đảo lộn cả học viện cảnh sát, mang đến những tràng cười sảng khoái và cả những tình tiết hồi hộp gay cấn.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Chae Soo Bin","avatar":""},{"name":"Park Yoo Na","avatar":""},{"name":"Kang Daniel","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324304);
