INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('notredame', 'Notre-Dame', 'Notre-Dame', 'https://phimimg.com/upload/vod/20240409-1/4328c6aaf1a7056c413c0df8a14dfecc.jpg', 'https://phimimg.com/upload/vod/20240409-1/00cf760096ebf16d8b44d903f85faa95.jpg', '<p>Dựa trên lời kể có thật của lính cứu hỏa người Pháp, loạt phim chính kịch này khám phá tác động của vụ cháy nhà thờ Đức Bà năm 2019 đối với một nhóm người Paris khác nhau.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Roschdy Zem","avatar":""},{"name":"Caroline Proust","avatar":""},{"name":"Megan Northam","avatar":""},{"name":"Simon Abkarian","avatar":""},{"name":"Alice Isaaz","avatar":""},{"name":"Sandor Funtek","avatar":""},{"name":"Marie Zabukovec","avatar":""},{"name":"Corentin Fila","avatar":""},{"name":"Kassem Al Khoja","avatar":""},{"name":"Rayad Mohamed","avatar":""},{"name":"Frédéric Chau","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324304);
