INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-canh-sat-paradise-phan-4', 'Sở Cảnh Sát Paradise (Phần 4)', 'Paradise PD (Season 4)', 'https://phimimg.com/upload/vod/20240409-1/b698cd758595fa48ca628bd52a31306e.jpg', 'https://phimimg.com/upload/vod/20240409-1/f0b25fb6904b32e6c72a1f4cc86d69d3.jpg', '<p>Khi lực lượng cảnh sát không hoạt động, thị trấn đối mặt với những mối đe dọa từ tỷ phú mưu mô, nghệ sĩ thù hằn, AI đâm sau lưng, v.v.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Kenny","avatar":""},{"name":"David Herman","avatar":""},{"name":"Sarah Chalke","avatar":""},{"name":"Kyle Kinane","avatar":""},{"name":"Dana Snyder","avatar":""},{"name":"Cedric Yarbrough","avatar":""},{"name":"Grey Griffin","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Roger Black","avatar":""},{"name":"Waco O''Guin","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324304);
