INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-toi-tro-ve-tu-di-gioi', 'Chú Tôi Trở Về Từ Dị Giới', 'Uncle From Another World', 'https://phimimg.com/upload/vod/20240409-1/bf60f49cfe4787b91274e0e89a2edb7f.jpg', 'https://phimimg.com/upload/vod/20240409-1/c8c2e8671bd2d60eb6ed439cfe853d43.jpg', '<p>Sau khi hôn mê suốt 17 năm, người chú trung niên của Takafumi đột nhiên tỉnh dậy rồi nói một thứ ngôn ngữ khó nhận biết cũng như sử dụng sức mạnh ma thuật.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Koyasu Takehito","avatar":""},{"name":"Fukuyama Jun","avatar":""},{"name":"Komatsu Mikako","avatar":""},{"name":"Tomatsu Haruka","avatar":""},{"name":"Yuki Aoi","avatar":""},{"name":"Toyosaki Aki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324304);
