INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ong-hoan-hao-tvb', 'Người Đàn Ông Hoàn Hảo TVB', 'A Perfect Man', 'https://phimimg.com/upload/vod/20240409-1/ad4f261e22c59c075adec7a788fb9558.jpg', 'https://phimimg.com/upload/vod/20240409-1/9c23e04c74e812cddecf37e16febe6da.jpg', '<p>Mã Đức Chung từng làm vệ sĩ cho các nhân vật quan trọng trước khi làm diễn viên. Trong phim “Người đàn ông hoàn hảo”, Mã Đức Chung có dịp thể hiện tài năng làm vệ sĩ của mình. Dương Nhật Chính (do Mã Đức Chung đóng) từng là thành viên của G4 và đội Phi Hổ, là nhân tài trong giới vệ sĩ. Anh được bạn thân Hạ Trung Thu (do Từ Vinh đóng) giới thiệu làm vệ sĩ cho đại gia Tưởng Định Thiên (do Trương Quốc Cường đóng). Với tính cách lạnh lùng, các đồng nghiệp trong công ty vệ sĩ đều không thích Chính. Chính gặp rắc rối với Lại Hoằng Trí (do Âu Thoại Vĩ đóng), La Thiếu Na (do Dương Trác Na đóng) và Phù Tuấn (do Tào Vĩnh Liêm đóng). Mặt khác, Chính không có lòng tin với hôn nhân, anh không thích sự ràng buộc. Ngay cả cô út của Chính là Dương Phi Vân (do Trần Tự Dao đóng) cũng chịu thua tính cách này của anh.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2022, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Joe Ma","avatar":""},{"name":"Ali Lee","avatar":""},{"name":"Ricco Ng","avatar":""},{"name":"Yoyo Chen","avatar":""},{"name":"Tsui Wing","avatar":""},{"name":"Raymond Cho","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324304);
