INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-nhan-chop-nhoang', 'Hôn Nhân Chớp Nhoáng', 'Wiwa Fah Laep', 'https://phimimg.com/upload/vod/20240409-1/3b7f1857cf117114435c1cc5a09a4119.jpg', 'https://phimimg.com/upload/vod/20240409-1/fe692e6bb709320503fa798795f2eb0b.jpg', '<p>Nàng là một dân chơi chính hiệu, còn chàng là công tử nơi tỉnh lẻ. Hai người gặp gỡ và ác cảm với đối phương ngay từ lần gặp đầu tiên. Thế nhưng chạy trời không khỏi nắng, trong một lần vô tình say xỉn, chàng và nàng đã cùng nhau trải qua một đêm mặn nồng và đám cưới của hai người diễn ra đầy chớp nhoáng.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 12, 2022, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Tono Phakin Khamwilaisak","avatar":""},{"name":"Pooklook Fonthip Watcharatrakul","avatar":""},{"name":"Sakakorn Pitchanart","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324304);
