INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('king-of-stonks', 'King Of Stonks', 'King Of Stonks', 'https://phimimg.com/upload/vod/20240409-1/a86f9f2953fa8fbc3bee227c386bd5aa.jpg', 'https://phimimg.com/upload/vod/20240409-1/2c1b85436a8822cb4dd6e0c1f3f50126.jpg', '<p>Với tham vọng khởi nghiệp thành công quá lớn, tay tội phạm tài chính nói dối, gian lận và âm mưu đưa công ty không mấy uy tín của mình tiến xa.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Thomas Schubert","avatar":""},{"name":"Matthias Brandt","avatar":""},{"name":"Larissa Sirah Herden","avatar":""},{"name":"Sophia Burtscher","avatar":""},{"name":"Altine Emini","avatar":""},{"name":"Andreas Döhler","avatar":""},{"name":"Julian Sark","avatar":""},{"name":"Bibiana Beglau","avatar":""},{"name":"Lazar Simaifar","avatar":""},{"name":"Ali Salman","avatar":""},{"name":"Wilson Gonzalez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324304);
