INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-vong-hon-nhan', 'Tham Vọng Hôn Nhân', 'Remarriage & Desires', 'https://phimimg.com/upload/vod/20240409-1/bc6aaa0e32e3998ca9e69eed5c25eec6.jpg', 'https://phimimg.com/upload/vod/20240409-1/29a3b3a44c812677339e8623e2fdf9b5.jpg', '<p>Thông qua một công ty mai mối độc quyền phục vụ giới siêu giàu, một phụ nữ âm mưu trả thù cô tình nhân mưu mô của chồng cũ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Hee Seon","avatar":""},{"name":"Lee Hyun Wook","avatar":""},{"name":"Jung Eugene","avatar":""},{"name":"Park Hoon","avatar":""},{"name":"Cha Ji Yeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324304);
