INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-truong-co-gi-sai-sai', 'Đội Trưởng Có Gì Sai Sai', 'My Amazing Captain', 'https://phimimg.com/upload/vod/20240409-1/9303b8af9ddc3abaa2059cc159dfec9b.jpg', 'https://phimimg.com/upload/vod/20240409-1/3ba62b08cd149a93ee66761f1102b70b.jpg', '<p>Thiên tài bóng rổ Chung Đại Hải đột nhiên trở thành nữ sau một tai nạn bất ngờ. Tuy nhiên cậu ấy vẫn không hề từ bỏ ước mơ của mình và vô tình tham gia vào đội bóng rổ với tư cách là thành viên đội cổ vũ. Cô ấy vừa phải đối phó với cậu bạn thân Lục Tinh Tề, vừa phải đối phó sự giám sát của Diệp Nhiên, người của bác sĩ, để che giấu thân phận của mình, từ đó đã gây ra rất nhiều chuyện cười ra nước mắt. Tuy nhiên trên thực tế Chung Đại Hải vốn là nữ giới mắc chứng rối loạn định dạng giới, nên trước giờ vẫn nghĩ mình là nam.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 4, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Junhao","avatar":""},{"name":"Pan Yuetong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324304);
