INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-chet-gio-tay-ke-doc-hanh', 'Ai Chết Giơ Tay: Kẻ Độc Hành', 'Land Of Spirits: The Young Shaman', 'https://phimimg.com/upload/vod/20240409-1/5dbc7e1eb190025adaa2da63da497a82.jpg', 'https://phimimg.com/upload/vod/20240409-1/456eaaaa1d02008061aefb800ae5a853.jpg', '<p>Sinh ra trong gia đình làm nghề trừ tà, vị pháp sư nghiệp dư nọ sử dụng chuyên môn của mình để bắt ma ở khu phố ngập tràn hoạt động siêu nhiên.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Huỳnh Lập","avatar":""},{"name":"Quốc Khánh","avatar":""},{"name":"Puka","avatar":""},{"name":"Hồng Vân","avatar":""},{"name":"Duy Anh","avatar":""},{"name":"Hứa Minh Đạt","avatar":""},{"name":"Lâm Vỹ Dạ","avatar":""},{"name":"Vy Vân","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324304);
