INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-gia-tu-xung-la-do-de-hien-gia-tai-di-gioi', 'Hiền Giả Tự Xưng Là Đồ Đệ Hiền Giả Tại Dị Giới', 'Kenja No Deshi Wo Nanoru Kenja, She Professed Herself Pupil Of The Wise Man', 'https://phimimg.com/upload/vod/20240409-1/7ae233003ea630b3f59c03d10fbde213.jpg', 'https://phimimg.com/upload/vod/20240409-1/901b21a36c4f7d99cbcbe18662f15321.jpg', '<p>Sakimori Kagami đóng một VRMMORPG có tên Arch Earth Online. Anh ta là một game thủ kỳ cựu với cái tên và ngoại hình tương tự như một phù thủy già có râu trong một cuốn sách nào đó về võ đài. Một ngày nọ, anh ta mua một món đồ thay đổi ngoại hình như một phương sách cuối cùng để chi tiêu số tiền sắp hết hạn sử dụng và có ý tưởng chọn diện mạo của anh ta sẽ như thế nào nếu nhân vật của anh ta từng là một cô gái. Ngủ gật nên đã tạm dừng trò chơi, nhưng Kagami thức dậy vẫn trực tuyến và cảm thấy trò chơi đã trở nên thực tế hơn một chút. Arch Earth Online cuối cùng có nhận được bản cập nhật được chờ đợi từ lâu không?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324304);
