INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dang-kiep-doi-co-vu-noi-loan', 'Đáng Kiếp: Đội Cổ Vũ Nổi Loạn', 'Rebel Cheer Squad: A Get Even Series', 'https://phimimg.com/upload/vod/20240409-1/19dcd9ea541469fcd157c52028fcff6d.jpg', 'https://phimimg.com/upload/vod/20240409-1/3af87fcf2a1cfe6e9f7e404e40c0ae3a.jpg', '<p>Trong phim giật gân tuổi teen này, bộ ba hoạt náo viên ở một trường tư thục thượng lưu hồi sinh CLB chống bắt nạt của các bạn học cũ và bắt tay chống lại sự bất công.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Lashay Anderson","avatar":""},{"name":"Amelia Brooks","avatar":""},{"name":"Ashling O''Shea","avatar":""},{"name":"Ramanique Ahluwalia","avatar":""},{"name":"Niyi Akin","avatar":""},{"name":"Renee Bailey","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324304);
