INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-cu', 'Tâm Cư', 'LIFE IS A LONG QUIET RIVER', 'https://phimimg.com/upload/vod/20240409-1/ce0bcaf276d93e0797c9e8d0495ca81b.jpg', 'https://phimimg.com/upload/vod/20240409-1/649a60f6e8a387dfe12459495311c0c1.jpg', '<p>Câu chuyện diễn ra ở Thượng Hải vào năm 2019. Trong mắt Phùng Hiểu Cầm, bà cô 37 tuổi Cố Thanh Du là một \gái già\ không thể lấy chồng, nhưng trước mặt cô luôn nói: \Chị à, chị là người mà em ngưỡng mộ nhất.\ Gu Qingyu cũng đầy nghi ngờ về người chị dâu ngoại quốc này, em trai Gu Lei bị tật ở chân cũng không có triển vọng cho lắm, ngoại trừ hộ khẩu Thượng Hải. Gu Qingyu cảnh giác với người phụ nữ này với dòng chữ \thay đổi vận mệnh\ được viết trên khắp mặt cô, và đôi khi hy vọng rằng cô ấy sẽ chân thành với anh trai mình. Câu chuyện bắt đầu từ việc Gu Qingyu \kết hôn giả\ để mua nhà, và kể về những thay đổi mạnh mẽ của bốn thế hệ gia đình Gu trong quá trình thay nhà. Gu Lei chết bất đắc kỳ tử, Feng Xiaoqin từng bước trưởng thành, một mình gánh vác gia đình. Việc Gu Qingyu chuyển từ hôn nhân sang ly hôn cũng khiến nhận thức của cô về cuộc sống và gia đình bị lật đổ.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Christina","avatar":""},{"name":"Đồng Dao","avatar":""},{"name":"Trương Tụng Văn","avatar":""},{"name":"Phùng Thiệu Phong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324304);
