INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-xa-dien-nghia', 'Long Xà Diễn Nghĩa', 'Dragon''s Disciple', 'https://phimimg.com/upload/vod/20240409-1/081356424fea3b5ec3c552aa5113c8e7.jpg', 'https://phimimg.com/upload/vod/20240409-1/5beaa287f720e641f3e3dca075be7272.jpg', '<p>Dưới sự dẫn dắt của bậc thầy võ thuật cổ truyền Đường Tử Trần, thiếu niên Vương Siêu cơ thể yếu ớt nhưng rất giàu lòng chính nghĩa bước lên con đường võ thuật, luôn gặp thuận lợi, vượt qua chính mình. Anh đã được trải nghiệm tinh thần lấy võ thuật ngăn chặn đao thương, lấy đức khiến người ta nể phục của người học võ, cũng nêu cao võ thuật truyền thống, nêu cao tinh thần chính trực.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 4, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324304);
