INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-va-vo-chinh-phu-phan-2', 'Tình Yêu Và Vô Chính Phủ (Phần 2)', 'Love & Anarchy (Season 2)', 'https://phimimg.com/upload/vod/20240409-1/994862557a456d98bfdaaa8e46f36088.jpg', 'https://phimimg.com/upload/vod/20240409-1/0bc90c0b67ddb90b9417ce323c78a320.jpg', '<p>Sau khi nhận được tin tức đau lòng, việc Sofie chần chừ không đối diện với nỗi đau khiến cuộc sống, sự nghiệp và mối quan hệ của cô với Max rơi vào ngõ cụt.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 15, 2022, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Ida Engvoll","avatar":""},{"name":"Björn Mosten","avatar":""},{"name":"Carla Sehn","avatar":""},{"name":"Reine Brynolfsson","avatar":""},{"name":"Gizem Erdogan","avatar":""},{"name":"Björn Kjellman","avatar":""},{"name":"Ruben Lopez","avatar":""},{"name":"Johannes Kuhnke","avatar":""},{"name":"Elsa Agemalm Reiland","avatar":""},{"name":"Benjamin Shaps","avatar":""},{"name":"Disa Östrand","avatar":""},{"name":"Ejke Blomberg","avatar":""},{"name":"Lars Väringer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324304);
