INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-yeu-va-vo-chinh-phu-phan-2', 'Tình Yêu Và Vô Chính Phủ (Phần 2)', 'Love & Anarchy (Season 2)', 'tình yêu và vô chính phủ (phần 2) love & anarchy (season 2) ida engvoll björn mosten carla sehn reine brynolfsson gizem erdogan björn kjellman ruben lopez johannes kuhnke elsa agemalm reiland benjamin shaps disa östrand ejke blomberg lars väringer ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-am-ap-2', 'Kỳ Nghỉ Ấm Áp 2', 'Vacation Of Love 2', 'https://phimimg.com/upload/vod/20240409-1/e969a90d9f15c530faa92656fba390dc.jpg', 'https://phimimg.com/upload/vod/20240409-1/8155b758de893dc4b5cac76a19b2fa3c.jpg', '<p>Lại một mùa đông, Trình Mạn em gái của một phụ nữ mạnh mẽ trong thế giới đầu tư, đang ở Thượng Hải và chuẩn bị đưa con gái đến Tam Á ăn Tết do sai sót mà đã bay về quê nhà ở Đông Bắc Trung Quốc. Khổng Lệnh Kì, người sáng lập công ty tài chính, cũng theo Trình Mạn đến vùng Đông Bắc để thay đổi suy nghĩ của Trình Mạn. Sau một số lần hiểu nhầm, cuối cùng cả hai cũng đã giải tỏa được mối nghi ngờ của mình. Cô em gái Trình Thục ở quê nhà Đông Bắc kinh doanh homestay cũng đang đối mặt với nguy cơ phá sản, thì nhận được đơn hàng lớn từ trên trời rơi xuống của bạn trai cũ Vệ Kì. Liêu Nhiên một người có ước mơ trở thành đầu bếp. Ba người họ bước vào một đoạn tình cảm đầy khúc mắc. Cô cháu gái Trình Miểu sắp tốt nghiệp về quê đón Tết, một mình trượt tuyết để giải tỏa cảm xúc, lạc vào khu vực thi của cuộc thi máy bay không người lái và vô tình gặp Mã Bá Uyên, một cao thủ trong giới máy bay không người lái. Mã Bá Uyên phát hiện cô gái này rất có thiên phú, đồng thời có tình cảm đặc biệt với người con gái này. Mảnh đất phương Bắc này dùng hơi ấm độc đáo của mình để làm tan đi lớp băng giá trong lòng người, và giúp họ tìm ra mục đích sống của chính mình.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Đào","avatar":""},{"name":"MichaelChen","avatar":""},{"name":"Dương Lặc","avatar":""},{"name":"Jenny Zhang","avatar":""},{"name":"Trình Tiêu","avatar":""},{"name":"NiDaHong","avatar":""},{"name":"Ping Ni","avatar":""},{"name":"Jiang Chao","avatar":""},{"name":"張天陽","avatar":""},{"name":"Lula Zhou","avatar":""},{"name":"Jiang Man","avatar":""},{"name":"Bill","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324304);
