INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-tuong-quan-co-mot-nang-dau-bep', 'Phủ Tướng Quân Có Một Nàng Đầu Bếp', 'The Little Wife Of The General', 'https://phimimg.com/upload/vod/20240409-1/0154b847f9e4f6f50977d022d168565f.jpg', 'https://phimimg.com/upload/vod/20240409-1/d04d56a8bfb51a203d43ead98fca967b.jpg', '<p>Đầu bếp cao cấp Tô Thiển Thiển vô tình xuyên không vào cơ thể thứ nữ phủ Quốc công có cảnh ngộ thê thảm. Nhiệm vụ của hệ thống là tìm được ý trung nhân và động phòng với người đó mới có thể trở về thế giới thực. Tô Thiển Thiển chỉ đành tạm thời gả cho tướng quân bá đạo Sở Quân Dao, khổ nỗi Sở Quân Dao đã phải lòng người khác, Tô Thiển Thiển dùng tài nấu ăn để bắt đầu hành trình lội ngược dòng, tán mỹ nam, vả mặt kẻ giả tạo.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cui Yu Xin","avatar":""},{"name":"Smile Wei","avatar":""},{"name":"Qiu Yu Shuo","avatar":""},{"name":"Zhang Xing He","avatar":""},{"name":"Chen Hao Wen","avatar":""},{"name":"Qian Si Yi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324304);
