INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-tu-bo-tu-cach-la-mot-anh-hung', 'Tôi Từ Bỏ Tư Cách Là Một Anh Hùng', 'Yuusha, Yamemasu, I''m Quitting Heroing', 'https://phimimg.com/upload/vod/20240409-1/d7eb0fd4db545911faa9d9543737a2e8.jpg', 'https://phimimg.com/upload/vod/20240409-1/91ab60fc3498ae8b96471f41ab353b50.jpg', '<p>Sau khi cứu nhân loại khỏi Ma Vương nhưng Leo Demonhart lại không có được vị thế của một Anh Hùng. Thay vào đó, từ những người anh ta chiến đấu để bảo vệ lại quay sang nghi ngờ và thù địch. Leo bị trục xuất khỏi vương quốc, đi lang thang khắp mọi nơi. Đến khi không còn nơi nào để đi, Leo quyết định từ bỏ làm Anh Hùng và đầu quân cho Đội quân Ma Vương để tiêu diệt con người.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 4, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324304);
