INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-ve-si-cua-toi', 'Nàng Vệ Sĩ Của Tôi', 'My Lovely Bodyguard', 'https://phimimg.com/upload/vod/20240409-1/0b3305eb7f0a680d85e3f45db0552d87.jpg', 'https://phimimg.com/upload/vod/20240409-1/645d42e4e0056586679f43031da43468.jpg', '<p>bắt đầu từ sự kiện Chủ tịch Khanin, người sở hữu khối tài sản khổng lồ, cùng vợ đột ngột qua đời. Tuy nhiên, ông đã kịp thời làm di chúc trao lại toàn bộ tài sản cho con trai là bé Ekapop, đồng thời bổ nhiệm em vợ là Thewan, làm người quản lý toàn bộ tài sản thừa kế cũng như chăm sóc bé Ekapop. Nhưng điều này khiến người nhà của ông Kanin phẫn nộ và tìm cách hãm hại hai cậu cháu Thewan để cướp lấy tài sản thừa kế. Sau một lần gặp gỡ, Saraphi, cô gái xinh đẹp từng làm diễn viên đóng thế, đã được chọn làm vệ sĩ bảo vệ cho Ek và đồng hành cùng Thewan trong hành trình chống lại những kẻ xấu. Trong thời gian bên nhau, chính sự chân thành của Saraphi đã làm rung động trái tim lạnh giá của Thewan, và cả hai đã nảy sinh tình cảm với nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2022, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Vill Wannarot Sonthichai","avatar":""},{"name":"Ken Phupoom Phongpanu","avatar":""},{"name":"Petch Boranin","avatar":""},{"name":"Ann Siriam Pakdeedumrongrit","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324304);
