INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-cua-jinx', 'Người Tình Của Jinx', 'Jinxed At First', 'https://phimimg.com/upload/vod/20240409-1/98a3248739b3285945f09c5f6ea583bc.jpg', 'https://phimimg.com/upload/vod/20240409-1/22b94fa0783468920c7e50c04a7f0033.jpg', '<p>Bộ phim chuyển thể từ bộ truyện tranh cùng tên, kể về câu chuyện của một người đàn ông coi cuộc đời bất hạnh của mình là số phận của mình và quyết định thuận theo. Và một nữ thần đã rời khỏi thế giới vô danh để gỡ bỏ lời nguyền. Sau đó cả hai cùng nhau thoát khỏi số phận nghiệt ngã.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Na Jong Chan","avatar":""},{"name":"Seo Ju Hyun","avatar":""},{"name":"Kwang-leol Jeon","avatar":""},{"name":"Yin Zhi Hui","avatar":""},{"name":"Do-hun Ki","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324304);
