INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-khung-long-trai-ky-phan-trang-phan-5', 'Thế Giới Khủng Long: Trại Kỷ Phấn Trắng (Phần 5)', 'Jurassic World Camp Cretaceous (Season 5)', 'https://phimimg.com/upload/vod/20240409-1/f21f34c20bcb0bd702ec3343a23a7c3e.jpg', 'https://phimimg.com/upload/vod/20240409-1/7edd2b6c9ebe8b35a57c2ad4943493b3.jpg', '<p>Tình bạn. Tình yêu. Sự phản bội. Sinh tồn. Tương lai đang bị đe dọa khi nhóm bạn tuổi teen đối mặt với mùa cuối hoành tráng cùng các lựa chọn khó khăn và tiết lộ bất ngờ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul-Mikél Williams","avatar":""},{"name":"Jenna Ortega","avatar":""},{"name":"Sean Giambrone","avatar":""},{"name":"Kausar Mohammed","avatar":""},{"name":"Ryan Potter","avatar":""},{"name":"Raini Rodriguez","avatar":""},{"name":"Kirby Howell-Baptiste","avatar":""},{"name":"Haley Joel Osment","avatar":""},{"name":"Andrew Kishino","avatar":""},{"name":"Roger Craig Smith","avatar":""},{"name":"Stephanie Beatriz","avatar":""},{"name":"Angus Sampson","avatar":""},{"name":"Bradley Whitford","avatar":""},{"name":"Glen Powell","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324304);
