INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ancient-earth-dinosaurs-of-the-frozen-continent', 'Ancient Earth: Dinosaurs Of The Frozen Continent', 'Ancient Earth: Dinosaurs Of The Frozen Continent', 'https://phimimg.com/upload/vod/20240409-1/2eaaeb6f070d4afcc19eeebfd8ba20ea.jpg', 'https://phimimg.com/upload/vod/20240409-1/a074e6c0f6f2eb3b0088b1e9a7aaba2e.jpg', '<p>Sâu dưới lớp băng của Nam Cực là dấu vết của một thế giới đã mất của Khủng long và các sinh vật thời tiền sử. Những khu rừng lớn từng bao phủ lục địa Nam Cực giờ đã đóng băng; những con khủng long khổng lồ khổng lồ đi lang thang trong các thung lũng của nó, và những động vật có vú nguyên sinh lao qua những bụi cây. Đây cũng là nơi sinh sống của loài ăn thịt lớn nhất thời bấy giờ, Cryolophosaurus – T-Rex của Nam Cực.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324304);
