INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-cua-trung-sinh', 'Cánh Cửa Trùng Sinh', 'Be Reborn', 'https://phimimg.com/upload/vod/20240409-1/af49f0d73e6f2daa1c30b22e50b38a5d.jpg', 'https://phimimg.com/upload/vod/20240409-1/064c42eb90ca6043dd23547eaf065b18.jpg', '<p>La Kiên là một vị cảnh sát điều tra dày dạn kinh nghiệm, năng lực trinh sát rất mạnh. Trang Văn Kiệt một sinh viên Luật năm 3 thiên tài lạnh lùng, nhà có truyền thống trộm cắp, với truyền thống từ ông nội và cha, cậu có thể nắm rõ được những mánh khóe tinh vi trong kỹ thuật trộm.Một lần bức tranh “Hoa Súng” bị đánh cắp xảy ra trong trường học mà cảnh sát La Kiên và cậu sinh viên Trang Văn Kiệt gặp gỡ, hai con người với hai tính cách và hoàn cảnh sống khác biệt, từ vụ án “Hoa Súng” đến những vụ án kì lạ khác xảy ra, từ ngờ vực lẫn nhau đến tin tưởng kề vai chiến đấu, cuối cùng cả hai vẫn kiên định với ánh sáng công lý và truyền tải năng lượng tích cực cho bộ phim.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yi","avatar":""},{"name":"Karry Wang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324304);
