INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-sinh-an', 'Phù Sinh Ấn', 'Seal Of Love', 'https://phimimg.com/upload/vod/20240409-1/81de5d430cd27862b39175ba80370fbf.jpg', 'https://phimimg.com/upload/vod/20240409-1/b3e6e40b4d260f6ce29bdf1da42ca806.jpg', '<p>Kể về câu chuyện tình yêu kéo dài của Meng Fusheng với Jingyuan và Qingchen ở núi Fengming. Câu chuyện về sự thay đổi cuộc đời cuối cùng của Meng Fusheng nhờ làm việc chăm chỉ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Phi","avatar":""},{"name":"Minh Gia Gia","avatar":""},{"name":"Hoàng Hựu Thiên","avatar":""},{"name":"Tôn Lợi Á","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324304);
