INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phu-sinh-an', 'Phù Sinh Ấn', 'Seal Of Love', 'phù sinh ấn seal of love lý phi minh gia gia hoàng hựu thiên tôn lợi á ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anna', 'Anna', 'Anna', 'https://phimimg.com/upload/vod/20240408-1/39e3bec57e50ab6a22516fa05e3ce8b8.jpg', 'https://phimimg.com/upload/vod/20240408-1/5dd077022857d799052c56ff05f2782e.jpg', '<p>Phim là câu chuyện xoay quanh nhân vật Yoo Mi . Yoo Mi mắc hội chứng rối loạn nhân cách chống đối xã hội, là một bệnh nhân có thói quen nói dối và niềm tin vào thế giới hư cấu không có thật. Bắt đầu từ một lời nói dối nhỏ, cô đã nhập vai hoàn hảo vào một người khác và sống cuộc đời hoàn toàn khác.Hyun Joo là một người phụ nữ sống cuộc sống của mình, giữ mình trên tất cả mọi người, đối xử với họ không tử tế cũng không ác ý. Cô có một mối quan hệ căng thẳng với Yoo Mi. Ji Hoon là chồng của Yoo Mi, người có tham vọng và định hướng tương lai. Ji Won là một tiền bối đáng tin cậy, người duy nhất mà Yoo Mi tin tưởng.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 19, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Bae Suzy","avatar":""},{"name":"Jung Eun Chae","avatar":""},{"name":"Kim Joon Han","avatar":""},{"name":"Park Ye Young","avatar":""},{"name":"Kim Jung Young","avatar":""},{"name":"Kim Soo Jin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324304);
