INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lenh-cam-hon', 'Lệnh Cấm Hôn', 'The Forbidden Marriage', 'https://phimimg.com/upload/vod/20240408-1/f0023c2319bd91f964a53e7bb6aefe3c.jpg', 'https://phimimg.com/upload/vod/20240408-1/e9c2b9263a283059e5cac3d1fdcfc896.jpg', '<p>Dựa trên tiểu thuyết web cùng tên, “The Forbidden Marriage” sẽ có sự tham gia của Kim Young Dae trong vai Vua Yi Heon, người chìm sâu vào tuyệt vọng sau cái chết của vợ và cuối cùng bị cấm kết hôn ở vương quốc của mình. Bảy năm sau khi mất vợ (do Kim Min Ju của IZ*ONE thủ vai ), lúc đó là công chúa, anh tình cờ gặp một kẻ lừa đảo tên là So Rang ( Park Ju Hyun ), người tuyên bố rằng cô có thể bị chiếm hữu. linh hồn của công chúa quá cố.Kim Woo Seok sẽ tham gia bộ phim với vai Lee Shin Won, một sĩ quan Uigeumbu dường như có tất cả, từ ngoại hình, trí tuệ đến xuất thân. Vừa là thần dân vừa là bạn lâu năm của Vua Yi Heon, Lee Shin Won đáng tin cậy bảo vệ vị vua của mình bằng kỹ năng võ thuật xuất chúng và lòng trung thành đáng ngưỡng mộ của mình.Tuy nhiên, mặc dù bề ngoài Lee Shin Won dường như có mọi thứ dành cho anh ấy, nhưng anh ấy thực sự là một linh hồn cô đơn chịu đựng nỗi đau của chính mình. Bị dày vò bởi một tình yêu không được đáp lại, Lee Shin Won sẽ lay động trái tim người xem bằng câu chuyện đau buồn về sự tận tâm đơn phương của anh.&nbsp;</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Ju Hyun","avatar":""},{"name":"Kim Young Dae","avatar":""},{"name":"Kim Woo Seok","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324304);
