INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-an-do-an-mang-trong-phong-xu-an', 'Sát Nhân Ấn Độ: Án Mạng Trong Phòng Xử án', 'Indian Predator: Murder In A Courtroom', 'https://phimimg.com/upload/vod/20240408-1/774dbc958d9bb46b23ee386e584955d7.jpg', 'https://phimimg.com/upload/vod/20240408-1/98455a9bd7e084bf750ed6a1d3c50cef.jpg', '<p>Năm 2004, một kẻ săn mồi tàn bạo bị hành hình ngay trong phòng xử án. Đây là câu chuyện về cộng đồng mà hắn đã khủng bố và sự trả thù của họ.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Ấn Độ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324304);
