INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-me-doc-sach', 'Công Chúa Mê Đọc Sách', 'Princess Of The Bibliophile', 'https://phimimg.com/upload/vod/20240408-1/e6d4903606ec7822bdc5a1e60ffc1d8d.jpg', 'https://phimimg.com/upload/vod/20240408-1/48068a5a253ee1c21571b73eabaf7ee2.jpg', '<p>Miễn là cô có thể đọc, Eliana Bernstein - thường được biết đến với biệt danh Công chúa mê đọc sách - đã thích công ty của những cuốn sách hơn là của mọi người. Tuy nhiên, là một quý tộc, nhiệm vụ của cô là phải tìm một người cầu hôn. May mắn thay cho cô, Thái tử Christopher Selkirk Asherald đưa ra một thỏa thuận: Anh sẽ bảo vệ thời gian rảnh của cô, và đổi lại, Eliana sẽ chỉ là vị hôn thê của anh trên danh nghĩa. Những năm họ ở bên nhau thật hạnh phúc, khi Eliana học cách cởi mở với người khác. Nhưng tất cả những điều tốt đẹp đều phải kết thúc. Đối với Eliana, người yêu sách hơn người, việc kết thúc mối quan hệ giả tạo của họ hẳn không có gì to tát. Nhưng khi Christopher trở nên thân thiết với một cô gái khác, Eliana bắt đầu nhận ra rằng cô không thờ ơ với anh như cô từng nghĩ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324304);
