INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-toc-vinh-dieu', 'Gia Tộc Vinh Diệu', 'Modern Dynasty', 'https://phimimg.com/upload/vod/20240403-1/d1be6b23e88259fb4fa4d2f7333781b0.jpg', 'https://phimimg.com/upload/vod/20240403-1/8515787199e48f4dfc4e3a4c9c2fe3fa.jpg', '<p>Đám cưới thế kỷ giữa hai thiếu gia gia tộc họ Mã tài phiệt giàu có với hai chị em hoa hậu là Chân Tâm và Lạc Nghi được diễn ra cùng một ngày trong sự vui mừng của hai cô gái. Tuy nhiên, sau đám cưới hoành tráng xa hoa ấy, ba anh em nhà họ Mã gồm Diệu Tông, Diệu Tổ, Diệu Đường đã bị bắt để điều tra vì nghi ngờ hối lộ quan chức. Và Anh họ của cả ba là Mã Triển Hồng đột nhiên xuất hiện trở thành CEO tạm thời của tập đoàn. Sau đó là những cuộc tranh giành đấu đá giữa các cô gái và thành viên trong gia tộc diễn ra ngày một căng thẳng.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 2022, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Trương Trí Lâm","avatar":""},{"name":"Dương Thiến Nghiêu","avatar":""},{"name":"Lý Thể Hoa","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324304);
