INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-chinh-dien-sau-lam-moi-theo', 'Nữ Chính Diễn Sâu Lắm Mối Theo', 'Affairs Of Drama Queen', 'https://phimimg.com/upload/vod/20240403-1/7f7c8ae1b4638209bb674c6461492874.jpg', 'https://phimimg.com/upload/vod/20240403-1/7a72ff0e097ab55694a111676327676a.jpg', '<p>Nữ minh tinh không mấy nổi tiếng vô tình xuyên không vào kịch bản, trở thành nhân vật Tô Hướng Vãn trong kịch bản. Ở thế giới này, Tô Hướng Vãn vô cùng đào hoa. Để trở về thế giới thực, Tô Hướng Vãn buộc phải thay đổi cốt truyện, tạo ra cái kết viên mãn. Trong quá trình này, cô đã gặp Dự Vương Triệu Dung Hiển, cả hai từ gặp gỡ trở thành tình yêu...</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hứa Hiểu Nặc","avatar":""},{"name":"Hầu Lập","avatar":""},{"name":"Quyền Bái Luân","avatar":""},{"name":"Cam Vọng Tinh","avatar":""},{"name":"Vương Thuỵ Tuyết","avatar":""},{"name":"Lưu Nhuận Minh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324304);
