INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-doan-tu-phan-5', 'Gia Đình Đoàn Tụ (Phần 5)', 'Family Reunion (Season 5)', 'https://phimimg.com/upload/vod/20240403-1/467f471629b5239865f10cdff28526d2.jpg', 'https://phimimg.com/upload/vod/20240403-1/8c79e20c4e5f62326e10628837d38c32.jpg', '<p>Nhà McKellan lại có thêm người dưới nhiều hình thức khi những khó khăn bất ngờ thử thách nghị lực của họ. Nhưng dù thế nào, gia đình vẫn là trên hết.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Loretta Devine","avatar":""},{"name":"Tia Mowry","avatar":""},{"name":"Anthony Alabi","avatar":""},{"name":"Talia Jackson","avatar":""},{"name":"Cameron J. Wright","avatar":""},{"name":"Jordyn Raya James","avatar":""},{"name":"Isaiah Russell-Bailey","avatar":""},{"name":"Richard Roundtree","avatar":""},{"name":"Jasun Jabbar Wardlaw Jr.","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324305);
