INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-doan-tu-phan-5', 'Gia Đình Đoàn Tụ (Phần 5)', 'Family Reunion (Season 5)', 'gia đình đoàn tụ (phần 5) family reunion (season 5) loretta devine tia mowry anthony alabi talia jackson cameron j. wright jordyn raya james isaiah russell-bailey richard roundtree jasun jabbar wardlaw jr. ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-su-1000-won', 'Luật Sư 1000 Won', 'One Dollar Lawyer', 'https://phimimg.com/upload/vod/20240403-1/dc1af2b746deafbd4ae1604606c2a8b5.jpg', 'https://phimimg.com/upload/vod/20240403-1/132bfe5c3adcb1aa9479159b288eeb32.jpg', '<p>Cheon Ji Hun là một luật sư có phong cách khác thường. Tóc của anh ấy được uốn kiểu cách. Anh ta chỉ tính phí 1.000 won (khoảng 1 USD) cho dịch vụ của mình, nhưng anh ta là một trong những luật sư lành nghề nhất. Anh ta luôn chiến đấu chống lại những luật sư đắt giá khác và những khách hàng giàu có của họ, những người cố gắng trốn tránh việc vi phạm pháp luật.Baek Ma Ri làm trợ lý công tố sau khi tốt nghiệp Học viện Đào tạo và Nghiên cứu Tư pháp. Cô ấy tự tin và có lòng tự trọng cao. Ông nội của cô là Baek Hyun Mu, người đã thành lập Công ty luật Baek nổi tiếng và làm việc tại công ty luật của ông với tư cách là một luật sư. Cuộc sống của Baek Ma Ri diễn ra suôn sẻ, nhưng cuộc đời cô thay đổi sau khi cô gặp Cheon Ji Hun.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 19, 2022, 'VietSub', 'HD', 'Hàn Quốc', 0, '[{"name":"Nam Goong Min","avatar":""},{"name":"Kim Ji Eun","avatar":""},{"name":"Choi Dae Hoon","avatar":""},{"name":"Lee Duk Hwa","avatar":""},{"name":"Park Jin Woo","avatar":""},{"name":"Ha Sung Kwang","avatar":""},{"name":"Kim Ja Young","avatar":""},{"name":"Kim Cheol Yoon","avatar":""},{"name":"Jo Yeon Hee","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324305);
