INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-truoc-mat-phan-sau-lung', 'Yêu Trước Mặt, Phản Sau Lưng', 'P.S. I Hate You', 'https://phimimg.com/upload/vod/20240403-1/8ddf35aa56b569078c6ad5eb2426ddc9.jpg', 'https://phimimg.com/upload/vod/20240403-1/36bb91bcf686fea73cc0888c13b312a0.jpg', '<p>Vào ngày cưới của Prae, một đoạn phim riêng tư của cô bị lộ ra ngoài. Quá tủi nhục, Prae đã quyết định tự kết liễu cuộc đời mình. Hóa ra, thủ phạm tung đoạn phim đó lại là một trong những người bạn thân của cô. Khi Meena, bạn thân nhất của Prae, quyết định điều tra kẻ chủ mưu, những sự thật không ngờ dần dần hé hộ, những yêu hận tình thù luôn hiện hữu trong mối quan hệ có tên gọi “tình bạn”.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 7, 2022, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Pearwah Nichaphat Chatchaipholrat","avatar":""},{"name":"Jan Ployshompoo Supasap","avatar":""},{"name":"Pat Chayanit Chansangavej","avatar":""},{"name":"Fah Yongwaree Anilbol","avatar":""},{"name":"Aye Sarunchana Apisamaimongkol","avatar":""},{"name":"Lee Thanat Lowkhunsombat","avatar":""},{"name":"Papang Phromphiriya Thongputtaruk","avatar":""},{"name":"Nat Nattaraht Maurice Legrand","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
