INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ve-nha-2022', 'Trở Về Nhà', 'Homesick', 'https://phimimg.com/upload/vod/20240403-1/69bf33b65ec08bb36bbc235375c9fa19.jpg', 'https://phimimg.com/upload/vod/20240403-1/e104782ffa9191b99a5d12689500e162.jpg', '<p>Vào mùa thu năm 1997, để tìm người chị em Tiểu Tú bị mất tích, Trần Hữu Hi đã trốn khỏi trại trẻ mồ côi và đến huyện Đàm Lĩnh một mình. Trước khi mất tích, Tiểu Tú làm bảo mẫu cho nhà họ Lý, sau khi cô mất tích, nhà họ Lý cho rằng cô ăn cắp và bỏ trốn. Hữu Hi tin chắc rằng Tiểu Tú không ăn trộm, và gia đình họ Lý đang che dấu điều gì đó. Hữu Hi phát hiện ra rằng Lý Văn Văn con gái của gia đình họ Lý đã mất nhiều năm trước, bằng tuổi cô, vì vậy cô đã giả vờ là Lý Văn Văn quay trở lại. Trong thời gian ở nhà họ Lý, Hữu Hi được bao bọc bởi sự ấm áp của gia đình, cô dần buông bỏ những nghi ngờ nhưng lại phát hiện ra rằng đằng sau \sự ấm áp\ đó là sự dối trá, âm mưu, tội ác và cái chết. Các thành viên trong gia đình còn phức tạp hơn cô tưởng tượng, Hữu Hi đã bước vào vòng nguy hiểm...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wendy Zhang","avatar":""},{"name":"Wang Yan Hui","avatar":""},{"name":"Mei Ting","avatar":""},{"name":"Lý Nãi Văn","avatar":""},{"name":"Wang Yan Hui","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
