INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-dau-phai-dep', 'Sàn Đấu Phái Đẹp', 'The Beauty Of War', 'https://phimimg.com/upload/vod/20240403-1/fb11852042fe84b67a86f8052c3ff328.jpg', 'https://phimimg.com/upload/vod/20240403-1/57dcb6b769809391d0823b5e71857bfc.jpg', '<p>Sở hữu dàn diễn viên đầy triển vọng, “Sàn đấu phái đẹp” vẽ nên một cuộc chiến vô hình, được che đậy bởi vẻ ngoài diễm lệ, hứa hẹn mang đến nhiều cung bậc cảm xúc cho người xem.&nbsp;Ba cô bạn Chung Gia Bảo (do Trần Oánh đóng), Lâm Tiểu Mỹ (do Trần Hiểu Hoa đóng) và Lý Tịnh Nghi (do Lưu Bội Nguyệt đóng) chơi thân với nhau từ thuở còn cắp sách. Trong đó, Bảo có nhan sắc nổi trội hơn cả, dễ làm xao xuyến lòng người. Một lần, Mỹ âm thầm đăng ký cho Bảo tham gia cuộc thi hoa khôi tạp chí. Nhờ vậy, Bảo không những đoạt giải nhất, mà còn lọt vào mắt xanh của chàng giám đốc trẻ Vương Nhất Ngôn (do Trần Sơn Thông đóng).&nbsp;Ngôn mời Bảo vào công ty của mình làm việc, ra sức nâng đỡ, ủng hộ cô tham gia cuộc thi hoa khôi Hồng Kông. Em gái của Bảo, là Chung Gia Kỳ (do Tưởng Gia Mân đóng), cũng tham gia cuộc thi này. Kỳ là con riêng của mẹ kế. Vì đố kỵ, cô không từ thủ đoạn, hãm hại Bảo.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 11, 2022, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Trần Oánh","avatar":""},{"name":"Tưởng Gia Mân","avatar":""},{"name":"Phương Lực Thân","avatar":""},{"name":"Lưu Bội Nguyệt","avatar":""},{"name":"Trần Hiểu Hoa","avatar":""},{"name":"Trần Sơn Thông","avatar":""},{"name":"Chu Thần Lệ","avatar":""},{"name":"Đinh Tử Lãng","avatar":""},{"name":"Khương Đại Vệ","avatar":""},{"name":"Trương Trì Hào","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
