INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-man-ro', 'Kẻ Man Rợ', 'Barbarian', 'https://phimimg.com/upload/vod/20230925-1/dfe8e8868d31a6a3eb7f34f17dae505a.jpg', 'https://phimimg.com/upload/vod/20230925-1/a8b177ad636ea3af6b7f38ca486f7aad.jpg', '<p>Câu chuyện về một cô gái trẻ đến Detroit để phỏng vấn xin việc, nhưng khi cô ấy đến nơi vào buổi tối muộn thì phát hiện ra căn hộ mình thuê đã có một người đàn ông khác thuê ở đó. Vì đã tối muộn và mưa to gió lớn, cô quyết định ở lại nhưng lại phát hiện ra còn nhiều điều đáng sợ hơn cả một vị khách không ngờ trong căn nhà này</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Georgina Campbell","avatar":""},{"name":"Bill Skarsgård","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Matthew Patrick Davis","avatar":""},{"name":"Richard Brake","avatar":""},{"name":"Kurt Braunohler","avatar":""},{"name":"Jaymes Butler","avatar":""},{"name":"Sophie Sörensen","avatar":""},{"name":"Rachel Fowler","avatar":""},{"name":"J.R. Esposito","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
