INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-man-ro', 'Kẻ Man Rợ', 'Barbarian', 'kẻ man rợ barbarian georgina campbell bill skarsgård justin long matthew patrick davis richard brake kurt braunohler jaymes butler sophie sörensen rachel fowler j.r. esposito ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-ke-doc-tinh', 'Thâm Kế Độc Tình', 'Pid Ruk Roy Adeed', 'https://phimimg.com/upload/vod/20240326-1/778d84a48ee212e6922682b7a85a22e9.jpg', 'https://phimimg.com/upload/vod/20240326-1/8b0ecced4d5870118c664ddd885d39b5.jpg', '<p>Phing là một cô gái bình thường và thừa cân. Cô ấy sống nội tâm nhưng cô ấy có một trái tim nhân hậu bởi vì người ông của cô ấy đã nuôi dạy cô ấy luôn khuyến khích cô ấy giúp đỡ người khác. Mặt khác, Han, học trò của ông nội, luôn nghĩ về bản thân. Phing thiếu các kỹ năng xã hội nên Fei có cơ hội đến gần và kết hôn với cô ấy vì lợi ích nhưng đây lại là sự khởi đầu cho thảm họa của cuộc đời cô. Cô ấy đang phải đối mặt với một bà mẹ chồng kinh khủng và người chồng của cô ấy đang lừa dối cô ấy với công nhân của cô ấy. Cuối cùng, cô biết sự thật nhưng những người này cố gắng đầu độc và chôn sống cô và ông nội cô. May mắn thay, Korn, người mà ông cô đã giúp đỡ từ lâu, có thể cứu cô và ông của cô. Sau khi sống sót, Phing đã biến thành May, một phụ nữ quyến rũ với trái tim đầy giận dữ.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 14, 2022, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Bee Namthip","avatar":""},{"name":"Marie Broenner","avatar":""},{"name":"Bright Norraphat","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
