INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-xem-phim-chuyen-tinh-da-qua', 'Vé Xem Phim Chuyện Tình Đã Qua', '10 Years Ticket', 'https://phimimg.com/upload/vod/20240326-1/739fec283324b71db9717186e38ddee7.jpg', 'https://phimimg.com/upload/vod/20240326-1/bce834ef291f7ee9b2c12aa49645fcfa.jpg', '<p>Nang Rak Rueang Thi Laeo nói về Pukao và Kongkwan là bạn thời ấu thơ và gia đình của họ cũng rất thân thiết với nhau. Nhưng mọi thứ đột ngột biến thành địa ngục vào cái ngày chị gái của Kongkwan sát hại anh trai của Pukao. Sự kiện thảm khốc này đã đặt dấu chấm hết cho tình bạn của cả hai. Từ đây, Pukao không ngừng trả thù Kongkwan, bất chấp sự thật rằng cô vô tội.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2022, 'Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Tu Tontawan Tantivejakul","avatar":""},{"name":"Ohm Pawat Chittsawangdee","avatar":""},{"name":"Off Jumpol Adulkittiporn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324305);
