INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vach-tran-fifa-bong-da-tien-bac-quyen-luc', 'Vạch Trần FIFA: Bóng đá, Tiền Bạc, Quyền Lực', 'FIFA Uncovered', 'https://phimimg.com/upload/vod/20240326-1/33869b9ff2138403a858dc58ce80f4e7.jpg', 'https://phimimg.com/upload/vod/20240326-1/8d0faee6d5fd136c503c279f63f7012a.jpg', '<p>Từ cuộc chiến giành quyền lực đến chính trị quốc tế, loạt phim tìm hiểu FIFA hé lộ quá khứ biến động của tổ chức này cũng như công tác chuẩn bị đăng cai World Cup.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324305);
