INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vach-tran-fifa-bong-da-tien-bac-quyen-luc', 'Vạch Trần FIFA: Bóng đá, Tiền Bạc, Quyền Lực', 'FIFA Uncovered', 'vạch trần fifa: bóng đá, tiền bạc, quyền lực fifa uncovered  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-giap-ri-set-binh-minh', 'Bộ Giáp Rỉ Sét -Bình Minh-', 'Sabiiro No Armor -Reimei-, Rusted Armors, Sabiiro No Armor, Rusted Armors -Dawn-', 'https://phimimg.com/upload/vod/20240326-1/7d2af2ae55ce4101d7f955487da8d224.jpg', 'https://phimimg.com/upload/vod/20240326-1/9f1e8121523887dc26784e1e23b23a2c.jpg', '<p>Một nhóm ưu tú được gọi là Owl phục vụ hoàng đế của Nhật Bản. Với một mục đích nhất định trong đầu, họ bí mật tìm kiếm mười bảo vật thiêng liêng nằm rải rác khắp đất nước. Đôi khi chúng thậm chí còn được gọi là sát thủ, do sức tàn phá khủng khiếp của chúng. Anh em nhà Tachibana, được nhiều người biết đến là những chiến binh mạnh nhất trong Owl, hiện đang tiến về khu bảo tồn ở Kumano. Trong khi đó, ở tỉnh Kii, nơi đã thoát khỏi cuộc chiến với Hideyoshi, nhóm lính đánh thuê Saika Ikki đang cố gắng chuyển đến một ngôi làng nằm sâu trong núi của Miền Kishu. Fujishiro, lãnh đạo của tỉnh Kii, cũng đang hướng đến thánh địa ở Kumano, cùng với ba người sử dụng áo giáp - Tsurukubi, Kokuhyo và Ageha. Anh ta định yêu cầu thần làng của họ được chào đón vào đền thờ Kumano Shrine. Các sinh vật ở thế giới khác cũng đang tiến về khu bảo tồn, để mắt đến những kho báu thiêng liêng. Trong chốc lát, tiếng nước vang lên. Khu bảo tồn lựa chọn những người thực hiện điều ước với các vị thần và yêu cầu họ phải trải qua một cuộc thử thách thanh tẩy. Giữa tất cả những điều này, một cuộc hội ngộ bất ngờ diễn ra. Một lần nữa, những chiếc áo giáp rỉ sét đang di chuyển, và con cú trên bầu trời xanh đang dang rộng đôi cánh của mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
