INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giam-doc-thuong-moi-toi-an-toi', 'Giám Đốc Thường Mời Tôi Ăn Tối', 'The Director Who Buys Me Dinner', 'https://phimimg.com/upload/vod/20240326-1/4e211b5894137cc5169337bdc9e542e5.jpg', 'https://phimimg.com/upload/vod/20240326-1/9fc44239de5eccd3577f4683df0f1f6b.jpg', '<p>Bộ phim xoay quanh việc Min Yoo Dam bị cuốn vào vòng luân hồi vì phạm phải tội đặt tên Seol Dong Baek cho một đứa trẻ vô danh. Còn Dong Baek thì mất đi ký ức về tiền kiếp, và cứ mỗi kiếp lại được sinh ra trong một hình hài khác. Trải qua mấy trăm năm, đến kiếp luân hồi thứ tư, vốn chưa biết có phải là kiếp luân hồi cuối cùng hay không, Yoo Dam lại gặp được Dong Baek, nhưng người lần này Yoo Dam gặp không phải một cô gái mà lại là chàng trai Dong Baek chừng 25 tuổi. Và chỉ có một cách duy nhất giúp Yoo Dam giải được lời nguyền, đó chính là phải yêu Dong Baek bằng cả con tim.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Jeong Woo","avatar":""},{"name":"Young woon Park","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
