INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vat-chat-toi-cua-ngai-phan-3', 'Vật Chất Tối Của Ngài (Phần 3)', 'His Dark Materials (Season 3)', 'https://phimimg.com/upload/vod/20240326-1/4e32a6651b76401509dbd9a930a91daf.jpg', 'https://phimimg.com/upload/vod/20240326-1/d4a76acaeff363c2a45a23e42c307830.jpg', '<p>Lyra là một đứa trẻ mồ côi sống trong một vũ trụ song song, trong đó khoa học, thần học và ma thuật đan xen với nhau. Cuộc tìm kiếm người bạn bị bắt cóc của cô đã phát hiện ra một âm mưu thâm độc liên quan đến những đứa trẻ bị bắt cóc, và biến thành nhiệm vụ tìm hiểu một hiện tượng bí ẩn tên là Bụi. Sau đó, cô được tham gia vào cuộc hành trình của mình bởi Will, một cậu bé sở hữu con dao có thể cắt cửa sổ giữa các thế giới. Khi biết được sự thật về cha mẹ mình và số phận đã được tiên tri của mình, hai người trẻ tuổi bị cuốn vào cuộc chiến chống lại các thế lực thiên thể trải dài trên nhiều thế giới.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dafne Keen","avatar":""},{"name":"Amir Wilson","avatar":""},{"name":"Ruth Wilson","avatar":""},{"name":"Ariyon Bakare","avatar":""},{"name":"Ruta Gedmintas","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324305);
