INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-den-vi-linh-hon', 'Tôi Đến Vì Linh Hồn', 'Dear Doctor, I''m Coming For Soul', 'https://phimimg.com/upload/vod/20240326-1/c578587ee800f79731bf2a3a1971aad0.jpg', 'https://phimimg.com/upload/vod/20240326-1/4780e65e39aa961753612d81106b9457.jpg', '<p>Prakan Pitakjiti là một trong những bác sĩ Khoa Ngoại tuyệt vời nhất tại bệnh viện. Anh ta có một thiên phú đặc biệt là có thể nhìn thấy thần chết. Prakan gọi thần chết là Tua-Phee (vé quỷ), vì anh ta luôn xuất hiện trong phòng phẫu thuật với tấm vé màu trắng, điều đó có nghĩa là bệnh nhân của Prakan sẽ chết. Tua-Phee trở thành người mà Prakan không muốn gặp vì sự hiện diện của anh ta đồng nghĩa với việc Prakan không thể cứu được bệnh nhân. Tuy nhiên, tín ngưỡng đã đưa họ đến với nhau, vì sự thật chứng minh Tua-Phee sống ở bên cạnh Prakan.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Nut Nutchapol Rattanamongkol","avatar":""},{"name":"Karn Kasidej Hongladaromp","avatar":""},{"name":"Pat Chatborirak","avatar":""},{"name":"Tae Weerapat Toemmaneerat","avatar":""},{"name":"Soodyacht Patsit Permpoonsavat","avatar":""},{"name":"Singto Namchok","avatar":""},{"name":"Cook Pavadee Komchokpaisan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
