INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-ban-gai-dong-bac-cua-toi', 'Xin Chào, Bạn Gái Đông Bắc Của Tôi', 'Hello My Girl', 'https://phimimg.com/upload/vod/20240326-1/ae7bc0b8136caf6ebba69097c90ef729.jpg', 'https://phimimg.com/upload/vod/20240326-1/ded585be36986507e64cd2fadc625d4a.jpg', '<p>Bking Dương Nhất Sam người sinh ra lớn lên ở Thượng Hải, để theo đuổi tự do và thoát khỏi sự kiểm soát của dì mình, đã nộp đơn vào bốn trường đại học ở các thành phố thuộc bốn phía Đông Tây Nam Bắc của đất nước và cuối cùng anh đã rời xa Thượng Hải đến mảnh đất xa xôi Đông Bắc. Bởi vì thói quen sinh hoạt khác biệt, khó có thể thích ứng với cuộc sống ở Đông Bắc. Tại đây cô anh quen với Triệu Đa Đa cô gái lớn ở vùng Đông Bắc. Người dì lo lắng cho Nhất Sam nên cũng dọn đến Thẩm Dương để tiện chăm sóc cậu ấy. Cha của Đa Đa trở thành chủ nhà của cô. Nhất Sam muốn trốn tránh dì của mình, nên nộp đơn đi du học, và không dám nói cho dì biết. Đa Đa muốn mai muốn cha với dì của Nhất Sam nên đã yêu cầu Nhất Sam cùng hợp tác giúp đỡ cô mai mối . Cuối cùng người dì cô đơn nhiều năm cũng đã rung động trước người cha chân thành của Đa Đa. Hai người trẻ tuổi từ kẻ thù dần dần cũng trở thành một đôi...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 22, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ngao Tử Dật","avatar":""},{"name":"Huang Can Can","avatar":""},{"name":"Hong Jian Tao","avatar":""},{"name":"Danni Liang","avatar":""},{"name":"Cai Xin Yang","avatar":""},{"name":"Lin Jun Yi","avatar":""},{"name":"Zhao Yi Ji","avatar":""},{"name":"Shi Rui","avatar":""},{"name":"Kyle","avatar":""},{"name":"David Chen","avatar":""},{"name":"Chen Mu Yang","avatar":""},{"name":"Trần Nhất Long","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324305);
