INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uu-tu-phan-5', 'Ưu Tú (Phần 5)', 'Elite (Season 5)', 'https://phimimg.com/upload/vod/20240326-1/7d1efa535b5553db40ad3b52889453a1.jpg', 'https://phimimg.com/upload/vod/20240326-1/10f88ba4bf7ca2bbd303c51f25c3c77e.jpg', '<p>Khi 3 thiếu niên thuộc tầng lớp lao động chuyển tới một trường tư thục thượng lưu Tây Ban Nha, mâu thuẫn giữa họ và các học sinh nhà giàu dẫn tới một vụ án mạng.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Itzan Escamilla","avatar":""},{"name":"Miguel Bernardeau","avatar":""},{"name":"Danna Paola","avatar":""},{"name":"Arón Piper","avatar":""},{"name":"Omar Ayuso","avatar":""},{"name":"Álvaro Rico","avatar":""},{"name":"Mina El Hammani","avatar":""},{"name":"Ester Expósito","avatar":""},{"name":"Jorge López","avatar":""},{"name":"Claudia Salas","avatar":""},{"name":"María Pedraza","avatar":""},{"name":"Georgina Amorós","avatar":""},{"name":"Miguel Herrán","avatar":""},{"name":"Jaime Lorente","avatar":""},{"name":"Leïti Sène","avatar":""},{"name":"Sergio Momo","avatar":""},{"name":"Carla","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
