INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('uu-tu-phan-5', 'Ưu Tú (Phần 5)', 'Elite (Season 5)', 'ưu tú (phần 5) elite (season 5) itzan escamilla miguel bernardeau danna paola arón piper omar ayuso álvaro rico mina el hammani ester expósito jorge lópez claudia salas maría pedraza georgina amorós miguel herrán jaime lorente leïti sène sergio momo carla ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-ra-la-em', 'Hoá Ra Là Em', 'So It''s You', 'https://phimimg.com/upload/vod/20240326-1/12418f31d77168a8c0b4dc13d0cd2d36.jpg', 'https://phimimg.com/upload/vod/20240326-1/90c3fd989acc57f5effc36cbc22abd94.jpg', '<p>Cuộc gặp gỡ giữa ngôi sao judo đang lên Yuan Lai và thiên tài bơi lội đang sa sút Jiang Gunan không giống như một câu chuyện tình lãng mạn trong cổ tích, mà giống như tia lửa điện giáng xuống trái đất, và con đường của kẻ thù đã bắt đầu mất kiểm soát kể từ đó. Jiang Gunan tình cờ phát hiện ra rằng Yuan Lai thực sự là thần hộ mệnh của anh ấy khi còn nhỏ, và anh ấy rất mong được gặp Yuan Lai trong niềm vui. Dần dần thân thiết với nhau, giữa anh và cô gái có vẻ vô tư lự này đã xảy ra một phản ứng hóa học tuyệt vời. Được sự khuyến khích của Yuan Lai, Jiang Gunan đã xem xét lại tình yêu của mình đối với môn bơi lội và cuối cùng đã thành công trong việc vượt qua bóng đen tâm lý của mình; Thành tựu, cuối cùng trở thành một bản thân tốt hơn.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Huyền Duệ","avatar":""},{"name":"Luo Yutong","avatar":""},{"name":"Lưu Khải","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
