INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-ra-la-em', 'Hoá Ra Là Em', 'So It''s You', 'hoá ra là em so it''s you trương huyền duệ luo yutong lưu khải ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-du-an-than-yeu-cua-toi', 'Liễu Dư An Thân Yêu Của Tôi', 'My Dearest Boss', 'https://phimimg.com/upload/vod/20240326-1/0e9175dcd869d25e3157454cbdf2e8df.jpg', 'https://phimimg.com/upload/vod/20240326-1/6cc813fa4ed5e1b3cb05d2c32ada9958.jpg', '<p>Dụ Tinh Thùy, người thừa kế ngôi nhà bạc tỷ, vô tình trở thành hàng xóm với ông chủ Liễu Dư An của mình, thế là cô bắt đầu cuộc chiến với bất tận tại nơi làm việc và nơi ở với Liễu Dư An. Trong quá trình đó, cặp đôi oan gia này đã thầm yêu nhau. Lúc này, người mẹ mất tích nhiều năm của Liễu Dư An, bà Dương Tự đã tìm đến cửa. Bà chính là người sắp xếp cho Dụ Tinh Thùy sống ở ngôi nhà này. Bà nói với Dụ Tinh Thùy rằng cha cô đã nhảy lầu tự tử từ tòa nhà cao do Liễu Dư An quản lý khiến Liễu Dư An ám ảnh rất lớn. Biết được sự thật, Dụ Tinh Thùy hiểu được nỗi lòng của Dương Tự nên đã giúp Liễu Dư An thoát khỏi ám ảnh. Cuối cùng hai người đã đến với nhau.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
