INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-can-meow-phai-anh', 'Bất Cẩn Meow Phải Anh', 'Accidentally Meow On You', 'https://phimimg.com/upload/vod/20240326-1/b42f2f2eefee913fc394c77177910b91.jpg', 'https://phimimg.com/upload/vod/20240326-1/7359f587fc8855b42f929df001cfc3ca.jpg', '<p>Châu Thiên, một kiện tướng thể thao đã chó ngáp phải ruồi vào công ty văn hoá làm việc. Ngày đầu tiên đi làm, cô đã gặp Kỷ Thần, anh chàng tổng giám đốc mặt lạnh, hai người xem nhau như khắc tinh nơi làm việc. Luôn đối đầu gay gắt trong đời thực là vậy nhưng dưới sự mai mối của thú cưng Bóng Tròn, hai người đã kết bạn Wechat, trở thành hai con sen chưa từng gặp mặt nhưng trò chuyện vui vẻ, cùng nhau nuôi mèo. Cứ như vậy, hai người bắt đầu hành trình vừa yêu vừa ghét, đời thực tranh cãi, trên mạng thả thính...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hồ Băng Khanh","avatar":""},{"name":"Hình Chiêu Lâm","avatar":""},{"name":"Lý Quân Duệ","avatar":""},{"name":"Hồ Gia Hân","avatar":""},{"name":"Vương Hạo Ca","avatar":""},{"name":"Vương Gia Trữ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
