INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ridley-jones-phan-3', 'Ridley Jones (Phần 3)', 'Ridley Jones (Season 3)', 'https://phimimg.com/upload/vod/20240326-1/5565a95d357332fb9d5263508afc8743.jpg', 'https://phimimg.com/upload/vod/20240326-1/e817663805813d6d92806dc184e2735a.jpg', '<p>Ridley và nhóm bận rộn với các cuộc phiêu lưu ngoài vũ trụ, tìm kho báu và hội bạn mới trong khi bảo vệ bảo tàng trước những rắc rối ma thuật – và ông Peabody.</p>', 'Hoàn Tất (4/4)', 4, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Iara Nemirovsky","avatar":""},{"name":"Laraine Newman","avatar":""},{"name":"David Errigo Jr.","avatar":""},{"name":"Tyler Shamy","avatar":""},{"name":"Ezra Menas","avatar":""},{"name":"Ashlyn Madden","avatar":""},{"name":"Sutton Foster","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324305);
