INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-nhon-voi-chi', 'Đừng Nhờn Với Chị', 'Destined To Meet You', 'https://phimimg.com/upload/vod/20240326-1/f5723553543e525d5479780bac174358.jpg', 'https://phimimg.com/upload/vod/20240326-1/dabab5e44515e5fe97bf304cb84f305a.jpg', '<p>Jin Rong Rong, tổng giám đốc kiên quyết của tập đoàn Jinchao, đã gặp Gu Cong Bei, một ca sĩ của một quán bar, trên đường bí mật kiểm tra hoạt động của khu kinh doanh.<br/>Sau một đêm say xỉn Jin Rong Rong biết rằng Gu Cong Bei vẫn còn là một sinh viên đại học, và kinh nghiệm tình yêu bằng không, cô giả vờ bình tĩnh và tuyên bố phải chịu trách nhiệm với anh ta. Thật trùng hợp khi Jin Rong Rong đến văn phòng hẹn hò, cô bất ngờ phát hiện ra rằng Gu Cong Bei là con trai thứ ba của gia đình họ Gu, và cũng có nhu cầu kết hôn, vì vậy cô quyết định chọn anh làm đối tượng kết hôn của mình. Điều mà cô không biết là Gu Cong Bei đang cố tình đến gần cô.<br/>Giờ đây, về chung sống dưới một mái nhà sau khi kết hôn, Gu Cong Bei nhận thấy Jin Rong Rong khác biệt, độc nhất nhưng Jin Rong Rong cũng rất kín tiếng và không chịu công khai với chồng mới về lý do cô sợ lạnh. Khi sự thật và động cơ bắt đầu xuất hiện, liệu hai người này có thể vượt qua những thử thách đang xảy ra?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lục Nghiên Kỳ","avatar":""},{"name":"Dương Trạch","avatar":""},{"name":"Nghê Hàn Tẫn","avatar":""},{"name":"Quách Gia Ngữ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
