INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-mat-den-ay', 'Đôi Mắt Đen Ấy', 'Yeh Kaali Kaali Ankhein', 'https://phimimg.com/upload/vod/20240326-1/b20160477b932094cc0a6b7b7663aaeb.jpg', 'https://phimimg.com/upload/vod/20240326-1/d614f037738153fc0b22bb5b341e0646.jpg', '<p>Bị con gái của chính trị gia quyền lực đeo đuổi và làm mọi cách biến anh thành của cô, người đàn ông nọ rơi vào con đường đen tối và rủi ro để giành lại đời mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Tahir Raj Bhasin","avatar":""},{"name":"Shweta Tripathi Sharma","avatar":""},{"name":"Anchal Singh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
