INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-hien-dai', 'Tình Yêu Hiện Đại', 'Modern Love Tokyo', 'https://phimimg.com/upload/vod/20240326-1/9821ff51c946ae86ed47eb67df7ed7c8.jpg', 'https://phimimg.com/upload/vod/20240326-1/f9706bf1f7c59985053f1038d0cd8045.jpg', '<p>Sê-ri Amazon Original “Tình yêu hiện đại”, dựa trên một chuyên mục xuất hiện trên Thời báo New York, đã được phát hành từ năm 2019. Giờ đây, “Tình yêu hiện đại” khởi động lại với giao diện mới ở Tokyo với tên gọi “Tình yêu hiện đại Tokyo”. Tuyển tập bảy tập có sự tham gia của các diễn viên chính và mô tả nhiều dạng “tình yêu” khác nhau, chẳng hạn như tình yêu gần như bị lãng quên, tình yêu giữa con trai và mẹ, và tình yêu vượt qua biên giới.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mizukawa Asami","avatar":""},{"name":"Ikematsu Sosuke","avatar":""},{"name":"Nagasaku Hiromi","avatar":""},{"name":"Yusuke Santamaria","avatar":""},{"name":"Naomi Scott","avatar":""},{"name":"Maeda Atsuko","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
