INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-quan-xin-tu-trong', 'Phu Quân Xin Tự Trọng', 'Bossy Husband Who Loved Me', 'https://phimimg.com/upload/vod/20240326-1/e51252f6ffda85ac7f66bd727abd3691.jpg', 'https://phimimg.com/upload/vod/20240326-1/758e0da3107f2e3ead4078e0499bfc41.jpg', '<p>Nhà văn Mộc Tiểu Tịch vô tình lạc vào cuốn tiểu thuyết của cô và hoàn thành mười nhiệm vụ trước khi trở về. Cô nghĩ rằng đó là một điều chắc chắn, nhưng cô không biết rằng Tần Chuẩn, nam nhân vật chính, có khả năng nghe thấy những mong muốn chân thành của Mộc Tiểu Tịch. Khi nam chính cũng có thể đoán trước được tình tiết, hướng đi của câu chuyện đã trải qua những biến động kinh thiên động địa, và số phận của hai người gắn bó chặt chẽ với nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Dương Trạch","avatar":""},{"name":"Đồ Chỉ Oánh","avatar":""},{"name":"Hứa Quốc Đống","avatar":""},{"name":"Phán Lý Đồng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324305);
