INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-bai-noi-dau-song-phan-1', 'Thành Bại Nơi Đầu Sóng (Phần 1)', 'Make Or Break (Season 1)', 'https://phimimg.com/upload/vod/20240326-1/5ae7f07e4a3cbc74baa9e02547427b4f.jpg', 'https://phimimg.com/upload/vod/20240326-1/88f3101ddb5a40387bbc503afe4f6252.jpg', '<p>Hòa mình vào thế giới lướt sóng chuyên nghiệp với tư cách là người giỏi nhất trong môn thể thao này đi khắp thế giới để tranh chức vô địch Thế giới. Với khả năng tiếp cận chưa từng có, loạt phim tài liệu này ghi lại cuộc sống của các vận động viên trong chuyến lưu diễn và những hy sinh mà họ thực hiện để đạt đến đỉnh cao.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324305);
