INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-chuyen-bi-hai', 'Vua Chuyện Bi Hài', 'Last One Standing', 'https://phimimg.com/upload/vod/20240326-1/55d11352b86af8f21db9459b23d39e6d.jpg', 'https://phimimg.com/upload/vod/20240326-1/1f6ae3425ec0f36833d17a7493d4bacc.jpg', '<p>Họ là các cây hài đóng chính trong một bộ phim giật gân, nhưng nếu không gây cười trong những cảnh ngoài kịch bản, họ sẽ bị loại. Hãy để sự hỗn loạn bắt đầu!</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Daigo","avatar":""},{"name":"Nobu","avatar":""},{"name":"Hitori Gekidan","avatar":""},{"name":"Iio Kazuki","avatar":""},{"name":"Kobayashi Kendo","avatar":""},{"name":"Tsukaji Muga","avatar":""},{"name":"Itakura Toshiyuki","avatar":""},{"name":"Tanaka Takushi","avatar":""},{"name":"Yoshimura Takashi","avatar":""},{"name":"Tonikaku Akarui Yasumura","avatar":""},{"name":"Kano Eiko","avatar":""},{"name":"Komiya Hironobu","avatar":""},{"name":"Minegishi Minami","avatar":""},{"name":"Iwai Yuki","avatar":""},{"name":"Mukai Satoshi","avatar":""},{"name":"Morita Tetsuya","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
