INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huan-luyen-vien-truong', 'Huấn Luyện Viên Trưởng', 'Coach Prime', 'https://phimimg.com/upload/vod/20240326-1/18bdf1a5b21ade2ce611423c56141d0a.jpg', 'https://phimimg.com/upload/vod/20240326-1/db61269f7b2961d80b407e05141fc97e.jpg', '<p>Theo dõi đội bóng Những chú hổ của Đại học bang Jackson năm 2022 khi luyện tập và trong các trận đấu, trong phòng thay đồ, ngoài sân cỏ và trong cộng đồng, trong suốt mùa giải Giải vô địch SWAC bất bại 12-0 của họ.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 15, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '[]', 1784690324305);
