INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-ma-lai', 'Lời Nguyền Ma Lai', 'Music And Krasue', 'https://phimimg.com/upload/vod/20240326-1/2af237f12d601b7257404f3e7153a072.jpg', 'https://phimimg.com/upload/vod/20240326-1/14fcb89300860af19857804b36aa1b28.jpg', '<p>Nina, ca sĩ trẻ của công ty Charasrak, thường xuyên gặp ác mộng, thấy mình biến thành Ma Lai. Kan là du học sinh và là con trai của người đứng đầu Charasrak. Kan hiểu lầm Nina là bồ nhí của bố nên luôn đối đầu với cô. Bỗng một ngày Nina thức dậy trong đêm và biến thành Ma Lai, cô sợ hãi và tìm cách chạy trốn. Vô tình biết được bí mật của Nina, Kan đã giúp cô tìm hiểu bí mật của bản thân cũng như nguyên nhân của kẻ thừa kế dòng máu Ma Lai.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 7, 2022, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Cheer Thikumporn Rittapinun","avatar":""},{"name":"Indy Intad Leowrakwong","avatar":""},{"name":"Kannaporn Puangtong","avatar":""},{"name":"Sun Prachakorn Piyasakulkaew","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324305);
