INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-life-and-movies-of-eran-kuneri', 'The Life And Movies Of Erşan Kuneri', 'The Life And Movies Of Erşan Kuneri', 'https://phimimg.com/upload/vod/20240326-1/fcc61941edfe26f021828d8d2fb553ba.jpg', 'https://phimimg.com/upload/vod/20240326-1/3bada42cbeff9a08dcc8edae285cf718.jpg', '<p>Nhìn lại di sản của mình, một nhân vật lẫy lừng trong giới điện ảnh khêu gợi quyết định đi theo hướng mới và làm phim thể loại khác, từ viễn tưởng đến hành động trung cổ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 17, 2022, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Cem Yılmaz","avatar":""},{"name":"Zafer Algöz","avatar":""},{"name":"Ezgi Mola","avatar":""},{"name":"Çağlar Çorumlu","avatar":""},{"name":"Uraz Kaygılaroğlu","avatar":""},{"name":"Nilperi Şahinkaya","avatar":""},{"name":"Merve Dizdar","avatar":""},{"name":"Bülent Şakrak","avatar":""},{"name":"Can Yılmaz","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324305);
