INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ong-jack-phan-2', 'Quý Ông Jack (Phần 2)', 'Gentleman Jack (Season 2)', 'https://phimimg.com/upload/vod/20240326-1/0578d1d91c8f1af23e8c3fc06ee016b3.jpg', 'https://phimimg.com/upload/vod/20240326-1/6338e1b4075c67cc55136bd12a8029fe.jpg', '<p>Yorkshire, 1834. Mọi con mắt đều đổ dồn vào Anne Lister và Ann Walker khi họ cùng nhau xây dựng tổ ấm tại Shibden Hall với tư cách là vợ và chồng, quyết tâm kết hợp tài sản của họ và trở thành một cặp vợ chồng quyền lực. Tinh thần kinh doanh của Anne Lister khiến người dân địa phương khiếp sợ nhiều như cô ấy Cuộc sống yêu đương khác thường và, với Halifax trên bờ vực của cuộc cách mạng, việc từ chối giữ một lý lịch thấp của cô ấy trở nên khiêu khích và nguy hiểm.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Suranne Jones","avatar":""},{"name":"Sophie Rundle","avatar":""},{"name":"Rosie Cavaliero","avatar":""},{"name":"Albane Courtois","avatar":""},{"name":"Gemma Whelan","avatar":""},{"name":"Gemma Jones","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
