INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-quoc-troi-day-ottoman-phan-2', 'Đế Quốc Trỗi Dậy: Ottoman (Phần 2)', 'Rise Of Empires: Ottoman (Season 2)', 'https://phimimg.com/upload/vod/20240324-1/af510c0fcf8c16cb94baae87233a85a2.jpg', 'https://phimimg.com/upload/vod/20240324-1/13a1c9a47d680d32e99de570320485b4.jpg', '<p>Nhiều năm sau khi chinh phục Constantinople, Sultan Mehmed II củng cố quyền lực, nhưng một kẻ cai trị tàn nhẫn ở Wallachia đe dọa lật đổ đế chế của anh.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 16, 2022, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Charles Dance","avatar":""},{"name":"Cem Yiğit Üzümoğlu","avatar":""},{"name":"Daniel Nuță","avatar":""},{"name":"Ali Gözüşirin","avatar":""},{"name":"Nik Xhelilaj","avatar":""},{"name":"Radu Andrei Micu","avatar":""},{"name":"Tuba Büyüküstün","avatar":""},{"name":"Tommaso Basili","avatar":""},{"name":"Selim Bayraktar","avatar":""},{"name":"Birkan Sokullu","avatar":""},{"name":"Osman Sonant","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
