INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-muon-tro-thanh-chua-te-bong-toi-phan-1', 'Ta Muốn Trở Thành Chúa Tể Bóng Tối (Phần 1)', 'The Eminence in Shadow (Season 1)', 'https://phimimg.com/upload/vod/20240411-1/73042ae1095405a7eff6040faa7817c4.jpg', 'https://phimimg.com/upload/vod/20240411-1/e70d5523ecefb9368918e49374144692.jpg', '<p>&quot;Tôi không phải nhân vật chính, cũng chẳng phải trùm cuối...&quot; Tôi là một cậu trai ước mơ làm &quot;chúa tể bóng tối&quot;, chèo lái câu chuyện trong bóng tối, bí mật phô bày năng lực, tên là Shido. Vừa mới hớn hở vì được chuyển sinh đến thế giới khác và quyết định &quot;mình sẽ là chúa tể bóng đêm, ngấm ngầm loại bỏ giáo phái đen tối&quot;, thì hình như cái giáo phái ấy lại có thật...?? Thuận theo đó, các thiếu nữ thủ hạ của hắn cũng vì hiểu lầm mà tôn thờ hắn dưới danh nghĩa Shadow, bản thân Shido đã chẳng hề hay biết mà trở thành &quot;Chúa tể bóng tối&quot; đích thực, và thế là tổ chức bóng tối &quot;Shadow Garden&quot; do Shido lãnh đạo sẽ đi hủy diệt hắc ám của thế gian...</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Seiichiro Yamashita","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Suzuko Mimori","avatar":""},{"name":"Fairouz Ai","avatar":""},{"name":"Hisako Kanemoto","avatar":""},{"name":"Reina Kondo","avatar":""},{"name":"Rina Hidaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324305);
