INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-la-quen-thuoc-2022', 'Người Lạ Quen Thuộc', 'A Familiar Stranger', 'https://phimimg.com/upload/vod/20240324-1/9e841bb8d046b464fd8890adc7fa90f0.jpg', 'https://phimimg.com/upload/vod/20240324-1/d33c9b44c9a836fce2d211efccb72b2f.jpg', '<p>Chàng họa sĩ có tình yêu trong sáng đã thay đổi diện mạo kết hôn, đoàn tụ với tình cũ, cô con gái mưu mô từ bỏ sĩ diện tìm kiếm tình yêu đích thực của mình. Quân vương cùng quần thần tranh đoạt, thành bại trăm bề, hai chị em khôn cùng đối mặt, mặt giả, tình thật.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kha Ying","avatar":""},{"name":"Cheng Lei","avatar":""},{"name":"Wang Zexuan","avatar":""},{"name":"Song Zhaoyi","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324305);
