INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('baymax-phan-1', 'Baymax (Phần 1)', 'Baymax! (Season 1)', 'https://phimimg.com/upload/vod/20240324-1/6fbca5dd65980627d8591d02a2cc4a93.jpg', 'https://phimimg.com/upload/vod/20240324-1/8b55efa5f37945b78f28dbf798ea09e2.jpg', '<p>Loạt phim hoạt hình thứ hai của Big Hero 6 có dạng Baymax !, một loạt phim nhẹ nhàng, vui nhộn gồm sáu đoạn phim ngắn được thiết kế để tạo sự thoải mái và thích thú. Khoảng chín phút mỗi chuyến, cho hay mất, những cuộc phiêu lưu ngắn này có bác sĩ-bot bơm hơi đáng yêu Baymax tuần tra khu phố San Fransokyo nhộn nhịp để tìm kiếm những người cần hỗ trợ về y tế - và tinh thần -. Đó là nội dung nhẹ nhàng, bổ ích cho những ai đang tìm kiếm một bản tóm tắt ngắn gọn.Baymax với tư cách là một nhân vật, là một chiến thắng trên nhiều cấp độ. Giống như Kẻ hủy diệt ngược, nó không ngừng trong sứ mệnh giúp đỡ người khác và phần lớn sự hài hước ở đây đến dưới dạng chúng ta miễn cưỡng, về cơ bản, đi kiểm tra. Sự bướng bỉnh của chính chúng ta, với tư cách là con người, để rèn luyện khả năng tự chăm sóc bản thân hoặc thậm chí là nỗi sợ hãi khi phải đối mặt với một chẩn đoán xung đột với chương trình của Baymax để trở nên tử tế và hợp lý. Vì vậy, không có gì ngạc nhiên khi một vài chương trong số này liên quan đến một kịch bản rượt đuổi, trong đó bệnh nhân của tập phim thực sự cố gắng trốn tránh sự chăm sóc kiên quyết, ngoan cố của Baymax.</p>', 'Hoàn Tất (6/6)', 6, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Maya Rudolph","avatar":""},{"name":"Scott Adsit","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324305);
