INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('control-z-bi-mat-giau-kin-phan-3', 'Control Z: Bí Mật Giấu Kín (Phần 3)', 'Control Z (Season 3)', 'https://phimimg.com/upload/vod/20240324-1/25bbf8df256db2aec083a48f72f20e52.jpg', 'https://phimimg.com/upload/vod/20240324-1/9ff02468aea5d1174c0cb3ad7a82cdae.jpg', '<p>Sofia và bạn bè cố gắng bước tiếp trong năm cuối cấp, nhưng một hacker không rõ danh tính với tài khoản quen thuộc lại khiến cuộc sống của họ trở nên khó khăn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 16, 2022, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Ana Valeria Becerril","avatar":""},{"name":"Michael Ronda","avatar":""},{"name":"Yankel Stevan","avatar":""},{"name":"Luis Curiel","avatar":""},{"name":"Samantha Acuña","avatar":""},{"name":"Macarena García","avatar":""},{"name":"Fiona Palomo","avatar":""},{"name":"Andrés Baida","avatar":""},{"name":"Patricio Gallardo","avatar":""},{"name":"Iván Aragón","avatar":""},{"name":"Xabiani Ponce de León","avatar":""},{"name":"Patricia Maqueo","avatar":""},{"name":"Rodrigo Cachero","avatar":""},{"name":"Rocío Verdejo","avatar":""},{"name":"Zion Moreno","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
