INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('control-z-bi-mat-giau-kin-phan-3', 'Control Z: Bí Mật Giấu Kín (Phần 3)', 'Control Z (Season 3)', 'control z: bí mật giấu kín (phần 3) control z (season 3) ana valeria becerril michael ronda yankel stevan luis curiel samantha acuña macarena garcía fiona palomo andrés baida patricio gallardo iván aragón xabiani ponce de león patricia maqueo rodrigo cachero rocío verdejo zion moreno ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-thanh-nu-chinh-co-gai-nha-que-va-cong-viec-bi-mat', 'Trở Thành Nữ Chính! Cô Gái Nhà Quê Và Công Việc Bí Mật', 'Heroine Tarumono!, Heroines Run The Show', 'https://phimimg.com/upload/vod/20240324-1/b6f09d8f7e86dc31adc82a5b06b2950b.jpg', 'https://phimimg.com/upload/vod/20240324-1/f98210f1f71a5ad85b490d6f95d33f9e.jpg', '<p>Hiyori Suzumi là một cô gái nhà quê, đi lên thành phố và vào trung học Sakuragaoka tại Tokyo để theo đuổi giấc mơ điền kinh. Trong lúc tìm kiếm việc làm thêm, cô đã trở thành quản lý tập sự của hai người bạn cùng lớp là Yujiro Someya và Aizo Shibasaki - Hai thành viên của nhóm nhạc thần tượng LIPxLIP. Câu chuyện kể về những khó khăn và cách mà Hiyori vượt qua trong việc học hành ở trường, tham gia sinh hoạt CLB và cả công việc hỗ trợ hai người bạn là Idol của mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 17, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324305);
