INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-tac-nhan-gian', 'Ba Tấc Nhân Gian', 'A World Worth Protecting', 'https://phimimg.com/upload/vod/20240324-1/4f2e87a0edc8549868ecc95ce3c2eb1f.jpg', 'https://phimimg.com/upload/vod/20240324-1/dbdf28b9d1092928b99da95b7c2f1359.jpg', '<p>Ở thế giới dị giới tương lai với linh lực dồi dào, chàng trai mập nhiệt tình vui vẻ Vương Bảo Lạc đã nhìn thấu được ảo cảnh do các thầy cô giáo tạo ra trong kỳ thi nhập học của Phiêu Diểu Đạo Viện, dùng biểu hiện xuất sắc giành được điểm cao, giành được suất học đặc biệt của khoa Pháp binh, từ đây vượt qua đủ mọi chướng ngại và mở ra con đường thăng cấp của mình. Trong quá trình tu tiên và đánh quái, cậu đã kết thân được với một nhóm bạn tốt, đồng thời bắt đầu một chuỗi các câu chuyện phiêu lưu mạo hiểm đầy vui nhộn.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324305);
