INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiem-ca-phe-my-nam', 'Tiệm Cà Phê Mỹ Nam', 'Café Minamdang', 'https://phimimg.com/upload/vod/20240324-1/831933460a537aff3387d6cbc16361cc.jpg', 'https://phimimg.com/upload/vod/20240324-1/d307a0355b6aa25138f9a951bac8d4fc.jpg', '<p>Seo In-guk hóa thân thành Nam Han Jun, một pháp sư tà giáo, nguyên là cựu hồ sơ viên, thể hiện một nhân vật có tính cách mạnh mẽ với mái tóc bồng bềnh, gu thời trang sành điệu cùng sự quyến rũ sắc sảo. Oh Yeon-seo trong vai Han Jae Hee, một thám tử thuộc đội điều tra tội phạm bạo lực với khả năng điều tra thần tốc và nhạy bén. Kwon Soo Hyun trong vai Cha Do Won, một công tố viên không bao giờ bỏ sót bất cứ điều gì dự kiến sẽ chiếm được trái tim khán giả.Seo In Guk, Oh Yeon Seo và Kwon Soo Hyun sẽ mang đến một sự kết hợp vô cùng thú vị, đan xen giữa sự lãng mạn và đối địch. Mời các bạn đón xem câu chuyện của những người tạo nên tiếng cười, sự hào hứng và cả những màn trình diễn hồi hộp gay cấn ”.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Seo In Guk","avatar":""},{"name":"Oh Yeon Seo","avatar":""},{"name":"Kwon Soo Hyun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
