INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-bi-mat-cua-nguoi-vo', 'Thế Giới Bí Mật Của Người Vợ', 'The Wife''s Secret World', 'https://phimimg.com/upload/vod/20240324-1/828bb0f7dbf7a081b62392093672aa9e.jpg', 'https://phimimg.com/upload/vod/20240324-1/fb16594b76114c06cb2275f879b35273.jpg', '<p>Cô ấy là nội trợ của gia đình, hy sinh sáu năm thanh xuân vì người mình yêu, sinh cho anh ta đứa con gái nhưng mãi không chờ được tờ giấy hôn thú từ anh. Mẹ chồng bạo lực lạnh, bạn trai như đang ngoại tình, mọi thứ đều khiến cô bắt đầu bùng nổ tuyệt vọng đối với căn nhà lạnh lẽo này. Nhưng một trận tai nạn xe thần bí, một lần mất trí nhớ ly kỳ, từng cơn ác mộng ập đến hằng đêm, tất cả khiến cuộc sống của cô ngày càng hỗn loạn, đẩy cô vào vực sâu không đấy. Một ti sáng len lói từ đêm tối, đó chính là sự ấm áp đến từ anh ấy, anh chữa lành vết thương cho cô, đưa cô vào thế giới mới. Đến khi tưởng chừng cuộc sống đã đi vào quỹ đạo, thì bỗng một sự thật khiến cô khó lòng chấp nhận đã xuất hiện...</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lâm Tử Lâm","avatar":""},{"name":"Hoàng Đào","avatar":""},{"name":"Thừa Lỗi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
