INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huan-luyen-vien-tinh-than-je-gal-gil', 'Huấn Luyện Viên Tinh Thần Je Gal Gil', 'Mental Coach Jegal', 'https://phimimg.com/upload/vod/20240324-1/c287ee93a670138d257e91740453346f.jpg', 'https://phimimg.com/upload/vod/20240324-1/a4946cf3fced863a43b2eb9577afb9d4.jpg', '<p>Bộ truyện kể về một vận động viên Taekwondo bị cấm thi đấu vĩnh viễn trong đội tuyển quốc gia và trở thành một huấn luyện viên tinh thần để giúp những người chơi sa sút phong độ, chữa lành các vận động viên đã nghỉ hưu và chiến đấu một trận đấu thực sự chống lại thế giới vô lý của kẻ thắng người thua.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 16, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Woo","avatar":""},{"name":"Lee Yoo Mi","avatar":""},{"name":"Kwon Yool","avatar":""},{"name":"Park Se Young","avatar":""},{"name":"Yoon Joo Sang","avatar":""},{"name":"Moon Sung Geun","avatar":""},{"name":"Gil Hae Yeon","avatar":""}]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '[]', 1784690324305);
