INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-la-mu-quang-nhat-ban', 'Yêu Là Mù Quáng: Nhật Bản', 'Love Is Blind: Japan', 'https://phimimg.com/upload/vod/20240324-1/52b0ea1438e7b7a0bcfe1a6cff625ce1.jpg', 'https://phimimg.com/upload/vod/20240324-1/ab3d2aec4aaf1e9c45f3228cfbe5e8d2.jpg', '<p>Trong loạt chương trình hẹn hò thực tế này, những người Nhật độc thân muốn kết hôn sẽ gặp gỡ, hẹn hò và đính hôn – tất cả trước khi nhìn thấy mặt nhau.</p>', 'Full', 11, 'tvshows', 'completed', 13, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Fujii Takashi","avatar":""},{"name":"Itaya Yuka","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
