INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-chua-may-man-cua-ta-quan-chua-van-phuc', 'Quận Chúa May Mắn Của Ta (Quận Chúa Vạn Phúc)', 'My Lucky Princess (Jun Zhu Wan Fu)', 'https://phimimg.com/upload/vod/20240324-1/9384ed0f706ffe370766ac0dfc1b951b.jpg', 'https://phimimg.com/upload/vod/20240324-1/fef64058027d19e74f2ff4cea97bf65a.jpg', '<p>Các vị hoàng đế tiền nhiệm không thoát khỏi cảnh chết trẻ vì bệnh tật, nhưng hoàng tộc có một bí mật không muốn ai biết. Đại hoàng tử Tiêu Hoa giả vờ nhu nhược cùng Nhị hoàng tử vì không muốn được phong làm Thái tử. Nhưng tình thế này bị quận chúa phá đám đến gả, nàng quyết tâm phò tá Tiêu Hoa lên làm thái tử.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vu Hiên Thần","avatar":""},{"name":"Lý Áo","avatar":""},{"name":"Lý Tử Y","avatar":""},{"name":"Vương Tinh Vĩ","avatar":""},{"name":"Phi Nhĩ Đa Tư","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324305);
