INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quan-chua-may-man-cua-ta-quan-chua-van-phuc', 'Quận Chúa May Mắn Của Ta (Quận Chúa Vạn Phúc)', 'My Lucky Princess (Jun Zhu Wan Fu)', 'quận chúa may mắn của ta (quận chúa vạn phúc) my lucky princess (jun zhu wan fu) vu hiên thần lý áo lý tử y vương tinh vĩ phi nhĩ đa tư ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-to-tinh-anh', 'Công Tố Tinh Anh', 'Prosecution Elite', 'https://phimimg.com/upload/vod/20240324-1/8dece751fc8e13a5338ac01b5c7e70f3.jpg', 'https://phimimg.com/upload/vod/20240324-1/efdb2b12e9b7cc21785984d103ed8c6b.jpg', '<p>An Ni, một công tố viên của Viện kiểm sát Giang Thành, được Trưởng công tố Xu An Lâm giao nhiệm vụ điều tra vụ án một sinh viên đại học mất tích nhảy xuống hồ. Cô bắt đầu với Zhao Jikai, Tổng giám đốc của Huiquan Games, và tìm thấy mối liên hệ giữa anh ta với các tổ chức ở nước ngoài thúc đẩy bắt nạt, dẫn đến việc bắt giữ những kẻ phạm tội. Trong khi giá cổ phiếu của Huiquan Games giảm mạnh, Yin Huiquan quyên góp cho Học viện Jiangxiao, từ đó sẽ làm hư hỏng trẻ vị thành niên dưới chiêu bài từ thiện.Sinh viên Li Xiaowen và các nạn nhân khác tiến lên, công khai tố cáo các phương tiện không chính thống của Học viện Jiangxiao để kiểm soát thanh niên. An Ni trình bày bằng chứng chắc chắn trước tòa, dẫn đến việc đóng cửa học viện và trừng phạt những người có liên quan.Yan Qin, người đã tiếp quản Huiquan Games, đã biển thủ quỹ để đầu tư vào việc phát triển một mỏ đồng. Tuy nhiên, liên doanh đầu tư này là một kế hoạch Ponzi của một băng nhóm lừa đảo tài chính trực tuyến. Có đầy đủ bằng chứng, An Ni ra nước ngoài tham gia phiên tòa xuyên biên giới. Với sự hợp tác của các tổ chức tư pháp Trung Quốc và nước ngoài, Qian Tianxin được đưa về Trung Quốc và tài sản của anh ta bị đóng băng.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 9, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Địch Lệ Nhiệt Ba","avatar":""},{"name":"Đồng Đại Vỹ","avatar":""},{"name":"Cao Hâm","avatar":""},{"name":"Hàn Đống","avatar":""},{"name":"Trương Khả Doanh","avatar":""},{"name":"Vưu Tĩnh Như","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
