INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-van-lan-cuu-anh', 'Một Vạn Lần Cứu Anh', 'Love In A Loop', 'https://phimimg.com/upload/vod/20240324-1/58e694c70fb27a2de5f929de0494232e.jpg', 'https://phimimg.com/upload/vod/20240324-1/e93f47057060a8d3db645dec0a58f56b.jpg', '<p>Ông chủ độc địa tự luyến Bạch Chân Tương liên tục chết vì sự oán hận của nhân viên. Mỗi lần anh ta chết, thời gian đều được lặp lại vào cùng một ngày, điều này khiến nhân viên của anh là Lí Lộ Đa bị mắc kẹt trong một vòng thời gian lặp lại. Để thoát ra khỏi vòng lặp thời gian, Lộ Đa phải tiếp xúc nhiều với sếp khiến cô phát điên, cô cố gắng làm thay đổi sếp, giải cứu anh ấy cho đến tận khi đã phải lòng anh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"White. K","avatar":""},{"name":"Zhang Ya Qin","avatar":""},{"name":"Alvin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324305);
