INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-duyen-dai-nhan-xin-dung-buoc', 'Nhân Duyên Đại Nhân Xin Dừng Bước', 'Ms. Cupid In Love', 'https://phimimg.com/upload/vod/20240324-1/23a2839713bdd970fc21ccc72c7e9285.jpg', 'https://phimimg.com/upload/vod/20240324-1/11fb15c9a2abc4ffa700e34cf526d63e.jpg', '<p>Nhân Duyên Đại Nhân Xin Dừng Bước kể về Bách Diễn vốn là vị thần quản sự sống chết của chúng sinh do vô tình làm loạn nhân duyên trong nhân gian nên bị đày hạ phàm lịch kiếp, đụng trúng bà chủ Quan Nhã của một tiệm quán dưới nhân gian, rồi lại thành vị hôn phu Sở Diệp của Quan Nhã. Một người vốn đã nhìn quen sống chết cũng lạnh nhạt với chuyện tình cảm nhi nữ dần bị Quan Nhã thu hút, hai người cùng nhau nắm sợi tơ hồng, bắt đầu một mối nhân duyên giữa người và tiên.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 14, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tào Dục Thần","avatar":""},{"name":"Điền Hi Vi","avatar":""},{"name":"Tiêu Vũ Lương","avatar":""},{"name":"Kim Ưu Mỹ","avatar":""},{"name":"Cảnh Nghiêm Tuấn","avatar":""},{"name":"Từ Chẩn Chẩn","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324305);
