INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-an-bi-van-luc', 'Trường An Bí Văn Lục', 'Mysterious Tales Of Chang''an', 'https://phimimg.com/upload/vod/20240324-1/1c893ce01077866a198e70f3aebdf78f.jpg', 'https://phimimg.com/upload/vod/20240324-1/5c00d21ffd8c080fc459775e1e6bc3e7.jpg', '<p>Vào thời Đường, trong lúc cải trang xuất cung, Hoàng thái tử Lý Tinh Hà đã tình cờ gặp gỡ nữ ngỗ tác Trương Tiểu Manh và tư trực Sở Thất. Sau khi ba người hợp sức phá giải kì án trùng độc Sinh Tử thì bị cuốn vào vụ án sát nhân y phục đỏ. Trong quá trình phá án lại dây vào vụ án mật thất hồ ly giết người đã bị lãng quên từ lâu, ba người sẽ ở lại Trường An và phá án thế nào đây?</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sách Á Tín","avatar":""},{"name":"Trương Đan Dương","avatar":""},{"name":"Bạch Thần Hi","avatar":""},{"name":"Hoàng Huyên Huyên","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324305);
