INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mang-luoi-gia-tao-cai-chet-doi-tra-va-internet', 'Mạng Lưới Giả Tạo: Cái Chết, Dối Trá Và Internet', 'Web Of Make Believe: Death, Lies And The Internet', 'https://phimimg.com/upload/vod/20240324-1/078862db4695bbbe5f3e8f2f89ce8d10.jpg', 'https://phimimg.com/upload/vod/20240324-1/62e46babbd15dae7f0f23b902a8f3754.jpg', '<p>Âm mưu. Lừa đảo. Bạo lực. Án mạng. Những gì bắt đầu trên mạng ảo lại có thể trở thành thật quá nhanh – và khi mạng phủ sóng trên toàn thế giới, hậu quả cũng vậy.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324305);
