INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('check-out-series-dem-do-cung-cau-sao-bac-dau', 'Check Out Series (Đêm Đó Cùng Cậu Sao Bắc Đẩu)', 'Check Out Series Uncut Version', 'https://phimimg.com/upload/vod/20240324-1/0804988bed01396ae713cb375c97d7a2.jpg', 'https://phimimg.com/upload/vod/20240324-1/59ec06003ec8425e8d45a34b5361f9a2.jpg', '<p>Check Out Series - Đêm Đó Cùng Cậu Sao Bắc Đẩu là bộ phim xoay quanh câu chuyện của Dao Nuea và Nai. Dao Nuea (do Chahub Marut Ghoummeddin thủ vai), vừa chia tay mối tình đầu của mình, trong thời gian đi nghỉ tại TheAir Khao Yai đã gặp Nai (do Best Vittawin Veeravidhayanant thủ vai), chàng trai đã giúp tâm trạng của anh ấy trở nên tốt hơn mặc dù tất cả chỉ là trong một cuộc gặp ngắn ngủi. Sau khi Dao Nuea trở về, Nai biến mất trong ba tháng. Anh ấy đã cố gắng quên đi tất cả về Nai bằng cách quay trở lại cuộc sống cũ, làm việc với Tee, người đồng sở hữu và là mối tình đầu của Dao Nuea. Tuy nhiên, Tee lại muốn có cơ hội thứ hai để nối lại mối quan hệ xưa. Mọi thứ trở nên biến động khi công ty không có thu nhập vào thời điểm đó. Nai đồng ý giúp Tee với tư cách là bạn học cũ. Dao Nuea biết rằng anh ấy muốn đến bên Nai, nhưng khá miễn cưỡng vì Nai lại có một cô bạn gái sắp ra đi. Vượt qua mọi khó khăn trở ngại, Dao Nuea và Nai đã giải quyết vấn đề của riêng mình và đến với nhau. Xem Check Out Series - Đêm Đó Cùng Cậu Sao Bắc Đẩu Vietsub sớm nhất trên iQiyi và iQ.com. Lịch chiếu phim Check Out và Review phim Check Out sẽ sớm được cập nhật.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Chahub Marut Ghoummeddin","avatar":""},{"name":"Best Vittawin Veeravidhayanant","avatar":""},{"name":"Mew Sirilapas Kongtragan","avatar":""},{"name":"M Sarawut Laoruamsap","avatar":""},{"name":"Beam Atichart Lawansathean","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
