INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-my-vi-cua-anh', 'Em Là Mỹ Vị Của Anh', 'Healing Food, Healing Love', 'https://phimimg.com/upload/vod/20240324-1/a2c5dd0392fd033365ddc6589703d370.jpg', 'https://phimimg.com/upload/vod/20240324-1/5e036161806eb254c5ad2dbb2fc85e65.jpg', '<p>Bộ phim kể về câu chuyện của Thân Anh, một biên tập viên ẩm thực và Trịnh Đạo một chuyên gia ẩm thực. Hai người vì ẩm thực mà quen nhau, thông qua công việc mà hiểu hơn nhau , cùng nhau trưởng thành và cùng nhau chữa lành vết thương lòng.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Hách","avatar":""},{"name":"Triệu Nghiêu Kha","avatar":""},{"name":"Triệu Phẩm Lâm","avatar":""},{"name":"Nghê Ngôn","avatar":""},{"name":"Lợi Tinh Thiên","avatar":""},{"name":"Văn Sinh","avatar":""},{"name":"Châu Tử Kiệt","avatar":""},{"name":"Tôn Vi Mộc","avatar":""},{"name":"Triệu Thiên Qua","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
