INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cua-lai-vo-cu', 'Cua Lại Vợ Cũ', 'Ex-Wife Stop', 'https://phimimg.com/upload/vod/20240324-1/43a55cf043bf2c87a7a3bd1f1e30c88f.jpg', 'https://phimimg.com/upload/vod/20240324-1/4c226c32cbeee40e833c645c65f3d7f1.jpg', '<p>Chủ tịch lạnh lùng Thịnh Nam Phương bị ép phải cưới cô gái bình thường Tô Thiều Nhan, lại vì biết bao hiểu lầm mà làm tổn thương trái tim cô ấy, ly hôn xong mới biết mình đã đánh mất tình yêu đích thực. Để cua lại vợ cũ, Thịnh Nam Phương biến thành một ông chồng “cá con” đội vợ lên đầu, cuối cùng cũng khiến vợ cảm động, thành công ôm được người đẹp về nhà.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bai Haoyan","avatar":""},{"name":"Feng Yiran","avatar":""},{"name":"Pupu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
