INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-tong-thu', 'Thiên Tòng Thú', 'The Indomitable', 'https://phimimg.com/upload/vod/20240324-1/484e6afae811a4997ff91bf4ca39b651.jpg', 'https://phimimg.com/upload/vod/20240324-1/b36f19e0961be42a09861f373b9e7807.jpg', '<p>Thiên Tòng, một thiếu niên đến từ nước Hoa, là một yêu tinh bị phong ấn nên không thể sử dụng khả năng diễn thuyết của mình. Nhưng dù là vậy, cậu vẫn nuôi ước mơ trở thành một diễn thuyết gia mạnh nhất. Chính vì vậy, cậu đã đến Học Thành xin học, bắt đầu cuộc sống bất diệt của mình.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324305);
