INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-lan-nga-ngua-phan-1', 'Kỳ Lân Ngã Ngựa (Phần 1)', 'WeCrashed (Season 1)', 'https://phimimg.com/upload/vod/20240324-1/3d813c331b0d507de11ca855970b29e5.jpg', 'https://phimimg.com/upload/vod/20240324-1/d09eb5d700965a72106bb8fe300badc2.jpg', '<p>Lấy cảm hứng từ các sự kiện thực tế - và câu chuyện tình yêu là trung tâm của tất cả. WeWork đã phát triển từ một không gian làm việc chung đơn lẻ thành một thương hiệu toàn cầu trị giá 47 tỷ USD trong vòng chưa đầy một thập kỷ. Sau đó, trong vòng chưa đầy một năm, giá trị của nó đã giảm 40 tỷ đô la. Chuyện gì đã xảy ra thế?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jared Leto","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Kyle Marvin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
