INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-bai-vanguard-willdress', 'Đấu Bài!! Vanguard: Will+Dress', 'Cardfight!! Vanguard: Will+Dress', 'https://phimimg.com/upload/vod/20240324-1/ef51ec817c3121442df36e8fd95d2ce7.jpg', 'https://phimimg.com/upload/vod/20240324-1/a6f45ca2eb4748967d71ef7e86e2663f.jpg', '<p>4 tháng sau trận đấu ở lâu đài Nagoya, Yu-yu và bạn bè nhận một được lời mời tham dự một giải đấu khác. Mục đích của giải đấu Deluxe ấy là xác định người đấu bài mạnh nhất, tập hợp các Đấu Sĩ Tiền Phương , những người đang thể hiện tài năng ở các giải đấu chính thức và các tổ chức bí ẩn Đấu Sĩ Phản Nghịch như Blackout, và để họ thi đấu với nhau vì những lá cờ. Các nhân vật ở phần overDress sẽ thi đấu với các nhân vật mới ở phần này như Raika, Michiru và Urara để trở thành người mạnh nhất. Tương lai đang ở đây!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324305);
