INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-hai-lam-tuoi-hai-mot', 'Tuổi Hai Lăm, Tuổi Hai Mốt', 'Twenty Five Twenty One', 'https://phimimg.com/upload/vod/20240324-1/07ac1e85759b17ba066f3115b82f5637.jpg', 'https://phimimg.com/upload/vod/20240324-1/e8dffe4760d2e46949b05840f9a0b9b2.jpg', '<p>Tại thời điểm mà những ước mơ dường như xa tầm với, một kiếm sĩ tuổi teen theo đuổi những hoài bão lớn và gặp một chàng trai chăm chỉ đang tìm cách làm lại cuộc đời.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Tae Ri","avatar":""},{"name":"Nam Joo Hyuk","avatar":""},{"name":"Kim Ji Yeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
