INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-mong-cua-co-nang-duong-xi', 'Ảo Mộng Của Cô Nàng Dương Xỉ', 'Star-Crossed Lovers', 'https://phimimg.com/upload/vod/20240324-1/a4853c358962fb5471508c48f8715075.jpg', 'https://phimimg.com/upload/vod/20240324-1/3dc0cd7fdb041bb28a2988ca7ab72318.jpg', '<p>Phim kể về Điền Quyết (Hà Lam Đậu)- một tác giả vẽ truyện tranh tự do, một ngày nọ cô phát hiện bản thân có thần giao cách cảm với chàng trai đến từ ngoài hành tinh chỉ vì một nụ hôn. Chàng trai đó lại chính là An Bạch Dạ (Ngưu Tử Phiên) - nam chính trong truyện tranh của cô vẽ. Điền Quyết mang trên mình viên đá mà An Bạch Dạ đang tìm kiếm nhiều năm qua, Bạch Dạ muốn lấy đi viên đá đó để cứu hành tinh của mình nhưng nếu lấy nó đi đồng nghĩa với việc Điền Quyết sẽ chết. Trong quá trình cùng tìm cách giải quyết vấn đề, hai người đã nảy sinh tình cảm. Liệu mối quan hệ giữa cô gái trái đất và chàng trai ngoài hành tinh sẽ có được kết thúc có hậu?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hà Lam Đậu","avatar":""},{"name":"Ngưu Tử Phiên","avatar":""},{"name":"Mạch Hanh Lợi","avatar":""},{"name":"Ngô Hạo Trạch","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
