INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-dau-go', 'Cô Nàng Đầu Gỗ', 'Smile To Life', 'https://phimimg.com/upload/vod/20240324-1/3ede75aa73b4d5d89375c00dd5962e3a.jpg', 'https://phimimg.com/upload/vod/20240324-1/8b6590b05b5240b6b1f5198976b88bd2.jpg', '<p>Hứa Đa Tranh là một cô gái trẻ đầy sức sống. Không ai biết phía sau nụ cười ấy là căn bệnh hiếm gặp ALS, cô ấy biết mình sống không còn lâu nữa nhưng vẫn muốn tận hưởng mỗi ngày trôi qua thật vui vẻ. Đột nhiên, Giang Nam, chàng nhạc sĩ nổi tiếng đẹp trai, xuất hiện và làm đảo lộn cuộc sống của cô. Giữa sống hạnh phúc những ngày còn lại với người mình yêu và bỏ đi để tránh gây đau khổ cho người ấy, cô sẽ chọn con đường nào cho mình?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2022, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Mao Na","avatar":""},{"name":"Thường Triết Khoan","avatar":""},{"name":"Tưởng Thân","avatar":""},{"name":"Hoàng Thiên Thạc","avatar":""},{"name":"Phương Sở Đồng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
