INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-buoc-tien-len', 'Vững Bước Tiến Lên', 'Best Foot Forward', 'https://phimimg.com/upload/vod/20240324-1/b83616a409647eaa7781da766071fdb9.jpg', 'https://phimimg.com/upload/vod/20240324-1/369aa4decab07415e9a57a03bf9985d0.jpg', '<p>Josh Dubin rất vui khi được chuyển từ trường học tại nhà sang trường công lập và việc trở thành đứa trẻ duy nhất mang chân giả là một thử thách mà cậu ấy sẵn sàng đối mặt. Khi anh ấy tạo dựng một vị trí trong số các đồng nghiệp của mình, bạn bè và gia đình của anh ấy sẽ ở bên anh ấy trên mọi bước đường.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Logan Marmino","avatar":""},{"name":"Peyton Jackson","avatar":""},{"name":"Trinity Bliss","avatar":""},{"name":"Joy Suprano","avatar":""},{"name":"Stephen Schneider","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
