INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('saree-yeu-dau', 'Saree Yêu Dấu', 'Sinaeha Saree', 'https://phimimg.com/upload/vod/20240324-1/e32f77572f3cfdd9b53f44ab23fed206.jpg', 'https://phimimg.com/upload/vod/20240324-1/4a5caf2208f8747f375979c87a0fb6f5.jpg', '<p>Sarree Yêu Dấu - Sinaeha Saree xoay quanh câu chuyện tình yêu và cuộc sống của Nuannuerkaew Jaz. Cô chưa bao giờ nghĩ đến việc đến Ấn Độ, nhưng bây giờ cô phải bay đến đây vì em gái là Nilapat sẽ kết hôn với Chaithat - hoàng tử của thành phố Muntra Putra. Mọi chuyện đều tốt đẹp cho đến khi Nữ hoàng Sasiprapai không chấp nhận Nilapat là con dâu của mình. Bà sắp đặt Savitree cho Chaithat, một kẻ chuyên gây rắc rối và có âm mưu sẽ phá hỏng lễ cưới của Nilapat và Chaithat. Câu chuyện sẽ đỡ phức tạp hơn nếu cô không gặp Giris, anh trai của Chaithat, người mà cô đã yêu ngay từ cái nhìn đầu tiên.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Baifern Pimchanok","avatar":""},{"name":"Sean Jindachot","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
