INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-thien-kim-lac-duong', 'Tứ Thiên Kim Lạc Dương', 'The Four Daughters Of Luoyang', 'https://phimimg.com/upload/vod/20240403-1/98335b2e1816a0f074a6d3da8aff4a16.jpg', 'https://phimimg.com/upload/vod/20240403-1/5efbec8962c1ebca7578a8585b49146d.jpg', '<p>Cố lão gia và Cố phu nhân, gia chủ họ Cố giàu có nhất Lạc Dương đột nhiên biến mất, chỉ để lại bốn người con gái. Nhị thúc của Cố gia và bốn tiểu thư họ Cố bắt đầu xoay quanh cuộc chiến tài sản. Cố Nhị Thúc liên thủ với Lý gia, đối thủ cạnh tranh với nhà Cố gia, dùng mọi lý do để ép trưởng nữ Cố gia là Cố Nhược Nhược gả cho con trai thứ Lý gia là Lý Tùng để làm mất quyền thừa kế của cô. Với sự giúp đỡ của ba tỷ muội, Cố Nhược Nhược đã dùng mọi cách để ngăn chặn âm mưu của Cố Nhị thúc, cuối cùng kết thành đồng minh với Lý Khách, trưởng tử của Lý gia. Hai người đã dùng cách liên hôn để đánh bại âm mưu trong gia tộc và trong mối quan hệ đối đầu và liên minh này, họ ngày càng gắn bó hơn và nên duyên với nhau.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lai Yumeng","avatar":""},{"name":"Yu Yijie","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324305);
