INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-dieu-phan-1', 'Hắc Điểu (Phần 1)', 'Black Bird (Season 1)', 'https://phimimg.com/upload/vod/20240403-1/ebd70a850c32a18e42b45ece0a76dfc7.jpg', 'https://phimimg.com/upload/vod/20240403-1/ae38895246eb061e5d56bcdc26b81c9a.jpg', '<p>Khi Jimmy Keene bắt đầu bản án 10 năm tù, anh ta nhận được một lời đề nghị đáng kinh ngạc: Nếu anh ta có thể lôi ra lời thú tội từ kẻ giết người bị tình nghi là Larry Hall, Jimmy sẽ được trả tự do. Hoàn thành nhiệm vụ này trở thành thử thách của cả cuộc đời.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 17, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Taron Egerton","avatar":""},{"name":"Paul Walter Hauser","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Greg Kinnear","avatar":""},{"name":"Sepideh Moafi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
