INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-sinh', 'Vĩnh Sinh', 'IMMORTALITY', 'https://phimimg.com/upload/vod/20240403-1/ff1fe66b0d9756e50cad65c1d7551691.jpg', 'https://phimimg.com/upload/vod/20240403-1/00aa856945beb2b4731956af063d6075.jpg', '<p>Phương Hàn, một nô lệ thấp kém từ nhỏ đã có mong muốn thà làm ăn mày hơn làm nô lệ, dựa vào bản thân tung hoàng khắp trời đất. Bằng sự quật cường không chịu khuất phục, hắn đã phá bỏ những huyền bí thần thông, luyện thành cơ thể vĩnh hằng; từng bước cố gắng gia nhập tiên đạo và trở thành Người đứng đầu.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
