INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dr-parks-clinic', 'Dr. Park''s Clinic', 'Dr. Park''s Clinic', 'https://phimimg.com/upload/vod/20240403-1/972f6b64a39dde394a46b7be5bdd0df2.jpg', 'https://phimimg.com/upload/vod/20240403-1/f6421fa44377f1bb35d15ede31533f3f.jpg', '<p>Phim kể về Park Won Jang mở phòng khám bệnh với mong muốn trở thành một bác sĩ giỏi và kiếm được nhiều tiền. Nhưng số bệnh nhân đến thăm khám lại rất ít khiến phòng khám đang trên đà phá sản. Thêm vào đó, bác sĩ Park Won Jang bắt đầu bị rụng tóc. Vợ anh là Sa Mo Rim lại chỉ tin tưởng các chương trình y tế trên truyền hình hơn là khả năng của chồng. Liệu bác sĩ Park Won Jang sẽ làm gì để xoay chuyển được tình thế?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
