INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-bau-quoc-gia-ranh-gioi-lich-su', 'Kho Báu Quốc Gia: Ranh Giới Lịch Sử', 'National Treasure: Edge Of History', 'https://phimimg.com/upload/vod/20240403-1/f7c93005f68abe5c07f2a8ce2e961bd6.jpg', 'https://phimimg.com/upload/vod/20240403-1/4189411c673d00cf33326fa4c717150e.jpg', '<p>&nbsp;Jess hy sinh tất cả để đối đầu với kẻ đã giết cha mình nhằm tìm ra mảnh ghép cuối cùng của tấm bản đồ. Nhưng cuộc gặp gỡ đó đã làm rung chuyển thế giới của cô khi cô biết rằng không có gì được mong đợi trong một cuộc truy tìm kho báu, khiến cô đưa ra một quyết định nguy hiểm có thể khiến cô phải ngồi tù suốt đời. Trong khi tìm kiếm kho báu vĩ đại nhất trong lịch sử, Jess Valenzuela đã khám phá ra quá khứ bí mật của gia đình cô.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 17, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lisette Olivera","avatar":""},{"name":"Zuri Reed","avatar":""},{"name":"Catherine Zeta-Jones","avatar":""},{"name":"Breeda Wool","avatar":""},{"name":"Lyndon Smith","avatar":""},{"name":"Armando Riesco","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324305);
