INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thay-y-duc-ban-tho-nhi-ky', 'Người Thầy Y Đức (Bản Thổ Nhĩ Kỳ)', 'Dr. Romantic / Kasaba Doktoru', 'https://phimimg.com/upload/vod/20240403-1/26d0b118ba9ef13b1330d14b20ad2b78.jpg', 'https://phimimg.com/upload/vod/20240403-1/46743b22dbed63ca71a0925ef2c59c3f.jpg', '<p>&nbsp;Layla có biệt danh là “cá voi điên”. Với tính cách lạc quan và trong sáng, cô đã trở thành một bác sĩ hết mình vì bệnh nhân để chứng minh sự tồn tại của bản thân mình và luôn hi vọng được ai đó công nhận. Sau tai nạn, cô biến mất khỏi Bệnh viện Istanbul và được Hakan cứu sống sau khi bị thương. Cô bị mắc chứng bệnh PTSD (hội chứng rối loạn sau chấn thương tâm lí) do cảm giác tội lỗi sau cái chết của vị hôn phu. Sau đó cô trở thành bác sĩ tại Bệnh viện Ulucinar.Omer thông minh và được trang bị những kỹ năng tuyệt vời, anh ấy có khao khát thành công mạnh mẽ nhưng bị kìm hãm do hoàn cảnh gia đình nghèo khó. Omer được chuyển đến Bệnh viện Ulucinar sau cuộc phẫu thuật thất bại trên VIP, đó là cơ hội để anh chứng minh kỹ năng của mình.Trong những ngày đầu đến Bệnh viện Ulucinar, Omer bị choáng ngợp bởi phong cách làm việc ở đây, và có nhiều bất đồng với vị bác sĩ Hakan – người đã cứu Layla.Vậy bác sĩ Hakan là ai và có tầm ảnh hưởng như thế nào tại bệnh viện này? Liệu Omer có thích nghi được với phong cách làm việc của bệnh viện Ulucinar hay không?&nbsp;</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 18, 2022, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Ozan Akbaba","avatar":""},{"name":"Hazal Subaşı","avatar":""},{"name":"Deniz Can Aktaş","avatar":""},{"name":"Vildan Atasever","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
