INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-thien-tinh-phan-3', 'Cô Gái Thiên Tinh (Phần 3)', 'DC''s Stargirl (Season 3)', 'https://phimimg.com/upload/vod/20240403-1/ea9d26d89c9853375c701bbf08039739.jpg', 'https://phimimg.com/upload/vod/20240403-1/6f18f80ffd571130ac5dab295c0a43cb.jpg', '<p>Courtney Whitmore, một cô gái thông minh, thể thao và hơn hết là tốt bụng, phát hiện ra cha dượng của cô có một bí mật: ông từng là bạn đồng hành của một siêu anh hùng. Vay mượn thành viên vũ trụ anh hùng đã mất từ lâu, cô ấy trở thành nguồn cảm hứng cho một thế hệ siêu anh hùng hoàn toàn mới.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 18, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brec Bassinger","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Amy Smart","avatar":""},{"name":"Yvette Monreal","avatar":""},{"name":"Anjelika Washington","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
