INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-banh-cung-otis-phan-2', 'Lăn Bánh Cùng Otis (Phần 2)', 'Get Rolling With Otis (Season 2)', 'https://phimimg.com/upload/vod/20240403-1/84a81bf2fa91f9706a70ab8056d24846.jpg', 'https://phimimg.com/upload/vod/20240403-1/59ec34fb591466dc2b1b14a730ea1375.jpg', '<p>Chào mừng bạn đến với Trang trại bò sữa Long Hill, quê hương của máy kéo Otis và tất cả bạn bè của anh ấy. Otis có thể nhỏ bé, nhưng anh ấy có một trái tim lớn. Bất cứ khi nào anh ấy thấy một người bạn gặp khó khăn, anh ấy sẽ phanh lại để xem có gì sai và lao vào hành động để giúp đỡ.</p>', 'Hoàn Tất (9/9)', 9, 'hoathinh', 'completed', 12, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Griffin Robert Faulkner","avatar":""},{"name":"Elliott Fullam","avatar":""},{"name":"Katie Grober","avatar":""},{"name":"Josiah Gaffney","avatar":""},{"name":"Leah Janvier","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324305);
