INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-chau-a-am-thuc-khieu-vu-mo-mong', 'Đêm Châu Á: Ẩm Thực - Khiêu Vũ - Mơ Mộng', 'Midnight Asia: Eat · Dance · Dream', 'https://phimimg.com/upload/vod/20240403-1/1642bb35e193f5de9d43622bccfac178.jpg', 'https://phimimg.com/upload/vod/20240403-1/4c5d509ecc3c0d101103eda6176caf33.jpg', '<p>Màn đêm khơi dậy mặt chịu chơi nhất của các đô thị châu Á. Loạt phim tài liệu này xoay quanh đồ ăn, thức uống, âm nhạc — và những con cú đêm tỏa sáng trong bóng tối.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324305);
