INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-ngam-toa-soan', 'Sóng Ngầm Tòa Soạn', 'Pride And Price', 'https://phimimg.com/upload/vod/20240403-1/3747b72e3bfa3e3b1f4564f026d141f4.jpg', 'https://phimimg.com/upload/vod/20240403-1/c4fd2cd5a477a887e799f89fffa5016b.jpg', '<p>Với sự phát triển của Internet, các phương tiện truyền thông truyền thống chịu sự ảnh hưởng không nhỏ. Tòa soạn tạp chí Blossom cũng phải đối mặt với bước chuyển mình bất ngờ với vị trí chủ biên. Dù có phó chủ biên Trần Khai Di giỏi chuyên môn, đầy tham vọng nhưng tập đoàn lại cử Tiêu Hồng Tuyết đến làm chủ biên mới. Những cải tổ của Hồng Tuyết đã giúp cho tạp chí Blossom mang một diện mạo mới phát triển tốt hơn.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 6, 2022, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Tiểu Tống Giai","avatar":""},{"name":"Trần Hách","avatar":""},{"name":"Viên Vịnh Nghi","avatar":""},{"name":"Tống Tổ Nhi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
