INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-mon', 'Hắc Môn', 'SWARM', 'https://phimimg.com/upload/vod/20240403-1/05c931d00a4ffee7d5c9c32a56334119.jpg', 'https://phimimg.com/upload/vod/20240403-1/aa70924fe6f6fa4172b9ed26c3aa65f0.jpg', '<p>Một vụ tai nạn giao thông tưởng chừng như đơn giản lại khiến rất nhiều thế lực bị cuốn vào. Trong lúc các bên đang điều tra chân tướng sự việc, một loạt sự cố đột nhiên xảy ra. Nguy cơ ẩn giấu sau vụ án vượt xa so với trong tưởng tượng của mọi người… Khi tất cả đang tìm kiếm giới hạn của bản thân, họ lại không ý thức được rằng mình lại lần nữa đang đứng giữa ngã rẽ của sự tiến hoá, một thời đại vĩ đại đã được mở ra.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
