INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lon-xon', 'Lộn Xộn', 'Darmaduman', 'https://phimimg.com/upload/vod/20240403-1/640d106b7365b0c0a205100f67287b4d.jpg', 'https://phimimg.com/upload/vod/20240403-1/88c68b24d5ffe29fa5ce38cf9fd857ae.jpg', '<p>Gia đình Servet, chuyển từ Eskişehir đến Istanbul vì lý do gia đình, bước vào một môi trường hoàn toàn khác. Cố gắng thích nghi với môi trường tại trường đại học tư thục mà họ bắt đầu, cặp song sinh Kerem và Ece sẽ gặp những người không giống mình, trong khi họ đang trên đường trưởng thành trong những nỗi đau lớn dần, họ cũng sẽ bước vào một hành trình dài mang tên tuổi trẻ, nơi họ họ sẽ bị cuốn theo những mưu cầu, sai lầm và sự phấn khích của mối tình đầu muốn khám phá chính mình.<br/>Trong khi cặp song sinh đang bị thử thách với những cơn đau ngày càng lớn, khi cha của họ là Harun buộc phải trở về nhà của cha mình, nơi ông đã không đặt chân đến trong 25 năm, mối hận thù giữa cha và con trai sẽ khiến cả gia đình căng thẳng với những tính toán sâu sắc. Mẹ của họ, Beliz, sẽ bước vào một thời kỳ mới mà bà sẽ khám phá bản thân.<br/>Khi ông của cặp song sinh Asaf và bà của họ Ayla bắt đầu sống chung dưới một mái nhà với các con trai và cháu của họ 25 năm sau, họ sẽ nhận ra rằng sự trưởng thành và trưởng thành kéo dài suốt đời với những xung đột mà họ sẽ bước vào.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 17, 2022, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Mert Yazıcıoğlu","avatar":""},{"name":"Aslıhan Malbora","avatar":""},{"name":"Hafsanur Sancaktutan","avatar":""},{"name":"Aytaç Şaşmaz","avatar":""},{"name":"Nur Fettahoğlu","avatar":""},{"name":"Necip Memili","avatar":""},{"name":"Aslı Orcan","avatar":""},{"name":"Meral Çetinkaya","avatar":""},{"name":"Metin Coşkun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
