INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-man', 'Hạ Màn', 'Curtain Call', 'https://phimimg.com/upload/vod/20240403-1/fceccc37643c2f69ad03171197cae278.jpg', 'https://phimimg.com/upload/vod/20240403-1/4ff58da19b6bc91fa882c06a3850e997.jpg', '<p>bộ phim kể về những con người bị cuốn vào màn kịch lừa đảo. một quý ông yêu cầu Yoo Jae-Heon đóng vai cháu trai của một bà già. Cháu trai của bà lão đào tẩu khỏi Triều Tiên. Điều này thay đổi cuộc đời của Yoo Jae-Heon.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kang Ha-Neul","avatar":""},{"name":"Ha Ji-Won","avatar":""},{"name":"Kwon Sang-Woo","avatar":""},{"name":"Jung Ji-So","avatar":""},{"name":"Sung Dong-Il","avatar":""},{"name":"Ji Seung-Hyun","avatar":""},{"name":"Noh Sang-Hyun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
