INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-ma-dau-lo-tay-roi', 'Tiểu Ma Đầu Lộ Tẩy Rồi!', 'BUSTED! DARKLORD', 'https://phimimg.com/upload/vod/20240403-1/7c3e8f3607801cd65b4423be5b8a66ff.jpg', 'https://phimimg.com/upload/vod/20240403-1/ffbe277ed86c3e0fa4fd230cc8123141.jpg', '<p>Để sống tiếp trên giang hồ, con trai giáo chủ ma giáp Vu Nhân Kiệt nhận lệnh trà trộn vào “học viện chính đạo” chỉ tuyển đệ tử danh môn chính phái, mục tiêu để giành được “chứng nhận người tốt” nằm rửa sạch thân phận ma giáo. Chuyến đi này cực kỳ hung hiểm, một khi bị lộ thâm phận ma giáo thì sẽ bị vô số hiệp khách chính đạo giết ngay tại chỗ. Nhưng hôm báo cáo, Vu Nhân Kiệt xấu hổ phát hiện thông tin cá nhân của mình sớm đã bị người tra điều tra rõ mồn một rồi, vì để che giấu thân phận anh cuối cùng chọn… mặc áo quần con gái. Cuộc sống vườn trường hung hiểm lại hài hước sắp bắt đầu.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324305);
