INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phap-y-tan-minh-nguoi-doc-tam', 'Pháp Y Tần Minh: Người Đọc Tâm', 'Medical Examiner Dr Qin: The Mind Reader', 'https://phimimg.com/upload/vod/20240403-1/9471ccea2aec29d8dd5fcd7abd946211.jpg', 'https://phimimg.com/upload/vod/20240403-1/5a68eed3ec6462802075ffea01118283.jpg', '<p>Cậu sinh viên pháp y vừa mới tốt nghiệp Tần Minh trở về quê để điều tra cái chết bí ẩn của mẹ. Quá trình thu thập chứng cứ đã vô tình dẫn Tần Minh đến một vụ án mạng khác. Cùng một lúc phải giải quyết hai vụ án, Tần Minh không còn cách nào khác là phải cầu cứu chính quyền địa phương. Với sự giúp đỡ của nhóm cảnh sát cùng nhân viên khám nghiệm tử thi An Nhiên, Lâm Đào, Hoàn Hoàn, các vụ án dần dần được lật mở, hé lộ một âm mưu cực lớn đằng sau đó.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 6, 2022, 'Vietsub + Thuyết minh', 'HD', 'Trung Quốc', 0, '[{"name":"Bành Sở Việt","avatar":""},{"name":"Trương Diệu","avatar":""},{"name":"Thang Mẫn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
