INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-ban-ngoi-hang-cuoi', 'Những Cô Bạn Ngồi Hàng Cuối', 'The Girls At The Back', 'https://phimimg.com/upload/vod/20240403-1/f807fbd3708a80e444a4d40424edfe66.jpg', 'https://phimimg.com/upload/vod/20240403-1/83513a65c8500f64a6aa24450fa9dc5a.jpg', '<p>Trong bộ phim hài cảm động này, sau khi một người trong nhóm mắc bệnh ung thư, 5 người bạn lập kế hoạch cho loạt thử thách đầy hỗn loạn để thực hiện những điều phải làm trong đời.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Itsaso Arana","avatar":""},{"name":"Mónica Miranda","avatar":""},{"name":"María Rodríguez Soto","avatar":""},{"name":"Mariona Terés","avatar":""},{"name":"Godeliv Van den Brandt","avatar":""},{"name":"Javier Rey","avatar":""},{"name":"Macarena García","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
