INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-toi-voi-tinh-yeu', 'Ăn Tối Với Tình Yêu', 'Dine With Love', 'https://phimimg.com/upload/vod/20240403-1/c64531ae2b5e88acff81b1f9710ad44a.jpg', 'https://phimimg.com/upload/vod/20240403-1/99c901a171fb90b2cef54ad94e6311a9.jpg', '<p>Phim kể về Yu Hao, người không biết nấu ăn và thậm chí không có bếp. Nhưng anh không muốn mất thời gian học nấu ăn vì hiệu quả nên đã dùng chiêu trò quay lén, xúc phạm ê-kíp chương trình. Su Kelan được lệnh trở thành giám đốc quan hệ công chúng đang gặp nguy hiểm, đảm nhận công việc quan hệ công chúng để đối phó với khủng hoảng, và trở thành giáo viên dạy nấu ăn của Yu Hao. Cô đưa anh vào bếp và từ từ bắt đầu đi vào trái tim anh.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Gao Hanyu","avatar":""},{"name":"Zheng Qiuhong","avatar":""},{"name":"Wang Peihan","avatar":""},{"name":"He Lei","avatar":""},{"name":"Bai Xinyi","avatar":""},{"name":"Lu Lu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
