INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dieu-tra-phap-y', 'Đội Điều Tra Pháp Y', 'Forensic Investigation Team', 'https://phimimg.com/upload/vod/20240403-1/9f7cd1bb5633bf87e58e752772e2fe78.jpg', 'https://phimimg.com/upload/vod/20240403-1/3aa4f64a2012fdc1e4ad1e0646923fac.jpg', '<p>Đội điều tra pháp y Đội bầu trời pháp y được tập hợp lại, họ sẽ đến sáu địa điểm để điều tra những vụ án kỳ quái với kiến thức pháp y năng lượng cao, đồng thời đặc biệt mời một số người đam mê lý luận theo đuổi sự thật trong sương mù. Chương trình bám sát chủ đề “Giáo dục phổ biến pháp luật” giúp tạo trải nghiệm mới về phổ biến pháp luật cho toàn dân.</p>', 'Hoàn Tất (5/5)', 5, 'tvshows', 'completed', 12, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tề Tư Quân","avatar":""},{"name":"Thiệu Minh Minh","avatar":""},{"name":"Thạch Khải","avatar":""},{"name":"Hướng Cầm Cầm","avatar":""},{"name":"Khuất Dật Linh","avatar":""},{"name":"Lưu Triều Dụ","avatar":""},{"name":"Trần Thực","avatar":""},{"name":"Lưu Lương","avatar":""},{"name":"Châu Dịch Võ","avatar":""},{"name":"Khuất Quốc Cường","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324305);
