INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-trai-12-cua-toi', 'Bạn Trai 1/2 Của Tôi', 'My Honey', 'https://phimimg.com/upload/vod/20240403-1/9ca0c648483762885e069e6d4450a568.jpg', 'https://phimimg.com/upload/vod/20240403-1/b154af63a5e23e686715ccd4e23c6346.jpg', '<p>Học sinh ưu tú Tô Tử Oánh keo kiệt có biệt danh Bồ Tát Làm Công, trong lúc làm người mẫu ngoài giờ đã vô tình gặp đại thần tranh sơn dầu Diệp Tuấn Thành lạnh lùng nhỏ hơn cô một khoá. Hai người bên nhau chữa lành căn bệnh lạ và bóng đen tuổi thơ cho nhau, nhưng đồng thời họ cũng rơi vào vòng xoáy của tình cảm. Mở màn cho câu chuyện Tam giác tình yêu hai người của số phận.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kim Tử Hàm","avatar":""},{"name":"Giang Tín Hi","avatar":""},{"name":"Trần Hân Uy","avatar":""},{"name":"Trương Cảnh Quân","avatar":""},{"name":"Trương Hạo Liêm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
