INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mac-bach', 'Mặc Bạch', 'Double Love', 'https://phimimg.com/upload/vod/20240403-1/e9c532402fdc70668180f305f979bf26.jpg', 'https://phimimg.com/upload/vod/20240403-1/e0a3e6593402224e299220338164f03f.jpg', '<p>Mặc Bạch do Vương Nham làm đạo diễn, là một bộ phim tình cảm ngọt ngào với sự tham gia của Trương Tuyết Nghênh, Tất Văn Quân, Quách Phẩm Siêu, Đại Tư. Bộ phim được chuyển thể từ tiểu thuyết Đại Thần Phu Nhân Nhà Ngài Lại AFK Rồi của tác giả Đại Quất Miêu, Bộ phim chủ yếu xoay quanh câu chuyện tình yêu của gà mờ Lục Hoàn Hoàn và đại thần Hàn Kinh Mạc. Lục Hoàn Hoàn vì trượt tay trong trò chơi mà lỡ đâm bay đại thần đứng đầu toàn server Mặc Bạch Chi Gian . Thực ra Lục Hoàn Hoàn ngoài đời luôn theo dõi tác phẩm của Hàn Kinh Mạc nhưng một lần cô lại bị anh tạt nước mà từ đó hay người trở thành kẻ thù. Nhưng Lục Hoàn Hoàn không thể ngờ được Mặc Bạch Chi Gian lại chính là Hàn Kinh Mạc, dù ngoài đời hay là trong game thì anh vẫn luôn bên cô cả hai từ thế giới game đến hiện thực, họ yêu nhau và hiện thực hóa ước mơ diễn xuất của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Tuyết Nghênh","avatar":""},{"name":"Tất Văn Quân","avatar":""},{"name":"Dylan Kuo","avatar":""},{"name":"Daisy Dai","avatar":""},{"name":"Stella","avatar":""},{"name":"Didy","avatar":""},{"name":"Guo Xiaotian","avatar":""},{"name":"Francis","avatar":""},{"name":"Li Yu Yang","avatar":""},{"name":"Chun Yu","avatar":""},{"name":"李欣燃","avatar":""},{"name":"Shi Nan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
