INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-quan-thu-sau-mua-3', 'Giác Quan Thứ Sáu (Mùa 3)', 'Sixth Sense (Season 3)', 'https://phimimg.com/upload/vod/20240403-1/6023befacf26fd9adf3c20e85b738953.jpg', 'https://phimimg.com/upload/vod/20240403-1/0602119167ceac8536b66dab4bedbf4a.jpg', '<p>Chương trình đấu trí cực kỳ thú vị và gay cấn khi người chơi và khách mời phải vận dụng đến cả giác quan thứ sáu để tìm ra đồ-giả-thật-hơn-đồ-thật ẩn trong thế giới thực. Những kết quả không thể đoán trước, những bức rèm bí mật dần hé lộ sẽ mang đến nhiều bất ngờ cho khán giả.Sixth Sense - Giác Quan Thứ Sáu mùa 3 có sự tham gia của 5 thành viên cố định gồm: MC Quốc dân Yoo Jae Suk, Jessi, Mi Joo (Lovelyz), Oh Na Ra và Lee Sang Yeob. Mỗi tập phát sóng sẽ có những khách mời nổi tiếng khác cùng tham gia như Yoon Chan Young, Nam Yoon Su, Kim Hye Yoon, ...Sixth Sense - Giác Quan Thứ Sáu mùa 3 phát song song với Hàn Quốc tối thứ Sáu hàng tuần trên FPT Play. Mời quý khán giả đón theo dõi.</p>', 'Hoàn Tất (14/14)', 14, 'tvshows', 'completed', 12, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yoo Jae Suk","avatar":""},{"name":"Jessi","avatar":""},{"name":"Oh Na Ra","avatar":""},{"name":"Mi Joo (Lovelyz)","avatar":""},{"name":"Lee Sang Yeob","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
