INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-lang-nghe-toi', 'Hãy Lắng Nghe Tôi', 'Duy Beni (Hear Me)', 'https://phimimg.com/upload/vod/20240403-1/48f8141690d98f9ea6353496ffa212ba.jpg', 'https://phimimg.com/upload/vod/20240403-1/04fc167461586dd1725e05f8162b57c0.jpg', '<p>uộc sống của cô học sinh trung học Ekim, một người sống bình thường tại một trong những khu trung lưu của Istanbul, bị đảo lộn bởi một vụ tai nạn giao thông thương tâm diễn ra ngay trước mắt cô. Điều duy nhất mà Ekim nhớ về vụ tai nạn là chiếc mặt nạ trên mặt người lái xe và người bạn Leyla của cô ấy nằm trên mặt đất đầy máu.Chiếc xe đâm vào Leyla và bỏ chạy, người dân trong khu phố bắt đầu nổi loạn khi biết rằng hung thủ đang trốn trong trường Cao đẳng Gerçek - trường có khuôn viên rất gần khu phố. Chiếc xe gần như biến mất khi lao vào giữa ngôi trường mà con cái của những gia đình giàu có và quyền lực này theo học.Trong khi những người hàng xóm yêu cầu công lý, ban giám hiệu nhà trường cố gắng làm dịu phản ứng bằng cách trao học bổng cho ba học sinh từ khu phố của Leyla. Sau một thời gian, tin tức này được khép lại. Tuy nhiên, Ekim không có ý định buông tha cho kẻ đã khiến bạn thân mình dành phần đời còn lại của mình trên xe lăn. Chỉ có một điều mà cô ấy chắc chắn: Tên tội phạm là một trong những đứa trẻ nhà giàu và hư hỏng ở trường.Vì vướng phải vài rắc rối mà Ekim và hai người bạn kia phải đối mặt với cảnh bạo lực học đường do một nhóm học sinh gây nên, mà trong đó cầm đầu là “nữ hoàng” của trường.Khi Ekim đấu tranh để phá bỏ bức màn bí mật đen tối này và đảm bảo công lý, cảm xúc của cô ấy sẽ khiến cô ấy bối rối và trái tim của cô ấy sẽ bị đảo lộn.Liệu Ekim có đủ sức mạnh để vượt qua tất cả, đứng lên tìm ra và đưa sự thật ra công lý hay không?&nbsp;Hãy cùng chờ đón sự phát sóng của siêu phẩm “DUY BENI / HEAR ME / LẮNG NGHE TÔI” trên OPhim.CC nhé cả nhà mình ơiiii&nbsp;cho tớ thấy cánh tay của các bạn đang hóng phim này đi ạ</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 18, 2022, 'Vietsub', 'Full HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Berk Hakman","avatar":""},{"name":"Rabia Soytürk","avatar":""},{"name":"Caner Topçu","avatar":""},{"name":"Helin Kandemir","avatar":""},{"name":"Burak Can","avatar":""},{"name":"Sümeyye Aydoğan","avatar":""},{"name":"Feride Çetin","avatar":""},{"name":"Aytaç Uşun","avatar":""},{"name":"Meltem Akçöl","avatar":""},{"name":"..","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324305);
