INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghiep-trong-phuc', 'Nghiệp Trong Phúc', 'Buang Bai Bun', 'https://phimimg.com/upload/vod/20240403-1/51909d419d146745e49b671024709397.jpg', 'https://phimimg.com/upload/vod/20240403-1/8d1b63ffacbd0ae2db39946cf2aa3e0e.jpg', '<p>Dok Rak từ cô gái bình thường, bị gia đình gán nợ và trở thành vợ bé của ông chủ nhà giàu. Bước chân vào hào môn, cuộc đời cô bắt đầu là chuỗi ngày tranh giành tình yêu và tài sản. Kể cả phải chà đạp lên người khác hay làm người khác tổn thương, thì Dok Rak cũng sẵn sàng làm để đạt được mục đích của mình. Đâu sẽ là cái giá mà Dok Rak phải trả cho những gì mình gây ra?</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 7, 2022, 'Vietsub + Thuyết minh', 'HD', 'Thái Lan', 0, '[{"name":"Sirilak Pongchoke","avatar":""},{"name":"Kamolchanok Komoltithi","avatar":""},{"name":"Moo Dilok Thongwattana","avatar":""},{"name":"Big Sarut Vichitrananda","avatar":""},{"name":"Kett Tharntup","avatar":""},{"name":"Oh Anuchit Sapunpohng","avatar":""},{"name":"Ohm Thitiwat Ritprasert","avatar":""},{"name":"Tong Savitree Samipak","avatar":""},{"name":"June Cholruedee Amornlak","avatar":""},{"name":"Pete Thongchua","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324305);
