INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('even-sun', 'Even Sun', 'Even Sun', 'https://phimimg.com/upload/vod/20240403-1/485880623c3e5f5859fbe33241c564a9.jpg', 'https://phimimg.com/upload/vod/20240403-1/89cb94c9c9beeee9da2d4a0c13aa8997.jpg', '<p>Even Sun (Tôi Chính Là Cậu Arthid) kể về câu chuyện xoay quanh Sun, là một người làm công việc đòi nợ nhưng chưa bao giờ anh chàng đòi nợ thành công. Cạnh tranh với Sun là Tai, một người mới vào nghề và thay vì đi đòi nợ, Tai lấy Mangkorn để đổi lấy tiền lãi. Một ngày nọ Sun được cha mình yêu cầu đi tìm Atid để thu hồi số nợ nếu không ông ấy sẽ bị phá sản, vì vậy ông đã yêu cầu Sun đến đảo Atid. Trên đường đến đảo Atid, Sun gặp những người bạn của Talay và Nai cùng tay sai của Atid nên Sun đã nghĩ ra kế hoạch tiếp cận Atid thông qua những người mới quen này. Atid biết Sun đến đòi nợ nhưng lại chẳng quan tâm đến điều đó mà bảo Sun quay lại Bangkok. Sun tìm mọi cách chọc phá Atid đến mức khiến Atid tức giận và lừa Sun đến một ngôi nhà bỏ hoang ở cuối hòn đảo. Và đó là khởi đầu của toàn bộ câu chuyện hỗn loạn này. Cuối cùng, liệu Sun có đòi được nợ Atid hay không hay từ kẻ xấu sẽ trở thành người yêu. Xem Even Sun Series vietsub cùng các thông tin về diễn viên, lịch chiếu sớm nhất trên iQIYI.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Boun Noppanut Guntachai","avatar":""},{"name":"Prem Warut Chawalitrujiwong","avatar":""},{"name":"Prem","avatar":""},{"name":"Longshi Lee","avatar":""},{"name":"Top Nathas Tunjaroen","avatar":""},{"name":"Tae Weerapat Toemmaneerat","avatar":""},{"name":"Kokliang Parinya Angsanan","avatar":""},{"name":"Tiger Tanawat Hudchaleelaha","avatar":""},{"name":"Mon Warakorn Waruncharernthorn","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
