INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-long-nhai-the-series', 'Ai Long Nhai The Series', 'AiLongNhai The Series', 'https://phimimg.com/upload/vod/20240302-1/6cbae38158977310558372e34255ff7e.jpg', 'https://phimimg.com/upload/vod/20240302-1/5f2fbb4ea0e30f69b945945687a25c5d.jpg', '<p>Kể về câu chuyện của chàng thiếu gia nhà giàu tên Ai đang đi du học tại Canada. Anh chàng vì một số lý do mà buộc phải quay trở lại Thái Lan, tại đây anh gặp gỡ Nhai - người bạn có nỗi ám ảnh về chiếc móc khóa hình con vịt màu vàng. Ai biết mình đã yêu ngay Nhai từ cái nhìn đầu tiên và một mối tình lãng mạn ập đến và câu chuyện tình yêu bắt đầu từ đây.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Meen Nichakoon Khajornborirak","avatar":""},{"name":"Ping Krittanun Aunchananun","avatar":""},{"name":"Arm Suppatyu Pranartkul","avatar":""},{"name":"Porsch Apiwat Apiwatseri","avatar":""},{"name":"Gungun Gun Tieosuwan","avatar":""},{"name":"Save Saisawat","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
