INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-kuroitsu-o-cuc-phat-trien-quai-nhan', 'Cô KUROITSU Ở Cục Phát Triển Quái Nhân', 'Kaijin Kaihatsubu No Kuroitsu-san, Miss Kuroitsu From The Monster Development Department', 'https://phimimg.com/upload/vod/20240302-1/af381598ed486b664105ba4dd90f5700.jpg', 'https://phimimg.com/upload/vod/20240302-1/f9b8ec60ac91c0127ba7eb2fc0fa1e2f.jpg', '<p>Kuroitsu Touka là nhà nghiên cứu của phòng phát triển quái nhân thuộc tổ chức tội ác Agastia. Tuy nhiên, kẻ địch mà cô ấy phải chiến đấu không phải là anh hùng chính nghĩa, mà là... yêu cầu vô lý của cấp trên, bắt cô phải lập bản kế hoạch trong vòng 10 phút trước khi thuyết trình trong hội nghị. Miễn là trên thế giới này, chính nghĩa vẫn hiện diện, thì cái ác vẫn còn tồn tại. Đây là câu chuyện về những chiến binh mà con người không hề hay biết. Một cuộc chiến giữa chính nghĩa và tội ác.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
