INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-anh-quoc-phan-6', 'Bóng Ma Anh Quốc (Phần 6)', 'Peaky Blinders (Season 6)', 'https://phimimg.com/upload/vod/20240302-1/eebbaaef047b855f9c491c02a3db8b8b.jpg', 'https://phimimg.com/upload/vod/20240302-1/833ad84dc8c22a04b75ea654f9f8f6f0.jpg', '<p>Phim lấy bối cảnh tại thành phố Birmingham, kể về sự khai thác của Gia đình tội phạm Shelby trong hậu quả trực tiếp của Thế chiến thứ nhất. Sự hư cấu gia đình dựa trên câu chuyện có thật cùng tên Peaky Blinders, nhóm băng đảng hoạt động trong thành phố nước Anh từ những năm 1890 đến những năm đầu thế kỷ 20. Đây là phần thứ 6 trong loạt phim Bóng Ma Anh Quốc. Một băng đảng khét tiếng xuất hiện ở Birmingham, Anh Quốc năm 1919. Cầm đầu băng là Tommy Shelby, tên trùm tội phạm khét tiếng muốn nổi lên bằng mọi giá.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Cillian Murphy","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Helen McCrory","avatar":""},{"name":"Paul Anderson","avatar":""},{"name":"Iddo Goldberg","avatar":""},{"name":"Annabelle Wallis","avatar":""},{"name":"Sophie Rundle","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"Joe Cole","avatar":""},{"name":"Ned Dennehy","avatar":""},{"name":"Andy Nyman","avatar":""},{"name":"Charlie Creed-Miles","avatar":""},{"name":"Charlotte Riley","avatar":""},{"name":"David Dawson","avatar":""},{"name":"Jeffrey Postlethwaite","avatar":""},{"name":"Matthew Postle","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
