INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-cung-con-luan', 'Thần Cung Côn Luân', 'Candle In The Tomb: Kunlun Tomb', 'https://phimimg.com/upload/vod/20240302-1/32b113c344583154e3a52d94d61b9b5e.jpg', 'https://phimimg.com/upload/vod/20240302-1/0e23a234b258235a9e0fa76f232ec070.jpg', '<p>Nhà buôn đồ cổ Hong Kong Ming Shu giao Hu Ba Yi, Wang Kai Xuan và Shirley Yang đi tìm xác chết trên sông băng trong vương quốc ma quỷ từ truyền thuyết về Vua Gesar. Vừa thoát khỏi thung lũng sâu, họ bắt đầu một cuộc hành trình mới để làm sáng tỏ một lời nguyền.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Phan Việt Minh","avatar":""},{"name":"Trương Vũ Kỳ","avatar":""},{"name":"Khương Siêu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324305);
