INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuc-khanh-hao', 'Chúc Khanh Hảo', 'My Sassy Princess', 'https://phimimg.com/upload/vod/20240302-1/6252b0a8e8c7924bea7b84d8ef97a440.jpg', 'https://phimimg.com/upload/vod/20240302-1/5ddd21724b57d6e51b994dd03d6ebb9d.jpg', '<p>Chúc Khanh Hảo (My Sassy Princess 2022) kể về câu chuyện của Trường Nhạc quận chúa Lưu Linh (Viên Băng Nghiên) vừa ngổ ngáo đáng yêu lại vừa bá đạo, tình cờ gặp được Cẩm Y Vệ Thẩm Yến (Trịnh Nghiệp Thành) lạnh lùng có võ công cao cường, bắt đầu câu chuyện truy đuổi thú vị muôn màu muôn vẻ. Thẩm Yến là một nam nhân thâm trầm kiêu ngạo, lạnh lùng nhưng nội tâm vô cùng ấm áp. Lần đầu gặp Thẩm Yến, Lưu Linh đã si mê cực độ, nàng quyết định theo đuổi một cách không kỷ cương, làm náo loạn thiên hạ lúc bấy giờ.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Crystal","avatar":""},{"name":"Trịnh Nghiệp Thành","avatar":""},{"name":"Mễ Nhiệt","avatar":""},{"name":"Zhang Yue","avatar":""},{"name":"Yang Zhiwen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324305);
