INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thinh-quan', 'Thỉnh Quân', 'Thousand Years For You', 'https://phimimg.com/upload/vod/20240302-1/440270bf45e106e9d1a6bba147d31fae.jpg', 'https://phimimg.com/upload/vod/20240302-1/a3af4580b1ee4b45b5cc7f5ebc4b84c6.jpg', '<p>Thỉnh Quân (Thousand Years For You) xoay quanh mối lương duyên 2 kiếp giữa nữ trại chủ Vu Đăng Đăng (Lý Thấm thủ vai) nghĩa hiệp, trọng nghĩa. Kiếp trước nàng là thần nữ với năng lực tuyệt đỉnh, nhất kiến chung tình cùng Lục Viêm (Nhậm Gia Luân thủ vai) một “sát thần ngàn năm” lạnh lùng, kiêu ngạo, vì yêu mà ngủ say ngàn năm. Từ đây câu chuyện tình yêu dở khóc, dở cười giữa 2 nhân vật diễn ra ,khi nàng ”một nữ trại chủ” dám cướp hôn ”một chiến thần ngàn năm”, trớ trêu thay khi kiếp trước họ là người yêu trong số mệnh, tạo ra một cuộc tình oan gia đầy thú vị.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 11, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Lý Thấm","avatar":""},{"name":"Cdy","avatar":""},{"name":"Chase Chen","avatar":""},{"name":"Wu Ming Jing","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
