INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-hanh-giua-cac-vi-sao', 'Du Hành Giữa Các Vì Sao', 'Interstellar Wanderer', 'https://phimimg.com/upload/vod/20240302-1/6b0c91c224f41bda3522f51b276cb9cc.jpg', 'https://phimimg.com/upload/vod/20240302-1/080de608afa490cb04a3a249f440e42a.jpg', '<p>Đường Nguyệt Lượng sắp xếp lại hành tinh, đã đánh thức năng lực của anh ấy, gánh vác trách nhiệm tìm kiếm vũ trụ trên vai. Thiện niệm của toàn nhân loại biến hoác ra hình thái “Thiên Khải” nói với Đường Nguyệt Lượng, cô là truyền nhân đời thứ 110 của tộc Giáng Ma. Từ sau khi con người rời khỏi trái đất, Thiên Thương làm loạn vũ trụ, vũ trụ dần mất trật tự, tràn đầy hỗn loạn và bạo lực, chỉ có tìm được pháp khí đầu cuối của vũ trụ, mới có thể thanh lọc vũ trụ. Đường Nguyệt Lượng kết bạn với Tôn Tiểu Bổng, Chu Liên Liên và Sa Bổn Bổ, họ mang theo mục đích riêng của mình thành lập nhóm lâm thời. Họ trải qua kiếp nạn, mỗi lần bị cản trở không chỉ không khiến họ từ bỏ mà ngược lại khiến suy nghĩ quay lại trái đất, vườn địa đàng đó càng thêm vững chắc.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
