INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chi-em-phan-1', 'Ba Chị Em (Phần 1)', 'Uc Kiz Kardes', 'https://phimimg.com/upload/vod/20240326-1/54f3ba4bded5146595551d7788309f9a.jpg', 'https://phimimg.com/upload/vod/20240326-1/796038783dee431a1f0abe26aaa82e5e.jpg', '<p>Ngày xửa ngày xưa ở một đất nước xinh đẹp nhưng bí ẩn, có ba chị em gái tên là Türkan, Dönüş và Derya. Là một gia đình gắn bó, họ sẽ mơ về một tương lai đầy hứa hẹn mỗi đêm. Có lẽ một cách dạy dỗ như vậy, tương tự như một câu chuyện cổ tích trên những con đường đầy mùi thông của Ayvalık, đã không chuẩn bị cho họ trước thực tế nghiệt ngã của tuổi trưởng thành. Theo thời gian, chị em phát hiện ra rằng cuộc sống và những lựa chọn đi kèm với nó không hề dễ dàng như họ tưởng. Những bí mật không thể ngờ tới có thể bị che giấu ngay cả với những người được tin tưởng nhất và những căn bệnh khủng khiếp có thể dẫn đến sự sống lại của quá khứ. Điều này dẫn họ đến câu hỏi: Có thứ gì trên đời mà thời gian không thể chữa lành?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 17, 2022, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"İclal Aydın","avatar":""},{"name":"Reha Özcan","avatar":""},{"name":"Özgü Kaya","avatar":""},{"name":"Almila Ada","avatar":""},{"name":"Melisa Berberoğlu","avatar":""},{"name":"Berker Güven","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
