INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ha-truong-minh', 'Tinh Hà Trường Minh', 'Shining Just For You', 'https://phimimg.com/upload/vod/20240229-1/4ce2bb5c5825448d4676591e10eeccf5.jpg', 'https://phimimg.com/upload/vod/20240229-1/35a53a845b3598a8db3ae402c27cd76a.jpg', '<p>Ye Lingshuang, một thiếu nữ bình thường lớn lên cùng công chúa út được yêu quý của thảo nguyên Qi Hairui / Zhuyan. Các cô gái trở thành bạn thân và Ye Lingshuang thề trung thành với công chúa. Thật không may, nhà cai trị đầy tham vọng của Vương quốc Zhao Yu Xiuming đã âm mưu chiếm lấy đồng cỏ, điều này cuối cùng dẫn đến việc Qi Hairui tự sát. Ye Lingshuang thề sẽ trả thù cho cái chết của công chúa và bước vào cung điện của Yu Xiuming dưới một thân phận mới. Hoàng đế bắt đầu quan tâm đến Ye Lingshuang sau khi nhận ra động cơ thực sự của cô ấy, và nữ chính bị giằng xé giữa lòng trung thành với quê hương và tình yêu.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2022, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Phùng Thiệu Phong","avatar":""},{"name":"Bành Tiểu Nhiễm","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
