INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-nui-bong-tuyet-thu-thach-truong-thanh', 'Ngọn Núi Bông Tuyết: Thử Thách Trưởng Thành', 'Snowflake Mountain', 'https://phimimg.com/upload/vod/20240229-1/6b0a9f5b73c7770499ba194cd15f94ff.jpg', 'https://phimimg.com/upload/vod/20240229-1/287afe3b58b7f38676cb78e5c4fa0397.jpg', '<p>Thương cho roi cho vọt, ghét cho ngọt cho bùi? Mười thanh niên bị chiều hư trải nghiệm thiên nhiên mà không có sự bảo bọc của cha mẹ trong loạt chương trình thực tế này.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 18, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Joel Graves","avatar":""},{"name":"Matt Tate","avatar":""},{"name":"Cat Bigney","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324305);
