INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('summering', 'Summering', 'Summering', 'https://phimimg.com/upload/vod/20240323-1/04bf57372b1cbbdab88447a3b37672b9.jpg', 'https://phimimg.com/upload/vod/20240323-1/e0ae0057ec0743f5cb9ae71d32e76269.jpg', '<p>Bốn người bạn thân nhất, trên bờ vực bắt đầu học cấp hai, nhận ra cuộc sống của họ sắp thay đổi mãi mãi. Vì vậy, vào cuối tuần cuối cùng của mùa hè, họ bắt đầu tận dụng tối đa nó. Tuy nhiên, không có gì có thể chuẩn bị cho họ khám phá đáng ngạc nhiên mà họ thực hiện khi thăm lại một trong những nỗi ám ảnh yêu thích của họ.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lia Barnett","avatar":""},{"name":"Madalen Mills","avatar":""},{"name":"Eden Grace Redfield","avatar":""},{"name":"Sanai Victoria","avatar":""},{"name":"Lake Bell","avatar":""},{"name":"Sarah Cooper","avatar":""},{"name":"Ashley Madekwe","avatar":""},{"name":"Megan Mullally","avatar":""},{"name":"Colleen Baum","avatar":""},{"name":"Dale McKeel","avatar":""},{"name":"Willow Corner-Bettweiser","avatar":""},{"name":"Yolanda Stange","avatar":""},{"name":"Nick Mathews","avatar":""},{"name":"Lu Prickett","avatar":""},{"name":"Camrey Bagley Fox","avatar":""},{"name":"Brandon Augustin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
