INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('when-the-rain-falls', 'When The Rain Falls', 'When The Rain Falls', 'https://phimimg.com/upload/vod/20240228-1/f1017f49d4e3ea5112dfd684267ab665.jpg', 'https://phimimg.com/upload/vod/20240228-1/408a619d0ee64e95aca9c6493346d448.jpg', '<p>Hazuki cắt móng tay mỗi khi trời mưa. Hồi đó cô vuốt ve cô bằng những ngón tay này. Hazuki, hiện là biên tập viên của một công ty xuất bản, bị thu hút bởi Shiori, trưởng phòng kế hoạch. Vào một ngày hai người phụ nữ ướt sũng dưới mưa, họ vào một nhà nghỉ trú ẩn và đi tắm. Ở đó, Hazuki nhìn thấy hình ảnh người bạn gái thất lạc của mình ở Shiori và cuối cùng họ đã liên lạc được với nhau.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kazumi","avatar":""},{"name":"Kazuha Komiya","avatar":""},{"name":"Yurisa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
