INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('high-low-lien-minh-tam-trung', 'High & Low: Liên Minh Tam Trung', 'High & Low The Worst X', 'https://phimimg.com/upload/vod/20240228-1/860a1a8942752daba476429a0e21821f.jpg', 'https://phimimg.com/upload/vod/20240228-1/a31615add77fa31a8e105973e2a919cb.jpg', '<p>Trong phần này, trung tâm câu chuyện tiếp tục xoay quanh trường trung học Oya do Hanaoka Fujio (Kawamura Kazuma) cầm đầu và kẻ thù mới, trường trung học Kỹ thuật Senomon. Amagai Kohei (Miyama Ryoki), thủ lĩnh Senomon và cánh tay phải đắc lực của hắn, đồng thời cũng là bạn từ nhỏ, Suzaki Ryo (Nakamoto Yuta) - người được mệnh danh là “thiên tài cô độc”, kẻ mạnh nhất Senomon cùng nhau thành lập một “Liên minh tam trung” gồm Senomon, trung học Kamasaka và trung học Thương mại Ebara nhằm lật đổ Oya.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kazuma Kawamura","avatar":""},{"name":"Hokuto Yoshino","avatar":""},{"name":"Nakamoto Yuta","avatar":""},{"name":"Ryoki Miyama","avatar":""},{"name":"Goki Maeda","avatar":""},{"name":"Akihisa Shiono","avatar":""},{"name":"Kohei Fukuyama","avatar":""},{"name":"Suzuki Takahide","avatar":""},{"name":"Ryutaro Ata","avatar":""},{"name":"Ryuji Sato","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
