INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-ho-chon-cong-so', 'Hẹn Hò Chốn Công Sở', 'Business Proposal', 'https://phimimg.com/upload/vod/20240319-1/300fa4392411a44d497d6c00e66de13a.jpg', 'https://phimimg.com/upload/vod/20240319-1/99d76187b7a370f64238e9cb5cffbb4a.jpg', '<p>Giả làm bạn của mình, Ha Ri đến buổi xem mắt để xua đuổi đối tượng. Nhưng kế hoạch này đổ bể khi hóa ra anh lại là sếp của cô – và anh đưa ra một đề xuất.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 12, 2022, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ahn Hyo-seop","avatar":""},{"name":"Kim Se-jeong","avatar":""},{"name":"Kim Min-gue","avatar":""},{"name":"Seol In-a","avatar":""},{"name":"Lee Duck-hwa","avatar":""},{"name":"Kim Kwang-kyu","avatar":""},{"name":"Jung Young-ju","avatar":""},{"name":"Kim Hyun-sook","avatar":""},{"name":"Song Won-seok","avatar":""},{"name":"Choi Byung-chan","avatar":""},{"name":"Im Gi-hong","avatar":""},{"name":"Yun Sang-jeong","avatar":""},{"name":"Bae Woo-hee","avatar":""},{"name":"Seo Hye-won","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
