INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-khu-toi-loi', 'Quá Khứ Tội Lỗi', 'Jezabel', 'https://phimimg.com/upload/vod/20240228-1/3fe989e189ff1ab6bbe4a83537c717a4.jpg', 'https://phimimg.com/upload/vod/20240228-1/46f0cfac0078e9d8015a5fc42816b617.jpg', '<p>Bốn học sinh trung học thượng lưu sống vô tư giữa ma túy, game và tình yêu cho đến khi một trong hai cô gái, Eli, bị giết một cách dã man. Mười sáu năm sau, ký ức về tội ác dày vò Alain, một thành viên khác của nhóm.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Gabriel Agüero","avatar":""},{"name":"Johanna Juliethe","avatar":""},{"name":"Eliane Chipia","avatar":""},{"name":"Shakti Maal","avatar":""},{"name":"Erich Wildpret","avatar":""},{"name":"Diana Volpe","avatar":""},{"name":"María Conchita Alonso","avatar":""},{"name":"Giovanni García","avatar":""},{"name":"Cesar Cova","avatar":""},{"name":"Héctor Manrique","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
