INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-noi-dau-moi', 'Yêu Nơi Đầu Môi', 'Love At First Taste', 'https://phimimg.com/upload/vod/20240229-1/87d18cd396275910b3d7c8b22f6439d9.jpg', 'https://phimimg.com/upload/vod/20240229-1/a2571497a66410fa43235e89bf48681d.jpg', '<p>Bộ phim kể về chuyện tình giữa chàng giám đốc nửa người nửa ma cà rồng Âu Trạch Dã và cô sinh viên năm cuối khoa Biểu diễn học viện Điện ảnh Đồng Tiểu Mạn. Nam chính Âu Trạch Dã bề ngoài là thiên tài về game sát phạt quyết đoán, máu lạnh vô tình, nắm trong tay gia tài kếch xù, nhưng bên trong lại là một chàng trai cưng chiều người yêu, cuồng hôn bất chấp, hay ghen tuông và nhỏ mọn. Nữ chính Đồng Tiểu Mạn là người có vẻ ngoài đáng yêu ngây thơ nhưng thực tế lại hay khẩu nghiệp không khoan nhượng. Hai người nắm tay nhau viết nên câu chuyện tình yêu cấm kỵ giữa con người và ma cà rồng, cùng nhau trải qua cuộc hành trình ngập tràn lãng mạn.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Feifei","avatar":""},{"name":"Pan Yuetong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
