INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-ac-de-anh-dung-yeu', 'Thầm Ác Để Anh Đừng Yêu', 'Devil Sister', 'https://phimimg.com/upload/vod/20240229-1/70bff464e8422cfe4af5e2e9d39f35a2.jpg', 'https://phimimg.com/upload/vod/20240229-1/ffcb9362e4de2230a3997ddcf24d2a47.jpg', '<p>Thầm Ác Để Anh Đừng Yêu - Devil Sister là một câu chuyện tình phi công trẻ - máy bay bà già đầy sự dễ thương và ngọt ngào. Bộ phim hài hước lãng mạn chuyển thể từ tiểu thuyết kể về Irin, một cô nàng đanh đá vẫn chưa quên được người yêu cũ là một chàng bác sĩ thú y. Liệu mọi chuyện sẽ ra sao khi em gái của cô, Inn, lại đang trong quá trình cưa cẩm bạn trai cũ của chị gái. Hơn nữa, càng ngày cô càng nhận ra rằng anh chàng người yêu cũ vẫn còn vương vấn mình.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Metawin Opas-iamkajorn","avatar":""},{"name":"Peechaya Wattanamontree","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
