INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-may-den-gap-trang-sang', 'Khi Mây Đen Gặp Trăng Sáng', 'My Deepest Dream', 'https://phimimg.com/upload/vod/20240228-1/abb74dd4fc6f88bd8cae753c77e12010.jpg', 'https://phimimg.com/upload/vod/20240228-1/c2689dad26e5ad86336aefd462c40484.jpg', '<p>Ô Ngộ và Đàm Giảo gặp nhau trên một chiếc du thuyền du lịch, hai người vừa gặp đã yêu. Sau chuyến du lịch, hai người cùng mất đi một phần trí nhớ, Ô Ngộ quên mất ký ức mấy ngày sau khi chuyến du lịch kết thúc, Đàm Giảo mất đi ký ức gần một năm rưỡi. Ô Ngộ là một học bá phát triển toàn diện, tiền đồ như gấm, nhưng sau chuyến du lịch cuộc đời anh thay đổi kinh thiên động địa, mẹ và em gái của mình bị giết. Vì để tìm ra hung thủ, anh buông bỏ tiền đồ trở thành thợ sửa xe hơi. Đàm Giảo gặp lại anh lúc đến sửa xe, sau đó bỗng cách nửa tháng hai người sẽ xuyên không một lần.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Nhất Đồng","avatar":""},{"name":"Kim Hạn","avatar":""},{"name":"Tăng Khả Ny","avatar":""},{"name":"Vương Tử Duệ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324305);
