INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-the', 'Song Thể', 'Dual', 'https://phimimg.com/upload/vod/20240228-1/baa56de5ad75a97a4dd2308117fde5dc.jpg', 'https://phimimg.com/upload/vod/20240228-1/c08471aec196d6021cb8dae507ec1cd1.jpg', '<p>Một người phụ nữ bị bệnh nan y đã lựa chọn thủ tục nhân bản để giảm bớt sự mất mát cho bạn bè và gia đình của mình. Khi cô ấy hồi phục một cách thần kỳ, nỗ lực của cô ấy để làm cho bản sao của mình ngừng hoạt động đã thất bại và dẫn đến một cuộc đấu tay đôi do tòa án ủy thác cho đến chết.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Karen Gillan","avatar":""},{"name":"Aaron Paul","avatar":""},{"name":"Jesse Eisenberg","avatar":""},{"name":"Beulah Koale","avatar":""},{"name":"Theo James","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
