INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-nu', 'Vệ Nữ', 'Venus', 'https://phimimg.com/upload/vod/20240227-1/4d6d8136c81219c125c34a9cb883671d.jpg', 'https://phimimg.com/upload/vod/20240227-1/51df42bdee459fc3cb0b93807dd3f99a.jpg', '<p>Phim kể về Lucía một cô gái làm trong hộp đêm. Một tối nọ Lucía tan làm sớm và chôm hàng (gói ma túy siêu to siêu khổng lồ) của đại ca xã hội đen quản lý nên bị đánh tơi tả. Cô nàng chạy trốn về nhà chị gái Rocío (hiện đang ở chung với con gái Alba) ở tòa nhà Venus. Tòa nhà ma ám thời hiện đại với những sự mất tích và cái chết bí ẩn của rất nhiều nạn nhân. Chị gái Rocío tận tình chăm sóc Lucía và cho cô nàng ở lại một đêm. Sáng ra, Rocío biến mất, Lucía chăm sóc cháu gái Alba và câu chuyện của chúng ta bắt đầu từ đây. Liệu Lucía có thể thoát khỏi sự truy lùng gắt gao của băng đảng và tìm được người chị gái mất tích. Người chị Rocío mất tích là do băng đản bắt hay còn có ẩn tình gì khác. Tất cả sẽ được giải đáp trong Venus.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Ester Expósito","avatar":""},{"name":"Ángela Cremonte","avatar":""},{"name":"Inés Fernández","avatar":""},{"name":"Magüi Mira","avatar":""},{"name":"Aten Soria","avatar":""},{"name":"María José Sarrate","avatar":""},{"name":"Sofía Reyes","avatar":""},{"name":"Fernando Valdivielso","avatar":""},{"name":"Federico Aguado","avatar":""},{"name":"Francisco Boira","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324305);
