INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('webtoon-doi-toi', 'Webtoon Đời Tôi', 'Today''s Webtoon', 'https://phimimg.com/upload/vod/20240220-1/94819b7aa091ed403964011cf5f3982f.jpg', 'https://phimimg.com/upload/vod/20240220-1/6f46048780afc4234f438f1befe434d6.jpg', '<p>On Ma Eum từng là một vận động viên judo nhưng chấn thương đã buộc cô phải chấm dứt sự nghiệp. Sau đó, cô trở thành biên tập viên tân binh của công ty webtoon Neon. Với người từng xem judo là tất cả cuộc sống thì việc bắt đầu lại từ đầu đã khiến Ma Eum gặp không ít khó khăn.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2022, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Se Jeong","avatar":""},{"name":"Choi Daniel","avatar":""},{"name":"Nam Yoon-Soo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324305);
