INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-viec-mua-he', 'Công Việc Mùa Hè', 'Summer Job', 'https://phimimg.com/upload/vod/20240220-1/1e8377168b66898778f0ff8e7e9cd17b.jpg', 'https://phimimg.com/upload/vod/20240220-1/c803e61b0fd99f77dd8b8878029b8133.jpg', '<p>Mười thí sinh thế hệ Z bước vào kỳ nghỉ trong mơ. Nhưng để có cơ hội ở lại căn biệt thự sang trọng cũng như giành được 100.000 euro, họ phải làm những công việc thực sự.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Matilde Gioli","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324305);
