INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-ki-vanitas', 'Hồi Kí Vanitas', 'Vanitas No Carte, The Case Study Of Vanitas', 'https://phimimg.com/upload/vod/20240220-1/17bd380a3ffca19a111e26ee2a7c32b1.jpg', 'https://phimimg.com/upload/vod/20240220-1/15e1b231531bacc81eab399ef87b1cec.jpg', '<p>Noé Archiviste là một ma cà rồng vùng nông thôn đi tìm kiếm sự thật về cuốn sổ ma thuật có khả năng can thiệp vào tên thật của vampire. Đang trên phi thuyền tới Paris tìm manh mối, cậu bắt gặp Vanitas, một con người tự xưng là bác sĩ chữa bệnh cho vampire, giúp họ thoát khỏi bệnh ma - thứ khiến họ hành xử không theo ý muốn. Trùng hợp thay, cuốn sổ mà Vanitas sử dụng chính là thứ mà Noé đang tìm - cuốn sổ của Vanitas trong câu chuyện cổ tích về Vampire Mặt trăng xanh. Tuy mục đích hơi khác nhau, nhưng cả hai đã quyết định cùng hợp tác chữa bệnh cho nhiều vampire khác, đối đầu với thế lực bí ẩn Charlatan - kẻ đứng sau căn bệnh ma quái ác.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324305);
