INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-da-tan-nuong-2', 'Nhất Dạ Tân Nương 2', 'The Romance Of Hua Rong 2', 'https://phimimg.com/upload/vod/20240220-1/5586b28c5a77ef92847bea08b8f38bb7.jpg', 'https://phimimg.com/upload/vod/20240220-1/634cdb204a431156bc43cc45d665b7e2.jpg', '<p>Hoa Dung và Tần Thượng Thành đã thành thân. Tuy nhiên ngay sau đó, một sắc lệnh của triều đình được ban ra, lệnh cho Hoa Dung thành thân cùng một hoàng tử con tin của vương quốc láng giềng, để làm dịu mối quan hệ giữa hai nước. Hoa Dung và Tần Thượng Thành quyết định đến vương quốc láng giềng để cứu vãn tình hình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Viên Hạo","avatar":""},{"name":"Triệu Chiêu Nghi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324305);
