INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-nguoi-ly-tuong', 'Em Là Người Lý Tưởng', 'Fairy From The Painting', 'https://phimimg.com/upload/vod/20240220-1/6e8af50f923ebbb752517145ac090be4.jpg', 'https://phimimg.com/upload/vod/20240220-1/da060b8a8166c5e5bc28d4b29d5224c6.jpg', '<p>Cố Ngạn Thành người thừa kế của Tập đoàn Cố Thị bị mất khả năng chạm khắc, đã gặp Vũ Huyên người lái xe trông giống như tiên nữ trong truyền thuyết \Tiên nữ bay lên trời\ của gia tộc. Điều kỳ lạ nhất là chỉ cần nhìn thấy Vũ Huyên gặp nguy hiểm, anh ấy sẽ vô thức lao tới, bước tới để bảo vệ. Để xác minh tình cảm của mình với Vũ Huyên và vì thuận tiện cho việc hồi phục năng lực điêu khắc, Ngạn Thành đã sắp xếp Vũ Huyên trở thành tài xế kiêm trợ lý của mình và dọn đến nhà anh sống. Một người tự luyến và bị ám ảnh cưỡng chế quá mức hoàn hảo, còn người kia là một người vô tư cả hai bắt đầu cuộc sống cùng nhau đầy chán ghét nhưng không thể tách rời, và cả hai dần trở nên nhập nhằng trong mối quan hệ của mình khi tình cảm của mọi người đang có những bước tiến nhảy vọt thì Vũ Huyên biết sự thật câu chuyện về \Tiên nữ bay lên trời\ chỉ là một giả tưởng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Peter","avatar":""},{"name":"Wang Mo Han","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324305);
