INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yen-ngu-phu', 'Yên Ngữ Phú', 'The Autumn Ballad', 'https://phimimg.com/upload/vod/20240215-1/6352c9cc3da1beeee867696eae9b136f.jpg', 'https://phimimg.com/upload/vod/20240215-1/3f044daa23cbdc33c502ad4f1ce87f85.jpg', '<p>Kể về câu chuyện đại tiểu thư Thu Yên ít được yêu thương nhất ở Thu phủ bước ra khỏi chốn khuê phòng bằng sự cố gắng và trí tuệ của mình, cẩn thận thăm dò từng vụ án bí ẩn, trăn trở tiến bước trong từng khó khăn, đấu mưu đấu trí, bầu bạn, thấu hiểu vương gia Lương Dực lạnh lùng, nham hiểm, cuối cùng hai người có được hạnh phúc và tình yêu thuộc về mình.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 16, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kiều Hân","avatar":""},{"name":"Lưu Nhuế Lân","avatar":""},{"name":"Từ Chính Khê","avatar":""},{"name":"Hứa Nhã Đình","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324305);
