INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-them-yeu-duong-voi-sep', 'Không Thèm Yêu Đương Với Sếp', 'Legally Romance', 'https://phimimg.com/upload/vod/20240215-1/75a2c8d6704cb69f06b50b5e37c2400c.jpg', 'https://phimimg.com/upload/vod/20240215-1/8864da6ba8a5ea8f3ba2cf7a84997aff.jpg', '<p>Tiền Duy, 28 tuổi là một trợ lý luật sư cấp trên Lục Tuân là bạn học cũ của cô. Tiền Duy nghĩ rằng việc Lục Tuân luôn lạnh lùng chèn ép cô là vì cô đã xúc phạm anh ấy khi còn ở trường, vì vậy cô luôn phàn nàn than trời trách đất, luôn nghĩ cách lấy lòng Lục Tuân để thoát khỏi khó khăn ở nơi làm việc. Nhưng trong một lần hôn mê do tai nạn, Tiền Duy mơ thấy mình năm 19 tuổi và nhận ra rằng thái độ của Luân đối với cô có thể là một cách quan tâm khác. Khi Tiền Duy tỉnh dậy, cô cố gắng đến gần hơn với thế giới nội tâm của Lục Tuân nhận thấy anh ấy là người ngay thẳng và ấm áp, và cô cũng cảm nhận được tình yêu mà anh dành cho mình…</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tao Huang","avatar":""},{"name":"SongZu''er","avatar":""},{"name":"Jin Ze","avatar":""},{"name":"Zhong Lili","avatar":""},{"name":"Li Baihui","avatar":""},{"name":"Yan An","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324306);
