INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('db-cooper-ky-an-khong-tac', 'D.B. Cooper: Kỳ án Không Tặc', 'D.B. Cooper: Where Are You?!', 'https://phimimg.com/upload/vod/20240215-1/dfcfb3cc50b7d313639c2b9177967bf6.jpg', 'https://phimimg.com/upload/vod/20240215-1/d7cb5d941a4b2bc60b26465ad834431a.jpg', '<p>Năm 1971, một không tặc nhảy dù khỏi máy bay cùng túi tiền đánh cắp – rồi tẩu thoát trót lọt. Nhiều thập kỷ sau, danh tính của hắn vẫn là một bí ẩn đầy cuốn hút.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324306);
