INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-gian-am-ap-ben-em', 'Thời Gian Ấm Áp Bên Em', 'Warm Time With You', 'https://phimimg.com/upload/vod/20240215-1/7a4bdacbd4cae199eb19c6263ce8ca8c.jpg', 'https://phimimg.com/upload/vod/20240215-1/08bd3fbf45efb9a2d24a1f05d5a994a3.jpg', '<p>Wu Yi là một cậu bé mồ côi cha mẹ nhưng sống một cuộc sống ấm áp và hạnh phúc với người cô của mình, Wu Jiao Jiao, người điều hành một võ quán. Chú của anh, chủ tịch độc đoán Qi Mo, muốn cha anh gặp đứa cháu trai duy nhất của mình và vì vậy anh bắt đầu cuộc chiến giành quyền nuôi con với Wu Jiao Jiao, một phụ nữ trẻ đầy nhiệt huyết và sẽ không dễ dàng từ bỏ.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Dai Gaozheng","avatar":""},{"name":"Ley","avatar":""},{"name":"Zhao Tiange","avatar":""},{"name":"Zhang Yanbo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324306);
