INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-vay-thi-ayumu-van-se-tiep-can', 'Dù Vậy Thì Ayumu Vẫn Sẽ Tiếp Cận', 'Soredemo Ayumu Wa Yosetekuru When Will Ayumu Make His Move?', 'https://phimimg.com/upload/vod/20240215-1/92100b5437514b74b347cbc4d755e433.jpg', 'https://phimimg.com/upload/vod/20240215-1/bd524da95d4ac900235f69c760557896.jpg', '<p>Tanaka Ayumu, một kỳ thủ cờ Shogi tập sự vì phải lòng Yaotome Urushi mà gia nhập câu lạc bộ cờ Shogi. Tuy có ý muốn Sẽ tỏ tình với tiền bối nếu giành chiến thắng nhưng thực lực của cậu ấy lại chẳng có mấy. Tuy vậy, trước tư thế tấn công đầy nghị lực của Ayumu mà Urushi lại thấy vô cùng lo lắng. Tại câu lạc bộ cờ vua nơi chỉ có hai thành viên, dù là trên bàn cờ hay không thì cuộc tranh chấp vẫn đang được diễn ra. Công chuyện tình hài hước được viết bởi Yamamoto Souichirou, tác giả của bộ Nhất quỷ nhì ma, thứ ba Takagi.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 17, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324306);
