INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-muon-lam-anh-em-voi-cau', 'Tôi Muốn Làm Anh Em Với Cậu', 'I Want To Be Brothers With You', 'https://phimimg.com/upload/vod/20240215-1/d7e0444349ae9fa11ccd13302a9301ce.jpg', 'https://phimimg.com/upload/vod/20240215-1/495ad82e1a5332ad20287bafd927a01a.jpg', '<p>Gao Yang và cha của anh ấy từ nhỏ đã không giao dịch với nhau, Gao Bin một mình nuôi nấng con trai của mình, nhưng Gao Yang và cha của anh ấy không lớn không nhỏ. Anh trốn học trong ba ngày và chiến đấu trong năm ngày, điên cuồng kiểm tra giới hạn chịu đựng của giáo viên và cha mình đối với anh. Mặc dù con gái của hiệu trưởng Jin Beibei có ấn tượng tốt với anh ta, anh ta chạy theo Ban Hua, và khi Ban Hua rời đi, trái tim của anh ta cũng bay về Bắc Kinh.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xin Yunlai","avatar":""},{"name":"Chen Youwei","avatar":""},{"name":"Lu Fangsheng","avatar":""},{"name":"Zhao Zhaoyi","avatar":""},{"name":"Liu Jinyan","avatar":""},{"name":"Yang Yikai","avatar":""},{"name":"Li Ao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324306);
