INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-ma-pha-an', 'Bắt Ma Phá Án', 'From Now On, Showtime!', 'https://phimimg.com/upload/vod/20240205-1/ff2a20333adcabe2146ab9b6b514bc93.jpg', 'https://phimimg.com/upload/vod/20240205-1/ba88913f6abaf04d9a446e7953d49c11.jpg', '<p>Cha Woong là một ảo thuật gia nổi tiếng với kỹ năng biểu diễn các trò ảo thuật như ma thuật. Anh có một bí mật lớn là có thể nhìn thấy ma và giao tiếp với chúng. Bằng khả năng của mình, Cha Woong đã hợp tác cùng nữ cảnh sát Go Seul Hae để phá những vụ án nhờ vào sự giúp đỡ của những hồn ma.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Hae Jin","avatar":""},{"name":"Jin Ki Joo","avatar":""},{"name":"Jung Joon Ho","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324306);
