INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-nga-tuoi-thanh-xuan', 'Bản Ngã Tuổi Thanh Xuân', 'Bản Ngã Tuổi Thanh Xuân', 'https://phimimg.com/upload/vod/20240205-1/9a47ac6c5a621ecc19eb0c310221ac78.jpg', 'https://phimimg.com/upload/vod/20240205-1/b3fc42d01c960129bc1ce4c1d13a3dd6.jpg', '<p>Trung học là thời kỳ thanh xuân nhất, nhiệt huyết nhất, đồng thời cũng gây hoang mang nhất. Cuộc sống học đường có vẻ vô tư, nhưng mỗi học sinh đều có vấn đề của riêng mình. Nữ sinh Hà Thiên Thiên bị rối loạn cảm xúc do ba mẹ muốn ly dị, Diệp Mẫn Nhi muốn ứng cử vị trí trưởng học sinh nữ nhưng bị bạn bè cô lập, tẩy chay. Trần Đình, Nghê Vận Địch, Hồ Hiểu Cương, Mạch Lạc Khắc, Diệp Á Trì cũng có những chuyện buồn phiền đến từ gia đình, tình yêu, tình bạn. Liệu giáo viên phụ đạo tâm lý mới đến - Uông Thiện Mỹ, cùng các thầy cô trong học viện Thanh Xuân sẽ làm gì để giúp đỡ các em học sinh can đảm đối mặt và vượt qua?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 14, 2022, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Viêm Minh Hy","avatar":""},{"name":"Diêu Trác Phi","avatar":""},{"name":"Hà Tấn Lạc","avatar":""},{"name":"Trương Trì Hào","avatar":""},{"name":"Chung Nhu Mỹ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324306);
