INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-va-am-muu-2', 'Tình Yêu Và Âm Mưu 2', 'Plot Love 2', 'https://phimimg.com/upload/vod/20240205-1/6c01b33c12befef1fbe025ab394f34ce.jpg', 'https://phimimg.com/upload/vod/20240205-1/93bd0dd446fbb9f72f161714df7d70b0.jpg', '<p>Tô Bắc là nhà thiết kế thời trang của công ty Tang Lan, vì công ty của bố đang đứng bên bờ vực phá sản nên cô phải gả cho một ông chủ lớn chưa từng quen biết, lại không ngờ ông chủ lớn này lại là CEO Lộ Nam của tập đoàn Hoán Trăn. Vì muốn mau chóng được tiếp quản công ty, dưới sự bày mưu tính kế của bà nội Lộ Nam tìm được Tô Bắc, cô gái từng đính hôn với mình lúc nhỏ, cũng cùng Tô Bắc ký hợp đồng vợ chồng, không can thiệp vào cuộc sống của nhau. Ngày qua ngày chung sống hai người đã nảy sinh tình cảm sâu đậm, nhưng sóng gió ồ ạt kéo đến khi em gái cùng cha khác mẹ của Tô Bắc là Tô Mạn Ny lại có ý đồ bất chính với Lộ Nam, đồng thời cô em gái Lộ Phỉ Nhi trông như ngoan ngoan của Lộ Nam dường như cũng có tình cảm khác thường với anh trai mình. Người trợ lý thân cận vẫn luôn trung thành lại có dụng ý khác, người bà từng thích Tô Bắc cũng vì chuyện cô không muốn từ chức để mang thai mà dần xa cách.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Thù Quân","avatar":""},{"name":"Trần Phẩm Diên","avatar":""},{"name":"Tôn Hiểu Luân","avatar":""},{"name":"Lưu Hân Lôi","avatar":""},{"name":"Thái Tường Vũ","avatar":""},{"name":"Kỳ Lăng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324306);
