INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-gap-go-ngot-ngao', 'Cuộc Gặp Gỡ Ngọt Ngào', 'Meet Cute', 'https://phimimg.com/upload/vod/20240220-1/7a9ec37b55e56e3e2a68eb7d1c052fe7.jpg', 'https://phimimg.com/upload/vod/20240220-1/ab3d4f7f52cf92a3c2e89ef05814b48e.jpg', '<p>tiếp nối câu chuyện của Sheila (Kaley Cuoco) và Gary (Pete Davidson). Khi họ gặp nhau, đó là tình yêu sét đánh - cho đến khi chúng tôi nhận ra cuộc hẹn kỳ diệu của họ hoàn toàn không phải là định mệnh. Sheila có một cỗ máy thời gian, và họ đã yêu nhau hết lần này đến lần khác. Nhưng khi một đêm hoàn hảo không bao giờ là đủ, Sheila du hành về quá khứ của Gary để thay đổi anh ta thành người đàn ông hoàn hảo.</p>', 'Full', 1, 'single', 'completed', 5, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kaley Cuoco","avatar":""},{"name":"Pete Davidson","avatar":""},{"name":"Kevin Corrigan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324306);
