INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('slr', 'SLR', 'SLR', 'https://phimimg.com/upload/vod/20240220-1/2654e18637abcdf80b5d35726eb91cec.jpg', 'https://phimimg.com/upload/vod/20240220-1/662ce334678c111bd2974ccfc9bf515c.jpg', '<p>Dan một sinh viên trẻ của Khoa Nhiếp ảnh. người đã thi Luận văn với Giáo sư Em trong một năm Nhưng mọi chuyện vẫn chưa kết thúc cho đến khi cuối cùng Giáo sư Em trao một máy ảnh SLR cho Dan để có tác phẩm tốt nhất. Dan sắp khám phá ra rằng Đó là một bài kiểm tra từ việc sinh nở ám ảnh trong máy ảnh SLR. mà anh ta không có lối thoát Trừ khi bạn phải chọn có chấp nhận nó hay không. hoặc sẽ chiến đấu với nó Và anh ta sắp kéo bạn gái và bạn bè của mình Nam và Great vào một số phận đáng sợ. mà cũng bị bao vây bởi cái chết từ chiếc máy ảnh này.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Nanon Korapat Kirdpan","avatar":""},{"name":"Sadanont Durongkhaweroj","avatar":""},{"name":"Nophand Boonyai","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324306);
