INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-cuu-long-huyen-quan', 'Địch Nhân Kiệt: Cửu Long Huyền Quán', 'Nine Dragons Mysterious Coffin', 'https://phimimg.com/upload/vod/20240220-1/aaa2db447b3f60c35300a87e8a121e0d.jpg', 'https://phimimg.com/upload/vod/20240220-1/35a3a325fb2891cc46aaafd3e90ac449.jpg', '<p>Dưới thời trị vì của Diệc Phàm, một nhóm trộm mộ đã đào được một quan tài ăn thịt người bí ẩn, con rồng vàng lao lên từ trong quan tài, quan tài ăn thịt người bay vào đại điện khiến người ta kinh ngạc. Địch Nhân Kiệt được lệnh điều tra và phát hiện ra rằng những thây ma nghiện ăn thịt người và không sợ kiếm sĩ có liên quan đến gia đình của Vương hậu, người đã bị đày đến Lĩnh Nam hai mươi năm trước. Đêm hội rồng và phượng, nơi mọi người thưởng thức những chiếc đèn lồng, âm thanh kỳ lạ của sáo bay lơ lửng trên bầu trời Trường An, những thây ma bò xuất hiện, tấn công mọi người. Địch Nhân Kiệt và Lí Lăng Vi dẫn quân chiến đấu với thây ma, nhưng binh lính của thành ngày càng ít đi. Thây ma càng lúc càng nhiều, cách duy nhất là đợi đến bình minh, cho lũ thây ma đốt mình dưới nắng, nhưng họ có thể cầm cự được không?</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"KK","avatar":""},{"name":"Li Zhen An","avatar":""},{"name":"Michelle Ye","avatar":""},{"name":"Zhang Hao Cheng","avatar":""},{"name":"Lou Xue Xian","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324306);
