INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-tre-mo-coi-2-nan-nhan-dau-tien', 'Đứa Trẻ Mồ Côi 2: Nạn Nhân Đầu Tiên', 'Orphan: First Kill', 'https://phimimg.com/upload/vod/20240219-1/dc2f79a92d42463ddbda67d48f021a68.jpg', 'https://phimimg.com/upload/vod/20240219-1/cfc0658a726e752d0c41d15086ea2e07.jpg', '<p>Đứa Trẻ Mồ Côi 2: Nạn Nhân Đầu Tiên Orphan: First Kill 2022 Full HD Vietsub Thuyết Minh Câu chuyện đáng sợ của Esther tiếp tục trong phần tiền truyện ly kỳ này cho đến bản gốc và bộ phim kinh dị gây sốc Orphan. Sau khi dàn xếp một cuộc trốn thoát tuyệt vời khỏi một cơ sở tâm thần ở Estonia, Esther đến Mỹ bằng cách đóng giả con gái bị mất tích của một gia đình giàu có. Tuy nhiên, một bước ngoặt bất ngờ nảy sinh khiến cô phải chống lại một người mẹ, người sẽ bảo vệ gia đình cô khỏi đứa con bị sát hại bằng bất cứ giá nào.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Isabelle Fuhrman","avatar":""},{"name":"Julia Stiles","avatar":""},{"name":"Rossif Sutherland","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324306);
