INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mafia-mumbai-canh-sat-va-the-gioi-ngam', 'Mafia Mumbai: Cảnh Sát Và Thế Giới Ngầm', 'Mumbai Mafia: Police Vs The Underworld', 'https://phimimg.com/upload/vod/20240219-1/06ef65ec27a2ee4d615590b60c0b254d.jpg', 'https://phimimg.com/upload/vod/20240219-1/bc637cdc7ad4a0047fa74fd15c6722d8.jpg', '<p>Những năm 1990 ở Mumbai, một trùm tội phạm và mạng lưới của hắn nắm quyền kiểm soát toàn thành phố. Rồi xuất hiện cảnh sát đột kích ngang nhiên hạ sát mục tiêu.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324306);
