INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('le-hoi-jazz-cau-chuyen-new-orleans', 'Lễ Hội Jazz: Câu Chuyện New Orleans', 'Jazz Fest: A New Orleans Story', 'https://phimimg.com/upload/vod/20240219-1/a623e00da5d313c0f14903a789a7bb01.jpg', 'https://phimimg.com/upload/vod/20240219-1/0d5231ee1b6ae73d0821eff6d26d769e.jpg', '<p>Bộ phim tài liệu này kết hợp các buổi biểu diễn trực tiếp và các cuộc phỏng vấn từ lễ kỷ niệm 50 năm của lễ hội mang tính biểu tượng, với sự góp mặt của một số tên tuổi lớn nhất trong ngành công nghiệp âm nhạc, cùng với vô số cảnh quay tài liệu lưu trữ từ nửa thế kỷ qua. Bộ phim này không chỉ ghi lại lễ hội âm nhạc với tất cả vẻ đẹp, sự điên rồ và vinh quang của nó mà còn đi sâu vào nền văn hóa phong phú của The Big Easy.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Springsteen","avatar":""},{"name":"Jimmy Buffett","avatar":""},{"name":"Katy Perry","avatar":""},{"name":"Gregory Porter","avatar":""},{"name":"Pitbull","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324306);
