INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sebastian-maniscalco-la-toi-a', 'Sebastian Maniscalco: Là Tôi À?', 'Sebastian Maniscalco: Is It Me?', 'https://phimimg.com/upload/vod/20240219-1/b24ca84e74e36e8edc790aebb5e6e44d.jpg', 'https://phimimg.com/upload/vod/20240219-1/ff2b3d3bedf8898929fd429e04c23ccc.jpg', '<p>Trong chương trình hài độc thoại sống động này, Sebastian bức xúc về những nỗi khổ nhỏ nhặt trong cuộc sống, từ đưa con đến trường, chó được thả rông đến những tối hẹn hò với vợ.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sebastian Maniscalco","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324306);
