INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ao-thuat-su-2', 'Đại Ảo Thuật Sư 2', 'The Great Illusionist 2', 'https://phimimg.com/upload/vod/20240219-1/87ef062df0380f016284ceec93c95a8a.jpg', 'https://phimimg.com/upload/vod/20240219-1/bf055564769e40f40d6ab008137738c5.jpg', '<p>Vào năm 1932, tại thành phố Bắc Hải xảy ra hàng loạt vụ án mạng kỳ lạ, trong quá trình điều tra, cảnh sát điều tra Long Thông phát hiện kẻ sát nhân dùng ảo giác giết người dưới lốt yêu ma. Cuối cùng, với sự giúp đỡ của nữ phóng viên Hoa Linh, Long Thông đã đưa được thủ phạm ra trước công lý, nhưng sự thật đằng sau đó khiến anh khó lòng chấp nhận...</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'VietSub', 'HD', 'Trung Quốc', 0, '[{"name":"Tiền Tiểu Hào","avatar":""},{"name":"Silvio","avatar":""},{"name":"Yu Li","avatar":""},{"name":"Guan Xiang Yun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324306);
