INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tin-chet', 'Bản Tin Chết', 'The Anchor', 'https://phimimg.com/upload/vod/20240219-1/8877f383ecf6ca0294f716ae1d715a4f.jpg', 'https://phimimg.com/upload/vod/20240219-1/ac2878453d64d47511467dbb89baa2f6.jpg', '<p>Khi người phụ nữ mỏ neo Sera nhận được tin báo rằng người mách nước sắp bị giết, cô ấy đi ra ngoài để báo cáo, chỉ để tìm thấy người phụ nữ mách nước và thi thể của con gái mình. Với một báo cáo độc quyền về trường hợp này, cô ấy củng cố vị trí của mình tại nhà ga. Tuy nhiên, cô bắt đầu mắc chứng ảo giác và mắc lỗi trên truyền hình trực tiếp và vai trò người phụ trách chính của cô bị đe dọa.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 1, '[{"name":"Chun Woo-hee","avatar":""},{"name":"Shin Ha-kyun","avatar":""},{"name":"Lee Hye-young","avatar":""},{"name":"Park Ji-hyun","avatar":""},{"name":"Cha Rae-hyung","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324306);
