INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-trai-tan-bien-chi-do-tinh', 'Liêu Trai Tân Biên Chi Độ Tình', 'The Love Of The Ferry: New Legend Of Liao Zhai', 'https://phimimg.com/upload/vod/20240219-1/e0e583d28f11266168225462822088db.jpg', 'https://phimimg.com/upload/vod/20240219-1/1a9c4750a61b6931cc882507a3b7d5b3.jpg', '<p>Chàng thư sinh Vương Văn quen biết được cô gái ở thanh lâu Nha Đầu hai người tâm đầu ý hợp. Vương Văn tình cờ phát hiện ra thân phận của hồ ly của tú bà, may mắn thay, Nha Đầu đã giúp anh trốn thoát. Sau đó, Nha Đầu bị tú bà ngược đãi Vương Vă rất đau buồn. Nhiều năm sau, Vương Văn và con trai của mình là Vương Tử đã giải cứu Nha Đầu, đánh bại tú bà, và gia đình đoàn tụ.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Daixin Guo","avatar":""},{"name":"Yang Lan","avatar":""},{"name":"Ziqiao Song","avatar":""},{"name":"Tu Yu Ming","avatar":""},{"name":"AL WAI","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324306);
