INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-dau-la-sau-rieng-tien-sinh', 'Tình Đầu Là Sầu Riêng Tiên Sinh', 'Mr. Durian', 'https://phimimg.com/upload/vod/20240126-1/12cd142ed94a30f1eb41eb70b1a5c952.jpg', 'https://phimimg.com/upload/vod/20240126-1/a8cb16fd9728faecbe6ebec45b4fa270.jpg', '<p>Một lời nói dối, Dịch Hướng Noãn biến mất năm năm, khi xuất hiện trở lại, bạn trai cũ của cô là Tô Trầm đã mang một chiếc nhẫn làm lễ gặp mặt? Anh ngoài mặt đe dọa sẽ trả thù, nhưng tại sao cuộc sống sau hôn nhân lại khác với những gì anh nói? Mặc dù bề ngoài Tô Trầm lạnh lùng với Dịch Hướng Noãn, nhưng anh lại giấu kín sự quan tâm của mình dành cho Dịch Hướng Noãn vào tận đáy lòng.Còn cô chỉ muốn đưa kẻ hãm hại nhà họ Dịch ra chịu tội trước pháp luật. Cô vùi đầu tìm kiếm sự thật nhưng lại rơi vào một vòng xoáy nguy hiểm hơn, sau khi trải qua nhiều gian nan,và sau khi điều tra rõ sự thật, mối quan hệ giữa hai người dần bình thường trở lại...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Hâm Đình","avatar":""},{"name":"Ngu Y Kiệt","avatar":""},{"name":"Hoa Văn","avatar":""},{"name":"Vương Triều Dương","avatar":""},{"name":"Lữ Chiêu","avatar":""},{"name":"Trần Ổn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324306);
