INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hao-quang-phan-1', 'Hào Quang (Phần 1)', 'Halo (Season 1)', 'https://phimimg.com/upload/vod/20240301-1/016c91f915d739f4199275400bf3a456.jpg', 'https://phimimg.com/upload/vod/20240301-1/981bbd71362d2c1ad1a8f64d69cad7bc.jpg', '<p>Halo (2022) bộ phim được lấy ý tưởng từ trò chơi cùng tên, bối cảnh diễn ra ở thế kỷ 26 khi vũ trụ được đẩy mạnh khai phá và sự xuất hiện của những dấu hiệu sống ngoài con người được biết đến. Lúc này người ngoài hành tinh đến Trái Đất mang theo ý định xâm lược, đe doạ sự tồn vong của toàn nhân loại.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 7, 2022, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Pablo Schreiber","avatar":""},{"name":"Natascha McElhone","avatar":""},{"name":"Joseph Morgan","avatar":""},{"name":"Shabana Azmi","avatar":""},{"name":"Christina Bennington","avatar":""},{"name":"Natasha Culzac","avatar":""},{"name":"Olive Gray","avatar":""},{"name":"Yerin Ha","avatar":""},{"name":"Bentley Kalu","avatar":""},{"name":"Kate Kennedy","avatar":""},{"name":"Charlie Murphy","avatar":""},{"name":"Fiona O''Shaughnessy","avatar":""},{"name":"Cristina Rodlo","avatar":""},{"name":"Danny Sapani","avatar":""},{"name":"Jen Taylor","avatar":""},{"name":"Viktor Åkerblom","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324306);
