INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-hoa-binh', 'Cây Hòa Bình', 'Trees Of Peace', 'https://phimimg.com/upload/vod/20240207-1/216165d89e36a3780ed595a6139f27be.jpg', 'https://phimimg.com/upload/vod/20240207-1/3fc32bae2ff96746cbbb3a8b0497e730.jpg', '<p>Có xuất thân khác nhau, bốn phụ nữ trở thành những người chị em gắn bó khi bị mắc kẹt và ẩn náu trong cuộc diệt chủng ở Rwanda. Dựa trên các sự kiện có thật.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eliane Umuhire","avatar":""},{"name":"Charmaine Bingwa","avatar":""},{"name":"Ella Cannon","avatar":""},{"name":"Bola Koleosho","avatar":""},{"name":"Tongayi Chirisa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324306);
