INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-vi-bao-nguoc', 'Hành Vi Bạo Ngược', 'The Violence Action', 'https://phimimg.com/upload/vod/20240207-1/6dbc1dcae305dcae5775269be1c743eb.jpg', 'https://phimimg.com/upload/vod/20240207-1/ea963ae845becbf7fadf60223f92591e.jpg', '<p>Ban ngày, cô chỉ là sinh viên đại học bình thường, ưa nhìn. Nhưng khi đêm xuống, cô là sát thủ bán thời gian và sắp sửa đối mặt với mục tiêu khó nhằn nhất từ trước đến nay.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hashimoto Kanna","avatar":""},{"name":"Sugino Yosuke","avatar":""},{"name":"Suzuka Ouji","avatar":""},{"name":"Baba Fumika","avatar":""},{"name":"Morisaki Win","avatar":""},{"name":"Shunsuke Daito","avatar":""},{"name":"Ota Yuri","avatar":""},{"name":"Sato Jiro","avatar":""},{"name":"Shirota Yu","avatar":""},{"name":"Takahashi Katsunori","avatar":""},{"name":"Okamura Takashi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324306);
