INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-giac-noi-buon', 'Tam Giác Nỗi Buồn', 'Triangle Of Sadness', 'https://phimimg.com/upload/vod/20240205-1/b4d946320541442e74cb8e929226ff8c.jpg', 'https://phimimg.com/upload/vod/20240205-1/237d0e1b34f26e3ef37db6d5565860f8.jpg', '<p>Người mẫu Carl và Yaya đang điều hướng thế giới thời trang trong khi khám phá ranh giới của mối quan hệ của họ. Cặp đôi được mời tham gia một chuyến du ngoạn sang trọng với phòng trưng bày của những hành khách siêu giàu, một nhà tài phiệt người Nga, những tay buôn vũ khí người Anh và một thuyền trưởng có phong cách riêng, nghiện rượu, trích dẫn Marx. Lúc đầu, tất cả đều có vẻ Instagramizable. Nhưng một cơn bão đang ập đến và các hành khách bị say sóng nặng trong bữa tối dành cho thuyền trưởng bảy món. Hành trình kết thúc một cách thảm khốc. Carl và Yaya thấy mình bị mắc kẹt trên một hòn đảo sa mạc với một nhóm tỷ phú và một trong những người dọn dẹp con tàu. Hệ thống phân cấp đột nhiên bị đảo lộn, vì quản gia là người duy nhất biết câu cá.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harris Dickinson","avatar":""},{"name":"Charlbi Dean","avatar":""},{"name":"Woody Harrelson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324306);
