INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dog', 'Dog', 'Dog', 'https://phimimg.com/upload/vod/20240207-1/04455747497d611c4a22c7e3317e9317.jpg', 'https://phimimg.com/upload/vod/20240207-1/dbd9355431ee6395a944de9b04dc0338.jpg', '<p>Hai cựu kiểm lâm viên được ghép đôi với ý muốn của họ trong chuyến đi đường bộ của một đời. Quân đội Ranger Briggs (Channing Tatum) và Lulu (một con chó Malinois Bỉ) khóa vào một chiếc Ford Bronco năm 1984 và chạy xuống bờ biển Thái Bình Dương với hy vọng biến nó thành một đám tang của một người lính đúng giờ. Trên đường đi, họ sẽ lái xe hoàn toàn điên rồ, phá vỡ một số ít luật, trốn tránh sự chết hẹp và học cách buông bỏ những người bảo vệ của họ để có cơ hội chiến đấu để tìm thấy hạnh phúc.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324306);
