INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuc-vu-nhan-dan', 'Phục Vụ Nhân Dân', 'Serve The People', 'https://phimimg.com/upload/vod/20240207-1/7b726ed29262d3c77f573229bff67b8e.jpg', 'https://phimimg.com/upload/vod/20240207-1/1c413180adc0304800485864b6d3453f.jpg', '<p>Mu-kwang tình nguyện trở thành cảnh sát bếp của Sa-taek, chỉ huy sư đoàn, với ước mơ thành công. Một ngày nọ, Mu-kwang tình cờ gặp Su-ryeon, người vợ trẻ và xinh đẹp của chỉ huy. Chẳng bao lâu, anh ấy cảm thấy bị cô ấy thu hút mạnh mẽ.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yeon Woo-jin","avatar":""},{"name":"Ji An","avatar":""},{"name":"Cho Seong-ha","avatar":""},{"name":"Jeong Gyu-su","avatar":""},{"name":"Kim Ji-chul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324306);
