INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kimi', 'Kimi', 'Kimi', 'https://phimimg.com/upload/vod/20240207-1/0c22fbc496db7c1b5b19aadb0916786a.jpg', 'https://phimimg.com/upload/vod/20240207-1/4c7414f88237e11148cf5ff85e2f53cd.jpg', '<p>Một nhân viên công nghệ mắc chứng sợ hãi kinh hoàng đã phát hiện ra bằng chứng được ghi lại về một tội ác bạo lực nhưng đã gặp phải sự phản kháng khi cô ấy cố gắng khai báo. Đi tìm công lý, cô ấy phải làm điều mà cô ấy sợ nhất: cô ấy phải rời khỏi căn hộ của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Soderbergh","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324306);
