INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ganh-nang-ngan-can-cua-tai-nang-kiet-xuat', 'Gánh Nặng Ngàn Cân Của Tài Năng Kiệt Xuất', 'The Unbearable Weight Of Massive Talent', 'https://phimimg.com/upload/vod/20240207-1/e47af409ed011d0cd65c863fa5a77a72.jpg', 'https://phimimg.com/upload/vod/20240207-1/3313339a77b0f72fca3785fa3c915aaf.jpg', '<p>Sáng tạo không đạt yêu cầu và đối mặt với sự điêu đứng về tài chính, Nick Cage phải chấp nhận lời đề nghị trị giá 1 triệu USD để tham dự sinh nhật của một siêu fan nguy hiểm. Mọi thứ trở nên vô cùng bất ngờ khi Cage được một đặc nhiệm CIA tuyển dụng và buộc phải sống theo huyền thoại của chính mình, chuyển thể các nhân vật trên màn ảnh mang tính biểu tượng và được yêu thích nhất của anh ấy để cứu chính mình và những người thân yêu của anh ấy.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Pedro Pascal","avatar":""},{"name":"Neil Patrick Harris","avatar":""},{"name":"Tiffany Haddish","avatar":""},{"name":"Lily Mo Sheen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324306);
