INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-muc-stu', 'Linh Mục Stu', 'Father Stu', 'https://phimimg.com/upload/vod/20240207-1/dd6f40333a4e5bb01e4202b67ca6cd78.jpg', 'https://phimimg.com/upload/vod/20240207-1/f43f993a1c2f0fe28a44e74db6b452a1.jpg', '<p>Tiếp nối cuộc đời của Cha Stuart Long, một võ sĩ quyền anh, người đã truyền cảm hứng cho vô số người trong cuộc hành trình từ tự hủy diệt đến cứu chuộc. Sau khi sống sót sau một vụ tai nạn xe máy, một cựu võ sĩ quyền anh và người theo thuyết bất khả tri lâu năm bắt đầu tự hỏi liệu anh ta có thể sử dụng cơ hội thứ hai để giúp đỡ người khác hay không, dẫn đến nhận ra đáng ngạc nhiên rằng anh ta muốn trở thành một linh mục Công giáo.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 1, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Mel Gibson","avatar":""},{"name":"Jacki Weaver","avatar":""},{"name":"Teresa Ruiz","avatar":""},{"name":"Malcolm McDowell","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324306);
