INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('niem-tin-giang-sinh', 'Niềm Tin Giáng Sinh', 'I Believe In Santa', 'https://phimimg.com/upload/vod/20240207-1/6fb823ae14cf026bbb39338d70da3b1e.jpg', 'https://phimimg.com/upload/vod/20240207-1/f10e8d29e9331d30f55c5e5908641c7f.jpg', '<p>Sau 5 tháng hạnh phúc hẹn hò với Tom, Lisa bàng hoàng nhận ra anh bị ám ảnh với dịp lễ mà cô không ưa nhất. Có phải đã đến lúc cho Giáng sinh một cơ hội khác?</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christina Moore","avatar":""},{"name":"John Ducey","avatar":""},{"name":"Violet McGraw","avatar":""},{"name":"Lateefah Holder","avatar":""},{"name":"Sachin Bhatt","avatar":""},{"name":"Matthew Glave","avatar":""},{"name":"Paxton Booth","avatar":""},{"name":"Brooke Dillman","avatar":""},{"name":"Missi Pyle","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324306);
