INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-thau', 'Nhà Thầu', 'The Contractor', 'https://phimimg.com/upload/vod/20240205-1/556f560c7023b72a5a6071c3f5f6fe13.jpg', 'https://phimimg.com/upload/vod/20240205-1/c85ba255efd0a642a78b8953f9257b52.jpg', '<p>Nhà Thầu xoay quanh câu chuyện bị quân đội loại vì vấn đề sức khỏe, cựu Trung sĩ của Lực lượng Đặc nhiệm Hoa Kỳ James Harper sớm gặp khó về vấn đề tài chính, anh đã mạo hiểm tất cả mọi thứ của mình để trở thành một kẻ đánh thuê.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Pine","avatar":""},{"name":"Florian Munteanu","avatar":""},{"name":"Gillian Jacobs","avatar":""},{"name":"Ben Foster","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324306);
