INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('glorious', 'Glorious', 'Glorious', 'https://phimimg.com/upload/vod/20240205-1/0468f03a23c9e11a76a17146672dccd6.jpg', 'https://phimimg.com/upload/vod/20240205-1/146a787b19ece4a24093d93dbc5ab1f2.jpg', '<p>Sau khi chia tay, Wes kết thúc ở một bến đỗ xa xôi. Anh ta thấy mình bị nhốt trong phòng tắm với một nhân vật bí ẩn đang nói chuyện từ một quầy hàng liền kề. Chẳng bao lâu Wes nhận ra mình đang tham gia vào một tình huống khủng khiếp hơn những gì anh có thể tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"J.K. Simmons","avatar":""},{"name":"Ryan Kwanten","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324306);
