INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-toi', 'Bóng Tối', 'Darkling (Mrak)', 'https://phimimg.com/upload/vod/20240205-1/888fb4fac7e9ee7acb3b611eb615974f.jpg', 'https://phimimg.com/upload/vod/20240205-1/2dc4f2b045b356f54a9c728ded757bf5.jpg', '<p>Ở Kosovo do NATO chiếm đóng, một cô bé viết bài luận cho Liên Hợp Quốc về người cha đã mất tích. Trong khi đó, ông nội của cô gái ngày càng trở nên hoang tưởng về những mối đe dọa vô hình rình rập trong bóng tối. Dựa trên một câu chuyện có thật.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danica Curcic","avatar":""},{"name":"Darren Pettie","avatar":""},{"name":"Slavko Stimac","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324306);
