INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('amandla', 'Amandla', 'Amandla', 'https://phimimg.com/upload/vod/20240205-1/d3bef7501364b5093b7e4b7c1a5fcb10.jpg', 'https://phimimg.com/upload/vod/20240205-1/8dfe636b389598868d1b1ce06970d85a.jpg', '<p>Nhiều năm sau khi thoát được bi kịch thời thơ ấu, hai anh em giờ ở hai đầu luật pháp khi vụ tội phạm dính đến băng đảng thử thách lòng trung thành giữa họ.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Lemogang Tsipa","avatar":""},{"name":"Thabiso Masoti","avatar":""},{"name":"Thabo Rametsi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324306);
