INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-thoi-den-nam-hai-quy-hu', 'Ma Thổi Đèn: Nam Hải Quy Hư', 'Ghost Blowing Lantern In The South China Sea', 'https://phimimg.com/upload/vod/20240205-1/1807c218cfc89ed0496ce8307de68f9a.jpg', 'https://phimimg.com/upload/vod/20240205-1/396b867960480cc935d7a35ebe1f8446.jpg', '<p>Nam Hải Quy Khư là bộ phim đầu tiên kể về câu chuyện của nhóm đào mộ của đội trưởng Hồ Bát Nhất. Sau khi rửa tay gác kiếm, họ hỗ trợ người bạn của mình là chú Minh đi đến Biển Đông để trục vớt ngọc trai. Di tích của một quốc gia ngàn năm tuổi, họ đã trải qua biết bao gian khổ và nguy hiểm dưới đáy biển. Cuối cùng họ đoàn kết và hợp tác để đánh bại những con quái vật khổng lồ dưới biển sâu, cũng như tận dụng những thiết bị cơ quan có trong di tích để tìm đường sống sót.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nick","avatar":""},{"name":"Leo","avatar":""},{"name":"Nita","avatar":""},{"name":"Han Yezhou","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324306);
