INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-dai-armageddon', 'Thời Đại Armageddon', 'Armageddon Time', 'https://phimimg.com/upload/vod/20240123-1/5381a7ed1fb87f982f58a8d61433ddad.jpg', 'https://phimimg.com/upload/vod/20240123-1/2a34235af3a8e7d62d3306a57808f3c1.jpg', '<p>Năm 1980, Queens, New York, một cậu bé Do Thái trẻ tuổi kết bạn với một người bạn học người Mỹ gốc Phi nổi loạn trước sự phản đối của gia đình đặc quyền của anh ta và bắt đầu tính đến việc lớn lên trong một thế giới bất bình đẳng và định kiến.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Banks Repeta","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Jeremy Strong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324306);
