INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-quan-tai-thuong-nguoi-tinh-vuot-thoi-gian', 'Tướng Quân Tại Thượng - Người Tình Vượt Thời Gian', 'Oh My General - Love Across Time', 'https://phimimg.com/upload/vod/20240123-1/518982b58a4d32898cbe2c81888aea05.jpg', 'https://phimimg.com/upload/vod/20240123-1/74d354e8ef2ab4f0c5ed21c1a9120952.jpg', '<p>Tướng quân tại thượng: Người tình vượt thời gian - Oh My General: Love Across Time là bộ truyện tranh thuộc thể loại tâm lý, tình cảm, chính kịch, giả tưởng của Trung Quốc. Tác phẩm do đạo diễn Ye Tian chịu trách nhiệm chỉ đạo, với sự tham gia của các diễn viên Wang Churan và Li Jiulin.Để bảo vệ nhà Tống, Liu Xiyin đã kích động vào cuộc xung đột dân sự ở Xiaxia bằng sắc đẹp và trí tuệ của mình, sau đó đã uống rượu có độc cùng cỏ bất tử với một chiếc chén vàng.Sau đó cô đã chuyển đến một thế giới khác. Tại thế giới này, Liu Xiyin đã gặp một người tên là Diệp Chiêu, ở thế giới của thời Bắc Tống, chân tâm không thể nào đáp trả, và trên thế giới này, sự si mê của Liu Xiyin sẽ đi về đâu.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324306);
