INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-tron-chay-vu-an-ky-la-ve-carlos-ghosn', 'Kẻ Trốn Chạy: Vụ Án Kỳ Lạ Về Carlos Ghosn', 'Fugitive: The Curious Case Of Carlos Ghosn', 'https://phimimg.com/upload/vod/20240123-1/49970047c2f59dfb1c2518d21bdac21b.jpg', 'https://phimimg.com/upload/vod/20240123-1/e8d230a96c8f4e5dc0fa2ce870dd148c.jpg', '<p>Qua hành trình trỗi dậy thành trùm kinh doanh cho đến khi khét tiếng quốc tế, bộ phim tài liệu tội phạm có thật này khám phá câu chuyện kỳ quặc của Carlos Ghosn.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324306);
