INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('beclin-tren-khong', 'Béc-Lin Trên Không', '1941. Kryilya Nad Berlinom', 'https://phimimg.com/upload/vod/20240123-1/2dd66faed0fef7a6650bc1f06aa50e7f.jpg', 'https://phimimg.com/upload/vod/20240123-1/8b741df7c2ac6f3648cda161efb44c29.jpg', '<p>Sau cuộc xâm lược Liên Xô, tuyên truyền ở Đức Quốc xã tuyên bố rằng Lực lượng Không quân Đỏ đã bị tiêu diệt hoàn toàn. Do đó, bộ chỉ huy Liên Xô quyết định thực hiện một cuộc tấn công trả đũa vào thủ đô của đế chế, Berlin, bằng máy bay ném bom tầm xa. Nhiệm vụ được giao cho Lực lượng Không quân của Hạm đội Baltic, lực lượng này đã cử 13 máy bay ném bom hai động cơ DB-3F do Đại tá Preobrazhensky ( Maxim Biťukov ) chỉ huy tham gia cuộc đột kích vào đêm ngày 7-8 tháng 8 năm 1941 . Bộ phim tái tạo không chỉ quá trình chuẩn bị cho sự kiện phức tạp mà còn cả cuộc đột kích. Trong chuyến bay dài, các phi hành đoàn dũng cảm không chỉ phải chiến đấu với kẻ thù mà còn cả sự mệt mỏi và thời tiết xấu. Đây là câu chuyện của họ...</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Evgeniy Antropov","avatar":""},{"name":"Stepan Belozyorov","avatar":""},{"name":"Maksim Bityukov","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324306);
