INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-ket-van-menh', 'Liên Kết Vận Mệnh', 'Connect', 'https://phimimg.com/upload/vod/20240118-1/8e5f15822ada8aec13f9c7b30c69b224.jpg', 'https://phimimg.com/upload/vod/20240118-1/21c7724f8e618e1562fd452247560e27.jpg', '<p>Dựa trên webcomic cùng tên của Shin Dae-Sung.Ha Dong-Soo ( Jung Hae-In ) là một phần của loài người mới được gọi là kết nối. Các sinh vật kết nối không bao giờ chết. Một đêm nọ, Ha Dong-Soo bị bắt cóc bởi một nhóm buôn bán nội tạng người. Mắt anh ta bị cắt ra khỏi anh ta. Anh ta sớm nhìn thấy thứ gì đó và nhận ra người đàn ông đã đánh cắp con mắt của mình là một kẻ giết người hàng loạt. Ha Dong-Soo giờ đã có thể nhìn thấy những gì kẻ giết người hàng loạt nhìn thấy. Anh đuổi theo kẻ giết người hàng loạt để ngăn hắn giết người nữa.Trong khi đó, con mắt bị đánh cắp của Ha Dong-Soo đã được cấy ghép vào Oh Jin-Seob ( Ko Gyung-Pyo ). Oh Jin-Seob trông có vẻ là một nhân viên lịch sự và có năng lực trong công việc, nhưng anh ta thực sự là một kẻ giết người hàng loạt máu lạnh.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Hae-In","avatar":""},{"name":"Ko Kyoung-Pyo","avatar":""},{"name":"Kim Hye-Jun","avatar":""},{"name":"Jang Gwang","avatar":""},{"name":"Kim Roe-Ha","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324306);
