INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-so-khong', 'Từ Số Không', 'From Scratch', 'https://phimimg.com/upload/vod/20240118-1/39f7d6994379024cadfd825f177c8148.jpg', 'https://phimimg.com/upload/vod/20240118-1/58ab5071a261377319769f0bcdc3516b.jpg', '<p>Một họa sĩ rơi vào lưới tình với một đầu bếp ở Ý và dấn thân vào hành trình thay đổi cuộc đời, chứa đựng tình yêu, mất mát, nghị lực cùng hi vọng qua nhiều nền văn hóa và lục địa.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zoe Saldaña","avatar":""},{"name":"Eugenio Mastrandrea","avatar":""},{"name":"Keith David","avatar":""},{"name":"Danielle Deadwyler","avatar":""},{"name":"Judith Scott","avatar":""},{"name":"Kellita Smith","avatar":""},{"name":"Lucia Sardo","avatar":""},{"name":"Paride Benassai","avatar":""},{"name":"Roberta Rigano","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324306);
