INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-chung-ta-co-ke-noi-doi', 'Trong Chúng Ta Có Kẻ Nói Dối', 'One Of Us Is Lying', 'https://phimimg.com/upload/vod/20240118-1/8aa6ef5ad156aeb779da745a100f0e91.jpg', 'https://phimimg.com/upload/vod/20240118-1/92a85aadb31e77c079643c234725e215.jpg', '<p>Năm học sinh cấp ba gặp nhau qua lần bị cấm túc, nhưng án mạng và những bí mật giữ họ ở bên nhau khi một vụ giết người bí ẩn kiểu mèo vờn chuột dần hé mở.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Annalisa Cochrane","avatar":""},{"name":"Chibuikem Uche","avatar":""},{"name":"Marianly Tejada","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324306);
