INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ly-thien-vuong', 'Trợ Lý Thiên Vương', 'Assistant Of Superstar', 'https://phimimg.com/upload/vod/20240118-1/f2a356f20b2287373cdb7280d9dead9c.jpg', 'https://phimimg.com/upload/vod/20240118-1/a2ca8209759f43f0b90fbc1bba906ff3.jpg', '<p>Trợ Lý Thiên Vương kể về một sinh viên hàng đầu của Khoa lịch sử tình cờ gặp gỡ và quen biết siêu sao Do Hi. Do trình độ văn chương kém, Do Hi khiến đạo diễn tức giận, hơn nữa còn bị tố cáo năng lực của bản thân. Không còn cách nào, công ty quản lý bèn phải tìm người gia sư với hy vọng có thể giúp Do Hi nâng cao trình độ và giúp anh giành được vai nam chính trong phim. Từ hai con người có tính cách và thói quen trái ngược, họ dần quen với sự xuất hiện của đối phương.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tôn Trạch Nguyên","avatar":""},{"name":"Lư Dương Dương","avatar":""},{"name":"Trần Bằng Vạn Lý","avatar":""},{"name":"Vương Lộ Tình","avatar":""},{"name":"Từ Hạc Ni","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324306);
