INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ray-donovan-finale', 'Ray Donovan Finale', 'Ray Donovan Finale', 'https://phimimg.com/upload/vod/20240124-1/48e519c04e6112ac0241b4c4dbca930e.jpg', 'https://phimimg.com/upload/vod/20240124-1/85f5d6aa3d709aa681c605fe888e6a21.jpg', '<p>Một thập kỷ hiển thị trong việc tạo ra các vòng tròn đầy đủ của gia đình Donovan. Là những sự kiện khiến Nguồn trở thành người hôm nay cuối cùng cũng đến với ánh sáng, những người Donovans thấy mình bị lôi kéo trở lại Boston để đối mặt với quá khứ. Mỗi người trong số họ đấu tranh để vượt qua sự giáo dục bạo lực của họ, nhưng định mệnh chết mạnh mẽ, và chỉ có tình yêu khốc liệt của họ dành cho nhau để giữ chúng trong cuộc chiến. Cho dù họ đứng cùng nhau hay họ đi xuống đong đưa, một thứ chắc chắn - tia không bị lỏng lẻo kết thúc.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324306);
