INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-phia-sau-giai-dieu', 'Tình Yêu Phía Sau Giai Điệu', 'Love Behind The Melody', 'https://phimimg.com/upload/vod/20240118-1/b61952a3e51d6999b181bfbd13104659.jpg', 'https://phimimg.com/upload/vod/20240118-1/08c49e9123a82d6e7c2a2f7bd1c439f4.jpg', '<p>Li Sasa, người biểu diễn pipa chính, đang biểu diễn trên sân khấu với một màn biểu diễn lôi cuốn thì tình cờ, một con pipa cổ phượng đã kéo cô vào triều đại thịnh vượng một nghìn năm trước và trở thành một cô gái pipa bị bỏ rơi. Sống trên đường phố Shangjing, cô ấy vô tình sống ở Youjiaofang, và trở nên gắn bó với Lu Jingnian, người đứng đầu Youjiaofang, người đang bị Yingyan vây quanh trong chợ. Với đầy đủ kỹ năng tình trường và trường khí, Li Sasa dần khiến Lu Jingnian có cái nhìn khác về mình. Cả hai đã chung tay với Xiner, Yu Shijie và những người bạn khác để cùng nhau xây dựng nên Nhóm Thiên nữ Shengchao. Trong suốt quá trình đó, tình yêu giữa hai người vẫn tiếp tục lan tỏa, và ai sẽ là người tỏ tình trước khi họ đang ở bờ vực của sự mơ hồ?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bao Shangen","avatar":""},{"name":"Wu Chongxuan","avatar":""},{"name":"Pan Yuetong","avatar":""},{"name":"Jiang Yiming","avatar":""},{"name":"Zhu Jiaqian","avatar":""},{"name":"Xiang Hao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324306);
