INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-hong-dai-chien-2022', 'Hoa Hồng Đại Chiến', 'The War Of Flowers', 'https://phimimg.com/upload/vod/20240116-1/b98def9bb7a37e6c35c2882d5c5c801e.jpg', 'https://phimimg.com/upload/vod/20240116-1/0ea1f37682f4c0fbe321d899bd2952e8.jpg', '<p>Là nhân tình của một triệu phú giàu có, trong nhiều năm, Ornnapa đã phải chịu đựng tất cả các loại ngược đãi của Kannika, vợ hợp pháp của chồng mình. Khi chồng chết, Kannika đuổi Ornnapa và con gái Onsalao ra khỏi nhà của họ. Nhiều năm trôi qua, thế hệ thứ hai của gia đình trưởng thành, những ân oán từ quá khứ lại khơi mào cho một cuộc chiến giữa những người cùng dòng máu.Hoa Hồng Đại Chiến - The War Of Flowers, phim Thái hoa hồng đại chiến, xem phim hoa hong dai chien, hoa hong dai chien tap 1 2 3 4 5 6 7 8 9.., phim Thai the war of flowers,</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2022, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Lukkade Metinee Kingpayom","avatar":""},{"name":"Sonia Couling","avatar":""},{"name":"Krist Perawat Sangpotirat","avatar":""},{"name":"Aye Sarunchana Apisamaimongkol","avatar":""},{"name":"Gun Atthaphan Phunsawat","avatar":""},{"name":"June Wanwimol Jaenasavamethee","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324306);
