INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-kha-nghi', 'Không Khả Nghi', 'Unsuspicious', 'https://phimimg.com/upload/vod/20240116-1/02b039568060e1eb2b78fb9019ad9a05.jpg', 'https://phimimg.com/upload/vod/20240116-1/c84dfe1187b29216fd799e0a986682c0.jpg', '<p>Cùng bị một tay chơi lừa gạt, ba phụ nữ và gia đình của họ đến biệt thự của anh ta để tìm câu trả lời và phải ở lại tham gia điều tra khi anh ta được phát hiện đã chết.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 15, 2022, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Paulo Tiefenthaler","avatar":""},{"name":"Marcelo Médici","avatar":""},{"name":"Gi Uzêda","avatar":""},{"name":"Fernanda Paes Leme","avatar":""},{"name":"Maíra Azevedo","avatar":""},{"name":"Thati Lopes","avatar":""},{"name":"Eliezer Motta","avatar":""},{"name":"Gkay","avatar":""},{"name":"Dhu Moraes","avatar":""},{"name":"Raphael Logam","avatar":""},{"name":"Rômulo Arantes Neto","avatar":""},{"name":"Silvero Pereira","avatar":""},{"name":"Cezar Maracujá","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324306);
