INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('senzo-vu-sat-hai-ngoi-sao-bong-da', 'Senzo: Vụ Sát Hại Ngôi Sao Bóng Đá', 'Senzo: Murder Of A Soccer Star', 'https://phimimg.com/upload/vod/20240116-1/864ec8b27b2803c69fdce9564c1c521d.jpg', 'https://phimimg.com/upload/vod/20240116-1/67c5f1047052ecd7ba8ed63b82c07160.jpg', '<p>Cầu thủ bóng đá Senzo Meyiwa vốn là anh hùng dân tộc trước khi vụ sát hại anh khiến Nam Phi chấn động. Ai giết anh và vì sao? Loạt phim tài liệu này sẽ đào sâu chứng cứ.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 14, 2022, 'Vietsub', 'HD', 'Nam Phi', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324306);
