INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-ngung-uoc-mo-cuoc-doi-va-di-san-cua-shimon-peres', 'Không Ngừng Ước Mơ: Cuộc Đời Và Di Sản Của Shimon Peres', 'Never Stop Dreaming: The Life And Legacy Of Shimon Peres', 'https://phimimg.com/upload/vod/20240123-1/6091fe92e15a14f7f8ab393862867f9c.jpg', 'https://phimimg.com/upload/vod/20240123-1/50487c459220e4a7c40fcffede2a5766.jpg', '<p>Trong chính trị, đa số theo đuổi quyền lực còn ông lại một lòng vì hòa bình. Uy thế và sự chính trực của Shimon Peres là yếu tố then chốt giúp thành lập và bảo vệ Israel.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shimon Peres","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324306);
