INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-ruot-duoi-sinh-tu', 'Cuộc Rượt Đuổi Sinh Tử', 'Run & Gun', 'https://phimimg.com/upload/vod/20240123-1/a7fcc53a901db44d9e81c727f7a50c2d.jpg', 'https://phimimg.com/upload/vod/20240123-1/d2a0bb05f8358a2de4c56e6f9fad2405.jpg', '<p>Cuộc rượt đuổi sinh tử - Run &amp; Gun là bộ phim thuộc thể loại hành động, giật gân của Mỹ. Tác phẩm do đạo diễn Christopher Borrelli chịu trách nhiệm chỉ đạo, với sự tham gia của các diễn viên Angela Sarafyan, Mark Dacascos và Richard Kind.Sau khi rời bỏ cuộc đời đầy tội ác và bạo lực, Ray là một chàng trai được cải tạo tốt, tận hưởng một cuộc sống gia đình êm ấm và hạnh phúc. Nhưng khi quá khứ của anh ta bị phát hiện, Ray bị ép phải làm một công việc cuối cùng chính là thu thập một gói bí ẩn.Sau một pha băng giá chết người, anh ta thấy mình bị thương và đang chạy trốn khỏi những sát thủ tàn nhẫn, những kẻ sẽ không dừng lại để lấy đi những gì anh ta có. Bây giờ, với việc cuộc sống của những người thân của anh ta đang bị mất cân bằng và rơi vào nguy hiểm ở mọi nơi, hy vọng duy nhất của Ray là dựa vào quá khứ bạo lực của mình để tồn tại.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Milliken","avatar":""},{"name":"Brad William Henke","avatar":""},{"name":"Janel Parrish","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324306);
