INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-dong-vuot-nguc-3', 'Hành Động Vượt Ngục 3', 'Breakout Brothers 3', 'https://phimimg.com/upload/vod/20240122-1/603fe82835dcbceae2ee74bc7c02e51c.jpg', 'https://phimimg.com/upload/vod/20240122-1/19912110fac0540709063564b5fb9f8e.jpg', '<p>Cựu quản giáo Tang bị bỏ tù vì nhận hối lộ, trong khi Jun, người không vượt ngục trở lại nhà tù để tiếp tục thi hành án. Jun thấy Tang quen thuộc với nhà tù và dụ anh ta hợp tác trong kế hoạch vượt ngục. Cả hai đã đánh nó, và thậm chí còn cố gắng tạo ra rắc rối và đổ lỗi cho Big Roller. Jun nhanh chóng phát hiện ra Tang có những thủ đoạn khác, buộc anh phải hợp tác một lần nữa với Big Roller, Mak và người quản giáo mới Ma để phá âm mưu của Tang.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Patrick Tam","avatar":""},{"name":"Ron Ng","avatar":""},{"name":"Tak-bun Wong","avatar":""},{"name":"Justin Cheung","avatar":""},{"name":"Moses Chan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324306);
