INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuyen-vuong', 'Khuyển Vương', 'INU-OH', 'https://phimimg.com/upload/vod/20240121-1/47849d46969208ae912ee4bad4a22015.jpg', 'https://phimimg.com/upload/vod/20240121-1/9a070ea1b9434d9d96b63180243e90e3.jpg', '<p>Sinh ra trong một gia đình danh giá, Inu-oh dính phải một lời nguyền cổ xưa khiến anh bị gạt ra bên lề xã hội. Khi gặp nhạc sĩ mù Tomona, một linh mục biwa trẻ tuổi bị ám ảnh bởi quá khứ của mình, Inu-oh phát hiện ra khả năng khiêu vũ quyến rũ. Cặp đôi nhanh chóng trở thành đối tác kinh doanh và những người bạn không thể tách rời khi đám đông đổ xô đến các buổi hòa nhạc hoành tráng, hoành tráng của họ. Nhưng khi những người nắm quyền đe dọa sẽ giải tán ban nhạc, Inu-oh và Tomona phải nhảy và hát để khám phá sự thật đằng sau tài năng sáng tạo của họ.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Avu-chan","avatar":""},{"name":"Mirai Moriyama","avatar":""},{"name":"Tasuku Emoto","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Yutaka Matsushige","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324306);
