INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-con-ma-me-ke-dan-ve-tung-la-ban-gai-cu', 'Đứa Con Mà Mẹ Kế Dẫn Về Từng Là Bạn Gái Cũ', 'Mamahaha No Tsurego Ga Motokano Datta My Stepmom''s Daughter Is My Ex', 'https://phimimg.com/upload/vod/20240116-1/ae5cae3cacca518ba3442f08b995f45b.jpg', 'https://phimimg.com/upload/vod/20240116-1/3086d7c83a68119d5692dd67ef26b858.jpg', '<p>Irido Mizuto và Ayai Yume từng hẹn hò trong thời sơ trung. Tuy nhiên, vì bất đồng trong những chuyện nhỏ nhặt mà hai người đã quyết định chia tay nhau vào ngày tốt nghiệp. Tưởng rằng mọi chuyện đã kết thúc, ngay sau đó Mizuto lại biết được người mẹ kế mà bố cậu sắp tái hôn lại chính là mẹ của Yume. Cũng vì thế mà Mizuto và Yume trở thành chị em một nhà trên danh nghĩa. Để giữ bí mật quan hệ tình cảm trước kia với bố mẹ, hai người đã đặt ra luật lệ anh chị em, rằng đối phương nào tỏ tình trước sẽ là người thua cuộc.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 13, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324306);
