INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-be-hawa', 'Cô Bé Hawa', 'Hawa', 'https://phimimg.com/upload/vod/20240205-1/af3716992622e90ab20fb1e0da641a0a.jpg', 'https://phimimg.com/upload/vod/20240205-1/c69e3247468c864673a0e1078e3bf48a.jpg', '<p>Hầu hết chúng ta đều mơ ước trở thành con của người nổi tiếng mà mình yêu thích. Nhưng Hawa rất nghiêm túc. Cô bé mắc bệnh bạch tạng mong muốn được Michelle Obama nhận làm con nuôi. Lý do của cô ấy là gì? Tại sao cô ấy muốn rời khỏi nhà của mình? Câu chuyện dựa trên bộ phim Hawa của Pháp . Bộ phim ra mắt trên Amazon Prime Video và phimmoi vào ngày 9 tháng 12 .</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sania Halifa","avatar":""},{"name":"Oumou Sangaré","avatar":""},{"name":"Yseult","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324306);
