INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuong-quy-2022', 'Xưởng Quỷ', 'Devils Workshop', 'https://phimimg.com/upload/vod/20240104-1/38f3f6a6c42a8fc566940b7adc37fa76.jpg', 'https://phimimg.com/upload/vod/20240104-1/ad796bc51a0bdc51d8263fcd1aa03a36.jpg', '<p>Trong bộ phim kinh dị tâm lý rùng rợn này có sự tham gia của Emile Hirsch (Into the Wild), nam diễn viên đang gặp khó khăn Clayton (Timothy Granaderos, 13 Reasons Why) đang khao khát được đóng vai một nhà quỷ học. Anh liên lạc với Eliza (Radha Mitchell, Man on Fire), một chuyên gia về truyền thuyết ma quỷ, để giúp anh chuẩn bị và dành cuối tuần ở nhà cô. Eliza buộc Clayton phải đối mặt với quá khứ rắc rối của mình, thực hiện các nghi lễ đen tối và hiến tế một con dê. Cô ấy muốn giúp Clayton, quyến rũ anh ta - hay tiêu diệt anh ta? Cao trào gây sốc sẽ đốt cháy tâm hồn bạn.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Radha Mitchell","avatar":""},{"name":"Timothy Granaderos","avatar":""},{"name":"Emile Hirsch","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324306);
