INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-trung', 'Thanh Trừng', 'Hugas', 'https://phimimg.com/upload/vod/20240104-1/f00d2d028145388a2d169a598fc20fc0.jpg', 'https://phimimg.com/upload/vod/20240104-1/8f210583417d797ee359000d5984432f.jpg', '<p>Các thành viên cũ của băng đảng và cặp vợ chồng mới cưới Al và Liezl chạy trốn với một túi tiền lớn, nhưng ông chủ cũ của họ sẽ đi đến tận cùng trái đất để tìm họ.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"AJ Raval","avatar":""},{"name":"Sean de Guzman","avatar":""},{"name":"Jay Manalo","avatar":""},{"name":"Soliman Cruz","avatar":""},{"name":"Benj Manalo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324306);
