INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tranh-tam-sau', 'Tranh Tầm Sâu', 'Diorama', 'https://phimimg.com/upload/vod/20240104-1/ab7a0db1cef6ab6604139c3f72fdfbd3.jpg', 'https://phimimg.com/upload/vod/20240104-1/2f189555dae5b2c3b43bfb56739e9831.jpg', '<p>Khi những hiểu lầm và cám dỗ ngày một nhiều thêm, cuộc hôn nhân từng một thời mặn nồng của cặp đôi nọ dần dần được hé lộ và thuật lại qua loạt cảnh tầm sâu hài hước.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Pia Tjelta","avatar":""},{"name":"David Dencik","avatar":""},{"name":"Morgan Alling","avatar":""},{"name":"Anna Lagerkvist","avatar":""},{"name":"Dag Andersson","avatar":""},{"name":"Sarah Dawn Finer","avatar":""},{"name":"Shanti Roney","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324306);
