INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-anh-duong-amalfi', 'Dưới Ánh Dương Amalfi', 'Under The Amalfi Sun', 'https://phimimg.com/upload/vod/20240104-1/06fc3da178fa7eda2a1f30602f37d597.jpg', 'https://phimimg.com/upload/vod/20240104-1/12c51c302e75e128c06eb413a85f9efd.jpg', '<p>Một năm sau khi chuyện tình của họ bắt đầu ở Riccione, Vincenzo và Camilla đoàn tụ vào một kỳ nghỉ ở Bờ biển Amalfi đẹp như tranh và thử thách tình yêu của họ.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Lorenzo Zurzolo","avatar":""},{"name":"Ludovica Martino","avatar":""},{"name":"Davide Calgaro","avatar":""},{"name":"Isabella Ferrari","avatar":""},{"name":"Luca Ward","avatar":""},{"name":"Kyshan Wilson","avatar":""},{"name":"Nicolas Maupas","avatar":""},{"name":"Andrea Occhipinti","avatar":""},{"name":"Elena Funari","avatar":""},{"name":"Marit Nissen","avatar":""},{"name":"Raz Degan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324306);
