INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-nang-cua-green-lantern', 'Quyền Năng Của Green Lantern', 'Green Lantern: Beware My Power', 'https://phimimg.com/upload/vod/20240104-1/0b1790186b77b9b0860afb75a8ea46b7.jpg', 'https://phimimg.com/upload/vod/20240104-1/54d7d65c68bd44ce208b9b801bd57adb.jpg', '<p>Trong Green Lantern: Beware My Power , lính bắn tỉa của Thủy quân lục chiến John Stewart mới giải ngũ gần đây đang ở ngã rẽ trong cuộc đời mình, nơi chỉ phức tạp khi nhận được một chiếc nhẫn ngoài Trái đất, thứ trao cho anh sức mạnh của Green Lantern of Earth. Thật không may, chiếc nhẫn không có hướng dẫn - nhưng nó đi kèm với hành lý, giống như một đám sát thủ liên hành tinh đang cố gắng loại bỏ mọi Green Lantern trong vũ trụ. Giờ đây, với sự trợ giúp của Green Arrow nhẹ nhàng, Adam Strange và Hawkgirl, người lính bất đắc dĩ này phải hành trình vào trung tâm của cuộc chiến giữa thiên hà Rann / Thanagar và bằng cách nào đó thành công, nơi mà tất cả các Green Lantern khác đã thất bại.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aldis Hodge","avatar":""},{"name":"Jimmi Simpson","avatar":""},{"name":"Ike Amadi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324306);
