INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-cua-co-dau', 'Bố Của Cô Dâu', 'Father Of The Bride', 'https://phimimg.com/upload/vod/20240104-1/2b0e5689508a93526e2ea58ae173d7d4.jpg', 'https://phimimg.com/upload/vod/20240104-1/b26200922ab0e1baf1f8733a103a74c2.jpg', '<p>Kiến trúc sư nổi tiếng Billy ( Andy Garcia ) và vợ Ingrid ( Gloria Estefan ) Herrera là một cặp vợ chồng người Mỹ gốc Cuba sống ở Miami có hai con gái, Sofia ( Adria Arjona ) mới tốt nghiệp trường luật và nhà thiết kế thời trang nổi loạn Cora ( Isabela Merced ). Tại buổi tư vấn cho các cặp vợ chồng, Ingrid nói với Billy rằng cô ấy đã có đủ thái độ tham công tiếc việc và sự bướng bỉnh của anh ta và muốn ly hôn; cố vấn của họ nói với họ để nói với con gái của họ ngay lập tức. Ingrid muốn thông báo nó vào cuối ngày hôm đó sau khi Sofia đến thăm, nhưng Sofia lần đầu tiên thông báo rằng cô đã đính hôn với luật sư đồng nghiệp Adan Castillo ( Diego Boneta) và họ muốn kết hôn sau một tháng nữa. Billy và Ingrid đồng ý giữ bí mật vụ ly hôn của họ cho đến sau đám cưới. Billy đang do dự về việc cưới của Sofia và mong muốn chuyển đến Mexico cùng Adan để làm việc cho một tổ chức phi lợi nhuận thay vì ở lại Hoa Kỳ. Hai người càng bất đồng vì Billy muốn một đám cưới lớn, truyền thống của Cuba trong khi Sofia và Adan muốn một buổi lễ nhỏ hơn. Trong khi đó, Sofia yêu cầu Cora may váy cưới và váy cho phù dâu của cô ấy, khiến người tổ chức đám cưới lập dị Natalie Vance ( Chloe Fineman ) bất bình.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andy García","avatar":""},{"name":"Gloria Estefan","avatar":""},{"name":"Adria Arjona","avatar":""},{"name":"Isabela Merced","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324306);
