INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nocebo', 'Nocebo', 'Nocebo', 'https://phimimg.com/upload/vod/20240103-1/2f4c8a00322f2bb42b8c4dc0491ecd7d.jpg', 'https://phimimg.com/upload/vod/20240103-1/0ab63343744d12f329b745cf49793d03.jpg', '<p>Một nhà thiết kế thời trang thuê một bảo mẫu từ Philippines để hỗ trợ cô ấy chăm sóc gia đình trong khi cô ấy đang mắc một căn bệnh mà cô ấy tin là liên quan đến ve. vì vậy, cô ấy phát hiện ra một sự thật kinh hoàng về lý do tại sao cô ấy ở đó và tại sao chủ của cô ấy thực sự bị ốm.</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Eva Green","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Chai Fonacier","avatar":""},{"name":"Billie Gadsdon","avatar":""},{"name":"Cathy Belton","avatar":""},{"name":"Anthony Falcon","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324306);
