INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('redeem-team-doi-bong-ro-sieu-sao', 'Redeem Team: Đội Bóng Rổ Siêu Sao', 'The Redeem Team', 'https://phimimg.com/upload/vod/20240103-1/1033736ab6995f48e463b973f697b3ee.jpg', 'https://phimimg.com/upload/vod/20240103-1/a2a26378e8bc6e1bc6fe8c6ba8974285.jpg', '<p>Sau phần thể hiện gây sốc ở Thế vận hội 2004, đội tuyển bóng rổ nam Hoa Kỳ tìm cách chuộc lỗi khi họ nhắm đến huy chương vàng ở Thế vận hội Bắc Kinh 2008.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324306);
