INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngam-trung-tuong-lai-cua-em', 'Ngắm Trúng Tương Lai Của Em', 'Out With A Bang', 'https://phimimg.com/upload/vod/20240112-1/35904c0f0e2c797e0e938a2a08a64b88.jpg', 'https://phimimg.com/upload/vod/20240112-1/bb07cc4e88b81ec117d91097b3ac0bd3.jpg', '<p>Tiêu Diệc Xuyên một tuyển thủ thể thao điện tử chuyên nghiệp sắp giải nghệ. Để giành quán quân, anh sẵn sàng từ bỏ điều trị chấn thương. Vừa trở về Trung Quốc, anh gặp Hùng Thu Thu, một cô gái đầy nhiệt huyết đang tìm kiếm thành viên trong số những tuyển thủ thể thao điện tử không xuất sắc. Thông qua nỗ lực của Thu Thu, Diệc Xuyên quyết định gia nhập đội. Đội không nổi tiếng này được thành lập bao gồm nhà vô địch thể thao điện tử Diệc Xuyên, vua lý thuyết Hồng Dương, tuyển thủ tài năng Chu Thiên và đổng sự. Họ không chỉ phải đối mặt với những kẻ thù mạnh mà còn cả những vấn đề xung quanh cuộc sống của họ. Bắt đầu từ một gà mờ trở thành game thủ xuất sắc, từ việc không hòa hợp đến biết hỗ trợ giúp đỡ lẫn nhau, trải qua nhiều thử thách, cuối cùng họ đã đứng trên đấu trường quốc tế. Thu Thu và Dược Xuyên cũng đã giải quyết được hiểu lầm hẹn hò trực tuyến vài năm trước và trở thành cặp đôi hình mẫu lí tưởng trong giới thể thao điện tử.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Jiong Min","avatar":""},{"name":"Từ Nhược Hàm","avatar":""},{"name":"Hách Phú Thân","avatar":""},{"name":"Seek","avatar":""},{"name":"Wang Jia Meng","avatar":""},{"name":"Poppy","avatar":""},{"name":"Mai Tong","avatar":""},{"name":"Yuan Jia Yi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324306);
