INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-si-dan-duong-cua-nha-vua', 'Kỵ Sĩ Dẫn Đường Của Nhà Vua', 'Elesin Oba: The King''s Horseman', 'https://phimimg.com/upload/vod/20240108-1/0886ab9cbad3364ddfa19baeeb7eb49e.jpg', 'https://phimimg.com/upload/vod/20240108-1/2b30b1b09b571e9a11f248c07ecfcaa5.jpg', '<p>Sau khi vua của anh qua đời, một kỵ sĩ phải hy sinh chính mình để phục vụ chủ nhân ở thế giới bên kia. Nhưng rồi sự phân tâm đột ngột dẫn đến bi kịch không ngờ.</p>', 'Full', 1, 'single', 'completed', 32, 2022, 'Vietsub', 'HD', 'Châu Phi', 0, '[{"name":"Odunlade Adekola","avatar":""},{"name":"Shaffy Bello","avatar":""},{"name":"Deyemi Okanlawon","avatar":""},{"name":"Mark Elderkin","avatar":""},{"name":"Jenny Stead","avatar":""},{"name":"Omowunmi Dada","avatar":""},{"name":"Jide Kosoko","avatar":""},{"name":"Kevin Ushi","avatar":""},{"name":"Langley Kirkwood","avatar":""},{"name":"Olawale ''Brymo'' Olofooro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
