INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-guong-3', 'Ma Gương 3', 'Kuntilanak 3', 'https://phimimg.com/upload/vod/20240108-1/f88501f5503c7b309265bf3ab5bc7628.jpg', 'https://phimimg.com/upload/vod/20240108-1/711457644e7d42443dba258d00ab6693.jpg', '<p>&nbsp;Bộ phim này tiếp tục câu chuyện của Kuntilanak 2 (2019). Dinda (Nicole Rossi), người được coi là kỳ lạ vì sức mạnh của mình sau đó yêu cầu người chăm sóc của trại trẻ mồ côi gửi cô đến Trường Mata Hati để học cách kiểm soát sức mạnh của mình.Nhưng sau đó người ta phát hiện ra rằng nhiều điều kỳ lạ đã xảy ra ở đó, trong đó có việc các học sinh mất tích. Hiệu trưởng đã cảm thấy sức mạnh của Dinda sau đó báo cáo kết quả cho người sáng lập bí ẩn của trường, Eyang Sukma (Sara Wijayanto).</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Indonesia', 1, '[{"name":"Nicole Rossi","avatar":""},{"name":"Andryan Bima","avatar":""},{"name":"Ali Fikry","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324307);
