INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luu-trai-tan-truyen-hoa-bi', 'Lưu Trai Tân Truyện - Họa Bì', 'GHOST STORY', 'https://phimimg.com/upload/vod/20240108-1/99dff7d660360114d0efda63430df4c1.jpg', 'https://phimimg.com/upload/vod/20240108-1/0e5a1ed357bfe49d58d99b4e53073735.jpg', '<p>Chàng thư sinh Vương Sinh vô tình thu nhận yêu tinh hồ ly Hương Nhi, không biết thân phận của ả nên đã để ả ở lại nhà, thậm chí còn muốn lấy ả làm vợ. Cùng với việc danh tính của Hương Nhi bại lộ thì mọi thứ dần dần sáng tỏ. Cuối cùng, vì sự mê muội của Vương Sinh mà chàng thư sinh đã mất tất đi cả...</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ma Hui","avatar":""},{"name":"Zhou Yu Peng","avatar":""},{"name":"Zhao Han Xue","avatar":""},{"name":"Wai Lam","avatar":""},{"name":"Yin Yang Ming","avatar":""},{"name":"Wilson Lam","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324307);
