INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-muon-xac-tra-hon', 'Địch Nhân Kiệt: Mượn Xác Trả Hồn', 'Di Renjie Resurrection', 'https://phimimg.com/upload/vod/20240104-1/4cc90e19604f11d1a39f5f6b33cc4368.jpg', 'https://phimimg.com/upload/vod/20240104-1/082afa5df80edcc9ad3ed1a59f877b37.jpg', '<p>Vào năm đầu tiên của triều đại nhà Chu, một xác chết sống lại đột nhiên xuất hiện ở quận Kiều. Người dân đồn thổi rằng hồn ma của Lý Đường đã trở lại, nhằm lật đổ Chu. Cùng lúc đó, ác long được hình thành bằng âm khí của xác chết đột nhiên giáng xuống kinh thành, tuyên bố rằng long khí trên người Vũ Chiếu đang bị mất dần và sắp chết. Trước sự việc này, Định Nhân Kiệt nhận lệnh điều tra. Đối mặt với sự kháng cự nặng nề và những âm mưu đánh trả, Định Nhân Kiệt đã liên thủ với đã Tống Tiểu Bạch một chàng trai giống hệt mình. Bằng sự thông minh và dũng cảm cuối cùng Định Nhân Kiệt cũng lật ngược đại cục bằng cách hồi sinh xác chết và đánh bại kẻ phản bội, phá vỡ âm mưu của kẻ xấu và đưa sự thật ra ánh sáng.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Apollo","avatar":""},{"name":"Sun Wei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
