INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-bup-be-3', 'Linh Hồn Búp Bê 3', 'The Doll 3', 'https://phimimg.com/upload/vod/20231231-1/df9718bce380be4ae6d368e3753cd597.jpg', 'https://phimimg.com/upload/vod/20231231-1/f20d95a34c84408fd568c80e99a878b0.jpg', '<p>Sau một tai nạn giết chết cả cha và mẹ của Tara, Tara giờ chỉ còn một người em trai tên Gian là một thành viên trong gia đình. Tuy nhiên, vụ tai nạn đã khiến Giản bị chấn thương tâm lý nên Giản chọn cách kết liễu đời mình. Tara, người làm việc tại một cửa hàng đồ chơi, quyết định nhờ một pháp sư triệu hồi linh hồn của Gian bằng cách sử dụng Bobby, một con búp bê mà cô ấy bán trong cửa hàng đồ chơi của mình, để làm nơi dành cho linh hồn của Gian.Liệu Tara sẽ làm thế nào theo dõi phimmoichilla để biết tất cả diễn biến câu chuyện cũng như linh hồn trong búp bê ấy sẽ được hóa giải hay không ?</p>', 'Trailer', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jessica Mila","avatar":""},{"name":"Winky Wiryawan","avatar":""},{"name":"Masayu Anastasia","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324307);
