INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-giang-yeu-co', 'Trường Giang Yêu Cơ', 'Elves In Changjiang River', 'https://phimimg.com/upload/vod/20240128-1/5d296b891f477c096fe62f5a1997a1fc.jpg', 'https://phimimg.com/upload/vod/20240128-1/7099ddd0a46476eede6ba3fee0d6b347.jpg', '<p>Trường Giang bắt nguồn từ Côn Lôn và kết thúc ở Đông Minh, có vô số vạn vật bị nước sông nuôi dưỡng mà biến thành quỷ. Tùy Nguyên một học giả đến Kinh đô học, tình cờ rơi vào bẫy tình của cá chép Giang Tiểu Ngu và yêu đem lòng yêu cô. Thầy diệt quỷ đã cứu Tùy Nguyên và phát hiện tất cả đều do thú cá cổ xưa gây nên. Nước sông sôi sục, dân chúng lầm than, bắt đầu một trận chiến để cứu người trên dòng Ngô Giang ...</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"An Wei Ling","avatar":""},{"name":"Li Cheng Xi","avatar":""},{"name":"Norman Chui","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324307);
