INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('eraser-reborn', 'Eraser: Reborn', 'Eraser: Reborn', 'https://phimimg.com/upload/vod/20240127-1/d3b66486491147067a156fdfdb4c0413.jpg', 'https://phimimg.com/upload/vod/20240127-1/c80993dfd0a8c68b332317125756f1b1.jpg', '<p>Thống chế Hoa Kỳ Mason Pollard chuyên “xóa sổ” con người - làm giả cái chết của những nhân chứng có nguy cơ cao. Với những tiến bộ công nghệ trong 25 năm qua, trò chơi đã được nâng cấp và chỉ là một ngày nữa tại văn phòng khi anh được giao cho Rina Kimura, vợ của một trùm tội phạm, người đã quyết định lật lại bằng chứng của bang. Khi cả hai chạy trốn đến Cape Town, Nam Phi, Pollard phát hiện ra rằng anh ta đã được sắp đặt và sẽ cần phải đứng đầu trò chơi của mình, nếu không anh ta sẽ là người bị xóa sổ.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dominic Sherwood","avatar":""},{"name":"Jacky Lai","avatar":""},{"name":"McKinley Belcher III","avatar":""},{"name":"Mampho Brescia","avatar":""},{"name":"Eddie Ramos","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324307);
