INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-luu-tru-81', 'Kho Lưu Trữ 81', 'Archive 81', 'https://phimimg.com/upload/vod/20240112-1/55166d9d737543a1452dc2ed94b927a8.jpg', 'https://phimimg.com/upload/vod/20240112-1/80bea56230f24654dab5ca1493d3de49.jpg', '<p>Nhận công việc khôi phục các băng video bị hỏng, một chuyên viên lưu trữ bị kéo vào vòng xoáy bí ẩn liên quan đến vị đạo diễn mất tích và một giáo phái hiểm ác.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mamoudou Athie","avatar":""},{"name":"Dina Shihabi","avatar":""},{"name":"Matt McGorry","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
