INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-hoi-su-cuoi-cung', 'Triệu Hồi Sư Cuối Cùng', 'The Last Summoner, Zui Hou De Zhao Huan Shi', 'https://phimimg.com/upload/vod/20240112-1/cfc73d598742a37ee4715b634820f8c4.jpg', 'https://phimimg.com/upload/vod/20240112-1/158f5cb0e959ca16c698e41f394ea7d5.jpg', '<p>Vạn vật đều có linh hồn, người có thể triệu hồi linh hồn vạn vật gọi là triệu hồi sư. Từ xưa tới nay, truyền thuyết của các triệu hồi sư được giấu trong mỗi đoạn lịch sử. Nay, thời đại mới, triệu hồi sư vừa thức tỉnh, A Kiệt lập chí trở thành vua kéo mì vô tình triệu hồi nữ thần Dora. Từ nay bước vào thế giới của triệu hồi sư. Trong mỗi lần chiến đấu và mạo hiểm, các thiếu niên có thể nắm được vận mệnh của mình, khám phá ra được sự thật của thế giới không?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
