INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('13-phim-nhac-kich', '13: Phim Nhạc Kịch', '13: The Musical', 'https://phimimg.com/upload/vod/20240102-1/5547e5b744c13dfc8b9cbd06b966fd92.jpg', 'https://phimimg.com/upload/vod/20240102-1/d22da4b3f30c414bb9cd884f4e283f09.jpg', '<p>Chuyển từ New York đến Indiana sau cuộc ly hôn của bố mẹ, một học sinh cấp hai thông minh quyết tâm tổ chức một lễ trưởng thành tuyệt vời nhất từ trước đến nay.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eli Golden","avatar":""},{"name":"Gabriella Uhl","avatar":""},{"name":"Debra Messing","avatar":""},{"name":"Rhea Perlman","avatar":""},{"name":"JD McCrary","avatar":""},{"name":"Lindsey Blackwell","avatar":""},{"name":"Peter Hermann","avatar":""},{"name":"Josh Peck","avatar":""},{"name":"Frankie McNellis","avatar":""},{"name":"Jonathan Lengel","avatar":""},{"name":"Ramon Reed","avatar":""},{"name":"Nolen Dubuc","avatar":""},{"name":"Luke Islam","avatar":""},{"name":"Shechinah Mpumlwana","avatar":""},{"name":"Khiyla Aynne","avatar":""},{"name":"Willow Moss","avatar":""},{"name":"Kaylei","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324307);
