INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('heo-con', 'Heo Con', 'Piggy', 'https://phimimg.com/upload/vod/20240102-1/33dbc6e52e15fce830117d0d56011694.jpg', 'https://phimimg.com/upload/vod/20240102-1/8fb98ac1c3d69fa4219f3b3e5cdfefff.jpg', '<p>Không phải ai cũng thích mùa hè. Đối với Sara, điều đó chỉ có nghĩa là phải đối mặt với hàng loạt lời chế giễu, phán xét và lạm dụng liên tục từ những cô gái khác trong làng của cô. Nhưng ngày nay thì khác. Một người đàn ông bí ẩn không rõ danh tính đến làng và bắt cóc những kẻ hành hạ cô. Ai đó cuối cùng đã đứng lên vì cô ấy. Sara nhìn thấy tất cả: máu, bùn, con dao và chiếc xe tải mà anh đã lấy chúng. Và người đàn ông vô danh đã nhìn thấy cô. Một hiệp ước không lời mà sẽ không phản bội. Giờ cô ấy là đồng phạm. Một loạt tội ác làm rung chuyển ngôi làng, và một cuộc điều tra sẽ sớm bắt đầu. Người bảo vệ dân phố thắc mắc không ngớt, dân làng nghi ngờ và chỉ tay, những người hàng xóm lớn tuổi đàm tiếu. Cái nóng ngột ngạt, áp lực ngột ngạt và cảm giác tội lỗi dày vò cô. Nếu cô ấy bị phát hiện thì sao? Chuyện gì đã xảy ra với các cô gái? Điều gì sẽ xảy ra nếu người đàn ông vô danh trở lại?Nên phimmoi khuyên: ĐỪNG BAO GIỜ CHÊ PHỤ NỮ BÉO MẬP NHƯ Piggy</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Laura Galán","avatar":""},{"name":"Richard Holmes","avatar":""},{"name":"Carmen Machi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324307);
