INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hieu-ung-martha-mitchell', 'Hiệu Ứng Martha Mitchell', 'The Martha Mitchell Effect', 'https://phimimg.com/upload/vod/20240102-1/c4b5e6ac4a95c26e9e6221e78ebbb8f4.jpg', 'https://phimimg.com/upload/vod/20240102-1/3a9e5f5c7f44ad95cfc0f698c5f3a2f1.jpg', '<p>Phim tài liệu này xoay quanh vợ của một chính trị gia cấp cao đã lên tiếng trong vụ Watergate – và chiến dịch của chính quyền Nixon nhằm thao túng để bà im lặng.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324307);
