INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('den-khi-cuoc-song-chia-lia', 'Đến Khi Cuộc Sống Chia Lìa', 'Until Life Do Us Part', 'https://phimimg.com/upload/vod/20240109-1/6ed5ccc6179920af943cb8a20863bb21.jpg', 'https://phimimg.com/upload/vod/20240109-1/5550a1eed467b09c8ccd0630be8b4f7f.jpg', '<p>Cùng sống trong ngôi biệt thự thơ mộng, ba thế hệ của một gia đình xoay xở giữa những đòi hỏi của công việc tổ chức đám cưới và cả những rắc rối cá nhân của mỗi người.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 36, 2022, 'Vietsub', 'HD', 'Bồ Đào Nha', 0, '[{"name":"Rita Loureiro","avatar":""},{"name":"Dinarte Branco","avatar":""},{"name":"Madalena Almeida","avatar":""},{"name":"Diogo Martins","avatar":""},{"name":"Henriqueta Maya","avatar":""},{"name":"José Peixoto","avatar":""},{"name":"Teresa Tavares","avatar":""},{"name":"Rita Poças","avatar":""},{"name":"Luís Lobão","avatar":""},{"name":"José Mata","avatar":""},{"name":"Albano Jerónimo","avatar":""},{"name":"Lourenço Ortigão","avatar":""},{"name":"José Condessa","avatar":""},{"name":"José Neto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
