INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('den-khi-cuoc-song-chia-lia', 'Đến Khi Cuộc Sống Chia Lìa', 'Until Life Do Us Part', 'đến khi cuộc sống chia lìa until life do us part rita loureiro dinarte branco madalena almeida diogo martins henriqueta maya josé peixoto teresa tavares rita poças luís lobão josé mata albano jerónimo lourenço ortigão josé condessa josé neto ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguy-co-tu-hai-phia', 'Nguy Cơ Từ Hai Phía', 'Double Threat', 'https://phimimg.com/upload/vod/20231231-1/d062a931228a9c9c84cdf64b2ea78afb.jpg', 'https://phimimg.com/upload/vod/20231231-1/77e37b94e3a7a40012ab8052eaa179e2.jpg', '<p>Jimmy (Matthew Lawrence) gần đây đã mất anh trai của mình và hứa sẽ rải tro của anh ấy xuống đại dương. Tuy nhiên, kế hoạch của anh ta bị trật bánh khi một cửa hàng tiện lợi bình thường trở thành một cuộc tấn công của đám đông nhằm vào nhân viên thu ngân Natasha (Danielle C. Ryan). Khi Jimmy cố gắng chạy trốn, anh ta phát hiện ra Natasha đang trốn ở ghế sau, và biết rằng cô ấy không phải là một nhân viên thu ngân ngẫu nhiên, mà là một phụ nữ đang chạy trốn khỏi đám đông với tính cách khác biệt: Nat và Tasha. Sau một hồi thuyết phục, Nat và Tasha gắn bó với Jimmy trong một chuyến đi xuyên quốc gia, hy vọng sẽ trốn thoát trên một chiếc thuyền đến Hawaii. Nhưng khi con trai của trùm tội phạm, Ellis (Kevin Joy), tham gia lực lượng với cánh tay phải của đám Ask (Dawn Olivieri), một cuộc rượt đuổi xuyên quốc gia bùng nổ và bạo lực.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 1, '[{"name":"Dawn Olivieri","avatar":""},{"name":"Matthew Lawrence","avatar":""},{"name":"Danielle C. Ryan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324307);
