INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-moi', 'Con Mồi', 'Prey', 'https://phimimg.com/upload/vod/20231209-1/7d5dffd0f1e96d091a8d88c2b14fdaf3.jpg', 'https://phimimg.com/upload/vod/20231209-1/35bdde6a20d9a9992235361a5f5d1ad5.jpg', '<p>Sau lần phát hành cuối cùng của Quái thú vô hình vào năm 2018, câu chuyện về sinh vật này đã được tái tạo. Lần này có Prey 2022 , người sẽ kể về sự xuất hiện của một Predator ngoài hành tinh trong thế giới loài người.Bộ phim kể về lịch sử lần đầu tiên những kẻ thù săn mồi đến thăm Trái đất cách đây 300 năm. Kẻ săn mồi bắt đầu khám phá hành tinh Trái đất và săn bắt động vật với con người vào năm 1719.Naru, một cô gái thuộc bộ tộc da đỏ Comanche dũng cảm và có ước mơ trở thành thợ săn. Bản thân Naru phải đối mặt với sự kỳ thị của những người phụ nữ vốn chỉ được đánh giá là chỉ biết lo việc nhà và nuôi dạy con cái.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"David Kross","avatar":""},{"name":"Hanno Koffler","avatar":""},{"name":"Maria Ehrich","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324307);
