INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('operation-seawolf', 'Operation Seawolf', 'Operation Seawolf', 'https://phimimg.com/upload/vod/20231231-1/ece214558474c8ca955724704d7fe080.jpg', 'https://phimimg.com/upload/vod/20231231-1/1b1124e65556a6ac2f7232f7272dc06d.jpg', '<p>Trong những ngày cuối cùng của Thế chiến thứ hai, Đức, tuyệt vọng tìm kiếm bất kỳ sự nắm bắt cuối cùng nào để đánh bại các cường quốc đồng minh, đã tìm đến những vũ khí và binh lính cuối cùng còn lại của họ. Hải quân Đức và những chiếc U-Boats cuối cùng còn lại được thành lập cùng nhau cho một nhiệm vụ cuối cùng tuyệt vọng - một nhiệm vụ tấn công Tổ quốc Hoa Kỳ, được gọi là Chiến dịch Seawolf. Thuyền trưởng Hans Kessler, một chỉ huy tàu ngầm hoa râm trong cả hai cuộc Thế chiến, được gọi vào phục vụ để thực hiện một nhiệm vụ thành công và giúp xoay chuyển cục diện của cuộc chiến.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hiram A. Murray","avatar":""},{"name":"Andrew Stecker","avatar":""},{"name":"Apostolos Gliarmis","avatar":""},{"name":"Dolph Lundgren","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Luke Steinborn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
