INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-nien-su-taco-quyen-3', 'Biên Niên Sử Taco (Quyển 3)', 'Taco Chronicles (Volume 3)', 'https://phimimg.com/upload/vod/20240109-1/5a9f27f7d889ee90c57f4e60e42f3801.jpg', 'https://phimimg.com/upload/vod/20240109-1/16ed88ff24eaa4992b0e197f60f9447a.jpg', '<p>Taco rời Mexico, nhưng Mexico không rời taco. Ở Hoa Kỳ, các đầu bếp Mexico vẫn gìn giữ món ăn truyền thống này cũng như thử nghiệm những hương vị mới.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324307);
