INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('burial', 'Burial', 'Burial', 'https://phimimg.com/upload/vod/20231230-1/aaee0abb28659f088813dd146db7d0c0.jpg', 'https://phimimg.com/upload/vod/20231230-1/c1a49ac719fb726f745b0ff430028720.jpg', '<p>Lấy bối cảnh những ngày cuối cùng của Thế chiến thứ hai, một nhóm nhỏ lính Nga do sĩ quan tình báo Brana Vasilyeva chỉ huy, người được giao nhiệm vụ buôn bán hài cốt của Hitler về cho Stalin ở Nga. Trên đường đi, đơn vị bị tấn công bởi những người thuộc phe Người sói của Đức và bị bắt từng người một. Brana dẫn dắt những người đồng đội còn sống sót của mình ở vị trí cuối cùng để đảm bảo ‘hàng hóa’ của họ không rơi vào tay những người sẽ thấy nó bị chôn vùi để che giấu sự thật mãi mãi.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlotte Vega","avatar":""},{"name":"Niamh Algar","avatar":""},{"name":"Diana Rigg","avatar":""},{"name":"Harriet Walter","avatar":""},{"name":"Barry Ward","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
