INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ricky-gervais-sieu-nhien', 'Ricky Gervais: Siêu Nhiên', 'Ricky Gervais: SuperNature', 'https://phimimg.com/upload/vod/20231230-1/51fc4501050e5b9c85afc90a5c9b8363.jpg', 'https://phimimg.com/upload/vod/20231230-1/6e93bd7094a6c1266cd05704c190046d.jpg', '<p>Trong chương trình đặc biệt thứ hai của anh trên Netflix, Ricky Gervais pha trò về quy tắc hài kịch, việc chiều hư đám mèo và siêu tự nhiên.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Ricky Gervais","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324307);
