INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-tai-thien-duong', 'Giáng Sinh Tại Thiên Đường', 'Christmas In Paradise', 'https://phimimg.com/upload/vod/20231230-1/39310014a8980ba72be83dc7cd85f3b1.jpg', 'https://phimimg.com/upload/vod/20231230-1/061e6641b063c118a573746de66108de.jpg', '<p>Kế hoạch của Joanna cho một kỳ nghỉ yên tĩnh, ấm cúng tan thành mây khói khi các chị gái của cô gọi điện thông báo rằng bố của họ đã bị vị hôn thê bỏ rơi và đã biến mất đến Nevis, một hòn đảo nhỏ ở Caribe, và không trả lời bất kỳ cuộc gọi nào. Hai chị em quyết định lên đảo để cứu cha và đưa ông về nhà đón Giáng sinh. Gia đình Giáng sinh mới được kết nối lại có thể sống sót qua một Giáng sinh điên rồ không?</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
