INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-nguoi-truong-thanh', 'Tình Yêu Người Trưởng Thành', 'Loving Adults', 'https://phimimg.com/upload/vod/20231227-1/09d398472f86e21c47df5261c826fe6b.jpg', 'https://phimimg.com/upload/vod/20231227-1/fc27568e9855bd55067324f83f439b0a.jpg', '<p>Ranh giới mong manh giữa yêu và ghét hóa thành chết chóc khi người vợ phát hiện chồng ngoại tình – và cả hai đều dùng đến các biện pháp cực đoan để đạt được điều họ muốn.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Dar Salim","avatar":""},{"name":"Sonja Richter","avatar":""},{"name":"Sus Wilkins","avatar":""},{"name":"Mikael Birkkjær","avatar":""},{"name":"Katinka Petersen","avatar":""},{"name":"Lars Ranthe","avatar":""},{"name":"Milo Campanale","avatar":""},{"name":"Iris Mealor Olsen","avatar":""},{"name":"Morten Burian","avatar":""},{"name":"Salomon Stampe","avatar":""},{"name":"Susanne Storm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
