INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-deo-giay-marcel', 'Chú Chó Đeo Giày Marcel', 'Marcel The Shell With Shoes On', 'https://phimimg.com/upload/vod/20231227-1/6f9f32793ff46f909c831926b2276231.jpg', 'https://phimimg.com/upload/vod/20231227-1/3def762abe9bd5f7e12f4b750ea0da9c.jpg', '<p>Marcel là một chú chó có vỏ cao một inch đáng yêu, người đã tạo ra một sự tồn tại đầy màu sắc cùng với bà nội của mình là Connie và cây lông thú cưng của họ, Alan. Từng là một phần của cộng đồng vỏ sò rộng lớn, giờ đây họ sống một mình với tư cách là những người sống sót duy nhất sau một thảm kịch bí ẩn. Nhưng khi một nhà làm phim tài liệu phát hiện ra họ giữa đống lộn xộn trên Airbnb của mình, đoạn phim ngắn mà anh ấy đăng trực tuyến đã mang đến cho Marcel hàng triệu người hâm mộ cuồng nhiệt, cũng như những nguy hiểm chưa từng có và một hy vọng mới trong việc tìm lại gia đình đã thất lạc từ lâu của anh ấy.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jenny Slate","avatar":""},{"name":"Dean Fleischer-Camp","avatar":""},{"name":"Isabella Rossellini","avatar":""},{"name":"Thomas Mann","avatar":""},{"name":"Rosa Salazar","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
