INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-lieu-kashmir', 'Tài Liệu Kashmir', 'The Kashmir Files', 'https://phimimg.com/upload/vod/20231230-1/eb9c3a2d7700a7148c91522edfd4e8f4.jpg', 'https://phimimg.com/upload/vod/20231230-1/8bbeec395de18dce4f4f12fe23cb333f.jpg', '<p>Dựa trên một bi kịch có thật, bộ phim gây xúc động làm sáng tỏ hoàn cảnh khó khăn của Kashmiri Pandits (người theo đạo Hindu), một thiểu số tôn giáo ở thung lũng Kashmir những năm 1990, những người đã bị các chiến binh Hồi giáo buộc phải rời bỏ nhà cửa của họ.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Mithun Chakraborty","avatar":""},{"name":"Anupam Kher","avatar":""},{"name":"Darshan Kumaar","avatar":""},{"name":"Pallavi Joshi","avatar":""},{"name":"Chinmay Mandlekar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
