INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-khuyen', 'Bạch Khuyển', 'White Dog', 'https://phimimg.com/upload/vod/20231230-1/8dea7aa26f4ccb9ae658c426214b4749.jpg', 'https://phimimg.com/upload/vod/20231230-1/add0b8015aa53862b93606646ff53668.jpg', '<p>Khi đất nước bùng nổ căng thẳng chủng tộc sau vụ ám sát Martin Luther King, nhà văn Romain Gary, nhà nhân văn và người yêu động vật, và vợ ông, ngôi sao Jean Seberg, nhà hoạt động dân quyền, chào đón một chú chó bị bỏ rơi vào nhà của họ, được huấn luyện để nhảy vào miệng của người da đen: một con chó trắng.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Denis Ménochet","avatar":""},{"name":"Kacey Rohl","avatar":""},{"name":"K.C. Collins","avatar":""},{"name":"Jhaleil Swaby","avatar":""},{"name":"Laurent Lemaire","avatar":""},{"name":"Peter Bryant","avatar":""},{"name":"Chip Chuipka","avatar":""},{"name":"Michaëna Benoit","avatar":""},{"name":"Melissa Toussaint","avatar":""},{"name":"Pascal Tshilambo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
