INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-man-lua', 'Dưới Màn Lửa', 'Under Fire (Onder Vuur)', 'https://phimimg.com/upload/vod/20240109-1/21c66d553bf9879fe5443b1efdbdaf39.jpg', 'https://phimimg.com/upload/vod/20240109-1/0be8376c531f23bedf26f1f81d2d2145.jpg', '<p>Tại trạm East Bank, một đội lính cứu hỏa thân thiết phải xoay xở với công việc nguy hiểm, nhiều áp lực, những thử thách cá nhân và trở ngại trong sự nghiệp.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'ongoing', 17, 2022, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Louis Talpe","avatar":""},{"name":"Lien de Grave","avatar":""},{"name":"Sam Louwyck","avatar":""},{"name":"Katelijne Verbeke","avatar":""},{"name":"Dirk Van Dijck","avatar":""},{"name":"Maarten Ketels","avatar":""},{"name":"Alessia Sartor","avatar":""},{"name":"Aimé Claeys","avatar":""},{"name":"Sahin Avci","avatar":""},{"name":"Wouter Bruneel","avatar":""},{"name":"Ann Tuts","avatar":""},{"name":"Piet De Praitere","avatar":""},{"name":"Kasper Vandenberghe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
