INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('duoi-man-lua', 'Dưới Màn Lửa', 'Under Fire (Onder Vuur)', 'dưới màn lửa under fire (onder vuur) louis talpe lien de grave sam louwyck katelijne verbeke dirk van dijck maarten ketels alessia sartor aimé claeys sahin avci wouter bruneel ann tuts piet de praitere kasper vandenberghe ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('johnny', 'Johnny', 'Johnny', 'https://phimimg.com/upload/vod/20231230-1/0f97d794fc8ede65588e038882e5e0ef.jpg', 'https://phimimg.com/upload/vod/20231230-1/43ee40e4566dc74f7e4b46868842effd.jpg', '<p>Patryk đột nhập vào một ngôi nhà ở một thị trấn nhỏ. Anh ta bị kết án phục vụ cộng đồng tại nhà tế bần ở Puck, nơi anh ta gặp người cha Jan Kaczkowski, một người khá khác thường. Vị linh mục lôi kéo những cậu bé từ trường dạy nghề, những người có vẻ là những kẻ nổi loạn cứng rắn, giúp đỡ những người mắc bệnh nan y. Trong công việc của mình, anh ấy tập trung vào sự thân mật, tình cảm và cuộc đấu tranh để thiết lập mối quan hệ với người khác. Ông dạy sự đồng cảm. Và anh ấy làm điều đó với một khiếu hài hước tuyệt vời, điều này khiến anh ấy rất nổi tiếng. Ngay sau đó, chính cha Jan trở thành bệnh nhân trong nhà tế bần. Patryk được đặt vào một vị trí sẽ thay đổi toàn bộ cuộc đời anh. Dựa trên một câu chuyện có thật.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Dawid Ogrodnik","avatar":""},{"name":"Piotr Trojan","avatar":""},{"name":"Beata Zygarlicka","avatar":""},{"name":"Grażyna Bułka","avatar":""},{"name":"Maria Pakulnis","avatar":""},{"name":"Joachim Lamża","avatar":""},{"name":"Marta Stalmierska","avatar":""},{"name":"Jakub Nosiadek","avatar":""},{"name":"Anna Dymna","avatar":""},{"name":"Witold Dębicki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
