INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-o-nha-tre', 'Đêm Ở Nhà Trẻ', 'A Night At The Kindergarten', 'https://phimimg.com/upload/vod/20231230-1/c404817a3bdb047001d2f80e96ee1e5d.jpg', 'https://phimimg.com/upload/vod/20231230-1/377553263d7143ac09af5133f312d57a.jpg', '<p>Chàng trai trẻ nọ không mời mà đến một buổi diễn tập kịch ở trường để ngăn một nhóm giáo viên và phụ huynh lập dị đuổi học con trai của bạn gái anh.</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Piotr Witkowski","avatar":""},{"name":"Lena Góra","avatar":""},{"name":"Zbigniew Zamachowski","avatar":""},{"name":"Aleksandra Domańska","avatar":""},{"name":"Dobromir Dymecki","avatar":""},{"name":"Matylda Damięcka","avatar":""},{"name":"Maciej Nawrocki","avatar":""},{"name":"Sylwia Boroń","avatar":""},{"name":"Piotr Borowski","avatar":""},{"name":"Julia Wyszyńska","avatar":""},{"name":"Masza Wągrocka","avatar":""},{"name":"Marcel Krzemiński","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324307);
