INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luong-kiem-quyet-chien-quy-khoc-coc', 'Lượng Kiếm: Quyết Chiến Quỷ Khốc Cốc', 'Drawing Sword：Fighting Ghost Cry', 'https://phimimg.com/upload/vod/20231219-1/54b067b7284f49e785da260e3e06db16.jpg', 'https://phimimg.com/upload/vod/20231219-1/a28a4a4b4fa9fe6ab85afbcab43bfbb1.jpg', '<p>Đầu năm 1942, quân Nhật điên cuồng càn quét khu căn cứ ở Tây Bắc Sơn Tây. Để chống lại sự ngạo mạn của quân đội Nhật Bản, Lí Vân Long đã chỉ huy một trung đoàn độc lập tấn công huyện Bình An. Quân Nhật từ các ngả lần lượt đến ứng cứu, bị quân của Lí Vân Long chặn đánh hết. Lí Chính Hổ được chỉ thị dẫn một đại đội kỵ binh đến khe núi Tuyết Lang phòng thủ, dựa vào địa hình đặc biệt, ông đã chiến đấu hết mình với quân Nhật và hy sinh anh dũng, giúp lực lượng tấn công chủ lực của Lí Vân Long đánh chiếm thành công huyện Bình An, gây thiệt hại nặng nề cho quân địch...</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Luo Li Qun","avatar":""},{"name":"Zhang Chu Xuan","avatar":""},{"name":"You Li","avatar":""},{"name":"Zhang Guang Bei","avatar":""},{"name":"Weihua Zhan","avatar":""},{"name":"Li Meng Nan","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324307);
