INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giua-lung-chung', 'Giữa Lưng Chừng', 'The In Between', 'https://phimimg.com/upload/vod/20231219-1/485c6b2939d54cdc9786bd03164dddab.jpg', 'https://phimimg.com/upload/vod/20231219-1/6cd7650eb76bb0f082e132b6b2e0a8dc.jpg', '<p>Sau khi sống sót sau một vụ tai nạn xe hơi cướp đi sinh mạng của bạn trai, một cô gái tuổi teen tin rằng anh ấy đang cố gắng kết nối lại với cô ấy từ thế giới bên kia.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joey King","avatar":""},{"name":"Kyle Allen","avatar":""},{"name":"Kim Dickens","avatar":""},{"name":"John Ortiz","avatar":""},{"name":"Celeste O''Connor","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
