INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-thoi-den-tinh-tuyet-co-thanh-dien-anh', 'Ma Thổi Đèn: Tinh Tuyệt Cổ Thành (Điện Ảnh)', 'Candle In The Tomb', 'https://phimimg.com/upload/vod/20231219-1/88387a3bd75a9be3f640bf4a0cd5beb4.jpg', 'https://phimimg.com/upload/vod/20231219-1/69526032ea265ee42a6f8bb96294f8aa.jpg', '<p>Nhiều năm trước, nhóm người Hồ Bát Nhất bị sinh vật lạ tấn công ở dãy núi Côn Luân, chỉ có một mình Hồ Bát Nhất may mắn thoát nạn. Shirley Dương từ Mỹ trở về, mời Hồ Bát Nhất cùng đến thành cổ Tinh Tuyệt, tìm kiếm chân tướng việc cha của Shirley Dương và bạn bè của Hồ Bát Nhất gặp nạn...</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yu Yi","avatar":""},{"name":"Fu Mei","avatar":""},{"name":"Kong Lianshun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324307);
