INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('whitney-houston-i-wanna-dance-with-somebody', 'Whitney Houston: I Wanna Dance With Somebody', 'Whitney Houston: I Wanna Dance With Somebody', 'https://phimimg.com/upload/vod/20231219-1/8372d0cc45b06823707d2bb4de26d431.jpg', 'https://phimimg.com/upload/vod/20231219-1/2d3f866d3b2ab226056f0eb14f408d58.jpg', '<p>Bức chân dung phức tạp này dõi theo hành trình của ca sĩ có một không hai Whitney Houston, từ cô gái trong dàn hợp xướng ở New Jersey vươn lên thành siêu sao quốc tế.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Naomi Ackie","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Ashton Sanders","avatar":""},{"name":"Tamara Tunie","avatar":""},{"name":"Nafessa Williams","avatar":""},{"name":"Clarke Peters","avatar":""},{"name":"Daniel Washington","avatar":""},{"name":"Bria Danielle Singleton","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
