INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('whitney-houston-i-wanna-dance-with-somebody', 'Whitney Houston: I Wanna Dance With Somebody', 'Whitney Houston: I Wanna Dance With Somebody', 'whitney houston: i wanna dance with somebody whitney houston: i wanna dance with somebody naomi ackie stanley tucci ashton sanders tamara tunie nafessa williams clarke peters daniel washington bria danielle singleton ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-menh-than-yeu', 'Sinh Mệnh Thân Yêu', 'Beloved Life', 'https://phimimg.com/upload/vod/20231219-1/289f505ddc75cb59a17e4ad0c8c70043.jpg', 'https://phimimg.com/upload/vod/20231219-1/0f56683c3f916760d2aa1862a8ce95a7.jpg', '<p>Bộ phim là câu chuyện về sự nghiệp và tình cảm của hai nữ bác sĩ nội trú trẻ trong ngành sản phụ khoa Đỗ Đế và Ngô Thông Duệ. Bộ phim cho chúng ta thấy phụ nữ dưới 30 tuổi có thể tự nhận thức và trưởng thành như thế nào khi đối mặt với những khó khăn và lo lắng về hôn nhân, sinh con và sự nghiệp. Đồng thời, với những câu chuyện về nhiều nữ bệnh nhân khác nhau trong khoa sản phụ khoa và bệnh viện sản phụ khoa làm nền của câu chuyện, nó làm bức tranh toàn cảnh về gia đình và xã hội, và miêu tả trạng thái thể chất và tinh thần và điều kiện sống của phụ nữ Trung Quốc ở các tầng lớp và lứa tuổi khác nhau. Khi cứu bệnh nhân, Đỗ Đế và Ngô Thông Duệ không chỉ cho mọi người thấy được giá trị nghề nghiệp của họ mà họ còn hiểu được giá trị của tình bạn và tình yêu. Bộ phim thể hiện phẩm chất cao đẹp về lòng nhân hậu của các y, bác sĩ trẻ, tinh thần đấu tranh tích cực của thanh niên đương thời, truyền cảm hứng yêu đời, yêu nghề.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tống Thiến","avatar":""},{"name":"Xiaochen Wang","avatar":""},{"name":"Doãn Phưỡng","avatar":""},{"name":"Myolie Wu","avatar":""},{"name":"Wilson","avatar":""},{"name":"Tony Xu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324307);
