INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-hua-bat-tu', 'Lời Hứa Bất Tử', 'The Immortal Promise', 'https://phimimg.com/upload/vod/20231219-1/61e1a7b0bcc5ed1fdad6afe13d95e950.jpg', 'https://phimimg.com/upload/vod/20231219-1/3bcfaffdbba8bd81f66e903e6f535f3e.jpg', '<p>Điệp viên ngàn mặt Zhou Qingzhu bị hoàng tử đáng tin cậy Li Ye coi là vật tế thần, và được Zhang Xiaomei, chỉ huy của Beiyi Division, giải cứu trong một tình huống tuyệt vọng. Cả hai cùng nhau canh gác mái hiên, tình yêu của họ dần nảy nở, nhưng Li Ye đã lấy lòng tốt đe dọa cô và buộc cô phải cướp Qianxia Sauvignon từ Zhang Xiaomei. Zhou Qingzhu cả đời khốn khổ, không người nương tựa, dần dần rơi vào sự dịu dàng thấp thoáng của Zhang Xiaomei, Zhang Xiaomei gánh vác trách nhiệm nặng nề và kiềm chế bản thân, nhưng cô không thể buông bỏ sự huy hoàng của Zhou Qingzhu. Gia đình, thù hận, quan hệ trực diện, quyền lực hoàng gia ... xiềng xích bị chặn giữa hai người, và cả hai không ngừng tiến về phía trước, chỉ để ở bên nhau trong giây lát.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chu Lệ Lan","avatar":""},{"name":"Lý Phỉ","avatar":""},{"name":"Trương Tịnh Vân","avatar":""},{"name":"Chu Vi Vi","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324307);
