INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nho-to-chon-van-phong', 'Nhỏ To Chốn Văn Phòng', 'Office Gossip', 'https://phimimg.com/upload/vod/20231219-1/b8cd2f5cdf016302e40185df59734534.jpg', 'https://phimimg.com/upload/vod/20231219-1/96b3a9bbcf340c3952562a8c97e1eaf2.jpg', '<p>Trong một văn phòng ngập tràn những cá tính riêng biệt và đầy màu sắc, các nhân viên trẻ cùng hỗ trợ nhau xoay xở với đủ loại trở ngại của cuộc sống.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 13, 2022, 'Lồng Tiếng', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Nguyễn Thùy Anh","avatar":""},{"name":"Marando","avatar":""},{"name":"Minh Khánh","avatar":""},{"name":"Nguyễn Thùy Dương","avatar":""},{"name":"Quan Phúc Toàn","avatar":""},{"name":"Khương Hưng","avatar":""},{"name":"Đỗ Nguyễn Thạch Thảo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324307);
