INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thao-thuc-dem-he', 'Thao Thức Đêm Hè', 'Along For The Ride', 'https://phimimg.com/upload/vod/20231215-1/7aea53c4a2c622a21dbeb2ff692f274a.jpg', 'https://phimimg.com/upload/vod/20231215-1/96e30c9ff4409331d67a873edc2bca1a.jpg', '<p>Mùa hè trước khi vào đại học, Auden mọt sách gặp Eli bí ẩn. Qua các buổi đi chơi đêm, anh giúp cô trải nghiệm cuộc sống thiếu nữ vô tư mà cô đã bỏ lỡ.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emma Pasarow","avatar":""},{"name":"Belmont Cameli","avatar":""},{"name":"Kate Bosworth","avatar":""},{"name":"Andie MacDowell","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Laura Kariuki","avatar":""},{"name":"Marcus Scribner","avatar":""},{"name":"Genevieve Hannelius","avatar":""},{"name":"Samia Finnerty","avatar":""},{"name":"Ricardo Hurtado","avatar":""},{"name":"Paul Karmiryan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
