INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ranh-gioi-an-toan', 'Ranh Giới An Toàn', 'Khem Sorn Plai', 'https://phimimg.com/upload/vod/20231219-1/7887566042fec99c4fd5634578eaef28.jpg', 'https://phimimg.com/upload/vod/20231219-1/cdc8c9a97bdbd7a091a41aa7ea57f8ba.jpg', '<p>Xoay quanh chuyện tình nhiều rắc rối của Cherd và Lanna. Cả hai yêu nhau khi Cherd vẫn đang trong cuộc hôn nhân bế tắc với bác sĩ Ruengboon. Tuy nhiên, bác sĩ Ruengboon từ chối ly hôn Cherd. Nghĩ mình hết hi vọng, Lanna chia tay Cherd, kết hôn với Yaowayod, một phụ nữ trẻ hoàn hảo cả về ngoại hình lẫn địa vị xã hội. Nhưng Lanna vẫn không thể quên được Cherd và tiếp tục âm thầm giữ cô gái đỏng đảnh trong lòng. Sau này, khi Cherd ly hôn chồng, Lanna muốn nối lại quan hệ với cô nhưng cũng không muốn ly hôn vợ.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 9, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Kitkong Khamkrith","avatar":""},{"name":"Varithisa Limthammahisorn","avatar":""},{"name":"Woranuch Bhirombhakdi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324307);
