INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-si-dac-biet-phan-5-nga-tu-vo-tan', 'Vệ Sĩ Đặc Biệt Phần 5: Ngã Tư Vô Tận', 'Infinite Blocks', 'https://phimimg.com/upload/vod/20231213-1/4e7bc5c758997cd269e60af62400ca9e.jpg', 'https://phimimg.com/upload/vod/20231213-1/65d89711dda8473139576c29a3a3abb8.jpg', '<p>Ôn Cách Luân người mất trí nhớ không hiểu sao bị bắt phải thực hiện một nhiệm vụ tử thần. Cậu tức giận phẩn đối kịch liệt, khi tham gia nhiệm vụ thì trí nhớ của cậu dần dần phục hồi. Nhớ lại nhiệm vụ của mình, anh ta sẽ phải đối mặt với một thử thách khó khăn hơn, sống sót hay chết chóc, anh ta sẽ lựa chọn như thế nào?</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Steven Hao","avatar":""},{"name":"Ren Tian Qi","avatar":""},{"name":"J.C","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
