INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-than-tien-o-new-york-2', 'Chuyện Thần Tiên Ở New York 2', 'Disenchanted', 'https://phimimg.com/upload/vod/20231212-1/5226f703b45c4940b41a1e862e23853c.jpg', 'https://phimimg.com/upload/vod/20231212-1/50339c1c189ed38c6f206d6f50cfb15c.jpg', '<p>Đã mười lăm năm kể từ khi Giselle và Robert kết hôn, nhưng Giselle đã dần vỡ mộng với cuộc sống ở thành phố. Họ quyết định chuyển gia đình đang phát triển của mình đến cộng đồng ngoại ô buồn ngủ Monroeville để tìm kiếm một cuộc sống cổ tích hơn - thật không may, đó không phải là giải pháp nhanh chóng mà cô ấy mong đợi. Vùng ngoại ô có một bộ quy tắc hoàn toàn mới và một con ong chúa địa phương, Malvina Monroe, người khiến Giselle cảm thấy lạc lõng hơn bao giờ hết. Thất vọng vì hạnh phúc mãi mãi không dễ tìm thấy, cô tìm đến phép thuật của Andalasia để được giúp đỡ, vô tình biến toàn bộ thị trấn thành một câu chuyện cổ tích ngoài đời thực, khiến hạnh phúc tương lai của gia đình cô gặp nguy hiểm. Giờ đây, Giselle đang chạy đua với thời gian để đảo ngược câu thần chú và xác định hạnh phúc mãi mãi về sau thực sự có ý nghĩa như thế nào đối với cô và gia đình.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Dempsey","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Rachel Covey","avatar":""},{"name":"Idina Menzel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324307);
