INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anythings-possible', 'Anything''s Possible', 'Anything''s Possible', 'https://phimimg.com/upload/vod/20231212-1/f9b5307a9c451035c78e28b3b357dc3b.jpg', 'https://phimimg.com/upload/vod/20231212-1/3f6715f9feabbaa6a4ec054da1796e68.jpg', '<p>Anything’s Possible là một câu chuyện thú vị dành cho lứa tuổi mới lớn thế hệ Z kể về Kelsa, một nữ sinh trung học tự tin đã chuyển giới khi bước qua năm cuối cấp. Khi người bạn cùng lớp của cô là Khal phải lòng cô, anh đã lấy hết can đảm để mời cô đi chơi, bất chấp bộ phim mà anh biết nó có thể gây ra. Những gì diễn ra là một câu chuyện tình lãng mạn thể hiện niềm vui, sự dịu dàng và nỗi đau của tình yêu trẻ.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eva Reign","avatar":""},{"name":"Abubakr Ali","avatar":""},{"name":"Renée Elise Goldsberry","avatar":""},{"name":"Courtnee Carter","avatar":""},{"name":"Kelly Lamor Wilson","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
