INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-thoi-tien-su', 'Hành Tinh Thời Tiền Sử', 'Prehistoric Planet', 'https://phimimg.com/upload/vod/20231219-1/daa3d7b557ef3e1af835e68f0b3b9b85.jpg', 'https://phimimg.com/upload/vod/20231219-1/77808a634238fd9a269b53d44efc5388.jpg', '<p>Trải nghiệm những điều kỳ diệu của thế giới chúng ta chưa từng có trong kho tài liệu sử thi này của Jon Favreau và các nhà sản xuất của Planet Earth. Du hành ngược 66 triệu năm về thời kỳ khủng long hùng vĩ và những sinh vật phi thường lang thang trên các vùng đất, vùng biển và bầu trời.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 9, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324307);
