INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ammu', 'Ammu', 'Ammu', 'https://phimimg.com/upload/vod/20240104-1/977f0c1aa37217a9a923f13422cfea94.jpg', 'https://phimimg.com/upload/vod/20240104-1/46450cc9a10145324d36480f5e0706a3.jpg', '<p>Những tưởng cuộc hôn nhân của Ammu là một câu chuyện cổ tích - đầy tình yêu và phép thuật, kết thúc khi người chồng cảnh sát Ravi của cô đánh cô lần đầu tiên. Những gì Ammu nghĩ là một sự cố chỉ xảy ra một lần sớm trở thành một chu kỳ lạm dụng không bao giờ kết thúc, bẫy cô ấy và phá vỡ linh hồn và tinh thần của cô ấy. Bị đẩy đến giới hạn của mình, Ammu hợp tác với một đồng minh khó có thể thoát ra.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Aishwarya Lekshmi","avatar":""},{"name":"Naveen Chandra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
