INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ngam-tokyo', 'Thế Giới Ngầm Tokyo', 'Tokyo Vice', 'https://phimimg.com/upload/vod/20231219-1/a860c1fb46a9ba8f84c6f8fbd445fd8f.jpg', 'https://phimimg.com/upload/vod/20231219-1/08d1692cfc73cfd312d322f30205c7ab.jpg', '<p>Thế Giới Ngầm Tokyo&nbsp;- Tokyo Vice (2022) là người Mỹ đầu tiên được vào làm tại tòa báo Meicho Shimbun, Jake Adelstein không ngừng nỗ lực để có thể làm tốt và thể hiện tài năng của bản thân. Đúng lúc này anh được cấp trên giao cho thực hiện bài viết về hai vụ việc khồng hề liên quan gì đến nhau, xong trong quá trình tìm hiểu thì Jake Adelstein nhận ra sự liên kết giữa các manh mối. Lúc này, Jake Adelstein quyết định đánh cược sự nghiệp và tính mạng của bản thân vào công việc.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ansel Elgort","avatar":""},{"name":"Ken Watanabe","avatar":""},{"name":"Rachel Keller","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324307);
