INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-hen-ho-thu-n', 'Lần Hẹn Hò Thứ N', 'Lần Hẹn Hò Thứ N', 'https://phimimg.com/upload/vod/20231219-1/408d64f4dfbe89b33bb5270511c2dfcf.jpg', 'https://phimimg.com/upload/vod/20231219-1/93028043656ef57eb90711410c18698d.jpg', '<p>Thiên Mỹ là một cô nàng diễn viên xinh đẹp, phong cách và thời thượng. Được nhiều người ngưỡng mộ nhưng đồng thời cô cũng nổi tiếng là đang ế. Lý do là cô khá cầu toàn trong chuyện tình yêu. Mỗi tập phim sẽ là một lần hẹn hò của Thiên Mỹ với một người đàn ông. Liệu cô có tìm được ý trung nhân của mình?</p>', 'Hoàn Tất (9/9)', 9, 'tvshows', 'completed', 18, 2022, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Khả Như","avatar":""},{"name":"Bi Max","avatar":""},{"name":"Tim","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324307);
