INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-dien-binh-vuong-trinh-thanh-cong', 'Truyền Thuyết Diên Bình Vương Trịnh Thành Công', 'The Hero Named Koxinga', 'https://phimimg.com/upload/vod/20231210-1/fc1a4920e05d3c94133c2ac6766560db.jpg', 'https://phimimg.com/upload/vod/20231210-1/14b5976771490061162eade2c0bd1c6d.jpg', '<p>Vào năm Long Vũ thứ hai thời Nam Minh, quân Thanh tiến xuống phía nam tấn công thành và chiếm đất, khói lửa mịt mù súng nổ muôn nơi, Diêm Bình Vương Trịnh Thành Công đã lãnh đạo đội quân, chiến đấu bảo vệ lãnh thổ. Bất chấp hàng loạt biến cố diễn ra, cha đầu hàng, mẹ bị giết hại và sự phản bội của chú mình, Thành Công vẫn tuân theo lời thề bảo vệ đất nước và không bao giờ lùi bước!</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Trung Quốc', 1, '[{"name":"Phàn Thiếu Hoàng","avatar":""},{"name":"Kan Xin","avatar":""},{"name":"Shane","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324307);
