INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tom-va-jerry-cao-boi-len', 'Tom và Jerry, Cao Bồi Lên!', 'Tom And Jerry: Cowboy Up', 'https://phimimg.com/upload/vod/20231211-1/f9550f54ed8ed59253fff4903e8610ea.jpg', 'https://phimimg.com/upload/vod/20231211-1/38e7b1ada39b394e40e6e748e21ffab5.jpg', '<p>Lần này, các đối thủ hợp sức để giúp một cô gái chăn bò và anh trai của cô ấy cứu ngôi nhà của họ khỏi một tên cướp đất tham lam và họ sẽ cần một số trợ giúp! Ba đứa cháu trai sớm của Jerry đều đã sẵn sàng hành động, còn Tom thì thành lập một đàn chó đồng cỏ. Nhưng liệu một băng ragtag gồm những người đánh véc-ni có thể đánh bại một kẻ liều lĩnh gian dối quyết tâm đánh lừa một tên khốn đang gặp nạn không? Không có vấn đề gì xảy ra với Tom và Jerry trong yên ngựa, đó sẽ là thời điểm tốt!</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"William Hanna","avatar":""},{"name":"Kath Soucie","avatar":""},{"name":"George Ackles","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324307);
