INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-than-tham-enola-holmes-2', 'Nữ Thần Thám Enola Holmes 2', 'Enola Holmes 2', 'https://phimimg.com/upload/vod/20231211-1/06974fb131b7cb628ebf3703bd9e4c84.jpg', 'https://phimimg.com/upload/vod/20231211-1/c5b110dfa9a1096a5370b65ce115926c.jpg', '<p>Tiếp theo sự thành công của Nữ Thần Thám Enola Holmes 1 thì ở phần 2 này nói về Enola Holmes đảm nhận trường hợp đầu tiên của cô với tư cách là một thám tử, nhưng để làm sáng tỏ bí ẩn về một cô gái mất tích, cô sẽ cần sự giúp đỡ từ bạn bè và anh trai Sherlock.</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Millie Bobby Brown","avatar":""},{"name":"Henry Cavill","avatar":""},{"name":"Helena Bonham Carter","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324307);
