INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moonshot', 'Moonshot', 'Moonshot', 'https://phimimg.com/upload/vod/20231211-1/97212ee36fcd93de4fa27a3e88c6d088.jpg', 'https://phimimg.com/upload/vod/20231211-1/eacb53cce43823fca53cc23df53930ef.jpg', '<p>Walt làm nhân viên pha chế trong khuôn viên trường đại học vào năm 2049. Ước mơ đi vào vũ trụ của anh ấy đã trở thành hiện thực với sự ra đời của Kovi Industries Student Mars Program, một tổ chức đưa sinh viên đại học lên sao Hỏa. Sự thiếu kiến thức và chuyên môn của anh ấy là lý do khiến chương trình từ chối lời đề nghị của anh ấy 37 lần. Trong một bữa tiệc ở trường đại học, anh ta vô tình phá vỡ mạng internet cho một sinh viên vô nghĩa đang yêu một người đàn ông trên sao Hỏa. Trong khi ở bữa tiệc, anh ấy đã yêu một sinh viên khác, Ginny, người được gửi đến sao Hỏa vào sáng hôm sau. Vài tuần sau khi Calvin chấp nhận ở lại Sao Hỏa lâu hơn, Walt thuyết phụcSophie mua vé để đi du lịch trong lần phóng tàu con thoi tiếp theo, khi cô ấy khóc tại quán cà phê của anh ấy trong nước mắt vì Calvin chấp nhận ở lại Sao Hỏa lâu hơn. Khi cô đến gần cổng phóng, Walt thao túng cô giúp anh lẻn lên tàu con thoi bằng cách giả làm một thành viên trong gia đình, nhưng bất ngờ khi họ phải tuyên bố đang có mối quan hệ trên tàu con thoi để giữ bí mật về danh tính của anh. Trong suốt chuyến đi đến sao Hỏa, cả hai ngày càng thân thiết hơn, khi họ tìm hiểu thêm về Calvin khi anh ta tuyên bố danh tính của mình, và khi cô biết được con người thật của mình, có thể Calvin đã đặt cô đứng thứ hai sau ước mơ cải tạo sao Hỏa để trở nên hiếu khách hơn. Trong một buổi thuyết trình trên máy bay, Walt buộc phải thuyết trình về địa hình, một chủ đề mà anh ta không biết gì về nó, nhưng thuyết phục hai hành khách kết hôn khi bài phát biểu về tình yêu của anh ta khiến khán giả, bao gồm cả chính anh ta xúc động.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cole Sprouse","avatar":""},{"name":"Lana Condor","avatar":""},{"name":"Mason Gooding","avatar":""},{"name":"Emily Rudd","avatar":""},{"name":"Zach Braff","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324307);
