INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('joyride', 'Joyride', 'Joyride', 'https://phimimg.com/upload/vod/20231211-1/e3c1abf9696b1c7322434dd9c3d959ec.jpg', 'https://phimimg.com/upload/vod/20231211-1/0e873ed454bca157aa9586b8aa130aac.jpg', '<p>Một vụ đắm tàu trong một cuộc phiêu lưu sẵn sàng cho đi đứa con mới chào đời của mình. Được tham gia bởi một chú nhím đường phố táo tợn, họ là hai viên kim cương thô trên đường chạy trốn.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlie Ray Reid","avatar":""},{"name":"Olivia Colman","avatar":""},{"name":"Olwen Fouéré","avatar":""},{"name":"Florence Adebambo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
