INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-sach-mua-sam-cua-ke-sat-nhan', 'Danh Sách Mua Sắm Của Kẻ Sát Nhân', 'The Killer''s Shopping List', 'https://phimimg.com/upload/vod/20231219-1/4c0fe8c4efde7d24abb29156e77bc56d.jpg', 'https://phimimg.com/upload/vod/20231219-1/ebfca7d20a426ccffaf7ae83cd13c958.jpg', '<p>Bộ phim truyền hình Hàn Quốc \Danh Sách Mua Sắm Của Kẻ Sát Nhân\ được chuyển thể từ tiểu thuyết cùng tên của Kang Ji-young, do đạo diễn Lee Eon Hee và biên kịch biên kịch Han Ju Wan\nBộ phim truyền hình này là một bộ phim truyền hình kinh dị thực tế kể về nhiều tội ác khác nhau như lạm dụng trẻ em... ở những khu dân cư dường như quen thuộc trong thời đại mà chúng ta chỉ biết bề nổi nhưng không biết hết được rõ ràng toàn cảnh sự việc.\nCốt truyện bắt đầu với việc phát hiện ra một thi thể trong một căn hộ ở ngoại ô Seoul. Nhân vật chính là một thực tập sinh ở siêu thị, cảnh sát viên và chủ siêu thị, câu chuyện xoay quanh vụ án với một biên lai siêu thị xuất hiện tại hiện trường.\nLee Kwang Soo đóng vai Ahn Dae Sung thực tập sinh siêu thị MS ; Kim Seol Hyun đóng vai Do Ah Hee là một cảnh sát viên và là bạn gái của Dae Sung; Jin Hee Kyung đóng vai Jung Myung Sook là chủ siêu thị MS và là mẹ của Dae Sung.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Kwang Soo","avatar":""},{"name":"Kim SeolYeon","avatar":""},{"name":"진희경","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d