INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-noi-cho-toi-dieu-uoc-cua-ban', 'Hãy Nói Cho Tôi Điều Ước Của Bạn', 'If You Wish Upon Me', 'https://phimimg.com/upload/vod/20231219-1/0c71a4ffc301d41eac284ee0892c3bba.jpg', 'https://phimimg.com/upload/vod/20231219-1/c0ea46cc6b3bb73dff5e0c97d5005812.jpg', '<p>Bộ phim truyền hình này được lấy cảm hứng từ Quỹ điều ước cứu thương, ban đầu được thành lập ở Hà Lan. Chương trình từ thiện trao những điều ước cho những bệnh nhân mắc bệnh nan y.Câu chuyện xoay quanh một chàng trai trẻ Yoon Gyeo Rye (Ji Chang Wook), người đang gặp nguy hiểm đến tính mạng, vào bệnh viện tế bần theo lệnh phục vụ cộng đồng và cùng với các nhân viên bệnh viện lắng nghe nguyện vọng cuối cùng của mọi người. vào cuối cuộc đời của họ một cách tươi sáng và vui vẻ qua các tập phim khác nhau.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Won Ji Ahn","avatar":""},{"name":"Yang Hee Kyung","avatar":""},{"name":"Gil Hae Yeon","avatar":""},{"name":"Yoo Soon Woon","avatar":""},{"name":"Jeon Chae Eun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324307);
