INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-khat-vong', 'Trò Chơi Khát Vọng', 'Rivalry', 'https://phimimg.com/upload/vod/20231219-1/0675c0adea2abb6a394b951165505174.jpg', 'https://phimimg.com/upload/vod/20231219-1/534f2e1207eaeef9115609caf6f8cbd3.jpg', '<p>hai gia tộc nổi tiếng là Wiraya Wanich và Teerakitkankul, từ lâu đã trở thành đối thủ trên thương trường qua nhiều thế hệ. Chính vì vậy mà những hậu duệ sau này của hai gia đình, cụ thể là Milin (Nychaa Nuttanicha Dungwattanawanich) và Anawin (Alek Teeradetch Metawarayut) đối đầu nhau ngay từ khi còn trẻ. Milin, nàng tiểu thư danh giá của nhà Weerayawanich luôn khao khát vị trí CEO của tập đoàn Empire do gia đình sở hữu. Mọi chuyện trở nên tồi tệ hơn khi Pee, cha của Milin, tái hôn với Vianna và bổ nhiệm cô vào chức vụ CEO của tập đoàn. Điều đó khiến Milin rất tức giận và cắt đứt quan hệ với cha. Tin tức này cũng khiến Anawin vô cùng sốc, bởi Vianna chính là bạn gái cũ, người đã bỏ rơi anh một năm trước. Với mục đích trả thù Pee, Milin và Anawin quyết định hợp tác để gây dựng một công ty mới nhằm đối chọi với Empire, đồng thời cả hai cũng giả vờ yêu nhau. Nhưng khi thời gian trôi qua, việc đóng giả là một cặp đôi lại trở thành thật. Vậy, tình yêu của Milin và Anawin sẽ ra sao và khi nào thì những ân oán hận thù của hai gia tộc sẽ kết thúc?</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 13, 2022, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Alek Teeradetch Metawarayut","avatar":""},{"name":"Nychaa Nuttanicha Dungwattanawanich","avatar":""},{"name":"Sam Yuranunt Pamornmontri","avatar":""},{"name":"Donut Manatsanun Panlertwongskul","avatar":""},{"name":"Pop Thagoon Karnthip","avatar":""},{"name":"Prima Bhunjaroeun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324307);
