INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai', 'Mai', 'Mai: A Mother''s Rage', 'https://phimimg.com/upload/vod/20231219-1/3992070b04a9d61260ddf4c17f3f27cb.jpg', 'https://phimimg.com/upload/vod/20231219-1/2d35aa8e3e1f1d292753e94c51a7d1b1.jpg', '<p>Phát hiện bọn tội phạm đã gây ra cái chết bi thảm của con gái mình, bà mẹ đau khổ nọ từ một người ôn hòa trở nên tàn nhẫn để tìm ra chân tướng.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 9, 2022, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Sakshi Tanwar","avatar":""},{"name":"Vivek Mushran","avatar":""},{"name":"Raima Sen","avatar":""},{"name":"Prashant Narayanan","avatar":""},{"name":"Seema Pahwa","avatar":""},{"name":"Anant Vidhaat","avatar":""},{"name":"Vaibhav Raj Gupta","avatar":""},{"name":"Omkar Jaiprakash","avatar":""},{"name":"Ankur Ratan","avatar":""},{"name":"Wamiqa Gabbi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
