INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('blue-thermal', 'Blue Thermal', 'Blue Thermal', 'https://phimimg.com/upload/vod/20231231-1/cdd60e5b6b6666afa27acf74dc3c4f54.jpg', 'https://phimimg.com/upload/vod/20231231-1/4d6e11a33c4d5d32480df3fb52db5058.jpg', '<p>Đến từ Nagasaki với câu thần chú ước nguyện của mình là Tamaki Tsuru, người ở trường trung học chỉ có thể nghĩ về bóng chuyền. Tuy nhiên, mọi thứ bắt đầu không suôn sẻ khi cô ấy tìm kiếm một câu lạc bộ ngoại khóa để tham gia và bắt đầu ngay lập tức nhảy tàu lượn tại các buổi tập thử của câu lạc bộ hàng không và cuối cùng phải dừng lại. Ban đầu cô ấy vỡ mộng với cuộc sống trong khuôn viên trường. Sau đó, Kuramochi, trưởng câu lạc bộ và phi công lái tàu lượn, đã che chở cho Tamaki, và kể từ thời điểm anh đưa cô lên chuyến bay trên tàu lượn, Tamaki trở thành kẻ bị giam cầm trước vẻ đẹp bao la của bầu trời.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mayu Hotta","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Haruka Shiraishi","avatar":""},{"name":"You Taichi","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Makoto Furukawa","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Kengo Kawanishi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
