INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('september-mornings-phan-2', 'September Mornings (Phần 2)', 'Manhãs De Setembro (Season 2)', 'https://phimimg.com/upload/vod/20231219-1/a43ad62124bbcaf1c94678fad8f2cb2d.jpg', 'https://phimimg.com/upload/vod/20231219-1/cdc7422d1fa1e9c3ad032115752ab68a.jpg', '<p>Cuộc hành trình của Cassandra, người bắt đầu thấy mọi thứ đi đúng hướng trong cuộc sống của cô ấy với một nơi ở lần đầu tiên của riêng mình, một người bạn trai mà cô ấy yêu, Ivaldo, một công việc chuyển phát nhanh ở trung tâm thành phố São Paulo, và thực hiện ước mơ của mình là nghệ sĩ cover của Vanusa, một ca sĩ Brazil nổi tiếng từ những năm 70. Tuy nhiên, cuộc đời của cô có một bước ngoặt bất ngờ, khi người yêu cũ của cô, Leide, xuất hiện với Gersinho và tuyên bố anh là con trai của Cassandra.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
