INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('september-mornings-phan-2', 'September Mornings (Phần 2)', 'Manhãs De Setembro (Season 2)', 'september mornings (phần 2) manhãs de setembro (season 2)  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xich-cuoc-dai-tien', 'Xích Cước Đại Tiên', 'Growth Of God', 'https://phimimg.com/upload/vod/20231211-1/2d182867c3950aad0d7db0fd0adc328a.jpg', 'https://phimimg.com/upload/vod/20231211-1/77eb0d8c9be68fc76b66fa13d89a55ee.jpg', '<p>Phim kể về câu chuyện của Xích Cước Đại Tiên xuống trần gian để tìm bảo vật. Từ một con người kiêu ngạo, cậy tài khinh người, hẹp hòi rồi dần dần trở thành một người tốt bụng, dũng cảm và giàu lòng yêu thương. Xích Cước Đại Tiên gặp gỡ và quen biết những người dân làng tốt bụng và đã cảm nhận được chân, thiện, mỹ của con người từ họ. Từ sự đoàn kết của những người dân làng đã cảm nhận được sự biết ơn và tình cảm đích thực giữa con người. Khi Xích Cước Đại Tiên biết được thái độ coi thường mình của các vị đại tiên khác thì đột nhiên tỉnh ngộ. Cuối cùng, Xích Cước Đại Tiên đã từ bỏ cơ hội trở về trời và chọn đi khắp nhân gian để làm những điều tốt đẹp, khuyến khích mọi người dám đứng lên, đoàn kết và giúp đỡ lẫn nhau, để củng cố niềm tin, dũng cảm theo đuổi và kêu gọi công lý bằng lòng nhân ái...</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bàng Ngỗ Mỗ","avatar":""},{"name":"Xu Yuan Yuan","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324307);
