INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-ha-nhat-chu-huong', 'Tại Hạ Nhất Chú Hương', 'Call Me Detective Incense', 'https://phimimg.com/upload/vod/20231208-1/d0f81d34f7fa8e275935302e665aff53.jpg', 'https://phimimg.com/upload/vod/20231208-1/36775f3409a806f6b332c3dc02faf751.jpg', '<p>Dịch Khinh Y là bổ khoái hàng đầu trong thiên hạ, có thể phá mọi vụ án ly kỳ trong thời gian một nén hương, nhưng chỉ vì một vụ án mất cừu mà chịu đả kích, từ đó lụi bại không gượng dậy nổi. Một năm sau, vụ án khó này lại bị một bổ khoái mới là Ngô Tửu Tửu phá giải dễ dàng, hai người có duyên kết thành nhóm sư đồ, bước lên hành trình trở lại thành bổ khoái hàng đầu thiên hạ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2022, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tuấn Nhân","avatar":""},{"name":"Trương Nhã Thiến","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324307);
