INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-loi-thoat', 'Không Lối Thoát', 'No Exit', 'https://phimimg.com/upload/vod/20231211-1/4504d47ce48085efd20191f30b365307.jpg', 'https://phimimg.com/upload/vod/20231211-1/e5b5ee37f66d1fb8fbd233aa1621dc10.jpg', '<p>Không lối thoát - No Exit (2022) là bộ phim thuộc thể loại chính kịch, bí ẩn, giật gân của Mỹ. Tác phẩm do đạo diễn Damien Power chịu trách nhiệm chỉ đạo, với sự tham gia của các diễn viên Havana Rose Liu, Danny Ramirez và David Rysdahl.Darby (Havana Rose Liu) cảm thấy buồn chán trong quá trình phục hồi chức năng, với những cảm xúc như mệt mỏi, bồn chồn và hoài nghi. Cô ấy chia sẻ rằng cô ấy đã 11 ngày tỉnh táo và trong lần cai nghiện thứ 7 cô ấy đã nhận được một cuộc gọi điện thoại. Mẹ cô ấy bị chứng phình động mạch và hiện đang ở trong bệnh viện.&nbsp;Đó thực sự là một điều khó khăn, khi cô ấy chạy trốn khỏi ma tuý khiến cho cô ấy không được chào đón ở gia đình. Và cô ấy không thể thực hiện bất kỳ cuộc gọi nào vào thời gian ở lại của mình, cô ấy còn không được phép rời đi, rõ ràng là ngay cả khi mẹ cô đang cận kề cái chết.Tuy nhiên, điều đó không ngăn được Darby, cô ấy đã lấy cắp điện thoại di động của một bệnh nhân, chiếm dụng tủ của người gác cổng, lấy cắp một số dụng cụ, sau đó chạy khỏi cửa và khi chuông đổ, cô ấy đã chạy ra khỏi đó.Ngoài kia, khi cô ấy lao vào một trận bão tuyết kinh khủng khiến cô bị lạc hướng đến thành phố Salt Lake. Các con đường bị đóng cửa, cô ấy mắc kẹt ở một trạm dừng chân, nơi một số người khác cũng kéo ra ngoài để chờ cơn bão lặng đi. Có cặp vợ chồng Ed (Dennis Haysbert) và Sandi (Dale Dickey), một con chồn sóc béo ục ịch tên là Lars (David Rysdahl), và Ash (Danny Ramirez).Darby cùng tham gia và có một cô bé bị trói và bị bịt miệng bằng băng keo. Cô ấy quay số 911 không có dịch vụ chụp ảnh biển số xe và sau đó nhắn tin cho cảnh sát nhưng nó không đi qua và có ai đó nhìn ra cửa sổ, sau đó phát hiện ra cô ấy không?Cô ấy kéo cửa và an ủi cô gái, sau đó quay trở lại bên trong trạm nghỉ ngơi và những trò chơi nhảm nhí, che đậy sự lo lắng của cô ấy và thường xuyên liếc nhìn ra cửa sổ xe tải. Ai là kẻ bắt cóc? Liệu đó là một chàng trai hay một cô gái.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Havana Rose Liu","avatar":""},{"name":"Danny Ramirez","avatar":""},{"name":"Dale Dickey","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
