INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-o', 'Hang Ổ', 'The Lair', 'https://phimimg.com/upload/vod/20231211-1/1442eed792551f42be88bfeb785bb246.jpg', 'https://phimimg.com/upload/vod/20231211-1/fa66adc73380d4c0f74fe8fb3aa38f1e.jpg', '<p>Khi phi công của Lực lượng Không quân Hoàng gia, Trung úy Kate Sinclair bị bắn rơi tại Afghanistan, cô đã tìm thấy nơi ẩn náu trong một hệ thống boongke ngầm bị bỏ hoang, nơi vũ khí sinh học chết người do con người tạo ra - nửa người, nửa người ngoài hành tinh - được đánh thức.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonathan Howard","avatar":""},{"name":"Charlotte Kirk","avatar":""},{"name":"Jamie Bamber","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324307);
