INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-dep-tan-khoc', 'Sắc Đẹp Tàn Khốc', 'Savage Beauty', 'https://phimimg.com/upload/vod/20231209-1/e9660f81c50204f5c52b3ca6eed1c685.jpg', 'https://phimimg.com/upload/vod/20231209-1/41023caaff21b56a50aa9d4a1e8d69ff.jpg', '<p>Để trả thù cho quá khứ bi kịch của mình, một phụ nữ bí ẩn tìm cách sống cùng gia đình quyền lực sở hữu đế chế làm đẹp toàn cầu – và những bí mật đen tối.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 15, 2022, 'Vietsub', 'HD', 'Nam Phi', 0, '[{"name":"Rosemary Zimu","avatar":""},{"name":"Dumisani Mbebe","avatar":""},{"name":"Nthati Moshesh","avatar":""},{"name":"Angela Sithole","avatar":""},{"name":"Jesse Suntele","avatar":""},{"name":"Nambitha Ben-Mazwi","avatar":""},{"name":"Oros Mampofu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
