INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-kiem-phong-van', 'Tiên Kiếm Phong Vân', 'The Whirlwind Of Sword And Fairy', 'https://phimimg.com/upload/vod/20231211-1/e85e3d416d6c07de31360d1390d9269a.jpg', 'https://phimimg.com/upload/vod/20231211-1/a4a5cd8893243449dd5843d664e566a4.jpg', '<p>Một trăm năm trước, Trương Chưởng môn tổ sư của Tiên Kiếm Môn, đã chiến đấu chống lại thủ lĩnh Dị Nhân U Hoàng trong bảy ngày bảy đêm, và phong ấn vũ khí của Dị Nhân tộc \Cửu Lê\ ở Tiên Kiếm Môn. U Hoàng bị thương nặng và bị đánh bại. Một trăm năm sau, Trương Chi Lâm một đệ tử của Tiên Kiếm Môn lên kế hoạch khiến thuộc hạ của U Hoàng lấy trộm đi Tử Thanh Song Kiếm giả, lúc này trong trấn đang bùng phát dịch bệnh, U Hoàng nhân lúc hỗn loạn đi tìm Quyết Âm để khôi phục nguyên khí. Sư thúc của Trương Chi Lâm đại chiến với U Hoàng, nhưng kẻ địch quá mạnh, Cửu Lê đã bị phá phong ấn. Tình thế cấp bách Trương Chi Lâm và Thẩm Vân đóng cửa tu luyện Tử Dương Thanh Minh song kiếm. Sau nhiều lần nghi ngờ, Thẩm Vân nhìn thấy Trương Chi Lâm đã xả thân cứu giúp, hai người trân trọng nhau, cuối cùng đã thành công sử dụng song kiếm, đánh bại U Hoàng!</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Benny Chan","avatar":""},{"name":"Raquel","avatar":""},{"name":"Zhang Ming Ming","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324307);
