INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qala', 'Qala', 'Qala', 'https://phimimg.com/upload/vod/20231211-1/ab20fd52a4b481ef5b3af1ffc620b740.jpg', 'https://phimimg.com/upload/vod/20231211-1/39642186a3ae80e74208ed08872c22c4.jpg', '<p>Bị quá khứ ám ảnh, một ca sĩ tài năng có sự nghiệp đang lên phải đương đầu với áp lực thành công, sự khinh miệt của mẹ và những hoài nghi trong cô.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Triptii Dimri","avatar":""},{"name":"Swastika Mukherjee","avatar":""},{"name":"Babil Khan","avatar":""},{"name":"Amit Sial","avatar":""},{"name":"Sameer Kochhar","avatar":""},{"name":"Girija Oak","avatar":""},{"name":"Swanand Kirkire","avatar":""},{"name":"Tasveer Kamil","avatar":""},{"name":"Varun Grover","avatar":""},{"name":"Veera Kapur Ee","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
