INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-tam-phong', 'Trương Tam Phong', 'The Taichi Master', 'https://phimimg.com/upload/vod/20231211-1/d722de0e783b5bcb94b7f1a5c23bdb09.jpg', 'https://phimimg.com/upload/vod/20231211-1/46c2af865e6a4d318f825889d2d0a8ae.jpg', '<p>Phim kể về câu chuyện cuối thời Nam Tống, khi các thế lực nổi lên, đất nước lâm vào cảnh nội loạn, quân địch nhưng không ngờ Shimen lại bị giáo phái yêu quái tắm máu một cách tàn bạo. Để vực dậy môn phái và bảo vệ quê hương, Zhang Junbao kiên quyết dấn thân vào con đường diệt trừ yêu ma giáo phái, ai ngờ rằng anh lại tham gia vào một âm mưu lớn hơn ...</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324307);
