INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-danh-cho-tinh-yeu', 'Chỉ Dành Cho Tình Yêu', 'Only For Love', 'https://phimimg.com/upload/vod/20231208-1/358c4e69247aa1755f87d83d7ae36b76.jpg', 'https://phimimg.com/upload/vod/20231208-1/ec308f5ddc0d0223b93eb5dab30043d0.jpg', '<p>Sự nghiệp solo của Deusa thử thách chuyện tình của cô với Tadeu. Eva muốn một nghệ sĩ tuyệt vời hát lời nhạc của mình. Những giấc mơ âm nhạc của họ sớm giao thoa.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 13, 2022, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Lucy Alves","avatar":""},{"name":"Filipe Bragança","avatar":""},{"name":"Agnes Nunes","avatar":""},{"name":"Micael","avatar":""},{"name":"Giordano Castro","avatar":""},{"name":"Adriano Ferreira","avatar":""},{"name":"Luiza Fittipaldi","avatar":""},{"name":"Bruno Fagundes","avatar":""},{"name":"Clarissa Müller","avatar":""},{"name":"Gustavo Vaz","avatar":""},{"name":"Ana Mametto","avatar":""},{"name":"Laila Garin","avatar":""},{"name":"Jeniffer Nascimento","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
