INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-tim-hanh-phuc', 'Đi Tìm Hạnh Phúc', 'You''ve Got a Message', 'https://phimimg.com/upload/vod/20231203-1/7c4439a7c9b3abe780d1b0c99f61e131.jpg', 'https://phimimg.com/upload/vod/20231203-1/db3dfb1dc62048598b80ba104815afe5.jpg', '<p>7 câu chuyện đơn vị độc lập, kể về những câu chuyện nhỏ kỳ lạ mà mọi người gặp phải trong quá trình sử dụng APP di động. Đi taxi, đánh giá mua sắm trực tuyến, ghi lại giấc ngủ... Những khoảnh khắc của cuộc sống di động này tuy mang lại sự tiện lợi nhưng lại có thể vô tình làm rò rỉ thông tin cá nhân, các mối nguy hiểm về an toàn tính mạng có thể đã tiếp cận chúng ta qua hàng loạt thông tin mà chúng ta không hề hay biết.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
