INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('strike-phan-5', 'Strike (Phần 5)', 'Strike (Season 5)', 'https://phimimg.com/upload/vod/20231203-1/e24cbac147dd83e11546db3383125573.jpg', 'https://phimimg.com/upload/vod/20231203-1/95940f26f89cff564d6f5e48b2ade304.jpg', '<p>Thám tử tư Cormoran Strike đang đến thăm gia đình ở Cornwall thì được một người phụ nữ, Anna Phipps tiếp cận, nhờ giúp đỡ tìm kiếm mẹ của cô, Margot Bamborough, người đã mất tích trong một hoàn cảnh bí ẩn vào năm 1974. Chưa từng giải quyết một vụ án lạnh lùng nào trước đây, anh tò mò và nhận nó on, bổ sung vào danh sách dài các trường hợp mà anh ấy và cộng sự hiện đang giải quyết. Khi Strike và Robin điều tra vụ mất tích của Margot, họ đối mặt với một vụ án cực kỳ phức tạp với một kẻ tâm thần giết người hàng loạt và những nhân chứng không thể tin tưởng được.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 9, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Tom Burke","avatar":""},{"name":"Holliday Grainger","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
