INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('borrego', 'Borrego', 'Borrego', 'https://phimimg.com/upload/vod/20231210-1/442db9de6b9c765040c20fe2131991df.jpg', 'https://phimimg.com/upload/vod/20231210-1/667866d023af29707f0a1f5f7b2b481d.jpg', '<p>Một nhà thực vật học trẻ tuổi chuyển đến một thị trấn sa mạc nhỏ để nghiên cứu một loài thực vật xâm lấn. Trong khi đang nghiên cứu, cô đến với sự trợ giúp của một chiếc máy bay bị rơi chỉ để thấy mình bị bắt bởi một con la ma túy thiếu kinh nghiệm, kẻ buộc cô phải dẫn đầu một chuyến đi bộ xuyên qua sa mạc oi bức để thả hắn. Một cảnh sát trưởng địa phương bị thu hút vào cuộc săn lùng khi cô con gái nổi loạn của anh ta bắt đầu tìm kiếm nhà thực vật học bị mất tích, trong khi bị truy đuổi bởi một kẻ nhận ma túy địa phương.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lucy Hale","avatar":""},{"name":"Nicholas Gonzalez","avatar":""},{"name":"Leynar Gomez","avatar":""},{"name":"Jorge A. Jimenez","avatar":""},{"name":"Olivia Trujillo","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
