INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('margaux', 'Margaux', 'Margaux', 'https://phimimg.com/upload/vod/20231210-1/ef8ebe28008e751d3de47b1bd7a095ec.jpg', 'https://phimimg.com/upload/vod/20231210-1/949f64f2bc058376028389eb2f9d1514.jpg', '<p>Khi một nhóm học sinh cuối cấp kỷ niệm những ngày cuối cùng đại học của họ tại một ngôi nhà thông minh, hệ thống AI tiên tiến của ngôi nhà, Margaux, bắt đầu có sự hiện diện chết chóc của riêng cô ấy. Một ngày cuối tuần vô tư tiệc tùng biến thành một cơn ác mộng loạn lạc khi họ nhận ra kế hoạch của Margaux nhằm loại bỏ những người thuê nhà của cô ấy bằng cách này hay cách khác. Thời gian bắt đầu cạn kiệt khi cả nhóm cố gắng sống sót và vượt qua ngôi nhà thông minh một cách tuyệt vọng.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Madison Pettis","avatar":""},{"name":"Vanessa Morgan","avatar":""},{"name":"Richard Harmon","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324307);
