INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-khi-gap-duoc-anh-the-italian-recipe', 'Sau Khi Gặp được Anh', 'The Italian Recipe', 'https://phimimg.com/upload/vod/20231209-1/af37aae421d5f90c5b3cc17f9cdc8e34.jpg', 'https://phimimg.com/upload/vod/20231209-1/0e3cc2c0497fc480dd031cce2bbce0b8.jpg', '<p>Ở Rome, cuộc gặp tình cờ giữa một sinh viên đang gặp khó khăn và một thần tượng quyến rũ mở ra câu chuyện tình yêu không ngờ tới khiến các thế giới của họ đảo lộn.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hoàng Nghiêu","avatar":""},{"name":"Lưu Tấn","avatar":""},{"name":"Ngô Anh Triết","avatar":""},{"name":"Phó Mĩ","avatar":""},{"name":"Lý Hiểu Xuyên","avatar":""},{"name":"Romano Reggiani","avatar":""},{"name":"Hồ Hạo Phàm","avatar":""},{"name":"Lui Di","avatar":""},{"name":"Phạm Văn Phương","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324307);
