INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-tu-thu', 'Mối Tử Thù', 'Vendetta', 'https://phimimg.com/upload/vod/20231208-1/443fd2d4d81b3752a89cc1c08ad3d4b7.jpg', 'https://phimimg.com/upload/vod/20231208-1/95e18bb6c52fc4550ab3d2ac52e37172.jpg', '<p>Khi con gái của mình bị giết hại dã man và công lý pháp lý dường như không thể xảy ra, William Duncan nắm lấy luật pháp của chính mình, bắt đầu một nhiệm vụ<br/>quả báo. Sau khi giết tên côn đồ đường phố, người trực tiếp gây ra cái chết của cô, anh thấy mình đang ở giữa cuộc chiến với Rory, anh trai của tên côn đồ.<br/>Fetter, và băng nhóm của anh ta, những người cũng không kém phần quan tâm đến việc kiếm được đồng đều cho thành viên đã chết của họ. Những gì xảy ra sau đó là một trò chơi qua lại căng thẳng về khát khao của một người đàn ông<br/>sự báo thù của người khác. William đến để nhận ra rằng nhiệm vụ trả thù luôn có cùng một kết thúc.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Thomas Jane","avatar":""},{"name":"Clive Standen","avatar":""},{"name":"Jackie Moore","avatar":""},{"name":"Mike Tyson","avatar":""},{"name":"Maddie Nichols","avatar":""},{"name":"Derek Russo","avatar":""},{"name":"Kurt Yue","avatar":""},{"name":"Randy Gonzalez","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324307);
