INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-giac-tinh-yeu', 'Vị Giác Tình Yêu', 'Cupid''s Kitchen', 'https://phimimg.com/upload/vod/20231207-1/62b6fa3718e9186112ffcfc40453b42a.jpg', 'https://phimimg.com/upload/vod/20231207-1/51e68693619ff612a804d6f2641defeb.jpg', '<p>Vị Giác Tình Yêu là câu chuyện tìm kiếm ước mơ của chính mình, họ gặp gỡ và đồng hành với câu chuyện tình yêu ẩm thực không thể ngọt ngào hơn.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 20, 2022, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Đông Thấm","avatar":""},{"name":"Nguyễn Kinh Thiên","avatar":""},{"name":"Tống Tổ Nhi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324307);
