INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-khi-gap-duoc-anh-since-i-met-u', 'Sau Khi Gặp Được Anh', 'Since I Met U', 'https://phimimg.com/upload/vod/20231207-1/35e47465231a79eec0628ab0274886f3.jpg', 'https://phimimg.com/upload/vod/20231207-1/808bad9c16742d05ed122ffd445302ed.jpg', '<p>Sau Khi Gặp Được Anh (Since I Met U) kể về câu chuyện của cặp đôi Trình Mộ và Giang Tư Hàm. Đại sư bánh ngọt Trình Mộ tuổi trẻ tài cao dựa vào công thức cùng đồng hành với một Blogger ẩm thực - nô lệ của bàn phím Giang Tư Hàm. Vì món tráng miệng và đứa trẻ dễ thương, hai người khởi đầu với tính cách không hề có điểm chung nào, bắt đầu một cuộc sống hạnh phúc của \một gia đình ba người\ đầy bất ngờ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhou Jun Wei","avatar":""},{"name":"Jin Zi Xuan","avatar":""},{"name":"Bin Chang","avatar":""},{"name":"Chu Tuấn Vũ","avatar":""},{"name":"Lennon","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324307);
