INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nho-ban-do-he-thong-chien-than', 'Nhờ Bạn Đó! Hệ Thống Chiến Thần', 'War God System! I''m Counting On You!', 'https://phimimg.com/upload/vod/20231207-1/322587281c49edc9e8c6b3d9b36c6fb1.jpg', 'https://phimimg.com/upload/vod/20231207-1/049a4efb4b11ec1176f4e2d680f6987e.jpg', '<p>Thanh niên bình thường ở đô thị An Lâm tình cờ gặp một người tu hành cực mạnh, đối phương ban cho cậu ấy một bộ hệ thống chiến thần và đưa cậu tới Linh giới để tu luyện. An Lâm tư chất bình thường lần đầu tới Linh tới bị sỉ nhục là Hộ có quan hệ mạnh nhất. Để rửa sạch ô danh, An Lâm lạc quan dưới sự giúp đỡ của hệ thống đã nâng cao công lực tu hành, cậu ấy dựa vào nhiều lần thể hiện siêu việt mà kết giao được với một đám bạn thân cùng vào sinh ra tử, bước lên con đường lội ngược dòng.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 9, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
