INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-mua-nha-cua-toi', 'Hãy Mua Nhà Của Tôi', 'Buy My House', 'https://phimimg.com/upload/vod/20231207-1/4c10753f2e73089d60e6cdb3d4523952.jpg', 'https://phimimg.com/upload/vod/20231207-1/1661229508fd4ddcb373d653fb685143.jpg', '<p>Chủ nhà từ khắp nước Mỹ rao bán bất động sản cho bốn nhà đầu tư bất động sản giàu kinh nghiệm, hy vọng có được một thỏa thuận đổi đời ngay lập tức.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 10, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Nina Parker","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324307);
