INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phieu-luu-cung-nguoi-ban-da-tro-thanh-thieu-nu-xinh-dep-o-di-gioi', 'Phiêu Lưu Cùng Người Bạn Đã Trở Thành Thiếu Nữ Xinh Đẹp Ở Dị Giới', 'With a Fogie Reincarnated as a Pretty Fantasy Girl, Fabiniku, Isekai Bishoujo Juniku Ojisan', 'https://phimimg.com/upload/vod/20231207-1/2d2732594d43fb7f8408c09fd430468b.jpg', 'https://phimimg.com/upload/vod/20231207-1/b20018ca359239e951db47e8b91fa0c7.jpg', '<p>Một ông già buồn tẻ và người bạn thân đẹp trai của mình đã bị một nữ thần khỏa thân triệu hồi đến một thế giới khác! Tuy nhiên, vì sự nghịch ngợm của nữ thần, anh ta đã biến thành một cô gái xinh đẹp vô song ?! Để lấy lại cơ thể của mình, anh ấy phải tham gia một cuộc hành trình với người bạn thân nhất của mình để đánh bại quỷ vương !! Một ông già đã trở thành một cô gái xinh đẹp và Một ông già đẹp trai! Hãy để cuộc hành trình rom-com đầy điên rồ trong một thế giới khác bắt đầu !!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 13, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324307);
