INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ivanna', 'Ivanna', 'Ivanna', 'https://phimimg.com/upload/vod/20231210-1/5aef2094f178b0981598e5db68d421ab.jpg', 'https://phimimg.com/upload/vod/20231210-1/ba396c63ef31ccb77d83349ed0c65a8a.jpg', '<p>Ambar &amp; Dika vừa bắt đầu một chương mới của cuộc đời khi mối hận thù lâu năm của một thực thể độc hại hiện ra trước mắt họ. Với món quà mà cô vô tình có được, Ambar giờ đây buộc phải hoàn thành cuộc báo thù của thực thể, một linh hồn người Hà Lan không đầu, Ivanna.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Caitlin Halderman","avatar":""},{"name":"Taskya Namya","avatar":""},{"name":"Junior Roberts","avatar":""},{"name":"Shandy William","avatar":""},{"name":"Tanta Ginting","avatar":""},{"name":"Jovarel Callum","avatar":""},{"name":"Sonia Alyssa","avatar":""},{"name":"Yayu Unru","avatar":""},{"name":"Rina Hasyim","avatar":""},{"name":"Yati Surachman","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324307);
