INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ivanna', 'Ivanna', 'Ivanna', 'ivanna ivanna caitlin halderman taskya namya junior roberts shandy william tanta ginting jovarel callum sonia alyssa yayu unru rina hasyim yati surachman ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-nguoi-go-live-action', 'Cậu Bé Người Gỗ (Live Action)', 'Pinocchio (Live Action)', 'https://phimimg.com/upload/vod/20231210-1/16503d0fda9fa3c8025e23e38db41ec0.jpg', 'https://phimimg.com/upload/vod/20231210-1/95bc1710c3fba39e7f4fd5120fd54b75.jpg', '<p>Robert Zemeckis, người từng đoạt giải Oscar, chỉ đạo live action này và kể lại CGI về câu chuyện yêu dấu của một con rối gỗ, người dấn thân vào cuộc phiêu lưu ly kỳ để trở thành một cậu bé thực thụ. Tom Hanks đóng vai Geppetto, người thợ khắc gỗ, người xây dựng và đối xử với Pinocchio (Benjamin Evan Ainsworth) như thể cậu là con trai ruột của mình. Joseph Gordon-Levitt là Jiminy Cricket, người đóng vai trò là người hướng dẫn Pinocchio cũng như lương tâm của anh ta; Cynthia Erivo, ứng cử viên được đề cử của Academy Award® là Blue Fairy; Keegan-Michael Key là John Honest; Người được đề cử Academy Award® Lorraine Bracco là Sofia the Seagull, một nhân vật mới, và Luke Evans là Người đánh xe.</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Benjamin Evan Ainsworth","avatar":""},{"name":"Joseph Gordon Levitt","avatar":""},{"name":"Keegan Michael Key","avatar":""},{"name":"Cynthia Erivo","avatar":""},{"name":"Luke Evans","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324307);
