INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('how-i-fell-in-love-with-a-gangster', 'How I Fell In Love With A Gangster', 'How I Fell In Love With A Gangster', 'https://phimimg.com/upload/vod/20231210-1/c0c4083efe415ba61d22b4819947743e.jpg', 'https://phimimg.com/upload/vod/20231210-1/116f82e77279e74f60ae3d3634c0f67a.jpg', '<p>Một người phụ nữ bí ẩn kể lại sự trỗi dậy và sự sụp đổ của Nikodem Nikos Skotarczak, một trong những búp bê lớn nhất trong lịch sử Ba Lan.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Ba Lan', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324307);
