INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-du-ky-tien-hon-ha-pham', 'Bắc Du Ký: Tiên Hồn Hạ Phàm', 'Journey To The North', 'https://phimimg.com/upload/vod/20231209-1/c02df45c2bc646c867f96892be5bfcdd.jpg', 'https://phimimg.com/upload/vod/20231209-1/f65ceda3398fc0c35b325729495b8ad8.jpg', '<p>Câu chuyện bắt đầu khi hai phần tiên hồn của Thiên đế, một chính một tà chuyển thế hạ phàm. Một phần linh hồn hóa thành Chiến thần Trường Sinh, dù bị móc mất trái tim cũng không chết. Một phần linh hồn thì hóa thành Vân Hoang, bị Minh vương giam cầm hàng trăm năm ở địa ngục U Vân của Ma tộc, ngày ngày bị Phệ Hồn Đinh hành hạ. Liên tục có những âm mưu quỷ kế khiến hai phần hồn tự tàn sát lẫn nhau. Thần thú tộc Thừa Hoàng biến thành một thiếu nữ hoạt bát dụ dỗ Chiến thần, giúp Vân Hoang ra tay với Chiến thần, cướp đi Ngọc Minh Tâm của người mình yêu là Trường Sinh. Sau đó cô mới biết Trường Sinh vì tình yêu mà chủ động chịu đựng Xả Tâm Kiếp. Mối tình tay ba đầy trắc trở và khó quên, đồng thời cũng liên quan đến đoạn tình duyên của Thiên đế và Thần thú tộc Thừa Hoàng trăm năm về trước. Phong ấn của Minh giới được giải trừ, Ma binh giáng thế, bách tính lầm than. Rốt cuộc luyện ngục của Ma tộc có ẩn tình gì? Hai phần hồn của Thiên đế phải làm sao để trải qua lịch kiếp viên mãn trở về?</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Merxat Mi","avatar":""},{"name":"Lai Yumeng","avatar":""},{"name":"Xiao Xiangfei","avatar":""},{"name":"Wu Motong","avatar":""},{"name":"Shen Feifan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
