INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('be-cung-la-tro-thu-dac-luc', 'Bé Cưng Là Trợ Thủ Đắc Lực', 'Born To Be Together', 'https://phimimg.com/upload/vod/20231207-1/bf86b187ae33646627ff765e6e9a440a.jpg', 'https://phimimg.com/upload/vod/20231207-1/623b6051f34ea584d45cc662bda69222.jpg', '<p>Cặp anh em sinh đôi tráo đổi thân phận, từ cậu nhóc nghịch ngợm hoạt bát biến thành một công tử nhà giàu ít nói, không ngờ lại tìm thấy cha mẹ ruột chưa hề biết mặt của mình. Khi nhà thiết kế giỏi xã giao gặp phải chủ tịch bá đạo khả năng biểu đạt kém thì những câu chuyện rắc rối điên khùng và hài hước cũng từ đó bắt đầu.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 11, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tào Quân Hào","avatar":""},{"name":"Đổng Hân Vân","avatar":""},{"name":"Diêu Tư Thần","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324307);
