INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-quan', 'Thủ Quân', 'Captains', 'https://phimimg.com/upload/vod/20231207-1/49f36196226645a6f8343b751ca938cc.jpg', 'https://phimimg.com/upload/vod/20231207-1/38174edcd6d4c5e2d0bb5450326f4d66.jpg', '<p>Từ đớn đau đến vinh quang, loạt phim tài liệu này theo chân sáu đội trưởng đội bóng đá cùng cả đội khi họ cạnh tranh để giành suất tham dự FIFA World Cup 2022.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 19, 2022, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324307);
