INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-quy-quen-thuoc', 'Ác Quỷ Quen Thuộc', 'The Devil You Know', 'https://phimimg.com/upload/vod/20231209-1/d353c54b4a0896795785c9ed65a87670.jpg', 'https://phimimg.com/upload/vod/20231209-1/ef995d08fc235ea04cdac977b99f8dc3.jpg', '<p>Marcus Cowans (Omar Epps) từng bị giam giữ đang cố gắng lật lại một chiếc lá mới với sự hỗ trợ của gia đình yêu thương của mình. Khi phát hiện ra rằng một trong những người anh em của mình (Will Catlett) có thể đã tham gia vào một tội ác kinh hoàng, Marcus vật lộn với giới hạn của tình anh em và lòng trung thành. Anh và gia đình, ngày càng mệt mỏi với những thất bại của hệ thống tư pháp, cuối cùng rơi vào tay một thám tử dày dạn nhưng mệt mỏi (Michael Ealy). Do Charles Murray viết kịch bản và đạo diễn, The Devil You Know gợi lên câu hỏi: Tôi có phải là thủ môn của anh trai tôi không? Và với chi phí nào?</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Omar Epps","avatar":""},{"name":"Michael Ealy","avatar":""},{"name":"Theo Rossi","avatar":""},{"name":"Vaughn Hebron","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324307);
