INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('student-body', 'Student Body', 'Student Body', 'https://phimimg.com/upload/vod/20231208-1/c5d0bdaa9acbf2b9c3a5998488c474ef.jpg', 'https://phimimg.com/upload/vod/20231208-1/2fa882ec00ca16b961b92fad1a18ab87.jpg', '<p>Học sinh trung học Jane Shipley tìm cách sửa chữa mối quan hệ phù hợp của cô với những người bạn tốt nhất thời thơ ấu Merritt, và phù hợp với những đồng nghiệp nổi tiếng của mình. Khi giáo viên toán của Jane vượt qua giới hạn của mình, một chính quyền cấp ba thờ ơ buộc Jane và Merritt đưa những vấn đề vào tay chính họ, thúc đẩy mối quan hệ của họ thành sự hỗn loạn hơn nữa và gây ra hậu quả chết người.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324307);
