INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gioi-han', 'Giới Hạn', 'Draw The Line', 'https://phimimg.com/upload/vod/20231207-1/73e09062cbed459ab0dbb724372e473e.jpg', 'https://phimimg.com/upload/vod/20231207-1/e134fc04484ae70f3415c85bbb0bab53.jpg', '<p>Fang Yuan, Chánh án Tòa án Nhân dân Quận Xingcheng và Song Yufei, Phó Chánh án Phòng Hình sự của Tòa án Nhân dân Trung cấp Dung Châu, là những người tập sự của Zhang Weimin, Phó Chủ tịch Tòa án Nhân dân Quận Xingcheng. Ba thầy trò đã cống hiến tuổi trẻ và niềm đam mê cho sự nghiệp tư pháp của Trung Quốc. Giờ đây, người học việc kiêm trợ lý pháp lý của Fang Yuan là Zhou Yian vừa trở thành một thẩm phán. Nhóm cố vấn và học việc trước đây đã được phân tán đến các vị trí thử việc khác nhau và tiếp tục tỏa sáng. Việc Ye Xin, một nữ cán bộ trẻ của Văn phòng Nghiên cứu Tòa án Tối cao, đột ngột sa thải, đã mang đến nhiều thay đổi hơn cho Tòa án Hình Thành. Ba thế hệ nhân viên tòa án này, trong mỗi vụ án, đã tiếp nối truyền thống tốt đẹp của sự giúp đỡ và hướng dẫn của tòa án, và họ luôn tôn trọng điểm mấu chốt của công lý, đạo đức và nhân văn.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 9, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jin Dong","avatar":""},{"name":"Cheng Yi","avatar":""},{"name":"Elvira Cai","avatar":""},{"name":"Wang Xiu Zhu","avatar":""},{"name":"Wang Zi Quan","avatar":""},{"name":"Wang Jin Song","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324307);
