INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('snoopy-gioi-thieu-gui-loi-men-yeu-den-me-va-bo', 'Snoopy Giới Thiệu: Gửi Lời Mến Yêu Đến Mẹ (Và Bố)', 'Snoopy Presents: To Mom (and Dad), With Love', 'https://phimimg.com/upload/vod/20231208-1/4e11bdd4dff2831eb24c27170d617053.jpg', 'https://phimimg.com/upload/vod/20231208-1/46f137169742ab1a1173eb41c19799b8.jpg', '<p>Ngày của Mẹ sắp đến rồi và cả nhóm đều rất hào hứng - ngoại trừ Peppermint Patty. Đối với cô ấy, đó là một lời nhắc nhở rằng cô ấy không lớn lên với mẹ. Nhưng người bạn tốt Marcie đã giúp Peppermint Patty thấy rằng các gia đình có đủ hình dạng và kích cỡ.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tyler James Nathan","avatar":""},{"name":"Terry McGurrin","avatar":""},{"name":"Lexi Perri","avatar":""},{"name":"Rob Tinkler","avatar":""},{"name":"Isabella Leo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324308);
