INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-nhan-than-nong', 'Dã Nhân Thần Nông', 'Shennong Savage', 'https://phimimg.com/upload/vod/20231208-1/900e6187f20f4072c104708a4944e13a.jpg', 'https://phimimg.com/upload/vod/20231208-1/797a12fb69f0769dbec74f276342e274.jpg', '<p>Bộ phim kể về hai cha con nhà họ Dương, Zhang Sanlianzi và những người khác bước chân vào khu rừng rậm Shennongjia dưới sự cưỡng bức của lãnh chúa Yan Liben. Anh ta đã bị tấn công bởi nhiều sinh vật khác nhau trong rừng và đã được giải cứu bởi những kẻ man rợ khi họ gặp nguy hiểm.Yian Liben cuối cùng đã bị giết bởi con thằn lằn vì lòng tham. Người dã man đã chiến đấu dũng cảm để bảo vệ thần nông. Cuối cùng, một số người đã hợp tác với nhau để giết con thằn lằn màn, rừng sâu và ngôi làng đã quay lại bình yên.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Quán Anh","avatar":""},{"name":"Lâm Nghiên Nhu","avatar":""},{"name":"Lạc Đạt Hoá","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324308);
