INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-vatican-vu-mat-tich-cua-emanuela-orlandi', 'Cô Gái Vatican: Vụ Mất Tích Của Emanuela Orlandi', 'Vatican Girl: The Disappearance of Emanuela Orlandi', 'https://phimimg.com/upload/vod/20231207-1/c0da5304b4e232dfed096f386b49b213.jpg', 'https://phimimg.com/upload/vod/20231207-1/339811c994dcb040fda753980bf9a848.jpg', '<p>Ở Rome năm 1983, sau khi bỏ dở một buổi học nhạc, cô nàng 15 tuổi Emanuela Orlando mất tích – đưa Vatican vào một bí ẩn kéo dài hàng thập kỷ.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 13, 2022, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324308);
