INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-nay-dau-tinh-yeu-nay-bien-mat-khoi-the-gian', 'Đêm Nay Dẫu Tình Yêu Này Biến Mất Khỏi Thế Gian', 'Even If This Love Disappears From The World Tonight', 'https://phimimg.com/upload/vod/20231208-1/81face334283c7c356ff5ecab6a2e0d6.jpg', 'https://phimimg.com/upload/vod/20231208-1/641c3703f54cc97bb8c1b82c04fdf2cb.jpg', '<p>Vì bị bạn cùng lớp bắt nạt, Tooru Kamiya đã giả vờ tỏ tình với Maori Hino. Cậu nói rằng mình thích cô, nhưng cô lại đặt ra các quy tắc khi hẹn hò, một trong số đó là họ không yêu nhau. Chẳng bao lâu, Tooru thất hứa và yêu Maori. Và đó cũng là ngày cậu biết Maori khi tỉnh dậy, căn bệnh của cô khiến cô không còn ký ức về ngày hôm trước. Cô ghi nhật ký về những gì đã xảy ra trước đó và đọc nó vào buổi sáng để có thể nhớ lại. Tooru quyết tâm dùng tình yêu của mình để mang đến cho cô càng nhiều hạnh phúc càng tốt, trước khi cô quên vĩnh viễn cậu.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Shunsuke Michieda","avatar":""},{"name":"Riko Fukumoto","avatar":""},{"name":"Kotone Furukawa","avatar":""},{"name":"Honoka Matsumoto","avatar":""},{"name":"Toru Nomaguchi","avatar":""},{"name":"Maki Mizuno","avatar":""},{"name":"Masato Hagiwara","avatar":""},{"name":"Maho Nonami","avatar":""},{"name":"Koki Maeda","avatar":""},{"name":"Shô Nishigaki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324308);
