INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-ten-lua', 'Cuộc Chiến Tên Lửa', 'Interceptor', 'https://phimimg.com/upload/vod/20231206-1/b4ed9e22e871898d0758ba4f43596933.jpg', 'https://phimimg.com/upload/vod/20231206-1/3ca3395060baa5c318a9d07c7d2906dd.jpg', '<p>Cuộc Chiến Tên Lửa kể về Một đội trưởng quân đội buộc phải sử dụng nhiều năm đào tạo chiến thuật và chuyên môn quân sự của mình khi một cuộc tấn công phối hợp đồng thời đe dọa trạm đánh chặn tên lửa từ xa mà cô ấy đang chỉ huy.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elsa Pataky","avatar":""},{"name":"Luke Bracey","avatar":""},{"name":"Aaron Glenane","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324308);
