INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jazz-va-cuoc-doi-cua-louis-armstrong', 'Jazz và Cuộc Đời của Louis Armstrong', 'Louis Armstrong''s Black & Blues', 'https://phimimg.com/upload/vod/20231206-1/4146b58dce43088fbb5effe991c54d98.jpg', 'https://phimimg.com/upload/vod/20231206-1/3dbdf811fd0b7f14adc9276c9a626d9e.jpg', '<p>Một cái nhìn thân mật và tiết lộ về nhạc sĩ đang thay đổi thế giới, được trình bày qua lăng kính của cảnh quay lưu trữ và các bản ghi âm tại nhà và các cuộc trò chuyện cá nhân chưa từng được nghe trước đây. Bộ phim tài liệu dứt khoát này tôn vinh di sản của Armstrong với tư cách là cha đẻ của nhạc jazz, một trong những ngôi sao đầu tiên được quốc tế biết đến và yêu mến, đồng thời là đại sứ văn hóa của Hoa Kỳ.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Louis Armstrong","avatar":""},{"name":"Nas","avatar":""},{"name":"Dwight D. Eisenhower","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324308);
