INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wendell-va-wild', 'Wendell và Wild', 'Wendell & Wild', 'https://phimimg.com/upload/vod/20231206-1/b033e049e26a288f0e2e97a749c0fd54.jpg', 'https://phimimg.com/upload/vod/20231206-1/57f941d40ca98efee8165281763c6835.jpg', '<p>Hai ác quỷ mưu mô thỏa thuận với một thiếu nữ mê nhạc punk rock để có thể rời Địa ngục và thực hiện ước mơ của chúng ở Dương gian.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keegan-Michael Key","avatar":""},{"name":"Jordan Peele","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"Lyric Ross","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Gabrielle Dennis","avatar":""},{"name":"Gary Gatewood","avatar":""},{"name":"Tamara Smart","avatar":""},{"name":"Natalie Martinez","avatar":""},{"name":"James Hong","avatar":""},{"name":"Tantoo Cardinal","avatar":""},{"name":"Igal Naor","avatar":""},{"name":"David Harewood","avatar":""},{"name":"Maxine Peake","avatar":""},{"name":"Sam Zelaya","avatar":""},{"name":"Seema Virdi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324308);
