INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('wendell-va-wild', 'Wendell và Wild', 'Wendell & Wild', 'wendell và wild wendell & wild keegan-michael key jordan peele angela bassett lyric ross ving rhames gabrielle dennis gary gatewood tamara smart natalie martinez james hong tantoo cardinal igal naor david harewood maxine peake sam zelaya seema virdi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-tri-mang', 'Thiếu Nữ Trí Mạng', 'Revenge Girl', 'https://phimimg.com/upload/vod/20231206-1/8117062592bcfe32a5bb8b32762788be.jpg', 'https://phimimg.com/upload/vod/20231206-1/ef6d3a082ed83cc2dc0433b86f2c3333.jpg', '<p>Trong thế giới tương lai, trí tuệ nhân tạo rất phát triển, và tổ chức nghiên cứu khoa học ngầm do Trình Phi quản lí đã bí mật phát triển các con chíp não dùng để kích thích tiềm năng của cơ thể con người, nhằm mục đích nuôi dưỡng một nhóm sinh vật siêu nhiên và kiếm lợi bất chính. Trong một sự cố, Trình Phi đã ra lệnh loại bỏ tất cả những người làm thí nghiệm. Vì vậy mà mẹ của Thiên Hạc cũng đã chết, Thiên Hạc một mình trốn thoát được kiếp nạn. Mười năm sau, Thiên Hạc và bà ngoại sống nương tựa vào nhau bên một dòng sông . Thiên Hạc suốt bao năm luôn canh cánh trong lòng, nhưng đối với chuyện năm xưa không chút manh mối nên không thể tìm ra tổ chức ngầm hồi đó ở đâu. Trong một sự cố bất ngờ, một người cấy chip của tổ chức ngầm đào thoát đến bên sông, vì vậy Thiên Hạc cũng dần lần ra manh mối về tổ chức ngầm. Để tìm ra sự thật, Thiên Hạc đã mạo hiểm, không ngờ phát hiện ra rằng con chip do mẹ cô cấy vào chính là thứ mà tổ chức ngầm đang tìm kiếm.</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liang Long","avatar":""},{"name":"Michelle Ye","avatar":""},{"name":"Zhang Yiyu","avatar":""},{"name":"Lu Siheng","avatar":""},{"name":"Hu Haofan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678