INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('empire-of-light', 'Empire of Light', 'Empire of Light', 'https://phimimg.com/upload/vod/20231206-1/b681ecb46914f2442b6a9a1e5a7d36af.jpg', 'https://phimimg.com/upload/vod/20231206-1/3020753aec2e42a83899badf7eea3763.jpg', '<p>Người quản lý trực của một rạp chiếu phim bên bờ biển, người đang phải vật lộn với sức khỏe tâm thần của mình, đã hình thành mối quan hệ với một nhân viên mới ở bờ biển phía nam nước Anh vào những năm 1980.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Olivia Colman","avatar":""},{"name":"Micheal Ward","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Tom Brooke","avatar":""},{"name":"Tanya Moodie","avatar":""},{"name":"Hannah Onslow","avatar":""},{"name":"Crystal Clarke","avatar":""},{"name":"Sara Stewart","avatar":""},{"name":"Adrian McLoughlin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324308);
