INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-bac', 'Sòng Bạc', 'Big Bet', 'https://phimimg.com/upload/vod/20231202-1/90bfecb1e2c7a161ed1738b5389015f7.jpg', 'https://phimimg.com/upload/vod/20230923-1/b9da35e0d6c0d70cb07ded585401ea70.jpg', '<p>Bộ phim xoay quanh một nhân vật huyền thoại trong thế giới sòng bạc của Philippines. Cha Mu-Sik (Choi Min-Sik) đã trở thành huyền thoại trong thế giới sòng bạc, sau nhiều lần trái ngang. Anh ta dính líu đến một vụ án giết người. Điều này dẫn đến cuộc sống của anh ta đang đứng trên bờ vực của sự sụp đổ. Cha Mu-Sik sau đó bắt đầu đặt cược những gì cuối cùng của mình, mạo hiểm mạng sống của mình.Trước đây được gọi là&nbsp; King Of Savvy ,&nbsp; loạt phim mới của Hàn Quốc lấy bối cảnh kể câu chuyện về một người đàn ông đấu tranh để đạt được mục tiêu trở thành ông trùm sòng bạc, tuy nhiên phần lớn bị lùi lại sau một chuỗi sự kiện đáng tiếc. Người đàn ông bắt đầu mạo hiểm mọi thứ anh ta có, bao gồm cả mạng sống của mình, để đưa mình trở lại đúng hướng. Disney + đã thông báo vào ngày hôm qua (16 tháng 11) rằng bộ phim truyền hình K rất được mong đợi sẽ có buổi ra mắt toàn cầu trên dịch vụ phát trực tuyến vào ngày 21 tháng 12. Hãng cũng tiết lộ hình ảnh đầu tiên cho loạt phim mới; một đoạn giới thiệu dài một phút mô tả thế giới cờ bạc khốc liệt, lấy bối cảnh ở Philippines.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Choi Min Sik","avatar":""},{"name":"Son Suk Ku","avatar":""},{"name":"Lee Dong Hwi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324308);
