INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-tinh-2022', 'Ngoại Tình', 'An Affair to Forget', 'https://phimimg.com/upload/vod/20231206-1/a5f6d25d86f6b132e7160e8fcface347.jpg', 'https://phimimg.com/upload/vod/20231206-1/b56738f80a2dcf2c52bb0c382b4c7f02.jpg', '<p>Một người vợ tìm kiếm sự giúp đỡ của một phụ nữ trẻ để tìm hiểu xem chồng mình có ngoại tình hay không. Cốt truyện dày lên khi người phụ nữ trẻ phải lòng người chồng</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Sunshine Cruz","avatar":""},{"name":"Angelica Cervantes","avatar":""},{"name":"Allen Dizon","avatar":""},{"name":"Karl Aquino","avatar":""},{"name":"Mark Dionisio","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324308);
