INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-em-kinh-ngu', 'Chị Em Kình Ngư', 'The Swimmers', 'https://phimimg.com/upload/vod/20231205-1/ac15386189a3e8b11657e3c44678e89b.jpg', 'https://phimimg.com/upload/vod/20231205-1/461f561e2d99a5bedcf91c35575a19c2.jpg', '<p>Từ Syria bị chiến tranh tàn phá đến Olympic Rio 2016, hai chị em trẻ tuổi bắt đầu cuộc hành trình mạo hiểm, dành trọn trái tim và kỹ năng bơi lội của họ cho chính nghĩa.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Manal Issa","avatar":""},{"name":"Nathalie Issa","avatar":""},{"name":"Matthias Schweighöfer","avatar":""},{"name":"Ahmed Malek","avatar":""},{"name":"Ali Suliman","avatar":""},{"name":"Kinda Alloush","avatar":""},{"name":"James Krishna Floyd","avatar":""},{"name":"Nahel Tzegal","avatar":""},{"name":"Akuc Bol","avatar":""}]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324308);
