INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-theo-duoi-anh-sang', 'Người Theo Đuổi Ánh Sáng', 'Light Chaser Rescue', 'https://phimimg.com/upload/vod/20231207-1/fd8d909438f71a2c683c3bbc3f22ff04.jpg', 'https://phimimg.com/upload/vod/20231207-1/a0d0944e4d12d4a9694730d7d83177be.jpg', '<p>Sau trận động đất ở Tây Xuyên, luật sư Luo Ben đã đến đó để tìm em gái của mình, Luo Yuan. Đây là lần đầu tiên anh gặp đội cứu hộ phi lợi nhuận do Đội trưởng Thanh Sơn dẫn đầu và sau đó anh gặp lại kẻ thù cũ Zhan Yan. Luo Ben vô cùng ấn tượng trước sự hỗ trợ lẫn nhau của người dân ở các khu vực bị ảnh hưởng và sự hy sinh của các nhân viên cứu hộ. Anh cũng rất ấn tượng trước kỹ năng y học tuyệt vời và lòng vị tha của Zhan Yan. Luo Ben, Xiong Fei, Zhou Mingming, Ding Dingding và những người mới khác tham gia đội cứu hộ phi lợi nhuận Yuanfang, dưới sự huấn luyện nghiêm ngặt của Đội trưởng Qingshan, và trở thành thành viên đội cứu hộ, họ tham gia nhiều lần vào các hoạt động cứu hộ khác nhau vì động đất , hỏa hoạn, chết đuối, bão. Bước ra khỏi phương hướng của cuộc sống, dùng mạng sống của mình cứu sống, thông qua lễ rửa tội trong thảm họa và cuối cùng họ trở thành những người ưu tú cứu hộ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 11, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Leo Luo","avatar":""},{"name":"Wu Qian","avatar":""},{"name":"Li Mingde","avatar":""},{"name":"Li Tingting","avatar":""},{"name":"Xu Shaoying","avatar":""},{"name":"Honey Yang","avatar":""},{"name":"Zeng Chen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324308);
