INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-con-cach-nao', 'Không Còn Cách Nào', 'There Are No Saints', 'https://phimimg.com/upload/vod/20231203-1/b57aa7896b0af35e30b6edf656e89468.jpg', 'https://phimimg.com/upload/vod/20231203-1/0ecae6321dca9644d9f2257ed1791600.jpg', '<p>Một người đàn ông có biệt danh là Dòng Tên, bị bỏ tù vì một tội ác mà anh ta không phạm phải. Khi vợ anh ta bị sát hại và con trai anh ta bị bắt cóc và đưa đến Mexico, anh ta đã nghĩ ra một kế hoạch phức tạp và nguy hiểm để giải cứu con trai mình và trả thù cho kẻ giết người. Phim không còn cách nào có diễn biến ra sao, hay theo dõi ngay trên phimmoichill.net</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tim Roth","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Ron Perlman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324308);
