INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-phap-y-tong-tu-thau-luong-hoan-tru', 'Đại Pháp Y Tống Từ: Thâu Lương Hoán Trụ', 'Forensic Medicine Song Ci', 'https://phimimg.com/upload/vod/20231203-1/55a00080dec27902c1be3747e8e23133.jpg', 'https://phimimg.com/upload/vod/20231203-1/651d2195187d12504e77740fbd773f8d.jpg', '<p>“Series Pháp y vĩ đại Tống Từ: Thâu Lương Hoán Trụ là một bộ phim cổ trang trinh thám, kể về việc Tống Từ sử dụng tuyệt vời kỹ năng thám tử pháp y để tìm ra manh mối và sử dụng bằng chứng từng bước dưới nhiều khó khăn, tiến gần hơn đến chân tưởng và giải quyết các kỳ án chưa được phá giải. Bộ phim thể hiện công nghệ pháp y tiên tiến và tuyệt vời ở Trung Quốc cổ đại, ca ngợi những nhân vật lịch sử kiệt xuất của Trung Quốc và cổ vũ tinh thần yêu nước.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Gang","avatar":""},{"name":"LawrenceNg","avatar":""},{"name":"Lawrence Ng Kai Wah","avatar":""},{"name":"Ng Kai Wah","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324308);
