INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oni-su-tich-than-sam', 'ONI: Sự Tích Thần Sấm', 'ONI: Thunder God''s Tale', 'https://phimimg.com/upload/vod/20231204-1/d4f979504c3a381c73b91bd77d6cfece.jpg', 'https://phimimg.com/upload/vod/20231204-1/2736d4417b67e3c97607cccb49312ba2.jpg', '<p>Ở thế giới thần bí của các vị thần và linh hồn Nhật Bản, một cô bé can đảm nỗ lực tiếp bước người bố bí ẩn và tìm được sức mạnh thực sự của mình.</p>', 'Hoàn Tất (4/4)', 4, 'hoathinh', 'completed', 7, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Momona Tamada","avatar":""},{"name":"Craig Robinson","avatar":""},{"name":"Archie Yates","avatar":""},{"name":"George Takei","avatar":""},{"name":"Seth Carr","avatar":""},{"name":"Tantoo Cardinal","avatar":""},{"name":"Brittany Ishibashi","avatar":""},{"name":"Anna Akana","avatar":""},{"name":"Charlet Takahashi Chung","avatar":""},{"name":"Robert Kondo","avatar":""},{"name":"Sawashiro Miyuki","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324308);
