INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('oni-su-tich-than-sam', 'ONI: Sự Tích Thần Sấm', 'ONI: Thunder God''s Tale', 'oni: sự tích thần sấm oni: thunder god''s tale momona tamada craig robinson archie yates george takei seth carr tantoo cardinal brittany ishibashi anna akana charlet takahashi chung robert kondo sawashiro miyuki ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-tre-mat-tich', 'Đứa Trẻ Mất Tích', 'The Disappearing Child', 'https://phimimg.com/upload/vod/20231204-1/2f32123bbe3315ff0f7181256f7a1d51.jpg', 'https://phimimg.com/upload/vod/20231204-1/ce927256f9428a38957f86ed27435b25.jpg', '<p>Vào sáng sớm ngày đông chí, đứa con trai chín tuổi của Dương Nguyên đã biến mất không tung tích ở cầu thang. Cảnh sát phát hiện ra rằng anh ta đã lẻn vào nhà hàng xóm ngay trước khi mất tích. Người hàng xóm đáng ngờ có bằng chứng ngoại phạm chắc chắn, như thể điều khiển từ xa một cuộc trốn thoát khỏi căn phòng ma thuật.Ở phía bên kia của đơn vị, cha của Yuan Wu đột ngột qua đời sau khi uống rượu. Để nhận tiền trợ cấp, Yuan Wu quyết định giấu xác cha mình trong căn nhà cho thuê. Trong khoảng thời gian này, anh gặp phải nỗi sợ hãi về ảo ảnh và thực tế, đồng thời vô tình chạm vào một bí ẩn khác.Sáu tháng trước, Lin Chu Ping, một nữ công nhân cổ trắng sống một mình, thức dậy trong nhà và phát hiện mình bị xâm phạm khi đang ngủ, nhưng không có manh mối gì về thủ phạm, chỉ còn lại một mảnh khăn mùi xoa trên người. ngưỡng cửa sổ ...<br/>Những con người tưởng như không liên quan này, ở thời gian và không gian khác nhau chồng chất lên nhau và bắt đầu hành trình tìm kiếm câu trả lời.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 13, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Đồng Đại Vỹ","avatar":""},{"name":"Vision Wei","avatar":""},{"name":"Kelly","avatar":""},{"name":"Dany Lee","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324308);
