INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-lac-tung-3', 'Hoan Lạc Tụng 3', 'Ode To Joy 3', 'https://phimimg.com/upload/vod/20231204-1/2cceb475e06c58cc5483f8ea444a99c4.jpg', 'https://phimimg.com/upload/vod/20231204-1/bc1bb716ca0c65570e8d11ee7c5b7d2b.jpg', '<p>Cuộc sống của năm cô gái trong tiểu khu lầu 22 nay đã đi theo những ngã rẽ mới. Những khó khăn khi khởi nghiệp, nỗi buồn vì tư tưởng trọng nam khinh nữ của cha mẹ và cả những vấp ngã trong tình yêu, mọi thứ đều có thể vượt qua được, chỉ cần họ mãi ở bên và giúp đỡ nhau cùng trưởng thành.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 16, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Giang Sơ Ảnh","avatar":""},{"name":"Trương Giai Ninh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324308);
