INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhu-the-da-du-den-chua', 'Như Thế Đã Đủ Đen Chưa?!?', 'Is That Black Enough for You?!?', 'https://phimimg.com/upload/vod/20231202-1/4d7f3cc680cc091e89c0bc1cd728929a.jpg', 'https://phimimg.com/upload/vod/20231202-1/6e51fef48f0a81006c5ccc05f04bf2ff.jpg', '<p>Sử gia kiêm nhà phê bình văn hóa Elvis Mitchell khám phá sự phát triển và cuộc cách mạng của điện ảnh da đen, từ khởi nguồn cho đến những bộ phim có tác động trong những năm 1970.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elvis Mitchell","avatar":""},{"name":"Margaret Avery","avatar":""},{"name":"Harry Belafonte","avatar":""},{"name":"Charles Burnett","avatar":""},{"name":"Suzanne de Passe","avatar":""},{"name":"Antonio Fargas","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Sheila Frazier","avatar":""},{"name":"Whoopi Goldberg","avatar":""},{"name":"Louise Archambault","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Stan Lathan","avatar":""},{"name":"Roscoe Orman","avatar":""},{"name":"James Signorelli","avatar":""},{"name":"Glynn Turman","avatar":""},{"name":"Mari","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324308);
