INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('elvis', 'Elvis', 'Elvis', 'https://phimimg.com/upload/vod/20231202-1/a0601c136f2692350211afedd560146b.jpg', 'https://phimimg.com/upload/vod/20231202-1/58ba9305f7edce2fb200e679571bf4f4.jpg', '<p>Từ khi nổi tiếng trở thành siêu sao chưa từng có, biểu tượng nhạc rock *n* roll Elvis Presley duy trì mối quan hệ phức tạp với người quản lý bí ẩn của mình, Đại tá Tom Parker, trong suốt 20 năm. Trung tâm của hành trình và hạnh phúc của Presley là một trong những người có ảnh hưởng lớn nhất đến cuộc đời anh - Priscilla</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Austin Butler","avatar":""},{"name":"Tom Hanks","avatar":""},{"name":"Olivia DeJonge","avatar":""},{"name":"Helen Thomson","avatar":""},{"name":"Richard Roxburgh","avatar":""},{"name":"Kelvin Harrison Jr.","avatar":""},{"name":"David Wenham","avatar":""},{"name":"Kodi Smit-McPhee","avatar":""},{"name":"Luke Bracey","avatar":""},{"name":"Dacre Montgomery","avatar":""},{"name":"Leon Ford","avatar":""},{"name":"Gary Clark Jr.","avatar":""},{"name":"Yola","avatar":""},{"name":"Natasha Bassett","avatar":""},{"name":"Xavier Samuel","avatar":""},{"name":"Adam Dunn","avatar":""},{"name":"Alton Mason","avatar":""},{"name":"Shonka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324308);
