INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinosaurs-the-final-day-with-david-attenborough', 'Dinosaurs: The Final Day with David Attenborough', 'Dinosaurs: The Final Day with David Attenborough', 'https://phimimg.com/upload/vod/20231202-1/3e960157874930a025cd92362c8ce61d.jpg', 'https://phimimg.com/upload/vod/20231202-1/2a1b6460116879949275120e613f21bb.jpg', '<p>David Attenborough làm sống động một cách chi tiết chưa từng có về những ngày cuối cùng của loài khủng long. Nhà cổ sinh vật học Robert DePalma đã có một khám phá đáng kinh ngạc trong một nghĩa địa thời tiền sử: những sinh vật hóa thạch, được bảo quản tốt một cách đáng kinh ngạc, có thể giúp thay đổi hiểu biết của chúng ta về những ngày cuối cùng của loài khủng long. Bằng chứng từ trang web của anh ấy ghi lại ngày một tiểu hành tinh lớn hơn đỉnh Everest tàn phá hành tinh của chúng ta và gây ra sự tuyệt chủng của loài khủng long. Dựa trên những bằng chứng hoàn toàn mới, hãy chứng kiến những sự kiện thảm khốc trong ngày đó diễn ra từng phút một.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324308);
