INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-thay-bong-toi', 'Bậc Thầy Bóng Tối', 'Shadow Master', 'https://phimimg.com/upload/vod/20231202-1/1889553a61343ed908e52a912e4a3cdc.jpg', 'https://phimimg.com/upload/vod/20231202-1/f621dd2003eebce2287365d3b3ae0d06.jpg', '<p>Sau khi bị giết bởi một nhóm tội phạm, An Voaen được tái sinh với siêu năng lực siêu nhiên chưa thể lý giải được và thực hiện sứ mệnh của mình để sửa chữa những sai trái cho thành phố của mình. Anh ta sẽ đối đầu với ai và những pha hành động như thế nào ? cùng phimmoichilly xem và giải đáp các câu hỏi đó</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"D.Y. Sao","avatar":""},{"name":"Layton Matthews","avatar":""},{"name":"Brian Le","avatar":""},{"name":"Craig Ng","avatar":""},{"name":"Anna Harr","avatar":""},{"name":"Luciana Faulhaber","avatar":""},{"name":"Dominique Swain","avatar":""},{"name":"Pearry Reginald Teo","avatar":""},{"name":"Camilo González","avatar":""},{"name":"Eric Gay Jr.","avatar":""},{"name":"Morgan M. Younge","avatar":""},{"name":"Dylan Walton","avatar":""},{"name":"Dezzaray Stephens","avatar":""},{"name":"Alex Farnham","avatar":""},{"name":"Daniel Mah","avatar":""},{"name":"Lucy Kate Akers","avatar":""},{"name":"Dexter Haag","avatar":""},{"name":"Ja","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324308);
