INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-ay-bay-gio', 'Ngày Ấy & Bây Giờ', 'Now and Then', 'https://phimimg.com/upload/vod/20231203-1/9fdf2e9a81863bc301d0208344d25934.jpg', 'https://phimimg.com/upload/vod/20231203-1/544aaef39e2527f283504e524e2dd415.jpg', '<p>Vào đêm trước lễ tốt nghiệp đại học, sáu người bạn thân bắt đầu một ngày cuối tuần hoành tráng để ăn mừng—nhưng nó lại xảy ra một bước ngoặt tai hại. Gần 20 năm sau, những người sống sót bất đắc dĩ đoàn tụ bởi một tin nhắn tống tiền đe dọa phơi bày sự thật về đêm định mệnh đó.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Rosie Perez","avatar":""},{"name":"Marina de Tavira","avatar":""},{"name":"José María Yázpik","avatar":""},{"name":"Maribel Verdú","avatar":""},{"name":"Manolo Cardona","avatar":""},{"name":"Soledad Villamil","avatar":""},{"name":"Zeljko Ivanek","avatar":""},{"name":"Jorge López","avatar":""},{"name":"Alicia Jaziz Zapién","avatar":""},{"name":"Dario Yazbek Bernal","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324308);
