INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-gui-nuoc-nga', 'Tình Yêu Gửi Nước Nga', 'To Russia with Love', 'https://phimimg.com/upload/vod/20231201-1/790db744e8333e63c51599bad64b79b9.jpg', 'https://phimimg.com/upload/vod/20231201-1/af37f5a1b7270b4aaaad8ed43a84f1bc.jpg', '<p>Khi một doanh nhân tận tụy chiếm được cảm tình của một khách du lịch phóng khoáng, anh cũng phải lấy lòng ông bố nghiêm khắc đang phản đối chuyện tình của cô.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Gerald Anderson","avatar":""},{"name":"Elena Kozlova","avatar":""},{"name":"Scott Alexander Young","avatar":""},{"name":"Kakai Bautista","avatar":""},{"name":"Simon Szabó","avatar":""},{"name":"Isay Alvarez","avatar":""},{"name":"Malou Crisologo","avatar":""},{"name":"Ivan Carapiet","avatar":""},{"name":"Jef Gaitan","avatar":""},{"name":"Karl Gabriel","avatar":""},{"name":"Veronica Reyes","avatar":""},{"name":"Dániel Kanalas","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324308);
