INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vikrant-rona', 'Vikrant Rona', 'Vikrant Rona', 'https://phimimg.com/upload/vod/20231201-1/9d15206bca0f2d39f3138043aa7b2954.jpg', 'https://phimimg.com/upload/vod/20231201-1/b69d18e5b7ccfc92b76d5af5fb7af656.jpg', '<p>Gần nửa thế kỷ trước, một ngôi làng hẻo lánh nằm giữa khu rừng mưa nhiệt đới bắt đầu chứng kiến một loạt sự kiện không thể giải thích được mà họ cho là siêu nhiên. Vikrant Rona, Một sĩ quan cảnh sát lập dị, được giao nhiệm vụ giải quyết bí ẩn. Một trò chơi bí ẩn diễn ra trong đó mọi người trong làng đều là nạn nhân tiềm năng và mọi người đều là nghi phạm.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Sudeep","avatar":""},{"name":"Nirup Bhandari","avatar":""},{"name":"Jacqueline Fernandez","avatar":""},{"name":"Neetha Ashok","avatar":""},{"name":"Ravishanker Gowda","avatar":""},{"name":"Madhusudhan Rao","avatar":""},{"name":"Vasuki Vaibhav","avatar":""},{"name":"Siddu Moolimani","avatar":""},{"name":"Chitkala Biradar","avatar":""},{"name":"Ramesh Kukkuvalli","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324308);
