INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-thu-dong-bac-quyet-chien-nui-ho-nha', 'Xạ Thủ Đông Bắc: Quyết Chiến Núi Hổ Nha', 'The King of Sniper in Northeast', 'https://phimimg.com/upload/vod/20231201-1/97ca03a837153cfea19801e8e042da1a.jpg', 'https://phimimg.com/upload/vod/20231201-1/f15c72e71420065c9d051dad417520e9.jpg', '<p>Phim kể về câu chuyện năm 1931, sau khi &quot;Sự kiện Mãn Châu&quot; nổ ra, xạ thủ Nhâm Thiên Thành không nghe lời can ngăn dẫn quân chiến đấu và bị giết trong đêm phục kích quân Nhật. Nhâm Thiên Thành cũng bị thương nặng và được thổ phỉ giải cứu. Năm năm sau, Nhâm Thiên Thành sống trong một ngôi nhà nhỏ, chỉ uống rượu và đánh bạc, và tình cờ gặp Bạch Cáp, đồng đội cũ của anh. Để bảo vệ Bạch Cáp, anh quyết định gia nhập tổ chức ám sát ngầm của Đảng Cộng sản Trung Quốc, tham gia vào vụ ám sát chuyên gia virus học người Nhật Bản Sakamoto Ichiro. Người bảo vệ Ichiro Sakamoto là đối thủ cũ của anh- Kazuya Sorimachi, để bảo vệ đồng đội Nhâm Thiên Thành đã hành động một mình giết thành công Ichiro Sakamoto. Tuy nhiên, chỉ có 3 người Nhâm Thiên Thành, Bạch Cáp, Giao Thông sống sót sau cuộc sơ tán. Kazuya cũng bị khiêu khích, vì ép Nhâm Thiên Thành phải xuất hiện đã lệnh tàn sát ngôi nhà, chỉ tha mạng cho thổ phỉ thứ tư để truyền lời lại cho Nhâm Thiên Thành yêu cầu quyết chiến với anh ta ở núi Huya. Nhìn thấy tình trạng thê thảm của thổ phỉ sau khi bị quân Nhật tàn sát, Nhâm Thiên Thành đau lòng và quyết định đối đầu với Kazuya Soramachi. Nhưng quân địch quá đông, liệu mọi người sẽ hành động như thế nào? Chúng ta hãy cùng đón xem.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Junhan","avatar":""},{"name":"Kan Xin","avatar":""},{"name":"Chai Yuanle","avatar":""},{"name":"Sun Yizhen","avatar":""},{"name":"Liu Weizhou","avatar":""},{"name":"Yan Jiaying","avatar":""},{"name":"Wu Long","avatar":""},{"name":"Ning Xiaohua","avatar":""},{"name":"Chen Yuyong","avatar":""},{"name":"Gao Xuanming","avatar":""},{"name":"Cheng Qi","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324308);
