INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-trip-to-infinity', 'A Trip to Infinity', 'A Trip to Infinity', 'https://phimimg.com/upload/vod/20231130-1/311ded08a1f8cc8871c18e38a9fcc25d.jpg', 'https://phimimg.com/upload/vod/20231130-1/a7185215e88cce914c398503dd286542.jpg', '<p>Vô cực có tồn tại không? Chúng ta có thể trải nghiệm cái Vô hạn không? Trong một bộ phim hoạt hình (do các nghệ sĩ đến từ 10 quốc gia tạo ra), các nhà khoa học và toán học tiên tiến nhất thế giới đi tìm kiếm cái vô hạn và những tác động uốn nắn tâm trí của nó đối với vũ trụ. Các nhà toán học, nhà vật lý hạt và nhà vũ trụ học lỗi lạc đi sâu vào vô cực và những tác động uốn nắn tâm trí của nó đối với vũ trụ.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anthony Aguirre","avatar":""},{"name":"Stephon Alexander","avatar":""},{"name":"Eugenia Cheng","avatar":""},{"name":"Moon Duchin","avatar":""},{"name":"Kenny Easwaran","avatar":""},{"name":"Delilah Gates","avatar":""},{"name":"Rebecca Goldstein","avatar":""},{"name":"Brian Greene","avatar":""},{"name":"Janna Levin","avatar":""},{"name":"Alan Lightman","avatar":""},{"name":"Carlo Rovelli","avatar":""},{"name":"Steven H. Strogatz","avatar":""},{"name":"Brian Bremer","avatar":""},{"name":"Jimbo Matison","avatar":""},{"name":"Alex Ricciardi","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324308);
