INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiem-banh-hambogo-cua-bob', 'Tiệm Bánh Ham-bơ-gơ Của Bob', 'The Bob''s Burgers Movie', 'https://phimimg.com/upload/vod/20231130-1/66882039f6df9887ee8c67352075571c.jpg', 'https://phimimg.com/upload/vod/20231130-1/bfa9ac12547d6bc62d10cfda8d9df666.jpg', '<p>Khi một đường ống dẫn nước bị vỡ tạo ra một hố sụt khổng lồ ngay trước cửa hàng Bob&#39;s Burgers, nó sẽ chặn lối vào vô thời hạn và phá hỏng kế hoạch của Belchers cho một mùa hè thành công. Trong khi Bob và Linda đấu tranh để duy trì hoạt động kinh doanh, những đứa trẻ cố gắng giải quyết một bí ẩn có thể cứu nhà hàng của gia đình họ. Khi mối nguy hiểm ngày càng gia tăng, những người dưới quyền này giúp nhau tìm thấy hy vọng và chiến đấu để trở lại phía sau quầy, nơi họ thuộc về.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"H. Jon Benjamin","avatar":""},{"name":"Kristen Schaal","avatar":""},{"name":"John Roberts","avatar":""},{"name":"Dan Mintz","avatar":""},{"name":"Eugene Mirman","avatar":""},{"name":"Larry Murphy","avatar":""},{"name":"Kevin Kline","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"David Wain","avatar":""},{"name":"Gary Cole","avatar":""},{"name":"John Q. Kubin","avatar":""},{"name":"Sarah Silverman","avatar":""},{"name":"Laura Silverman","avatar":""},{"name":"Jenny Slate","avatar":""},{"name":"Brian Huskey","avatar":""},{"name":"Aziz Ansari","avatar":""},{"name":"Sam Seder","avatar":""},{"name":"Ron Lynch","avatar":""},{"name":"St","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182d