INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-ay-khong-phai-me-toi', 'Bà Ấy Không Phải Mẹ Tôi', 'You Are Not My Mother', 'https://phimimg.com/upload/vod/20231130-1/fdc5782116bac682f3917b27995688b3.jpg', 'https://phimimg.com/upload/vod/20231130-1/106d1bb17dff10c63611791c9a236c88.jpg', '<p>Phim thuộc thể loại kinh dị, tâm lý. Câu chuyện xoay quanh cuộc sống của gia đình Char, họ vốn đang sống vô cùng bình yên và hạnh phúc tại ngôi nhà ờ phía Bắc Dublin. Việc mẹ cô mất tích một cách bí ẩn rồi trở về khiến Char đặt ra những nghi vấn, điều này thôi thúc cô ấy lật mở bí mật đằng sau nó.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Ireland', 0, '[{"name":"Hazel Doupe","avatar":""},{"name":"Carolyn Bracken","avatar":""},{"name":"Jordanne Jones","avatar":""},{"name":"Florence Adebamo","avatar":""},{"name":"Katie White","avatar":""},{"name":"Paul Reid","avatar":""},{"name":"Ingrid Craigie","avatar":""},{"name":"Colin Peppard","avatar":""},{"name":"Martin O''Sullivan","avatar":""},{"name":"Aoife Spratt","avatar":""},{"name":"Jade Jordan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324308);
