INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-than', 'Thế Thân', 'The Other Child', 'https://phimimg.com/upload/vod/20231130-1/105d2510c7ad57893b45fe7fa71047f8.jpg', 'https://phimimg.com/upload/vod/20231130-1/01d6d06618dc6458f17ca09709de063b.jpg', '<p>Hyun-woo chọn cách nhận nuôi Isaac để vượt qua nỗi đau mất con sau một tai nạn thảm khốc. Oan nghiệt thay, Isaac lại là một đứa bé sở hữu đôi mắt âm dương có thể thấy được người cõi âm. Năng lực đặc biệt hay lời nguyền ám ảnh sẽ giáng lên cuộc sống của gia đình vốn chất chứa nhiều bi kịch?</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Hyo-ju","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Cha Sun-woo","avatar":""},{"name":"Park Jae-jun","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324308);
