INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-sau-di-bien', 'Biển Sâu Dị Biến', 'Deep Sea Variability', 'null', 'https://phimimg.com/upload/vod/20231129-1/c03c34e039c50404f3ea0a47c3d71893.jpg', '<p>Tương truyền những năm gần đây có một khu vực chết ven biển, nơi đậu của hàng trăm nghìn con tàu ma cao ngất, quái vật bên trong đều hung ác, không ai đi ngang qua khu vực này mà sống sót trở lại. Địch Nhân Kiệt cùng cha đi đến một huyện gần đó, tình cờ gặp vị hôn thê Kim Yến Tử đang đuổi theo quái vật. Hai người sau này hợp lực và tìm cách đến được con tàu ma này. Và nhân vật phản diện lớn nhất cuối cùng đã xuất hiện...</p>', 'Full', 1, 'single', 'completed', 6, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jason Sze","avatar":""},{"name":"Zhang Chunzhong","avatar":""},{"name":"Wei Xiao","avatar":""},{"name":"Jackson Liu","avatar":""},{"name":"Ma Peng","avatar":""},{"name":"Yin Zeqiang","avatar":""},{"name":"Zhang Jingsong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324308);
