INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dia-the-gioi-sup-do', 'Chiến Địa: Thế Giới Sụp Đổ', 'Battlefield: Fall of The World', 'https://phimimg.com/upload/vod/20231129-1/3892b6e1c188086077ab393d655092bd.jpg', 'https://phimimg.com/upload/vod/20231129-1/942dfcf3fb1428de9b96ae288437917b.jpg', '<p>Vũ trụ song song 1216, 2042. Vài năm sau khi sinh vật ngoài hành tinh của Hercules M16 xâm chiếm trái đất, Trình Lăng một người lính chạy trốn của Lực lượng Phòng vệ bị chó ba đầu tấn công và bất ngờ gặp Gao Ren và những người khác trong đội của Chúc Dung. Trên đường đi, mọi người bị bao vây bởi những kẻ săn mồi, bị chó ba đầu truy đuổi, và gặp Tiến sĩ Doji Pam, người làm chủ công nghệ khống chế chó ba đầu. Trong suốt cuộc hành trình, Trình Lăng dần dần biến thành một lực lượng phòng thủ đủ tiêu chuẩn dưới sự truyền cảm hứng từ lòng dũng cảm của các thành viên trong đội để chiến đấu chống trả mà không hề sợ hãi. Khi mọi người đến thành trì kháng chiến, họ phát hiện ra rằng cái gọi là thành trì kháng chiến chỉ là một cái bẫy do các thợ săn chó ba đầu giăng ra. Sau sự kháng cự tuyệt vọng và sự hy sinh của Cao Nhân và những người khác, Trình Lăng và Doji Pam đã gửi thành công tín hiệu \&quot;sự thật\</p>', 'Full', 1, 'single', 'completed', 7, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ren Tianye","avatar":""},{"name":"Zhang Zhilu","avatar":""},{"name":"Choenyi Tsering","avatar":""},{"name":"He Zhuoen","avatar":""},{"name":"Liu Jianwei","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324308);
