INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-oan-luc-chi-tay-ha-thiet-quan', 'Tẩy Oan Lục Chi Tây Hạ Thiết Quan', 'The Iron Coffin of Western Xia', 'https://phimimg.com/upload/vod/20231129-1/4f7b81df1d8fb3242e634bfdd2c934f1.jpg', 'https://phimimg.com/upload/vod/20231129-1/53505fa85b5a374e5c0c1e0797528f56.jpg', '<p>Vua Tây Hạ có một bộ y phục quý giá tên là &quot;Bi Lu&quot;, được cho là có thể giúp người phàm thăng hoa bất tử. Hoàng đế vô cùng tức giận, ra lệnh cho Tống Từ tìm ra sự thật, phải chăng là Tây Hạ có ý định phản nghịch hay thực sự là bảo y đã móc hồn.</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Zhengyang","avatar":""},{"name":"Norman Chui Siu-Keung","avatar":""},{"name":"Cherry Chen","avatar":""},{"name":"Lee Yiu-Ging","avatar":""},{"name":"Hu Xingyu","avatar":""},{"name":"Zhu Pengcheng","avatar":""},{"name":"Zhou Peng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324308);
