INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yuri-maral-sai-lam-vo-y', 'Yuri Marçal: Sai Lầm Vô Ý', 'Yuri Marçal: Honest Mistake', 'https://phimimg.com/upload/vod/20231129-1/7087eb9b62c479bc7d80922b52abe517.jpg', 'https://phimimg.com/upload/vod/20231129-1/df670e71828b65107efd3156c411b3f4.jpg', '<p>Từ chia sẻ quan điểm độc đáo về gia đình, chủng tộc và tôn giáo đến kể tường tận về mối bất hòa gay gắt trên mạng, cây hài người Brazil Yuri Marçal không hề e ngại.</p>', 'Full', 1, 'single', 'completed', 25, 2022, 'Vietsub', 'HD', 'Bồ Đào Nha', 0, '[{"name":"Yuri Marçal","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324308);
