INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-best-friends-exorcism', 'My Best Friend''s Exorcism', 'My Best Friend''s Exorcism', 'https://phimimg.com/upload/vod/20231129-1/dd77db0cd0988cd7a68b103926aecb16.jpg', 'https://phimimg.com/upload/vod/20231129-1/7178ca5e6102cbf100954032b30ce4e9.jpg', '<p>Đó là năm 1988. Abby và Gretchen là bạn thân từ năm lớp bốn. Sau một buổi tối gầy gò trở nên sai lầm thảm hại, Gretchen bắt đầu hành động… khác người, khiến Abby nghi ngờ người bạn thân nhất của cô có thể bị quỷ ám. Với sự giúp đỡ từ một số đồng minh không chắc chắn, Abby bắt tay vào nhiệm vụ cứu Gretchen. Nhưng liệu tình bạn của họ có đủ sức mạnh để đánh bại ma quỷ?</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Elsie Fisher","avatar":""},{"name":"Amiah Miller","avatar":""},{"name":"Rachel Ogechi Kanu","avatar":""},{"name":"Cathy Ang","avatar":""},{"name":"Clayton Royal Johnson","avatar":""},{"name":"​Christopher Lowell","avatar":""},{"name":"Nathan Anderson","avatar":""},{"name":"Cynthia Evans","avatar":""},{"name":"Rachel Leah Cohen","avatar":""},{"name":"John Stoneburner","avatar":""},{"name":"Cameron Bass","avatar":""},{"name":"Ashley LeConte Campbell","avatar":""},{"name":"Michael Wayne Foster","avatar":""},{"name":"Michael Proctor","avatar":""},{"name":"Erin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324308);
