INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-mang-tren-song-nile-2022', 'Án Mạng Trên Sông Nile', 'Death on the Nile', 'https://phimimg.com/upload/vod/20231022-1/ce1dbd428dd0fe984cfd94a1066caf3e.jpg', 'https://phimimg.com/upload/vod/20231022-1/d010c938538a8f510565c59d53cf33e9.jpg', '<p>Án Mạng Trên Sông Nile xoay quanh chuyến đi tham quan Ai Cập của thám tử Poirot. Trên chiếc du thuyền nhỏ, ông bắt gặp một cặp nam thanh nữ tú: nàng triệu phú trẻ Linnet Doyle và người chồng mới cưới Simon Doyle đang hưởng tuần trăng mật. Chuyến đi hạnh phúc của hai người bị phá hỏng bởi người tình cũ của Simon - Jacqueline de Bellefort không ngừng bám theo phá đám.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Kenneth Branagh","avatar":""},{"name":"Tom Bateman","avatar":""},{"name":"Annette Bening","avatar":""},{"name":"Russell Brand","avatar":""},{"name":"Ali Fazal","avatar":""},{"name":"Dawn French","avatar":""},{"name":"Gal Gadot","avatar":""},{"name":"Armie Hammer","avatar":""},{"name":"Rose Leslie","avatar":""},{"name":"Emma Mackey","avatar":""},{"name":"Sophie Okonedo","avatar":""},{"name":"Jennifer Saunders","avatar":""},{"name":"Letitia Wright","avatar":""},{"name":"Michael Rouse","avatar":""},{"name":"Alaa Safi","avatar":""},{"name":"Orlando Seale","avatar":""},{"name":"Charlie Anson","avatar":""},{"name":"Danny Hughes","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324308);
