INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-than-vung-texas-2022', 'Tử Thần Vùng Texas', 'Texas Chainsaw Massacre', 'https://phimimg.com/upload/vod/20230926-1/e71afd1e5d1960d67c6baa54fefce46d.jpg', 'https://phimimg.com/upload/vod/20230926-1/99f728a1f26250fcebae80b29bb482b6.jpg', '<p>Phần sau: những người có ảnh hưởng đang muốn thổi làn gió mới cho một thị trấn đìu hiu ở Texas thì chạm trán tên sát nhân khét tiếng đeo mặt nạ da người.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Yarkin","avatar":""},{"name":"Elsie Fisher","avatar":""},{"name":"Mark Burnham","avatar":""},{"name":"Jacob Latimore","avatar":""},{"name":"Moe Dunford","avatar":""},{"name":"Olwen Fouéré","avatar":""},{"name":"Jessica Allain","avatar":""},{"name":"Nell Hudson","avatar":""},{"name":"Alice Krige","avatar":""},{"name":"William Hope","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324308);
