INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-thu-2022', 'Quái Thú', 'Beast', 'https://phimimg.com/upload/vod/20230925-1/454458edd453d18ab9f4759938a23140.jpg', 'https://phimimg.com/upload/vod/20230925-1/65621d77000aead7e4353cec156dca38.jpg', '<p>Người cha đơn thân là tiến sĩ Nate Daniels do Idris Elba thủ vai, cùng hai cô con gái trong chuyến đi dã ngoại tới khu bảo tồn thiên nhiên được quản lý bởi người bạn cũ của gia đình, và cũng là nhà sinh vật học, chuyên nghiên cứu về động vật hoang dã. Thế nhưng, những gì bắt đầu một cuộc hành trình gắn kết tình cảm gia đình và giải tỏa căng thẳng lại trở thành một cuộc chiến sinh tồn đáng sợ khi một loài thú khát máu coi tất cả là kẻ thù, bắt đầu rình rập họ.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Idris Elba","avatar":""},{"name":"Leah Sava Jeffries","avatar":""},{"name":"Iyana Halley","avatar":""},{"name":"Sharlto Copley","avatar":""},{"name":"Martin Munro","avatar":""},{"name":"Liyabuya Gongo","avatar":""},{"name":"Daniel Hadebe","avatar":""},{"name":"Thapelo Sebogodi","avatar":""},{"name":"Mduduzi Mavimbela","avatar":""},{"name":"Chris Gxalaba","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324308);
