INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-2022', 'Người Dơi', 'The Batman', 'https://phimimg.com/upload/vod/20231018-1/e58014050ad6ce7fbed8c3932b615073.jpg', 'https://phimimg.com/upload/vod/20231018-1/6ca3f656e2cb638938dacd7ba3a3865d.jpg', '<p>Tay giết người hàng loạt – The Ridder (Paul Dano) sẽ là kẻ thù nguy hiểm hàng đầu của Batman ở phần phim sắp tới. Tên xấu xa này bị cảnh sát James Gordon và đồng đội bắt giữ đã lâu. Thế nhưng, hóa ra việc nhốt gã sau song sắt chỉ khiến The Ridder phiền phức hơn với Đấng. Penguin (Colin Farrell) thể hiện là kẻ thủ ác thích trực tiếp tạo ra hỗn loạn, muốn đối đầu Batman hơn là chỉ đạo gián tiếp theo cách The Ridder thực hiện.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Pattinson","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Paul Dano","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"John Turturro","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Colin Farrell","avatar":""},{"name":"Jayme Lawson","avatar":""},{"name":"Gil Perez-Abraham","avatar":""},{"name":"Peter McDonald","avatar":""},{"name":"Con O''Neill","avatar":""},{"name":"Alex Ferns","avatar":""},{"name":"Rupert Penry-Jones","avatar":""},{"name":"Charlie Carver","avatar":""},{"name":"Max Carver","avatar":""},{"name":"Barry Keog","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324308);
