INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('always-amore', 'Always Amore', 'Always Amore', 'https://phimimg.com/upload/vod/20231209-1/c520f6a30ddb5815880c4d3569019161.jpg', 'https://phimimg.com/upload/vod/20231209-1/7719a27c446ffea74a81db6fba78a461.jpg', '<p>Một góa phụ bất đắc dĩ phải thuê chuyên gia tư vấn để giúp duy trì hoạt động cho nhà hàng của người chồng quá cố. Khi dần mở lòng để thay đổi, liệu cô có thể đón nhận tình yêu mới?</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Autumn Reeser","avatar":""},{"name":"Tyler Hynes","avatar":""},{"name":"Matthew Del Bel Belluz","avatar":""},{"name":"Rachelle Goulding","avatar":""},{"name":"Patty McCormack","avatar":""},{"name":"Lisa Marie DiGiacinto","avatar":""},{"name":"Peter Bryant","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324308);
