INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('always-amore', 'Always Amore', 'Always Amore', 'always amore always amore autumn reeser tyler hynes matthew del bel belluz rachelle goulding patty mccormack lisa marie digiacinto peter bryant ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-ma-tu-linh-nguyen-bi-thuat', 'Trấn Ma Tư: Linh Nguyên Bí Thuật', 'Demon Sealer Bureau', 'https://phimimg.com/upload/vod/20230928-1/87207f5bf6f5627bf70afcdae6d12488.jpg', 'https://phimimg.com/upload/vod/20230928-1/d6120e0edb28a0f93733ed9d7433b616.jpg', '<p>Một trăm năm trước, Ngọc Tu tiên sư phong ấn quái thú tám châu, và
 mộc thần Tây Nam biến thành gỗ khô (biến thành linh nguyên). Vào năm 
thứ 40 của triều đại nhà Triệu, Cố Niệm Đồng của Tà giáo, muốn phá vỡ 
phong ấn của tiên sư, tinh luyện mộc thần và biến nó thành mộc yêu, đầu 
độc chúng sinh. Vì vậy, tiên hoàng đã đặc biệt sắc lệnh cho Đường Lăng 
Phong và một số người khác của Ẩn giám Trấn ma tư, chỉ huy quân đội tiến
 về phía Tây Nam để bình định yêu tà. Để chinh phục mộc yêu cần quái thú
 do Công Thâu gia tạo ra. Cách để điều khiển con quái thú là &quot;linh 
nguyên mật thuật&quot; được ghi lại trong &quot;Lỗ Ban Toàn Thư&quot;. Điều này cũng 
liên quan đến mối thù 10 năm trước của Đường gia với Công Thâu gia, Trấn
 ma tư. Mười năm trước Công Thâu gia vì để có được &quot;Lỗ Ban Toàn Thư&quot; đã 
tàn sát cả nhà họ Đường, chỉ có Đường Lăng Phong 8 tuổi may mắn thoát 
chết được thống lĩnh Trấn ma tư Trương Khiệm đưa về Trấn ma tư nuôi 
dưỡng. Đường Lăng Phong kết giao với Lục Ấn và Lục Đồng, ba người thân 
thiết như huynh muội một nhà, đồng thời thông qua sát hạch nghiêm ngặt 
trở thành thành viên của Ẩn giám. Cùng với thân thế của Đường Lăng Phong
 dần dần được tiết lộ thì mối quan hệ của Lăng Phong và Lục Ấn, Lục Đồng
 cũng dần thay đổi. Ba người cũng dần dần bị rơi vào âm mưu của Công 
Thâu gia.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yaqi","avatar":""},{"name":"He Landou","avatar":""},{"name":"Wang Han-Yang","avatar":""},{"name":"Bai Xinyi","avatar":""},{"name":"Guo Muhan","avatar":""},{"name":"Zhang Chunzhong","avatar":""},{"name":"Zhou Zhuo","avatar":""},{"name":"Wang Luojia","avatar":""},{"name":"Zhang Jijun","avatar":""},{"name":"Chun Chieh Liu","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324308);
