INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-nho-nu-hoang-elizabeth-ii', 'Tưởng Nhớ Nữ Hoàng Elizabeth II', 'A Tribute to Her Majesty the Queen', 'https://phimimg.com/upload/vod/20231129-1/a8e3e307ba1bd8f03d7c30b29c15fd71.jpg', 'https://phimimg.com/upload/vod/20231129-1/d66300b13eac13008d1f537bf6182c7d.jpg', '<p>Về cái chết của HM Queen Elizabeth II, một bộ phim tài liệu đặc biệt có sự đóng góp của HM King Charles III, các con của bà, các nhân vật của công chúng và những người đã làm việc với bà. Với những cảnh quay lưu trữ chưa từng thấy trước đây từ bộ sưu tập của Nữ hoàng.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Kirsty Young","avatar":""},{"name":"King Charles III of the United Kingdom","avatar":""},{"name":"Prince Edward","avatar":""},{"name":"Duke of Edinburgh","avatar":""},{"name":"Anne","avatar":""},{"name":"Princess Royal","avatar":""},{"name":"Boris Johnson","avatar":""},{"name":"Prince Andrew","avatar":""},{"name":"Duke of York","avatar":""},{"name":"Queen Elizabeth II of the United Kingdom","avatar":""},{"name":"Tony Blair","avatar":""},{"name":"David Cameron","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324308);
