INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-girl-on-a-bulldozer', 'The Girl on a Bulldozer', 'The Girl on a Bulldozer', 'https://phimimg.com/upload/vod/20231129-1/859fc41a80888f5d8a943859b54b0c56.jpg', 'https://phimimg.com/upload/vod/20231129-1/8cef3823f56e73f9e18aa1dd2a4345cc.jpg', '<p>Haeyoung là một cô gái vô vọng. Cô sống với cha mình, người điều hành một nhà hàng Trung Quốc và một người em. Một ngày nọ, cha cô gặp một tai nạn bí ẩn, đặt cô vào một vị trí đầy trách nhiệm. Giờ đây, cô không chỉ là người đứng đầu trong nhà và phải chăm sóc đứa em của mình, mà còn là một điều tra viên được giao nhiệm vụ tìm ra sự thật về vụ tai nạn, và một chiến binh chống lại thế giới xấu xí.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Hye-yoon","avatar":""},{"name":"Park Hyeok-kwon","avatar":""},{"name":"Yesung","avatar":""},{"name":"Oh Man-seok","avatar":""},{"name":"Choi Hee-jin","avatar":""},{"name":"Park Hyun-woo","avatar":""},{"name":"Park So-eul","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324308);
