INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-cho-san', 'Biệt Đội Chó Săn', 'Wolf Hound', 'https://phimimg.com/upload/vod/20231128-1/58bd155eab4fef3b641439818a3c0903.jpg', 'https://phimimg.com/upload/vod/20231128-1/b84862ebf67b528b92fcd837e9c363b9.jpg', '<p>Biệt Đội Chó Săn - Wolf Hound 2022: Phim thuộc thể loại hành động - chiến tranh được diễn ra trong trận chiến khốc liệt giữa hai cường quốc Pháp và Đức trong Thế Chiến Thứ 2. Lúc này Pháp bị Đức tấn công mạnh mẽ, kẻ thù phục kích khiến David Holden khốn đốn. Anh phải nhanh chóng tìm ra cách tự giải cứu chính mình và đồng đội trước một loạt mưa bom của kẻ thù. Liệu anh có thành công giải cứu các người đồng đội của mình hay không?</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Maslow","avatar":""},{"name":"Trevor Donovan","avatar":""},{"name":"John Turk","avatar":""},{"name":"Michael Wayne Foster","avatar":""},{"name":"Ronald Woodhead","avatar":""},{"name":"Taylor Novak","avatar":""},{"name":"Michael Parrish","avatar":""},{"name":"Brian Heintz","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324308);
