INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('grimcutty', 'Grimcutty', 'Grimcutty', 'https://phimimg.com/upload/vod/20231128-1/842a3ae9eba05d2aae778a4d0b14191a.jpg', 'https://phimimg.com/upload/vod/20231128-1/bbafaefaeb6fe8dce3c20342c1f62982.jpg', '<p>Một cô gái tuổi teen ngoại ô và em trai của cô ấy phải ngăn chặn một meme internet đáng sợ được đưa vào cuộc sống bởi sự cuồng loạn của cha mẹ họ.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sara Wolfkind","avatar":""},{"name":"Shannyn Sossamon","avatar":""},{"name":"Usman Ally","avatar":""},{"name":"Callan Farris","avatar":""},{"name":"Tate Moore","avatar":""},{"name":"Joel Ezra Hebner","avatar":""},{"name":"Alona Tal","avatar":""},{"name":"Kayden Alexander Koshelev","avatar":""},{"name":"Malaya Valenzuela","avatar":""},{"name":"Ryan P. Shrime","avatar":""},{"name":"Olabisi Kovabel","avatar":""},{"name":"Brenda Schmid","avatar":""},{"name":"Scott Roberts","avatar":""},{"name":"Nanrisa Lee","avatar":""},{"name":"Shelli Boone","avatar":""},{"name":"John Ross Bowie","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324308);
