INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-cat-bien-vung-dat-co-lau-lan', 'Động Cát Biển Vùng Đất Cổ Lâu Lan', 'The ancient City of Loulan', 'https://phimimg.com/upload/vod/20231128-1/5ee12b2fa1a271ffa2a546ebdd4eaa4c.jpg', 'https://phimimg.com/upload/vod/20231128-1/3be2cce773c85ef4234f639015ac13bf.jpg', '<p>Vào đầu thế kỷ trước, tàn tích của thành phố cổ Lâu Lan được phát hiện, thu hút các nhà thám hiểm trên khắp thế giới đến khám phá và tìm kiếm kho báu. Nhà thám hiểm Trần Tiêu đã ngăn chặn bọn cướp tàn phá các di tích lịch sử và cướp phá bảo vật quốc gia, vì vậy ông được coi là cái gai trong mắt của nhiều tên cướp. Trong lúc thoát khỏi sự truy đuổi của bọn cướp, Trần Tiêu đã tình cờ lạc vào một khu vực chưa từng được đặt chân tới, nơi đây chính là “Thành phố Mirage” trong truyền thuyết, để bảo vệ thành cổ bí ẩn này và những bảo vật của nó, Trần Tiêu đã tìm đến cho những người bạn tốt để giúp đỡ. Tổ đội từng sát cánh cùng nhau hội tụ lại để bắt đầu hành trình bảo vệ báu vật quốc gia. Cùng lúc đó, tên trộm xuyên quốc gia Quang Cốc Đại Siêu cũng nắm được tin tức về &quot;thành phố Mirage</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Max Mok Siu-Chung","avatar":""},{"name":"Kimmy Tong Fei","avatar":""},{"name":"Minowa Yasufumi","avatar":""},{"name":"Xu Jingwen","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324308);
