INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-an-phong-dac-vu', 'Vụ Án Phòng Đặc Vụ', 'Wire Room', 'https://phimimg.com/upload/vod/20231128-1/c9ba0ae30d77c7b0312af51f4f7aead5.jpg', 'https://phimimg.com/upload/vod/20231128-1/4bbcdbc6e8ec30b8468e7752f9a5152d.jpg', '<p>Tân binh Justin Rosa phải theo dõi thành viên băng đảng buôn lậu vũ khí Eddie Flynn - và giữ anh ta sống sót bằng mọi giá. Khi một đội SWAT đến nhà Flynn, Rosa phá vỡ giao thức và liên hệ trực tiếp với xã hội đen để cứu mạng anh ta. Khi các tay súng đột nhập vào Phòng dây và hỗn loạn nổ ra, Mueller và Rosa quyết định cuối cùng, tuyệt vọng chống lại các đặc vụ và quan chức tham nhũng, những kẻ tìm cách phá hủy bằng chứng và giết cả hai.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Dillon","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Oliver Trevena","avatar":""},{"name":"Texas Battle","avatar":""},{"name":"Cameron Douglas","avatar":""},{"name":"Shelby Cobb","avatar":""},{"name":"MWW Michael Wilkerson","avatar":""},{"name":"Adam Huel Potter","avatar":""},{"name":"Amber Townsend","avatar":""},{"name":"John D. Hickman","avatar":""},{"name":"Larken Woodward","avatar":""},{"name":"Faith Stowers","avatar":""},{"name":"Brad Mintun","avatar":""},{"name":"Sarah Schueler","avatar":""},{"name":"Bradford Norris","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324308);
