INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-may-dia-nguc', 'Cỗ Máy Địa Ngục', 'The Infernal Machine', 'https://phimimg.com/upload/vod/20231125-1/2a7b0a3764f1c8af3602c01a774ba131.jpg', 'https://phimimg.com/upload/vod/20231125-1/4d8485b9cb69bf25ef8dabbb91d59717.jpg', '<p>Tác giả ẩn dật và gây tranh cãi Bruce Cogburn bị một người hâm mộ ám ảnh lôi ra khỏi chỗ ẩn náu, buộc tiểu thuyết gia phải đối mặt với quá khứ mà anh ta nghĩ rằng anh ta có thể thoát ra, và giải thích cho những sự kiện đã khởi động trong cuốn sách bán chạy của anh ta nhiều thập kỷ trước đó. Việc Cogburn tìm kiếm kẻ đứng sau thao túng và dằn vặt tinh thần mà anh ta gặp phải dẫn đến một chuyến đi tàu lượn siêu tốc đầy cảm xúc đầy sợ hãi và nguy hiểm, nơi mọi thứ không phải lúc nào cũng rõ ràng như chúng ta tưởng, và nơi mà những việc làm trong quá khứ có thể gây ra hậu quả thảm khốc.</p>', 'Full', 1, 'single', 'completed', 33, 2022, 'Vietsub', 'HD', 'Bồ Đào Nha', 0, '[{"name":"Guy Pearce","avatar":""},{"name":"Alice Eve","avatar":""},{"name":"Jeremy Davies","avatar":""},{"name":"Alex Pettyfer","avatar":""},{"name":"Iris Cayatte","avatar":""},{"name":"Rachel De Fontes","avatar":""},{"name":"Ana Lopes","avatar":""},{"name":"Georgia Goodman","avatar":""},{"name":"Bella Alexandras","avatar":""},{"name":"Gary Anthony Stennette","avatar":""},{"name":"Ben Temple","avatar":""},{"name":"Oliver Ritchie","avatar":""},{"name":"Maria de Sá","avatar":""},{"name":"Paula Lobo Antunes","avatar":""},{"name":"Rocco Salata","avatar":""},{"name":"Joel Abadal","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324308);
