INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-co-don-nhat-the-gioi', 'Cậu Bé Cô Đơn Nhất Thế Giới', 'The Loneliest Boy in the World', 'https://phimimg.com/upload/vod/20231125-1/debea6520c0609b27f64035acf3ee71e.jpg', 'https://phimimg.com/upload/vod/20231125-1/fbfdef9d1ad9ce89ecf6006c75376a62.jpg', '<p>Là một câu chuyện cổ tích hiện đại - với những thây ma. Một sự châm biếm và tôn vinh các giá trị gia đình, về hình ảnh của các bộ phim kinh dị, về cuộc sống ngoại ô, về Giấc mơ Mỹ và về điều cấm kỵ tối thượng; cái chết.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Max Harwood","avatar":""},{"name":"Hero Fiennes Tiffin","avatar":""},{"name":"Susan Wokoma","avatar":""},{"name":"Evan Ross","avatar":""},{"name":"Tallulah Haddon","avatar":""},{"name":"Hammed Animashaun","avatar":""},{"name":"Ashley Benson","avatar":""},{"name":"Ben Miller","avatar":""},{"name":"Alex Murphy","avatar":""},{"name":"Jacob Sartorius","avatar":""},{"name":"Zenobia Williams","avatar":""},{"name":"Mitchell Zhangazha","avatar":""},{"name":"Sam Coleman","avatar":""},{"name":"Nicola Roberts","avatar":""},{"name":"Benjamin Nealon","avatar":""},{"name":"Carol Anne Watts","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324308);
