INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-thuc-tinh-cua-vu-khi-than-but-cuu-long', 'Sự Thức Tỉnh Của Vũ Khí Thần Bút Cửu Long', 'The treasure code', 'https://phimimg.com/upload/vod/20231125-1/e0426e5b7eabdee853b91a97621fa79c.jpg', 'https://phimimg.com/upload/vod/20231125-1/ea0900a87a38368394b61ee5d6983816.jpg', '<p>Thiếu Khanh Kì Lăng nhận được chỉ dụ bí mật của hoàng đế truy tìm &quot;Cửu Long Bút&quot; với sức mạnh ma thuật siêu nhiên đồng thời phá vỡ các cơ mật. Sau nhiều lần điều tra, Kì Lăng phát hiện ra rằng thứ này thực sự có liên quan đến cái chết của cha. Cùng với việc các cơ quan của &quot;Cửu Long Bút&quot; được mở ra, thì vụ án cũng dần dần được làm rõ. Nhưng lúc này các thế lực trong triều cũng đang có những động thái hành động ngầm, mọi chuyện không hề đơn giản như vậy.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Qi Shenghan","avatar":""},{"name":"Deng Lingshu","avatar":""},{"name":"Michael Jen","avatar":""},{"name":"Yan Ma","avatar":""},{"name":"Zhou Xiaochuan","avatar":""},{"name":"Kai Shen","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324308);
