INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chip-va-potato-ky-nghi-cua-chip', 'Chip và Potato: Kỳ nghỉ của Chip', 'Chip and Potato: Chip''s Holiday', 'https://phimimg.com/upload/vod/20231125-1/ce3f140fe983d5a469040f2e589565f1.jpg', 'https://phimimg.com/upload/vod/20231125-1/b41eee48598672df3c6f9862fd6b1a8f.jpg', '<p>Khi dừa rụng khiến mọi người thức trắng đêm vào kỳ nghỉ, Chip và Potato nảy ra một kế hoạch để giúp cả nhà có giấc ngủ thật ngon!</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2022, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Briana Buckmaster","avatar":""},{"name":"Brian Dobson","avatar":""},{"name":"Chance Hurstfield","avatar":""},{"name":"Andrea Libman","avatar":""},{"name":"Abigail Oliver","avatar":""},{"name":"Gigi Saul Guerrero","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324308);
