INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-xau-xa', 'Kẻ Xấu Xa', 'The Bad Guy', 'https://phimimg.com/upload/vod/20231202-1/b638a43901f69c131606ebc7a6ac749a.jpg', 'https://phimimg.com/upload/vod/20231202-1/8fed399037571b9f6d16d47cbae0f9bc.jpg', '<p>Câu chuyện về Nino Scotellaro, một công tố viên người Sicily, người đã cống hiến cả cuộc đời mình để chiến đấu chống lại mafia và đột nhiên bị buộc tội là một trong những người mà anh ta luôn chống lại. Sau khi bị kết án và không còn gì để mất, Nino quyết định thực hiện kế hoạch trả thù Machiavellian.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 19, 2022, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Luigi Lo Cascio","avatar":""},{"name":"Claudia Pandolfi","avatar":""},{"name":"Vincenzo Pirrotta","avatar":""},{"name":"Selene Caramazza","avatar":""},{"name":"Giulia Maenza","avatar":""},{"name":"Antonio Catania","avatar":""},{"name":"Fabrizio Ferracane","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324308);
