INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('honor-society', 'Honor Society', 'Honor Society', 'https://phimimg.com/upload/vod/20231125-1/952c44d9382bc1333f2240be8c44c477.jpg', 'https://phimimg.com/upload/vod/20231125-1/48adcffc56e79d22dcf09e98cc09c26a.jpg', '<p>Honor là một học sinh trung học đầy tham vọng với trọng tâm duy nhất là vào Harvard, cho rằng cô ấy có thể đạt điểm đầu tiên khi được người cố vấn hướng dẫn của mình, ông Calvin, cho biết. Sẵn sàng làm bất cứ điều gì cần thiết, Honor thực hiện một kế hoạch giống như Machiavellian để hạ gục ba đối thủ cạnh tranh sinh viên hàng đầu của cô, cho đến khi mọi thứ chuyển hướng khi cô bất ngờ rơi vào đối thủ lớn nhất của mình, Michael.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Angourie Rice","avatar":""},{"name":"Gaten Matarazzo","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"Armani Jackson","avatar":""},{"name":"Amy Keum","avatar":""},{"name":"Ben Jackson Walker","avatar":""},{"name":"Kelcey Mawema","avatar":""},{"name":"Avery Konrad","avatar":""},{"name":"Michael P. Northey","avatar":""},{"name":"Kerry Butler","avatar":""},{"name":"Andres Collantes","avatar":""},{"name":"Danny Wattley","avatar":""},{"name":"Candice Hunter","avatar":""},{"name":"Arghavan Jenati","avatar":""},{"name":"Miku Martineau","avatar":""},{"name":"Jason","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324308);
