INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-be-bang-gia', 'Bốn Bề Băng Giá', 'Against the Ice', 'https://phimimg.com/upload/vod/20231125-1/6bc6b5c64b7688ec0bfd73c280261462.jpg', 'https://phimimg.com/upload/vod/20231125-1/0241d2b5e9c49ddeacdeb32c1493df28.jpg', '<p>Hai người đàn ông phải cố gắng để sinh tồn khi tiến vào vùng đất bao la ở Greenland để tìm bản đồ bị mất. Chuyện có thật về cuộc thám hiểm địa cực năm 1909 của Đan Mạch.</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Nikolaj Coster-Waldau","avatar":""},{"name":"Joe Cole","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Heida Reed","avatar":""},{"name":"Gísli Örn Garðarsson","avatar":""},{"name":"Sam Redford","avatar":""},{"name":"Diarmaid Murtagh","avatar":""},{"name":"Ed Speleers","avatar":""},{"name":"Frankie Wilson","avatar":""},{"name":"Nick Jameson","avatar":""},{"name":"Þorsteinn Bachmann","avatar":""},{"name":"Árni Þór Lárusson","avatar":""},{"name":"Haukur M. Hrafnsson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324308);
