INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duc-hoa-mau-dan', 'Dục Hỏa Mẫu Đan', 'BURNING PEONY', 'https://phimimg.com/upload/vod/20231125-1/95109096ae9b3686b89cf84146e1212d.jpg', 'https://phimimg.com/upload/vod/20231125-1/359a8c899e56a9c5b05b224a68f1a20b.jpg', '<p>Đỉnh núi Côn Lôn được xưng là thần điện nắm giữ vạn vật, Hoa Vương của Tiên giới đột ngột tạ thế trước sự chứng kiến của người người tại Bách Hoa Yến dẫn ra mọi chuyện. Hết thảy những chuyện như biến con rối thành người thật, hút mệnh để trường thọ, mẫu đơn chìm trong biển lửa, thần khí tinh linh đều tham gia vào câu chuyện này. Thượng cổ thần khí có thể đánh đổi lấy tất thảy, từ đó thể hiện được khát cầu trong lòng người vô cùng sống động. Tiên môn ẩn dật, các hộ tiên gia trên đảo Bách Hoa của Thiên Giới lần lời tiêu vong một cách bí ẩn, danh tính thật sự của Mẫu Đơn Hoa Vương lại khó lòng xác thực. Nam chính là thần thú Tì Hưu, hút cạn sông hồ để dập tan lôi hoả thiên kiếp trên người nữ chính, nữ chính lại đem lòng thương vị thần quân vốn là một con rối, nhưng vẫn biết rằng trong chuyện tình này, mình lại xem tình cảm của Hoa Vương là vật thay thế. Khi thế thân và danh tính thật hợp lại, lại lỡ làng một đoạn lương duyên đích thực</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lai Yu Meng","avatar":""},{"name":"Jia Zhengyu","avatar":""},{"name":"Yang Jingru","avatar":""},{"name":"Fu Qianwen","avatar":""},{"name":"Yun Xiang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324308);
