INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-kiem', 'Tìm Kiếm', 'Missing', 'https://phimimg.com/upload/vod/20231124-1/5ac7a68cb2e5ab4908c7b5487337321a.jpg', 'https://phimimg.com/upload/vod/20231124-1/8ff50ab44cb31981b7d193063246022f.jpg', '<p>Sau cái chết của vợ, Santoshi chìm trong trầm cảm và nợ nần, trước sự kinh hoàng của con gái ông, học sinh trung học Kaede. Để xóa nợ, Santoshi quyết tâm truy tìm kẻ giết người hàng loạt đang bị truy nã nhằm lấy thưởng, trong sự ngỡ ngàng của con gái. Một ngày, Santoshi biến mất và Kaede vô hình lại rơi vào hành trình đi tìm bố.</p>', 'Full', 1, 'single', 'completed', 8, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Jiro Sato","avatar":""},{"name":"Aoi Ito","avatar":""},{"name":"Hiroya Shimizu","avatar":""},{"name":"Misato Morita","avatar":""},{"name":"Shotaro Ishii","avatar":""},{"name":"Izumi Matsuoka","avatar":""},{"name":"Tôko Narushima","avatar":""},{"name":"Tōru Shinagawa","avatar":""},{"name":"Nishimoto Ryuuki","avatar":""},{"name":"Yasuo Sugimoto","avatar":""},{"name":"Yuya Matsuura","avatar":""},{"name":"Masayasu Kitayama","avatar":""},{"name":"Roy Kishima","avatar":""},{"name":"Shion Nakamaru","avatar":""},{"name":"Masaki Naito","avatar":""},{"name":"Ichiko Kurenai","avatar":""},{"name":"Misa Wada","avatar":""},{"name":"Tsu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324308);
