INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tha-thu', 'Tha Thứ', 'The Forgiven', 'https://phimimg.com/upload/vod/20231124-1/e6c03fd275c35bcc434f1bde5d4b3cfe.jpg', 'https://phimimg.com/upload/vod/20231124-1/9541188b2b49438c26e09f6e6b2de0fd.jpg', '<p>Tăng tốc băng qua sa mạc Maroc để tham dự bữa tiệc cuối tuần xa hoa của một người bạn cũ, những người London giàu có David và Jo Henninger (Ralph Fiennes và Jessica Chastain) dính vào một vụ tai nạn thương tâm với một thiếu niên địa phương. Đến căn biệt thự hoành tráng với bữa tiệc thác loạn đang hoành hành muộn, cặp đôi cố gắng che đậy vụ việc với sự thông đồng của cảnh sát địa phương. Nhưng khi cha của cậu bé đến tìm kiếm công lý, sân khấu được thiết lập cho một cuộc đụng độ văn hóa đầy căng thẳng, trong đó David và Jo phải đối mặt với hành động định mệnh của họ và hậu quả tan vỡ của</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ralph Fiennes","avatar":""},{"name":"Jessica Chastain","avatar":""},{"name":"Matt Smith","avatar":""},{"name":"Caleb Landry Jones","avatar":""},{"name":"Abbey Lee","avatar":""},{"name":"Christopher Abbott","avatar":""},{"name":"Marie-Josée Croze","avatar":""},{"name":"Alex Jennings","avatar":""},{"name":"Saïd Taghmaoui","avatar":""},{"name":"David McSavage","avatar":""},{"name":"Mourad Zaoui","avatar":""},{"name":"Imane Elmechrafi","avatar":""},{"name":"Ben Affan","avatar":""},{"name":"Ismael Kanater","avatar":""},{"name":"Anas El Baz","avatar":""},{"name":"Brianna Bella","avatar":""},{"name":"Omar G","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324308);
