INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('curious-caterer-cam-bay-socola', 'Curious Caterer: Cạm Bẫy Sôcôla', 'Curious Caterer: Dying for Chocolate', 'https://phimimg.com/upload/vod/20231124-1/ac9573cf84f2b05256507b64d14aaf10.jpg', 'https://phimimg.com/upload/vod/20231124-1/1668713d02c316b6383be92426bb9368.jpg', '<p>Goldy là một bà mẹ đơn thân mạnh mẽ, người dấn thân vào vai thám tử thị trấn để giúp giải quyết cái chết bí ẩn của một người bạn. Khi đồng hồ kêu tích tắc để tìm ra thủ phạm, Goldy bắt đầu một mối quan hệ hợp tác khó có thể xảy ra với Thám tử Tom Schultz, người dựa vào kiến thức địa phương của Goldy. Khi mối quan hệ của họ có dấu hiệu trở thành một thứ gì đó hơn thế nữa, danh sách nghi phạm tăng lên. Goldy sẽ thu hẹp kẻ giết người trước khi kẻ giết người thu hẹp cô ấy?</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Nikki DeLoach","avatar":""},{"name":"Andrew W. Walker","avatar":""},{"name":"Jaycie Dotin","avatar":""},{"name":"Jason Schombing","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Riley Davis","avatar":""},{"name":"Kendall Cross","avatar":""},{"name":"Jason Tremblay","avatar":""},{"name":"Antonio Cayonne","avatar":""},{"name":"Maesa Nicholson","avatar":""},{"name":"Erin Boyes","avatar":""},{"name":"Shawna Clarke","avatar":""},{"name":"Easton Van B","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324308);
