INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('she-said', 'She Said', 'She Said', 'https://phimimg.com/upload/vod/20231123-1/c5100e33b4961156742f76415f0ae909.jpg', 'https://phimimg.com/upload/vod/20231123-1/e9905e70a032de1675fb43ed3a715e90.jpg', '<p>Các phóng viên Megan Twohey và Jodi Kantor của New York Times đã phá vỡ một trong những câu chuyện quan trọng nhất trong cả một thế hệ — câu chuyện giúp phát động phong trào #MeToo và phá vỡ hàng thập kỷ im lặng xung quanh chủ đề tấn công tình dục ở Hollywood.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Carey Mulligan","avatar":""},{"name":"Zoe Kazan","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Andre Braugher","avatar":""},{"name":"Jennifer Ehle","avatar":""},{"name":"Samantha Morton","avatar":""},{"name":"Ashley Judd","avatar":""},{"name":"Zach Grenier","avatar":""},{"name":"Peter Friedman","avatar":""},{"name":"Tom Pelphrey","avatar":""},{"name":"Frank Wood","avatar":""},{"name":"Adam Shapiro","avatar":""},{"name":"Roxanna Hope","avatar":""},{"name":"Lola Petticrew","avatar":""},{"name":"Angela Yeoh","avatar":""},{"name":"Sean Cullen","avatar":""},{"name":"Gregg Edelman","avatar":""},{"name":"Katheri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324308);
