INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-choi-vuot-thoi-khong', 'Người Chơi Vượt Thời Không', 'I Am A Super Star', 'https://phimimg.com/upload/vod/20231203-1/d5164202121c7f718ba58f7aeaff7b92.jpg', 'https://phimimg.com/upload/vod/20231203-1/bb78f227a30f81365366cc01563dc95e.jpg', '<p>Người Chơi Vượt Thời Không kể về câu chuyện của Trương Diệp, một người vô danh ở thế giới ban đầu, vì thí nghiệm của người ngoài hành tinh mà xuyên không vào thế giới trò chơi. Ở nơi đây, anh ta từng bước phản công trở thành một ngôi sao lớn, cũng phải đối mặt với rất nhiều thử thách của bản chất con người.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 17, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wei Da Xun","avatar":""},{"name":"Tân Chỉ Lôi","avatar":""},{"name":"Trương Nghệ Thượng","avatar":""},{"name":"Zhang Zi Xian","avatar":""},{"name":"Gao Yu Xi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324308);
