INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-sac-loc-vuong', 'Cửu Sắc Lộc Vương', 'Nine colors deer king', 'https://phimimg.com/upload/vod/20231121-1/5107dae5f4988c0cabf4a49a96b985bb.jpg', 'https://phimimg.com/upload/vod/20231121-1/d290ca26e0337ece7a64815c53c74e68.jpg', '<p>Một căn bệnh lạ đang lan tràn ở làng Hoan Nghi. Với sự hướng dẫn của Hề trường lão, Trường Sinh đã đi tìm kiếm các loại dược liệu cho dân làng. Tuy nhiên, vì việc này hiệu quả không cao và nguy hiểm, Trường Sinh quyết định tìm Cửu Sắc Lộc Vương huyền thoại để cứu ngôi làng. Ở một nơi khác, Yêu Hậu có ý định kiểm soát cung điện và đi tìm dấu vết của Cửu Sắc Lộc Vương để thực hành phép thuật của mình. Để ngăn chặn Yêu Hậu, Thái tử cũng bắt đầu cuộc phiêu lưu tìm kiếm Cửu Sắc Lộc Vương. Đội của Trường Sinh, Duyên Di, và đội săn đã lao đến con đường mòn đầu tiên của Cửu Sắc Lộc Vương - Khu rừng Lửa. Trường Sinh, Duyên Di trở thành bạn bè trong nguy hiểm, nhưng không để họ tìm thấy Cửu Sắc Lộc Vương, họ đã bị truy sát bởi Yêu Hậu và biết được kế hoạch khủng khiếp của ả. Mặc dù Trường Sinh, Duyên Di phải tiếp tục hành trình cùng đội săn trên đường đi vẫn phải lẩn tránh đội truy sát của Yêu Hậu, với sự giúp đỡ của Tiểu Lê và những người khác, cả hai đã vượt qua từng thử thách và trở thành người đầu tiên khám phá bí mật về Cửu Sắc Lộc Vương, cũng như cảm hóa Yêu Hậu giải cứu dân làng và Đại Nguyệt Quốc.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ge Qiugu","avatar":""},{"name":"Xu Heni","avatar":""},{"name":"Tan Yongwen","avatar":""},{"name":"Zhang Chunzhong","avatar":""},{"name":"Daniella Wang","avatar":""},{"name":"Mao Fan","avatar":""},{"name":"Bai Zhijie","avatar":""},{"name":"Ai Li-Ku","avatar":""},{"name":"Hou Tongjiang","avatar":""},{"name":"Xu Zhangchao","avatar":""},{"name":"Fang Xushi","avatar":""},{"name":"Zhang Yu Yi","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324308);
