INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-due-cua-clotilda', 'Hậu duệ của Clotilda', 'Descendant', 'https://phimimg.com/upload/vod/20231120-1/ac6f572842a90d1fabc0853eaf899b4c.jpg', 'https://phimimg.com/upload/vod/20231120-1/7ce7f8405a472d0a7ca6a3b1cebfe8c4.jpg', '<p>Họ là hậu duệ của những nô lệ châu Phi trên con tàu bất hợp pháp đến Alabama năm 1860. Giờ họ tìm công lý và sự chữa lành khi phần còn lại của con tàu được tìm thấy.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kamau Sadiki","avatar":""},{"name":"Emmett Lewis","avatar":""},{"name":"Vernetta Henson","avatar":""},{"name":"Veda Tunstall","avatar":""},{"name":"Joycelyn Davis","avatar":""},{"name":"Willomina Davis","avatar":""},{"name":"Mae Jones","avatar":""},{"name":"Lorna Woods","avatar":""},{"name":"Karlos Finley","avatar":""},{"name":"Kern Jackson","avatar":""},{"name":"Cleon Jones","avatar":""},{"name":"Joe Womack","avatar":""},{"name":"Vivian Figures","avatar":""},{"name":"Frederik Hiebert","avatar":""},{"name":"Jim Delgado","avatar":""},{"name":"Ramsey Sprague","avatar":""},{"name":"Darron Patterson","avatar":""},{"name":"Bob","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324309);
