INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-cua-cemara-2', 'Gia đình của Cemara 2', 'Cemara''s Family 2', 'https://phimimg.com/upload/vod/20231120-1/ff36af91b833bfb7caf5deb41a130f84.jpg', 'https://phimimg.com/upload/vod/20231120-1/a977a1e4a9a774ab174edef55b6d47d0.jpg', '<p>Trong khi bố mẹ họ nỗ lực kiếm sống lương thiện, ba cô con gái nhỏ trải qua những vấn đề riêng trong quá trình trưởng thành.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Ringgo Agus Rahman","avatar":""},{"name":"Nirina Zubir","avatar":""},{"name":"Adhisty Zara","avatar":""},{"name":"Widuri Puteri","avatar":""},{"name":"Asri Welas","avatar":""},{"name":"Niloufer Bahalwan","avatar":""},{"name":"Muzakki Ramdhan","avatar":""},{"name":"Abdurrahman Arif","avatar":""},{"name":"Kafin Sulthan","avatar":""},{"name":"Joshia Frederico","avatar":""},{"name":"Kawai Labiba","avatar":""},{"name":"Yasamin Jasem","avatar":""},{"name":"Yayu Unru","avatar":""},{"name":"Epy Kusnandar","avatar":""},{"name":"Joe P Project","avatar":""},{"name":"Totos Rasiti","avatar":""},{"name":"Ruth Mari","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324309);
