INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-nguc-tu', 'Trái Tim Ngục Tù', 'In the Heart of the Machine', 'https://phimimg.com/upload/vod/20231120-1/40374819a87ff02a537a1016d30ff024.jpg', 'https://phimimg.com/upload/vod/20231120-1/6f0293c982e6176b4c0cb2351ce771fe.jpg', '<p>Năm 1978, Bohemy, một tù nhân trẻ đang phục vụ tại Nhà tù Trung tâm ở Sofia , có cơ hội rút ngắn bản án nếu anh ta tập hợp một nhóm để tăng gấp đôi sản lượng trong thời gian họ làm việc tại nhà máy Kremikovtsi . Anh ta tập hợp một đội bao gồm Hatchet, một kẻ sát nhân kép khủng khiếp, tên tội phạm rắc rối Needle, Giáo viên lớn tuổi và Krasy gypsy . Vấn đề của họ bắt đầu khi Hatchet từ chối bật máy tiện của mình vì một con chim bồ câu bị mắc kẹt bên trong nó. Bất chấp việc Đại úy Vekilsky, quản giáo của nhà máy , ra lệnh cho anh ta bật máy tiện, Hatchet kiên quyết từ chối, bắt quản giáo tân binh Kovachky làm con tin và tuyên bố rằng anh ta sẽ không bắt đầu công việc cho đến khi con chim bồ câu được giải cứu. Tình hình nhanh chóng leo thang và ngày càng trở nên phức tạp sau khi có thêm lính canh đến và Giáo viên bị giết khi cố gắng thương lượng với họ. Dần dần, các tù nhân nhận ra rằng cách duy nhất để giải quyết tình huống là giải cứu chú chim như mong muốn của Hatchet.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Bulgaria', 0, '[{"name":"Alexander Sano","avatar":""},{"name":"Julian Vergov","avatar":""},{"name":"Hristo Petkov","avatar":""},{"name":"Hristo Shopov","avatar":""},{"name":"Igor Angelov","avatar":""},{"name":"Stoyan Doychev","avatar":""},{"name":"Ivaylo Hristov","avatar":""},{"name":"Bashar Rahal","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324309);
