INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('guc-nga-truoc-dong-tien', 'Gục Ngã Trước Đồng Tiền', 'Dead for a Dollar', 'https://phimimg.com/upload/vod/20231120-1/f534749283a2b6173e3c6131aeff753c.jpg', 'https://phimimg.com/upload/vod/20231120-1/69693557d1c9c96f199b45e449b1337f.jpg', '<p>Khi nó xuất hiện một phụ nữ trẻ đã chạy trốn với một quân đội đào ngũ, một khẩu súng được thuê, Max, được ký hợp đồng để truy đuổi họ và mang cô ấy về nhà. Phát hiện ra rằng cô bỏ trốn khỏi người chồng bạo hành, Max phải đối mặt với sự lựa chọn hoàn thành công việc hoặc nhìn theo hướng khác trong khi những sát thủ tàn nhẫn và đối thủ lâu năm của anh ta, Joe, đang áp sát.</p>', 'Full', 1, 'single', 'completed', 22, 2022, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Christoph Waltz","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Rachel Brosnahan","avatar":""},{"name":"Hamish Linklater","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"Guy Burnet","avatar":""},{"name":"Brandon Scott","avatar":""},{"name":"Scott Peat","avatar":""},{"name":"Warren Burke","avatar":""},{"name":"Luis Chávez","avatar":""},{"name":"Jackamoe Buzzell","avatar":""},{"name":"Diana Navarrete","avatar":""},{"name":"J.D. Garfield","avatar":""},{"name":"Shawn-Caulin Young","avatar":""},{"name":"Vic Browder","avatar":""},{"name":"Alfredo Quiroz","avatar":""},{"name":"Rocko R","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324309);
