INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuc-gian-tot-cung', 'Tức Giận Tột Cùng', 'High Heat', 'https://phimimg.com/upload/vod/20231123-1/9f52d670027f37933cf6d7c7e40c0bd9.jpg', 'https://phimimg.com/upload/vod/20231123-1/789f7d3abbc54d88171d99a1ff126ece.jpg', '<p>Với sự tham gia của Don Johnson (Knives Out) và Olga Kurylenko (Quantum of Solace). Một cựu nhân viên KGB đã trở thành đầu bếp, Ana (Kurylenko) là mục tiêu của mafia địa phương trong một cuộc tấn công vào nhà hàng mới của cô ấy để đòi nợ của chồng cô ấy (Johnson). Giờ đây, Ana phải dựa vào những kỹ năng chết người của mình khi cô nổi cơn thịnh nộ chết người để lần lượt tiêu diệt toàn bộ tổ chức tội phạm để cứu nhà hàng của mình và sống sót qua đêm trong bộ phim tội phạm ly kỳ đầy hành động này.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Olga Kurylenko","avatar":""},{"name":"Don Johnson","avatar":""},{"name":"Chris Diamantopoulos","avatar":""},{"name":"Kaitlin Doubleday","avatar":""},{"name":"Page Falkinburg Jr.","avatar":""},{"name":"Dylan Flashner","avatar":""},{"name":"Bianca D''Ambrosio","avatar":""},{"name":"Erik Bloomquist","avatar":""},{"name":"Carlos Flores","avatar":""},{"name":"Cathy Salvodon","avatar":""},{"name":"Chiara D''Ambrosio","avatar":""},{"name":"Donnie Francis","avatar":""},{"name":"Emmanuel Kerry","avatar":""},{"name":"Greg Nutcher","avatar":""},{"name":"Heathe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324309);
