INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-vay-ham-cua-robin-hood', 'Cuộc Vây Hãm Của Robin Hood', 'The Siege of Robin Hood', 'https://phimimg.com/upload/vod/20231123-1/cc6ca9f9880b9fb702f5fc6a6b74b1c8.jpg', 'https://phimimg.com/upload/vod/20231123-1/97c99ae7ca433c02259dbdd3f4f81586.jpg', '<p>Khi cảnh sát trưởng của binh lính Nottingham tấn công tàn bạo gia đình anh ta, một thanh niên tên là Robin thề sẽ trả thù đẫm máu những người đàn ông chịu trách nhiệm. Anh ta tuyển mộ một đội gồm những kẻ bị ruồng bỏ, mavericks và những chiến binh chạy trốn, mỗi người đều có mối hận thù phải giải quyết với Cảnh sát trưởng và một kỹ năng chiến đấu cực kỳ phù hợp. Họ cùng nhau vạch ra một kế hoạch để trả thù chính xác nhất</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Paul Allica","avatar":""},{"name":"John Fallon","avatar":""},{"name":"Peter Roordink","avatar":""},{"name":"Keanu Gonzalez","avatar":""},{"name":"Dave Beamish","avatar":""},{"name":"Kahli Williams","avatar":""},{"name":"David Macrae","avatar":""},{"name":"Tom McCathie","avatar":""},{"name":"Nina Iaroslavtseva","avatar":""},{"name":"Wallis Murphy-Munn","avatar":""},{"name":"Steve Young","avatar":""},{"name":"Sophie Hardy","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324309);
