INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-vay-ham-cua-robin-hood', 'Cuộc Vây Hãm Của Robin Hood', 'The Siege of Robin Hood', 'cuộc vây hãm của robin hood the siege of robin hood paul allica john fallon peter roordink keanu gonzalez dave beamish kahli williams david macrae tom mccathie nina iaroslavtseva wallis murphy-munn steve young sophie hardy ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-chien', 'Manh Chiến', 'Blind War', 'https://phimimg.com/upload/vod/20231123-1/d1ad7e49f2ff072551ae913e6461c09d.jpg', 'https://phimimg.com/upload/vod/20231123-1/71ebce7e36a20cccdad27a3ed2d28bbb.jpg', '<p>Nội dung phim xoay quanh câu chuyện về cựu đội trưởng SWAT Đông Cốc (do An Chí Kiệt thủ vai) bị bọn côn đồ tấn công Đông Cốc trong quá trình làm việc không may bị thương và bị mù vĩnh viễn, và phải chịu trách nhiệm về việc nhiệm vụ bị thất bại. Dưới sự giúp đỡ và đồng hành của con gái, Đông Cốc dần vượt qua khó khăn và chấp nhận việc bản thân bị mù. Kẻ thù cũ của anh lại xuất hiện, con gái anh rơi vào nguy hiểm. Để cứu con gái, Đông Cốc bắt đầu cuộc chiến sinh tử với đôi mắt không thấy ánh sáng.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Andy On","avatar":""},{"name":"Yang Xing","avatar":""},{"name":"Qi Shenghan","avatar":""},{"name":"Zhang Yaqi","avatar":""},{"name":"Wang Han-Yang","avatar":""},{"name":"Jane Wu","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324309);
