INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('selena-gomez-my-mind-me', 'Selena Gomez: My Mind & Me', 'Selena Gomez: My Mind & Me', 'https://phimimg.com/upload/vod/20231123-1/650b32bcc2cc3e1b8fd15aabb67edda1.jpg', 'https://phimimg.com/upload/vod/20231123-1/08d5aacbdb404f26e2916814408dd626.jpg', '<p>Sau nhiều năm hoạt động dưới ánh đèn sân khấu, Selena Gomez đã đạt được ngôi sao ngoài sức tưởng tượng. Nhưng ngay khi cô ấy đạt đến một đỉnh cao mới, một ngã rẽ bất ngờ kéo cô ấy vào bóng tối. Bộ phim tài liệu thô sơ và gần gũi độc đáo này đã kéo dài cuộc hành trình sáu năm của cô ấy sang một ánh sáng mới.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Selena Gomez","avatar":""},{"name":"Raquelle Stevens","avatar":""},{"name":"Ashley Cook","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324309);
