INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-gai-pha-le', 'Những cô gái pha lê', 'Dancing on Glass', 'https://phimimg.com/upload/vod/20231123-1/32527c5b0ee12bbfe9abde97f2d18d0b.jpg', 'https://phimimg.com/upload/vod/20231123-1/e8ea5c9446ea9e12c0a2929cf80fe831.jpg', '<p>Khi áp lực nặng nề đè lên một nữ diễn viên ba lê mới nhận vai chính, cô và một vũ công khác xây dựng một tình bạn đưa họ lánh xa thế giới thực tại.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"María Pedraza","avatar":""},{"name":"Paula Losada","avatar":""},{"name":"Mona Martínez","avatar":""},{"name":"Marta Hazas","avatar":""},{"name":"Ana Wagener","avatar":""},{"name":"Juanjo Almeida","avatar":""},{"name":"Jota Castellano","avatar":""},{"name":"Iria del Río","avatar":""},{"name":"Jessica Rookeward","avatar":""},{"name":"Olivia Baglivi","avatar":""},{"name":"Hannah Taylor","avatar":""},{"name":"Paqui Horcajo","avatar":""},{"name":"Fernando Delgado-Hierro","avatar":""},{"name":"Silvia Kal","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324309);
