INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('not-okay', 'Not Okay', 'Not Okay', 'https://phimimg.com/upload/vod/20231123-1/5361389bca145b9cd4d6f8bbde94dbf3.jpg', 'https://phimimg.com/upload/vod/20231123-1/81529ce970e50cf73df0eb33452b5932.jpg', '<p>Một phụ nữ trẻ đầy tham vọng, khao khát người theo dõi và sự nổi tiếng, đã giả mạo một chuyến đi đến Paris để tăng cường sự hiện diện trên mạng xã hội của mình. Khi một sự việc đáng sợ xảy ra trong thế giới thực và trở thành một phần trong chuyến đi tưởng tượng của cô ấy, lời nói dối trắng trợn của cô ấy trở thành một điều khó khăn về mặt đạo đức mang lại cho cô ấy tất cả sự chú ý mà cô ấy muốn.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zoey Deutch","avatar":""},{"name":"Mia Isaac","avatar":""},{"name":"Dylan O''Brien","avatar":""},{"name":"Nadia Alexander","avatar":""},{"name":"Tia Dionne Hodge","avatar":""},{"name":"Negin Farsad","avatar":""},{"name":"Embeth Davidtz","avatar":""},{"name":"Karan Soni","avatar":""},{"name":"Sarah Yarkin","avatar":""},{"name":"Gwyneth Anne Trumbore","avatar":""},{"name":"Peter Patrikios","avatar":""},{"name":"Steven Bono Jr.","avatar":""},{"name":"Blaise Corrigan","avatar":""},{"name":"Simone Vysnovsky","avatar":""},{"name":"Logan Crawford","avatar":""},{"name":"Judy Zheng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324309);
