INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-dong-long-linh', 'Mê Động Long Lĩnh', 'Tomb Adventurer', 'https://phimimg.com/upload/vod/20231123-1/f3109d8898fad3cd6d8cf3cf18f5bc6c.jpg', 'https://phimimg.com/upload/vod/20231123-1/1f40cc92f08f6aaa18f96e4a75e31adb.jpg', '<p>Sau khi trở về từ thành cổ Jingjue, Xue Li Yang phát hiện ra rằng lời nguyền của ban đỏ mắt ma đã ảnh hưởng đến cô, và sử dụng chiến lược để cho King Hu Bayi, Fatty Wang và những người khác đi đến Longling Labyrinth để tìm Cuốn sách Xương rồng. , cố gắng dỡ bỏ lời nguyền. Chấp nhận rủi ro, chạm trán với những con thú thần thoại cổ đại, một con cá trê khổng lồ, vua rồng đầu sắt, những con sói mắt đỏ ăn xương người và chiến đấu với nhện mặt người, con đường phía trước không chắc chắn, liệu họ có thể trốn thoát…</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cai Heng","avatar":""},{"name":"Gu Xuan","avatar":""},{"name":"Yusi Chen","avatar":""},{"name":"Marc Ma","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324309);
