INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tranh-thoi-thieu-nu', 'Chiến Tranh Thời Thiếu Nữ', 'The Midnight Maiden War', 'https://phimimg.com/upload/vod/20231123-1/b5718c6c33322c263c072ae3f04d7a73.jpg', 'https://phimimg.com/upload/vod/20231123-1/7d267358fa66696cad352de7e48f8c2e.jpg', '<p>Tôi là một trường đại học, người đến Tokyo từ quê hương của mình. Tôi sống một mình và không có bạn bè hay bạn gái. Cuộc sống đại học của tôi thật nhàm chán và anh ấy không có ước mơ. Tôi tự nuôi sống bản thân bằng cách đi làm thuê ban ngày ở công trường. Tôi gặp hai người tại một câu lạc bộ trốn tìm. Một người là Senior của anh ấy và người còn lại là Black Suit. Khi gặp họ, cuộc sống nhàm chán của tôi thay đổi. Họ bắt đầu &quot;Midnight Maiden War&quot;, đó là kế hoạch của họ để phá hủy Tokyo.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ren Nagase","avatar":""},{"name":"Elaiza Ikeda","avatar":""},{"name":"Tasuku Emoto","avatar":""},{"name":"Makiko Watanabe","avatar":""},{"name":"Songha","avatar":""},{"name":"Masaya Sano","avatar":""},{"name":"Mayu Yamaguchi","avatar":""},{"name":"Akinori Ando","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324309);
