INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chien-tranh-thoi-thieu-nu', 'Chiến Tranh Thời Thiếu Nữ', 'The Midnight Maiden War', 'chiến tranh thời thiếu nữ the midnight maiden war ren nagase elaiza ikeda tasuku emoto makiko watanabe songha masaya sano mayu yamaguchi akinori ando ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doc-thich-nhap-hau', 'Độc Thích Nhập Hầu', 'Stabbing Into the Throat', 'https://phimimg.com/upload/vod/20231123-1/738f99f2faeb5009701ef616a6ac3125.jpg', 'https://phimimg.com/upload/vod/20231123-1/300b8ffa956bf9f9b99ee0cfa9a78b87.jpg', '<p>Lu Yao phát hiện ra rằng em gái mình đang bị bắt làm con tin bởi những kẻ buôn bán ma túy, và các thành viên trong nhóm muốn trao đổi Maitreya với em gái của anh ta. Nhưng Lu Yao kiên quyết phản đối, và thực sự giơ súng nhắm vào chính chị gái của mình. Trước chính nghĩa quốc gia và lợi ích cá nhân, Lu Yao đã chọn đất nước. Maitreya bị sốc trước quyết định của Lu Yao, anh ta sợ hãi nên phải thỏa hiệp và ra lệnh cho cấp dưới buông tha cho em gái mình. Đám đông bắt đầu thực hiện Kế hoạch B, đi đến một thị trấn gần đó và đi qua đó để đến biên giới. Nhưng điều bất ngờ là họ đã bước vào &quot;địa ngục&quot; Đây là thế giới của Di Lặc. Không chỉ những kẻ buôn bán ma túy rượt đuổi, giết chóc, ngay cả những đứa trẻ đang chơi đùa bên đường cũng giơ hung khí lên và bắn vào người ngay lập tức. Họ sẽ phải đối mặt với trận chiến khốc liệt nào? Di Lặc ném mình vào lưới nhằm mục đích gì? Liệu Lu Yao và những người khác có thể đưa em gái và Maitreya thoát khỏi &quot;địa ngục&quot; và trở về đất mẹ? Hoàn thành xuất sắc nhiệm vụ được gọi là &quot;Poison in the Họng&quot;.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"YuanFufu","avatar":""},{"name":"Jiang Jingzhong","avatar":""},{"name":"Chen Qianli","avatar":""},{"name":"Zhao Muyan","avatar":""},{"name":"Wang Xiaolei","avatar":""},{"name":"Wang Yuze","avatar":""},{"name":"Zhang Shaorong","avatar":""},{"name":"Li Xinbiao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324309);
