INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-moi-mau-lanh', 'Kẻ Săn Mồi Máu Lạnh', 'Assailant', 'https://phimimg.com/upload/vod/20231123-1/324d416db54535da4143fcb6ebe811bb.jpg', 'https://phimimg.com/upload/vod/20231123-1/2d59b1858afe788d8cb2d6b3d01d4faf.jpg', '<p>Cuộc hôn nhân của một cặp vợ chồng người Anh diễn ra trên đá, đi thuyền đến vùng biển Caribê với hy vọng cứu vãn cuộc hôn nhân của họ. Sau một cuộc chiến trong quán bar tưởng chừng như vô hại giữa người chồng và một kẻ say rượu bí ẩn, tình huống chuyển thành một trò chơi nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Poppy Delevingne","avatar":""},{"name":"Chad Michael Collins","avatar":""},{"name":"Casper Van Dien","avatar":""},{"name":"Jeff Fahey","avatar":""},{"name":"Danielle Browne","avatar":""},{"name":"Spencer Collings","avatar":""},{"name":"Frank Corbie","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324309);
