INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-trung-co', 'Anh hùng Trung cổ', 'Medieval', 'https://phimimg.com/upload/vod/20230912-1/e84f49e1e3be598b8effa07b45ddbef2.jpg', 'https://phimimg.com/upload/vod/20230912-1/9d8c634abb0f5fbc6975218cf55a0ed0.jpg', '<p>Câu chuyện về biểu tượng và lãnh chúa người Séc thế kỷ 14 Jan Zizka, người đã đánh bại quân đội của Dòng Teutonic và Đế chế La Mã Thần thánh.</p>', 'Full', 1, 'single', 'completed', 35, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Ben Foster","avatar":""},{"name":"Sophie Lowe","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Til Schweiger","avatar":""},{"name":"Matthew Goode","avatar":""},{"name":"Roland Møller","avatar":""},{"name":"William Moseley","avatar":""},{"name":"Karel Roden","avatar":""},{"name":"Werner Daehn","avatar":""},{"name":"Jan Budař","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Điển","slug":"kinh-dien","id":"268385d0de78827ff7bb25c35036ee2a"}]', '[]', 1784690324309);
