INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('raymond-va-ray', 'Raymond và Ray', 'Raymond & Ray', 'https://phimimg.com/upload/vod/20231120-1/c4812e94e59a38aede82ea7101067a40.jpg', 'https://phimimg.com/upload/vod/20231120-1/2f3793f167cf21f28889872f93b15799.jpg', '<p>Hai anh em cùng cha khác mẹ Raymond và Ray đoàn tụ khi người cha ghẻ lạnh của họ qua đời - và phát hiện ra rằng điều ước cuối cùng của anh là được đào mộ anh. Cùng nhau, họ xử lý những người họ đã trở thành đàn ông, cả vì cha của họ và bất chấp ông.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Maribel Verdú","avatar":""},{"name":"Sophie Okonedo","avatar":""},{"name":"Vondie Curtis-Hall","avatar":""},{"name":"Todd Louiso","avatar":""},{"name":"Tom Bower","avatar":""},{"name":"Maxim Swinton","avatar":""},{"name":"Chris Silcox","avatar":""},{"name":"Chris Grabher","avatar":""},{"name":"Oscar Nunez","avatar":""},{"name":"Angie Campbell","avatar":""},{"name":"Gina Jun","avatar":""},{"name":"Laura Linda Bradley","avatar":""},{"name":"Aaron Angus","avatar":""},{"name":"Angela Deiss","avatar":""},{"name":"Jim Meisner Jr.","avatar":""},{"name":"Mike","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324309);
