INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bia-do-dan', 'Bia Đỡ Đạn', 'Bullet Proof', 'https://phimimg.com/upload/vod/20231120-1/e41045ebc38148a15fd8ba2d91a4f6ce.jpg', 'https://phimimg.com/upload/vod/20231120-1/35f00fa2f41a40051dda355784606f5e.jpg', '<p>Vinnie Jones vào vai Temple, một trùm băng đảng tàn bạo, trong chuyến hành động tàn bạo, da trắng này. Sau khi lấy trộm hàng triệu đồng tiền mặt từ nơi ẩn náu buôn bán ma túy của Temple, Kẻ trộm tìm thấy một người trốn theo xe hơi của hắn - vợ đang mang thai của Temple, Mia! Mong muốn đòi lại tiền mặt của mình - và đứa con trai chưa chào đời của mình - Temple cử một đội gồm những tên sát nhân và thợ săn tiền thưởng để truy đuổi. Tốc độ, sự thông minh và nhắm tốt mang lại cho bộ đôi này một lợi thế ngắn ngủi, nhưng vận may của họ sẽ tồn tại được bao lâu? cùng xem tiếp trên phimmoichills để biết kết cục sẽ thế nào nhé.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vinnie Jones","avatar":""},{"name":"Lina Lecompte","avatar":""},{"name":"James Clayton","avatar":""},{"name":"Janvier Katabarwa","avatar":""},{"name":"Danny Mac","avatar":""},{"name":"Glenn Ennis","avatar":""},{"name":"Philip Granger","avatar":""},{"name":"Lori Triolo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324309);
