INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-thit-xay', 'Chiến Dịch Thịt Xay', 'Operation Mincemeat', 'https://phimimg.com/upload/vod/20231120-1/983a2932ebd35484c51351c75b7bc051.jpg', 'https://phimimg.com/upload/vod/20231120-1/7821722465eb34213fc47f630a045622.jpg', '<p>Năm 1943, hai sĩ quan tình báo Anh tổ chức Chiến dịch Mincemeat, trong đó kế hoạch thả một xác chết với giấy tờ giả ngoài khơi bờ biển Tây Ban Nha sẽ đánh lừa các điệp viên Đức Quốc xã tin rằng lực lượng Đồng minh đang lên kế hoạch tấn công bằng con đường vào Hy Lạp chứ không phải Sicily.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Colin Firth","avatar":""},{"name":"Matthew Macfadyen","avatar":""},{"name":"Kelly Macdonald","avatar":""},{"name":"Penelope Wilton","avatar":""},{"name":"Johnny Flynn","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Mark Gatiss","avatar":""},{"name":"Hattie Morahan","avatar":""},{"name":"Paul Ritter","avatar":""},{"name":"Simon Russell Beale","avatar":""},{"name":"Lorne MacFadyen","avatar":""},{"name":"Markus von Lingen","avatar":""},{"name":"Ruby Bentall","avatar":""},{"name":"Alex Jennings","avatar":""},{"name":"Ellie Haddington","avatar":""},{"name":"Nicholas Rowe","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324309);
