INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('madea-tro-ve-nha', 'Madea Trở Về Nhà', 'Tyler Perry''s A Madea Homecoming', 'https://phimimg.com/upload/vod/20231120-1/cba02e30103b72cafc71e28d0ea0b64d.jpg', 'https://phimimg.com/upload/vod/20231120-1/21d308cd910a2206639e197e9419e409.jpg', '<p>Madea đã trở lại – quá tuyệt! Và bà không chấp nhận mấy chuyện vớ vẩn khi rắc rối gia đình nảy sinh ở lễ tốt nghiệp đại học của chắt trai mình.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tyler Perry","avatar":""},{"name":"Cassi Davis","avatar":""},{"name":"David Mann","avatar":""},{"name":"Tamela Mann","avatar":""},{"name":"Brendan O''Carroll","avatar":""},{"name":"Jennifer Gibney","avatar":""},{"name":"Brandon Black","avatar":""},{"name":"Isha Blaaker","avatar":""},{"name":"Gabrielle Dennis","avatar":""},{"name":"Amani Atkinson","avatar":""},{"name":"Geneva Maccarone","avatar":""},{"name":"Candace Neolani Maxwell","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324309);
