INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tang-dia-ky-binh', 'Tàng Địa Kỳ Binh', 'Tibetan Raiders', 'https://phimimg.com/upload/vod/20231116-1/9716633c9abcd08866ae1f80d2740126.jpg', 'https://phimimg.com/upload/vod/20231116-1/4b001bca12892507bb38bb6548b53d0e.jpg', '<p>Cách đây 6 năm, nhà nghiên cứu khảo cổ học Lin Guo Hua đã biến mất một cách bí ẩn ở Tây Tạng sau khi chứng minh được sự tồn tại của vua Gesar. Cô con gái Lin Xi kế thừa công việc kinh doanh của cha khi lớn lên và với sự giúp đỡ của chú Da, cô tiếp tục khám phá bí ẩn về Vua Gesar. Ma Qiang, người tình cờ gặp một người lính đặc nhiệm đã nghỉ hưu bên ngoài sân bay cao nguyên, trở thành hướng dẫn viên lái xe của họ, và cả ba bắt đầu một cuộc phiêu lưu ly kỳ cùng nhau. Vào thời khắc sinh tử, cô gái Tây Tạng Zhuo Ma xuất hiện để giúp đỡ, cả bốn thành lập một đội lính Tây Tạng để tiếp tục khám phá sự thật.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Shawn Wei","avatar":""},{"name":"Qu Jingjing","avatar":""},{"name":"John Wu","avatar":""},{"name":"Jackie Lui Chung-Yin","avatar":""},{"name":"Xing Hanqing","avatar":""},{"name":"Wu Jingyi","avatar":""},{"name":"Chen Jian","avatar":""},{"name":"Yang Qingzhu","avatar":""},{"name":"Zhang Zhulin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324309);
