INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-vu-tru', 'Trở lại vũ trụ', 'Return to Space', 'https://phimimg.com/upload/vod/20231119-1/258196c309f8e0d43580bc75e11fc906.jpg', 'https://phimimg.com/upload/vod/20231119-1/57ea75c6b6b1c2d5273c1429b801ea9b.jpg', '<p>Elon Musk và các kỹ sư ở SpaceX bắt đầu thực hiện một dự án lịch sử là đưa các phi hành gia NASA trở lại Trạm Vũ trụ Quốc tế và cách mạng hóa du hành vũ trụ.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elon Musk","avatar":""},{"name":"Douglas Hurley","avatar":""},{"name":"Robert Behnken","avatar":""},{"name":"James Bridenstine","avatar":""},{"name":"Tim Dodd","avatar":""},{"name":"Hans-Jörg Koenigsmann","avatar":""},{"name":"Gwynne Shotwell","avatar":""},{"name":"Lars Blackmore","avatar":""},{"name":"Megan McArthur","avatar":""},{"name":"Kiko Dontchev","avatar":""},{"name":"Lori Garver","avatar":""},{"name":"Karen Nyberg","avatar":""},{"name":"Balachandar Ramamurthy","avatar":""},{"name":"Anna Menon","avatar":""},{"name":"Kay Bailey Hutchison","avatar":""},{"name":"Richard She","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324309);
