INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('heidi-dien-cuong', 'Heidi Điên Cuồng', 'Mad Heidi', 'https://phimimg.com/upload/vod/20230922-1/997e2cfa080fc0ac80433f0e321bde38.jpg', 'https://phimimg.com/upload/vod/20230922-1/b2a15c654df2786d612f15fa04e50964.jpg', '<p>Tại một Thụy Sĩ đen tối đã rơi vào sự thống trị của phát xít của một tên bạo chúa phô mai độc ác, Heidi sống một cuộc sống trong sáng và giản dị ở dãy núi Alps của Thụy Sĩ. Ông nội Alpöhi cố gắng hết sức để bảo vệ Heidi, nhưng khao khát tự do của cô sớm khiến cô gặp rắc rối với tay sai của nhà độc tài. Cô gái ngây thơ hóa thân thành một nữ chiến binh dũng mãnh lên đường giải phóng đất nước khỏi bọn phát xít phô mai điên cuồng.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Thụy Sĩ', 0, '[{"name":"Alice Lucy","avatar":""},{"name":"Max Rüdlinger","avatar":""},{"name":"Casper Van Dien","avatar":""},{"name":"David Schofield","avatar":""},{"name":"Kel Matsena","avatar":""},{"name":"Almar G. Sato","avatar":""},{"name":"Pascal Ulli","avatar":""},{"name":"Katja Kolm","avatar":""},{"name":"Rebecca Dyson-Smith","avatar":""},{"name":"Kaspar Weiss","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324309);
