INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xa-tien-duyen', 'Thanh Xà: Tiền Duyên', 'The fate of reunion', 'https://phimimg.com/upload/vod/20231117-1/1ab8cbcccefec7b3aa1e572bb61ea228.jpg', 'https://phimimg.com/upload/vod/20231117-1/1d57a85bf5da095844c75bee62b61c6e.jpg', '<p>Nghìn năm trước, Thanh Xà được Đạo Thanh soi sáng mà được khai hóa dần, muốn mãi mãi sống cùng với Đạo Thanh. Nhưng Đạo Thanh lại bị cuốn vào số kiếp luân hồi bởi sự ám ảnh của Thanh Xà, kiếp nào cũng chịu nỗi đau đột tử. Để hóa giải số kiếp cho Đạo Thanh, Thanh Xà không ngừng tìm người đầu thai của Đạo Thanh...</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Gillian Chung","avatar":""},{"name":"Henry Prince Mak","avatar":""},{"name":"Lin Yo-Wei","avatar":""},{"name":"Sun Meinan","avatar":""},{"name":"Jiang Mengxuan","avatar":""},{"name":"Zhou Luoyi","avatar":""},{"name":"Yu Qinghui","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324309);
