INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hinh-xam-vo-hinh', 'Hình Xăm Vô Hình', 'Invisible Tattoo', 'https://phimimg.com/upload/vod/20231116-1/4bfb3193863d2a4b3b4d143b834b3f3e.jpg', 'https://phimimg.com/upload/vod/20231116-1/96795dc3dbcc88abbb8095b064da58e3.jpg', '<p>Văn thân là phim thuộc đề tài võ thuật. Nội dung xoay quanh chuyện tranh giành quyền lực liên miên giữa các băng nhóm tại một thị trấn công nghiệp muối ở phía Tây Nam Trung Quốc vào năm 1935. A Ca (Triệu Văn Trác) là bậc thầy xăm hình, bị vướng vào vụ ám sát, vô tình mưu phản băng nhóm của mình. Ngoài tài tử Hoàng Phi Hồng, Văn thân còn quy tụ võ sư hàng đầu Trung Quốc hiện nay là Nhất Long, Tang Bình và diễn viên khác như Từ Đông Đông, Phạm Dật Thần, Vương Thánh Địch.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vincent Zhao Wenzhuo","avatar":""},{"name":"David Belle","avatar":""},{"name":"Raquel Xu","avatar":""},{"name":"Li Mincheng","avatar":""},{"name":"Van Fan","avatar":""},{"name":"Sang Ping","avatar":""},{"name":"Yi Long","avatar":""},{"name":"Ge Tian","avatar":""},{"name":"Wang Shengdi","avatar":""},{"name":"Lai Xiaosheng","avatar":""},{"name":"Liu Jin","avatar":""},{"name":"Lai Xiaosheng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324309);
