INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('semantic-error-loi-logic', 'Semantic Error: Lỗi Logic', 'Semantic Error: The Movie', 'https://phimimg.com/upload/vod/20231116-1/fc1a93e8137860d887bf34029def0b0b.jpg', 'https://phimimg.com/upload/vod/20231116-1/071854e6a7dc625639818ab9a5d0a8d9.jpg', '<p>Choo Sang Woo - một cậu nhóc khô khan, máy móc, sống trong những khuôn khổ đầy tính logic. Jang Jae Young - chàng trai tài hoa, lãng tử, luôn bỏ qua mọi quy tắc để sống hết mình với đam mê, niềm vui tuổi trẻ. Hai con người, hai kim chỉ nam trái ngược nhau về lẽ sống nhưng lại cùng nhau chạm đến “định mệnh”. Cuộc sống tưởng chừng như gặp đầy “lỗi” bỗng chốc như trải đầy hoa.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Seo-ham","avatar":""},{"name":"Park Jae-chan","avatar":""},{"name":"Song Ji-oh","avatar":""},{"name":"Kim No-jin","avatar":""},{"name":"Kim Won-gi","avatar":""},{"name":"Choi Su-geon","avatar":""},{"name":"Cha Jae-hoon","avatar":""},{"name":"Jung Joon-gyo","avatar":""},{"name":"Ki Hyun-woo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324309);
