INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toscana', 'Toscana', 'Toscana', 'https://phimimg.com/upload/vod/20231116-1/f67dca3cfcfce440f65d755cdc7f5b33.jpg', 'https://phimimg.com/upload/vod/20231116-1/fe4f8b73d7bd6f5026210576d8866aff.jpg', '<p>Khi một đầu bếp Đan Mạch đến Tuscany để bán gia sản của bố, anh gặp một phụ nữ địa phương truyền cảm hứng cho anh nghĩ lại cách sống và yêu trong đời mình.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Anders Matthesen","avatar":""},{"name":"Cristiana Dell''Anna","avatar":""},{"name":"Andrea Bosca","avatar":""},{"name":"Ghita Nørby","avatar":""},{"name":"Sebastian Jessen","avatar":""},{"name":"Ari Alexander","avatar":""},{"name":"Christopher","avatar":""},{"name":"Karoline Brygmann","avatar":""},{"name":"Lærke Winther","avatar":""},{"name":"Christoffer Jindyl","avatar":""},{"name":"Pino Ammendola","avatar":""},{"name":"Sergio Pantani","avatar":""},{"name":"Thue Ersted Rasmussen","avatar":""},{"name":"Sarah Juel Werner","avatar":""},{"name":"Esther Han","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324309);
