INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-bao-vo-tan', 'Cơn Bão Vô Tận', 'Infinite Storm', 'https://phimimg.com/upload/vod/20231116-1/bc8ad633acedfcb6411ce2c3178678b6.jpg', 'https://phimimg.com/upload/vod/20231116-1/91048c7b9a3fcbe4178044858c9ba7d7.jpg', '<p>Là một nhà leo núi có kinh nghiệm, Pam quyết định quay lại trước khi lên đến đỉnh do nhận thấy một trận bão tuyết lớn ập đến. Nhưng trên đường đi xuống, cô bắt gặp một người đàn ông đang bị mắc kẹt và quyết định tự mình đưa cả hai xuống núi trước khi màn đêm buông xuống và họ không thể chống chọi được với cơn bão. Bộ phim dựa trên câu chuyện có thật về Pam Bales.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Naomi Watts","avatar":""},{"name":"Billy Howle","avatar":""},{"name":"Denis O''Hare","avatar":""},{"name":"Parker Sawyers","avatar":""},{"name":"Joshua Rollins","avatar":""},{"name":"Eliot Sumner","avatar":""},{"name":"Lina Kolenko","avatar":""},{"name":"Karin Putrih","avatar":""},{"name":"Arya Petric","avatar":""},{"name":"Kaja Dolenc","avatar":""},{"name":"Alja Gacnik","avatar":""},{"name":"Brina Merhar","avatar":""},{"name":"Richard Faillace","avatar":""},{"name":"Trisha Arnold","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324309);
