INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-dam-mau', 'Giáng Sinh Đẫm Máu', 'Christmas Bloody Christmas', 'https://phimimg.com/upload/vod/20231116-1/4f6858f25b341b4982f25dce35f29427.jpg', 'https://phimimg.com/upload/vod/20231116-1/2208039ff1ee61c2c0975ecb5d76360d.jpg', '<p>Đó là đêm Giáng sinh và chủ cửa hàng băng đĩa bốc lửa Tori Tooms chỉ muốn say khướt và tiệc tùng, cho đến khi ông già Noel người máy ở một cửa hàng đồ chơi gần đó gặp rắc rối và khiến đêm của cô ấy trở nên phức tạp hơn một chút. Ông già Noel bắt đầu một cuộc giết chóc tràn lan qua khung cảnh tuyết ướt đẫm đèn neon trong bối cảnh ma túy, tình dục, kim loại và bạo lực, cuối cùng buộc Tori phải chiến đấu đẫm máu để sinh tồn chống lại chính kim loại nặng tàn nhẫn Saint Nick.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Riley Dandy","avatar":""},{"name":"Sam Delich","avatar":""},{"name":"Jonah Ray Rodrigues","avatar":""},{"name":"Dora Madison","avatar":""},{"name":"Jeff Daniel Phillips","avatar":""},{"name":"Abraham Benrubi","avatar":""},{"name":"Jeremy Gardner","avatar":""},{"name":"Kansas Bowling","avatar":""},{"name":"Graham Skipper","avatar":""},{"name":"Joe Begos","avatar":""},{"name":"Josh Ethier","avatar":""},{"name":"Matt Mercer","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324309);
