INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-thoat-qua-chau-phi', 'Trốn Thoát Qua Châu Phi', 'Escape Through Africa', 'https://phimimg.com/upload/vod/20231116-1/d71d59233c140993d93d08c99cbab146.jpg', 'https://phimimg.com/upload/vod/20231116-1/ae2d0c8223e16d044e053a5693db9c2c.jpg', '<p>Năm 1914, một y tá người Anh, Anne, thoát khỏi một cuộc tấn công vào tiền đồn của cô ở Châu Phi. Bị săn đuổi bởi một nhóm chiến tranh do Đức lãnh đạo, và với sự giúp đỡ từ chú của cô, một Đại úy quân đội và các chiến binh địa phương, cô bắt đầu một cuộc hành trình hoành tráng qua quốc gia đồi núi châu Phi. Cô phải cân bằng giữa lòng dũng cảm với lý tưởng hòa bình của mình để giải cứu một cô gái bản địa an toàn cho mẹ cô, đoàn tụ với chồng và cứu một tiền đồn lân cận khỏi một vụ thảm sát.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eric Roberts","avatar":""},{"name":"Linn Bjornland","avatar":""},{"name":"Justin Gordon","avatar":""},{"name":"Robert Okumu","avatar":""},{"name":"Jeff Berg","avatar":""},{"name":"Leonard Kelly-Young","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324309);
