INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('battle-freestyle', 'Battle: Freestyle', 'Battle: Freestyle', 'https://phimimg.com/upload/vod/20231117-1/fc59c2b3a99f546441a44162f5b3c0cf.jpg', 'https://phimimg.com/upload/vod/20231117-1/f953c398783e9774f72f834d37ce8c44.jpg', '<p>Amalie vô cùng phấn khích khi nhóm nhảy của cô và Mikael được chọn đi thi đấu ở Paris, nhưng cô lại trở nên phân tâm khi gặp lại người mẹ xa cách từ lâu của mình.</p>', 'Full', 1, 'single', 'completed', 23, 2022, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Lisa Teige","avatar":""},{"name":"Fabian Svegaard Tapia","avatar":""},{"name":"Ellen Dorrit Petersen","avatar":""},{"name":"Morad Aziman","avatar":""},{"name":"Georgia May Anta","avatar":""},{"name":"Bao Andre Nguyen","avatar":""},{"name":"Keiona","avatar":""},{"name":"Léa Djyl","avatar":""},{"name":"Lea Lavabre","avatar":""},{"name":"Adeline Tayoro","avatar":""},{"name":"Ola G. Furuseth","avatar":""},{"name":"Christine Grace Szarkó","avatar":""},{"name":"Philou","avatar":""},{"name":"Salah Benlemqawanssa","avatar":""},{"name":"Sarah Bee","avatar":""},{"name":"Bboy Junior","avatar":""},{"name":"Marti","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324309);
