INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuop-ngan-hang-phi-vu-lich-su-buenos-aires', 'Cướp ngân hàng: Phi vụ lịch sử Buenos Aires', 'Bank Robbers: The Last Great Heist', 'https://phimimg.com/upload/vod/20231117-1/a3947ac444d5dee801bae3a9a4f7fe67.jpg', 'https://phimimg.com/upload/vod/20231117-1/efe97309e548aa3514f16a27de2e5509.jpg', '<p>Qua những cuộc phỏng vấn thẳng thắn, các thủ phạm của vụ trộm ngân hàng khét tiếng nhất Argentina trình bày chi tiết cách thức và lý do bọn họ thực hiện phi vụ năm 2006.</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Argentina', 0, '[{"name":"Fernando Araujo","avatar":""},{"name":"Luis Mario Vitette","avatar":""},{"name":"Sebastián García Bolster","avatar":""},{"name":"Rubén Alberto de la Torre","avatar":""},{"name":"Miguel Ángel Sileo","avatar":""},{"name":"Walter Serrano","avatar":""},{"name":"Estela Maris Casal","avatar":""},{"name":"Leandro Dall Acqua","avatar":""},{"name":"Gastón Garbus","avatar":""},{"name":"Osvaldo Seisdedos","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324309);
