INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuop-ngan-hang-phi-vu-lich-su-buenos-aires', 'Cướp ngân hàng: Phi vụ lịch sử Buenos Aires', 'Bank Robbers: The Last Great Heist', 'cướp ngân hàng: phi vụ lịch sử buenos aires bank robbers: the last great heist fernando araujo luis mario vitette sebastián garcía bolster rubén alberto de la torre miguel ángel sileo walter serrano estela maris casal leandro dall acqua gastón garbus osvaldo seisdedos ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lanh-tho-thu-dich', 'Lãnh Thổ Thù Địch', 'Hostile Territory', 'https://phimimg.com/upload/vod/20231117-1/4067c7ccd4e740dc3e4cd9460a7d8a6c.jpg', 'https://phimimg.com/upload/vod/20231117-1/6bfe5fbe95d31098406a8a088731d90b.jpg', '<p>Lấy cảm hứng từ một câu chuyện có thật, Lãnh địa thù địch là một cuộc phiêu lưu hành động thú vị của phương Tây. Cựu tù binh Jack Calgrove di chuyển &quot;Thiên đường và Trái đất &quot; để đoàn tụ với các con của mình sau Nội chiến. Sau khi trở về nhà, Jack phát hiện ra vợ mình đã chết và những đứa con của anh, được cho là trẻ mồ côi, đang tiến sâu vào miền Tây trên một chuyến tàu băng qua chiến tuyến của kẻ thù cũ. Calgrove và một cựu binh sĩ khác được gia nhập bởi một đội quân bắn cá mập người Mỹ bản địa và một nô lệ được trả tự do, khi họ chạy đua để chặn đoàn tàu mồ côi trước khi tất cả hy vọng bị mất.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brian Presley","avatar":""},{"name":"Matt McCoy","avatar":""},{"name":"Brad Leland","avatar":""},{"name":"Brea Bee","avatar":""},{"name":"Lew Temple","avatar":""},{"name":"Craig Tate","avatar":""},{"name":"Cooper North","avatar":""},{"name":"Natalie Whittle","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324309);
