INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('daeng-hau-due-tinh-nguoi-duyen-ma', 'Daeng: Hậu Duệ "Tình Người Duyên Ma"', 'Daeng Phra Khanong', 'https://phimimg.com/upload/vod/20230919-1/d8c67a18a067e2c69ef22f08754a0f49.jpg', 'https://phimimg.com/upload/vod/20230919-1/993a908a9a9162e013bb6fdcc0501966.jpg', '<p><span style="font-family: ">Một cặp đôi đại học xui xẻo vô tình trở thành hiện tượng đình đám trên mạng sau một lần cãi vã. Giờ họ phải tìm hiểu tình cảm của mình – khi cả thế giới đang theo dõi.</span></p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Petchtai Wongkamlao","avatar":""},{"name":"Melix Efe Aygun","avatar":""},{"name":"Machida Sutthikulphanich","avatar":""},{"name":"Phuwarak Khamsing","avatar":""},{"name":"Mboke Medad Epie","avatar":""},{"name":"Surachai Borsuwan","avatar":""},{"name":"Tanapatch Chantasorn","avatar":""},{"name":"Chookiat Iamsook","avatar":""},{"name":"Suthep Sisai","avatar":""},{"name":"Apaporn Nakornsawan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324309);
