INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('daeng-hau-due-tinh-nguoi-duyen-ma', 'Daeng: Hậu Duệ "Tình Người Duyên Ma"', 'Daeng Phra Khanong', 'daeng: hậu duệ "tình người duyên ma" daeng phra khanong petchtai wongkamlao melix efe aygun machida sutthikulphanich phuwarak khamsing mboke medad epie surachai borsuwan tanapatch chantasorn chookiat iamsook suthep sisai apaporn nakornsawan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-ho-nguy-thanh', 'Cuồng Hổ Nguy Thành', 'Mutant Tiger', 'https://phimimg.com/upload/vod/20231116-1/ab7f9a9d067fcfdfd25e91353a9bcc1f.jpg', 'https://phimimg.com/upload/vod/20231116-1/89e2dd369d6ac7b4d8bcab90b586c4ae.jpg', '<p>Ming Jiajing trong 37 năm, quyền của thái tử đã thay đổi đối lập. Cho nên Đông xưởng ở nơi hung hổ xuất hiện - tây nam biên giới nhỏ thành lập &quot;Sư lễ săn trường&quot;, săn hung hổ dùng để luyện hóa. Nhưng không ngờ, động thái này làm cho virus kỳ lạ xâm nhập vào cơ thể hổ, khiến hổ phát điên và hình thành dịch hạch nhanh chóng lan truyền. …… Vào thời điểm này, Zhang Liucheng, một gia đình của Jin Yi Wei bị sa thải, đã mang theo đứa trẻ mồ côi bị gia đình Dongchang tiêu diệt vì đã tố cáo vụ việc, đến nơi này để tìm Zhang Lưuping, em trai của người săn mồi, người đã được tuyển vào khu săn bắn Sili. Nhưng không ngờ bị tấn công bởi những con hổ biến dị. Nhưng khủng hoảng chỉ là bắt đầu, rất nhanh, dịch bệnh làm cho hổ nhanh chóng tập hợp gần trăm con, đem thị trấn thành phố đoàn vây quanh, một thời gian trấn dân liên tiếp bị mãnh hổ giết chóc, toàn thành nguy hiểm ở trong nguy hiểm! Trương Liễu Thành đứng lên ra, chuẩn bị dẫn dắt Hoan Nhi cùng dân chúng trong trấn trốn sinh thiên, nhưng hắn không biết chính là, “Sân săn” trong còn có bí mật kinh thiên hung dữ hơn dã thú. ……</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tse Miu","avatar":""},{"name":"Hong Jianing","avatar":""},{"name":"Jing Yanqiao","avatar":""},{"name":"Xiang Hao","avatar":""},{"name":"Shi Zichen","avatar":""},{"name":"Zhang Haosen","avatar":""},{"name":"Wang Yukai","avatar":""},{"name":"Yu Jinpu","avatar":""},{"name":"Jin Qingling","avatar":""},{"name":"Hou Meng","avatar":""},{"name":"Wei Jinsong","avatar":""},{"name":"Ming Xiaoxi","avatar":""},{"name":"Yu Qinghui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324309);
