INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong', 'Ác Mộng', 'The Free Fall', 'https://phimimg.com/upload/vod/20231116-1/56d233d73747d5ca1a2064e8268c783c.jpg', 'https://phimimg.com/upload/vod/20231116-1/32775a46a90bad822829cb96800014e9.jpg', '<p>Sau khi cố gắng đưa cuộc sống của riêng mình, một phụ nữ trẻ phải vật lộn với một người chồng hống hách.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andrea Londo","avatar":""},{"name":"Shawn Ashmore","avatar":""},{"name":"Jane Badler","avatar":""},{"name":"Michael Berry Jr.","avatar":""},{"name":"Elizabeth Cappuccino","avatar":""},{"name":"Dominic Hoffman","avatar":""},{"name":"Lorenzo Antonucci","avatar":""},{"name":"Marc Senter","avatar":""},{"name":"Nathaniel Peterson","avatar":""},{"name":"Madeleine Coghlan","avatar":""},{"name":"Diane Ayala Goldner","avatar":""},{"name":"Jackie Dallas","avatar":""},{"name":"Samuel Davis","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324309);
