INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-yeu-quat-sinh-hoai-nam', 'Thầm Yêu Quất Sinh Hoài Nam', 'My Blue Summer', 'https://phimimg.com/upload/vod/20231116-1/6534eaa4fa64137a40cdfd064aa22b3e.jpg', 'https://phimimg.com/upload/vod/20231116-1/182475f9b3b0039e45bd71283d3ec265.jpg', '<p>Thịnh Hoài Nam, cái tên này đã khắc sâu vào lòng Lạc Chỉ. Gặp lại ở trung học, Thịnh Hoài Nam như một đường ánh sáng, khiến Lạc Chỉ không thể không ngước mắt nhìn theo, cũng khiến cho tâm tư thiếu nữ của Lạc Chỉ không thể che giấu. Trên sân thượng khắc &quot;Lạc Chỉ yêu Thịnh Hoài Nam, không ai hay biết&quot; chính là tuyên ngôn yêu thầm của Lạc Chỉ không thể nói ra. Sau khi vào đại học, Lạc Chỉ tràn đầy mong đợi cuộc sống mới, lại phát hiện Thịnh Hoài Nam học cùng một trường, Hai người dần dần quen biết, càng ngày càng gần, nhưng cũng không dám bày tỏ nỗi lòng. Khi áp lực của trưởng thành và hiện thực cùng nhau kéo đến, mối tình yêu thầm lâu dài này, rốt cuộc phải làm sao mới yên ổn?</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sophie Zhang","avatar":""},{"name":"Yunlai Xin","avatar":""},{"name":"Jackie Li","avatar":""},{"name":"刘琳","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324309);
