INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-cung', 'Đường cùng', 'End of the Road', 'https://phimimg.com/upload/vod/20231116-1/77a6cc4393ddab8d63e51d3a7e90e289.jpg', 'https://phimimg.com/upload/vod/20231116-1/8c1d6a543d1cbe36718de61d79c8e783.jpg', '<p>Là mẹ và mới mất chồng, Brenda chiến đấu để bảo vệ gia đình mình trong chuyến phượt kinh hoàng khi một vụ án mạng và một túi tiền mất tích đẩy họ vào vòng nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Queen Latifah","avatar":""},{"name":"Ludacris","avatar":""},{"name":"Mychala Lee","avatar":""},{"name":"Shaun Dixon","avatar":""},{"name":"Beau Bridges","avatar":""},{"name":"Frances Lee McCain","avatar":""},{"name":"Keith Jardine","avatar":""},{"name":"Jesse Luken","avatar":""},{"name":"Tabatha Shaun","avatar":""},{"name":"Micah McNeil","avatar":""},{"name":"Jasper Keen","avatar":""},{"name":"Aaron Valentine","avatar":""},{"name":"Will C. Vogel","avatar":""},{"name":"James Blackburn","avatar":""},{"name":"James Moontasri","avatar":""},{"name":"Tim Stafford","avatar":""},{"name":"John C Pond","avatar":""},{"name":"Ruben B","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324309);
