INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('teen-titans-go-cac-nu-sieu-anh-hung-dc-mayhem-trong-da-vu-tru', 'Teen Titans Go! & Các nữ siêu anh hùng DC: Mayhem trong Đa vũ trụ', 'Teen Titans Go! & DC Super Hero Girls: Mayhem in the Multiverse', 'https://phimimg.com/upload/vod/20231115-1/553f83255a1c091febf590716c579c9a.jpg', 'https://phimimg.com/upload/vod/20231115-1/9321363d34f5efbf9d770730ce249470.jpg', '<p>Với sự giúp đỡ của sức mạnh Kryptonian cổ đại, Lex Luthor hợp nhất các Siêu nhân vật phản diện trên thế giới để bắt tất cả các Siêu anh hùng của Trái đất, cho đến khi… chỉ còn lại các Cô gái Siêu anh hùng DC để ngăn chặn Legion of Doom. Các anh hùng của chúng ta phải vượt qua các chiều không gian để giải cứu các Siêu anh hùng đồng nghiệp của họ khỏi Phantom Zone, nhưng một ngã rẽ tình cờ đã đưa họ đến Tháp Titans - nơi họ tìm thấy những đồng minh rất cần thiết trong Teen Titans. Các Siêu anh hùng trẻ tuổi khám phá ra sức mạnh tổng hợp của họ - và sự nhẹ nhõm thông thường trong truyện tranh - là điều cần thiết để cứu lấy một ngày trong sự kiện bom tấn này!</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tara Strong","avatar":""},{"name":"Greg Cipes","avatar":""},{"name":"Scott Menville","avatar":""},{"name":"Khary Payton","avatar":""},{"name":"Hynden Walch","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Kimberly Brooks","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Myrna Velasco","avatar":""},{"name":"Keith Ferguson","avatar":""},{"name":"Will Friedle","avatar":""},{"name":"Phil LaMarr","avatar":""},{"name":"Jessica McKenna","avatar":""},{"name":"Alexander Polinsky","avatar":""},{"name":"Missi Pyle","avatar":""},{"name":"Nicole Sullivan","avatar":""},{"name":"Cree Summer","avatar":""},{"name":"Fre","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324309);
