INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-vat-huyen-bi-lich-su-tu-nhien', 'Sinh Vật Huyền Bí: Lịch Sử Tự Nhiên', 'Fantastic Beasts: A Natural History', 'https://phimimg.com/upload/vod/20231113-1/db6cb1719cbf8ba07155bddac47cae98.jpg', 'https://phimimg.com/upload/vod/20231113-1/cef7d0b61d22f2bfa3b11d875a1d3032.jpg', '<p>Stephen Fry bắt đầu một cuộc hành trình để khám phá những câu chuyện đằng sau một số loài quái thú tuyệt vời nhất trên thế giới đã truyền cảm hứng cho các huyền thoại và truyền thuyết trong lịch sử, kể chuyện và phim.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Stephen Fry","avatar":""},{"name":"J.K. Rowling","avatar":""},{"name":"Christian Manz","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324309);
