INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-cu-cua-romeo', 'Người Yêu Cũ Của Romeo', 'Rosaline', 'https://phimimg.com/upload/vod/20231113-1/73e14bf5ec4862be46c720ccaf456f85.jpg', 'https://phimimg.com/upload/vod/20231113-1/73ffc3c714513404ddb6eab91f5d894b.jpg', '<p>&quot;Rosaline&quot; là một sự thay đổi hài hước của &quot;Romeo và Juliet&quot; của Shakespeare, trong đó câu chuyện tình yêu kinh điển được kể từ góc nhìn của Rosaline, em họ của Juliet (Kaitlyn Dever), người vừa mới đây là bạn gái cũ của Romeo. Bị nghiền nát khi Romeo (Kyle Allen) vứt bỏ cô sau khi gặp Juliet (Isabela Merced), Rosaline sắc sảo nhưng đầy lý tưởng lên kế hoạch phá bỏ mối tình lãng mạn nổi tiếng và giành lại chàng trai của cô.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kaitlyn Dever","avatar":""},{"name":"Isabela Merced","avatar":""},{"name":"Kyle Allen","avatar":""},{"name":"Sean Teale","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Minnie Driver","avatar":""},{"name":"Bradley Whitford","avatar":""},{"name":"Spencer Rayshon Stevenson","avatar":""},{"name":"Nico Hiraga","avatar":""},{"name":"Alistair Toovey","avatar":""},{"name":"Alhaji Fofana","avatar":""},{"name":"Mercedes Colon","avatar":""},{"name":"Nicholas Rowe","avatar":""},{"name":"Valentina Carnelutti","avatar":""},{"name":"Lew Temple","avatar":""},{"name":"Henry Hu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324309);
