INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-cua-hon-dao', 'Linh Hồn Của Hòn Đảo', 'The Banshees of Inisherin', 'https://phimimg.com/upload/vod/20231114-1/8a01a88e2a06590bdaecaa160c158220.jpg', 'https://phimimg.com/upload/vod/20231114-1/32d39404021218b43578da62c2336729.jpg', '<p>Lấy bối cảnh trên một hòn đảo xa xôi ngoài khơi bờ biển phía tây Ireland,bộ phim theo chân những người bạn lâu năm là Pádraic và Colm, họ cảm thấy bế tắc khi Colm bất ngờ chấm dứt tình bạn của họ. Pádraic choáng váng, được sự giúp đỡ của chị gái Siobhán và người dân đảo trẻ tuổi đang gặp rắc rối Dominic, nỗ lực hàn gắn mối quan hệ, từ chối chấp nhận câu trả lời là không. Nhưng những nỗ lực lặp đi lặp lại của Pádraic chỉ củng cố quyết tâm của người bạn cũ và khi Colm đưa ra một tối hậu thư tuyệt vọng, các sự kiện nhanh chóng leo thang, kéo theo những hậu quả kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Kerry Condon","avatar":""},{"name":"Barry Keoghan","avatar":""},{"name":"Gary Lydon","avatar":""},{"name":"Pat Shortt","avatar":""},{"name":"Jon Kenny","avatar":""},{"name":"Sheila Flitton","avatar":""},{"name":"David Pearse","avatar":""},{"name":"Bríd Ní Neachtain","avatar":""},{"name":"Aaron Monaghan","avatar":""},{"name":"Lasairfhíona Ní Chonaola","avatar":""},{"name":"James Carty","avatar":""},{"name":"Conor Connolly","avatar":""},{"name":"Ryan Owens","avatar":""},{"name":"John Carty","avatar":""},{"name":"Oliver Farrelly","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324309);
