INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-quai-toan-thu', 'Yêu Quái Toàn Thư', 'Ghost Book', 'https://phimimg.com/upload/vod/20231114-1/2199df50f604a8d2869db5588335a8d4.jpg', 'https://phimimg.com/upload/vod/20231114-1/fe8c99791d5985c7720aa04a96318cc3.jpg', '<p>Cuốn sách cấm &quot;The Haunted Book&quot; có thể biến bất kỳ điều ước nào thành hiện thực, nhưng để biến điều ước thành hiện thực thì bạn phải trải qua một thử thách nguy hiểm đến tính mạng. Thử thách là gì ...!?</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ryunosuke Kamiki","avatar":""},{"name":"Kairi Jo","avatar":""},{"name":"Yui Aragaki","avatar":""},{"name":"Fuga Shibazaki","avatar":""},{"name":"Sonny Mcclendon","avatar":""},{"name":"Fumika Yoshimura","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Min Tanaka","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Hiro Shimono","avatar":""},{"name":"Rie Kugimiya","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324309);
