INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-immaculate-room', 'The Immaculate Room', 'The Immaculate Room', 'https://phimimg.com/upload/vod/20231115-1/a1a18d72550d95ca50c4777ff632f350.jpg', 'https://phimimg.com/upload/vod/20231115-1/979b615496005a29420592fa1bad1ff5.jpg', '<p>Mike và Kate, một cặp vợ chồng trẻ, có cơ hội một lần trong đời để giành được năm triệu đô la hấp dẫn. Thử thách: Sống 50 ngày trong một không gian trống. Gắn bó với nó trong ba mươi ngày, và năm triệu là của họ. no kho đên mưc nao?</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Bosworth","avatar":""},{"name":"Emile Hirsch","avatar":""},{"name":"Ashley Greene","avatar":""},{"name":"M. Emmet Walsh","avatar":""},{"name":"Alex Sgambati","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324309);
