INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-wife', 'The Wife', 'The Wife', 'https://phimimg.com/upload/vod/20231115-1/0f17fdb21c83df669779878ad7f7d7e0.jpg', 'https://phimimg.com/upload/vod/20231115-1/40ab6d384c95969062641bbfc069fb36.jpg', '<p>Cuộc hôn nhân của cặp đôi tan vỡ vì bị chồng lừa dối. Người vợ làm sao có thể chấp nhận lời cầu xin hấp hối của chồng để được ở bên mình và tình nhân trong những ngày còn lại của cuộc đời?</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Diego Loyzaga","avatar":""},{"name":"Cara Gonzales","avatar":""},{"name":"Louise delos Reyes","avatar":""},{"name":"Debbie Garcia","avatar":""},{"name":"Mayton Eugenio","avatar":""},{"name":"Jean Kiley Manguera","avatar":""},{"name":"Lander Vera-Perez","avatar":""},{"name":"Rafa Siguion-Reyna","avatar":""},{"name":"Juvz Tesalona","avatar":""},{"name":"Diony Abarra Sison","avatar":""},{"name":"Ashley Capoquian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324309);
