INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-linh-trung-coc', 'Long Lĩnh Trùng Cốc', 'Longling insect Valley', 'https://phimimg.com/upload/vod/20231115-1/883a1f82ed9209d71cf7cd7998c9449a.jpg', 'https://phimimg.com/upload/vod/20231115-1/5e00cee3d3338135f6a20651001b3028.jpg', '<p>Một giáo sư sinh học điên, một người giàu mắc bệnh nan y, một nhà thám hiểm đang tìm kiếm người thân mất tích, một kẻ chỉ nhìn thấy tiền là mắt sáng lên... Một nhóm người với những mục đích khác nhau đã thành lập một đội thám hiểm đi đến cốc côn trùng ở phía Tây Nam, tìm kiếm những ngôi mộ cổ hàng nghìn năm và côn trùng chúa trong truyền thuyết. Đối mặt với rắn độc và bọ cạp, chất gây ảo giác quỷ diệu, côn trùng chúa to lớn và hung dữ..., nhóm thám hiểm đã trải qua nhiều cung bậc cảm xúc trong ngôi mộ cổ, và trải qua cuộc xuyên không đối đầu sinh tử với nền văn minh bí ẩn đã mất của cổ đại. Câu đố do Điền Vương đặt ra, khiến các nhà thám hiểm phải chiến đấu qua lại giữa bản chất và dục vọng của con người, và cuộc chiến bí ẩn của cốc côn trùng đã diễn ra...</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ma Jianxun","avatar":""},{"name":"Fu Xuerui","avatar":""},{"name":"Zhou Yi","avatar":""},{"name":"Wu Kegang","avatar":""},{"name":"Li Xiaopeng","avatar":""},{"name":"Sui Dalong","avatar":""},{"name":"Zhang Yijun","avatar":""},{"name":"Rong Shao","avatar":""},{"name":"Qiu Yinping","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324309);
