INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-duoi', 'Truy đuổi', 'Pursuit', 'https://phimimg.com/upload/vod/20231115-1/4daa4dc0fbe65f30412abc9b88d99c29.jpg', 'https://phimimg.com/upload/vod/20231115-1/cf1253f6b11ded4e656935206aeac95a.jpg', '<p>Thám tử Breslin vượt qua con đường với Calloway, một tin tặc tàn nhẫn tuyệt vọng để tìm vợ của mình, người đã bị bắt cóc bởi một tập đoàn ma túy. Khi Calloway thoát khỏi sự giam giữ của cảnh sát, Breslin gia nhập lực lượng với một nữ cảnh sát ngoại hình để đòi lại tù nhân của anh ta. Nhưng liệu cha của trùm tội phạm Calloway bằng cách nào đó có liên quan đến tình huống bùng nổ này?</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Emile Hirsch","avatar":""},{"name":"John Cusack","avatar":""},{"name":"Jake Manley","avatar":""},{"name":"Elizabeth Faith Ludlow","avatar":""},{"name":"Graham Patrick Martin","avatar":""},{"name":"Heather Marie Marsden","avatar":""},{"name":"Chris Jai Alex","avatar":""},{"name":"Aubrey Stevens","avatar":""},{"name":"Barry Hanley","avatar":""},{"name":"Nick Benseman","avatar":""},{"name":"Shelby Yardley","avatar":""},{"name":"James Logan","avatar":""},{"name":"William Katt","avatar":""},{"name":"Brittany Belt","avatar":""},{"name":"Andrew Stevens","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324309);
