INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-co-luc-thien-quan-hi-phap-do', 'Vân Cơ Lục: Thiên Quan Hí Pháp Đồ', 'Mystery Magic Figure', 'null', 'https://phimimg.com/upload/vod/20231125-1/57fd20131e0bc4ada7510de617d480c7.jpg', '<p>Ba gia tộc chính ở Tân Môn là Đường môn, Lí gia và Tư gia. Đường Môn có tốc độ tay tốt, sở trường trong các thủ pháp tận cảnh và thủ pháp che mắt . Lí gia giỏi trong đạo cụ và các cơ quan. Tư gia lại rất giỏi trong việc giải mã các loại ma thuật, và đã sáng tạo ra thuật tương nhân. Trong cuộc họp thường niên của Tân Môn, chiếc áo khoác lụa vàng bị mất tích khiến đám đông đứng ngồi không yên. Ba gia tộc hợp sức chống lại các thuật sĩ ngoại bang để lấy lại chiếc áo lụa vàng.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Ziyou","avatar":""},{"name":"Zhu Moyan","avatar":""},{"name":"Shao Shuai","avatar":""},{"name":"Hou Yaohua","avatar":""},{"name":"Liu Jin","avatar":""},{"name":"Guan Zeqiang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324309);
