INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-trong-mo-cua-georgie-stone', 'Cuộc sống trong mơ của Georgie Stone', 'The Dreamlife of Georgie Stone', 'https://phimimg.com/upload/vod/20231113-1/ee9b33bb2d1148d96e034547b182f8fb.jpg', 'https://phimimg.com/upload/vod/20231113-1/eb1e9f8d4189acf5198a59bfdb06c96f.jpg', '<p>Phim tài liệu về hành trình từ nhỏ đến khi là nhà hoạt động tuổi teen của Georgie Stone khi cô nhìn lại đời mình và cuộc đấu tranh lịch sử vì quyền của người chuyển giới.</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Georgie Stone","avatar":""},{"name":"Rebekah Robertson","avatar":""},{"name":"Greg Stone","avatar":""},{"name":"Harry Stone","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324309);
