INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-cat-toc', 'Vua Cắt Tóc', 'Kung Fu Hairdresser', 'https://phimimg.com/upload/vod/20231113-1/c1403e1ba982744e0039c1c8a368b98c.jpg', 'https://phimimg.com/upload/vod/20231113-1/e602e06276dd7a84a4008287a5c77311.jpg', '<p>Thợ cắt tóc trẻ Lí Trọng Quang rời quê hương để theo đuổi &quot;nghệ thuật cắt tóc&quot;. Anh học hỏi từ những người có kinh nghiệm và chăm chỉ nghiên cứu. Sau khi trải qua những xung đột của quan niệm truyền thống và hiện đại, kỹ năng truyền thống và công nghệ hiện đại, cuối cùng anh ấy đã tìm thấy phương pháp của riêng mình, tích hợp các kỹ năng thủ công truyền thống và công nghệ mới, tìm ra “nghệ thuật cắt tóc” của riêng mình.</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Qing","avatar":""},{"name":"Yang Jinci","avatar":""},{"name":"Ye Tian","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324309);
