INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('weird-the-al-yankovic-story', 'Weird: The Al Yankovic Story', 'Weird: The Al Yankovic Story', 'https://phimimg.com/upload/vod/20231113-1/5d09b15f4b658dc99b4f4cf91fefb98f.jpg', 'https://phimimg.com/upload/vod/20231113-1/98ae87b115f44d97339901e522fe1a16.jpg', '<p>Khám phá mọi khía cạnh trong cuộc đời của &#39;Weird Al&#39; Yankovic, từ sự nổi tiếng nhanh chóng của anh ấy với những bản hit đầu tiên như &#39;Eat It&#39; và &#39;Like a Surgeon&#39; cho đến những cuộc tình nóng bỏng của người nổi tiếng và lối sống sa đọa nổi tiếng của anh ấy, bộ phim tiểu sử này đưa khán giả vào một câu chuyện thực sự khó tin. hành trình xuyên suốt cuộc đời và sự nghiệp của Yankovic, từ một thần đồng tài năng đến huyền thoại âm nhạc vĩ đại nhất mọi thời đại.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Evan Rachel Wood","avatar":""},{"name":"Rainn Wilson","avatar":""},{"name":"Toby Huss","avatar":""},{"name":"Jack Lancaster","avatar":""},{"name":"Spencer Treat Clark","avatar":""},{"name":"Tommy O''Brien","avatar":""},{"name":"Arturo Castro","avatar":""},{"name":"Julianne Nicholson","avatar":""},{"name":"Diedrich Bader","avatar":""},{"name":"Lin-Manuel Miranda","avatar":""},{"name":"Richard Aaron Anderson","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"David Bloom","avatar":""},{"name":"Keanush Tafres","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324309);
