INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-dau', 'Cắm Đầu', 'Dive (La caída)', 'https://phimimg.com/upload/vod/20231112-1/6d0626f00248295e47bc799bd1903927.jpg', 'https://phimimg.com/upload/vod/20231112-1/9e653f07029627b1c4d90f89a3deea7a.jpg', '<p>Mariel là một thợ lặn ưu tú kỳ cựu, người có một cơ hội cuối cùng tại Thế vận hội Olympic. Tuy nhiên, khi một sự thật khủng khiếp được đưa ra ánh sáng, Mariel phải đối mặt với câu hỏi cá nhân lớn nhất của mình: Có phải giấc mơ thực sự của cô là chiến thắng?</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Karla Souza","avatar":""},{"name":"Hernán Mendoza","avatar":""},{"name":"Dèja Ebergenyi","avatar":""},{"name":"Christian Vázquez","avatar":""},{"name":"Mabel Cadena","avatar":""},{"name":"Fernanda Borches","avatar":""},{"name":"Claudia Lobo","avatar":""},{"name":"Enrique Singer","avatar":""},{"name":"Amalia Rangel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324309);
