INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-trang-phieu-dat', 'Ánh Trăng Phiêu Dạt', 'Wandering', 'https://phimimg.com/upload/vod/20231112-1/a6aedf6c2e6534940739a3db7b5545dd.jpg', 'https://phimimg.com/upload/vod/20231112-1/9988b630876029ad702cd47637f82f02.jpg', '<p>Vào một buổi tối mưa, sinh viên đại học 19 tuổi Saeki Fumi tình cờ gặp cô bé 9 tuổi Kanai Sarasa đang ướt sũng trong công viên. Cô bé bị tách khỏi cha mẹ và sống với dì của mình, nhưng cô bé nói với Fumi rằng mình không muốn quay lại sống tiếp với bà ấy. Nhận thấy cô bé không muốn về nhà, Fumi quyết định đưa cô bé về chỗ của mình và họ sống cùng nhau. Hai tháng sau, Fumi bị bắt vì tội bắt cóc. Anh ấy bị coi là kẻ bắt cóc nguy hiểm và Sarasa được coi là nạn nhân đáng thương. 15 năm sau, Sarasa và Fumi tình cờ gặp lại nhau......</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Suzu Hirose","avatar":""},{"name":"Tori Matsuzaka","avatar":""},{"name":"Ryusei Yokohama","avatar":""},{"name":"Mikako Tabe","avatar":""},{"name":"Shuri","avatar":""},{"name":"Takahiro Miura","avatar":""},{"name":"Tamaki Shiratori","avatar":""},{"name":"Yayako Uchida","avatar":""},{"name":"Akira Emoto","avatar":""},{"name":"Mio Masuda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324309);
