INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('three-months', 'Three Months', 'Three Months', 'https://phimimg.com/upload/vod/20231111-1/9a8ef1637b1e80a64614b58faf44f89d.jpg', 'https://phimimg.com/upload/vod/20231111-1/75ec73dc976e89cdf9d1bcc02952789d.jpg', '<p>Caleb, một thiếu niên Nam Florida, yêu máy ảnh của mình, cỏ dại và bà của anh ta. Vào đêm trước khi tốt nghiệp trung học, mọi thứ thay đổi khi anh ta tiếp xúc với HIV. Trong khi anh ta đợi ba tháng cho kết quả của mình, Caleb tìm thấy tình yêu ở những nơi khó xảy ra nhất.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Troye Sivan","avatar":""},{"name":"Viveik Kalra","avatar":""},{"name":"Brianne Tju","avatar":""},{"name":"Amy Landecker","avatar":""},{"name":"Javier Muñoz","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Louis Gossett Jr.","avatar":""},{"name":"Ellen Burstyn","avatar":""},{"name":"Steven Sean Garland","avatar":""},{"name":"Scott Johnson","avatar":""},{"name":"Martina Meneses","avatar":""},{"name":"Jacinte Blankenship","avatar":""},{"name":"Carlos Guerrero","avatar":""},{"name":"Aaron Nedrick","avatar":""},{"name":"Kaleka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324309);
