INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meo-hoang', 'Mèo Hoang', 'Wildcat', 'https://phimimg.com/upload/vod/20230917-1/3a82a9dd973856b10ac33359deda76d7.webp', 'https://phimimg.com/upload/vod/20230917-1/c4ccc809e88c753c2cd0d564e5edaed9.jpg', '<p>Trở về sau cuộc chiến ở Afghanistan, một người lính trẻ người Anh đang vật lộn với chứng trầm cảm và PTSD tìm thấy cơ hội thứ hai trong rừng nhiệt đới Amazon khi anh gặp một nhà khoa học người Mỹ và họ cùng nhau nuôi dưỡng một bé bạch dương mồ côi.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Dante Cueva Altamirano","avatar":""},{"name":"Cristian De La Cruz","avatar":""},{"name":"Erick Scott Vargas Laura","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324309);
