INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chip-va-dale-biet-doi-giai-cuu', 'Chip và Dale: Biệt Đội Giải Cứu', 'Chip''n Dale: Rescue Rangers', 'https://phimimg.com/upload/vod/20231111-1/d8a9dd30b57d57e0c67c8c27b9a0fe61.jpg', 'https://phimimg.com/upload/vod/20231111-1/b7a973bf789d0cde7ed2d665f39fb368.jpg', '<p>Chip và Dale trở lại sau 30 năm kể từ khi Rescue Rangers (tập phim đầu tiên ra mắt), trong một thế giới nơi con người và các nhân vật hoạt hình sinh sống cùng nhau. Ở đó các nhân vật hoạt hình truyền thống đang phải vật lộn để tồn tại khi việc tái khởi động với đồ họa máy tính đang trở thành một xu hướng tất yếu. Cùng lúc đó, Chip và Dale phải nối lại quan hệ đối tác để cứu một người bạn khỏi nạn vi phạm bản quyền video</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andy Samberg","avatar":""},{"name":"John Mulaney","avatar":""},{"name":"KiKi Layne","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Eric Bana","avatar":""},{"name":"Flula Borg","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Tress MacNeille","avatar":""},{"name":"Tim Robinson","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Da''Vone McDonald","avatar":""},{"name":"Akiva Schaffer","avatar":""},{"name":"Rachel Bloom","avatar":""},{"name":"Juliet Donenfeld","avatar":""},{"name":"Liz Cackowski","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn"