INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-chau-thanh-hanh-ki', 'Cửu Châu Thanh Hạnh Kỉ', 'Novoland - Floating Heart', 'null', 'https://phimimg.com/upload/vod/20231111-1/f267b531d1f2e9052f52a8a53be6d371.jpg', '<p>Trong thời Cửu Châu hồn loạn, Nam Tinh xinh đẹp con gái của Thái sư chết thảm trong phòng vào ngày hôn lễ một hôm, điều này chấn động nhiều người và thu hút sự điều tra của các gia tộc khác nhau. La Lợi tình cờ gặp được Nam Tinh sống lại một cách kì lạ , được bí mật đưa vào một hang động và rơi vào những âm mưu lớn hơn.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ashin Shu","avatar":""},{"name":"Shi Xuejing","avatar":""},{"name":"Zhao Yijie","avatar":""},{"name":"Wang Meixin","avatar":""},{"name":"Han Mengwu","avatar":""},{"name":"Su Mao","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324309);
