INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ve-shiva', 'Câu chuyện về Shiva', 'Brahmāstra Part One: Shiva', 'https://phimimg.com/upload/vod/20231111-1/36f21ae5b24495a69a0317913f5d31cf.jpg', 'https://phimimg.com/upload/vod/20231111-1/f607335da9a2adfd9220948779c65c8f.jpg', '<p>Câu chuyện về Shiva – một chàng trai trẻ đang trên bờ vực của một tình yêu sử thi, với một cô gái tên là Isha. Nhưng thế giới của họ bị đảo lộn khi Shiva biết rằng anh ta có mối liên hệ bí ẩn với Brahmāstra... và một sức mạnh to lớn bên trong anh ta mà anh ta vẫn chưa hiểu - sức mạnh của Lửa.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Ranbir Kapoor","avatar":""},{"name":"Alia Bhatt","avatar":""},{"name":"Mouni Roy","avatar":""},{"name":"Amitabh Bachchan","avatar":""},{"name":"Nagarjuna Akkineni","avatar":""},{"name":"Shah Rukh Khan","avatar":""},{"name":"Dimple Kapadia","avatar":""},{"name":"Saurav Gurjar","avatar":""},{"name":"Rounallah Gazi","avatar":""},{"name":"Gurfateh Pirzada","avatar":""},{"name":"Stanzin Delek","avatar":""},{"name":"Lehar Khan","avatar":""},{"name":"Aditi Joshi","avatar":""},{"name":"Markand Soni","avatar":""},{"name":"Chaitanya Sharma","avatar":""},{"name":"Saqib Ayub","avatar":""},{"name":"Rashi Mal","avatar":""},{"name":"Roh","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324309);
