INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-di-dang-nho', 'Chuyến Đi Đáng Nhớ', 'Ajoomma', 'https://phimimg.com/upload/vod/20231111-1/e3d81d5777f5459c59cb5e493bd64855.jpg', 'https://phimimg.com/upload/vod/20231111-1/47c3117d4600b50bc9141f6914489402.jpg', '<p>Một bà cô người Singapore ghiền phim truyền hình Hàn Quốc đã tự du lịch đến Seoul để rồi bị lạc khỏi đoàn. Cuộc hành trình của cô trở thành thử thách tìm ra mục đích sống của một người phụ nữ lớn tuổi phương Đông, rời xa khỏi trách nhiệm của một người con, người vợ và người mẹ</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'HD', 'Singapore', 0, '[{"name":"Hong Huifang","avatar":""},{"name":"Kang Hyung-suk","avatar":""},{"name":"Jung Dong-hwan","avatar":""},{"name":"Shane Pow","avatar":""},{"name":"Yeo Jin-goo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324310);
