INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thap-tu-sat-duong-den-normandy', 'Thập Tự Sắt: Đường Đến Normandy', 'Iron Cross: The Road to Normandy', 'https://phimimg.com/upload/vod/20231111-1/ed113d6daa4dc9a368915677e3240b15.jpg', 'https://phimimg.com/upload/vod/20231111-1/a9061f3b3ee3cab59a8b4ed199ce9c3d.jpg', '<p>Thuyền trưởng Muller đấu tranh để tồn tại khi chiến đấu với lực lượng áp đảo của Nga. Bị thương, anh ta được gửi đến Normandy Khi người Mỹ của chúng tôi Lee và Trey đang chuẩn bị cho ngày D. Điểm số sớm được giải quyết và trận chiến đưa GIs và người Đức của chúng ta vào cùng một con đường.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tino Struckmann","avatar":""},{"name":"Olivier Gruner","avatar":""},{"name":"Kim Sønderholm","avatar":""},{"name":"Damian Chapa","avatar":""},{"name":"Jack Dimich","avatar":""},{"name":"Thomas Raft","avatar":""},{"name":"Tori London","avatar":""},{"name":"Caspar von Winterfeldt","avatar":""},{"name":"Birk Mogenson","avatar":""},{"name":"Steve Effler","avatar":""},{"name":"Elvin Manges","avatar":""},{"name":"Lee Tingey","avatar":""},{"name":"Trey Hough","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324310);
