INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-truoc-giang-sinh', 'Giao trước Giáng sinh', 'Delivery by Christmas', 'https://phimimg.com/upload/vod/20231111-1/56c8dd97c07da18cc8453ff1a5b3f4b3.jpg', 'https://phimimg.com/upload/vod/20231111-1/335ed1557c47db35a6bb72059cfe8e13.jpg', '<p>Khi một đồng nghiệp hằn học phá hoại các chuyến giao hàng của cô, một người chuyển phát nhanh và một khách hàng tốt bụng phải gấp rút trả lại quà Giáng sinh cho người nhận dự kiến.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Monika Frajczyk","avatar":""},{"name":"Piotr Pacek","avatar":""},{"name":"Franciszek Krupowicz","avatar":""},{"name":"Barbara Jonak","avatar":""},{"name":"Łukasz Simlat","avatar":""},{"name":"Łukasz Gawroński","avatar":""},{"name":"Dorota Kolak","avatar":""},{"name":"Mirosław Baka","avatar":""},{"name":"Marek Kalita","avatar":""},{"name":"Zdzisław Wardejn","avatar":""},{"name":"Zuzanna Puławska","avatar":""},{"name":"Radosław Rożniecki","avatar":""},{"name":"Tomasz Schuchardt","avatar":""},{"name":"Agnieszka Roszkowska","avatar":""},{"name":"Maria Maj","avatar":""},{"name":"Małg","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324310);
