INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-dam-hac-thach-linh', 'Quái Đàm Hắc Thạch Linh', 'Strange Talk about Heishiling', 'null', 'https://phimimg.com/upload/vod/20231111-1/7b0e21087b99698c264031f5a8a63cca.jpg', '<p>Câu chuyện xảy ra ở một nơi tên là Hắc Thạch Lĩnh trong thời kỳ Trung Hoa Dân Quốc. Chiến tranh thường xuyên khiến người dân khốn khổ, và các thế lực và vị thần kỳ lạ thường xuyên xuất hiện. Có một câu nói rằng Sơn Thần Hắc Thạch Lĩnh phù hộ như một cách nói may rủi. Nhân vật chính Lưu Tam Mộc đã trải qua đủ loại gian nan, bất chấp nguy hiểm trùng trùng trong màn sương, cuối cùng tiết lộ sự thật của mọi thứ và mang lại ánh sáng cho Hắc Thạch LĨnh</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Zhiyang","avatar":""},{"name":"Xiao Yin","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Yu Yang","avatar":""},{"name":"Zhu Xinyuan","avatar":""},{"name":"Du Xudong","avatar":""},{"name":"Yang Dachuan","avatar":""},{"name":"Wang Peng","avatar":""},{"name":"Xu Mancang","avatar":""},{"name":"San Wenshi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324310);
