INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-con-thoi-gian', 'Khi Còn Thời Gian', 'Still Time', 'https://phimimg.com/upload/vod/20231111-1/497a5e539fdfe7d31a4f264b9ad4560d.jpg', 'https://phimimg.com/upload/vod/20231111-1/f7f847a02f34933a1fda444c97a3dcd6.jpg', '<p>Trong bộ phim hài chính kịch vượt thời gian này, một người nghiện công việc luôn tất bật nay muốn cuộc sống chậm lại khi cứ vài giờ anh lại thấy mình nhảy vọt lên trước một năm.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Edoardo Leo","avatar":""},{"name":"Barbara Ronchi","avatar":""},{"name":"Mario Sgueglia","avatar":""},{"name":"Francesca Cavallin","avatar":""},{"name":"Raz Degan","avatar":""},{"name":"Massimo Wertmüller","avatar":""},{"name":"Stella Trotta","avatar":""},{"name":"Andrea Purgatori","avatar":""},{"name":"Alla Krasovitzkaya","avatar":""},{"name":"Angelo Tanzi","avatar":""},{"name":"Alessio Genchi","avatar":""},{"name":"Barnaba Bonafaccia","avatar":""},{"name":"Luca Confortini","avatar":""},{"name":"Luigi Cesolini","avatar":""},{"name":"Chiara Shufflebotham","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324310);
