INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('miss-willoughby-and-the-haunted-bookshop', 'Miss Willoughby and the Haunted Bookshop', 'Miss Willoughby and the Haunted Bookshop', 'https://phimimg.com/upload/vod/20231110-1/1070edd97f15153bf38b4543f59519af.jpg', 'https://phimimg.com/upload/vod/20231110-1/6b2c6ab4cdba1262419a78fb41ee78ab.jpg', '<p>Tragalally mồ côi ở độ tuổi trẻ, Elizabeth Willoughby thừa hưởng bất động sản gia đình ấn tượng của cô và được nuôi dưỡng bởi chúng tôi đã nghỉ hưu Marine, Robert. Theo hướng dẫn thận trọng của mình, thời thơ ấu của cô đã được dành để nghiên cứu chiến lược, lịch sử và văn học, tất cả trong khi làm chủ các nghệ thuật chiến đấu cổ xưa. Bây giờ, một giáo sư văn minh cổ đại tại Đại học, Willoughby nhận được một cuộc gọi từ những người bạn gia đình, Helen và Oliver Deakin, những người đã trải qua một loạt các ám ảnh tại cửa hàng sách cổ của họ. Không có ai khác để chuyển sang, và biết sự thèm ăn vô độ của Willoughby để điều tra, Helen yêu cầu Willoughby đi đến tận cùng của bí ẩn huyền bí này.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Nathalie Cox","avatar":""},{"name":"Kelsey Grammer","avatar":""},{"name":"Caroline Quentin","avatar":""},{"name":"Steven Elder","avatar":""},{"name":"Tara Fitzgerald","avatar":""},{"name":"Louise Bangay","avatar":""},{"name":"Wayne Gordon","avatar":""},{"name":"Nicholas Jones","avatar":""},{"name":"Bhavna Limbachia","avatar":""},{"name":"Marc Bannerman","avatar":""},{"name":"Giacomo Gex","avatar":""},{"name":"Scarlett Graham","avatar":""},{"name":"Lucas Livesey","avatar":""},{"name":"Lauren Dickinson","avatar":""},{"name":"Russell Richardson","avatar":""},{"name":"Bryan Samson","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be8