INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-san-nguoi-tu-than', 'Cuộc Săn Người Tử Thần', 'Death Hunt', 'https://phimimg.com/upload/vod/20231109-1/37aef445ae12982c44183a719b928756.jpg', 'https://phimimg.com/upload/vod/20231109-1/12ee7a25fad84df6f1fc52fc8d930842.jpg', '<p>Lấy bối cảnh vào cuối những năm 1990, mỗi năm một lần một nhóm đàn ông chọn săn các mục tiêu là con người trên một hòn đảo xa xôi. Một nhà phát triển và tình nhân của anh ta rút lui đến một ngôi nhà nhỏ nơi nghỉ ngơi, nơi họ bị bắt làm con tin, đưa đến hòn đảo và bị săn bắn để chơi thể thao.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Rick Amsbury","avatar":""},{"name":"Michael Coughlan","avatar":""},{"name":"Mason Cromwell","avatar":""},{"name":"Frank Ieraci","avatar":""},{"name":"Greg Johnston","avatar":""},{"name":"Peter Lewis","avatar":""},{"name":"Riley Lewis","avatar":""},{"name":"Marlene Malcolm","avatar":""},{"name":"Terry McDonald","avatar":""},{"name":"Sam Slessor","avatar":""},{"name":"Omar Tucci","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324310);
