INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-san-nguoi-tu-than', 'Cuộc Săn Người Tử Thần', 'Death Hunt', 'cuộc săn người tử thần death hunt rick amsbury michael coughlan mason cromwell frank ieraci greg johnston peter lewis riley lewis marlene malcolm terry mcdonald sam slessor omar tucci ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-chien-binh-phan-1', 'Siêu Chiến Binh (Phần 1)', 'Attack Part 1', 'https://phimimg.com/upload/vod/20231109-1/bfd6c27baa4296984a66a2f788f82b01.jpg', 'https://phimimg.com/upload/vod/20231109-1/a54cd9a2cacf36cd4141c3ddd253d01a.jpg', '<p>Arjun Shergill đang thực hiện nhiệm vụ truy bắt tên khủng bố Rehman Gul, nơi anh ta cứu một kẻ đánh bom liều chết trẻ tuổi nhưng bắt được Rehman Gul. 12 năm sau khi đang đi trên một chuyến bay Arjun gặp nữ tiếp viên hàng không Ayesha và yêu cô ấy cả hai sắp đưa mối quan hệ của họ đi xa hơn nhưng một cuộc tấn công khủng bố ở sân bay giết chết Ayesha, khiến Arjun bị thương nặng. Người đứng đầu cơ quan tình báo Ấn Độ Subramanium nảy ra ý tưởng giới thiệu các siêu chiến binh được vận hành bằng robot trong Quân đội Ấn Độ để cứu những người mất mạng trong chiến tranh do Tiến sĩ Sabaha Qureshi thiết kế.Subramanium chọn Arjun cho nhiệm vụ này nhưng trong khi được giới thiệu với quy trình này, cơ hội sống sót của anh ấy là rất ít... Liệu Arjun sẽ như thế nào ?</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"John Abraham","avatar":""},{"name":"Serena Walia","avatar":""},{"name":"Rakul Preet Singh","avatar":""},{"name":"Prakash Raj","avatar":""},{"name":"Ratna Pathak Shah","avatar":""},{"name":"Elham Ehsas","avatar":""},{"name":"Jacqueline Fernandez","avatar":""},{"name":"Kiran Kumar","avatar":""},{"name":"Rajit Kapoor","avatar":""},{"name":"Jaimini Pathak","avatar":""},{"name":"Mehroos Mir","avatar":""},{"name":"Shahnawaz Bhatt","avatar":""},{"name":"Babrak Akbari","avatar":""},{"name":"Ranjit Punia","avatar":""},{"name":"Habib Al Aidroos","avatar":""},{"name":"Nimish Desai","avatar":""},{"name":"Mohd Ta","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324310);
