INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-map-duoi-nuoc', 'Cá Mập Dưới Nước', 'Blood in the Water', 'https://phimimg.com/upload/vod/20231110-1/75580c9ec9e41629c573d5674ad55732.jpg', 'https://phimimg.com/upload/vod/20231110-1/695e2976f2504c5ff1039fcf269cf2ed.jpg', '<p>Zara là một phụ nữ trẻ có một bí mật đen tối. Cuộc sống của cô đột ngột bị gián đoạn khi một tên sát nhân đeo mặt nạ đột nhập vào căn hộ của cô, đánh gục cô và xích cô vào một bể bơi cùng với năm người lạ. Ngay sau đó, họ nhận ra rằng họ không đơn độc khi thành viên cuối cùng của hội được tiết lộ: một Cá Mập trắng đáng sợ.Trò chơi của loài sinh vật vô hình chung sau đó trở nên rõ ràng khi mỗi người trong số họ được chọn từng người một để bị kéo xuống hồ bơi trở thành thức ăn cho cá mập. Khi máu đổ và số lượng người ngày càng giảm, Zara biết được rằng, để tìm được sự cứu chuộc thực sự, cô sẽ phải nói ra tất cả và phó mặc số phận của mình cho tên sát nhân xã hội đen và quan trọng hơn là con cá mập chờ đợi dưới nước.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jamie Robertson","avatar":""},{"name":"Amanda-Jade Tyler","avatar":""},{"name":"Georgie Banks","avatar":""},{"name":"Faith Kiggundu","avatar":""},{"name":"Hannah Ponting","avatar":""},{"name":"Andrew Rolfe","avatar":""},{"name":"Michael Hoad","avatar":""},{"name":"Brendan Jones","avatar":""},{"name":"Lewis Sycamore","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324310);
