INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bill-burr-truc-tiep-tai-red-rocks', 'Bill Burr: Trực tiếp tại Red Rocks', 'Bill Burr: Live at Red Rocks', 'https://phimimg.com/upload/vod/20231109-1/34ee7ea4c596b09f67fbebeb5e7079a5.jpg', 'https://phimimg.com/upload/vod/20231109-1/a535cc36b5e8a55f0edbfef68f3a5b5b.jpg', '<p>Trong tiết mục hài độc thoại sôi nổi này, cây hài Bill Burr bày tỏ quan điểm về văn hóa tẩy chay, nữ quyền, nhận đánh giá tệ từ vợ và sự giác ngộ giúp thay đổi cuộc đời.</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Burr","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324310);
