INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ghe-nong', 'Ghế Nóng', 'Hot Seat', 'https://phimimg.com/upload/vod/20231109-1/2b5d3fae7aba54fae77d32e198d1c2b5.jpg', 'https://phimimg.com/upload/vod/20231109-1/82c3fb816e73709890c659db8d08e00b.jpg', '<p>Người từng đoạt giải Oscar, Mel Gibson đã mang bộ phim kinh dị mạng bùng nổ này trở nên sống động. Hành động bắt đầu khi chuyên gia CNTT Friar (Kevin Dillon, Poseidon) tìm thấy một quả bom kích hoạt tóc được gắn trên ghế bàn của anh ta. Một hacker vô hình trung ra lệnh cho anh ta ăn cắp tiền kỹ thuật số trực tuyến - hoặc không sẽ bắt cóc con gái anh ta. Khi một chuyên gia đánh bom không sợ hãi (Gibson) đến hiện trường, hacker đã định hình Friar là kẻ đánh bom. Sự căng thẳng tăng lên khi Friar chạy đua để xóa tên của mình và vạch trần tên khủng bố thực sự - mà không khiến bản thân bị nổ tung.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Dillon","avatar":""},{"name":"Mel Gibson","avatar":""},{"name":"Shannen Doherty","avatar":""},{"name":"Sam Asghari","avatar":""},{"name":"Anna Harr","avatar":""},{"name":"Michael Welch","avatar":""},{"name":"Lydia Hull","avatar":""},{"name":"Eddie Steeples","avatar":""},{"name":"Kate Katzman","avatar":""},{"name":"Keith Jardine","avatar":""},{"name":"Jonathan Stoddard","avatar":""},{"name":"Kaleb Clifton","avatar":""},{"name":"Dylan Flashner","avatar":""},{"name":"Xzavier Estrada","avatar":""},{"name":"Drew Taylor","avatar":""},{"name":"Ben Steele","avatar":""},{"name":"Christopher Márquez","avatar":""},{"name":"Sha","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324310);
