INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-day-vo-hinh', 'Sợi dây vô hình', 'The Invisible Thread', 'https://phimimg.com/upload/vod/20231108-1/a77bead106c1024faa6f6cf0553106df.jpg', 'https://phimimg.com/upload/vod/20231108-1/a1927a1a52634f784148d13fa01ea705.jpg', '<p>Cậu con trai tuổi teen của hai ông bố làm phim tài liệu về phụ huynh, nhưng rồi bất ngờ khi một cú ngoặt xảy ra trong đời thực của gia đình cậu.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Filippo Timi","avatar":""},{"name":"Francesco Scianna","avatar":""},{"name":"Francesco Gheghi","avatar":""},{"name":"Emanuele Maria Di Stefano","avatar":""},{"name":"Matteo Oscar Giuggioli","avatar":""},{"name":"Giulia Maenza","avatar":""},{"name":"Jodhi May","avatar":""},{"name":"Valentina Cervi","avatar":""},{"name":"Gerald Tyler","avatar":""},{"name":"Mauro Conte","avatar":""},{"name":"Alessia Giuliani","avatar":""},{"name":"Tim Daish","avatar":""},{"name":"Gianluca De Marchi","avatar":""},{"name":"Ambrosia Caldarelli","avatar":""},{"name":"Enrico Borell","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324310);
