INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-quai-di-tran-am-duong', 'Chuyện Quái Dị Trấn Âm Dương', 'The Town of Ghosts', 'https://phimimg.com/upload/vod/20231108-1/d7183f5188ad9f9ec0edf10bd7ae7934.jpg', 'https://phimimg.com/upload/vod/20231108-1/7d65f800dd6cd908ab47756cbd0259cc.jpg', '<p>Diêm Dương Nhất và Bảo Hồ Lô lạc vào trấn Âm Dương kỳ lạ, nơi họ chỉ có thể vào chứ không thể ra. Bất cứ ai tự ý rời đi đều sẽ chết một cách bí ẩn. Mặc dù Diêm Dương Nhất không tin vào những truyền thuyết kinh dị trên trấn Âm Dương, nhưng rất nhiều chuyện tà ma kì quái xảy ra với họ. Diêm Vương khiến họ canh ba phải chết, vậy liệu họ có thể nào sống được đến canh năm không? Điều khiến Diêm Dương Nhất và Bảo Hồ Lô không thể ngờ được là đằng sau thị trấn ma quái bị dính lời nguyền còn có một bí mật đáng kinh ngạc...</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lee Lichun","avatar":""},{"name":"QiaoQiao Jin","avatar":""},{"name":"Jerry Wu","avatar":""},{"name":"Li Ming","avatar":""},{"name":"Wang Zhipeng","avatar":""},{"name":"Gao Chenglong","avatar":""},{"name":"Hou Tongjiang","avatar":""},{"name":"Fu Xiaoshuang","avatar":""},{"name":"An Jianlin","avatar":""},{"name":"Chen Xianmin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324310);
