INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-chung-ta-ghet-o-dam-cuoi', 'Những Người Chúng Ta Ghét Ở Đám Cưới', 'The People We Hate at the Wedding', 'https://phimimg.com/upload/vod/20231108-1/c6e1a54809f38212866af6a4e7e3609d.jpg', 'https://phimimg.com/upload/vod/20231108-1/4aab6156f1b9ede8d834b3a362c2e40c.jpg', '<p>Một gia đình rối loạn chức năng dường như không thể hòa thuận và gắn kết với nhau miễn cưỡng đoàn tụ trong một đám cưới gia đình. Khi nhiều bộ xương của họ bị lôi ra khỏi tủ quần áo, hóa ra đó chính là thứ mà gia đình độc nhất này cần để kết nối lại.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kristen Bell","avatar":""},{"name":"Ben Platt","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Cynthia Addai-Robinson","avatar":""},{"name":"Dustin Milligan","avatar":""},{"name":"John Macmillan","avatar":""},{"name":"Isaach De Bankolé","avatar":""},{"name":"Karan Soni","avatar":""},{"name":"Jorma Taccone","avatar":""},{"name":"Lizzy Caplan","avatar":""},{"name":"Andrew Daly","avatar":""},{"name":"Adam Godley","avatar":""},{"name":"Brandon Johnston","avatar":""},{"name":"Lexi Janicek","avatar":""},{"name":"Milakale Kember","avatar":""},{"name":"Jaxon Goldenberg","avatar":""},{"name":"Emma","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324310);
