INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiem-quyen', 'Chiếm Quyền', 'The Takeover', 'https://phimimg.com/upload/vod/20231108-1/d4488504d16ce0b36784308ac798c424.jpg', 'https://phimimg.com/upload/vod/20231108-1/40a79518d4db9d19c5b21b6ca44b163b.jpg', '<p>Bị đổ tội giết người sau khi phát hiện ra vụ bê bối về quyền riêng tư, một tin tặc mũ trắng vừa trốn tránh cảnh sát vừa truy tìm bọn tội phạm đang đe dọa cô.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Hà Lan', 0, '[{"name":"Holly Mae Brood","avatar":""},{"name":"Géza Weisz","avatar":""},{"name":"Susan Radder","avatar":""},{"name":"Frank Lammers","avatar":""},{"name":"Noortje Herlaar","avatar":""},{"name":"Walid Benmbarek","avatar":""},{"name":"Lawrence Sheldon","avatar":""},{"name":"Jenny Hsia","avatar":""},{"name":"Faye Kimmijser","avatar":""},{"name":"Mike Wijdenbosch","avatar":""},{"name":"Carly Wijs","avatar":""},{"name":"Thomas Dudkiewicz","avatar":""},{"name":"Kyra Isako Smith","avatar":""},{"name":"Burt Rutteman","avatar":""},{"name":"Bas Heerkens","avatar":""},{"name":"Geoffrey Breton","avatar":""},{"name":"Kok-","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324310);
