INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lenh-bat-rong', 'Lệnh Bắt Rồng', 'Catch the dragon', 'https://phimimg.com/upload/vod/20231108-1/92a54e6dcd50d44ab20c65a3fd849b56.jpg', 'https://phimimg.com/upload/vod/20231108-1/deeb216e05a3fbcdc427bb9197a18768.jpg', '<p>Cha của chuyên gia sinh vật học cổ Tần Hiểu Phong đã mất khi ông đến núi Côn Mạch để tìm kiếm rồng. Để tìm ra sự thật về cái chết của cha mình, Tần Hiểu Phong đã lên đường tìm kiếm con rồng cùng với thợ săn Hỏa Gia và cao thủ về các cơ quan Diệp Dục Linh. Khi Tần Hiểu Phong nghĩ rằng mình có thể tìm ra bí ẩn về cái chết của cha bằng cách bắt con rồng, thì anh đã vô tình phát hiện ra xương của các thành viên đội thám hiểm sinh học trước đó, có dấu vết của những viên đạn. Đối mặt với những nghi vấn, Tần Hiểu Phong hoàn toàn bị rơi vào vòng bí ẩn. Sự thật về cái chết của cha và sự khủng hoảng của đội bắt rồng dường như có kẻ đứng sau, đẩy Tần Hiểu Phong từng bước rơi xuống vực sâu không đáy.</p>', 'Full', 1, 'single', 'completed', 9, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jeam","avatar":""},{"name":"Xing Yu","avatar":""},{"name":"Haoyue Huang","avatar":""},{"name":"Zheng Honglai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324310);
