INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-menh-hoang-gia', 'Vận Mệnh Hoàng Gia', 'The Royal Treatment', 'https://phimimg.com/upload/vod/20231108-1/0e4db8f3f405dbf5d8b779cb2f275d82.jpg', 'https://phimimg.com/upload/vod/20231108-1/69e0baec00de763bd1e6c48a70b1958c.jpg', '<p>Cô thợ làm tóc Izzy tại New York nắm lấy cơ hội làm việc ở đám cưới của chàng bạch mã hoàng tử. Nhưng khi họ nảy sinh tình cảm, liệu tình yêu hay nghĩa vụ sẽ thắng?</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Laura Marano","avatar":""},{"name":"Mena Massoud","avatar":""},{"name":"Chelsie Preston Crayford","avatar":""},{"name":"Grace Bentley-Tsibuah","avatar":""},{"name":"Cameron Rhodes","avatar":""},{"name":"Sonia Gray","avatar":""},{"name":"Amanda Billing","avatar":""},{"name":"Elizabeth Hawthorne","avatar":""},{"name":"Paul Norell","avatar":""},{"name":"Teuila Blakely","avatar":""},{"name":"James Gaylyn","avatar":""},{"name":"Phoenix Connolly","avatar":""},{"name":"Jacque Drew","avatar":""},{"name":"Matthew E. Morgan","avatar":""},{"name":"Taylor Barrett","avatar":""},{"name":"Sial","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324310);
