INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uoc-mo-cua-nate', 'Ước Mơ Của Nate', 'Better Nate Than Ever', 'https://phimimg.com/upload/vod/20231108-1/6056deb85c828c99e2a98d871d78ff8a.jpg', 'https://phimimg.com/upload/vod/20231108-1/7eaf3654e8a23610106e7754725e1d87.jpg', '<p>Nate Foster, 13 tuổi, có ước mơ trở thành một ngôi sao nhạc kịch Broadway. Tuy nhiên, cậu bé thậm chí không thể có được một vai tử tế trong các tác phẩm ở trường cấp hai của mình. Dẫu vậy, khi cậu và người bạn thân nhất của mình là Libby quyết định thức hiện một chuyến đi táo bạo đến Thành phố New York để thử giọng cho “Lilo and Stitch: The Musical”.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rueby Wood","avatar":""},{"name":"Lisa Kudrow","avatar":""},{"name":"Joshua Bassett","avatar":""},{"name":"Aria Brooks","avatar":""},{"name":"Norbert Leo Butz","avatar":""},{"name":"Michelle Federer","avatar":""},{"name":"Finn Egan-Liang","avatar":""},{"name":"Pierson Salvador","avatar":""},{"name":"Mandy González","avatar":""},{"name":"Jimmy Ray Bennett","avatar":""},{"name":"Brandon Espinoza","avatar":""},{"name":"Kim Rios Lin","avatar":""},{"name":"Kylie Kuioka","avatar":""},{"name":"Krystina Alabado","avatar":""},{"name":"Brooks Ashmanskas","avatar":""},{"name":"Tamika Lawre","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324310);
