INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-viking', 'Sói Viking', 'Vikingulven', 'https://phimimg.com/upload/vod/20231108-1/b9e590b32b742b1ca11acce8e461d95b.jpg', 'https://phimimg.com/upload/vod/20231108-1/90985da3d989c95485c5bcb42cd60cee.jpg', '<p>Sau khi chứng kiến vụ án mạng kỳ dị tại một bữa tiệc ở thị trấn mới của mình, cô nàng tuổi teen nọ bắt đầu nhìn thấy những ảo ảnh kỳ lạ và có những ham muốn kỳ quái.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Elli Rhiannon Müller Osborne","avatar":""},{"name":"Liv Mjönes","avatar":""},{"name":"Vidar Magnussen","avatar":""},{"name":"Mia Fosshaug Laubacher","avatar":""},{"name":"Arthur Hakalahti","avatar":""},{"name":"Sjur Vatne Brean","avatar":""},{"name":"Øyvind Brandtzæg","avatar":""},{"name":"Ståle Bjørnhaug","avatar":""},{"name":"Sverre Breivik","avatar":""},{"name":"Anna Dworak","avatar":""},{"name":"Assad Siddique","avatar":""},{"name":"Hilde Olausson","avatar":""},{"name":"Ola Otnes","avatar":""},{"name":"Kasper Antonsen","avatar":""},{"name":"Silje Økslan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324310);
