INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-dam', 'Quái Đàm', 'The Unbelievable', 'https://phimimg.com/upload/vod/20231108-1/129af11f024e75f1d4e5bee7ebf1c240.jpg', 'https://phimimg.com/upload/vod/20231108-1/676942d87c3567d054fd272d09417b4d.jpg', '<p>Khi Thanh Trình còn là một thiếu niên, anh đã bị tấn công bởi một con quái vật đột biến không rõ nguồn gốc, mất đi gia đình và trí nhớ, anh bị dân làng coi là điềm gở sẽ mang đến tai họa. Mười năm sau, những con quái vật đột biến lại xuất hiện tàn sát rất nhiều người. Thanh Trình mơ hồ nhận ra rằng những con quái vật này có liên quan đến trí nhớ đã mất của mình, để cứu ngôi làng và lấy lại trí nhớ của mình,Thanh Trình quyết tâm đối đầu với lũ quái vật. Nhưng điều bất ngờ là đằng sau con quái vật này lại có một thế lực khác, đang làm những thí nghiệm kinh hoàng của con người, cả ngôi lang đã tham gia vào thí nghiệm đó, đang đối mặt với những thảm họa</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Patrick Shih","avatar":""},{"name":"Fu Mengni","avatar":""},{"name":"Pei Chenwei","avatar":""},{"name":"He Shaohong","avatar":""},{"name":"Tao Wang","avatar":""},{"name":"Zhang Dong","avatar":""},{"name":"Zhu Haijun","avatar":""},{"name":"Ren Xuehai","avatar":""},{"name":"Yang Dachuan","avatar":""},{"name":"Han Mengwu","avatar":""},{"name":"Li Ping''an","avatar":""},{"name":"Li Yuanqi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324310);
