INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-doi-san-tien-thuong', 'Bộ Đôi Săn Tiền Thưởng', 'No Name and Dynamite', 'https://phimimg.com/upload/vod/20231108-1/355269063a2e4300072a63a66af8dc14.jpg', 'https://phimimg.com/upload/vod/20231108-1/53dca1191f418689410a4c954ab55d7d.jpg', '<p>Ranh giới giữa người tốt và kẻ xấu mờ đi khi những kẻ săn tiền thưởng tàn nhẫn No Name và Dynamite Davenport bắn phá miền Tây hoang dã, thu thập phần thưởng và kết bạn với nhiều kẻ thù hơn. Với kẻ ngoài vòng pháp luật John Wilkes Booth đang chạy trốn và giấu vàng trên đồi, công lý phải được thực thi.</p>', 'Full', 1, 'single', 'completed', 22, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Northup","avatar":""},{"name":"Rich Ting","avatar":""},{"name":"Natalie Burn","avatar":""},{"name":"Vernon Wells","avatar":""},{"name":"Thomas Rosales Jr.","avatar":""},{"name":"Mark Krenik","avatar":""},{"name":"Walter Scott","avatar":""},{"name":"Esteban Cueto","avatar":""},{"name":"Jawed El Berni","avatar":""},{"name":"Don Collier","avatar":""},{"name":"Bonnie Morgan","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324310);
