INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-day-an-dien', 'Giáng sinh đầy ân điển', 'Christmas Full of Grace', 'https://phimimg.com/upload/vod/20231107-1/45c1da6deb1bf748930788b482fa592f.jpg', 'https://phimimg.com/upload/vod/20231107-1/2231bc7305b8cc094a0b91682cf049bf.jpg', '<p>Sau khi bắt quả tang người yêu lừa dối mình, Carlinhos gặp Graça sôi nổi. Cô giả làm người yêu mới của anh để anh giữ thể diện với gia đình truyền thống của mình vào Giáng sinh.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Sergio Malheiros","avatar":""},{"name":"Gessica Kayane","avatar":""},{"name":"Vera Fischer","avatar":""},{"name":"Monique Alfradique","avatar":""},{"name":"Letícia Isnard","avatar":""},{"name":"Nando Cunha","avatar":""},{"name":"Cézar Maracujá","avatar":""},{"name":"Flávia Reis","avatar":""},{"name":"Valentina Vieira","avatar":""},{"name":"Gabriel Louchard","avatar":""},{"name":"Heitor Martinez","avatar":""},{"name":"Valéria Vitoriano","avatar":""},{"name":"Victor Meyniel","avatar":""},{"name":"Noemia Oliveira","avatar":""},{"name":"Diogo Defante","avatar":""},{"name":"Marianna","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324310);
