INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('fruits-basket-prelude', 'Fruits Basket: Prelude', 'Fruits Basket: Prelude', 'https://phimimg.com/upload/vod/20231108-1/0465386d6f17616efec5156f64284e57.jpg', 'https://phimimg.com/upload/vod/20231108-1/488be89b9792a2ed7b11c9c69b168a17.jpg', '<p>Kyoko, người không thể tin vào bất cứ điều gì trên thế giới và sống một cuộc sống hoang vắng, gặp Katsuya Honda, người được chỉ định làm thực tập sinh giáo dục. Cô ấy phải chịu sự thương xót của Katsuya, người thô lỗ và có thói quen mạnh mẽ, và cô ấy dần dần bị thu hút bởi cô ấy. Tuy nhiên, cô bị cha mẹ ruồng bỏ sau một sự cố với người bạn xấu của mình. Đó là một hình phạt mà tôi đã làm bao nhiêu tùy thích. Katsuya xuất hiện trước mặt Kyoko, người nghĩ vậy...</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Manaka Iwami","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Yuma Uchida","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324310);
