INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('liss-pereira-lam-nguoi-lon', 'Liss Pereira: Làm người lớn', 'Liss Pereira: Adulting', 'https://phimimg.com/upload/vod/20231108-1/0bae95ead9d254dd799f4cedb18dd2bc.jpg', 'https://phimimg.com/upload/vod/20231108-1/9fb6912f64e3a823d45c1474cf1edead.jpg', '<p>Cây hài Liss Pereira chia sẻ chân tình về các mối quan hệ, tuổi trưởng thành và trạng thái lững lờ – không hoàn hảo cũng không quá tệ – trong thế giới của những thái cực.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Colombia', 0, '[{"name":"Liss Pereira","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324310);
