INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tich-ca-trich', 'Sự Tích Cá Trích', 'The legend of herring', 'https://phimimg.com/upload/vod/20231108-1/650ea0e671d12cc37a020217680135cc.jpg', 'https://phimimg.com/upload/vod/20231108-1/981f3b29b2b64efa98f7e3767e05dbf9.jpg', '<p>Liễu Thiên Chi là đệ tử của Bất Ngôn Môn chuyên hàng yêu diệt ma, tình cờ gặp Tiểu Thanh, một ngư yêu muốn tu luyện thành rồng. Tiểu Thanh đã nói dối rằng cô ấy cũng là một pháp sư trừ yêu để người khác không phát hiện ra thân phận ngư yêu của mình Sau đó, cả hai cùng nhau phiêu bạt và trải qua nhiều khó khăn trở ngại. Trên đường đi, trái tim nhân hậu của Tiểu Thanh không chỉ thay đổi suy nghĩ của Liễu Thiên Chi rằng quái vật là xấu xa mà còn trở thành chỗ dựa lẫn nhau. Cuối cùng, cả hai đã chung tay đánh bại âm mưu của ác long và bảo vệ những người dân thường trên thế giới, kể cả Tiểu Thanh sẵn sàng hy sinh thân rồng để đổi lấy sự hồi sinh của Liễu Thiên Chi;</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sabrina Qiu","avatar":""},{"name":"Zhang Yaqi","avatar":""},{"name":"Canti Lau Sek-Ming","avatar":""},{"name":"Lanyi Zhang","avatar":""},{"name":"Shao Sihan","avatar":""},{"name":"Zheng Peilin","avatar":""},{"name":"Zhao Ruihan","avatar":""},{"name":"Li Shiyan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324310);
