INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-danh-anh-hung', 'Giả Danh Anh Hùng', 'Superwho? (Super-héros Malgré Lui)', 'https://phimimg.com/upload/vod/20231108-1/03374cd32245509febad1bcf1d6558b1.jpg', 'https://phimimg.com/upload/vod/20231108-1/6cee42291b7ac5dd900a407dfd54a11a.jpg', '<p>Diễn viên đấu tranh Cedric dường như sẽ phải sống cuộc đời của một kẻ thất bại. Anh ấy đã tan vỡ và bạn gái của anh ấy đã bỏ rơi anh ấy. Ngay cả cha, chị gái và những người bạn thân nhất của anh ấy cũng mất niềm tin vào khả năng làm bất cứ điều gì đáng giá của anh ấy. Cuối cùng, anh ấy nhận được một vai chính: siêu anh hùng “Badman”. Một cơ hội để kéo mình ra khỏi vòng xoáy đi xuống vô tận và nhận được sự tôn trọng của cha mình. Nhưng số phận lại ập đến! Vội vã rời khỏi phim trường trong bộ trang phục đầy đủ.....</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Philippe Lacheau","avatar":""},{"name":"Julien Arruti","avatar":""},{"name":"Tarek Boudali","avatar":""},{"name":"Élodie Fontan","avatar":""},{"name":"Alice Dufour","avatar":""},{"name":"Jean-Hugues Anglade","avatar":""},{"name":"Amr Waked","avatar":""},{"name":"Chantal Ladesou","avatar":""},{"name":"Brahim Bouhlel","avatar":""},{"name":"Georges Corraface","avatar":""},{"name":"Paco Boisson","avatar":""},{"name":"Tony Saint-Laurent","avatar":""},{"name":"Salomé Partouche","avatar":""},{"name":"Dédeine Volk-Léonovitch","avatar":""},{"name":"Régis Laspalès","avatar":""},{"name":"I","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324310);
