INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-mon-huyen-an', 'Tân Môn Huyền Án', 'The curious case of Tianjin', 'https://phimimg.com/upload/vod/20231108-1/1f72d4bc27e094755a6b44a6864f63ae.jpg', 'https://phimimg.com/upload/vod/20231108-1/d992b7889982c93a219279812f304143.jpg', '<p>Trong thời kỳ Dân Quốc, tình hình tại bến cảng Tân Môn lại trở lên hỗn loạn. Tào Vận và bang Thanh Long đánh nhau tranh chấp địa bàn làm ăn kinh doanh. Tần Phàm đi đàm phán nhưng vô tình đánh chết hai người anh em của bang phái, bị gán cho cái tên là kẻ giết người vượt ngục trộm xác sau đó bị cảnh sát và hai bang phái truy đuổi. các băng nhóm với nhau. Tần Phàm vì không nhớ mình đã trốn thoát bằng cách nào nên đã quyết định đích thân tìm ra nguyên nhân thực sự cái chết của tên trộm xác chết và hai người em trai của hắn để chứng minh mình vô tội. Sảnh lớn khói mịt mù cả bến tàu Âm mưu hại nước hại dân, Tần Sở có thể thoát ra ngoài an toàn? Làm thế nào để ngăn chặn những hành động xấu xa của kẻ ngoại lai?</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Junming","avatar":""},{"name":"Tan Xiaofan","avatar":""},{"name":"Li Feiran","avatar":""},{"name":"Zhang Chunzhong","avatar":""},{"name":"Guo Jiayi","avatar":""},{"name":"Kai Shen","avatar":""},{"name":"Lin Xuepiao","avatar":""},{"name":"Li Yanfeng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324310);
