INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-trom-mussolini', 'Vụ Trộm Mussolini', 'Robbing Mussolini', 'https://phimimg.com/upload/vod/20231108-1/868fdf3608af9328aa87062fbfc08685.jpg', 'https://phimimg.com/upload/vod/20231108-1/d282c2fad5d03f9f5c0b85ff82233c11.jpg', '<p>Cuối Thế chiến II, một nhóm chiến binh kháng chiến đủ thành phần lên kế hoạch thực hiện vụ trộm bất khả thi: đánh cắp kho báu của Mussolini tại trụ sở phát xít của Milan.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Pietro Castellitto","avatar":""},{"name":"Matilda De Angelis","avatar":""},{"name":"Tommaso Ragno","avatar":""},{"name":"Isabella Ferrari","avatar":""},{"name":"Filippo Timi","avatar":""},{"name":"Alberto Astorri","avatar":""},{"name":"Maccio Capatonda","avatar":""},{"name":"Luigi Fedele","avatar":""},{"name":"Coco Rebecca Edogamhe","avatar":""},{"name":"Maurizio Lombardi","avatar":""},{"name":"Lorenzo de Moor","avatar":""},{"name":"Luca Lo Destro","avatar":""},{"name":"Giorgio Antonini","avatar":""},{"name":"Enrico Bergamasco","avatar":""},{"name":"Matteo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324310);
