INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-nhan-kiet-doat-menh-ki-huong', 'Định Nhân Kiệt: Đoạt Mệnh Kì Hương', 'Detective Dee: Scent of a Killer', 'https://phimimg.com/upload/vod/20231107-1/a35d58eb8540bb50caa1198dae2e6aef.jpg', 'https://phimimg.com/upload/vod/20231107-1/5cffb61f650eae3a5366d6f946510c9f.jpg', '<p>Thời nhà Chu, Maiko nổi tiếng của Lạc Dương đã bị chặt đầu oan, biến thành oan hồn và giết người hàng loạt. Định Nhân Kiệt được phái đến để điều tra vụ án. Không ngờ trên đường trở về thành lại bị ám sát và rơi xuống vách núi mất trí nhớ, nhưng được Lã Chiêu Nguyên trên đường vào thành tìm vợ cứu sống. Hai người đã hoán đổi thân phận cho nhau, La Chiêu Nguyên lúc này bất đắc dĩ phải điều tra vụ án. Với bản năng điều tra và cái nhìn sâu sắc tuyệt vời của mình, La Chiêu Nguyên đã nhanh chóng nắm được bằng chứng then chốt về mùi thơm kỳ lạ của xác chết . Hai người với hai thân phận hoán đổi đã hợp tác rất ăn ý, sử dụng lợi thế của mình để vạch trần sự thật, và kẻ sát nhân thực sự đứng sau \&quot;ma nữ\&quot; cuối cùng cũng lộ diện...</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yang Bing","avatar":""},{"name":"Xiao Hongpeng","avatar":""},{"name":"Wang Yitian","avatar":""},{"name":"Wang Meiying","avatar":""},{"name":"Bao Yanxi","avatar":""},{"name":"Yuan Yulong","avatar":""},{"name":"Emile Amro","avatar":""},{"name":"Jason Thomas Wong","avatar":""},{"name":"Guo Jinbiao","avatar":""},{"name":"Zhu Tianyu","avatar":""},{"name":"Nu Ya","avatar":""},{"name":"Zhu Xinfan","avatar":""},{"name":"Zhang Minglei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324310);
