INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dinh-nhan-kiet-doat-menh-ki-huong', 'Định Nhân Kiệt: Đoạt Mệnh Kì Hương', 'Detective Dee: Scent of a Killer', 'định nhân kiệt: đoạt mệnh kì hương detective dee: scent of a killer yang bing xiao hongpeng wang yitian wang meiying bao yanxi yuan yulong emile amro jason thomas wong guo jinbiao zhu tianyu nu ya zhu xinfan zhang minglei ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuop-rong-hoa-meo', 'Cướp Rồng Hóa Mèo', 'Civet cat for crown prince', 'https://phimimg.com/upload/vod/20231107-1/6d8a85f11fdc84ebcec5e0d09514fb11.jpg', 'https://phimimg.com/upload/vod/20231107-1/dfeb135589c10df556c0223a689af503.jpg', '<p>Bộ phim là một loạt tình tiết gay cấn bắt nguồn từ việc tình cờ trao đổi thân phận của hai người đàn ông ban đầu không liên quan gì đến nhau. Từ Nghị vốn là một gã lang thang thất nghiệp ở khu phố Trung Quốc của Thái Lan. Anh ta cho rằng thất bại trong cuộc sống là số không may mắn và luôn đổ lỗi cho người khác. Một cách tình cờ, anh đã vô tình hoán đổi danh tính với Long Sơn, từ đó dính vào cuộc chiến giữa Long Sơn và băng nhóm tội phạm Skeleton Buddha. Từ Nghị cuối cùng đã lựa chọn đứng về phía công lý và cùng với Long Sơn đưa băng nhóm Skeleton Buddha ra trước công lý, anh ấy cũng nhận ra những khiếm khuyết của bản thân dưới ảnh hưởng của Long Sơn và quyết định đối mặt với cuộc sống với một thái độ tích cực thay vì phàn nàn.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Peng Yu Si","avatar":""},{"name":"Cui Yongxuan","avatar":""},{"name":"Qian Siyi","avatar":""},{"name":"Shen Taoran","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324310);
