INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-vanessa-guillen', 'Tôi là Vanessa Guillen', 'I Am Vanessa Guillen', 'https://phimimg.com/upload/vod/20231107-1/7aeca83c92451ebe416874a3681b4f70.jpg', 'https://phimimg.com/upload/vod/20231107-1/76b96eddf38cc0f3ae021e7aa4e89a9b.jpg', '<p>Vanessa Guillen được phát hiện bị sát hại tại một căn cứ của quân đội Hoa Kỳ, khi đó cô mới 20 tuổi. Thay vì ngậm đắng nuốt cay, gia đình cô đấu tranh vì công lý và sự thay đổi.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jackie Speier","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324310);
