INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuyet-phuc', 'Thuyết Phục', 'Persuasion', 'https://phimimg.com/upload/vod/20231107-1/76df6cb7b62a49d90ecdf1ab88407f82.jpg', 'https://phimimg.com/upload/vod/20231107-1/58c2772e4d506fb797e38a027b6aba33.jpg', '<p>Tám năm sau khi Anne Elliot bị thuyết phục không cưới người đàn ông bảnh bao có xuất thân khiêm tốn, họ gặp lại. Liệu cô có nắm lấy cơ hội thứ hai với tình yêu đích thực?</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Dakota Johnson","avatar":""},{"name":"Cosmo Jarvis","avatar":""},{"name":"Henry Golding","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Nikki Amuka-Bird","avatar":""},{"name":"Ben Bailey Smith","avatar":""},{"name":"Mia McKenna-Bruce","avatar":""},{"name":"Izuka Hoyle","avatar":""},{"name":"Nia Towle","avatar":""},{"name":"Edward Bluemel","avatar":""},{"name":"Lydia Rose Bewley","avatar":""},{"name":"Yolanda Kettle","avatar":""},{"name":"Jordan Long","avatar":""},{"name":"Simon Paisley Day","avatar":""},{"name":"Agni Scott","avatar":""},{"name":"Stewart Scudamore","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324310);
