INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('son-hai-phuc-ma-truy-nguyet', 'Sơn Hải Phục Ma: Truy Nguyệt', 'Story Of Shanhaijing', 'null', 'https://phimimg.com/upload/vod/20231114-1/4483552ebb3749275c9f9391ff81d57c.jpg', '<p>Bộ Phim Dựa Trên Thần Thoại Và Truyền Thuyết Dân Gian Quen Thuộc Với Khán Giả Trung Quốc, Hằng Nga Bay Lên Mặt Trăng Và Hậu Nghệ Bắn Mặt Trời, Trên Cơ Sở Hai Thần Thoại Và Tiểu Thuyết Này, Sử Dụng Khái Niệm Thời Gian Và Không Gian Kép. Bộ Phim Chủ Yếu Kể Về Câu Chuyện Tình Yêu Chung Thuỷ Của Hằng Nga Và Hậu Nghệ, Nhưng Họ đã Bị Chia Cắt Bởi Sự Hiểu Lầm, Và Cố Gắng Viết Lại Lịch Sử. Liệu Rằng Hằng Nga Và Hậu Nghệ Có Thể Tái Hợp Không? Liệu Những điều Mà Hằng Nga Hy Sinh Vì Tình Yêu Có Thể Giúp Cô Tìm Thấy đích đến Của Tình Yêu? Sau Sự đảo Lộn Của Thời Gian Và Không Gian, Xingtian Tranh đoạt Vị Thần, Hằng Nga Bay Lên Mặt Trăng Và âm Mưu Gây Chấn động Nào được Cất Giấu Trên Thiên Cung?</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Leo Xu Ding","avatar":""},{"name":"Lu Xiao Ran","avatar":""},{"name":"Teng Yi","avatar":""},{"name":"Jiang Tong","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324310);
