INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-ban-hang-iii', 'Gã Bán Hàng III', 'Clerks III', 'https://phimimg.com/upload/vod/20231103-1/3fc6c3c17dd25e7b9c501d2996f1da57.jpg', 'https://phimimg.com/upload/vod/20231103-1/672e511b65911c2c1bdcab8ca4fb6d6b.jpg', '<p>Sau khi sống sót trong gang tấc sau một cơn đau tim lớn, Randal nhờ người bạn cũ của mình là Dante để giúp anh ta làm một bộ phim bất tử về những ngày tháng tuổi trẻ của họ tại cửa hàng tiện lợi nhỏ đã bắt đầu tất cả.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeff Anderson","avatar":""},{"name":"Brian O''Halloran","avatar":""},{"name":"Jason Mewes","avatar":""},{"name":"Kevin Smith","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Marilyn Ghigliotti","avatar":""},{"name":"Trevor Fehrman","avatar":""},{"name":"Austin Zajur","avatar":""},{"name":"Jennifer Schwalbach Smith","avatar":""},{"name":"Harley Quinn Smith","avatar":""},{"name":"Amy Sedaris","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Michelle Buteau","avatar":""},{"name":"Marc Bernardin","avatar":""},{"name":"AnnaMarie Brown","avatar":""},{"name":"Ya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324310);
