INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phao-dai-2-ke-noi-gian', 'Pháo Đài 2: Kẻ Nội Gián', 'Fortress: Sniper''s Eye', 'https://phimimg.com/upload/vod/20231107-1/83d19d6be055a22c9f951888a60eb232.jpg', 'https://phimimg.com/upload/vod/20231107-1/4eed2806f778ed5fd67654190ba3e99f.jpg', '<p>Nhiều tuần sau cuộc tấn công chết người ở Trại Pháo đài, Robert đã thực hiện một cuộc giải cứu táo bạo để cứu Sasha, góa phụ của kẻ thù cũ Balzary của anh. Nhưng trở lại hầm chỉ huy của trại, có vẻ như Sasha có thể có những kế hoạch ranh ma của riêng mình. Khi một cuộc tấn công mới nổ ra, Robert phải đối mặt với một khuôn mặt quen thuộc mà anh nghĩ rằng anh sẽ không bao giờ gặp lại…</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chad Michael Murray","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Jesse Metcalfe","avatar":""},{"name":"Kelly Greyson","avatar":""},{"name":"Ser''Darius Blain","avatar":""},{"name":"Michael Sirow","avatar":""},{"name":"Welker White","avatar":""},{"name":"Natali Yura","avatar":""},{"name":"Celeste Fianna","avatar":""},{"name":"Larken Woodward","avatar":""},{"name":"Leslee Emmett","avatar":""},{"name":"Alyssa Julya Smith","avatar":""},{"name":"Natalie Burn","avatar":""},{"name":"Gabrielle Haugh","avatar":""},{"name":"Leonardo Castro","avatar":""},{"name":"Adam Hue","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324310);
