INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoac-gia-quyen-my-nu-tay-sat-3', 'Hoắc Gia Quyền Mỹ Nữ Tay Sắt 3', 'The Queen of Kung Fu 3', 'https://phimimg.com/upload/vod/20231103-1/92b9f1c4a19229c30e5691534cb85809.jpg', 'https://phimimg.com/upload/vod/20231103-1/fb42e6275a775b17d6197ac8d993e5d0.jpg', '<p>Bà chủ xinh đẹp A Hi của Bến Thượng Hải quyết định rửa tay gác kiếm. Nhưng các môn phái khác nhau trong rừng đang tranh giành danh hiệu võ sĩ giỏi nhất thế giới. Khi A Hi về quê, sư phụ cô đã bị sát hại. Để trả thù cho sư phụ cô trở về Thượng Hải cùng sư phụ và tìm giết bọn xã hội đen, nhưng cô lại bị vu oan là giết thầy diệt tổ. Làm thế nào cô ấy có thể trả thù cho sư phụ và trừng phạt những kẻ ác?</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Meng Meng","avatar":""},{"name":"Ma Mu Xuan","avatar":""},{"name":"Xie Ning","avatar":""},{"name":"Mã Đông Chấn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324310);
