INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-song-va-cai-chet', 'Sự Sống Và Cái Chết', 'Men of Sacrifice', 'https://phimimg.com/upload/vod/20231103-1/e5622b4a05736919ffb07576b86348bb.jpg', 'https://phimimg.com/upload/vod/20231103-1/9ae85a04ecf4661ab8e8619a8e317d04.jpg', '<p>Đội SWAT của EOD với Mã Tiến và Chu Giang là đối tác, đã được điều động ngay sau khi nhận được thông tin từ cảnh sát và họ phải giải quyết mối đe dọa bom trong một chiếc bánh tại văn phòng của Lý Đông Hưng, một người đứng đầu một nhóm tội phạm. Qua quá trình điều trachi tiết, cảnh sát phát hiện ra rằng vụ án là hành động trả đũa của chủ mỏ đá cũ Tuấn Hùng đối với Lý Đông Hưng, và Tuấn Hùng cũng có trong tay 200 kg thuốc nổ, nếu kích nổ thì hậu quả sẽ rất thảm khốc . Trận chiến giữa EOD SWAT và Phan Tuấn Hùng sắp nổ ra, và kết cục chỉ diễn ra trong vòng mili giây</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Duan Bowen","avatar":""},{"name":"Wang Yuzhang","avatar":""},{"name":"Haobo Hu","avatar":""},{"name":"Zhaoyan Guozhang","avatar":""},{"name":"Coco Fan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324310);
