INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-charlie', 'Chú Chó Charlie', '777 Charlie', 'https://phimimg.com/upload/vod/20231103-1/f594a50aa026de35f8b00805de7360ec.jpg', 'https://phimimg.com/upload/vod/20231103-1/4b5fce3154223c37c29dcde8f70c23c6.jpg', '<p>Dharma bị mắc kẹt trong guồng quay với lối sống tiêu cực và cô đơn của mình và dành mỗi ngày để thoải mái với nỗi cô đơn của mình. Một chú chó con tên Charlie nghịch ngợm và năng động, hoàn toàn trái ngược với tính cách của Dharma bước vào cuộc sống của anh ấy và mang đến cho anh ấy một cái nhìn mới về nó.</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Rakshit Shetty","avatar":""},{"name":"Raj B Shetty","avatar":""},{"name":"Bobby Simha","avatar":""},{"name":"Sangeetha Sringeri","avatar":""},{"name":"Bhargavi Narayan","avatar":""},{"name":"Danish Sait","avatar":""},{"name":"Harini Shreekanth","avatar":""},{"name":"Mime  Ramdas","avatar":""},{"name":"Dinesh Mangalore","avatar":""},{"name":"Anirudh Mahesh","avatar":""},{"name":"Bangalore Nagesh","avatar":""},{"name":"Praanya Rao","avatar":""},{"name":"Sharvari","avatar":""},{"name":"Jhanvi","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324310);
