INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-khong-voi-cai-ac', 'Nói Không Với Cái Ác', 'Speak No Evil', 'https://phimimg.com/upload/vod/20231110-1/2d426599fbf91a113d20e3b4e3845c20.jpg', 'https://phimimg.com/upload/vod/20231110-1/56791f57b4e7dc764b03d5564ed300ac.jpg', '<p>Trong một kỳ nghỉ ở Tuscany, hai gia đình - một người Đan Mạch, một người Hà Lan - gặp gỡ và trở thành những người bạn nhanh chóng. Nhiều tháng sau, gia đình Hà Lan có tinh thần tự do mở rộng lời mời đến một gia đình Đan Mạch bảo thủ hơn về một kỳ nghỉ cuối tuần ở quê nhà của họ. Tuy nhiên, không lâu sau mọi thứ dần trở nên không như ý khi niềm vui đoàn tụ bị thay thế bằng những hiểu lầm. Lòng hiếu khách của người Hà Lan nhanh chóng khiến người Đan Mạch khó chịu, và họ ngày càng thấy mình bị cuốn vào một mạng lưới lịch sự của riêng mình khi đối mặt với những hành vi lập dị ... hay đó là hành vi ... độc ác.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Morten Burian","avatar":""},{"name":"Sidsel Siem Koch","avatar":""},{"name":"Fedja van Huêt","avatar":""},{"name":"Karina Smulders","avatar":""},{"name":"Liva Forsberg","avatar":""},{"name":"Marius Damslev","avatar":""},{"name":"Hichem Yacoubi","avatar":""},{"name":"Lea Baastrup Rønne","avatar":""},{"name":"Jesper Dupont","avatar":""},{"name":"Sieger Sloot","avatar":""},{"name":"Ilaria Di Raimo","avatar":""},{"name":"Alessio Barni","avatar":""},{"name":"Sarina Maria Rausa","avatar":""},{"name":"Adrian Blanchard","avatar":""},{"name":"Martina Barreca","avatar":""},{"name":"Andrea","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324310);
