INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-doi-hoan-my', 'Bộ Đôi Hoàn Mỹ', 'A Perfect Pairing', 'https://phimimg.com/upload/vod/20231102-1/e6420e3ab8eb6176280644c48cccc318.jpg', 'https://phimimg.com/upload/vod/20231102-1/0dd061e7ccc7f2db7f15d00e81bef375.jpg', '<p>Để giành được một khách hàng lớn, vị giám đốc rượu vang năng nổ ở Los Angeles nhận việc tại trang trại cừu ở Úc rồi phải lòng anh chàng thô kệch và bí ẩn ở địa phương.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Victoria Justice","avatar":""},{"name":"Adam Demos","avatar":""},{"name":"Luca Sardelis","avatar":""},{"name":"Samantha Cain","avatar":""},{"name":"Craig Horner","avatar":""},{"name":"Antonio Alvarez","avatar":""},{"name":"Lucy Durack","avatar":""},{"name":"Emily Havea","avatar":""},{"name":"Natalie Abbott","avatar":""},{"name":"Jayden Popik","avatar":""},{"name":"Alex Neal","avatar":""},{"name":"Callan Knight","avatar":""},{"name":"Nicholas Brown","avatar":""},{"name":"Charles Allen","avatar":""},{"name":"Veronica Neave","avatar":""},{"name":"Liam Olsen","avatar":""},{"name":"Joel Spreadborough","avatar":""},{"name":"Ann","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324310);
