INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-he', 'Mẫu Hệ', 'Matriarch', 'https://phimimg.com/upload/vod/20231102-1/d2a0744b26d291d1e8912ca7b1b9d7d3.jpg', 'https://phimimg.com/upload/vod/20231102-1/fac2df4ba9772cbb38abe35f7b56736f.jpg', '<p>Sau khi dùng thuốc quá liều gần như cướp đi mạng sống của cô, Laura Birch thoát khỏi áp lực quá cao của thế giới quảng cáo để trở về với cội nguồn của mình. Chấp nhận lời mời về nhà từ người mẹ ghẻ lạnh của mình, Laura hy vọng khoảng thời gian sống ở ngôi làng hẻo lánh ở Anh sẽ giúp xoa dịu những con quỷ đang hoành hành bên trong cô. Cô sớm phát hiện ra rằng những người dân địa phương trong thị trấn đều đang bảo vệ một bí mật đen tối không thể nói ra - một bí mật không chỉ liên quan đến mẹ cô mà còn cả số phận đáng sợ của chính cô.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jemima Rooper","avatar":""},{"name":"Kate Dickie","avatar":""},{"name":"Sarah Paul","avatar":""},{"name":"Nick Haverson","avatar":""},{"name":"Franc Ashman","avatar":""},{"name":"Anna Frost","avatar":""},{"name":"Keith David Bartlett","avatar":""},{"name":"Kathryn McGarr","avatar":""},{"name":"Simon Meacock","avatar":""},{"name":"Celinde Schoenmaker","avatar":""},{"name":"Phillipa Peak","avatar":""},{"name":"Natasha Thurrell","avatar":""},{"name":"Christina Cole","avatar":""},{"name":"Stephen DeRosa","avatar":""},{"name":"Kate Lynn Evans","avatar":""},{"name":"Clare Barrett","avatar":""},{"name":"Emm","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324310);
