INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-nhen', 'Đầu Nhện', 'Spiderhead', 'https://phimimg.com/upload/vod/20231101-1/9f507fd87141bd1fe861f3a169cb3fe5.jpg', 'https://phimimg.com/upload/vod/20231101-1/06317a087a31f244152230f13e60f2b5.jpg', '<p>Trong nhà tù tối tân, một tù nhân bắt đầu đặt câu hỏi về mục đích của loại thuốc kiểm soát cảm xúc mà anh đang thử nghiệm cho một thiên tài dược phẩm.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Hemsworth","avatar":""},{"name":"Miles Teller","avatar":""},{"name":"Jurnee Smollett","avatar":""},{"name":"Mark Paguio","avatar":""},{"name":"Tess Haubrich","avatar":""},{"name":"BeBe Bettencourt","avatar":""},{"name":"Nathan Jones","avatar":""},{"name":"Angie Milliken","avatar":""},{"name":"Ron Smyck","avatar":""},{"name":"Joey Vieira","avatar":""},{"name":"Sam Delich","avatar":""},{"name":"Daniel Reader","avatar":""},{"name":"Stephen Tongun","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324310);
