INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-nhen', 'Đầu Nhện', 'Spiderhead', 'đầu nhện spiderhead chris hemsworth miles teller jurnee smollett mark paguio tess haubrich bebe bettencourt nathan jones angie milliken ron smyck joey vieira sam delich daniel reader stephen tongun ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-phong-than-bang-duong-tien', 'Tân Phong Thần Bảng: Dương Tiễn', 'New Gods: Yang Jian', 'https://phimimg.com/upload/vod/20231101-1/d3797f7369df7d9622b7544a7d72985f.jpg', 'https://phimimg.com/upload/vod/20231101-1/3daa75aabd83ade335c5c5d9e2f1a44e.jpg', '<p>Mười ba năm sau khi Dương Tiễn giam cầm em gái của mình dưới một ngọn núi, vị thần quyền năng một thời giờ đã trở thành một thợ săn tiền thưởng không một xu dính túi. Khi một người phụ nữ bí ẩn thuê anh ta cho một công việc mới, Dương Tiễn nhanh chóng nhận ra mình đang đuổi theo một hình bóng quen thuộc. Anh ta phải ngăn đứa cháu trai thất lạc từ lâu của mình, người đang tìm kiếm chiếc lồng đèn hoa sen huyền diệu sẽ giải thoát cho mẹ y, ngay cả khi nó sẽ mang đến tai họa. Khi Dương Tiễn đối mặt với những hành động trong quá khứ của mình, anh ta phải đối mặt với một loạt cảnh giác nguy hiểm đang tìm kiếm cùng một kho báu với sức mạnh để thay đổi sự cân bằng của thế giới của họ.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kai Wang","avatar":""},{"name":"Ji Guanlin","avatar":""},{"name":"Lihong Li","avatar":""},{"name":"Lanling Li","avatar":""},{"name":"Yi Zhao","avatar":""},{"name":"Xiaoyu Liu","avatar":""},{"name":"Wen jingyuan","avatar":""},{"name":"Shuiyu Tang","avatar":""},{"name":"Xing Chao","avatar":""},{"name":"Qiu Qiu","avatar":""},{"name":"Yang Tianxiang","avatar":""},{"name":"Meng Yu","avatar":""},{"name":"Yang Mo","avatar":""},{"name":"Zhao Mingzhou","avatar":""},{"name":"Li Nan","avatar":""},{"name":"Lin Qiang","avatar":""},{"name":"Cong Liu","avatar":""},{"name":"Chen Jinwen","avatar":""},{"name":"Zhao Ji","avatar":""},{"name":"Hu Yajie","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324310);
