INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-an-cuoi-cung', 'Dấu Ấn Cuối Cùng', 'The Last Mark', 'https://phimimg.com/upload/vod/20231101-1/062a0af1ed21fb59bef7d920754a1bf5.jpg', 'https://phimimg.com/upload/vod/20231101-1/9d280d1d9b1aed81a8050362c7ffc90b.jpg', '<p>Sau khi một phụ nữ trẻ chứng kiến một đám đông bị tấn công, một sát thủ dày dạn kinh nghiệm và đối tác tâm thần của anh ta phải truy tìm cô ấy trước khi cô ấy bắt họ, nhưng cô ấy chứng tỏ là dấu hiệu khó giết nhất.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Alexia Fast","avatar":""},{"name":"Shawn Doyle","avatar":""},{"name":"Bryce Hodgson","avatar":""},{"name":"Josh Cruddas","avatar":""},{"name":"Jasmin Geljo","avatar":""},{"name":"Jonas Chernick","avatar":""},{"name":"Andre Richards","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324310);
