INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-tuoc-chien-ky', 'Chu Tước Chiến Kỷ', 'The Red Sparrow', 'https://phimimg.com/upload/vod/20231101-1/b2e549d62b7ec02a7fabff4cf8968cee.jpg', 'https://phimimg.com/upload/vod/20231101-1/b234a0c2ec39adf2fc40c972c97c49a2.jpg', '<p>Phim kể về nửa sau thế kỷ 21, một cuộc xung đột gay gắt nổ ra giữa con người và trí tuệ nhân tạo. Nữ chính Yi Ni (do Han Congcong thủ vai) đã đưa ra quyết định của số phận và dẫn dắt binh đoàn người máy phát động trận chiến quyết định với nhóm Ron hùng mạnh. câu chuyện. Yi Ni là một robot hình người được sinh ra trong &quot;Sự cố 2060&quot;, và là hy vọng duy nhất để ngăn chặn nhóm Ron chiếm lấy loài người. Cô lớn lên trên đường phố và trong chợ đen của người máy. Trong một cuộc xung đột tình cờ, cô bị nhóm Ron bắt giữ và biết được sự thật về kinh nghiệm sống của mình. Và chính những người máy sống sót sau &quot;Sự cố năm 2060&quot; đã giải cứu cô khỏi nanh vuốt. Kể từ đó, để ngăn chặn nhóm Ron cai trị hành vi điên rồ của loài người, Yi Ni dẫn đầu đội quân máy phát động cuộc phản diệt Jedi, và bắt đầu trận chiến thế kỷ với nhóm Ron về số phận của loài người, Yi Ni cũng hóa thân thành một siêu cường với hiệu quả chiến đấu vượt trội &quot;Dark Phoenix&quot;.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Han Congcong","avatar":""},{"name":"Jiang Zhenhao","avatar":""},{"name":"Shuxian Zheng","avatar":""},{"name":"Mei Aoxue","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324310);
