INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-gioi-the-thao-thang-tram-cua-and1', 'Bí mật giới thể thao: Thăng trầm của AND1', 'Untold: The Rise and Fall of AND1', 'https://phimimg.com/upload/vod/20231101-1/c7c97c988b0967062097676c4b7ec549.jpg', 'https://phimimg.com/upload/vod/20231101-1/1bd3ce34af92a8eff187432ba0e672a0.jpg', '<p>Lấy cảm hứng từ bóng rổ đường phố New York, thương hiệu có ảnh hưởng AND1 biến huyền thoại quốc gia trên sân đấu thành biểu tượng quốc tế. Vậy vì sao mọi chuyện kết thúc?</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324310);
