INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trick-or-treat-scoobydoo', 'Trick or Treat Scooby-Doo!', 'Trick or Treat Scooby-Doo!', 'https://phimimg.com/upload/vod/20231101-1/91a9cd6ad5676319abc8f7c8d9f53b30.jpg', 'https://phimimg.com/upload/vod/20231101-1/84ca6149e8819d074938e9976e43ad72.jpg', '<p>Mystery Inc. đã phá vỡ trường hợp này để đứng đầu tất cả các trường hợp! Họ đã lần ra Coco Diablo, người đứng đầu một tổ chức tội phạm hóa trang khét tiếng. Với Coco và mèo con của cô ấy trong tù, Mystery Inc. nghĩ rằng cuối cùng họ có thể tận hưởng thời gian nghỉ ngơi. Sai! Đột nhiên, những bóng ma doppelgänger đe dọa của phi hành đoàn Scooby và những kẻ thù cổ điển yêu thích xuất hiện ở Coolsville để đe dọa Halloween. Bây giờ, những đứa trẻ hay can thiệp phải vạch mặt tên vô lại mới nhất và cứu Halloween!</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Frank Welker","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Matthew Lillard","avatar":""},{"name":"Kate Micucci","avatar":""},{"name":"Myrna Velasco","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Anthony Carrigan","avatar":""},{"name":"Erin Fitzgerald","avatar":""},{"name":"David Lodge","avatar":""},{"name":"Lara Jill Miller","avatar":""},{"name":"Candi Milo","avatar":""},{"name":"Jenelle Lynn Randall","avatar":""},{"name":"Kevin Michael Richardson","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia