INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-mo-me-anh', 'Hồ Mộ Mê Ảnh', 'Fox tomb shadow', 'null', 'https://phimimg.com/upload/vod/20231101-1/667e90999770a261786b8ac0ffe41f4c.jpg', '<p>A Sinh hậu duệ của Mô Kim Giáo Úy, mắc chứng bệnh di truyền, hai năm sau khi cha anh rời khỏi nhà một cách bí ẩn, anh tình cờ tìm thấy một cục vàng được giấu trong nhà. Dựa trên những manh mối ở trên, anh đến Cẩm thành và làm quen kết bạn với hai người bạn là Bạch Xuân Thành và Bạch Liễu. Ba người họ bắt đầu chuyến phiêu lưu tìm kiếm kho báu của Hoàng đế Bạch Hồ. Trong khoảng thời gian này, họ gặp Tân Điền, một học giả cũng đang bí mật tìm kiếm kho báu, và cũng gặp Kim Tam, Xích Hồ - người đem đến phiền phức cho A Sinh và những người khác. Họ rơi vào nhiều cạm bẫy và nguy hiểm khác nhau. Một trận chiến lớn với Tân Điền và Xích Hồ đã diễn ra. Tuy nhiên, với kỹ năng của mình khi là con cháu của Mô Kim, A Sinh và những người bạn đã đánh bại được bọn gian ác.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Owodog Chuang","avatar":""},{"name":"Li Shuinuo","avatar":""},{"name":"Ye Yan","avatar":""},{"name":"Li Hongtao","avatar":""},{"name":"Jing Xingyao","avatar":""},{"name":"Yu Liwen","avatar":""},{"name":"Chen Xuming","avatar":""}]', '[]', '[]', 1784690324310);
