INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-linh', 'Liều Lĩnh', 'Overdose', 'https://phimimg.com/upload/vod/20231029-1/7898d1238f127a61f70229c029dec440.jpg', 'https://phimimg.com/upload/vod/20231029-1/fa5fe234d17b69b68dac17287a1f5436.jpg', '<p>Đại úy Sara Bellaiche, từ chi nhánh Cảnh sát Tư pháp Toulouse, đang điều tra nhanh chóng liên quan đến vụ sát hại hai thanh thiếu niên, một cuộc điều tra do Richard Cross, từ Đội hình sự Paris dẫn đầu. Bị buộc phải hợp tác để tìm ra kẻ sát nhân và ngăn chặn cuộc đua xe đẫm máu, Sara và Richard đều bị ném vào một cuộc đua nghẹt thở với đồng hồ trên đường của Tây Ban Nha và Pháp.</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Sofia Essaïdi","avatar":""},{"name":"Assaad Bouab","avatar":""},{"name":"Alberto Ammann","avatar":""},{"name":"Nicolas Cazalé","avatar":""},{"name":"Nassim Lyes","avatar":""},{"name":"Naïma Rodric","avatar":""},{"name":"Kool Shen","avatar":""},{"name":"Moussa Mansaly","avatar":""},{"name":"Simon Abkarian","avatar":""},{"name":"Zoé Marchal","avatar":""},{"name":"Kenza Fortas","avatar":""},{"name":"Francis Renaud","avatar":""},{"name":"Salem Kali","avatar":""},{"name":"Daniel Girondeaud","avatar":""},{"name":"Frédéric Guérin","avatar":""},{"name":"Julie Chevallier","avatar":""},{"name":"Jean Pierre Hor","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324311);
