INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-ngay-giang-sinh', 'Linh Hồn Ngày Giáng Sinh', 'Spirited', 'https://phimimg.com/upload/vod/20231029-1/b8574ef260b2a3d7748a654aa76486e0.jpg', 'https://phimimg.com/upload/vod/20231029-1/883396d9628b44400ee5d9f6b25e0dc8.jpg', '<p>Hãy hình dung câu chuyện cảm động của Charles Dickens về một ông già keo kiệt bị bốn hồn ma ghé thăm vào đêm Giáng sinh - nhưng hài hước hơn. Và với dàn sao Will Ferrell, Ryan Reynold và Octavia Spencer. Ngoài ra, còn những màn ca hát hoành tráng nữa. Hình dung thế có vẻ nhiều phết đấy. Hay là mời các bạn xem luôn trailer nhé?</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Ferrell","avatar":""},{"name":"Ryan Reynolds","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Patrick Page","avatar":""},{"name":"Sunita Mani","avatar":""},{"name":"Loren G. Woods","avatar":""},{"name":"Tracy Morgan","avatar":""},{"name":"Joe Tippett","avatar":""},{"name":"Marlow Barkley","avatar":""},{"name":"Aimee Carrero","avatar":""},{"name":"Andrea Anders","avatar":""},{"name":"Jen Tullock","avatar":""},{"name":"Adam Grupper","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Matt Cardenes","avatar":""},{"name":"Ava Bernstine","avatar":""},{"name":"Charlene Anders","avatar":""},{"name":"Naheem","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324311);
