INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ten-ta-la-tu-thu', 'Tên Ta Là Tử Thù', 'My Name Is Vendetta', 'https://phimimg.com/upload/vod/20231022-1/ef106f180508f7de3841473500cff3eb.jpg', 'https://phimimg.com/upload/vod/20231022-1/ce553a4cf6c947be2cf7beb6dcc5c682.jpg', '<p>Khi kẻ thù trong quá khứ giết vợ và anh vợ của anh, một cựu tay sai mafia cùng con gái chạy trốn đến Milan để lên kế hoạch trả thù.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Alessandro Gassmann","avatar":""},{"name":"Ginevra Francesconi","avatar":""},{"name":"Remo Girone","avatar":""},{"name":"Alessio Praticò","avatar":""},{"name":"Francesco Villano","avatar":""},{"name":"Gabriele Falsetta","avatar":""},{"name":"Marcello Mazzarella","avatar":""},{"name":"Mauro Lamanna","avatar":""},{"name":"Sinja Dieks","avatar":""},{"name":"Luca Zamperoni","avatar":""},{"name":"Isnaba Na Montche","avatar":""},{"name":"Marco Boriero","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324311);
