INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-thi-cong-ly', 'Thực Thi Công Lý', 'The Enforcer', 'https://phimimg.com/upload/vod/20231022-1/1e58b088054ff1d0049455893adee25b.jpg', 'https://phimimg.com/upload/vod/20231022-1/6feab0895d7e824c36242c7dbe128706.jpg', '<p>Cuda (Antonio Banderas), kẻ thực thi tội phạm hàng đầu của Miami, hy sinh tất cả để phá bỏ tổ chức tội phạm mà anh ta đã dành cả cuộc đời để gây dựng khi phát hiện ra ông chủ của mình là Estelle (Kate Bosworth) đang đặt cuộc sống của một kẻ bỏ trốn trẻ tuổi vào nguy hiểm nghiêm trọng. Giờ đây, anh ấy có một cơ hội cuối cùng để bù đắp lại quá khứ của mình và tìm sự chuộc lỗi - cho cả bản thân và gia đình - trước khi đám đông truy lùng anh ấy vì sự phản bội của anh ấy.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Antonio Banderas","avatar":""},{"name":"Kate Bosworth","avatar":""},{"name":"Mojean Aria","avatar":""},{"name":"Alexis Ren","avatar":""},{"name":"Zolee Griggs","avatar":""},{"name":"2 Chainz","avatar":""},{"name":"Aaron Cohen","avatar":""},{"name":"Natalie Burn","avatar":""},{"name":"Mark Rhino Smith","avatar":""},{"name":"Luke Bouchier","avatar":""},{"name":"Kika Georgiou","avatar":""},{"name":"Kostas Sommer","avatar":""},{"name":"Christos Vasilopoulos","avatar":""},{"name":"Vivian Milkova","avatar":""},{"name":"Lucia McKinstry Calvo","avatar":""},{"name":"Eleftheria Giovanaki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324311);
