INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lyle-chu-ca-sau-biet-hat', 'Lyle, Chú Cá Sấu Biết Hát', 'Lyle, Lyle, Crocodile', 'https://phimimg.com/upload/vod/20231022-1/5f6f4d8158a0ce69781327343c1a8506.jpg', 'https://phimimg.com/upload/vod/20231022-1/565fafc6da41be3bf37bdc7f878f2064.jpg', '<p>Khi gia đình Primm chuyển đến thành phố New York, cậu con trai nhỏ Josh gặp khó khăn trong việc thích nghi với ngôi trường và những người bạn mới. Mọi thứ thay đổi khi cậu bé phát hiện ra ra Lyle - một chàng cá sấu mê tắm rửa, trứng cá muối và âm nhạc sống trên gác mái của của mình. Hai người nhanh chóng trở thành bạn bè. Thế nhưng, khi cuộc sống của Lyle bị ông hàng xóm Grumps đe dọa, gia đình Primm buộc phải kết hợp với ông chủ cũ của Lyle là Hector P. Valenti (Javier Bardem) để cho cả thế giới thấy giá trị tình thân và sự kỳ diệu của một chàng cá sấu biết hát.</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Shawn Mendes","avatar":""},{"name":"Javier Bardem","avatar":""},{"name":"Winslow Fegley","avatar":""},{"name":"Constance Wu","avatar":""},{"name":"Scoot McNairy","avatar":""},{"name":"Brett Gelman","avatar":""},{"name":"Ego Nwodim","avatar":""},{"name":"Lyric Hurd","avatar":""},{"name":"Jason Kravits","avatar":""},{"name":"Ben Palacios","avatar":""},{"name":"Joshua Vasquez","avatar":""},{"name":"Marc Farley","avatar":""},{"name":"Sal Viscuso","avatar":""},{"name":"Adam Murray","avatar":""},{"name":"Mary Neely","avatar":""},{"name":"Don DiPetta","avatar":""},{"name":"Lindsey Moser","avatar":""},{"name":"Matthew Risch","avatar":""},{"name":"Clay","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324311);
