INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-o-vien-bao-tang-kahmunrah-troi-day', 'Đêm Ở Viện Bảo Tàng: Kahmunrah Trỗi Dậy', 'Night at the Museum: Kahmunrah Rises Again', 'https://phimimg.com/upload/vod/20231023-1/17478f973d7e5e41eac680ab2ff6972c.jpg', 'https://phimimg.com/upload/vod/20231023-1/c0fc82fa926b43fc2d9d6fa19115494b.jpg', '<p>Nick Daley đang theo bước cha mình làm người gác đêm tại Bảo tàng Lịch sử Tự nhiên Hoa Kỳ, vì vậy anh biết điều gì sẽ xảy ra khi mặt trời lặn. Nhưng khi kẻ thống trị điên cuồng Kahmunrah trốn thoát, Nick phải một lần cứu được bảo tàng và cho tất cả.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joshua Bassett","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Joseph Kamal","avatar":""},{"name":"Akmal Saleh","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Jack Whitehall","avatar":""},{"name":"Kieran Sequoia","avatar":""},{"name":"Alice Isaaz","avatar":""},{"name":"Jamie Demetriou","avatar":""},{"name":"Zachary Levi","avatar":""},{"name":"Gillian Jacobs","avatar":""},{"name":"Alexander Salamat","avatar":""},{"name":"Shelby Simmons","avatar":""},{"name":"Lidia Porto","avatar":""},{"name":"Tenzing Norgay Trainor","avatar":""},{"name":"Bowen Yang","avatar":""},{"name":"Chris Par","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324311);
