INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-co-nam-nang-dau-ban-dien-anh', 'Nhà Có Năm Nàng Dâu: Bản Điện Ảnh', 'The Quintessential Quintuplets Movie', 'https://phimimg.com/upload/vod/20231022-1/5b0ef99ae4b40f51b4cbb87c3a793b44.jpg', 'https://phimimg.com/upload/vod/20231022-1/925f353d0214d84412604b98d49cb561.jpg', '<p>Khi năm cô gái trẻ đáng yêu ghét học tập thuê gia sư bán thời gian Futaro, anh không chỉ hướng dẫn họ về việc học mà còn cả trái tim của họ. Thời gian trôi qua đã đưa họ đến gần nhau hơn, tình cảm ngày càng lớn dần trong các cô gái và Futaro. Khi học xong năm thứ ba trung học và lễ hội trường cuối cùng sắp đến gần, họ đặt mục tiêu vào những gì tiếp theo. Liệu có tương lai giữa một trong số họ và Futaro không?</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Miku Ito","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Natsumi Takamori","avatar":""},{"name":"Satoshi Hino","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324311);
