INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-bong-da', 'Giải Cứu Bóng Đá', 'The Soccer Football Movie', 'https://phimimg.com/upload/vod/20231023-1/4fe31a330b50581a6d0c3660aec15f29.jpg', 'https://phimimg.com/upload/vod/20231023-1/56e80a3c793c1a1b8f0adfc39eee0215.jpg', '<p>Bốn cô cậu mê bóng đá cùng hợp sức giúp các thần tượng của mình giành lại năng lực sau khi một nhà khoa học xấu xa và mưu mô đánh cắp tài năng của họ.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zlatan Ibrahimović","avatar":""},{"name":"Megan Rapinoe","avatar":""},{"name":"''Weird Al'' Yankovic","avatar":""},{"name":"Rob Stone","avatar":""},{"name":"Kieran Walton","avatar":""},{"name":"Madison Zamor","avatar":""},{"name":"Tania Gunadi","avatar":""},{"name":"Arnie Pantoja","avatar":""},{"name":"Ian James Corlett","avatar":""},{"name":"Tom Kenny","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Deeki Deke","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324311);
