INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-xuyen-khong', 'Cuộc Chiến Xuyên Không', 'Alienoid', 'https://phimimg.com/upload/vod/20231022-1/89393d82c4540750636121a632578a9e.jpg', 'https://phimimg.com/upload/vod/20231022-1/c366043a1809dd0bc5bb2859555376fa.jpg', '<p>Năm 2022, hai người ngoài hành tinh là Guard (Kim Woo-bin) và Thunder sinh sống tại Trái Đất đang tìm kiếm những tù nhân vượt ngục, vốn bị họ giam giữ trong cơ thể con người. Cảnh sát Moon (So Ji-sub) vô tình trở thành đối tượng bị truy đuổi mà không rõ lý do. Cùng lúc đó, ở triều đại Goryeo hơn 630 năm về trước, pháp sư xui xẻo Muruk (Ryu Jun-yeol) và “cô gái bắn sấm sét” Ean (Kim Tae-ri) đang cố gắng tranh giành một thanh gươm thần huyền thoại. Cuộc chiến khốc liệt ấy còn có sự tham gia của hai phù thủy hắc ám là Madam Black (Yum Jung-ah) và Mr. Blue (Jo Woo-Jin), cùng kẻ đeo mặt nạ bí ẩn Jajang (Kim Eui-sung). Một cánh cổng thời gian xuất hiện và mở ra sự kết nối giữa hai thời đại, tạo nên tình huống hỗn loạn chưa từng thấy</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ryu Jun-yeol","avatar":""},{"name":"Kim Woo-bin","avatar":""},{"name":"Kim Tae-ri","avatar":""},{"name":"Choi Yu-ri","avatar":""},{"name":"So Ji-sub","avatar":""},{"name":"Yum Jung-ah","avatar":""},{"name":"Jo Woo-jin","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Lee Ha-nee","avatar":""},{"name":"Shin Jung-geun","avatar":""},{"name":"Lee Si-hoon","avatar":""},{"name":"Kim Dae-myung","avatar":""},{"name":"Kim Ki-chun","avatar":""},{"name":"Yoon Byung-hee","avatar":""},{"name":"Yoon Kyung-ho","avatar":""},{"name":"Ok Ja-yeon","avatar":""},{"name":"Lee Hyun-geol","avatar":""},{"name":"Kim Hae-sook","avatar":""},{"name":"Yoo Jae-myung","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324311);
