INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-co-the', 'Trò Chơi Cơ Thể', 'Bodies Bodies Bodies', 'https://phimimg.com/upload/vod/20231021-1/d49f96b748b40dc025851409f254ab95.jpg', 'https://phimimg.com/upload/vod/20231021-1/77c1cdbe2f9e5bd7a25cba9c63dc2752.jpg', '<p>Trong một biệt thự của một gia đình biệt lập, một nhóm 20 người giàu có quyết định chơi Bodies Bodies, một trò chơi mà một trong số họ bí mật là “kẻ giết người” trong khi những người còn lại cố gắng “trốn thoát”. Mọi thứ trở nên tồi tệ hơn khi các cơ thể thực sự bắt đầu hoạt động, gây ra một chuỗi sự kiện hoang tưởng và nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amandla Stenberg","avatar":""},{"name":"Maria Bakalova","avatar":""},{"name":"Rachel Sennott","avatar":""},{"name":"Chase Sui Wonders","avatar":""},{"name":"Myha''la Herrold","avatar":""},{"name":"Pete Davidson","avatar":""},{"name":"Lee Pace","avatar":""},{"name":"Conner O''Malley","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324311);
