INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('halloween-cham-dut', 'Halloween Chấm Dứt', 'Halloween Ends', 'https://phimimg.com/upload/vod/20231018-1/8ff4adbdc23496838c7eff86782ca3b1.jpg', 'https://phimimg.com/upload/vod/20231018-1/b4bbcbd4652bdad8e1bf19685f6593ec.jpg', '<p>Bốn năm sau sự kiện Halloween năm 2018, Laurie đã quyết định giải phóng bản thân khỏi nỗi sợ hãi và thịnh nộ để đón nhận cuộc sống. Nhưng khi một chàng trai trẻ bị buộc tội giết một cậu bé mà anh ta đang trông trẻ, nó đã gây ra một làn sóng bạo lực và khủng bố buộc Laurie cuối cùng phải đối đầu với cái ác mà cô không thể kiểm soát, một lần và mãi mãi.</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jamie Lee Curtis","avatar":""},{"name":"Andi Matichak","avatar":""},{"name":"Rohan Campbell","avatar":""},{"name":"Will Patton","avatar":""},{"name":"James Jude Courtney","avatar":""},{"name":"Kyle Richards","avatar":""},{"name":"Omar Dorsey","avatar":""},{"name":"Jesse C. Boyd","avatar":""},{"name":"Joanne Baron","avatar":""},{"name":"Rick Moose","avatar":""},{"name":"Michael Barbieri","avatar":""},{"name":"Destiny Mone","avatar":""},{"name":"Joey Harris","avatar":""},{"name":"Marteen","avatar":""},{"name":"Michael O''Leary","avatar":""},{"name":"Michele Dawson","avatar":""},{"name":"Keraun Harr","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324311);
