INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-lang-thang-2', 'Ma Lang Thang 2', 'Hocus Pocus 2', 'https://phimimg.com/upload/vod/20231018-1/d385c42f52d1a081e99cd79da0d55c4e.jpg', 'https://phimimg.com/upload/vod/20231018-1/cf160bb130f1b232c507cfae72f50053.jpg', '<p>Sau các sự kiện của phần đầu tiên, Ba cô gái trẻ vô tình triệu hồi chị em nhà phù thủy Sanderson, mở đường cho họ bước vào thế giới hiện đại. Những nối ám ảnh và sợ hãi cũng vì thế tăng lên và bằng mọi cách, các cô gái phải ngăn chặn họ trước khi trẻ em gặp nguy hiểm</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bette Midler","avatar":""},{"name":"Sarah Jessica Parker","avatar":""},{"name":"Kathy Najimy","avatar":""},{"name":"Whitney Peak","avatar":""},{"name":"Belissa Escobedo","avatar":""},{"name":"Lilia Buckingham","avatar":""},{"name":"Froy Gutierrez","avatar":""},{"name":"Sam Richardson","avatar":""},{"name":"Doug Jones","avatar":""},{"name":"Tony Hale","avatar":""},{"name":"Hannah Waddingham","avatar":""},{"name":"Taylor Henderson","avatar":""},{"name":"Nina Kitchen","avatar":""},{"name":"Juju Journey Brener","avatar":""},{"name":"Thomas Fitzgerald","avatar":""},{"name":"Brett Cra","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324311);
