INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-vat-huyen-bi-nhung-bi-mat-cua-dumbledore', 'Sinh Vật Huyền Bí: Những Bí Mật của Dumbledore', 'Fantastic Beasts: The Secrets of Dumbledore', 'https://phimimg.com/upload/vod/20231018-1/d52c043fc4f86a27ccf5216c35a1ff4d.jpg', 'https://phimimg.com/upload/vod/20231018-1/cf53f7bd7df83d2e9dd0d0f43e071cf5.jpg', '<p>Câu chuyện của phần phim thứ ba này xoay quanh việc Giáo sư Albus Dumbledore (Jude Law) phát hiện ra việc Phù thủy Bóng tối quyền năng Gellert Grindelwald (Mads Mikkelsen) đang âm mưu chiếm lấy quyền kiểm soát Thế giới Phù thủy. Không thể một mình ngăn chặn đoàn quân hùng mạnh của của Grindelwald, Dumbledore đặt niềm tin vào Nhà nghiên cứu sinh vật huyền bí Newt Scamander (Eddie Redmayne) cùng đồng đội thực hiện nhiệm vụ đầy hiểm nguy này. Trong tình thế ngàn cân treo sợi tóc như vậy, liệu thầy Dumbledore có thể đứng ngoài được bao lâu?</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Eddie Redmayne","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Mads Mikkelsen","avatar":""},{"name":"Ezra Miller","avatar":""},{"name":"Dan Fogler","avatar":""},{"name":"Alison Sudol","avatar":""},{"name":"Callum Turner","avatar":""},{"name":"Jessica Williams","avatar":""},{"name":"Katherine Waterston","avatar":""},{"name":"Oliver Masucci","avatar":""},{"name":"Richard Coyle","avatar":""},{"name":"William Nadylam","avatar":""},{"name":"Maria Fernanda Cândido","avatar":""},{"name":"Poppy Corby-Tuech","avatar":""},{"name":"Victoria Yeates","avatar":""},{"name":"Aleksandr Ku","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":