INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tru-ta-cua-chua', 'Sự Trừ Tà Của Chúa', 'The Exorcism of God', 'https://phimimg.com/upload/vod/20231017-1/f4e67358ad1cb4fd287d9aa12ed40aac.jpg', 'https://phimimg.com/upload/vod/20231017-1/76ddaaa76e9e498fcdc9d325d09782e6.jpg', '<p>Một linh mục người Mỹ làm việc tại Mexico được nhiều giáo dân địa phương coi là một vị thánh. Tuy nhiên, do một phép trừ tà bất thành, anh ta mang theo một bí mật đang ăn tươi nuốt sống anh ta cho đến khi anh ta có cơ hội đối mặt với con quỷ của mình lần cuối cùng.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Will Beinbrink","avatar":""},{"name":"María Gabriela de Faría","avatar":""},{"name":"Irán Castillo","avatar":""},{"name":"Joseph Marcell","avatar":""},{"name":"Hector Kotsifakis","avatar":""},{"name":"Juan Ignacio Aranda","avatar":""},{"name":"Evelia Di Gennaro","avatar":""},{"name":"Raquel Rojas","avatar":""},{"name":"Nuria Gil","avatar":""},{"name":"Jesse Celedon","avatar":""},{"name":"María Antonieta Hidalgo","avatar":""},{"name":"Simona Chirinos","avatar":""},{"name":"Eloísa Maturén","avatar":""},{"name":"Alfredo Herrera","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324311);
