INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-thu-vo-hinh-san-moi', 'Quái Thú Vô Hình: Săn Mồi', 'Prey', 'https://phimimg.com/upload/vod/20231017-1/55dcab2d4ba72f1d03e7b3df6b02fd33.jpg', 'https://phimimg.com/upload/vod/20231017-1/db67d111c984b7376b9ecb9de5bae22b.jpg', '<p>Lấy bối cảnh 300 trước tại vùng đồng bằng Nam Hoa Kỳ. Tại đây, một sinh vật ngoại lai đến từ ngoài vũ trụ đổ bộ xuống Trái Đất đe dọa cuộc sống của một bộ tộc cổ xưa. Naru, một nữ chiến binh lành nghề, phải dùng mọi kỹ năng của mình để tồn tại cũng như bảo vệ ngôi làng trước mối hiểm họa mà cô chưa từng hiểu biết</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amber Midthunder","avatar":""},{"name":"Dakota Beavers","avatar":""},{"name":"Michelle Thrush","avatar":""},{"name":"Stormee Kipp","avatar":""},{"name":"Julian Black Antelope","avatar":""},{"name":"Dane DiLiegro","avatar":""},{"name":"Stefany Mathias","avatar":""},{"name":"Bennett Taylor","avatar":""},{"name":"Mike Paterson","avatar":""},{"name":"Nelson Leis","avatar":""},{"name":"Tymon Carter","avatar":""},{"name":"Skye Pelletier","avatar":""},{"name":"Harlan Blayne Kytwayhat","avatar":""},{"name":"Corvin Mack","avatar":""},{"name":"Samuel Marty","avatar":""},{"name":"Ginger Ca","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324311);
