INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-san-soi', 'Kế Hoạch Săn Sói', 'Project Wolf Hunting', 'https://phimimg.com/upload/vod/20231018-1/2100d32262f585eac60bf97fb41544e2.jpg', 'https://phimimg.com/upload/vod/20231018-1/851ecc039c65c3487b83f0471c23043d.jpg', '<p>Frontier Titan là một chiếc lồng to lớn được chuyển đến Philippines để đưa dẫn những tên tội phạm đang lẩn trốn ở Đông Nam Á về lại Hàn Quốc. Họ là những tên tội phạm cực kỳ hung ác đang tập trung tại cảng Manila ở Philippines để lên thuyền và tới Hàn Quốc. Jong Doo (do Seo In Guk thủ vai đang lên kế hoạch để trốn thoát, và Do Il (do Jang Dong Yoon thủ vai) đang trên đường trở về lại Hàn Quốc. Con tàu xuất phát, họ trở nên lo lắng và cẩn trọng hơn. Trên đường đến Hàn Quốc, ở Thái Bình Dương họ gặp phải những điều kiện khắc nghiệt mà chưa từng thấy trước đây … Địa ngục ở Thái Bình Dương, ai sẽ sống sót?</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Seo In-guk","avatar":""},{"name":"Jang Dong-yoon","avatar":""},{"name":"Park Ho-san","avatar":""},{"name":"Jung So-min","avatar":""},{"name":"Ko Chang-seok","avatar":""},{"name":"Jang Young-nam","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Son Jong-hak","avatar":""},{"name":"Lee Sung-wook","avatar":""},{"name":"Hong Ji-yoon","avatar":""},{"name":"Choi Gwi-hwa","avatar":""},{"name":"Jung Moon-sung","avatar":""},{"name":"Lim Ju-hwan","avatar":""},{"name":"Kim Kang-hoon","avatar":""},{"name":"Kim Moon-hak","avatar":""},{"name":"Kim Chan-hyung","avatar":""},{"name":"Kang Shin-chul","avatar":""},{"name":"Ahn Ji-hy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},