INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-loi-thoat-2022', 'Không Lối Thoát', 'No Exit', 'https://phimimg.com/upload/vod/20230926-1/ca5b0d62b8ad5c5cdd28903d5fd24624.jpg', 'https://phimimg.com/upload/vod/20230926-1/7cf72d01a7b2a25e8459891c0f85e712.jpg', '<p>Bị mắc kẹt tại trạm nghỉ trên núi trong trận bão tuyết, một người nghiện đang hồi phục phát hiện ra một đứa trẻ bị bắt cóc giấu trong một chiếc ô tô của một trong những người bên trong tòa nhà, khiến cô phải đấu tranh kinh hoàng để xác định ai trong số họ là kẻ bắt cóc.</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Havana Rose Liu","avatar":""},{"name":"Danny Ramirez","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"David Rysdahl","avatar":""},{"name":"Dale Dickey","avatar":""},{"name":"Mila Harris","avatar":""},{"name":"Benedict Wall","avatar":""},{"name":"James Gaylyn","avatar":""},{"name":"Lisa Zhang","avatar":""},{"name":"Nick Davies","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324311);
