INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-hang-dong-tan-linh', 'Bí Mật Hang Động Tần Lĩnh', 'Qinling Mountains', 'https://phimimg.com/upload/vod/20231014-1/9fefb866d9bed47b02ebd17b2ed69764.jpg', 'https://phimimg.com/upload/vod/20231014-1/bc6c1222963bec64ff449f8bf7a1537c.jpg', '<p>Nhân vật chính Tề Tương Văn bị trùm xã hội đen Trương Thần Nhãn đe dọa. Anh đóng giả là một thành viên của Cục địa chất và lừa giáo sư Hồ, mở hang động bí mật từ di tích cổ trên dãy núi Tần Lĩnh để đánh cắp kho báu. Trong quá trình thăm dò, chỉ có Tề Tương Văn quay trở lại, và được em gái của La Cẩm là La Hân chữa trị. Tuy nhiên, chấn thương trên đầu của anh ấy đã dẫn đến chứng mất trí nhớ. Khi bọn xã hội đen và nhện đột biến tấn công ngôi làng anh đang ở, anh đã giải cứu ngôi làng và trở thành anh hùng trong mắt dân làng. Khi anh cùng đội tìm kiếm và cứu hộ tiến vào hang động bí mật lần nữa, trí nhớ của anh dần phục hồi. Giữa thiện và ác, anh đã lựa chọn cùng đội tìm kiếm cứu hộ chiến đấu chống lại băng đảng xã hội đen, và cuối cùng đã hy sinh bản thân để cứu mọi người...</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Weizhou","avatar":""},{"name":"Shi Xuanru","avatar":""},{"name":"Wang Hongqian","avatar":""},{"name":"Wu Hao","avatar":""},{"name":"Alan Chen","avatar":""},{"name":"Miao Qing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324311);
