INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-lai-long-quan-kho-bau-tu-phuc', 'Bồng Lai Long Quan : Kho Báu Từ Phúc', 'Xu Fu Treasure', 'https://phimimg.com/upload/vod/20231014-1/6b1a115b37c273d1a4a7063638017c14.jpg', 'https://phimimg.com/upload/vod/20231014-1/15a7cab7ff6fbf13a2d9ce459935a4ca.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Dựa trên câu chuyện của Xu Fu Dongdu trong các ghi chép lịch sử và văn hóa dân gian, bộ phim này kể về câu chuyện của các nhà thám hiểm thời Trung Hoa Dân Quốc đã tìm kiếm kho báu Xu Fu huyền thoại trên đảo Bồng Lai, và loại bỏ gián điệp Nhật Bản để bảo vệ kho báu Trung Quốc. Bộ phim này tạo ra hình ảnh của một nhà thám hiểm Trung Quốc chính trực và đầy cảm hứng, người rời khỏi quân đội và trở thành một nhà thám hiểm vì anh ta ghê tởm cuộc cận chiến của lãnh chúa, và hoa hồng anh ta nhận được mỗi lần được chia cho những người lính tàn tật, cũng như âm mưu quan trọng mà anh ta thà chết cùng nhau còn hơn để kho báu Trung Quốc rơi vào tay kẻ thù. Trong phim, đặc vụ Nhật Bản Yoshioka chiếm giữ kho báu của Trung Quốc để phục vụ cuộc xâm lược, và hành vi phạm tội của những kẻ xâm lược được phơi bày rõ ràng. Cái kết bi thảm của con gái lãnh chúa, Jinna, người săn tìm kho báu để giúp cha mình thoát khỏi sự kiểm soát của Nhật Bản, và cuối cùng chết cùng với Yoshioka cũng tiết lộ sự thật lịch sử rằng cận chiến lãnh chúa thực sự là một cuộc chiến ủy nhiệm của các cường quốc.</span></p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Eric Suen","avatar":""},{"name":"Feier Han","avatar":""},{"name":"Xu Jingwen","avatar":""},{"name":"Xu Zhanwei","avatar":""},{"name":"Liu Dongli","avatar":""},{"name":"Li Zitian","avatar":""},{"name":"Yucheng Cao","avatar":""},{"name":"Zhu Tingbei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324311);
