INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-dao-mau-hong-va-dai-mien-vuong-2', 'Anh Đào Màu Hồng và Đại Miên Vương 2', 'Why Women Cheat Part 2', 'null', 'https://phimimg.com/upload/vod/20231013-1/dabf326dc50adfac8ba82d46803a2871.jpg', '<p>Nam chính là vua của một đảo quốc nhỏ, anh từng bị nữ chính làm tổn thương sâu sắc. Nữ chính có một chiếc răng khểnh, lúc cười lên vô cùng quyến rũ. Sau khi nữ chính biến mất, nam chính trở nên cực kỳ thích ngủ vì không muốn nhớ gì đến nữ chính. Một cách tình cờ, cuối cùng anh lại lấy nữ chính, anh quyết định phải hành hạ cô gái bề ngoài đáng yêu nhưng lại có hành vi đáng ghét này cho thỏa.</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Deng Kai","avatar":""},{"name":"Yao Xiaoxiao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324311);
