INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-hiep-nghia', 'Anh Hùng Hiệp Nghĩa', 'Hero', 'null', 'https://phimimg.com/upload/vod/20231013-1/ef3070723de2591d4427f5a67653c332.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Chiếc máy bay docent (do Wang Zirui thủ vai) và đội trưởng an ninh Haozi (do Sun Hao thủ vai) của nhà tưởng niệm bất ngờ gặp phải những tên trộm Giang Dương vào đêm trước khi giám tuyển học viện để đánh cắp kho báu của sân thị trấn &quot;Núi cao và nước chảy&quot;. Trong cuộc tranh giành giữa thiện và ác, anh tình cờ gặp phải cõi giả tưởng &quot;nguyệt thực&quot;, mở ra một cuộc hành trình tuyệt vời qua triều đại nhà Minh thông qua việc thiết lập lại thời gian liên tục. Trong hành trình gian nan để phá vỡ thiết lập lại, Máy bay và Haozi tham gia vào cuộc tranh chấp sinh tử giữa Xu Wuqiang (do Zhang Ge), một bộ trưởng trung thành và quan trọng của triều đại nhà Minh, và nhóm thiến của Liu Jin, tận mắt chứng kiến lịch sử đầy biến động đó, và cả hai có sự hiểu biết sâu sắc hơn về tình cảm gia đình và đất nước và tình anh em.</span></p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Zirui","avatar":""},{"name":"Sun Hao","avatar":""},{"name":"Liu Yuqiao","avatar":""},{"name":"Zhang Ge","avatar":""},{"name":"Yang Shufeng","avatar":""},{"name":"Thiệu Tông","avatar":""},{"name":"Trương Vũ Long","avatar":""},{"name":"Yabu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324311);
