INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-den-roi', 'Ba Đến Rồi', 'Dad Is Here', 'null', 'https://phimimg.com/upload/vod/20231013-1/838faa9d376a80d032d17b4579dfd2be.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Bộ phim kể về câu chuyện của một người cha &quot;không đáng tin cậy&quot; mâu thuẫn và một cô con gái &quot;siêu nghiêm túc&quot; sau khi vô tình hoán đổi cơ thể do một tờ vé số ma thuật. Người cha xã hội đen &quot;thay đổi&quot; con gái trở về tuổi trẻ và náo loạn trường học, còn con gái của học sinh &quot;thay đổi&quot; người cha để sửa chữa con hẻm. Họ thực sự gần gũi với nhau trong cuộc sống không đúng chỗ đáng xấu hổ và vui nhộn này, đó là một &quot;cô con gái đáng tự hào&quot; và một &quot;người cha thất bại&quot; để làm hòa, buông bỏ nhau và suy ngẫm về bản thân.</span></p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhou Xiaoou","avatar":""},{"name":"Sato Rei","avatar":""},{"name":"Huang Cailun Huang","avatar":""},{"name":"Yin Fei","avatar":""},{"name":"Deng Zeming","avatar":""},{"name":"Lý Đồng","avatar":""},{"name":"Đại Đông Chu","avatar":""},{"name":"Trương Cương","avatar":""},{"name":"Zeng Shuyan","avatar":""},{"name":"Pan Yue và Yuetong Pan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324311);
