INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-la-tran-long-van', 'Chuyện Lạ Trấn Long Vân', 'The Mysterious Story of Longyun Town', 'https://phimimg.com/upload/vod/20231012-1/9f4db6ea143148eb0a6f12c18e0865cc.jpg', 'https://phimimg.com/upload/vod/20231012-1/e13ee86cd36fae84175cafed21842536.jpg', '<p>Những năm đầu Dân Quốc, chiến tranh khắp nơi, dân chúng lầm than. Câu chuyện xảy ra ở trấn Long Vân. Theo truyền thuyết, sau khi một kho báu được phát hiện bên cạnh trấn, những điều kỳ lạ bắt đầu xảy ra trong thị trấn, liên tiếp xảy ra vụ việc các cô gái bị giết hại tại nhà. Người ta nói rằng triều trước một tên thủ lĩnh tự xưng là&nbsp;</p>', 'Full', 1, 'single', 'completed', 11, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chin Siu-ho","avatar":""},{"name":"Guo Donghai","avatar":""},{"name":"Andrew Pong","avatar":""},{"name":"Jie Luo","avatar":""},{"name":"Han Rui","avatar":""},{"name":"Gao Hailong","avatar":""},{"name":"Xin Yiquan","avatar":""},{"name":"Zhang Haifeng","avatar":""},{"name":"Zhang Fengjun","avatar":""},{"name":"Han Mengwu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324311);
