INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-dong-bac-toi-ten-trieu-hong-binh', 'Chuyện Đông Bắc : Tôi Tên Triệu Hồng Binh', 'The Godfather of Northeast China', 'https://phimimg.com/upload/vod/20231012-1/a95bb0804a467277eaa9aefd2e0872a9.jpg', 'https://phimimg.com/upload/vod/20231012-1/f1850e2621bf546f1ceb18c1fc7fc63e.jpg', '<p>Zhao Hongbing đã cải tạo trở về quê hương, và khi đang điều hành một nhà hàng &quot;Xinxingyuan&quot; cùng với người đồng đội Xiao Beijing, anh đang tìm kiếm Xiaolong, con trai của người bạn cũ. Trong quá trình tìm kiếm Xiaolong, Zhao Hongbing đã gặp thợ cắt tóc Xiaojing do hiểu lầm và dần dần gắn bó với nhau trong quá trình này. Triệu Hồng Băng chọc tức Đại Hồ vì nhận nuôi và chăm sóc Tiểu Long, sự nghịch ngợm của Tiểu Long cũng khiến những người xung quanh chỉ trích hành vi của Triệu Hồng Băng. Đủ loại rắc rối cũng kéo theo, áp đảo Triệu Hồng Băng, con hổ lớn cũng đang để mắt tới khách sạn &quot;Xinxingyuan&quot; trong bóng tối</p>', 'Full', 1, 'single', 'completed', 10, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xu Juncong","avatar":""},{"name":"Zhang Junran","avatar":""},{"name":"Bao Bei Er","avatar":""},{"name":"Zhang Jiahao","avatar":""},{"name":"Jason Chu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324311);
