INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-dong-bac-toi-ten-trieu-hong-binh', 'Chuyện Đông Bắc : Tôi Tên Triệu Hồng Binh', 'The Godfather of Northeast China', 'chuyện đông bắc : tôi tên triệu hồng binh the godfather of northeast china xu juncong zhang junran bao bei er zhang jiahao jason chu ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-ngot-ngao', 'Bẫy Ngọt Ngào', 'Naked Truth', 'https://phimimg.com/upload/vod/20231011-1/56ff787394519a0a8c21c2b5f853836b.jpg', 'https://phimimg.com/upload/vod/20231011-1/d7fd3ab09f8d9c9bdc956a099a2ad228.jpg', '<p>Một câu chuyện sâu sắc, khéo léo cân bằng giữa sự nhẹ nhàng và hấp dẫn, Bảy Ngọc Ngao (Sự thật trần trụi) xoay quanh bốn người bạn thời thơ ấu từng điên cuồng quyết tâm thoát khỏi cuộc sống độc thân. Sau nhiều năm xa cách, họ vui vẻ đoàn tụ để kỷ niệm 3 năm ngày cưới của người kế vị duy nhất của nhóm đi tìm hạnh phúc hôn nhân. Cuộc hội ngộ của họ có một bước ngoặt đáng kinh ngạc khi từng lớp một, những cuộc đời bị che giấu được tiết lộ, nhốt mỗi nhân vật trong một mạng lưới bí mật nguy hiểm rối rắm có nguy cơ đẩy các mối quan hệ bấp bênh đến bờ vực. Bảy Ngọt Ngao (Sự thật trần trụi) kể về sức mạnh của tình bạn lâu năm, bóng tối tiềm ẩn của nạn bạo hành gia đình và sức mạnh giải phóng cá nhân. Đạo diễn Đinh Hà Uyên Thư. Được sản xuất bởi Live On. Phát hành tại Mỹ bởi 3388 Films.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Bảo Anh","avatar":""},{"name":"Minh Hằng","avatar":""},{"name":"Diệu Nhi","avatar":""},{"name":"Thuan Nguyen","avatar":""},{"name":"Quốc Trường","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324311);
