INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('maika-co-be-den-tu-hanh-tinh-khac', 'Maika: Cô Bé Đến Từ Hành Tinh Khác', 'Maika: The Girl From Another Galaxy', 'https://phimimg.com/upload/vod/20231011-1/993767110844d9128bc5350fb22647b5.jpg', 'https://phimimg.com/upload/vod/20231011-1/5e6634d9d397029622a698e138e08de1.jpg', '<p>Mọi chuyện có thể tốt hơn với cậu bé Hùng 8 tuổi đang đau buồn vì mất mẹ đã qua đời một năm trước. Mối quan hệ của anh với cha mình trở nên căng thẳng, người bạn thân nhất của anh sắp chuyển đi nơi khác, và trên hết, một tên chủ nhà tham lam đang bắt nạt cha anh để buộc họ rời khỏi căn hộ của mình. Anh tìm thấy niềm an ủi bằng cách ngắm bầu trời đêm từ nóc tòa nhà chung cư của mình. Một đêm nọ, anh chứng kiến một trận mưa sao băng và một ngôi sao rơi nhầm chỗ ở vùng nông thôn gần đó. Anh điều tra, nhưng thay vì tìm thấy một ngôi sao băng, anh gặp một người bạn mới và anh quyết định làm mọi thứ có thể để giúp cô ấy.</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Phu Truong","avatar":""},{"name":"Diep Anh Tru","avatar":""},{"name":"Tin Tin","avatar":""},{"name":"Ngoc Tuong","avatar":""},{"name":"Kim Nha","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324311);
