INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('maika-co-be-den-tu-hanh-tinh-khac', 'Maika: Cô Bé Đến Từ Hành Tinh Khác', 'Maika: The Girl From Another Galaxy', 'maika: cô bé đến từ hành tinh khác maika: the girl from another galaxy phu truong diep anh tru tin tin ngoc tuong kim nha ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-tay-oan-luc', 'Tân Tẩy Oan Lục', 'Song Ci', 'https://phimimg.com/upload/vod/20231010-1/9d11aa1845110b9203b398d22802be18.jpg', 'https://phimimg.com/upload/vod/20231010-1/4185c103f7d15eb8c5d6ec272453d8f1.jpg', '<p>Tai nạn không ngừng xảy ra ở trấn Linh Long, tin đồn dân gian rằng đây là Thuồng Luồng làm loạn, cần ném trẻ con cả nam lẫn nữ vào giếng Tỏa Long nuôi nó mới được an ninh lại. Hủ tục thờ cúng duy trì bao năm, không biết bao nhiêu trẻ con vô tội bị vùi thân bụng rồng. Tiếng khóc trong trấn long trời lở đất, các nhà có trẻ con đều hốt hoảng. Sau nhậm chức Chủ Bộ, Tiến sĩ mới năm nay Trang Nghiêm kiên quyết vào giếng Tỏa Long điều tra vụ án Thuồng Luồng, bất ngờ lại vào tù bởi xúc phạm đến Long Vương. Thợ khám nghiệm tử thi trong trấn Tiểu Uyển thỉnh cầu Tống Từ đã bỏ nghề xuống núi điều tra để cứu người yêu mình. Vụ án này um tùm đáng ngờ, Tống Từ và Tiểu Uyển bắt tay phá bỏ khó khăn chồng chất, cuối cùng tra rõ chân tướng trước khi Trang Nghiêm suýt bị chém đầu. Trang Nghiêm được minh oan và Tiểu Uyển bái Tống Từ làm sư phụ trước mắt các bà con. Tuy nhiên, Tống Từ lại phát hiện chân tướng không giản đơn như mình vốn tưởng đang khi trấn Linh Long yên bình lại dần...</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bobby Au-Yeung","avatar":""},{"name":"Shao Yun","avatar":""},{"name":"Lu Yu","avatar":""},{"name":"Zhao Yibei","avatar":""},{"name":"Chang Haibo","avatar":""},{"name":"Xu Liwei","avatar":""},{"name":"Man Ningxi","avatar":""},{"name":"Li Xiaopeng","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324311);
