INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-kim-dai-dao-nguc', 'Hoàng Kim Đại Đào Ngục', 'Golden Escape', 'https://phimimg.com/upload/vod/20231009-1/a755fbce6c7dc5acd4a4a2d592be9043.jpg', 'https://phimimg.com/upload/vod/20231009-1/ac230005b4c6ce440ca73741a5374cde.jpg', '<p>Một nhà biên kịch phim nhỏ đã vô tình tìm thấy một bản đồ kho báu trong số đồ đạc của ông nội mình, và vị trí của kho báu nằm ở bên dưới nhà tù ở Vịnh Chilang.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Justin Cheung","avatar":""},{"name":"Ray Lui","avatar":""},{"name":"Ricky Chan Po-Yuen","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Qiu Zijian","avatar":""},{"name":"Cai Deheng","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324311);
