INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dac-nhiem-hit', 'Đội Đặc Nhiệm HIT', 'HIT Team', 'https://phimimg.com/upload/vod/20231009-1/2c2607a86eb15cb98338be01b6f3f74a.jpg', 'https://phimimg.com/upload/vod/20231009-1/d001ec3ad572ceba93a55154bd1acd7f.jpg', '<p>Bộ phim kể về câu chuyện của cảnh sát trưởng hạng nặng Chen Zhiwei, người đã lãnh đạo người của mình bắt giữ những kẻ buôn bán ma túy để trấn áp những kẻ buôn bán ma túy khổng lồ, và cuối cùng đã thành công hóa giải câu chuyện về thế lực đen tối.</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jordan Chan","avatar":""},{"name":"Sabrina Qiu","avatar":""},{"name":"Michelle Hu","avatar":""},{"name":"Lan Yu","avatar":""},{"name":"Ricky Chan Po-Yuen","avatar":""},{"name":"Ken Wong","avatar":""},{"name":"Dominic Ho","avatar":""},{"name":"Jason Wong","avatar":""},{"name":"Liang Guorong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324311);
