INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-diep-vien-phan-3', 'Siêu Điệp Viên (Phần 3)', 'Tom Clancy''s Jack Ryan (Season 3)', 'https://phimimg.com/upload/vod/20231002-1/254b989b86c1ff8fcc14808a435b28eb.jpg', 'https://phimimg.com/upload/vod/20231002-1/a27566fc69d21e65d7cac17c809f404a.jpg', '<p>Phim Siêu Điệp Viên với sự xuất hiện của “kho báu quốc gia” John Krasinski. Lần này, anh sẽ vào vai một chuyên viên phân tích CIA bị tình thế đưa đẩy phải trở thành một đặc vụ nằm vùng. Mặc dù nhân vật này trước đây từng được rất nhiều nam diễn viên nổi tiếng khác như Alec Baldwin, Harrison Ford, Ben Affleck và Chris Pine thủ vai trên màn ảnh rộng, nhưng Krasinski sẽ là người đầu tiên đảm nhận nhân vật này trên màn ảnh nhỏ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 20, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Krasinski","avatar":""},{"name":"Wendell Pierce","avatar":""},{"name":"John Hoogenakker","avatar":""},{"name":"Jordi Mollà","avatar":""},{"name":"Francisco Denis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324311);
