INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-diep-vien-phan-2', 'Siêu Điệp Viên (Phần 2)', 'Tom Clancy''s Jack Ryan (Season 2)', 'https://phimimg.com/upload/vod/20231002-1/54a980968756cc9d065c0584b7c92969.jpg', 'https://phimimg.com/upload/vod/20231002-1/74ca450645e0d2e92de9558c15d9e824.jpg', '<p>Sau khi theo dõi một chuyến hàng đáng ngờ trong rừng rậm Venezuela, Jack Ryan đến Nam Mỹ để điều tra. Khi Jack đe dọa sẽ phát hiện ra một âm mưu sâu rộng, Tổng thống Venezuela đã phát động một cuộc phản công đánh vào nhà, dẫn Jack vào một nhiệm vụ trải dài khắp Hoa Kỳ, Anh, Nga và Venezuela để làm sáng tỏ âm mưu của Tổng thống và mang lại sự ổn định cho một quốc gia trên bờ vực của sự hỗn loạn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 18, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Krasinski","avatar":""},{"name":"Wendell Pierce","avatar":""},{"name":"Nina Hoss","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324311);
