INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thia-vang', 'Thìa Vàng', 'The Golden Spoon', 'https://phimimg.com/upload/vod/20231001-1/e1f2041201918ca3cb736cbeab0a91a5.jpg', 'https://phimimg.com/upload/vod/20231001-1/20c78eab60cdbb0ee98e25b916cee321.jpg', '<p>Thìa Vàng được chuyển thể từ tiểu thuyết cùng tên, nội dung phim kể về câu chuyện của một đứa trẻ sinh ra từ một gia đình nghèo. Một ngày nọ cậu đã có được một chiếc thìa vàng và cậu đã sử dụng chiếc thìa vàng bí ẩn đó để hoán đổi số phận với một người bạn sinh ra từ gia đình giàu có.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 27, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yook Sung-jae","avatar":""},{"name":"Lee Jong-won","avatar":""},{"name":"Jung Chae-yeon","avatar":""},{"name":"Yeon-woo","avatar":""},{"name":"Choi Won-young","avatar":""},{"name":"Son Yeo-eun","avatar":""},{"name":"Choi Dae-chul","avatar":""},{"name":"Han Chae-a","avatar":""},{"name":"Chang Ryul","avatar":""},{"name":"Kim Seo-ha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324311);
