INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-bi', 'Họa Bì', 'Painted Skin', 'https://phimimg.com/upload/vod/20230929-1/d728b3450ffcba84d60217f8049bb86e.jpg', 'https://phimimg.com/upload/vod/20230929-1/e0b393357d2923504660a9d6827fde26.jpg', '<p>Kể về mối quan hệ đầy ám ảnh và bạo tàn giữa yêu nữ Tiều Dung, học giả Vương Hoài Khanh và vợ A Nhược. Mở ra câu chuyện về tình yêu, sự sống cái chết giữa yêu quái và con người.</p>', 'Full', 1, 'single', 'completed', 23, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nita Lei","avatar":""},{"name":"Kenji Chen","avatar":""},{"name":"Du Yutong","avatar":""},{"name":"Shi Guohui","avatar":""},{"name":"Wang Hongqian","avatar":""},{"name":"Xu Shao-Hang","avatar":""},{"name":"Rong Weifeng","avatar":""},{"name":"Wu Hao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324311);
