INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('liep-hai-lap-chi', 'Liệp Hải Lập Chí', 'See The Sea', 'https://phimimg.com/upload/vod/20230929-1/306e5eb5cba216460f864c43296adea4.jpg', 'https://phimimg.com/upload/vod/20230929-1/7e45f3f084615344d471ff1aeb20615d.jpg', '<p>Ngô Tần dòng dõi của gia đình săn bắn, trong một lần hành động vì 
lời nguyền của gia đình mà mất đi người yêu là Tô Nhược Thủy. Kể từ đó, 
Ngô Tần rời tổ chức cứu hộ lớn nhất thế giới, Đội quân săn biển, trở về 
điều hành một nhà hàng lẩu đồng thời bí mật nghiên cứu bí ẩn về lời 
nguyền gia tộc. Ba năm sau, bảo vật bị mất Nam Minh Bích xuất hiện trở 
lại trên thế giới và được ngư dân cầm giữ, những người đó đã dụ Ngô Tần 
xuất hiện một lần nữa. Ngô Tần quay trở lại Đội quân săn biển, và Đội 
quân săn biển cùng ngư dân đã đạt được thỏa thuận để cùng nhau giải 
quyết bí ẩn của Nam Minh Bích.</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jordan Chan","avatar":""},{"name":"Patrick Zhao","avatar":""},{"name":"Wang Yiyao","avatar":""},{"name":"Zhang Xueqi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324311);
