INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mi-anh-cuong-hoa', 'Mị Ảnh Cuồng Hoa', 'Phantom Wildflower', 'https://phimimg.com/upload/vod/20230929-1/e74dcfefa8e4014f1b72eb13272edc1a.jpg', 'https://phimimg.com/upload/vod/20230929-1/7f47b69034596b301068e96d40cd34db.jpg', '<p><span class="key"></span>Lâm Gia Anh cùng chị gái nương tựa lẫn 
nhau, từ nhỏ đã sống dưới ảnh hưởng của các lãnh chúa. Thỉnh thoảng bắt 
gặp cảnh chị gái bị lãnh chúa Mã Thế Kiệt và những người khác truy sát, 
tận mắt chứng kiến chị mình bị áp bức nhưng không thể làm gì được. Lúc 
này, Hà Mỹ Tử xuất hiện, dáng người yêu kiều và kỹ năng độc đáo, khi đó 
Lâm Gia Anh mới biết được chị gái mình là thành viên đội đặc công nữ của
 Hà Mỹ Tử, cô lập tức quyết định gia nhập đội đặc công của Hà Mỹ Tử. 
Trong cơ sở huấn luyện, Lâm Gia Anh và các chị em khác đã cùng học các 
kỹ năng khác nhau, vượt qua một loạt các bài kiểm tra khắc nghiệt và 
đồng thời thiết lập tình bạn sâu sắc. Lâm Gia Anh bước ra khỏi căn cứ 
huấn luyện và bắt đầu thực hiện các nhiệm vụ, phải đối mặt với những 
thách thức lớn hơn. Đối mặt với sự vướng mắc và đau khổ bên trong, cô 
bắt đầu nghi ngờ tổ chức huấn luyện bí mật này, và cuối cùng đã tiết lộ 
bí mật của tổ chức này sau màn sương mù.</p><p><br/></p><p><br/></p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Raquel Xu","avatar":""},{"name":"Sun Cong","avatar":""},{"name":"Hei Zi","avatar":""},{"name":"Ge Tian","avatar":""},{"name":"Meiling Jin","avatar":""},{"name":"Tao Huang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324311);
