INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ca', 'Người Cá', 'Murloc', 'https://phimimg.com/upload/vod/20230929-1/4d4b785934166db3deee829e8eab2c86.jpg', 'https://phimimg.com/upload/vod/20230929-1/5f6114ad4f92b60fc09f0b72f4d9eb95.jpg', '<p>Phim kể về câu chuyện của nhân vật chính Hàn Hách (do Phàn Thiểu 
Hoàng thủ vai). Con trai của Hàn Hách vô tình bị mắc kẹt trong một phòng
 thí nghiệm bí mật. Bằng sự mưu trí và dũng cảm, Hàn Hách đã từng bước 
tiến lên chiến đấu với sinh vật lạ &quot;Người cá&quot;. Với tinh thần ngoan cường
 và trí tuệ siêu việt, anh đã dẫn dắt những người bị mắc kẹt vượt qua 
nhiều cuộc khủng hoảng. Một cuộc chạy trốn sinh tử căng thẳng bắt đầu...</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Fan Siu-wong","avatar":""},{"name":"Ken Lok","avatar":""},{"name":"Li Ruoxi","avatar":""},{"name":"Tang Xin","avatar":""},{"name":"Zaimire Aheiti","avatar":""},{"name":"Ma Chenglong","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Koko Tang","avatar":""},{"name":"Tian Haoning","avatar":""},{"name":"Mao Fan","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324311);
