INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tai-3', 'Thần Tài 3', 'Runaway God of Wealth 3', 'https://phimimg.com/upload/vod/20230929-1/9e54d9ae5a0d10cdce5ec85a90264f03.jpg', 'https://phimimg.com/upload/vod/20230929-1/01debb99e9e311e4edb4ba4f6f47dbfc.jpg', '<p><span class="key"></span>Vương Gia Thành, người luôn mơ mộng làm 
giàu nhưng chẳng đạt được gì, trong lúc đón Thần Tài đã vô tình dùng 
pháo bắn hạ Thần Tài mới được bổ nhiệm của Trung Quốc, và vì thế bắt đầu
 sống chung với Thần Tài. Vương Gia Thành cho rằng mình là người thành 
tâm và tâm linh, nhưng không biết rằng có một điều bí ẩn khác về sự xuất
 hiện của Thần Tài, không chỉ Thần Tài Trung Quốc xuất hiện mà các vị 
Thần Tài của các nước khác cũng đang dõi theo anh. Tại sao Thần Tài của 
Trung Quốc và Thần Tài của các nước đều vây quanh Vương Gia Thành? Họ sẽ
 làm gì Vương Gia Thành? Đối mặt với muôn vàn cám dỗ, Vương Gia Thành sẽ
 lựa chọn điều gì? Mọi thứ đều nằm trong cuộc phiêu lưu kỳ ảo này của 
Vương Gia Thành và các vị Thần Tài.</p>', 'Full', 1, 'single', 'ongoing', 20, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yue Sun","avatar":""},{"name":"Yin Fei","avatar":""},{"name":"Koji Yano","avatar":""},{"name":"Dao Dao","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324311);
