INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-me-quyen-anh', 'Người Mẹ Quyền Anh', 'Boxing Champion Mother', 'https://phimimg.com/upload/vod/20230929-1/bf9ac149d311cf4e54212248c7c7370b.jpg', 'https://phimimg.com/upload/vod/20230929-1/e92ca9fb7cbae58fddd42ae51e5cd20a.jpg', '<p>Hàn Tiếu Tiếu là một công nhân chuyển hoa, hàng ngày phải vật lộn vì gia đình, người chồng thì nhàn rỗi không chịu làm nụng và cô con gái thất ngôn khiến cô vất vả bận rộn. Vốn là một người lạc quan nên cô tin rằng mọi thứ sẽ ổn, vì vậy cô luôn dùng thái độ lạc quan để đối mặt với mọi thứ. Lúc đó bộ phim sắp quay <br/></p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Mao Tai","avatar":""},{"name":"Leng Meng","avatar":""},{"name":"Chen Xiang","avatar":""},{"name":"Ying Baolin","avatar":""},{"name":"Lin Yating","avatar":""},{"name":"Huang Xiaofei","avatar":""},{"name":"Tai Guangyuan","avatar":""},{"name":"Mo Gutou","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324311);
