INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-ho-li-noi-thon-que', 'Vợ Hồ Li Nơi Thôn Quê', 'The Wicked Wife', 'https://phimimg.com/upload/vod/20230929-1/a6280dfc248975fef061683f7c3cd09f.jpg', 'https://phimimg.com/upload/vod/20230929-1/6a203b284c2dd5ba16f82033d21da9a3.jpg', '<p>Vào thời Dân Quốc, một trận mưa lớn đã làm kẹt lại đoàn kinh kịch 
đang đi qua sông tham gia sự kiện nổi tiếng ở Lạt Bá Câu. Vào một đêm 
giông bão, cùng trú mưa với đoàn kịch còn có một tên thổ phỉ giết người,
 và cậu lính tuần không rõ danh tính...Một nhóm này không ngờ đều có 
liên quan mật thiết đến việc vợ hồ li mười lăm năm trước ...</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sheng Guansen","avatar":""},{"name":"Wang Ming","avatar":""},{"name":"Lin Fengye","avatar":""},{"name":"付赫安琪","avatar":""},{"name":"Shi Guohui","avatar":""},{"name":"Fu Jun","avatar":""},{"name":"Bao Xiaoping","avatar":""},{"name":"Han Rui","avatar":""},{"name":"Zhang Haifeng","avatar":""},{"name":"Wei Jinsong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324311);
