INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoc-vuong-thien-quan-trung-khoi', 'Dược Vương Thiên Quan: Trùng Khởi', 'The Medicine King Coffin', 'https://phimimg.com/upload/vod/20230928-1/efc06e9c7255109ab70eff27feeb3de2.jpg', 'https://phimimg.com/upload/vod/20230928-1/a523b45a537a3b2eb6fd31cf2b28f40c.jpg', '<p>Hạ Trường Sinh từ nhỏ đã theo ông cố đi du ngạo khắp nơi, hành 
nghề chữa bệnh cứu người, học được rất nhiều kỹ năng. Khi ông cố mất 
Trường Sinh cùng với bạn thân thuở nhỏ Hồ Nhất Phát cùng đến Thượng Hải 
mở một tiệm thuốc chữa bệnh cho người dân. Cho đến một ngày, khi Trường 
Sinh và Nhất Phát đang trông coi tiệm, thì một người phụ nữ tên A Man ăn
 mặc như người Miêu, đến trước cửa và yêu cầu Hạ Trường Sinh trả nợ cho 
cha, thực hiện lời hứa. Hạ Trường Sinh đã tranh cãi với A Man. Khi hai 
người đang tranh cãi, một người đàn ông tên là Hà Nhân Kiên xuất hiện 
cùng một đội lính đánh thuê nước ngoài bao vây tiệm thuốc...</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jason Sze","avatar":""},{"name":"Xu Xiaosa","avatar":""},{"name":"Li Ming","avatar":""},{"name":"Yang Zimo","avatar":""},{"name":"Wang Junpeng","avatar":""},{"name":"Wang Gang","avatar":""},{"name":"Kaiyi Zhang","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324311);
