INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-la-bo-bac', 'Bí Ẩn La Bố Bạc', 'Lop Nur Mysterious Event', 'https://phimimg.com/upload/vod/20230928-1/94326b45854f3fc2e998b7cbb29b83c9.jpg', 'https://phimimg.com/upload/vod/20230928-1/cb343249b3cfa4e1aace2b7fc8c3adf0.jpg', '<p>Trong khu vực Lop Nur bí ẩn thường xuyên xảy ra hàng loạt sự cố kỳ
 quái. Tổ chức điều tra sự cố bí ẩn địa phương &quot;Hội Thất Tử&quot; đã mở một 
cuộc điều tra về những sự kiện bí ẩn này. Chủ tịch hội - Thạch Sơ Thất 
dẫn dắt thành viên của các đội nhóm điều tra tìm ra bí ẩn và cuối cùng 
thì sự thật cũng được làm sáng tỏ.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jerry Wu","avatar":""},{"name":"Choenyi Tsering","avatar":""},{"name":"Tong Yang","avatar":""},{"name":"Gao Chenglong","avatar":""},{"name":"Wang Zhipeng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324311);
