INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-ngan', 'Bỉ Ngạn', 'Lycoris Radiata', 'https://phimimg.com/upload/vod/20230928-1/ca71e1d6f2243e0295e7c12b37973e1c.jpg', 'https://phimimg.com/upload/vod/20230928-1/4b0638cc819ff9547eb2714190675e59.jpg', '<p>Trong vai một sứ giả dẫn độ từ thế giới ngầm đã cắt đứt tình yêu, 
Mạn Thù bất ngờ gặp Sa Hoa, người có thể mang lại hơi ấm tình thương cho
 cô ấy. Cả hai được định sẵn để ở bên nhau, nhưng phải đối mặt với sự 
cản trở từ Mãnh bà, chấp nhận những dằn vặt và thử thách của một cuộc 
sống cuối cùng cả hai đã vượt qua tất cả, thành công trong việc bảo vệ 
thế giới ngầm và Sa Hoa trở thành sứ giả dẫn đường bảo vệ Mạn Thù.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sheng Nan","avatar":""},{"name":"Li Jiaming","avatar":""},{"name":"Wang Xingchen","avatar":""},{"name":"Jackson Liu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324311);
