INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-ve-si-cua-toi', 'Chàng Vệ Sĩ Của Tôi', 'My Dear Bodyguard', 'https://phimimg.com/upload/vod/20230928-1/44ef437cb7c64a462893a790fb4ba706.jpg', 'https://phimimg.com/upload/vod/20230928-1/3a1c8bbf3dec427260e64d6f3e21ef4b.jpg', '<p>Hàn Bân cựu thành viên ưu tú của một công ty an ninh ở nước ngoài 
vì chữa bệnh nên trở lại làm việc. Nhiệm vụ của anh là bảo vệ ngôi sao 
Tô Hiểu Kì đến một quốc gia ở Đông Nam Á để quay một chương trình. Sau 
khi giải quyết một số sự cố đe dọa sự an toàn của Hiểu Kì trên đường đi,
 anh nhận ra rằng mục tiêu thực sự là chính mình. Trong một nhiệm vụ 
cách đây vài năm, những kẻ phản diện sống sót đã đặt nhiều bẫy khác nhau
 để trả đũa Hàn Bân. Với sự giúp đỡ của nhiều bên, Hàn Bân cuối cùng đã 
thành công trong việc giải cứu Hiểu Kì và cùng với cảnh sát nước ngoài 
tiêu diệt tất cả những kẻ ác.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Raquel Xu","avatar":""},{"name":"Terence Yin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324311);
