INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-nhen-vang', 'Thành Phố Nhện Vàng', 'Golden Spider City', 'https://phimimg.com/upload/vod/20230928-1/9762c2c66b09cf6b47ec208c3296d958.jpg', 'https://phimimg.com/upload/vod/20230928-1/bdee3f39e73be8981659cd15164dfb3a.jpg', '<p>Vì một quyển ghi chép khảo cổ do cha mẹ để lại, Tư Mã Công đã bị một doanh nhân giàu có ở Thái Lan nhắm tới, và dùng mạng sống của bạn gái anh Lisa để đe dọa yêu cầu anh đi vào núi sâu tìm kiếm nhện vàng. Trong lúc thám hiểm, Tư Mã Công đã gặp Bát Gia, một thiên tài trốn thoát khỏi chiếc quan tài nhuốm máu trong lăng mộ. Hai người cùng nhau hợp sức để khám phá những bí mật của nơi đây. Lúc này, nhân vật phản diện Tương Gia đột ngột xuất hiện tiết lộ một bí mật gây sốc. Danh tính thực sự của Bát Gia hóa ra là người cha đã mất từ lâu của Tư Mã Công -Tư Mã Khôi. Cả ba tiếp tục tìm kiếm tung tích của nhện vàng. Khi họ đi sâu vào trong nhện vàng khổng lồ đã xuất hiện và mối nguy hiểm của họ cũng đã đến. Lần này, Tư Mã Khôi quyết định một lần nữa gánh vác trọng trách của người cha, Tư Mã Công vốn luôn ích kỷ cũng đã tỉnh ngộ, cùng với sự hòa giải của hai cha con, thành nhện vàng dưới lòng đất cũng hé lộ bí ẩn về nền văn minh ngoài hành tinh.</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Lincheng","avatar":""},{"name":"Chen Mengqi","avatar":""},{"name":"Ning Xiaohua","avatar":""},{"name":"Sasha","avatar":""},{"name":"Mao Fan","avatar":""},{"name":"Sang Ping","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324311);
