INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-long-vien', 'Ô Long Viện', 'Messy Temple', 'https://phimimg.com/upload/vod/20230928-1/3b37c855b71a41e76dbe4460cc442522.jpg', 'https://phimimg.com/upload/vod/20230928-1/fe56ed1d5261c38c786a2c2df5494e65.jpg', '<p>A Lượng đệ tử của Ô Long Viện muốn trở thành một nhà trừ tà vĩ 
đại, trong cuộc hành trình cậu đã gặp Shakeyang một bậc thầy trừ tà, và 
Ái Phi một cô gái viết tiểu thuyết trừ tà. Họ cùng nhau đồng hành, cùng 
nhau hợp tác để gửi Quỷ Kiếm đến Tháp Khóa Quỷ và phong ấn câu chuyện 
phiêu lưu kỳ ảo của Quỷ Vương.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xia Zhi Yuan","avatar":""},{"name":"Yu Li","avatar":""},{"name":"Zhao Wenhao","avatar":""},{"name":"Wong Yat-fei","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324311);
