INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('o-long-vien', 'Ô Long Viện', 'Messy Temple', 'ô long viện messy temple xia zhi yuan yu li zhao wenhao wong yat-fei ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-kiem-phong-ma', 'Đao Kiếm Phong Ma', 'The Legend of Enveloped Demons', 'https://phimimg.com/upload/vod/20230928-1/a491ea41887b511db1cd50fdf53e4053.jpg', 'https://phimimg.com/upload/vod/20230928-1/5e6209dee4b8a11b2fbd957d284c044b.jpg', '<p>Từ lâu, người phong ấn quỷ là một anh hùng diệt trừ quỷ. Tuy 
nhiên, khi họ tiêu diệt những con quỷ, những người dân thường để ý đến 
siêu năng lực của họ, nếu bị bắt, họ sẽ bị tống vào tù, vì vậy họ phải 
che dấu thân phận. Ba anh em Đường Khê, Lạc Xuyên và Khâu Phong thân 
phận hiện tại là những ngư dân rất giản dị và lương thiện. Tuy nhiên, 
một sự cố xảy ra khiến họ biết rằng con quỷ đã tái sinh. Ba anh em đã đi
 điều tra và tìm ra dấu vết của quỷ trong xưởng rượu. Tuy nhiên, tất cả 
người dân thậm trí người đứng đầu trấn đều bỏ ngoài tai lời cảnh báo cỏ 
họ, còn đem họ ra quy án. Để tránh cho nhiều người bị thương, họ đã phải
 làm trái mệnh lệnh đích thân ra tay giết quỷ. Tuy nhiên, tất cả những 
điều này là một âm mưu chống lại những người phong ấn quỷ, và ai đó đã 
sử dụng sức mạnh của quỷ để giết họ. Số phận của cả ba đã được định đoạt
 từ khi mới sinh ra. Cái gọi là trừ quỷ thay trời hành đạo ngay từ đầu 
