INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ton-ngo-khong-dong-khong-day', 'Tôn Ngộ Không: Động Không Đáy', 'Monkey King The Bottomless Hole', 'https://phimimg.com/upload/vod/20230928-1/76ea6d9edcf1cd469011be885e11110f.jpg', 'https://phimimg.com/upload/vod/20230928-1/856c0f1ed028868453b3465326c59cd0.jpg', '<p>Bốn thầy trò Đường Tăng trên đường đi lấy kinh đi qua một đất nước nhỏ, hai con yêu chuột là Tiểu Bạch và Tiểu Hồng đang tu luyện thành tiên trong hang động không đáy gần đó đã dùng thủ đoạn bắt cóc thầy trò Đường Tăng vào trong hang. Để cứu sư phụ của mình, Ngộ Không đã khám phá xung quanh hang động không đáy. Tiểu Bạch tốt bụng đã có duyên với Đường Tăng từ một trăm năm trước. Tiểu Hồng ăn thịt biến thành quỷ cuối cùng bị đánh trở về nguyên hình.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ning Wang","avatar":""},{"name":"Song Hanhuan","avatar":""},{"name":"Ariel Ann","avatar":""},{"name":"Yu Li","avatar":""},{"name":"Ai Li-Ku","avatar":""},{"name":"Sang Ping","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324311);
