INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuong-va-tat-ca', 'Xương và Tất Cả', 'Bones and All', 'https://phimimg.com/upload/vod/20230928-1/d784c04671aaf9ad41edbb9aa73716ce.jpg', 'https://phimimg.com/upload/vod/20230928-1/d1662cb42e89b71b33f82c6edf639399.jpg', '<p>Bộ phim xoay quanh hai nhân vật trẻ tuổi: Maren (Taylor Russell) và Lee (Timothée Chalamet). Lee là mối tình đầu của Maren. Cả hai sống bên lề xã hội nước Mỹ những năm 80, cùng rong ruổi trên một hành trình dài và kỳ lạ. Chuyến hành trình của cả hai không chỉ có tự do, lãng mạn, sự cô đơn lẩn khuất, mà còn là căng thẳng, kịch tính. Bởi Lee là một chàng trai đẹp mã và… ăn thịt người.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Taylor Russell","avatar":""},{"name":"Timothée Chalamet","avatar":""},{"name":"Mark Rylance","avatar":""},{"name":"Anna Cobb","avatar":""},{"name":"André Holland","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"David Gordon Green","avatar":""},{"name":"Jessica Harper","avatar":""},{"name":"Chloë Sevigny","avatar":""},{"name":"Jake Horowitz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324311);
