INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xuong-va-tat-ca', 'Xương và Tất Cả', 'Bones and All', 'xương và tất cả bones and all taylor russell timothée chalamet mark rylance anna cobb andré holland michael stuhlbarg david gordon green jessica harper chloë sevigny jake horowitz ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gioi-han-tinh-yeu', 'Giới Hạn Tình Yêu', 'Borders of Love', 'https://phimimg.com/upload/vod/20230928-1/652240eb5e2a272db9c06f97fce3566c.jpg', 'https://phimimg.com/upload/vod/20230928-1/4cb5fac859509aef802df6829aee97ff.jpg', '<p>Sau nhiều năm bên nhau, Petr và Hana, các đối tác trong công việc và trong cuộc sống, chia sẻ những tưởng tượng khiêu dâm bất thành văn của họ. Những gì bắt đầu như một cuộc trò chuyện ngây thơ dần dần biến thành thử nghiệm tò mò với một cách tiếp cận không đơn độc đối với mối quan hệ của họ. Nhưng tự do tình dục có vị khác nhau cho mỗi người trong số họ. Không cần dùng đến việc khai thác, Tính năng đầu tay của Tomasz Wiński, xem xét các câu hỏi là điều cấm kỵ đối với nhiều cặp vợ chồng. Biên giới tình yêu khám phá không chỉ các hình thức thân mật khác nhau mà còn là những cách mô tả nó trên màn ảnh rộng, vì, trong số những người khác, chính các nhân vật chính quay lại với nhau trên điện thoại di động của họ. Xuất hiện trong các vai chính là Matyáš řezníček và Hana Vagnerová, người đã hợp tác trong bộ phim câu chuyện và kịch bản.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hana Vagnerová","avatar":""},{"name":"Matyáš Řezníček","avatar":""},{"name":"Eliška Křenková","avatar":""},{"name":"Martin Hofmann","avatar":""},{"name":"Antonie Formanová","avatar":""},{"name":"Hynek Čermák","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324311);
