INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ngon-nghe-cu', 'Những Ngón Nghề Cũ', 'All the Old Knives', 'https://phimimg.com/upload/vod/20230926-1/ad022c8b23540c248a6eef834928b789.jpg', 'https://phimimg.com/upload/vod/20230926-1/a7a795716fac7e2cdd89f6e0a66e82c6.jpg', '<p>Người yêu cũ đồng thời là những điệp viên của CIA – Henry và Celia gặp nhau trong bữa tối để hồi tưởng về khoảng thời gian họ bên nhau tại nhà ga Vienna. Trong cuộc gặp mặt đó, họ cũng bắt đầu kể lại câu chuyện về 6 năm trước khi một thảm kịch máy bay bất ngờ xảy ra và không ai trên đó sống sót.</p>', 'Full', 1, 'single', 'completed', 12, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Pine","avatar":""},{"name":"Thandiwe Newton","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Corey Johnson","avatar":""},{"name":"Jonjo O''Neill","avatar":""},{"name":"Ahd","avatar":""},{"name":"David Dawson","avatar":""},{"name":"Nasser Memarzia","avatar":""},{"name":"Orli Shuka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324311);
