INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-de-chet', 'Một Ngày Để Chết', 'A Day to Die', 'https://phimimg.com/upload/vod/20230926-1/3275fd72b6e804e37d69d659a9fcbef1.jpg', 'https://phimimg.com/upload/vod/20230926-1/d9c691dc2445ff4ac3f94d8d93e1ff71.jpg', '<p>Một sĩ quan tạm tha bị thất sủng mắc nợ một thủ lĩnh băng đảng địa phương và buộc phải thực hiện một loạt vụ trộm ma túy nguy hiểm trong vòng 12 giờ để trả số tiền 2 triệu đô la mà anh ta nợ, giải cứu người vợ đang mang thai bị bắt cóc và giải quyết vấn đề tham nhũng của thành phố. cảnh sát trưởng, người đang làm việc với thủ lĩnh băng đảng và đã qua mặt hắn nhiều năm trước.</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Dillon","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Leon","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Gianni Capaldi","avatar":""},{"name":"Brooke Butler","avatar":""},{"name":"Johnny Messner","avatar":""},{"name":"Vernon Davis","avatar":""},{"name":"Alexander Kane","avatar":""},{"name":"Aspen Kennedy Wilson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324311);
