INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xe-cap-cuu', 'Xe Cấp Cứu', 'Ambulance', 'https://phimimg.com/upload/vod/20230926-1/931e2a4fdbe63889e067661d3093436e.jpg', 'https://phimimg.com/upload/vod/20230926-1/fcb34da03b54df3f31e4ea1f9b5a8b04.jpg', '<p>Xe cấp cứu – Ambulance là bộ phim hành động kịch tính của Mỹ được đạo diễn kiêm sản xuất bởi Michael Bay. Bối cảnh phim được diễn ra tại thành phố Los Angeles đầy hối hả, sôi động và sầm uất. Cựu binh Will Sharp (do Yahya Abdul-Mateen II thủ vai) vì hoàn cảnh khó khăn nên đã tìm đến sự giúp đỡ của người mà anh biết mình không nên nhờ vả – em trai nuôi Danny Sharp (do Jake Gyllenhaal thủ vai). Danny đã đề nghị Will Sharp cùng thực hiện phi vụ cướp ngân hàng lớn nhất trong lịch sử Los Angeles: 32 triệu đô.</p>', 'Full', 1, 'single', 'completed', 13, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Yahya Abdul-Mateen II","avatar":""},{"name":"Eiza González","avatar":""},{"name":"Garret Dillahunt","avatar":""},{"name":"Keir O''Donnell","avatar":""},{"name":"Jackson White","avatar":""},{"name":"Olivia Stambouliah","avatar":""},{"name":"Moses Ingram","avatar":""},{"name":"Colin Woodell","avatar":""},{"name":"Cedric Sanders","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324311);
