INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('apollo-10-thoi-tho-au-o-ky-nguyen-vu-tru', 'Apollo 10½:  Thời Thơ Ấu Ở Kỷ Nguyên Vũ Trụ', 'Apollo 10½: A Space Age Childhood', 'https://phimimg.com/upload/vod/20230926-1/aa5deaeb87645a7099b9c38aae14c828.jpg', 'https://phimimg.com/upload/vod/20230926-1/4b879842a9b055b10b08a43c8f751996.jpg', '<p>Một người đàn ông kể lại những câu chuyện về cuộc đời mình khi còn là một cậu bé 10 tuổi ở Houston năm 1969, dệt nên những câu chuyện hoài niệm bằng câu chuyện kỳ ảo về chuyến hành trình lên mặt trăng.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Milo Coy","avatar":""},{"name":"Jack Black","avatar":""},{"name":"Zachary Levi","avatar":""},{"name":"Glen Powell","avatar":""},{"name":"Josh Wiggins","avatar":""},{"name":"Lee Eddy","avatar":""},{"name":"Bill Wise","avatar":""},{"name":"Natalie L''Amoreaux","avatar":""},{"name":"Jessica Brynn Cohen","avatar":""},{"name":"Sam Chipman","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324311);
