INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('apollo-10-thoi-tho-au-o-ky-nguyen-vu-tru', 'Apollo 10½:  Thời Thơ Ấu Ở Kỷ Nguyên Vũ Trụ', 'Apollo 10½: A Space Age Childhood', 'apollo 10½:  thời thơ ấu ở kỷ nguyên vũ trụ apollo 10½: a space age childhood milo coy jack black zachary levi glen powell josh wiggins lee eddy bill wise natalie l''amoreaux jessica brynn cohen sam chipman ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-cu-den', 'Căn Cứ Đen', 'Black Site', 'https://phimimg.com/upload/vod/20230926-1/d3d22722d146288d43b753e45074c58e.jpg', 'https://phimimg.com/upload/vod/20230926-1/8bc57e3c3631aa0c4f3b48a8b8b69cb1.jpg', '<p>Phim xoay quanh câu chuyện kể về một bệnh viện bị đánh bom ở Thổ Nhĩ Kỳ, và trong số hàng trăm người thương vong là CIA có chồng bác sĩ và con gái nhỏ của nhà phân tích CIA Abigail “Abby” Trent. Bên trong nỗi đau của Abby là một lời kêu gọi hành động, và cô ấy chọc tức sếp của mình ở Langley, để được giao nhiệm vụ thực địa cho “The Citadel”, một boongke giám sát và cơ sở điều hành đặc biệt nằm dưới một tảng đá ở sa mạc Jordan. Ở đó, cô đào sâu vào việc phân tích dữ liệu, hỏi những người bị giam giữ và khám phá ra mối liên hệ giữa vụ đánh bom bệnh viện và một nhà điều hành quốc tế khét tiếng và khó nắm bắt được gọi là “Hatchet” (Jason Clarke).</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Jason Clarke","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"Pallavi Sharda","avatar":""},{"name":"Fayssal Bazzi","avatar":""},{"name":"Uli Latukefu","avatar":""},{"name":"Lucy Barrett","avatar":""},{"name":"Logan Huffman","avatar":""},{"name":"Phoenix Raei","avatar":""},{"name":"Todd Lasance","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324311);
