INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chia-khoa-tram-ty', 'Chìa Khóa Trăm Tỷ', 'A Hundred Billion Key', 'https://phimimg.com/upload/vod/20230926-1/22aea8a0e05c520bc980e9965fe50c26.jpg', 'https://phimimg.com/upload/vod/20230926-1/2e8ff4147065d37b6d2d8d66d93a8464.jpg', '<p>Chìa Khoá Trăm Tỷ là câu chuyện đầy oái ăm và ngập tràn tiếng cười kể về những cuộc gặp gỡ định mệnh của bộ ba Mai (Thu Trang),&nbsp; Dũng (Anh Tú) và Thạch (Kiều Minh Tuấn). Ba con người,&nbsp; ba tính cách vô tình va vào nhau rồi bất ngờ thay đổi hoàn toàn số phận lẫn nhau. Có kẻ giàu lên, có người đột ngột trở thành diễn viên...quần chúng và cũng có người bỗng dưng tìm được một nửa của đời mình. Và đó là một câu chuyện cười ra nước mắt khi mỗi một ngày trôi qua họ lại phải tìm mọi cách để sống thật nhất với thân phận mới mà vô tình có được.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Kiều Minh Tuấn","avatar":""},{"name":"Thu Trang","avatar":""},{"name":"Anh Tú","avatar":""},{"name":"Jun Vũ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324311);
