INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-dac-vu', 'Chó Đặc Vụ', 'Dog', 'https://phimimg.com/upload/vod/20230926-1/cacc4c5e4fb318cab2b19314585b697d.jpg', 'https://phimimg.com/upload/vod/20230926-1/26f1d7cd3dfc04618f15274b152612e6.jpg', '<p>Một kiểm lâm quân đội và con chó của anh ta bắt đầu chuyến đi dọc theo Đường cao tốc Bờ biển Thái Bình Dương để dự đám tang của một người bạn.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Channing Tatum","avatar":""},{"name":"Aavi Haas","avatar":""},{"name":"Ryder McLaughlin","avatar":""},{"name":"Luke Forbes","avatar":""},{"name":"Darren Keilan","avatar":""},{"name":"Eric Urbiztondo","avatar":""},{"name":"Darin Keith Martin","avatar":""},{"name":"Justin Louis Weiss","avatar":""},{"name":"Cayden Boyd","avatar":""},{"name":"Devin White","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324311);
