INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-quyen-phuc-thu', 'Thiết Quyền Phục Thù', 'Fistful of Vengeance', 'https://phimimg.com/upload/vod/20230926-1/4dc13a09dc73586767b2325da7cee0ee.jpg', 'https://phimimg.com/upload/vod/20230926-1/b2d75f61187ccaac048d8598a09710ef.jpg', '<p>Nhiệm vụ trả thù biến thành trận chiến giải cứu thế giới khỏi mối đe dọa cổ xưa khi tay thích khách siêu năng lực Khải theo dấu một tên sát nhân đến Bangkok.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Iko Uwais","avatar":""},{"name":"Lewis Tan","avatar":""},{"name":"Lawrence Kao","avatar":""},{"name":"Pearl Thusi","avatar":""},{"name":"Francesca Corney","avatar":""},{"name":"JuJu Chan","avatar":""},{"name":"Jason Tobin","avatar":""},{"name":"Rhatha Phongam","avatar":""},{"name":"Selina Wiesmann","avatar":""},{"name":"Joseph Angelo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324311);
