INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-khoi-lua', 'Người Khởi Lửa', 'Firestarter', 'https://phimimg.com/upload/vod/20230926-1/7b17651a4c08ab3467dad5c86c6abd9d.jpg', 'https://phimimg.com/upload/vod/20230926-1/586e509265bfcd8ee0ef1d3acead8388.jpg', '<p>Sau khi được thí nghiệm bởi một thực thể bí mật của chính phủ có tên là The Shop, Andy McGee phát triển năng lực tâm linh và gặp được tình yêu của đời mình. Họ cùng nhau có một cô con gái với sức mạnh của riêng mình, người có thể đốt cháy mọi thứ từ tâm chí của bản thân. Điều này khiến cho gia đình họ gặp phải vô vàn khó khăn, nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Ryan Kiera Armstrong","avatar":""},{"name":"Zac Efron","avatar":""},{"name":"Sydney Lemmon","avatar":""},{"name":"Kurtwood Smith","avatar":""},{"name":"Michael Greyeyes","avatar":""},{"name":"Gloria Reuben","avatar":""},{"name":"John Beasley","avatar":""},{"name":"Tina Jung","avatar":""},{"name":"Hannan Younis","avatar":""},{"name":"Gavin MacIver-Wright","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324312);
