INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('interceptor-cuoc-chien-ten-lua', 'Interceptor: Cuộc Chiến Tên Lửa', 'Interceptor', 'https://phimimg.com/upload/vod/20230926-1/df5948b4a8b473e2f24c60fe97ca1637.jpg', 'https://phimimg.com/upload/vod/20230926-1/d250a0ede20d6a3183bf74bb049d2f0f.jpg', '<p>Sĩ quan cuối cùng tại một căn cứ phòng thủ tên lửa hẻo lánh tham gia cuộc chiến sinh tử với bọn khủng bố đang nhắm 16 vũ khí hạt nhân đánh cắp vào Hoa Kỳ.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Elsa Pataky","avatar":""},{"name":"Luke Bracey","avatar":""},{"name":"Aaron Glenane","avatar":""},{"name":"Belinda Jombwe","avatar":""},{"name":"Mayen Mehta","avatar":""},{"name":"Paul Caesar","avatar":""},{"name":"Marcus Johnson","avatar":""},{"name":"Rhys Muldoon","avatar":""},{"name":"Colin Friels","avatar":""},{"name":"Zoe Carides","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324312);
