INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('365-ngay-hom-nay', '365 Ngày: Hôm Nay', '365 Days: This Day', 'https://phimimg.com/upload/vod/20230926-1/fee6614bef7db41fc996e39ae870bda8.jpg', 'https://phimimg.com/upload/vod/20230926-1/b234a1a8078097a0f3bbef6f13794553.jpg', '<p>Laura và Massimo trở lại và mạnh mẽ hơn bao giờ hết. Nhưng mối quan hệ gia đình của Massimo và một người đàn ông bí ẩn tán tỉnh Laura khiến cuộc sống của cặp đôi đảo lộn.</p>', 'Full', 1, 'single', 'completed', 22, 2022, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Anna-Maria Sieklucka","avatar":""},{"name":"Michele Morrone","avatar":""},{"name":"Simone Susinna","avatar":""},{"name":"Magdalena Lamparska","avatar":""},{"name":"Otar Saralidze","avatar":""},{"name":"Natasza Urbańska","avatar":""},{"name":"Ramón Langa","avatar":""},{"name":"Ewa Kasprzyk","avatar":""},{"name":"Dariusz Jakubowski","avatar":""},{"name":"Tomasz Mandes","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
