INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-ca-map', 'Mồi Cá Mập', 'Shark Bait', 'https://phimimg.com/upload/vod/20230926-1/9995aeaba209c6bbaeebd0deb752d499.jpg', 'https://phimimg.com/upload/vod/20230926-1/7746c7db87ade36631ae60c301b1dd5e.jpg', '<p>Một nhóm du khách nghỉ xuân đang tận hưởng chuyến đi của cuộc đời trên những bãi biển đầy cát ở Mexico. Khi mặt trời mọc sau một đêm tiệc tùng, họ đánh cắp một vài chiếc cano và đua ra biển. Nhưng sự dũng cảm và những quyết định tồi tệ đã dẫn đến một tai nạn kinh hoàng. Bị mắc kẹt cách bờ hàng dặm, nỗi kinh hoàng thực sự bắt đầu khi cả nhóm nhận ra họ đã trôi dạt vào vùng nước có nhiều cá mập. Không còn đường lui và một người bạn bị thương nặng chảy máu nhiều, cả nhóm phải nhanh chóng tìm cách sống sót trước kẻ săn mồi đang rình rập ở vùng nước bên dưới .</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Holly Earl","avatar":""},{"name":"Jack Trueman","avatar":""},{"name":"Catherine Hannay","avatar":""},{"name":"Malachi Pullar-Latchman","avatar":""},{"name":"Thomas Michael Flynn","avatar":""},{"name":"Manuel Cauchi","avatar":""},{"name":"Maxime Durand","avatar":""},{"name":"Joshua Takacs","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324312);
