INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-danh-thue', 'Lính Đánh Thuê', 'The Contractor', 'https://phimimg.com/upload/vod/20230926-1/8cae4d7428d7d998ad85f3111ed6aa18.jpg', 'https://phimimg.com/upload/vod/20230926-1/dead0d83b431879f3a73fe711d828e9e.jpg', '<p>Sau khi tự nguyện giải ngũ khỏi Lực lượng Đặc biệt Hoa Kỳ, James Harper quyết định hỗ trợ gia đình mình bằng cách gia nhập một tổ chức hợp đồng tư nhân cùng với người bạn thân nhất của mình và dưới sự chỉ huy của một cựu chiến binh. Ở nước ngoài trong một nhiệm vụ bí mật, Harper phải trốn tránh những kẻ đang cố gắng giết mình khi đang trên đường trở về nhà.</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Chris Pine","avatar":""},{"name":"Gillian Jacobs","avatar":""},{"name":"Sander Thomas","avatar":""},{"name":"Toby Dixon","avatar":""},{"name":"Dean Ashton","avatar":""},{"name":"Dustin Lewis","avatar":""},{"name":"Regina Ting Chen","avatar":""},{"name":"Brian Lafontaine","avatar":""},{"name":"Cory Scott Allen","avatar":""},{"name":"Antal Kalik","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324312);
