INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-kich', 'Biệt Kích', 'The Commando', 'https://phimimg.com/upload/vod/20230926-1/d5cb3292eb80a0d0ab7be46c75dfb335.jpg', 'https://phimimg.com/upload/vod/20230926-1/28523343edd359171ec687e44c5f9106.jpg', '<p>Một đặc vụ DEA ưu tú trở về nhà sau một nhiệm vụ thất bại khi gia đình anh phát hiện ra điều bất ngờ trong ngôi nhà của họ – một kho tiền trị giá 3 triệu USD. Họ sớm phải đối mặt với mối nguy hiểm và đe dọa từ một tên tội phạm mới được thả và đồng bọn của hắn, những kẻ sẽ làm mọi cách để lấy lại tiền, bao gồm cả việc bắt cóc con gái của đặc vụ. Tiền đặt cọc rất cao và tính mạng có nguy cơ bị đe dọa trong trận chiến đối đầu này khi đặc vụ không ngừng nỗ lực để bảo vệ gia đình mình trước bọn tội phạm hám tiền.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Jai White","avatar":""},{"name":"Mickey Rourke","avatar":""},{"name":"Jeff Fahey","avatar":""},{"name":"Brendan Fehr","avatar":""},{"name":"Aris Mejias","avatar":""},{"name":"Gianni Capaldi","avatar":""},{"name":"Donald Cerrone","avatar":""},{"name":"John Enos III","avatar":""},{"name":"James Chalke","avatar":""},{"name":"Cord Newman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324312);
