INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-co-vat', 'Thợ Săn Cổ Vật', 'Uncharted', 'https://phimimg.com/upload/vod/20230926-1/be9b88427f1745af49ad15bf54642b9e.jpg', 'https://phimimg.com/upload/vod/20230926-1/9fd12ecb8a43850ff2e5b785a0c1ae72.jpg', '<p>Thợ Săn Cổ Vật xoay quanh nhân vật chính là chàng trai trẻ yêu phiêu lưu mạo hiểm Nathan Drake (Tom Holland). Với sự trợ giúp của huấn luyện viên Victor Sullivan (Mark Wahlberg), Nathan dấn thân vào cuộc hành trình khám phá những di tích cổ xưa, sử dụng vũ khí và kỹ năng leo trèo để đối phó với kẻ thù và những cạm bẫy trên hành trình. Dọc đường đi, Nathan gặp gỡ nhiều thợ săn kho báu khác, trong đó có cô nàng nóng bỏng Chloe Frazer (Sophia Taylor Ali).</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Holland","avatar":""},{"name":"Mark Wahlberg","avatar":""},{"name":"Sophia Ali","avatar":""},{"name":"Tati Gabrielle","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Steven Waddington","avatar":""},{"name":"Rudy Pankow","avatar":""},{"name":"Tiernan Jones","avatar":""},{"name":"Pingi Moli","avatar":""},{"name":"Jesús Evita","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324312);
