INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ma-gan-nha', 'Chuyện Ma Gần Nhà', 'Vietnamese Horror Story', 'https://phimimg.com/upload/vod/20230926-1/b9d298a8bc0d84c925ec4e130efd15c2.jpg', 'https://phimimg.com/upload/vod/20230926-1/af283adc66f00350deb76cb95c491c39.jpg', '<p>Chuyện Ma Gần Nhà là tác phẩm đầu tiên trong vũ trụ kinh dị Việt Nam được lấy cảm hứng từ những truyền thuyết đô thị và các câu chuyện ma được đồn thổi trong dân gian. Bộ phim mang màu sắc u ám, quỷ dị với chất liệu từ cuộc sống đời thường. Văn hoá và tín ngưỡng, phong tục tập quán của người Việt Nam sẽ là một điểm nhấn trong tác phẩm này, bên cạnh những cảnh kinh dị.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Khả Như","avatar":""},{"name":"Mạc Can","avatar":""},{"name":"Vân Trang","avatar":""},{"name":"Huỳnh Thanh Trực","avatar":""},{"name":"Lê Bê La","avatar":""},{"name":"Trần Phong","avatar":""},{"name":"Nguyễn Hữu Tiến","avatar":""},{"name":"Ngoc Hiep Nguyen","avatar":""},{"name":"Như Đan","avatar":""},{"name":"Trịnh Tài","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324312);
