INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-diet-2-ngay-tan-the', 'Tận Diệt 2: Ngày Tận Thế', 'Wyrmwood: Apocalypse', 'https://phimimg.com/upload/vod/20230926-1/db5543ba251c2f991cdbe0b9a27eaca2.jpg', 'https://phimimg.com/upload/vod/20230926-1/44dba29b2ed87941b1023aa7935e4c58.jpg', '<p>Wyrmwood: Apocalypse là một bộ phim về thây ma hậu tận thế theo chân người lính Rhys sống trong một vùng đất hoang ở Úc bị nhiễm zombie. Rhys đang trên đường cứu chuộc khi anh quay lại chống lại những tên trùm độc ác của mình và gia nhập lực lượng với một nhóm những người sống sót sau phiến quân để giúp giải cứu một cô gái có khả năng chữa khỏi virus.</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Luke McKenzie","avatar":""},{"name":"Shantae Barnes-Cowan","avatar":""},{"name":"Bianca Bradey","avatar":""},{"name":"Tasia Zalar","avatar":""},{"name":"Jay Gallagher","avatar":""},{"name":"Nicholas Boshier","avatar":""},{"name":"Lauren Grimson","avatar":""},{"name":"Jim Robison","avatar":""},{"name":"Jake Ryan","avatar":""},{"name":"Goran D. Kleut","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324312);
