INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-cho', 'Lầm Chỗ', 'Wrong Place', 'https://phimimg.com/upload/vod/20230925-1/5d5cb53db00fb19be42f0a2ccd892316.jpg', 'https://phimimg.com/upload/vod/20230925-1/0d47152a53d8d4f1b989e41ad3056388.jpg', '<p>Một đầu bếp methamphetamine săn lùng cựu cảnh sát trưởng của một thị trấn nhỏ để bịt miệng ông ta trước khi ông ta có thể đưa ra lời khai nhân chứng chống lại gia đình mình, nhưng cuối cùng lại thấy mình phải đối mặt với nhiều điều hơn những gì ông ta đã mặc cả.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Greene","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Michael Sirow","avatar":""},{"name":"Texas Battle","avatar":""},{"name":"Stacey Danger","avatar":""},{"name":"Massi Furlan","avatar":""},{"name":"Adam Huel Potter","avatar":""},{"name":"Josh Rhett Noble","avatar":""},{"name":"Larken Woodward","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324312);
