INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-con-soi-thoi-chien', 'Những Con Sói Thời Chiến', 'Wolves of War', 'https://phimimg.com/upload/vod/20230925-1/14b38bb0eb50e46d87fce10b5de72b69.jpg', 'https://phimimg.com/upload/vod/20230925-1/e5fe509cd69b2abf58f16087d0c4a215.jpg', '<p>Sĩ quan người Anh được trang trí Jack Wallace phải dẫn đầu một nhóm biệt kích Đồng minh vượt qua chiến tuyến của kẻ thù để giải cứu Giáo sư Hopper, một nhà khoa học người Mỹ bị Đức Quốc xã bắt làm con tin. Với thông tin có thể xoay chuyển tình thế chiến tranh, những anh hùng bất đắc dĩ này phải băng qua lãnh thổ của kẻ thù cùng với một thường dân Mỹ chưa qua đào tạo, tránh những lính đánh thuê tàn bạo của Đức Quốc xã và ném bom không ngừng – với số phận của cuộc chiến đặt trên vai họ, kết quả của nhiệm vụ này sẽ thay đổi thế giới mãi mãi; thất bại không phải là một lựa chọn.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Ed Westwick","avatar":""},{"name":"Matt Willis","avatar":""},{"name":"Sam Gittins","avatar":""},{"name":"Éva Magyar","avatar":""},{"name":"Anastasia Martin","avatar":""},{"name":"Rupert Graves","avatar":""},{"name":"Scott Rose-Marsh","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324312);
