INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-nhan-tao', 'Vợ Nhân Tạo', 'WifeLike', 'https://phimimg.com/upload/vod/20230925-1/5bc85e2a28345726d450cf6493641e90.jpg', 'https://phimimg.com/upload/vod/20230925-1/aff421866f2fe1bab66f297bfb2dd7d6.jpg', '<p>Một thám tử đau buồn ở tương lai gần truy lùng những tên tội phạm buôn bán con người nhân tạo ở chợ đen. Trong cuộc chiến nhằm chấm dứt việc khai thác AI, một lực lượng kháng chiến ngầm cố gắng xâm nhập vào anh ta bằng cách phá hoại việc lập trình con người nhân tạo được chỉ định làm bạn đồng hành của anh ta để cư xử giống như người vợ quá cố của anh ta. Cô bắt đầu đặt câu hỏi về thực tế của mình khi ký ức về tiền kiếp bắt đầu hiện lên trong một thế giới nơi không có gì giống như vẻ ngoài của nó.</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elena Kampouris","avatar":""},{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Doron Bell","avatar":""},{"name":"Agam Darshi","avatar":""},{"name":"Sara Sampaio","avatar":""},{"name":"Alix Villaret","avatar":""},{"name":"Fletcher Donovan","avatar":""},{"name":"Lana","avatar":""},{"name":"Stephen Lobo","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324312);
