INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-ngoai-kia-noi-loai-tom-hat', 'Xa Ngoài Kia Nơi Loài Tôm Hát', 'Where the Crawdads Sing', 'https://phimimg.com/upload/vod/20230925-1/b31b91044fb3fda4cd061feacc9a8f62.jpg', 'https://phimimg.com/upload/vod/20230925-1/db1b126c4686bc9bf0d2bb78fce3990e.jpg', '<p>Bộ phim kể về Kya Clark - một cô gái bị gia đình bỏ rơi, lớn lên ở vùng đầm lầy phía nam thị trấn Barkley Cove vào những năm 50. Khi cảnh sát của thị trấn bị phát hiện đã qua đời, người ta bắt đầu dồn mọi mối nghi ngờ vào Kya.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daisy Edgar-Jones","avatar":""},{"name":"Taylor John Smith","avatar":""},{"name":"Harris Dickinson","avatar":""},{"name":"Michael Hyatt","avatar":""},{"name":"Sterling Macer Jr.","avatar":""},{"name":"Jojo Regina","avatar":""},{"name":"Garret Dillahunt","avatar":""},{"name":"Ahna O''Reilly","avatar":""},{"name":"David Strathairn","avatar":""},{"name":"Eric Ladin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324312);
