INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-soi-trong-dem', 'Ma Sói Trong Đêm', 'Werewolf by Night', 'https://phimimg.com/upload/vod/20230925-1/1143ee1cc6046151059dd2ffa3b50442.jpg', 'https://phimimg.com/upload/vod/20230925-1/191ba27001d3a1ca3d1c7917f5a537ad.jpg', '<p>Vào một đêm tối tăm và u ám, một đoàn thợ săn quái vật bí mật xuất hiện từ trong bóng tối và tập hợp tại Đền Bloodstone điềm báo sau cái chết của thủ lĩnh của họ. Trong một đài tưởng niệm kỳ lạ và rùng rợn về cuộc đời của nhà lãnh đạo, những người tham dự bị đẩy vào một cuộc cạnh tranh bí ẩn và chết chóc để giành lấy một di vật quyền năng - một cuộc săn lùng cuối cùng sẽ đưa họ đối mặt với một con quái vật nguy hiểm. Lấy cảm hứng từ những bộ phim kinh dị của những năm 1930 và 1940, đặc biệt làm lạnh nhằm mục đích gợi lên cảm giác sợ hãi và rùng rợn, với nhiều hồi hộp và sợ hãi trên đường đi khi chúng ta khám phá một góc mới của Vũ trụ Điện ảnh Marvel.</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gael García Bernal","avatar":""},{"name":"Laura Donnelly","avatar":""},{"name":"Harriet Sansom Harris","avatar":""},{"name":"Kirk R. Thatcher","avatar":""},{"name":"Eugenie Bondurant","avatar":""},{"name":"Leonardo Nam","avatar":""},{"name":"Daniel J. Watts","avatar":""},{"name":"Al Hamacher","avatar":""},{"name":"Carey Jones","avatar":""},{"name":"David Silverman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324312);
