INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nguyen-sinh-ton', 'Kỷ Nguyên Sinh Tồn', 'Vesper', 'https://phimimg.com/upload/vod/20230925-1/9cd14d42cbbf63956f6a99edc65aa210.jpg', 'https://phimimg.com/upload/vod/20230925-1/be76eaaba2489e98ba934aa801fc23aa.jpg', '<p>Sau sự sụp đổ của hệ sinh thái Trái đất, Vesper, một cô gái 13 tuổi đang vật lộn để tồn tại với người cha bị liệt của mình, gặp một người phụ nữ có một bí mật, người sẽ buộc cô phải sử dụng trí thông minh, sức mạnh và khả năng hack sinh học của mình để chiến đấu cho khả năng của một tương lai.</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Raffiella Chapman","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Rosy McEwen","avatar":""},{"name":"Richard Brake","avatar":""},{"name":"Melanie Gaydos","avatar":""},{"name":"Edmund Dehn","avatar":""},{"name":"Matvej Buravkov","avatar":""},{"name":"Marijus Demiskis","avatar":""},{"name":"Markas Eimontas","avatar":""},{"name":"Titas Rukas","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324312);
