INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-kiem-cua-47-lang-nhan', 'Thanh Kiếm Của 47 Lãng Nhân', 'Blade of the 47 Ronin', 'https://phimimg.com/upload/vod/20230925-1/5f983eff0349d446bf2647202e1c8f06.jpg', 'https://phimimg.com/upload/vod/20230925-1/5544fdde8900636ac3d92a65dee1937e.jpg', '<p>Trong phần tiếp theo của &quot;47 Ronin&quot;, một lớp chiến binh mới xuất hiện trong gia tộc Samurai để giữ thanh kiếm được săn đón không rơi vào tay kẻ xấu.</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anna Akana","avatar":""},{"name":"Mark Dacascos","avatar":""},{"name":"Teresa Ting","avatar":""},{"name":"Dustin Nguyen","avatar":""},{"name":"Dan Southworth","avatar":""},{"name":"Yoshi Sudarso","avatar":""},{"name":"Akira Koieyama","avatar":""},{"name":"Nino Furuhata","avatar":""},{"name":"Luna Fujimoto","avatar":""},{"name":"Chikako Fukuyama","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324312);
