INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-sieu-thu-dc', 'Liên Minh Siêu Thú DC', 'DC League of Super-Pets', 'https://phimimg.com/upload/vod/20230925-1/d0c33f0cd19f8f4e5a9d6d6c87d58ddb.jpg', 'https://phimimg.com/upload/vod/20230925-1/a66ff1c7610ffc72bb28aa649bd12a6b.jpg', '<p>Trong “Liên Minh Siêu Thú DC”, Siêu Cún Krypto và Superman là cặp bài trùng không thể tách rời, cùng sở hữu những siêu năng lực tương tự và cùng nhau chiến đấu chống lại tội phạm tại thành phố Metropolis. Khi Superman và những thành viên của Liên Minh Công Lý bị bắt cóc, Krypto phải thuyết phục cậu chàng Ace luộm thuộm, nàng Heo PB, Rùa Merton và Sóc Chip khai phá những sức mạnh tiềm ẩn và cùng nhau giải cứu các siêu anh hùng. “Liên Minh Siêu Thú DC” có sự góp giọng của bộ đôi ngôi sao nổi tiếng bậc nhất Hollywood Dwayne Johnson (lồng tiếng cho Siêu cún Krypto) và Kevin Hart (Superman). Đặc biệt, tài tử Keanu Reeves sẽ đảm nhận những câu thoại chất lừ đến từ Batman.</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Kevin Hart","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Keanu Reeves","avatar":""},{"name":"Kate McKinnon","avatar":""},{"name":"Vanessa Bayer","avatar":""},{"name":"Natasha Lyonne","avatar":""},{"name":"Diego Luna","avatar":""},{"name":"Jameela Jamil","avatar":""},{"name":"Marc Maron","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324312);
