INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyet-tam-chia-tay', 'Quyết Tâm Chia Tay', 'Decision to Leave', 'https://phimimg.com/upload/vod/20230925-1/cbc75e7120eb2cd20564d6599f422cbd.jpg', 'https://phimimg.com/upload/vod/20230925-1/a7bb64bc1389b0276ffad72456557ecb.jpg', '<p>Thám tử Hae Joon được phân công nhiệm vụ điều tra nguyên nhân xung quanh cái chết của một người đàn ông khi leo núi. Cuộc truy tìm dẫn anh đến gặp Seo Rae - vợ của nạn nhân. Tuy nhiên, từ việc nghi ngờ, Hae Joon dần có tình cảm với người phụ nữ bí ẩn với cuộc sống khép kín này. Mối quan hệ rắc rối và tình cảm nhập nhằng khiến anh ngày càng lún sâu vào vụ án.</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Tang Wei","avatar":""},{"name":"Park Hae-il","avatar":""},{"name":"Lee Jung-hyun","avatar":""},{"name":"Go Kyung-pyo","avatar":""},{"name":"Park Yong-woo","avatar":""},{"name":"Kim Shin-young","avatar":""},{"name":"Yoo Seung-mok","avatar":""},{"name":"Jung Yi-seo","avatar":""},{"name":"Jung Young-sook","avatar":""},{"name":"Lee Hak-ju","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324312);
