INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-chang-va-moi-tinh-voi-co-sinh-vien', 'Anh Chàng Và Mối Tình Với Cô Sinh Viên', 'Doblado', 'https://phimimg.com/upload/vod/20230925-1/109165728ac9be1adcce7adeb03e5a9a.jpg', 'https://phimimg.com/upload/vod/20230925-1/67502d75e9b3e7999b40f960e5e50e12.jpg', '<p>Ban ngày là sinh viên đại học, ban đêm là gái mại dâm cao cấp, cuộc sống hai mặt của Jaira trở nên nguy hiểm khi cô bắt đầu phải lòng khách hàng của mình.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Denise Esteban","avatar":""},{"name":"Mark Anthony Fernandez","avatar":""},{"name":"Josef Elizalde","avatar":""},{"name":"Kat Dovey","avatar":""},{"name":"Stephanie Raz","avatar":""},{"name":"Jastine Lim","avatar":""},{"name":"Kier Legaspi","avatar":""},{"name":"Jiad Arroyo","avatar":""},{"name":"Johnny Revilla","avatar":""},{"name":"Mickey Ferriols","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324312);
