INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-va-trinh', 'Em và Trịnh', 'Em and Trinh', 'https://phimimg.com/upload/vod/20230925-1/07699d3afce57f47c1a1db39b70342df.jpg', 'https://phimimg.com/upload/vod/20230925-1/eef793ff5cae00020556442ef6970703.jpg', '<p>Tác phẩm xoay quanh cuộc đời Trịnh Công Sơn từ thời trẻ đến lúc trung niên trong khoảng những năm 1960-1990, điểm nhấn là câu chuyện giữa cố nhạc sĩ và cô gái Dao Ánh.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Lương Anh Vũ","avatar":""},{"name":"Phạm Nguyễn Lan Thy","avatar":""},{"name":"Hoàng Hà","avatar":""},{"name":"Trần Lực","avatar":""},{"name":"Bùi Lan Hương","avatar":""},{"name":"Samuel An","avatar":""},{"name":"Nakatani Akari","avatar":""},{"name":"Phạm Nhật Linh","avatar":""},{"name":"Chiều Xuân","avatar":""},{"name":"Trọng Trinh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324312);
