INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-canh-khan-cap', 'Hạ Cánh Khẩn Cấp', 'Emergency Declaration', 'https://phimimg.com/upload/vod/20230925-1/9926fa6d4da24daf2d3b1c34f4fb6fb5.jpg', 'https://phimimg.com/upload/vod/20230925-1/597f41e2b727dda9cfbafec6c74ab34f.jpg', '<p>Hạ Cánh Khẩn Cấp quy tụ dàn diễn viên đình đám bậc nhất xứ Hàn, bao gồm Song Kang-ho, Lee Byung-hun, Jeon Do-yeon, Kim Nam-Gil và Yim Si-wan, Park Hae-Joon. Bộ phim xoay quanh chuyến bay mang số hiệu KI501 của hãng hàng không Sky Korea, khởi hành từ sân bay quốc tế Incheon tới Honolulu, Hawaii. Không lâu sau khi máy bay cất cánh, một hành khách bắt đầu có những biểu hiện lạ và tử vong trước sự bàng hoàng của mọi người. Một virus lạ với tốc độ lây lan chóng mặt đã xâm nhập lên máy bay, tất cả chìm trong hỗn loạn và sợ hãi. Trong tình huống ngàn cân treo sợi tóc, một tuyên bố đề nghị hạ cánh khẩn cấp được đưa ra. Trên độ cao 8,534 mét, số phận của hơn 150 con người bao gồm cả các hành khách và phi hành đoàn sẽ ra sao?</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Kang-ho","avatar":""},{"name":"Lee Byung-hun","avatar":""},{"name":"Jeon Do-yeon","avatar":""},{"name":"Kim Nam-gil","avatar":""},{"name":"Yim Si-wan","avatar":""},{"name":"Kim So-jin","avatar":""},{"name":"Park Hae-jun","avatar":""},{"name":"Kim Bo-min","avatar":""},{"name":"Hyun Bong-sik","avatar":""},{"name":"Woo Mi-hwa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324312);
