INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-nhan-emily', 'Tội Nhân Emily', 'Emily the Criminal', 'https://phimimg.com/upload/vod/20230925-1/b8a56055e74df8aec103608f57158942.jpg', 'https://phimimg.com/upload/vod/20230925-1/638f5f4a9048ac8bbcd1d61da14647e7.jpg', '<p>Emily (Aubrey Plaza) đang gánh khoản nợ nhỏ và bị loại khỏi thị trường việc làm do tiền án tiền sự nhỏ. Tuyệt vọng vì thu nhập, cô thực hiện một hợp đồng béo bở mờ ám là &quot;người mua hàng giả&quot;, mua hàng bằng thẻ tín dụng ăn cắp được cung cấp bởi một người trung gian đẹp trai và lôi cuốn tên là Youcef (Theo Rossi). Đối mặt với hàng loạt cuộc phỏng vấn xin việc không có kết quả, Emily sớm nhận ra mình bị quyến rũ bởi tiền mặt nhanh chóng và những thú vui bất chính của chủ nghĩa tư bản thị trường chợ đen, và ngày càng quan tâm đến người cố vấn Youcef của cô. Họ cùng nhau ấp ủ một kế hoạch đưa công việc kinh doanh của mình lên một tầm cao mới ở Los Angeles.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aubrey Plaza","avatar":""},{"name":"Theo Rossi","avatar":""},{"name":"Megalyn Echikunwoke","avatar":""},{"name":"Gina Gershon","avatar":""},{"name":"Jonathan Avigdori","avatar":""},{"name":"Bernardo Badillo","avatar":""},{"name":"Craig Stark","avatar":""},{"name":"Brandon Sklenar","avatar":""},{"name":"John Billingsley","avatar":""},{"name":"Kim Yarbrough","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
