INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-roi-tu-than', 'Cú Rơi Tử Thần', 'Fall', 'https://phimimg.com/upload/vod/20230925-1/46f0dad2eb71ea3edf0c95bbca30e93b.jpg', 'https://phimimg.com/upload/vod/20230925-1/9c708bd0b14219994d05a666ca5f19b5.jpg', '<p>Hai người bạn thân là Becky và Hunter trên hành trình chữa lành nỗi đau của quá khứ đã cố gắng chinh phục tòa tháp radio và kết quả là họ đã bị mắc kẹt ở độ cao 2,000 foot, tương đương hơn 600 mét.</p>', 'Full', 1, 'single', 'completed', 24, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Grace Caroline Currey","avatar":""},{"name":"Virginia Gardner","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Mason Gooding","avatar":""},{"name":"Jasper Cole","avatar":""},{"name":"Darrell Dennis","avatar":""},{"name":"Julia Pace Mitchell","avatar":""},{"name":"Bamm Ericsen","avatar":""},{"name":"Evie Mann","avatar":""},{"name":"Joseph Mann","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324312);
