INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cang-gia-kim-thuat-su-scar-bao-thu', 'Cang Giả Kim Thuật Sư: Scar Báo Thù', 'Fullmetal Alchemist: The Revenge of Scar', 'https://phimimg.com/upload/vod/20230925-1/de605b74884ca96a05b8c3cef46fc746.jpg', 'https://phimimg.com/upload/vod/20230925-1/38b3713a14aaddb51d218c0cd85ef900.jpg', '<p>Trong phần sau của bộ phim điện ảnh đầu tiên, anh em nhà Elric gặp đối thủ khó nhằn nhất từ trước tới nay – kẻ giết người hàng loạt đơn độc có vết sẹo lớn trên trán.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ryosuke Yamada","avatar":""},{"name":"Atomu Mizuishi","avatar":""},{"name":"Tsubasa Honda","avatar":""},{"name":"Dean Fujioka","avatar":""},{"name":"Jun Fubuki","avatar":""},{"name":"Naohito Fujiki","avatar":""},{"name":"Mackenyu","avatar":""},{"name":"Yuina Kuroshima","avatar":""},{"name":"Misako Renbutsu","avatar":""},{"name":"Hiroshi Tachi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324312);
