INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-tham', 'Lòng Tham', 'Greed', 'https://phimimg.com/upload/vod/20230925-1/31657ed172b67d5e72d4920f5f009b18.jpg', 'https://phimimg.com/upload/vod/20230925-1/f971dc6ad2eee30ddc073217139c021d.jpg', '<p>Khi một cặp vợ chồng phát hiện ra mình trúng số độc đắc, họ lên kế hoạch rời đi trong im lặng trong thị trấn buồn ngủ của mình.</p>', 'Full', 1, 'single', 'completed', 23, 2022, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Nadine Lustre","avatar":""},{"name":"Diego Loyzaga","avatar":""},{"name":"Jeffrey Quizon","avatar":""},{"name":"Jacqueline Yu","avatar":""},{"name":"Krissha Viaje","avatar":""},{"name":"Raul Morit","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
