INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-lung-gian-diep', 'Săn Lùng Gián Điệp', 'Hunt', 'https://phimimg.com/upload/vod/20230925-1/6ac19f84e1405fc37af589fd18c9cfb9.jpg', 'https://phimimg.com/upload/vod/20230925-1/da2cd00ff5411acb568d41eadf030f45.jpg', '<p>Hunt lấy bối cảnh Hàn Quốc thập niên 1980, giai đoạn mà chính quyền quân sự nước này siết chặt các vấn đề liên quan đến chiến lược an ninh quốc gia. Nhân vật chính của phim là hai hai điệp viên Hàn Quốc (Lee Jung Jae và Jung Woo Sung) nhận nhiệm vụ lật mặt một gián điệp Triều Tiên trong tổ chức của mình. Trong quá trình làm nhiệm vụ, họ đã nảy sinh nghi ngờ và bắt đầu điều tra lẫn nhau.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Jung-jae","avatar":""},{"name":"Jung Woo-sung","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"Heo Sung-tae","avatar":""},{"name":"Go Youn-jung","avatar":""},{"name":"Kim Jong-soo","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Lim Hyung-kook","avatar":""},{"name":"Jung Kyung-soon","avatar":""},{"name":"Jung Jae-sung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324312);
