INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-dao-duc-vong', 'Hòn Đảo Dục Vọng', 'Island of Desire', 'https://phimimg.com/upload/vod/20230925-1/94ea9ed916bc78d16bb22c646b709a12.jpg', 'https://phimimg.com/upload/vod/20230925-1/3156531d9ba79dc2c06f062366201f6e.jpg', '<p>Một y tá được phân công làm việc tại một hòn đảo tên là Isla Bato, nơi đàn ông đối xử với phụ nữ bằng dục vọng. Khi trải nghiệm sự điên rồ của mọi người, cô lên kế hoạch thoát khỏi hòn đảo.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Christine Bermas","avatar":""},{"name":"Sean de Guzman","avatar":""},{"name":"Jela Cuenca","avatar":""},{"name":"Rash Flores","avatar":""},{"name":"Sheree","avatar":""},{"name":"Massimo Scofield","avatar":""},{"name":"Quinn Carrillo","avatar":""},{"name":"Jim Pebanco","avatar":""},{"name":"Andrea Del Rosario","avatar":""},{"name":"Rolando Inocencio","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324312);
