INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gioi-han-truy-lung', 'Giới Hạn Truy Lùng', 'Limit', 'https://phimimg.com/upload/vod/20230925-1/c01f058f31d82bb6a9450a86e1a0b930.jpg', 'https://phimimg.com/upload/vod/20230925-1/21ffadb2b862341a590eeb685c0a25d9.jpg', '<p>Câu chuyện về nữ cảnh sát tài năng So Eun (Lee Jung Hyun), sau những vụ bắt cóc bí ẩn, cô đã đóng giả làm mẹ của một nạn nhân để tiếp cận bọn bắt cóc. Sau khi thân phận bị bại lộ, So Eun vô tình con trai cô rơi vào nguy hiểm. Không chỉ có rượt đuổi, đối đầu trực diện, phim còn là màn đấu trí không khoan nhượng, từng đường đi nước bước của bọn tội phạm đều được tính toán kỹ lưỡng khiến nữ chính nhiều phen khốn đốn.</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Jung-hyun","avatar":""},{"name":"Moon Jeong-hee","avatar":""},{"name":"Jin Seo-yeon","avatar":""},{"name":"Park Myung-hoon","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"Park Kyung-hye","avatar":""},{"name":"Im Chul-hyung","avatar":""},{"name":"Oh Min-seok","avatar":""},{"name":"Kim Ha-eon","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324312);
