INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-bop-nghet', 'Tình Yêu Bóp Nghẹt', 'No Limit', 'https://phimimg.com/upload/vod/20230925-1/c3e8b384175f00a7761084695250f4b1.jpg', 'https://phimimg.com/upload/vod/20230925-1/ecc4613ee90b12b242d334176a42162d.jpg', '<p>Roxana Aubrey quyết định bỏ dở việc học và trốn khỏi cuộc sống ở Paris để tham gia khóa học lặn miễn phí ở miền nam nước Pháp. Cô nhanh chóng bị kéo vào một cuộc sống đạt đến những độ sâu mới do sức nặng của đại dương chìm xuống.</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Camille Rowe","avatar":""},{"name":"Sofiane Zermani","avatar":""},{"name":"César Domboy","avatar":""},{"name":"Laurent Fernandez","avatar":""},{"name":"Zacharie Chasseriaud","avatar":""},{"name":"Natalie Mitson","avatar":""},{"name":"Muriel Combeau","avatar":""},{"name":"Alexandre Poole","avatar":""},{"name":"Hassam Ghancy","avatar":""},{"name":"Laurence Porteil","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
