INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-rong-den-tim-lai-anh-sang', 'Huyền Thoại Rồng Đen: Tìm Lại Ánh Sáng', 'Mortal Kombat Legends: Snow Blind', 'https://phimimg.com/upload/vod/20230925-1/cacdc930f2c933c7557d07ef902c97bd.jpg', 'https://phimimg.com/upload/vod/20230925-1/5637a8b018ebb07c053b92caaa156d39.jpg', '<p>Quyết tâm chiếm lấy Earthrealm, Kano tàn ác tấn công hết thị trấn này đến thị trấn khác với sự hỗ trợ của ba lính đánh thuê Rồng Đen máu lạnh. Kẻ không phục tùng sẽ bị tiêu diệt nhưng có một thanh niên không chịu quỳ gối trước Kano: Kenshi.</p>', 'Full', 1, 'hoathinh', 'completed', 22, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Manny Jacinto","avatar":""},{"name":"David Wenham","avatar":""},{"name":"Artt Butler","avatar":""},{"name":"Yuri Lowenthal","avatar":""},{"name":"Sumalee Montano","avatar":""},{"name":"Patrick Seitz","avatar":""},{"name":"Keith Silverstein","avatar":""},{"name":"Courtenay Taylor","avatar":""},{"name":"Imari Williams","avatar":""},{"name":"Debra Wilson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
