INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-soi-bien', 'Chiến Dịch Sói Biển', 'Operation Seawolf', 'https://phimimg.com/upload/vod/20230925-1/e2817125e856812e22d80174b2ea3c60.jpg', 'https://phimimg.com/upload/vod/20230925-1/6c5cd1a155e4910b6533ade567f16216.jpg', '<p>Trong những ngày cuối cùng của Thế chiến thứ hai, Đức, tuyệt vọng tìm mọi cách cuối cùng để đánh bại các cường quốc đồng minh, đã tìm đến những vũ khí và binh lính cuối cùng còn lại của họ. Hải quân Đức và những chiếc U-Boat cuối cùng còn sót lại được thành lập cùng nhau để thực hiện một nhiệm vụ cuối cùng đầy tuyệt vọng - nhiệm vụ tấn công Tổ quốc Hoa Kỳ, được gọi là Chiến dịch Seawolf. Thuyền trưởng Hans Kessler, một chỉ huy tàu ngầm hoa râm từ cả hai Thế chiến, được gọi vào phục vụ để thực hiện thành công một nhiệm vụ và giúp xoay chuyển tình thế của cuộc chiến.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Aaron Courteau","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Andrew Stecker","avatar":""},{"name":"Hiram A. Murray","avatar":""},{"name":"Apostolos Gliarmis","avatar":""},{"name":"Luke Steinborn","avatar":""},{"name":"Edgar Damatian","avatar":""},{"name":"Cody Fleury","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-t