INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('out-of-the-blue', 'Out of the Blue', 'Out of the Blue', 'https://phimimg.com/upload/vod/20230925-1/8a1e966aa6948f6b70fc39baa105aedd.jpg', 'https://phimimg.com/upload/vod/20230925-1/f3b445a5aa7f6cf001f3c518edd38314.jpg', '<p>Sau thời gian ngồi tù sau một vụ tấn công, Connor Bates hiện làm việc trong thư viện và dành thời gian rảnh để chạy, bơi lội và cố gắng ghép lại thế giới của mình lại với nhau. Khi anh gặp Marilyn Chambers, vợ của một doanh nhân giàu có, họ va chạm vào một mối quan hệ tình cảm và thể xác mãnh liệt, nhanh chóng leo thang thành cuộc nói chuyện vu vơ về vụ sát hại chồng cô.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Diane Kruger","avatar":""},{"name":"Ray Nicholson","avatar":""},{"name":"Hank Azaria","avatar":""},{"name":"Chase Sui Wonders","avatar":""},{"name":"Victor Slezak","avatar":""},{"name":"Pamela Jayne Morgan","avatar":""},{"name":"Gia Crovatin","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324312);
