INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-nguoi-go', 'Cậu Bé Người Gỗ', 'Pinocchio', 'https://phimimg.com/upload/vod/20230925-1/7d6f2ea627b6d2ec412850f221cb203f.jpg', 'https://phimimg.com/upload/vod/20230925-1/cc07147b94095b4e415da14e550c84f4.jpg', '<p>Một phim do người thật đóng&nbsp; và CGI kể lại câu chuyện yêu dấu của một con rối gỗ, người bắt đầu cuộc phiêu lưu ly kỳ để trở thành một cậu bé thực sự. Các nhân vật khác bao gồm Geppetto, người thợ mộc, người đã khắc và đối xử với Pinocchio như thể cậu là con trai thực sự của mình; Dế Jiminy, người vừa là người hướng dẫn Pinocchio vừa là&nbsp;</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Tom Hanks","avatar":""},{"name":"Benjamin Evan Ainsworth","avatar":""},{"name":"Angus Wright","avatar":""},{"name":"Cynthia Erivo","avatar":""},{"name":"Sheila Atim","avatar":""},{"name":"Lorraine Bracco","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Jamie Demetriou","avatar":""},{"name":"Giuseppe Battiston","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324312);
