INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuoc-lai-tinh-yeu', 'Chuộc Lại Tình Yêu', 'Redeeming Love', 'https://phimimg.com/upload/vod/20230925-1/61ecbd9148dbd6bed6558051120dafca.jpg', 'https://phimimg.com/upload/vod/20230925-1/73b1adf163f4ecb6d38bd874cdd14a32.jpg', '<p>Redeeming Love là một bộ phim lãng mạn Thiên chúa giáo phương Tây của Mỹ năm 2022 do D. J. Caruso đạo diễn, người đồng viết kịch bản với Francine Rivers. Bộ phim dựa trên cuốn tiểu thuyết cùng tên năm 1991 của Rivers và lấy bối cảnh ở Miền Tây Cổ của Mỹ trong cơn sốt vàng California.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Abigail Cowen","avatar":""},{"name":"Tom Lewis","avatar":""},{"name":"Eric Dane","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Logan Marshall-Green","avatar":""},{"name":"Nina Dobrev","avatar":""},{"name":"Livi Birch","avatar":""},{"name":"Jamie Lee O''Donnell","avatar":""},{"name":"Wu Ke-Xi","avatar":""},{"name":"Brandon Auret","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
