INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-cap-dem-3', 'Bọ Cạp Đêm 3', 'Scorpio Nights 3', 'https://phimimg.com/upload/vod/20230925-1/c12edcce8defb053434ca9988b4ea1d8.jpg', 'https://phimimg.com/upload/vod/20230925-1/3975bfefc36fb14450daf5e2feaa01ce.jpg', '<p>Hành vi quan hệ tình dục của một cặp vợ chồng trẻ bị nam thanh niên chứng kiến qua một cái hố. Khi người vợ quyến rũ anh ta, họ bắt đầu ngoại tình. Sự hỗn loạn xảy ra khi người chồng biết về họ.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Christine Bermas","avatar":""},{"name":"Mark Anthony Fernandez","avatar":""},{"name":"Gold Aceron","avatar":""},{"name":"Sheree","avatar":""},{"name":"Allison Smith","avatar":""},{"name":"Julio Diaz","avatar":""},{"name":"Amanda Avecilla","avatar":""},{"name":"Aica Veloso","avatar":""},{"name":"Gabe Pineda","avatar":""},{"name":"Yumi Garcia","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324312);
