INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-cu-bi-mat', 'Căn Cứ Bí Mật', 'Secret Headquarters', 'https://phimimg.com/upload/vod/20230925-1/6555e68c5f3ac3d45a21bcba50e04f64.jpg', 'https://phimimg.com/upload/vod/20230925-1/415763a84512b99679ad4a731503a328.jpg', '<p>Trong khi đi chơi sau giờ học, Charlie và những người bạn khám phá ra trụ sở của siêu anh hùng mạnh nhất thế giới ẩn bên dưới nhà của anh ấy. Khi những kẻ xấu tấn công, họ phải hợp sức để bảo vệ trụ sở chính và cứu thế giới.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Walker Scobell","avatar":""},{"name":"Momona Tamada","avatar":""},{"name":"Keith L. Williams","avatar":""},{"name":"Abigail James Witherspoon","avatar":""},{"name":"Jesse Williams","avatar":""},{"name":"Jessie Mueller","avatar":""},{"name":"Dustin Ingram","avatar":""},{"name":"Charles Melton","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324312);
