INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-khu-o-chuot', 'Cô Gái Khu Ổ Chuột', 'Silip Sa Apoy', 'https://phimimg.com/upload/vod/20230925-1/ea214d6e1bf8faa827b3f60a6dc06a0e.jpg', 'https://phimimg.com/upload/vod/20230925-1/a33661fb57f625203024e3b037311a0a.jpg', '<p>Hãy xem qua cuộc sống của một bà nội trợ bất hạnh tìm thấy tình yêu nồng nàn từ người hàng xóm của mình và mối tình của họ đã đưa họ đến gần lửa hơn như thế nào.</p>', 'Full', 1, 'single', 'completed', 22, 2022, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Angeli Khang","avatar":""},{"name":"Sid Lucero","avatar":""},{"name":"Paolo Gumabao","avatar":""},{"name":"Jela Cuenca","avatar":""},{"name":"Dexter Doria","avatar":""},{"name":"Massimo Scofield","avatar":""},{"name":"John Drey Guevarra","avatar":""},{"name":"Juvz Tesalona","avatar":""},{"name":"Jun Teves","avatar":""},{"name":"Angel Savellano","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
