INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-do', 'Cám Dỗ', 'Serve the People', 'https://phimimg.com/upload/vod/20230925-1/ecccd9a2efc397620f2d3fad7578f277.jpg', 'https://phimimg.com/upload/vod/20230925-1/1d0989fa5e311089ba96b5e3532d9048.jpg', '<p>Mu-kwang tình nguyện trở thành cảnh sát bếp của Sa-taek, chỉ huy sư đoàn, với ước mơ thành công. Một ngày nọ, Mu-kwang tình cờ gặp Su-ryeon, người vợ trẻ và xinh đẹp của chỉ huy. Chẳng bao lâu, anh ấy cảm thấy bị cô ấy thu hút mạnh mẽ.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yeon Woo-jin","avatar":""},{"name":"Ji An","avatar":""},{"name":"Cho Seong-ha","avatar":""},{"name":"Jeong Gyu-su","avatar":""},{"name":"Kim Ji-chul","avatar":""},{"name":"Kim Byeong-man","avatar":""},{"name":"Jang Hae-min","avatar":""},{"name":"Park Jung-eon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
