INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cam-do', 'Cám Dỗ', 'Serve the People', 'cám dỗ serve the people yeon woo-jin ji an cho seong-ha jeong gyu-su kim ji-chul kim byeong-man jang hae-min park jung-eon ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-ban-tia-qua-trang', 'Lính Bắn Tỉa: Quạ Trắng', 'Sniper: The White Raven', 'https://phimimg.com/upload/vod/20230925-1/da24184ddec369f50162d9c048bc732f.jpg', 'https://phimimg.com/upload/vod/20230925-1/c30f6e56b70627b6f343b19d55d6b3b9.jpg', '<p>Mykola là một người theo chủ nghĩa hòa bình lập dị muốn có ích cho nhân loại. Khi chiến tranh bắt đầu ở Donbass, thế giới ngây thơ của Mykola đang sụp đổ khi các chiến binh giết chết người vợ đang mang thai của anh và đốt nhà của anh thành tro bụi. Đã bình phục, anh đưa ra một quyết định quan trọng và được gia nhập một đại đội bắn tỉa. Gặp phải kẻ giết vợ, anh vỡ òa trong cảm xúc và dàn xếp “khủng bố bắn tỉa” cho kẻ thù. Anh ta được cứu khỏi cái chết vô nghĩa bởi người hướng dẫn của mình, người cũng bị trọng thương. Cái chết của một người bạn để lại “vết sẹo” và Mykola sẵn sàng hy sinh mạng sống của mình.</p>', 'Full', 1, 'single', 'completed', 32, 2022, 'Vietsub', 'HD', 'Ukraina', 0, '[{"name":"Pavlo Aldoshyn","avatar":""},{"name":"Maryna Koshkina","avatar":""},{"name":"Andrii Mostrenko","avatar":""},{"name":"Roman Semysal","avatar":""},{"name":"Roman Yasinovskyi","avatar":""},{"name":"Oleh Shulha","avatar":""},{"name":"Yehor Kozlov","avatar":""},{"name":"Yevhen Chernykov","avatar":""},{"name":"Vadym Kurylko","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
