INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dien-thoai-den', 'Điện Thoại Đen', 'The Black Phone', 'https://phimimg.com/upload/vod/20230925-1/c21d18eb8e6d9d7c47424bb35516c01b.jpg', 'https://phimimg.com/upload/vod/20230925-1/390224eb6222f61708b43ab082405d49.jpg', '<p>Finney Shaw, một cậu bé 13 tuổi nhút nhát nhưng thông minh, bị một kẻ giết người tàn bạo bắt cóc và bị mắc kẹt trong một tầng hầm cách âm, nơi tiếng la hét không được sử dụng nhiều. Khi một chiếc điện thoại bị ngắt kết nối trên tường bắt đầu đổ chuông, Finney phát hiện ra rằng anh có thể nghe thấy giọng nói của những nạn nhân trước đây của kẻ giết người. Và họ đã cố gắng đảm bảo rằng những gì đã xảy ra với họ không xảy ra với Finney</p>', 'Full', 1, 'single', 'completed', 16, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mason Thames","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Madeleine McGraw","avatar":""},{"name":"Jeremy Davies","avatar":""},{"name":"E. Roger Mitchell","avatar":""},{"name":"Troy Rudeseal","avatar":""},{"name":"James Ransone","avatar":""},{"name":"Miguel Cazarez Mora","avatar":""},{"name":"Rebecca Clarke","avatar":""},{"name":"J. Gaven Wilde","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324312);
