INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-sat-nhan-dua-tre-co-the-chet', 'Kẻ Sát Nhân: Đứa Trẻ Có Thể Chết', 'The Killer: A Girl Who Deserves to Die', 'https://phimimg.com/upload/vod/20230925-1/4a250032b9b07004e5dfbe65cfaa97a8.jpg', 'https://phimimg.com/upload/vod/20230925-1/cbfd1b3f3698be0e1951f74707b32231.jpg', '<p>Kẻ Sát Nhân: Đứa Trẻ Có Thể Chết - The Killer: A Girl Who Deserves To Die người đàn ông Bang Ui Gang một kẻ giết người, nay đã rửa tay gác kiếm về sống yên bình. Nhưng, chưa được bao lâu thì anh bị cuốn vào một vụ án đặt biệt, đó chính là bảo vệ cô học sinh Kim Jun Ji. Một trẻ vị thành niên bị bạo hành đến nỗi các vết sẹo đầy khắp cả người. Sau cuộc gặp gỡ với Bang Ui Gang, Kim Jun Ji chỉ có thể tin tưởng vào anh giúp mình thoát khỏi cuộc sống chết chóc này.</p>', 'Full', 1, 'single', 'completed', 23, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Hyuk","avatar":""},{"name":"Lee Seo-young","avatar":""},{"name":"Bruce Khan","avatar":""},{"name":"Bang Eun-jeong","avatar":""},{"name":"Lee Seung-joon","avatar":""},{"name":"Shin Seung-hwan","avatar":""},{"name":"Hong Seo-joon","avatar":""},{"name":"Lee Chae-young","avatar":""},{"name":"Yoo Seo-jin","avatar":""},{"name":"Choi Ki-seob","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324312);
