INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-dan-ma-quai', 'Cư Dân Ma Quái', 'The Inhabitant', 'https://phimimg.com/upload/vod/20230925-1/47cf9f05aa01996d2a962abab605972e.jpg', 'https://phimimg.com/upload/vod/20230925-1/c9727679bb74392b178ddbbd80913a08.jpg', '<p>Giống như bất kỳ cô gái tuổi teen nào khác, Tara chỉ mới học xong trung học - nhưng cha và mẹ cô dường như xa cách một cách kỳ lạ. Giữa một loạt vụ giết người bằng rìu khủng khiếp gần đó, Tara nhìn thấy những thực thể đáng sợ, buộc cô phải đặt câu hỏi về sự tỉnh táo của chính mình và tổ tiên gây sốc.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Odessa A''zion","avatar":""},{"name":"Leslie Bibb","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Lizze Broadway","avatar":""},{"name":"Michael Cooper Jr.","avatar":""},{"name":"Mary Buss","avatar":""},{"name":"Jackson Dean Vincent","avatar":""},{"name":"Kenneisha Thompson","avatar":""},{"name":"Ryan Francis","avatar":""},{"name":"Hartleigh Buwick","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324312);
