INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-quai-vat', 'Cổng Quái Vật', 'The Offering', 'https://phimimg.com/upload/vod/20230925-1/9ed20fd4ae0042927e69e8985e34e56b.jpg', 'https://phimimg.com/upload/vod/20230925-1/4e153872388115c563055a6edba2fb1e.jpg', '<p>Sau sự mất tích của một cô gái trẻ Do Thái, con trai của một giám đốc tang lễ Hasidic trở về nhà cùng người vợ đang mang thai với hy vọng hòa giải với cha mình. Họ không hề biết rằng ngay bên dưới họ trong nhà xác gia đình, một ác quỷ cổ xưa với những kế hoạch nham hiểm nhằm vào đứa trẻ chưa sinh đang ẩn nấp bên trong một xác chết bí ẩn.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nick Blood","avatar":""},{"name":"Emm Wiseman","avatar":""},{"name":"Paul Kaye","avatar":""},{"name":"Allan Corduner","avatar":""},{"name":"Daniel Ben Zenou","avatar":""},{"name":"Sofia Weldon","avatar":""},{"name":"Anton Trendafilov","avatar":""},{"name":"Meglena Karalambova","avatar":""},{"name":"Jonathan Yunger","avatar":""},{"name":"Velizar Binev","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324312);
