INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-mau-o-tiffany', 'Phép Màu Ở Tiffany', 'Something from Tiffany''s', 'https://phimimg.com/upload/vod/20230925-1/78b8af5a56cf47268fc7fd98c2275b6c.jpg', 'https://phimimg.com/upload/vod/20230925-1/07c6c02db2c6d337f3938028d934ee34.jpg', '<p>Không phải mọi cô gái đều mơ ước nhận được... thứ gì đó từ Tiffany&#39;s sao? Trên Đại lộ số 5 ở Thành phố New York, nơi không gì có thể so sánh được với sự kỳ diệu và phấn khích của những ngày nghỉ lễ, nơi đường phố rực rỡ ánh đèn và cửa sổ chói lóa, một chiếc hộp đặc biệt của Tiffany có thể thay đổi cuộc đời một con người. Hoặc nhiều cuộc sống. Rachel và Gary đủ hạnh phúc nhưng chưa hoàn toàn sẵn sàng cho cam kết lớn lao đó. Ethan và Vanessa, bức tranh hoàn hảo, sắp chính thức ra mắt. Khi một sự kết hợp đơn giản giữa các món quà khiến tất cả các con đường của họ gặp nhau, nó sẽ tạo ra một loạt khúc mắc và những khám phá bất ngờ dẫn họ đến nơi họ thực sự có ý nghĩa. Bởi vì tình yêu - giống như cuộc sống - đầy những điều bất ngờ.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zoey Deutch","avatar":""},{"name":"Kendrick Sampson","avatar":""},{"name":"Ray Nicholson","avatar":""},{"name":"Leah Sava Jeffries","avatar":""},{"name":"Shay Mitchell","avatar":""},{"name":"Jojo T. Gibbs","avatar":""},{"name":"Javicia Leslie","avatar":""},{"name":"Chido Nwokocha","avatar":""},{"name":"Connor Hines","avatar":""},{"name":"Rose Abdoo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324312);
