INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('scrooge-bai-hat-giang-sinh', 'Scrooge: Bài Hát Giáng Sinh', 'Scrooge: A Christmas Carol', 'https://phimimg.com/upload/vod/20230925-1/ef13d48619de30003fc19f582db42656.jpg', 'https://phimimg.com/upload/vod/20230925-1/c8557319f4b635790f8df7e4ee510467.jpg', '<p>Vào một đêm Giáng sinh lạnh giá, kẻ hà tiện ích kỷ Ebenezer Scrooge chỉ còn một đêm để đối mặt với quá khứ của mình và thay đổi tương lai trước khi hết thời gian.</p>', 'Full', 1, 'hoathinh', 'completed', 24, 2022, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Luke Evans","avatar":""},{"name":"Olivia Colman","avatar":""},{"name":"Jessie Buckley","avatar":""},{"name":"Johnny Flynn","avatar":""},{"name":"Fra Fee","avatar":""},{"name":"Giles Terera","avatar":""},{"name":"Trevor Dion Nicholas","avatar":""},{"name":"James Cosmo","avatar":""},{"name":"Jonathan Pryce","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324312);
