INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-choi-mao-hiem', 'Cuộc Chơi Mạo Hiểm', 'Poker Face', 'https://phimimg.com/upload/vod/20230925-1/511ea597f9ffb1db1452923326a06157.jpg', 'https://phimimg.com/upload/vod/20230925-1/8efc0043373072f7719ebff5e7f99a11.jpg', '<p>Trò chơi poker đặt cược cao hàng năm giữa những người bạn thời thơ ấu trở nên hỗn loạn khi người dẫn chương trình là tỷ phú công nghệ tiết lộ một kế hoạch phức tạp nhằm trả thù cho cách họ đã phản bội ông trong nhiều năm. Nhưng khi kế hoạch của anh ta lộ ra, một nhóm trộm ấp ủ kế hoạch đột nhập vào dinh thự vì nghĩ rằng nó trống rỗng. Những người bạn cũ nhanh chóng hợp tác với nhau và những năm chơi trò chơi đã giúp họ giành chiến thắng trong một đêm kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Russell Crowe","avatar":""},{"name":"Liam Hemsworth","avatar":""},{"name":"RZA","avatar":""},{"name":"Brooke Satchwell","avatar":""},{"name":"Aden Young","avatar":""},{"name":"Steve Bastoni","avatar":""},{"name":"Daniel MacPherson","avatar":""},{"name":"Elsa Pataky","avatar":""},{"name":"Jack Thompson","avatar":""},{"name":"Jacqueline McKenzie","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324312);
