INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-vo-hanh-dong', 'Những Cô Vợ Hành Động', 'Jealous and Furious', 'null', 'https://phimimg.com/upload/vod/20230925-1/340da3b38bfb1a5d88ffcc9105881f45.jpg', '<p>Phim Những cô vợ hành động nói về bộ ba Đạt - Thái - Tùng là những ông chồng trẻ vô âu vô lo rất ham chơi, sự vô tư đó vô tình đã làm tổn thương những người vợ của họ. Thậm chí họ còn trốn vợ vụng trộm với những chân dàu xinh đẹp. Ngược lại với tâm trạng vui vẻ của các ông chồng, Hân - Vy - Thư luôn trong tình trạng tức giận, bồn chồn, lo lắng. Đến lúc những bà vợ không thể chịu đựng được họ đã lên kế hoạch trả thù trước khi buông tay, chấm dứt mọi tổn thương.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Huỳnh Phương","avatar":""},{"name":"Thai Vu","avatar":""},{"name":"Vinh Râu","avatar":""},{"name":"Thu Quỳnh","avatar":""},{"name":"Phan Hoàng Kim","avatar":""},{"name":"Pham Thi Minh Huyen","avatar":""},{"name":"Mai Thúy Vy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324312);
