INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-ngon-oppy', 'Ngủ Ngon Oppy', 'Good Night Oppy', 'https://phimimg.com/upload/vod/20230925-1/b25a040b6a4cca1bc2bce7fb7e5c18b8.jpg', 'https://phimimg.com/upload/vod/20230925-1/3e208d6633dde5a3137aeb4d74c77e25.jpg', '<p>Câu chuyện có thật đầy cảm hứng về Cơ hội, một tàu thám hiểm được gửi lên Sao Hỏa để thực hiện sứ mệnh kéo dài 90 ngày nhưng cuối cùng lại sống sót được 15 năm. Hãy theo dõi hành trình đột phá của Cơ hội trên sao Hỏa và mối liên kết đáng chú ý giữa robot và con người ở cách xa hàng triệu dặm.</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Angela Bassett","avatar":""},{"name":"Steve Squyres","avatar":""},{"name":"Jennifer Trosper","avatar":""},{"name":"Rob Manning","avatar":""},{"name":"Kobie Boykins","avatar":""},{"name":"Ashitey Trebi-Ollennu","avatar":""},{"name":"Doug Ellison","avatar":""},{"name":"Abigail Fraeman","avatar":""},{"name":"Vandi Verma","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324312);
