INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-tham-tu-enola-holmes-2', 'Nữ Thám Tử Enola Holmes 2', 'Enola Holmes 2', 'https://phimimg.com/upload/vod/20230925-1/78ee5c987d7f4a23a8c1fc2af43d9d1f.jpg', 'https://phimimg.com/upload/vod/20230925-1/59237b929f2a3d6ad4e9eeacb606d8af.jpg', '<p>Enola đảm nhận vụ án chính thức đầu tiên với tư cách thám tử. Nhưng để phá giải bí ẩn về một cô gái mất tích, cô sẽ cần sự giúp đỡ của bạn bè cũng như anh trai Sherlock.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Millie Bobby Brown","avatar":""},{"name":"Henry Cavill","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Louis Partridge","avatar":""},{"name":"Susan Wokoma","avatar":""},{"name":"Adeel Akhtar","avatar":""},{"name":"Sharon Duncan-Brewster","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Sofia Stavrinou","avatar":""},{"name":"John Parshall","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324312);
