INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-knight-gia-mao', 'Thám Tử Knight: Giả Mạo', 'Detective Knight: Rogue', 'https://phimimg.com/upload/vod/20230925-1/d590a29c3bd561ce7916ecee818a0954.jpg', 'https://phimimg.com/upload/vod/20230925-1/81378ee4f6cf3571d4430bc0745e388e.jpg', '<p>Khi Los Angeles chuẩn bị cho Halloween, những tên cướp có vũ trang đeo mặt nạ đã làm đồng đội của thám tử James Knight bị thương nặng trong cuộc đấu súng sau một vụ cướp. Khi Knight đang bị truy đuổi gắt gao, bọn cướp chạy trốn khỏi L.A. để đến New York, nơi quá khứ đen tối của vị thám tử va chạm với vụ án hiện tại của anh ta và đe dọa xé nát thế giới của anh ta…trừ khi sự chuộc lỗi có thể đòi lại Knight trước.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Beau Mirchoff","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Corey Large","avatar":""},{"name":"Jimmy Jean-Louis","avatar":""},{"name":"Michael Eklund","avatar":""},{"name":"Johnny Messner","avatar":""},{"name":"Cody Kearsley","avatar":""},{"name":"Keeya King","avatar":""},{"name":"Dax Campbell","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324312);
