INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-knight-gia-mao', 'Thám Tử Knight: Giả Mạo', 'Detective Knight: Rogue', 'thám tử knight: giả mạo detective knight: rogue bruce willis beau mirchoff lochlyn munro corey large jimmy jean-louis michael eklund johnny messner cody kearsley keeya king dax campbell ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-yeu-dung-so', 'Em Yêu, Đừng Sợ', 'Don''t Worry Darling', 'https://phimimg.com/upload/vod/20230925-1/45ce84b49ecbd9a493db2b9fa64aec04.jpg', 'https://phimimg.com/upload/vod/20230925-1/dbf0e5178bbff82c7ccb83973c439019.jpg', '<p>Trái ngược với tựa đề lãng mạn, Don’t Worry Darling lại là tác phẩm thuộc thể loại chính kịch - giật gân vô cùng kịch tính và có phần điên rồ. Trong phim, Florence Pugh và Harry Styles hóa thân vào cặp vợ chồng trẻ Alice và Jack trong những ngày mặn nồng nhất cuộc hôn nhân của mình. Cả hai sống tại Victory - một cộng đồng dành cho gia đình những người đàn ông tham gia dự án tuyệt mật Victory Project. Được khắc họa như một “chốn thiên đường” đích thực với chuẩn mực sống hoàn hảo, nơi đây đáp ứng tất thảy mọi nhu cầu của các cư dân, cùng nhau hướng tới mục tiêu “thay đổi thế giới”. Điều duy nhất các cư dân Victory được yêu cầu, chính là không bao giờ đặt câu hỏi về nguyên nhân của dự án Victory. Vậy nhưng, khi những rạn nứt trong cuộc sống xuất hiện, Alice không thể ngừng nghi ngờ nơi đây, tất cả những việc đang xảy ra xung quanh cô và lý do của chúng. Một bí mật kinh hoàng vượt ngoài tưởng tượng của Alice đang chờ cô vạch trần sau bức màn nhung đẹp đẽ kia.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Florence Pugh","avatar":""},{"name":"Harry Styles","avatar":""},{"name":"Chris Pine","avatar":""},{"name":"Olivia Wilde","avatar":""},{"name":"Gemma Chan","avatar":""},{"name":"KiKi Layne","avatar":""},{"name":"Nick Kroll","avatar":""},{"name":"Kate Berlant","avatar":""},{"name":"Timothy Simons","avatar":""},{"name":"Asif Ali","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324312);
