INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-xuyen-quoc-gia', 'Đặc Vụ Xuyên Quốc Gia', 'Confidential Assignment 2: International', 'https://phimimg.com/upload/vod/20230925-1/f5449f286e6808182a5183c2dda0e78e.jpg', 'https://phimimg.com/upload/vod/20230925-1/ffaa224edcab9c8c163086f645984882.jpg', '<p>Theo chân Rim Chul Ryung quay trở lại Hàn Quốc để truy đuổi một tổ chức tội phạm tàn bạo và bí mật. Anh ấy hợp tác một lần nữa với Kang Jin Tae, người tình nguyện làm việc với Triều Tiên để trở lại đội điều tra sau khi một sai lầm đưa anh ấy vào bộ phận tội phạm mạng.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Hyun Bin","avatar":""},{"name":"Yoo Hae-jin","avatar":""},{"name":"Yoona","avatar":""},{"name":"Daniel Henney","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Jang Young-nam","avatar":""},{"name":"Lee Hae-yeong","avatar":""},{"name":"Park Hoon","avatar":""},{"name":"Im Sung-jae","avatar":""},{"name":"Yoon Sang-hwa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324312);
