INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-son-co-mo', 'Quan Sơn Cổ Mộ', 'Coffin Mountain Ancient Tomb', 'https://phimimg.com/upload/vod/20230925-1/f69241200efdf4ebf95047f2a41045b1.jpg', 'https://phimimg.com/upload/vod/20230925-1/9320d6685f0751b0dd848a274690b333.jpg', '<p>Trương Tam Gia đã đến làng Long Đường cùng với đệ tử của mình. Để tránh rắc rối và tai họa ở Ngạc Châu, Trương Tam Gia và những người khác quyết tâm tìm ra ngôi mộ của Ma cô. Nhóm người đã vượt qua nhiều khó khăn, cuối cùng cũng tìm thấy ngôi mộ, nhưng Trương Tam Gia phát hiện ra rằng vụ trộm mộ thực chất là một cái bẫy được và sắp có một âm mưu lớn hơn đằng sau kho báu trong lăng mộ của Ma cô</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yuen Biao","avatar":""},{"name":"Wu Hao","avatar":""},{"name":"Wang Yunhan","avatar":""},{"name":"Wang Hongqian","avatar":""},{"name":"David Dai","avatar":""},{"name":"Shang Na","avatar":""},{"name":"Xie Changding","avatar":""},{"name":"Rong Weifeng","avatar":""},{"name":"Han Mengwu","avatar":""},{"name":"Wang Zirun","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324312);
