INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-mang-nuoc-my', 'Án Mạng Nước Mỹ', 'American Murderer', 'https://phimimg.com/upload/vod/20230925-1/b194b3607d7e640bc3c9e0043d5b748d.jpg', 'https://phimimg.com/upload/vod/20230925-1/2b312b55b6781f55decae07e584977be.jpg', '<p>Câu chuyện có thật về cách kẻ lừa đảo lôi cuốn Jason Derek Brown kiếm tiền từ lối sống xa hoa của mình thông qua một loạt vụ lừa đảo. Lần theo dấu vết của Brown: Lance Leising, một đặc vụ FBI kiên cường quyết tâm đưa Brown vào sau song sắt. Khi quỹ của Brown cạn kiệt và quá khứ bắt kịp anh ta, anh ta vạch ra kế hoạch phức tạp nhất của mình, đọ sức với Leising trong một trò chơi mèo vờn chuột chết người - và trở thành kẻ chạy trốn khó tin nhất và khó nắm bắt nhất trong danh sách truy nã gắt gao nhất của FBI.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Pelphrey","avatar":""},{"name":"Ryan Phillippe","avatar":""},{"name":"Idina Menzel","avatar":""},{"name":"Shantel VanSanten","avatar":""},{"name":"Jacki Weaver","avatar":""},{"name":"Laura Dennis","avatar":""},{"name":"Paul Schneider","avatar":""},{"name":"Moisés Arias","avatar":""},{"name":"Kevin Corrigan","avatar":""},{"name":"Kylie Rohead","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
