INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lucio-urtubia-con-nguoi-hanh-dong', 'Lucio Urtubia: Con người hành động', 'A Man of Action', 'https://phimimg.com/upload/vod/20230925-1/cd5fc6f698cdd347fd5d0c14432f8cb3.jpg', 'https://phimimg.com/upload/vod/20230925-1/989c3e9db6fa3e583e036c0fe2374874.jpg', '<p>Lấy cảm hứng từ cuộc đời của Lucio Urtubia, hãy khám phá nhân vật của cái gọi là &#39;Robin Hood&#39; theo chủ nghĩa vô chính phủ, người điều hành một hoạt động làm tiền giả huyền thoại ở Paris, khiến anh ta rơi vào tầm ngắm của ngân hàng lớn nhất nước Mỹ, khi anh ta kiếm được một số tiền khổng lồ tiền bằng cách giả mạo séc du lịch để đầu tư vào những mục tiêu mà anh ta tin tưởng.</p>', 'Full', 1, 'single', 'completed', 22, 2022, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Juan José Ballesta","avatar":""},{"name":"Miki Esparbé","avatar":""},{"name":"Luis Callejo","avatar":""},{"name":"Liah O''Prey","avatar":""},{"name":"Alexandre Blazy","avatar":""},{"name":"Josean Bengoetxea","avatar":""},{"name":"Philip Schurer","avatar":""},{"name":"Daniel Chamorro","avatar":""},{"name":"Ben Temple","avatar":""},{"name":"Jacobo Marrero","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
