INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lucio-urtubia-con-nguoi-hanh-dong', 'Lucio Urtubia: Con người hành động', 'A Man of Action', 'lucio urtubia: con người hành động a man of action juan josé ballesta miki esparbé luis callejo liah o''prey alexandre blazy josean bengoetxea philip schurer daniel chamorro ben temple jacobo marrero ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-su-2', 'Đạo Sư 2', 'Demon Catcher 2', 'https://phimimg.com/upload/vod/20230923-1/12bbbc56094d1866cb63b34dba88e911.jpg', 'https://phimimg.com/upload/vod/20230923-1/54393273620e70e44ed043d85da3f70d.jpg', '<p>Đạo sư 2 là một giai thoại được lưu truyền trong dân gian do một người kể chuyện kể lại, kể về câu chuyện hào hùng của một thế hệ kỳ nhân Quan Sư Phụ, một người trượng nghĩa chuyên trừ gian diệt ác trong thời Trung Hoa Dân Quốc. Câu chuyện bắt đầu với hai tên trộm đào mộ lấy nhau vì ham giàu sang. Vào năm Trung Hoa Dân Quốc thứ 17, chiến tranh liên miên, dân chúng di tản, nhân vật chính vì lòng tốt mà thu thập hài cốt của một số người tị nạn, nhưng lại bị quy tội trộm cắp và buôn bán người, bị bỏ tù vì tội này. Tình cờ, Quan sư gia đi ngang qua, ông và Diệp Phi có mỗi giao tình lâu năm, để cứu Diệp Phi, tìm ra sự thật và giúp Diệp Phi thoát tội. Diệp Phi sùng bái Quan sư gia như thầy của mình, cùng ông đến sa mạc. Nhưng vì đoàn kịch xướng khúc, dẫn tới một hồi chuyện xưa đầy bi thương lại kinh diễm được chôn vùi trong sa mạc từ thời Đường</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Eric Wan","avatar":""},{"name":"Lin Fengye","avatar":""},{"name":"Liu Tianzuo","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Lang Feng","avatar":""},{"name":"Li Zhongyu","avatar":""},{"name":"Xie Ning","avatar":""},{"name":"Sun Yizhen","avatar":""},{"name":"Chen Yuyong","avatar":""},{"name":"Li Gaoji","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324312);
