INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-doc-dac-tu-mau-thien-linh-cai', 'Đảo Độc Đắc - Tử Mẫu Thiên Linh Cái', 'Jackpot Island - Kumanthong Returns', 'https://phimimg.com/upload/vod/20230923-1/f0cbbeca7d6533fb9770045ff4a0840d.jpg', 'https://phimimg.com/upload/vod/20230923-1/569b90b4eeb6a3b37f390a3a2781b98c.jpg', '<p>“Đảo độc đắc - Tử mẫu Thiên linh cái” tiếp tục gieo rắc nỗi ám ảnh lẫn loạt dấu hỏi lớn về một trong những loại bùa ngải đáng sợ của vùng Đông Nam Á.&nbsp; Ai mới thực sự là người đang “ẩn nấp” đằng sau gương mặt tà ác, quỷ dị và nắm giữ những bí mật kinh hoàng? Một hòn đảo chết chóc cùng sự xuất hiện bí ẩn rợn người của nhân ngư kì quái có liên quan gì đến loại bùa ngải tàn bạo và kinh hãi này?</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Trần Nghĩa","avatar":""},{"name":"Sam","avatar":""},{"name":"Hoa Hậu Tiểu Vy","avatar":""},{"name":"Trần Phong","avatar":""},{"name":"Minh Dự","avatar":""},{"name":"Phương Lan","avatar":""},{"name":"Tân Trề","avatar":""},{"name":"Lê Huỳnh","avatar":""},{"name":"Hoàng Yến Chibi","avatar":""},{"name":"Nguyễn Steven","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324312);
