INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-dang', 'Hiến Dâng', 'Devotion', 'https://phimimg.com/upload/vod/20230923-1/009f572f6ddc9e961fc3b560eab443d0.jpg', 'https://phimimg.com/upload/vod/20230923-1/6bfdadedef7fbfddf281df230f2a2687.jpg', '<p>Bộ phim kể câu chuyện xoay quanh 2 người đàn ông Jesse và Tom. Trong khi phần lớn nước Mỹ vẫn bị chia cắt bởi sự phân biệt chủng tộc, cả hai đã quyết tâm gia nhập lực lượng chiến đấu trong chiến tranh Triều Tiên để rồi trở thành một trong những phi công chạy cánh nổi tiếng nhất lịch sử Hải Quân Hoa Kỳ.</p>', 'Full', 1, 'single', 'completed', 15, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonathan Majors","avatar":""},{"name":"Glen Powell","avatar":""},{"name":"Christina Jackson","avatar":""},{"name":"Thomas Sadoski","avatar":""},{"name":"Daren Kagasoff","avatar":""},{"name":"Joe Jonas","avatar":""},{"name":"Spencer Neville","avatar":""},{"name":"Nick Hargrove","avatar":""},{"name":"Boone Platt","avatar":""},{"name":"Dean Denton","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324312);
