INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-truong', 'Cảnh Sát Trưởng', 'Mindcage', 'https://phimimg.com/upload/vod/20230923-1/bddef98004d48e812bdf4d1d1f315cdd.jpg', 'https://phimimg.com/upload/vod/20230923-1/ec07554a5119d27da4c1d91856b7f438.jpg', '<p>Các thám tử Jake Doyle (Martin Lawrence) và Mary Kelly (Melissa Roxburgh) tìm kiếm sự giúp đỡ của một kẻ giết người hàng loạt đang bị giam giữ tên là The Artist (John Malkovich) khi một kẻ giết người bắt chước tấn công. Trong khi Mary tìm kiếm manh mối trong tâm hồn thông minh nhưng vặn vẹo của The Artist, cô và Jake bị dụ vào một trò chơi mèo vờn chuột ma quái, chạy đua với thời gian để đi trước The Artist và kẻ sao chép của anh ta một bước.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Martin Lawrence","avatar":""},{"name":"Melissa Roxburgh","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Aiden Turner","avatar":""},{"name":"Jacob Grodnik","avatar":""},{"name":"Chris Mullinax","avatar":""},{"name":"Ritchie Montgomery","avatar":""},{"name":"Kira Reed Lorsch","avatar":""},{"name":"Jeremy Turner","avatar":""},{"name":"Cassandra Gava","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324312);
