INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duyen-ma', 'Duyên Ma', 'My Boyfriend Is A Ghost', 'null', 'https://phimimg.com/upload/vod/20230923-1/de24b95353563f2dfca650ddda686693.jpg', '<p>“Duyên Ma” bắt nguồn từ số phận kỳ lạ của Minh (Kiều Minh Tuấn) khi vô cớ trở thành ma và gặp Ngọc (Ngọc Trinh). Mọi chuyện sẽ chẳng có gì đặc biệt nếu Ngọc không gặp Minh và cùng với “ba cada 3 hồn ma” tinh nghịch nhưng tốt bụng giúp đỡ anh khỏi tâm hồn vô gia cư dần dần làm quen với việc làm ma. Tuy nhiên, bản chất kỳ diệu không bằng bản chất tình yêu, Ngọc và Minh yêu nhau. Từ đây đã “gây ra” biết bao rắc rối, nhất là khi có sự xuất hiện của hồn ma Bạch Cát bí ẩn.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Ngọc Trinh","avatar":""},{"name":"Kiều Minh Tuấn","avatar":""},{"name":"Phi Phung","avatar":""},{"name":"Hải Triều","avatar":""},{"name":"Loc Le","avatar":""},{"name":"La Thành","avatar":""},{"name":"Quỳnh Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324312);
