INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-quy-du', 'Mồi Quỷ Dữ', 'Prey for the Devil', 'https://phimimg.com/upload/vod/20230923-1/80f2f77cba063eb41b30dea49c2dcfd6.jpg', 'https://phimimg.com/upload/vod/20230923-1/944dca5dc192aedea25f3912913dc56b.jpg', '<p>“Mồi Quỷ Dữ” xoay quanh sơ Ann (do Jacqueline Byers thủ vai) bị kéo vào một cuộc chiến tại một Nhà Thờ Công Giáo trước thế lực quỷ ám đang ngày một hùng mạnh. Với khả năng chiến đấu với quỷ dữ, sơ Ann được phép thực hiện các buổi trừ tà dẫu cho các luật lệ xưa cũ chỉ cho phép Cha xứ thực hiện công việc này. Cùng với Cha Dante, sơ Ann chạm mặt một con quỷ dữ đang cố chiếm lấy linh hồn của một cô gái trẻ, và cũng có thể là kẻ đã ám lấy người mẹ quá cố của sơ. Sơ Ann dần nhận ra mối nguy đang đe dọa mình khủng khiếp thế nào, và cả lý do con quỷ dữ đó khao khát đoạt mạng cô.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jacqueline Byers","avatar":""},{"name":"Colin Salmon","avatar":""},{"name":"Christian Navarro","avatar":""},{"name":"Lisa Palfrey","avatar":""},{"name":"Nicholas Ralph","avatar":""},{"name":"Ben Cross","avatar":""},{"name":"Virginia Madsen","avatar":""},{"name":"Tom Forbes","avatar":""},{"name":"Velizar Binev","avatar":""},{"name":"Owen Davis","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324312);
