INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ma-do-thi', 'Chuyện Ma Đô Thị', 'Urban Myths', 'https://phimimg.com/upload/vod/20230923-1/81f64e16ec3519ff2a61584ce77a75ae.jpg', 'https://phimimg.com/upload/vod/20230923-1/ff434dc06d123ac454078ceaa78779b5.jpg', '<p>Xử lý những nỗi kinh hoàng sống động trong cuộc sống hàng ngày có thể dễ dàng gặp ở những địa điểm quen thuộc xung quanh các chủ thể như tiếng ồn giữa các tầng, đồ nội thất cũ, ma-nơ-canh và mạng xã hội.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Do-yoon","avatar":""},{"name":"Lee Yul-eum","avatar":""},{"name":"Lee Ho-won","avatar":""},{"name":"Choi Ye-won","avatar":""},{"name":"Lee Soo-min","avatar":""},{"name":"Exy","avatar":""},{"name":"Jung Won-chang","avatar":""},{"name":"Seola","avatar":""},{"name":"Lee Min-hyuk","avatar":""},{"name":"Lee Yeong-jin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324312);
