INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-uc', 'Hồi Ức', 'Remember', 'https://phimimg.com/upload/vod/20230923-1/b17c743961f6297c483cb5924054dc66.jpg', 'https://phimimg.com/upload/vod/20230923-1/14c723a084fa8d72baddfc8ee4513a60.jpg', '<p>Pil-Ju, một bệnh nhân của Alzheimer ở độ tuổi 80, người đã mất cả gia đình trong thời kỳ thuộc địa Nhật Bản, và cống hiến cả cuộc trả thù trọn đời trước khi ký ức biến mất, và một chàng trai trẻ ở độ tuổi 20, người giúp anh ta.</p>', 'Full', 1, 'single', 'completed', 17, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Sung-min","avatar":""},{"name":"Nam Joo-hyuk","avatar":""},{"name":"Park Geun-hyung","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Yoon Je-moon","avatar":""},{"name":"Song Young-chang","avatar":""},{"name":"Moon Chang-gil","avatar":""},{"name":"Choi Min-chul","avatar":""},{"name":"Nam Moon-chul","avatar":""},{"name":"Yang Hyun-min","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
