INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-voi-sitio-diablo', 'Cuộc Chiến Với Sitio Diablo', 'Sitio Diablo', 'https://phimimg.com/upload/vod/20230923-1/f98bc617ec1cde492ad917a7dc315313.jpg', 'https://phimimg.com/upload/vod/20230923-1/3b49804c27b3a831ea65d3acb8c18791.jpg', '<p>Câu chuyện về một cặp vợ chồng xã hội đen quay trở lại Sitio Diablo, một băng đảng xã hội đen ở Manila và thành lập một băng đảng mới, Illustrados. Một cuộc tắm máu sắp xảy ra khi họ phải đối mặt với băng đảng cũ của mình, Los Hijos Diablos, kẻ thống trị Sitio Diablo.</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"AJ Raval","avatar":""},{"name":"Kiko Estrada","avatar":""},{"name":"Benz Sangalang","avatar":""},{"name":"Joko Diaz","avatar":""},{"name":"Pio Balbuena","avatar":""},{"name":"Azi Acosta","avatar":""},{"name":"Cean Jr.","avatar":""},{"name":"Ace Raval","avatar":""},{"name":"Ruby Ruiz","avatar":""},{"name":"Karl Aquino","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
