INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-cuoi-gap-an-cuop', 'Ăn Cưới Gặp Ăn Cướp', 'Shotgun Wedding', 'https://phimimg.com/upload/vod/20230923-1/e5fea98e5872671861325c8dbdd9ee0a.jpg', 'https://phimimg.com/upload/vod/20230923-1/39f68c28ced4c2bc258394ff6ddf0ca6.jpg', '<p>Cặp đôi Darcy (Jennifer Lopez thủ vai) và Tom (Josh Duhamel thủ vai) mời cả gia đình và những người bạn thân thiết đến một hòn đảo tại Philippines để tham dự lễ cưới của cả hai. Những lo lắng, tranh cãi vụn vặt của Darcy và Tom khiến mối quan hệ của hai người rơi vào tình trạng “báo động” ngay trước hôn lễ. Và mọi chuyện trở nên tệ hại thực sự khi một băng cướp ập vào lễ cưới, bắt cóc tất cả khách mời làm con tin. Darcy và Tom phải cùng nhau đối đầu với băng cướp, để rồi nhận ra tình yêu của họ tuyệt vời đến nhường nào.</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Lopez","avatar":""},{"name":"Josh Duhamel","avatar":""},{"name":"Jennifer Coolidge","avatar":""},{"name":"Sônia Braga","avatar":""},{"name":"Lenny Kravitz","avatar":""},{"name":"D''Arcy Carden","avatar":""},{"name":"Cheech Marin","avatar":""},{"name":"Selena Tan","avatar":""},{"name":"Desmin Borges","avatar":""},{"name":"Pancho Cardena","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324312);
