INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-la-lung', 'Thế Giới Lạ Lùng', 'Strange World', 'https://phimimg.com/upload/vod/20230923-1/1c76cf5ed0f107df70b828dcff2c37d3.jpg', 'https://phimimg.com/upload/vod/20230923-1/1eeb44cc153303735356afda5d4d7f3d.jpg', '<p>Strange World kể về chuyến phiêu lưu “vượt không gian và thời gian” của gia đình Clade, một gia đình tập hợp toàn những huyền thoại trong làng phiêu lưu khám phá trong chuyến đi khó nhằn nhất của họ. Chuyến đi là cuộc hành trình đến một vùng đất kỳ lạ đầy rẫy những điều bí hiểm cùng những sinh vật chưa bao giờ xuất hiện. Đây cũng có thể sẽ là chuyến hành trình mang tới nhiều điều kỳ lạ nhất của Disney tới khản giả. Nhưng dường như thế giới kì bí ấy có thể còn dễ đương đầu hơn cả những khác biệt và xung đột trong chính gia đình này.</p>', 'Full', 1, 'hoathinh', 'completed', 22, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Dennis Quaid","avatar":""},{"name":"Jaboukie Young-White","avatar":""},{"name":"Gabrielle Union","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Jonathan Melo","avatar":""},{"name":"Abraham Benrubi","avatar":""},{"name":"Karan Soni","avatar":""},{"name":"Adelina Anthony","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324312);
