INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-khien-em-quay-cuong', 'Anh Khiến Em Quay Cuồng', 'Spin Me Round', 'https://phimimg.com/upload/vod/20230923-1/0c87aa27622173d067883050291e45ac.jpg', 'https://phimimg.com/upload/vod/20230923-1/502f29c963feb66d812a8c602a3a672f.jpg', '<p>Khi người quản lý của một chuỗi nhà hàng Ý giành được cơ hội tham gia chương trình giáo dục hòa nhập của nhượng quyền thương mại tại Ý, điều mà cô ấy nghĩ sẽ là một nơi nghỉ ngơi lãng mạn lại biến thành hỗn loạn và thảm họa.</p>', 'Full', 1, 'single', 'completed', 22, 2022, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Alison Brie","avatar":""},{"name":"Alessandro Nivola","avatar":""},{"name":"Fred Armisen","avatar":""},{"name":"Tim Heidecker","avatar":""},{"name":"Tricia Helfer","avatar":""},{"name":"Ayden Mayeri","avatar":""},{"name":"Ego Nwodim","avatar":""},{"name":"Jake Picking","avatar":""},{"name":"Debby Ryan","avatar":""},{"name":"Molly Shannon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324312);
