INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hang-xom-tot', 'Người Hàng Xóm Tốt', 'The Good Neighbor', 'https://phimimg.com/upload/vod/20230923-1/6b49c3aa6c3966dcad6df6bef2d57439.jpg', 'https://phimimg.com/upload/vod/20230923-1/82e88cf650c7721eed40de130c19470f.jpg', '<p>Một buổi tối ác mộng mở ra với David, cựu nhà báo của tờ New York Times, khi anh và người hàng xóm mới lạ Robert vô tình tông phải một cô gái đi xe đạp. Bực mình và mất phương hướng, David để Robert thuyết phục anh ta chạy trốn khỏi hiện trường và bỏ mặc cô gái cho đến chết, để bảo vệ sự nghiệp của anh ta. Robert không hề tỏ ra hối hận, và nhân danh tình bạn, anh làm những điều không thể diễn tả được để bảo vệ bí mật. Giờ đây, khi cảnh sát đang ráo riết truy lùng kẻ giết người đâm xe rồi bỏ chạy, mọi thứ bắt đầu vượt khỏi tầm kiểm soát khi tờ báo địa phương của David cử anh đến để đưa tin về câu chuyện nơi anh gặp Vanessa, em gái của cô gái đã khuất. Bất chấp hoàn cảnh và mong muốn sâu sắc của cô là tìm ra kẻ giết em gái mình, cả hai ngay lập tức có một mối liên hệ lãng mạn, điều này khiến David ngạc nhiên và ám ảnh, đồng thời đẩy Robert phải thực hiện những bước đi tàn bạo để giữ người bạn mới của mình cho riêng mình.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Luke Kleintank","avatar":""},{"name":"Eloise Smyth","avatar":""},{"name":"Bruce Davison","avatar":""},{"name":"Ieva Florence-Vīksne","avatar":""},{"name":"Regīna Razuma","avatar":""},{"name":"Guna Zariņa","avatar":""},{"name":"Kaspars Znotiņš","avatar":""},{"name":"Tom J. Benedict","avatar":""},{"name":"Ieva Segliņa","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324312);
