INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tre-huy-hoang', 'Tuổi Trẻ Huy Hoàng', 'The Fabelmans', 'https://phimimg.com/upload/vod/20230923-1/95ba7e761889b374a62e4402b778e756.jpg', 'https://phimimg.com/upload/vod/20230923-1/10356a246e8377ee16bdc9e484200df9.jpg', '<p>Dựa trên thời thơ ấu của đạo diễn huyền thoại Steven Spielberg, người lớn lên ở Arizona thời kỳ hậu Thế chiến thứ hai, bộ phim theo sau cuộc hành trình của một thanh niên tên Sammy Fabelman từ khi còn nhỏ đến lúc trưởng thành. Anh chàng đã khám phá ra bí mật của một gia đình tan vỡ cũng như cách sức mạnh của điện ảnh giúp chúng ta nhìn ra sự thật về nhau và chính thế giới xung quanh mình.</p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gabriel LaBelle","avatar":""},{"name":"Michelle Williams","avatar":""},{"name":"Paul Dano","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Judd Hirsch","avatar":""},{"name":"David Lynch","avatar":""},{"name":"Jeannie Berlin","avatar":""},{"name":"Julia Butters","avatar":""},{"name":"Keeley Karsten","avatar":""},{"name":"Sam Rechner","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
