INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-den-tu-dak-lak', 'CO GAI DEN TU DAK LAK', 'The Girl From Dak Lak', 'https://phimimg.com/upload/vod/20230923-1/7cdf3701647a98244b079f6a228d5769.jpg', 'https://phimimg.com/upload/vod/20230923-1/95265e17c965c6d3d4c9b7563f930510.jpg', '<p>Sương, một cô gái trẻ đến từ vùng nông thôn Việt Nam, di cư đến thành phố Hồ Chí Minh nhộn nhịp để làm việc tại một quán ăn địa phương cùng với hai công nhân nhập cư khác. Trong những bức tường lồng, cằn cỗi của quán ăn, ngày của họ tràn ngập những công việc lặp đi lặp lại và những giờ phút trống rỗng, tẻ nhạt. Tuy nhiên, đằng sau tấm màn thờ ơ, Sương phải đối mặt với tình thế khó xử mà cô sớm phải đối mặt với gia đình mình.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Huynh Thi Phuong","avatar":""},{"name":"Suong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
