INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-don-bi-an', 'Thực Đơn Bí Ẩn', 'The Menu', 'https://phimimg.com/upload/vod/20230923-1/0c069c7d08ce52f87bcb7cba9b77619f.jpg', 'https://phimimg.com/upload/vod/20230923-1/b2af70281f909b9fccfe491ed7407234.jpg', '<p>Một cặp đôi (Anya Taylor-Joy và Nicholas Hoult) tới một hòn đảo ven biển để thưởng thức ẩm thực tại một nhà hàng độc nhất và bếp trưởng (Ralph Fiennes) đã chuẩn bị cho mọi người một thực đơn hoành tráng, kèm theo một vài bất ngờ gây sốc.</p>', 'Full', 1, 'single', 'completed', 22, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ralph Fiennes","avatar":""},{"name":"Anya Taylor-Joy","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Hong Chau","avatar":""},{"name":"Janet McTeer","avatar":""},{"name":"Paul Adelstein","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Aimee Carrero","avatar":""},{"name":"Reed Birney","avatar":""},{"name":"Judith Light","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324312);
