INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('day-thuong-luu', 'Đáy Thượng Lưu', 'Triangle of Sadness', 'https://phimimg.com/upload/vod/20230923-1/2ce71b2ef19a798c73810f4ae3d37be5.jpg', 'https://phimimg.com/upload/vod/20230923-1/831e77f2b69d079463b41cbc93c2f377.jpg', '<p>Chuyến du thuyền dành cho giới siêu giàu bị chìm, khiến những người mắc kẹt khổ sở sinh tồn trên một hòn đảo, bao gồm một cặp đôi người mẫu thời trang nổi tiếng. Trớ trêu thay, kể từ đây đám nhà giàu nứt đố đổ vách lại thành lũ ăn hại dưới trướng một bà lao công rách nát chỉ vì bà này biết sinh tồn, nhóm lửa, bắt cá. Một bộ phim châm biếm hoàn hảo phơi bày khoảng cách giàu nghèo.</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Harris Dickinson","avatar":""},{"name":"Charlbi Dean","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Zlatko Burić","avatar":""},{"name":"Vicki Berlin","avatar":""},{"name":"Dolly de Leon","avatar":""},{"name":"Henrik Dorsin","avatar":""},{"name":"Iris Berben","avatar":""},{"name":"Jean-Christophe Folly","avatar":""},{"name":"Amanda Walker","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
