INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-qua-ca-vu-tru', 'Vượt Qua Cả Vũ Trụ', 'Beyond the Universe', 'https://phimimg.com/upload/vod/20230923-1/4fe43a5562547f7e73dc1ea3ef5ef98a.jpg', 'https://phimimg.com/upload/vod/20230923-1/fedc1d39c2d8aa7afb03359b7f3a5ffb.jpg', '<p>Trong khi chờ ghép thận, một nghệ sĩ piano trẻ tìm được mối liên hệ không ngờ tới với bác sĩ của cô và sự can đảm để thực hiện ước mơ âm nhạc.</p>', 'Full', 1, 'single', 'completed', 24, 2022, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Henry Zaga","avatar":""},{"name":"Giulia Be","avatar":""},{"name":"João Miguel","avatar":""},{"name":"Denise Del Vecchio","avatar":""},{"name":"Othon Bastos","avatar":""},{"name":"Viviane Araújo","avatar":""},{"name":"Diego Freitas","avatar":""},{"name":"Adriana Lessa","avatar":""},{"name":"Isabel Fillardis","avatar":""},{"name":"Leo Bahia","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
