INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-danh-ca-huyen-thoai', 'Nữ Danh Ca Huyền Thoại', 'Whitney Houston: I Wanna Dance with Somebody', 'https://phimimg.com/upload/vod/20230922-1/2d56e57c97d5836713744a54b7f5c8d3.jpg', 'https://phimimg.com/upload/vod/20230922-1/8837b1aaa36ccc94cf351c16115175f9.jpg', '<p>Lễ kỷ niệm vui vẻ, cảm động nhưng đau lòng về cuộc đời và âm nhạc của Whitney Houston, nữ ca sĩ nhạc pop R&amp;B vĩ đại nhất mọi thời đại. Theo dõi hành trình của cô từ vô danh đến siêu sao âm nhạc.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Naomi Ackie","avatar":""},{"name":"Ashton Sanders","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Nafessa Williams","avatar":""},{"name":"Lance A. Williams","avatar":""},{"name":"Tamara Tunie","avatar":""},{"name":"Clarke Peters","avatar":""},{"name":"Daniel Washington","avatar":""},{"name":"JaQuan Malik Jones","avatar":""},{"name":"Kris Sidberry","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
