INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-duong-hoa-bi', 'Âm Dương Hoạ Bì', 'Yin Yang Painted Skin', 'https://phimimg.com/upload/vod/20230922-1/189339db965584c890372a7b4945edc2.jpg', 'https://phimimg.com/upload/vod/20230922-1/71d0604a495d668dfd941b0ebd0c91b7.jpg', '<p>Phim kể về con rắn yêu Liqing quyến rũ mọi sinh vật. Để độc chiếm Wang Sheng, người đã yêu từ cái nhìn đầu tiên, cô bằng mọi cách vào nhà Wang Sheng và lên kế hoạch &quot;hoán đổi da&quot; với vợ của Wang Sheng, Xu Pan. Nhưng Liqing không ngờ rằng hành động của cô liên tục không vâng lời mẹ chồng, người thu thập linh hồn đàn ông, và sự ích kỷ của cô hoàn toàn khiến cô tức giận, khiến Wang Sheng hết lần này đến lần khác gặp nguy hiểm. , Liệu tình yêu giữa hai người có thể tiếp tục?</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Du Yuchen","avatar":""},{"name":"Liang Zhigang","avatar":""},{"name":"Li Muyun","avatar":""},{"name":"Sun Jiaolong","avatar":""},{"name":"Ben Ngai-Cheung Ng","avatar":""},{"name":"Clara Lee","avatar":""},{"name":"Du Shuai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324312);
