INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-con-thu', 'Những Con Thú', 'The Beasts', 'https://phimimg.com/upload/vod/20230922-1/538be192f76eb98b48a51a01acd02d40.jpg', 'https://phimimg.com/upload/vod/20230922-1/dc8607accb2e59053de3a0bcf818601a.jpg', '<p>Antoine và Olga, một cặp vợ chồng người Pháp, đã sống từ lâu tại một ngôi làng nhỏ ở Galicia. Họ thực hành nông nghiệp có trách nhiệm với môi trường và khôi phục những ngôi nhà bỏ hoang để tạo điều kiện cho việc tái định cư. Mọi thứ lẽ ra phải bình dị ngoại trừ việc họ phản đối dự án tuabin gió đã tạo ra xung đột nghiêm trọng với những người hàng xóm. Sự căng thẳng sẽ tăng lên đến mức không thể khắc phục được.</p>', 'Full', 1, 'single', 'completed', 20, 2022, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Marina Foïs","avatar":""},{"name":"Denis Ménochet","avatar":""},{"name":"Luis Zahera","avatar":""},{"name":"Diego Anido","avatar":""},{"name":"Marie Colomb","avatar":""},{"name":"Machi Salgado","avatar":""},{"name":"David Menéndez","avatar":""},{"name":"Luisa Merelas","avatar":""},{"name":"José Manuel Fernández y Blanco","avatar":""},{"name":"Federico Pérez Rey","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
