INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('beo-phi', 'Béo Phì', 'The Whale', 'https://phimimg.com/upload/vod/20230922-1/bdba2e4a43d86503499533959c8dc947.jpg', 'https://phimimg.com/upload/vod/20230922-1/f1850067654ff1ad761c4025fc02473c.jpg', '<p>Bộ phim xoay quanh Charlie, người mắc hội chứng rối loạn ăn uống sau tai nạn của người bạn đời, khiến cơ thể anh trở nên béo phì cùng cân nặng lên đến 600 pound (272 kg). Khi sức khỏe ngày càng xấu đi, anh cố gắng kết nối lại với cô con gái đã từng bị bỏ rơi của mình tên Ellie cũng như đấu tranh để tìm lại ý nghĩa cho cuộc sống.</p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brendan Fraser","avatar":""},{"name":"Sadie Sink","avatar":""},{"name":"Ty Simpkins","avatar":""},{"name":"Hong Chau","avatar":""},{"name":"Samantha Morton","avatar":""},{"name":"Sathya Sridharan","avatar":""},{"name":"Jacey Sink","avatar":""},{"name":"Alison Altman","avatar":""},{"name":"Wilhelm Schalaudek","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324312);
