INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-ly-man-ro', 'Công Lý Man Rợ', 'Savage Salvation', 'https://phimimg.com/upload/vod/20230922-1/f029208b3545746f0a2681a14eca964b.jpg', 'https://phimimg.com/upload/vod/20230922-1/79ed2066a9bc4bdc23d4e6e55a20ad6b.jpg', '<p>Sheriff Church ( Robert De Niro ) và Thám tử Zeppelin cố gắng giữ hòa bình trong thị trấn gồ ghề của họ, nơi mà hai lợi ích duy nhất của cư dân là nhà thờ hoặc oxycodone. Shelby John ( Jack Huston ) và Ruby Red mới đính hôn muốn có một khởi đầu mới. Họ quyết định cùng nhau có một gia đình và trở nên trong sạch, với sự hỗ trợ của Peter, anh rể của Ruby ( John Malkovich). Tuy nhiên, Shelby phát hiện ra Ruby yêu dấu của mình đã chết trước hiên nhà của họ trước khi cô ấy có thể thực hiện ước nguyện cuối cùng của mình: được rửa tội dưới dòng sông và rửa sạch tội lỗi trong quá khứ. Tràn đầy cơn thịnh nộ, Shelby dấn thân vào một cuộc giết người đầy thù hận để sửa chữa mọi sai trái mà mọi mắt xích trong chuỗi buôn bán ma túy đã gây ra cho Ruby. Không được trang bị gì ngoài adrenaline và một khẩu súng bắn đinh, Shelby lần lượt hạ gục những người chia bài và những kẻ nghiện ngập cho đến khi anh ta lên đến đỉnh.</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Huston","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Willa Fitzgerald","avatar":""},{"name":"Quavo","avatar":""},{"name":"Meadow Williams","avatar":""},{"name":"Swen Temmel","avatar":""},{"name":"Noel Gugliemi","avatar":""},{"name":"Jonny Orsini","avatar":""},{"name":"Dale Dickey","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324312);
