INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bai-hoc-sat-nhan', 'Bài Học Sát Nhân', 'Lesson in Murder', 'https://phimimg.com/upload/vod/20230922-1/569dfc7aca1a919c0f7c52a73094b283.jpg', 'https://phimimg.com/upload/vod/20230922-1/4a8c12cc3bc59d6de2a79276989e7969.jpg', '<p>Masaya Kakei là một chàng sinh viên đại học sống cuộc đời nhạt nhẽo. Một ngày nọ, cậu nhận được một lá thư từ kẻ giết người hàng loạt Yamato Haimura, kẻ bị kết án hàng loạt tội giết người và nhận án tử hình. Trong thư, Yamato chia sẻ mình thực hiện các vụ giết người khi điều hành một cửa hàng bánh mì. Lúc đó, Masaya đang là học sinh cấp Hai và là khách hàng quen tại cửa hàng. Yamato thú nhận đã thực hiện các vụ giết người, nhưng khẳng định mình không ra tay vụ số 9, và cầu xin Masaya cứu giúp. Và từ đây Masaya bắt đầu điều tra vụ án giết người cuối cùng để minh oan cho tên sát nhân.</p>', 'Full', 1, 'single', 'completed', 24, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sadawo Abe","avatar":""},{"name":"Koshi Mizukami","avatar":""},{"name":"Takanori Iwata","avatar":""},{"name":"Miho Nakayama","avatar":""},{"name":"Shimako Iwai","avatar":""},{"name":"Yu Miyazaki","avatar":""},{"name":"Hiroto Oshita","avatar":""},{"name":"Takuma Otoo","avatar":""},{"name":"Ryo Sato","avatar":""},{"name":"Takuji Suzuki","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324312);
