INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('one-piece-film-red', 'ONE PIECE FILM RED', 'ONE PIECE FILM RED', 'https://phimimg.com/upload/vod/20230922-1/61f686b92d5f29ed34ab75e998895b9b.jpg', 'https://phimimg.com/upload/vod/20230922-1/c787c4458260fac226233ec52ce4fa36.jpg', '<p><span style="font-family: ">Đây là phần phim thứ mười lăm trong loạt phim điện ảnh của One Piece, dựa trên bộ truyện manga nổi tiếng cùng tên của tác giả Eiichiro Oda. Phim được công bố lần đầu tiên vào ngày 21 tháng 11, 2021 để kỷ niệm sự ra mắt của tập phim thứ 1000 của bộ anime One Piece và sau khi tập phim này được phát sóng, đoạn quảng cáo và áp phích chính thức của phim cũng chính thức được công bố. Phim dự kiến sẽ phát hành vào ngày 6 tháng 8 năm 2022. Bộ phim được giới thiệu sẽ là hành trình xoay quanh một nhân vật nữ mới cùng với Shanks &quot;Tóc Đỏ&quot;.</span></p>', 'Full', 1, 'hoathinh', 'completed', 30, 2022, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kaori Nazuka","avatar":""},{"name":"Shuichi Ikeda","avatar":""},{"name":"Mayumi Tanaka","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Kazuki Yao","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324313);
