INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-song-mekong', 'Quái Vật Sông Mekong', 'The Lake', 'https://phimimg.com/upload/vod/20230921-1/5b852fd44bf5717598e68daf2536a43f.jpg', 'https://phimimg.com/upload/vod/20230921-1/4cd8b6c75519bc0d614d839631c49b66.jpg', '<p><span style="font-family: ">Đặt bối cảnh tại làng Buengkan, một tỉnh thuộc miền Bắc Thái Lan, Quái Vật Sông Mekong chính thức trở thành cơn ác mộng đối với dân làng và được coi là khơi nguồn của thảm họa ngay khi nó phá hủy mọi thứ và khiến mọi người bị mất kết nối hoàn toàn với thế giới bên ngoài. Sự kiện chấn động toàn Thái Lan này đã khiến các cơ quan chức năng cùng những nhà khoa học vô tình đến Bueng Kan để tiến hành nghiên cứu phải huy động tất cả các lực lượng để bắt con quái vật điên rồ này trước khi quá muộn.</span></p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Theerapat Sajakul","avatar":""},{"name":"Sushar Manaying","avatar":""},{"name":"Supansa Wedkama","avatar":""},{"name":"Thanachat Tullayachat","avatar":""},{"name":"Wanmai Chatborirak","avatar":""},{"name":"Vithaya Pansringarm","avatar":""},{"name":"Palita Chueasawathee","avatar":""},{"name":"Amnaj Wajaon","avatar":""},{"name":"Unruean Rachot","avatar":""},{"name":"Somphong Kunapratom","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324313);
