INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-bau-cu', 'Vua Bầu Cử', 'Kingmaker', 'https://phimimg.com/upload/vod/20230921-1/ddf8182754a1e91dc928ebc363bc74b9.jpg', 'https://phimimg.com/upload/vod/20230921-1/f36fb1c82b6f46158af29bdb49f92504.jpg', '<p>Seo Chang-dae, một chiến lược gia chiến dịch chính trị đầy tham vọng, người cuối cùng lại có những khác biệt về hệ tư tưởng với khách hàng hiện tại của mình, nhận được một lời đề nghị béo bở sẽ đặt lòng trung thành của anh ta dưới kính hiển vi.</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Sol Kyung-gu","avatar":""},{"name":"Lee Sun-kyun","avatar":""},{"name":"Yoo Jae-myung","avatar":""},{"name":"Jo Woo-jin","avatar":""},{"name":"Park In-hwan","avatar":""},{"name":"Bae Jong-ok","avatar":""},{"name":"Kim Sae-byuk","avatar":""},{"name":"Lee Hae-yeong","avatar":""},{"name":"Kim Sung-oh","avatar":""},{"name":"Jeon Bae-soo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324313);
