INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-thinh-no-tu-coi-am', 'Cơn Thịnh Nộ Từ Cõi Âm', 'The Accursed', 'https://phimimg.com/upload/vod/20230921-1/5747edb7f17c6178713e1b015ab44b4b.jpg', 'https://phimimg.com/upload/vod/20230921-1/55f1097bce987d5fade6409c386d321b.jpg', '<p><span style="font-family: ">Câu chuyện bắt đầu khi Elly được gia đình của một người bạn nhờ chăm sóc một người phụ nữ lớn tuổi sống trong một căn nhà gỗ hẻo lánh trong vài ngày. Nhận lời đồng ý, nhưng sau đó Elly phát hiện ra sự xuất hiện của một con quỷ đang ẩn náu trong người phụ nữ chỉ chực chờ để thoát ra. Cùng lúc đó, những bí ẩn về cái chết của mẹ cô dần dần được gợi mở bởi những cơn ác mộng mà Elly phải trải qua.</span></p>', 'Full', 1, 'single', 'completed', 14, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Grey","avatar":""},{"name":"Meg Foster","avatar":""},{"name":"Sarah Dumont","avatar":""},{"name":"Alexis Knapp","avatar":""},{"name":"Mena Suvari","avatar":""},{"name":"Sherman Augustus","avatar":""},{"name":"Marian Lee","avatar":""},{"name":"Olivia Day","avatar":""},{"name":"Kim Kendall","avatar":""},{"name":"Jennifer Silverstein","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324313);
