INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khat-mau', 'Khát Máu', 'Blood', 'https://phimimg.com/upload/vod/20230920-1/9677c10be64095a3b73fa9bc91162eaf.jpg', 'https://phimimg.com/upload/vod/20230920-1/4c4cc7f33f1057838e81f754c7004dbd.jpg', '<p>Jess, một người mẹ và y tá mới ly thân, chuyển đến ngôi nhà trang trại cũ của gia đình cô cùng với Tyler, cô con gái tuổi teen và Owen, cậu con trai tám tuổi của cô. Một đêm nọ, con chó của gia đình cảm nhận được thứ gì đó trong rừng và chạy đi tìm nó. Anh ta quay lại vài ngày sau đó và tấn công Owen, cắn anh ta một cách dã man trước khi Jess kịp can thiệp. Owen được đưa đến bệnh viện. Tình trạng của anh ấy trở nên tồi tệ hơn và không ai có thể hiểu tại sao... cho đến khi Jess phát hiện ra một phương pháp chữa trị đáng lo ngại...</p>', 'Full', 1, 'single', 'completed', 19, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michelle Monaghan","avatar":""},{"name":"Skeet Ulrich","avatar":""},{"name":"Finlay Wojtak-Hissong","avatar":""},{"name":"Skylar Morgan Jones","avatar":""},{"name":"June B. Wilde","avatar":""},{"name":"Erik Athavale","avatar":""},{"name":"Onalee Ames","avatar":""},{"name":"Danika Frederick","avatar":""},{"name":"Jerni Stewart","avatar":""},{"name":"Jennifer Rose Garcia","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324313);
