INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuong-va-tro', 'Xương và Tro', 'Ash and Bone', 'https://phimimg.com/upload/vod/20230920-1/bcb9e82491eaecb8eba9eb5594939d53.jpg', 'https://phimimg.com/upload/vod/20230920-1/494926acd057ca8a1a28b1e9685967cb.jpg', '<p>Bộ phim kể về một thiếu niên nổi loạn tên là Cassie Vanderbilt, tính cách hoang dã của cô ngày càng leo thang khi người cha chăm sóc của cô, Lucas quyết định đưa cô và người vợ mới Sarah ra khỏi thành phố để có khoảng thời gian gắn kết và vui vẻ bên nhau. Nhưng sau khi Cassie vượt qua gia đình McKinley khét tiếng, người ta mới thấy rõ rằng đôi khi mối nguy hiểm ẩn chứa trong đám cỏ dại, sẵn sàng tấn công bất cứ lúc nào.</p>', 'Full', 1, 'single', 'completed', 21, 2022, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jamie Bernadette","avatar":""},{"name":"Mel Novak","avatar":""},{"name":"Kaiti Wallen","avatar":""},{"name":"Harley Wallen","avatar":""},{"name":"Jimmy Doom","avatar":""},{"name":"Erika Hoveland","avatar":""},{"name":"Calhoun Koenig","avatar":""},{"name":"Angelina Danielle Cama","avatar":""},{"name":"Shane Hagedorn","avatar":""},{"name":"Michael James Alexander","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324313);
