INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-nhan-ma-ca-rong', 'Truyền Nhân Ma Cà Rồng', 'Dampyr', 'https://phimimg.com/upload/vod/20230920-1/f38e3a6f966e6968fc3d3166b43d6224.jpg', 'https://phimimg.com/upload/vod/20230920-1/0ff33f11705df7940ce662ca0dca3d58.jpg', '<p><span style="font-family: ">Mang trong mình dòng máu lai đặc biệt nhưng Harlan Draka lại không hề biết điều đó. Để rồi đến khi khám phá ra sức mạnh của bản thân cũng là lúc anh phải đối mặt với kẻ thù tàn bạo bậc nhất.</span></p>', 'Full', 1, 'single', 'completed', 23, 2022, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Wade Briggs","avatar":""},{"name":"Stuart Martin","avatar":""},{"name":"Frida Gustavsson","avatar":""},{"name":"Sebastian Croft","avatar":""},{"name":"Luke Roberts","avatar":""},{"name":"David Morrissey","avatar":""},{"name":"Radu Andrei Micu","avatar":""},{"name":"Ionut Grama","avatar":""},{"name":"Florin Frăţilă","avatar":""},{"name":"Mădălina Bellariu Ion","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324313);
