INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vet-nut-am-hon-trong-tranh', 'Vết Nứt: Âm Hồn Trong Tranh', 'Cracked', 'https://phimimg.com/upload/vod/20230920-1/0d20920ac856a06c0bde2270891ba551.jpg', 'https://phimimg.com/upload/vod/20230920-1/7eeb773692eb1e4a1ea6fae942e0bf0d.jpg', '<p>Ruja thừa kế bức tranh từ người cha đã khuất của cô và thuê Tim, một nhà phục chế nghệ thuật để sửa chữa nó, nhưng họ không biết rằng tác phẩm vô giá này đi kèm với nỗi kinh hoàng nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 23, 2022, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Chayanit Chansangavej","avatar":""},{"name":"Nichkhun Horvejkul","avatar":""},{"name":"Sahajak Boonthanakit","avatar":""},{"name":"Nutthacha Padovan","avatar":""},{"name":"Passalak Supasiripaisarn","avatar":""},{"name":"Byron Bishop","avatar":""},{"name":"Nualpanod Nat Khianpukdee","avatar":""},{"name":"Kunkanit Khumkrong","avatar":""},{"name":"Machida Sutthikulphanich","avatar":""},{"name":"Pranchanok Pansamdang","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324313);
