INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('son-hai-kinh-tam-biet-quai-thu', 'Sơn Hải Kinh: Tạm Biệt Quái Thú', 'Goodbye Monster', 'https://phimimg.com/upload/vod/20230919-1/dce8eeb38c6160119aa628c3fbeeecbe.jpg', 'https://phimimg.com/upload/vod/20230919-1/9489477bb5dd3eab4ff0bd9721d2d9ac.jpg', '<p><span style="font-family: ">Côn Luân Hư được che giấu trong sơn hải, nuôi dưỡng vô số sinh linh. Y quán Côn Luân ở nơi này có y thuật tinh tường nhưng lại có một loạ bệnh trăm ngàn năm qua không có thuốc chữa, đó là hắc linh. Y sư Bạch Trạch dốc sức đối kháng hắc linh, nhưng lại tự cho là đúng huỷ cả một hòn đảo, bị trục xuất khởi y quán. Bảy năm sau, y thuật của Bạch Trạch tiến bộ vượt bậc nhưng lại bị người khác xem thường, không thể hành y nên muốn mượn y quán để rửa mối nhục xưa. Nhưng trời xui đất khiến lại cùng cậu bé kỳ lân tự ti Tiểu Nghệ bước lên một hòn đảo hoang vu, bắt đầu một cuộc hành trình cứu rỗi.</span></p>', 'Full', 1, 'hoathinh', 'completed', 25, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Cong","avatar":""},{"name":"Kai Wang","avatar":""},{"name":"Zhang Zhe","avatar":""},{"name":"Zhang Lei","avatar":""},{"name":"Zhang Yaohan","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324313);
