INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-dien-sat-nhan', 'Vô Diện Sát Nhân', 'Nightmares', 'null', 'https://phimimg.com/upload/vod/20230919-1/ddea8948b67d5bae89dfd0c4953f9cbd.jpg', '<p><span style="font-family: ">Lâu rồi bác sĩ Phương Anh không được ngủ ngon. Giữa đêm, cô thường thức giấc vì những cơn ác mộng có nội dung tương tự. Trong mơ bác sĩ luôn thấy một kẻ không lộ rõ mặt, bám theo cô với con dao nhọn hoắt trên tay hòng cướp mạng. Cơn ác mộng lặp đi lặp lại khiến cuộc sống vốn hoàn hảo của Phương Anh đã bị đảo lộn hoàn toàn. Thế nhưng, điều kinh hoàng hơn còn xảy ra, khi tên Vô Diện Sát Nhân bước ra đời thực và truy sát cô.</span></p>', 'Full', 1, 'single', 'completed', 23, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Phương Anh Đào","avatar":""},{"name":"Quách Ngọc Tuyên","avatar":""},{"name":"Hiếu Nguyễn","avatar":""},{"name":"Oanh Kiều","avatar":""},{"name":"Hoàng Phúc","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324313);
