INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('la-may-tren-bau-troi-cua-ai-do', 'Là Mây Trên Bầu Trời Của Ai Đó', 'Side Seeing', 'https://phimimg.com/upload/vod/20230919-1/a156f72d1967e07b02ac3929c0eeb33d.jpg', 'https://phimimg.com/upload/vod/20230919-1/9594ae93dedbbb91d73324cc16d2d072.jpg', '<p><span style="font-family: ">Theo chân cuộc hành trình đu idol của “Fangirl hường phấn” Mây (Ngọc Lan Vy) – nàng tiểu thư chính hiệu có cuộc sống luôn “được” kiểm soát chặt chẽ của gia đình. Nàng lặn lội sang tận đất Thái chỉ để thỏa mãn ước mơ của mình là được dùng bữa với idol nhân ngày sinh nhật. Trớ trêu thay trong chuyến đi đầy sóng gió này, người mà nàng gặp nhiều nhất không phải là chàng idol Park đẹp trai (Push Puttichai) lại là một chàng trai đầy oan gia ngõ hẹp tên Boy (August Vachiravit). Giữa một bên là thần tượng bản thân luôn ngày đêm mong nhớ và một bên đích thị là “oan gia” chạy trốn thế nào cũng gặp, nàng Mây sẽ đưa ra lựa chọn nào trong khoảng thời gian du lịch đầy “ngắn ngủi” của mình trên đất Thái?</span></p>', 'Full', 1, 'single', 'completed', 18, 2022, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Ngọc Lan Vy","avatar":""},{"name":"Hồng Vân","avatar":""},{"name":"Trịnh Tú Trung","avatar":""},{"name":"Hải Triều","avatar":""},{"name":"Lưu Đông","avatar":""},{"name":"Lâm Bảo Châu","avatar":""},{"name":"Quỳnh Lý","avatar":""},{"name":"Nhâm Phương Nam","avatar":""},{"name":"Bhuripat Vejvongsatechavat","avatar":""},{"name":"Pakorn Lum","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324313);
