INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-uoc-cuoi-cua-tu-nhan-2037', 'Điều Ước Cuối Của Tù Nhân 2037', '2037', 'https://phimimg.com/upload/vod/20230916-1/3454754140d9b709aa251335ed16d2cf.jpg', 'https://phimimg.com/upload/vod/20230916-1/a53ef5faafb73b89b3fde1d3036d9066.jpg', '<p>Yoon Young 19 tuổi sống một mình với mẹ và chuẩn bị cho kỳ thi công chức trong khi làm việc bán thời gian. Bất kể trái tim nhân hậu và ý chí chân thành, những sự cố bất ngờ đã biến Yoon Young từ nạn nhân trở thành kẻ giết người, đẩy cô vào tù và bị gọi là tù nhân &quot;2037&quot; thay vì &quot;Yoon Young&quot;. Trong hoàn cảnh vô vọng, những người bạn tù của cô ở phòng giam số 12 với những câu chuyện của chính họ đã chắp cánh hy vọng để bảo vệ Yoon Young...</p>', 'Full', 1, 'single', 'completed', 32, 2022, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Hong Ye-ji","avatar":""},{"name":"Kim Ji-young","avatar":""},{"name":"Kim Mi-hwa","avatar":""},{"name":"Hwang Suk-jung","avatar":""},{"name":"Shin Eun-jung","avatar":""},{"name":"Jeon So-min","avatar":""},{"name":"Jeong In-gi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324313);
