INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-thu-dai-nao-dong-kinh', 'Ngũ Thử Đại Náo Đông Kinh', 'The Invincible Constable', 'https://phimimg.com/upload/vod/20230913-1/1c308c57737fe05b4683c549027fc753.jpg', 'https://phimimg.com/upload/vod/20230913-1/2a6ab0cb3ba955e65bd32d0bce2223e8.jpg', '<p>Dựa trên các nhân vật trong tiểu thuyết Trung Quốc thế kỷ 19 Thất anh hùng và Ngũ dũng sĩ. Zhan Zhao, Nam anh hùng, được Hoàng đế Renzong phong làm Chúa mèo. Wu Yi, được biết đến với cái tên Five Rats of Sky Island, đã rất thất vọng khi nghe điều này. Bạch Ngọc Đường, con chuột gấm thứ năm, vô cùng tức giận. Anh thề sẽ cạnh tranh với Zhan Zhao. Đông Đô Hỏa Tiên đang dâng lễ tế đất nước thái bình thịnh vượng. Tượng Hỏa Tiên được ban tặng để cầu nguyện cho thế giới. Bệ hạ ra lệnh cho Zhan Zhao bảo vệ nó. Khi Bai Yutang biết được điều này, anh ta đã cố gắng đánh cắp Tượng Hỏa Bất Tử vì phẩm giá của Ngũ Chuột. Hai anh em lần lượt đến nhưng lại vô tình vướng vào một vụ án trả thù bí ẩn.</p>', 'Full', 1, 'single', 'completed', 27, 2022, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ivan Xu","avatar":""},{"name":"Leif Ye","avatar":""},{"name":"Wang Yuwei","avatar":""},{"name":"Li Shaoting","avatar":""},{"name":"Yan Yanlong","avatar":""},{"name":"Chen Xianmin","avatar":""},{"name":"Lu Shun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324313);
