INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-kim-phong-bao', 'Hắc Kim Phong Bạo', 'In the Storm', 'https://phimimg.com/upload/vod/20230913-1/7da1277e9ab1f862005e9df48a98cd54.jpg', 'https://phimimg.com/upload/vod/20230913-1/19c217951f4c681a41e93acb062be95d.jpg', '<p><span style="font-family: ">Vi Cảnh Thanh (Lâm Phong đóng) là một thanh tra cao cấp đến Ma Cao để truy tìm sự thật nhằm tìm ra “căn bệnh” đang ẩn mình trong mạng lưới cấp cao của Hong Kong. Tuy nhiên, độ khó và quy mô của cuộc điều tra vụ án vượt xa ngoài sức tưởng tượng của anh khi hàng loạt cái tên có sức ảnh hưởng dần lộ diện như người nổi tiếng, giới chính trị và kinh doanh,… Người cộng sự của Vi Cảnh Thanh là chủ nhiệm tổ điều tra cao cấp Hong Kong – Hạ Vĩ Liêm (Huỳnh Hạo Nhiên đóng). Cả hai quen biết và hợp tác với nhau khi vô tình điều tra cùng một vụ án, mối quan hệ của đôi bên vừa là bạn vừa là kẻ đối nghịch. Phim có sự tham gia của các diễn viên: Lâm Phong, Châu Tú Na, Huỳnh Hạo Nhiên, Lý Xán Sâm, Lương Cạnh Huy, Liên Thi Nhã, Ngô Khải Hoa…</span></p>', '', 30, 'series', 'completed', 29, 2022, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Raymond Lam","avatar":""},{"name":"Chrissie Chau","avatar":""},{"name":"Raymond Wong Ho-yin","avatar":""},{"name":"Lynn Hung","avatar":""},{"name":"Lawrence Ng","avatar":""},{"name":"Oscar Leung","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324313);
