INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-gioi-doc-ton', 'Vạn Giới Độc Tôn', 'Ten Thousand Worlds', 'https://phimimg.com/upload/vod/20250308-1/4b81238b9844aa16e3f7e9ee8afdbc94.jpg', 'https://phimimg.com/upload/vod/20250308-1/25c9c7486b5de820475bd8fe0ccb316e.jpg', '<p>Với sự trợ giúp của Phượng Hoàng huyết mạch, Lâm Phong đã vượt qua mọi khó khăndần &nbsp;từng bước tiến lên trên con đường võ đạo. Anh trải qua những thử thách đầy nguy hiểm, chiến đấu với những đối thủ mạnh mẽ. Lâm Phong trở thành một cường giả được tôn kính.</p>', 'Tập 465', 800, 'hoathinh', 'ongoing', 82, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Ten Thousand Worlds","Wan Jie Du Zun","Wan Jie Duzun","萬界獨尊","Lord of The Ancient God Grave","The Sovereign of All Realms","万界独尊"]', 1784690324313);
