INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('van-gioi-doc-ton', 'Vạn Giới Độc Tôn', 'Ten Thousand Worlds', 'vạn giới độc tôn ten thousand worlds  ten thousand worlds wan jie du zun wan jie duzun 萬界獨尊 lord of the ancient god grave the sovereign of all realms 万界独尊', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-thien-chi-ton', 'Nghịch Thiên Chí Tôn', 'Against The Sky Supreme / Ni Tian Zhi Zun', 'https://phimimg.com/upload/vod/20250903-1/cc1e9fd59cf70b050455ceb0bf183bf3.jpg', 'https://phimimg.com/upload/vod/20250903-1/fe12e74047daf65d58b996a82987f6aa.jpg', '<p>Vũ trụ chia thành vực nội và vực ngoại, là kẻ thù của nhau. Vực ngoại do Thiên Ma thống trị, vực nội bao gồm phàm giới, tiên giới và thần giới. Các phàm giới như đại lục Thiên Phạt rất nhiều, gọi chung là tinh vực Cửu Thiên, do chín đại Tiên Đế lãnh đạo. Trên Cửu Thiên là thần vực Luyện Tiên, nơi tiên nhân cần đi qua để thành thần. Trong quá khứ, vạn tộc do ba chí tôn Thủy Nguyên, Hỗn Độn và Hồng Mông thống trị. Hồng Mông Chí Tôn là mạnh nhất, nhân hậu và bình đẳng với mọi sinh linh. Khi vũ trụ vực ngoại xâm lấn, ngài bị hai chí tôn kia cấu kết giết hại và nguyền rủa luân hồi. Người thân, thuộc hạ, quê hương không còn, đồ đệ Linh Hà thiên tôn phản bội, ngài trải qua nhiều kiếp bị diệt môn, cuối cùng chuyển kiếp thành Đàm Vân, thiếu gia 16 tuổi của một gia tộc chớm nổi trong trấn Vọng Nguyệt. Khi chưa thức tỉnh, hắn bị ức hiếp vì là kẻ vô dụng. Trong hôn lễ, hắn bị đánh vì phát hiện vị hôn thê gian díu với Tư Đồ công tử. Lúc sắp chết, ký ức của Hồng Mông Chí Tôn mới được thức tỉnh, thay đổi số phận, sở hữu thiên phú cấp thần, tu luyện công pháp kiếp trước và nhanh chóng tăng tu vi. Sau khi báo thù nhà, hắn vào Hoàng Phổ Thánh Tông, dùng trí tuệ và thuật pháp của Hồng Mông Chí Tôn, trở thành tông chủ, thống trị cả đại lục. Hắn còn gặp lại thuộc hạ và thê tử chuyển kiếp, tìm lại thần khí, hiểu rõ mọi chuyện quá khứ, gặp thêm rất nhiều giai lệ.</p>', 'Tập 531', 880, 'hoathinh', 'ongoing', 109, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Nitian Zhizun","Nì Tiān Zhì Zūn","Ni Tian Zhi Zun","Ni Tian Zhizun","Against the sky Supreme","역천지존","NTZZ","Guards against the sky","N.T.Z.Z","Lit The Supreme Being","Against the Heavenly Lords","Heaven Guards","Heaven Defying Supreme","逆天至尊"]', 1784690324313);
