INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-hoan-my', 'Thế Giới Hoàn Mỹ', 'Perfect World', 'https://phimimg.com/upload/vod/20240822-1/98b87edeb63d262313f864bc57df93d5.jpg', 'https://phimimg.com/upload/vod/20240822-1/97aa8ce6feea9737ac591a26a289b725.jpg', '<p>Thới Giới Hoàn Mỹ là phim hoạt hình kể về quá trình trưởng thành của một đứa trẻ trời sinh Chí Tôn cốt (đứa bé này tương lai có thể sánh vai cùng hung Thái cổ được trời ưu ái), có thể chinh chiến với Chân Hống, Kim Sí Đại Bàng có huyết mạnh tinh thuần đến hoàn mỹ, Nguyên thủy bảo thuật của nó sẽ danh chấn thiên hạ, được ghi khắc vào lịch sử của dân tộc.</p>', 'Tập 277', 280, 'hoathinh', 'ongoing', 54, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"陳錦聞","avatar":""},{"name":"趙雙","avatar":""},{"name":"李詩萌","avatar":""},{"name":"劉朙月","avatar":""},{"name":"劉晴","avatar":""},{"name":"楚越","avatar":""},{"name":"李蘭陵","avatar":""},{"name":"閻麼麼","avatar":""},{"name":"胡亞捷","avatar":""},{"name":"张雨濛","avatar":""},{"name":"賀文瀟","avatar":""},{"name":"白雪岑","avatar":""},{"name":"劉琮","avatar":""},{"name":"弋凡","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324313);
