INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-quy-co-say-xin-phan-1', 'Những Quý Cô Say Xỉn (Phần 1)', 'Work Later, Drink Now (Season 1)', 'https://phimimg.com/upload/vod/20260703-1/2dace24a552ed7d8ac2f559a75ec3965.jpg', 'https://phimimg.com/upload/vod/20260703-1/02339672c8b39a4955d71b0e7e9be113.jpg', '<p>Là những phụ nữ độc thân, độc lập và ngoài 30, ban ngày So Hee, Ji Yeon và Ji Gu vùi đầu vào công việc, nhưng khi màn đêm buông xuống họ cùng tụ tập để thưởng thức cốc bia lạnh, kết thúc một ngày bận rộn. Đồng hành cùng họ là anh chàng PD Kang Buk Gu hài hước. Tình bạn giữa ba cô gái và Buk Gu sẽ được khắc họa rõ nét qua những buổi nhậu tâm tình, động viên nhau trước mọi vấn đề trong cuộc sống.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 48, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Sun-bin","avatar":""},{"name":"Han Seon-hwa","avatar":""},{"name":"Jung Eun-ji","avatar":""},{"name":"Choi Si-won","avatar":""},{"name":"Yoo In-young","avatar":""},{"name":"Joo Eo-jin","avatar":""},{"name":"Yoon Shi-yoon","avatar":""},{"name":"Jung Hae-na","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["술꾼도시여자들"]', 1784690324313);
