INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-nam-chi', 'Mộ Nam Chi', 'Rebirth For You', 'https://phimimg.com/upload/vod/20250811-1/19406a0acf437910a96bd1d4ca108bfc.jpg', 'https://phimimg.com/upload/vod/20250811-1/790dffa164181ad63e9fb7e39aaa143f.jpg', '<p>Phim được chuyển thể từ tiểu thuyết Mộ Nam Chi của tác giả Chi Chi. Mộ Nam Chi xoay quanh chuyện tình ngọt ngào nhưng cũng đầy trắc trở của Gia Nam quận chúa. Gia Nam quận chúa Khương Hiến, nhũ danh Bảo Ninh, (Cúc Tịnh Y) dựa vào sự thông minh tài trí của mình từng bước cân bằng thế lực các phương. Cô yêu thương Lý Khiêm (Tăng Thuấn Hi) người có xuất thân là Cấm quân thị vệ. Cả hai người vượt qua nhiều khó khăn về việc thân phận cách biệt, cuối cùng có được hạnh phúc.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 56, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cúc Tịnh Y","avatar":""},{"name":"Tăng Thuấn Hỷ","avatar":""},{"name":"Vương Trác Thành","avatar":""},{"name":"Vương Nghệ Đình","avatar":""},{"name":"Lý Dịch Trân","avatar":""},{"name":"Lý Vân Duệ","avatar":""},{"name":"Lục Đăng Ngọc","avatar":""},{"name":"Tống Hân Nghi","avatar":""},{"name":"Vương Hoan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["慕南枝","ตำนานเจียหนาน","嘉南傳","嘉南传"]', 1784690324313);
