INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-pho-tau-3', 'Thám Tử Phố Tàu 3', 'Detective Chinatown 3', 'https://phimimg.com/upload/vod/20260628-1/0631763df3725a751f4d153e2cf2a2b5.jpg', 'https://phimimg.com/upload/vod/20260628-1/dffcfaffe7e4f01af0986dcc5b764afe.jpg', '<p>Nhóm thám tử phố Tàu Tần Phong do Lưu Hạo Nhiên đóng và Đường Nhân Vương Bảo Cường đóng sẽ tiếp tục chiến đấu ở Tokyo sau cuộc bạo loạn ở Bangkok và New York! Lần này họ chấp nhận yêu cầu của Noda hiroshi do Satoshi Tsumabuki đóng và tham gia vào một cuộc chiến giữa các băng nhóm. Liệu họ có thể tìm ra sự thật? Tần Phong có thể phát hiện ra thân phận thật sự của Q không?</p>', 'Full', 1, 'single', 'completed', 37, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Bảo Cường","avatar":""},{"name":"Lưu Hạo Nhiên","avatar":""},{"name":"Thê Phu Mộc Thông","avatar":""},{"name":"Tony Jaa","avatar":""},{"name":"Trường Trạch Nhã Mỹ","avatar":""},{"name":"Nhiễm Điền Tương","avatar":""},{"name":"Thiển Dã Trung Tín","avatar":""},{"name":"Linh Mộc Bảo Nại Mỹ","avatar":""},{"name":"Thượng Ngữ Hiền","avatar":""},{"name":"Vương Tấn","avatar":""},{"name":"Trương Tử Phong","avatar":""},{"name":"Văn Vịnh San","avatar":""},{"name":"Khắc Lạp Lạp","avatar":""},{"name":"Trình Tiêu","avatar":""},{"name":"Tiêu Ương","avatar":""},{"name":"Trần Triết Viễn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["唐探3","Detective Chinatown 3","แก๊งม่วนป่วนโตเกียว","唐人街探案3","Detective Chinatown III"]', 1784690324313);
