INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-sot-san-co-giai-ngoai-hang-anh-troi-day', 'Cơn Sốt Sân Cỏ: Giải Ngoại Hạng Anh Trỗi Dậy', 'Fever Pitch: The Rise Of The Premier League', 'https://phimimg.com/upload/vod/20260620-1/2ccd65dac1197e95034792daaa82d2a5.jpg', 'https://phimimg.com/upload/vod/20260620-1/92fc5f91d0debc93d0d48308da32ffbc.jpg', '<p>Ngày xửa ngày xưa, bóng đá vốn dĩ chỉ là một trò chơi đơn thuần... Câu chuyện được kể lại từ chính những người đã sống trong thời kỳ đó, và cả những người đã biến &quot;trò chơi đẹp&quot; này thành một ngành kinh doanh trị giá hàng tỷ bảng Anh. Nơi hội tụ của những bàn thắng đỉnh cao, sự hào nhoáng và vinh quang rực rỡ.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 40, 2021, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"David Beckham","avatar":""},{"name":"Éric Cantona","avatar":""},{"name":"Alan Shearer","avatar":""},{"name":"Arsène Wenger","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["狂热足球：英超崛起","Fever Pitch: The Rise of the Premier League"]', 1784690324313);
