INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-tuong-lai', 'Cuộc Chiến Tương Lai', 'The Tomorrow War', 'cuộc chiến tương lai the tomorrow war chris pratt yvonne strahovski j.k. simmons betty gilpin sam richardson edwin hodge jasmine mathews ryan kiera armstrong keith powers mary lynn rajskub mike mitchell jared shaw alexis louder rose bianco seychelle gabriel alan trong chibuike ghost draft война в бъдещето 내일의 전쟁 幽靈徵募 幽靈分遣隊 明日之战 明日之戰 válka zítřka ο πόλεμος του αύριο トゥモローウォー wojna o jutro война будущего sutrašnji rat 明日戰爭 yarının savaşı війна майбутнього ข้ามเวลา หยุดโลกวินาศ a holnap háborúja війна завтрашнього дня 투모로우 워 sabahın müharibəsi the tomorrow war', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vet-xe-theo-duong-ke-strappare-lungo-i-bordi', 'Vết Xé Theo Đường Kẻ (Strappare lungo i bordi)', 'Tear Along The Dotted Line', 'https://phimimg.com/upload/vod/20260615-1/8c9e36bc36baaef1ab0c345ecb336865.jpg', 'https://phimimg.com/upload/vod/20260615-1/55858e2c868ee4645a2aaeddafc91d61.jpg', '<p>Một họa sĩ truyện tranh ở Rome cùng với con tào tinh (linh hồn hộ mệnh) trong hình hài một con tà lạp (con tatu) đóng vai trò như tiếng gọi lương tri của mình, đã cùng nhìn lại chặng đường đời và một mối tình dang dở, khi anh và nhóm bạn thân cùng nhau thực hiện một chuyến đi ra ngoại ô thành phố.</p>', 'Hoàn Tất (6/6)', 6, 'hoathinh', 'completed', 29, 2021, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Zerocalcare","avatar":""},{"name":"Valerio Mastandrea","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["قص بمحاذاة الخط المنقط","Entrelinhas Pontilhadas","An der perforierten Linie abreißen","Cortar por la línea de puntos","À découper suivant les pointillés","A pontozott vonal mentén","点線に沿って切り取る","점선을 따라 찢어라","Oderwij wzdłuż linii","Destacar Pelo Picotado","Otkinite po liniji","Линия отрыва","İşaretli Yerden Kesin","人生的輪廓","Лінія розривання","Strappare lungo i bordi"]', 1784690324313);
