INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suong-mu-dinh-bat-giac', 'Sương Mù Đình Bát Giác', 'The Pavilion', 'https://phimimg.com/upload/vod/20260524-1/0b36f3534cfd05140f0bd38122b9bf68.jpg', 'https://phimimg.com/upload/vod/20260524-1/a4f669a90a64f3250c54c098bf9e9a01.jpg', '<p>Mười bảy năm trước, em gái xinh như thiên sứ nhà họ Huyền bị sát hại, vụ án ném bỏ thi thở bị gác lại, hung thủ tự do ngoài vòng pháp luật. Nhà họ Huyền vì thế mà phân tán Nam Bắc, mỗi người một phương. Mười bảy năm sau, thị trấn xảy ra một vụ án kỳ có liên quan tới nhà họ Huyền. Điều này khiến cho những người thân từ khắp nơi cùng tập hợp làm. Theo chân tướng vụ án cũ dần lộ diện, mâu thuẫn nhiều năm anh em giày vò cuối cùng cũng bùng nổ. Một nhà bốn người nên đi đâu về đâu, họ có thể mở lòng bước khỏi màn sương mù mờ mịt này không?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 20, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đoạn Dịch Hoành","avatar":""},{"name":"Hách Lôi","avatar":""},{"name":"Tổ Phong","avatar":""},{"name":"Ngô Việt","avatar":""},{"name":"Hình Mân Sơn","avatar":""},{"name":"Bạch Vũ Phàm","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["팔각정의 미스터리","八角亭謎霧","八角亭谜雾"]', 1784690324313);
