INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chim-lua', 'Chim Lửa', 'Firebird', 'https://phimimg.com/upload/vod/20260519-1/ce9e40810b255356ea56682447f94ffa.jpg', 'https://phimimg.com/upload/vod/20260519-1/88acf1922c11b51667daf01139fbd414.jpg', '<p>Sergey là một quân nhân trẻ đang gặp khó khăn với cuộc sống quân đội, anh đang đếm từng ngày cho đến khi kết thúc nghĩa vụ quân sự. Một ngày nọ, chàng phi công gan dạ Roman xuất hiện và làm đảo lộn cuộc sống của anh. Sergey bị thúc đẩy bởi sự tò mò về người đàn ông quyến rũ tên Roman, cả hai đứng giữa ranh giới tình bạn và tình yêu. Sau đó, họ bị cuốn vào mối tình tay ba với Luisa, thư ký của chỉ huy căn cứ. Sergey buộc phải đối mặt với quá khứ của mình và sự nghiệp của Roman bị ảnh hưởng không nhỏ. Liệu họ có thể vượt qua được bức tường vô hình để tìm kiếm hạnh phúc thực sự của bản thân?</p>', 'Full', 1, 'single', 'completed', 36, 2021, 'Vietsub', 'FHD', 'Estonia', 0, '[{"name":"Tom Prior","avatar":""},{"name":"Oleg Zagorodnii","avatar":""},{"name":"Diana Pozharskaya","avatar":""},{"name":"Jake Henderson","avatar":""},{"name":"Margus Prangel","avatar":""},{"name":"Nicholas Woodeson","avatar":""},{"name":"Ester Kuntu","avatar":""},{"name":"Kaspar Velberg","avatar":""},{"name":"Sergei Lavrentyev","avatar":""},{"name":"Rasmus Kaljujärv","avatar":""},{"name":"Lauri Mäesepp","avatar":""},{"name":"Karl-Andreas Kalmet","avatar":""},{"name":"Vladimir Nadein","avatar":""},{"name":"Markus Luik","avatar":""},{"name":"Anatoli Tafitšuk","avatar":""},{"name":"Nils Ma","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f712