INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-nong', 'Nắng Nóng', 'Hotsunlight', 'https://phimimg.com/upload/vod/20260512-1/56d1a66e5337cee750a4e1b69d2ef8df.jpg', 'https://phimimg.com/upload/vod/20260512-1/60d158816f983110b013d084062c1a27.jpg', '<p>Vùng Lugansk, tháng 5 năm 2014. Gia đình Novozhilov, một cách tình cờ, bị cuốn vào vòng xoáy của các sự kiện ở Lugansk. Vlad Novozhilov là một cựu chiến binh tham gia chiến tranh ở Afghanistan. Ông hiểu rõ chiến tranh là gì. Sau khi chứng kiến đủ những nỗi kinh hoàng của chiến tranh trong thời gian phục vụ, về nguyên tắc ông thậm chí không muốn chạm vào vũ khí. Trong tình huống này, ông chỉ thấy một lối thoát duy nhất - rời khỏi đất nước. Nhưng không thể chạy trốn khỏi chiến tranh, biên giới đã bị đóng cửa. Để cứu gia đình mình, ông sẽ phải đưa ra những lựa chọn đạo đức khó khăn.</p>', 'Full', 1, 'single', 'completed', 25, 2021, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Vladimir Ilin","avatar":""},{"name":"Aleksandr Bukharov","avatar":""},{"name":"Aleksey Kravchenko","avatar":""},{"name":"Maksim Dakhnenko","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Солнцепек","Solntsepyok","hot sunlight","Hotsunlight","Солнцепёк"]', 1784690324313);
