INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ky-nghi-nho-kieu-y', 'Một kỳ nghỉ nhỏ kiểu Ý', 'A Little Italian Vacation', 'https://phimimg.com/upload/vod/20260505-1/e1534f2bda17ee854892cc80a3e327da.jpg', 'https://phimimg.com/upload/vod/20260505-1/99d22a12a1187d38ef55cc470336aac3.jpg', '<p>Trong bộ phim hài hước đầy táo bạo này, một nhóm học sinh cuối cấp phải xoay xở giữa những mối tình cũ và những cuộc tình mới trên bờ biển của một thị trấn xinh đẹp ở Ý.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"James Tarpey","avatar":""},{"name":"Emma Curtis","avatar":""},{"name":"Andrew Tilt","avatar":""},{"name":"Hannah van der Westhuysen","avatar":""},{"name":"Karen Maruyama","avatar":""},{"name":"Jonas Fisch","avatar":""},{"name":"Jude Schedden","avatar":""},{"name":"Guy Potter","avatar":""},{"name":"Bianca Cedrone","avatar":""},{"name":"Niccolò Besio","avatar":""},{"name":"Jean Michael Lif","avatar":""},{"name":"Daniel Nava Argote","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Sleeping Arrangements","A Little Italian Vacation"]', 1784690324314);
