INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-ngoai-hanh-tinh-phan-1', 'Bác Sĩ Ngoài Hành Tinh (Phần 1)', 'Resident Alien (Season 1)', 'https://phimimg.com/upload/vod/20250722-1/51cbaa3a14a660982c9aa3f3074a19a2.jpg', 'https://phimimg.com/upload/vod/20250722-1/2281ca9278d500402223c2dd3929f268.jpg', '<p>Bộ phim dựa trên truyện tranh cùng tên của Peter Hogan và Steve Parkhouse. Câu chuyện kể về một anh chàng người ngoài hành tinh, sau khi hạ cánh xuống Trái Đất anh lấy thân phận là bác sĩ và sinh sống tại thị trấn Colorado. Tại đây, anh chàng người ngoài hành tinh phải vật lộn trong tình thế tiến thoái lưỡng nan giữa nhiệm vụ bí mật và đạo đức con người. Đồng thời anh chàng còn phải đối phó với cậu bé 9 tuổi, người duy nhất biết được thân phận thật sự của anh. Liệu anh chàng sẽ lựa chọn giữa nhiệm vụ hủy diệt Trái Đất hay cứu giúp nhân loại?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 15, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alan Tudyk","avatar":""},{"name":"Sara Tomko","avatar":""},{"name":"Corey Reynolds","avatar":""},{"name":"Alice Wetterlund","avatar":""},{"name":"Levi Fiehler","avatar":""},{"name":"Elizabeth Bowen","avatar":""},{"name":"Meredith Garretson","avatar":""},{"name":"Judah Prehn","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Местен извънземен","外星居民","תושב חייזרי","レジデント・エイリアン ～宇宙からの訪問者～","Местный пришелец","Пришелец-постоялец","Резидент прибулець","Постоялець з космосу","Resident Alien"]', 1784690324314);
