INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-sao-lai-giet-toi', 'Vì Sao Lại Giết Tôi?', 'Why Did You Kill Me?', 'https://phimimg.com/upload/vod/20260501-1/6b55fd2e0685b41d3d527d629dc2f868.jpg', 'https://phimimg.com/upload/vod/20260501-1/36e7c0a88ec2d41efaf3f2610472af8c.jpg', '<p>Ranh giới giữa công lý và trả thù bị xóa nhòa khi một gia đình đau khổ dùng mạng xã hội để tìm những kẻ đã sát hại thanh niên 24 tuổi Crystal Theobald.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Belinda Lane","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Por Que Você Me Matou?","Warum hast du mich getötet?","Γιατί με Σκότωσες;","Beni Neden Öldürdün?","Por qué me mataron?","なぜ殺したの?","Pourquoi tu m''as tuée?","Why Did You Kill Me?"]', 1784690324314);
