INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-truoc-giang-sinh', 'Cuộc Chiến Trước Giáng Sinh', '''Twas the Fight Before Christmas', 'https://phimimg.com/upload/vod/20260501-1/8a980f54980a29d71e9cf2371d421f69.jpg', 'https://phimimg.com/upload/vod/20260501-1/2a9a0a69166c14fd100da9064e8d3f34.jpg', '<p>Trong câu chuyện Giáng sinh có thực đầy kịch tính này, Jeremy Morris mang đến một ý nghĩa khác hẳn cho tinh thần Giáng sinh khi cuộc trưng bày siêu hoành tráng mừng mùa lễ hội của anh châm ngòi cho mâu thuẫn với hàng xóm và đưa họ tới tòa án.</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jeremy Morris","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["The Fight Before Christmas","''Twas the Fight Before Christmas"]', 1784690324314);
