INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-thoi-den-mo-hoang-bi-tu', 'Ma Thổi Đèn: Mộ Hoàng Bì Tử', 'Mojin The Tomb Of Weasel', 'https://phimimg.com/upload/vod/20260502-1/004c7ec27c4a7c31aa1ea54d72312a5a.jpg', 'https://phimimg.com/upload/vod/20260502-1/b710c5fc841106f719ed727a82565244.jpg', '<p>Để giải cứu cô thôn nữ Họa My bị bệnh, Hồ Bát Nhất cùng một số thanh niên trai tráng ở miền quê Đông Bắc, đã liên kết với cùng với chú thợ săn họ Triệu tìm đến hang động của người gấu tuyết trong rừng để tìm thuốc giải. Không ngờ đột nhiên lại bị người tuyết tấn công, buộc phải trốn vào trong ...</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Mojin The Tomb Of Weasel"]', 1784690324314);
