INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-ban-tia', 'Vua Bắn Tỉa', 'The Sniper', 'https://phimimg.com/upload/vod/20260502-1/c3e84879f9ce026f4ebd1dfeaec8f70e.jpg', 'https://phimimg.com/upload/vod/20260502-1/fa5cc673185f6ea89eba038f12427918.jpg', '<p>Cứu Thế Hội là tổ chức tội phạm mạnh nhất Đông Nam Á, nạn buôn người, buôn bán nội tạng, sản xuất ma túy diễn ra tràn lan. Có thể nói là không có việc xấu nào là không làm. Vào năm 2012, đội Đặc công lên kế hoạch tỉ mỉ để bắt giữ Sompa thủ lĩnh của tổ chức tội phạm. Nhưng trong quá trình phục kích, Kim Minh vì cứu một cậu bé bị moi tim đã đánh rắn động cỏ, dẫn đến cuộc chiến khốc liệt giữa hai bên. Cuối cùng nhiệm vụ kết thúc trong thất bại, và cứu được hai đứa trẻ. Cậu bé tên là Kim Thái, và cô bé tên là Tiêu Mi. Dưới sự dạy dỗ của Kim Minh, mười năm sau, cả hai đứa trẻ đã trở thành những tay súng bắn tỉa hàng đầu. Trong một lần hành động, Kim Thái đã rất bất ngờ khi biết rằng ân sư xưa của mình là nội gián của Cứu Thế Hội. Khi danh tính bị lộ, Kim Minh và Tiêu Mi đã xảy ra cuộc chiến đẫm máu.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Xu Dongdong","avatar":""},{"name":"Henry Prince Mak","avatar":""},{"name":"Michael Tong Man-Lung","avatar":""},{"name":"Jane Wu","avatar":""},{"name":"Cheng Tao","avatar":""},{"name":"Ye Xinyu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["狙击之王","The Sniper"]', 1784690324314);
