INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-xa-vuong', 'Đảo Xà Vương', 'King Serpent Island', 'https://phimimg.com/upload/vod/20231114-1/6c3ceeb7a9275355e5523228de630d2b.jpg', 'https://phimimg.com/upload/vod/20231114-1/31483be86d3a251accfa1e8433cceff1.jpg', '<p>Phim nói về câu chuyện đấu tranh giữa nhóm Trần Tranh muốn bảo vệ loài rắn khổng lồ có nguy cơ tuyệt chủng và băng nhóm săn rắn trục lợi. Lính đặc chủng giải ngũ, nhân viên thu thập số liệu loài rắn, ba người Trần Tranh, Châu Hiểu Hiểu và Mã Phấn cùng đến đảo Xà Vương thu thập số liệu, không ngờ gặp phải băng nhóm bắt rắn cực hung ác do Kim lão tứ cầm đầu. Trong lúc rắn khổng lồ đẻ trứng, hai nhóm người bắt đầu liều chết đọ sức, cuối cùng nhóm người Trần Tranh thuận lợi rời khỏi đảo Xà Vương, còn Kim lão tứ hám lợi đen lòng bị rắn khổng lồ nuốt trọn. Cuối cùng đảo Xà Vương được liệt vào khu bảo tồn loài rắn, ba người Trần Tranh cũng bảo vệ hoà bình sinh thái, bảo vệ môi trường tự nhiên.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Lincheng","avatar":""},{"name":"Shao Yun","avatar":""},{"name":"Wang Hongqian","avatar":""},{"name":"Guo Ye","avatar":""},{"name":"Rong Weifeng","avatar":""},{"name":"Wu Hao","avatar":""},{"name":"Xu Daning","avatar":""},{"name":"Jiang Lie","avatar":""},{"name":"Biao Zi","avatar":""},{"name":"Wang Zhigang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Snake King Island","She Wang Dao","蛇王岛"]', 1784690324314);
