INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-di-gap-me', 'Chuyến Đi Gặp Mẹ', 'Kids Are Fine', 'https://phimimg.com/upload/vod/20260502-1/46443046af16c6dbb19ebe16ef868fdc.jpg', 'https://phimimg.com/upload/vod/20260502-1/1f7b3b8d9d55e6eaeac4b1859df8997a.jpg', '<p>Mẹ ốm nặng và phải chuyển viện, cậu bé Da Yi 9 tuổi cùng bạn bè quyết định lên đường đi tìm mẹ. Trên hành trình ấy, cậu đã học thêm nhiều điều về tình bạn, lòng can đảm và đối mặt nỗi sợ mất mát.</p>', 'Full', 1, 'single', 'completed', 17, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Kyung-hoon","avatar":""},{"name":"Park Ye-chan","avatar":""},{"name":"Hong Jeong-min","avatar":""},{"name":"Park Si-wan","avatar":""},{"name":"Ok Ye-rin","avatar":""},{"name":"Lee Sang-hee","avatar":""},{"name":"Yoon Kyung-ho","avatar":""},{"name":"Gong Min-jeung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Happy Children","아이들은 즐겁다"]', 1784690324314);
