INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hinh-the-phan-1', 'Hình Thể (Phần 1)', 'Physical (Season 1)', 'https://phimimg.com/upload/vod/20260430-1/0cdbbe1cd3fa5cbec1554f0f64436b50.jpg', 'https://phimimg.com/upload/vod/20260430-1/c30b8b5ab57f2c4b42a063438e7fffda.jpg', '<p>Sheila Rubin là một bà nội trợ bị dày vò lặng lẽ ở San Diego thập niên 80. Đằng sau những cánh cửa đóng kín, cô chiến đấu với những con quỷ cá nhân cực đoan và tiếng nói xấu xa bên trong. Nhưng mọi thứ thay đổi khi cô ấy khám phá ra thể dục nhịp điệu, mở ra một hành trình hướng tới trao quyền và thành công.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 14, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rose Byrne","avatar":""},{"name":"Rory Scovel","avatar":""},{"name":"Dierdre Friel","avatar":""},{"name":"Paul Sparks","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["جسمانی","فیزیکی","Physical"]', 1784690324314);
