INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-mo', 'Thần Mộ', 'The Warrior From Sky', 'https://phimimg.com/upload/vod/20260409-1/88f32134c2204586ed1e77646ffcee05.jpg', 'https://phimimg.com/upload/vod/20260409-1/46405d6200c127d42de242157d63c3fc.jpg', '<p>Thượng cổ chiến thần Thần Nam sau vạn năm ngủ vùi đã thức tỉnh giữa quần thể mộ trịnh trên đỉnh núi tuyết. Lúc này, cả thần lực và ký ức của anh đều bị phong ấn. Sau một trận giao tranh quyết liệt với người giữ mộ và rơi xuống vách đá, Thần Nam vô tình lạc vào địa giới của Sở Quốc. Để tìm kiếm lời giải cho bí ẩn về thân thế của mình, anh đã dấn thân vào hành trình đầy gian khổ để cứu rỗi thiên hạ chúng sinh.</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thử Sa","avatar":""},{"name":"Trương Địch","avatar":""},{"name":"Lý Minh Hiên","avatar":""},{"name":"Triệu Hội Nam","avatar":""},{"name":"Đan Minh Khải","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Shen Mu","Shenmo Cemetery","Tomb of Gods","Divine Grave","The Warrior From Sky","神墓"]', 1784690324314);
