INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-cua-otar', 'Cái Chết Của Otar', 'Otar''s Death', 'https://phimimg.com/upload/vod/20260409-1/ea0d43d24eb57cc5c1fc79e4813fa93f.jpg', 'https://phimimg.com/upload/vod/20260409-1/83dbb96814a143ec621e76f229bbea99.jpg', '<p>Keti và Nika hoảng loạn khi vô tình đâm phải một ông lão trên đường. Tai nạn nhanh chóng biến thành rắc rối lớn khi gia đình nạn nhân đe dọa kiện ra tòa. Để tránh việc Nika phải vào tù, Keti buộc phải tìm cách xoay đủ một khoản tiền lớn. Áp lực và nỗi sợ dần đẩy họ vào những lựa chọn khó khăn. Mọi chuyện ngày càng vượt khỏi tầm kiểm soát.</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub', 'FHD', 'Georgia', 0, '[{"name":"Marlen Egutia","avatar":""},{"name":"Iva Kimeridze","avatar":""},{"name":"Nutsa Kukhianidze","avatar":""},{"name":"Eka Chavleishvili","avatar":""},{"name":"Dimitri Tatishvili","avatar":""},{"name":"Dato Roinishvili","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ოთარის სიკვდილი"]', 1784690324314);
