INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khutulun-cong-chua-do-vat-', 'Khutulun: Công Chúa Đô Vật (Хотулун гүнж: Алтан судрын эрэлд)', 'The Warrior Princess (Khutulun: The Wrestling Princess)', 'https://phimimg.com/upload/vod/20260409-1/b895113babc47fe137274456135d8e1d.jpg', 'https://phimimg.com/upload/vod/20260409-1/d51c875e4e12f4a4b38d7d4868e054f4.jpg', '<p>Công chúa Hốt Thốc Luân, hậu duệ của Thành Cát Tư Hãn và là chiến binh Mông Cổ dũng mãnh, bị sát thủ phục kích trong đám cưới khi Kim Quang Minh Kinh bị đánh cắp. Quyết tâm bảo vệ danh dự và hòa bình, cô lên đường truy tìm văn tự bị mất, đối mặt nhiều kẻ thù nguy hiểm trên hành trình.</p>', 'Full', 1, 'single', 'completed', 25, 2021, 'Vietsub', 'FHD', 'Mongolia', 0, '[{"name":"Tserendolgor Munkhbat","avatar":""},{"name":"Altantur Altanjargal","avatar":""},{"name":"Setgeltuvshin Bayarbat","avatar":""},{"name":"Tumurtogtokh Davaakhuu","avatar":""},{"name":"Badrakh Battogtokh","avatar":""},{"name":"Munkhtumur Dondov","avatar":""},{"name":"Temuujin Odkhuu","avatar":""},{"name":"Gerelsukh Otgon","avatar":""},{"name":"Umravdan Oyunbileg","avatar":""},{"name":"Tumurbaatar Dashtseren","avatar":""},{"name":"Shuudertsetseg Baatarsuren","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Wrestling Princess","Хотулун гүнж: Алтан судрын эрэлд"]', 1784690324314);
