INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-am-duong', 'Kiếm Âm Dương', 'The Vengeance', 'https://phimimg.com/upload/vod/20260409-1/6dbe93cb3fb037e6865e72e6167bc17c.jpg', 'https://phimimg.com/upload/vod/20260409-1/64881e07a219672d3777f9b08ca32f4c.jpg', '<p>Cả nhà của cô dâu Nguyên Như Ý bị giết hại vào đêm tân hôn và một người che mặt cứu nàng ra. Một năm sau, Như Ý được biết sự thật từ người buôn tình báo Bao Đại Đình. Hóa ra năm đó cha nàng từng giết một cường đạo để cứu giúp bà con và con của cường đạo đó Đà Gia tàn sát nhà Nguyên trả thù cho cha. Với sự giúp đỡ của Bao Đại Đình, Như Ý tìm được nhược điểm của kẻ địch và lên đường trả thù...</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dư Lệ","avatar":""},{"name":"Lý Tư Dương","avatar":""},{"name":"Quách Mộ Hàm","avatar":""},{"name":"Tôn Nhất Minh","avatar":""},{"name":"Từ Thiệu Hàng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["The Vengeance","Yin and Yang Sword","陰陽劍","阴阳剑"]', 1784690324314);
