INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-mon-my-nhan-giang-ho', 'Đường Môn: Mỹ Nhân Giang Hồ', 'Beauty Of Tang Men', 'https://phimimg.com/upload/vod/20260409-1/72469ee168083c8d57368de1a95bc571.jpg', 'https://phimimg.com/upload/vod/20260409-1/3bb8645fe3f531d56675d33e53955b52.jpg', '<p>Tương truyền Đường Môn có báu vật thần bí là “Động Thiên Nghi”. Đó có thể báo trước danh sách kẻ ác và chém họ trước khi họ làm ác. Tuy nhiên, bất ngờ tên họ của trưởng môn mới Đường Môn Đương Vô Yên cũng xuất hiện trên Động Thiên Nghi. Trong quá trình chạy trốn, Đường Vô Diên gặp gỡ tên tặc lương thiện Sở Thần. Được chàng đi cùng, Đường Vô Yên quyết tâm trở lại Đường Môn, phá hoại Động Thiên Nghi và lấy lại vận mệnh của mình.</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Uẩn Phàm","avatar":""},{"name":"Vương Gia Lệ","avatar":""},{"name":"Lữ Khổng Duy","avatar":""},{"name":"Tôn Văn Tuyết","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["美人江湖","The Tangs Creed","the Tangs'' Creed","당문 : 미인강호","จอมนางแห่งถังเหมิน","唐门：美人江湖"]', 1784690324314);
