INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('duong-mon-my-nhan-giang-ho', 'Đường Môn: Mỹ Nhân Giang Hồ', 'Beauty Of Tang Men', 'đường môn: mỹ nhân giang hồ beauty of tang men vương uẩn phàm vương gia lệ lữ khổng duy tôn văn tuyết 美人江湖 the tangs creed the tangs'' creed 당문 : 미인강호 จอมนางแห่งถังเหมิน 唐门：美人江湖', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-chan-sinh-tu', 'Đánh Chặn Sinh Tử', 'They Shall Not Pass', 'https://phimimg.com/upload/vod/20260409-1/b20e45d0058a02547c3714b9b8fc8870.jpg', 'https://phimimg.com/upload/vod/20260409-1/2075a8a1f1b52a24d3da8e756f39780f.jpg', '<p>Một đơn vị thuộc Bát Lộ Quân buộc phải di chuyển để đối phó với cuộc càn quét của quân Nhật sau Chiến dịch Bách Đoàn. Để đảm bảo an toàn cho đại quân và người dân, Phó tư lệnh quân khu mới nhậm chức Lý Trí Viễn cùng Tiểu đoàn trưởng Lục Thiên Trạch, Đại đội trưởng Hoàng Trường Quân đã dẫn dắt các chiến sĩ lấy Mã Gia Bảo làm trận địa đánh chặn. Tại điểm chốt là đại viện nhà dân làng Lưu Hải Tĩnh, họ đã cùng nhau tạo nên một câu chuyện anh hùng, liều chết chiến đấu để kìm chân quân địch.</p>', 'Full', 1, 'single', 'completed', 18, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Ấu Bân","avatar":""},{"name":"Sử Lan Nha","avatar":""},{"name":"Vương Thao","avatar":""},{"name":"Ngụy Tử Thiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["They Shall Not Pass","阻击手","生死阻击"]', 1784690324314);
