INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chay-tron-doi-dau', 'Chạy Trốn Đối Đầu', 'Run Hide Fight', 'https://phimimg.com/upload/vod/20250804-1/c05cf922eb318b664783fda7ea87725b.jpg', 'https://phimimg.com/upload/vod/20250804-1/c796a7a73cd0287c6e47f8f182aa88a3.jpg', '<p>Zoe luôn sống khép mình sau cái chết của mẹ. Bỗng một ngày, trường của cô lại xảy ra một vụ xả súng tàn nhẫn. Bằng sự mưu trí và sự gan dạ, Zoe đã cùng mọi người chống lại những kẻ thủ ác.</p>', 'Full', 1, 'single', 'completed', 21, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Isabel May","avatar":""},{"name":"Thomas Jane","avatar":""},{"name":"Radha Mitchell","avatar":""},{"name":"Eli Brown","avatar":""},{"name":"Olly Sholotan","avatar":""},{"name":"Treat Williams","avatar":""},{"name":"Barbara Crampton","avatar":""},{"name":"Cyrus Arnold","avatar":""},{"name":"Britton Sear","avatar":""},{"name":"Catherine Davis","avatar":""},{"name":"Kenneisha Thompson","avatar":""},{"name":"Zachary Le Vey","avatar":""},{"name":"Cindy Vela","avatar":""},{"name":"Tom Williamson","avatar":""},{"name":"Joel Michaely","avatar":""},{"name":"Nate Boyer","avatar":""},{"name":"Bryan Massey","avatar":""},{"name":"CG L","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Shelter","Uciekaj albo walcz","Беги, прячься, бей","Біжи, ховайся, бий","¡Corre, Escóndete, Pelea!","Run Hide Fight"]', 1784690324314);
