INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luc-do-toi-da-chuyen-sinh-thanh-slime-phan-2', 'Lúc Đó Tôi Đã Chuyển Sinh Thành Slime (Phần 2)', 'That Time I Got Reincarnated As A Slime (Season 2)', 'lúc đó tôi đã chuyển sinh thành slime (phần 2) that time i got reincarnated as a slime (season 2) miho okasaki tomoaki maeno takuya eguchi hochu otsuka asuna tomari chikahiro kobayashi jun fukushima rie tanaka rina hidaka anzu haruno aquella vez que reencarne como un slime 關於我轉生變成史萊姆這檔事 tensei shitara slime datta ken 关于我转生变成史莱姆这档事 that time i got reincarnated as a slime tensura regarding reincarnated to slime aquella vez que me convertí en slime moi, quand je me réincarne en slime تولد دوباره به‌عنوان یک اسلایم وقتی به‌عنوان یک اسلایم تناسخ پیدا کردم آن زمان که به‌عنوان یک اسلایم زندگی دوباره یافتم tensei shitara slime datta ken tensei slime tensura 2 tensei shitara slime datta ken 2 転生したらスライムだった件 転スラ tensei shitara slime datta ken 3rd season tensei shitara slime datta ken: coleus no yume tensei shitara slime datta ken s4 tensei shitara slime datta ken 4th season 전생했더니 슬라임이었던 건에 대하여 전생했더니 슬라임이었던 건에 대하여 3기 關於我轉生變成史萊姆這檔事 柯里烏斯之夢 моє переродження в слиз that time i got reincarnated as a slime 2 that time i got reincarnated as a slime: visions of coleus chuyển sinh thành slime', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vao-ma-gioi-roi-day-irumakun-phan-2', 'Vào Ma Giới Rồi Đấy! Iruma-Kun (Phần 2)', 'Welcome To Demon School! Iruma-kun (Season 2)', 'https://phimimg.com/upload/vod/20251026-1/07a4524875bfffbb94b5302dc085c82e.jpg', 'https://phimimg.com/upload/vod/20251026-1/92a0513c37a4db0197e508cd9b05aa82.jpg', '<p>Câu chuyện kể về Ikoma, một cậu bé 14 tuổi đã bị cha mẹ mình bán cho ác ma để đạt được những điều họ muốn. Tuy nhiên, ác ma đã mua cậu về vốn không có cháu trai nối dõi nên ông rất yêu mến Ikoma và gửi cậu vào trường học ác ma.</p>', 'Hoàn Tất (21/21)', 21, 'hoathinh', 'completed', 14, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Ayaka Asai","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Takuya Sato","avatar":""},{"name":"Takaya Kuroda","avatar":""},{"name":"Mitsuki Saiga","avatar":""},{"name":"Yoshitaka Yamaya","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Tetsuya Kakihara","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Gakuto Kajiwara","avatar":""},{"name":"Takuto Yoshinaga","avatar":""},{"name":"Genki Okawa","avatar":""},{"name":"Shunichi Toki","avatar":""},{"name":"Junko Takeuchi","avatar":""},{"name":"Shin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Iruma à l’école des démons","डेमन स्कूल में आपका स्वागत है! इरुमा-कुन","Mairimashita! Iruma-kun","Mairimashita! Iruma-kun 2","Mairimashita, Iruma-kun","Mairimashita, Iruma-kun 2","Mairimashita! Iruma-kun 3","魔入りました！入間くん４","마계학교 이루마군","악마에 입문했습니다! 이루마 군","마계학교! 이루마군","Iruma w szkole demonów","อิรุมะคุงกับโรงเรียนปิศาจ","Welcome to Demon-School, Iruma-kun","Welcome to Demon School, Iruma-kun","The Demon, Iruma-kun, Came and Enrolled!","Enrolled Demon Iruma!","Here Comes the Demon! Iruma-Kun","Welcome to Demon School! Iruma-kun 2","Welcome to Demon-School! Iruma-kun 3","Vào Ma Giới Rồi Đấy","Vào Ma Giới Rồi Đấy! Iruma-kun","Vào Ma Giới Rồi Đấy Iruma-kun","魔入りました！入間くん"]', 1784690324314);
