INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vao-ma-gioi-roi-day-irumakun-phan-2', 'Vào Ma Giới Rồi Đấy! Iruma-Kun (Phần 2)', 'Welcome To Demon School! Iruma-kun (Season 2)', 'vào ma giới rồi đấy! iruma-kun (phần 2) welcome to demon school! iruma-kun (season 2) ayumu murase ryohei kimura ayaka asai daisuke ono saori hayami takuya sato takaya kuroda mitsuki saiga yoshitaka yamaya nao toyama tetsuya kakihara kaede hondo gakuto kajiwara takuto yoshinaga genki okawa shunichi toki junko takeuchi shin iruma à l’école des démons डेमन स्कूल में आपका स्वागत है! इरुमा-कुन mairimashita! iruma-kun mairimashita! iruma-kun 2 mairimashita, iruma-kun mairimashita, iruma-kun 2 mairimashita! iruma-kun 3 魔入りました！入間くん４ 마계학교 이루마군 악마에 입문했습니다! 이루마 군 마계학교! 이루마군 iruma w szkole demonów อิรุมะคุงกับโรงเรียนปิศาจ welcome to demon-school, iruma-kun welcome to demon school, iruma-kun the demon, iruma-kun, came and enrolled! enrolled demon iruma! here comes the demon! iruma-kun welcome to demon school! iruma-kun 2 welcome to demon-school! iruma-kun 3 vào ma giới rồi đấy vào ma giới rồi đấy! iruma-kun vào ma giới rồi đấy iruma-kun 魔入りました！入間くん', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-khong-gian-phan-2', 'Cuộc Chiến Không Gian (Phần 2)', 'For All Mankind (Season 2)', 'https://phimimg.com/upload/vod/20260328-1/6ee086e98c8fb61f94ccaf82b4c350a1.jpg', 'https://phimimg.com/upload/vod/20260328-1/7a281052886a91d8cc7527c94f8c1f82.jpg', '<p>Thế giới sẽ ra sao nếu cuộc chạy đua vào không gian chưa bao giờ kết thúc? Ronald D. Moore thử tìm lời đáp qua câu chuyện giả tưởng ly kỳ về các phi hành gia ngôi sao của NASA và gia đình họ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 15, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joel Kinnaman","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Mireille Enos","avatar":""},{"name":"Edi Gathegi","avatar":""},{"name":"Cynthy Wu","avatar":""},{"name":"Coral Peña","avatar":""},{"name":"Costa Ronin","avatar":""},{"name":"Sean Kaufman","avatar":""},{"name":"Ruby Cruz","avatar":""},{"name":"Wrenn Schmidt","avatar":""},{"name":"Ines Høysæter Asserson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bütün İnsanlıq Üçün","为全人类","עבור כל האנושות","برای همه بشریت","Ради всего человечества","For All Mankind"]', 1784690324314);
