INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-khong-gian-phan-2', 'Cuộc Chiến Không Gian (Phần 2)', 'For All Mankind (Season 2)', 'cuộc chiến không gian (phần 2) for all mankind (season 2) joel kinnaman toby kebbell mireille enos edi gathegi cynthy wu coral peña costa ronin sean kaufman ruby cruz wrenn schmidt ines høysæter asserson bütün i̇nsanlıq üçün 为全人类 עבור כל האנושות برای همه بشریت ради всего человечества for all mankind', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-kha-chien-bai-phan-1', 'Bất Khả Chiến Bại (Phần 1)', 'Invincible (Season 1)', 'https://phimimg.com/upload/vod/20260322-1/85421917636de969d5226abacb58e7e2.jpg', 'https://phimimg.com/upload/vod/20260322-1/80bd0f16deb492616f9fe360285a8f77.jpg', '<p>Invincible là series hoạt hình siêu anh hùng dành cho người lớn được chuyển thể từ truyện tranh cùng tên của Skybound/Image Comic do Robert Kirkman sáng tác. Phim được lên kế hoạch kéo dài trong 3 mùa và sẽ phát sóng thông qua nền tảng Amazon Prime Video.

Invincible là câu chuyện xoay quanh Mark Grayson, con trai của anh hùng mạnh nhất hành tinh - Omni-Man. Sau khi vừa tròn 17 tuổi, Mark bắt đầu thức tỉnh sức mạnh của riêng mình. Dưới sự giám hộ của Omni-Man, Mark dấn thân vào con đường trở thành siêu anh hùng và đối đầu với thử thách cam go.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 32, 2021, 'Vietsub + Lồng Tiếng', 'FHD', 'Canada', 0, '[{"name":"Steven Yeun","avatar":""},{"name":"Sandra Oh","avatar":""},{"name":"J.K. Simmons","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["无敌小子","无敌少侠","Unbesiegbar","Invencible","დაუმარცხებელი","無敵少俠","インビンシブル","O Invencivel","Неуязвимый","Nepremožiteľný","Невколупний","Непереможний","Невразливий","Invincible: Atom Eve","Invincible","INVINCIBLE"]', 1784690324314);
