INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-dao-nhat-chi-mai', 'Hiệp Đạo Nhất Chi Mai', 'Thief Female Hero (Thief Heroine)', 'https://phimimg.com/upload/vod/20260308-1/426a13b9ed1dca335e1a5dd49e5e5573.jpg', 'https://phimimg.com/upload/vod/20260308-1/059f76c46b99275601150c6702d3ae39.jpg', '<p>Bản đồ kho báu triều Minh tái hiện, Thẩm Diên với biệt hiệu là “Đạo Thánh Nhất Chi Mai” là đầu lĩnh của tổ chức thần bí “Thiên Cơ Môn”. Chàng ấy xuất hiện tranh giành báu vật, bất ngờ mắc bẫy Đông Xưởng mà bị thương nặng. Đồng thời, Cẩm Y Vệ phái Châu Mộ Phong cứu vớt Nhất Chi Mai. Vốn tưởng Châu Mộ Phong cùng chung mối thủ lại cũng mưu mô trong lòng. Thẩm Diên trước sau đều có địch, nguy cơ sống chết mới bắt đầu...</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Đông Đông","avatar":""},{"name":"Lý Quý","avatar":""},{"name":"Lý Nhược Hy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Thief Female Hero","Thief Heroine","盗圣一枝梅"]', 1784690324314);
