INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-dao', 'Cuồng Đao', 'Soul Of Blades', 'https://phimimg.com/upload/vod/20260215-1/1adc96d7523ff567cc00cbd6f3912a32.jpg', 'https://phimimg.com/upload/vod/20260215-1/833fa8fa40792c6354e0772b961f4cc8.jpg', '<p>Thanh kim đao do gia tộc đúc kiếm Nam Cung đúc ra bị kiếm khách &quot;Tần Nhất Đao&quot; cướp mất, kim đao có sức mê hoặc cực lớn, trên giang hồ bắt đầu treo thưởng bắt hắn. Trong một lần trốn truy sát, Tần Nhất Đao nhặt được một cậu bé tên A Cẩu và dẫn cậu đến vùng đất hỗn loạn &quot;Tam Bất Quản&quot;. Sau khi A Cẩu trưởng thành, tiểu thư gia tộc Nam Cung biết được vị trí của kẻ thù, dùng khổ nhục kế tiếp cập A Cẩu, ý đồ lợi dụng A Cẩu giết chết Tần Nhất Đao, mà lúc này A Cẩu đã biết được bí mật của kim đao...</p>', 'Full', 1, 'single', 'completed', 29, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Kình Đường","avatar":""},{"name":"Vi Ni","avatar":""},{"name":"Lý Thừa Tịch","avatar":""},{"name":"Đường Văn Long","avatar":""},{"name":"Nguyên Bảo","avatar":""},{"name":"Uyển Quỳnh Đan","avatar":""},{"name":"Ngụy Tiểu Hoan","avatar":""},{"name":"Lưu Hạo Nham","avatar":""},{"name":"Khang Ân Hách","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["狂刀-Cuồng Đao"]', 1784690324314);
