INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuong-dao', 'Cuồng Đao', 'Soul Of Blades', 'cuồng đao soul of blades hoàng kình đường vi ni lý thừa tịch đường văn long nguyên bảo uyển quỳnh đan ngụy tiểu hoan lưu hạo nham khang ân hách 狂刀-cuồng đao', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-cham-la-no-tru-bom-nhat-xuc-tuc-phat-chi-tru-bao', 'Một Chạm Là Nổ: Trừ Bom (Nhất Xúc Tức Phát Chi Trừ Bạo)', 'On The Verge', 'https://phimimg.com/upload/vod/20260208-1/aaf6719bea8c551762968cbedfcfd152.jpg', 'https://phimimg.com/upload/vod/20260208-1/7e3eefa8df2b05d0b14dbc40e060f94f.jpg', '<p>An Vũ Hoán – một cao thủ võ thuật – vì sự thất lạc tình cờ của một chiếc hộp bí ẩn mà bị cuốn vào vòng xoáy tranh giành tàn khốc giữa các băng nhóm tội phạm. Những sát thủ xã hội đen máu lạnh bắt đầu mở một cuộc truy sát sinh tử nhắm vào anh.&nbsp; Để giải cứu người em gái vốn là điểm tựa duy nhất trong đời, An Vũ Hoán đã đơn thương độc mã, dùng đôi tay trần đối đầu với hàng trăm kẻ thù. Đặt cược cả tính mạng, anh tiến tới trận quyết chiến cuối cùng với tên trùm băng đảng. Lần này, An Vũ Hoán quyết định dùng nắm đấm của chính mình để đòi lại công đạo thuần túy nhất và chiến đấu vì chính nghĩa!</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Nhất Minh","avatar":""},{"name":"Trịnh Trung Cơ","avatar":""},{"name":"Inés Ê-phrôn","avatar":""},{"name":"Jennifer","avatar":""},{"name":"Cindy","avatar":""},{"name":"Trịnh Sở Dịch","avatar":""},{"name":"Vương Phán","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Yi Chu Ji Fa Zhi Chu Bao","一触即发之除爆"]', 1784690324314);
