INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-cham-la-no-tru-bom-nhat-xuc-tuc-phat-chi-tru-bao', 'Một Chạm Là Nổ: Trừ Bom (Nhất Xúc Tức Phát Chi Trừ Bạo)', 'On The Verge', 'một chạm là nổ: trừ bom (nhất xúc tức phát chi trừ bạo) on the verge trần nhất minh trịnh trung cơ inés ê-phrôn jennifer cindy trịnh sở dịch vương phán yi chu ji fa zhi chu bao 一触即发之除爆', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-thuat-hoi-chien-0-truong-chuyen-chu-thuat-tokyo', 'Chú Thuật Hồi Chiến 0: Trường Chuyên Chú Thuật Tokyo', 'Jujutsu Kaisen 0', 'https://phimimg.com/upload/vod/20260207-1/b1a940340882577c2d5d44a57e5d26b6.jpg', 'https://phimimg.com/upload/vod/20260207-1/c061a30c66499600aed1b4d8714d436e.jpg', '<p>Yuta Okkotsu là một học sinh trung học hay lo lắng đang phải chịu đựng một vấn đề nghiêm trọng—người bạn thời thơ ấu Rika của anh đã trở thành một lời nguyền và không để anh yên. Vì Rika không phải là một lời nguyền bình thường nên hoàn cảnh của anh được Satoru Gojo, một giáo viên tại trường trung học Jujutsu, một ngôi trường nơi các nhà trừ tà non trẻ học cách chống lại lời nguyền chú ý đến. Gojo thuyết phục Yuta ghi danh, nhưng liệu anh có thể học đủ kịp thời để đối mặt với lời nguyền ám ảnh mình không?</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Megumi Ogata","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Mikako Komatsu","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Mitsuo Iwata","avatar":""},{"name":"Takaya Kuroda","avatar":""},{"name":"Risae Matsuda","avatar":""},{"name":"Satsumi Matsuda","avatar":""},{"name":"Shizuka Itoh","avatar":""},{"name":"Show Hayami","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Rie Kugimiy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b0