INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuc-toc-chien-tuong', 'Cực Tốc Chiến Tướng', 'Speed ​​Fighter (The Speed Warrior)', 'https://phimimg.com/upload/vod/20260207-1/cd13afadaf8ebb15edbdd6b444144345.jpg', 'https://phimimg.com/upload/vod/20260207-1/984084ecf2b1d45df0a2828e024bb288.jpg', '<p>Lý Húc, một nhân viên đặc vụ công an, đã thâm nhập vào một tập đoàn buôn bán ma túy nhằm triệt phá ổ nhóm của chúng. Để điều tra kẻ cung cấp nguồn hàng phía trên, Lý Húc cố ý tiếp cận A Mỹ – người tình của tên cầm đầu, nhưng kế hoạch đã bị phát giác. Là một kẻ tâm địa độc ác, A Mỹ bắt cóc Trương Tư Di, em gái của người anh em thân thiết với Lý Húc, để uy hiếp anh phải giúp cô ta vận chuyển ma túy.&nbsp; A Mỹ gắn bom lên người Trương Tư Di và thực hiện giám sát Lý Húc qua video để ngăn anh báo cảnh sát. Quả bom được thiết lập sẽ tự động phát nổ sau hai giờ. Lý Húc phải tìm cách kết thúc trò chơi sinh tử này trước khi đồng hồ đếm ngược trở về số không...</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Thiêm Kỳ","avatar":""},{"name":"Ngô Văn Cảnh","avatar":""},{"name":"Ân Nghĩa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Extreme Speeo Warridr","极速战将"]', 1784690324314);
