INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-ky-di-cua-ban-than', 'Điểm Kỳ Dị Của Bản Thân', 'Naked Singularity', 'https://phimimg.com/upload/vod/20260206-1/88630bc0a91db4b6c5c388629015b569.jpg', 'https://phimimg.com/upload/vod/20260206-1/6f9e2e29e0d3f223c480344935be3188.jpg', '<p>Khi một luật sư thành công ở New York thua vụ án đầu tiên, anh ta bị một khách hàng cũ lôi kéo vào một vụ trộm ma túy trong nỗ lực đánh bại hệ thống bị hỏng trong chính trò chơi của nó.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"John Boyega","avatar":""},{"name":"Olivia Cooke","avatar":""},{"name":"Bill Skarsgård","avatar":""},{"name":"Ed Skrein","avatar":""},{"name":"Linda Lavin","avatar":""},{"name":"Tim Blake Nelson","avatar":""},{"name":"Kyle Mooney","avatar":""},{"name":"Robert Christopher Riley","avatar":""},{"name":"Robert T. Bogue","avatar":""},{"name":"K. Todd Freeman","avatar":""},{"name":"Liza Colón-Zayas","avatar":""},{"name":"Scott Barrows","avatar":""},{"name":"Teddy Cañez","avatar":""},{"name":"Tatsuo Ichikawa","avatar":""},{"name":"Robert Lee Leng","avatar":""},{"name":"Rao Rampilla","avatar":""},{"name":"Jos","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Con su propia justicia","Naked Singularity"]', 1784690324314);
