INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diem-ky-di-cua-ban-than', 'Điểm Kỳ Dị Của Bản Thân', 'Naked Singularity', 'điểm kỳ dị của bản thân naked singularity john boyega olivia cooke bill skarsgård ed skrein linda lavin tim blake nelson kyle mooney robert christopher riley robert t. bogue k. todd freeman liza colón-zayas scott barrows teddy cañez tatsuo ichikawa robert lee leng rao rampilla jos con su propia justicia naked singularity', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-cuc-2021', 'Bố Cục', 'Layout', 'https://phimimg.com/upload/vod/20260203-1/f71eb4fa0ac929e43c1614773ffbced1.jpg', 'https://phimimg.com/upload/vod/20260203-1/0ec4911ed609bab8c223e10a3b81e7da.jpg', '<p>Lấy bối cảnh ngành công nghiệp sòng bạc (cờ bạc) tại Ma Cao, bộ phim kể về hai thương hội lớn là &#39;Thiên Hợp&#39; và &#39;Địa Thắng&#39; thuộc tập đoàn Thiên Địa Hợp Thịnh. Sau nhiều năm nỗ lực gây dựng, sản nghiệp của họ ngày càng lớn mạnh. Tuy nhiên, khi người đứng đầu tập đoàn đã tuổi cao sức yếu, cuộc tranh giành quyền lực mới bắt đầu diễn ra quyết liệt.&nbsp; Lợi dụng sự đấu đá nội bộ này, thương hội &#39;Đại Thành&#39; – một thế lực đen tối từ nước ngoài – đã dùng mọi thủ đoạn hèn hạ để chiếm đoạt quyền kinh doanh sòng bạc. Chúng sử dụng các sòng bạc này làm công cụ để rửa tiền và thực hiện các hoạt động bất hợp pháp, làm lũng đoạn thị trường và phá hoại các quy tắc đạo đức kinh doanh.&nbsp; Trước tình thế hiểm nghèo đó, hai thương hội &#39;Thiên Hợp&#39; và &#39;Địa Thắng&#39; đã quyết định gạt bỏ tư thù, đoàn kết một lòng vì đại nghĩa dân tộc. Họ phối hợp cùng cảnh sát để triệt phá thế lực kinh tế đen tối từ bên ngoài, bảo vệ trật tự kinh tế quốc gia.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 11, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Jingwei","avatar":""},{"name":"Kun Hua","avatar":""},{"name":"Yu Zhang","avatar":""},{"name":"Liu Tingzuo","avatar":""},{"name":"Ricky Chan Po-Yuen","avatar":""},{"name":"Sena Ng","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Ken Lo Wai-Kwong","avatar":""},{"name":"Shek Sau","avatar":""},{"name":"Ricky Wong Chun-Tong","avatar":""},{"name":"Alan Chui Chung-San","avatar":""},{"name":"Shum Wai","avatar":""},{"name":"Sonny Chiba","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bu Ju","布局"]', 1784690324314);
