INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('d-r-3-a-m-di-chuyen', 'D R 3 A M Dị Chuyện', 'D R 3 A M Strange Tales', 'https://phimimg.com/upload/vod/20241104-1/d6bbe0a6da9f74fd792a8af14942e27d.jpg', 'https://phimimg.com/upload/vod/20241104-1/51e02cd69f7ae85195614b5663a2ee4a.jpg', '<p>Bộ phim là tản mạn những câu chuyện quỷ quái thời hiện đại, đi sâu khai thác nỗi sợ hãi về những bóng ma ẩn náu trong bóng tối của chốn thành thị, những bí ẩn kinh hoàng trong tâm trí con người. Từ nhà sản xuất của Mắt Biếc, màu sắc phim mới mẻ này chắc chắn sẽ khiến bạn phải bất ngờ.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 22, 2021, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hồ Thu Anh","avatar":""},{"name":"Ánh Ngọc","avatar":""},{"name":"Kiều Trinh","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Beibishiteo","베이비시터"]', 1784690324314);
