INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngay-thanh-trung-vinh-vien', 'Ngày Thanh Trừng Vĩnh Viễn', 'The Forever Purge', 'ngày thanh trừng vĩnh viễn the forever purge ana de la reguera josh lucas willow beuoy leven rambin will patton cassidy freeman tenoch huerta mejía susie abromeit anthony molinari alejandro edda will brittain sammi rotibi mark krenik gregory zaragoza brett edwards gary nohealii jeffr чистка 5 國定殺戮日：無限狂屠 the forever purge la purga infinita uma noite de crime 5:  a fronteira american nightmare 5 : sans limites la purge éternelle 國定殺戮日5：無限狂屠 더 퍼지; 포에버 더 퍼지 5; 포에버 더 퍼지 5: 포에버 הטיהור 5 the purge 5: the forever purge ngày thanh trừng 5 uma noite de crime 5 a fronteira 人类清除计划5 the forever purge', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-xa-2-thanh-xa-kiep-khoi', 'Bạch Xà 2: Thanh Xà Kiếp Khởi', 'Green Snake', 'https://phimimg.com/upload/vod/20260125-1/1eb0172990caedaf4a31e94ebe902bff.jpg', 'https://phimimg.com/upload/vod/20260125-1/f8c70bd12cd5421361b04c61984e00ed.jpg', '<p>Bạch Xà 2: Thanh Xà kiếp khởi tiếp nối mạch truyện của phần 1. Rắn tinh Tiểu Bạch đã bị pháp sư Pháp Hải nhốt vào Lôi Phong tháp. Tiểu Thanh vì xả thân cứu chị đã bị đánh vào cõi Atula, đến cảnh giới Niết Bàn vô ngã vô sắc. &nbsp;Khi đang băng qua những cửa ải khó khăn, mây khói mịt mù, mờ ảo thì bỗng nghe thấy tiếng còi cảnh sát vang lên từ xa. Và rồi một thế giới hiện đại xuất hiện với những toà nhà chọc trời, Tiểu Thanh cảm thấy choáng ngợp và vô cùng hoang mang. &nbsp;Tại đây cô đã vô tình gặp được một chàng trai lạ mặt, nhiều lần cứu Thanh Xà thoát khỏi hiểm nguy, liệu điều gì sẽ xảy ra tiếp theo? Muốn vượt qua không gian, thời gian vô ngã để quay lại cứu Tiểu Bạch thì Tiểu Thanh phải làm gì?</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tang Xiaoxi","avatar":""},{"name":"Zhang Fuzheng","avatar":""},{"name":"Wei Chao","avatar":""},{"name":"Zhao Mingzhou","avatar":""},{"name":"Zheng Xiaopu","avatar":""},{"name":"Ma Cheng","avatar":""},{"name":"Song Xuchen","avatar":""},{"name":"Qiu Qiu","avatar":""},{"name":"Zhang Kai","avatar":""},{"name":"Xu Jiaqi","avatar":""},{"name":"Shuai Guan","avatar":""},{"name":"Zhang Biyu","avatar":""},{"name":"Zhang Zhe","avatar":""},{"name":"Yang Tianxiang","avatar":""},{"name":"Baomu Zhongyang","avatar":""},{"name":"Lin Qiang","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["White Snake 2","White Snake 2: The Green Snake Tribulation","White Snake 2: The Tribulation of the Green Snake","白蛇2：青蛇劫起","Зелёная змея","Bai She 2: Qing She jie qi","White Snake 2: Green Snake","นาคามรกต","白蛇II：青蛇劫起","白蛇2: 青蛇劫起","白蛇 2: 青蛇劫起","白蛇 2：青蛇劫起","White Snake II: Green Snake","Báishé èr: Qīngshé jiéqǐ","白蛇2：青蛇興起","白蛇2 青蛇興起","백사 2: 청사의 시련","백사2: 청사의 시련","A Serpente Branca 2","White Snake II: Tribulations of the Green Snake"]', 1784690324314);
