INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-phap-y-ngu-tu-tieu-ngo-tac-phan-1', 'Nữ Pháp Y (Ngự Tứ Tiểu Ngỗ Tác) (Phần 1)', 'The Imperial Coroner (Season 1)', 'https://phimimg.com/upload/vod/20251107-1/951509eed0b9779f260f466adac28d56.jpg', 'https://phimimg.com/upload/vod/20260115-1/a281b85aa7e36039ade4548ad9154a19.jpg', '<p>Phim lấy bối cảnh vào thời Đường, chuyện bắt đầu từ gia đình ngỗ tác sống tại khu Tây Nam Sơn có thiếu nữ tên Sở Sở, cô trông xinh đẹp nhưng tính tình lại ương ngạnh. Vì muốn theo đuổi ước mơ nên đã liều mình đi đến Trường An tham gia kỳ thi ngỗ tác (quan khám nghiệm tử thi). Tại đây cô gặp được một người có khả năng phá án thần sầu tên An Quân Vương Tiêu Cẩn Du.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 14, 2021, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Tô Hiểu Đồng","avatar":""},{"name":"Vương Tử Kỳ","avatar":""},{"name":"Dương Đình Đông","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["御赐小仵作 2","御赐小仵作 第二季","Yu Ci Xiao Wu Zuo 2","Yu Ci Xiao Wu Zuo","御赐小仵作 第2季","Yu Ci Xiao Wu Zuo Di Er Ji","Detektif Kerajaan S2","御用検事S2","황실 검시관","어사소오작: 미스터리 검시관","어사소오작 시즌2","机智女法医","Jade The Imperial Coroner","Императорский коронер 2","御賜小仵作","御賜小仵作 第二季","The Imperial Coroner","The Imperial Coroner S2","The Imperial Coroner Season 2","Ngự Tứ Tiểu Ngỗ Tác 2","御赐小仵作"]', 1784690324314);
