INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('godzilla-dai-chien-kong', 'Godzilla Đại Chiến Kong', 'Godzilla vs. Kong', 'https://phimimg.com/upload/vod/20260123-1/b468a7efc3020313a44166e79f6d875b.jpg', 'https://phimimg.com/upload/vod/20260123-1/fd5d7563ba6edb504be25369355e3740.jpg', '<p>Khi hai kẻ thù truyền kiếp gặp nhau trong một trận chiến ngoạn mục, số phận của cả thế giới vẫn còn bị bỏ ngỏ… Bị đưa khỏi Đảo Đầu Lâu, Kong cùng Jia, một cô bé mồ côi có mối liên kết mạnh mẽ với mình và đội bảo vệ đặc biệt hướng về mái nhà mới. Bất ngờ, nhóm đụng độ phải Godzilla hùng mạnh, tạo ra một làn sóng hủy diệt trên toàn cầu. Thực chất, cuộc chiến giữa hai kẻ khổng lồ dưới sự thao túng của các thế lực vô hình mới chỉ là điểm khởi đầu để khám phá những bí ẩn nằm sâu trong tâm Trái đất.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Alexander Skarsgård","avatar":""},{"name":"Rebecca Hall","avatar":""},{"name":"Kaylee Hottle","avatar":""},{"name":"Brian Tyree Henry","avatar":""},{"name":"Millie Bobby Brown","avatar":""},{"name":"Julian Dennison","avatar":""},{"name":"Demián Bichir","avatar":""},{"name":"Eiza González","avatar":""},{"name":"Shun Oguri","avatar":""},{"name":"Kyle Chandler","avatar":""},{"name":"Lance Reddick","avatar":""},{"name":"Hakeem Kae-Kazim","avatar":""},{"name":"Ronny Chieng","avatar":""},{"name":"John Pirruccello","avatar":""},{"name":"Chris Chalk","avatar":""},{"name":"Conlan Casal","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d47