INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuc-thu-cuoc-doi-tokyo-revengers-live-action-movie', 'Phục Thù Cuộc Đời (Tokyo Revengers Live Action Movie)', 'Tokyo Revengers', 'https://phimimg.com/upload/vod/20260118-1/a7810a9e0ef8eed91fb7624c97236b18.jpg', 'https://phimimg.com/upload/vod/20260118-1/1a7cecc2eb0d85d519e0aafd25fefaec.jpg', '<p>Hanagaki Takemichi rỗi việc sống trong một căn hộ tồi tàn, có công việc khốn khổ và bị tên sếp chế giễu. Vào một ngày khi đang coi thời sự, Takemichi phát hiện Tachibana Hinata – cô bạn gái cũ duy nhất trong cuộc đời cậu hồi học trung học, đã bị băng đảng Tokyo Manji giết chết. Tưởng chừng như hiện tại sẽ là địa ngục trần gian mãi này, thế nhưng cậu bỗng có cơ hội trở về quá khứ 10 năm trước vào những tháng ngày trung học. Hanagaki Takemichi quyết tâm thay đổi tương lai cứu sống Hinata bằng một cách duy nhất chính là giải tán Tokyo Manji!!!</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takumi Kitamura","avatar":""},{"name":"Ryo Yoshizawa","avatar":""},{"name":"Yuki Yamada","avatar":""},{"name":"Yosuke Sugino","avatar":""},{"name":"Mio Imada","avatar":""},{"name":"Hayato Isomura","avatar":""},{"name":"Nobuyuki Suzuki","avatar":""},{"name":"Shotaro Mamiya","avatar":""},{"name":"Hiroya Shimizu","avatar":""},{"name":"Gordon Maeda","avatar":""},{"name":"Kazuki Horike","avatar":""},{"name":"Shunji Tagawa","avatar":""},{"name":"Rio Takahashi","avatar":""},{"name":"Hinata Todo","avatar":""},{"name":"Kazuki Miki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["โตเกียว รีเวนเจอร์ส","Tokyo Revengers (Live-Action)","東京卍リベンジャーズ","东京复仇者","Kịch trường của Takemichi","東京リベンジャーズ"]', 1784690324314);
