INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truyen-kinh-di-my-phan-10-double-feature', 'Truyện Kinh Dị Mỹ (Phần 10) (Double Feature)', 'American Horror Story (Season 10)', 'truyện kinh dị mỹ (phần 10) (double feature) american horror story (season 10) emma roberts matt czuchry kim kardashian annabelle dexter-jones michaela jaé rodriguez denis o''hare cara delevingne julie white maaz ali história de horror americana uma história de horror americana 美恐 american horror story - die dunkle seite in dir american horror story: la casa del crimen סיפור אימה אמריקאי アメリカン・ホラー・ストーリー 아메리칸 호러 스토리 американская история ужасов американська історія жахів american horror story: freak show ahs hotel american horror story: hotel ahs american horror story: murder house american horror story: asylum american horror story: coven american horror story: roanoke american horror story: cult american horror story: apocalypse american horror story: 1984 american horror story: double feature american horror story: red tide american horror story: death valley american horror story: nyc american horror story: delicate american horror story', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-nu-diep-vu-tho-xu-ly-vuong-mien-1', 'Năm Nữ Điệp Vụ: Thợ Xử Lý Vương Miện 1', 'Princess Principal Crown Handler: Chapter 1', 'https://phimimg.com/upload/vod/20260117-1/fc7dcbe77afd9e3e51f7a7871e676332.jpg', 'https://phimimg.com/upload/vod/20260117-1/3df41cd90a79cc29dfe5df8c1c06c9ec.jpg', '<p>Câu chuyện lấy bối cảnh tại London vào cuối thế kỷ 19. Một nhiệm vụ mới đã được giao cho Đội Bồ Câu Trắng (Team White Pigeon), nhóm điệp viên thuộc Khối Thịnh vượng chung. Nhiệm vụ lần này là giải cứu và đưa một chủ tiệm sách cũ về phía Thịnh vượng chung. Ange, Dorothy và Chise đã thực hiện thành công việc giành lại người chủ tiệm này khi ông ta đang bị phía Vương quốc giam giữ tại một trung tâm cải huấn.Trong khi đó, chiến dịch &#39;săn lùng gián điệp&#39; tại Vương quốc ngày càng trở nên gắt gao sau nỗ lực ám sát Nữ hoàng, khiến bầu không khí tại Trung tâm điều hành của Khối Thịnh vượng chung cũng trở nên căng thẳng tột độ. Phía Điều hành nghi ngờ rằng điệp viên được phái đến cài cắm trong hoàng gia có thể là một &#39;gián điệp nhị trùng&#39; (điệp viên hai mặt). Để tìm ra sự thật, họ ra lệnh cho Đội Bồ Câu Trắng tiếp cận với điệp viên có mật danh là &#39;Bishop&#39;. Liệu nhiệm vụ mới này sẽ được hoàn thành ra sao? Và danh tính thật sự của &#39;Bishop&#39; là ai?</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aoi Koga","avatar":""},{"name":"Akira Sekine","avatar":""},{"name":"You Taichi","avatar":""},{"name":"Akari Kageyama","avatar":""},{"name":"Nozomi Furuki","avatar":""},{"name":"Takayuki Sugo","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Hiroyuki Honda","avatar":""},{"name":"Takumi Yamazaki","avatar":""},{"name":"Takaya Hashi","avatar":""},{"name":"Yuuko Iida","avatar":""},{"name":"Nobuo Tobita","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["公主准则剧场版","公主准则 第一章","프린세스 프린서플 크라운 핸들러 제1장","Princess Principal: Crown Handler Part 1","Princess Principal: Crown Handler 1","プリンセス・プリンシパル Crown Handler 第1章"]', 1784690324314);
