INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-nhan-chi-ha-phan-4-nguoi-tren-van-nguoi', 'Nhất Nhân Chi Hạ (Phần 4) (Người Trên Vạn Người)', 'The Outcast (Season 4) (Hitori No Shita)', 'https://phimimg.com/upload/vod/20260110-1/8669355e5b56abe3556aacdeb930984c.jpg', 'https://phimimg.com/upload/vod/20260110-1/c8dc264be8b89c341cb298a0454a445d.jpg', '<p>Bộ phim kể câu chuyện về một nhóm người dị nhân có siêu năng lực ở một thành phố thời hiện đại. Những người này bề ngoài không khác gì người thường, nhưng lại thân mang tuyệt kỹ. Phần &quot;Thôn Bích Du&quot; này là phần 4. Người phụ trách &quot;Nhân viên thời vụ&quot; đại khu Hoa Nam bị &quot;Nhân viên thời vụ&quot; Trần Đóa giết chết, các nhân viên thời vụ ở các khu khác nhận được nhiệm vụ đi Tây Nam bắt Trần Đóa về, nhưng trên đường truy bắt gặp phải Mã Tiên Hồng đến từ thôn Bích Du....</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Liansha","avatar":""},{"name":"Sheng Feng","avatar":""},{"name":"Yuntu Cao","avatar":""},{"name":"Shan Xin","avatar":""},{"name":"Ajie","avatar":""},{"name":"Wang Chenguang","avatar":""},{"name":"Baomu Zhongyang","avatar":""},{"name":"Teng Xin","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一人之下","Fengqi Yunyong, Luotian Dajiao","异人","Yi Ren Zhi Xia","Yi Ren Zhixi