INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-hoa-trong-an', 'Nộ Hỏa: Trọng Án', 'Raging Fire', 'https://phimimg.com/upload/vod/20250616-1/88a033a78ea63ed0eee0f4067c67ae62.jpg', 'https://phimimg.com/upload/vod/20250616-1/95f946498f765ba43cb3664bccc6e735.jpg', '<p>Trong lúc làm nhiệm vụ, đội của Trương Tuý Bang (Chân Tử Đan) đã đối đầu một nhóm tội phạm bí ẩn. Mà thủ lĩnh lại chính là cậu học trò A Ngao (Tạ Đình Phong), người từ bỏ công lý, trả thù tổ chức cũ.</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tạ Đình Phong","avatar":""},{"name":"Chân Tử Đan","avatar":""},{"name":"Tần Lam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Nou fo","怒火·重案","Crossfire 2021","Raging Fire","Frente à Frente","Cara a Cara","レイジング・ファイア","Nù Huǒ","怒火"]', 1784690324314);
