INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-den-khi-chet-toi-chet', 'Cho Đến Khi Chết (Tới Chết)', 'Till Death', 'https://phimimg.com/upload/vod/20251228-1/4e2e201d81170655613289e164d4b41e.jpg', 'https://phimimg.com/upload/vod/20251228-1/c0818219e0486ca19e3d49cf4936b27c.jpg', '<p>Một người phụ nữ bị còng tay với người chồng đã chết của mình trong một phần của âm mưu trả thù bệnh hoạn. Không thể tháo xích, cô ấy phải sống sót khi hai kẻ giết người đến để kết liễu cô ấy.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Pháp', 0, '[{"name":"Megan Fox","avatar":""},{"name":"Eoin Macken","avatar":""},{"name":"Aml Ameen","avatar":""},{"name":"Callan Mulvey","avatar":""},{"name":"Jack Roth","avatar":""},{"name":"Stefanie Yunger","avatar":""},{"name":"Teodora Djuric","avatar":""},{"name":"Lili Rich","avatar":""},{"name":"Julian Balahurov","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Aż do śmierci","Till Death. Hasta que la muerte nos separe","Till Death - Bis dass dein Tod uns scheidet","Jusqu''à la mort","Hasta que mueras","Hasta la Muerte - Sobrevivir es la Mejor Venganza","長相屍手","Till Death"]', 1784690324314);
