INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-vang-phan-4', 'Đá Vàng (Phần 4)', 'Yellowstone (Season 4)', 'https://phimimg.com/upload/vod/20251125-1/0687861fd8e0bd9f8402f2de784406f2.jpg', 'https://phimimg.com/upload/vod/20251125-1/b3cd99f73c6b641ac14dbb7a585608db.jpg', '<p>Theo dõi thế giới bạo lực của gia đình Dutton, người kiểm soát trang trại tiếp giáp lớn nhất ở Hoa Kỳ. Được lãnh đạo bởi tộc trưởng John Dutton, gia đình bảo vệ tài sản của họ trước sự tấn công liên tục của các nhà phát triển đất đai, khu bảo tồn của người da đỏ và Công viên Quốc gia đầu tiên của Hoa Kỳ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 32, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Luke Grimes","avatar":""},{"name":"Kelly Reilly","avatar":""},{"name":"Wes Bentley","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Kelsey Asbille","avatar":""},{"name":"Brecken Merrill","avatar":""},{"name":"Ryan Bingham","avatar":""},{"name":"Finn Little","avatar":""},{"name":"Ian Bohen","avatar":""},{"name":"Forrie J. Smith","avatar":""},{"name":"Denim Richards","avatar":""},{"name":"Wendy Moniz","avatar":""},{"name":"Jennifer Landon","avatar":""},{"name":"Kathryn Kelly","avatar":""},{"name":"Mo Brings Plenty","avatar":""},{"name":"Gil Birmingham","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yellowstone"]', 1784690324314);
