INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khap-huyet-dao-cua-lan-lang-vuong', 'Khấp Huyết Đao Của Lan Lăng Vương', 'Prince Of Lanling: Blood Weeping Blade (Blood Weeping Blade Of Lanling King)', 'https://phimimg.com/upload/vod/20251226-1/4775a9376e963d39a1c012120f8c79a8.jpg', 'https://phimimg.com/upload/vod/20251226-1/eaf346e9fe10963b490e6d8d26b16220.jpg', '<p>Một danh tướng của triều đại Bắc Tề, Lan Lăng Vương (Cao Trường Cung) đã thể hiện tài nghệ của mình trong trận đấu ở Núi Mang, đẩy lùi quân xâm lược Bắc Chu, nhưng khi trở về triều đình, ông phải đối mặt với một đối thủ nguy hiểm hơn là tên quan lạm quyền- Hòa Sĩ Khai .Cao Trường Cung, huynh trưởng Cao Hiếu Du, và tướng quân Đoàn Thiệu đã thành lập một đội quân chính nghĩa để bảo vệ Hoàng thượng, và chiến đấu hết trận này đến trận khác với Hòa Sĩ Khai và thuộc hạ của ông ta. Đúng lúc này, nữ hiệp dân gian Mộc Lan đột nhiên xuất hiện trong cuộc đời của Cao Trường Cung. Cao Trường Cung đã phải lòng cô gái thẳng thắn vui vẻ này, nhưng Mộc Lan lại ẩn giấu một bí mật kinh hoàng...</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Diệp Tượng Minh","avatar":""},{"name":"Miên Phi","avatar":""},{"name":"Tiêu Na","avatar":""},{"name":"Nam Sinh","avatar":""},{"name":"Lý Tử Hùng","avatar":""},{"name":"Lương Gia Nhân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Lan Ling Wang Zhi Qi Xue Dao Feng","兰陵王之泣血刀锋"]', 1784690324314);
