INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kyra-va-the-gioi-phep-thuat-phan-2', 'Kyra Và Thế Giới Phép Thuật (Phần 2)', 'The Bureau Of Magical Things (Season 2)', 'https://phimimg.com/upload/vod/20251226-1/b79d3149255e73c4f7326e29db141552.jpg', 'https://phimimg.com/upload/vod/20251226-1/27ce9fce7d97617b5cc3ca4c7f4da87e.jpg', '<p>Khi cô thiếu niên bình thường Kyra chạm vào một cuốn sách bí ẩn, cô đã bị biến đổi thành một &quot;Tri-ling&quot; — thực thể mang trong mình ba dòng máu: người, tiên tử (fairy) và yêu tinh (elf). Bên cạnh việc sở hữu những sức mạnh phép thuật kinh ngạc, Kyra còn khám phá ra một thế giới phép thuật bí mật đang tồn tại ngay xung quanh mình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 26, 2021, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Kimie Tsukakoshi","avatar":""},{"name":"Mia Milnes","avatar":""},{"name":"Elizabeth Cullen","avatar":""},{"name":"Julian Cullen","avatar":""},{"name":"Rainbow Wedell","avatar":""},{"name":"Jamie Carter","avatar":""},{"name":"Christopher Sommers","avatar":""},{"name":"Nicholas Bell","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ured za čarolije","Бюро магических штучек","The Bureau of Magical Things"]', 1784690324314);
