INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('apache-junction', 'Apache Junction', 'Apache Junction', 'https://phimimg.com/upload/vod/20251216-1/8935aa6232e086da2d9cb78fbe1ec302.jpg', 'https://phimimg.com/upload/vod/20251216-1/5b10d80ca5a0703f63962bd684dee44d.jpg', '<p>Apache Junction là một tiền đồn của sự vô luật pháp, thiên đường của những tên trộm và những kẻ giết người máu lạnh. Sau khi phóng viên thành phố lớn Annabelle Angel đến để viết một bài báo về thị trấn, cô trở thành mục tiêu khi tay súng khét tiếng Jericho Ford đến giúp đỡ. Giờ đây, Annabelle phải giao phó tương lai của mình cho một người đàn ông có quá khứ chết chóc, khi Jericho đang tiến vào một cuộc đối đầu căng thẳng.</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Stuart Townsend","avatar":""},{"name":"Scout Taylor-Compton","avatar":""},{"name":"Trace Adkins","avatar":""},{"name":"Thomas Jane","avatar":""},{"name":"Ed Morrone","avatar":""},{"name":"Victoria Pratt","avatar":""},{"name":"Edward Finlay","avatar":""},{"name":"Danielle Gross","avatar":""},{"name":"Phil Burke","avatar":""},{"name":"Wanna Choy","avatar":""},{"name":"J. Nathan Simmons","avatar":""},{"name":"Luella Hill","avatar":""},{"name":"Josh Folan","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Apache Junction - Stadt der Gesetzlosen","Apache Junction"]', 1784690324314);
