INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-cap-ta-day', 'Siêu Cấp Ta Đây', 'Super Me', 'https://phimimg.com/upload/vod/20251206-1/3c490d9f845c55089502a11f86307e87.jpg', 'https://phimimg.com/upload/vod/20251206-1/97182436fa2f0a743b5301c3628950eb.jpg', '<p>Một biên kịch đang khó khăn bỗng khám phá ra khả năng béo bở: mang đồ cổ trong giấc mơ ra đời thực. Nhưng rắc rối chẳng mấy chốc đã gõ cửa cuộc sống mới của anh.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Đại Lục","avatar":""},{"name":"Tống Giai","avatar":""},{"name":"Tào Bỉnh Côn","avatar":""},{"name":"Ngô Cương","avatar":""},{"name":"Kim Sĩ Kiệt","avatar":""},{"name":"Vương Tử Dật","avatar":""},{"name":"Lý Tiệp","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qi Huan Zhi Lv","Magic Journey to Africa","Super Me","超级的我"]', 1784690324314);
