INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-cap-ta-day', 'Siêu Cấp Ta Đây', 'Super Me', 'siêu cấp ta đây super me vương đại lục tống giai tào bỉnh côn ngô cương kim sĩ kiệt vương tử dật lý tiệp qi huan zhi lv magic journey to africa super me 超级的我', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luong-y-giua-bau-troi-sao-bac-si-nhi-khoa', 'Lương Y Giữa Bầu Trời Sao (Bác Sĩ Nhi Khoa)', 'Kids'' Lives Matter', 'https://phimimg.com/upload/vod/20251203-1/f59856364d1b6507ada664c3b7598e8c.jpg', 'https://phimimg.com/upload/vod/20251203-1/23b05af9c38edef03e494ac92b2ca309.jpg', '<p>Hai mươi năm trước, một ca phẫu thuật đã khiến mối quan hệ giữa bác sĩ thực tập nội trú khoa Nhi – Huống Tùng Hân (do Mã Quốc Minh đóng) và Hứa Cam Phong (do Trịnh Gia Dĩnh đóng) rạn nứt. Thời gian trôi qua, Tùng Hân trở thành bác sĩ tư vấn phẫu thuật Nhi khoa ở một bệnh viện hàng đầu. Còn Cam Phong đang làm việc tại bệnh viện tuyến hai. Và rồi, một ca đại phẫu thuật buộc họ phải giáp mặt cùng thực hiện.

Tâm huyết xây dựng một trung tâm Nhi khoa, Tùng Hân đã nghĩ cách để Cam Phong gia nhập đội ngũ bác sĩ ưu tú của mình. Ngoài ra, anh còn tìm đến bác sĩ chuyên khoa Lồng ngực Chương Dĩ Tâm (do Chung Gia Hân đóng) và trưởng khoa Ngoại Nhi Mạch Hải Kỳ (do Châu Gia Di đóng).</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 19, 2021, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Kenneth Ma Kwok-Ming","avatar":""},{"name":"Kevin Cheng Ka-Wing","avatar":""},{"name":"Linda Chung Ka-Yan","avatar":""},{"name":"Catherine Chau","avatar":""},{"name":"Lo Chung-Him","avatar":""},{"name":"Bowie Cheung","avatar":""},{"name":"Gabriel Harrison","avatar":""},{"name":"Florence Kwok Siu-Wan","avatar":""},{"name":"Regina Ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["As Vidas das Crianças Importam","星空下的仁医","星空下的仁医 2021","Er Ke Yi Sheng","兒科醫生","Kids'' Lives Matter","星空下的仁醫","Детские жизни важнее всего"]', 1784690324314);
