INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luong-y-giua-bau-troi-sao-bac-si-nhi-khoa', 'Lương Y Giữa Bầu Trời Sao (Bác Sĩ Nhi Khoa)', 'Kids'' Lives Matter', 'lương y giữa bầu trời sao (bác sĩ nhi khoa) kids'' lives matter kenneth ma kwok-ming kevin cheng ka-wing linda chung ka-yan catherine chau lo chung-him bowie cheung gabriel harrison florence kwok siu-wan regina ho as vidas das crianças importam 星空下的仁医 星空下的仁医 2021 er ke yi sheng 兒科醫生 kids'' lives matter 星空下的仁醫 детские жизни важнее всего', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-nhi-long-ho', 'Chuyện Tình Nhị Long Hồ', 'Er Long Hu Love Story', 'https://phimimg.com/upload/vod/20251128-1/58013695e4e85d90496001914f404289.jpg', 'https://phimimg.com/upload/vod/20251128-1/2ff39f7437eeab98a4eac2f8dd3558af.jpg', '<p>Sau nhiều năm yêu nhau, Trương Lập Đông và Vương Xuân Hoa cuối cùng cũng quyết định tiến tới hôn nhân. Thế nhưng, bất ngờ thay, Vương Trung Đức—cha của Vương Xuân Hoa, người đã mất liên lạc nhiều năm vì đi biển—lại đột nhiên trở về. Kẻ theo đuổi Vương Xuân Hoa là Lý Thiết Cương nhân cơ hội này thể hiện mình, chuẩn bị tranh giành vị trí con rể với Trương Lập Đông. Cùng lúc đó, làng quê cũng không yên bình: Liên minh nuôi gà bị ế trứng, thương hiệu rượu Hạo Cửu bị phát hiện có rượu giả lưu hành trên thị trường. Đối mặt với áp lực kép từ gia đình và sự nghiệp, Trương Lập Đông sẽ làm thế nào để giành được sự công nhận của bố vợ? Cô gái bí ẩn Mạt Lị mà Lý Thiết Cương đưa về lại gây ra những câu chuyện gì? Và sự kiện rượu giả đã khuấy động những sóng gió nào?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Tử Hân","avatar":""},{"name":"Lý Dã","avatar":""},{"name":"Tạ Tân Long","avatar":""},{"name":"Trương Hạo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["二龙湖爱情故事","Er Longhu Love Story"]', 1784690324314);
