INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-nao-nhiet-ban-dien-anh', 'Ngôi Nhà Náo Nhiệt (Bản Điện Ảnh)', 'The Loud House Movie', 'https://phimimg.com/upload/vod/20251126-1/ab9ae42440bc4d22a2af9780661b9026.jpg', 'https://phimimg.com/upload/vod/20251126-1/5d70337995fabdb6b16a4dd9b16fb845.jpg', '<p>Mọi thứ thật hỗn loạn tại nhà Loud khi cậu con trai thứ Lincoln xoay xở với cuộc sống cùng mười chị em gái – năm chị lớn, năm em nhỏ, và tất cả họ đều rắc rối.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2021, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Asher Bishop","avatar":""},{"name":"David Tennant","avatar":""},{"name":"Michelle Gomez","avatar":""},{"name":"Jill Talley","avatar":""},{"name":"Brian Stepanek","avatar":""},{"name":"Catherine Taber","avatar":""},{"name":"Liliana Mumy","avatar":""},{"name":"Nika Futterman","avatar":""},{"name":"Cristina Pucelli","avatar":""},{"name":"Jessica DiCicco","avatar":""},{"name":"Grey DeLisle-Griffin","avatar":""},{"name":"Lara Jill Miller","avatar":""},{"name":"Katy Townsend","avatar":""},{"name":"Andre Robinson","avatar":""},{"name":"Carlos PenaVega","avatar":""},{"name":"Izabella Al","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["LOUD HOUSE","劳德之家大电影","Harmidom – Film","The Loud House: La Película","Bienvenue chez les Loud: Le film","Kuća obitelji Glasnić: Film","Hlasiťákovi ve filmu","Højs hus - filmen","Näin meillä - Elokuva","Wi