INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoi-nha-nao-nhiet-ban-dien-anh', 'Ngôi Nhà Náo Nhiệt (Bản Điện Ảnh)', 'The Loud House Movie', 'ngôi nhà náo nhiệt (bản điện ảnh) the loud house movie asher bishop david tennant michelle gomez jill talley brian stepanek catherine taber liliana mumy nika futterman cristina pucelli jessica dicicco grey delisle-griffin lara jill miller katy townsend andre robinson carlos penavega izabella al loud house 劳德之家大电影 harmidom – film the loud house: la película bienvenue chez les loud: le film kuća obitelji glasnić: film hlasiťákovi ve filmu højs hus - filmen näin meillä - elokuva willkommen bei den louds - der film a lármás család - a film a casa dei loud: il film ラウド・ハウス・ムービー huize herrie: de film bulderhuset - filmen loud em casa: o filme casa loud: filmul мой шумный дом: фильм 링컨의 집에서 살아남기: 더 무비 la casa sollorosa una casa de locos: la película lugn i stormen - filmen 勞德之家：電影版 gürültü ailesi - film гучний дім: фільм فيلم منزل لاود ngôi nhà náo nhiệt - bản điện ảnh the loud house movie', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-sung-than-sau-2021', 'Tay Súng Thần Sầu', 'The Magical Shooters (The Sniper)', 'https://phimimg.com/upload/vod/20251126-1/9f9775d6dc65d28090b966e7d1696d1d.jpg', 'https://phimimg.com/upload/vod/20251126-1/c2881d5ded4b442f336a0ce397a502e8.jpg', '<p>“Bàn Tay Quỷ” – kẻ bắn tỉa huyền thoại của Giang Thành bị Hi Hoà Đường truy lùng với danh nghĩa là kẻ phản bội. Lục Lan trong lúc bị Lãnh Phong nữ sát thủ số một của Hi Hoà Đường bắt cóc, biết được anh trai Thẩm Liệt của mình bị “Bàn Tay Quỷ” giết chết, đã sinh lòng thù hận. Hi Hoà Đường đã huấn luyện Lục Lan trở thành sát thủ, Lục Lan cùng Lãnh Phong đã tiêu diệt các thế lực ngầm chuyên bán vũ khí đạn dược, ám sát Mã Văn Xương. “Bàn Tay Quỷ” đã nhiều lần xuất hiện để cản trở nhiệm vụ của hai người, Lục Lan quyết định giết “Bàn Tay Quỷ” để trả thù cho anh trai. Trong cuộc đấu súng sinh tử, Lục Lan phát hiện ra thân phận thật sự của “Bàn Tay Quỷ”, chính là anh trai của mình. Hoá ra, tất cả đều là âm mưu của Hi Hoà Đường…</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thức Diễn Năng","avatar":""},{"name":"Vương Văn Kiệt","avatar":""},{"name":"Lý Mộng Mộng","avatar":""},{"name":"Hoàng Mãng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["the Magical Shooters","귀수신창","Gui Shou Shen Qiang","鬼手神槍","鬼手神枪"]', 1784690324314);
