INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-dich-ran-2021', 'Đại Dịch Rắn', 'The Great Dragon Plague (Special Police And Snake Revenge)', 'https://phimimg.com/upload/vod/20251126-1/3ce19c6378e5087f6303f79615c441f9.jpg', 'https://phimimg.com/upload/vod/20251126-1/cccfc7c8de4df2be4d1fb24a2c0a27d8.jpg', '<p>Câu chuyện kể về thời kì thịnh vượng của nhà Đường, dị tượng yêu long giáng thế xuống Khúc Giang Trì, bá tánh thành Trường An trọc đầu sau một đêm, hoàng đế giận dữ. Vương Huyền, huyện lệnh Hoàng Hà đã bí mật điều tra vụ án, một âm mưu bí mật tàn sát hàng loạt người dân trong thành, đe doạ sự an nguy của hoàng đế. Vương Huyền thâm nhập sâu vào Long Vương giáo, dùng trí tuệ giải đáp câu đố về cá chép vàng, đúng lúc biết được kế hoạch thảm sát. Cuối cùng tra ra được chân tướng, thành công cứu được hoàng đế, bảo vệ bá tánh thành Trường An.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Đông Học","avatar":""},{"name":"Cao Vi Mạn","avatar":""},{"name":"Chu Tiểu Xuyên","avatar":""},{"name":"Tôn Mộng Hàn","avatar":""},{"name":"Đoạn Vĩ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Special Police and Snake Revenge","불량수 : 대사재","不良帅之大蛇灾"]', 1784690324314);
