INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-va-bac-cha-chu', 'Tôi Và Bậc Cha Chú', 'My Country, My Parents', 'https://phimimg.com/upload/vod/20251122-1/552f45ccaf514f7d1c71a1fcb1070248.jpg', 'https://phimimg.com/upload/vod/20251122-1/0f2a5fb1c7ee28498fcb8ed0183b860d.jpg', '<p>Bộ phim được tạo thành từ bốn câu chuyện đơn vị: 《Cưỡi Gió》, 《Thơ》, 《Vịt Tiên Tri》 và 《Thiếu Niên Hành》.&nbsp; Lấy cách mạng, kiến thiết, cải cách mở cửa và kỷ nguyên mới làm tọa độ lịch sử, bộ phim thông qua góc nhìn &quot;Gia đình và Đất nước&quot; để miêu tả quá trình phấn đấu của các thế hệ cha ông. Từ đó, bộ phim kể về mối liên kết máu mủ và sự kế thừa tinh thần của người Trung Quốc, tái hiện lại những ký ức về nỗ lực và sự đấu tranh trong các thời đại của họ.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Kinh","avatar":""},{"name":"Chương Tử Di","avatar":""},{"name":"Từ Trịnh","avatar":""},{"name":"Thẩm Đăng","avatar":""},{"name":"Ngô Lỗi","avatar":""},{"name":"Tống Giai","avatar":""},{"name":"Trương Dực Kỳ","avatar":""},{"name":"Hoàng Huyên","avatar":""},{"name":"Bành Dục Sảng","avatar":""},{"name":"Lý Nại Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["My Country, My Parents","Wo he wo de fu bei","My Country My Parents","ちちにささぐものがたり","我和我的父辈"]', 1784690324314);
