INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-va-bac-cha-chu', 'Tôi Và Bậc Cha Chú', 'My Country, My Parents', 'tôi và bậc cha chú my country, my parents ngô kinh chương tử di từ trịnh thẩm đăng ngô lỗi tống giai trương dực kỳ hoàng huyên bành dục sảng lý nại văn my country, my parents wo he wo de fu bei my country my parents ちちにささぐものがたり 我和我的父辈', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-xe-an-danh-phan-1', 'Tài Xế Ẩn Danh (Phần 1)', 'Taxi Driver (Season 1)', 'https://phimimg.com/upload/vod/20251122-1/36150d1e47bc1c4beeaa617cad7126c0.jpg', 'https://phimimg.com/upload/vod/20251122-1/e9fdf1b0b5ac1037bfc13755527d7a55.jpg', '<p>Bộ phim diễn ra xung quanh một công ty taxi bí mật có tên Rainbow Taxi chuyên trả thù những nạn nhân của tội ác không được pháp luật bảo vệ. Lee Je Hoon vào vai một cựu sĩ quan đặc nhiệm, hiện là tài xế taxi Kim Do Ki, người có trực giác bẩm sinh nhưng cũng có óc phán đoán lạnh lùng và tính cách táo bạo. Esom vào vai công tố viên Kang Ha Na thông minh và tinh ranh. Kim Eui Sung vào vai Jang Sung Chul, người sáng lập ra Rainbow Taxi . Và Lee Na Eun vào vai chuyên gia IT Go Eun, người đang làm việc cho Rainbow Taxi và tìm ra thông tin cá nhân để giúp giải quyết các vụ việc.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 18, 2021, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Je-hoon","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Pyo Ye-jin","avatar":""},{"name":"Jang Hyuk-jin","avatar":""},{"name":"Bae Yu-ram","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Taksi Sürücüsü","模范计程车","模范的士","模范出租车","ViuTV Mobeomtaeksi","模範的士","راننده تاکسی","復讐代行人～模範タクシー～","Mobeomtaxi","Premium Taxi","모범택시 3","Хар такси","Такси мстителей","Такси Делюкс","Model Taxi","Red Cage","Exemplary Taxi","D