INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('11-thang-5-ngay', '11 Tháng 5 ngày', '11 Months And 5 Days', 'https://phimimg.com/upload/vod/20251117-1/f78bbebf31fc0eb5a6ee3ea3f858a8c5.jpg', 'https://phimimg.com/upload/vod/20251117-1/b15aabd3c77b8b4926057a29ad9e81b8.jpg', '<p>Tuệ Nhi, vốn là tiểu thư nhà giàu, quyết tâm từ bỏ đất Sài thành ra Bắc lập nghiệp. Trong suốt hành trình đi tìm lí tưởng sống mới, Tuệ Nhi gặp muôn vàn khó khăn, rắc rối.</p>', 'Hoàn Tất (46/46)', 46, 'series', 'completed', 21, 2021, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Khả Ngân","avatar":""},{"name":"Thanh Sơn","avatar":""},{"name":"Hà Trung","avatar":""},{"name":"Lương Thanh","avatar":""},{"name":"Ngọc Lan","avatar":""},{"name":"Mạnh Cường","avatar":""},{"name":"Vân Dung","avatar":""},{"name":"Quang Thắng","avatar":""},{"name":"Anh Thơ","avatar":""},{"name":"Minh Hương","avatar":""},{"name":"Tuấn Tú","avatar":""},{"name":"Ngọc Tản","avatar":""},{"name":"Quốc Trị","avatar":""},{"name":"Phú Thăng","avatar":""},{"name":"Phạm Tiến Lộc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Điều em chưa biết","11 tháng 5 ngày"]', 1784690324314);
