INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('11-thang-5-ngay', '11 Tháng 5 ngày', '11 Months And 5 Days', '11 tháng 5 ngày 11 months and 5 days khả ngân thanh sơn hà trung lương thanh ngọc lan mạnh cường vân dung quang thắng anh thơ minh hương tuấn tú ngọc tản quốc trị phú thăng phạm tiến lộc điều em chưa biết 11 tháng 5 ngày', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-yeu-dau-cua-chung-ta-nhung-ngay-he-ruc-nang-cua-chung-minh', 'Mùa Hè Yêu Dấu Của Chúng Ta (Những Ngày Hè Rực Nắng Của Chúng Mình)', 'Our Beloved Summer', 'https://phimimg.com/upload/vod/20250326-1/8a7cbfbccb8cd563ca79831cb0e7e042.jpg', 'https://phimimg.com/upload/vod/20250326-1/85adfabf64eb3a7c14c998f954fbf9b7.jpg', '<p>Nhiều năm sau khi quay một bộ phim tài liệu đình đám ở trường cấp ba, hai người yêu cũ hay cãi vã nay bị kéo đến trước ống kính cùng nhau — và lại vướng vào nhau.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 26, 2021, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Woo-shik","avatar":""},{"name":"Kim Da-mi","avatar":""},{"name":"Kim Sung-cheol","avatar":""},{"name":"Roh Jeong-eui","avatar":""},{"name":"Ahn Dong-gu","avatar":""},{"name":"Jeon Hye-won","avatar":""},{"name":"Park Jin-joo","avatar":""},{"name":"Lee Jun-hyuk","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ένα Μοναδικό Καλοκαίρι","そのとし、わたしたちは","那年，我们的夏天","ร้อนนั้นเรารักกัน","那年，我們的夏天","Us That Year","That Year We","Our Beloved Summer","그 해 우리는"]', 1784690324314);
