INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-trong-toa-nha-phan-5', 'Sát Nhân Trong Tòa Nhà (Phần 5)', 'Only Murders in the Building (Season 5)', 'https://phimimg.com/upload/vod/20250920-1/68152d7da08b7c798baf1b0899b52926.jpg', 'https://phimimg.com/upload/vod/20250920-1/88aabd7c9063326a7c7a10ef55d894b4.jpg', '<p>Ba người xa lạ có chung nỗi ám ảnh về tội ác thực sự đột nhiên thấy mình bị cuốn vào một. Những người hàng xóm của nhóm Upper West Side Charles, Oliver và Mabel gắn bó với nhau vì tình yêu chung của tội phạm thực sự. Khi một người dân chết trong tòa nhà của họ, bộ ba quyết định giải quyết bí ẩn và ghi lại một podcast đi kèm.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 10, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Steve Martin","avatar":""},{"name":"Martin Short","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Michael Cyril Creighton","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Homicídios Ao Domicílio","Só os Assassinos no Edifício","Só os Assassinos do Edifício","大楼里只有谋杀","公寓大楼里的谋杀案","רק רציחות בבניין","فقط قتل‌های داخل ساختمان","Убийства в пределах здания","Тільки вбивства у будівлі","omitb","Only Murders in the Building"]', 1784690324314);
