INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-lai-hoa-tieu-thu', 'Đứng Lại, Hoa Tiểu Thư', 'Stop! Miss Hua', 'https://phimimg.com/upload/vod/20251107-1/87c394456530bac725516c07efce4b94.jpg', 'https://phimimg.com/upload/vod/20251107-1/051dd0fd29b9653d88a5e16a8ce70dea.jpg', '<p>Là cháu gái cưng của ông chủ tập đoàn Hoa Thị, nhưng khi ông nội mắc bệnh nặng, Hoa Minh Nguyệt bị anh trai đuổi ra khỏi tập đoàn. Tần Đông Hải sau khi du học trở về đã gia nhập Hoa Thị và bất ngờ trở thành cố vấn của Minh Nguyệt. Từ oan gia trở thành cộng sự, họ dần dần nảy sinh tình cảm với nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tích Yến Địch","avatar":""},{"name":"Trương Hác","avatar":""},{"name":"Cao Cơ Tài","avatar":""},{"name":"Tô Mộng Địch","avatar":""},{"name":"Lưu Ấn Quân","avatar":""},{"name":"Ngô Minh Tinh","avatar":""},{"name":"Trương Tầng Tầng","avatar":""},{"name":"Ngô Thiên Hạo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324314);
