INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dung-lai-hoa-tieu-thu', 'Đứng Lại, Hoa Tiểu Thư', 'Stop! Miss Hua', 'đứng lại, hoa tiểu thư stop! miss hua tích yến địch trương hác cao cơ tài tô mộng địch lưu ấn quân ngô minh tinh trương tầng tầng ngô thiên hạo ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-dang', 'Tư Đằng', 'Rattan', 'https://phimimg.com/upload/vod/20251107-1/f3d44d6b2a41575ff48f2f4266d2481b.jpg', 'https://phimimg.com/upload/vod/20251107-1/03189c8d54f51948af292ac239d754e1.jpg', '<p>Phim được chuyển thể từ tiểu thuyết cùng tên của Vĩ Ngư. Nhân vật chính của truyện là Tư Đằng – một yêu nữ có nguyên thần là cây mây. Cô bị chúng lão đạo sĩ giết chết vào thời Dân Quốc tại Thượng Hải. Bối cảnh vào năm 1946, thiên sư đạo trưởng Khưu Sơn trấn giết được nữ yêu Tư Đằng, trước khi chết Tư Đằng nở một nụ cười quái dị tựa như trút được gánh nặng. Đến năm 2013, thiếu niên Tần Phóng dẫn theo vị hôn thê đi tìm vị ân nhân của tổ tiên, xe hỏng rơi xuống vực, cọc nhọn dưới vực đâm thẳng vào tim, máu tim từng giọt nhỏ vào yêu nữ Tư Đằng được chôn phía dưới.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 14, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cảnh Điềm","avatar":""},{"name":"Trương Bân Bân","avatar":""},{"name":"Trương Diệu","avatar":""},{"name":"Lý Mẫn","avatar":""},{"name":"Trương Y Nhân","avatar":""},{"name":"Ngụy Chiêu Hiền","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["半妖司藤","司藤","RATTAN","Rattan"]', 1784690324314);
