INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-tinh-nhat-duoc-tong-tai', 'Vô Tình Nhặt Được Tổng Tài', 'Please Feel At Ease Mr. Ling', 'https://phimimg.com/upload/vod/20251106-1/79d0a273117961d61570baaa37eac9c8.jpg', 'https://phimimg.com/upload/vod/20251106-1/9cdc5ec30631e22445c9f60cd3914531.jpg', '<p>Bộ phim kể về cô nàng shipper Cố An Tâm (Triệu Lộ Tư đóng) bất cẩn đụng phải người thừa kế tập đoàn lớn Lăng Việt (Lưu Đặc đóng). Lăng Việt bắt An Tâm phải chịu trách nhiệm nên An Tâm đành đưa anh về nhà chăm sóc. Hai con người với hai môi trường sống khác nhau khi về chung một nhà tạo ra những tình huống dở khóc dở cười nhưng không kém phần ngọt ngào.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2021, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lộ Tư","avatar":""},{"name":"Lưu Đặc","avatar":""},{"name":"Lưu Dương","avatar":""},{"name":"Chu Tuấn Vỹ","avatar":""},{"name":"Triệu Lâm Đông","avatar":""},{"name":"Quách Thư Dao","avatar":""},{"name":"Mã Trạch Hàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["I Accidentally Found Love","Yi Bu Xiao Xin Jian Dao Ai","You succeeded in attracting my attention","I Accidentally Picked Up Love","Accidentally Picked Up by Love","YBXXJDA","일부소심렴도애","Пожалуйста, не волнуйтесь, господин Лин","一不小心捡到爱"]', 1784690324314);
