INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-xep-hang-quoc-vuong-ousama-ranking', 'Bảng Xếp Hạng Quốc Vương (Ousama Ranking)', 'Ranking Of Kings', 'https://phimimg.com/upload/vod/20251105-1/3a043b38f5b45f1f753a4d29f3f5d0cc.jpg', 'https://phimimg.com/upload/vod/20251105-1/dc54cb2fda69da4b73963544b28ec47a.jpg', '<p>Không thể nghe, không thể nói, cũng không thể dùng kiếm, Hoàng tử Bojji dường như không phải là một người kế vị ngai vàng điển hình—và vương quốc của anh cũng đồng tình với điều đó.&nbsp; Nhưng cuộc gặp gỡ định mệnh của anh với Kage (một bóng đen trên mặt đất) đã mang đến cho anh người bạn thân đầu tiên. Cả hai cùng nhau bắt đầu một cuộc phiêu lưu vĩ đại và xây dựng một mối liên kết có thể vượt qua mọi trở ngại... ngay cả thử thách trở thành Vua.</p>', 'Hoàn Tất (23/23)', 23, 'hoathinh', 'completed', 10, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Hinata","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Takuya Eguchi","avatar":""},{"name":"Yoji Ueda","avatar":""},{"name":"Daiki Yamashita","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ōsama Ranking","Ousama Ranking","تقييم الملوك","Ranking of Kings","王様ランキング"]', 1784690324315);
