INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-ngay-nang-ve', 'Thương Ngày Nắng Về', 'Loving The Sunny Days', 'https://phimimg.com/upload/vod/20251104-1/c5d963abb2999965703ec7583eebdaea.jpg', 'https://phimimg.com/upload/vod/20251104-1/a35d1267c2feceebcdaedd062beb8c15.jpg', '<p>Bộ phim "Thương Ngày Nắng Về" là câu chuyện về Bà Nga, một người mẹ bán bún riêu, một mình gồng gánh nuôi ba cô con gái trưởng thành.Nội dung xoay quanh những khó khăn, thử thách và mâu thuẫn trong cuộc sống, tình yêu và hôn nhân của ba cô con gái (Khánh, Trang, Vân). Dù phải trải qua nhiều sóng gió, ly tán và bi kịch (mâu thuẫn mẹ chồng, ân oán quá khứ, bệnh tật), nhưng cuối cùng, tình yêu thương vô bờ bến và sự hy sinh của Bà Nga đã trở thành sức mạnh và là điểm tựa để cả gia đình vượt qua tất cả, tìm lại niềm vui và ý nghĩa cuộc sống.</p>', 'Hoàn Tất (88/88)', 88, 'series', 'completed', 17, 2021, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"NSƯT Thanh Quý","avatar":""},{"name":"NSND Minh Hòa","avatar":""},{"name":"NSƯT Trung Anh","avatar":""},{"name":"NSND Lan Hương","avatar":""},{"name":"NSƯT Bá Anh","avatar":""},{"name":"Lan Phương","avatar":""},{"name":"Huyền Lizzie","avatar":""},{"name":"Hồng Đăng","avatar":""},{"name":"Đình Tú","avatar":""},{"name":"Doãn Quốc Đam","avatar":""},{"name":"Ngọc Huyền","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324315);
