INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vivy-bai-hat-cua-mat-fluorite', 'Vivy: Bài Hát Của Mắt Fluorite', 'Vivy: Fluorite Eye''s Song', 'https://phimimg.com/upload/vod/20251104-1/6e0518698681d768125fd94b60635f5a.jpg', 'https://phimimg.com/upload/vod/20251104-1/950270128821ca4350885c7819d1756b.jpg', '<p>Niearland – Một công viên giải trí với chủ đề về A.I nơi mà giấc mơ, hy vọng và khoa học hoà lẫn vào nhau. Được tạo ra với tư cách là A.I hình người tự vận hành đầu tiên, Vivy là A.I đang biểu diễn tại đây. Để hoàn thành sứ mệnh đem đến hạnh phúc cho mọi người qua những bản ca, cô luôn bước lên sân khấu và biểu diễn hết mình. Tuy nhiên, công viên vẫn không được nổi tiếng.

Một ngày nọ, một A.I tên là Matsumoto xuất hiện trước mắt Vivy và giải thích rằng anh ta đến từ tương lai 100 năm sau Với sứ mệnh sửa lại lịch sử cùng với Vivy và ngăn chặn cuộc chiến giữa loài người và A.I sẽ xảy ra trong 100 năm sau.

Tương lai nào đang chờ đợi hai A.I bọn họ khi mà cả hai mang trên mình những sứ mệnh khác nhau. Đây là câu chuyện về A.I tiêu diệt A.I, cuộc hành trình dài trăm năm của nàng A.I Viyy, bắt đầu…</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Atsumi Tanezaki","avatar":""},{"name":"Jun Fukuyama","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["萤石眼之歌","Vivy Fluorite Eye’s Song","薇薇","薇薇 -萤石眼之歌-","Vivy -萤石眼之歌-","ヴィヴィ -フローライトアイズソング-","Vivy ーFluorite Eye’s Songー","비비 -형석안의 노래-","플로라이트 아이즈 송","형석안의 노래","비비","비비: 플로라이트 아이즈 송","비비-불화석 눈의 노래","퍄표","วีวี่ บทเพลงจักรกลกู้ศตวรรษ","Пісня флюоритового ока","Віві","Vivy: Fluorite Eye''s Song","Vivy","Fluorite Eye''s Song","Vivy -Fluorite Eye''s Song-"]', 1784690324315);
