INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vung-dat-cam-lang-phan-ii', 'Vùng Đất Câm Lặng: Phần II', 'A Quiet Place: Part II', 'vùng đất câm lặng: phần ii a quiet place: part ii emily blunt john krasinski millicent simmonds noah jupe cillian murphy djimon hounsou okieriete onaodowan scoot mcnairy zachary golinger blake delong stefania warwick alycia ripley cristalis bonilla domonic taggart silas pereira-olson alice тихе місце: частина ii (special) a quiet place part ii silent experience un lugar tranquilo 2 無聲絕境2 噤界ii un lugar en silencio: parte ii sans un bruit 2 тихое место 2 sessiz bir yer 2 寂静之地2 sessiz bir yer a quiet place ii - un posto tranquillo parte 2 a quiet place 2 kena vaikne kohake 2 ดินแดนไร้เสียง 2 un coin tranquille : 2e partie a quiet place part 2 нито звук 2 クワイエット・プレイス 破られた沈黙：2021 vùng đất câm lặng 2 səssiz bir yer 2 a quiet place part ii', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-anh-mat-troi-2021', 'Dưới Ánh Mặt Trời', 'Modern City', 'https://phimimg.com/upload/vod/20251026-1/8186fe9dfdabb728a4eb86d1e71992ba.jpg', 'https://phimimg.com/upload/vod/20251026-1/ce93896d2ff21d286b36679ca270a825.jpg', '<p>Xem trọng việc phát triển sự nghiệp, Tống Tư Ngưng và chồng thường xuyên mâu thuẫn về vấn đề sinh con thứ hai. Sự xuất hiện của cậu em trai Duy Nhất và vợ là Khả Doanh lại càng khiến Tư Ngưng phải đối mặt với nhiều căng thẳng hơn. Trong khi đó, sếp của cô là Trần Tụng Anh lại bắt đầu thay đổi suy nghĩ về thỏa thuận hôn nhân không con cái giữa cô và chồng bấy lâu nay. Thông qua câu chuyện của ba người phụ nữ ở ba giai đoạn khác nhau của cuộc đời, phim khắc họa chân thực và sinh động đời sống tình yêu, hôn nhân, sự nghiệp và việc nuôi dạy con cái trong thời đại hiện nay.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 9, 2021, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Lộ","avatar":""},{"name":"Tưởng Nghĩa","avatar":""},{"name":"Trần Tử Hàm","avatar":""},{"name":"Quách Hiểu Đông","avatar":""},{"name":"Lãnh Kỷ Nguyên","avatar":""},{"name":"Lưu Đình Vũ","avatar":""},{"name":"Lưu Ân Hựu","avatar":""},{"name":"Tiền Cẩn","avatar":""},{"name":"Phương Thanh Trác","avatar":""},{"name":"Văn Bộ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["梦想城","Modern City","现代城","暖阳之下"]', 1784690324315);
