INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('arcane-lien-minh-huyen-thoai-phan-1', 'Arcane: Liên Minh Huyền Thoại (Phần 1)', 'Arcane (Season 1)', 'https://phimimg.com/upload/vod/20241001-1/dae7d80cd9a77bc2a6edc5b8d0104292.jpg', 'https://phimimg.com/upload/vod/20241001-1/b17489996dc095e8a90eb2ca5f06d797.jpg', '<p>Khi hai thành phố song sinh Piltover và Zaun ở thế mâu thuẫn gay gắt, hai chị em chiến đấu ở hai bên chiến tuyến cùng các công nghệ ma thuật và những niềm tin trái chiều.</p>', 'Hoàn Tất (9/9)', 9, 'hoathinh', 'completed', 11, 2021, 'Vietsub + Lồng Tiếng', 'FHD', 'Pháp', 0, '[{"name":"Hailee Steinfeld","avatar":""},{"name":"Ella Purnell","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["英雄联盟：双城之战","არკეინი","آرکین : لیگ افسانه ها","Аркейн: League of Legends","Arcane: League of Legends","Arcane Afterglow","Arcane"]', 1784690324315);
