INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('arcane-lien-minh-huyen-thoai-phan-1', 'Arcane: Liên Minh Huyền Thoại (Phần 1)', 'Arcane (Season 1)', 'arcane: liên minh huyền thoại (phần 1) arcane (season 1) hailee steinfeld ella purnell 英雄联盟：双城之战 არკეინი آرکین : لیگ افسانه ها аркейн: league of legends arcane: league of legends arcane afterglow arcane', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-long-tu-tien-truyen-2-vuong-quoc-ma-thu', 'Ngự Long Tu Tiên Truyện 2: Vương Quốc Ma Thú', 'Dragon Sword: Outlander', 'https://phimimg.com/upload/vod/20251020-1/d7ba6a138a29e0233c851434012e8ef0.jpg', 'https://phimimg.com/upload/vod/20251020-1/3da934f2e7b5fa67b2a9c05ef0a1146a.jpg', '<p>Phó Viêm một người tu tiên với thể chất bình thường vô tình lọt vào vết nứt không gian, đến với một nơi có tên là Thú Nhân Vực. Phó Viêm trong lúc tìm kiếm lối ra đã giết chết vô số yêu thú, đến khi sức cùng lực kiệt mới phát hiện tu vi của mình đã bị giáng xuống Kết đan trung kỳ. Lúc này, xuất hiện một Quỷ tu ẩn mình trong băng ngọc mà Phó Viêm đeo trên người, giúp anh ta tìm được đường ra, đồng thời truyền dạy phương pháp luyện đan. Sau khi thoát ra khỏi đó, Phó Viêm đến thành Thọ Hoa và đã gặp gỡ với Lam Mặc Y, thánh nữ của Phiêu Diểu Cung, hai người trở nên quen thuộc và cùng đồng hành với nhau. Tuy nhiên, trên đường đi gặp phải vô vàn khó khăn, còn có sự xuất hiện của của Nữ hoàng Bọ Cạp…</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"ành Vũ Tư","avatar":""},{"name":"Lôi Mông","avatar":""},{"name":"Đỗ Phùng Vũ Dung","avatar":""},{"name":"Hứa Nguyệt Nguyệt","avatar":""},{"name":"Trần Lập Ly","avatar":""},{"name":"Biên Minh Vũ","avatar":""},{"name":"Triệu Gia Nghệ","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["御龙修仙传2：魔兽疆界"]', 1784690324315);
