INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-mon-tieu-yen', 'Hổ Môn Tiêu Yên', 'Destruction Of Opium At Humen', 'https://phimimg.com/upload/vod/20251020-1/63cf6a53fc71fcbdbdd8ad23036cb0b0.jpg', 'https://phimimg.com/upload/vod/20251020-1/b234d2e611f0a4ee98fe5174b7476bb7.jpg', '<p>Cuối thời nhà Thanh, thuốc phiện tràn lan, nhiều người Trung Quốc bị thuốc phiện tàn hại. Lâm Tắc Từ được lệnh đến Quảng Châu cấm thuốc phiện. Nhưng quan lại địa phương cấu kết với thổ phỉ, hành động cấm thuốc phiện rơi vào tình thế bế tắc. Nhằm tiêu diệt “Thập Tam Hàng”, nhà buôn ma túy lớn nhất tại Quảng Châu, một đám người thanh niên anh dũng đứng ra, trợ giúp Lâm Tắc Từ đánh bại lái buôn thuốc phiện và gian thương, cùng giành được thắng lợi lớn lao!</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiết Miêu","avatar":""},{"name":"Diệu Lộ","avatar":""},{"name":"Đỗ Ngọc Minh","avatar":""},{"name":"Trương Tử Sâm","avatar":""},{"name":"Khúc Ỷ Thành","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["虎门销烟","Xue Zhan Hu Men","血战虎门"]', 1784690324315);
