INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-than-co', 'Đấu Thần Cơ', 'Ancient Girl''s Frame', 'https://phimimg.com/upload/vod/20251016-1/2dbe489c2f566646e919373d0768e25e.jpg', 'https://phimimg.com/upload/vod/20251016-1/4634a4378cbdf7e503042a8db381b904.jpg', '<p>Trong quá khứ xa xôi, những người ngoài hành tinh sống sót bị Nergal xâm lược và đày xuống trái đất do khai thác nguồn năng lượng vô hạn đã tạo ra di tích và nền văn minh của các vị thần cho trái đất và tiếp tục cho đến ngày nay. Khi trái đất phải đối mặt với cuộc khủng hoảng tương tự, người máy khổng lồ bị phong ấn trong di tích đã thức tỉnh, để tìm kiếm người chị bị mất tích trong cuộc tấn công của Nergal, Lý Tinh Lan đã tình nguyện tham gia vào đơn vị AG ở đầu chiến tuyến.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Shan Xin","avatar":""},{"name":"Shuang Zhao","avatar":""},{"name":"Meme Yan","avatar":""},{"name":"Ye Zhiqiu","avatar":""},{"name":"Yang Ning","avatar":""},{"name":"Yeqiao Yan","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Dou Shen Ji","斗神姬","Dǒu Shén Jī","Tōshinki G''s Flame","Toushinki G''s Flame","闘神機ジーズフレーム","Tōshinki Jīzu Furēmu","Toushinki G''s Frame","Ancient G''s Frame","Divine Fighting Machine G''s Flame","Ancient Girl''s-Frame"]', 1784690324315);
