INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chin-chin-tam-mot', 'Chín Chín Tám Mốt', '9981 The Oriental Odyssey', 'https://phimimg.com/upload/vod/20251012-1/b917a3ed64b3839ec24be89210a6657b.jpg', 'https://phimimg.com/upload/vod/20251012-1/7e826aca335b7269944bfe9c07a8c8d1.jpg', '<p>Khi Ẩn Thụ – cây thần bảo hộ cho trời đất và ba tộc – bắt đầu tàn úa, Bích Hàm, người mang thiên mệnh và sứ mạng được trao, đã lên đường bước vào hành trình dài vô tận. Để tìm kiếm Hồng Mông và mang lại bình yên cho thế gian, nàng phải vượt qua muôn vàn thử thách, chông gai và hiểm nguy giăng khắp lối. Trên đường đi, có người thân thương gắn bó sâu nặng, cũng có kẻ độc ác, hiểm nguy khôn lường; nhưng nhờ có bằng hữu kề vai sát cánh, dù gian nan vạn dặm, nàng vẫn vừa đi vừa hát, không ngừng tiến bước.</p>', 'Hoàn Tất (2/2)', 2, 'hoathinh', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jiu Jiu Ba Shi Yi","九九八十一"]', 1784690324315);
