INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-tinh-khong-loi', 'Mối Tình Không Lời', 'A Love of No Words', 'https://phimimg.com/upload/vod/20251010-1/517abf541a8ca3b84002a470ce7a144c.jpg', 'https://phimimg.com/upload/vod/20251010-1/913d9c536a9479b0206f7a4972657c3f.jpg', '<p>Sau 20 năm, phiên bản mới của bộ phim “Đường về hạnh phúc” từng gây tiếng vang nay tái hiện với diễn xuất tươi mới của dàn diễn viên trẻ. “Mối tình không lời” mang đến bức tranh đầy màu sắc về tình cảm gia đình xen lẫn những câu chuyện tình yêu với nhiều cung bậc cảm xúc.

Vào thập niên 80, nữ ca sĩ Chu Sa Kiều (do Mễ Tuyết đóng) một mình nuôi dưỡng hai con gái sinh đôi. Sau khi trưởng thành, tình cảm của hai cô con gái bị rạn nứt bởi tình yêu khiến Sa Hoa (do Diêu Gia Ni đóng) rời đi biệt tăm. Sa Sa vì sinh khó mà tử vong. Sa Kiều một mình nuôi dưỡng cháu gái Quân Hảo (do Hà Y Đình đóng), đồng thời cũng nhận nuôi một bé trai bị câm tên Văn Sơ (do Hồ Hồng Quân đóng).</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2021, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Regina Ho","avatar":""},{"name":"Michelle Yim","avatar":""},{"name":"Hubert Wu","avatar":""},{"name":"Claire Yiu","avatar":""},{"name":"Shek Sau","avatar":""},{"name":"Joey Law","avatar":""},{"name":"Gabriel Harrison","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["十月初五的月光","A Love of No Words","Return of the Cuckoo 2021"]', 1784690324315);
