INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-lai-tu-dau', 'Làm Lại Từ Đầu', 'RE-MAIN', 'https://phimimg.com/upload/vod/20251010-1/040c2c1d21c61b3829255b4f8592aee1.jpg', 'https://phimimg.com/upload/vod/20251010-1/a487d1a40356bcce3df09b59cf742060.jpg', '<p>Câu chuyện xoay quanh Minato Kiyoumizu, một cậu bé đã bỏ chơi bóng nước sau một sự cố vào mùa đông năm thứ ba trung học cơ sở. Sau khi vào trung học, anh ấy đã hứa và quyết định thử lại môn bóng nước và tham gia vào đội của trường với bạn bè của mình. Tuy nhiên, đội mới sẽ gặp phải những vấn đề trong quá trình…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuto Uemura","avatar":""},{"name":"Koutaro Nishiyama","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Lynn","avatar":""},{"name":"Soma Saito","avatar":""},{"name":"Makoto Furukawa","avatar":""},{"name":"Tasuku Hatanaka","avatar":""},{"name":"Daisuke Hirose","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["RE-MAIN：少年与水球","少年与水球","Re-Main","Remain","水球少年","リメイン","RE-MAIN"]', 1784690324315);
