INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ban-gai-lai-them-ban-gai-phan-1', 'Có Bạn Gái, Lại Thêm Bạn Gái (Phần 1)', 'Girlfriend, Girlfriend (Season 1)', 'https://phimimg.com/upload/vod/20240922-1/6333c899014e1df826a94c649b63cb21.jpg', 'https://phimimg.com/upload/vod/20251010-1/15287aea8ed566705136483b2b3f08ef.jpg', '<p>Nhân vật chính Naoya là một học sinh cao trung năm nhất. Sau khi tỏ tình với Saki và được cô ấy đồng ý làm bạn gái, cậu đã cảm nhận được hạnh phúc tột cùng.

Nhưng rồi, một cô gái xinh đẹp khác là Nagisa lại bắt chuyện với Naoya. Cô bất ngờ thổ lộ và mong được hẹn hò với Naoya.

Naoya đã xiêu lòng trước bao ưu điểm của Nagisa và đưa ra quyết định...

Một hài kịch tình yêu theo tiêu chuẩn mới đã bất đầu!!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Junya Enoki","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Azumi Waki","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Aoi Koga","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["女友成双","女朋友 女朋友","Ella es la novia también","Kupunya Dia dan Dirinya","Kanojo mo Kanojo","カノかの","Kano Kano","그녀도 여친","女友成堆","女朋友 and 女朋友","カノジョも彼女"]', 1784690324315);
