INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-nhoc-nho', 'Cậu Nhóc Nhỏ', 'Sonny Boy', 'https://phimimg.com/upload/vod/20251008-1/a79de25c7da8cafec690212553a1c244.jpg', 'https://phimimg.com/upload/vod/20251008-1/dd499a9a7241e358927bc841dd5f42eb.jpg', '<p>Tưởng chừng là một ngày hè bình thường, nhưng số phận đã an bài cho 36 học sinh trường trung học Nagara một hành trình không tưởng. Trong chớp mắt, họ bị cuốn vào một chiều không gian khác, nơi quy luật tự nhiên bị đảo lộn và những điều kỳ diệu trở thành hiện thực.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aoi Ichikawa","avatar":""},{"name":"Saori Onishi","avatar":""},{"name":"Aoi Yuuki","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Hiroki Goto","avatar":""},{"name":"Ami Naito","avatar":""},{"name":"Hana Sato","avatar":""},{"name":"Yoji Ueda","avatar":""},{"name":"Shota Yamamoto","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Ai Kakuma","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["サニー​ボーイ","Sonny Boy -サニーボーイ-","소니 보이","서니 보이","Sonny Boy"]', 1784690324315);
