INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-duong-gi-tam-nay', 'Yêu Đương Gì Tầm Này', 'Love Once Again', 'https://phimimg.com/upload/vod/20251008-1/717331623b8a156ffa67f983cc6f4e41.jpg', 'https://phimimg.com/upload/vod/20251008-1/3492b4a647278071a2e3c1d4de50862d.jpg', '<p>&quot;Yêu Đương Gì Tầm Này&quot; kể về cô nàng Lâm Noãn Noãn (Vưu Tĩnh Như thủ vai) trong lần tình cờ đã gặp được anh chàng nhân viên siêu thị Thời Quang (Triệu Nhượng thủ vai). Ngay từ cái nhìn đầu tiên, Lâm Noãn Noãn đã cho rằng Thời Quang rất có tiềm năng để làm một thần tượng. Nên cô nàng đã dùng đủ mọi cách để thuyết phục anh làm Idol. Từ đó, hai người bắt đầu mở ra câu chuyện tình yêu hài hước dí dỏm.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 11, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"You Jingru","avatar":""},{"name":"Ryan Zhao","avatar":""},{"name":"Ariel Ann","avatar":""},{"name":"Hong Yike","avatar":""},{"name":"Xu Xiaohan","avatar":""},{"name":"Liu Xu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["谈什么恋爱","谈什么恋爱啊"]', 1784690324315);
