INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-tuoc-chet-choc-va-co-hau-gai-cua-cau', 'Công Tước Chết Chóc Và Cô Hầu Gái Của Cậu', 'The Duke of Death and His Maid', 'https://phimimg.com/upload/vod/20251008-1/c77bb12886afa7ff1dda4a9b192489b0.jpg', 'https://phimimg.com/upload/vod/20251008-1/1cc09ea925846496e9b2b97e08f253ee.jpg', '<p>Thiếu gia nhà quý tộc hồi nhỏ bị phù thủy thực hiện lời nguyền “chạm vào thứ gì thì thứ đó sẽ chết”, đồng thời vì lời nguyền này mà phải sống một mình trong căn nhà lớn ở sâu trong khu rừng xa xôi. Nhưng với sự xuất hiện của một cô hầu gái đi theo hầu cậu, Alice, cuộc đời của thiếu gia bắt đầu có những sự thay đổi.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Natsuki Hanae","avatar":""},{"name":"Ayumi Mano","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Wakana Kuramochi","avatar":""},{"name":"Hiroshi Kamiya","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Yoko Hikasa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Shinigami Bocchan to Kuro Maid","Смертоносный герцог и его чёрная горничная","เมดสาวแสบร้ายกับคุณชายยมทูต","The Duke of Death and His Maid","死神坊ちゃんと黒メイド"]', 1784690324315);
