INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-tuoc-chet-choc-va-co-hau-gai-cua-cau', 'Công Tước Chết Chóc Và Cô Hầu Gái Của Cậu', 'The Duke of Death and His Maid', 'công tước chết chóc và cô hầu gái của cậu the duke of death and his maid natsuki hanae ayumi mano hochu otsuka inori minase wakana kuramochi hiroshi kamiya yuma uchida yoko hikasa shinigami bocchan to kuro maid смертоносный герцог и его чёрная горничная เมดสาวแสบร้ายกับคุณชายยมทูต the duke of death and his maid 死神坊ちゃんと黒メイド', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-sieu-anh-hung-mua-5', 'Học Viện Siêu Anh Hùng (Mùa 5)', 'My Hero Academia (Season 5)', 'https://phimimg.com/upload/vod/20251005-1/9cfdb2e288582d48c1991133ac86d1c4.jpg', 'https://phimimg.com/upload/vod/20251005-1/a9f09c3df3483fac159dd3fc277528db.jpg', '<p>Chuyển thể từ manga cùng tên của tác giả Horikoshi Kohei. Bối cảnh tương lai, 80% dân số thế giới sở hữu siêu năng lực, anh hùng là một nghề nghiệp phát triển mạnh mẽ. Đây là câu chuyện về Midoriya Izuku (Deku) một cậu nhóc với niềm ngưỡng mộ anh hùng mãnh liệt. Người Deku thần tượng nhất chính là All Might – anh hùng vĩ đại nhất thế giới. Cậu muốn trở thành anh hùng như All Might để bảo vệ và cứu giúp mọi người. Nhưng Hiện thực đau đớn đã dẫm nát giấc mơ của cậu, Deku chỉ là một người bình thường, luôn bị bắt nạt vì không có siêu năng lực. Cứ tưởng chừng ước mơ là không thể thực hiện cho đến ngày Deku gặp gỡ All Might, được ngài ấy ban cho năng lực &quot;One for All&quot;. Chính thức trở thành học viên của &quot;Học viện U.A&quot; - học viện siêu anh hùng hàng đầu tại Nhật Bản. Con đường từ một kẻ bất tài trở thành một siêu anh hùng bắt đầu!</p>', 'Hoàn Tất (27/27)', 27, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Daiki Yamashita","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["मेरा नायक एकेडेमिया","माई हीरो एकेडेमिया","ヒロアカ","Boku no Hero Academia","BNHA","僕のヒーローアカデミア Memories","僕のヒーローアカデミア No. 170+1 More","Boku no Hero Academia: More","Boku no Hero Academia No. 170+1: More","Boku no Hero Academia: I am a hero too","나의 히어로 아카데미아","أكاديمية بطلي","我的英雄學院 FINAL SEASON","Моя геройська академія","MHA","My Hero Academia: More","My Hero Academia: I am a hero too","Anh Hùng Học Viện","僕のヒーローアカデミア"]', 1784690324315);
