INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ban-xinh-dep-cua-toi', 'Người Bạn Xinh Đẹp Của Tôi', 'Young and Beautiful', 'https://phimimg.com/upload/vod/20251002-1/77ede7a0f59d7058dd3cbdec8f1b28c2.jpg', 'https://phimimg.com/upload/vod/20251002-1/219f8c9a91853b193547636448e17d39.jpg', '<p>Năm 2008, cô thôn nữ 19 tuổi Lưu Văn Tịnh từ Sơn Tây đến Thượng Hải một mình. Ở đó, cô gặp Hoa Hoa và Hình Thiên Minh và kết bạn với họ, từ đó cuộc sống của cô đã thay đổi. Trong suốt một thập kỷ sau đó, Lưu Văn Tịnh và những người bạn của cô đã giúp đỡ lẫn nhau và chiến đấu vì mục tiêu của riêng mình nhưng Lưu Văn Tịnh dần đánh mất chính mình. Bị ảnh hưởng bởi tình bạn và quan hệ họ hàng, cô tỉnh táo lại, từ bỏ cuộc sống trống rỗng và cuối cùng đã tìm lại được nguyện vọng ban đầu của mình.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Tian''ai","avatar":""},{"name":"Xu Kaicheng","avatar":""},{"name":"Daisy Li","avatar":""},{"name":"Joy Sheng","avatar":""},{"name":"Ouyang Xiao Ru","avatar":""},{"name":"Gao Zhiting","avatar":""},{"name":"Niu Zifan","avatar":""},{"name":"Yang Tingdong","avatar":""},{"name":"Ren Luomin","avatar":""},{"name":"Yan Jingyao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Ngo Di Piu Leung Pang Yau","Wo De Piao Liang Peng You","My Beautiful Friend","我的漂亮朋友"]', 1784690324315);
