INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('buoc-nhay-cham-den-tim-anh', 'Bước Nhảy Chạm Đến Tim Anh', 'You Make Me Dance', 'bước nhảy chạm đến tim anh you make me dance choo young-woo won tae-min jeon hyeong min lee su-ryeon 迷恋告急 与你共舞 时光可期 你让我跳舞 tu me haces bailar 너는나를춤추게한다 유메이크미댄스 유 메이크 미 댄스 (영화) you make me dance 時光可期 you make me dance (movie)', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bb-the-story-of-the-battle-of-brody-brandy', 'B&B: The Story of the Battle of Brody & Brandy', 'B&B: The Story of the Battle of Brody & Brandy', 'https://phimimg.com/upload/vod/20251001-1/cd6e44716ac9bca5a36f3ee68e5e1fc1.jpg', 'https://phimimg.com/upload/vod/20251001-1/7250f26586d6282542efeb539340ddda.jpg', '<p>Brandy Zulueta không phải là một tay mơ trong tình yêu. Cô ấy đã có chuỗi ngày lãng mạn tồi tệ, những gã bạn trai cũ khốn nạn và những mối quan hệ độc hại, đó là lý do tại sao cô ấy từ bỏ việc tìm kiếm một mối quan hệ tình cảm. Ở tuổi 38, cô hài lòng với cuộc sống độc thân, dành toàn bộ thời gian và sự quan tâm cho nhà khách chỉ phục vụ bữa sáng của mình. Đây là nhà của cô ấy, và những vị khách của cô ấy - gia đình của cô ấy. Cho đến khi cô gặp Brody Nuyda, người khiến cô tin tưởng vào sự lãng mạn một lần nữa. Brody Nuyda, ở tuổi 40, đang sống khoảng thời gian đẹp nhất trong cuộc đời - độc thân và không có bất kỳ gánh nặng nào, sở hữu và quản lý một số doanh nghiệp. Và rồi anh gặp Brandy, người khiến anh phải suy nghĩ lại về những lựa chọn trong cuộc sống. Cả hai đều sợ mạo hiểm và tình yêu, họ che giấu cảm xúc thật của mình bằng khả năng cạnh tranh và chiến lược kinh doanh. Nhưng cuối cùng, Brody và Brandy biết rằng họ sẽ chỉ làm tổn thương bản thân và đối phương nếu họ cố gắng che giấu cảm xúc của mình. Cả hai đều biết rằng họ cần phải đánh bạc một lần nữa để giành chiến thắng.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 17, 2021, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Iza Calzado","avatar":""},{"name":"Ian Veneracion","avatar":""},{"name":"Ketchup Eusebio","avatar":""},{"name":"Lovely Abella","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["B&B: The Story of the Battle of Brody & Brandy"]', 1784690324315);
