INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-10-la-hon', 'Đếm 10 Là Hôn', 'Lovely Writer (Uncut Ver.)', 'https://phimimg.com/upload/vod/20251001-1/7087f55bd8a6890e4e6c2fb02e03c40f.jpg', 'https://phimimg.com/upload/vod/20251001-1/bd5ccebbc6b59ce94d9a847a962479f6.jpg', '<p>Gene, một nhà văn chuyên nghiệp, một ngày nọ được nhà xuất bản yêu cầu thử sức với một thể loại mới, đó là Boys Love. Chấp nhận thử thách mới này, Gene viết và xuất bản một cuốn tiểu thuyết Y được mọi người đón nhận và trở nên thành công ngoài sức tưởng tượng. Thành công đến mức nó thậm chí còn được dựng thành một bộ phim truyền hình BL. Đây là câu chuyện về cách Gene, một nhà văn nổi tiếng, bị lừa bởi chàng trai 20 tuổi, Nubsib, người đến thử vai cho vai chính — giả vờ lịch sự và tốt bụng trong khi anh ta là một con sói chính hiệu.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Noppakao Dechaphatthanakun","avatar":""},{"name":"Poompat Iam-samang","avatar":""},{"name":"Sirikorn Kananurak","avatar":""},{"name":"Prarunyu Sooksamran","avatar":""},{"name":"Wasin Panunaporn","avatar":""},{"name":"Suppacheep Chanapai","avatar":""},{"name":"Nirodha Ruencharoen","avatar":""},{"name":"Nathanan Akkharakitwattanakul","avatar":""},{"name":"Papinee Yaemnatda","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["นับสิบจะจูบ","นับสิบจะจูบ Special Episode","Lovely Writer Special Episode","My Lovely Writer","Lovely Writer The Series"]', 1784690324315);
