INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-tuong-quan-thu-cung-cua-toi', 'Thiếu Tướng Quân Thú Cưng Của Tôi', 'Be My Cat', 'https://phimimg.com/upload/vod/20251001-1/335a7c5b3c70ef36d59bb7ae1495c67e.jpg', 'https://phimimg.com/upload/vod/20251001-1/a12aaa1fd3dbadcc50e1f5fde4f7734c.jpg', '<p>Ở nước Thanh Khâu, bên hồ Thanh Sơn của vùng Giang Châu có một tiệm thú cưng của bà chủ dễ thương tinh nghịch Tô Tiểu Hà (Điền Hy Vy đóng). Cô ấy tình cờ nhặt được một viên Lam Hồn Châu, đánh thức Hoàng tử Mèo đến từ DW tinh cầu. Hoàng tử Mèo hóa thần thành soái ca ngôn tình cộng thêm vẻ ngoài thần bí với tên gọi Mạc Tu Nhiễm (Tiêu Khải Trung đóng). Cả 2 cùng kí kết một bản khế ước nô bộc, mở ra một câu chuyện tình yêu nhân thú xuyên không vũ trụ, đánh bật mọi giống loài, cùng khám phá ra bí mật sau màn sương.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Kaizhong","avatar":""},{"name":"Tian Xiwei","avatar":""},{"name":"Sun Xizhi","avatar":""},{"name":"Wang Xiran","avatar":""},{"name":"Zhang Guansen","avatar":""},{"name":"Liu Jiaxi","avatar":""},{"name":"Wang Yimeng","avatar":""},{"name":"Xu Qin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Be My Cat","My Young Pet General","Мой юный питомец генерал","我的宠物少将军"]', 1784690324315);
