INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tong-dai-truy-vet', 'Tổng Đài Truy Vết', 'The Guilty', 'https://phimimg.com/upload/vod/20250930-1/08778fb560c232ff1ce0219e0d62254b.jpg', 'https://phimimg.com/upload/vod/20250930-1/ef40f4c6be1701df70be3ec66ca1ffcc.jpg', '<p>Bị giáng cấp làm nhân viên tổng đài 911, vị thanh tra phiền muộn vật lộn để cứu một người gọi gặp nguy nan — trong một ngày u ám đầy những phát hiện và nhìn nhận.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Riley Keough","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Christina Vidal","avatar":""},{"name":"Paul Dano","avatar":""},{"name":"Eli Goree","avatar":""},{"name":"Da''Vine Joy Randolph","avatar":""},{"name":"David Castañeda","avatar":""},{"name":"Adrian Martinez","avatar":""},{"name":"Christiana Montoya","avatar":""},{"name":"Gillian Zinser","avatar":""},{"name":"Aileen Burdock","avatar":""},{"name":"Bill Burr","avatar":""},{"name":"Beau Knapp","avatar":""},{"name":"Edi Patterson","avatar":""},{"name":"Marl","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["接线追缉","คนผิด","THE GUILTY／ギルティ","The Guilty"]', 1784690324315);
