INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-vi-tinh-than-phan-1', 'Hương Vị Tình Thân (Phần 1)', 'The Taste Of Intimacy (Season 1)', 'https://phimimg.com/upload/vod/20250930-1/e605ea09169ca44016a6ddd5650122c6.jpg', 'https://phimimg.com/upload/vod/20250930-1/7dbb6593d4cc853f8fe46f3d1a476580.jpg', '<p>Hương vị tình thân kể về Phương Nam, cuộc sống đảo lộn khi Nam phát hiện ra cô chỉ là con nuôi trong gia đình mình. Những biến cố liên tiếp ập tới. Giữa lúc đó, ông Sinh - cha ruột của Nam xuất hiện, lặng thầm bảo vệ con gái nhỏ. Nam luôn tin rằng cô sẽ tìm được một gia đình thực sự, và đến khi Hoàng Long xuất hiện, hạnh phúc tưởng đã mỉm cười với Nam. Nhưng khi đó, bí mật về ông Sinh được hé lộ khiến Nam sụp đổ. Những mâu thuẫn và ân oán lắt léo buộc Nam đứng trước hai lựa chọn: gia đình mà cô vừa gây dựng hay người cha tù tội vẫn lặng thầm bảo vệ cô.</p>', 'Hoàn Tất (71/71)', 71, 'series', 'completed', 16, 2021, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Võ Hoài Nam","avatar":""},{"name":"Phương Oanh","avatar":""},{"name":"Mạnh Trường","avatar":""},{"name":"Thu Quỳnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324315);
