INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-ngot-cua-mau', 'Vị Ngọt Của Máu', 'The Sweet Blood', 'https://phimimg.com/upload/vod/20250930-1/dc01c8514e7422eca8ea8f552959665d.jpg', 'https://phimimg.com/upload/vod/20250930-1/ad0e344dc99e921096cfdb5e6ff4f7e4.jpg', '<p>Vị Ngọt Của Máu kể về Yeon Seo (Song Chae Yeon đảm nhận), một nữ sinh trường trung học và đang đối mặt với những áp lực thi cử. Cô vốn là nửa người nửa ma cà rồng và đã sống được 118 năm với cuộc sống bình thường, cho đến khi gặp Song Meo Roo (Kim Eo Jin đóng) dường như cô không thể khống chế được khả năng thèm máu của mình bởi sức hút từ vị ngọt của máu của Song Meo Roo. Đặc biệt hơn, máu của Meo Roo còn thu hút cả những ma cà rồng khác lẫn loài sói ăn thịt người khiến cậu rơi vào nguy hiểm, lúc này Yeon Seo quyết đứng ra bảo vệ cậu nhưng liệu rằng cô có cưỡng lại được bản năng ma cà rồng của mình trước vị ngọt của máu đó hay không?</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Song Chae-yoon","avatar":""},{"name":"Kim Jiwoong","avatar":""},{"name":"Kim Eo-jin","avatar":""},{"name":"Yoon Da-young","avatar":""},{"name":"Cho Eun-ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["甜甜的那家伙","달달한그놈","The Sweet Blood","달달한 그놈"]', 1784690324315);
