INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-bl-va-chang-trai-khong-muon-bi-be-cong', 'Thế Giới BL Và Chàng Trai Không Muốn Bị Bẻ Cong', 'A Man Who Defies the World of BL', 'https://phimimg.com/upload/vod/20241026-1/29d27877855060b9595ca8e82d86617d.jpg', 'https://phimimg.com/upload/vod/20241026-1/e5bd99664bc0f03233dbce9b17517073.jpg', '<p>Hành trình chàng trai thẳng sống trong thế giới - nơi mà trai đẹp toàn yêu nhau sẽ ra sao, tất cả sẽ có trong Thế Giới BL Và Chàng Trai Không Muốn Bị Bẻ Cong.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 10, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"犬飼貴丈","avatar":""},{"name":"ゆうたろう","avatar":""},{"name":"塩野瑛久","avatar":""},{"name":"Masaki Yabe","avatar":""},{"name":"小林亮太","avatar":""},{"name":"Wataru Kuriyama","avatar":""},{"name":"北村諒","avatar":""},{"name":"濱正悟","avatar":""},{"name":"Kusachi Ryono","avatar":""},{"name":"Kondo Yohdi","avatar":""},{"name":"Shin Tamura","avatar":""},{"name":"Fuma Sadamoto","avatar":""},{"name":"小南光司","avatar":""},{"name":"Nakamoto Taiga","avatar":""},{"name":"本田響矢","avatar":""},{"name":"砂川脩弥","avatar":""},{"name":"Sakata Hideaki","avatar":""},{"name":"Yuya Uno","avatar":""},{"name":"宇佐卓真","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["绝对会变成BL的世界VS绝不想变成BL的男人","Zettai BL Ni Naru Sekai vs Zettai BL Ni Naritakunai Otoko","Zettai BL ni Naru Sekai VS Zettai BL ni Naritakunai Otoko 2024","絶対BLになる世界VS絶対BLになりたくない男3","絶対BLになる世界VS絶対BLになりたくない男 2024","A Man Who Defies the World of BL 3","Ostatni hetero vs. tęczowy świat","絶対BLになる世界vs絶対BLになりたくない男"]', 1784690324315);
