INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-bl-va-chang-trai-khong-muon-bi-be-cong', 'Thế Giới BL Và Chàng Trai Không Muốn Bị Bẻ Cong', 'A Man Who Defies the World of BL', 'thế giới bl và chàng trai không muốn bị bẻ cong a man who defies the world of bl 犬飼貴丈 ゆうたろう 塩野瑛久 masaki yabe 小林亮太 wataru kuriyama 北村諒 濱正悟 kusachi ryono kondo yohdi shin tamura fuma sadamoto 小南光司 nakamoto taiga 本田響矢 砂川脩弥 sakata hideaki yuya uno 宇佐卓真 绝对会变成bl的世界vs绝不想变成bl的男人 zettai bl ni naru sekai vs zettai bl ni naritakunai otoko zettai bl ni naru sekai vs zettai bl ni naritakunai otoko 2024 絶対blになる世界vs絶対blになりたくない男3 絶対blになる世界vs絶対blになりたくない男 2024 a man who defies the world of bl 3 ostatni hetero vs. tęczowy świat 絶対blになる世界vs絶対blになりたくない男', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-anh-tinh-yeu', 'Ảo Ảnh Tình Yêu', 'Love is Phantom', 'https://phimimg.com/upload/vod/20250930-1/c43d32fcef7053ec957a37a79ca800a7.jpg', 'https://phimimg.com/upload/vod/20250930-1/5ec45ef1724c1c62f639bd07c5781c9e.jpg', '<p>Một câu chuyện tình yêu bắt đầu khi Hirasawa Momoko, nhân viên quán cà phê tại một khách sạn, gặp một người lạ trên đài quan sát của khách sạn. Dù mới gặp nhưng họ đã liên tục hôn nhau. Ngày hôm sau, Momoko không thể quên được chuyện đó và biết rằng người đàn ông đó là Hase Kei, một chủ khách sạn ưu tú làm việc tại cùng một khách sạn và quá &quot;hoàn hảo&quot; đối với cô.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Renn Kiriyama","avatar":""},{"name":"Sakurako Konishi","avatar":""},{"name":"Megumi Sato","avatar":""},{"name":"Yuki Kubota","avatar":""},{"name":"Kanata Hosoda","avatar":""},{"name":"Wakana Matsumoto","avatar":""},{"name":"Akane Hotta","avatar":""},{"name":"Yumi Takigawa","avatar":""},{"name":"Hiroaki Murakami","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Love is Phantom","ラブファントム"]', 1784690324315);
