INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-hen-uoc', 'Lời Hẹn Ước', 'Be Loved in House: I Do', 'https://phimimg.com/upload/vod/20250930-1/df4ef7171be14c3901afcb0f011e9fdb.jpg', 'https://phimimg.com/upload/vod/20250930-1/534f85217ed22a6e867ee194f1ae0cd7.jpg', '<p>Lời Hẹn Ước là câu chuyện tình yêu dễ thương giữa một hoàng tử bé và con cáo ranh mãnh. Bắt đầu từ một lời hứa, gã giám đốc lạnh lùng và chàng nhân viên kiêu ngạo sống cùng một mái nhà... Tình yêu bắt đầu đơm hoa trong trái tim của họ.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 13, 2021, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Aaron Lai","avatar":""},{"name":"Hank Wang","avatar":""},{"name":"Liao Wei-po","avatar":""},{"name":"JN Yu","avatar":""},{"name":"Yao Mi","avatar":""},{"name":"Chen Xi Teng","avatar":""},{"name":"Lotus Wang","avatar":""},{"name":"Deyn Li","avatar":""},{"name":"Ai Yu Fan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Be Loved in House 約・定～I do","約定","約・定～I do","Be Loved in House: I Do","約．定"]', 1784690324315);
