INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-quy-tay-song-nguyet', 'Nhạn Quy Tây Song Nguyệt', 'Time Flies and You Are Here', 'https://phimimg.com/upload/vod/20250930-1/6cbdf57ea7b22474823a56e742c8fe01.jpg', 'https://phimimg.com/upload/vod/20250930-1/e66602d94c921a49ab1e916667585ad5.jpg', '<p>Nhạn Quy Tây Song Nguyệt kể về cuộc đời của Xie Jiang Er, một cô con gái của một gia đình rất lớn. Cô ấy sẽ gặp Zhao Xiao Qian, nơi cả hai sẽ cùng nhau trải qua những cuộc phiêu lưu và tìm thấy tình yêu cho nhau.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Joseph Zeng","avatar":""},{"name":"Liang Jie","avatar":""},{"name":"Fan Zhixin","avatar":""},{"name":"Liu Luoxi","avatar":""},{"name":"Li Jiulin","avatar":""},{"name":"Li Xinze","avatar":""},{"name":"Guan Chang","avatar":""},{"name":"Cao Wanjin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["如梦令","Yan Gui Xi Chuang Yue","Yan Gui Xi Chaung Yue","雁歸西窗月","雁归西窗月"]', 1784690324315);
