INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-vang-2021', 'Màu Vàng', 'Yellow', 'https://phimimg.com/upload/vod/20250928-1/568396d135cf5b70f9cd3833d74fca62.jpg', 'https://phimimg.com/upload/vod/20250928-1/f98a89873c48100f561238b98b5fb92f.jpg', '<p>Thiên tài âm nhạc Ji Hoon đã gửi gắm mối tình đầu của mình, người mà anh yêu say đắm như âm nhạc. Soo A tích cực, người nói rằng điều đơn giản là tốt nhất cho cả tình yêu và âm nhạc. Tae Min, đạt được tất cả nhưng không thể chiếm được trái tim của người mình yêu. Yeo Reum theo chủ nghĩa hiện thực, người muốn yêu thích công việc một cách hoàn hảo. JaPi và Dong Woo, những người thích tận hưởng hiện tại. Sáu chàng trai và cô gái khác nhau hát về tuổi trẻ và tình yêu.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Se-jin","avatar":""},{"name":"Kim Ye Ji","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324315);
