INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-xinh-dep-ban-nhat', 'Cô Nàng Xinh Đẹp (Bản Nhật)', 'She Was Pretty (Japan Version)', 'https://phimimg.com/upload/vod/20250928-1/372cb4425f295db015edff9a683cb9c7.jpg', 'https://phimimg.com/upload/vod/20250928-1/8ca838065047b1fbb088de9735afaf35.jpg', '<p>Bộ phim kể về câu chuyện tình yêu giữa một nữ chính xinh đẹp, người đã trở thành một phụ nữ thất nghiệp từ một sinh viên hàng đầu và người bạn chơi thời thơ ấu của cô đã chuyển từ một người đàn ông béo thành một người đàn ông ưu tú.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kento Nakajima","avatar":""},{"name":"Fuka Koshiba","avatar":""},{"name":"Eiji Akaso","avatar":""},{"name":"Yui Sakuma","avatar":""},{"name":"Nana Katase","avatar":""},{"name":"Yuto Takahashi","avatar":""},{"name":"Misato Ugaki","avatar":""},{"name":"Murase Sae","avatar":""},{"name":"LiLiCo","avatar":""},{"name":"Ayana Sogawa","avatar":""},{"name":"Paolo Andrea Di Pietro","avatar":""},{"name":"Momoko Yamada","avatar":""},{"name":"Chikara Honda","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kanojo wa Kirei datta","彼女はキレイだった (2021)","She Was Pretty","彼女はキレイだった"]', 1784690324315);
