INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-nang-xinh-dep-ban-nhat', 'Cô Nàng Xinh Đẹp (Bản Nhật)', 'She Was Pretty (Japan Version)', 'cô nàng xinh đẹp (bản nhật) she was pretty (japan version) kento nakajima fuka koshiba eiji akaso yui sakuma nana katase yuto takahashi misato ugaki murase sae lilico ayana sogawa paolo andrea di pietro momoko yamada chikara honda kanojo wa kirei datta 彼女はキレイだった (2021) she was pretty 彼女はキレイだった', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-long-yen-nguyet-dao', 'Thanh Long Yến Nguyệt Đao', 'Green Dragon Crescent Blade', 'https://phimimg.com/upload/vod/20250926-1/bcf8d91a93f514efe10e7de1ec0ad020.jpg', 'https://phimimg.com/upload/vod/20250926-1/1799ce3554233cd83baa7806fb202837.jpg', '<p>Trong trận chiến Mạch thành, Quan Vũ bị Phan Chương của quân Ngô giết chết, Thanh Long Yển Nguyệt Đao cũng bị cướp đi từ đó. Quan Hưng, con trai của Quan Vũ may mắn sống sót một lòng báo thù cho cha, khổ luyện võ công chỉ vì muốn đoạt thần binh về. &nbsp;Hai năm sau, Lưu Bị chuẩn bị thảo phạt nước Ngô, lệnh cho các tướng lĩnh trẻ tuổi do Quan Hưng đứng đầu hợp thành một đội bí mật thực thi nhiệm vụ phá hoại trung khu phòng ngự của quân Ngô. Quan Hưng đã vượt qua vô vàn trở ngại, hiểm nguy chồng chất, bất ngờ phát hiện âm mưu của quân Ngô, xoay vần thế cục cuộc chiến trong thời khắc mấu chốt. Cuối cùng, Quan Hưng quyết chiến với kẻ thù giết cha Phan Chương ở thủy trại, liệu Thanh Long Yển Nguyệt Đao sẽ về tay ai đây?</p>', 'Full', 1, 'single', 'completed', 22, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Quan Trí Bân","avatar":""},{"name":"Lục Thụ Minh","avatar":""},{"name":"Tấn Tùng","avatar":""},{"name":"Chu Hàng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qīnglongyanyuedāo","청룡언월도","Knights of Valour","Thanh Long Yến Nguyệt Đao","靑龍偃月刀","Green Dragon Crescent Blade","Клинок дракона","Рыцари доблести","青龙偃月刀"]', 1784690324315);
