INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-nhuom-song-vo-danh-duc-huyet-vo-danh-xuyen', 'Máu Nhuộm Sông Vô Danh (Dục Huyết Vô Danh Xuyên)', 'Bloodbath In The Nameless River (Raid)', 'https://phimimg.com/upload/vod/20250926-1/b358b518cc75431332592202f1965a76.jpg', 'https://phimimg.com/upload/vod/20250926-1/d7aaceca5f1186aab373483df733b454.jpg', '<p>Bộ phim lấy bối cảnh chiến tranh Triều Tiên, kể về một nhóm chiến sĩ Trung Quốc phải vượt qua hiểm nguy và hy sinh trên chiến trường Vô Danh Xuyên, khắc họa tinh thần quả cảm và tình đồng đội trong khói lửa chiến tranh.</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Đông Học","avatar":""},{"name":"Nhậm Thiên Dã","avatar":""},{"name":"Trương Lộ","avatar":""},{"name":"Phó Mỹ","avatar":""},{"name":"Hảo Hán","avatar":""},{"name":"Khúc Gia Huỳnh","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["浴血无名川","Bloody Nameless River"]', 1784690324315);
