INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mau-nhuom-song-vo-danh-duc-huyet-vo-danh-xuyen', 'Máu Nhuộm Sông Vô Danh (Dục Huyết Vô Danh Xuyên)', 'Bloodbath In The Nameless River (Raid)', 'máu nhuộm sông vô danh (dục huyết vô danh xuyên) bloodbath in the nameless river (raid) lý đông học nhậm thiên dã trương lộ phó mỹ hảo hán khúc gia huỳnh 浴血无名川 bloody nameless river', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoa-hoc-tinh-yeu', 'Khoa Học Tình Yêu', 'Love Is Science?', 'https://phimimg.com/upload/vod/20250925-1/427f9098e97005fbdfafefd8e2263874.jpg', 'https://phimimg.com/upload/vod/20250925-1/b409802e0cd8212ec35c5fdcca89567b.jpg', '<p>Xinh đẹp, năng động, tài giỏi, Nhan Phi là sếp của một công ty môi giới hôn nhân có tiếng. Sự kết hợp khéo léo giữa các con số, dữ liệu và kinh nghiệm sống giúp cô se duyên thành công cho nhiều đối tượng độc thân. Ấy vậy mà chính bản thân cô lại gặp phải nhiều trắc trở trong chuyện tình duyên. Sau một cuộc hôn nhân thất bại, Nhan Phi gặp lại một người bạn cũ vốn đã thầm yêu trộm nhớ cô từ rất lâu nhưng lại không dám thổ lộ. Thế nhưng, khi tình cảm của hai người vừa chớm nở thì người chồng cũ lại bất ngờ quay về, quyết tâm hàn gắn tình xưa.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 12, 2021, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Mạc Duận Văn","avatar":""},{"name":"Ngô Niệm Hiển","avatar":""},{"name":"Hoàng Vi Đình","avatar":""},{"name":"Trịnh Úy Đạt","avatar":""},{"name":"Cao Tuệ Nha","avatar":""},{"name":"Lâm Vũ","avatar":""},{"name":"Hứa Hoài Dân","avatar":""},{"name":"Diệp Toàn Chân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lian Ai Shi Ke Xue","Always Be With You","戀愛是科學"]', 1784690324315);
