INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khoa-hoc-tinh-yeu', 'Khoa Học Tình Yêu', 'Love Is Science?', 'khoa học tình yêu love is science? mạc duận văn ngô niệm hiển hoàng vi đình trịnh úy đạt cao tuệ nha lâm vũ hứa hoài dân diệp toàn chân lian ai shi ke xue always be with you 戀愛是科學', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-va-lois-phan-1', 'Siêu Nhân Và Lois (Phần 1)', 'Superman And Lois (Season 1)', 'https://phimimg.com/upload/vod/20250331-1/b96ae5d461d0ea4edfd7cec155778e58.jpg', 'https://phimimg.com/upload/vod/20250331-1/9faa4081d3ad9897d39303f15123086b.jpg', '<p>Clark Ken/ Superman và người vợ Lois Lane chuyển về Smallville sống cùng 2 cậu con trai là Jonathan và Jordan. Tại đây, họ bắt đầu một cuộc phiêu lưu mới đầy thử thách, hiểm nguy và một kẻ thù mới đầy bí ẩn.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 8, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tyler Hoechlin","avatar":""},{"name":"Elizabeth Tulloch","avatar":""},{"name":"Alex Garfin","avatar":""},{"name":"Michael Bishop","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["超人和露易丝","超人与露易丝","ზეადამიანი და ლოისი","סופרמן ולואיס","슈퍼맨 & 로이스","စူပါမန်းနှင့် ချစ်ဇနီး","Süpermen ve Lois","Superman and Lois","DC''s Superman & Lois","Superman & Lois"]', 1784690324315);
