INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-nhan-va-lois-phan-1', 'Siêu Nhân Và Lois (Phần 1)', 'Superman And Lois (Season 1)', 'siêu nhân và lois (phần 1) superman and lois (season 1) tyler hoechlin elizabeth tulloch alex garfin michael bishop 超人和露易丝 超人与露易丝 ზეადამიანი და ლოისი סופרמן ולואיס 슈퍼맨 & 로이스 စူပါမန်းနှင့် ချစ်ဇနီး süpermen ve lois superman and lois dc''s superman & lois superman & lois', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-debut', 'The Debut', 'The Debut', 'https://phimimg.com/upload/vod/20250923-1/4f2ea7e77ffae12a5f3ebe65f99e4e07.jpg', 'https://phimimg.com/upload/vod/20250923-1/a7d1fd82022eb6864ad54715d825499c.jpg', '<p>J-Pop đã trở lại và phổ biến hơn bao giờ hết ở Thái Lan. Nhiều cô gái trẻ mơ ước được gia nhập nhóm nhạc thần tượng nổi tiếng. Họ mơ ước trở nên nổi tiếng. Họ muốn trở thành tâm điểm, họ muốn mặc những bộ trang phục tuyệt vời nhất và biểu diễn trước đám đông khổng lồ. Nhưng để được ở trong một nhóm nhạc thần tượng không phải là điều dễ dàng. Những cô gái trẻ hay ‘thành viên’ này phải tuân thủ các quy tắc nghiêm ngặt trong ít nhất 6 năm. Quên đi cuộc sống bình thường của một thiếu niên. Quên chuyện hẹn hò đi. Các thành viên này phải luyện tập cả ngày lẫn đêm. Họ phải loại bỏ tính cách cũ của mình và thay thế bằng hình tượng ‘ngây thơ, cô gái nhà bên’ mà các fan hay ‘Ota’ tán thành. FAME muốn thử giọng cho nhóm nhạc thần tượng nổi tiếng có tên là &#39;Newtype&#39;. Chương trình thực sự của cô là tìm hiểu về cái chết của cô em gái FARN, người từng là thành viên trong nhóm nhạc thần tượng này. Cô ấy có lý do để tin rằng em gái mình đã bị các thành viên Newtype khác bắt nạt thậm tệ. Fame nhờ người bạn Ota giúp đỡ để biến cô thành một cô gái ngây thơ, kiểu thần tượng hàng xóm. Sau đó cô ấy được nhận vào nhóm.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ploypailin Thangprapaporn","avatar":""},{"name":"Nathasit Kotimanuswanich","avatar":""},{"name":"Jirayu La-ongmanee","avatar":""},{"name":"Darisa Karnpoj","avatar":""},{"name":"Rachanun Mahawan","avatar":""},{"name":"Chonnikan Netjui","avatar":""},{"name":"Nachjaree Horvejkul","avatar":""},{"name":"Nara Thepnupha","avatar":""},{"name":"Nardear Montgod","avatar":""},{"name":"Warawut Brown","avatar":""},{"name":"Supranee Charoenpol","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["เดอะ เดบิวต์..อวสานไอดอล","เดอะเดบิวต์..อวสานไอดอล"]', 1784690324315);
