INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phan-kich-cua-so-2', 'Cuộc Phản Kích Của Số 2', 'Fighting Mr. 2nd', 'https://phimimg.com/upload/vod/20250919-1/82700aca9d3fec4a59e7b8f0aca8fce1.jpg', 'https://phimimg.com/upload/vod/20250919-1/334d9fb3329db27e573149c973956ea1.jpg', '<p>Từ thanh xuân vườn trường đến cú phản kích trên thương trường. Năm năm rồi, may mắn kia có còn là của tôi không? Hôm nay, ai trong &quot;Hoa Khánh&quot; cũng đang gặp rủi ro của riêng mình. Không vì nguyên nhân nào khác, thân là công ty bị thu mua thì ai mà không lo cho bát cơm của mình? Dù cho người phụ trách đã đảm bảo rằng bên mua sẽ không dễ dàng điều động nhân sự, nhưng không thể chắc chắn được việc không sa thải nhân viên. Nhất là khi nghe nói vị giám đốc mà đối phương cử tới để phụ trách điều chỉnh lại là đại đao vương của nhà họ Châu - Người &quot;chém người không thấy máu, giết người không run tay&quot; trong truyền thuyết? Châu Thư Dật tức tối trừng mắt nhìn Cao Sĩ Đức vẫn đang tỏ ra ung dung trước mắt. Thời gian năm năm đủ để khiến hai chàng trai trở thành hai người đàn ông, cũng đủ để Châu Thư Dật nhìn rõ tình cảm điên cuồng thời trai trẻ? Một người không bao giờ chịu thua như cậu quyết định, nếu anh đã vô tâm thì tôi cũng chẳng cần gì nữa. Từ đó, mây tầng nào gặp mây tầng đó! Không ngờ, sau năm năm oan gia ngõ hẹp, Cao Sĩ Đức lại là người đại diện cho công ty kỹ thuật mà gia đình mình thu mua. Một số 2 vạn năm bị tên vô lương tâm nào đó vứt bỏ quyết định phản kích. Có thể trên phương diện học tập, cậu không thắng được anh ta, nhưng trong công việc, cậu sẽ cho anh ta biết thế nào gọi là sự kiêu ngạo của bên mua! Bạn có bằng lòng tin một người vẫn luôn yêu thương, chiều chuộng mình hay không?</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 20, 2021, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Lâm Tử Hoành","avatar":""},{"name":"YU Dương Vũ Đằng","avatar":""},{"name":"Trương Duệ Gia","avatar":""},{"name":"Thạch Trí Điền","avatar":""},{"name":"Lý Tề","avatar":""},{"name":"Evan Luo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["WBL亚洲耽美影集系列","No. 1 For You","We Best Love之永远的第一名","我们挚爱的故事之永远的第一名","We Best Love: No 1 for You","We Best Love: Fighting Mr. 2nd","We Best Love第二季","第二名的逆襲","We Best Love之第二名的逆袭","We Best Love：No 1 for You","We Best Love 2位の反撃","WBL","永遠的第一名","我們最好的愛","我们挚爱的故事"]', 1784690324315);
