INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-phan-kich-cua-so-2', 'Cuộc Phản Kích Của Số 2', 'Fighting Mr. 2nd', 'cuộc phản kích của số 2 fighting mr. 2nd lâm tử hoành yu dương vũ đằng trương duệ gia thạch trí điền lý tề evan luo wbl亚洲耽美影集系列 no. 1 for you we best love之永远的第一名 我们挚爱的故事之永远的第一名 we best love: no 1 for you we best love: fighting mr. 2nd we best love第二季 第二名的逆襲 we best love之第二名的逆袭 we best love：no 1 for you we best love 2位の反撃 wbl 永遠的第一名 我們最好的愛 我们挚爱的故事', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-mai-la-so-1', 'Mãi Mãi Là Số 1', 'No.1 For You', 'https://phimimg.com/upload/vod/20250919-1/8132677cbc3772bf7c7806fc1a7f8ab8.jpg', 'https://phimimg.com/upload/vod/20250919-1/53ac81eab5ec8969acd0e816c83ff3ff.jpg', '<p>Lúc nào cũng bị người khác chèn ép là cảm giác thế nào? Châu Thư Dật trừng mắt nhìn bảng thành tích của cả lớp trong tay, cậu lại một lần nữa trông thấy cái tên Cao Sĩ Đức đè lên đầu mình. Cậu không hiểu, kể từ năm lớp năm khi người này bước vào cuộc đời cậu, vị trí thứ nhất đã bỏ cậu mà đi, để cậu từ “luôn là số một” trở thành “số hai vạn năm”… Cuối cùng, đến năm lớp 12 thì cậu không chịu đựng nổi nữa. Châu Thư Dật cười trộm, tốt lắm, vào đại học là đường ai nấy đi, cuối cùng họ cũng có thể không gặp lại nhau nữa rồi! Châu Thư Dật vui sướng đón chào cuộc sống đại học, cậu vào câu lạc bộ bơi lội mà mình yêu thích nhất, lúc nào cũng được tán tụng. Nào ngờ, trước khi tốt nghiệp, trong một cuộc thi dành cho sinh viên mới gia nhập câu lạc bộ, cậu lại thấy Cao Sĩ Đức xuất hiện. Lần này, không những chưa kịp đoạt giải quán quân trước mặt đàn chị mà mình yêu thầm, cậu còn bị ngã xuống nước, chuột rút suýt nữa chết đuối. Châu Thư Dật chỉ có ba chữ… Thật – muốn – chết! Sau đó cậu lại phát hiện ra đàn chị hẹn hò với cậu bạn thân nhất của mình, cậu càng muốn đập đầu vào gối tự sát, quả nhiên cứ gặp Cao Sĩ Đức là không có chuyện gì tốt đẹp! Cậu không biết trời đất rộng lớn như vậy, tại sao đi đến đâu Cao Sĩ Đức cũng bám theo cậu. Người đó nói… “Tôi luôn dõi theo cậu”, vậy muốn dõi theo đến lúc nào mới chịu buông tha cho cậu đây?</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 17, 2021, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"YU","avatar":""},{"name":"Sam Lin","avatar":""},{"name":"Ray Chang","avatar":""},{"name":"Richard Lee","avatar":""},{"name":"Moon Lee","avatar":""},{"name":"Hsia Teng Hung","avatar":""},{"name":"Shih Chih-tian","avatar":""},{"name":"Eriku Yoza","avatar":""},{"name":"Evan Luo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["WBL亚洲耽美影集系列","No. 1 For You","We Best Love之永远的第一名","我们挚爱的故事之永远的第一名","We Best Love: No 1 for You","We Best Love: Fighting Mr. 2nd","We Best Love第二季","第二名的逆襲","We Best Love之第二名的逆袭","We Best Love：No 1 for You","We Best Love 2位の反撃","WBL","永遠的第一名","我們最好的愛","我们挚爱的故事"]', 1784690324315);
