INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-noi-goc-toi', 'Bí Mật Nơi Góc Tối', 'Our Secret', 'https://phimimg.com/upload/vod/20250722-1/c9f4cc0a87708756de234b7e2b934cf2.jpg', 'https://phimimg.com/upload/vod/20250722-1/34dd51e26248293b1de7d757f0f67aaa.jpg', '<p>Câu chuyện thanh xuân tốt đẹp kể về nam thần trường học xuất sắc Chu Tư Việt và cô gái lọ len Đinh Tiễn quật cường đáng yêu, hai người từ việc là bạn cùng bàn ghét bỏ lẫn nhau, rồi trong cuộc sống chung ngày qua ngày dần phát hiện ra ưu điểm của đối phương, cùng ở bên nhau trải qua sự mù mịt và trở ngại trên con đường tuổi trẻ, cuối cùng hai người đạt được thành tựu bứt phá.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2021, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Phàn Trị Hân","avatar":""},{"name":"Trần Triết Viễn","avatar":""},{"name":"Từ Mộng Khiết","avatar":""},{"name":"Vương Trạch Hiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["An Ge Li De Mi Mi","The Secret of the Dark Grid","Our Secrets","Secrets in the Lattice","暗格里的秘密"]', 1784690324315);
