INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-troi-van-dung-yen', 'Mặt Trời Vẫn Đứng Yên', 'The Sun Stands Still', 'https://phimimg.com/upload/vod/20250913-1/99eaf99b814d2a415930207aa1b80f50.jpg', 'https://phimimg.com/upload/vod/20250913-1/72edfc9e47afa8af008bbb6f3f113fb4.jpg', '<p>Kazuhiko Takano và Ryoichi Taoka là những gián điệp công nghiệp. Đằng sau công nghệ có thể làm rung chuyển thế giới chính trị và kinh tế Nhật Bản tồn tại một âm mưu nguy hiểm. Takano phải đối mặt với điệp viên Hàn Quốc Kim, một người phụ nữ bí ẩn tên Ayako cùng những thế lực quyền lực đến từ nhiều quốc gia khác nhau.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tatsuya Fujiwara","avatar":""},{"name":"Ryoma Takeuchi","avatar":""},{"name":"Han Hyo-joo","avatar":""},{"name":"Byun Yo-han","avatar":""},{"name":"Hayato Ichihara","avatar":""},{"name":"Sara Minami","avatar":""},{"name":"Seishirou Katou","avatar":""},{"name":"Eiji Yokota","avatar":""},{"name":"Alissa Yagi","avatar":""},{"name":"Hiroshi Katsuno","avatar":""},{"name":"Yoshiko Miyazaki","avatar":""},{"name":"Shingo Tsurumi","avatar":""},{"name":"Koichi Sato","avatar":""},{"name":"Wataru Hyuga","avatar":""},{"name":"Kaei Okina","avatar":""},{"name":"Kotaro Daigo","avatar":""},{"name":"Yusuke Hirayama","avatar":""},{"name":"R","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Taiyo wa Ugokanai","The Sun Does Not Move","烈日特工：毁灭倒数","太阳不会动","太陽は動かない"]', 1784690324315);
