INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mat-troi-van-dung-yen', 'Mặt Trời Vẫn Đứng Yên', 'The Sun Stands Still', 'mặt trời vẫn đứng yên the sun stands still tatsuya fujiwara ryoma takeuchi han hyo-joo byun yo-han hayato ichihara sara minami seishirou katou eiji yokota alissa yagi hiroshi katsuno yoshiko miyazaki shingo tsurumi koichi sato wataru hyuga kaei okina kotaro daigo yusuke hirayama r taiyo wa ugokanai the sun does not move 烈日特工：毁灭倒数 太阳不会动 太陽は動かない', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-anh-kinh-hoang-ma-xui-quy-khien', 'Ám Ảnh Kinh Hoàng: Ma Xui Quỷ Khiến', 'The Conjuring: The Devil Made Me Do It', 'https://phimimg.com/upload/vod/20250515-1/705035af0e0364db6aa43bb72b82fe52.jpg', 'https://phimimg.com/upload/vod/20250515-1/e4e1127eb380173f18de4f955011ede1.jpg', '<p>Phần phim đen tối và đáng sợ nhất của vũ trụ kinh dị The Conjuring, dựa trên &quot;Vụ án kẻ sát nhân quỷ nhập&quot; gây rúng động nước Mỹ. Câu chuyện rùng rợn về vụ giết người và tội ác chưa từng được biết đến, gây sợ hãi cho hai nhà ngoại cảm Ed và Lorraine Warren. Đây là một trong những vụ án giật gân nhất từ hơn 3,000 hồ sơ của họ, bắt đầu bằng cuộc chiến giành linh hồn từ tay quỷ dữ cho một cậu bé, sau đó đưa họ vào trải nghiệm khủng khiếp nhất từ trước đến nay, để đánh dấu lần đầu tiên trong lịch sử nước Mỹ, một nghi phạm giết người tuyên bố mình bị quỷ nhập hồn, sai khiến cơ thể làm điều sai trái.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Patrick Wilson","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Ruairí O''Connor","avatar":""},{"name":"Sarah Catherine Hook","avatar":""},{"name":"Julian Hilliard","avatar":""},{"name":"Charlene Amoia","avatar":""},{"name":"Sterling Jerins","avatar":""},{"name":"John Noble","avatar":""},{"name":"Eugenie Bondurant","avatar":""},{"name":"Shannon Kook","avatar":""},{"name":"Ronnie Gene Blevins","avatar":""},{"name":"Keith Arthur Bolden","avatar":""},{"name":"Steve Coulter","avatar":""},{"name":"Vince Pisani","avatar":""},{"name":"Megan Ashley Br","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2f