INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-dien-tran-trui-phan-2', 'Đạo Diễn Trần Trụi (Phần 2)', 'The Naked Director (Season 2)', 'https://phimimg.com/upload/vod/20250829-1/a189ee1591320341215b0f87f7ff28d9.jpg', 'https://phimimg.com/upload/vod/20240709-1/2b2f12589fb624328b1ea30095f86f9c.jpg', '<p>Kịch bản phim lấy bối cảnh vào những năm 1980 để khắc họa về cuộc sống và sự nghiệp của Toru Muranishi. Bên cạnh đó, phim cũng phơi bày hiện thực về ngành công nghiệp làm phim người lớn của nước Nhật và cuộc đời của các diễn viên, nhà sản xuất phim JAV ở phía sau hậu trường. Muranishi Tooru là đạo diễn tài năng nhưng cũng đầy tai tiếng, ông cũng là người sáng tạo ra phong cách bán tài liệu rất phổ biến trong dòng phim người lớn nhưng cũng được biết đến với danh xưng &quot;Lão già bẩn thỉu&quot; nhất trong những lão già bẩn thỉu của ngành công nghiệp khiêu dâm.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takayuki Yamada","avatar":""},{"name":"Shinnosuke Mitsushima","avatar":""},{"name":"Misato Morita","avatar":""},{"name":"Tetsuji Tamayama","avatar":""},{"name":"Tokio Emoto","avatar":""},{"name":"Sairi Ito","avatar":""},{"name":"Takenori Goto","avatar":""},{"name":"Jun Kunimura","avatar":""},{"name":"Ami Tomite","avatar":""},{"name":"Nuno Uraji","avatar":""},{"name":"Yusaku Mori","avatar":""},{"name":"Kanae Otsuka","avatar":""},{"name":"Mariya Nishiuchi","avatar":""},{"name":"Pierre Taki","avatar":""},{"name":"Show Kasamatsu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","s