INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-quy', 'Ấn Quỷ', 'The Unholy', 'https://phimimg.com/upload/vod/20250823-1/a0a7c46da6fe9d30012b9372318b2508.jpg', 'https://phimimg.com/upload/vod/20250823-1/2d761d9ad0299658f37b870b8e5cf59e.jpg', '<p>Ấn Quỷ xoay quanh cô gái khiếm thính Alice tại một thị trấn nhỏ thuộc vùng New England. Một ngày nọ, cô bỗng nhiên có thể nghe, nói như bình thường và có được năng lực chữa bệnh cho mọi người. Hàng trăm nghìn người từ khắp đất nước đổ về chứng kiến phép màu của cô. Trong số này, nhà báo Gerry Fenn muốn thực hiện một phóng sự để cứu vãn sự nghiệp. Song, hàng loạt những sự kiện kinh hoàng xảy ra khiến ông dần nhận ra thế lực ma quỷ thật sự đứng sau lưng cô gái trẻ.</p>', 'Full', 1, 'single', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Cricket Brown","avatar":""},{"name":"William Sadler","avatar":""},{"name":"Katie Aselton","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Diogo Morgado","avatar":""},{"name":"Bates Wilder","avatar":""},{"name":"Marina Mazepa","avatar":""},{"name":"Christine Adams","avatar":""},{"name":"Dustin Tucker","avatar":""},{"name":"Gisela Chípe","avatar":""},{"name":"Danny Corbo","avatar":""},{"name":"Sonny Corbo","avatar":""},{"name":"Michael Strauss","avatar":""},{"name":"Madison LaPlante","avatar":""},{"name":"Doria Bramante","avatar":""},{"name":"Stephen O","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shrine","邪恶玛利亚","Rogai por Nós","הטמאה","Mëkatarja","اللا مقدسة","Nečastiva","Nesveta","Нечестивият","不洁","顯靈","Zvrácená","