INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-xuyen-phan-1', 'Tử Xuyên (Phần 1)', 'Purple River (Season 1)', 'https://phimimg.com/upload/vod/20250822-1/5ff75d15f16658506d12400511729e8e.jpg', 'https://phimimg.com/upload/vod/20250822-1/4a6994ddfb90dec9ec27def0020ff78c.jpg', '<p>Truyền kì máu lửa qua từng thời đại: Trong đế quốc của loài người, gia tộc thần bí ở phương Đông xa xôi, Tử Xuyên Tam Kiệt phất lên! Anh cả Đế Lâm chín chắn đa mưu, tàn khốc lí trí, anh hai Sterling chỉ huy một đội quân, có lòng trung thành với nước, em út Tử Xuyên Tú bị người đời gọi với cái tên “Vô Lại”, trí dũng song toàn. Gia tộc Tử Xuyên loạn trong giặc ngoài, Tử Xuyên Tam Kiệt mỗi người đều có thế mạnh riêng: Trong thời khắc nước sôi lửa bỏng, đánh bại Ma tộc hung ác, xông vào hang hổ truy sát tên phản đồ Lôi Hồng đến cùng; Tư Đặc Lâm lấy gia tộc làm gốc, vừa vô tình vừa trọng tình lưu luyến người yêu... Loài người, Ma tộc, Thú tộc. Mỗi tộc ở mỗi phương khác nhau, tranh chấp lẫn nhau trên mảnh đất Đại Lục này, xích mích không ngừng. Khi máu và lửa hòa vào nhau, đao và kiếm va chạm, tạo ra câu chuyện sử thi bi tráng-Tử Xuyên.</p>', 'Hoàn Tất (42/42)', 42, 'hoathinh', 'completed', 9, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tang Bao","avatar":""},{"name":"Zhengyang Ma","avatar":""},{"name":"Jiang Guangtao","avatar":""},{"name":"Baomu Zhongyang","avatar":""},{"name":"Ajie","avatar":""},{"name":"Qiao Shiyu","avatar":""},{"name":"Liangwei Hu","avatar":""},{"name":"Gao Qifan","avatar":""},{"name":"Xiao Han","avatar":""},{"name":"Yuanfei Mei","avatar":""},{"name":"Zhou Dong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Zi Chuan","ZICHUAN","紫川动画","Purple River","紫川：光明王者","紫川·光明王者","紫川","紫川三傑","Eternal Brotherhood","The Legend of Zichuan Clan","Tử Xuyên 3D","Tử Xuyên"]', 1784690324315);
