INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('son-ha-lenh', 'Sơn Hà Lệnh', 'Word Of Honor', 'https://phimimg.com/upload/vod/20250815-1/2442fd1555bb69bf130ce196231def65.jpg', 'https://phimimg.com/upload/vod/20250815-1/aa44c80476fd29ff3ede3181fe506f81.jpg', '<p>Thủ lĩnh Thiên Song Chu Tử Thư vì mưu cầu tự do, không tiếc dùng mạng để rời khỏi tổ chức, lúc mạng sống không còn lâu gặp được Ôn Khách Hành cốc chủ Quỷ Cốc một lòng muốn tiêu diệt thế gian. Hai người vì rơi vào phân tranh của giang hồ mà quen biết nhau, cuối cùng trở thành sự cứu rỗi của cuộc đời nhau. Một âm mưu, hai tri kỷ, năm mảnh bảo tàng hợp lại, ân oán hai mươi năm, giấc mộng giang hồ ngàn vạn năm.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2021, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Triết Hạn","avatar":""},{"name":"Khấu Chấn Hải","avatar":""},{"name":"Từ Thiếu Cường","avatar":""},{"name":"Lương Gia Nhân","avatar":""},{"name":"Vương Cương","avatar":""},{"name":"Trần Tử Hàm","avatar":""},{"name":"Cung Tuấn","avatar":""},{"name":"Chu Dã","avatar":""},{"name":"Mã Văn Viễn","avatar":""},{"name":"Tôn Hy Luân","avatar":""},{"name":"Kim Nhạc","avatar":""},{"name":"Kha Nãi Dư","avatar":""},{"name":"Vương Nhược Lân","avatar":""},{"name":"Quách Gia Hào","avatar":""},{"name":"Hắc Tử","avatar":""},{"name":"Trầm Bảo Bình","avatar":""},{"name":"Trương Song Lợi","avatar":""},{"name":"Vương Bạ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-