INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tao-hac-phong-bao', 'Tảo Hắc Phong Bạo', 'Crime Crackdown', 'https://phimimg.com/upload/vod/20250806-1/3adb9d16107bc3327eb5d703ec473b42.jpg', 'https://phimimg.com/upload/vod/20250806-1/8b4dae3c9d146cd4752ee048486c473a.jpg', '<p>Bộ phim xoay quanh chiến dịch “quét sạch băng nhóm tội phạm” của cơ quan công an Trung Quốc. Nhân vật trung tâm là Lý Thành Dương (Tôn Hồng Lôi) – cựu đội trưởng đội hình sự, bị hãm hại và sa thải vì điều tra các thế lực đen. Khi trung ương mở chiến dịch chống tội phạm có tổ chức, anh được mời quay lại phối hợp với Lâm Hạo (Trương Nghệ Hưng) – một cảnh sát trẻ, và Hạ Dũng (Lưu Dật Quân) – bạn đồng nghiệp cũ, để lần ra chân tướng. Trong quá trình phá án, họ phát hiện mạng lưới tội phạm phức tạp do ông trùm Cao Minh Viễn (Vương Chí Phi) cầm đầu, liên kết chặt chẽ với nhiều quan chức biến chất. Phim khắc họa cuộc đấu trí, đấu lực giữa cảnh sát và thế lực đen, phơi bày những âm mưu tham nhũng, lợi ích nhóm, đồng thời cho thấy sự kiên trì và dũng cảm của những người thực thi pháp luật trong việc bảo vệ công lý.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Hồng Lôi","avatar":""},{"name":"Trương Nghệ Hưng","avatar":""},{"name":"Lưu Dật Quân","avatar":""},{"name":"Ngô Việt","avatar":""},{"name":"Vương Chí Phi","avatar":""},{"name":"Lưu Chi Băng","avatar":""},{"name":"Ngô Hiểu Lượng","avatar":""},{"name":"Giang Thư Ảnh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["扫黑风暴","Crime Crackdown"]', 1784690324315);
