INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mortal-kombat-cuoc-chien-sinh-tu', 'Mortal Kombat: Cuộc Chiến Sinh Tử', 'Mortal Kombat', 'https://phimimg.com/upload/vod/20250804-1/e810d7c6c3b2ebac27eba6497d902976.jpg', 'https://phimimg.com/upload/vod/20250804-1/e374adac33c262576afaec4dcaf2fc8a.jpg', '<p>Mortal Kombat: Cuộc Chiến Sinh Tử xoay quanh võ sĩ võ thuật tổng hợp Cole Young (Lewis Tan), người mang trên mình một vết chàm rồng đen bí ẩn - biểu tượng của Mortal Kombat. Cole Young không hề biết về dòng máu bí ẩn đang chảy trong người anh, hay vì sao anh lại bị tên sát thủ Sub-Zero (Joe Taslim) săn lùng. Vì sự an nguy của gia đình, Cole cùng với một nhóm những chiến binh đã được tuyển chọn để tham gia vào một trận chiến đẫm máu nhằm chống lại những kẻ thù đến từ Outworld.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lewis Tan","avatar":""},{"name":"Jessica McNamee","avatar":""},{"name":"Mehcad Brooks","avatar":""},{"name":"Josh Lawson","avatar":""},{"name":"Ludi Lin","avatar":""},{"name":"Max Huang","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Chin Han","avatar":""},{"name":"Hiroyuki Sanada","avatar":""},{"name":"Joe Taslim","avatar":""},{"name":"Sisi Stringer","avatar":""},{"name":"Daniel Nelson","avatar":""},{"name":"Matilda Kimber","avatar":""},{"name":"Laura Brent","avatar":""},{"name":"Melanie Jarnson","avatar":""},{"name":"Nathan Jones","avatar":""},{"name":"Ian Streetz","avatar":""},{"name":"Yukiko Shinohara","avatar":""},{"name":"Re","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d4