INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-tau-bang-gia-phan-2', 'Chuyến Tàu Băng Giá (Phần 2)', 'Snowpiercer (Season 2)', 'chuyến tàu băng giá (phần 2) snowpiercer (season 2) daveed diggs mickey sumner alison wright iddo goldberg roberto urbina rowan blanchard katie mcguinness sam otto clark gregg michael aronov 雪国列车 snowpiercer 末世列車 רכבת הקרח برف‌شکن یخ‌شکن قطار برف‌شکن قطار یخ‌شکن スノーピアサー 설국열차 ледоломац сквозь снег 末日列車 крізь сніг снігокол', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-tia-chop-phan-8', 'Người Hùng Tia Chớp (Phần 8)', 'The Flash (Season 8)', 'https://phimimg.com/upload/vod/20250729-1/bcf50b7305a1a381b596dce4b148bf78.jpg', 'https://phimimg.com/upload/vod/20250729-1/2048b0a5b6b06199a2ab7fc01b679255.jpg', '<p>Phim dựa theo một nhân vật của DC Comics, trong 1 thí nghiệm tại Starling City, anh chàng Barry đã vô tình bị ảnh hưởng bởi vụ nổ trong thí nghiệm khiến anh hôm mê bất tỉnh nhiều ngày trong bệnh viện. Khi tỉnh dậy, anh ta đã phát hiện ra rằng mình có khả năng đặc biệt đó là tăng tốc độ cơ thể và di chuyển siêu nhanh. Kể từ đây, huyền thoại về người anh hùng Flash bắt đầu.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Grant Gustin","avatar":""},{"name":"Candice Patton","avatar":""},{"name":"Danielle Panabaker","avatar":""},{"name":"Danielle Nicolet","avatar":""},{"name":"Kayla Compton","avatar":""},{"name":"Brandon McKnight","avatar":""},{"name":"Jon Cor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["闪电侠 (格兰特·古斯汀)","The Flash (2014)","The Flash 2014","פלאש","플래시","The Flash"]', 1784690324315);
