INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-ly-hoan-anh', 'Xin Chào Lý Hoán Anh', 'Hi, Mom', 'https://phimimg.com/upload/vod/20250725-1/efae165c8f19a7a88b61f93a1cfc58b7.jpg', 'https://phimimg.com/upload/vod/20250725-1/7042970e5ed2ff497b4708b516620750.jpg', '<p>Sinh viên Đại học Giả Hiểu Linh suy sụp khi nghe tin mẹ cô qua đời trong một tai nạn, và tự trách mình vì đã không phải là một người con tốt. Trong cơn khủng hoảng tinh thần, cô bất ngờ xuyên không về năm 1981, nơi cô gặp gỡ phiên bản trẻ tuổi của mẹ mình, Lý Hoán Anh, và cả hai nhanh chóng trở nên thân thiết không rời. Mặc dù Hiểu Linh quyết tâm cải thiện cuộc sống của mẹ mình bằng cách sử dụng những hiểu biết từ tương lai, nhưng kế hoạch của cô liên tục gặp trục trặc. Cô sớm nhận ra mình đang tạo ra những thay đổi có thể phải trả giá đắt.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Giả Linh","avatar":""},{"name":"Trương Tiểu Phỉ","avatar":""},{"name":"Thẩm Đằng","avatar":""},{"name":"Trần Hách","avatar":""},{"name":"Vương Lâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hi, MOM","Hello, Li Huanying","Nǐ hǎo, Lǐ Huànyīng","니호, 이환영","Nihao, Li Huanying","Hi Mom","你好，李焕英"]', 1784690324315);
