INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoat-chet', 'Thoát Chết', 'Out Of Death', 'https://phimimg.com/upload/vod/20231109-1/02f177bc651453793b7086fd68e3cc84.jpg', 'https://phimimg.com/upload/vod/20231109-1/81f66725942848de33c5def0f5bdbd89.jpg', '<p>Đang tận hưởng sự yên bình ở thị trấn nhỏ, cựu cảnh sát Jack Harris lại chứng kiến vụ án mạng tàn bạo. Báo án không thành vì hung thủ đã xóa mọi dấu vết, ông quyết định tự mình tìm ra kẻ sát nhân.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jaime King","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Lala Kent","avatar":""},{"name":"Tyler Jon Olson","avatar":""},{"name":"Kelly Greyson","avatar":""},{"name":"Michael Sirow","avatar":""},{"name":"Megan Leonard","avatar":""},{"name":"Kayla Eva","avatar":""},{"name":"Oliver Trevena","avatar":""},{"name":"Kendyll Legier","avatar":""},{"name":"Lauren McCord","avatar":""},{"name":"Adam Huel Potter","avatar":""},{"name":"Keagan Lasater","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324315);
