INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('belle-rong-va-cong-chua-tan-nhang', 'Belle: Rồng và Công Chúa Tàn Nhang', 'Belle', 'https://phimimg.com/upload/vod/20250725-1/c6d2df2693558a5c44ca9cf60f44b5fa.jpg', 'https://phimimg.com/upload/vod/20250725-1/f911f47ef325e50604ade7643cf8f60e.jpg', '<p>Suzu là một học sinh trung học bình thường, nhút nhát sống ở một ngôi làng nông thôn. Trong nhiều năm, cô ấy chỉ là cái bóng của chính mình. Nhưng khi bước vào &quot;U&quot;, một thế giới ảo rộng lớn, cô ấy thoát vào nhân vật trực tuyến của mình là Belle, một ca sĩ tuyệt đẹp và được yêu mến trên toàn cầu. Một ngày nọ, buổi biểu diễn của cô bị gián đoạn bởi một sinh vật quái dị bị truy đuổi bởi những người cảnh giác. Khi cuộc săn lùng của họ leo thang, Suzu bắt tay vào một nhiệm vụ đầy cảm xúc và sử thi để khám phá danh tính của &quot;quái thú&quot; bí ẩn này và khám phá con người thật của cô ấy trong một thế giới mà bạn có thể là bất cứ ai.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaho Nakamura","avatar":""},{"name":"Ryo Narita","avatar":""},{"name":"Shota Sometani","avatar":""},{"name":"Tina Tamashiro","avatar":""},{"name":"Lilas Ikuta","avatar":""},{"name":"Ryoko Moriyama","avatar":""},{"name":"Michiko Shimizu","avatar":""},{"name":"Fuyumi Sakamoto","avatar":""},{"name":"Yoshimi Iwasaki","avatar":""},{"name":"Sachiyo Nakao","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Mamoru Miyano","avatar":""},{"name":"Sumi Shimamoto","avatar":""},{"name":"Koji Yakusho","avatar":""},{"name":"Ken Ishiguro","avatar":""},{"name":"ermhoi","avatar":""},{"name":"Hana Hope","avatar":""},{"name":"Tak","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Ryuu to Sobakasu no Hime","용과 주근깨 공주","Belle: Smok i piegowata księżniczka","龙和雀斑公主","เจ้าหญิงแห่งเสียงเพลง","雀斑公主","龙与雀斑公主","Dragon and the Freckled Princess","Ryū to sobakasu no hime","Belle: The Dragon and the Freckled Princess","竜とそばかすの姫：2021","竜とそばかすの姫"]', 1784690324315);
