INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-danh-lap-van', 'Dương Danh Lập Vạn', 'Be Somebody', 'https://phimimg.com/upload/vod/20250725-1/6cdc3c479880337e90be1a25eef256ca.jpg', 'https://phimimg.com/upload/vod/20250725-1/73b884fc0f937f823aae856d79093d05.jpg', '<p>Vào thời kỳ Dân Quốc, một nhóm người chán nản từ giới điện ảnh được mời đến một dinh thự sang trọng để làm một bộ phim dựa trên một vụ án ghê rợn vừa gây chấn động thành phố Thượng Hải, với hy vọng rằng nó sẽ trở thành một hiện tượng lớn và mang lại danh tiếng cho họ. Tuy nhiên, họ không bao giờ ngờ rằng kẻ sát nhân lại ở giữa họ và sự thật đằng sau vụ án còn kỳ quái hơn nhiều so với cốt truyện hư cấu của bộ phim họ đang thực hiện.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Doãn Chính","avatar":""},{"name":"Đặng Gia Giai","avatar":""},{"name":"Dụ Ân Thái","avatar":""},{"name":"Dương Hạo Vũ","avatar":""},{"name":"Tần Tiêu Hiền","avatar":""},{"name":"Đặng Ân Hi","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Be Somebody","一部电影的诞生","The China Be Somebody","扬名立万"]', 1784690324315);
