INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-ma-tuy-mexico-phan-3', 'Trùm Ma Túy: Mexico (Phần 3)', 'Narcos: Mexico (Season 3)', 'https://phimimg.com/upload/vod/20250723-1/6980ab9c7f2a3badac8d1a87e8558eab.jpg', 'https://phimimg.com/upload/vod/20250723-1/f23ef2773c421ce94a592bc60b366faf.jpg', '<p>Bộ phim khám phá nguồn gốc của cuộc chiến ma túy hiện đại bằng cách quay trở lại thời điểm khi giới buôn hàng trắng Mexico chỉ mới là một liên minh lỏng lẻo và vô tổ chức của những người trồng và buôn bán thuốc phiện nhỏ lẻ. Bộ phim sẽ nói về sự nổi lên của Cartel Guadalajara trong những năm 1980 khi Félix Gallardo (Diego Luna) nắm quyền lãnh đạo, thống nhất những tay buôn để tạo nên một đế chế.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 11, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Scoot McNairy","avatar":""},{"name":"José María Yázpik","avatar":""},{"name":"Alejandro Edda","avatar":""},{"name":"Luis Gerardo Méndez","avatar":""},{"name":"Matt Letscher","avatar":""},{"name":"Gorka Lasaosa","avatar":""},{"name":"Alfonso Dosal","avatar":""},{"name":"Mayra Hermosillo","avatar":""},{"name":"Luisa Rubino","avatar":""},{"name":"Manuel Masalva","avatar":""},{"name":"Kristen Lee Gutoskie","avatar":""},{"name":"Bobby Soto","avatar":""},{"name":"Lorenzo Ferro","avatar":""},{"name":"José Zúñiga","avatar":""},{"name":"Alejandro Furth","avatar":""},{"name":"Alberto Guer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Narcos: Μεξικό","나르코스 멕시코","Барыги: Мексика","Narcos: Meksika","Narcos: Mexico"]', 1784690324315);
