INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-nha-mot-minh-6', 'Ở Nhà Một Mình 6', 'Home Sweet Home Alone', 'https://phimimg.com/upload/vod/20250722-1/f03994006d06f091c7299cad844bea94.jpg', 'https://phimimg.com/upload/vod/20250722-1/f771f88556d3e6245738a0d942314feb.jpg', '<p>Ở phiên bản Home Alone 2021, ngôi sao 12 tuổi Archie Yates sẽ là người kế nhiệm Macaulay Culkin để vào vai nam chính lầy lội. Diễn viên nhí người Anh này cũng đang là một trong những tài năng trẻ được đánh giá cao tại Hollywood, nhất là sau tác phẩm Jojo Rabbit đình đám của đạo diễn Thor Taika Waititi. &nbsp;Với cốt truyện quen thuộc, Home Sweet Home Alone vẫn sẽ tập trung vào kỳ nghỉ Giáng sinh đáng nhớ của cậu bé Kevin McCallister. Lần này, cậu nhóc tinh nghịch vô tình bị gia đình bỏ lại ngay trước chuyến du lịch đến Tokyo, Nhật Bản. Và y chang phần phim năm nào, Kevin lại một lần nữa đối mặt với lũ trộm &quot;vô liêm sỉ&quot; và cho ra đời vô vàn tình huống khó đỡ.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ellie Kemper","avatar":""},{"name":"Rob Delaney","avatar":""},{"name":"Archie Yates","avatar":""},{"name":"Aisling Bea","avatar":""},{"name":"Pete Holmes","avatar":""},{"name":"Kenan Thompson","avatar":""},{"name":"Timothy Simons","avatar":""},{"name":"Ally Maki","avatar":""},{"name":"Chris Parnell","avatar":""},{"name":"Devin Ratray","avatar":""},{"name":"Katie Beth Hall","avatar":""},{"name":"Max Ivutin","avatar":""},{"name":"Andy Daly","avatar":""},{"name":"Madeline Holliday","avatar":""},{"name":"Mikey Day","avatar":""},{"name":"Jordan Carlos","avatar":""},{"name":"Esther Povitsky","avatar":""},{"name":"Marty Adams","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["나 홀로 집에 6","Home Alone 6","Home Alone 6: Home Sweet Home Alone","Evde Tek Başına 6","Maman, j''ai raté l''avion (ça recommence)","Esqueceram de Mim no Lar, Doce Lar","Esqueceram de Mim 6","小鬼當家千日好","Mi Pobre Y Dulce  Angelito","홈 스위트 홈 얼론","בית מתוק לבד בבית","Ở Nhà Một Mình 6","Kevin - Allein zu Haus 6","Allein zu Haus 6","Untitled Home Alone Project","Home Alone 6: Home Sweet Home","Nicht schon wieder allein zu Haus","שכחו אותי בבית 6","לבד בבית 6","Maman, j''ai raté l''avion 3 - ça recommence","小鬼当家6：真爱宝藏","Միայնակ սիրելի տանը","Home Sweet Home Alone"]', 1784690324315);
