INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('o-nha-mot-minh-6', 'Ở Nhà Một Mình 6', 'Home Sweet Home Alone', 'ở nhà một mình 6 home sweet home alone ellie kemper rob delaney archie yates aisling bea pete holmes kenan thompson timothy simons ally maki chris parnell devin ratray katie beth hall max ivutin andy daly madeline holliday mikey day jordan carlos esther povitsky marty adams j 나 홀로 집에 6 home alone 6 home alone 6: home sweet home alone evde tek başına 6 maman, j''ai raté l''avion (ça recommence) esqueceram de mim no lar, doce lar esqueceram de mim 6 小鬼當家千日好 mi pobre y dulce  angelito 홈 스위트 홈 얼론 בית מתוק לבד בבית ở nhà một mình 6 kevin - allein zu haus 6 allein zu haus 6 untitled home alone project home alone 6: home sweet home nicht schon wieder allein zu haus שכחו אותי בבית 6 לבד בבית 6 maman, j''ai raté l''avion 3 - ça recommence 小鬼当家6：真爱宝藏 միայնակ սիրելի տանը home sweet home alone', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-luong-phan-ung-phan-5', 'Lực Lượng Phản Ứng (Phần 5)', 'Armed Reaction (Season 5)', 'https://phimimg.com/upload/vod/20250717-1/660f16d2708f80125e10a518de1b869c.jpg', 'https://phimimg.com/upload/vod/20250717-1/822047fa29787bf27393d6532b9dcb3f.jpg', '<p>Từ nhỏ, Trần Tam Nguyên đã chịu sự ảnh hưởng của chú mình là Trần Tiểu Sanh, cô gia nhập đội cảnh sát làm sư tỉ cầm sung và trở thành bạn tốt của Chu Tố Nga. Sau khi ly hôn, Tố Nga quen biết Trần Tiểu Sanh, hai người từ đôi oan gia đấu khẩu dần trở thành tình nhân. Tam Nguyên vì có biểu hiện xuất sắc nên được điều chuyển qua tổ chống mại dâm, hợp tác cùng Trình Phong, trở thành một đôi “anh em” tốt, nhưng một lần tình cờ, cô phát hiện Trình Phong có tình cảm với mình. Nhưng khi hai người ở bên nhau, Tam Nguyên lại đột nhiên ngừng bước…</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2021, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Âu Dương Chấn Hoa","avatar":""},{"name":"Quan Vịnh Hà","avatar":""},{"name":"Đằng Lệ Danh","avatar":""},{"name":"Ngụy Tuấn Kiệt","avatar":""},{"name":"Chu Mễ Mễ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["陀枪师姐","陀枪师姐2021","陀枪师姐 第5季 2021","Tuo qiang shi jie","陀槍師姐","Armed Reaction"]', 1784690324315);
