INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-khong-the-yeu-duong', 'Bí Mật Không Thể Yêu Đương', 'The Secret Of Love (The Secret Of Not Falling In Love)', 'https://phimimg.com/upload/vod/20250714-1/d80750764cd080379f482f735015592d.jpg', 'https://phimimg.com/upload/vod/20250714-1/a2593eb1443f9c105d2e359b9ec4b34d.jpg', '<p>Một vụ hỏa hoạn xảy ra đã khiến Tô Y bị mất đi một đoạn ký ức. Trong quá trình tìm kiếm sự thật và ký ức, cô gặp Lý Gia Thượng, CEO điển trai và lạnh lùng của Lý thị. Trùng hợp thay, Tô Y có khuôn mặt y hệt Mộc Miên, mối tình đầu mà Gia Thượng tìm kiếm bấy lâu nay. Rất nhanh chóng, hai người đã dành tình cảm cho nhau. Nhưng liệu có mối liên hệ nào giữa hai người con gái Tô Y và Mộc Miên?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Dịch Sướng","avatar":""},{"name":"Viên Vũ Huyên","avatar":""},{"name":"Trương Tư Phàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["网剧不能恋爱的秘密","사랑의 비밀","연애할수없는비밀","연애못하는 비밀","不能恋爱的秘密"]', 1784690324315);
