INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('la-ciguapa-siempre', 'La Ciguapa Siempre', 'La Ciguapa Siempre', 'https://phimimg.com/upload/vod/20250710-1/a2e04dfced157ff5df80e76a30da94cc.jpg', 'https://phimimg.com/upload/vod/20250710-1/4fabc7ddeb7243cf543258df9783957e.jpg', '<p>Trong bộ phim giật gân ngắn này, cô gái trẻ đang tìm kiếm bản sắc của chính mình đã tìm thấy nó giữa vùng hoang dã trong chuyến cắm trại rùng rợn cùng gã bạn trai mờ ám.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Cheyenne Washington","avatar":""},{"name":"Michael Bonini","avatar":""},{"name":"Jillian Kinsey","avatar":""},{"name":"Lotus Lain","avatar":""},{"name":"Nina A. Martinez","avatar":""},{"name":"Ashaki Ayoka","avatar":""},{"name":"Gaby Gonzalez","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["La Ciguapa Siempre"]', 1784690324315);
