INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chong-thu-hai', 'Người Chồng Thứ Hai', 'The Second Husband', 'https://phimimg.com/upload/vod/20250710-1/9af58e21d8305317bab53e2385fa7c1d.jpg', 'https://phimimg.com/upload/vod/20250710-1/96b125e93192b86ed4e3f169c4d4f80d.jpg', '<p>Để đến với Jae Kyeong, con gái chủ tịch một tập đoàn lớn, Sang Hyeok nhẫn tâm hãm hại gia đình nhỏ của mình, khiến người vợ Seon Hwa phải gánh chịu nỗi đau mất con. Mất đi tất cả tình yêu, niềm tin và hy vọng, Seon Hwa điên cuồng lao vào hành trình trả thù người chồng bội bạc. Nhưng rồi định mệnh trớ trêu lại khiến cô gặp được Jae Min, em trai kế của Jae Kyeong. Liệu Seon Hwa có thể vượt qua được bóng đen của quá khứ và mở lòng đón nhận tình cảm của anh?</p>', 'Hoàn Tất (100/100)', 100, 'series', 'completed', 7, 2021, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Uhm Hyun-kyung","avatar":""},{"name":"Cha Seo-won","avatar":""},{"name":"Oh Seung-ah","avatar":""},{"name":"Han Ki-woong","avatar":""},{"name":"Choi Seung-kyung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["二老","Dubeonjjae Nampyeon","Second Husband","두 번째 남편"]', 1784690324315);
