INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-rong-hau-gai-cua-kobayashi-phan-2', 'Cô Rồng Hầu Gái Của Kobayashi (Phần 2)', 'Miss Kobayashi''s Dragon Maid (Season 2)', 'https://phimimg.com/upload/vod/20250708-1/332ab245e2c402d63f5a38b38a6a264e.jpg', 'https://phimimg.com/upload/vod/20250708-1/0f837b6d2a7573c641dac7e41d4da345.jpg', '<p>Kobayashi - một nữ kĩ sư phần mềm chăm chỉ, độc thân, sống một mình ở một khu chung cư. Một lần, cô tình cờ cứu giúp một con rồng, loài vật huyền thoại có thể hủy diệt cả thế giới. Có nợ thì phải trả, dù đó có là loài người thấp kém, Tohru đã được dạy như thế. Cô tâm niệm sẽ giúp đỡ hết mình cho ân nhân trong vai trò maid - một hầu gái, dù đôi khi mọi thứ có vẻ không suôn sẻ lắm... Hãy cùng theo dõi hành trình trở thành Hầu Gái của Tohru và những tình huống dở khóc dở cười mà Kobayashi phải trải qua nào!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mutsumi Tamura","avatar":""},{"name":"Yuuki Kuwahara","avatar":""},{"name":"Maria Naganawa","avatar":""},{"name":"Yuuki Takada","avatar":""},{"name":"Minami Takahashi","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Emiri Kato","avatar":""},{"name":"Yuko Goto","avatar":""},{"name":"Kaori Ishihara","avatar":""},{"name":"Tomomi Mineuchi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["小林家的龙女仆","小林家的妹抖龙","小林家的女仆龙","小林家的女仆龙S","小林家的龙女仆S","המשרתת הדרקונית של קובאיאשי-סאן","העוזרת הדרקונית של קוביאשי-סאן","Kobayashi-san Chi no Maid Dragon","Kobayashi-san Chi no Maid Dragon S","小林さんちのメイドラゴンS","Kobayashi-san Chi no Meidoragon S","小林さんちのメイドラゴン","코바야시네 메이드래곤","고바야시네 메이드래곤","Kobayashi-san Chi no Maidragon S","Дракорничная госпожи Кобаяси","Дракон-горничная госпожи Кобаяси","Дракониха-горничная госпожи Кобаяси","โคบายาชิซังกับเมดมังกร","Драконопокоївка Кобаяші","Драконопокоївка пані Кобаяші","The Maid Dragon of Kobayashi-san","Miss Kobayashi''s Dragon Maid S"]', 1784690324315);
