INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-rong-hau-gai-cua-kobayashi-phan-2', 'Cô Rồng Hầu Gái Của Kobayashi (Phần 2)', 'Miss Kobayashi''s Dragon Maid (Season 2)', 'cô rồng hầu gái của kobayashi (phần 2) miss kobayashi''s dragon maid (season 2) mutsumi tamura yuuki kuwahara maria naganawa yuuki takada minami takahashi daisuke ono yuichi nakamura emiri kato yuko goto kaori ishihara tomomi mineuchi 小林家的龙女仆 小林家的妹抖龙 小林家的女仆龙 小林家的女仆龙s 小林家的龙女仆s המשרתת הדרקונית של קובאיאשי-סאן העוזרת הדרקונית של קוביאשי-סאן kobayashi-san chi no maid dragon kobayashi-san chi no maid dragon s 小林さんちのメイドラゴンs kobayashi-san chi no meidoragon s 小林さんちのメイドラゴン 코바야시네 메이드래곤 고바야시네 메이드래곤 kobayashi-san chi no maidragon s дракорничная госпожи кобаяси дракон-горничная госпожи кобаяси дракониха-горничная госпожи кобаяси โคบายาชิซังกับเมดมังกร драконопокоївка кобаяші драконопокоївка пані кобаяші the maid dragon of kobayashi-san miss kobayashi''s dragon maid s', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-di-thuong', 'Những Kẻ Dị Thường', 'The Misfits', 'https://phimimg.com/upload/vod/20250707-1/a5ffbf9b8534672846fbbc0cf8eabd64.jpg', 'https://phimimg.com/upload/vod/20250707-1/853cc65aef10d0cedbdd7271daec846b.jpg', '<p>Tên tội phạm khét tiếng, Richard Pace, được tuyển mộ vào một băng cướp với nhiều thành phần bất hảo để tham gia một phi vụ trộm vàng có một không hai. Trớ trêu thay, sự thành bại của phi vụ này không chỉ ảnh hưởng đến tính mạng của những tên trộm mà còn liên quan đến sự sống còn của rất nhiều người.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Tim Roth","avatar":""},{"name":"Nick Cannon","avatar":""},{"name":"Rami Jaber","avatar":""},{"name":"Jamie Chung","avatar":""},{"name":"Hermione Corfield","avatar":""},{"name":"Mike Angelo","avatar":""},{"name":"Qais Qandil","avatar":""},{"name":"Martin J. Corrado","avatar":""},{"name":"Robert Henny","avatar":""},{"name":"Samer al Masri","avatar":""},{"name":"Gonzalo Menendez","avatar":""},{"name":"Ahmed Mawas","avatar":""},{"name":"Christian Mandel","avatar":""},{"name":"Adam Stone","avatar":""},{"name":"Ehab Elganady","avatar":""},{"name":"Kouryou Ngin","avatar":""},{"name":"Mahmoud","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["偷天俠盜團","Ballistic","พยัคฆ์ทรชน ปล้นพลิกโลก","ザ・ミスフィッツ：2021","The Misfits","Bankas aplaupīšana"]', 1784690324315);
