INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-ke-di-thuong', 'Những Kẻ Dị Thường', 'The Misfits', 'những kẻ dị thường the misfits pierce brosnan tim roth nick cannon rami jaber jamie chung hermione corfield mike angelo qais qandil martin j. corrado robert henny samer al masri gonzalo menendez ahmed mawas christian mandel adam stone ehab elganady kouryou ngin mahmoud 偷天俠盜團 ballistic พยัคฆ์ทรชน ปล้นพลิกโลก ザ・ミスフィッツ：2021 the misfits bankas aplaupīšana', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-dang-nho-son-yaz', 'Mùa Hè Đáng Nhớ (Son Yaz)', 'Last Summer', 'https://phimimg.com/upload/vod/20250706-1/d3aed8079657b114c1bc82d1d52013c8.jpg', 'https://phimimg.com/upload/vod/20250706-1/bae2c46fd32940b7b744ca1c38ba90f9.jpg', '<p>Tám năm sau khi khởi tố thành công thủ lĩnh băng đảng tội phạm có tổ chức Selcuk Taskin, công tố viên Selim Kara nhận được một đề nghị khó từ chối từ ông trùm hiện đang thụ án trong tù. Selcuk muốn ra làm chứng trong một vụ án của Selim và lời khai của hắn có thể khiến toàn bộ tổ chức tội phạm sụp đổ. Điều kiện duy nhất Selcuk đưa ra là Selim phải bảo vệ con trai hắn, Akgun Gokalp, trước mọi mối đe dọa đến từ những đồng bọn cũ trong băng đảng.</p>', 'Hoàn Tất (93/93)', 93, 'series', 'completed', 26, 2021, 'Thuyết Minh', 'FHD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Ali Atay","avatar":""},{"name":"Alperen Duymaz","avatar":""},{"name":"Yaprak Medine","avatar":""},{"name":"Hafsanur Sancaktutan","avatar":""},{"name":"Birce Akalay","avatar":""},{"name":"Arif Pişkin","avatar":""},{"name":"Zuhal Gencer","avatar":""},{"name":"Halil Babür","avatar":""},{"name":"Yasemin Yazıcı","avatar":""},{"name":"Sezer Avcı","avatar":""},{"name":"Cengiz Okuyucu","avatar":""},{"name":"Adam Bay","avatar":""},{"name":"Yunus Narin","avatar":""},{"name":"Ata Nedim Arman","avatar":""},{"name":"Onur Bay","avatar":""},{"name":"Tayfun Sav","avatar":""},{"name":"İlda Özgürel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Τελευταίο Καλοκαίρι","Last Summer","Son Yaz"]', 1784690324315);
