INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-xa-thu', 'Tay Xạ Thủ', 'The Marksman (The Minuteman)', 'https://phimimg.com/upload/vod/20250701-1/2320e5358262d8abfd8239907983121c.jpg', 'https://phimimg.com/upload/vod/20250701-1/0ca7d825e50737ed6ac4ec0ab68e27ab.jpg', '<p>Jim - một cựu thủy quân lục chiến tại biên giới bang Arizona vô tình bị cuốn theo cuộc truy lùng của băng Vasquez khi cố giúp đưa Miguel thoát khỏi chúng. Nhiệm vụ giờ đây của Jim là &quot;vận chuyển&quot; Miguel về Chicago cùng gia đình trước sự truy giết máu lạnh của băng đảng Vasquez.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Jacob Perez","avatar":""},{"name":"Katheryn Winnick","avatar":""},{"name":"Teresa Ruiz","avatar":""},{"name":"Sean A. Rosales","avatar":""},{"name":"Jose Vasquez","avatar":""},{"name":"Juan Pablo Raba","avatar":""},{"name":"Alfredo Quiroz","avatar":""},{"name":"Antonio Leyba","avatar":""},{"name":"Dylan Kenin","avatar":""},{"name":"Luce Rains","avatar":""},{"name":"Ann Barrett Richards","avatar":""},{"name":"Clark Sanchez","avatar":""},{"name":"Alex Knight","avatar":""},{"name":"David DeLao","avatar":""},{"name":"Harry Maldonado","avatar":""},{"name":"Elias Gallegos","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["The Minuteman","The Marksman (El protector)","Закрилникът","Zaštitnik","Strzelec wyborowy","マークスマン：2021","Šāvējs","Zaščitnik","The Marksman"]', 1784690324315);
