INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-trom-2021', 'Siêu Trộm', 'The Vault (Way Down)', 'https://phimimg.com/upload/vod/20250701-1/2bf4fecfa86230c7712b4e69ef2fff13.jpg', 'https://phimimg.com/upload/vod/20250701-1/3d513026a5e7bbc432c2547d5d911b14.jpg', '<p>Ngân hàng Tây Ban Nha là một nơi bất khả xâm phạm, không một tên trộm nào có thể bước vào. Được xem như một nơi bí ẩn bậc nhất trên thế giới, ngân hàng này không có bản thiết kế, không dữ liệu lưu lại và không một ai biết đến cấu trúc sắp đặt bên trong chiếc két sắt hơn trăm năm tuổi. Thử thách này đã khơi dậy sự tò mò của Thom – một kỹ sư thiên tài quyết định thử đột nhập vào sâu bên trong nơi này và lật mở bí ẩn của chiếc két sắt.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Pháp', 0, '[{"name":"Freddie Highmore","avatar":""},{"name":"Astrid Bergès-Frisbey","avatar":""},{"name":"Jose Coronado","avatar":""},{"name":"Liam Cunningham","avatar":""},{"name":"Sam Riley","avatar":""},{"name":"Luis Tosar","avatar":""},{"name":"Emilio Gutiérrez Caba","avatar":""},{"name":"Axel Stein","avatar":""},{"name":"Daniel Holguín","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"James Giblin","avatar":""},{"name":"Frank Feys","avatar":""},{"name":"Fernando Martín","avatar":""},{"name":"Vicente Gil","avatar":""},{"name":"Bill Dixon","avatar":""},{"name":"Reg Wilson","avatar":""},{"name":"Julius Cotter","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["地窖奇劫","Countdown in Madri