INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-thu-bay', 'Ngày Thứ Bảy', 'The Seventh Day', 'https://phimimg.com/upload/vod/20250701-1/7201dbb5d6bf4c2ab513b89eeb19eacb.jpg', 'https://phimimg.com/upload/vod/20250701-1/f23f42a97c3dba5f90c0e56b83291d4d.jpg', '<p>Phim kể về ngày đầu tiên thực hiện chức trách của một linh mục. Công việc của anh là phối hợp với một nhà trừ tà nổi tiếng để đi sâu vào địa ngục nơi ác quỷ bị giam cầm. Khi họ chìm sâu hơn vào địa ngục trần gian, ranh giới thiện - ác dần mở ra cũng chính là lúc những con quỷ tàn bạo nhất xuất hiện.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Guy Pearce","avatar":""},{"name":"Vadhir Derbez","avatar":""},{"name":"Stephen Lang","avatar":""},{"name":"Brady Jenness","avatar":""},{"name":"Robin Bartlett","avatar":""},{"name":"Keith David","avatar":""},{"name":"Chris Galust","avatar":""},{"name":"Acoryé White","avatar":""},{"name":"James Healy Jr.","avatar":""},{"name":"Heath Freeman","avatar":""},{"name":"Hannah Alline","avatar":""},{"name":"Tristan Riggs","avatar":""},{"name":"Stephanie Rhodes","avatar":""},{"name":"Major Dodge","avatar":""},{"name":"Evangeline Griffin","avatar":""},{"name":"Johari Turner","avatar":""},{"name":"Björgvin Arnar","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Possédés: L''exorcisme","Exorcismo en el séptimo día","O Sétimo Dia","Le septième jour","The Seventh Day"]', 1784690324316);
