INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-em-bay-luon-theo-gio', 'Cùng Em Bay Lượn Theo Gió', 'To Fly With You', 'https://phimimg.com/upload/vod/20250615-1/5bbf1821e8c71dd2222373dac228e41d.jpg', 'https://phimimg.com/upload/vod/20250615-1/f68602ae704433a1e2c02fe266d853c8.jpg', '<p>Đam mê môn trượt băng ngắn, Thẩm Tranh Nhất giấu mẹ lén tham gia tuyển chọn người mới của câu lạc bộ Trục Phong và thực hiện ước mơ trở thành tuyển thủ chuyên nghiệp. Vì chưa từng được huấn luyện nên Thẩm Tranh Nhất gặp vô vàn khó khăn trong quá trình tập luyện khắt khe. Tuy nhiên may mắn lúc đó, nhờ có sự kề vai sát cánh của Hoàng tử trượt băng Thiệu Bắc Sênh mà cô dần lấy lại tự tin và vượt qua được mọi trở ngại. Trải qua nhiều chuyện, cả hai cũng dần thấu hiểu và cùng nhau vun đắp ước mơ.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Tổ Nhi","avatar":""},{"name":"Vương An Vũ","avatar":""},{"name":"Miêu Phố","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["陪你逐风飞翔","Volar Contigo","To Fly with You"]', 1784690324316);
