INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luong-ngon-ta-y', 'Lương Ngôn Tả Ý', 'Lie To Love', 'https://phimimg.com/upload/vod/20250614-1/e1b01143e3468bf7bdb2fc5a2f13607f.jpg', 'https://phimimg.com/upload/vod/20250614-1/f26fd29a4ac44db059deb67e49fdc66a.jpg', '<p>Một biến cố khiến Tô Tả Ý tan cửa nát nhà, người gây ra là Lệ Trạch Lương, người cô yêu sâu đậm. Để điều tra chân tướng, Tả Ý vờ mất trí và ở lại bên Trạch Lương, từng bước tính kế khiến sự nghiệp của anh sụp đổ. Khi chân tướng dần hé mở, Tô Tả Ý phát hiện luôn trách lầm Trạch Lương, rồi cố gắng cứu vãn mối tình đó, còn anh đáp lại bằng con dấu khắc tên hai người. Để bảo vệ tình yêu, hai người cùng gây dựng sự nghiệp, trở thành chỗ dựa vững chắc của nhau.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 10, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"La Vân Hi","avatar":""},{"name":"Trình Tiêu","avatar":""},{"name":"Quý Tiêu Băng","avatar":""},{"name":"Điền Y Đồng","avatar":""},{"name":"Cao Hàn","avatar":""},{"name":"Lý Giai Khiết","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Liang Yan Xie Yi","良言写意","Lie to Love","เกมรักซ่อนกลลวง","良言寫意"]', 1784690324316);
