INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-tu-luong', 'Quyến Tư Lượng', 'The Island Of Siliang', 'https://phimimg.com/upload/vod/20240205-1/7752d183a52b94a33749ab4d23afa11d.jpg', 'https://phimimg.com/upload/vod/20240205-1/3d2aff6a73488df49a35adbd4b6898db.jpg', '<p>Nữ chính Đồ Lệ là một phàm nhân, thích huyền ca và là một kỹ sư. Nam chính Kính Huyền có ước muốn lớn lên sẽ trở thành một chủ tướng khí thế. Nữ chính 2 Tu Linh Tê: là hậu duệ Thần Gia, là nữ nhân cầm kỳ thư họa đều tinh thông. Nam chính 2 Tiêu Tế là phàm nhân, anh ta khá đặc biệt, là hoàng tộc Tiêu Thị Phụng Miên: nữ chính 3, là một nữ tử thần bí, thuộc chủng tộc Thượng Cổ Thần Thú tộc Linh Hoàng.</p>', 'Hoàn Tất (30/30)', 30, 'hoathinh', 'completed', 36, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324316);
