INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-nao-cung-trang', 'Đại Náo Cung Trăng', 'Moonbound', 'đại náo cung trăng moonbound david daria stefko hanushevsky thyra uhde laurens walter stephan benson proschat madani caroline schreiber elisabeth kanettis den magiske maane rejse maagiline reis kuule le royaume des étoiles peterchen''s mondfahrt peterchens mondfahrt - wie anna und ihr bruder das universum retten 문바운드 peterchens mondfahrt', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-cuu-linh', 'Quân Cửu Linh', 'Jun Jiu Ling', 'https://phimimg.com/upload/vod/20250609-1/a0d2cfe8bc9a2de8e403b4245bc21dca.jpg', 'https://phimimg.com/upload/vod/20250609-1/b200664ff82f2a4617a94e8a5b99a23e.jpg', '<p>Quân Cửu Linh chuyển thể từ tiểu thuyết cùng tên của Hi Hành. Nữ chính Quân Cửu Linh (Bành Tiểu Nhiễm) công chúa tính tình thiện, một lòng yêu thích y thuật, là con gái của tiền thái tử. Sau khi cha chết thì em trai của cha lên làm hoàng đế. Cô được ban hôn cho thủ lĩnh cấm y vệ Lục Vân Kỳ. Sau vài năm thì phát hiện âm mưu của hoàng đế ngày xưa đã hại chết cha cô cướp ngôi của em trai cô. Cô quyết định đi hành thích, sau đó thất bại rồi bỏ mạng. Tái sinh vào một cô tiểu thư nhà giàu nhưng mồ côi. Rồi từng bước vượt qua chông gai để đấu tranh trả thù giành lại ngai vị cho em trai. Trên con đường đó gặp gỡ Chu Toản (Kim Hạn), con trai của Thành Quốc Công. Họ kết giao và nảy sinh tình cảm trong quá trình tìm lại chính nghĩa cũng như đấu trí chống lại ngoại bang xâm lược.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2021, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Tiểu Nhiễm","avatar":""},{"name":"Kim Hạn","avatar":""},{"name":"Đỗ Á Phi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jun Jiu Ling","九齢公主 隠された真実","君九龄"]', 1784690324316);
