INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-bup-be-chucky-phan-1', 'Ma Búp Bê Chucky (Phần 1)', 'Chucky (Season 1)', 'https://phimimg.com/upload/vod/20250515-1/b9361acb71a99a68753124b8154e5560.jpg', 'https://phimimg.com/upload/vod/20250515-1/1cae9587a95c879fd74b1206938d7cab.jpg', '<p>Sau khi một búp bê Chucky cổ bất ngờ xuất hiện tại một buổi bán đồ sân vườn ở vùng ngoại ô, một thị trấn yên bình kiểu Mỹ nhanh chóng rơi vào hỗn loạn. Hàng loạt vụ án mạng kinh hoàng diễn ra, dần vạch trần những giả dối và bí mật thầm kín mà thị trấn tưởng chừng hoàn hảo này đang che giấu. Trong lúc đó, những kẻ thù và đồng minh từ quá khứ của Chucky lần lượt xuất hiện, đe dọa phơi bày sự thật đằng sau những vụ giết người — và cả nguồn gốc đen tối chưa từng được tiết lộ của con búp bê quỷ ám này.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zackary Arthur","avatar":""},{"name":"Brad Dourif","avatar":""},{"name":"Björgvin Arnarson","avatar":""},{"name":"Alyvia Alyn Lind","avatar":""},{"name":"Devon Sawa","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chucky: A Série","чаки","鬼娃恰吉","Child''s Play: The TV Series","Don Mancini''s Chucky","Chucky"]', 1784690324316);
