INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ginny-georgia-phan-1', 'Ginny & Georgia (Phần 1)', 'Ginny & Georgia (Season 1)', 'https://phimimg.com/upload/vod/20241103-1/6f9820b6d6e9f33135cab4459b76e00b.jpg', 'https://phimimg.com/upload/vod/20250608-1/fc06147fcb4d34416e9b74b0232eb5e1.jpg', '<p>Georgia phóng khoáng cùng hai con Ginny và Austin đi về phía bắc tìm kiếm khởi đầu mới, nhưng nhận ra rằng con đường này có thể chứa đầy chông gai.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Antonia Gentry","avatar":""},{"name":"Brianne Howey","avatar":""},{"name":"Diesel La Torraca","avatar":""},{"name":"Jennifer Robertson","avatar":""},{"name":"Felix Mallard","avatar":""},{"name":"Sara Waisglass","avatar":""},{"name":"Scott Porter","avatar":""},{"name":"Raymond Ablack","avatar":""},{"name":"Katie Douglas","avatar":""},{"name":"Chelsea Clark","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ginny and Georgia","Ginny & Georgia"]', 1784690324316);
