INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('marvels-hitmonkey-phan-1', 'Marvel''s Hit-Monkey (Phần 1)', 'Marvel''s Hit-Monkey (Season 1)', 'https://phimimg.com/upload/vod/20250603-1/452869f39cd1cb7839542755a262a7d3.jpg', 'https://phimimg.com/upload/vod/20250603-1/9ed1b772ee4435056b86d4fd3f2cafe7.jpg', '<p>Marvels Hit-Monkey - một bộ phim hành động tâm lý đầy kịch tính và hấp dẫn, kể về câu chuyện của một sát thủ giấu tên bị truy sát sau khi tham gia vào cuộc đảo chính thất bại. Anh ta được cứu sống bởi một đoàn khỉ Nhật Bản, nhưng không ngờ rằng một con khỉ đơn độc lại học lấy kỹ năng của anh. Sự xung đột giữa sát thủ và con khỉ tạo nên những tình tiết gay cấn và ly kỳ trong phim, khiến cho bộ tộc khỉ phải tìm cách cứu chữa cho anh. Với sự xuất hiện của các diễn viên hàng đầu như Fred Tatasciore, Jason Sudeikis, George Takei, Marvels Hit-Monkey hứa hẹn mang lại trải nghiệm khó quên cho khán giả yêu thích thể loại phim hành động. Hãy chuẩn bị để khám phá câu chuyện ly kỳ này!</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Fred Tatasciore","avatar":""},{"name":"Jason Sudeikis","avatar":""},{"name":"Olivia Munn","avatar":""},{"name":"Ally Maki","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Leslie Jones","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["מארוול: היט מאנקי","マーベル ヒット・モンキー","마블 히트 멍키","히트멍키","Hit-Monkey","Marvel''s Hit-Monkey"]', 1784690324316);
