INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-chan-tu-phong-than-duyen-khoi', 'Lôi Chấn Tử: Phong Thần Duyên Khởi', 'Leizhenzi: The Origin Of The Gods', 'https://phimimg.com/upload/vod/20250530-1/78d110f5f9145cf5734b9053cc24a8db.jpg', 'https://phimimg.com/upload/vod/20250530-1/2f24d91e0b2343aaa6aaab208fdd9091.jpg', '<p>Thuở xưa Thiên Tôn dùng linh khí trời đất bày trận Phong Thần, người tộc Vũ trời sinh đã có cánh, do thám chuyện thế gian giữa đất trời, một khi gặp loạn thế, sẽ lợi dụng đôi cánh Phong Lôi khởi động trận. Những năm cuối Ân Thương, đứa trẻ định mệnh Lôi Chấn Tử và Tân Hoàn gánh vác sứ mệnh của người tộc Vũ, muốn sử dụng đôi cánh Phong Lôi cùng sức mạnh Tướng Tinh mở trận Phong Thần, câu chuyện bắt đầu từ đây.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Thừa Lâm","avatar":""},{"name":"Quách Gia Nam","avatar":""},{"name":"Liêu Thiên Sam","avatar":""},{"name":"Lưu Dũng","avatar":""},{"name":"Quách Vĩ","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Lei Zhen Zi Feng Shen Yuan Qi","Thunder Twins","雷震子：封神缘起"]', 1784690324316);
