INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lap-trinh-vien-dang-yeu', 'Lập Trình Viên Đáng Yêu', 'Cute Programmer', 'https://phimimg.com/upload/vod/20250515-1/8435c0e41b4e2dfe3b2a2e2534dff0d3.jpg', 'https://phimimg.com/upload/vod/20250515-1/f7da82bfe75472777747623a49b243fa.jpg', '<p>Sau khi yêu nam thần code Khương Dật Thành, Lục Ly không những ra sức học hành để vào cùng trường, cùng khoa công nghệ thông tin với anh mà còn ấp ủ giấc mơ trở thành một lập trình viên xinh đẹp. Với mục tiêu theo đuổi Khương Dật Thành, Lục Ly trở thành cô sinh viên xuất sắc như anh đã từng, nhưng không ngờ rằng công ty khởi nghiệp của Khương Dật Thành lại không tuyển dụng nhân viên nữ. Để lại gần nam thần, Lục Ly không ngần ngại giả nam để vào được công ty, sau đó bắt đầu đấu trí đấu dũng với anh chàng tổng giám đốc kiêu ngạo - Khương Dật Thành. Sau nhiều lần bị đả kích và nghi ngờ thân phận khiến Lục Ly ở công ty gặp nhiều khó khăn. Vì sự nghiệp yêu thầm, vì mục tiêu cuộc đời mà Lục Ly liều mình nắm bắt cơ hội, cuối cùng kí hợp đồng hôn nhân một năm với Khương Dật Thành. Trong thời gian sống chung, hai người có những câu chuyện ngọt ngào, Khương Dật Thành cũng dần dần yêu Lục Ly từ lúc nào không hay.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hình Chiêu Lâm","avatar":""},{"name":"Chúc Tự Đan","avatar":""},{"name":"Dịch Đại Thiên","avatar":""},{"name":"Điền Y Đồng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["the Programmer Is,so Cute","CYXNMKA","程序員那麼可愛","程序员那么可爱"]', 1784690324316);
