INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-man-dem-gon-song', 'Khi Màn Đêm Gợn Sóng', 'Love At Night', 'https://phimimg.com/upload/vod/20250504-1/4c02437bb21dc7f4234a40368a243c72.jpg', 'https://phimimg.com/upload/vod/20250504-1/cde1a3ddad69b722058ccc224f6c53b1.jpg', '<p>Hứa Khuynh Du và Phạm Vân Tích bên nhau hơn 10 năm và đang chuẩn bị tiến tới hôn nhân. Thế nhưng, khi phát hiện vị hôn phu lừa dối, Khuynh Du nhất quyết đòi chia tay. Ngay lúc này, định mệnh lại sắp đặt Khuynh Du &quot;va phải&quot; Mạc Linh Trạch, trai đẹp ban ngày làm CEO ban đêm làm ca sĩ chính kiêm tay guitar cho một ban nhạc. Câu chuyện của họ hứa hẹn sẽ rất thú vị khi cả hai đều là người tài giỏi trong công việc nhưng là kẻ thất bại trong chuyện tình cảm.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Dư Hi","avatar":""},{"name":"Lưu Học Nghĩa","avatar":""},{"name":"Triệu Viên Viện","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["When the Darkness Falls","Ye Sik Am Yung Si","Ye Se An Yong Shi","夜色暗涌时","Secret and Passionate Love","Love At Night","夜色暗涌時","夜色暗湧時"]', 1784690324316);
