INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yakuza-va-gia-dinh', 'Yakuza và Gia Đình', 'A Family & Yakuza', 'https://phimimg.com/upload/vod/20250511-1/774e9961349e7a13a2d4c7da091391bf.jpg', 'https://phimimg.com/upload/vod/20250511-1/5292bfdea0221592d52cd9ded9401ee4.jpg', '<p>Một câu chuyện về gia đình yakuza từ năm 1999 đến năm 2019. Cha của Kenji Yamamoto’s (Gou Ayano) đã chết vì sử dụng một loại thuốc kích thích. Cuộc sống của anh rơi vào tuyệt vọng. Kenji Yamamoto sau đó tham gia vào một tổ chức tội phạm. Tại đây, anh gặp trùm băng đảng Hiroshi Shibasaki (Hiroshi Tachi). Hiroshi Shibasaki tìm đến Kenji Yamamoto và họ đã phát triển một mối quan hệ như cha con. Thời gian trôi qua, Kenji Yamamoto đã có gia đình của riêng mình.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Go Ayano","avatar":""},{"name":"Hiroshi Tachi","avatar":""},{"name":"Machiko Ono","avatar":""},{"name":"Yukiya Kitamura","avatar":""},{"name":"Hayato Ichihara","avatar":""},{"name":"Hayato Isomura","avatar":""},{"name":"Shinobu Terajima","avatar":""},{"name":"Ryutaro Ninomiya","avatar":""},{"name":"Taro Suruga","avatar":""},{"name":"Ryo Iwamatsu","avatar":""},{"name":"Shun Sugata","avatar":""},{"name":"Suon Kan","avatar":""},{"name":"Kosuke Toyohara","avatar":""},{"name":"Rina Komiyama","avatar":""},{"name":"Goki Maeda","avatar":""},{"name":"Akito Fujii","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Yakuza to Kazoku","家族极道物语","黑道与家族","Yakuza and the Family","The Family","Yakuza i rodzina","A Family","ヤクザと家族","Yakuza to Kazoku The Family","ヤクザと家族 The Family"]', 1784690324316);
