INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-lang-hai-phan-1', 'Huyền Thoại Làng Hài (Phần 1)', 'Hacks (Season 1)', 'https://phimimg.com/upload/vod/20250111-1/07adc1f9c4a2e4746ce4f4fe2bc21e69.jpg', 'https://phimimg.com/upload/vod/20250111-1/7c9381c5c59f63dde0771b33dbc4abba.jpg', '<p>Huyền thoại làng hài khám phá mối quan hệ thầy trò đầy phức tạp giữa Deborah Vance (Jean Smart), một cây hài huyền thoại ở Las Vegas, và một cô gái 25 tuổi khác người (Hannah Einbinder).</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jean Smart","avatar":""},{"name":"Hannah Einbinder","avatar":""},{"name":"Carl Clemons-Hopkins","avatar":""},{"name":"Megan Stalter","avatar":""},{"name":"Paul W. Downs","avatar":""},{"name":"Mark Indelicato","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["老哏新侃","天后与草莓","Полезные советы","Hacks"]', 1784690324316);
