INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-khu-414', 'Đặc Khu 414', 'Zone 414', 'https://phimimg.com/upload/vod/20231125-1/32ecb3c571aa0c501ae3fa8b357eb92d.jpg', 'https://phimimg.com/upload/vod/20231125-1/6bff456237538a6c858f26cc4a0f4bd2.jpg', '<p>Marlon Veidt trở nên giàu có nhờ tạo nên những con robot AI. Để truy tìm con gái mất tích, Marlon Veidt mời thám tử tư David Carmichael tham gia điều tra tại đặc khu 414, nơi robot và con người có thể tương tác. Jane (một AI) bị tấn công bởi các tin nhắn nặc danh cầu cứu Marlon Veidt. Cả hai cùng hỗ trợ để tự giải thoát.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Guy Pearce","avatar":""},{"name":"Matilda Lutz","avatar":""},{"name":"Travis Fimmel","avatar":""},{"name":"Jonathan Aris","avatar":""},{"name":"Colin Salmon","avatar":""},{"name":"Jóhannes Haukur Jóhannesson","avatar":""},{"name":"Ned Dennehy","avatar":""},{"name":"Antonia Campbell-Hughes","avatar":""},{"name":"Olwen Fouéré","avatar":""},{"name":"Maggie Cronin","avatar":""},{"name":"Fionnula Flanagan","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324316);
