INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-le-cua-em', 'Hôn Lễ Của Em', 'My Love', 'https://phimimg.com/upload/vod/20250508-1/01be62f6b7666a6febed27aef8c7bc8b.jpg', 'https://phimimg.com/upload/vod/20231209-1/ff4ebc9bc993697a594d5c1cc0a47793.jpg', '<p>Mười lăm năm, Châu Tiêu Tề luôn giữ trong tim hình bóng của Vưu Vịnh Tử như lần đầu gặp gỡ. Tình yêu thuần khiết thời thanh xuân đưa cả hai trải qua những khoảng thời gian tuyệt đẹp nhất và gian truân nhất của tuổi trẻ. Nhưng tình yêu là thứ khó nắm bắt, sẽ thế nào khi người nắm tay em ở cuối con đường... không phải anh?</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hứa Quang Hán","avatar":""},{"name":"Chương Nhược Nam","avatar":""},{"name":"Lương Tĩnh Khang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324316);
