INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('be-trung-nao-loan-chau-phi', 'Bé Trứng: Náo Loạn Châu Phi', 'Little Eggs: An African Rescue', 'https://phimimg.com/upload/vod/20250508-1/cbbad22444022356cf4eaad5b3b93540.jpg', 'https://phimimg.com/upload/vod/20250508-1/cbc518c4b9c71073be4225388c8ff4fc.jpg', '<p>May mắn trở thành những quả trứng vàng trong làng trang trại, Uly và Max là cặp anh em “được săn đón” và trở thành tầm ngắm của hội sưu tầm đồ độc lạ Châu Phi. Để giải cứu các con, bố mẹ của Uly và Max cùng những người hàng xóm tốt bụng đã có chuyến xuất ngoại “đáng nhớ” với nhiều pha hành động dở khóc dở cười.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Lồng Tiếng', 'FHD', 'Mexico', 0, '[{"name":"Bruno Bichir","avatar":""},{"name":"Maite Perroni","avatar":""},{"name":"Carlos Espejel","avatar":""},{"name":"Angélica Vale","avatar":""},{"name":"Dione Riva Palacio Santacruz","avatar":""},{"name":"Oliver Díaz Barba","avatar":""},{"name":"Mayra Rojas","avatar":""},{"name":"Ariel Miramontes","avatar":""},{"name":"Jesús Ochoa","avatar":""},{"name":"Freddy Ortega","avatar":""},{"name":"Germán Ortega","avatar":""},{"name":"Rodolfo Riva Palacio Alatriste","avatar":""},{"name":"Gabriel Riva Palacio Alatriste","avatar":""},{"name":"Ximena d","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Little Eggs: An African Rescue","La course aux œufs","Bé Trứng: Náo Loạn Châu Phi","Eggs Run","危雞總動員","Rescate en África: Una película de huevos","Un rescate de huevitos"]', 1784690324316);
