INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-xom-cua-toi-khong-chiu-lon', 'Hàng Xóm Của Tôi Không Chịu Lớn', 'My Fated Boy', 'https://phimimg.com/upload/vod/20250505-1/08ec60d3ad37019754a8af97f0d1dddf.jpg', 'https://phimimg.com/upload/vod/20250505-1/dea27cef88786f7cb0b8dabace16754e.jpg', '<p>&quot;Chị già&quot; Lâm Dạng 31 tuổi dù siêng năng làm việc nhưng sự nghiệp vẫn bấp bênh. Lục Chính An, chàng trai trẻ 24 tuổi, thanh mai trúc mã năm xưa của Lâm Dạng, cũng là hàng xóm của cô, vừa trở về nước sau thời gian dài du học. Vì lý do bất đắc dĩ, Lâm Dạng buộc phải để Chính An ở chung với mình và cũng từ đây, cuộc sống của cô bắt đầu có nhiều thay đổi.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Khê Nhuế","avatar":""},{"name":"Hà Dữ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["내 운명의 소년","WDLJZBD","我的鄰居長不大","My Fated Boy","My Neighbor is Not Grown Up","Love Me Like a Child","我的邻居长不大"]', 1784690324316);
