INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-babylon-cua-toi', 'Người Tình Babylon Của Tôi', 'Dear Diary', 'https://phimimg.com/upload/vod/20250504-1/19aa7ef7408036e9600c55208e2c7e33.jpg', 'https://phimimg.com/upload/vod/20250504-1/4448abca5d0b2bd16a134efc5482a3aa.jpg', '<p>Phim kể về Trần Mỹ Như (do Bốc Quan Kim thủ vai), một cô gái lập dị, sống nội tâm và có trí tưởng tượng phong phú. Năm 12 tuổi, cô viết nhật ký về một chàng hoàng tử Babylon hoàn hảo mà cô mơ ước. Vào sinh nhật lần thứ 24, người bạn thân của cô, Khương Huệ Chân (Chu Nhan Mạn Tư), đã sử dụng cuốn nhật ký đó trong một nghi thức tà đạo để &quot;troll&quot; bạn mình. Không ngờ, nghi thức này vô tình triệu hồi hoàng tử Babylon (Phượng Tiểu Nhạc) từ quá khứ 3.700 năm trước. Từ đây, Mỹ Như bị cuốn vào một cuộc phiêu lưu xuyên không đầy rắc rối, nơi các nhân vật trong trí tưởng tượng tuổi thơ của cô lần lượt xuất hiện, tạo nên những tình huống dở khóc dở cười.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bốc Quan Kim","avatar":""},{"name":"Phượng Tiểu Nhạc","avatar":""},{"name":"Hứa Vỹ Ninh","avatar":""},{"name":"Chu Du","avatar":""},{"name":"Vương Thụy Xương","avatar":""},{"name":"Chu Nhan Mạn Tư","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["我的巴比伦","爱在三千七百多年前","Ai在西元前","我的巴比伦恋人","WDBBLLR"]', 1784690324316);
