INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-tinh-babylon-cua-toi', 'Người Tình Babylon Của Tôi', 'Dear Diary', 'người tình babylon của tôi dear diary bốc quan kim phượng tiểu nhạc hứa vỹ ninh chu du vương thụy xương chu nhan mạn tư 我的巴比伦 爱在三千七百多年前 ai在西元前 我的巴比伦恋人 wdbbllr', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-trai-nha-doi-dien', 'Anh Trai Nhà Đối Diện', 'Sweet Sweet', 'https://phimimg.com/upload/vod/20250504-1/ba889596040949547bc2f00ab1cb60ab.jpg', 'https://phimimg.com/upload/vod/20250504-1/2bd73de9dac178836dc87d51840b8b88.jpg', '<p>Trong một lần thử nghiệm, máy bay không người lái của Tô Mộ bay vào nhà Điền Điềm. Tưởng không có ai ở nhà nên anh trèo tường vào tìm, kết quả bị Điền Điềm đang tắm bắt ngay tại trận. Trùng hợp thay, chỉ có kem do Điền Điềm tự làm mới có thể khiến Tô Mộ vui vẻ, nói năng trôi chảy. Vì muốn ăn kem do Điền Điềm làm, Tô Mộ chuyển đến ở đối diện nhà cô, từ đó quan hệ của hai người có bước tiến mới.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 8, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Dịch Khâm","avatar":""},{"name":"Đinh Nhất Nhất","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["住我对面的小哥哥","住我對面的小哥哥","The Little Brother Who Lives Across From Me","Zhu Wo Dui Mian De Xiao Ge Ge","Sweet Sweet","스윗스윗","ZWDMDXGG","주아대면적소가가 : 달달한 이웃","Моя милая соседка, живущая напротив"]', 1784690324316);
