INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-guom-diet-quy-phan-3-ky-vien-tran', 'Thanh Gươm Diệt Quỷ (Phần 3) (Kỹ Viện Trấn)', 'Demon Slayer (Season 3) (Entertainment District Arc)', 'https://phimimg.com/upload/vod/20240302-1/495167573eb3f65d09652933e64327c0.jpg', 'https://phimimg.com/upload/vod/20250427-1/ba01d82e006a7d9c2fb3aca49a0a8b1e.jpg', '<p>Nhiều phụ nữ ở phố đèn đỏ Yoshiwara, nơi có nhiều quỷ dữ và tội phạm hoành hành nhất, mất tích một cách bí ẩn. Lần này, Tanjirou, Zenitsu và Inosuke với sự hỗ trợ của Âm Trụ sẽ đến Yoshiwara để bảo vệ con người và tiêu diệt quỷ nữ đang làm mưa làm gió tại nơi đây.</p>', 'Full', 11, 'hoathinh', 'completed', 5, 2021, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Hanae Natsuki","avatar":""},{"name":"Kito Akari","avatar":""},{"name":"Shimono Hiro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324316);
