INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-guom-diet-quy-phan-2-chuyen-tau-vo-tan', 'Thanh Gươm Diệt Quỷ (Phần 2) (Chuyến Tàu Vô Tận)', 'Demon Slayer (Season 2) (Mugen Train Arc)', 'https://phimimg.com/upload/vod/20240709-1/e79b6aaa75300e7424ca41500980cbe2.jpg', 'https://phimimg.com/upload/vod/20250427-1/d58646e693f31b0775f0fec0b3ea9461.jpg', '<p>Nhóm của Tanjirou được giao cho nhiệm vụ tiêu diệt con quỷ trên Chuyến Tàu Vô Tận cùng Viêm Đại Trụ Rengoku. Hành trình bất ngờ không những khiến Tanjirou phải đối mặt với sự dằn vặt về cuộc sống yên bình cậu đã đánh mất, mà còn hé lộ những bí mật về sức mạnh và tiềm lực thực sự của bản thân.</p>', 'Hoàn Tất (7/7)', 7, 'hoathinh', 'completed', 7, 2021, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Natsuki Hanae","avatar":""},{"name":"Akari Kitō","avatar":""},{"name":"Hiro Shimono","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324316);
