INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-tre-trong-le-shiva', 'Đứa Trẻ Trong Lễ Shiva', 'Shiva Baby', 'https://phimimg.com/upload/vod/20250424-1/4b30c38fb4a08517b4d0b0bfb013eb6a.jpg', 'https://phimimg.com/upload/vod/20250424-1/aee5954a0cda33251213d60e9fd163c9.jpg', '<p>Nữ sinh đại học Danielle phải tìm cách che giấu mọi chuyện khi bất ngờ chạm mặt “sugar daddy” của mình tại một buổi lễ tang theo nghi thức Do Thái (shiva) – nơi có mặt cả bố mẹ, bạn gái cũ và bạn bè gia đình cô.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rachel Sennott","avatar":""},{"name":"Molly Gordon","avatar":""},{"name":"Polly Draper","avatar":""},{"name":"Danny Deferrari","avatar":""},{"name":"Fred Melamed","avatar":""},{"name":"Dianna Agron","avatar":""},{"name":"Glynis Bell","avatar":""},{"name":"Sondra James","avatar":""},{"name":"Deborah Offner","avatar":""},{"name":"Rita Gardner","avatar":""},{"name":"Jackie Hoffman","avatar":""},{"name":"Vivien Landau","avatar":""},{"name":"Cilda Shaur","avatar":""},{"name":"Richard Brundage","avatar":""},{"name":"Noemie Zysermann","avatar":""},{"name":"Ted Seligman","avatar":""},{"name":"Edgar Harmanci","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["시바 베이비","Помен по еврейски","Danielle és a süvet","Шалом, папик!","Şiva Bebeği","Shiva Baby"]', 1784690324316);
