INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dua-tre-trong-le-shiva', 'Đứa Trẻ Trong Lễ Shiva', 'Shiva Baby', 'đứa trẻ trong lễ shiva shiva baby rachel sennott molly gordon polly draper danny deferrari fred melamed dianna agron glynis bell sondra james deborah offner rita gardner jackie hoffman vivien landau cilda shaur richard brundage noemie zysermann ted seligman edgar harmanci 시바 베이비 помен по еврейски danielle és a süvet шалом, папик! şiva bebeği shiva baby', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-quan-ca', 'Dữ Quân Ca', 'Dream Of Chang An', 'https://phimimg.com/upload/vod/20231007-1/f95a59b4ee2c49ca3808dd7050347cc4.jpg', 'https://phimimg.com/upload/vod/20231007-1/06c5917841cf7fad05cba2809d53938d.jpg', '<p>Dữ Quân Ca được chuyển thể từ tiểu thuyết Kiếm Khí Hành của tác giả Phi Hoa, kể về cuộc hội ngộ định mệnh của hai chị em sinh đôi Trường Nhược Ngư (Trương Dư Hi) và Cừu Uyên Chức (Tuyên Lộ). Thời đại vua Đường Văn Tông, thiên hạ đại loạn, ngoại thích và hoạn quan nắm giữ triều chính. Tể tướng Vương Nhai và gia quyến bị xử trảm, chỉ trừ cặp chị em song sinh may mắn tìm được đường sống. Vận mệnh trớ trêu, cả hai gặp lại nhau trong tình trạng hai phe đối địch. Trường Nhược Dư, Cừu Uyên Đức, Lý Viêm (Thành Nghị) và Quang Vương (Hàn Đổng) cùng bị cuốn vào phong vân của triều đình, dần lột xác và trưởng thành tại khoảng thời gian tối tăm nhất của triều Đường.</p>', 'Hoàn tất (49/49)', 49, 'series', 'completed', 5, 2021, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Tuyên Lộ","avatar":""},{"name":"Trương Dư Hi","avatar":""},{"name":"Thành Nghị","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324316);
