INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoang-tau-so-6', 'Khoang Tàu Số 6', 'Compartment No. 6 / Compartment Number 6', 'https://phimimg.com/upload/vod/20250420-1/1efc244896bbfcc1a2ee94351cecc6f9.jpg', 'https://phimimg.com/upload/vod/20250420-1/c1c159f903a895410916a5cefd96f19d.jpg', '<p>&quot;Compartment Number 6&quot; (tựa gốc: &quot;Hytti nro 6&quot;) là một bộ phim chính kịch dựa trên tiểu thuyết cùng tên năm 2011 của Rosa Liksom. Câu chuyện kể về một cô gái trẻ người Phần Lan rời bỏ mối tình bí ẩn ở Moscow bằng cách lên tàu đến cảng Bắc Cực Murmansk. Cô chia sẻ khoang tàu với một thợ mỏ người Nga cục mịch, và cuộc gặp gỡ bất ngờ này dẫn họ đối diện với sự thật lớn về kết nối giữa con người. Phim nhận được nhiều lời khen ngợi từ giới phê bình và đoạt giải Grand Prix tại Liên hoan phim Cannes 2021. Đây cũng là bộ phim Phần Lan được đề cử cho giải Phim quốc tế hay nhất tại Giải Oscar lần thứ 94.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Seidi Haarla","avatar":""},{"name":"Yura Borisov","avatar":""},{"name":"Dinara Drukarova","avatar":""},{"name":"Yuliya Aug","avatar":""},{"name":"Lidiya Kostina","avatar":""},{"name":"Tomi Alatalo","avatar":""},{"name":"Viktor Chuprov","avatar":""},{"name":"Sergey Agafonov","avatar":""},{"name":"Nadezhda Kulakova","avatar":""},{"name":"Denis Pyanov","avatar":""},{"name":"Polina Aug","avatar":""},{"name":"Natalia Drozd","avatar":""},{"name":"Konstantin Murzenko","avatar":""},{"name":"Konstantin Shavlovsky","avatar":""},{"name":"Stasya Grankovskaya","avatar":""},{"name":"Vyachesla","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Przedział nr 6","Sovekupé nr 6","Kupe br. 6","Купе номер шесть","Купэ нумар шэсць","Scompartimento n. 6 - In viaggio con il destino","六号包厢","Kupé nummer 6","A 6-os számú fülke","Купе номер шість","Compartment Number 6","6번 칸","6번칸","コンパートメント No.6","Hytti nro 6"]', 1784690324316);
