INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khoang-tau-so-6', 'Khoang Tàu Số 6', 'Compartment No. 6 / Compartment Number 6', 'khoang tàu số 6 compartment no. 6 / compartment number 6 seidi haarla yura borisov dinara drukarova yuliya aug lidiya kostina tomi alatalo viktor chuprov sergey agafonov nadezhda kulakova denis pyanov polina aug natalia drozd konstantin murzenko konstantin shavlovsky stasya grankovskaya vyachesla przedział nr 6 sovekupé nr 6 kupe br. 6 купе номер шесть купэ нумар шэсць scompartimento n. 6 - in viaggio con il destino 六号包厢 kupé nummer 6 a 6-os számú fülke купе номер шість compartment number 6 6번 칸 6번칸 コンパートメント no.6 hytti nro 6', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truoc-them-nam-moi', 'Trước Thềm Năm Mới', 'New Year Blues', 'https://phimimg.com/upload/vod/20231129-1/0a2556d28cb091d47d5e398e00a7b3c5.jpg', 'https://phimimg.com/upload/vod/20231129-1/118982b9a222410121b7ea070df75c40.jpg', '<p>Bộ phim là một câu chuyện tình yêu của bốn cặp đôi trong tuần trước khi năm mới.&nbsp; Ji Ho từng là thám tử trong một đội tội phạm nghiêm trọng. Anh bị giáng chức và làm việc tại một văn phòng dịch vụ dân sự nói. Hyo Young là một huấn luyện viên phục hồi chức năng. Cô đang làm thủ tục ly hôn. Cô đến văn phòng dịch vụ dân sự để yêu cầu một lệnh cấm. Ji Ho tình cờ bảo vệ Hyo Young khỏi chồng cô.&nbsp; Jae Hun mệt mỏi với cuộc sống. Anh đến Argentina và hiện đang làm công việc giao rượu. Anh tình cờ gặp Jin A . Jin A đã bị bạn trai của cô ấy ruồng bỏ. Cô đến Argentina và bắt đầu làm việc tại một khu nghỉ mát trượt tuyết.&nbsp; Yong Chan điều hành một công ty du lịch. Anh sắp kết hôn với Yaolin, một người Trung Quốc, nhưng anh có một vấn đề lớn. Yong Chan đã bị lừa vì tiền cho cuộc hôn nhân của mình. Yaolin được chỉ định đến một chi nhánh Hàn Quốc, trước khi họ kết hôn. Chị gái của Yong Chan là Yong Mi không cảm thấy thoải mái khi Yong Chan sẽ kết hôn với một người nước ngoài.&nbsp; Rae Hwan là một tuyển thủ quốc gia trong thế vận hội Paralympic. Anh luôn cảm thấy có lỗi với bạn gái Oh Wol, người vì anh mà phải đối mặt với định kiến của mọi người.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Kang-woo","avatar":""},{"name":"Yu In-na","avatar":""},{"name":"Yoo Yeon-seok","avatar":""},{"name":"Lee Yeon-hee","avatar":""},{"name":"Lee Dong-hwi","avatar":""},{"name":"Chen Duling","avatar":""},{"name":"Yeom Hye-ran","avatar":""},{"name":"Choi Soo-young","avatar":""},{"name":"Teo Yoo","avatar":""},{"name":"Ye Su-jeong","avatar":""},{"name":"Kim Kwang-kyu","avatar":""},{"name":"Nam Bo-ra","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Oh Sang-jin","avatar":""},{"name":"Jo Han-chul","avatar":""},{"name":"Ahn Se-ha","avatar":""},{"name":"Ponchy Brusse","avatar":""},{"name":"Song Sang-eun","avatar":""},{"name":"Lee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324316);
