INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dieu-tra-ky-an-truong-ky', 'Đội Điều Tra Kỳ Án Trường Kỳ', 'SIGNAL: The Movie – Cold Case Investigation Unit', 'https://phimimg.com/upload/vod/20250419-1/ce9f177ff6ec2a0dbf75df9eaf3a2eb9.jpg', 'https://phimimg.com/upload/vod/20250419-1/152c151b9447db304118bae691f64536.jpg', '<p>Câu chuyện tiếp tục từ loạt phim truyền hình &quot;Signal&quot;. Saegusa Kento và Sakurai Misaki đến nơi Oyama Takeshi đang ở hiện tại.</p>', 'Full', 1, 'single', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kentaro Sakaguchi","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"Michiko Kichise","avatar":""},{"name":"Yuichi Kimura","avatar":""},{"name":"Tetsuhiro Ikeda","avatar":""},{"name":"Kaede Aono","avatar":""},{"name":"Tsuyoshi Ihara","avatar":""},{"name":"Tetsushi Tanaka","avatar":""},{"name":"Tetta Sugimoto","avatar":""},{"name":"Takeshi Kaga","avatar":""},{"name":"Nao","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gekijoban Signal: Choki Mikaiketsu Jiken Sosahan","Gekijōban Signal: Chōki Mikaiketsu Jiken Sōsahan","SIGNAL: The Movie","剧场版 信号 长期未解决事件搜查组","Gekijōban Signal","SIGNAL: Long-Term Unsolved Case Investigation – The Movie","Gekijōban Shigunaru: Chōki Mikaiketsu Jiken Sōsahan","Gekijôban: Signal","SIGNAL: The Movie –Cold Case Investigation Unit–","SIGNAL The Movie Cold Case Investigation Unit","SIGNAL: The Movie: Cold Case Investigation Unit","Signal：The Movie","劇場版 シグナル 長期未解決事件捜査班"]', 1784690324316);
