INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-dieu-tra-ky-an-truong-ky', 'Đội Điều Tra Kỳ Án Trường Kỳ', 'SIGNAL: The Movie – Cold Case Investigation Unit', 'đội điều tra kỳ án trường kỳ signal: the movie – cold case investigation unit kentaro sakaguchi kazuki kitamura michiko kichise yuichi kimura tetsuhiro ikeda kaede aono tsuyoshi ihara tetsushi tanaka tetta sugimoto takeshi kaga nao gekijoban signal: choki mikaiketsu jiken sosahan gekijōban signal: chōki mikaiketsu jiken sōsahan signal: the movie 剧场版 信号 长期未解决事件搜查组 gekijōban signal signal: long-term unsolved case investigation – the movie gekijōban shigunaru: chōki mikaiketsu jiken sōsahan gekijôban: signal signal: the movie –cold case investigation unit– signal the movie cold case investigation unit signal: the movie: cold case investigation unit signal：the movie 劇場版 シグナル 長期未解決事件捜査班', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-chau-phu-nhan', 'Hộc Châu Phu Nhân', 'Novoland: Pearl Eclipse', 'https://phimimg.com/upload/vod/20250418-1/300c21d5d6e041d33e0dac2fb8d557bb.jpg', 'https://phimimg.com/upload/vod/20250418-1/81e1ddfa80ea3d5009e5cf555a4cb703.jpg', '<p>Năm Thiên Hưởng Đại Trưng, thuế ngọc nặng nề. Để gom ngọc nộp cho triều đình, cha để Diệp Hải Thị lặn xuống biển, đến trước mặt giao nhân. Giao nhân Lang Hoàn tặng cho Hải Thị một hộc ngọc giao, tên quan gian ác thấy ngọc giao thượng hạng nên giết hết cả làng để cướp ngọc. Vào thời khắc hiểm nguy, Phương Chư đã xuất hiện và cứu lấy Hải Thị. Diệp Hải Thị bái Phương Chư làm sư phụ, đổi tên thành Phương Hải Thị, trở thành đồ đệ thứ hai của Phương Chư, từ đó sống trong thân phận nam nhi. Trong những năm đi theo Phương Chư, Phương Hải Thị học được nhiều điều, có bản lĩnh bảo vệ nền hòa bình của Đại Trưng, lập nhiều chiến công. Cô nảy sinh tình cảm với Phương Chư vì đã cùng nhau trải qua bao phen sinh tử, song Phương Chư không thể đáp lại do vẫn mang sứ mệnh bảo vệ Đế Húc và Đại Trưng. Sau đó, Phương Hải Thị bị vạch trần thân phận nữ nhi, Phương Chư đành đưa cô đến bên Đế Húc để bảo vệ cô, giữa ba người không ngừng xảy ra những vướng mắc tình cảm.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Mịch","avatar":""},{"name":"Trần Vỹ Đình","avatar":""},{"name":"Từ Khai Sính","avatar":""},{"name":"Trần Tiểu Vân","avatar":""},{"name":"Vương Sâm","avatar":""},{"name":"Viên Vũ Huyên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["九州·斛珠夫人","斛珠夫人"]', 1784690324316);
