INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-lop-vo-boc', 'Dưới Lớp Vỏ Bọc', 'Ugly Beauty', 'https://phimimg.com/upload/vod/20250416-1/24eaf4ca000a748594d92d0bec6c7991.jpg', 'https://phimimg.com/upload/vod/20250416-1/a7e405234042f1a1e154d0c6e4a9f535.jpg', '<p>Bộ phim Dưới Lớp Vỏ Bọc - Ugly Beauty kể về câu chuyện hồi hộp về tình yêu của một cặp chị em sinh đôi giống hệt nhau làm việc trong ngành giải trí. Tiêu Mộ đã thay thế danh tính của em gái mình là Diêu Mộng Quy từ một người bình thường trở thành một diễn viên. Tiêu Mộ bị nhiều người nghi ngờ, cô đã ẩn náu bên cạnh Trần Mặc làm nhân viên điều hành.

Khi Tiêu Mộ dần dần thích nghi với cuộc sống của người nghệ sĩ và dần dần trở nên tình cảm với nam chính Trần Mặc, Diêu Mộng Quy bất ngờ trở lại. Cuối cùng, Trần Mặc đã chọn phơi bày hay bảo vệ người yêu của mình? Liệu Tiêu Mộ có tiếp tục dựa vào làn da để trở thành cái bóng của em gái mình không? Và ai là kẻ thao túng thực sự đằng sau chuyện này?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zheng Hehuizi","avatar":""},{"name":"Huang Shengchi","avatar":""},{"name":"Hu Wenzhe","avatar":""},{"name":"Tai Yawen","avatar":""},{"name":"Zheng Miao","avatar":""},{"name":"Li Dianzun","avatar":""},{"name":"Yan Luhan","avatar":""},{"name":"Gu Tianyi","avatar":""},{"name":"Yu Weini","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Ugly Beauty","皮囊之下"]', 1784690324316);
