INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noc-doc-vang-phan-1', 'Nọc Độc Vàng (Phần 1)', 'Yellowjackets (Season 1)', 'https://phimimg.com/upload/vod/20231207-1/302715dc6d4cfc4e13cfe0a6aa01db79.jpg', 'https://phimimg.com/upload/vod/20231207-1/b6dfd52279792a7246f3c8ed50e4beb3.jpg', '<p>Câu chuyện về một nhóm các nữ sinh trung học tài năng điên cuồng, những người đã trở thành người may mắn sống sót sau một vụ tai nạn máy bay sâu trong vùng hoang dã xa xôi phía Bắc. Họ sẽ phải cùng nhau sinh tồn, tạo nên một cuộc sống mới tại vùng đất hoang sơ và hẻo lánh này.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Christina Ricci","avatar":""},{"name":"Juliette Lewis","avatar":""},{"name":"Tawny Cypress","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324316);
