INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-gian-huyen-ao-tan-truyen', 'Nhân Gian Huyền Ảo Tân Truyện', 'A Traditional New Story Of Taiwan', 'https://phimimg.com/upload/vod/20250413-1/666956a78d58789846967b828f745664.jpg', 'https://phimimg.com/upload/vod/20250413-1/b9bc472212119710d6b57288d815abf2.jpg', '<p>&quot;Nhân Gian Huyền Ảo Tân Truyện&quot; là một series phim truyền hình cổ trang huyền ảo nổi tiếng với những câu chuyện mang yếu tố liêu trai chí dị, đan xen yếu tố thần thoại và tâm linh. Nội dung phim thường xoay quanh các câu chuyện kỳ bí, những mối oan tình chưa được giải quyết, cuộc chiến giữa thiện và ác, và những bài học nhân văn sâu sắc. Mỗi tập phim thường là một câu chuyện độc lập, có mở đầu và kết thúc rõ ràng, nhưng vẫn giữ được mạch truyện chung của series.</p>', 'Hoàn Tất (577/577)', 577, 'series', 'completed', 15, 2021, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Lâm Dung Hạo","avatar":""},{"name":"Trần Uy Hàn","avatar":""},{"name":"Trương Phong Kỳ","avatar":""},{"name":"Trần Tử Huyền","avatar":""},{"name":"Trần Thủy Tiên","avatar":""},{"name":"Cao Tử Linh","avatar":""},{"name":"Lý Tường","avatar":""},{"name":"Nguyên Lục","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["炎炎消防队 叁之章","炎炎消防队 贰之章","炎炎消防队 壹之章","Fire Force","En''en no Shouboutai","Enn Enn no Shōbōtai","Enen no Shouboutai","Enen no Shouboutai: Ni no Shou","Enen no shôbôtai","En''en no Shouboutai Ni no Shou","Enn Enn no Shouboutai","Enen no Shōbōtai","Enen No Shouboutai - Ni no Shou","炎炎ノ消防隊 弐ノ章","炎炎ノ消防隊 参ノ章","Enen no Shouboutai San","Пламенная бригада пожарных","Пламенный отряд","Огненная бригада пожарных!","Огненная бригада","炎炎消防隊 貳之章","炎炎消防隊 參之章","Fire Brigade of Flames","Fireforce","Blazing Fire Brigade","Bộc Hỏa Nhân Tượng","炎炎ノ消防隊"]', 1784690324316);
