INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhan-gian-huyen-ao-tan-truyen', 'Nhân Gian Huyền Ảo Tân Truyện', 'A Traditional New Story Of Taiwan', 'nhân gian huyền ảo tân truyện a traditional new story of taiwan lâm dung hạo trần uy hàn trương phong kỳ trần tử huyền trần thủy tiên cao tử linh lý tường nguyên lục 炎炎消防队 叁之章 炎炎消防队 贰之章 炎炎消防队 壹之章 fire force en''en no shouboutai enn enn no shōbōtai enen no shouboutai enen no shouboutai: ni no shou enen no shôbôtai en''en no shouboutai ni no shou enn enn no shouboutai enen no shōbōtai enen no shouboutai - ni no shou 炎炎ノ消防隊 弐ノ章 炎炎ノ消防隊 参ノ章 enen no shouboutai san пламенная бригада пожарных пламенный отряд огненная бригада пожарных! огненная бригада 炎炎消防隊 貳之章 炎炎消防隊 參之章 fire brigade of flames fireforce blazing fire brigade bộc hỏa nhân tượng 炎炎ノ消防隊', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-giang-ho-chi-bat-luong-nhan-phan-4', 'Họa giang hồ chi bất lương nhân (Phần 4)', 'A Portrait of Jianghu: Bad Guys (Season 4) / Hua Jiang Hu Zhi Bu Liang Ren 4', 'https://phimimg.com/upload/vod/20250412-1/a940cd4b8ce04efb049614c1cacc710c.jpg', 'https://phimimg.com/upload/vod/20250412-1/73945dacd3e90ad72d11a338fe09d8c5.jpg', '<p>Lý Tinh Vân bị quân Lương bao vây, Lục Lâm Hiên dùng tính mạng để đánh cược với Chu Hữu Trinh, cuối cùng giành chiến thắng sít sao, tạo cơ hội cho Chung Tiểu Quỳ đưa Trương Tử Phàm rời khỏi doanh trại quân Lương. Khi Chu Hữu Trinh trừng phạt Chung Tiểu Quỳ, Lý Tinh Vân – người bị bỏ lại ở doanh trại đã bất ngờ tỉnh lại sau hôn mê. Trên đài điểm tướng, Lý Tồn Húc giết kẻ đóng giả Chu Hữu Trinh để nâng cao sĩ khí. Trong Thông Văn Quán, Tấn vương Lý Khắc Dụng đang đánh cờ và trò chuyện cùng một nữ tử về tung tích của Ôn Thao và Long Tuyền kiếm.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Bian","avatar":""},{"name":"Mengmeng Yan","avatar":""},{"name":"Zhao Yi","avatar":""},{"name":"Qiuxiang Shen","avatar":""},{"name":"Jun Chu","avatar":""},{"name":"Shuren Zhao","avatar":""},{"name":"Xuecen Bai","avatar":""},{"name":"Lu Zhixing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["画江湖之不良人动画版","Huajianghu Bu Liang Ren","Buliang Ren VI","画江湖之不良人Ⅴ","Buliang Ren II","Buliang Ren V","Buliang Ren III","Buliang Ren IV","Buliang Ren","Drawing Jianghu Of Bu Liang Ren Ⅵ","Drawing Jianghu of Bu Liang Ren","Hua Jiang Hu Zhi Bu Liang Ren","The Degenerate-Drawing Jianghu","画江湖之不良人II","画江湖之不良人第七季：九幽玄天","画江湖之不良人","畫江湖之不良人","A Portrait of Jianghu Bad Guys","A Portrait of Jianghu : Bad Guys"]', 1784690324316);
