INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-giang-ho-chi-bat-luong-nhan-phan-4', 'Họa giang hồ chi bất lương nhân (Phần 4)', 'A Portrait of Jianghu: Bad Guys (Season 4) / Hua Jiang Hu Zhi Bu Liang Ren 4', 'họa giang hồ chi bất lương nhân (phần 4) a portrait of jianghu: bad guys (season 4) / hua jiang hu zhi bu liang ren 4 jiang bian mengmeng yan zhao yi qiuxiang shen jun chu shuren zhao xuecen bai lu zhixing 画江湖之不良人动画版 huajianghu bu liang ren buliang ren vi 画江湖之不良人ⅴ buliang ren ii buliang ren v buliang ren iii buliang ren iv buliang ren drawing jianghu of bu liang ren ⅵ drawing jianghu of bu liang ren hua jiang hu zhi bu liang ren the degenerate-drawing jianghu 画江湖之不良人ii 画江湖之不良人第七季：九幽玄天 画江湖之不良人 畫江湖之不良人 a portrait of jianghu bad guys a portrait of jianghu : bad guys', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-xoay-tinh-yeu', 'Vòng Xoáy Tình Yêu', 'Love Twist', 'https://phimimg.com/upload/vod/20250412-1/44d81968c0844953824cf7d4e09af17c.jpg', 'https://phimimg.com/upload/vod/20250412-1/abbb183587db3282461ef3ed2ad6b16d.jpg', '<p>Phim kể lại câu chuyện của ba gia đình với những hoàn cảnh khác nhau. Oh So Ri được sinh ra trong một gia đình giàu có. Ngược lại, Park Hee Ok cũng xuất thân từ một gia đình giàu có, nhưng cuộc sống bên Mỹ cùng với người chồng cũ lại không hề tốt đẹp chút nào. Bà gửi con trai Park Ha Roo về và nhờ Ok Hee nuôi nấng. Ha Roo học hành rất tốt, anh rời khỏi nhà họ Oh khi đã có thể tự chủ tài chính. Anh thích Oh So Ri từ khi còn nhỏ nhưng không dám bày tỏ lòng mình, trong khi So Ri không chỉ tỏ tình mà còn cố gắng học hành để được học chung trường đại học với Ha Roo.</p>', 'Hoàn Tất (103/103)', 103, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hahm Eun-jung","avatar":""},{"name":"Kim Jin-yeop","avatar":""},{"name":"Hwang Shin-hye","avatar":""},{"name":"Yoon Da-hoon","avatar":""},{"name":"Shim Hye-jin","avatar":""},{"name":"Son Sung-yoon","avatar":""},{"name":"Jang Se-hyun","avatar":""},{"name":"Park Hye-jin","avatar":""},{"name":"Yoo Tae-woong","avatar":""},{"name":"Oh Young-shil","avatar":""},{"name":"Kim Ju-ri","avatar":""},{"name":"Lee Soo-young","avatar":""},{"name":"Park Jae-joon","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad