INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-sinh-so-11', 'Nam Sinh Số 11', 'The Child Who Would Not Come', 'https://phimimg.com/upload/vod/20250412-1/e97757cc2db1485f953d7172eb73e974.jpg', 'https://phimimg.com/upload/vod/20250412-1/bd8712982e8d881212f6c2b581ac6064.jpg', '<p>Trong một buổi điểm danh trước khi vào lớp học, giáo viên thực tập Su-ah phát hiện một nam sinh không bao giờ đến lớp. Su-ah quyết định tìm đến và thuyết phục nam sinh nhanh chóng trở lại trường nhưng cô không ngờ tai họa từ đó ập tới. Không có học sinh nào trong trường chào đón sự trở lại của cậu ta và tệ hơn là những chuyện kỳ quái liên tục xảy ra đe dọa đến mạng sống của nhiều người.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Kim So-hye","avatar":""},{"name":"Jung Yoon-suk","avatar":""},{"name":"Lee Gyu-hyeon","avatar":""},{"name":"Yoo Na-gyeol","avatar":""},{"name":"Karin","avatar":""},{"name":"Yeonge","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nam Sinh Số 11","오지않는 아이","Strange School Tales: The Child Wouldn’t come","학교기담-오지 않는 아이"]', 1784690324316);
