INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-vo-hoan-hao', 'Người Vợ Hoàn Hảo', 'The All-Round Wife', 'https://phimimg.com/upload/vod/20250410-1/2beb8b4779fb5653c1b56ce0d337abf3.jpg', 'https://phimimg.com/upload/vod/20250410-1/0846a3414c8b39dea9c716009f29a90b.jpg', '<p>Bộ phim kể về Seo Cho Hee và chồng của cô ấy là Kang Nam Goo. Cho Hee là một người vợ đã dành cả đời nỗ lực để mua một căn nhà ở Gangnam vì mục đích học hành của con gái. Mặc dù nỗ lực chuyển đến Gangnam để có chất lượng cuộc sống tốt hơn, nhưng cô lại thấy mình lạc lõng do giá nhà đất liên tục tăng.</p>', 'Hoàn Tất (122/122)', 122, 'series', 'completed', 7, 2021, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Jae-In","avatar":""},{"name":"Shim Ji-ho","avatar":""},{"name":"Han Da-gam","avatar":""},{"name":"Han Sang-jin","avatar":""},{"name":"Kim Jae-in","avatar":""},{"name":"Shin Seung-hwan","avatar":""},{"name":"Geum Bo-ra","avatar":""},{"name":"Shin Hyun-tak","avatar":""},{"name":"Yang Mi-kyung","avatar":""},{"name":"Cho Eun-sook","avatar":""},{"name":"Yoon Da-young","avatar":""},{"name":"Jung Bo-min","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["国家代表妻子","The All-Round Wife","국가대표 와이프","National Representative''s Wife","Guggadaepyo Waipeu","Gukgadaepy Waipeu","National Wife","National Team Wife","일일연속극 국가대표 와이프"]', 1784690324316);
