INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diet-slime-suot-300-nam-toi-level-max-luc-nao-chang-hay-phan-1', 'Diệt Slime Suốt 300 Năm, Tôi Level Max Lúc Nào Chẳng Hay (Phần 1)', 'I''ve Been Killing Slimes For 300 Years And Maxed Out My Level (Season 1)', 'diệt slime suốt 300 năm, tôi level max lúc nào chẳng hay (phần 1) i''ve been killing slimes for 300 years and maxed out my level (season 1) aoi yuki kaede hondo sayaka senbongi minami tanaka sayaka harada manami numakura riho sugiyama azumi waki yukari tamura slime taoshite 300-nen 持续狩猎史莱姆三百年，不知不觉就练到lv max 打了三百年的史莱姆，不知不觉就练到了满等 打了三百年的史莱姆，不知不觉就练到了满级 打了300年的史莱姆，不知不觉就练到了满级 ～其二～ slime300 la sorcière invincible tueuse de slime depuis 300 ans tanpa sadar levelku mentok setelah membasmi slime selama 300 tahun slime taoshite 300-nen, shiranai uchi ni level max ni nattemashita slime taoshite 300 slime taoshite 300nen shiranai uchi ni level max ni nattemashita sono ni 슬라임을 잡으면서 300년, 모르는 사이에 레벨max가 되었습니다 я 300 лет убивала слизь и прокачалась на максимум убивая слизней триста лет, сама того не заметив, я достигла максимального уровня убивая слизней 300 лет, сама того не заметив, я достигла максимального уровня diệt slime suốt 300 năm, tôi level max lúc nào chẳng hay スライム倒して300年、知らないうちにレベルmaxになってました', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-xa-dieu-cuu-am-bach-cot-trao', 'Anh Hùng Xạ Điêu: Cửu Âm Bạch Cốt Trảo', 'The Legend Of The Condor Heroes: The Cadaverous Claws', 'https://phimimg.com/upload/vod/20240205-1/8e61edc15cbf7e58718deca942c25d22.jpg', 'https://phimimg.com/upload/vod/20240205-1/4d5eecef55511ed3f81eb2f4b035ff67.jpg', '<p>Phim&nbsp;được cải biên từ bộ tiểu thuyết &quot;Anh Hùng Xạ Điêu&quot; của Kim Dung với nhiều tình tiết mới. Mai Siêu Phong từng là cô gái lang thang không cha mẹ, được Hoàng Dược Sư nhận làm đồ đệ, sau đó cùng các sư huynh luyện võ trên đảo Đào Hoa. Dần dần, nữ đồ đệ nảy sinh tình cảm với sư phụ. Nhận ra điều đó, Hoàng Dược Sư kiếm cớ cùng vợ mình là Phùng Hành rời khỏi đảo, để rồi hai năm sau, vợ chồng ông quay trở về với một nửa quyển Cửu Âm Chân Kinh.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Nghiêm Khoan","avatar":""},{"name":"Nguyễn Cự","avatar":""},{"name":"Genden Phuntsok","avatar":""},{"name":"Uông Tiểu Mẫn","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324316);
