INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-cool-ngau', 'Thế Giới Cool Ngầu', 'The Coolest World', 'https://phimimg.com/upload/vod/20250410-1/a98c3268a8515dfdc3659d3118c4438f.jpg', 'https://phimimg.com/upload/vod/20250410-1/0744944a5ef1c5fa8e7db227515e0603.jpg', '<p>Bộ phim Thế Giới Cool Ngầu kể về cô gái tầm thường Đằng Tiểu Tiểu ở toà soạn tạp chí cố gắng làm việc vì Giải Pulitzer, đột nhiên lại bị công ty truyền thông mới Yo thu mua, bắt đầu làm lại từ vị trí thực tập sinh. Trong thế giới đang biến hoá nhanh chóng, đối diện với tranh đấu và dung hợp của truyền thông truyền thống và thế hệ truyền thông mới Đằng Tiểu Tiểu không ngừng tiến lên, trải qua sự trưởng thành, cuối cùng thu hoạch được tình yêu và sự nghiệp.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Châu Vũ Đồng","avatar":""},{"name":"Lý Hoành Nghị","avatar":""},{"name":"Vương Đông","avatar":""},{"name":"Trần Cẩn Như","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["这世界好酷","这个世界很酷","ZJDSJ","가장 멋진 세상","最酷的世界"]', 1784690324316);
