INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-trai-tim-toa-sang', 'Khi Trái Tim Tỏa Sáng', 'The Moment The Heart Shines', 'https://phimimg.com/upload/vod/20250409-1/61e55d772ec9f3d76563937d66211a60.jpg', 'https://phimimg.com/upload/vod/20250409-1/0f8abbe8bf967cb5a2f65a9d3cad740d.jpg', '<p>Một bộ phim giáo dục về kỹ năng số (digital literacy), cổ vũ tinh thần của giới trẻ thời nay – những người đang sống trong thế giới kỹ thuật số, nơi giá trị của một người được đánh giá qua số lượng “tim” (like) trên mạng xã hội.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Oh Jae-woong","avatar":""},{"name":"Choi Ji-su","avatar":""},{"name":"Subin","avatar":""},{"name":"Shin So-hyun","avatar":""},{"name":"Kim Ah-young","avatar":""},{"name":"Bae Yu-jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Moment of Shining Heart","Hateuga Bitchnaneun Sungan","하트가 빛나는 순간"]', 1784690324316);
