INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khi-trai-tim-toa-sang', 'Khi Trái Tim Tỏa Sáng', 'The Moment The Heart Shines', 'khi trái tim tỏa sáng the moment the heart shines oh jae-woong choi ji-su subin shin so-hyun kim ah-young bae yu-jin the moment of shining heart hateuga bitchnaneun sungan 하트가 빛나는 순간', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kpop-hanh-trinh-tien-hoa', 'K-Pop: Hành Trình Tiến Hóa', 'K-Pop Evolution', 'https://phimimg.com/upload/vod/20250408-1/ca9672eb9c3719afd3bfaf3472931b46.jpg', 'https://phimimg.com/upload/vod/20250408-1/149e9965f5da9d09cb2b04336c84e0f7.jpg', '<p>K-Pop là gì? Làm thế nào mà nó trở thành hiện tượng toàn cầu? Series tài liệu dài 7 tập này sẽ kể cho bạn tất cả những gì cần biết – từ lịch sử hình thành, những nghệ sĩ tạo nên cú hích, đến cộng đồng người hâm mộ và nhiều điều thú vị khác – qua góc nhìn của chính những người đã trải nghiệm và góp phần tạo nên làn sóng Hallyu. K-Pop Evolution là tư liệu toàn diện và chân thực nhất về hiện tượng văn hóa toàn cầu mang tên K-Pop. Series có sự xuất hiện của các nghệ sĩ nổi tiếng như: SuperM, H.O.T., BoA, SUPER JUNIOR, KARA, Ha:tfelt (Wonder Girls), Kang Daniel, Sandara Park (2NE1), Red Velvet, EXO, NCT, (G)I-DLE và PENTAGON.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Ye-eun","avatar":""},{"name":"Han Seung-yeon","avatar":""},{"name":"Amber Liu","avatar":""},{"name":"Joon Park","avatar":""},{"name":"Sandara Park","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["K-Pop Evolution"]', 1784690324316);
