INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-tren-troi', 'Cá Trên Trời', 'Fish Upon The Sky', 'https://phimimg.com/upload/vod/20250407-1/f386a430cbdce2332966ccde16ad0388.jpg', 'https://phimimg.com/upload/vod/20250407-1/7a9268df6bba12f6989f9928644e42ce.jpg', '<p>Pi thầm thích một trong những sinh viên hot nhất của Khoa Khoa học Sức khỏe Liên kết, nhưng vì thiếu tự tin về ngoại hình, cậu cảm thấy bất lực. Ít nhất là cho đến khi Duean và nhóm bạn giúp Pi thay đổi diện mạo để tăng sự tự tin. Khi Pi có đủ dũng khí để tiếp cận người mình thích, cậu lại chạm trán tình địch – Mork. Pi cố gắng vượt qua Mork trong mọi thứ để thu hút sự chú ý của Nan, nhưng không may mắn để đánh bại anh ta. Tuy nhiên, mọi thứ bắt đầu thay đổi khi Pi nhận ra mình đang nảy sinh những cảm xúc khác biệt dành cho Mork, khiến mọi chuyện trở nên phức tạp hơn.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Phuwin Tangsakyuen","avatar":""},{"name":"Naravit Lertratkosum","avatar":""},{"name":"Sahaphap Wongratch","avatar":""},{"name":"Thanawin Teeraphosukarn","avatar":""},{"name":"Chayapol Jutamas","avatar":""},{"name":"Thanaset Suriyapornchaikul","avatar":""},{"name":"Kittiphop Sereevichayasawat","avatar":""},{"name":"Ployshompoo Supasap","avatar":""},{"name":"Nancy Darina","avatar":""},{"name":"Yourboy Nureee","avatar":""},{"name":"Ploynira Hiruntaveesin","avatar":""},{"name":"Trai Nimtawat","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["鱼你相医",