INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dua-con-nha-ho-kieu', 'Những Đứa Con Nhà Họ Kiều', 'The Bond', 'https://phimimg.com/upload/vod/20240618-1/1179821bdfb52eb7def9e7cfd6d8e222.jpg', 'https://phimimg.com/upload/vod/20240618-1/2cf3f735aa0ad20b3959bc6b03a3f14d.jpg', '<p>Những Đứa Con Nhà Họ Kiều được chuyển thể từ tiểu thuyết cùng tên của nhà văn Vị Tịch. Bộ phim bắt đầu với hình ảnh ông Kiều Tổ Vọng một thân một mình nuôi 5 người con Nhất Thành, Nhị Cường, Tam Lệ, Tứ Mỹ và Thất Thất. Những đứa trẻ ngây thơ, lớn lên trong hoàn cảnh thiếu thốn cả vật chất lẫn tình cảm của cha mẹ, giữa thập niên đầy khó khăn và biến động.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2021, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Vũ","avatar":""},{"name":"Mao Hiểu Đồng","avatar":""},{"name":"Trương Văn Ý","avatar":""},{"name":"Tống Tổ Nhi","avatar":""},{"name":"Chu Dực Nhiên","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324316);
