INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-tay-linh-nghiep-du', 'Những Tay Lính Nghiệp Dư', 'Toy Soldiers', 'https://phimimg.com/upload/vod/20250407-1/f288329fe856d3b053c41e5b8ce16267.jpg', 'https://phimimg.com/upload/vod/20250407-1/e3c27f5e3202686ab65c0de1b787280f.jpg', '<p>Bộ phim là phiên bản điện ảnh của show thực tế nổi tiếng Hàn Quốc, kể về hành trình huấn luyện khắc nghiệt của những người nổi tiếng. Phim sử dụng công nghệ ScreenX và 4DX để mang đến trải nghiệm sống động như thật về những thử thách và sự trưởng thành của họ, truyền tải thông điệp mạnh mẽ về ý chí và sự vượt khó.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Byung-ji","avatar":""},{"name":"Julien Kang","avatar":""},{"name":"Road of the Strength","avatar":""},{"name":"Lee Moon-sik","avatar":""},{"name":"Kwak Yoon-gy","avatar":""},{"name":"Son Min-su","avatar":""},{"name":"caro","avatar":""},{"name":"Jigi","avatar":""},{"name":"Jo Jae-won","avatar":""},{"name":"Murdoc","avatar":""},{"name":"Kim Myung-jun","avatar":""},{"name":"Lim Hong-kyu","avatar":""},{"name":"Oh Hyun-min","avatar":""},{"name":"Sam Kim","avatar":""},{"name":"Kim Egg","avatar":""},{"name":"Oscar Jun","avatar":""},{"name":"Aslan","avatar":""},{"name":"Jake","avatar":""},{"name":"Axe","avatar":""},{"name":"Yoon Kwon","avatar":""},{"name":"Agent H","avatar":""},{"name":"Logan","avatar":""},{"name":"Jang Jae-sung","avatar":""},{"name":"Sse","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Toy Soldiers: Fake Men 2 The Complete","토이 솔져스: 가짜사나이2 더 컴플리트"]', 1784690324316);
