INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-vuong', 'Quyền Vương', 'The Ringmaster', 'https://phimimg.com/upload/vod/20250324-1/b33ae9f45b1540a7a46939a6704bb4cb.jpg', 'https://phimimg.com/upload/vod/20250324-1/6685b0292f07fb0f7fa97dbd97e2b7db.jpg', '<p>Hải Chính Hy (do Đàm Tuấn Ngạn đóng) là nhà vô địch Muay Thái với liên tiếp 12 lần bất bại. Nhưng sau lần ăn mừng chiến thắng thứ 13, anh vô tình xung đột với một tên xã hội đen khi giải cứu người phụ nữ bị quấy rối, không may qua đời. Khi xem lại đoạn ghi hình các trận đấu của Chính Hy, Hải Chính Lam (do Trương Chấn Lãng đóng) phát hiện cái chết của anh mình có nhiều uẩn khúc. Lam nghi ngờ có liên quan đến huấn luyện viên Thạch Ngạo Sơn (do Lê Diệu Tường đóng).

Lôi Kiên (do Diêu Tử Linh đóng), cô nàng trâm anh luôn cháy bỏng khát khao có một chỗ đứng trong thế giới Muay Thái. Với quyết tâm của mình, Lôi Kiên đã trở thành cố vấn cho liên đoàn quyền anh, từ đó gặp gỡ và nảy sinh mối quan hệ mập mờ với Ngạo Sơn.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 8, 2021, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Đàm Tuấn Ngạn","avatar":""},{"name":"Diêu Tử Linh","avatar":""},{"name":"Lại Úy Linh","avatar":""},{"name":"Lê Diệu Tường","avatar":""},{"name":"Trương Chấn Lãng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["拳王","The Ringmaster"]', 1784690324316);
