INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quyen-vuong', 'Quyền Vương', 'The Ringmaster', 'quyền vương the ringmaster đàm tuấn ngạn diêu tử linh lại úy linh lê diệu tường trương chấn lãng 拳王 the ringmaster', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-dong-san-ban', 'Hành Động Săn Bắn', 'The Hunting Opeations', 'https://phimimg.com/upload/vod/20231231-1/ca9d88fe5413dee9455c219399b0e512.jpg', 'https://phimimg.com/upload/vod/20231231-1/a9877c82b77ddbc0b066f219708f3256.jpg', '<p>Bộ phim này kể về Trần Xương Bình, một cảnh sát phòng chống ma túy nằm vùng. Nhằm bắt Đàm Tiêu Sơn, một người buôn ma túy, anh ấy nằm vùng bên cạnh Đàm Tử Long, con một của Đàm Tiêu Sơn. Vì cứu Đàm Tử Long nhiều lần, Trần Xương Bình dễ dàng được tín nhiệm. Sau cứu được Tiểu Muội đã nhà tan cửa nát do người buôn ma túy và con trai của em ấy, Trần Xương Bình nhờ Tiểu Muội liên lạc với Lí Chính Bân. Người khác đều tưởng Trần Xương Bình và Tiểu Muội là vợ chồng. Sau lòi đuôi, Trần Xương Bình lập tức báo tin cho Tiểu Muội, nhưng lại bị Đàm Tiêu Sơn phát hiện. Đàm Tiêu Sơn cưỡng ép Tiểu Muội và Minh Minh, cắt dứt khả năng liên lạc với Lí Chính Bân của Trần Xương Bình. Anh ấy đành phải liều lĩnh đưa tin cho Lí Chính Bân bằng mật mã đặc biệt do cảnh sát đã hy sinh để lại. Nhằm cứu Tiểu Muội và Minh Minh, Trần Xương Bình tự mình đến căn cứ địa giấu ma túy của Xhaka, một tội phạm ngấp nghé thế lực của Đàm Tiêu Sơn lâu năm, đàm phán với hắn để cứu Đàm Tử Long. Cuối cùng, Trần Xương Bình và Lí Chính Bân cùng nhau bắt được Đàm Tiêu Sơn và Đàm Tử Long, kết thúc “Hành động săn bắn” này.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Li Fei","avatar":""},{"name":"Zhang Yong Gang","avatar":""},{"name":"Wang Wen Xuan","avatar":""},{"name":"Ge Bu","avatar":""},{"name":"Huang Kai Xiang","avatar":""},{"name":"Yang Jun Chao","avatar":""},{"name":"Yang Zi Hua","avatar":""},{"name":"Da He","avatar":""},{"name":"Jin Song","avatar":""},{"name":"Hong Wei","avatar":""},{"name":"Lang Feng","avatar":""},{"name":"Hao Shuai","avatar":""},{"name":"Zhang Lu Yao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324316);
