INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-hieu-con-tim-phan-4', 'Tín Hiệu Con Tim (Phần 4)', 'Heart Signal (Season 4)', 'https://phimimg.com/upload/vod/20250327-1/e26877df7ea1e2297439b3988ac70cbe.jpg', 'https://phimimg.com/upload/vod/20250327-1/f69f9d0b5955ca603e5a14d6eb0d0c29.jpg', '<p>Tín Hiệu Con Tim là chương trình thực tế giao lưu suy luận về tình cảm nam nữ. Các cặp đôi nam nữ độc thân bước vào &quot;Ngôi nhà nhỏ tín hiệu&quot; sống chung và phát triển tình cảm với nhau.</p>', 'Hoàn Tất (21/21)', 21, 'tvshows', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Du Haitao","avatar":""},{"name":"Jerry Yan","avatar":""},{"name":"Chunye Zhang","avatar":""},{"name":"Ariel Lin","avatar":""},{"name":"Rao Xueman","avatar":""},{"name":"The8","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Heart Signal","心动的信号"]', 1784690324316);
