INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-cua-luca', 'Mùa Hè Của Luca', 'Luca', 'https://phimimg.com/upload/vod/20250327-1/2aa4c98aee79ec7ed357649a0c7def34.jpg', 'https://phimimg.com/upload/vod/20250327-1/99f72ee8d4c1843f5cc3fd098aa487a7.jpg', '<p>Lấy bối cảnh thành phố biển Riviera xinh đẹp ở nước Ý thơ mộng, bộ phim Luca kể về câu chuyện trưởng thành của một câu bé cùng với những trải nghiệm mùa hè đáng nhớ với tất cả những nét đặc trưng của nước Ý như kem gelato, mỳ pasta và những chuyến du ngoạn thị trấn trên chiếc xe tay ga. Cậu bé Luca tận hưởng niềm vui bất tận của mùa hè cùng với người bạn thân thiết mới quen, tuy nhiên tình bạn đẹp đẽ này có phần bấp bênh khi Luca phát hiện ra một bí mật động trời: người bạn ấy là một sinh vật sống ở dưới đáy đại dương.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jacob Tremblay","avatar":""},{"name":"Jack Dylan Grazer","avatar":""},{"name":"Emma Berman","avatar":""},{"name":"Saverio Raimondo","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Marco Barricelli","avatar":""},{"name":"Jim Gaffigan","avatar":""},{"name":"Peter Sohn","avatar":""},{"name":"Lorenzo Crisci","avatar":""},{"name":"Marina Massironi","avatar":""},{"name":"Gino La Monica","avatar":""},{"name":"Sandy Martin","avatar":""},{"name":"Giacomo Gianniotti","avatar":""},{"name":"Elisa Gabrielli","avatar":""},{"name":"Mimi Maynard","avatar":""},{"name":"Sacha Baron Cohe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["卢卡","盛夏友晴天","Luca","루카","ลูก้า","Mùa Hè Của Luca","Pixar Film Fest: Luca"]', 1784690324317);
