INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mua-he-cua-luca', 'Mùa Hè Của Luca', 'Luca', 'mùa hè của luca luca jacob tremblay jack dylan grazer emma berman saverio raimondo maya rudolph marco barricelli jim gaffigan peter sohn lorenzo crisci marina massironi gino la monica sandy martin giacomo gianniotti elisa gabrielli mimi maynard sacha baron cohe 卢卡 盛夏友晴天 luca 루카 ลูก้า mùa hè của luca pixar film fest: luca', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-thuc-tu-cam-thanh', 'Ẩm Thực Tử Cấm Thành', 'Royal Masterchef', 'https://phimimg.com/upload/vod/20231211-1/ef7970e47e340ccd3485525b398c9f2b.jpg', 'https://phimimg.com/upload/vod/20231211-1/8a6139abc918a034f878e69bd5472138.jpg', '<p>Phim kể về câu chuyện tình yêu của một cặp tình nhân ở Tử Cấm Thành, sau khi trải qua những thử thách trong chốn thâm cung tranh đấu đã kết hôn với nhau. Nhân vật chính Jing Xiangege và đầu bếp trong cung Zhang Dongguan đã vượt qua sự khác biệt trong quan niệm gia đình truyền thống, về danh tính và những áp lực khác nhau để có thể tồn tại. Họ liên tiếp giúp các cung nữ, hoàng tử, tướng lĩnh giải quyết các vấn đề của mỗi người, thông qua việc làm một loạt các món ăn ngon được chuẩn bị tỉ mỉ để giải quyết mọi mâu thuẫn. Trong quá trình đó, cả hai đã cùng nhau vượt qua khó khăn, hiểu nhau hơn, lặng lẽ hoàn thành quá trình trưởng thành của bản thân và cuối cùng quay về cuộc sống bình thường cùng nhau.</p>', 'Full', 1, 'single', 'completed', 32, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cui Erkang","avatar":""},{"name":"Lu Jiani","avatar":""},{"name":"Zhang Chunzhong","avatar":""},{"name":"Zhu Jian","avatar":""},{"name":"Zhu Xuan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324317);
