INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-quai-2-rung-den', 'Thủy Quái 2: Rừng Đen', 'Water Monster 2', 'https://phimimg.com/upload/vod/20250326-1/c06ad5a8842fd4e80b9f180be849dfa0.jpg', 'https://phimimg.com/upload/vod/20250326-1/5b456096df2e4b3fa893c1c9305a544f.jpg', '<p>Nữ pháp y Thanh Linh đã nhiều lần phá giải các vụ án kỳ lạ, nhưng thân thế của cô lại rất mơ hồ không rõ. Em trai muốn giải đáp bí ẩn về thân thế của chị, mà đã mất tích ở trấn Thượng Thuỷ. Thanh Linh vì tìm kiếm em trai, một thân một mình đến với trấn Thượng Thuỷ xa xôi và cổ quái. Tại trấn Thượng Thuỷ, cô đã liên tiếp gặp phải “thuỷ quái” hung ác giết người. Vì muốn điều tra ra rõ chân tướng, Thanh Linh đã xông vào khu vực cấm…</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Zhener","avatar":""},{"name":"Han Dong","avatar":""},{"name":"Liu Lincheng","avatar":""},{"name":"Wang Jianguo","avatar":""},{"name":"Wang Hongqian","avatar":""},{"name":"Guo Jiayi","avatar":""},{"name":"Wang Zirun","avatar":""},{"name":"Ziqi Wei","avatar":""},{"name":"Wu Hao","avatar":""},{"name":"Wu Chengzhi","avatar":""},{"name":"Rong Weifeng","avatar":""},{"name":"Xu Shao-Hang","avatar":""},{"name":"Gao Yuanfeng","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Shui Guai","수괴2 : 흑목림","水怪2：黑木林"]', 1784690324317);
