INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-mau-dinh-menh', 'Sắc Màu Định Mệnh', 'Tinted With You', 'https://phimimg.com/upload/vod/20250325-1/fe4aac76efac5476f632aafe87d43642.jpg', 'https://phimimg.com/upload/vod/20250325-1/c5401b65da927aaf98718a1536038930.jpg', '<p>Trong quá khứ phong kiến của Hàn Quốc, Thái tử bị phế truất Lee Heon bị ép phải sống lưu vong, cô độc và đầy lo sợ. Người anh trai tàn nhẫn của anh đã soán ngôi, và để củng cố quyền lực, hắn sẵn sàng thủ tiêu Lee Heon bất cứ lúc nào. Những kẻ ám sát và âm mưu đen tối luôn rình rập, và người duy nhất Lee Heon có thể tin tưởng chính là cận vệ trung thành và nhân hậu Geum. Trong khi đó, ở thời hiện đại, Eun Ho, một nam sinh trung học đam mê hội họa, coi nghệ thuật là cả thế giới của mình. Một ngày nọ, khi nhận nhiệm vụ hoàn thành một bức tranh bí ẩn, Eun Ho bất ngờ bị cuốn vào quá khứ xa xôi và gặp Lee Heon. Cả hai dần nảy sinh mối quan hệ sâu sắc, lãng mạn và đầy xúc cảm. Nhưng khi vị vua đương nhiệm ngày càng bất an, quyết tâm loại bỏ Lee Heon, Eun Ho nhận ra rằng cậu có thể là hy vọng sống sót duy nhất của vị Thái tử bị lưu đày…</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Hyun Woo","avatar":""},{"name":"Park Jun-hee","avatar":""},{"name":"Kim Tae-jeong","avatar":""},{"name":"Yoon Ye-hee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Pintado Com Você","물들여"]', 1784690324317);
