INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-si-da-hoi-sinh-the-gioi-phan-2', 'Tiến Sĩ Đá: Hồi Sinh Thế Giới (Phần 2)', 'Dr. STONE (Season 2)', 'https://phimimg.com/upload/vod/20241009-1/51bc69910279c515f1731bd0081485e9.jpg', 'https://phimimg.com/upload/vod/20241009-1/12d6f61cc28cc3b701e7adcc77907d48.jpg', '<p>Ngày cậu học sinh cấp 3 Taiju quyết định tỏ tình với người đã thầm mến bao năm thì có một luồng ánh sáng kỳ lạ chiếu qua. Trong phút chốc, loài người trên thế giới đều hoá đá! Bởi một lòng nghĩ đến nguyện vọng chưa hoàn thành giúp cậu ấy giữ được ý thức. Cứ vậy qua hàng ngàn năm, cuối cùng lời nguyền hoá đá được hoá giải nhưng điều khiến cậu ngạc nhiên là trước mặt cậu một dòng chữ yêu cầu cậu đi theo…. Taiju đã đi đến đó và lại gặp được bạn học Senku của mình. Thế nên cậu quyết định bắt tay cùng Senku xây dựng lại nền văn minh nhân loại.</p>', 'Full', 11, 'hoathinh', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"小林裕介","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Доктор Стоун","石纪元","新石纪","石纪元 科学与未来 第2部分","Dr.STONE","डॉ. स्टोन","ドクターストーン","Dr.STONE STONE WARS","Dr.STONE (ドクターストーン)","Dr.STONE NEW WORLD","Dr.STONE SCIENCE FUTURE","닥터스톤","닥터스톤 4기","Доктор Стоун: Каменные войны","دكتور ستون","طبيب الحجر","Dr. STONE 新石紀","Dr. STONE WARS 新石紀 戰爭","Dr. STONE NEW WORLD 新石紀-新世界","Dr. STONE 龍水","石紀元","Dr. STONE: Stone Wars","Dr. STONE: New World","Dr. STONE: Science Future","Doctor Stone","Tiến Sĩ Đá","Tiến Sĩ Đá: Vương Quốc Khoa Học","Tiến Sĩ Đá: Cuộc Chiến Thế Giới Đá","Tiến Sĩ Đá: Thuyền Trưởng Ryusui","Tiến Sĩ Đá: Thế Giới Mới","Tiến Sĩ Đá: Tương Lai Của Khoa Học"]', 1784690324317);
