INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tien-si-da-hoi-sinh-the-gioi-phan-2', 'Tiến Sĩ Đá: Hồi Sinh Thế Giới (Phần 2)', 'Dr. STONE (Season 2)', 'tiến sĩ đá: hồi sinh thế giới (phần 2) dr. stone (season 2) 小林裕介 доктор стоун 石纪元 新石纪 石纪元 科学与未来 第2部分 dr.stone डॉ. स्टोन ドクターストーン dr.stone stone wars dr.stone (ドクターストーン) dr.stone new world dr.stone science future 닥터스톤 닥터스톤 4기 доктор стоун: каменные войны دكتور ستون طبيب الحجر dr. stone 新石紀 dr. stone wars 新石紀 戰爭 dr. stone new world 新石紀-新世界 dr. stone 龍水 石紀元 dr. stone: stone wars dr. stone: new world dr. stone: science future doctor stone tiến sĩ đá tiến sĩ đá: vương quốc khoa học tiến sĩ đá: cuộc chiến thế giới đá tiến sĩ đá: thuyền trưởng ryusui tiến sĩ đá: thế giới mới tiến sĩ đá: tương lai của khoa học', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-trong-toa-nha-phan-1', 'Sát Nhân Trong Tòa Nhà (Phần 1)', 'Only Murders in the Building (Season 1)', 'https://phimimg.com/upload/vod/20250319-1/fec215e232ae1559b306220b3c64eb49.jpg', 'https://phimimg.com/upload/vod/20250319-1/535deaca09035ce30a07db84a3a9ef37.jpg', '<p>Phim xoay quanh câu chuyện về những con người hàng xóm trong tòa nhà là Charles, Oliver và Mabel, cả ba đều có một mối liên kết với nhau vô cùng đặc biệt. Bỗng một hôm, người sống trong tòa nhà của họ chết đầy bí ẩn, vì thế cả ba cùng nhau bắt đầu cuộc hành trình điều tra nguyên nhân. Bọn họ bắt đầu khám phá về lai lịch cũng nhưng những người thân của nạn nhân, điều này cũng khiến cho quá khứ bí ẩn của Mabel được giải mã. Còn Oliver thì dùng những tài năng của mình phân tích sự việc. Liệu mọi chuyện sẽ như thế nào? Cả ba có thể tìm kiếm được hung thủ thật sự?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Steve Martin","avatar":""},{"name":"Martin Short","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Michael Cyril Creighton","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Homicídios Ao Domicílio","Só os Assassinos no Edifício","Só os Assassinos do Edifício","大楼里只有谋杀","公寓大楼里的谋杀案","רק רציחות בבניין","فقط قتل‌های داخل ساختمان","Убийства в пределах здания","Тільки вбивства у будівлі","omitb","Only Murders in the Building"]', 1784690324317);
