INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-nhan-trong-toa-nha-phan-1', 'Sát Nhân Trong Tòa Nhà (Phần 1)', 'Only Murders in the Building (Season 1)', 'sát nhân trong tòa nhà (phần 1) only murders in the building (season 1) steve martin martin short selena gomez michael cyril creighton homicídios ao domicílio só os assassinos no edifício só os assassinos do edifício 大楼里只有谋杀 公寓大楼里的谋杀案 רק רציחות בבניין فقط قتل‌های داخل ساختمان убийства в пределах здания тільки вбивства у будівлі omitb only murders in the building', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-co-nam-nang-dau-phan-2', 'Nhà Có Năm Nàng Dâu (Phần 2)', 'The Quintessential Quintuplets (Season 2)', 'https://phimimg.com/upload/vod/20250316-1/0528ebfc8eaec8e8bb7cabe4cd0d4043.jpg', 'https://phimimg.com/upload/vod/20250316-1/f70f365713843f868b08c13f88597a8a.jpg', '<p>Trong một lần nọ, anh chàng Futaro Uesugi được thuê về làm gia sư cho 5 cô con gái của một ông chú giàu nứt vách, và dĩ nhiên, tiền thuê cậu khá là cao. Thế là những câu chuyện dở khóc dở cười xoay quanh anh gia sư Uesugi và 5 cô nàng xinh đẹp nhưng hay gây rắc rối cho cậu bắt đầu…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Miku Ito","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Inori Minase","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["As Quíntuplas","五等分的花嫁","The Quintessential Quintuplets","Go-Toubun no Hanayome","Gotoubun no Hanayome","5-toubun no Hanayome","Go-Tōbun no Hanayome","5Hanayome SP","5등분의 신부","Sposób na pięcioraczki","Go Toubun no Hanayome","The Quintessential Quintuplets∬.","五等分の花嫁"]', 1784690324317);
