INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-thac', 'Dòng Thác', 'The Falls', 'https://phimimg.com/upload/vod/20250315-1/efed66004a297727bd456c8c3453ad65.jpg', 'https://phimimg.com/upload/vod/20250315-1/0b7355fa8f197ef12f9df3a4b9bca163.jpg', '<p>Dòng Thác Sau khi phải cách ly cùng nhau trong dịch COVID-19, một người mẹ và cô con gái buộc phải đối mặt với những khó khăn cá nhân và căng thẳng trong quan hệ giữa hai người.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Đài Loan', 0, '[{"name":"Alyssa Chia","avatar":""},{"name":"Gingle Wang","avatar":""},{"name":"Chen Yi-wen","avatar":""},{"name":"Lee-Zen Lee","avatar":""},{"name":"Liang-Tso Liu","avatar":""},{"name":"Yang Li-Yin","avatar":""},{"name":"Shau-Ching Sung","avatar":""},{"name":"Waa Wei","avatar":""},{"name":"Tiffany Hsu Wei-Ning","avatar":""},{"name":"Shao-Huai Chang","avatar":""},{"name":"Liu Kuan-ting","avatar":""},{"name":"Huang Hsin-Yao","avatar":""},{"name":"Lin Chiao-yuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Pu Bu","สวนทาง","Падение","The Falls","瀑布"]', 1784690324317);
