INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-dai-tong-su', 'Nhất Đại Tông Sư', 'Viet Nam''s Grandmaster', 'https://phimimg.com/upload/vod/20250314-1/f2edc712e0abf00ecf2b34736e636bdc.jpg', 'https://phimimg.com/upload/vod/20250314-1/9e2360c251e6a9c36b48c548ae16bef8.jpg', '<p>&quot;Nhất Đại Tông Sư&quot; là một bộ phim của đạo diễn Đỗ Khôi &amp; Võ Đức, dựa trên một câu chuyện có thật kể về một võ sư huyền thoại đất võ tên Ngọc Đinh (tên nhân vật đã được thay đổi ). Ông được giới võ thuật mệnh danh là người giữ lửa cho tinh hoa võ thuật, cả cuộc đời say mê luyện võ và luôn muốn võ học được lưu truyền cho hậu thế. Bộ phim mang đến thông điệp: Học võ là để nâng cao sức khỏe, bảo vệ bản thân và người khác khi gặp nguy hiểm chứ không phải học võ là để giương oai, gây hấn và đánh nhau. Qua đó, góp phần tôn vinh tinh hoa võ cổ truyền Bình Định nói riêng và nền võ học Việt Nam nói chung.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Nguyên Yunie","avatar":""},{"name":"Thanh Sang","avatar":""},{"name":"Tử Đằng","avatar":""},{"name":"Như Quỳnh","avatar":""},{"name":"Võ Đức","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Children of the Century","Az évszázad gyermekei","Das Liebesdrama von Venedig","Les Enfants du Siècle"]', 1784690324317);
