INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-dai-tong-su', 'Nhất Đại Tông Sư', 'Viet Nam''s Grandmaster', 'nhất đại tông sư viet nam''s grandmaster nguyên yunie thanh sang tử đằng như quỳnh võ đức children of the century az évszázad gyermekei das liebesdrama von venedig les enfants du siècle', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-nguon-nuoc-mat', 'Thượng Nguồn Nước Mắt', 'A River Runs Through It', 'https://phimimg.com/upload/vod/20250314-1/c4606b244492d8327b0b1b87b6965773.jpg', 'https://phimimg.com/upload/vod/20250314-1/5136d88dbff0f8ff152138a3e8aa3e32.jpg', '<p><span style="text-wrap-mode: nowrap;">Trước kỳ thi đại học, Hạ Tiểu Quất chuyển đến một ngôi trường mới và kết bạn với một nhóm bạn mới như Trình Lãng điềm đạm, Lục Thập Y thẳng tính, Nhạc Lạc Đào ngơ ngác... Mặc dù môi trường mới khiến cô bối rối và việc làm quen với bạn mới bắt đầu bằng hàng loạt hiểu lầm, nhưng sự chân thành và giúp đỡ lẫn nhau đã khiến những người trẻ tuổi xây dựng tình bạn sâu sắc. Họ cùng nhau học tập, thi đua trong học hành, đồng lòng trong đại hội thể thao, khiến tình bạn ngày càng bền chặt. Việc chia sẻ những rắc rối trong gia đình và lựa chọn nguyện vọng tương lai cũng giúp họ cùng nhau cảm nhận hương vị của sự trưởng thành.</span><span style="text-wrap-mode: nowrap;">Kỳ thi đại học cuối cùng cũng đến, Trình Lãng vì cứu người mà ảnh hưởng đến thành tích, lỡ mất chuyên ngành mình mong muốn. Lục Thập Y giấu gia đình đăng ký vào chuyên ngành mà cha mình phản đối nhất. Hạ Tiểu Quất và Nhạc Lạc Đào thi vượt kỳ vọng và đỗ vào ngôi trường mơ ước. Trong cuộc sống đại học, họ lại đối mặt với những thử thách mới: Trình Lãng vật lộn với việc học trái ngành, Lục Thập Y phải vượt qua rào cản tâm lý, còn Tiểu Quất rơi vào sự mơ hồ về định hướng cuộc đời. Thế nhưng họ đã cùng nhau vượt qua khó khăn, hỗ trợ lẫn nhau, dần xác lập ước mơ cuộc đời trong những lúc mông lung và thất bại, cũng như trải nghiệm đầy đủ vị ngọt đắng của tình bạn và tình yêu.</span></p><p><span style="text-wrap-mode: nowrap;">Hạ Tiểu Quất và những người bạn của cô đã cùng nhau đi qua một tuổi trẻ ấm áp và tràn đầy nỗ lực như thế.</span></p><p><br/></p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thụy Xương","avatar":""},{"name":"Hồ Ý Huyên","avatar":""},{"name":"Trần Bác Hào","avatar":""},{"name":"Thích Nghiễn Địch","avatar":""},{"name":"Khương Trác Quân","avatar":""},{"name":"Đàm Tuyền","avatar":""},{"name":"Trịnh Vệ Lệ","avatar":""},{"name":"Hoàng Hải Băng","avatar":""},{"name":"Dương Vũ Đình","avatar":""},{"name":"Dương Đồng Thư","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["眼泪的上游","Yan Lei De Shang You","Shang You","نهر يجري خلاله","SY","강은 관통해 흐른다","상유","上游"]', 1784690324317);
