INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thuong-nguon-nuoc-mat', 'Thượng Nguồn Nước Mắt', 'A River Runs Through It', 'thượng nguồn nước mắt a river runs through it thụy xương hồ ý huyên trần bác hào thích nghiễn địch khương trác quân đàm tuyền trịnh vệ lệ hoàng hải băng dương vũ đình dương đồng thư 眼泪的上游 yan lei de shang you shang you نهر يجري خلاله sy 강은 관통해 흐른다 상유 上游', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiep-an-nuong-tuyet-menh-thich-sat', 'Nhiếp Ấn Nương: Tuyệt Mệnh Thích Sát', 'The Assassination Of Nie Yinniang', 'https://phimimg.com/upload/vod/20240205-1/d87e9c157a1e98eb808d8074f573568f.jpg', 'https://phimimg.com/upload/vod/20240205-1/996f89dce75e2a13578f5c30fb570967.jpg', '<p>Sau khi cuộc nổi dậy An Sử được giải quyết, những người còn lại của An Sử đã thành lập băng đảng Phi Ất, thường xuyên tạo ra các cuộc khủng bố nhằm mục đích khơi lại tai họa chiến tranh và lật đổ nhà Đường. Vào năm Trinh Nguyên thứ 12, bọn cướp Phi Ất, lên kế hoạch bắt các thủ lĩnh quân sự của bảy châu Ngụy Bác và khởi binh ở Hà Bắc. Để bảo vệ sự yên bình, môn phái Trường Thủy được thành lập bởi liên minh kiếm sĩ giang hồ, đã cử người cao thủ của họ - Chiêu Nương, đóng giả là Niếp Ấn Nương, con gái của tướng quân Ngụy Bác - Niếp Phong bí mật thâm nhập vào Ngụy Bác chờ cơ hội để giết thủ lĩnh của băng đảng Phi Ất. Trận chiến sinh tử giữa hai bên sắp xảy ra...</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Royi","avatar":""},{"name":"Jin Chong","avatar":""},{"name":"Zheng Yuan Yuan","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324317);
