INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-gia-vung-harlem-phan-2', 'Bố Già Vùng Harlem (Phần 2)', 'Godfather Of Harlem (Season 2)', 'https://phimimg.com/upload/vod/20250308-1/35ab619ae8cd329b634cf9646097cac0.jpg', 'https://phimimg.com/upload/vod/20250308-1/1d3be99f7e6eccfe182a3f2574bdb47c.jpg', '<p>Lấy cảm hứng từ trùm tội phạm khét tiếng Bumpy Johnson, người sau mười năm trong tù trở về vào đầu thập niên 1960 và chứng kiến khu phố từng dưới quyền kiểm soát của mình rơi vào hỗn loạn. Với những con phố nay nằm trong tay mafia Ý, Bumpy quyết tâm giành lại vị thế của mình ở Harlem.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Forest Whitaker","avatar":""},{"name":"Ilfenesh Hadera","avatar":""},{"name":"Antoinette Crowe-Legacy","avatar":""},{"name":"Lucy Fry","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Крестный отец Гарлема","Godfather of Harlem"]', 1784690324317);
