INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-nguon-nhip-tim', 'Kế Hoạch Nguồn Nhịp Tim', 'Broker', 'https://phimimg.com/upload/vod/20250305-1/bedffa2b4ea989965bcdb7303d76c2ce.jpg', 'https://phimimg.com/upload/vod/20250305-1/1d082757b80d723442cde600425b991f.jpg', '<p>Một nghiên cứu của Cầu Giai Ninh đã đạt đến giai đoạn lâm sàng thì bỗng nam nghiên cứu viên Châu Tiểu Sơn xuất hiện. Bằng sự khôn ngoan của mình, anh đã thu hút Giai Ninh, cả hai dần nảy sinh tình cảm. Thế nhưng, thực chất Tiểu Sơn là một “gián điệp” khoa học, có nhiệm vụ đánh cắp công trình nghiên cứu của Gia Ninh. Liệu khi sự thật được phát giác, cả hai sẽ như thế nào?</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 5, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"La Vân Hi","avatar":""},{"name":"Tống Thiến","avatar":""},{"name":"Từ Khai Sính","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xin Tiao Yuan Ji Hua","Fatal Encounter","致命邂逅","Zhi Ming Xie Hou","Qian Ke","掮客","遇见阳光遇见你","XTYJH","ลวงรักเล่ห์จารชน","心跳源计划"]', 1784690324317);
