INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sang-nhu-trang-trong-may', 'Sáng Như Trăng Trong Mây', 'Bright As The Moon', 'https://phimimg.com/upload/vod/20250305-1/f3374dda30c0df880fc4cfdf03edaef9.jpg', 'https://phimimg.com/upload/vod/20250305-1/5fe470f73ac530a4917aef16cf52cd6c.jpg', '<p>Vân Thiển Nguyệt cùng thế tử Dung Cảnh vốn yêu thương nhau, lại bị hoàng quyền ngăn cản. Dung Cảnh, vì trúng hàn độc mà chịu bệnh tật mười năm, Thiển Nguyệt nguyện trả giá mất đi ký ức để cứu chàng. Thiên Thánh tân hoàng Dạ Khinh Nhiễm yêu Thiển Nguyệt, để có được tình yêu đã đem độc khóa tình sinh tử dẫn vào người nàng, mục đích khiến nàng sinh tử không rời mình. Dù ký ức mất đi, song trái tim của Thiển Nguyệt vẫn như thuở ban đầu.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Chỉ Khê","avatar":""},{"name":"Đồng Mộng Thực","avatar":""},{"name":"Hướng Hạo","avatar":""},{"name":"Trình Nghiên Thu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Jiao Ruo Yun Jian Yue","Wan Ku Shi Zi Fei","Bright as the Moon","纨绔世子妃","皎若雲間月","皎若云间月"]', 1784690324317);
