INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-hiep-co-tri', 'Nửa Hiệp Cơ Trí', 'Be Yourself', 'https://phimimg.com/upload/vod/20250305-1/a5bf260dd62a89fd4740743873bac841.jpg', 'https://phimimg.com/upload/vod/20250305-1/055e5e3c3658e48dad54926893904b1b.jpg', '<p>Bốn cô gái Hạ Lãng Lãng, Phàn Tiêu Vũ, Thục Mẫn, Dương Gia Thiến từ bốn vùng quê cùng nhau đến báo danh ở khoa tin tức và bắt đầu cuộc sống đại học vui vẻ. Trải qua những va chạm, những đối đầu, họ dần hiểu rõ về nhau, trở thành những người bạn thân thiết và cùng nhau trải qua quãng đời thanh xuân tươi đẹp nơi giảng đường đại học.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thẩm Nguyệt","avatar":""},{"name":"Chương Nhược Nam","avatar":""},{"name":"Vi Vi An","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ji Zhi De Shang Ban Chang","JZDSBC","예지적상반전","너 자신이 되라","기지적상반장","기지적상반장: 청춘시대","機智的上半場","机智的上半场"]', 1784690324317);
