INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-dan-dieu-duoc-khong-bang-nang', 'Linh Đan Diệu Dược Không Bằng Nàng', 'Beyond Prescriptions', 'https://phimimg.com/upload/vod/20250305-1/b7afb85b1f111d843598f4a77e2eabd3.jpg', 'https://phimimg.com/upload/vod/20250305-1/76f252ace27a0ec86068d4c75526088b.jpg', '<p>Nữ y sư lớn tuổi Y Hoa lên núi hái thuốc vô tình gặp Diệp Hướng bị thương hôn mê, tấm lòng người hành y nên nàng mang hắn về y quán cứu chữa. Diệp Hướng mất trí nhớ, xuất hiện khuynh hướng đa nhân cách, khi thì ngoan ngoãn khi thì ngang ngược. Y Hoa nhận hắn làm dược đồng, gọi là Vân Quy. Cảm động trước ơn cứu mạng cũng như nhân cách của Y Hoa, Vân Quy dần nảy sinh tình cảm với nàng.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ding Yiyi","avatar":""},{"name":"Wang Haoge","avatar":""},{"name":"Liu Haoxin","avatar":""},{"name":"Yuanyuan Zong","avatar":""},{"name":"Erli Xi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["灵丹妙药不及你","那时杏林春暖","Na Shi Chun Xing Lin Nuan","Ling Dan Miao Yao Bu Ji Ni","영단묘약불급니","Панацея не так хороша, как ты","Xing Lin Was Warm in Spring","Beyond Prescriptions"]', 1784690324317);
