INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('linh-dan-dieu-duoc-khong-bang-nang', 'Linh Đan Diệu Dược Không Bằng Nàng', 'Beyond Prescriptions', 'linh đan diệu dược không bằng nàng beyond prescriptions ding yiyi wang haoge liu haoxin yuanyuan zong erli xi 灵丹妙药不及你 那时杏林春暖 na shi chun xing lin nuan ling dan miao yao bu ji ni 영단묘약불급니 панацея не так хороша, как ты xing lin was warm in spring beyond prescriptions', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-du-phan-2', 'Quỷ Dữ (Phần 2)', 'Evil (Season 2)', 'https://phimimg.com/upload/vod/20250305-1/362d333d0050a7a19e46045c3ab77802.jpg', 'https://phimimg.com/upload/vod/20250305-1/dd0382c68ff36899a564f6072b1d3a14.jpg', '<p>Nhà tâm lý học pháp y hoài nghi Kristen Bouchard hợp tác cùng David Acosta, một linh mục tập sự, và chuyên gia công nghệ Ben Shakir để điều tra những phép màu được đồn đại, các vụ quỷ ám và những hiện tượng kỳ bí khác. Họ tìm kiếm lời giải thích khoa học cho những sự kiện này hoặc xác định liệu có điều gì thực sự siêu nhiên đang diễn ra.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Katja Herbers","avatar":""},{"name":"Mike Colter","avatar":""},{"name":"Aasif Mandvi","avatar":""},{"name":"Michael Emerson","avatar":""},{"name":"Brooklyn Shuck","avatar":""},{"name":"Skylar Gray","avatar":""},{"name":"Maddy Crocco","avatar":""},{"name":"Dalya Knapp","avatar":""},{"name":"Andrea Martin","avatar":""},{"name":"Kurt Fuller","avatar":""},{"name":"Christine Lahti","avatar":""},{"name":"Marti Matulis","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Evil - Dem Bösen auf der Spur","Evil"]', 1784690324317);
