INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-pha-thuong-khung-phan-4', 'Đấu Phá Thương Khung (Phần 4)', 'Fights Break Sphere (Season 4)', 'đấu phá thương khung (phần 4) fights break sphere (season 4) 劉三木 张沛 刘雨轩 蘇婉 祝俊 陳奕雯 楊夢露 文曉依 閻麼麼 夏磊 dian tao 张韦 ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-thoi-khong-lang-man', 'Siêu Thời Không Lãng Mạn', 'See You Again', 'https://phimimg.com/upload/vod/20240118-1/20d0519bde0f5175692c68fc8f6d6f00.jpg', 'https://phimimg.com/upload/vod/20240118-1/9ca529e2ef6faf7b9dca5dca59b48273.jpg', '<p>Bộ phim tình yêu thời Dân Quốc do Vương Phong làm đạo diễn, với sự tham gia của các diễn viên Hồ Nhất Thiên, Trần Ngọc Kỳ, Vương Thiên Thần, Bạch Thủy, Lưu Di Đồng.Bộ phim kể về câu chuyện lãng mạn và hài hước của Hướng Tần Vũ một ngôi sao điện ảnh của Trung Hoa Dân Quốc tình cờ gặp Kim A Ngân một biên kịch chưa có kinh nghiệm ở thế kỷ 21.Hai con người với những tính cách khác nhau bắt đầu câu chuyện xuyên không lãng mạn và hài hước.Vào những năm 1930, Hướng Tần Vũ một ngôi sao điện ảnh của Trung Hoa Dân Quốc, vô tình bị bắn trúng trên phim trường và xuyên không về thời hiện đại. Vì vậy, anh bắt đầu một mối tình ngọt ngào với Kim A Ngân, đồng thời anh đang tìm kiếm sự thật đằng sau sự tái sinh của số phận và sự thật về việc anh bị súng bắn chết...</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Hồ Nhất Thiên","avatar":""},{"name":"Trần Ngọc Kì","avatar":""},{"name":"Wang Tian Chen","avatar":""},{"name":"Michelle Bai","avatar":""},{"name":"Liuyittong","avatar":""},{"name":"Dai Wenwen","avatar":""},{"name":"HeiZe","avatar":""},{"name":"Hei Ze","avatar":""},{"name":"Sally","avatar":""},{"name":"Zhang Xue Han","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324317);
