INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-tu-khuynh-thanh', 'Công Tử Khuynh Thành', 'Your Sensibility My Destiny', 'https://phimimg.com/upload/vod/20240801-1/2afdeca4dd0a205ac21cc3747a9c0f5f.jpg', 'https://phimimg.com/upload/vod/20250302-1/af3740048b3e9de4523a9d5ce8857ab5.jpg', '<p>&quot;Công Tử Khuynh Thành&quot; (2021) là một bộ phim tình yêu cổ trang nhẹ nhàng, hài hước, được chuyển thể từ tiểu thuyết cùng tên. Đạo diễn: Lý Dương. Diễn viên: Bốc Quan Kim, Vương Tinh Việt, Nhiếp Tử Hạo, Lưu Nhất Đồng, Chiến Vũ, Trương Tuyết Hàm,... Bộ phim kể về nữ hiệp giang hồ Lâm Trì (Bốc Quan Kim đóng) tinh nghịch, hào sảng nhưng lại hơi mù đường. Từ nhỏ, cô đã theo sư phụ lang bạt giang hồ, cướp của người giàu chia cho người nghèo. Trong một lần bỏ trốn, cô lên nhầm xe ngựa của Mạch Khinh Trần. Vị Hoàng tử này không có cảm giác, vẫn luôn sống nhàn tản trong sự che chở của Hoàng hậu. Trên xe ngựa, hai người vô tình chạm vào nhau, lần đầu tiên Mạch Khinh Trần cảm nhận được thế giới, bèn ép Lâm Trì ký kết khế ước với mình... Từ đó, hai người bắt đầu một câu chuyện nhân duyên kỳ diệu, từ đôi oan gia vui vẻ trở thành người yêu, tình cảm ngày càng sâu nặng. Cuối cùng, họ nắm tay nhau chống lại những khó khăn trong số mệnh, trở thành giai thoại tình yêu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bu Guanjin","avatar":""},{"name":"王星越","avatar":""},{"name":"Nie Zihao","avatar":""},{"name":"Liu Yitong","avatar":""},{"name":"Zhan Yu","avatar":""},{"name":"张雪菡","avatar":""},{"name":"Min Liang","avatar":""},{"name":"李九霖","avatar":""},{"name":"Liu Xiao Liang","avatar":""},{"name":"Liu Luo Xi","avatar":""},{"name":"Zhang Tian Lin","avatar":""},{"name":"Liao Huijia","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324317);
