INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-than-bien-phan-3', 'Tinh Thần Biến (Phần 3)', 'Stellar Transformation (Season 3)', 'https://phimimg.com/upload/vod/20250224-1/c114a533547ca2093fbbab3a6656133b.jpg', 'https://phimimg.com/upload/vod/20250225-1/d65b3600001769b15a7668c9ff189db0.jpg', '<p>Sau trận chiến của Tần Đế, không rõ tung tích của Tần Vũ và Tiểu Hắc, Tần Đế tức giận quay trở lại triều đình và nắm lấy hành động tấn công Vương quốc Chu. Tuy nhiên, Tần Vũ đã không chết sau thảm họa, và vô tình đến được Lôi Sơn cùng với Xiao Hei, và dựa vào nước mắt sao băng để sửa chữa cơ thể của mình. “Sao đổi mệnh” của Lôi Dận sẽ mang đến cho Tần Vũ những thay đổi gì</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yuan Weng","avatar":""},{"name":"Shen Dawei","avatar":""},{"name":"Jingxia Liu","avatar":""},{"name":"Liu Yuxuan","avatar":""},{"name":"Muqing Ke","avatar":""},{"name":"Ming Zhao","avatar":""},{"name":"Xia Lei","avatar":""},{"name":"Hongbo Guo","avatar":""},{"name":"Qingqing Du","avatar":""},{"name":"Jackwin","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Stellar Transformations","Legend of Immortals","Xingchen Bian","Xing Chen Bian","Stellar Transformation","星辰變","星辰变"]', 1784690324317);
