INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('eternals-chung-toc-bat-tu', 'Eternals: Chủng Tộc Bất Tử', 'Eternals', 'https://phimimg.com/upload/vod/20250219-1/6fd633fd7914b5e5bfda680942a877df.jpg', 'https://phimimg.com/upload/vod/20250219-1/779b6954e2fc00bf8613e42c1d9fcc01.jpg', '<p>Chủng Tộc Bất Tử (The Eternals) là một nhóm gồm những người ngoài hành tinh cổ đại đã sống bí mật trên Trái đất trong hàng nghìn năm. Khi một bi kịch bất ngờ ập đến buộc họ phải thoát ra khỏi bóng tối, họ buộc phải đoàn tụ chống lại kẻ thù truyền kiếp nhất của nhân loại, Deviants.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Gemma Chan","avatar":""},{"name":"Richard Madden","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Salma Hayek Pinault","avatar":""},{"name":"Kumail Nanjiani","avatar":""},{"name":"Lia McHugh","avatar":""},{"name":"Brian Tyree Henry","avatar":""},{"name":"Lauren Ridloff","avatar":""},{"name":"Barry Keoghan","avatar":""},{"name":"Don Lee","avatar":""},{"name":"Bill Skarsgård","avatar":""},{"name":"Kit Harington","avatar":""},{"name":"Harish Patel","avatar":""},{"name":"Haaz Sleiman","avatar":""},{"name":"Esai Daniel Cross","avatar":""},{"name":"Harry Styles","avatar":""},{"name":"Alan Scott","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Marvel Studios'' Eternals","ฮีโร่พลังเทพเจ้า","The Eternals","永恆","이터널스","Sonsuzlar","永恒族","永恆族","მარადიულები","Chủng Tộc Bất Tử","Eternos","اترنالز","Ölümsüzl