INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-vat', 'Nhân Vật', 'Character', 'https://phimimg.com/upload/vod/20250210-1/2b01984c915975cbf51501ecd52068e7.jpg', 'https://phimimg.com/upload/vod/20250210-1/d7a5a19626aafa1459e63dbf09f158c6.jpg', '<p>Một người đàn ông tốt bụng mơ ước trở thành một tác giả manga, nhưng những nhân vật phản diện và hành động xấu xa không dễ dàng đến với anh ta, vì anh ta ít có kinh nghiệm hoặc không có khuynh hướng tự nhiên cho chúng. Mọi thứ bất ngờ thay đổi khi anh ta tình cờ gặp một gia đình từng được miêu tả là lý tưởng nhưng nay không còn nữa. Anh ta sử dụng tình huống thực tế này cho công việc của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masaki Suda","avatar":""},{"name":"Fukase","avatar":""},{"name":"Mitsuki Takahata","avatar":""},{"name":"Shido Nakamura","avatar":""},{"name":"Shun Oguri","avatar":""},{"name":"Akiyoshi Nakao","avatar":""},{"name":"Youji Matsuda","avatar":""},{"name":"Tomu Miyazaki","avatar":""},{"name":"Takashi Okabe","avatar":""},{"name":"Jun Hashizume","avatar":""},{"name":"Hijiri Kojima","avatar":""},{"name":"Ai Mikami","avatar":""},{"name":"Ryushin Tei","avatar":""},{"name":"Shigemitsu Ogi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Kyarakuta","Kyarakutā","Kyarakutaa","漫畫殺人狂","캐릭터","キャラクター"]', 1784690324317);
