INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngo-long', 'Ngộ Long', 'Miss The Dragon', 'https://phimimg.com/upload/vod/20250205-1/667c2f91452eb38945b290aa24f9014b.jpg', 'https://phimimg.com/upload/vod/20250205-1/0112607473363c135bc7f5d0c0d735d7.jpg', '<p>Ngộ Long là phim Cổ Trang kể về một cô nha hoàn tên Lưu Huỳnh (Chúc Tự Đan thủ vai) trong một lần tình cờ đã giúp tiểu thư Hạ Hầu Tuyết (Phan Mỹ Diệp đóng) cứu một con rắn, nhưng trái thay con rắn đó lại là một con rồng tu luyện ngàn năm tên là Úy Trì Long Viêm (Vương Hạc Đệ đảm nhận). Để đáp lại ân tình này nên anh đã đưa Lưu Huỳnh rời đi và muốn thành thân với nàng, nhưng vô tình lại khiến Hạ Hầu Tuyết nghĩ rằng cô bị mất tích. Trên đường đi tìm thì gặp phải Lang yêu và cuối cùng chết trong tay Úy Trì Long Viêm.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hạc Đệ","avatar":""},{"name":"Chúc Tự Đan","avatar":""},{"name":"Đặng Vi","avatar":""},{"name":"Phan Mỹ Hoa","avatar":""},{"name":"Chu Tán Cẩm","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["A Noiva do Dragão","Miss The Dragon","삼생 초월 로맨스 우룡","우룡","Скучаю по дракону","Повстречавшая дракона","Встретиться с драконом","遇龙"]', 1784690324317);
