INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngo-long', 'Ngộ Long', 'Miss The Dragon', 'ngộ long miss the dragon vương hạc đệ chúc tự đan đặng vi phan mỹ hoa chu tán cẩm a noiva do dragão miss the dragon 삼생 초월 로맨스 우룡 우룡 скучаю по дракону повстречавшая дракона встретиться с драконом 遇龙', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dai-dien-thoi-gian-phan-3', 'Người Đại Diện Thời Gian (Phần 3)', 'Link Click (Season 3)', 'https://phimimg.com/upload/vod/20250125-1/87d06d0ad91741ab28de4e65c90a93ba.jpg', 'https://phimimg.com/upload/vod/20250125-1/16173edd865d90aa609776eb316b0014.jpg', '<p>Ở một góc nào đó trong đô thị sầm uất, có một cửa hiệu tên là &quot;Tiệm chụp ảnh Thời Quang&quot; vẫn ngày ngày chăm chỉ hoạt động. Tuy trước sân trông lúc nào cũng vắng vẻ nhưng thật ra hai cậu chủ tiệm lại là người có năng lực đặc biệt - Trình Tiểu Thời và Lục Quang. Để hoàn thành yêu cầu của khách hàng, Lục Quang và Trình Tiểu Thời lập nhóm phối hợp với nhau, sử dụng siêu năng lực để tiến vào trong ảnh chụp. Thế nhưng sự việc lại không đơn giản như bọn họ nghĩ.</p>', 'Tập 6', 12, 'hoathinh', 'ongoing', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Su Shangqing","avatar":""},{"name":"Yang Tianxiang","avatar":""},{"name":"Li Shimeng","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Shi Guang Dai Li Ren","Shiguang Dailiren","时光代理人 第二季","时光代理人 英都篇","时光代理人 第三季","時光代理人 - LINK CLICK- Ⅱ","시광대리인 -Link Click-","Агенты времени","Агент времени","Агенти часу","Link Click","Link Click II","Link Click III","Link Click: Bridon Arc","Người Đại Diện Thời Gian","时光代理人"]', 1784690324317);
