INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-gia-2021', 'Bố Già', 'Dad, I''m Sorry', 'https://phimimg.com/upload/vod/20250119-1/f42aefe12ee48db50ee7c465efb85798.jpg', 'https://phimimg.com/upload/vod/20250119-1/78ea9e50373b3ac2e51a8fa6b147984f.jpg', '<p>Câu chuyện về Ba Sang - con thứ hai trong 4 anh em ồn ào: Giàu, Sang, Phú, Quý. Ba Sang là một người ga lăng, “quá” tốt bụng và luôn hy sinh vì người khác dù họ có muốn hay không. Quân - Ba Sang’s son là một Youtuber trẻ hiện đại.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Trấn Thành","avatar":""},{"name":"Tuấn Trần","avatar":""},{"name":"Ngân Chi","avatar":""},{"name":"Ngọc Giàu","avatar":""},{"name":"Lê Giang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324317);
