INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rang-buoc-phan-2', 'Ràng Buộc (Phần 2)', 'BONDING (Season 2)', 'https://phimimg.com/upload/vod/20240109-1/8c800781cbed90fb6827a09f2afe0ab1.jpg', 'https://phimimg.com/upload/vod/20240109-1/53e28a93f9ad74e434dfef5b02652c8e.jpg', '<p>Nhẵn túi và bị cấm cửa ở mọi động tại Thành phố New York, đôi bạn thân Tiff và Pete cố gắng gây dựng lại danh tiếng trong cộng đồng BDSM.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zoe Levin","avatar":""},{"name":"Brendan Scannell","avatar":""},{"name":"Micah Stock","avatar":""},{"name":"Theo Stockman","avatar":""},{"name":"Nana Mensah","avatar":""},{"name":"Alex Hurt","avatar":""},{"name":"D''Arcy Carden","avatar":""},{"name":"Gabrielle Ryan","avatar":""},{"name":"Charles Gould","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324317);
