INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-bien-chesapeake-phan-5', 'Bờ biển Chesapeake (Phần 5)', 'Chesapeake Shores (Season 5)', 'https://phimimg.com/upload/vod/20250115-1/8058063e68ffb0023d615dac4f21cefb.jpg', 'https://phimimg.com/upload/vod/20250115-1/aed2a210161386e37e4271b9797eecf9.jpg', '<p>Abby O&#39;Brien Winters trở về quê nhà Chesapeake Shores, Maryland, từ New York sau khi nhận được cuộc gọi hoảng loạn từ cô em gái út Jess, người đang cải tạo Nhà trọ tại Eagle Point. Sự nghiệp đầy thách thức, cuộc ly hôn và những cô con gái nhỏ của Abby khiến cô quá bận rộn đến nỗi không thể nghĩ đến thị trấn mà cha cô đã xây dựng. Việc cứu nhà trọ của chị gái cô khỏi bị tịch thu không chỉ có nghĩa là phải đối phó với gia đình tan vỡ của cô mà còn phải đối phó với Trace Riley, mối tình đầu của cô mà cô đột ngột rời xa mười sáu năm trước. Ban đầu, anh là một trở ngại nhưng trở thành đồng minh bất ngờ và là cơ hội thứ hai để tìm thấy tình yêu. Động thái gia đình đầy rắc rối trở nên căng thẳng hơn khi người mẹ xa cách của Abby trở về thị trấn.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Meghan Ory","avatar":""},{"name":"Laci J. Mailey","avatar":""},{"name":"Emilie Ullerup","avatar":""},{"name":"Barbara Niven","avatar":""},{"name":"Robert Buckley","avatar":""},{"name":"Brendan Penny","avatar":""},{"name":"Andrew Francis","avatar":""},{"name":"Treat Williams","avatar":""},{"name":"Diane Ladd","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["切萨皮克湾","Chesapeake Shores"]', 1784690324317);
