INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toan-chuc-phap-su-phan-5', 'Toàn Chức Pháp Sư (Phần 5)', 'Quanzhi Fashi (Season 5)', 'https://phimimg.com/upload/vod/20240215-1/6c8b9bd2e90e7d9882037018b3d3caef.jpg', 'https://phimimg.com/upload/vod/20240215-1/c33d9c94765a152285476d3b54d6269b.jpg', '<p>Mạc Phàm phát hiện tuyệt đại đa số mọi người đều chỉ có thể tu luyện được một hệ phép thuật mà chính mình nhưng là toàn hệ toàn năng pháp sư. Bên ngoài thành phố, lũ yêu ma quỷ quái đang nhìn chằm chằm loài người như hổ đói, chực chờ tấn công. Thế giới vốn tôn sùng khoa học giờ đây tôn sùng Ma pháp…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2021, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lu Zhao","avatar":""},{"name":"Dawei Shen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324317);
