INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-linh-huyen-tuong-ky-phan-1', 'Tinh Linh Huyễn Tưởng Ký (Phần 1)', 'Seirei Gensouki: Spirit Chronicles (Season 1)', 'https://phimimg.com/upload/vod/20241118-1/e7572801c01ab66dd4c92e5a378ba7d5.jpg', 'https://phimimg.com/upload/vod/20241118-1/3c33bfb6752affa10364bcf137b9665d.jpg', '<p>Amakawa Haruto, một sinh viên bị tai nạn chết đi trong khi vẫn nặng lòng về mối tình đầu thuở ấu thơ với Ayase Miharu. Hắn được chuyển sinh sang một thế giới khác sống với thân phận Rio nhưng vẫn lưu giữ ký ức của tiền kiếp.

Một thế giới huyền ảo khắc nghiệt, Rio mồ côi mang theo mối thù giết mẹ, một ngày nọ có một cô công chúa bị bắt cóc, hắn vô tình giải cứu được cô nàng và từ đó cuộc đời Rio đã rẽ sang một bước ngoặt hoàn toàn mới.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Ayaka Suwa","avatar":""},{"name":"Akane Fujita","avatar":""},{"name":"Yuuki Kuwahara","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Seirei Gensouki","Seirei Gensōki","精霊幻想記2","정령환상기","Мифический Дух: Хроники","精霊幻想記"]', 1784690324317);
