INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-tay-ao-mau-do', 'Cổ Tay Áo Màu Đỏ', 'The Red Sleeve', 'https://phimimg.com/upload/vod/20240615-1/1fd24a1303d14cee0de8ee453092903a.jpg', 'https://phimimg.com/upload/vod/20240615-1/5f40cf6154a898afe50bb5952ab37b6c.jpg', '<p>Cổ Tay Áo Màu Đỏ - The Red Sleeve lấy bối cảnh thời Joseon, xoay quanh câu chuyện tình lãng mạn chốn cung đình giữa một cung nữ - người một lòng muốn bảo vệ hoàng đế và một vị vua có trách nhiệm đặt an nguy quốc gia lên trước tình yêu. Junho vào vai Yi San, người mang tính cách lạnh lùng, sinh ra là hậu duệ thừa kế ngai vàng. Yi San không ngừng nỗ lực để trở thành một hoàng đế tốt, nhưng lại chịu tổn thương khi chứng kiến cái chết của cha mình. Số phận run rủi để Yi San gặp được cung nữ Seong Deok Im (Lee Se Young) và rơi vào lưới tình với nàng. Yi San buộc phải chọn giữa quốc gia và người phụ nữ mình yêu say đắm.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jun-ho","avatar":""},{"name":"Lee Se- young","avatar":""},{"name":"Kang Hoon","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324317);
