INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-la-gia-dinh-trong-mo-cua-toi', 'Hãy Là Gia Đình Trong Mơ Của Tôi', 'Be My Dream Family', 'https://phimimg.com/upload/vod/20241230-1/1442bfcfb5d86752517eee52702d3054.jpg', 'https://phimimg.com/upload/vod/20241230-1/1a3e178c6328ea72695fc137e20dff28.jpg', '<p>Hai nhà họ Geum và Han có những quan điểm khác nhau về cuộc sống và gia đình. Khi cha mẹ hai bên tái hôn vào lúc hoàng hôn của cuộc đời, họ bất đắc dĩ trở thành một gia đình. Khác nhau về quan điểm nên những xung đột là điều không thể tránh khỏi, nhưng cảm thông và thấu hiểu sẽ kéo họ gần nhau hơn.</p>', 'Hoàn Tất (120/120)', 120, 'series', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Jung-woo","avatar":""},{"name":"Park Joon-geum","avatar":""},{"name":"Hahm Eun-jung","avatar":""},{"name":"Wang Ji-hye","avatar":""},{"name":"Joo Ah-reum","avatar":""},{"name":"Ryu Jin","avatar":""},{"name":"Park Tam-hee","avatar":""},{"name":"Ok Jin-uk","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["일일연속극 속아도 꿈결","Sokado Ggumgyeol","속아도 꿈결"]', 1784690324317);
