INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('horimiya', 'Horimiya', 'Horimiya', 'https://phimimg.com/upload/vod/20241229-1/4f8b65a5846a8e592fddaa06ecd87809.jpg', 'https://phimimg.com/upload/vod/20241229-1/008d822472339cb644a5ce65c1dd74d2.jpg', '<p>Có bí mật là rất thích ở nhà, cô nàng nổi tiếng và thân thiện kết thân với cậu bạn mọt sách cùng lớp – người giấu đi hình xăm và khuyên của mình khi ở trường.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Haruka Tomatsu","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Seiichiro Yamashita","avatar":""},{"name":"Yurie Kozakai","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Reina Kondo","avatar":""},{"name":"Daiki Yamashita","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Shoya Chiba","avatar":""},{"name":"Momo Asakura","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Yuka Terasaki","avatar":""},{"name":"Hisako Kanemoto","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["堀与宫村","动画 堀与宫村","Horimiya","ホリミヤ","アニメ ホリミヤ","Хорі-сан і Міямура-кун","Хорі та Міямура","Hori-san and Miyamura-kun","HoriMiya"]', 1784690324317);
