INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('horimiya', 'Horimiya', 'Horimiya', 'horimiya horimiya haruka tomatsu koki uchiyama seiichiro yamashita yurie kozakai nobuhiko okamoto mao ichimichi reina kondo daiki yamashita jun fukuyama taku yashiro shoya chiba momo asakura daisuke ono ai kayano yuka terasaki hisako kanemoto 堀与宫村 动画 堀与宫村 horimiya ホリミヤ アニメ ホリミヤ хорі-сан і міямура-кун хорі та міямура hori-san and miyamura-kun horimiya', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-de-nhat-the-gioi-chuyen-sinh-thanh-quy-toc-o-the-gioi-khac', 'Sát Thủ Đệ Nhất Thế Giới Chuyển Sinh Thành Quý Tộc Ở Thế Giới Khác', 'The World''s Finest Assassin Gets Reincarnated in Another World as an Aristocrat', 'https://phimimg.com/upload/vod/20241228-1/0c4134bdab3dc56ac5a35a5aec45c31b.jpg', 'https://phimimg.com/upload/vod/20241228-1/18931fe84080dd867da0f9b785c59ccf.jpg', '<p>&quot;Tôi sẽ sống cho chính mình!&quot; Sát thủ vĩ đại nhất trên Trái đất chỉ biết cách sống như một công cụ cho chủ nhân của mình - cho đến khi họ ngừng để anh ta sống. Được tái sinh bởi ân sủng của một nữ thần vào một thế giới của kiếm và ma thuật, lần này anh ta có cơ hội làm những điều khác đi, nhưng có một cái bắt ... thế giới trừ khi anh ta bị dừng lại. Bây giờ được biết đến với cái tên Lugh Tuatha Dé, sát thủ bậc thầy chắc chắn đã bó tay, đặc biệt là vì toàn những cô gái xinh đẹp luôn vây quanh anh ta. L Dù có thể là một kẻ giết người không thể so sánh được, nhưng anh ta sẽ chống lại kẻ thù bằng phép thuật mạnh mẽ như thế nào?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kenji Akabane","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Yuuki Takada","avatar":""},{"name":"Shino Shimoji","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Chiaki Takahashi","avatar":""},{"name":"Yukari Tamura","avatar":""},{"name":"Junpei Morita","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["世界顶尖的暗杀者转生为异世界贵族","世界顶尖的暗杀者转生成为异世界贵族","世界最强暗杀者转生成异世界贵族","Sekai Saikou no Assassin","Sekai Saikō no Ansatsusha, Isekai Kizoku ni Tensei Suru","Sekai Saikou no Ansatsusha, Isekai Kizoku ni Tensei suru","Sekai Saikou no Assassin, Isekai Kizoku ni Tensei Suru","暗殺貴族","Найкращий у світі вбивця перероджується в іншому світі аристократом","Найкращий у світі асасин перероджується в іншому світі аристократом","Найкращий у світі асасин переродився в іншому світі як аристократ","The World''s Finest Assassin Gets Reincarnated in Another World as an Aristocrat","世界最高の暗殺者、異世界貴族に転生する"]', 1784690324317);
