INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-thu-de-nhat-the-gioi-chuyen-sinh-thanh-quy-toc-o-the-gioi-khac', 'Sát Thủ Đệ Nhất Thế Giới Chuyển Sinh Thành Quý Tộc Ở Thế Giới Khác', 'The World''s Finest Assassin Gets Reincarnated in Another World as an Aristocrat', 'sát thủ đệ nhất thế giới chuyển sinh thành quý tộc ở thế giới khác the world''s finest assassin gets reincarnated in another world as an aristocrat kenji akabane reina ueda yuuki takada shino shimoji toshiyuki morikawa chiaki takahashi yukari tamura junpei morita 世界顶尖的暗杀者转生为异世界贵族 世界顶尖的暗杀者转生成为异世界贵族 世界最强暗杀者转生成异世界贵族 sekai saikou no assassin sekai saikō no ansatsusha, isekai kizoku ni tensei suru sekai saikou no ansatsusha, isekai kizoku ni tensei suru sekai saikou no assassin, isekai kizoku ni tensei suru 暗殺貴族 найкращий у світі вбивця перероджується в іншому світі аристократом найкращий у світі асасин перероджується в іншому світі аристократом найкращий у світі асасин переродився в іншому світі як аристократ the world''s finest assassin gets reincarnated in another world as an aristocrat 世界最高の暗殺者、異世界貴族に転生する', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-va-antifan-ket-hon-2021', 'Tôi Và Anti-fan Kết Hôn', 'So I Married The Anti-Fan', 'https://phimimg.com/upload/vod/20241228-1/4a50905353b4c3e789fc72070fe0d1b8.jpg', 'https://phimimg.com/upload/vod/20241228-1/aa43c408231f7ea5a5d3a23ba6a815c1.jpg', '<p>Ngôi sao K-pop Hoo Joon và phóng viên tạp chí Lee Geun Young, cũng là anti-fan của anh, vô tình phải sống cùng nhau và mở ra một chuyện tình lãng mạn hấp dẫn.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Tae-joon","avatar":""},{"name":"Choi Soo-young","avatar":""},{"name":"Hwang Chan-seong","avatar":""},{"name":"Han Ji-an","avatar":""},{"name":"Kim Min-gue","avatar":""},{"name":"Kim Ha-kyung","avatar":""},{"name":"Kim Sun-hyuk","avatar":""},{"name":"Dong Hyun-bae","avatar":""},{"name":"Im Do-yoon","avatar":""},{"name":"Kim Min-kyo","avatar":""},{"name":"Park Mi-ri","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["所以我和黑粉结婚了","Geuraeseo Naneun Antipaengwa Gyeolhonhaedda","So I Married the Anti-Fan","So I Married My Anti-Fan","그래서 나는 안티팬과 결혼했다"]', 1784690324317);
