INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dai-dien-thoi-gian-phan-1', 'Người Đại Diện Thời Gian (Phần 1)', 'Link Click (Season 1)', 'https://phimimg.com/upload/vod/20241215-1/0bacd2d822c1b35c4274b53ecf5af6ad.jpg', 'https://phimimg.com/upload/vod/20241215-1/bc73d4d1bab2af9db0ab34fc39965794.jpg', '<p>Ở một góc nào đó trong đô thị sầm uất, có một cửa hiệu tên là &quot;Tiệm chụp ảnh Thời Quang&quot; vẫn ngày ngày chăm chỉ hoạt động. Tuy trước sân trông lúc nào cũng vắng vẻ nhưng thật ra hai cậu chủ tiệm lại là người có năng lực đặc biệt - Trình Tiểu Thời và Lục Quang. Để hoàn thành yêu cầu của khách hàng, Lục Quang và Trình Tiểu Thời lập nhóm phối hợp với nhau, sử dụng siêu năng lực để tiến vào trong ảnh chụp. Thế nhưng sự việc lại không đơn giản như bọn họ nghĩ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Su Shangqing","avatar":""},{"name":"Yang Tianxiang","avatar":""},{"name":"Li Shimeng","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Shi Guang Dai Li Ren","Shiguang Dailiren","时光代理人 第二季","时光代理人 英都篇","时光代理人 第三季","時光代理人 - LINK CLICK- Ⅱ","시광대리인 -Link Click-","Агенты времени","Агент времени","Агенти часу","Link Click","Link Click II","Link Click III","Link Click: Bridon Arc","Người Đại Diện Thời Gian","时光代理人"]', 1784690324317);
