INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-ac-ma-cha-thien-su', 'Mẹ Ác Ma Cha Thiên Sứ', 'Mother Evil Father Angel', 'https://phimimg.com/upload/vod/20241215-1/e651d577e71bd5a2bc097bce4a1e5d3a.jpg', 'https://phimimg.com/upload/vod/20241215-1/d48dba41b2521048b0646c5bee2a0be7.jpg', '<p>Câu chuyện xoay quanh gia đình nhỏ vui vẻ đầm ấm của Tất Thắng (Minh Hằng), Tấn Lộc (Huy Anh) và cô con gái Trâm Anh mới lên sáu. Đến một ngày, Võ Tất Thắng bỗng phát hiện ra nhiều bà mẹ quanh mình đã chuẩn bị đầy đủ mọi thứ cho tương lai của con ngay từ khi vào lớp 1. Để con có được tương lai tốt, Tất Thắng không ngần ngại dùng những phương pháp hà khắc và đặt nhiều yêu cầu cao cho con mình. Cách dạy con trái ngược của hai vợ chồng cùng sự tác động của người ngoài, đã phần nào khiến cuộc hôn nhân đứng trước nguy cơ đổ vỡ. May mắn thay, theo thời gian, sóng gió cũng qua đi khi cả ba cùng nhìn lại tình cảm dành cho nhau.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thanh Thủy","avatar":""},{"name":"Công Ninh","avatar":""},{"name":"Trung Dân","avatar":""},{"name":"Minh Hằng","avatar":""},{"name":"Khả Như","avatar":""},{"name":"Ngân Chi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Adventures on Orsum Island"]', 1784690324317);
