INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiem-do-quai-di', 'Tiệm Đồ Quái Dị', 'Used Good', 'https://phimimg.com/upload/vod/20241203-1/0a59934c0204f660efa929d663b1893a.jpg', 'https://phimimg.com/upload/vod/20241203-1/d33e7725c2e34552d1c47a8a93afe922.jpg', '<p>Lúc nhỏ, Vi Đức Tín (do Hà Quảng Bái đóng) bị sốc nặng do cái chết của cha. Từ đó, Tín thay đổi tính cách, mất hết ký ức về cha. Mẹ của Tín là Tạ Mỹ Thường (do Lâm Y Kỳ đóng) và cậu Tạ Thiêm Thắng (do Tào Vĩnh Liêm đóng) vì bảo vệ Tín mà không nhắc đến cái chết của cha anh.

Trong một dịp tình cờ, Đức Tín đã quen biết với con gái chủ tiệm đồ cũ là Phùng Tổ Nghi (do Trần Hiểu Hoa đóng). Tổ Nghi đã có bạn trai là bác sĩ Lý Chí Hằng (do Ngô Nghiệp Khôn đóng). Tín phát hiện mình có cảm ứng đặc biệt với đồ vật cũ. Chính vì vậy, Tín và Nghi đã giúp nhiều người gỡ nút thắt trong lòng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 18, 2021, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Tào Vĩnh Liêm","avatar":""},{"name":"Trần Hiểu Hoa","avatar":""},{"name":"Ngô Nghiệp Khôn","avatar":""},{"name":"Hà Quảng Bái","avatar":""},{"name":"Lâm Y Kỳ","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["異搜店","Used Good"]', 1784690324317);
