INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dua-tre-cuoi-cung-tren-trai-dat-chuc-tan-the-vui-ve', 'Những đứa trẻ cuối cùng trên Trái Đất: Chúc tận thế vui vẻ', 'The Last Kids on Earth: Happy Apocalypse to You', 'https://phimimg.com/upload/vod/20241123-1/8a8f61ecc11a907bb0e221078f70402a.jpg', 'https://phimimg.com/upload/vod/20241123-1/95f15c81e994be3dd62ea930b8c1b094.jpg', '<p>Hãy giúp Jack và hội bạn chiến đấu với quái vật đưa ra lựa chọn để sống sót – và vui chơi – trong cuộc phiêu lưu tương tác &quot;Những đứa trẻ cuối cùng trên Trái Đất&quot; này!</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Nick Wolfhard","avatar":""},{"name":"Charles Demers","avatar":""},{"name":"Montse Hernandez","avatar":""},{"name":"Garland Whitt","avatar":""},{"name":"Bruce Campbell","avatar":""},{"name":"Catherine O''Hara","avatar":""},{"name":"Brian Drummond","avatar":""},{"name":"Giles Panton","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Ostatnie dzieciaki na Ziemi: Wszystkiego apokaliptycznego!","Jack, der Monsterschreck: Alles Gute zur Apokalypse","ラスト・キッズ・オン・アース: 世界の終わりオメデトウ!","The Last Kids on Earth: Happy Apocalypse to You"]', 1784690324317);
