INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-thu-qua-den-va-tien-sinh-than-lan', 'Tiểu Thư Quạ Đen Và Tiên Sinh Thằn Lằn', 'Miss Crow With Mr. Lizard', 'https://phimimg.com/upload/vod/20241117-1/d9fb042360a3a8987ce0b026e648d864.jpg', 'https://phimimg.com/upload/vod/20241117-1/fa200c5daee565373424c6cca2a61a5b.jpg', '<p>Phim chủ yếu xoay quanh nhân vật Cố Xuyên (Nhậm Gia Luân) từng là một thanh niên vui vẻ, đam mê cuộc sống nhưng lại trở thành &quot;xác chết&quot; biết đi do gặp tai nạn ô tô dẫn đến tổn thương tim nghiêm trọng. Dù đã trải qua ca ghép tim nhưng Cố Xuyên không thể thực hiện các bài tập vận động mạnh cũng như cảm xúc mãnh liệt như trước kia.Vì chỉ có thể sống dựa vào trái tim nhân tạo nên cuộc sống của anh mất đi sự vui vẻ tươi tắn trước đó. Thay vào đó, anh dần trở nên bi quan, thờ ơ với cuộc sống.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Hình Phi","avatar":""},{"name":"Lưu Nhuế Lân","avatar":""},{"name":"Triệu Dịch Hoan","avatar":""},{"name":"Cát Thi Mẫn","avatar":""},{"name":"Tuấn Thanh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Miss Crow And Mr Lizard","까마귀양과 도마뱀군","오아소저여석척선생","烏鴉小姐與蜥蜴先生","乌鸦小姐与蜥蜴先生"]', 1784690324317);
