INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hank-va-ban-xe-tai-cho-rac-phan-2', 'Hank Và Bạn Xe Tải Chở Rác (Phần 2)', 'Trash Truck (Season 2)', 'https://phimimg.com/upload/vod/20241114-1/c47a3bd496db97c91fffa133a089030d.jpg', 'https://phimimg.com/upload/vod/20241114-1/3276f2ac9235cd82b50ccee2e44354c3.jpg', '<p>Trí tưởng tượng đưa Hank, Xe Rác, hội bạn động vật Walter, Donny và cô Mona vào những cuộc phiêu lưu ấm lòng ở sân sau và xa hơn nữa!</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Henry Keane","avatar":""},{"name":"Glen Keane","avatar":""},{"name":"Lucas Neff","avatar":""},{"name":"Brian Baumgartner","avatar":""},{"name":"Jackie Loeb","avatar":""},{"name":"Olive Keane","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["小汉克和垃圾车","宝贝呠呠垃圾车","내친구 청소차","Gran Camión","De vuilniswagen","Śmieciarka","Giant Jack","Trash Truck"]', 1784690324317);
