INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-van-cach-yeu', 'Muôn Vàn Cách Yêu', 'Brilliant Girls', 'https://phimimg.com/upload/vod/20241113-1/e3944347f799eefaa1ef15518416f8b5.jpg', 'https://phimimg.com/upload/vod/20241113-1/1f718a87ec3b0c1354b9c3427a7d2706.jpg', '<p>Phim Muôn Vàn Cách Yêu - Brilliant Girls kể về 5 cô gái với 5 tính cách khác nhau, trải qua khó khăn trong cuộc sống tìm lại chính mình. Đới Hi Hi trong lúc nhất thời không có nơi nào để đi, sống nhờ nhà Đinh Cối Kiều, bắt đầu lại cuộc sống, nhưng vô tình trở thành oan gia với nhà thiết kế hôn lễ thuê trước ở đây - Ôn Như Tuyết. Mặc dù về diện mạo, Đinh Cối Kiều không hề thua kém Ôn Như Tuyết, nhưng cô ấy là một nữ cường nhân IQ cao, EQ cao, coi công việc là mục tiêu quan trọng nhất trong đời. Còn Ôn Tiểu Dương tới Thượng Hải theo đuổi giấc mơ làm họa sĩ manga, trở thành một thành viên trong ngôi nhà. Các cô gái sống chung dưới một mái nhà, từ va chạm mâu thuẫn với nhau dần trở thành chỗ dựa cho nhau.</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yin Tao","avatar":""},{"name":"Song Yi","avatar":""},{"name":"Zhao Jinmai","avatar":""},{"name":"Hu Lianxin","avatar":""},{"name":"Guo Tong Tong","avatar":""},{"name":"Wei Daxun","avatar":""},{"name":"Yang Shuo","avatar":""},{"name":"Sun Yizhou","avatar":""},{"name":"Tan Kai","avatar":""},{"name":"Wang Youjun","avatar":""},{"name":"Zhang Junming","avatar":""},{"name":"Nita Xia","avatar":""},{"name":"Wang Ruixin","avatar":""},{"name":"Hu Linxi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["新粉红女郎","涩女郎","Astringent Girl","Brilliantgirls","Brilliant Girls","爱的理想生活"]', 1784690324317);
