INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-dan-ong-yeu', 'Khi Đàn Ông Yêu', 'Man in Love', 'https://phimimg.com/upload/vod/20241112-1/2d2e0e7362e876ae58bd0a8f5ba685f8.jpg', 'https://phimimg.com/upload/vod/20241112-1/f8e9565f268b5642e2316af674793b17.jpg', '<p>Một người đòi nợ đã thỏa thuận với một người phụ nữ mắc nợ đang phải vật lộn để chăm sóc người cha đau yếu của mình: anh ta sẽ trả các hóa đơn cho cô nếu cô đồng ý hẹn hò với anh ta.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Roy Chiu","avatar":""},{"name":"Tiffany Hsu","avatar":""},{"name":"Tsai Chen-Nan","avatar":""},{"name":"Hsin-Ling Chung","avatar":""},{"name":"Lan Wei-Hua","avatar":""},{"name":"Peace Yang","avatar":""},{"name":"LULU Huang","avatar":""},{"name":"Bai Xiao-Ying","avatar":""},{"name":"Ching-Pu Tan","avatar":""},{"name":"Xavier Lin","avatar":""},{"name":"Kurt Hsiao","avatar":""},{"name":"Chih-ju Lin","avatar":""},{"name":"Chun Hong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["当男人恋爱时 台湾版","Man in Love","ผ่อนรักระยะยาว","當男人戀愛時"]', 1784690324317);
