INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('le-vuong-lee-bang-won', 'Lệ Vương, Lee Bang Won', 'The King of Tears, Lee Bang Won', 'https://phimimg.com/upload/vod/20241110-1/7d374c0ff58d2dfe2c83f3608940353c.jpg', 'https://phimimg.com/upload/vod/20241110-1/d9ef5bb92a87fd853212af6590888e43.jpg', '<p>Chuyện phim về ông vua lắm thị phi nhất thời Joseon, Lee Bang Won, người đã sát hại tất cả anh em của mình để lên ngôi. Đây có thể được xem là Games of Thrones phiên bản Hàn Quốc.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ju Sang-uk","avatar":""},{"name":"Kim Yeong-cheol","avatar":""},{"name":"Park Jin-hee","avatar":""},{"name":"Ye Ji-won","avatar":""},{"name":"Lee Kwang-gi","avatar":""},{"name":"Ye Su-jeong","avatar":""},{"name":"Kim Myung-soo","avatar":""},{"name":"Hong Kyung-in","avatar":""},{"name":"Nam Myung-ryeol","avatar":""},{"name":"Tae Hang-ho","avatar":""},{"name":"Jeong Tae-woo","avatar":""},{"name":"Kim Min-ki","avatar":""},{"name":"Sun Dong-hyuk","avatar":""},{"name":"Choi Jong-hwan","avatar":""},{"name":"Lee Tae-ri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["The Great King Yi Bang Won","Taejong Lee Bang Won","Taejong Ibangwon","태종 이방원","The Great King Lee Bang Won","Taejong Lee Bang-won"]', 1784690324317);
