INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('le-vuong-lee-bang-won', 'Lệ Vương, Lee Bang Won', 'The King of Tears, Lee Bang Won', 'lệ vương, lee bang won the king of tears, lee bang won ju sang-uk kim yeong-cheol park jin-hee ye ji-won lee kwang-gi ye su-jeong kim myung-soo hong kyung-in nam myung-ryeol tae hang-ho jeong tae-woo kim min-ki sun dong-hyuk choi jong-hwan lee tae-ri the great king yi bang won taejong lee bang won taejong ibangwon 태종 이방원 the great king lee bang won taejong lee bang-won', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-dien-bao-thu', 'Gã Điên Báo Thù', 'Wrath Of Man', 'https://phimimg.com/upload/vod/20231019-1/36ec5f59af35ff8830dfc0df27c12b8f.jpg', 'https://phimimg.com/upload/vod/20231019-1/23cb1a5351b176c8f708b871d934055b.jpg', '<p>Một nhân viên bảo vệ mới lạnh lùng và bí ẩn cho một công ty xe tải chở tiền ở Los Angeles đã gây bất ngờ cho đồng nghiệp khi anh ta thể hiện những kỹ năng chính xác trong một vụ trộm. Phi hành đoàn còn lại tự hỏi anh ta là ai và anh ta đến từ đâu. Chẳng bao lâu, động cơ cuối cùng của tay thiện xạ trở nên rõ ràng khi anh ta thực hiện các bước ấn tượng và không thể thay đổi để giải quyết một điểm số.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub + Thuyết Minh', 'HD', 'Anh', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Josh Hartnett","avatar":""},{"name":"Scott Eastwood","avatar":""},{"name":"Darrell D''Silva","avatar":""},{"name":"Babs Olusanmokun","avatar":""},{"name":"Jeffrey Donovan","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Andy García","avatar":""},{"name":"Niamh Algar","avatar":""},{"name":"Alex Ferns","avatar":""},{"name":"Laz Alonso","avatar":""},{"name":"Deobia Oparei","avatar":""},{"name":"Chris Reilly","avatar":""},{"name":"Raúl Castillo","avatar":""},{"name":"Post Malone","avatar":""},{"name":"Lyne Renee","avatar":""},{"name":"Roc","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324317);
