INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-cuop-tinh-yeu', 'Kẻ Cướp Tình Yêu', 'Amor Bandido', 'https://phimimg.com/upload/vod/20241109-1/24f3495e3fcee9bf33d31a9611c82192.jpg', 'https://phimimg.com/upload/vod/20241109-1/2967eabc2e333e0437a53ea5ad8a46c9.jpg', '<p>Joan là một cô gái 16 tuổi ngây thơ và dễ yêu. Một ngày nọ, anh quyết định trốn đến các tỉnh cùng với Luciana, một phụ nữ 35 tuổi xinh đẹp và là giáo viên ở trường anh, để được tự do kiềm chế tình yêu của mình. Chẳng bao lâu, Joan kinh hoàng phát hiện ra rằng cô đã rơi vào một cái bẫy đan xen giữa tình dục, tiền bạc, chính trị và bạo lực.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'FHD', 'Argentina', 0, '[{"name":"Renato Quattordio","avatar":""},{"name":"Romina Ricci","avatar":""},{"name":"Rafael Ferro","avatar":""},{"name":"Mónica Gonzaga","avatar":""},{"name":"Sergio Prina","avatar":""},{"name":"Susana Manchini","avatar":""},{"name":"Carlos Mena","avatar":""},{"name":"Jorge Prado","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Amor bandido"]', 1784690324317);
