INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-trang-than-yeu', 'Quân Trang Thân Yêu', 'My Dear Guardian', 'https://phimimg.com/upload/vod/20241106-1/ee2e6b3a949ffe3dd5260a8f12402848.jpg', 'https://phimimg.com/upload/vod/20241106-1/58c3ad35774b1b5215bf1768125e63b7.jpg', '<p>Quân Trang Thân Yêu (My Dear Guardian) là bộ phim kể về quá trình gặp gỡ, quen biết rồi yêu nhau giữa Lương Mục Trạch, thiếu tá có triển vọng nhất trong đại đội đặc chủng quân khu G và Hạ Sơ, bác sĩ của đội cứu trợ y tế nước ngoài. Họ cùng nhau vượt qua vụ bắt cóc khủng bố, tiêu diệt băng nhóm tội phạm đánh cắp bí mật quân sự, cuối cùng là quét sạch thế lực tội phạm, là câu chuyện lãng mạn của người lính vừa hoàn thành sứ mệnh quân sự vừa bảo vệ người mình yêu.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Johnny Huang","avatar":""},{"name":"Li Qin","avatar":""},{"name":"Yang Shu","avatar":""},{"name":"Nie Zihao","avatar":""},{"name":"Yuan Jiang","avatar":""},{"name":"Zhao Xun","avatar":""},{"name":"Fu Chengpeng","avatar":""},{"name":"Xu Hong Hao","avatar":""},{"name":"Liu Xiao Jie","avatar":""},{"name":"Finn Han","avatar":""},{"name":"Yu Yue","avatar":""},{"name":"Ou Hao","avatar":""},{"name":"Ruiling Xiong","avatar":""},{"name":"Zhong Lili","avatar":""},{"name":"Xia Hou Bin","avatar":""},{"name":"Xie Xian","avatar":""},{"name":"Shen Lu","avatar":""},{"name":"Zhang Zhijian","avatar":""},{"name":"Guan Yajun","avatar":""},{"name":"Gu Yuhan","avatar":""},{"name":"Zhou Huilin","avatar":""},{"name":"Zhang Jin","avatar":""},{"name":"Che","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["亲爱的戎装","军装下的绕指柔","Dear Military Uniform","My Dear Guardian","Round Fingers Under Military Uniforms","ASTZB","Влюбившись в спецназ","Мягкие пальчики под военной формой","Мой дорогой защитник","ภารกิจลับ ภารกิจรัก","爱上特种兵"]', 1784690324317);
