INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quan-trang-than-yeu', 'Quân Trang Thân Yêu', 'My Dear Guardian', 'quân trang thân yêu my dear guardian johnny huang li qin yang shu nie zihao yuan jiang zhao xun fu chengpeng xu hong hao liu xiao jie finn han yu yue ou hao ruiling xiong zhong lili xia hou bin xie xian shen lu zhang zhijian guan yajun gu yuhan zhou huilin zhang jin che 亲爱的戎装 军装下的绕指柔 dear military uniform my dear guardian round fingers under military uniforms astzb влюбившись в спецназ мягкие пальчики под военной формой мой дорогой защитник ภารกิจลับ ภารกิจรัก 爱上特种兵', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tre-cua-thang-nam', 'Tuổi trẻ của tháng Năm', 'Youth of May', 'https://phimimg.com/upload/vod/20241106-1/36697df315fec1e32d64ee1a8771b53f.jpg', 'https://phimimg.com/upload/vod/20241106-1/619dd1331e717124cb555e002621b627.jpg', '<p>Bộ phim kể về hai người trẻ tuổi bị cuốn vào cuộc nổi dậy Gwangju xảy ra vào tháng 5 năm 1980. Hwang Hee Tae là một kẻ gây rối, ghét bất cứ điều gì có thể đoán trước được. Cuộc sống của anh ấy được mô tả là “cuộc chiến chống lại định kiến”, và để phá vỡ định kiến đối với những đứa con trai được nuôi dưỡng bởi các bà mẹ đơn thân, anh ấy đã đạt điểm cao nhất và thậm chí đỗ vào Đại học Y khoa Đại học Quốc gia Seoul. Anh ấy cũng chơi guitar vàthích đến quán cà phê âm nhạc.Tuy nhiên, do những biến cố bất ngờ xảy ra, cuối cùng anh đã phải trải qua tháng năm khắc nghiệt nhất trong cuộc đời mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Do-hyun","avatar":""},{"name":"Go Min-si","avatar":""},{"name":"Lee Sang-yi","avatar":""},{"name":"Geum Sae-rok","avatar":""},{"name":"Oh Man-seok","avatar":""},{"name":"Kim Won-hae","avatar":""},{"name":"Uhm Hyo-seop","avatar":""},{"name":"Hwang Young-hee","avatar":""},{"name":"Sim Yi-young","avatar":""},{"name":"Park Cheol-min","avatar":""},{"name":"Lee Hwang-eui","avatar":""},{"name":"Heo Jeong-do","avatar":""},{"name":"Kim Bo-jeong","avatar":""},{"name":"Jung Wook-jin","avatar":""},{"name":"Rho Sang-bo","avatar":""},{"name":"Kim Eun-soo","avatar":""},{"name":"Lee Kyu-sung","avatar":""},{"name":"Joo Bo-young","avatar":""},{"name":"Kwon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["五月的青春","May Youth","Youth in May","오월의 청춘"]', 1784690324317);
