INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-tim-lai-tinh-yeu', 'Hành Trình Tìm Lại Tình Yêu', 'Check Out the Event', 'https://phimimg.com/upload/vod/20241105-1/6353daf8353c29552cb6cf95d86638eb.jpg', 'https://phimimg.com/upload/vod/20241105-1/8f428a968125c38f78db062b7fb38fb2.jpg', '<p>Hành Trình Tìm Lại Tình Yêu kể về cặp đôi đã chia tay nhưng một lần nữa đóng giả làm người yêu của nhau cùng tham gia chuyến du lịch để giành giải thưởng cho các cặp đôi, từ đó mở ra câu chuyện về tình yêu.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"방민아","avatar":""},{"name":"권화운","avatar":""},{"name":"안우연","avatar":""},{"name":"Nam Kyu-hee","avatar":""},{"name":"이주명","avatar":""},{"name":"이진혁","avatar":""},{"name":"김영선","avatar":""},{"name":"Kim Hee-chang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Eventreul Hwakinhaseyo","Please Check the Event","이벤트를 확인하세요"]', 1784690324317);
