INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-biet', 'Dẫu Biết', 'Nevertheless', 'https://phimimg.com/upload/vod/20241105-1/a07b3504c7411b2dac06a22f6ee4244c.jpg', 'https://phimimg.com/upload/vod/20241105-1/6fb3bdb50ca0c0045e53add39936db0d.jpg', '<p>Dẫu Biết (Nevertheless) là bộ phim được dựa trên một webtoon nổi tiếng có cùng tên được xuất bản lần đầu tiên trên Naver Webtoon vào tháng 10 năm 2018. Phim kể về chàng trai tên Park Jae Uhn (Song Kang thủ vai) người rất ghét sự ràng buộc nhưng lại thích tán tỉnh phụ nữ bừa bãi. &nbsp;Một ngày nọ, anh gặp Yoo Na Bi (Han So Hee đảm nhận) một cô gái khao khát được hẹn hò nhưng mất niềm tin vào tình yêu sau khi bị bạn trai cũ làm tổn thương. Dẫu Biết là chuyện tình giữa cả hai con người họ từ khi gặp mặt và bước vào một mối quan hệ khiến cả hai phải thay đổi suy nghĩ về cuộc sống.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"한소희","avatar":""},{"name":"송강","avatar":""},{"name":"채종협","avatar":""},{"name":"이열음","avatar":""},{"name":"양혜지","avatar":""},{"name":"Kim Min-gwi","avatar":""},{"name":"이호정","avatar":""},{"name":"Yoon Seo-ah","avatar":""},{"name":"정재광","avatar":""},{"name":"Han Eu-ddeum","avatar":""},{"name":"Lee Seung-hyub","avatar":""},{"name":"서혜원","avatar":""},{"name":"Lee Tae-hee","avatar":""},{"name":"이정하","avatar":""},{"name":"김무준","avatar":""},{"name":"Yoo Ji-hyun","avatar":""},{"name":"Son Bo-seung","avatar":""},{"name":"Seo Bum-june","avatar":""},{"name":"Yoon Sa-bong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Apesar de Tudo, Amor","虽然我知道","无法抗拒的他","با این حال","با این وجود","わかっていても","Algoitjiman","Nevertheless","Тем не менее","Я знаю, но","Так или иначе","รักนี้ห้ามไม่ได้","เนเวอร์เดอะเลส: รักนี้ห้ามไม่ได้","Yine de","Buna Rağmen","I Know But","Nevertheless,","알고있지만,"]', 1784690324317);
