INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bogdan-boner-nguoi-tru-quy-phan-2', 'Bogdan Boner: Người Trừ Quỷ (Phần 2)', 'Bad Exorcist (Season 2)', 'https://phimimg.com/upload/vod/20241105-1/5cf7371c1637cdc6f5d309facfe821ec.jpg', 'https://phimimg.com/upload/vod/20241105-1/9ca600e04c307d50db02e453cd7d3657.jpg', '<p>Từ băng ma túy như địa ngục cho đến quái vật chống đạn mê khoai tây, Boner trở lại để đối mặt với một loạt kẻ thù hoàn toàn mới.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 15, 2021, 'Vietsub', 'FHD', 'Ba Lan', 0, '[{"name":"Bartosz Walaszek","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["배드 엑소시스트","驅魔狂人","Bogdan Boner: Egzorcysta"]', 1784690324317);
