INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bogdan-boner-nguoi-tru-quy-phan-2', 'Bogdan Boner: Người Trừ Quỷ (Phần 2)', 'Bad Exorcist (Season 2)', 'bogdan boner: người trừ quỷ (phần 2) bad exorcist (season 2) bartosz walaszek 배드 엑소시스트 驅魔狂人 bogdan boner: egzorcysta', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-mai-la-em', 'Vẫn Mãi Là Em', 'Me Always You', 'https://phimimg.com/upload/vod/20241105-1/48437a2a62e5036c7aed1f6182a411ed.jpg', 'https://phimimg.com/upload/vod/20241105-1/ff9b778b3f26b2b82af290a6b306c40f.jpg', '<p>Bản remake từ She Was Pretty - bộ phim Hàn Quốc đình đám, dựa trên một câu chuyện có thật về mối quan hệ của một cặp đôi từ bạn thành yêu. Ploypailin là một cô gái xinh đẹp xuất thân từ một gia đình giàu có. Sau khi công ty xuất bản của gia đình cô bị phá sản, cô đã trải qua những khó khăn và mất đi vẻ đẹp của mình. Kawin là một cậu bé xấu xí lại tự ti, nhưng lớn lên trở thành một biên tập viên đẹp trai và thành đạt. Hai người bạn thưở nhỏ quyết định gặp lại nhau khi trưởng thành. Vì xấu hổ về vẻ ngoài và sợ làm hỏng ký ức tốt đẹp của Kawin về mình, Ploypailin đã yêu cầu người bạn thân xinh đẹp giả làm cô để gặp Kawin. Tuy nhiên, mọi thứ nhanh chóng trở nên phức tạp khi Ploypailin được chỉ định làm việc tại tạp chí nơi Kawin là phó tổng biên tập. Anh công khai ngược đãi và coi thường cô vì bản tính vụng về của cô, mà không biết rằng cô chính là người bạn thời thơ ấu của anh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2021, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Pae Arak","avatar":""},{"name":"Fang Dhanundhorn","avatar":""},{"name":"Malinee Adelaide","avatar":""},{"name":"Nat Kitcharit","avatar":""},{"name":"Up Poompat","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["รักวุ่นวาย ยัยตัวป่วน"]', 1784690324317);
