INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-ay-hoan-hao', 'Anh Ấy Hoàn Hảo', 'Love Crossed', 'https://phimimg.com/upload/vod/20241104-1/202ecb36c8548a7e5bf8f565d1b5722c.jpg', 'https://phimimg.com/upload/vod/20241104-1/f1f8847e13eb05600097dbfdb62616d7.jpg', '<p>Game thực tế ảo về tình yêu &quot;Love boys&quot; tạo nên nhóm bốn nhân vật chính hoàn hảo tên Y4 gồm Lục Tiếu, Tô Liệt, Hứa Niệm và Lạc Khả. Trên thực tế, bốn nhân vật hư cấu này được xây dựng trên cơ sở dữ liệu về nhóm hoa mỹ nam G4 mà Công ty Giải trí Diệu thu thập được. Trong thực tế, G4 có rất nhiều khuyết điểm, hoàn toàn ngược lại với Y4, hơn nữa còn là một đám gà mờ trong chuyện yêu đương. Nữ chính Khương Khả Lạc và Quan Thiên Nhã vô tình phát hiện ra bí mật của Love boys và âm mưu phía sau của Giải trí Diệu. CEO của Giải trí Diệu Từ Quảng Hàn âm thầm thao túng tất cả, dưới sự ảnh hưởng của Khả Lạc và Thiên Nhã, kế hoạch bỏ trốn của G4 gặp phải muôn vàn khó khăn.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"He Luoluo","avatar":""},{"name":"代露娃","avatar":""},{"name":"张凌赫","avatar":""},{"name":"Fan Shuaiqi","avatar":""},{"name":"常斌","avatar":""},{"name":"Huang Deyi","avatar":""},{"name":"Li Baihui","avatar":""},{"name":"闫安","avatar":""},{"name":"Ming Dao","avatar":""},{"name":"Tien Niu","avatar":""},{"name":"Fan Jing Yi","avatar":""},{"name":"Wang Xingchen","avatar":""},{"name":"Zhang Sha Sha","avatar":""},{"name":"Li Yun Ao","avatar":""},{"name":"Shi Yu","avatar":""},{"name":"Yuan ChengJie","avatar":""},{"name":"Leng Haiming","avatar":""},{"name":"Zhang Liwei","avatar":""},{"name":"Li Xi Yuan","avatar":""},{"name":"Wu Ya Heng","avatar":""},{"name":"Li Yi","avatar":""},{"name":"Zheng Xiao Wan","avatar":""},{"name":"Tian Lei"