INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-em-binh-an-do-moi-la-ngay-dep-troi', 'Nếu Em Bình An Đó Mới Là Ngày Đẹp Trời', 'Sunshine Of My Life', 'https://phimimg.com/upload/vod/20241104-1/242b2d917c2006dff599fbe34117b802.jpg', 'https://phimimg.com/upload/vod/20241104-1/bc0d9288de2a59315e21e43eccbab2ae.jpg', '<p>Bối cảnh phim được diễn ra khi mà các thương hiệu thời trang nội địa Trung Quốc phát triển. Nam chính Đường Minh Hiên (Trương Hàn thủ vai) là chủ tịch một tập đoàn, có tính khí hống hách và lạnh lùng. Mạc Phi (Từ Lộ đảm nhận) là mỹ nữ thiết kế thời trang, đam mê các sản phẩm truyền thống của nước nhà. Cả hai vô tình gặp nhau trong việc tạo nên những trang phục đẹp, độc đáo để quảng bá ra thế giới. Trong quá trình làm chung Đường Minh Hiên nảy sinh tình cảm với Mạc Phi tạo nên chuyện tình đẹp, lãng mạn nhưng cũng không kém phần hài hước.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Han","avatar":""},{"name":"徐璐","avatar":""},{"name":"Wang Ruizi","avatar":""},{"name":"洪堯","avatar":""},{"name":"Jiao Na","avatar":""},{"name":"Wang Xuan","avatar":""},{"name":"Du Juan","avatar":""},{"name":"Zhu Wei Ling","avatar":""},{"name":"Wang Jinsong","avatar":""},{"name":"Wen Zhengrong","avatar":""},{"name":"Morning Chang","avatar":""},{"name":"Shi Qingyan","avatar":""},{"name":"吳迪飛","avatar":""},{"name":"李昕哲","avatar":""},{"name":"Qian Jie","avatar":""},{"name":"Jiang Yan Ru","avatar":""},{"name":"Gong Zhengnan","avatar":""},{"name":"Zhang Minglei","avatar":""},{"name":"Wu Yitong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sunshine of My Life","A Love Story You Are the Greatest Happiness of My Life","若你安好便是晴天","러브 스토리: 그대는 내 인생 최대의 행복","약니안호편시청천: 네가 좋으면 맑은 날인거야"]', 1784690324318);
