INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('neu-em-binh-an-do-moi-la-ngay-dep-troi', 'Nếu Em Bình An Đó Mới Là Ngày Đẹp Trời', 'Sunshine Of My Life', 'nếu em bình an đó mới là ngày đẹp trời sunshine of my life zhang han 徐璐 wang ruizi 洪堯 jiao na wang xuan du juan zhu wei ling wang jinsong wen zhengrong morning chang shi qingyan 吳迪飛 李昕哲 qian jie jiang yan ru gong zhengnan zhang minglei wu yitong sunshine of my life a love story you are the greatest happiness of my life 若你安好便是晴天 러브 스토리: 그대는 내 인생 최대의 행복 약니안호편시청천: 네가 좋으면 맑은 날인거야', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sisyphus-than-thoai', 'Sisyphus: Thần Thoại', 'Sisyphus', 'https://phimimg.com/upload/vod/20241103-1/ccdaa18e26202a3ce6b7f87048870db0.jpg', 'https://phimimg.com/upload/vod/20241103-1/664575ff9cc0cb536bbc04333bc23dc3.jpg', '<p>Sisyphus: Thần Thoại là phim hành động giả tưởng tập trung vào kỹ sư thiên tài Han Tae Sool (Jo Seung Woo) và vị cứu tinh của anh là Kang Seo Hae (Park Shin Hye). Han Tae Sool là người đồng sáng lập công ty Lượng tử và Thời gian. Được biết đến như thiên tài trong số các thiên tài, anh có tay nghề cao trong lĩnh vực kỹ thuật và mã hóa. Sự đổi mới của Han Tae Sool đã nâng Lượng tử và Thời gian lên tầm quốc tế, anh được biết đến như một anh hùng dân tộc và một kỳ tích trong thế giới kỹ thuật Hàn Quốc.

Tuy nhiên, ngoài đời mọi chuyện lại khác. Sau cái chết đột ngột của người anh trai 10 năm trước, hành vi lập dị của anh đã khiến cổ phiếu của công ty biến động. Rồi một ngày, anh phát hiện ra một sự thật khó tin về cái chết của anh trai mình, đưa anh vào một cuộc hành trình nguy hiểm.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"조승우","avatar":""},{"name":"박신혜","avatar":""},{"name":"채종협","avatar":""},{"name":"성동일","avatar":""},{"name":"태인호","avatar":""},{"name":"태원석","avatar":""},{"name":"전국환","avatar":""},{"name":"허준석","avatar":""},{"name":"정혜인","avatar":""},{"name":"최정우","avatar":""},{"name":"Go Yoon","avatar":""},{"name":"김병철","avatar":""},{"name":"Lee Yeon-su","avatar":""},{"name":"이시우","avatar":""},{"name":"Lim Ji-sub","avatar":""},{"name":"Kim Jong-tae","avatar":""},{"name":"하율리","avatar":""},{"name":"Park Young Bin","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["سيزيف: الأسطورة","El mito de Sísifo","Sijipeuseu: The Myth","Sisyphus:the Myth","西西弗斯：神话","Sisyfov mýtus","Sijipeuseu: the Myth","Sísifo","Sisyphus: The Myth","Σίσυφος","시지프스 - the myth","시지프스: the myth","Sisif","Миф о Сизифе","Sizyfov mýtus","薛西弗斯的神話","西西弗斯的神話","시지프스 : the myth"]', 1784690324318);
