INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-de-nhat-the-gioi-chuyen-sinh-thanh-quy-toc', 'Sát thủ đệ nhất thế giới chuyển sinh thành quý tộc', 'The World''s Finest Assassin Gets Reincarnated in Another World as an Aristocrat', 'https://phimimg.com/upload/vod/20241102-1/52f851f518c2f6d053d6ef1692cdf7c0.jpg', 'https://phimimg.com/upload/vod/20241102-1/30f4b8cd46e16ef46240b25233b0c69f.jpg', '<p>&quot;Tôi sẽ sống cho chính mình!&quot; Sát thủ vĩ đại nhất trên Trái đất chỉ biết cách sống như một công cụ cho chủ nhân của mình - cho đến khi họ ngừng để anh ta sống. Được tái sinh bởi ân sủng của một nữ thần vào một thế giới của kiếm và ma thuật, lần này anh ta có cơ hội làm những điều khác đi, nhưng có một cái bắt ... thế giới trừ khi anh ta bị dừng lại. Bây giờ được biết đến với cái tên Lugh Tuatha Dé, sát thủ bậc thầy chắc chắn đã bó tay, đặc biệt là vì toàn những cô gái xinh đẹp luôn vây quanh anh ta. L Dù có thể là một kẻ giết người không thể so sánh được, nhưng anh ta sẽ chống lại kẻ thù bằng phép thuật mạnh mẽ như thế nào?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"赤羽根健治","avatar":""},{"name":"上田麗奈","avatar":""},{"name":"高田憂希","avatar":""},{"name":"下地紫野","avatar":""},{"name":"森川智之","avatar":""},{"name":"たかはし智秋","avatar":""},{"name":"田村ゆかり","avatar":""},{"name":"森田順平","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["世界顶尖的暗杀者转生为异世界贵族","世界顶尖的暗杀者转生成为异世界贵族","世界最强暗杀者转生成异世界贵族","Sekai Saikou no Assassin","Sekai Saikō no Ansatsusha, Isekai Kizoku ni Tensei Suru","Sekai Saikou no Ansatsusha, Isekai Kizoku ni Tensei suru","Sekai Saikou no Assassin, Isekai Kizoku ni Tensei Suru","暗殺貴族","Найкращий у світі вбивця перероджується в іншому світі аристократом","Найкращий у світі асасин перероджується в іншому світі аристократом","Найкращий у світі асасин переродився в іншому світі як аристократ","The World''s Finest Assassin Gets Reincarnated in Another World as an Aristocrat","世界最高の暗殺者、異世界貴族に転生する"]', 1784690324318);
