INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dem-truoc-o-soho', 'Đêm Trước Ở Soho', 'Last Night in Soho', 'đêm trước ở soho last night in soho thomasin mckenzie anya taylor-joy matt smith rita tushingham michael ajao synnøve karlsen pauline mclynn terence stamp diana rigg aimée cassettari colin mace jessie mei li kassius nelson rebecca harrod alan mahon connor calland josh zaré ultima notte a soho une dernière nuit à soho 蘇豪的最後一夜 última noche en el soho последна нощ в сохо ฝัน-หลอน-ที่โซโห dün gece soho''da ostatniej nocy w soho el misterio de soho noite passada em soho ラストナイト・イン・ソーホー：2021 última nit al soho վերջին գիշերը սոհոյում last night in soho', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-cac-te-bao-lam-viec-phan-2', 'Khi Các Tế Bào Làm Việc (Phần 2)', 'Cells at Work! (Season 2)', 'https://phimimg.com/upload/vod/20241030-1/af4324b8456ea0a676847943efdc94d3.jpg', 'https://phimimg.com/upload/vod/20241030-1/ab2879015ce6c3165c971b605b333d09.jpg', '<p>Trung bình cơ thể con người gồm có 60 nghìn tỉ tế bào. Mỗi tế bào tuy nhỏ bé nhưng đều bận rộn tất bật với công việc và chức năng của riêng mình: Hồng Cầu giúp vận chuyển Oxi, Tiểu Cầu giúp làm đông máu... Khi con người bị thương, virus và vi khuẩn sẽ nhanh chóng xâm nhập vào cơ thể, và khi dị ứng bắt đầu lan tỏa, tất cả các tế bào sẽ nhường chỗ cho Bạch Cầu và Tế Bào nơ-ron thần kinh để họ làm nhiệm vụ tiêu diệt kẻ xâm nhập.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"花澤香菜","avatar":""},{"name":"前野智昭","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["工作细胞第2季","Cells at Work!","Hataraku Saibou","LES BRIGADES IMMUNITAIRES (CELLS AT WORK - HATARAKU SAIBOU)","Hataraku Saibō","働く細胞","はたらく細胞!!","はたらく細胞!!(2021)","Робота клітин!","Робота клітин!!","Cells at Work!!","はたらく細胞"]', 1784690324318);
