INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-mo-but-ky-tan-linh-than-thu', 'Đạo Mộ Bút Ký: Tần Lĩnh Thần Thụ', 'The Buried Tree Devil', 'https://phimimg.com/upload/vod/20241030-1/922c31f461f21173aba94c55fa5a33cc.jpg', 'https://phimimg.com/upload/vod/20241030-1/032f88262899585e1e2619183a568ec7.jpg', '<p>Trải qua hai chuyện mạo hiểm, Ngô Tà từ Nam Sa quay về Hàng Châu. Trong lúc tĩnh dưỡng đột nhiên nhận được cuộc điện thoại của người bạn nối khố đã lâu không gặp - Lão Dương. Lão Dương kể với Ngô Tà những điều mắt thấy tai nghe trong chuyến đi vào núi Tần Lĩnh ba năm trước, đồng thời mời Ngô Tà cùng mình mạo hiểm một chuyến, quay lại khám phá di tích cổ đại.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xin Teng","avatar":""},{"name":"Lu Zhao","avatar":""},{"name":"姚雷","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["秦岭神树","Daomu Biji Zhi Qinling Shen Shu","Daomu Biji: Qinling Shen Shu","Dao Mu Bi Ji","Dao Mu Bi Ji: Qin Ling Shen Shu","Dao Mu Bi Ji Zhi Qin Ling Shen Shu","Dàomù Bǐjì Zhī Qínlǐng Shén Shù","Qinling Shen Shu","Qin Ling Shen Shu","盗墓笔记之秦岭神树","Tomb Raider’s Chronicles: Qinling Sacred Tree","Grave Robbery Note II","Lost Tomb 2","Grave Robbers'' Chronicle II","Grave Robbers'' Chronicles II","Đạo Mộ Bút Ký - Tần Lĩnh Thần Thụ","盗墓笔记秦岭神树"]', 1784690324318);
