INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-sao-antares', 'Ngôi Sao Antares', 'Antares', 'https://phimimg.com/upload/vod/20241026-1/6e68758c8c8173976d1aadddcd15425c.jpg', 'https://phimimg.com/upload/vod/20241026-1/3c8ed2771097121552978168dc7d59cf.jpg', '<p>Zea, một cô gái bí ẩn nhưng quyến rũ, tìm đường đến cuộc sống của Ares, thủ lĩnh của Calderioz, để điều tra tai nạn đáng tiếc của anh trai cô. Cả hai cùng tham gia vào một câu chuyện tình không giống ai; dạy họ giá trị của lòng tin, tình bạn và tình yêu đích thực.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2021, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Angga Yunanda","avatar":""},{"name":"Beby Tsabina","avatar":""},{"name":"Devano Danendra","avatar":""},{"name":"Alika Jantinia","avatar":""},{"name":"Kevin Royano","avatar":""},{"name":"Keanu Campora","avatar":""},{"name":"Adam Farrel","avatar":""},{"name":"Nicholas Christian Calame","avatar":""},{"name":"Zulkifli Nasution","avatar":""},{"name":"Widi Mulia","avatar":""},{"name":"Aurellia Salma","avatar":""},{"name":"Gilbert Pattiruhu","avatar":""},{"name":"Kenes Andari","avatar":""},{"name":"Stephanus Hermawan Chris","avatar":""},{"name":"Anyun Cadel","avatar":""},{"name":"Anugr","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Antares"]', 1784690324318);
