INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('9-thang-yeu', '9 Tháng Yêu', '9 Months', 'https://phimimg.com/upload/vod/20241024-1/0228cb1b25bd524cbb6a5ba29e0472d0.jpg', 'https://phimimg.com/upload/vod/20241024-1/2270dc24a827db46409bec29cce6c130.jpg', '<p>9 Tháng Yêu kể về cuộc đời của Welly (Fero Walandouw) phải ký hợp đồng kết hôn với Karen (Pamela Bowie) vì tiền để giành lấy người yêu của anh - Andini (Cita Citata).</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 13, 2021, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Fero Walandouw","avatar":""},{"name":"Cita Citata","avatar":""},{"name":"Pamela Bowie","avatar":""},{"name":"Anyun Cadel","avatar":""},{"name":"Syakir Daulay","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["9 Bulan"]', 1784690324318);
