INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('9-thang-yeu', '9 Tháng Yêu', '9 Months', '9 tháng yêu 9 months fero walandouw cita citata pamela bowie anyun cadel syakir daulay 9 bulan', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gui-den-ngoi-sao-cua-anh-2021', 'Gửi Đến Ngôi Sao Của Anh', 'To My Star', 'https://phimimg.com/upload/vod/20241022-1/db6344fcf2800b75ca0f31da907019b7.jpg', 'https://phimimg.com/upload/vod/20241022-1/ebe89cc76b3faa11ff55606c631ce791.jpg', '<p>Bộ phim là câu chuyện tình yêu ngọt ngào của anh chàng diễn viên Kang Seo Joon (Son Woo Huyn đóng) luôn tìm cách thoát khỏi quy luật cuộc sống và đầu bếp Han Ji Woo (Kim Kang Min đóng) chỉ muốn có một cuộc sống an ổn bình thường. Từ lúc được debut đến nay, anh chàng diễn viên tài mạo song toàn Kang Seo Joon chưa biết mùi flop là gì, như thể anh chính là một ngôi sao lấp lánh trên trời. Nhưng anh lại bất ngờ tiến vào thế giới của Han Ji Woo, cũng trải nghiệm được sự biến hóa kỳ diệu trong tình cảm. Chàng đầu bếp ấm áp Han Ji Woo luôn kiên nhẫn chậm rãi hướng đến mục tiêu của mình, thế mà lại rơi vào vô số rắc rối rối bời chỉ vì sự xuất hiện của Kang Seo Joon.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Son Woo-hyeon","avatar":""},{"name":"Kim Kang-min","avatar":""},{"name":"Go Jae-hyun","avatar":""},{"name":"Chun Jae-young","avatar":""},{"name":"진권","avatar":""},{"name":"Han Ji-won","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["나의 별에게"]', 1784690324318);
