INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-gia-chu-mau', 'Đương Gia Chủ Mẫu', 'Marvelous Woman', 'https://phimimg.com/upload/vod/20241022-1/27a4a46a49390260abc5c763b54ec472.jpg', 'https://phimimg.com/upload/vod/20241022-1/5d62581f700a929bcc4f13edd21e455f.jpg', '<p>Trong thời kỳ Càn Long Triều Thanh, ngành dệt may của Cô Tô dẫn đầu, gấm Tô Châu và lụa hoa đều là cống phẩm cung đình. Gia tộc nhà họ Nhậm thế tập chức vụ dẫn dệt trong Chức Tạo Hàng tại Phủ Tô Châu và họ sở hữu bí kíp dệt lụa hoa. Nhậm Tuyết Đường, gia chủ nhà Nhậm, tính tình tao nhã, lịch sử. Ngược lại, Thẩm Thúy Hỉ, phu nhân của ông, tính cách cương nghị, làm việc mạnh mẽ vang dội, bà không những quản lý nhà Nhậm cho có ngăn có nắp, mà còn nhờ nghệ thuật thêu dệt tuyệt vời phát huy công nghệ dệt lụa hoa của nhà Nhậm, trở thành “chủ mẫu đương gia” nổi tiếng. Tuy nhiên sông có lúc trong lúc đục, Nhậm Tuyết Đường gặp phải bất trắc mà mất tích khi truy bắt thổ phỉ trên sông. Việc này khiến nhà Nhậm rơi vào cảnh ngộ nguy hiểm.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Qin Qin","avatar":""},{"name":"張慧雯","avatar":""},{"name":"Yang Rong","avatar":""},{"name":"Mao Zijun","avatar":""},{"name":"徐垚","avatar":""},{"name":"Li Yinan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["当家主母 當家主母","Dang Jia Zhi Mu","Dang Jia Zhu Mu","Хозяйка дома","Marvelous Woman","The Matriarch","Marvelous Women","当家主母"]', 1784690324318);
