INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-menh-ky-dieu', 'Vận Mệnh Kỳ Diệu', 'Wonderful Fate', 'https://phimimg.com/upload/vod/20241022-1/ed30233ec7272bae5c0a39839ed59674.jpg', 'https://phimimg.com/upload/vod/20241022-1/bff2583016c5acced975c29b2c189bb7.jpg', '<p>Lý Phúc Châu, một người thiếu nữ học tra cổ linh tinh quái, ngẫu nhiên lạc vào nước Vân Lai nghèo khổ trong thế giới truyện tranh, được người dân nơi đó nhầm tưởng là thiên nữ từ trời giáng trần mà hưởng lễ ngang với thiên tử Vân Dịch. Nàng muốn dùng học thức nông cạn của mình giúp nước Vân Lai trở nên giàu mạnh, nhưng lại vô cớ bị cuốn vào trần đấu giữa quốc sư mang dã tâm sôi sục và thiên tử bù nhìn Vân Dịch. Nàng đơn thuần, hiền lành, trở thành bánh quy có nhân, rơi vào tình thế khó xử. Do vậy, nàng còn hiểu được chỗ xấu của sự thiếu hiểu biết và tầm quan trọng của học tập.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Junxiang","avatar":""},{"name":"Zhang Yuenan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["奇妙的命运呀"]', 1784690324318);
