INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('grace-va-frankie-phan-7', 'Grace Và Frankie (Phần 7)', 'Grace And Frankie (Season 7)', 'https://phimimg.com/upload/vod/20241019-1/23901245819ea85008b85aee973561b3.jpg', 'https://phimimg.com/upload/vod/20241019-1/a7e699a29086163dcccb40b9a43232ec.jpg', '<p>Căng thẳng dâng cao tại ngôi nhà bên bờ biển khi bà Grace, bà Frankie, ông Robert và ông Sol đều đang sống ở đó cùng nhau – và làm nhau phát điên.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jane Fonda","avatar":""},{"name":"Lily Tomlin","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"Sam Waterston","avatar":""},{"name":"June Diane Raphael","avatar":""},{"name":"Brooklyn Decker","avatar":""},{"name":"Ethan Embry","avatar":""},{"name":"Baron Vaughn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["格蕾丝与弗兰基","同妻俱乐部","Γκρέις και Φράνκι","그레이스 앤 프랭키","Grace & Frankie","Grace and Frankie"]', 1784690324318);
