INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-gia-lam-chieu-v-nhung-cuoc-doi-vuong-gia', 'Gái Già Lắm Chiêu V: Những Cuộc Đời Vương Giả', 'Camellia Sisters 5 - Living Like Royalty', 'https://phimimg.com/upload/vod/20241020-1/dcd2aa66363f765da6fd1baf19a9e1d9.jpg', 'https://phimimg.com/upload/vod/20241020-1/ef91a46c40f95baafb331ab4aba8495e.jpg', '<p>Cuộc chiến “Chị - Em máu mủ tình thâm” chỉ vì hai chữ TÌNH- TIỀN của ba chị em gái Lý gia tại Biệt thự Bạch Trà Viên xứ Huế. Chính vì vòng xoáy “tình – tiền, được – mất” đã khiến họ từ chị em trở thành những kẻ đối đầu trong mối quan hệ tình thân. Câu chuyện bắt đầu vào đêm đấu giá phiên Xuân tại Bạch Trà Viên, Phượng bào tam vĩ - cổ vật 30 triệu đô, bảo vật của Lý gia bị mất cắp. Khiến ba chị em bắt đầu nghi kỵ lẫn nhau đồng thời phơi bày nhiều bí mật động trời tưởng chừng đã được che giấu suốt cả một đời.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Hồng Vân","avatar":""},{"name":"Kaity Nguyễn","avatar":""},{"name":"Khương Lê","avatar":""},{"name":"Hoàng Dũng","avatar":""},{"name":"Lê Khánh","avatar":""},{"name":"Jun Vũ","avatar":""},{"name":"Trang Hý","avatar":""},{"name":"Anh Dũng","avatar":""},{"name":"Huỳnh Kiến An","avatar":""},{"name":"Le Khanh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["山茶花姊妹：王室秘辛","Camellia Sisters","Gái Già Lắm Chiêu V: Những Cuộc Đời Vương Giả"]', 1784690324318);
