INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-va-am-muu', 'Tình Yêu Và Âm Mưu', 'Plot Love', 'https://phimimg.com/upload/vod/20241019-1/17a8e947d96acd4b8cfb41ad4cfe6fc2.jpg', 'https://phimimg.com/upload/vod/20241019-1/e080f85a32b5d0e60e53db0decfc77fb.jpg', '<p>Tô Bắc dẫn con dễ thương trở về, gặp lại “chồng trước” Lộ Nam, điều tra chân tướng sau hàng loạt âm mưu 7 năm trước. Trong quá trình này, Tô Bắc lại tiếp nối tiền duyên với Lộ Nam.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Shu Jun","avatar":""},{"name":"Ross Chen","avatar":""},{"name":"Cai Xiangyu","avatar":""},{"name":"Sun Xiaolun","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Qin Ai De Ning Meng Jing Xian Sheng","Plot Love","亲爱的柠檬精先生"]', 1784690324318);
