INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-tam-su-ngot-ngao-nhat-cua-anh', 'Em Là Tâm Sự Ngọt Ngào Nhất Của Anh', 'The Sweetest Secret', 'https://phimimg.com/upload/vod/20241019-1/de558690d15dd7c5a66c3861ae2e65eb.jpg', 'https://phimimg.com/upload/vod/20241019-1/6584f0aed8ecffd0bd44029f41a404dd.jpg', '<p>Sau tốt nghiệp Thạc sĩ, Đường Vi Vị định dự thi Tiến sĩ, nhưng lại bị người thân ngăn và bị đòi hỏi kết hôn trước 28 tuổi. Đường Vi Vi mắc bệnh tâm lý, đối mặt với nhiều thử thách và thách thức. Nàng hết sức khổ não, sốt ruột và hình như toàn thế giới đều trở thành kẻ địch với nàng. Lúc này, Lâm Nhiên đứng ra, rọi sáng thế giới của Đường Vi Vi.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Joey Chua","avatar":""},{"name":"周翊然","avatar":""},{"name":"Xu Kaixin","avatar":""},{"name":"Xu Baiyun","avatar":""},{"name":"Liao Huijia","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["You Are My Sweetest Thing","Ni Shi Wo Zui Tian Mi De Xin Shi","니시아최첨밀적심사","你是我最甜蜜的心事"]', 1784690324318);
