INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-la-hiep-si-bong-dem-cua-em', 'Anh Là Hiệp Sĩ Bóng Đêm Của Em', 'Let Me Be Your Knight', 'https://phimimg.com/upload/vod/20241017-1/faf6fd237f04f57339d1f8cf5007fb50.jpg', 'https://phimimg.com/upload/vod/20241017-1/05b5e86e0a9339f7e3be1c5ed2e60a57.jpg', '<p>Bộ phim Hàn Quốc “Em Sẽ Trở Thành Ban Đêm Của Anh” kể về câu chuyện ngọt ngào lại hồi hộp giữa nữ bác sĩ và năm thành viên ban nhạc. Ngôi sao nổi tiếng thế giới Yoon Tae-in(Lee Jun-young thủ vai) mắc bệnh mộng du, đành phải tìm bác sĩ rởm In Yoon-joo(Jung In-sun thủ vai), mời cô ở vào ký túc xá để bí ẩn điều trị cho mình. Nam chính Yoon Tae-in là đội trưởng, ca sĩ chính và nhà sản xuất nhạc của ban nhạc thần tượng nổi tiếng thế giới “Luna”. Nữ chính In Yoon-joo nhờ vào tài ăn nói và sự đồng cảm mình, làm hướng dẫn viên du lịch cho các người già cô độc để nỗ lực thực hiện ước mơ mua nhà. Nhưng cô ngẫu nhiên bị cuốn vào sự kiện bất ngờ, trở thành bác sĩ rởm mạo trong ký túc xá của nhóm thần tượng “Luna”, mạo hiểm sống cùng với năm người đàn ông.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"정인선","avatar":""},{"name":"이준영","avatar":""},{"name":"장동주","avatar":""},{"name":"JR","avatar":""},{"name":"Yoon Ji-sung","avatar":""},{"name":"Kim Dong-hyun","avatar":""},{"name":"서혜원","avatar":""},{"name":"Ha Yeong","avatar":""},{"name":"곽자형","avatar":""},{"name":"이세창","avatar":""},{"name":"Park Ji-won","avatar":""},{"name":"Seo Yi-soo","avatar":""},{"name":"Jo Eun-seo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["成為你的夜晚","I''ll Be Your Night","Your Night","Your Knight","Let Me Be Your Knight","I''ll Be Your Knight","Let Me Be Your Night","너의 밤이 되어줄게"]', 1784690324318);
