INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-khong-roi-tren-vung-dat-vo-than', 'Mưa Không Rơi Trên Vùng Đất Vô Thần', 'Rainless Love in a Godless Land', 'https://phimimg.com/upload/vod/20241017-1/2b0cad3d75fc3d568118a18577a98bc3.jpg', 'https://phimimg.com/upload/vod/20241017-1/0005e0e6cdb79869adbd290a322a8f00.jpg', '<p>Bộ phim dựa trên thần thoại của bộ tộc Ami, trước trận mưa cuối cùng của ngày tận thế, toàn bộ các thần đều rời đi, không ngờ kế hoạch rút lui của các vị thần lại bị một cô gái người phàm làm rối tung cả lên. Khi thế giới đang đi về hướng bất định, cô gái phát hiện ra cơ hội để xoay chuyển vận mệnh gắn liền với bản thân mình và thần hộ mệnh. Câu chuyện tình yêu giữa người phàm và thần linh trước ngày tàn của thế giới sắp sửa diễn ra.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"曾之喬","avatar":""},{"name":"傅孟柏","avatar":""},{"name":"鄭元暢","avatar":""},{"name":"柯佳嬿","avatar":""},{"name":"顏毓麟","avatar":""},{"name":"柯淑勤","avatar":""},{"name":"許光漢","avatar":""},{"name":"郭書瑤","avatar":""},{"name":"鍾欣凌","avatar":""},{"name":"李國毅","avatar":""},{"name":"于子育","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Rainless Love in a Godless Land","무신지지불하우","無神之地不下雨"]', 1784690324318);
