INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-co-the-nhin-thay-chung', 'Tôi Có Thể Nhìn Thấy Chúng', 'Mieruko-chan', 'https://phimimg.com/upload/vod/20241017-1/38e3a06fe0fe459d9982a17aba84c1ad.jpg', 'https://phimimg.com/upload/vod/20241017-1/bca20201fb59580afb839da4d9f1ebf6.jpg', '<p>Miko là một học sinh cao trung điển hình có cuộc sống đảo lộn khi cô đột nhiên bắt đầu nhìn thấy những con quái vật ghê rợn và gớm ghiếc. Mặc dù hoàn toàn vô cùng sợ hãi, Miko vẫn tiếp tục cuộc sống hàng ngày của mình, giả vờ không để ý đến nỗi kinh hoàng đang bao quanh cô. Cô ấy phải chịu đựng nỗi sợ hãi để giữ cho mình và người bạn Hana của cô ấy thoát khỏi nguy hiểm, ngay cả khi điều đó có nghĩa là phải đối mặt với điều tồi tệ nhất. Pha trộn giữa hài kịch và kinh dị, Mieruko-chan kể câu chuyện về một cô gái cố gắng đối phó với điều huyền bí bằng cách tỏ ra thờ ơ với nó.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 18, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"雨宮天","avatar":""},{"name":"本渡楓","avatar":""},{"name":"佐倉綾音","avatar":""},{"name":"中村悠一","avatar":""},{"name":"谷育子","avatar":""},{"name":"花守ゆみり","avatar":""},{"name":"生天目仁美","avatar":""},{"name":"鳥海浩輔","avatar":""},{"name":"飛田展男","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["阴阳眼见子","看得见的女孩","Mieruko-chan","Девочка, которая видит это","Девочка, которая видит монстров","Видящая","Мієруко-чян","Girl That Can See It","MIERUKO CHAN","toi co the nhin thay chung","Mieruko-chan: Tôi có thể nhìn thấy chúng","見える子ちゃん"]',