INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('komi-khong-the-giao-tiep', 'Komi không thể giao tiếp', 'Komi Can''t Communicate', 'komi không thể giao tiếp komi can''t communicate 古賀葵 梶原岳人 村川梨衣 日高里菜 大久保瑠美 藤井ゆきよ 前島亜美 日髙のり子 komi-san wa, comyushou desu. komi-san wa, komyushō desu. komi-san wa, komyushou desu. 古见同学有交流障碍症 古見同學有交流障礙症 古見同學有社交障礙 komi sulit berkomunikasi 古見さんは、コミュ症です。(アニメ) у комі проблеми зі спілкуванням 古見さんは、コミュ症です。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-thoi-gian-am-ap', 'Nửa Thời Gian Ấm Áp', 'The Memory About You', 'https://phimimg.com/upload/vod/20241017-1/f665c73b96ba518b553f14a4e51ec685.jpg', 'https://phimimg.com/upload/vod/20241017-1/944595ba5262cbb480aa3b1231687853.jpg', '<p>Nửa Thời Gian Ấm Áp - The Memory About You xoay quanh mối tình của Yan Xiao Chen và Shen Hou. Để kiếm tiền để trả học phí, Yan Xiao Chen làm việc bán thời gian tại quán bar. Ở đó, cô gặp Cheng Jin Yuan, một anh chàng giàu có. Điều này khiến Shen Hou không vui. Sau khi tốt nghiệp đại học, Xiao Chen và Shen Hou quyết định kết hôn. Tuy nhiên, Xiao Chen phát hiện ra rằng cái chết của cha cô là do mẹ của Shen Hou gây ra. Cô hủy hôn và chạy trốn đến Mỹ. Trong thời gian khó khăn này, Jin Yuan đã ở bên và giúp đỡ cô. Tuy nhiên, Shen Hou đột nhiên xuất hiện và mang theo bí mật sâu sắc nhất của Jin Yuan. Sau loạt sự cố này, Xiao Chen quyết định thay thế sự thù hận với sự tha thứ và đi theo cảm xúc thật của trái tim mình.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"许龄月","avatar":""},{"name":"杨旭文","avatar":""},{"name":"付辛博","avatar":""},{"name":"Ding Guansen","avatar":""},{"name":"Wang Yan Zhi","avatar":""},{"name":"Chang Shixin","avatar":""},{"name":"Hailan Liu","avatar":""},{"name":"Ren Bin","avatar":""},{"name":"Bowen Li","avatar":""},{"name":"徐帆","avatar":""},{"name":"Tenzin Jigme","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Memory About You","Половина тепла","半暖时光"]', 1784690324318);
