INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ten-cua-em-ho-cua-anh', 'Tên Của Em Họ Của Anh', 'Once Given, Never Forgotten', 'https://phimimg.com/upload/vod/20241017-1/af80156802cd0dbee3a557a92fed0d37.jpg', 'https://phimimg.com/upload/vod/20241017-1/e73220ccff31919e6d10367f823e2096.jpg', '<p>Bạn gái của cô nhi Hạng Ngữ Thu là La Đình qua đời bởi tai nạn và hiến giác mạc cho một cô bé mồ côi ốm yếu bệnh tật tên Hạng Liên Tâm. Mười năm sau, Hạng Liên Tâm du học trở về rồi vô tình quen biết với em trai của La Đình là La Duệ. La Duệ yêu Liên Tâm từ cái nhìn đầu tiên rồi điên cuồng theo đuổi, nhưng Liên Tâm lại yêu Hạng Ngữ Thu sâu sắc. Hạng Ngữ Thu không cách nào đối diện với Hạng Liên Tâm, người đang sở hữu đôi mắt của La Đình, anh cũng chẳng thể thừa nhận tình cảm của bản thân. Dưới áp lực nặng nề, Hạng Liên Tâm bị mắc bệnh Alzheimer, Hạng Ngữ Thu tìm đủ mọi cách chữa trị cho cô ấy. Sự kiên trì và bảo vệ không ngừng nghỉ ấy cuối cùng đã đánh thức được trí nhớ của Hạng Liên Tâm.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"張雪迎","avatar":""},{"name":"米露","avatar":""},{"name":"張超","avatar":""},{"name":"楊玏","avatar":""},{"name":"Sheren Tang","avatar":""},{"name":"Chen Ziyou","avatar":""},{"name":"Jasmine Liu","avatar":""},{"name":"Wang Cheng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["你的名字我的姓氏","NDMZWDXS"]', 1784690324318);
