INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-cuoc-tai-thiet-vuong-quoc-cua-anh-hung-chu-nghia-hien-thuc', 'Công Cuộc Tái Thiết Vương Quốc Của Anh Hùng Chủ Nghĩa Hiện Thực', 'How a Realist Hero Rebuilt the Kingdom', 'https://phimimg.com/upload/vod/20241017-1/e6cf86237653c616b53020d2cd8eae06.jpg', 'https://phimimg.com/upload/vod/20241017-1/e42f13f420f4fcd6092818b89858a198.jpg', '<p>Chàng trai tên Kazuya Souma. Bổng một ngày bị triều hồi đến một vương quốc kì lạ, nơi mọi người kì vọng cậu ấy trở thành anh hùng của họ. Nhưng lí tưởng anh hùng của Kazuma hoàn toàn khác so với những gì nhà vua suy nghĩ, anh ấy muốn cải kinh tế cho đất nước, xây dựng lại kinh tế để phản kháng lại sự xâm lược của các nươc láng giềng. Bằng một nguyên nhân kì lạ nào đó, Kazuya được nhà vua trao ngai vàng lại, bằng cơ duyên đó anh gặp được con gái của nhà vua, công chúa Liscia người trở thành hôn phu của anh. Từ đó hành trình cải cách đất nước của vị anh hùng bắt đầu.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"小林裕介","avatar":""},{"name":"水瀬いのり","avatar":""},{"name":"長谷川育美","avatar":""},{"name":"上田麗奈","avatar":""},{"name":"興津和幸","avatar":""},{"name":"佳原萌枝","avatar":""},{"name":"水中雅章","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Crónica de la restauración de un reino","Genjitsu Shugi Yūsha no Ōkoku Saikenki","Genjitsu Shugi Yuusha no Oukoku Saikenki","Genjitsushugi Yūsha no Ōkoku Saikenki","Genjitsushugi Yuusha no Oukoku Saikenki","現国","Genkoku","現実主義勇者の王国再建記 第二部","현실주의 용사의 왕국 재건기","现实主义勇者的王国重建记","A Realist Hero''s Kingdom Restoration Chronicle","How a Realist Hero Rebuilt the Kingdom","現実主義勇者の王国再建記"]', 1784690324318);
