INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-cuoc-tai-thiet-vuong-quoc-cua-anh-hung-chu-nghia-hien-thuc', 'Công Cuộc Tái Thiết Vương Quốc Của Anh Hùng Chủ Nghĩa Hiện Thực', 'How a Realist Hero Rebuilt the Kingdom', 'công cuộc tái thiết vương quốc của anh hùng chủ nghĩa hiện thực how a realist hero rebuilt the kingdom 小林裕介 水瀬いのり 長谷川育美 上田麗奈 興津和幸 佳原萌枝 水中雅章 crónica de la restauración de un reino genjitsu shugi yūsha no ōkoku saikenki genjitsu shugi yuusha no oukoku saikenki genjitsushugi yūsha no ōkoku saikenki genjitsushugi yuusha no oukoku saikenki 現国 genkoku 現実主義勇者の王国再建記 第二部 현실주의 용사의 왕국 재건기 现实主义勇者的王国重建记 a realist hero''s kingdom restoration chronicle how a realist hero rebuilt the kingdom 現実主義勇者の王国再建記', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-gap-su-tu', 'Mơ Gặp Sư Tử', 'Out Of The Dream', 'https://phimimg.com/upload/vod/20241017-1/13ee7218f62e0a1aec9135c222271e46.jpg', 'https://phimimg.com/upload/vod/20241017-1/d8b8391cd9ae074e6f47b8c25135b98b.jpg', '<p>Phim xoay quanh câu chuyện của Vũ Phi (Trần Vũ Tư thủ vai), là một nghệ sĩ kinh kịch Bắc Kinh vì mắc sai lầm mà bị khai trừ. Ngay lúc đó, nhà sản xuất Bạch Phi Lệ (Diêu Trì thủ vai) đang tìm kiếm một nữ diễn viên có nền tảng về kinh kịch Bắc Kinh và đã tuyển dụng Vũ Phi. Sự xuất hiện của Vũ Phi đã mang đến cho sân khấu một làn gió mới khi mà tài năng và giọng hát của cô giúp sân khấu tăng lượng khách lên đáng kể chỉ sau vài ngày đầu hát. Sự nghiệp của nữ chính Mơ Gặp Sư Tử tưởng chừng phất lên như diều gặp gió thì bất chợt cả hai cắt đứt mối quan hệ về cái chết của người mẹ. Sau một thời gian, khi họ gặp lại nhau, Vũ Phi đang trong quá trình chuẩn bị cho trường kịch nghệ trong khi Bạch Phi Lệ phải đối mặt với cuộc khủng hoảng chưa từng có. Vũ Phi bắt đầu làm việc bán thời gian cho Bạch Phi Lệ trong khi anh giúp cô với bài kiểm tra đầu vào. Trong khoảng thời gian này cả hai đã nhen nhóm lại mối quan hệ của mình và bắt đầu nắm tay nhau cho kế hoạch Mơ Gặp Sư Tử nơi sân khấu kịch.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"姚弛","avatar":""},{"name":"Yusi Chen","avatar":""},{"name":"Fu Jing","avatar":""},{"name":"谢兴阳","avatar":""},{"name":"Wu Yuheng","avatar":""},{"name":"孫珍妮","avatar":""},{"name":"Shi An","avatar":""},{"name":"Sheng Gangshuai","avatar":""},{"name":"Jing Yanjun","avatar":""},{"name":"Sun Tianyu","avatar":""},{"name":"Hu Xiaoting","avatar":""},{"name":"Han Xintong","avatar":""},{"name":"林静","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Meng Jian Shi Zi","Dream of Lion","Meng Jian Shizi","Dreaming of Lion","몽견사자","梦见狮子"]', 1784690324318);
