INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('girls5eva-phan-1', 'Girls5eva (Phần 1)', 'Girls5eva (Season 1)', 'https://phimimg.com/upload/vod/20241017-1/1c2033d8cf7b8798636ed07c9a8bd950.jpg', 'https://phimimg.com/upload/vod/20241017-1/d07555a98913af34b60b0ddbc5c3e4fe.jpg', '<p>Nhóm nhạc nữ chỉ có một bài để đời ở thập niên 90 cố gắng tái xuất trong khi hài hước xoay xở với gia đình, các mối quan hệ và niềm vui cũng như nỗi đau của tuổi trung niên.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sara Bareilles","avatar":""},{"name":"Busy Philipps","avatar":""},{"name":"Paula Pell","avatar":""},{"name":"Renée Elise Goldsberry","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Girls5eva","Дев4онки навсегда"]', 1784690324318);
