INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-bong-dem-gon-song', 'Khi Bóng Đêm Gợn Sóng', 'Love At Night', 'https://phimimg.com/upload/vod/20241016-1/6be1f4c6712e806e7a3a99339e17b2e3.jpg', 'https://phimimg.com/upload/vod/20241016-1/2f70bd2710298efb95fe644a4482b535.jpg', '<p>Hứa Khuynh Du và Phạm Vân Tích bên nhau đã hơn 10 năm và đang chuẩn bị tiến tới hôn nhân. Thế nhưng, khi phát hiện vị hôn phu lừa dối, Khuynh Du nhất quyết đòi chia tay. Ngay lúc này, định mệnh lại sắp đặt Khuynh Du &quot;va phải&quot; Mạc Linh Trạch, trai đẹp ban ngày làm CEO ban đêm là ca sĩ chính kiêm tay guitar cho một ban nhạc. Câu chuyện của họ hứa hẹn sẽ rất thú vị khi cả hai đều là những người tài giỏi trong công việc nhưng là kẻ thất bại trong chuyện tình cảm.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"張予曦","avatar":""},{"name":"劉學義","avatar":""},{"name":"Yuanyuan Zhao","avatar":""},{"name":"古子成","avatar":""},{"name":"Li Siqi","avatar":""},{"name":"Chen Pengwanli","avatar":""},{"name":"Yumiko Cheng","avatar":""},{"name":"Zeng Youzhen","avatar":""},{"name":"Li Zifeng","avatar":""},{"name":"Tian Yuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["When the Darkness Falls","Ye Sik Am Yung Si","Ye Se An Yong Shi","夜色暗涌时","Secret and Passionate Love","Love At Night","夜色暗涌時","夜色暗湧時"]', 1784690324318);
