INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-le-ac-mong', 'Thánh Lễ Ác Mộng', 'Midnight Mass', 'https://phimimg.com/upload/vod/20241015-1/c42be132cda5ef757b8b8f8dc1f6e885.jpg', 'https://phimimg.com/upload/vod/20241015-1/43c6b608eda30ed56edf9ac23cec51f6.jpg', '<p>Vị linh mục trẻ lôi cuốn mang đến những phép màu huy hoàng, bí ẩn tăm tối và làm sống lại đức tin cho một thị trấn đang chết dần chết mòn và rất cần có niềm tin.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hamish Linklater","avatar":""},{"name":"Zach Gilford","avatar":""},{"name":"Kate Siegel","avatar":""},{"name":"Henry Thomas","avatar":""},{"name":"Kristin Lehman","avatar":""},{"name":"Samantha Sloyan","avatar":""},{"name":"Rahul Kohli","avatar":""},{"name":"Igby Rigney","avatar":""},{"name":"Annarah Cymone","avatar":""},{"name":"Annabeth Gish","avatar":""},{"name":"Alex Essoe","avatar":""},{"name":"Michael Trucco","avatar":""},{"name":"Crystal Balint","avatar":""},{"name":"Rahul Abburi","avatar":""},{"name":"Matt Biedel","avatar":""},{"name":"Robert Longstreet","avatar":""},{"name":"Louis Oliver","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Misa de Medianoche","มิดไนท์ แมส","Midnight Mass"]', 1784690324318);
