INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thanh-le-ac-mong', 'Thánh Lễ Ác Mộng', 'Midnight Mass', 'thánh lễ ác mộng midnight mass hamish linklater zach gilford kate siegel henry thomas kristin lehman samantha sloyan rahul kohli igby rigney annarah cymone annabeth gish alex essoe michael trucco crystal balint rahul abburi matt biedel robert longstreet louis oliver misa de medianoche มิดไนท์ แมส midnight mass', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-no-ke-huy-diet-go-cua-nha-toi', 'Một Ngày Nọ Kẻ Huỷ Diệt Gõ Cửa Nhà Tôi', 'Doom at Your Service', 'https://phimimg.com/upload/vod/20241015-1/ab7837d2df24cba3c0a8cd23476e4206.jpg', 'https://phimimg.com/upload/vod/20241015-1/7dd6211cf5a0d189d6783698f59ded55.jpg', '<p>Một Ngày Nọ Kẻ Hủy Diệt Gõ Cửa Nhà Tôi xoay quanh nhân vật Tak Dong Kyung, một cô gái mạnh mẽ và lương thiện. Sau khi bố mẹ qua đời, cô đã làm việc rất chăm chỉ, mong cuộc sống của mình sẽ tốt lên qua từng ngày. Công việc biên tập tiểu thuyết web trong 6 năm dần đi vào ổn định, thì cô bị chẩn đoán mắc bệnh ung thư não. Cô đổ lỗi cho cuộc sống kém may mắn của mình và mong muốn mọi thứ biến mất, công bằng với mình hơn. Đúng lúc này, Myeol Mang xuất hiện, anh là sứ giả giữa con người và các vị thần. Anh có thể ban cho cô ấy những điều ước, giống như điều ước cuối cùng của Dong Kyung. Lúc này, cô chỉ cần 100 ngày để sống theo cách của mình, mạo hiểm với tất cả mọi thứ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"박보영","avatar":""},{"name":"서인국","avatar":""},{"name":"이수혁","avatar":""},{"name":"강태오","avatar":""},{"name":"Shin Do-hyun","avatar":""},{"name":"Dawon","avatar":""},{"name":"우희진","avatar":""},{"name":"정지소","avatar":""},{"name":"이승준","avatar":""},{"name":"Park Tae-in","avatar":""},{"name":"Song Joo-hee","avatar":""},{"name":"Choi So-yoon","avatar":""},{"name":"송진우","avatar":""},{"name":"남다름","avatar":""},{"name":"Daniel C. Kennedy","avatar":""},{"name":"Jeong Min-gyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["某一天灭亡走进我家门","某天，灭亡从我家玄关进来了","אל ההרס לשירותך","あるひ、わたしのいえのげんかんにめつぼうがはいってきた","myeolmang","멸망","어느날 우리집 현관으로 멸망이 들어왔다","Судьба в вашем распоряжении","Гибель к вашим услугам","Однажды разрушение вошло в дверь моего дома","One Day, Destruction Entered the Front Door of My House","어느 날 우리 집 현관으로 멸망이 들어왔다"]', 1784690324318);
