INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-ngay-no-ke-huy-diet-go-cua-nha-toi', 'Một Ngày Nọ Kẻ Huỷ Diệt Gõ Cửa Nhà Tôi', 'Doom at Your Service', 'một ngày nọ kẻ huỷ diệt gõ cửa nhà tôi doom at your service 박보영 서인국 이수혁 강태오 shin do-hyun dawon 우희진 정지소 이승준 park tae-in song joo-hee choi so-yoon 송진우 남다름 daniel c. kennedy jeong min-gyu 某一天灭亡走进我家门 某天，灭亡从我家玄关进来了 אל ההרס לשירותך あるひ、わたしのいえのげんかんにめつぼうがはいってきた myeolmang 멸망 어느날 우리집 현관으로 멸망이 들어왔다 судьба в вашем распоряжении гибель к вашим услугам однажды разрушение вошло в дверь моего дома one day, destruction entered the front door of my house 어느 날 우리 집 현관으로 멸망이 들어왔다', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giup-be-hoc-tu-vung-toan', 'Giúp bé học từ vựng: Toán!', 'Word Party Presents: Math!', 'https://phimimg.com/upload/vod/20241015-1/47668fa3ac54fb911ff11b1d2da73197.jpg', 'https://phimimg.com/upload/vod/20241015-1/e405224bb72f9466aea80e9ad3f912db.jpg', '<p>Hãy đếm số, so sánh hình dạng và tìm mẫu hình cùng các bé thú Franny, Bailey, Kip, Lulu và Tilly khi các em vận dụng toán học và ca hát để xử lý vấn đề.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Misty Rosas","avatar":""},{"name":"John Tartaglia","avatar":""},{"name":"Alice Dinnean","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["La fête des mots : Vive les maths !","מסיבת מילים: חשבון!","מסיבת מילים חשבון","신나는 글자축제: 수학이 좋아!","신나는 글자 축제: 수학이 좋아!","Kelime Partisi Dersimiz Matematik!","Word Party Presents: Math!"]', 1784690324318);
