INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('john-cua-chua-thay-tam-linh-va-toi-pham', 'John của Chúa: Thầy tâm linh và tội phạm', 'John of God: The Crimes of a Spiritual Healer', 'https://phimimg.com/upload/vod/20241015-1/a67c3abbebb7140a6eb1b4edfcae2699.jpg', 'https://phimimg.com/upload/vod/20241015-1/90fd95e16cb83ba9cf6c5ada53c80c5a.jpg', '<p>Thầy đồng được tôn thờ João Teixeira de Faria vang danh quốc tế trước khi bị các nạn nhân, công tố viên và báo chí tiết lộ tội ác xâm phạm kinh hoàng.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 14, 2021, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Andrea Mannelli","avatar":""},{"name":"Rejane Araújo","avatar":""},{"name":"Jardel Wagner","avatar":""},{"name":"Norberto Kist","avatar":""},{"name":"Angela Homercher","avatar":""},{"name":"Luciano Miranda Meireles","avatar":""},{"name":"Gabriela Manssur","avatar":""},{"name":"Maria Helena Machado","avatar":""},{"name":"Marina Brito","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["João de Deus: Cura e Crime"]', 1784690324318);
