INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('john-cua-chua-thay-tam-linh-va-toi-pham', 'John của Chúa: Thầy tâm linh và tội phạm', 'John of God: The Crimes of a Spiritual Healer', 'john của chúa: thầy tâm linh và tội phạm john of god: the crimes of a spiritual healer andrea mannelli rejane araújo jardel wagner norberto kist angela homercher luciano miranda meireles gabriela manssur maria helena machado marina brito joão de deus: cura e crime', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ban-dieu-ky-2021', 'Tình Bạn Diệu Kỳ', 'The Best Friend', 'https://phimimg.com/upload/vod/20241015-1/43fc984f8c4c0f84ed3df59fd783d505.jpg', 'https://phimimg.com/upload/vod/20241015-1/d2663f98a2be1df39b50391fbc7aebea.jpg', '<p>Tình Bạn Diệu Kỳ - The Best Friend bắt đầu với cuộc sống đại học của sáu sinh viên chuyên ngành Nhật Bản, với Lin và Shao là nhân vật chính. Lin là một thanh niên nhạy cảm nhưng cực kỳ bướng bỉnh, không chịu nhờ người khác giúp đỡ trong bất kỳ khó khăn nào; trong khi Shao là người tháo vát, cởi mở và bổ sung một cách hoàn hảo tính cách của Lin. Họ nhanh chóng thành bạn bè và tham gia vào một loạt sự kiện và cuộc phiêu lưu. Họ hỗ trợ nhau vượt qua những khó khăn. Tuy nhiên, tính cách trái ngược của họ cũng tạo ra những cuộc tranh cãi và mâu thuẫn không ngừng. Cuối cùng thì Lin và Shao rời xa nhau. 10 năm sau, hai người gặp lại nhau. Họ bỏ qua những bất đồng trong quá khứ phù phiếm thời đại học, và câu chuyện tình bạn tiếp tục từ đó.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xinchi Xu","avatar":""},{"name":"陈沐","avatar":""},{"name":"杨皓羽","avatar":""},{"name":"Wang Yueyi","avatar":""},{"name":"Wang Yijun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["the Best Friend","最好的朋友"]', 1784690324318);
