INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-tam-biet-me', 'Xin Chào, Tạm Biệt Mẹ', 'The Last Goodbye to Mama', 'https://phimimg.com/upload/vod/20241015-1/d64ce4b699d29a199fda1a0d202a3bfe.jpg', 'https://phimimg.com/upload/vod/20241015-1/e13f5192b36c8fa3d6d83296dd5edb2b.jpg', '<p>Xin Chào, Tạm Biệt Mẹ - The Last Goodbye To Mama là câu chuyện cảm động xoay quanh cuộc sống của hai mẹ con đến từ một thị trấn nhỏ ở Tô Bắc. Thanh niên 18 tuổi Ding Xiao Jun được nhận vào một trường đại học ở Bắc Kinh và bắt đầu cuộc sống nổi loạn, ngỗ nghịch. Xiao Jun đã không thể tốt nghiệp đại học nếu như mẹ anh không đến xin nhà trường. Sau khi tốt nghiệp, Ding Xiao Jun bị lừa hết số tiền kiếm được và trở thành một kẻ ăn bám trong nhiều tháng. Bắt đầu hiểu được tất cả những khó khăn mà mẹ đã phải trải qua, Xiao Jun đã cố gắng để được quay về với mẹ. Trong đêm giao thừa, Ding Xiao Jun nhận được tin trúng tuyển vào 1 công ty ở Bắc Kinh, cũng là lúc anh nhận tin mẹ bị chẩn đoán mắc bệnh nan y. Ding Xiao Jun phải đối mặt với hai lựa chọn: tiếp tục xây dựng sự nghiệp ở Bắc Kinh hay về nhà với mẹ trong những ngày cuối đời của bà.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"董潔","avatar":""},{"name":"Yin Fang","avatar":""},{"name":"Lu Fangsheng","avatar":""},{"name":"王楚然","avatar":""},{"name":"Zhao Wei","avatar":""},{"name":"Lu Cai","avatar":""},{"name":"Chen Jiawen","avatar":""},{"name":"Jiang Xueming","avatar":""},{"name":"Zhang Yao","avatar":""},{"name":"Ran Xu","avatar":""},{"name":"Qu Shanshan","avatar":""},{"name":"Zeng Qi","avatar":""},{"name":"Gong Lei","avatar":""},{"name":"He Xuanlin","avatar":""},{"name":"Du Shuangyu","avatar":""},{"name":"Gong Zhengye","avatar":""},{"name":"Liang Yue Jun","avatar":""},{"name":"Zhou Dehua","avatar":""},{"name":"Cao Yanyan","avatar":""},{"name":"Han Xiuyi","avatar":""},{"name":"方悅喬","avatar":""},{"name":"Yin Yuhang","avatar":""},{"name":"Zhou Lula","avatar":""},{"name":"Zhang Le","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["99 Things With My Mom , Zai Jian La Mu Qin Da Ren , 再见啦！母亲大人 , 与母亲的99件小事","再见啦！母亲大人","再见啦母亲大人","The Last Goodbye To Mama","니호!모친대인 : 안녕! 엄마","您好！母亲大人"]', 1784690324318);
