INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xin-chao-tam-biet-me', 'Xin Chào, Tạm Biệt Mẹ', 'The Last Goodbye to Mama', 'xin chào, tạm biệt mẹ the last goodbye to mama 董潔 yin fang lu fangsheng 王楚然 zhao wei lu cai chen jiawen jiang xueming zhang yao ran xu qu shanshan zeng qi gong lei he xuanlin du shuangyu gong zhengye liang yue jun zhou dehua cao yanyan han xiuyi 方悅喬 yin yuhang zhou lula zhang le 99 things with my mom , zai jian la mu qin da ren , 再见啦！母亲大人 , 与母亲的99件小事 再见啦！母亲大人 再见啦母亲大人 the last goodbye to mama 니호!모친대인 : 안녕! 엄마 您好！母亲大人', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thap-nhi-dam', 'Thập Nhị Đàm', 'Twelve Legends', 'https://phimimg.com/upload/vod/20241015-1/2f0f9ec11938ebabc32b9f948bd21568.jpg', 'https://phimimg.com/upload/vod/20241015-1/dd5d4cd8906b8f5b136f70165a30da46.jpg', '<p>Nội dung phim xoay quanh câu chuyện về yêu tinh Dạ Minh (Cổ Lực Na Trát) và vị thần Kim Tính Kiên (Lưu Dĩ Hào). Kim Tính Kiên được hoá thành từ một hòn đá, mang trong mình sức mạnh nửa thần nửa yêu. Với tuổi đời 2000 năm, Kim Tính Kiên luôn xuất hiện với gương mặt lạnh lùng. Với tình yêu sâu đậm và chân thành, Kim Tính Kiên có thể chờ đợi hàng thiên niên kỷ để được ở bên người con gái mình yêu - Dạ Minh. Nàng là nữ yêu tinh Dạ Minh do dạ minh châu tu luyện thành, có tính cách vui vẻ, hồn nhiên, yêu cuộc sống và thích sự tự do. Nhưng nàng bị Kim Tính Kiên giam cầm trong nhiều năm và sẵn sàng giết những ai gây ảnh hưởng đến cuộc sống của người con gái anh yêu. Vì thế nàng rất căm ghét Kim Tính Kiên. Tình yêu, những khó khăn, thử thách giữa thế giới huyền bí nửa thần nửa yêu, cùng sự thù hận đan xen kéo dài đến hàng nghìn năm. Nhưng qua các diễn biến của bộ phim, câu chuyện tình yêu hài hước, cảm động và vô cùng ngọt ngào sẽ được mở ra.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 9, 2021, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"古力娜扎","avatar":""},{"name":"劉以豪","avatar":""},{"name":"刘畅","avatar":""},{"name":"Jason Koo","avatar":""},{"name":"周峻緯","avatar":""},{"name":"Zhang Qiaoer","avatar":""},{"name":"楊之楹","avatar":""},{"name":"Yusi Chen","avatar":""},{"name":"邓恩熙","avatar":""},{"name":"邊程","avatar":""},{"name":"Larina Zhang","avatar":""},{"name":"魏哲鸣","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Twelve Tan","Twelve Legends","Shi''er tan","12 Legend","十二谭"]', 1784690324318);
