INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bau-troi-ruc-do', 'Bầu Trời Rực Đỏ', 'Lovers of the Red Sky', 'https://phimimg.com/upload/vod/20241015-1/df08237b684d8d452881c972fd8cf0b1.jpg', 'https://phimimg.com/upload/vod/20241015-1/8080e8d73d1fff9b670918381c19f5c6.jpg', '<p>Bầu Trời Rực Đỏ diễn ra trong bối cảnh thời đại Joseon. Phim xoay quanh nàng Hong Chun Gi (Kim Yoo Jung) - nữ họa sĩ đầu tiên và cũng là cuối cùng của triều đại này. Nàng sở hữu ngoại hình vô cùng xinh đẹp, tính cách tươi sáng cùng tài năng hội họa được thừa hưởng từ cha. Với nàng, hội họa là tất cả. Dù bị mù bẩm sinh nhưng nàng đã lấy lại được thị lực một cách thần kỳ. Cho đến một ngày, Hong Chun Gi gặp Ha Ram (Ahn Hyo Seop) - một viên chức tại Seowoongwan, chuyên phụ trách thiên văn, địa lý, khí tượng học và nghệ thuật bói toán. Ha Ram cũng bị mù từ nhỏ sau một tai nạn nhưng vẫn có thể đọc được thiên văn và các vì sao. Từ những cuộc gặp gỡ, 2 người đã nảy sinh tình cảm với nhau.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"김유정","avatar":""},{"name":"안효섭","avatar":""},{"name":"공명","avatar":""},{"name":"곽시양","avatar":""},{"name":"이보희","avatar":""},{"name":"고규필","avatar":""},{"name":"Yoon Sa-bong","avatar":""},{"name":"Lee Sang-un","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Lovers of the Red Sky","Hongcheongi","Hongcheonki","Hong Chun Gi","홍천기"]', 1784690324318);
