INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-canh-sat', 'Học Viện Cảnh Sát', 'Police University', 'https://phimimg.com/upload/vod/20241016-1/283096f17912f7ef47abc3d7fb3ca263.jpg', 'https://phimimg.com/upload/vod/20241016-1/f11e027e3bea7a12dfb2afd478bbecab.jpg', '<p>Bộ phim mô tả câu chuyện trong khuôn viên trường Đại học Cảnh sát Quốc gia. Giáo sư Yoo Dong-Man có 20 năm kinh nghiệm trong lĩnh vực điều tra tội phạm giết người và gặp gỡ sinh viên năm nhất Kang Seon-Ho, một cựu hacker và Oh Kang-Hee, một sinh viên chính trực năm nhất thông minh, họ thành lập một nhóm để cùng điều tra. Bộ phim cũng cho thấy sự xung đột và hòa hợp giữa giáo sư và sinh viên.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"차태현","avatar":""},{"name":"정진영","avatar":""},{"name":"정수정","avatar":""},{"name":"홍수현","avatar":""},{"name":"이종혁","avatar":""},{"name":"서예화","avatar":""},{"name":"추영우","avatar":""},{"name":"Yoo Young-jae","avatar":""},{"name":"Choi Yi-sun","avatar":""},{"name":"강신일","avatar":""},{"name":"송진우","avatar":""},{"name":"Yoon Jin-Ho","avatar":""},{"name":"유태웅","avatar":""},{"name":"신승환","avatar":""},{"name":"오만석","avatar":""},{"name":"최우성","avatar":""},{"name":"김영선","avatar":""},{"name":"Byeon Seo-yun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Police Academy","警察学院","경찰수업","วิทยาลัยการตำรวจ"]', 1784690324318);
