INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-lai-cham-tinh-ha', 'Xuân Lai Chẩm Tinh Hà', 'Cry Me A River of Stars', 'https://phimimg.com/upload/vod/20241013-1/f426cb08dfd203bf471a4cdb0575cb8e.jpg', 'https://phimimg.com/upload/vod/20241013-1/73cd56adb4865e55f5cb0ebe07e05f90.jpg', '<p>Xuân Lai Chẩm Tinh Hà kể về câu chuyện giữa Đào Quân Nhiên (do La Chính thủ vai) một phán quan đẹp trai, văn võ song toàn và A Sở (Hoàng Nhật Oánh thủ vai), chủ nhân của con thuyền sơn cước - người coi trọng tình yêu và lẽ phải. Trong quá trình quen biết, họ đã trải qua hàng loạt câu chuyện éo le. Đào Quân Nhiên muốn tiếp cận thuyền sơn cước để điều tra một vụ án cũ còn A Sở thì muốn lấy lòng chàng phán quan, mỗi người đều có ý định riêng và rồi họ bắt đầu xích lại gần nhau hơn lúc nào chẳng hay.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Luo Zheng","avatar":""},{"name":"黄日莹","avatar":""},{"name":"文竹","avatar":""},{"name":"冯荔军","avatar":""},{"name":"王術一","avatar":""},{"name":"Sang Na","avatar":""},{"name":"Zheng Tuojiang","avatar":""},{"name":"严子贤","avatar":""},{"name":"Xu Bing","avatar":""},{"name":"Hu Wei","avatar":""},{"name":"Tan Qinxuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["봄이 오면 은하수를 베개 삼으리","CLZXH","별빛 로맨스 춘래침성하","Sleeping in the Galaxy in Spring","春来枕星河"]', 1784690324318);
