INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xuan-lai-cham-tinh-ha', 'Xuân Lai Chẩm Tinh Hà', 'Cry Me A River of Stars', 'xuân lai chẩm tinh hà cry me a river of stars luo zheng 黄日莹 文竹 冯荔军 王術一 sang na zheng tuojiang 严子贤 xu bing hu wei tan qinxuan 봄이 오면 은하수를 베개 삼으리 clzxh 별빛 로맨스 춘래침성하 sleeping in the galaxy in spring 春来枕星河', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-gian-va-em-biet-lai-vo-dang', 'Thời Gian Và Em Biệt Lai Vô Dạng', 'Timeless Love', 'https://phimimg.com/upload/vod/20241013-1/81f3e9e4b0ff18d67c730bcd3c0ec90a.jpg', 'https://phimimg.com/upload/vod/20241013-1/28d89831b199a1dc7f26b6d5b6d717d8.jpg', '<p>Anh chàng đẹp trai vẻ ngoài lạnh lùng nhưng yêu thương bạn gái Khương Điên bất ngờ chui vào trong sách, gặp tình yêu sét đánh với cô gái mạnh mẽ Trình Phùng nhưng lại bị từ chối. Khương Điên không ngừng theo đuổi và gỡ được nút thắt trong lòng Trình Phùng, hai người bắt đầu sống chung. Sau khi Khương Điên và Trình Phùng sống cùng nhau, những trở ngại đến từ thế giới bên ngoài cũng lần lượt kéo đến. Hai người không thể đi tiếp vì nhiều lý do, cuối cùng phải chia tay do nhiều thứ áp lực. Nhưng hai người đã hẹn phải trở thành một bản thân mạnh mẽ hơn...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xu Yiyang","avatar":""},{"name":"Chen Youwei","avatar":""},{"name":"Cai Xiangyu","avatar":""},{"name":"Fu Weilun","avatar":""},{"name":"郑玉佳","avatar":""},{"name":"Tian Yifan","avatar":""},{"name":"Jiang Zhenyu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shi Guang Yu Ni Bie Lai Wu Yang","SGYNBLWY","時光與你別來無恙","时光与你别来无恙"]', 1784690324318);
