INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-hoan-nay-ta-khong-dung-duoc', 'Nha Hoàn Này Ta Không Dùng Được', 'Maid Escort', 'https://phimimg.com/upload/vod/20241013-1/6be46d9819d65e97a4a5964022c29d3d.jpg', 'https://phimimg.com/upload/vod/20241013-1/f57e6dbe8e403f5703961d45d82fb4fc.jpg', '<p>Nha Hoàn Này Ta Không Cần kể về nha hoàn Nhạc Tử Duyên giúp đỡ tiểu thư Bạch Ngân Nhược thành thân với Dương Tiêu, nhưng bất ngờ rơi vào lưới tình với vị hôn phu của tiểu thư. Hai người liên minh điều tra chân tướng chuyện cha mẹ mình bị hại năm xưa, khôi phục lại con đường buôn bán, dệt lên câu chuyện trưởng thành huyền thoại ngọt ngào đầy màu sắc.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zheng Qiuhong","avatar":""},{"name":"Wang Runze","avatar":""},{"name":"Shao Xingying","avatar":""},{"name":"林楓松","avatar":""},{"name":"Xiong Yuexi","avatar":""},{"name":"Ren Yinsong","avatar":""},{"name":"Jiang Sheng Nan","avatar":""},{"name":"Hu Haofan","avatar":""},{"name":"Qiao Xinfeng","avatar":""},{"name":"Chen Jiayi","avatar":""},{"name":"邓灵枢","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["这丫环我用不起"]', 1784690324318);
