INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-lai-do-truyen-thuyet-nam-duong', 'Người Lái Đò: Truyền Thuyết Nam Dương', 'The Ferryman: Legends of Nanyang', 'https://phimimg.com/upload/vod/20241013-1/935b0940e842a496655b7d58e391f55b.jpg', 'https://phimimg.com/upload/vod/20241013-1/d213df2370b72e8d9bdb7522a42c93a7.jpg', '<p>Hạ Đông Thanh cùng người dẫn độ linh hồn Triệu Lại giúp các linh hồn chưa hoàn thành tâm nguyện mà phải ở lại nhân gian. Hạ Đông Thanh với vẻ ngoài không mấy nổi bật nhưng lại Đôi Mắt Âm Dương có thể nhìn thấy người chết. Bí mật này đã mang lại rất nhiều rắc rối cho Hạ Đông Thanh.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kate Kinney","avatar":""},{"name":"王冠逸","avatar":""},{"name":"Qi Yuwu","avatar":""},{"name":"欧萱","avatar":""},{"name":"Ping Hui Tay","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Ling Hun Bai Du Zhi Nan Yang Chuan Shuo","灵魂摆渡之南洋传说"]', 1784690324318);
