INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-xu-nguoi-toi-rat-on', 'Nơi Xứ Người Tôi Rất Ổn', 'Remembrance of Things Past', 'https://phimimg.com/upload/vod/20241013-1/984ea4a69baba13d1bcfd4ebf81a07c8.jpg', 'https://phimimg.com/upload/vod/20241013-1/444175c90f48dcd79c695215bba3a838.jpg', '<p>Nơi Xứ Người Tôi Rất Ổn (Remembrance of Things Past) là bộ phim với câu chuyện xoay quanh những người phụ nữ và đàn ông sinh ra trong những năm 80 và 90 gặp nhau ở Bắc Kinh. Dù cuộc sống ở nơi đô thị có phần bon chen, áp lực nhưng họ vẫn giữ vững ước mơ của mình và trải qua nhiều thử thách khác nhau trong cuộc sống, tình yêu và sự nghiệp.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"周雨彤","avatar":""},{"name":"Suxi Ren","avatar":""},{"name":"Sun Qian","avatar":""},{"name":"白宇帆","avatar":""},{"name":"Ma Sichao","avatar":""},{"name":"Dai Yunfan","avatar":""},{"name":"Gong Beibi","avatar":""},{"name":"Xiu Meng","avatar":""},{"name":"金靖","avatar":""},{"name":"Hu Linxi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Remembrance of Things Past","我在他鄉挺好的","我在他乡挺好的"]', 1784690324318);
