INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('noi-xu-nguoi-toi-rat-on', 'Nơi Xứ Người Tôi Rất Ổn', 'Remembrance of Things Past', 'nơi xứ người tôi rất ổn remembrance of things past 周雨彤 suxi ren sun qian 白宇帆 ma sichao dai yunfan gong beibi xiu meng 金靖 hu linxi remembrance of things past 我在他鄉挺好的 我在他乡挺好的', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-tu-ta-cuoi-chang-chac-roi-2', 'Công Tử Ta Cưới Chàng Chắc Rồi 2', 'Honey Don''t Run Away 2', 'https://phimimg.com/upload/vod/20241013-1/879f4397a0445233ccf6b6a6d8192f78.jpg', 'https://phimimg.com/upload/vod/20241013-1/ed4e962909e019efa79ef9e9fbd85d3d.jpg', '<p>Diệp Tiểu Đường người giàu nhất kinh thành và Mộ Cẩn Ngôn chàng công tử nổi tiếng có tình cảm với nhau. Nhưng số phận sắp đặt hai người là truyền nhân của tộc Chúc Do và Mô Cốt Thuật, vận mệnh tương khắc. Để giải trừ vận mệnh của mình, cả hai kết giao cùng Lăng Tử Nhiên Cửu hoàng tử của nước Lăng và Việt U Nhi công chúa của nước Việt bắt đầu hành trình đi tìm báu vật. Trong hành trình nguy hiểm này, đã tôi luyện được sự trưởng thành và mỗi người cũng có được tình yêu đích thực của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hạc Nam","avatar":""},{"name":"Khưu Sĩ Luân","avatar":""},{"name":"Wen Yuan","avatar":""},{"name":"shàngxuán","avatar":""},{"name":"Zhou Bo Xuan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["I Decide to Marry You","金主大人请自重","公子，我娶定你了2","Honey, Don''t Run Away 2","公子，我娶定你了"]', 1784690324318);
