INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-la-hung-thu', 'Ai Là Hung Thủ', 'Who Is The Murderer', 'https://phimimg.com/upload/vod/20241013-1/ac857daa6884121c14df4c139d623e7c.jpg', 'https://phimimg.com/upload/vod/20241013-1/c23001ac00d1e2ab5cf7930495235c2d.jpg', '<p>Một vụ án mạng xảy ra trong một nhà máy in ấn ở thành phố Hải Chu. Cảnh sát mới vào nghề Lãnh Tiểu Binh và đàn anh nhận được báo án liền đi tới hiện trường, đối mặt với sát thủ Lãnh Tiểu Binh nhát gan không dám nổ súng, hung thủ từ hiện trường bỏ trốn giết chết đàn anh Lý Lam. Nhân chứng khác ở hiện trường là con của người bị hại trốn dưới gầm giường, Hạ Mục. Để có thể tiếp tục ở lại đội hình sư, Lãnh Tiểu Băng che giấu việc không dám nổ súng, Hạ Mộc cũng không dám vạch trần anh ta. Còn về hung thủ lại ẩn mình, vụ án ở Hải Chu chưa được giải quyết. 16 năm sau, Hạ Mộc tới đội hình sự thực tập, nắm thóp chuyện Lãnh Tiểu Băng không dám nổ súng, ép anh ta cùng điều tra án với mình. Vài lúc hai người nghi ngờ bố của bác sĩ tâm lý Thẩm Vũ, Thẩm Vũ cũng bắt đầu kế hoạch mô phỏng tội phạm giúp chồng thoát tội. Sau đó một bộ xương với thời gian tử vong quá 16 năm làm 3 người rơi vào màn đêm sâu thẳm. Cuối cùng ba người bắt tay cùng bắt hung thủ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"赵丽颖","avatar":""},{"name":"肖央","avatar":""},{"name":"董子健","avatar":""},{"name":"王茂蕾","avatar":""},{"name":"李光复","avatar":""},{"name":"刘琳","avatar":""},{"name":"高露","avatar":""},{"name":"周奇","avatar":""},{"name":"Yao Anlian","avatar":""},{"name":"Mo Yang","avatar":""},{"name":"Zhang Yang","avatar":""},{"name":"常鋮","avatar":""},{"name":"Jiang Zhuojun","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["未知罪","Who Is the Murderer","Shei Shi Xiong Shou","誰是兇手","Light on Series - Who Is Murderer","谁是凶手"]', 1784690324318);
