INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-ket-hon-va-ly-di-mua-1', 'Yêu (Kết Hôn và Ly Dị) Mùa 1', 'Love (ft. Marriage and Divorce) Season 1', 'https://phimimg.com/upload/vod/20241013-1/80b405ef384af79f2ee853921971e53c.jpg', 'https://phimimg.com/upload/vod/20241013-1/7163a5dbae644f2bf118238adf0f462d.jpg', '<p>Mọi thứ dần sụp đổ với ba phụ nữ chạy chương trình radio thành đạt khi các nút thắt, bước ngoặt và rắc rối nảy sinh trong những cuộc hôn nhân tưởng như hạnh phúc của họ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"성훈","avatar":""},{"name":"이가령","avatar":""},{"name":"이태곤","avatar":""},{"name":"박주미","avatar":""},{"name":"전노민","avatar":""},{"name":"전수경","avatar":""},{"name":"김응수","avatar":""},{"name":"김보연","avatar":""},{"name":"전혜원","avatar":""},{"name":"Lee Min-young","avatar":""},{"name":"Moon Sung-Ho","avatar":""},{"name":"송지인","avatar":""},{"name":"윤서현","avatar":""},{"name":"Gi So-you","avatar":""},{"name":"Lim Hye-Young","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Amor Casamento E Divórcio","Marriage Lyrics and Divorce Music","Love Ft Marriage and Divorce","Love (ft. Marriage and Divorce)","结婚故事","结婚作词 离婚作曲","결혼 이야기","Брачная лирика","Свадебные слова для музыки развода","Лирика брака и музыка развода","결혼작사 이혼작곡"]', 1784690324318);
