INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-bi-vui-lap-phan-2', 'Bí Mật Bị Vùi Lấp (Phần 2)', 'Outer Banks (Season 2)', 'https://phimimg.com/upload/vod/20241013-1/d137f9812f2e469e513a2c23a0ead8cc.jpg', 'https://phimimg.com/upload/vod/20241013-1/08a612a682807b9c43c6c4450b6a92e0.jpg', '<p>Bí Mật Bị Vùi Lấp (Phần 2) tiếp nối câu truyện khi kho báu vàng đang bị đe dọa và tương lai của họ lâm nguy, nhóm Cá Mòi hấp tấp lao vào mối hiểm họa và bí ẩn mới khi họ đối mặt với cả kẻ thù cũ lẫn mới.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chase Stokes","avatar":""},{"name":"Madelyn Cline","avatar":""},{"name":"Madison Bailey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["아우터 뱅크스","아우터뱅크스","OBX","Outer Banks"]', 1784690324318);
