INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-dong-san-tru-ta', 'Bất Động Sản Trừ Tà', 'Sell Your Haunted House', 'https://phimimg.com/upload/vod/20241013-1/a697210516fdc70a1038a1f657fd8189.jpg', 'https://phimimg.com/upload/vod/20241013-1/1877026147aa8b107a357fdf24f694d5.jpg', '<p>Bộ phim với chủ đề siêu nhiên này kể về câu chuyện của Hong Ji-a (Jang Na-ra đóng), một thầy trừ tà nhưng lại điều hành một công ty bất động sản. Không phải là người môi giới thông thường, nhân vật này chuyên giải bùa ếm, giúp các khu đất trở nên an toàn để tiện buôn bán. Tuy nhiên, Hong Ji-a có một nỗi ám ảnh mà cô không thể tự giải quyết, đó là cái chết bí ẩn của mẹ cô 20 năm trước. Người có thể giúp Hong Ji-a tìm hiểu tận gốc vấn đề của cô là Oh In-beom (do Jung Yong-hwa – thành viên nhóm nhạc CNBlue thủ vai), thực chất lại là một kẻ chuyên đi lừa đảo.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"장나라","avatar":""},{"name":"정용화","avatar":""},{"name":"강말금","avatar":""},{"name":"Kang Hong-suk","avatar":""},{"name":"안길강","avatar":""},{"name":"허동원","avatar":""},{"name":"백지원","avatar":""},{"name":"이채경","avatar":""},{"name":"최우성","avatar":""},{"name":"Park Han-sol","avatar":""},{"name":"Baek Eun-hae","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Продай обладания си дом","大发不动产","Daebakbudongsan","Адская недвижимость","Проклятая недвижимость","Крутое риэлторское агентство","Недвижимость «Дэбак»","大發不動產","The Chronicle of Haunted Real Estate","Real Estate Exorcism","Great Real Estate","Daebak Real Estate","대박부동산"]', 1784690324318);
