INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-gio-chung-ta-dang-chia-tay', 'Bây Giờ, Chúng Ta Đang Chia Tay', 'Now, We Are Breaking Up', 'https://phimimg.com/upload/vod/20241013-1/ea70dd089aedced3a8ecb12e82b25716.jpg', 'https://phimimg.com/upload/vod/20241013-1/0ba80a97e3ca0574708ed562f7cc0bfa.jpg', '<p>Phim kể về câu chuyện tình yêu hợp rồi tan đầy xúc động. Ha Young Eun (Song Hye Kyo) là quản lý của đội thiết kế tại một nhãn hiệu thời trang, một người theo chủ nghĩa hiện thực, thời thượng và rất thông minh. Trong khi đó, Yoon Jae Guk (Jang Ki Yong) là một nhiếp ảnh gia tự do giàu có và nổi tiếng, người cũng có trí tuệ và ngoại hình. Anh xuất hiện giữa thời điểm Ha Young Eun đang vô cùng tuyệt vọng và mệt mỏi. Từ đó, họ bắt đầu một tình yêu vô cùng đẹp như định mệnh sinh ra họ để dành cho nhau.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"송혜교","avatar":""},{"name":"장기용","avatar":""},{"name":"최희서","avatar":""},{"name":"김주헌","avatar":""},{"name":"박효주","avatar":""},{"name":"윤나무","avatar":""},{"name":"남기애","avatar":""},{"name":"Choi Hong-il","avatar":""},{"name":"차화연","avatar":""},{"name":"Moon Joo-yeon","avatar":""},{"name":"주진모","avatar":""},{"name":"장혁진","avatar":""},{"name":"윤정희","avatar":""},{"name":"세훈","avatar":""},{"name":"Song You-hyun","avatar":""},{"name":"Kim Bo-jeong","avatar":""},{"name":"Ha Yeong","avatar":""},{"name":"신동욱","avatar":""},{"name":"유라","avatar":""},{"name":"신승환","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["现正分手中","现在正在分手中","Теперь мы расстаемся","Теперь мы расстаёмся","А теперь мы расстаемся","現正分手中","Now, We’re Breaking Up","I''m Breaking Up Now","지금, 헤어지는 중입니다"]', 1784690324318);
