INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bay-gio-chung-ta-dang-chia-tay', 'Bây Giờ, Chúng Ta Đang Chia Tay', 'Now, We Are Breaking Up', 'bây giờ, chúng ta đang chia tay now, we are breaking up 송혜교 장기용 최희서 김주헌 박효주 윤나무 남기애 choi hong-il 차화연 moon joo-yeon 주진모 장혁진 윤정희 세훈 song you-hyun kim bo-jeong ha yeong 신동욱 유라 신승환 现正分手中 现在正在分手中 теперь мы расстаемся теперь мы расстаёмся а теперь мы расстаемся 現正分手中 now, we’re breaking up i''m breaking up now 지금, 헤어지는 중입니다', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-mat-na-khe-uoc-ac-ma', 'Hiệp Sĩ Mặt Nạ: Khế Ước Ác Ma', 'Kamen Rider: Revice', 'https://phimimg.com/upload/vod/20241013-1/75e5c222f597f718c2d51c6feccfeed6.jpg', 'https://phimimg.com/upload/vod/20241013-1/f63e3f237d9847f47a381c78ff90d912.jpg', '<p>Một giáo phái quỷ quyệt lợi dụng tâm ma của con người để tạo nên một đạo quân hùng mạnh, đe dọa an toàn của Nhật Bản. Trước tình cảnh đó, chính phủ Nhật thành lập tổ chức Fenix nhằm phát triển vũ khí mới có khả năng khai thác sức mạnh của ác quỷ để chống lại chính chúng. Khi hiểm họa đến ngày càng gần, Ikki - anh trai của một thành viên Fenix - đã ký kết khế ước với ác ma bên trong mình để trở thành Kamen Rider bảo vệ gia đình và thế giới.</p>', 'Hoàn Tất (50/50)', 50, 'hoathinh', 'completed', 10, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kentaro Maeda","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Wataru Hyuga","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["假面骑士利维斯","假面骑士Revice","Masked Rider Revice","Reiwa Rider 3","仮面ライダーリバイス"]', 1784690324318);
