INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-the-gioi', 'Hai Thế Giới', 'The Unidentical Twins', 'https://phimimg.com/upload/vod/20241011-1/546b9e0886e7c48f3bd41bec71e126c3.jpg', 'https://phimimg.com/upload/vod/20241011-1/5c9db8b88040cfc082528daa92417214.jpg', '<p>Phim được ramek lại từ phiên bản năm 2005 của CH7, kể về hai chị em song sinh Duenyard (Duen) &amp; Pilarluk (Pit) có khuôn mặt lẫn vóc dáng rất giống nhau nhưng tính cách khác nhau hoàn toàn. Duenyard là một người mẫu diễn viên nổi tiếng, có tính tình thất thường, vướng scandai không hay với một nghệ sĩ nhạc rock. Pilarluk trái ngược, hiền hậu, đơn giản, thầm yêu anh chàng Warit. Duen ganh tỵ với Pit, tạo ra mọi hiểu lầm để Warit chia tay chị gái mình nhằm quay sang chú ý đến cô nhưng không thành công. Ngày Warit và Pit tổ chức lễ cưới, Duen lên kế hoạch bắt cóc chị mình để thoã mãn cơn tức nhưng Pit không chống lại vì nghĩ mình chính là nguyên nhân khiến người em mà cô thương yêu nhất phải làm như vậy. Số phận của cặp chị em song sinh sẽ ra sao và hạnh phúc sẽ thuộc về ai?</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Kimberly Ann Voltemas","avatar":""},{"name":"เจมส์ อัศรัสกร","avatar":""},{"name":"Pichaya Nitipaisalkul","avatar":""},{"name":"Sheranut Yusananda","avatar":""},{"name":"Wattikorn Permsubhirun","avatar":""},{"name":"Namnung Suttidachanai","avatar":""},{"name":"ทรงสิทธิ์ รุ่งนพคุณศรี","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Song Sanaeha","The Unidentical Twins"]', 1784690324318);
