INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-hoang-phuong-nam-phan-5', 'Bà Hoàng Phương Nam (Phần 5)', 'Queen Of The South (Season 5)', 'https://phimimg.com/upload/vod/20241011-1/a2a6867d33c024afdb5a21aa5f94ea3a.jpg', 'https://phimimg.com/upload/vod/20241011-1/c64603d22bf36fef65f4d8ce50a9954f.jpg', '<p>Sau sự trở lại của một người quen, Teresa nhìn nhận lại việc cai trị của mình với tư cách bà trùm và cố luôn đi trước một bước so với đám giang hồ tàn nhẫn và CIA.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alice Braga","avatar":""},{"name":"Hemky Madera","avatar":""},{"name":"Peter Gadiot","avatar":""},{"name":"Veronica Falcón","avatar":""},{"name":"Molly Burnett","avatar":""},{"name":"Joaquim de Almeida","avatar":""},{"name":"Yancey Arias","avatar":""},{"name":"Justina Machado","avatar":""},{"name":"Gerardo Taracena","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Regina del Sud","QUEEN OF THE SOUTH/クイーン・オブ・ザ・サウス ～女王への階段～","남부의 여왕","Queen of the South"]', 1784690324318);
