INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-he-56k', 'Thế hệ 56k', 'Generation 56k', 'https://phimimg.com/upload/vod/20241011-1/860307bebf3fcda39b604bcb4abba199.jpg', 'https://phimimg.com/upload/vod/20241011-1/9cd9197548494c42bec14e5c55b7e36c.jpg', '<p>Cuộc gặp gỡ tình cờ khiến hai người đã ngoài 30 nhớ lại năm 1998, năm mà hoóc-môn tuổi dậy thì bắt đầu &quot;tác quái&quot; trong họ – và Internet thay đổi cuộc đời họ mãi mãi.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2021, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Angelo Spagnoletti","avatar":""},{"name":"Cristina Cappelli","avatar":""},{"name":"Gianluca Colucci","avatar":""},{"name":"Fabio Balsamo","avatar":""},{"name":"Alfredo Cerrone","avatar":""},{"name":"Azzurra Iacone","avatar":""},{"name":"Egidio Mercurio","avatar":""},{"name":"Gennaro Filippone","avatar":""},{"name":"Biagio Forestieri","avatar":""},{"name":"Claudia Tranchese","avatar":""},{"name":"Sebastiano Kiniger","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["拨号上网 80 后","Generation 56K","Generazione 56k"]', 1784690324318);
