INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-he-56k', 'Thế hệ 56k', 'Generation 56k', 'thế hệ 56k generation 56k angelo spagnoletti cristina cappelli gianluca colucci fabio balsamo alfredo cerrone azzurra iacone egidio mercurio gennaro filippone biagio forestieri claudia tranchese sebastiano kiniger 拨号上网 80 后 generation 56k generazione 56k', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-tao-no-hoa', 'Cây Táo Nở Hoa', 'Liver Or Die Vietnam Version', 'https://phimimg.com/upload/vod/20241010-1/1892981a8680c7404778daeff8a53f4a.jpg', 'https://phimimg.com/upload/vod/20241010-1/9050391ad6922527d8120bb13e93dcce.jpg', '<p>Cây táo nở hoa bắt đầu khi người cha của 5 đứa con đã trưởng thành đột nhiên quay về và chết. Đám ma kì quặc hé lộ những mâu thuẫn, bất ổn, bi kịch của nhà họ Đỗ bao gồm 5 người con: Ngọc, Ngà, Châu, Báu, Dư. Ngọc - anh trai cả trong 1 gia đình nghèo bình dân, phải đối mặt với rất nhiều bi kịch. Ngọc sống với các em trai em gái, vợ và con gái trong một căn nhà chật hẹp kiêm xưởng sửa chữa xe máy nhỏ. Cuộc sống đã khó khăn nhưng mọi sự ngày càng trở nên khó chấp nhận khi những người em vô cùng lười biếng, vô trách nhiệm đã không giúp đỡ mà còn gây ra vô vàn rắc rối. Ngà mê cờ bạc, liên tục chạy trốn chủ nợ và liên tục gây tai họa cho gia đình.</p>', 'Hoàn Tất (80/80)', 80, 'series', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hồng Ánh","avatar":""},{"name":"Thái Hòa","avatar":""},{"name":"Trương Thế Vinh","avatar":""},{"name":"Thúy Ngân","avatar":""},{"name":"Nhã Phương","avatar":""},{"name":"Song Luân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cây Táo Nở Hoa"]', 1784690324318);
