INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-vien-thong-thien', 'Thư Viện Thông Thiên', 'Celestial Authority Academy', 'https://phimimg.com/upload/vod/20241008-1/63dc8323ff29f854ebd1c844cb1f2cf1.jpg', 'https://phimimg.com/upload/vod/20241008-1/9fd479d4d36c3b5b225ffb06535c348c.jpg', '<p>Thư Viện Thông Thiên là câu chuyện ở Vương triều Thông Thiên, thái bình thịnh thế, bốn gia tộc Hoàng thất vì để củng cố địa vị của gia tộc nên đã lập ra thư viện Thông Thiên, ngay cả gia tộc Hoàng thất cũng phải tranh sứt đầu mẻ trán để được vào thư viện. Tác giả kỳ tài nổi tiếng có vô số người hâm mộ, đến cả Hoàng hậu cũng là fans trung thành của &quot;anh ta&quot;, thế là nhờ vào tài hoa hơn người đó của mình mà được tuyển thẳng vào thư viện Thông Thiên. Nhưng không ngờ rằng thiếu niên tài hoa có dung mạo tuyệt đẹp này lại là một nữ nhi, từ đó mở ra một câu chuyện tình yêu vườn trường đẹp đẽ ngọt ngào.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"周彥辰","avatar":""},{"name":"徐好","avatar":""},{"name":"Qin Fen","avatar":""},{"name":"Gao Maotong","avatar":""},{"name":"Han Mubo","avatar":""},{"name":"Yu Nai Jia","avatar":""},{"name":"Meng Zidi","avatar":""},{"name":"Wang Xinting","avatar":""},{"name":"Wang Chuang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Celestial Authority Academy","通天书院"]', 1784690324318);
