INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-da-chuyen-sinh-thanh-slime-nhat-ky-cua-rimuru', 'Tôi Đã Chuyển Sinh Thành Slime: Nhật Ký Của Rimuru', 'The Slime Diaries: That Time I Got Reincarnated as a Slime', 'tôi đã chuyển sinh thành slime: nhật ký của rimuru the slime diaries: that time i got reincarnated as a slime 岡咲美保 古川慎 千本木彩花 市道真央 江口拓也 大塚芳忠 柳田淳一 山本兼平 泊明日菜 小林親弘 福島潤 大久保瑠美 田中理恵 日高里菜 关于我转生变成史莱姆这档事 转生史莱姆日记 the slime diaries meine wiedergeburt als schleim - die schleim-tagebücher meine wiedergeburt als schleim in einer anderen welt - die schleim-tagebücher 転スラ日記 転スラ日記 転生したらスライムだった件 tensei shitara slime datta ken: tensura nikki tensura nikki: tensei shitara slime datta ken 전생했더니 슬라임이었던 건에 대하여: 전생슬라임 일기 щоденник слизу: коли я переродився слизом коли я  переродився слизом - щоденниик слизу the slime diaries: that time i got reincarnated as a slime 転生したらスライムだった件 転スラ日記', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-vuong-truy-the-nu-than-tro-ve', 'Tà Vương Truy Thê: Nữ Thần Trở Về', 'Be My Wife (Season 3)', 'https://phimimg.com/upload/vod/20241008-1/c9abaf845aaca8c61acda324897f042f.jpg', 'https://phimimg.com/upload/vod/20241008-1/ea7946187cd784470884a388ab50fa72.jpg', '<p>Tô Lạc bị tình địch Lý Dao Dao và sư phụ tiên nữ Yên Hà bắt lấy, bị họ tẩy phép thuật dị dung mà lộ ra khuôn mặt thật. Đồng thời, thân thế thần bí của cô cũng bị để lộ. Nhằm chạy thoát, Tô Lạc phá động phủ của tiên nữ Yên Hà, nhưng cô cũng bị thương nặng mà rơi vào biển. Người cứu cô lại là Vân Khởi, người yêu giết chết cô tại địa cầu và bây giờ Vân Khởi tỏ rõ mình biết bí ẩn về thân thế của Tô Lạc. Bên cạnh đó, Nam Cung đang dốc sức tìm Tô Lạc. Rốt cuộc Tô Lạc sẽ chọn đường ngắn vì thân thế mình, đi theo người bội bạc Vân Khởi, hay là trở về bên cạnh Nam Cung Lưu Vân cùng cố tìm chân tướng?</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324318);
