INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ta-vuong-truy-the-nu-than-tro-ve', 'Tà Vương Truy Thê: Nữ Thần Trở Về', 'Be My Wife (Season 3)', 'tà vương truy thê: nữ thần trở về be my wife (season 3)  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-tay-thanh-nien-khoi-nghiep', 'Sổ Tay Thanh Niên Khởi Nghiệp', 'Youth Entrepreneurship Manual', 'https://phimimg.com/upload/vod/20241008-1/125c38620778a9d06c5665aa69d11329.jpg', 'https://phimimg.com/upload/vod/20241008-1/db2274f6dbbdeac96840890dab98a523.jpg', '<p>La Lập Hạ gây dựng sự nghiệp ở Tokyo Nhật Bản nhận được tin tức mẹ bệnh tình nguy kịch, dứt khoát từ bỏ cổ phần công ty trở về nước. Trong lúc sự nghiệp, tình yêu đều phản bội, gặp được hai người sáng lập trẻ tuổi Tả Hữu và Sở Hà. La Lập Hạ bị nhiệt tình và cố chấp của hai người làm cảm động, quyết định lập nghiệp lần nữa với họ, lập chí muốn khiến khoa học kỹ thuật Trung Quốc phát triển rực rỡ trên thế giới. Lần này, mục tiêu bọn họ muốn đánh bại là La Lập Hạ từng một tay thành lập công ty khoa học kỹ thuật, là đối tác tốt nhất của họ trước đây. Sau khi trải qua vô số thất bại, tuyệt vọng, nản lòng thoái chí, ba người đến từ ba hoàn cảnh gia đình khác nhau dưới sự giúp đỡ của chính phủ và mọi tầng lớp nhân dân, lần lượt vượt qua khó khăn của bản thân và trưởng thành, mà tình bạn của ba người cũng càng thêm sâu sắc. Sau nhiều năm, bộ ba trở nên mạnh mẽ hơn cuối cùng đã đứng trên sân khấu nằm trong giấc mơ ban đầu của họ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"李茂","avatar":""},{"name":"涂冰","avatar":""},{"name":"Qiao Junda","avatar":""},{"name":"Jing Ling Xiao","avatar":""},{"name":"张层层","avatar":""},{"name":"Chen Siche","avatar":""},{"name":"Qian Yongchen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Youth Entrepreneurship Manual","青春创业手册"]', 1784690324318);
