INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-xa-la', 'Người Tình Xa Lạ', 'Lover or Stranger', 'https://phimimg.com/upload/vod/20241009-1/716375ecced2d50c3de1051181b7b315.jpg', 'https://phimimg.com/upload/vod/20241009-1/029348dbf128543ea57000c49959ccad.jpg', '<p>Người Tình Xa Lạ kể về câu chuyện của nghệ sĩ vĩ cầm La Thiên Di và vị hôn phu Lôi Hựu Trạch cùng nhau vén lên bức màn sương mù tìm ra sự thật, theo đuổi tình yêu thật sự.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"宋茜","avatar":""},{"name":"歐豪","avatar":""},{"name":"张赫","avatar":""},{"name":"He Dujuan","avatar":""},{"name":"Dai Jingyao","avatar":""},{"name":"Fan Jing Yi","avatar":""},{"name":"Wang Yizhe","avatar":""},{"name":"Tao Hai","avatar":""},{"name":"Tian Lei","avatar":""},{"name":"Huang Deyi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Lover Who is a Stranger","Strange Lover","Unfamiliar Lover","Mo Sheng De Lian Ren","Lover or Stranger","Возлюбленный незнакомец","陌生的恋人"]', 1784690324318);
