INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meo-meo-gau-gau-co-yeu-quai', 'Meo Meo Gâu Gâu Có Yêu Quái', 'Cat and Dog', 'https://phimimg.com/upload/vod/20241009-1/5ef29cf9e27e44a6024bcad3ad3faa04.jpg', 'https://phimimg.com/upload/vod/20241009-1/1856b49abc504b7c0214d8164ea1201a.jpg', '<p>Meo Meo Gâu Gâu Có Yêu Quái là bộ phim kể về thế giới nơi con người, yêu quái và thần tiên cùng tồn tại, nhưng các vị thần sống ở đâu? Nó trông như thế nào? không ai biết mà cũng chẳng ai hay. Ngoài thế giới loài người và thế giới yêu quái, có một nơi đặc biệt khác trên thế giới này rất đặc biệt, nơi mà thần không quản, người phàm không đến, và yêu quái thì càng ghét. Đây là nơi câu chuyện của bộ phim Meo Meo Gâu Gâu Có Yêu Quái của chúng ta bắt đầu.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Peihan Wang","avatar":""},{"name":"Zhang Jiaxi","avatar":""},{"name":"He Cao","avatar":""},{"name":"Ma Xier","avatar":""},{"name":"Sun Qiheng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["喵喵汪汪有妖怪","喵喵汪汪","Cat and Dog"]', 1784690324319);
