INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-tinh-yeu-gap-nha-khoa-hoc', 'Khi Tình Yêu Gặp Nhà Khoa Học', 'Fall in Love with a Scientist', 'https://phimimg.com/upload/vod/20241009-1/d0e5748d4dcbb159b611900573cf6dd8.jpg', 'https://phimimg.com/upload/vod/20241009-1/806bf0c69cdf1a221d2a5b0ea5b2a856.jpg', '<p>Khi Tình Yêu Gặp Gỡ Nhà Khoa Học kể về câu chuyện tình yêu qua mạng của Bạch Lăng Lăng (Châu Vũ Đồng Thủ Vai), là nữ sinh của khoa điện khí, trường Đại Học Hạ Môn. Cô yêu chàng trai qua mạng với nickname Mãi Mãi Là Bao Xa cùng avatar đầu trọc vô cùng dễ thương. Thế nhưng cô chưa bao giờ nghĩ rằng người ấy lại chính là Dương Lam Hàng (Lưu Dĩ Hào thủ vai). Anh là con người ngoài lạnh trong nóng, hướng nội, chỉ biết sống trong phòng thí nghiệm. Với tính cách mạnh mẽ, lạc quan, yêu đời của Bạch Lăng Lăng, dần dần từng bước cô đã khiến khối băng tên Dương Lam Hàng dần dần học cách yêu...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"劉以豪","avatar":""},{"name":"周雨彤","avatar":""},{"name":"Dai Jingyao","avatar":""},{"name":"Cao Xiyue","avatar":""},{"name":"Wu Chengxuan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["When Love Meets a Scientist","當愛情遇上科學家","当爱情遇上科学家"]', 1784690324319);
