INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-chong-yakuza-noi-tro-phan-1', 'Ông Chồng Yakuza Nội Trợ (Phần 1)', 'The Way Of The Househusband (Season 1)', 'https://phimimg.com/upload/vod/20241009-1/00b5c93bca2d59917168d56fb4d1f3cf.jpg', 'https://phimimg.com/upload/vod/20241009-1/4504e3b011c384364ff22ccb4bad85b3.jpg', '<p>Gokushufudou – Ông Chồng Nội Trợ. Được biết đến với cái tên “Immortal Tatsu”, yakuza huyền thoại đã đánh bại một băng đảng đối thủ, Tatsu giờ đã có một sự thay đổi nhỏ về nghề nghiệp – như một ông chồng nội trợ! Nhưng ngay cả một người chồng tận tụy tại nhà. Cũng phải đối phó với phần chia sẻ công bằng của mình (bán hàng tại siêu thị). Và dọn dẹp những mớ hỗn độn bẩn thỉu (trong nhà bếp)… (Lưu ý: “Yakuza” là thuật ngữ đề cập đến các nhóm tội phạm. Có tổ chức ở Nhật Bản, tương tự như mafias.)

Bộ manga Gokushufudou: Ông chồng nội trợ lấy bối cảnh thế giới hiện đại của thế kỷ 21. Câu chuyện tập trung vào cuộc sống thường nhật của Tatsu “bất tử”, một tay yakuza huyền thoại từng làm ra những chiến tích không tưởng trong thế giới xã hội đen.Tuy nhiên giờ đây, anh ta đã quy ẩn giang hồ, kết hôn và giờ chỉ tận tụy dành thời gian cho cuộc sống nội trợ tại gia thay cho người vợ của mình. Cũng từ đây, những chuyện dở khóc dở cười xảy ra xung quanh cuộc sống của Tatsu bất tử.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"津田健次郎","avatar":""},{"name":"伊藤静","avatar":""},{"name":"興津和幸","avatar":""},{"name":"細谷佳正","avatar":""},{"name":"田中敦子","avatar":""},{"name":"市道真央","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Anime-极道主夫","Gokushufudou","Gokushufudō","Yakuza w fartuszku. Kodeks perfekcyjnego pana domu","Шлях домогосподаря","The Way of the House Husband","極主夫道"]', 1784690324319);
