INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('con-gai-la-the-do', 'Con Gái Là Thế Đó', 'A Girl Like Me', 'con gái là thế đó a girl like me guan xiaotong 侯明昊 李宗霖 夏楠 zhao shunran an yongchang jiang haomin yang ming na 常鋮 tang qun wu yuheng shao tian wo jiushi zheban nvzi wo jiu shi zhe ban nv zi 나 같은 여자 ข้าก็เป็นสตรีเช่นนี้ i am just this type of girl 我就是这般女子', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-nguoi', 'Kẻ Săn Người', 'Mouse', 'https://phimimg.com/upload/vod/20241005-1/5e8d71f5855b875427997af8e34dfa0c.jpg', 'https://phimimg.com/upload/vod/20241005-1/23102c1e1c659dfdd3adac64511488b9.jpg', '<p>Phim xoay quanh cuộc truy đuổi giữa cảnh sát và tên sát nhân biến thái đang gây rúng động cả nước với sự tham gia diễn xuất của Lee Seung Gi, Lee Hee Joon, Park Joo Hyun, Kyung Soo Jin... Trong Mouse, Lee Seung Gi vào vai Jung Ba Reum, một cảnh sát tân binh xuất chúng, luôn tin vào công lý, ngay thẳng và nhân từ đến mức khó tin. Nhưng toàn bộ cuộc sống của anh nhanh chóng bị đảo lộn khi cuộc truy đuổi kẻ giết người hàng loạt bắt đầu. Bên cạnh Ba Reum là một thám tử Goo Moo Chi (Lee Hee Joon đóng) khó tính, bị chay sần cảm xúc sau bi kịch bố mẹ bị sát hại lúc anh còn bé. Với ý niệm báo thù mạnh mẽ, anh sẵn sàng bất chấp mọi thủ đoạn để bắt được tội phạm. Park Joo Hyun vào vai Oh Bong Yi, một học sinh cấp ba mạnh mẽ, sống cùng bà và sở hữu kỹ năng võ thuật siêu đỉnh.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"이승기","avatar":""},{"name":"이희준","avatar":""},{"name":"박주현","avatar":""},{"name":"권화운","avatar":""},{"name":"경수진","avatar":""},{"name":"우지현","avatar":""},{"name":"조재윤","avatar":""},{"name":"김영재","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Mouse (Ratón)","Mouse","موش","Mauseu","Мышь","พันธุ์นักฆ่า","窺探","마우스"]', 1784690324319);
