INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-san-nguoi', 'Kẻ Săn Người', 'Mouse', 'kẻ săn người mouse 이승기 이희준 박주현 권화운 경수진 우지현 조재윤 김영재 mouse (ratón) mouse موش mauseu мышь พันธุ์นักฆ่า 窺探 마우스', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-muc-ham-mat-2-than-ai-chi-ai', 'Cá Mực Hầm Mật 2: Thân Ái Chí Ái', 'Go Go Squid 2: Dt.Appledog''s Time', 'https://phimimg.com/upload/vod/20241005-1/c2f642c6986569202141e4031665fe5f.jpg', 'https://phimimg.com/upload/vod/20241005-1/0980d4f6f2a4b9df0b64102388519fa5.jpg', '<p>Nội dung bộ phim xoay quanh câu chuyện tình cảm của Ngãi Tình (Lý Nhất Đồng đóng) và Ngô Bạch (Hồ Nhất Thiên đóng). Trong lần gặp mặt Ngãi Tình đầu tiên, mọi người đã vô cùng ngạc nhiên khi thấy Ngô Bạch nói liền 12 câu. Dù lạnh lùng, trầm tính kiệm lời đến đâu nhưng khi đứng trước Ngãi Tình anh trở thành một người hoàn toàn khác. Vì thần tượng Ngãi Tình từ lâu, Ngô Bạch đã nỗ lực không ngừng để gia nhập đội tuyển của Hàn Thương Ngôn, đi theo con đường Esports. Còn Ngãi Tình luôn đồng hành cùng Ngô Bạch trong những cuộc thi chế tạo robot cũng như những giải đấu lớn mang tầm quốc tế. Hai người cùng sát cánh bên nhau vượt qua không ít những khó khăn, trở ngại trên con đường làm tuyển thủ chuyên nghiệp.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"胡一天","avatar":""},{"name":"李一桐","avatar":""},{"name":"王安宇","avatar":""},{"name":"Li Mingde","avatar":""},{"name":"Xu Lexiao","avatar":""},{"name":"龐瀚辰","avatar":""},{"name":"李現","avatar":""},{"name":"Keru Wang","avatar":""},{"name":"Xu Yao","avatar":""},{"name":"Liu Shuai","avatar":""},{"name":"Chai Jun Zhe","avatar":""},{"name":"Huang Xing Yuan","avatar":""},{"name":"徐洋","avatar":""},{"name":"Ji Xiao Fei","avatar":""},{"name":"Yao Bo Lan","avatar":""},{"name":"Shi Yu","avatar":""},{"name":"秦沛","avatar":""},{"name":"Wang Jianing","avatar":""},{"name":"Lu Siyu","avatar":""},{"name":"Wu Ya Heng","avatar":""},{"name":"Dmitriy Shcherbynsky","avatar":""},{"name":"Peng Shi Teng","avatar":""},{"name":"王梓豪","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["密室困游鱼","亲爱的，挚爱的","친애적, 지애적","아적시대니적시대","아적시대, 니적시대: 우리의 빛나는 시간","아적시대 니적시대: 우리의 빛나는 시간","아적시대, 니적시대","아적시대 니적시대","我的時代你的時代","Dt.Appledog''s Time","我的时代，你的时代"]', 1784690324319);
