INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ca-muc-ham-mat-2-than-ai-chi-ai', 'Cá Mực Hầm Mật 2: Thân Ái Chí Ái', 'Go Go Squid 2: Dt.Appledog''s Time', 'cá mực hầm mật 2: thân ái chí ái go go squid 2: dt.appledog''s time 胡一天 李一桐 王安宇 li mingde xu lexiao 龐瀚辰 李現 keru wang xu yao liu shuai chai jun zhe huang xing yuan 徐洋 ji xiao fei yao bo lan shi yu 秦沛 wang jianing lu siyu wu ya heng dmitriy shcherbynsky peng shi teng 王梓豪 密室困游鱼 亲爱的，挚爱的 친애적, 지애적 아적시대니적시대 아적시대, 니적시대: 우리의 빛나는 시간 아적시대 니적시대: 우리의 빛나는 시간 아적시대, 니적시대 아적시대 니적시대 我的時代你的時代 dt.appledog''s time 我的时代，你的时代', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-va-thoi-nien-thieu-cua-toi', 'Tôi Và Thời Niên Thiếu Của Tôi', 'Flourish In Time', 'https://phimimg.com/upload/vod/20241005-1/9357f7b6ca2ea1fc5c9b284b6b850ca8.jpg', 'https://phimimg.com/upload/vod/20241005-1/4571e9692c451fd7858084add0f9d6bb.jpg', '<p>Nội dung kể về câu chuyện tình cảm ngọt ngào ấm áp của cô gái hoạt bát Lục Miểu lương thiện dũng cảm và nam thần học giỏi kiêu ngạo Giang Hạo Nguyệt. Hai người từ &nbsp;thanh mai trúc mã sau trở thành người yêu, cùng bầu bạn, che chở, cùng trưởng thành.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"邓恩熙","avatar":""},{"name":"张凌赫","avatar":""},{"name":"Ren Shihao","avatar":""},{"name":"Tan Yanyan","avatar":""},{"name":"Guo Xinyu","avatar":""},{"name":"楊童舒","avatar":""},{"name":"Zhao Yang","avatar":""},{"name":"Zhang Jiashuo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["谁能凭爱意将月亮私有","Flourish in Time","우리의 청춘시대","เมื่อเธอมีฉัน และฉันมีเธอ","我和我的時光少年","我和我的时光少年"]', 1784690324319);
