INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-troi-do-phan-2', 'Chân Trời Đỏ (Phần 2)', 'Sky Rojo (Season 2)', 'https://phimimg.com/upload/vod/20241005-1/d8bc3f47699ba1a757adda1ef1afc8d5.jpg', 'https://phimimg.com/upload/vod/20241005-1/0f2d7b15f4521e5dc435ec4b581a63bd.jpg', '<p>Khao khát tự do nhưng cũng ham muốn trả thù, Coral, Wendy và Gina tiếp tục đối đầu với những kẻ săn đuổi họ, trong khi những kẻ này bắt đầu trở mặt với nhau.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Verónica Sánchez","avatar":""},{"name":"Miguel Ángel Silvestre","avatar":""},{"name":"Asier Etxeandia","avatar":""},{"name":"Lali Espósito","avatar":""},{"name":"Yany Prado","avatar":""},{"name":"Enric Auquer","avatar":""},{"name":"José Manuel Poga","avatar":""},{"name":"Carmen Santamaría","avatar":""},{"name":"Niko Verona","avatar":""},{"name":"Cecilia Gómez","avatar":""},{"name":"Godeliv Van den Brandt","avatar":""},{"name":"Penélope Guerrero","avatar":""},{"name":"Luisa Vides","avatar":""},{"name":"Iván Yao","avatar":""},{"name":"Luis Zahera","avatar":""},{"name":"Chema Ruiz","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sky Rojo"]', 1784690324319);
