INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('snabba-cash-dong-tien-phi-phap-phan-1', 'Snabba Cash: Đồng Tiền Phi Pháp (Phần 1)', 'Snabba Cash (Season 1)', 'https://phimimg.com/upload/vod/20241005-1/56747edceee015d1c33981920f05c602.jpg', 'https://phimimg.com/upload/vod/20241005-1/166b6ef82ee70cfc377a93b30446a02d.jpg', '<p>Cuộc sống của một nữ doanh nhân đầy tham vọng, một tên cướp quyến rũ và một cậu thiếu niên gặp rắc rối tìm thấy chính mình trong một cuộc tìm kiếm điên cuồng chỉ với một mục tiêu: kiếm tiền. Cuộc sống của một nữ doanh nhân đầy tham vọng, một tên cướp quyến rũ và một cậu thiếu niên gặp rắc rối tìm thấy chính mình trong một cuộc tìm kiếm điên cuồng chỉ với một mục tiêu: kiếm tiền.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 12, 2021, 'Vietsub', 'FHD', 'Thụy Điển', 0, '[{"name":"Evin Ahmad","avatar":""},{"name":"Ali Alarik","avatar":""},{"name":"Dada Fungula Bozela","avatar":""},{"name":"Jozef Wojciechowicz","avatar":""},{"name":"Alexander Abdallah","avatar":""},{"name":"Ayaan Ahmed","avatar":""},{"name":"Olle Sarri","avatar":""},{"name":"Ghazal Khalili","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["不义之财：十年不晚","Dinero fácil","Snabba Cash","เงินโหด"]', 1784690324319);
