INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-nu-nghe-thuong', 'Tiểu Nữ Nghê Thường', 'Ni Chang', 'https://phimimg.com/upload/vod/20241004-1/e8c3c60abfae99b60dedb81763ffea8c.jpg', 'https://phimimg.com/upload/vod/20241004-1/208a64602a3c1b927ced891347a003ae.jpg', '<p>Tiểu Nữ Nghê Thường - Ni Chang kể về con gái của cửa hiệu tơ tằm nổi tiếng Tạ Thị - Tạ Tiểu Nghê (do Lệ Gia Kỳ thủ vai). Cô được thừa kế cơ nghiệp của gia tộc và trở thành nữ thương nhân trong thời kỳ Đại Ninh. Gia đình và sự nghiệp của gia tộc cô bị hủy hoại dưới tay Tô Thị - một kẻ thù cùng trong giới tơ tằm. Tô Thị không từ thủ đoạn tìm cách tiêu diệt cô. May mắn thay Tiểu Nghê sống sót và thề sẽ báo thù và đòi lại công bằng cho gia tộc mình. Cô ở ẩn và gia nhập vào Vân Cẩm gia trang để học nghề nhuộm cũng như trau dồi bản thân. Sau nhiều năm tu luyện, với trí tuệ và sự chăm chỉ cần cù, công sức bao lâu này của cô đã được đền đáp.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Jiaqi","avatar":""},{"name":"畢雯珺","avatar":""},{"name":"Zeng Qi","avatar":""},{"name":"Sun Jia Lu","avatar":""},{"name":"Song Wenzuo","avatar":""},{"name":"Xing En","avatar":""},{"name":"He Zeyuan","avatar":""},{"name":"Li Yuxuan","avatar":""},{"name":"Peng Bo","avatar":""},{"name":"Zhong Ming","avatar":""},{"name":"Li Yixiao","avatar":""},{"name":"Wang Ruolin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Nichang","小女霓裳"]', 1784690324319);
