INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-la-con-gai-me-toi', 'Bố Là Con Gái Mẹ Tôi', 'Family Swap', 'https://phimimg.com/upload/vod/20241004-1/ddab6d12de6e6e2749ed7f69fc146176.jpg', 'https://phimimg.com/upload/vod/20241004-1/2bfb95dcbe5f5c7ec6fc111d7da1858c.jpg', '<p>Trong bữa tiệc mừng sinh nhật cô con gái út, Alain ước có thể thay đổi gia đình hiện tại. Điều ước bỗng linh nghiệm, nhưng lại theo một cách dở khóc dở cười khi linh hồn các thành viên bị hoán đổi.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Franck Dubosc","avatar":""},{"name":"Alexandra Lamy","avatar":""},{"name":"Christiane Millet","avatar":""},{"name":"Rose de Kervenoaël","avatar":""},{"name":"Mathilde Roehrich","avatar":""},{"name":"Nils Othenin-Girard","avatar":""},{"name":"Artus","avatar":""},{"name":"Jackie Berroyer","avatar":""},{"name":"Christophe Canard","avatar":""},{"name":"Michaël Vander-Meiren","avatar":""},{"name":"Philippe Uchan","avatar":""},{"name":"Marc Citti","avatar":""},{"name":"Caroline Charlety","avatar":""},{"name":"Loxiane Lopes","avatar":""},{"name":"Suzanne Gradt de","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Le sens de la famille","Quien es Quien?","או לה לה","變身好家在","Family Swap"]', 1784690324319);
