INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bo-la-con-gai-me-toi', 'Bố Là Con Gái Mẹ Tôi', 'Family Swap', 'bố là con gái mẹ tôi family swap franck dubosc alexandra lamy christiane millet rose de kervenoaël mathilde roehrich nils othenin-girard artus jackie berroyer christophe canard michaël vander-meiren philippe uchan marc citti caroline charlety loxiane lopes suzanne gradt de le sens de la famille quien es quien? או לה לה 變身好家在 family swap', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-gian-luong-than-my-canh', 'Thời Gian Lương Thần Mỹ Cảnh', 'Love Scenery', 'https://phimimg.com/upload/vod/20241004-1/bd76bf36d9bf3fd66d01179035170d3f.jpg', 'https://phimimg.com/upload/vod/20241004-1/b49bd91f97a1175be0d0da3e80df1cf6.jpg', '<p>Bộ phim được cải biên từ tiểu thuyết nên phần nội dung hầu như đã được biết trước với những ai đã xem qua tác phẩm tiểu thuyết này của tác giả Kiều Diêu. Lương Thần (Từ Lộ) là nữ ca sĩ game PUBG, vốn là một cô gái xinh đẹp xuất thần, giọng hát thiên phú và có thực lực nên album ra nhiều vô kể, cũng được rất nhiều người yêu mến. &nbsp;Còn Lục Cảnh (Lâm Nhất) là Streamer với biệt danh Herman là học đệ của Lương Thần. Cả hai quen nhau và nên duyên từ thế giới ảo, tạo nên một cuộc tình ngọt sâu răng. Vốn trước đó Lương Thần đã có bạn trai, nhưng trong một lần livestream đã phát hiện ra việc bạn trai của mình ngoại tình. Hơn nữa cô còn nói rằng cô không gần nam sắc.

Không lâu sau đó mọi người phát hiện ra rằng cô ở cùng Herman, và những nghi vấn được đặt ra vì việc cô không gần nam sắc. Rốt cuộc đây là chuyện gì?</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"徐璐","avatar":""},{"name":"林一","avatar":""},{"name":"Hu Bing","avatar":""},{"name":"Hu Yunhao","avatar":""},{"name":"Danni Chong","avatar":""},{"name":"Jiang Yuwei","avatar":""},{"name":"Wang Cheng","avatar":""},{"name":"Wang Ting","avatar":""},{"name":"Wang Luqing","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Liang chen mei jing hao shi guang","Liangchen meijing hao shíguang","良辰美景好時光","Love Scenery","良辰美景好时光"]', 1784690324319);
