INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dota-dong-mau-rong-1', 'DOTA: Dòng Máu Rồng 1', 'DOTA: Dragon''s Blood 1', 'https://phimimg.com/upload/vod/20241003-1/fff230e41a5d6ea1827b51dc7d815960.jpg', 'https://phimimg.com/upload/vod/20241003-1/2ff8ffc1ce7985d49025756bd5f2c066.jpg', '<p>Một Hiệp sĩ Rồng dũng cảm, đầy mâu thuẫn phải dùng sức mạnh của loài rồng để ngăn cản một ác quỷ chết chóc trong loạt phim kỳ ảo hoành tráng dựa trên trò chơi trực tuyến.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Dota:dragon''s Blood","DOTA ドラゴンの血","Дота: Кровь дракона","ДОТА: Кров дракона","DOTA Dragons Blood","DOTA  Dragon''s Blood","DOTA Dòng Máu Rồng","DOTA: Dragon''s Blood"]', 1784690324319);
