INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-ra-em-rat-yeu-anh', 'Hóa Ra Em Rất Yêu Anh', 'Crush', 'https://phimimg.com/upload/vod/20241004-1/2079617031d238eb3b948d04c4e6bca1.jpg', 'https://phimimg.com/upload/vod/20241004-1/07a622b330257e37847dfa33cfda5e3d.jpg', '<p>Hóa Ra Em Rất Yêu Anh kể về cô sinh viên sắp tốt nghiệp chuyên ngành tâm lý học Tang Vô Yên ôm mộng trở thành phát thanh viên nên đến làm trợ lý ở đài truyền hình, còn thích một người viết lời có bút danh &quot;Nhất Kim&quot;. Tang Vô Yên tình cờ có cơ hội gặp được một anh chàng khiếm thị tên Tô Niệm Khâm và rơi vào tiếng sét ái tình. Sau đó, Tang Vô Yên biết được Tô Niệm Khâm chính là thần tượng Nhất Kim của mình, cô đã hoàn toàn chìm trong bể tình. Tuy nhiên do Tang Vô Yên bỏ lỡ lần gặp mặt cuối cùng với cha mình nên tình yêu của hai người tan tành. Ba năm sau, Tang Vô Yên trở thành phát thanh viên, Tô Niệm Khâm đã khôi phục thị lực và tiếp nhận việc kinh doanh của gia đình mình. Trên con đường đời khác nhau, họ gặp lại đối phương lần nữa và về bên nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lin Yanjun","avatar":""},{"name":"萬鵬","avatar":""},{"name":"Li Jiahao","avatar":""},{"name":"Zhao Xin","avatar":""},{"name":"王策","avatar":""},{"name":"吳昊澤","avatar":""},{"name":"Jiaqi Li","avatar":""},{"name":"Cong Shang","avatar":""},{"name":"Niu Yukun","avatar":""},{"name":"Zeng Yixuan","avatar":""},{"name":"Ma Li","avatar":""},{"name":"Cai Gang","avatar":""},{"name":"Lin Zheyu","avatar":""},{"name":"Shao Haofan","avatar":""},{"name":"Mei Yichen","avatar":""},{"name":"Zhou Shiyuan","avatar":""},{"name":"Jiang Xinqi","avatar":""},{"name":"Shang Si Qi","avatar":""},{"name":"Du Fan Xin Zhi","avatar":""},{"name":"Xiao Wei","avatar":""},{"name":"Kou Yun Hao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["衾何以堪","原来我很爱你"]', 1784690324319);
