INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luong-bat-nghi', 'Lưỡng Bất Nghi', 'No Doubt in Us', 'https://phimimg.com/upload/vod/20241004-1/0b6ddd7ae0f3f4e6b63f7d7d97db6e9b.jpg', 'https://phimimg.com/upload/vod/20241004-1/95abd7ad8825a400bb5baf5fa537e0f2.jpg', '<p>Lưỡng Bất Nghi kể về hoàng hậu xuất thân nhà quan võ, không giỏi cầm kỳ thi hoạ nhưng binh võ lại không thua ai. Nàng bước vào hoàng cung bị vua lạnh nhạt nhiều năm, chịu đủ loại uất ức. Nhưng đến một ngày, tai nạn nhỏ xảy ra, nàng phát hiện... Mình bị đổi thân thể với Hoàng thượng rồi!!! Sau khi đổi thân thể, hoàng hậu giúp hoàng thượng thượng triều, xuất binh đánh trận. Hoàng thượng giúp nàng quản lý hậu cung, mọi hiểu lầm dần được xoá bỏ. Đế hậu thân mật hơn xưa.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"徐佳琦","avatar":""},{"name":"張傑","avatar":""},{"name":"Su Shangqing","avatar":""},{"name":"李詩萌","avatar":""},{"name":"金弦","avatar":""},{"name":"Qian Chen","avatar":""},{"name":"杨天翔","avatar":""},{"name":"Guo Haoran","avatar":""},{"name":"劉琮","avatar":""},{"name":"Yitong Zhao","avatar":""},{"name":"Sun Lulu","avatar":""},{"name":"谷江山","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Liang Bu Yi","No Doubt In Us","两不疑"]', 1784690324319);
