INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-phong-thuyet-am-muu-phan-1', 'Văn Phòng Thuyết âm Mưu (Phần 1)', 'Inside Job (Season 1)', 'https://phimimg.com/upload/vod/20241003-1/38404d977d7c3ced7ac8a1af713f282f.jpg', 'https://phimimg.com/upload/vod/20241003-1/d8b0218e43dd5f9a99a4e25215c6a53f.jpg', '<p>Người thằn lằn? Thật. Đặt chân lên mặt trăng? Giả. Quản lý âm mưu của thế giới là công việc toàn thời gian đối với một thiên tài vụng về và các đồng nghiệp lập dị.</p>', 'Hoàn Tất (10/10)', 18, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lizzy Caplan","avatar":""},{"name":"Clark Duke","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Brett Gelman","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Tisha Campbell","avatar":""},{"name":"Bobby Lee","avatar":""},{"name":"Andy Daly","avatar":""},{"name":"Chris Diamantopoulos","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["مكتب تنسيق المؤامرات","Departamento de Conspirações","阴谋办公室","阴谋职场","Trabajo incógnito","Piklírna","Zavjere su naš posao","Konspirációs korporáció","陰謀論のオシゴト","은밀한 회사원","Korporacja Konspiracja","บริษัทรับจ้างป่วน","陰謀辦公室","Корпорація змов","Văn Phòng Thuyết Âm Mưu","Inside Job"]', 1784690324319);
