INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-cau-day-lop-truong', 'Xin Cậu Đấy Lớp Trưởng', 'Please Classmate', 'https://phimimg.com/upload/vod/20241003-1/4e56263b1a00655ae7eeed2e4eefbb03.jpg', 'https://phimimg.com/upload/vod/20241003-1/c015e1512d8afda42b5fb6c0e89dd186.jpg', '<p>Câu chuyện kể về hai nhóm thanh niên vốn có mâu thuẫn với nhau. Hỗn loạn nảy sinh khi thủ lĩnh phe phương Bắc và thủ lĩnh phe phương nam trở thành bạn học trong cùng một lớp.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hạ Chi Quang","avatar":""},{"name":"Đại Lộ Oa","avatar":""},{"name":"Yên Hủ Gia","avatar":""},{"name":"Chu Dực Nhiên","avatar":""},{"name":"Tư Ngoại Qua","avatar":""},{"name":"Vương Nghệ Điềm","avatar":""},{"name":"Chung Dịch Hiên","avatar":""},{"name":"Khưu Hồng Khải","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Please Class Mate","부탁해요, 반장","拜托了班长"]', 1784690324319);
