INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-ho-ngay-cua-me', 'Hẹn Hò Ngày Của Mẹ', 'Mothering Sunday', 'https://phimimg.com/upload/vod/20241003-1/a7ab35a1bdff1253be9ab071a67600d2.jpg', 'https://phimimg.com/upload/vod/20241003-1/44243db0d742da51cf74f7dd23a506d1.jpg', '<p>Vào một ngày mùa xuân ấm áp năm 1924, người giúp việc nhà và cũng là đứa trẻ sơ sinh Jane Fairchild thấy mình cô đơn trong Ngày của Mẹ. Ông chủ của cô, ông bà Niven, đang đi vắng và cô có cơ hội hiếm có để dành thời gian quý giá với người tình bí mật của mình. Paul là chàng trai đến từ trang viên gần đó, tình yêu lâu dài của Jane mặc dù anh đã đính hôn và kết hôn với một người phụ nữ khác, một người bạn thời thơ ấu và là con gái của bạn của bố mẹ anh. Nhưng những sự kiện không thể đoán trước sẽ thay đổi cuộc đời Jane mãi mãi.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Odessa Young","avatar":""},{"name":"Josh O''Connor","avatar":""},{"name":"Sope Dirisu","avatar":""},{"name":"Patsy Ferran","avatar":""},{"name":"Emma D''Arcy","avatar":""},{"name":"Glenda Jackson","avatar":""},{"name":"Olivia Colman","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Nathan Reeve","avatar":""},{"name":"Samuel Barlow","avatar":""},{"name":"Dexter Raggatt","avatar":""},{"name":"Charlie Oscar","avatar":""},{"name":"Simon Shepherd","avatar":""},{"name":"Caroline Harker","avatar":""},{"name":"Craig Crosbie","avatar":""},{"name":"Emily Woof","avatar":""},{"name":"Scaredy Kat","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Mātes svētdiena","Primavera en Beechwood","Amores Prohibidos","Helligdag","母亲节幽会","יום האם","Mothering Sunday"]', 1784690324319);
