INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-den', 'Hố Đen', 'Dark Hole', 'https://phimimg.com/upload/vod/20241001-1/c447251879348973ec1d6fb9212d4f9f.jpg', 'https://phimimg.com/upload/vod/20241001-1/e65e7f5d93e3c4533569f9af8bab5422.jpg', '<p>Phim xoay quanh Lee Hwa Sun bắt đầu từ lúc cô nhận được cuộc điện thoại từ kẻ đã sát hại chồng cô và dụ dỗ cô đến Mujishi - nơi mà rất nhiều người đã hóa thành zombie sau khi hít phải làn khói đen không rõ đến từ đâu. Giờ đây, cô phải chiến đấu để bảo toàn mạng sống cũng như để săn lùng kẻ đã ám hại chồng mình. Đồng hành cùng cô là Yoo Tae Han - một &quot;thổ địa&quot; tại Mujishi một lòng hướng về chính nghĩa. Hành trình đấu tranh chống lại zombie, cứu sống mọi người của cả hai sẽ thế nào đây?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"김옥빈","avatar":""},{"name":"이준혁","avatar":""},{"name":"Yoon Jung-hoon","avatar":""},{"name":"박근록","avatar":""},{"name":"Jang Sung-won","avatar":""},{"name":"Lee Ha-eun","avatar":""},{"name":"김병기","avatar":""},{"name":"오유진","avatar":""},{"name":"Song Sang-eun","avatar":""},{"name":"Lee Ye-bit","avatar":""},{"name":"Bae Jung-hwa","avatar":""},{"name":"임원희","avatar":""},{"name":"Zo Zee-an","avatar":""},{"name":"김도훈","avatar":""},{"name":"Kim Su-ol","avatar":""},{"name":"Heo Hyung-kyu","avatar":""},{"name":"Jang Myung-kap","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931