INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-tong-cung-tu', 'Đại Tống Cung Từ', 'Palace of Devotion', 'https://phimimg.com/upload/vod/20241001-1/170b28d5cbcb4fc455364d479df8679a.jpg', 'https://phimimg.com/upload/vod/20241001-1/94b44bc991fe56dfdb65ec35a7798b5f.jpg', '<p>Đại Tống Cung Từ kể về Kim Quỹ Chi Minh thời Triệu Khuông Dẫn để lại, gây nên cuộc chiến tranh giành ngôi báu trong triều đình nhà Tống. Lưu Nga (do Lưu Đào thủ vai) vốn là cô gái mồ côi đất Thục, trong lúc chiến loạn gặp gỡ và nảy sinh tình cảm với tam hoàng tử Triệu Hằng (do Châu Du Dân thủ vai). Hai người trải qua muôn vàn khó khăn trắc trở, cuối cùng khổ tận cam lai. Về sau, Triệu Hằng băng hà lúc vua Nhân Tông trẻ dại, để hoàn thành di nguyện của tiên đế, Lưu Nga buông rèm nhiếp chính, chủ trì sự vụ trong triều, nhờ đó kết thúc đấu tranh đảng phái, tu bổ, xây dựng công trình thủy lợi, tạo ra nhiều phúc lợi, giải quyết ổn thỏa những phân tranh và bất an của các dân tộc xung quanh, đồng thời mạnh dạn trọng dụng những nhân tài kiểu mới như Phạm Trọng Yêm, Yến Thù, Tô Tuân, gầy dựng một cơ sở vững chắc cho bốn mươi năm &quot;Nhân Tông thịnh trị&quot; sau này.</p>', 'Hoàn Tất (61/61)', 61, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Tao","avatar":""},{"name":"周渝民","avatar":""},{"name":"Lin Xi","avatar":""},{"name":"Cao Lei","avatar":""},{"name":"齐溪","avatar":""},{"name":"Liang Guanhua","avatar":""},{"name":"Li Jia Xin","avatar":""},{"name":"房子斌","avatar":""},{"name":"Zheng Wei","avatar":""},{"name":"Pan Yiyi","avatar":""},{"name":"Liu Cong","avatar":""},{"name":"Wang Xin","avatar":""},{"name":"Wu Mouchou","avatar":""},{"name":"Li Yanming","avatar":""},{"name":"Xiao Yang","avatar":""},{"name":"陈政阳","avatar":""},{"name":"Wei Daming","avatar":""},{"name":"Li Haobin","avatar":""},{"name":"Gong Jinguo","avatar":""},{"name":"Wang Heming","avatar":""},{"name":"Zhou Xuefei","avatar":""},{"name":"Feier Han","avatar":""},{"name":"Han Yuanqi","avatar":""},{"name":"Yu Yao","avatar":""},{"name":"Fu Heng","avatar":""},{"name":"钱冬旎","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["大宋宫词","Palace of Devotion"]', 1784690324319);
