INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-cung-co-binh-thuong-dau', 'Em cũng có bình thường đâu', 'You''re Not Normal, Either!', 'https://phimimg.com/upload/vod/20241001-1/9105d130327df13609bc3b10d6ec4ac8.jpg', 'https://phimimg.com/upload/vod/20241001-1/d202e41f623d16717adc9eaca27c185a.jpg', '<p>Ono Yasuomi là một giáo viên dạy toán độc thân tại một trường luyện thi. Tuy anh không thấy có gì bất ổn trong cuộc sống hiện tại của mình nhưng khi nghe cô học trò Akimoto Kasumi nói rằng anh không bình thường và điều đó sẽ khiến anh phải sống cô đơn suốt quãng đời còn lại thì anh bỗng cảm thấy lo sợ. Anh nhờ Kasumi chỉ cho anh cách để trở nên bình thường và cô bắt đầu dẫn anh đi tán gái…</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"成田凌","avatar":""},{"name":"清原果耶","avatar":""},{"name":"泉里香","avatar":""},{"name":"小泉孝太郎","avatar":""},{"name":"山谷花純","avatar":""},{"name":"倉悠貴","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Matomo Janai no wa Kimi mo Issho","你和我一样不正常","Mato mo janai no wa kimi mo issho","まともじゃないのは君も一緒"]', 1784690324319);
