INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-phan-ac-ma', 'Thẩm Phán Ác Ma', 'The Devil Judge', 'https://phimimg.com/upload/vod/20240928-1/2bfadf366d772f7b972502ad253edbe4.jpg', 'https://phimimg.com/upload/vod/20240928-1/5d97b1a4b9d845db9c7f7e97723f7b15.jpg', '<p>Lấy bối cảnh ở một của Hàn Quốc ngày nay, nơi cuộc sống hàng ngày hỗn loạn và xã hội đã sụp đổ đến mức mọi người công khai bày tỏ sự ngờ vực và căm ghét đối với các nhà lãnh đạo của họ. Trong thế giới không có luật pháp và trật tự này, Thẩm phán trưởng Kang đang báo hiệu sự cần thiết phải thay đổi. Phòng xử án của anh ta là chủ đề của một chương trình thực tế, nơi anh ta trừng phạt kẻ có tội một cách không thương tiếc, khiến anh ta có biệt danh là &quot;Thẩm Phán Ác Ma &quot;. &nbsp;Là một nhân vật gây chia rẽ với hào quang bí ẩn luôn tin vào danh tính và tham vọng thực sự của anh ta, công chúng không chắc anh ta là anh hùng thực sự hay ai đó, cố ý gieo mầm bất mãn trong phòng xử án của anh ta.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"지성","avatar":""},{"name":"김민정","avatar":""},{"name":"진영","avatar":""},{"name":"박규영","avatar":""},{"name":"장영남","avatar":""},{"name":"김재경","avatar":""},{"name":"안내상","avatar":""},{"name":"Chun Young-min","avatar":""},{"name":"Jeon Chae-eun","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["عدالة الشيطان","恶魔法官","El juez del diablo (The Devil Judge)","あくまはんじ","Akmapansa","The Devil Judge","قاضي الشيطان","Devilish Judge","The Demon Judge","The Devil Judgement","The Devil''s Justice","악마판사"]', 1784