INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-phan-ac-ma', 'Thẩm Phán Ác Ma', 'The Devil Judge', 'thẩm phán ác ma the devil judge 지성 김민정 진영 박규영 장영남 김재경 안내상 chun young-min jeon chae-eun عدالة الشيطان 恶魔法官 el juez del diablo (the devil judge) あくまはんじ akmapansa the devil judge قاضي الشيطان devilish judge the demon judge the devil judgement the devil''s justice 악마판사', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-trong-phim-ban-lang-man', 'Tình Yêu Trong Phim: Bản Lãng Mạn', 'The Romance The Series', 'https://phimimg.com/upload/vod/20240928-1/283a806655c81d188e29ff2d5561d573.jpg', 'https://phimimg.com/upload/vod/20240928-1/93f1be8d1e73983eff59612072169f3a.jpg', '<p>Đây là một kịch bản do 2 nhóm ngôi sao cùng xây dựng. “Đến Với Thế Giới Anh Ấy Thử Xem” kể về sự gặp gỡ kỳ diệu giữa thần tượng ảo Rainbow (Ngô Tuyên Nghi thủ vai) và nhà sản xuất nhạc Tiểu Khải (Tiểu Quỷ Vương Lâm Khải thủ vai). Là một thần tượng, Rainbow cần chịu trách nhiệm với fan và Tiểu Khải không bằng lòng mất tự do sản xuất nhạc. Đối mặt với tình yêu và hiện thực, hai người sẽ lựa chọn thế nào? “Chúng Ta Yêu Nhau Nào” kể về tác giả chán nản Hứa Đắc Chí (Hứa Ngụy Châu thủ vai). Một hôm, tự dưng xuất hiện một người nàng thần bí Kiều Đóa Đóa (Kiều Hân thủ vai), Hứa Đắc Chí bị bắt cùng sống với nàng. Tình cảm của cặp oan gia này dần dần thay đổi trong cuộc sống gà bay chó chạy.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wu Xuanyi","avatar":""},{"name":"許魏洲","avatar":""},{"name":"喬欣","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["恋恋剧中人 剧情版"]', 1784690324319);
