INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-tuan-hoan', 'Tình Yêu Tuần Hoàn', 'First Love Again', 'https://phimimg.com/upload/vod/20240928-1/8f5f05906919e4fb1f099c4a98bbe1de.jpg', 'https://phimimg.com/upload/vod/20240928-1/18bc89f474e6e9fc0271d67cb4fc7b2e.jpg', '<p>Tình Yêu Tuần Hoàn-Ở không gian song song, học bá lạnh lùng Diệp Hựu Ninh (Thi Bách Vũ đóng) và &quot;cô gái hướng dương&quot; Hạ Văn Hy (Trần Hạo Vũ đóng) đã có một cuộc gặp gỡ kỳ lạ ngọt ngào. Hai người gặp nhau dưới xác suất là 1/1 tỷ, bắt đầu lại cuộc sống trung học, gặp lại bạn bè thời thanh xuân, bắt đầu lại mối tình đầu ngây ngô. Cuộc đối thoại xuyên qua thời không này phủ lên một tầng sắc màu kỳ diệu lên khoảng thời gian thiếu niên tươi đẹp.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"施柏宇","avatar":""},{"name":"陳昊宇","avatar":""},{"name":"Gao Maotong","avatar":""},{"name":"Gao Qiuzi","avatar":""},{"name":"Yang Gen","avatar":""},{"name":"Xu Wanting","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["First Love Again","循环初恋"]', 1784690324319);
