INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyen-vong-tri-mang', 'Nguyện Vọng Trí Mạng', 'Wisher', 'https://phimimg.com/upload/vod/20240928-1/788b78ea174dbd5af9cd0caee934f6ba.jpg', 'https://phimimg.com/upload/vod/20240928-1/b773e0cde6d01f3a9963ddf17cc56d69.jpg', '<p>Khởi điểm và công tắc của tất cả mọi thứ đều là một phần mềm gọi tên là Wisher. Wisher đột nhiên tự động được cài đặt vào điện thoại di động của một đám sinh viên. Sau cầu nguyện với nó, chỉ cần hoàn thành nhiệm vụ giản đơn được nó đưa cho, thì nguyện vọng sẽ được thực hiện. Những người thanh niên này bị mê hoặc, hình như giao ước với ma quỷ, trở thành thẻ domino bị dục vọng khống chế. Người phóng viên trung niên Na Đa và những người thanh niên như Lộ Lí, Cầu Văn Đông, v.v... bắt đầu chống lại thế lực đằng sau Wisher.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"冯绍峰","avatar":""},{"name":"文淇","avatar":""},{"name":"范丞丞","avatar":""},{"name":"郭子凡","avatar":""},{"name":"Yang Rong","avatar":""},{"name":"邵兵","avatar":""},{"name":"Wang Zhen","avatar":""},{"name":"Hu Wei","avatar":""},{"name":"Cao Wanjin","avatar":""},{"name":"Shuang Wu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["喂食者协会","致命願望","Fatal Wish","致命愿望"]', 1784690324319);
