INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-vuc-nguy-hiem', 'Khu Vực Nguy Hiểm', 'Danger Zone', 'https://phimimg.com/upload/vod/20240928-1/521376d79b81d7c349143fb92a3ae262.jpg', 'https://phimimg.com/upload/vod/20240928-1/d037f5583150844d4275c8ea96eb0f56.jpg', '<p>Khu Vực Nguy Hiểm kể về thủ pháp phạm tội không có kẽ hở, vụ án giết người liên hoàn không tìm được hung thủ…! Liên tiếp những vụ án kỳ bí xảy ra buộc cảnh sát và tội phạm không thể không bắt tay hợp tác, thâm nhập vào hiện trường án mạng, cùng vật lộn đọ sức, tìm lại chính nghĩa cho người chết. Cuộc chiến với song hùng hợp tác xuất kích, lại làm cho cuộc giao dịch mao quỷ này nổi sóng ngầm dữ dội, dẫn tới hàng loạt nguy cơ chí mạng khác to lớn hơn!</p>', 'Hoàn Tất (24/24) + Tập ĐB', 24, 'series', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Teresa Daley","avatar":""},{"name":"周渝民","avatar":""},{"name":"Berant Zhu","avatar":""},{"name":"張榕容","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["逆局","追凶者","Danger Zone"]', 1784690324319);
