INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khu-vuc-nguy-hiem', 'Khu Vực Nguy Hiểm', 'Danger Zone', 'khu vực nguy hiểm danger zone teresa daley 周渝民 berant zhu 張榕容 逆局 追凶者 danger zone', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-phan-nghich', 'Kẻ Phản Nghịch', 'The Rebel', 'https://phimimg.com/upload/vod/20240928-1/5bad936da2fd7e1c29e589ecbafabd9f.jpg', 'https://phimimg.com/upload/vod/20240928-1/3e17c23c255cf11f0a3675e2c0539a33.jpg', '<p>Năm 1936, học viên lớp đào tạo cán bộ Hội Phục Hưng Lâm Nam Sênh bị đưa đến Thượng Hải tham gia hoạt động bắt giữ các thành viên thuộc Đảng bí mật. Trong quá trình thực hiện, Lâm Nam Sênh bị tinh thần hy sinh cũng như sứ mệnh của những người Đảng Cộng sản làm cho dao động. Lâm Nam Sênh dũng cảm quyết đoán, nhiều lần lập công trong quá trình kháng chiến chống Nhật. Nhiều lần đứng về phía Đảng Cộng sản, lợi dụng thân phận đặc biệt của mình trong quân đội giúp đỡ vô cùng lớn cho Đảng bí mật. Sau khí kháng chiến thắng lợi, Lâm Nam Sênh trở thành một Đảng viên chân chính, đồng thời vào thời khắc quyết định giải phóng, đã cống hiến rất nhiều cho đất nước và Đảng Cộng sản.</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"朱一龍","avatar":""},{"name":"童瑤","avatar":""},{"name":"Zhiwen Wang","avatar":""},{"name":"王阳","avatar":""},{"name":"朱珠","avatar":""},{"name":"李强","avatar":""},{"name":"張子賢","avatar":""},{"name":"Yao Anlian","avatar":""},{"name":"袁文康","avatar":""},{"name":"代旭","avatar":""},{"name":"Shi Wenzhong","avatar":""},{"name":"Lu Senbao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["The Rebel","Rthk31 the Rebel","The Rebel Betrayer","叛逆者"]', 1784690324319);
