INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-phan-nghich', 'Kẻ Phản Nghịch', 'The Rebel', 'kẻ phản nghịch the rebel 朱一龍 童瑤 zhiwen wang 王阳 朱珠 李强 張子賢 yao anlian 袁文康 代旭 shi wenzhong lu senbao the rebel rthk31 the rebel the rebel betrayer 叛逆者', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-mat-trang-thanh-hoa-dua-no', 'Gió Mát Trăng Thanh Hoa Đua Nở', 'The Flowers Are Blooming', 'https://phimimg.com/upload/vod/20240928-1/68d19bc8b2d7c4e9c4f8866853a54466.jpg', 'https://phimimg.com/upload/vod/20240928-1/5c7cfdbc75719cd7e2117cddce8a455b.jpg', '<p>Bô phim “Gió Mát Trăng Thanh Hoa Đua Nở”(2021) kể về câu chuyện trưởng thành của các nhân vật chính. Sau công chúa Đại Tiêu Trần Lãng Nguyệt (Hứa Giai Kỳ thủ vai) trốn ra cung để theo đuổi ước mơ kiến trúc, nàng gặp gỡ người thợ thiên tài Lý Thanh Phong (Hoàng Thánh Trì thủ vai) và hai người cùng theo đuổi ước mơ, thực hiện giá trị chính mình. Là công chúa Đại Tiêu, nữ chính Trần Lãng Nguyệt học rộng tài cao, tinh thông cầm kỳ thi họa từ nhỏ, lại có một ước mơ đủ lớn về kiến trúc. Nam chính Lý Thanh Phong sinh ra trong một dòng dõi quý tộc, là một kiến trúc sư thiên tài nổi tiếng. Chàng cùng bạn La Duệ sáng lập đội thợ Mộc Vũ. Tám người thiếu niên, người thiếu nữ Đại Tiêu tính cách khác hẳn, lại tụ tập vào đội thợ Mộc Vũ do ước mơ riêng mình. Họ cùng cải tạo nhiều kiến trúc kỳ lạ, thú vị, từ thanh lâu đến nhà quỷ, từ tòa nhà đến cầu cống, từ tổ nhỏ ấm áp đến lạc viên tình yêu, từ vườn đất dân gian đến tháp Phong Tương triều đình, cuối cùng họ còn cải tạo công sự bảo vệ cho quốc gia... Họ có khi cãi nhau đến mức gà bay chó chạy, có khi lại giúp đỡ và sưởi ấm lẫn nhau. Trong khi cải tạo kiến trúc, mỗi một người còn được cõi đi về riêng mình và được trưởng thành nhiều. “Gió Mát Trăng Thanh Hoa Đua Nở” được Hứa Giai Kỳ(cựu thành viên nhóm SNH48 và THE9, từng tham gia “Thanh Xuân Có Bạn Mùa 2”, “Như Ý Phương Phi”) và Hoàng Thánh Trì (từng diễn xuất “Thiếu Nữ Toàn Phong Phần 2”, “Bong Bóng Mùa Hè”, “Truy Cầu”) cùng thủ vai chính.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xu Jia Qi","avatar":""},{"name":"黃聖池","avatar":""},{"name":"Wu Yang","avatar":""},{"name":"Song Hanyu","avatar":""},{"name":"Ma Zhenhuan","avatar":""},{"name":"Fu Yaning","avatar":""},{"name":"Jiahui Li","avatar":""},{"name":"Zhang Zhuowen","avatar":""},{"name":"Jiuyi Zhao","avatar":""},{"name":"Wang Yuxuan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["The Flowers Are Bloomimg","청풍랑월화정개","清风朗月花正开"]', 1784690324319);
