INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-ho-sinh-hoc-tinh-yeu', 'Đồng Hồ Sinh Học Tình Yêu', 'Love O''Clock', 'https://phimimg.com/upload/vod/20240928-1/8e048f99a62a0e9ee426c9af421875cc.jpg', 'https://phimimg.com/upload/vod/20240928-1/4d9144419d9861f942f34b770665e9a7.jpg', '<p>Đồng hồ sinh học tình yêu kể về tác giả Hòa Chân - người muốn ký hợp đồng với Văn hóa Dữ Thư, cô dùng chiếc đồng hồ cổ để lấy lòng tổng biên tập Lục Quân Chi, một người sinh hoạt có quy tắc. Khi &quot;tặng đồng hồ&quot;, sức mạnh bí ẩn của chiếc đồng hồ bất ngờ bị đánh thức, hai người buộc phải đổi đồng hồ sinh hoạt cho nhau và bắt đầu chung sống. Trong thời gian ở chung, hai người gỡ bỏ hiểu lầm và giúp đỡ lẫn nhau. Nhờ sự giúp đỡ của Lục Quân Chi và bạn bè, Hòa Chân bắt đầu con đường tác giả của mình, mà nhờ có Hòa Chân ở bên, Lục Quân Chi cũng hòa giải với bản thân trong quá khứ. Cuối cùng, hai người gặt hái được sự nghiệp mà mình yêu thích cùng một tình yêu ngọt ngào.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Chengxuan","avatar":""},{"name":"Peng Chuyue","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["恋爱生物钟"]', 1784690324319);
