INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dep-nhat-la-khi-gap-em', 'Đẹp Nhất Là Khi Gặp Em', 'Nice to Meet You', 'https://phimimg.com/upload/vod/20240928-1/276033676002e7d8e7d135c49fb5dc80.jpg', 'https://phimimg.com/upload/vod/20240928-1/7fdf01a9aaf1d1ea4f8acde9a91988ac.jpg', '<p>Bộ phim thanh xuân vườn trường Trung Quốc kể về nữ sinh Hạ An Sênh có một bí mật mà cô không muốn ai biết sau khi chuyển đến trường Thần Quang, tại đây cô làm bạn với hai cậu nam sinh điển trai. Một trong số đó là con trai của dì nhỏ, người dì căm ghét An Sênh một cách kỳ lạ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 16, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Fu Weilun","avatar":""},{"name":"Muyi Han","avatar":""},{"name":"Peng Chuyue","avatar":""},{"name":"Xu Kaixin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["The most beautiful but I met you","Zui Mei Bu Guo Yu Jian Ni","Nice To Meet You","最美不过遇见你"]', 1784690324319);
