INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dep-nhat-la-khi-gap-em', 'Đẹp Nhất Là Khi Gặp Em', 'Nice to Meet You', 'đẹp nhất là khi gặp em nice to meet you fu weilun muyi han peng chuyue xu kaixin the most beautiful but i met you zui mei bu guo yu jian ni nice to meet you 最美不过遇见你', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-co-tich-cua-co-gai-thoi-taisho', 'Chuyện Cổ Tích Của Cô Gái Thời Taisho', 'Taisho Otome Fairy Tale', 'https://phimimg.com/upload/vod/20240928-1/34fd8d3d5181b3d13f126bde8789881c.jpg', 'https://phimimg.com/upload/vod/20240928-1/5f2ef54ad99e3509292e7b9c67472b79.jpg', '<p>Năm thứ 11 Đại Chính của Nhật Bản (năm 1922), Tamahiko, người con trai thứ 2 của gia tộc Shima, bị tai nạn xe hơi mà mất người mẹ và một tay mình. Do vậy chàng ấy bị gia tộc đối xử lạnh nhạt, bị vứt bỏ mà ở ẩn trong biệt thự tại núi thẳm. Lúc này, Yoizuki, người thiếu nữ ngây thơ nhanh nhẹn xuất hiện trước mặt Tamahiko nản lòng. Nàng ấy chính là đầy tớ theo sát bên cạnh và vợ chưa cưới của Tamahiko. Quý công tử chán nản gặp gỡ người thiếu nữ ngây thơ, hai người sẽ trình diễn một câu chuyện ấm áp như thế nào?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"小林裕介","avatar":""},{"name":"会沢紗弥","avatar":""},{"name":"宮本侑芽","avatar":""},{"name":"安済知佳","avatar":""},{"name":"伊藤彩沙","avatar":""},{"name":"土岐隼一","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["大正处女御伽话","Taishō Otome Otogi Banashi","Taishou Otome Otogi Banashi","大正処女御伽話","Taisho Maiden Fairytale","大正オトメ御伽話"]', 1784690324319);
