INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-co-tich-cua-co-gai-thoi-taisho', 'Chuyện Cổ Tích Của Cô Gái Thời Taisho', 'Taisho Otome Fairy Tale', 'chuyện cổ tích của cô gái thời taisho taisho otome fairy tale 小林裕介 会沢紗弥 宮本侑芽 安済知佳 伊藤彩沙 土岐隼一 大正处女御伽话 taishō otome otogi banashi taishou otome otogi banashi 大正処女御伽話 taisho maiden fairytale 大正オトメ御伽話', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-hoi-thu-hai-2021', 'Cơ Hội Thứ Hai', 'Second Chance The Series', 'https://phimimg.com/upload/vod/20240928-1/a22b549201a5ec30a36bc8ec0c2a44a1.jpg', 'https://phimimg.com/upload/vod/20240928-1/7fec490ca04f0217b71ae0ed9c253d7e.jpg', '<p>Trong cuộc sống không ai là chưa từng trải nỗi đau. Tongfah gần đây đã mất cha, và những người đã giúp anh vượt qua mọi khó khăn, ngoài mẹ cô còn có người bạn thân nhất của anh là Paper. Hai người họ luôn giúp đỡ lẫn nhau, cho đến một ngày, mối quan hệ giữa hai người bắt đầu phát triển thành &quot;Hơn thế này&quot;, điều này buộc họ phải đưa ra quyết định về mối quan hệ của mình. Jeno, người đã bị tổn thương bởi người mình yêu, không còn tin tưởng vào tình yêu cho đến khi anh gặp Chris, người đã cố gắng rất nhiều để khiến Jeno mở lòng mình một lần nữa. Mọi thứ ở trường trung học này đều trở nên hỗn loạn, mọi thứ đều thất bại ngay từ lần đầu tiên, cố gắng làm tốt. Để đạt được điều mình muốn, ai cũng chờ đợi cơ hội thứ hai, ai cũng sẽ thử cơ hội để yêu lần nữa.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Fluke Chinnathan Rojrawee Thanakun","avatar":""},{"name":"ธนายุทธ ฐากูรอรรถยา","avatar":""},{"name":"Mawin Tanawin Duangnate","avatar":""},{"name":"Run Kantheephop Sirorattanaphanit","avatar":""},{"name":"Games Nanthipat Srrttnphnt","avatar":""},{"name":"Nine Theepop Phanitprasert","avatar":""},{"name":"Nice Pitayut Orsuwan","avatar":""},{"name":"Minty Chuthikan Chawasathienphong","avatar":""},{"name":"Pangpond Potchana Lertcha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["จังหวะจะรัก"]', 1784690324319);
