INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-tay-cua-me-chong', 'Vòng Tay Của Mẹ Chồng', 'The Priceless', 'https://phimimg.com/upload/vod/20240928-1/939ccb232e9b0353bf081e0579bda897.jpg', 'https://phimimg.com/upload/vod/20240928-1/3d8756d4dbc6ca8fdf472c551c78534a.jpg', '<p>Vòng Tay Của Mẹ Chồng xoay quanh câu chuyện về cô nàng 9X Lưu Nhân bước vào giai đoạn hôn nhân cùng chàng trai Thượng Hải Thạch Lỗi. Trong ngày diễn ra lễ cưới trọng đại, cô được mẹ chồng trao tặng một chiếc vòng tay quý giá cũng là bảo vật gia truyền của gia đình chồng. Thế nhưng, sau đó cô nhận ra đây chỉ là một chiếc vòng giả và trở nên vô cùng hoảng loạn khi tưởng rằng đã mất đi chiếc vòng thật sự. Do đó, người mẹ chồng cùng với những thành viên khác đều bị cuốn vào cuộc rắc rối về chiếc vòng gia truyền. Một cuộc chiến gia tộc mà lòng tham và lòng người, đến cùng điều gì sẽ chiến thắng?</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 11, 2021, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"蓝盈莹","avatar":""},{"name":"牛駿峰","avatar":""},{"name":"邬君梅","avatar":""},{"name":"王鶴潤","avatar":""},{"name":"Chen Yating","avatar":""},{"name":"Morning Chang","avatar":""},{"name":"Min Tian","avatar":""},{"name":"Lam Wai","avatar":""},{"name":"Hou Chang-Rong","avatar":""},{"name":"Yang Yuting","avatar":""},{"name":"Jing Yanjun","avatar":""},{"name":"Rayna Wang","avatar":""},{"name":"Yang Kun","avatar":""},{"name":"Eliza Liang","avatar":""},{"name":"Hong Tao","avatar":""},{"name":"Rong Fei","avatar":""},{"name":"Wang Zitong","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["她们的镯子","the Priceless","婆婆的鐲子","婆婆的镯子"]', 1784690324319);
