INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-chong-yakuza-noi-tro-dao-lam-chong-lam-cong-phu', 'Ông chồng yakuza nội trợ: Đạo làm chồng lắm công phu', 'The Ingenuity of the Househusband', 'https://phimimg.com/upload/vod/20240928-1/db452e173912162282869617c8874552.jpg', 'https://phimimg.com/upload/vod/20240928-1/048aad0ceed22b60d9c003ff80f0b879.jpg', '<p>Một anh chàng cứng rắn có năng khiếu nội trợ tỉ mẩn làm việc nhà trong loạt phim hài hước phiên bản người đóng này.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"津田健次郎","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Hausmann goes Genie","El ingenio del amo de casa","Gokushufudou - A találékony háztartásbeli férj","The Ingenuity of the Househusband","L''ingegno dello yakuza casalingo","Gokukufudou","อัจฉริยะพ่อบ้านสุดเก๋า","Đạo Làm Chồng Đảm Lắm Công Phu","極工夫道"]', 1784690324319);
