INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ong-chong-yakuza-noi-tro-dao-lam-chong-lam-cong-phu', 'Ông chồng yakuza nội trợ: Đạo làm chồng lắm công phu', 'The Ingenuity of the Househusband', 'ông chồng yakuza nội trợ: đạo làm chồng lắm công phu the ingenuity of the househusband 津田健次郎 hausmann goes genie el ingenio del amo de casa gokushufudou - a találékony háztartásbeli férj the ingenuity of the househusband l''ingegno dello yakuza casalingo gokukufudou อัจฉริยะพ่อบ้านสุดเก๋า đạo làm chồng đảm lắm công phu 極工夫道', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('li-ca-hanh', 'Li Ca Hành', 'Court Lady', 'https://phimimg.com/upload/vod/20240813-1/ffa3c06462a5d8d50de7a8eac2751f22.jpg', 'https://phimimg.com/upload/vod/20240813-1/692c0288f388efe99d7f2e05bcbeba50.jpg', '<p>Li Ca Hành kể về mối tình khắc cốt ghi tâm của tướng quân Trình Xử Mặc (Hứa Khải thủ vai) và nữ quan Phó Nhu (Lý Nhất Đồng đóng). Phó Nhu là một tiểu thư xinh đẹp, tài giỏi rất am hiểu cầm kỳ thi họa, giỏi thêu thùa và may vá. Mọi chuyện yên lành cho tới khi nàng bị tuyển vào cung để làm người hầu. Tại đây nàng lọt vào tầm mắt của công tử nhà tướng quân chỉ biết ăn chơi lêu lổng. Vì quá yêu Phó Nhu mà Trình Xử Mặc quyết tâm thay đổi bản thân để chiếm trọn tình cảm của nàng. Cả hai tạo nên chuyện tình vừa ngọt ngào, hài hước vừa nhiều thử thách và tất nhiên họ cũng bị cuốn vào những âm mưu mô thủ đoạn, nguy hiểm luôn kề trong cuộc tranh đấu chốn cung đình.</p>', 'Hoàn Tất (55/55)', 55, 'series', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"李一桐","avatar":""},{"name":"許凱","avatar":""},{"name":"李澤鋒","avatar":""},{"name":"吳佳怡","avatar":""},{"name":"檀兮爾","avatar":""},{"name":"何奉天","avatar":""},{"name":"Wang Yizhe","avatar":""},{"name":"Zhang Nan","avatar":""},{"name":"何瑞賢","avatar":""},{"name":"Ma Yue","avatar":""},{"name":"Miao Pu","avatar":""},{"name":"Lin Peng","avatar":""},{"name":"Liu Min","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324319);
