INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-em-den-ngay-mua', 'Chờ Em Đến Ngày Mưa', 'Waiting For Rain', 'https://phimimg.com/upload/vod/20240928-1/b506ccf5d39f91c724d5a54cb6b17d78.jpg', 'https://phimimg.com/upload/vod/20240928-1/142a4603940f212731edda20b7dd41b1.jpg', '<p>Young Ho là một chàng trai cố gắng thi đại học nhưng không đỗ. Từ đó, anh không có mục tiêu sống nào đặc biệt. Một ngày nọ, anh quyết định gửi một lá thư cho người bạn cùng bàn thời tiểu học là So Hee và nhận được lời hồi đáp từ người chị gái cô. Sự kiện này trở thành nguồn an ủi lớn cho anh. Từ đây, mở ra câu chuyện tình lãng mạn, nhẹ nhàng sâu lắng.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kang Ha Neul","avatar":""},{"name":"Chun Woo Hee","avatar":""},{"name":"Kang So Ra","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Waiting For Rain","Rain and Your Story","باران ابدی","داستان تو و باران","در انتظار باران","Endless Rain","Esperando la lluvia","비와 당신의 이야기"]', 1784690324319);
