INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-thi-nghiem-ma', 'Phòng Thí Nghiệm Ma', 'Ghost Lab', 'https://phimimg.com/upload/vod/20240927-1/55056e6c2369f9a64e73184e09167583.jpg', 'https://phimimg.com/upload/vod/20240927-1/aa598d0d133ab912f0af4b16ea0a8cef.jpg', '<p>Sau khi gặp ma trong bệnh viện của họ, hai bác sĩ trở nên ám ảnh một cách nguy hiểm về việc thu thập bằng chứng khoa học để chứng minh sự tồn tại của ma.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"ธนภพ ลีรัตนขจร","avatar":""},{"name":"Paris Intarakomalyasut","avatar":""},{"name":"ณัฏฐณิชา ดังวัธนาวณิชย์","avatar":""},{"name":"สู่ขวัญ บูลกุล","avatar":""},{"name":"Rachanee Siralert","avatar":""},{"name":"Nuttawut Jenmana","avatar":""},{"name":"Chaleeda Gilbert","avatar":""},{"name":"Anchuleeon Buagaew","avatar":""},{"name":"Jinjuta Rattanaburi","avatar":""},{"name":"Alanta Potjes","avatar":""},{"name":"Suniti Supavarahasoonthorn","avatar":""},{"name":"Prem Fakseemuang","avatar":""},{"name":"Ekkhapop Sunwanna","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ghost Lab","โกสต์แล็บฉีกกฎทดลองผี","El Experimento Fantasma","猛鬼实验室","亡灵实验室","鬼魂实验室","โกสต์แล็บ..ฉีกกฎทดลองผี"]', 1784690324319);
