INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-mang-lien-hoan-luc-nua-dem', 'Án Mạng Liên Hoàn Lúc Nửa Đêm', 'Haunted Tales', 'https://phimimg.com/upload/vod/20240928-1/58fde73d92b0de37742603cc98cb9df3.jpg', 'https://phimimg.com/upload/vod/20240928-1/91ba948948dd16fff2b7ce5424481138.jpg', '<p>Ba câu chuyện, ba án mạng bí ẩn được tổng hợp dựa trên những truyền thuyết tâm linh rùng rợn của Thái Lan, bộ phim kinh dị dù không có những thế lực siêu nhiên &quot;đao to búa lớn&quot; nhưng thông qua những giáo lý nhân sinh vẫn mang lại cảm giác ám ảnh đáng sợ.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Arak Amornsupasiri","avatar":""},{"name":"ธเนศ วรากุลนุเคราะห์","avatar":""},{"name":"Prin Suparat","avatar":""},{"name":"Kannarun Wongkajonklai","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["鬼故事","Haunted Tales","เรื่อง ผี เล่า","เรื่องผีเล่า"]', 1784690324319);
