INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-sao-dien-anh-hollywood-brad-pitt', 'Siêu Sao Điện Ảnh Hollywood: Brad Pitt', 'Brad Pitt: Breaking Hollywood', 'https://phimimg.com/upload/vod/20240928-1/a5aa141000ec06fe82c6b61d6ced7df5.jpg', 'https://phimimg.com/upload/vod/20240928-1/e6d13a445eb98df9ec567f619825cdba.jpg', '<p>Là một trong những nam diễn viên quyến rũ bậc nhất của Hollywood, Brad Pitt không ngại thử sức với vô số nhân vật, để rồi đã và đang lưu lại dấu ấn không chỉ về doanh thu phòng vé mà còn cả mặt hàn lâm.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Maria Pendolino","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Brad Pitt & Jennifer Aniston: Hollywood''s Couple of the Year"]', 1784690324319);
