INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-te-dia-nguc-phan-6', 'Chúa Tể Địa Ngục (Phần 6)', 'Lucifer (Season 6)', 'https://phimimg.com/upload/vod/20240927-1/9ec5e71ab8baacd3a6b22a7fb5a3a628.jpg', 'https://phimimg.com/upload/vod/20240927-1/393317b3ae812b98c7e4b909e95a8237.jpg', '<p>Phim xoay quanh câu chuyện của Lucifer Morningstar sau khi rời khỏi địa ngục với ý nghĩ mình đã trưởng thành, hắn định cư tại thành phố Los Angeles, nơi mà anh cho là thành phố của những thiên thần. Tuy nhiên, với những gì xảy ra ở đây nó như không muốn anh trở thành con người lương thiện mà đưa Lucifer Morningstar về lại bản tính hắn không hề mong.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tom Ellis","avatar":""},{"name":"Kevin Alejandr","avatar":""},{"name":"Lauren German","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["路西法","ლუციფერი","Λούσιφερ","Lucifer az Újvilágban","لوسيفر","루시퍼","Луцифер","魔鬼神探","Lucifer"]', 1784690324319);
