INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('new-amsterdam-phan-4', 'New Amsterdam (Phần 4)', 'New Amsterdam (Season 4)', 'https://phimimg.com/upload/vod/20240925-1/f946c2b510d1337a218613976081a569.jpg', 'https://phimimg.com/upload/vod/20240925-1/972a2ae16c3c5441623ea0420a32fdf2.jpg', '<p>Giám đốc y tế mới phá vỡ các quy tắc để hàn gắn hệ thống tại bệnh viện công lâu đời nhất nước Mỹ. Max Goodwin bắt đầu phá bỏ bộ máy quan liêu và cung cấp dịch vụ chăm sóc đặc biệt, nhưng các bác sĩ và nhân viên không chắc anh ấy có thể thành công hay không. Họ đã nghe điều này trước đây. Không coi câu trả lời là không, phản ứng theo bản năng của Tiến sĩ Goodwin đối với các vấn đề lớn và nhỏ là bốn từ đơn giản: Tôi có thể giúp gì? Anh ta phải phá vỡ hiện trạng và chứng minh rằng anh ta sẽ không dừng lại để thổi sức sống mới vào bệnh viện thiếu vốn và không được đánh giá cao này, trả lại vinh quang đã đưa nó lên bản đồ.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ryan Eggold","avatar":""},{"name":"Janet Montgomery","avatar":""},{"name":"Jocko Sims","avatar":""},{"name":"Tyler Labine","avatar":""},{"name":"Sandra Mae Frank","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["نيو أمستردام","Ню Амстердам","Hospital New Amsterdam","Nemocnice New Amsterdam","ახალი ამსტერდამი","New Amsterdam - Vészhelyzet New Yorkban","뉴 암스테르담","Szpital New Amsterdam","Spitalul Bellevue","Нови Амстердам","Новый Амстердам","Nový Amsterdam","紐約新醫革命","Лікарня «Новий Амстердам»","Bellevue","Bệnh Viện New Amsterdam","New Amsterdam"]', 1784690324319);
