INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-phap-su-va-thanh-thach-rave', 'Hội Pháp Sư Và Thánh Thạch Rave', 'EDENS ZERO', 'https://phimimg.com/upload/vod/20240924-1/7078d5b8165e984d42f3ef7990e3e317.jpg', 'https://phimimg.com/upload/vod/20240924-1/b8a4b2197acffcd5d674fc4e10f46ced.jpg', '<p>Rebecca đã gặp gỡ Shiki, chàng trai sở hữu năng lực điều khiển trọng lực tại Hành tinh của máy móc, Granbell. Theo lời chỉ dạy của Ziggy, cỗ máy đã làm cha nuôi và được mệnh danh là &quot;Ma vương&quot;, Shiki trân trọng bạn bè hơn bất cứ điều gì. Rebecca đã trở thành bạn của cậu và dẫn theo chàng trai Shiki không hề biết đến thế giới bên ngoài đó, lên chuyến hành trình đến Vũ trụ.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"寺島拓篤","avatar":""},{"name":"小松未可子","avatar":""},{"name":"釘宮理恵","avatar":""},{"name":"手塚ヒロミチ","avatar":""},{"name":"井澤詩織","avatar":""},{"name":"青木志貴","avatar":""},{"name":"安野希世乃","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["エデンズゼロ","えでんずぜろ","EDENS ZERO 2","EDENSZERO/エデンズ ゼロ","Edens Zero: Digest","EDENS ZERO"]', 1784690324319);
