INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-toi-oi', 'Xin Chào, Tôi Ơi!', 'Hello, Me!', 'https://phimimg.com/upload/vod/20240924-1/1c2d13cb6930e5e653818f381f301e08.jpg', 'https://phimimg.com/upload/vod/20240924-1/f7e87b61cdd18e442ccaa2b56c486cfa.jpg', '<p>Xin Chào Tôi Ơi kể về Ban Ha Ni (Choi Gang Hee thủ vai) người phụ nữ vừa bước sang tuổi 37, tính tình nhút nhát và hiện đang sống độc thân. Điều kiện cuộc sống hiện tại của cô thực sự bấp bênh vì công việc mà cô đang làm có thể bị sa thải bất cứ lúc nào. Cô luôn ấp ủ cho mình một gia đình hạnh phúc, đầm ấm như bao người. Tên gọi Xin Chào Tôi Ơi là lúc Ban Ha Ni rơi vào cuộc đấu tranh nội tâm gay gắt, rối bời. Và rồi cô bất chợt gặp lại chính bản thân mình lúc 17 tuổi, đó là một cô gái trẻ đến gõ cửa nhà để rồi Ban Ha Ni nhận ra bản thân từng là một người lạc quan và tươi sáng biết bao.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"최강희","avatar":""},{"name":"김영광","avatar":""},{"name":"이레","avatar":""},{"name":"음문석","avatar":""},{"name":"김유미","avatar":""},{"name":"지승현","avatar":""},{"name":"윤주상","avatar":""},{"name":"백현주","avatar":""},{"name":"Kim Sang-woo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Hola, yo!","سلام، این منم.","سلام؟ منم!","سلام؟ من خودمم.","こんにちは わたしだよ","こんにちは 私だよ","Annyeong? Naya!","你好？是我！","Hi? It''s Me","Hello, It''s Me!","안녕? 나야!"]', 1784690324319);
