INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-nay-khong-ai-bang-em', 'Thế Giới Này Không Ai Bằng Em', 'She is the One', 'https://phimimg.com/upload/vod/20240924-1/375d99ba8f0cb7092147f6d4278cd9a7.jpg', 'https://phimimg.com/upload/vod/20240924-1/2c074e44933456d9aa2ca0ea676ba244.jpg', '<p>Bộ phim xoay quanh câu chuyện về chàng rể giấu thân phận và nàng dâu giả thay chị ruột. Sau nhiều trải nghiệm trên con đường tình cảm của hôn nhân đầu tiên và sau đó là tình yêu, cả hai bị cuốn vào trò chơi tình cảm mèo vờn chuột. Liệu họ có chọn ở bên nhau trọn đời?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Pei Zitian","avatar":""},{"name":"李诺","avatar":""},{"name":"Wang Cong","avatar":""},{"name":"Yin Ye Zi","avatar":""},{"name":"Geng Jia Wei","avatar":""},{"name":"Li Jun Feng","avatar":""},{"name":"Cheng Ye Qing","avatar":""},{"name":"Dong Zhi Cheng","avatar":""},{"name":"Li Yong Tian","avatar":""},{"name":"Wu You","avatar":""},{"name":"Cheng Xiaomeng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["She Is the One","Ella es la única","全世界都不如你"]', 1784690324319);
