INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minh-chau-ruc-ro', 'Minh Châu Rực Rỡ', 'Praomook', 'https://phimimg.com/upload/vod/20240924-1/a27876ecfb0908c89de79a2bb4d1015a.jpg', 'https://phimimg.com/upload/vod/20240924-1/74df36a8f993819ad4723d70a4bcd0a7.jpg', '<p>Praomook là một cô gái làm việc tại một hộp đêm để kiếm tiền trả nợ. Cô với Chalunthorn đã xảy ra mâu thuẫn vì anh hiểu lầm cô, anh luôn cho rằng cô ấy là một cô gái xấu xa. Một ngày đẹp trời, cha mẹ Chalunthorn đã yêu cầu Praomook kết hôn với anh để xóa bỏ vận rủi cho chính anh. Cô chấp nhận lời cầu hôn chỉ để trả thù những hành động xem thường của anh dành cho mình. Nhưng để không kết hôn với cô, anh đã giả vờ mình là &quot;gay&quot; để trốn tránh nhưng cô không tin. Cuối cùng lý trí không thắng được con tim, họ bắt đầu yêu nhau, nhưng những trở ngại cho tình yêu của họ cũng bắt đầu xuất hiện khi Treenucht - người yêu cũ của Chalunthorn muốn cố gắng giành lại anh. Ngoài ra còn có Maithong, đối thủ của gia đình Praomook và Chalunthorn xuất hiện.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Nawasch Phupantachsee","avatar":""},{"name":"Bua Nalinthip Sakulongumpai","avatar":""},{"name":"Krating Khunnarong Pratesrat","avatar":""},{"name":"Ranchrawee Uakoolwarawat","avatar":""},{"name":"นิชคุณ ขจรบริรักษ์","avatar":""},{"name":"กัญญาภัค พงษ์ศักดิ์","avatar":""},{"name":"จักรพันธ์ พุทธา","avatar":""},{"name":"Ta Warit Tipgomut","avatar":""},{"name":"Benjawan Artner","avatar":""},{"name":"Mayurin Pongpudpunth","avatar":""},{"name":"Thanakrit Saengvanich","avatar":""},{"name":"Nithi Sm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["珠光璀璨","璀璨的珍珠","พราวมุก"]', 1784690324319);
