INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-anh-dao-tuoi-moi', 'Vị Anh Đào Tươi Mới', 'Brand New Cherry Flavor', 'https://phimimg.com/upload/vod/20240924-1/43cbf7c279d1d888105d4c9499058dea.jpg', 'https://phimimg.com/upload/vod/20240924-1/bd2f818d70452553f61ca7bb9dd9a2fc.jpg', '<p>Dựa trên cuốn tiểu thuyết cùng tên, limited series Brand New Cherry Flavor là một series kinh dị kỳ quái về thế giới siêu nhiên trải dài từ Los Angeles đến Brazil và trung tâm của nó là nhà làm phim trẻ Lisa Nova (Rosa Salazar). Cô như Alice rơi vào thế giới thần tiên, có điều, thỏ trắng dẫn cô đến một thế giới ma mị và thù hằn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rosa Salazar","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Eric Lange","avatar":""},{"name":"Jeff Ward","avatar":""},{"name":"Manny Jacinto","avatar":""},{"name":"Daniel Doheny","avatar":""},{"name":"Mark Acheson","avatar":""},{"name":"Hannah Levien","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["全新樱桃味","Абсолютно новий смак вишні","Brand New Cherry Flavor"]', 1784690324319);
