INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-den-phan-2', 'Mùa Hè Đen (Phần 2)', 'Black Summer (Season 2)', 'https://phimimg.com/upload/vod/20240924-1/efa6200920b8286430143614bf976254.jpg', 'https://phimimg.com/upload/vod/20240924-1/9264bb89f1d1d4ef7db4f0ceb3f3afe9.jpg', '<p>Mùa đông đến cùng những thử thách máu lạnh mới giữa đại họa zombie khi những kẻ săn xác điên cuồng và dân quân hung tợn chiến đấu với thây ma và nỗi tuyệt vọng.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jaime King","avatar":""},{"name":"Christine Lee","avatar":""},{"name":"Zoe Marlett","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["黑夏","Черное лето","Black Summer"]', 1784690324319);
