INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doa-hoa-tham-vong', 'Đóa Hoa Tham Vọng', 'Krachao Seeda', 'https://phimimg.com/upload/vod/20240924-1/fd08ac40149901aced1f7a84e52133e6.jpg', 'https://phimimg.com/upload/vod/20240924-1/9013243779820aa9197bca8408ea5980.jpg', '<p>Rum luôn mặc cảm vì xuất thân thấp hèn khi có mẹ là một người giúp việc nghèo. Rum có tham vọng lớn nên đã xác định với bản thân sẽ làm mọi cách để cuộc sống của mình tốt đẹp hơn cho đến khi không còn ai xúc phạm đến nguồn gốc của cô. Rum thầm yêu Lue, người giám hộ của cô, cũng là ông chủ của mẹ mình, mặc dù anh đã chính thức có vợ là Nampink. Vì vậy, Rum đã cố gắng kích động Nampink rằng Lue đã tán tỉnh nhiều cô gái. Nampink tin cô mà không biết rằng đây là kế hoạch độc ác của Rum nhằm loại bỏ Nampink và trở thành vợ của Lue. Cuộc sống của Lue trở nên tồi tệ khi anh bắt đầu ngoại tình với Rum sau lưng Nampink. Nampink phát hiện ra hai người mà mình tin tưởng lại lừa dối mình, cô dứt khoát ly hôn với Lue. Công việc của Lue gặp nhiều trục trặc vì không có tài trợ từ Nampink và những đàm tiếu không hay xung quanh anh. Tuy nhiên, Lue vẫn không chịu công bố rằng Rum là vợ mới của mình, điều này khiến Rum cảm thấy vô cùng khó chịu...</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 9, 2021, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Woranuch Bhirombhakdi","avatar":""},{"name":"Ausadaporn Siriwattanakul","avatar":""},{"name":"Peter Corp Dyrendal","avatar":""},{"name":"Jirayu Thantrakul","avatar":""},{"name":"Witaya Wasukraipaisarn","avatar":""},{"name":"Nappon Gomarachun","avatar":""},{"name":"Claudia Chakrabandhu Na Ayudya","avatar":""},{"name":"Kratip Chawallakorn Wanthanapisitkul","avatar":""},{"name":"Nat Thewphaingam","avatar":""},{"name":"Kanjanaporn Plodpai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Only You I Need","Krachao Seeda"]', 1784690324319);
