INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tuong-cuoc-dao-chinh', 'Thần tượng: Cuộc Đảo Chính', 'IDOL: The Coup', 'https://phimimg.com/upload/vod/20240924-1/d987e4b24a344531fa03ae7a8f469642.jpg', 'https://phimimg.com/upload/vod/20240924-1/397819473c638348c824a7d387aa285c.jpg', '<p>Nhằm giải tán nhóm nhạc thần tượng, họ cấp bách cần “thành công” một lần. Một nhóm nhạc thần tượng không có tiền đồ trình diễn một vở kịch giải tán nhóm nhạc xưa nay chưa từng có!</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"하니","avatar":""},{"name":"안솔빈","avatar":""},{"name":"엑시","avatar":""},{"name":"Han So-eun","avatar":""},{"name":"Green","avatar":""},{"name":"곽시양","avatar":""},{"name":"Kim Min-kyu","avatar":""},{"name":"Cho Jun-young","avatar":""},{"name":"Hong Eun-ki","avatar":""},{"name":"Baek Seo Hoo","avatar":""},{"name":"Lee Eun-sang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["偶像：The Coup","IDOL [아이돌 : The Coup]","아이돌: 더 쿠데타","IDOL [아이돌: The Coup]","偶像：砰然一擊"]', 1784690324319);
