INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-mua-xuan-xanh', 'Chờ Mùa Xuân Xanh', 'At a Distance, Spring is Green', 'https://phimimg.com/upload/vod/20240924-1/6bc75fc7d57a1d9c7506d0741d7f1ca7.jpg', 'https://phimimg.com/upload/vod/20240924-1/c1f172c5417334c8a33ce13668a70845.jpg', '<p>Được chuyển thể từ web truyện tranh cùng tên với chủ đề &quot;Đời là hài kịch nếu nhìn từ xa và là bi kịch nếu nhìn gần&quot;, kể về những éo le và mâu thuẫn của những người trẻ đương thời ngoài đời. Park Ji Hoon vào vai Lu Jun, chàng trai có vẻ ngoài điển trai và lớn lên trong một gia đình giàu có, học quản lý kinh doanh ở trường Đại học Yeongil. Người khác thấy cậu là một người hiền lành, thích nhõng nhẽo nhưng nội tâm lại ẩn giấu những đau thương và bí mật không ai biết được. Kang Min Ah vào vai Jin Su Bin, một sinh viên đại học có thực lực, chăm chỉ và trung thực. Bae In Hyuk vào vai Nam Soo Hyun, một sinh viên xuất sắc hạng A + trong tất cả các môn học cũng là người theo chủ nghĩa hoàn hảo.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"박지훈","avatar":""},{"name":"배인혁","avatar":""},{"name":"강민아","avatar":""},{"name":"Kwon Eun-bin","avatar":""},{"name":"Woo Da-vi","avatar":""},{"name":"Choi Jung-woo","avatar":""},{"name":"Lee Woo-je","avatar":""},{"name":"유인수","avatar":""},{"name":"Yoon Jung-hoon","avatar":""},{"name":"신수현","avatar":""},{"name":"최문희","avatar":""},{"name":"Bin Chan-uk","avatar":""},{"name":"차청화","avatar":""},{"name":"Eru","avatar":""},{"name":"김형묵","avatar":""},{"name":"소희정","avatar":""},{"name":"나인우","avatar":""},{"name":"김수겸","avatar":""},{"name":"Lee Ye-rim","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Meolriseo Bomyun Pooreun Bom","Зеленая весна вдали","Синяя весна издалека","Uzakta, Bahar Yeşildir","A Blue Spring from Afar","From Distance, Blue Spring","Blue Spring From a Distance","Seen From a Distance, Green Spring","멀리서 보면 푸른 봄"]', 1784690324319);
