INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cho-mua-xuan-xanh', 'Chờ Mùa Xuân Xanh', 'At a Distance, Spring is Green', 'chờ mùa xuân xanh at a distance, spring is green 박지훈 배인혁 강민아 kwon eun-bin woo da-vi choi jung-woo lee woo-je 유인수 yoon jung-hoon 신수현 최문희 bin chan-uk 차청화 eru 김형묵 소희정 나인우 김수겸 lee ye-rim meolriseo bomyun pooreun bom зеленая весна вдали синяя весна издалека uzakta, bahar yeşildir a blue spring from afar from distance, blue spring blue spring from a distance seen from a distance, green spring 멀리서 보면 푸른 봄', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-mat-hieu-kim', 'Tuyệt Mật Hiếu Kim', 'Top Secret Xiao Jin', 'https://phimimg.com/upload/vod/20240923-1/b26036d2820e772fbbae620453b2a789.jpg', 'https://phimimg.com/upload/vod/20240923-1/13f6137d171e1cd6c92c715d3011d5e5.jpg', '<p>Vào những năm đầu thời Trung Hoa Dân Quốc, những cuốn sách cổ của người giàu nhất ở Hiếu Thành đã bị đánh cắp, thám tử cảnh sát Trần Trọng Kim đã bị đổ tội khi tìm thấy những cuốn sách cổ. Các thế lực ở Hiếu Thành đều nhìn lăm le kho báu ẩn giấu bên trong sách cổ, cuộc sống yên tĩnh của nơi đây cũng bị quấy đến long trời lở đất. Đoàn người Trần Trọng Kim đã thành công đánh bại người Nhật trong cuộc chiến, thành công bảo vệ kho báu không rơi vào tay các kẻ trộm.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hongjie Wan","avatar":""},{"name":"Jiang Luxia","avatar":""},{"name":"張浩","avatar":""},{"name":"Zhou Zhou","avatar":""},{"name":"白庆琳","avatar":""},{"name":"He Yin","avatar":""},{"name":"Chen Long","avatar":""},{"name":"Bai Hailong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["二十四孝传奇","The Secret Of Filial Badges","绝密孝金"]', 1784690324319);
