INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-co-canh-gioi', 'Chiến Cơ Cảnh Giới', 'AMAIM Warrior at the Borderline', 'https://phimimg.com/upload/vod/20240923-1/939fedba09e2b7dd206469868c045cea.jpg', 'https://phimimg.com/upload/vod/20240923-1/6e661fd3b06101369ade60adc87abf50.jpg', '<p>Vào năm 2061 Dương lịch, Nhật Bản đã bị chiếm đóng và phân chia làm 4 khu vực do 4 nền kính tế trọng yếu của thế giới chi phối. Người Nhật đã trải qua những ngày bị áp bức dưới thân phận dân nước thuộc địa. Nơi đây trở thành tiền tuyến cùng với sự phát triển của vũ khí cơ động đặc biệt hình người AMAIM.

Cậu bé Shiiba Amou, người yêu thích cơ khí, vào một ngày nọ đã gặp gỡ với Gai, một AI (trí thông minh nhân tạo) có thể tư duy độc lập. Từ đây, trên chiếc AMAIM &quot;&quot;Kenbu&quot;&quot; do chính tay Amou tạo nên, cậu bước vào cuộc chiến giành lại nền độc lập cho Nhật Bản.</p>', 'Tập 13', 25, 'hoathinh', 'ongoing', 7, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"佐藤元","avatar":""},{"name":"藤原夏海","avatar":""},{"name":"市ノ瀬加那","avatar":""},{"name":"村田太志","avatar":""},{"name":"石川由依","avatar":""},{"name":"上村祐翔","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Kyōkai Senki","Kyoukai Senki","境界戰機第二部","War Machines on the Borderline","AMAIM Warrior at the Borderline","Biên Giới Chiến Ký","Cảnh Giới Chiến Cơ","境界戦機"]', 1784690324319);
