INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoc-chieu-lenh-phan-1', 'Ngọc Chiêu Lệnh - Phần 1', 'No Boundary Season 1', 'https://phimimg.com/upload/vod/20240923-1/a83e88f5ea8c9ef86dee649fec4cc7fb.jpg', 'https://phimimg.com/upload/vod/20240923-1/9f82dc6f6d6d0a8b027f970058aabb68.jpg', '<p>Ngọc Chiêu Lệnh kể về Thương Trụ vô đạo, Cơ Vũ thay thế. Dưới đài Phong Thần, Khương Tử Nha đã nhường thần vị, cam nguyện làm công hầu dưới nhân gian, bảo vệ nghĩa nữ Đoan Mộc Thúy trở thành tiên. Thoắt cái đã ngàn năm, thiên hạ là của Đại Tống. Vì danh tiếng &quot;thẩm vấn cả âm dương&quot; của Bao Thanh Thiên, Đoan Mộc Thúy hạ phàm lập nên môn phái &quot;Tế Hoa Lưu&quot;, Tứ phẩm Đới đao Hộ vệ Triển Chiêu phụng lệnh Bao Chửng, &quot;bù trừ lẫn nhau&quot; với Đoan Mộc Thúy, trải qua vài phen đồng sinh cộng tử thì lặng lẽ nảy sinh tình cảm.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"张艺上","avatar":""},{"name":"Darren Chen","avatar":""},{"name":"Wang Yifei","avatar":""},{"name":"古子成","avatar":""},{"name":"楊澤","avatar":""},{"name":"Wang Yinuo","avatar":""},{"name":"謝君豪","avatar":""},{"name":"韓棟","avatar":""},{"name":"Liu Zhiyang","avatar":""},{"name":"Liu Yang","avatar":""},{"name":"Hei Ze","avatar":""},{"name":"書亞信","avatar":""},{"name":"盧昱曉","avatar":""},{"name":"洪瀟","avatar":""},{"name":"Yu Tong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["开封志怪","No Boundary","玉昭令"]', 1784690324319);
