INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-cuong-cua-soi', 'Kim cương của sói', 'Coyotes', 'https://phimimg.com/upload/vod/20240921-1/02a4bc872cc23623b840f346f773a391.jpg', 'https://phimimg.com/upload/vod/20240921-1/1e8f773ee6550d5ab35bd95e8d095687.jpg', '<p>Một nhóm bạn thân ở trại hè tìm thấy kim cương trong rừng, khiến một thử thách gay go nổ ra, thách thức tình bạn của họ và đẩy cuộc sống của họ vào vòng nguy hiểm.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 16, 2021, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Kassim Meesters","avatar":""},{"name":"Léo Hainaut","avatar":""},{"name":"Isabelle Defossé","avatar":""},{"name":"Anas El Marcouchi","avatar":""},{"name":"Tessa Balzano","avatar":""},{"name":"Louka Minnella","avatar":""},{"name":"Sarah Ber","avatar":""},{"name":"Victoria Bluck","avatar":""},{"name":"Felix Vannoorenberghe","avatar":""},{"name":"Dara Tombroff","avatar":""},{"name":"Magaly Teixeira","avatar":""},{"name":"Nilton Martins","avatar":""},{"name":"Philippe Jeusette","avatar":""},{"name":"Antonythasan Jesuthasan","avatar":""},{"name":"Valérie Bodson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Coyotes"]', 1784690324320);
