INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-mua-tuyet-roi', 'Tình Yêu Mùa Tuyết Rơi', 'Snow Lover', 'https://phimimg.com/upload/vod/20240920-1/05bad2469754aba9bf974357232fce3e.jpg', 'https://phimimg.com/upload/vod/20240920-1/2903fdf11f06b1cf81cab906c7e7e676.jpg', '<p>Chuyện phim Tình Yêu Mùa Tuyết Rơi bắt đầu từ Vương Hiểu An, một nhà biên soạn kịch bộ phim không được đào tạo chính quy đang gặp khó khăn trong sự nghiệp của mình, cô không thể xóa đi nhãn nhà soạn kịch chuyên soạn kịch ảo. Bất ngờ một ngày nọ cô gặp lại Hách Phong chàng nhân tài IT học bá từ nhỏ và đồng thời là mối tình đầu của cô nhưng họ đã chia tay do một sự hiểu lầm.

Cả hai giờ đây trở thành đồng nghiệp của nhau, khi Hách Phong đang chuẩn bị cho việc nghiên cứu chế tạo một trò chơi tình tiết liên quan đến trượt tuyết nên anh cần một người trù hoạch biết trượt tuyết. Sau khi tìm hiểu thì anh biết được Vương Hiểu An là một cao thủ bộ môn này, dù có hơi khó xử nhưng cô nàng nhanh chóng nhận lời làm việc vì đang trong tình trạng thất nghiệp. Đây cũng là lúc mà Tình Yêu Mùa Tuyết Rơi bắt đầu, tình cảm giữa họ bắt đầu được hâm nóng sau thời gian dài cô đơn</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xu Xiaonuo","avatar":""},{"name":"高旻睿","avatar":""},{"name":"Zhang Xin","avatar":""},{"name":"Yu Yijie","avatar":""},{"name":"Su Jianquan","avatar":""},{"name":"曾柯琅","avatar":""},{"name":"Hu Caihong","avatar":""},{"name":"孙书博","avatar":""},{"name":"Cui Baoyue","avatar":""},{"name":"Mei Bao Lai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["爱在粉雪时光","Amante En La Nieve"]', 1784690324320);
