INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-anne-dong-tinh', 'Nàng Anne đồng tính', 'Anne+: The Film', 'https://phimimg.com/upload/vod/20240910-1/37d11623afa3cd88cb5f5af63cf1b37c.jpg', 'https://phimimg.com/upload/vod/20240910-1/2b827b160cab20ab7ecaf137538916b9.jpg', '<p>Một nữ sinh viên hai mươi tốt nghiệp đại học dành cho người đồng tính nữ ở Amsterdam chuẩn bị lên đường tới Montreal, đồng thời điều hướng cuộc sống xã hội của mình và viết carreer.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub', 'FHD', 'Hà Lan', 0, '[{"name":"Hanna van Vliet","avatar":""},{"name":"Jouman Fattal","avatar":""},{"name":"Thorn Roos de Vries","avatar":""},{"name":"Eline van Gils","avatar":""},{"name":"Jesse Mensah","avatar":""},{"name":"Jade Olieberg","avatar":""},{"name":"Huib Cluistra","avatar":""},{"name":"Amy van der Weerden","avatar":""},{"name":"Ayla Satijn","avatar":""},{"name":"Jacqueline Blom","avatar":""},{"name":"Hein van der Heijden","avatar":""},{"name":"Romana Vrede","avatar":""},{"name":"Anne-Chris Schulting","avatar":""},{"name":"Georgina Verbaan","avatar":""},{"name":"Anna Drijver","avatar":""},{"name":"H","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324320);
