INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-sidonia', 'Hiệp Sĩ Sidonia', 'Knights Of Sidonia: Love Woven In The Stars', 'https://phimimg.com/upload/vod/20231108-1/4df3048d71fd836d7387621b0ad86664.jpg', 'https://phimimg.com/upload/vod/20231108-1/7a74944b5a69f1ae4acc2a7a246870eb.jpg', '<p>Đã 10 năm trôi qua kể từ tập cuối của bộ phim truyền hình, phi hành đoàn của Sidonia đã chuẩn bị kỹ lưỡng cho cuộc chiến lớn với sinh vật không tương tác, Gauna, để định cư ở hành tinh thứ bảy trong hệ sao Lem. Át chủ bài Nagate yêu Tsumugi tha thiết.&nbsp;Tuy nhiên, ác ý của một nhà khoa học già ẩn náu trong một chàng trai đã thay đổi toàn bộ tình hình.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ryota Osaka","avatar":""},{"name":"Aya Suzaki","avatar":""},{"name":"Aki Toyosaki","avatar":""},{"name":"Hisako Kanemoto","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Ayane Sakura","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324320);
