INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tung-dong-xu-phim-tai-lieu-one-ok-rock', 'Tung đồng xu: Phim tài liệu ONE OK ROCK', 'Flip a Coin: ONE OK ROCK Documentary', 'https://phimimg.com/upload/vod/20231108-1/5ddd9282eceae85099ae9671d7d0ea52.jpg', 'https://phimimg.com/upload/vod/20231108-1/ae8169cb7e5d358887373e2a6bf266a7.jpg', '<p>Không lưu diễn được trong năm 2020, các thành viên của ONE OK ROCK tập luyện nhiều tháng để có được một buổi biểu diễn trực tuyến sôi động không kém gì diễn trực tiếp.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takahiro Moriuchi","avatar":""},{"name":"Toru Yamashita","avatar":""},{"name":"Ryota Kohama","avatar":""},{"name":"Tomoya Kanki","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324320);
