INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-long-thien-quan', 'Hám Long Thiên Quan', 'Dragon Shaking Coffin', 'https://phimimg.com/upload/vod/20231108-1/3b8e2c62e298dd34e18d93888ca51864.jpg', 'https://phimimg.com/upload/vod/20231108-1/45d400fc1337f4ce3cc5df49a2e59620.jpg', '<p>Vào thời Trung Hoa Dân Quốc, một bộ xương kỳ lạ của người khổng lồ từ trên trời rơi xuống, ngôi mộ cổ của Thiên Khả Hãn triều Nguyên đã được phát hiện. Trương Thiên Lăng, một nhà nghiên cứu di tích văn hóa khảo cổ sau khi trải qua nguy hiểm đã tìm thấy ngôi mộ cổ trên trời. Cùng lúc đó, đặc vụ Nhật Bản Uno Chiyo đã âm mưu đánh cắp số tài sản khổng lồ từ &quot;quan tài rồng&quot;. Một trận chiến đẫm máu để bảo vệ kho báu quốc gia chính thức bắt đầu.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Lincheng","avatar":""},{"name":"Zhang Dong","avatar":""},{"name":"Wang Shu Dan","avatar":""},{"name":"Kunlun","avatar":""},{"name":"Zhang Chunzhong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324320);
