INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-du-ky-tai-the-yeu-vuong', 'Tây Du Ký: Tái Thế Yêu Vương', 'The Monkey King: Reborn', 'https://phimimg.com/upload/vod/20231103-1/f34f19d5aea5fcfd771e1d219d303a3f.jpg', 'https://phimimg.com/upload/vod/20231103-1/eb3530be1287fc3ac1d925ea39222b3a.jpg', '<p>Khi bắt đầu hỗn loạn, con quỷ đầu tiên trên thế giới được sinh ra, tên là Yuandi, và được tôn thờ như tổ tiên của loài quỷ. Hàng nghìn năm sau, cựu quỷ vương Tôn Ngộ Không được Đường Tăng cứu thoát khỏi núi Ngũ Hành, người hứa sẽ bảo vệ anh ta và đi về phương Tây để lấy kinh sách.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jiang Bian","avatar":""},{"name":"Haiting Cai","avatar":""},{"name":"Su Shangqing","avatar":""},{"name":"Zhang Lei","avatar":""},{"name":"He Zhang","avatar":""},{"name":"Lin Qiang","avatar":""},{"name":"Sicen Liu","avatar":""},{"name":"Wang Chenguang","avatar":""},{"name":"Zhongyang Baomu","avatar":""},{"name":"Sheng Feng","avatar":""},{"name":"Zhang Yaohan","avatar":""},{"name":"Bai Xuecen","avatar":""},{"name":"Qiu Qiu","avatar":""},{"name":"Roly Gutiérrez","avatar":""},{"name":"Jason Kesser","avatar":""},{"name":"Donald Guzzi","avatar":""},{"name":"Dalton Walker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324320);
