INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tay-du-ky-tai-the-yeu-vuong', 'Tây Du Ký: Tái Thế Yêu Vương', 'The Monkey King: Reborn', 'tây du ký: tái thế yêu vương the monkey king: reborn jiang bian haiting cai su shangqing zhang lei he zhang lin qiang sicen liu wang chenguang zhongyang baomu sheng feng zhang yaohan bai xuecen qiu qiu roly gutiérrez jason kesser donald guzzi dalton walker ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-dau-bep-cua-toi', 'Cô Nàng Đầu Bếp Của Tôi', 'Mae Krua Kon Mai', 'https://phimimg.com/upload/vod/20240908-1/171a8923b28bff55486d6a1774208914.jpg', 'https://phimimg.com/upload/vod/20240908-1/b73cdb29aebc1bda93362474b40d24f4.jpg', '<p>Cô Nàng Đầu Bếp Của Tôi - Mae Krua Kon Mai xoay quanh nhân vật Lomdao, một cô gái hiền lành, lương thiện. Lomdao có cuộc hôn nhân sắp đặt với chàng trai Balam, nhưng cô đã từ chối vì chưa bao giờ nhìn thấy mặt anh ta và cũng không hề biết anh là người như thế nào. Chính vì thế mà Lomdao quyết định làm người hầu trong một gia đình giàu có với cái tên Fai Dam để trang trải cuộc sống. Tuy nhiên, cô lại không hề biết mình đang làm cho gia đình của Balam. Còn với Balam, anh cảm thấy có nhiều điều kỳ lạ đối với Fai Dam, và cuối cùng cũng phát hiện cô chính là Lomdao, vị hôn thê của mình. Cả hai trải qua nhiều vui buồn, vượt qua nhiều sóng gió để đến được với nhau. Là bộ phim remake từ bộ cùng tên 2007, cặp đôi diễn viên trẻ đẹp, tài năng và đã từng là cặp đôi phụ tham gia &quot;Lồng Nghiệp chướng&quot; phim rating cao nhất đài 2019 và là một trong 10 phim có rating cao nhất Thái Lan.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ampere Suttatip Wutchaipradit","avatar":""},{"name":"August Vachiravit Paisarnkulwong","avatar":""},{"name":"Namfah Thunyaphat Phatrathinchaicherin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324320);
