INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-gia', 'Sói Già', 'Mad Wolf', 'https://phimimg.com/upload/vod/20240908-1/d9c7fb4a441a28a8fd50ae7790fe8b02.jpg', 'https://phimimg.com/upload/vod/20240908-1/10c5844594112fa5b4ff146a46e966cd.jpg', '<p>Những cuộc đấu trí căng thẳng, hồi hộp giữa cảnh sát và băng đảng tội phạm gian xảo, xen lẫn những mưu mô toan tính nội bộ giữa những người anh em lớn lên cùng một cô nhi viện.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 16, 2021, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Ưng Hoàng Phúc","avatar":""},{"name":"Thu Thủy","avatar":""},{"name":"Quách Ngọc Ngoan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324320);
