INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-trung-han-dao-hanh', 'Tuyết Trung Hãn Đao Hành', 'Sword Snow Stride', 'https://phimimg.com/upload/vod/20240904-1/964618d3f71bd65558fb052ab207c968.jpg', 'https://phimimg.com/upload/vod/20240904-1/6c57d129aa6b63626fb8a4a8dde2af79.jpg', '<p>Thế tử Bắc Lương vương Từ Phượng Niên tài hoa xuất chúng, dưới sự mong đợi tha thiết của phụ thân Từ Kiêu, cuối cùng cũng trở thành nhân tài. Ngày ngày rèn luyện, gặp nhiều khó khăn, Từ Phượng Niên cưỡi ngựa tung hoành trên giang hồ đầy bí ẩn. Tuy đường sá xa xôi lại nhiều trở ngại, những kẻ có ý định giết cậu vẫn rình rập xung quanh, nhưng cậu vẫn kiên định đi hết chặng đường, tu luyện đến cảnh giới Thiên Nhân Đại Trường Sinh. Trên con đường hành tẩu giang hồ, Từ Phượng Niên phấn đấu vì mối thù của mẫu thân, bên cạnh việc nâng cao võ nghệ, cậu còn được lòng rất nhiều nhân sĩ giang hồ.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 9, 2021, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"张若昀","avatar":""},{"name":"胡军","avatar":""},{"name":"Li Gengxi","avatar":""},{"name":"Yang Haoyu","avatar":""},{"name":"張天愛","avatar":""},{"name":"丁笑瀅","avatar":""},{"name":"Qiu Xinzhi","avatar":""},{"name":"刘端端","avatar":""},{"name":"李纯","avatar":""},{"name":"高偉光","avatar":""},{"name":"Gao Taiyu","avatar":""},{"name":"Janice Man","avatar":""},{"name":"张艺上","avatar":""},{"name":"張天陽","avatar":""},{"name":"Meng Ziyi","avatar":""},{"name":"Li Nian","avatar":""},{"name":"Zhang Xiaochen","avatar":""},{"name":"Tian Xiaojie","avatar":""},{"name":"Rong Zishan","avatar":""},{"name":"Liu Tianzuo","avatar":""},{"name":"隋俊波","avatar":""},{"name":"Jia Ze","avatar":""},{"name":"于荣光","avatar":""},{"name":"Yuming Du","avatar":""},{"name":"刘佩琦","avatar":""},{"name":"Liao Huijia","avatar":""},{"name":"Shen Baoping","avatar":""},{"name":"Sun Yali","avatar":""},{"name":"Dong Ya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324320);
