INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-nhac-kich', 'Cô Gái Nhạc Kịch!!', 'Kageki Shojo!!', 'https://phimimg.com/upload/vod/20240709-1/3f92bf65a98584b506a23ccb0ee4b147.jpg', 'https://phimimg.com/upload/vod/20240709-1/e58124f4e7230c1f600e5210b44b355a.jpg', '<p>Được thành lập vào thời Taisho, Kouka Kageki là đoàn ca kịch chỉ bao gồm những cô gái chưa kết hôn. Những vở diễn của họ đã đánh cắp trái tim của biết bao nhiêu người. Vài năm sau, học viện âm nhạc Kouka Kageki được thành lập, và chỉ những cô gái xinh đẹp mới có thể gia nhập. Watanabe Sarasa là một cô gái ngây thơ với chiều cao 1m78 khao khát được đóng vai Oscar-sama. Narada Ai là một cựu thần tượng nổi tiếng toàn quốc, người luôn thơ ơ với mọi thứ, kể cả ước mơ lẫn bạn bè. Cuộc sống học đường đầy hy vọng và biến động của họ chuẩn bị bắt đầu.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 16, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324320);
