INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('everybody-in-the-house', 'Everybody In The House', 'Everybody In The House', 'https://phimimg.com/upload/vod/20240709-1/3aad3b1ddb060eb4fe2a7560b6d2a1cf.jpg', 'https://phimimg.com/upload/vod/20240709-1/644b092127600e0008f2e94f4c40813c.jpg', '<p>Ma Dai, một lập trình viên tự do, sống cùng ông nội Ma Tian Mings chuyển nhà trong khi ông nội đang sống trong một ngôi nhà ba phòng ngủ khác cùng cháu gái và gia đình cô. Họ đã mở một tiệm mát-xa trong cộng đồng. Một ngày nọ, Mã Thiên Minh vô tình xịt thuốc vào một khách hàng và khiến anh ta phải nhập viện. Để kiếm tiền bồi thường, anh quyết định cho thuê căn nhà hai phòng ngủ nơi Mã Đại đang ở. Vì vậy, Ma Dai bắt đầu cuộc sống chung với Peng Wei Wei, người dẫn chương trình của taobao Lives. Hai người ban đầu có mâu thuẫn với nhau, dần dần có phản ứng hóa học. Sau đó, cuộc sống thường nhật của cộng đồng tái định cư tràn ngập tiếng cười, chửi bới liên tục.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Patrick Zhang","avatar":""},{"name":"Ma Shu Liang","avatar":""},{"name":"Liu Xuan Rui","avatar":""},{"name":"Walley","avatar":""},{"name":"heping","avatar":""},{"name":"liangwenhui","avatar":""},{"name":"Ping Ni","avatar":""},{"name":"Sa Dật","avatar":""},{"name":"Li Jian Yi","avatar":""},{"name":"Zhiguang Xia","avatar":""},{"name":"Đàn Kiện Thứ","avatar":""},{"name":"Hai Yi Tian","avatar":""},{"name":"Sonya","avatar":""},{"name":"Han Hao Lin","avatar":""},{"name":"Jia Bing","avatar":""},{"name":"Chen Xi Xu","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324320);
