INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-tach-ca-phe-nhe', 'Một Tách Cà Phê Nhé?', 'Would You Like A Cup Of Coffee?', 'https://phimimg.com/upload/vod/20240709-1/ccc97f4dbd74c8c5b60a9b5a91938564.jpg', 'https://phimimg.com/upload/vod/20240709-1/c9d41eae9bc4c5c554735ccb17f30f0f.jpg', '<p>Phim xoay quanh Kang Go Bi (Ong Seong Wu), một người có niềm đam mê với cà phê. Niềm đam mê này đã khiến anh chàng trở thành một nhân viên pha chế tại cửa hàng cà phê do Park Seok làm chủ. Kang Go Bi tìm hiểu về cà phê và con người thông qua các bài học cuộc sống của Park Seok.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ong Seong-wu","avatar":""},{"name":"Park Ho-san","avatar":""},{"name":"Seo Young-hee","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324320);
