INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-binh-minh-vien-da-than', 'Truyền Thuyết Bình Minh: Viên Đá Thần', 'Legends Of Dawn The Sacred Stone', 'https://phimimg.com/upload/vod/20240709-1/1aaa26ee134597dd326fad88694be17c.jpg', 'https://phimimg.com/upload/vod/20240709-1/0aad40d5b187f201ba1b51b58d96b94a.jpg', '<p>Truyền Thuyết Bình Minh: Viên Đá Thần kể về câu chuyện của Claude, một tên trộm khét tiếng, khi anh ta cố gắng đánh cắp Sacred Stone từ kinh đô. Khi câu chuyện mở ra, người xem được đưa vào một cuộc hành trình hài hước với một dàn anh hùng mang tính biểu tượng, những người cố gắng ngăn chặn anh ta, đồng thời khám phá động cơ thực sự của Claude là muốn đánh cắp viên đá.</p>', 'Hoàn Tất (9/9)', 9, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324320);
