INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-tiem-thieu-nien-mong-huyen-tay-du', 'Chỉ Tiêm Thiếu Niên (Mộng Huyễn Tây Du)', 'Fantasy Westward Journey', 'https://phimimg.com/upload/vod/20240709-1/4b6609e8e5b33f82c6d7ee7143661701.jpg', 'https://phimimg.com/upload/vod/20240709-1/09e3f8e7f32365477a6d70d1fd021816.jpg', '<p>Phim bắt đầu từ một nhóm bạn chơi game bỗng lạc vào thế giới trong game và vì một lỗi trong trò chơi mà xảy ra nhiều cuộc khủng hoảng chồng chéo giữa thực tế và thế giới ảo. Trong phim, Trần Dao thủ vai Cốc Linh – người bạn, người đồng đội thân thiết của Nhậm Nhất Hiệp (Cung Tuấn đóng) – một chàng trai nghiện game chính hiệu.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cung Tuấn","avatar":""},{"name":"Lưu Dịch Sướng","avatar":""},{"name":"Trần Bách Dung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324320);
