INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-mat-nguon-coi', 'Lạc Mất Nguồn Cội', 'Kaew Lerm Korn', 'https://phimimg.com/upload/vod/20240709-1/f1e67caa28dbf907946531b9de1dd32b.jpg', 'https://phimimg.com/upload/vod/20240709-1/13b9c3b2abded1a72cadb7a5664082fd.jpg', '<p>Kể về hai chị em song sinh Kaew và Chidchanok bị chia cắt từ nhỏ vì âm mưu thâm hiểm của người chú, nhằm chiếm đoạt tài sản của cha họ. Sau đó Kaew lớn lên trong cảnh nghèo khó, trong khi Chidchanok sống cùng cha tại Pháp. Rồi Chidchanok quyết định về Thái Lan để tìm mẹ. Tại đây cặp song sinh hội ngộ và cùng nhau thoát khỏi người chú luôn mang dã tâm trừ khử cả hai.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2021, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Green Ausadaporn Siriwattanakul","avatar":""},{"name":"Kang Korn Sirisorn","avatar":""},{"name":"Dom Haetrakul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324320);
