INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-chinh-dau-tranh-vi-nuoc-my', 'Tu Chính: Đấu Tranh Vì Nước Mỹ', 'Amend: The Fight For America', 'https://phimimg.com/upload/vod/20240709-1/cc989f2a5097daa3e9191678f04b16ee.jpg', 'https://phimimg.com/upload/vod/20240709-1/31092e00d30e3f312338a85bae778203.jpg', '<p>Will Smith dẫn dắt góc nhìn về cuộc đấu tranh cho quyền bình đẳng ở Mỹ, biến đổi từng ngày và thường gây chết chóc, qua lăng kính của Tu chính án thứ 14 Hiến pháp Hoa Kỳ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Mahershala Ali","avatar":""},{"name":"Laverne Cox","avatar":""},{"name":"Utkarsh Ambudkar","avatar":""},{"name":"Bambadjan Bamba","avatar":""},{"name":"Sterling K. Brown","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Rafael Casal","avatar":""},{"name":"Whitney Cummings","avatar":""},{"name":"Daveed Diggs","avatar":""},{"name":"Hannah Gadsby","avatar":""},{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Graham Greene","avatar":""},{"name":"Diane Guerrero","avatar":""},{"name":"Helen Hunt","avatar":""},{"name":"Jo","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324320);
