INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hao-quang', 'Hào Quang', 'The Justice', 'https://phimimg.com/upload/vod/20240709-1/385431205de2f65d71f2daf3aa150a27.jpg', 'https://phimimg.com/upload/vod/20240709-1/8b17bd717af4144ed8541156608085b1.jpg', '<p>Trình Diệc Trị (Trương Tân Thành đóng) xuất thân bần hàn, vì tình cờ mà quen biết với chủ ngân hàng Ngô Tri Phất, quyết tâm tiến vào ngành tiền tệ phát triển, đồng thời cùng con gái chủ ngân hàng Lệ Tư (Thái Văn Tịnh đóng) kết thành vợ chồng giả. Sau đó, Trình Diệc Trị phát hiện chủ ngân hàng tư nhân đã gây nên cái chết của Ngô Tri Phất, đồng thời cấu kết với thế lực khắp nơi tạo nên một đến quốc tiền đen khổng lồ. Trình Diệc Trị biết được chân tướng không chút do dự lựa chọn rời khỏi ngân hàng tư nhân, cùng tạo nên ngân hàng mới. Sau khi cùng trải qua khó khăn, Trình Diệc Trị và Lệ Tư cũng nảy sinh tình cảm, trở thành cặp đôi hiểu nhau. Bộ phim với sự tham gia diễn xuất của nam chính bộ phim tình cảm “Một Ngày Biến Thành Em” Trương Tân Thành đang được phát sóng tại trang web.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Tân Thành","avatar":""},{"name":"Elvira","avatar":""},{"name":"Zhang Zhi Jian","avatar":""},{"name":"Cố Tử Thành","avatar":""},{"name":"Wang Zi Jian","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324320);
