INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('capitani-phan-2', 'Capitani (Phần 2)', 'Capitani (Season 2)', 'https://phimimg.com/upload/vod/20240709-1/b7cde1bae9f9c97cc7a4f1e0bc7d5218.jpg', 'https://phimimg.com/upload/vod/20240709-1/466c376d46f4c1a53a4bb1fb8797c457.jpg', '<p>Hiện đang sống ở Thành phố Luxembourg, Luc Capitani nhận một công việc sớm khiến anh vướng vào cuộc điều tra án mạng có liên quan đến thế giới tội phạm ngầm ở thủ đô.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 15, 2021, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Luc Schiltz","avatar":""},{"name":"Sophie Mousel","avatar":""},{"name":"Claude De Demo","avatar":""},{"name":"Joe Dennenwald","avatar":""},{"name":"Konstantin Rommelfangen","avatar":""},{"name":"Jules Werner","avatar":""},{"name":"Jil Devresse","avatar":""},{"name":"Julie Kieffer","avatar":""},{"name":"Edita Malovčić","avatar":""},{"name":"Philippe Thelen","avatar":""},{"name":"Edson Anibal","avatar":""},{"name":"Adrien Papritz","avatar":""},{"name":"Lydia Indjova","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324320);
