INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vach-toi', 'Vạch Tội', 'Shadow Of Justice', 'https://phimimg.com/upload/vod/20240709-1/31693ea467449b240966e6324f753d37.jpg', 'https://phimimg.com/upload/vod/20240709-1/0e0cf3c2d0c9865a52d66fc274c583ce.jpg', '<p>Một vụ tai nạn thảm khốc xảy ra mà không hề để lại một manh mối nào. Trong khi cảnh sát Âu Dương Thông cùng đồng đội tìm mọi cách để tống kẻ gây tai nạn vào tù thì luật sư Đới Chính Quân lại cố gắng tìm thấy sơ hở để bào chữa cho thân chủ. Một cuộc đấu trí cam go âm thầm bắt đầu.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 8, 2021, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Âu Dương Chấn Hoa","avatar":""},{"name":"Mã Đức Chung","avatar":""},{"name":"Vạn Ỷ Văn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324320);
