INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-cam-do-nong-bong-brazil', 'Sự Cám Dỗ Nóng Bỏng: Brazil', 'Too Hot To Handle: Brazil', 'https://phimimg.com/upload/vod/20240709-1/f889b92fe7c4438d73c01e245da1724b.jpg', 'https://phimimg.com/upload/vod/20240709-1/d089101d0a3e7f2e1c208ee8bccd67da.jpg', '<p>Một nhóm người Brazil trẻ, nóng bỏng gặp gỡ ở khu nghỉ mát thơ mộng ven biển. Song để giành 500.000 BRL, họ phải từ bỏ tình dục trong chương trình thực tế vui nhộn này.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 15, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Bruna Louise","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324320);
