INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-dien-ro-bad-and-crazy', 'Người Hùng Điên Rồ (Bad And Crazy)', 'Bad And Crazy', 'https://phimimg.com/upload/vod/20240709-1/45a2bf41cdd0aa0f2ad65defb1f8f6cf.jpg', 'https://phimimg.com/upload/vod/20240709-1/8f22acc2d01e0c2649305e5244976e2a.jpg', '<p>Người Hùng Điên Rồ (Bad and Crazy) là một bộ phim chủ nghĩa anh hùng về kẻ xấu có năng lực Soo Yeol (Lee Dong Wook) đã phục hồi nhân tính sau khi gặp K (Wi Ha Joon), một người điên rồ nhưng chính trực. Soo Yeol (Lee Dong Wook) là một sĩ quan cảnh sát tài năng của đội truy bắt tội phạm ma túy dù chỉ tốt nghiệp trung học. Vì tham vọng của mình, anh chỉ nhận những nhiệm vụ mà cấp trên thích và cung cấp cho họ kết quả như ý muốn, đôi khi làm ngơ với một số điều bất chính. Khi kỳ thăng chức đến gần, Soo Yeol không có ai chống lưng phải đối mặt với việc có thể lại đánh mất cơ hội. Nghị sĩ Do Yoo Gon trao cho Soo Yeol hy vọng thăng chức một lần nữa, nhưng cuộc sống của anh lại rơi vào bế tắc khi K (Wi Ha Joon) chính trực điên rồ bất ngờ xuất hiện vào giây phút quyết định. Cuộc đụng độ giữa kẻ xấu Soo Yeol và kẻ điên K sẽ thế nào? Bộ phim Hàn Quốc của iQIYI Bad and Crazy với sự xuất hiện của Lee Dong Wook (Guardian: The Lonely and Great God, The Tale of a Gumiho, Touch Your Heart), Wi Ha Joon (Squid Game, Something in the Rain) và Han Ji Eun (Real). Được sản xuất bởi những nhà làm phim The Uncanny Counter cùng đội kỹ xảo của Guardian: The Lonely and Great God.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Dong Wook","avatar":""},{"name":"Wi Ha Jun","avatar":""},{"name":"Han Ji Eun","avatar":""},{"name":"Cha Hak Yeon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324320);
