INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dramaworld', 'Dramaworld', 'Dramaworld', 'https://phimimg.com/upload/vod/20240709-1/07874c87ae20a846c24fa56777932752.jpg', 'https://phimimg.com/upload/vod/20240709-1/ee02a9e7830db47a32dd2b6e30d65c9e.jpg', '<p>Nhân vật chính trong phim là một cô gái người Mỹ tóc vàng tên Claire. Cô ấy là một fan hâm mộ cuồng nhiệt của các bộ phim truyền hình Hàn Quốc. Một ngày nọ, khi cô đang làm việc trong cửa hàng của gia đình, thì một tên trộm đột nhập vào ngay lúc cô đang bật công tắc fan cuồng của mình lên. Cô đâm đầu vào ngay tên trộm. Thế nhưng, ngay khoảnh khắc đó, Claire bị hút vào một bộ phim truyền hình Hàn Quốc, thế giới của một chiều không gian khác nằm trong chiếc điện thoại của cô.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ha Ji Won","avatar":""},{"name":"Henry lau","avatar":""},{"name":"Olivia Hewson","avatar":""},{"name":"Li Fu Xiu Sen","avatar":""},{"name":"Xiao En Li Cha","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324320);
