INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-trinh-sat-hinh-su', 'Nhật Ký Trinh Sát Hình Sự', 'Murder Diary', 'https://phimimg.com/upload/vod/20240709-1/ff0874db49fea643aa8f637929078615.jpg', 'https://phimimg.com/upload/vod/20240709-1/49c86e12b2d4e41e2638bc17a76c3979.jpg', '<p>Cú sốc suýt bị giết chết bởi chính mẹ ruột lúc bé đã khiến trong Diệp Kình Phong hình thành nhân cách thứ hai tên Chu Cơ. Nếu Kình Phong khỏe mạnh, giỏi võ nghệ, thì Chu Cơ lại yếu đuối, hay bệnh vặt. Với trí thông minh hơn người, Cơ đã giúp cảnh sát giám định bút tích tội phạm một cách tài ba. Hai vụ án thảm khốc vừa xảy ra trong thành phố, giám đốc sở cảnh sát lập tức thành lập tổ phá án đặc biệt và mời Phong tham gia. Với điểm mạnh của từng thành viên, những bí mật của vụ án đã dần dần được hé lộ.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 8, 2021, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Vương Hạo Tín","avatar":""},{"name":"Huệ Anh Hồng","avatar":""},{"name":"Viên Vĩ Hào","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324320);
