INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-ma-tam-tri-phan-2', 'Giải Mã Tâm Trí (Phần 2)', 'The Mind, Explained (Season 2)', 'https://phimimg.com/upload/vod/20240903-1/1e321e9ca328803225eb5d5c8f95ecfd.jpg', 'https://phimimg.com/upload/vod/20240903-1/427ccdbbc1d7f7024c7a02cb4b4094b5.jpg', '<p>Trí óc của chúng ta có những khả năng tuyệt vời, nhưng cũng có thể giết chết những ý định tốt đẹp nhất. Hãy cùng tìm hiểu khoa học đằng sau sự sáng tạo, tẩy não, v.v.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 9, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emma Stone","avatar":""},{"name":"Julianne Moore","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324320);
