INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-chung-2021', 'Nhân Chứng', 'Key Witness', 'https://phimimg.com/upload/vod/20240709-1/a974efd09a4e26e473f38b7325c554c4.jpg', 'https://phimimg.com/upload/vod/20240709-1/07d73be049c59dea6fbb329b5f079f8b.jpg', '<p>Do không bảo vệ được nhân chứng trong một vụ buôn lậu ma túy quốc tế, quan chức Interpol Từ Hoắc Anh kết quả là phải từ chức. Trong một sự xoay vần của số phận, Hoắc Anh tham gia công việc săn nhân chứng, trong quá trình này, nhà lập kế hoạch Tang lễ Vương Vũ Huyên và nhân viên trò chơi điện tử Trần Chí Minh đã tham gia liên minh công lý của cô. Nhưng Hoắc Anh nhanh chóng nhận ra Chí Minhg và Vũ Huyên không giống như những gì họ có.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hồng Lệ Đình","avatar":""},{"name":"Trần Huýnh Giang","avatar":""},{"name":"Trần Sở Hoàn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324320);
