INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-vuon-mong-mo', 'Khu Vườn Mộng Mơ', 'Dream Garden', 'https://phimimg.com/upload/vod/20240709-1/2f022cb4edbd3252e96ebd60d69c9bc7.jpg', 'https://phimimg.com/upload/vod/20240709-1/cb5e3738382925ca2cda41cdd508ef90.jpg', '<p>Xiao Xiao và Lin Shen đã có ân oán trong một chương trình tạp kỹ tình yêu, tình cờ Xiao Xiao xin vào làm trợ lý của Lin Shen, trong quá trình làm việc và cuộc sống, họ đã cùng nhau giải quyết một số vụ án tâm lý, đồng thời cũng giải được tâm phục khẩu phục bên cạnh họ. Hết khủng hoảng này đến khủng hoảng khác, trái tim ngày càng gần nhau hơn. Sự nhiệt tình và sức sống của Xiao Xiao đã lây nhiễm cho Lin Shen, người có tính cách lạnh lùng, và Lin Shen đã dạy Xiao Xiao cách trở thành một nhà tư vấn tâm lý chuyên nghiệp xuất sắc.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Gong Jun","avatar":""},{"name":"Qiao Xin","avatar":""},{"name":"Jing Chao","avatar":""},{"name":"Sun Yi","avatar":""},{"name":"Zhang Duo","avatar":""},{"name":"Zhou Qiqi","avatar":""},{"name":"Wang Zexuan","avatar":""},{"name":"Ma Mengwei","avatar":""},{"name":"Zhou Shiyuan","avatar":""},{"name":"An Ge","avatar":""},{"name":"Wu Zheng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324320);
