INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-yeu-anh-tam-biet', 'Em Yêu Anh, Tạm Biệt!', 'Saying Goodbye', 'https://phimimg.com/upload/vod/20240709-1/cbffc96d7513852306b632caa4d74c02.jpg', 'https://phimimg.com/upload/vod/20240709-1/82740256d313b23885eafa34f49e4187.jpg', '<p>“Em Yêu Anh, Tạm Biệt!” kể về câu chuyện dù cuộc sống mang lại nhiều thách thức, nhưng chúng ta vẫn cần chào mừng cuộc sống. Mối tình yêu giữa họ có đến trễ không? Sau khi được biết hai người sẽ xa lìa nhau mãi mãi, họ có thể tiếp tục yêu nhau không?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Andrea Brillantes","avatar":""},{"name":"Seth Fedelin","avatar":""},{"name":"Andi Abaya","avatar":""},{"name":"Kobie Brown","avatar":""},{"name":"Nio Tria","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324320);
