INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-co-quyet-tran', 'Thiên Cổ Quyết Trần', 'Ancient Love Poetry', 'https://phimimg.com/upload/vod/20240709-1/d76b18141c170b621fb668bece01e552.jpg', 'https://phimimg.com/upload/vod/20240709-1/faa7305fb718d829979a1391d6c835ee.jpg', '<p>Thiên thần Thượng cổ – 1 vị thần với thật sau khi mất đi trí nhớ đã chờ đợi người trong mộng trong sự cô đơn. Nàng được chúng sinh tôn kính vô cùng, 1 lòng sùng bái. Mặc dù bị ba vị thần còn lại ghen ghét nhưng Thượng cổ vẫn thong thả tự tại. Nàng đã mất đi ký ức ba trăm năm thời hỗn độn, quên đi người mà nàng yêu nhất. Bây giờ, Cửu Châu tịch mịch, tam giới tuyệt vọng, Càn Khôn chỉ còn lại bóng dáng cô độc của nàng. Lần này, đổi lại là nàng đợi người ấy trở lại.</p>', 'Hoàn Tất (49/49)', 49, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Châu Đông Vũ","avatar":""},{"name":"Hứa Khải","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324320);
