INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ly-hon-kieu-an', 'Ly Hôn Kiểu Ấn', 'Decoupled', 'https://phimimg.com/upload/vod/20240709-1/812170375e38088936fb8ef2d74d0f97.jpg', 'https://phimimg.com/upload/vod/20240709-1/689a1a96985113d58182b3c2d9348af0.jpg', '<p>Trong loạt phim hài không e dè này, những ý kiến khác lạ của một tiểu thuyết gia kỳ quặc chọc điên cô-vợ-sắp-thành-vợ-cũ... và hầu hết những người anh gặp.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Madhavan","avatar":""},{"name":"Surveen Chawla","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324320);
