INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ly-hon-kieu-an', 'Ly Hôn Kiểu Ấn', 'Decoupled', 'ly hôn kiểu ấn decoupled madhavan surveen chawla ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-day-mi-luc-cua-toi', 'Người Yêu Đầy Mị Lực Của Tôi', 'My Lover Is A Mystery', 'https://phimimg.com/upload/vod/20240709-1/9c30931143352f860964551d721340bf.jpg', 'https://phimimg.com/upload/vod/20240709-1/39332f62b46ef400b709e910d0bb9a8a.jpg', '<p>Phim bắt đầu từ chủ tịch tập đoàn Yujie - Xinruila, người độc đoán hợp tác với người pha chế bí ẩn ở Mirage Bar để giải quyết cuộc khủng hoảng của công ty phát sóng trực tiếp. Lý do chấp thuận lời đề nghị của anh được cho là vì thua cược nên anh phải làm việc bán thời gian trong quán bar.Sau một thời gian tiếp xúc với nhau Xinruila bất ngờ phát hiện ra rằng anh chàng pha chế đó chính là người yêu thuở nhỏ của mình là Wen Qi, đã hơn 10 hơn trở về trước nhưng vì diện mạo lúc lớn thay đổi cùng tên của cũng đã được nên cả hai không nhận ra nhau khi mới gặp. Thực chất cả hai đã có mối tình đậm sâu và hiểu ý nhau đến mức không thể lìa xa, nhưng vì một sự hiểu lầm mà họ đã buông tay nhau. Giờ đây Xinruila không hiểu tại sao Wen Qi lại đổi tên và họ của mình? Câu chuyện Người Yêu Đầy Mị Lực Của Tôi chính thức một lần nữa bắt đầu giữa hai con người này.Đến khi tình cảm của cặp đôi chính gương vỡ lại lành chưa kịp vui mừng và tận hưởng khoảng thời gian hạnh phúc thì bất ngờ cả hai đối mặt với khủng hoảng của công ty. Cả hai cùng nhau bắt tay nhau khôi phục lại danh tiếng của công ty, trong quá trình bảo vệ họ hâm nóng tình cảm cho nhau, họ trở nên yêu nhau đậm sâu hơn.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Feiran Cao","avatar":""},{"name":"Fang Xiaodong","avatar":""},{"name":"Zhang Ju Ju","avatar":""},{"name":"Zhang Qi Dan Ya","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324320);
