INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-me-hai-con-phan-2', 'Hai Mẹ, Hai Con (Phần 2)', 'Daughter From Another Mother (Season 2)', 'https://phimimg.com/upload/vod/20240709-1/c12eb824e4da1db4533d924d3e887acc.jpg', 'https://phimimg.com/upload/vod/20240709-1/e949ee491b75db435cadd11bbd67cfd3.jpg', '<p>Khi Ana và Mariana vất vả sửa chữa lại sai lầm, tình yêu mới và những cơ hội sự nghiệp thú vị khiến mối quan hệ gia đình của họ chấn động đến tận cốt lõi.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 16, 2021, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Ludwika Paleta","avatar":""},{"name":"Paulina Goto","avatar":""},{"name":"Martín Altomaro","avatar":""},{"name":"Liz Gallardo","avatar":""},{"name":"Javier Ponce","avatar":""},{"name":"Oka Giner","avatar":""},{"name":"Dalexa Meneses","avatar":""},{"name":"Emilio Beltrán Ulrich","avatar":""},{"name":"Lisa Owen","avatar":""},{"name":"Zaide Silvia Gutiérrez","avatar":""},{"name":"Fernando Memije","avatar":""},{"name":"Elena del Río","avatar":""},{"name":"Christian Chávez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324320);
