INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-sinh-xin-chi-giao-nhieu-hon-quang-doi-con-lai-xin-chi-giao-nhieu-hon', 'Dư Sinh Xin Chỉ Giáo Nhiều Hơn / Quãng Đời Còn Lại Xin Chỉ Giáo Nhiều Hơn', 'The Oath Of Love', 'https://phimimg.com/upload/vod/20240709-1/f7b8040216c430c0251913ce0b0704aa.jpg', 'https://phimimg.com/upload/vod/20240709-1/dfe18d6e8301466a52f8f6d91688d222.jpg', '<p>Phim xoay quanh câu chuyện Lâm Chi Hiệu - sinh viên năm 4 trước khi tốt nghiệp đại học đã vấp phải những khó khăn nhất của đời người khi cha mắc bệnh nằm viện, không thể từ bỏ cơ hội làm việc ở nước ngoài, lại phải chia tay với bạn trai. Tất cả những những sự tốt đẹp của tình yêu và cuộc sống tương lai đều bị hủy hoại hết vào thời khắc này. Nhưng trùng hợp thay, Cố Ngụy - bác sĩ của bệnh viện mà cha Lâm Chi Hiệu ở đã bước vào cuộc sống của cô. Hai người họ từng chịu vết thương trong chuyện tình cảm nên không còn tin tưởng mấy vào tình yêu. Nhưng cả hai từng bước từng bước từ quen biết đến yêu thương nhau. Từng có hiểu lầm cũng như vấp phải những chuyện không vui, nhưng trong quá trình họ càng ngày càng phát hiện đối phương thực sự là nửa kia đáng phó thác trong quãng đời còn lại của mình.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tiêu Chiến","avatar":""},{"name":"Dương Tử","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324320);
