INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('du-sinh-xin-chi-giao-nhieu-hon-quang-doi-con-lai-xin-chi-giao-nhieu-hon', 'Dư Sinh Xin Chỉ Giáo Nhiều Hơn / Quãng Đời Còn Lại Xin Chỉ Giáo Nhiều Hơn', 'The Oath Of Love', 'dư sinh xin chỉ giáo nhiều hơn / quãng đời còn lại xin chỉ giáo nhiều hơn the oath of love tiêu chiến dương tử ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-em-o-ngay-the-gioi-ket-thuc', 'Cùng Em Ở Ngày Thế Giới Kết Thúc', 'Love You As The World Ends', 'https://phimimg.com/upload/vod/20240709-1/8cd5d93dc30578bc4a04f7cbdd2c35ff.jpg', 'https://phimimg.com/upload/vod/20240709-1/eec91fd53dd04b4c8c449442cbcff121.jpg', '<p>Mamiya Hibiki (Takeuchi Ryoma) là nhân viên bảo dưỡng xe hơi, bạn gái của anh là Ogasawara Kurumi (Nakajo Ayami), hai người hẹn hò từ thời trung học và đang sống chung với nhau. Vào ngày dự định cầu hôn bạn gái, Hibiki bị tai nạn và mắc kẹt trong đường hầm đổ nát suốt 4 ngày. Khi anh thoát ra khỏi đó, thế giới bên ngoài đã thay đổi hoàn toàn, đường phố vắng tanh, giao thông tê liệt, lệnh sơ tán khẩn cấp liên tục được phát ra từ radio. Hibiki nhận ra thành phố đã bị phong tỏa, anh bắt đầu tìm kiếm Kurumi trong tuyệt vọng và được một nhóm người giúp đỡ khi bị tấn công bởi một đám xác sống. Liệu họ có thể trở thành đồng đội cùng nhau sống sót trong thế giới điên rồ này? Liệu Hibiki có tìm được bạn gái của mình?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takeuchi Ryoma","avatar":""},{"name":"Nakajo Ayami","avatar":""},{"name":"Kasamatsu Sho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324320);
