INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meo-hay-cau-nguyen', 'Meo, Hãy Cầu Nguyện', 'Make A Wish', 'https://phimimg.com/upload/vod/20240709-1/c818ffa18532632f68c47d219f147895.jpg', 'https://phimimg.com/upload/vod/20240709-1/b51a132fdc971d99bf858fd83a625e19.jpg', '<p>Meo, hãy cầu nguyện kể về chủ tiệm sách Trì Viêm là một thanh niên dễ tính theo chủ nghĩa độc thân. Anh cứu một con mèo trắng từ dưới xe về, hôm sau tỉnh dậy thấy mèo trắng biến thành một thiếu nữ trẻ trung. Thiếu nữ Tiểu Hưu đến từ quốc gia Mèo ở thế giới song song, cô phải thực hiện một điều ước của người đã cứu mình mới có thể trở về nhà. Nhưng Trì Viêm là một người sống đạm bạc không có mong muốn gì nhiều, con đường báo ơn của thiếu nữ khó khăn muôn trùng. Từ đó, những ngày chung sống đặc sắc và vui vẻ của hai người bắt đầu, nút thắt tồn tại nhiều năm trong lòng Trì Viêm dần dần được Tiểu Hưu hồn nhiên ngây thơ tháo bỏ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nhậm Hựu Luân","avatar":""},{"name":"Cát Hâm Di","avatar":""},{"name":"Trần Hạo Lam","avatar":""},{"name":"Wang Tian Yu","avatar":""},{"name":"Shiu Hung Hui","avatar":""},{"name":"Wang Ying Ying","avatar":""},{"name":"Zhang He Hao Zhen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324320);
