INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-menh-winx-saga', 'Định Mệnh: Winx Saga', 'Fate: The Winx Saga', 'https://phimimg.com/upload/vod/20240709-1/68d4a71ef48ff62742fac3de14506154.jpg', 'https://phimimg.com/upload/vod/20240709-1/674575d5f2d6000bbe6a5d3d0e488dd1.jpg', '<p>Quyết tâm làm chủ sức mạnh bùa phép của mình, một nhóm thanh thiếu niên xoay xở với sự ganh đua, tình yêu và các bài học siêu nhiên tại trường nội trú phép thuật Alfea.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Abigail Cowen","avatar":""},{"name":"Hannah Van Der Westhuysen","avatar":""},{"name":"Precious Mustapha","avatar":""},{"name":"Eliot Salt","avatar":""},{"name":"Elisha Applebaum","avatar":""},{"name":"Danny Griffin","avatar":""},{"name":"Sadie Soverall","avatar":""},{"name":"Freddie Thorp","avatar":""},{"name":"Rob James-Collier","avatar":""},{"name":"Eve Best","avatar":""},{"name":"Lesley Sharp","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324320);
