INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-kiep-may-man-gap-duoc-em', 'Ba Kiếp May Mắn Gặp Được Em', 'Lucky With You', 'https://phimimg.com/upload/vod/20240709-1/68766180591e6d4b42efa7a71b29dce0.jpg', 'https://phimimg.com/upload/vod/20240709-1/1eb577b49eccad3328de47d849cf1d03.jpg', '<p>Ngũ Thập Nhất, một nữ vệ sĩ, từng là vận động viên Kick Boxing, vô tình phát hiện bạn trai ngoại tình. Trong quá trình làm việc, cô được phân công đảm bảo an toàn tính mạng cho con trai Chủ tịch công ty kiến trúc Chí Vinh, Hầu Tước. Sau khi trải qua nhiều nguy hiểm, họ ngày càng xích lại gần nhau và nảy sinh tình cảm.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Hoàng Cảnh Du","avatar":""},{"name":"Vương Lệ Khôn","avatar":""},{"name":"Vương Sách","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324320);
