INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-trai-cua-su-that', 'Mặt Trái Của Sự Thật', 'Undercover', 'https://phimimg.com/upload/vod/20240709-1/f4ea4120413020db040f65959ca38446.jpg', 'https://phimimg.com/upload/vod/20240709-1/e1bc489ff65035ff75f1b896b3364087.jpg', '<p>Han Jung-Hyun (ji Jin-Hee) là một đặc vụ tài năng, vô cùng thông minh và dũng cảm. Anh đã được Cục Tình báo Quốc gia tuyển dụng khi anh còn đang học tại Đại học Cảnh sát quốc gia. Trong quá trình làm việc bí mật, anh đã tình cờ gặp gỡ, yêu và kết hôn với Choi Yeon-Su (Do Kim Hyun Joo đảm nhận) - một nữ luật sư luôn bảo vệ công lý và sự thật. Sau những ngày hôn nhân yên bình, Yeon-Su đã được đề cử làm giám đốc đầu tiên của cuộc đấu trang tham nhũng. Trong dự án này, cô đối mặt với sự thật gây sốc của Jung Hyun mà anh đã đang che giấu rất nhiều năm.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ji Jin Hee","avatar":""},{"name":"Kim Hyun Joo","avatar":""},{"name":"Han Sun Hwa","avatar":""},{"name":"Yeon Woo Jin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324320);
