INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-nui-jiri-jirisan', 'Bí Ẩn Núi Jiri (Jirisan)', 'Jirisan', 'https://phimimg.com/upload/vod/20240709-1/03d479d5f782603b88b44bff7d20b6be.jpg', 'https://phimimg.com/upload/vod/20240709-1/608b5292123c5da150b904d24c47aebf.jpg', '<p>Bộ phim Hàn Quốc “Bí Ẩn Núi Jiri” (2021) do Jun Ji Hyun (“Vì Sao Đưa Anh Tới”, “Huyền Thoại Biển Xanh”) và Joo Ji Hoon (“Vương Triều Xác Sống”, “Hoàng Cung”) diễn chính, đạo diễn Lee Eung Bok (“Yêu Tinh”, “Hậu Duệ Mặt Trời”) và biên kịch Kim Eun Hee (“Vương Triều Xác Sống”) hợp tác sản xuất, đây là bộ phim dài tập cuối tuần trong kế hoạch đặc biệt kỷ niệm 15 năm phát sóng từ ngày 23 tháng 10 năm 2021 của đài tvN Hàn Quốc, phim này sẽ do kênh iQIYI Quốc tế phát sóng độc quyền. Bí Ẩn Núi Jiri (Jirisan) kể về quá trình kiểm lâm Kang Hyun Jo (Joo Ji Hoon đóng) của Vườn quốc gia núi Jiri phát hiện mình nhìn thấy các hồn ma qua đời vì gặp nạn trên núi, vì thế đã cùng tiền bối Seo Yi Kang (Jun Ji Hyun đóng) bắt tay giải đáp những câu chuyện chưa biết này.\n\nNữ chính Seo Yi Kang là kiểm lâm giỏi nhất của Vườn quốc gia núi Jiri. Nam chính Kang Hyun Jo tích cực cầu tiến, yêu cuộc sống, là cộng sự làm việc của Seo Yi Kang. Dù là đường đất, vách đá hay vách núi, Seo Yi Kang đều biết cách vượt qua như bản năng, chỉ cần một chiếc lá trên ba lô người gặp nạn là phán đoán được địa điểm gặp nạn, hơn nữa còn cực kỳ thông thuộc về khí hậu, thảm thực vật, tính chất đất đai. Tuy bị đồng nghiệp gọi là “Thần rừng”, “Seo ác quỷ”, nhưng Seo Yi Kang say mê công tác cứu nạn hơn bất cứ ai, đó là vì nguyện vọng của cô, giành giật thời gian với thần chết, cứu giúp người gặp nạn. Kang Hyun Jo, đại úy lục quân đương nhiệm gặp tai nạn lúc hành quân huấn luyện trong núi Jiri, chiến hữu vì thế mà bỏ mình. Sau này, anh ấy bắt đầu nhìn thấy hồn ma của những người gặp nạn trong núi Jiri. Kang Hyun Ho cho rằng đây là món quà cứu giúp con người của ngọn núi, vì thế anh ấy trở về núi Jiri, cùng nhau cứu giúp người gặp nạn với tư cách là cộng sự của Seo Yi Kang. Dần đần, bí mật đáng sợ ẩn giấu đằng sau ngọn núi Jiri xinh đẹp cũng từ từ hé lộ…</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Gianna Jun","avatar":""},{"name":"Ju Ji-hoon","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Oh Jung-se","avatar":""},{"name":"Cho Han-cheul","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324320);
