INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-kich-chon-thuong-luu', 'Thảm Kịch Chốn Thượng Lưu', 'The Road: Tragedy Of One', 'https://phimimg.com/upload/vod/20240709-1/e0f1df4976259bf633f1a81621a86f12.jpg', 'https://phimimg.com/upload/vod/20240709-1/3b432e47dc534a6464b2c2d85980da07.jpg', '<p>Thảm Kịch Chốn Thượng Lưu - The Road: Tragedy of One là bộ phim mới nhất về xã hội thượng lưu với sự tham gia của Ji Jin Hee, Yoon Se Ah và Kim Hye Eun. Bộ phim tập trung vào cuộc sống bí ẩn, tham vọng và sự xấu hổ của những cư dân sống trong dinh thự biệt lập Royal the Hill. Trong số cư dân có Baek Soo Hyun (Ji Jin Hee), nhà báo nổi tiếng, được kính trọng nhưng bản chất tàn nhẫn, lạnh lùng và khó đoán. Soo Hyun kết hôn với Seo Eun Soo (Yoon Se Ah), con gái của giám đốc điều hành công ty quyền lực. Ngoài ra là Cha Seo Young (Kim Hye Eun), phát thanh viên truyền hình xinh đẹp, có nền tảng giáo dục tốt nhưng không bao giờ hài lòng với cuộc sống của mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 10, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ji Jin Hee","avatar":""},{"name":"Kim Hye Eun","avatar":""},{"name":"Yoon Se Ah","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324320);
