INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-trong-dai-phan-2', 'Ngày Trọng Đại (Phần 2)', 'The Big Day (Season 2)', 'https://phimimg.com/upload/vod/20240709-1/6f3f9654281d4c57b01776d83361f938.jpg', 'https://phimimg.com/upload/vod/20240709-1/6b0f0a44b71f5b486714ace76143ffc8.jpg', '<p>Có phong tục lâu đời kết hợp với những giá trị đương đại – và tất nhiên là cả trang phục cao cấp – trong chương trình tôn vinh sáu đám cưới Ấn Độ hoành tráng này.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 9, 2021, 'Vietsub', 'HD', 'Ấn Độ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324320);
