INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cac-te-bao-cua-yumi', 'Các Tế Bào Của Yumi', 'Yumi''s Cells', 'https://phimimg.com/upload/vod/20240709-1/556a0bdd6444ab365b051eef42f13b05.jpg', 'https://phimimg.com/upload/vod/20240709-1/d1ba88bdaefa5bba818ad363d0ca1e08.jpg', '<p>“Các Tế Bào Của Yumi” là bộ phim đầu tiên kết hợp giữa truyện tranh và người thật của Hàn Quốc, cải biên từ bộ truyện tranh nổi tiếng cùng tên tại Hàn Quốc “Các Tế Bào Của Yumi”. Kim Go Eun (Goblin) đóng vai nữ chính Yumi, là một cô gái bình dị nơi công sở không giỏi thể hiện tình cảm. Ahn Bo Hyun (Itaewon Class) đóng vai nam chính Ku Woong, Lee Yu Bi đóng vai đồng nghiệp dịu dàng Ruby, thành viên GOT7 Park Jin Young đóng vai Yoo Ba-bi. Ngoài ra thành viên của Shinee Min Ho cũng đặc biệt tham gia diễn xuất.\nYumi 31 tuổi là một cô gái bình thường sống ở Seoul, làm nhân viên kế toán ở một công ty mỳ sợi. Cuộc sống của cô vô cùng đơn điệu, không hề có gợn sóng. Nhưng mà, Ku Woong lại xông vào thế giới yên bình của Yumi, khiến các tế bào trong người cô hoàn toàn trở nên hỗn loạn. Mọt sách Ku Woong là người bắt đầu trò chơi, là một anh chàng đẹp trai trông bề ngoài như một người rất hướng nội, lạnh lùng với tất cả mọi chuyện, trên thực tế lại là một chàng trai vô cùng thuần khiết. Yumi bị sự hài hước và đơ thuần của Ku Woong thu hút, “tế bào tình yêu” của hai người mở lòng với nhau, một câu chuyện tình yêu ngọt ngào cứ thế bắt đầu.\n“Các Tế Bào Của Yumi” do đạo diễn Lee Sang-yeobcủa “Người Vợ Thân Quen”, “Em là một nửa đời anh” và biên kịch Song Jae-jeong của “W- Hai Thế giới” và “Ký ức Alhambra” cùng biên kịch Kim Yoon-joocủa “Tìm Em Trong Hồi Ức”cùng hợp tác tạp nên. “Các Tế Bào Của Yumi”xoay quanh cuộc sống của nữ chính Yumi tại thành phố, thông qua các tế bào não của nhân vật chính Yumi, miêu cả công việc, tình yêu, mơ ước của người nhân viên bình thường tuổi 30, từ đó thu hút sự cộng hưởng của mỗi một người sống tại nơi đô thị.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Jin-young","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324320);
