INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-lac', 'Thanh Lạc', 'Qing Luo', 'https://phimimg.com/upload/vod/20240709-1/3567de5d55448e29b884237259e6e652.jpg', 'https://phimimg.com/upload/vod/20240709-1/9d7217f60ea17f7346d88c083811b89e.jpg', '<p>Vì một biến cố mà nữ thần y Ngọc Thanh Lạc mang thai nhưng lại không rõ cha đứa bé là ai. Bảy năm sau, trong quá trình đưa con trai đi tìm cha, Thanh Lạc vô tình gặp Dạ Tu Độc - vị hoàng tử của Phong Thương Quốc. Chỉ vì chàng mang tướng mạo giống với kẻ thù Dương Tu Thành nên Thanh Lạc không hề có thiện cảm tốt. Tuy nhiên, Dạ Tu Độc và mẹ con nàng dường như có một mối liên kết nào đó.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Học Nghĩa","avatar":""},{"name":"Vương Tử Vi","avatar":""},{"name":"Đại Tư","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324320);
