INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-ho-chuyen-ve-doc-antle', 'Vua Hổ: Chuyện Về Doc Antle', 'Tiger King: The Doc Antle Story', 'https://phimimg.com/upload/vod/20240709-1/c649b65e08511812d150ef32620a7b1a.jpg', 'https://phimimg.com/upload/vod/20240709-1/eecf694b161ac1354e2f78bff5457059.jpg', '<p>Loạt phim tài liệu về Vua hổ này kể chi tiết những cáo buộc đáng ngại về hành vi xâm hại tình dục, bạo lực và sai trái của chủ sở thú nuôi mèo lớn Bhagavan “Doc” Antle.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324320);
