INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-rat-my-vi', 'Yêu Rất Mỹ Vị', 'Delicious Romance', 'https://phimimg.com/upload/vod/20240709-1/f0257ab223e28ea39536326bb249c0cb.jpg', 'https://phimimg.com/upload/vod/20240709-1/79e0b779e85bd24ce334bdb1e9f575ee.jpg', '<p>Ba người đẹp đô thị xinh đẹp rạng ngời cá tính khác nhau, trải qua một loạt gian khổ gây dựng sự nghiệp, áp lực nơi công sở và trắc trở trong tình cảm đều có nhận thức mới về cuộc sống, sự nghiệp và tình yêu. Trong đó, Lưu Tịnh là blogger ẩm thực kén chọn trong tình yêu; Phương Hân là chủ vlog ly dị vẻ ngoài xuất chúng nhưng cứ khổ não vì tình; Hạ Mộng nữ cường nhân vì quá xuất sắc mà khiến bạn trai cảm thấy áp lực. Mỗi một cái mác rực rỡ đều phản ánh quan hệ thân mật của nam nữ hiện tại ở các mức độ khác nhau.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"LiChun","avatar":""},{"name":"Zhang Hanyun","avatar":""},{"name":"WangJu","avatar":""},{"name":"ZhouChengao","avatar":""},{"name":"Liu Dongqin","avatar":""},{"name":"Ren Bin","avatar":""},{"name":"Zhang Fan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324320);
