INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-met-phia-tren-bau-troi-phan-2', 'Ba Mét Phía Trên Bầu Trời (Phần 2)', 'Summertime (Season 2)', 'https://phimimg.com/upload/vod/20240709-1/93290b9949b05d75a5725c3b4608bfa5.jpg', 'https://phimimg.com/upload/vod/20240709-1/667b39790c39c10f397f190389a1c793.jpg', '<p>Ba Mét Phía Trên Bầu Trời (Phần 2) kể về một mùa hè nữa lại đến. Trong khi nhiều mối quan hệ đã thay đổi suốt năm qua, hội bạn này nhận ra họ khó có thể cưỡng lại một số sự hấp dẫn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rebecca Coco Edogamhe","avatar":""},{"name":"Ludovico Tersigni","avatar":""},{"name":"Amanda Campana","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324320);
