INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cua-hang-tap-hoa-phep-thuat', 'Cửa Hàng Tạp Hoá Phép Thuật', 'Magic Grocery Store', 'https://phimimg.com/upload/vod/20240709-1/afcd40b8c5af6c3625348baf6a0b89e8.jpg', 'https://phimimg.com/upload/vod/20240709-1/6d189f0fd409c48ade026bb5acc516aa.jpg', '<p>Trong một cuộc thi viết kịch bản giả tưởng, nhà biên kịch đã tạo ra một kẻ bắt quái vật hạng hai Xiaotian ở cuối con hạc, anh ta gặp được yêu quái mèo Xiaoqi tốt bụng và đáng yêu và con ma đẹp trai Jincheng đang tìm vợ, mặc dù họ có mục tiêu riêng , họ đã làm việc cùng nhau để tìm cơ hội để làm những điều tốt đẹp. , một câu chuyện giả tưởng về việc giúp Xiao Qicheng trở thành một nàng tiên. Sau khi ba người họ hợp tác với nhau, tuân thủ nguyên tắc tốt không tìm thấy, xấu tự tìm đến, cửa hàng ma thuật chính thức khai trương. Cả ba đã thiết lập một tình bạn sâu sắc trong việc giải quyết các vấn đề khác nhau, đồng thời thể hiện tình yêu đích thực và sự ấm áp trên thế giới trong một loạt câu chuyện vui nhộn về việc giúp đỡ người khác, đồng thời hoàn thành quá trình trưởng thành và biến đổi của cả ba.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Triệu Thanh","avatar":""},{"name":"Ngô Địch Phi","avatar":""},{"name":"Vương Gia Mông","avatar":""},{"name":"Miêu Kinh Câu","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324320);
