INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dear-m', 'Dear. M', 'Dear. M', 'https://phimimg.com/upload/vod/20240709-1/ea27133b446c7a8fa910706144291ecc.jpg', 'https://phimimg.com/upload/vod/20240709-1/8ecbe4511367672cc047fa640cc5fac2.jpg', '<p>“Dear.M” sẽ đề cập câu chuyện về cuộc tìm kiếmbí hiểm “M” trong khuôn viên trường, 1 cá nhân được đề cập trong một bài đăng ẩn danh trên cộng đồng trực tuyến của Đại học Seoyeon. Bộ phim tình cảm lãng mạn thực tiễn sẽ theo dõi các mối quan hệ đang đổi thay và những mối tình lãng mạn chớm nở giữa những nhân vật khác nhau trong bối cảnh hầu hếtnhững lời bàn tán về “M.”Ma Joo-A là sinh viên năm 2 khoa Quản trị Kinh doanh tại Đại học Seoyeon. Cô ấycómột trái tim ấm ápvà tính phương pháp tươi sáng. Cô đấykhôngưa chuộngtới việc đeo đuổi giấc mơ hay sở hữumột mối quan hệ lãng mạn. Cô đấy chưa từng sở hữu bạn trai trước đây.Cha Min-Ho là sinh viên năm 2 Khoa Khoa học Máy tính tại Đại học Seoyeon. Anh ấyvới tài vững mạnháp dụngvớicác ý tưởng sáng tạo. Anh đó đã là bạn mang Ma Joo-A trong 12 năm.Seo Ji-Min là sinh viên khoa Kinh tế tại Đại học Seoyeon. Cô cũng là thành viên của đội khích lệ trường học.Park Ha-Neul là sinh viên khoa Quản trị Kinh doanh tại Đại học Seoyeon và anh là đại sứ danh dự của trường.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 18, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Piao Hui Xiu","avatar":""},{"name":"JaeHyun","avatar":""},{"name":"Jeong-eui Roh","avatar":""},{"name":"Pei Xian Sheng","avatar":""},{"name":"Lee Jin Hyuk","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324320);
