INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-phu-thuy-quyet-dau', 'Thiếu Nữ Phù Thủy Quyết Đấu', 'The Great Shaman Ga Doo Shim', 'https://phimimg.com/upload/vod/20240709-1/031ac47c5c399d38bdd953b77fcacf49.jpg', 'https://phimimg.com/upload/vod/20240709-1/ce6e6bb2246d417f85edd94c78dbf11b.jpg', '<p>Thiếu Nữ Phù Thủy Quyết Đấu (Great Shaman Ga Doo Shim 2021) là bộ phim truyền hình Hàn Quốc kể về câu chuyện tình lãng mạn nhưng cũng đầy bí ẩn của hai học sinh trung học độc nhất vô nhị, họ tham gia vào hàng loạt các sự cố bí ẩn trong các căn nhà bị ma ám. Chuyện bắt đầu từ hai học sinh trung học Na Woo Soo và Ga Doo Shim. Trong đó Na Woo Soo (Nam Da Reum thủ vai) thiếu gia của một gia đình giàu có, vẻ ngoài điển trai và có kết quả học tập đáng ngưỡng mộ. Bản thân anh có khả năng nhìn thấy những linh hồn ma quỷ nhưng anh không nhận ra điều đó, chỉ đến khi nữ sinh Ga Doo Shim xuất hiện trong cuộc đời của anh.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 21, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Sae-ron","avatar":""},{"name":"Nam Da-reum","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324320);
