INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-vo-bat-buoc', 'Cô Vợ Bắt Buộc', 'Mia Jum Pen', 'https://phimimg.com/upload/vod/20240709-1/bdeeeb3abaca73e758c462b43d80c64d.jpg', 'https://phimimg.com/upload/vod/20240709-1/0f63bc9535ff810238cc1627ddb468e8.jpg', '<p>Cô Vợ Bắt Buộc (Mia Jum Pen) được FPT PLAY độc quyền phát song song với Thái Lan và được cập nhật vào tối Thứ 6, Thứ 7 và Chủ nhật hàng tuần.Cô Vợ Bắt Buộc xoay quanh mối tình cưới trước yêu sau của nàng lọ lem Tawan và chàng trai thừa kế Tomorn. Tawan (Pie Rinrada) đang sống và làm người giúp việc cho Yuanjai và Yadfah, con gái của Yuanjai. Yadfah được cha mình là ông Yod hứa hôn cho Tomorn (Mai Warit), con trai của người bạn thân của mình. Yadfah không muốn kết hôn với Tomorn vì nghĩ rằng anh là kẻ nhà quê nghèo mạt, hơn nữa Yadfah cũng đang chung sống như vợ chồng với người đàn ông khác. Cho nên Yuanjai và Yadfah đã để Tawan thay Yadfah kết hôn với Tomorn. Cả hai dần có tình cảm với nhau nhưng Tawan vẫn luôn dằn vặt vì đã lừa dối người mình yêu. Bên cạnh đó, cô luôn bị bắt nạt và hãm hại với các cô gái trà xanh xung quanh Tomorn. Mối quan hệ của Tawan và Tomorn sẽ ra sao khi Yadfah biết được thân phận giàu có của Tomorn và tìm cách ép buộc Tomorn ly dị với Tawan?</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 7, 2021, 'Thuyết Minh', 'HD', 'Thái Lan', 0, '[{"name":"Mai Warit Sirisantana","avatar":""},{"name":"Pie Rinrada Kaewbuasai","avatar":""},{"name":"Pear Pitchapa Phanthumchinda","avatar":""},{"name":"Best Chanidapa Pongsilpipat","avatar":""},{"name":"Mind Waratthaya Wongchayaporn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324320);
