INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tap-doan-hac-am-o-me-cung', 'Tập Đoàn Hắc Ám Ở Mê Cung', 'The Dungeon Of Black Company Mekyu Black Company', 'https://phimimg.com/upload/vod/20240709-1/8c723ccdce1b4722bded31175be5df38.jpg', 'https://phimimg.com/upload/vod/20240709-1/ce600161da5f438d4b2c59e8d75b497a.jpg', '<p>Kinji - người không có đạo đức trong công việc ở cuộc sống hiện đại. Một ngày nọ, anh thấy mình được đưa đến một thế giới khác và bị đẩy vào công việc tồi tệ. Kinji thực sự sẽ học được ý nghĩa của làm việc chăm chỉ?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 4, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324320);
