INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-qua-bong-toi', 'Vượt Qua Bóng Tối', 'Break Through the Darkness', 'https://phimimg.com/upload/vod/20231101-1/a1301f4ead044f91379a28e6268e19fd.jpg', 'https://phimimg.com/upload/vod/20231101-1/01c3c12e9f744fd6b8747586540072f3.jpg', '<p>Đội trưởng đội điều tra tội phạm xã hội đen Tống Nhất Duệ dẫn dắt thành viên trong đội cùng nhau dấn thân phá án, triệt phá mọi chướng ngại, chiến đấu không khoan nhượng với thế lực đen tối ẩn mình phía sau, cuối cùng vạch mặt đám quan tham hủ bại lợi dụng chức quyền để phạm tội, đưa bọn tội phạm ra trước công lý.</p>', 'Full', 1, 'single', 'completed', 4, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jiang Wu","avatar":""},{"name":"Zhang Songwen","avatar":""},{"name":"Jin Shijia","avatar":""},{"name":"Li Qian","avatar":""},{"name":"Zhao Yi","avatar":""},{"name":"Yong You","avatar":""},{"name":"Liu Lin","avatar":""},{"name":"Dong Borui","avatar":""},{"name":"Bai Zhidi","avatar":""},{"name":"Wang Liyun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324320);
