INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('castlevania-phan-4', 'Castlevania (Phần 4)', 'Castlevania (Season 4)', 'https://phimimg.com/upload/vod/20240709-1/51727eb995212abb7bf41c5fb97c3561.jpg', 'https://phimimg.com/upload/vod/20240709-1/69dd2ad3f9e1b0761671a9cff5b36804.jpg', '<p>Ảnh hưởng của Dracula ngày càng lớn khi Belmont và Sypha điều tra âm mưu hồi sinh ma cà rồng khét tiếng. Alucard cố gắng đón nhận phần nhân tính trong mình.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Richard Armitage","avatar":""},{"name":"James Callis","avatar":""},{"name":"Alejandra Reynoso","avatar":""},{"name":"Jessica Brown Findlay","avatar":""},{"name":"Fukushima Rila","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Theo James","avatar":""},{"name":"Yasmine Al Massri","avatar":""},{"name":"Adetokumboh M''Cormack","avatar":""},{"name":"Ivana Milicevic","avatar":""},{"name":"Jaime Murray","avatar":""},{"name":"Navid Negahban","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Uchikado Toru","avatar":""},{"name":"Gild","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324320);
