INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-thien-long-bat-bo-2021', 'Tân Thiên Long Bát Bộ 2021', 'Demi-Gods And Semi-Devils', 'https://phimimg.com/upload/vod/20240709-1/2a3a79044e86846e99967f83e66a5680.jpg', 'https://phimimg.com/upload/vod/20240709-1/7ccc636d4bc7d6caf6e0d45bf014e631.jpg', '<p>Tân Thiên Long Bát Bộ 2021 là bản làm lại (remake) từ tiểu thuyết kinh điển cùng tên của nhà văn Kim Dung. Bộ phim kiếm võ hiệp xoay quanh các nhân vật của lãnh thổ 5 quốc gia là Tống, Liêu, Đại Lý, Tây Hạ, Thổ Phồn. Câu chuyện về cuộc đời, tình yêu và những biến cố kinh thiên động địa trong cuộc đời ba nhân vật chính, ba chàng trai tài giỏi, đầy cá tính là: Kiều Phong (Dương Hựu Ninh), Đoàn Dự (Bạch Chú) và Hư Trúc (Trương Thiên Dương).</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 15, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Dương Hựu Ninh","avatar":""},{"name":"Văn Vịnh San","avatar":""},{"name":"Bạch Chú","avatar":""},{"name":"Trương Thiên Dương","avatar":""},{"name":"Tô Thanh","avatar":""},{"name":"Hà Hoằng San","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324320);
