INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('her-bucket-list', 'Her Bucket List', 'Her Bucket List', 'https://phimimg.com/upload/vod/20240709-1/42cf462103079ceb63d33417b9d90400.jpg', 'https://phimimg.com/upload/vod/20240709-1/31576e4a6c3f85de85be884795c496f9.jpg', '<p>Bạn trai đột nhiên mất liên lạc, và “Cha Ra Ri” sau khi nhận được tin bạn trai mất, đã quyết định tự tử để đi theo người yêu. Nhưng vì sợ hãi cái chết nên trong lòng cô đã không ngừng đấu tranh, và không thể kết thúc cuộc đời mình. Trong lúc chán nản, cô bất ngờ phát hiện ra “Danh Mục Di Nguyện” mà cô ấy đã viết cùng với bạn trai. Rồi tình cờ cô gặp được thực tập sinh thần tượng “Kang Han Sol”, một thực tập sinh rất có thực lực nhưng lại mắc chứng sợ sân khấu. Cha Ra Ri và Kang Han Sol lần lượt thực hiện các ước nguyện trong danh mục di nguyện, và trong quá trình cùng nhau chữa lành vết thương, đôi bên đã nảy sinh tình cảm với nhau...</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kim So Hye","avatar":""},{"name":"Na Jong Chan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324320);
