INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('firefly-lane', 'Firefly Lane', 'Firefly Lane', 'https://phimimg.com/upload/vod/20240709-1/26fe7df975b50c6021a229cb9938e601.jpg', 'https://phimimg.com/upload/vod/20240709-1/1d425fae7e7ce6129982f54ccd7319e5.jpg', '<p>Hai người bạn thân Tully và Kate hỗ trợ nhau vượt qua những giai đoạn thăng trầm với sự gắn kết không thể phá vỡ đã theo họ từ tuổi thiếu niên đến tuổi 40.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Katherine Heigl","avatar":""},{"name":"Sarah Chalke","avatar":""},{"name":"Ben Lawson","avatar":""},{"name":"Beau Garrett","avatar":""},{"name":"Ali Skovbye","avatar":""},{"name":"Roan Curtis","avatar":""},{"name":"Yael Yurman","avatar":""},{"name":"Jon-Michael Ecker","avatar":""},{"name":"Brandon Jay McLaren","avatar":""},{"name":"Paul McGillion","avatar":""},{"name":"Chelah Horsdal","avatar":""},{"name":"Brendan Taylor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324320);
