INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-ca-rong-lap-tuc-di-chet', 'Ma Cà Rồng, Lập Tức Đi Chết', 'The Vampire Dies In No Time', 'https://phimimg.com/upload/vod/20240709-1/3404f83ae821916316801fa7bdf46c16.jpg', 'https://phimimg.com/upload/vod/20240709-1/65f255e4224924fe09b2081deb967716.jpg', '<p>Một ngôi thành lũy nằm ở vùng ngoại ô dân cư thưa thớt. Nơi này là địa bàn của Doraruku, một quỷ hút máu bất tử và khiến người sợ sệt cực. Nhằm cứu vớt đứa trẻ lạc đường vào thành lũy đó, người đuổi quỷ anh dũng đứng ra, tự mình sang thành lũy của Doraruku. Nhưng mà điều khiến anh ấy rất bất ngờ là Doraruku vô địch trong truyền thuyết chỉ là một quỷ hút máu thường biến thành bụi đất, yếu nhất trong lịch sử.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324320);
