INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuc-bien-tau-anh-trang', 'Khúc Biến Tấu Ánh Trăng', 'Moonlight', 'https://phimimg.com/upload/vod/20240709-1/da067769ab4f2a2710806abdf74966b9.jpg', 'https://phimimg.com/upload/vod/20240709-1/d5c4d1950e528f517b74c5b2ac4a0398.jpg', '<p>Trú Xuyên – một “đại thần” mới nổi, luôn nói rằng biên tập thời đại Internet đã chết, không ngờ lại gặp Sơ Lễ – một biên tập viên tay mơ của tòa soạn Nguyên Nguyệt. Cô nhóc này không chỉ oán trời trách đất, đấu khẩu với đại thần, mà Trú Xuyên còn phát hiện cô lại là Hầu Tử Quân – người bạn trên mạng lâu năm của mình. Fan sách của Trú Xuyên gọi anh là Xuyên công tử dịu dàng như ngọc, nhưng qua lời Sơ Lễ anh lại trở thành “bậc thầy diễn trò” sống hai mặt.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yu Shuxin","avatar":""},{"name":"Ding Yuxi","avatar":""},{"name":"Yang Shize","avatar":""},{"name":"Ma Yinyin","avatar":""},{"name":"Wang Ting","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324320);
