INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-am-thanh-co-ky-uc', 'Nếu Âm Thanh Có Ký Ức', 'If The Voice Has Memory', 'https://phimimg.com/upload/vod/20240709-1/b561a7549ef61149b3af9615a93c198e.jpg', 'https://phimimg.com/upload/vod/20240709-1/53871b0691783eece67273d005caa01c.jpg', '<p>Du Lộc Ly, luôn có ước mơ trở thành một diễn viên lồng tiếng chuyên nghiệp, tình cờ phát hiện ra Lâm Nam – sếp của mình, hóa ra lại là thần tượng lồng tiếng Mạch Đại. Lộc Hy theo bái Lâm Nam làm thầy, cả hai cùng song hành trong thế giới của âm thanh. Với sự tiến bộ không ngừng của Du Lộc Hy, họ dần khám phá ra những bí mật mà lúc đó Lâm Nam không hề biết.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ngụy Triết Minh","avatar":""},{"name":"Phan Mỹ Diệp","avatar":""},{"name":"Tống Phương Nghiên","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324320);
