INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-vo-than-quyet', 'Tinh Võ Thần Quyết', 'Astral Sutra', 'https://phimimg.com/upload/vod/20240709-1/a5f0f92a6fabafc9a70225c3234c07f2.jpg', 'https://phimimg.com/upload/vod/20240709-1/620accee62896c85b98fc7e759071887.jpg', '<p>Phim kể về con đường tu luyện của Diệp Tinh Hà. Một con đường của kẻ mạnh chống lại ý trời, với hồng nhan tri kỷ ở bên, kế thừa Tu Tinh Võ, uy quyền khắp nơi, trở thành thần vương tối cao. Thiếu nữ thiên tài đáng yêu dịu dàng, quận chúa nóng bỏng phóng khoáng, mỹ nữ yêu tộc bí ẩn, còn có nữ võ thần tối cao trong truyền thuyết.</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 15, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324320);
