INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghi-ngo-hop-ly-cau-chuyen-ve-hai-vu-bat-coc', 'Nghi Ngờ Hợp Lý: Câu Chuyện Về Hai Vụ Bắt Cóc', 'Reasonable Doubt: A Tale Of Two Kidnappings', 'https://phimimg.com/upload/vod/20240709-1/3b58975285e932920bda8efa2f70e436.jpg', 'https://phimimg.com/upload/vod/20240709-1/2aa85bf513b6cfdccc2b7b0f5eb1bd87.jpg', '<p>Một vụ va chạm xe nhỏ hóa vụ bắt cóc đã khiến chuyên viên hồ sơ Roberto Hernández ra tay vạch trần sự thật đằng sau hệ thống tư pháp đầy khiếm khuyết của Mexico.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 16, 2021, 'Vietsub', 'HD', 'Mexico', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324320);
