INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-chi-ky-phong-nguyet', 'Nhất Chỉ Ký Phong Nguyệt', 'Palace: Devious Women', 'https://phimimg.com/upload/vod/20240709-1/7b2e05d8538f50944e76ac181a80bcc5.jpg', 'https://phimimg.com/upload/vod/20240709-1/943eab46ba64c8b81c614a2d349164fe.jpg', '<p>Phim kể về cô gái trẻ Cao Hân Duyệt là một nhà biên kịch, hiện tại cô đang trong quá trình hoàng thành kịch bản Nhất Chỉ Ký Phong Nguyệt. Thế nhưng, cô lại bị một đồng nghiệp xấu xa thay đổi toàn bộ nội dung trong kịch bản và tự giao nộp cho cấp trên. Trên đường đi đến công ty lấy lại kịch bản thì Cao Hân Duyệt bất ngờ xuyên không vào kịch bản, cô trở thành nhân vật thị thiếp của Tam a Ca Lăng Hoằng. Do kịch bản đã bị đồng nghiệp thay đổi, nên số phận của Cao Hân Duyệt sẽ chịu đựng vô số đau khổ và trắc trở khi gã vào vương phủ. Còn về người hầu Giai Ninh lại trở thành một vị thống lĩnh của vương phủ, sử dụng mọi thủ đoạn đầy tàn ác gây khó khăn cho Cao Hân Duyệt.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chu Nguyên Băng","avatar":""},{"name":"Triệu Gia Mẫn","avatar":""},{"name":"Triệu Tịnh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324320);
