INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoc-ngoat-11-thang-9-va-cuoc-chien-chong-khung-bo', 'Bước Ngoặt: 11 Tháng 9 Và Cuộc Chiến Chống Khủng Bố', 'Turning Point: 9/11 And The War On Terror', 'https://phimimg.com/upload/vod/20240709-1/b766037b12ffd079981bf84964f6ca3f.jpg', 'https://phimimg.com/upload/vod/20240709-1/be3f56d88e6240dde2f390494011a107.jpg', '<p>Loạt phim tài liệu chân thực về vụ tấn công khủng bố ngày 11/9, từ cội nguồn Al Qaeda những năm 1980 cho đến đòn đáp trả của Mỹ ở cả trong nước lẫn nước ngoài.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324320);
