INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-bao-phuc-yeu-luc-phan-2', 'Thiên Bảo Phục Yêu Lục (Phần 2)', 'Tian Bao Fuyao Lu (Season 2)', 'https://phimimg.com/upload/vod/20240709-1/09fc135b8a4c0f4687acb8707683bd3e.jpg', 'https://phimimg.com/upload/vod/20240709-1/d61158df2d1247108cbfb886958298ee.jpg', '<p>Vào năm Thiên Bảo thứ mười hai, thời gian phục sinh của Thiên Ma cũng đang đến gần. Ma vương Giải Ngục có ý định lợi dụng Thiên Ma để thống lĩnh yêu ma, lật đổ nhân gian, biến nhân gian thành vùng đất của yêu quái. Khu Ma Ti của nhân gian đã triệu tập những nhân tài trẻ tuổi trở về Trường An để chuẩn bị cho sự xuất hiện của Thiên Ma sau 4 năm nữa. Tại biên giới, tất cả mọi người của Khu Ma Ti đều tụ họp lại, sau đó phát hiện ra cuộc bạo loạn của những thây ma chết trong chiến tranh. Tất cả những điều này dường như đều liên quan đến Hươu Trắng trong truyền thuyết. Vậy Hươu Trắng ở đâu?</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324320);
