INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-vinh-hang-cung-vang-trang', 'Tình Yêu Vĩnh Hằng Cùng Vầng Trăng', 'Love Under The Moonlight', 'https://phimimg.com/upload/vod/20240709-1/0b002918bd09b995fdc28598508ce160.jpg', 'https://phimimg.com/upload/vod/20240709-1/0580b4c00bb0a7bdafc4a1076253ab51.jpg', '<p>Tình Yêu Vĩnh Hằng Cùng Vầng Trăng (Love Under The Moonlight) vietsub kể về chuyện tình của chàng Thacha (Ken Theeradeth Wongpuapan) bất tử. Hơn 200 năm qua, anh đã chờ đợi tình yêu của đời mình quay trở lại. Sau đó, anh gặp Tongjan (Ice Preechaya Pongthananikorn), người giống hệt tình yêu đầu tiên và duy nhất của mình. Tongjan mang ánh sáng đến với cuộc đời của Thacha. Tình cảm của Thacha dành cho cô vô cùng mãnh liệt. Nhưng làm sao họ có thể ở bên nhau khi Tongjan chỉ là một con người bình thường trong khi Thacha thì không?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Ken Theeradeth Wongpuapan","avatar":""},{"name":"Ice Preechaya Pongthananikorn","avatar":""},{"name":"Wawwa Nicha Chokprajakchat","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324320);
