INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-gap-go-nhung-dieu-ki-la', 'Cô Gái Gặp Gỡ ''Những Điều Kì Lạ''', 'Daisy Meets Girl', 'https://phimimg.com/upload/vod/20240709-1/a6e08240652a97b4571cee2098eb9074.jpg', 'https://phimimg.com/upload/vod/20240709-1/22d3e7c082bc5de8ae861484d789d809.jpg', '<p>Câu chuyện bắt đầu vào một mùa hè khi Maise Higa, một nữ sinh trung học năm nhất bơ phờ với công việc bán thời gian tại quầy lễ tân của khách sạn của gia đình cô ở Okinawa, đã gặp Ichiro Suzuki, một thanh niên bí ẩn đến một mình từ Tokyo. Kể từ khi Suzuki đến, mọi thứ Deji đã xảy ra xung quanh Maise, như cá bơi quanh phòng hay một cây đa khổng lồ đâm xuyên qua trần khách sạn.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324320);
