INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('te-cong-truyen-ky', 'Tế Công Truyền Kỳ', 'Final Destiny', 'https://phimimg.com/upload/vod/20240709-1/24d59e4fa8d0f81e3edf2c56ce108dbb.jpg', 'https://phimimg.com/upload/vod/20240709-1/6e073949f40d2dcf6bf9ef07007d73ea.jpg', '<p>Đại bàng tinh tự ý xuống trần gây họa, Phật Tổ phái sứ giả Hàng Long đuổi theo, thu phục nó. Một cuộc chiến long trời lở đất đã diễn ra, vô tình tạo ra một mối lương duyên đến tận năm trăm năm sau. Ở hiện tại, Lục Thanh Nhi, Võ Dã Quang và nữ bộ khoái Tô Nhu vô tình gặp nhau, hình thành mối tình tay ba đầy vương vấn. Tuy nhiên, yêu ma xuất hiện hoành hành khắp nơi, Dã Quang biết được mình là Hàng Long của quá khứ, nên đã gạt bỏ ái tình, quyết tâm tu hành, lấy pháp danh Đạo Tế để thay trời hành đạo, hoàn thành sứ mệnh mà Phật Tổ đã giao phó.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2021, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Tiêu Chính Nam","avatar":""},{"name":"Thang Văn Lạc","avatar":""},{"name":"Thẩm Chấn Hiên","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324320);
