INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-duong-va-dia-nguc-hoan-doi-linh-hon', 'Thiên Đường Và Địa Ngục: Hoán Đổi Linh Hồn', 'Heaven And Hell: Soul Exchange', 'https://phimimg.com/upload/vod/20240709-1/85bcc0d02393d2919774c3641fb0d1ea.jpg', 'https://phimimg.com/upload/vod/20240709-1/c7e965635921e6006566fbd81ea25b34.jpg', '<p>Khi linh hồn của cô bị tráo đổi một cách bí ẩn với linh hồn của kẻ tâm thần giết người hàng loạt, nữ thanh tra đầy tham vọng ở Tokyo chứng kiến số phận của cô thay đổi.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 4, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ayase Haruka","avatar":""},{"name":"Takahashi Issey","avatar":""},{"name":"Emoto Tasuku","avatar":""},{"name":"Mizobata Junpei","avatar":""},{"name":"Nakamura Yuri","avatar":""},{"name":"Kitamura Kazuki","avatar":""},{"name":"Sakoda Takaya","avatar":""},{"name":"Hayashi Yasufumi","avatar":""},{"name":"Nomaguchi Toru","avatar":""},{"name":"Yoshimi Kazutoyo","avatar":""},{"name":"Baba Toru","avatar":""},{"name":"Kyosuke Tani","avatar":""},{"name":"Kishii Yukino","avatar":""},{"name":"Kiba Katsumi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324321);
