INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('7-project', '7 Project', '7 Project', 'https://phimimg.com/upload/vod/20240709-1/fddb22c5c736b2e0ad88721e168a3afa.jpg', 'https://phimimg.com/upload/vod/20240709-1/d11325d90548f3066eb8238eb3c58f37.jpg', '<p>7 Project là bộ series phim Thái Lan bao gồm 7 câu chuyện, 7 chủ đề nội dung đến từ Studio Wabi Sabi, với sự quy tụ của dàn diễn viên Thái Lan trẻ được yêu thích như Plan, Art, Boun, Prem, Peak, Boom, Santa, Earth, Soodyacht, và Sammy. Tên của 7 tập phim trong 7 Project là: Ngọt Ngào Tuổi Mới Lớn (50% My Puppy Love), Tình Yêu Đối Đầu (VS LOVE), Gương Vỡ Lại Lành (Breakup Zone), Nhịp Điệu Trái Tim (Rhythm’s Heart), Hồi Ức (Remember), Góc Khuất Tình Yêu (Once Upon A Time), Làm Người Yêu Anh Nhé (Would You Be My Love?).</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 16, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Earth Katsamonnat Namwirote","avatar":""},{"name":"Earth","avatar":""},{"name":"Boun Noppanut Guntachai","avatar":""},{"name":"Prem Warut Chawalitrujiwong","avatar":""},{"name":"Prem","avatar":""},{"name":"Sammy Samantha Melanie Coates","avatar":""},{"name":"Pineare Pannin Charnmanoon","avatar":""},{"name":"Santa Pongsapak Oudompoch","avatar":""},{"name":"Ryu Pakphum Jitpisutsiri","avatar":""},{"name":"Soodyacht Patsit Permpoonsavat","avatar":""},{"name":"Maya Ch","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324321);
