INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('1971-nam-am-nhac-thay-doi-tat-ca', '1971: Năm Âm Nhạc Thay Đổi Tất Cả', '1971: The Year That Music Changed Everything', 'https://phimimg.com/upload/vod/20240628-1/6f1b3a36cf9280429578e425b03b72e0.jpg', 'https://phimimg.com/upload/vod/20240628-1/926abd99751c5903f43318314e66d27a.jpg', '<p>Một loạt tài liệu phong phú, sâu sắc với các đoạn phim lưu trữ và các cuộc phỏng vấn khám phá các nhạc sĩ và nhạc phim đã định hình nên văn hóa và chính trị năm 1971.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Đang cập nhât","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324321);
