INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-van-tham-vong-phan-3', 'Nhà Văn Tham Vọng (Phần 3)', 'Dickinson (Season 3)', 'https://phimimg.com/upload/vod/20240628-1/9da8688a8207b8a2127ab5588ea22e8a.jpg', 'https://phimimg.com/upload/vod/20240628-1/e97c005c49d0ce6fd9a3a91239217818.jpg', '<p>Trong mùa thứ ba và cũng là mùa cuối cùng, khoảng thời gian làm việc hiệu quả nhất của Emily Dickinson với tư cách là một nghệ sĩ rơi vào giữa Nội chiến Hoa Kỳ đang hoành hành và một trận chiến khốc liệt không kém chia rẽ chính gia đình cô. Khi Emily cố gắng hàn gắn những chia rẽ xung quanh mình, cô tự hỏi liệu nghệ thuật có thể giúp duy trì niềm hy vọng và liệu tương lai có thể tốt đẹp hơn quá khứ hay không.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hailee Steinfeld","avatar":""},{"name":"Toby Huss","avatar":""},{"name":"Adrian Enscoe","avatar":""},{"name":"Anna Baryshnikov","avatar":""},{"name":"Ella Hunt","avatar":""},{"name":"Amanda Warren","avatar":""},{"name":"Chinaza Uche","avatar":""},{"name":"Jane Krakowski","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324321);
