INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-van-tham-vong-phan-2', 'Nhà Văn Tham Vọng (Phần 2)', 'Dickinson (Season 2)', 'https://phimimg.com/upload/vod/20240628-1/dd6caf4f69a6cd9b01d25476f83f7f23.jpg', 'https://phimimg.com/upload/vod/20240628-1/8544993c65a4ab8cb45ea74a544383bb.jpg', '<p>Trong mùa thứ hai, Dickinson bị rút ra khỏi đời sống văn học riêng tư và lọt vào mắt công chúng, đồng thời đấu tranh với cảm giác rằng việc theo đuổi danh tiếng có thể là một trò chơi nguy hiểm đối với cô.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hailee Steinfeld","avatar":""},{"name":"Toby Huss","avatar":""},{"name":"Adrian Enscoe","avatar":""},{"name":"Anna Baryshnikov","avatar":""},{"name":"Ella Hunt","avatar":""},{"name":"Amanda Warren","avatar":""},{"name":"Chinaza Uche","avatar":""},{"name":"Jane Krakowski","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324321);
