INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chia-khoa-chet-choc-phan-2', 'Chìa Khóa Chết Chóc (Phần 2)', 'Locke & Key (Season 2)', 'https://phimimg.com/upload/vod/20240901-1/c0201a200779f876c7716fd3e46f110d.jpg', 'https://phimimg.com/upload/vod/20240901-1/d4013847cd5e8e2aaa1028628074d680.jpg', '<p>Ba anh chị em chuyển đến sống tại khu đất của tổ tiên sau vụ giết người khủng khiếp của cha họ đã phát hiện ra chìa khóa ma thuật của ngôi nhà mới của họ, chiếc chìa khóa này phải được sử dụng để chống lại một sinh vật độc ác muốn có chìa khóa và sức mạnh của chúng.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Darby Stanchfield","avatar":""},{"name":"Emilia Jones","avatar":""},{"name":"Jackson Robert Scott","avatar":""},{"name":"Connor Jessup","avatar":""},{"name":"Petrice Jones","avatar":""},{"name":"Hallea Jones","avatar":""},{"name":"Brendan Hines","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324321);
