INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chia-khoa-chet-choc-phan-2', 'Chìa Khóa Chết Chóc (Phần 2)', 'Locke & Key (Season 2)', 'chìa khóa chết chóc (phần 2) locke & key (season 2) darby stanchfield emilia jones jackson robert scott connor jessup petrice jones hallea jones brendan hines ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-pin-o-the-gioi-dao-lon', 'Thiếu Nữ Pin Ở Thế Giới Đảo Lộn', 'RUMBLE GARANNDOLL', 'https://phimimg.com/upload/vod/20240615-1/a7d39c406d78c92a3e9cb3b25d77e2f5.jpg', 'https://phimimg.com/upload/vod/20240615-1/0f1a0d55563776383a8f195cf011566f.jpg', '<p>Tây lịch năm 2019. Đó là năm khởi đầu kỷ nguyên mới tại Nhật Bản. Trên bầu trời bỗng xuất hiện một vết nứt không gian nối đến một thế giới song song khác, nơi có một đất nước với tên gọi Chính Quốc Nhật Bản. Ở thế giới ấy vẫn duy trì chế độ quân phiệt với niên hiệu Showa Vĩnh Hằng. Với những vũ khí vượt trội, họ đã thực hiện việc xâm chiếm Nhật Bản. Chỉ trong nháy mắt, chính phủ Nhật Bản đã bị khống chế, nước Nhật nằm dưới sự kiểm soát của Chính Quốc Nhật Bản. Chính vì vậy, thời đại Reiwa đã không bao giờ xuất hiện ở đất nước mặt trời mọc. Mười năm sau, Nhật Bản nay đã có tên gọi mới là Huyễn Quốc Nhật Bản, trở thành chư hầu của Chính Quốc Nhật Bản. Dưới sự kiểm duyệt nghiêm ngặt, nền giải trí Manga, Anime, Idol hưng thịnh một thời giờ đây đã hoàn toàn bị xóa sổ. Những tưởng là như vậy, nhưng... Otaku is not dead! Một tổ chức với cái tên Arahabaki đã đứng lên chống lại Chính Quốc Nhật Bản, với mục đích bảo vệ nền giải trí ấy. Vũ khí của họ là cỗ máy Garann Doll, cùng những thiếu nữ sạc năng lượng cho nó. Người ta gọi những cô gái đó với cái tên: những Thiếu nữ pin.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324321);
