INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('schmigadoon-phan-1', 'Schmigadoon! (Phần 1)', 'Schmigadoon! (Season 1)', 'https://phimimg.com/upload/vod/20240615-1/61629e08720332b77cecd3f044e3d020.jpg', 'https://phimimg.com/upload/vod/20240615-1/ac9fb5308669fde6aa453220b2132031.jpg', '<p>Trong vở nhạc kịch nhại lại những năm 1940 này, cặp đôi du lịch ba lô Melissa và Josh bị mắc kẹt ở Schmigadoon, một thị trấn kỳ diệu với những người dân thị trấn ca hát và nhảy múa, và biết rằng họ không thể rời đi nếu chưa tìm được tình yêu đích thực—điều mà họ nghĩ rằng mình đã có.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keegan-Michael Key","avatar":""},{"name":"Cecily Strong","avatar":""},{"name":"Dove Cameron","avatar":""},{"name":"Ariana DeBose","avatar":""},{"name":"Jaime Camil","avatar":""},{"name":"Kristin Chenoweth","avatar":""},{"name":"Alan Cumming","avatar":""},{"name":"Ann Harada","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Aaron Tveit","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324321);
