INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-trang-laika-va-cong-chua-hut-mau', 'Mặt Trăng, Laika Và Công Chúa Hút Máu', 'Moon, Laika, And The Bloodsucking Princess', 'https://phimimg.com/upload/vod/20240615-1/460d2feb5d88bae673090ace58704ddf.jpg', 'https://phimimg.com/upload/vod/20240615-1/9990f88da338ae80e733dfc7709c3274.jpg', '<p>Lịch sử phương Đông 1960. Gergiev, lãnh đạo chính của Cộng hòa, công bố chương trình bay không gian có người lái Dự án Mechtat (Dream). Lev Leps, một ứng viên phi hành gia thay thế, được lệnh thực hiện một nhiệm vụ tối mật. Dự án Nosferatu, chương trình thử nghiệm với ma cà rồng trước khi thực hiện với người lái, sẽ sử dụng Irina Luminesk làm đối tượng thử nghiệm, và Lev sẽ theo dõi và huấn luyện cô ấy. Bị cản trở bởi vấn đề chủng tộc và bản ngã của các quốc gia, Lev và Irina vẫn chia sẻ một tình cảm chân thành hướng tới vũ trụ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324321);
