INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('fran-lebowitz-gia-nhu-no-la-thanh-pho', 'Fran Lebowitz: Giả Như Nó Là Thành Phố', 'Pretend It''s A City', 'https://phimimg.com/upload/vod/20240615-1/e152317d8b8efdbfc56db35568fd8265.jpg', 'https://phimimg.com/upload/vod/20240615-1/7f3261f888e026f2a595155dd68e6dfa.jpg', '<p>Lang thang qua phố xá ở Thành phố New York và tâm trí thú vị của nhà văn hài hước, mỉa mai với tài kể chuyện Fran Lebowitz khi bà ngồi cùng Martin Scorsese.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Fran Lebowitz","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324321);
