INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-doi-the-gioi', 'Hoán Đổi Thế Giới', 'Switch On', 'https://phimimg.com/upload/vod/20240615-1/8840b80de2a3a296b13d3eeab7f26824.jpg', 'https://phimimg.com/upload/vod/20240615-1/2434e7d49751aec1569ccdc9c6faab95.jpg', '<p>Bộ phim xoay quanh Nisa (Aom Sushar thủ vai) – con gái của chủ sở hữu trò chơi Better World nổi tiếng. Cuộc sống của cô thay đổi hoàn toàn khi bị hoán đổi với nhân vật trong game. Từ đó, cả hai phải gắn bó với nhau nhằm tìm cách đưa mọi thứ trở về vị trí ban đầu. Trong khi đó, A-Kin là một anh hùng đấu tranh cho lẽ phải trong thế giới game có tên là Better World và luôn tìm kiếm sự thật về cái chết của cha mình. Đan xen giữa hai thế giới tách biệt, thì, tình yêu giữa A-Kin và Nisa sẽ ra sao? Liệu cả hai có đến được với nhau?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2021, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Gee Sutthirak","avatar":""},{"name":"Aom Sushar","avatar":""},{"name":"Phukhao Worapot","avatar":""},{"name":"Chin Chinawut","avatar":""},{"name":"Meiko Chonnikan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324321);
