INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('new-amsterdam-phan-3', 'New Amsterdam (Phần 3)', 'New Amsterdam (Season 3)', 'https://phimimg.com/upload/vod/20240615-1/cbc910ca5b7bc50081992f80d2cbe293.jpg', 'https://phimimg.com/upload/vod/20240615-1/503d4a53d941c179d56626af8198cbeb.jpg', '<p>Khi Tiến sĩ Max Goodwin tiếp quản New Amsterdam, ông đã hỏi một câu hỏi đơn giản và mang tính cách mạng: “Tôi có thể giúp gì?” Trong phần ba, Max và nhóm của anh ấy phải đối mặt với nhiệm vụ khó khăn là duy trì sự lạc quan đó trong khi đối phó với một đại dịch phơi bày sự bất bình đẳng trong chăm sóc sức khỏe của chúng ta. Max không còn hài lòng với việc sửa chữa một hệ thống bị hỏng. Anh ấy quyết tâm phá bỏ nó và xây dựng một cái gì đó tốt hơn.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Eggold","avatar":""},{"name":"Janet Montgomery","avatar":""},{"name":"Jocko Sims","avatar":""},{"name":"Tyler Labine","avatar":""},{"name":"Sandra Mae Frank","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324321);
