INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-cau-chuyen-phu-nu-tieng-telugu', 'Bốn Câu Chuyện Phụ Nữ (tiếng Telugu)', 'Pitta Kathalu', 'https://phimimg.com/upload/vod/20240615-1/fadb260090c8c60b6e81ea56f5fd8329.jpg', 'https://phimimg.com/upload/vod/20240615-1/4842214c48d34d521211dcebeab4aa9e.jpg', '<p>Từ những bí mật và dối trá cho đến ghen tuông và kiểm soát, bốn câu chuyện trong phim hợp tuyển này khám phá những mặt dối trá, đen tối hơn của tình yêu.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Manchu Lakshmi","avatar":""},{"name":"Saanve Megghana","avatar":""},{"name":"Naveen Kumar","avatar":""},{"name":"Jagapathi Babu","avatar":""},{"name":"Amala Paul","avatar":""},{"name":"Aswin Kakamanu","avatar":""},{"name":"Shruthi Haasan","avatar":""},{"name":"Sanjith Hegde","avatar":""},{"name":"Sangeeth Shoban","avatar":""},{"name":"Anish Kuruvilla","avatar":""},{"name":"Uko","avatar":""},{"name":"Dayanand Reddy","avatar":""},{"name":"Thanmayi","avatar":""},{"name":"Satya Dev","avatar":""},{"name":"Eesha Rebba","avatar":""},{"name":"Srinivas Avasarala","avatar":""},{"name":"Ashima N","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324321);
