INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-toi-la-robot', 'Người Yêu Tôi Là Rô-Bốt', 'AI Romantic', 'https://phimimg.com/upload/vod/20240615-1/ee08741ad085303f5d5befd838c16f91.jpg', 'https://phimimg.com/upload/vod/20240615-1/710e909c4b6fb1ba97edcf872c5e9db4.jpg', '<p>Trên đường vận chuyển cho khách hàng, người máy cao cấp ASI 005 đột nhiên biến mất. Cổ Gia Liêm tình cờ gặp ASI 005 trên đường nên quyết định đưa về nhà, đặt tên là Bảo. Dưới sự hướng dẫn của Liêm, Bảo trở thành trợ lý tích cực của nhà họ Cổ. Trong quá trình thực hiện các nhiệm vụ kỳ lạ mà các thành viên giao cho, Bảo vô tình khởi động công năng tự học tập. Nhờ đó, cô bắt đầu cảm nhận mọi cung bậc cảm xúc của loài người và nảy sinh tình cảm với Liêm. Chính điều này đã mang đến cho Bảo nhiều rắc rối.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2021, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Lý Giai Tâm","avatar":""},{"name":"Lục Vĩnh","avatar":""},{"name":"Phùng Doanh Doanh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324321);
