INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('azcarate-khong-kieng-de', 'Azcárate: Không Kiêng Dè', 'Azcárate: No Holds Barred', 'https://phimimg.com/upload/vod/20240615-1/d385d7a8c3aaaf0defe09f8228fab689.jpg', 'https://phimimg.com/upload/vod/20240615-1/4eb5c4a136f55dfbbe3a379dda3fb851.jpg', '<p>Nữ diễn viên-danh hài Colombia Alejandra Azcárate kết hợp chương trình đối thoại cùng hài để mang đến những tràng cười lớn và suy ngẫm về tuổi tác, tình yêu, tình dục.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 11, 2021, 'Vietsub', 'HD', 'Colombia', 0, '[{"name":"Alejandra Azcárate","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324321);
