INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-vuc-cua-su-dien-ro', 'Bờ Vực Của Sự Điên Rồ', 'On The Verge Of Insanity', 'https://phimimg.com/upload/vod/20240615-1/bf54e696e2738bc57756ccde045e97dd.jpg', 'https://phimimg.com/upload/vod/20240615-1/4fb4d7d5cb06cdd6b19049c05609ba49.jpg', '<p>Bờ Vực Của Sự Điên Rồ - On the Verge of Insanity kể về kỹ sư kỳ cựu Choi Ban Suk (Jung Jae Young) là nhà phát triển trong bộ phận điện tử tiêu dùng của Hanmyung Electronics, với tính cách điềm tĩnh và ấm áp. Anh phải đối mặt với cuộc khủng hoảng lớn nhất trong sự nghiệp 22 năm làm việc khi phải chuyển sang bộ phận nhân sự để tránh bị sa thải. Trong khi đó, Dang Ja Young (Moon So Ri) - trưởng phòng nhân sự - là người nghiện công việc và muốn trở thành nữ giám đốc điều hành đầu tiên của công ty. Khi Choi Ban Sukk chuyển đến bộ phận của mình, ban đầu cô không biết xử lý thế nào nhưng khi làm việc cùng nhau, cô nhận thấy cuộc sống của mình đã dần thay đổi.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Moon So-ri","avatar":""},{"name":"Jeong Jae-young","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324321);
