INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-lai-cuoc-doi-cua-chung-ta', 'Làm Lại Cuộc Đời Của Chúng Ta', 'Remake Our Life!', 'https://phimimg.com/upload/vod/20240615-1/4fb47df532063b94f99eb560092d6941.jpg', 'https://phimimg.com/upload/vod/20240615-1/af75e5edbb49b2cef78d53e9c4bc3035.jpg', '<p>Năm 2016, Kyōya Hashiba 28 tuổi vì công ty trò chơi do anh làm giám chế phá sản mà phải trở về quê nhà. Khi nhìn thấy tác giả thành công trên manga Niconico, Kyōya cảm thấy những người này là người bằng tuổi mình. Sau khi Kyōya về quê nhà, phát hiện không biết vì nguyên nhân gì, bản thân lại quay về năm 2006, để thay đổi mọi thứ, anh quyết định đi học tại đại học nghệ thuật.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 17, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324321);
