INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-cho-em-su-yeu-chieu-doc-nhat', 'Dành Cho Em Sự Yêu Chiều Độc Nhất', 'Here Is My Exclusive Indulge', 'https://phimimg.com/upload/vod/20240615-1/9893fa3368c809162415eb190a3194ea.jpg', 'https://phimimg.com/upload/vod/20240615-1/1dfab23d213402fe382c7d6e5930ab21.jpg', '<p>Vân Tưởng Tưởng ngây thơ trong sáng, được mẹ yêu chiều từ nhỏ, cuộc sống hạnh phúc, tính cách lương thiện, không ngờ cuộc sống gia đình bỗng xảy ra một loạt biến cố. Cha kế Vân Dật Minh bày đủ mưu kế, Vân Tưởng Tưởng suýt thì gặp bất trắc, mẹ cô - Diệp Khanh cũng cận kề nguy hiểm. Để bảo vệ mẹ, Vân Tưởng Tưởng đã vùng dậy từ nghịch cảnh, dưới sự giúp đỡ của Phó Tư Hàn, cô đấu trí đấu dũng với Vân Dật Minh, nhiều lần lật đổ âm mưu của ông ta, bản thân Vân Tưởng Tưởng cũng dần trưởng thành trong trắc trở, từ một thiếu nữ không hiểu sự đời trở thành cô gái thời đại mới dám làm dám chịu, đồng thời thu hoạch được tình yêu ngọt ngào với Phó Tư Hàn.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Guo Jianan","avatar":""},{"name":"Sissi Bao","avatar":""},{"name":"Chen Siqi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324321);
