INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoc-chieu-anh-sang-noi-loi-yeu-em', 'Ngược Chiều Ánh Sáng, Nói Lời Yêu Em', 'Mysterious Love', 'https://phimimg.com/upload/vod/20240615-1/e517d1da253568a2bc75c1cd313cb21c.jpg', 'https://phimimg.com/upload/vod/20240615-1/37488ecd5e6a6fb784b714ebe2f08105.jpg', '<p>Phim kể về nam chính đẹp trai lạnh lùng Lệ Đằng và diễn viên kịch nói thông minh lanh lợi Nguyễn Niệm Sơ. Lệ Đằng tình cờ gặp gỡ và đã cứu Niệm Sơ trong lúc nguy hiểm, hai người cảm mến nhau nhưng do không cùng quỹ đạo sống nên đành chia xa. Năm năm sau, một cuộc gặp gỡ đã phá vỡ cuộc sống của Nguyễn Niệm Sơ, hai người họ hóa giải hết những hiểu lầm và nguy hiểm, cùng nắm tay nhau chiến đấu, phá giải hết những âm mưu, quay trở lại cuộc sống hạnh phúc bình thường.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tào Hựu Ninh","avatar":""},{"name":"Dư Nguyệt","avatar":""},{"name":"Ngô Hạo Trạch","avatar":""},{"name":"Mã Hân Mặc","avatar":""},{"name":"Lợi Tình Thiên","avatar":""},{"name":"Ngô Hạnh Kiện","avatar":""},{"name":"Trịnh Y Minh","avatar":""},{"name":"Từ Thấm","avatar":""},{"name":"Tôn Hi Chi","avatar":""},{"name":"La Gia Mạnh","avatar":""},{"name":"Na Uy","avatar":""},{"name":"Thang Gia Văn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324321);
