INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoc-chieu-anh-sang-noi-loi-yeu-em', 'Ngược Chiều Ánh Sáng, Nói Lời Yêu Em', 'Mysterious Love', 'ngược chiều ánh sáng, nói lời yêu em mysterious love tào hựu ninh dư nguyệt ngô hạo trạch mã hân mặc lợi tình thiên ngô hạnh kiện trịnh y minh từ thấm tôn hi chi la gia mạnh na uy thang gia văn ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ket-thuc-bach-kim', 'Kết Thúc Bạch Kim', 'Platinum End', 'https://phimimg.com/upload/vod/20240615-1/257c9273f5499f4e394be3607391862f.jpg', 'https://phimimg.com/upload/vod/20240615-1/610ffca0204dc583dc1056b2a13df7b2.jpg', '<p>Khi các bạn cùng lớp tổ chức lễ tốt nghiệp cấp hai, Mirai gặp rắc rối và chìm trong bóng tối. Nhưng trận chiến của anh ấy chỉ mới bắt đầu khi anh ấy nhận được sự cứu rỗi từ trên cao dưới hình dạng một thiên thần. Bây giờ Mirai phải đọ sức với 12 người được chọn khác trong một trận chiến mà người chiến thắng sẽ trở thành vị thần tiếp theo của thế giới. Mirai có một thiên thần trong góc của mình, nhưng anh ấy có thể cần phải trở thành ác quỷ để tồn tại.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 5, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Miyu Irino","avatar":""},{"name":"Yui Ogura","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Kikuko Inoue","avatar":""},{"name":"Tomoaki Maeno","avatar":""},{"name":"Hikaru Midorikawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324321);
