INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('iruma-gia-dao-phan-2', 'Iruma Giá Đáo! Phần 2', 'Mairimashita! Iruma-kun 2nd Season', 'https://phimimg.com/upload/vod/20240615-1/cc3243ca38f9e16169529ae920df482f.jpg', 'https://phimimg.com/upload/vod/20240615-1/e689dba1b6770913d941fa0c0951d5c7.jpg', '<p>Suzuki Irima - bị biến thành cháu trai của đại ác quỷ trong thế giới quỷ, cậu bắt đầu theo học trường của quỷ, cậu che giấu việc mình vốn là con người, mong muốn một cuộc sống thật yên bình, thế nhưng cuộc sống học đường lại đầy rẫy những rắc rối.</p>', 'Hoàn Tất (21/21)', 21, 'hoathinh', 'completed', 20, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324321);
