INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-bong-su-tu-tren-than-meo', 'Chiếc Bóng Sư Tử Trên Thân Mèo', 'The Lion''s Secret', 'https://phimimg.com/upload/vod/20240615-1/56e3d980390243bc6e8bfb4d7ec3cc63.jpg', 'https://phimimg.com/upload/vod/20240615-1/344fa32d80ca2fd2eaeb75a8a243a571.jpg', '<p>Chiếc Bóng Sư Tử Trên Thân Mèo là bộ phim kể về câu chuyện vào ngày nữ tổng giám đốc tập đoàn Mậu Viễn – Mộ Vãn Thanh kết hôn, cũng là lần đầu tiên cô gặp được chú rể - Lưu Thanh. Hai người trở thành hai người xa lạ có quan hệ thân thiết nhất, bắt đầu màn kịch hay giữa cô gái mạnh mẽ và chàng trai yếu đuối. Lưu Thanh tiến vào tập đoàn Mậu Viễn, giúp đỡ Mộ Vãn Thanh xử lý các nguy cơ, khiến cô mềm lòng. Trong lần đi tới Thái Lan để hoàn thành di nguyện của bà nội, hai người mới phát hiện tất cả là một âm mưu lớn, và thân phận của Lưu Thanh cũng dần được hé lộ.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chu Á Văn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324321);
