INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-cung-phong-cua-toi-la-gumiho', 'Bạn Cùng Phòng Của Tôi Là Gumiho', 'My Roommate Is A Gumiho', 'https://phimimg.com/upload/vod/20240615-1/e91c700987fbf222d8e8fc84fd7e4e1e.jpg', 'https://phimimg.com/upload/vod/20240615-1/399be24d781fab73fecd7fe5f7a607cc.jpg', '<p>Bạn Cùng Phòng Của Tôi Là Gumiho (My Roommate is a Gumiho) là bộ phim truyền hình Hàn Quốc xoay quanh câu chuyện về nữ sinh viên đại học Lee Dam và nam hồ ly Shin Woo Yeo khi cô nàng vô tình nuốt phải quả cầu của cửu vĩ hồ khiến cả hai rơi vào tình huống đầy khó xử. Cô sẽ không thể sống quá 1 năm kể từ khi nuốt quả cầu đó, đồng thời cũng khiến cho cửu vĩ hồ Shin Woo Yeo mất đi cơ hội trở thành người sau 999 năm chờ đợi. Đó cũng chính là lý do đưa họ tới quyết định nên sống cùng nhau cho tới khi tìm ra giải pháp để đưa mọi thứ quay về vị trí ban đầu và những tình huống dở khóc dở cười bắt đầu từ đây.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 17, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Ki Yong","avatar":""},{"name":"Lee Hye-ri","avatar":""},{"name":"Kang Han Na","avatar":""},{"name":"Kim Do-Wan","avatar":""},{"name":"Bae In-hyuk","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324321);
