INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-bi-kich-bi-kich-thuong-luu', 'Con Đường Bi Kịch (Bi Kịch Thượng Lưu)', 'The Road: The Tragedy Of One', 'https://phimimg.com/upload/vod/20240615-1/2f4e1ae4d021345664050111c132d765.jpg', 'https://phimimg.com/upload/vod/20240615-1/3fa3c7dd77669c9419967686a0b23691.jpg', '<p>Con Đường Bi Kịch (Bi Kịch Thượng Lưu, The Road: Tragedy of One) là bộ phim xoay quanh những tham vọng khủng khiếp, bí mật, tội lỗi và sự cứu rỗi xoay quanh Royal the Hills - nơi sinh sống của 1% những người giàu có và quyền lực nhất Hàn Quốc. Bi kịch thượng lưu bắt đầu khi một sự cố khủng khiếp phá vỡ sự yên bình bên trong khu bảo tồn trang nhã. Tất cả mọi người đều bị cuốn vào sự cố này, kéo theo đó là những khúc quanh bất ngờ trong cuộc đời của họ.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2021, 'Vietsub + Thuyết minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Ji Jin Hee","avatar":""},{"name":"Yoon Se A","avatar":""},{"name":"Kim Hye Eun","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324321);
