INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-lung-cong-chua', 'Linh Lung Công Chúa', 'The Wolf Princess', 'https://phimimg.com/upload/vod/20240829-1/ae1303a0b05243fe1aa4308de0b2df83.jpg', 'https://phimimg.com/upload/vod/20240829-1/b77806401576664e0a2c95157204effd.jpg', '<p>Linh Lung Lang Tâm xoay quanh một cô gái hiện đại được tái sinh về thời cổ trang trong thân thể của một cô công chúa ẩn sống yên bình, lặng lẽ mang trong mình linh hồn của một con sói hai là con người. Tên phim Linh Lung Lang Tâm bắt nguồn từ vương quốc với những điều kỳ bí về những con mãnh thú với sự xuất hiện của chàng hoàng tử người khả ái, lạnh lùng và đầy bí ẩn khiến phim trở nên thú vị và bí mật về linh hồn con sói trong người vị công chúa này cũng dần được các vị hoàng tử tìm hiểu dần dần.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2021, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngụy Tông Vạn","avatar":""},{"name":"Trịnh Hạo Nam","avatar":""},{"name":"Vương Tâm Hải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324321);
