INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-binh-pham-diep-vu-sinh-tu', 'Dã Bình Phàm Điệp Vụ Sinh Tử', 'The Mask', 'https://phimimg.com/upload/vod/20240828-1/3de07f26359e194706b99301ccacd329.jpg', 'https://phimimg.com/upload/vod/20240828-1/0c976733075d5ee820d4af4174305ccd.jpg', '<p>Dã Bình Phàm: Điệp Vụ Sinh Tử - The Mask xoay quanh một vụ án cũ cách đây 27 năm. Vụ án này tưởng chừng bị thời gian vùi lấp nhưng dần dần được hé lộ. Hung thủ chính là bố và anh của Lý Phàm là Lý Đình Sơn và Lý Bình, mà Lý Bình thay em là Lý Phàm đảm nhận việc trả thù cách đây 27 năm. Sau khi Lý Đình Sơn bị bắt, Lý Bình nhảy xuống biển chạy trốn, Lý Phàm truy tìm tung tích của anh hai đã đến nơi mà họ đã khôn lớn Châu Âu.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 8, 2021, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"鄭愷","avatar":""},{"name":"張國立","avatar":""},{"name":"Danni Chong","avatar":""},{"name":"Raymond Lam","avatar":""},{"name":"Guo Yunqi","avatar":""},{"name":"Lv Liang","avatar":""},{"name":"Gao Xiao Fei","avatar":""},{"name":"Qiao Jing Wen","avatar":""},{"name":"湯夢佳","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324321);
