INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-tien-sinh-hoa-ra-anh-la-nhu-vay', 'Cố Tiên Sinh, Hóa Ra Anh Là Như Vậy', 'Hello Mr. Gu', 'https://phimimg.com/upload/vod/20240827-1/f309ccd741455867af4e6518b3097215.jpg', 'https://phimimg.com/upload/vod/20240827-1/52fc2197a3b835b7c68148b7e2ebd3d7.jpg', '<p>Cố Tiên Sinh, Hóa Ra Anh Là Như Vậy kể về một là CEO hai mặt, đáng yêu, một là công chúa gặp nạn, nam nữ chính tính cách khác nhau, cuộc sống cũng khác nhau một trời một vực, dẫn đến không ưa gì nhau. Nhưng vì một lần ngoài ý muốn dẫn đến 1 bản hợp đồng hôn nhân. Đôi vợ chồng giả bắt đầu sống chung một nhà, sau khi trải qua những đụng chạm và hoạn nạn, hai người dần dần từ đôi oan gia trở thành bạn bè thân thương thậm chí là người yêu.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"陳靖可","avatar":""},{"name":"严智超","avatar":""},{"name":"Guo Yun Qi","avatar":""},{"name":"Zhu Danni","avatar":""},{"name":"Xin Ruiqi","avatar":""},{"name":"丁嘉文","avatar":""},{"name":"Liu Xiao Liang","avatar":""},{"name":"Cheng Zi","avatar":""},{"name":"任杰","avatar":""},{"name":"Wang Xin","avatar":""},{"name":"Wang Lei","avatar":""},{"name":"Liang Gao","avatar":""},{"name":"Zhong Weilun","avatar":""},{"name":"Chen Liang","avatar":""},{"name":"Zeng Qi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324321);
