INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-nhan-tao', 'Thành Phố Nhân Tạo', 'Artificial City', 'https://phimimg.com/upload/vod/20240820-1/588a819725af561d6e7667f917e41e8a.jpg', 'https://phimimg.com/upload/vod/20240820-1/e8f77cdfdb3a21b47b1bc32f61b32a36.jpg', '<p>Lấy bối cảnh tại một viện bảo tàng nghệ thuật thuộc tập đoàn Sungjin, một tập đoàn lớn nắm giữ nhiều mối liên hệ của giới chính trị và tài chính Hàn Quốc. Phim khai thác tâm lý, tham vọng của những người phụ nữ nỗ lực vươn lên vị trí cao nhất Hàn Quốc. Yoon Jae Hee là con dâu thứ hai của&nbsp; gia tộc sở hữu Tập đoàn Sungjin. Cô làm việc tại phòng trưng bày nghệ thuật Space Jin. Trong quá khứ, cô chia tay người bạn trai lâu năm để cưới Jung Joon Hyeok - con trai ngoài giá thú của gia đình tài phiệt đó. Yoon Jae Hee muốn giúp chồng mình trở thành tổng thống. Vì thế nên cô hợp tác với Tổng trưởng công tố kế nhiệm và cô bắt đầu chống lại nhà chồng của mình. Jung Joon Hyuk – chồng của Yoon Jae Hee, phát thanh viên của đài JBC, người đàn ông toả ra “ánh hào quang” nhưng bản thân luôn tự ti vì thân phận “con hoang” của mình. Jung Joon Hyuk luôn giả vờ cười nhạo những kẻ tham vọng nhưng tận sâu bên trong, người này luôn ấp ủ chờ thời cơ có thể để thay đổi về đúng bản chất của mình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"수애","avatar":""},{"name":"김강우","avatar":""},{"name":"김미숙","avatar":""},{"name":"이이담","avatar":""},{"name":"이학주","avatar":""},{"name":"김주령","avatar":""},{"name":"김영재","avatar":""},{"name":"김지현","avatar":""},{"name":"백지원","avatar":""},{"name":"남기애","avatar":""},{"name":"박지일","avatar":""},{"name":"남문철","avatar":""},{"name":"Yum Dong-hun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324321);
