INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hao-quang-nghiet-nga-phan-2', 'Hào Quang Nghiệt Ngã (Phần 2)', 'Hidden Truths (Season 2)', 'https://phimimg.com/upload/vod/20240820-1/c89ca456013a8deee082ee5a4ddffa1b.jpg', 'https://phimimg.com/upload/vod/20240820-1/de349a4695cee92e85f16897816b1072.jpg', '<p>Nhiều năm sau khi những sự kiện diễn ra ở phần một, ai cũng tưởng rằng câu chuyện của Angel đã đi đến hồi kết. Tuy nhiên, Giovanna bất ngờ trở lại với quyết tâm lật tẩy tội giết người của Angel, buộc cô phải bước đi trên con đường Catwalk đầy máu và nước mắt một lần nữa.</p>', 'Hoàn Tất (51/51)', 51, 'series', 'completed', 16, 2021, 'Thuyết Minh', 'FHD', 'Brazil', 0, '[{"name":"Camila Queiroz","avatar":""},{"name":"Rômulo Estrela","avatar":""},{"name":"Ágatha Moreira","avatar":""},{"name":"Rodrigo Lombardi","avatar":""},{"name":"Gabriel Braga Nunes","avatar":""},{"name":"Deborah Evelyn","avatar":""},{"name":"Rainer Cadete","avatar":""},{"name":"Maria de Medeiros","avatar":""},{"name":"Sérgio Guizé","avatar":""},{"name":"Erika Januza","avatar":""},{"name":"Jonathan Azevedo","avatar":""},{"name":"Ícaro Silva","avatar":""},{"name":"João Vitor Silva","avatar":""},{"name":"Guilhermina Guinle","avatar":""},{"name":"Júlia Byrro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324321);
