INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-goi-anh-la-cau-chu', 'Đừng Gọi Anh Là Cậu Chủ', 'My Boss Calls Me My Love', 'https://phimimg.com/upload/vod/20240819-1/9e77aec286f80bd4e2de154e377df5ab.jpg', 'https://phimimg.com/upload/vod/20240819-1/78d50e67e7670d2b47fb074b25ea261f.jpg', '<p>Fai và Wai trở thành oan gia của nhau sau một vụ hiểu lầm. Sau đó, nhờ bác Kew mà Fai được vào làm đầu bếp cho nhà Wai dưới thân phận là Soi - con gái bác Kew. Vì biết Soi là giả dạng nên Wai thường xuyên tìm cách hoạnh họe và bắt nạt cô nàng, ép cô phải nấu thật nhiều món ăn khó. Nhưng nhờ tài nấu nướng cực giỏi của Soi mà Wai dần yêu cô lúc nào không hay.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Amornlak Cholruedee","avatar":""},{"name":"Mark Apiwit Jakthreemongkol","avatar":""},{"name":"Pokchat Thiamchai","avatar":""},{"name":"Preeyada Sittachai","avatar":""},{"name":"Arm Sukavin Keawpikul","avatar":""},{"name":"Sitang Punnapob","avatar":""},{"name":"Simon Kessler","avatar":""},{"name":"Indy Intad Leowrakwong","avatar":""},{"name":"Michelle Behrmann","avatar":""},{"name":"วิทวัส สิงห์ลำพอง","avatar":""},{"name":"Rudklao Amratisha","avatar":""},{"name":"Nahathai Pichitra","avatar":""},{"name":"Passakorn P","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324321);
