INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nabi-toi-se-khong-yeu-em', 'Nabi, Tôi Sẽ Không Yêu Em', 'Nabi, My Stepdarling', 'https://phimimg.com/upload/vod/20240819-1/5c7575ca75ea768730a45b233bc07c0b.jpg', 'https://phimimg.com/upload/vod/20240819-1/c48073755c816640fa5335cf2f63f434.jpg', '<p>Mối nhân duyên của Kawin và Nabi bắt đầu khi họ gặp nhau tại hộp đêm Dubai, nhưng sự ganh ghét và tình yêu mù quáng của người dì Weeranat đã khiến mọi chuyện rơi vào bi kịch. Trở về nước sau thời gian du học, Kawin gặp lại Nabi, nay là quản lý của Dubai, đã khiến cậu nảy sinh những hiểu lầm. Càng ghét thì càng chứng tỏ tình yêu mà Kawin dành cho Nabi, nhưng những ân oán đời trước là bức tường ngăn cách hai người.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Myria Benedetti","avatar":""},{"name":"Way-ar Sangngern","avatar":""},{"name":"Yongwaree Anilbol","avatar":""},{"name":"Oliver Poupart","avatar":""},{"name":"พลอยนิรา หิรัญทวีศิลป์","avatar":""},{"name":"Luke Ishikawa Plowden","avatar":""},{"name":"Ployshompoo Supasap","avatar":""},{"name":"ทัชชกร บุญลัภยานันท์","avatar":""},{"name":"พรหมพิริยะ ทองพุทธรักษ์","avatar":""},{"name":"ภัทร เอกแสงกุล","avatar":""},{"name":"Wanpiya Oamsinnoppakulj","avatar":""},{"name":"Apinun Prasertwattanakul","avatar":""},{"name":"Nip","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324321);
