INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-24-vien-dan-do', 'Thám Tử Lừng Danh Conan 24: Viên Đạn Đỏ', 'Detective Conan: The Scarlet Bullet', 'https://phimimg.com/upload/vod/20231019-1/e2bd1164d074d7ac00fcf24817b92977.jpg', 'https://phimimg.com/upload/vod/20231019-1/8b09c07dba1931b747227f103f8f8bbc.jpg', '<p>Thế vận hội thể thao lớn nhất thế giới được tổ chức tại Tokyo, Nhật Bản thu hút rất nhiều sự chú ý. Khi sự kiện ra mắt con tàu siêu tốc với tốc độ 1000km/h diễn ra cũng là lúc hàng loạt các vụ bắt cóc xảy ra! Gia tộc hiểm ác tụ tập tại đây sẽ gây ra một loạt sự kiện chấn động thế giới!</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2021, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 1, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Fumio Matsuoka","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Ryotaro Okiayu","avatar":""},{"name":"Shuichi Ikeda","avatar":""},{"name":"Atsuko Tanaka","avatar":""},{"name":"Noriko Hidaka","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Yu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356