INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-the-tha-thu', 'Không Thể Tha Thứ', 'The Unforgivable', 'https://phimimg.com/upload/vod/20231129-1/2bcea51ea46c1025632cb3bfe7ad76a4.jpg', 'https://phimimg.com/upload/vod/20231129-1/d15f0a90bd729d7df27b23fc54cdf5c9.jpg', '<p>Ra tù và dấn thân vào một xã hội không tha thứ cho mình, một phụ nữ bị buộc tội giết người đi tìm đứa em gái mà cô đã buộc lòng bỏ lại.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Richard Thomas","avatar":""},{"name":"Linda Emond","avatar":""},{"name":"Aisling Franciosi","avatar":""},{"name":"Emma Nelson","avatar":""},{"name":"Will Pullen","avatar":""},{"name":"Tom Guiry","avatar":""},{"name":"Jess McLeod","avatar":""},{"name":"Rob Morgan","avatar":""},{"name":"Andrew Francis","avatar":""},{"name":"W. Earl Brown","avatar":""},{"name":"Orlando Lucas","avatar":""},{"name":"Jude Wilson","avatar":""},{"name":"Paul Moniz de Sa","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324321);
