INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-the-tha-thu', 'Không Thể Tha Thứ', 'The Unforgivable', 'không thể tha thứ the unforgivable sandra bullock viola davis vincent d''onofrio jon bernthal richard thomas linda emond aisling franciosi emma nelson will pullen tom guiry jess mcleod rob morgan andrew francis w. earl brown orlando lucas jude wilson paul moniz de sa c ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-kien-khuynh-tam', 'Nhất Kiến Khuynh Tâm', 'Fall In Love', 'https://phimimg.com/upload/vod/20240815-1/801601229ddd7cf84d05aff8b571a087.jpg', 'https://phimimg.com/upload/vod/20240815-1/80d3707b6ce5570886c7f23031b9b09e.jpg', '<p>Sau 10 năm tha hương, Mộc Uyển Khanh trở về Trung Quốc để tìm ra sự thật về cái chết của người anh trai năm xưa khiến cha mẹ cô chia cắt. Đàm Huyền Lâm là đội trưởng binh biến của Thượng Hải nhưng vì lý lịch khiêm tốn nên tiền đồ không mấy xán lạn. Từ Quang Diệu, con trai duy nhất của Tư lệnh Việt Thành, là người được ngưỡng mộ nhưng anh rất ghét các cuộc tranh giành quyền lực. Một cuộc gặp gỡ định mệnh đã gắn kết cuộc đời ba người lại với nhau, cùng nhau trải qua những thăng trầm, thậm chí những khoảnh khắc sinh tử.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"陳星旭","avatar":""},{"name":"張婧儀","avatar":""},{"name":"Lin Yanjun","avatar":""},{"name":"Maggie Chen","avatar":""},{"name":"馬月","avatar":""},{"name":"Dai Yaqi","avatar":""},{"name":"Shao Weitong","avatar":""},{"name":"Huo Zhengyan","avatar":""},{"name":"Xiu Qing","avatar":""},{"name":"Zheng Xiaoning","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324321);
