INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-luyen-lum-dong-tien', 'Quyến Luyến Lúm Đồng Tiền', 'In Love With Your Dimples', 'https://phimimg.com/upload/vod/20240814-1/5c3220ddab131089735685daa5b1100c.jpg', 'https://phimimg.com/upload/vod/20240814-1/a7f61a2203f4f18b388e589cef8fe38a.jpg', '<p>Quyến Luyến Lúm Đồng Tiền kể về câu chuyện của nữ bạo chúa học đường Đường Song Ký (Trần Ý Hàm thủ vai), người đang đối mặt với 3 điều không: không việc, không tình và không tiền. Cô buộc phải trở về quê hương để làm nhân viên lễ tân, vốn muốn trở thành người bình thường sống cuộc sống qua ngày nhưng vì tài năng thiên bẩm, tầm hồn thu ví và tính cách thẳng thắn nên Đường Song Ký đã vô tình thu hút sự chú ý của ba chàng trai. Họ đều là những người đẹp trai nhưng hoàn toàn khác biệt về tính cách và cả ba thích Đường Song Ký bởi lúm đồng tiền của cô nàng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xu Kaixin","avatar":""},{"name":"楊仕澤","avatar":""},{"name":"Li Jiahao","avatar":""},{"name":"Estelle Chen","avatar":""},{"name":"Wan Zilin","avatar":""},{"name":"Wang Zhi Yi","avatar":""},{"name":"Liu Xin","avatar":""},{"name":"Liu Yuqiao","avatar":""},{"name":"He Jiayi","avatar":""},{"name":"Li Zhengjun","avatar":""},{"name":"Хоу Мэн Ди","avatar":""},{"name":"Чжу Цзин И","avatar":""},{"name":"Цзя Ци","avatar":""},{"name":"Го Чжэнь Юй","avatar":""},{"name":"Сун Юй Хэ","avatar":""},{"name":"Ван Хао Дун","avatar":""},{"name":"Сюй Цзин Дань","avatar":""},{"name":"Хоу Мэй Цин","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324321);
