INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-yeu-nhau-duoi-anh-trang-tron', 'Hãy Yêu Nhau Dưới Ánh Trăng Tròn', 'Love Under the Full Moon', 'https://phimimg.com/upload/vod/20240814-1/107ffb6479a30e1a1b852f7a064156f4.jpg', 'https://phimimg.com/upload/vod/20240814-1/9be713144d39b0f932ab1f9eaa650e6d.jpg', '<p>Hãy Yêu Nhau Dưới Trăng Tròn (Love Under The Full Moon) xoay quanh câu chuyện cô nàng Lôi Sơ Hạ (do Cúc Tịnh Y thủ vai) bị ảnh hưởng bởi hiệu ứng đêm trăng siêu tròn, không những khiến cô mất trí trí mà còn khiến cuộc sống cô bị đảo lộn, chấm dứt chuỗi ngày êm đềm, bình yên. Kể từ đêm đó Lôi Sơ Hạ bắt đầu chuỗi ngày gắn liền như hình với bóng cùng chàng trai Hứa Hiểu Đông (Trịnh Nghiệp Thành thủ vai). Cuộc sống và chuyện tình của Lôi Sơ Hạ trở nên ngày một đặc biệt hơn sau khi cô nàng trải qua hiện tượng đầy kỳ ảo đó.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"鞠婧禕","avatar":""},{"name":"鄭業成","avatar":""},{"name":"米熱","avatar":""},{"name":"Zheng Fanxing","avatar":""},{"name":"Shen Yao","avatar":""},{"name":"Sun Yining","avatar":""},{"name":"Jiang Shan","avatar":""},{"name":"Xiaosu Zhao","avatar":""},{"name":"Yao Anlian","avatar":""},{"name":"Wang Ting","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324321);
