INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ba-claude', 'Quý Bà Claude', 'Madame Claude', 'https://phimimg.com/upload/vod/20230925-1/7eae525bdda0532ea4ca8c5dc596f29d.jpg', 'https://phimimg.com/upload/vod/20230925-1/8be3a15131b146dc947ea531716965b4.jpg', '<p>Madame Claude kể câu chuyện cuộc đời của “tú bà” Fernande Grudet (1923-2015) có biệt danh Madame Claude - người nắm giữ nhà thổ nổi tiếng ở Paris (Pháp) trong nhiều thập niên. Khi Madame Claude qua đời vào năm 2015 ở tuổi 92, tất cả các tờ báo lớn như Le Monde, Washington Post đều đăng tải những lời vĩnh biệt dành cho người phụ nữ đã trở thành huyền thoại.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Karole Rocher","avatar":""},{"name":"Garance Marillier","avatar":""},{"name":"Roschdy Zem","avatar":""},{"name":"Pierre Deladonchamps","avatar":""},{"name":"Paul Hamy","avatar":""},{"name":"Benjamin Biolay","avatar":""},{"name":"Hafsia Herzi","avatar":""},{"name":"Liah O''Prey","avatar":""},{"name":"Joséphine de la Baume","avatar":""},{"name":"Mylène Jampanoï","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324321);
