INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-than-ban-thai', 'Thực Thần (Bản Thái)', 'Let''s Eat', 'https://phimimg.com/upload/vod/20240811-1/646242f0d1db9a97b32a07f7864b0478.jpg', 'https://phimimg.com/upload/vod/20240811-1/4ece83dd2d72a1ab05edf032a2bd02d2.jpg', '<p>Một nhân viên bảo hiểm viết blog về ẩm thực gặp lại một người bạn từ thời tiểu học có mối thù truyền kiếp với anh ta -- nhưng sau đó lại nhanh chóng trở thành cộng sự của cô ấy.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Apinya Sakuljaroensuk","avatar":""},{"name":"Mawin Taweepol","avatar":""},{"name":"Nat Sakdatorn","avatar":""},{"name":"Maneerat Kam-Uan","avatar":""},{"name":"Rudklao Amratisha","avatar":""},{"name":"จตุรงค์ พลบูรณ์","avatar":""},{"name":"Pisamai Wilaisak","avatar":""},{"name":"Pranapong Khaisang","avatar":""},{"name":"Boy Chokchai Boonvoramatee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324321);
