INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khat-khao-hanh-phuc', 'Khát Khao Hạnh Phúc', 'I Need Romance', 'https://phimimg.com/upload/vod/20240811-1/d51cd9e6b9f9be6b1f174a9d56d30505.jpg', 'https://phimimg.com/upload/vod/20240811-1/e583ba52209fd8e376fb7448b35583d2.jpg', '<p>Một giám đốc tiếp thị thời trang 33 tuổi tại một công ty kênh mua sắm tại nhà đã phát triển một lớp vỏ bên ngoài cứng rắn và gai góc để thành công ở nơi làm việc. Sau nhiều lần thất bại trong các mối quan hệ, cô đã từ bỏ ý định tìm kiếm tình yêu. Một nhạc sĩ 26 tuổi với tinh thần vô tư trở về nhà sau mười bảy năm sống ở nước ngoài. Được nuôi dưỡng bởi bạn của mẹ anh và con gái của bà, người hiện là giám đốc tiếp thị thời trang 33 tuổi. Nhưng cô chỉ nhớ về anh như một đứa trẻ mà cô buộc phải chơi cùng khi mẹ cô quá bận. Khi hai người gặp lại nhau, anh ấy cố gắng hàn gắn cảm giác lãng mạn đã cạn kiệt của cô ấy.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Khemanit Jamikorn","avatar":""},{"name":"Thitipoom Techa-apaikhun","avatar":""},{"name":"Peck Premanat Suwannannon","avatar":""},{"name":"Kannaporn Puangtong","avatar":""},{"name":"Mintita Wattanakul","avatar":""},{"name":"Thames Sanpakit","avatar":""},{"name":"Raweewit Jiraphongkanon","avatar":""},{"name":"Phanuroj Chalermkijporntavee","avatar":""},{"name":"Katareeya Theapchatri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324321);
