INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-ngo-ngao-ban-thai', 'Cô Nàng Ngổ Ngáo (Bản Thái)', 'My Sassy Girl (Thailand Version)', 'https://phimimg.com/upload/vod/20240811-1/1f798d5fbd18180023346f0d64b93409.jpg', 'https://phimimg.com/upload/vod/20240811-1/1f9ebf490076b614d71ee7ac623d5199.jpg', '<p>Một chàng trai trẻ nhìn thấy một người phụ nữ dễ thương, say xỉn đứng quá gần đường ray tại một bến tàu và kéo cô ấy lại. Cô ấy khiến anh ta gặp rắc rối liên tục sau đó, bắt đầu từ bến tàu.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jarinya Sirimongkolsakul","avatar":""},{"name":"ณัฐสิทธิ์ โกฏิมนัสวนิชย์","avatar":""},{"name":"Duangporn Sontikhan","avatar":""},{"name":"Sutthipong Thatphitakkul","avatar":""},{"name":"Pongsapat Kankam","avatar":""},{"name":"Narumon Phongsupan","avatar":""},{"name":"นิติ ชัยชิตาทร","avatar":""},{"name":"Tik Klinsee","avatar":""},{"name":"Attharut Kongrasri","avatar":""},{"name":"Anon Saisangcharn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324321);
