INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-dong-bangkok', 'Báo Động Bangkok', 'Bangkok Breaking', 'https://phimimg.com/upload/vod/20240811-1/1cd334ce9b2d859ee995def8135607e3.jpg', 'https://phimimg.com/upload/vod/20240811-1/7fa526813c28808fef4b680dcda1ad07.jpg', '<p>Đang chật vật kiếm sống ở Bangkok, một người đàn ông tham gia dịch vụ cứu hộ khẩn cấp và nhận ra mình phải làm sáng tỏ một âm mưu có quy mô toàn thành phố.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"ศุกลวัฒน์ คณารศ","avatar":""},{"name":"Sushar Manaying","avatar":""},{"name":"สหจักร บุญธนกิจ","avatar":""},{"name":"Pawarith Monkolpisit","avatar":""},{"name":"Suda Chuenban","avatar":""},{"name":"Panupan Jantanawong","avatar":""},{"name":"นพพันธ์ บุญใหญ่","avatar":""},{"name":"Waratthaya Wongchayaporn","avatar":""},{"name":"Pitchatorn Santinatornkul","avatar":""},{"name":"Daweerit Chullasapya","avatar":""},{"name":"Arisara Wongchalee","avatar":""},{"name":"Sawanee Utoomma","avatar":""},{"name":"Jaytiya Naiwattan","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324321);
