INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-nghi-duong-hoa-sen-trang-phan-1', 'Khu Nghỉ Dưỡng Hoa Sen Trắng (Phần 1)', 'The White Lotus (Season 1)', 'https://phimimg.com/upload/vod/20240809-1/ade1111756c7e16bf79badaa22653a44.jpg', 'https://phimimg.com/upload/vod/20240809-1/200717d8102e7978f6f2cc480f4319da.jpg', '<p>Loạt phim hài châm biếm xã hội lấy bối cảnh ở một khu nghỉ dưỡng nhiệt đới. Mỗi ngày trôi qua, những vị khách hoàn hảo, những nhân viên khách sạn thân thiện và hòn đảo bình dị lại cho thấy 1 bức tranh đen tối khác đằng sau kỳ nghỉ dưỡng thư giãn tưởng như êm đềm.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 14, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"F. Murray Abraham","avatar":""},{"name":"Jennifer Coolidge","avatar":""},{"name":"Adam DiMarco","avatar":""},{"name":"Meghann Fahy","avatar":""},{"name":"Beatrice Grannò","avatar":""},{"name":"Jon Gries","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"Sabrina Impacciatore","avatar":""},{"name":"Michael Imperioli","avatar":""},{"name":"Theo James","avatar":""},{"name":"Aubrey Plaza","avatar":""},{"name":"Haley Lu Richardson","avatar":""},{"name":"Will Sharpe","avatar":""},{"name":"Simona Tabasco","avatar":""},{"name":"Leo Woodall","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324321);
