INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bap-benh-phan-5', 'Bấp Bênh (Phần 5)', 'Insecure (Season 5)', 'https://phimimg.com/upload/vod/20240809-1/a852c3a946a5c233c0c781081ab2f117.jpg', 'https://phimimg.com/upload/vod/20240809-1/7e1588707b07a607a06418ffc0230075.jpg', '<p>Mùa phim cuối cùng tiếp tục theo chân các nhân vật ưa thích của chúng ta khi họ đánh giá các mối quan hệ cả cũ lẫn mới của mình, trong một nỗ lực để xác định ai và cái gì sẽ đồng hành với họ trong chương tiếp theo của cuộc đời.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Issa Rae","avatar":""},{"name":"Yvonne Orji","avatar":""},{"name":"Jay Ellis","avatar":""},{"name":"Natasha Rothwell","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324321);
