INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-qua-nhiet-tinh-phan-11', 'Đừng Quá Nhiệt Tình (Phần 11)', 'Curb Your Enthusiasm (Season 11)', 'https://phimimg.com/upload/vod/20240808-1/9184a8c9b9414dbad0d1ef7b7c8c5337.jpg', 'https://phimimg.com/upload/vod/20240808-1/e8d98f75470736f4fedb91844a858ec8.jpg', '<p>Tầm nhìn hài hước, không theo kịch bản của Larry David, người đóng vai chính mình trong một vũ trụ song song, nơi anh dường như không thể làm bất cứ điều gì đúng đắn, và theo tiêu chuẩn của anh, thì không ai khác có thể làm đúng được.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Larry David","avatar":""},{"name":"Jeff Garlin","avatar":""},{"name":"Susie Essman","avatar":""},{"name":"Cheryl Hines","avatar":""},{"name":"J.B. Smoove","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324321);
