INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-dam-mau', 'Ngồi Nhà Đẫm Máu', 'House Tour', 'https://phimimg.com/upload/vod/20230925-1/c9ba65ba187361e092cf6a4d151993b8.jpg', 'https://phimimg.com/upload/vod/20230925-1/51a1048d6f76f2a178ab05e6d55d883a.jpg', '<p>Năm tên cướp đột nhập vào nhà của một nữ diễn viên nhưng một cuộc chạm trán đẫm máu với cảnh sát xảy ra khiến hai tên cướp còn sống. Không còn lựa chọn nào khác, họ trốn vào trong nhà và phát hiện ra rằng mọi thứ đã được lên kế hoạch.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Cindy Miranda","avatar":""},{"name":"Diego Loyzaga","avatar":""},{"name":"Sunshine Guimary","avatar":""},{"name":"Mark Anthony Fernandez","avatar":""},{"name":"Marco Gomez","avatar":""},{"name":"Rafa Siguion-Reyna","avatar":""},{"name":"Raquel Monteza","avatar":""},{"name":"Jim Pebanco","avatar":""},{"name":"Glen Medalla","avatar":""},{"name":"Massimo Scofield","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324321);
