INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-moi-2021', 'Con Mồi', 'Prey', 'https://phimimg.com/upload/vod/20240807-1/4711f5a568eecbf9e05c3f7f7a1d8ad2.jpg', 'https://phimimg.com/upload/vod/20240807-1/a94ad440e65ebef1cce097ede842f676.jpg', '<p>Con mồi - Prey (2021) là bộ phim thuộc thể loại phiêu lưu, chính kịch, giật gân của Đức. Tác phẩm do Thomas Sieben chịu trách nhiệm chỉ đạo đồng viết kịch bản, với sự tham gia của các diễn viên David Kross, Hanno Koffler và Maria Ehrich.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"David Kross","avatar":""},{"name":"Hanno Koffler","avatar":""},{"name":"Maria Ehrich","avatar":""},{"name":"Robert Finster","avatar":""},{"name":"Yung Ngo","avatar":""},{"name":"Klaus Steinbacher","avatar":""},{"name":"Livia Matthes","avatar":""},{"name":"Nellie Thalbach","avatar":""},{"name":"Natalie Fischer","avatar":""},{"name":"Tim Haberland","avatar":""},{"name":"Patrick Richter","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324321);
