INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-linh-bi-luc', 'Tạ Lĩnh Bí Lục', 'The Kiddie Tomb', 'https://phimimg.com/upload/vod/20240804-1/0542bf042b039b81f3ad1cc9e41a7867.jpg', 'https://phimimg.com/upload/vod/20230908-1/697ebaacce07d54f086d5fd5e03545f9.png', '<p>Phim lấy bối cảnh vào thời kỳ quân phiệt, khi lúc bấy giờ chiến tranh diễn ra khắp nơi, khiến cho người dân rơi vào những hoàn cảnh khó khăn. Giờ đây, buộc phái Tạ Lĩnh cải tạo quy chính, vì thế họ quyết định xuống dưới hầm một lấy số tiền được cất giữ để cứu giúp dân chúng. Giờ đây, vị truyền nhân Giang Vũ đi cùng với người chú hai là Giang Hoài Thụy, dẫn một đội quân Tạ Lĩnh đi vào trong hầm mộ để lấy tiền. Nhưng ở khắp nơi trong ngôi mộ đều có những cơ quan phức tạp và cạm bẫy nguy hiểm, không những thể còn có một bí mật được che giấu hơn ngàn năm.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Shengrong Li","avatar":""},{"name":"Shi Xue Jing","avatar":""},{"name":"Zhang Chun Zhong","avatar":""},{"name":"Zhang Hengrui","avatar":""},{"name":"Ning Xiao Hua","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324321);
