INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-nha-claus-2', 'Gia đình nhà Claus 2', 'The Claus Family 2', 'https://phimimg.com/upload/vod/20231123-1/79675cc4936cbb2ef80f8a9484c04cd9.jpg', 'https://phimimg.com/upload/vod/20231123-1/6ed074686a3019ef02c81018f4c85d94.jpg', '<p>Công việc của Santa là gì? Trao quà. Nhưng khi Jules đảm nhiệm công việc của người ông Noël, anh nhận được lá thư của một bé gái kèm theo lời ước đặc biệt cho ngày lễ.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Jan Decleir","avatar":""},{"name":"Mo Bakker","avatar":""},{"name":"Bracha van Doesburgh","avatar":""},{"name":"Stefaan Degand","avatar":""},{"name":"Eva van der Gucht","avatar":""},{"name":"Josje Huisman","avatar":""},{"name":"Janne Desmet","avatar":""},{"name":"Emma Moortgat","avatar":""},{"name":"Renée Soutendijk","avatar":""},{"name":"Sien Eggers","avatar":""},{"name":"Pommelien Thijs","avatar":""},{"name":"Kürt Rogiers","avatar":""},{"name":"Amber Metdepenningen","avatar":""},{"name":"Pieter Verelst","avatar":""},{"name":"Rashif El Kaoui","avatar":""},{"name":"Carly Wijs","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324321);
