INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('baby-assassins', 'Baby Assassins', 'Baby Assassins', 'https://phimimg.com/upload/vod/20240804-1/e34dd27caa29eb28cc4de10bd2215b2f.jpg', 'https://phimimg.com/upload/vod/20240804-1/98afa408e4aecbb43dc885569e1d934f.jpg', '<p>Chisato và Mahiro là hai cô gái trung học sắp tốt nghiệp. Họ cũng tình cờ là những sát thủ có kỹ năng cao.</p><p>Khi tổ chức mà họ làm việc ra lệnh cho họ ở chung một phòng, mối quan hệ giữa hai người nhanh chóng trở nên tồi tệ.</p><p>Tuy nhiên, khi họ thấy mình bị yakuza nhắm đến, các cô gái nhanh chóng nhận ra rằng họ sẽ phải tìm cách để làm việc cùng nhau.</p>', 'Full', 1, 'single', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Akari Takaishi","avatar":""},{"name":"伊澤彩織","avatar":""},{"name":"Masanori Mimoto","avatar":""},{"name":"Yasukaze Motomiya","avatar":""},{"name":"Takashi Nishina","avatar":""},{"name":"Nagiko Tsuji","avatar":""},{"name":"Yukina Fukushima","avatar":""},{"name":"Atomu Mizuishi","avatar":""},{"name":"Mone Akitani","avatar":""},{"name":"伊能昌幸","avatar":""},{"name":"飛永 翼","avatar":""},{"name":"Yosuke Omizu","avatar":""},{"name":"Satoshi Uekiya","avatar":""},{"name":"Shigeo Ôsako","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324321);
