INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suicide-squad-diep-vu-cam-tu', 'Suicide Squad: Điệp Vụ Cảm Tử', 'The Suicide Squad', 'https://phimimg.com/upload/vod/20231018-1/cc2742e0d2fe391e1d954ca77ed35ca5.jpg', 'https://phimimg.com/upload/vod/20231018-1/ef5603d981230be525a226c1210cd646.jpg', '<p>Chính phủ gửi những siêu tội phạm nguy hiểm nhất trên thế giới - Bloodsport, Peacemaker, King Shark, Harley Quinn và những người khác - đến hòn đảo Corto Maltese xa xôi, đầy kẻ thù. Được trang bị vũ khí công nghệ cao, họ băng qua khu rừng rậm nguy hiểm trong một nhiệm vụ tìm kiếm và tiêu diệt, chỉ có Đại tá Rick Flag trên mặt đất để bắt họ hành xử.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Margot Robbie","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"John Cena","avatar":""},{"name":"Joel Kinnaman","avatar":""},{"name":"Sylvester Stallone","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"Daniela Melchior","avatar":""},{"name":"Michael Rooker","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"Peter Capaldi","avatar":""},{"name":"Alice Braga","avatar":""},{"name":"Pete Davidson","avatar":""},{"name":"Joaquín Cosío","avatar":""},{"name":"Juan Diego Botto","avatar":""},{"name":"Storm Reid","avatar":""},{"name":"Nathan Fillio","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324321);
