INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('suicide-squad-diep-vu-cam-tu', 'Suicide Squad: Điệp Vụ Cảm Tử', 'The Suicide Squad', 'suicide squad: điệp vụ cảm tử the suicide squad margot robbie idris elba john cena joel kinnaman sylvester stallone viola davis david dastmalchian daniela melchior michael rooker jai courtney peter capaldi alice braga pete davidson joaquín cosío juan diego botto storm reid nathan fillio ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-chong-tham-nhung-5-chuong-cuoi', 'Đội Chống Tham Nhũng 5: Chương Cuối', 'G Storm', 'https://phimimg.com/upload/vod/20240802-1/28a5ef9065327e529d4ecda01bbe5014.jpg', 'https://phimimg.com/upload/vod/20240802-1/1cf8cc70416af207cdd08d15c8745b70.jpg', '<p>ICAC tiếp nhận vụ án tàn khốc nhất của mình khi tổ chức cuộc chiến chống buôn người. Phạm vi tiếp cận của những người liên quan rất rộng và tất cả các manh mối đều không dẫn đến đâu. Giám đốc điều tra Lu Zhi Lian giữ vững lập trường của mình trong cuộc chiến chống tham nhũng cuối cùng.Trong khi cùng nhau điều tra một vụ buôn lậu và tham nhũng, Lu Zhi Lian và Cheng Deming đã khám phá ra một tệ nạn buôn người lớn hơn. Vụ việc ngày càng lan rộng vì nó liên quan đến thủ lĩnh nhóm khủng bố King và Xiao Zhuo Ya, người giật dây đằng sau hậu trường.Nó thậm chí còn gợi ý về sự tham gia của một số lãnh đạo cấp cao trong Hải quan Hồng Kông cũng như Chánh án Aima, người đã nhận được lời mời đặc biệt đến Hồng Kông và đặt dưới sự bảo vệ của Liao Bao Qiang. Giữa những dòng chảy ngầm đang dâng trào, khi nào thì sự thật mới lộ diện?</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"古天樂","avatar":""},{"name":"Kevin Cheng","avatar":""},{"name":"張智霖","avatar":""},{"name":"Jessica Hester Hsuan","avatar":""},{"name":"Michael Tse","avatar":""},{"name":"Louis Cheung","avatar":""},{"name":"Bosco Wong","avatar":""},{"name":"BabyJohn Choi","avatar":""},{"name":"廖啟智","avatar":""},{"name":"Lo Hoi-pang","avatar":""},{"name":"Dada Chan","avatar":""},{"name":"Janelle Sing","avatar":""},{"name":"Eddie Kwan Lai-Kit","avatar":""},{"name":"張兆輝","avatar":""},{"name":"Justin Cheung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be1