INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('david-attenborough-su-song-day-mau-sac', 'David Attenborough: Sự Sống Đầy Màu Sắc', 'Life In Colour With David Attenborough', 'https://phimimg.com/upload/vod/20240615-1/d18c28eee289c7b39989543395fbb05c.jpg', 'https://phimimg.com/upload/vod/20240615-1/8aa98d8ddfcefc90e4107718d8910315.jpg', '<p>Sử dụng công nghệ tiên tiến, loạt phim tài liệu này khám phá tự nhiên qua góc nhìn mới: các loài vật dùng màu sắc để sinh tồn và phát triển trong môi trường hoang dã.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324321);
