INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-dai-duong-xanh', 'Trái Tim Đại Dương Xanh', 'The Blue Ocean Diamond', 'https://phimimg.com/upload/vod/20240615-1/c1c31648cb8837fce19a7f543008fce4.jpg', 'https://phimimg.com/upload/vod/20240615-1/366315d58b99ea86ee58335cde493384.jpg', '<p>Trái Tim Đại Dương Xanh (The Blue Ocean Diamond) vietsub xoay quanh chủ một công ty vệ sĩ, một cựu cảnh sát điển trai và rất giỏi võ tên Prompoom. Anh luôn được giao những nhiệm vụ khó. Lúc này, có nhiều tin đồn về một viên kim cương quý giá bị đánh cắp và có rất nhiều kẻ muốn lấy nó. Với trị giá cực lớn, cảnh sát bắt đầu vào cuộc và 10 kẻ tình nghi được cho vào tầm ngắm. Sau đó, Prompoom được chọn để thực hiện nhiệm vụ truy tìm kẻ trộm, người đứng sau điều khiển mọi chuyện là ai. Đồng hành cùng anh là Lisa thông minh xinh đẹp, đồng thời là con gái của chủ nhân viên kim cương. Liệu hai người có thể tìm ra sự thật, bắt gọn tên tội phạm?</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Son Yuke Songpaisan","avatar":""},{"name":"Esther Supreeleela","avatar":""},{"name":"Pang Ornjira Larmwilai","avatar":""},{"name":"Cindy Bishop","avatar":""},{"name":"James Rusameekae Fagerlund","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324321);
