INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luong-nhan-nguy-hiem', 'Lương Nhân Nguy Hiểm', 'A Dangerous Man', 'https://phimimg.com/upload/vod/20240615-1/f3599d757cb4f622c9eea723277765d1.jpg', 'https://phimimg.com/upload/vod/20240615-1/6bbbe1df8e2acfd9ac56fba6301e5ae8.jpg', '<p>Phim kể về Thẩm Khuynh Mi cải nam trang và trở thành Huyện lệnh huyện Quất Tỉnh. Tạ Lâm Châu do một sự cố mà mất trí nhớ, trở thành sư gia mặt lạnh. Từ một hôn quan bị người người chửi bới cho đến vị “thanh thiên” được khen ngợi không thôi, họ đã tạo nên một bộ phim hài kịch đầy vẻ nghiêm túc. Hai người phối hợp ăn ý, từ đó dần nảy sinh tình cảm. Sau khi có tình cảm, Tạ Lâm Châu được cho hay mình là sát thủ, mục tiêu cuối cùng của hắn trước khi bị mất trí nhớ chính là Thẩm Khuynh Mi.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 4, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tiêu Nhiên Tâm","avatar":""},{"name":"Tôn Đống Hàm","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324321);
