INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-mo-but-ky-4-van-dinh-thien-cung', 'Đạo Mộ Bút Ký 4: Vân Đỉnh Thiên Cung', 'The Lost Tomb: Explore With The Note', 'https://phimimg.com/upload/vod/20240615-1/1ff790192745d56b646c49b96e3d0c42.jpg', 'https://phimimg.com/upload/vod/20240615-1/32997a3def9ee0c2594f71c9158e1a88.jpg', '<p>Bộ phim kể về hành trình của Ngô Tà, Vương Bàn Tử, Tiểu Ca, Giải Vũ Thần cùng những người khác phối hợp với cơ quan Nhà nước điều tra băng nhóm trộm cắp buôn lậu cổ vật của Cầu Đức Khảo, cuối cùng tại Vân Đỉnh Thiên Cung ở núi Trường Bạch đã điều tra rõ âm mưu dòm ngó bảo vật quốc gia nhiều năm trời của Cầu Đức Khảo, đồng thời thành công ngăn chặn hành vi trộm mộ của phần tử phạm pháp.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 14, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bạch Chú","avatar":""},{"name":"Triệu Đông Trạch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324321);
