INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-xa-dac', 'Tiểu Xá Đắc', 'A Love For Dillema', 'https://phimimg.com/upload/vod/20240731-1/27267289a6b608e9534852b73d06198d.jpg', 'https://phimimg.com/upload/vod/20240731-1/4bf81fefa2b18df04020c0eff020144e.jpg', '<p>Nam Lệ sầu lo vì thành tích học tập của con gái Hoan Hoan sụt giảm, bắt đầu hiểu được sự cần thiết của học thêm, từ đó Hoan Hoan phải bước đi trên con đường học thêm vất vả. Sau khi cả nhà trải qua bao nhiêu chuyện lớn nhỏ từ lúc Hoan Hoan học tiểu học đến khi lên trung học cơ sở, cuối cùng Nam Lệ và Hạ Quân cũng tỉnh ngộ, quyết định cho con của mình một tuổi thơ vui vẻ.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Song Jia","avatar":""},{"name":"佟大为","avatar":""},{"name":"蔣欣","avatar":""},{"name":"李佳航","avatar":""},{"name":"張國立","avatar":""},{"name":"Wu Yufang","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324321);
