INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-me-dam', 'Người Tình Mê Đắm', 'Haseen Dillruba', 'https://phimimg.com/upload/vod/20231111-1/5d4d8e73b76cd54114c45bd5963c2388.jpg', 'https://phimimg.com/upload/vod/20231111-1/71225dd515b70b85e362c6057ed41edb.jpg', '<p>Đang bị điều tra vì là nghi phạm giết chồng, một người vợ tiết lộ những chi tiết về cuộc hôn nhân đầy chông gai của họ – nhưng dường như chỉ khiến sự thật nhòa đi thêm.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Taapsee Pannu","avatar":""},{"name":"Vikrant Massey","avatar":""},{"name":"Harshvardhan Rane","avatar":""},{"name":"Aditya Srivastava","avatar":""},{"name":"Yamini Das","avatar":""},{"name":"Daya Shankar Pandey","avatar":""},{"name":"Ashish Verma","avatar":""},{"name":"Deepesh Sumitra Jagdish","avatar":""},{"name":"Ashique Hussain","avatar":""},{"name":"Puja Sarup","avatar":""},{"name":"Kunj Anand","avatar":""},{"name":"Amit Singh Thakur","avatar":""},{"name":"Alka Badola Kaushal","avatar":""},{"name":"Atul Tiwari","avatar":""},{"name":"Nilofar Gesawat","avatar":""},{"name":"Vij","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324321);
