INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-mat-hon-nhan', 'Muôn Mặt Hôn Nhân', 'Scenes From A Marriage', 'https://phimimg.com/upload/vod/20240730-1/bb17e8c73824039e2192b3e34f26a831.jpg', 'https://phimimg.com/upload/vod/20240730-1/ac86d4a119744f7a12edd7e57395a206.jpg', '<p>Biên niên sử về nhiều năm tình yêu và sự hỗn loạn gắn kết một cặp vợ chồng người Mỹ đương đại, theo dõi mối quan hệ của họ khi nó tiến triển qua một số giai đoạn liên tiếp: hôn nhân, làm cha mẹ, ngoại tình, ly hôn và những mối quan hệ đối tác sau đó.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 16, 2021, 'Vietsub', 'FHD', 'Thụy Điển', 0, '[{"name":"Jessica Chastain","avatar":""},{"name":"Oscar Isaac","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324321);
