INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-bao-vu', 'Phong Bạo Vũ', 'The Dance of the Storm', 'https://phimimg.com/upload/vod/20240729-1/44980beb317d21f912900fb62f4c3e89.jpg', 'https://phimimg.com/upload/vod/20240729-1/3526ff5dbd86716b1fbc18ef2786b0a1.jpg', '<p>Phong Bạo Vũ xoay quanh nam chính Lý Tuấn Kiệt (Trần Vỹ Đình) là nhân viên của một công ty an ninh thông tin. Trong khi thực hiện nhiệm vụ, anh phát hiện nội bộ công ty và một thế lực đen tối có liên hệ với nhau, dưới sự trợ giúp của đội trưởng đội hành động Chu Tử Huyên (Cổ Lực Na Trát), hai người cùng hợp sức thâm nhập điều tra. Trong qua trình điều tra không ngừng bị các thế lực hãm hại, truy bắt. Cuối cùng bí mật cũng dần dần được phơi bày. Trong quá trình này, Lý Tuấn Kiệt đã dần bị rung động với cô bạn cũ thông minh xinh đẹp và cả hai đã rơi vào lưới tình với nhau.</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"William Chan Wai-Ting","avatar":""},{"name":"古力娜扎","avatar":""},{"name":"郭家豪","avatar":""},{"name":"Cecilia Boey","avatar":""},{"name":"任達華","avatar":""},{"name":"Jiang Wenli","avatar":""},{"name":"Wang Tonghui","avatar":""},{"name":"Gao Liwen","avatar":""},{"name":"Ji Dongran","avatar":""},{"name":"Qin Mingyue","avatar":""},{"name":"Candice Zhao","avatar":""},{"name":"Wu Gang","avatar":""},{"name":"Wang Ji","avatar":""},{"name":"Chen Chuhan","avatar":""},{"name":"Guo Guangping","avatar":""},{"name":"Wang Zhifei","avatar":""},{"name":"Cheng Yusen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324321);
