INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-diet-vong-phan-3', 'Biệt Đội Diệt Vong (Phần 3)', 'Doom Patrol (Season 3)', 'https://phimimg.com/upload/vod/20240729-1/523c292edbccd6c04cb249e4a4980c1f.jpg', 'https://phimimg.com/upload/vod/20240729-1/61882e6356efb68d0e430d77bc4f4e28.jpg', '<p>Doom Patrol là loạt phim truyền hình web của Mỹ được tạo bởi Jeremy Carver cho DC Universe. Dựa trên nhóm siêu anh hùng cùng tên của DC Comics, bộ truyện có Jane, Rita Farr, Vic Stone, Larry Trainor, Cliff Steele, và Chief là thành viên của Doom Patrol. Lấy bối cảnh năm 2019, nhóm Doom Patrol - bao gồm Robotman, Negative Man, Elasti-Woman, Crazy Jane cùng thành viên mới Cyborg dưới sự dẫn dắt của Dr. Niles Caulder - nhận nhiệm vụ bảo vệ thế giới khỏi kẻ thù nguy hiểm tên là Mr. Nobody.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Diane Guerrero","avatar":""},{"name":"April Bowlby","avatar":""},{"name":"Joivan Wade","avatar":""},{"name":"Skye Roberts","avatar":""},{"name":"Riley Shanahan","avatar":""},{"name":"Matthew Zuk","avatar":""},{"name":"Matt Bomer","avatar":""},{"name":"Brendan Fraser","avatar":""},{"name":"Michelle Gomez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324321);
