INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-that-chi-vi-sinh-ra-truoc', 'Yêu Thật Chỉ Vì Sinh Ra Trước', 'May-December Romance', 'https://phimimg.com/upload/vod/20240615-1/119ba1bc92e55d2efe6a3d5c45d8e6c1.jpg', 'https://phimimg.com/upload/vod/20240615-1/540e679c60b4b1e0d8abd2f9e6994e12.jpg', '<p>Orn bị đá lúc 52 tuổi. Cuộc \đại trùng tu\ khiến cô về tuổi 25 một lần nữa. Cô dành tình cảm cho Tom, vận động viên bóng bàn trẻ hơn cô đến mức có thể làm con của cô. Tom bị bắt vì dùng thuốc cấm mà không biết nó là của Tar, anh trai Tom. Tar là bác sĩ đang chịu nợ nần do bài bạc. Mint thì luôn lưỡng lự trong những chuyện liên quan đến Tar. Cô nên thuyết phục người mình thích cai nghiện cờ bạc hay quên nó đi luôn? Danai, chủ tịch Hiệp hội Tennis bỗng dưng thay đổi và muốn quay lại với Orn. Một sinh viên đại học tên May có vẻ không quan tâm vấn đề tuổi tác của Danai. Cô còn thấy anh là một người đàn ông cổ điển. Liệu tình yêu có vượt trên cả tuổi tác? Hãy tìm hiểu qua bộ phim \Yêu Thật Chỉ Vì Sinh Ra Trước\ trên iQiyi.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Chakrit Yamnam","avatar":""},{"name":"Yam Matira Tantiprasut","avatar":""},{"name":"Ryu Vachirawich Wattanapakdeepaisan","avatar":""},{"name":"Bomb","avatar":""},{"name":"Mint Ranchrawee Uakoolwarawat","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324321);
