INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ve-zombie', 'Chuyện Về Zombie', 'Story Of Zom-B', 'https://phimimg.com/upload/vod/20240615-1/4db90b6c22ce5b9447126defa19b9821.jpg', 'https://phimimg.com/upload/vod/20240615-1/23e051d371f22b4c7f08951c9ad8fac8.jpg', '<p>Câu chuyện về một chàng điển trai là zombie nhưng B vẫn có ý thức con người, chỉ phát điên khi lên cơn thèm não mà thôi. Khi ăn não một nạn nhân nào đó, B có được cả ký ức năm xưa của người này. Nhờ đó, B học được ý nghĩa cuộc sống và tầm quan trọng của gia đình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2021, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Hà Quảng Bái","avatar":""},{"name":"Giang Gia Mẫn","avatar":""},{"name":"Quách Tử Hào","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324321);
