INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-trang-khong-hieu-long-toi', 'Ánh Trăng Không Hiểu Lòng Tôi', 'Love Under The Moon', 'https://phimimg.com/upload/vod/20240615-1/540037563675820dcc798c47f6e829d6.jpg', 'https://phimimg.com/upload/vod/20240615-1/c72b8069ded9afa6fb5160021364f0d3.jpg', '<p>Thời Gian Tươi Đẹp Của Anh Và Em chuyển thể từ tiểu thuyết cùng tên của Đinh Mặc. Bộ phim xoay quanh cuộc chiến đấu giành lại quyền kinh doanh và quản lý của tập đoàn của gia tộc Lệ Trí Thành (Kim Hạn). Lệ Trí Thành là một thiếu tá không có nhiều kinh nghiệm trong việc quản lý và kinh doanh. Từ khi gia tộc gặp khó khăn, anh phải trở về giúp đỡ công việc làm ăn. Tuy nhiên, mặc dù trở thành chủ tịch nhưng Lệ Trí Thành không nhận được sự ủng hộ của thành viên tập đoàn. Lúc này, nhờ sự giúp đỡ của Lâm Thiển (Triệu Lệ Dĩnh), Lệ Trí Thành ngày càng được sự chấp thuận của tập đoàn. Trong công cuộc dành lại uy tín, Lệ Trí Thành còn có được cả trái tim của Lâm Thiển.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Triệu Lệ Dĩnh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324321);
