INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-chi-la-hat-bui', 'Cũng Chỉ Là Hạt Bụi', 'Sweet Teeth', 'https://phimimg.com/upload/vod/20240718-1/a858d7c8032e10283cfef117f01bf649.jpg', 'https://phimimg.com/upload/vod/20240718-1/b1f51a41e36d538200c04998e8a08fe7.jpg', '<p>Khi còn trẻ, Ngải Cảnh Sơ (Tất Văn Quân đóng) ngoài ý muốn nhận được bức thư tình Tăng Lý (Ngô Tuyên Nghi đóng) viết cho tình đầu Vu Dịch (Trạch Tiêu Văn đóng), duyên phận của hai người bắt đầu từ đó. Nhiều lần liên hệ và gặp mặt, duyên phận từ người lạ tới một cuộc điện thoại, rồi quen biết từ mói quan hệ bác sĩ - bệnh nhân tới người yêu. Hai trái tim cô đơn khát vọng ấm áp, lại gần nhau, chữa trị cho nhau…</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 5, 2021, 'Vietsub', 'FullHD', 'Trung Quốc', 0, '[{"name":"Wu Xuanyi","avatar":""},{"name":"畢雯珺","avatar":""},{"name":"翟瀟聞","avatar":""},{"name":"Zhang Baijia","avatar":""},{"name":"劉特","avatar":""},{"name":"Wan Zilin","avatar":""},{"name":"米熱","avatar":""},{"name":"Chen Yijing","avatar":""},{"name":"Hou Tongjiang","avatar":""},{"name":"Qie Lutong","avatar":""},{"name":"Cen Ming","avatar":""},{"name":"Cheng Min","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324321);
