INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quoc-tu-giam-co-mot-nu-de-tu', 'Quốc Tử Giám Có Một Nữ Đệ Tử', 'A Female Student Arrives At The Imperial College', 'https://phimimg.com/upload/vod/20240615-1/1fd5777e089a49657b34a9b93d4c69f9.jpg', 'https://phimimg.com/upload/vod/20240615-1/c6e508926f28c7cdd11081dbeb0e8b0d.jpg', '<p>Quốc Tử Giám Có Một Nữ Đệ Tử là câu chuyện kể về nữ đệ tử đầu tiên của Quốc Tử Giám – Tang Kỳ (Triệu Lộ Tư đóng). Tang Kỳ vì thua một cuộc cá cược nên đành phải chịu thử thách là khiến cho Đệ Nhất Công Tử Đại Yên – Yến Vân (Từ Khai Sính đóng) nhận túi thơm – một vật “bất khả ly thân” của các nữ nhi thời xưa và đồng ý đến gặp cô tại lễ hội Hoa Đăng. Kế hoạch tiếp cận của cô nàng là gì? Nữ đệ tử duy nhất của Quốc Tử Giám sẽ đối mặt với các tình huống dở khóc dở cười ra sao?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 4, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Đỗ Dục","avatar":""},{"name":"Ngao Thụy Bằng","avatar":""},{"name":"Nhậm Hào","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324321);
