INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-chien-ii-ban-mau-duong-toi-chien-thang', 'Thế Chiến II Bản Màu: Đường Tới Chiến Thắng', 'WWII In Color: Road To Victory', 'https://phimimg.com/upload/vod/20240615-1/77738b5bbd5ddc4378e7ec7646d125b1.jpg', 'https://phimimg.com/upload/vod/20240615-1/a537c3b28f608d8944c2049dae1fd611.jpg', '<p>Những thước phim lịch sử hấp dẫn và lời bình của chuyên gia mang đến thông tin chuyên sâu về các nhân vật hàng đầu và những bước ngoặt quyết định trong Thế chiến II.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324321);
