INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-chien-ii-ban-mau-duong-toi-chien-thang', 'Thế Chiến II Bản Màu: Đường Tới Chiến Thắng', 'WWII In Color: Road To Victory', 'thế chiến ii bản màu: đường tới chiến thắng wwii in color: road to victory  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gen-y-the-series-phan-2', 'Gen Y The Series (Phần 2)', 'Gen Y The Series (Season 2)', 'https://phimimg.com/upload/vod/20240615-1/d1af45acc99cfc5b52fd0c68ff9298cc.jpg', 'https://phimimg.com/upload/vod/20240615-1/866ca2c753d588da6b59061ec8d52b0e.jpg', '<p>Giải quyết những hiểu lầm, thất vọng ở phần trước, đặc biệt là chuyện tình kết thúc đột ngột của Pha và Wayu. Sau đó lại là mối tình vội vàng giữa Thanu và Wayu, cả hai nhanh tiến tới hẹn hò vì cảm xúc nhất thời nhưng có lẽ không dễ dàng vì mối quan hệ không rõ ràng giữa Phai và Thanu. Đồng thời, trước khi quyết định tạm dừng cả Kit và Mark gặp vấn đề với khoảng cách và thời gian, buộc họ phải tập trung vào việc tạm thời xa nhau một thời gian để nghĩ về đối phương nhiều hơn. Phim Gen Y The Series Phần 2 còn là câu chuyện của nhân vật Pok đang phải nỗ lực rất nhiều để tốt hơn cho Tong nhưng anh cảm thấy mình luôn là người làm Tong cảm thấy thất vọng cho mỗi chuyện xảy ra. Bên cạnh đó, Tong đã cố gắng dành tất cả những gì tốt nhất cho Pok vì đơn giản anh nghĩ rằng người anh yêu xứng đáng được hạnh phúc nhưng anh ấy đã hiểu lầm rằng Pok không bao giờ muốn điều đó. Cuối cùng là trong khi Wayu bắt đầu mở lòng với một mối quan hệ mới, thì vấn đề của Mark và Kit, mâu thuẫn của Pok và Tong. Câu chuyện tình ở Gen Y 2 hứa hẹn sẽ phức tạp và đầy sóng gió hơn cho những chàng trai này.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 4, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Bas Suradet Piniwat","avatar":""},{"name":"Dun Romchampa","avatar":""},{"name":"Big Thanakorn Kuljarassombat","avatar":""},{"name":"Kimmon Warodom Khemmonta","avatar":""},{"name":"Copter Panuwat Kerdthongtavee","avatar":""},{"name":"Bank Thoranin Manosudprasit","avatar":""},{"name":"Bonus Thanadech Deeseesuk","avatar":""},{"name":"Bank Thanathip Srithongsuk","avatar":""},{"name":"Pon Thanapon Aiemkumchai","avatar":""},{"name":"Kad Ploysupa","avatar":""},{"name":"Bank The","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324321);
