INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-ty-quai-vat-2021', 'Công Ty Quái Vật', 'Monsters At Work', 'https://phimimg.com/upload/vod/20240615-1/4f5823d7503f88289b56c210aa550a28.jpg', 'https://phimimg.com/upload/vod/20240615-1/f08eef3c5e504acd0d1b9be4a5df6c71.jpg', '<p>Monster At Work sẽ lấy bối cảnh 6 tháng sau sự kiện của Monster, Inc. Vào thời điểm này, công ty đã chuyển từ kinh doanh tiếng thét trẻ em sang nụ cười của chúng để tạo ra nguồn năng lượng cho thế giới quái vật. Mike và Sully lúc này đã được giao công việc quản lý Đơn vị phát hiện trẻ em. Mike rất là phấn khởi khi được thăng chức nhưng Sully thì tỏ vẻ e dè. Mike khẳng định rằng anh sẽ ban hành các quy định để tiếng cười đến khắp mọi nơi trong Công ty quái vật.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 5, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Billy Crystal","avatar":""},{"name":"Ben Feldman","avatar":""},{"name":"Mindy Kaling","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324321);
