INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-hoa-diem-lam', 'Xin Chào, Hỏa Diễm Lam', 'The Flaming Heart', 'https://phimimg.com/upload/vod/20240615-1/f52c6c70a612da214590d9e28fcdc1ee.jpg', 'https://phimimg.com/upload/vod/20240615-1/9caea335addcd9d879b5dace213ff5ab.jpg', '<p>Xin Chào, Ngọn Lửa Xanh xoay quanh nhân vật Hoắc Tư Yến (do Cung Tuấn thủ vai). Sau khi Hoắc Tư Yến tốt nghiệp Học viện Dân phòng, anh trở thành đội phó của Đội cứu hỏa. Trong một lần giải cứu người phụ nữ mang thai khỏi xe giao hàng, anh đã tình cờ gặp được Diễm Lam (do Trương Tuệ Văn thủ vai) – một bác sĩ làm việc tại Khoa Cấp cứu của bệnh viện. Công việc của cả hai đều mang yếu tố vô cùng khắc nghiệt có thể hy sinh bất cứ lúc nào, nhiều lần làm nhiệm vụ, cả hai suýt phải mất mạng, họ đối mặt với sự thật tàn khốc của tình huống khẩn cấp nhưng cũng vì thế mà tình cảm càng bền chặt hơn, không gì có thể chia cắt.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 4, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Châu Ngạn Thần","avatar":""},{"name":"Cung Tuấn","avatar":""},{"name":"Trương Tuệ Văn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324321);
