INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-hiep-si-tu-noi-tan-cung', 'Thánh Hiệp Sĩ Từ Nơi Tận Cùng', 'Paladin Of The End, Ultimate Paladin, The Faraway Paladin, Saihate No Paladin', 'https://phimimg.com/upload/vod/20240615-1/a0b03cbd001e29f541b1095ef4d13c1d.jpg', 'https://phimimg.com/upload/vod/20240615-1/4efe776f3fa0c1a94e949a5da200e836.jpg', '<p>Câu chuyện kể về Will, cậu bé duy nhất trong thế giới của người chết. Cậu được nuôi nấng bởi ba xác sống Blood, Mary và Gus. Will bắt đầu thắc mắc “Mình là ai?” và cậu sẽ đi tìm câu trả lời cho bí ẩn về vùng đất chết chóc nơi phương xa này, cũng như hé lộ được bí mật về quá khứ của ba undead kia.&nbsp;</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324321);
