INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-ranh-2021', 'Lằn Ranh', 'The Line', 'https://phimimg.com/upload/vod/20240615-1/e1eaa2e3095bb6f7ccf2dfed8fa5b33b.jpg', 'https://phimimg.com/upload/vod/20240615-1/b58b1dc01de6c36c1c0a3a9a1823edb4.jpg', '<p>Trong chiến tranh bí mật hiện đại, ranh giới giữa đúng và sai đã mờ đi. Loạt phim tài liệu này xem xét sự mơ hồ về đạo đức của chiến tranh được thể hiện qua vụ án năm 2018, trong đó một trung đội SEAL của Hải quân Hoa Kỳ cáo buộc chỉ huy của nó, Eddie Gallagher, về tội ác chiến tranh.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brad Hebert","avatar":""},{"name":"Alex Gibney","avatar":""},{"name":"Jeff Zimbalist","avatar":""},{"name":"Michael Zimbalist","avatar":""},{"name":"Stacey Offman","avatar":""},{"name":"Richard Perello","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324321);
