INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('johnny-test-phan-2', 'Johnny Test (Phần 2)', 'Johnny Test (Season 2)', 'https://phimimg.com/upload/vod/20240615-1/c26896fb96cdecc27ff5df7c0167dd12.jpg', 'https://phimimg.com/upload/vod/20240615-1/c193dee21766695e590d4efedf4fa93e.jpg', '<p>Từ trò phù thủy thực tế ảo đến giết quái vật ngoài đời thật, Johnny và Dukey lao vào một loạt những cuộc phiêu lưu điên rồ hiếm khi diễn ra theo kế hoạch.</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 4, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Arnold Taylor","avatar":""},{"name":"Trevor Devall","avatar":""},{"name":"Maryke Hendrikse","avatar":""},{"name":"Emily Tennant","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324321);
