INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('takt-opdestiny', 'Takt Op.Destiny', 'Takt Op.Destiny', 'https://phimimg.com/upload/vod/20240615-1/1f579b8d81b99b5d8f6d4118afe7c140.jpg', 'https://phimimg.com/upload/vod/20240615-1/b0cac40f2db44eda4c8c3bdac76f9bcb.jpg', '<p>Một ngày nọ, một thiên thạch đen rơi xuống thế giới và khiến thế giới thay đổi hoàn toàn. Thiên thạch đó tạo ra những quái vật kì dị gọi là D2 chạy loạn khắp nơi. D2 nhanh chóng cấm tất cả âm nhạc, bởi đó là thứ có thể hạ gục chúng. Nhưng một số người đã chống lại D2. Họ là Musicart - những cô gái trẻ nắm giữ sức mạnh của âm nhạc và có thể đánh bại đám quái vật này. Người dẫn dắt họ là Conductor.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Lin Mo","avatar":""},{"name":"Lục Di Tuyền","avatar":""},{"name":"FU","avatar":""},{"name":"Chi Yi","avatar":""},{"name":"Tôn Diệc Hàng","avatar":""},{"name":"Yu Mu Yang","avatar":""},{"name":"Yan Ke","avatar":""},{"name":"Lạc Tuấn Phàm","avatar":""},{"name":"He Luo Luo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324321);
