INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-toi-cua-binh-yen', 'Mặt Tối Của Bình Yên', 'Hometown', 'https://phimimg.com/upload/vod/20240615-1/c08d407b95cdec271b978a4600cccd83.jpg', 'https://phimimg.com/upload/vod/20240615-1/06762407b4fb5b91c1a7a05b498b0fa8.jpg', '<p>Ở một thị trấn nhỏ năm 1999, em gái tên khủng bố bị kết án tham gia cuộc điều tra của một thanh tra về loạt băng ghi âm kỳ quái ghi lại các vụ giết người hàng loạt.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yoo Jae Myung","avatar":""},{"name":"Han Ye Ri","avatar":""},{"name":"Uhm Tae Goo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324321);
