INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-phuc-chung-cu-co-doc-happiness', 'Hạnh Phúc: Chung Cư Có Độc (Happiness)', 'Happiness', 'https://phimimg.com/upload/vod/20240615-1/66854f989aceda97a50690b12750b928.jpg', 'https://phimimg.com/upload/vod/20240615-1/b4c043efc1d9dabff2bb36a6b4880027.jpg', '<p>Hạnh Phúc: Chung Cư Có Độc (Happiness 2021) kể về câu chuyện tại một tòa chung cư mới được xây dựng trong thành phố lớn. Tầng cao dành cho tầng lớp người giàu, tầng thấp để người thuê sống. Một hôm, bệnh truyền nhiễm mới bùng phát và hoàn hành khắp nơi trong thành phố. Nhằm phòng ngừa dịch bệnh lan truyền, tòa chung cư đã bị phong tỏa. Do nỗi sợ với vi-rút và mâu thuẫn giữa tầng lớp khác nhau, các cư dân đành phải nỗ lực tìm cách sinh tồn nơi chung cư có độc này.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Han HyoJoo","avatar":""},{"name":"Park Hyung Sik","avatar":""},{"name":"Woo-jin Jo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324321);
