INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kich-ban-cuoc-doi', 'Kịch Bản Cuộc Đời', 'Scripting Your Destiny', 'https://phimimg.com/upload/vod/20240615-1/c5ddd2947af118821e0cbc860f3e9041.jpg', 'https://phimimg.com/upload/vod/20240615-1/0cf72ad0a7a7d3197c36b66bc232fdf0.jpg', '<p>Câu chuyện lãng mạn giữa vị thần Shin Hoyoon (Ki Dohoon đóng) có thể viết nên số phận của con người cùng biên kịch Go Chekyung (Jeon Sonee đóng) bề ngoài bình thường nhưng thật ra đang giấu diếm thân phận bí mật. Thân phận của Shin Hoyoon có thể viết nên số phận của con người ở nhân gian là chủ một tòa nhà đẹp trai giàu có. Một ngày nọ, anh ấy phụ trách viết nên số phận của biên kịch Go Chekyung đang ở trong tòa nhà của mình, nhưng vì không có kinh nghiệm trong chuyện tình cảm nên anh ấy đã trộm lấy tình tiết trong một cuốn tiểu thuyết Go Chekyung đã viết lúc học cấp ba, thế nên Go Chekyung gặp PD của phim, đồng thời luôn gặp phải những tình tiết trong cuốn tiểu thuyết đầu tiên của mình, Go Chekyung dần phát hiện ra thân phận bí mật của Shin Hoyoon......</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 15, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Quan Su Ni","avatar":""},{"name":"Do-hun Ki","avatar":""},{"name":"Ge Su Yuan","avatar":""},{"name":"Park Sang-nam","avatar":""},{"name":"Kim Woo Suk","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324321);
