INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-hop-dong', 'Tình Yêu Hợp Đồng', 'Contractual Love', 'https://phimimg.com/upload/vod/20240615-1/b4e08fb3508d391ef559cf8cdf5c3f5a.jpg', 'https://phimimg.com/upload/vod/20240615-1/e8c34ca34ea825a7879043259d69de12.jpg', '<p>Nó kể về câu chuyện của Huang Zixuan, một cô gái đến từ một thành phố hạng mười ba, để trả món nợ khổng lồ của cha cô, và ký một thỏa thuận với Leng Yaozu, chủ một cửa hàng làm đẹp, và cả hai trở thành &nbsp;anh em hợp đồng. Sau khi phát hiện ra danh tính điệp viên hai mang của Huang Zixuan, người giàu nhất thủ đô và cô gái giàu có ở Bắc Kinh đã bắt đầu một câu chuyện thót tim.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 8, 2021, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Cheng Lei","avatar":""},{"name":"Zheng Miao","avatar":""},{"name":"Niu Xin","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324321);
