INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-mat-cuoc-song', 'Muôn Mặt Cuộc Sống', 'Good Life', 'https://phimimg.com/upload/vod/20240615-1/0d7a0adbee30f708db010f7a84e82dad.jpg', 'https://phimimg.com/upload/vod/20240615-1/3c83ab5f35839c4089d82f584b06736a.jpg', '<p>Bộ phim tập trung vào một gia đình năm người vừa hạnh phúc vất vả, vừa tràn đầy ấm áp nhưng cũng đầy mâu thuẫn, vừa bình thường nhưng cũng vừa đặc biệt. Câu chuyện kể về việc người cha tỉnh lại sau khi hôn mê đã lâu, tự nghĩ về chính mình, đồng thời thông qua nhiều sự kiện dở khóc dở cười, giúp bốn đứa con tìm lại cuộc sống, thấu hiểu hơn và ôm lấy cuộc đời.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 9, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"LiuWei","avatar":""},{"name":"Angel Wang","avatar":""},{"name":"Tôn Nghệ Châu","avatar":""},{"name":"Dai Xu","avatar":""},{"name":"Koala","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324321);
