INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-lung-nhung-bac-thay-gia-mao', 'Săn Lùng Những Bậc Thầy Giả Mạo', 'The Puppet Master: Hunting The Ultimate Conman', 'https://phimimg.com/upload/vod/20240608-1/044fd13a9d086215fc58c27640d27895.jpg', 'https://phimimg.com/upload/vod/20240608-1/447daf9f4ff2c3a7dc812729994e466f.jpg', '<p>Trong loạt phim tài liệu bi ai này, tên lừa đảo hung ác giả mạo điệp viên Anh để thao túng và chiếm đoạt của các nạn nhân, khiến nhiều gia đình bị hắn hủy hoại.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324322);
