INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-giac-2021', 'Thức Giấc', 'Open Your Eyes', 'https://phimimg.com/upload/vod/20240608-1/ecf5dcb71182277660ec70d41011fdb8.jpg', 'https://phimimg.com/upload/vod/20240608-1/c473a17723e20fb4689323924d9ed66e.jpg', '<p>Phim chưa có nội dung.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 15, 2021, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Maria Wawreniuk","avatar":""},{"name":"Ignacy Liss","avatar":""},{"name":"Michał Sikorski","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324322);
