INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thuc-giac-2021', 'Thức Giấc', 'Open Your Eyes', 'thức giấc open your eyes maria wawreniuk ignacy liss michał sikorski ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-doi-mot-kiep-nhat-sinh-nhat-the', 'Một Đời Một Kiếp (Nhất Sinh Nhất Thế)', 'Forever And Ever', 'https://phimimg.com/upload/vod/20240608-1/1e4e4abdcd3156b603d67ae76f7ce8fb.jpg', 'https://phimimg.com/upload/vod/20240608-1/ca5c8773e4cd0b3bced24397332eb86f.jpg', '<p>Một Đời Một Kiếp (Nhất Sinh Nhất Thế, Forever and Ever) kể về mối lương duyên giữa diễn viên lồng tiếng hàng đầu Thời Nghi (Bạch Lộc) dịu dàng, hiền lành, khiêm tốn và giáo sư hóa học lịch lãm Châu Sinh Thần (Nhậm Gia Luân). Dù mới gặp nhau lần đầu tại sân bay nhưng họ như đã quen biết từ lâu. Để cứu sản nghiệp gia đình, Châu Sinh Thần đồng ý điều kiện với mẹ và đề nghị đính hôn với Thời Nghi, người anh có cảm tình. Hai người dần nảy sinh tình cảm. Khi Châu Sinh Thần phải đối diện với khó khăn khắp nơi, Thời Nghi vẫn luôn ở bên anh. Cuối cùng, châu Sinh Thần bị kẻ gian hãm hại, Thời Nghi vì cứu anh mà bị thương rồi hôn mê. Dưới sự chăm sóc tận tâm của Châu Sinh Thần, Thời Nghi cũng tỉnh lại và hai người hứa hẹn bên nhau mãi mãi. Cặp nam, nữ chính Bạch Lộc và Nhậm Gia Luân cũng đảm nhiệm vai chính trong bộ phim cổ trang tình yêu được yêu thích gần đây - \Trường An Như Cố\.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Bạch Lộc","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324322);
