INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhoc-vu-tru-phan-2', 'Siêu Nhóc Vũ Trụ (Phần 2)', 'Kid Cosmic (Season 2)', 'https://phimimg.com/upload/vod/20240608-1/2e1f4bc2c7cee0ccb3d40e2c4b827645.jpg', 'https://phimimg.com/upload/vod/20240608-1/3fbc95ddd35dc8363710c548e0b27d96.jpg', '<p>Jo học được ý nghĩa của việc trở thành thủ lĩnh thực thụ khi các Anh hùng Địa phương phiêu lưu ngoài vũ trụ để tìm những viên Đá Sức Mạnh còn lại và cứu thiên hà.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Fisher","avatar":""},{"name":"Tom Kenny","avatar":""},{"name":"Amanda C. Miller","avatar":""},{"name":"Kim Yarbrough","avatar":""},{"name":"Keith Ferguson","avatar":""},{"name":"Grey Griffin","avatar":""},{"name":"Lily Rose Silver","avatar":""},{"name":"Fred Tatasciore","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324322);
