INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-ket-ruc-do', 'Liên Kết Rực Đỏ', 'SCARLET NEXUS', 'https://phimimg.com/upload/vod/20240608-1/314e9dc12e1cd5c0f9a8817457665e91.jpg', 'https://phimimg.com/upload/vod/20240608-1/4321963ca483ba710f8cdda0d1c65345.jpg', '<p>Năm 2020 theo lịch mặt trời: Những sinh vật kỳ dị được gọi là Quái đã bắt đầu ăn thịt người. Để hạ gục kẻ thù mới này, Quân Đàn Áp Quái được thành lập. Được cứu bởi đội ưu tú này khi còn nhỏ, Yuito chịu quá trình huấn luyện để nhập ngũ. Mặt khác, thần đồng Kasane được chiêu mộ nhờ khả năng của mình. Nhưng giấc mơ của Kasane cho cô biết nhiều điều kỳ lạ, kéo cả hai vào một định mệnh khó tránh khỏi.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 5, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324322);
