INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-khoi-lac-duong-thieu-nien-than-co-2021', 'Phong Khởi Lạc Dương: Thiếu Niên Thần Cơ', 'Luoyang (anime)', 'https://phimimg.com/upload/vod/20240608-1/1b43bf48338d0a45e60752af960544fb.jpg', 'https://phimimg.com/upload/vod/20240608-1/89735d6d4d75e9994112af31870f1070.jpg', '<p>Thời kỳ Võ Chu, Võ Tắc Thiên phát triển rộng chế độ khoa cử nghiêm khắc mà ảnh hướng đến lợi ích của các thế gia truyền thống. Họ chuẩn bị ngăn cản Võ Tắc Thiên lên ngôi. Chính trong bối cảnh vậy, nhân vật chính Bùi Khôn đến với thần đô Lạc Dương và bị cuốn vào âm mưu của Xuân Thu Đạo. Cuối cùng chàng lại bất ngờ phá vỡ âm mưu lớn này.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 16, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324322);
