INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-chua-30', 'Vẫn Chưa 30', 'How To Be Thirty', 'https://phimimg.com/upload/vod/20240608-1/f8f86a8d8c4d02142bc9c6e0074fbac1.jpg', 'https://phimimg.com/upload/vod/20240608-1/8d40d98e65af60c01f391236da18d7b8.jpg', '<p>Vẫn Chưa 30 Giới thiệu: Đây là câu chuyện về những chuyện xảy ra sau khi anh chàng họa sĩ truyện tranh 31 tuổi gặp lại tình yêu tuổi trăng tròn giờ đã là một người đại diện của nhà xuất bản. Tác phẩm này chủ yếu xoay quanh những rắc rối đời thường và thế giới tình cảm của những con người đang trong độ tuổi 30.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 4, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kang Min Hyuk","avatar":""},{"name":"Jung In-sun","avatar":""},{"name":"Ahn Hee Yeon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324322);
