INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-can-nao-2021', 'Trò Chơi Cân Não', 'The Mind Game', 'https://phimimg.com/upload/vod/20240608-1/ffb8f45f014536012e68895fd916829b.jpg', 'https://phimimg.com/upload/vod/20240608-1/a550051a67e2ce4e59104a7519514fa9.jpg', '<p>Trò Chơi Cân Não (The Mind Game) vietsub kể về Thatthai sau một lần thoát chết một cách thần kỳ trong một vụ tai nạn nghiêm trọng, anh bỗng sở hữu khả năng đặc biệt: đọc được suy nghĩ của người khác. Nhưng rồi số phận lại xoay chuyển khi anh vô tình trở thành kẻ tình nghi trong một vụ án. Với sự giúp đỡ của những người bạn, Thatthai bắt đầu cuộc hành trình truy đuổi những tên tội phạm thực sự và chứng minh mình vô tội.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Bank Thiti Mahayotaruk","avatar":""},{"name":"Oab Oabnithi Wiwattanawarang","avatar":""},{"name":"Peak Pattarasaya Kreursuwansiri","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324322);
