INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-ech', 'Hoàng Tử Ếch', 'Frog Prince', 'https://phimimg.com/upload/vod/20240608-1/0eec10852c93505192ae35d413120930.jpg', 'https://phimimg.com/upload/vod/20240608-1/e5715b43c46bab1de7f651e93e932d6b.jpg', '<p>Bộ phim xoay quanh 2 nhân vật chính Looktarn và Khin. Looktarn là một cô gái thông minh, luôn muốn bảo vệ quê hương Chuen Chiva khỏi những tên kinh doanh tham lam. Khin - một doanh nhân lạnh lùng - có kế hoạch xây dựng một khu nghỉ dưỡng cao cấp ở đây. Tuy nhiên, do một tai nạn bất ngờ, Kin bị mất trí nhớ và trở nên rất tốt bụng. Looktarn và Khin đã có một tình yêu đẹp nhưng tiếc rằng không kéo dài khi Khin dần hồi phục trí nhớ. Liệu Looktarn có thể khiến Khin yêu lại cô ấy không?</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Will Wannarot","avatar":""},{"name":"Son Yuke","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324322);
