INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-tac-song-canh-nha-toi', 'Đối Tác Sống Cạnh Nhà Tôi', 'Party A Who Lives Beside Me', 'https://phimimg.com/upload/vod/20240608-1/1c2f1c8b2c1b2af3a2ae221460bd32bb.jpg', 'https://phimimg.com/upload/vod/20240608-1/52b65310ee28839cfef0f2ab02dd2a44.jpg', '<p>Xiaobai Ye Xuan (do Wang Zixuan thủ vai), người có ước mơ ở nơi làm việc cục cay, gặp Li Zenan (do Xie Binbin thủ vai), một người hàng xóm ưu tú của những người làm nghề trôi dạt Thượng Hải, người đang làm rõ món súp trong quá trình của than phiền về nơi làm việc, hai người “có tâm tư thầm kín”. Như mọi người đã biết, thân phận thực sự của Li Zenan chính là cha của bên A, người đã gây khó dễ cho Dương Tử Quỳnh. Cả hai phải đối mặt với nghịch cảnh trong cuộc khủng hoảng nơi làm việc, và khi họ đang điều tra sự thật, họ tin tưởng nhau và bắt đầu câu chuyện tình hàng xóm thành thị giữa Bên B động vật xã hội và bên A ác quỷ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xie Binbin","avatar":""},{"name":"Wang Zixuan","avatar":""},{"name":"Zhai Guanhua","avatar":""},{"name":"Zhu Ran","avatar":""},{"name":"Ke Ying","avatar":""},{"name":"Liu Zhehui","avatar":""},{"name":"Chen Mengxi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324322);
