INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ridley-jones-phan-2', 'Ridley Jones (Phần 2)', 'Ridley Jones (Season 2)', 'https://phimimg.com/upload/vod/20240608-1/8e1b271f717d99e7ea475759bf9d0a80.jpg', 'https://phimimg.com/upload/vod/20240608-1/614dd69792cc57f4404bd8b90a2c817b.jpg', '<p>Ridley và các đồng đội gan dạ tiếp tục khám phá bảo tàng kỳ diệu cùng hội bạn mới, các nhiệm vụ mạo hiểm và cả công cuộc giành Mắt La Bàn của Ridley.</p>', 'Hoàn Tất (5/5)', 5, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Iara Nemirovsky","avatar":""},{"name":"Laraine Newman","avatar":""},{"name":"David Errigo Jr.","avatar":""},{"name":"Tyler Shamy","avatar":""},{"name":"Ezra Menas","avatar":""},{"name":"Ashlyn Madden","avatar":""},{"name":"Sutton Foster","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324322);
