INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bai-ca-yeu-thuong', 'Bài Ca Yêu Thương', 'Coffee Melody', 'https://phimimg.com/upload/vod/20240608-1/dd3893183bb6a8360e268038d9db8576.jpg', 'https://phimimg.com/upload/vod/20240608-1/eb4238a0cfaf3ff407f8c1f2d9542087.jpg', '<p>Duan Yi, một nhà soạn nhạc nổi tiếng đã nhận được một dự án mới từ công ty để sáng tác bài hát tình yêu. Duan Yi đang loay hoay sáng tác một bài hát và đánh mất niềm đam mê của mình. Và nguồn cảm hứng sáng tác đầu tiên của Duen Yi đã trở lại khi anh gặp Handsome barista Pleng Ruk. Nốt cuối cùng của bố cục Nó giống như giọt cà phê cuối cùng.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Pavel Naret Promphaopun","avatar":""},{"name":"Benz Panupun Vongjorn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324322);
