INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-thu-pham-luu-day-tinh-khong', 'Tàn Thứ Phẩm: Lưu Đày Tinh Không', 'Can Ci Pin: Fangzhu Xingkong', 'https://phimimg.com/upload/vod/20240608-1/77e3be197717396393611af9a10a0d1c.jpg', 'https://phimimg.com/upload/vod/20240608-1/1b427e8afa1146440d845e70d7eb32eb.jpg', '<p>Thời đại Tân Tinh, Liên minh Những Vì Sao thiết lập hệ thống Khu vườn Eden, giúp con người thoát khỏi đau khổ và phiền não. Thế nhưng, trong 8 tinh hệ lớn vẫn còn 1% con người không thể vào Khu vườn Eden. Họ bị lưu đày tới tinh hệ thứ 8 và trở thành Tàn thứ phẩm. Lúc này, Thượng tướng của Liên minh - Lâm Tĩnh Hằng bị kẻ khác hãm hại, lưu lạc tới tinh hệ thứ 8, quen biết với một thanh niên trong lòng luôn hướng tới giáo dục, Lục Tất Hành. Sau đó Liên minh bị lật đổ, hải tặc hoành hành, hai người chỉ đành đưa những người Tàn thứ phẩm này trải qua những mạo hiểm trong thế giới những vì sao, hé lộ từng lớp sự thật.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324322);
