INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bai-cat-trang-ben-bo-thuy-cung-aquatope', 'Bãi Cát Trắng Bên Bờ Thủy Cung Aquatope', 'Shiroi Suna No Aquatope, The Aquatope On White Sand', 'https://phimimg.com/upload/vod/20240608-1/5b2fdf05d73298d3baf3a2f23beab227.jpg', 'https://phimimg.com/upload/vod/20240608-1/afd42807065dfd3e0922a0fa7f37efb7.jpg', '<p>Cô nữ sinh cao trung 18 tuổi Misakino Kukuru đang làm thêm tại thủy cung thì gặp Miyazawa Fuuka, một cựu Idol đã mất đi danh tiếng ở Tokyo nên về quê để trốn chạy hiện thực. Fuuka vào làm ở thủy cung với những trăn trở trong lòng. Tuy nhiên, cơn khủng hoảng đóng cửa thủy cung ập tới, đối mặt với thử thách, các cô gái khám phá ra giấc mơ và thực tại của bản thân, nhận ra tình bạn trong nỗi cô đơn và tầm quan trọng của những mới liên kết.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 4, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324322);
