INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('johnny-test-phan-1', 'Johnny Test (Phần 1)', 'Johnny Test (Season 1)', 'https://phimimg.com/upload/vod/20240608-1/3c377384ea33f488566b5b6b00b15a92.jpg', 'https://phimimg.com/upload/vod/20240608-1/0ff6afe13679d49bd0a73b2bfd042cff.jpg', '<p>Một cậu bé giàu trí tưởng tượng, chú chó trung thành của cậu cùng hai cô chị yêu khoa học thì có thể gặp bao nhiêu rắc rối chứ? Hừm, nghe như một lời thách thức ấy nhỉ!</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Arnold Taylor","avatar":""},{"name":"Trevor Devall","avatar":""},{"name":"Maryke Hendrikse","avatar":""},{"name":"Emily Tennant","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324322);
