INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phap-y-tan-minh-bang-chung-cam-lang', 'Pháp Y Tần Minh: Bằng Chứng Câm Lặng', 'Medical Examiner Dr.Qin: Silent Evidence', 'https://phimimg.com/upload/vod/20240608-1/a0b85b8f011c71ac011c3ce075e33665.jpg', 'https://phimimg.com/upload/vod/20240608-1/9eeda26769400537fa5590a677d47be2.jpg', '<p>Phim xoay quanh nhân vật Tần Minh, một thiếu niên tuổi trẻ tài cao. Mặc dù mới bước chân ra ngoài xã hội nhưng với thiên phú hơn người mà cậu sớm học hỏi được các kỹ năng và hòa nhập tốt với môi trường mới. Với sự giúp đỡ của cao thủ Lâm Đang và những người khác, anh từ từ thoát khỏi chấn thương tâm lý thời thơ ấu và trở thành một giám định viên y khoa. Trong một vụ án giết người, Tần Minh phát hiện ra có nhiều điểm tương đồng giữa vụ án này và vụ án 15 năm trước. Kẻ sát nhân đã bị bắt 15 năm trước, liệu cảnh sát đã bắt nhầm người hay hắn có đồng phạm?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 18, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Châu Vũ Đồng","avatar":""},{"name":"Trương Vũ Kiếm","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324322);
