INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tiec-cua-phu-thuy', 'Bàn Tiệc Của Phù Thủy', 'The Witch''s Diner', 'https://phimimg.com/upload/vod/20240608-1/a9fd21cec6695768178409f7f5643b33.jpg', 'https://phimimg.com/upload/vod/20240608-1/f97d74b8534229be37757a24e95c0f34.jpg', '<p>Bàn Tiệc Của Phù Thủy được bắt đầu khi Jung Jin (Nam Ji Hyun thủ vai) – một cô nàng 28 tuổi đang có một cuộc sống vô cùng bình thường bỗng dưng gặp phải tình cảnh trớ trêu, khi cả công việc lẫn người bạn trai gắn bó bao lâu nay đều lần lượt ruồng bỏ cô. Sau khi vượt qua nỗi đau vừa thất nghiệp vừa thất tình, Jung Jin quyết tâm làm lại cuộc đời và mở một quán ăn cùng với mẹ của mình. Tuy nhiên, tình hình kinh doanh lại không được như ý, khiến nhà hàng dần rơi vào bờ vực phá sản và Jung Jin chỉ còn lại một mình. Đúng lúc đó, Zo Hee Ra (Song Ji Hyo thủ vai) – một phù thuỷ bí ẩn xuất hiện đã mướn nhà hàng của cô để mở một tiệm ăn của riêng mình. Tại đây, với tư cách là một đối tác kinh doanh, Jung Jin trở thành nhân viên phục vụ cho nhà hàng của Hee Ra cùng với anh chàng Gil Yong (Chae Jong Hyo thủ vai) – một người đến làm việc để tìm kiếm câu trả lời cho cuộc đời mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Chae Jong Hyeop","avatar":""},{"name":"Ha Do Gwon","avatar":""},{"name":"Nam Ji Hyun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324322);
