INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ven-man-toi-ac', 'Vén Màn Tội Ác', 'The Veil', 'https://phimimg.com/upload/vod/20240608-1/2b80ad49e4b47ddebd1320bb792af6c0.jpg', 'https://phimimg.com/upload/vod/20240608-1/39ec4ff0eec4ff254277abcccf203799.jpg', '<p>Nam Goong Min đóng vai Han Ji Hyuk, một đặc vụ hiện trường ưu tú với thành tích và kỹ năng hoàn thành nhiệm vụ hoàn hảo đã khiến anh trở thành huyền thoại tại NIS. Tuy nhiên, ngay khi anh ấy lật đổ tổ chức tội phạm cuối cùng thì bỗng nhiên anh ấy mất tích, mất trí nhớ, tất cả mọi người đều nghĩ Han Ji Hyuk đã chết. Sau một năm, Han Ji Hyuk trở về, anh tìm lại chính mình và truy lùng kẻ phản bội mình. Bên cạnh đó, Han Ji Hyuk cũng đồng thời vén một bức màn tội ác kinh hoàng đứng đằng sau NIS.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Namkoong Min","avatar":""},{"name":"Kim Ji Eun","avatar":""},{"name":"Park Ha Sun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324322);
