INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jack-whitehall-du-lich-cung-cha-toi-phan-5', 'Jack Whitehall: Du Lịch Cùng Cha Tôi (Phần 5)', 'Jack Whitehall: Travels With My Father (Season 5)', 'https://phimimg.com/upload/vod/20240608-1/eb1f38cd664cb880592fa1c2dcd8fba0.jpg', 'https://phimimg.com/upload/vod/20240608-1/392d07a49f4e9a3f498f93f283ecf512.jpg', '<p>Sau cả năm phong tỏa, bà Hilary rất muốn Jack đưa ông Michael đi chuyến cuối cùng. Nhưng lần này, họ không đi đâu xa mà ở ngay quê nhà Vương quốc Anh.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jack Whitehall","avatar":""},{"name":"Michael Whitehall","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324322);
