INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-rac-roi-khi-khoi-nghiep', 'Những Rắc Rối Khi Khởi Nghiệp', 'The Arc Of Life', 'https://phimimg.com/upload/vod/20240608-1/4c95ddf6f7e987b8d4a4c580373da7a8.jpg', 'https://phimimg.com/upload/vod/20240608-1/4b3f536e0adca4bd798fb53393c6449c.jpg', '<p>Ba cô gái với ba tính cách khác nhau, một Hạ Chỉ lúc nào cũng vùi đầu vào công việc, Công Trị Tiểu Điểu độc đoán, bá đạo và một Lâm Mỹ Quý với nhiều mối quan hệ. Ba người đều làm việc trong công ty lớn với tâm trạng lo lắng, thấp thỏm, càng cố gắng thì càng mệt mỏi. Từ không quen biết, ba cô gái vô tình gặp được nhau, họ vì những lý do riêng của mình mà rời xa cuộc sống công sở, cùng nhau bắt tay khởi nghiệp. Trên con đường khởi nghiệp gian khổ này, họ cùng giúp đỡ nhau, vượt qua sự lạnh lẽo của tình yêu, tình bạn và tình thân...</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 9, 2021, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"林心如","avatar":""},{"name":"Ivy Chen","avatar":""},{"name":"Jian Man Shu","avatar":""},{"name":"Khưu Trạch","avatar":""},{"name":"Lee Li-Chun","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324322);
