INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-lac-bo-tham-tu-dien-trai', 'Câu Lạc Bộ Thám Tử Điển Trai', 'Bishounen Tanteidan Bishounen Series', 'https://phimimg.com/upload/vod/20240608-1/113bfc2298f350c742a2a1286fcd1a45.jpg', 'https://phimimg.com/upload/vod/20240608-1/f4eeea8f89b7d7642fc8a4b7bae1ffdd.jpg', '<p>“Một cô gái đang tìm kiếm một ngôi sao, Meimi Hitomishima - cô gái đi tìm các vì sao. Năm chàng mĩ nam với những nét tính cách khác nhau đã giúp cô tìm ra các vì sao. Một cuộc phiêu lưu giải mã những bí ẩn tuyệt đẹp bắt đầu từ đây!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 18, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324322);
