INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bossam-danh-cap-so-phan', 'Bossam: Đánh Cắp Số Phận', 'Bossam: Steal The Fate', 'https://phimimg.com/upload/vod/20240608-1/25c3a836cf75938559615296e7f3991f.jpg', 'https://phimimg.com/upload/vod/20240608-1/9fb2eb217e0dd8cdf84ce97d85e8dd04.jpg', '<p>Phim lấy bối cảnh ở thời Vua Gwang Hae, xoay quanh cuộc sống của hai nhân vật công chúa Soo Kyung và Ba Woo. Trong đó Ba Woo là người thực hiện việc kết nối những góa phụ, những người phụ nữ không có ý định lấy chồng mới. Công việc này như bị đóng khung vào âm mưu của ai đó, Ba Woo mong muốn thoát khỏi nó và lựa chọn sống trong vỏ bọc của một người thấp hèn. Những góc khuất trong xã hội phong kiến về tình yêu, cuộc sống và cảnh áp bức mà người phụ nữ, người nghèo khổ Hàn Quốc phải chịu sẽ được khắc họ một cách chân thực.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 18, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Il Woo","avatar":""},{"name":"Kwon Yoo Ri","avatar":""},{"name":"Shin Hyun Soo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324322);
