INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kishibe-rohan-da-noi-vay', 'Kishibe Rohan Đã Nói Vậy', 'Thus Spoke Kishibe Rohan', 'https://phimimg.com/upload/vod/20240608-1/46f630f098ce077fa1bfa93aeae80f21.jpg', 'https://phimimg.com/upload/vod/20240608-1/b109619930d13333d566ceb47da08d7a.jpg', '<p>Một tác giả manga nổi tiếng bị cuốn vào những sự việc siêu nhiên trong quá trình tìm tư liệu: Người sử dụng Stand Kishibe Rohan đến Ý, phá sản và gặp nhiều biến cố khác.</p>', 'Hoàn Tất (4/4)', 4, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sakurai Takahiro","avatar":""},{"name":"Takahashi Hiroki","avatar":""},{"name":"Uchiyama Koki","avatar":""},{"name":"Nakahara Mai","avatar":""},{"name":"Mizuhashi Kaori","avatar":""},{"name":"Kaji Yuki","avatar":""},{"name":"Takagi Wataru","avatar":""},{"name":"Tanezaki Atsumi","avatar":""},{"name":"Majima Junji","avatar":""},{"name":"Mogi Takamasa","avatar":""},{"name":"Tsuruoka Satoshi","avatar":""},{"name":"Showtaro Morikubo","avatar":""},{"name":"Kase Yasuyuki","avatar":""},{"name":"Ogami Shinnosuke","avatar":""},{"name":"Masuyama Takeaki","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324322);
