INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-noi-tam-biet', 'Không Nói Tạm Biệt', 'Never Say Goodbye', 'https://phimimg.com/upload/vod/20240608-1/685ab4fcbec22265f13e646ffd3e2451.jpg', 'https://phimimg.com/upload/vod/20240608-1/a8cee20e8bc23d75c64c8bec01436cb9.jpg', '<p>Ba năm trước, vì nhầm lẫn của cảnh sát Lưu Viễn Văn đã khiến cho vợ chưa cưới của mình, một cảnh sát ưu tú mới vào nghề bỏ mạng trong biển lửa của bọn buôn ma túy. Vì cái chết của em gái mình mà Vinh Diệu, cảnh sát của đội chống ma túy đã trở mặt với người anh em tốt Lưu Viễn Văn, Lưu Viễn Văn chán chường rời khỏi cục cảnh sát, không rõ tung tích, Vinh Diệu vì muốn trả thù, trải qua ba năm không ngừng cố gắng đã trở thành đội trưởng đội chống ma túy thành phố Vân Cảng. Để tiêu diệt tập đoàn K và tìm ra đầu sỏ buôn ma túy quốc tế \U Linh\</p>', 'Hoàn Tất (47/47)', 47, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Trương Quân Ninh","avatar":""},{"name":"jonny","avatar":""},{"name":"Cheng Yu","avatar":""},{"name":"Enyou Liu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324322);
