INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-vat-yeu-ot-cua-tomozakikun', 'Nhân Vật Yếu Ớt Của Tomozaki-kun', 'The Low Tier Character', 'https://phimimg.com/upload/vod/20240608-1/095c27a4ee849f4c27a5535f60513dec.jpg', 'https://phimimg.com/upload/vod/20240608-1/93f1560c62c1f47924f6ed485a2b04b0.jpg', '<p>Fumiya Tomozaki, một trong những game thủ hàng đầu Nhật Bản tuyên bố rằng cuộc sống chỉ là một trò chơi nhàm chán, đã gặp Aoi Hinami, nữ anh hùng hoàn hảo của trường. Sau đó, dưới sự hướng dẫn của Hinami, chiến lược tấn công cuộc đời của học sinh trung học yếu đuối bắt đầu!</p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 18, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324322);
