INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-hinh-su-hanh-dong-hai-ngoai', 'Cảnh Sát Hình Sự: Hành Động Hải Ngoại.', 'The Dragnet', 'https://phimimg.com/upload/vod/20240608-1/fd0222e347d3d58b6e421184d2182833.jpg', 'https://phimimg.com/upload/vod/20240608-1/8a3a9140ce6cf7bdc28d38f2ecd392a9.jpg', '<p>Trong tình hình không có quyền chấp pháp tại nước ngoài, các thành viên tổ chuyên án do Cao Tiếu Thiên lãnh đạo đã thể hiện ra trí tuệ xuất sắc, sự dũng cảm hơn người, và cả kỹ năng tinh tế khi hợp tác với cơ quan chấp pháp nước ngoài. Tại Đông Nam Á, tổ chuyên án đã vây bắt và tấn công kẻ cầm đầu đường dây lừa đảo viễn thông Đài Loan Lâm Quốc Hùng, kẻ nhiều lần gây tổn hại tới người dân Đại lục. Ở nước Mỹ, họ khuyên bảo được hai nhân chứng mấu chốt trong một vụ án cán bộ cấp cao phạm tội về nước. Tại Nam Mỹ, họ loại bỏ hai băng đảng địa phương đã gây tổn hại tới tính mạng và tài sản những người dân Hoa Kiều. Họ không màng gian khổ, hoàn thành mọi nhiệm vụ tại nước ngoài, bảo vệ thành công pháp chế cũng như lợi ích của nhân dân.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wu Gang","avatar":""},{"name":"Michelle","avatar":""},{"name":"Ninh Lý","avatar":""},{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Faye","avatar":""},{"name":"Yu Feihong","avatar":""},{"name":"Shi Liang","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Suet Lam","avatar":""},{"name":"zhaojun","avatar":""},{"name":"Qi Jiu Zhou","avatar":""},{"name":"Yinyin Ma","avatar":""},{"name":"Ma Yin Yin","avatar":""},{"name":"Wang Yu","avatar":""},{"name":"Rooy Sun","avatar":""},{"name":"Danny","avatar":""},{"name":"Guohua Wu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324322);
