INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-chim-lac', 'Bầy Chim Lạc', 'Stray Birds', 'https://phimimg.com/upload/vod/20240608-1/e34dca6ceb4a7114e61411de278125e7.jpg', 'https://phimimg.com/upload/vod/20240608-1/7a02b6c9e7c4bd3d234309b291c2cee2.jpg', '<p>Bầy Chim Lạc xoay quanh một nhóm con nhà giàu thế hệ thứ 2, mang theo nhiệt huyết và khao khát, chập chững bước vào nơi làm việc. Song hiện thực tàn khốc, trải qua lừa dối, trả thù, cái bóng của gia đình, cám dỗ, phản bội nhưng vẫn kiên trì với lý tưởng, cố gắng chiến đấu, bức phá ra những ràng buộc, tạo nên một câu chuyện về chủ nghĩa hiện thực tươi sáng.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cao Chí Đình","avatar":""},{"name":"Khưu Hách Nam","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324322);
