INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-de-tinh-yeu-phan-xet', 'Hãy Để Tình Yêu Phán Xét', 'Dare To Love', 'https://phimimg.com/upload/vod/20240608-1/5bf92960063da43d783bed33b2d2e7d0.jpg', 'https://phimimg.com/upload/vod/20240608-1/d307ae80bfecc673bbae1e4eed2ed1b6.jpg', '<p>Trong Hãy Để Tình Yêu Phán Xét (Dare To Love) vietsub, Ticha là một luật sư đầy tham vọng và có năng lực. Cô và đồng nghiệp Camellia đang cạnh tranh gay gắt để trở thành nữ cộng sự đầu tiên trong công ty luật danh tiếng Ross \u0026 Harvey. Do khối lượng công việc ngày một lớn nên công ty đã tuyển dụng thực tập sinh nhằm hỗ trợ các luật sư. Vì vậy, Napawat hay còn gọi là \</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Bella Ranee Campen","avatar":""},{"name":"Kongthap Peak","avatar":""},{"name":"Pinky Savika Chaiyadej","avatar":""},{"name":"Au Tanakorn Posayanon","avatar":""},{"name":"Namfah Thunyaphat Phatrathinchaicherin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324322);
