INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-trai-tim-em-mim-cuoi', 'Làm Trái Tim Em Mỉm Cười', 'Make My Heart Smile', 'https://phimimg.com/upload/vod/20240608-1/5a5cde305a79b082bc8a5b8a5919ef38.jpg', 'https://phimimg.com/upload/vod/20240608-1/e731aa5d79fa9ba775a9a697c37811d1.jpg', '<p>Câu truyện về ba cặp đôi trẻ cùng nhau cố gắng phấn đấu về ước mơ: câu chuyện tình yêu tình cờ giữa chàng hotboy Cố Ngôn Lạc (La Chính) và cô nàng lém lỉnh Diệp Vị Miên (Quý Mỹ Hàm), ngự tỷ Lộ Dao (Lý Sa Mân Tử) và anh chàng đào hoa Mộ Trạch (Trần Hạc Nhất) là một cặp đôi ồn ào; họa sĩ thiên tài Tả Tư Thần (Văn Uyên) và anh chàng mọt sách Ngôn Cửu Nguyệt (Thường Hoa Sâm)</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 24, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"La Chính","avatar":""},{"name":"Quý Mỹ Hàm","avatar":""},{"name":"Trần Hạc Nhất","avatar":""},{"name":"Li Sha Min Zi","avatar":""},{"name":"Wen Yuan","avatar":""},{"name":"Thường Hoa Sâm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324322);
