INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rong-di-tim-nha', 'Rồng Đi Tìm Nhà', 'Dragon, Ie Wo Kau., Dragon Goes House-Hunting, DoraIe', 'https://phimimg.com/upload/vod/20240608-1/a4c8e01f09eee0bb6a9018dbc17639d7.jpg', 'https://phimimg.com/upload/vod/20240608-1/6bebfe8cbef910e118497a0f8c208f9c.jpg', '<p>Letty, một chú rồng nhút nhát trong lúc đi tìm nhà đã được một người làm bất động sản tên Diaria cứu giúp và họ đã cùng nhau bắt đầu một cuộc hành trình. Chuyến đi kỳ ảo với nhiều cảm giác mới lạ của chú rồng và ma vương bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324322);
