INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghi-thuc-hoa-anh-dao', 'Nghi Thức Hoa Anh Đào', 'Shikizakura', 'https://phimimg.com/upload/vod/20240608-1/85b4ad95fac803616e3cd91d6ff9c219.jpg', 'https://phimimg.com/upload/vod/20240608-1/07acc6c9303b4a5f26d062bacc103e39.jpg', '<p>Kakeru Miwa là một học sinh trung học. Trong một sự kiện tình cờ, cậu đã trở thành thành viên của một biệt đội diệt quỷ. Những con quỷ này chiếm hữu cơ thể con người để bám víu vào thế giới thực. Chỉ những bộ giáp Yoroi kết hợp giữa tri thức cổ xưa và công nghệ hiện đại mới có thể chống lại chúng. Cậu quyết định trở thành một anh hùng chiến đấu chống lại lũ quỷ và bảo vệ Ouka, một vu nữ với sứ mệnh cứu rỗi thế giới.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324322);
