INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-giai-cuu-sinh-tu', 'Cuộc Giải Cứu Sinh Tử', 'Redemption Day', 'https://phimimg.com/upload/vod/20231026-1/cd9fd1019b8e435ba86b762386f02a1f.jpg', 'https://phimimg.com/upload/vod/20231026-1/520f4c088eb1198b8994146491221f41.jpg', '<p>Sau khi nhận Huân chương danh dự vì đã anh dung chống lại tổ chức ISIS, Đội trưởng Hải quân Mỹ Brad Paxton (Gary Dourdan) bị sang chấn do mắc kẹt ở chiến trường một thời giang dài. Anh quyết định sống cuộc đời bình lặng bên vợ mình là Kate (Seridan Swan) – một nhà khảo cổ học nổi tiếng. Trong lúc đó, Kate nhận được một cơ hội hiếm có ở Morocco và Brad vô cùng ủng hộ vợ mình theo đuổi ước mơ này. Tuy nhiên, khi Kate đến Morocco thì cô bị một nhóm khủng bố bắt cóc và chúng đòi khoản tiền chuộc 10 triệu đô. Cuộc đàm phán giữa Đại sứ quán Mỹ và bọn khủng bố để giải cứu Kate đã rơi vào bế tắc vì thoả thuận này sẽ ảnh hưởng đến quyền khai thác dầu mỏ của Liên hợp quốc tại đất nước này. Brad đành phải lao đến Morocco và dùng khả năng chinh chiến của mình để thực thi một nhiệm vụ nguy hiểm nhằm cứu lấy vợ. Liệu Brad có thành công?</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Maroc', 0, '[{"name":"Gary Dourdan","avatar":""},{"name":"Serinda Swan","avatar":""},{"name":"Andy García","avatar":""},{"name":"Brice Bexter","avatar":""},{"name":"Ernie Hudson","avatar":""},{"name":"Martin Donovan","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"Samy Naceri","avatar":""},{"name":"Soumaya Akaaboune","avatar":""},{"name":"Don Bigg","avatar":""},{"name":"Jay Footlik","avatar":""},{"name":"Lilia Hajji","avatar":""},{"name":"Sonia Okacha","avatar":""},{"name":"Karim Saidi","avatar":""},{"name":"Hami Belal","avatar":""},{"name":"Aïssam Bouali","avatar":""},{"name":"Bradley Gregg","avatar":""},{"name":"Michael Patrick L","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324322);
