INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ron-chu-robot-khac-biet', 'Ron: Chú Robot Khác Biệt', 'Ron''s Gone Wrong', 'https://phimimg.com/upload/vod/20231026-1/11b63abda21ce262812e50d1b5e5f815.jpg', 'https://phimimg.com/upload/vod/20231026-1/0dcf39e1cd925a08c6631d7258eb9c72.jpg', '<p>Lấy bối cảnh ở một thế giới nơi những chú robot có thể đi đứng, nói chuyện, kết nối kỹ thuật số và đã trở thành bạn thân của trẻ em, Ron - Chú Robot Khác Biệt kể về câu chuyện của một cậu bé 11 tuổi nhận thấy rằng người bạn robot của mình hoạt động không như bình thường. Cậu cố gắng hướng dẫn chú robot nhưng tất cả dường như trở thành một cuộc trải nghiệm đầy hài hước, ấm áp và đầy ý nghĩa về tình bạn trong thế giới chỉ có thuật toán và mạng xã hội.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Zach Galifianakis","avatar":""},{"name":"Jack Dylan Grazer","avatar":""},{"name":"Ed Helms","avatar":""},{"name":"Olivia Colman","avatar":""},{"name":"Justice Smith","avatar":""},{"name":"Rob Delaney","avatar":""},{"name":"Kylie Cantrall","avatar":""},{"name":"Ricardo Hurtado","avatar":""},{"name":"Marcus Scribner","avatar":""},{"name":"Thomas Barbusca","avatar":""},{"name":"Ruby Wax","avatar":""},{"name":"Ava Morse","avatar":""},{"name":"Krupa Pattani","avatar":""},{"name":"John Macmillan","avatar":""},{"name":"Megan Maczko","avatar":""},{"name":"David Menkin","avatar":""},{"name":"Tristan Allerick","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1