INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ma-phu-thuy-phan-2', 'Mật Mã Phù Thủy (Phần 2)', 'A Discovery Of Witches (Season 2)', 'https://phimimg.com/upload/vod/20240215-1/b780eb5694ae0b1915d80c9e28a982af.jpg', 'https://phimimg.com/upload/vod/20240215-1/0b8078b30c40854e7524dbdea49c5a2e.jpg', '<p>Cô nàng phù thuỷ Diana Bishop là một nhà sử học vô tình khám phá ra 1 pho sách cổ thần bí bên trong thư viện Bodleian tại Oxford. Sự khám phá này ép cô phải quay trở lại với thế giới ma thuật đã bị cô chối bỏ từ lâu đã tìm hiểu về các bí mật xung quanh cách sinh vật huyền thoại đang sống hoà lẫn cùng với nhân loại, trong đó có tộc phù thuỷ của cô. Đồng hành với cô là nhà di truyền học Matthew Clairmont, cũng là một ma cà rồng ngàn năm. Bỏ qua những hiềm khích trước đây giữa hai tộc, Diana và Matthew cùng sát cánh bên nhau để bảo vệ pho sách cổ cũng như khám phá về những bí mật lớn của thế giới.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Goode","avatar":""},{"name":"Teresa Palmer","avatar":""},{"name":"Edward Bluemel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324322);
