INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rung-hien-te', 'Rừng Hiến Tế', 'Gaia', 'https://phimimg.com/upload/vod/20231110-1/9c92f1294d6271c1a0a45d46072077f7.jpg', 'https://phimimg.com/upload/vod/20231110-1/6b69b241a1cbe751ccb8da847d83e2cf.jpg', '<p>Một nhân viên kiểm lâm bị thương trong một nhiệm vụ thường lệ được cứu bởi hai người sống sót. Những gì ban đầu là một cuộc giải cứu được chào đón trở nên đáng ngờ hơn khi cậu con trai và người cha phản bội của mình tiết lộ một lòng sùng kính đối với khu rừng.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Nam Phi', 0, '[{"name":"Monique Rockman","avatar":""},{"name":"Carel Nel","avatar":""},{"name":"Alex van Dyk","avatar":""},{"name":"Anthony Oseyemi","avatar":""},{"name":"Elaine Apruzzese","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324322);
