INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-luyen-o-kota-phan-2', 'Lò Luyện ở Kota (Phần 2)', 'Kota Factory (Season 2)', 'https://phimimg.com/upload/vod/20240624-1/4b0ce7de0a40a4614a1fea80f255c0cc.jpg', 'https://phimimg.com/upload/vod/20240624-1/8556fab8e8433bb67d45d500b5a801cd.jpg', '<p>Tại thành phố của các lò luyện ra những sinh viên giỏi nhất Ấn Độ, một sinh viên có chí nhưng không phải xuất sắc cùng bạn bè xoay xở với cuộc sống ở trường đại học.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 10, 2021, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Mayur More","avatar":""},{"name":"Jitendra Kumar","avatar":""},{"name":"Ranjan Raj","avatar":""},{"name":"Alam Khan","avatar":""},{"name":"Ahsaas Channa","avatar":""},{"name":"Revathi Pillai","avatar":""},{"name":"Urvi Singh","avatar":""},{"name":"Arun Kumar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324322);
