INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-no', 'Một Ngày Nọ', 'One Ordinary Day', 'https://phimimg.com/upload/vod/20240622-1/389887c2f87fdabc93c25e30ad3d7c7b.jpg', 'https://phimimg.com/upload/vod/20240622-1/ee093c22f19d7e3bf80574b2b48cf67c.jpg', '<p>Một Ngày Nọ đưa người xem khám phá hệ thống tư pháp hình sự từ một góc nhìn cực kỳ phổ biến thông qua câu chuyện khốc liệt của hai người đàn ông xung quanh vụ giết một người phụ nữ. Kim Hyun Soo, một sinh viên đại học bình thường, đột nhiên trở thành nghi phạm chính trong một vụ án giết người. Shin Joong Han là luật sư duy nhất sẵn sàng giúp đỡ Hyun Soo. Chỉ vừa mới đậu trường luật, sự tham gia của Shin Joong Han vào vụ án đã đưa cuộc đời không mấy nổi bật của anh lên một tầm cao mới.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"김수현","avatar":""},{"name":"차승원","avatar":""},{"name":"김성규","avatar":""},{"name":"김신록","avatar":""},{"name":"이설","avatar":""},{"name":"김홍파","avatar":""},{"name":"양경원","avatar":""},{"name":"김영아","avatar":""},{"name":"서재희","avatar":""},{"name":"Moon Ye-won","avatar":""},{"name":"Jeong Ji-ho","avatar":""},{"name":"유승목","avatar":""},{"name":"Sung Nak-kyung","avatar":""},{"name":"Park Yoon-hee","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324322);
