INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-thu-vien-dong', 'Xạ Thủ Viễn Đông', 'Siberian Sniper', 'https://phimimg.com/upload/vod/20240616-1/fb09a48aa739934c4aaded1cdf2492a2.jpg', 'https://phimimg.com/upload/vod/20240616-1/7cd9618e5ee730de143e9ae6b4a81fed.jpg', '<p>Trong thời kỳ đỉnh cao của Thế chiến thứ hai, người lính bắn tỉa cuối cùng còn sống sót của một đơn vị Liên Xô được cử đi thực hiện một nhiệm vụ liều chết nhằm phá vỡ một thành trì của Đức để cứu những người lính của mình.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Aytal Stepanov","avatar":""},{"name":"Aleksandr Kazantsev","avatar":""},{"name":"Dmitriy Koltzov","avatar":""},{"name":"Daniil Zhuravlev","avatar":""},{"name":"Pavel Pogodaev","avatar":""},{"name":"Vyacheslav Yugov","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324322);
