INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kien-truc-su-dai-tai', 'Kiến Trúc Sư Đại Tài', 'Eiffel', 'https://phimimg.com/upload/vod/20240607-1/7eea41a5ca0ac7aa662f7f76a611a042.jpg', 'https://phimimg.com/upload/vod/20240607-1/11a91790b2e8cf34c546019781d47ff9.jpg', '<p>Người kỹ sư đã miễn cưỡng đảm nhận dự án, ông và kiến trúc sư Eugène Viollet-le-Duc, người nổi tiếng với khối chóp nhà thờ Đức Bà vừa hoàn thành việc xây dựng khung bằng sắt và thép cho tượng nữ thần tự do ở New York và Eiffel thì lại đang quan tâm tới việc làm hệ thống Metro ở Paris.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Romain Duris","avatar":""},{"name":"Emma Mackey","avatar":""},{"name":"Pierre Deladonchamps","avatar":""},{"name":"Armande Boulanger","avatar":""},{"name":"Andranic Manet","avatar":""},{"name":"Alexandre Steiger","avatar":""},{"name":"Philippe Hérisson","avatar":""},{"name":"Jérémie Petrus","avatar":""},{"name":"Jérémy Lopez","avatar":""},{"name":"Frédéric Merlo","avatar":""},{"name":"Damien Zanoly","avatar":""},{"name":"Clémence Boué","avatar":""},{"name":"Julien Sarazin","avatar":""},{"name":"Josselin Baillarguet","avatar":""},{"name":"Michèle Clément","avatar":""},{"name":"Ju","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324322);
