INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-ban-than', 'Gái Bán Thân', 'Girls to Buy', 'https://phimimg.com/upload/vod/20240607-1/cd7673d9eb7904a8c2bf951b8f8826cc.jpg', 'https://phimimg.com/upload/vod/20240607-1/7a23ad18e53fef22cc0193bc0523ac76.jpg', '<p>Emi là một cô gái trẻ đầy tham vọng, mơ về một thế giới rộng lớn. Bất cứ khi nào có cơ hội, cô ấy nhảy vào mà không do dự. Ngay sau đó, theo lời mời của các Sheikh Ả Rập, bắt đầu tuyển dụng các hoa hậu, người nổi tiếng, ngôi sao màn bạc và người mẫu Ba Lan. Tuy nhiên, thế giới xa hoa không thể tiếp cận này sẽ sớm biến mất.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'FHD', 'Ba Lan', 0, '[{"name":"Paulina Gałązka","avatar":""},{"name":"Giulio Berruti","avatar":""},{"name":"Katarzyna Figura","avatar":""},{"name":"Jan Englert","avatar":""},{"name":"Beata Ścibakówna","avatar":""},{"name":"Katarzyna Sawczuk","avatar":""},{"name":"Olga Kalicka","avatar":""},{"name":"Józef Pawłowski","avatar":""},{"name":"Andrea Preti","avatar":""},{"name":"Iacopo Ricciotti","avatar":""},{"name":"Marek Walczyk","avatar":""},{"name":"Sebastian Skalski","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324322);
