INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luu-cong-ky-an', 'Lưu Công Kỳ Án', 'Liu Yong Pursues The Case', 'https://phimimg.com/upload/vod/20240606-1/3ee54a0bdee6e81b5fa037291151f56d.jpg', 'https://phimimg.com/upload/vod/20240606-1/07520dc848933481cbbac94027ba72c3.jpg', '<p>Lưu Công Kỳ Án xoay quanh vị quan trung quân, yêu dân và liêm khiết Lưu Dung, còn được nhiều người biết đến với danh hiệu “Tể tướng Lưu gù”. Dưới triều đại Càn Long, Phú Quốc Thái - quan tuần phủ tỉnh Sơn Đông đã lợi dụng chức quyền, viện danh nghĩa cống nạp cho hoàng thượng để bóc lột dân chúng. Vua Càn Long đã phong Lưu Dung làm Khâm sai đại thần cùng Hòa Thân đi đến Sơn Đông để điều tra vụ án tham nhũng nghiêm trọng này. Lưu Dung càng đi sâu vào vụ án thì các thế lực thù địch càng sợ hãi bị phát hiện nên đã giở mọi thủ đoạn để hãm hại ông. Nhưng với sự thông minh, kiên cường và khả năng phá án kỳ tài của mình, Lưu Dung đã thoát khỏi hiểm nguy và từng bước tìm ra bằng chứng, tội trạng của Phú Quốc Thái.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 9, 2021, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"He Bing","avatar":""},{"name":"Bai Bing","avatar":""},{"name":"王鶴潤","avatar":""},{"name":"李乃文","avatar":""},{"name":"Cao Zheng","avatar":""},{"name":"Huang Haibing","avatar":""},{"name":"Liu Xiaofeng","avatar":""},{"name":"Wang Quanyou","avatar":""},{"name":"Wang Yuzheng","avatar":""},{"name":"Liu Yuting","avatar":""},{"name":"Zhang Yun","avatar":""},{"name":"Li Ming","avatar":""},{"name":"Shi Xiao-Hong","avatar":""},{"name":"Li Daqiang","avatar":""},{"name":"Ning Xiaohua","avatar":""},{"name":"Yu Aiqun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324322);
