INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sweet-tooth-cau-be-gac-nai', 'Sweet Tooth: Cậu Bé Gạc Nai', 'Sweet Tooth', 'https://phimimg.com/upload/vod/20240606-1/8645be0a735a48fe6318f1a0c18dbc96.jpg', 'https://phimimg.com/upload/vod/20240606-1/3de87d1403c986b1e160d120aa1fc4f3.jpg', '<p>Trong hành trình phiêu lưu đầy hiểm nguy trên khắp thế giới hậu tận thế, cậu bé nửa người nửa nai đáng yêu tìm kiếm khởi đầu mới cùng một người bảo vệ cộc cằn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nonso Anozie","avatar":""},{"name":"Christian Convery","avatar":""},{"name":"Adeel Akhtar","avatar":""},{"name":"Stefania LaVie Owen","avatar":""},{"name":"Dania Ramirez","avatar":""},{"name":"Aliza Vellani","avatar":""},{"name":"Will Forte","avatar":""},{"name":"James Brolin","avatar":""},{"name":"Neil Sandilands","avatar":""},{"name":"Mia Artemis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324322);
