INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-lai-cho-toi', 'Cầm Lái Cho Tôi', 'Drive My Car', 'https://phimimg.com/upload/vod/20240604-1/f4e36714fa1f38fe5946f98b957542e6.jpg', 'https://phimimg.com/upload/vod/20240604-1/c131d3bb893dfb780347bb30f23a83c5.jpg', '<p>Yusuke Kafuku, một diễn viên và đạo diễn sân khấu, sau hai năm, vẫn không thể chống chọi với sự ra đi của người vợ thân yêu của mình, đã chấp nhận làm đạo diễn cho chú Vanja tại một liên hoan sân khấu ở Hiroshima. Ở đó, anh gặp Misaki, một phụ nữ trẻ sống nội tâm, được chỉ định lái xe của anh. Giữa các chuyến đi, những bí mật từ quá khứ và những lời thú nhận chân thành sẽ được bật mí.</p>', 'Full', 1, 'single', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hidetoshi Nishijima","avatar":""},{"name":"Toko Miura","avatar":""},{"name":"Masaki Okada","avatar":""},{"name":"Reika Kirishima","avatar":""},{"name":"박유림","avatar":""},{"name":"Jin Dae-yeon","avatar":""},{"name":"袁子芸","avatar":""},{"name":"Ahn Hwi-tae","avatar":""},{"name":"Perry Dizon","avatar":""},{"name":"Satoko Abe","avatar":""},{"name":"Hiroko Matsuda","avatar":""},{"name":"Toshiaki Inomata","avatar":""},{"name":"Takako Yamamura","avatar":""},{"name":"Ryo Iwase","avatar":""},{"name":"Faisal Anwar","avatar":""},{"name":"Kamal Zharif","avatar":""},{"name":"Massimo Biondi","avatar":""},{"name":"Shoichiro Tanigawa","avatar":""},{"name":"Yos","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324322);
