INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-cuoi-cung', 'Giáng Sinh Cuối Cùng', 'Spencer', 'https://phimimg.com/upload/vod/20240530-1/76d6bbbb1baf626676e7a48a222d4c33.jpg', 'https://phimimg.com/upload/vod/20240530-1/313b674232bd8dea5972ce888fef2027.jpg', '<p>Cuộc hôn nhân giữa Công nương Diana và Thái tử Charles đã nguội lạnh từ lâu. Mặc dù có rất nhiều tin đồn về chuyện ngoại tình và ly hôn, nhưng hòa bình vẫn được phong cho lễ Giáng sinh tại dinh thự của nữ hoàng. Có ăn uống, bắn súng và săn bắn. Diana biết rõ trò chơi, nhưng năm nay, mọi thứ sẽ khác sâu sắc.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kristen Stewart","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Jack Nielen","avatar":""},{"name":"Freddie Spry","avatar":""},{"name":"Jack Farthing","avatar":""},{"name":"Sean Harris","avatar":""},{"name":"Stella Gonet","avatar":""},{"name":"Richard Sammel","avatar":""},{"name":"Elizabeth Berrington","avatar":""},{"name":"Lore Stefanek","avatar":""},{"name":"Amy Manson","avatar":""},{"name":"Sally Hawkins","avatar":""},{"name":"James Harkness","avatar":""},{"name":"Laura Benson","avatar":""},{"name":"Wendy Patterson","avatar":""},{"name":"Libby Rodliffe","avatar":""},{"name":"John Keogh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324322);
