INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-muon-chung-ta-o-ben-nhau', 'Anh Muốn Chúng Ta Ở Bên Nhau', 'Love Will Tear Us Apart', 'https://phimimg.com/upload/vod/20240508-1/13440c3e05f3f49ff82e5a49302b1f1b.jpg', 'https://phimimg.com/upload/vod/20240508-1/9c3e05050ce65dce68f70f34f3334e1d.jpg', '<p>Một tình yêu đơn phương bắt đầu từ năm trung học. Họ gặp lại nhau vào 10 năm sau. Lữ Khâm Dương (Khuất Sở Tiêu), chàng trai đến từ nông thôn. Anh đem lòng yêu cô gái xinh đẹp Lăng Nhất Nghiêu (Trương Tịnh Nghi) từ năm 16 tuổi nhưng cặp đôi không vượt qua được hiện thực tàn khốc.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Qu Chuxiao","avatar":""},{"name":"Zhang Jingyi","avatar":""},{"name":"Sun Ning","avatar":""},{"name":"Du Jiayi","avatar":""},{"name":"Li Jiahao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324322);
