INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-bi-choi-bo-phan-1', 'Những kẻ bị chối bỏ (Phần 1)', 'The Nevers (Season 1)', 'https://phimimg.com/upload/vod/20240423-1/509fb163d59023e09b9cfcad24247e13.jpg', 'https://phimimg.com/upload/vod/20240423-1/8f4601f5752561ec2f29a7259971dff5.jpg', '<p>The Nevers là một bộ phim truyền hình chính kịch khoa học viễn tưởng của Mỹ do Joss Whedon tạo ra cho HBO. Loạt phim được sản xuất bởi HBO và Mutant Enemy Productions, với các nhà sản xuất điều hành bao gồm Whedon, Philippa Goslett, Doug Petrie, Jane Espenson, Ilene S. Landress và Bernadette Caulfield.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2021, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Laura Donnelly","avatar":""},{"name":"Ann Skelly","avatar":""},{"name":"Olivia Williams","avatar":""},{"name":"James Norton","avatar":""},{"name":"Tom Riley","avatar":""},{"name":"Pip Torrens","avatar":""},{"name":"Rochelle Neil","avatar":""},{"name":"Amy Manson","avatar":""},{"name":"Zackary Momoh","avatar":""},{"name":"Elizabeth Berrington","avatar":""},{"name":"Viola Prettejohn","avatar":""},{"name":"Anna Devlin","avatar":""},{"name":"Kiran Sonia Sawar","avatar":""},{"name":"Ben Chaplin","avatar":""},{"name":"Denis O''Hare","avatar":""},{"name":"Ella Smith","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Vi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324322);
