INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-an-nhu-co', 'Trường An Như Cố', 'One And Only', 'https://phimimg.com/upload/vod/20240409-1/172435e9a3669a59fb7afd13247dc262.jpg', 'https://phimimg.com/upload/vod/20240409-1/7d091013cb333631cc4bef18682243cd.jpg', '<p>Trường An Như Cố (Châu Sinh Như Cố) là bộ phim kể về câu chuyện xoay quanh Thôi Thời Nghi (Bạch Lộc thủ vai) vốn là Thái tử phi tương lai, nàng được trưởng bối đưa đến Vương phủ để học nghệ. Trong thời gian tiếp xúc, Thôi Thời Nghi dần phải lòng Tiểu Nam Thần Vương Châu Sinh Thần (Nhậm Gia Luân đóng). Tình cảm của hai người mau chóng phát triển, nhưng vẫn giữ lễ với nhau. Sau này, Thôi Thời Nghi bị ép buộc thành hôn với Thái tử, đồng thời lúc này, Châu Sinh Thần cũng gặp tai nạn và bị thương nặng trong lúc dẫn quân ra trận, chàng để lại lá thư trước lúc lâm chung cho Thôi Thời Nghi sau đó qua đời.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Bạch Lộc","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324322);
