INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-vat-ha-cap-tomozaki-phan-2', 'Nhân Vật Hạ Cấp Tomozaki (Phần 2)', 'Bottom-Tier Character Tomozaki 2nd Stage', 'https://phimimg.com/upload/vod/20240305-1/33a204bb1445d8164b77b0cbfb764a1d.jpg', 'https://phimimg.com/upload/vod/20240305-1/beead409127c106067d5ff4a0c9e3598.jpg', '<p>Tomozaki là một trong những game thủ giỏi nhất Nhật Bản và theo quan điểm của cậu, trò chơi đời thực là một trong những thứ dở nhất. Không có quy tắc rõ ràng để thành công, sự cân bằng khủng khiếp và chả có ý nghĩa gì. Nhưng sau đó, cậu gặp một game thủ cũng giỏi như mình và cô ta đề nghị dạy cho cậu một vài thứ về game mà cậu chưa biết.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Gen Sato","avatar":""},{"name":"Hisako Kanemoto","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Ryoko Maekawa","avatar":""},{"name":"Nene Hieda","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Shuntaro Mizuno","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324322);
