INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-nao-ma-kia-thai-lan', 'Chiến Nào, Ma Kia!', 'Let''s Fight Ghost', 'https://phimimg.com/upload/vod/20240327-1/464e7a85e5625539d0699220940ac1b9.jpg', 'https://phimimg.com/upload/vod/20240327-1/09d3b0447deeb3c420c77702ebd8f9ac.jpg', '<p>Một sinh viên y khoa cố dùng năng lực siêu nhiên của mình để kiếm tiền bằng cách đấu với hồn ma – cho đến khi linh hồn lang thang nọ mang đến một chuyện tình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Suppapong Udomkaewkanjana","avatar":""},{"name":"Patchanan Jiajirachote","avatar":""},{"name":"Thongpoom Siripipat","avatar":""},{"name":"Apiwit Reardon","avatar":""},{"name":"Kornrawich Sungkitbool","avatar":""},{"name":"Waratthaya Wongchayaporn","avatar":""},{"name":"Wannasak Sirilar","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324322);
