INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('deep-insanity-the-lost-child', 'Deep Insanity THE LOST CHILD', 'Deep Insanity THE LOST CHILD', 'https://phimimg.com/upload/vod/20240302-1/65033c70378f981b97d777e9c6682ca6.jpg', 'https://phimimg.com/upload/vod/20240302-1/4b991c918eb9f847bc731c79c9d47cf2.jpg', '<p>Hội chứng Randolph, một chứng bệnh lạ gây nên những cơn điên và đưa người ta vào hôn mê, không ngừng tấn công nhân loại một cách chậm rãi mà chắc chắn. Asylum, thế giới ngầm khổng lồ xuất hiện tại Nam Cực được xem là nguyên nhân gây nên chứng bệnh. Ở nơi đó tồn tại vô số loài sinh vật quái lạ gọi là dị hình và nguồn tài nguyên chưa ai biết đến. Vì những món tiền kếch xù, âm mưu hay tham vọng của chính mình, con người không ngại hy sinh tính mạng dấn thân vào vực sâu của tân thế giới đầy bí ẩn. Và tại đó, một chàng trai ôm ấp ước nguyện trong tim và đương đầu với tiền tuyến Asylum.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324322);
