INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('arlo-o-new-york', 'Arlo Ở New York', 'I Heart Arlo', 'https://phimimg.com/upload/vod/20240302-1/486e3017cba3adfa6d7176b742faa548.jpg', 'https://phimimg.com/upload/vod/20240302-1/c6dc8e58ffc8ac3128f877668f714f48.jpg', '<p>Thế giới hoàn toàn mới mở ra với Arlo và hội bạn có một không hai khi họ bắt đầu khôi phục một khu phố xập xệ ở Thành phố New York – và biến nơi ấy thành của riêng họ.</p>', 'Hoàn Tất (19/19)', 19, 'hoathinh', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael J. Woodard","avatar":""},{"name":"Mary Lambert","avatar":""},{"name":"Jonathan Van Ness","avatar":""},{"name":"Haley Tju","avatar":""},{"name":"Brett Gelman","avatar":""},{"name":"Tony Hale","avatar":""},{"name":"Vincent Rodriguez III","avatar":""},{"name":"Annie Potts","avatar":""},{"name":"Jessica Williams","avatar":""},{"name":"Melissa Villaseñor","avatar":""},{"name":"Cathy Vu","avatar":""},{"name":"Jennifer Coolidge","avatar":""},{"name":"Flea","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324322);
