INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyet-san-thieu-nu-nozakikun', 'Nguyệt San Thiếu Nữ Nozaki-kun', 'Monthly Shojo Magazine Nozaki-kun', 'https://phimimg.com/upload/vod/20240302-1/1e8d0257a91b2d9c537587d06f74a792.jpg', 'https://phimimg.com/upload/vod/20240302-1/2694fa589a2f373c1b37df12205148b2.jpg', '<p>Nữ sinh cấp ba Sakura Chiyo khó khăn lắm mới lấy hết cam đảm để tỏ tình với nam sinh cùng khóa Nozaki Umetarou, thế nhưng nhận lại lại là chữ kí của Nozaki và lời mời: “ Cậu có muốn đến nhà tôi không?”. Mặc dù Sakura rất bối rối trước diễn biến bất ngờ này nhưng cô vẫn mang theo hi vọng và đến nhà Nozaki. Không ngờ thứ đang đợi chờ cô lại là bản thảo truyện tranh, không nghĩ ngợi gì cô làm theo lời của Nozaki và bắt đầu tô màu đen cho bản thảo.Sau đó Sakura mới phát hiện ra rằng Nozaki chính là Yumeno Sakiko, một họa sĩ truyện tranh thiếu nữ nổi tiếng.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324322);
