INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-sieu-nho-phan-2', 'Thế Giới Siêu Nhỏ (Phần 2)', 'Tiny World (Season 2)', 'https://phimimg.com/upload/vod/20240228-1/f8cd6214babf85ed4c9483d5bb6e0527.jpg', 'https://phimimg.com/upload/vod/20240228-1/f5a9e429ec02b765727e27ee907f0354.jpg', '<p>Series phim tài liệu này nói về các anh hùng siêu nhỏ ít được chú ý ngoài thiên nhiên. Mỗi tập mang tới nhiều câu chuyện bất ngờ và các thước phim kinh ngạc về đời sống và bản năng sinh tồn kỳ diệu của những sinh vật bé nhỏ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Rudd","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324322);
