INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-tuoi-dep-the-animation', 'Thế Giới Tươi Đẹp The Animation', 'Subarashiki Kono Sekai The Animation', 'https://phimimg.com/upload/vod/20240228-1/6dd801ceae69760ea82796397c7b5577.jpg', 'https://phimimg.com/upload/vod/20240228-1/14c48544f2ae9f1abfab95ea63e91407.jpg', '<p>Tham gia vào Trò chơi tử thần, nhân vật chính Nek đã gặp Shiki - cô gái cùng tham gia vào thành phố ảo Shibuya, họ ký hợp đồng làm đối tác của nhau. Hai người vừa chạy trốn khỏi thần chết, vừa đi tìm sự thật được che giấu trong “trò chơi” và trong chính ký ức của họ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324322);
