INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-giao-ky-phan-1-du-quan-so-tuong-thuc', 'Ngự Giao Ký (Phần 1): Dữ Quân Sơ Tương Thức', 'The Blue Whisper', 'https://phimimg.com/upload/vod/20240228-1/17a3d5e44255493c89bca92ef31232b6.jpg', 'https://phimimg.com/upload/vod/20240228-1/bb88cd3f43d09de284205dc6a2a6bf22.jpg', '<p>Phim lấy bối cảnh một thế giới nơi con người và yêu quái cùng tồn tại, có một chuyện tình vượt qua ranh giới chủng tộc giữa nữ ngự linh sư Kỷ Vân Hòa và thế tử giao nhân Trường Ý.Công chúa Thuận Đức trong 1 lần tình cờ săn được một giao nhân và muốn tìm người thuần hóa nó. Công chúa đã đặt ra 3 nguyện vọng, một là ngự yêu kia phải mở miệng nói tiếng người, hai là ngự yêu bỏ đuôi thành chân, ba là không bao giờ phản nghịch. Thế nhân đều biết, phía Đông ngự yêu đảo, phía Tây ngự yêu sơn, phía Nam ngự yêu cốc cùng với phía Bắc ngự yêu đài là bốn nơi duy nhất trên thế gian còn những người có khả năng thuần ngự yêu sống sót. Mà phía Nam ngự yêu cốc chính là nơi ở của những ngự yêu sư mạnh nhất trong thiên hạ.Kỷ Vân Hòa - 1 ngự yêu sư cao thâm nhưng lại bị mê hoặc bởi người cá Trường Ý. Mọi chuyện bắt đầu khi Trường Ý đến Ngự Yêu cốc, Trường Ý bị nhốt ở Ngự Yêu Cốc ngày ngày bị tra tấn, dùng khổ hình khắc nghiệt. Khi bị giam trong cốc chịu đủ mọi khổ hình thì chỉ có duy nhất Kỷ Vân Hòa thường xuyên đến chăm sóc bôi thuốc cho mình, từ đó trong trái tim Trường Ý chỉ có một mình Kỷ Vân Hòa. Sau này khi biến cố xảy ra, Trường Ý cũng vì muốn cứu Kỷ Vân Hòa mà chặt đi đuôi cá của mình để biến thành đôi chân.Nữ chính Kỷ Vân Hòa là cô gái khao khát tự do, không muốn tranh đoạt, đối với cô ấy Ngự Yêu Cốc chính nhà tù giam hãm mình vì vậy nên cô ấy rất đồng cảm với nam chính Trường Ý,muốn giúp nam chính thoát khỏi chốn địa ngục, trở về với biển cả tự do. Sau này, vì muốn giúp Trường Ý thoát khỏi xiềng xích trói buộc mà bày mưu tính kế lừa gạt Trường Ý, nói với chàng rằng tất cả tình cảm của của nàng dành cho Trường Ý từ đầu đến cuối chỉ là giả.. khiến cho Trường Ý tuyệt vọng rời đi.Sau 6 năm gặp lại, Trường Ý trở thành một Tôn chủ cao cao tại thượng chống lại triều đình, mà Kỷ Vân Hòa lại trở thành một kẻ cạn kiệt sinh lực chỉ đợi ngày chết đi.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Địch Lệ Nhiệt Ba","avatar":""},{"name":"Nhậm Gia Luân","avatar":""},{"name":"Tiêu Thuận","avatar":""},{"name":"Quách Hiểu Đình","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324322);
