INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-thanh-tra-tai-ba', 'Nữ Thanh Tra Tài Ba', 'One The Woman', 'https://phimimg.com/upload/vod/20240228-1/d037fe39197f973ec029326f478dc124.jpg', 'https://phimimg.com/upload/vod/20240228-1/2e616dd86b83e8d1cfbefcca0be85c31.jpg', '<p>Jo Yeon Joo là một công tố viên chống tham nhũng. Trong một vụ án, cô bị mất trí nhớ và bắt đầu sống với tư cách là Kang Mi Na, con dâu nhà tài phiệt. Hành trình tìm lại thân phận thật của Jo Yeon Joo bắt đầu, sự thật đằng sau những việc làm xấu xa của các gia đình tài phiệt và những kẻ đã lạm dụng quyền lực sẽ dần dần được đưa ra ánh sáng.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Honey Lee","avatar":""},{"name":"Lee Sang Yoon","avatar":""},{"name":"Lee Won Geun","avatar":""},{"name":"Jin Seo Yeon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324322);
