INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-co-the-tro-ve-luc-dau-thang-tram-trong-kinh-doanh', 'Nếu Có Thể Trở Về Lúc Đầu: Thăng Trầm Trong Kinh Doanh', 'If At First: Sailing In Business', 'https://phimimg.com/upload/vod/20240228-1/91fa9bc933979a7f22c75c127facbf25.jpg', 'https://phimimg.com/upload/vod/20240228-1/2ca93088d7ac28dc194f925e565f342d.jpg', '<p>Sự phát triển nhanh chóng của Thâm Quyến đã mang lại cho Diệu Tổ sự giác ngộ và động viên to lớn. Anh và người bạn của mình là Tiểu Bánh đã quyết định thành lập doanh nghiệp ở Thâm Quyến và đặt nền móng cho họ. Hai người bắt đầu buôn bán đồ gia dụng nhỏ, qua bao thăng trầm, công việc kinh doanh ngày càng lớn mạnh, họ cũng từng trải qua tình người ấm áp nơi đây.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yang Xu Wen","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324322);
