INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anne-frank-nguoi-ban-yeu-quy-cua-toi', 'Anne Frank, Người Bạn Yêu Quý Của Tôi', 'My Best Friend Anne Frank', 'https://phimimg.com/upload/vod/20240227-1/09a8f3292cdc44b4a08948a9d73b96da.jpg', 'https://phimimg.com/upload/vod/20240227-1/1a9d932e64900112c2be32b1f1a2d87c.jpg', '<p>Dựa trên tình bạn ngoài đời thật giữa Anne Frank và Hannah Goslar, từ Amsterdam bị Đức Quốc xã chiếm đóng cho đến cuộc hội ngộ bất hạnh của họ trong trại tập trung.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'HD', 'Hà Lan', 0, '[{"name":"Josephine Arendsen","avatar":""},{"name":"Aiko Mila Beemsterboer","avatar":""},{"name":"Roeland Fernhout","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324322);
