INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-linh-dam', 'Bách Linh Đàm', 'Bai Ling Tan', 'https://phimimg.com/upload/vod/20240220-1/1fd4aebdb7c53f44afa221b1109fced9.jpg', 'https://phimimg.com/upload/vod/20240220-1/7c5c85022289184170c043c6a0f663d7.jpg', '<p>Bách Linh Đàm - Bai Ling Tan kể câu chuyện của vua quỷ và công chúa xui xẻo. Họ bị lôi kéo về quá khứ trong bộ sưu tập sách. Chun Yao là người bất tử, anh có nhiệm vụ canh gác lũ quái vật tại Wangchuan, nhưng vì mắc sai lầm mà bị trục xuất khỏi thiên đường và trở thành vua của những loài quái vật ở hồ Hundred Spirits. Khi công chúa Han Sheng của Vương quốc Bailu xuống hồ, cô phát hiện ra mình đã mang theo cuốn sách mà chỉ quái vật mới có quyền sở hữu. Cô gặp Chun Yao, con người kiêu ngạo này không có cách nào giải quyết được nên chỉ có thể kéo nàng công chúa tham gia vào hành trình lật mở những điều bí mật trong cuốn sách.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Quách Tuấn Thần","avatar":""},{"name":"Khang Ninh","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324322);
