INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-uu-tu-o-truong-cao-trung-ma-phap-hoi-uc', 'Học Viên Ưu Tú Ở Trường Cao Trung Ma Pháp: Hồi Ức', 'The Irregular At Magic High School: Reminiscence Arc, Mahouka Koukou No Rettousei: Tsuioku-hen', 'https://phimimg.com/upload/vod/20240227-1/3eeb41102f91b33cf013d790975d90af.jpg', 'https://phimimg.com/upload/vod/20240227-1/10090d6d5bb4881f22448afd0a78ad85.jpg', '<p>Nhìn Miyuki và Tatsuya bây giờ, có lẽ khó có thể tưởng tượng họ giống như bất cứ thứ gì khác ngoài tình cảm anh em ruột thịt. Nhưng không phải lúc nào cũng như vậy ..Ba năm trước, Miyuki luôn cảm thấy không thoải mái khi ở cạnh anh trai mình. Những người còn lại trong gia đình họ đối xử với anh không tốt hơn một người hầu thấp hèn, mặc dù anh là Người bảo vệ hoàn hảo, trông chừng Miyuki trong khi cô sống một cuộc sống bình thường ở trường cấp hai. Nhưng điều khiến cô thực sự bận tâm là anh không bao giờ bộc lộ bất kỳ cảm xúc hay suy nghĩ nào của riêng mình.Tuy nhiên, khi nguy hiểm ập đến trong chuyến đi định mệnh đến Okinawa, mối quan hệ anh em của họ sẽ thay đổi mãi mãi…</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324322);
