INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-son-phuc-ma-truyen', 'Kim Sơn Phục Ma Truyện', 'Invisible Guard', 'https://phimimg.com/upload/vod/20240227-1/77ade51eea88d3d3e631e8467f4fe657.jpg', 'https://phimimg.com/upload/vod/20240227-1/93f17b44a9652df617d7dc7db7dcbe66.jpg', '<p>Khai Nguyên thịnh thế, thái tử đương triều bệnh nặng, tất cả thái y đều bó tay, vào lúc hoàng đế bí mật tìm phương thuốc cho thái tử, một vị cao nhân chẩn đoán mệnh của thái tử hết sức đặc thù, cầm mang Phật Cốt Xá Lợi quy y theo Phật môn, nhưng hoàng đề không nỡ để thái tử chịu khổ, liền lệnh cho Bùi Luân Đức có cùng bát tự với thái tử đi xuất gia thay.Tuy trong lòng Bùi Luân Đức bất mãn, nhưng cũng không dám chống lệnh lệnh vua, chỉ có thể buông thả chính mình để giảm bớt phiền muộn.Phương trượng của chùa Kim Quang dự cảm rằng Bùi Luân Đức sẽ gặp nạn hoạ trùng trùng, liền sai võ tăng hàng ma Tiểu Ngũ hộ tống Bùi Luân Đức, bảo vệ hắn an toàn đến chùa Kim Quang</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trình Trác","avatar":""},{"name":"Lâm Phong Diệp","avatar":""},{"name":"Phó Hách An Kỳ","avatar":""},{"name":"Trần Ngọc Dũng","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324322);
