INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-hau-cong-luoc', 'Hoàng Hậu Công Lược', 'The Queen Of Attack', 'https://phimimg.com/upload/vod/20240220-1/cc33c72d17cb2ddd1f9ea811c125e2ee.jpg', 'https://phimimg.com/upload/vod/20240220-1/f51882a856b1b4e321d282985bdcfc9a.jpg', '<p>Phim Hoàng Hậu Công Lược (The Queen of Attack 2021) xoay quanh câu chuyện kể về cô gái Lương Vy Vy khoa thể dục có sức mạnh kỳ lạ đột nhiên xuyên vào bộ phim thần tượng cổ trang mà đàn anh khóa trên của cô, thần tượng nổi tiếng Cảnh Thanh, đóng chính. Cô trở thành nhân vật phế hoàng hậu bị định là sẽ chết ngay trong tập 3. Để thoát khỏi vòng luẩn quẩn chết đi sống lại, cô quyết định nghịch chuyển vận mệnh, trở thành nữ chính, tranh đoạt sủng ái của hoàng thượng, mở ra một câu chuyện tình yêu ngọt ngào kỳ ảo với hoàng thượng.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 10, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cao Tuấn Hàm","avatar":""},{"name":"Mã Tiểu Khâm","avatar":""},{"name":"Thừa Lỗi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324322);
