INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-len-nao-xe-nho-phan-6', 'Tiến Lên Nào Xe Nhỏ! (Phần 6)', 'Go! Go! Cory Carson (Season 6)', 'https://phimimg.com/upload/vod/20240220-1/ff8001fb94af7688d0dd7f0afb33f9de.jpg', 'https://phimimg.com/upload/vod/20240220-1/4259ef5ebd4f2eab9305f31f9e01e9c9.jpg', '<p>Ngày đi biển, chuyện kể lúc đi ngủ và những vui đùa cùng hội bạn thân! Cory Carson luôn sẵn sàng để có thêm tiếng cười và những bài học ấm lòng ở Đồi Bumperton!</p>', 'Hoàn Tất (18/18)', 18, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"AC Lim","avatar":""},{"name":"Paul Killam","avatar":""},{"name":"Kerry Gudjohnsen","avatar":""},{"name":"Maisie Benson","avatar":""},{"name":"Smith Foreman","avatar":""},{"name":"Adelaide Hirasaki","avatar":""},{"name":"Neena-Sinaii Simpo","avatar":""},{"name":"Eli Morse","avatar":""},{"name":"Jim Capobianco","avatar":""},{"name":"Ella Joy Ballesteros","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324322);
