INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-chat', 'Bản Chất', 'Truth Reveals', 'https://phimimg.com/upload/vod/20240220-1/a2540b7f315e66643ffc82957a7ade7a.jpg', 'https://phimimg.com/upload/vod/20240220-1/6a4ed6af248b95826f508391e4f6bc2f.jpg', '<p>Bộ phim Bản Chất (Truth Reveals) vietsub kể về Khempetch, một cô gái xuất thân nghèo khổ nên bản thân cô luôn cảm thấy tự ti. Vốn thông minh và tài giỏi, cô đã tự mình vươn lên và làm tất cả mọi việc để có thể thành công trong ngành thiết kế trang sức. Sau một thời gian phấn đấu, cô đã lột xác và sở hữu cửa hàng trang sức lớn. Để có thể vươn lên đứng đầu trong ngành thiết kế, Khem liên tục bày mưu tính kế nhằm loại bỏ các đối thủ. Thậm chí Khem còn hãm hại Plee, bạn thân của mình, đẩy số phận của Plee một cô gái hiền lành trở nên bất hạnh. Sakul, chồng Khempetch, không đồng tình với những gì cô đang làm nên ngày càng xa cách với cô.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 12, 2021, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Kaneungnich Jaksamithanon","avatar":""},{"name":"Cris Horwang","avatar":""},{"name":"Jaksamittanon Kaneungnij","avatar":""},{"name":"Golf Anuwat Choocherdratana","avatar":""},{"name":"Art Pasut Banyam","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324322);
