INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-gioi-ky-duyen', 'Vạn Giới Kỳ Duyên', 'The Legendary Monster Emperor', 'https://phimimg.com/upload/vod/20240220-1/b70ea09561188fae8d786e979f5cb498.jpg', 'https://phimimg.com/upload/vod/20240220-1/eb23d15b2d1f8babd81f97ab9644eac4.jpg', '<p>Gọi hắn là ma, hắn vạch kiếm ngang trời, khí thế lay động đất trời, khí thế còn hơn cả thần tiên! Đạo hắn là Phật, hắn tiêu diệt bát hoang, thây chất thành núi, máu chảy thành sông, còn đáng sợ hơn cả yêu ma. Lấy máu rửa thân, lấy lửa luyện cốt. Bất tử bất diệt, trở thành Hồng Manh đại yêu đạo! Thiếu niên Lâm Phong vùng dậy từ khốn cảnh. Gặp được Hồng Manh yêu chủng, trở thành yêu tổ duy nhất của trời đất.</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324322);
