INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuc-no-dang-yeu', 'Cục Nợ Đáng Yêu', 'Hello Misfortune', 'https://phimimg.com/upload/vod/20240220-1/9506a08dcfd221e8dc21996c2396f42b.jpg', 'https://phimimg.com/upload/vod/20240220-1/d4a8bf3707af879215765411389dee07.jpg', '<p>Qua đời sau tai nạn giao thông, cô gái 17 tuổi Phan Tiểu Du (do Trần Gia Tuệ đóng) đi vào chiều không gian khác, được gia nhập ban quản lý nhân sinh, có nhiệm vụ quản lý con người ở nhân gian, dựa trên luật nhân quả. Đối tượng mà Tiểu Du phải quản lý đó là Trần Bắc Hà (do Hồ Hồng Quân đóng), một anh chàng giao thức ăn nhanh, tính tình hiền lành, tốt bụng và có phần cam chịu. Bắc Hà hàng ngày dãi nắng dầm mưa tích cóp từng đồng để lo cho bà nội và trả số nợ cờ bạc của ba mình, nhưng dường như gia đình lại thờ ơ. Những rắc rối càng lúc càng nhiều, khiến Bắc Hà cảm thấy khó thở. Anh không biết rằng những vận xui liên tiếp đeo bám, một phần do “cục nợ” Tiểu Du gây ra.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 12, 2021, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Hồ Hồng Quân","avatar":""},{"name":"Trần Gia Tuệ","avatar":""},{"name":"Mạch Mỹ Ân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324323);
