INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dien-ro', 'Điên Rồ', 'Rabid', 'https://phimimg.com/upload/vod/20240215-1/28b0b2b3e9b026a9beae526913efcdec.jpg', 'https://phimimg.com/upload/vod/20240215-1/0681ab9c423a4394b520caa78f1357a9.jpg', '<p>Trong loạt phim kinh dị này, lệnh phong tỏa do đại dịch mang đến nỗi khiếp sợ và bi kịch, biến trạng thái bình thường mới thành những cơn ác mộng mới.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 12, 2021, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Chesca Diaz","avatar":""},{"name":"Jake Macapagal","avatar":""},{"name":"Jay Glorioso","avatar":""},{"name":"Ameera Johara","avatar":""},{"name":"Kent Gonzales","avatar":""},{"name":"Donna Cariaga","avatar":""},{"name":"Yñigo Delen","avatar":""},{"name":"Chrome Prince Cosio","avatar":""},{"name":"Pam Gonzales","avatar":""},{"name":"Vance Larena","avatar":""},{"name":"Ayeesha Cervantes","avatar":""},{"name":"Ricci Rivero","avatar":""},{"name":"Ube Lola","avatar":""},{"name":"Brace Arquiza","avatar":""},{"name":"Moira Lang","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324323);
