INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-binh-may-lbx-girls', 'Nữ Binh Máy LBX Girls', 'Soukou Musume Senki', 'https://phimimg.com/upload/vod/20240215-1/68679cfebb0032fadbf20c6efa0a1bf8.jpg', 'https://phimimg.com/upload/vod/20240215-1/0227fbe3e813ebbb0d3d66ba24db2adb.jpg', '<p>Năm cô gái có biệt danh&nbsp; những cô gái mặc giáp, bị cướp đi những ngày tháng bình thường, trên tay chân họ đeo vũ khí chiến thuật mang tên đơn vị LBX. Nhiệm vụ của các cô gái được lựa chọn và chuyển giao là quét sạch và tiêu diệt Mimesis dạng sống bằng kim loại, thứ tiếp tục ăn mòn và sinh sôi nảy nở trên nhiều thế giới. Sống như một lính đánh thuê bị ép buộc xuyên thời gian và không gian, đó là một chuyến đi học nguy hiểm đến tính mạng mang lại cái nhìn thoáng qua về hy vọng và tuyệt vọng của thế giới!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324323);
