INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('godzilla-diem-di-thuong', 'Godzilla: Điểm Dị Thường', 'Godzilla Singular Point', 'https://phimimg.com/upload/vod/20240215-1/7ecb3d7746ddd351366fa0e9d3aa8a63.jpg', 'https://phimimg.com/upload/vod/20240215-1/15c9000a3ca24721d8dad0a5355c92c1.jpg', '<p>Tình cờ quen biết nhờ một bài hát bí ẩn, cô nàng sinh viên cao học cùng một kỹ sư dẫn đầu cuộc chiến chống lại một thế lực khó tin có thể khiến thế giới diệt vong.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Miyamoto Yume","avatar":""},{"name":"Ishige Shoya","avatar":""},{"name":"Kuno Misaki","avatar":""},{"name":"Kugimiya Rie","avatar":""},{"name":"Kiuchi Taro","avatar":""},{"name":"Takagi Wataru","avatar":""},{"name":"Takeuchi Ayako","avatar":""},{"name":"Azakami Yohei","avatar":""},{"name":"Urayama Jin","avatar":""},{"name":"Koiwai Kotori","avatar":""},{"name":"Suzumura Kenichi","avatar":""},{"name":"Koda Natsuho","avatar":""},{"name":"Tezuka Hiromichi","avatar":""},{"name":"Okiayu Ryotaro","avatar":""},{"name":"Onodera Runa","avatar":""},{"name":"Miyake Kenta","avatar":""},{"name":"Is","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324323);
