INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-hinh-dai-toi-4', 'Thất Hình Đại Tội 4', 'The Seven Deadly Sins 4', 'https://phimimg.com/upload/vod/20240215-1/a1de252cafbeab7fdbe974e2520a7750.jpg', 'https://phimimg.com/upload/vod/20240215-1/eea7e539c8a9e617fb252ce2fe54c045.jpg', '<p>Mặc dù đã đẩy lùi được cuộc xâm lược của quỷ ở Vương quốc Lioness, cuộc chiến vẫn chưa kết thúc, vì Vương quốc Camelot của Arthur vẫn đang bị chiếm đóng bởi đội quân quỷ và những thành viên sống sót của Jikkai. Tuy nhiên, để bắt đầu phản công, Thất Hình Đại Tội cần sự hợp sức của tất cả các thành viên. Thật không may, King và Diane vẫn đang trốn trong Khu rừng Tiên Vương, nơi họ được khám phá lịch sử kỳ lạ của Jikkai.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yūki Kaji","avatar":""},{"name":"Aoi Yuki","avatar":""},{"name":"Tatsuhisa Suzuki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324323);
