INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-ma-tien-te', 'Giải Mã Tiền Tệ', 'Money, Explained', 'https://phimimg.com/upload/vod/20240215-1/ff74cb3f08dae56fa0073fdc23edf28e.jpg', 'https://phimimg.com/upload/vod/20240215-1/5f0920daeeb2f2e98101a6b59a3d8ef8.jpg', '<p>Chúng ta tiêu tiền, mượn tiền, và để dành tiền. Giờ hãy bàn về tiền và những cạm bẫy của nó – từ thẻ tín dụng, sòng bạc, bọn lừa đảo cho đến các khoản vay của sinh viên.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324323);
