INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-cam-do-nong-bong-latinh', 'Sự Cám Dỗ Nóng Bỏng: Latinh', 'Too Hot To Handle: Latino', 'https://phimimg.com/upload/vod/20240215-1/2903e083b0baf0b3e1668aa29cf3ea11.jpg', 'https://phimimg.com/upload/vod/20240215-1/e17d8f11d87404ce50145dc5e8d1118c.jpg', '<p>Trong chương trình thực tế này, các nam thanh nữ tú độc thân từ Mỹ Latinh và Tây Ban Nha sẽ nhận thử thách nhịn tình dục. Tin vui là sự tiết chế đi kèm với 100.000 USD.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 16, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Itatí Cantoral","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324323);
