INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-re', 'Ở Rể', 'My Heroic Husband', 'https://phimimg.com/upload/vod/20240215-1/13ec8fb5e15c7de3f9fd697570286477.jpg', 'https://phimimg.com/upload/vod/20240215-1/c05bfd4e3312e82df003b4196d65fc03.jpg', '<p>Bộ phim kể về Ninh Nghị - người đến ở rể tại gia đình buôn vải nhà họ Tô. Anh ta đã giúp thê tử cùng gây dựng sự nghiệp, xoay chuyển giới thương nhân dưới triều Vũ và trở thành người giàu nhất Giang Ninh.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 11, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Quách Kỳ Lân","avatar":""},{"name":"Tống Dật","avatar":""},{"name":"Tưởng Y Y","avatar":""},{"name":"Gao Thự Quang","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324323);
