INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('o-re', 'Ở Rể', 'My Heroic Husband', 'ở rể my heroic husband quách kỳ lân tống dật tưởng y y gao thự quang ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-tuoc-tu-than-va-co-hau', 'Công Tước Tử Thần Và Cô Hầu', 'Shinigami Bocchan To Kuro Maid, The Duke Of Death And His Maid', 'https://phimimg.com/upload/vod/20240215-1/00f1d67a95767dc61eaf61ad82fb4096.jpg', 'https://phimimg.com/upload/vod/20240215-1/25001072ef7578f1acd47b11fb1a0a36.jpg', '<p>Bị nguyền rủa từ nhỏ, một công tước trẻ nhận được thứ sức mạnh không hề mong muốn là giết hết mọi thứ mà cậu ta chạm vào. Bị buộc phải cách xa gia đình và sống ở một dinh thự sâu trong rừng, cậu bị đối xử như thể không có tồn tại và tiếp tục bị mọi người xa lánh. Tuy nhiên cậu không chỉ một mình. Rob và Alice là quản gia và người hầu luôn ở bên cạnh cậu ta. Alice thích trêu chọc cậu, và dần dà mối quan hệ giữa hai người phát triển, cậu công tước trẻ muốn phá bỏ lời nguyền chết chóc của mình. Để giải được lời nguyền ấy, cậu sẽ cần đến sự trợ giúp từ những người bạn với sức mạnh siêu nhiên.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324323);
