INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-cham-rai-cua-duoc-si-gian-lan-lap-hieu-thuoc-o-the-gioi-khac-nao', 'Cuộc Sống Chậm Rãi Của Dược Sĩ Gian Lận: Lập Hiệu Thuốc Ở Thế Giới Khác Nào', 'Chito Kusushi No Suro Raifu', 'https://phimimg.com/upload/vod/20240215-1/e234d41998ca2009f116bdea626a4d1e.jpg', 'https://phimimg.com/upload/vod/20240215-1/890df5120223926ebb69551497822ba2.jpg', '<p>Một ngày nọ, Reiji đột nhiên bị đưa đến một thế giới khác. Anh ấy đã phát huy hết khả năng của mình để chế tạo ra những loại thuốc tốt hơn, giúp anh ấy kiếm được rất nhiều tiền và dùng số tiền đó để dựng một hiệu thuốc! Một Elf gặp khó khăn khi nhắm bắn với cây cung của mình? Cho anh ta một ít thuốc nhỏ mắt! Một con Rồng luôn vô tình thở ra lửa? Đừng lo lắng, chúng tôi đã có thuốc ho dành cho bạn! Cuộc sống mới, vui vẻ, chậm rãi của Reiji với tư cách là một dược sĩ trong một tiệm thuốc trong làng bắt đầu bây giờ đã bắt đầu!!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324323);
