INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jo-yi-va-am-hanh-ngu-su-ngu-su-tai-ba-va-quy-co-thong-thai', 'Jo Yi Và Ám Hành Ngự Sử (Ngự Sử Tài Ba Và Quý Cô Thông Thái)', 'Secret Royal Inspector & Joy', 'https://phimimg.com/upload/vod/20240209-1/c93a82b884464755397b061f0bf8c2a7.jpg', 'https://phimimg.com/upload/vod/20240209-1/95ec130ab63b7ace5bae4fd65615ad88.jpg', '<p>Jo Yi và Ám Hành Ngự Sử (Ngự Sử Tài Ba Và Quý Cô Thông Thái, Secret Royal Inspector Joy) kể về câu chuyện của một chàng thanh niên hiền hòa nhưng không kém phần tiêu cực, muốn kiếm sống bằng kinh doanh một quán bánh. Ngẫu nhiên chàng trở thành một ngự sử bí ẩn, tuần tra cơ quan các tỉnh để vạch trần quan chức nằm vùng tham nhũng. Nhưng chàng vẫn có thể duy trì một cuộc sống thoải mái, chẳng cần trả công cho công việc ngự sử cực nhọc. Chàng hợp tác với một quý cô thông minh nhưng đã ly hôn với chồng để khám phá ra nhiều sự thật bí ẩn. Tiếp sau đó, chàng ta lập một kế hoạch to lớn để vạch trần các vụ đen tối, tham nhũng...</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ok Taec-yeon","avatar":""},{"name":"Kim Hye-yoon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324323);
