INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-va-chung-ta-o-ben-nhau', 'Tôi Và Chúng Ta Ở Bên Nhau', 'Be Together', 'https://phimimg.com/upload/vod/20240209-1/a5f1762fb8fb198a06e34aa26e4688c2.jpg', 'https://phimimg.com/upload/vod/20240209-1/a17eacf6f556a1f387c96ca40465b620.jpg', '<p>Tôi Và Chúng Ta Ở Bên Nhau xoay quanh bốn người phụ nữ sắp bước sang tuổi ba mươi. Nhóm bạn thân Hạ Nhan, Lương Sảng, Triệu Tiểu Lôi và Hạng Nam quen biết nhau từ thời còn học đại học. Sau khi tốt nghiệp, họ cùng nhau làm việc và sinh sống ở cùng một thành phố. Mỗi người một tính cách, một giấc mơ riêng, tuy nhiên trải qua nhiều trắc trở, bốn cô gái trẻ cổ vũ và giúp đỡ lẫn nhau, cùng nhau giải quyết những vấn đề khó khăn xảy ra trong cuộc sống, cũng chứng kiến sự trưởng thành và thay đổi của nhau.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 6, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Khương Nghiên","avatar":""},{"name":"Tôn Di","avatar":""},{"name":"Trương Bân Bân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324323);
