INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jiva-vu-dieu-uoc-mo', 'Jiva! – Vũ Điệu Ước Mơ', 'Jiva!', 'https://phimimg.com/upload/vod/20240209-1/0c3d764fc4177158fe38e9a526f53ce2.jpg', 'https://phimimg.com/upload/vod/20240209-1/ee26496b07569b8185fd2f40c10d3a0a.jpg', '<p>Một vũ công đường phố tài năng ở Umlazi, Durban phải chế ngự được nỗi sợ hãi và đối mặt với sự phản đối của gia đình để theo đuổi ước mơ nhảy múa.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 15, 2021, 'Vietsub', 'HD', 'Nam Phi', 0, '[{"name":"Noxolo Dlamini","avatar":""},{"name":"Candice Modiselle","avatar":""},{"name":"Sne Mbatha","avatar":""},{"name":"Stella Dlangalala","avatar":""},{"name":"Zazi Kunene","avatar":""},{"name":"Ntuthuzelo Grootboom","avatar":""},{"name":"Given Stuurman","avatar":""},{"name":"Tony Kgoroge","avatar":""},{"name":"Anga Makubalo","avatar":""},{"name":"Sibulele Gcilitshana","avatar":""},{"name":"Zamani Mbatha","avatar":""},{"name":"Kagiso Modupe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324323);
