INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sakugan', 'SAKUGAN', 'Sacks&Guns!!', 'https://phimimg.com/upload/vod/20240209-1/e7906c55aeafb37582e404575dfe5705.jpg', 'https://phimimg.com/upload/vod/20240209-1/765641371f365aed616a76e842378a01.jpg', '<p>Một thuộc địa theo phong cách châu Á Pinyin được bao phủ bởi đèn neon màu rực rỡ và sương khói. Sống như một công nhân trong thành phố, Memenpu có ước mơ trở thành người đánh dấu để đi du lịch bên ngoài thuộc địa. Vào đêm lễ hội hàng năm, người cha già của Marker và cô con gái Walsh và Linda trở về sau chuyến đi của họ...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324323);
