INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-biet-phan-2', 'Đặc Biệt (Phần 2)', 'Special (Season 2)', 'https://phimimg.com/upload/vod/20240209-1/a221d49351720e7aa99514d4e5e2f334.jpg', 'https://phimimg.com/upload/vod/20240209-1/7b7d9ff1ea6a0b58fc564678536753d0.jpg', '<p>Giờ quan hệ giữa mẹ con xa cách, Ryan tiếp tục tự mình khám phá thế giới, với tất cả những thăng trầm phức tạp mà tình yêu và cuộc sống mang đến cho cậu.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan O''Connell","avatar":""},{"name":"Jessica Hecht","avatar":""},{"name":"Punam Patel","avatar":""},{"name":"Max Jenkins","avatar":""},{"name":"Marla Mindelle","avatar":""},{"name":"Augustus Prew","avatar":""},{"name":"Patrick Fabian","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324323);
