INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-yeu-trong-vung-ngo-om', 'Bùa Yêu Trong Vũng Ngò Ôm', 'To Me, It''s Simply You', 'https://phimimg.com/upload/vod/20240205-1/0abec0b19a8fa39a4e7b2f75dd5c810f.jpg', 'https://phimimg.com/upload/vod/20240205-1/98711797d678dd37a03de01236889143.jpg', '<p>xoay quanh Kiew, là một trai quê lên Bangkok làm việc. Một ngày nọ, bạn gái Kiew bất ngờ nói lời chia tay. Đau lòng, Kiew quyết định quay về quê, nơi anh gặp một cô gái tên là Chompoo. Lúc đầu, Kiew và Chompoo không ưa nhau và liên tục gây gổ vì Kiew muốn bán mảnh đất của bà mình, cũng là nơi Chompoo làm việc. Nhưng thời gian trôi qua, Kiew dần thấy được sự chân thành của Chompoo và bắt đầu cảm mến cô gái này.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Nadech Kugimiya","avatar":""},{"name":"Bow Maylada Susri","avatar":""},{"name":"Preaw Anusara Wantongtak","avatar":""},{"name":"Boss Natpongpon Suddee","avatar":""},{"name":"Namfon Sueangsuda Lawanprasert","avatar":""},{"name":"Yeong Lookyee","avatar":""},{"name":"Chamaiporn Sitthiworanang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324323);
