INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-nhan-ban-2021', 'Người Nhân Bản', 'Seobok', 'https://phimimg.com/upload/vod/20240220-1/0bc9488e1e8c554c4fd9ee663efea2f5.jpg', 'https://phimimg.com/upload/vod/20240220-1/98f4f5e7392c40f542c4340c542bfca2.jpg', '<p>Người Nhân Bản kể về Ki-hun – một cựu đặc vụ sống tách biệt với thế giới bên ngoài kể từ sau biến cố trong quá khứ, chấp nhận thực hiện nhiệm vụ cuối cùng từ Cơ quan Tình báo. Anh phải chịu trách nhiệm di chuyển Seobok, một đối tượng thử nghiệm được tạo ra bằng cách nhân bản tế bào gốc và biến đổi gen. Tuy nhiên mọi việc không hề suôn sẻ với họ, khi Seobok trở thành mục tiêu của các thế lực khác với những tham vọng và âm mưu khó đoán. Ki-hun sẽ vượt qua tất cả những hiểm nguy đang chực chờ phía trước, hay Seobok cuối cùng sẽ rơi vào tay kẻ muốn chiếm đoạt vận mệnh của toàn nhân loại?</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 1, '[{"name":"Gong Yoo","avatar":""},{"name":"Park Bo Gum","avatar":""},{"name":"Jo Woo Jin","avatar":""},{"name":"Jang Young Nam","avatar":""},{"name":"Na Gwang Hoon","avatar":""},{"name":"Jung Mi Nam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324323);
