INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-ky-lan', 'Thị Trấn Kỳ Lân', 'Magic Town', 'https://phimimg.com/upload/vod/20240219-1/a797c97e1ad19c59ad9334b3c5b26f66.jpg', 'https://phimimg.com/upload/vod/20240219-1/7459358b507bed9fe40da5413ec9ee48.jpg', '<p>Châu Khôn một lòng tu luyện, Lý Kiều Nhiên một lòng muốn trừ gian diệt bạo, hai người vốn là trúc mã lại không nhưng từ bé lại không hợp nhau. Nhưng một chuyện li kì đã khiến số phận hai người bị cuốn vào nhau. Châu Khôn bị cảm động trước nhiều lần liều mạng điều tra của Lý Kiều Nhiên, hai người cùng nhau điều tra án.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Qi Sheng Han","avatar":""},{"name":"Wang Zhi Yi","avatar":""},{"name":"Sun Lei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324323);
