INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('400-bullets', '400 Bullets', '400 Bullets', 'https://phimimg.com/upload/vod/20240219-1/1c02ba2b83e7c1004952348ca1275bc8.jpg', 'https://phimimg.com/upload/vod/20240219-1/0bf4f4633058743aaff973e90141710d.jpg', '<p>Một nhóm lính đánh thuê đánh chặn và có được bốn tên lửa vào một đêm lạnh lẽo, tuyết rơi ở Afghanistan. Double-Crossed, Black Ops Chuyên gia Noah Brandt thoát khỏi các chân điều hướng. Khi chạy và bị thương, anh ta vấp ngã trên tiền đồn vận chuyển của người Anh và lưới. Đơn vị chiếm lĩnh tiền đồn đang diễn ra trong một nhiệm vụ, chỉ với hai binh sĩ và 400 viên đạn còn lại để bảo vệ hợp chất.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324323);
