INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tao-nen-vo-nhac-kich-malinche-phim-tai-lieu-tu-nacho-cano', 'Tạo Nên Vở Nhạc Kịch Malinche: Phim Tài Liệu Từ Nacho Cano', 'Making Malinche: A Documentary By Nacho Cano', 'https://phimimg.com/upload/vod/20240219-1/02841c1f42e8f715df4891e5e72b68dc.jpg', 'https://phimimg.com/upload/vod/20240219-1/5b3e382be1473c03a4295d9b12d05725.jpg', '<p>Khám phá quá trình sáng tạo đằng sau vở nhạc kịch mới của Nacho Cano dựa trên chuyện tình của Malinche và Hernán Cortés và sự kết hợp giữa hai thế giới của họ.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Nacho Cano","avatar":""},{"name":"Melissa Barrera","avatar":""},{"name":"Thaddeus Pearson","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324323);
