INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-am-ap', 'Kỳ Nghỉ Ấm Áp', 'Vacation Of Love', 'https://phimimg.com/upload/vod/20240126-1/e4c44e68ea5fcb482d6b2f0dbcfb6a84.jpg', 'https://phimimg.com/upload/vod/20240126-1/ada37de3bee769c15e3a21f264d9c8d2.jpg', '<p>Bộ phim kể về một loạt những câu chuyện vui vẻ, lãng mạn đầy hài hước xảy ra tại \Resort Tình Yêu Đích Thực\ trong kỳ nghỉ bảy ngày vào dịp tết Âm lịch 2021 của ba nhóm du khách. Nữ chính Hứa Khả Y là quản lý, đơn đả độc đấu trong làng giải trí. Vào đêm giao thừa, vì tình yêu không kết trái nên mượn rượu giải sầu. Nam chính Hầu Hạo vẫn luôn lặng lẽ quan tâm tới cô vô tình bước vào cuộc sống của nữ chính, tạo ra \phản ứng hóa học\ đầy ngọt ngào lãng mạn. Một cặp vợ chồng sắp tan vỡ, nam phụ Trần Bân Bân trình diễn tiết mục theo đuổi lại vợ đầy hài hước. Trong kỳ nghỉ, còn diễn ra rất nhiều tình tiết bình thường mà đầy ấm áp khác...</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yao Chen","avatar":""},{"name":"Bạch Vũ","avatar":""},{"name":"Da Peng","avatar":""},{"name":"Trương Tịnh Sơ","avatar":""},{"name":"Xiaoyi Chen","avatar":""},{"name":"Hồ Quân","avatar":""},{"name":"Gao Diệp","avatar":""},{"name":"Candy","avatar":""},{"name":"Zheng Yun Long","avatar":""},{"name":"Zhu Yan Man Zi","avatar":""},{"name":"Zhou Cheng Ao","avatar":""},{"name":"Khương Tử Tân","avatar":""},{"name":"Karen","avatar":""},{"name":"Kang Ke Ren","avatar":""},{"name":"Lancia","avatar":""},{"name":"Mingzhu Li","avatar":""},{"name":"Yuan Xie","avatar":""},{"name":"Zhu Shuan Zhong","avatar":""},{"name":"Tu Ling","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387e