INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-khuat-hoc-duong-melancholia', 'Góc Khuất Học Đường (Melancholia)', 'Melancholia', 'https://phimimg.com/upload/vod/20240118-1/2ab5ed96ccb48b2ec99cb67140598d2c.jpg', 'https://phimimg.com/upload/vod/20240118-1/3ff0eeef3b09f289d06092c1beb505ad.jpg', '<p>Bộ phim truyền hình Hàn Quốc Góc Khuất Học Đường - Melancholia (2021) kể về câu chuyện tình yêu đẹp đẽ nhưng bị ngăn cấm giữa cô giáo dạy toán xinh đẹp Ji Yoon Soo (do Lim Soo Jung thủ vai) và thiên tài toán học Baek Seung Yoo (do Lee Do Hyun thủ vai). Melancolía lấy bối cảnh tại một trường trung học tư thục tên là Trường trung học Ahseong. Vẻ ngoài mỏng manh của Ji Yoon Soo để lại cho mọi người ấn tượng đầu tiên nhẹ nhàng và tốt bụng, nhưng thực tế, cô lại có tính cách cứng rắn và ngoan cố. Một khi đã quyết tâm làm điều gì đó, cô ấy sẽ làm đến cùng. Cô Ji đam mê toán học và hy sinh cả giờ ăn giấc ngủ khi gặp một bài toán khó. Đối với môn toán, cô khuyến khích học sinh tự tìm ra cách giải. Baek Seung Yoo trầm lặng, không quan tâm đến bất cứ điều gì và đứng bét toàn trường. Cậu được coi là một học sinh cá biệt trong mắt mọi người. Thế nhưng, thật ra cậu đã từng tham gia nhiều cuộc thi Olympic Toán khi còn nhỏ. Cậu được mời theo học MIT khi lên 10 tuổi, nhưng bất ngờ thay, cậu thôi học và biến mất hoàn toàn khi 12 tuổi. Cậu được gọi là “Thiên Tài Toán Học Đã Biến Mất”. Với sự quan tâm và dẫn dắt của cô Ji, điểm số của học sinh cá biệt Baek Seung Yoo đã cải thiện và trở thành học sinh đứng đầu lớp. Tuy nhiên, cô Ji không ngờ rằng sự quan tâm của cô lại khiến các học sinh khác và những phụ huynh đồn đại về scandal giữa giáo viên và học sinh. Bộ phim truyền hình Hàn Quốc Melancolía do Lim Soo-j Jung (Tìm kiếm: WWW</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 12, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Im Soo-jung","avatar":""},{"name":"Lee Do-hyeon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324323);
