INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-vi-con', 'Cuộc Chiến Vì Con', 'Vanquish', 'https://phimimg.com/upload/vod/20240207-1/e9f6f3e2465f7b0e746aa2e14079192f.jpg', 'https://phimimg.com/upload/vod/20240207-1/6f3de3ff139b7c9cf968c5b4211c0269.jpg', '<p>Nội dung phim xoay quanh câu chuyện của một người mẹ từng buôn bán, vận chuyển ma túy tại Nga đang muốn xóa bỏ đi quá khứ của mình tên là Victoria. Nhưng cảnh sát về hưu tên Damon vì muốn cô đối đầu với mình trong một cuộc chiến, để khiêu khích và ép buộc Victoria ra mặt hắn đã bắt cóc con gái cô. Để cứu con gái, Victoria bắt buộc phải bước vào trận chiến này.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Morgan Freeman","avatar":""},{"name":"Ruby Rose","avatar":""},{"name":"Patrick Muldoon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324323);
