INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('te-cong-hang-long-giang-the', 'Tế Công: Hàng Long Giáng Thế', 'Master Ji Gong', 'https://phimimg.com/upload/vod/20240205-1/4ab1a9edff96349d63de17d0ff6ff808.jpg', 'https://phimimg.com/upload/vod/20240205-1/8cbf3d411d2869c45a3f8b74243f2475.jpg', '<p>Tế Công: Hàng Long Giáng Thế Thôn Vĩnh Ninh dưới chân núi Xích Thành, có một cậu bé ngoan ngoãn tên Lý Tu Duyên vì muốn người mẹ bị bệnh triền miên nhanh khỏi bệnh nên một lòng muốn trở thành anh hùng, cậu có lòng nhưng toàn gây ra chuyện xấu khiến cho cả thôn gà bay chó sủa. Sau một lần gặp hiểm nguy, cậu phát hiện ra bản thân là chuyển thế của anh hùng la hán hàng long. Cha của cậu, Lý Mậu Xuân bị Kim Linh mê hoặc, ông vì muốn bảo vệ Lý Tu Duyên nên cướp đoạt kim thân. Nhưng kim thân của ông lại bị Kim Linh cướp đi hiến tế cho Kim Sí Đại Bằng để Kim Sí Đại Bằng phục sinh trở lại huỷ diệt nhân gian.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Chu Tinh","avatar":""},{"name":"Bạch Văn Hiển","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324323);
