INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-kiem-nguoi-cha', 'Tìm Kiếm Người Cha', 'The Tender Bar', 'https://phimimg.com/upload/vod/20240205-1/179023ddde9e6d193a2c3fd668bb6b43.jpg', 'https://phimimg.com/upload/vod/20240205-1/f5b3d8998e26f53353d8247cc4396d20.jpg', '<p>Một cậu bé (Jr.) tìm kiếm một người thay thế cho cha mình, người đã biến mất ngay sau khi anh ta sinh ra và trái phiếu với chú Charlie và các khách hàng quen tại một quán bar ở Long Island. Bác Charlie làm việc như một nhân viên pha chế ở đó và biết tất cả các nhân viên và khách hàng quen thông thường. Anh ta là một cá nhân lôi cuốn và tất cả những người bạn của mình rất háo hức để bắt đầu Jr. vào các nghi thức của họ. Jr. lắng nghe rất kỹ về những câu chuyện của những người đàn ông này và dựa vào những câu chuyện này để được hướng dẫn về cách sống</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324323);
