INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-do-cua-nhung-dieu-nho-be-hoan-hao', 'Bản Đồ Của Những Điều Nhỏ Bé Hoàn Hảo', 'The Map Of Tiny Perfect Things', 'https://phimimg.com/upload/vod/20240205-1/255094c8eca59a2c8985bf9bec9f2f2f.jpg', 'https://phimimg.com/upload/vod/20240205-1/f2b614a2b4503c8035821e67541714bb.jpg', '<p>Bản Đồ Của Những Điều Nhỏ Bé Hoàn Hảo là câu chuyện sẽ thế nào nếu bạn bị kẹt trong một vòng tuần hoàn của thời gian, mọi thứ xung quanh bạn sẽ lặp lại sau 12 giờ đêm. Đúng kiểu Chỉ có bạn tỉnh và mọi người đang mộng du. Đó chính xác là cuộc sống của Mark. Cậu đang rất chán vì mọi thứ đang xảy ra xung quanh mình. Nhưng đó có thực sự là vấn đề không? Khi mà mỗi ngày chính cậu cũng không thay đổi. Cậu làm những gì mà ngày hôm qua mình vẫn làm, cậu vẫn đến những nơi mà mình từng đi. Cậu vẫn đang ở trong vùng an toàn của chính bản thân mình mà không quan tâm đến mọi người xung quanh, chính là những người thân của cậu Cho tới khi cậu gặp Margaret một người cũng đang trong tình trạng giống Mark. Họ đã kết bạn và cùng nhau chia sẻ những điều thú vị mà mình thấy cho đối phương, cùng khám phá thêm nữa để chợt nhận ra trong suốt thời gian qua mình đã bỏ sót qua biết bao điều tốt đẹp xung quanh mình.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kathryn Newton","avatar":""},{"name":"Kyle Allen","avatar":""},{"name":"Anna Mikami","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324323);
