INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-mo-but-ky-trung-khoi-xa-cot-phat-thue', 'Đạo Mộ Bút Ký: Trùng Khởi: Xà Cốt Phật Thuế', 'Reunion: Escape From The Monstrous Snake', 'https://phimimg.com/upload/vod/20240207-1/5ebec2f0b2dec24ed46ab0b625de111a.jpg', 'https://phimimg.com/upload/vod/20240207-1/3ec237c88d78083e028e82e1aa6e9680.jpg', '<p>Bộ phim kể về cuộc phiêu lưu của Hắc Hạt Tử , để giải cứu những người đồng đội trong quá khứ, đi sâu vào những khu rừng rậm của Campuchia, chiến đấu chống lại những con sâu kỳ dị và kỳ dị ẩn sâu trong những di tích , và giải mã bí ẩn về sự mất tích của những người đồng đội.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Quý Thần","avatar":""},{"name":"Bành Cao Xướng","avatar":""},{"name":"Tần Sở Minh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324323);
