INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luon-co-tinh-yeu-trong-cach-ly', 'Luôn Có Tình Yêu Trong Cách Ly', 'All U Need Is Love', 'https://phimimg.com/upload/vod/20240207-1/9e1bc2aea9470e1c6e34eaab94cddb0b.jpg', 'https://phimimg.com/upload/vod/20240207-1/fe1bdd5b54d01a254386a00b779e6d75.jpg', '<p>Công ty sản xuất của Hồng Kông sản xuất, số tiền thu được sẽ được chuyển trực tiếp đến các nghệ sĩ và kỹ thuật viên trong ngành điện ảnh Hồng Kông.&nbsp;vốn bị ảnh hưởng nặng nề vào năm ngoái bởi dịch Covid19.Luôn có tình yêu trong cách ly do Cổ Thiên Lạc kêu gọi sản xuất, Hiệp hội Nghệ sĩ Biểu diễn Hong Kong và Hiệp hội Công nhân Điện ảnh Hong Kong khởi xướng. Hơn 10 công ty điện ảnh góp sức. Phim phân ra 3 tổ quay, chỉ trong 15 ngày đã hoàn thành tác phẩm. bộ phim lấy bối cảnh một khách sạn bị cách ly 14 ngày vì có 3 người bị nghi nhiễm Covid đã ở đó. Khách trong đó đủ mọi thành phần giai cấp, tính cách, tạo nên những xung đột tưởng chừng khó có thể hòa giải. Tuy nhiên, sau 14 ngày bị cách ly, họ đã cùng nhau vượt qua khó khăn.&nbsp;</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Thái Khiết","avatar":""},{"name":"Carlos Chan","avatar":""},{"name":"Haley Chan","avatar":""},{"name":"Thành Long","avatar":""},{"name":"Châu Tú Na","avatar":""},{"name":"Stephanie Che","avatar":""},{"name":"Trịnh Tắc Sĩ","avatar":""},{"name":"Trương Trí Lâm","avatar":""},{"name":"Trương Quốc Cường","avatar":""},{"name":"Louis Cheung","avatar":""},{"name":"Max Tat-Lun Cheung","avatar":""},{"name":"Trương Văn Từ","avatar":""},{"name":"Tiền Gia Lạc","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324323);
