INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-ma-ti-tay-vuc-di-thu', 'Trấn Ma Ti: Tây Vực Dị Thú', 'The Demon Suppressors: West Barbarian Beast', 'https://phimimg.com/upload/vod/20240207-1/9d8b98a90187611fa5a8a352206a7879.jpg', 'https://phimimg.com/upload/vod/20240207-1/08acca170824bfe96b70034d55143d9c.jpg', '<p>Hàng trăm năm trước, Ngọc Tu tiên sư phong ấn dị thú tám phương, chủ thú phương Tây hóa thành linh cốt thánh vật. Trong bốn mươi năm vương triều Đại Triệu, man tộc phương Tây muốn phá phong ấn của tiên sư, lấy linh cốt thánh vật để gọi chủ thú về, mong đạt được thần lực phi thường của chủ thú để lấy lại sinh cơ cho thảo nguyên, bèn chỉ huy quân binh chinh phạt phương Đông, dấy lên chiến hỏa. Giáo phái Vãng Sinh sai Cố Niệm Đồng ngăn cản chiến sự, lấy trộm thánh vật, định lấy phương pháp huyết tế để thao túng đại tướng quân man tộc là Kỳ Nỗ Cáp Nhĩ, toan mượn chủ thú A Ni Mao Ti hóa thành tà thần. Vì thế thủ lĩnh của Trấn Ma Ti là Trương Khiêm đã gọi đoàn kỵ binh tinh nhuệ của Trấn Ma Ti là Hoa Vô Song, Hoa Vô Thường, Tiêu Chấn, Ninh Vô Mưu tiến quân xuống phía Tây, hợp tác với lang kỵ sĩ của man tộc, phong ấn tử thủ Kim Cương Môn, dẹp loạn tứ phương, tiêu diệt yêu ma tám hướng.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hà Lam Đậu","avatar":""},{"name":"Vương Lạc Gia","avatar":""},{"name":"Quách Mộ Hàm","avatar":""},{"name":"Tây Linh Na Y","avatar":""},{"name":"Trình Đào","avatar":""},{"name":"Trương Xuân Trọng","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324323);
