INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-dao-mau-hong-va-dai-mien-vuong-phan-2', 'Anh Đào Màu Hồng Và Đại Miên Vương (Phần 2)', 'Why Women Cheat (Part 2)', 'https://phimimg.com/upload/vod/20240205-1/98d4a3a625349f38b680f3fcdf149376.jpg', 'https://phimimg.com/upload/vod/20240205-1/2935eace46b9456acde127c0511e9c19.jpg', '<p>Nam chính là vua của một đảo quốc nhỏ, anh từng bị nữ chính làm tổn thương sâu sắc. Nữ chính có một chiếc răng khểnh, lúc cười lên vô cùng quyến rũ. Sau khi nữ chính biến mất, nam chính trở nên cực kỳ thích ngủ vì không muốn nhớ gì đến nữ chính. Một cách tình cờ, cuối cùng anh lại lấy nữ chính, anh quyết định phải hành hạ cô gái bề ngoài đáng yêu nhưng lại có hành vi đáng ghét này cho thỏa.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Shag Deng","avatar":""},{"name":"Yao Xiao Xiao","avatar":""},{"name":"Xiong Su Yi","avatar":""},{"name":"Wang Kui Rong","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324323);
