INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-rua-than', 'Đảo Rùa Thần', 'The Turtle Island', 'https://phimimg.com/upload/vod/20240205-1/c1e5e2475939349e1bc180317029b104.jpg', 'https://phimimg.com/upload/vod/20240205-1/e6476fba4053686e9239d3ae17b97d88.jpg', '<p>Đảo Rùa Thần - The Turtle Island xoay quanh câu chuyện về chàng trai trẻ Vương Miễn, trên đường ra khơi tìm kiếm người huynh trưởng mất tích của mình. Thế nhưng trên chuyến đi tàu của anh bất ngờ gặp phải cơn bão lớn mạnh. Trong lúc phải đối diện với cái chết, đoàn tàu của anh đã được một vị tiên nữ bí ẩn cứu giúp và đưa lên một hòn đảo đễ lánh nạn. Tại đây, bọn họ cùng nhau tận hưởng rượu ngon, mỹ nhân, phong cảnh hữu tình, khiến họ quên đi mối nguy hiểm ấy. Tuy nhiên, các thành viên trong đoàn lại lần lượt biến mất và con thuyền cũng bị đánh cấp. Lúc này, những người còn sống đều bị kẹt lại trên hòn đảo.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Uông Trác Thành","avatar":""},{"name":"Lại Vũ Mông","avatar":""},{"name":"Tiêu Hướng Phi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324323);
