INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-ky-anh-hung-cuu-long-bi-thuoc', 'Thời Kỳ Anh Hùng Cửu Long Bí Thược', 'Age Of The Legend', 'https://phimimg.com/upload/vod/20240205-1/8ffc9578d03c79496146fe9f4e5c03c4.jpg', 'https://phimimg.com/upload/vod/20240205-1/f811faf3eb7f0f3f3404b633d027b10b.jpg', '<p>Cuối thời nhà Thanh, các nước mạnh nước ngoài nhìn chằm chằm vào Trung Quốc, không ngừng xâm lược. Triều đình nhà Thanh không có sức chống lại bởi bế quan tỏa cảng lâu năm. Giặc xâm lược Anh, Nhật Bản cấu kết với nhau, hòng xâm chiếm thành Quảng Châu. Mấy võ giả nhận lệnh trước nguy cơ. Vượt qua nhiều khó khăn nguy hiểm, họ đánh bại Ninja Nhật Bản và dùng công sự phòng ngự bí mật đánh lui chiến hạm nước Anh, cứu vớt thành Quảng Châu.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Adan","avatar":""},{"name":"Wu Yi Jia","avatar":""},{"name":"Wu Yi Jia","avatar":""},{"name":"Zhang Shuang Li","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324323);
