INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pacific-rim-vung-toi-phan-1', 'Pacific Rim: Vùng Tối (Phần 1)', 'Pacific Rim: The Black (Season 1)', 'https://phimimg.com/upload/vod/20240118-1/0172e589f047805d075543d69ba5122a.jpg', 'https://phimimg.com/upload/vod/20240118-1/211936541e798443566f46a3979162e6.jpg', '<p>Sau khi Kaiju tàn phá nước Úc, hai anh em điều khiển một Jaeger để tìm kiếm cha mẹ, đồng thời bắt gặp những sinh vật mới, các nhân vật bất hảo và đồng minh tình cờ.</p>', 'Hoàn Tất (7/7)', 7, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gideon Adlon","avatar":""},{"name":"Calum Worthy","avatar":""},{"name":"Erica Lindbeck","avatar":""},{"name":"Victoria Grace","avatar":""},{"name":"Alexandra MacDonald","avatar":""},{"name":"Jason Spisak","avatar":""},{"name":"Leilani Jones Wilmore","avatar":""},{"name":"Nolan North","avatar":""},{"name":"Andrew McPhee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324323);
