INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-tinh-yeu-day-song', 'Nơi Tình Yêu Dậy Sóng', 'Somewhere Our Love Begins', 'https://phimimg.com/upload/vod/20240118-1/b8caf77ca152aa0374162cfee29dbf8b.jpg', 'https://phimimg.com/upload/vod/20240118-1/56afe5eee3f8b57903a0b288b1da8985.jpg', '<p>Nơi Tình Yêu Dậy Sóng - Somewhere Our Love Begins xoay quanh mối tình của Panin và Arissara. Cả hai gặp nhau ở tỉnh Rayong khi cô giúp anh lúc bị bọn trộm tấn công. Panin bị ấn tượng bởi sự hào phóng của Arissara. Còn cô bị ấn tượng bởi sự chính trực của Panin. Khi họ trở về Bangkok, Arissara phát hiện ra rằng Panin đã lừa cô về hoàn cảnh thực sự của mình và Panin phát hiện ra rằng cô là người tình trong mộng của em trai mình, Yoh. Vì vậy, cả hai đều tức giận. Những hiểu lầm càng thêm lớn cùng với tình yêu ám ảnh của Yoh dành cho Arissara, còn Panin đấu tranh với ý tưởng nhường người mình yêu cho em trai.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Esther Supreeleela","avatar":""},{"name":"Jes Jespipat","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324323);
