INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('noi-tinh-yeu-day-song', 'Nơi Tình Yêu Dậy Sóng', 'Somewhere Our Love Begins', 'nơi tình yêu dậy sóng somewhere our love begins esther supreeleela jes jespipat ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-an-nha-thanh-ii', 'Kỳ Án Nhà Thanh II', 'A Pillow Case of Mystery II', 'https://phimimg.com/upload/vod/20240118-1/fa51105fabbc9a71d625b9e3fa95f135.jpg', 'https://phimimg.com/upload/vod/20240118-1/7fc0a113c7c56e14c2fce86906a4f0b3.jpg', '<p>Kỳ Án Nhà Thanh 2 thuộc thể loại cổ trang điều tra pha lẫn hài hước, với dàn diễn viên tên tuổi của TVB : Âu Dương Chấn Hoa, Tuyên Huyên, Đường Ninh, Lý Tư Kiệt. Vang danh vì biệt tài phá nhiều vụ án kỳ bí, nhưng vì quá đau lòng trước cái chết của vợ con trong một tai nạn, Thi Thế Luân đã từ bỏ quan trường, đưa gia quyến đi ngao du khắp nơi. Hoàn cảnh đưa đẩy, Thế Luân lại được bổ nhiệm làm tri huyện Tiên Du. Tại đây, anh cưới Ngô Quân Nhu làm thiếp. Duyên chồng vợ của họ xuất phát từ oán thù, nhưng lại trở thành lương duyên. Được sự giúp đỡ của tiên gối, Thế Luân đã phá được nhiều vụ án ly kỳ và điều tra làm rõ nguyên nhân cái chết của vị tiên gối, từ đó đưa ra ánh sáng kẻ chủ mưu đã gây ra vụ đắm thuyền thảm khốc khiến rất nhiều người vô tội chết oan, trong đó có cả vợ con của Thế Luân. Xuyên suốt trong quá trình đó là mối lương duyên đầy trắc trở của Thế Luân và Quân Nhu.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 17, 2021, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Tuyên Huyên","avatar":""},{"name":"Âu Dương Chấn Hoa","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324323);
