INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-vu-tru', 'Tội Ác Vũ Trụ', 'Cosmic Sin', 'https://phimimg.com/upload/vod/20240220-1/2a7bcabf46fdae091b15fd89dbb68fc7.jpg', 'https://phimimg.com/upload/vod/20240220-1/969e1feca254d48a5443087d39b94c9e.jpg', '<p>Seven Rogue Soldiers ra mắt một cuộc đình công phủ đầu chống lại một nền văn minh ngoài hành tinh mới được phát hiện với hy vọng chấm dứt một cuộc chiến liên ngôn trước khi nó bắt đầu.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Frank Grillo","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Brandon Thomas Lee","avatar":""},{"name":"Corey Large","avatar":""},{"name":"Perrey Reeves","avatar":""},{"name":"C.J. Perry","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Costas Mandylor","avatar":""},{"name":"Adelaide Kane","avatar":""},{"name":"Eva De Dominici","avatar":""},{"name":"Sarah May Sommers","avatar":""},{"name":"Trevor Gretzky","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324323);
