INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('in-the-wake', 'In The Wake', 'In The Wake', 'https://phimimg.com/upload/vod/20240219-1/d121d79dca9bde70284c9c27caad163f.jpg', 'https://phimimg.com/upload/vod/20240219-1/020064f5ece7d6e799fb648c0d033853.jpg', '<p>Những vụ giết người hàng loạt hỗn loạn diễn ra trong đó các nạn nhân bị trói và bỏ đói. Tone vừa được ra tù sau khi mãn hạn tù vì một tội danh khác, và anh ta lộ diện như một kẻ tình nghi nhưng thám tử Tomashiro không thể đưa ra bằng chứng kết luận.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takeru Satoh","avatar":""},{"name":"Hiroshi Abe","avatar":""},{"name":"Mitsuko Baisho","avatar":""},{"name":"Kaya Kiyohara","avatar":""},{"name":"Eita Nagayama","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324323);
