INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-stairs', 'The Stairs', 'The Stairs', 'https://phimimg.com/upload/vod/20240128-1/821a7fc9fba2640065fb911e5211d6d0.jpg', 'https://phimimg.com/upload/vod/20240128-1/fa0f32e9cc4873634cb58213320aaf27.jpg', '<p>Những gì bắt đầu như một cuộc phiêu lưu kéo dài một tuần với những người bạn nhanh chóng biến thành một cuộc chiến đáng sợ để sống sót trong cầu thang. Năm 1997, một cậu bé đang đi săn với ông nội (Schneider), khi anh vấp ngã một cầu thang bí ẩn sâu trong rừng. Sự biến mất tiếp theo khiến người dân địa phương bị cản trở đến số phận của cặp bướng bỉnh. Hai mươi năm sau, một nhóm những người đi bộ đã lên đường trên một con đường đầy tham vọng, sâu vào cùng một vùng hoang dã. Với mỗi bước ra khỏi nền văn minh, họ được kéo sâu hơn vào bẫy nguy hiểm của địa hình núi nơi họ vấp ngã trên cùng một bộ cầu thang đáng ngại.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324323);
