INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-lon-yeu', 'Truy Tìm Lợn Yêu', 'Pig', 'https://phimimg.com/upload/vod/20240128-1/fd1053ee6dd7989589d5c15b77923e1c.jpg', 'https://phimimg.com/upload/vod/20240128-1/ab32bf91c3dcf82fffde526544fdd454.jpg', '<p>Pig xoay quanh câu chuyện về người đàn ông thợ săn nấm sống một mình tại vùng Orgonian đầy hoang vắng. Lúc trước, anh có từng nuôi một con lợn cái nhưng hiện tại đã bị bọn người xấu bắt đi, vì thế anh quay trở lại Portland để có thể tìm kiếm được cô lợn yêu quý của mình.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Alex Wolff","avatar":""},{"name":"Cassandra Violet","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324323);
