INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-sinh-ky-uc', 'Hồi Sinh Ký Ức', 'Reminiscence', 'https://phimimg.com/upload/vod/20240128-1/62f7c93b8b04e6824ac87a1354dc92c5.jpg', 'https://phimimg.com/upload/vod/20240128-1/5a8053c650b20aa3062afad769dc8008.jpg', '<p>Nick Bannister, một cuộc điều tra tư nhân của tâm trí, điều hướng thế giới lôi cuốn của quá khứ khi cuộc sống của anh ta được thay đổi bởi khách hàng mới Mae. Một trường hợp đơn giản trở thành một nỗi ám ảnh sau khi cô biến mất và anh chiến đấu để tìm hiểu sự thật về cô.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324323);
