INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mouse-ke-san-nguoi-ban-dien-anh', 'Mouse Kẻ Săn Người (Bản Điện Ảnh)', 'Mouse (Movie Version)', 'https://phimimg.com/upload/vod/20240128-1/7cb3747edb23e4a32be2c732e35df1dc.jpg', 'https://phimimg.com/upload/vod/20240128-1/68aa671a5f4196bc263642afb25836b5.jpg', '<p>Phim kể về cảnh sát tuần tra đầy chính trực Jung Ba Reum (do Lee Seung Gi thủ vai) và cảnh sát hình sự Go Moo Chi (do Lee Hee Joon thủ vai) mất cha mẹ vì tên cuồng sát, sống để báo thù, sau khi gặp được \Kẻ săn mồi\ ác độc nhất thuộc 1% những bệnh nhân mắc bệnh tâm thần, vận mệnh của họ đã hoàn toàn thay đổi.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Seung Gi","avatar":""},{"name":"Lee Hee-jun","avatar":""},{"name":"Park Juhyun","avatar":""},{"name":"Kyong Soo Jin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324323);
