INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-zlatan', 'Tôi Là Zlatan', 'Jag är Zlatan', 'https://phimimg.com/upload/vod/20240128-1/f6f549637033b86a7690e4a45be4f9d3.jpg', 'https://phimimg.com/upload/vod/20240128-1/dddf727de3ad9cf7f68955d7d65a740d.jpg', '<p>Câu chuyện về tuổi mới lớn mô tả sự lớn lên của Zlatan Ibrahimovic ở một vùng ngoại ô thô sơ của Thụy Điển. Sinh ra từ những người nhập cư vùng Balkan, bóng đá là sự ra đời của Zlatan trong một môi trường khắc nghiệt, nơi tài năng vượt trội và sự tự lực của anh đã giúp anh vượt qua mọi khó khăn để lên đỉnh bóng đá quốc tế khi chơi cho các câu lạc bộ như Ajax Amsterdam, Juventus, Inter, Milan, Barcelona, Paris Saint- Germain và Manchester United.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Dominic Andersson Bajraktati","avatar":""},{"name":"Granit Rushiti","avatar":""},{"name":"Cedomir Glisovic","avatar":""},{"name":"Merima Dizdarevic","avatar":""},{"name":"Linda Haziri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324323);
