INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-vo-ranh-gioi-cuu-lay-hanh-tinh-cua-chung-ta', 'Phá Vỡ Ranh Giới: Cứu Lấy Hành Tinh Của Chúng Ta', 'Breaking Boundaries: The Science Of Our Planet', 'https://phimimg.com/upload/vod/20240127-1/e714a0445b8429c2a9628fc57716342a.jpg', 'https://phimimg.com/upload/vod/20240127-1/0df94821e4a9a59753dd917769abb36f.jpg', '<p>David Attenborough và nhà khoa học Johan Rockström phân tích sự sụp đổ của đa dạng sinh học trên Trái Đất và cuộc khủng hoảng này vẫn có thể được ngăn chặn như thế nào.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Attenborough","avatar":""},{"name":"Johan Rockström","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324323);
