INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-con-sat-thu', 'Mẹ Con Sát Thủ', 'Gunpowder Milkshake', 'https://phimimg.com/upload/vod/20240127-1/41c7d05c1e405da2c787d5616b1f56bc.jpg', 'https://phimimg.com/upload/vod/20240127-1/9cd138360a73da7dd0b7f1775031b237.jpg', '<p>Trong cuộc sống hỗn loạn của cô như một kẻ ám sát chuyên nghiệp, Scarlet bị buộc phải bỏ cuộc con gái Sam và tiếp tục chạy. Nhiều năm sau, bất chấp sự ôn hòa, Sam cũng đã phát triển thành một người phụ nữ hit máu lạnh. Sau một nhiệm vụ cổ phần cao quay ra khỏi tầm kiểm soát, hãy đặt một cô gái 8 tuổi vô tội vào giữa chiến tranh băng đảng mà cô ấy đã giải phóng, Sam không có lựa chọn nào khác ngoài việc khiến Rogue. Điều này cuối cùng dẫn cô trở về với mẹ và cựu Sidewomen của cô, tất cả đều tham gia các lực lượng trong một cuộc chiến khơi dậy với những người lấy tất cả mọi thứ từ họ.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324323);
