INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kalina-duc-vong-trong-toi', 'Kalina: Dục Vọng Trong Tôi', 'Autumn Girl', 'https://phimimg.com/upload/vod/20240126-1/50bc0a063c613da7349581d10d22d57d.jpg', 'https://phimimg.com/upload/vod/20240126-1/e000f50f28c893aeb4a0ab2319ce44ca.jpg', '<p>Những năm 1960 ở Ba Lan, nghệ sĩ biểu diễn Kalina Jędrusik đang ở đỉnh cao danh vọng. Cô từ chối một vị quan chức và hắn đe dọa hủy hoại sự nghiệp của cô.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Maria Dębska","avatar":""},{"name":"Leszek Lichota","avatar":""},{"name":"Krzysztof Zalewski","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324323);
