INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-yeu-the', 'Kẻ Yếu Thế', 'American Underdog', 'https://phimimg.com/upload/vod/20240125-1/49e5d89f96f132d56f6bc154590e5255.jpg', 'https://phimimg.com/upload/vod/20240125-1/2a8e80973bd40a1a723f99303c065d86.jpg', '<p>Câu chuyện có thật đầy cảm hứng về Kurt Warner, người đã vượt qua nhiều năm thử thách và thất bại để trở thành NFL MVP hai lần, nhà vô địch Super Bowl và tiền vệ của Hall of Fame. Chỉ khi những ước mơ của anh ấy dường như đều nằm ngoài tầm với, nó chỉ có thể có được sự ủng hộ của vợ anh ấy, Brenda, và sự động viên của fa anh ấy mily, huấn luyện viên và đồng đội mà Warner kiên trì và tìm thấy sức mạnh để cho cả thế giới thấy rằng anh ấy đã là nhà vô địch.</p>', 'Full', 1, 'single', 'completed', 17, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zachary Levi","avatar":""},{"name":"Anna Paquin","avatar":""},{"name":"Hayden Zaller","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '[]', 1784690324323);
