INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-co-the-tro-ve-luc-dau-giong-nhu-nguoi-yeu', 'Nếu Có Thể Trở Về Lúc Đầu: Giống Như Người Yêu', 'If At First: Almost Lover', 'https://phimimg.com/upload/vod/20240124-1/53641c6e608c61b3264c8a50a984e476.jpg', 'https://phimimg.com/upload/vod/20240124-1/c0b3c1fcd5f910e8a4de4cf8d7a6f08a.jpg', '<p>Diệu Tổ lấy hết can đảm để tỏ tình với nữ thần khuôn viên trường Tĩnh Tĩnh, người đã giành được sự ưu ái của cô. Chỉ có khoảng thời gian hạnh phúc ngắn ngủi, không lâu sau lại Tĩnh Tĩnh quyết định đến Bắc Kinh phát triển và tách khỏi Diệu Tổ. Diệu Tổ không thể chịu đựng được chia tay và một mình đi về phía bắc để theo đuổi tình yêu, nhưng không ngờ lại gặp được cô gái yêu say đắm Beth, và cô gái Lê Khai trưởng thành và xinh đẹp. Với quan niệm mới về tình yêu và trải nghiệm mới về tình yêu, có lẽ tình yêu sẽ được mở theo những cách khác.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yang Xu Wen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324323);
