INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-lan-doa-loi-nguyen-duyen-khoi', 'Đồ Lan Đóa: Lời Nguyền Duyên Khởi', 'The Curse Of Turandot', 'https://phimimg.com/upload/vod/20240124-1/ca8d44a24114b08ca619925279bc0cdb.jpg', 'https://phimimg.com/upload/vod/20240124-1/0e4964a1fd225dd807cffd94633e2bf1.jpg', '<p>Cốt truyện kể về Công chúa Turandot, người bị nguyền rủa bởi một sức mạnh bí ẩn phát ra từ ba chiếc vòng tay Mazovian được tặng cho cô như một món quà sinh nhật. Những tác động tiêu diệt sự sống của những chiếc vòng này khiến công chúa trở nên độc ác, và dần dần cô mất nhân tính.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Guan Xiaotong","avatar":""},{"name":"Dylan Sprouse","avatar":""},{"name":"Hu Jun","avatar":""},{"name":"Jiang Wen","avatar":""},{"name":"Collin Chou","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324323);
