INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('aileen-wuornos-american-boogeywoman', 'Aileen Wuornos: American Boogeywoman', 'Aileen Wuornos: American Boogeywoman', 'https://phimimg.com/upload/vod/20240122-1/4b98fbd19049b9fca290826327786ea8.jpg', 'https://phimimg.com/upload/vod/20240122-1/aacce17e06e46b58fa5cdc712521f234.jpg', '<p>Dựa trên cuộc đời đầu tiên của Aileen Wuornos, kẻ giết người hàng đầu tiên nổi tiếng nhất của Mỹ, vào năm 1976, một đứa trẻ Aileen đến Florida đang tìm kiếm một cuộc sống mới sẽ giúp cô thoát khỏi quá khứ bi thảm của mình, kết hôn với chủ tịch câu lạc bộ du thuyền giàu có và có cơ hội bắt đầu lại Là một phần của xã hội cao cấp của Florida. Nhưng bị dằn vặt bởi những con quỷ bên trong, cô ấy đầu hàng những xung động sát thủ của mình và tàn phá trong cộng đồng bờ biển yên bình của Deland, Florida.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324323);
