INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-vuc-1', 'Linh Vực 1', 'The World Of Fantasy 1', 'https://phimimg.com/upload/vod/20240122-1/290bf146bcc211e0ffb866d3719cea30.jpg', 'https://phimimg.com/upload/vod/20240122-1/864fb01bdcf8e749997c4d8b427d5f4b.jpg', '<p>Tại một vùng đất được gọi là Linh Vực, thiếu niên Tần Liệt của trấn Lăng Gia cùng với Lăng Ngữ Thi và Cao Vũ được lệnh phải tham gia vào trận chiến trừng phạt thú thực hồn của Huyền Thiên Minh. Tần Liệt không ngờ rằng từ đây bản thân bị cuốn vào một âm mưu vô cùng to lớn, cậu phải bảo vệ bạn bè, giải cứu người mình yêu và che dấu sức mạnh có trong dòng máu vừa thức tỉnh của mình</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xia Hou Luo Feng","avatar":""},{"name":"Teng Xin","avatar":""},{"name":"Huang Zhen Ji","avatar":""},{"name":"Bao Mu Zhong Yang","avatar":""},{"name":"Zhang Sheng","avatar":""},{"name":"可爱小狼","avatar":""},{"name":"huangbin","avatar":""},{"name":"Zhou Jian","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324323);
