INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('black-as-night', 'Black As Night', 'Black As Night', 'https://phimimg.com/upload/vod/20240205-1/f778b93e8a3a4fde555954f360a8b187.jpg', 'https://phimimg.com/upload/vod/20240205-1/6845183c470b9e04e5d74336f2f87a84.jpg', '<p>Một cô gái tuổi teen với những vấn đề về lòng tự trọng tìm thấy sự tự tin về cách không có khả năng nhất, bằng cách dành mùa hè của mình để chiến đấu với Ma cà rồng mà con mồi cho người mới rời khỏi New Orleans với sự giúp đỡ của người bạn thân nhất của cô, chàng trai mà cô ấy luôn luôn chọc tức, và một cô gái giàu có.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324323);
