INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-titan-vi-khach-bat-ngo', 'Đại Chiến Titan: Vị Khách Bất Ngờ', 'Attack On Titan: Totsuzen No Raihousha, Attack On Titan: The Sudden Visitor', 'https://phimimg.com/upload/vod/20240205-1/02a6872551fb2fbea93a7cd3f0fffee0.jpg', 'https://phimimg.com/upload/vod/20240205-1/5060a0e4f3ee1d9b5a826b6fb5933b2f.jpg', '<p>Jean Kirstein sẽ làm mọi cách để thoát khỏi cuộc sống ở nhà buồn tẻ và người mẹ quá độc đoán. Sau khi nhập ngũ, mục tiêu cuối cùng của anh là gia nhập Đội Cảnh vệ và sống trong yên bình và sang trọng. Tuy nhiên, trong thời gian làm việc trong khóa huấn luyện thứ 104, mọi thứ không bao giờ thực sự diễn ra theo cách mà Jean mong muốn. Cuối cùng, vinh quang thì không đạt được và những lời đùa cợt của đồng đội thì trở nên quá mức chịu đựng. Jean đã thách thức đồng đội Sasha Blouse một cuộc chiến để xác định xem ai trong số họ là mạnh nhất - nhưng ai sẽ là người đứng đầu?</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324323);
