INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-an-bat-de', 'Vụ Án Bắt Dê', 'Get The Goat', 'https://phimimg.com/upload/vod/20240104-1/0717cd5a602058489686b3cd9e2bad00.jpg', 'https://phimimg.com/upload/vod/20240104-1/f93c3d59353dd640b2d89b8aff8f7c46.jpg', '<p>Hai cảnh sát xui xẻo nhận ra họ ngập trong rắc rối khi vô tình chạm trán với bọn tội phạm nguy hiểm trong lúc tìm kiếm Celestina – linh vật dê được yêu mến.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Matheus Nachtergaele","avatar":""},{"name":"Edmilson Filho","avatar":""},{"name":"Letícia Lima","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324323);
