INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-hoc-uy-long-moi', 'Trường Học Uy Long Mới', 'New Fight Back To School', 'https://phimimg.com/upload/vod/20240104-1/31caf1fa2bd63b2cc5ed37afe2e06b55.jpg', 'https://phimimg.com/upload/vod/20240104-1/612fc834f2d5d98eb2b29342adaa8b44.jpg', '<p>Hoàng Tiểu Quý, nhân chứng của một vụ án trọng tài tại một thành phố Đông Nam Á, bất ngờ lẩn trốn. Trương Hạo, một cảnh sát đặc nhiệm nằm vùng trong một ngôi trường quý tốc quốc tế, thử tìm Hoàng Tiểu Quý qua tiếp cận Hoàng Anh, con gái của Hoàng Tiểu Quý. Bên cạnh đó, tập đoàn tội phạm sai sát thủ chờ thời cơ bắt cóc Hoàng Anh. Tên phản bội giữa cảnh sát, sát thủ bên ngoài và sự phản kháng của Hoàng Anh đều khiếu Trương Hạo rơi vào cảnh khó. Đại chiến đầy nguy cơ sắp bắt đầu, Trương Hạo sẽ ứng đối như thế nào?</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Hao","avatar":""},{"name":"Tong Fei","avatar":""},{"name":"Kar-Ying Law","avatar":""},{"name":"Ai Fu Lu Si","avatar":""},{"name":"Huan He","avatar":""},{"name":"Jatfei Wong","avatar":""},{"name":"Gabriel Wong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324323);
