INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huynh-de-than-men-cua-ta', 'Huynh Đệ Thân Mến Của Ta', 'My Dear Brothers', 'https://phimimg.com/upload/vod/20240116-1/42ba9c9c9d05d5ecff6c8191faae8898.jpg', 'https://phimimg.com/upload/vod/20240116-1/364168a11fef2f0f62bbe23a407978fd.jpg', '<p>Bộ phim kể về thiếu nữ thiên tài thông minh đáng yêu Thời Hạ (Ngô Thiên Doanh đóng), vì tìm anh trai thất lạc mà ngoài ý muốn đi tới thế giới tiên hiệp lạ lẫm, cùng anh trai ma tôn cuồng em gái Thời Đông (Đại Vân Phàm đóng) và Thái Thượng Lão Tổ Hậu Trì của phái Ngọc Diệp (Triệu Anh Bác đóng) với những chuyện ở chung hài hước ấm áp thường ngày, từ đó mở ra câu chuyện hài hước hai anh trai cùng “bảo vệ” em gái.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhao Ying Bo","avatar":""},{"name":"yunfan dai","avatar":""},{"name":"Ngô Thiên Doanh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324323);
