INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-khoi-lac-duong', 'Phong Khởi Lạc Dương', 'Luoyang', 'https://phimimg.com/upload/vod/20240116-1/efd31533ae5f582c4f282c8a815d9cce.jpg', 'https://phimimg.com/upload/vod/20240116-1/92b8ec718ce5e4758822ec55e6ad9c70.jpg', '<p>Bộ phim lấy bối cảnh thời Võ Tắc Thiên, năm Trường An thứ 4 tại Lạc Dương. Công trình xây dựng Thiên Đường sắp hoàn thành, Lạc Dương sắp tổ chức đại điển tế thiên. Võ Tắc Thiên lại nhận được tin có người muốn lên kinh mật báo nhưng nửa đường suýt nữa bị chặn giết. Võ Hoàng tức giận, giao trọng trách phải tra rõ chuyện này. Bất lương Phó soái, Cao Bỉnh Chúc (Hoàng Hiên thủ vai) thường xuyên trà trộn vào tầng lớp thấp kém ở Lạc Dương, không may trở thành nghi phạm của vụ án truy sát này.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hoàng Hiên","avatar":""},{"name":"Tống Thiến","avatar":""},{"name":"Vương Nhất Bác","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324323);
