INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-hiep-si-nguoi-ke-vi-anh-hung', 'Bảy Hiệp Sĩ - Người Kế Vị Anh Hùng', 'Seven Knights Revolution: The Hero''s Successor, Seven Knights Revolution -Eiyuu No Keishousha', 'https://phimimg.com/upload/vod/20240116-1/800a9481d7613d094cfe8d11eac23443.jpg', 'https://phimimg.com/upload/vod/20240116-1/a59af2cea932ef2db86ebe022fa980c6.jpg', '<p>Mang trong mình sức mạnh của anh hùng bảo vệ thế giới khỏi sự hủy diệt, Faria - một cô gái luôn đứng đầu trong số những người được mệnh danh là người kế thừa, , đã cứu cậu bé Monet. Trong cuộc chiến khốc liệt, sức mạnh anh hùng không một kẻ nào biết đã trỗi dậy trong thân thể của Nemo.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324323);
