INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-titan-oad', 'Đại Chiến Titan OAD', 'Attack On Titan OAD', 'https://phimimg.com/upload/vod/20240116-1/b43c380e0c5e25c5b5bf47e3d24f6cb2.jpg', 'https://phimimg.com/upload/vod/20240116-1/48ca10be71f624927977eb3fe248e105.jpg', '<p>Câu chuyện xoay quanh Eren Yeager và những người bạn của anh ấy. Sự tồn tại của họ có một bước ngoặt đáng kể khi bức tường thành của quê hương họ bị tiêu diệt bởi Titan. Eren và bạn bè của mình tham gia Tiểu đoàn thợ săn. Đó là một đội gồm những người lính được huấn luyện chiến đấu chống lại các Titan đang trả thù.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324323);
