INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-re-cat-hung-cao-chieu', 'Ở Rể: Cát Hưng Cao Chiếu', 'My Heroic Husband', 'https://phimimg.com/upload/vod/20240104-1/aae0d132e9c558a27e2a49e4f7e3f1ed.jpg', 'https://phimimg.com/upload/vod/20240104-1/c63624225c09e01c2ef96a3ef09f68fa.jpg', '<p>Ở Rể: Cát Hưng Cao Chiếu là phần phim xoay quanh thiếu gia nhị phòng của gia đình buôn vải họ Tô. Từng muốn tranh giành vị trí kế thừa gia tộc họ Tô, nhưng anh chàng lại bị Ninh Nghị đánh bại trong cuộc đua cạnh tranh với em gái Tô Đàn Nhi. Trong một lần tình cờ, anh chàng đã nghe được sự thật từ người hầu, hóa ra trong mắt mọi người anh chỉ là một kẻ bù nhìn của tiệm vải họ Tô. Là người có lòng tự trọng nên khi bị sỉ nhục như vậy, Văn Hưng quyết định rời khỏi gia đình để tới Phúc Nguyên lập nghiệp nhằm chứng tỏ năng lực và thoát khỏi cái bóng của Ninh Nghị. Cuộc phiêu lưu mới của anh chàng bắt đầu từ đây.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Guan Lin","avatar":""},{"name":"Wang Zhi Xuan","avatar":""},{"name":"Yue Yang","avatar":""},{"name":"Han Cheng Yu","avatar":""},{"name":"Xiangyu Dai","avatar":""},{"name":"Hai Bo","avatar":""},{"name":"Guanying Chen","avatar":""},{"name":"Zhang Zi Lin","avatar":""},{"name":"Cai Gang","avatar":""},{"name":"Smile","avatar":""},{"name":"Cao Xi Yue","avatar":""},{"name":"Zhang Jing Tong","avatar":""},{"name":"Yao Yi Qi","avatar":""},{"name":"Ma Xiao Qian","avatar":""},{"name":"Shen Hao","avatar":""},{"name":"Hai Bo","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324323);
