INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-phai-lam-gi-do', 'Chúng Ta Phải Làm Gì Đó', 'We Need Do Some Thing', 'https://phimimg.com/upload/vod/20240103-1/89465a6c2d92deb4416a8734117fc192.jpg', 'https://phimimg.com/upload/vod/20240103-1/ba308c90c7699614c77e22a0fc4ba4dd.jpg', '<p>Chúng Ta Phải Làm Gì Đó - We Need to Do Something (2021) là phim kinh dị, tâm lý có thời lượng 97 phút do Sean King OGrady làm đạo diễn. Một cơn bão xuất hiện, Melissa cùng gia đình phải tìm nơi cứ trú và bị mắc kẹt. Thời gian qua đi, mãi họ không thấy có dấu hiệu được giải cứu. Ngày nọ Melissa cùng với Amy có thể đã liên quan tới nỗi kinh hoàng đe dọa sẽ chia cắt gia đình cô và &nbsp;toàn bộ thế giới.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sierra McCormick","avatar":""},{"name":"Vinessa Shaw","avatar":""},{"name":"Pat Healy","avatar":""},{"name":"Lisette Alexis John","avatar":""},{"name":"James Cronin Ozzy","avatar":""},{"name":"Osbourne Logan","avatar":""},{"name":"Kearney Dan","avatar":""},{"name":"John Miller","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324323);
