INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-yakuza', 'Công Chúa Yakuza', 'Yakuza Princess', 'https://phimimg.com/upload/vod/20240103-1/41a1e46336dcfacef1df05d7ad0f6815.jpg', 'https://phimimg.com/upload/vod/20240103-1/561aed6874db09032ac77a67e1137268.jpg', '<p>Công Chúa Yakuza kể về người thừa kế của một nửa tổ chức tội phạm Yakuza đã tạo dựng một liên minh không dễ chịu với một người lạ bị mất trí nhớ, người tin rằng một thanh kiếm cổ sẽ gắn kết hai số phận của họ. Cô phải mở cuộc chiến chống lại một nửa còn lại của tổ chức muốn cô chết.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"MASUMI","avatar":""},{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Tsuyoshi Ihara","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324323);
