INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguy-co-tien-sinh', 'Nguy Cơ Tiên Sinh', 'Game Changer', 'https://phimimg.com/upload/vod/20240112-1/477b563b289fd5cabca0d5a8ac9e3113.jpg', 'https://phimimg.com/upload/vod/20240112-1/d8e3f289e4bb973cce749a8c71e637ee.jpg', '<p>Lâm Trung Thạc vốn là một phóng viên mảng giải trí nên rất am hiểu về con người và đặc thù của ngành. Sau khi chuyển sang làm ở một công ty truyền thông, anh chuyên xử lý các vụ khó và giảm thiểu hậu quả đến mức thấp nhất, dần dần có được vị thế trong ngành. Nhưng rồi một sự cố bất ngờ xảy ra buộc Thạc phải rời khỏi ngành, tự trách bản thân và anh bắt đầu sửa chữa sai lầm của mình.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 7, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Đàm Trác","avatar":""},{"name":"Huỳnh Hiểu Minh","avatar":""},{"name":"Thái Văn Tịnh","avatar":""},{"name":"Lâm Hựu Uy","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324323);
