INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-long-thanh-trai', 'Cửu Long Thành Trại', 'Kowloon Walled City', 'https://phimimg.com/upload/vod/20240108-1/ca53b66d935ab48d58960dd155e04817.jpg', 'https://phimimg.com/upload/vod/20240108-1/30cb79b661634cfd3c60f7d7a4841c01.jpg', '<p>A Năng từng là bá chủ đường phố ở vùng Đông Bắc, để bản thân trở nên xuất sắc hơn, a Năng đến Cửu Long Thành Trại của Hong Kong để bắt đầu lại. Nhưng không ngờ, anh lại dính vào một âm mưu và cuộc hỗn chiến giữa các thế lực ngầm. Cuối cùng, để bảo vệ người bạn tốt bị thế lực đó truy bắt, A Năng đã lấy lại chính mình, dũng cảm bước lên phía trước, cùng cư dân thành trại chiến đấu chống lại các thế lực và thề sẽ bảo vệ bạn mình đến chết.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"釋彥能","avatar":""},{"name":"Yu Lang","avatar":""},{"name":"Peter  lv","avatar":""},{"name":"孫子鈞","avatar":""},{"name":"楊曉波","avatar":""},{"name":"楊曉波","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324323);
