INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gui-den-ngoi-sao-cua-anh', 'Gửi Đến Ngôi Sao Của Anh', 'To My Star', 'https://phimimg.com/upload/vod/20240104-1/7c667fb3d4545feb42e95a3f4d5086b8.jpg', 'https://phimimg.com/upload/vod/20240104-1/632d19e8ae390da95b11df73a4eb7b26.jpg', '<p>Bộ phim là câu chuyện tình yêu ngọt ngào của anh chàng diễn viên Kang Seo Joon (Son Woo Huyn đóng) luôn tìm cách thoát khỏi quy luật cuộc sống và đầu bếp Han Ji Woo (Kim Kang Min đóng) chỉ muốn có một cuộc sống an ổn bình thường. Từ lúc được debut đến nay, anh chàng diễn viên tài mạo song toàn Kang Seo Joon chưa biết mùi flop là gì, như thể anh chính là một ngôi sao lấp lánh trên trời. Nhưng anh lại bất ngờ tiến vào thế giới của Han Ji Woo, cũng trải nghiệm được sự biến hóa kỳ diệu trong tình cảm. Chàng đầu bếp ấm áp Han Ji Woo luôn kiên nhẫn chậm rãi hướng đến mục tiêu của mình, thế mà lại rơi vào vô số rắc rối rối bời chỉ vì sự xuất hiện của Kang Seo Joon.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Son Woo-Hyun","avatar":""},{"name":"Kim KangMin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324323);
