INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-nghi-tinh-yeu', 'Chặng Nghỉ Tình Yêu', 'Resort To Love', 'https://phimimg.com/upload/vod/20240104-1/6c05f3b878c08422a46673385dc7995b.jpg', 'https://phimimg.com/upload/vod/20240104-1/3ee153377560cff19f4b48040346ba46.jpg', '<p>Lao đao vì thất tình và sự nghiệp lao dốc, cô ca sĩ nhận biểu diễn ở một khu resort hạng sang trên đảo – nơi tình cờ là địa điểm đám cưới vị hôn phu cũ của cô.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christina Milian","avatar":""},{"name":"Jay Pharoah","avatar":""},{"name":"Sinqua Walls","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324323);
