INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-bep-ha-pham', 'Thần Bếp Hạ Phàm', 'The King Of Cookery', 'https://phimimg.com/upload/vod/20231231-1/d0cf367feabd5c29fb8801059fb0ae74.jpg', 'https://phimimg.com/upload/vod/20231231-1/9ad6d798093c550a842a9e7e6c5dad65.jpg', '<p>Thiên giới Đường Mặc bị thiên thần đuổi xuống trần gian lịch luyện, trở thành đầu bếp của quầy bán quà vặt. Một hôm, một ông lão thần bí mời anh ấy tham gia “Cuộc thi Vua đầu bếp hàng đầu” và hứa hẹn với anh ấy có thể giành được tiền thưởng 5 tỷ tệ. Trong quá trình dự thi, Đường Mặc nhờ vào tài năng nấu ăn mà được mọi người chú ý, nhưng cũng dẫn tới họa sát thân đến từ kình địch mang bối cảnh xã hội đen cho mình. Theo sự hướng dẫn của ông lão thần bí, Đường Mặc lánh đi làng Ngũ Vị, một nơi cao thủ ở ẩn về các trường phái ẩm thực khác nhau tụ hợp. Đường Mặc vốn muốn rút lui, bỏ đi, lại được ông lão thần bí và sáu vị cao thủ ở ẩn giúp đỡ mà quyết định bất chấp mọi thứ, tiến hành thi đấu long trời lở đất, xưa nay chưa từng có với kình địch…</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bàng Vũ Nùng","avatar":""},{"name":"Tô Kiện Thuyên","avatar":""},{"name":"Nhạc Đông Phong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324323);
