INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-gian-phong-bao', 'Vô Gian Phong Bão', 'Infernal Storm', 'https://phimimg.com/upload/vod/20240128-1/444a754cd6aa4a8d16cc526f416c88b8.jpg', 'https://phimimg.com/upload/vod/20240128-1/9c758f25cafe02b40d6ca6deec4e2c96.jpg', '<p>Cảnh sát nằm vùng Sơn Ca của tổ trọng án Tây Cửu Long gửi tin cho chỉ huy cấp cao Duy Sir, kẻ buôn ma túy đáng gờm nhất Hồng Kông Kim tiên sinh sẽ đích thân giao dịch chuyến ma túy lớn nhất trong năm, đồng thời liên quan tới số tiền những hai mươi triệu đô. Tuy nhân, lần này lại là cái bẫy điệu hổ ly sơn để tìm ra cảnh sát nằm vùng của đám buôn ma túy. Sơn Ca bất cẩn bị bạo lộ thân phận. Cả tập đoàn dồn lực đuổi giết, thân phận nằm vùng cũng đột ngột bị mất, Sơn Ca bỗng chốc rơi vào vòng xoáy tranh chấp của hai bên hắc bạch đạo. Sơn Ca phải chứng minh được bản thân trong sạch trong thời gian đã định, đồng thời phá hoại âm mưu của trùm ma túy Kim tiên sinh...</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Tiểu Xuân","avatar":""},{"name":"Thang Trấn Nghiệp","avatar":""},{"name":"Trần Bảo Nguyên","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324324);
