INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bingo-hell', 'Bingo Hell', 'Bingo Hell', 'https://phimimg.com/upload/vod/20240128-1/a8150f5d52f4822c377f925ba0566212.jpg', 'https://phimimg.com/upload/vod/20240128-1/1155d800c7a20ab5482e3f7ed618e51d.jpg', '<p>Trong Barrio của Oak Springs sống một nhóm người bạn già mạnh mẽ và bướng bỉnh, những người không chịu được gentrified. Thủ lĩnh của họ, Lupita, giữ họ cùng nhau như một cộng đồng, một gia đình. Nhưng họ ít biết, Hội trường Bingo yêu dấu của họ sắp được bán cho một lực lượng mạnh hơn nhiều so với tiền.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324324);
