INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhi-long-ho-dem-kinh-hoang', 'Nhị Long Hồ: Đêm Kinh Hoàng', 'Er Long Hu Wang Shi Jing Hun Ye', 'https://phimimg.com/upload/vod/20240102-1/0f7493f5bd1fe0f21041f62091a4328b.jpg', 'https://phimimg.com/upload/vod/20240102-1/30ea3e40b20b0adf6e39a32f0a34c61b.jpg', '<p>Câu chuyện trong phim Nhị Long Hồ: Đêm Kinh Hoàng bắt đầu từ một đoàn nghệ thuật Xiaolihua Erren Zhuan, họ đã nhận được lời mời ẩn danh đến biểu diễn ở làng Erlonghu. Trên đường đi, thành viên Liu Dezi (Zhang Hao) ghen tuông đến mức Liu Dezi (Zhang Hao) rất tức giận và thậm chí còn được sắp xếp để sống một mình. Không ngờ Liu Dezi sống trong một ngôi nhà bùn, những chuyện kỳ lạ lần lượt xảy ra. Sau vài lần dò hỏi chủ nhân của ngôi nhà, ông lão họ Giang đã chết một cách thê thảm cách đây không lâu, mọi người một hồi hoảng sợ, và mở ra những câu chuyện dở khóc dở cười với anh</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Hạo","avatar":""},{"name":"Sài Bảo Ngọc","avatar":""},{"name":"Diêm Tinh Di","avatar":""},{"name":"Vương Khuê Vinh","avatar":""},{"name":"Đỗ Nguyên","avatar":""},{"name":"Lý Minh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324324);
