INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('leave-no-traces', 'Leave No Traces', 'Leave No Traces', 'https://phimimg.com/upload/vod/20240102-1/90c8ebdd67c24039ecd4a4eff7b9fd37.jpg', 'https://phimimg.com/upload/vod/20240102-1/89730305c3050e00a05c6c98de5e6ef3.jpg', '<p>Bộ phim kinh dị chính trị dựa trên một câu chuyện có thật về một sinh viên trẻ bị cảnh sát đánh chết vào những năm 1980 của Cộng sản Ba Lan.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Tomasz Zietek","avatar":""},{"name":"Sandra Korzeniak","avatar":""},{"name":"Jacek Braciak","avatar":""},{"name":"Agnieszka Grochowska","avatar":""},{"name":"Robert Więckiewicz","avatar":""},{"name":"Tomasz Kot","avatar":""},{"name":"Aleksandra Konieczna","avatar":""},{"name":"Sebastian Pawlak","avatar":""},{"name":"Andrzej Chyra","avatar":""},{"name":"Michał Żurawski","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324324);
