INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-tuyen-nguy-co-no-bom', 'Phòng Tuyến Nguy Cơ Nổ Bom', 'Defense:Bomb Crisis', 'https://phimimg.com/upload/vod/20240102-1/e53a81b3faa5bfb04607f3fd3721d661.jpg', 'https://phimimg.com/upload/vod/20240102-1/33da04c72e7ec2c33bcaff36d8734267.jpg', '<p>Sắp hòa đàm, cảnh sát gìn giữ hòa bình lại phát hiện có phần tử khủng bố hòng phá hoại hòa đàm qua đặt bom. Bởi vậy, cảnh sát gìn giữ hòa bình Trung Quốc Bồ Phàm gia nhập vào nhóm chung tháo dỡ quả bom để bảo vệ hòa đàm. Ban đầu nhóm chung nghi ngờ chuyên gia tháo dỡ quả bom bản xứ Rampa tức là hung thủ. Nhưng Bồ Phàm lại nhận được thư mật báo liên quan đến địa điểm đặt bom do Rampa gửi cho mà cảm thấy hết sức nghi hoặc. Cuối cùng, Bồ Phàm bắt được Rampa, mới biết hóa ra Rampa chẳng phải là kẻ gây vụ án khủng bố này mà còn hai bàn tay đen đằng sau sự kiện đặt bom...</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Di Yu Jia","avatar":""},{"name":"Mirrre","avatar":""},{"name":"Fei Er Duo Si","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324324);
