INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-duong-phu-giang-son-co-nhan', 'Thượng Dương Phú / Giang Sơn Cố Nhân', 'The Rebel Princess', 'https://phimimg.com/upload/vod/20240112-1/97ba468d8520a7a196fd56765d557679.jpg', 'https://phimimg.com/upload/vod/20240112-1/7c1e79b27f91914e85bf9163b0fd0c75.jpg', '<p>Thượng Dương Phú (Giang Sơn Cố Nhân) được chuyển thể từ tiểu thuyết Đế Vương Nghiệp của Mị Ngữ Giả. Phim kể về Thượng Dương Quận chúa Vương Huyên (Chương Tử Di) xuất thân danh gia vọng tộc, mang huyết mạch hoàng gia cao quý. Nàng có người thương yêu là thanh mai trúc mã, được người người ngưỡng mộ. Vì sống trong loạn thế mà thân bất do kỷ, không thể sống theo ý mình. Tiêu Kỳ (Chu Nhất Vi) xuất thân bần hàn, dùng nghiệp nhà binh đánh trận giết địch, từng bước đoạt quyền đoạt thế trở thành Dự Chương Vương quyền khuynh thiên hạ. Tiêu Kỳ lấy Vương Huyên chỉ là một cuộc hôn nhân chính trị, không tình yêu. Nhưng vận mệnh trớ trêu, từ người dưng hóa người thương, gặp nhau tuy muộn nhưng chính số mệnh đã định sẵn thuộc về nhau. Sau một lần binh biến, Vương Huyên nắm tay Tiêu Kỳ dựng nghiệp Đế vương. Trước mắt nàng là đại nghĩa diệt thân, là nguy cơ trùng trùng. Đến cuối cùng, Vương Huyên bước đi trên con đường lập quốc, đỉnh cao vương quyền hay đợi chờ nàng là đầy rẫy kiếp nạn không thể quay đầu, vạn kiếp bất phục.</p>', 'Hoàn Tất (68/68)', 68, 'series', 'completed', 14, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Chu Nhất Vi","avatar":""},{"name":"Chương Tử Di","avatar":""},{"name":"Huệ Ánh Hồng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324324);
