INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-bang-kinh-hoang-94', 'Đoạn Băng Kinh Hoàng 94', 'V/H/S/94', 'https://phimimg.com/upload/vod/20231230-1/675196c296eed0482bf9b113a53c8f17.jpg', 'https://phimimg.com/upload/vod/20231230-1/255be93ba6b9064af796aeb059149eff.jpg', '<p>Một người phụ nữ mặc áo trắng hít hơi từ một chất màu trắng đục trên tay. Sau đó, cùng một người phụ nữ, với đôi mắt khoét sâu, đếm ngược từ mười bằng một giọng y tĩnh khi một người phụ nữ khác đi qua phía sau cô. Một đội SWAT - bao gồm Slater, Oursler, Sprayberry, Spivey, Petro và Nash - đột kích vào một nhà kho trong một vụ bắt quả tang ma túy, với người quay phim Gary đi theo. Họ tìm thấy một chiếc máy bay tư nhân phía sau nhà kho. Một giọng nữ méo mó phát ra từ loa: Tất cả đều được chào đón. Tất cả đang theo dõi. Cuối cùng, các tín đồ, đêm nay là đêm mà bạn đã chờ đợi. Hãy theo dõi tín hiệu của tôi. Tín hiệu là chất kích thích. Tín hiệu là liều thuốc an thần. tín hiệu là sự cứu rỗi. &nbsp;Khi các sĩ quan đi qua các hành lang chật hẹp, họ phát hiện ra nhiều phòng giống như phòng giam của nhà tù với máy thu hình hiển thị tĩnh. Họ phát hiện ra một người đàn ông đang ngồi trong một trong những căn phòng,Tiến qua nhà kho để tìm kiếm những kẻ tình nghi, cả nhóm tiến vào căn phòng được thấy trong băng VHS và bắt gặp thêm nhiều tên tu luyện đã chết. Slater ra lệnh tìm kiếm tầng trên cùng với đội Xanh trong khi các sĩ quan còn lại tiếp tục đi khi một trong những chiếc tivi bắt đầu phát bản tin.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 1, '[{"name":"Anna Hopkins","avatar":""},{"name":"Gina Philips","avatar":""},{"name":"Christian Potenza","avatar":""},{"name":"David Reale","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324324);
