INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-virtuoso', 'The Virtuoso', 'The Virtuoso', 'https://phimimg.com/upload/vod/20231227-1/616de3be1ff247f4d096cae58883c4f2.jpg', 'https://phimimg.com/upload/vod/20231227-1/c1e316c524e6533ac4c6d426e9321750.jpg', '<p>Một người lạ lonesome, an toàn, dây thần kinh của thép, phải theo dõi và giết một kẻ lừa đảo lừa đảo để đáp ứng một khoản nợ tồn đọng. Nhưng thông tin duy nhất anh được trao là một thời gian và địa điểm nơi tìm mỏ đá của mình - 5 giờ chiều tại một quán ăn mộc mạc ở thị trấn sắp chết. Không có tên, không có mô tả, không có gì. Khi Assassin đến có một số mục tiêu có thể, bao gồm cả cảnh sát trưởng quận. Gây ra cuộc sống của mình, Assassin bắt tay vào một kẻ săn lùng để tìm người Hitman và hoàn thành nhiệm vụ của mình. Nhưng mối nguy hiểm leo thang khi những cuộc gặp gỡ khiêu dâm với một người phụ nữ địa phương đe dọa làm trật bánh nhiệm vụ của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324324);
