INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('4-kings-tu-vuong', '4 Kings: Tứ Vương', '4 Kings', 'https://phimimg.com/upload/vod/20231227-1/b7d56043b1354fb08e7f831dae0708e9.jpg', 'https://phimimg.com/upload/vod/20231227-1/8b23d43045c4e38e3127f399ce64dd4e.jpg', '<p>Sau khi cô con gái tuổi teen bị thương nặng trong một vụ đánh nhau ở trường, ông bố đơn thân nọ hồi tưởng về cuộc chiến băng đảng thời học sinh của mình vào những năm 90.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Arak Amornsupasiri","avatar":""},{"name":"Itkron Pungkiatrassamee","avatar":""},{"name":"Poom Rungsrithananon","avatar":""},{"name":"Akarin Akaranitimayratt","avatar":""},{"name":"Nat Kitcharit","avatar":""},{"name":"Warawut Brown","avatar":""},{"name":"Chanatip Pisutsereewong","avatar":""},{"name":"Sirat Intarachote","avatar":""},{"name":"Ukrit Willi Brord Dongabriel","avatar":""},{"name":"Naerunchara Lertprasert","avatar":""},{"name":"Sukanya Kelley Keaneam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324324);
