INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-trang-nguyen-to-khat-nhi-thanh-du-troi-ban', 'Võ Trạng Nguyên Tô Khất Nhi - Thánh Dụ Trời Ban', 'King Of The New Beggars', 'https://phimimg.com/upload/vod/20231227-1/51adbe13a7e2e83ee452e6ecebcbcba2.jpg', 'https://phimimg.com/upload/vod/20231227-1/2c2787eb7b633f4d536d5ce7e6fcc5f5.jpg', '<p>Thánh dụ trời ban của Võ trạng nguyên Tô Khất Nhi.\nTóm tắt: Vào cuối đời nhà Thanh, các quan đại thần liên tiếp chết một cách bất đắc kỳ tử, tin đồn về nhà Thanh sẽ diệt vong được lưu truyền trong dân gian. Vì để ngăn chặn lời đồn của quần chúng, Hoàng thượng quyết định sẽ tổ chức nghi lễ tế trời, đồng thời bí mật ra lệnh cho Phú Sát Ngự Hằng điều tra vụ án này. Phú Sát Ngự Hằng biết được mức độ nghiêm trọng của vụ án, đành phải tìm đến người bạn tốt của mình là Võ trạng nguyên đời trước, cũng chính là bang chủ Cái Bang Tô Xán nhờ giúp đỡ. Nhưng sau đó những việc ngoài ý muốn lại kéo nhau mà đến, đầu tiên là Tô Xán và Phú Sát Ngự Hằng bị ám sát, tiếp đến là cái chết bất ngờ của nhiều vị đại thần, mà thân thể họ đã bị ăn mòn gần hết. Khiến cho Tô Xán nhận ra rằng vụ án này rất khó giải quyết, phía sau nó nhất định ẩn chứa một bí mật động trời…\</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bàng Ngỗ Mỗ","avatar":""},{"name":"Liu Zheng Fei","avatar":""},{"name":"Billy Lau","avatar":""},{"name":"Lau Nam Kwong","avatar":""},{"name":"Yue Dong Feng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324324);
