INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-good-the-bart-and-the-loki', 'The Good, The Bart, And The Loki', 'The Good, The Bart, And The Loki', 'https://phimimg.com/upload/vod/20231227-1/0639003fc1a840e177ec1074cc180b0e.jpg', 'https://phimimg.com/upload/vod/20231227-1/06ea3d2010f0484f6931cfdf8b4a4cd9.jpg', '<p>Loki tham gia lực lượng với Bart Simpson để chiến đấu chống lại những đối thủ khó khăn nhất của mình ở Springfield sau khi anh ta bị trục xuất khỏi ASGARD một lần nữa.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324324);
