INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-good-the-bart-and-the-loki', 'The Good, The Bart, And The Loki', 'The Good, The Bart, And The Loki', 'the good, the bart, and the loki the good, the bart, and the loki  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-than-dat-ky', 'Phong Thần Đát Kỷ', 'The Queen', 'https://phimimg.com/upload/vod/20231225-1/68bec08ecf65a61a126e77aa5cc62cef.jpg', 'https://phimimg.com/upload/vod/20231225-1/50372db6b7a059110136b2f19bfa1ff6.jpg', '<p>Nữ quân của tộc hồ ly có chín cái đuôi và nàng phong thái yểu điệu, khuôn mặt xinh đẹp. Nàng không may rơi vào vòng tay yêu quái vượn khỉ Viên Hồng, đại ca của Mai Sơn Thất Quái. Bất ngờ nàng được Khương Tử Nha cứu ra lại bị ổng chém một cái đuôi. Nàng đến bước cùng đường, được Nữ Oa Nương Nương chỉ bảo mà lên thân Đát Kỷ, trở thành con gái của Ký Châu Hầu Tô Hộ. Vài hôm nữa, Trụ Vương dẫn đầu quân đội tấn công Ký Châu. Đát Kỷ lo lắng về người cha nên tự mình mặc giáp trụ xuất trận. Tuy nhiên Trụ Vương bắt được Đát Kỷ, hai người tâm sự về đạo lý chinh chiến. Cách nhìn của Đát Kỷ thuyết phục Trụ Vương và khiến chàng yêu nàng dần. Tối hôm đó, Trụ Vương liền thỉnh cầu Tô Hộ gả Đát kỷ cho mình. Sau đó, Đát Kỷ trở thành hoàng hậu nhà Thương và bắt đầu làm loạn thiên hạ.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Gillian Chung","avatar":""},{"name":"Natas Asoka","avatar":""},{"name":"Sammy Sum","avatar":""},{"name":"Hanson","avatar":""},{"name":"Jeana Ho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324324);
