INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-vay-ham-tu-than', 'Cuộc Vây Hãm Tử Thần', 'Deadlock', 'https://phimimg.com/upload/vod/20231225-1/4c90e0cc2d350496a11724411831b709.jpg', 'https://phimimg.com/upload/vod/20231225-1/38a5f59d0d5d5bf65cf241d9502d7528.jpg', '<p>Cuộc Vây Hãm Tử Thần - Deadlock kể về Ron Whitlock - một tên tội phạm truy nã khét tiếng dẫn đầu một đội quân đánh thuê đầy tinh nhuệ và bắt đầu kế hoạch chiếm giữ nhà máy năng lượng vì muốn báo thù. Lúc này, Mark là một cựu quân nhân, hiện đang làm việc tại một nhà máy điện Georgia, đã đứng lên hành động giải cứu con tin và ngăn chặn mọi việc trước khi xảy ra cuộc thảm họa kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Muldoon","avatar":""},{"name":" Bruce Willis","avatar":""},{"name":"Matthew Marsden","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324324);
