INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-cua-lord-elmelloi-de-nhi-chuyen-tau-suu-tap-ma-nhan-tap-dac-biet', 'Hồ Sơ Của Lord El-Melloi Đệ Nhị - Chuyến Tàu Sưu Tập Ma Nhãn (Tập Đặc Biệt)', 'Lord El-Melloi II Case Files: Rail Zeppelin Grace Note, Lord El-Melloi II Sei No Jikenbo: Rail Zeppelin Grace Note', 'https://phimimg.com/upload/vod/20240121-1/f1ffeeac65a1822dae3f24f6690dd4f7.jpg', 'https://phimimg.com/upload/vod/20240121-1/38cad1d87c9a468efdeb07d2b7b56acb.jpg', '<p>Mười năm sau khi đối mặt với thất bại trong Cuộc chiến Chén Thánh lần thứ tư, Waver Velvet, bây giờ là Lord El-Melloi Đệ Nhị, dạy các lớp học tại Tháp Đồng hồ - trung tâm giáo dục cho các pháp sư. Tuy nhiên, địa vị mới của anh ta là Lord đi kèm với một lời cảnh báo: tuân theo mệnh lệnh của Reines, em gái của người đã khuất Kayneth El Melloi, cho đến khi cô đủ tuổi để cai trị Nhà của El Melloi. Waver cùng với Gray, người học việc bí ẩn của mình, đảm nhận một loạt các vụ án do Reines và Hiệp hội pháp sư giao cho. Với mỗi trường hợp được chứng minh là phức tạp hơn lần trước, liệu có nhiều điều đến Tháp Đồng hồ hơn là nhìn thấy mắt, và những bí mật nào mà Reines che giấu?</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324324);
