INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jungle-run', 'Jungle Run', 'Jungle Run', 'https://phimimg.com/upload/vod/20231230-1/11c2f4e78aa231488a2b0b937e25ea91.jpg', 'https://phimimg.com/upload/vod/20231230-1/869543377fe5d1d1a43af0a37ab17e0e.jpg', '<p>Một cuộc tìm kiếm cho người cha mất tích của họ trở nên nguy hiểm khi những người thám hiểm anh chị em thấy mình bị động vật rừng dữ dội tấn công một cách nặng nề. Nhưng khi họ chiến đấu trở lại chống lại sự tấn công không ngừng nghỉ, họ bắt đầu nhận ra điều gì đó nhiều nham hiểm có thể đứng sau các cuộc tấn công</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324324);
