INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot-pha-vong-vay-hoa-tuyen', 'Đột Phá Vòng Vây Hỏa Tuyến', 'BREAK THROUGH', 'https://phimimg.com/upload/vod/20231230-1/8773b1b6f0139e0d34b1a0399805f3a7.jpg', 'https://phimimg.com/upload/vod/20231230-1/6a3a47e09055345ebf7d35b7b53ce104.jpg', '<p>Đạt Dung là vệ sĩ cao cấp nhất của Đông Nam Á, trong một lần hành động đã đắc tội với ông trùm ma túy địa phương và tay súng dưới tay ông ta là Sát Long. Bị Sát Long điên cuồng trả thù, khiến anh em và vợ mất mạng, Đạt Dung nản lỏng thoái chí, quy ẩn giang hồ. Năm năm sau, con gái của Đạt Dung là Kỳ Kỳ trưởng thành, vô tình bị cuốn vào một cuộc giao dịch ma túy, bị kẻ bỏ trốn bắt cóc. Để cứu con gái, Đạt Dung tái xuất giang hồ, tìm được kẻ thao túng phía sau, chính là ông trùm ma túy và tay sai Sát Long! Hai bên gặp lại tựa như sự sắp đặt của số mệnh, cuộc chiến lớn chỉ cần chạm vào là bùng nổ!</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tianye Ren","avatar":""},{"name":"Julian Chen (Banny Chen )","avatar":""},{"name":"Feng Wan He","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324324);
