INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sas-bao-dong-do', 'SAS: Báo Động Đỏ', 'SAS: Red Notice', 'https://phimimg.com/upload/vod/20231230-1/ae3d56ddafe4cc80037560ed703f515e.jpg', 'https://phimimg.com/upload/vod/20231230-1/8713709d3c3547410744751816876e12.jpg', '<p>Tom Buckingham, một nhà điều hành lực lượng đặc biệt, đang đưa Tiến sĩ Sophie Hart từ London đến Paris để cầu hôn. Khi tàu của họ sâu bên trong đường hầm kênh, Grace Lewis và đội bóng chiến tranh vũ trang nặng nề của cô chiếm lấy tàu và giữ hàng trăm con tin hành khách. Grace đe dọa sẽ phơi bày những bí mật đen tối nhất của chính phủ Anh và thổi bay đường hầm kênh nếu nhu cầu về tiền chuộc của cô không được đáp ứng. Không vũ trang và cắt đứt khỏi nhóm khủng bố truy cập của mình, Tom là hy vọng duy nhất mà Sophie và các hành khách khác phải thực hiện nó tồn tại. Dựa trên cuốn tiểu thuyết bán chạy nhất của cựu vận hành SAS Andy MCNAB, SAS: Thông báo màu đỏ là một chân dung khiêu khích và xác thực của một hoạt động đáp ứng khẩn cấp và tư duy số ít Tom cần phải sống sót.</p>', 'Full', 1, 'single', 'completed', 26, 2021, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324324);
