INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sas-bao-dong-do', 'SAS: Báo Động Đỏ', 'SAS: Red Notice', 'sas: báo động đỏ sas: red notice  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-chuong-mon-ngo-ngao-cua-toi', 'Nữ Chưởng Môn Ngổ Ngáo Của Tôi', 'My Sassy Girl', 'https://phimimg.com/upload/vod/20231230-1/ae3d77bdc12f94036ccfdcb823950e5f.jpg', 'https://phimimg.com/upload/vod/20231230-1/2d5ec6f4449ec26c3ebbd3c663dfc6dc.jpg', '<p>Nữ chưởng môn Vu Thắng Nam của Thanh Vân Đường là một cô gái cương trực, với tính tình ghê gớm và nắm đấm còn cứng hơn cả thép. Vì hoàn thành nguyện vọng của người cha ốm bệnh liệt giường. Vu Thắng Nam nóng lòng kết hôn, trên con đường đi xem mặt đầy khôi hài của mình, cô đã quen với oan gia trời định Ngưu Đa Đa, bèn ép buộc dụ dỗ ông chú khờ này ký hiệp nghị giả vờ kết hôn. Ngay khi Thắng Nam đang dần bị sự thiện lương và chất phác của Ngưu Đa Đa làm rung động, sư huynh Lâm Kiệt từng bị cha của Thắng Nam trục xuất nhiều năm về trước trở về, dùng lời lẽ khích bác, khiến ông phát bệnh qua đời. Đồng thời, hắn còn dùng một chân của Ngưu Đa Đa để ép Thắng Nam nhận lời thách đấu. Vu Thắng Nam giận dữ nhận lời, hai sư huynh muội trở mặt thành thù, thề không đội trời chung tại đại hội võ lâm.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yu Sha Sha","avatar":""},{"name":"Young-Jong","avatar":""},{"name":"Li Kui","avatar":""},{"name":"Wang Yi Qin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324324);
