INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('henrry-gia-coi', 'Henrry Già Cỗi', 'Old Henry', 'https://phimimg.com/upload/vod/20231219-1/75944bf7ae8068935543923547e8fe02.jpg', 'https://phimimg.com/upload/vod/20231219-1/d220ce60795953ba6d8d49a113849ce6.jpg', '<p>Một người nông dân góa vợ và con trai tiếp cận một người đàn ông bí ẩn bị thương với một túi tiền mặt. Khi một đội quân nhân danh luật pháp đến đòi tiền, người nông dân phải quyết định tin tưởng ai. Để bảo vệ ngôi nhà của mình, người nông dân bộc lộ tài năng bắn súng khiến mọi người ngạc nhiên và đặt câu hỏi về danh tính thực sự của anh ta.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tim Blake Nelson","avatar":""},{"name":"Scott Haze","avatar":""},{"name":"Gavin Lewis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324324);
