INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-quang-xan-lan-tru-bat-gioi', 'Xuân Quang Xán Lạn Trư Bát Giới', 'A Piggy Love Story', 'https://phimimg.com/upload/vod/20231219-1/6bcc242a358980db9e8c4c0c083caa70.jpg', 'https://phimimg.com/upload/vod/20231219-1/d26c4715f0572a8cc5bc6a258304bc14.jpg', '<p>Chuyện về một con lợn lười biếng, chỉ muốn sống thoải mái. Nó bất ngờ được cơ hội làm người, được Thái Bạch Kim Tinh bảo cho mình là Trư Bát Giới đã luân hồi 8 kiếp. Sau đó, nó bị cuốn vào sự kiện miêu yêu và cùng Tiểu Long Nữ khởi hành tìm kim đan. Nó trải nghiệm được nỗi khổ và niềm vui làm người, hiểu rõ trách nhiệm và sự đảm đương làm người, còn thu được tình yêu với Tiểu Long Nữ. Cuối cùng, Trư Bát Giới đánh bại miêu yêu, cưu vớt được bà con trấn Xuân Thủy.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xu Zi Li","avatar":""},{"name":"Yangqiru","avatar":""},{"name":"Yang Qi Ru","avatar":""},{"name":"Hao Shao Wen","avatar":""},{"name":"Wei Xiao Xuan","avatar":""},{"name":"Ewong","avatar":""},{"name":"Lee Li-Chun","avatar":""},{"name":"Tao Hong","avatar":""},{"name":"Hao Shao Wen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324324);
