INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xuan-quang-xan-lan-tru-bat-gioi', 'Xuân Quang Xán Lạn Trư Bát Giới', 'A Piggy Love Story', 'xuân quang xán lạn trư bát giới a piggy love story xu zi li yangqiru yang qi ru hao shao wen wei xiao xuan ewong lee li-chun tao hong hao shao wen ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('den-khi-ta-gap-lai', 'Đến Khi Ta Gặp Lại', 'Till We Meet Again', 'https://phimimg.com/upload/vod/20231219-1/67bc90a5be6c76725c1f367cac311d71.jpg', 'https://phimimg.com/upload/vod/20231219-1/9c4b76ec348a0c56a84c148957c4698e.jpg', '<p>A Lun (Ke Zhendong), người bị sét đánh chết, đến âm phủ, và tất cả ký ức của anh ta trước khi chết trở về con số không.&nbsp;Anh ta phải đưa ra một lựa chọn: đầu thai nhưng có thể biến thành một con ốc sên; hoặc nhận một chức tư tế, tích lũy các đức tính Âm và tái sinh làm một con người?&nbsp;Aaron quyết định trở thành một người mới đến mặt trăng cũ. Anh hợp tác với Pinky (Wang Jing), một cô gái màu hồng nóng bỏng, và đến thế giới để thực hiện một nhiệm vụ. Khi Aaron gặp chú chó Alu và dẫn dắt chủ nhân Xiaomi, anh đã ở kiếp trước, ký ức của Xiao Mi (do Song Yunhua thủ vai) đều quay trở lại.&nbsp;Aaron hy vọng sẽ giúp Xiaomi trên thế giới tìm được một cuộc hôn nhân mới, nhưng mọi sợi chỉ đỏ trói tay Xiaomi đã bị đốt cháy.&nbsp;Hóa ra một số điều sẽ không thay đổi trong 10.000 năm nữa ... Cùng lúc đó, Gui Toucheng (Ma Zhixiang), người đã trốn thoát khỏi thế giới ngầm để xuống trần gian, thực hiện một chiến dịch trả thù đẫm máu để tìm ra người anh trai trộm ngựa đã phản bội và đã giết anh ta từ năm trăm năm trước.&nbsp;Trong khi Aaron vẫn còn hào hứng về việc Xiao Mi không thể vượt qua ranh giới đỏ, Guitoucheng đã coi Xiao Mi là mục tiêu tiếp theo để tiêu diệt ...</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'VietSub', 'HD', 'Đài Loan', 0, '[{"name":"Gingle Wang","avatar":""},{"name":"Tống Vân Hoa","avatar":""},{"name":"Kha Chấn Đông","avatar":""},{"name":"Mã Chí Tường","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324324);
