INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mac-gia-co-quan-thuat', 'Mặc Gia Cơ Quan Thuật', 'Mohist Mechanism', 'https://phimimg.com/upload/vod/20231219-1/22266749d1baee0e12a6b972d5538e09.jpg', 'https://phimimg.com/upload/vod/20231219-1/52614ebbc483ee885634e0aa21255ecb.jpg', '<p>Bộ phim kể về Thẩm Thác là truyền nhân cơ quan thuật của Mặc gia, vì cứu vị hôn thê là Khương Nhẫn bị nhốt trong cơ quan thành nên đã đánh cược với giám ngục trưởng nhà tù Vô Cực, đi vào bộ phận thấp nhất của cơ quan thành, cùng sáu đồng đội tìm kiếm vật báu thần bí của Mặc gia. Nhưng Mặc gia đã bố trí vô số cơ quan tinh xảo, thay đổi khôn lường, liên miên không dứt, cạm bẫy khắp nơi, che giấu nguy hiểm chết người trong cơ quan thành, nghe nói từ trước đến nay chưa từng có ai sống sót thoát ra. Từ đây Thẩm Thác và đồng đội bắt đầu một cuộc trốn chạy sống chết vô cùng gay cấn và nghẹt thở trong mật thất.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Lin Cheng","avatar":""},{"name":"Rachel","avatar":""},{"name":"Tu Yu Ming","avatar":""},{"name":"Xu Ci","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324324);
