INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-lop-phuc-trang', 'Dưới Lớp Phục Trang', 'Sa Balik Baju', 'https://phimimg.com/upload/vod/20231219-1/d7378eddfaa46bca08fab930c9fae51d.jpg', 'https://phimimg.com/upload/vod/20231219-1/a47111e89e90a37ed8643cab7b4a2235.jpg', '<p>Các câu chuyện đan xen xoay quanh 6 người phụ nữ khi họ đương đầu với những áp lực hiện đại của mạng xã hội, công việc và mối quan hệ trong thời đại số.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'HD', 'Malaysia', 0, '[{"name":"Nadiya Nissa","avatar":""},{"name":"Elena Laurel Moujing","avatar":""},{"name":"Juliana Evans","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324324);
