INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-si-nui-lao', 'Đạo Sĩ Núi Lao', 'Laoshan Taoist', 'https://phimimg.com/upload/vod/20231219-1/ef632e14401a5d51324bb81d205c94ec.jpg', 'https://phimimg.com/upload/vod/20231219-1/9380903223b1d7a36eaa9ca04dba2ff3.jpg', '<p>Vương Sinh là một người thiếu niên lông bông mà chỉ muốn tu luyện Đạo pháp Núi Lao. Dù bị người ta chất vấn, nhưng chàng cũng khăng khăng lên đường Cầu Đạo. Qua bao khó khăn, cuối cùng chàng được cao nhân chỉ bảo và được đồng môn ủng hộ. Sau khi tìm ra thân thế thật sự và kiên định chủ tâm của mình, Vương Sinh ngộ Đạo và quyết tâm dùng cách mình để chống lại Huyền Chân Yêu Đạo.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Qi Wei","avatar":""},{"name":"胡雪兒","avatar":""},{"name":"Hugo Ng Doi-Yung","avatar":""},{"name":"Shang Tie Long","avatar":""},{"name":"Bryan Leung","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324324);
