INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ito', 'Ito', 'Ito', 'https://phimimg.com/upload/vod/20231219-1/67cf7a44d6bd920ba364ef884e70cb55.jpg', 'https://phimimg.com/upload/vod/20231219-1/2047fe644fcf9e2cae741fb9a36d2443.jpg', '<p>Ito Soma có tài chơi Tsugaru-shamisen. Âm nhạc có nguồn gốc từ tỉnh Aomori và liên quan đến nhạc cụ dân gian truyền thống Tsugaru-shamisen, một nhạc cụ ba dây gảy. Ito Soma học chơi Tsugaru-shamisen từ người mẹ đã qua đời của cô. Do tiếng địa phương Tsugaru mạnh mẽ và tính cách nhút nhát của mình, cô ấy gặp khó khăn khi chơi ở nơi công cộng và cũng gặp khó khăn trong môi trường xã hội. Cô ấy không có bất kỳ người bạn nào. Để thay đổi bản thân, Ito Soma bắt đầu công việc bán thời gian tại một quán cà phê hầu gái.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ren Komai","avatar":""},{"name":"Etsushi Toyokawa","avatar":""},{"name":"Mei Kurokawa","avatar":""},{"name":"Mayuu Yokota","avatar":""},{"name":"Ayumu Nakajima","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324324);
