INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-nguoi-yeu-cua-toi', 'Xin Chào, Người Yêu Của Tôi', 'Hello Heart', 'https://phimimg.com/upload/vod/20231219-1/516a3983015e28f54e91fa7d9ed3708d.jpg', 'https://phimimg.com/upload/vod/20231219-1/64834d01e0c8e6e07b9be3f23e3c2779.jpg', '<p>Hart là một người phụ nữ xinh đẹp, nhanh nhẹn, cần cù nhưng hết sức bất hạnh, cuối cùng gặp được Saul, bùa hộ mệnh của mình. Anh ấy là một người không có tình cảm, không chịu thay đổi và mời Hart giả vờ người vợ của mình để lấy lòng bà nội đã mắc bệnh Alzheimer. Mặc dù hai người ghét nhau, nhưng tình yêu sẽ tìm được biện pháp. Tuy nhiên lúc nào mới có thể nói mối tình này đã trở nên chân thực?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 12, 2021, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Celeste Legaspi","avatar":""},{"name":"Gerald Anderson","avatar":""},{"name":"Gigi De Lana","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324324);
