INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-ren-kiem-vi-dai', 'Thợ Rèn Kiếm Vĩ Đại', 'Sword Of Destiny', 'https://phimimg.com/upload/vod/20231219-1/6421356f6ca946e625d7d543ebc84a1d.jpg', 'https://phimimg.com/upload/vod/20231219-1/9c0dc0979cba6457dc50cd10150d3715.jpg', '<p>Giới thiệu vắn tắt: Mối họa diệt môn đến từ gian thần triều đình Triệu Hàm đã ập tới gia đình thợ rèn kiếm số một thiên hạ Mông Dã Tử vì ông rèn ra thanh kiếm nổi danh Hàm Quang, ông liều mạng bảo toàn tính mạng cho Mông Dương và để lại thanh kiếm Thừa Ảnh đang rèn dang dở. Hai mươi năm sau Mông Dương khôn lớn thành người, lên kế hoạch báo thù cho cha, nhưng thanh kiếm Thừa Ảnh có thể khắc chế được thanh kiếm Hàm Quang lại vẫn mãi chưa đúc thành. Hoàng đế bệnh tình nguy kịch, vừa hay cơ duyên đến, Mông Dương nhận được nhiệm vụ hộ tống Thái tử Công Tử Đô về cung kế vị. Để điều tra chân tướng vụ Mông phủ bị diêt môn và báo thù cho cha, Mông Dương đã tiếp nhận nhiệm vụ, lần nữa kéo về mối họa sát thân…</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xiao Zi Mo","avatar":""},{"name":"Yang Yi","avatar":""},{"name":"Vangie","avatar":""},{"name":"Chai Yuan Le","avatar":""},{"name":"Zhang Bai Qiao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324324);
