INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boc-tran-su-that', 'Bóc Trần Sự Thật', 'Intrepid Hero', 'https://phimimg.com/upload/vod/20231219-1/821fa4413374280e7544088673be2785.jpg', 'https://phimimg.com/upload/vod/20231219-1/8aeb5a4d72ebcb7c8c93a1ad4aea4430.jpg', '<p>Bóc Trần Sự Thật - Intrepid Hero là một bộ phim trinh thám hấp dẫn. Khi một xác chết được tìm thấy ở ngoại ô thành phố Mingde, lực lượng cảnh sát thành phố đã được huy động để điều tra gấp về nguyên nhân. Dần dần sự thật được hé lộ khi chủ tịch Tập đoàn Dingfeng - Lin Feng đã tham gia vào vụ giết người, đánh bạc và nhiều tội danh khác.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Song Zong-Li","avatar":""},{"name":"Tong LiyaGong Yu","avatar":""},{"name":"Zhang Dong-Ling","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324324);
