INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-tro-xuat-sac', 'Học Trò Xuất Sắc', 'The Disciple', 'https://phimimg.com/upload/vod/20231219-1/a3a28b1b7c992bcf5375587bd7a64648.jpg', 'https://phimimg.com/upload/vod/20231219-1/aef435260efbddfb5e8c623cc408ab75.jpg', '<p>Nghi ngờ bản thân, hi sinh rồi tranh đấu... tất cả dồn nén và trở thành dấu hỏi lớn về sự tồn tại với ca sĩ cổ điển tận tụy khi đẳng cấp anh mong muốn vẫn xa tầm tay với.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Aditya Modak","avatar":""},{"name":"Arun Dravid","avatar":""},{"name":"Sumitra Bhave","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324324);
