INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-cleaner', 'The Cleaner', 'The Cleaner', 'https://phimimg.com/upload/vod/20231219-1/7613db228d07924ad3661c52bc09ebaf.jpg', 'https://phimimg.com/upload/vod/20231219-1/215262a3c39a95323a72ddf6d2d55583.jpg', '<p>Cuộc sống của Buck Enderly đã không hoạt động theo cách anh lên kế hoạch. Anh ta là một người dọn dẹp nhà ở trung niên sống với mẹ, người mà anh ta phải chăm sóc sau khi cô bị chấn thương suy nhược. Khi Buck đảm nhận một khách hàng mới lập dị, anh ta bị kéo vào một công việc phụ định vị con trai estranged của mình. Với sự giúp đỡ của những người hàng xóm hai mươi tuổi, Buck tra lại với chàng trai trẻ bị xáo trộn. Nhưng sau đó trong một twist khác của số phận, anh ta thấy mình là một đồng phạm với một tội ác bạo lực. Bây giờ Buck phải che giấu sự thật từ gia đình, bao gồm cả em trai của mình - một sĩ quan cảnh sát địa phương.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324324);
