INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-quai-sieu-cap-chuyen-ngay-xua-ngay-xua', 'Hội Quái Siêu Cấp: Chuyện Ngày Xửa Ngày Xưa', 'Super Monsters: Once Upon A Rhyme', 'https://phimimg.com/upload/vod/20231219-1/29fc7830d47726d73bf353c110d132b5.jpg', 'https://phimimg.com/upload/vod/20231219-1/550b496f56e46f96403328001d82215a.jpg', '<p>Từ Goldilocks đến Hansel và Gretel, Hội Quái Siêu Cấp viết lại những câu chuyện cổ tích kinh điển và giai điệu trẻ thơ yêu thích với một chút âm nhạc và phép thuật.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elyse Maloway","avatar":""},{"name":"Vincent Tong","avatar":""},{"name":"Andrea Libman","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324324);
