INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-vuong', 'Lang Vương', 'The Werewolf', 'https://phimimg.com/upload/vod/20231219-1/ec2b4dadfad61c6eb264f92f8347f63c.jpg', 'https://phimimg.com/upload/vod/20231219-1/5fe0910f139b7be65eaa22da5feb28ae.jpg', '<p>“Tham Lang Tinh” biến thành hình hài con người, giáng xuống trần gian, sống cùng với bầy sói 20 năm và trở thành một chàng thiếu niên nhanh nhẹn mà thông hiểu tập tính con sói. Trong quá trình đi săn, nàng thiếu nữ của làng Thợ Săn lỡ tay làm thương chàng sói và đem chàng về làng. Tiếc rằng bà con trong làng bài xích chàng sói đủ kiểu. May mà trong quá trình ăn ở với con người, chàng sói hiểu tính người dần và công phá “Tứ Thú Trận” của làng Thợ Săn bằng võ thuật mình học được. Làng Thợ Săn đành vậy tiếp nhận “quái vật” nửa người nửa sói này. “Phá Quân Tinh”, có vận mệnh nhất định sẽ quyết chiến với “Tham Lang Tinh”, xưng bá giang hồ, hiện giờ đã là hiệp sĩ nổi tiếng. Sau khi được biết sự giáng trần của “Tham Lang Tinh”, “Phá Quân Tinh” dẫn “Thất Sát Tinh” đến làng Thợ Săn, chỉ muốn tìm được “Tham Lang Tinh” và quyết chiến với anh ấy.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Owodog","avatar":""},{"name":"Hao-Chuan Chuang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324324);
