INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-ky-dac-bao-o-thieu-lam-tu', 'Truyền Kỳ Đắc Bảo Ở Thiếu Lâm Tự', 'Shao Lin Shi Zhi De Bao Chuan Qi', 'https://phimimg.com/upload/vod/20231230-1/8f56c274113636f51178c8cf0e774096.jpg', 'https://phimimg.com/upload/vod/20231230-1/62264837eff4ece80f56dab012363d9a.jpg', '<p>Tây Môn Đắc Bảo là một ông chủ quán trọ không có chí, hàng ngày cùng huynh đệ đóng giả sơn tặc còn mình đóng giả tướng quân cứu người nhằm dẫn khách tới khách trạm của mình. Không may một ngày màn kịch bị vạch trần, lại thêm một ông hòa thượng già cản trở việc làm ăn. Họa không chỉ thế, Thứ sử Linh Châu là Hà Kiêu lại giết khâm sai rồi đổ tội cho Đắc Bảo nhằm có được bảo đồ kho báu. Trong một đêm, Đắc Bảo trở thành tội phạm truy nã, con trai mất mạng, vì để trả thù Đắc Bảo đã theo hòa thượng học võ công. Từ đây mở ra một cuộc hành trình đắc đạo đầy ly kỳ.</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Bảo Cường","avatar":""},{"name":"Lưu Hạo Nhiên","avatar":""},{"name":"Nghê Đại Hồng","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324324);
