INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-kinh-hoang', 'Sát Nhân Kinh Hoàng', 'Ted Bundy: American Boogeyman', 'https://phimimg.com/upload/vod/20231227-1/b93a91b99e87ba88444f964200de5737.jpg', 'https://phimimg.com/upload/vod/20231227-1/c1a9c69e5f67a1b5495474cb767cc296.jpg', '<p>Sát Nhân Kinh Hoàng lấy bối cảnh vào năm 1970 tại nước Mỹ, tên sát nhân Ted Bundy đã gây ra nỗi ám ảnh cho mọi người trên đường cao tốc và đang săn lùng con mồi tiếp theo, nhưng chưa có ai dem được hắn ra trước ánh sáng công lý. Nhưng vị nữ thám tử đầy gan dạ Kathleen McChesney hiện đang làm việc tại văn phfogn cảnh sát và anh chàng tân binh FBI Robert Ressler từ đây bắt đầu cuộc hành trình săn lùng tên sát nhân ra trước công lý.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chad Michael Murray","avatar":""},{"name":"Holland Roden","avatar":""},{"name":"Jake Hays","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324324);
