INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ngay-thang-cuoi', 'Những Ngày Tháng Cuối', 'Swan Song', 'https://phimimg.com/upload/vod/20231227-1/fc70dbd5439185d4e4ed61ddfa538cae.jpg', 'https://phimimg.com/upload/vod/20231227-1/845d5b552a335bdef170fc6af27e18a8.jpg', '<p>Đặt trong tương lai gần, Swan Song Song là một hành trình mạnh mẽ, cảm xúc đã nói qua con mắt của Cameron (Mahershala Ali), một người chồng yêu thương và người cha được chẩn đoán mắc một căn bệnh ga được trình bày với một giải pháp thay thế của bác sĩ (Glenn Close ) để che chắn gia đình khỏi đau buồn. Khi Cam Grapples có hay không làm thay đổi số phận của gia đình anh ta, anh ta học được nhiều hơn về cuộc sống và tình yêu hơn bao giờ anh tưởng tượng. Swan Song khám phá chúng ta sẽ đi bao xa, và chúng ta sẵn sàng hy sinh bao nhiêu, để làm cho một cuộc sống hạnh phúc hơn cho những người chúng ta yêu thích.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324324);
