INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-con-cuoi-cung', 'Đứa Con Cuối Cùng', 'The Last Son', 'https://phimimg.com/upload/vod/20231227-1/448756d1cff20e6d0325e028a38c05c8.jpg', 'https://phimimg.com/upload/vod/20231227-1/f428e62baba2860d25a8299bd1d8b805.jpg', '<p>Ở một nơi nào đó ở miền tây hoang dã, vào khoảng thời gian sau cuộc nội chiến, huyền thoại sống ngoài vòng pháp luật Isaac LeMay (Sam Worthington) quyết định tự tay nhận lấy số phận của mình và phá vỡ một lời tiên tri rằng anh ta chỉ có thể bị giết bởi một trong những đứa con của mình. Điều đó có nghĩa là theo dõi nhiều con cái của anh ta và giết chúng trước, từng con một. Một người đàn ông rất ít lời nhưng lại có một mái tóc xù và sự may mắn kỳ lạ khi tránh được đạn, LeMay có một vài tài lẻ, nhưng không mấy quyến rũ. Ngoài ra, anh ấy rõ ràng chưa bao giờ đọc bất kỳ câu chuyện cổ tích nào về các bi kịch Hy Lạp nếu không anh ấy sẽ biết rằng một khúc quanh trớ trêu nằm ngay trên con đường của anh ấy trong màn cuối cùng, một điều mà hầu hết người xem sẽ thấy đến từ hàng dặm trên thảo nguyên và địa hình đồi núi....</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Heather Graham","avatar":""},{"name":"Sam Worthington","avatar":""},{"name":"Machine Gun Kelly","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324324);
