INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-ca-ac-ma', 'Hơn Cả Ác Ma', 'Beyond Evil', 'https://phimimg.com/upload/vod/20231219-1/f65024702f5e3e8c1de46a1a170fc8d6.jpg', 'https://phimimg.com/upload/vod/20231219-1/9cf444213107cff60363c397c3d5a4ab.jpg', '<p>Beyond Evil kể về cuộc gặp gỡ của hai thám tử dũng cảm, sẵn sàng mạo hiểm để tìm đáp án cho mọi vụ án. Lee Dong Sik, một thám tử tài năng nhưng lại bị giáng chức để làm tất cả những công việc tẻ nhạt và nhàm chán tại Trạm cảnh sát Manyang. Sau đó Han Joo Won, một thám tử ưu tú khác, với gia thế đáng ngưỡng mộ, lại được chuyển đến trụ sở Manyang và trở thành cấp trên của Dong Sik. Hai người đã gạt bỏ những khác biệt để bắt tay vào phá một vụ án giết người hàng loạt kéo dài từ 20 năm trước.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Shin Ha-Kyun","avatar":""},{"name":"Yeo Jin-goo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324324);
