INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-tam-tua-ngoc', 'Cẩm Tâm Tựa Ngọc', 'The Sword And The Brocade', 'https://phimimg.com/upload/vod/20231219-1/4ebc24215336277144790ee3a567c1a8.jpg', 'https://phimimg.com/upload/vod/20231219-1/60adfd6e158525bc67c4cf02cff35a49.jpg', '<p>Thập Nhất Nương (Đàm Tùng Vận thủ vai) một tiểu thư trâm anh đài các nhưng không may bị gả vào nhà của vương gia Từ Lệnh Nghi. Hai người cưới nhau vì nghĩa vụ với gia tộc chứ không hề có chút tình cảm gì với nhau. Thế nhưng vì sự đáng yêu, ngay thẳng chính trực của Thập Nhất Nương mà dần dần Từ Lệnh Nghi (Chung Hán Lương đảm nhận) nảy sinh tình cảm với cô lúc nào không hay. Với sự quan tâm đầy ôn nhu của phu quân nàng Thập Nhất Nương cũng dần bị cảm hóa và từ đó cả hai chia sẻ tình cảm cho nhau nhiều hơn. Hạnh phúc chưa được bao lâu thì Từ Lệnh Nghi nghe theo lệnh triều định phải rời xa nhà, bỏ lại Thập Nhất Nương một mình. Ngoài việc ngóng trông phu quân trở về nàng còn phải đối diện với các thành viên Từ gia khi họ liên tiếp gây khó dễ cho cô. Cho tới khi Từ gia gặp biến cố lớn, cả nhà đều bị bắt giam còn Thập Nhất Nương lại bị tuyên án tử. Lúc này Từ Lệnh Nghi sẽ làm gì để cứu thê tử cũng như gia đình của mình?</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 16, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chung Hán Lương","avatar":""},{"name":"Đàm Tùng Vận","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324324);
