INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-nguu-phan-no', 'Hoàng Ngưu Phẫn Nộ', 'Angry Scalper', 'https://phimimg.com/upload/vod/20231219-1/1736a82b9fbc6377f94effb4fd169ef8.jpg', 'https://phimimg.com/upload/vod/20231219-1/dce31bfc67d714917e17573608c08fbe.jpg', '<p>Ở trong một nước Đông Nam Á nào đó, Ba Đồ và người vợ của anh Tháp Na bất ngờ gặp phải ông trùm tập đoàn tội phạm mua bán người Ca Phóng. Sau đó Tháp Na bị Ca Phóng bắt cóc. Người vợ mất tích lạ lùng khiến Ba Đồ hết sức sốt ruột, cùng bạn thân Lão Tiêu đi tìm trinh thám Tụng Xai giúp đỡ. Ba người dần dần tìm ra chân tướng qua manh mối nhỏ nhặt, gặp phải rất nhiều nguy hiểm, Ba Đồ căm phẫn mà trở thành anh hùng gan dạ, xông vào đầm rồng hang hổ để cứu vợ.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wu Yue","avatar":""},{"name":"Dong Xuan","avatar":""},{"name":"Cui Zhi Jia","avatar":""},{"name":"Samuel Ku","avatar":""},{"name":"Samuel","avatar":""},{"name":"Liang Chao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324324);
