INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-song-liao', 'Cuộc Chiến Song Liao', 'My GuiYing Command', 'https://phimimg.com/upload/vod/20231214-1/78d9a8339ff1359afbf2bcd0cb407900.jpg', 'https://phimimg.com/upload/vod/20231214-1/292908b7cc0a37020ab0d4ef60dc5121.jpg', '<p>Cuộc Chiến Song Liao - My GuiYing Command kể câu chuyện Mộc Quế Anh (Hàn Phi Nhi đóng) cùng thuộc hạ trà trộn vào quân doanh Liêu Quốc suýt bị bắt, may nhờ có Dương Tông Bảo (Chu Đình Bắc đóng) cứu giúp. Dương Tông Bảo theo phụ thân Lục Lang Dương Đình Chiêu (Dương Tử đóng) thống lĩnh đại quân phản kích quân Liêu giành lại lãnh thổ đã mất. Dương gia quân đang thắng thế nhưng bất ngờ gặp Thiên Môn Mê Hồn trận liền bị rơi vào ảo ảnh mất đi lí trí. Tà trận được giăng ngoài Nhạn Môn Quan, cô lập đại quân, tình thế vô cùng nguy cấp. Mộc Quế Anh đã xin Dương Đình Chiêu được thống lĩnh binh lính, bày kế phá bỏ thế trận của quân Liêu, xóa tan sương mù chứa độc khí, đồng thời đích thân dẫn quân giết chết tà sư quỷ kế đa đoan.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Han Ni","avatar":""},{"name":"Yang Zi","avatar":""},{"name":"Zhu Tingbei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324324);
