INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-dia-bao-lien-dang', 'Thiên Địa Bảo Liên Đăng', 'The Magic Lotus Lantern', 'https://phimimg.com/upload/vod/20231214-1/74e7ce95880aae650c7493eab9f3e924.jpg', 'https://phimimg.com/upload/vod/20231214-1/28d3dd48baa433435c199cc22cca5189.jpg', '<p>Bảo Liên Đăng trấn giữ trời đất bị mất trộm, Dương Tiễn tự mình giáng trần tìm đèn và yêu nhau với một người phụ nữ phàm trần. Hai người cùng nhau chống lại Ma Quân Hỗn Độn hòng lật đảo Lục Giới, cuối cùng ngăn trở Bảo Liên Đăng bị hủy.</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhao Wen Hao","avatar":""},{"name":"Ewong","avatar":""},{"name":"Mou Feng Bin","avatar":""},{"name":"Fang Jia Yi","avatar":""},{"name":"Wang Wei Guo","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324324);
