INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-cua-huong-bac-ha', 'Mùa Hè Của Hương Bạc Hà', 'Summer Again', 'https://phimimg.com/upload/vod/20231219-1/c5c070a05a88113770109cdef5725821.jpg', 'https://phimimg.com/upload/vod/20231219-1/83a4660f78b6740df10246fdb5f0ecbe.jpg', '<p>Cô gái múa ba lê Đồng Tịch phải giã từ thành phố lớn để trở về thị trấn nhỏ ở quê nhà do mẹ bị điều chuyển công tác.&nbsp;Cô muốn nhân cơ hội chuyển trường che giấu tính cách mạnh mẽ của mình nhưng nào ngờ lại bị thanh mai trúc mã Lâm Nam Nhất thân quen từ nhỏ nhìn thấu.&nbsp;Một người muốn đóng kịch, một người muốn vạch trần, từ liên tục hiểu lầm đến giúp đỡ lẫn nhau, cặp đôi oan gia này dần dần thấu hiểu và dựa dẫm vào nhau hơn trong cuộc sống thường ngày cùng bạn bè ở thị trấn.Tuy nhiên, Đồng Tịch vô tình biết được Lâm Nam Nhất chính là nam thần truyện tranh mà cô ngưỡng mộ bấy lâu...&nbsp;Khi những bối rối trên con đường theo đuổi ước mơ chạm phải những rung động đầu đời ngây ngô, trong trẻo, mối lương duyên tiền định này sẽ viết nên câu chuyện thanh xuân ngọt ngào vui vẻ trong mùa hè này.Và giữa họ còn rất nhiều những cuộc hội ngộ và chia ly...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 13, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nghê Kha Hân","avatar":""},{"name":"Trần Hạc Nhất","avatar":""},{"name":"Cora","avatar":""},{"name":"Johnson","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324324);
