INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-sat-thu-bao-thu', 'Nữ Sát Thủ Báo Thù', 'The Protege', 'https://phimimg.com/upload/vod/20231213-1/238e61e4402a9fa1027934217c248318.jpg', 'https://phimimg.com/upload/vod/20231213-1/67dcf4c7ec7cc4b0db210f355ff36e4f.jpg', '<p>Giải cứu khi còn là một đứa trẻ bởi sát thủ huyền thoại Moody, Anna là kẻ giết người hợp đồng lành nghề nhất thế giới. Tuy nhiên, khi Moody bị giết một cách tàn nhẫn, cô thề sẽ trả thù cho người đàn ông đã dạy cô mọi thứ cô biết.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324324);
