INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-than-thac-thap-thien-vuong', 'Phong Thần: Thác Tháp Thiên Vương', 'The Legend Of Deification', 'https://phimimg.com/upload/vod/20231213-1/b3a92e45b14ba91aa2eb6c820d31bb21.jpg', 'https://phimimg.com/upload/vod/20231213-1/051025840312a60ea581d478257d46ba.jpg', '<p>Vào thời thượng cổ, Xích Hầu và Hoàng Đế bị đánh bại, bị phong ấn tại một nơi nào đó ở Đông Hải, thế cục đã được sắp đặt. Ba ngàn năm sau, chàng thiếu niên Lý Tịnh tu hành công pháp ở núi Côn Luân, nhận lệnh xuống núi giáng yêu trừ ma. Trên đường đi, Lý Tịnh đã gặp được Khương Tử Nha đa mưu túc trí, thiếu nữ Phụng Thập, và giao long Ngao Quang. Đúng lúc này, thành chủ của thành Đại Hoang cho rằng quái vật Ổ Nhậm cố ý sát hại bách tính, hơn nữa còn có mưu đồ hồi sinh Xích Hầu. Bốn người ăn nhịp với nhau, quyết tâm hợp lực thu phục yêu quái, cùng nhau giải quyết nguy cơ của nhân gian. Một trận chiến giữa thiện và ác bắt đầu…</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Huai Wen","avatar":""},{"name":"Lang Feng","avatar":""},{"name":"Khương Manh Hiên","avatar":""},{"name":"Chen Xi Wen","avatar":""},{"name":"Wang Cheng Jun","avatar":""},{"name":"Kong Yu Qian","avatar":""},{"name":"Lv Wen Jun","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324324);
