INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('east-of-the-mountains', 'East Of The Mountains', 'East Of The Mountains', 'https://phimimg.com/upload/vod/20231212-1/7ed536883bd1b7cb961b4adb62bd2593.jpg', 'https://phimimg.com/upload/vod/20231212-1/d8d2facd516a2c8931f16a2c8929b147.jpg', '<p>Dựa trên cuốn tiểu thuyết bán chạy nhất của David Guterson khi bác sĩ phẫu thuật trái tim đã nghỉ hưu Ben Givens biết rằng anh ta bị ung thư đầu cuối, anh ta đưa chú chó yêu dấu của mình trở lại ngôi nhà tuổi thơ của mình ở phía đông Washington, quyết tâm kết thúc cuộc sống của mình. Mặc dù vậy, hành trình của Ben có một bước ngoặt bất ngờ, và sớm trở thành một cuộc phiêu lưu chống lại mình với chủ nghĩa khắc kỷ đặc trưng, trí thông minh và quyết tâm.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324324);
