INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('parallel-mothers', 'Parallel Mothers', 'Parallel Mothers', 'https://phimimg.com/upload/vod/20231211-1/546f1060ff147b1e565e2e0221321f41.jpg', 'https://phimimg.com/upload/vod/20231211-1/fe5ab8cc4bfcdb49c5672caf88446a93.jpg', '<p>Hai người phụ nữ, Janis và Ana, trùng hợp trong một căn phòng bệnh viện nơi họ sẽ sinh con. Cả hai đều độc thân và mang thai một cách tình cờ. Janis, trung niên, không hối tiếc và cô ấy đang nổi dậy. Khác, Ana, một thanh thiếu niên, sợ hãi, ăn năn và bị chấn thương. Janis cố gắng khuyến khích cô ấy trong khi họ di chuyển như những người mộng du dọc theo hành lang bệnh viện. Một vài từ họ trao đổi trong những giờ này sẽ tạo ra một liên kết rất gần giữa hai người, mà tình cờ phát triển và phức tạp và thay đổi cuộc sống của họ một cách quyết định</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324324);
