INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thanh-thien-co-quan-tai-rong', 'Bao Thanh Thiên: Cổ Quan Tài Rỗng', 'Tomb Empty Coffin', 'https://phimimg.com/upload/vod/20231211-1/b005097a9bc109bbc34d15438650c68a.jpg', 'https://phimimg.com/upload/vod/20231211-1/8ee5cc9b574d55ae13822207386d7fd5.jpg', '<p>Bao thanh thiên: Cổ quan tài rỗng - Tomb Empty Coffin&nbsp; là bộ phim thuộc thể loại hành động, cổ trang, giả tưởng của Trung Quốc. Tác phẩm do đạo diễn Mieng Chan chịu trách nhiệm chỉ đạo, với sự tham gia của các diễn viên Zheng Guolin, Chen Mengxi và Yuan Fufu.Vào những năm đầu của Thiên Kinh thuộc triều đại Bắc Tống, hai anh em nhà họ Tề chuyên tu sửa mộ đã đào được một ngôi mộ đơn độc vào đêm khuya, sau đó gây ra một vụ biến xác. Người anh cả chết tại chỗ còn người em thứ hai thì lại phát điên, ai cũng nguy kịch một lúc.Bao Thanh Thiên khi đó đang là thanh tra của nhà Tống, nhận được tin dữ về cái chết đột ngột của sư phụ Hồ Vĩnh, liền dẫn thị vệ của mình là Triển Chiêu đi đến quận Công An, nơi mà những người trẻ tuổi theo học nghệ thuật. Bao Thanh Thiên biết rằng sư phụ của anh ta là người được đồn đại là xác chết biến hình ở thành phố.Tron khi mọi người vào thành phố để điều tra, các vụ án lột da và giết người lần lượt nổ ra. Bao Thanh Thiên không nghĩ rằng nguyên nhân cái chết của sư phụ mình có liên quan đến sự mất tích của một cô gái đã treo cổ nhiều năm trong thành phố.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324324);
