INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-chang-the-truong-thanh', 'Chúng Ta Chẳng Thể Trưởng Thành', 'We Couldn''t Become Adults', 'https://phimimg.com/upload/vod/20231211-1/2518acf32eead32f9aedea4da3afb09c.jpg', 'https://phimimg.com/upload/vod/20231211-1/a6489fd2102a31009ce3af7b71118e83.jpg', '<p>Một lời mời kết bạn khiến người đàn ông kém thành đạt ở độ tuổi 40 nhớ lại các mối quan hệ cũ từ những năm 90, để tìm lại những hy vọng và ước mơ đã tan biến.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Moriyama Mirai","avatar":""},{"name":"Ito Sairi","avatar":""},{"name":"Higashide Masahiro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324324);
