INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-toi-oi-ma-oi', 'Cứu Tôi! Ôi Ma ơi', 'Help Me! Oh My Ghost', 'https://phimimg.com/upload/vod/20231219-1/f33696c0fed45ea22f1f09485c30c67d.jpg', 'https://phimimg.com/upload/vod/20231219-1/52ff6aed2e0988bc8ef961940476ca78.jpg', '<p>Âm mưu trở lại với vợ cũ của mình từ kiếp trước, một hồn ma ám ảnh kết bạn kết bạn với một phụ nữ và khiến cuộc sống của cô đảo lộn.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 11, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Chantavit Dhanasevi","avatar":""},{"name":"Diana Flipo","avatar":""},{"name":"Parit Thimthong","avatar":""},{"name":"Kannarun Wongkajornklai","avatar":""},{"name":"Songsit Roongnophakunsri","avatar":""},{"name":"Kathaleeya McIntosh","avatar":""},{"name":"Smithi Likhitmaskul","avatar":""},{"name":"Weerakaniz Karnwatanagool","avatar":""},{"name":"Apinan Prasertwatanakul","avatar":""},{"name":"Mayurin Pongpudpunth","avatar":""},{"name":"Krisiree Suksawadi","avatar":""},{"name":"Viraka","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324324);
