INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-con-gai', 'Giải Cứu Con Gái', 'Take Back', 'https://phimimg.com/upload/vod/20231211-1/7ebf7a1cf4818a6ad78bdc6b8c5ea654.jpg', 'https://phimimg.com/upload/vod/20231211-1/3d95100a95fa08e3bee9f19017e71b84.jpg', '<p>Bộ phim xoay quanh gia đình nhỏ hạnh phúc của Zara và Brian cùng với cô con gái thân yêu, họ sống những tháng ngày yên bình tại một thị trấn nhỏ. Cuộc sống phút chốc bị phá vỡ khi một kẻ lạ mặt bí ẩn từ quá khứ tìm đến bắt cóc cô con gái thân yêu đi mất. Để giải cứu con mình Brian và Zara phải chạy đua với thời gian, đối mặt với muôn trùng nguy hiểm chết người để tìm kiếm cứu con mình thoát khỏi tên bắt cóc chết tiệt.</p>', 'Full', 1, 'single', 'completed', 6, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mickey Rourke","avatar":""},{"name":"Michael Jai White","avatar":""},{"name":"Gillian White","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324324);
