INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-bao', 'Cảnh Báo', 'Warning', 'https://phimimg.com/upload/vod/20231212-1/7684b10d3151b1faa2f5ee9673180049.jpg', 'https://phimimg.com/upload/vod/20231212-1/0bed70aa418e87fba1a49a26eaa955b0.jpg', '<p>Đặt trong tương lai không quá xa, Thriller khoa học viễn tưởng mãnh liệt này khám phá các hậu quả mà nhân loại phải đối mặt khi công nghệ toàn tri của họ trở thành người thay thế cho sự tiếp xúc của con người. Nhưng cuộc sống bắt đầu làm sáng tỏ khi một cơn bão toàn cầu gây ra các thiết bị điện tử đi Haywire, dẫn đến hậu quả đáng sợ, gây chết người.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324324);
