INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-dau-nha-giau', 'Làm Dâu Nhà Giàu', 'Daughter In War', 'https://phimimg.com/upload/vod/20231219-1/65ae2251a4380d6361e0675994beb13f.jpg', 'https://phimimg.com/upload/vod/20231219-1/bbfb270b4bf7162e575251368f35a374.jpg', '<p>Bộ phim Làm Dâu Nhà Giàu (Daughter In War) xoay quanh gia đình ông Tien, một doanh nhân giàu có nhưng bảo thủ và gia trưởng. Ông luôn bắt 4 người con trai phải làm theo ý của mình thậm chí là chuyện kết hôn. Tuy nhiên, người con trai út tên là Traiwit vì không muốn nối nghiệp gia đình nên đã quyết định trở thành cảnh sát và rời khỏi nhà chuyển đến vùng Đông Bắc sống. Tại đó anh gặp Fahsai, cô gái thôn quê mạnh mẽ và luôn mang trong mình hoài bão phát triển quê hương. Ban đầu vì hiểu lầm mà Fahsai không ưa Traiwit. Sau đó, do phải trở về Băng Cốc, Traiwit đã thuê Fahsai kết hôn giả với anh và cùng nhau nghĩ cách đối phó ông Tien. Khi về làm dâu, Fahsai đã gặp phải sự phản đối dữ dội của cha chồng trong khi tình cảm giữa cô và Traiwit lại ngày một lớn dần.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 11, 2021, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Ohm Kanin Stanley","avatar":""},{"name":"Prima Bhunjaroeun","avatar":""},{"name":"Jaturong Mokjok","avatar":""},{"name":"Kaew Apiradee Pawaputanont","avatar":""},{"name":"Singto Sakolrat Puntace","avatar":""},{"name":"Kat Trinnaya Morson","avatar":""},{"name":"Khame Narawit Chitbanchong","avatar":""},{"name":"Paint Krittakan Prasitpanit","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324324);
