INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-dai-tay-duong', 'Cuộc Chiến Đại Tây Dương', 'The Rebels Of PT-218', 'https://phimimg.com/upload/vod/20231212-1/2017371c0ec049a145917a553dc14abe.jpg', 'https://phimimg.com/upload/vod/20231212-1/c7a884e0f2752911d0f2811609481b31.jpg', '<p>The Rebels Of PT-218 (2021) lấy bối cảnh những năm máu lửa nhất của chiến tranh thế giới thứ 2. Lúc này Đại Tây Dương trở thành chiến trường ác liệt, nơi quân đội Đức bắt đầu bành trướng thế lực đối đầu với các cường quốc khác. Một tàu chiến bắn lôi của Mỹ đã gia nhập vào cuộc chiến này, sẵn sàng nghênh đón từng đợt tấn công của chiến hạm phe Đức.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eric Roberts","avatar":""},{"name":"William Baldwin","avatar":""},{"name":"Geoff Meed","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324324);
