INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-bien-thanh-em', 'Một Ngày Biến Thành Em', 'The Day Of Becoming You', 'https://phimimg.com/upload/vod/20231219-1/b004257a1fca3111f38c368df8dc1669.jpg', 'https://phimimg.com/upload/vod/20231219-1/89fcc06eeff6dfc913b5aef16fa61118.jpg', '<p>Trong phim Một Ngày Biến Thành Em, Trương Tân Thành sẽ sắm vai nam thần tượng Chu Dập ngoài lạnh trong ấm. Lương Khiết vào vai cô phóng viên lạc quan hướng ngoại Dư Thanh Thanh rất giỏi quan sát phân tích, tâm tư tỉ mỉ. Họ có cùng sinh nhật và vô tình hoán đổi thân xác cho nhau. Cũng kể từ đó, vô vàn tình huống hài hước xảy ra khiến cặp đôi dần dần nảy sinh tình cảm.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Tân Thành","avatar":""},{"name":"Lương Khiết","avatar":""},{"name":"Triệu Chí Vỹ","avatar":""},{"name":"Vương Vi","avatar":""},{"name":"Châu Sỹ Nguyên","avatar":""},{"name":"Tô Huân Luân","avatar":""},{"name":"An Qua","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324324);
