INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-xom-ke-ben', 'Hàng Xóm Kế Bên', 'Best Friend (Next Door Neighbor)', 'https://phimimg.com/upload/vod/20231211-1/b03dfed9eb63b83af5a44fa570629fbe.jpg', 'https://phimimg.com/upload/vod/20231211-1/e0778db1a963f8913f9b1c0ee04d0ffc.jpg', '<p>Hàng Xóm Kế Bên - Best Friend (Next Door Neighbor) kể về một đội nghe trộm do Yoo Dae Kwon (Jung Woo) đứng đầu nhận chỉ thị của chính phủ theo dõi ứng cử viên tổng thống Lee Ui Sik (Oh Dal Soo) và các thành viên gia đình ông sau khi hồi hương từ nước ngoài. Các thành viên của đội nghe trộm chuyển đến nhà bên cạnh Lee Ui Sik, giả làm hàng xóm và bắt đầu hoạt động giám sát. Sau đó, bí mật từ từ lộ ra, Yoo Dae Kwon dần bị tính cách của Lee Ui Sik chinh phục và quay sang ủng hộ ông, giúp Lee Ui Sik lật ngược tình thế bất lợi trong cuộc tổng tuyển cử.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Dal-su Oh","avatar":""},{"name":"Woo Jung","avatar":""},{"name":"Seung-Hyeon Ji","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324324);
