INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-da-roi-yeu', 'Ăn Đã Rồi Yêu', 'Falling In Love', 'https://phimimg.com/upload/vod/20231211-1/7a96ae6eb872b27a3769cb8539c1b0de.jpg', 'https://phimimg.com/upload/vod/20231211-1/cb187aad8662e828fe96c85890e7d55b.jpg', '<p>[Ăn Đã Rồi Yêu] là một câu chuyện tình yêu ngọt ngào và ấm áp về sự trưởng thành của tuổi trẻ. Phim kể về câu chuyện của Trì Tiểu Niệm, một cô gái bình thường nhưng lại có tài nấu ăn bị bạn trai đá vì sự nhàm chán và tầm thường, khiến cô rơi vào trạng thái thiếu tự tin. Thế rồi, cô gặp lại chàng thanh mai trúc mã thời thơ ấu, sự xuất hiện đúng lúc của cậu đã giúp cô ấy thoát ra khỏi ám ảnh của tình yêu tan vỡ, giúp cô lấy lại sự tự tin và trở thành phiên bản tốt hơn của bản thân.&nbsp;</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Chân Ninh","avatar":""},{"name":"Hồng Nhất Khả","avatar":""},{"name":"Ngô Hách Luân","avatar":""},{"name":"Tào Y Nặc","avatar":""},{"name":"Hàn Hân Dư","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324324);
