INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mao-son', 'Mao Sơn', 'Maoshan', 'https://phimimg.com/upload/vod/20231211-1/cc9a00465112fce2b389789a0bcd8a10.jpg', 'https://phimimg.com/upload/vod/20231211-1/ce2c26ed34ae22d2c8d8a7a44866f468.jpg', '<p>Âm Thủ Nhất từ nhỏ đến lớn luôn ước ao trở thành anh hùng Mao Sơn, nhưng cha mẹ cậu chỉ mong cậu có một cuộc đời bình an. Cậu đã lén người nhà tìm đến đại lễ tuyển chọn nhân tài của Cửu Long chân nhân ở Mao Sơn, bất ngờ giành chiến thắng và gánh vác trách nhiệm giải cứu Mao Sơn! Lúc này kẻ phản bội Mao Sơn là Lạc Huyễn Chân lại tiếp tục gây hấn, liệu Âm Thủ Nhất có bảo vệ được Mao Sơn hay không?</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Natas Asoka","avatar":""},{"name":"Tiền Tiểu Hào","avatar":""},{"name":"Zhang Dong","avatar":""},{"name":"Zhang Chun Zhong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324325);
