INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('black-friday', 'Black Friday', 'Black Friday', 'https://phimimg.com/upload/vod/20240103-1/c4870a93ee08ddbdc7714257acf469f7.jpg', 'https://phimimg.com/upload/vod/20240103-1/c8323f5a4069a991c072c9f88c2d8784.jpg', '<p>Vào đêm Lễ Tạ ơn, một nhóm nhân viên cửa hàng đồ chơi bất mãn đã đến nơi làm việc để mở cửa hàng vào nửa đêm cho ngày mua sắm bận rộn nhất trong năm. Trong khi đó, một ký sinh trùng ngoài hành tinh đâm vào trái đất trong một thiên thạch. Nhóm Misfits này được dẫn dắt bởi người quản lý cửa hàng Jonathan và nhân viên lâu năm Ken sớm thấy mình chiến đấu chống lại đám người mua sắm kỳ nghỉ đã bị biến thành những sinh vật quái dị Hellbent trên một cơn thịnh nộ giết người trên Thứ Sáu Đen.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324325);
