INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('petrovs-flu', 'Petrov''s Flu', 'Petrov''s Flu', 'https://phimimg.com/upload/vod/20231211-1/06e086bcae1a9d102dbdc4cbe53ce3a2.jpg', 'https://phimimg.com/upload/vod/20231211-1/f2d21e002505d114736f3a14ecc46dc2.jpg', '<p>Một ngày trong cuộc đời của một nghệ sĩ truyện tranh và gia đình ở Nga hậu Xô Viết. Trong khi bị cúm, Petrov được mang theo bởi người bạn Igor trên một chuyến đi dài, trôi dạt vào và ra khỏi sự tưởng tượng và thực tế.</p>', 'Full', 1, 'single', 'completed', 18, 2021, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324325);
