INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-bip-cuoc-doi', 'Trò Bịp Cuộc Đời', 'Ley Luang', 'https://phimimg.com/upload/vod/20231219-1/d3260a416722ed00182922a0cd15fbfc.jpg', 'https://phimimg.com/upload/vod/20231219-1/5dd6f460b420254d1105b8ee0561671e.jpg', '<p>Nội dung bộ phim Trò Bịp Cuộc Đời (Life Coach, Ley Luang) vietsub xoay quanh Ailada - một cô gái siêng năng, làm nghề bán hàng online. Cô sống cùng với bạn trai và là người duy nhất gánh vác mọi chi phí sinh hoạt của hai người. Vì vậy cuộc sống của cô rất khó khăn. Trong lúc vô cùng chán nản, Ailada đã tìm đến sự giúp đỡ của Venus - huấn luyện viên cuộc sống xinh đẹp tài giỏi, người đứng sau thành công của nhiều mô hình kinh doanh online. Liệu với sự giúp đỡ của Venus, Ailada có thực hiện được ước mơ về một cuộc sống ổn định?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Pooklook Fonthip Watcharatrakul","avatar":""},{"name":"Bright Norraphat Vilaiphan","avatar":""},{"name":"Cheer Thikumporn Rittapinun","avatar":""},{"name":"Jes Jespipat Tilapornputt","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324325);
