INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-chung-minh-la-nhat', 'Con Chúng Mình Là Nhất', 'Plan ''B''', 'https://phimimg.com/upload/vod/20231219-1/2f8be6fec12c4e25cc98eae32714e880.jpg', 'https://phimimg.com/upload/vod/20231219-1/62fb5d074d2253628a2cd77fd047c093.jpg', '<p>Dù còn trẻ, nhưng Khang Nhã Du đã an phận làm người phụ nữ của gia đình để chồng Du Tại Sơn yên tâm làm việc ngoài xã hội. Tuy nhiên, Sơn lại cảm thấy không hề thoải mái khi hai vợ chồng phải sống chung nhà với ba mẹ vợ. Bên cạnh đó, mối quan hệ căng thẳng của hai bên gia đình vô tình đẩy Sơn và Du vào tình thế tiến thoái lưỡng nan.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 13, 2021, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Mã Quốc Minh","avatar":""},{"name":"Sầm Lệ Hương","avatar":""},{"name":"Thương Thiên Nga","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324325);
