INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-bang-truyen-thuyet', 'Cái Bang Truyền Thuyết', 'Other People’s Lives', 'https://phimimg.com/upload/vod/20231211-1/369cbcdd7dfe7ca1721e7d9cf808cf80.jpg', 'https://phimimg.com/upload/vod/20231211-1/0a19b3054bafe19cb21e4baa956d7a57.jpg', '<p>Cái Bang Truyền Thuyết - Other People’s Lives kể về Phú Giang ốm yếu từ nhỏ, bị cha bắt đi luyện võ, tại xứ sở sương khói và hoa liễu, chàng đã lỡ tay giết chết hoàng tử bé để cứu bạn mình là Ngọc Tân và bị kết án tử hình. Phú Tướng quân nhờ sự giúp đỡ của Hồng bang chủ. Hồng bang chủ bị bắt thay Phú Giang trong tù, Phú Giang ra ngoài, định chạy trốn nhưng Ngọc Tân chặn lại, và bất đắc dĩ Phú Giang phải làm bang chủ để hóa giải hiểu lầm và cũng để bảo vệ Phú gia. Với sự thông minh và khả năng thiên bẩm của mình, bang chủ ngày đêm luyện đả cẩu bổng pháp để bảo vệ cái bang. Cái bang bị phái bạch đà tấn công, liệu rằng Dương tướng quân có đến ứng cứu được cho đệ tử Phú Giang của mình hay không?</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Fan New","avatar":""},{"name":"Huang Jian","avatar":""},{"name":"Zhang Tong","avatar":""},{"name":"Zhaoqiu Sheng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324325);
