INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mong-giau-sang', 'Giấc Mộng Giàu Sang', 'Dreams Of Getting Rich', 'https://phimimg.com/upload/vod/20231211-1/52f4887eb915db8fd68cecf3f0fe466d.jpg', 'https://phimimg.com/upload/vod/20231211-1/61f87f12c9784a0155b30a50eb3dae47.jpg', '<p>Cốt truyện kéo dài gần 30 năm, kể về câu chuyện của cậu bé nghèo vùng Đông Bắc Tiểu Bảo theo Anh Hai cùng làng đến Thâm Quyến làm giàu, hai người đàn ông quyết tâm kiếm tiền lập nghiệp. Sự xuất hiện bất ngờ của cậu bé bị bỏ rơi Thiên Ý đã làm thay đổi cuộc đời họ. Cả hai trở thành cha bất đắc dĩ và gặp Mã Lộ, một phụ nữ lạnh lùng lớn tuổi. Từ đây bắt đầu cuộc đời đầy niềm vui nước mắt của họ.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Mã Lộ","avatar":""},{"name":"Sa Dật","avatar":""},{"name":"Tống Tiểu Bảo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324325);
