INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-thien-ky-an', 'Nghịch Thiên Kỳ Án', 'Sinister Beings', 'https://phimimg.com/upload/vod/20231219-1/27e92c1b1aec8d9b3ab6f6a23f79d351.jpg', 'https://phimimg.com/upload/vod/20231219-1/1aafc318bddfa483e79ceda0a6f63379.jpg', '<p>Với tư chất năng động, anh dũng và giỏi võ, từ lâu, Hứa Tuấn Sâm (do Trần Triển Bằng đóng) ước mơ được gia nhập đội Phi Hổ. Tuy nhiên, cơ duyên lại đưa đẩy anh trở thành trinh thám, làm việc cho Cục chống Xã hội đen và Tội phạm có tổ chức, gọi tắt là O Ký. Bằng trí thông minh và khả năng quan sát nhạy bén, Sâm đã phá nhiều vụ án ly kỳ. Nhờ đó, anh được cấp trên và đồng nghiệp rất mực yêu quý, ngưỡng mộ. Trong O Ký cũng có một trinh thám khác tài ba không kém. Đó là tiền bối của Sâm, Thẩm Vi Lực (do Huỳnh Trí Hiền đóng). Thâm niên xử lý các vụ án khác nhau giúp Lực ngày càng dày dặn kinh nghiệm, luôn nhìn nhận mọi vấn đề với thái độ khách quan nhất. Sâm và Lực với hai lối phá án đối lập, vừa là đồng đội, ...</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 13, 2021, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Tiền Tiểu Hào","avatar":""},{"name":"Huỳnh Trí Hiền","avatar":""},{"name":"Lâm Hạ Vy","avatar":""},{"name":"Trần Triển Bằng","avatar":""},{"name":"Lý Quốc Lân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324325);
