INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-mat-thu-3', 'Con Mắt Thứ 3', 'I See Dead People', 'https://phimimg.com/upload/vod/20231219-1/bb2c8d13122ec9360250b8eea43cd23b.jpg', 'https://phimimg.com/upload/vod/20231219-1/6196193f927cb9ead4eacea573728d9b.jpg', '<p>Con Mắt Thứ Ba/Huệ Nhãn - I See Dead People xoay quanh câu chuyện về chàng trai kỳ lạ Trikal. Anh sở hữu con mắt thứ ba, có khả năng nhìn thấy những hồn ma. Nhưng vì có khả năng đặc biệt này nên Trikal đã gặp vô số nguy hiểm, phải may mắn lắm mới sống sót được. Một lần tình cờ, Trikal gặp lại người bạn thân của mình là cô nàng xinh đẹp Pum. Trikal cùng với Pum đi đến Bangkok để quay ngược thời gian về quá khứ, tìm hiểu sự thật tình yêu của hai người.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 11, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Mew Nittha Jirayungyurn","avatar":""},{"name":"James Ma","avatar":""},{"name":"Pat Napapa Thantrakul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324325);
