INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tri-thuy-uy-ho-son', 'Trí Thủy Uy Hổ Sơn', 'The Taking Of Tiger Moutain', 'https://phimimg.com/upload/vod/20231231-1/3cb49c4782b6a97784b4af966e67aa22.jpg', 'https://phimimg.com/upload/vod/20231231-1/bad7072c3db446b4ca0ab74e83ed2edd.jpg', '<p>Mùa đông năm 1947, phân đội 203 thuộc liên quân Dân chủ Đông Bắc dưới sự chỉ huy của thủ trưởng Thiếu Kiếm Ba (Lâm Canh Tân đóng), tiếp nhận mệnh lệnh của thượng cấp bảo vệ an toàn cho dân chúng khỏi nạn cướp bóc hoành hành trên cánh đồng tuyết Lâm Hải.Trinh sát viên Dương Tử Vinh (Trương Hàm Dư đóng) và nhân viên y tế Bạch Như (Đồng Lệ Á đóng) gấp rút tiếp viện cho tiền tuyến. Để triệt phá hoàn toàn thế lực của thổ phỉ, Dương Tử Vinh khăng khăng đề nghị cải trang trà trộn vào hang ổ của thổ phỉ: núi Uy Hổ.&nbsp;</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lương Gia Huy","avatar":""},{"name":"Trương Hàm Dư","avatar":""},{"name":"Lâm Canh Tân","avatar":""},{"name":"Hàn Canh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324325);
