INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-tinh-yeu-con-nho', 'Một Tình Yêu Còn Nhớ', 'I Missed You', 'https://phimimg.com/upload/vod/20231211-1/d381f838d536cb8dcab46b0d68722134.jpg', 'https://phimimg.com/upload/vod/20231211-1/fb808c1cd1841fee51229eacf3e01fe3.jpg', '<p>Một Tình Yêu Còn Nhớ - I Missed You (2021) theo chân Quách Cần Cần cô gái cuồng công việc ít khi bày tỏ cảm xúc thật của bản thân. Một ngày nọ Quách Cần Cần được phân công phát triển trò chơi chủ đề tình yêu, khi ấy Cần Cần mới có thời gian suy ngẫm và nhìn lại các mối quan hệ xung quanh mình. Đặc biệt hơn Cần Cần chú ý đến hai người đàn ông mà trước đây cô từng chặn trên mạng xã hội. Giờ đây không chỉ cần hoàn thành công việc mà Cần Cần phải đối diện với cảm xúc thật của bản thân sau nhiều năm.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kang Ren Wu","avatar":""},{"name":"Eve Ai","avatar":""},{"name":"Meng-Po Fu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324325);
