INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dap-gio-re-song', 'Đạp Gió Rẽ Sóng', 'The Warlord Of The Sea', 'https://phimimg.com/upload/vod/20231211-1/cefc10ba9bf7553acf87cfac8db0ffac.jpg', 'https://phimimg.com/upload/vod/20231211-1/537c5fb62ef3d4df5805d115da4622f6.jpg', '<p>Thành Vô Cực, lục địa duy nhất trên trái đất tương lại, bất ngờ bị hạm đội cướp biển tập kích mà vật tư ở nơi đây ngày càng thiếu hụt. Cảnh sát biển La Lịch dẫn đội thám hiểm xuất phát đi tìm lục địa mới. Họ được nữ cướp biển Hải Cơ trợ giúp khi trải qua vùng biển nguy hiểm và lần lượt tàn sát nhau với quái vật biển khổng lồ và vua cướp biển. Sau đó, họ lên đường tìm lục địa mới tiếp.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Mei Tong","avatar":""},{"name":"Vin","avatar":""},{"name":"Zheng Yi Bin","avatar":""},{"name":"Shao Shuai","avatar":""},{"name":"Xue Yi Lun","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324325);
