INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-nang-wanthong', 'Chuyện Nàng Wanthong', 'Wanthong', 'https://phimimg.com/upload/vod/20231208-1/c0532c5be8b333611340289fe4eb117e.jpg', 'https://phimimg.com/upload/vod/20231208-1/abe34f42afb8ef63995c55fd76c77bf6.jpg', '<p>Chuyện Nàng Wanthong - Wanthong, xoay quanh cuộc đời của nàng Wanthong xinh đẹp thông minh. Mặc dù tài trí hơn người nhưng Wanthong lại dây dưa vào mối quan hệ rắc rối với hai người đàn ông. Cũng chính từ đây cuộc đời Wanthong hoàn toàn thay đổi, bi kịch nhanh chóng kéo đến.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 11, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Pong Nawat Kulrattanarak","avatar":""},{"name":"Krit Shahkrit Yamnam","avatar":""},{"name":"Mai Davika Hoorne","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324325);
