INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-dem-truong-halloween', 'Người Dơi: Đêm Trường Halloween', 'Batman: The Long Halloween', 'https://phimimg.com/upload/vod/20231211-1/92d54f6e90d1b8114c1360c40f335d9d.jpg', 'https://phimimg.com/upload/vod/20231211-1/a12cd99a9a696aa8e1926ce3965a65b7.jpg', '<p>Đêm trường Halloween là một phần khác của Vũ trụ Hoạt hình DC, dựa trên những câu chuyện phong phú về lịch sử của Người Dơi. Là phần tiếp theo của Batman: Year One, đây là một Bat-man trong quá trình chuyển đổi. Một vụ giết người tàn bạo vào dịp Halloween đã thúc đẩy người cảnh giác trẻ tuổi của Gotham, Người dơi, lập hiệp ước với Cảnh sát trưởng James Gordan và Biện lý quận Harvey Dent để hạ gục The Roman, người đứng đầu Gia đình tội phạm Falcone khét tiếng và quyền lực. Sau khi nhiều cái chết hơn xảy ra vào Lễ Tạ ơn và Giáng sinh, rõ ràng là họ đang đối phó với một kẻ giết người hàng loạt – danh tính của kẻ này ngày càng khó xác định với những manh mối mâu thuẫn.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jensen Ackles","avatar":""},{"name":"Josh Duhamel","avatar":""},{"name":"Naya Rivera","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324325);
