INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-trip', 'The Trip', 'I Onde Dager', 'https://phimimg.com/upload/vod/20231210-1/48dc51b301aa9d893b0fc8c6277a5386.jpg', 'https://phimimg.com/upload/vod/20231210-1/d4772a9112cba0324012951903c95c34.jpg', '<p>Một cặp vợ chồng rối loạn chức năng đi đến một căn nhà gỗ hẻo lánh để kết nối lại nhưng mỗi người đều có ý định giết người kia. Trước khi họ có thể thực hiện kế hoạch của mình, những vị khách bất ngờ đã đến và họ phải đối mặt với mối nguy hiểm lớn hơn.</p>', 'Full', 1, 'single', 'completed', 21, 2021, 'Vietsub', 'HD', 'Na Uy', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324325);
