INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('blackpink-the-movie', 'Blackpink: The Movie', 'Blackpink: The Movie', 'https://phimimg.com/upload/vod/20231210-1/2efd924d640fba48859c0262a1027e41.jpg', 'https://phimimg.com/upload/vod/20231210-1/0e7fca39b6191436a8dbcc22111d137f.jpg', '<p>Blackpink Bộ phim là một bộ phim để kỷ niệm 5 năm ra mắt của nhóm K-POP K-POP được thế giới Blackpink. Trong bộ phim này, bạn có thể gặp gỡ năm năm ký ức của Blackpink chia sẻ với người hâm mộ trên toàn thế giới, các cuộc phỏng vấn đặc biệt không được tiết lộ, những khoảnh khắc sáng chói nhất và các giai đoạn đặc biệt của Blackpink của chương trình (2021), trong khu vực của bạn (2018) , một tá các bài hát hit nhiều hơn từ Blackpink đã được chỉnh sửa lại và được tối ưu hóa cho môi trường sân khấu.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324325);
