INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-hoang-bi-tu', 'Mộ Hoàng Bì Tử', 'The Tomb Of Weasel', 'https://phimimg.com/upload/vod/20231210-1/e023944716a2659649c1e1531c75789d.jpg', 'https://phimimg.com/upload/vod/20231210-1/567bc1e669579e26ea115778c7308cc9.jpg', '<p>Để giải cứu cô thôn nữ Họa My bị bệnh, Hồ Bát Nhất cùng một số thanh niên trai tráng ở miền quê Đông Bắc, đã liên kết với cùng với chú thợ săn họ Triệu tìm đến hang động của người gấu tuyết trong rừng để tìm thuốc giải. Không ngờ đột nhiên lại bị người tuyết tấn công, buộc phải trốn vào trong khu nhà Hoàng Bì dưới lòng đất, từ đây bao nhiêu sự kiện ly kỳ trong khu nhà Hoàng Bì này liên tiếp xảy đến, từ ảo ảnh trùng trùng. Hồ Bát nhất và đám người đi cùng đã phá giải được những quỷ kế mê tín, nhổ cỏ tận gốc, tìm ra chân tướng kẻ đứng sau mọi chuyện, cuối cùng đã giải cứu được dân làng thoát khỏi địa phủ.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhou Cheng Ao","avatar":""},{"name":"FLASH","avatar":""},{"name":"Sun Ya Li","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324325);
