INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-tong-huyet-chien-su-tu-lau', 'Võ Tòng Huyết Chiến Sư Tử Lâu', 'The Legend Of Justice WuSong', 'https://phimimg.com/upload/vod/20231209-1/d8368e73eacd851794b8d2cc81f98725.jpg', 'https://phimimg.com/upload/vod/20231209-1/0e420cdc69859bbb16983668040f1ddc.jpg', '<p>Tây Môn Khánh say mê sắc đẹp của Phan Kim Liên, dụ dỗ Vương bà giúp hắn chiếm được Phan Kim Liên. Khi bắt kẻ gian phu dâm phụ, Võ Đại Lang bị đạp ngã đến hộc máu, không gượng dậy nổi. Dưới sự xúi giục của Vương bà và Tây Môn Khánh, Phan Kim Liên đã bắt tay với bọn họ đầu độc hại chết Võ Đại Lang. Võ Tòng báo thù, giết chết Phan Kim Liên, dùng máu tế bái huynh trưởng, đồng thời tự tay giết kẻ thù, lấy đầu Tây Môn Khánh.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ding Hai Feng","avatar":""},{"name":"潘長江","avatar":""},{"name":"Crystal","avatar":""},{"name":"Liu Zheng Fei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324325);
