INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-rong-nhat-kien-khuynh-tam', 'Cô Dâu Rồng: Nhất Kiến Khuynh Tâm', 'Dragon Bride', 'https://phimimg.com/upload/vod/20231209-1/0355c719b6a61c555271d1037b518722.jpg', 'https://phimimg.com/upload/vod/20231209-1/73dc1bc299b8165c7bbff8e43550531a.jpg', '<p>Cô gái rồng Tĩnh Linh một mình đi tìm ân nhân để trả ơn cứu mạng nhưng lại nhận nhầm người bắt rồng Diệp Nhân là ân nhân của mình. May mắn thay, Lăng Hạo Thần đã ra tay cứu giúp cô khỏi cuộc tàn sát bộ tộc rồng. Sau khi trải qua nhiều nguy hiểm, Tịnh Linh cuối cùng cũng nhận ra Hạo Thần mới là ân nhân thật sự của mình, hai người cũng nhận ra tình cảm của mình dành cho đối phương.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324325);
