INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gogos', 'The Go-Go''s', 'The Go-Go''s', 'https://phimimg.com/upload/vod/20231209-1/ad8a1ec6143b14ef7c9a231d3ec2e10d.jpg', 'https://phimimg.com/upload/vod/20231209-1/d22ef4736773e95a233a94f8bd9e3331.jpg', '<p>Là ban nhạc bán bạch kim, toàn cầu đầu tiên chơi nhạc cụ của riêng họ, hãy viết các bài hát của riêng họ và tăng vọt lên vị trí thứ 1 trên bảng xếp hạng album, Go-Go là ban nhạc rock nữ thành công nhất mọi thời đại. Bị củng cố bởi những lời chứng nhận thẳng thắn từ quá khứ và hiện tại của Go-Go Go-Go, việc ghi lại sự nổi tiếng của sự nổi tiếng của một ban nhạc được sinh ra từ cảnh La Punk không chỉ bị bắt mà không chỉ bị bắt mà không chỉ bị bắt mà không chỉ bị bắt mà không chỉ bị bắt mà đã bị bắt mà không chỉ bị bắt mà đã bị bắt mà không chỉ bị bắt mà đã chiếm được</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324325);
