INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oxygen', 'Oxygen', 'Oxygen', 'https://phimimg.com/upload/vod/20231209-1/3161d4a8d9469b9fe79c2b85017721da.jpg', 'https://phimimg.com/upload/vod/20231209-1/a40662266c9c0e12bf4201e666c3d1b0.jpg', '<p>Sau khi tỉnh dậy trong một khoang đông lạnh, Liz chiến đấu để tồn tại và cố nhớ ra mình là ai trước khi oxy cạn kiệt.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Mélanie Laurent","avatar":""},{"name":"Mathieu Amalric","avatar":""},{"name":"Malik Zidi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324325);
