INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gunjou-senki', 'GUNJOU SENKI', 'Brave: Gunjyo Senki', 'https://phimimg.com/upload/vod/20231209-1/9f76336a1efabe794e4a96c09a606175.jpg', 'https://phimimg.com/upload/vod/20231209-1/5eef6990bff1c86ebda8272685704dea.jpg', '<p>Gunjou Senki xoay quanh một nhóm học sinh cấp 3 tại một trường chuyên thể thao danh tiếng. Một ngày trời mưa to, cả trường bị sét đánh và xuyên không trở về thời Sengoku, đúng lúc thời này đang diễn ra trận chiến Okehazama. Nhóm học sinh này đành phải cố gắng chiến đấu để có thể bảo vệ những người bạn của mình! Dựa theo manga cùng tên phát hành từ năm 2013 đến 2017 trên tuần san Young Jump.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hirona Yamazaki","avatar":""},{"name":"Mackenyu","avatar":""},{"name":"Haruma Miura","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324325);
