INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lego-star-wars-terrifying-tales', 'Lego Star Wars Terrifying Tales', 'Lego Star Wars Terrifying Tales', 'https://phimimg.com/upload/vod/20231209-1/79debcdf451ababcf6b63176482562fb.jpg', 'https://phimimg.com/upload/vod/20231209-1/22c17d2fa95ee5924dfd983214b9fd3d.jpg', '<p>Sau các sự kiện của Star Wars: Tập IX - Sự trỗi dậy của Skywalker (2019), Poe Dameron và BB-8 phải thực hiện hạ cánh khẩn cấp trên hành tinh núi lửa Mustafar, nơi họ gặp người tham lam và liên kết Graballa the Hutt. Ông chủ tội phạm đã mua lâu đài Darth Vader và đang cải tạo nó vào khách sạn sang trọng toàn diện đầu tiên của Galaxy. Trong khi chờ đợi cánh X được sửa chữa, Poe, BB-8, Graballa và Dean (một cậu bé ngoan ngoãn và can đảm, làm việc như một thợ máy của Graballa) liên doanh sâu vào lâu đài bí ẩn với người hầu trung thành của Vader, Vaneé.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324325);
