INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-duong-chi-thanh', 'Hải Dương Chi Thành', 'One Boat One World (Phát Song Song)', 'https://phimimg.com/upload/vod/20231207-1/e17857716d845710797aa046f0f62fef.jpg', 'https://phimimg.com/upload/vod/20231207-1/d3f5878ad670acfde2978679e6a74356.jpg', '<p>Phim tập trung khai thác câu chuyện về ngành du lịch biển, bối cảnh phim chủ yếu diễn ra trên du thuyền sang trọng - nơi mà sĩ quan hàng hải Đinh Khải (Trương Hàn) đang công tác. Trong quá trình làm việc, Đinh Hải gặp gỡ và đem lòng yêu nữ hướng dẫn viên hiền lành, thẳng thắn (Vương Lệ Khôn đóng). Tuy nhiên, mối lương duyên của 2 người bị ngăn cản bởi khá nhiều khó khăn. Thông qua chuyện yêu đương của 2 nhân vật chính, thông điệp về tình bạn, tình yêu, gia đình cũng được gửi gắm và truyền tải.</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 9, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Lệ Khôn","avatar":""},{"name":"Trương Hàn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324325);
