INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-thanh-dieu-ky', 'Âm Thanh Diệu Kỳ', 'The Man''s Voice', 'https://phimimg.com/upload/vod/20231207-1/48e2d3b8260dbcdba6de8bc9b6bd3ee9.jpg', 'https://phimimg.com/upload/vod/20231207-1/ade8d926f8e88cab5e26e761dd9508d6.jpg', '<p>Một bộ phim hài lãng mạn giả tưởng về một nhân viên bán thời gian ở cửa hàng tiện lợi đang tìm kiếm một công việc toàn thời gian, một phi công đẹp trai và con mèo cưng của anh ta. Bộ phim kể về câu chuyện diễn ra khi nữ chính nhút nhát có được khả năng giao tiếp với một chú mèo mà cô tình cờ gặp và đi đến một thỏa thuận với chú mèo nóng tính đó. Baek Tae Hwa là chủ nhân của chú mèo và phi công phó của một hãng hàng không. Anh có xuất thân tốt và vẻ ngoài điển trai khiến bất cứ ai cũng phải xiêu lòng. Với tính cách ngọt ngào tự nhiên, Baek Tae Hwa thường khiến phụ nữ phải rơi lệ dù không cố ý. Khách sạn dành cho thú cưng mà anh hay dùng đột ngột đóng cửa trước chuyến bay một ngày, vì vậy cuối cùng Baek Tae Hwa phải giao mèo cưng của mình cho một người phụ nữ. Go Mi Rim có xuất thân bình thường và bản tính lạc quan. Cô làm bán thời gian tại một cửa hàng tiện lợi trong khi tìm kiếm một công việc toàn thời gian. Go Mi Rim đồng ý chăm sóc chú mèo của người mà cô thầm thích, nhưng cô bắt đầu nghe thấy giọng nói của chú mèo sau khi bị sét đánh, tạo nên cốt truyện cho một chuyện tình thú vị nảy nở.</p>', 'Hoàn Tất (08/08)', 8, 'series', 'completed', 9, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324325);
