INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xu-so-dieu-ky-cua-willy', 'Xứ Sở Diệu Kỳ Của Willy', 'Willy''s Wonderland', 'https://phimimg.com/upload/vod/20231210-1/90e778953c5c5ed7f57c3e2184462288.jpg', 'https://phimimg.com/upload/vod/20231210-1/027c73ed4a7de18d51262d2f71ad827b.jpg', '<p>Một anh chàng lưu lạc bị lừa nhận công việc dọn dẹp cho một khu vui chơi bị bỏ hoang – Xứ sở Diệu kì của Willy. Những công việc tưởng như bình thường bỗng nhiên trở thành một cuộc chiến sống còn với những con quỷ đội lốt những cỗ máy nhân vật hoạt hình. Nắm đấm ruồi, người khổng lồ… và chỉ có một phe có được chiến thắng.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Emily Tosta","avatar":""},{"name":"Beth Grant","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324325);
