INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dieu-nho-nhat', 'Những Điều Nhỏ Nhặt', 'The Little Things', 'https://phimimg.com/upload/vod/20231208-1/11182b6133f68766ef63e618b11751e6.jpg', 'https://phimimg.com/upload/vod/20231208-1/7b2552537ec149d79dfa203048ef91a1.jpg', '<p>Deke (Denzel Washington), một quận Kern bị cháy, Ca phó cảnh sát trưởng đội ngũ Baxter (Rami Malek), một thám tử lasd crack, để kiếm một kẻ giết người hàng loạt. Mũi của Deke vì những điều nhỏ nhặt của người Viking chứng tỏ chính xác một cách kỳ lạ, nhưng sự sẵn lòng của anh ta để phá vỡ các quy tắc lôi kéo người Baxter trong một tình huống khó xử tan vỡ linh hồn. Trong khi đó, Deke phải vật lộn với một bí mật đen tối từ quá khứ của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Rami Malek","avatar":""},{"name":"Jared Leto","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324325);
