INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-tuyet-diem', 'Hoa Tuyết Điểm', 'Snowdrop', 'https://phimimg.com/upload/vod/20231207-1/7004682e530dc0119e784f0b8d50d6d5.jpg', 'https://phimimg.com/upload/vod/20231207-1/4fc2599df7d866fc21e070ae54bc4d45.jpg', '<p>Sau một biến cố đau buồn, cô gái trẻ Yoo So Na tập trung vào công việc trồng hoa trong vườn Snow Drop của mình. Tuy nhiên, cô bị người cha góa ép buộc phải quay lại trường trung học mới. Cô ấy rất đau khổ cho đến khi gặp Oh Hae Gi, một người mẫu trẻ. Họ dễ dàng hiểu nhau vì cả hai điều có một quá khứ bi thảm. Trái với mong muốn của gia đình, họ yêu nhau. Tuy nhiên, gia đình của họ có những bí mật đen tối. Trên thực tế, anh trai của Hae Gi đã bắt cóc So Na, lúc đó mới 12 tuổi và gây ra cái chết của mẹ cô. Bạn của So Na, Ha Da, phải lòng Ko Mo, người tình cờ là anh trai của Hae Gi, người mà anh ấy tin là một cô gái. So Na buộc phải kết hôn với Kwon Hwi Rin, cháu trai của bạn ông Yoo.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Hae‑in","avatar":""},{"name":"Jisoo","avatar":""},{"name":"Kim Hye‑yoon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324325);
