INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phia-sau-khung-cua-so', 'Phía Sau Khung Cửa Sổ', 'Show Window: Queen''s House', 'https://phimimg.com/upload/vod/20231207-1/56e6f474dc59525253fa45110417a7ef.jpg', 'https://phimimg.com/upload/vod/20231207-1/912289c79ed618d837ff764c26636c7b.jpg', '<p>Han Sun Joo là một phụ nữ thông minh, xinh đẹp lại giàu có. Cô còn là người mẹ, người vợ tuyệt vời. Tuy nhiên, rạn nứt bắt đầu xuất hiện trong gia đình vốn đã hoàn hảo của Sun Joo, khi cô vô tình ủng hộ việc ngoại tình của một người phụ nữ khác mà không hề biết rằng người đó ngoại tình với chính chồng mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 18, 2021, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Yoon Ah","avatar":""},{"name":"Lee Sung Jae","avatar":""},{"name":"Jeon So Min","avatar":""},{"name":"Chansung","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324325);
