INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-bat-kha-khang-cua-thuat-si-orphen', 'Hành Trình Bất Khả Kháng Của Thuật Sĩ Orphen', 'Majutsushi Orphen Hagure Tabi: Kimluck-hen', 'https://phimimg.com/upload/vod/20231207-1/a261dd0d71486b838b01a5c567ea2c27.jpg', 'https://phimimg.com/upload/vod/20231207-1/5d41b296e6c3d47c86e841c2f6c5698d.jpg', '<p>Nghe theo những lời mà chị dâu Ashali để lại, nhóm Ou Fei tiến đến Kimrak, nơi xảy ra xung đột gay gắt với pháp sư. Khi anh nghe thấy một tiếng hét và lao vào, anh gặp Mechen, một nữ kiếm sĩ dũng cảm chiến đấu chống lại kẻ thù trong một ngọn núi có vô số xác chết. Người chờ đợi những Ou Fei tiêu diệt kẻ thù và cuối cùng đến được với Kimrak là những Người hướng dẫn tử thần, những người chịu trách nhiệm cho vụ ám sát pháp sư do Kuo đứng đầu. Sự thật của thiên thần và ác quỷ mà Ou Fei đến cuối cùng là gì? Ý nghĩa thực sự của lời mời Ashali đến nơi này là gì? Nhiều suy đoán khác nhau lẫn lộn, và một câu chuyện tuyệt vời bắt đầu!</p>', 'Full', 11, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324325);
