INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dang-cap-thuong-luu', 'Đẳng Cấp Thượng Lưu', 'High Class', 'https://phimimg.com/upload/vod/20231207-1/279bb8afdc67f9caa8156d628e217210.jpg', 'https://phimimg.com/upload/vod/20231207-1/65dacfd3bfc1a83909acda8b96982417.jpg', '<p>Đẳng Cấp Thượng Lưu - High Class là bộ phim truyền hình hồi hộp bí ẩn về những lời nói dối nguy hiểm và đạo đức giả ẩn đằng sau cuộc sống hoàn hảo của những người phụ nữ sống trong 0,1% hàng đầu của xã hội. Song Yeo Wool, người mất tất cả khi bị buộc tội giết chồng. Nam Ji Sun, ong chúa trong số các bà mẹ tại trường quốc tế nơi con trai Song Yeo Wool theo học. Danny Oh, một giáo viên tại trường và là một cựu vận động viên khúc côn cầu trên băng. Hwang Na Yoon, một bà mẹ đơn thân là người duy nhất thân thiện với Song Yeo Wool. Cha Do Young, một cựu nữ diễn viên hàng đầu luôn theo dõi Nam Ji Sun vì cô ấy muốn trở lại ánh đèn sân khấu.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Se-Jin","avatar":""},{"name":"Kim Ji Soo","avatar":""},{"name":"Ha Joon","avatar":""},{"name":"Jo Yeo Jung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324325);
