INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-nhau-hit-tho-sau', 'Cùng Nhau Hít Thở Sâu', 'Breath of Destiny', 'https://phimimg.com/upload/vod/20231207-1/7f8b9d991dcf3ac4c2fc4e17bc73d391.jpg', 'https://phimimg.com/upload/vod/20231207-1/c419da6c866572469efe1574c83f7a41.jpg', '<p>Một phân đội cứu viện y tế nhỏ của Trung Quốc đến một hòn đảo nhỏ ở Nam Thái Bình Dương thực hiện sứ mệnh nghề nghiệp. Ai ngờ họ vừa đến đã gặp phải thiên tai trăm năm mới có một lần, chính thức bắt đầu một cuộc hành động cứu trợ chạy đua với thời gian. Mà những người làm công tác y tế này hoàn toàn không ngờ tới rằng, họ không chỉ cần hoàn thành trọn vẹn nhiệm vụ cứu viện, mà cũng sắp vạch trần một âm mưu lớn trên hòn đảo nhỏ này.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 9, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Thích Vy","avatar":""},{"name":"Dương Hựu Ninh","avatar":""},{"name":"Trương Quân Ninh","avatar":""},{"name":"He Zheng Jun","avatar":""},{"name":"Tu Ling","avatar":""},{"name":"Chu Châu","avatar":""},{"name":"Cao Thánh Viễn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324325);
