INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('in-the-heights-giac-mo-new-york', 'In The Heights: Giấc Mơ New York', 'In The Heights', 'https://phimimg.com/upload/vod/20231208-1/4e13d8c10e542aa0a25117231e5c9aba.jpg', 'https://phimimg.com/upload/vod/20231208-1/d3b13898a582b4a429560c6308f947c6.jpg', '<p>Một phiên bản phim của vở nhạc kịch Broadway trong đó USNAVI, một chủ sở hữu Bodega New York thông cảm, cứu từng xu mỗi ngày khi anh tưởng tượng và hát về một cuộc sống tốt hơn.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324325);
