INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('in-the-heights-giac-mo-new-york', 'In The Heights: Giấc Mơ New York', 'In The Heights', 'in the heights: giấc mơ new york in the heights  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-ba-ho-doi-trang-thay-den', 'Đường Bá Hổ Đổi Trắng Thay Đen', 'The Story Of Tangbohu', 'https://phimimg.com/upload/vod/20231208-1/1227a03b34e649fa7ac7766ace909f99.jpg', 'https://phimimg.com/upload/vod/20231208-1/a1ee226252389062a207fda6ed903658.jpg', '<p>Đệ nhất tài tử Giang Nam Đường Bá Hổ vì sự ngưỡng mộ đối với thiếu nữ Đào Bảo nên đã vung tiền như nước trong đêm hoa khôi, nhưng lại bị một nam tử thần bí làm cho nhục nhã. Vì để trút giận, Đường Bá Hổ đã liên hợp với bạn tốt Chúc Chi Sơn đánh tên đó một trận. Nhưng sau khi xong việc lại bị cả kinh thành truy nã! Hoá ra nam tử thần bí bị đánh kia, chính là Hoàng thượng cải trang xuất cung! Vì muốn trốn khỏi sự truy bắt, Đường Bá Hổ dưới sự sắp xếp của kẻ thù truyền kiếp Tống An, bị ép đóng giả làm thái giám bên cạnh Hoàng đế, từ đây vô tình bị cuốn vào cuộc tạo phản… Đường Bá Hổ dưới sự giúp đỡ của bạn bè đã phá giải các nghi vấn và lật ngược thế cục!</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Suen","avatar":""},{"name":"Eric","avatar":""},{"name":"LawrenceNg","avatar":""},{"name":"Lawrence Ng Kai Wah","avatar":""},{"name":"Ng Kai Wah","avatar":""},{"name":"Gabriel Wong","avatar":""},{"name":"Ewong","avatar":""},{"name":"Canti Lau","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324325);
