INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('petite-maman', 'Petite Maman', 'Petite Maman', 'https://phimimg.com/upload/vod/20231208-1/6e9af9279b424fcdc07b4d70519937e8.jpg', 'https://phimimg.com/upload/vod/20231208-1/de0a805c9b91841de671c41ca4d1bbfd.jpg', '<p>Nelly vừa mất bà và giúp bố mẹ dọn dẹp nhà thời thơ ấu của mẹ. Cô khám phá ngôi nhà và những khu rừng xung quanh. Một ngày nọ, cô gặp một cô gái cùng tuổi xây dựng một ngôi nhà trên cây.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324325);
