INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chu', 'Bà Chủ', 'Queen Of Triads 2', 'https://phimimg.com/upload/vod/20231208-1/c9d869a5f5cacd98b1a98e60738b9b5b.jpg', 'https://phimimg.com/upload/vod/20231208-1/34a5c14b1979896f4d4341c2a7079c43.jpg', '<p>Hồng Kông những năm 70, người dân ở tầng lớp thấp sống rất khổ cực, cảnh sát Anh cấu kết với các lực lượng tội phạm, bao che các giao dịch phi pháp như mại dâm, cờ bạc, ma túy. Chị Thiết, bà chủ của nhà hàng Thiết Ký đã đứng ra bảo vệ những người dân bị áp bức. Sau khi Ủy ban độc lập chống tham nhũng Hồng Kông (ICAC) được thành lập, chị Thiết và những công dân đấu tranh vì công lý khác tích cực cung cấp thông tin cho ICAC, hỗ trợ tổ chức này chống tội phạm, đấu trí với bọn xã hội đen và cả những cảnh sát Anh cấu kết với chúng.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Raquel","avatar":""},{"name":"Miu Tse","avatar":""},{"name":"Liu Teng Yuan","avatar":""},{"name":"Jie Si Tong","avatar":""},{"name":"jenny","avatar":""},{"name":"Natalie Fong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324325);
