INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-dem-cua-sicario', 'Màn Đêm Của Sicario', 'Night Of The Sicario (Blindsided)', 'https://phimimg.com/upload/vod/20231208-1/0ae165eaddc86b7b19196d167066c4fb.jpg', 'https://phimimg.com/upload/vod/20231208-1/d88197d4a1df3941e785371985b5ac5d.jpg', '<p>Taylor buộc phải che giấu cô con gái nhỏ của một phụ nữ Colombia trong sự bảo vệ nhân chứng, người sẽ làm chứng dựa vào một cartel ma túy mạnh mẽ trong Tòa án Liên bang, vì Sicarios tàn nhẫn nhắm đến việc săn lùng chúng.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324325);
