INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dolly-parton-tri-an-tu-musicares', 'Dolly Parton: Tri ân Từ MusiCares', 'Dolly Parton: A MusiCares Tribute', 'https://phimimg.com/upload/vod/20231208-1/70ec7cae4655989902f57302b42a3614.jpg', 'https://phimimg.com/upload/vod/20231208-1/569206110950dc39cf3dcc453be287cf.jpg', '<p>Trong đêm của âm nhạc và hồi ức quy tụ nhiều ngôi sao, một nhóm nghệ sĩ trình diễn đình đám vinh danh Dolly Parton là MusiCares Nhân Vật Của Năm.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dolly Parton","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324325);
