INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-exorcism-of-god', 'The Exorcism Of God', 'The Exorcism Of God', 'https://phimimg.com/upload/vod/20231208-1/fcbfad4e230e52456987cff339bff751.jpg', 'https://phimimg.com/upload/vod/20231208-1/71d842e1a18865e15a6a3b2a3aa83a5e.jpg', '<p>Cha Peter Williams, một người trừ quỷ Mỹ, bị con quỷ đang cố gắng trục xuất từ một phụ nữ trẻ và mà anh ta bị ép buộc, chống lại ý chí của mình, để phạm tội thú vị khủng khiếp nhất. Mười tám năm sau, cố gắng giữ tội lỗi của mình bị chôn vùi trong công việc từ thiện cho người nghèo và trẻ em ở một thị trấn nhỏ ở Mexico, Peter phát hiện ra rằng con quỷ đã trở lại. Lần này nó đã sở hữu một phụ nữ trẻ tên là Esperanza, và ngoài ra, nó cũng giải phóng một căn bệnh chết người giữa những đứa trẻ của thị trấn. Nhưng mục đích thực sự của anh ấy là một cái gì đó khác: để sở hữu linh hồn của Peter. Exorcise Esperanza, Peter phải thú nhận tội lỗi của mình, nhưng nếu anh ta làm thế, anh ta sẽ kết án chính mình không chỉ là một số phận của một sự xuất hiện, mà còn hy sinh đức tin của mình, nhà của anh ta, tâm hồn anh ta, và cơ hội cứu người mà anh ta quan tâm hầu hết.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324325);
