INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-mat-ao-tuong-thanh-that', 'Đổi Mặt - Ảo Tưởng Thành Thật', 'Face', 'https://phimimg.com/upload/vod/20231208-1/afd81c6d12ecfb38010f229e23653387.jpg', 'https://phimimg.com/upload/vod/20231208-1/05c61d4213f9b857e59b91309f31f423.jpg', '<p>Sau một cuộc gặp gỡ bất ngờ, thanh niên thất nghiệp Châu Ngao và nhà văn mạng Giang Tử Vi vô tình được thay đổi gương mặt, trở thành trợ thủ của robot thông minh AI tới từ tương lai. Để hoàn thành nhiệm vụ, họ đã giúp đỡ nữ minh tinh và những con nợ đổi mặt dưới sự chỉ dẫn của robot, đồng thời thu thập trải nghiệm khác nhau từ những người được đổi mặt.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sun Hao","avatar":""},{"name":"He Lin Yan Yuan","avatar":""},{"name":"yangkaiwen","avatar":""},{"name":"Lilixuan","avatar":""},{"name":"Zhang Ge","avatar":""},{"name":"LvChengDao","avatar":""},{"name":"Wu Xu Xu","avatar":""},{"name":"Li Yi Feng","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324325);
