INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-leo-nui-alps', 'Nhà Leo Núi Alps', 'The Alpinist', 'https://phimimg.com/upload/vod/20231208-1/0a4580cf1ce342dde50b2a8ca36cb149.jpg', 'https://phimimg.com/upload/vod/20231208-1/a581a61cc797ff9ec9a61b963ad3e133.jpg', '<p>Marc-André Leclerc, một nhà leo núi xuất sắc, đã một mình thực hiện tôn giáo và băng giá trên quê hương của mình. Khi nhà làm phim Peter Mortimer bắt đầu bộ phim của mình, anh ấy đặt máy ảnh của mình dưới chân một vách đá ở British Columbia và kiên nhẫn chờ đợi ngôi sao leo núi đi xuống để trả lời câu hỏi của mình. Marc André, hơi khó chịu, thích quay trở lại sâu trong rừng, nơi anh sống trong lều với bạn gái Brette Harrington. Giữa mùa đông, Peter quay những màn solo chóng mặt trên lớp băng mỏng manh. Anh ấy cố gắng hẹn gặp người leo núi không bao giờ ở đó và dường như không thực sự quan tâm đến việc chiếc máy ảnh này chĩa vào anh ấy Đối với tôi, sẽ không phải là một mình nếu có người khác. Marc-André vì thế chính là “ánh sáng thuần khiết” của những người leo núi thời bấy giờ, khiến Barry Blanchard, Alex Honnold hay Reinhold Messner phải kinh ngạc khi được phỏng vấn trong phim. Một bộ phim sự kiện dành cho một nhân vật phi thường.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Marc-André Leclerc","avatar":""},{"name":"Brette Harrington","avatar":""},{"name":"Alex Honnold","avatar":""},{"name":"Reinhold Messner","avatar":""},{"name":"Ueli Steck","avatar":""},{"name":"Dean Potter","avatar":""},{"name":"Derek Hersey","avatar":""},{"name":"Jon Walsh","avatar":""},{"name":"Tommy Caldwell","avatar":""},{"name":"Austin Siadak","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324325);
