INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-ke-ben', 'Bác Sĩ Kế Bên', 'The Shrink Next Door', 'https://phimimg.com/upload/vod/20231207-1/50b137cd2c22db18a4800d81ef1a0702.jpg', 'https://phimimg.com/upload/vod/20231207-1/3ae8a5ce10a28f9066f5c7c177be2694.jpg', '<p>Câu chuyện về Marty và bác sĩ trị liệu, người đã xoay chuyển cuộc đời anh - sau đó tiếp quản nó. Khi gặp Tiến sĩ Ike, Marty chỉ muốn hiểu rõ hơn về ranh giới. Hơn 30 năm, anh ấy sẽ tìm hiểu tất cả về chúng - và điều gì sẽ xảy ra khi chúng vượt qua.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Rudd","avatar":""},{"name":"Will Ferrell","avatar":""},{"name":"Kathryn Hahn","avatar":""},{"name":"Casey Wilson","avatar":""},{"name":"Cornell Womack","avatar":""},{"name":"Robin Bartlett","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324325);
