INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-dem-truong-halloween-2', 'Người Dơi: Đêm Trường Halloween 2', 'Batman: The Long Halloween 2', 'https://phimimg.com/upload/vod/20231207-1/f32642d45ecda4d623715e32cebad1cb.jpg', 'https://phimimg.com/upload/vod/20231207-1/d0d63a54dcdd0e8ff5f91dc2158d59f9.jpg', '<p>Kẻ giết người được biết đến với cái tên Holiday tiếp tục theo dõi gia đình tội phạm Falcone trong khi một lớp tội phạm mặc trang phục mới nổi lên ở thành phố Gotham. Batman nghi ngờ rằng một cựu đồng minh có thể là kẻ giết người hàng loạt.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jensen Ackles","avatar":""},{"name":"Josh Duhamel","avatar":""},{"name":"Naya Rivera","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324325);
