INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoa-trai', 'Khóa Trái', 'Locked In', 'https://phimimg.com/upload/vod/20231206-1/d7a5a6f67b426532d4a152f313f8183a.jpg', 'https://phimimg.com/upload/vod/20231206-1/821e4dba887c7a54696e8c67b5555a12.jpg', '<p>Bà mẹ đơn thân Maggie cùng đứa con gái tuổi teen đang sống trong một nhà nghỉ tồi tàn và phải đối mặt với việc bị đuổi ra khỏi nhà bất kỳ lúc nào. Khi ông chủ của cô bị giết, cuộc sống của hai mẹ con bị de dọa bởi những kẻ đang tìm kiếm những viên kim cương bị đánh cắp được cất giấu ở đâu đó bên trong chỗ làm việc của cô. Để tồn tại và bảo vệ con gái, Maggie phải làm mọi cách để luôn đi trước những gã đáng sợ kia một bước.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mena Suvari","avatar":""},{"name":"Jasper Polish","avatar":""},{"name":"Costas Mandylor","avatar":""},{"name":"Jeff Fahey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324325);
