INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-trai-cua-chua', 'Tay Trái Của Chúa', 'The Hand of God', 'https://phimimg.com/upload/vod/20231205-1/d3d5087b0996cddffde4e0d6734b8ced.jpg', 'https://phimimg.com/upload/vod/20231205-1/67536c5e1a9ade9cecf32f1ed9ddac39.jpg', '<p>Từ nhà văn và đạo diễn giành giải học của Học viện Paolo Sorrentino (Il Divo, vẻ đẹp tuyệt vời, Giáo hoàng trẻ), là câu chuyện về một cậu bé, Fabietto Schisa, trong những năm 1980 của những năm 1980. Bàn tay của Thiên Chúa là một câu chuyện đầy những niềm vui bất ngờ, chẳng hạn như sự xuất hiện của huyền thoại bóng đá Diego Maradona, và một thảm kịch bất ngờ không kém. Fate đóng vai trò, niềm vui và bi kịch đan xen và tương lai của Fabietto được đặt trong chuyển động. Sorrentino trở về quê hương của mình để kể câu chuyện cá nhân nhất của mình, một câu chuyện về số phận và gia đình, thể thao và điện ảnh, tình yêu và sự mất mát.</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324325);
