INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-van-tong-su-thuc-tinh-2021', 'Diệp Vấn Tông Sư Thức Tỉnh', 'IP Man: The Awakening Master', 'https://phimimg.com/upload/vod/20231204-1/b4e9c2f170951ff06eb0a63138548d53.jpg', 'https://phimimg.com/upload/vod/20231204-1/6365e59021e031e61ae6d7907b887aa3.jpg', '<p>Khi du học Hồng Kông, người thiếu niên Diệp Vấn bất ngờ bị cuốn vào vụ án tập đoàn Stark lừa gạt, buôn lậu phụ nữ Trung Quốc sang nước ngoài. Diệp Vấn anh dũng đứng ra, ba lần đối đầu với dũng sĩ Patton, dùng Vịnh Xuân Quyền bảo vệ danh dự của người Trung Quốc.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Miu Tse","avatar":""},{"name":"Guanying Chen","avatar":""},{"name":"Hua Qi Long","avatar":""},{"name":"Hou Tong Jiang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324325);
