INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-toi-khong-the-tro-thanh-nguoi-lon', 'Chúng Tôi Không Thể Trở Thành Người Lớn', 'We Couldn''t Become Adults', 'https://phimimg.com/upload/vod/20231204-1/e5d231737ad818bd84a3ead3cc3b2868.jpg', 'https://phimimg.com/upload/vod/20231204-1/5b5a84ac205d31f5d46319dd4503dc2e.jpg', '<p>Năm 1995, tôi gặp cô ấy và muốn làm hết sức mình lần đầu tiên trong đời. Mỗi ngày tôi đã làm việc chăm chỉ vào cuối ngành công nghiệp video vì tôi muốn được cô ấy nhận ra bình thường. Năm 1999, trái với lời tiên tri vĩ đại của Nostradamus, trái đất đã không bị diệt vong, và cô, người là người ủng hộ duy nhất trong trái tim cô, rời đi mà không nói lời tạm biệt. Và 2020. Người 46 tuổi, đã sống hài hòa với xã hội, nhớ lại sau đó khi anh ta không bao giờ quay trở lại, được kích hoạt bởi một số cuộc hội ngộ buồn vui lẫn lộn.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324325);
