INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-sut', 'Hố Sụt', 'Sinkhole', 'https://phimimg.com/upload/vod/20231203-1/670cd68ff47cc506bbbce382719a3e26.jpg', 'https://phimimg.com/upload/vod/20231203-1/b7af46f9da92bc6e0bcfa701fff016ab.jpg', '<p>Park Dong-won (Kim Sung-Kyun), một người bình thường và gia đình anh ta chuyển đến một ngôi nhà đã mua sau 11 năm lao động. Họ ném một bữa tiệc tân gia và mời tất cả bạn bè. Một trận mưa dưới một đêm nặng nề tạo ra một hố hố cực lớn, và chỉ trong một phút, nó nhấn chìm cả ngôi nhà với những người bên trong nó. Deep Down the Hole, Park Dong-won, người hàng xóm Jeong Man-soo (Cha Seung-won), và những vị khách phải tìm lối thoát. Khi may mắn sẽ có trời mưa một lần nữa bắt đầu đổ xuống, đổ đầy hố với nước. Họ phải tìm ra một giải pháp trước khi hết thời gian để tồn tại ....</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324325);
