INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('te-giac', 'Tê Giác', 'Rhino (Nosorih)', 'https://phimimg.com/upload/vod/20231203-1/00fb575281d2bad997d4fdb0cf05feff.jpg', 'https://phimimg.com/upload/vod/20231203-1/97e7c309f33ec3b646848c967f534129.jpg', '<p>Khởi nghiệp là một tên trộm vặt, một thanh niên có biệt danh Tê giác nhanh chóng hoạt động theo cách của mình trong hệ thống phân cấp tội phạm vào những năm 1990 ở Ukraine. Rhino chỉ biết đến quyền lực và sự tàn ác, nhưng không còn gì để mất, liệu cuối cùng anh ta có thể tìm thấy cơ hội cứu chuộc? theo dõi phim trên phimmoi để biết diễn biến phim hơn nha</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Serhii Filimonov","avatar":""},{"name":"Evhen Chernykov","avatar":""},{"name":"Yevhen Grygoriev","avatar":""},{"name":"Alina Zievakova","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324325);
