INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-chay-2021', 'Trốn Chạy', 'Ditched', 'https://phimimg.com/upload/vod/20231203-1/74aeefa140e643d4944b498e51dc73a3.jpg', 'https://phimimg.com/upload/vod/20231203-1/517196df7beb20bd0e36c05fc54ac4ad.jpg', '<p>Sau khi một nhà tù thường xuyên chuyển sự cố trong rừng, Young Inuit Paramesic Melina phát hiện ra mình được bao quanh bởi những kẻ giết người chỉ bằng 100 feet để trèo ra khỏi một con mương để trốn thoát. Khi chúng bị tấn công bởi một lực lượng vô hình trong rừng, hành trình an toàn ngắn gọn của Melina trở thành cuộc thi cuối cùng của Wills.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Canada', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324325);
