INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-quai-2-rung-go-mun', 'Thủy Quái 2: Rừng Gỗ Mun', 'Water Monster 2', 'https://phimimg.com/upload/vod/20231203-1/3944c6374308c21ee5d93e9be46b6781.jpg', 'https://phimimg.com/upload/vod/20231203-1/af0d30eb211cd457d20e2c54cde4dbf1.jpg', '<p>Thanh Linh, một nữ bác sĩ pháp y của Trung Hoa Dân Quốc quay trở lại thị trấn Thượng Thuỷ nơi mình từng sinh sống để tìm kiếm người em trai đã mất tích. Nhưng cũng ở đây, cô vô tình phát hiện được bí mật về thân phận của mình. Cô nỗ lực xoá bỏ hủ tục mê tín phong kiến bằng nền văn minh khoa học, dùng sự thật thức tỉnh người dân thị trấn để chống lại thế lực xấu xa.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Chân Nhi","avatar":""},{"name":"Hàn Đông","avatar":""},{"name":"Lưu Lâm Thành","avatar":""},{"name":"Nguỵ Tử Kỳ","avatar":""},{"name":"Vương Kiến Quốc","avatar":""},{"name":"Ngô Thành Chí","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324325);
