INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-tinh-vo-mon-vo-hon', 'Tân Tinh Võ Môn: Võ Hồn', 'Fist of Fury: Soul', 'https://phimimg.com/upload/vod/20231203-1/9f3a89d178bdbf11ad02249b12d200a8.jpg', 'https://phimimg.com/upload/vod/20231203-1/fa4c70a28a67027239741698a258f6ff.jpg', '<p>Trong đại hội võ thuật, một mình Huyết Ma La đã khiến cả vỗ lâm bị thiệt hại nặng nề. Minh chủ , Hoắc Tràng Không, đã mất một nửa số nước đi trong trận chiến quyết định, và cuối cùng truyền sức mạnh của mình cho Lưu Tinh trẻ tuổi và bảo vệ anh ta khỏi việc di tản. Mười bốn năm sau, Lưu Tinh, vì muốn học võ nên đã tình cờ đến \Phòng tập quyền anh Hoắc Gia\ và tự nhận mình là người có tài năng xuất chúng. Sư phụ Hoắc, chủ phòng, đã cho phép anh ta chấp nhận bài kiểm tra, nhưng Lưu Tinh đã thất bại và phải rời đi. Trên đường phố, Lưu Tinh gặp một người tài giỏi khác, Đường Bách Bách và đi theo anh ta để tìm kiếm một vị người tài giỏi thực sự vô song, nhưng lại đến lưới điện bí mật của Hội Lông Đen và gặp Huyết Ma La...</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Guanying Chen","avatar":""},{"name":"Khương Manh Hiên","avatar":""},{"name":"Norman Chui","avatar":""},{"name":"Zhang Chun Zhong","avatar":""},{"name":"Tu Yu Ming","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324325);
