INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-ly-tuong', 'Thành Phố Lý Tưởng', 'The Ideal City', 'https://phimimg.com/upload/vod/20231204-1/78146e262ca39f03c0f3f57489ff4298.jpg', 'https://phimimg.com/upload/vod/20231204-1/2bb039dbb240dc3ef35c737f389d54c8.jpg', '<p>Bộ phim xoay quanh câu chuyện cô kỹ sư chi phí kỹ thuật Tô Tiêu (Tôn Lệ đóng) trong một doanh nghiệp trong nước, do bị chịu tội thay nên bị sa thải, sau đó vào làm cho tập đoàn Chấn Hoa - một doanh nghiệp tư nhân. Với năng lực vượt trội, Tô Tiêu được đề bạt làm phó phó giám đốc quản lý kinh tế của tập đoàn, bị cuốn vào cuộc chiến trính trị phức tạp mà khéo léo của tập đoàn. Đồng thời với sự chỉ dẫn và giúp đỡ của Hạ Minh (Triệu Hiệu Đình đóng) từng bước trở thành chủ tịch của tập đoàn Chấn Hoa.</p>', 'Hoàn tất (40/40)', 40, 'series', 'completed', 14, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tôn Lệ","avatar":""},{"name":"Triệu Hựu Đình","avatar":""},{"name":"Yu He Wei","avatar":""},{"name":"Trần Minh Hạo","avatar":""},{"name":"Gao Diệp","avatar":""},{"name":"Yang Chao Yue","avatar":""},{"name":"Lưu Dịch Sướng","avatar":""},{"name":"Li Zhuan Ying","avatar":""},{"name":"Zhang Shu","avatar":""},{"name":"Ding Wen Bo","avatar":""},{"name":"Qian Yi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324325);
