INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-thu-mat-trang-vinh-hang', 'Thủy Thủ Mặt Trăng: Vĩnh Hằng', 'Pretty Guardian Sailor Moon Eternal The MOVIE Part 2', 'https://phimimg.com/upload/vod/20231205-1/574a04e3a410f0340350a1e6c800b865.jpg', 'https://phimimg.com/upload/vod/20231205-1/de46a15d788b46f4766c72120ea4dedd.jpg', '<p>Bộ những cuộc phiêu lưu mới nhất của Sailor Guardian đã diễn ra vào tháng Tư, khi hoa anh đào của Tokyo đang nở rộ, và thủ đô Nhật Bản đang trong một tâm trạng lễ hội, vì nó kỷ niệm toàn bộ nhật thực lớn nhất thế kỷ. Khi mặt trăng mới che khuất mặt trời và dần dần làm mờ ánh sáng, Usagi và Chibi-USA gặp Pegasus, người đang tìm kiếm con gái đã chọn, người có thể phá vỡ con dấu của tinh thể vàng. Đồng thời, một đoàn kịch bí ẩn được gọi là Circ MOON Circus xuất hiện trong thị trấn, kế hoạch bất chính của họ sẽ phân tán các hóa thân ác mộng được gọi là hình nón, để chiếm giữ Crystal bạc huyền thoại, và để cai trị mặt trăng và đất, cuối cùng đến thống trị toàn bộ vũ trụ.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324325);
