INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pele', 'Pelé', 'Pelé', 'https://phimimg.com/upload/vod/20231204-1/86318265e9ca6613f3b9b42ac52187c6.jpg', 'https://phimimg.com/upload/vod/20231204-1/4c8291f98c7ece555a5d6d804629c48b.jpg', '<p>Với bối cảnh ở một thời kỳ đầy biến động của Brazil, phim tài liệu này ghi lại con đường phi thường của Pelé từ nhân tài bứt phá thành người hùng dân tộc.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Pelé","avatar":""}]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324325);
