INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-the-vu-tru', 'Quần Thể Vũ Trụ', 'Invisible Alien', 'https://phimimg.com/upload/vod/20231204-1/baf761e2f1ded5e23c556f07364decc0.jpg', 'https://phimimg.com/upload/vod/20231204-1/a7a013dd4f7cf8764b972785c0d209b9.jpg', '<p>Tàu vũ trụ thám hiểm các vì sao “Deep Space” đã biến mất một cách bí ẩn cách đây 150 năm bất ngờ xuất hiện gần quỹ đạo trái đất. Ngành hàng không vũ vụ nhân loại đã thành lập một uỷ ban tạm thời, điều tra và và truy hỏi về người còn sống sót duy nhất, những trải nghiệm đáng sợ của “Deep Space” từ từ được mở ra.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wu Jiao","avatar":""},{"name":"Ruan Sheng Wen","avatar":""},{"name":"Xia Wang","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324325);
