INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hai-den-roi-lam-sao-day', 'Anh Hai Đến Rồi, Làm Sao Đây', 'Hi Brothers', 'https://phimimg.com/upload/vod/20231203-1/a895b747fdc4f7db7ff60d4a97f5e872.jpg', 'https://phimimg.com/upload/vod/20231203-1/a9fdabc1146db8b3a8f7dbe02d010c7f.jpg', '<p>Sau cuộc hôn nhân mới của mẹ, thế giới của hai anh em nọ đảo lộn khi người anh trai mới kỳ lạ xuất hiện một cách đầy lúng túng trong cuộc sống của họ.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hồ Tiên Hú","avatar":""},{"name":"Đặng Ân Hi","avatar":""},{"name":"Trịnh Vĩ","avatar":""},{"name":"Đại Lạc Lạc","avatar":""},{"name":"Trần Hi Thánh","avatar":""},{"name":"Cao Thự Quang","avatar":""},{"name":"Trương Bình Quyên","avatar":""},{"name":"Hanikezi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324325);
