INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-nhan-cua-vung-dat-ma-quai', 'Tù Nhân Của Vùng Đất Ma Quái', 'Prisoners of the Ghostland', 'https://phimimg.com/upload/vod/20231203-1/2f6e14acdb3e51fb098bccf502035868.jpg', 'https://phimimg.com/upload/vod/20231203-1/9dfeb56239194a690cd50b4ba213be9f.jpg', '<p>Tù Nhân Của Vùng Đất Ma Quái kể về Hero bị giam giữ trong một thị trấn hậu tận thế có tên Samurai Town. Tay thị trưởng của nơi đây bị thất lạc đứa con gái thân yêu Bernice và quyết định cử Hero để truy tìm cô về. Để đảm bảo mọi thứ thành công, tay thị trưởng còn khoác lên áo da cho Hero mặc với những quả bom đính kèm khắp người. Điều nguy hiểm nhất chính là Bernice hiện đang lẩn trốn trong một nơi gọi là Ghost Land. Vùng đất biên giới với những kẻ điên loạn, ma quái tôn thờ một thế lực thần bí.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Sofia Boutella","avatar":""},{"name":"Nick Cassavetes","avatar":""},{"name":"Bill Moseley","avatar":""},{"name":"Tak Sakaguchi","avatar":""},{"name":"Young Dais","avatar":""},{"name":"Charles Glover","avatar":""},{"name":"Cici Zhou","avatar":""},{"name":"Tetsu Watanabe","avatar":""},{"name":"Takato Yonemoto","avatar":""},{"name":"Shin Shimizu","avatar":""},{"name":"Matthew Chozick","avatar":""},{"name":"Constant Voisin","avatar":""},{"name":"Yuzuka Nakaya","avatar":""},{"name":"Lorena Koto","avatar":""},{"name":"Canon Nawata","avatar":""},{"name":"Hiroshi Kaname","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"