INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiem-do-co-trung-cuc-mat-ma-quoc-hoa', 'Tiệm Đồ Cổ Trung Cục: Mật Mã Quốc Hoạ', 'Mystery of Antiques: The Chinese Painting Code', 'https://phimimg.com/upload/vod/20231202-1/fce3551257c6b9fb76da6ceee47c75fc.jpg', 'https://phimimg.com/upload/vod/20231202-1/5aff04987f58f2661bcd62335ce363de.jpg', '<p>Phim kể về chủ một cửa hàng đồ cổ nhỏ Chúc Sách đang có cuộc sống bình thường nhưng lại vô tình vướng vào một sự cố về bảo vật quốc gia &quot;Ven Sông Trong Lễ Hội Thanh Minh&quot;, và biết được rằng mình có mối quan hệ thân thiết với sự cố này. Trong cuộc điều tra chống lại kẻ thủ ác chống lại thời gian, Chúc đã lần ra nhiều lớp manh mối để tìm ra những bằng chứng then chốt, và cuối cùng bảo vệ thành công câu chuyện về bảo vật quốc gia .</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Han Dong","avatar":""},{"name":"Wang Yunfan","avatar":""},{"name":"Yu Kang","avatar":""},{"name":"Jampa Tseten","avatar":""},{"name":"Ariel Ann","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Shuangli Zhang","avatar":""},{"name":"Zhang Fengjun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324325);
