INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-mua-so-hai', 'Cơn Mưa Sợ Hãi', 'Fear of Rain', 'https://phimimg.com/upload/vod/20231202-1/17f4dcb23483c25721cd3c9058ed1ab7.jpg', 'https://phimimg.com/upload/vod/20231202-1/1055c2be89f8d2c8b736243b95c51505.jpg', '<p>Một cô gái sống với tâm thần phân liệt vật lộn với ảo giác kinh hoàng khi cô bắt đầu nghi ngờ hàng xóm của mình đã bắt cóc một đứa trẻ. Người duy nhất tin rằng cô ấy là CALEB -A Boy, cô ấy thậm chí không chắc chắn tồn tại.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Madison Iseman","avatar":""},{"name":"Israel Broussard","avatar":""},{"name":"Katherine Heigl","avatar":""},{"name":"Harry Connick Jr.","avatar":""},{"name":"Eugenie Bondurant","avatar":""},{"name":"Julia Vasi","avatar":""},{"name":"Enuka Okuma","avatar":""},{"name":"Hudson Rodgers","avatar":""},{"name":"Lyla Restaino","avatar":""},{"name":"Ashley Abrams","avatar":""},{"name":"Jannette Sepwa","avatar":""},{"name":"Bianca D''Ambrosio","avatar":""},{"name":"Brian Yang","avatar":""},{"name":"Lindsay Lamb","avatar":""},{"name":"Mackenzie Bonefont","avatar":""},{"name":"Todd Gobl","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324325);
