INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('stowaway', 'Stowaway', 'Stowaway', 'https://phimimg.com/upload/vod/20231201-1/923cfa05c039767434e137b1ceec254b.jpg', 'https://phimimg.com/upload/vod/20231201-1/0182e2f908f33f642bdb5546de9e5866.jpg', '<p>Trong nhiệm vụ đến sao Hỏa, phi hành đoàn ba người phải đưa ra lựa chọn khó khăn khi một hành khách không mời đặt tính mạng của mọi người trên tàu vào hiểm cảnh.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Anna Kendrick","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"Daniel Dae Kim","avatar":""},{"name":"Shamier Anderson","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324325);
