INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('stowaway', 'Stowaway', 'Stowaway', 'stowaway stowaway anna kendrick toni collette daniel dae kim shamier anderson ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-thang-chot-voi-qua', 'Năm Tháng Chợt Vội Qua', 'PASSAGE OF MY YOUTH', 'https://phimimg.com/upload/vod/20231201-1/643b1b2af6a24f28ee08271b47390813.jpg', 'https://phimimg.com/upload/vod/20231201-1/926c04e9cb7927c7ba85f59d76d8851a.jpg', '<p>Từ khi mười tuổi, Khương Hà đã bắt đầu sùng bái Giang Hải. Trong những năm tháng thanh xuân, điều cô tin theo trong đời chính là đến gần Giang Hải hơn một chút. Còn có một người nữa có suy nghĩ giống như vậy, đó chính là Cố Tân Liệt, chỉ có điều, lý tưởng của anh là tới gần Khương Hà hơn một chút. Cố Tân Liệt luôn bị Giang Hà gọi thành \&quot;Cố Ngốc Nghếch\&quot;. Nhưng thật ra anh hoàn toàn không hề ngốc, chỉ là bị lúng túng khi đứng trước tình yêu mà thôi. Cuộc sống du học tại Anh của Giang Hải và Khương Hà tràn đầy nước mắt và cả những nụ cười. Cố Tân Liệt phấn đấu tại quê nhà, cuối cùng cũng tới được nước Anh. Khương Hà vẫn luôn bước theo Giang Hải, và Cố Tân Liệt cũng vẫn mãi đi theo Khương Hà. Nhiệt huyết của thanh xuân, đơn giản mà cố chấp, khúc nhạc về tình yêu nơi đất khách lặng lẽ bắt đầu.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Zifeng","avatar":""},{"name":"Jo Jiang","avatar":""},{"name":"Zhao Duona","avatar":""},{"name":"Song Weilong","avatar":""},{"name":"Xue Huiwei","avatar":""},{"name":"Gao Yang","avatar":""},{"name":"Sun Jingjing","avatar":""},{"name":"Li Rui","avatar":""},{"name":"Zhao Yingjun","avatar":""},{"name":"Joe Xu","avatar":""},{"name":"Emma Wu","avatar":""},{"name":"Rong Zishan","avatar":""},{"name":"Xue Bowen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324325);
