INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-gi-joe-xa-nhan-bao-thu', 'Biệt Đội G.I. Joe: Xà Nhãn Báo Thù', 'Snake Eyes: G.I. Joe Origins', 'https://phimimg.com/upload/vod/20231201-1/06c199a235e8153a856c53501a16a7ba.jpg', 'https://phimimg.com/upload/vod/20231201-1/27f09f7b58f2c37db9d07eca48cc950d.jpg', '<p>Snake Eyes: G.I. Joe Origins theo chân Snake Eyes - một chiến binh cô độc, ngoan cường bất ngờ được kết nạp vào gia tộc Arashikage sau khi cứu mạng người thừa kế của họ. Khi đến Nhật Bản, Arashikage dạy Snake Eyes những chiêu thức cơ bản của một chiến binh ninja đồng thời mang tới cho anh một mái ấm. Tuy nhiên, khi những bí mật từ quá khứ của Snake Eyes được bật mí, anh sẽ phải đối mặt với những thử thách lớn nhất trong cuộc đời.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Henry Golding","avatar":""},{"name":"Andrew Koji","avatar":""},{"name":"Haruka Abe","avatar":""},{"name":"Úrsula Corberó","avatar":""},{"name":"Samara Weaving","avatar":""},{"name":"Takehiro Hira","avatar":""},{"name":"Eri Ishida","avatar":""},{"name":"Iko Uwais","avatar":""},{"name":"Peter Mensah","avatar":""},{"name":"Steven Allerick","avatar":""},{"name":"Simon Chin","avatar":""},{"name":"Samuel Finzi","avatar":""},{"name":"Shota Kakibata","avatar":""},{"name":"Nicholas Dohy","avatar":""},{"name":"Dean Muhtadi","avatar":""},{"name":"James Hiroyuki Liao","avatar":""},{"name":"Kenji Tanigaki","avatar":""},{"name":"Kento","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324325);
