INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-mad-womens-ball', 'The Mad Women''s Ball', 'The Mad Women''s Ball', 'https://phimimg.com/upload/vod/20231211-1/36028249e80e2c340dda178a75fc6248.jpg', 'https://phimimg.com/upload/vod/20231211-1/80cee2fb24e6601dcb73b721801b10d1.jpg', '<p>Câu chuyện về Eugenie, một cô gái trẻ dạ quang và đam mê vào cuối thế kỷ 19. Eugenie có một món quà độc đáo: cô ấy nghe thấy và nhìn thấy người chết. Khi gia đình cô phát hiện ra bí mật của mình, cô được cha và anh trai của cô đến phòng khám thần kinh tại La Pitié Salpetrière không có khả năng thoát khỏi số phận của mình. Một phòng khám, được điều hành bởi Giáo sư nổi tiếng Charcot</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324325);
