INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('im-your-man', 'I''m Your Man', 'I''m Your Man', 'https://phimimg.com/upload/vod/20231201-1/6eb73ac9d102b6cf0afcf5c7a641b243.jpg', 'https://phimimg.com/upload/vod/20231201-1/2c7c3d08398b76486f7057f73b4573e6.jpg', '<p>Để có được quỹ nghiên cứu cho các nghiên cứu của mình, một nhà khoa học chấp nhận một đề nghị tham gia vào một thí nghiệm đặc biệt: trong ba tuần, cô ấy sẽ sống với một robot hình người, được tạo ra để làm cho cô ấy hạnh phúc.</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Maren Eggert","avatar":""},{"name":"Dan Stevens","avatar":""},{"name":"Sandra Hüller","avatar":""},{"name":"Hans Löw","avatar":""},{"name":"Wolfgang Hübsch","avatar":""},{"name":"Annika Meier","avatar":""},{"name":"Falilou Seck","avatar":""},{"name":"Jürgen Tarrach","avatar":""},{"name":"Henriette Richter-Röhl","avatar":""},{"name":"Monika Oschek","avatar":""},{"name":"Karolin Oesterling","avatar":""},{"name":"Marlene Sophie Haagen","avatar":""},{"name":"Victor Pape-Thies","avatar":""},{"name":"Inga Busch","avatar":""},{"name":"Amal Keller","avatar":""},{"name":"Mignon Remé","avatar":""},{"name":"Gab","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324325);
