INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-blood-of-wolves-ii', 'The Blood Of Wolves II', 'The Blood Of Wolves II', 'https://phimimg.com/upload/vod/20231211-1/9e7a72ca8321f203e1d2d3452fe5f7f7.jpg', 'https://phimimg.com/upload/vod/20231211-1/2cc5c99e3b283e128ded2d3ab1139fd5.jpg', '<p>Đặt vài năm sau khi máu của Wolves và cái chết của Ogami Shogo ở thành phố phía tây Hiroshima, kế hoạch của thám tử bao quanh và kiểm soát cuộc sống thấp Yakuza đã được thực hiện và đang làm việc. Nhiều ca đỏ và tử vong tiềm năng đã được ngăn chặn. Tuy nhiên, việc phát hành một yếu tố tội phạm đặt tất cả mọi thứ trong Jeopardy.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324326);
