INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-execution', 'The Execution', 'Kazn', 'https://phimimg.com/upload/vod/20231211-1/25b07b913934ed32aa4347301889575c.jpg', 'https://phimimg.com/upload/vod/20231211-1/f1626c3ee42978f4157a96c14210e798.jpg', '<p>Trong hơn 10 năm, lực lượng cảnh sát Nga đã cố gắng ngăn chặn kẻ giết người hàng loạt thông minh và bị truy nã gắt gao nhất đất nước. Nhưng ngay cả khi anh ta bị bắt, không ai có thể chứng minh tội lỗi của anh ta. Khi cuộc truy lùng tăng cường, cuộc điều tra ngày càng trở nên cá nhân giữa thám tử và nghi phạm.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Niko Tavadze","avatar":""},{"name":"Daniil Spivakovskiy","avatar":""},{"name":"Yuliya Snigir","avatar":""},{"name":"Evgeniy Tkachuk","avatar":""},{"name":"Aglaya Tarasova","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324326);
