INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-hon-phap-su-2-tham-hoa-sinh-tu-cuong-thi-do-bo', 'Trấn Hồn Pháp Sư 2 | Thảm Hoạ Sinh Tử, Cương Thi Đổ Bộ!', 'Exorcism Master 2', 'https://phimimg.com/upload/vod/20231211-1/6aa063966609515e7c57779467cba962.jpg', 'https://phimimg.com/upload/vod/20231211-1/0683de9ca5f290587bb1a16c47398c77.jpg', '<p>Li Yanzhi cùng ba nhóm trấn áp linh hồn khác đã trở nên vang danh khi đánh bại được Zhao Yuanqi, nhưng một âm mưu mới đã bắt đầu manh nha. Li Yanzhi đã nhận thấy một dấu hiệu kỳ lạ, Lý Yến Chi, Huyền Dương Tử và Tần Vũ ngoài việc dùng các kỹ năng thoát hiểm đã tìm cách xoay xở để cứu lấy những người bị mắc kẹt, qua lần này họ cảm thấy có rất nhiều nghi vấn và bắt đầu điều tra. Ba vị chủ trấn áp linh hồn tới một thôn hẻo lánh, lúc này nữ nhân Thanh Thanh đang bị ba đại nam nhân uy hiếp, Lý Ngôn Chi đã tới giải cứu Tiểu Thanh Thanh, Tần Vũ đối với Thanh Thanh không mấy thiện cảm. Người phụ nữ được cứu sống tên Qingqing đã dẫn ba người của hội trấn hồn đến một quán trọ hoang vắng.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324326);
