INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-ve-dem', 'Ngôi Nhà Về Đêm', 'The Night House', 'https://phimimg.com/upload/vod/20231129-1/7936e5e6876af3ace728dfa8312b49b4.jpg', 'https://phimimg.com/upload/vod/20231129-1/a1df6d3ce8efd8a30d1aed005c6572da.jpg', '<p>Quay cuồng với cái chết bất ngờ của chồng, Beth bị bỏ lại một mình trong ngôi nhà ven hồ mà anh đã xây cho cô. Chẳng bao lâu, cô bắt đầu khám phá ra những bí mật đáng lo ngại của người chồng vừa qua đời của cô.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Rebecca Hall","avatar":""},{"name":"Sarah Goldberg","avatar":""},{"name":"Vondie Curtis-Hall","avatar":""},{"name":"Evan Jonigkeit","avatar":""},{"name":"Stacy Martin","avatar":""},{"name":"David Abeles","avatar":""},{"name":"Christina Jackson","avatar":""},{"name":"Patrick Klein","avatar":""},{"name":"Crystal Swan","avatar":""},{"name":"Catherine Weidner","avatar":""},{"name":"Laura Austin","avatar":""},{"name":"Jacob Garrett White","avatar":""},{"name":"Samantha Buck","avatar":""},{"name":"Lydia Hand","avatar":""},{"name":"Lea Enslin","avatar":""},{"name":"Amy Zubieta","avatar":""},{"name":"Allie M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324326);
