INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-nguoi-soi', 'Truyền Thuyết Người Sói', 'The war of werewolf', 'null', 'https://phimimg.com/upload/vod/20231129-1/eb4dd47e7f75e0c7775d6a8c7d78610d.jpg', '<p>Lãng Tuấn - một thanh niên bình thường, vô tình bị thương trong lúc đi giao hàng, đã trở thành vật thí nghiệm của thế lực hắc ám “Tam Vũ Liên”. Sở hữu khả năng biến thành người sói, trong lúc trốn tránh sự truy đuổi của “Tam Vũ Liên”, Lãng Tuấn đã phát hiện ra sự thật về cái chết của cha mình…Vì để bảo vệ người mình yêu, cũng như lật đổ sự thống trị của thế lực hắc ám, người sói Lãng Tuấn đã bắt đầu hành trình chống lại…</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Jingyi","avatar":""},{"name":"Wu Xuanxuan","avatar":""},{"name":"Ren Tianye","avatar":""},{"name":"Liang Guorong","avatar":""},{"name":"Yang Yong","avatar":""},{"name":"Han Mingxi","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324326);
