INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truyen-thuyet-nguoi-soi', 'Truyền Thuyết Người Sói', 'The war of werewolf', 'truyền thuyết người sói the war of werewolf li jingyi wu xuanxuan ren tianye liang guorong yang yong han mingxi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-toi-la-tac-gia-truyen-tranh-tho-tuc-movie', 'Cha Tôi Là Tác Giả Truyện Tranh Thô Tục Movie', 'Kakushigoto Movie', 'https://phimimg.com/upload/vod/20231129-1/2bc4e95a2980426ab417e559ad7101ee.jpg', 'https://phimimg.com/upload/vod/20231129-1/3373cd4dcaca9d828e7933773dc5f8cf.jpg', '<p>Phim tổng hợp của loạt phim truyền hình bao gồm những cảnh mới chưa được chuyển thể trong anime truyền hình và các góc nhìn khác nhau. Kakushi Gotou là một họa sĩ truyện tranh nổi tiếng với những tác phẩm được biết đến với nội dung không phù hợp. Vì điều này, khi đứa con gái Hime của anh được sinh ra, anh thề sẽ giấu nghề của mình với cô vì sợ rằng cô sẽ vỡ mộng nếu phát hiện ra. Niềm tin gây ra bởi sự hoang tưởng này dẫn Kakushi vào những tình huống bận rộn. Mặc dù là một người cha đơn thân, anh ấy làm hết sức mình và thường dùng đến những mục đích cực đoan chỉ để bảo vệ bí mật của mình, chẳng hạn như cải trang làm công ăn lương hàng ngày hoặc tổ chức các cuộc tập trận khẩn cấp trong trường hợp Hime bằng cách nào đó tìm được đường đến nơi làm việc của anh ấy. Kakushigoto kể câu chuyện về một người cha và cô con gái sống cạnh nhau, duy trì sự tồn tại hòa bình của họ khi người cha cố gắng bảo tồn nguyên trạng. Tuy nhiên, có câu: “không có bí mật nào mà thời gian không thể tiết lộ”. Theo thời gian, Hime phải tìm hiểu thực tế đằng sau những điều mà cô ấy coi là đương nhiên khi lớn lên.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hiroshi Kamiya","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Kiyono Yasuno","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Manami Numakura","avatar":""},{"name":"Ari Ozawa","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Azumi Waki","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Emiri Kato","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Rikako Aida","avatar":""},{"name":"Shiho Kokido","avatar":""},{"name":"Yumi Hara","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324326);
