INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-bong-cua-tre-mo-coi', 'Đội Bóng Của Trẻ Mồ Côi', '12 Mighty Orphans', 'https://phimimg.com/upload/vod/20231129-1/d2e7b266d1ea88d78fceb1d47491808f.jpg', 'https://phimimg.com/upload/vod/20231129-1/77f569307da87b1597d02af52361117c.jpg', '<p>bộ phim thể thao của Mỹ được phát hành năm 2021, tác phẩm do Ty Roberts làm đạo diễn với phần kịch bản được chắp bút bởi Roberts, Lane Garrison và Kevin Meyer. Phim có sự tham gia của các diễn viên Luke Wilson , Vinessa Shaw , Wayne Knight , Jake Austin Walker , Jacob Lofland , Levi Dylan, Robert Duvall và Martin Sheen. &nbsp;Bộ phim thể thao dựa trên sự kiện có thật của đạo diễn Ty Roberts kể lại câu chuyện về Mighty Mites, một đội bóng đá trung học phi truyền thống được thành lập tại Masonic Home &amp; School vào những năm 1930 ở Fort Worth, Texas. &nbsp;Bộ phim lấy bối cảnh năm 1938, khi huấn luyện viên bóng đá Rusty Russell ( Luke Wilson ) cùng vợ chồng giáo viên đồng nghiệp của anh là Juanita ( Vinessa Shaw ) tới Masonic Home cùng với cô con gái nhỏ của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luke Wilson","avatar":""},{"name":"Vinessa Shaw","avatar":""},{"name":"Wayne Knight","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"Jake Austin Walker","avatar":""},{"name":"Scott Haze","avatar":""},{"name":"Levi Dylan","avatar":""},{"name":"Jacob Lofland","avatar":""},{"name":"Rooster McConaughey","avatar":""},{"name":"King Orba","avatar":""},{"name":"Treat Williams","avatar":""},{"name":"Larry Pine","avatar":""},{"name":"Lillie Fink","avatar":""},{"name":"Josie Fink","avatar":""},{"name":"Slade Monroe","avatar":""},{"name":"Preston Porter","avatar":""},{"name":"Ron White","avatar":""},{"name":"Woodrow Luttrel","a