INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-than-sach', 'Mỹ Nhân Thần Sách', 'Bookworm Beauty', 'https://phimimg.com/upload/vod/20231125-1/9c1788147080f22e3055cdf51bad49d8.jpg', 'https://phimimg.com/upload/vod/20231125-1/3a92bb1c30c208c18d72803160eca5de.jpg', '<p>Mỹ Nhân Thần Sách là câu chuyện về An, một cô nàng nhút nhát, lù đù, mọt sách được mệnh danh là “An thần sách” vừa chuyển đến trường mới. Với sự thông minh của mình, An nhanh chóng được hội VỸ NHÂN (tập họp các học sinh xuất sắc về học thuật) của trường mới chú ý, quyết lôi kéo vào hội với mục đích làm hội lớn mạnh hơn, để chinh phục các cuộc thi kiến thức trong trường và quốc gia.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Minh Beta","avatar":""},{"name":"Korapat Kirdpan","avatar":""},{"name":"Việt Linh","avatar":""},{"name":"Trúc Anh Burin","avatar":""},{"name":"Thiên Nga","avatar":""},{"name":"Phi Phung","avatar":""},{"name":"Thuy Huong Ha","avatar":""},{"name":"Gino Tống","avatar":""},{"name":"Alex Nguyễn","avatar":""},{"name":"Nguyễn Tiến Dũng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324326);
