INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-co-ky-dam-1-am-thanh-sat-co', 'Tân Cô Kỳ Đàm 1: Ám Thành Sát Cơ', 'Deadly Puppet', 'https://phimimg.com/upload/vod/20230929-1/2527f15ecbde8f36082bdad8d86b51d2.jpg', 'https://phimimg.com/upload/vod/20230929-1/f74134833354710447e3a7e637d048ad.jpg', '<p>Bộ phim xoay quanh một vụ án liên hoàn ở thành Tân Cô thời dân quốc, cảnh sát cũng phải bó tay vì không có bất cứ đầu mối nào về vụ án. Lúc này Trâu Thích và Đoạn Vu Hào là hai người chuyên dùng ‘phong thủy phá án’ đã quyết định điều ra sự thật bị che giấu đằng sau. Trong quá trình điều tra họ vô tình phát hiện sự việc có liên quan đến vụ án từ nhiều năm trước. Hai người cùng nhau tìm ra sự thật, đồng thời giải quyết bí ẩn về tên sát nhân vẫn luôn nấp trong bóng tối.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Ke","avatar":""},{"name":"Sun Sheng Hao","avatar":""},{"name":"Han Xinrui","avatar":""},{"name":"Ji Muchuan","avatar":""},{"name":"Zhang Jingjing","avatar":""},{"name":"William Li","avatar":""},{"name":"Feng Xiang","avatar":""},{"name":"Yi Zhengfu","avatar":""},{"name":"Wang Xiaohong","avatar":""},{"name":"Yang Junbai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324326);
