INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-nhu-2021', 'Nếu Như…?', 'What If...?', 'https://phimimg.com/upload/vod/20231006-1/f4f9031f173531b3546316b3d11dfacd.jpg', 'https://phimimg.com/upload/vod/20231006-1/585b9c054609c8528626063f2deefdec.jpg', '<p>What If...? là series phim truyền hình Mỹ, phát sóng trên nền tảng xem phim trực tuyến Disney+. Giám chế phim là A.C. Bradley, cùng với đạo diễn là Bryan Andrews. Tác phẩm được xây dựng trong bối cảnh của Vũ trụ Điện ảnh Marvel (MCU), nói về những biến cố có thể xảy ra nếu các sự kiện trong các phim điện ảnh của vũ trụ này không đi theo chiều hướng ban đầu.</p>', 'Hoàn Tất (9/9)', 9, 'hoathinh', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeffrey Wright","avatar":""},{"name":"Terri Douglas","avatar":""},{"name":"Matthew Wood","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Chadwick Boseman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324326);
