INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-2021', 'Giải Cứu', 'Free Guy', 'https://phimimg.com/upload/vod/20231019-1/9b0c064aa8ab3f334576f4eae4078688.jpg', 'https://phimimg.com/upload/vod/20231019-1/0f4451da129cd0de9ea0efc90567e2ba.jpg', '<p>Guy - Nhân viên giao dịch ngân hàng, phát hiện anh ấy thực chất là người chơi nền trong trò chơi điện tử thế giới mở. Guy quyết định trở thành người anh hùng và viết lại câu chuyện của chính mình. Giờ đây, trong một thế giới không còn giới hạn, anh ấy quyết định trở thành người giải cứu thế giới, theo cách của chính mình.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Jodie Comer","avatar":""},{"name":"Joe Keery","avatar":""},{"name":"Lil Rel Howery","avatar":""},{"name":"Utkarsh Ambudkar","avatar":""},{"name":"Taika Waititi","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Aaron W Reed","avatar":""},{"name":"Britne Oldford","avatar":""},{"name":"Camille Kostek","avatar":""},{"name":"Mark Lainer","avatar":""},{"name":"Mike Devine","avatar":""},{"name":"Sophie Levy","avatar":""},{"name":"Vernon Scott","avatar":""},{"name":"Naheem Garcia","avatar":""},{"name":"Anabel Graetz","avatar":""},{"name":"Ric Plamenco","avatar":""},{"name":"Kenneth","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324326);
