INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-poltergeist-diaries', 'The Poltergeist Diaries', 'The Poltergeist Diaries', 'https://phimimg.com/upload/vod/20231208-1/3815fd43e2097014f2c117135e775572.jpg', 'https://phimimg.com/upload/vod/20231208-1/28d3241f694e4fe2eb6f0618f9e554ca.jpg', '<p>Sau khi chuyển đến một cabin bị cô lập, Jacob Taylor biến mất mà không có dấu vết. Với sự giúp đỡ của đoạn phim, anh ta bỏ lại, các thành viên gia đình, bạn bè và một thám tử cố gắng tìm câu trả lời cho những sự kiện kỳ lạ đang tập trung vào anh ta.</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324326);
