INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-chu-be-nhut-nhat', 'Nhật Ký Chú Bé Nhút Nhát', 'Diary of a Wimpy Kid', 'https://phimimg.com/upload/vod/20231129-1/cc1e5cf394798eafb1edbf2ad6866b7f.jpg', 'https://phimimg.com/upload/vod/20231129-1/ddd5c06872461a6d2d41cbae43578ef9.jpg', '<p>Greg Heffley là một đứa trẻ gầy gò nhưng đầy tham vọng, có trí tưởng tượng phong phú và có những kế hoạch lớn để trở nên giàu có và nổi tiếng - trước tiên cậu chỉ cần sống sót qua trường cấp hai.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2021, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Brady Noon","avatar":""},{"name":"Ethan William Childress","avatar":""},{"name":"Hunter Dillon","avatar":""},{"name":"Erica Cerra","avatar":""},{"name":"Chris Diamantopoulos","avatar":""},{"name":"Gracen Newton","avatar":""},{"name":"Christian Convery","avatar":""},{"name":"Jessica Mikayla Adams","avatar":""},{"name":"Cyrus Arnold","avatar":""},{"name":"Braxton Baker","avatar":""},{"name":"Lossen Chambers","avatar":""},{"name":"Brenda Crichlow","avatar":""},{"name":"Tessa Espinola","avatar":""},{"name":"Yuvraj Singh","avatar":""},{"name":"Billy Lopez","avatar":""},{"name":"Donny","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324326);
