INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-dem-bai', 'Kẻ Đếm Bài', 'The Card Counter', 'https://phimimg.com/upload/vod/20231129-1/19fad428e5adf148d0f1a90735a129de.jpg', 'https://phimimg.com/upload/vod/20231129-1/670d259b7ac6f66ab27e02498fa9be43.jpg', '<p>Nội dung bộ phim là câu chuyện về một người đàn ông William Tell cực nghiện cờ bạc. Nhưng “niềm đam mê” ấy những tưởng sẽ được dập tắt đi bởi sự xuất hiện của Crick một thanh niên dễ thương. Thế nhưng dường như sự xuất hiện ấy lại làm anh không thể thoát ra khỏi bóng tối trong quá khứ.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Oscar Isaac","avatar":""},{"name":"Tiffany Haddish","avatar":""},{"name":"Tye Sheridan","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Alexander Babara","avatar":""},{"name":"Bobby C. King","avatar":""},{"name":"Ekaterina Baker","avatar":""},{"name":"Dylan Flashner","avatar":""},{"name":"Adrienne Lau","avatar":""},{"name":"Joel Michaely","avatar":""},{"name":"Rachel Michiko Whitney","avatar":""},{"name":"Britton Webb","avatar":""},{"name":"Amye Gousset","avatar":""},{"name":"Billy Slaughter","avatar":""},{"name":"Joseph Singletary","avatar":""},{"name":"Kirill Sheyner","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324326);
