INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('banh-que-mochi-dai-tiec-ngay-le', 'Bánh Quế + Mochi: Đại Tiệc Ngày Lễ', 'Waffles + Mochi''s Holiday Feast', 'https://phimimg.com/upload/vod/20231129-1/6d7f655b065983a3b6f05be702b16c4f.jpg', 'https://phimimg.com/upload/vod/20231129-1/88156985d408071134a5df1f292e42ca.jpg', '<p>Trong Ngày Đóng Băng đầu tiên, Waffles và Mochi nhận ra truyền thống ngày lễ không chỉ có đồ ăn, mà còn là việc tạo ra kỷ niệm đẹp với những người bạn yêu quí!</p>', 'Full', 1, 'single', 'completed', 7, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michelle Obama","avatar":""},{"name":"Diona Elise Burnett","avatar":""},{"name":"Taleia Gilliam","avatar":""},{"name":"Andy Hayward","avatar":""},{"name":"Jonathan Kidder","avatar":""},{"name":"George Konner","avatar":""},{"name":"Lyric Lewis","avatar":""},{"name":"Piotr Michael","avatar":""},{"name":"Ellie Nicklaw","avatar":""},{"name":"Samin Nosrat","avatar":""},{"name":"Tracee Ellis Ross","avatar":""},{"name":"Russ Walko","avatar":""},{"name":"Michelle Zamora","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324326);
