INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('banh-que-mochi-dai-tiec-ngay-le', 'Bánh Quế + Mochi: Đại Tiệc Ngày Lễ', 'Waffles + Mochi''s Holiday Feast', 'bánh quế + mochi: đại tiệc ngày lễ waffles + mochi''s holiday feast michelle obama diona elise burnett taleia gilliam andy hayward jonathan kidder george konner lyric lewis piotr michael ellie nicklaw samin nosrat tracee ellis ross russ walko michelle zamora ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-thu-han', 'Trò Chơi Thù Hận', 'The Hating Game', 'https://phimimg.com/upload/vod/20231130-1/1471cfb9635019342d6371fcfa202f97.jpg', 'https://phimimg.com/upload/vod/20231130-1/83ece30d8bb22c5404dc2cb039739ba1.jpg', '<p>Là trợ lý cho các đồng CEO của một công ty xuất bản, Lucy Hutton và Joshua Templeman ngồi đối diện nhau mỗi ngày - và họ ghét nhau. Không không thích. Không khoan dung một cách khoan dung. GHÉT BỎ. Lucy không thể hiểu cách tiếp cận niềm vui, sức khỏe của Josh của Josh đối với công việc của mình và từ chối mỉm cười, điều đó trái ngược với quần áo sáng, quầng sáng và dễ chịu. Bị mắc kẹt trong một văn phòng chia sẻ 5 ngày một tuần, họ đã trở nên cố thủ trong một trò chơi không bao giờ kết thúc gây nghiện, vô lý. Lucy không thể để Josh đánh bại cô ấy ở bất cứ điều gì - đặc biệt là khi một chương trình khuyến mãi mới lớn để quản lý giám đốc là lấy lấy. Họ tấn công một thỏa thuận mà bất cứ ai không nhận được khuyến mãi phải bỏ. Đó là trò chơi trên - nhưng như căng thẳng đạt đến điểm sôi và một chuyến đi thang máy vô tội biến thành một nụ hôn ướt át, Lucy bắt đầu nhận ra cách tốt như thế nào một dòng có giữa tình yêu và ghét.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lucy Hale","avatar":""},{"name":"Austin Stowell","avatar":""},{"name":"Yasha Jackson","avatar":""},{"name":"Sakina Jaffrey","avatar":""},{"name":"Corbin Bernsen","avatar":""},{"name":"Kathryn Boswell","avatar":""},{"name":"Shona Tucker","avatar":""},{"name":"Damon Daunno","avatar":""},{"name":"Sean Cullen","avatar":""},{"name":"Nance Williamson","avatar":""},{"name":"Brock Yurich","avatar":""},{"name":"Robby Johnson","avatar":""},{"name":"Tania Asnes","avatar":""},{"name":"Nicholas Baroudi","avatar":""},{"name":"David Ebert","avatar":""},{"name":"Crystal Tweed","avatar":""},{"name":"Kevin Carrigan","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324326);
