INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-thai-cua-trai-tim', 'Sắc Thái Của Trái Tim', 'Shades of the Heart', 'https://phimimg.com/upload/vod/20231129-1/60cdb3d51a866cc1e2feccc88272124a.jpg', 'https://phimimg.com/upload/vod/20231129-1/412d278cb83a14947c9deb093ced37c4.jpg', '<p>Sắc Thái Của Trái Tim là câu chuyện sau khi ly hôn ở nước ngoài, Chang Seok (Yeon Woo Jin) trở về Hàn Quốc và chuẩn bị xuất bản một cuốn tiểu thuyết dựa trên tự truyện của mình. Anh ấy gặp những người lạ bao gồm Sung Ha (Kim Sang Ho), Mi Young (Lee Ji Eun), Joo Eun (Lee Joo Young) và Yoo Jin (Yoon Hye Ri) tại các địa điểm khác nhau. Chang Seok lắng nghe và nghe câu chuyện của những người xung quanh và cảm thấy trái tim mình thay đổi và bắt đầu viết một câu chuyện mới.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yeon Woo-jin","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"IU","avatar":""},{"name":"Lee Joo-young","avatar":""},{"name":"Yoon Hye-ree","avatar":""},{"name":"Moon Sook","avatar":""},{"name":"Lim Sun-woo","avatar":""},{"name":"Kim Keum-soon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324326);
