INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lich-su-manchester-united', 'Lịch Sử Manchester United', 'The United Way', 'https://phimimg.com/upload/vod/20231129-1/47ba16825ff86ecd5984e0c4bab7ba67.jpg', 'https://phimimg.com/upload/vod/20231129-1/87482a2b59a1447b32d5e4f96d7f01e7.jpg', '<p>The United Way là câu chuyện huyền thoại về một trong những đội thể thao mang tính biểu tượng nhất trên thế giới, Manchester United, từ khởi đầu khiêm tốn nhất cho đến thành công lớn với hơn 650 triệu người ủng hộ trên toàn thế giới. Được trình bày bởi Eric Cantona và có Charlton, Best, Cantona, Beckham và Ronaldo, cùng với kho lưu trữ tuyệt đẹp và cảnh quay chưa từng thấy, The United Way tôn vinh hiện tượng toàn cầu về một câu lạc bộ đoàn kết do con người, vì con người.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Éric Cantona","avatar":""},{"name":"David Beckham","avatar":""},{"name":"Ole Gunnar Solskjaer","avatar":""},{"name":"Nicky Butt","avatar":""},{"name":"Bryan Robson","avatar":""},{"name":"Ryan Giggs","avatar":""},{"name":"Martin Edwards","avatar":""},{"name":"Ron Atkinson","avatar":""},{"name":"Mark Hughes","avatar":""},{"name":"Peter Schmeichel","avatar":""},{"name":"Alex Stepney","avatar":""},{"name":"Steve Bruce","avatar":""},{"name":"Arthur Albiston","avatar":""},{"name":"Tommy Docherty","avatar":""},{"name":"Sammy McIlroy","avatar":""},{"name":"David May","avatar":""},{"name":"Michael Heseltine","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324326);
