INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-sinh-ton-2021', 'Cuộc Chiến Sinh Tồn', 'Endangered Species', 'https://phimimg.com/upload/vod/20231129-1/b776f02e41407341d39cd4b0a12f8b08.jpg', 'https://phimimg.com/upload/vod/20231129-1/8c1e17c19c9edaa08c35653984040d19.jpg', '<p>Cuộc Chiến Sinh Tồn - Endangered Species (2021) xoay quanh câu chuyện về chuyến phiêu lưu đến vùng đất hoang dã ở Châu Phi của một gia đình Mỹ giàu có. Mục đích của chuyến đi là hàn gắn tình cảm gia đình đã rạn nứt trong thời gian vừa rồi. Thế nhưng ngay khi vừa đặt chân đến vùng đất này thì cả nhà bất ngờ bị tấn công bởi một con tê giác khổng lồ. Họ rơi vào tình thế ngàn cân treo sợi tóc, buộc phải tìm mọi cách để sinh tồn. Bộ phim có sự tham gia của các diễn viên gồm: Rebecca Romijn, Isabel Bassett, Philip Winchester, Michael Johnston, Jerry O&#39;Connell, Chris Fisher, Brenda Ngeso, Aseem Sharma, George Glenn Ouma, Pritul Raithatha, Stephen Adogo.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Kenya', 0, '[{"name":"Rebecca Romijn","avatar":""},{"name":"Philip Winchester","avatar":""},{"name":"Isabel Bassett","avatar":""},{"name":"Michael Johnston","avatar":""},{"name":"Chris Fisher","avatar":""},{"name":"Jerry O''Connell","avatar":""},{"name":"Brenda Ngeso","avatar":""},{"name":"George Glenn Ouma","avatar":""},{"name":"Aseem Sharma","avatar":""},{"name":"Pritul Raithatha","avatar":""},{"name":"Stephen Adogo","avatar":""},{"name":"Danica Davis","avatar":""},{"name":"Kirk Fonda","avatar":""},{"name":"Isaac Naiganya","avatar":""},{"name":"Matthew Owiti","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324326);
