INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-y-quan', 'Yêu Y Quán', 'Monster Hospital', 'https://phimimg.com/upload/vod/20231129-1/c6b20313ca0f5fdfbc25c28026c44559.jpg', 'https://phimimg.com/upload/vod/20231129-1/48671b172926e76eda7e908db36258aa.jpg', '<p>Tam giới có một bệnh viện chỉ chữa bệnh cho yêu quái mà không cứu chữa con người. Hôm nọ, thư sinh Kim Chí Kiên không mời mà đến. Hóa ra chàng bị trồng “Ma Hoàn” thượng cổ vào bụng. Bác sĩ Hồng Nương dốc lòng chăm sóc Ma Hoàn mà mối tình hữu nghị nảy sinh giữa một người và một thú này. Hồng Nương quyết tâm thả Ma Hoàn, lại bị Huyền Giáp Môn vây chặt. Hóa ra tất cả mọi việc đều là âm mưu của trưởng môn Hùng Khôi...</p>', 'Full', 1, 'single', 'completed', 23, 2021, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Raquel Xu","avatar":""},{"name":"Ming Junchen","avatar":""},{"name":"Jingyi Zhang","avatar":""},{"name":"Zhang Fengjun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324326);
