INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('some-like-it-rare', 'Some Like It Rare', 'Barbaque', 'https://phimimg.com/upload/vod/20231128-1/4493372deda3864c9dcf847b96097c0f.jpg', 'https://phimimg.com/upload/vod/20231128-1/41b914f9354fe7375d0be9de9cba37f8.jpg', '<p>Cửa hàng bán thịt nhỏ của Sophie và Vincent đang trên bờ vực phá sản và cuộc hôn nhân của họ tan vỡ. Cuộc sống của họ bị đảo lộn khi Vincent vô tình giết một nhà hoạt động thuần chay đã phá hoại cửa hàng của họ. Quá choáng ngợp và sợ hãi khi bị buộc tội giết người, giải pháp duy nhất của họ là phi tang thi thể bằng cách biến nó thành giăm bông. Trước sự ngạc nhiên của họ, giăm bông phổ biến đến mức có thể cứu công việc kinh doanh của họ… đó là nếu họ sẵn sàng tiếp tục “săn”!</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Fabrice Eboué","avatar":""},{"name":"Marina Foïs","avatar":""},{"name":"Virginie Hocq","avatar":""},{"name":"Jean-François Cayrey","avatar":""},{"name":"Lisa Do Couto Texeira","avatar":""},{"name":"Victor Meutelet","avatar":""},{"name":"Stéphane Soo Mongo","avatar":""},{"name":"Nicolas Lumbreras","avatar":""},{"name":"Alexia Chardard","avatar":""},{"name":"Franck Migeon","avatar":""},{"name":"Colette Sodoyez","avatar":""},{"name":"Roby Schinasi","avatar":""},{"name":"Ted Etienne","avatar":""},{"name":"Alexis Pujol","avatar":""},{"name":"Tom Pezier","avatar":""},{"name":"Sébastie","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324326);
