INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-hyacinth', 'Chiến Dịch Hyacinth', 'Operation Hyacinth', 'https://phimimg.com/upload/vod/20231127-1/2391da7bf73d5fe5a6b906fca4b7155f.jpg', 'https://phimimg.com/upload/vod/20231127-1/9adbb063905bdf0d5123914d1bdb5880.jpg', '<p>Không hài lòng với kết quả điều tra một vụ án mạng trong giới đồng tính ở Warsaw, viên sĩ quan cộng sản những năm 1980 quyết tự mình lật mở sự thật.</p>', 'Full', 1, 'single', 'completed', 21, 2021, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Tomasz Zietek","avatar":""},{"name":"Hubert Miłkowski","avatar":""},{"name":"Adrianna Chlebicka","avatar":""},{"name":"Tomasz Schuchardt","avatar":""},{"name":"Marek Kalita","avatar":""},{"name":"Mirosław Zbrojewicz","avatar":""},{"name":"Sebastian Stankiewicz","avatar":""},{"name":"Piotr Trojan","avatar":""},{"name":"Jacek Poniedziałek","avatar":""},{"name":"Agnieszka Suchora","avatar":""},{"name":"Tomasz Włosok","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324326);
