INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-dem', 'NỬA ĐÊM', 'Midnight', 'https://phimimg.com/upload/vod/20231126-1/0c4189d13e885e771a2910be81f75f66.jpg', 'https://phimimg.com/upload/vod/20231126-1/c1369ea752ef305f713c2f2197d2537d.jpg', '<p>Nửa Đêm xoay quanh câu chuyện của Kyung-Mi, cô gái có vấn đề về thính giác và đang làm cố vấn ký hiệu tại một trung tâm cuộc gọi. Vào ban đêm, trên một con phố ở Seoul, cô gặp kẻ giết người hàng loạt Do-Sik.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jin Ki-joo","avatar":""},{"name":"Wi Ha-jun","avatar":""},{"name":"Park Hoon","avatar":""},{"name":"Kil Hae-yeon","avatar":""},{"name":"Kim Hye-yoon","avatar":""},{"name":"Lee Sang-hee","avatar":""},{"name":"Park Ji-hoon","avatar":""},{"name":"Eun-Woo Bae","avatar":""},{"name":"Min-woo Choi","avatar":""},{"name":"Oh Ji-young","avatar":""},{"name":"Jung Won-chang","avatar":""},{"name":"Im Sung Mi","avatar":""},{"name":"Noh Su Min","avatar":""},{"name":"Na Eun-saem","avatar":""},{"name":"Shin Mi-yeong","avatar":""},{"name":"Song You-hyun","avatar":""},{"name":"Na Yoon-sung","avatar":""},{"name":"In-woo Kim","avatar":""},{"name":"Kim Yoo-ri","avatar":""},{"name":"Kim","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324326);
