INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hard-luck-love-song', 'Hard Luck Love Song', 'Hard Luck Love Song', 'https://phimimg.com/upload/vod/20231129-1/a29bd7f9e30a1b41dafd8e1257adbf04.jpg', 'https://phimimg.com/upload/vod/20231129-1/fa5656983f0c38782ba61866c6bd5b77.jpg', '<p>Một câu chuyện tình yêu gritty về một sự lôi cuốn nhưng hạ thấp sự khó khăn của anh ta sống ngoài những nhà nghỉ giá rẻ và đưa ra những quyết định tồi tệ.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Dorman","avatar":""},{"name":"Sophia Bush","avatar":""},{"name":"RZA","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Brian Sacca","avatar":""},{"name":"Melora Walters","avatar":""},{"name":"Randal Reeder","avatar":""},{"name":"Zac Badasci","avatar":""},{"name":"Max Arciniega","avatar":""},{"name":"Biff Wiff","avatar":""},{"name":"Geri Courtney-Austein","avatar":""},{"name":"Toni Robison-May","avatar":""},{"name":"Taylor Gray","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324326);
