INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-con-hu-don', 'Đám Con Hư Đốn', 'Spoiled Brats', 'https://phimimg.com/upload/vod/20231125-1/bda007fcb03df7827afad48ba15292fe.jpg', 'https://phimimg.com/upload/vod/20231125-1/9f72ae5199793c276f6b68b4cbf93778.jpg', '<p>Spoiled Brats xoay quanh câu chuyện về Francis Bartek là một vị triệu phú giàu có, ông có những người con vô cùng hư hỏng và ăn chơi, chỉ vì ông giàu. Không những thế chúng còn luôn kiếm tiền từ tài sản của ông mà không phải làm việc. Vì quá mệt mỏi với tính cách của các con mình. Nên Francis Bartek đã quyết định nghĩ ra một kế hoạch để thay đổi tính cách bọn chúng. Đó là ông giả vờ sự nghiệp làm ăn thất bại và trở nên phá sản. Lúc này, khi những người con của ông không còn chổ dựa nên quyết định học tập cách làm việc, trân trọng mọi thứ mình có và yêu thương gia đình</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Gérard Jugnot","avatar":""},{"name":"Camille Lou","avatar":""},{"name":"Artus","avatar":""},{"name":"Louka Meliava","avatar":""},{"name":"François Morel","avatar":""},{"name":"Tom Leeb","avatar":""},{"name":"Clara Joly","avatar":""},{"name":"Jean-Baptiste Sagory","avatar":""},{"name":"Colette Kraffe","avatar":""},{"name":"Franck Adrien","avatar":""},{"name":"Joffrey Verbruggen","avatar":""},{"name":"Eléa Clair","avatar":""},{"name":"Fabien Ara","avatar":""},{"name":"Ichem Bougheraba","avatar":""},{"name":"Guillaume Méry","avatar":""},{"name":"Victor Sansano","avatar":""},{"name":"Eric Marcel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324326);
