INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('amanda-cua-toi', 'Amanda Của Tôi', 'My Amanda', 'https://phimimg.com/upload/vod/20231125-1/47cba8978867f19523d621eefba79198.jpg', 'https://phimimg.com/upload/vod/20231125-1/02612c63699b1323299d8eb92f6905f9.jpg', '<p>Đôi bạn thân thiết một cách lạ thường chia sẻ với nhau về mọi mặt của cuộc sống. Rồi cuộc sống cả hai dần thay đổi, chỉ có sự gắn kết của họ là vẫn nguyên.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Alessandra de Rossi","avatar":""},{"name":"Piolo Pascual","avatar":""},{"name":"Luz Valdez","avatar":""},{"name":"KC Montero","avatar":""},{"name":"Alexander Medina","avatar":""},{"name":"Helga Krapf","avatar":""},{"name":"Joyce Ann Burton","avatar":""},{"name":"Jess Mendoza","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324326);
