INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hong-hi-quan-yeu-nu-ma-mon', 'Hồng Hi Quan: Yêu Nữ Ma Môn', 'The Legend and Hag of Shaolin', 'https://phimimg.com/upload/vod/20231125-1/03bbc5aa8dbeff477eb811a237a34aa5.jpg', 'https://phimimg.com/upload/vod/20231125-1/3ea6a1971829e31a701610e0a070ebce.jpg', '<p>Trong thời kỳ Khang Hi triều Thanh, nhằm thực hiện chí nguyện của sư phụ Thái Cửu Nghi đã chết, đệ tử Thiếu Lâm Hồng Hi Quan và sư đệ Phương Thế Ngọc đến với Quảng Châu tuyên truyền và phát huy võ thuật Thiếu Lâm. Trong quá trình chạm trán với thế lực Ngô Tam Quế, triều đình và quyền sư Quảng Đông, Hồng Hi Quan dần dần làm cho võ thuật Thích Gia Quân Minh mạt, công phu Thiếu Lâm và quyền thuật Quảng Đông dung hợp lại, sáng lập “Hồng Môn” gom góp ưu điểm võ thuật của các môn phái.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Gu Shangwei","avatar":""},{"name":"Vincent Zhao Wenzhuo","avatar":""},{"name":"Jingpei Zhao","avatar":""},{"name":"Yang Yunran","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324326);
