INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('arsene-wenger-bat-kha-chien-bai', 'Arsène Wenger: Bất Khả Chiến Bại', 'Arsène Wenger: Invincible', 'https://phimimg.com/upload/vod/20231125-1/6187f6b2efa92a4a1aee63a5bd7d5f11.jpg', 'https://phimimg.com/upload/vod/20231125-1/e7b981258df46819b3f727febf1629d6.jpg', '<p>Được xây dựng dựa trên bối cảnh của mùa giải lịch sử “Bất khả chiến bại” của Arsenal 2003-04, lần đầu tiên và duy nhất một đội đã trải qua toàn bộ chiến dịch Premier League mà không bị đánh bại, bộ phim cho thấy Wenger phản ánh thẳng thắn về kỷ nguyên cách mạng của ông tại Arsenal cũng như cảm xúc và cá nhân tình trạng hỗn loạn bao quanh lối ra gây tranh cãi của ông sau 22 năm.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Arsène Wenger","avatar":""},{"name":"Dennis Bergkamp","avatar":""},{"name":"David Dein","avatar":""},{"name":"Lee Dixon","avatar":""},{"name":"Alex Ferguson","avatar":""},{"name":"Thierry Henry","avatar":""},{"name":"Martin Keown","avatar":""},{"name":"Emmanuel Petit","avatar":""},{"name":"Robert Pirès","avatar":""},{"name":"Patrick Vieira","avatar":""},{"name":"Ian Wright","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324326);
