INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-gia-noel-tro-lai', 'Ông Già Noel Trở Lại', 'Father Christmas Is Back', 'https://phimimg.com/upload/vod/20231124-1/83ed1758898f3fa6cada164e505d89c4.jpg', 'https://phimimg.com/upload/vod/20231124-1/5c9c5336ce52b518106d6a16d5f9a0e9.jpg', '<p>Bốn chị em bất hòa có bài học cấp tốc về tình cảm gia đình khi ông bố mất tích từ lâu của họ xuất hiện vào Giáng sinh ở trang viên xa hoa của tổ tiên họ.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Nathalie Cox","avatar":""},{"name":"Talulah Riley","avatar":""},{"name":"Elizabeth Hurley","avatar":""},{"name":"Kelsey Grammer","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Caroline Quentin","avatar":""},{"name":"April Bowlby","avatar":""},{"name":"Kris Marshall","avatar":""},{"name":"Ray Fearon","avatar":""},{"name":"Katy Brand","avatar":""},{"name":"Ania Marson","avatar":""},{"name":"Naomi Frederick","avatar":""},{"name":"Amelie Prescott","avatar":""},{"name":"Janie Booth","avatar":""},{"name":"Bryan Samson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324326);
