INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ong-gia-noel-tro-lai', 'Ông Già Noel Trở Lại', 'Father Christmas Is Back', 'ông già noel trở lại father christmas is back nathalie cox talulah riley elizabeth hurley kelsey grammer john cleese caroline quentin april bowlby kris marshall ray fearon katy brand ania marson naomi frederick amelie prescott janie booth bryan samson ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-vong-tu-hon-dao-chet', 'Tiếng Vọng Từ Hòn Đảo Chết', 'The Block Island Sound', 'https://phimimg.com/upload/vod/20231124-1/ca5c304a55f3685786d40b6261e14e57.jpg', 'https://phimimg.com/upload/vod/20231124-1/164779873e799d9551d7bfe267a6da7a.jpg', '<p>Tiếng Vọng Từ Hòn Đảo Chết - The Block Island Sound (2020) phim có nhiều tính tiết bị ẩn, siêu nhiên và có cả kinh dị của nhóm đạo diễn Matthew McManus, Kevin McManus. Phim sẽ đưa chúng ta cùng theo chân cô gái tên Audry Lynch người vừa từ đảo Block về nhà, sẽ chẳng có gì đặc biệt nếu như không có chuyện gì xảy ra. Tuy nhiên, sau chuyến đi này cha của Audry Lynch là Archambault có biểu hiện bị điên loạn vì ảo giác, ông còn mất trí nhớ. Một đêm nọ đã gia đình cô xảy ra biến cố, sự mất tích của Archambault khiến cho cô gái cùng người anh trai tên Harry lo lắng vô cùng. Họ cùng nhau tìm kiếm cha, sâu chuỗi mọi sự kiện hai anh em vô cùng bất ngờ khi nó có liên quan tới hòn đảo Block. Bắt đầu từ đây cuộc sống của Audry và gia đình bị đảo lộn, vô vàn nguy hiểm đang đợi chờ họ trên hành trình tìm cha.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michaela McManus","avatar":""},{"name":"Chris Sheffield","avatar":""},{"name":"Neville Archambault","avatar":""},{"name":"Matilda Lawler","avatar":""},{"name":"Ryan O''Flanagan","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Heidi Niedermeyer","avatar":""},{"name":"Jeremy Holm","avatar":""},{"name":"Willie C. Carpenter","avatar":""},{"name":"Matthew Lawler","avatar":""},{"name":"Robyn Payne","avatar":""},{"name":"PJ McCabe","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf407791667