INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('its-not-you-its-me', 'It''s Not You, It''s Me', 'It''s Not You, It''s Me', 'https://phimimg.com/upload/vod/20231124-1/7ccbdd771083d0ab589690a0577931ea.jpg', 'https://phimimg.com/upload/vod/20231124-1/547ab663e5d0cd4179cf9fa98eb32230.jpg', '<p>Khi Jason phát hiện ra cuộc hôn nhân của mình có thể bị sụp đổ trước khi bắt đầu, anh ta bắt đầu cuộc hành trình tìm hiểu loại bạn trai của anh ta đến từ người yêu cũ.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeff Friedman","avatar":""},{"name":"Michaella Russell","avatar":""},{"name":"Cherish Holland","avatar":""},{"name":"Audra Van Hees","avatar":""},{"name":"Indi Rossi","avatar":""},{"name":"Max Raines","avatar":""},{"name":"Anna Greene","avatar":""},{"name":"Morgan Hunt","avatar":""},{"name":"Angela Smeraldi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324326);
