INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-ma-mua-ha', 'Hồn Ma Mùa Hạ', 'Summer Ghost', 'https://phimimg.com/upload/vod/20231124-1/4cdee3142720e3539e8b7a2392ae45e5.jpg', 'https://phimimg.com/upload/vod/20231124-1/4b56d74591b1a3f572a2b49dff4e251e.jpg', '<p>Tomoya, Aoi và Ryo là những học sinh trung học tình cờ gặp gỡ nhau trên mạng. Họ đều được nghe về một truyền thuyết đô thị nói về một “hồn ma mùa hè”, một linh hồn của một cô gái sẽ xuất hiện khi pháo hoa cháy sáng. Tomoya không thể sống cuộc sống mà cậu ấy đã hình dung cho chính mình. Aoi không thể tìm thấy vị trí của mình trên thế giới. Ryo từng có một tương lai tươi sáng nay đã bị tước bỏ. Mỗi người đều có một lý do riêng để cần gặp hồn ma mùa hè. Vào một đêm hè khi sự sống và cái chết giao thoa lẫn nhau, mỗi cung bậc cảm xúc của họ sẽ đưa họ đến nơi đâu?</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Chiaki Kobayashi","avatar":""},{"name":"Miyuri Shimabukuro","avatar":""},{"name":"Rina Kawaei","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324326);
