INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-sau-su-that', 'Lỗ Sâu Sự Thật', 'The Whole Truth', 'https://phimimg.com/upload/vod/20231124-1/9d84a5660ae8995ddcb056eb992117a9.jpg', 'https://phimimg.com/upload/vod/20231124-1/b5cb8675aa6025d79a5572e80f421d5a.jpg', '<p>Khi hai chị em vô tình phát hiện một cái lỗ kỳ lạ trên tường nhà ông bà, những vụ việc kinh hoàng xảy ra làm hé lộ những bí mật hiểm ác về gia đình họ.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Sompob Benjathikul","avatar":""},{"name":"Tarika Thidathit","avatar":""},{"name":"Sutatta Udomsilp","avatar":""},{"name":"Nattapat Nimjirawat","avatar":""},{"name":"Nicole Theriault","avatar":""},{"name":"Sadanont Durongkhaweroj","avatar":""},{"name":"Keetapat Pongruea","avatar":""},{"name":"Thasorn Klinnium","avatar":""},{"name":"Steven Isarapong Fuhrer","avatar":""},{"name":"Atichart Lee","avatar":""},{"name":"Ronnaporn Kanivichaporn","avatar":""},{"name":"Chalita Mangkornpunt","avatar":""},{"name":"Surapol Poon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324326);
