INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-nang-hoang-dai', 'Bản Năng Hoang Dại', 'Voyagers', 'https://phimimg.com/upload/vod/20231124-1/e29cc8b8cbdb4a19480f7b14244832ed.jpg', 'https://phimimg.com/upload/vod/20231124-1/c1a6037ef99d5fb3bdd03bad4654d8dc.jpg', '<p>Trong một tương lai không xa khi nhân loại đang trên bờ vực diệt chủng, một nhóm thanh thiếu niên được nuôi dưỡng để phục vụ cho mục đích khai thác trí tuệ và chấp nhận sai khiến. Họ bắt đầu một chuyến hành trình thám hiểm khai phá một hành tinh xa xôi khác. Nhưng khi họ phát hiện ra bí mật được che giấu đằng sau nhiệm vụ cao cả này, tất cả bắt đầu kháng cự lại việc huấn luyện này và bắt đầu để bản năng nguyên thuỷ lấn chiếm cảm xúc. Khi vận mệnh của cả phi đoàn rơi vào hỗn loạn, họ bị chôn vùi trong sợ hãi, ham muốn và cơn khao khát quyền lực.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tye Sheridan","avatar":""},{"name":"Lily-Rose Depp","avatar":""},{"name":"Fionn Whitehead","avatar":""},{"name":"Colin Farrell","avatar":""},{"name":"Chanté Adams","avatar":""},{"name":"Viveik Kalra","avatar":""},{"name":"Archie Madekwe","avatar":""},{"name":"Quintessa Swindell","avatar":""},{"name":"Isaac Hempstead-Wright","avatar":""},{"name":"Madison Hu","avatar":""},{"name":"Archie Renaux","avatar":""},{"name":"Wern Lee","avatar":""},{"name":"Veronica Falcón","avatar":""},{"name":"Laura Dreyfuss","avatar":""},{"name":"April Grace","avatar":""},{"name":"Patrick Bucur","avatar":""},{"name":"Rufus B","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324326);
