INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ramo-phan-2', 'Ramo (Phần 2)', 'Ramo (Season 2)', 'https://phimimg.com/upload/vod/20231204-1/c286038c3d0c9ff0f05f28a5d0b8748e.jpg', 'https://phimimg.com/upload/vod/20231204-1/241593488cb05a4d91f57161301780b3.jpg', '<p>Cú sốc lớn nhất đối với Ramo, người được tái sinh từ đống tro tàn trong những năm tháng trong tù, là sự phản bội của Sibel. Không bao giờ nghi ngờ rằng Sibel phản bội mình, Ramo phải giải một câu đố khác, tại sao Sibel lại làm điều này. Kế hoạch của Ramo khá rõ ràng. Kết thúc Cihangir và vương quốc của hắn!Phản ứng của Ramo với Yavuz Bey, người đã cảnh báo anh, phản ánh sự quyết tâm và táo bạo của anh. Tôi đủ cho 24 giờ!</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 19, 2021, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Murat Yildirim","avatar":""},{"name":"Esra Bilgic","avatar":""},{"name":"Ilker Aksum","avatar":""},{"name":"Yigit Ozsener","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324326);
