INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-mong-ma-quai', 'Ảo Mộng Ma Quái', 'Fever Dream', 'https://phimimg.com/upload/vod/20231123-1/5ddbad977a8fe1bc37fe06f9154302ce.jpg', 'https://phimimg.com/upload/vod/20231123-1/e99ab9feb29da3b4e2f8799d6ceb4f06.jpg', '<p>Một người phụ nữ tên Amanda nằm đau khổ, xa nhà. Một cậu bé tên David hỏi cô, cố gắng làm cô nhớ lại. Cô ấy không phải là mẹ anh ấy, anh ấy không phải con trai cô ấy. Khi thời gian của cô không còn nhiều, anh giúp cô làm sáng tỏ một câu chuyện mạnh mẽ, đầy ám ảnh về sự ghen tuông ám ảnh, một mối nguy hiểm vô hình và sức mạnh tình yêu của người mẹ dành cho con mình.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"María Valverde","avatar":""},{"name":"Guillermo Pfening","avatar":""},{"name":"Dolores Fonzi","avatar":""},{"name":"Germán Palacios","avatar":""},{"name":"Emilio Vodanovich","avatar":""},{"name":"Guillermina Sorribes Liotta","avatar":""},{"name":"Marcelo Michinaux","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324326);
