INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-dua-quyen-nang-linh-hon-samurai', 'Chiếc Đũa Quyền Năng: Linh Hồn Samurai', 'Bright: Samurai Soul', 'https://phimimg.com/upload/vod/20231123-1/46fe458d2f3a92365737366b02f3dc1b.jpg', 'https://phimimg.com/upload/vod/20231123-1/1f2fb27269833ce14c524ba8384bd748.jpg', '<p>Nằm ở Nhật Bản trong phần cuối của Mạc phủ và sự khởi đầu của giai đoạn Meiji, bộ phim sẽ theo một samurai một mắt, lang thang tên là Izo (Simu Liu) và một Orc tên Raiden (Fred Mancuso), khi họ làm việc để mang đến một Cô gái Elf trẻ (Yuzu Harada) và cây đũa phép mà cô mang đến vùng đất của yêu tinh ở phía bắc.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yuuki Nomura","avatar":""},{"name":"Daisuke Hirakawa","avatar":""},{"name":"Shion Wakayama","avatar":""},{"name":"MIYAVI","avatar":""},{"name":"Maaya Sakamoto","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Mamoru Miyano","avatar":""},{"name":"Kenichi Suzumura","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324326);
