INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('titane', 'Titane', 'Titane', 'https://phimimg.com/upload/vod/20231123-1/19956684f45638f5a84e100553ba33ad.jpg', 'https://phimimg.com/upload/vod/20231123-1/cd39d322a5b0b960bb49012461b5e65c.jpg', '<p>Một người phụ nữ với một chiếc đĩa kim loại trên đầu sau một vụ tai nạn xe hơi thời thơ ấu bắt đầu một cuộc hành trình kỳ lạ, đưa cô tiếp xúc với một người lính cứu hỏa, người đoàn tụ với đứa con trai mất tích của anh ta sau 10 năm.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Agathe Rousselle","avatar":""},{"name":"Vincent Lindon","avatar":""},{"name":"Garance Marillier","avatar":""},{"name":"Laïs Salameh","avatar":""},{"name":"Mara Cissé","avatar":""},{"name":"Marin Judas","avatar":""},{"name":"Diong-Kéba Tacu","avatar":""},{"name":"Myriem Akheddiou","avatar":""},{"name":"Bertrand Bonello","avatar":""},{"name":"Céline Carrère","avatar":""},{"name":"Adèle Guigue","avatar":""},{"name":"Thibault Cathalifaud","avatar":""},{"name":"Dominique Frot","avatar":""},{"name":"Lamine Cissokho","avatar":""},{"name":"Florence Janas","avatar":""},{"name":"Frédéric","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324326);
