INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jje', 'JJ+E', 'JJ+E', 'https://phimimg.com/upload/vod/20231123-1/6e06832c91bc2b5d0177a16fc145b0fb.jpg', 'https://phimimg.com/upload/vod/20231123-1/555898366d9c71feadd216fa21cd679c.jpg', '<p>Elisabeth và John-John ở cùng một thành phố, nhưng họ sống trong những thế giới khác nhau. Liệu mối tình đầu mãnh liệt có thể phá vỡ rào cản giai cấp và văn hóa?</p>', 'Full', 1, 'single', 'completed', 17, 2021, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Mustapha Aarab","avatar":""},{"name":"Elsa Öhrn","avatar":""},{"name":"Magnus Krepper","avatar":""},{"name":"Marika Lagercrantz","avatar":""},{"name":"Simon Mezher","avatar":""},{"name":"Loreen","avatar":""},{"name":"Albin Grenholm","avatar":""},{"name":"Jonay Pineda Skallak","avatar":""},{"name":"Elsa Bergström Terent","avatar":""},{"name":"Otto Hargne","avatar":""},{"name":"Josef Kadim","avatar":""},{"name":"Yohannes Frezgi","avatar":""},{"name":"Edvin Wassberg","avatar":""},{"name":"Nikie Pourfallah","avatar":""},{"name":"Sandra Strandberg Zubovic","avatar":""},{"name":"Jenna","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324326);
