INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-truy-quet-ma-tuy', 'Biệt Đội Truy Quét Ma Túy', 'Drug Hunting Operation', 'https://phimimg.com/upload/vod/20231123-1/a70c9b1b6f6137cf51752d7653e8a0fc.jpg', 'https://phimimg.com/upload/vod/20231123-1/f8918ba6ce5ea8682b7794e328429a69.jpg', '<p>Cảnh sát phòng chống ma túy trẻ tuổi Vương Hâm vừa kết thúc sự huấn luyện đặc biệt mà từ Nam Mỹ trở về. Nhằm phá vỡ âm mưu của trùm ma túy quốc tế Kim Gia, anh được đội trưởng Lý Quảng Phong dẫn dắt, phát động một hành động phòng chống ma túy với tên “Hành động bắn tỉa chớp nhoáng”, đối đầu với người buôn ma túy thâm độc nham hiểm Hứa Đạt Hồng. Đen trắng đối đầu nhau, chính tà chạm trán nhau, cảnh sát phòng chống ma tuy tiền tuyến nhờ vào tinh thần anh dũng, ngoan cường và hy sinh, triển khai một cuộc chiến bắt buôn ma túy ở bên bờ biển.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ryan Zhang","avatar":""},{"name":"Li Xinzhe","avatar":""},{"name":"Wu Chunyi","avatar":""},{"name":"Pang Hao-Feng","avatar":""},{"name":"Cheng Chu-Fung","avatar":""},{"name":"Jin Luying","avatar":""},{"name":"Basa","avatar":""},{"name":"Zheng Dong","avatar":""},{"name":"Jiang Xiaolin","avatar":""},{"name":"Li Qianfeng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324326);
