INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('whispering-corridors-the-humming', 'Whispering Corridors: The Humming', 'Whispering Corridors: The Humming', 'https://phimimg.com/upload/vod/20231123-1/b0d0a6cbeb0f2236b603ce77106c0f17.jpg', 'https://phimimg.com/upload/vod/20231123-1/091acaea013f815f660da243d50300e4.jpg', '<p>Những điều kỳ lạ xảy ra trong nhà vệ sinh kín của trường cũ của Eunhee, nơi cô ấy là phó của cô gái đầu. Hayeong và Soyeon, người đã sử dụng nơi ẩn náu của họ, tin rằng có một con ma ở đó sau khi họ nghe thấy một âm thanh ngân nga vang vọng trong nhà vệ sinh, ngay cả khi không có ai khác. Với một cái nồi thực vật được phát hiện bởi cơ hội là bằng chứng, Hayeong tin rằng bí ẩn được liên kết với Eunhee, và sau khi bị buộc tội, Eunhee bị ảo giác thị giác và thính giác. Cô cũng bị thuyết phục rằng cô đã được gọi đó sau khi thấy nữ sinh viên bị thương phải đối mặt trên khắp trường học cũ.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Seo-hyung","avatar":""},{"name":"Kim Hyun-soo","avatar":""},{"name":"Choi Ri","avatar":""},{"name":"BIBI","avatar":""},{"name":"Seo Hye-won","avatar":""},{"name":"Park Se-hyun","avatar":""},{"name":"Lee Ji-won","avatar":""},{"name":"Jang Won-hyung","avatar":""},{"name":"Kwon Hae-hyo","avatar":""},{"name":"Lee Joo-sil","avatar":""},{"name":"Chae Won-been","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324326);
