INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-hoi-tiec', 'Không Hối Tiếc', 'Without Remorse', 'https://phimimg.com/upload/vod/20231120-1/acb4bedf8e47e013b615915fe8b6695c.jpg', 'https://phimimg.com/upload/vod/20231120-1/d8aaebc40b785fd156dc8f58c57683b9.jpg', '<p>Cốt truyện của tác phẩm theo chân John Kelly, một đặc vụ SEAL của Hải quân Hoa Kỳ bắt đầu con đường trả thù sau khi người vợ đang mang thai của anh ta và các thành viên trong đơn vị bị sát hại bởi những kẻ sát nhân người Nga. &nbsp;Anh ta phải hợp tác với đồng nghiệp cũng là hải quân SEAL Karen Greer ( Jodie Turner-Smith ) và đặc vụ CIA mờ ám Robert Ritter &nbsp;( Jamie Bell ). Kelly cố gắng tìm ra sự thật kẻ đứng đằng sau các vụ tấn công, trong quá trình điều tra, anh đã phát hiện ra âm mưu bí mật chắc chắn sẽ dẫn tới chiến tranh, Kelly phải chiến đấu với kẻ thù của mình để ngăn chặn những thảm hoạ sắp xảy ra.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael B. Jordan","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Guy Pearce","avatar":""},{"name":"Jodie Turner-Smith","avatar":""},{"name":"Lauren London","avatar":""},{"name":"Brett Gelman","avatar":""},{"name":"Jacob Scipio","avatar":""},{"name":"Jack Kesy","avatar":""},{"name":"Colman Domingo","avatar":""},{"name":"Todd Lasance","avatar":""},{"name":"Cam Gigandet","avatar":""},{"name":"Luke Mitchell","avatar":""},{"name":"Stephanie McIntyre","avatar":""},{"name":"Adrian Rawlins","avatar":""},{"name":"Lucy Russell","avatar":""},{"name":"Robert Maaser","avatar":""},{"name":"Gina Jun","avatar":""},{"name":"Rae","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"