INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('demigod', 'Demigod', 'Demigod', 'https://phimimg.com/upload/vod/20231120-1/c678d789330a08b0ed6e45e471b0027a.jpg', 'https://phimimg.com/upload/vod/20231120-1/a1ab116aeeb3aaec5e41785eba146c4e.jpg', '<p>Khi cái chết của ông nội, một người phụ nữ và chồng trở về nơi sinh của mình trong khu rừng đen của Đức, chỉ để tìm một bí mật đáng sợ đang chờ đợi họ.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rachel Nichols","avatar":""},{"name":"Yohance Myles","avatar":""},{"name":"Miles Doleac","avatar":""},{"name":"Sherri Eakin","avatar":""},{"name":"Lindsay Anne Williams","avatar":""},{"name":"Mike Mayhall","avatar":""},{"name":"Christian Stokes","avatar":""},{"name":"Rachel Ryals","avatar":""},{"name":"Chukwuma Onwuchekwa","avatar":""},{"name":"Tatiana Piper","avatar":""},{"name":"Sarah Fisher","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324326);
