INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-ay-la-tat-ca', 'Anh Ấy Là Tất Cả', 'He''s All That', 'https://phimimg.com/upload/vod/20231116-1/b244eb5a3599b01e6941e83dd334ce44.jpg', 'https://phimimg.com/upload/vod/20231116-1/41b15a5d23461c979d31829a2dd212cc.jpg', '<p>Cô gái nổi tiếng giỏi tân trang ngoại hình cá cược rằng cô có thể biến chàng bạn học mờ nhạt thành vua vũ hội. Làm lại từ phim tuổi teen kinh điển “Em là tất cả”.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Addison Rae","avatar":""},{"name":"Tanner Buchanan","avatar":""},{"name":"Madison Pettis","avatar":""},{"name":"Rachael Leigh Cook","avatar":""},{"name":"Peyton Meyer","avatar":""},{"name":"Isabella Crovetti","avatar":""},{"name":"Annie Jacob","avatar":""},{"name":"Myra Molloy","avatar":""},{"name":"Matthew Lillard","avatar":""},{"name":"Kourtney Kardashian Barker","avatar":""},{"name":"Hallie Samuels","avatar":""},{"name":"Andrew Matarazzo","avatar":""},{"name":"Heather Ann Gottlieb","avatar":""},{"name":"Vanessa Dubasso","avatar":""},{"name":"Romel de Sil","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324326);
