INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-perfect-enemy', 'A Perfect Enemy', 'A Perfect Enemy', 'https://phimimg.com/upload/vod/20231116-1/30c8feab08152c2f03be7663b8f3b329.jpg', 'https://phimimg.com/upload/vod/20231116-1/7c58888e8a2b356d0cc65c3849301a12.jpg', '<p>Kiến trúc sư thành công Jeremiasz Angust được tiếp cận trong chuyến đi đến Sân bay Paris bởi một cô gái Chatty tên là Texel Textor. Cô là một phụ nữ trẻ kỳ lạ, dường như đang tìm kiếm những nạn nhân bị giam giữ mà cô buộc phải lắng nghe những câu chuyện kỳ lạ của mình. Jeremy mất chuyến bay vì Texel và một khi chúng được lắp đặt trong khu vực phòng khách, anh ta sẽ không thể thoát khỏi người xa lạ gây phiền nhiễu. Mặc dù cuộc họp có vẻ là tình cờ, sẽ sớm có một bước ngoặt sẽ biến đổi tính cách của cuộc gặp gỡ đó thành một thứ gì đó độc ác và tội phạm nhiều hơn.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Tomasz Kot","avatar":""},{"name":"Athena Strates","avatar":""},{"name":"Marta Nieto","avatar":""},{"name":"Dominique Pinon","avatar":""},{"name":"Felizia Trube","avatar":""},{"name":"Julian Helmes","avatar":""},{"name":"Freyja Simpson","avatar":""},{"name":"Sebastian Ghandchi","avatar":""},{"name":"Nerea Jordana","avatar":""},{"name":"Götz Vogel von Vogelstein","avatar":""},{"name":"Barbara Stollhans","avatar":""},{"name":"George Strassburg","avatar":""},{"name":"Janosh Hetzel","avatar":""},{"name":"Clara Immel","avatar":""},{"name":"Stefanie Früchtenicht","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324326);
