INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-tuan-nang-ha', 'Một Tuần Nắng Hạ', 'A Week Away', 'https://phimimg.com/upload/vod/20231119-1/b7b988867f8b79c64d67d5b473c8f947.jpg', 'https://phimimg.com/upload/vod/20231119-1/bc35ff558c6bbf97b4fd07e52a56aadf.jpg', '<p>Trong phim ca nhạc đầy hứng khởi này, một thiếu niên gặp rắc rối phải liều tham gia trại hè – và bất ngờ tìm được tình yêu, bạn bè và một nơi để gắn bó</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bailee Madison","avatar":""},{"name":"Kevin G. Quinn","avatar":""},{"name":"Sherri Shepherd","avatar":""},{"name":"David Koechner","avatar":""},{"name":"Jahbril Cook","avatar":""},{"name":"Kat Conner Sterling","avatar":""},{"name":"Iain Tucker","avatar":""},{"name":"Ed Amatrudo","avatar":""},{"name":"Hutch Greene","avatar":""},{"name":"Josh Rasile","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324326);
