INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-tuan-nang-ha', 'Một Tuần Nắng Hạ', 'A Week Away', 'một tuần nắng hạ a week away bailee madison kevin g. quinn sherri shepherd david koechner jahbril cook kat conner sterling iain tucker ed amatrudo hutch greene josh rasile ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-thoai-than-bo', 'Đại Thoại Thần Bộ', 'Big Talk, God Catcher', 'https://phimimg.com/upload/vod/20231119-1/0ebdd35da52c8b6ef83c603188728897.jpg', 'https://phimimg.com/upload/vod/20231119-1/6677a4d2d5fc977cd56a0d2c495f9bc8.jpg', '<p>Đại Thoại Thần Bộ kể về trong thời gian gần đây, huyện Thu Phong, Hà Bắc không bình yên lắm. Từ khi người đàn bà góa Hà Tú Cầm bị thổ phỉ giết chết ở ngoài huyện vào nửa tháng trước, “nữ quỷ” bắt đầu ẩn hiện trên cầu Xích Kiều trong huyện. Một hôm, huyện trưởng Trần Chi Chương bị “nữ quỷ” làm giật nẩy mình sau khi ông say rượu đi qua cầu Xích Kiều vào đêm khuya. Ông liền phái sai dịch Quách Huyễn dẫn đầu bắt quỷ trong hạn. Quách Huyễn là một sai dịch chính nghĩa, lương thiện, khi nhân dân trong huyện lo sợ do “chuyện ma quái”, anh ấy anh dũng đứng ra và bắt được người đàn ông vạm vỡ Hạ Trùng. Hạ Trùng giải thích nguyên nhân mình đóng giả “nữ quỷ” cho Quách Huyễn, hóa ra đằng sau “chuyện ma quái” còn có một vụ huyết án kỳ lạ.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xu Juncong","avatar":""},{"name":"Bu Yu","avatar":""},{"name":"Bao Bei Er","avatar":""},{"name":"Chen Qiuling","avatar":""},{"name":"Yu Yang","avatar":""},{"name":"Zhang Taiwei","avatar":""},{"name":"Ximen Piaopiao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324326);
