INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-recon', 'The Recon', 'The Recon', 'https://phimimg.com/upload/vod/20231118-1/8c1b25310968c693f48269a17a4c5325.jpg', 'https://phimimg.com/upload/vod/20231118-1/ca7c6702c52c049abb8516750b288ce9.jpg', '<p>Một sĩ quan giáo dục được điều động đã chết sau khi một phát súng nổ trong đêm khuya. Cùng lúc đó, những người đào ngũ chạy trốn đến DMZ trong vùng kiểm soát truy cập, và trung đội 3 được triển khai khẩn cấp cho hoạt động tìm kiếm DMZ. Ở đó, phi hành đoàn nhìn thấy một người lính không rõ danh tính, không phải một người đào ngũ hay một đội tìm kiếm.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Chang-eui","avatar":""},{"name":"Song Young-gyu","avatar":""},{"name":"Lee Hyun-kyun","avatar":""},{"name":"Jang Hae-song","avatar":""},{"name":"Kim Young-jae","avatar":""},{"name":"Yoon Woo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324326);
