INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-many-saints-of-newark', 'The Many Saints of Newark', 'The Many Saints of Newark', 'https://phimimg.com/upload/vod/20231117-1/de0c5598c5243774d3e5adb45af13372.jpg', 'https://phimimg.com/upload/vod/20231117-1/7d7697d1e83d1972d46611d42c027eab.jpg', '<p>Anthony Soprano lớn đang lớn lên ở một trong những Eras hỗn độn nhất trong lịch sử của Newark, trở thành một người đàn ông giống như các bọn côn đồ đối thủ bắt đầu vươn lên và thách thức gia đình tội phạm Dimeo toàn năng nắm giữ thành phố ngày càng chạy đua. Bị cuốn vào thời gian thay đổi là chú anh thần tượng, Dickie Moltisanti, người đấu tranh để quản lý cả trách nhiệm cá nhân và chuyên môn và có ảnh hưởng đối với cháu trai của ông sẽ giúp tạo ra những thiếu niên ấn tượng vào ông chủ Mob toàn năng, sau đó chúng ta sẽ đến Biết: Tony soprano.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alessandro Nivola","avatar":""},{"name":"Leslie Odom Jr.","avatar":""},{"name":"Michael Gandolfini","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Michela De Rossi","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Corey Stoll","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Billy Magnussen","avatar":""},{"name":"John Magaro","avatar":""},{"name":"Talia Balsam","avatar":""},{"name":"Patina Miller","avatar":""},{"name":"Joey Diaz","avatar":""},{"name":"Germar Terrell Gardner","avatar":""},{"name":"Michael Imperioli","avatar":""},{"name":"Samson Moeakiol","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324326);
