INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hop-den', 'Hộp Đen', 'Black Box - Boite Noire', 'https://phimimg.com/upload/vod/20231129-1/99b18077ee3eb298660ab205f33dbe5f.jpg', 'https://phimimg.com/upload/vod/20231129-1/6ef63ac6e543642a1570209a91d86523.jpg', '<p>Câu chuyện đề cập đến Matthieu, một chàng trai trẻ tuổi và tài năng, chuyên phân tích hộp đen để tìm ra manh mối của vụ án. Hiện Matthieu đang truy tìm nguyên nhân đằng sau vụ tai nạn máy bay chết người nhưng vụ việc đã được nhà chức trách khép lại.</p>', 'Full', 1, 'single', 'completed', 8, 2021, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Pierre Niney","avatar":""},{"name":"Lou de Laâge","avatar":""},{"name":"André Dussollier","avatar":""},{"name":"Sébastien Pouderoux","avatar":""},{"name":"Olivier Rabourdin","avatar":""},{"name":"Guillaume Marquet","avatar":""},{"name":"Mehdi Djaadi","avatar":""},{"name":"Aurélien Recoing","avatar":""},{"name":"André Marcon","avatar":""},{"name":"Anne Azoulay","avatar":""},{"name":"Marie Dompnier","avatar":""},{"name":"Grégori Derangère","avatar":""},{"name":"Philippe Maymat","avatar":""},{"name":"Boris Ravaine","avatar":""},{"name":"Octave Bossuet","avatar":""},{"name":"Lorène","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324326);
