INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-nu-co-gai-duoc-ran-khong-lo-nuoi-lon', 'Xà Nữ | Cô Gái Được Rắn Khổng Lồ Nuôi Lớn', 'Snake Girl', 'https://phimimg.com/upload/vod/20231116-1/0c0b545effcd3d95ba54a6ac8c2bcad6.jpg', 'https://phimimg.com/upload/vod/20231116-1/4670a14e00d006525f5ea61641f799ab.jpg', '<p>Đội đặc nhiệm đi sâu vào rừng rậm để tìm hiểu bí mật về tiên dược tử quang thảo, nhưng họ phát hiện một cô gái bí ẩn sinh sống cùng con rắn khổng lồ. Lâm Thành đưa cô gái trở về thế giới loài người thì bị rắn khổng lồ tấn công, đội thám hiểm bị tiêu diệt. Trong quá trình tiếp xúc với Xà Nữ, hai người đã nảy sinh tình cảm. Lâm Thành lợi dụng Xà Nữ để tiếp cận rắn khổng lồ. Liệu Lâm Thành có đạt được mục đích về danh vọng tiền tài? Rốt cuộc cái kết cho câu chuyện này sẽ đi đến đâu?</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Haoyue","avatar":""},{"name":"Xiao Yanbo","avatar":""},{"name":"Wang Hongqian","avatar":""},{"name":"Temur Gang","avatar":""},{"name":"Zhang Xinyuan","avatar":""},{"name":"Sun Huangchen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324326);
