INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-worst-person-in-the-world', 'The Worst Person in the World', 'The Worst Person in the World', 'https://phimimg.com/upload/vod/20231117-1/e1ffa8f59423d7946e0cc3d5606b9c5c.jpg', 'https://phimimg.com/upload/vod/20231117-1/5d7990376b8d39272c5de43c987643f4.jpg', '<p>Biên niên sử được bốn năm trong cuộc đời của Julie, một phụ nữ trẻ điều hướng những vùng biển gặp khó khăn trong cuộc sống tình yêu của mình và những cuộc đấu tranh để tìm con đường sự nghiệp của mình, khiến cô ấy có một cái nhìn thực tế về người mà cô ấy thực sự.</p>', 'Full', 1, 'single', 'completed', 18, 2021, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Renate Reinsve","avatar":""},{"name":"Anders Danielsen Lie","avatar":""},{"name":"Herbert Nordrum","avatar":""},{"name":"Hans Olav Brenner","avatar":""},{"name":"Helene Bjørnebye","avatar":""},{"name":"Vidar Sandem","avatar":""},{"name":"Maria Grazia Di Meo","avatar":""},{"name":"Lasse Gretland","avatar":""},{"name":"Karen Røise Kielland","avatar":""},{"name":"Marianne Krogh","avatar":""},{"name":"Thea Stabell","avatar":""},{"name":"Deniz Kaya","avatar":""},{"name":"Eia Skjønsberg","avatar":""},{"name":"Ruby Dagnall","avatar":""},{"name":"Torgny Amdam","avatar":""},{"name":"Rebe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324327);
