INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-worst-person-in-the-world', 'The Worst Person in the World', 'The Worst Person in the World', 'the worst person in the world the worst person in the world renate reinsve anders danielsen lie herbert nordrum hans olav brenner helene bjørnebye vidar sandem maria grazia di meo lasse gretland karen røise kielland marianne krogh thea stabell deniz kaya eia skjønsberg ruby dagnall torgny amdam rebe ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sweet-carolina', 'Sweet Carolina', 'Sweet Carolina', 'https://phimimg.com/upload/vod/20231117-1/d4f61c13a17c1b9dda4cabc9a888b8bd.jpg', 'https://phimimg.com/upload/vod/20231117-1/a734a92cd6644890fcc5e9d7f40efec4.jpg', '<p>Josie Wilder là một giám đốc điều hành tại công ty tiếp thị dựa trên New York, chân tốt nhất về phía trước. Mặc dù yêu gia đình của mình - cô ấy luôn coi chị gái Ellie, người bạn thân nhất của mình - tất cả những người vẫn sống ở quê nhà nhỏ của họ, Bắc Carolina, Josie hiếm khi gặp họ khi công việc luôn được ưu tiên. Chuyến đi theo kế hoạch của Josie trong một tháng đã xảy ra sớm hơn khi Ellie và chồng Aaron bị giết trong một tai nạn xe hơi. Trong khi tất cả mọi người trong gia đình hy vọng Ellie, Josie và cha mẹ của người anh em công nghệ của họ, Pete và Kate Wilder, sẽ đảm nhận quyền nuôi con của Ellie và Aaron, Teen Teen Ben và Tweener Delilah, Ellie và Aaron ném tất cả cho một vòng lặp như Họ, mà không nói với cô ấy hoặc bất cứ ai khác, đã quy định trong ý chí của họ rằng họ muốn Josie bị giam giữ. Josie phải tìm ra lý do Ellie chọn cô ấy chăm sóc con mình, cô ấy không phải là lựa chọn rõ ràng cho cô ấy hoặc bất cứ ai khác, đặc biệt là Pete, người dường như luôn phẫn nộ sự lựa chọn của Josie để rời khỏi hy vọng mới nhanh nhất có thể khi cô ấy trở nên tuổi tác. Cũng không rõ ràng đối với Ben hay Delilah, người, trong khi vẫn yêu dì của họ, luôn định nghĩa tiêu cực với cô ấy về mặt của thành phố. Điều đặc biệt khó khăn để nhạy cảm hơn với những người đang trải qua trường hợp đầu tiên của mình về tình yêu con chó con dành cho bạn cùng lớp, Lily, từ người mà anh ta không chắc chắn nếu cảm xúc được trả lại. Ngoài gia đình cô, giúp Josie hình những thứ này là Cooper Avchen, người yêu trung học của cô và huấn luyện viên bóng rổ của Delilah, gần đây anh chỉ mới trở về thị trấn sau khi ở xa &quot;thành phố&quot; như Josie, trong vụ án Atlanta.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Lacey Chabert","avatar":""},{"name":"Tyler Hynes","avatar":""},{"name":"Gregory Harrison","avatar":""},{"name":"Jesse Moss","avatar":""},{"name":"Teryl Rothery","avatar":""},{"name":"Cassidy Nugent","avatar":""},{"name":"Glen Gordon","avatar":""},{"name":"Donna Benedicto","avatar":""},{"name":"Christine Chatelain","avatar":""},{"name":"Nathan Witte","avatar":""},{"name":"Daniel Bacon","avatar":""},{"name":"Gabrielle Quinn","avatar":""},{"name":"Benita Ha","avatar":""},{"name":"Alistair Abell","avatar":""},{"name":"Peter Benson","avatar":""},{"name":"Jason Tremblay","avatar":""},{"name":"Kevan Ohtsji","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324327);
