INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-scary-of-sixtyfirst', 'The Scary of Sixty-First', 'The Scary of Sixty-First', 'https://phimimg.com/upload/vod/20231117-1/537d7b40696987f1292b3c21e3dcc0e4.jpg', 'https://phimimg.com/upload/vod/20231117-1/7e2ede6a8054fb7875b11abcdafaf942.jpg', '<p>Addie và Noelle được giới thiệu làm một cái gì đó cư dân thành phố biết thực sự kinh khủng: săn bắn căn hộ. Mọi thứ thay đổi cho cả hai người phụ nữ khi một người lạ giấu tên gõ cửa. Cô gái nói với Noelle rằng cô tin rằng họ đang sống ở một nơi đã thấy những nỗi kinh hoàng chưa kể. Một trong những căn hộ mà Jeffrey Epstein đã từng giao thông và lạm dụng các cô gái. Trước khi bạn biết điều đó, họ đã ngã xuống lỗ thỏ vào một thế giới âm mưu của các lý thuyết về Epstein và các căn hộ của anh ta.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Betsey Brown","avatar":""},{"name":"Madeline Quinn","avatar":""},{"name":"Dasha Nekrasova","avatar":""},{"name":"Mark H. Rapaport","avatar":""},{"name":"Jason Grisell","avatar":""},{"name":"Stephen Gurewitz","avatar":""},{"name":"Michael M. Bilandic","avatar":""},{"name":"Ruby McCollister","avatar":""},{"name":"Aaron Dalla Villa","avatar":""},{"name":"Anna Khachiyan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324327);
