INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huu-nhan-so-ishi-okoshi-to-ayashiki-raihousha', 'Hữu Nhân Sổ: Ishi Okoshi to Ayashiki Raihousha', 'Natsume''s Book of Friends', 'https://phimimg.com/upload/vod/20231117-1/2ee033f417d522d0bc231966bdbe9876.jpg', 'https://phimimg.com/upload/vod/20231117-1/d9bd873c48b2da48f1a7b0f5dc03a6e5.jpg', '<p>Bộ này sẽ kể hai câu chuyện: &quot;Ishi Okoshi&quot; và &quot;Ayashiki Raihousha.&quot; Trong &quot;Ishi Okoshi&quot;, Natsume gặp một yêu quái nhỏ tên là Mitsumi trong một khu rừng. Mitsumi được giao nhiệm vụ đánh thức yêu quái thần thánh &quot;Iwatetsu&quot; khỏi giấc ngủ sâu của nó. Mitsumi đè nặng tâm trí của Natsume, vì vậy anh ấy bắt đầu giúp Mitsumi thực hiện nhiệm vụ của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hiroshi Kamiya","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Kazuma Horie","avatar":""},{"name":"Takaya Kuroda","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Cho","avatar":""},{"name":"Hisako Kanemoto","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324327);
