INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('adele-dem-duy-nhat', 'Adele: Đêm Duy Nhất', 'Adele One Night Only', 'https://phimimg.com/upload/vod/20231116-1/cdf631cf2bb1a5af1dd9466ab128662d.jpg', 'https://phimimg.com/upload/vod/20231116-1/ef1bb807d22fc29a60aa0a162c669e98.jpg', '<p>Một chương trình đặc biệt vào giờ vàng với các màn trình diễn của siêu sao bao gồm các bài hát mới đầu tiên của Adele sau sáu năm cộng với các bản hit đứng đầu bảng xếp hạng của cô ấy. Đặc biệt cũng sẽ có cuộc phỏng vấn độc quyền với Adele của Oprah Winfrey từ vườn hồng của cô ấy, trong cuộc trò chuyện rộng rãi trên truyền hình đầu tiên của Adele.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adele","avatar":""},{"name":"Oprah Winfrey","avatar":""},{"name":"Lizzo","avatar":""},{"name":"Melissa McCarthy","avatar":""},{"name":"Gabrielle Union","avatar":""},{"name":"James Corden","avatar":""},{"name":"Dwyane Wade","avatar":""},{"name":"Ava DuVernay","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Drake","avatar":""},{"name":"Donald Glover","avatar":""},{"name":"Ellen DeGeneres","avatar":""},{"name":"Portia de Rossi","avatar":""},{"name":"Leonardo DiCaprio","avatar":""},{"name":"Jesse Tyler Ferguson","avatar":""},{"name":"Kris Jenner","avatar":""},{"name":"Gayle King","avatar":""},{"name":"Aaron Paul","avatar":""},{"name":"Sara","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324327);
