INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-feast', 'The Feast', 'The Feast', 'https://phimimg.com/upload/vod/20231113-1/89d67269a0ceba8638f80318b85feb4d.jpg', 'https://phimimg.com/upload/vod/20231113-1/c737d514cb7987e94ff1c25556d7edc1.jpg', '<p>Một gia đình giàu có có một bữa tiệc tối tại nhà của mình ở vùng núi Welsh, tổ chức một doanh nhân địa phương và nông dân hy vọng sẽ có môi giới kinh doanh. Sau đó, một phụ nữ trẻ bí ẩn đến là cô hầu bàn của gia đình. Sự xuất hiện này sẽ có ảnh hưởng nhất thời vào các nguyên tắc và đạo đức của gia đình.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Annes Elwy","avatar":""},{"name":"Nia Roberts","avatar":""},{"name":"Julian Lewis Jones","avatar":""},{"name":"Steffan Cennydd","avatar":""},{"name":"Sion Alun Davies","avatar":""},{"name":"Rhodri Meilir","avatar":""},{"name":"Lisa Palfrey","avatar":""},{"name":"Caroline Berry","avatar":""},{"name":"Chris Gordon","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324327);
