INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cryptozoo', 'Cryptozoo', 'Cryptozoo', 'https://phimimg.com/upload/vod/20231113-1/5e2edebc5f20bac4b40bd424f8a3b81f.jpg', 'https://phimimg.com/upload/vod/20231113-1/b5f66d9d9a3d41940b56896322e429ad.jpg', '<p>Cryptozookeepers cố gắng chụp một chiếc Baku, một sinh vật lai tạo giấc mơ của huyền thoại, và bắt đầu tự hỏi liệu họ có nên hiển thị những con thú này hoặc giữ cho chúng ẩn và không biết.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lake Bell","avatar":""},{"name":"Michael Cera","avatar":""},{"name":"Alex Karpovsky","avatar":""},{"name":"Zoe Kazan","avatar":""},{"name":"Louisa Krause","avatar":""},{"name":"Angeliki Papoulia","avatar":""},{"name":"Thomas Jay Ryan","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Grace Zabriskie","avatar":""},{"name":"Emily Davis","avatar":""},{"name":"Ivan Kamasarav","avatar":""},{"name":"Nathan Nikulin","avatar":""},{"name":"Maxim Pozdorovkin","avatar":""},{"name":"Matvey Kulakov","avatar":""},{"name":"Irene Muscara","avatar":""},{"name":"Owen K. Price","avatar":""},{"name":"Joce Soub","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324327);
