INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-hai-da-hanh-1-vu-an-hac-kim', 'Thượng Hải Dạ Hành 1: Vụ Án Hắc Kim', 'The Bund', 'null', 'https://phimimg.com/upload/vod/20231113-1/91156fab8cef04860022c37561ebf491.jpg', '<p>Trùm bang phái xã hội đen Thượng Hải là Lương Tiếu Đường qua đời vì bị đứa con trai cả đầy dã tâm ám sát. Con trai thứ Lương Gia Tấn đối mặt với khó khăn chồng chất. Tai họa cứ xảy đến dồn dập, lúc này anh lại phát hiện ra cô bạn gái nhiều năm của mình là sát thủ do bang phái cài cắm bên cạnh. Bị dồn vào bước đường cùng, Lương Gia Tấn bắt đầu lập một chuỗi kế hoạch tỉ mỉ để vực dậy công ty Thiên Hòa, diệt trừ bang phái xã hội đen, vạch trần bộ mặt thật của cô bạn gái sát thủ...</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Zhuowen","avatar":""},{"name":"Dian Jiang","avatar":""},{"name":"Li Wei Jian","avatar":""},{"name":"Dang Tao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324327);
