INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jungle-cruise-tham-hiem-rung-xanh', 'Jungle Cruise: Thám Hiểm Rừng Xanh', 'Jungle Cruise', 'https://phimimg.com/upload/vod/20231114-1/049ae81566a140c7f553f7545f8ea88b.jpg', 'https://phimimg.com/upload/vod/20231114-1/a09debba33a6c6c450b6192e39a2b7e9.jpg', '<p>Nội dung phim kể về một cặp đôi đi thám hiểm cùng nhau - Frank và Lily. Một người là thuyền trưởng người Mỹ và một người là nhà thám hiểm Anh quyết tâm hành trình vào rừng rậm Amazon để tìm kiếm một cây thần thoại với khả năng chữa bệnh đáng kinh ngạc.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"Edgar Ramírez","avatar":""},{"name":"Jack Whitehall","avatar":""},{"name":"Jesse Plemons","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Veronica Falcón","avatar":""},{"name":"Dani Rovira","avatar":""},{"name":"Quim Gutiérrez","avatar":""},{"name":"Dan Dargan Carter","avatar":""},{"name":"Andy Nyman","avatar":""},{"name":"Raphael Alejandro","avatar":""},{"name":"Simone Lockhart","avatar":""},{"name":"Pedro Lopez","avatar":""},{"name":"Sulem Calderon","avatar":""},{"name":"Sebastian Blunt","avatar":""},{"name":"Mark A","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324327);
