INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('raya-va-rong-than-cuoi-cung', 'Raya và Rồng Thần Cuối Cùng', 'Raya and the Last Dragon', 'https://phimimg.com/upload/vod/20231115-1/462056eaf335165ac4afc1184c86664c.jpg', 'https://phimimg.com/upload/vod/20231115-1/62ee6a21d5de188f9478638e02595619.jpg', '<p>Raya và Rồng Thần Cuối Cùng kể về một vương quốc huyền bí có tên là Kumandra – vùng đất mà loài rồng và con người sống hòa thuận với nhau. Nhưng rồi một thế lực đen tối bỗng đe dọa bình yên nơi đây, loài rồng buộc phải hi sinh để cứu lấy loài người. 500 năm sau, thế lực ấy bỗng trỗi dậy và một lần nữa, Raya là chiến binh duy nhất mang trong mình trọng trách đi tìm Rồng Thần cuối cùng trong truyền thuyết nhằm hàn gắn lại khối ngọc đã vỡ để cứu lấy vương quốc. Thông qua cuộc hành trình, Raya nhận ra loài người cần nhiều hơn những gì họ nghĩ, đó chính là lòng tin và sự đoàn kết.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kelly Marie Tran","avatar":""},{"name":"Awkwafina","avatar":""},{"name":"Gemma Chan","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Izaac Wang","avatar":""},{"name":"Benedict Wong","avatar":""},{"name":"Daniel Dae Kim","avatar":""},{"name":"Thalia Tran","avatar":""},{"name":"Sandra Oh","avatar":""},{"name":"Dichen Lachman","avatar":""},{"name":"Patti Harrison","avatar":""},{"name":"Lucille Soong","avatar":""},{"name":"Jona Xiao","avatar":""},{"name":"Sung Kang","avatar":""},{"name":"Ross Butler","avatar":""},{"name":"François Chau","avatar":""},{"name":"Paul Yen","avatar":""},{"name":"Ren Hanami","avatar":""},{"name":"Sierra Katow","avatar":""},{"name":"Go","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324327);
