INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-kieu-ngao-nhu-vay', 'Đừng Kiêu Ngạo Như Vậy', 'Proud of Love', 'https://phimimg.com/upload/vod/20231125-1/3d544815075782e86c0ff7f26fe1635d.jpg', 'https://phimimg.com/upload/vod/20231125-1/0e025f0550f97f690f6fc47fc7467651.jpg', '<p>Sao Diêm Vương quay chậm tạo ra từ trường bí ẩn khiến cho cô gái Thẩm Hi lần đầu đi làm bị nhốt vào vòng lặp thời gian của một ngày. Tất cả chuyện này dường như đều liên quan đến ông chủ độc miệng của công ty, Hà Chi Châu. Thẩm Hi không ngừng tiếp cận Hà Chi Châu, thay đổi tính cách đáng ghét của anh ta nhằm thoát khỏi vòng lặp thời gian này. Trong lúc đó, một mối tình dở khóc dở cười dần dần chớm nở...</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Ziyou","avatar":""},{"name":"Tan Yanyan","avatar":""},{"name":"Jin Jing","avatar":""},{"name":"Feng Qing","avatar":""},{"name":"Zhang Bohan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324327);
