INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bot-hon-3', 'Bốt Hôn 3', 'The Kissing Booth 3', 'https://phimimg.com/upload/vod/20231113-1/dc979a439d96bead66bf2fda42c6e18b.jpg', 'https://phimimg.com/upload/vod/20231113-1/534c894a65280fad0990d5098b790169.jpg', '<p>Quyết tâm tận hưởng mùa hè cuối cùng trước khi vào đại học, Elle lên danh sách việc muốn làm nhất trong khi xoay xở với những gì sắp xảy đến cùng Noah và Lee.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joey King","avatar":""},{"name":"Joel Courtney","avatar":""},{"name":"Jacob Elordi","avatar":""},{"name":"Molly Ringwald","avatar":""},{"name":"Taylor Zakhar Perez","avatar":""},{"name":"Meganne Young","avatar":""},{"name":"Maisie Richardson-Sellers","avatar":""},{"name":"Stephen Jennings","avatar":""},{"name":"Carson White","avatar":""},{"name":"Morné Visser","avatar":""},{"name":"Bianca Bosch","avatar":""},{"name":"Camilla Wolfson","avatar":""},{"name":"Zandile Madliwa","avatar":""},{"name":"Judd Krok","avatar":""},{"name":"Sanda Shandu","avatar":""},{"name":"Hilton Pelser","avatar":""},{"name":"Fr","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324327);
