INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('happy-new-year-chuc-mung-nam-moi', 'HAPPY NEW YEAR: CHÚC MỪNG NĂM MỚI', 'A Year-End Medley', 'https://phimimg.com/upload/vod/20231113-1/0b38640531edbf41e691bf7bac0d2db7.jpg', 'https://phimimg.com/upload/vod/20231113-1/e64f15af85ea74bf52295772ded03773.jpg', '<p>HAPPY NEW YEAR là bức tranh gồm những mảnh ghép đầy thú vị về những vị khách tới với khách sạn Emross dịp cuối năm. Mỗi người một câu chuyện riêng, cảm xúc riêng, góc nhìn riêng và mong cầu riêng đối với tình yêu và cuộc sống. “Đây là nơi mà người ta ở lại, rời đi, gặp gỡ, rồi chia tay. Liệu chúng ta cũng sẽ tìm thấy ai đó đặc biệt cho riêng mình chứ?” – câu hỏi không chỉ dành cho các nhân vật, mà còn là nỗi niềm của mỗi người trong chúng ta sau một năm khó khăn vừa qua. Lời giải đáp sẽ đến cùng Happy New Year vào ngày 31.12.2021.</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Ji-min","avatar":""},{"name":"Lee Dong-wook","avatar":""},{"name":"Kang Ha-neul","avatar":""},{"name":"Seo Kang-joon","avatar":""},{"name":"Yoona","avatar":""},{"name":"Won Jin-ah","avatar":""},{"name":"Lee Hye-young","avatar":""},{"name":"Jung Jin-young","avatar":""},{"name":"Kim Young-kwang","avatar":""},{"name":"Lee Kwang-soo","avatar":""},{"name":"Ko Sung-hee","avatar":""},{"name":"Lee Jin-wook","avatar":""},{"name":"Cho Jun-young","avatar":""},{"name":"Won Ji-an","avatar":""},{"name":"Lee Kyoo-hyung","avatar":""},{"name":"Bae Hae-seon","avatar":""},{"name":"Lee Joong-ok","avatar":""},{"name":"Oh Min-ae","avatar":""},{"name":"Jung Eu-g","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324327);
