INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('annette', 'Annette', 'Annette', 'https://phimimg.com/upload/vod/20231113-1/c4817b9a37bf5d477194706f68683cc2.jpg', 'https://phimimg.com/upload/vod/20231113-1/f0e5cc67e03d9b0d41f70088e2be0b4a.jpg', '<p>Một diễn viên hài độc lập và vợ ca sĩ Opera của ông có một cô con gái 2 tuổi với một món quà đáng ngạc nhiên.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Driver","avatar":""},{"name":"Marion Cotillard","avatar":""},{"name":"Simon Helberg","avatar":""},{"name":"Devyn McDowell","avatar":""},{"name":"Angèle","avatar":""},{"name":"Natalia Lafourcade","avatar":""},{"name":"Sinay Bavurhe","avatar":""},{"name":"Franziska Grohmann","avatar":""},{"name":"Rachel Mulowayi","avatar":""},{"name":"Christiane Tchouhan","avatar":""},{"name":"Iman Europe","avatar":""},{"name":"Lauren Evans","avatar":""},{"name":"Cindy Almouzni","avatar":""},{"name":"Danielle Withers","avatar":""},{"name":"Julia Bullock","avatar":""},{"name":"Claron McFadden","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324327);
