INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sweat', 'Sweat', 'Sweat', 'https://phimimg.com/upload/vod/20231113-1/ba9a4c8772eaa9824acf85e85465c225.jpg', 'https://phimimg.com/upload/vod/20231113-1/a76da57828cd0ff7d94dda9996fbe337.jpg', '<p>Không còn nghi ngờ gì nữa, Sylwia gợi cảm trẻ, tươi, và dễ dàng, một người có ảnh hưởng đến truyền thông xã hội nổi tiếng và Guru thể dục động lực, nằm trên đỉnh của trò chơi của cô. Oozing với năng lượng và sự lạc quan, Athletic, tự quảng cáo Tóc vàng Messiah của Fitness dẫn đến toàn bộ các lớp học tập luyện để ngây ngất và tự chấp nhận, đã tìm cách tích lũy một đội quân những người theo dõi khó khăn. Tuy nhiên, ai có thể tin rằng nỗi buồn ngồi sâu nằm trong tâm hồn của Sylwia? Chẳng hạn, ai biết Sylwia đang làm gì giữa các bài đăng của cô ấy, ngoài việc tạo dáng cho các tạp chí quyến rũ và quảng bá sản phẩm của nhà tài trợ của mình? Và, điều gì xảy ra nếu một trong những người hâm mộ của Sylwia quan tâm nhiều hơn việc học cách đốt cháy chất béo bướng bỉnh?</p>', 'Full', 1, 'single', 'completed', 17, 2021, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Magdalena Koleśnik","avatar":""},{"name":"Aleksandra Konieczna","avatar":""},{"name":"Julian Świeżewski","avatar":""},{"name":"Zbigniew Zamachowski","avatar":""},{"name":"Tomasz Orpiński","avatar":""},{"name":"Lech Łotocki","avatar":""},{"name":"Magdalena Kuta","avatar":""},{"name":"Dominika Biernat","avatar":""},{"name":"Katarzyna Dziurska","avatar":""},{"name":"Wiktoria Filus","avatar":""},{"name":"Bartosz Sak","avatar":""},{"name":"Edgar Grischuk","avatar":""},{"name":"Dorota Zięciowska","avatar":""},{"name":"Katarzyna Cynke","avatar":""},{"name":"Bogna","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324327);
