INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sweat', 'Sweat', 'Sweat', 'sweat sweat magdalena koleśnik aleksandra konieczna julian świeżewski zbigniew zamachowski tomasz orpiński lech łotocki magdalena kuta dominika biernat katarzyna dziurska wiktoria filus bartosz sak edgar grischuk dorota zięciowska katarzyna cynke bogna ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-chernobyl', 'Thảm Họa Chernobyl', 'Chernobyl 1986', 'https://phimimg.com/upload/vod/20231123-1/f402228c17c838a5735d3118ebc2cc95.jpg', 'https://phimimg.com/upload/vod/20231123-1/d8211df302ed6d4ffed58df503f2c110.jpg', '<p>Chernobyl: Abyss là bộ phim truyện lớn đầu tiên của Nga kể về hậu quả của vụ nổ tại nhà máy điện hạt nhân Chernobyl, khi hàng trăm người hy sinh mạng sống của mình để dọn dẹp nơi xảy ra thảm họa và ngăn chặn thành công một thảm họa lớn hơn có thể xảy ra. đã biến một phần rộng lớn của lục địa Châu Âu thành một khu vực loại trừ không thể ở được.</p><p>Vào ngày 26/4/1986 tại thị trấn Pripyat, thành phố Chernobyl, Ukraina, một vụ nổ nhà máy điện hạt nhân “kinh thiên động địa” đã xảy ra khiến cả thế giới sợ hãi. Sau gần 41 năm kể từ lần Mỹ thả 2 quả bom nguyên tử xuống Nhật Bản, đây là lần thứ hai loài người được nhìn thấy sức mạnh hủy diệt của hạt nhân. Điều đáng nói là vụ nổ để lại hậu quả thật sự khủng khiếp. Nó cũng được xem là một trong những lý do trực tiếp đẩy Liên Xô đến bờ vực diệt vong 5 năm sau đó.</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Danila Kozlovsky","avatar":""},{"name":"Oksana Akinshina","avatar":""},{"name":"Philip Avdeev","avatar":""},{"name":"Ravshana Kurkova","avatar":""},{"name":"Arthur Beschastny","avatar":""},{"name":"Nikolay Kozak","avatar":""},{"name":"Igor Chernevich","avatar":""},{"name":"Anton Shvarts","avatar":""},{"name":"Andrey Archakov","avatar":""},{"name":"Samvel Tadevossian","avatar":""},{"name":"Dmitry Beseda","avatar":""},{"name":"Pavel Davydov","avatar":""},{"name":"Dmitry Matveev","avatar":""},{"name":"Mariya Abramova","avatar":""},{"name":"Daniela Bogatyreva","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324327);
