INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-ly-tuong-tren-ly-thuyet', 'Chàng Lý Tưởng, Trên Lý Thuyết', 'Good on Paper', 'https://phimimg.com/upload/vod/20231111-1/0daf88abf59c2950ab2ca0de9b092fc6.jpg', 'https://phimimg.com/upload/vod/20231111-1/3fb910a05e4429e0d3528ea399b06e7a.jpg', '<p>Sau nhiều năm ưu tiên cho sự nghiệp, cây hài độc thoại gặp một anh chàng dường như là hoàn hảo: thông minh, tử tế, thành công... và có thể không phải là hàng thật.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Iliza Shlesinger","avatar":""},{"name":"Ryan Hansen","avatar":""},{"name":"Margaret Cho","avatar":""},{"name":"Rebecca Rittenhouse","avatar":""},{"name":"Matt McGorry","avatar":""},{"name":"Taylor Hill","avatar":""},{"name":"Beth Dover","avatar":""},{"name":"Kimia Behpoornia","avatar":""},{"name":"Rebecca Delgado Smith","avatar":""},{"name":"Britney Young","avatar":""},{"name":"Christopher Nicholas Smith","avatar":""},{"name":"Adam Lustick","avatar":""},{"name":"Alexander Roberts","avatar":""},{"name":"Rebekka Johnson","avatar":""},{"name":"Mav Viola","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324327);
