INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lau-dai-giang-sinh', 'Lâu Đài Giáng Sinh', 'A Castle For Christmas', 'https://phimimg.com/upload/vod/20231111-1/762080a2d1630cb877bcaefb160ffa4b.jpg', 'https://phimimg.com/upload/vod/20231111-1/5569a83a45f1ed100763adec58835007.jpg', '<p>Sophie - một tác giả nổi tiếng người Mỹ, đi du lịch đến Scotland và ao ước muốn mua một lâu đài ở đây, nhưng người chủ khó tính của nó - Công tước Scotland tên Myles lại không muốn bán nó cho một người nước ngoài như Sophie.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Brooke Shields","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Lee Ross","avatar":""},{"name":"Andi Osho","avatar":""},{"name":"Tina Gray","avatar":""},{"name":"Eilidh Loan","avatar":""},{"name":"Stephen Oswald","avatar":""},{"name":"Vanessa Grasse","avatar":""},{"name":"Desiree Burch","avatar":""},{"name":"Anthony Strachan","avatar":""},{"name":"Drew Barrymore","avatar":""},{"name":"John Stahl","avatar":""},{"name":"Timothy Barrow","avatar":""},{"name":"Mark Fleischmann","avatar":""},{"name":"Suanne Braun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324327);
