INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('road-to-perth', 'Road to Perth', 'Road to Perth', 'https://phimimg.com/upload/vod/20231111-1/b7ff31c853750edefcf06f3a75d63827.jpg', 'https://phimimg.com/upload/vod/20231111-1/4bc344a65aa1f405801b9c09cce64434.jpg', '<p>Bị từ chối sau một lời cầu hôn, Alex thấy mình một mình trên một hành trình từ Los Angeles đến Melbourne, Úc, về những gì được cho là một kỳ nghỉ vui vẻ với vị hôn phu mới của mình. Bị mắc kẹt trong một trạng thái sốc nhẹ, Alex vượt qua những con đường với Ronnie - một người phụ nữ trong một cuộc phiêu lưu của riêng mình - và cùng nhau họ tham gia một chuyến đi lớn trên đồng bằng Nullarbor của Úc, trên đường đến Perth.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tommy O''Brien","avatar":""},{"name":"Hannah Lehmann","avatar":""},{"name":"Rachel Scott","avatar":""},{"name":"Ellen Grimshaw","avatar":""},{"name":"Katrina Schmidt","avatar":""},{"name":"Eric Branco","avatar":""},{"name":"Pei-Hsia Sen","avatar":""},{"name":"Jason Conheady","avatar":""},{"name":"Richard Conheady","avatar":""},{"name":"Martijn Meeuwsen","avatar":""},{"name":"Michael Williams","avatar":""},{"name":"Brendan Williams","avatar":""},{"name":"Steve Day","avatar":""},{"name":"John Day","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324327);
