INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuoc-dia-2021', 'Thuộc Địa', 'The Colony', 'https://phimimg.com/upload/vod/20231111-1/5ca8537e066841136af5c9b7f0434725.jpg', 'https://phimimg.com/upload/vod/20231111-1/58026c3ae222ba1bc2487f96b051edd6.jpg', '<p>Trong một tương lai không xa: sau một thảm họa toàn cầu quét sạch gần như toàn bộ nhân loại trên Trái đất, một phi hành gia ưu tú từ Space Colony Kepler phải đưa ra quyết định sẽ phong ấn số phận của con người trên cả hai hành tinh.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Nora Arnezeder","avatar":""},{"name":"Iain Glen","avatar":""},{"name":"Sarah-Sofie Boussnina","avatar":""},{"name":"Sope Dirisu","avatar":""},{"name":"Sebastian Roché","avatar":""},{"name":"Joel Basman","avatar":""},{"name":"Kotti Yun","avatar":""},{"name":"Bella Bading","avatar":""},{"name":"Cloé Heinrich","avatar":""},{"name":"Eden Gough","avatar":""},{"name":"Nicola Perot","avatar":""},{"name":"Luna Mwezi","avatar":""},{"name":"Hong Indira Rieck","avatar":""},{"name":"Keziah Bürki","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324327);
