INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-bao-thu-cuoi-cung', 'Kẻ Báo Thù Cuối Cùng', 'Last Man Down', 'https://phimimg.com/upload/vod/20231111-1/26149a7508fc4addb8d89b5dbb1b687d.jpg', 'https://phimimg.com/upload/vod/20231111-1/ce47d24cfd18fea8e22f78326ec79d71.jpg', '<p>Sau khi chọi với một đại dịch chết người và vợ anh ta bị sát hại,John Wood một người lính lực lượng đặc biệt từ bỏ nhiệm vụ của mình và trở thành một ẩn sĩ ở vùng hoang dã Bắc Âu. Nhiều năm sau, một người phụ nữ bị thương xuất hiện trước cửa nhà anh. Cô đã trốn thoát khỏi một phòng thí nghiệm và những người theo đuổi cô tin rằng máu của cô là chìa khóa để chữa khỏi bệnh trên toàn thế giới. Anh ta do dự khi tham gia, nhưng mọi nghi ngờ đều được gạt sang một bên khi anh ta phát hiện ra kẻ theo đuổi cô không ai khác chính là Chỉ huy Stone, người đàn ông đã sát hại vợ anh ta vài năm trước.</p>', 'Full', 1, 'single', 'completed', 18, 2021, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Daniel Stisen","avatar":""},{"name":"Olga Kent","avatar":""},{"name":"Daniel Nehme","avatar":""},{"name":"Stanislav Yanevski","avatar":""},{"name":"Madeleine Vall","avatar":""},{"name":"Natassia Malthe","avatar":""},{"name":"Stephanie Siadatan","avatar":""},{"name":"Robert Follin","avatar":""},{"name":"Michael Billington","avatar":""},{"name":"Pasi Antero Remsu","avatar":""},{"name":"Kamil Lemieszewski","avatar":""},{"name":"Veera Seppälä","avatar":""},{"name":"Kenneth Wolf Andersen Haugen","avatar":""},{"name":"Sam Hardy","avatar":""},{"name":"Marcus Alexa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324327);
