INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shaun-the-sheep-the-flight-before-christmas', 'Shaun the Sheep: The Flight Before Christmas', 'Shaun the Sheep: The Flight Before Christmas', 'https://phimimg.com/upload/vod/20231110-1/de033de24599c3890d35fbc8f42e4cc2.jpg', 'https://phimimg.com/upload/vod/20231110-1/719e7fe6e9f0857c67e3bad2b39e5f47.jpg', '<p>Sự phấn khích theo mùa của Shaun biến thành sự mất tinh thần khi một trang trại đột kích để có vớ lớn hơn cho đàn vô tình dẫn đến việc mất thời gian. Shaun có thể lấy lại Timmy trước khi anh ta trở thành hiện tại của người khác không?</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Justin Fletcher","avatar":""},{"name":"John Sparkes","avatar":""},{"name":"Kate Harbour","avatar":""},{"name":"Laura Aikman","avatar":""},{"name":"Marcus Brigstocke","avatar":""},{"name":"Anna Leong Brophy","avatar":""},{"name":"Simon Greenall","avatar":""},{"name":"Andy Nyman","avatar":""},{"name":"Emma Tate","avatar":""},{"name":"Richard Webber","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324327);
