INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('plan-a', 'Plan A', 'Plan A', 'https://phimimg.com/upload/vod/20231110-1/b9c6e7fd90233bbea1aa8c9b8272c7ef.jpg', 'https://phimimg.com/upload/vod/20231110-1/fcb68e689e078f4a2f0c85e4da232a01.jpg', '<p>Đức năm 1945, Max, một người sống sót sau Holocaust người Do Thái, gặp một nhóm chiến binh cực đoan của người Do Thái kháng chiến, những người cũng giống như anh, mất hết hy vọng về tương lai của họ sau khi họ bị cướp mất sự tồn tại và toàn bộ gia đình của họ bị giết bởi Đức quốc xã. Họ mơ về sự trả thù trên quy mô hoành tráng cho dân tộc Do Thái. Một con mắt cho một con mắt, một cái răng cho một cái răng. Max bắt đầu xác định với những kế hoạch quái dị của nhóm ...</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"August Diehl","avatar":""},{"name":"Sylvia Hoeks","avatar":""},{"name":"Michael Aloni","avatar":""},{"name":"Nikolai Kinski","avatar":""},{"name":"Oz Zehavi","avatar":""},{"name":"Barbara Bauer","avatar":""},{"name":"Yoel Rozenkier","avatar":""},{"name":"Ishai Golan","avatar":""},{"name":"Milton Welsh","avatar":""},{"name":"Michael Brandner","avatar":""},{"name":"Tim Wilde","avatar":""},{"name":"Eckhard Preuß","avatar":""},{"name":"Kai Ivo Baulitz","avatar":""},{"name":"Petra Berndt","avatar":""},{"name":"Sina Bianca Hentschel","avatar":""},{"name":"Gerhard Georg Jilka","avatar":""},{"name":"Sevda Po","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324327);
