INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tick-tick-boom', 'tick, tick... BOOM!', 'tick, tick... BOOM!', 'tick, tick... boom! tick, tick... boom! andrew garfield alexandra shipp robin de jesús vanessa hudgens joshua henry jonathan marc sherman michaela jaé rodriguez ben levi ross judith light bradley whitford laura benanti danielle ferland micaela diamond utkarsh ambudkar gizel jimene ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoang-cach-ky-la', 'Khoảng Cách Kỳ Lạ', 'After Yang', 'https://phimimg.com/upload/vod/20231110-1/e3eaa5bda84546c5fa061674a090f67f.jpg', 'https://phimimg.com/upload/vod/20231110-1/bce895528dd30370f424bc2d8df4eeec.jpg', '<p>Có rất nhiều đau buồn đang xảy ra trên thế giới hiện tại. Có một sự đau buồn trực tiếp về số lượng cái chết mà mọi người đã phải đối mặt trong hai năm qua, nhưng cũng là sự đau buồn về cách sống đã thay đổi, có thể là mãi mãi, và những chia rẽ mà dịch bệnh đã gây ra trong xã hội. Bộ phim &quot;After Yang&quot; của Kogonada đề cập đến sự mất mát và đau buồn theo cách vừa tiến bộ vừa quen thuộc. Một trong những bộ phim khoa học viễn tưởng hiện nay mà tôi từng xem là phim chuyển thể từ truyện ngắn &quot;Nói lời tạm biệt với Yang&quot; của Alexander Weinstein, diễn ra trong một tương lai với công nghệ không tồn tại ngày nay. Mặc dù nhiều viễn cảnh về tương lai có vẻ xa vời, nhưng &quot;After Yang&quot; vẫn ổn ở cách nó tập trung kết nối và trải nghiệm mà tất cả chúng ta đều có thể liên hệ. Đó là một bộ phim truyền hình mạnh mẽ, cảm động về ý nghĩa của việc được sống.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Justin H. Min","avatar":""},{"name":"Malea Emma Tjandrawidjaja","avatar":""},{"name":"Jodie Turner-Smith","avatar":""},{"name":"Haley Lu Richardson","avatar":""},{"name":"Sarita Choudhury","avatar":""},{"name":"Ritchie Coster","avatar":""},{"name":"Clifton Collins Jr.","avatar":""},{"name":"Orlagh Cassidy","avatar":""},{"name":"Ava DeMary","avatar":""},{"name":"Lee Wong","avatar":""},{"name":"Brett Dier","avatar":""},{"name":"Eve Lindley","avatar":""},{"name":"Adeline Kerns","avatar":""},{"name":"Ansley Kerns","avatar":""},{"name":"Nana Mensa","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324327);
