INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('marilyn-co-doi-mat-den', 'Marilyn có đôi mắt đen', 'Marilyn''s Eyes', 'https://phimimg.com/upload/vod/20231109-1/6c994b32402b417622137bf9d15c178c.jpg', 'https://phimimg.com/upload/vod/20231109-1/32c07c616cfb468b0c3b99a4f76ff522.jpg', '<p>Ẩm thực kết nối một bộ đôi sáng tạo trong bệnh viện tâm thần. Để đưa nhà hàng trong trí tưởng tượng ra ngoài đời thực, họ sẽ phải tìm ra một phương pháp chữa lành.</p>', 'Full', 1, 'single', 'completed', 17, 2021, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Miriam Leone","avatar":""},{"name":"Stefano Accorsi","avatar":""},{"name":"Thomas Trabacchi","avatar":""},{"name":"Mario Pirrello","avatar":""},{"name":"Orietta Notari","avatar":""},{"name":"Marco Messeri","avatar":""},{"name":"Andrea Di Casa","avatar":""},{"name":"Valentina Oteri","avatar":""},{"name":"Ariella Reggio","avatar":""},{"name":"Astrid Meloni","avatar":""},{"name":"Giulia Patrignani","avatar":""},{"name":"Vanessa Compagnucci","avatar":""},{"name":"Lucio Patané","avatar":""},{"name":"Agnese Brighittini","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324327);
