INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('evan-hansen-than-men', 'Evan Hansen Thân Mến', 'Dear Evan Hansen', 'https://phimimg.com/upload/vod/20231109-1/232682e5964c1eaaa02e8272a87ea081.jpg', 'https://phimimg.com/upload/vod/20231109-1/27ecfc4de4da77271e5ff9c8aca4f5d1.jpg', '<p>Một thiếu niên trung học vướng vào một lời nói dối sau khi bức thư cậu tự viết bị nhầm với thư tuyệt mệnh của một người bạn cùng trường đã tự sát.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ben Platt","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Kaitlyn Dever","avatar":""},{"name":"Danny Pino","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Amandla Stenberg","avatar":""},{"name":"Nik Dodani","avatar":""},{"name":"Colton Ryan","avatar":""},{"name":"DeMarius R. Copes","avatar":""},{"name":"Liz Kate","avatar":""},{"name":"Zoey Luna","avatar":""},{"name":"Isaac Powell","avatar":""},{"name":"Marvin Leon","avatar":""},{"name":"Hadiya Eshe''","avatar":""},{"name":"Julia Chen Myers","avatar":""},{"name":"Gerald Caesar","avatar":""},{"name":"Avery Bederman","avatar":""},{"name":"Swift Rice","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324327);
