INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-hinh-anh-trang', 'Bóng Hình Ánh Trăng', 'Moonlight Shadow', 'https://phimimg.com/upload/vod/20231109-1/ba98c8720c1633fc63d992d6c729e729.jpg', 'https://phimimg.com/upload/vod/20231109-1/7cbbecf76fe989477cedf83b8c347b30.jpg', '<p>Hitoshi gặp Satsuki vào ban đêm trên bờ sông, sau khi nghe thấy tiếng chuông nhỏ. Đó là tình yêu sét đánh, và cả hai phải lòng nhau. Ngay sau đó, anh giới thiệu cô với anh trai của mình, Hiiragi, một thanh niên khá kỳ quặc, có vẻ như mắc chứng ngủ rũ và thích nấu ăn cho mọi người vì anh có thể hiểu mọi thứ về họ qua cách họ ăn, và bạn gái của anh, Yumiko, người quan tâm đến điều huyền bí, và đặc biệt là hiện tượng tiêu chuẩn, được cho là, cho phép mọi người triệu tập với người chết. Bốn người họ bắt đầu ngay lập tức, dành toàn bộ thời gian cho nhau, cho đến khi một người bạn của Satsuki sắp chuyển ra nước ngoài đề nghị cho thuê lại căn hộ của cô ấy. Satsuki bắt đầu thảo luận về việc chuyển đến sống cùng với Hitoshi, nhưng vào khoảng thời gian đó, anh và Yumiko bị chết trong một vụ tai nạn xe hơi. Đầy đau buồn, Hiiragi bắt đầu mặc quần áo của Yumiko ở bất cứ đâu anh ấy đến, trong khi Satsuki chìm đắm trong một thói quen rèn luyện thể chất cường độ cao. Tuy nhiên, dường như không có gì có thể giúp ích, cho đến khi cả hai gặp Urara, một phụ nữ mặc áo đen bí ẩn dường như tồn tại ở đâu đó giữa thế giới thực và siêu nhiên, và thu thập các đoạn ghi âm của những người tiết lộ bí mật sâu kín nhất của họ. Bộ phim thực sự bắt đầu với việc Satsuki nói chuyện với cô ấy, trước khi nó quay ngược thời gian để bắt kịp mạch truyện từ đầu. và thu thập các đoạn ghi âm của những người tiết lộ bí mật sâu sắc nhất của họ. Bộ phim thực sự bắt đầu với việc Satsuki nói chuyện với cô ấy, trước khi nó quay ngược thời gian để bắt kịp mạch truyện từ đầu. và thu thập các đoạn ghi âm của những người tiết lộ bí mật sâu sắc nhất của họ. Bộ phim Bóng Hình Ánh Trăng thực sự bắt đầu với việc Satsuki nói chuyện với cô ấy, trước khi nó quay ngược thời gian để bắt kịp mạch truyện từ đầu.&nbsp;</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Nana Komatsu","avatar":""},{"name":"Hio Miyazawa","avatar":""},{"name":"Himi Sato","avatar":""},{"name":"Nana Nakahara","avatar":""},{"name":"Aoi Yoshikura","avatar":""},{"name":"Seiya Nakano","avatar":""},{"name":"Asami Usuda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324327);
