INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bong-hinh-anh-trang', 'Bóng Hình Ánh Trăng', 'Moonlight Shadow', 'bóng hình ánh trăng moonlight shadow nana komatsu hio miyazawa himi sato nana nakahara aoi yoshikura seiya nakano asami usuda ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phat-sung-chi-mang', 'Phát Súng Chí Mạng', 'One Shot', 'https://phimimg.com/upload/vod/20231109-1/bf8905735ebfb0ba6c0b24ac368e0aa3.jpg', 'https://phimimg.com/upload/vod/20231109-1/52d980748322bc2f06887a930381317d.jpg', '<p>Phim xoay quanh câu chuyện kể về nhà phân tích cơ sở của CIA Zoe Anderson, mở đầu phim với phân cảnh anh ta đang ngồi trên một chiếc trực thăng cùng đội ngũ tinh nhuệ của Hoa Kỳ. Biệt đội đột kích của hải quân được chỉ huy bởi Jake Harris. Nhiệm vụ của nhóm là truy tìm một người đang bị giam giữ tại một nhà tù trên đảo tên là Amin Mansur, vốn là một địa điểm bí mật của CIA và mang anh ta trở lại Washington. Nhiệm vụ khẩn cấp và thời gian là điều quyết định mọi thứ. Nhưng khi họ đến đó, Phó giám đốc công trường Jack Yorke từ chối việc áp giải tù nhân đi. Tệ hơn nữa, khi họ đang tranh cãi thì một nhóm khủng bố khác gồm những kẻ khủng bố chưa rõ danh tính đã tràn lên đảo, cũng đang tìm kiếm Mansur. Khi đạn bay và lựu đạn nổ, rõ ràng Mansur là người sống sót duy nhất có thể ngăn chặn thảm kịch xảy ra tại Hoa Kỳ. Liệu rằng họ có tới kịp không?</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Scott Adkins","avatar":""},{"name":"Ashley Greene","avatar":""},{"name":"Ryan Phillippe","avatar":""},{"name":"Emmanuel Imani","avatar":""},{"name":"Dino Kelly","avatar":""},{"name":"Jack Parr","avatar":""},{"name":"Waleed Elgadi","avatar":""},{"name":"Terence Maynard","avatar":""},{"name":"Jess Liaudin","avatar":""},{"name":"Andrei Maniata","avatar":""},{"name":"Lee Charles","avatar":""},{"name":"Ladislav Basti","avatar":""},{"name":"Alana Maria","avatar":""},{"name":"Efeosa Afolabi","avatar":""},{"name":"Dan Styles","avatar":""},{"name":"Jonathan Holby","avatar":""},{"name":"Jamie B. Chambers","avatar":""},{"name":"Coli","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324327);
