INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('american-night', 'American Night', 'American Night', 'https://phimimg.com/upload/vod/20231110-1/d44b0ed8cd1c108ac26d3a2f8ba6a6ee.jpg', 'https://phimimg.com/upload/vod/20231110-1/68eb25d06d652b625a3979f37cb5dd21.jpg', '<p>Một Neo-Noir được thiết lập trong thế giới nghệ thuật đương đại tham nhũng của thành phố New York nơi đại lý nghệ thuật John Kaplan và người đứng đầu tàn nhẫn của Mafia của New York, Michael Rubino, chiến đấu vì tiền, nghệ thuật, quyền năng và tình yêu.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Paz Vega","avatar":""},{"name":"Emile Hirsch","avatar":""},{"name":"Michael Madsen","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Maria Grazia Cucinotta","avatar":""},{"name":"Mara Lane","avatar":""},{"name":"Marco Leonardi","avatar":""},{"name":"Fortunato Cerlino","avatar":""},{"name":"Manal El-Feitury","avatar":""},{"name":"Anastacia","avatar":""},{"name":"Leart Dokle","avatar":""},{"name":"Marc Fiorini","avatar":""},{"name":"Paudge Behan","avatar":""},{"name":"Owen Davis","avatar":""},{"name":"Raicho Vasilev","avatar":""},{"name":"Annabelle B","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324327);
