INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-du-ky-hong-hai-nhi', 'Tây Du Ký: Hồng Hài Nhi', 'The Journey to The West: Demon''s Child', 'https://phimimg.com/upload/vod/20231110-1/a3ab9a0342a676aa9f4aceba3ede5515.jpg', 'https://phimimg.com/upload/vod/20231110-1/c45cc5f37e763160605355eda959ffa2.jpg', '<p>500 năm trước, Tôn Ngộ Không đại náo Thiên Cung, bất ngờ đá lật lò Bát Quái mà dẫn đến thiên hỏa giáng thế. Thiết Phiến công chúa dốc sức áp chế thiên hỏa vì muốn cứu vớt muôn dân. Nhưng Hồng Hài Nhi trong bùng bà lại bị tam muội chân hỏa của lò Bát Quái làm hại mà trở thành ma đồng. Nhằm tìm vật quý hiếm cho người mẹ, Hồng Hài Nhi bị Thương Lang Quái xúi giục đi bắt Đường Tăng. Do vậy đứa đại chiến với Tôn Ngộ Không và bất ngờ hai người lại bị Thương Lang Quái nhốt vào lò Bát Quái. Hóa ra Thương Lang Quái oán hận người thân bị chết do thiên hỏa khi nó còn nhỏ mà đời thời cơ trả thù. Tuy nhiên hành vị của Thương Lang Quái lại khiến muôn dân rơi vào cảnh khó đối mặt với thiên hỏa...</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Raquel Xu","avatar":""},{"name":"Ji Hao","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Zhuang Qiqian","avatar":""},{"name":"Xu Huang","avatar":""},{"name":"Ximen Piaopiao","avatar":""},{"name":"Wu Xiaolong","avatar":""},{"name":"Liu Zhanling","avatar":""},{"name":"Zhang Fengjun","avatar":""},{"name":"Hu Dongqing","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324327);
