INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-palma', 'Chú Chó Palma', 'A Dog Named Palma', 'https://phimimg.com/upload/vod/20231109-1/1c48a52cb4bb2b8b80b43190e2bc84a8.jpg', 'https://phimimg.com/upload/vod/20231109-1/230c39c807d4f961c8beeebe0cbb59a1.jpg', '<p>Nếu bạn đã thích Tiếng gọi nơi hoang dã hay Hachiko: chú chó trung thành thì mùa Giáng sinh này cũng nên lựa Palma – một câu chuyện cảm động dành cho gia đình, nhất là con trẻ. Palma do Alexander Domogarov đạo diễn, dựa trên các sự kiện có thật diễn ra vào năm 1974-1976 tại sân bay Vnukovo (Moscow)</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Victor Dobronravov","avatar":""},{"name":"Leonid Basov","avatar":""},{"name":"Vladimir Ilin","avatar":""},{"name":"Valeriya Fedorovich","avatar":""},{"name":"Evgeniya Dmitrieva","avatar":""},{"name":"Igor Khripunov","avatar":""},{"name":"Pavel Maykov","avatar":""},{"name":"Vladimir Simonov","avatar":""},{"name":"Yan Tsapnik","avatar":""},{"name":"Filipp Savinkov","avatar":""},{"name":"Darya Luzina","avatar":""},{"name":"Elena Anisimova","avatar":""},{"name":"Bain Bovaldinov","avatar":""},{"name":"Ilya Lutsak","avatar":""},{"name":"Viktoriya Pivko","avatar":""},{"name":"Michael J","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324327);
