INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-linh-hon-cua-rong', 'Người Dơi: Linh Hồn Của Rồng', 'Batman: Soul of the Dragon', 'https://phimimg.com/upload/vod/20231109-1/eb059e365e6592714d39d01184277b91.jpg', 'https://phimimg.com/upload/vod/20231109-1/ad193edef5cd856b13cab72620678e3d.jpg', '<p>Người Dơi: Linh Hồn Của Rồng nói về Batman, Bronze Tiger, Lady Shiva và Richard Dragon hợp lực khi họ nhận ra rằng họ có chung một người quen. Võ sư huấn luyện họ đã mất tích trong nhiều năm và trong những hoàn cảnh bí ẩn. Khi một di tích bị nguyền rủa sống lại, bí ẩn về người chủ đã chết của họ lại mở ra và Batman và những người bạn học cũ của anh ta phải đối đầu trong bài kiểm tra cuối cùng về những người giết được Võ thuật của họ để giành quyền kiểm soát di tích nguy hiểm này.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Giuntoli","avatar":""},{"name":"Mark Dacascos","avatar":""},{"name":"Kelly Hu","avatar":""},{"name":"Michael Jai White","avatar":""},{"name":"James Hong","avatar":""},{"name":"Eric Bauza","avatar":""},{"name":"Jamie Chung","avatar":""},{"name":"Chris Cox","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Josh Keaton","avatar":""},{"name":"Erica Luttrell","avatar":""},{"name":"Patrick Seitz","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324327);
