INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyen-dau-chong-dich', 'Tuyến đầu chống dịch', 'Frontliner', 'null', 'https://phimimg.com/upload/vod/20231108-1/0eb9d3da6f6992ba5f1c475ceda78780.jpg', '<p>Từ các nhân viên y tế đến đội ngũ giao đồ ăn, những người chiến đấu chống COVID-19 ở Malaysia truyền cảm hứng cho một loạt câu chuyện dựa trên sự kiện có thật.</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub', 'HD', 'Malaysia', 0, '[{"name":"Beto Kusyairy","avatar":""},{"name":"Emma Maembong","avatar":""},{"name":"Farah Ahmad","avatar":""},{"name":"Wan Maimunah","avatar":""},{"name":"Azhan Rani","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324327);
