INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phao-thu-nhien-hon', 'Pháo Thủ Nhiên Hồn', 'The Cannoneer''s Burning Soul', 'null', 'https://phimimg.com/upload/vod/20231116-1/2c48344e5f83a8610826dfc65dfcc19c.jpg', '<p>Năm 1592 Toyotomi Hideyoshi thống nhất Nhật Bản và xâm lược Triều Tiên nhằm chinh phục Đế quốc Minh. Gần như toàn bộ đất nước Joseon rơi vào tay quân xâm lược và không còn lựa chọn nào khác ngoài việc nhờ đến sự giúp đỡ từ Hoàng đế Vạn Lịch của nhà Minh. Vì sự giúp đỡ này, Joseon đã dâng công chúa Li Jin Yi cho Hoàng đế Vạn Lịch.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Zhengjun","avatar":""},{"name":"Weihua Zhan","avatar":""},{"name":"Zhang Xiaojun","avatar":""},{"name":"Shui Jiang","avatar":""},{"name":"Yang Qingwen","avatar":""},{"name":"Dong Qiming","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324327);
