INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-lau-lan-doi-quan-u-linh', 'Truyền Thuyết Lâu Lan: Đội Quân U Linh', 'The Legend Of Loulan: Ghost Army', 'null', 'https://phimimg.com/upload/vod/20231108-1/a1cef5c89dc5147671be02a12500d788.jpg', '<p>Truyền Thuyết Lâu Lan: Đội Quân U Linh kể về Wu Tian vốn là một nhà khảo cổ học đầy nhiệt huyết và chính nghĩa, đã phát hiện ra một chiếc gương đồng tráng men của các di tích văn hoá Lâu Lan trong sa mạc. Kho báu để ngăn nó rơi vào tay kẻ ngoại bang và những kẻ trộm mộ, cả hai đã tới lăng mộ của thiên vương trong lăng mộ Lâu Lan, để khám phá bí mật về đội quân u linh bí ẩn ngàn năm tuổi, và có một cuộc phiêu lưu chiến đấu dũng cảm ở Lâu Lan.</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Chang","avatar":""},{"name":"Zaimire Aheiti","avatar":""},{"name":"Wa Er","avatar":""},{"name":"付赫安琪","avatar":""},{"name":"Akbar Erhei","avatar":""},{"name":"Kunlun","avatar":""},{"name":"Scotty Cox","avatar":""},{"name":"Zhou Zhuo","avatar":""},{"name":"Li Binghan","avatar":""},{"name":"Zhou Sanyou","avatar":""},{"name":"Li Gaoji","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324327);
