INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-novice', 'The Novice', 'The Novice', 'https://phimimg.com/upload/vod/20231108-1/0bad49dfbc85b9d505ad88bdf38f2f3b.jpg', 'https://phimimg.com/upload/vod/20231108-1/919aed7021832aecaea80ed5f9dcb314.jpg', '<p>Alex, một sinh viên năm nhất đại học, tham gia vào đội chèo của trường đại học và thực hiện một cuộc hành trình về thể chất và tâm lý ám ảnh để biến nó thành chiếc thuyền varsity hàng đầu. Giá không quan trọng. Ý định vượt trội so với các đồng đội của mình, Alex đẩy mình đến giới hạn của mình và xa hơn, xa lánh tất cả mọi người xung quanh với tên thành công.</p>', 'Full', 1, 'single', 'completed', 9, 2021, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Isabelle Fuhrman","avatar":""},{"name":"Amy Forsyth","avatar":""},{"name":"Dilone","avatar":""},{"name":"Jonathan Cherry","avatar":""},{"name":"Kate Drummond","avatar":""},{"name":"Charlotte Ubben","avatar":""},{"name":"Sage Irvine","avatar":""},{"name":"Chantelle Bishop","avatar":""},{"name":"Jeni Ross","avatar":""},{"name":"Nikki Duval","avatar":""},{"name":"Eve Kanyo","avatar":""},{"name":"Al Bernstein","avatar":""},{"name":"Neil Babcock","avatar":""},{"name":"Robert Ifedi","avatar":""},{"name":"Kialeigh Magee","avatar":""},{"name":"Jeff Scott Whal","avatar":""},{"name":"Nigel Holt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324327);
