INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-khong-do-dem', 'Yêu không đo đếm', 'Just Short of Perfect', 'https://phimimg.com/upload/vod/20231103-1/4e274c4eef3bc92ccda515353594a9df.jpg', 'https://phimimg.com/upload/vod/20231103-1/a685ff6a49137528ba144467c3a023a2.jpg', '<p>Luật sư đã ly hôn phải lòng bác sĩ tim mạch cuốn hút. Nhưng khi sự khác biệt về ngoại hình dẫn đến bất đồng trong gia đình, liệu cô có sẵn sàng lắng nghe trái tim mình?</p>', 'Full', 1, 'single', 'completed', 22, 2021, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Juliana Paes","avatar":""},{"name":"Leandro Hassum","avatar":""},{"name":"Elizângela","avatar":""},{"name":"Marcelo Mansfield","avatar":""},{"name":"Marcelo Laham","avatar":""},{"name":"Luana Martau","avatar":""},{"name":"Pietra Hassum","avatar":""},{"name":"Letícia Birkheuer","avatar":""},{"name":"Carol Portes","avatar":""},{"name":"Rogerio Morgado","avatar":""},{"name":"Rafael Portugal","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324327);
