INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-thuat-xac-song-san-moi', 'Ám thuật: Xác sống săn mồi', 'The Cursed: Dead Man''s Prey', 'https://phimimg.com/upload/vod/20231103-1/e361858eddec6699eaf6eaedfdb0a642.jpg', 'https://phimimg.com/upload/vod/20231103-1/dd2a7563e75f16e6d636fe8dce64fd1f.jpg', '<p>Tại hiện trường vụ án mạng, cảnh sát vô cùng bối rối khi phát hiện nghi phạm là một cái xác đã chết từ 3 tháng trước. Trong lúc đó, phóng viên Im Jin Hee nhận được một cuộc gọi từ kẻ tự xưng là hung thủ của vụ án bí ẩn. Hắn muốn thực hiện một buổi phỏng vấn. Trong buổi phát sóng trực tiếp, hắn ta nói rằng sẽ tiếp tục thực hiện 3 vụ giết người bằng &quot;xác chết tái sinh&quot;. Vào ngày xảy ra vụ giết người được báo trước đầu tiên, một đội quân xác sống xuất hiện và bất ngờ tấn công cảnh sát. Ai là kẻ chủ mưu, và lý do sau tất cả là gì?</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Uhm Ji-won","avatar":""},{"name":"Jung Ji-so","avatar":""},{"name":"Jung Moon-sung","avatar":""},{"name":"Kim In-kwon","avatar":""},{"name":"Go Gyu-pil","avatar":""},{"name":"Oh Yoon-ah","avatar":""},{"name":"Kwon Hae-hyo","avatar":""},{"name":"Lee Sul","avatar":""},{"name":"Jeon Kuk-hwan","avatar":""},{"name":"Jung Jae-sung","avatar":""},{"name":"Nam Yeon-woo","avatar":""},{"name":"Jo Han-chul","avatar":""},{"name":"Lee Joong-ok","avatar":""},{"name":"Yang Hyun-min","avatar":""},{"name":"Park Kang-sup","avatar":""},{"name":"Park Jae-wan","avatar":""},{"name":"Yoo Jang-young","avatar":""},{"name":"Yoo In-hyuk","avatar":""},{"name":"Jeon Ah-hee","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"