INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-song-scheldt', 'Trận Chiến Sông Scheldt', 'The Forgotten Battle', 'https://phimimg.com/upload/vod/20231107-1/8fafcef371c1081d01f7ce3cf76ffcdd.jpg', 'https://phimimg.com/upload/vod/20231107-1/4bc5a95bceee420be8f6fdfc1305f32b.jpg', '<p>Trận sông Scheldt quyết định của Thế chiến II là điểm gặp gỡ bi thảm trong cuộc đời của ba người: phi công tàu lượn, lính Đức Quốc xã, tân binh kháng chiến do dự.</p>', 'Full', 1, 'single', 'completed', 22, 2021, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Gijs Blom","avatar":""},{"name":"Jamie Flatters","avatar":""},{"name":"Susan Radder","avatar":""},{"name":"Theo Barklem-Biggs","avatar":""},{"name":"Jan Bijvoet","avatar":""},{"name":"Marthe Schneider","avatar":""},{"name":"Ronald Kalter","avatar":""},{"name":"Scott Reid","avatar":""},{"name":"Robert Naylor","avatar":""},{"name":"Tom Felton","avatar":""},{"name":"Coen Bril","avatar":""},{"name":"Justus von Dohnányi","avatar":""},{"name":"Mark van Eeuwen","avatar":""},{"name":"Hajo Bruins","avatar":""},{"name":"Joep Paddenburg","avatar":""},{"name":"Vincent van den Berg","avatar":""},{"name":"Sytse Fa","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324327);
