INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tran-chien-song-scheldt', 'Trận Chiến Sông Scheldt', 'The Forgotten Battle', 'trận chiến sông scheldt the forgotten battle gijs blom jamie flatters susan radder theo barklem-biggs jan bijvoet marthe schneider ronald kalter scott reid robert naylor tom felton coen bril justus von dohnányi mark van eeuwen hajo bruins joep paddenburg vincent van den berg sytse fa ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-hoang-phi', 'Trái Tim Hoàng Phi', 'Queen of My Heart', 'https://phimimg.com/upload/vod/20231107-1/02945e59a2a96406aa07440ff12e99c7.jpg', 'https://phimimg.com/upload/vod/20231107-1/c75df0be4dc17de2e0c366331c820792.jpg', '<p>Vào thời xa xưa, có một vị Thái tử nhận được chỉ dẫn, tiến vào một sơn động thần bí. Vị lão nhân ở ẩn trong động đã nói với Thái tử, cuộc đời này của chàng sẽ gặp gỡ 2 người con gái tri âm, một người giống như Mặt trời, người còn lại giống như Mặt trăng. Sau khi Thái tử ra khỏi sơn động, liền gặp phải một cô gái quyến rũ. Cô gái này bày tỏ rằng, nàng đã từng gặp mặt Thái tử trong Lễ hội đèn lồng đêm Nguyên Tiêu, nếu không phải là chàng thì nàng sẽ không gả cho bất kì người nào khác. Thái tử đã cự tuyệt lời tỏ tình của cô gái, nhưng chàng không biết rằng, cô gái này lại chính là nữ nhi của tể tướng. Cùng lúc đó, Vương thúc đã giới thiệu một vị mỹ nhân cho Thái tử. Thực ra, vị mỹ nhân này chính là gian tế của Vương thúc, Vương thúc dự định dùng cô gái này để khống chế Thái tử,…</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xiong Su Yi","avatar":""},{"name":"LiZhiYing","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324327);
