INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-chang-trai-nam-ay-mai-yeu-tiec-hau', 'Những chàng trai năm ấy: Mãi yêu – Tiệc hậu', 'To All the Boys: Always and Forever - The Afterparty', 'https://phimimg.com/upload/vod/20231103-1/6783c6f5a1535ccd0e7d454272cf6627.jpg', 'https://phimimg.com/upload/vod/20231103-1/c5fc3b68bac99f7d1bd8db664cfb5147.jpg', '<p>Dàn diễn viên &quot;Những chàng trai năm ấy&quot; bàn tán về phần ba của loạt phim và trả lời câu hỏi của người hâm mộ. Whitney Cummings đưa ra lời khuyên hẹn hò đáng ngờ.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'HD', 'Thái Lan', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324327);
