INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-vo-thuat-2', 'Nữ Hoàng Võ Thuật 2', 'The Queen of KungFu 2', 'null', 'https://phimimg.com/upload/vod/20231103-1/b1a7f09775aa2877334a0e5d991c9519.jpg', '<p>Tóm tắt: Thủ lĩnh A Hy đã mai danh ẩn tích trong lúc các bang phái phân tranh, giấu đi danh tính thật, trở thành một hiệp khách cô độc chuyên trừng trị các thế lực tà ác, độc lai độc vãng chỉ lấy bầu rượu và chiến mã làm bạn đồng hành, luyện được Hoắc Thị Tuý Quyền, trở thành thần thoại của võ lâm. Quân phiệt Tiêu Bá Thiên hành sự tàn bạo đã cấu kết với sơn tặc núi Hắc Hổ thành lập “ xưởng trà” áp bức bóc lột người dân, khiến cho bách tính lâm vào cảnh nước sôi lửa bỏng. A Hy một mặt phản kháng các thế lực tội ác, một mặt đánh hạ tâm ma của chính mình, cuối cùng đoàn kết lòng dân cùng tiêu diệt các thế lực ác bá, cứu chuộc được những người dân tị nạn lưu lạc trong cảnh nước sôi lửa bỏng.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Mengmeng","avatar":""},{"name":"Zhang Shuyang","avatar":""},{"name":"Yan Yu","avatar":""},{"name":"Gong Xiaojun","avatar":""},{"name":"Yang Di","avatar":""},{"name":"Jiang Yongbo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324327);
