INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kinh-hoa-duyen-quyet-chien-nu-nhi-quoc', 'Kính Hoa Duyên: Quyết Chiến Nữ Nhi Quốc', 'The Kingdom of Women', 'https://phimimg.com/upload/vod/20231103-1/b6eff98c69e5062e84231ecad6ea8248.jpg', 'https://phimimg.com/upload/vod/20231103-1/80cbeb698913894d3039a16aafb9955c.jpg', '<p>Trên con đường du ngoạn khắp nơi, Đường Ngao, Lâm Tử Dương, Đa Cửu Công đã cứu một cô gái nữ cải nam trang tên Nhược Thủy. Ba người cầm tấm bản đồ mà Nhược Thủy đưa và đến một nơi gọi là Nữ Nhi Quốc, họ phát hiện ra quốc vương của Nữ Nhi Quốc lại chính là Nhược Thủy! Phong tục của Nữ Nhi Quốc là nữ ăn vận nam trang, làm trụ cột gia đình; còn nam nhân thì trang điểm, sinh con, lo việc trong nhà... Việc đảo lộn âm dương như thế này lại bắt nguồn từ lời nguyền của Quốc cữu vào 50 năm trước...</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Meng Ziyi","avatar":""},{"name":"Merxat","avatar":""},{"name":"Jia Zhengyu","avatar":""},{"name":"Li Yixiao","avatar":""},{"name":"Lin Chenhan","avatar":""},{"name":"Kou Zhenhai","avatar":""},{"name":"Li Binglei","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324328);
