INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-chay-khoi-ca-map', 'Trốn Chạy Khỏi Cá Mập', 'Escape of Shark', 'https://phimimg.com/upload/vod/20231103-1/9e5c2e17541285181609946c9e1ebbc5.jpg', 'https://phimimg.com/upload/vod/20231103-1/3fe5f26e079efbdaffedb158562afb23.jpg', '<p>Bữa tiệc sôi động đặc biệt bên bờ biển vừa kết thúc, tất cả mọi người vẫn còn chưa tỉnh táo sau cơn say, thì một cơn sóng thần bất ngờ ập đến. Khách sạn trên đảo lập tức bị nước biển nhấn chìm, một con cá mập khổng lồ hung bạo theo đó mà lẻn vào khách sạn, mở ra trận chiến giữa người và cá mập. Vương Lỗi dẫn dắt mọi người thoát thân khỏi hàm cá mập…</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Raquel Xu","avatar":""},{"name":"Zhang Xinyuan","avatar":""},{"name":"Ziwen Zhang","avatar":""},{"name":"Liu Qianyu","avatar":""},{"name":"Zhuang Qiqian","avatar":""},{"name":"Su Shenghua","avatar":""},{"name":"Wang Xiaolong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324328);
