INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vr-fighter', 'VR Fighter', 'One More Shot', 'https://phimimg.com/upload/vod/20231111-1/030f6bee9d168529d8b70b45073dbf2f.jpg', 'https://phimimg.com/upload/vod/20231111-1/4c014e4bef791293d56cf928643dec47.jpg', '<p>Sau cái chết của vợ, vệ sĩ chuyên nghiệp Lung Wei đã ra nước ngoài để tìm bác sĩ cho con gái mình, nhưng thay vào đó lại tìm một công việc mới là người kiểm tra thực tế ảo</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"Jiang Yiyi","avatar":""},{"name":"Wang Zhipeng","avatar":""},{"name":"Song Ziqiao","avatar":""},{"name":"Liu Weizhou","avatar":""},{"name":"Tang Hu","avatar":""},{"name":"Diego Dati","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324328);
