INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-varsity-blues-vu-be-boi-tuyen-sinh-dai-hoc', 'Chiến dịch Varsity Blues: Vụ bê bối tuyển sinh đại học', 'Operation Varsity Blues: The College Admissions Scandal', 'https://phimimg.com/upload/vod/20231103-1/929e38320ae336f88f142b8385e2007c.jpg', 'https://phimimg.com/upload/vod/20231103-1/956140999beed38e619556b1f52a234f.jpg', '<p>Qua các màn tái dựng, phim tài liệu này điều tra về kẻ chủ mưu của vụ lừa đảo để đưa con của các gia đình giàu có và nổi tiếng vào các trường đại học hàng đầu ở Hoa Kỳ.</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Modine","avatar":""},{"name":"Roger Rignack","avatar":""},{"name":"Jillian Peterson","avatar":""},{"name":"Courtney Rackley","avatar":""},{"name":"Wallace Langham","avatar":""},{"name":"Josh Stamberg","avatar":""},{"name":"Jeff Rector","avatar":""},{"name":"William-Christopher Stephens","avatar":""},{"name":"Cullen Arbaugh","avatar":""},{"name":"Leroy Edwards III","avatar":""},{"name":"David Starzyk","avatar":""},{"name":"Kristen O''Meara","avatar":""},{"name":"Angela Nicholas","avatar":""},{"name":"Jeremy Sless","avatar":""},{"name":"John Coluc","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324328);
