INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chien-dich-varsity-blues-vu-be-boi-tuyen-sinh-dai-hoc', 'Chiến dịch Varsity Blues: Vụ bê bối tuyển sinh đại học', 'Operation Varsity Blues: The College Admissions Scandal', 'chiến dịch varsity blues: vụ bê bối tuyển sinh đại học operation varsity blues: the college admissions scandal matthew modine roger rignack jillian peterson courtney rackley wallace langham josh stamberg jeff rector william-christopher stephens cullen arbaugh leroy edwards iii david starzyk kristen o''meara angela nicholas jeremy sless john coluc ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-cuoi-den', 'Đám Cưới Đen', 'Dark Spell', 'https://phimimg.com/upload/vod/20231102-1/23af9cc848b42cde8ea43db9daf6ab30.jpg', 'https://phimimg.com/upload/vod/20231102-1/d563818166e1ad736498351a3341d233.jpg', '<p>Nội dung phim xoay quanh câu chuyện của tên Zhenya, một cô gái đau khổ vì tình yêu với người chồng đã bỏ mình nên cô quyết định mang anh ta trở lại. Trong sự tuyệt vọng, cô gái đã sử dụng một câu thần chú gọi là &quot;Đám cưới đen&quot;, một nghi lễ ma thuật nổi tiếng với sức mạnh to lớn và không thể đảo ngược. Sau nghi lễ, người chồng yêu dấu của cô trở lại, mặc dù tình yêu của anh trở nên giống như một nỗi ám ảnh: anh thậm chí sẵn sàng giết Zhenya, để không trao cô cho bất cứ ai. Khi người chồng điên cuồng chết đi, câu thần chú vẫn chưa dừng lại: bởi vì ngay cả cái chết cũng không chia lìa những người đã được hứa hôn bởi con quỷ của đám cưới đen</p>', 'Full', 1, 'single', 'completed', 22, 2021, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Yana Enzhaeva","avatar":""},{"name":"Konstantin Beloshapka","avatar":""},{"name":"Ilya Ermolov","avatar":""},{"name":"Varvara Borodina","avatar":""},{"name":"Igor Khripunov","avatar":""},{"name":"Sabina Akhmedova","avatar":""},{"name":"Kristina Marandy","avatar":""},{"name":"Larysa Domaskina","avatar":""},{"name":"Daniela Bogatyreva","avatar":""},{"name":"Nikita Yuranov","avatar":""},{"name":"Andrey Zavodyuk","avatar":""},{"name":"Anna Vartanyan","avatar":""},{"name":"Alla Malkova","avatar":""},{"name":"Maksim Bramatkin","avatar":""},{"name":"Alena Akimova","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b06