INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-hoa-phuong', 'Băng Hỏa Phượng', 'The Fire Phoenix', 'https://phimimg.com/upload/vod/20231102-1/c277e76a49e40759b5d0ab2113a2a8e4.jpg', 'https://phimimg.com/upload/vod/20231102-1/ff86ce74549ff9527d191ab60ecc85ba.jpg', '<p>Thiên Tuyết Bạt, con gái của Tuyết Tôn đã đoạt mất Xích Luyện Hỏa của Viêm Tôn trong đêm động phòng hoa chúc, và hóa thành phượng hoàng trắng, ra tay chiến đấu với Viêm Tôn, khiến Xích Luyện Tộc bị đóng băng vạn dặm. Để cứu bách tính thiên hạ, Hoa Mộc thề sẽ đoạt lại Xích Luyện Hỏa, nhưng lại rơi vào lưới tình với Thiên Tuyết Bạt, trận chiến băng hỏa sinh tử bùng nổ...</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jim Yu","avatar":""},{"name":"Zhu Shengyi","avatar":""},{"name":"Chi Shuai","avatar":""},{"name":"Zheng Guolin","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324328);
