INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-tao-anh-hung', 'Hắc Tảo Anh Hùng', 'Intrepid Hero', 'https://phimimg.com/upload/vod/20231101-1/339a7a05006bd0ac5516077e5222f230.jpg', 'https://phimimg.com/upload/vod/20231101-1/1f5d0e1370b7a7ddc87cfe286b881187.jpg', '<p>Phim là phần 3 của series &quot;Tôi Là Cảnh Sát&quot;, bắt đầu bằng một vụ án mạng bất ngờ, kể về Dương Đông, cục phó cục công an thành phố Minh Đức, dẫn đầu toàn bộ lực lượng cảnh sát điều tra và cắn chết anh ta. đến chết, phanh phui câu chuyện phạm tội do doanh nhân Lin Feng cầm đầu. Nhóm người đứng đầu giết người, cho vay nặng lãi và mở sòng bạc để thu lợi nhuận khổng lồ.</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yi","avatar":""},{"name":"Wang Haidi","avatar":""},{"name":"Tang Xu","avatar":""},{"name":"Zhao Yang","avatar":""},{"name":"Ma Jiawei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324328);
