INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thuong-cua-me', 'Người thương của mẹ', 'Will You Marry', 'https://phimimg.com/upload/vod/20231101-1/2d756150bdf9bfa8e22a132e364cb0e8.jpg', 'https://phimimg.com/upload/vod/20231101-1/e6e114c44613609fec9769ea70fa2607.jpg', '<p>Một phụ nữ đến Copenhagen để gặp bạn trai quen trên mạng, nhưng con gái chị lại không tin tưởng anh. Liệu tình yêu có thể chữa lành trái tim tan vỡ?</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"K Brosas","avatar":""},{"name":"Elisse Joson","avatar":""},{"name":"Alwyn Uytingco","avatar":""},{"name":"Hannah Ledesma","avatar":""},{"name":"Pio Balbuena","avatar":""},{"name":"Anjo Yllana","avatar":""},{"name":"Paul Lyderer","avatar":""},{"name":"Jeanet Lang Bolvig","avatar":""},{"name":"Deanie Mofjeld","avatar":""},{"name":"Jesper S. Nielsen","avatar":""},{"name":"Michael Cardeno","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324328);
