INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-thuong-cua-me', 'Người thương của mẹ', 'Will You Marry', 'người thương của mẹ will you marry k brosas elisse joson alwyn uytingco hannah ledesma pio balbuena anjo yllana paul lyderer jeanet lang bolvig deanie mofjeld jesper s. nielsen michael cardeno ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('all-about-my-mother', 'All About My Mother', 'All About My Mother', 'https://phimimg.com/upload/vod/20231109-1/29524358d6861028efc962952e78c4a7.jpg', 'https://phimimg.com/upload/vod/20231109-1/cb372b6807b2f9210b385a698a08f2b7.jpg', '<p>Mẹ Ji Peizhen (Xu Fan) là linh hồn của gia đình này. Cô ấy chăm sóc gia đình quá tốt, dường như có một bản sao của cô ấy. Ngôi nhà trông có trật tự dưới cái nhìn của cô ấy, nhưng đó không phải là toàn bộ sự thật. Ji Peizhen cho rằng con gái của cô, Li Xiaomei, là người tốt nhất, tuy nhiên, Xiaomei vẫn có những mặt khác khi cô làm việc và sống ở Bắc Kinh. Chồng của Peizhen, bác sĩ Li Wengfan, đã không thể nhặt con dao mổ do nhầm lẫn vài năm trước đó. Với tất cả những điều này, Peizhen nghĩ rằng cô ấy sẽ có thể thư giãn sau khi nghỉ hưu ... Nhưng cô ấy bị chẩn đoán mắc bệnh ung thư. Nếu mẹ chỉ còn sống được bốn tháng thì cuộc sống của gia đình có thể tiếp tục như thế nào?</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xu Fan","avatar":""},{"name":"Zhang Jingyi","avatar":""},{"name":"Xu Ya Jun","avatar":""},{"name":"Zhang Xinyi","avatar":""},{"name":"Chen Minghao","avatar":""},{"name":"Wu Yanshu","avatar":""},{"name":"Toby Lee","avatar":""},{"name":"Han Yunyun","avatar":""},{"name":"Xiaosu Zhao","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324328);
