INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-mac-than-long', 'Đại Mạc Thần Long', 'Desert Dragon', 'https://phimimg.com/upload/vod/20231109-1/a7952efe91f48e3da7f3cf89d793a499.jpg', 'https://phimimg.com/upload/vod/20231109-1/c3490ea972d2b07f9f35d7e55299cee9.jpg', '<p>Vào cuối thời nhà Đường, Lý Nguyên Cơ – một người bình thường và các bạn đồng hành của mình đã gặp gỡ đệ tử của Côn Ngô Các núi Côn Luân là Sở Linh Nhi và Tầm Đồ, cùng họ tham gia vào cuộc đọ sức với thụ yêu cũng như ma đạo. Trong quá trình đối đầu với thụ yêu, Lý Nguyên Cơ đã dần trưởng thành và thay đổi suy nghĩ về những việc lớn thì không liên quan đến những người dân thường nhỏ bé, đảm nhận sứ mệnh bảo vệ chính nghĩa, cuối cùng xả thân mình cứu lấy bách tính, đánh bại ma đạo, trở thành anh hùng của đại mạc.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tan Xin Zer","avatar":""},{"name":"Liu Yiyan","avatar":""},{"name":"Sun Jiaolong","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Zhang Xilai","avatar":""},{"name":"Wang Zhigang","avatar":""},{"name":"Ma Ruize","avatar":""},{"name":"Du Jianqiao","avatar":""},{"name":"Gong Pinyu","avatar":""},{"name":"Zheng Liuzhi","avatar":""},{"name":"Fang Xushi","avatar":""},{"name":"Liu Zhanling","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324328);
