INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-nguoi-cuon-cuon', 'Biển Người Cuồn Cuộn', 'Endgame', 'https://phimimg.com/upload/vod/20231109-1/c633ff5d5d6a7edc70c09592a07cc4b2.jpg', 'https://phimimg.com/upload/vod/20231109-1/239b750ec0fa3ff17cccbeeffa467ea7.jpg', '<p>&quot;Sát thủ&quot; hàng đầu Chu Toàn (Lưu Đức Hoa đóng) và diễn viên quần chúng Trần Tiểu Manh vô tình hoán đổi thân phận với nhau chỉ vì một cục xà phòng. Sau khi mất trí, Chu Toàn sống cuộc sống của Trần Tiểu Manh, làm quen với sếp mới của công ty truyền thông Lý Tưởng (Vạn Thiến đóng). Trần Tiểu Manh bất đắc dĩ trở thành sát thủ. Từ đây bắt đầu hàng loạt câu chuyện hài hước, hai người cũng nhờ đó mà thay đổi cách sống. Trong cuộc sống rơi xuống đáy xã hội, sát thủ nhìn nhận lại về tình yêu và cuộc sống. Diễn viên quần chúng định nghĩa lại cuộc đời mình trong khi đóng giả làm sát thủ.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Wan Qian","avatar":""},{"name":"Cheng Yi","avatar":""},{"name":"Huang Xiaolei","avatar":""},{"name":"Guo Jingfei","avatar":""},{"name":"Frant Gwo","avatar":""},{"name":"Lu Yang","avatar":""},{"name":"Xuebing Wang","avatar":""},{"name":"Lei Jiayin","avatar":""},{"name":"Liu Tianzuo","avatar":""},{"name":"Rao Xiaozhi","avatar":""},{"name":"Xiao Yang","avatar":""},{"name":"Guo Yiqian","avatar":""},{"name":"Lau Ho-leung","avatar":""},{"name":"Shi Hang","avatar":""},{"name":"Wang Ge","avatar":""},{"name":"Zhang Ning","avatar":""},{"name":"Xiaodong Gu","avatar":""},{"name":"Wang Zichuan","avatar":""},{"name":"Zhang Zhanyi","avatar":""},{"name":"Su Shuhe","avatar":""},{"name":"Xu Cha","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324328);
