INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('roberto-baggio-duoi-ngua-than-thanh', 'Roberto Baggio: Đuôi ngựa thần thánh', 'Baggio: The Divine Ponytail', 'https://phimimg.com/upload/vod/20231101-1/440e01f7fb456409dfaa8c84dc65c313.jpg', 'https://phimimg.com/upload/vod/20231101-1/975e42f007aeff6e6e2e63b8fec41a5c.jpg', '<p>Câu chuyện về Roberto Baggio, một trong những cầu thủ bóng đá giỏi nhất mọi thời đại: những thành tích nổi bật, chiến thắng trước chấn thương và việc lĩnh ngộ Phật giáo.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Andrea Arcangeli","avatar":""},{"name":"Valentina Bellè","avatar":""},{"name":"Andrea Pennacchi","avatar":""},{"name":"Antonio Zavatteri","avatar":""},{"name":"Anna Ferruzzo","avatar":""},{"name":"Riccardo Goretti","avatar":""},{"name":"Roberto Turchetta","avatar":""},{"name":"Martufello","avatar":""},{"name":"Thomas Trabacchi","avatar":""},{"name":"Marc Clotet","avatar":""},{"name":"Simone Colombari","avatar":""},{"name":"Alice Ottavi","avatar":""},{"name":"Ginevra Ottavi","avatar":""},{"name":"Matteo Pachera","avatar":""},{"name":"Federico Pasquali","avatar":""},{"name":"Beppe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324328);
