INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-kargil', 'Cuộc chiến Kargil', 'Shershaah', 'https://phimimg.com/upload/vod/20231101-1/e5f9408e29df719add87e0f92a56083c.jpg', 'https://phimimg.com/upload/vod/20231101-1/45fc2c81fa028b346f1e3c39aee90b4f.jpg', '<p>Lấy cảm hứng từ cuộc đời của đội trưởng Vikram Batra (PVC), bộ phim tôn vinh sự quả cảm, tinh thần dũng cảm của anh và tôn vinh sự hy sinh vô giá của anh trong trận chiến Kargil năm 1999, khi anh mới 24 tuổi.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Sidharth Malhotra","avatar":""},{"name":"Kiara Advani","avatar":""},{"name":"Shataf Figar","avatar":""},{"name":"Shiv Panditt","avatar":""},{"name":"Nikitin Dheer","avatar":""},{"name":"Raj Arjun","avatar":""},{"name":"Abhiroy Singh","avatar":""},{"name":"Anil Charanjeett","avatar":""},{"name":"Pawan Chopra","avatar":""},{"name":"Sahil Vaid","avatar":""},{"name":"Mir Sarwar","avatar":""},{"name":"Trishaan","avatar":""},{"name":"Himanshu Malhotra","avatar":""},{"name":"Pranay Pachauri","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324328);
