INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-tru-toi-loi', 'Vũ Trụ Tội Lỗi', 'Cosmic Sin', 'https://phimimg.com/upload/vod/20231101-1/e71706e3cadd78f677017b506e4b7a94.jpg', 'https://phimimg.com/upload/vod/20231101-1/7d1507c8249881de6596eccac1fe98d9.jpg', '<p>Vũ Trụ Tội Lỗi - Cosmic Sin lấy bối cảnh tương lai vào năm 2524, lúc này là bốn thế kỷ sau khi con người bắt đầu chiếm giữ các hành tinh bên ngoài. Tướng James Ford đã nghỉ hưu được gọi trở lại phục vụ sau khi một hạm đội thù địch ngoài hành tinh tấn công những người lính trên một hành tinh xa xôi. Mối đe dọa chống lại loài người nhanh chóng leo thang thành một cuộc chiến giữa các vì sao.</p>', 'Full', 1, 'single', 'completed', 10, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Adelaide Kane","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Costas Mandylor","avatar":""},{"name":"Johnny Messner","avatar":""},{"name":"Brandon Thomas Lee","avatar":""},{"name":"Eva De Dominici","avatar":""},{"name":"Corey Large","avatar":""},{"name":"Lana","avatar":""},{"name":"Perrey Reeves","avatar":""},{"name":"Trevor Gretzky","avatar":""},{"name":"Robert Laenen","avatar":""},{"name":"Mark Rhynard","avatar":""},{"name":"Austin Humble","avatar":""},{"name":"Tabitha Woodman","avatar":""},{"name":"Everly Large","avatar":""},{"name":"Tr","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324328);
