INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tia-chop-murali', 'Tia Chớp Murali', 'Minnal Murali', 'https://phimimg.com/upload/vod/20231101-1/f6efd0afc15ab210380c4a6d341d2ae6.jpg', 'https://phimimg.com/upload/vod/20231101-1/3b42413e2a4bd9123059342db77a48fe.jpg', '<p>Một thợ may có được năng lực đặc biệt sau khi bị sét đánh, nhưng anh phải hạ một đối thủ không ngờ tới trên đường trở thành siêu anh hùng mà quê nhà cần.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Tovino Thomas","avatar":""},{"name":"Guru Somasundaram","avatar":""},{"name":"Harisree Ashokan","avatar":""},{"name":"Aju Varghese","avatar":""},{"name":"Baiju Santhosh","avatar":""},{"name":"Femina George","avatar":""},{"name":"Sneha Babu","avatar":""},{"name":"Bijukuttan","avatar":""},{"name":"Jude Anthany Joseph","avatar":""},{"name":"P Balachandran","avatar":""},{"name":"Mamukkoya","avatar":""},{"name":"Rajesh Madhavan","avatar":""},{"name":"Vasisht Umesh","avatar":""},{"name":"Shelly Kishore","avatar":""},{"name":"Devi Chandana","avatar":""},{"name":"Sudheesh","avatar":""},{"name":"Arya Salim","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324328);
