INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phap-y-tong-tu-2-tu-tong-toi', 'Pháp Y Tống Từ 2: Tứ Tông Tội', 'Work in Vain Song Ci', 'https://phimimg.com/upload/vod/20231101-1/0e30afc836939d8d102ab41e9809bd43.jpg', 'https://phimimg.com/upload/vod/20231101-1/2667387c5092bdb0f1e0f7ad1a0bb083.jpg', '<p>Trong thời kỳ triệu Tống, Tống Từ đến huyện Trường Thinh nhậm chức và dốc lòng nghiên cứu cách khám nghiệm tử thi để sáng tác “Tẩy Oan Tập Lục”. Một tối, một đàn ông và một đàn bà chết cùng lúc. Vụ này khiến cả huyện kinh hãi. Tống Từ bắt đầu điều tra và phát hiện vụ này kỳ lạ thật sự. Khi Tống Từ đang bó tay, ông đột nhiên nhớ tới một đàn bà mà ông không dám đi thăm, “Vạn Sự Thông” của huyện Trường Thinh Đan Thanh. Tống Từ liền đến nơi ở của Đan Thanh, hỏi về hai vụ án mạng gần đây và xin Đan Thanh cùng tra án. Sau họ điều tra và suy lý, cuối cùng chân tướng được lộ rõ.</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324328);
