INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-mat-cua-tammy-faye', 'Đôi Mắt Của Tammy Faye', 'The Eyes of Tammy Faye', 'https://phimimg.com/upload/vod/20231101-1/76d7b041b00f1156fa6419950f06def0.jpg', 'https://phimimg.com/upload/vod/20231101-1/9c0bf7ee14ea34e60fd308433c12e65c.jpg', '<p>The Eyes of Tammy Faye lấy bối cảnh vào những năm 1970 và 1980, khi Tammy Faye và Jim Bakker đã cùng nhau cố gắng vượt qua mọi khó khăn và vươn lên từ sự khởi đầu bấp bênh và thành công tạo ra được một mạng lưới truyền hình tôn giáo lớn nhất thế giới và được mọi người ủng hộ vì nó truyền tải những thông điệp về tình yêu và sự chấp nhận trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jessica Chastain","avatar":""},{"name":"Andrew Garfield","avatar":""},{"name":"Cherry Jones","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Mark Wystrach","avatar":""},{"name":"Sam Jaeger","avatar":""},{"name":"Louis Cancelmi","avatar":""},{"name":"Gabriel Olds","avatar":""},{"name":"Fredric Lehne","avatar":""},{"name":"Chandler Head","avatar":""},{"name":"Jay Huguley","avatar":""},{"name":"Dan Johnson","avatar":""},{"name":"Michael MacCauley","avatar":""},{"name":"Grant Owens","avatar":""},{"name":"Coley Campany","avatar":""},{"name":"Craig Newkirk","avatar":""},{"name":"Wes Jet","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324328);
