INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-hon-loan', 'Hành Tinh Hỗn Loạn', 'Chaos Walking', 'https://phimimg.com/upload/vod/20231030-1/de1d4eb90048cbd4704b020f521295b7.jpg', 'https://phimimg.com/upload/vod/20231030-1/a2bd8df2e2ed6d288b538198765798a2.jpg', '<p>Todd Hewwitt (Tom Holland) tình cờ phát hiện ra Viola (Daisy Ridley)- một cô gái sống sót sau khi phi thuyền của cô gặp nạn và rơi xuống hành tinh của cậu. Hành tinh này không hề có bóng dáng phụ nữ, còn đàn ông thì bị ảnh hưởng bởi &quot;Tiếng Ồn&quot; - một thế lực thể hiện toàn bộ suy nghĩ của họ ra bên ngoài. Vì là cô gái duy nhất trên hành tinh kì lạ này, tính mạng của Viola bị đe dọa. Todd quyết tâm bảo vệ Viola và cả hai bị cuốn vào cuộc phiêu lưu nguy hiểm. Từ đó, Todd dần khám phá ra năng lực đặc biệt của mình, và phát hiện ra những bí mật đen tối của hành tinh mà cậu đang sống.</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Daisy Ridley","avatar":""},{"name":"Tom Holland","avatar":""},{"name":"Mads Mikkelsen","avatar":""},{"name":"Demián Bichir","avatar":""},{"name":"David Oyelowo","avatar":""},{"name":"Kurt Sutter","avatar":""},{"name":"Cynthia Erivo","avatar":""},{"name":"Bethany Anne Lind","avatar":""},{"name":"Nick Jonas","avatar":""},{"name":"Ray McKinnon","avatar":""},{"name":"Vincent Leclerc","avatar":""},{"name":"Blane Crockarell","avatar":""},{"name":"François Gauthier","avatar":""},{"name":"Tyrone Benskin","avatar":""},{"name":"Frank Fontaine","avatar":""},{"name":"Don Jordan","avatar":""},{"name":"Patrick Gar","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuon