INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-bang-gia', 'Con Đường Băng Giá', 'The Ice Road', 'https://phimimg.com/upload/vod/20231030-1/d49298bd33985ef04a12be5e0f99137a.jpg', 'https://phimimg.com/upload/vod/20231030-1/3df5d8ff09aa344ee53d2c8c7efe9a96.jpg', '<p>Sau khi một mỏ kim cương hẻo lánh bị sập ở vùng xa phía bắc của Canada, một người lái xe băng dẫn đầu một nhiệm vụ cứu hộ phi thường trên đại dương đóng băng để cứu mạng sống của những người thợ mỏ bị mắc kẹt mặc dù nước tan băng và mối đe dọa mà họ không bao giờ thấy sắp tới.</p>', 'Full', 1, 'single', 'completed', 17, 2021, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Marcus Thomas","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Amber Midthunder","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Matt McCoy","avatar":""},{"name":"Martin Sensmeier","avatar":""},{"name":"Matt Salinger","avatar":""},{"name":"BJ Verot","avatar":""},{"name":"Bradley Sawatzky","avatar":""},{"name":"Chad Bruce","avatar":""},{"name":"Jake Kennerd","avatar":""},{"name":"Arne MacPherson","avatar":""},{"name":"Paul Essiembre","avatar":""},{"name":"Marshall Williams","avatar":""},{"name":"Adam Hurtig","avatar":""},{"name":"Benjamin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324328);
