INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-bao-den', 'Băng Đảng Báo Đen', 'Judas and the Black Messiah', 'https://phimimg.com/upload/vod/20231030-1/fb21a147425348f7a7013ced89bb640c.jpg', 'https://phimimg.com/upload/vod/20231030-1/cec2b8aeccb5d73e0b3a1a92f7a94b3b.jpg', '<p>Bill O &amp; Neal thâm nhập Black Panthers theo lệnh của Đặc vụ FBI Mitchell và J. Edgar Hoover. Khi Chủ tịch Black Panther, Fred Hampton thăng tiến — phải lòng một người đồng hương cách mạng trên đường — một trận chiến giành lấy linh hồn của O&#39;Neal.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"LaKeith Stanfield","avatar":""},{"name":"Daniel Kaluuya","avatar":""},{"name":"Dominique Fishback","avatar":""},{"name":"Jesse Plemons","avatar":""},{"name":"Ashton Sanders","avatar":""},{"name":"Algee Smith","avatar":""},{"name":"Darrell Britt-Gibson","avatar":""},{"name":"Lil Rel Howery","avatar":""},{"name":"Dominique Thorne","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"Amari Cheatom","avatar":""},{"name":"Ian Duff","avatar":""},{"name":"Caleb Eberhardt","avatar":""},{"name":"Robert Longstreet","avatar":""},{"name":"Nick Fink","avatar":""},{"name":"Nicholas Velez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324328);
