INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bau-troi-nhuom-mau', 'Bầu Trời Nhuốm Máu', 'Blood Red Sky', 'https://phimimg.com/upload/vod/20231030-1/8e85aa52e9e847acb6d556bac41f93d5.jpg', 'https://phimimg.com/upload/vod/20231030-1/41925165a00779108c6f8946f29dd023.jpg', '<p>Một người phụ nữ mắc chứng bệnh bí ẩn buộc phải hành động khi một nhóm khủng bố cố gắng cướp một chuyến bay xuyên Đại Tây Dương qua đêm. Để bảo vệ con trai mình, cô sẽ phải tiết lộ một bí mật đen tối, và giải phóng con quái vật bên trong mà cô đã chiến đấu để che giấu.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Peri Baumeister","avatar":""},{"name":"Carl Anton Koch","avatar":""},{"name":"Kais Setti","avatar":""},{"name":"Alexander Scheer","avatar":""},{"name":"Dominic Purcell","avatar":""},{"name":"Graham McTavish","avatar":""},{"name":"Roland Møller","avatar":""},{"name":"Chidi Ajufo","avatar":""},{"name":"Rebecca Dyson-Smith","avatar":""},{"name":"Leonie Brill","avatar":""},{"name":"Nele Kiper","avatar":""},{"name":"Rainer Reiners","avatar":""},{"name":"Ilona Schulz","avatar":""},{"name":"Nader Ben-Abdallah","avatar":""},{"name":"Jacqueline Macaulay","avatar":""},{"name":"Wolfgang Mi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324328);
