INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bau-vat-cua-nhoc-nicolas', 'Báu Vật Của Nhóc Nicolas', 'Little Nicholas'' Treasure', 'https://phimimg.com/upload/vod/20231030-1/8b33203dc73fe310d44eb5b9557f8faa.jpg', 'https://phimimg.com/upload/vod/20231030-1/a3f00e2e836fefc3b6cd1d50c8901c57.jpg', '<p>Trong thế giới yên bình của cậu bé Nicholas, có Bố, có Mẹ, trường học và trên hết là nhóm bạn của cậu. Họ được gọi là Những kẻ bất khả chiến bại, nhưng trên hết họ không thể tách rời. Ít nhất là họ nghĩ vậy. Nhưng khi bố được thăng chức và thông báo rằng gia đình sẽ chuyển đến miền nam nước Pháp, Nicolas&quot; thế giới sụp đổ. Làm thế nào anh ấy có thể tưởng tượng cuộc sống mà không có những người bạn thân nhất của mình?</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Ilan Debrabant","avatar":""},{"name":"Jean-Paul Rouve","avatar":""},{"name":"Audrey Lamy","avatar":""},{"name":"Pierre Arditi","avatar":""},{"name":"Grégory Gadebois","avatar":""},{"name":"Jean-Pierre Darroussin","avatar":""},{"name":"Adeline D''Hermy","avatar":""},{"name":"Noémie Lvovsky","avatar":""},{"name":"François Morel","avatar":""},{"name":"Anton Alluin","avatar":""},{"name":"Oscar Boissière","avatar":""},{"name":"Léandre Castellano-Lemoine","avatar":""},{"name":"Malo Chanson-Demange","avatar":""},{"name":"Simon Faliu","avatar":""},{"name":"Mali","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324328);
