INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-tuong-sieu-nhien-nguoi-than-tiep-theo', 'Hiện Tượng Siêu Nhiên: Người Thân Tiếp Theo', 'Paranormal Activity: Next of Kin', 'https://phimimg.com/upload/vod/20231026-1/73a1a1d2eb61ac42bc08a171623bd4eb.jpg', 'https://phimimg.com/upload/vod/20231026-1/32110ffaccbb0b77d6c6445989a7c3fa.jpg', '<p>Một nhà làm phim tài liệu theo chân Margot, khi cô tìm đến một cộng đồng người Amish sống ẩn dật với hy vọng gặp gỡ và tìm hiểu về người mẹ thất lạc từ lâu và đại gia đình của mình. Sau một chuỗi các sự kiện và khám phá kỳ lạ, cô sớm nhận ra cộng đồng đang chào đón mình có thể đang che giấu một điều nham hiểm gì đó.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Emily Bader","avatar":""},{"name":"Ari Notartomaso","avatar":""},{"name":"Alexa Shae Niziak","avatar":""},{"name":"Dan Lippert","avatar":""},{"name":"Kyli Zion","avatar":""},{"name":"Jaye Ayres-Brown","avatar":""},{"name":"Wesley Han","avatar":""},{"name":"Emerald Rose Sullivan","avatar":""},{"name":"Roland Buck III","avatar":""},{"name":"Jill Andre","avatar":""},{"name":"Tom Nowicki","avatar":""},{"name":"Colin Keane","avatar":""},{"name":"Michael Short","avatar":""},{"name":"Al Garrison","avatar":""},{"name":"Emily Brobst","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324328);
