INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pho-fear-phan-1-1994', 'Phố Fear Phần 1: 1994', 'Fear Street: 1994', 'https://phimimg.com/upload/vod/20231026-1/3600c57a0ea9dfc734f4ca87970cbce4.jpg', 'https://phimimg.com/upload/vod/20231026-1/2002eb7e812baf3ba7aa4df275abfe72.jpg', '<p>Sau hàng loạt vụ giết người tàn bạo, một thiếu niên và bạn bè của cô phải đối mặt với một thế lực tà ác đang hoành hành thị trấn khét tiếng của họ trong nhiều thế kỷ.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kiana Madeira","avatar":""},{"name":"Olivia Scott Welch","avatar":""},{"name":"Benjamin Flores Jr.","avatar":""},{"name":"Julia Rehwald","avatar":""},{"name":"Fred Hechinger","avatar":""},{"name":"Ashley Zukerman","avatar":""},{"name":"Jordyn DiNatale","avatar":""},{"name":"Noah Bain Garret","avatar":""},{"name":"Lloyd Pitts","avatar":""},{"name":"Maya Hawke","avatar":""},{"name":"David W. Thompson","avatar":""},{"name":"Darrell Britt-Gibson","avatar":""},{"name":"Jordana Spiro","avatar":""},{"name":"Charlene Amoia","avatar":""},{"name":"Jana Allen","avatar":""},{"name":"Matt Bu","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324328);
