INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phao-dai', 'Pháo Đài', 'Fortress', 'https://phimimg.com/upload/vod/20231026-1/0552bd572aa861f99b9feaa78f7e87e2.jpg', 'https://phimimg.com/upload/vod/20231026-1/e73a249acaa55683d9ad91a91fc030d9.jpg', '<p>Pháo Đài - Fortress kể về người đàn ông Robert, một nhân viên CIA đã về hưu và sinh sống tại một ngôi nhà trong khu rừng hẻo lánh. Một hôm, khi đứa con trai bị ghẻ lạnh của anh bất ngờ đến thăm nhà, nhưng cậu ta không hề biết rằng bản thân đã bị kẻ thù cũ của Robert theo dõi là Balzary. Giờ đây cả căn nhà đã bị lính đội quân của Balzary bao vây tứ phía, và hai cha con đã nhanh chóng trốn thoát đến một Boongke công nghệ cao, nơi được bao quanh bởi các bức tường thép và vũ khí công nghệ cao. Liệu với những thứ tối tân ấy có giúp hai cha con thoát khỏi sự truy bắt của kẻ thù?</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jesse Metcalfe","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Chad Michael Murray","avatar":""},{"name":"Kelly Greyson","avatar":""},{"name":"Ser''Darius Blain","avatar":""},{"name":"Katalina Viteri","avatar":""},{"name":"Shannen Doherty","avatar":""},{"name":"Natalie Burn","avatar":""},{"name":"Kaleina Cordova","avatar":""},{"name":"Leslee Emmett","avatar":""},{"name":"Sean Kanan","avatar":""},{"name":"James Cullen Bressack","avatar":""},{"name":"Simon Phillips","avatar":""},{"name":"Trae Ireland","avatar":""},{"name":"Michael Sirow","avatar":""},{"name":"Luis D","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324328);
