INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rung-dong-ngot-ngao', 'Rung Động Ngọt Ngào', 'Nothing Serious', 'https://phimimg.com/upload/vod/20231026-1/c4d0820731f0aa8ff4151ce14c1bb1d6.jpg', 'https://phimimg.com/upload/vod/20231026-1/3e6a4db95e95fd0b84101cec6b67c335.jpg', '<p>Phim xoay quanh câu chuyện của hai nhân vật Woo Ri và Ja Young, hai con người với hai hoàn cảnh khác nhau. Nếu Woo Ri là một phóng viên tiên binh và được giao nhiệm vụ viết về tình dục, mà đã 33 tuổi anh ấy vẫn độc thân chẳng có được mối tình lãng mạn nào. Ja Young lại cô gái có nhiều tham vọng, 29 tuổi cô ấy mong muốn mình có thể thành công trước 30 tuổi nhưng lại luôn rơi vào thất bại và bị người yêu bỏ rơi. Thông qua một ứng dụng trên mạng, hai người họ đã quen nhau và quyết định hẹn hò.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jun Jong-seo","avatar":""},{"name":"Son Suk-ku","avatar":""},{"name":"Gong Min-jeung","avatar":""},{"name":"Kim Seul-ki","avatar":""},{"name":"Bae Yoo-ram","avatar":""},{"name":"Kim Jae-hwa","avatar":""},{"name":"Im Sung-jae","avatar":""},{"name":"Lim Sun-woo","avatar":""},{"name":"Kim Young-ok","avatar":""},{"name":"Kim Kwang-kyu","avatar":""},{"name":"Lee Hak-ju","avatar":""},{"name":"Park Jong-hwan","avatar":""},{"name":"Jang Eui-soo","avatar":""},{"name":"Jang Seo-Kyung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324328);
