INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-giat', 'Cú Giật', 'Jolt', 'https://phimimg.com/upload/vod/20231024-1/416324617ee56dd0e0d3760f4e82c31d.jpg', 'https://phimimg.com/upload/vod/20231024-1/2eafb801c495d7eb976225cd9054c1bf.jpg', '<p>Jolt (2021) là một bộ phim hành động Mỹ của đạo diển Tanya Wexler, nói về cô gái Lindy, một cô gái mang trong mình cơn rối loạn thần kinh hiếm gặp đã bị kết án oan sau khi sát hại người bạn trai, cô ta phải đối mặt với nguy hiểm khi điều tra và phải chạy trốn cảnh sát khỏi cuộc truy tìm.</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Bulgaria', 0, '[{"name":"Kate Beckinsale","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"Laverne Cox","avatar":""},{"name":"David Bradley","avatar":""},{"name":"Susan Sarandon","avatar":""},{"name":"Ori Pfeffer","avatar":""},{"name":"James Grogan","avatar":""},{"name":"Lili Rich","avatar":""},{"name":"Christian Brassington","avatar":""},{"name":"Richard Price","avatar":""},{"name":"Adam Brashaw","avatar":""},{"name":"Tom Xander","avatar":""},{"name":"Stuart Shepherd-Garner","avatar":""},{"name":"Sophie Sanderson","avatar":""},{"name":"Evan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324328);
