INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lang-khach-kenshin-hoi-ket', 'Lãng Khách Kenshin: Hồi Kết', 'Rurouni Kenshin: The Final', 'lãng khách kenshin: hồi kết rurouni kenshin: the final takeru satoh emi takei mackenyu munetaka aoki yu aoi yûsuke iseya tao tsuchiya ryosuke miura yosuke eguchi takuma otoo shingo tsurumi takeo nakahara riku onishi kazuki kitamura shinnosuke abe shuntaro yanagi joey iwanaga eiki narita kasu ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gac', 'Gạc', 'Antlers', 'https://phimimg.com/upload/vod/20231024-1/1065757fe069eabc059f799e1675b032.jpg', 'https://phimimg.com/upload/vod/20231024-1/f68550d58cc60d9df5be611a9e3175ed.jpg', '<p>Nội dung xoay quanh những điều bí ẩn xảy ra tại Oregon, một thị trấn bị cô lập. Ở đây, một cô giáo cấp hai và anh trai là cảnh sát trưởng của mình đã bị lôi kéo vào sự việc đầy nguy hiểm với những học sinh bí ẩn của cô. Học sinh này đều có bí mật đen tối, vì thế mà hai anh em cô đã có một cuộc gặp gỡ đáng sợ với một sinh vật tổ tiên huyền thoại đến trước họ.</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keri Russell","avatar":""},{"name":"Jesse Plemons","avatar":""},{"name":"Jeremy Thomas","avatar":""},{"name":"Graham Greene","avatar":""},{"name":"Scott Haze","avatar":""},{"name":"Sawyer Jones","avatar":""},{"name":"Rory Cochrane","avatar":""},{"name":"Amy Madigan","avatar":""},{"name":"Cody Davis","avatar":""},{"name":"Glynis Davies","avatar":""},{"name":"Dorian Kingi","avatar":""},{"name":"Arlo Hajdu","avatar":""},{"name":"Andy Thompson","avatar":""},{"name":"Jesse Downs","avatar":""},{"name":"Dendrie Taylor","avatar":""},{"name":"Katelyn Peterson","avatar":""},{"name":"Charmaine Wilson","avatar":""},{"name":"Jay Braze","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324328);
