INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-trong-bong-toi-2', 'Sát Nhân Trong Bóng Tối 2', 'Don''t Breathe 2', 'https://phimimg.com/upload/vod/20231024-1/098d1517accc6fc67b875a20a25b206f.jpg', 'https://phimimg.com/upload/vod/20231024-1/126cef9782fa7d0327f2f88522158185.jpg', '<p>Sát Nhân Trong Bóng Tối 2 sẽ mở rộng câu chuyện về Mr. Blind Man khi anh đã ẩn náu vài năm trong một căn nhà gỗ biệt lập và đã nhận và nuôi dạy một cô gái trẻ mồ côi từ một vụ cháy nhà kinh hoàng. Cuộc sống êm ấm bên nhau của họ tan vỡ khi một nhóm tội phạm bắt cóc cô gái, buộc anh phải rời nơi trú ẩn an toàn để cứu cô.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stephen Lang","avatar":""},{"name":"Brendan Sexton III","avatar":""},{"name":"Madelyn Grace","avatar":""},{"name":"Stephanie Arcila","avatar":""},{"name":"Rocci Williams","avatar":""},{"name":"Bobby Schofield","avatar":""},{"name":"Adam Young","avatar":""},{"name":"Fiona O''Shaughnessy","avatar":""},{"name":"Steffan Rhodri","avatar":""},{"name":"Diaana Babnicova","avatar":""},{"name":"Christian Zagia","avatar":""},{"name":"Ron Rogell","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324328);
