INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-nhan-trong-bong-toi-2', 'Sát Nhân Trong Bóng Tối 2', 'Don''t Breathe 2', 'sát nhân trong bóng tối 2 don''t breathe 2 stephen lang brendan sexton iii madelyn grace stephanie arcila rocci williams bobby schofield adam young fiona o''shaughnessy steffan rhodri diaana babnicova christian zagia ron rogell ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-anh-hung-3-nhiem-vu-giai-cuu-the-gioi', 'Học Viện Anh Hùng 3: Nhiệm Vụ Giải Cứu Thế Giới', 'My Hero Academia: World Heroes'' Mission', 'https://phimimg.com/upload/vod/20231023-1/33034490d1bdfa9460830c38f94956a3.jpg', 'https://phimimg.com/upload/vod/20231023-1/20fc5d2a5c9f84fb8eb95d1e6ca15132.jpg', '<p>My Hero Academia: World Heroes&quot; Mission sẽ tiếp nối các dự kiện diễn ra sau mùa 5 của anime TV. Một nhóm người bí ẩn tự xưng là Humarize rất tin tưởng vòa giả thuyết những đứa trẻ sở hữu Quirk có thể khiến sự sống của nhân loại kết thúc. Vì thế, họ thực hiện nhiệm vụ thanh lọc những đứa trẻ sở hữu Quirk, nhưng đồng thời cũng gây ra sự phá hoại khủng khiếp và hủy diệt vô số sinh mệnh.&nbsp; Để cứu mọi người, các anh hùng chuyên nghiệp đã yêu cầu các anh hùng của trường trng học U.A ra tay ứng cứu. Thế nhưng trong quá trình thực hiện nhiệm vụ có những rắc rối đã xảy ra khiến thế giới thêm phần hỗn loạn.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2021, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Daiki Yamashita","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Ryo Yoshizawa","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Tetsu Inada","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Ryo Hirohashi","avatar":""},{"name":"Aoi Yuki","avatar":""},{"name":"Kei Shindo","avatar":""},{"name":"Toshiki Masuda","avatar":""},{"name":"Tasuku Hatanaka","avatar":""},{"name":"Masakazu Nishida","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324328);
