INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoc-vien-anh-hung-3-nhiem-vu-giai-cuu-the-gioi', 'Học Viện Anh Hùng 3: Nhiệm Vụ Giải Cứu Thế Giới', 'My Hero Academia: World Heroes'' Mission', 'học viện anh hùng 3: nhiệm vụ giải cứu thế giới my hero academia: world heroes'' mission daiki yamashita nobuhiko okamoto yuki kaji ryo yoshizawa kazuya nakai megumi hayashibara kenta miyake tetsu inada yuichi nakamura ayane sakura marina inoue ryo hirohashi aoi yuki kei shindo toshiki masuda tasuku hatanaka masakazu nishida ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-cuoi-cung-coi-nguon-cua-quy', 'Chiến Binh Cuối Cùng: Cội Nguồn Của Quỷ', 'The Last Warrior: Root of Evil', 'https://phimimg.com/upload/vod/20231023-1/80efc09d2d6b3befb9675a6120028340.jpg', 'https://phimimg.com/upload/vod/20231023-1/d3c76ab57b7d7357b01df417553ff9f4.jpg', '<p>Hòa bình đã được thiết lập tại Belogorie sau khi cái ác bị đánh bại và Ivan đang tận hưởng sự nổi tiếng mà anh xứng đáng. Không chỉ có được sự tín nhiệm từ gia đình, bạn bè và những điều mới lạ từ thế giới hiện đại đã mang tới cho anh một cuộc sống thoải mái, Ivan còn may mắn sở hữu thanh gươm phép thuật giúp việc di chuyển giữa hai thế giới trở nên thuận tiện hơn. Song, sự trỗi dậy của một ác quỷ cổ đại đã đe dọa thế giới ma thuật, Ivan quyết định hợp tác với những người bạn cũ và đối thủ của mình để bắt đầu cuộc hành trình dài tới vùng không gian mới, nhằm tìm cách đánh bạn kẻ thù cũng như trả lại hòa bình cho Belogorie.</p>', 'Full', 1, 'single', 'completed', 21, 2021, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Viktor Horinyak","avatar":""},{"name":"Mila Syvatska","avatar":""},{"name":"Ekaterina Vilkova","avatar":""},{"name":"Elena Yakovleva","avatar":""},{"name":"Konstantin Lavronenko","avatar":""},{"name":"Evgeniy Dyatlov","avatar":""},{"name":"Timofey Tribuntsev","avatar":""},{"name":"Pavel Davydov","avatar":""},{"name":"Aleksandr Semchev","avatar":""},{"name":"Sergey Burunov","avatar":""},{"name":"Elena Valyushkina","avatar":""},{"name":"Kirill Zaytsev","avatar":""},{"name":"Yuriy Tsurilo","avatar":""},{"name":"Taisiya Vilkova","avatar":""},{"name":"Sophia Bor","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324328);
