INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chien-binh-cuoi-cung-coi-nguon-cua-quy', 'Chiến Binh Cuối Cùng: Cội Nguồn Của Quỷ', 'The Last Warrior: Root of Evil', 'chiến binh cuối cùng: cội nguồn của quỷ the last warrior: root of evil viktor horinyak mila syvatska ekaterina vilkova elena yakovleva konstantin lavronenko evgeniy dyatlov timofey tribuntsev pavel davydov aleksandr semchev sergey burunov elena valyushkina kirill zaytsev yuriy tsurilo taisiya vilkova sophia bor ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tom-va-jerry-quay-tung-new-york', 'Tom và Jerry: Quậy Tung New York', 'Tom & Jerry', 'https://phimimg.com/upload/vod/20231022-1/9de7163e2f6ec39f92a112c72b60c383.jpg', 'https://phimimg.com/upload/vod/20231022-1/5fc99081d735fad9116140621c01c2b1.jpg', '<p>“Sau nhiều năm chành chọe, nay cặp kỳ phùng địch thủ nổi tiếng nhất thế giới Tom và Jerry đã làm hòa, khăn gói rời khỏi mái nhà chung, và bắt đầu hành trình của riêng mình. Chuột Jerry nay trú ngụ tại một khách sạn sang trọng, nơi chuẩn bị tổ chức một đám cưới Thế kỷ. Cô nhân viên mới Kayla được giao cho nhiệm vụ đuổi Jerry đi nên mang về một chàng mèo “mình đầy kinh nghiệm” đối phó với chuột, không ai khác chính là Tom. Và thế là cuộc chiến mèo - chuột lại nổ ra, kéo theo loạt rắc rối cho khách sạn, và biết bao tình huống dở khóc dở cười.“</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chloë Grace Moretz","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Colin Jost","avatar":""},{"name":"Rob Delaney","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Pallavi Sharda","avatar":""},{"name":"Jordan Bolger","avatar":""},{"name":"Patsy Ferran","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Nicky Jam","avatar":""},{"name":"Lil Rel Howery","avatar":""},{"name":"Joey Wells","avatar":""},{"name":"Na''im Lynn","avatar":""},{"name":"William Horton","avatar":""},{"name":"Harry Ratchford","avatar":""},{"name":"Utkarsh Ambudkar","avatar":""},{"name":"Tim Story","avatar":""},{"name":"Somi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324328);
