INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tom-va-jerry-quay-tung-new-york', 'Tom và Jerry: Quậy Tung New York', 'Tom & Jerry', 'tom và jerry: quậy tung new york tom & jerry chloë grace moretz michael peña colin jost rob delaney ken jeong pallavi sharda jordan bolger patsy ferran bobby cannavale nicky jam lil rel howery joey wells na''im lynn william horton harry ratchford utkarsh ambudkar tim story somi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-dau-cuoi-cung', 'Trận Đấu Cuối Cùng', 'The Last Duel', 'https://phimimg.com/upload/vod/20231022-1/fd2d86591a30285e5b8a53cac11da5e6.jpg', 'https://phimimg.com/upload/vod/20231022-1/9175ec6ed68b2208c5aac6b5627706c9.jpg', '<p>Jean de Carrouges là một hiệp sĩ được kính trọng, nổi tiếng với sự dũng cảm và tài giỏi trên chiến trường. Jacques Le Gris là một cận thần có trí thông minh và tài hùng biện khiến ông trở thành một trong những quý tộc được ngưỡng mộ nhất trong triều đình. Khi Le Gris hung ác tấn công vợ của Carrouges, cô ấy bước tới để buộc tội kẻ tấn công mình, một hành động dũng cảm và bất chấp khiến tính mạng của cô ấy gặp nguy hiểm. Cuộc thử thách tiếp theo bằng chiến đấu, một trận đấu cam go đến chết, đặt số phận của cả ba vào tay Chúa.</p>', 'Full', 1, 'single', 'completed', 17, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jodie Comer","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Adam Driver","avatar":""},{"name":"Ben Affleck","avatar":""},{"name":"Harriet Walter","avatar":""},{"name":"Marton Csokas","avatar":""},{"name":"Alex Lawther","avatar":""},{"name":"William Houston","avatar":""},{"name":"Oliver Cotton","avatar":""},{"name":"Aurélien Lorgnier","avatar":""},{"name":"Nathaniel Parker","avatar":""},{"name":"Tallulah Haddon","avatar":""},{"name":"Bryony Hannah","avatar":""},{"name":"Thomas Silberstein","avatar":""},{"name":"Adam Goodwin","avatar":""},{"name":"Ian Pirie","avatar":""},{"name":"Daniel Horn","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324328);
