INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-duoi-day-ho', 'Ngôi Nhà Dưới Đáy Hồ', 'The Deep House', 'https://phimimg.com/upload/vod/20231023-1/00999de253fae87035dc8ef2d8776ffd.jpg', 'https://phimimg.com/upload/vod/20231023-1/981d70ebfd7d963eba18ec489f6527ec.jpg', '<p>Khi đang lặn ở một hồ nước xa xôi của Pháp, một vài YouTuber chuyên quay video khám phá dưới nước đã phát hiện ra một ngôi nhà chìm trong vùng nước sâu. Những gì ban đầu là một phát hiện độc đáo sớm biến thành cơn ác mộng khi họ phát hiện ra rằng ngôi nhà là hiện trường của những tội ác tàn bạo. Bị mắc kẹt, lượng oxy dự trữ giảm xuống mức nguy hiểm, họ nhận ra điều tồi tệ nhất vẫn chưa xảy ra: họ không chỉ có một mình trong nhà.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"James Jagger","avatar":""},{"name":"Camille Rowe","avatar":""},{"name":"Eric Savin","avatar":""},{"name":"Carolina Massey","avatar":""},{"name":"Alexis Servaes","avatar":""},{"name":"Anne Claessens","avatar":""},{"name":"Marie Caffier","avatar":""},{"name":"Marie Bernard","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324328);
