INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('clifford-chu-cho-do-khong-lo', 'Clifford Chú Chó Đỏ Khổng Lồ', 'Clifford the Big Red Dog', 'https://phimimg.com/upload/vod/20231022-1/af21bf6389cc91049c031c192390685b.jpg', 'https://phimimg.com/upload/vod/20231022-1/90b5d35aebfefcb946c66453c3c0a20f.jpg', '<p>Khi phát hiện ra chú cún nhỏ màu đỏ tên Clifford của mình đã cao thêm ba mét chỉ sau một đêm, Emily tìm đến chú Casey lập dị của mình để được giúp đỡ. Nhưng khi một nhà khoa học điên tìm cách bắt chú chó con ham chơi thu hút sự chú ý này, toàn bộ khu phố phải giúp che giấu Clifford khi họ chạy đua khắp thành phố. Hãy sẵn sàng cho cuộc phiêu lưu hài hước đáng kinh ngạc, thú vị mang niềm vui LỚN cho cả gia đình!</p>', 'Full', 1, 'single', 'completed', 18, 2021, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Darby Camp","avatar":""},{"name":"Jack Whitehall","avatar":""},{"name":"Izaac Wang","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Tony Hale","avatar":""},{"name":"David Alan Grier","avatar":""},{"name":"Paul Rodríguez","avatar":""},{"name":"Horatio Sanz","avatar":""},{"name":"Sienna Guillory","avatar":""},{"name":"Rosie Perez","avatar":""},{"name":"Kenan Thompson","avatar":""},{"name":"Jessica Keenan Wynn","avatar":""},{"name":"Russell Wong","avatar":""},{"name":"Karen Lynn Gorney","avatar":""},{"name":"Melanie Chandra","avatar":""},{"name":"Russell Peters","avatar":""},{"name":"Kevin McCo","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324328);
