INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mong-ao-tan-bien', 'Mộng Ảo Tan Biến', 'Lost Illusions', 'https://phimimg.com/upload/vod/20231023-1/84c5673701c8982cd0fc29bc12e13f61.jpg', 'https://phimimg.com/upload/vod/20231023-1/76fa407464dd01acd13ba6d1728bf2d4.jpg', '<p>Lucien là một nhà thơ trẻ vô danh ở Pháp thế kỷ 19. Anh ấy có những kỳ vọng lớn và muốn rèn giũa vận mệnh của mình. Anh rời bỏ công việc kinh doanh in ấn của gia đình ở quê hương để thử vận may ở Paris, trong vòng tay của người bảo vệ anh. Chẳng bao lâu sau khi rời khỏi thành phố tuyệt vời với các thiết bị của riêng mình, chàng trai trẻ sẽ khám phá ra đằng sau một thế giới dành riêng cho quy luật lợi nhuận và sự giả vờ. Một vở hài kịch của con người nơi mọi thứ đều được mua và bán, văn học cũng như báo chí, chính trị cũng như tình cảm, danh tiếng cũng như tâm hồn. Anh ấy sẽ yêu, anh ấy sẽ đau khổ, và sống sót qua những ảo tưởng của mình.</p>', 'Full', 1, 'single', 'completed', 23, 2021, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Benjamin Voisin","avatar":""},{"name":"Cécile de France","avatar":""},{"name":"Vincent Lacoste","avatar":""},{"name":"Xavier Dolan","avatar":""},{"name":"Salomé Dewaels","avatar":""},{"name":"Jeanne Balibar","avatar":""},{"name":"André Marcon","avatar":""},{"name":"Louis-Do de Lencquesaing","avatar":""},{"name":"Gérard Depardieu","avatar":""},{"name":"Jean-François Stévenin","avatar":""},{"name":"Alexis Barbosa","avatar":""},{"name":"Arnaud de Montlivault","avatar":""},{"name":"Saïd Amadis","avatar":""},{"name":"Édouard Michelon","avatar":""},{"name":"Rapha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324328);
