INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-halloween', 'Sát Nhân Halloween', 'Halloween Kills', 'https://phimimg.com/upload/vod/20231021-1/9aaae1877919a43bd5c3934e62efe826.jpg', 'https://phimimg.com/upload/vod/20231021-1/f0f095fdd5268e1ab355bfdc7f9c25ae.jpg', '<p>Cơn ác mộng vẫn chưa kết thúc khi kẻ giết người không thể ngăn cản Michael Myers trốn thoát khỏi bẫy của Laurie Strode để tiếp tục nghi lễ tắm máu của mình. Bị thương và được đưa đến bệnh viện, Laurie cố gắng vượt qua nỗi đau khi truyền cảm hứng cho cư dân Haddonfield đứng lên chống lại Myers. Tự mình giải quyết vấn đề, những người phụ nữ Strode và những người sống sót khác thành lập một đám đông cảnh giác để truy lùng Michael và chấm dứt triều đại khủng bố của hắn một lần và mãi mãi.</p>', 'Full', 1, 'single', 'completed', 11, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jamie Lee Curtis","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Andi Matichak","avatar":""},{"name":"James Jude Courtney","avatar":""},{"name":"Nick Castle","avatar":""},{"name":"Airon Armstrong","avatar":""},{"name":"Will Patton","avatar":""},{"name":"Thomas Mann","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Dylan Arnold","avatar":""},{"name":"Robert Longstreet","avatar":""},{"name":"Anthony Michael Hall","avatar":""},{"name":"Charles Cyphers","avatar":""},{"name":"Scott MacArthur","avatar":""},{"name":"Michael McDonald","avatar":""},{"name":"Ross Bacon","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324328);
