INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-007-khong-phai-luc-chet', 'Điệp Viên 007: Không Phải Lúc Chết', 'No Time to Die', 'https://phimimg.com/upload/vod/20231019-1/464bfa48e2c1b343df197c9b6b95b789.jpg', 'https://phimimg.com/upload/vod/20231019-1/cfd8564c9365b0ef7b2aef74b8eaedb5.jpg', '<p>Phần 25 của bộ phim điệp viên huyền thoại 007 sẽ tiếp nối câu chuyện về James Bond cùng những pha hành động táo bạo và hoành tráng hơn bao giờ hết. Sau sự kiện đầy ám ảnh trong Spectre, Bond lui về ở ẩn tại đất nước Jamaica, sống một cuộc đời cô độc nhưng bình lặng. Bỗng một người bạn cũ từ CIA xuất hiện, cầu xin anh giúp đỡ. Bond bất đắc dĩ phải tái xuất, nhưng không hề biết mình sẽ đối đầu với thế lực nào. Chi tiết đáng chú ý nhất là chiếc mặt nạ trắng vỡ nửa, đánh dấu sự xuất hiện của tên ác nhân kì quái bậc nhất trong cả series 007. Màn chạm trán giữa Bond và kẻ thù nguy hiểm này sẽ vén màn những bí ẩn còn để ngỏ và tiếp theo đó, có thể là một cuộc đối đầu “sinh tử”.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Daniel Craig","avatar":""},{"name":"Léa Seydoux","avatar":""},{"name":"Rami Malek","avatar":""},{"name":"Lashana Lynch","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Ben Whishaw","avatar":""},{"name":"Naomie Harris","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Ana de Armas","avatar":""},{"name":"Billy Magnussen","avatar":""},{"name":"Christoph Waltz","avatar":""},{"name":"Rory Kinnear","avatar":""},{"name":"David Dencik","avatar":""},{"name":"Dali Benssalah","avatar":""},{"name":"Lisa-Dorah Sonnet","avatar":""},{"name":"Coline Defaud","avatar":""},{"name":"Mathilde Bourbin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324328);
