INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-san-ma-chuyen-kiep', 'Biệt Đội Săn Ma: Chuyển Kiếp', 'Ghostbusters: Afterlife', 'https://phimimg.com/upload/vod/20231019-1/faffb68ec88101d6ddbeab880dc6cad7.jpg', 'https://phimimg.com/upload/vod/20231019-1/a824f23e6d706049dc7c4a7a2b35deb0.jpg', '<p>Biệt Đội Săn Ma: Chuyển Kiếp xoay quanh bà mẹ đơn thân Callie cùng hai đứa con Trevor và Phoebe. Vì gia đình bị phá sản, họ đành chuyển về khu nông trại hẻo lánh do ông mình để lại ở vùng ngoại ô Summerville. Tại đây, bọn họ bắt đầu chứng kiến hàng loạt hiện tượng kì lạ như mặt đất đột ngột rung lắc hay mấy làn khói xanh đáng sợ.</p>', 'Full', 1, 'single', 'completed', 18, 2021, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Carrie Coon","avatar":""},{"name":"Finn Wolfhard","avatar":""},{"name":"Mckenna Grace","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Logan Kim","avatar":""},{"name":"Celeste O''Connor","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"Dan Aykroyd","avatar":""},{"name":"Ernie Hudson","avatar":""},{"name":"Annie Potts","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Bokeem Woodbine","avatar":""},{"name":"Tracy Letts","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Josh Gad","avatar":""},{"name":"Bob Gunton","avatar":""},{"name":"Billy Bryk","avatar":""},{"name":"Sydney Mae Diaz","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324328);
