INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('resident-evil-quy-du-troi-day', 'Resident Evil: Quỷ Dữ Trỗi Dậy', 'Resident Evil: Welcome to Raccoon City', 'https://phimimg.com/upload/vod/20231019-1/f28e7d00318bf1b1886956be866ce573.jpg', 'https://phimimg.com/upload/vod/20231019-1/fd88554a844f1ec154a427f51be0854d.jpg', '<p>Resident Evil là một trong những tựa game sinh tồn xác sống ăn khách nhất mọi thời đại. Sau 25 năm và 8 phần game gốc cùng hàng loạt ngoại truyện, tác phẩm ngày càng có đông đảo người hâm mộ. Loạt phim Resident Evil do Paul W.S. Anderson đạo diễn là một thành công về mặt thương mại nhưng bị nhiều fan chỉ trích vì rời quá xa nguyên tác. Do đó mà Sony quyết định tái khởi động thương hiệu với Resident Evil: Welcome to Raccoon City (Resident Evil: Quỷ dữ trỗi dậy) có nội dung lấy từ hai phần game đầu tiên.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Kaya Scodelario","avatar":""},{"name":"Hannah John-Kamen","avatar":""},{"name":"Robbie Amell","avatar":""},{"name":"Tom Hopper","avatar":""},{"name":"Avan Jogia","avatar":""},{"name":"Donal Logue","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Lily Gao","avatar":""},{"name":"Chad Rook","avatar":""},{"name":"Marina Mazepa","avatar":""},{"name":"Nathan Dales","avatar":""},{"name":"Josh Cruddas","avatar":""},{"name":"Pat Thornton","avatar":""},{"name":"Holly de Barros","avatar":""},{"name":"Janet Porter","avatar":""},{"name":"Lily Gail Reid","avatar":""},{"name":"Daxton Gujral","avatar":""},{"name":"Dylan Taylor","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc