INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toc-san-nguoi', 'Tộc Săn Người', 'Wrong Turn', 'https://phimimg.com/upload/vod/20231019-1/02da261386dde87c6cb1404929a5f04c.jpg', 'https://phimimg.com/upload/vod/20231019-1/d9cc8f0c683c4220c6a2abcf961b0987.jpg', '<p>Phim đưa chúng ta theo chân một nhóm bạn đến Harpers Ferry, Tây Virginia để dành vài ngày đi bộ đường dài trên đường mòn Appalachian. Chuỗi ngày “không may mắn” của họ bắt đầu khi phải đối mặt với “The Foundation” – một cộng đồng những người đã sống trên núi từ trước Nội chiến, và họ không ưa gì với người lạ, thậm chí muốn tiêu diệt bất cứ người lạ nào mà họ gặp.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Charlotte Vega","avatar":""},{"name":"Adain Bradley","avatar":""},{"name":"Bill Sage","avatar":""},{"name":"Emma Dumont","avatar":""},{"name":"Dylan McTee","avatar":""},{"name":"Daisy Head","avatar":""},{"name":"Matthew Modine","avatar":""},{"name":"Vardaan Arora","avatar":""},{"name":"Adrian Favela","avatar":""},{"name":"Tim DeZarn","avatar":""},{"name":"Rhyan Elizabeth Hanavan","avatar":""},{"name":"Chaney Morrow","avatar":""},{"name":"Cory Scott Allen","avatar":""},{"name":"Amy Warner","avatar":""},{"name":"Richard Hagerman","avatar":""},{"name":"Damian Maffei","avatar":""},{"name":"Mark Mench","avatar":""},{"name":"Da","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324328);
