INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-khat-mau-dong-mau-moi', 'Thiên Thần Khát Máu: Dòng Máu Mới', 'Dexter: New Blood', 'https://phimimg.com/upload/vod/20231021-1/150079adff1a67c6da1057d42f6c42d0.jpg', 'https://phimimg.com/upload/vod/20231021-1/ef678bd5231ed1138c193e187547461c.jpg', '<p>Dexter: New Blood sẽ vẫn tiếp tục theo chân kẻ giết người hàng loạt Dexter Morgan mười năm sau khi anh ta mất tích trong cơn bão Laura, vào cuối mùa cuối cùng của chương trình. Rời khỏi bờ biển đầy nắng ở Florida, sống dưới một cái tên giả ở Ironlake, New York, một thị trấn nhỏ bé, khiêm tốn, Dexter bận rộn với cuộc sống mới của mình cho đến khi những sự việc kinh hoàng tiếp tục xảy ra.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 22, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael C. Hall","avatar":""},{"name":"Jack Alcott","avatar":""},{"name":"Julia Jones","avatar":""},{"name":"Johnny Sequoyah","avatar":""},{"name":"Alano Miller","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Jennifer Carpenter","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324328);
