INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-tran-hoi-sinh', 'Ma Trận: Hồi Sinh', 'The Matrix Resurrections', 'https://phimimg.com/upload/vod/20231018-1/2ec7cb259dcaf1bfc7e3808ee4237946.jpg', 'https://phimimg.com/upload/vod/20231018-1/c31ed4b0ab4359f80f36c85b9842729a.jpg', '<p>Bị quấy rầy bởi những ký ức kỳ lạ, cuộc đời của Neo có một bước ngoặt bất ngờ khi anh thấy mình trở lại bên trong Ma trận.</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Carrie-Anne Moss","avatar":""},{"name":"Yahya Abdul-Mateen II","avatar":""},{"name":"Jonathan Groff","avatar":""},{"name":"Jessica Henwick","avatar":""},{"name":"Neil Patrick Harris","avatar":""},{"name":"Jada Pinkett Smith","avatar":""},{"name":"Priyanka Chopra Jonas","avatar":""},{"name":"Christina Ricci","avatar":""},{"name":"Lambert Wilson","avatar":""},{"name":"Andrew Lewis Caldwell","avatar":""},{"name":"Toby Onwumere","avatar":""},{"name":"Max Riemelt","avatar":""},{"name":"Joshua Grothe","avatar":""},{"name":"Bria","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324328);
