INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-addams-2', 'Gia Đình Addams 2', 'The Addams Family 2', 'https://phimimg.com/upload/vod/20231018-1/6a0b7cdd2ad5126bbc19956f0d383d24.jpg', 'https://phimimg.com/upload/vod/20231018-1/ac09768125aa755f0c0ff37fb9c218a4.jpg', '<p>Sự trở lại của The Addams Family 2 vào năm 2021 sẽ mang tới những điều “dị thường” không thể ngờ tới. Chỉ vừa kịp tuyên bố điều này, chú béo Fester đã ăn ngay phải một cú chơi khăm từ người em họ lông lá Itt. Rủ Itt đi câu cá nhưng lại câu phải đúng thuốc nổ. Cháy hết quần áo, cô cháu gái Wednesday đã “giúp khéo” chú mình bằng cách phun mực đen lên người. Không cần nhiều dẫn giải, khán giả có thể nhận ra giọng lồng tiếng quen thuộc của nữ diễn Chloë Grace Moretz trong vai cô con gái lớn Wednesday “khó ở” của nhà Addams.</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Oscar Isaac","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Chloë Grace Moretz","avatar":""},{"name":"Javon Walton","avatar":""},{"name":"Nick Kroll","avatar":""},{"name":"Snoop Dogg","avatar":""},{"name":"Bette Midler","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Wallace Shawn","avatar":""},{"name":"Conrad Vernon","avatar":""},{"name":"Brian Sommer","avatar":""},{"name":"Courtenay Taylor","avatar":""},{"name":"Cherami Leigh","avatar":""},{"name":"Mary Faber","avatar":""},{"name":"Kyla Pratt","avatar":""},{"name":"Charlet Chung","avatar":""},{"name":"Kyle Chapple","avatar":""},{"name":"Griffin Bur","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324328);
