INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-cua-vong-xoay-tu-than', 'Lưỡi Cưa: Vòng Xoáy Tử Thần', 'Spiral: From the Book of Saw', 'https://phimimg.com/upload/vod/20231017-1/c96065db2a3c14610dd0a63046ebc195.jpg', 'https://phimimg.com/upload/vod/20231017-1/6546a333c033c5c6efb9c407e66f5e59.jpg', '<p>Làm việc trong cái bóng của một cựu cảnh sát đáng kính, thám tử dũng cảm Ezekiel “Zeke” Banks và cộng sự tân binh của anh ấy phụ trách một cuộc điều tra rùng rợn về những vụ giết người gợi nhớ đến quá khứ khủng khiếp của thành phố. Vô tình bị cuốn vào một bí ẩn ngày càng sâu sắc, Zeke thấy mình là trung tâm của trò chơi bệnh hoạn của kẻ giết người.</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Rock","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Max Minghella","avatar":""},{"name":"Marisol Nichols","avatar":""},{"name":"Dan Petronijevic","avatar":""},{"name":"Richard Zeppieri","avatar":""},{"name":"Patrick McManus","avatar":""},{"name":"Edie Inksetter","avatar":""},{"name":"Thomas Mitchell","avatar":""},{"name":"Nazneen Contractor","avatar":""},{"name":"K.C. Collins","avatar":""},{"name":"Trevor Gretzky","avatar":""},{"name":"Chris Ramsay","avatar":""},{"name":"Genelle Williams","avatar":""},{"name":"Dylan Roberts","avatar":""},{"name":"Ali Johns","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324328);
