INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cruella-101-chu-cho-dom', 'Cruella: 101 Chú Chó Đốm', 'Cruella', 'https://phimimg.com/upload/vod/20231018-1/94921f87c7809e005737cdb8589ecd35.jpg', 'https://phimimg.com/upload/vod/20231018-1/cbb22e2f92c6c777e0b3dc9e7a8a8b58.jpg', '<p>Cruella là bản live action về phần tiền truyện của một trong những nhân vật phản diện mang tính biểu tượng, huyền thoại Cruella de Vil. “Cruella” lấy bối cảnh ở London những năm 1970 theo chân cô lao công thông minh &amp; sáng tạo Estella với quyết tâm làm nên tên tuổi từ những thiết kế của mình. Cô kết giao với 2 kẻ trộm luôn đánh giá cao tham vọng và sự nghịch ngợm của cô và họ cùng nhau gây dựng tên tuổi ở khu phố London. Một ngày nọ, sự nhạy bén về thời trang của Estella đã lọt vào mắt xanh của bà Nam tước von Hallman, một huyền thoại thời trang, người phụ nữ sang trọng nhưng không kém vẻ đáng sợ. Nhưng mối quan hệ của họ dẫn đến những sự kiện và khiến Estella bước vào con đường để trở thành một người đậm chất thời trang nhưng tàn ác và đầy lòng hận thù - Cruella.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Emma Stone","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Joel Fry","avatar":""},{"name":"Paul Walter Hauser","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Tipper Seifert-Cleveland","avatar":""},{"name":"Kirby Howell-Baptiste","avatar":""},{"name":"Emily Beecham","avatar":""},{"name":"John McCrea","avatar":""},{"name":"Kayvan Novak","avatar":""},{"name":"Jamie Demetriou","avatar":""},{"name":"Abraham Popoola","avatar":""},{"name":"Leo Bill","avatar":""},{"name":"Javone Prince","avatar":""},{"name":"Steve Edge","avatar":""},{"name":"Paul Chowdhry","avatar":""},{"name":"Ziggy Ga","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324328);
