INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-khi-chung-ta-tan-vo', 'Từ Khi Chúng Ta Tan Vỡ', 'After We Fell', 'https://phimimg.com/upload/vod/20231017-1/1ac31e023aea7f72a81530190ad7d7e0.jpg', 'https://phimimg.com/upload/vod/20231017-1/e35bb5e3fdb7d8fd26c7f5ebbd06d45d.jpg', '<p>Tessa và Hardin yêu nhau hơn bao giờ hết. Nhưng trước những bí mật còn giấu kín và lời hứa còn dang dở, chỉ tình yêu thôi thì chưa đủ để cùng xây đắp tương lai.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Josephine Langford","avatar":""},{"name":"Hero Fiennes Tiffin","avatar":""},{"name":"Louise Lombard","avatar":""},{"name":"Chance Perdomo","avatar":""},{"name":"Rob Estes","avatar":""},{"name":"Arielle Kebbel","avatar":""},{"name":"Stephen Moyer","avatar":""},{"name":"Mira Sorvino","avatar":""},{"name":"Frances Turner","avatar":""},{"name":"Kiana Madeira","avatar":""},{"name":"Carter Jenkins","avatar":""},{"name":"Atanas Srebrev","avatar":""},{"name":"Anton Kottas","avatar":""},{"name":"Velizar Nikolaev Biney","avatar":""},{"name":"Matthew Hall","avatar":""},{"name":"Angela Sari","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324328);
