INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly-cua-zack-snyder', 'Liên Minh Công Lý của Zack Snyder', 'Zack Snyder''s Justice League', 'https://phimimg.com/upload/vod/20231016-1/ffd14feb9753f59f0c5424947e686aaa.jpg', 'https://phimimg.com/upload/vod/20231016-1/bea0be39324578ada5fba0b9c11c6f7a.jpg', '<p>Justice League hay còn được biết đến với cái tên Liên Minh Công Lý, là tập hợp những siêu anh hùng mang trong mình sức mạnh phi thường để giải cứu thế giới khỏi những thế lực đen tối trong vũ trụ DC. Lần này, nhân loại phải đối mặt với tên ác quỷ vô cùng tàn độc – Steppenwolf. Hắn là một trong những tay sai đắc lực của Darksied – một ác nhân và cũng chính là kẻ thù lớn nhất của Liên Minh Công Lý. Steppenwolf đã phô trương năng lực siêu phàm của mình, gieo rắc nỗi sợ hãi và bóng tối tới xứ Themyscira – quê hương của Wonder Woman và loài người.</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Henry Cavill","avatar":""},{"name":"Gal Gadot","avatar":""},{"name":"Jason Momoa","avatar":""},{"name":"Ezra Miller","avatar":""},{"name":"Ray Fisher","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"Connie Nielsen","avatar":""},{"name":"Diane Lane","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Amber Heard","avatar":""},{"name":"Joe Morton","avatar":""},{"name":"Ray Porter","avatar":""},{"name":"Jesse Eisenberg","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Kiersey Clemons","avatar":""},{"name":"P","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b