INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-loi-thoat-2021', 'Không Lối Thoát', 'The Gateway', 'https://phimimg.com/upload/vod/20230926-1/6089a966d8c8436a27775b5fa89c87ca.jpg', 'https://phimimg.com/upload/vod/20230926-1/6317c406c3a1e5b8ce0ae8d4aed4be8f.jpg', '<p>Một nhân viên xã hội được giao nhiệm vụ chăm sóc con gái của một bà mẹ đơn thân đã can thiệp khi người cha trở về từ nhà tù và dụ họ vào cuộc đời tội phạm.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shea Whigham","avatar":""},{"name":"Olivia Munn","avatar":""},{"name":"Taryn Manning","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Bruce Dern","avatar":""},{"name":"Keith David","avatar":""},{"name":"Mark Boone Junior","avatar":""},{"name":"Zach Avery","avatar":""},{"name":"Jessica Medina","avatar":""},{"name":"Alexander Wraith","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324328);
