INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-dong-ca-sau-dien', 'Biển Động Cá Sấu Điên', 'Crazy Tsunami', 'https://phimimg.com/upload/vod/20231014-1/c043cd462410a666d149fe12b72436af.jpg', 'https://phimimg.com/upload/vod/20231014-1/aff9335ec373ba53c72fb212a4a24569.jpg', '<p>Một cơn sóng thần bất ngờ ập tới, khiến cho Khương Bồng và con gái của mình Khương Tiểu Hồ bị mắc kẹt ở Khu phố Tàu Đông Nam Á. Hai bố con Khương Bồng và người dân Khu phố Tàu đã đồng tâm hiệp lực, ra sức chiến đấu với con quái vật khổng lồ do sóng thần mang tới. Trải qua sinh tử mới phát hiện ra rằng, hoá ra mọi thứ không phải do thiên tai mà là do con người tạo ra…</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Rong Fei","avatar":""},{"name":"Wang Yinglu","avatar":""},{"name":"Canti Lau","avatar":""},{"name":"Daniella Wang","avatar":""},{"name":"Huo Weimin","avatar":""},{"name":"Tong Xi","avatar":""},{"name":"Li Junru","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324328);
