INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-ma-hanh-trinh-vuong-gia', 'Đồ Ma: Hành Trình Vương Giả', 'The Sword', 'https://phimimg.com/upload/vod/20231014-1/82a893c6154104356c83a535b5d80b04.jpg', 'https://phimimg.com/upload/vod/20231014-1/d7fb0ef045f9d472d87e05c49581c815.jpg', '<p>Thời thượng cổ, nhằm tiêu diệt loài người, ma vương Arsa lợi dụng lòng tham và dục vọng của con người mà xây dựng một quân đoàn vong linh. Kỵ sĩ trưởng Thánh Điện phương Tây dẫn đầu Đoàn Kỵ sĩ sang đại lục Đông Nguyên tìm Thánh Kiếm trợ giúp. Nhưng mà Arsa đã bắt đầu tấn công đại lục Đông Nguyên. Vì vậy, Đoàn Kỵ sĩ Thánh Điện phương Tây đoàn kết các môn phái phương Đông như Tuần Dạ Sơn Cung cùng chống lại Arsa.</p>', 'Full', 1, 'single', 'completed', 18, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Xianshi","avatar":""},{"name":"Robert Gilabert Cuenca","avatar":""},{"name":"Anita Yoo","avatar":""},{"name":"Ren Qing''an","avatar":""},{"name":"Long Yangyang","avatar":""},{"name":"Hu Dongqing","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324328);
