INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-thu-than-tham-quy-mon-thap-tam-cham', 'Cao Thủ Thần Thám: Quỷ Môn Thập Tam Châm', 'The Needle of GuiMen', 'https://phimimg.com/upload/vod/20231014-1/f5c51fffd67411187f891ab96ea5bd2c.jpg', 'https://phimimg.com/upload/vod/20231014-1/6f6d87365224fd3816e025123981ab96.jpg', '<p>Theo truyền thuyết, &quot;Mười ba kim của cổng ma&quot;, một cây kim bí mật của y học cổ xưa đã được truyền lại hàng ngàn năm, có thể cứu người khỏi cổng ma, và cái ác có thể điều khiển con người như những con rối, mọi người đều muốn nó, nhưng nó đã ẩn giấu trong thế giới từ lâu và không tìm thấy dấu vết nào. Khi thế giới dần lãng quên &quot;Mười ba cây kim của Cổng ma&quot;, một vụ án giết người hàng loạt kỳ quái và khó lường liên quan đến &quot;Mười ba cây kim của Cổng ma&quot; và giáo phái bí mật của Cổng ma ẩn đằng sau nó. Vụ án ngày càng trở nên khó hiểu. Cùng lúc đó, Song Jingzhi, người bị trục xuất khỏi địa ngục vì tội giết người thầy của mình, không hiểu sao lại trở thành kẻ sát nhân trong vụ giết người hàng loạt trong khi đang điều tra vụ án. Đối mặt với đủ loại bằng chứng không thể chối cãi, Song Jingzhi và kẻ sát nhân đứng sau hậu trường đã phát động một cuộc chiến công bằng liên quan đến sự sống, cái chết và sự cứu chuộc. Vào thời khắc mấu chốt, một bà lão dị dạng đã thú nhận mọi tội ác, bọ ngựa rình rập con ve sầu và chim vàng anh đi theo, cả đúng và sai, hung thủ thực sự là ai?</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Gang","avatar":""},{"name":"Bai Chengjun","avatar":""},{"name":"Zhang Xinlei","avatar":""},{"name":"Yang Zhenning","avatar":""},{"name":"Chen Xianyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324328);
