INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-dia-minh-hai', 'Cấm Địa Minh Hải', 'The Forbidden Depths', 'https://phimimg.com/upload/vod/20231013-1/9d194897361f3116eeb2993e51939998.jpg', 'https://phimimg.com/upload/vod/20231013-1/509c608391eda27ef348c8be40535c97.jpg', '<p>Biện Hải Sinh, một con đứa bị bỏ rơi mà trưởng thành trong nhà Đản, quyết tâm làm “Hải Lao Tử”. Chàng ngẫu nhiên kiếm được mảnh giáp trụ vàng khi lặn biển kiếm báu vật, lại bị giặc biển bắt. Sau đó, chàng ngẫu nhiên gặp gỡ An Tố, cháu gái của ông chủ đảo Linh Dược thần bí. Hai người cùng trốn đến đảo Linh Dược và vượt qua khó khăn chồng chắt, tìm được thành trì văn minh thần bí dưới đáy biển sâu. Chàng được sức lực mạnh mẽ, phát hiện được thân phận thật của mình.</p>', 'Full', 1, 'single', 'completed', 14, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tim Huang","avatar":""},{"name":"Michael Tong","avatar":""},{"name":"Huang Ziqi","avatar":""},{"name":"Huang Xiaoge","avatar":""},{"name":"Minowa Yasufumi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324328);
