INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-so-biet-noi', 'Con Số Biết Nói', 'The Unexpected Man', 'https://phimimg.com/upload/vod/20231013-1/896e3471db1ffa68413d924ed8058d84.jpg', 'https://phimimg.com/upload/vod/20231013-1/3fdd43cbc1da9aa5f7dd111516a303e8.jpg', '<p>Trần Chính, một thiên tài toán học đi làm tại Cục Thống kê, tình cờ giúp cảnh sát giải mã bí ẩn đằng sau chân dung của tội phạm ăn cướp Đinh Cường mà nổi danh khắp chốn, được người dân thành phố tôn là “Hiệp sĩ chữ số”. Nhưng tiệc vui chóng tàn, Đinh Nhã Băng, con gái của Đinh Cường, trở thành hacker “Yêu Hoa” để báo thù cho bố. Cô ấy xâm phạm vào máy tính của đội cảnh sát hình sự, tuyên bố mình đã bố trí quả bom ẩn hình. Vụ này khiến người ta vô cùng kinh hoàng. Lúc bước ngoặt hiểm nghèo, nhằm cứu vớt người dân thành phố, Trần Chính được lệnh giải mã 3 phương trình “Yêu Hoa” để lại. Nhưng trong quá trình điều tra, Trần Chính phát hiện thì ra “Yêu Hoa” là anh trai mình Trần Mặc chứ là Đinh Nhã Băng. Hai anh em trở mặt, việc cũ được nhắc lại. Hai người đối địch về lợi ích, khi đối mặt với tình yêu, tình thân và chính nghĩa, họ sẽ lựa chọn như thế nào?</p>', 'Full', 1, 'single', 'completed', 13, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Kelong","avatar":""},{"name":"Liao Weiwei","avatar":""},{"name":"Han Zhao","avatar":""},{"name":"Qi Zhi","avatar":""},{"name":"Laixi","avatar":""},{"name":"Guo Jinjie","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324328);
