INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-dao-mau-hong-va-dai-mien-vuong-1', 'Anh Đào Màu Hồng và Đại Miên Vương 1', 'Why Women Cheat Part 1', 'null', 'https://phimimg.com/upload/vod/20231013-1/46117945b2e586f0bb4162e3421825db.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Nam chính là vua của một quốc đảo nhỏ ở Đông Nam Á vào thế kỷ trước. Anh bị nữ chính tổn thương sâu sắc. Nhân vật nữ chính có răng hổ và cười siêu quyến rũ. Khi nữ chính biến mất, nam chính thích ngủ vì không muốn bỏ lỡ nữ chính. Nó đã từng ngọt ngào như thế nào, bây giờ nó tàn bạo như thế nào. Nhân vật nam chính cuối cùng đã kết hôn với nhân vật nữ chính, và anh ta quyết định tra tấn nhân vật nữ chính trông dễ thương và đáng ghét này. Tuy nhiên, nam chính yêu nhân vật nữ chính quá nhiều trong lòng nên cuộc sống thường ngày của anh và cô luôn trong sự hiểu lầm, ngọt ngào. Những lời không thể nói ra là chân thành nhất, và những tấm lòng không thể nhìn thấy là trung thành. Mỗi khi nữ chính thể hiện tình yêu, nam chính sẽ bị hiểu lầm nhiều hơn. Luôn có hai tình huống này trong cuộc sống, một là nỗi đau của việc không nói chuyện và hai là nụ cười của việc không nói. Nhưng hai người yêu nhau không ngốc, tất cả những lời có thể nói đều có thể truyền tải tình yêu nóng bỏng, làm sao có thể không lay động lẫn nhau. Cuối cùng, hạt giống của tình yêu đích thực đã nảy nở trong trái tim của hai người, và chủ nghĩa khổ dâm đã bị vượt qua bởi tiếng cười ngọt ngào.</span></p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Deng Kai","avatar":""},{"name":"Yao Xiaoxiao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324328);
