INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-long-thap-bat-chuong', 'Giáng Long Thập Bát Chưởng', 'The Dragon Tamer', 'null', 'https://phimimg.com/upload/vod/20231013-1/1dcee58b637527c9a1b21be413f16810.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Cậu bé sa mạc Quách Tĩnh cùng sư phụ Giang Nam đi xuống Giang Nam Lục Quái để tu luyện, và gặp Hoàng Tráng Tráng , con gái của Hoàng Diệu Thạch, và hai người đã tham gia vào một âm mưu tranh giành &quot;Cửu Âm Chân Kinh&quot;. Quách Tĩnh đã nhiều lần gặp phải nguy hiểm, nhưng may mắn là Hồng Khí Công, lão nhím và các võ sư khác đã chỉ ra, kỹ năng võ thuật của hắn tiến bộ từng bước. Tây độc Âu Dương Phong đổ bộ lên đảo Hoa Đào để nuôi nấng gia đình, và gây ra một cơn bão đẫm máu trên sông hồ để chiếm lấy kinh điển chân chính. Quách Tĩnh gánh vác trọng trách nặng nề và bắt tay vào một trận chiến quyết định trên đỉnh núi Hoa.</span></p>', 'Full', 1, 'single', 'completed', 23, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Geng Yeting","avatar":""},{"name":"Lin Yanrou","avatar":""},{"name":"To Dewei","avatar":""},{"name":"Kwan Lijie","avatar":""},{"name":"Zhu Jianran","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Giang Trung Vĩ","avatar":""},{"name":"Luo Yingjun","avatar":""},{"name":"Lâm Tử Công","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324328);
