INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-thuat-su', 'Ảo Thuật Sư', 'The Oriental Illusionist', 'null', 'https://phimimg.com/upload/vod/20231013-1/8d9dc32798bdc852dad1fc71a9bd684f.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">&quot;The Juggler&quot; kể câu chuyện về cuộc đấu tay đôi tung hứng bắt đầu từ những năm đầu của Trung Hoa Dân Quốc, hai trường phái lừa trong và ngoài Sơn Hải Quan, vì một &quot;Cuốn sách về vận may trên trời&quot; được đồn đại là có thể thay đổi cuộc sống của một người trên bầu trời. Bộ phim dựa trên các thủ thuật cổ điển phương Đông, với Yin Tianzhao đóng vai Jiang Beihai trong Yangmen và Zhang Chunzhong đóng vai Huang Xianshou trong Yin Gate, và cả hai đã dàn dựng một cuộc đấu lừa cao cấp vì sự cạnh tranh cho &quot;The Book of Heavenly Fortune&quot;.</span></p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yin Tianzhao","avatar":""},{"name":"Zhang Chunzhong","avatar":""},{"name":"Xu Shaoqiang","avatar":""},{"name":"Fu He Anqi","avatar":""},{"name":"Chen Yeling","avatar":""},{"name":"Ngô Xuân Nghi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324328);
