INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-sat-tieu-thuyet-gia', 'Ám Sát Tiểu Thuyết Gia', 'A Writer''s Odyssey', 'https://phimimg.com/upload/vod/20231012-1/1982ee2b38308fed8bb09474e3d31ad6.jpg', 'https://phimimg.com/upload/vod/20231012-1/86c31e3594d25918049d8389aca56a33.jpg', '<p>Mong muốn tìm con gái mất tích của mình, một người cha đồng ý giúp đỡ một người phụ nữ bí ẩn ám sát một tiểu thuyết gia. Đồng thời, người anh hùng trẻ tuổi trong vũ trụ thay thế của cuốn sách cũng đã đưa kế hoạch trả thù của mình vào hành động, và hành động của anh ta bắt đầu ảnh hưởng đến thế giới thực.</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lei Jiayin","avatar":""},{"name":"Yang Mi","avatar":""},{"name":"Dong Zijian","avatar":""},{"name":"Wang Shengdi","avatar":""},{"name":"Yu Hewei","avatar":""},{"name":"Guo Jingfei","avatar":""},{"name":"Yang Yi","avatar":""},{"name":"Tong Liya","avatar":""},{"name":"Liu Tianzuo","avatar":""},{"name":"Li Binghui","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324328);
