INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-tuyet-am-chien-thien-co', 'Báo Tuyết : Ám Chiến Thiên Cơ', 'Snow Leopard Secret War', 'https://phimimg.com/upload/vod/20231012-1/9b7d9211e3007c9a29f6220b78c9d018.jpg', 'https://phimimg.com/upload/vod/20231012-1/b47268aaa15ca34fd0b8df8760c594f7.jpg', '<p>Snow Leopard Secret War lấy bối cảnh năm 1943, khi cuộc chiến ở Thái Bình Dương vẫn đang diễn ra khiến quân đội Nhật Bản bị ảnh hưởng và phải chuyển sang chế độ phòng thủ. Tuy nhiên, họ đang thực hiện một kế hoạch tác chiến khác, một cuộc tấn công quy mô lớn bắt đầu, họ cũng giao nhiệm vụ cho các đặc vụ nằm trong khu vực và vận chuyển vũ khí trái phép. . Lúc này, thủ lĩnh của Đội độc lập Hổ Đầu Sơn Bát Lộ Lưu Viên đã tìm ra bọn gián điệp và ngăn chặn thành công một cuộc chiến sắp xảy ra.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Pan Taiming","avatar":""},{"name":"Yue Feng","avatar":""},{"name":"Zhengyong Zhang","avatar":""},{"name":"Xuesong Lin","avatar":""},{"name":"Xu Jingwen","avatar":""},{"name":"Clara Lee","avatar":""},{"name":"Yu Zhen","avatar":""},{"name":"Lu Fangsheng","avatar":""},{"name":"Hongbiao Bai","avatar":""},{"name":"Chuangao Hou","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324328);
