INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-nguyet-vi-uong', 'Bát Nguyệt Vị Ương', 'August Never Ends', 'https://phimimg.com/upload/vod/20231012-1/022b4be89f2ad65dda1f73919e7b7421.jpg', 'https://phimimg.com/upload/vod/20231012-1/8aad090828be3a3295b936dd53721acd.jpg', '<p>Một câu chuyện xoay quanh hai người bạn có tính cách rất khác nhau - Vị Ương nổi loạn và chính trực và &#39;Công chúa&#39; lý tưởng Qiao. Khi Tiểu Kiều gặp Vị Ương, cả hai dễ dàng trở thành bạn thân. Tuy nhiên, vị hôn thê của Xiao Qiao, Chao Yan, không thể tự chủ được khi yêu Weiyang sâu sắc, điều này đã phá hỏng câu chuyện tình cổ tích của Xiao Qiao. Khi cả ba đang vướng vào một thế giới phức tạp, Vị Ương đưa ra một quyết định đáng ngạc nhiên.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhong Chuxi","avatar":""},{"name":"Luo Jin","avatar":""},{"name":"Tan Songyun","avatar":""},{"name":"Tian Yu","avatar":""},{"name":"Chen Minghao","avatar":""},{"name":"Wan Ziqing","avatar":""},{"name":"Guo Mucheng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324328);
