INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-ho-menh', 'Thiên Thần Hộ Mệnh', 'The Guardian', 'https://phimimg.com/upload/vod/20231012-1/5e0f485839d9269c0a7778ffd5874d75.jpg', 'https://phimimg.com/upload/vod/20231012-1/5085cb28f6f53b892d42200db0001ea0.jpg', '<p>Cái chết của một cô ca sĩ nổi tiếng dẫn đến sự thành công của một cô ca sĩ trẻ khác. Câu chuyện này có liên quan như thế nào đến sự giúp đỡ của một &quot;thiên thần hộ mệnh&quot;?</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Trúc Anh","avatar":""},{"name":"Amee","avatar":""},{"name":"Salim","avatar":""},{"name":"Samuel An","avatar":""},{"name":"Trọng Trinh","avatar":""},{"name":"Thanh Thủy","avatar":""},{"name":"Nguyen Anh Dung","avatar":""},{"name":"Thu Vu","avatar":""},{"name":"Tran Le Nguyen","avatar":""},{"name":"Thuy Kieu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324328);
