INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-tieu-dac-di-4', 'Bảo Tiêu Đặc Dị 4', 'Special Bodyguard 4', 'null', 'https://phimimg.com/upload/vod/20231011-1/c102b0265ab5b22aba5b5c6f083e2cbd.jpg', '<p>Câu chuyện diễn ra vào cuối thời nhà Minh và đầu thời nhà Thanh, quân Thanh cùng quân chống Thanh và quân Minh của Zheng Chenggong đã tham gia vào một cuộc giằng co ở miền nam Phúc Kiến. giặc ngoại xâm, cướp biển không rõ quốc tịch và tàn quân tóc đỏ cấu kết với nhau ở bờ biển phía Đông Nam để lợi dụng tình thế hoặc cướp bóc trên biển, tàu buôn có thể quấy rối người dân trên bờ, biển chằng chịt, khiến kế sinh nhai của người dân khó. Phim tập trung vào câu chuyện về tướng quân Lan Li (1647-1720) thời Khang Hy (truyện về cuộc đời ông được chọn trong “Bản thảo lịch sử nhà Thanh”), tuổi thiếu niên đã cần cù, rèn luyện tài năng, dũng cảm chiến đấu chống lại bọn cướp biển, và gia nhập quân đội để dẹp tan chư hầu, và sau này trở thành một vị tướng nổi tiếng trong lịch sử nhà Thanh. , và đã giành được những lời khen ngợi như &quot;Thần chiến trên biển và trên đất liền&quot;, &quot;Công lao đầu tiên trên bục&quot;, &quot;Trụ đồng có lập được nhiều thành tích trên biển, chiến lược quân sự sắt đá từ lâu đã nổi tiếng”, “Dũng cảm và giản dị, bất khuất” và những câu chuyện hay khác đã đặt nền móng vững chắc cho cuộc sống.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Yiming","avatar":""},{"name":"Ai Jiani","avatar":""},{"name":"Waise Lee","avatar":""},{"name":"Zhuang Qiqian","avatar":""},{"name":"Dev Raturi","avatar":""},{"name":"Wang Yiqin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324328);
