INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-e', 'Bóng Ðè', 'The Ancestral', 'https://phimimg.com/upload/vod/20231011-1/b1241615c1dfaa5044a10a78b0d50bd4.jpg', 'https://phimimg.com/upload/vod/20231011-1/fcf3835abcb934402f5ad9e64573a0a4.jpg', '<p>Sau khi trải qua bi kịch gia đình, người đàn ông góa vợ tên Thành chuyển hai cô con gái về ngôi nhà tổ tiên hàng thế kỷ. Cả hai cô con gái đều rơi vào tình trạng tê liệt khi ngủ và nỗi kinh hoàng về đêm. Cha của họ tìm kiếm sự giúp đỡ của một nhà tâm lý học địa phương, nhưng những bí mật và tầm nhìn rùng rợn cuối cùng đã chứng minh rằng tất cả không phải như những gì diễn ra trong ngôi nhà cũ của gia đình.</p>', 'Full', 1, 'single', 'completed', 15, 2021, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Lam Thanh My","avatar":""},{"name":"Quang Tuấn","avatar":""},{"name":"Mai Cat Vi","avatar":""},{"name":"Dieu Nhi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324328);
