INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dien-toi', 'Điên Tối', 'Dien Toi', 'https://phimimg.com/upload/vod/20231011-1/9635eb2a91c757667f7e4225f3efeb63.jpg', 'https://phimimg.com/upload/vod/20231011-1/0302396ac4c8f6ebe2cc66e2db0d5924.jpg', '<p>Tìm mọi cách để tài trợ cho bộ phim đầu tiên của mình, vị đạo diễn nọ nhờ một biên kịch tài năng giúp đỡ – chẳng ngờ rằng vụ hợp tác sẽ đưa họ vào cuộc hành trình bí ẩn.</p>', 'Full', 1, 'single', 'completed', 17, 2021, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Lien Binh Phat","avatar":""},{"name":"Yu Dương","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324329);
