INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dien-toi', 'Điên Tối', 'Dien Toi', 'điên tối dien toi lien binh phat yu dương ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-hanh-dong-chong-dua-xe', 'Sự Hành Động Chống Đua Xe', 'Anti Racing Action', 'https://phimimg.com/upload/vod/20231010-1/f63e6cde17b9ee19969c5b83781c02be.jpg', 'https://phimimg.com/upload/vod/20231010-1/e32d2854516e912a323542a63c47f72f.jpg', '<p>Hong Kong luôn được mệnh danh là thành phố an toàn nhất châu Á, thời gian gần đây, những băng nhóm mê tốc độ cố tình gây rối thường xuyên xuất hiện ở Hong Kong. Cảnh sát luôn có thái độ không khoan nhượng đối với đua xe tốc độ, một nhóm tội phạm còn được gọi là “băng nhóm tốc độ”, vì vậy, cảnh sát đã đặc biệt huy động tinh hoa của Bộ Giao thông vận tải thành lập “đội chống chạy quá tốc độ” để thực hiện. đối xử đặc biệt đối với băng đảng chạy quá tốc độ. Đội chống chạy quá tốc độ do Cheng Zhifei làm đội trưởng bắt đầu điều tra. Một tổ chức đua xe chợ đen do Jiang Xiaohai đứng đầu nổi lên, tổ chức này muốn bí mật tổ chức một sự kiện đua xe chợ đen ở Hồng Kông để thu lợi bất hợp pháp. Trong quá trình cảnh sát điều tra, mối hận thù giữa Cheng Zhifei và Jiang Xiaohai mười lăm năm trước cũng lộ ra, cả hai đều bị tra tấn tâm lý suốt mười lăm năm vì mối hận thù này và không thể buông bỏ. Giang Tiểu Hải vì thế dấn thân vào con đường đua chợ đen. Cheng Zhifei và Jiang Xiaohai đều phải đối mặt với những lựa chọn lớn trong cuộc sống, số phận, công lý và tội ác.</p>', 'Full', 1, 'single', 'completed', 12, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Michael Tse","avatar":""},{"name":"Hugo Ng","avatar":""},{"name":"Stanley Cheung King-Seun","avatar":""},{"name":"Jason Chu","avatar":""},{"name":"Jill Tang Le","avatar":""},{"name":"Danny Lee Sau-Yin","avatar":""},{"name":"Aki Lee","avatar":""},{"name":"Joan Lee Wing-Yee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324329);
