INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-cao-cap-mot', 'Tố Cáo Cấp Một', 'The Attorney', 'https://phimimg.com/upload/vod/20231010-1/7d5b0b7576f2c7e5544e0d18ff6e5148.jpg', 'https://phimimg.com/upload/vod/20231010-1/57e5bfa3afc70a34bbd4230178923211.jpg', '<p>Quách Gia Nghi, con gái của nhà giàu nhất trong thành phố, bị chết bất đắc trong văn phòng riêng một cách ly kỳ. Vì ở hiện trường trong quãng thời gian vụ án mạng xảy ra, Lí Dật Phong, cháu của người bán rau quả Châu Ma, bị tố cáo với tội cưỡng hiếp và giết người. Luật sư Lôi Hữu Huy và Hà Học Minh cùng truy xét sự thật, nắm được bằng chứng dần. Nhưng nhân chứng bị giết, bằng chứng bị tiêu hủy. Làm thế nào mới ràng buộc các thế lực quyền quý đen tối như Tằng Chí Uy bằng luật pháp được? Lôi Hữu Huy đành phải phản kích trong cuộc thẩm vấn cuối cùng trên tòa!</p>', 'Full', 1, 'single', 'completed', 17, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Alex Fong","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Carlos Chan","avatar":""},{"name":"Pau Hei-Ching","avatar":""},{"name":"Kelly Chen Jia-li","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Justin Cheung","avatar":""},{"name":"Jeana Ho Pui-Yu","avatar":""},{"name":"Bernice Liu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324329);
