INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-song', 'Mộ Sông', 'Tomb of the River', 'https://phimimg.com/upload/vod/20231002-1/769bc7ce586eb23bcb574d81eb95b010.jpg', 'https://phimimg.com/upload/vod/20231002-1/2ea28810c19f65ae8626c52073527d1f.jpg', '<p>Ông trùm tập đoàn tội phạm lớn nhất tại Gangneung, Hàn Quốc lập kế hoạch xây dựng khu nghỉ dưỡng lớn nhất Châu Á. Gil-Suk(Yu Oh-seong thủ vai) là tay sai đáng tin cậy và hết sức trung thành của ông ấy, sống một cuộc sống thoải mái, mỗi ngày thi hành nhiệm vụ của ông ấy. Min Seok(Jang Hyuk thủ vai) là trùm xã hội đen trẻ đến từ Seoul, mang trí tuệ cũng như dã tâm, quyết định chuyển nghề sang ngành du dịch nghỉ dưỡng và xây dựng thế lực của mình. Min Seok giành được khu nghỉ dưỡng bằng các thủ đoạn bạo lực, lừa dối mà khiến tập đoàn của Gil-Suk rơi vào nguy hiểm. Bởi vậy, Gil-Suk quyết tâm trả thù...</p>', 'Full', 1, 'single', 'completed', 17, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Hyuk","avatar":""},{"name":"Yu Oh-seong","avatar":""},{"name":"Han Seon-hwa","avatar":""},{"name":"Kim Joon-bae","avatar":""},{"name":"Oh Dae-hwan","avatar":""},{"name":"Jo Hyun-sik","avatar":""},{"name":"Lee Chae-young","avatar":""},{"name":"Shin Seung-hwan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324329);
