INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoc-nhin-toi', 'Ngước Nhìn Tôi', 'Eyes On Me', 'https://phimimg.com/upload/vod/20231002-1/281591236271ee44969ee33b9cfb2268.jpg', 'https://phimimg.com/upload/vod/20231002-1/6a952f5436b0a731fbf71f2c4dec9574.jpg', '<p>Bộ phim kể về câu chuyện của một cô gái trẻ tên là Tôi, người đã trải 
qua nhiều khó khăn và thử thách trong cuộc sống. Tuy nhiên, với sự kiên 
nhẫn và nỗ lực không ngừng, cô đã vượt qua những trở ngại và trở thành 
một người phụ nữ mạnh mẽ và độc lập. &quot;Ngước Nhìn Tôi&quot; không chỉ là một 
bộ phim giải trí, mà còn là một câu chuyện cảm động về sự tự tin và sự 
khám phá bản thân. Với diễn xuất tuyệt vời của dàn diễn viên, cùng với 
kịch bản hấp dẫn và hình ảnh đẹp mắt, bộ phim hứa hẹn sẽ mang lại những 
trải nghiệm tuyệt vời cho khán giả.</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"IZONE","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324329);
