INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-kha-thi', 'Nhiệm Vụ Khả Thi', 'Mission : Possible', 'https://phimimg.com/upload/vod/20231002-1/9606fb63ed95b5497e73530391399088.jpg', 'https://phimimg.com/upload/vod/20231002-1/4b4c14ab0a70269c045c2485bf162806.jpg', '<p>Bộ phim kể về Yoo Da Hee, một mật vụ hàng đầu của bộ An Ninh của Trung Quốc. Khi bộ phận của cô nhận được thông tin về một vụ buôn lậu vũ khí ở Hàn Quốc, cô đã được cử đi tóm những kẻ buôn lậu. Một phần kế hoạch liên quan tới mối quan hệ của một đặc nhiệm Hàn Quốc.&nbsp; Nhưng do một trường hợp nhầm lẫn danh tính, cô bất ngờ được cho là đã gặp gỡ với Woo Soo Han, một người có tính cách hài hước và là một thám tử tư thiếu kinh nghiệm, lo những vụ nhỏ nhặt gồm cả việc tìm kiếm con chó bị mất tích. Yoo Da Hee không biết rằng Woo Soo Han không phải là đặc vụ mà cô được cử đến để làm việc cùng và đưa anh ta vào kế hoạch của mình.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Young-kwang","avatar":""},{"name":"Lee Sun-bin","avatar":""},{"name":"Oh Dae-hwan","avatar":""},{"name":"Seo Hyun-chul","avatar":""},{"name":"Choi Byung-mo","avatar":""},{"name":"Kim Tae-hun","avatar":""},{"name":"Julien Kang","avatar":""},{"name":"Lee Ji-hun","avatar":""},{"name":"Park Jin-su","avatar":""},{"name":"Shin Hye-jeong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324329);
