INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('banh-xe-thoi-gian-phan-1', 'Bánh Xe Thời Gian: Phần 1', 'The Wheel of Time: Season 1', 'https://phimimg.com/upload/vod/20231001-1/1e72d7744f46381b20c014f1711fb90e.jpg', 'https://phimimg.com/upload/vod/20231001-1/c9a7d1e347126756b3e8e36a0f8e2697.jpg', '<p>Phim xoay quanh câu chuyện về cô gái Moiraine là thành viên của Aes Sedai là một tổ chức bóng tối có tầm ảnh hưởng vô cùng lớn và điều đặc biệt là những người trong tổ chức toàn là phụ nữ. Giờ đây Moiraine đã cùng với 5 người đặc biệt gồm đàn ông và phụ nữ bắt đầu đuộc hành trình đi khắp thế giới đầy nguy hiểm. Không những thế Moiraine cho rằng những người này là các chiến binh vô cùng mạnh mẽ trong lời tiên chi và bọn họ chính là hy vọng duy nhất để giải cứu nhân loại trong tương lai.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 26, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rosamund Pike","avatar":""},{"name":"Daniel Henney","avatar":""},{"name":"Josha Stradowski","avatar":""},{"name":"Zoë Robins","avatar":""},{"name":"Madeleine Madden","avatar":""},{"name":"Marcus Rutherford","avatar":""},{"name":"Dónal Finn","avatar":""},{"name":"Ceara Coveney","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324329);
