INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tu-thu-3', 'Nhà Tù Thứ 3', 'Asurado', 'https://phimimg.com/upload/vod/20230930-1/56ab207eb3aa232b56d6eb50190f7fcd.jpg', 'https://phimimg.com/upload/vod/20230930-1/638065b173ffc5511300f8f02d843024.jpg', '<p>Nhà tù Thứ Ba tuyệt vọng tụ tập nhiều tên tội phạm hung hãn tàn 
bạo, bất ngờ trùm Lee Tae-sik khiến các tội phạm lúng ta lúng túng lại 
vào tù. Kỷ nguyên quyền lực mới sắp mở đầu. Chẳng bao lâu nữa, cai ngục 
mới Jo Pyeong-ho nhậm chức và ông lộ ra tâm địa độc ác, lạnh lùng...</p>', 'Full', 1, 'single', 'completed', 17, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Seol-gu","avatar":""},{"name":"Jang Gwang","avatar":""},{"name":"Lee Won-jong","avatar":""},{"name":"Lee Doll-hyung","avatar":""},{"name":"Jung Mi-nam","avatar":""},{"name":"Hwang In-mu","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324329);
