INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-mon', 'Cửu Môn', 'Nine Gates', 'https://phimimg.com/upload/vod/20230930-1/07d8b13bed041a67a99bd662688d50ae.jpg', 'https://phimimg.com/upload/vod/20230930-1/cc3c4bd40dc9184f372d5b0a50407e64.jpg', '<p>Viên quan Trịnh Nham chết một cách kỳ lạ, Lục Tầm phát hiện ra vũ nữ Phong Như Nguyệt và người anh trai Phong Không Không có điểm đáng ngờ, Phong Không Không lại đột ngột mất tích. Căn cứ theo đầu mối tìm được, Lục Tầm cùng Đại Sơn và Như Nguyệt đi tới thành Hắc Trạch. Bọn họ vô tình cứu được Tiểu Đường, không ngờ bị Tiểu Đường uy hiếp ngược lại. Thì ra Phong Không Không cũng là bị Tiểu Đường bắt giữ, mục đích chính là làm nổ tung kinh thành. Lục Tầm vạch trần mưu kế sát hại Trịnh Nham của Phong Như Nguyệt và Phong Không Không. Như Nguyệt thẳng thắn cho biết cha mình bị Trịnh Nham hãm hại mà chết.</p>', 'Full', 1, 'single', 'completed', 23, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Yuexin","avatar":""},{"name":"Zhang Zixuan","avatar":""},{"name":"Wang Xudong","avatar":""},{"name":"Gu Zhiyun","avatar":""},{"name":"Jianchang Tan","avatar":""},{"name":"Liu Zhanling","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324329);
