INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('te-cong-hang-long-la-han', 'Tế Công: Hàng Long La Hán', 'The Mad Monk', 'https://phimimg.com/upload/vod/20230929-1/b8caa3ddb91db164e66e986fca399328.jpg', 'https://phimimg.com/upload/vod/20230929-1/e434862caa499212d80c5c460e02f5c0.jpg', '<p>Hắc Long gian ác hút cảm xúc của con người để làm thức ăn, gây nên một trận dịch bệnh cho con người, đồng thời gửi yêu quái cây Bồ Quỳ đến để bắt đối thủ Lý Tâm Viễn. Trong quá trình truy sát yêu quái cây Bồ Quỳ bị sự lương thiện và chính trực của Lý Tâm Viễn làm cho cảm động và dần lung lay. Sau cùng ác long đã được tích đủ năng lượng đã đích thân đến nhân gian để giết Lý Tâm Viễn. Vì để bảo vệ Lý Tâm Viễn mà Bồ Quỳ bị đốt cháy thành tro. Lý Tâm Viễn vì quá đau lòng nên đã nổ ra một trận đại chiến với ác long.</p>', 'Full', 1, 'single', 'completed', 23, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chan Ho-Man","avatar":""},{"name":"Zhang Chuxuan","avatar":""},{"name":"Zheng Junhao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324329);
