INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-lac-ta-thuat', 'Con Lắc Tà Thuật', 'The Hypnosis', 'https://phimimg.com/upload/vod/20230930-1/e3be338ede8d207c99a126b9ec06ce84.jpg', 'https://phimimg.com/upload/vod/20230930-1/4899fe33e3930c9bcf3f1d40ce2b46c4.jpg', '<p>Đô Hiền (Lý Đại Vệ đóng vai), một sinh viên khoa Tiếng Anh có cuộc
 sống phong phú, ngẫu nhiên hứng thú nghiên cứu thôi miên do sinh viên 
chuyển trường Chấn Hạo (Kim Nam Ưu đóng vai). Được giáo sư thầy Thôi 
(Tôn Bính Hiếu đóng vai) giúp đỡ, Đô Hiền thử điều trị bằng thôi miên. 
Nhưng sau đó anh ấy bắt đầu xem được ảnh ảo trí nhớ khiến mình nghi ngờ,
 các bạn của anh ấy cũng lần lượt bị ảnh ảo ảnh hưởng mà gặp phải việc 
kỳ lạ. Rốt cuộc mục đích của giáo sư thầy Thôi ẩn náu đằng sau thôi miên
 là gì?</p>', 'Full', 1, 'single', 'completed', 18, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Da-wit","avatar":""},{"name":"Shin Ji Won","avatar":""},{"name":"Kim Do-hoon","avatar":""},{"name":"Nam Min-woo","avatar":""},{"name":"Kim Nam-woo","avatar":""},{"name":"Son Byung-ho","avatar":""},{"name":"Seo Yi-sook","avatar":""},{"name":"Moon Ho-jin","avatar":""},{"name":"Yim Seung-min","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324329);
