INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-xa-tinh-kiep', 'Bạch Xà: Tình Kiếp', 'The White Snake : A Love Affair', 'https://phimimg.com/upload/vod/20230928-1/c2ebbb81643df5da423c5bb295fad1c4.jpg', 'https://phimimg.com/upload/vod/20230928-1/1d4dfc7feea2c8c597bddaccf59f2550.jpg', '<p><span class="key"></span>Nữ xà yêu Bạch Tố Tố mang trong mình linh
 huyết – thứ máu thần có thể làm tăng sức mạnh của pháp sư trừ yêu lên 
gấp bội. Bị dã tâm và tham vọng làm mờ mắt, những pháp sư trừ yêu liền 
truy bắt cô để làm lợi cho mình. Hứa Tiên – chàng pháp sư xuất thân từ 
một gia tộc trừ yêu thất thế, đã bắt được Bạch Tố Tố. Chàng vốn định bán
 nàng đi để thu về cả một gia tài, dùng số của cải đó để khôi phục danh 
dự và tiếng tăm cho gia đình. Nhưng trớ trêu thay, Hứa Tiên lại phải 
lòng Bạch Tố Tố. Giữa tình yêu và gia tộc, Hứa Tiên sẽ chọn gì?</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Hua","avatar":""},{"name":"Wen Yi Fan","avatar":""},{"name":"Yu Li","avatar":""},{"name":"Wang Zhigang","avatar":""},{"name":"Xu Shao-Hang","avatar":""},{"name":"Liu Chun","avatar":""},{"name":"Xu Daning","avatar":""},{"name":"Xu Ning","avatar":""},{"name":"Yang Ming","avatar":""},{"name":"Wu Hao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324329);
