INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-chung-ran-dien', 'Biến Chủng Rắn Điên', 'Nowhere To Hide', 'https://phimimg.com/upload/vod/20230928-1/8d04466e3c58d93bc72773fd755b61e4.jpg', 'https://phimimg.com/upload/vod/20230928-1/b34e77409a66c156aa0b714ea0de8be9.jpg', '<p>Một nhóm thực khách tham lam vốn định thưởng thức một bữa đại tiệc
 dân dã, nhưng rắn mối khổng lồ đột biến đã phát nát lồng sắt và trở 
thành một kẻ săn mồi đích thực. Sau bao khó khăn, cuối cùng chuyên gia 
bắt chuột A Phát cũng đã chế ngự được rắn mối khổng lồ…</p><p><br/></p><p><br/></p>', 'Full', 1, 'single', 'completed', 18, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jason Zhang","avatar":""},{"name":"Pang Yong","avatar":""},{"name":"Rayna Wang","avatar":""},{"name":"Peng Haiyang","avatar":""},{"name":"Li Zhenyu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324329);
