INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-chien-giang-ho', 'Tái Chiến Giang Hồ', 'Back on the Society', 'https://phimimg.com/upload/vod/20230928-1/9babe85446e395b144744fd2aec1216a.jpg', 'https://phimimg.com/upload/vod/20230928-1/c4a48a5a14d7c0d981459f5751430e31.jpg', '<p>Nhiều năm trước, Chương Sơn Hà vào tù bởi đánh lộn với người khác, người vợ chết sớm vì sinh khó mà để lại con gái Chương Tiểu Nặc sống trong viện trẻ mồ côi. Sau khi ra tù, Chương Sơn Hà quyết định tìm con gái về. Hôm nọ, Chương Sơn Hà trợ giúp bạn bè mà bị trả thù, khiến con gái bị bắt cóc tại Đông Nam Á. Bởi vậy, Chương Sơn Hà một mình sang Đông Nam Á cứu con gái trong khi bị kẻ thù truy sát, cuối cùng anh ấy quyết chiến với kẻ thù.</p>', 'Full', 1, 'single', 'completed', 18, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jordan Chan","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Jason Chu","avatar":""},{"name":"Sheng Yijie","avatar":""},{"name":"Liu Weizhou","avatar":""},{"name":"Chang Li-Wei","avatar":""},{"name":"Naomen Eerdeni","avatar":""},{"name":"Yu Keran","avatar":""},{"name":"Wang Xingchen","avatar":""},{"name":"Wang Han","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324329);
