INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoi-dong-dia-cau', 'Khởi Động Địa Cầu', 'Restart the Earth', 'https://phimimg.com/upload/vod/20230928-1/33dd36df00676f692fe999bf501d9581.jpg', 'https://phimimg.com/upload/vod/20230928-1/e7ab03b2639e6af4c470f0039dccc9d8.jpg', '<p>Con người vì muốn chống lại hiện tượng sa mạc hoá, đã nghiên cứu 
ra thuốc thúc đẩy quá trình sinh sản của tế bào thực vật. Điều này vô 
tình giải phóng hệ thống kích thích phản ứng của thực vật, đánh thức cảm
 xúc của chúng, khiến thực vật sinh sôi nảy nở nhanh chóng. Chúng nhấn 
chìm thành phố và tấn công con người, một đợt thuỷ triều xanh trên toàn 
cầu sẽ khiến nền văn minh nhân loại biến mất. Các nước hợp tác cử ra một
 đội hành động chấp hành việc bố trí các loại thuốc ức chế hoạt động của
 thực vật. Đội Trung Quốc và những người sống sót gặp nhau trong nguy 
hiểm, vượt qua đống đổ nát của thành phố, cùng nhau hoàn thành nhiệm vụ 
khó khăn.</p><p><br/></p><p><br/></p>', 'Full', 1, 'single', 'completed', 18, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Shengming","avatar":""},{"name":"Mi Luo","avatar":""},{"name":"Michelle Ye","avatar":""},{"name":"Yu Rongguang","avatar":""},{"name":"Li Ning","avatar":""},{"name":"Zhang Mingcan","avatar":""},{"name":"Li Ruoxi","avatar":""},{"name":"Huang Kai-Lun","avatar":""},{"name":"Ye Xinyu","avatar":""},{"name":"Tang Xin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324329);
