INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-han-truong-khien', 'Đại Hán Trương Khiên', 'The legend of Zhang Qian', 'null', 'https://phimimg.com/upload/vod/20230928-1/8dcb45be8637ef0a59e0d7cf05b0374b.jpg', '<p>Trương Khiên phụng lệnh Hán Vũ Đế về phía Tây đi sứ đến Đại Nguyệt Chi bị Hung Nô chặn đánh giữa đường, giam lỏng ở vương đình Hung Nô đã mười năm. Cuộc sống vốn đang yên tĩnh lại bị biên phòng Đại tướng quân Lan Ký của Hung Nô phá vỡ. Lan Ký thực hiện chính sách bạo ngược với tù binh người Hán, Trương Khiên nhẫn nhục chịu đựng để bảo vệ tính mạng đồng tộc. Nhưng kế hoạch chạy trốn đã lập ra lâu nay lại vì người này đến mà phải gác lại, làm thế nào để đưa người Hán chạy trốn trở thành vấn đề lớn nhất…</p>', 'Full', 1, 'single', 'completed', 21, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Ninh Giang","avatar":""},{"name":"Trần Hi","avatar":""},{"name":"Thạch Triệu Kì","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324329);
