INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-long-bi-thuoc', 'Cửu Long Bí Thược', 'Age of the Legend', 'https://phimimg.com/upload/vod/20230926-1/b19f524a0b5f1df7cc092441e8c6fd40.jpg', 'https://phimimg.com/upload/vod/20230926-1/0e55a0d212aff45eab5e1b8866c31414.jpg', '<p>Thời Kỳ Anh Hùng Cửu Long Bí Thược, Age Of The Legend (2021) Cuối thời nhà Thanh, các nước mạnh nước ngoài nhìn chằm chằm vào Trung Quốc, không ngừng xâm lược. Triều đình nhà Thanh không có sức chống lại bởi bế quan tỏa cảng lâu năm. Giặc xâm lược Anh, Nhật Bản cấu kết với nhau, hòng xâm chiếm thành Quảng Châu. Mấy võ giả nhận lệnh trước nguy cơ. Vượt qua nhiều khó khăn nguy hiểm, họ đánh bại Ninja Nhật Bản và dùng công sự phòng ngự bí mật đánh lui chiến hạm nước Anh, cứu vớt thành Quảng Châu.</p>', 'Full', 1, 'single', 'completed', 16, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Xiang","avatar":""},{"name":"Wen Dongjun","avatar":""},{"name":"Liu Kai","avatar":""},{"name":"Wu Yijia","avatar":""},{"name":"Li Junmo","avatar":""},{"name":"Li Zhen''an","avatar":""},{"name":"Shuangli Zhang","avatar":""},{"name":"Wu Xinzun","avatar":""},{"name":"Chuanying Li","avatar":""},{"name":"Cui Zhenzhen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324329);
