INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('amina', 'Amina', 'Amina', 'https://phimimg.com/upload/vod/20230926-1/e4ece06d34a2b77f01f343a00d711162.jpg', 'https://phimimg.com/upload/vod/20230926-1/017fe03d3cccf59fc411fcc39e5c5150.jpg', '<p>Ở Zazzau thế kỷ 16, nay là Zaria, Nigeria, Amina phải sử dụng các kỹ năng và chiến thuật quân sự của mình để bảo vệ vương quốc của gia đình mình. Dựa trên một câu chuyện có thật.</p>', 'Full', 1, 'single', 'completed', 18, 2021, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Lucy Ameh","avatar":""},{"name":"Ali Nuhu","avatar":""},{"name":"Clarion Chukwurah-Abiola","avatar":""},{"name":"Chris Gbakann","avatar":""},{"name":"Ibrahim Mijinyawa","avatar":""},{"name":"Ummi Mohammed","avatar":""},{"name":"Madaki Asabe","avatar":""},{"name":"Yakubu Mohammed","avatar":""},{"name":"Ogunjiofor Jenevieve","avatar":""},{"name":"Blessing Godwin Ogaga","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324329);
