INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-dong-tay-du-hong-hai-nhi', 'Ma Đồng Tây Du Hồng Hài Nhi', 'Awakened Demon', 'https://phimimg.com/upload/vod/20230926-1/04bb33c65be20aa9d6f56b7b549e9142.jpg', 'https://phimimg.com/upload/vod/20230926-1/e3129c3c4f9aa642351674e61a07666e.jpg', '<p>Nó kể về câu chuyện của Hong Hai Er, người đã được Bồ Tát Quán Âm nhận nuôi làm Đứa trẻ may mắn. Anh tuân theo mệnh lệnh của người cố vấn để luyện tập trong Bài kiểm tra số phận. Hong Hai Er muốn trở thành anh hùng nhưng bị người khác loại trừ do di sản lai giữa bất tử và ác quỷ. Đối mặt với những hiểu lầm và thảm họa sắp xảy ra, Hong Hai Er kiên quyết từ bỏ những định kiến và sự hung hãn vào thời điểm quan trọng và dũng cảm chiến đấu với cái ác cùng Ne Zha và Miss Dragon. Cuối cùng, anh đã đánh bại được tà ác và được mọi người công nhận.</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Geng Yeting","avatar":""},{"name":"Wa Er","avatar":""},{"name":"Duan Xingyu","avatar":""},{"name":"Nan Sikai","avatar":""},{"name":"Zhuang Qiqian","avatar":""},{"name":"Fang Jiayi","avatar":""},{"name":"Hei Zi","avatar":""},{"name":"He Xie","avatar":""},{"name":"Juan Zi","avatar":""},{"name":"Lou Mingsen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324329);
