INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-chi-mat-do-quai-la', 'Địch Nhân Kiệt Chi Mắt Đỏ Quái Lạ', 'Detective Dee and The Red Eye', 'https://phimimg.com/upload/vod/20230926-1/9361ff944fe5dbf564ab03eb9cd7f517.jpg', 'https://phimimg.com/upload/vod/20230926-1/56059d1102140c191d56f8da6854f01d.jpg', '<p>Trong thời kỳ Võ Tắc Thiên, Địch Nhân Kiệt xét xử vụ án “quái vật mắt đỏ” làm loạn và diệt trừ thân vương Võ Mẫn Chi hòng cướp ngôi, bảo vệ được an ninh quốc gia.</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Minghan","avatar":""},{"name":"Fan Meng","avatar":""},{"name":"Chao Lichuan","avatar":""},{"name":"He Qiwei","avatar":""},{"name":"Wang Guanpeng","avatar":""},{"name":"Zhao Zuo","avatar":""},{"name":"Hou Tianfang","avatar":""},{"name":"Zhang Zijun","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324329);
