INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-danh-cong-ly-2', 'Nhân Danh Công Lý 2', 'Drishyam 2', 'https://phimimg.com/upload/vod/20230926-1/96bc5416eb8775535c3b0468e811fbfc.jpg', 'https://phimimg.com/upload/vod/20230926-1/911ff1b48eb75d3f2ba8a34036340814.jpg', '<p>Drishyam 2 là bộ phim kinh dị chính kịch ngôn ngữ Malayalam được phát hành năm 2021 của Ấn Độ do Jeethu Joseph đồng đạo diễn và viết kịch bản, Antony Perumbavoor chịu trách nhiệm sản xuất thông qua công ty Aashirvad Cinemas. Đây cũng là phần phim tiếp theo của bộ phim Drishyam được phát hành năm 2013. Phim có sự tham gia của các diễn viên Mohanlal , Meena , Ansiba Hassan và Esther Anil quay lại từ phần trước. Phim lấy bối cảnh 5 năm sau sự kiện phần 1.</p>', 'Full', 1, 'single', 'completed', 23, 2021, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Mohanlal","avatar":""},{"name":"Meena","avatar":""},{"name":"Murali Gopy","avatar":""},{"name":"Asha Sarath","avatar":""},{"name":"Siddique","avatar":""},{"name":"Anjali Aneesh Upasana","avatar":""},{"name":"Esther Anil","avatar":""},{"name":"Ansiba Hassan","avatar":""},{"name":"Saikumar","avatar":""},{"name":"Ganesh Kumar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324329);
