INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('encanto-vung-dat-than-ky', 'Encanto: Vùng Đất Thần Kỳ', 'Encanto', 'https://phimimg.com/upload/vod/20230926-1/ee0e178855770946d1c2eae6eb525f48.jpg', 'https://phimimg.com/upload/vod/20230926-1/7d2f758616d2ef7ec1081ca9994f1b26.jpg', '<p>Câu chuyện về một gia đình phi thường, nhà Madrigals, sống ẩn mình trong vùng núi Colombia, trong một ngôi nhà ma thuật, trong một thị trấn sôi động, ở một nơi kỳ diệu, quyến rũ được gọi là Encanto. Phép thuật của Encanto đã ban phước cho mọi đứa trẻ trong gia đình món quà độc nhất vô nhị từ siêu sức mạnh đến sức mạnh chữa lành — mọi đứa trẻ, trừ Mirabel. Nhưng khi cô phát hiện ra rằng phép thuật xung quanh Encanto đang gặp nguy hiểm, Mirabel quyết định rằng cô, người nhà Madrigal bình thường duy nhất, có thể là hy vọng cuối cùng của gia đình cô.</p>', 'Full', 1, 'hoathinh', 'completed', 22, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stephanie Beatriz","avatar":""},{"name":"María Cecilia Botero","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Diane Guerrero","avatar":""},{"name":"Jessica Darrow","avatar":""},{"name":"Carolina Gaitán","avatar":""},{"name":"Angie Cepeda","avatar":""},{"name":"Ravi Cabot-Conyers","avatar":""},{"name":"Mauro Castillo","avatar":""},{"name":"Rhenzy Feliz","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324329);
