INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-rap-richie', 'Vua Rap Richie', 'Forever Rich', 'https://phimimg.com/upload/vod/20230926-1/ce49ee318477316fdc4c8307b9c136ad.jpg', 'https://phimimg.com/upload/vod/20230926-1/fa3ef43ba34e3fe07a12c54cae8f17a1.jpg', '<p>Đây là câu chuyện về Richie và hành trình trở thành nghệ sĩ rap vĩ đại nhất Hà Lan. Một buổi tối, anh ta bị một nhóm thanh thiếu niên cướp bóc một cách thô bạo và đánh mất tài sản quý giá nhất của mình: một chiếc đồng hồ đắt tiền. Khi những hình ảnh về vụ cướp nhục nhã được lan truyền rộng rãi, danh tiếng khó khăn mới có được của Richie bị tổn hại.</p>', 'Full', 1, 'single', 'completed', 17, 2021, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Jonas Smulders","avatar":""},{"name":"Daniël Kolf","avatar":""},{"name":"Sinem Kavus","avatar":""},{"name":"Hadewych Minis","avatar":""},{"name":"Yootha Wong-Loi-Sing","avatar":""},{"name":"Mustafa Duygulu","avatar":""},{"name":"Yassin Dardour","avatar":""},{"name":"Sergio Krijnen","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324329);
