INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-toc-gucci', 'Gia Tộc Gucci', 'House of Gucci', 'https://phimimg.com/upload/vod/20230926-1/2493ec0abaa0dcf4ae848b9026843202.jpg', 'https://phimimg.com/upload/vod/20230926-1/7966ae351410590e7cdd770d1973d494.jpg', '<p>Gia Tộc Gucci (House of Gucci) được lấy cảm hứng từ câu chuyện có gây sốc có thật về đế chế gia đình đằng sau nhà mốt Gucci của Ý. Trải qua ba thập kỷ yêu, phản bội, suy đồi, trả thù và cuối cùng là giết người, chúng ta thấy được ý nghĩa đằng sau cái tên, giá trị của danh tiếng và mức độ một gia đình có thể nắm quyền kiểm soát.</p>', 'Full', 1, 'single', 'completed', 21, 2021, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Lady Gaga","avatar":""},{"name":"Adam Driver","avatar":""},{"name":"Al Pacino","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Jack Huston","avatar":""},{"name":"Salma Hayek Pinault","avatar":""},{"name":"Alexia Murray","avatar":""},{"name":"Vincent Riotta","avatar":""},{"name":"Gaetano Bruno","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324329);
