INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sao-hoa-di-bien', 'Sao Hoả Dị Biến', 'Mutation on Mars', 'https://phimimg.com/upload/vod/20230926-1/70271a3de44b2408cbd5e64b69ac33a6.jpg', 'https://phimimg.com/upload/vod/20230926-1/6287c1d95fc0a66619a4aa5dbf7a1d90.jpg', '<p>Trong tương lai gần, nguồn tài nguyên của Trái đất đang dần khan hiếm. Để nối tiếp hy vọng sống sót cho thế hệ con cháu, các nhà khoa học hàng đầu từ nhiều quốc gia đã đưa một số loài động vật và thực vật lên Sao Hỏa để nghiên cứu, với hy vọng cải thiện môi trường Sao Hỏa thông qua khoa học và công nghệ tiên tiến để phù hợp với con người. nơi ở.</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Shi Liang","avatar":""},{"name":"Ren Zhong","avatar":""},{"name":"Suo Xiaokun","avatar":""},{"name":"Liu Xinqi","avatar":""},{"name":"Xin Zuoyu","avatar":""},{"name":"Fan Ziqi","avatar":""},{"name":"Li Xinzhe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324329);
