INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giua-hai-mau-da', 'Giữa Hai Màu Da', 'Passing', 'https://phimimg.com/upload/vod/20230926-1/a12c92bf08e14ba25da81b4df5d3ee44.jpg', 'https://phimimg.com/upload/vod/20230926-1/be94457658ae32adb0b038976158b0d3.jpg', '<p>Vào những năm 1920 ở thành phố New York, một phụ nữ da đen thấy thế giới của mình bị đảo lộn khi cuộc sống của cô gắn liền với một người bạn thời thơ ấu đã qua đời với tư cách là người da trắng.</p>', 'Full', 1, 'single', 'completed', 21, 2021, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Tessa Thompson","avatar":""},{"name":"Ruth Negga","avatar":""},{"name":"André Holland","avatar":""},{"name":"Alexander Skarsgård","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"Gbenga Akinnagbe","avatar":""},{"name":"Antoinette Crowe-Legacy","avatar":""},{"name":"Justus Davis Graham","avatar":""},{"name":"Ethan Barrett","avatar":""},{"name":"Ashley Ware Jenkins","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324329);
