INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-dau-tro-ve', 'Chị Dâu Trở Về', 'The Return of the Sister-in-Law', 'https://phimimg.com/upload/vod/20230926-1/831490cb3ff09151eed8de8e9298d524.jpg', 'https://phimimg.com/upload/vod/20230926-1/6c42dce6318b5a340e0ff1583e9f6480.jpg', '<p>Nhằm báo thù cho người thân, người thiếu nữ ngây thơ Thanh Trừng trải qua sự huấn luyện mà trở thành sát thủ lạnh lùng. Sau giết người nhiều lần, nàng quyết định xóa bỏ hận thù, trải qua nửa đời cuối yên ổn trong trại An Lạc. Tại đấy nàng quen biết với A Bang và kết hôn với chàng. Khi Thanh Trừng giả vờ không biết võ thuật, sinh sống bình thường. Bất ngờ giang hồ lại gió giục mây vần. Để bảo vệ sự an ninh của trại An Lạc, Thanh Trừng dũng cảm đứng ra, trở thành người bảo vệ của trại An Lạc.</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Raquel Xu","avatar":""},{"name":"Terence Yin","avatar":""},{"name":"Andrew Lin","avatar":""},{"name":"Jane Wu","avatar":""},{"name":"Zhong Xinghui","avatar":""},{"name":"Xu Zhangchao","avatar":""},{"name":"Xu Shaowu","avatar":""},{"name":"Li Yuehui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324329);
