INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-cong-o-phan-lan', 'Tấn Công Ở Phần Lan', 'Attack on Finland', 'https://phimimg.com/upload/vod/20230925-1/bcf7edf42fffd62c4fea9411ccb10b82.jpg', 'https://phimimg.com/upload/vod/20230925-1/7e7afe213b1d38c3b4ec51cbcc989753.jpg', '<p>Tiệc chiêu đãi Ngày Độc lập của Phần Lan bị gián đoạn một cách thô bạo khi dinh tổng thống bị tấn công và lãnh đạo nhà nước bị bắt làm con tin. Max Tanner của Cảnh sát An ninh được bổ nhiệm làm người đàm phán trong cuộc khủng hoảng con tin, diễn ra như một phần trong kế hoạch lớn hơn nhằm phá hoại an ninh châu Âu.</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Jasper Pääkkönen","avatar":""},{"name":"Nanna Blondell","avatar":""},{"name":"Sverrir Gudnason","avatar":""},{"name":"Cathy Belton","avatar":""},{"name":"Nika Savolainen","avatar":""},{"name":"Pertti Sveholm","avatar":""},{"name":"Juhan Ulfsak","avatar":""},{"name":"Zijad Gračić","avatar":""},{"name":"Miodrag Stojanović","avatar":""},{"name":"Dragomir Mrsic","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324329);
