INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tan-cong-o-phan-lan', 'Tấn Công Ở Phần Lan', 'Attack on Finland', 'tấn công ở phần lan attack on finland jasper pääkkönen nanna blondell sverrir gudnason cathy belton nika savolainen pertti sveholm juhan ulfsak zijad gračić miodrag stojanović dragomir mrsic ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-sut-tu-than', 'Hố Sụt Tử Thần', 'Sinkhole', 'https://phimimg.com/upload/vod/20230925-1/0dfa7917f2e7db050a50c93e9d87d8d6.jpg', 'https://phimimg.com/upload/vod/20230925-1/f2f7e4334828328b83a408f447793a36.jpg', '<p>Sau 11 năm làm việc chăm chỉ và tích cóp tiết kiệm, Park Dong-won đã mua được một căn hộ cho riêng mình và chuyển đến ở cùng vợ và con trai. Park Dong-won tổ chức một bữa tiệc tân gia mời bạn bè, đồng nghiệp của mình đến. Sáng hôm sau, cả căn nhà bỗng mất nước đột ngột, Dong-won vừa lên sân thượng để hòi người hàng xóm thì mặt đất rung chuyển, một hố sụt khổng lồ hình thành và nuốt chửng toàn bộ tòa nhà, rơi xuống dưới mặt đất 500 mét. Dưới hố sâu, Park Dong-won, người hàng xóm Jeong Man-soo và những vị khách tân gia phải tìm cách để bảo vệ bản thân và tự cứu chính mình trước khi cảnh sát tìm ra biện pháp giải cứu họ. Đúng lúc đó, trời lại bắt đầu mưa, nước dội xuống liên tục đe dọa nhấm chìm cái hố, căn nhà và dìm chết những người xấu xố ở dưới đó. Họ phải tìm ra giải pháp trước khi hết thời gian để hít thở.</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Cha Seung-won","avatar":""},{"name":"Kim Sung-kyun","avatar":""},{"name":"Lee Kwang-soo","avatar":""},{"name":"Kwon So-hyun","avatar":""},{"name":"Kim Hye-jun","avatar":""},{"name":"Kim Jae-hwa","avatar":""},{"name":"Nam Da-reum","avatar":""},{"name":"Jung Young-sook","avatar":""},{"name":"Lee Hak-ju","avatar":""},{"name":"Han Hye-rin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324329);
