INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-mat-chuoc', 'Đêm Mạt Chược', 'Mahjong Nights', 'https://phimimg.com/upload/vod/20230925-1/5446a00b03717066d5bc7f2b775298f9.jpg', 'https://phimimg.com/upload/vod/20230925-1/b493511b6fb2d909401ac106f69e644f.jpg', '<p>Alexa chứng kiến một đêm mạt chược đơn giản trở nên đẫm máu khi tất cả bí mật đen tối của người chơi bị phát hiện - bao gồm cả mối tình bất chính của Alexa với cha dượng.</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Angeli Khang","avatar":""},{"name":"Sean de Guzman","avatar":""},{"name":"Mickey Ferriols","avatar":""},{"name":"Jay Manalo","avatar":""},{"name":"Arnell Ignacio","avatar":""},{"name":"Jamilla Obispo","avatar":""},{"name":"Liz Alindogan","avatar":""},{"name":"Jonathan Tadioan","avatar":""},{"name":"Oakley","avatar":""},{"name":"Kimmy Maclang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324329);
