INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-vang', 'Cậu Vàng', 'The Old Man''s Dog', 'https://phimimg.com/upload/vod/20230925-1/f385a3c4d70dd8cfd1633372871223d9.jpg', 'https://phimimg.com/upload/vod/20230925-1/b62bfcaec05c9783c116200fcc6f05be.jpg', '<p>“Cậu Vàng” được lấy cảm hứng từ những tác phẩm văn học của nhà văn Nam Cao, phim điện ảnh đầu tiên của Việt Nam lấy một chú chó làm diễn viên chính và là đường dây, điểm sáng xuyên suốt. “Cậu Vàng” do chính cố NSND Bùi Cường – người được biết đến với vai diễn Chí Phèo trong bộ phim kinh điển “Làng Vũ Đại ngày ấy”- chắp bút, nhằm tưởng nhớ, tri ân cố nhà văn Nam Cao. Và dự án điện ảnh “Cậu Vàng” cũng chính là tâm nguyện lúc cuối đời của cố NSND Bùi Cường</p>', 'Full', 1, 'single', 'completed', 23, 2021, 'Vietsub', 'HD', 'Việt Nam', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324329);
