INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-phai-giet-toi', 'Anh Phải Giết Tôi', 'You Have To Kill Me', 'https://phimimg.com/upload/vod/20230922-1/7fb18650917dc0badcf13111992b5f7f.jpg', 'https://phimimg.com/upload/vod/20230922-1/6478a9de30e59bdf09f083cad4d4158b.jpg', '<p>Sĩ quan cảnh sát Chou chuẩn bị cầu hôn bạn gái Chen. Sau đó anh ta nhận được một bản báo cáo vụ án giết người và theo nó đến vùng núi. Đáng buồn thay, người đã khuất chính là bạn gái anh Chen. Bị tàn phá nặng nề, anh ta cố gắng hết sức và bắt giữ kẻ sát nhân Li. Tuy nhiên, từ lời thú nhận của Li, Chou biết rằng Chen đã tự nguyện để Li giết cô. Tại sao Li và Chen lại cùng nhau thực hiện hành trình giết người? Hay là Chen tự sát?</p>', 'Full', 1, 'single', 'completed', 23, 2021, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Rexen Cheng Jen-Shuo","avatar":""},{"name":"Janel Tsai","avatar":""},{"name":"Simon Hsueh","avatar":""},{"name":"Yin Chao-Te","avatar":""},{"name":"Chao Yi-lan","avatar":""},{"name":"Kass Tsai","avatar":""},{"name":"Bo-Hao Ruan","avatar":""},{"name":"Chen Yi-Chun","avatar":""},{"name":"Nan-Chung Cheng","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324329);
