INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nan-diet-chung-srebrenica', 'Nạn Diệt Chủng Srebrenica', 'Quo Vadis, Aida?', 'https://phimimg.com/upload/vod/20230922-1/725ed766a55d55f9940097c27b0e97a8.jpg', 'https://phimimg.com/upload/vod/20230922-1/13deaef2e75a185439a8e64ac83f5210.jpg', '<p>Bosnia, tháng 7 năm 1995. Aida là thông dịch viên cho Liên Hiệp Quốc tại thị trấn nhỏ Srebrenica. Khi quân đội Serbia tiếp quản thị trấn, gia đình cô nằm trong số hàng nghìn công dân đang tìm nơi trú ẩn trong trại Liên Hợp Quốc. Là người trong cuộc trong cuộc đàm phán, Aida có quyền truy cập vào thông tin quan trọng mà cô ấy cần giải thích. Điều gì sẽ xảy ra với gia đình và mọi người của cô ấy - giải cứu hay cái chết? Cô ấy nên thực hiện hành động nào?</p>', 'Full', 1, 'single', 'completed', 19, 2021, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Jasna Đuričić","avatar":""},{"name":"Izudin Bajrović","avatar":""},{"name":"Boris Ler","avatar":""},{"name":"Dino Bajrović","avatar":""},{"name":"Johan Heldenbergh","avatar":""},{"name":"Raymond Thiry","avatar":""},{"name":"Boris Isaković","avatar":""},{"name":"Emir Hadžihafizbegović","avatar":""},{"name":"Reinout Bussemaker","avatar":""},{"name":"Teun Luijkx","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324329);
