INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nan-diet-chung-srebrenica', 'Nạn Diệt Chủng Srebrenica', 'Quo Vadis, Aida?', 'nạn diệt chủng srebrenica quo vadis, aida? jasna đuričić izudin bajrović boris ler dino bajrović johan heldenbergh raymond thiry boris isaković emir hadžihafizbegović reinout bussemaker teun luijkx ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dot-kich-dinh-menh', 'Cuộc Đột Kích Định Mệnh', 'The Ambush', 'https://phimimg.com/upload/vod/20230921-1/2fa8d9b790d8a70cf507c2ddd8058957.jpg', 'https://phimimg.com/upload/vod/20230921-1/c559f96a67a7c8108f69c1a84d630969.jpg', '<p>Đó là mùa đông năm 2018, nam nữ quân nhân UAE được triển khai để hỗ trợ. Tại Căn cứ Mocha, tinh thần lên cao khi ba người lính Tiểu vương quốc chờ đợi chuyến trở về nhà sắp xảy ra. Khi đang thực hiện chuyến tuần tra định kỳ cuối cùng, ba người lính Ali, Bilal và Hindasi bị phục kích bởi các chiến binh được trang bị vũ khí hạng nặng trên đường đi của họ, qua một hẻm núi hẹp. Bị mắc kẹt, bị thương và nằm ngoài phạm vi liên lạc, ba người lính nhận ra mức độ nghiêm trọng của tình hình của họ. Họ đang cạn kiệt lựa chọn, đạn dược - và thời gian. Trở lại căn cứ, chỉ huy của họ nhận được tin báo và nhận ra rằng cuộc tấn công vào đội tuần tra của quân đội UAE đã được tính toán trước. Một nhiệm vụ giải cứu nhanh chóng được thực hiện, nhưng liệu sự hỗ trợ trên không và trên bộ có đến được với những người đàn ông kịp thời và liệu họ có sống sót?</p>', 'Full', 1, 'single', 'completed', 20, 2021, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Marwan Abdullah","avatar":""},{"name":"Khalifa Al Jassem","avatar":""},{"name":"Mohammed Ahmed","avatar":""},{"name":"Abdulla Saeed Bin Haider","avatar":""},{"name":"Saeed Alharsh","avatar":""},{"name":"Hassan Yousuf Alblooshi","avatar":""},{"name":"Khalifa Albahri","avatar":""},{"name":"Ghanim Nasser","avatar":""},{"name":"Mansoor Alfeeli","avatar":""},{"name":"Ibrahim Almusharaakh","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324329);
