INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-alpinist-2021', 'The Alpinist', 'The Alpinist', 'https://phimimg.com/upload/vod/20230919-1/f2c0ae714ce4089a9524ea9e30a5d569.jpg', 'https://phimimg.com/upload/vod/20230919-1/a8fb31383378af591fe1555ec5415475.jpg', '<p>Marc-André Leclerc, nhà leo núi một mình táo bạo nhưng ẩn dật, trở thành người hùng bất đắc dĩ khi leo lên những độ cao băng giá, đáng sợ nhất trên thế giới.</p>', 'Full', 1, 'single', 'completed', 26, 2021, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Marc-André Leclerc","avatar":""},{"name":"Brette Harrington","avatar":""},{"name":"Alex Honnold","avatar":""},{"name":"Reinhold Messner","avatar":""},{"name":"Ueli Steck","avatar":""},{"name":"Dean Potter","avatar":""},{"name":"Derek Hersey","avatar":""},{"name":"Jon Walsh","avatar":""},{"name":"Tommy Caldwell","avatar":""},{"name":"Austin Siadak","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324329);
