INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-cua-em', 'Em Là Của Em', 'I Am Mine', 'https://phimimg.com/upload/vod/20230919-1/619a9e50cea2740eeb8f995350c73e27.jpg', 'https://phimimg.com/upload/vod/20230919-1/26817034338d96bcf5589d0c9d3485f7.jpg', '<p><span style="font-family: ">Chuyện phim “Em” Là Của Em xoay quanh Hoàng (Ngô Kiến Huy) - một chàng trai đã 30 tuổi nhưng vẫn chưa đi đến được trạm cuối của con đường tình yêu. Phải lòng một cô gái hơn tuổi từ tận năm cấp 3, Hoàng đã phải trải qua nhiều gian nan trắc trở để “cầm cưa” chị đẹp nhưng đều liên tiếp bị chị người thương từ chối. Lúc này, Thanh (Khả Như) trở thành người “cứu rỗi” tình yêu cho Hoàng khi lập ra cho anh hẳn một kế hoạch cưa đổ crush cực kỳ hoàn hảo. Liệu rằng với kế hoạch ấy, anh chàng có thành công thu phục trái tim của người đẹp giấu mặt?</span></p>', 'Full', 1, 'single', 'completed', 24, 2021, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Ngô Kiến Huy","avatar":""},{"name":"Maya","avatar":""},{"name":"Khả Như","avatar":""},{"name":"Hứa Vĩ Văn","avatar":""},{"name":"Hoàng Phi","avatar":""},{"name":"Đại Nghĩa","avatar":""},{"name":"Lê Giang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324329);
