INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-cat', 'Hành Tinh Cát', 'Dune', 'https://phimimg.com/upload/vod/20230918-1/8e17e494da77ad4161d26c078c9253ce.jpg', 'https://phimimg.com/upload/vod/20230918-1/c457097a5a6ed3c81eabd9901b542bbb.jpg', '<p><span style="font-family: ">Là chuyến hành trình sử thi đầy cảm xúc của Paul Atreides – một chàng thanh niên trẻ tài ba xuất chúng được sinh ra với một sứ mệnh vĩ đại vượt ngoài tầm hiểu biết của chính bản thân anh. Paul đã phải du hành tới hành tinh nguy hiểm nhất trong Vũ trụ để đảm bảo được tương lai cho gia đình cũng như những người dân của anh ấy. Khi các thế lực tàn độc bắt đầu lao vào cuộc xung đột nhằm tranh giành độc quyền nguồn tài nguyên có giá trị nhất hành tinh – thứ nhiên liệu quý giá có khả năng kích hoạt những tiềm năng lớn nhất của nhân loại – chỉ những người chiến thắng được nỗi sợ hãi của mình mới có thể sống sót.</span></p>', 'Full', 1, 'single', 'completed', 24, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Timothée Chalamet","avatar":""},{"name":"Rebecca Ferguson","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Sharon Duncan-Brewster","avatar":""},{"name":"Stephen McKinley Henderson","avatar":""},{"name":"Zendaya","avatar":""},{"name":"Chang Chen","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324329);
