INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoat-khoi-mogadishu', 'Thoát Khỏi Mogadishu', 'Escape from Mogadishu', 'https://phimimg.com/upload/vod/20230917-1/adc90a8a61d6befe1f4926e5363f9e81.jpg', 'https://phimimg.com/upload/vod/20230917-1/027e56e939fb33b654c00d7beeaed3cc.jpg', '<p><span style="font-family: ">Các nhà ngoại giao đối thủ từ Triều Tiên và Hàn Quốc bị mắc kẹt khi cuộc nội chiến bùng nổ ở Mogadishu, Somalia. Không có sự trợ giúp từ chính phủ nào, mục tiêu duy nhất của họ để sống sót đòi hỏi phải đoàn kết với những kẻ thù cay đắng để trốn thoát.</span></p>', 'Full', 1, 'single', 'completed', 26, 2021, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Yoon-seok","avatar":""},{"name":"Zo In-sung","avatar":""},{"name":"Heo Joon-ho","avatar":""},{"name":"Kim So-jin","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Koo Kyo-hwan","avatar":""},{"name":"Kim Jae-hwa","avatar":""},{"name":"Park Kyung-hye","avatar":""},{"name":"Park Myung-shin","avatar":""},{"name":"Han Chul-woo","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324329);
