INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-ben-kia-khung-cua', 'Bí Mật Bên Kia Khung Cửa', 'The Woman in the Window', 'https://phimimg.com/upload/vod/20230917-1/754e874fd57db460e61ffcbab7f2640f.jpg', 'https://phimimg.com/upload/vod/20230917-1/b040b6c5a194dfb3c137304eb62d889d.jpg', '<p><span style="font-family: ">Luôn ở trong nhà vì chứng sợ khoảng trống, một nhà tâm lý học trở nên ám ảnh với những người hàng xóm mới – và phá giải một vụ án tàn bạo mà cô chứng kiến qua cửa sổ.</span></p>', 'Full', 1, 'single', 'completed', 26, 2021, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amy Adams","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Fred Hechinger","avatar":""},{"name":"Wyatt Russell","avatar":""},{"name":"Brian Tyree Henry","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Jeanine Serralles","avatar":""},{"name":"Mariah Bozeman","avatar":""},{"name":"Julianne Moore","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324329);
