INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bi-mat-ben-kia-khung-cua', 'Bí Mật Bên Kia Khung Cửa', 'The Woman in the Window', 'bí mật bên kia khung cửa the woman in the window amy adams gary oldman anthony mackie fred hechinger wyatt russell brian tyree henry jennifer jason leigh jeanine serralles mariah bozeman julianne moore ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-trung-cat', 'Côn Trùng Cát', 'Devil In Dune', 'https://phimimg.com/upload/vod/20230916-1/78c5e48586026808a7a069b00f5e8ff6.jpg', 'https://phimimg.com/upload/vod/20230916-1/aaa52302e66c8a57404351f89c9df85c.jpg', '<p>Côn Trùng Cát lấy bối cảnh ở tương lai, khi mà ô nhiễm mỗi trường khiến cho tần ô zôn tại Nam Cực bị thủng, trái đất bước vào thời kỳ hoang mạc hóa và chắc chắn không thể đảo ngược. Lúc này, động vật cùng những thực vật quái dị có tên “côn trùng cát” là chủ nhân mới của trái đất. Không chấp nhận điều này, nhóm người gồm Tôn Bác Văn một phú thương, Lưu Đông nhà khoa học, Vương Cường đội trưởng bảo vệ, Lý Quốc Lương thợ máy cùng Mã Ba một kẻ lưu manh đã cùng nhau lên xe bọc thép để tìm “ốc đảo” nơi có thể duy trì sự sống cho loài người. Liệu rồi họ có thể tìm được nơi đó? Hành trình của họ có dễ dàng trước sự hung ác tàn bạo của những loài côn trùng?</p>', 'Full', 1, 'single', 'completed', 31, 2021, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Ziyi","avatar":""},{"name":"Tang Yinuo","avatar":""},{"name":"Ying Da","avatar":""},{"name":"Ma Muxuan","avatar":""},{"name":"Zhang Zhenlei","avatar":""},{"name":"Zhao Peilin","avatar":""},{"name":"Cui Yahan","avatar":""},{"name":"Liao Wang","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324329);
