INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tham-xinh-dep', 'Thần Thám Xinh Đẹp', 'Miss S', 'https://phimimg.com/upload/vod/20260630-1/9c4b62cc084efaee58b34a18d284a13c.jpg', 'https://phimimg.com/upload/vod/20260630-1/7a6e90abd84049df389b57c84cabd441.jpg', '<p>Chuyện phá án tại phòng tuần bổ trong tô giới Pháp giữa Tô Văn Lệ và thám trưởng La Thu Hằng. Thám trưởng La Thu Hằng vốn là người điềm tĩnh, cẩn trọng, chính trực, trong khi Tô Văn Lệ là thích hành động theo ý mình, hay xen vào các vụ án, hai người họ cũng vì thế mới quen biết. Về sau, La Thu Hằng dần nhận ra sự thông minh, độc lập, lương thiện của Văn Lệ và nảy sinh tình cảm lúc nào không hay.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 45, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Y Lợi","avatar":""},{"name":"Cao Vỹ Quang","avatar":""},{"name":"Đổng Tuyền","avatar":""},{"name":"Bốc Quán Kim","avatar":""},{"name":"Ngô Hạo Thần","avatar":""},{"name":"Điềm Nữu","avatar":""},{"name":"Diêu An Liêm","avatar":""},{"name":"Từ Thiệu Anh","avatar":""},{"name":"Lưu Dĩ Hàng","avatar":""},{"name":"Quách Thu Thành","avatar":""},{"name":"Hứa Dung Chân","avatar":""},{"name":"Cao Nhất Thanh","avatar":""},{"name":"Kháp Ny","avatar":""},{"name":"Khương Siêu","avatar":""},{"name":"Lưu Mẫn","avatar":""},{"name":"Ấn Tiểu Thiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["爱思小姐探案集","Ai Si Xiao Jie Tan An Ji","Qi Pao Mei Tan","미쓰에스: 치파오 미녀 탐정","Miss S: 치파오 미녀 탐정","미쓰에스 - 치파오 미녀 탐정","기포미탐: 미쓰에스 치파오 미녀 탐정","Miss S Murder Mysteries","旗袍美探"]', 1784690324329);
