INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('than-tham-xinh-dep', 'Thần Thám Xinh Đẹp', 'Miss S', 'thần thám xinh đẹp miss s mã y lợi cao vỹ quang đổng tuyền bốc quán kim ngô hạo thần điềm nữu diêu an liêm từ thiệu anh lưu dĩ hàng quách thu thành hứa dung chân cao nhất thanh kháp ny khương siêu lưu mẫn ấn tiểu thiên 爱思小姐探案集 ai si xiao jie tan an ji qi pao mei tan 미쓰에스: 치파오 미녀 탐정 miss s: 치파오 미녀 탐정 미쓰에스 - 치파오 미녀 탐정 기포미탐: 미쓰에스 치파오 미녀 탐정 miss s murder mysteries 旗袍美探', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cau-chuyen-an-giau', 'Những Câu Chuyện Ẩn Giấu', 'Invisible Stories', 'https://phimimg.com/upload/vod/20260630-1/580cb620078b349057998f6fe2a00b29.jpg', 'https://phimimg.com/upload/vod/20260630-1/978a953da70b56e9a8002d3b0aa51aeb.jpg', '<p>Đây là series tuyển tập gồm 6 câu chuyện độc lập lấy bối cảnh một khu nhà ở công cộng đa sắc tộc tại Singapore. Mỗi tập theo chân một nhân vật với những khó khăn riêng như nuôi con mắc chứng tự kỷ, người nhập cư, tài xế taxi, người có tham vọng trở thành influencer... Qua đó, phim khắc họa những góc khuất, hy sinh và khát vọng của những con người bình thường trong xã hội hiện đại.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 40, 2020, 'Vietsub', 'FHD', 'Singapore', 0, '[{"name":"Gavin Yap","avatar":""},{"name":"Diêu Ý Nhân","avatar":""},{"name":"Vương Vũ Thanh","avatar":""},{"name":"Suchada Rojmanothum","avatar":""},{"name":"Devin Pan","avatar":""},{"name":"Du Kha Na","avatar":""},{"name":"Aden Tan","avatar":""},{"name":"Kaew Korravee","avatar":""},{"name":"Ratchaneeboon Pheinwikraisophon","avatar":""},{"name":"Rosalind Pho","avatar":""},{"name":"Maimunah Bagharib","avatar":""},{"name":"Sunny Pang","avatar":""},{"name":"Kay Tong Lim","avatar":""},{"name":"Regina Lim","avatar":""},{"name":"Gemia Foo","avatar":""},{"name":"Karen Tan Bee Lin","avatar":""},{"name":"Serene Chen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Invisible Stories"]', 1784690324329);
