INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-boonie-ke-hoach-quai-vat-phan-1', 'Gấu Boonie: Kế Hoạch Quái Vật (Phần 1)', 'Boonie Bears: Monster Plan (Season 1)', 'https://phimimg.com/upload/vod/20260429-1/c40f68ac1dc9674d05bf2a72325b07d4.jpg', 'https://phimimg.com/upload/vod/20260429-1/e71d9908a569af95babc289dad812173.jpg', '<p>Sự xuất hiện của tiến sĩ Rex Vector và con quái vật cơ khí mang đến nỗi sợ hãi bao trùm khắp khu rừng. Với mục tiêu bảo vệ các loài động vật khỏi kế hoạch đánh cắp kỹ năng quái đản, bộ ba gồm anh em gấu Boonie cùng tiều phu Vick phải dấn thân vào một cuộc hành trình đầy kịch tính.</p>', 'Tập 40', 52, 'hoathinh', 'ongoing', 46, 2020, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Wei","avatar":""},{"name":"Zhang Bingjun","avatar":""},{"name":"Tan Xiao","avatar":""},{"name":"Yingying Miu","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["熊出没之探险日记3","熊出没之怪兽计划"]', 1784690324329);
