INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chu-thuat-hoi-chien-phan-1', 'Chú Thuật Hồi Chiến (Phần 1)', 'Jujutsu Kaisen (Season 1)', 'chú thuật hồi chiến (phần 1) jujutsu kaisen (season 1)  jujutsu kaisen 咒术回战 咒术回战 第一季 咒术回战 第二季 咒术回战 第三季 咒術迴戰 jujutsu kaisen: guerra de hechiceros अभिशाप नेटवर्क 呪術廻戦 懐玉・玉折 呪術廻戦 渋谷事変 呪術廻戦 死滅回游 前編 jujutsu kaisen: shimetsu kaiyuu - zenpen guerra de magia магическая битва มหาเวทย์ผนึกมาร 咒術迴戰 死滅迴游 前篇 магічна битва sorcery fight jjk jujutsu kaisen season 3: the culling game part 1 chú thuật hồi chiến 呪術廻戦', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-goi-noi-hoang-da-2020', 'Tiếng Gọi Nơi Hoang Dã', 'The Call Of The Wild', 'https://phimimg.com/upload/vod/20251214-1/ec27062ebf6c092f4d6b1ce099df4fbc.jpg', 'https://phimimg.com/upload/vod/20251214-1/91d87b1b502c1cae0f67eadca5343319.jpg', '<p>Bộ phim lấy bối cảnh cuộc đổ xô đi tìm vàng ở vùng Klondike, Yukon vào những năm 1890. Câu chuyện xoay quanh Buck, một chú chó to lớn, có trái tim ấm áp đang sống cuộc đời an nhàn trong một gia đình giàu có ở California.Cuộc sống của Buck bị đảo lộn hoàn toàn khi nó bị bắt cóc và bán đến vùng Yukon lạnh giá để làm chó kéo xe chở thư. Tại đây, Buck phải học cách sinh tồn giữa thiên nhiên khắc nghiệt và sự tàn nhẫn của con người. Sau nhiều biến cố và qua tay nhiều người chủ, Buck kết bạn với John Thornton (Harrison Ford) – một người đàn ông lớn tuổi đang gánh chịu nỗi đau mất mát. Cùng nhau, họ trải qua một chuyến hành trình phiêu lưu lớn, giúp Buck dần thức tỉnh bản năng nguyên thủy và tìm lại vị trí thực sự của mình trong thế giới tự nhiên.</p>', 'Full', 1, 'single', 'completed', 48, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Dan Stevens","avatar":""},{"name":"Colin Woodell","avatar":""},{"name":"Karen Gillan","avatar":""},{"name":"Omar Sy","avatar":""},{"name":"Raven Scott","avatar":""},{"name":"Wes Brown","avatar":""},{"name":"Cara Gee","avatar":""},{"name":"Jean Louisa Kelly","avatar":""},{"name":"Terry Notary","avatar":""},{"name":"Preston Bailey","avatar":""},{"name":"Michael Horse","avatar":""},{"name":"Alex Solowitz","avatar":""},{"name":"Stephanie Czajkowski","avatar":""},{"name":"Adam Fergus","avatar":""},{"name":"Brad Greenquist","avatar":""},{"name":"Scott MacDonald","avatar":""},{"name":"Anthony","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La llamada de lo salvaje","O Chamado da Floresta","絕境長征","野性的呼唤","Skriet från vildmarken","极地守护犬","The Call of the Wild"]', 1784690324329);
