INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-bao-to', 'Phi Vụ Bão Tố', 'Force of Nature', 'https://phimimg.com/upload/vod/20260617-1/f889b2b6d36e1129e20290d009830a4b.jpg', 'https://phimimg.com/upload/vod/20260617-1/1c5bae7e922c3324a077fac7ad11c8fe.jpg', '<p>Phim là cuộc chạm trán giữa tâm bão của hai sĩ quan cảnh sát với âm mưu táo tợn của một băng cướp. Giữa những tháng ngày chật vật vượt qua ký ức đau thương, chàng sĩ quan cảnh sát Cadeo được giao nhiệm vụ sơ tán khẩn cấp cư dân tại một khu chung cư giữa lòng Puerto Rico khi khi cơn bão lịch sử bất ngờ đổ bộ. Tại đây, Cadeo và cộng sự vô tình đụng độ băng cướp “máu lạnh” do John cầm đầu – kẻ sẵn sàng tàn sát để chiếm đoạt các tác phẩm nghệ thuật vô giá. Giữa tình thế ngàn cân treo sợi tóc, cơn bão nghiệt ngã còn đe dọa nhấn chìm cả toà nhà trong biển nước. Liệu sự liều lĩnh và lòng can đảm có giúp hai sĩ quan cảnh sát cùng những cư dân còn sót lại trong toà chung cư sống sót?</p>', 'Full', 1, 'single', 'completed', 31, 2020, 'Vietsub', 'FHD', 'Anh', 1, '[{"name":"Mel Gibson","avatar":""},{"name":"Emile Hirsch","avatar":""},{"name":"Kate Bosworth","avatar":""},{"name":"David Zayas","avatar":""},{"name":"Stephanie Cayo","avatar":""},{"name":"Tyler Jon Olson","avatar":""},{"name":"Rey Hernandez","avatar":""},{"name":"Blas Sien Diaz","avatar":""},{"name":"William Catlett","avatar":""},{"name":"Jasper Polish","avatar":""},{"name":"Swen Temmel","avatar":""},{"name":"Jesy McKinney","avatar":""},{"name":"Leslee Emmett","avatar":""},{"name":"Anil Raman","avatar":""},{"name":"Sebastian Vázquez","avatar":""},{"name":"Julio Ramoz Velez","avatar":""},{"name":"Joksan Ramos","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu