INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('avenue-5-phan-1', 'Avenue 5 (Phần 1)', 'Avenue 5 (Season 1)', 'https://phimimg.com/upload/vod/20260615-1/a8384ea2389308fe6a701c3f060025ed.jpg', 'https://phimimg.com/upload/vod/20260615-1/924947e8175c80e28ae468da45edba8d.jpg', '<p>Bối cảnh diễn ra vào 40 năm sau ở tương lai, thuyền trưởng không gian Ryan Clark cùng phi hành đoàn trên con tàu du hành vũ trụ sang trọng mang tên Avenue 5 phải chật vật xoay xở trước những hành khách bất mãn và hàng loạt sự cố ngoài ý muốn, sau khi con tàu gặp phải các trục trặc kỹ thuật nghiêm trọng trên boong.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 29, 2020, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Hugh Laurie","avatar":""},{"name":"Josh Gad","avatar":""},{"name":"Lenora Crichlow","avatar":""},{"name":"Zach Woods","avatar":""},{"name":"Nikki Amuka-Bird","avatar":""},{"name":"Suzy Nakamura","avatar":""},{"name":"Ethan Phillips","avatar":""},{"name":"Rebecca Front","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["第五大道","五号大道","Пятая авеню","Avenue 5"]', 1784690324329);
