INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-cua-chiec-nhan', 'Cuộc Phiêu Lưu Của Chiếc Nhẫn', 'Adventure Of The Ring', 'https://phimimg.com/upload/vod/20251203-1/1a8c61ec02b321a57f890099730fe34f.jpg', 'https://phimimg.com/upload/vod/20251203-1/17fffa03a28602498d22471f36bb33c2.jpg', '<p>Hoàng Dịch Chi đánh mất chiếc nhẫn trên tàu điện ngầm vào đúng ngày anh định cầu hôn. Chiếc nhẫn qua tay 7 người và tạo nên 7 câu chuyện lãng mạn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 33, 2020, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Chris Wang","avatar":""},{"name":"Allison Lin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["戒指流浪記","La aventura del anillo","Adventure of the Ring"]', 1784690324329);
