INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-di-dong', 'Trò Chơi Di Động', 'A3!', 'https://phimimg.com/upload/vod/20260611-1/ee3d378932a5f50162e10d9a454b34b9.jpg', 'https://phimimg.com/upload/vod/20260611-1/00060e882add9e1a17df5a7751baae0e.jpg', '<p>Trò Chơi Di Động đưa khán giả đến “Veludo Way” - con phố sân khấu nổi tiếng ở ngoại ô Tokyo, nơi Izumi Tachibana bất ngờ trở thành người dẫn dắt đoàn kịch MANKAI đang đứng trước nguy cơ giải thể. Từ một cô gái chưa từng nghĩ sẽ gắn bó với sân khấu, Izumi bắt đầu hành trình vực dậy đoàn kịch cùng những chàng trai trẻ đầy cá tính và đam mê diễn xuất. Giữa ánh đèn sân khấu, tiếng cười và những giấc mơ tuổi trẻ, bộ phim anime mang đến câu chuyện thanh xuân vừa sôi nổi, cảm động vừa tràn đầy nhiệt huyết.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 30, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuichi Jose","avatar":""},{"name":"Chiharu Sawashiro","avatar":""},{"name":"Shunsuke Takeuchi","avatar":""},{"name":"Kento Hama","avatar":""},{"name":"Kentaro Kumagai","avatar":""},{"name":"Seiya Konishi","avatar":""},{"name":"Atsushi Tamaru","avatar":""},{"name":"Takuya Sato","avatar":""},{"name":"Junta Terashima","avatar":""},{"name":"Toshiyuki Toyonaga","avatar":""},{"name":"Tetsuya Kakihara","avatar":""},{"name":"Daman Mills","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A3!","A3! Cour 2","A3! Season Spring & Summer","エースリー Season Spring & Summer","A3! 시즌 스프링 엔 썸머","A3! 시즌 스프링 앤 썸머","A3! Act! Addict! Actors!","A3! Season Autumn & Winter"]', 1784690324329);
