INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-rung-xanh-phan-2', 'Quái Vật Rừng Xanh (Phần 2)', 'Brahmarakshas (Season 2)', 'https://phimimg.com/upload/vod/20260611-1/150c94ec2702c58ab615bb7ca281b376.jpg', 'https://phimimg.com/upload/vod/20260611-1/50996aef33eb2d5dc7f03a0a467dd9f0.jpg', '<p>16 năm sau bi kịch đẫm máu của gia đình Kalindi, một quái vật mang khát vọng bất tử bất ngờ trở lại và bắt đầu truy lùng cô gái sở hữu lá số tử vi đặc biệt. Mỗi lần nó xuất hiện đều kéo theo những cái chết kinh hoàng. Trong khi Kalindi liên tiếp trở thành mục tiêu của hàng loạt âm mưu đen tối của những kẻ tham lam muốn chiếm đoạt tài sản, cô lại bị cuốn vào cơn ác mộng đáng sợ liên quan đến con quái vật chưa từng biến mất suốt nhiều năm qua.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 40, 2020, 'Lồng Tiếng', 'FHD', 'Ấn Độ', 0, '[{"name":"Adiba Hussain","avatar":""},{"name":"Leenesh Mattoo","avatar":""},{"name":"Ashish Kaul","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Brahmarakshas: Jaag Utha Shaitaan","ब्रह्मराक्षस"]', 1784690324329);
