INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-chay-ngam-2020', 'Dòng Chảy Ngầm', 'Undercurrent', 'https://phimimg.com/upload/vod/20260603-1/3110cfde0ec50d99f7e3b14648db7862.jpg', 'https://phimimg.com/upload/vod/20260603-1/fedc1a65f5d1c4b81f92b4051f89536b.jpg', '<p>Vào một buổi tối mùa đông năm 1979, cuộc bắt giữ những người biểu tình chống chính phủ đang diễn ra. Thành phố đang trong lệnh giới nghiêm, nhưng một nữ sinh tuổi teen, vì tò mò, đã bám theo một chàng trai trẻ bí ẩn từ con đường ven sông vào một túp lều bỏ hoang. Sống ở Đài Loan dưới chế độ thiết quân luật, liệu những người đàn ông liên tục trốn tránh chính quyền, xã hội, hay tình cảm chôn chặt trong tim họ?</p>', 'Full', 1, 'single', 'completed', 37, 2020, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Chih-Han Chang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["宵禁"]', 1784690324329);
