INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-ke-tiep-la-hanh-phuc', 'Trạm Kế Tiếp Là Hạnh Phúc', 'Find Yourself', 'https://phimimg.com/upload/vod/20241118-1/0530519fdc3b38c1c4b42931673f69e3.jpg', 'https://phimimg.com/upload/vod/20260528-1/8e1c2ae660a550e004099195e4782847.jpg', '<p>Nữ doanh nhân kiên định loay hoay giữa mối tình tay ba giữa chàng trai trẻ quyến rũ và người giám đốc hơn tuổi. Từ đây, cô bước vào con đường tình yêu trái lẽ thường.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 26, 2020, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Thiến","avatar":""},{"name":"Tống Uy Long","avatar":""},{"name":"Vương Diệu Khánh","avatar":""},{"name":"Ngu Thư Hân","avatar":""},{"name":"Trương Vũ Kiếm","avatar":""},{"name":"Dương Chi Doanh","avatar":""},{"name":"Châu Kỳ Kỳ","avatar":""},{"name":"Thái Nhã Đồng","avatar":""},{"name":"Tăng Lê","avatar":""},{"name":"Ngụy Triết Minh","avatar":""},{"name":"Mã Lệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["资深少女的初恋","资深少女的幸福生活","รักแรกของสาวใหญ่","下一站是幸福","Find Yourself"]', 1784690324329);
