INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dac-nhiem-swat-phan-4', 'Đội Đặc Nhiệm SWAT (Phần 4)', 'S.W.A.T. (Season 4)', 'https://phimimg.com/upload/vod/20251116-1/e6960daa505bbd3f64458b6876d841c7.jpg', 'https://phimimg.com/upload/vod/20251116-1/e053d0092911a148b6fbaec3194725bf.jpg', '<p>Phim theo chân Daniel &quot;Hondo&quot; Harrelson, một trung sĩ đặc nhiệm kỳ cựu và các thành viên đội SWAT, trong hành trình bảo vệ sự bình yên của đường phố Los Angeles. Sau khi đội trưởng cũ của đội SWAT bị sa thải vì vô tình bắn một thiếu niên trong lúc đấu súng, Hondo được giao nhiệm vụ dẫn dắt đơn vị tinh nhuệ này. Trong vai trò mới, Hondo buộc phải nỗ lực hết mình để duy trì sự phối hợp ăn ý giữa các thành viên trong đội và đồng thời tìm cách lấy lại lòng tin của người dân vào lực lượng hành pháp.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 12, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Shemar Moore","avatar":""},{"name":"Jay Harrington","avatar":""},{"name":"David Lim","avatar":""},{"name":"Patrick St. Esprit","avatar":""},{"name":"Anna Enger Ritch","avatar":""},{"name":"Niko Pepaj","avatar":""},{"name":"Annie Ilonzeh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["S.W.A.T.: Força de Intervenção","反恐特警组","סוואט","יממ","Ｓ．Ｗ．Ａ．Ｔ．シーズン６","Спецназ города ангелов","S.W.A.T."]', 1784690324329);
