INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-de-dang', 'Cuộc Sống Dễ Dàng', 'EASY LIVING', 'https://phimimg.com/upload/vod/20260509-1/45f54f49843e34b0cf3848356f5a78df.jpg', 'https://phimimg.com/upload/vod/20260509-1/7378afc799b4ad3b35ac2b531fd60996.jpg', '<p>Easy Living là một bộ phim hài tuổi mới lớn mang sắc thái u buồn, trong đó hiện thực đầy kịch tính và đương đại của những người di cư được nhìn nhận qua con mắt của một đứa trẻ và biến thành một cuộc phiêu lưu.</p>', 'Full', 1, 'single', 'completed', 24, 2020, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Camilla Semino Favro","avatar":""},{"name":"James Miyakawa","avatar":""},{"name":"Manoel Hudec","avatar":""},{"name":"Alberto Boubakar Malanchino","avatar":""},{"name":"Giorgio Serra","avatar":""},{"name":"Brando Facente","avatar":""},{"name":"Francesco Sala","avatar":""},{"name":"Alessandro Bonsignori","avatar":""},{"name":"Giovanna Luraschi","avatar":""},{"name":"Paola Luraschi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["活着，不难","轻松生活","Easy Living"]', 1784690324329);
