INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-mat-na-hon-chien-thoi-gian-thuc', 'Hiệp Sĩ Mặt Nạ: Hỗn Chiến Thời Gian Thực', 'Kamen Rider Zero-One: Real Time', 'https://phimimg.com/upload/vod/20260505-1/df6cd7594f78571d4fabaacf956ee6aa.jpg', 'https://phimimg.com/upload/vod/20260505-1/2db97dc14aa4491be92f0a8012731612.jpg', '<p>Một người đàn ông bí ẩn tên là Es/Kamen Rider Eden xuất hiện, gây ra những hành động khủng bố đồng thời trên khắp thế giới, với hàng ngàn tín đồ tin theo hắn. Trong khi người dân lần lượt gục ngã và thế giới chìm trong hỗn loạn, Aruto Hiden đứng lên để ngăn chặn hắn. Isamu Fuwa, Yaiba Yuia, Gai Amatsu, cùng Jin và Horobi của MetsubouJinrai.net cũng biến hình thành Kamen Rider và chiến đấu chống lại kẻ thù trong khi nỗ lực tìm kiếm sự thật.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Fumiya Takahashi","avatar":""},{"name":"Ryutaro Okada","avatar":""},{"name":"Noa Tsurushima","avatar":""},{"name":"Hiroe Igeta","avatar":""},{"name":"Hideaki Ito","avatar":""},{"name":"Daisuke Nakagawa","avatar":""},{"name":"Shuya Sunagawa","avatar":""},{"name":"Nachi Sakuragi","avatar":""},{"name":"Daichi Yamaguchi","avatar":""},{"name":"Satsuki Nakayama","avatar":""},{"name":"Kazuya Kojima","avatar":""},{"name":"Asumi Narita","avatar":""},{"name":"Seiji Fukushi","avatar":""},{"name":"Arata Saeki","avatar":""},{"name":"Goro Yoshida","avatar":""},{"name":"Tomomi Maruyama","avatar":""},{"name":"Hirook","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Kamen Rider Zero-One Th