INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gap-duoc-nhau-cung-la-kho-bau', 'Gặp Được Nhau Cũng Là Kho Báu', 'Adam', 'https://phimimg.com/upload/vod/20260505-1/0b61afb7c245c1f0a77adc542d1af7b4.jpg', 'https://phimimg.com/upload/vod/20260505-1/4d855ba2b164197a54f5dea155ad1a6e.jpg', '<p>Vào ngày nhận tin vui, Adam gặp nạn và liệt tứ chi. Tuyệt vọng bủa vây, anh tưởng đời mình chấm hết cho đến khi gặp điều dưỡng Yevgeniya. Cô giúp anh chấp nhận thực tại, tìm lại hy vọng và tình yêu.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Aaron Paul","avatar":""},{"name":"Jeff Daniels","avatar":""},{"name":"Tom Sizemore","avatar":""},{"name":"Tom Berenger","avatar":""},{"name":"Lena Olin","avatar":""},{"name":"Shannon Lucio","avatar":""},{"name":"Paul Walter Hauser","avatar":""},{"name":"Celia Weston","avatar":""},{"name":"Michael Weston","avatar":""},{"name":"Billy Field","avatar":""},{"name":"Jan Radcliff","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Quad","人生急轉彎","Adam"]', 1784690324329);
