INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-hai-cuong-chu', 'Nộ Hải Cuồng Chu', 'Mad Spider Sea', 'https://phimimg.com/upload/vod/20231111-1/1e7d7455d56cec71709e71a3839a56df.jpg', 'https://phimimg.com/upload/vod/20231111-1/3ca64830af928294b6cf696ca7e2394c.jpg', '<p>Thành viên đội cứu hộ Ajie và những người bạn đồng hành đã giải cứu một tàu chở đá ngầm trong cơn bão, nhưng gặp vị thuyền trưởng cứng đầu và không muốn bỏ cuộc. Cùng lúc đó, một bóng đen ám ảnh dưới đáy biển sâu và kéo mọi người xuống biển. Kể từ đó, Ajie còn sống sót, mang bóng dáng của cái chết của các đồng nghiệp của mình, trở nên suy đồi và chán nản. Nhiều năm sau, Ajie vượt qua cái bóng và lên thuyền đánh cá một lần nữa. Họ cứu Xiaojing, người đã rơi xuống biển sau khi du thuyền của anh ta bị lật. Khi đã lên tàu, mọi thứ bắt đầu trở nên kỳ lạ. Khi những người mắc kẹt đối mặt với thử thách khắc nghiệt của cơn bão, họ nhận thấy điều nguy hiểm nhất còn hơn thế nhiều. Có những sinh vật vô danh thèm muốn dưới nước. Những con người man rợ phải gạt bỏ những định kiến của mình và cùng nhau cố gắng để tồn tại.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Đài Loan', 0, '[{"name":"Sunny Wang","avatar":""},{"name":"Ko Chia-yen","avatar":""},{"name":"Rexen Cheng Jen-Shuo","avatar":""},{"name":"Andrew Lin","avatar":""},{"name":"Lee-Zen Lee","avatar":""},{"name":"Jiu Kong","avatar":""},{"name":"Lee Kang-sheng","avatar":""},{"name":"Aggie Hsieh","avatar":""},{"name":"Hong Yu Hong","avatar":""},{"name":"Tao Yu Lin","avatar":""},{"name":"Cliff Cho","avatar":""},{"name":"Chia-Yi Chu","avatar":""},{"name":"Angel Wang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf407791667