INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-anh-hung-pha-hoai-phan-2', 'Siêu Anh Hùng Phá Hoại (Phần 2)', 'The Boys (Season 2)', 'siêu anh hùng phá hoại (phần 2) the boys (season 2) karl urban jack quaid antony starr erin moriarty jessie t. usher laz alonso chace crawford tomer capone karen fukuhara nathan mitchell jensen ackles момчетата 英雄克星 黑袍纠察队 kluci الرفاق the boys - a fiúk ザ・ボーイズ 더 보이즈 chłopcy băieții дечаци парни chlapci ก๊วนหนุ่มซ่าล่าซูเปอร์ฮีโร่ 黑袍糾察隊 хлопці хлопчаки пацани типи yigitlar siêu anh hùng phá hoại the boys', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ran-chin-dau-dot-bien', 'Rắn Chín Đầu Đột Biến', 'Variation Hydra', 'https://phimimg.com/upload/vod/20260425-1/d537e55f16c1702d92b1248ea13e315c.jpg', 'https://phimimg.com/upload/vod/20260425-1/23b909f69bb8405fb77f6ff796c5f471.jpg', '<p>Nhà khoa học trẻ Bai Jingtian dẫn đầu một nhóm người vào những ngọn núi rộng lớn để tìm kiếm một loài thủy thần giết người. Anh cho rằng đó chỉ là một cuộc thám hiểm khoa học bình thường. Không ngờ, nhiều mối nguy hiểm sẽ nối tiếp nhau - \&quot;bóng ma\&quot; chặn đường, quái vật hoành hành và lòng người khó lường.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Zhengyu","avatar":""},{"name":"Hannah Zhang","avatar":""},{"name":"Shi Guohui","avatar":""},{"name":"Kai Li","avatar":""},{"name":"Yu Mei Yang","avatar":""},{"name":"Huang Shuowen","avatar":""},{"name":"En Jing","avatar":""},{"name":"Wang Kanwei","avatar":""},{"name":"Zuo Xiaoguang","avatar":""},{"name":"Zhao Jingzhi","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Rise of the Mutant Cobras","变异九头蛇"]', 1784690324329);
