INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('2-trai-tim', '2 Trái Tim', '2 Hearts', '2 trái tim 2 hearts jacob elordi adan canto tiera skovbye radha mitchell kari matchett tahmoh penikett steve bacic jordan burtchett neil webb anthony konechny georgia bradner malcolm stewart corey woods doralynn mui stefania indelicato beck schurko 2颗心 deux cœurs două inimi قلبان 兩顆心 2 srca 2 srdce 2 cœurs 2 καρδιές שני לבבות 2 दिल két szív intreccio di destini 2ハート 2개의 심장 all my tomorrows 2 inimi два сердца 2 corazones 2 หัวใจสายใยรัก 2 kalp два серця 2 trái tim fate të kryqëzuara 2 срца 2 сердца 2 hearts', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-cuoi-sieu-dang', 'Trùm Cuối Siêu Đẳng', 'Boss Level', 'https://phimimg.com/upload/vod/20260413-1/b4b2b4fcb0a8cf4d101684945d50c1d1.jpg', 'https://phimimg.com/upload/vod/20260413-1/f10597913d8873437da74aa3f8374fa7.jpg', '<p>Mắc kẹt trong một vòng lặp thời gian ngay đúng ngày anh ta bị giết chết, một cựu đặc vụ Roy Pulver (Frank Gillo) đã phát hiện ra manh mới về một dự án bí mật của chính phủ có thể giải đáp bí ẩn đằng sau cái chết vô thời hạn của anh ta. Roy buộc lòng phải chạy đua với thời gian và truy bắt tên Colonel Ventor (Mel Gibson), đầu sỏ của dự án chính phủ này. Trong lúc đó, anh phải thoát khỏi cuộc vây bắt của những tên sát thủ tàn ác quyết tâm ngăn cản Roy tìm ra được sự thật. Liệu Roy Pulver có thể thoát khỏi vòng lặp này và cứu lấy gia đình đồng thời sống lại một lần nữa vào ngày mai?</p>', 'Full', 1, 'single', 'completed', 16, 2020, 'Vietsub', 'FHD', 'Anh', 1, '[{"name":"Frank Grillo","avatar":""},{"name":"Mel Gibson","avatar":""},{"name":"Naomi Watts","avatar":""},{"name":"Will Sasso","avatar":""},{"name":"Annabelle Wallis","avatar":""},{"name":"Sheaun McKinney","avatar":""},{"name":"Selina Lo","avatar":""},{"name":"Michelle Yeoh","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Meadow Williams","avatar":""},{"name":"Mathilde Ollivier","avatar":""},{"name":"Rio Grillo","avatar":""},{"name":"Armida Lopez","avatar":""},{"name":"Buster Reeves","avatar":""},{"name":"Eric Etebari","avatar":""},{"name":"Quinton ''Rampage'' Jackson","avatar":""},{"name":"Rash","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f0