INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('3-phan-4', '3% (Phần 4)', '3% (Season 4)', 'https://phimimg.com/upload/vod/20260403-1/e6ed069da5615850cf9546fe3a4f01ff.jpg', 'https://phimimg.com/upload/vod/20260403-1/7ba411abd03e28ef7abb3b61511dbb66.jpg', '<p>Phim 3% nói về một tương lai thế giới bị chia cắt làm hai: Offshore và Inland. Một bên sống trong sung sướng, văn minh, tiến bộ và một bên sống trong thiếu thốn, khó khăn và lo sợ. Hằng năm, những cư dân đủ 20 tuổi sẽ được trao một cơ hội tham gia vào Quá Trình Chọn Lọc, khi tham gia, họ sẽ phải trải qua nhiều bài kiểm tra khác nhau, để xem họ có đủ khả năng lọt vào 3% trên tổng số người được đến với Offshore (Bên sống tốt đẹp hơn).</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 32, 2020, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Bianca Comparato","avatar":""},{"name":"Rodolfo Valente","avatar":""},{"name":"Vaneza Oliveira","avatar":""},{"name":"Rafael Lozano","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["3 por cento","百分之三","3%","3 percent","3 Pourcent","3 %","3","Три відсотки","Three Percent"]', 1784690324330);
