INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-duong-nguoc-nang', 'Hướng Dương Ngược Nắng', 'Sunlight In The Mirror', 'https://phimimg.com/upload/vod/20260328-1/d6d217334f3e657bcbc347ecb0c7619f.jpg', 'https://phimimg.com/upload/vod/20260328-1/6f35e5043d4f2380c618273491e363c4.jpg', '<p>Hướng dương ngược nắng xoay quanh Minh (Lương Thu Trang) với những mối quan hệ gia đình phức tạp. Từ bé đến lớn sống với người mẹ vô trách nhiệm, bỗng một ngày cô và em trai của mình (Đình Tú) lại được phát hiện là con riêng của Tổng giám đốc Tập đoàn Cao Dược và là thành viên chính thức trong gia tộc họ Cao. Cũng từ đây, cô phải đối mặt với cuộc đua tranh quyền lực của các thành viên trong chính gia đình mình cùng những người xung quanh với đầy rẫy âm mưu và tham vọng.</p>', 'Hoàn Tất (70/70)', 70, 'series', 'completed', 24, 2020, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thu Hà","avatar":""},{"name":"Việt Anh","avatar":""},{"name":"Lương Thu Trang","avatar":""},{"name":"Hồng Đăng","avatar":""},{"name":"Đức Trung","avatar":""},{"name":"Vân Dung","avatar":""},{"name":"Mạnh Cường","avatar":""},{"name":"Phạm Cường","avatar":""},{"name":"Doãn Quốc Đam","avatar":""},{"name":"Đình Tú","avatar":""},{"name":"Công Lý","avatar":""},{"name":"Nguyễn Quỳnh","avatar":""},{"name":"Minh Phương","avatar":""},{"name":"Trần Nhượng","avatar":""},{"name":"Trần Đức","avatar":""},{"name":"Ngọc Tản","avatar":""},{"name":"Hoang Yen","avatar":""},{"name":"Nguyễn Mạnh Cường","avatar":""},{"name":"Nguyễn Mạnh Hưng","avatar":""},{"name":"Thanh Hương","avatar":""},{"name":"Hồng Diễm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hướng dương ngược nắng"]', 1784690324330);
