INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huong-duong-nguoc-nang', 'Hướng Dương Ngược Nắng', 'Sunlight In The Mirror', 'hướng dương ngược nắng sunlight in the mirror thu hà việt anh lương thu trang hồng đăng đức trung vân dung mạnh cường phạm cường doãn quốc đam đình tú công lý nguyễn quỳnh minh phương trần nhượng trần đức ngọc tản hoang yen nguyễn mạnh cường nguyễn mạnh hưng thanh hương hồng diễm hướng dương ngược nắng', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-rong-phan-2', 'Trống Rỗng (Phần 2)', 'The Hollow (Season 2)', 'https://phimimg.com/upload/vod/20260327-1/30c4da831d05ddf9608e9647a0a2c394.jpg', 'https://phimimg.com/upload/vod/20260327-1/79d47c5a89eabe446beda2ca8bc2860f.jpg', '<p>Ba cô cậu học sinh cùng nhau tìm đường về nhà sau khi thức dậy ở một vương quốc xa lạ với vô số cổng phép thuật, những câu đố hóc búa và lũ quái vật hung ác.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 27, 2020, 'Vietsub + Lồng Tiếng', 'FHD', 'Canada', 0, '[{"name":"Ashleigh Ball","avatar":""},{"name":"Connor Parnall","avatar":""},{"name":"Adrian Petriw","avatar":""},{"name":"Alex Barima","avatar":""},{"name":"Diana Kaarina","avatar":""},{"name":"Jesse Moss","avatar":""},{"name":"Mark Hildreth","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ロスト・ティーンエイジャー","Улоговина","The Hollow"]', 1784690324330);
