INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-bo-de-gio-tan-truong', 'Nhật Ký Bờ Đê Giờ Tan Trường', 'Diary Of Our Days At The Breakwater', 'https://phimimg.com/upload/vod/20260327-1/64449ba46d3290f4be9b13f8f2c918f3.jpg', 'https://phimimg.com/upload/vod/20260327-1/fd10709bd8abdd36c788ce59b4e36208.jpg', '<p>Tsurugi Hina là tuýp người thích ở trong nhà và không ưa các sinh vật sống. Cô bé mới chuyển nhà từ thành phố về nông thôn. Tuy có ý định vào câu lạc bộ thủ công mỹ nghệ để vui vẻ tận hưởng cuộc sống cấp ba nhưng trong một lần đi dạo, Hina đã bắt gặp Kuroiwa Yuki, người đã rủ cô bé vào một nơi có tên “Câu lạc bộ bờ đê” kì lạ và bắt đầu những chuyến đi câu. Các thành viên khác xung quanh Hina đều có những tính cách riêng. Liệu cuộc sống cấp ba của Hina sẽ ra sao đây?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 15, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kanon Takao","avatar":""},{"name":"Natsumi Kawaida","avatar":""},{"name":"Yu Sasahara","avatar":""},{"name":"Satomi Akesaka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["放学后海堤日志","Houkago Teibou Nisshi","Hōkago Teibō Nisshi","Hokago Teibo Nisshi","บันทึกชมรมริมเขื่อนหลังเลิกเรียน","Afterschool Embankment Journal","Nhật Ký Bờ Đê Giờ Tan Trường","放課後ていぼう日誌"]', 1784690324330);
