INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-ky-bo-de-gio-tan-truong', 'Nhật Ký Bờ Đê Giờ Tan Trường', 'Diary Of Our Days At The Breakwater', 'nhật ký bờ đê giờ tan trường diary of our days at the breakwater kanon takao natsumi kawaida yu sasahara satomi akesaka 放学后海堤日志 houkago teibou nisshi hōkago teibō nisshi hokago teibo nisshi บันทึกชมรมริมเขื่อนหลังเลิกเรียน afterschool embankment journal nhật ký bờ đê giờ tan trường 放課後ていぼう日誌', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tro-balanha', 'Nhà Trọ Balanha', 'Balanha Boarding House', 'https://phimimg.com/upload/vod/20260327-1/72c1c63c953997e4a04ed0727768a2bf.jpg', 'https://phimimg.com/upload/vod/20260327-1/cd12ac1493268547b1d8ab27fcfee551.jpg', '<p>Lâm, Bách và Nhân là những sinh viên mới tốt nghiệp, nhiệt tình bước vào đời với ước mơ phải làm được điều gì đó thật đặc biệt. Quyết tâm lớn, hoài bão lớn, thêm cả sự nhiệt tình của tuổi trẻ, mọi cánh cửa chắc chắn sẽ mở ra với họ. Nhưng éo le thay, cả ba lại chẳng giỏi giang như họ vốn nghĩ, họ nhìn đời quá đơn giản, nghĩ mọi thứ &quot;dễ như ăn oản&quot;. Và kết quả tất yếu là việc khởi nghiệp bằng kinh doanh homestay không thuận lợi, ba chàng trai buộc phải gánh những khoản nợ chồng chất. Mọi khó khăn tiếp tục dồn dập rơi xuống khi họ phải phải cưu mang thêm những người mới bước vào Nhà trọ Balanha cùng sinh sống. Đó là Hân – một bà mẹ đơn thân không đồng xu dính túi với đứa bé mới vài tháng tuổi; là Nhi – cô người yêu cũ &quot;xấu tính&quot; vừa &quot;đá đít&quot; Lâm; là Nhiên – em gái ruột của Lâm, mới tốt nghiệp Đại học nhưng chưa tìm được việc làm.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 39, 2020, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Xuân Nghị","avatar":""},{"name":"Công Dương","avatar":""},{"name":"Trần Nghĩa","avatar":""},{"name":"Nguyễn Quỳnh","avatar":""},{"name":"Bích Ngọc","avatar":""},{"name":"Trần Vân","avatar":""},{"name":"Trần Đức","avatar":""},{"name":"Anh Thơ","avatar":""},{"name":"Hoàng Kiên","avatar":""},{"name":"Thu Hoài","avatar":""},{"name":"Phạm Tiến Lộc","avatar":""},{"name":"Thùy Anh","avatar":""},{"name":"Duy Hưng","avatar":""},{"name":"Andrea Aybar","avatar":""},{"name":"Hoàng Mai Anh","avatar":""},{"name":"Xuân Trường","avatar":""},{"name":"Ngọc Thu","avatar":""},{"name":"Liên Tít","avatar":""},{"name":"Lý Chí Huy","avatar":""},{"name":"Que Chi","avatar":""},{"name":"Mai Như Quỳnh","avatar":""},{"name":"Kiều Yến Ng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nhà trọ Balanha"]', 1784690324330);
