INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nha-tro-balanha', 'Nhà Trọ Balanha', 'Balanha Boarding House', 'nhà trọ balanha balanha boarding house xuân nghị công dương trần nghĩa nguyễn quỳnh bích ngọc trần vân trần đức anh thơ hoàng kiên thu hoài phạm tiến lộc thùy anh duy hưng andrea aybar hoàng mai anh xuân trường ngọc thu liên tít lý chí huy que chi mai như quỳnh kiều yến ng nhà trọ balanha', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-ba-cuoc-san', 'Mười Ba Cuộc Săn', 'The Vindicator', 'https://phimimg.com/upload/vod/20260320-1/bb6a63ff13993390c3d5d3b56246063c.jpg', 'https://phimimg.com/upload/vod/20260320-1/7655f8d8f6891da8a07f368901a3c78b.jpg', '<p>Đảng viên Cộng sản Cao Lãng vì để bảo vệ đồng đội Diệp Vô Song đã một thân một mình quay trở về quê hương - làng thợ săn. Tại yến tiệc săn bắn của làng, Cao Lãng phát hiện Diệp Vô Song sắp đến ngày sinh nở, không tiện chuyển đi ngay lập tức. Đúng lúc đó, quân địch đang truy bắt Diệp Vô Song đột ngột xuất hiện. Chúng sát hại những dân làng vô tội và bắt đi Diệp Vô Song. Dựa vào kỹ năng săn bắn điêu luyện trong rừng sâu của một thợ săn thực thụ, Cao Lãng đã bắt đầu một cuộc đối đầu sinh tử với tiểu đội quân địch giữa chốn rừng thiêng nước độc...</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cốc Thượng Úy","avatar":""},{"name":"Thang Yến","avatar":""},{"name":"Shibuya Tenma","avatar":""},{"name":"Mạnh Trí Siêu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["十三獵殺","Hunt 13","Shi San Lie Sha","十三猎杀"]', 1784690324330);
