INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('muoi-ba-cuoc-san', 'Mười Ba Cuộc Săn', 'The Vindicator', 'mười ba cuộc săn the vindicator cốc thượng úy thang yến shibuya tenma mạnh trí siêu 十三獵殺 hunt 13 shi san lie sha 十三猎杀', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-khong-muon-lam-ban-voi-con-toi-khong-muon-lam-ban', 'Mẹ Không Muốn Làm Bạn Với Con (Tôi Không Muốn Làm Bạn)', 'I Don''t Want To Be Friends With You', 'https://phimimg.com/upload/vod/20260321-1/eb85645e9fb8cb879d304665dc21b24d.jpg', 'https://phimimg.com/upload/vod/20260321-1/bfe3828bf5daab97c2008c4110a4f74c.jpg', '<p>Nữ sinh cấp 3 Lý Tiến Bộ từ nhỏ lớn lên cùng với mẹ trong một chuyến du lịch kì ảo trở về 20 năm trước, gặp được mẹ là Lý Thanh Đồng trở thành bạn tốt. Hai người bởi vì khác biệt về thời đại, tính cách, mà xảy ra một loạt những câu chuyện dở khóc dở cười, nắm tay nhau cùng vượt qua những ngọt ngào và chua xót của tuổi trẻ. Lý Tiến Bộ hiểu được sự dũng cảm, điềm đạm của mẹ, sau khi trở về thực tại, hóa giải mọi khúc mắc, cùng tìm ra chân lý của cuộc sống.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 14, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Hạo Vũ","avatar":""},{"name":"Trang Đạt Phi","avatar":""},{"name":"Chu Ngạn Thần","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Cai Bu Yao He Ni Zuo Peng You Ne","I Don''t Want to be Friends with You","WoCaiBuYaoHeNiZuoPengYouNe","아재불요화니주붕우니: 엄마는 열일곱","Я не хочу с тобой дружить","我才不要和你做朋友呢"]', 1784690324330);
