INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('domingo', 'Domingo', 'Domingo', 'https://phimimg.com/upload/vod/20260311-1/2e6625f58edbf7e8737deb58d1fd3509.jpg', 'https://phimimg.com/upload/vod/20260311-1/0183d4520f1b41840cbc98edb0f87b43.jpg', '<p>Sau khi ly hôn, Domingo quyết tâm theo đuổi ước mơ trở thành bình luận viên thể thao. Anh tìm cách gia nhập đài truyền hình địa phương để bắt đầu lại cuộc sống. Tuy nhiên, những lời bình luận thẳng thắn của anh nhanh chóng gây chú ý. Quan điểm của Domingo tạo ra nhiều tranh luận trong cộng đồng. Từ đó, hành trình mới của anh bắt đầu với những tác động không ngờ.</p>', 'Full', 1, 'single', 'completed', 31, 2020, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Eduardo Covarrubias","avatar":""},{"name":"Martha Claudia Moreno","avatar":""},{"name":"Jesús Hernández","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["星期天的多明哥","Domingo"]', 1784690324330);
