INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhin-xuong-vuc-tham', 'Nhìn Xuống Vực Thẳm', 'Im Abgrund / Staring into the Abyss', 'https://phimimg.com/upload/vod/20260311-1/40c1874bcbccfb8f44b875ea98226335.jpg', 'https://phimimg.com/upload/vod/20260311-1/3c712fa96ebb36d5e2b59c448ba1ede5.jpg', '<p>Sĩ quan David Wallat âm thầm theo dõi Joseph Maria Hagenow, kẻ giết trẻ em vừa được trả tự do sau nhiều năm tù. Hagenow nhanh chóng thao túng những người canh gác và bắt đầu lại trò chơi tâm lý nguy hiểm của mình. Khi một đứa trẻ bất ngờ mất tích, nỗi sợ hãi lan rộng trong cộng đồng. Wallat buộc phải hành động trước khi quá muộn. Nhưng mỗi bước đi đều có thể khiến kế hoạch bí mật của anh bị bại lộ.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Florian Stetter","avatar":""},{"name":"Peter Kurth","avatar":""},{"name":"Tobias Moretti","avatar":""},{"name":"Tinka Fürst","avatar":""},{"name":"Simon Schwarz","avatar":""},{"name":"Jessica McIntyre","avatar":""},{"name":"Odine Johne","avatar":""},{"name":"Jan Krauter","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Im Abgrund"]', 1784690324330);
