INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-ma-than-cai-to-khat-nhi', 'Phong Ma Thần: Cái Tô Khất Nhi', 'Crazy Beggar SuQiEr', 'https://phimimg.com/upload/vod/20260308-1/be973ea5a34db13168c61a31a0aff457.jpg', 'https://phimimg.com/upload/vod/20260308-1/a16d266dc147eb2f05fb2ef3351b7c8b.jpg', '<p>Bộ phim kể về hành trình của nam chính Tô Sán – một võ trạng nguyên lừng lẫy. Trong một lần triệt phá Thiên Môn Giáo (một giáo phái buôn bán nha phiến trái phép), Tô Sán không may bị thương dẫn đến mất trí nhớ, phải sống lưu lạc đầu đường xó chợ và trở thành kẻ ăn mày với danh xưng Tô Khất Nhi. Trong quãng thời gian khốn khó đó, anh được hai mẹ con Kim Chi và Tiểu Quả thu nhận, chăm sóc. Tuy nhiên, vì bí mật về thuốc phiện bị rò rỉ, Thiên Môn Giáo đã bắt cóc cô bé Tiểu Quả để diệt khẩu. Để cứu đứa trẻ đã cưu mang mình, Tô Khất Nhi dần thức tỉnh bản ngã, phá tan âm mưu thâm độc của Thiên Môn Giáo và cuối cùng phối hợp cùng quan phủ để quét sạch giáo phái tà ác này.</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Ngu Tư","avatar":""},{"name":"Quách Mộ Hàm","avatar":""},{"name":"Trình Đào","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Crazy Beggar SuQiEr","疯魔神丐苏乞儿"]', 1784690324330);
