INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phong-ma-than-cai-to-khat-nhi', 'Phong Ma Thần: Cái Tô Khất Nhi', 'Crazy Beggar SuQiEr', 'phong ma thần: cái tô khất nhi crazy beggar suqier bành ngu tư quách mộ hàm trình đào crazy beggar suqier 疯魔神丐苏乞儿', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-loi-o-khach-san-tinh-yeu', 'Lạc Lối Ở Khách Sạn Tình Yêu', 'Lost Girls & Love Hotels', 'https://phimimg.com/upload/vod/20260307-1/6267269ed5097c233260dc6547788b13.jpg', 'https://phimimg.com/upload/vod/20260307-1/a633713248aa350064afd2188ee8de5b.jpg', '<p>Bị ám ảnh bởi quá khứ của mình, một giáo viên tiếng Anh người Mỹ bắt đầu một cuộc tình đầy biến động với một trùm xã hội đen yakuza ở Tokyo. Margaret lạc trong mê cung lấp lánh của Tokyo vào ban đêm và là một giáo viên tiếng Anh được kính trọng của học viện tiếp viên hàng không Nhật Bản vào ban ngày. Không có hướng đi rõ ràng, cô tìm kiếm ý nghĩa cuộc sống với cô bạn trong một quán bar, uống rượu để quên và đánh mất bản thân trong những cuộc gặp gỡ trong khách sạn tình yêu với những người đàn ông thỏa mãn cơn thèm khát thoáng qua. Khi cô gặp Kazu, một yakuza bảnh bao, cô đã yêu anh ấy bất chấp nguy hiểm và truyền thống cản trở cơ hội ở bên nhau của họ. Chúng ta sẽ theo dõi cô ấy qua bóng tối và ánh sáng của tình yêu và ý nghĩa của việc tìm thấy chính mình ở nước ngoài với một sự bỏ rơi tuổi trẻ.</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alexandra Daddario","avatar":""},{"name":"Takehiro Hira","avatar":""},{"name":"Carice van Houten","avatar":""},{"name":"Dasha Teranishi","avatar":""},{"name":"Mariko Tsutsui","avatar":""},{"name":"Anastasia Nasu","avatar":""},{"name":"Andrew Rothney","avatar":""},{"name":"Elisabeth Larena","avatar":""},{"name":"Asuka Kurosawa","avatar":""},{"name":"Kate Easton","avatar":""},{"name":"Niclas Ericsson","avatar":""},{"name":"Haruka Imou","avatar":""},{"name":"Eri Ishida","avatar":""},{"name":"Kenji Isomura","avatar":""},{"name":"Misuzu Kanno","avatar":""},{"name":"Peter Mark Kendall","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["I Am Not a Bird","Загублені дівчата та готелі кохання","Lost Girls And Love Hotels","Garotas Perdidas e Motéis","Lost Girls & Love Hotels"]', 1784690324330);
