INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-toi-chet-ca-roi-wszyscy-moi-przyjaciele-nie-yj', 'Bạn Tôi Chết Cả Rồi (Wszyscy moi przyjaciele nie żyją)', 'All My Friends Are Dead', 'bạn tôi chết cả rồi (wszyscy moi przyjaciele nie żyją) all my friends are dead julia wieniawa mateusz więcławek adam woronowicz monika krzywkowska paulina gałązka aleksandra pisula adam turczyk nikodem rozbicki katarzyna chojnacka konrad żygadło bartłomiej firlet yassine fadel barbara garstka michał meyer szymon roszak all my friends are dead 我的朋友全掰了 все мои друзья мертвы bütün arkadaşlarım öldü tous mes amis sont morts todos os meus amigos estão mortos meine freunde sind alle tot όλοι οι φίλοι μου είναι νεκροί a barátaim mind halottak todos mis amigos están muertos vennene mine er døde toți prietenii mei au murit 我的朋友都挂了 wszyscy moi przyjaciele nie żyją', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-tuyet-dai-song-kieu-tan-tuyet-dai-song-kieu', 'Tân Tuyệt Đại Song Kiều (Tân Tuyệt Đại Song Kiêu)', 'Handsome Siblings', 'https://phimimg.com/upload/vod/20241111-1/2fc20579f2f4139d3470072e2fea082c.jpg', 'https://phimimg.com/upload/vod/20241111-1/e0b05f46746f3b4e6002fac078bc7254.jpg', '<p>Tân Tuyệt Đại Song Kiêu kể về câu chuyện tự xưng là “Thiên hạ đệ nhất ác ma”, Giang Tiểu Ngư từ nhỏ đã sống ở Thung lũng ác ma, dưới sự nuôi dưỡng 10 ác ma và Lý Đại Chủy, cả ngày giở trò, miệng lưỡi giảo hoạt, nhưng tâm địa lương thiện, thuần khiết, đáng yêu. Tiểu Ngư Nhi hành tẩu giang hồ, cùng với Hoa Vô Khuyết anh khí bừng bừng, không đánh không quen biết. Khi mối quan hệ thâm sâu hơn, Tiểu Ngư Nhi và Hoa Vô Khuyết từ kẻ thù trở thành bằng hữu.</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 18, 2020, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Nhất Thiên","avatar":""},{"name":"Trần Triết Viễn","avatar":""},{"name":"Lương Khiết","avatar":""},{"name":"Lý Nghệ Đồng","avatar":""},{"name":"La Gia Lương","avatar":""},{"name":"Mao Lâm Lâm","avatar":""},{"name":"Trịnh Gia Dĩnh","avatar":""},{"name":"Mạnh Lệ","avatar":""},{"name":"Vương Trí Văn","avatar":""},{"name":"Cốc Đức Chiêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["절대쌍교","绝代双骄"]', 1784690324330);
