INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-dau-phan-1', 'Phấn Đấu (Phần 1)', 'Industry (Season 1)', 'https://phimimg.com/upload/vod/20260210-1/275829b3a6fc13a7a8314e033e3feef8.jpg', 'https://phimimg.com/upload/vod/20260210-1/fcf1ae86e9511dec9c1fb46e41bb7f79.jpg', '<p>Trong thế giới khốc liệt của tài chính quốc tế, một nhóm sinh viên mới tốt nghiệp cùng nhau cạnh tranh cho một số lượng giới hạn các vị trí chính thức tại một ngân hàng đầu tư hàng đầu ở London. Ranh giới giữa đồng nghiệp, bạn bè, người tình và kẻ thù sớm trở nên mờ nhạt khi họ đắm mình vào một văn hóa công ty được định nghĩa bởi tình dục, ma túy và cái tôi cá nhân cũng nhiều như bởi các thương vụ và cổ tức.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2020, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Myha''la","avatar":""},{"name":"Marisa Abela","avatar":""},{"name":"Ken Leung","avatar":""},{"name":"Kit Harington","avatar":""},{"name":"Max Minghella","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Miriam Petche","avatar":""},{"name":"Toheeb Jimoh","avatar":""},{"name":"Charlie Heaton","avatar":""},{"name":"Sagar Radia","avatar":""},{"name":"Kal Penn","avatar":""},{"name":"Amy James-Kelly","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["投行风云","投行迷情","金融业实录","金融围城","Industry"]', 1784690324330);
