INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('carmen-sandiego-trom-hay-khong-trom', 'Carmen Sandiego: Trộm Hay Không Trộm', 'Carmen Sandiego: To Steal Or Not To Steal', 'https://phimimg.com/upload/vod/20260125-1/76c55ba4f41191b6da360cbb522fc955.jpg', 'https://phimimg.com/upload/vod/20260125-1/576b2017962da33051a26e75bf37939f.jpg', '<p>Bạn là người điều khiển trong cuộc phiêu lưu tương tác này. Hãy giúp Carmen giải cứu Ivy và Zack khi họ bị VILE bắt giữ trong một vụ cướp ở Thượng Hải.</p>', 'Full', 1, 'single', 'completed', 21, 2020, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Gina Rodriguez","avatar":""},{"name":"Finn Wolfhard","avatar":""},{"name":"Abby Trott","avatar":""},{"name":"Micheal Hawley","avatar":""},{"name":"Liam O''Brien","avatar":""},{"name":"Mary Elizabeth McGlynn","avatar":""},{"name":"Toks Olagundoye","avatar":""},{"name":"Sharon Muthu","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Andrew Pifko","avatar":""},{"name":"Bernardo de Paula","avatar":""},{"name":"Kimiko Glenn","avatar":""},{"name":"Charlet Chung","avatar":""},{"name":"Dawnn Lewis","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Carmen Sandiego: To Steal or Not to Steal"]', 1784690324330);
