INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiec-trang-mau', 'Tiệc Trăng Máu', 'Blood Moon Party', 'https://phimimg.com/upload/vod/20260123-1/a99ede8e342b97387a282cffd66746ae.jpg', 'https://phimimg.com/upload/vod/20260123-1/978e6060f811ed9903c2c1e2f9b6f4f0.jpg', '<p>Trong buổi họp mặt của nhóm bạn thân, một thành viên bất ngờ đề xuất trò chơi chia sẻ điện thoại nhằm tăng tinh thần “đoàn kết”. Từ đó, những góc khuất của từng người dần hé lộ và khiến cho mối quan hệ vốn khắng khít của họ bắt đầu lay chuyển.</p>', 'Full', 1, 'single', 'completed', 26, 2020, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Thái Hòa","avatar":""},{"name":"Hồng Ánh","avatar":""},{"name":"Hứa Vĩ Văn","avatar":""},{"name":"Thu Trang","avatar":""},{"name":"Kiều Minh Tuấn","avatar":""},{"name":"Kaity Nguyễn","avatar":""},{"name":"Đức Thịnh","avatar":""},{"name":"Việt Linh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tiệc Trăng Máu"]', 1784690324330);
