INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xu-so-alice', 'Xứ Sở Alice', 'Alice', 'https://phimimg.com/upload/vod/20260122-1/78889c99fc15cbc40b7dd456b046d76d.jpg', 'https://phimimg.com/upload/vod/20260122-1/dea25724c584ed0d1c47f5c5da40ce4a.jpg', '<p>Alice bắt đầu với sự u ám của cái chết, khiến hai người hoàn toàn phải chia xa mãi mãi trước khi được gặp lại nhau lần nữa như phép màu. Park Jin Gyum (Joo Won) là một thanh tra không bao giờ thể hiện cảm xúc, luôn giữ trong mình ý định sẽ trả thù cho cái chết tức tưởi của mẹ. Khi điều tra cho một vụ án bí ẩn, anh đã nhận ra sự tồn tại của những người du hành thời gian. Họ đến từ tương lai thông qua một không gian vũ trụ được gọi là Alice. Dần dần, anh trở thành người ngăn chặn những điều tiêu cực xảy ra thông qua nơi này.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 15, 2020, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hee-seon","avatar":""},{"name":"Joo Won","avatar":""},{"name":"Kwak Si-yang","avatar":""},{"name":"Choi Won-young","avatar":""},{"name":"Lee Da-in","avatar":""},{"name":"Yeon Woo","avatar":""},{"name":"Bae Hae-seon","avatar":""},{"name":"Lim Jae-hyeok","avatar":""},{"name":"Song Ji-hyuk","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Alice","Aelliseu","호텔 앨리스","愛麗絲Alice","我的愛麗絲","Hotel Alice","앨리스"]', 1784690324330);
