INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xu-so-alice', 'Xứ Sở Alice', 'Alice', 'xứ sở alice alice kim hee-seon joo won kwak si-yang choi won-young lee da-in yeon woo bae hae-seon lim jae-hyeok song ji-hyuk alice aelliseu 호텔 앨리스 愛麗絲alice 我的愛麗絲 hotel alice 앨리스', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-chung-rac-roi', 'Nhân Chứng Rắc Rối', 'The Witness', 'https://phimimg.com/upload/vod/20250602-1/8ac29d0ffdcdb424bfac7d0b2a50d536.jpg', 'https://phimimg.com/upload/vod/20250602-1/2a0665927dc2316bdf41f094bb36ddfd.jpg', '<p>Là người duy nhất nhìn thấy dung mạo kẻ giết người trong trận truy quét mại dâm của cảnh sát, Lý Hạo Phàm trở thành nhân chứng cực kỳ quan trọng. Trớ trêu thay, Phàm không những khờ khạo, mà còn bị mất trí nhớ tạm thời, khiến các trinh sát rất mực đau đầu, không biết phải tra án từ đâu. Điều tra viên hạng bét – Cao Lực Cơ, muốn thừa cơ hội này, nhận nhiệm vụ bảo vệ Phàm để lập công. Nhưng lối làm việc tự tung tự tác của anh đã gây xích mích với em gái Phàm, là Lý Tụng Doanh. Chị gái Cơ – Cao Vịnh Âm, quá lứa lỡ thì, lại nghĩ Phàm là nhân duyên của mình, ra sức tán tỉnh anh. Tuy nhiên, Phàm có một tình cảm đặc biệt đối với Cơ. Ở bên cạnh Cơ, Phàm bỏ qua hết bản tính cố chấp, khó chịu, sạch sẽ tới mức cực đoan. Dần dần, họ trở thành “cặp bài trùng”, bù trừ khuyết điểm cho nhau, cùng lật mặt hung thủ. Nhưng cả Phàm và Cơ đều không thể ngờ, cuộc gặp gỡ của 4 anh chị em không phải do tình cờ, mà có liên quan đến vụ án treo hơn 20 năm trước</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 18, 2020, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"La Trọng Khiêm","avatar":""},{"name":"Trương Hy Văn","avatar":""},{"name":"Vy Gia Hùng","avatar":""},{"name":"Từ Vinh","avatar":""},{"name":"Trương Văn Từ","avatar":""},{"name":"Lưu Giang","avatar":""},{"name":"Trương Tú Văn","avatar":""},{"name":"Huỳnh Tử Duy","avatar":""},{"name":"Thái Khải Duy","avatar":""},{"name":"Viên Khiết Nghi","avatar":""},{"name":"Thang Tuấn Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["木棘証人","The Witness"]', 1784690324330);
