INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dac-nhiem-shield-phan-7', 'Đội Đặc Nhiệm SHIELD (Phần 7)', 'Marvel''s Agents Of S.H.I.E.L.D. (Season 7)', 'https://phimimg.com/upload/vod/20260119-1/3352657232c568805c3b93f0fc8b695f.jpg', 'https://phimimg.com/upload/vod/20260119-1/6875c96f5ff9937efa8de85b506bb655.jpg', '<p>Phil Coulson (Clark Gregg, lặp lại vai trò của mình từ &quot;The Avengers&quot; và &quot;Người sắt&quot;) đứng đầu một nhóm đặc vụ tinh nhuệ với tổ chức thực thi pháp luật trên toàn thế giới được gọi là SHIELD (Phòng Hậu cần và Thi hành Can thiệp Chiến lược Quê hương) sự xuất hiện kỳ lạ trên toàn cầu. Các thành viên của nhóm - mỗi người mang một đặc sản cho nhóm - làm việc với Coulson để bảo vệ những người không thể tự bảo vệ mình khỏi các mối đe dọa phi thường và không thể tưởng tượng được, bao gồm một nhóm đáng gờm được gọi là Hydra.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 17, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Clark Gregg","avatar":""},{"name":"Chloe Bennet","avatar":""},{"name":"Elizabeth Henstridge","avatar":""},{"name":"Ming-Na Wen","avatar":""},{"name":"Henry Simmons","avatar":""},{"name":"Natalia Cordova-Buckley","avatar":""},{"name":"Jeff Ward","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Marvel''s Agentes da S.H.I.E.L.D.","Agentes da SHIELD da Marvel","神盾