INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-vo-hinh', 'Kẻ Vô Hình', 'The Invisible Man', 'https://phimimg.com/upload/vod/20260115-1/28921720b813981570673c27787cb542.jpg', 'https://phimimg.com/upload/vod/20260115-1/79d11a5400d6e7756b0973adc0039797.jpg', '<p>Bị kẹt trong một mối quan hệ bạo lực và kiểm soát với một nhà khoa học giàu có và thông minh, Cecilia Kass chạy trốn vào nửa đêm cùng với sự giúp đỡ của người thân. Nhưng khi người yêu cũ của Cecilia tự vẫn và để lại khối tài sản lớn cho cô, Cecilia nghi ngờ cái chết của anh ta không có thật. Một loạt các sự kiện trùng hợp chết người diễn ra, đe dọa mạng sống bản thân cô và những người xung quanh - Những gì bạn không thấy có thể làm hại bạn.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Úc', 1, '[{"name":"Elisabeth Moss","avatar":""},{"name":"Aldis Hodge","avatar":""},{"name":"Storm Reid","avatar":""},{"name":"Michael Dorman","avatar":""},{"name":"Harriet Dyer","avatar":""},{"name":"Oliver Jackson-Cohen","avatar":""},{"name":"Benedict Hardie","avatar":""},{"name":"Zara Michales","avatar":""},{"name":"Renee Lim","avatar":""},{"name":"Sam Smith","avatar":""},{"name":"Nick Kici","avatar":""},{"name":"Vivienne Greer","avatar":""},{"name":"Anthony Brandon Wong","avatar":""},{"name":"Serag Mohammed","avatar":""},{"name":"Nash Edgerton","avatar":""},{"name":"Nicholas Hope","avatar":""},{"name":"Cardwell Lync","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Bilti Nir''eh","Ο ΑΟΡΑΤΟΣ ΑΝΘΡΩΠΟΣ - The Invisible Man","มนุษย์ล่องหน","Invisible Man","L''homme invisible","האיש הבלתי נראה","透明人間：2020","El hombre invisible","Görünməz Adam","The Invisible Man"]', 1784690324330);
