INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-vo-hinh', 'Kẻ Vô Hình', 'The Invisible Man', 'kẻ vô hình the invisible man elisabeth moss aldis hodge storm reid michael dorman harriet dyer oliver jackson-cohen benedict hardie zara michales renee lim sam smith nick kici vivienne greer anthony brandon wong serag mohammed nash edgerton nicholas hope cardwell lync bilti nir''eh ο αορατος ανθρωπος - the invisible man มนุษย์ล่องหน invisible man l''homme invisible האיש הבלתי נראה 透明人間：2020 el hombre invisible görünməz adam the invisible man', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-ma-nha-xi-hanako-phan-1', 'Cậu Ma Nhà Xí Hanako (Phần 1)', 'Toilet-Bound Hanako-kun (Season 1)', 'https://phimimg.com/upload/vod/20260114-1/240a9b9e90a5dd1de9293e23a3a59ea9.jpg', 'https://phimimg.com/upload/vod/20260114-1/cdb7c964e4b5fa154e1b7f5c2caeb94d.jpg', '<p>Bảy điều kỳ bí vốn dĩ luôn tồn tại trong mọi ngôi trường là một phần không thể thiếu trong các truyền thuyết đô thị Nhật Bản. Một trong những câu chuyện nổi tiếng nhất chính là về Hanako-san: hồn ma của một cô bé thường ám trong các nhà vệ sinh của trường học.Học viện Kamome cũng sở hữu phiên bản huyền thoại Hanako-san của riêng mình. Lời đồn cho rằng nếu ai đó triệu hồi thành công Hanako-san, thực thể này sẽ ban cho người đó bất kỳ điều ước nào. Bị lôi cuốn bởi lời đồn thổi, nhiều người đã thử gọi hồn cô bé, nhưng mọi nỗ lực đều thất bại. Tuy nhiên, khi Nene Yashiro — một cô gái đang khao khát có được vận may trong tình yêu — đánh liều triệu hồi Hanako-san, cô bàng hoàng phát hiện ra &#39;cô bé&#39; trong lời đồn thực chất lại là một cậu bé!Sau một loạt các sự kiện không may liên quan đến ước nguyện tình cảm của mình, Yashiro vô tình bị kéo vào thế giới siêu nhiên và trở thành trợ lý của Hanako-kun. Sớm thôi, cô cũng khám phá ra nhiệm vụ ít người biết tới của cậu: duy trì sự cân bằng mong manh giữa thế giới loài người và các linh hồn.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 12, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Megumi Ogata","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Shoya Chiba","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Takahiro Mizushima","avatar":""},{"name":"Chika Anzai","avatar":""},{"name":"Chitose Morinaga","avatar":""},{"name":"Megumi Ogata","avatar":""},{"name":"Shunichi Toki","avatar":""},{"name":"Yukana","avatar":""},{"name":"Yu-ri Yoshida","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Hanako-kun: El fantasma del lavabo","Jibaku Shounen Hanako-kun","Jibaku Shōnen Hanako-kun","地縛少年花子くん２","Hanako, duch ze szkolnej toalety","ฮานาโกะคุง วิญญาณติดที่","Туалетний хлопчина Ханако","地縛少年花子くん"]', 1784690324330);
