INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-ma-nha-xi-hanako-phan-1', 'Cậu Ma Nhà Xí Hanako (Phần 1)', 'Toilet-Bound Hanako-kun (Season 1)', 'cậu ma nhà xí hanako (phần 1) toilet-bound hanako-kun (season 1) megumi ogata akari kito shoya chiba yuma uchida takahiro mizushima chika anzai chitose morinaga megumi ogata shunichi toki yukana yu-ri yoshida hanako-kun: el fantasma del lavabo jibaku shounen hanako-kun jibaku shōnen hanako-kun 地縛少年花子くん２ hanako, duch ze szkolnej toalety ฮานาโกะคุง วิญญาณติดที่ туалетний хлопчина ханако 地縛少年花子くん', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-an-rong-thieng-ban-2020', 'Dấu Ấn Rồng Thiêng (Bản 2020)', 'Dragon Quest: The Adventure Of Dai', 'https://phimimg.com/upload/vod/20260111-1/c842c81a6d0936edf9faae4a64d1cdeb.jpg', 'https://phimimg.com/upload/vod/20260111-1/fbda001ceef9f83a298f51a84705adc4.jpg', '<p>Câu chuyện kể rằng, sau khi ma vương Hadlar bị đánh bại, những con quái vật được giải thoát khỏi hắn bắt đầu dời đến hòn đảo Delmurin để sinh sống trong hòa bình. Dai là cậu bé loài người duy nhất sống trên hòn đảo đó. Cậu được nuôi dưỡng bởi một quái vật tốt bụng Brass và luôn nuôi dưỡng ước mơ trở thành một anh hùng. Khi Hadlar được hồi sinh, Avan là một anh hùng kì cựu trước đó đã đến để huấn luyện cho Dai cho cuộc chiến sắp tới. Nhưng Hadlar sau khi hồi sinh đã trở nên mạnh hơn trước gấp bội, hắn tìm đến giết Avan. Để cứu những đồ đệ của mình, Avan đã sử dụng thần chú Self-Sacrifice nhưng không đủ để đánh bại Hadlar. Khi mọi Dai và đồng môn Pop của mình tưởng chừng như sắp tiêu đời, một dấu ấn xuất hiện trên trán của Dai, sức mạnh của cậu bỗng nhiên gia tăng bất ngờ, cuối cùng họ đã có thể chống lại Hadlar. Từ đó, hai người họ bắt đầu cuộc hành trình báo thù cho sư phụ Avan và mang lại hòa bình cho thế gian.</p>', 'Hoàn Tất (100/100)', 100, 'hoathinh', 'completed', 13, 2020, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Atsumi Tanezaki","avatar":""},{"name":"Toshiyuki Toyonaga","avatar":""},{"name":"Mikako Komatsu","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Ai Furihata","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Toru Nara","avatar":""},{"name":"Show Hayami","avatar":""},{"name":"Takaya Hashi","avatar":""},{"name":"Tomoaki Maeno","avatar":""},{"name":"Mitsuo Iwata","avatar":""},{"name":"Hiroshi Iwasaki","avatar":""},{"name":"Hiro Shimono","avatar":""},{"name":"Y","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["勇者鬥惡龍 達伊的大冒險","Dragon Quest: Dai no Daibōken","dragon-quest-the-adventure-of-dai","ドラゴンクエスト・ダイの大冒険 (2020)","Dragon Quest: Dai no Daibouken","드래곤 퀘스트: 타이의 대모험","DRAGON QUEST: ไดตะลุยแดนเวทมนตร์","Dragon Quest: Dai''s Great Adventure","Dragon Quest: Adventure of Dai (2020)","Dấu Ấn Rồng Thiêng","ドラゴンクエスト ダイの大冒険"]', 1784690324330);
