INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-sot-2020', 'Sống Sót (Tôi còn sống)', '#Alive', 'https://phimimg.com/upload/vod/20260112-1/6ce48ae4886bf201ba26211b6df4545a.jpg', 'https://phimimg.com/upload/vod/20260112-1/dae5bcc7870273f3ddb6ac228e2f7497.jpg', '<p>Bộ phim kể về câu chuyện liên quan đến những người sống sót bị cô lập của một thành phố đang bị phong tỏa, cách ly do hậu quả của sự lây nhiễm bất ngờ của một dịch bệnh không rõ nguồn gốc. Yoo Ah-in sẽ vào vai Joon Woon, một game thủ sống sót và bị ngắt kết nối với phần còn lại của thế giới. Park Shin-hye đảm nhận vai Yoo Bin, một người sống sót khác dựa vào kỹ năng sinh tồn của chính cô trong tình huống vô cùng khó khăn trong thành phố.</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Ah-in","avatar":""},{"name":"Park Shin-hye","avatar":""},{"name":"Lee Hyun-wook","avatar":""},{"name":"Jin So-yeon","avatar":""},{"name":"Kim Hak-seon","avatar":""},{"name":"So Hee-jung","avatar":""},{"name":"Joo Bo-bi","avatar":""},{"name":"Jeon Bae-soo","avatar":""},{"name":"Lee Chae-kyung","avatar":""},{"name":"Oh Hye-won","avatar":""},{"name":"Jeon Woon-jong","avatar":""},{"name":"Son Kyoung-won","avatar":""},{"name":"Lee Kyu-ho","avatar":""},{"name":"Jang Ji-gun","avatar":""},{"name":"Yoo Yeon","avatar":""},{"name":"Jang Ui-don","avatar":""},{"name":"Kim Hyun-woo","avatar":""},{"name":"Lee Seung-jin","avatar":""},{"name":"Yang Mal-bok","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1