INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vuong-trieu-cuoi-cung-phan-4', 'Vương Triều Cuối Cùng (Phần 4)', 'The Last Kingdom (Season 4)', 'vương triều cuối cùng (phần 4) the last kingdom (season 4) alexander dreymon emily cox eliza butterworth mark rowley ruby hartley cavan clerkin arnas fedaravičius harry gilby timothy innes stefanie martini phia saban adrian schiller sonuncu krallıq последното кралство o último reino 孤国春秋 最后的王国 το τελευταίο βασίλειο 最後的王國 posljednje kraljevstvo az utolsó királyság آخرین پادشاهی ラスト・キングダム 라스트 킹덤 paskutinioji karalystė det siste kongeriket upadek królestwa poslednje kraljevstvo последнее королевство المملكة الأخيرة posledné kráľovstvo son krallık останнє королівство vương triều cuối cùng the last kingdom', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tehran-phan-1', 'Tehran (Phần 1)', 'Tehran (Season 1)', 'https://phimimg.com/upload/vod/20260111-1/0573e87ace0eb63827a17443c62b1252.jpg', 'https://phimimg.com/upload/vod/20260111-1/6c0d73b5210dbbd84a5d06acb908cf0b.jpg', '<p>Tamar, điệp viên hacker của Mossad, thâm nhập vào Tehran bằng danh tính giả để giúp phá huỷ lò phản ứng hạt nhân của Iran. Nhưng khi nhiệm vụ của cô thất bại, Tamar phải lên kế hoạch một chiến dịch làm tất cả những người cô yêu quý lâm nguy.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 12, 2020, 'Vietsub', 'FHD', 'Greece', 0, '[{"name":"Niv Sultan","avatar":""},{"name":"Shaun Toub","avatar":""},{"name":"Shervin Alenabi","avatar":""},{"name":"Hugh Laurie","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Tehran","Teherán","Téhéran","Тегеран","טהרן"]', 1784690324330);
