INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-nhan-chi-ha-phan-3-nguoi-tren-van-nguoi', 'Nhất Nhân Chi Hạ (Phần 3) (Người Trên Vạn Người)', 'The Outcast (Season 3) (Hitori No Shita)', 'https://phimimg.com/upload/vod/20260110-1/3b2e89cd7fcfd6fcf343ac6e9d3ea27d.jpg', 'https://phimimg.com/upload/vod/20260110-1/1884d08e96cb73df6d0b6d412235e037.jpg', '<p>Sau Thiên La Đại Tiếu, Vương Dã bị Võ Đang gạch tên ( bị đuổi ) quay về nhà. Lại vì thân mang “ bát kỳ kỹ- Phong Hậu Kỳ Môn” bị người ta nhắm phải, người nhà bị theo dõi. Vương Dã vô cùng bế tắc, dưới kiến nghị của bạn thân Gia Cát Thanh xin công ty “Đâu Cũng Được” giúp đỡ. Trương Sở Lam cùng Phùng Bảo Bảo đến đó phá án. Trương Sở Lam thể hiện thân thủ ra sao để giúp Vương Dã bắt kẻ chủ mưu? Gia Cát Thanh và Vương Dã sẽ có những biểu hiện đặc sắc thế nào? Kẻ muốn cướp “ bát kỳ kỹ” rốt cuộc là ai?</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 12, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Liansha","avatar":""},{"name":"Sheng Feng","avatar":""},{"name":"Yuntu Cao","avatar":""},{"name":"Shan Xin","avatar":""},{"name":"Ajie","avatar":""},{"name":"Wang Chenguang","avatar":""},{"name":"Baomu Zhongyang","avatar":""},{"name":"Teng Xin","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一人之下","Fengqi Yunyong, Luotian Dajiao","异人","Yi Ren Zhi Xia","Yi Ren Zhixia","Hitori no Shita – The Outcast","hitorinoshita - The Outcast","Hitori no Shita","一人の下","一人之下 THE OUTCAST","일인지하 The Outcast","Один из отвергнутых: Изгой","Under One Person","The Outcast","The.OutCast"]', 1784690324330);
