INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-lun-tinh-nghich-chuyen-luu-dien-the-gioi', 'Quỷ Lùn Tinh Nghịch: Chuyến Lưu Diễn Thế Giới', 'Trolls World Tour', 'https://phimimg.com/upload/vod/20260105-1/d080cfe689a89e350947dc29d9aee255.jpg', 'https://phimimg.com/upload/vod/20260105-1/474a17d767aa4b5b1f14cba589ceadf5.jpg', '<p>Trolls World Tour sẽ mở ra một cuộc phiêu lưu mà các nhân vật của chúng ta chưa bao giờ tưởng tượng đến trước đó. Lần này, Poppy và Branch nhận ra rằng có đến sáu bộ lạc Troll đang sinh sống ở những vùng đất khác nhau, và họ đều chỉ chuyên chú vào một thể loại nhạc duy nhất: Funk, Country, Techno, Classical, Pop và Rock. Thế giới của họ giờ đây trở nên rộng lớn hơn, nhưng cũng chính vì vậy mà nhiều rắc rối họ không lường trước được cũng xảy đến.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2020, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Anna Kendrick","avatar":""},{"name":"Justin Timberlake","avatar":""},{"name":"Ron Funches","avatar":""},{"name":"Rachel Bloom","avatar":""},{"name":"James Corden","avatar":""},{"name":"Kelly Clarkson","avatar":""},{"name":"Anderson .Paak","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"George Clinton","avatar":""},{"name":"Mary J. Blige","avatar":""},{"name":"Kenan Thompson","avatar":""},{"name":"Kunal Nayyar","avatar":""},{"name":"Caroline Hjelt","avatar":""},{"name":"Aino Jawo","avatar":""},{"name":"J Balvin","avatar":""},{"name":"Flula Borg","avatar":""},{"name":"Ester Dean","avatar":""},{"name":"Jamie Dornan","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"