INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-cuu-ho-khan-cap', 'Đội Cứu Hộ Khẩn Cấp', 'The Rescue', 'https://phimimg.com/upload/vod/20260105-1/8631ab811a5c08274cb59cff3cccbe0d.jpg', 'https://phimimg.com/upload/vod/20260105-1/926cb8ecd6d576491dfea3bebcd20b3a.jpg', '<p>Sân thượng của giàn khoan đổ nghiêng, xe bồn chở dầu chảy xuôi dòng, phi cơ chở đành hành khách lao thẳng xuống biển. Đội trưởng đội cứu hộ trên không Cao Khiêm, cơ trưởng Phương Vũ Lăng, cùng tay trục kéo Triệu Trình lần lượt dẫn đội ra tiền tuyền, đứng đầu trước nước lửa gầm thét, canh giữ nơi nguy cấp và rút lui sau cùng, dùng tính mạng để chống lại thiên tai nhân họa.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Eddie Peng Yu-Yan","avatar":""},{"name":"Wang Yanlin","avatar":""},{"name":"Xin Zhilei","avatar":""},{"name":"Lyric Lan","avatar":""},{"name":"Yutian Wang","avatar":""},{"name":"Carlos Chan","avatar":""},{"name":"Li Mincheng","avatar":""},{"name":"Zhang Guoqiang","avatar":""},{"name":"Guo Xiaodong","avatar":""},{"name":"Wei Daxun","avatar":""},{"name":"Zhang Feng","avatar":""},{"name":"Will Tomi","avatar":""},{"name":"Liu Yichun","avatar":""},{"name":"Shang Bai","avatar":""},{"name":"Jingyi Zhang","avatar":""},{"name":"Zhang Jingyi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["The Rescue","The Rescue HK","Emergency Rescue Aid","Desastre Inminente","紧急救援"]', 1784690324330);
