INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hong-quyen', 'Hồng Quyền', 'Hong Boxing', 'https://phimimg.com/upload/vod/20251225-1/f63e34fffd2fb3a04a7b92e674c3d615.jpg', 'https://phimimg.com/upload/vod/20251225-1/6a0be99abff68cce5e7df8ef56139764.jpg', '<p>Vào những năm cuối đời nhà Thanh, Lâm Thế Vinh – một chàng trai bán thịt lợn đã bái Hoàng Phi Hồng-tông sư của Hồng Gia Quyền làm thầy, hành hiệp trượng nghĩa. Nhưng lại bị những kẻ bại hoại võ lâm là Thái Tiến Bảo và Mâu Thành Uy liên thủ hãm hại, bị ép vào bước đường cùng. Đối diện với bước đường cùng nhưng chàng vẫn không hề bỏ cuộc, tự lập tự cường. Cuối cùng đánh bại được kẻ địch mạnh, đòi lại sự trong sạch. Đồng thời phổ cập Hồng Gia Quyền tới mọi người, trở thành Nhất đại tông sư.</p>', 'Full', 1, 'single', 'completed', 32, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Mạnh Phi","avatar":""},{"name":"Vương Dục Hàm","avatar":""},{"name":"Lý Trung Hoa","avatar":""},{"name":"Lỗ Diên Đoàn","avatar":""},{"name":"Đặng Vĩ","avatar":""},{"name":"Đỗ Nhất Cương","avatar":""},{"name":"Lỗ Quốc Đông","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["百家拳之洪拳"]', 1784690324330);
