INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-huy-diet', 'Cuộc Chiến Hủy Diệt', 'Skylines', 'https://phimimg.com/upload/vod/20251222-1/9b87f1d132f5a1c29224f501153c3e0a.jpg', 'https://phimimg.com/upload/vod/20251222-1/64453b2cebd83128346aa98ef97095c2.jpg', '<p>SKYLIN3S - phim hành động giả tưởng, xoay quanh cuộc xâm lăng Trái Đất của một chủng tộc người ngoài hành tinh. 15 năm sau kết thúc của phần hai, một loại virus mới đã xuất hiện và xâm nhập vào những người ngoài hành tinh đang sinh sống trên Trái Đất. Loại virus này khiến những sinh vật từ thân thiện trở nên hung hãn và chống lại con người. Đội trưởng Rose Corley phải lãnh đạo một đội lính đánh thuê tinh thuệ, tham gia nhiệm vụ đến thế giới ngoài hành tinh để cứu những gì còn lại của nhân loại.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Lindsey Morgan","avatar":""},{"name":"Alexander Siddig","avatar":""},{"name":"Rhona Mitra","avatar":""},{"name":"Daniel Bernhardt","avatar":""},{"name":"Yayan Ruhian","avatar":""},{"name":"James Cosmo","avatar":""},{"name":"Jonathan Howard","avatar":""},{"name":"Ieva Andrejevaitė","avatar":""},{"name":"Samantha Jean","avatar":""},{"name":"Giedrė Mockeliūnaitė","avatar":""},{"name":"Jeremy Fitzgerald","avatar":""},{"name":"Yoon Cha-Lee","avatar":""},{"name":"Naomi J. Ogawa","avatar":""},{"name":"Rokas Spanlinskas","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Skylin3s","스카이라인 3","天际浩劫3","Skyline 3 - Skylin3s"