INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-doc-trong-dem', 'Đơn Độc Trong đêm', 'Raat Akeli Hai', 'https://phimimg.com/upload/vod/20251222-1/a7497f6c72ced63cfca003709a7dd235.jpg', 'https://phimimg.com/upload/vod/20251222-1/8ed10a2d32edd318acbbaf4671e7e5fb.jpg', '<p><span style="text-wrap-mode: wrap;">Khi một chủ nhà mới cưới bị sát hại, cuộc điều tra của một cảnh sát lập dị trở nên phức tạp vì gia đình giấu nhiều bí mật của nạn nhân và trái tim mâu thuẫn của anh.</span></p>', 'Full', 1, 'single', 'completed', 21, 2020, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Nawazuddin Siddiqui","avatar":""},{"name":"Radhika Apte","avatar":""},{"name":"Padmavati Rao","avatar":""},{"name":"Shweta Tripathi Sharma","avatar":""},{"name":"Aditya Srivastava","avatar":""},{"name":"Nishant Dahiya","avatar":""},{"name":"Shivani Raghuvanshi","avatar":""},{"name":"Khalid Tyabji","avatar":""},{"name":"Tigmanshu Dhulia","avatar":""},{"name":"Ila Arun","avatar":""},{"name":"Swanand Kirkire","avatar":""},{"name":"Gyanendra Tripathi","avatar":""},{"name":"Shreedhar Dubey","avatar":""},{"name":"Riya Shukla","avatar":""},{"name":"Ravi Sah","avatar":""},{"name":"Balji","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["孤夜","रात अकेली है"]', 1784690324330);
