INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-ngam-2020', 'Điệp Viên Ngầm', 'Autumn Cicada', 'https://phimimg.com/upload/vod/20251220-1/309058e28f379b3168910b215bfce36b.jpg', 'https://phimimg.com/upload/vod/20251220-1/39d9c007ea08d7ab54094e981b7f507e.jpg', '<p>Phim lấy bối cảnh cuối năm 1941, thời điểm Hồng Kông bị quân đội Nhật Bản xâm chiếm. Diệp Xung, một đảng viên trẻ tuổi với mật danh Thu Thiền, nhận nhiệm vụ đặc biệt trở thành gián điệp tình báo cấp cao trà trộn vào quân đội Nhật nhằm cung cấp cho Đảng những thông tin chiến lược quan trọng.Tuy nhiên, quân đội Nhật vô cùng xảo quyệt và nghi ngờ, họ đã cô lập Diệp Xung khi phát hiện những dấu hiệu đáng ngờ. Dù đối mặt với nguy hiểm thường trực và áp lực từ kẻ thù, Diệp Xung không hề nao núng hay từ bỏ nhiệm vụ. Anh kiên cường tìm mọi cách để tiếp tục đưa tin tình báo về cho tổ chức, thể hiện tinh thần yêu nước và lòng trung thành tuyệt đối.</p>', 'Hoàn Tất (49/49)', 49, 'series', 'completed', 10, 2020, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Lý Mạn","avatar":""},{"name":"Lưu Hoàn","avatar":""},{"name":"Hà Đỗ Quyên","avatar":""},{"name":"Kiển Nhân Tử","avatar":""},{"name":"Lưu Tuệ Nghi","avatar":""},{"name":"Lương Kính Hiên","avatar":""},{"name":"Trương Kinh Tống","avatar":""},{"name":"Lý Tiểu Nhiên","avatar":""},{"name":"Hàn Đông","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["جیرجیرک های پاییزی","Cicada of Autumn","Autumn Cicada 2020","秋蝉"]', 1784690324330);
