INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-khuat-cua-bi-mat', 'Góc Khuất Của Bí Mật', 'The Bad Kids', 'https://phimimg.com/upload/vod/20241206-1/52cf6f577813efad985458438b79605f.jpg', 'https://phimimg.com/upload/vod/20241206-1/f6159baf78a6a5a8766c3734275f78cf.jpg', '<p>Góc Khuất Của Bí Mật kể về Trương Đông Thăng là giáo viên phương Bắc xuống ở rể ở phương Nam. Người vợ ngoại tình và muốn ly hôn, ngay cả cha mẹ vợ cũng khuyên anh ta nên buông tay. Trương Đông Thăng giả vờ mời bố mẹ vợ đi leo núi. Khi đến đỉnh núi, anh ta tìm cách đẩy họ xuống vực. Ba đứa trẻ Chu Triều Dương, Phổ Phổ, Đinh Hạo vô tình chứng kiến và quay lại cảnh Trương Đông Thăng giết cha mẹ vợ. Vì Phổ Phổ cần tiền để chữa bệnh cho em trai nên ba đứa trẻ lên kế hoạch tống tiền Trương Đông Thăng. Sau đó liên tục xảy ra nhiều cái chết bí ẩn. Chu Triều Dương là học sinh có thành tích học tập xuất sắc nhất toàn trường cấp 2. Mạch chuyện thêm kịch tính khi Chu Triều Dương vô tình ngộ sát em gái cùng cha khác mẹ, Phổ Phổ và Đinh Hạo chứng kiến sự việc. Sự việc đẩy đưa biến Chu Triều Dương trở thành Trương Đông Thăng thứ hai.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 13, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tần Hạo","avatar":""},{"name":"Vương Cảnh Xuân","avatar":""},{"name":"Vinh Tử Sâm","avatar":""},{"name":"Sử Bành Nguyên","avatar":""},{"name":"Vương Thánh Địch","avatar":""},{"name":"Trương Tụng Văn","avatar":""},{"name":"Lưu Lâm","avatar":""},{"name":"Lô Phương Sinh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","