INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cach-mang-tinh-yeu', 'Cách Mạng Tình Yêu', 'Love Revolution', 'https://phimimg.com/upload/vod/20251208-1/11b2dccc3598f2d966ade1260afd469e.jpg', 'https://phimimg.com/upload/vod/20251208-1/b78c8c0f218aaee87ea4f23375950258.jpg', '<p>Cách Mạng Tình Yêu kể về Gong Joo Yong quên ví tiền vào ngày đầu tiên đi học và không thể bắt xe buýt. Một nữ sinh giúp anh ta trả tiền vé xe lúc nguy cấp. Anh ta lập tức trúng tiếng sét ái tình với cô nhưng không được đáp lại dù cố gắng theo đuổi đến đâu. Dù vậy, Goo Joo Young vẫn không hề nản chí… Và một câu chuyện tình cảm hài hước mở ra!</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 13, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Ji-hoon","avatar":""},{"name":"Lee Ruby","avatar":""},{"name":"Younghoon","avatar":""},{"name":"Jeong Da-eun","avatar":""},{"name":"Dayoung","avatar":""},{"name":"Ko Chan-bin","avatar":""},{"name":"Ahn Do-gyu","avatar":""},{"name":"Kim Jung-don","avatar":""},{"name":"Yoon Seo-ah","avatar":""},{"name":"Kim Young-jae","avatar":""},{"name":"Kim Li-ye","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["연애혁명"]', 1784690324330);
