INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-quoc-xa-phan-1', 'Thợ Săn Quốc Xã (Phần 1)', 'Hunters (Season 1)', 'https://phimimg.com/upload/vod/20251207-1/4800146d0b8b330a1c4cb4120f5e2663.jpg', 'https://phimimg.com/upload/vod/20251207-1/76219a535d0ce4c63ced26c5ba6c2591.jpg', '<p>Tại thành phố New York năm 1977, một nhóm thợ săn Đức Quốc Xã đa chủng tộc phát hiện ra rằng hàng trăm quan chức cấp cao Đức Quốc Xã đang sống giữa chúng ta và âm mưu thành lập Đệ Tứ Đế Chế (Fourth Reich) tại Hoa Kỳ. Đội ngũ Thợ Săn khác biệt này bắt đầu một hành trình đẫm máu để đưa những tên Quốc Xã ra trước công lý và ngăn chặn kế hoạch diệt chủng mới của chúng.</p>', 'Full', 11, 'series', 'completed', 12, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Logan Lerman","avatar":""},{"name":"Jerrika Hinton","avatar":""},{"name":"Lena Olin","avatar":""},{"name":"Carol Kane","avatar":""},{"name":"Josh Radnor","avatar":""},{"name":"Greg Austin","avatar":""},{"name":"Kate Mulvany","avatar":""},{"name":"Tiffany Boone","avatar":""},{"name":"Louis Ozawa","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Al Pacino","avatar":""},{"name":"Emily Rudd","avatar":""},{"name":"Udo Kier","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["纳粹捕猎者","헌터스","Caçadores","Охота","นักล่านาซี","Nazi Avcıları","Hunters"]', 1784690324330);
