INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-tap-gia-nghiep', 'Bão Táp Gia Nghiệp', 'The Dripping Sauce', 'https://phimimg.com/upload/vod/20251124-1/f6311f9e68d2833760733c4556236b15.jpg', 'https://phimimg.com/upload/vod/20251124-1/855fddf7b38b46668b2fe7f778df87b6.jpg', '<p>Xưởng nước tương Vạn Quán Viên rất nổi tiếng ở Phật Sơn, từ lâu đã có quy định chỉ truyền nghề cho nam, không truyền cho nữ. Trước sức ép của gia tộc, người đứng đầu xưởng – Vạn Khải Sơn (do Ngô Đại Dung đóng), phải dùng chiêu &quot;trộm long tráo phụng&quot; để giữ quyền điều hành. Tuy nhiên, trong quá trình tráo hài nhi, con gái ruột của ông bị trôi sông, thất lạc. Cô bé bất hạnh đó phải lớn lên trong kỹ viện, lấy tên Hạ Tiểu Mãn (do Chu Thần Lệ đóng). Còn đứa con trai may mắn được Sơn nhận nuôi, đặt tên Vạn Trác Phong (do Hà Quảng Bái đóng), càng lớn càng lêu lỏng, không tha thiết với cơ nghiệp của gia đình.

Mãn có em gái kết nghĩa, là Diệp Tế Yêu (do Cung Gia Hân đóng). Hai người cùng nhau trốn khỏi kỹ viện, làm lụng chắt chiu, mong có được cửa tiệm của riêng mình. Cơ duyên run rủi, một lần nọ, Mãn và Yêu vô tình giúp Vạn Quán Viên vượt qua đại nạn. Ông Sơn đành phá lệ, nhận hai cô vào học nghề để trả ơn...</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 12, 2020, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Katy Kung","avatar":""},{"name":"Kong Ka-Man","avatar":""},{"name":"Griselda Yeung","avatar":""},{"name":"Mimi Kung","avatar":""},{"name":"Hugo Ng Doi-Yung","avatar":""},{"name":"Rebecca Zhu","avatar":""},{"name":"James Ng Yip-Kwan","avatar":""},{"name":"Wong Ka-Lok","avatar":""},{"name":"Matthew Ho","avatar":""},{"name":"Willie Wai Ga-Hung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["大醬園"]', 1784690324330);
