INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoi-lua-nhan-gian', 'Khói Lửa Nhân Gian', 'Chef Hua', 'https://phimimg.com/upload/vod/20240829-1/902e0f45404d30e652495b14741c6e8a.jpg', 'https://phimimg.com/upload/vod/20240829-1/bf036caffdb3a07e74912e50c63fadb1.jpg', '<p>Khói Lửa Nhân Gian Hoa Tiểu Trù kể về lần gặp gỡ tình cờ giữa Hoa Tiểu Mạch, một cô nương có tài nấu nướng và tiêu đầu Mạnh Úc Hòe. Hoa Tiểu Mạch đem lòng nhung nhớ Mạnh Úc Hòe ngay từ lần đầu gặp mặt không hề &quot;vui vẻ&quot; tí nào giữa hai người, nhưng cô nàng vẫn quyết tâm theo đuổi cho bằng được người đàn ông mình thích. Hành trình theo đuổi tình yêu của Hoa Tiểu Mạch rồi sẽ thế nào đây?</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 10, 2020, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tang Min","avatar":""},{"name":"Yang Kai Cheng","avatar":""},{"name":"Siqin Gaoli","avatar":""},{"name":"Li Xiaohong","avatar":""},{"name":"Liu Jingyi","avatar":""},{"name":"Yu Lei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324330);
