INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xanh-tham', 'Xanh Thẳm', 'Grand Blue', 'https://phimimg.com/upload/vod/20251122-1/b473a45b224c1f1b25b785b92601e0d1.jpg', 'https://phimimg.com/upload/vod/20251122-1/2451abb4f814523cedb58b1696872703.jpg', '<p>Ước mơ duy nhất của Iori là được vào đại học trên một hòn đảo xa xôi. Nhưng khi anh bị lôi kéo vào câu lạc bộ lặn biển đầy những trò trác táng và nghiện rượu của trường, hy vọng về một đời sống đại học tươi sáng của anh đã bị quẳng vào hỗn loạn.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryo Ryusei","avatar":""},{"name":"Atsuhiro Inukai","avatar":""},{"name":"Yuki Yoda","avatar":""},{"name":"Aya Asahina","avatar":""},{"name":"Yuka Ogura","avatar":""},{"name":"Ren Ishikawa","avatar":""},{"name":"Masahiro Takashima","avatar":""},{"name":"Ririka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Granblue","Grand Blue Dreaming","Guranburu","ぐらんぶる"]', 1784690324330);
