INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-no-lon-thien-khai', 'Vụ Nổ Lớn Thiên Khải', 'The Big Explosion', 'https://phimimg.com/upload/vod/20251122-1/129ccfe5c34ae81e508b60496202036a.jpg', 'https://phimimg.com/upload/vod/20251122-1/5d20647c0afcf898205b83d41d1e4cf3.jpg', '<p>Nội dung phim xoay quanh cẩm y vệ Trần Lăng, người đứng đầu đội Dạ Ti Hành của triều đình, chuyên điều tra những vụ án bí ẩn không có lời giải. Trong một lần trừ yêu cho thái tử, anh vô tình phát hiện ra bí mật về loài hoa Nhật Luân biến con người trở nên hung dữ và đáng sợ. Trong lúc điều tra, Trần Lăng vô tình để Mộc Đạo Nhân thoát khỏi ngục, lập kế hoạch lật đổ Đại Trần. Sứ mệnh của anh là ngăn cản ông ta, giúp nhân dân thoát khỏi trận chiến đẫm máu.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quách Tiến Đông","avatar":""},{"name":"Hoàng Liễu Yên","avatar":""},{"name":"Lương Gia Nhan","avatar":""},{"name":"Naomen E‘erdeni","avatar":""},{"name":"Tăng Vệ","avatar":""},{"name":"Hàn Mộng Vũ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tianqi da baozha","天启大爆炸"]', 1784690324330);
