INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-3-loi-hua-cua-cha', 'Nắng 3: Lời Hứa Của Cha', 'Accidentally Dad', 'https://phimimg.com/upload/vod/20251120-1/41625ed5f34dbf2d8b5dab145d9ab9d9.jpg', 'https://phimimg.com/upload/vod/20251120-1/8680b06ebec1d1e324939fe1eed28ac3.jpg', '<p>Lời Hứa Của Cha kể về cuộc sống của 2 mẹ con lừa đảo Quế Phương và bé Hồng Ân. Mọi thứ trở nên đảo lộn khi 2 mẹ con vô tình lừa phải bác sĩ Tùng Sơn, người có khả năng là cha mà bé Hồng Ân bấy lâu đang tìm kiếm. Hành trình chinh phục người cha bất đắc dĩ của 2 mẹ con không hề suôn sẻ khi gặp phải chướng ngại đáng gờm là Thùy Linh, người yêu hiện tại của Sơn. Số phận nghiệt ngã còn trêu đùa và thử thách tình cha con hơn nữa khi đặt Hồng Ân vào tình huống hiểm nghèo.</p>', 'Full', 1, 'single', 'completed', 20, 2020, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Kiều Minh Tuấn","avatar":""},{"name":"Oanh Kiều","avatar":""},{"name":"Khả Như","avatar":""},{"name":"Ngân Chi","avatar":""},{"name":"Hữu Châu","avatar":""},{"name":"Hồng Vân","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Nắng 3: Lời Hứa Của Cha"]', 1784690324330);
