INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pen15-phan-2', 'PEN15 (Phần 2)', 'PEN15 (Season 2)', 'https://phimimg.com/upload/vod/20251115-1/add914f7100c93aa7d6d7381c1791b19.jpg', 'https://phimimg.com/upload/vod/20251115-1/ca8b8ccc816fe6b4a2ef2775c4a819b8.jpg', '<p>Maya Erskine và Anna Konkle vào vai chính… là chính họ phiên bản 13 tuổi vào năm 2000, trong khi toàn bộ bạn diễn còn lại đều là học sinh 13 tuổi thật. Bộ phim tái hiện đời sống trung học cơ sở một cách chân thật, hài hước và đầy ngượng ngùng — nơi chỉ một nét bút gel cũng có thể biến “ngày tuyệt nhất” thành “ngày tệ nhất”.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 9, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Maya Erskine","avatar":""},{"name":"Anna Konkle","avatar":""},{"name":"Mutsuko Erskine","avatar":""},{"name":"Taylor Nichols","avatar":""},{"name":"Melora Walters","avatar":""},{"name":"Taj Cross","avatar":""},{"name":"Dallas Liu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["PEN15"]', 1784690324330);
