INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alice-trang-ram', 'Alice Trăng Rằm', 'Oversize Love', 'https://phimimg.com/upload/vod/20251113-1/c8b7db1e91f3f238419375270bc69b19.jpg', 'https://phimimg.com/upload/vod/20251113-1/3c92ad8786dc8b0d260906d5496793d5.jpg', '<p>Cô gái mập mạp Hiểu Hy, sau khi sử dụng một loại nước bí ẩn, đã biến thành một cô nàng xinh đẹp tên Alice. Cô cùng người bạn thanh mai trúc mã Hàn Băng và nam thần Hoàng Khả đã tạo nên chuyện tình tay ba đầy thú vị, hài hước và cảm động.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Quan Hiểu Đồng","avatar":""},{"name":"Hoàng Cảnh Vũ","avatar":""},{"name":"Quan Hồng","avatar":""},{"name":"Lô Sâm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Полненькая любовь","月半爱丽丝"]', 1784690324330);
