INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-ca-rong-khi-yeu', 'Ma Cà Rồng Khi Yêu', 'Forest Demon (The Demon King)', 'https://phimimg.com/upload/vod/20251110-1/c125d2c617340b45f73d2568bf65b07a.jpg', 'https://phimimg.com/upload/vod/20251110-1/cf0a15940da6a44eda10b7b9461faba5.jpg', '<p>Vì tình yêu, lòng hận thù và một lời nguyền từ xa xưa, Chúa Pirajak phải sống như một ma cà rồng. Nhưng với tình yêu trong sáng của Puping, lời nguyền đã được gỡ bỏ và lãnh chúa Pirajak trở thành một con người bình thường và sống với Puping hạnh phúc mãi mãi.</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 11, 2020, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Punyaporn Pongpipat","avatar":""},{"name":"Ohm Atshar Nampan","avatar":""},{"name":"Nutwara Vongvasana","avatar":""},{"name":"Nut Devahastin Na Ayutthaya","avatar":""},{"name":"Chatchadaporn Tananta","avatar":""},{"name":"Thitiwat Ritprasert","avatar":""},{"name":"Tian Atcharee Buakhiao","avatar":""},{"name":"Ornanong Panyawong","avatar":""},{"name":"Rong Kaomulkadee","avatar":""},{"name":"Supoj Janjareonborn","avatar":""},{"name":"Pai Sitang","avatar":""},{"name":"Phutharit Prombandal","avatar":""},{"name":"Chart","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Phut Rattikan (Night Spirit)","Poot Ratikarn","ภูตรัตติกาล"]', 1784690324330);
