INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ma-ca-rong-khi-yeu', 'Ma Cà Rồng Khi Yêu', 'Forest Demon (The Demon King)', 'ma cà rồng khi yêu forest demon (the demon king) punyaporn pongpipat ohm atshar nampan nutwara vongvasana nut devahastin na ayutthaya chatchadaporn tananta thitiwat ritprasert tian atcharee buakhiao ornanong panyawong rong kaomulkadee supoj janjareonborn pai sitang phutharit prombandal chart phut rattikan (night spirit) poot ratikarn ภูตรัตติกาล', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chua-te-2020', 'Đại Chúa Tể', 'The Great Ruler', 'https://phimimg.com/upload/vod/20241125-1/f2a2e2cdc461bc849fce3d50ae4adc90.jpg', 'https://phimimg.com/upload/vod/20241125-1/eb771153724281cd30af6e333cf8da51.jpg', '<p>Trong Đại thiên giới, nơi các vị diện giao nhau, có một truyền kỳ trong thế giới vô tận này đến từ Hạ vị diện. Thiếu chủ Mục Trần của Bắc Linh Cảnh đã đem lòng yêu thương Lạc Ly trên hành trình tiến vào Linh Lộ. Sau một thảm sát đẫm máu Mục Trần đã bị đuổi khỏi Linh Lộ, vẫn quyết gặp lại Lạc Ly ở Ngũ Đại Viện. Trong Bắc Linh Cảnh, Liễu vực và Mục vực luôn đối đầu với nhau, mà Liễu Kinh Thiên – chủ nhân của Liễu vực luôn ấp ủ một âm mưu to lớn. Gánh trên vai trách nhiệm về sự hưng thịnh của Mục vực, về lời hẹn ước với Lạc Ly, Mục Trần bắt đầu con đường trở thành Đại chúa tể của mình.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 11, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Nguyên","avatar":""},{"name":"Âu Dương Na Na","avatar":""},{"name":"Lạc Minh Kiệt","avatar":""},{"name":"Vương Ỷ Tinh","avatar":""},{"name":"Trương Thành Nghệ","avatar":""},{"name":"Mã Nguyệt","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["大主宰","The Great Lord","Great Master","北灵少年志之大主宰"]', 1784690324330);
