INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-man-tro-chuyen-2020', 'Lãng Mạn, Trò Chuyện', 'Romance, Talking', 'https://phimimg.com/upload/vod/20251103-1/23e00f167c8223ffbf9b139ada6f2b3f.jpg', 'https://phimimg.com/upload/vod/20251103-1/f2e9409481ce148fc025222ca6922ad4.jpg', '<p>Phim kể về một nữ sinh đại học trẻ tuổi có thần tượng là một streamer nổi tiếng chuyên tư vấn tình cảm. Bất ngờ, chàng streamer ấy chuyển đến học cùng trường và dường như còn bắt đầu chú ý đến cô. Từ đây, cô phải đối mặt với câu hỏi: Làm sao để đến gần người mình ngưỡng mộ? Và quan trọng hơn — liệu một mối quan hệ với người nổi tiếng trên mạng có thể thật sự bền vững?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Seo-yeon","avatar":""},{"name":"Choi Kyung-hoon","avatar":""},{"name":"Jeong Hyo-jun","avatar":""},{"name":"Jang Tae Hoon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Romance Talking","로맨스, 토킹"]', 1784690324330);
