INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-duong-trong-gio', 'Hải Đường Trong Gió', 'Game Of Shadows', 'https://phimimg.com/upload/vod/20251030-1/0fdf4fe8f1e1a691ab8c5af3109c3766.jpg', 'https://phimimg.com/upload/vod/20251030-1/197e752e2ac0fbbd2189f922aaa63ce5.jpg', '<p>Phim kể về hành trình nhiều sóng gió xoay quanh Hải Đường (Thúy Ngân) - cô gái có thanh xuân bất hạnh, không chỉ bị cha dượng là ông Dần (Trung Dũng) cưỡng bức mà còn bị hắn vu oan phải vào tù. Sau nhiều biến cố, Hải Đường vì muốn trả thù cha dượng của mình đã gia nhập thế giới ngầm, trở thành “chị đại” điều hành đường dây kinh doanh quán bar, vũ trường. Song song với câu chuyện báo thù đầy gây cấn là sự đấu tranh ẩn sâu trong tâm hồn Hải Đường, giữa việc biến nỗi đau và hận thù thành sức mạnh, đồng thời cũng phải chống lại chính nó để bản thân không đánh mất chính mình giữa lằn ranh thiện - ác.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 14, 2020, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thúy Ngân","avatar":""},{"name":"Trung Dũng","avatar":""},{"name":"Gia Huy","avatar":""},{"name":"Tiko Tien Cong","avatar":""},{"name":"Puka","avatar":""},{"name":"Lãnh Thanh","avatar":""},{"name":"Ngân Quỳnh","avatar":""},{"name":"Ngọc Thuận","avatar":""},{"name":"Thụy Mười","avatar":""},{"name":"Phương Hằng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hải Đường Trong Gió"]', 1784690324330);
