INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-khoi-chi-cuc-hai-thinh-loi-2', 'Trùng Khởi Chi Cực Hải Thính Lôi 2', 'Reunion: The Sound Of The Providence (Season 2)', 'https://phimimg.com/upload/vod/20241112-1/5461482ebedb4f3ce95d2d28723791e0.jpg', 'https://phimimg.com/upload/vod/20241112-1/94f620285c72d5ade0aa5ccb35d871fe.jpg', '<p>Nội dung phim xoay quanh việc sau khi Ngô Tà vào làm tại kho 11 biết được chú ba phát hiện tiếng sấm ở kho Tử Đương, đã tiến hành điều tra lần nữa. Anh cùng Vương Bàn Tử, Trương Khởi Linh, Bạch Hạo Thiên lên đường đi tìm tung tích của chú ba, cuối cùng đến được với Thành Sấm. Trong khi họ tìm cách giải đáp bí ẩn trong chuyện “nghe sấm”, một âm mưu bí ẩn đã lâu cũng đang từng bước tiếp cận Ngô Tà và mọi người.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 12, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Nhất Long","avatar":""},{"name":"Mao Hiểu Đồng","avatar":""},{"name":"Hồ Quân","avatar":""},{"name":"Trần Sở Hà","avatar":""},{"name":"Trần Minh Hạo","avatar":""},{"name":"Hoàng Tuấn Tiệp","avatar":""},{"name":"Huỳnh Mỹ Kì","avatar":""},{"name":"Tạ Quân Hào","avatar":""},{"name":"Dương Địch","avatar":""},{"name":"Cù Dĩnh","avatar":""},{"name":"Lưu Sướng","avatar":""},{"name":"Oa Nhĩ","avatar":""},{"name":"Kiều Chấn Vũ","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["盗墓笔记 重启之极海听雷","重启·极海听雷","重启之极海听雷"]', 1784690324330);
