INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-quoc-ky-tham', 'Dân Quốc Kỳ Thám', 'My Roommate Is A Detective', 'https://phimimg.com/upload/vod/20251026-1/7e8364a2d767bf0c9849194ef71a09cf.jpg', 'https://phimimg.com/upload/vod/20251026-1/41c33b4db8d7c3c9d0bfc378edcba938.jpg', '<p>Lộ Nghiêu mới du học Anh trở về, nhờ vào IQ cao và khả năng đưa ra phán đoán cực tốt bị thám trưởng phòng tuần tra thân thủ bất phàm Sở Kiều Sinh ép làm cố vấn cho các vụ án. Sau đó hai người họ lại bắt tay cùng nữ nhà báo Bạch Ấu Ninh, người có đầy lòng chính nghĩa, thành lập nhóm trinh thám gồm 3 thành viên, cùng nhau phá những vụ án mạng tâm linh kỳ lạ.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 20, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Nhất Thiên","avatar":""},{"name":"Trương Vân Long","avatar":""},{"name":"Tiêu Yến","avatar":""},{"name":"Phó Nguyệt Thăng","avatar":""},{"name":"Hứa Ngụy Châu","avatar":""},{"name":"Lưu Sướng","avatar":""},{"name":"Trần Lập Nghiệp","avatar":""},{"name":"Lưu Triệu Dương","avatar":""},{"name":"Hách Tử Huyên","avatar":""},{"name":"Triệu Tĩnh Như","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Min Guo Qi Tan","民國奇探","民国奇探"]', 1784690324330);
