INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dan-quoc-ky-tham', 'Dân Quốc Kỳ Thám', 'My Roommate Is A Detective', 'dân quốc kỳ thám my roommate is a detective hồ nhất thiên trương vân long tiêu yến phó nguyệt thăng hứa ngụy châu lưu sướng trần lập nghiệp lưu triệu dương hách tử huyên triệu tĩnh như min guo qi tan 民國奇探 民国奇探', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('upin-ipin-phan-14', 'Upin & Ipin (Phần 14)', 'Upin & Ipin (Season 14)', 'https://phimimg.com/upload/vod/20251022-1/9152fa23511cd4a5757d2a9c3d1ef16f.jpg', 'https://phimimg.com/upload/vod/20251022-1/bdbbc797f5831911c2069c39fe4f7c82.jpg', '<p style="text-wrap-mode: wrap;">“Upin &amp; Ipin” là loạt phim hoạt hình 3D do Les’ Copaque Production Sdn. Bhd. sản xuất và hiện là một trong những loạt phim hoạt hình ăn khách nhất tại Malaysia, nhận được nhiều đánh giá tích cực và trung bình đạt khoảng 800.000 lượt xem mỗi tập. Bộ phim thực chất là phần ngoại truyện của bộ phim đầu tay “Geng: Pengembaraan Bermula” của công ty.</p><p style="text-wrap-mode: wrap;">Bộ phim xoay quanh cặp song sinh 5 tuổi Upin và Ipin, những người kể chuyện về cuộc sống thường ngày của mình thông qua những hành động vui nhộn và thú vị với bạn bè, đồng thời học hỏi những điều mới mẻ trong các hoạt động thường ngày. Giống như bao đứa trẻ khác, Upin và Ipin rất tinh nghịch và thường xuyên gặp rắc rối, chủ yếu là với cô em gái tuổi teen Ros.</p><p style="text-wrap-mode: wrap;"><br/></p><p style="text-wrap-mode: wrap;"><br/></p><p><br/></p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 18, 2020, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Asyiela Putri","avatar":""},{"name":"Siti Khairunnisa","avatar":""},{"name":"Hajah Ainon Ariff","avatar":""},{"name":"Calvin Tony Lokeemin","avatar":""},{"name":"Tang Ying Sowk","avatar":""},{"name":"Muhammad Hafiz Hassan","avatar":""},{"name":"Muhammad Fareez Daniel","avatar":""},{"name":"Rufaidah Mohamed Fadzil","avatar":""},{"name":"Usayd Uqashah Kamsani","avatar":""},{"name":"Siti Nor Adwin Safie","avatar":""},{"name":"Irfan Fahim","avatar":""},{"name":"Maheswary Mohan","avatar":""},{"name":"Suleiman Bakti Azl","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Upin & Ipin"]', 1784690324330);
