INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('upin-ipin-phan-14', 'Upin & Ipin (Phần 14)', 'Upin & Ipin (Season 14)', 'upin & ipin (phần 14) upin & ipin (season 14) asyiela putri siti khairunnisa hajah ainon ariff calvin tony lokeemin tang ying sowk muhammad hafiz hassan muhammad fareez daniel rufaidah mohamed fadzil usayd uqashah kamsani siti nor adwin safie irfan fahim maheswary mohan suleiman bakti azl upin & ipin', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-ung', 'Sói Ưng', 'Wolf Hawk', 'https://phimimg.com/upload/vod/20251020-1/35c9369372ef4c33035a760ec80b9764.jpg', 'https://phimimg.com/upload/vod/20251020-1/407267b38cea0fb7b4b5f5990e3bf95f.jpg', '<p>Bộ phim kể về câu chuyện một nhóm quân nhân và nhân viên dân sự cùng hợp tác nghiên cứu một vật thể bay lạ từ nước ngoài bay vào lãnh thổ Trung Quốc.Trong quá trình phát triển, họ phải đối mặt với sự nhòm ngó và can thiệp từ nhiều thế lực nước ngoài, những “sói, hổ, báo” đầy âm mưu.Vì thế, họ thành lập “Tổ hành động Lợi Kiếm” — một đội đặc nhiệm tinh nhuệ, mỗi thành viên đều phát huy trí tuệ và kỹ năng đặc biệt của mình để tạo nên sức mạnh vô địch, hoàn thành nhiệm vụ quốc gia giao phó trong muôn vàn nguy hiểm.Sau những trận chiến sinh tử đầy kịch tính, họ đã thành công thu hồi được mảnh vỡ của vật thể bay — mở đầu cho một cuộc đấu tranh sống còn mới vì an ninh và danh dự của Tổ quốc.</p>', 'Full', 1, 'single', 'completed', 16, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Giang Nghệ Thanh","avatar":""},{"name":"Thẩm Áo","avatar":""},{"name":"Châu Huệ Lâm","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["狼鹰"]', 1784690324330);
