INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-ay-tui-mo-vuon-bach-thu', 'Năm Ấy Tui Mở Vườn Bách Thú', 'Those Years I Opened A Zoo', 'https://phimimg.com/upload/vod/20251012-1/272ccc388d270b78b0ad4281f0414dca.jpg', 'https://phimimg.com/upload/vod/20251012-1/0a98e2dac2a02b89127f67122275e431.jpg', '<p>“Nhân viên công sở mới nổi” Đoạn Gia Trạch thừa kế một vườn thú đang trên bờ phá sản. Tuy nhiên, một bản hợp đồng mà anh buộc phải ký đã đặt cược bằng chính mạng sống của mình — yêu cầu anh phải mở rộng quy mô kinh doanh trong thời gian ngắn. Cùng lúc đó, anh còn đón nhận hàng loạt “nhân viên phái cử” đi kèm trong hợp đồng: Tam túc kim ô “Lục Áp”, Cửu vĩ hồ “Hữu Tô”, yêu xà “Bạch Tố Trinh” và “Tiểu Thanh”... Từ đó, Đoạn Gia Trạch bắt đầu hành trình khởi nghiệp vừa mệt bở hơi tai vừa vui không kém, đầy những câu chuyện dở khóc dở cười.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 11, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Su Shangqing","avatar":""},{"name":"Ajie","avatar":""},{"name":"Li Shimeng","avatar":""},{"name":"Yitong Zhao","avatar":""},{"name":"Sun Lulu","avatar":""},{"name":"Qian Chen","avatar":""},{"name":"Xing Chao","avatar":""},{"name":"Hu Yajie","avatar":""},{"name":"Shuang Zhao","avatar":""},{"name":"董玲燕","avatar":""},{"name":"Liu Cong","avatar":""},{"name":"Shuai Guan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Kai Dongwuyuan Naxie Nian","wǒ kāi dòngwùyuán nàxiē nián","Those years I opened a Zoo","The Years I Opened the Zoo","我开动物园那些年"]', 1784690324330);
