INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-bao-thu-2020', 'Sát Thủ Báo Thù', 'I Am Vengeance: Retaliation', 'https://phimimg.com/upload/vod/20251008-1/f1604b8715beef1a7690db395c8560e8.jpg', 'https://phimimg.com/upload/vod/20251008-1/d84fa318507634b7f8bd63b2784e8d5f.jpg', '<p>Bộ phim I Am Vengeance (Sát Thủ Báo Thù) lấy bối cảnh tại một thị trấn của nước Anh bị thao túng bởi một nhóm đặc nhiệm biến chất buôn bán ma túy. Chuyện phim là hành trình của một cựu binh tìm lại công lý cho đồng đội bị lũ đặc nhiệm giết chết dã man cùng gia đình.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Stuart Bennett","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Jessica-Jane Stafford","avatar":""},{"name":"Katrina Durden","avatar":""},{"name":"Sam Benjamin","avatar":""},{"name":"Lee Charles","avatar":""},{"name":"Josh Myers","avatar":""},{"name":"Joe Egan","avatar":""},{"name":"David Schaal","avatar":""},{"name":"Greg Burridge","avatar":""},{"name":"Bentley Kalu","avatar":""},{"name":"Mark Griffin","avatar":""},{"name":"Phoebe Robinson-Galvin","avatar":""},{"name":"Dritan Kastrati","avatar":""},{"name":"Jean-Paul Ly","avatar":""},{"name":"Jennifer Lee Moon","avatar":""},{"name":"Tony C","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Vengence 2","Мститель 2. Расплата","I Am Vengeance: Retaliation"]', 1784690324331);
