INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cua-em', 'Bí Mật Của Em', 'Miss Gu Who is Silent', 'https://phimimg.com/upload/vod/20251002-1/178c663eb5bfca925e7c98979aea4802.jpg', 'https://phimimg.com/upload/vod/20251002-1/ef8e946e6fc6ee420725542f588ed18a.jpg', '<p>Nội dung kể về việc Cố Khinh Châu thay tên đổi họ để làm rõ oan khuất của người anh trai. Cô đã sắp xếp cẩn thận hàng loạt kế hoạch, tưởng chừng mọi việc đã nằm trong tầm kiểm soát, nhưng không ngờ lúc bản thân lún sâu trong cuộc, lại trở thành con tốt của kẻ khác. Đối mặt với tình thân, với tình yêu, sự kiên trì và sự từ bỏ, cuối cùng cô ấy đã xóa tan được sương mù, tìm ra sự thật và tìm lại con người thật của chính mình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Aliyah","avatar":""},{"name":"Li Zifeng","avatar":""},{"name":"Joyin Cai","avatar":""},{"name":"Ye Xiaowei","avatar":""},{"name":"Guo Jianan","avatar":""},{"name":"Liu Luoxi","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["引罪者","完美的我","沉默不语的顾小姐"]', 1784690324331);
