INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-dau-du-dua', 'Lần Đầu Đu Đưa', 'Single & Ready to Mingle', 'https://phimimg.com/upload/vod/20251002-1/fe54ed6dc8775efc7b476d9265eec1a6.jpg', 'https://phimimg.com/upload/vod/20251002-1/e0b6889d1bb59a18ccc8409c9165f5e3.jpg', '<p>Joo-yi và Yeon-seo, tốt nghiệp cùng cấp hai và cấp ba với nhau, lên đại học lại cùng nhau thi vào trường nữ sinh. Hai người độc thân đều vì có nguyên do của chính mình. Một người bị quá khích, còn người kia thì lại căng thẳng quá độ khi gặp gỡ một chàng trai. Tình cờ, Joo-yi và Yeon-seo chuyển đến một căn hộ chung cư, sống với ba chàng trai. Joo-yi tưởng tượng rằng căn hộ này sẽ là một căn hộ tình yêu, trong khi Yeon-seo lại rất lo lắng. Theo thời gian, sự ảo tưởng và sợ hãi về người khác giới của hai người dần được chữa lành, tự hỏi liệu họ có thể thoát khỏi tình trạng độc thân và bắt đầu hẹn hò hay không.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Yoo-jung","avatar":""},{"name":"Kim Do-yeon","avatar":""},{"name":"Jeong Hyo-jun","avatar":""},{"name":"Kim Min-chul","avatar":""},{"name":"Moon Ji-hoo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Melo Not Solo","Single and Ready to Mingle","솔로 말고 멜로"]', 1784690324331);
