INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-den-cung-mua-he', 'Em Đến Cùng Mùa Hè', 'Midsummer is Full of Love', 'https://phimimg.com/upload/vod/20251002-1/93d9c1cb985606eace2fc3a688b6a0a8.jpg', 'https://phimimg.com/upload/vod/20251002-1/f02abb26c0c8d2ef7a6ef1444d236f49.jpg', '<p>Bộ phim xoay quanh câu chuyện cô gái không có năng khiếu âm nhạc nhưng lại mơ mộng trở thành nhà soạn nhạc - Lạc Thiên Nhiên (Dương Siêu Việt đóng) có cơ duyên gặp gỡ ngôi sao thần tượng Cận Trạch Nhất (Hứa Nguỵ Châu đóng), vì tính cách khác biệt giữa hai người mà dẫn đến một loạt tình huống dở khóc dở cười.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Chaoyue","avatar":""},{"name":"Timmy Xu","avatar":""},{"name":"Shi Shi","avatar":""},{"name":"Li Jiaming","avatar":""},{"name":"Jiang Zixin","avatar":""},{"name":"Cao Weiyu","avatar":""},{"name":"Zhong Qi","avatar":""},{"name":"Zhang Lichuan","avatar":""},{"name":"Sun Ke Jie","avatar":""},{"name":"Meng Li","avatar":""},{"name":"Hu Xiaoting","avatar":""},{"name":"Gua Ah-leh","avatar":""},{"name":"Kou Zhenhai","avatar":""},{"name":"Jiang Yan Ru","avatar":""},{"name":"Zhang Yi","avatar":""},{"name":"Dong Xiaobai","avatar":""},{"name":"Yang Dapeng","avatar":""},{"name":"Zhou Haodong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["浪漫满屋","新浪漫满屋","心动满屋","풀하우스","รักวุ่นๆ ในฤดูร้อน","Midsummer is full of love","Full House","仲夏满天心"]', 1784690324331);
