INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thong-linh-phi-phan-2', 'Thông Linh Phi (Phần 2)', 'Psychic Princess (Season 2)', 'https://phimimg.com/upload/vod/20251001-1/9b731bc3bb9e4c9ab2645f08a7b02cef.jpg', 'https://phimimg.com/upload/vod/20251001-1/3b5b2f793a9f0b0c49dcf8039502900d.jpg', '<p>Câu chuyện kể về tiểu thư lớn của Tể tướng phủ – Thiên Vân Hy, từ nhỏ đã mang dị năng đặc biệt nên bị coi là điềm xấu và bị nuôi dưỡng trên núi Linh Vân. Năm 16 tuổi, nàng thay muội muội Thiên Vân Thường gả vào Dạ Vương phủ. Truyền thuyết đồn rằng Dạ U Mịch có tính tình quái lạ, lạnh lùng tàn bạo. Liệu Thiên Vân Hy sẽ phải trải qua những biến cố gì trong cuộc hôn nhân đầy bí ẩn và nguy hiểm này?</p>', 'Hoàn Tất (72/72)', 72, 'series', 'completed', 11, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Nhật Oánh","avatar":""},{"name":"Yến Tử Đông","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["通灵妃"]', 1784690324331);
