INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-tuong-tram-mac', 'Chân Tướng Trầm Mặc', 'The Long Night', 'https://phimimg.com/upload/vod/20241218-1/1648325628cdab70c700299e6765767e.jpg', 'https://phimimg.com/upload/vod/20241218-1/d453d72bd47e04c73d775feb9db6b77d.jpg', '<p>Liêu Phàm, Bạch Vũ mạnh dạn thử sức với bộ phim phạm tội quy mô lớn. Hung thủ giết người vứt xác nhưng lại vô tình bị bắt gặp ngay tại trận, giữa hàng trăm con mắt chứng kiến. Hung thủ cũng đã thừa nhận toàn bộ tội tác của mình. Nhân chứng, vật chứng, khẩu cung đều đầy đủ. Thế nhưng thời khắc viện kiểm sát chính thức khởi tố bị cáo, tình tiết vụ án lại thay đổi bất ngờ...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Liêu Phàm","avatar":""},{"name":"Bạch Vũ","avatar":""},{"name":"Tam Trác","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["长夜难明","沉默的真相","沈默的真相","The Long Night"]', 1784690324331);
