INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-khong-loi-thoat-phan-1', 'Thế Giới Không Lối Thoát (Phần 1)', 'Alice In Borderland (Season 1)', 'thế giới không lối thoát (phần 1) alice in borderland (season 1) kento yamazaki tao tsuchiya এলিস ইন বর্ডারল্যান্ড 今际之国的闯关者 彌留之國的愛麗絲 弥留之国的爱丽丝 alice in borderland η αλίκη στη χώρα των εσχάτων 今际之国的有栖 אליס בבורדרלנד آلیس در منطقه مرزی imawa no kuni no alice imawa no kuni no arisu 아리스 인 보더랜드 аліса в бордерленді аліса в ігрокраї ajal o''yini alisa chegara ortida thế giới không lối thoát 今際の国のアリス', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-co-yeu-2', 'Tình Cờ Yêu 2', 'Love By Chance (A Chance To Love)', 'https://phimimg.com/upload/vod/20250923-1/092e4fda14c3d64f8be8710cd0f9ecf9.jpg', 'https://phimimg.com/upload/vod/20250923-1/7e53c2b0cfe287cf3c8fa2fdc2fd69d7.jpg', '<p>Bộ phim kể về chàng công tử Tin (Mean Phiravich) từng mất lòng tin vào mọi người bỗng chốc trao trọn tim mình cho anh chàng Can (Plan Rathavit) ngờ nghệch. Đồng thời kể tiếp diễn tiến trong mối quan hệ giữa Kengla (Mark Siwat), Techno (Gun Napat); Tam (Title Kirati) và Tar (Earth Katsamonnat).</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 2020, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Rathavit Kijworalak","avatar":""},{"name":"Phiravich Attachitsataporn","avatar":""},{"name":"Tanapon Sukumpantanasan","avatar":""},{"name":"Napat Na Ranong","avatar":""},{"name":"Siwat Jumlongkul","avatar":""},{"name":"Kirati Puangmalee","avatar":""},{"name":"Katsamonnat Namwirote","avatar":""},{"name":"Samantha Melanie Coates","avatar":""},{"name":"Patsit Permpoonsavat","avatar":""},{"name":"Pisitpon Ekpongpisit","avatar":""},{"name":"Boss Thapanat Athikompokin","avatar":""},{"name":"Norravi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Amor Por Acaso 2","Amor Por Acaso","Amor Por Casualidad","A Chance To Love","Love By Chance","บังเอิญรัก"]', 1784690324331);
