INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiep-nguoi-titisan', 'Kiếp Người (Titisan)', 'The Incarnation', 'https://phimimg.com/upload/vod/20250922-1/b620b8ebdcd75ba693f3455ec495fabd.jpg', 'https://phimimg.com/upload/vod/20250922-1/22301a67053c21308a5c3b56162839df.jpg', '<p>Thalia, một cô gái 18 tuổi, liên tục gặp ác mộng về cậu bé có vết bớt ở hông trái rơi xuống giếng sau ngôi nhà nơi cô sinh ra. Cùng lúc, cô bắt đầu nhìn thấy hồn ma và tin rằng mình là một thiếu niên ngoại cảm. Khi phát hiện chàng trai nổi loạn Arra có cùng vết bớt và cứu cậu thoát chết, Thalia vô tình bị cuốn vào cuộc chiến tâm linh giữa các thế lực tà ác và Môn phái Người Canh Cổng. Trong hành trình ấy, cô phải đối diện với sự thật kinh hoàng: mình chính là người được định sẵn để trở thành Nữ Hoàng Tà Ác.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 15, 2020, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Amanda Rawles","avatar":""},{"name":"Arya Vasco","avatar":""},{"name":"Wulan Guritno","avatar":""},{"name":"Imelda Therinne","avatar":""},{"name":"Chicco Kurniawan","avatar":""},{"name":"Claresta Taufan","avatar":""},{"name":"Ruth Marini","avatar":""},{"name":"Valerie Tifanka","avatar":""},{"name":"Dinda Mahira","avatar":""},{"name":"Naomi Paulinda","avatar":""},{"name":"Dolly Martin","avatar":""},{"name":"Farell Akbar","avatar":""},{"name":"Hikmal Abrar","avatar":""},{"name":"Nadira Sungkar","avatar":""},{"name":"Ivan Leonardy","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Titisan"]', 1784690324331);
