INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-do-cua-tu-than', 'Câu Đố Của Tử Thần', 'Manner Of Death', 'https://phimimg.com/upload/vod/20250922-1/7175dc39a81d898a4c7f88ab1a250187.jpg', 'https://phimimg.com/upload/vod/20250922-1/b80cb295fef39a030a8abd3d27ae5e97.jpg', '<p>Đây là bộ phim tội phạm hồi hộp kể về mối quan hệ giữa hai người đàn ông thông qua câu chuyện hấp dẫn của một vụ án giết người. Đây là loạt phim sẽ khiến khán giả phải ngả mũ trước phản ứng hóa học giữa hai nhân vật chính trong khi đồng thời không thể không hào hứng với vụ án và những câu hỏi đặt ra sau đó: Cách chết thực sự là gì? Và ai là kẻ sát nhân thực sự?</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Nattapol Diloknawarit","avatar":""},{"name":"Pakorn Thanasrivanitchai","avatar":""},{"name":"Sapol Assawamunkong","avatar":""},{"name":"Patara Eksangkul","avatar":""},{"name":"Nutwara Vongvasana","avatar":""},{"name":"Chonnikan Netjui","avatar":""},{"name":"Nutthapong Phibunthanakiet","avatar":""},{"name":"Bhudis Viseshchitra","avatar":""},{"name":"Dechphisit Jarukornapiwat","avatar":""},{"name":"Suraphan Chaopaknam","avatar":""},{"name":"Wantanee Inchoiy","avatar":""},{"name":"Kittitouch Kae","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Phri Dti Gaan Thee Dtaai","Manner of Death the Series","พฤติการณ์ที่ตาย"]', 1784690324331);
