INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('banh-rang-trang-va-ao-choang-bui', 'Bánh Răng Trắng và Áo Choàng Bụi', 'My Gear And Your Gown', 'https://phimimg.com/upload/vod/20250921-1/0efe256193bc86f44e5a337076a22432.jpg', 'https://phimimg.com/upload/vod/20250921-1/3f2efa96f1452a271c0b8f9357858cea.jpg', '<p>Một người lựa chọn vĩnh biệt tình yêu, còn một người sẽ trở về và thoả hiệp khi định mệnh khiến họ gặp lại nhau một lần nữa.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Natarit Worakornlertsith","avatar":""},{"name":"Thanik Kamontharanon","avatar":""},{"name":"Chayakorn Jutamas","avatar":""},{"name":"Patchata Janngeon","avatar":""},{"name":"Napat Patcharachavalit","avatar":""},{"name":"Neen Suwanamas","avatar":""},{"name":"Intira Jaroenpura","avatar":""},{"name":"Phollawat Manuprasert","avatar":""},{"name":"Nicole Theriault","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["白色齿轮","Kia Si Khao Kap Kao Si Fun","My Gear And Your Gown: The Series","เกียร์สีขาวกับกาวน์สีฝุ่น"]', 1784690324331);
