INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('growing-season', 'Growing Season', 'Growing Season', 'https://phimimg.com/upload/vod/20250919-1/8aaf18a689cac2029fe58f2d662a6b74.jpg', 'https://phimimg.com/upload/vod/20250919-1/ce3590bd769f46ad21311634338f5e49.jpg', '<p>Nhân vật chính là ba cô gái dưới những câu chuyện tình yêu của họ, nhiều cuộc thảo luận hơn về tình dục và tình yêu.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 10, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Han Su-ah","avatar":""},{"name":"Park Ji-won","avatar":""},{"name":"Kim Chae-eun","avatar":""},{"name":"Kim Kang-min","avatar":""},{"name":"Choi Yoon-je","avatar":""},{"name":"Kang You-seok","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["I Want to Do It Well","I Want to Do Well","잘 하고 싶어"]', 1784690324331);
