INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-quai-vat-2020', 'Thợ Săn Quái Vật', 'Monster Hunter', 'https://phimimg.com/upload/vod/20250915-1/2fb6a06171678aa212e182d42089dee1.jpg', 'https://phimimg.com/upload/vod/20250915-1/fffcb7bdd7582e6531e3e50535901a25.jpg', '<p>Monster Hunter được chuyển thể từ series game nổi tiếng cùng tên của Capcom. Trong phim, đội trưởng Artemis của nữ diễn viên Milla Jovovich (Resident Evil) và đồng đội đã vô tình bước qua một cánh cửa bí ẩn dẫn tới thế giới khác. Tại đây, họ phải chiến đấu với nhiều loài quái vật khổng lồ trong hành trình trở về thế giới. Đồng hành với họ trong trận chiến là nhân vật “Thợ săn” của nam diễn viên Tony Jaa (Ong Bak). Monster Hunter hứa hẹn sẽ là bom tấn hành động với những màn săn quái vật khổng lồ hoành tráng nhất năm 2020.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Milla Jovovich","avatar":""},{"name":"Tony Jaa","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"T.I.","avatar":""},{"name":"Diego Boneta","avatar":""},{"name":"Meagan Good","avatar":""},{"name":"Josh Helman","avatar":""},{"name":"Au-Yeung Jin","avatar":""},{"name":"Hirona Yamazaki","avatar":""},{"name":"Jannik Schümann","avatar":""},{"name":"Nanda Costa","avatar":""},{"name":"Nic Rasenti","avatar":""},{"name":"Clyde Berning","avatar":""},{"name":"Paul Hampshire","avatar":""},{"name":"Schelaine Bennett","avatar":""},{"name":"Bart Fouche","avatar":""},{"name":"Pope Jerrod","avatar":""},{"name":"Aaron Beelner","avatar":""},{"name":"Adriá","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b2390