INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tho-san-quai-vat-2020', 'Thợ Săn Quái Vật', 'Monster Hunter', 'thợ săn quái vật monster hunter milla jovovich tony jaa ron perlman t.i. diego boneta meagan good josh helman au-yeung jin hirona yamazaki jannik schümann nanda costa nic rasenti clyde berning paul hampshire schelaine bennett bart fouche pope jerrod aaron beelner adriá 魔物獵人 モンスターハンター 몬스터 헌터 vânătorul de monștri ציידי המפלצות มอนสเตอร์ ฮันเตอร์ モンスターハンター：2020 monster hunter 怪物猎人', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chinh-phuc-tinh-yeu-hoan-hao', 'Chinh Phục Tình Yêu Hoàn Hảo', 'Love Conquest', 'https://phimimg.com/upload/vod/20250913-1/5bd21639c7463d5b4b07bb3341e7ae41.jpg', 'https://phimimg.com/upload/vod/20250913-1/de6356eaa756b32bf09fbd51994b841e.jpg', '<p>Yeong-seok thầm thích cô bạn cùng câu lạc bộ là Hee-yeon. Sau 1.262 ngày, anh quyết định tỏ tình, nhưng cuối cùng lại từ bỏ khi tận mắt chứng kiến Hee-yeon hôn đàn anh của mình. Theo lời gợi ý của người bạn cùng phòng Byung-soon, Yeong-seok tìm đến một trang web huấn luyện hẹn hò mang tên “Adventure M”. Tại đây, anh gặp một ứng viên khác là Myo-ryeong. Cô gái này, sau khi đưa đón chàng Yeong-seok vừa bảnh bao vừa quyến rũ, đã đưa ra một lời đề nghị bất ngờ: một chuyến tham quan nhà nghỉ...</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kang Ye-bin","avatar":""},{"name":"Oh Hee-joong","avatar":""},{"name":"Shin Sae-rom","avatar":""},{"name":"Kim Do-hyun","avatar":""},{"name":"Ha Ra","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["yeon-ae wan-jeon jeong-bok","Complete conquest of love","연애 완전 정복"]', 1784690324331);
