INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-gia-my-hau-vuong-dai-thanh-vo-song', 'Thật Giả Mỹ Hầu Vương: Đại Thánh Vô Song', 'True And False Monkey King', 'https://phimimg.com/upload/vod/20250910-1/1eea503dde1eda82a1179d9699c47856.jpg', 'https://phimimg.com/upload/vod/20250910-1/9ef586f9af83116b8ceef6f27060c233.jpg', '<p>Lục Nhĩ vì muốn cứu nữ yêu Tử Đằng bị Tôn Ngộ Không tổn thương, mà đồng ý với yêu vương, cải trang thành Tôn Ngộ Không, phá hủy kế hoạch đi thỉnh kinh của Đường Tăng. Vì để chứng minh thân phận, Lục Nhĩ và Tôn Ngộ Không quyết đấu nhiều lần, nhưng là thật hay giả, mọi người khó mà phân biệt. Dần dần, Lục Nhĩ cũng quên mất thân phận của mình, tin rằng mình chính là Tôn Ngộ Không, để chúng sinh an bình, cuối cùng Lục Nhĩ chọn cách kề vai chiến đấu cùng Tôn Ngộ Không, thậm chí không tiếc hy sinh chính mình...</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đỗ Dật Hành","avatar":""},{"name":"Hạ Cương","avatar":""},{"name":"Kim Khảo Khảo","avatar":""},{"name":"Ngô Mạnh Đạt","avatar":""},{"name":"Hồ Lâm Hy","avatar":""},{"name":"Trình Dã","avatar":""},{"name":"Cù Thượng Uy","avatar":""},{"name":"Long Dương Dương","avatar":""},{"name":"Tôn Thông","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["真假美猴王之战神归来","The Return of the True and False Monkey King","True&False Monkey King","大圣杀","真假美猴王之大圣无双"]', 1784690324331);
