INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('that-gia-my-hau-vuong-dai-thanh-vo-song', 'Thật Giả Mỹ Hầu Vương: Đại Thánh Vô Song', 'True And False Monkey King', 'thật giả mỹ hầu vương: đại thánh vô song true and false monkey king đỗ dật hành hạ cương kim khảo khảo ngô mạnh đạt hồ lâm hy trình dã cù thượng uy long dương dương tôn thông 真假美猴王之战神归来 the return of the true and false monkey king true&false monkey king 大圣杀 真假美猴王之大圣无双', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luong-the-hoan', 'Lưỡng Thế Hoan', 'The Love Lasts Two Minds', 'https://phimimg.com/upload/vod/20241203-1/7574a5bed4b05282eb4c00f7c45a484b.jpg', 'https://phimimg.com/upload/vod/20241203-1/dd018841e76490116d53841db689326f.jpg', '<p>Lưỡng Thế Hoan kể về câu chuyện giữa nàng Nguyên Thanh Ly (Trần Ngọc Kỳ) con gái của tướng quân, sau khi bị mất trí nhớ liền trốn tới huyện Thấm Hà làm sai dịch. Tại đây, nàng đã gặp Cảnh Từ (Vu Mông Lung) là con nuôi Triệu Vương và đã bị cuốn vào một cuộc tranh giành quyền lực khốc liệt. Đồng thời Nguyên Thanh Ly đã cùng với Cảnh Từ đóng góp công sức xoá sạch những tệ nạn ở huyện Thấm Hà. Trên con đường đầy chông gai đó, Nguyên Thanh Ly dần tìm lại được trí nhớ và phát hiện ra trước khi mất trí nhớ mình đã bị đánh tráo với tỷ muội sinh đôi. Nàng thật ra là Phong Viên Mãn còn Nguyên Thanh Ly lại là danh phận của một người khác. Trải qua bao sóng gió, cuối cùng Cảnh Từ đã quyết định cùng với Phong Viên Mãn lui về ở ẩn, sống cuộc đời an nhàn cho những năm tháng cuối đời.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 11, 2020, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Vu Mông Lung","avatar":""},{"name":"Trần Ngọc Kỳ","avatar":""},{"name":"Trương Tư Phàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Liang Shi Huan","Past Life and Life","Happiness Over Two Lifetimes","Два мира","两世欢"]', 1784690324331);
