INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-anh-hung-bloodshot', 'Siêu Anh Hùng Bloodshot', 'Bloodshot', 'https://phimimg.com/upload/vod/20250905-1/a32df0bf06d11388554ace1f24f137e2.jpg', 'https://phimimg.com/upload/vod/20250905-1/e4c64f54f35cd50c496d12d580284dac.jpg', '<p>Ray Garrison là một sĩ quan cấp cao đã hy sinh trong một trận chiến. Thế nhưng, anh được tái sinh bằng công nghệ cao, giúp Ray sở hữu sức mạnh siêu nhiên và khả năng phục hồi nhanh chóng. Vận dụng những kỹ năng mới, anh săn lùng gã đàn ông đã giết vợ mình. Thế nhưng, khi sự thật dần hé mở, Ray nhận ra rằng không phải mọi thứ đều đáng tin. Ngay cả chính bản thân anh.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Vin Diesel","avatar":""},{"name":"Eiza González","avatar":""},{"name":"Sam Heughan","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Talulah Riley","avatar":""},{"name":"Lamorne Morris","avatar":""},{"name":"Guy Pearce","avatar":""},{"name":"Jóhannes Haukur Jóhannesson","avatar":""},{"name":"Alex Hernandez","avatar":""},{"name":"Siddharth Dhananjay","avatar":""},{"name":"Tamer Burjaq","avatar":""},{"name":"Clyde Berning","avatar":""},{"name":"David Dukas","avatar":""},{"name":"Tyrel Meyer","avatar":""},{"name":"Alex Anlos","avatar":""},{"name":"Maarten Römer","avatar":""},{"name":"Charlie Bo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["喋血战士","喋血戰士","Bloodshot"]', 1784690324331);
