INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-do-me-tung-chi-dau-chien-can-khon', 'Long Đô Mê Tung: Chi Đấu Chiến Càn Khôn', 'The Battle Of The Lost Track Of The Dragon', 'https://phimimg.com/upload/vod/20250905-1/f95c67150218610e08b80b4a2acec850.jpg', 'https://phimimg.com/upload/vod/20250905-1/63a4e9cbe988d412ab42f948923cae0f.jpg', '<p>Câu chuyện xoay quanh hành trình mạo hiểm của một nhóm người tại “Long Đô”, nơi ẩn chứa nhiều bí mật và kho báu cổ xưa. Trong quá trình tìm kiếm chân tướng, họ vô tình bị cuốn vào cuộc chiến tranh giành bảo vật thần bí mang sức mạnh xoay chuyển càn khôn. Giữa những thế lực tà ác, âm mưu đen tối và nguy hiểm trùng trùng, các nhân vật chính phải đấu trí, đấu dũng để bảo vệ chính nghĩa và sinh tồn.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vũ Địch Văn","avatar":""},{"name":"Lý Mộng Mộng","avatar":""},{"name":"Lý Bác Nghĩ","avatar":""},{"name":"Hạc Thanh","avatar":""},{"name":"Cao Hạnh","avatar":""},{"name":"Từ Thiếu Cường","avatar":""},{"name":"Vương Dự Khải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["龍都迷踪之鬥戰乾坤","Long Dou Mi Zong Zhi Dou Zhan Qian Kun","The Battle of the Lost Track of the Dragon City","龙都迷踪之斗战乾坤"]', 1784690324331);
