INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-dao-to-su-chibi', 'Ma Đạo Tổ Sư Chibi', 'The Founder of Diabolism Q', 'https://phimimg.com/upload/vod/20250903-1/a004e279712e9b4f46b391406ca8a0fb.jpg', 'https://phimimg.com/upload/vod/20250903-1/ad5ec53e838fa8fd49b5a68d5be67ae7.jpg', '<p>Ma Đạo Tổ Sư Chibi kể về 3 khoảng thời gian thời niên thiếu, lúc lớn lên và sau khi trở về từ cõi chết của Nguỵ Vô Tiện</p>', 'Hoàn Tất (30/30)', 30, 'hoathinh', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ajie","avatar":""},{"name":"Jiang Bian","avatar":""},{"name":"Guo Haoran","avatar":""},{"name":"Liu Sanmu","avatar":""},{"name":"Titus Jin","avatar":""},{"name":"Su Shangqing","avatar":""},{"name":"Yang Tianxiang","avatar":""},{"name":"Li Shimeng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["마도조사 Q","마도조사Q","魔道祖师Q"]', 1784690324331);
