INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('30-chua-phai-la-het', '30 Chưa Phải Là Hết', 'Nothing But Thirty', 'https://phimimg.com/upload/vod/20240917-1/0d13832718ce67f7d1d53704486eb4f3.jpg', 'https://phimimg.com/upload/vod/20240917-1/149b87781114fda20bf112b160e86f64.jpg', '<p>Bộ phim xoay quanh 3 người phụ nữ vừa bước sang tuổi 30 phải liên tục đối mặt với những khủng hoảng mới trong cuộc sống. Đó là Chung Hiểu Cần (Mao Hiểu Đồng) - một nữ nhà văn phổ thông bỗng dưng giàu có sau khi bán được tác phẩm với giá cao, nhưng giờ đây phải đối mặt với sự lựa chọn giữa chồng con và sự nghiệp. Đó là Cố Giai (Đồng Dao) - một người vợ chu toàn, giúp chồng trở thành tổng tài thành đạt, nhưng phải đối mặt với sự xuất hiện của con giáp thứ 13 . Đó là Vương Mạn Ni (Giang Sơ Ảnh) - một nữ nhân xinh đẹp thông minh, dám nghĩ dám làm, thế nhưng khó khăn bắt đầu bủa vây khi cuộc hôn nhân hấp tấp của cô dẫn đến chia ly trong nuối tiếc. Cả ba cô gái sát cánh bên nhau, cùng vượt qua những sóng gió cuộc đời.</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 10, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Giang Sơ Ảnh","avatar":""},{"name":"Đồng Dao","avatar":""},{"name":"Mao Hiểu Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["겨우 서른","겨우서른","삼십이이","三十而已","Nothing But Thirty"]', 1784690324331);
