INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phi-vu-trieu-do-phan-4', 'Phi Vụ Triệu Đô (Phần 4)', 'Money Heist (Season 4)', 'phi vụ triệu đô (phần 4) money heist (season 4) úrsula corberó itziar ituño álvaro morte pedro alonso miguel herrán esther acebo jaime lorente najwa nimri enrique arce rodrigo de la serna darko peric hovik keuchkerian luka peroš belén cuesta fernando cayo haus des geldes kuca od papira хартиената къща la casa de papel la maison de papier 纸钞屋 纸钞屋（西班牙版） papirhuset la casa de papel η τέλεια ληστεία سرقت پول خانه کاغذی البروفيسور la casa de papel darphane soygunu money heist', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-trieu-do-mot-hien-tuong', 'Phi Vụ Triệu Đô: Một Hiện Tượng', 'Money Heist: The Phenomenon', 'https://phimimg.com/upload/vod/20250827-1/db2771e8738a04399de324c897e1d8c3.jpg', 'https://phimimg.com/upload/vod/20250827-1/d11d01986f589de45367fb95fdeec5d4.jpg', '<p>Là một tác phẩm trộm cướp đột phá và cuốn hút đến từ đất nước Tây Ban Nha, La Casa De Papel kể về một nhóm những tội phạm tập hợp lại cho một phi vụ lịch sử: đột nhập Royal Mint of Spain – sở đúc tiền hoàng gia của Tây Ban Nha và tiến hành trộm hàng tỷ euro.
 Không dừng lại ở việc lấy tiền rồi chạy trốn, kế hoạch của gang trộm này còn bao gồm… in thêm tiền, bắt giữ con tin kéo dài đến hàng chục ngày được thiết kế tỉ mẩn và cực kỳ thông minh bởi nhân vật trùm cuối mang tên Profesor (Giáo Sư). Cùng lúc đó, băng tội phạm sẽ phải cân não với lực lượng cảnh sát, thám tử cũng đang cố gắng giải vây cho nhóm con tin bị bắt giữ.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Úrsula Corberó","avatar":""},{"name":"Álvaro Morte","avatar":""},{"name":"Itziar Ituño","avatar":""},{"name":"Pedro Alonso","avatar":""},{"name":"Alba Flores","avatar":""},{"name":"Miguel Herrán","avatar":""},{"name":"Esther Acebo","avatar":""},{"name":"Jaime Lorente","avatar":""},{"name":"Rodrigo de la Serna","avatar":""},{"name":"Darko Peric","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Haus des Geldes: Das Phänomen","La Casa de Papel: O Fenômeno","La Casa de Papel: el fenómeno"]', 1784690324331);
