INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-yeu-pho-phan-1', 'Bách Yêu Phổ (Phần 1)', 'Fairies Albums (Season 1)', 'https://phimimg.com/upload/vod/20250825-1/5b6a915f578d1e354fdce2c18f94ad66.jpg', 'https://phimimg.com/upload/vod/20250825-1/b7fa168e4f9ebb40f1fcfc6d59181f8d.jpg', '<p>Bách Yêu Phổ - Bai Yao Pu, kể về chuyến vân du bốn phương của nữ Quỷ y Đào Yêu cùng với tiểu hoà thượng Ma Nha, hồ ly Cổn Cổn và Liễu công tử anh tuấn. Quỷ y Đào Yêu chỉ nhận chữa bệnh cho yêu chứ không chữa trị cho con người. Trong hành trình dài ấy, họ gặp gỡ rồi chữa trị cho rất nhiều yêu quái, hoá giải vô số sầu muộn cho người khác.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Shuang Zhao","avatar":""},{"name":"Chang Rongshan","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["百妖谱·京师篇 Fairies Album","百妖谱·京师篇","Baiyaopu","Bai Yao Pu","百妖谱 第貳季","Bai Yao Pu Di Yi Ce","Bai Yao Pu Di Er Ji","Bai Yao Pu Jing Shi Pia","Bai Yao Pu Si Fu Pian","百妖谱 京师篇","百妖谱 第壹册","百妖谱 司府篇","Bǎiyāopǔ","百妖譜","バイヤオプー","ひゃくようふ","Espectro dos Cem Demónios","Manual dos Cem Demónios","Hundred Demon Spectrum","Manual of Hundred Demons","Fairies Album","百妖谱"]', 1784690324331);
