INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chao-mung-toi-cai-chet-bat-ngo', 'Chào Mừng Tới Cái Chết Bất Ngờ', 'Welcome To Sudden Death', 'https://phimimg.com/upload/vod/20250823-1/1f5a5c2b33fe371bc21e825d69cc1427.jpg', 'https://phimimg.com/upload/vod/20250823-1/fa55846eef49a2854d8eb8d47f9ae98d.jpg', '<p>Jesse Freeman là một cựu sĩ quan lực lượng đặc biệt và chuyên gia chất nổ, hiện đang làm công việc bình thường với tư cách là nhân viên bảo vệ trong một đấu trường bóng rổ. Rắc rối nổ ra khi một nhóm khủng bố am hiểu công nghệ bắt cóc ông chủ của đội bóng và con gái của Jesse trong đêm khai mạc. Đối mặt với thời gian eo hẹp và tỷ lệ thành công cực kì thấp, Jesse sẽ phải chiến đấu như thế nào.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Jai White","avatar":""},{"name":"Michael Eklund","avatar":""},{"name":"Gary Owen","avatar":""},{"name":"Sabryn Rock","avatar":""},{"name":"Anthony Grant","avatar":""},{"name":"Gillian White","avatar":""},{"name":"Anthony J. Mifsud","avatar":""},{"name":"Kristen Harris","avatar":""},{"name":"Paul Essiembre","avatar":""},{"name":"Stephanie Sy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sudden Death 2","Muerte súbita","מוות פתאומי מבורך","Welcome to Sudden Death"]', 1784690324331);
