INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-si-baki-phan-2', 'Võ Sĩ Baki (Phần 2)', 'BAKI (Season 2)', 'võ sĩ baki (phần 2) baki (season 2) nobunaga shimazaki kenjiro tsuda takehito koyasu issei futamata banjo ginga chafurin akio otsuka yoshihisa kawahara sora amamiya mugihito takayuki sugo bin shimada rikiya koyama takuya eguchi toru furuya 刃牙 大擂台赛的传说 刃牙 死囚篇 baki (2018) μπάκι באקי המתאבק החדש baki baki: dai raitaisai-hen باكي المحارب baki: the great raitai tournament saga バキ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-nam-hoa-hop-uoc-dinh-mot-loi', 'Trăm Năm Hòa Hợp, Ước Định Một Lời', 'Forever Love', 'https://phimimg.com/upload/vod/20250815-1/a372c6112ae2faa41cb33f149a982552.jpg', 'https://phimimg.com/upload/vod/20250815-1/18c53992b9988c7965973cd9a7701b41.jpg', '<p>Câu chuyện xoay quanh cuộc sống vườn trường đầy hoài bão và ước vọng đậu đại học. Trong đó, cặp đôi chính Tưởng Chính Hàn (Vương An Vũ) và Hạ Lâm Hy (Hướng Hàm Chi) ngay từ lần đầu gặp gỡ đã được gọi là &quot;oan gia ngõ hẹp&quot;. Vì là lớp trưởng nên Lâm Hy buộc phải quan tâm đến sự hiện diện trong lớp của tất cả mọi người, nếu ai vắng mặt, cô phải thay giáo viên tìm hiểu ngọn ngành.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 10, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương An Vũ","avatar":""},{"name":"Hướng Hàm Chi","avatar":""},{"name":"Trần Trạch","avatar":""},{"name":"Phan Mỹ Diệp","avatar":""},{"name":"Viên Hạo","avatar":""},{"name":"Triệu Hạo Hoằng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["百岁之好","백세지호일언위정","영원한 사랑","Forever Love","百岁之好，一言为定"]', 1784690324331);
