INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-vu-lenh-chi-cuu-u', 'Cấm Vũ Lệnh Chi Cửu U', 'Dragon Slayer', 'https://phimimg.com/upload/vod/20250725-1/e8306d9b985a3d4a7f87a22bb3a377bf.jpg', 'https://phimimg.com/upload/vod/20250725-1/0f2bccc7553346c378fbb227023849c6.jpg', '<p>Vạn thần tế đàn đã phong ấn một con chúc long cổ xưa, tương truyền nếu chúc long tỉnh dậy ắt sẽ mang đến tai ương. Đệ tử của môn phái Tây Tông thần bí trong giang hồ Hứa Mặc và sư muội Mộc Vũ Hàm đến thôn Cửu U để làm nhiệm vụ, nhưng vùng đất Cửu U vốn nguy hiểm trùng trùng, lại còn thêm chúc long đang vây tại đó. Họ sẽ phải cách nào đây?</p>', 'Full', 1, 'single', 'completed', 35, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâu Học Hiền","avatar":""},{"name":"Lưu Lâm Thành","avatar":""},{"name":"Khương Ninh","avatar":""},{"name":"Trịnh Thác Cương","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Dragon Slayer","禁武令之九幽烛龙"]', 1784690324331);
