INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-la-tan-nuong', 'Tu La Tân Nương', 'Asura Bride (Love In Blood)', 'https://phimimg.com/upload/vod/20250724-1/1b2bd5990b00eb067ed3e4535093f449.jpg', 'https://phimimg.com/upload/vod/20250724-1/9eb4882ae82085b4fb9f3c892ae198a7.jpg', '<p>Thiếu nữ vì báo thù mà hóa thành ma quỷ! Vào đêm thành hôn với Tướng quân xuất thân hàn vi là Tiêu Tễ, Quận chúa Vương Huyên biến thành tân nương Tu La, phá hoại giết chóc khắp nơi, ngay cả thanh mai trúc mã là Tam hoàng tử cũng sợ hãi vô cùng. Vậy nhưng Tiêu Tễ vẫn không hề từ bỏ, đi tìm kiếm chân tướng cùng với Vương Huyên. Chẳng ngờ phía sau chuyện này lại dính dáng tới một âm mưu to lớn khác...</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nữu Hạo Minh","avatar":""},{"name":"Châu Khả Di","avatar":""},{"name":"Đỗ Dật Hành","avatar":""},{"name":"Vương Thùy Di","avatar":""},{"name":"Bảo Lệ Ninh","avatar":""},{"name":"Trương Lâm Thanh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["帝王业之修罗新娘","Love in Blood","Tu La Tân Nương","修罗新娘"]', 1784690324331);
