INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tu-la-tan-nuong', 'Tu La Tân Nương', 'Asura Bride (Love In Blood)', 'tu la tân nương asura bride (love in blood) nữu hạo minh châu khả di đỗ dật hành vương thùy di bảo lệ ninh trương lâm thanh 帝王业之修罗新娘 love in blood tu la tân nương 修罗新娘', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-rung-bi-mat-phan-2', 'Khu Rừng Bí Mật (Phần 2)', 'Stranger (Season 2)', 'https://phimimg.com/upload/vod/20250723-1/42b30c6413a7144a94cf57da24274deb.jpg', 'https://phimimg.com/upload/vod/20250723-1/6acbaa3c5fc68ad2b625d1d20062131a.jpg', '<p>Công tố viên Hwang Shi Mok (Jo Seung Woo) và nữ cảnh sát Han Yeo Jin (Bae Doo Na) sẽ là những người lật mở từng bí mật trong “khu rừng&quot;, bắt đầu từ một vụ án mạng mà nạn nhân có liên quan trực tiếp tới những kẻ máu mặt trong văn phòng công tố, còn kẻ bị tình nghi là một người đàn ông luôn miệng phủ nhận tội danh giết người cướp của. Hwang Shi Mok là một tên máu lạnh thực sự, anh ta đã mất đi cảm xúc kể từ sau ca phẫu thuật não khi còn nhỏ. Mục tiêu của anh ta trong vụ án lần này không phải là Kang Jin Sub (Yoon Kyung Ho), người đang bị tình nghi. Những manh mối tại hiện trường và tiết lộ của nạn nhân vài ngày trước khi chết đủ để khiến Hwang Shi Mok nhắm vào những con cá to hơn, trong khi vẫn để một nữ công tố viên vừa kết thúc đợt thực tập 6 tháng đẩy Kang Jin Sub vào tù. Một kẻ tin rằng mình oan uổng sẽ không chịu ngồi tù 22 năm, hắn quyết tâm dùng chính cái chết của mình để tiêu diệt tên công tố viên ấy trước dư luận.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 10, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Seung-woo","avatar":""},{"name":"Bae Doona","avatar":""},{"name":"Lee Jun-hyuk","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"Choi Moo-seong","avatar":""},{"name":"Yoon Se-a","avatar":""},{"name":"Park Seong-geun","avatar":""},{"name":"Jeon Bae-soo","avatar":""},{"name":"Choi Jae-woong","avatar":""},{"name":"Lee Hae-yeong","avatar":""},{"name":"Song Ji-ho","avatar":""},{"name":"Kim Young-jae","avatar":""},{"name"