INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khu-rung-bi-mat-phan-2', 'Khu Rừng Bí Mật (Phần 2)', 'Stranger (Season 2)', 'khu rừng bí mật (phần 2) stranger (season 2) cho seung-woo bae doona lee jun-hyuk jeon hye-jin choi moo-seong yoon se-a park seong-geun jeon bae-soo choi jae-woong lee hae-yeong song ji-ho kim young-jae kim hak-seon jung sung-il yoon tae-in secret forest (stranger) 秘密森林 bimilui soop جنگل مخفی جنگل اسرار 비밀의 숲 stranger тайный лес таємний ліс stranger (2017) forest of secrets', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-fargo-phan-4', 'Thị Trấn Fargo (Phần 4)', 'Fargo (Season 4)', 'https://phimimg.com/upload/vod/20250723-1/68e453a72b70507f8e0a9686d7cbdd0b.jpg', 'https://phimimg.com/upload/vod/20250723-1/cc4caf52fc2521df7f097dd9a0a0512e.jpg', '<p>Fargo là một bộ phim truyền hình dài tập hài kịch tội phạm đen của Mỹ được tạo ra và chủ yếu được viết bởi Noah Hawley. Chương trình được lấy cảm hứng từ bộ phim cùng tên năm 1996 được viết và đạo diễn bởi anh em Coen, người được ghi là nhà sản xuất điều hành cho loạt phim cùng với Hawley. Sê-ri được công chiếu vào ngày 15 tháng 4 năm 2014, trên FX, và tuân theo định dạng hợp tuyển, với mỗi phần được đặt trong một thời đại khác nhau, và với một câu chuyện khác nhau và chủ yếu là các nhân vật và diễn viên mới, mặc dù có sự trùng lặp nhỏ. Mỗi mùa có rất nhiều tài liệu tham khảo cho phim của anh em Coen.</p>', 'Full', 11, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Juno Temple","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"David Rysdahl","avatar":""},{"name":"Joe Keery","avatar":""},{"name":"Lamorne Morris","avatar":""},{"name":"Richa Shukla Moorjani","avatar":""},{"name":"Sam Spruell","avatar":""},{"name":"Sienna King","avatar":""},{"name":"Dave Foley","avatar":""},{"name":"Jon Hamm","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["雪花高离奇命案","冰血暴","FARGO/ファーゴ","Фарго","Fargo: Year One","Fargo: Year Two","Fargo: Year Three","Fargo: Year Four","Fargo: Year Five","Fargo"]', 1784690324331);
