INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-cua-yeu-tinh', 'Nụ Hôn Của Yêu Tinh', 'Kiss Goblin', 'https://phimimg.com/upload/vod/20250716-1/77ab70a72a5cd1d1cf5f92082fba9d6a.jpg', 'https://phimimg.com/upload/vod/20250716-1/f034a1c8e03074336ebbae8df5abac17.jpg', '<p>&quot;Để trở thành con người, anh phải có mười nụ hôn với mười con người.&quot;

Một chuyện tình vừa ngọt ngào vừa nguy hiểm giữa một yêu tinh khao khát trở thành con người và một cô gái căm ghét loài người.

Ban-sook là một yêu tinh với khao khát muốn trở thành con người. Cách duy nhất để đạt được ước mơ đó là hoàn thành nhiệm vụ mười nụ hôn. Thông qua những nhiệm vụ này, anh sẽ học được cảm xúc của loài người và đủ điều kiện để trở thành con người.

Trong quá trình hoàn thành các nhiệm vụ, Ban-sook gặp Yeon-ah - một cô gái loài người. Cô căm ghét con người vì sự ích kỷ và vô tâm của họ.

Một yêu tinh và một con người bắt đầu quen biết nhau. Dần dần, cả hai bắt đầu nảy sinh tình cảm với nhau...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Bae In-hyuk","avatar":""},{"name":"Jeon Hye-won","avatar":""},{"name":"Lee Jung-min","avatar":""},{"name":"Lee Se-hee","avatar":""},{"name":"Moon Ji-yong","avatar":""},{"name":"Jang Eui-soo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Поцілунок демона","Kiss Goblin","키스요괴"]', 1784690324331);
