INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-goi-ca-ga-doo-ri', 'Quán Gỏi Cá Ga Doo Ri', 'Gaduri Restaurant', 'https://phimimg.com/upload/vod/20250714-1/fec801511aeedd88ea0c197937faab51.jpg', 'https://phimimg.com/upload/vod/20250714-1/95eb73c15f2f9c2906ba4deaab76245f.jpg', '<p>Sushi, Bí Mật và Hàng Xóm Khiến Cô Không Thể Làm Ngơ Sau một cuộc chia tay đầy đau khổ, Ga Doo Ri quyết tâm làm lại cuộc đời. Cô mở một quán nhỏ của riêng mình mang tên“Quán Gỏi Cá Ga Doo Ri”, nhanh chóng lột xác trở thành một bà chủ thành công kiêm chuyên gia tư vấn tình cảm. Khi ngày càng nhiều người kéo đến để thưởng thức và tìm lời khuyên, một người đàn ông bí ẩn tên là Cha Woo Bin bất ngờ xuất hiện trong tầm mắt cô. Anh ta quyến rũ nhưng lại có nhiều điểm đáng ngờ. Điều bất ngờ hơn cả là anh lại chính là... hàng xóm của Ga Doo Ri! Dù chưa thể hiểu rõ ý đồ thực sự của anh, nhưng cô không có ý định lùi bước – cô quyết tâm vạch trần sự thật ẩn sau vẻ ngoài dịu dàng của anh.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Ju-bin","avatar":""},{"name":"Han Sang-hyuk","avatar":""},{"name":"Choi Ji-hui","avatar":""},{"name":"Jung Jae-Oh","avatar":""},{"name":"Kim Seong-tae","avatar":""},{"name":"Lee Hyeong Seok","avatar":""},{"name":"Yoon Seul","avatar":""},{"name":"Jang Sol Mi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["加斗里生鱼片店","Gaduri Restaurant","가두리 횟집"]', 1784690324331);
