INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tham-dich-nhan-kiet-dai-chien-on-dich-dich-cong-diet-chuot', 'Thần Thám Địch Nhân Kiệt: Đại Chiến Ôn Dịch (Địch Công Diệt Chuột)', 'Detective Dee: Rats Invasion', 'https://phimimg.com/upload/vod/20250712-1/7d61917ccbd99c6701e0fc02bfabe787.jpg', 'https://phimimg.com/upload/vod/20250712-1/3d2aa6158583459bd391a3d3a2e69324.jpg', '<p>Tỉnh Binh Châu đang trải qua một đợt dịch chuột hoành hành, khiến các nhà tù bị sập. Địch Nhân Kiệt được giao trọng trách trong tình thế nguy cấp này. Nhiều dân làng đã bị nhiễm bệnh do dịch chuột và bị mắc kẹt trong thành phố. Để cứu sống người dân toàn thành, Địch Nhân Kiệt đã bắt tay vào điều tra nguồn bệnh. Tuy nhiên, khi cuộc điều tra đi sâu hơn, một âm mưu lớn dần hé lộ đằng sau thảm họa chuột này.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Hạo Dân","avatar":""},{"name":"Viện Khương Đan","avatar":""},{"name":"Trương Đông","avatar":""},{"name":"Quách Tiểu Quân","avatar":""},{"name":"Tôn Viễn Ninh","avatar":""},{"name":"Sơn Hà","avatar":""},{"name":"Cung Tiểu Quân","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Di Renjie The Exterminator","Detective Dee: Rats Invasion","Detective Dee und das Geheimnis des Rattenfluchs","狄公灭鼠"]', 1784690324331);
