INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-phu-nu-tuyet-voi', 'Người Phụ Nữ Tuyệt Vời', 'The Wonder Woman', 'https://phimimg.com/upload/vod/20250712-1/cd3e99e6217e8386629cc0da5c3c56f7.jpg', 'https://phimimg.com/upload/vod/20250712-1/0c3304753a04c6924be46b492d1a7a65.jpg', '<p>Là một người có tiếng trong giới Marketing, “cá mập” Đỗ Ngãi Sa luôn nỗ lực không ngừng để tiến về phía trước. Làm việc cùng Sa là “cá voi sát thủ” Dịch Phi Dương, người có khả năng kỳ lạ để giành lợi thế. Hai con người vốn cạnh tranh gay gắt ở nơi làm việc, nay buộc phải hợp tác để cùng nhau “bơi ra biển lớn”.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 16, 2020, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Chung Giao","avatar":""},{"name":"La Hoằng Chứng","avatar":""},{"name":"Lý Vận Khánh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kissing a Shark","跟鲨鱼接吻","The Wonder Woman","跟鯊魚接吻"]', 1784690324331);
