INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-van-ta-than-mat-na-tu-la', 'Hỏa Vân Tà Thần: Mặt Nạ Tu La', 'Fire Cloud Evil God: Mask Of Chaos', 'https://phimimg.com/upload/vod/20250709-1/d1cd29c6580146f2e63621bbba69b217.jpg', 'https://phimimg.com/upload/vod/20250709-1/5acc7ebe9550e8ce51e7c4be57acbc1b.jpg', '<p>Mười tám năm trước, thế lực tà ác Hắc Vũ Hội đã lén xâm nhập vào địa bàn của Lão Tà Thần Tây Thành Dũng và đánh cắp mặt nạ Tu La. Chúng dùng mặt nạ này để giải phóng Ma Thần. Lão Tà Thần, vì muốn bảo vệ thành phố, đã quyết định hủy diệt mặt nạ và Ma Thần, nhưng ông phát hiện Ma Thần chỉ là một đứa bé sơ sinh. Lão Tà Thần nhận nuôi đứa trẻ, và vì hấp thụ một phần sức mạnh từ mặt nạ, đứa bé có được thần lực và được gọi là Tiểu Tà Thần. Cuối cùng, Tiểu Tà Thần kiểm soát được sức mạnh của mặt nạ, trở thành người kế thừa của Lão Tà Thần, và tiếp tục bảo vệ thành phố.</p>', 'Full', 1, 'single', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lương Tiểu Long","avatar":""},{"name":"Nguyên Hoa","avatar":""},{"name":"Nguyên Thu","avatar":""},{"name":"Dương Bác Tiêu","avatar":""},{"name":"Tư Na","avatar":""},{"name":"Lý Tuấn Lân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Huo Yun Xie Shen","The Mask of Shura of Fire Cloud","쿵푸허슬 2","쿵푸허슬2","쿵푸 허슬 2","火云邪神之修罗面具"]', 1784690324331);
