INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-van-ta-than-2-giang-long-thap-bat-chuong', 'Hỏa Vân Tà Thần 2: Giáng Long Thập Bát Chưởng', 'Fire Cloud Evil God 2: Eighteen Dragon Palms', 'https://phimimg.com/upload/vod/20250709-1/1ccf5066a6820959f33802647eb24e60.jpg', 'https://phimimg.com/upload/vod/20250709-1/014d21343003ce75353fa0e021d51c47.jpg', '<p>La Sát giáo sắp tổ chức lựa chọn người kế vị cho Lão Tà Thần, không ngờ rằng Lão Tà Thần lại bị Hắc Vũ tính kế hãm hại bị thương, các Tiểu Tà Thần cũng đang gặp phải nguy hiểm trước mắt. Tiểu Tà Thần tới thổ lâu để tìm cách cứu mạng, từ đó Giáng Long Thập Bát Chưởng trong truyền thuyết xuất hiện lần nữa trên giang hồ.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lương Tiểu Long","avatar":""},{"name":"Nguyên Thu","avatar":""},{"name":"Điềm Nhi","avatar":""},{"name":"Dương Bác Tiêu","avatar":""},{"name":"Lý Tuấn Lân","avatar":""},{"name":"Kim Địch","avatar":""},{"name":"Dư Vỹ Vỹ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Huo Yun Xie Shen 2","Blazing Daimon","HUO YUN XIE SHEN","火雲邪神之降龍十八掌","火云邪神之降龙十八掌"]', 1784690324331);
