INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-tinh-ai', 'Sát Nhân Tình Ái', 'Kill For Love', 'https://phimimg.com/upload/vod/20250707-1/21dcb0f9cab9e4674a7d1adce59d1782.jpg', 'https://phimimg.com/upload/vod/20250707-1/8cbd07b88af0e70d59940199129b9fe3.jpg', '<p>Hơn một năm sau cái chết của chồng, Lâm Mỹ Như vẫn kiên trì hỏi cảnh sát về tung tích kẻ sát nhân. Khi câu hỏi vẫn chưa có lời giải thì cảnh sát phát hiện cô từng có quan hệ với một người đàn ông và người này cũng đã tử vong.</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Mạc Tử Nghi","avatar":""},{"name":"Tiểu Huân","avatar":""},{"name":"Trình Dư Hi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["追兇500天"]', 1784690324331);
