INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-trai-toi-la-ho-ly', 'Bạn Trai Tôi Là Hồ Ly', 'Tale Of The Nine Tailed', 'https://phimimg.com/upload/vod/20250705-1/704ca069bec8b39fa69f2819be991900.jpg', 'https://phimimg.com/upload/vod/20250705-1/a4a386cd3fa5a2fdc8027541045dde9f.jpg', '<p>Yi Yeon (Lee Dong Wook), cửu vĩ hồ từng cai trị dãy núi Baekdudaegan như vị thần giám hộ, nhưng hiện đang sống ở thành phố. Anh có nhiệm vụ giám sát và trừng phạt những yêu quái gây hại đến cuộc sống của loài người. Anh phải chống lại sự truy lùng ráo riết của nữ đạo diễn Nam Ji Ah (Jo Bo Ah thủ vai). Bên cạnh đó, Yi Rang (Kim Bum), anh trai cùng cha khác mẹ của Yi Yeon, mang một nửa dòng máu con người. Yi Rang là một hồ ly tinh nguy hiểm với những cảm xúc thay đổi thất thường, người sẽ mang đến xung đột cho câu chuyện.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2020, 'Vietsub + Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Dong-wook","avatar":""},{"name":"Cho Bo-ah","avatar":""},{"name":"Kim Bum","avatar":""},{"name":"Kim Yong-ji","avatar":""},{"name":"Hwang Hee","avatar":""},{"name":"Kim Jung-nan","avatar":""},{"name":"An Kil-kang","avatar":""},{"name":"Kim Hee-jung","avatar":""},{"name":"Kim Kang-min","avatar":""},{"name":"Lee Tae-ri","avatar":""},{"name":"Jung Yi-seo","avatar":""},{"name":"Uhm Hyo-seop","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Сказание о кумихо","Легенда о кумихо"