INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-trai-toi-la-ho-ly', 'Bạn Trai Tôi Là Hồ Ly', 'Tale Of The Nine Tailed', 'bạn trai tôi là hồ ly tale of the nine tailed lee dong-wook cho bo-ah kim bum kim yong-ji hwang hee kim jung-nan an kil-kang kim hee-jung kim kang-min lee tae-ri jung yi-seo uhm hyo-seop сказание о кумихо легенда о кумихо 구미호뎐', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-sinh-2020', 'Tái Sinh', 'Born Again', 'https://phimimg.com/upload/vod/20250704-1/ccd99f190987074306e374943b299bf5.jpg', 'https://phimimg.com/upload/vod/20250704-1/2d3003f69d309d5828f5e24df1583e15.jpg', '<p>Ba người có số phận đan xen, du hành xuyên không gian và thời gian với kết quả ám ảnh. Đó là những năm 1980 và Thanh tra Cha Hyung Bin đã cống hiến cả cuộc đời cho chính nghĩa và trái tim của anh dành cho Ha Eun, một chủ hiệu sách bị bệnh tim, người giữ bí mật về căn bệnh của cô. Nhưng Cha Hyung Bin không phải là người duy nhất yêu Ha Eun mà kẻ giết người hàng loạt Gong Ji Chul cũng phải lòng cô. Cuộc sống của họ va chạm với kết quả bi thảm, nhưng 30 năm sau, họ tái sinh và định mệnh đưa họ trở lại với nhau. Thời gian càng trôi qua, cuộc sống mới của họ càng trở nên rối bời trong mạng lưới tàn phá của quá khứ. Họ sẽ xoay sở để trốn tránh quá khứ, hay bị buộc phải đối mặt với nó?</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 9, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Ki-yong","avatar":""},{"name":"Jin Se-yeon","avatar":""},{"name":"Lee Soo-hyuk","avatar":""},{"name":"Kim Jung-nan","avatar":""},{"name":"Kim Hee-jung","avatar":""},{"name":"Jang Won-young","avatar":""},{"name":"Cha Min-jee","avatar":""},{"name":"Lee Seo-el","avatar":""},{"name":"Choi Gwang-il","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["再生","Born Again","본 어게인"]', 1784690324331);
