INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tai-sinh-2020', 'Tái Sinh', 'Born Again', 'tái sinh born again jang ki-yong jin se-yeon lee soo-hyuk kim jung-nan kim hee-jung jang won-young cha min-jee lee seo-el choi gwang-il 再生 born again 본 어게인', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-am', 'Lửa Ấm', 'Warm Fire', 'https://phimimg.com/upload/vod/20250704-1/3ae9c0df2f7fb2d8aca058ea6c223b9b.jpg', 'https://phimimg.com/upload/vod/20250704-1/ce28b4e678e48c31dc561ef4c60cee1c.jpg', '<p>Lửa ấm xoay quanh câu chuyện về gia đình Minh và Thủy khi Khánh Ngọc - người yêu cũ của Minh cũng là cô bạn gái thân thiết của Thủy - đột ngột từ nước ngoài trở về. Ngọc tiết lộ bí mật về đứa con chung của cô với Minh khiến tất cả đều bàng hoàng. Bà Mai, mẹ Minh, vốn có cảm tình với Ngọc từ trước, nay càng có nhiều xung đột hơn với con dâu. Minh là đội trưởng đội Phòng cháy chữa cháy, Thủy là bác sĩ cấp cứu, hai con người bản lĩnh, trách nhiệm, hàng ngày đối mặt với sống - chết, được - mất. Họ không ngại hy sinh, giành lại sự sống, bảo vệ hạnh phúc cho người khác, nhưng lại chông chênh, thiếu kinh nghiệm trong việc bảo vệ hạnh phúc của chính gia đình mình. Rất may mắn khi Minh và Thủy luôn có sự đồng hành của những người anh em cùng chí hướng, thấu hiểu lẫn nhau. Tiến và Hoàng - hai chàng lính cấp dưới cùng vào sinh ra tử với Minh. Bác sĩ Văn, bác sĩ Khánh - người thầy, người đồng nghiệp của Thủy. Họ đã luôn bên cạnh san sẻ và tiếp thêm niềm tin cho Minh và Thủy trước mọi biến cố. Minh, Thủy, Tiến, Hoàng, ông Văn hay Khánh, mỗi người đều có những nỗi niềm, những vấn đề trong cuộc sống, những nuối tiếc trong nghề nghiệp... nhưng họ có chung một đam mê đó là &quot;luôn sống vì người khác&quot;. Sau khi chứng kiến những mất mát, chấp nhận hai chữ &quot;hy sinh&quot;, liệu họ có còn giữ được lửa đam mê với nghề? Hạnh phúc có còn sau những tổn thương và sứt mẻ niềm tin? Những chiến sĩ thép sau lớp áo màu xanh tím than, những người hùng áo trắng có thể là anh hùng đưa tổ ấm của mình vượt qua những giông bão đời thường?</p>', 'Hoàn Tất (52/52)', 52, 'series', 'completed', 11, 2020, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Trương Minh Quốc","avatar":""},{"name":"Thái Thu Quỳnh","avatar":""},{"name":"Đỗ Thúy Hằng","avatar":""},{"name":"Trọng Trinh","avatar":""},{"name":"Lan Hương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324331);
