INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-tung-centimet', 'Yêu Từng Centimet', 'The Centimeter Of Love', 'https://phimimg.com/upload/vod/20250702-1/30023e4a209bc76b2890d951fdfc5531.jpg', 'https://phimimg.com/upload/vod/20250702-1/e8b3348d9927f1c2c83d647f9072834a.jpg', '<p>Bác sĩ ưu tú Từ Thanh Phong và nữ cơ trưởng bản lĩnh Quan Vũ Tinh thường chạm trán trong những tình huống vừa dở khóc dở cười vừa căng thẳng hồi hộp. Qua nhiều lần sát cánh bên nhau, cả hai dần nảy sinh tình cảm. Oái ăm thay, họ còn phải vượt qua rào cản từ hai bên gia đình vốn cũng có những mâu thuẫn không nhỏ.</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 7, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đồng Lệ Á","avatar":""},{"name":"Đồng Đại Vỹ","avatar":""},{"name":"Tả Tiểu Thanh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Centimeter of Love","爱的厘米","爱的厘米 2020"]', 1784690324331);
