INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-chong-xam-lang-mien-nhiet-doi', 'Cuộc Chiến Chống Xâm Lăng: Miền Nhiệt Đới', 'Occupation: Rainfall', 'https://phimimg.com/upload/vod/20240108-1/884ca367bee3ae7e2f50b80547631182.jpg', 'https://phimimg.com/upload/vod/20240108-1/bb85c2b049e5ac153c40b3c274b64ab3.jpg', '<p>Con người xâm lược lãnh thổ của nhau, nhưng nếu họ lại là đối tượng để xâm lăng của người ngoài hành tinh thì sao? Lấy bối cảnh 2 năm sau khi các kẻ thù ngoài vũ trụ hạ cánh xuống Trái Đất, những người sống sót phải chiến đấu trong một cuộc chiến không cân sức.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dan Ewing","avatar":""},{"name":"Daniel Gillies","avatar":""},{"name":"Temuera Morrison","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324331);
