INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-cha-gia', 'Người Cha Già', 'The Father', 'https://phimimg.com/upload/vod/20250624-1/5bbc5ffc296eae22d6181971d642116d.jpg', 'https://phimimg.com/upload/vod/20250624-1/b9e074d35c229289a0c32818ad335be5.jpg', '<p>Bộ phim kể câu chuyện qua đôi mắt của Anthony, ông già 80 tuổi mắc bệnh Alzheimer và không nhớ mặt con gái mình. Từ đó, tình &quot;cha - con&quot; bỗng trở thành cách viết khác của &quot;yêu thương - cam chịu&quot;.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Anthony Hopkins","avatar":""},{"name":"Olivia Colman","avatar":""},{"name":"Mark Gatiss","avatar":""},{"name":"Olivia Williams","avatar":""},{"name":"Imogen Poots","avatar":""},{"name":"Rufus Sewell","avatar":""},{"name":"Ayesha Dharker","avatar":""},{"name":"Roman Zeller","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["父亲","老父","爸爸可否不要老","Otec","ความทรงจำ ความรัก ความลืม","더 파더","The Father"]', 1784690324331);
