INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-cha-gia', 'Người Cha Già', 'The Father', 'người cha già the father anthony hopkins olivia colman mark gatiss olivia williams imogen poots rufus sewell ayesha dharker roman zeller 父亲 老父 爸爸可否不要老 otec ความทรงจำ ความรัก ความลืม 더 파더 the father', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-thien-than-thu-cung-ky-giang-the', 'Ngự Thiên Thần Thú: Cùng Kỳ Giáng Thế', 'The Holy Beasts: The Resurrection Of Ancient Beast', 'https://phimimg.com/upload/vod/20250624-1/a787970367e7a65c50171ad4e8e70367.jpg', 'https://phimimg.com/upload/vod/20250624-1/eebd1028f5967c7bdb6068039aaf34eb.jpg', '<p><span style="text-wrap-mode: wrap;">Bộ phim kể về thiên sư Thiên Phóng và Nhược Linh, những người hỗ trợ Thái tử trong việc tiêu diệt Chuột Yêu, từ đó phá được một vụ án lớn gây chấn động kinh kỳ. Khi hoàng thành tạm thời yên ổn, một vụ án mạng mới lại xảy ra ở làng chài nhỏ. Bộ khoái Nhị Lượng Ngân và Nhược Linh điều tra và phát hiện các hiện trường vụ án tạo thành một trận pháp ngũ mang tinh (ngôi sao 5 cánh), với trung tâm chính là hoàng cung – nơi ẩn náu của yêu thú Qiong Qi (Cùng Kỳ). Thái tử lập tức quay về cung thì phát hiện Quốc sư đã sát hại hoàng thượng và còn gieo rắc lời đồn vu oan cho Thái tử. Khi Thiên Phóng và Nhược Linh tìm ra Cùng Kỳ thì Quốc sư cũng đến. Lúc này, Nhị Lượng Ngân phát hiện Quốc sư chính là sư huynh của mình. Thì ra nhiều năm qua, Quốc sư đã tẩu hỏa nhập ma, vì Cùng Kỳ mà hành động điên cuồng, âm mưu sử dụng yêu lực để thống trị thiên hạ. Thiên Phóng và Nhị Lượng Ngân giao đấu với Quốc sư, nhưng không thể đánh bại hắn khi hắn đã hấp thụ yêu lực của Cùng Kỳ. Khi sư thúc Nhị Lượng Ngân ngã xuống và Thiên Phóng cận kề cái chết, Nhược Linh bị nhốt trong kết giới dần nhớ lại thân phận thật sự của mình – là một cửu vĩ miêu yêu (yêu hồ 9 đuôi hóa thân thành mèo)...</span></p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tử Văn","avatar":""},{"name":"Vân Ca","avatar":""},{"name":"Diệp Tiểu Khai","avatar":""},{"name":"Lý Tư Huyên","avatar":""},{"name":"Lưu Kiệt Dương","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Yu Tian Shen Shou","Imperial Beast 2","Imperial God Emperor 2","御天神兽之穷奇降世"]', 1784690324331);
