INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-tien-sinh', 'Quái Vật Tiên Sinh', 'Monster Run', 'https://phimimg.com/upload/vod/20250623-1/9652f08f6020f0ee116c3270af9bfdb5.jpg', 'https://phimimg.com/upload/vod/20250623-1/3188ab35d55ff2c8f77b300c5958a2b1.jpg', '<p>&quot;Trên đời không có quái vật&quot; - Quý Mạt dùng lời nói dối để được ra khỏi viện tâm thần. Tình cờ gặp A Mạnh - một thợ săn quái vật, cô bắt đầu hành trình mới và dần chấp nhận sự khác biệt của bản thân.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dư Văn Lạc","avatar":""},{"name":"Xuân Hạ","avatar":""},{"name":"Huệ Anh Hồng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mr. Monster","Guai wu xian sheng","Monster Run","怪物先生"]', 1784690324331);
