INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-dien-ha', 'Lang Điện Hạ', 'The Wolf', 'https://phimimg.com/upload/vod/20250623-1/5d8bbd9410dffaede0fb4f29cd1f2c71.jpg', 'https://phimimg.com/upload/vod/20250623-1/66137968d543fb124f473ed6b4a488f1.jpg', '<p>Bộ phim xoay quanh nhân vật Chu Hữu Văn (do Vương Đại Lục đóng) vô tình rơi xuống vực thẳm và được cứu sống bởi bầy sói. Cậu tình cờ ra tay cứu mạng quận chúa Mã Trích Tinh (Lý Thấm thủ vai) là con gái của Khuê Châu Thành Chủ - Mã Anh. Câu chuyện xảy ra vào cuối thời Đường, Chu Ôn soán ngôi lập lên nhà Lương và có duyên gặp gỡ nên đã nhận cậu bé làm nghĩa tử, đặt tên là Chu Hữu Văn. 10 năm sau cậu được phong làm Bột Vương và bắt đầu nảy sinh tình cảm với Mã Trích Tinh. Từ đây cả hai phải đương đầu với những sóng gió tranh đoạt để bảo vệ tình yêu toàn vẹn.</p>', 'Hoàn Tất (49/49)', 49, 'series', 'completed', 9, 2020, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Đại Lục","avatar":""},{"name":"Lý Thấm","avatar":""},{"name":"Tiêu Chiến","avatar":""},{"name":"Tân Chỉ Lôi","avatar":""},{"name":"Quách Thư Dao","avatar":""},{"name":"Đinh Dũng Đại","avatar":""},{"name":"Lâm Hựu Uy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["狼殿下","The Wolf","랑전하"]', 1784690324331);
