INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-du-2', 'Sóng Dữ 2', 'Shock Wave 2', 'https://phimimg.com/upload/vod/20250621-1/9cfe3d36fe57a8a8d9fecf7a496f73df.jpg', 'https://phimimg.com/upload/vod/20250621-1/7974133d70c54dfb8ce739d8065baeee.jpg', '<p>Sóng Dữ 2 kể rằng một nơi nào đó ở Hồng Kông xảy ra vụ án đánh bom, chuyên gia gỡ bom về hưu Phan Thừa Phong (Lưu Đức Hoa) bởi vì hôn mê ở hiện trường nên bị cảnh sát hoài nghi có liên quan đến vụ việc. Phan Thừa Phong sau khi tỉnh lại chỉ có thể vừa chạy trốn vừa tìm chân tướng, nhưng Đổng Trác Văn (Lưu Thanh Vân) và bạn gái cũ Bàng Linh (Nghê Ni) lại kể cho anh nghe hai đoạn quá khứ không giống nhau. Những vụ án đánh bom có kế hoạch liên tiếp xảy ra, chân tướng ngày càng khó bề phân biệt.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Tạ Quân Hào","avatar":""},{"name":"Lưu Thanh Vân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shock Wave: Hong Kong Destruction","คนคมถล่มนิวเคลียร์","Shock Wave 2","Onda de Choque 2","拆弹专家2","Chak dan juen ga 2","拆彈專家2"]', 1784690324331);
