INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-huong-cang-ngoai-truyen-thanh-tra-thap-uc', 'Trùm Hương Cảng Ngoại Truyện: Thanh Tra Thập Ức', 'Chasing The Dragon: The One Billion Dollar Inspector', 'https://phimimg.com/upload/vod/20250619-1/9e8c004baab33de5dc8dde615e35456b.jpg', 'https://phimimg.com/upload/vod/20250619-1/e56fa21dd60043d047689f2f9a253fc7.jpg', '<p>Hồng Kông những năm 6-70, cảnh sát và xã hội đen cấu kết. Lúc này, Từ Lạc (Vương Hạo Tín đóng) vì khó khăn nên bỏ học làm cảnh sát. Vì phá được một vụ án mà đắc tội cháu thanh tra Long (Lý Tử Hùng đóng), Từ Lạc bị cô lập và chèn ép. Khi giải quyết một vụ tranh chấp, anh đã quen biết thiên kim Bạch Trân Ni (Từ Đông Đông đóng). Giữa người bạn gái luôn bên mình – A Trinh (Vân Thiên Thiên đóng) và người có thể giúp mình thoát khỏi khó khăn, anh phải chọn giữa tình yêu và quyền lực. Từ Lạc sẽ từng bước trở thành thanh tra truyền kỳ ra sao…</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vincent Wong Ho-Shun","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Xu Dongdong","avatar":""},{"name":"Yun Qianqian","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Jazz Lam Tsz-Sin","avatar":""},{"name":"Vincent Wan Yeung-Ming","avatar":""},{"name":"Lawrence Chou Chun-Wai","avatar":""},{"name":"David Wayne Fish","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chasing the Dragon","追龙番外篇之十亿探长"]', 1784690324331);
