INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ke-nhiem-namsan', 'Người Kế Nhiệm Namsan', 'The Man Standing Next', 'https://phimimg.com/upload/vod/20250619-1/9a85020f976f922df641296424533aca.jpg', 'https://phimimg.com/upload/vod/20250619-1/203d184b800432f85cc811df57ea46f0.jpg', '<p>Bộ phim mang đề tài chính trị hình sự của Hàn Quốc vào những năm 1970. Chủ đề chính xoay quanh cuộc ám sát tổn thống của một nhân viên làm việc dưới cơ của vị tổn thống. Liệu có gì uẩn khúc quanh vụ án này, những người liên quan thì sao? Hãy cùng đợi xem phim để biết rõ tường tận là tại sao nha!</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Byung-hun","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Kwak Do-won","avatar":""},{"name":"Lee Hee-jun","avatar":""},{"name":"Kim So-jin","avatar":""},{"name":"Seo Hyun-woo","avatar":""},{"name":"Kim Min-sang","avatar":""},{"name":"Kim Hong-pa","avatar":""},{"name":"Park Ji-il","avatar":""},{"name":"Ji Hyun-jun","avatar":""},{"name":"Park Seong-geun","avatar":""},{"name":"Lee San-ho","avatar":""},{"name":"Kim Seung-hoon","avatar":""},{"name":"Ju Seok-tae","avatar":""},{"name":"Lee Yang-hee","avatar":""},{"name":"Jo Hye-joo","avatar":""},{"name":"John D. Michaels","avatar":""},{"name":"Lee Seung-jin","avatar":""},{"name":"Park","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Chiefs of Namsan","nam-san-eui bu-jang-deul","Namsanui bujangdeul","The Man Standing Next","ケーシーアイエー ナムサンのぶちょうたち","Kẻ ám sát tổng thống","KCIA 南山の部長たち：2020","남산의 부장들"]', 1784690324331);
