INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-ke-nhiem-namsan', 'Người Kế Nhiệm Namsan', 'The Man Standing Next', 'người kế nhiệm namsan the man standing next lee byung-hun lee sung-min kwak do-won lee hee-jun kim so-jin seo hyun-woo kim min-sang kim hong-pa park ji-il ji hyun-jun park seong-geun lee san-ho kim seung-hoon ju seok-tae lee yang-hee jo hye-joo john d. michaels lee seung-jin park chiefs of namsan nam-san-eui bu-jang-deul namsanui bujangdeul the man standing next ケーシーアイエー ナムサンのぶちょうたち kẻ ám sát tổng thống kcia 南山の部長たち：2020 남산의 부장들', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('le-hap-duong-phen', 'Lê Hấp Đường Phèn', 'Skate Into Love', 'https://phimimg.com/upload/vod/20250618-1/759a7f5e2f2f3281051cb3b8af04de00.jpg', 'https://phimimg.com/upload/vod/20250618-1/378d9e60659100fb731d39733d38b961.jpg', '<p>Lê Hấp Đường Phèn là tác phẩm được chuyển thể từ tiểu thuyết cùng tên của nhà văn nổi tiếng Tử Tiểu Thất kể về mối tình oan gia ngọt ngào giữa thiếu nữ trượt băng tốc độ Đường Tuyết (Ngô Thiến) và nam thần khúc côn cầu trên băng Lê Ngữ Băng (Trương Tân Thành). Đường Tuyết và Lê Ngữ Băng là thanh mai trúc mã, bạn học cùng bàn suốt năm tháng tiểu học, nhưng vì tính cách đối lập mà cả hai luôn gây gổ, tranh cãi và giận dỗi rất trẻ con. Ở trường tiểu học, Lê Ngữ Băng nhát gan yếu ớt luôn bị đại vương cùng bàn Đường Tuyết bắt nạt, và điểm chung duy nhất là họ đều có một giấc mơ trượt băng.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Thiến","avatar":""},{"name":"Trương Tân Thành","avatar":""},{"name":"Chu Lâm Đại","avatar":""},{"name":"Sái Trác Nhã","avatar":""},{"name":"Đổng Tình","avatar":""},{"name":"Hà Dữ","avatar":""},{"name":"Phó Tân Bác","avatar":""},{"name":"Mã Hạo Khiết","avatar":""},{"name":"Sái Chân","avatar":""},{"name":"Thịnh Hải Đăng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Любовь на коньках","Skate Into Love","Bing Tang Dun Xue Li","冰糖炖雪梨"]', 1784690324331);
