INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-binh-thuong', 'Người Bình Thường', 'Normal People', 'https://phimimg.com/upload/vod/20250617-1/502b68400c0f69751fa234f6bb00bf32.jpg', 'https://phimimg.com/upload/vod/20250617-1/c3f37a714f19ee7505bb22803da916c4.jpg', '<p>Chuyện tình oan trái nhiều cảnh 18+ nhưng &quot;sang - xịn - mịn&quot; ăn đứt 365 Days.

12 tập phim do BBC Three sản xuất, mỗi tập vọn vẹn 30 phút đã lột tả một cách trọn vẹn những tinh túy và chất cảm xúc trong áng văn của tác giả trẻ Sally Rooney. Đó là những đau khổ và dằn vặt của hai nhân vật chính trong một mối quan hệ mở, không tên, on and off, vốn chẳng hề lạ lẫm gì ở những người trẻ thuộc thế hệ Millennials.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 12, 2020, 'Vietsub', 'FHD', 'Ireland', 0, '[{"name":"Paul Mescal","avatar":""},{"name":"Daisy Edgar-Jones","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["正常人","普通人","Normaaleja ihmisiä","常人","노멀 피플","노말 피플","Normāli cilvēki","Pessoas normais","Нормальные люди","‎Normal İnsanlar‎","Звичайні люди","Normal People"]', 1784690324331);
