INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-thien-nha-sat', 'Tam Thiên Nha Sát', 'Love Of Thousand Years', 'https://phimimg.com/upload/vod/20250611-1/e01ed484e4619a2818af0488272a47f8.jpg', 'https://phimimg.com/upload/vod/20250611-1/f04e214c5456e337a71e429ce55a04da.jpg', '<p>Tam thiên nha sát được chuyển thể từ tiểu thuyết cùng tên của Thập Tứ Lang. Tam Thiên Nha Sát có nghĩa là “Ba ngàn con quạ ta giết hết/Cùng chàng yên giấc đến bình minh” (Tam thiên thế giới nha sát tẫn/Dữ quân cộng tẩm đáo thiên minh). Câu chuyện xoay quanh công chúa nước Đại Yến - Đế Cơ lại phải gánh chịu cùng lúc cả hai nỗi đau khi mới chỉ ở cái tuổi mười ba. Được cung nữ thân cận và tiên sinh từng dạy tiên thuật trong hoàng cung cứu giúp, nàng từ một lá ngọc cành vàng, mười đầu ngón tay không dính nước trở thành người mạnh mẽ, cứng cáp.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2020, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trịnh Nghiệp Thành","avatar":""},{"name":"Triệu Lộ Tư","avatar":""},{"name":"Vương Mộng Lệ","avatar":""},{"name":"Lưu Dị Thông","avatar":""},{"name":"Tăng Y Y","avatar":""},{"name":"Đái Vân Phàm","avatar":""},{"name":"Mao Phương Viên","avatar":""},{"name":"Vương Hành Hân","avatar":""},{"name":"Lý Lộ Kỳ","avatar":""},{"name":"Lý Minh Tuấn","avatar":""},{"name":"Hứa Mộng Viên","avatar":""},{"name":"Trương Đỉnh Đỉnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a2