INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-thien-nga-dam-cuoi-hoang-gia', 'Công Chúa Thiên Nga: Đám Cưới Hoàng Gia', 'The Swan Princess: A Royal Wedding', 'https://phimimg.com/upload/vod/20250610-1/983306347785b82887b2910de7ddb575.jpg', 'https://phimimg.com/upload/vod/20250610-1/56955e9931bca9c748c481dc7f78c786.jpg', '<p>Cuộc hành trình của công chúa Odette và hoàng tử Derek với những người bạn vươn buồm khám phá vùng đất ma thuật Cathay. Công chúa Mei Li đang dự định để cưới tình yêu của đời nàng là Chen nhưng bị một pháp sư tà ác là Fang ngầm âm mưu phá hoại. Với sự giúp đỡ của Odette, liệu Mei Li có tìm lại được tình yêu của đời mình?</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nina Herzog","avatar":""},{"name":"Yuri Lowenthal","avatar":""},{"name":"Vivian Lu","avatar":""},{"name":"Joseph Medrano","avatar":""},{"name":"Christine Lakin","avatar":""},{"name":"Gardner Jaas","avatar":""},{"name":"Doug Stone","avatar":""},{"name":"Alexandre Chen","avatar":""},{"name":"Hao Feng","avatar":""},{"name":"Francis Huang","avatar":""},{"name":"Clayton James","avatar":""},{"name":"Ben King","avatar":""},{"name":"Muet Li","avatar":""},{"name":"Rachanee Lumayno","avatar":""},{"name":"Brian Nissen","avatar":""},{"name":"Stephanie Sheh","avatar":""},{"name":"George Tang","avatar":""},{"name":"Lynna Yee","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]'