INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-song-con', 'Đêm Sống Còn', 'Survive The Night', 'https://phimimg.com/upload/vod/20250606-1/66ed33440360da238527861a8c7aa55b.jpg', 'https://phimimg.com/upload/vod/20250606-1/6975addbb98d492b4ff7b9f79cc7fbb9.jpg', '<p>Những tên cướp đang bị thương và chạy trốn khỏi sự săn lùng của cảnh sát. Để tránh bị bắt, chúng không vào bệnh viện mà chọn cách theo chân một bác sĩ về nhà riêng để ép buộc bác sĩ đó chữa trị cho chúng. Sau khi đột nhập vào nhà, chúng đã bắt trói và uy hiếp cả gia đình.</p>', 'Full', 1, 'single', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chad Michael Murray","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Lydia Hull","avatar":""},{"name":"Tyler Jon Olson","avatar":""},{"name":"Shea Buckner","avatar":""},{"name":"Jessica Abrams","avatar":""},{"name":"Riley Wolfe Rach","avatar":""},{"name":"Charlie Alvarado","avatar":""},{"name":"Jef Holbrook","avatar":""},{"name":"Natalie DiDonato","avatar":""},{"name":"Ravare Elise Rupert","avatar":""},{"name":"Sara Lynn Holbrook","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Long Night","Überlebe die Nacht","서바이브 더 나이트","Survivre","Sobrevive la noche","Survive the Night"]', 1784690324331);
