INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-hoi-cong-ly', 'Truy Hồi Công Lý', 'Burning', 'https://phimimg.com/upload/vod/20250601-1/f7627e2f8998c942b50045bf3b0ce358.jpg', 'https://phimimg.com/upload/vod/20250601-1/979d18c78168d5e71d46fe39b831dc0a.jpg', '<p>Cao Phong, một cảnh sát nhân dân xuất thân trong gia đình cảnh sát, thông qua một vụ án vứt xác phát hiện ra một kỳ án liên quan đến ông nội và bố cách đây nhiều năm trước. Cao Phong một mực tin vào sự trong sạch của bố và ông nội, liền tiến hành điều tra lại vụ án cũ này. Trong quá trình điều tra, mặc dù Cao Phong gặp vô vàn khó khăn, bắt đầu mất phương hướng, nhưng chân tướng cũng ngày càng gần hơn...</p>', 'Hoàn Tất (51/51)', 51, 'series', 'completed', 7, 2020, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Kinh Siêu","avatar":""},{"name":"Trương Giai Ninh","avatar":""},{"name":"Đàm Khải","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["燃烧的DNA","Ran Shao","Ran Shao de DNA","Burning DNA","燃烧"]', 1784690324331);
