INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xuan-khong-so-hai', 'Thanh Xuân Không Sợ Hãi', 'Young Days No Fears', 'https://phimimg.com/upload/vod/20250601-1/a0390fb4e13c7645534f1cdedc6e0e5a.jpg', 'https://phimimg.com/upload/vod/20250601-1/29f4bec27b97d716370ce46a6fd0fd66.jpg', '<p>Sáu cô bạn gái thân thiết Minh San, Điềm Điềm, Đan Phương, Mạn Ni, Phượng Châu và Cảnh Phàm có tính cách và hoàn cảnh khác biệt cùng nhau đối mặt với thử thách mang tên &quot;cuộc đời&quot;. Dù gặp phải vấn đề nan giải gì trong tình yêu hay công việc, sáu người bạn vẫn dũng cảm đương đầu vì họ luôn có nhau.</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 17, 2020, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Đường Vũ Triết","avatar":""},{"name":"Thái Hoàng Nhữ","avatar":""},{"name":"Vương Gia Lương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我的青春沒在怕"]', 1784690324331);
