INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minh-nguyet-tung-chieu-giang-dong-han', 'Minh Nguyệt Từng Chiếu Giang Đông Hàn', 'The Moon Brightens For You', 'https://phimimg.com/upload/vod/20250601-1/e4d24a5c9d8d39098b94c8e77b062326.jpg', 'https://phimimg.com/upload/vod/20250601-1/b04f4767bfebcf47034fd2ebf12df5ab.jpg', '<p>Bộ phim được chuyển thể từ tiểu thuyết cùng tên của Đinh Mặc. Cốt truyện xoay quanh ba nhân vật: Chiến Thanh Hoằng, Ôn Hựu, Lâm Phóng, lấy bối cảnh giang hồ hỗn loạn, triều đình lực bất tòng tâm. Cô gái vô tư Thanh Hoằng rời khỏi vòng tay cha mẹ, tiến vào giang hồ để trải nghiệm, tham gia đại hội võ lâm rồi bị cuốn luôn vào vòng xoáy giang hồ và triều đình từ đấy.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2020, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Vu Mông Lung","avatar":""},{"name":"Hình Phi","avatar":""},{"name":"Mễ Nhiệt","avatar":""},{"name":"Mã Nguyệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["明月曾照江东寒"]', 1784690324331);
