INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-man-trong-tay-em', 'Lãng Mạn Trong Tay Em', 'Lost Romance', 'https://phimimg.com/upload/vod/20250601-1/cea995b1b2a0e8c678b3035cffbd14f4.jpg', 'https://phimimg.com/upload/vod/20250601-1/c89954fc2a737c86917227eb502bcba8.jpg', '<p>Yêu thầm CEO Hạ Thiên Hành ở tòa nhà đối diện, biên tập viên tiểu thuyết Trịnh Hiểu Âu thường xuyên nhìn trộm anh. Trong một lần như thế, cô vô tình chứng kiến cảnh anh bị đẩy từ tầng thượng xuống, rơi vào hôn mê. Tối hôm đó, Hiểu Âu bị cuốn vào một cuốn tiểu thuyết mà cô là nữ phụ phản diện và các nhân vật khác là &quot;bản sao&quot; của những người xung quanh cô ngoài đời thực, bao gồm cả Hạ Thiên Hành. Không cam tâm làm nữ phụ, Hiểu Âu cố gắng thay đổi số phận để trở thành nữ chính và quay về thế giới thực cứu người mình yêu.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 17, 2020, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Hứa Mạnh Triết","avatar":""},{"name":"Liên Thần Tuờng","avatar":""},{"name":"Liệu Dịch Tuyền","avatar":""},{"name":"Thái Thuỵ Tuyết","avatar":""},{"name":"Trương Lập Ngang","avatar":""},{"name":"Tống Vân Hoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["浪漫输给你","The Overbearing CEO Fell In Love With Me","Romance Loses To You","浪漫輸給你"]', 1784690324331);
