INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-thap-tu-chinh-cuoi-cung-cua-chung-ta-hay-su-troi-day-cua-mot-the-gioi-moi-phan-1', 'Cuộc Thập Tự Chinh Cuối Cùng Của Chúng Ta Hay Sự Trỗi Dậy Của Một Thế Giới Mới (Phần 1)', 'Our Last Crusade Or The Rise Of A New World (Season 1)', 'https://phimimg.com/upload/vod/20250531-1/edc32a71a7121dfb45ec443ab4767dcc.jpg', 'https://phimimg.com/upload/vod/20250531-1/92f36e11fc1bd8e4f1422b77b15045c1.jpg', '<p>Một cuộc đại chiến đã nổ ra trong nhiều năm giữa phe Empire và phe Nebulis, thuở là vương quốc của những nữ pháp sư- cho đến khi các hiệp sĩ trẻ tuổi nhận được danh hiệu mạnh nhất từ phe Empire để gặp gỡ công chúa của phe đối thủ. Mặc dù họ là kẻ thù truyền kiếp, thề rằng không đội trời chung nhưng vị hiệp sĩ này đã bị lay động trước vẻ đẹp và tính cách của cô nàng công chúa. Còn công chúa thì lại bị lay động bởi sức mạnh và cách sống của chàng hiệp sĩ. Một mối tình bắt đầu có cho phép cuộc chiến kết thúc hay không?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yusuke Kobayashi","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Kaori Ishihara","avatar":""},{"name":"Nao Shiraki","avatar":""},{"name":"Shunichi Toki","avatar":""},{"name":"Yumiri Hanamori","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Jun Kasama","avatar":""},{"name":"Azumi Waki","avatar":""},{"name":"Aya Hisakawa","avatar":""},{"name":"Hikaru Midorikawa","avatar":""},{"name":"Konomi Kohara","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["这是你与我的最后战场，或是开创世界的圣战","Kimi to Boku no Saigo no Senjou, Aruiha Sekai ga Hajimaru Seisen","Our Last Crusade or the Rise of a New World","Kimi to Boku no Saigo no Senjou, Aruiwa Sekai ga Hajimaru Seisen","Kimi to Boku no Saigo no Senjou, Arui wa Sekai ga Hajimaru Seisen","Kimisen","Kimi to Boku no Saigo no Senjō, Arui wa Sekai ga Hajimaru Seisen","Kimi to Boku No Saigo No Senjou Aruiwa Sekai Ga Hajimaru Seisen","キミと僕の最後の戦場、あるいは世界が始まる聖戦 Season Ⅱ","Наше поле брани или Священная война зарождения мира","這是妳與我的最後戰場，或是開創世界的聖戰","The Last Battlefield Between You and I, or Perhaps the Beginning of the World''s Holy War","You, Me, and Our Last Battlefield, or the Beginning of the World''s Last Crusade","The War Ends the World / Raises the World","キミと僕の最後の戦場、あるいは世界が始まる聖戦"]', 1784690324331);
