INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-phong-dao', 'Trảm Phong Đao', 'The Blade Of Wind', 'https://phimimg.com/upload/vod/20250527-1/82c6c612ac85ae8f9c7e6d2204311554.jpg', 'https://phimimg.com/upload/vod/20250527-1/49140e75608608ecc44ac3b5e4531f3f.jpg', '<p>Đều bị cuốn vào sóng gió do “xà nhân” gây nên, tuy có hoàn cảnh, mục đích và tính cách khác biệt nhưng ba vị nữ hiệp vẫn quyết tâm cùng lên đường, kề vai sát cánh để tìm ra chân tướng.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Duy Ni","avatar":""},{"name":"Trần Phi","avatar":""},{"name":"Trần Chiêu Vũ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["斩风刀"]', 1784690324331);
