INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('y-ta-hac-am', 'Y Tá Hắc Ám', 'Saint Maud', 'https://phimimg.com/upload/vod/20250526-1/c16617415ad2d694e3d85a2ee2a8d09e.jpg', 'https://phimimg.com/upload/vod/20250526-1/48fe37fcacc8ea29c64b9b2a968e8b1e.jpg', '<p>Saint Maud kể về nhân vật nữ chính tên Maud - một y tá mới chuyển đến một nhà an dưỡng để chăm sóc và cầu nguyện cho các bệnh nhân ở giai đoạn cuối đời.Maud là một cô gái khép kín, đơn độc, từ đó khiến cô phải tìm đến niềm tin tôn giáo.Tuy nhiên một biến cố xảy đến trong quá khứ, khi cô còn làm y tá và vô tình hại chết một bệnh nhân ngay trên bàn mổ.Đau đớn bởi lỗi lầm trước kia, Maud tin rằng có một thế lực &quot;chúa trời&quot; đang ngự trị ngay trong con người cô, giúp cô vượt qua nỗi đau và sự trống trải để có thể cầu phúc cho linh hồn của các bệnh nhân tại nhà an dưỡng....</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Morfydd Clark","avatar":""},{"name":"Jennifer Ehle","avatar":""},{"name":"Lily Frazer","avatar":""},{"name":"Lily Knight","avatar":""},{"name":"Rosie Sansom","avatar":""},{"name":"Caoilfhionn Dunne","avatar":""},{"name":"Marcus Hutton","avatar":""},{"name":"Carl Prekopp","avatar":""},{"name":"Noa Bodner","avatar":""},{"name":"Takatsuna Mukai","avatar":""},{"name":"Sona Vyas","avatar":""},{"name":"Faith Edwards","avatar":""},{"name":"Brian Jackson","avatar":""},{"name":"Jonathan Milshaw","avatar":""},{"name":"Turlough Convery","avatar":""},{"name":"Rose Knox-Peebles","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Santa Maud","Спасительница [Saint 