INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nao-minh-cung-mo', 'Nào Mình Cùng Mơ', 'Dreambuilders', 'https://phimimg.com/upload/vod/20250526-1/93b6180201363cbc30baf6cc80dbfe52.jpg', 'https://phimimg.com/upload/vod/20250526-1/08ee137329705b16b855960d5e5f1f60.jpg', '<p>Nào Mình Cùng Mơ là chuyến hành trình đầy màu sắc của cô bé Minna vào xứ sở của những giấc mơ, nơi có những “thợ xây mơ” dễ thương và rộn chuyện. Cuộc sống của Minna đảo lộn khi cha cô tiến thêm bước nữa. Cô em gái Jenny mới đến là một “hot Instagram” khó ưa. Vì thế mà Minna quyết định xâm nhập và điều khiển giấc mơ, dạy cho Jenny một bài học. Và những màu nhiệm cũng như sự cố không ngờ đã xảy đến với “công xưởng giấc mơ”.</p>', 'Full', 1, 'hoathinh', 'completed', 26, 2020, 'Vietsub + Lồng Tiếng', 'FHD', 'Đan Mạch', 0, '[{"name":"Emilie Kroyer Koppel","avatar":""},{"name":"Caroline Vedel Larsen","avatar":""},{"name":"Rasmus Botoft","avatar":""},{"name":"Martin Buch","avatar":""},{"name":"Ditte Hansen","avatar":""},{"name":"Stig Hoffmeyer","avatar":""},{"name":"Mia Lerdam","avatar":""},{"name":"Alberte Winding","avatar":""},{"name":"Kim Hagen Jensen","avatar":""},{"name":"Audrey D''Hulstère","avatar":""},{"name":"Maxime Donnay","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Minna & The Dreambuilders","Dreambuilders","Mina und die Traumzauberer","Sapnu kurejai","Drømmebyggerne","A Fabrica dos Sonhos","מיה ובוני החלומות","Sueños S.A.","Unenägude meistrid","ドリーム・ビルダーズ　ミーナと秘密の夢工場","드림빌더","Sonhos S.A.","A Fábrica de Sonhos","Mina en de dromenbouwers","梦境历险记","Droemmebyggerne","Tvornica sno