INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-me-kong', 'Truyền Thuyết Mê Kông', 'The Legend Of The Mekong River', 'https://phimimg.com/upload/vod/20250525-1/02730cbbb12696f6daf7312aedb87026.jpg', 'https://phimimg.com/upload/vod/20250525-1/77ff77b1b73410d917c9bedb50884fc5.jpg', '<p>Bộ phim Truyền Thuyết Mê Kông (tên gốc là Khum Sab Lum Kong) thuộc thể loại phim hành động hiện đại pha nhiều yếu tố thần thoại được sản xuất bởi Thái Lan vào năm 2020. Phim kể về cuộc hành trình phiêu lưu tìm về thành cô Nakusa, một thành phố chỉ xuất hiện trong truyền thuyết mà không hề có bằng chứng chứng minh liệu nó có tồn tại thật sự hay không. Phim có sự tham gia của các diễn viên nổi tiếng xứ chùa vàng như Art Pasut Banyam, Fluke Jira Danbawornkiat, Mungkorn Paphawin, Pinky Savika Chaiyadech,…</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 9, 2020, 'Vietsub + Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Savika Chaiyadej","avatar":""},{"name":"Pasut Banyam","avatar":""},{"name":"Chartchai Ngamsan","avatar":""},{"name":"Phuripan Sapsangsawat","avatar":""},{"name":"Mungkorn Paphawin Hongcheon","avatar":""},{"name":"Sarawut Martthong","avatar":""},{"name":"Chokchai Boonvoramatee","avatar":""},{"name":"Jira Danbawornkiat","avatar":""},{"name":"Jirawat Wachirasarunpat","avatar":""},{"name":"Vanessa Herrmann","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Khum Sab Lum Kong","ขุมทรัพย์ลำโขง"]', 1784690324332);
