INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-boc-nguoi-may', 'Vỏ Bọc Người Máy', 'Almost Human', 'https://phimimg.com/upload/vod/20250523-1/8a7e67b077b46b8ffc7d95f12de81eeb.jpg', 'https://phimimg.com/upload/vod/20250523-1/36621236908b2f69f4f11a97009798e8.jpg', '<p>Tiến sĩ Lâm bí mật tạo ra một robot hình người để thỏa mãn bản thân, nhưng robot phát triển ý thức riêng. Nó dùng &quot;công nghệ đen&quot; thay thế da và giả dạng cô gái tên là Tô Tân để ở bên cạnh bạn trai cô – Vương Thăng. Cùng lúc, một loạt vụ án giết người kỳ lạ khiến cảnh sát Lý Động Tân vào cuộc, những mối nguy hiểm dần lộ diện...</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quách Bích Đình","avatar":""},{"name":"Đoạn Bác Văn","avatar":""},{"name":"Lưu Nghi Vĩ","avatar":""},{"name":"Mễ Mễ","avatar":""},{"name":"An Hổ","avatar":""},{"name":"Mã Du Tiệp","avatar":""},{"name":"Nhiếp Mai","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Almost Human","机械画皮"]', 1784690324332);
