INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-thanh-tai-sinh-dau-chien-nghich-thien', 'Đại Thánh Tái Sinh: Đấu Chiến Nghịch Thiên', 'Revival Of The Monkey King', 'https://phimimg.com/upload/vod/20250523-1/c85ca92b7c268729a98a4d41767ecae4.jpg', 'https://phimimg.com/upload/vod/20250523-1/2395daa053b32cbcfdf5f746cde507fb.jpg', '<p>Tôn Ngộ Không bị giam cầm vì chống lại Phật Tổ, một lần nữa lại nghịch thiên đổi mệnh! Thạch Hầu nhiều lần liên tiếp phạm phải luật trời, trốn khỏi thiên đình, xuống hạ giới đầu thai thành Hoa Tiểu Thiên. Tiên nữ A Thố phụng mệnh xuống hạ giới tìm Hoa Tiểu Thiên, bị ác ma Cự Linh phát hiện. Cự Linh dùng đủ loại quỷ kế, chỉ vì muốn có được thần khí của Hoa Tiểu Thiên. Sau một lần dốc sức chiến đấu, A Thố bị thiêu thành tro bụi. Hoa Thiểu Thiên cuối cùng được đánh thức, chiến thần quay trở lại, quyết một trận đại chiến sinh tử với Cự Linh...</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đỗng Hạo Nhiên","avatar":""},{"name":"Trịnh Tử Hảo","avatar":""},{"name":"Lưu Đằng Viễn","avatar":""},{"name":"Ôn Hải Ba","avatar":""},{"name":"Vũ Giai Huyên","avatar":""},{"name":"Cao Minh Dương","avatar":""},{"name":"Thôi Chân Chân","avatar":""},{"name":"Từ Hi","avatar":""},{"name":"Lưu Ích Yên","avatar":""},{"name":"Lâm Mỹ Tích","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["대성중생: 투전역천","大圣重生之斗战逆天"]', 1784690324332);
