INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('circle-hoa-ky-phan-1', 'Circle: Hoa Kỳ (Phần 1)', 'The Circle US (Season 1)', 'https://phimimg.com/upload/vod/20250523-1/3fca523e885b5273e3e2f0600b90fb48.jpg', 'https://phimimg.com/upload/vod/20250523-1/65db4953fffd6bddab272d806114f7f0.jpg', '<p>Thân thế và chiến lược kết hợp trong chương trình thử nghiệm xã hội và thi tài này, nơi các người chơi trực tuyến tán tỉnh, kết bạn và giả danh để giành lấy 100.000 USD.</p>', 'Hoàn Tất (12/12)', 12, 'tvshows', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michelle Buteau","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Le jeux du cercle","The Circle (US)","더 서클: 미국","The Circle US","The Cercle Etats Unis","The Circle"]', 1784690324332);
