INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-lam-xung-3-mieu-son-than', 'Anh Hùng Lâm Xung 3 : Miếu Sơn Thần', 'The Panther Head Hero 3 : Temple Of The Mountain Gods', 'https://phimimg.com/upload/vod/20250522-1/97c4fb798472baaabd9dc0049a1b9108.jpg', 'https://phimimg.com/upload/vod/20250522-1/4a9a4461566c91835358b22a287671cf.jpg', '<p>Bộ phim tiếp tục câu chuyện về người anh hùng Lâm Xung (một nhân vật hư cấu trong tiểu thuyết Thủy Hử). Ở phần này, kẻ xấu vì muốn đoạt vợ Lâm Xung mà bày kế ám hại, đày ải Lâm Xung đến Thương Châu. Mặc dù Lâm Xung thân đã bị đày, nhưng hắn vẫn chưa hả lòng, tiếp tục bày gian kế để đoạt mạng Lâm Xung.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Văn Đông Tuấn","avatar":""},{"name":"Bào Đan","avatar":""},{"name":"Tôn Khải","avatar":""},{"name":"Tống Khải","avatar":""},{"name":"Triệu Tĩnh Bội","avatar":""},{"name":"Lưu Kim","avatar":""},{"name":"Tất Kiền","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Dazed Soldier the Last Stand","Water Margin: Leopard Head Lin Chong 2","Leopard Head Lin Chong, Mountain Temple","豹子头林冲之山神庙"]', 1784690324332);
