INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-doi-ban-than-2', 'Doraemon: Đôi Bạn Thân 2', 'Stand by Me Doraemon 2', 'https://phimimg.com/upload/vod/20250521-1/f4fe192f89f6f84cba2de973dc65c9a7.jpg', 'https://phimimg.com/upload/vod/20250521-1/f127123e147e01e909db8e63c889ccc6.jpg', '<p>Phim Doraemon: Đôi Bạn Thân Phần 2 là câu chuyện kể về sự việc Doraemon, chú mèo máy đến từ thế kỷ 22. Vào ngày nay khi Doraemon và Nobita ở cùng nhau, Nobita tìm thấy một con gấu bông trong phòng. Đó là một món đồ kỉ niệm đã được may lại bởi bà nội cậu đã qua đời khi cậu lên mẫu giáo. Nobita, người nhớ đến bà của mình và không còn ngừng khóc, muốn gặp lại bà bằng cỗ máy thời gian. Doraemon phản đối, nhưng khởi hành đến quá khứ, nơi Nobita mới lên 3, với điều kiện cậu phải trở lại ngay khi nhìn thấy tình huống mà không gặp trực tiếp!</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2020, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Nhật Bản', 1, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Bakarhythm","avatar":""},{"name":"Shin''ichi Hatori","avatar":""},{"name":"Nobuko Miyamoto","avatar":""},{"name":"Vanilla Yamazaki","avatar":""},{"name":"Satoshi Tsumabuki","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["โดราเอมอน เพื่อนกันตลอดไป 2","Stand by Me Doraemon 2","STAND BY ME 多啦A夢 2","哆啦A梦：伴我同行2","doremon doi ban than 2","STAND BY ME 多啦A