INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-nhung-ban-khung-long-moi', 'Doraemon: Nobita và Những Bạn Khủng Long Mới', 'Doraemon: Nobita''s New Dinosaur', 'https://phimimg.com/upload/vod/20250521-1/7966687c9339c88186bbed56204c60cd.jpg', 'https://phimimg.com/upload/vod/20250521-1/0a5e9e3a28b27b8bd5b4779aa88e44b2.jpg', '<p>Trong lúc đang tham gia hoạt động khảo cổ ở một cuộc triễn lãm khủng long, Nobita tình cờ tìm thấy một viên hóa thạch và cậu tin rằng đây là trứng khủng long. Nobita liền mượn bảo bối thần kỳ &quot;khăn trùm thời gian&quot; của Doraemon để giúp viên hóa thạch trở lại thời của chúng nhưng ngay sau đó, quả trứng liền nở ra một cặp khủng long song sinh. Ngạc nhiên hơn hết, đây lại là loài khủng long mới hoàn toàn và chưa từng được phát hiện.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2020, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 1, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Takuya Kimura","avatar":""},{"name":"Aya Endo","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Naomi Watanabe","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Doraemon the Movie: Nobita''s New Dinosaur","Eiga Doraemon: Nobita no shin kyōryū","Doraemon: Il nuovo dinosauro di Nobita","多啦A梦：大雄之新恐龙","Eiga Doraemon - Nobita no shin kyoryu","多啦A夢大長篇 40: 大雄之新恐龍","映画ドラえもん のび太の新恐竜","哆啦A梦 大雄的新恐龙"]', 1784690324332);
