INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-tam-phong-2-thai-cuc-thien-su', 'Trương Tam Phong 2: Thái Cực Thiên Sư', 'Tai Chi Hero', 'https://phimimg.com/upload/vod/20240108-1/c840b97fc7fe30e5715db7faca4570e5.jpg', 'https://phimimg.com/upload/vod/20240108-1/f5eb0397d5d4fdd812ea28e070b251ba.jpg', '<p>Khi đang chống lại âm mưu thao túng võ lâm của nhóm người Tu La Mộ bí ẩn, Trương Tam Phong bị chúng tập kích đến thập tử nhất sinh. Dù được Khưu đạo trưởng cứu sống nhưng mọi chuyện vẫn vô cùng khó khăn khi Bạch Thanh Thanh lại bị bắt làm con tin.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Dương","avatar":""},{"name":"Lưu Ngật Thần","avatar":""},{"name":"Hứa Thi Thần","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324332);
