INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tenet', 'Tenet', 'Tenet', 'https://phimimg.com/upload/vod/20250520-1/3845760b686320b2d911098fd908d431.jpg', 'https://phimimg.com/upload/vod/20250520-1/8a4f7305469cf5278bf59ca4a2c3a7f2.jpg', '<p>Hai nhân vật được một tổ chức bí ẩn chiêu mộ, sử dụng một thứ được gọi là “Tenet” - được cho là “có thể mở ra những cửa đúng” và “vài cửa sai”, nhằm ngăn chặn Thế chiến thứ III từ trước khi nó xảy ra. Thay vì du hành thời gian, phương pháp nó hoạt động là “nghịch đảo” những gì đã có.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'FHD', 'Anh', 1, '[{"name":"John David Washington","avatar":""},{"name":"Robert Pattinson","avatar":""},{"name":"Elizabeth Debicki","avatar":""},{"name":"Kenneth Branagh","avatar":""},{"name":"Dimple Kapadia","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Martin Donovan","avatar":""},{"name":"Fiona Dourif","avatar":""},{"name":"Yuri Kolokolnikov","avatar":""},{"name":"Himesh Patel","avatar":""},{"name":"Clémence Poésy","avatar":""},{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"Laurie Shepherd","avatar":""},{"name":"Anthony Molinari","avatar":""},{"name":"Juhan Ulfsa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["İnanç","Verovanje","Merry-Go-Round","TENET天能","Dalil","信条","เทเน็ท","انگاشته","Tenet"]', 1784690324332);
