INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-ky-dieu', 'Cuộc Sống Kỳ Diệu', 'My Wonderful Life', 'https://phimimg.com/upload/vod/20250518-1/3bfea188e17685a10c36aa9cec1b7bfd.jpg', 'https://phimimg.com/upload/vod/20250518-1/dfa3a1eed8939ba8b710e95965826d25.jpg', '<p>Bộ phim xoay quanh hành trình hoán đổi số phận của hai người phụ nữ có cuộc đời hoàn toàn đối lập nhau. Số phận con người khi bị đẩy vào tình huống chưa bao giờ nghĩ đến phải chăng sẽ là điều tồi tệ? Hai người phụ nữ ở hai đầu của chiếc bập bênh địa vị sẽ làm gì để đối diện với sự thật nghiệt ngã và tìm kiếm ý nghĩa của cuộc sống?</p>', 'Hoàn Tất (127/127)', 127, 'series', 'completed', 7, 2020, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shim Yi Young","avatar":""},{"name":"Jin Ye-sol","avatar":""},{"name":"Won Ki-jun","avatar":""},{"name":"Choi Sung-jae","avatar":""},{"name":"Lee Jeong-kil","avatar":""},{"name":"Kim Yeong-ran","avatar":""},{"name":"Yang Hye-jin","avatar":""},{"name":"Park Yoo-ha","avatar":""},{"name":"Han So-yeong","avatar":""},{"name":"Son Seon-geun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["我的灿烂人生","Challanhan nae insaeng","Моя славная жизнь","My Brilliant Life","My Perfect Life","찬란한 내 인생"]', 1784690324332);
