INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-song-ky-dieu', 'Cuộc Sống Kỳ Diệu', 'My Wonderful Life', 'cuộc sống kỳ diệu my wonderful life shim yi young jin ye-sol won ki-jun choi sung-jae lee jeong-kil kim yeong-ran yang hye-jin park yoo-ha han so-yeong son seon-geun 我的灿烂人生 challanhan nae insaeng моя славная жизнь my brilliant life my perfect life 찬란한 내 인생', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-nguyen-bi-an', 'Di Nguyện Bí Ẩn', 'The Day I Died Unclosed Case', 'https://phimimg.com/upload/vod/20250518-1/00f5ac9678e6e1caf4eaacf35adaa1af.jpg', 'https://phimimg.com/upload/vod/20250518-1/db1a095b704ca0e0ba6d094f6e59fb23.jpg', '<p>Ở một hòn đảo xa xôi hẻo lánh, vào một đêm tối giông bão, nữ sinh cấp 3 Se-jin (Roh Jeong-eui) bất ngờ biến mất, chỉ để lại đôi giày trên mỏm đá sát biển và bức thư tuyệt mệnh. Mọi người cho rằng cô bé đã tử tự, nhưng do chưa tìm thấy thi thể, phía cảnh sát vẫn chưa thể đóng lại vụ án. Nữ cảnh sát Kim Hyun Soo (Kim Hye Soo) đã được giao điều tra vụ án của Se-jin khi vừa quay trở lại làm việc sau một thời gian dài tạm nghỉ. Để tìm hiểu về sự ra đi của cô gái trẻ, Kim Hyun Soo đã đến đảo để quan sát hiện trường và hỏi thăm những người dân ở đây, trong đó có một người phụ nữ câm kì lạ (Lee Jung Eun) – người cuối cùng nhìn thấy Se-jin. Liệu nữ cảnh sát Kim Hyun Soo có tìm ra nguyên nhân cho sự ra đi của Se-jin? Bí mật nào sẽ được hé lộ đằng sau vụ án tưởng chừng đơn giản chỉ đang chờ khép lại?</p>', 'Full', 1, 'single', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Kim Hye-soo","avatar":""},{"name":"Lee Jung-eun","avatar":""},{"name":"Roh Jeong-eui","avatar":""},{"name":"Kim Sun-young","avatar":""},{"name":"Lee Sang-yeob","avatar":""},{"name":"Moon Jeong-hee","avatar":""},{"name":"Kim Jung-young","avatar":""},{"name":"Cho Han-cheul","avatar":""},{"name":"Kim Tae-hun","avatar":""},{"name":"Im Sung-jae","avatar":""},{"name":"Kang Yeon-jung","avatar":""},{"name":"Kang Shin-chul","avatar":""},{"name":"Jung Young-ki","avatar":""},{"name":"Park Mi-hyeon","avatar":""},{"name":"Jeong Soo-ji","avatar":""},{"name":"Yoon Byung-hee","avatar":""},{"name":"Jung Ji-woo","avatar":""},{"name":"Lee G","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["nae-ga juk-deon nal","我死去的那天","내가 죽던 날"]', 1784690324332);
