INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('james-may-o-nau-an-phan-1', 'James May: Ơ Nấu Ăn (Phần 1)', 'James May: Oh Cook (Season 1)', 'https://phimimg.com/upload/vod/20250512-1/70ad8c62d2abc5236aea33e77475efdc.jpg', 'https://phimimg.com/upload/vod/20250512-1/190943db9e8f0c4ab97916205aa7a6a3.jpg', '<p>James May không phải là đầu bếp. Nhưng đó chính là điều cốt lõi: bạn không cần phải là một đầu bếp tài ba để nấu được những món ăn ngon. Trong chương trình, anh sẽ đưa khán giả đến với Viễn Đông, Địa Trung Hải, và cả những quán rượu địa phương – tất cả đều từ căn bếp của một chuyên gia kinh tế gia đình. James sẽ thực hiện những công thức món ăn ngon mà bạn hoàn toàn có thể tự làm, với nguyên liệu dễ kiếm, và đặc biệt là không hề dùng đến những chiêu trò thường thấy trong các chương trình nấu ăn trên truyền hình.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 9, 2020, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Nikki Morgan","avatar":""},{"name":"James May","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["James May: Oh Cook!"]', 1784690324332);
