INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-goi-anh-la-bo', 'Đừng Gọi Anh Là Bố', 'My God Father', 'https://phimimg.com/upload/vod/20250512-1/39d8819b6e3cb1f656522fe0889944f0.jpg', 'https://phimimg.com/upload/vod/20250512-1/495829c7e55b2ebe1e9c5d1077fa40a9.jpg', '<p>Đừng Gọi Anh Là Bố! xoay quanh mối quan hệ bất hòa giữa Got – một tay đua và người bố Prem. Một tai nạn xe hơi đưa anh trở về khoảng thời gian bố anh vẫn còn trẻ và vô tình trở thành bạn chí cốt của bố. Thông qua chuyến xuyên không kì diệu này, anh có cơ hội gặp lại được mẹ và hiểu hơn về câu chuyện đằng sau tính cách cộc cằn của bố.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Thanawat Wattanaputi","avatar":""},{"name":"Chantavit Dhanasevi","avatar":""},{"name":"Sammy Cowell","avatar":""},{"name":"Bhuripat Vejvongsatechavat","avatar":""},{"name":"Chawinroj Likitchareonsakul","avatar":""},{"name":"Siripon Sirinattakul","avatar":""},{"name":"Sarunyoo Prachakit","avatar":""},{"name":"Naphat Chumchittri","avatar":""},{"name":"Torphong Kul-on","avatar":""},{"name":"Suporn Sangkaphibal","avatar":""},{"name":"Nilawan Iamchuasawad","avatar":""},{"name":"Orn-arnin Peerachak","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["My God!! Father","เฮ้ย! ลูกเพ่ นี่ลูกพ่อ"]', 1784690324332);
