INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-lap-hai-phut', 'Vòng Lặp Hai Phút', 'Beyond the Infinite Two Minutes', 'https://phimimg.com/upload/vod/20250511-1/63db2a4aecdc204cd6e2797e6d7068ec.jpg', 'https://phimimg.com/upload/vod/20250511-1/11a009ebf7c0575482671e35a0fd9110.jpg', '<p>Beyond the Infinite Two Minutes (2020) là một bộ phim khoa học viễn tưởng hài của Nhật Bản, do Junta Yamaguchi đạo diễn. Phim kể về Kato, chủ quán cà phê, người phát hiện ra rằng màn hình máy tính của mình có thể hiển thị những gì sẽ xảy ra trong hai phút tương lai. Khi bạn bè của anh ấy biết được điều này, họ bắt đầu thử nghiệm với nó, nhưng mọi thứ nhanh chóng trở nên phức tạp.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kazunari Tosa","avatar":""},{"name":"Aki Asakura","avatar":""},{"name":"Riko Fujitani","avatar":""},{"name":"Gota Ishida","avatar":""},{"name":"Masashi Suwa","avatar":""},{"name":"Yoshifumi Sakai","avatar":""},{"name":"Haruki Nakagawa","avatar":""},{"name":"Takashi Sumita","avatar":""},{"name":"Munenori Nagano","avatar":""},{"name":"Chikara Honda","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Droste no hate de bokura","Beyond the Infinite 2 Minutes","Más allá de los dos minutos infinitos","Neskončni dve minuti","Beyond the Infinite Two Minutes","ドロステのはてで僕ら：2020","A Dois Minutos do Infinito","ドロステのはてで僕ら"]', 1784690324332);
