INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chong-nguoi-ta', 'Chồng Người Ta', 'Bridge of Destiny', 'https://phimimg.com/upload/vod/20250511-1/69705f7f344c061fb012147f2b9563f4.jpg', 'https://phimimg.com/upload/vod/20250511-1/d64c45a40a138cc999edbc66add792ea.jpg', '<p>Chuyện phim Chồng người ta theo chân Cường (Trịnh Xuân Nhản) - một người đàn ông trung niên thành đạt đang sống cùng vợ là Trúc (Yaya Trương Nhi) và con trai Hải (Trần Ngọc Vàng). Song, anh luôn phải che giấu bí mật là mối tình đồng tính với Trung (Hữu Tài) cách đây 20 năm. &nbsp;Một ngày nọ, Thắng (Lý Bình) xuất hiện và tìm cách tiếp cận hai cha con Cường - Hải. Bằng một cách nào đó, gã nắm rõ toàn bộ câu chuyện quá khứ của người cha. Từ đây, Cường bắt đầu bộc lộ bản ngã và dần rơi vào cái bẫy mà tên thanh niên bí ẩn giăng ra.</p>', 'Full', 1, 'single', 'completed', 30, 2020, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Trịnh Xuân Nhản","avatar":""},{"name":"YaYa Trương Nhi","avatar":""},{"name":"Trần Ngọc Vàng","avatar":""},{"name":"Hữu Tài","avatar":""},{"name":"Lý Bình","avatar":""},{"name":"Thanh Trúc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bridge of Destiny","El Puente del Destino","Chồng Người Ta"]', 1784690324332);
