INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-cua-zeus-phan-1', 'Máu Của Zeus (Phần 1)', 'Blood Of Zeus (Season 1)', 'https://phimimg.com/upload/vod/20240530-1/544a09698c4b7056f5b33b1ac33e4f53.jpg', 'https://phimimg.com/upload/vod/20240530-1/4c4c57ca4f0951367608d21c857b7bcf.jpg', '<p>Heron, một thường dân ở Hy Lạp cổ đại, khám phá ra di sản đích thực của mình với danh phận là con trai của Zeus cùng lẽ sống: cứu thế giới khỏi đội quân quỷ dữ.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jason O''mara","avatar":""},{"name":"Elias Toufexis","avatar":""},{"name":"Jessica Henwick","avatar":""},{"name":"Chris Diamantopoulos","avatar":""},{"name":"Adetokumboh M''cormack","avatar":""},{"name":"Matthew Mercer","avatar":""},{"name":"Mamie Gummer","avatar":""},{"name":"Claudia Christian","avatar":""},{"name":"Derek Phillips","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324332);
