INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-2067', 'Năm 2067', '2067', 'https://phimimg.com/upload/vod/20250508-1/eae0fcfd43a244fa28e6793bd3619208.jpg', 'https://phimimg.com/upload/vod/20250508-1/4cfe5bd527ad2c014c53040da2ec8288.jpg', '<p><span style="text-wrap-mode: wrap;">Năm 2067, thế giới trên bờ vực tuyệt chủng vì thiếu oxy và Ethan là người duy nhất có thể cứu lấy nhân loại. Anh phải đứng trước quyết định đi đến tương lai để làm tròn trách nhiệm cao cả hay ở lại chăm sóc người vợ đang bệnh nặng của mình.</span></p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Úc', 0, '[{"name":"Kodi Smit-McPhee","avatar":""},{"name":"Ryan Kwanten","avatar":""},{"name":"Sana''a Shaik","avatar":""},{"name":"Aaron Glenane","avatar":""},{"name":"Leeanna Walsman","avatar":""},{"name":"Deborah Mailman","avatar":""},{"name":"Finn Little","avatar":""},{"name":"Matt Testro","avatar":""},{"name":"Damian Walshe-Howling","avatar":""},{"name":"Andy McPhee","avatar":""},{"name":"Rachael Wegener","avatar":""},{"name":"V. Wasylczenko","avatar":""},{"name":"Judd Wild","avatar":""},{"name":"Natasha Wanganeen","avatar":""},{"name":"Rory Walker","avatar":""},{"name":"Meme Thorne","avatar":""},{"name":"Jane","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Subject 14","Chronical: 2067","2067"]', 1784690324332);
