INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nam-2067', 'Năm 2067', '2067', 'năm 2067 2067 kodi smit-mcphee ryan kwanten sana''a shaik aaron glenane leeanna walsman deborah mailman finn little matt testro damian walshe-howling andy mcphee rachael wegener v. wasylczenko judd wild natasha wanganeen rory walker meme thorne jane subject 14 chronical: 2067 2067', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-an-nac', 'Trường An Nặc', 'The Promise Of Chang''an', 'https://phimimg.com/upload/vod/20241104-1/63bd350eaa87ab0c94e8685f817be04d.jpg', 'https://phimimg.com/upload/vod/20241104-1/b5539478a916df53edc07f8f1bc8b525.jpg', '<p>Cháu gái của Ung Lâm vương - Hạ Lan Minh Ngọc - từ nhỏ là một nữ tử thông minh, lanh lợi. Thời niên thiếu, nàng tình cờ gặp gỡ và kết giao với Cửu hoàng tử Thịnh Châu - Tiêu Thừa Húc; hai người tính tình hòa hợp, dần dần nảy sinh tình cảm. Khi nghe tin đồn thất thiệt Tiêu Thừa Húc tử trận, để cứu đệ đệ ruột của Tiêu Thừa Húc - Tiêu Thừa Hiên, Minh Ngọc bị ép gả cho Thịnh Châu vương, Tam ca của Thừa Húc - Tiêu Thừa Duệ. Từ đây, nàng bắt đầu bước chân vào chốn hậu cung. Tiêu Thừa Húc nhiều lần lập chiến công giúp Tiêu Thừa Duệ xưng đế, lập nên nước Đại Thịnh, nhưng cũng chính vì lập nhiều công lớn nên bị ghen ghét. Thêm vào đó, khi biết được sự thật về cái chết của mẫu thân và việc truyền ngôi của phụ vương, Tiêu Thừa Húc quyết định báo thù. Khi chưa đạt được mục đích, Tiêu Thừa Duệ vì bệnh cũ tái phát mà đột ngột qua đời, lệnh cho con trai của Minh Ngọc - Tiêu Khải Nguyên lên kế vị, củng cố việc triều chính dưới sự kiểm soát của Tiêu Thừa Húc. Tiêu Thừa Húc bị ép phò tá cho Tiêu Khải Nguyên, nhưng vẫn một lòng muốn lấy Hạ Lan Minh Ngọc. Cũng vào lúc này, Khải Nguyên ngày một lớn dần, bất mãn với sự kiểm soát của Tiêu Thừa Húc, hơn nữa lại nghe sự chia rẽ từ những người xung quanh, biết được tình cảm riêng giữa mẫu thân mình và Tiêu Thừa Húc, nảy sinh lòng thù oán với hai người. Hạ Lan Minh Ngọc lấy sự bình yên và ổn định của Đại Thịnh làm trọng, dốc hết sức cân bằng giữa Khải Nguyên và Tiêu Thừa Húc. Không ngờ cuối cùng Tiêu Thừa Húc chết trong trận chiến; còn Khải Nguyên cũng một đời si tình, ra đi cùng với ái phi sinh bệnh mà chết - Đổng Nhược Huyên. Minh Ngọc vì tương lai của Đại Thịnh, một lần nữa ở bên cạnh tiểu hoàng đế đăng cơ.</p>', 'Hoàn Tất (56/56)', 56, 'series', 'completed', 7, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thành Nghị","avatar":""},{"name":"Triệu Anh Tử","avatar":""},{"name":"Hàn Đống","avatar":""},{"name":"Dương Siêu Việt","avatar":""},{"name":"Hàn Thừa Vũ","avatar":""},{"name":"Lương Tịnh Nhàn","avatar":""},{"name":"Ô Tĩnh Tĩnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Promise of Changan","长安诺"]', 1784690324332);
