INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truong-an-nac', 'Trường An Nặc', 'The Promise Of Chang''an', 'trường an nặc the promise of chang''an thành nghị triệu anh tử hàn đống dương siêu việt hàn thừa vũ lương tịnh nhàn ô tĩnh tĩnh the promise of changan 长安诺', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phao-hoa-song-day-mua-song-do', 'Pháo Hoa Sông Đây Mưa Sông Đó', 'Love Story Of Court Enemies', 'https://phimimg.com/upload/vod/20250508-1/cb015a6ce7d2a5e56ee726ae96e5944f.jpg', 'https://phimimg.com/upload/vod/20250508-1/b31a284d163851ab4718e6028e4dc211.jpg', '<p>Năm Ung Chính, phản quân nổi lên khắp nơi, hai tỷ muội Ngữ Tinh và Thái Hoàng trên đường chạy nạn bị lạc nhau, Ngữ Tinh hiểu nhầm Nhạc Tông Lân là phản quân, từ đó hai người trở thành oan gia. Ngữ Tinh sau khi biết Thái Hoàng đã tuyển tú vào cung, vì tìm Thái Hoàng cô liền thi vào Ngự thiện phòng. Nhờ có tài nấu ăn giỏi cô được hoàng thượng yêu thích, tấn phong thành Thừa ứng trưởng. Tuy nhiên khi Hoàng thái hậu qua đời do phạm vào đại kỵ của hoàng thượng, hai tỷ muội bị đưa tới công trường Tây Lăng làm khổ lao, chịu đủ khổ sở.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 6, 2020, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Giai Di","avatar":""},{"name":"Triệu Dịch Khâm","avatar":""},{"name":"Hàn Cửu Nặc","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["那江烟花那江雨"]', 1784690324332);
