INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tiep-vien-hang-khong-phan-1', 'Tiếp Viên Hàng Không (Phần 1)', 'The Flight Attendant (Season 1)', 'tiếp viên hàng không (phần 1) the flight attendant (season 1) kaley cuoco zosia mamet deniz akdeniz mo mcrae callie hernandez griffin matthews j. j. soria cheryl hines rosie perez 谜飞空姐 la asistente de vuelo l''assistente di volo стюардесса the flight attendant', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kich-ban-yeu-duong-cua-nang-va-chang', 'Kịch Bản Yêu Đương Của Nàng Và Chàng', 'Love Script', 'https://phimimg.com/upload/vod/20250504-1/a49ba25b1e3ea7ad1c78c5bb074d4419.jpg', 'https://phimimg.com/upload/vod/20250504-1/c0205b264896b19b64268c1fe9ff5b6e.jpg', '<p>Chu Tuyên Văn đúng chuẩn “soái ca” trong truyền thuyết, nhưng đáng tiếc mắc bệnh hoang tưởng, suốt ngày nghĩ mình là hoàng đế bỏ bê công việc kinh doanh của công ty. Khai Hoài là một bác sĩ tâm lý thực tập, đang điều trị cho anh trai Tuyên Văn. Vốn ban đầu cô không có thiện cảm với Tuyên Văn, nhưng oái oăm thế nào mà phải chữa trị cho ca bệnh “khó đỡ” này. Năm lần bảy lượt lấy cơ hội hành hạ Khai Hoài, nhưng Tuyên Văn không hề biết rằng cô nàng cũng “không phải dạng vừa”.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trang Đạt Phi","avatar":""},{"name":"Hoàn Nhan Lạc Nhung","avatar":""},{"name":"Đới Hướng Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["我的妄想症男友","她和他的恋爱剧本"]', 1784690324332);
