INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-tra-mau-muc-phan-1', 'Thanh Tra Mẫu Mực (Phần 1)', 'Good Detective (Season 1)', 'https://phimimg.com/upload/vod/20241108-1/654e82a7616584a008f0ca0da4112b7d.jpg', 'https://phimimg.com/upload/vod/20241108-1/582153830131e6ca74b50c5e780171aa.jpg', '<p>Thanh tra Kang Do Chang thường phá án dựa trên kinh nghiệm và mối quan hệ cá nhân thay vì áp dụng các phương pháp khoa học. Cảnh sát Oh Ji Hyuk, ngoài việc giỏi phá án còn là một “rick kid” chính hiệu do được thừa hưởng khối gia sản khổng lồ, điều tra các vụ án bằng cách sử dụng bằng chứng và phân tích tâm lý tội phạm. Hai cá nhân trái ngược về tính cách nhưng lại có cùng lý tưởng, quyết tâm bằng mọi giá truy tìm sự thật dù có phải giẫm đạp lên chính bản thân mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Son Hyun-joo","avatar":""},{"name":"Jang Seung-jo","avatar":""},{"name":"Kim Hyo-jin","avatar":""},{"name":"Jung Moon-sung","avatar":""},{"name":"Cha Rae-hyung","avatar":""},{"name":"Jung Soon-won","avatar":""},{"name":"Kim Ji-hoon","avatar":""},{"name":"Kim Myeong-jun","avatar":""},{"name":"Son Jong-hak","avatar":""},{"name":"Jo Hee-bong","avatar":""},{"name":"Song Young-chang","avatar":""},{"name":"Choi Dae-hoon","avatar":""},{"name":"Park Won-sang","avatar":""},{"name":"Lee Jung-ok","avatar":""},{"name":"Baek Eun-hae","avatar":""},{"name":"Lee Ha-eun","avatar":""},{"name":"Park Keun-hyong","avatar":""},{"name":"Hong Se","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"