INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-hoan-luong', 'Phi Vụ Hoàn Lương', 'Honest Thief', 'https://phimimg.com/upload/vod/20231108-1/6cef123e0b2574e52f11b8cf3754f6e7.jpg', 'https://phimimg.com/upload/vod/20231108-1/705c9837a3cfc8252ab14ab44bf2fb3e.jpg', '<p>Vì lỡ yêu một phụ nữ, tên cướp ngân hàng chuyên nghiệp quyết định &quot;rửa tay gác kiếm&quot;. Anh chấp nhận tự thú với FBI vì cuộc đời lương thiện sau này. Thế nhưng, &quot;cựu tướng cướp&quot; nhanh chóng phát hiện ra việc tiết lộ khoản tiền cướp ngân hàng ngày xưa cho các Đặc vụ liên bang là sai lầm nghiêm trọng. Liệu anh có thành công hoàn lương, trở về bên người phụ nữ mình yêu khi các đặc vụ tha hoa tìm cách đánh cắp số tiền?</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Kate Walsh","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"Jeffrey Donovan","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Anthony Ramos","avatar":""},{"name":"Jasmine Cephas Jones","avatar":""},{"name":"Birol Tarkan Yıldız","avatar":""},{"name":"Adam Teper","avatar":""},{"name":"Jose Guns Alves","avatar":""},{"name":"Osmani Rodriguez","avatar":""},{"name":"Devon Diep","avatar":""},{"name":"Michael Malvesti","avatar":""},{"name":"Lewis D. Wheeler","avatar":""},{"name":"Patty O''Neil","avatar":""},{"name":"Herlin Nava","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324332);
