INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nghe-thuat-san-quy-va-nau-mi-phan-1', 'Nghệ Thuật Săn Qủy Và Nấu Mì (Phần 1)', 'The Uncanny Counter (Season 1)', 'nghệ thuật săn qủy và nấu mì (phần 1) the uncanny counter (season 1) cho byeong kyu yu jun sang kim se jeong yeom hye ran 惊人的传闻 惊奇的传闻 驱魔面馆 悪霊狩猟団：カウンターズ 悪霊狩猟団 カウンターズ あくりょうしゅりょうだん：カウンターズ 경이로운 소문 驚異로운 所聞 경이로운 소문2: 카운터 펀치 el contador asombroso чудесный слух удивительный слух 驅魔麵館 the uncanny counter: counter punch amazing rumor amazing so mun', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-nho-doi', 'Kỳ Nghỉ Nhớ Đời', 'The Golden Holiday', 'https://phimimg.com/upload/vod/20231117-1/f2e9ca436e40a037d54c475c31472382.jpg', 'https://phimimg.com/upload/vod/20231117-1/b64033e2d8fca36a3541deed2154ea28.jpg', '<p>Kỳ Nghỉ Nhớ Đời kể về chuyến du lịch Philipines của gia đình anh cảnh sát Byung-soo nhân kỷ niệm 10 năm ngày cưới. Trong khi vợ và con gái đắm chìm trong niềm hạnh phúc lần đầu xuất ngoại, Byung-soo bí mật điều tra tung tích của Yong-bae – một người bạn cũ, cũng là tay lừa đảo cộm cán đã trốn khỏi Hàn Quốc vài năm trước đây. Gặp lại Yong-bae trong tù với tội danh giết người, Byung-soo được nghe câu chuyện hấp dẫn về “Kho vàng của Yamashita”. Thanh tra gà mờ không hề biết rằng bản thân đang bị cuốn vào một phi vụ nguy hiểm tầm cỡ quốc tế, thậm chí phải đánh đổi bằng cả tính mạng của bản thân mình.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kwak Do-won","avatar":""},{"name":"Kim Dae-myung","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Kim Hee-won","avatar":""},{"name":"Shin Dong-mi","avatar":""},{"name":"Lee Han-seo","avatar":""},{"name":"Son Hyun-joo","avatar":""},{"name":"Jo Jae-yun","avatar":""},{"name":"Lee Bong-ryeon","avatar":""},{"name":"Lee Hong-nae","avatar":""},{"name":"Lee So-jin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324332);
