INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cua-hang-tien-loi-saet-byul', 'Cửa Hàng Tiện Lợi Saet Byul', 'Backstreet Rookie', 'https://phimimg.com/upload/vod/20240312-1/a29a7b25a5c35e209ed16f408a10060d.jpg', 'https://phimimg.com/upload/vod/20240312-1/4c4db21f8eea0315ddbf540e7cad71ab.jpg', '<p>Cửa Hàng Tiện Lợi Saet Byul là câu chuyện tình giữa anh chủ cửa hàng tiện lợi Choi Dae Hyun (Ji Chang Wook) với cô nhân viên lập dị Jung Saet Byul (Kim Yoo Jung). Choi Dae Hyun là anh chàng mỹ nam nhưng vụng về và ngốc nghếch. Anh quyết định từ bỏ công việc ở một công ty lớn để quản lý một cửa hàng tiện lợi cho riêng mình. Tại đây, anh gặp cô nàng Saet Byul kỳ quặc – một nữ nhân viên bán thời gian của cửa hàng. Saet Byul được miêu tả là cô gái vừa tinh nghịch, vừa lập dị và đang quyết tâm từ bỏ quá khứ quậy phá để trở thành người phụ nữ đấu tranh cho công lý.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 11, 2020, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ji Chang-wook","avatar":""},{"name":"Kim You-jung","avatar":""},{"name":"Do Sang-woo","avatar":""},{"name":"Han Seon-hwa","avatar":""},{"name":"Ahn Sol-bin","avatar":""},{"name":"Kim Min-gue","avatar":""},{"name":"Lee Byung-joon","avatar":""},{"name":"Kim Sun-young","avatar":""},{"name":"Woo Hyeon","avatar":""},{"name":"Lee Yoon-hee","avatar":""},{"name":"Kyeon Mi-ri","avatar":""},{"name":"Seo Ye-hwa","avatar":""},{"name":"Um Mun-suk","avatar":""},{"name":"Kim Ji-hyun","avatar":""},{"name":"Kil Yong-woo","avatar":""},{"name":"Heo Jae-ho","avatar":""},{"name":"Yoon Seul","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-