INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-sinh-tam-the-cham-thuong-thu', 'Tam Sinh Tam Thế Chẩm Thượng Thư', 'Eternal Love Of Dream', 'https://phimimg.com/upload/vod/20250418-1/9e93b6cbbf625061d071b2515c853162.jpg', 'https://phimimg.com/upload/vod/20250418-1/882e5b58543a4235358775da216c4e7c.jpg', '<p>Tam Sinh Tam Thế Chẩm Thượng Thư kể câu chuyện về Thanh Khâu đế cơ Bạch Phượng Cửu (Địch Lệ Nhiệt Ba) bị một con yêu thú tấn công được Đông Hoa Đế Quân (Cao Vỹ Quang) ra tay giải cứu, từ đây mà ghi nhớ trong lòng. Để báo ân, Phượng Cửu khăng khăng đi theo Đông Hoa. Dần dần, nàng phát hiện lòng cảm kích muốn báo ân của mình đã dần chuyển hóa thành thương nhớ lúc nào không hay. Nhưng Đông Hoa sau ngàn năm chinh chiến, đã từ lâu không biết thế nào là ái tình. Để bảo vệ Phượng Cửu an toàn, Đông Hoa đem nàng đến nhân gian, lại bất hạnh khiến cho bằng hữu vì bảo vệ nàng mà chết.</p>', 'Hoàn Tất (56/56)', 56, 'series', 'completed', 7, 2020, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Địch Lệ Nhiệt Ba","avatar":""},{"name":"Cao Vỹ Quang","avatar":""},{"name":"Lưu Vũ Hân","avatar":""},{"name":"Lưu Dịch Quân","avatar":""},{"name":"Hoàng Minh","avatar":""},{"name":"Trương Thiên Dương","avatar":""},{"name":"Vương Kiêu","avatar":""},{"name":"Lý Đông Học","avatar":""},{"name":"Trương Giai Ninh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b06