INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tam-sinh-tam-the-cham-thuong-thu', 'Tam Sinh Tam Thế Chẩm Thượng Thư', 'Eternal Love Of Dream', 'tam sinh tam thế chẩm thượng thư eternal love of dream địch lệ nhiệt ba cao vỹ quang lưu vũ hân lưu dịch quân hoàng minh trương thiên dương vương kiêu lý đông học trương giai ninh the pillow book trois vies, trois mondes, the pillow book 夢幻の桃花 ～三生三世枕上書～ 夢幻の桃花 三生三世枕上書 삼생삼세침상서 สามชาติสามภพ ลิขิตเหนือเขนย three lives, three worlds: the pillow book 三生三世枕上书', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lay-danh-nghia-nguoi-nha', 'Lấy Danh Nghĩa Người Nhà', 'Go Ahead', 'https://phimimg.com/upload/vod/20241011-1/b6e1095ea659ed80106868d7e6a1bd43.jpg', 'https://phimimg.com/upload/vod/20241011-1/55129dd67c665a62ab45d433df24b4fd.jpg', '<p>Bối cảnh phim là Trung Quốc những năm 1990, ba đứa trẻ Lý Tiềm Tiềm, Lăng Tiêu, Hạ Tử Thu không cùng huyết thống lớn lên trong hoàn cảnh khác nhau, trải qua những vấn đề cuộc sống khó khăn, nhưng lại tình cờ ở chung một chỗ và trở thành anh em. Anh cả Lăng Tiêu (Tống Uy Long) – bố mẹ đẻ Lăng Hòa Bình và Trần Đình ly hôn từ lúc anh còn nhỏ, bố thiếu sự quan tâm, mẹ lấy chồng mới, sinh con khác, ít gặp; anh hai Tử Thu (Trương Tân Thành) – bố mẹ cũng đã ly hôn, mẹ là Hạ Mai đặt tên con theo tên mình vì đã sinh ra và một mình nuôi Tử Thu, rồi để anh lại cho người quen là Lý Hải Triều, đi về nơi xa; em út Lý Tiêm Tiêm (Đàm Tùng Vận) – con gái của Lý Hải Triều, mẹ mất sớm, bố như gà trống nuôi con. Cả ba người được hai người cha là Lý Hải Triều và Lăng Hòa Bình cùng nuôi nấng. Bọn họ nương tựa lẫn nhau, trưởng thành cùng nhau.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 9, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đàm Tùng Vận","avatar":""},{"name":"Tống Uy Long","avatar":""},{"name":"Trương Tân Thành","avatar":""},{"name":"Đồ Tùng Nham","avatar":""},{"name":"Tôn Y","avatar":""},{"name":"Hà Thụy Hiền","avatar":""},{"name":"An Qua","avatar":""},{"name":"Trương Hi Lâm","avatar":""},{"name":"Dương Đồng Thư","avatar":""},{"name":"Uyển Nhiễm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yi Jia Ren Zhi Ming","In the Name of the Family","以家人之名"]', 1784690324332);
