INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-nghiem-xac-song', 'Thí Nghiệm Xác Sống', 'Patients Of A Saint', 'https://phimimg.com/upload/vod/20231120-1/998e7d138a0fe73983b3039bbfe3265e.jpg', 'https://phimimg.com/upload/vod/20231120-1/83bfe593f17fce9672857b74a3342a88.jpg', '<p>Một sai lầm khủng khiếp đã xảy ra tạo nên sự bùng phát dịch bệnh trên toàn hòn đảo khiến cho người nhiễm bệnh trở nên bạo lực và khát máu. Stone và những người còn sống phải thoát khỏi trại giam địa ngục này để quay lại đất liền. Liệu một tử tù có thể trở thành anh hùng cứu sống mọi người hay trở thành thức ăn của những xác sống đang đói khát?</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jess Chanliau","avatar":""},{"name":"Meg Alexandra","avatar":""},{"name":"Gabz Barker","avatar":""},{"name":"Raymond Bethley","avatar":""},{"name":"Anastasia Borodina","avatar":""},{"name":"Sarah Brazier","avatar":""},{"name":"Tom Clegg","avatar":""},{"name":"Stacey Lynn Crowe","avatar":""},{"name":"Cherry-Rosa Cullen","avatar":""},{"name":"Leon Black","avatar":""},{"name":"Francesca Cherruault","avatar":""},{"name":"Christopher Dunne","avatar":""},{"name":"Jane Garioni","avatar":""},{"name":"Meryl Griffiths","avatar":""},{"name":"Lydia Hourihan","avatar":""},{"name":"Jennifer J","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324332);
