INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-chan-to-phieu-luu-ky', 'Gia Đình Chân To Phiêu Lưu Ký', 'Bigfoot Family', 'https://phimimg.com/upload/vod/20231124-1/155c1bb34f18a1c14cee53aabe877c49.jpg', 'https://phimimg.com/upload/vod/20231124-1/8fdb74bc1a4a31a49de5f28cd93e128d.jpg', '<p>Gia Đình Chân To Phiêu Lưu Ký tiếp nối phần phim Bố Tớ Là Chân To kể về cuộc phiêu lưu thú vị đến vùng đất Alaska với mong muốn truyền tải thông điệp ý nghĩa về môi trường sau khi Adam và Bố trở thành những gương mặt được truyền thông săn đón. Trong lúc đang dốc sức để mang lại những điều tuyệt vời cho Alaska, họ đã phát hiện một âm mưu tàn phá môi trường. Liệu gia đình Chân To có ngăn chặn được âm mưu độc ác này và bảo vệ vùng đất</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2020, 'Vietsub + Lồng Tiếng', 'FHD', 'Bỉ', 0, '[{"name":"Jules Medcraft","avatar":""},{"name":"David Lodge","avatar":""},{"name":"Grant George","avatar":""},{"name":"Shyloh Oostwald","avatar":""},{"name":"Joey Camen","avatar":""},{"name":"Kyle Hebert","avatar":""},{"name":"Jeff Rector","avatar":""},{"name":"Roger Craig Smith","avatar":""},{"name":"Sandy Fox","avatar":""},{"name":"Laila Berzins","avatar":""},{"name":"Michael Sorich","avatar":""},{"name":"George Babbit","avatar":""},{"name":"Cyndia Scott","avatar":""},{"name":"Dino Andrade","avatar":""},{"name":"Chris Niosi","avatar":""},{"name":"James Fredrick","avatar":""},{"name":"Alejandra Cazarez","avatar":""},{"name":"Linds","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324332);
