INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lay-long-hoa-su', 'Lấy Lòng Họa Sư', 'Oh! My Sweet Liar!', 'https://phimimg.com/upload/vod/20250415-1/5efe664ab9109020b4f96daea1baffcc.jpg', 'https://phimimg.com/upload/vod/20250415-1/bf513bf3fbcbe358a15c273c8dd69d20.jpg', '<p>Do hàng loạt hiểu lầm mà nữ họa sư tài năng Hùng Hi Nhược và Lý Hoằng Bân, thiếu chủ gia tộc họ Lý danh giá, buộc phải nói dối rằng họ yêu nhau để cứu mạng Hùng Hi Nhược cũng như giúp Lý Hoằng Bân thoát khỏi cuộc hôn nhân sắp đặt. Theo thời gian, hai người dần nảy sinh tình cảm thật sự, nhưng lúc này những hiểm nguy rình rập gia đình họ Lý cũng bắt đầu xuất hiện.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xi Zi","avatar":""},{"name":"Lan Bo","avatar":""},{"name":"Tian Shuchen","avatar":""},{"name":"Xia Ningjun","avatar":""},{"name":"Kang Keren","avatar":""},{"name":"Gu Jiangshan","avatar":""},{"name":"Cui Yi","avatar":""},{"name":"Huang Xingyuan","avatar":""},{"name":"Yang Dapeng","avatar":""},{"name":"Qiao Shiyu","avatar":""},{"name":"Zhang Ai","avatar":""},{"name":"Bai Jingjing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["偷心画师"]', 1784690324332);
