INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nha-tao-mau-toc-sieu-dang', 'Nhà Tạo Mẫu Tóc Siêu Đẳng', 'Bread Barbershop', 'nhà tạo mẫu tóc siêu đẳng bread barbershop um sang hyun park yoon hee kang si hyun hong bum ki kim hyun wook lee in suk song ha rim ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-linh-cuu-hoa-phan-2', 'Biệt Đội Lính Cứu Hỏa (Phần 2)', 'Fire Force (Season 2)', 'https://phimimg.com/upload/vod/20250411-1/962c1ed25e836aa1eed9465e5437aa8e.jpg', 'https://phimimg.com/upload/vod/20250411-1/db2991f6b28708dd7e6df591bf274045.jpg', '<p>Năm 198 của kỷ nguyên Thái Dương ở Tokyo, các đội cứu hỏa đặc thù chiến đấu chống lại Hiện tượng nhân thể bộc hỏa, khi cơ thể con người đột nhiên biến thành quái vật lửa được gọi Viêm Nhân. Shinra Kusakabe là một chàng trai trẻ bị gắn biệt danh là Dấu chân ác quỷ, vì chân của cậu ấy có thể bốc cháy theo ý muốn. Sau khi cậu gia nhập Đội lính cứu hỏa đặc thù số 8, cậu đã cùng những đồng đội trong đội ngũ chiến đấu chống lại các Viêm Nhân với sức mạnh lính cứu hỏa thế hệ thứ 3 của mình. Khi tiếp xúc với kẻ tạo ra Viêm Nhân, Shinra bắt đầu biết được bí mật của cuộc hỏa hoạn đã gây ra cái chết thương vong cho cả gia đình cậu 12 năm trước...</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Gakuto Kajiwara","avatar":""},{"name":"Yusuke Kobayashi","avatar":""},{"name":"Saeko Kamijo","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Kenichi Suzumura","avatar":""},{"name":"Aoi Yuki","avatar":""},{"name":"Daisuke Sakaguchi","avatar":""},{"name":"Taku Yashiro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["炎炎消防队 叁之章","炎炎消防队 贰之章","炎炎消防队 壹之章","Fire Force","En''en no Shouboutai","Enn Enn no Shōbōtai","Enen no Shouboutai","Enen no Shouboutai: Ni no Shou","Enen no shôbôtai","En''en no Shouboutai Ni no Shou","Enn Enn no Shouboutai","Enen no Shōbōtai","Enen No Shouboutai - Ni no Shou","炎炎ノ消防隊 弐ノ章","炎炎ノ消防隊 参ノ章","Enen no Shouboutai San","Пламенная бригада пожарных","Пламенный отряд","Огненная бригада пожарных!","Огненная бригада","炎炎消防隊 貳之章","炎炎消防隊 參之章","Fire Brigade of Flames","Fireforce","Blazing Fire Brigade","Bộc Hỏa Nhân Tượng","炎炎ノ消防隊"]', 1784690324332);
