INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-duong-nu-phap-y', 'Đại Đường Nữ Pháp Y', 'Miss Truth', 'https://phimimg.com/upload/vod/20250409-1/36e815ab557961f9faa0f36072a53fe4.jpg', 'https://phimimg.com/upload/vod/20250409-1/8e3ec6d219f54424f455f8f2094082fb.jpg', '<p>Nội dung kể về một cô gái tên Nhiễm Nhan vì để điều tra và tìm hiểu nội tình cái chết của mẹ mình nên từ nhỏ đã theo học khám nghiệm tử thi, trở thành một nữ pháp y tài giỏi. Bằng khả năng tài ba của mình, Nhiễm Nhan đã chữa bệnh, cứu sống rất nhiều người, phá được nhiều vụ án, và dần dần phát hiện ra một tổ chức giết người bí ẩn. Trong quá trình điều tra phá án, cô cũng tìm được tình yêu đích thực của đời mình.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 9, 2020, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Khiết Quỳnh","avatar":""},{"name":"Lý Trình Bân","avatar":""},{"name":"Bùi Tử Thiêm","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["大唐女法医"]', 1784690324332);
