INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-duoc-cac-vi-sao-bao-truoc', 'Cậu Bé Được Các Vì Sao Báo Trước', 'The Boy Foretold By the Stars', 'https://phimimg.com/upload/vod/20250404-1/ca0ac3cfabec6f0a782487feddd4f2cf.jpg', 'https://phimimg.com/upload/vod/20250404-1/681354f1465debdf1b5c74a51c8816ee.jpg', '<p>Bộ phim kể về hai chàng trai học trung học phổ thông. Thông qua sự giúp đỡ của một thầy bói, họ tìm thấy nhau tại một kỳ tĩnh tâm tùy chọn của trường mang tên &quot;Hành Trình Cùng Chúa&quot; (Journey with the Lord). Bộ phim kết hợp yếu tố tâm linh và tình cảm tuổi học trò, mang đến một câu chuyện nhẹ nhàng nhưng đầy ý nghĩa về định mệnh và tình yêu.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Adrian Lindayag","avatar":""},{"name":"Keann Johnson","avatar":""},{"name":"Iyah Mina","avatar":""},{"name":"Rissey Reyes","avatar":""},{"name":"John Leinard Ramos","avatar":""},{"name":"Jan Rey Escaño","avatar":""},{"name":"Vic Robinson III","avatar":""},{"name":"Jemuel Satumba","avatar":""},{"name":"Renshi de Guzman","avatar":""},{"name":"Kalil Almonte","avatar":""},{"name":"Jethro Niño Tenorio","avatar":""},{"name":"Kristian Cartilla","avatar":""},{"name":"Pongs Leonardo","avatar":""},{"name":"Dolly Dulu","avatar":""},{"name":"Pat Ong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["The Boy Foretold By the Stars"]', 1784690324332);
