INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huu-phi', 'Hữu Phỉ', 'Legend Of Fei', 'https://phimimg.com/upload/vod/20250402-1/29968516f17a0dd9cd6338e6acc75836.jpg', 'https://phimimg.com/upload/vod/20250402-1/9417756836e8e02ea7f9a5f24bbb9ba7.jpg', '<p>Lấy bối cảnh Hậu Chiêu năm Kiến Nguyên thứ mười bảy, non sông chia Nam-Bắc cai trị, chiến tranh liên miên, các tuyệt đại cao thủ trong truyền thuyết lần lượt ngã xuống, chỉ còn lại bốn mươi tám trại náu mình giữa Thập Vạn Đại Sơn, nhân tài suy thoái, bụi vàng phủ hết anh hùng. Phim kể về cô con gái Chu Phỉ của đại đương gia bốn mươi tám trại rời nhà ra đi, từ đó trải bao gian nguy hiểm trở, cuối cùng trở thành danh đao một thời.</p>', 'Hoàn Tất (51/51)', 51, 'series', 'completed', 8, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lệ Dĩnh","avatar":""},{"name":"Vương Nhất Bác","avatar":""},{"name":"Trương Huệ Văn","avatar":""},{"name":"Trần Nhược Huyên","avatar":""},{"name":"Tôn Kiên","avatar":""},{"name":"Chu Khiết Quỳnh","avatar":""},{"name":"Trương Hân Vũ","avatar":""},{"name":"Lãnh Kỷ Nguyên","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["有翡（ゆうひ）-Legend of Love-　","Legend of Fei","有翡"]', 1784690324332);
