INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huu-phi', 'Hữu Phỉ', 'Legend Of Fei', 'hữu phỉ legend of fei triệu lệ dĩnh vương nhất bác trương huệ văn trần nhược huyên tôn kiên chu khiết quỳnh trương hân vũ lãnh kỷ nguyên 有翡（ゆうひ）-legend of love-　 legend of fei 有翡', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-bac-si-tai-hoa-phan-1', 'Những Bác Sĩ Tài Hoa (Phần 1)', 'Hospital Playlist (Season 1)', 'https://phimimg.com/upload/vod/20250331-1/8be1339e5c6bf3e1f78417ea9dc11a19.jpg', 'https://phimimg.com/upload/vod/20250331-1/1dab154e83fdb62269360e9950377e37.jpg', '<p>Những Bác Sĩ Tài Hoa (phần 1) đưa khán giả vào cuộc hành trình của năm bác sĩ thân thiết từ thời sinh viên tại Đại học Quốc gia Seoul, khi họ cùng nhau bắt đầu công việc tại bệnh viện Yulje. Với sự chỉ đạo của đạo diễn Shin Won-ho và sự tham gia của các diễn viên hàng đầu như Cho Jung-Seok, Yoo Yeon-Seok, Jung Kyung-ho, bộ phim này hứa hẹn mang đến trải nghiệm kịch tính và đầy cảm xúc. Được coi là một trong những tác phẩm y khoa ấn tượng, Những Bác Sĩ Tài Hoa chinh phục khán giả bằng cốt truyện sâu lắng và diễn xuất tinh tế của dàn diễn viên.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Jung-seok","avatar":""},{"name":"Yoo Yeon-seok","avatar":""},{"name":"Jung Kyung-ho","avatar":""},{"name":"Kim Dae-myung","avatar":""},{"name":"Jeon Mi-do","avatar":""},{"name":"Shin Hyun-been","avatar":""},{"name":"Ahn Eun-jin","avatar":""},{"name":"Kwak Sun-young","avatar":""},{"name":"Kim Joon","avatar":""},{"name":"Kim Hae-sook","avatar":""},{"name":"Jung Moon-sung","avatar":""},{"name":"Kim Hye-In","avatar":""},{"name":"Ha Yoon-kyung","avatar":""},{"name":"Moon Tae-yu","avatar":""},{"name":"Choi Young-jun","avatar":""},{"name":"Kim Soo-jin","avatar":""},{"name":"Bae Hyeon-seong","avatar":""},{"name":"Kim Kang-min","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["机智的医生生活","חוכמת הרפואה","Больничный плейлист","Мудрая врачебная жизнь","Мудрая жизнь в больнице","Hastane Günlükleri","機智醫生生活","Smart Doctor Living","Doctor Playbook","Wise Doctor Life","A Wise Doctor''s Life","hospital playlist","Seulgiroun Euisasaenghal","슬기로운 의사생활"]', 1784690324332);
