INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-huy-diet-phan-1', 'Sự Hủy Diệt (Phần 1)', 'Star Trek: Picard (Season 1)', 'https://phimimg.com/upload/vod/20231207-1/b1925cd071968656af904a894027b8d5.jpg', 'https://phimimg.com/upload/vod/20231207-1/3891a6caa9d96a2ac6791e48422b0901.jpg', '<p>Picard lấy mốc thời gian hai mươi năm sau những sự kiện xảy ra từ lần cuối cùng Jean – Luc Picar xuất hiện trong Star Trek: Nemesis. Nội dung bộ phim xoay quanh việc cái chết của Data tác động đến mọi người như thế nào, đồng thời đi sâu khai thác cụ thể hơn những thay đổi sau sự hủy diệt của Romulus.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patrick Stewart","avatar":""},{"name":"Alison Pill","avatar":""},{"name":"Michelle Hurd","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324332);
