INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-vo-cung-cuc', 'Sát Thủ Vô Cùng Cực', 'Hitman: Agent Jun', 'https://phimimg.com/upload/vod/20250318-1/4ef65665cfa9bcc7154344f66dcae450.jpg', 'https://phimimg.com/upload/vod/20250318-1/1d83069d37bf783da0d17446aa9bd182.jpg', '<p>Bộ phim điện ảnh mới đến từ tài tử “Nấc thang lên thiên đường” kể lại hành trình “hoàn lương” dở khóc dở cười của một cựu mật vụ với niềm đam mê vẽ truyện tranh.Sát thủ vô cùng cực (tựa Anh: Hitman: Agent Jun) mở đầu bằng một ngày nắng đẹp. Một gia đình ba người đang lái xe qua đèo thì bị một chiếc xe tải đi ngược chiều do gã tài xế gà gật điều khiển đâm phải. Trong khoảnh khắc sinh tử, cậu con trai của gia đình bèn phát huy siêu năng lực, đỡ lấy chiếc xe và cứu lấy cả gia đình.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Kwon Sang-woo","avatar":""},{"name":"Jung Jun-ho","avatar":""},{"name":"Hwang Woo-seul-hye","avatar":""},{"name":"Lee Yi-kyung","avatar":""},{"name":"Lee Ji-won","avatar":""},{"name":"Heo Sung-tae","avatar":""},{"name":"Jo Woon","avatar":""},{"name":"Heo Dong-won","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Lee Jung-ok","avatar":""},{"name":"Ju Seo-eun","avatar":""},{"name":"Lee Sang-yi","avatar":""},{"name":"Park Doo-sik","avatar":""},{"name":"Park Ye-chan","avatar":""},{"name":"Kim Mi-hui","avatar":""},{"name":"Bae Min-jun","avatar":""},{"name":"Hwang Byeng-gug","avatar":""},{"name":"Park Sung-jin","avatar":""},{"name":"Choi Y","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["hi-teu-maen","大画特务","Hitman: Agent Jun","漫畫威龍之大話特務","히트맨"]', 1784690324332);
