INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-than-2020', 'Xả Thân', 'Sacrifice', 'https://phimimg.com/upload/vod/20250318-1/c9bce461c92155e9ad41fd75abd19a70.jpg', 'https://phimimg.com/upload/vod/20250318-1/8c45162760d1d6127fb36d093d8c5daf.jpg', '<p>Năm 1953, Chiến tranh Triều Tiên đang bước vào giai đoạn cuối. Quân tình nguyện nhân dân Trung Quốc đã tiến hành trận đánh lớn cuối cùng ở Kumsong. Để đến chiến trường đúng giờ và cung cấp đủ lực lượng cho tiền tuyến Kumsong, những người lính phải tự bảo vệ mình trước những đợt ném bom không ngừng của máy bay ném bom đối phương và chạy đua với thời gian để sửa chữa các cây cầu, tất cả đều trong hoàn cảnh thiếu thốn và không có trang thiết bị cần thiết.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Yi","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Li Jiuxiao","avatar":""},{"name":"Vision Wei","avatar":""},{"name":"Deng Chao","avatar":""},{"name":"Du Jiang","avatar":""},{"name":"Ou Hao","avatar":""},{"name":"Qiu Tian","avatar":""},{"name":"Liu Xianda","avatar":""},{"name":"Shi Haozheng","avatar":""},{"name":"Zhou Siyu","avatar":""},{"name":"Zhang Zhe","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["The Sacrifice","Sacrifice","Jingang Chuan","Jin Gang Chuan","Sacrifice CN","金刚川"]', 1784690324332);
