INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-trang', 'Bão Trắng', 'The White War', 'https://phimimg.com/upload/vod/20250317-1/1505c1c274434805dd8564d3a1a87ed0.jpg', 'https://phimimg.com/upload/vod/20250317-1/520c8e9ab5718430a4258f4ca61fb809.jpg', '<p>Nội dung xoay quanh 3 anh em gồm Trình Thiên, Vệ Tuấn Hiên và Hứa Tu Bình đều làm việc cho cảnh sát, tuy nhiên tình cảnh lại khác nhau. Vệ Tuấn Hiên thì là cảnh sát 2 mặt vừa bắt tay 2 phe hắc bạc lưỡng đạo. Còn anh chàng Trình Thiên cũng là cảnh sát được cấp trên cài vào nằm vùng, nhưng vì sống trống môi trường hắc đạo đã lâu nên bị nhiễm tật xấu dần mất đi phương hướng về chính đạo. May mắn có người em là Hứa Tu Bình một trình thám còn sáng suốt, đã cố gằng tìm cách lôi 2 anh mình về chính đạo, thức tỉnh sửa sai.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2020, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Ngô Trác Hy","avatar":""},{"name":"Quan Trí Bân","avatar":""},{"name":"Châu Tú Na","avatar":""},{"name":"Ngô Thiên Ngữ","avatar":""},{"name":"La Gia Lương","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["White War","戰毒"]', 1784690324332);
