INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-bao-thu-cua-analia', 'Kế Hoạch Báo Thù Của Analia', 'Ana''s Revenge', 'https://phimimg.com/upload/vod/20250305-1/9b0be646e5de4684f54519aac9f20dfe.jpg', 'https://phimimg.com/upload/vod/20250305-1/707310a67657dab5277354defed923d8.jpg', '<p>Analia, một cô gái xinh đẹp quyết định trả thù kẻ đã giết mẹ mình, kẻ đó lại chính là ứng cử viên cho chức vụ Tổng thống Cộng hòa, Guillermo León Mejía. Cô lên kế hoạch để giành được sự tin tưởng của Guillermo, trở thành cố vấn chính trị quan trọng nhất, cánh tay phải của ông ta. Kế hoạch này liệu có khả thi?</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 11, 2020, 'Lồng Tiếng', 'FHD', 'Colombia', 0, '[{"name":"Carolina Gómez","avatar":""},{"name":"George Slebi","avatar":""},{"name":"Brian Moreno","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ana''s Revenge","La venganza de Analía"]', 1784690324332);
