INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-rong-hon', 'Kẻ Rỗng Hồn', 'The Empty Man', 'https://phimimg.com/upload/vod/20250304-1/f241ae1c18e7c420ec4c827aa16c7d6e.jpg', 'https://phimimg.com/upload/vod/20250304-1/f0eee3233e0ffae6448bc3ec427e492b.jpg', '<p>Cựu cảnh sát James Lasombra được một người bạn nhờ điều tra vụ mất tích của con gái bà, người dường như đã đóng gói đồ đạc vào ban đêm và để lại một lời nhắn đáng ngại trên gương phòng tắm - &quot;Người đàn ông trống rỗng đã bắt tôi làm vậy.&quot; Khi tiếp tục điều tra về nhân vật bí ẩn này, James bắt đầu nhìn thấy và nghe thấy những điều kỳ lạ, và buộc phải đối mặt với quá khứ của mình và ý nghĩa của nó đối với tương lai.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'FHD', 'Nam Phi', 0, '[{"name":"James Badge Dale","avatar":""},{"name":"Marin Ireland","avatar":""},{"name":"Sasha Frolova","avatar":""},{"name":"Samantha Logan","avatar":""},{"name":"Evan Jonigkeit","avatar":""},{"name":"Virginia Kull","avatar":""},{"name":"Robert Aramayo","avatar":""},{"name":"Ron Canada","avatar":""},{"name":"Jessica Matten","avatar":""},{"name":"Aaron Poole","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Jamie-Lee Money","avatar":""},{"name":"Owen Teague","avatar":""},{"name":"Joel Courtney","avatar":""},{"name":"Connor Dowds","avatar":""},{"name":"Vere Tindale","avatar":""},{"name":"Tanya van Graan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Пустий","Empty Man: El mensajero del último día","The Empty Man: El Mensajero del último día","L''uomo Vuoto","The Empty Man"]', 1784690324332);
