INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-xanh-sau-tham-3', 'Biển Xanh Sâu Thẳm 3', 'Deep Blue Sea 3', 'https://phimimg.com/upload/vod/20250302-1/bb9a9172a1233b4e187e5cf1a63352c4.jpg', 'https://phimimg.com/upload/vod/20250302-1/fc019c004e4f0f50e1529ef74bab97cf.jpg', '<p>Phim xoay quanh bác sĩ Emma Collins, người lãnh đạo một nhóm tại một hòn đảo nhỏ nghiên cứu ảnh hưởng của biến đổi khí hậu đối với cá mập trắng lớn . Nghiên cứu bị gián đoạn khi bạn trai cũ của nhà sinh vật học biển tên Richard đến, tìm kiếm một số con cá mập tăng cường . Bộ phim đạt được điểm R về bạo lực, hình ảnh đẫm máu và ngôn ngữ. Dự án sẽ được phân phối bởi Warner Bros. Entertainment Entertainment .Tiến sĩ Emma Collins và nhóm của cô đang dành mùa hè thứ ba của mình trên đảo Little Happy để nghiên cứu ảnh hưởng của biến đổi khí hậu đối với những con cá mập trắng lớn đến vườn ươm gần đó mỗi năm để sinh con. Cùng với hai cư dân cuối cùng của làng chài cũ này, cuộc sống yên bình của họ bị phá vỡ ...</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tania Raymonde","avatar":""},{"name":"Nathaniel Buzolic","avatar":""},{"name":"Emerson Brooks","avatar":""},{"name":"Bren Foster","avatar":""},{"name":"Reina Aoi","avatar":""},{"name":"Alexander Bhat","avatar":""},{"name":"Siya Mayola","avatar":""},{"name":"Avumile Qongqo","avatar":""},{"name":"Brashaad Mayweather","avatar":""},{"name":"Ernest St Claire","avatar":""},{"name":"DeVille Vannik","avatar":""},{"name":"Alex Bhat","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng"