INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoanh-khac-rung-dong', 'Khoảnh Khắc Rung Động', 'Sparkle Love', 'https://phimimg.com/upload/vod/20250302-1/db69ab71005dafd4ae7580371dc006cf.jpg', 'https://phimimg.com/upload/vod/20250302-1/283444fee5a291f9287fc91fa58df11d.jpg', '<p>Khoảnh Khắc Rung Động kể về nam thần bơi lội đánh úp trái tim thiếu nữ tạo nên khoảnh khắc rung động con tim. Bộ phim lấy bối cảnh học đường cả 2 diễn viên chính đều quay trở về thời học sinh mới lớn và tình yêu chớm nở, ban đầu Lăng Mỹ Sĩ và Trương Lăng Hách căm ghét, không ưa gì nhau nhưng về sau cô nàng lại bắt đầu rung động trước ngoại hình điển trai của cậu học sinh giỏi bơi lội. Đúng với câu “ghét của nào trời trao của đó”, xen lẫn những chuyện tình cảm của cặp đôi nam nữ phim Khoảnh Khắc Rung Động còn có thêm yếu tố hài hước. Đây là bộ phim với sự góp mặt của nữ diễn viên quen thuộc trong phim Thiếu Nữ Đại Nhân hứa hẹn sẽ mang một làn gió mới không phải là cổ trang nữa dành cho khán giả phim hoa ngữ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lăng Mỹ Sĩ","avatar":""},{"name":"Trương Lăng Hách","avatar":""},{"name":"Sư Minh Trạch","avatar":""},{"name":"Sách Lãng Mỹ Kỳ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ритм моего сердца","心动的瞬间"]', 1784690324332);
