INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-muu-va-tinh-yeu-phan-2', 'Âm Mưu Và Tình Yêu (Phần 2)', 'Stay Together, My Love (Season 2)', 'https://phimimg.com/upload/vod/20250301-1/7816047cec2cba229792767b6ed8822f.jpg', 'https://phimimg.com/upload/vod/20250301-1/6a50e2fc26ab6b8d56e44717d1359e63.jpg', '<p>Câu chuyện về cuộc đời nhân vật Gopi đại diện cho sự hiền lành và lương thiện, thường xuyên bị hãm hại bởi người chị họ Rashi hay bị lừa gạt bởi những kẻ mưu mô bên ngoài. Tuy nhiên cô luôn luôn gặp may mắn, theo đúng luật nhân quả ‘Ở hiền gặp lành’. Đó là nội dung chính của bộ phim truyện Ấn Độ - ‘Âm mưu và tình yêu’.&nbsp; Với nội dung hoàn toàn mới dựa trên những nhân vật cũ được yêu thích từ phần 1 -&nbsp; Bộ phim truyện Ấn Độ ‘Âm mưu và tình yêu’ - Phần 2 hứa hẹn sẽ tiếp tục mang đến cho khán giả nhiều điều bất ngờ thú vị hơn.</p>', 'Hoàn Tất (410/410)', 410, 'series', 'completed', 7, 2020, 'Lồng Tiếng', 'FHD', 'Ấn Độ', 0, '[{"name":"Sneha Jain","avatar":""},{"name":"Harsh Nagar","avatar":""},{"name":"Jay Pathak","avatar":""},{"name":"Aliraza Namdar","avatar":""},{"name":"Nadia Himani","avatar":""},{"name":"Prakash Waghela","avatar":""},{"name":"Anuradha Aalia Namdar","avatar":""},{"name":"Rupal Patel","avatar":""},{"name":"Akanksha Juneja","avatar":""},{"name":"Devoleena Bhattacharjee","avatar":""},{"name":"Mohammad Nazim Khilji","avatar":""},{"name":"Vandana Vithlani","avatar":""},{"name":"Manish Arora","avatar":""},{"name":"Swati Shah","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad35638