INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-danh', 'Giả Danh', 'Good Casting', 'https://phimimg.com/upload/vod/20250224-1/c593d44d19d160a0b8309a3a6be7aabe.jpg', 'https://phimimg.com/upload/vod/20250224-1/ff5033e75065d803dc6955aed5b8c4bf.jpg', '<p>Bộ phim xoay quanh nhân vật Baek Chan-Mi (Choi Gang-Hee) là một đặc vụ mật huyền thoại của NIS, nhưng do công việc quá mức của cô, cấp dưới của cô đã chết và cô đã bỏ lỡ mục tiêu của mình. Baek Chan-Mi đã bị phạt vì vụ án bất thành đó và hiện cô làm việc trong một nhóm an ninh mạng cho NIS. Baek Chan-Mi sau đó được chọn để theo dõi một vụ án liên quan đến trộm cắp tài sản trí tuệ tại công ty lớn nhất Hàn Quốc.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Kang-hee","avatar":""},{"name":"Yoo In-young","avatar":""},{"name":"Kim Ji-young","avatar":""},{"name":"Lee Sang-yeob","avatar":""},{"name":"Lee Jong-hyuk","avatar":""},{"name":"Lee Jun-young","avatar":""},{"name":"Heo Jae-ho","avatar":""},{"name":"Jeong In-gi","avatar":""},{"name":"Jo Yeong-hoon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["好角色","特務阿珠媽","굿 캐스팅","Miss Casting","Good Casting","굿캐스팅"]', 1784690324332);
