INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-la-nang-ploy-ay', 'Vẫn Là Nàng Ploy Ấy', 'Unlucky Ploy', 'https://phimimg.com/upload/vod/20250224-1/b203ce09b035160fdefcfd897e0e5714.jpg', 'https://phimimg.com/upload/vod/20250224-1/7730be6bc73f1e3cd67b17e5e718a382.jpg', '<p>Phim kể về hai cô gái mang cùng cái tên Ploy liên quan đến nhau ngay từ ghế nhà trường. Trong đó có một Proy xinh đẹp và một Ploy xấu xí. Nam chính là vị hôn phu cũ của Proy xinh đẹp nhầm tưởng đám cưới của Ploy xấu xí là vị hôn thê cũ của mình nên tìm mọi cách phá hoại hôn nhân này. Chỉ đến khi Ploy xấu xí bị hủy hôn, anh chàng mới nhận ra mình đã nhầm người mất rồi. Trùng hợp thay, Ploy xấu xí từng xuất hiện trong những ảo cảnh tiên tri mà anh chàng nhìn thấy từ sau một vụ tai nạn. Vì điểm chung đều cùng bị bỏ rơi ngay trước ngày cưới, cả hai nhanh chóng trở nên thân thiết với nhau. Thậm chí anh chàng còn bắt đầu có tình cảm với Ploy xấu xí dù vẫn luôn phủ nhận điều đó. Liệu chuyện tình cảm của hai người sẽ thế nào khi đến ngày nọ Ploy xấu xí nhận ra người mình đang yêu chính là người đã phá hủy hôn lễ trước đó của mình. Liệu cả hai sẽ vượt qua nỗi sợ về việc anh chàng liên tục nhìn thấy cái chết của mình lặp đi lập lại trong những giấc mơ?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Anusorn Maneeted","avatar":""},{"name":"Ausadaporn Siriwattanakul","avatar":""},{"name":"Thanidaphat Tinsutthinanon","avatar":""},{"name":"Thanavate Siriwattanakul","avatar":""},{"name":"Kitsadee Phuangprayong","avatar":""},{"name":"Kittiphong Dumaviphat","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Unlucky Ploy","ชีช้ำกะหล่ำพลอย"]', 1784690324332);
