INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-dau-3', 'Mất Dấu 3', 'Line Walker: Bull Fight', 'https://phimimg.com/upload/vod/20250218-1/9b63e6a1e56683bdb4a2c63960ab99b7.jpg', 'https://phimimg.com/upload/vod/20250218-1/c695e4b20512a6cdabc903574c0b47c0.jpg', '<p>Tiết Gia Cường tiếp tục cùng CIB (Cục Tình Báo Hình Sự) thi hành nhiệm vụ truy bắt nhiều tội phạm khác nhau, trong khi đó Trác Khải vì 3 năm trước đã bắn kẻ đầu não của tập đoàn tội phạm là Tiền Thụy An bị thương nên bị phán 3 năm tù giam. Sau khi mãn hạn tù, anh chọn mở quán cà phê cùng vợ mình là Mạc Tiễn Tình để sinh sống ổn định nhưng lại phải đối mặt với nguy cơ bị đám người hắc bang truy sát. Mặt khác, Tổng Thanh Tra của CIB là Chương Kỷ Tư và nội gián trước đây của Trác Khải là Trịnh Thục Mai nghi ngờ rằng Trác Khải có ý định gia nhập hắc đạo, nên bí mật điều tra quan hệ giữa Trác Khải và đám người của hắc đạo...</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 8, 2020, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Raymond Lam Fung","avatar":""},{"name":"Michael Miu Kiu-Wai","avatar":""},{"name":"Ma Kwok-Ming","avatar":""},{"name":"Benjamin Yuen Wai-Ho","avatar":""},{"name":"Mandy Wong","avatar":""},{"name":"Priscilla Wong","avatar":""},{"name":"Sisley Choi","avatar":""},{"name":"Owen Cheung","avatar":""},{"name":"Benz Hui Siu-Hung","avatar":""},{"name":"Tony Hung","avatar":""},{"name":"Shiga Lin Si-Nga","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324332);
