INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mat-dau-3', 'Mất Dấu 3', 'Line Walker: Bull Fight', 'mất dấu 3 line walker: bull fight raymond lam fung michael miu kiu-wai ma kwok-ming benjamin yuen wai-ho mandy wong priscilla wong sisley choi owen cheung benz hui siu-hung tony hung shiga lin si-nga ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-vo-hinh', 'Cuộc Sống Vô Hình', 'Invisible Life', 'https://phimimg.com/upload/vod/20250218-1/925721dc2c9a8ef7cb1f9310375e6954.jpg', 'https://phimimg.com/upload/vod/20250218-1/e4c735caaeb2ab79beb1e6e6b74a743c.jpg', '<p>Phim kể về mối tình của Diệp Tiểu Bạch và Quản Nhất Hạc. Tiểu Bạch là một cô gái giàu trí tưởng tượng, mãi mới được thăng chức lại bị bạn trai cắm sừng, còn bị hiểu lầm là tiểu tam, cuộc sống trong nháy mắt sụp đổ. Để chạy trốn không bị bố mẹ bức hôn, cô chủ động yêu cầu đi công tác cùng với Nhất Hạc. Đúng lúc tình cảm giữa cả hai đang tốt đẹp, Triệu Kim Tử lại chen vào mối quan hệ của hai người. Nhất Hạc nhất quyết từ chối Kim Tử. Trải qua muôn vàn khó khăn, cả hai quyết định đi tới hôn nhân. Khi tình yêu gặp phải hiện thực nghiệt ngã, những hứa hẹn khi xưa liệu có thành sự thật? Cuối cùng, liệu cả hai có quay về với nhau?</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 9, 2020, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Đô Linh","avatar":""},{"name":"Lưu Khải Uy","avatar":""},{"name":"Huỳnh Thước Văn","avatar":""},{"name":"Đặng Sa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["太太万岁","Invisible Life","这就是生活"]', 1784690324332);
