INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-thu-2020-phim-bo', 'Xạ Thủ', 'Sniper', 'https://phimimg.com/upload/vod/20250217-1/8f400f47521813fa81a44dfefa9a781e.jpg', 'https://phimimg.com/upload/vod/20250217-1/88b8d1acdfc70bc663c906ee4e668944.jpg', '<p>Vào mùa xuân năm 1949, vì loại bỏ tổ chức ám sát bí mật và cố gắng khởi nghĩa , Tô Văn Khiêm cùng với tổ chuyên án phối hợp đối phó với sát thủ Trì Thiết Thành, người mà Tô Văn Khiêm sát cánh nhiều năm. Vì quyết tâm mọi việc để ngăn chặn âm mưu ám sát, hai bậc thầy bắn cùng nhau chiến đấu gay gắt, quyết liệt. Cuối cùng, công lý cũng đánh bại cái ác.</p>', 'Hoàn Tất (57/57)', 57, 'series', 'completed', 8, 2020, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Hiên","avatar":""},{"name":"Trần Hách","avatar":""},{"name":"Dương Thái Ngọc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Sniper","瞄准"]', 1784690324332);
