INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-nha-van-tao-bao-phan-1', 'Nữ Nhà Văn Táo Bạo (Phần 1)', 'Valeria (Season 1)', 'https://phimimg.com/upload/vod/20240920-1/a8a36b63609b50db0ed07033ce4f8804.jpg', 'https://phimimg.com/upload/vod/20240920-1/0162d91868b177458a77fbb752bd5caa.jpg', '<p>Sáng tạo thì bế tắc, hôn nhân thì trục trặc, nữ nhà văn tìm đến sự ủng hộ của ba cô bạn cũng đang khám phá chính mình. Phim dựa trên tiểu thuyết của Elísabet Benavent.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2020, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Diana Gómez","avatar":""},{"name":"Silma López","avatar":""},{"name":"Paula Malia","avatar":""},{"name":"Teresa Riott","avatar":""},{"name":"Maxi Iglesias","avatar":""},{"name":"Juanlu González","avatar":""},{"name":"Federico Aguado","avatar":""},{"name":"José Pastor","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Valeria"]', 1784690324332);
