INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bang-dang-luan-don-phan-1', 'Băng Đảng Luân Đôn (Phần 1)', 'Gangs Of London (Season 1)', 'băng đảng luân đôn (phần 1) gangs of london (season 1) jasmine armando orli shuka sope dirisu joe cole lucian msamati michelle fairley narges rashidi brian vernel fady elsayed pippa bennett-warner waleed zuaiter aymen hamdouchi asif raza mir gangues de londres 伦敦黑帮 gangs of london', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-nguc-toi-phan-3', 'Hầm Ngục Tối (Phần 3)', 'Danmachi (Season 3)', 'https://phimimg.com/upload/vod/20250214-1/c48d3ec0174acbfece1e0892c0a6cbe0.jpg', 'https://phimimg.com/upload/vod/20250214-1/73f54286581f95129cce2f5789f80405.jpg', '<p>Tại thành phố Orario phồn hoa mà trung tâm là mê cung dưới lòng đất &quot;Dungeon&quot;, một cậu bé tên Bell Cranell, đã chạy ra với mong ước &quot;gặp được định mệnh với người con gái đời mình&quot;. Một ngày nọ Bell bị một con quái vật tấn công và được cứu bởi Aiz Wallenstein - cô gái thám hiểm đứng đầu lớp. Trong thời khắc đó, Bell đã yêu Aiz ngay từ cái nhìn đầu tiên, và cậu ta bắt đầu hành động để một ngày nào đó có thể trở thành một nhà thám hiểm phù hợp với Aiz.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Saori Onishi","avatar":""},{"name":"Chinatsu Akasaki","avatar":""},{"name":"Haruka Chisuga","avatar":""},{"name":"Yurika Kubo","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Shizuka Ishigami","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Yuka Iguchi","avatar":""},{"name":"Masaaki Mizunaka","avatar":""},{"name":"Wakana Kowaka","avatar":""},{"name":"Yuuki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be11