INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mien-dat-hua', 'Miền Đất Hứa', 'The Promised Neverland', 'miền đất hứa the promised neverland minami hamabe kairi jo rihito itagaki keiko kitagawa naomi watanabe miyu andô halo asada soma santoki yurito mori natsuki deguchi the promised neverland yakusoku no neverland 約束のネバーランド', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('na-tra-hang-yeu-ky', 'Na Tra Hàng Yêu Ký', 'Heroic Journey Of Ne Zha', 'https://phimimg.com/upload/vod/20250210-1/6604c7366840ab964b4af3266093c404.jpg', 'https://phimimg.com/upload/vod/20250210-1/d7d4a99ae02bbed1386e78932e8026da.jpg', '<p>Na Tra&nbsp;nhìn thấy thiên hạ đại hạn, không nỡ để chúng sinh gặp nạn, nên đã đi đến Thủy tộc đòi hỏi công lý. Trong buổi tiệc thọ ở Đông Hải, Na Tra đã giao chiến ác liệt với Ngao Bính, con trai thứ ba của Đông Hải Long Vương. Tuy nhiên, do tộc yêu quái cản trở, họ đã giết chết Ngao Bính rồi vu tội cho Na Tra. Đông Hải Long Vương tiến đến Trần Đường Quan đòi hỏi công lý, Na Tra vì không muốn liên lụy đến cha mẹ, đã tự sát tại chỗ để tạ lỗi. Na Tra vốn là Linh Châu Tử, tất cả đều là kiếp nạn trong số mệnh của anh. Thái Ất Chân Nhân đã dùng ngó sen làm xương, lá sen làm y phục, tạo lại thân tiên cho Na Tra, khiến anh sống lại. Tuy nhiên, cái giá phải trả có hai điều: thứ nhất, Na Tra phải vào trần gian tìm lại năm món pháp bảo mang theo người; thứ hai, phải giúp Tiểu Long Nữ đánh bại Xà Cơ, phục hưng Thủy tộc. Chỉ có như vậy, Na Tra mới có thể trả hết mọi tội lỗi và trở lại trần gian, đoàn tụ với gia đình. Sau đó, Na Tra phát hiện ra rằng đại hạn ngày xưa và cái chết của Ngao Bính đều là mưu đồ của Xà Cơ để giành lấy quyền lực. Xà Cơ và Đại Đế yêu quái đã liên kết, giam giữ bốn vị Long Vương, biến cung điện rồng thành nơi trị vì của mình, trở thành vua của bốn biển. Trong quá trình cùng nhau tìm kiếm pháp bảo và chống lại sự truy đuổi của Xà Cơ, Tiểu Long Nữ và Na Tra từ vị trí thù địch không tin tưởng dần dần xây dựng được tình cảm sâu đậm, hợp tác cùng nhau. Cuối cùng, hai người đã thu thập đủ năm món pháp bảo, đánh bại Xà Cơ và Đại Đế yêu quái, phục hưng Thủy tộc và thực thi công lý.</p>', 'Hoàn Tất (46/46)', 46, 'series', 'completed', 8, 2020, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Tưởng Y Y","avatar":""},{"name":"Ngô Giai Di","avatar":""},{"name":"Đại Siêu","avatar":""},{"name":"Thôi Nhã Hàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["哪吒降妖记","哪咤降妖记","Ne Zha Jiang Yao Ji","Heroic Journey of Nezha"]', 1784690324332);
