INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buong-giam-mat-na', 'Buồng Giam Mặt Nạ', 'Masked Ward', 'https://phimimg.com/upload/vod/20231206-1/489fd142060b9076817a889fe0516983.jpg', 'https://phimimg.com/upload/vod/20231206-1/057742b7ee7332bc532c83ec4e811d56.jpg', '<p>Phim Buồng Giam Mặt Nạ | Masked Ward 2020 thuyet minh full hd xoay quanh câu chuyện kể về Shugo Hayami là bác sĩ tại một bệnh viện điều dưỡng mà trước đó từng là bệnh viện tâm thần. Một buổi tối, khi Shugo đang làm nhiệm vụ trực đêm, tên thủ phạm cướp tiền đeo mặt nạ chú hề đã đột nhập vào bệnh viện cùng con tin Hitomi Kawasaki. Liệu đây chỉ là một vụ án giữ người cướp của, còn chuyện gì ẩn sau những con người trong bệnh viện ấy?</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub + Thuyết Minh', 'HD', 'Nhật Bản', 0, '[{"name":"Aki Asakura","avatar":""},{"name":"Kentaro Sakaguchi","avatar":""},{"name":"Mei Nagano","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324332);
