INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-gap-anh-ay-o-hong-kong', 'Tôi Gặp Anh Ấy Ở Hồng Kông', 'The Journey Across The Night', 'https://phimimg.com/upload/vod/20250204-1/2813b4b9bc95f11c6a2c34ab2fd27eec.jpg', 'https://phimimg.com/upload/vod/20250204-1/a2238b31e6002b189635ef39006303ad.jpg', '<p>Bộ phim kể về nhân vật chính Lý Gia (Tăng Thuấn Hy đóng), sau khi mắc chứng tâm thần phân liệt từ mẹ và anh trai, phải chịu gánh nặng về bệnh di truyền này, đã quyết định đến Hồng Kông làm nghiên cứu sinh. Do ký túc xá đại học chật hẹp, cậu phải đi thuê nhà xung quanh. Từ đó, cậu quen với nhân viên môi giới nhà kỳ lạ Trương Xoa Xoa (Nhan Trác Linh đóng) và đàn em ngành giải phẫu học Thời Thành (Chu Trừng Áo đóng). Trong quá trình tìm nhà ở nhiều nơi, cậu đã gặp Tiêu Tê (Phùng Kiến Vũ), người được gọi là “sư phụ sắc bén”. Khi còn nhỏ , Tiêu Tê có năng lực phi thường. Khi lớn, anh đã nhận hai người học việc ở tuổi đôi mươi. Kể từ đó, Lý Gia và những người bạn đã gặp phải một loạt người lạ bí ẩn và nhiều câu chuyện phức tạp khác nhau.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 8, 2020, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tăng Thuấn Hy","avatar":""},{"name":"Nhan Trác Linh","avatar":""},{"name":"Chu Trừng Áo","avatar":""},{"name":"Phùng Kiến Vũ","avatar":""},{"name":"Ngô Khai Hoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Journey Across the Night","我在香港遇见他"]', 1784690324332);
