INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kaguyasama-muon-to-tinh-tinh-chien-cang-nao-cua-cac-thien-tai2', 'Kaguya‑sama muốn tỏ tình ~Tình chiến căng não của các thiên tài~2', 'かぐや様は告らせたい～天才たちの恋爱头脳戦～ 第 2 期', 'https://phimimg.com/upload/vod/20250118-1/9d9ae94ee6392e0d911c34379c581a47.jpg', 'https://phimimg.com/upload/vod/20250118-1/97b06fccc85fe00d8281d36a13da545b.jpg', '<p>Câu chuyện tình yêu giữa hội phó Kaguya Shinomiya và hội trưởng Miyuki Shirogane, 2 trong số những thiên tài của học viện Shuchiin, ngôi trường ưu tú nơi hội tụ những người tài năng. Hai người họ gặp nhau tại hội gặp mặt học sinh, dần nhận ra tình cảm dành cho đối phương, nhưng lòng kiêu hãnh của những thiên tài không cho phép họ thú nhận và ngỏ lời trước, và dẫn đến trận chiến khiến đối phương phải tỏ tình trước bắt đầu!!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 14, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324332);
