INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-can-quen-phai-nho', 'Người Cần Quên Phải Nhớ', 'What We Forgot to Remember', 'https://phimimg.com/upload/vod/20230918-1/35f008d5b70c8df311a332ed4e527510.jpg', 'https://phimimg.com/upload/vod/20230918-1/34309123c64377a25a67f2e9479356be.jpg', '<p><span style="font-family: ">Người Cần Quên Phải Nhớ xoay quanh nữ phóng viên Loan thuộc tòa soạn CP. Express, tác phẩm sẽ đưa khán giả theo chân nàng ta điều tra, vén màn bí mật đằng sau những cái chết bí ẩn. Trong lúc thu thập chứng cứ, cô tình cờ gặp gỡ và dần phải lòng Bình, chàng thanh niên lang bạt bị mất trí nhớ đồng thời là &quot;đối tượng tình nghi&quot; trong vụ án.</span></p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Hoàng Yến Chibi","avatar":""},{"name":"Trần Ngọc Vàng","avatar":""},{"name":"Huyme","avatar":""},{"name":"Karen Nguyễn","avatar":""},{"name":"Thái Hòa","avatar":""},{"name":"Xuân Phúc","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324333);
