INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-tai-bat-dac-di', 'Gia Tài Bất Đắc Dĩ', 'Brilliant Heritage', 'https://phimimg.com/upload/vod/20240112-1/c840dff41d74ea353ba258b80a89aaf8.jpg', 'https://phimimg.com/upload/vod/20240112-1/cdc1e01df72c947ece3dd7045451e7c5.jpg', '<p>Boo Young Bae, chủ một tiệm mì đã 50 năm tuổi, cảm thấy sức khỏe mình ngày càng suy giảm. Tuy nhiên, những người con trai của ông lại chỉ quan tâm tới tài sản của cha. Cảm thấy bị các con phản bội, ông quyết định kết hôn giả với Gye Ok - cô giúp việc độc thân 33 tuổi. Ban đầu, ông cũng nghĩ Gye Ok nhằm vào gia sản của mình nhưng sau đó, ông bị thuyết phục bởi sự chăm chỉ và tinh thần mạnh mẽ của cô.</p>', 'Hoàn Tất (122/122)', 122, 'series', 'completed', 8, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park In Hwan","avatar":""},{"name":"Kang Se Jung","avatar":""},{"name":"Shin Jung Yoon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324333);
