INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-an-cua-than-phan-1', 'Đặc Ân Của Thần (Phần 1)', 'By The Grace Of The Gods (Season 1)', 'https://phimimg.com/upload/vod/20241228-1/f8443137f452f6ebcaaaa69b2120a01e.jpg', 'https://phimimg.com/upload/vod/20241228-1/b7b72f740c8de2640c340dafb620cd69.jpg', '<p>Dưới sự bảo hộ của các vị thần, một cuộc sống giản đơn cùng slime ở thế giới khác đã bắt đầu! Một ngày nọ, tại Nhật Bản, cuộc đời của một doanh nhân tuổi trung niên có tên Ryoma Takebayashi đã chính thức “game over” một cách đột ngột và “thất vọng vì cái sự over” này. Sống ở đời, không biết do nghiệp hay vì lý do gì mà cuộc sống của Ryoma chưa bao giờ gặp được may mắn. Nhưng trong cái rủi có cái may. Sau khi chết, ba vị thần vĩ đại đã tìm đến anh và tái sinh anh ta trở thành một đứa trẻ ở thế giới khác, sở hữu kiếm và có ma thuật! Với sự chào đón nồng nhiệt và thiêng liêng nhất từ các vị thần, Ryoma đã quyết định tự mình sống nhàn nhã trong một khu rừng ở thế giới đó. Làm việc một cách cật lực với ma thuật của mình và săn bắn thứ gì đó. Niềm đam mê lớn nhất của Ryoma là nghiên cứu về những thứ mình thuần hóa được. Anh đang đào tạo các slime, bức màn sẽ được vén lên trong thế giới giả tưởng của Ryoma.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Azusa Tadokoro","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Makoto Koichi","avatar":""},{"name":"Marika Kouno","avatar":""},{"name":"Makoto Furukawa","avatar":""},{"name":"Kikuko Inoue","avatar":""},{"name":"Yuuki Kuwahara","avatar":""},{"name":"Motomu Kiyokawa","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Yuuki Takada","avatar":""},{"name":"Yui Fukuo","avatar":""},{"name":"Yuuki Hirose","avatar":""},{"name":"Tetsu Inada","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["众神眷顾的男人","被众神捡到的男孩","Por la gracia de los dioses","Por la gracia de los Dioses","Kami-tachi ni Hirowareta Otoko","Kamitachi ni Hirowareta Otoko","Kamihiro","Kami-tachi ni Hirowareta Otoko 2","신들에게 주워진 남자","Милостью богов","眾神眷顧的男人","The Man Picked Up by the Gods","神達に拾われた男"]', 1784690324333);
