INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-ca-tinh-ban', 'Hơn Cả Tình Bạn', 'More Than Friends', 'https://phimimg.com/upload/vod/20241218-1/802ce76e0ff492fe94f62b20ef0b8f3a.jpg', 'https://phimimg.com/upload/vod/20241218-1/6401f1dd8dc7bd42654928f2596c5f98.jpg', '<p>Hơn Cả Tình Bạn là bộ phim tình cảm lãng mạn do đài JTBC sản xuất, với sự tham gia diễn xuất của cặp đôi nam thanh nữ tú: Ong Seong Woo và Shin Ye Eun. Trong phim Seong Woo vào vai Lee Soo, một nhiếp ảnh gia tài năng và Ye Eun hóa thân thành Kyung Woo Yeon, nữ thư pháp xinh đẹp. Bộ phim sẽ diễn tả mối tình đơn phương lẫn nhau kéo dài trong mười năm của hai nhân vật chính từ thời còn đi học đến lúc trưởng thành.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ong Seong-wu","avatar":""},{"name":"Shin Ye-eun","avatar":""},{"name":"Kim Dong-jun","avatar":""},{"name":"Pyo Ji-hoon","avatar":""},{"name":"Ahn Eun-jin","avatar":""},{"name":"Choi Chan-ho","avatar":""},{"name":"Baek Soo-min","avatar":""},{"name":"Kim Hee-jung","avatar":""},{"name":"Ahn Nae-sang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["มากกว่าเพื่อนจะได้ไหม","境遇之數","More Than Friends","경우의 수"]', 1784690324333);
