INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-kham-y-khoa-cho-quai-vat', 'Phòng Khám Y Khoa Cho Quái Vật', 'Monster Girl Doctor', 'https://phimimg.com/upload/vod/20241218-1/fd8c65cea5526ce3320f98a269a5a03c.jpg', 'https://phimimg.com/upload/vod/20241218-1/86bef9019cd23c522c7d7c4ad87ed75d.jpg', '<p>Thị trấn Lindworm, nơi quái thú và con người sinh sống cùng nhau. Hôm nay, Glenn - bác sĩ vừa tốt nghiệp cũng đang tiến hành công việc kiểm tra sức khỏe nguy hiểm ư!? Từ kiểm tra vùng sâu thẳm trên cơ thể người cá, đến việc giúp khâu vết thương trên đùi của Flesh Golem, giúp Happy đẻ trứng, sờ mó từng vảy rồng để khám trực tiếp... Tác phẩm đầu tiên trong lịch sử kể về quá trình khám chữa bệnh ly kỳ cho cộng đồng quái thú!</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shunichi Toki","avatar":""},{"name":"Saori Onishi","avatar":""},{"name":"Sarah Emi Bridcutt","avatar":""},{"name":"Yu Shimamura","avatar":""},{"name":"Yukiyo Fujii","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Monster Mususme no Oishasan","Monster Musume no Oisha-san","Monster Musume no Oisha san","Monisha","Mon-isha","Monster Gril Doctor","The Doctor for Monster Girls","モンスター娘のお医者さん"]', 1784690324333);
