INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-dinh-co-yeu-khi', 'Triều Đình Có Yêu Khí', 'Feel The Fairies', 'https://phimimg.com/upload/vod/20241218-1/3e183be2235ef3bc322abf4c4a2a4efd.jpg', 'https://phimimg.com/upload/vod/20241218-1/96e06ab750020f1eaabed5ffad6b4b83.jpg', '<p>Thế lực của yêu tinh ngày càng chiếm cứ triều đình. Để sinh tồn, Thẩm Khanh Chi đã chấp nhận làm tiểu đệ của Trang Tử Khâm, cùng nhau lột trần từng lớp màn bí ẩn trong thành Hi Nguyệt. Trong chặng đường này, tính cách và thân phận thật của Trang Tử Khâm cũng dần dần hé lộ. Thẩm Khanh Chi: “Huynh hay nhắm vào ta như vậy là vì yêu thầm ta sao?” Trang Tử Khâm: “Không, ta chỉ đơn giản là đang nhắm vào ngươi thôi.”</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324333);
