INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-bep-lap-di', 'Đầu Bếp Lập Dị', 'Eccentric! Chef Moon', 'https://phimimg.com/upload/vod/20241218-1/9909a8d6d08e493a508d1ca0fb08b6a6.jpg', 'https://phimimg.com/upload/vod/20241218-1/57fc26a64c557ac385dda39a96130dcb.jpg', '<p>Đầu Bếp Lập Dị kể về Moon Seung Mo là một đầu bếp vô cùng nổi tiếng nhưng đã chuyển đến ngôi làng Seoha sinh sống sau khi bố mẹ anh qua đời vì hỏa hoạn. Thế rồi một ngày kia, cuộc sống yên bình êm ả của anh bị xáo trộn bởi sự xuất hiện bất ngờ của cô gái có tên Yoo Yoo Jin. Yoo Yoo Jin là một nhà thiết kế thời trang xinh đẹp và nổi tiếng thế giới. Cô làm việc dưới cái tên Yoo Bella. Bất ngờ xảy ra khi cô bị tai nạn xe hơi. Vụ tai nạn xe hơi khiến cô mất trí nhớ hoàn toàn và cuối cùng cô dọn đến làng Seoha để nghỉ dưỡng.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Eric Mun","avatar":""},{"name":"Go Won-hee","avatar":""},{"name":"Cha Jung-won","avatar":""},{"name":"Jang Jae-ho","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"Kil Hae-yeon","avatar":""},{"name":"Ryan","avatar":""},{"name":"Lee Seung-yeon","avatar":""},{"name":"Cha Chung-hwa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Yoobyeolna! Chef Moon","Yoo Byul Na! Chef Moon","Unique! Chef Moon","유별나! 문셰프"]', 1784690324333);
