INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-cho-bull-dieu-tra-ngoai-gio', 'Biệt Đội Chó Bull: Điều Tra Ngoài Giờ', 'Team Bulldog: Off-Duty Investigation', 'https://phimimg.com/upload/vod/20241218-1/fa83c757c3cdd3f5ab0d5f30edcc311a.jpg', 'https://phimimg.com/upload/vod/20241218-1/2fc26a9a499fc089495731b1125a10c4.jpg', '<p>Jin Kang Ho (Cha Tae Hyun đóng), một cảnh sát nhiệt huyết và tài năng, người sẵn sàng dùng mọi cách để bắt được tội phạm. Do tính cách kì quái, anh cũng không hòa đồng cùng các đồng nghiệp. Trong khi đó, Kang Moo Young là PD của một chương trình truyền hình chuyên nhắm đến điều tra những tội phạm mà cảnh sát chưa &quot;sờ gáy&quot; được. Cô sẵn sàng liều lĩnh để vạch trần sự thật đến công chúng. Kang Ho và Moo Young tình cờ gặp nhau và cùng hợp tác để giải quyết những vụ việc còn trong bóng tối.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cha Tae-hyun","avatar":""},{"name":"Lee Sun-bin","avatar":""},{"name":"Jung Sang-hoon","avatar":""},{"name":"Yoon Kyung-ho","avatar":""},{"name":"Ji Seung-hyun","avatar":""},{"name":"Im Cheol-hyung","avatar":""},{"name":"Jang Jin-hee","avatar":""},{"name":"Kim Kyung-sik","avatar":""},{"name":"Park Tae-san","avatar":""},{"name":"Song You-hyun","avatar":""},{"name":"Seo Hye-won","avatar":""},{"name":"Park Sung-jun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Beonoisusa","Further Investigation","번외수사"]', 1784690324333);
