INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-cau', 'Linh cẩu', 'Hyena', 'https://phimimg.com/upload/vod/20241207-1/bd0d1732d1918e8410f723ae6b0f54d7.jpg', 'https://phimimg.com/upload/vod/20241207-1/c64a8423a227e250984b18b71fe05ec0.jpg', '<p>Linh Cẩu là bộ phim khắc họa câu chuyện sinh tồn của những luật sư mặc dù am hiểu ‘luật pháp’ nhưng vẫn bị ‘đồng tiền’ chi phối. Để tồn tại trong xã hội ‘cá lớn nuốt cá bé’, họ phải cạnh tranh, cấu xé, sẵn sàng loại bỏ mọi trở ngại, không khác gì cách linh cẩu kiếm mồi.

Từ “linh cẩu” sẽ khiến bạn liên tưởng đến hình ảnh nào?

‘Linh cẩu’ là những bóng đen lông lá với bản tính tham lam, liều lĩnh, láu cá, sẵn sàng lăn xả để lấp đầy cái bụng của mình, thậm chí &nbsp;còn rất thích gây sự và ‘cuỗm’ mồi của các loài mãnh thú khác. Ở tác phẩm này, thuật ngữ “linh cẩu” chính là cách chơi chữ khéo léo, lột tả bản chất của những nhân vật chính trong phim. Họ đều là những luật sư trí thức, thuộc giới tinh hoa của xã hội, chuyên phục vụ tầng lớp thượng lưu siêu giàu, đầy quyền lực. Nhưng chính những luật sư này lại sử dụng luật pháp như một vũ khí để sinh tồn.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hye-soo","avatar":""},{"name":"Ju Ji-hoon","avatar":""},{"name":"Lee Kyung-young","avatar":""},{"name":"Kim Ho-jung","avatar":""},{"name":"Song Young-gyu","avatar":""},{"name":"Hwang Bo-ra","avatar":""},{"name":"Jun Suk-ho","avatar":""},{"name":"Hyun Bong-sik","avatar":""},{"name":"Park Se-jin","avatar":""},{"name":"Jeong Ji-hwan","avatar":""},{"name":"Oh Gyeong-hwa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Хиена","鬣狗式生存","富豪辩护人","کفتار","ハイエナ 弁護士たちの生存ゲーム","Гиена","HYENA：富豪辯護人","하이에나"]', 1784690324333);
