INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-than-2', 'Hà Thần 2', 'Tientsin Mystic 2', 'https://phimimg.com/upload/vod/20241206-1/d0e84bf2b3a5fae2b55557c6456bbf30.jpg', 'https://phimimg.com/upload/vod/20241206-1/2b03cb0ded9a93f357c6af59d3e25d92.jpg', '<p>Hải Hà dậy sóng, thiên đoàn Tân Môn một lần nữa xuất hiện, Cửu Ngưu, Nhị Hổ, Nhất Kê xuất hiện, thần sông trừ ma, diệt yêu quái dưới nước. Cách xa ba năm, tiểu đội năm nào giờ tiếp tục với tám vụ án kỳ lạ thời Dân Quốc! Hãy cứ chờ đón!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jin Shijia","avatar":""},{"name":"Zhang Ming''en","avatar":""},{"name":"Chen Yumi","avatar":""},{"name":"Wang Zixuan","avatar":""},{"name":"Chen Jian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["河神之魔古道","He Shen","河神2","Мистик из Теньцинь 2","Речной дух","Тяньцзиньская загадка","Тяньцзиньская мистика","河神","河神Ⅱ"]', 1784690324333);
