INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-tuoi-18', 'Ký Ức Tuổi 18', 'Live On', 'https://phimimg.com/upload/vod/20241206-1/d91e3109241f7714637688321c06c573.jpg', 'https://phimimg.com/upload/vod/20241206-1/96e55823c3d0e2b0f7913d29ed67ab44.jpg', '<p>Baek Ho Rang (Jung Da Bin thủ vai) với sự nổi tiếng ở trong thời kỳ đỉnh cao nên không xem ai ra gì và để tìm ra kẻ nặc danh đã vạch trần quá khứ của mình mà vào làm trong đài truyền hình của Go Eun Taek (Hwang Min Hyun đảm nhận). Live On lúc này mở ra một câu chuyện hài hước lãng mạn. Được biết Go Eun Taek vốn là người nhạy cảm, tinh tế và đôi lúc trở nên cáu kỉnh muốn mọi kế hoạch của mình phải thật hoàn hảo. Dù là một người khó tính và không mấy linh hoạt khi bàn chuyện lãnh đạo, nhưng Eun Taek chưa bao giờ né tránh công việc và được yêu thích bởi các bạn học của mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Minhyun","avatar":""},{"name":"Jung Da-bin","avatar":""},{"name":"Ro Jong-hyun","avatar":""},{"name":"Yang Hye-ji","avatar":""},{"name":"Yeon-woo","avatar":""},{"name":"Choi Byung-chan","avatar":""},{"name":"Woo Da-vi","avatar":""},{"name":"Hyun Woo-seok","avatar":""},{"name":"Wooyeon","avatar":""},{"name":"Lee Won-jeong","avatar":""},{"name":"Kang Hae-lim","avatar":""},{"name":"Chung Su-bin","avatar":""},{"name":"Yang Jung Yeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["恋はオンエアー中 Live On","恋はオン♡エアー中!〜Live on〜","恋はオン エアー中！～Live On～","รักวัยใส หัวใจออนแอร์","Live on 青春放送","Live On Korea","라이브온"]', 1784690324333);
