INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ky-uc-tuoi-18', 'Ký Ức Tuổi 18', 'Live On', 'ký ức tuổi 18 live on minhyun jung da-bin ro jong-hyun yang hye-ji yeon-woo choi byung-chan woo da-vi hyun woo-seok wooyeon lee won-jeong kang hae-lim chung su-bin yang jung yeon 恋はオンエアー中 live on 恋はオン♡エアー中!〜live on〜 恋はオン エアー中！～live on～ รักวัยใส หัวใจออนแอร์ live on 青春放送 live on korea 라이브온', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuc-cung-cua-tong-tai', 'Cục Cưng Của Tổng Tài', 'Favour', 'https://phimimg.com/upload/vod/20241206-1/6a6bbbde3a62d1a0d4fc3df063b158ef.jpg', 'https://phimimg.com/upload/vod/20241206-1/00f292ce75de7dbec3d41f099f1c620c.jpg', '<p>Chủ tịch lạnh lùng Quý Trần Phong bị “gái quê” Lâm Mạc Nhiễm vô tình đập mất trí, tình cờ trở thành vợ trên danh nghĩa của anh, ngờ đâu một trận hỏa hoạn bất ngờ, hai người mất đi liên lạc. Khi gặp lại, anh trở thành sếp lớn của cô, không chỉ nhiều lần cứu cô khỏi cơn nguy cấp, còn là người hướng dẫn trên con đường theo đuổi ước mơ thành minh tinh của cô. Hai người cũng bắt đầu từ quan hệ hợp đồng, dần dần có tình cảm với nhau, tình cảm dần nồng đậm, cuối cùng trở thành vợ chồng thật sự, yêu đương ngọt ngào, say đắm.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[]', '["Favour"]', 1784690324333);
