INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-trai-cua-mat-tich', 'Mặt Trái Của Mất Tích', 'Missing: The Other Side', 'https://phimimg.com/upload/vod/20241206-1/fa4cdfdd0491cb85ba5bab6f5af0b91c.jpg', 'https://phimimg.com/upload/vod/20241206-1/3ff071d59ef7e6e98f1692e17d099462.jpg', '<p>Phim xoay quanh hành trình tìm kiếm những thi thể mất tích và khám phá sự thật đằng sau tại một ngôi làng lưu giữ linh hồn của họ.

Kim Wook điển trai và kiếm sống bằng nghề lừa đảo, luôn biết cách thuyết phục đối tác của mình. Một ngày nọ, anh tình cờ đến ngôi làng Duon và phát hiện ra nhiều điều bí ẩn tại đây, nơi tập trung những người mất tích bị chết. Jang Pan Seok đang bí mật điều tra, anh chính là sợi dây kết nối giữa ngôi làng vào thế giới bên ngoài. Hai người gặp nhau và trở thành đối tác, họ cùng với nữ hacker Lee Jong Ah và thám tử trẻ tuổi Shin Joon Ho bắt tay giải quyết các vụ án.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Go Soo","avatar":""},{"name":"Heo Joon-ho","avatar":""},{"name":"An So-hee","avatar":""},{"name":"Lee Jung-eun","avatar":""},{"name":"Ha Jun","avatar":""},{"name":"Kim Dong-hwi","avatar":""},{"name":"Song Geon-hee","avatar":""},{"name":"Ji Dae-han","avatar":""},{"name":"Kwon Ah-reum","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Missing：他们存在过","Missing: Geudeuli Itseodda","미씽 그들이 있었다","Missing: The Other Side","Missing: หมู่บ้านแห่งวิญญาณ","Missing: They Were There","Mất tích: Thế giới bên kia","미씽: 그들이 있었다"]', 1784690324333);
