INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ky-su-tinh-yeu', 'Kỹ Sư Tình Yêu', 'En of Love', 'kỹ sư tình yêu en of love atthanin thaninphanuwiwat win achawin michaels folk thitiphat chankaew wanarat ratsameerat anan wong ratchapat worrasarn wongrapee krusong prat itthichaicharoen saran naksodsi thamrong cunpisut supitcha limsommut 学长的爱情攻心计 齿轮之爱 โปรเจกต์ซีรีส์วาย : กลรักรุ่นพี่ en of love: this is love story กวุ่นๆ ของหนุ่มวิศวะ - วิศวะมีเกียร์น่ะเมียหมอ โปรเจกต์ซีรีส์วาย: เหนือพระราม en of love: tossara en of love: love mechanics รักวุ่นๆของหนุ่มวิศวะ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim', 'Truy Tìm', 'Search', 'https://phimimg.com/upload/vod/20241206-1/da40da87f7d9b52294127ea7e14347f5.jpg', 'https://phimimg.com/upload/vod/20241206-1/96d2a13e5ec3537326e9754c981f8fac.jpg', '<p>Câu chuyện sinh tồn xoay quanh một biệt đội chuyên săn lùng và chiến đấu với quái vật. Krystal sẽ vào vai nữ chính Son Ye Rim - một nữ sĩ quan quân đội mẫn cán, quả cảm và đặc biệt &quot;trên thông thiên văn, dưới tường địa lý&quot; có kiến thức trong rất nhiều lĩnh vực. Trong khi đó, nam chính Yoon Dong Jin (Jang Dong Yoon) là một lính tại ngũ có chuyên môn huấn luyện chó cảnh sát chuyên nghiệp, dù chỉ còn một tháng nữa là đến ngày xuất ngũ nhưng bất ngờ gặp rắc rối khi một chó cảnh sát do anh phụ trách đã &quot;xổng trại&quot;. Anh chàng liền bị điều đến một đơn vị khác và sẽ phải hợp tác cùng nữ chính để truy lùng và đối phó với một con &quot;quái vật&quot;</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Yoon-je","avatar":""},{"name":"Jang Dong-yoon","avatar":""},{"name":"Krystal Jung","avatar":""},{"name":"Yoon Park","avatar":""},{"name":"Moon Jeong-hee","avatar":""},{"name":"Lee Hyun-wook","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"Yeon Woo-jin","avatar":""},{"name":"Lee Ha-yul","avatar":""},{"name":"Kim In-woo","avatar":""},{"name":"Lee Soon-won","avatar":""},{"name":"Park Da-yeon","avatar":""},{"name":"You Seong-joo","avatar":""},{"name":"Kim Ho-jung","avatar":""},{"name":"Yoon Young-min","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["搜索","搜索：非武装救援","서치","Sseochi","SEARCH","써치"]', 1784690324333);
