INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-tinh', 'Thức Tỉnh', 'Awaken', 'https://phimimg.com/upload/vod/20241206-1/e35e100ea019507ad393893885b624a6.jpg', 'https://phimimg.com/upload/vod/20241206-1/9112fbf30daf3335cc96b6656cda01aa.jpg', '<p>Bộ phim kể câu chuyện lãng mạn, bí ẩn về các nhân vật chính có được IQ cao nhờ thí nghiệm, nhưng đồng thời cũng mất đi tình cảm. Họ cùng nhau điều tra một vụ việc bí ẩn, cùng chống lại những âm mưu quyền thế, truy tìm chân tướng. Nam Goong Min vào vai một điều tra viên tài ba, phát hiện ra sự việc hiện tại có liên quan tới vụ án 26 năm trước. Đây là nhân vật then chốt để tìm kiếm ra manh mối sự việc. Kim Seol Hyun đóng vai nữ cảnh sát xinh đẹp có thiên phú, miệt mài truy tìm, là người gánh việc đánh nhau, uống rượu trong đội. Lee Chung Ah đóng vai điều tra viên của FBI. Yoon Sun Woo đóng vai kỹ sư thần bí chấp hành nhiệm vụ bí mật.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Namkoong Min","avatar":""},{"name":"Kim Seol-hyun","avatar":""},{"name":"Lee Chung-ah","avatar":""},{"name":"Yoon Sun-woo","avatar":""},{"name":"Kim Chang-wan","avatar":""},{"name":"Kim Won-hae","avatar":""},{"name":"Lee Sin-young","avatar":""},{"name":"Jung Dae-Ro","avatar":""},{"name":"An Si-ha","avatar":""},{"name":"Bae Hyun-kyung","avatar":""},{"name":"Baek Ji-won","avatar":""},{"name":"Yoon Kyung-ho","avatar":""},{"name":"Kim Ki-nam","avatar":""},{"name":"Choi Dae-chul","avatar":""},{"name":"Kang Rae-yeon","avatar":""},{"name":"Choi Jin-ho","avatar":""},{"name":"Kim Tae-woo","avatar":""},{"name":"Jeon Guk-hyang","avatar":""},{"name":"Jang","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["白天和黑夜","日与夜","Najgwa Bam","Awaken: ตื่น ตระหนัก ล่า","Day and Night","낮과 밤"]', 1784690324333);
