INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ve-hu-khong', 'Trở Về Hư Không', 'The Game: Towards Zero', 'https://phimimg.com/upload/vod/20241204-1/ae9b94772812deee050ed5a8bfb23b76.jpg', 'https://phimimg.com/upload/vod/20241204-1/56a69f9cc409d8be0c9b1a906d593005.jpg', '<p>Bộ phim này kể về câu chuyện của một nhà tiên tri và một thám tử hợp tác để giải quyết một vụ án giết người hàng loạt. Kim Tae Pyung ( TaecYeon ) là một nhà tiên tri có thể thấy trước cái chết của bất kỳ ai chỉ bằng cách nhìn vào mắt họ. Điều này thay đổi khi anh gặp Joon Young, cái chết mà anh không thể nhìn thấy. Joon Young ( Lee Yeon Hee ) là một thám tử làm việc tại Sở cảnh sát Yongsan. Cô hợp tác với một nhà tiên tri để giải quyết một vụ án giết người bí ẩn. Trong khi đó, Goo Do Kyung ( Im Ju Hwan ) là một chuyên gia pháp y. Ông là người cầu toàn, đào sâu mọi trường hợp.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ok Taec-yeon","avatar":""},{"name":"Lee Yeon-hee","avatar":""},{"name":"Lim Ju-hwan","avatar":""},{"name":"Jeong Dong-hwan","avatar":""},{"name":"Park Ji-il","avatar":""},{"name":"Park Won-sang","avatar":""},{"name":"Jang So-yeon","avatar":""},{"name":"Choi Jae-woong","avatar":""},{"name":"Kim Kang-hoon","avatar":""},{"name":"Lee Bom","avatar":""},{"name":"Hong In","avatar":""},{"name":"Yoon Ji-won","avatar":""},{"name":"Ryu Hye-rin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"