INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pho-ma-duong-than-yeu', 'Phố Ma Dương Thân Yêu', 'Dear Mayang Street', 'https://phimimg.com/upload/vod/20241204-1/92e0f56d0b60086d4f5392381c0719a8.jpg', 'https://phimimg.com/upload/vod/20241204-1/b4044049608327bac43e5674d718134a.jpg', '<p>Phố Ma Dương Thân Yêu - Dear Mayang Street (2020), bộ phim truyền hình dài tập thể loại thanh xuân, tình cảm xoay quanh những gia đình sống trên con phố Ma Dương có lịch sử lâu đời vào thời điểm những năm 80. Phim tái hiện bối cảnh Quảng Châu vào năm 1984, trên con phố Ma Dương Quảng Châu là cuộc sống của sau gia đình. Sáu gia đình này có lịch sử hơn 30 năm, bên trong chất chứa vận mệnh của những con người nhỏ bé và mộng tưởng của họ.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tan Songyun","avatar":""},{"name":"Timmy Xu","avatar":""},{"name":"Niu Junfeng","avatar":""},{"name":"Chen Jin","avatar":""},{"name":"Jiao Gang","avatar":""},{"name":"Shi Ke","avatar":""},{"name":"Kong Lin","avatar":""},{"name":"Ning Wentong","avatar":""},{"name":"Mu Liyan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["我的青春爱过你","我的青春遇见你2","Dear Mayang Street","親愛的麻洋街","亲爱的麻洋街"]', 1784690324333);
