INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-mai-doi-sunderland-phan-2', 'Mãi mãi đội Sunderland (Phần 2)', 'Sunderland ''Til I Die (Season 2)', 'https://phimimg.com/upload/vod/20241204-1/86a6d59d8dfa78ff7cde5fdfbc28b143.jpg', 'https://phimimg.com/upload/vod/20241204-1/3365f6a5b21921297163645d8896f7e7.jpg', '<p>Có chủ sở hữu mới, Sunderland bắt đầu tập trung vào mục tiêu thoát khỏi Giải Hạng ba và mang tự hào cùng hy vọng trở lại cho những người hâm mộ nhiệt thành của mình.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Sunderland Até Morrer","Σάντερλαντ μέχρι Θανάτου","Mãi mãi đội Sunderland","Sunderland ''Til I Die"]', 1784690324333);
