INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-su-thanh-xuan', 'Ký Sự Thanh Xuân', 'Record of Youth', 'https://phimimg.com/upload/vod/20241204-1/b50b8629e87c915c40a4799f8261d8cb.jpg', 'https://phimimg.com/upload/vod/20241204-1/ee45228bf56be1a163302d10604fd5d9.jpg', '<p>Youth Record xoay quanh cuộc sống của những người trẻ tuổi trong giới người mẫu. Sa Hye Joon thông minh và đẹp trai, anh ấy là một chàng trai tốt bụng và là một người mẫu nổi tiếng, nhưng điều anh ấy thực sự muốn là trở thành một diễn viên. Anh ấy đã thử sức với nhiều vai trò diễn xuất nhưng vẫn chưa thành công. Tiếc thay, Sa Hye Joon không xuất hiện nhiều với tư cách là một diễn viên, còn An Jung Ha lại làm nghề trang điểm.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Bo-gum","avatar":""},{"name":"Park So-dam","avatar":""},{"name":"Byeon Woo-seok","avatar":""},{"name":"Lee Chang-hoon","avatar":""},{"name":"Jo Yoon Jung","avatar":""},{"name":"Kwon Soo-hyun","avatar":""},{"name":"Ha Hee-ra","avatar":""},{"name":"Shin Ae-ra","avatar":""},{"name":"Han Jin-hee","avatar":""},{"name":"Park Soo-young","avatar":""},{"name":"Seo Sang-won","avatar":""},{"name":"Lee Jae-won","avatar":""},{"name":"Shin Dong-mi","avatar":""},{"name":"Park Se-hyun","avatar":""},{"name":"Im Gi-hong","avatar":""},{"name":"Jeong Min-sung","avatar":""},{"name":"Park Seong-yeon","avatar":""},{"name":"Jang Yi-jung","avatar":""},{"name":"Ya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Passarela de Sonhos","青春纪录","Recuerdos de juventud","Record of Youth","Youth Record","The Moment","청춘기록"]', 1784690324333);
