INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ma-am-o-trang-vien-bly', 'Chuyện Ma Ám Ở Trang Viên Bly', 'The Haunting of Bly Manor', 'https://phimimg.com/upload/vod/20241203-1/34fe3d9a12d801745225cf288ba738e2.jpg', 'https://phimimg.com/upload/vod/20241203-1/66f9f7efae0a363dff84fbd80c10cfab.jpg', '<p>Chết không có nghĩa là biến mất. Một cô gia sư bị cuốn vào những bí mật rùng rợn trong phim lãng mạn kiểu gothic này, từ tác giả của &quot;Chuyện ma ám ở căn nhà họ Hill&quot;.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Victoria Pedretti","avatar":""},{"name":"Oliver Jackson-Cohen","avatar":""},{"name":"Henry Thomas","avatar":""},{"name":"Amelia Eve","avatar":""},{"name":"T''Nia Miller","avatar":""},{"name":"Rahul Kohli","avatar":""},{"name":"Tahirah Sharif","avatar":""},{"name":"Amelie Bea Smith","avatar":""},{"name":"Benjamin Evan Ainsworth","avatar":""},{"name":"Carla Gugino","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Bly Manor : La dernière demeure","عمارت تسخیر شده بلای","ザ・ホーンティング・オブ・ブライマナー","Призраки поместья Блай","บลายเมเนอร์ บ้านกระตุกวิญญาณ","鬼莊園","Привиди садиби Блай","The Haunting of Bly Manor"]', 1784690324333);
