INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('buoc-chay-toi-trai-tim', 'Bước Chạy Tới Trái Tim', 'Run On', 'bước chạy tới trái tim run on yim si-wan shin se-kyung choi soo-young kang tae-oh lee bong-ryeon lee jung-ha park sung-jun park young-kyu cha hwa-yeon ryu abel lee hwang-eui choi jae-hyun yeon je-wook kim dong-young el amor es la meta na direção do amor run on συνέχισε να τρέχεις mindig csak előre 런온 продолжение วิ่งนำรัก 奔向愛情 런 온', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tham-dai-tai', 'Thần Thám Đại Tài', 'The Sleuth Of Ming Dynasty', 'https://phimimg.com/upload/vod/20241001-1/02d306a98ac576a2dee362ed9a0670e1.jpg', 'https://phimimg.com/upload/vod/20241001-1/af780050f0c41aa27c7155e4eb0c1f6b.jpg', '<p>Bộ phim kể về hành trình phá án của quan Lục phẩm Đường Phiếm và Cẩm y vệ tổng kỳ Tùy Châu. Trong một lần liên thủ, cả hai người phá kế hoạch của công tử Hầu gia thành công. Trong một vụ án khác, chủ nhà trọ là Trương thị vốn nổi tiếng hiền đức đột nhiên chết đi. Tuy bề ngoài nhìn như tự sát nhưng điểm đáng nghi lại tầng tầng lớp lớp. Sau quá trình điều tra căng não, Đường Phiếm cũng tìm ra được hung thủ thật sự là chồng của Trương thị. Vượt qua muôn vàn thử thách, dần đà cả hai nảy sinh tình cảm với nhau và cùng sát cánh bên nhau vượt qua nhiều gian khổ phía trước.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 18, 2020, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Thừa Tuấn","avatar":""},{"name":"Quan Hồng","avatar":""},{"name":"Phó Mạnh Bá","avatar":""},{"name":"Vương Mậu Lôi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Cheng Hua Shi Si Nian","The Sleuth of the Ming Dynasty","성화14년","The Story of Ming Dynasty","成化十四年"]', 1784690324333);
