INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-quoc-tich', 'Không Quốc Tịch', 'Stateless', 'https://phimimg.com/upload/vod/20241128-1/c4a45b5c4ec2f29a5468ecbb48be358d.jpg', 'https://phimimg.com/upload/vod/20241128-1/8adee02376cdd190301c36553d00146f.jpg', '<p>Bốn người lạ mặt - một tiếp viên hàng không thoát khỏi một giáo phái ngoại ô, một người tị nạn Afghanistan chạy trốn bắt bớ, một ông bố trẻ người Úc thoát khỏi một công việc bế tắc và một quan chức bị vướng vào một vụ bê bối quốc gia - bị mắc kẹt trong một nhà tù nhập cư ở sa mạc Úc. Được truyền cảm hứng bởi những sự kiện có thực.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 14, 2020, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Yvonne Strahovski","avatar":""},{"name":"Asher Keddie","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"Fayssal Bazzi","avatar":""},{"name":"Marta Dusseldorp","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Dominic West","avatar":""},{"name":"Darren Gilshenan","avatar":""},{"name":"Kate Box","avatar":""},{"name":"Rachel House","avatar":""},{"name":"Clarence John Ryan","avatar":""},{"name":"Claude Jabbour","avatar":""},{"name":"Dan Spielman","avatar":""},{"name":"Maria Angelico","avatar":""},{"name":"Chrissie Page","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ステートレス 彷徨の行方","無界之殤","Stateless"]', 1784690324334);
