INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-con-nguoi-cau-hoi-cua-cuoc-song-da-co-loi-dap', '100 Con Người: Câu Hỏi Của Cuộc Sống. Đã Có Lời Đáp.', '100 Humans: Life''s Questions. Answered.', 'https://phimimg.com/upload/vod/20241125-1/332b20a2d4031c1bd2b444f1cc62fc71.jpg', 'https://phimimg.com/upload/vod/20241125-1/6e274ba4a36c356126d03c24644d356d.jpg', '<p>Một trăm người can đảm có những hoàn cảnh khác nhau tham gia vào thử nghiệm thú vị nhằm khám phá về tuổi tác, giới tính, hạnh phúc và các khía cạnh khác của con người.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Haley Bockrath","avatar":""},{"name":"Tyanta Snow","avatar":""},{"name":"Komalpreet Batth","avatar":""},{"name":"Braxton Hale","avatar":""},{"name":"Alfredo Tavares","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["100 Humans. Risposte alle domande della vita (2020)","100 Humans","100 Humans: Life''s Questions. Answered."]', 1784690324334);
