INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-bong-chuyen-haikyuu-phan-4-2', 'Vua Bóng Chuyền Haikyuu (Phần 4) 2', 'Haikyu!! (Season 4) 2', 'https://phimimg.com/upload/vod/20241125-1/3f350921aada848aa1d294158e00fa39.jpg', 'https://phimimg.com/upload/vod/20241125-1/97930606b4b1e0967dad8939b8ff087e.jpg', '<p>Vua Bóng Chuyền Haikyu Phần 4 (2) - Haikyu!! 4th Season (Part 2). Trường trung học Karasuno đã giành chiến thắng trong nhiều trận chiến khốc liệt khác nhau như: trong trại huấn luyện chung, vòng loại Harutaka, bán kết đội tuyển quốc gia tỉnh Miyagi. Và còn một chiến thắng nữa, đó là trận đấu toàn quốc. Thử thách lớn nhất của Trường trung học Karasuno đấu với Trường trung học Shiratorizawa bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Kaito Ishikawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Haikyuu!!","High Kyuu!!","ハイキュー!! セカンドシーズン","Haikyuu!! Karasuno Koukou VS Shiratorizawa Gakuen Koukou","ハイキュー!! 烏野高校 VS 白鳥沢学園高校","ハイキュー!! バケモノたちの行くところ","Haikyuu!! Riku vs. Kuu","하이큐!! 땅 VS 하늘","Волейбол!!","Haikyuu!! II","Haikyuu!! TO THE TOP","HAIKYU!! LAND VS. AIR","Haikyu!! Karasuno High School vs Shiratorizawa Academy","Vua Bóng Chuyền","ハイキュー!!"]', 1784690324334);
