INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vua-bong-chuyen-haikyuu-phan-4-2', 'Vua Bóng Chuyền Haikyuu (Phần 4) 2', 'Haikyu!! (Season 4) 2', 'vua bóng chuyền haikyuu (phần 4) 2 haikyu!! (season 4) 2 ayumu murase kaito ishikawa haikyuu!! high kyuu!! ハイキュー!! セカンドシーズン haikyuu!! karasuno koukou vs shiratorizawa gakuen koukou ハイキュー!! 烏野高校 vs 白鳥沢学園高校 ハイキュー!! バケモノたちの行くところ haikyuu!! riku vs. kuu 하이큐!! 땅 vs 하늘 волейбол!! haikyuu!! ii haikyuu!! to the top haikyu!! land vs. air haikyu!! karasuno high school vs shiratorizawa academy vua bóng chuyền ハイキュー!!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-bong-chuyen-haikyuu-phan-4', 'Vua Bóng Chuyền Haikyuu (Phần 4)', 'Haikyu!! (Season 4)', 'https://phimimg.com/upload/vod/20241125-1/4d7fb810fd55cc1740699a43115968c7.jpg', 'https://phimimg.com/upload/vod/20241125-1/eaf6e3eaaea3581789c42dc65ea837dd.jpg', '<p>Vua Bóng Chuyền Haikyu Phần 4 (1) - Haikyu!! 4th Season (Part 1). Thông báo về việc triệu tập trại huấn luyện thanh niên toàn Nhật Bản của Kageyama đến với câu lạc bộ bóng chuyền trường trung học Karasuno trước giải đấu quốc gia bất ngờ ập tới. Tsukishima cũng được triệu tập tới trại huấn luyện dành cho sinh viên năm nhất ở tỉnh Miyagi. Hinata, người nôn nóng với sự khác biệt khoảng cách với những người cũng là học sinh lớp một, cũng xông tới trại huấn luyện tuyển chọn học sinh lớp một của tỉnh Miyagi ...!? Trận đấu hướng tới giải đấu quốc gia của câu lạc bộ bóng chuyền trường trung học Hinata, Kageyama và Karasuno bắt đầu !!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Kaito Ishikawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Haikyuu!!","High Kyuu!!","ハイキュー!! セカンドシーズン","Haikyuu!! Karasuno Koukou VS Shiratorizawa Gakuen Koukou","ハイキュー!! 烏野高校 VS 白鳥沢学園高校","ハイキュー!! バケモノたちの行くところ","Haikyuu!! Riku vs. Kuu","하이큐!! 땅 VS 하늘","Волейбол!!","Haikyuu!! II","Haikyuu!! TO THE TOP","HAIKYU!! LAND VS. AIR","Haikyu!! Karasuno High School vs Shiratorizawa Academy","Vua Bóng Chuyền","ハイキュー!!"]', 1784690324334);
