INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vua-bong-chuyen-haikyuu-phan-4', 'Vua Bóng Chuyền Haikyuu (Phần 4)', 'Haikyu!! (Season 4)', 'vua bóng chuyền haikyuu (phần 4) haikyu!! (season 4) ayumu murase kaito ishikawa haikyuu!! high kyuu!! ハイキュー!! セカンドシーズン haikyuu!! karasuno koukou vs shiratorizawa gakuen koukou ハイキュー!! 烏野高校 vs 白鳥沢学園高校 ハイキュー!! バケモノたちの行くところ haikyuu!! riku vs. kuu 하이큐!! 땅 vs 하늘 волейбол!! haikyuu!! ii haikyuu!! to the top haikyu!! land vs. air haikyu!! karasuno high school vs shiratorizawa academy vua bóng chuyền ハイキュー!!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-cua-cac-con-thu', 'Cuộc Phiêu Lưu Của Các Con Thú', 'Digimon Adventure', 'https://phimimg.com/upload/vod/20241125-1/cbb5dc7df69651b4459fca1a67e86ebb.jpg', 'https://phimimg.com/upload/vod/20241125-1/a3a431200347d2fbc56d44c2cfa41d2a.jpg', '<p>Năm 2020, mạng lưới ngày càng quan trọng trong cuộc sống con người. Nhưng loài người không biết phía khác của mạng lưới lại có một thế giới vô hạn – Thế giới Kỹ thuật số, và cả những Digimon đang sống bên trong… Nhân vật chính của câu chuyện là một học sinh lớp Năm Yagami Taichi sống ở ngoại ô Tokyo, mẹ và em gái cậu ngồi vào chiếc tàu điện không dừng lại được. Để cứu họ, Taichi vô ý đã vào Thế giới Kỹ thuật số! Những đứa trẻ gặp gỡ các Digimon cộng sự, cùng đối mặt với “cuộc phiêu lưu” không biết trước!</p>', 'Hoàn Tất (67/67)', 67, 'hoathinh', 'completed', 13, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuko Sanpei","avatar":""},{"name":"Chika Sakamoto","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Ryoko Shiraishi","avatar":""},{"name":"Yumiko Kobayashi","avatar":""},{"name":"Marika Kouno","avatar":""},{"name":"Takeshi Kusao","avatar":""},{"name":"Misaki Watada","avatar":""},{"name":"Mayumi Yamaguchi","avatar":""},{"name":"Atori Shigematsu","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Kinoko Yamada","avatar":""},{"name":"Junko Takeuchi","avatar":""},{"name":"Mie Sonozaki","avatar":""},{"name":"Masako Nozawa","avatar":""},{"name":"Miwa Matsumoto","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu