INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-phieu-luu-cua-cac-con-thu', 'Cuộc Phiêu Lưu Của Các Con Thú', 'Digimon Adventure', 'cuộc phiêu lưu của các con thú digimon adventure yuko sanpei chika sakamoto daisuke namikawa ryoko shiraishi yumiko kobayashi marika kouno takeshi kusao misaki watada mayumi yamaguchi atori shigematsu takahiro sakurai kinoko yamada junko takeuchi mie sonozaki masako nozawa miwa matsumoto дигимон: приключения дигимон приключения: 2020 приключението на дигимон приключението на дигимон: 2020 数码暴龙：重启之战 数码宝贝大冒险：重启 數碼暴龍：重啟之戰 digimon adventure: psi デジモンアドベンチャー：ψ 디지몬 어드벤처: 리부트 디지몬 어드벤처: 디지몬 어드벤처： ดิจิมอนแอดเวนเจอร์ (2020) digimon: psi digimon adventure 2020 デジモンアドベンチャー：', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-tre-do-that-tuyet-phan-2', 'Đứa trẻ đó thật tuyệt (Phần 2)', 'Cool Boy from LanXiang (Season 2)', 'https://phimimg.com/upload/vod/20241125-1/90214b76d2cb7e01d9e5b1e416b15aea.jpg', 'https://phimimg.com/upload/vod/20241125-1/2a1c544551559049362987d01737a44d.jpg', '<p>Trang Ni từ ngoài vũ trụ tới Trái đất để học các kỹ năng của con người tại Học viện chức nghiệp năng lượng cao. Hắn đã hoàn thành xuất sắc ba chuyên ngành, kết bạn với một số người Trái đất. Sau đó hắn sẽ tiếp tục học ba chuyên ngành khác: sửa chữa ô tô, trình diễn thời trang, tiếp viên hàng không. Trong quá trình học tập ba chuyên ngành này, hắn đã có nhiều xích mích với bạn học cùng lớp, cuối cùng biến đấu đá thành hòa bình, hơn nữa cùng nhau đánh bại các nhân vật xã hội bên ngoài trường, cuối cùng mọi người trở thành bạn bè. Trang Ni thuận lợi tốt nghiệp trường học, hơn nữa còn học được phẩm chất quan trọng nhất của nhân loại - đó là tình yêu, hắn mỉm cười rời khỏi Trái đất.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 18, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["Na Xiao Zi Zhen Ku","那小子真酷"]', 1784690324334);
