INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-tre-do-that-tuyet-phan-1', 'Đứa trẻ đó thật tuyệt (Phần 1)', 'Cool Boy from LanXiang (Season 1)', 'https://phimimg.com/upload/vod/20241125-1/29449cbb7fe5ac133354440d5c59c5df.jpg', 'https://phimimg.com/upload/vod/20241125-1/52167c41a0025cd938f857a73be39208.jpg', '<p>Người ngoài hành tinh Trang Ni đến trái đất để học các kỹ năng chuyên nghiệp và khả năng yêu thương. Có một trường cao đẳng dạy nghề năng lượng cao trong một cộng đồng người Hoa ở Đông Nam Á. Kỹ năng, phổ biến văn hóa truyền thống Trung Quốc. Trang Ni đã gặp các bạn học từ các chuyên ngành khác nhau ở trường, từ xích mích ban đầu cho đến sự giúp đỡ lẫn nhau cuối cùng, Trang Ni đã vượt qua rất nhiều khó khăn và cuối cùng đã hoàn thành tất cả các nghiên cứu chuyên ngành và tốt nghiệp một cách thuận lợi.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 15, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["Na Xiao Zi Zhen Ku","那小子真酷"]', 1784690324334);
