INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-yeu-ky', 'Song Yểu Ký', 'The Silent Criminal', 'https://phimimg.com/upload/vod/20241125-1/3a89d3beb8d2d808612b4f69e3391882.jpg', 'https://phimimg.com/upload/vod/20241125-1/9b970577bb4cee0d207c0a805668a0eb.jpg', '<p>Trong suốt 19 năm qua, Phùng Bảo nhiều lần cử vạn phu trưởng đến kinh thành để nghe ngóng về tung tích của “Đại Âm Bồ Nhã”. Họ bắt đầu đột nhập vào phủ Thụy Vương, xông thẳng đến chỗ Đại Âm Bồ Nhã những hóa ra bên trong lại không có gì. Thực chất tiên đế đã ban Đại Âm Bồ Nhã cho Bội Chương tướng quân từ lâu nhưng lại bị kẻ gian trộm đi mất. &nbsp;Không nản chí, Cẩm y vệ Long Yểu và Lý Dục quyết tâm đến phủ Thụy Vương cứu viện. Hai người đã giết chết nhóm người vạn phu trưởng, sau đó Long Yểu bị Lý Dục lừa đi chỗ khác, thừa cơ hội đến nhà Bội Chương tướng quân, lấy cớ Đại Âm Bồ Nhã bị mất để uy hiếp tướng quân.

Tuy nhiên, vì tính nóng nảy của mình mà con trai của Bội Chương tướng quân đã giết chết Lý Dục rồi ngụy tạo chứng cứ là hắn vô tình bị trúng tên ở bãi săn mà chết. Bổ Khoái Thi Kính Dao tiến hành điều tra vụ án Lý Dục theo sự giao phó của Lưu chi phủ.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Jiaming","avatar":""},{"name":"Wen Sheng","avatar":""},{"name":"Lan Xin","avatar":""},{"name":"Yu Nai Jia","avatar":""},{"name":"Fu Shuyang","avatar":""},{"name":"Wu Xinzun","avatar":""},{"name":"Wang Zi Xin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["双夭记"]', 1784690324334);
