INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('song-yeu-ky', 'Song Yểu Ký', 'The Silent Criminal', 'song yểu ký the silent criminal li jiaming wen sheng lan xin yu nai jia fu shuyang wu xinzun wang zi xin 双夭记', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dep-can-ve', 'Người Đẹp Cận Vệ', 'The Emperor''s Secret Army', 'https://phimimg.com/upload/vod/20241125-1/a1bf7e47f27a0965c6b1759de58d18f2.jpg', 'https://phimimg.com/upload/vod/20241125-1/42fab4e25e6007e40479288c2e5bea43.jpg', '<p>Nghe đồn trên giang hồ có mười hai đạo binh phù thất lạc, có được những binh phù này là có thể bá chiếm thiên hạ. Cẩm Y Vệ Thiên Hộ Viên Bân phụng mệnh điều tra tung tích binh phù, lại bị chỉ huy sứ Quý Môn Đạt lợi dụng và giá họa. Thời khắc mấu chốt, bạn chơi thời thơ ấu của Viên Bân - Kim Đao Môn Môn Chủ xuất hiện, cứu Viên Bân. Hai người suy đoán Quý Môn Đạt mưu toan thu thập binh phù nguy hại quốc gia. Vì bảo vệ quốc gia, lấy lại trong sạch cho mình, Viên Bân và Chu Bân bước lên con đường dài tìm đủ mười hai đạo binh phù.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Jin Dao Mi Wei Hua Mei Ren","金刀秘卫之婳美人"]', 1784690324334);
