INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gibiate', 'GIBIATE', 'GIBIATE', 'https://phimimg.com/upload/vod/20241125-1/ee6d4ac080631142ba3e8c57f078d6fa.jpg', 'https://phimimg.com/upload/vod/20241125-1/7023eaf40041a0436f5e00d7b7375d2a.jpg', '<p>Nhật bản năm 2030 xuất hiện một căn bệnh có tên Gibia có thể biến con người thành quái vật, một vị samurai và ninja từ thời cổ đại xuyên không đến tương lai đã cùng nhau chống lại căn bệnh với sự trợ giúp của các bác sĩ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tetsuya Kakihara","avatar":""},{"name":"Yukiyo Fujii","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Michio Hazama","avatar":""},{"name":"Shuichi Ikeda","avatar":""},{"name":"Hiroki Nanami","avatar":""},{"name":"Hiromi Sakimoto","avatar":""},{"name":"Emi Itou","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Koji Ishii","avatar":""},{"name":"Hozumi Goda","avatar":""},{"name":"Fukushi Ochiai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["GIBIATE","ジビエート"]', 1784690324334);
