INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uoc-hen-bay-cao', 'Ước Hẹn Bay Cao', 'Swing to the Sky', 'https://phimimg.com/upload/vod/20241125-1/fa749077c29551a1081ec7cf7359fbb6.jpg', 'https://phimimg.com/upload/vod/20241125-1/93e902dc60dd29b640ac8988b0c0b9cb.jpg', '<p>Tiểu Ngư - một cô gái ngây thơ trong sáng vô tình kết giao với chàng công tử nhà giàu Lăng Không. Sau đó, Tiểu Ngư đã trở thành thành viên của gia tộc họ Lăng giàu có dưới danh nghĩa “mẹ kế”. Nhờ khả năng bay cao khác thường, cô đã trở thành thành viên của đội nhảy cầu của Học viện Anh Lan, và bắt đầu chinh phục cuộc thi “Ước hẹn bay cao” - giải đấu có tính thách thức nhất toàn thế giới cùng với hai anh em nhà họ Lăng là: Lăng Không và Lăng Thần, và Huấn luyện viên huyền thoại Trần Thiên; nữ thần nhảy cầu Trĩ Nhã. Trong quá trình huấn luyện, Tiểu Ngư và Lăng Không từ những người không biết gì về nhảy cầu, đã trở thành những chiến binh thực lực tại “Ước hẹn bay cao”, dẫn dắt đội nhảy cầu Anh Lan vượt qua mọi thử thách; nhiệt huyết, thanh xuân, sự trưởng thành và những màn đối kháng ngoạn mục cũng được dịp bùng nổ.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Youlun Ren","avatar":""},{"name":"Tang Guo-Zhong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Swin to Sky","腾空之约"]', 1784690324334);
