INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-tan-de-quoc', 'Đại Tần Đế Quốc', 'Qin Dynasty Epic', 'https://phimimg.com/upload/vod/20240609-1/d0de7031dfc1640f9b246bee4402e8a3.jpg', 'https://phimimg.com/upload/vod/20240609-1/f76c7bd275cda83c47d226846c6ac2e1.jpg', '<p>Cuối thời kỳ Chiến quốc, lãnh địa Hoa Hạ vốn đã hỗn loạn năm trăm năm vẫn chiến tranh liên miên, dân chúng lầm than. Khi đó, sáu nước suy yếu, chỉ có nước Tần hùng mạnh, thế cục thống nhất thiên hạ đã dần lộ rõ. Thương nhân Lã Bất Vi đưa Doanh Dị Nhân, đang làm con tin ở nước Triệu trốn về nước Tần, còn Tần Thủy Hoàng Doanh Chính lúc nhỏ bị bỏ lại Hàm Đan, nhiều lần trải qua tai họa sinh tử nên đã tận mắt chứng kiến nỗi khổ và sự tuyệt vọng mà chiến tranh đã gây ra cho dân chúng, trong lòng đã nảy ra hoài bão thống nhất thiên hạ từ đây. Sau này, Doanh Chính trở lại nước Tần, trải qua vòng xoáy chính trị ở Hàm Dương đã trở thành một vị vua thực sự. Để nắm bắt thời cơ và sức mạnh thống nhất thiên hạ, thực hiện tham vọng thống nhất thiên hạ, Doanh Chính đã mưu tính kỹ lưỡng, hành động bí mật, cuối cùng bình định được loạn Lao Ái, tự mình chấp chính, bãi chức Thừa tướng, giành lại binh quyền...</p>', 'Hoàn Tất (78/78)', 78, 'series', 'completed', 9, 2020, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Luyi","avatar":""},{"name":"Duan Yihong","avatar":""},{"name":"李乃文","avatar":""},{"name":"Zhu Zhu","avatar":""},{"name":"Xin Baiqing","avatar":""},{"name":"邬君梅","avatar":""},{"name":"You Yongzhi","avatar":""},{"name":"Li Hongtao","avatar":""},{"name":"Wang Qingxiang","avatar":""},{"name":"Ye Xiangming","avatar":""},{"name":"Liu Guanlin","avatar":""},{"name":"Jiang Yi","avatar":""},{"name":"Huang Xiaoge","avatar":""},{"name":"Zhao Xin","avatar":""},{"name":"Ren Yu","avatar":""},{"name":"Chen Yating","avatar":""},{"name":"Su Maoyang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324334);
