INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-ra-anh-ay-khong-yeu-ban-den-the', 'Thật Ra Anh Ấy Không Yêu Bạn Đến Thế', 'Love Yourself', 'https://phimimg.com/upload/vod/20241125-1/ed0247807d9613323065308b8cb44d2c.jpg', 'https://phimimg.com/upload/vod/20241125-1/34810a3562555fb1835cca9a28fcfaf9.jpg', '<p>Nội dung tác phẩm xoay quanh câu chuyện tình yêu, tình bạn và khao khát trong cuộc sống của bốn người phụ nữ đã ngoài 30 tuổi.

Nhà sản xuất Tôn Nghệ Hà, chủ phòng tập thể hình Karen, người đại diện thực tập sinh Đinh Đinh và phó tổng giám đốc công ty DMA Nhậm Nhiễm đều là những người tài năng, xinh đẹp và có tính cách khác nhau, nhưng họ vẫn trên con đường tìm kiếm hạnh phúc thực sự của mình. Không như lúc còn trẻ, hiện tại tất cả đều có sự nghiệp và tiền bạc, thứ họ còn thiếu là sự đồng điệu về tâm hồn. Mỗi người đều được trải qua thử thách về tình yêu và tình bạn, liệu họ có thể vượt qua tất cả để có được hạnh phúc trọn vẹn.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Victoria Song","avatar":""},{"name":"Karlina Zhang","avatar":""},{"name":"Li Chun","avatar":""},{"name":"Celina Jade","avatar":""},{"name":"Ryan Zheng Kai","avatar":""},{"name":"Tony Yang","avatar":""},{"name":"Huang Zheng","avatar":""},{"name":"David Wang","avatar":""},{"name":"Wang Yuexin","avatar":""},{"name":"Shi An","avatar":""},{"name":"Zhang Haowei","avatar":""},{"name":"Arash Estilaf","avatar":""},{"name":"Yu Yang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ta Qi Shi Mei You Na Me Ai Ni","Love By Yourself","Love In Shanghai","He Doesn’t Love You That Much","他其实没有那么爱你"]', 1784690324334);
