INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('that-ra-anh-ay-khong-yeu-ban-den-the', 'Thật Ra Anh Ấy Không Yêu Bạn Đến Thế', 'Love Yourself', 'thật ra anh ấy không yêu bạn đến thế love yourself victoria song karlina zhang li chun celina jade ryan zheng kai tony yang huang zheng david wang wang yuexin shi an zhang haowei arash estilaf yu yang ta qi shi mei you na me ai ni love by yourself love in shanghai he doesn’t love you that much 他其实没有那么爱你', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-nhau', 'Cùng Nhau', 'With You', 'https://phimimg.com/upload/vod/20241125-1/ed5e1e65ecda72474a0bd7a2569c8401.jpg', 'https://phimimg.com/upload/vod/20241125-1/07dc25fe3708e91547a0f22bdceac855.jpg', '<p>Dựa trên những câu chuyện có thật ở mọi ngành nghề trong thời gian chống dịch, thêm vào yếu tố nghệ thuật, để tạo nên hình ảnh quần chúng anh hùng có khóc có cười trên mặt trận tuyến đầu chống dịch. Bóc tách từng biểu hiện, thái độ chống dịch của mỗi người dân trong bức tranh toàn cảnh của cuộc chiến cam go, thể hiện tinh thần đoàn kết một lòng, cùng chung hoạn nạn của nhân dân Trung Quốc.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Zai Yi Qi","Zai Yi Qi Tong Xing","เพราะเรามีกัน","Walk Together","Together","在一起"]', 1784690324334);
