INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiep-nan-kho-tranh', 'Kiếp Nạn Khó Tránh', 'Sisyphus', 'https://phimimg.com/upload/vod/20241125-1/f857c687d71d131e62f952e538551a5e.jpg', 'https://phimimg.com/upload/vod/20241125-1/00ed2334eb1818d0642ca6a40e5f0121.jpg', '<p>Hai diễn viên Lộc Hàm, Vương Thiên Nguyên đảm nhận vai chính trong bộ phim. Lộc Hàm đã dũng cảm thử thách vai phản diện trong bộ phim cùng với sự tham gia của hoàng loạt diễn viên kỳ cựu. Hãy cùng chờ đón siêu phẩm khoa học viễn tưởng sắp được ra mắt~</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Macao', 0, '[{"name":"Wang Qian-yuan","avatar":""},{"name":"Lu Han","avatar":""},{"name":"Qi Xi","avatar":""},{"name":"Qiao Xin","avatar":""},{"name":"Wu Yue","avatar":""},{"name":"Zhang Haoran","avatar":""},{"name":"Lee Kang-sheng","avatar":""},{"name":"Wang Longzheng","avatar":""},{"name":"Liu Jie","avatar":""},{"name":"Yu Mingjia","avatar":""},{"name":"Ma Chenyan","avatar":""},{"name":"Huo Qing","avatar":""},{"name":"Wang Zheng","avatar":""},{"name":"Zhu Xuan","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["在劫难逃"]', 1784690324334);
