INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-dang-yeu-nhu-the', 'Chúng Ta Đáng Yêu Như Thế', 'Lovely Us', 'https://phimimg.com/upload/vod/20241125-1/bb2ead06db22e37da4aa493b8af527d7.jpg', 'https://phimimg.com/upload/vod/20241125-1/2c9214f8a9e350ad580eb29ec494f952.jpg', '<p>Chúng Ta Đáng Yêu Như Thế kể về mùa hè năm 2007, Thế vận hội Olympic chính thức bước vào giai đoạn đếm ngược một năm, cuối cùng khu nhà công nhân viên chức Thụ Đức cũng chào đón một đợt di dời toàn bộ, sau khi chào tạm biệt tòa nhà ngang với bản sonata của hồi ức và âm thanh nồi niêu gáo chậu, rồi ôm ấp kỳ vọng vào căn hộ riêng lẻ lạ lẫm, mới tinh. Mà tất cả những điều nhỏ nhặt có liên quan đến việc trưởng thành, ước mơ cùng với tính cảm mập mờ xảy đến với Hoàng Tranh Tử, Đàm Tống, Chúc Kim Tiêu, Hạ Kim Triêu cũng trở thành dấu ấn ấm áp nhất của khu nhà Thụ Đức</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 13, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Mingde","avatar":""},{"name":"Tian Xiwei","avatar":""},{"name":"Li Mingyuan","avatar":""},{"name":"Yingying Li","avatar":""},{"name":"You Haoran","avatar":""},{"name":"Ma Shuliang","avatar":""},{"name":"Zhang Lei","avatar":""},{"name":"Zhao Yansong","avatar":""},{"name":"Zhao Qian","avatar":""},{"name":"Li Jiawei","avatar":""},{"name":"YaShu Zhan","avatar":""},{"name":"Wang Zhengquan","avatar":""},{"name":"Xie Xingyang","avatar":""},{"name":"Liu Yuhang","avatar":""},{"name":"Xingyao Li","avatar":""},{"name":"Jiang Zhinan","avatar":""},{"name":"Liang Guorong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Ru ci ke ai de wo men","如此可爱的我们"]', 1784690324334);
