INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-phieu-luu-cua-archibald-phan-2', 'Nhật Ký Phiêu Lưu Của Archibald (Phần 2)', 'Archibald''s Next Big Thing (Season 2)', 'https://phimimg.com/upload/vod/20241125-1/8a73eb4654df7c49f1c666b4a9ece6f7.jpg', 'https://phimimg.com/upload/vod/20241125-1/f5be00b003972f963478b06602b7e393.jpg', '<p>Dù là khi mắc kẹt trong trung tâm mua sắm, giải cứu chiếc ghế bập bênh hay lên kế hoạch cho tuần trăng mật, Archibald lúc nào cũng hết mình – và không bao giờ biết chán.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tony Hale","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"Jordan Fisher","avatar":""},{"name":"Chelsea Kane","avatar":""},{"name":"Adam Pally","avatar":""},{"name":"Kari Wahlgren","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["La próxima gran aventura de Archibald","As Aventuras de Arquibaldo","Archibald''s Next Big Thing"]', 1784690324334);
