INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-thi-tham-hiem-ac', 'Lời thì thầm hiểm ác', 'Whispers', 'https://phimimg.com/upload/vod/20241125-1/a26cdef72c07588f67f3bd5b225aa0d9.jpg', 'https://phimimg.com/upload/vod/20241125-1/84f115ae71e8457bff2f317031478b55.jpg', '<p>Khi những nghi ngờ xung quanh cái chết của người đứng đầu gia đình ngày một tăng, gia đình giàu có nọ bắt đầu lật mở sự thật khi các bí mật đen tối được đưa ra ánh sáng.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 28, 2020, 'Vietsub', 'FHD', 'Ả Rập Xê Út', 0, '[{"name":"Mysoon Alruwaily","avatar":""},{"name":"Norah Al Anbar","avatar":""},{"name":"Shaimaa Al Fadl","avatar":""},{"name":"Ali ElSherif","avatar":""},{"name":"Laila Araby","avatar":""},{"name":"Nada Tawhid","avatar":""},{"name":"Elham Ali","avatar":""},{"name":"Mohammed Ali","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["流言私语","وساوس","Whispers"]', 1784690324334);
