INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-giai-phong', 'Người Giải Phóng', 'The Liberator', 'https://phimimg.com/upload/vod/20241125-1/34405aea5aff7b6c18c85e227493e227.jpg', 'https://phimimg.com/upload/vod/20241125-1/9d103dd7a7232ec5eb2c35145ff7ee97.jpg', '<p>Vào ngày 10 tháng 7 năm 1943, một đơn vị lính đến từ Oklahoma bao gồm người Mỹ bản địa, người Mỹ gốc Mexico và cao bồi Dust Bowl. Đây là những nhóm người không thể ngồi xuống cùng nhau trong một quán Bar ở quê nhà Hoa Kỳ nhưng lại phải thực hiện một chiến dịch kéo dài 500 ngày.

Xuất phảm điểm của họ bắt đầu ở Sicily và xuyên qua các vùng đất Châu Âu đã bị Đức Quốc Xã chiếm đóng chứa đầy nguy hiểm. Bộ phim được thực hiện với phong cách hoạt hình đặc biệt với sự kết hợp giữa các cảnh quay thật và tinh chỉnh lại bằng CGI. Nhờ đó, The Liberator không mượt mà như các phim chiến tranh khác nhưng lại có những khung hình gây tương phản mạnh về thị giác mô tả được sự khốc liệt của chiến dịch.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bradley James","avatar":""},{"name":"Martin Sensmeier","avatar":""},{"name":"Jose Miguel Vasquez","avatar":""},{"name":"Mike Rowe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Liberator"]', 1784690324334);
