INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('julie-va-nhung-hon-ma', 'Julie và Những Hồn Ma', 'Julie and the Phantoms', 'https://phimimg.com/upload/vod/20241123-1/cfab5aef74b54521f85523265fc6ad91.jpg', 'https://phimimg.com/upload/vod/20241123-1/f85ac543d6d483a4601e4fd0839d6b99.jpg', '<p>Julie là một cô gái tuổi teen tìm thấy niềm đam mê với âm nhạc và cuộc sống với sự giúp đỡ của một ban nhạc tuổi teen có ý thức cao (The Phantoms), những người đã chết được 25 năm. Đến lượt mình, Julie đã giúp họ trở thành ban nhạc mà họ không bao giờ có thể trở thành. Một năm sau khi mẹ cô qua đời, Julie chơi một trong những đĩa CD cũ của cô. Đột nhiên, ba bóng ma xuất hiện - những người từ ban nhạc Sunset Curve của thập niên 90.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Madison Reyes","avatar":""},{"name":"Charlie Gillespie","avatar":""},{"name":"Owen Patrick Joyner","avatar":""},{"name":"Jeremy Shada","avatar":""},{"name":"Jadah Marie","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["ジュリー＆ザ・ファントムズ","จูลี่และหนุ่มๆแฟนทอมส์","Julie and the Phantoms"]', 1784690324334);
