INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-chuc-rugal', 'Tổ Chức Rugal', 'Rugal', 'https://phimimg.com/upload/vod/20241123-1/9c9428222852f13073325662a0a7dda4.jpg', 'https://phimimg.com/upload/vod/20241123-1/3cf3b9352e09633f077f91cfef7a6359.jpg', '<p>Mất tất cả bởi một tổ chức tội phạm, vị thanh tra cảnh sát quyết tâm trả thù khi anh có được khả năng đặc biệt thông qua công nghệ sinh học. &nbsp;Kang Ki Bum là một thám tử năng nổ. Anh đang tập trung điều tra tổ chức tội phạm Argos, nhưng khi quay về nhà, Ki Bum đã gặp vài kẻ đeo mặt nạ. Vợ và con Ki Bum bị giết bởi đám người đeo mặt nạ được Argos cử đến. Chúng đánh bại và khoét hai mắt của Ki Bum. Khi Kang Ki-Bum tỉnh lại trong bệnh viện và bị buộc tội giết người, NIS đã tiếp cận. Kang Ki Bum được lựa chọn để trở thành thành viên của Rugal, một nhóm đặc biệt được điều hành bởi NIS. Thông qua công nghệ, Ki Bum được lắp hai mắt nhân tạo với khả năng đặc biệt. Kang Ki Bum and the Rugal có nhiệm vụ triệt hạ tổ chức tội phạm này.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Jin-hyuk","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Cho Dong-hyuk","avatar":""},{"name":"Jung Hye-in","avatar":""},{"name":"Kim Min-sang","avatar":""},{"name":"Park Sun-ho","avatar":""},{"name":"Park Jeong-hak","avatar":""},{"name":"Ji Dae-han","avatar":""},{"name":"Kim In-woo","avatar":""},{"name":"Jang In-sub","avatar":""},{"name":"Kim Da-hyun","avatar":""},{"name":"Han Ji-Wan","avatar":""},{"name":"Jang Seo-kyung","avatar":""},{"name":"Yoo Ji-yeon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":