INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-thich-hen-ho-nhung-so-co-don', 'Không Thích Hẹn Hò Nhưng Sợ Cô Đơn', 'Lonely Enough to Love!', 'https://phimimg.com/upload/vod/20241122-1/05b529ff14622b2b3f2ad0ad00cdbc15.jpg', 'https://phimimg.com/upload/vod/20241122-1/6bd6226769c92a71d0845ee251a81a6a.jpg', '<p>Hai người trẻ vừa muốn yêu, vừa sợ gánh nặng, vừa thích tự do độc thân, vừa sợ cô đơn khi cả hai cùng sống dưới một mái nhà. Bộ phim phản ánh chân thật những thực tế và khó khăn của giới trẻ, nhưng cũng có những khoảnh khắc yêu thương ấm áp khiến tim bạn lỡ nhịp.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ji Hyun-woo","avatar":""},{"name":"Kim So-eun","avatar":""},{"name":"Park Geon-il","avatar":""},{"name":"Kim San-ho","avatar":""},{"name":"Gongchan","avatar":""},{"name":"Cha Soo-yeon","avatar":""},{"name":"Son Ji-hyun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["恋爱虽然麻烦但更讨厌孤独","Dating is Annoying, but I Don’t Wanna be Lonely","Love is Annoying, but I Hate Being Lonely","Can''t Bother Dating, Hate Being Lonely!","연애는 귀찮지만 외로운 건 싫어!"]', 1784690324334);
