INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-thich-hen-ho-nhung-so-co-don', 'Không Thích Hẹn Hò Nhưng Sợ Cô Đơn', 'Lonely Enough to Love!', 'không thích hẹn hò nhưng sợ cô đơn lonely enough to love! ji hyun-woo kim so-eun park geon-il kim san-ho gongchan cha soo-yeon son ji-hyun 恋爱虽然麻烦但更讨厌孤独 dating is annoying, but i don’t wanna be lonely love is annoying, but i hate being lonely can''t bother dating, hate being lonely! 연애는 귀찮지만 외로운 건 싫어!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-ngu-luc', 'Thám Tử Ngữ Lục', 'Detective', 'https://phimimg.com/upload/vod/20241122-1/6b0abb65c90debe2fb90ceaf903fafe9.jpg', 'https://phimimg.com/upload/vod/20241122-1/64464de9428fd25f0da96de4838357d5.jpg', '<p>Năm 1911 và Trung Quốc đang ở trước thềm cuộc cách mạng. Một loạt các vụ giết người liên quan xảy ra ở vùng nông thôn Fuyuan, một quận ở ngoại ô Thiên Tân. Thám tử Thiên Tân Tan Bodun và đội trưởng của anh ta ở đó để giải quyết vụ án. Sau khi khám phá những lớp bí ẩn, anh biết được một bí mật gây sốc về 1 âm mưu lớn và cuộc đấu tranh giữa công lý và cái ác bắt đầu.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gao Zhiting","avatar":""},{"name":"Zhang Xin","avatar":""},{"name":"Qu Gao Wei","avatar":""},{"name":"Wang Longzheng","avatar":""},{"name":"Liu Yijun","avatar":""},{"name":"Liu Enshang","avatar":""},{"name":"Xiu Meng","avatar":""},{"name":"Chen Yali","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Detective","侦探语录"]', 1784690324334);
