INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-xanh-lang-man', 'Sắc Xanh Lãng Mạn', 'Romantic Blue', 'https://phimimg.com/upload/vod/20241122-1/abd614bdd0bce10a35a69c49f9126033.jpg', 'https://phimimg.com/upload/vod/20241122-1/9cb0d889752b0d97deb41fbb0d83925a.jpg', '<p>Nội dung phim xoay quanh cuộc đời của hai anh em Mai và Man, cùng câu chuyện tình yêu trắc trở với cô gái xinh đẹp tên Pon. Hai anh em Mai và Men cùng yêu một cô gái tên Pon, nhưng do điều kiện gia đình không tốt, hai anh em đành dấn thân vào thế giới đen tối. &nbsp;Nhờ sự giới thiệu của Bo, hai anh em họ gia nhập vào một nhóm cướp xe do To dẫn đầu. Không lâu sau, bố của Mai là Sorn mất, Men cũng biết về quan hệ yêu dương của Mai và Pon. Lần này, Mai đã vướng phải vô vàn rắc rối, bao gồm cả sự truy sát của To. Chính vì vậy, Mai buộc phải giải quyết hết mọi rắc rối của mình, dù là trong tình cảm hay với những người xung quanh.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Thitiwat Ritprasert","avatar":""},{"name":"Prachaya Ruangroj","avatar":""},{"name":"Tipnaree Weerawatnodom","avatar":""},{"name":"Somchai Kemklad","avatar":""},{"name":"Kitsadee Phuangprayong","avatar":""},{"name":"Praeploy Oree","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["โลกทั้งใบให้นายคนเดียว"]', 1784690324334);
