INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-du-hoan-thuy', 'Tôi Là Dư Hoan Thuỷ', 'If There Is No Tomorrow', 'https://phimimg.com/upload/vod/20241122-1/edfe53b0ed83f085ddb6f5c3b876cb80.jpg', 'https://phimimg.com/upload/vod/20241122-1/b60d9153d9c681aa69fe375373319a67.jpg', '<p>Phim chưa có nội dung.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guo Jingfei","avatar":""},{"name":"Miao Miao","avatar":""},{"name":"Gao Lu","avatar":""},{"name":"Yue Yang","avatar":""},{"name":"Gao Ye","avatar":""},{"name":"Feng Hui","avatar":""},{"name":"Zhao Da","avatar":""},{"name":"Ning Wentong","avatar":""},{"name":"Fu Bohan","avatar":""},{"name":"Lexuan Lin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["If There''s No Tomorrow","我是余欢水"]', 1784690324334);
