INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-la-du-hoan-thuy', 'Tôi Là Dư Hoan Thuỷ', 'If There Is No Tomorrow', 'tôi là dư hoan thuỷ if there is no tomorrow guo jingfei miao miao gao lu yue yang gao ye feng hui zhao da ning wentong fu bohan lexuan lin if there''s no tomorrow 我是余欢水', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoc-vuong-dai-nhan-than-yeu', 'Dược Vương Đại Nhân Thân Yêu', 'Dear Herbal Lord', 'https://phimimg.com/upload/vod/20241122-1/8b15bf6d676e6fac7f5a1572b0077f7c.jpg', 'https://phimimg.com/upload/vod/20241122-1/a6ba267648366ec13ffcbb888a295956.jpg', '<p>Tiểu Tùng Lam một lòng muốn tu luyện thành chính quả, nhưng không ngờ âm dương sai lối bị quận chúa ăn luôn vào bụng. Để sớm được đắc đạo thành tiên, nàng đành phải đâm lao theo lao ép hôn “Dược Vương” Sở Chi Mặc, hòng hấp thụ dược khí trên người hắn. Mặc dù cây Bản Lam Căn này hơi ngốc, nhưng lại rất cố chấp. Nàng ngó lơ sự lạnh lùng của Sở Chi Mặc, trăm phương nghìn kế quyết tâm phải gả bằng được cho hắn. Trước đó, nàng còn cố tình về núi Trầm Hương, gọi hết mấy người tiên hữu thân thiết với mình đến nhân gian, để họ giúp nàng theo đuổi tình yêu. Thế mới có hàng loạt hành động cọc đi tìm trâu vừa ngốc vừa đáng yêu, đồng thời cũng từ đó mà “tìm lại được” tình yêu chân thành nhất, để cùng nhau viết nên câu chuyện chống lại “Ôn Thần”, giải cứu nhân thế.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ding Yiyi","avatar":""},{"name":"Yan Xi","avatar":""},{"name":"Leo Yang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["ตำรับรักฉบับภูติสาวสมุนไพร","Dear Herbal Lord (2020)","亲爱的药王大人"]', 1784690324334);
