INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-thi-nghiem-dieu-ky-cua-emily', 'Phòng thí nghiệm diệu kỳ của Emily', 'Emily''s Wonder Lab', 'https://phimimg.com/upload/vod/20241121-1/4ad2cbb84b6a06e3774f862fabab9131.jpg', 'https://phimimg.com/upload/vod/20241121-1/8e747505e00e3c24f5ae1a59d5a5f5f2.jpg', '<p>Người dẫn chương trình yêu khoa học Emily Calandrelli giúp STEAM trở nên thú vị với các hoạt động, màn trình diễn và thí nghiệm tại nhà khiến bạn suy ngẫm và choáng ngợp.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Emily Calandrelli","avatar":""},{"name":"Kennedi Lynn Butler","avatar":""},{"name":"Makenzie Lee-Foster","avatar":""},{"name":"Sky Alexis","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["O Lab de Emily","Emily''s Wonder Lab"]', 1784690324334);
