INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phong-thi-nghiem-dieu-ky-cua-emily', 'Phòng thí nghiệm diệu kỳ của Emily', 'Emily''s Wonder Lab', 'phòng thí nghiệm diệu kỳ của emily emily''s wonder lab emily calandrelli kennedi lynn butler makenzie lee-foster sky alexis o lab de emily emily''s wonder lab', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-vung-2020', 'Nằm Vùng', 'An Undercover', 'https://phimimg.com/upload/vod/20241119-1/1ddb817dbb2305f26cc7d265a8a32f7f.jpg', 'https://phimimg.com/upload/vod/20241119-1/2ef5cbea522851fb49843eee3efaa907.jpg', '<p>Ngụy Thứ Phương, một trinh sát trẻ tuổi và là thế hệ nữ cảnh sát đặc nhiệm mới &quot;Xứng Danh&quot; Đã bắt đầu sự nghiệp trinh sát đặc biệt ( nằm vùng ) ngay sau khi cô vừa rời học viện huấn luyện đặc biệt. Để hoàn thành nhiệm vụ, cô đã sử dụng nhiều danh tính và nghề nghiệp khác nhau để che giấu thân phận và xâm nhập vào hang ổ của nhiều băng đảng tội phạm khác nhau. Cô đã đóng nhiều vai trò khác nhau như ( Sinh viên đại học, người làm công, nhân viên văn phòng, nhân viên cứu hộ thể thao, người phục vụ, vệ sĩ…v..v ) Dựa vào ý chí kiên cường và bản lĩnh tuyệt vời của mình mà cô đã dũng cảm mưu trí chiến đấu với mọi loại tội phạm. Tuy Nhiên, ngay sau khi cô đột nhập vào một tổ chức tội phạm, cô đã vô tình gặp gỡ với người đàn ông tên là Ngô Đồng, đây là người đầu tiên cho cô nếm trãi mùi vị đẹp đẽ nhất của tình yêu nam nữ. Nhưng mà người đàn ông này lại rơi vào lưới tình của một người phụ nữ khác trong tổ chức tội phạm. Thoạt nhìn thì Ngụy Thứ Phương trông có vẻ yếu ớt và ôn nhu, nhưng không ai biết được bên trong cô là một trái tim cứng cỏi và một quyết tâm chắc như đinh đóng cột. Trên thực tế, mọi nhiệm vụ mà cô thực hiện đều là để giải thoát cho những người tốt bụng và vô tội như Ngô Đồng, giúp họ thoát khỏi sự lừa dối và nguy hiểm, đồng thời cũng mang lại cho họ một cuôc sống ổn định.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Annabel Lee","avatar":""},{"name":"Zhang Xiao Long","avatar":""},{"name":"Shang Tie Long","avatar":""},{"name":"Xu Lei Zhi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324334);
