INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-chong-toi-that-dang-yeu', 'Mẹ Chồng Tôi Thật Đáng Yêu', 'U Motherbaker', 'https://phimimg.com/upload/vod/20241119-1/19bf006672b64926c02dcc9e6eb9f47a.jpg', 'https://phimimg.com/upload/vod/20241119-1/f88f163dbc4c6839c0c6727d5d130e2d.jpg', '<p>Tiểu Âu là con dâu út của nhà họ Tô, vừa mới về nhà chồng chưa được bao lâu thì bất hạnh ập đến, bố chồng và chồng lần lượt ra đi.

Bà quả phụ Tiểu Âu chỉ mong sao nhanh chóng cắt đứt mọi quan hệ với mẹ chồng, nhưng số phận khiến cho cô và mẹ chồng ngày một gần gũi hơn.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 9, 2020, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Hsin-Ling Chung","avatar":""},{"name":"Huang Peijia","avatar":""},{"name":"Honduras","avatar":""},{"name":"Joe Chang","avatar":""},{"name":"Kai-wei Chiu","avatar":""},{"name":"Sam Wang","avatar":""},{"name":"Johnny Yang","avatar":""},{"name":"Esther Liu","avatar":""},{"name":"Candy Yang","avatar":""},{"name":"Chiao Yuan-Yuan","avatar":""},{"name":"Riva Chang","avatar":""},{"name":"Sara Yu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["아적파파즘마나마가애 : 나의 귀여운 시어머니","我的婆婆怎麼那麼可愛2","Mẹ Chồng Tôi Sao Mà Dễ Thương Thế","我的婆婆怎麼那麼可愛"]', 1784690324334);
