INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-tinh-chi-lo', 'Thiên Tỉnh Chi Lộ', 'Legend of Awakening', 'https://phimimg.com/upload/vod/20241119-1/9945ac6f6dc09b5b491589888b0237fe.jpg', 'https://phimimg.com/upload/vod/20241119-1/38b2497365c3fd96ccdb658f05d507c0.jpg', '<p>Thiên Tỉnh Chi Lộ là bộ phim về đề tài võ hiệp kỳ ảo, xoay quanh nam chính Lộ Bình và cuộc đấu tranh giữa các học viện dị năng trong một đại lục giả tưởng. Kể về thời Đại Nam Bắc Triều - người dân đã bị thú dữ tàn phá nên họ bắt đầu tu luyện như một vũ khí tự bảo vệ. Bốn anh hùng trẻ tuổi bắt đầu trên một hành trình hướng tới sự thức tỉnh. Lộ Bình và Tô Đường là trẻ mồ côi. Trường võ thuật Trạch Phong đưa họ vào khi họ còn trẻ và họ trở thành bạn tốt với Tần Tang và Yến Tây Phàm. Cả bốn làm một hiệp ước để trở thành một trong những người thức tỉnh, do đó bắt đầu trên một con đường nơi họ sẽ đối mặt với nhiều đối thủ khác nhau để đạt được mục tiêu của mình.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Arthur Chen","avatar":""},{"name":"Dylan Xiong","avatar":""},{"name":"Cheng Xiao","avatar":""},{"name":"Deng Enxi","avatar":""},{"name":"Yu Yijie","avatar":""},{"name":"Shang Xuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Путь пробуждения","Предание о пробуждении","天醒之路"]', 1784690324334);
