INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-cung-khao-khat-gap-duoc-em', 'Ai Cũng Khao Khát Gặp Được Em', 'Everyone Wants To Meet You', 'https://phimimg.com/upload/vod/20241119-1/b98cba8ead8a460a547fa0994ef859b7.jpg', 'https://phimimg.com/upload/vod/20241119-1/30ba89f17e77ddbdb2259bf43a62d393.jpg', '<p>Người sáng lập Tập đoàn Tứ Hải Trương Mẫn và cô gái ion âm La Khê có thể nói chuyện được với thực vật, khả năng mà thuật của La Khê đã chữa khỏi nỗi đau cho Trương Mẫn. Trương Mẫn luôn biết cha anh luôn nhớ về đứa trẻ đã mất khi anh còn nhỏ, cuộc sống của anh là cho đứa trẻ đó . Nhà thiên văn học Đào Luân là thanh mai trúc mặc thuở nhỏ của La Khê là một đứa trẻ mồ côi. Anh ta đang kiên trì đi tìm cuộc sống của chính mình. Anh ta biết tất cả các chòm sao trên bầu trời nhưng lại không biết chòm sao của chính mình. Khi ba người gặp nhau như sự sắp xếp trước của định mệnh thì Trương Mẫn phát hiện ra Đào Luân chính là người thừa kế thực sự</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Ruonan","avatar":""},{"name":"Zhang Zhehan","avatar":""},{"name":"Chen Haolan","avatar":""},{"name":"Wang Yilun","avatar":""},{"name":"Wang Xiaokun","avatar":""},{"name":"Peng Bo","avatar":""},{"name":"Zhang Yan","avatar":""},{"name":"Tu Ling","avatar":""},{"name":"Liu Zheer","avatar":""},{"name":"Li Nanxing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Everyone Wants to Meet You","Ai Cũng Khao Khát Gặp Được Em","谁都渴望遇见你"]', 1784690324334);
