INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-quai-vat-goc-nhin-tung-tap-phim', 'Thợ săn quái vật: Góc nhìn từng tập phim', 'The Witcher: A Look Inside the Episodes', 'https://phimimg.com/upload/vod/20241120-1/4daa6ae8d03377fc53af4f515e4badf3.jpg', 'https://phimimg.com/upload/vod/20241120-1/50de668dd64af43efe3acd0a6a33a7f0.jpg', '<p>Với sự dẫn dắt của tác giả loạt phim Lauren S. Hissrich, hãy tham gia hành trình khám phá trọn vẹn các câu chuyện và chủ đề nổi bật trong &quot;Thợ săn quái vật&quot; mùa đầu tiên.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lauren Schmidt Hissrich","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["The Witcher: A Look Inside the Episodes"]', 1784690324334);
