INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-hai-muoi', 'Tuổi Hai Mươi', 'Twenty Your Life On', 'https://phimimg.com/upload/vod/20241120-1/0a03fa49a932a2d2787c667abf434cb7.jpg', 'https://phimimg.com/upload/vod/20241120-1/743d002b31ef4abfa1e32dd66dd02b94.jpg', '<p>Quyền lực, nhan sắc và tiền bạc là thứ mà cô nàng “ba không” Khương Tiểu Quả luôn ngưỡng mộ những người bạn cùng phòng của mình: Đoạn Gia Bảo giàu có nhưng ngây thơ, không chút lo lắng, chỉ biết tới đồ ăn và thần tượng; La Diễm tuy ghét mẹ mình luôn làm theo ý mình, nhưng ít nhất không phải lo chuyện xin việc làm; mỹ nhân lạnh lùng Lương Sảng khéo ăn nói từ năm cuối đại học đã lao ra xã hội làm ăn, như cá gặp nước, rất là nhanh nhẹn. Nhưng họ đều không biết những khó khăn phải giải quyết sau khi tốt nghiệp. Đoạn Gia Bảo thử yêu một người lại không ngờ rằng mình và bạn thân có chung một đối tượng. La Diễm cố tiến gần tới mẹ thì phát hiện mẹ mình đang cất giấu một bí mật. Còn Lương Sảng lại phải tìm cách để không tổn thương người yêu thương mình. Trong một năm, bốn cô gái thân thiết với nhau hơn, Khương Tiểu Quả cũng tìm thấy được công việc và tình yêu cho bản thân sau bao nhiêu cố gắng.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guan Xiaotong","avatar":""},{"name":"Bu Guanjin","avatar":""},{"name":"Li Gengxi","avatar":""},{"name":"Dong Siyi","avatar":""},{"name":"Jin Shijia","avatar":""},{"name":"Niu Junfeng","avatar":""},{"name":"Wang Anyu","avatar":""},{"name":"Vincent Cao","avatar":""},{"name":"Xu Shaoying","avatar":""},{"name":"Xu Mengjie","avatar":""},{"name":"Jackson Zhou Zaharoni","avatar":""},{"name":"Cheng Si Han","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Twenty Your Life on","二十不惑2","二十不惑"]', 1784690324334);
