INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-than-cuong-phi-phung-khinh-thien-ha', 'Chiến Thần Cuồng Phi: Phụng Khinh Thiên Hạ', 'Battlefield Of The Crazy Empresses', 'https://phimimg.com/upload/vod/20241120-1/4b6e0c6d281d314dc77932afae467c9d.jpg', 'https://phimimg.com/upload/vod/20241120-1/5d23ec7a84a0a074b7039549cbd39a45.jpg', '<p>Đặc vụ hàng đầu xuất thân từ trại huấn luyện ma quỷ bị giết hại do sự phản bội của cấp trên. Cô được tái sinh đến lục địa Huyền Hải, trở thành tam tiểu thư nhà họ Yến gặp họa diệt môn, từ đây cô làm rung chuyển cục diện nơi này.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 14, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324334);
