INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-mo-but-ky-chung-cuc-but-ky', 'Đạo Mộ Bút Ký: Chung Cực Bút Ký', 'Ultimate Note', 'https://phimimg.com/upload/vod/20241120-1/5d833475558fe361208354922371f91d.jpg', 'https://phimimg.com/upload/vod/20241120-1/20cba2a0ec7ac6e5cfd73463ce819264.jpg', '<p>Chung Cực Bút Ký là câu chuyện vốn dĩ Ngô Tà chỉ thấy hứng thú với kinh nghiệm thực tế của chú ba, nhưng sau khi xem những cuộn băng cassette của chú mình, cậu lại phát hiện ra bản thân đã bị cuốn vào một âm mưu vô cùng lớn. Trong quá trình dấn thân vào nguy hiểm, cậu gặp được nhóm người với những mục đích khác nhau là Trương Khởi Linh, Giải Vũ Thần... Họ thành lập nhóm 6 người cùng hành động. Trương Khởi Linh bất ngờ mất trí nhớ. Mọi người tìm hiểu mới biết nhà cũ của nhà họ Trương mới là nơi có thể giải đáp mọi bí mật, nhưng do thế lực của Cầu Đức Khảo không đủ đành phải từ bỏ. Sau này, Ngô Tà nhờ tấm bản đồ mô phỏng mà quen được Hoắc Lão Thái của Cửu Môn. Không may, Ngô Tà bị thương nặng, Trương Khơi Linh và Bàn Tử sống chết không rõ, tất cả bí mật đều chưa được giải đáp. Giải Vũ Thần muốn Ngô Tà đóng giả làm chú ba, nhưng cậu lại do dự không quyết.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 9, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Joseph Zeng","avatar":""},{"name":"Xiao Yuliang","avatar":""},{"name":"Hani Kezi","avatar":""},{"name":"Liu Yuning","avatar":""},{"name":"Fan Ming","avatar":""},{"name":"Liu Yuhan","avatar":""},{"name":"Wang Jinsong","avatar":""},{"name":"Pema Jyad","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["盗墓笔记：终极笔记","盗墓笔记之终极笔记","종극필기","終極筆記","Ultimate Note","Đạo Mộ Bút Ký: Chung Cực Bút Ký","终极笔记"]', 1784690324334);
