INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-nguy-dai-dich', 'Mối nguy đại dịch', 'Pandemic: How to Prevent an Outbreak', 'https://phimimg.com/upload/vod/20241119-1/4f27fd2b2b45f5923c88c0a0e1b219e5.jpg', 'https://phimimg.com/upload/vod/20241119-1/097f4eab54d6ed8b7b52b083172dc798.jpg', '<p>Hãy gặp các anh hùng tuyến đầu trên mặt trận chống lại bệnh cúm và tìm hiểu nỗ lực của họ trong việc ngăn chặn đại dịch toàn cầu tiếp theo với loạt phim tài liệu này.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Syra Madad","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["流行病：如何预防流感大爆发","流感來襲","Pandemic: How to Prevent an Outbreak"]', 1784690324334);
