INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-toan-tri', 'Thành phố toàn tri', 'Omniscient', 'https://phimimg.com/upload/vod/20241119-1/d64d9fe04b1245627514d9b67696680d.jpg', 'https://phimimg.com/upload/vod/20241119-1/0592448e541dab121896f31f35b6f039.jpg', '<p>Ở thành phố mà người dân bị giám sát 24/7, một nhân viên kỹ thuật phải tìm cách vượt mặt máy bay giám sát để điều tra một vụ án mạng.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 14, 2020, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Jonathan Haagensen","avatar":""},{"name":"Luana Tanaka","avatar":""},{"name":"Sandra Corveloni","avatar":""},{"name":"Carla Salle","avatar":""},{"name":"Edmilson Cordeiro","avatar":""},{"name":"Guilherme Prates","avatar":""},{"name":"Marcello Airoldi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Onisciente"]', 1784690324334);
