INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-thien-thien-ngay-ay-bay-gio', 'Trần Thiên Thiên Ngày Ấy Bây Giờ', 'The Romance Of Tiger And Rose', 'https://phimimg.com/upload/vod/20241120-1/af23fd2e24397d4ed5c258f58d4a6135.jpg', 'https://phimimg.com/upload/vod/20241120-1/265f8a2289c9b849b155ccf4cc06a9fd.jpg', '<p>Tiểu Thiên là một nhà biên kịch tài năng, đang trong lúc tâm huyết viết nên kịch bản về nữ quyền. Tất cả đều thuật lợi cho đến khi nam chính chất vấn quá nhiều về tình cảm của nhân vật trong tác phẩm, Tiểu Thiên vì muốn chứng tỏ năng lực của bản thân mình ai ngờ lại bị kẹt trong chính bi kịch của mình. Tiểu Thiên xuyên không về quá khứ trở thành Công chúa của Đông Lương Quốc, có địa vị cao quý, quyền cao chức trọng nhưng lại nổi tiếng muôn nơi về độ độc ác của mình. Chỉ là tuyến nhân vật phụ không sống sót quá ba tập phim, vì bảo toàn tính mạng Thiên Thiên đã tìm đủ mọi cách mở ra phó bản, dịch chuyển nhân sinh, đảo ngược cuộc sống vô lý.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Lusi","avatar":""},{"name":"Ding Yuxi","avatar":""},{"name":"Sheng Yinghao","avatar":""},{"name":"Zhou Zixin","avatar":""},{"name":"Patrick Quan","avatar":""},{"name":"Liu Shuyuan","avatar":""},{"name":"Wu Yijia","avatar":""},{"name":"Wei Xiao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["传闻中的三公主","传闻中的陈芊芊","花の都に虎（とら）われて～The Romance of Tiger and Rose～","花の都に虎われて The Romance of Tiger and Rose","ข้านี่เเหละองค์หญิงสาม","傳聞中的陳芊芊"]', 1784690324334);
