INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-dau-coi-chet', 'Làm Dâu Cõi Chết', 'The Ghost Bride', 'https://phimimg.com/upload/vod/20241118-1/829e28ada1ae9f740b5123b8ed1ddecd.jpg', 'https://phimimg.com/upload/vod/20241118-1/70f7ce41ab350873064bccbc8d2a05c9.jpg', '<p>Làm Dâu Cõi Chết kể về thời gian vào những năm 1890 ở Malacca, Lệ Lan thấy mình ở kiếp sau và bị đẩy vào một bí ẩn liên quan đến người con trai hung hãn đã mất của một gia đình giàu có.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 15, 2020, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Kuang Tian","avatar":""},{"name":"Baily Oh","avatar":""},{"name":"Wu Kang-ren","avatar":""},{"name":"Teresa Daley","avatar":""},{"name":"Huang Peijia","avatar":""},{"name":"Ludi Lin","avatar":""},{"name":"Janet Hsieh","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["เจ้าสาวเซ่นศพ","The Ghost Bride","彼岸之嫁"]', 1784690324334);
