INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suy-luan-hu-cau', 'Suy Luận Hư Cấu', 'In Spectre', 'https://phimimg.com/upload/vod/20241116-1/967338483781e78a61e5e546ce8227ac.jpg', 'https://phimimg.com/upload/vod/20241116-1/94a62db8295b79dfc5610dee87e44c57.jpg', '<p>Ở tuổi 11, Kotoko Iwanaga đã bị yêu quái bắt cóc trong hai tuần và được yêu cầu trở thành Thần trí tuệ của họ, một người trung gian giữa linh hồn và thế giới con người, mà cô gái nhanh chóng đồng ý nhưng phải trả giá bằng mắt phải và chân trái. Bây giờ, sáu năm sau, bất cứ khi nào yêu quái muốn giải quyết vấn đề của họ, họ tìm đường đến Kotoko để tham khảo ý kiến.

Trong khi đó, Kurou Sakuragawa, một sinh viên đại học 22 tuổi, vừa chia tay bạn gái sau khi anh trốn đi một mình khi hai người gặp phải một kappa. Nhận thấy đây là cơ hội để cô trở nên thân thiết hơn với anh, Kotoko ngay lập tức khiến cô cảm động, hy vọng một ngày nào đó sẽ kết hôn với Kurou. Tuy nhiên, cô nhanh chóng nhận ra có gì đó hơn với Kurou. Với kiến thức này, cô ấy đã nhờ anh ấy giúp giải quyết các vấn đề khác nhau do siêu nhiên đưa ra, trong khi đó, mong muốn người bạn đời mới của cô ấy cuối cùng sẽ đáp lại tình cảm của cô ấy.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Akari Kito","avatar":""},{"name":"Mamoru Miyano","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Kyokō Suiri","Kyokou Suiri","虚構推理 Season2","虚構推理 ミニアニメ","Inspectre","Invented Inference","Bảo Vệ Nhân Gian Và Yêu Giới","虚構推理"]', 1784690324334);
