INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-gia-dinh-phan-4', 'Chuyện Gia Đình (Phần 4)', 'F Is For Family (Season 4)', 'https://phimimg.com/upload/vod/20241114-1/fa9b998abe0c32f34bc878b8119365f0.jpg', 'https://phimimg.com/upload/vod/20241114-1/bbc89834c7d6b59be6f966cc8fefea24.jpg', '<p>Trong khi Frank đối phó với chuyến thăm không mong đợi từ ông bố xa cách, Sue áp dụng phương pháp hỗ trợ mang thai Thời đại mới. Bọn trẻ nhà Murphy thử có tính cách mới.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bill Burr","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Debi Derryberry","avatar":""},{"name":"Haley Reinhart","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Mo Collins","avatar":""},{"name":"Trevor Devall","avatar":""},{"name":"Phil Hendrie","avatar":""},{"name":"David Koechner","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"Vince Vaughn","avatar":""},{"name":"Jonathan Banks","avatar":""},{"name":"Joe Pera","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["С за семейство","P niin kuin per...","משפחת מרפי","FはFamilyのF","그때 그 시절 패밀리","Nie ma jak w rodzinie","福是全家福的福","F is for Family"]', 1784690324334);
