INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tap-tanh-lam-me', 'Tập Tành Làm Mẹ', 'Birthcare Center', 'tập tành làm mẹ birthcare center uhm ji-won park ha-seon jang hye-jin yoon park choi ri im hwa-young bae woo-hee moo jin-sung choi soo-min lee se-rang nam yoon-su choi ja-hye jung sung-il son sook lee jun-hyeok birthcare center 산후조리원', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-no-ngay-nang-phan-2', 'Hoa Nở Ngày Nắng (Phần 2)', 'I Don''t Want To Run (Season 2)', 'https://phimimg.com/upload/vod/20241113-1/fc7c5ee296bcf7acadfb828d04607e0a.jpg', 'https://phimimg.com/upload/vod/20241113-1/c12d216760ec56ac6d4a7f4ca0fa2af3.jpg', '<p>Bộ phận kinh doanh đặc biệt của tập đoàn Hải Tinh bước vào thời kỳ phát triển nhanh chóng, Lý Tô Hàng chuẩn bị đưa quảng cáo lên để nâng cao danh tiếng thương hiệu. Hướng Tình ngoài ý muốn phát hiện chương trình giải trí La Na xem có khả năng truyền cảm hứng, buộc Lý Tô Hàng tham gia chương trình. Khí thế người lạ chớ gần của Lý Tô Hàng khiến hắn bị loại ngay ở vòng thứ nhất. Không nghĩ tới chính là, ngày hôm sau, Lý Tô Hàng ngoài ý muốn leo lên hot search, hơn nữa đạt được danh hiệu &quot;Hoàng tử khăn dì&quot;. Nhân cơ hội này, các sản phẩm của Tập đoàn nhanh chóng đạt được sự phổ biến rộng rãi trong quần chúng phụ nữ và thậm chí một số tập đoàn bán lẻ lớn cũng có ý định mua lại thương hiệu mới này. Hướng Tình đưa ra phương án kế hoạch mới, hy vọng có thể để cho ban lãnh đạo cấp cao tập đoàn nhìn thấy tiềm lực của bộ phận kinh doanh, chấm dứt toàn bộ kế hoạch mua lại. Thừa dịp Hướng Tình tiếp tục đẩy mạnh kế hoạch &quot;Bạn trai chung&quot;, Lý Tô Hàng lặng lẽ tụ tập những người khác đến bên cạnh, Lý Tô Hàng hy vọng bọn họ có thể giúp hắn một việc. Dưới bầu trời sao rực rỡ, trong tiếng chúc phúc của mọi người, Lý Tô Hàng cầm hoa tươi, biểu lộ tâm ý của mình với Hướng Tình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Yue","avatar":""},{"name":"Xiao Yin","avatar":""},{"name":"Thassapak Hsu","avatar":""},{"name":"Fan Meng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["撩了我别想跑","花开有晴天"]', 1784690324335);
