INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-no-ngay-nang', 'Hoa Nở Ngày Nắng', 'I Don''t Want To Run', 'https://phimimg.com/upload/vod/20241113-1/af19d51de2ee1cad0237d0401a7143e5.jpg', 'https://phimimg.com/upload/vod/20241113-1/01c8bd08d589f620d2f4a32c42348b30.jpg', '<p>Hướng Tình và Lý Tô Hàng va chạm rồi xảy ra xung đột, hai người lại gặp nhau trong buổi phỏng vấn của tập đoàn Hải Tinh, cả hai đều ghét bỏ nhìn đối phương, may mắn thay, Lưu Dược là người phỏng vấn đã giải vây. Sau khi vượt qua bài kiểm tra đầy khó khăn của Lý Tô Hàng, Hướng Tình chính thức trở thành một thành viên của bộ phận kinh doanh đặc biệt, cũng làm việc với bốn nam thần có tính cách khác nhau, theo thứ tự là &quot;Điều hòa trung ương siêu cấp&quot; Lưu Dược, “cậu bé sức sống” Hoàng Tử Hiên, mỗi ngày cho cô nhiều ánh mặt trời một chút, một người đàn ông có miệng lưỡi độc địa không chịu suy nghĩ, cùng với một bạo quân bộ phận luôn ngược tâm thỉnh thoảng ngọt ngào Lý Tô Hàng. Trong lúc năm người làm việc chung, bọn họ không ngừng khai thác thuộc tính sản phẩm của đối phương, chống lại những thói quen xấu trong ngành, chống lại sự cạnh tranh ác liệt của đồng nghiệp. Đồng thời, Hướng Tình cũng bắt đầu phát hiện một mặt khác mà Lý Tô Hàng, tổng giám đốc bề ngoài &quot;hoàn mỹ&quot; lại có bóng ma trong lòng không thể cho người khác biết, mà anh chỉ sợ tránh không kịp, dẫn tới cô lại càng tò mò tới gần anh. Mà cô chưa từng nghĩ tới, Tò mò cuối cùng một ngày sẽ &quot;hại chết&quot; con mèo lớn này.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Yue","avatar":""},{"name":"Xiao Yin","avatar":""},{"name":"Thassapak Hsu","avatar":""},{"name":"Fan Meng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["撩了我别想跑","花开有晴天"]', 1784690324335);
