INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-tra-bi-mat-cua-hoang-gia', 'Thanh Tra Bí Mật Của Hoàng Gia', 'Royal Secret Agent', 'https://phimimg.com/upload/vod/20241113-1/c8079cee01df2fe4f53b696e2fedcba2.jpg', 'https://phimimg.com/upload/vod/20241113-1/cbd7f20f5fadbad54e3b79efbbe21fbe.jpg', '<p>Câu chuyện kể về chức quan ám hành ngự sử trong triều đại Hàn Quốc xưa. Họ là tai mắt cho nhà vua đồng thời là tiếng nói của người dân, là anh hùng bí mật bảo vệ chính nghĩa. Kim Myung Soo vào vai ám hành ngự sử được vào cung sau khi đỗ trạng nguyên nhưng lại cực kì yêu thích võ thuật, thường ngày sắp xếp thư viện, ban đêm hóa thân thành tên cờ bạc lang thang. Kwon Nara vào vai kĩ nữ xinh đẹp thông minh, gan dạ không kém gì nam nhi. Lee Tae Hwan vào vai tên đạo tặc tuy mặt mày hung dữ nhưng lại trừ hại cho dân.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"L","avatar":""},{"name":"Kwon Na-ra","avatar":""},{"name":"Lee Yi-kyung","avatar":""},{"name":"Lee Tae-hwan","avatar":""},{"name":"Jo Soo-min","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"Choi Jong-won","avatar":""},{"name":"Son Byung-ho","avatar":""},{"name":"Chae Dong-hyeon","avatar":""},{"name":"Park Joo-Hyung","avatar":""},{"name":"Kim Ju-Young","avatar":""},{"name":"Shin Ji-hoon","avatar":""},{"name":"Han Eun-seong","avatar":""},{"name":"Lee Sang-un","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["New Secret Royal Inspector","암행어사 - 조선비밀수사단","암행어사-조선비밀수사단","암행어사:조선비밀수사단","Новый тайный королевский инспектор","Secret Royal In