INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-trung-quoc', 'Bác sĩ Trung Quốc', 'The Chinese Doctor', 'https://phimimg.com/upload/vod/20241113-1/de4bae53af0b4fafb88bbee8ebc85d22.jpg', 'https://phimimg.com/upload/vod/20241113-1/d3bcadb0251d4a1aa250e4e244edcf2e.jpg', '<p>“Bác sĩ Trung Quốc” là bộ phim tài liệu đầu tiên về y học với nhân vật chính là đội ngũ y tế của Trung Quốc. Bộ phim tài liệu xoay quanh 6 bệnh viện lớn hàng đầu tại Trung Quốc (Bệnh viện Hoa Tây, bệnh viện Cổ Lâu Nam Kinh, bệnh viện Trực thuộc số 1 Đại học Giao thông Tây An, bệnh viện Nhân dân tỉnh Chiết Giang, bệnh viện Trực thuộc số 1 Đại học Khoa học và Công nghệ Trung Quốc, bệnh viện nhân dân tỉnh Hà Nam), lựa chọn nhân viên y tế tiêu biểu, tình huống thường xảy ra nhất giữa người bình thường và bệnh viện, ghi lại câu chuyện ấm áp, đầy trách nhiệm, sự mâu thuẫn và hy vọng giữa bác sĩ và bệnh nhân. Đồng thời thể hiện góc nhìn đa chiều về nghề bác sĩ, vai trò quan trọng của hệ thống y tế trong đời sống xã hội, phản ánh chân thực niềm vui cũng như nỗi buồn của các bác sĩ Tr</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 10, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["医心","中国医生","The Chinese Doctor"]', 1784690324335);
