INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-tinh-nghich', 'Thiếu Nữ Tinh Nghịch', 'The Sweet Girl', 'https://phimimg.com/upload/vod/20241113-1/7c8bbc43aea4c739b826e0db535ec225.jpg', 'https://phimimg.com/upload/vod/20241113-1/4e872b82e4fa550621c2bc667f29d1b2.jpg', '<p>Bộ phim kể về mối tình “hoán đổi” dở khóc dở cười giữa ông chủ của Vân Y Phường kiêm nhà thiết kế trang phục hàng đầu, Lạc Dận Nhiên và cô nàng hiệp nữ dám yêu dám hận, tính cách hào sảng Mễ Tửu Nhi;</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jin Meichen","avatar":""},{"name":"Lyan Zhang","avatar":""},{"name":"Wang Zirui","avatar":""},{"name":"Fan Xiaodong","avatar":""},{"name":"Sun Zujun","avatar":""},{"name":"Hou Dong","avatar":""},{"name":"Chu Han","avatar":""},{"name":"Hu Yixuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["小女上房揭瓦第一季","小女上房揭瓦"]', 1784690324335);
