INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-moi-2020', 'Thế Giới Mới', 'New World', 'https://phimimg.com/upload/vod/20241113-1/d65d9587f4d8b092275cd5fa33e3b868.jpg', 'https://phimimg.com/upload/vod/20241113-1/a97f0d50f1e8c6fbdc58642951bc0047.jpg', '<p>Trước thềm giải phóng Trung Quốc, Từ Thiên cảnh sát nhỏ Cục Cảnh sát Bạch Chỉ Phường Từ Thiên trong quá trình điều tra vụ án vị hôn thê Cổ Tiểu Đóa bị hại, đã vô tình tham gia vào sự nghiệp giải phóng Bắc Bình của Đảng Cộng sản Trung Quốc. Đối mặt với thời cuộc rung chuyển, ba anh em Kim Hải, Thiết Lâm và Từ Thiên ở những vị trí khác nhau, khi tình thân, tình yêu, lợi ích quốc gia, tín ngưỡng cá nhân phát sinh xung đột kịch liệt, ba người tình như anh em đã đưa ra lựa chọn khác nhau, đi trên con đường nhân sinh hoàn toàn khác nhau. Từ Thiên và Đảng viên Cộng sản Điền Đan quen biết nhau trong tuyệt vọng, và ý thức về sứ mệnh khiến hai người đến với nhau. Xu Tian đã chọn hỗ trợ Đảng Cộng sản Trung Quốc trong tình trạng hỗn loạn giành được giải phóng hòa bình ở Bắc Bình trong cuộc loạn nạn loạn và mở ra một thế giới mới.</p>', 'Hoàn Tất (70/70)', 70, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yin Fang","avatar":""},{"name":"Sun Honglei","avatar":""},{"name":"Wan Qian","avatar":""},{"name":"Zhang Luyi","avatar":""},{"name":"Li Chun","avatar":""},{"name":"Zhou Dongyu","avatar":""},{"name":"Zhao Zheng","avatar":""},{"name":"Zhang Yao","avatar":""},{"name":"Zhang Yezi","avatar":""},{"name":"Wang Jinsong","avatar":""},{"name":"Lei Jia","avatar":""},{"name":"Zhou Yiwei","avatar":""},{"name":"Song Dandan","avatar":""},{"name":"Li Chengru","avatar":""},{"name":"Hong Jiantao","avatar":""},{"name":"Liang Tian","avatar":""},{"name":"Ma Yan","avatar":""},{"name":"Hu Jing","avatar":""},{"name":"Chin Han","avatar":""},{"name":"Zhao Zi Hui","avatar":""},{"name":"Huang Chengcheng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Xin Shi Jie","New World","新世界"]', 1784690324335);
