INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-moi-2020', 'Thế Giới Mới', 'New World', 'thế giới mới new world yin fang sun honglei wan qian zhang luyi li chun zhou dongyu zhao zheng zhang yao zhang yezi wang jinsong lei jia zhou yiwei song dandan li chengru hong jiantao liang tian ma yan hu jing chin han zhao zi hui huang chengcheng xin shi jie new world 新世界', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-ken-re', 'Đại Chiến Kén Rể', 'Oh My Baby', 'https://phimimg.com/upload/vod/20241113-1/37209a492180fef50877f2fff62203ec.jpg', 'https://phimimg.com/upload/vod/20241113-1/129c10da1cac74de687d922b9d1d0756.jpg', '<p>Jang Ha-Ri là một bà mẹ đơn thân và 39 tuổi. Cô làm việc như một phó giám đốc tại công ty tạp chí nuôi dạy con &quot;The Baby&quot;. Cô ấy có vẻ ngoài xinh đẹp, nhưng cô ấy đã không hẹn hò trong 10 năm qua. Điều này là do Jang Ha-Ri là một người nghiện công việc. Cô đã từ bỏ việc tìm kiếm tình yêu hoặc kết hôn, nhưng cô vẫn muốn có con. Jang Ha-Ri làm quen với 3 người đàn ông. Han Yi-Sang làm việc như một nhiếp ảnh gia tự do, anh ấy liên tục tìm kiếm những sở thích sẽ làm cho anh ấy hạnh phúc. Anh ấy phàn nàn về mọi thứ khá nhiều, nhưng anh ấy nhiệt tình với công việc của mình. Yoon Jae-Young làm việc như một bác sĩ nhi khoa, anh ấy là bạn với Jang Ha-Ri. Đột nhiên, Yoon Jae-Young trở thành một người cha độc thân và anh đấu tranh để giải quyết tình huống của mình. Choi Kang-Eu-Ddeum là một nhân viên tân binh, người làm việc cho Jang Ha-Ri. Anh ấy có một tính cách tích cực và anh ấy ngưỡng mộ cô ấy...</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Na-ra","avatar":""},{"name":"Go Joon","avatar":""},{"name":"Park Byung-eun","avatar":""},{"name":"Jung Gun-joo","avatar":""},{"name":"Jang Gwang","avatar":""},{"name":"Kim Hye-ok","avatar":""},{"name":"Kim Jae-hwa","avatar":""},{"name":"Park Soo-young","avatar":""},{"name":"Jeon Jin-gi","avatar":""},{"name":"Jo Hee-bong","avatar":""},{"name":"Lee Mi-do","avatar":""},{"name":"Wang Ji-hye","avatar":""},{"name":"Baek Seoung-hee","avatar":""},{"name":"Kim Jung-hwa","avatar":""},{"name":"Gi So-you","avatar":""},{"name":"Son Hwa Ryung","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Oh My Baby","اوه عزیز من","O Mai Beibi","Сложности выбора","오 마이 베이비"]', 1784690324335);
