INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gao-nep-gao-te-phan-2', 'Gạo Nếp Gạo Tẻ (Phần 2)', 'Sticky Rice And Plain Rice (Season 2)', 'https://phimimg.com/upload/vod/20241113-1/3f39bb4003b2092c7c6aea6e0393d3a7.jpg', 'https://phimimg.com/upload/vod/20241113-1/be2d65b4098dcf2d0a1f631ad319f9a1.jpg', '<p>Phim có nước mắt đủ để người xem thổn thức với những uất ức, đau khổ mà nhân vật phải chịu đựng trong cuộc sống, nhưng cũng có những nụ cười hạnh phúc, những tình tiết hài hước duyên dáng mang đến cảm xúc lạc quan, vui tươi cho khán giả. Những vấn đề như mâu thuẫn anh chị em, ngoại tình, những hiểu lầm, xào xáo giữa các thành viên sống cùng một nhà… được lồng vào nội dung phim thông qua cách dẫn chuyện nhẹ nhàng, lôi cuốn. Qua đó, phim khẳng định thông điệp ý nghĩa: Tình thân, gia đình là điểm tựa duy nhất giúp cho mỗi người mạnh mẽ, lạc quan để đối diện và vượt qua nghịch cảnh.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Trung Dũng","avatar":""},{"name":"Thúy Ngân","avatar":""},{"name":"Ngọc Thuận","avatar":""},{"name":"NSƯT Minh Đức","avatar":""},{"name":"Lê Khánh","avatar":""},{"name":"Tường Vi","avatar":""},{"name":"Jun Phạm","avatar":""},{"name":"Song Luân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Gạo Nếp Gạo Tẻ"]', 1784690324335);
