INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gao-nep-gao-te-phan-2', 'Gạo Nếp Gạo Tẻ (Phần 2)', 'Sticky Rice And Plain Rice (Season 2)', 'gạo nếp gạo tẻ (phần 2) sticky rice and plain rice (season 2) trung dũng thúy ngân ngọc thuận nsưt minh đức lê khánh tường vi jun phạm song luân gạo nếp gạo tẻ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuong-le-cuu-thien', 'Phượng Lệ Cửu Thiên', 'Renascence', 'https://phimimg.com/upload/vod/20241112-1/e2289b0cfdd4cf634d7f9c0631df9f27.jpg', 'https://phimimg.com/upload/vod/20241112-1/1c173d292059058576286e6527026ab5.jpg', '<p>Diêu Mạc Uyển, một cô gái xinh đẹp, thông minh và quyết đoán. Mọi chuyện bắt đầu từ khi chị gái của Mạc Uyển là Mạc Tâm bị đế vương Dạ Hồng Dịch làm hại, cô tìm cách nhập cung nhằm trả thù. Ban đầu, vì chưa có bất cứ thứ gì trong tay nên Mạc Uyển hết sức thận trọng, cô tìm cách chia rẽ thế lực của 4 đại quý phi, cô lập Hồng Dịch, tìm một chỗ đứng vững chắc trong hoàng cung.

Mạc Uyển lần lượt kết bạn với Phong Dật Hàn, Yến Nam Sanh, Hàn Cẩm Y và Khải Thương Lan, cô trải qua không ít mối tình nhưng luôn tự nhủ là không được động lòng với bất cứ ai ngoài Dạ Quân Thanh. Vì 8 nước Trung Nguyên có giao ước liên minh nên cô lại phải lên đường tới 7 nước còn lại để thuyết phục họ ủng hộ, lật đổ Đại Sở. Cuối cùng, Mạc Uyển cũng có thể thể báo thù cho chị gái song sinh và có được giang sơn, nhưng nàng vẫn quyết định cùng Quân Thanh quy ẩn giang hồ.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Zheyuan","avatar":""},{"name":"Li Mozhi","avatar":""},{"name":"Yan Zidong","avatar":""},{"name":"Johnny Zhang","avatar":""},{"name":"Eva Cheng","avatar":""},{"name":"Zong Fengyan","avatar":""},{"name":"Wang Jinsong","avatar":""},{"name":"Wen Li","avatar":""},{"name":"Zhu Pengcheng","avatar":""},{"name":"Madina","avatar":""},{"name":"Wang Ruixin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Плач феникса, достигший девятого неба","Перерождение","凤唳九天"]', 1784690324335);
