INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-sao-boss-muon-cuoi-toi-2', 'Tại Sao Boss Muốn Cưới Tôi 2', 'Well Intended Love 2', 'https://phimimg.com/upload/vod/20241112-1/3678aadf469a02646be54827c2cb88dd.jpg', 'https://phimimg.com/upload/vod/20241112-1/b6aa76d9faa751e7c7f85b47afad1341.jpg', '<p>Để bảo vệ sự nghiệp yêu thích của mình, Hạ Lâm đã chung tay với Lăng Di Châu đính chính vụ bê bối, Lăng Dị Châu nói với Hạ Lâm răng hai người có thể ký hợp đồng đính hôn giả, đến tận khi tin tức xấu ngừng lại, thế nên hai người bắt đầu diễn vai người yêu của nhau. Sau khi diễn vai người yêu của nhau thì hai người nảy sinh hảo cảm với nhau, lúc tình cảm tăng tiến lại vấp phải trắc trở vì hiểu nhầm, Lăng Dị Châu và Hạ Lâm cùng nhau đối mặt, giải quyết hiểu nhầm, cuối cùng bày tỏ lòng mình, ngọt ngào kết hôn</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Khai Sính","avatar":""},{"name":"Dịch Bách Thần","avatar":""},{"name":"Vương Song","avatar":""},{"name":"Huang Qian Shuo","avatar":""},{"name":"Lợi Tình Thiên","avatar":""},{"name":"Ding Ning","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324335);
