INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tai-sao-boss-muon-cuoi-toi-2', 'Tại Sao Boss Muốn Cưới Tôi 2', 'Well Intended Love 2', 'tại sao boss muốn cưới tôi 2 well intended love 2 từ khai sính dịch bách thần vương song huang qian shuo lợi tình thiên ding ning ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-nho', 'Bác Sĩ Nhỏ', 'Little Doctor', 'https://phimimg.com/upload/vod/20241112-1/ea952cdd9b5a19944d62829bcd9eb32c.jpg', 'https://phimimg.com/upload/vod/20241112-1/e795a517a42bfd0778396347842cc2ff.jpg', '<p>Bác sỹ khoa sản Quách Tĩnh luôn thích nghiêm cứu, suy đoán, phân tích rõ ràng mọi việc, anh cũng là bác sỹ lâm sàng tuyến đầu ở bệnh viện. Anh chàng bác sỹ vùng ven bị lãnh đạo đánh giá là “chuyên gia bỏ bê công việc” này lại muốn theo đuổi cô nàng chủ nhiệm Hoàng Dung, người trẻ tuổi xinh đẹp nhất bệnh viện, còn từng giành được giấy khen cấp chính phủ. Lãnh đạo trực tiếp của Quách Tĩnh, chủ nhiệm Hoàng Thái Vân của khoa sản lại chính là chị gái của Hoàng Dung. Cô nhất quyết không muốn em gái lấy một người chồng như vậy, nên luôn ngăn cản, khó dễ Quách Tĩnh. Bản thân chỉ là một bác sỹ bé nhỏ, Quách Tĩnh luôn cẩn thận từng tí cả trong cuộc sống lẫn công việc, đã phát hiện ra khó khăn của Hoàng Dung, anh bèn không ngừng cố gắng và dẫn dắt, tận tâm bảo vệ, cuối cùng đã giúp Hoàng Dung có được cuộc sống vui vẻ hạnh phúc.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dong Zijian","avatar":""},{"name":"Zhang Jiani","avatar":""},{"name":"Liu Mintao","avatar":""},{"name":"Lee Lichun","avatar":""},{"name":"Wang Zhener","avatar":""},{"name":"Li Tai","avatar":""},{"name":"Qi Kui","avatar":""},{"name":"Fang Zibin","avatar":""},{"name":"Gao Ruifeier","avatar":""},{"name":"Wang Wanjuan","avatar":""},{"name":"Jiuyi Zhao","avatar":""},{"name":"Rain","avatar":""},{"name":"Chen Bing","avatar":""},{"name":"Liu Jie","avatar":""},{"name":"Wen Li","avatar":""},{"name":"Zhang Tonghuan","avatar":""},{"name":"Wenfei Dai","avatar":""},{"name":"Xintong Zheng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["小大夫 Little Doctor","Little Doctor","小大夫"]', 1784690324335);
