INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-si-nho', 'Bác Sĩ Nhỏ', 'Little Doctor', 'bác sĩ nhỏ little doctor dong zijian zhang jiani liu mintao lee lichun wang zhener li tai qi kui fang zibin gao ruifeier wang wanjuan jiuyi zhao rain chen bing liu jie wen li zhang tonghuan wenfei dai xintong zheng 小大夫 little doctor little doctor 小大夫', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-lan-ga-treu-gheo-long-quan', 'Ba Lần Gả Trêu Ghẹo Lòng Quân', 'Marry Me', 'https://phimimg.com/upload/vod/20241112-1/75437d9490543167d073d0e10b0f4ed3.jpg', 'https://phimimg.com/upload/vod/20241112-1/42ed68eab7d25957367294563b3c3930.jpg', '<p>Cuộc sống yên tĩnh của Cư Mộc Nhi bị thay đổi sau khi ông nội mất, cô bị mù. Trên đường đi đòi lại công bằng cho ông mình cô vô tình đụng phải nam nhân giàu nhất kinh thành. Để điều tra về cái chết của ông, cô buộc phải thoả thuận thành thân với Long Dược. Sống cùng nhau mỗi ngày, hai ngừơi dần nãy sinh tình cảm tốt đẹp. Mộc Nhi sau khi điều tra, không muốn cái chết của ông mình gây phiền phức cho Long gia. Cô đã tạo sự hiểu lầm và hưu thư phu quân. Sau khi Long Dược biết được tất cả sự thật hai người thành thân. Không bao lâu cuộc điều tra về cái chết của ông cô càng lấn sâu, rắc rối, và nguy hiểm. Cả Long gia bị huỷ hoại, đi vào tình cảnh vô cùng khốn khó. Hai người họ đồng tâm cùng nhau vượt qua. Sau mọi sóng gió sự thật được phơi bày mọi thứ ổn định. Mộc Nhi 1 lần nữa kết hôn với Long Dược. Cuối cùng cũng hạnh phúc viên mãn bên nhau cả đời.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xing Zhaolin","avatar":""},{"name":"Xiao Yan","avatar":""},{"name":"Herman Li He","avatar":""},{"name":"Liu Yitong","avatar":""},{"name":"Qiu Shi Lun","avatar":""},{"name":"Huang Yilin","avatar":""},{"name":"Nie Zihao","avatar":""},{"name":"Xinbo Li","avatar":""},{"name":"Liu Xiaoxiao","avatar":""},{"name":"Nicky Wu","avatar":""},{"name":"Zhang Ye Shi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '