INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nhau-di-thuc-mong-quan', 'Yêu Nhau Đi, Thực Mộng Quân', 'Poisoned Love', 'https://phimimg.com/upload/vod/20241112-1/1fd4f10a6c480825506c3ed68a92809c.jpg', 'https://phimimg.com/upload/vod/20241112-1/f190129f1eb9166d11edf9aadda9d84e.jpg', '<p>Một cô gái thiên tài trong lĩnh vực lồng tiếng phim nhưng lại mắc bệnh tâm lý. Cô tình cờ gặp được Thời Mạnh, một nhà sản xuất phim có thể giúp cô chữa khỏi bệnh, nhưng cô lại vô tình hiểu lầm người giúp mình là Thời Nhất, anh trai của Thời Mạnh. Những hiểu nhầm của họ cũng nảy sinh từ đó, nhưng cuối cùng họ đã cùng nhau giải quyết, tháo gỡ những khúc mắc và tạo nên một cái kết hạnh phúc cho câu chuyện tình lãng mạn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ao Ruipeng","avatar":""},{"name":"Ma Mengwei","avatar":""},{"name":"Shi Qingyan","avatar":""},{"name":"Luo Zheng","avatar":""},{"name":"Ma Dong Chen","avatar":""},{"name":"Wu Chengze","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Lian Ai Ba, Shi Meng Jun!","恋爱吧，食梦君！第一季","恋爱吧，食梦君！第二季","恋爱吧食梦君","戀愛吧，食夢君！","Fall in Love","恋爱吧，食梦君！"]', 1784690324335);
