INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-ga-y-nu', 'Thế Gả Y Nữ', 'For Married Doctress', 'https://phimimg.com/upload/vod/20241112-1/b7bc11ebcc84e3e8ac6fc7958bc948ea.jpg', 'https://phimimg.com/upload/vod/20241112-1/e051ff108e590e6303cbbbc39e000ec1.jpg', '<p>Được dựng từ tiểu thuyết cùng tên của tác giả Không Không. Nội dung kể về Liễu Tịnh – con gái thái phó Trần Quốc – bị ép phải giả mạo là công chúa để gả cho Hoàng Đế Chu Quốc Vũ Văn Ung. Hai người sau đó cùng nhau trải qua nhiều khó khăn, chống lại các âm mưu triều chính để hạnh phúc bên nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Angela Gong Mi","avatar":""},{"name":"Merxat","avatar":""},{"name":"Qiao Jing Wen","avatar":""},{"name":"Wang Wanzhong","avatar":""},{"name":"Wang Mian","avatar":""},{"name":"Zhang Yongbo","avatar":""},{"name":"Miao Jie","avatar":""},{"name":"Tang Guo-Zhong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["To marry a medical woman","替嫁医女"]', 1784690324335);
