INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-dang-tiec', 'Điều Đáng Tiếc', 'Daughters', 'https://phimimg.com/upload/vod/20241112-1/aa4a805e1ff17f3608717df3c50908d2.jpg', 'https://phimimg.com/upload/vod/20241112-1/6d0f57c82c7894d0db412c9976505ca7.jpg', '<p>Điều Đáng Tiếc kể về câu chuyện của bốn nữ sinh thiếu hụt tình thương. Trong khoảng thời gian đau khổ nhất, bọn họ dần bắt đầu trốn tránh hiện thực tàn nhẫn, bắt đầu dùng thuốc phiện, nhầm lẫn thuốc phiện thành giả dược cho tâm hồn. Nhưng một khi đã tiếp xúc thì thuốc phiện sẽ làm con người ta bị nghiện, không thể dứt ra. Cuối cùng, bọn họ chỉ có thể &quot;tiếc nuối&quot; cho khoảng thời gian thanh xuân tươi đẹp nhất đã qua của mình, chỉ có thể để lại bài học được đổi lấy bằng cả tính mạng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chicha Amatayakul","avatar":""},{"name":"Chayanit Chansangavej","avatar":""},{"name":"Praewpannarai Sansanapitayakorn","avatar":""},{"name":"Natouch Siripongthon","avatar":""},{"name":"Ploynarin Sornarin","avatar":""},{"name":"Ratchaneekorn Phanmanee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Daughters","เสียดาย","Siadai 2559","Siadai 2020","เสียดาย2559","เสียดาย2020"]', 1784690324335);
