INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-vuot-thoi-gian', 'Người Tình Vượt Thời Gian', 'Oh My Drama Lover', 'https://phimimg.com/upload/vod/20241112-1/3f210fd0183336bc1fd7569105c30bb5.jpg', 'https://phimimg.com/upload/vod/20241112-1/8989465e89a22f2768e79d85b09ef5ee.jpg', '<p>Nhà văn ngôn tình hạng ba Lý Xuân Hỷ (Gia Trạch đóng) đột nhiên bị tai nạn xe. Sau khi tỉnh dậy phát hiện mình trở thành Tiền Trăn Trăn (Châu Lệ Lam đóng). Cô ấy không chỉ bị mất trí nhớ mà còn hay bị chi phối bởi những lời bộc bạch khó hiểu, thực hiện những hành động như một &quot;trà xanh&quot; dụ dỗ ông chủ Âu Dương Thần (Lâu Minh đóng). Âu Dương Thần theo đuổi Tiền Trăn Trăn theo cách của một tổng tài bá đạo, nhưng chàng trợ lý nhỏ Lục Ly (Trương Mạnh đóng) dần dần chiếm vị trí quan trọng trong lòng Tiền Trăn Trăn. Thế nhưng một Lục Ly nhìn có vẻ rất đơn thuần lại mang trong mình hai thân phận...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Meng","avatar":""},{"name":"Zhu Lilan","avatar":""},{"name":"Jia Ze","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Love Beyond Time and Space","Oh My Drama Lover","超时空恋人"]', 1784690324335);
