INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-thien-kiem-than', 'Nghịch Thiên Kiếm Thần', 'The Fabulous Sword God', 'https://phimimg.com/upload/vod/20241112-1/98c3b6b62f96c3f230d006efba9bb653.jpg', 'https://phimimg.com/upload/vod/20241112-1/8480b0063a45c8f69cd5171a571f62a2.jpg', '<p>Lẽ trời mênh mông, kẻ mạnh vô địch. Thuật giả kim cổ đại, soi sáng xuống nghìn sông núi, bảo kiếm Viêm Thiên hủy diệt vũ trụ luân hồi, huyết mạch Tu La chôn vùi Chí Tôn vạn giới. Tần Nam kế thừa thiên mệnh, tu luyện đạo vô địch, bắt đầu con đường của một kẻ mạnh, đứng trên vô số thiên tài trên đời, dẫn đến tấm thân bất tử, xưng bá thiên hạ.</p>', 'Hoàn Tất (78/78)', 78, 'hoathinh', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Ni Yian Jian Shen","Nghịch Thiên Kiếm Thần","逆天剑神"]', 1784690324335);
