INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-hoa-ac-ma-hoa-cua-quy', 'Bông Hoa Ác Ma (Hoa Của Quỷ)', 'Flower of Evil', 'https://phimimg.com/upload/vod/20241111-1/e6e55e4d544b3217b54cc07b9e92124e.jpg', 'https://phimimg.com/upload/vod/20241111-1/4d998c331c5c6d8e81c8963716f46caf.jpg', '<p>Hoa Của Quỷ xoay quanh cuộc hôn nhân tưởng chừng hạnh phúc giữa người đàn ông bí ẩn có quá khứ đen tối Baek Hee Sung (Lee Jun Ki) - kẻ luôn tìm cách che giấu thân phận sát nhân của mình và người vợ là thám tử điều tra Cha Ji Won (Moon Chae Won). Mọi chuyện bắt đầu trở nên thú vị khi người vợ dần nhận ra chồng mình không phải là người đàn ông ngọt ngào như cô vẫn tưởng. Sẽ như thế nào nếu người đàn ông mà bạn yêu thương và tin tưởng suốt 14 năm trời hóa ra lại là một kẻ máu lạnh đáng sợ?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Joon-gi","avatar":""},{"name":"Moon Chae-won","avatar":""},{"name":"Jang Hee-jin","avatar":""},{"name":"Seo Hyun-woo","avatar":""},{"name":"Jung Seo-yeon","avatar":""},{"name":"Nam Kee-ae","avatar":""},{"name":"Son Jong-hak","avatar":""},{"name":"Jo Kyung-sook","avatar":""},{"name":"Choi Dae-hoon","avatar":""},{"name":"Choi Young-jun","avatar":""},{"name":"Kim Soo-oh","avatar":""},{"name":"Im Cheol-hyung","avatar":""},{"name":"Yang Hye-jin","avatar":""},{"name":"Ju Ye-eun","avatar":""},{"name":"Hong Seo-jun","avatar":""},{"name":"Park Hyun Joon","avatar":""},{"name":"Lim Na-young","avatar":""},{"name":"Jeong Taek-hyeo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["邪恶之花","