INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chao-me-tam-biet', 'Chào Mẹ, Tạm Biệt!', 'Hi Bye, Mama!', 'https://phimimg.com/upload/vod/20241110-1/706cfe16f003127a71df29aa599024ca.jpg', 'https://phimimg.com/upload/vod/20241110-1/8236bf3eca5424ca9ffda48d8a490108.jpg', '<p>Chào Mẹ, Tạm Biệt là bộ phim kể về cuộc đời của Cha Yoo Ri (Kim Tae Hee), một người phụ nữ hóa thành hồn ma sau khi qua đời 5 năm trước. Cô ra đi đột ngột, để lại nỗi xót thương trong lòng Jo Kang Hwa (Lee Kyu Hyung) và đứa con. Để có thể hồi sinh, Cha Yoo Ri phải thực hiện các thử thách trong vòng 49 ngày.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Tae-hee","avatar":""},{"name":"Lee Kyoo-hyung","avatar":""},{"name":"Go Bo-gyeol","avatar":""},{"name":"Shin Dong-mi","avatar":""},{"name":"Seo Woo-jin","avatar":""},{"name":"Lee Si-woo","avatar":""},{"name":"Oh Eui-sik","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"Kim Mi-kyeong","avatar":""},{"name":"Park Soo-young","avatar":""},{"name":"Kim Mi-su","avatar":""},{"name":"Yoon Sa-bong","avatar":""},{"name":"Ban Hyo-jung","avatar":""},{"name":"Bae Hae-seon","avatar":""},{"name":"Park Eun-hye","avatar":""},{"name":"Kim Dae-gon","avatar":""},{"name":"Han In-soo","avatar":""},{"name":"Kang Yeon-jung","avatar":""},{"name":"Kwon Eun-","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Uma Segunda Chance","你好 再见，妈妈！","再见妈妈","再見媽媽又再見","ハイバイ、ママ!","안녕 엄마","¡Hola y adiós, mamá!","Здравст