INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhap-mon-lich-su-phan-1', 'Nhập Môn Lịch Sử (Phần 1)', 'History 101 (Season 1)', 'https://phimimg.com/upload/vod/20241110-1/4aa891c9180a910904f0211661fd2537.jpg', 'https://phimimg.com/upload/vod/20241110-1/2b5f58d49d4eb7cb504741a2efc149e6.jpg', '<p>Đồ họa thông tin và những thước phim lưu trữ mang đến bài học lịch sử súc tích về các đột phá trong khoa học, phong trào xã hội và những khám phá làm thay đổi thế giới.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Natalie Silverman","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Historia: nivel 1","Historia 101","История 101","Введение в историю","ประวัติศาสตร์ 101","History 101"]', 1784690324335);
