INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-nguoi-viking-phan-3', 'Chuyện Người Viking (Phần 3)', 'Norsemen (Season 3)', 'https://phimimg.com/upload/vod/20241110-1/c5d33f56f5c82af15b0e9d92248a39b2.jpg', 'https://phimimg.com/upload/vod/20241110-1/0b8af14adb1fa1ffac6edc47776c4ca9.jpg', '<p>Xoay quanh phần tiền truyện của loạt phim, mùa này sẽ hé lộ nguồn gốc bất ngờ về sự tàn ác của Bá tước Varg và cuộc hứa hôn đầy ngượng ngùng giữa Orm và Froya.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 16, 2020, 'Vietsub', 'FHD', 'Na Uy', 0, '[{"name":"Kåre Conradi","avatar":""},{"name":"Silje Torp","avatar":""},{"name":"Nils Jørgen Kaalstad","avatar":""},{"name":"Marian Saastad Ottesen","avatar":""},{"name":"Trond Fausa Aurvåg","avatar":""},{"name":"Kristine Riis","avatar":""},{"name":"Jon Øigarden","avatar":""},{"name":"Henrik Mestad","avatar":""},{"name":"Øystein Martinsen","avatar":""},{"name":"Mikkel Bratt Silset","avatar":""},{"name":"Mads Jørgensen","avatar":""},{"name":"Nikis Theophilakis","avatar":""},{"name":"Stig Frode Henriksen","avatar":""},{"name":"Bjørn Myrene","avatar":""},{"name":"André E","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["挪威的维京人","Vikingane","אנשי הצפון","Norsemen"]', 1784690324335);
