INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-nguoi-viking-phan-3', 'Chuyện Người Viking (Phần 3)', 'Norsemen (Season 3)', 'chuyện người viking (phần 3) norsemen (season 3) kåre conradi silje torp nils jørgen kaalstad marian saastad ottesen trond fausa aurvåg kristine riis jon øigarden henrik mestad øystein martinsen mikkel bratt silset mads jørgensen nikis theophilakis stig frode henriksen bjørn myrene andré e 挪威的维京人 vikingane אנשי הצפון norsemen', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-da-thanh-cong-thu-hut-su-chu-y-cua-toi', 'Chị Đã Thành Công Thu Hút Sự Chú Ý Của Tôi', 'My Dear Lady', 'https://phimimg.com/upload/vod/20241108-1/7202f4040cd8e9730117160dcb13defb.jpg', 'https://phimimg.com/upload/vod/20241108-1/c36409cffafe9e6ac034ecbeec87f1d2.jpg', '<p>Nàng Trợ Lý Của Anh kể về Hà Tiểu Ninh, một cô gái xinh đẹp, đáng yêu nhưng có niềm đam mê mãnh liệt với nghề diễn viên lồng tiếng. Dù không qua đào tạo nhưng cô luôn khao khát được làm việc trong một công ty có thể thực hiện được nguyện vọng của mình. Hà Tiểu Ninh là &quot;fan cứng&quot; của Mạc Đại (Mặc Ngôn) - diễn viên lồng tiếng chuyên nghiệp cho các bộ phim nổi tiếng. Động lực giúp cô đến với nghề lồng tiếng cũng được “truyền cảm hứng” từ nam thần tượng mà cô luôn yêu mến, quý mến. Tiểu Ninh hiếm hoi gặp gỡ Bất Ngu, nhưng nàng không biết rằng hắn chính là &quot;đại nhân&quot; trong lòng nàng bấy lâu nay. Mối quan hệ thú vị này lên đến đỉnh điểm khi Tiểu Ninh bất ngờ trở thành đồng nghiệp với tư cách là trợ lý của vị đại sư người Macedonian “không nổi tiếng”.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Mengjie","avatar":""},{"name":"Liu Te","avatar":""},{"name":"Mi Lu","avatar":""},{"name":"Sky Li","avatar":""},{"name":"Yilia Yu","avatar":""},{"name":"Zhang Guan Sen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["My Dear Lady","你成功引起我的注意了"]', 1784690324335);
