INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chi-da-thanh-cong-thu-hut-su-chu-y-cua-toi', 'Chị Đã Thành Công Thu Hút Sự Chú Ý Của Tôi', 'My Dear Lady', 'chị đã thành công thu hút sự chú ý của tôi my dear lady jiang mengjie liu te mi lu sky li yilia yu zhang guan sen my dear lady 你成功引起我的注意了', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-trong-hanh-phuc', 'Câu Chuyện Trong Hạnh Phúc', 'Spring in Happiness', 'https://phimimg.com/upload/vod/20241108-1/9f5feafe5dcaa422f33a25400920dd8b.jpg', 'https://phimimg.com/upload/vod/20241108-1/3bc6c9e7868d6ad2b3578756b1934785.jpg', '<p>Năm 1978, Trần Ngõa Nhi, Ngô Tây Khải, Lý Khải Minh, Hồ Mỹ Hoa và Hứa Vệ Đông đều cùng nhau bước vào phòng thi tuyển sinh đại học. Nhưng khi kết quả được công bố, Trần Ngõa Nhi và Hồ Mỹ Hoa đã trượt, còn Lý Tường thì được nhận vào trường kế toán tài vụ và Hứa Vệ Đông thì vào trường quân sự. Cuộc sống và công việc của bọn họ khác nhau nên khiến họ ngày càng xa cách hơn. Do theo kịp được nhịp đập của thời đại, Lý Tường đã kiếm được món tiền đầu tiên trên thị trường và cuối cùng đã kết hôn với Trần Ngõa Nhi, nhưng sau đó Lý Tường vì hanh danh vọng nên đã bỏ rơi vợ con mình, Trần Ngõa Nhi đã nhiều lần chịu sự đả kích của cuộc sống nhưng cô chưa bao giờ chịu khuất phục và cuối cùng cô cũng thành lập được một công ty doanh nghiệp nổi tiếng. Hồ Mỹ Hoa, người đã rời quê hương để sang nước Mĩ, lại trở thành chuyên gia tài chính và quay trở về con phố nơi cô đã xa cách nhiều năm.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jerry Lee","avatar":""},{"name":"Su Qing","avatar":""},{"name":"Wang Xiaochen","avatar":""},{"name":"Che Xiao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["北京西城故事","幸福里的故事"]', 1784690324335);
