INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-chuyen-trong-hanh-phuc', 'Câu Chuyện Trong Hạnh Phúc', 'Spring in Happiness', 'câu chuyện trong hạnh phúc spring in happiness jerry lee su qing wang xiaochen che xiao 北京西城故事 幸福里的故事', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-duong-am-ap', 'Chặng Đường Ấm Áp', 'Always Warm', 'https://phimimg.com/upload/vod/20241108-1/3dc0d744f71ff567c7e4b8a9821a2b0b.jpg', 'https://phimimg.com/upload/vod/20241108-1/d20b4ebdd309e1325c75319c096fdda7.jpg', '<p>Họa sĩ Ôn Thiển, đã rất ngạc nhiên khi nhìn thấy Bạch Kỉ, ca sĩ chính của ban nhạc thường chú ở quán ba, nên cô đã mời anh ấy làm người mẫu cho mình, cô theo đuổi anh ráo riết nhưng lại liên tục bị từ chối. Ôn Thiển được cha cô nhờ đi đến tu viện ở thành đô để lấy một món đồ từ bộ sưu tập của mẹ cô và gửi nó về vương quốc Anh. Trong khi đang lấy một chiếc túi gấm được đính cẩm thạch, cô bất ngờ gặp Bạch Kỉ. Bạch Kỉ nhận ra Ôn Thiển chính là cô bé mà anh đã quen ở vương quốc Anh khi còn nhỏ, nhưng Ôn Thiển lại không nhớ ra anh. Hai người vô tình đụng phải nhau, một người bởi vì bị mất balo, không chứng minh thư, không tiền, không điện thoại. Còn người kia thì muốn trốn tránh sự theo đuổi của những người hâm mộ cuồng nhiệt, cả hai đã cùng nhau dấn thân vào hành trình &quot;Bảo vệ &quot;</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["一路向暖","Always.Warm","Yi Lu Xiang Nuan"]', 1784690324335);
INSERT OR IGNORE INTO movie_categories (movie_slug, category_slug) VALUES ('chang-duong-am-ap', 'tinh-cam');
