INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-tuoi-18', 'Trở Lại Tuổi 18', '18 Again', 'https://phimimg.com/upload/vod/20241108-1/abdd359b45848c90798c88af2efa42ba.jpg', 'https://phimimg.com/upload/vod/20241108-1/42bfa66fffec747c747a881ee6f682bb.jpg', '<p>Hong Dae Young (Lee Do Hyun) - một người đàn ông trung niên gặp trắc trở trong sự nghiệp cũng như hôn nhân. Trước đó, anh từng được mệnh danh là nam thần bóng rổ của trường trung học khi đang độ tuổi 18. Nhưng vì một lần lầm lỡ với cô bạn gái xinh đẹp Jung Da Jung (Kim Ha Neul), anh buộc phải từ bỏ giấc mơ trở thành thành viên của đội tuyển bóng rổ quốc gia để gánh vác trọng trách trụ cột của gia đình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Do-hyun","avatar":""},{"name":"Kim Ha-neul","avatar":""},{"name":"Yoon Sang-hyun","avatar":""},{"name":"Roh Jeong-eui","avatar":""},{"name":"Ryeoun","avatar":""},{"name":"Wi Ha-jun","avatar":""},{"name":"Kim Kang-hyun","avatar":""},{"name":"Lee Mi-do","avatar":""},{"name":"Han So-eun","avatar":""},{"name":"Choi Bo-min","avatar":""},{"name":"Hwang In-yeop","avatar":""},{"name":"Kim Yoo-ri","avatar":""},{"name":"Lee Ki-woo","avatar":""},{"name":"Ahn Nae-sang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["De Volta aos 18","Eitin Eogein","再次十八岁","Viutv 18 Again","回到18歲","에이틴 어게인","18 어게인","18 Again: ย้อนรัก ย้อนวัยฝัน","重返18歲","Eighteen Again","18 Again","Trở Lại Tuổi 18"]', 1784690324335);
