INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tro-lai-tuoi-18', 'Trở Lại Tuổi 18', '18 Again', 'trở lại tuổi 18 18 again lee do-hyun kim ha-neul yoon sang-hyun roh jeong-eui ryeoun wi ha-jun kim kang-hyun lee mi-do han so-eun choi bo-min hwang in-yeop kim yoo-ri lee ki-woo ahn nae-sang de volta aos 18 eitin eogein 再次十八岁 viutv 18 again 回到18歲 에이틴 어게인 18 어게인 18 again: ย้อนรัก ย้อนวัยฝัน 重返18歲 eighteen again 18 again trở lại tuổi 18', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-tam-trach', 'Thợ Săn Tâm Trạch', 'Psych-Hunter', 'https://phimimg.com/upload/vod/20241108-1/15e69fedd1eded630ca31813892e9f06.jpg', 'https://phimimg.com/upload/vod/20241108-1/192a092688bcb7ad078c781232b4a387.jpg', '<p>Hung trạch là một ngôi nhà từng có người chết bất đắc kỳ tử. Linh hồn người chết không tiêu tan, vậy nên hung trạch thường xảy ra những chuyện kỳ lạ. Giang Thước và Tần Nhất Hằng là một cặp đôi cò nhà đất bí ẩn, bọn họ bỏ một số tiền thấp để mua hung trạch nổi tiếng gần xa, sau khi trừ tà thì sẽ bán lại cho người khác. Thế nhưng gần đây bọn họ phát hiện ra là mình đã lọt vào một cái lưới nguy hiểm rình rập khắp nơi.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hou Minghao","avatar":""},{"name":"Liu Dongqin","avatar":""},{"name":"Zhu Xudan","avatar":""},{"name":"Chen Meilin","avatar":""},{"name":"Gao Sheng Hao","avatar":""},{"name":"Zhang Yang","avatar":""},{"name":"Wang Jia He","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Psych Hunter","Mind Hunter","ปริศนานักล่าพลังจิต","心宅猎人"]', 1784690324335);
