INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-hiep-hoac-nguyen-giap', 'Đại Hiệp Hoắc Nguyên Giáp', 'Heroes', 'https://phimimg.com/upload/vod/20241108-1/4a38930d8ebdff18cc1c820b70f60982.jpg', 'https://phimimg.com/upload/vod/20241108-1/449faef0bd3071a99e1fcb47704231c6.jpg', '<p>Đại Hiệp Hoắc Nguyên Giáp lấy bối cảnh thời nhà Thanh, nội dung phim xoay quanh cuộc đời của Hoắc Nguyên Giáp, người đã vùng võ thuật và sự tôn nghiêm của mình để vực dậy tinh thần yêu nước, chống giặc ngoại xâm cho nhân dân trung hoa. Khi đó, triều đình nhà Thanh hết sức nhu nhược, nhường toàn bộ quyền kiểm soát cho Nhật, người dân rơi vào hoàn cảnh khốn cùng, bị áp bức bóc lột và khinh thường. Không thể nhẫn nhịn được mãi, Hoắc Nguyên Giáp cùng đệ tử của mình đã chiến đấu bằng võ thuật, tinh thần và sự can đảm.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vincent Zhao Wenzhuo","avatar":""},{"name":"Mao Linlin","avatar":""},{"name":"Ashton Chen","avatar":""},{"name":"Wang Zhiyi","avatar":""},{"name":"Wu Chao","avatar":""},{"name":"Jia Hongwei","avatar":""},{"name":"Xu Zhengguo","avatar":""},{"name":"Ryan Kou","avatar":""},{"name":"Bingo Zhou","avatar":""},{"name":"Zhou Yujing Hao","avatar":""},{"name":"Ping Hui Tay","avatar":""},{"name":"Zhang Chunzhong","avatar":""},{"name":"Eddy Ko Hung","avatar":""},{"name":"Hasi Gaowa","avatar":""},{"name":"Zhang Jingyan","avatar":""},{"name":"Jiani Lu","avatar":""},{"name":"Volker Helfrich","avatar":""},{"name":"Zhao Junze","avatar":""},{"name":"Hei Zi","avatar":""},{"name":"Zha","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Hero Huo Yuan Jia","Helden 2020","Heroes 2020","大侠霍元甲"]', 1784690324335);
