INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-doc-than-dua-vao-thuc-luc', 'Tôi Độc Thân Dựa Vào Thực Lực', 'Professional Single', 'https://phimimg.com/upload/vod/20241106-1/8643761934b3ef1c9e17e4201b19ec98.jpg', 'https://phimimg.com/upload/vod/20241106-1/340ddf46cee92ba7a535d338cdd6c78b.jpg', '<p>Bối cảnh của câu chuyện xoay quanh hai người bạn học cũ Tần Thâm và Nguyên Tiên, nay cùng nhau trở thành sinh viên trường đại học nghệ thuật với mong muốn trở thành nhà điêu khắc. Trên con đường theo đuổi lý tưởng nghệ thuật, đối mặt với muôn vàn khó khăn, cuối cùng họ nhận lại được tình yêu và tình bạn, tiến gần tới ước mơ của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ireine Song","avatar":""},{"name":"Aaron Deng","avatar":""},{"name":"He Zeyuan","avatar":""},{"name":"Chen Kefan","avatar":""},{"name":"Cui Liya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["我凭本事单身","Wo ping ben shi dan shen","Professional Single","I am single out of my own ability","I''m Single by Skill","I''m Single"]', 1784690324335);
