INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-ban-thanh-lich', 'Những Người Bạn Thanh Lịch', 'Graceful Friends', 'https://phimimg.com/upload/vod/20241106-1/d0effa40cf6c0d87f47ad067ed3d53e1.jpg', 'https://phimimg.com/upload/vod/20241106-1/1e161ddaa52c1b108756ec39b21bea07.jpg', '<p>Một nhóm các cặp vợ chồng ở độ tuổi 40 sống ở một thành phố mới. Một trong những cặp đôi đó là Ahn Goong-Cheol và Nam Jung-Hae. Họ tận hưởng những ngày bình yên và bình thường, nhưng, một vụ giết người xảy ra. Kể từ đó, những ngày bình yên của họ bị xáo trộn.</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yu Jun-sang","avatar":""},{"name":"Song Yun-ah","avatar":""},{"name":"Kim Sung-oh","avatar":""},{"name":"Bae Soo-bin","avatar":""},{"name":"Han Da-gam","avatar":""},{"name":"Kim Hye-eun","avatar":""},{"name":"Jeong Seok-yong","avatar":""},{"name":"Kim Ji-young","avatar":""},{"name":"Kim Ji-sung","avatar":""},{"name":"Park Sung-jun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Elegant Friends","우아한 친구들"]', 1784690324335);
