INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-den-sang-to', 'Trắng Đen Sáng Tỏ', 'The Penalty Zone', 'https://phimimg.com/upload/vod/20241106-1/4daa1aadb01dffc329c317817decf98a.jpg', 'https://phimimg.com/upload/vod/20241106-1/e4d0ff7609686bb58859eaee21420319.jpg', '<p>Kiềm Thiên Lôi, Hùng Quốc Lương, Dương Hiểu Luy đã từng là bộ ba của Học viện Cảnh sát. Kiềm Thiên Lôi vì giúp Dương Hiểu Luy không bị trừ điểm vì vụ việc đánh người khác bị thương đã rời khỏi Học viện Cảnh sát. Nhưng sau đó anh lại bị lôi kéo vào tập đoàn Caesars và trở thành gián điệp tại đây. Trong lúc thi hành nhiệm vụ, do ảnh hưởng của bom nổ anh đã hôn mê suốt 8 năm và mất trí nhớ. Cuối cùng, nhờ những cố gắng của cảnh sát, băng đảng tội phạm của tập đoàn Caesars và tập đoàn nhà họ Đàm đều đã sa lưới.</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gu Yuhan","avatar":""},{"name":"Liu Xiao Jie","avatar":""},{"name":"Ou Hao","avatar":""},{"name":"Xu Hong Hao","avatar":""},{"name":"Li Naiwen","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["黑白禁区","The Penalty Zone"]', 1784690324335);
