INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-cua-toi-la-gian-diep', 'Người Yêu Của Tôi Là Gián Điệp', 'The Spies Who Loved Me', 'https://phimimg.com/upload/vod/20241106-1/303f878f7f610330a2f505dd529017b1.jpg', 'https://phimimg.com/upload/vod/20241106-1/5cc3e505723cb692f88731c3c424ed59.jpg', '<p>Người Yêu Gián Điệp Của Tôi là một bộ phim hài lãng mạn xoay quanh một người phụ nữ vô tình bị cuốn vào thế giới gián điệp. Trong phim, Yoo In Na sẽ đóng vai chính Kang Ah Reum, một nhà thiết kế váy cưới đã kết hôn hai lần, với hai người chồng cả hai đều có nhiều bí mật. Trong đó, Eric sẽ đóng vai người chồng đầu tiên của Kang Ah Reum, Jun Ji Hoon, một điệp viên bí mật với tính cách quyến rũ và khó đoán, làm việc cho Interpol. Trong khi đó, Im Joo Hwan sẽ vào vai người chồng thứ hai của Kang Ah Reum, Derek Hyun, một điệp viên tư vô cùng thông minh với khả năng cạnh tranh mạnh mẽ.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo In-na","avatar":""},{"name":"Eric Mun","avatar":""},{"name":"Lim Ju-hwan","avatar":""},{"name":"Kim Tae-woo","avatar":""},{"name":"Jeong Seok-yong","avatar":""},{"name":"Cha Joo-young","avatar":""},{"name":"Park So-jin","avatar":""},{"name":"Bae In-hyuk","avatar":""},{"name":"Oh Kyung-joo","avatar":""},{"name":"Ian H.W. Kim","avatar":""},{"name":"Kim So-min","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Spy Who Loves Me","The Spy Who Loved Me","나를 사랑한 스파이"]', 1784690324335);
