INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doc-ky-uc', 'Người Đọc Ký Ức', 'Memorist', 'https://phimimg.com/upload/vod/20241104-1/50069a16e9cd4bb9c299073337373750.jpg', 'https://phimimg.com/upload/vod/20241104-1/330fa99c0de8a91d0e61fa9693e1e2dc.jpg', '<p>Kể về Dong Baek khi còn là học sinh trung học, anh đột nhiên có được một sức mạnh siêu nhiên. Bất cứ khi nào anh chạm vào ai đó, anh có thể đọc được ký ức của người đó. Dong Baek tiết lộ khả năng đọc trí nhớ của mình với mọi người và anh trở thành một thám tử. Anh ta cố gắng để bắt càng nhiều tội phạm càng tốt. Anh đã gặp một vụ án giết người hàng loạt bí ẩn.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Seung Ho","avatar":""},{"name":"Lee Se Young","avatar":""},{"name":"Jo Sung Ha","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Memorist","메모리스트"]', 1784690324335);
