INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-nuong-tu-nha-tuong-quan', 'Tiểu Nương Tử Nhà Tướng Quân', 'General''s Lady', 'https://phimimg.com/upload/vod/20241104-1/f574f4e3e4203d38e1aefc33b0c54703.jpg', 'https://phimimg.com/upload/vod/20241104-1/1a5450a720498e58f95870db2d10cde1.jpg', '<p>Tiểu Nương Tử Nhà Tướng Quân kể về cô nàng tiểu thư vương phủ Thẩm Cẩm từ bé đã được nuông chiều bảo bọc trong phủ, nhưng lại bị hoàng thượng ban hôn đến tận biên ải xa xôi. Phu quân của nàng là đại tướng quân Sở Tu Minh, người khiến nàng phải lòng vị tướng quân này từ cái nhìn đầu tiên. Tuy nhiên, cuộc sống mới nơi biên ải không đơn giản, hơn nữa hoàng thượng lại bắt đầu nảy sinh lòng nghi ngờ với Sở gia. Chuyện tình yêu của Thẩm Cẩm và Sở Tu cũng vì thế mà trải qua muôn vàn gian khó.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thang Mẫn","avatar":""},{"name":"Ngô Hi Trạch","avatar":""},{"name":"Tào Tuấn Tường","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["将军家的小娘子","Jiang Jun Jia De Xiao Niang Zi","將軍家的小娘子","General''s.Lady"]', 1784690324335);
