INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-cua-quy', 'Mắt Của Quỷ', 'Devil''s Eye', 'https://phimimg.com/upload/vod/20241104-1/0e1955bfae264dbfe8bc684a22059513.jpg', 'https://phimimg.com/upload/vod/20241104-1/70aaee9be46d786a01300e9aef693fd1.jpg', '<p>Đau đớn khi đứa con gái duy nhất mà Ngọc hết mực yêu thương mất do một tai nạn bất thường khi mới 10 tuổi. Ngọc cầu cứu pháp sư để được gặp đứa con gái vừa chết của mình. Cô chấp nhận trả bằng mọi giá, kể cả bằng máu và một phần cơ thể của mình cho đến khi cô phát hiện ra một sự thật kinh hoàng.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Diệp Bảo Ngọc","avatar":""},{"name":"La Thành","avatar":""},{"name":"Hữu Vi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Ice Adonis","Lửa Hận Tình Thù","노란 복수초"]', 1784690324335);
