INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-ngan-do-phan-1', 'Gái Ngàn Đô (Phần 1)', 'Thousand Dollar Girl (Season 1)', 'https://phimimg.com/upload/vod/20241104-1/23d03162c7040faea47ee7d0d66f998f.jpg', 'https://phimimg.com/upload/vod/20241104-1/30a1d87e388ac1373961859ce1ad5e25.jpg', '<p>Gái ngàn đô là dự án đi sâu vào việc bóc trần những bí mật “thâm cung bí sử” giúp cho &quot;thế giới&quot; mại dâm cao cấp tồn tại. Những cô “gái ngành” cao cấp phải học ngón nghề gì, họ được ăn chia ra sao, bị trừng phạt thế nào khi vi phạm luật chơi? Quyền lực kinh khủng của tú ông cao cấp? Cuộc chiến giành giật thị trường giữa những ông trùm?... Tất cả sẽ được hé lộ trong phim. Đằng sau những cuộc chơi hào nhoáng là cả một đường dây chằng chịt của giới xã hội đen và số phận bi thảm của các cô gái ngành được từ từ hé lộ một cách kịch tính.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Quỳnh Lương","avatar":""},{"name":"Đinh Ngọc Anh","avatar":""},{"name":"Lương Ánh Ngọc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gái Ngàn Đô"]', 1784690324335);
