INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mien-dat-hua-2020', 'Miền Đất Hứa', 'The Promised Neverland', 'https://phimimg.com/upload/vod/20241102-1/10905bd71f07511c264d6d8879a7afd5.jpg', 'https://phimimg.com/upload/vod/20241102-1/4bad147352fc5d2ecc9e672052e3806a.jpg', '<p>Miền Đất Hứa – Yakusoku no Neverland / The Promised Neverland (2020) Emma sống tại một trại trẻ mồ côi với những đứa trẻ mồ côi khác, bao gồm Norman và Ray. Cô bé thích thời gian ở đó với Isabella, người chăm sóc những đứa trẻ mồ côi như một người Mẹ, nhưng Emma và Norman tình cờ tìm hiểu bí mật đen tối của trại trẻ mồ côi. Bí mật là những đứa trẻ mồ côi được nuôi dưỡng để bị giết làm thức ăn cho loài quỷ. Emma và Norman cùng với Ray quyết định cùng nhau tìm cách đưa bọn trẻ trốn khỏi nơi đó. Nhưng kế hoạch của bọn trẻ dường như đã bị Mẹ phát hiện…</p>', 'Full', 1, 'single', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"浜辺美波","avatar":""},{"name":"Kairi Jo","avatar":""},{"name":"板垣李光人","avatar":""},{"name":"北川景子","avatar":""},{"name":"渡辺直美","avatar":""},{"name":"Miyu Andô","avatar":""},{"name":"Halo Asada","avatar":""},{"name":"Soma Santoki","avatar":""},{"name":"Yurito Mori","avatar":""},{"name":"出口夏希","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Promised Neverland","Yakusoku no Neverland","約束のネバーランド"]', 1784690324335);
