INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oanh-oanh-tuc-ngu-diec-nan-cau', 'Oanh Oanh Túc Ngữ Diệc Nan Cầu', 'Su Yu', 'https://phimimg.com/upload/vod/20241101-1/5de877fe060b4ac321b62602c5a000bc.jpg', 'https://phimimg.com/upload/vod/20241101-1/0a89268dc9ae6dd270e8c8c5645a51ff.jpg', '<p>Thiếu trang chủ Mộ Tuyệt Trần (Quách Tuấn Thần đóng) của Thiên Uẩn sơn trang (Động chủ thích bánh quế hoa) và trợ thủ đắc lực Thiên Ngữ (Lý Nặc). Thiếu trang chủ Mộ Tuyệt Trần là người tài giỏi xuất chúng, không chỉ có tài năng siêu phàm, mà còn có lòng hiệp nghĩa, cố gắng giữ được hòa khí trong giang hồ, trở thành anh hùng trong lòng bách tính, được coi là nam nhân hoàn mỹ.

Thiên Ngữ thấu tình đạt lý thông tuệ hơn người, quản lý Mộ Tuyệt Trần và mọi chuyện lớn nhỏ trong Thiên Uẩn sơn trang, ổn thỏa khéo léo, chưa bao giờ có chút sai sót nào. Trong lòng mọi người, hai người họ là trai tài gái sắc, trời đất tác thành, nhưng đáng tiếc Thiên Ngữ là đứa trẻ lưu lạc được lão trang chủ thu nhận, thân phận kém xa Mộ Tuyệt Trần, không thể yêu nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guo Junchen","avatar":""},{"name":"李诺","avatar":""},{"name":"Wu Ze Nan","avatar":""},{"name":"阳兵卓","avatar":""},{"name":"Yang Yun Zhuo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["萦萦夙语亦难求"]', 1784690324335);
