INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-sat-trong-vuon-nho', 'Truy Sát Trong Vườn Nho', 'Murder In The Vineyard', 'https://phimimg.com/upload/vod/20241031-1/8ab36308145313424911ec247016f5cb.jpg', 'https://phimimg.com/upload/vod/20241031-1/d97f0181e091e78259275494a4501e1a.jpg', '<p>Hai mẹ con Emma và Beatrice chuyển đến một thị trấn nhỏ để Emma tiếp quản nhà máy rượu của gia đình. Môi trường sống xa lạ khiến Beatrice phải vật lộn để hòa nhập với ngôi trường mới. Thật không may, cô bé lại bị bắt nạt trong trường và Emma phải cố gắng hết sức để bảo vệ con gái khỏi những nguy hiểm đang rình rập.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Helena Mattsson","avatar":""},{"name":"Emma Fuhrmann","avatar":""},{"name":"Daniel Brunnemer Hall","avatar":""},{"name":"Matthew Erick White","avatar":""},{"name":"Daniel Covin","avatar":""},{"name":"Kimberly Dooley","avatar":""},{"name":"Katie Kelly","avatar":""},{"name":"Randy Vasquez","avatar":""},{"name":"Joanne Baron","avatar":""},{"name":"Jon Root","avatar":""},{"name":"Sarah Pierce","avatar":""},{"name":"Mariah Wesley","avatar":""},{"name":"Ginette Rhodes","avatar":""},{"name":"Blake Boyd","avatar":""},{"name":"McKenna Slone","avatar":""},{"name":"Jaida - Iman Benjamin","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Asesinato en el valle","La nuova arrivata","Murder in the Vineyard"]', 1784690324335);
