INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-bi', 'Mỹ Nhân Bì', 'The Beauty Skin', 'https://phimimg.com/upload/vod/20231101-1/d1aff45197620b89cfdefa8ef2e8fd7a.jpg', 'https://phimimg.com/upload/vod/20231101-1/cb406b4815e0a4241fb5c800346494bd.jpg', '<p>Mỹ Nhân Bì -(Vỏ bọc mỹ nhân) chuyển thể từ Liêu trai mỹ nhân bì - Liên Thành của Bồ Tùng Linh, Trong kinh thành có 2 đại Sử gia, luôn luôn tranh đấu. Sử Hiếu Liêm gia có cô con gái tên Liên Thành (Trương Dư Hi). Cùng con gái Sử Thái Thủ gia - Tân Nương, cũng trở thành một cặp oan gia cái gì cũng đối đầu nhau Trong một lần tình cờ, cả hai nàng cùng gặp được một chàng thư sinh tên Kiều Sinh (Hàn Đống). Kiều Sinh tài nghệ xuất chúng, tâm địa lương thiện khiến cả hai đều thầm thương trộm nhớ. Kiều Sinh vừa yêu thích bản tính dịu dàng của Liên Thành, vừa ngưỡng mộ sự lanh lợi, cởi mở của Tân Nương. Nhưng chàng không thể cùng lúc lấy cả hai làm vợ, bản thân bị rơi vào thế tiến thoái lưỡng nan. Lúc đó, con trai Cự Giả - Vương Hóa Thành cũng muốn lấy Liên Thành làm vợ.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub + Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Han Dong","avatar":""},{"name":"Zhang Yuxi","avatar":""},{"name":"Carrie Wang","avatar":""},{"name":"Li Ruotian","avatar":""},{"name":"Xiao Xiangfei","avatar":""},{"name":"Tao Huimin","avatar":""},{"name":"Wen Haibo","avatar":""},{"name":"Man Ningxi","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324335);
