INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-chung-thep-phan-4', 'Bằng Chứng Thép (Phần 4)', 'Forensic Heroes (Season 4)', 'https://phimimg.com/upload/vod/20241029-1/b9d2d1b5eb60802779fe7c82021333c0.jpg', 'https://phimimg.com/upload/vod/20241029-1/d4cfe3d824f4acfbd130e47949873417.jpg', '<p>Với kiến thức pháp chứng, pháp y sâu rộng cùng phong thái phá án chuyên nghiệp, “Bằng chứng thép IV” tiếp tục kế thừa tinh thần của các phần trước, phanh phui chân tướng của những tội ác gây chấn động lòng người.Khu vực Tây Cửu Long thường xuyên xảy ra những vụ án mạng nghiêm trọng, đầy bí ẩn. Hung thủ dù tinh vi đến đâu, vẫn bị lôi ra ánh sáng bởi những nhân viên điều tra tài ba.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2020, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Lý Thi Vận","avatar":""},{"name":"Đàm Tuấn Ngạn","avatar":""},{"name":"Huỳnh Hạo Nhiên","avatar":""},{"name":"Chu Thần Lệ","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Forensic.Heroes.4","法证先锋4","法證先鋒IV","法證先鋒4","Forensic Heroes 4"]', 1784690324335);
