INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trang-lam-me', 'Hành Trang Làm Mẹ', 'Mother To Be', 'https://phimimg.com/upload/vod/20241029-1/431730ef204001fe738707918fc78e49.jpg', 'https://phimimg.com/upload/vod/20241029-1/43b618fd0cfa7b511fa085a09fabf6b0.jpg', '<p>Một chuyên gia tư vấn hiếm muộn vừa kết hôn lại gặp phải vấn đề sinh nở, một nữ doanh nhân 34 tuổi quyết định đông lạnh trứng sau một cơn bệnh nặng, một nàng dâu gả vào hào môn nhưng mãi vẫn chưa sinh con. Ba người phụ nữ, ba hoàn cảnh khác nhau, nhưng tất cả đều phải trăn trở với chuyện con cái, một trong những vấn đề quan trọng nhất trong đời người phụ nữ.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 11, 2020, 'Thuyết Minh', 'FHD', 'Đài Loan', 0, '[{"name":"郭書瑤","avatar":""},{"name":"Bruce He","avatar":""},{"name":"劉品言","avatar":""},{"name":"Umin Boya","avatar":""},{"name":"Chris Lee","avatar":""},{"name":"Ning Chang","avatar":""},{"name":"夏騰宏","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["未來媽媽"]', 1784690324335);
