INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-dat-do-mat-roi', 'Trái Đất Đỏ Mặt Rồi', 'My Lonely Planet', 'https://phimimg.com/upload/vod/20241029-1/3e032a913af00eb4a6326c012abccef8.jpg', 'https://phimimg.com/upload/vod/20241029-1/49c83501e2342254d4cf2b34c2529264.jpg', '<p>Câu chuyện kể về Miêu Vũ - tổng tài quê mùa một cục, không thể bá đạo nổi và nhà thiết kế lạnh lùng không bước chân được vào giới thời trang – Uông Thần. Hai người họ bị một ngôi sao chổi nhắm trúng và ép duyên ở bên nhau. Một khi bọn họ cảm thấy không vui sẽ tráo đổi linh hồn với thú cưng của đối phương.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Lingyi","avatar":""},{"name":"Li Shuting","avatar":""},{"name":"李歡","avatar":""},{"name":"Liang Guodong","avatar":""},{"name":"楊仕澤","avatar":""},{"name":"Xu Kaixin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["地球脸红了"]', 1784690324335);
