INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-bong-toi', 'Sau Bóng Tối', 'After Dark', 'https://phimimg.com/upload/vod/20241026-1/f209a3352da8576c234e22180079b8b2.jpg', 'https://phimimg.com/upload/vod/20241026-1/69344312caf328aece2926df3175af4f.jpg', '<p>Khi con người bộc lộ mặt tối của mình. Đã đến lúc bóng tối bao trùm. Đến từ bốn câu chuyện kinh dị phản ánh linh hồn đen tối của con người và cái kết kinh hoàng mà họ phải đối mặt: &quot;Mạng ảo - Blind date&quot;: Pink - một cô nàng nghiện ứng dụng hẹn hò, gặp Q - một anh chàng đẹp trai bí ẩn. Họ có một mối liên hệ sâu sắc dẫn đến việc Pink có một cái thai kỳ lạ, ám ảnh cô đến tận cùng. &quot;Khúc cầu hồn của thanh xuân&quot;: Lada là một y tá trẻ được thuê với số tiền lớn để chăm sóc một bệnh nhân liệt giường - công chúa Srisaang. Nỗi kinh hoàng của cô thức giấc khi bệnh nhân của cô có tình trạng tốt lên một cách bất thường, và khiến cô phải đối mặt với hàng loạt các sự kiện kỳ dị. &quot;Channel chết chóc&quot;: Off và Boat, một người là Youtuber nổi tiếng, một người là thần tượng, họ hợp tác với nhau để tạo ra một kênh hoạt động siêu nhiên được bảo trợ bởi những người dùng ẩn danh, họ không bao giờ biết điều gì đang chờ đợi mình. &quot;Hố tử thần&quot;: Người đàn ông quyến rũ Chai là chuyên gia tình một đêm, với hy vọng ghi lại những cuốn băng sex để kiếm tiền. Rồi anh ta gặp Dao - một người cô gái quyến rũ. Anh ta lại tiếp tục những hành vi xảo quyệt của mình, nhưng lần này lại không hề dễ dàng như trước.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Benjamin Joseph Varney","avatar":""},{"name":"Piglet (Charada Imraporn)","avatar":""},{"name":"Jane (Ramida Jiranorraphat)","avatar":""},{"name":"Nat Kitcharit","avatar":""},{"name":"Kanyaphak Pongsak","avatar":""},{"name":"Napath Vikairungroj","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sundown Time","After Dark: The Series","อาทิตย์อัสดง"]', 1784690324335);
