INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-mai-yeu-anh', 'Mãi Mãi Yêu Anh', 'An Incurable Case Of Love', 'https://phimimg.com/upload/vod/20241026-1/f702ed72bc54541677baadc13c96f3e4.jpg', 'https://phimimg.com/upload/vod/20241026-1/3c2e570f2972fa005ebfb31d966f0b9a.jpg', '<p>Sakura Nanase là một y tá tân binh 22 tuổi. Cô vô tình gặp bác sĩ Tendou Kairi vài năm trước và yêu anh từ cái nhìn đầu tiên. Để có thể gặp lại anh, cô học hành chăm chỉ và thi tuyển trở thành y tá. Sau 5 năm, cuối cùng cô cũng gặp lại Tendou Kairi, nhưng anh chàng lại có một tính cách hoàn toàn khác so với những gì cô tưởng tượng. Tendou Kairi, 33 tuổi, và được đồng nghiệp đặt biệt danh là &quot;Ma Vương&quot;. Anh là một người cầu toàn và luôn đưa ra những nhận xét “khó-mà-chịu-đựng-được&quot; cho các bác sĩ và y tá. Sakura Nanase làm việc chăm chỉ để nhận được sự công nhận từ Tendou Kairi và bày tỏ tình cảm của mình. Ai ngờ bị anh phũ ngay lần đầu tiên. Sakura Nanase vẫn kiến trì theo đuổi và trở nên nổi tiếng tại bệnh viện với biệt danh &quot;Dũng Sĩ&quot;. Liệu cô nàng có &quot;đánh bại&quot; được chàng bác sĩ Ma Vương hay không?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"上白石萌音","avatar":""},{"name":"佐藤健","avatar":""},{"name":"香里奈","avatar":""},{"name":"毎熊克哉","avatar":""},{"name":"片瀬那奈","avatar":""},{"name":"渡邊圭祐","avatar":""},{"name":"吉川愛","avatar":""},{"name":"山本耕史","avatar":""},{"name":"堀田真由","avatar":""},{"name":"蓮佛美沙子","avatar":""},{"name":"平岩紙","avatar":""},{"name":"Miki Kousei","avatar":""},{"name":"瀧内公美","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["恋无止境","Koi Wa Tsuzuku Yo Dokomademo","Koiwa Tsuzuku Yo Dokomademo","恋はつづくよどこまでも","Koi wa Tsuzuku yo Doko Made mo","恋爱可以持续到天长地久","An Incurable Case of Love"]', 1784690324335);
