INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mai-mai-yeu-anh', 'Mãi Mãi Yêu Anh', 'An Incurable Case Of Love', 'mãi mãi yêu anh an incurable case of love 上白石萌音 佐藤健 香里奈 毎熊克哉 片瀬那奈 渡邊圭祐 吉川愛 山本耕史 堀田真由 蓮佛美沙子 平岩紙 miki kousei 瀧内公美 恋无止境 koi wa tsuzuku yo dokomademo koiwa tsuzuku yo dokomademo 恋はつづくよどこまでも koi wa tsuzuku yo doko made mo 恋爱可以持续到天长地久 an incurable case of love', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-tham-anh-xa', 'Yêu Thầm Anh Xã', 'My Husband In Law', 'https://phimimg.com/upload/vod/20241024-1/60fa5e956b407724acbdb13764d7eb04.jpg', 'https://phimimg.com/upload/vod/20241024-1/17995bcd8c39d29a5c1688fc85a09141.jpg', '<p>Muey yêu thầm Thien từ khi còn học phổ thông nên đã tìm mọi cách xuất hiện bên anh, thậm chí làm “gián điệp” cho mẹ Thien. Việc này khiến Thien xem Muey là cái gai trong mắt. Sau một lần “lầm lỡ” tai hại, Thien buộc phải nghe lời mẹ, đồng ý cưới Muey. Từ đây biết bao rắc rối xảy ra khiến cặp đôi oan gia này xích lại gần nhau hơn.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 18, 2020, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Mark Prin Suparat","avatar":""},{"name":"Mew Nittha Jirayungyurn","avatar":""},{"name":"Jeab Lalana Kongtoranin","avatar":""},{"name":"Koy Rachwin Wongviriya","avatar":""},{"name":"Ohm Kanin Stanley","avatar":""},{"name":"Nut Devahastin Na Ayutthaya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ok Keub Hak Ab Ruk Khun Samee","Heart Almost Broken, Secretly in Love with My Husband","My Husband In Law","อกเกือบหักแอบรักคุณสามี"]', 1784690324335);
