INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yeu-tham-anh-xa', 'Yêu Thầm Anh Xã', 'My Husband In Law', 'yêu thầm anh xã my husband in law mark prin suparat mew nittha jirayungyurn jeab lalana kongtoranin koy rachwin wongviriya ohm kanin stanley nut devahastin na ayutthaya ok keub hak ab ruk khun samee heart almost broken, secretly in love with my husband my husband in law อกเกือบหักแอบรักคุณสามี', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-ay-khong-yeu-ban-den-the', 'Anh Ấy Không Yêu Bạn Đến Thế', 'Love Yourself', 'https://phimimg.com/upload/vod/20241024-1/cad9237044178410ceecdf8794a7c3f4.jpg', 'https://phimimg.com/upload/vod/20241024-1/7dd158d7638b729bd87d7753054b371e.jpg', '<p>Nội dung tác phẩm xoay quanh câu chuyện tình yêu, tình bạn và khao khát trong cuộc sống của bốn người phụ nữ đã ngoài 30 tuổi.

Nhà sản xuất Tôn Nghệ Hà, chủ phòng tập thể hình Karen, người đại diện thực tập sinh Đinh Đinh và phó tổng giám đốc công ty DMA Nhậm Nhiễm đều là những người tài năng, xinh đẹp và có tính cách khác nhau, nhưng họ vẫn trên con đường tìm kiếm hạnh phúc thực sự của mình. Không như lúc còn trẻ, hiện tại tất cả đều có sự nghiệp và tiền bạc, thứ họ còn thiếu là sự đồng điệu về tâm hồn. Mỗi người đều được trải qua thử thách về tình yêu và tình bạn, liệu họ có thể vượt qua tất cả để có được hạnh phúc trọn vẹn.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 4, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Thiến","avatar":""},{"name":"Trương Giai Ninh","avatar":""},{"name":"Lý Thuần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ta Qi Shi Mei You Na Me Ai Ni","Love By Yourself","Love In Shanghai","He Doesn’t Love You That Much","他其实没有那么爱你"]', 1784690324335);
