INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('anh-ay-khong-yeu-ban-den-the', 'Anh Ấy Không Yêu Bạn Đến Thế', 'Love Yourself', 'anh ấy không yêu bạn đến thế love yourself tống thiến trương giai ninh lý thuần ta qi shi mei you na me ai ni love by yourself love in shanghai he doesn’t love you that much 他其实没有那么爱你', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-yen-lang-chet-nguoi-2020', 'Sự Yên Lặng Chết Người', 'H.U.S.H.', 'https://phimimg.com/upload/vod/20241021-1/a403f0717db247fe99961d6cdc3ed3d6.jpg', 'https://phimimg.com/upload/vod/20241021-1/7acec99b787a6d3344dbbd4db64131f3.jpg', '<p>Sự Yên Lặng Chết Người chuyển thể từ cuốn tiểu thuyết “Sự yên lặng chết người”, kể về hành trình lựa chọn giữa lương tâm và sinh mạng. Đây là một bộ phim công sở nói lên tiếng lòng của dân văn phòng về những mặt xấu xí của lòng người. Im Yoon Ah vào vai một nữ phóng viên thực tập ngay thẳng, nhiệt tình dũng cảm, có gì nói đấy, từng bước trưởng thành, trở thành một phóng viên xuất sắc dưới sự dẫn dắt của Hwang Jung Min. Vai diễn của Hwang Jung Min là một phóng viên lão làng, nhưng lại bị gánh nặng từ cả chồng, cha lẫn cấp dưới khiến cô không thể không thỏa hiệp khi phải lựa chọn giữa chính nghĩa và sự thật trong các mối quan hệ phức tạp của mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"황정민","avatar":""},{"name":"윤아","avatar":""},{"name":"손병호","avatar":""},{"name":"유선","avatar":""},{"name":"김원해","avatar":""},{"name":"박호산","avatar":""},{"name":"이승준","avatar":""},{"name":"경수진","avatar":""},{"name":"김재철","avatar":""},{"name":"임성재","avatar":""},{"name":"이지현","avatar":""},{"name":"백주희","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["嘘","Hush","Hush Korean","허쉬"]', 1784690324335);
