INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('may-gio-va-mua', 'Mây Gió và Mưa', 'King Maker: The Change of Destiny', 'https://phimimg.com/upload/vod/20241021-1/5e14f5b57178261a737f53c1819428bf.jpg', 'https://phimimg.com/upload/vod/20241021-1/2004163dad1aae0a31c0d85595b10800.jpg', '<p>Mây Gió Và Mưa là bộ phim được chuyển thể từ tiểu thuyết của tác giả Lee Byung Joo với sự góp mặt của cặp đôi Park Si Hoo và Go Seung Hee. Mây, Gió Và Mưa lấy bối cảnh triều đại Joseon, khắc hoạ sự khắc nghiệt của việc tranh giành vương vị thời bấy giờ. Choi Chun Joong (Park Si Hoo) là con trai của một gia đình quý tộc, song gia cảnh ly tán, anh trở thành một thầy pháp có thể nhìn thấu tương lai của Joseon, cũng là người xem tướng xuất sắc nhất thời đó. Công chúa Lee Bong Ryun (Go Seung Hee) là con gái vua Cheoljong, cũng là một người có khả năng nhìn thấy vận mệnh của người khác. Cùng nhau, Choi Chun Joong và Lee Bong Ryun tìm cách đưa Joseon đến với tương lai tốt đẹp hơn.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 4, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"박시후","avatar":""},{"name":"고성희","avatar":""},{"name":"성혁","avatar":""},{"name":"전광렬","avatar":""},{"name":"Park Jung-yeon","avatar":""},{"name":"Yoon A-jung","avatar":""},{"name":"김승수","avatar":""},{"name":"Han Dong-kyu","avatar":""},{"name":"Shin Dong-hoon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["风云碑","Baramgwa Gureumgwa Bi","Wind, Cloud and Rain","Wind, Clouds and Rain","Wind and Cloud and Rain","Kingmaker: The Change of Destiny","바람과 구름과 비"]', 1784690324335);
