INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-song-song-chuyen-tau', 'Thế Giới Song Song (Chuyến Tàu)', 'Train', 'https://phimimg.com/upload/vod/20241021-1/87f805811e4acb00368897290065e528.jpg', 'https://phimimg.com/upload/vod/20241021-1/d6e1214a3dcf400bf379c690ea55a7e4.jpg', '<p>Đây là một melodrama khoa học viễn tưởng về một người đàn ông cố gắng bảo vệ người mình yêu khỏi một kẻ giết người hàng loạt trong một vũ trụ song song. Seo Do Won ( Yoon Shi Yoon ) là một thám tử và anh ấy rất nhiệt tình với công việc của mình. Trong khi đó, Han Seo Kyung ( Kyung Soo Jin ) là một công tố viên có tính cách trung thực. Lee Jung Min ( Shin So Yool ) là thành viên của một đơn vị điều tra khoa học. Cô là bạn thời thơ ấu của Seo Do Won và cũng là mối tình đầu của anh. Cô ấy ủng hộ Seo Do Won.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"윤시윤","avatar":""},{"name":"경수진","avatar":""},{"name":"신소율","avatar":""},{"name":"Cho Wan-ki","avatar":""},{"name":"차엽","avatar":""},{"name":"김동영","avatar":""},{"name":"이항나","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["قطار","火车","追凶列车","트레인","Галт тэрэг","Train KR"]', 1784690324335);
