INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-lam-chong-dam', 'Đạo Làm Chồng Đảm', 'Gokushufudo', 'https://phimimg.com/upload/vod/20241018-1/cf364690fe111dbd884aeaa14dd9b669.jpg', 'https://phimimg.com/upload/vod/20241018-1/d412e5db667eabf94361c3fba54202ca.jpg', '<p>Tatsu năm nay 38 tuổi. Anh từng là một yakuza huyền thoại và được gọi là “Rồng bất tử” với danh tiếng lẫy lừng trong xã hội đen Nhật Bản. Tuy nhiên, anh giờ đã quy ẩn giang hồ và trở thành nội trợ trong gia đình sau khi kết hôn. Tatsu vùi mình làm việc nhà như một đam mê mãnh liệt, còn cô vợ Miku lại rất dở việc nhà. Tuy nhiên một Yakuza huyền thoại sao giới lưu manh có thể dễ dàng quên đi được chứ? Những câu chuyện hài hước về người đàn ông nội trợ bắt đầu…</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"玉木宏","avatar":""},{"name":"川口春奈","avatar":""},{"name":"志尊淳","avatar":""},{"name":"玉城ティナ","avatar":""},{"name":"古川雄大","avatar":""},{"name":"白鳥玉季","avatar":""},{"name":"竹中直人","avatar":""},{"name":"稲森いずみ","avatar":""},{"name":"滝藤賢一","avatar":""},{"name":"Michiko Tanaka","avatar":""},{"name":"Megumi","avatar":""},{"name":"橋本じゅん","avatar":""},{"name":"安井順平","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["极主夫道","Gokushufudo","極主夫道 テレビドラマ","Gokushufudō","極主夫道：2020","극주부도 (드라마)","極道主夫","The Way of the House Husband","The Way of the Househusband","極主夫道"]', 1784690324335);
