INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-la-duong-mat-nua-la-dau-thuong', 'Nửa Là Đường Mật, Nửa Là Đau Thương', 'Love Is Sweet', 'https://phimimg.com/upload/vod/20241016-1/a40afcffbfa4cc1ee33f9bc784342ea0.jpg', 'https://phimimg.com/upload/vod/20241016-1/1b9dcbfc0ab343228b2a34ecb563e107.jpg', '<p>Một chuyện tình vừa ngọt ngào vừa đau thương của cặp thanh mai trúc mã Viên Soái (La Vân Hi) và Giang Quân (Bạch Lộc).

Viên Soái (La Vân Hi) là một tổng tài bá đạo với tính cách ngang bướng, độc miệng, còn Giang Quân (Bạch Lộc) là cô gái cá tính trong công việc và yêu kiều trong cuộc sống.

Viên Soái thầm yêu Giang Quân nhiều năm nhưng không dám thổ lộ tình cảm. Đến khi Giang Quân có người yêu, anh lại tìm cách phá hoại, đoạt lại người mình yêu.

Liệu sau những hiểu lầm và đau thương, cả hai còn có thể đến với nhau?

Tình yêu là thứ, nửa là đường mật, nửa là đau thương.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"罗云熙","avatar":""},{"name":"白鹿","avatar":""},{"name":"高瀚宇","avatar":""},{"name":"肖燕","avatar":""},{"name":"Wang Yilun","avatar":""},{"name":"Yuanyuan Zhao","avatar":""},{"name":"管梓净","avatar":""},{"name":"胡春楊","avatar":""},{"name":"Ariel Ann","avatar":""},{"name":"常鋮","avatar":""},{"name":"Jian Yu Xi","avatar":""},{"name":"Lu Chen Yue","avatar":""},{"name":"Shi Yu","avatar":""},{"name":"謝佳見","avatar":""},{"name":"祁憶","avatar":""},{"name":"Ran Xu","avatar":""},{"name":"Wang Chen Shuo","avatar":""},{"name":"Chen Guan Yi","avatar":""},{"name":"Jiang Rong","avatar":""},{"name":"Zhou Ting","avatar":""},{"name":"Xie Shan Shan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["半是蜜糖半是伤","Горький мёд","Такая сладкая любовь","Сладкая любовь","ครึ่งทางรัก","半是蜜糖半是傷","Love is Sweet","Nửa Là Đường Mật, Nửa Là Đau Thương"]', 1784690324335);
