INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thu-phi', 'Kẻ Thu Phí', 'The Toll', 'https://phimimg.com/upload/vod/20241016-1/8857760ad1eeab5753b36c92208a7531.jpg', 'https://phimimg.com/upload/vod/20241016-1/d743c052335b788cbba2aca3775c095f.jpg', '<p>Trên đường trở về, Cami gặp phải một lái xe kì lạ khi anh ta liên tục có những hành vi khác thường. Chưa hết sợ hãi, xe của cả hai bị hỏng giữa đường và được viếng thăm bởi một vị khách thần bí.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Jordan Hayes","avatar":""},{"name":"Max Topplin","avatar":""},{"name":"James McGowan","avatar":""},{"name":"Rosemary Dunsmore","avatar":""},{"name":"Thomas L. Colford","avatar":""},{"name":"Sharon McFarlane","avatar":""},{"name":"Jana Peck","avatar":""},{"name":"Jess Brown","avatar":""},{"name":"Sean Sullivan","avatar":""},{"name":"Anthony Ulc","avatar":""},{"name":"Daniel Harroch","avatar":""},{"name":"Sarah Camacho","avatar":""},{"name":"Madison Walsh","avatar":""},{"name":"Pamela MacDonald","avatar":""},{"name":"Katelyn McCulloch","avatar":""},{"name":"Shaina Silver-Baird","avatar":""},{"name":"Ni","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["통행료","丧钟","通行费","Peaje Mortal","عوارض","The Toll"]', 1784690324336);
