INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-tu-ta-cuoi-chang-chac-roi', 'Công Tử Ta Cưới Chàng Chắc Rồi', 'Honey Don''t Run Away', 'https://phimimg.com/upload/vod/20241013-1/0ea070917b59994e6a33508631b6692a.jpg', 'https://phimimg.com/upload/vod/20241013-1/f55229dcda310c76d26169ef5f3f10ef.jpg', '<p>Diệp Tiểu Đường người giàu nhất kinh thành và Mộ Cẩn Ngôn chàng công tử nổi tiếng có tình cảm với nhau. Nhưng số phận sắp đặt hai người là truyền nhân của tộc Chúc Do và Mô Cốt Thuật, vận mệnh tương khắc. Để giải trừ vận mệnh của mình, cả hai kết giao cùng Lăng Tử Nhiên Cửu hoàng tử của nước Lăng và Việt U Nhi công chúa của nước Việt bắt đầu hành trình đi tìm báu vật. Trong hành trình nguy hiểm này, đã tôi luyện được sự trưởng thành và mỗi người cũng có được tình yêu đích thực của mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiang Han Zhi","avatar":""},{"name":"Khưu Sĩ Luân","avatar":""},{"name":"Chengjun Bo","avatar":""},{"name":"Chen Ying Dan","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["I Decide to Marry You","金主大人请自重","公子，我娶定你了2","Honey, Don''t Run Away 2","公子，我娶定你了"]', 1784690324336);
