INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dieu-toi-chua-tung-phan-1', 'Những Điều Tôi Chưa Từng (Phần 1)', 'Never Have I Ever (Season 1)', 'https://phimimg.com/upload/vod/20241013-1/c802c12725a58ed736bb0f5577f96cf6.jpg', 'https://phimimg.com/upload/vod/20241013-1/5de571c5d5b927933441ac7549d9918c.jpg', '<p>Sau một năm đau thương, một thiếu nữ người Mỹ gốc Ấn chỉ muốn cải thiện địa vị xã hội – nhưng bạn bè, gia đình và những cảm xúc khiến việc này chẳng hề dễ dàng với cô.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Maitreyi Ramakrishnan","avatar":""},{"name":"Poorna Jagannathan","avatar":""},{"name":"Jaren Lewison","avatar":""},{"name":"Darren Barnet","avatar":""},{"name":"Lee Rodriguez","avatar":""},{"name":"Ramona Young","avatar":""},{"name":"John McEnroe","avatar":""},{"name":"Richa Shukla Moorjani","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["我从来没有","Yo nunca","Never Have I Ever"]', 1784690324336);
