INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-vuong-truy-the-nhat-the-khuynh-thanh', 'Tà Vương Truy Thế: Nhất Thế Khuynh Thành', 'Be My Wife', 'https://phimimg.com/upload/vod/20241008-1/c54ae51b5bbaeaca8b57b1fa78a063c0.jpg', 'https://phimimg.com/upload/vod/20241008-1/ac05e9b75462751ac320893dca9c991e.jpg', '<p>Điệp viên hàng đầu Tô Lạc bị sát hại bởi người yêu bội bạc, sau khi tỉnh dậy thì thấy mình trở thành tứ tiểu thư vô dụng trong Tô phủ ở Bích La Đại Lục. Người đời ai cũng tránh nhắc đến cô, duy chỉ có Tấn Vương điện hạ không ngừng bám theo cô. Dưới sự giúp đỡ của Tấn Vương, Tô Lạc đã đến thần điện để kiểm tra nhờ đó phát hiện ra cô là kì tài tu luyện hiếm gặp. Vì thế vô số người ích kỉ đã âm mưu giết chết cô, nhờ đó thân phận thần bí của cô cũng dần được hé lộ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["邪王追妻","Xie Wang Zhui Qi","Xié Wáng Zhuī Qī","一世倾城","邪王追妻：废材逆天小姐","邪王追妻2：一世倾城","邪王追妻之一世倾城","邪王追妻3：神女归来","邪王追妻之神女归来","Xie Wang Zhui Qi 2 : Yi Shi Qing Cheng","Xie Wang Zhui Qi 3 : Shen Nv Gui Lai","Be My Wife","The Demonic King Who Chases His Wife","King of Jin in Tang Dynasty"]', 1784690324336);
