INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-sinh', 'Trùng Sinh', 'Reborn', 'https://phimimg.com/upload/vod/20241007-1/89f9b464af16bc844aa7c3ac6f8f51e0.jpg', 'https://phimimg.com/upload/vod/20241007-1/01dc1e6503899d98d6ebe1d6debc4848.jpg', '<p>Trùng Sinh - Reborn là bộ phim có nội dung chủ yếu xoay quanh đội phó chi đội Tây Quan - Tần Trì, là người sống sót duy nhất sau &quot;Vụ nổ súng 714&quot;, Tần Trì bị thương nặng và phải không ngừng chống chọi với việc bị mất trí nhớ, đồng thời phá giải nghi án để tìm ra chân tướng.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 8, 2020, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trình Tiểu Mông","avatar":""},{"name":"Triệu Tử Kỳ","avatar":""},{"name":"Trương Hạo Duy","avatar":""},{"name":"Lưu Quan Thạch","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["白夜重生","Reborn","Перерождённый","重生"]', 1784690324336);
