INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-thuong-phong-van-ky', 'Tái Thượng Phong Vân Ký', 'Sai Shang Feng Yun Ji', 'https://phimimg.com/upload/vod/20241007-1/01619ea1c6d5a7535e90d9270ca2aee5.jpg', 'https://phimimg.com/upload/vod/20241007-1/e0154e4add2fe3cbe1f8e661f898d112.jpg', '<p>Tái Thượng Phong Vân Ký - Sai Shang Feng Yun Ji kể về Lữ Gia - một gia tộc có tiếng là giàu ngang một nước. Nhà họ Lữ có cơ ngơi đồ sộ, tuy nhiên hàng loạt âm mưu và chết chóc đã xảy ra sau khi Lữ lão gia qua đời. Lữ Tuấn Sơn- con trai cả của Lữ Gia, nghe theo lời Cù gia, âm mưu làm giả ngay khi cha qua đời nhằm thâu tóm Lữ gia. Lữ Tuấn Kiệt, con trai thứ của Lữ gia, sau khi bị cài vào 1 vụ án giết người buộc phải rời đi, lang thang trên thảo nguyên. Tuấn Kiệt muốn bắt đầu lại, nhưng Cù gia không ngừng tìm cách hãm hại anh. Dần dần, có nhiều người chọn đứng về phía Lữ Tuấn Kiệt, giúp anh sửa chữa đường sắt, xây dựng đài phát thanh thương mại, đóng góp lớn cho nền thương mại của đất nước. Sau khi Nhật Bản xâm lược Trung Quốc, Lữ Tuấn Kiệt đã chiến đấu một trận cuối cùng chống lại Cù gia, báo thù thành công cho gia đình mình.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Đống","avatar":""},{"name":"Trương Ninh Giang","avatar":""},{"name":"Từ Phạn Khê","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["张库大道","Sai Shang Feng Yun Ji","塞上风云记"]', 1784690324336);
