INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-sach-den-phan-8', 'Danh Sách Đen (Phần 8)', 'The Blacklist (Season 8)', 'https://phimimg.com/upload/vod/20241007-1/ff0674df62c9b1d2ac31ece7fec94daa.jpg', 'https://phimimg.com/upload/vod/20241007-1/86fe3ba825d7bec4108647e0991fb268.jpg', '<p>Cựu đặc vụ của chính phủ Raymond &quot;Red&quot; Reddington (do James Spader thủ vai) là mục tiêu truy nã hàng đầu của FBI trong cả thập kỷ đột ngột tới FBI tự nguyện đầu thú, đề nghị hỗ trợ bắt tên khủng bố tưởng đã chết từ lâu - Ranko Zamani, với điều kiện chỉ nói chuyện với duy nhất Elizabeth “Liz” Keen - một hồ sơ viên mới của FBI. Chuyện bắt đầu từ đó...</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"James Spader","avatar":""},{"name":"Diego Klattenhoff","avatar":""},{"name":"Hisham Tawfiq","avatar":""},{"name":"Anya Banerjee","avatar":""},{"name":"Harry Lennix","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["la liste noire","the blacklist","רשימה שחורה","THE BLACKLIST ブラックリスト","THE BLACKLIST/ブラックリスト","Melnais Saraksts","Kara Liste","Blacklist","The Blacklist"]', 1784690324336);
