INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-biet-lu-ngoc', 'Tạm Biệt Lũ Ngốc', 'Bye Bye Morons', 'https://phimimg.com/upload/vod/20241004-1/54b89affda654056feedc1482a857301.jpg', 'https://phimimg.com/upload/vod/20241004-1/f068b58936ccf30dd18fd20240df0f52.jpg', '<p>Khi thợ làm tóc 43 tuổi Suze Trappet phát hiện ra mình bị bệnh nặng, cô quyết định đi tìm đứa con mà cô buộc phải bỏ rơi khi mới 15 tuổi. Trong hành trình quan liêu điên rồ của mình, cô đã gặp JB, một người đàn ông 50 tuổi. -một ông già đang kiệt sức và ông Blin, một nhà lưu trữ mù quáng có xu hướng quá nhiệt tình. Bộ ba bất ngờ bắt đầu cuộc hành trình lạc lõng vui nhộn và sâu sắc xuyên thành phố để tìm kiếm đứa con thất lạc từ lâu của Suze.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Virginie Efira","avatar":""},{"name":"Albert Dupontel","avatar":""},{"name":"Nicolas Marié","avatar":""},{"name":"Jackie Berroyer","avatar":""},{"name":"Philippe Uchan","avatar":""},{"name":"Bastien Ughetto","avatar":""},{"name":"Marilou Aussilloux","avatar":""},{"name":"Michel Vuillermoz","avatar":""},{"name":"Laurent Stocker","avatar":""},{"name":"Terry Gilliam","avatar":""},{"name":"Kyan Khojandi","avatar":""},{"name":"Grégoire Ludig","avatar":""},{"name":"David Marsais","avatar":""},{"name":"Bouli Lanners","avatar":""},{"name":"Catherine Davenier","avatar":""},{"name":"Johan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Bye Bye Morons","Відчайдушні втікачі","蠢蛋告別式","Adieu Les Cons","Elég a hülyékből","Farväl fårskallar","Adiós, idiotas","Счастливо оставаться","Adeus, Idiotas","Żegnajcie, głupcy","Adieu les cons","Adiós, Id