INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-tai-bi-lang-quen', 'Thiên Tài Bị Lãng Quên', 'Tesla', 'https://phimimg.com/upload/vod/20231202-1/86aaa4732d37ca08f75d3be0bde077d2.jpg', 'https://phimimg.com/upload/vod/20231202-1/6d23733f61a317ee05cd773fdc077310.jpg', '<p>Bộ phim kể về cuộc đời Nicholas Tesla - nhà khoa học/vật lý đại tài người Serbia. Ông nổi tiếng với những ý tưởng phát minh đi trước thời đại, bao gồm cả ý tưởng về việc &quot;thắp sáng thế giới&quot; với công nghệ Alternating Current (dòng điện AC) và cả việc trích xuất điện &amp; năng lượng từ lõi Trái Đất thông qua Tháp Wardenclyffe. Nhiều người tin rằng Thomas Edison đã đánh cắp nhiều ý tưởng của Tesla để trở nên nổi tiếng - đây cũng là khía cạnh được bộ phim đẩy mạnh khai thác, cùng với mối quan hệ ít người biết giữa Tesla và Anne - con gái của ông trùm tài phiệt J. P. Morgan...</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Ethan Hawke","avatar":""},{"name":"Eve Hewson","avatar":""},{"name":"Jim Gaffigan","avatar":""},{"name":"Kyle MacLachlan","avatar":""},{"name":"Donnie Keshawarz","avatar":""},{"name":"Josh Hamilton","avatar":""},{"name":"Ebon Moss-Bachrach","avatar":""},{"name":"Lucy Walters","avatar":""},{"name":"John Palladino","avatar":""},{"name":"Michael Mastro","avatar":""},{"name":"Hannah Gross","avatar":""},{"name":"Peter Greene","avatar":""},{"name":"Blake DeLong","avatar":""},{"name":"Karl Geary","avatar":""},{"name":"James Urbaniak","avatar":""},{"name":"Eli Smith","avatar":""},{"name":"Dan Bittner","avatar":""},{"name":"David","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324336);
