INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-an', 'Trắng Án', 'Innocence', 'https://phimimg.com/upload/vod/20240928-1/d111560a194b783291e64b7e1b38d4c3.jpg', 'https://phimimg.com/upload/vod/20240928-1/254b464691f60338ef0c9a80f06a9a1f.jpg', '<p>Sống trong một gia đình gia trưởng bị đàn áp và không được coi trọng, Jung In quyết định bỏ nhà lên Seoul. Vào ngày bố cô mất, mẹ của cô bị cáo buộc giết người sau khi có kẻ đã bỏ thuốc độc vào rượu gạo trong đám tang của chồng bà. Tuy nhiên, bà Hwa Ja bị chứng mất trí nhớ và không thể tự bảo vệ mình. Lúc này, Jung In đã quyết định đứng ra để bào chữa cho người mẹ đáng thương.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"신혜선","avatar":""},{"name":"배종옥","avatar":""},{"name":"허준호","avatar":""},{"name":"홍경","avatar":""},{"name":"태항호","avatar":""},{"name":"고창석","avatar":""},{"name":"박철민","avatar":""},{"name":"김수현","avatar":""},{"name":"차순배","avatar":""},{"name":"정인겸","avatar":""},{"name":"배해선","avatar":""},{"name":"Kim Joong-hee","avatar":""},{"name":"Han Woo-yeol","avatar":""},{"name":"곽자형","avatar":""},{"name":"Kyul Hwi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["翻供","gyeol-baek","Gyul-baek","بی گناهی","بی‌گناه","بی گناه","Inocencia","결백"]', 1784690324336);
