INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-gia-von-si-tinh-ta', 'Thiếu Gia Vốn Si Tình Ta', 'A Love So Romantic', 'https://phimimg.com/upload/vod/20240925-1/5f4bb2c651c7e58b60e30f3233f7c6b0.jpg', 'https://phimimg.com/upload/vod/20240925-1/29cd631c5ee8859e9ec59c50f6d837ac.jpg', '<p>Thiếu Gia Vốn Si Tình Ta - A Love So Romantic kể về quá trình tìm hiểu yêu đương của cặp đôi Cố Ngôn Tịch và Tô Tiểu Vãn. Thiếu nữ bán hoa rất giỏi lừa gạt - Tô Tiểu Vãn, trong một lần trời xui đất khiến, đã cùng đại thiếu gia của gia tộc châu báu Cố phủ - Cố Ngôn Tịch, ký “khế ước huynh muội”, nháy mắt trở thành muội muội của Cố Ngôn Tịch. Tuy nhiên câu chuyện chim sẻ biến thành phượng hoàng không hề tốt đẹp như trong tưởng tượng của Tô Tiểu Vãn, đối mặt với ca ca độc miệng phúc hắc, Tiểu Vãn chỉ có thể gặp chiêu tiếp chiêu, đấu trí đấu dũng. Mặc dù gian nan nhưng may mắn còn một nhị ca ấm áp Cố Tử Khiêm luôn ở bên Tiểu Vãn, cho cô sự quan tâm che chở. Nhưng vị nhị ca này đối với Tiểu Vãn không đơn thuần là tình huynh muội, Và tồi tệ hơn là trong quá trình tiếp xúc với hai ca ca Tiểu Vãn phát hiện bản thân đã trót yêu Cố Ngôn Tịch đáng ghét nhất.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 9, 2020, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngu Thư Hân","avatar":""},{"name":"Diệp Thịnh Giai","avatar":""},{"name":"Dương Chi Văn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["我太爱哥哥了怎么办","少爷与我的罗曼史"]', 1784690324336);
