INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lala-school-duong-dua-idol-the-he-z', 'LaLa School: Đường Đua Idol Thế Hệ Z', 'LaLa School: Generation Z Idol Race', 'https://phimimg.com/upload/vod/20240925-1/78b4fcfd79ba014a8e5894410d829bcd.jpg', 'https://phimimg.com/upload/vod/20240925-1/700a9a45352f96bfca6e62eb31eef05a.jpg', '<p>LaLa School: Đường Đua Idol Thế Hệ Z kể về một nhóm bạn gồm các cô gái đến từ mọi vùng miền đất nước với những nét cá tính và đặc trưng khác nhau, nhưng cùng mang một hoài bão và niềm đam mê với âm nhạc. Trải qua nhiều sóng gió với những khó khăn từ chuyện phân biệt vùng miền, trở ngại từ hoàn cảnh gia đình và những trò chơi khăm của nhóm những cô nàng xấu tính… bên cạnh những khoảnh khắc ngọt ngào lãng mạn với những cậu bạn tài năng cùng chung đam mê, liệu nhóm bạn có đạt được mục đích ra mắt trong công ty giải trí danh giá? Liệu họ có chạm đến ước mơ của mình hay còn gặp trở ngại nào khác?</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"An Vy","avatar":""},{"name":"Dư Khánh Vũ","avatar":""},{"name":"Dương Nhất Linh","avatar":""},{"name":"Nhóm P336","avatar":""},{"name":"Otis Đỗ Nhật Trường","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324336);
