INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-ban-yeu-phan-1', 'Công Chúa Bán Yêu (Phần 1)', 'Yashahime: Princess Half-Demon', 'https://phimimg.com/upload/vod/20240924-1/827fb080a46be43a1c939edeb85b87d9.jpg', 'https://phimimg.com/upload/vod/20240924-1/bd74a3b829f1ded3d955850621a3faec.jpg', '<p>Hồi còn nhỏ, 2 chị em sinh đôi Towa và Setsuna đã dính vào một vụ hoả hoạn, và bị chia cắt. Towa tiếp tục quay ngược thời gian từ thời Chiến quốc cho đến nay, còn em gái Setsuna đã tham gia tiêu diệt yêu quái thời Chiến quốc. Khi họ gặp lại nhau ở thời hiện đại, Setsuna không hiểu vì sao đã quên mất Towa, hai chị em cũng tung hoành ngang dọc ở thời hiện đại và thời chiến quốc.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324336);
