INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-the-song-kieu-truyen', 'Phù Thế Song Kiều Truyện', 'Legend Of Two Sisters In The Chaos', 'https://phimimg.com/upload/vod/20240924-1/053121e6cd438bc7ae2f2ffb7ef8fb32.jpg', 'https://phimimg.com/upload/vod/20240924-1/5624453bdd2c97e6356c1ad2c019478d.jpg', '<p>Vào thời kỳ Hậu Chu, dân gian có truyền thuyết &quot;Phù Nữ Đế Hậu&quot;, nữ nhi của trọng thần năm triều là Phù Ngạn Khanh sẽ trở thành hoàng hậu tương lai. Có người phí hết tâm tư, cho rằng chỉ cần có được nữ nhi Phù gia thì sẽ có được thiên hạ. Lại có người trăm phương ngàn kế, cho rằng chỉ cần giết nữ nhi Phù gia thì liền có thể huỷ đi đế vị.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 10, 2020, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Trị Đình","avatar":""},{"name":"Lý Nghệ Đổng","avatar":""},{"name":"Mạnh Tử Nghĩa","avatar":""},{"name":"Uông Trác Thành","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["十国千娇","双嬌伝（そうきょうでん）～運命の姉妹と2人の皇子","双嬌伝 運命の姉妹と2人の皇子","双嬌伝(そうきょうでん) 運命の姉妹と2人の皇子","Charming and Countries","浮世双娇传"]', 1784690324336);
