INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phu-the-song-kieu-truyen', 'Phù Thế Song Kiều Truyện', 'Legend Of Two Sisters In The Chaos', 'phù thế song kiều truyện legend of two sisters in the chaos lý trị đình lý nghệ đổng mạnh tử nghĩa uông trác thành 十国千娇 双嬌伝（そうきょうでん）～運命の姉妹と2人の皇子 双嬌伝 運命の姉妹と2人の皇子 双嬌伝(そうきょうでん) 運命の姉妹と2人の皇子 charming and countries 浮世双娇传', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-tu-da-day', 'Yêu Em Từ Dạ Dày', 'Dating In The Kitchen', 'https://phimimg.com/upload/vod/20240924-1/fff40a84239e5bed85af229cc2dcdf9d.jpg', 'https://phimimg.com/upload/vod/20240924-1/37bcb441da7e21fdeec4b94b594a7f69.jpg', '<p>Điều khó tin nhất trong cuộc đời Cố Thắng Nam tinh ranh, chính là sau khi cô vừa thất tình vừa thất nghiệp đang mòn mỏi đợi chờ bạch mã hoàng tử đến cứu vớt cuộc đời, thì ai mà ngờ được chàng hoàng tử của cô vừa xoi mói vừa lươn lẹo, vừa độc mồm độc miệng, lại vừa tự cao tự đại, là bản update của &quot;Đường Tăng&quot;! Lộ Tấn sành ăn, kiêu ngạo, độc mồm vừa gặp đầu bếp thiên tài Cố Thắng Nam là không ngừng xảy ra sự cố, nhưng lần nào cũng bị tay nghề cao siêu của cô hấp dẫn. Trải qua suốt quá trình gà bay chó chạy, hỗn loạn tung trời này, hai người ngày càng sát lại gần nhau hơn tựa như được số phận sắp đặt.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"赵露思","avatar":""},{"name":"林雨申","avatar":""},{"name":"Zhang Xiao Qian","avatar":""},{"name":"付嘉","avatar":""},{"name":"於蓓蓓","avatar":""},{"name":"Wu Ya Heng","avatar":""},{"name":"Li Qian","avatar":""},{"name":"Xiu Jingshuang","avatar":""},{"name":"Yang Ping","avatar":""},{"name":"Fan Yujie","avatar":""},{"name":"Дун Цзо Хан","avatar":""},{"name":"Henry Luk Yat-Lung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["我，喜欢你","아희환니","ฝากรักไว้ท้ายครัว","我，喜歡你","Dating in the Kitchen"]', 1784690324336);
