INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('emicida-amarelo-tat-ca-vi-ngay-hom-qua', 'Emicida: Amarelo Tất Cả Vì Ngày Hôm Qua', 'Emicida: AmarElo - It''s All for Yesterday', 'https://phimimg.com/upload/vod/20240922-1/1abec14a042274f555bb2785dc9f01b9.jpg', 'https://phimimg.com/upload/vod/20240922-1/c5bdf2ced4ca670105993754ee9a17c1.jpg', '<p>Qua những cảnh quay trong buổi hòa nhạc của anh ở Nhà hát Thành phố của São Paulo, rapper kiêm nhà hoạt động Emicida tôn vinh di sản phong phú của văn hóa da đen Brazil.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Emicida","avatar":""},{"name":"Fernanda Montenegro","avatar":""},{"name":"Zeca Pagodinho","avatar":""},{"name":"Pabllo Vittar","avatar":""},{"name":"Majur","avatar":""},{"name":"MC Tha","avatar":""},{"name":"Marcos Valle","avatar":""},{"name":"Henrique Vieira","avatar":""},{"name":"Fabiana Cozza","avatar":""},{"name":"Ruth de Souza","avatar":""},{"name":"Lélia Gonzalez","avatar":""},{"name":"Wilson Simonal","avatar":""},{"name":"Abdias Nascimento","avatar":""},{"name":"Angela Davis","avatar":""},{"name":"Wilson das Neves","avatar":""},{"name":"Leci Brandão","avatar":""},{"name":"Mário de Andrade","avatar":""},{"name":"Don","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["Emicida: AmarElo - É Tudo Pra Ontem"]', 1784690324336);
