INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-xuc-con-tim', 'Cảm Xúc Con Tim', 'Chemical Hearts', 'https://phimimg.com/upload/vod/20231111-1/3ea6e6256f30f514e48dd826cacae014.jpg', 'https://phimimg.com/upload/vod/20231111-1/a3b8e45792e7a5fc29abf4b29c9b191a.jpg', '<p>Trang Henry 17 tuổi chưa bao giờ được yêu. Anh ta tưởng tượng mình là một người lãng mạn, nhưng tình yêu một lần trong đời mà anh ta hy vọng đã không xảy ra. Khi anh gặp Học sinh Grace Town vào ngày đầu tiên của năm cuối, tất cả những gì có thể sắp thay đổi. Khi Grace và Henry được chọn để đồng chỉnh sửa bài báo, anh ta ngay lập tức bị lôi cuốn vào người mới bí ẩn. Khi anh ta học được bí mật đau lòng đã thay đổi cuộc đời mình, anh thấy mình yêu cô - hoặc ít nhất là người mà anh nghĩ cô.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Austin Abrams","avatar":""},{"name":"Lili Reinhart","avatar":""},{"name":"Sarah Jones","avatar":""},{"name":"Bruce Altman","avatar":""},{"name":"Adhir Kalyan","avatar":""},{"name":"Coral Peña","avatar":""},{"name":"Shannon Walsh","avatar":""},{"name":"Kara Young","avatar":""},{"name":"Meg Gibson","avatar":""},{"name":"C.J. Hoff","avatar":""},{"name":"Jon Lemmon","avatar":""},{"name":"J.J. Pyle","avatar":""},{"name":"Robert Clohessy","avatar":""},{"name":"Catherine Curtin","avatar":""},{"name":"Lan Zhong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324336);
