INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sa-mang-vay-thanh', 'Sa Mãng Vây Thành', 'Snake: Fall of a City', 'https://phimimg.com/upload/vod/20240922-1/b4fb5bfa68fa5cdb2110a2000c803432.jpg', 'https://phimimg.com/upload/vod/20240922-1/b4e6f17f2707d744220f61f5d9741291.jpg', '<p>Nỗi khiếp sợ khi rắn hổ sa mạc tấn công! Tay đua Lương Tử rút lui khỏi cuộc đua trên sa mạc, Lâm Sấm người đang theo đuổi cô cũng vì thế mà rút lui. Hóa ra Lương Tử đang tìm kiếm người cha bị mất tích giữa sa mạc. Họ bị một sinh vật thần bí tấn công lúc về đêm. Liệu sinh vật thần bí này có liên quan gì đến sự mất tích của cha cô? Cuối cùng sinh vật thần bí cũng đã xuất hiện giữa con bão cát. Liệu họ có thể an toàn rút lui không?</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"林枫烨","avatar":""},{"name":"Jacinda Li","avatar":""},{"name":"Wang Bo","avatar":""},{"name":"Liya Wang","avatar":""},{"name":"Ma Wenliang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sand Python Siege","Sha Mang Wei Cheng","Shamang Weicheng","Осада песчаного питона","沙蟒围城"]', 1784690324336);
