INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('penthouse-cuoc-chien-thuong-luu-phan-1', 'Penthouse: Cuộc Chiến Thượng Lưu Phần 1', 'The Penthouse: War In Life 1', 'https://phimimg.com/upload/vod/20240920-1/5323f638e7f5370db8f54135648a90fb.jpg', 'https://phimimg.com/upload/vod/20240920-1/82c033585fd1194fba9e6b14bde9b27b.jpg', '<p>Bộ phim kể về câu chuyện những gia đình giàu có vì bồi dưỡng con em thành danh mà không từ thủ đoạn, xảy ra giữa tầng lớp thượng lưu Hàn Quốc sống tại tầng 100 của một tòa chung cư cao cấp (Tên &quot;Hera Palace&quot;), đi cùng với những đó là những thứ như báo thù, ngoại tình, giao dịch tiền bạc...</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 21, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"이지아","avatar":""},{"name":"김소연","avatar":""},{"name":"유진","avatar":""},{"name":"박호산","avatar":""},{"name":"엄기준","avatar":""},{"name":"신은경","avatar":""},{"name":"온주완","avatar":""},{"name":"봉태규","avatar":""},{"name":"윤종훈","avatar":""},{"name":"박은석","avatar":""},{"name":"윤주희","avatar":""},{"name":"하도권","avatar":""},{"name":"안연홍","avatar":""},{"name":"김현수","avatar":""},{"name":"진지희","avatar":""},{"name":"김영대","avatar":""},{"name":"한지현","avatar":""},{"name":"최예빈","avatar":""},{"name":"Lee Tae-vin","avatar":""},{"name":"Kim Dong-Kyu","avatar":""},{"name":"Kim Do-hyeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["顶楼","The Penthouse","เกมแค้นระฟ้า","上流战争","Пентгауз: Війна в житті","Пентхаус","The Penthouse KR","The Penthouse: War in Life","펜트하우스"]', 1784690324336);
