INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('retsuko-hung-hang-phan-3', 'Retsuko hung hăng (Phần 3)', 'Aggretsuko (Season 3)', 'https://phimimg.com/upload/vod/20240920-1/6632828aed4c13f568b120d2bc9d6f47.jpg', 'https://phimimg.com/upload/vod/20240920-1/d22b728160a68246799cd00c4c84efc8.jpg', '<p>Cơn thịnh nộ của Retsuko bùng nổ lên tầm cao mới khi cô phải làm thêm ngoài giờ với nhóm thần tượng underground nhằm trả nợ.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaolip","avatar":""},{"name":"Rareko","avatar":""},{"name":"Shingo Katou","avatar":""},{"name":"Rina Inoue","avatar":""},{"name":"荒井聡太","avatar":""},{"name":"鶴田真希","avatar":""},{"name":"Yuki Takahashi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["冲吧烈子","Η Ρέτσουκο Έξω Φρενών","Aggressive Retsuko","Retsuko Hung Hăng","アグレッシブ烈子"]', 1784690324336);
