INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('30-chua-phai-tet', '30 Chưa Phải Tết', '30 Chưa Phải Tết', 'https://phimimg.com/upload/vod/20240920-1/fa386724cc0750aee65ebc9caaca2e3c.jpg', 'https://phimimg.com/upload/vod/20240920-1/af0386c80cde29725a6afe030be2821f.jpg', '<p>Một bộ phim hài giả tưởng với sứ mệnh tạo ra tiếng cười ngày Tết và gửi gắm một thông điệp nhẹ nhàng về Nhân - Quả, Phụ - Tử và Bằng Hữu. Cách dựng chuyện và chủ đề ‘vòng lặp thời gian’ để nhấn mạnh yếu tố nhân quả - đừng vội vàng khi mọi chuyện chưa ngã ngũ. Bộ phim dẫn nhiều tình tiết có vay sẽ có trả, đồng thời tô đậm các mối quan hệ đã bị lãng quên, mang đến cho khán giả cơ hội nhận ra ai, điều gì mới là quan trọng trong cuộc đời của họ? Những chuyện xảy ra khi Hân mắc kẹt trong vòng lặp ngày 30 Tết sẽ được ‘vén màn’ vào ngày Mùng 01 Tết Canh Tý 2020.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Trường Giang","avatar":""},{"name":"Mạc Văn Khoa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["30 Chưa Phải Tết"]', 1784690324336);
