INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thong-long-ma-2', 'Thòng Lọng Ma 2', 'The Rope Curse 2', 'https://phimimg.com/upload/vod/20231127-1/92dfcf630ff5bcbb913441924bf261ed.jpg', 'https://phimimg.com/upload/vod/20231127-1/c3e8e3bdd6768908feaf653da5f691c7.jpg', '<p>Sau một nghi lễ thanh tẩy thất bại, vị pháp sư đầy mâu thuẫn cố giúp đỡ một nhà ngoại cảm trẻ và cô độc có người dì bị một ác quỷ quyền năng nhập xác.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Hsu An-Chih","avatar":""},{"name":"Vera Chen","avatar":""},{"name":"Lee Kang-sheng","avatar":""},{"name":"Bor Jeng Chen","avatar":""},{"name":"Yen Cheng-kuo","avatar":""},{"name":"Jason Tsou","avatar":""},{"name":"Hsia Yu-chiao","avatar":""},{"name":"Lei Hung","avatar":""},{"name":"Fox Lee","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324336);
