INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tong-su-cong-phu-hoac-nguyen-giap', 'Tông Sư Công Phu Hoắc Nguyên Giáp', 'Fearless Kungfu King', 'https://phimimg.com/upload/vod/20240918-1/7c241a2905c1e91766bdff196be075b0.jpg', 'https://phimimg.com/upload/vod/20240918-1/cf5b711782ef68ac5df20f070d20fbf9.jpg', '<p>FEARLESS KUNGFU KING : Bộ phim kể về một thanh niên trẻ tuổi Hoắc Nguyên Giáp, không màng đến lời dạy &quot;Nắm đấm dùng đức mà lập&quot; của cha, một lòng chỉ muốn &quot;Lấy võ phục người&quot; bỏ nhà ra đi đến Tân Môn. Tại đây hắn tình cờ gặp được Nông Kình Tôn, người luôn âm thầm theo pháp Duy Tân, đang gặp nguy hiểm và giải vây cho hắn. Nông Kình Tôn thấy Hoắc Nguyên Giáp có võ nghệ siêu quần, khuyên hắn mở võ quán để cường quốc cường dân, nhưng lúc đó ở Tân Môn có quy củ, nếu muốn mở võ quán thì phải đánh bại bảy võ quán ở đó trước để chứng minh thực lực. Tuy cuối cùng Hoắc Nguyên Giáp đã chiến thắng cả bảy võ quán, nhưng lại bị Viên Hiệu Trung hãm hại...</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hu Guofang","avatar":""},{"name":"Zheng Zhongyu","avatar":""},{"name":"Zhao Qiusheng","avatar":""},{"name":"Wang Yabin","avatar":""},{"name":"杨乾龙","avatar":""},{"name":"Vincent Zheng","avatar":""},{"name":"Li Zhenqi","avatar":""},{"name":"Yu Aiqun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Fearless Kungfu King","功夫宗师霍元甲","Gong Fu Zong Shi Huo Yuan Jia"]', 1784690324336);
