INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-nguyen-cua-cha', 'Di Nguyện Của Cha', 'The Last Thing He Wanted', 'https://phimimg.com/upload/vod/20231130-1/2dc02288613e2ef2734c022ad189a866.jpg', 'https://phimimg.com/upload/vod/20231130-1/797f3a2916a74525bda3c6933940ee5e.jpg', '<p>Một phóng viên đanh thép vướng vào câu chuyện mà cô cố gắng phơi bày trong khi giúp người cha đau ốm của mình môi giới hợp đồng vũ khí ở Trung Mỹ.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Ben Affleck","avatar":""},{"name":"Rosie Perez","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Edi Gathegi","avatar":""},{"name":"Mel Rodriguez","avatar":""},{"name":"Onata Aprile","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Carlos Leal","avatar":""},{"name":"Ben Chase","avatar":""},{"name":"Julian Gamble","avatar":""},{"name":"Robert Sedgwick","avatar":""},{"name":"Bill Kelly","avatar":""},{"name":"David Vadim","avatar":""},{"name":"César Galindez","avatar":""},{"name":"Diomedes Rodriguez","avatar":""},{"name":"Casiano Ancalle","avatar":""},{"name":"Lee Markham","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324336);
