INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-khi-tat-1162', 'Tân Khí Tật 1162', 'Xin Qiji 1162', 'https://phimimg.com/upload/vod/20231109-1/23fcd8d4ad60dcf2baf66ba2fff566e9.jpg', 'https://phimimg.com/upload/vod/20231109-1/9b574f24c330b91cc70a43cf08897459.jpg', '<p>Năm 1161, khi mà vùng đất đại triều Tống bị chia cắt, nhân dân rơi vào cảnh khốn cùng, Tân Khí Tật cảm thấy bất mãn trước sự độc ác của chính quyền nên quyết tâm nuôi khát vọng thống nhất giang sơn xã tắc. Chiến tranh và sự áp lực đã đẩy cuộc sống của mọi người đã khó khăn lại càng thêm bi đát, tất cả cùng nhau hợp sức đòi lại công bằng, từ những cuộc khởi nghĩa nhân dân nhỏ lẻ và dần dần lớn mạnh. Khí Tật trải qua bao trận đánh, trở thành một tướng quân tài giỏi, niềm tự hào của dân tộc.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tse Miu","avatar":""},{"name":"Sheng Nan","avatar":""},{"name":"Jason Zheng","avatar":""},{"name":"Gao Mingyang","avatar":""},{"name":"Zhang Haosen","avatar":""},{"name":"Guo Ye","avatar":""},{"name":"Fu Jun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324336);
