INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-thai-tu', 'Tam Thái Tử', 'Three Princes', 'https://phimimg.com/upload/vod/20240911-1/36fc2be65580e5149c24c2701cddd4b4.jpg', 'https://phimimg.com/upload/vod/20240911-1/fb05641a31efcaa2f9b2e4947e67821f.webp', '<p>Cuộc chiến tàn khốc phân tranh chợ cũ, chợ mới nổ ra sau sự ra đi đột ngột của ông Sói, trùm Chợ Cá. Anh em trong xã đoàn sẽ làm gì để tranh giành quyền lực?</p>', 'Hoàn Tất (3/3)', 40, 'series', 'completed', 14, 2020, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Việt Hương","avatar":""},{"name":"Thanh Tân","avatar":""},{"name":"Xuân Nghị","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324336);
