INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-gian-dung-lai-o-khoanh-khac-nay', 'Thời gian dừng lại ở khoảnh khắc này', 'Time Stops at This Moment', 'null', 'https://phimimg.com/upload/vod/20231108-1/78ef76e6fb95304dba94eff02d4f9a2b.jpg', '<p>Gao Ming Ze, người thiếu vắng sự chăm sóc của gia đình từ khi còn rất nhỏ, là một học sinh bị ám ảnh bởi rất nhiều cô gái, nhưng vì những khiếm khuyết trong tính cách của mình, luôn phải chuyển trường vì đánh nhau. Cho đến một ngày Gao Ming Ze gặp Zhou Xiao Tong, một học sinh ngây thơ và chính trực. Cả hai người đã từng là xa lạ trở nên không thể tách rời vì một nhiệm vụ. Cậu thiếu niên lãnh đạm này dần dần bước vào cuộc sống và gia đình Zhou Xiao Tong. Anh cảm thấy được an ủi bởi những cảm xúc đơn giản nhưng hợp lý của gia đình Zhou Xiao Tong. Liệu Gao Ming Ze có thể thay đổi và vượt qua tất cả những trở ngại trên con đường tìm kiếm một cuộc sống mới?</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Te","avatar":""},{"name":"Dong Xin Yun","avatar":""},{"name":"Su Dan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324336);
