INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-tong-giet-tay-mon-khanhvo-tong-tra-thu-cho-dai-lang', 'Võ Tòng Giết Tây Môn Khánh/Võ Tòng Trả Thù Cho Đại Lang', 'Wu Song VS Ximen Qing', 'https://phimimg.com/upload/vod/20231108-1/a38a01a3b516d432f2face8710400b8a.jpg', 'https://phimimg.com/upload/vod/20231108-1/0d3020b5432cc91e7c72e6ffa63234f5.jpg', '<p>PHIM Võ Tòng Giết Tây Môn Khánh/Võ Tòng Trả Thù Cho Đại Lang-Wu Song VS Ximen Qing (2021) [FULL HD-VIETSUB] : Tây Môn khánh và Văn Lãng chạm mặt nhau và cố gắng đưa Võ Tòng tới Nhật Bản. Khi Võ Tòng vội vã về nhà thì anh trai của anh ta là Đại Lang đã bị hạ sát. Võ Tòng không tin những lời thanh minh của Văn Lãng và quyết định điều tra nguyên nhân cái chết của anh trai mình, nhưng trên đường tìm kiếm tung tích anh ta đã bị một người dùng dây bạc tấn công.Võ Tòng trói Anh Vũ và Chư Hiệu để đưa đến nha môn, cố gắng kết tội Tây Môn Khánh và Văn Lãng, nhưng nha môn đáp lại bằng một vài lời nói hời hợt và khép lại vụ án bằng một văn bản nguệch ngoạc.Võ Tòng không thể nào chấp nhận được, anh ta đã chém Văn Lãng, và Vương Xương. Trong thủ phủ, Võ Tòng và Tây Môn Khánh đã xảy ra một cuộc chiến ác liệt, cuối cùng anh ta đã giết được Tây Môn Khánh và báo thù cho anh trai của mình.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhengyong Zhang","avatar":""},{"name":"Ge Tian","avatar":""},{"name":"Zhang Haocheng","avatar":""},{"name":"Li Lianzheng","avatar":""},{"name":"Tian Lu","avatar":""},{"name":"Han Jiwei","avatar":""},{"name":"Xu Min","avatar":""},{"name":"Jiang Haiyong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324336);
