INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-khong-muon-lam-ban-voi-cau', 'Tôi Không Muốn Làm Bạn Với Cậu', 'I Don''t Want To Be Friends With You', 'https://phimimg.com/upload/vod/20240909-1/22add9b071b2d9949c7344ec25612ecb.jpg', 'https://phimimg.com/upload/vod/20240909-1/55df8f779dba33aab43ce82f861d8ddd.jpg', '<p>Nữ sinh cấp 3 Lý Tiến Bộ từ nhỏ lớn lên cùng với mẹ trong một chuyến du lịch kì ảo trở về 20 năm trước, gặp được mẹ là Lý Thanh Đồng trở thành bạn tốt. Hai người bởi vì khác biệt về thời đại, tính cách, mà xảy ra một loạt những câu chuyện dở khóc dở cười, nắm tay nhau cùng vượt qua những ngọt ngào và chua xót của tuổi trẻ. Lý Tiến Bộ hiểu được sự dũng cảm, điềm đạm của mẹ, sau khi trở về thực tại, hóa giải mọi khúc mắc, cùng tìm ra chân lý của cuộc sống.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2020, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"陳昊宇","avatar":""},{"name":"Zhuang Dafei","avatar":""},{"name":"Ma Sichao","avatar":""},{"name":"周彥辰","avatar":""},{"name":"古子成","avatar":""},{"name":"Wang Yimiao","avatar":""},{"name":"Guo Xinyu","avatar":""},{"name":"Wang Zheng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324336);
