INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-tinh-dau-nhieu-nam-nhu-the', 'Mối Tình Đầu Nhiều Năm Như Thế', 'First Romance', 'https://phimimg.com/upload/vod/20240909-1/95a24afe8bdd292240a2f36621a1447e.jpg', 'https://phimimg.com/upload/vod/20240909-1/5398129effa22b7a3c05022373bf365b.jpg', '<p>Phim Mối Tình Đầu Nhiều Năm Như Thế - First Romance xoay quanh nữ sinh Hùng Y Phàm (Vạn Bằng thủ vai) cô nàng từ cao trung đến đại học đã bỏ ra rất nhiều thời gian để theo đuổi anh chàng Nhan Kha (Vương Dĩ Luân thủ vai). Yêu phải một người thì sợ gì người đó đã cự tuyệt mình nhiều lần, dù có biết trước được kết quả sẽ không đẹp như mơ ước nhưng hãy can đảm, dũng cảm mà làm, đừng vì những thứ bên ngoài nhiễu sóng một tí là buông bỏ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2020, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lư Dương Dương","avatar":""},{"name":"Vương Dĩ Luân","avatar":""},{"name":"Ngô Hán Khôn","avatar":""},{"name":"Trịnh Thư Hoàn","avatar":""},{"name":"Vạn Bằng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324336);
