INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-toi-nhung-vi-sao', 'Đi Tới Những Vì Sao', 'Steps To The Star', 'https://phimimg.com/upload/vod/20240908-1/13d18c7df32772aa7e2c3fb6e0f18ae2.jpg', 'https://phimimg.com/upload/vod/20240908-1/cecbb3d21cec185def08a03d5299c2c1.jpg', '<p>Đi Tới Những Vì Sao - Steps To The Star là bộ phim tâm lý, tình cảm đầy kịch tính của Thái Lan xoay quanh cặp vợ chồng Hemsuda (Cris Horwang) và Sharump (Atichart Chumnanon), tuy đã hết yêu nhau nhưng vì hình ảnh của bản thân ngoài xã hội mà vẫn duy trì hôn nhân. Lớp vỏ hạnh phúc giả dối của họ hoàn toàn thay đổi khi cả hai gặp được một cặp đôi đang yêu nhau là Theewin và Paitong. Hemsuda thích Theewin, trong khi Sharump cũng muốn có được Paitong và cả hai sử dụng mọi mánh khóe để phá hủy mối quan hệ của cặp tình nhân trẻ tuổi. Đồng thời họ cũng phải đấu đá với nhau hòng nhận được nhiều lợi ích nhất khi vụ ly hôn hoàn tất.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Cris Horwang","avatar":""},{"name":"Bank Thiti Mahayotaruk","avatar":""},{"name":"Atichart Chumnanon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324336);
