INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-mu-suong', 'Đỉnh Mù Sương', 'The Foggy Mountain', 'null', 'https://phimimg.com/upload/vod/20231101-1/a81527e54932f100d723a19482b8e8f8.jpg', '<p>Sau cái chết đầy bất ngờ của vợ, Phi - một võ sỹ tự do quyết định trở về Việt Nam để đòi món nợ máu. Tại bản Mù Sương, anh không chỉ đối mặt với Ba Râu cùng mối thù giết vợ mà còn phát hiện hàng loạt những bí mật kinh hoàng. Ba Râu cũng chính là nỗi khiếp sợ bấy lâu nay của người dân nơi này. Số phận một lần nữa đặt Phi vào giữa lằn ranh lựa chọn: báo thù Ba Râu hay bảo vệ người dân bản Mù Sương? Và liệu Phi sẽ tìm ra được thuốc giải cho liều thuốc độc mang tên &quot;hận thù&quot; đang tồn tại trong chính bản thân mình?</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Peter Pham","avatar":""},{"name":"Kim Long Thach","avatar":""},{"name":"Công Ninh","avatar":""},{"name":"Pham Huy Thuc","avatar":""},{"name":"Truc May","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324336);
