INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhanh-ve-phia-truoc', 'Nhanh về phía trước', 'Fast Forward', 'https://phimimg.com/upload/vod/20231101-1/f4d83fc2da6f100694004899673b0fc5.jpg', 'https://phimimg.com/upload/vod/20231101-1/dc579e39f874b9011a67cd589213e083.jpg', '<p>Gao Shang, một tài xế xe cứu thương bình thường với ước mơ đua xe từ khi còn là một đứa trẻ, đã lái chiếc xe của chính mình và vô tình vướng vào một cuộc tranh chấp đua xe, khiến cuộc đời anh thay đổi hoàn toàn. Đứng trước ngã ba đường đời, chọn cuộc sống ổn định hay ước mơ? Gao Shang đang gặp khó khăn, nhưng những gì Mengmeng nói trước khi chết khiến anh nhận ra tầm quan trọng của việc theo đuổi ước mơ. Và chính Mengmeng là người đã thúc đẩy anh ấy kiên định với ước mơ của mình. Cuộc sống thật ngắn ngủi. Chỉ có sống thật với chính mình và dũng cảm tiến về phía trước, bạn mới có thể sống trọn vẹn cuộc sống của mình.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Ruihan","avatar":""},{"name":"Shi Shi","avatar":""},{"name":"Jia Bing","avatar":""},{"name":"Jiang Chao","avatar":""},{"name":"Yi Na","avatar":""},{"name":"Wu Di-wen","avatar":""},{"name":"Hai Yitian","avatar":""},{"name":"Ma Li","avatar":""},{"name":"Tian Yin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324336);
