INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-nguy-hiem-nhat-chau-au-otto-skorzeny-o-tay-ban-nha', 'Kẻ nguy hiểm nhất Châu Âu: Otto Skorzeny ở Tây Ban Nha', 'Europe''s Most Dangerous Man: Otto Skorzeny in Spain', 'https://phimimg.com/upload/vod/20231101-1/67f7461f0cc9a06fd733ee30924bd205.jpg', 'https://phimimg.com/upload/vod/20231101-1/fa5db806de6dd9d7834ff9d32b1f61c5.jpg', '<p>Tài liệu đã được công khai hé lộ cuộc sống hậu Thế chiến II của Otto Skorzeny, thân tín của Hitler. Ông ta trốn sang Tây Ban Nha và làm cố vấn cho các vị tổng thống.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Paloma Navarro","avatar":""},{"name":"Luis María Pardo","avatar":""},{"name":"José Luis Blanco Corredoira","avatar":""},{"name":"Ralph P. Ganis","avatar":""},{"name":"Almudena Grandes","avatar":""},{"name":"Stuart Smith","avatar":""},{"name":"Joan Buades","avatar":""},{"name":"Javier Juárez","avatar":""},{"name":"David Solar","avatar":""},{"name":"Jacinto Antón","avatar":""},{"name":"Waltraut Riess","avatar":""},{"name":"Efraim Zuroff","avatar":""},{"name":"Óscar González","avatar":""},{"name":"Jaume Poma","avatar":""},{"name":"Alexandra Jones","avatar":""},{"name":"Yossi Melman","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324336);
