INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('arthur-merlin-hiep-si-lac-da', 'Arthur & Merlin: Hiệp Sĩ Lạc Đà', 'Arthur & Merlin: Knights of Camelot', 'https://phimimg.com/upload/vod/20231030-1/a4449080abd7ba36cceeacc7a5bdba96.jpg', 'https://phimimg.com/upload/vod/20231030-1/ea313023d201635e8a98807fd0dede1a.jpg', '<p>Vua Arthur trở về nhà sau khi chiến đấu với quân La Mã. Con trai ngoài giá thú của ông đã làm hỏng ngai vàng của Camelot. Bây giờ, Vua Arthur phải đoàn tụ với phù thủy Merlin và Hiệp sĩ Bàn tròn và chiến đấu để lấy lại vương miệng của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Richard Short","avatar":""},{"name":"Joe Egan","avatar":""},{"name":"Ronan Summers","avatar":""},{"name":"Olivia Bernstone","avatar":""},{"name":"Georgia Curtis","avatar":""},{"name":"Charlie Hiett","avatar":""},{"name":"Jennifer Matter","avatar":""},{"name":"Stella Stocker","avatar":""},{"name":"James G. Nunn","avatar":""},{"name":"Kris Johnson","avatar":""},{"name":"Ian Sharp","avatar":""},{"name":"Stefan Boehm","avatar":""},{"name":"Paul Marc Davis","avatar":""},{"name":"Tim Fellingham","avatar":""},{"name":"Joel Phillimore","avatar":""},{"name":"Antonio Bustorff","avatar":""},{"name":"Audrey L�","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324336);
