INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-chu-muu-2020', 'Kẻ Chủ Mưu', 'Insect Detective', 'https://phimimg.com/upload/vod/20240829-1/4c90150416136d632994eae3cdfb4292.jpg', 'https://phimimg.com/upload/vod/20240829-1/b9a06c84b17ae76e586ff8c0c7e82f8e.jpg', '<p>Bộ phim kể về câu chuyện một nghiên cứu sinh ngành Độc học Côn trùng Đàm Cảnh Thiên vô tình bị cuốn vào một vụ án ly kỳ. Trong quá trình giúp cảnh sát phá án anh đã nảy sinh tình cảm với bác sĩ pháp y Kim Linh, đồng thời khám phá ra bí ẩn về thân thế của mình, vạch trần kẻ đứng sau đã ẩn náu nhiều năm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2020, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Khả","avatar":""},{"name":"Sở Nguyệt","avatar":""},{"name":"Đổng Kỳ","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324336);
