INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-vi-nhan-gian', 'Mỹ Vị Nhân Gian', 'Recipe Of Life', 'https://phimimg.com/upload/vod/20240829-1/da3e7a7de2ab36d54f6e8aca644eea07.jpg', 'https://phimimg.com/upload/vod/20240829-1/26c0bc4b3775b9cf2a1513eaa9dedd95.jpg', '<p>Hương vị cuộc sống là câu chuyện về những món ăn, những cố gắng giữ gìn cơ nghiệp của các thế hệ tiếp nối nghề đầu bếp truyền thống ở Singapore. Bên cạnh đó là những âm mưu, tranh giành bí quyết “Bữa tiệc vô song” huyền thoại để rồi có thể thực sự hiểu rõ phương châm ẩm thực của sư tổ Tần Phấn; “Chỉ với tấm lòng chân thật, bạn mới có thể nấu được hương vị ngon nhất từ trước đến nay - hương vị của con người.</p>', 'Hoàn Tất (66/66)', 66, 'series', 'completed', 6, 2020, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Vũ","avatar":""},{"name":"Chu Hậu Nhậm","avatar":""},{"name":"Hoàng Bích Nhân","avatar":""},{"name":"Trần Li Bình","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324336);
