INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai', 'Gai', 'Thorn', 'https://phimimg.com/upload/vod/20240829-1/566e96b103039d433755fdf08cc64fb9.jpg', 'https://phimimg.com/upload/vod/20240829-1/1fb846ab6fa1bdf2b369c9685d921d0d.jpg', '<p>Gai - Thorn là bộ phim nói về vấn đề bạo lực học đường đang rầm rộ hiện nay, bắt đầu từ khi cảnh sát Trần Thiến nhận được báo án sự kiện cô nữ sinh mất tích, trong khi sự việc vẫn còn đang điều tra thì một vụ án bắt nạt trong trường học của mười năm trước dần được hé lộ, câu chuyện cấp 3 của mười năm trước giữa Hàn Hiểu Đình, Trương Bội Lôi, Lưu Đào đan xen giữa tình bạn tình yêu, phản bội, thờ ơ, sỉ nhục, bắt nạt... đã để lại bóng ma tâm lý sâu sắc trong lòng Hàn Hiểu Đình. 10 năm sau, nhân vật chính của câu chuyện vì quan hệ công việc lại lần nữa bị số phận ghép cùng, một kế hoạch trả thù mà Hàn Hiểu Đình nung nấu dần được tiến hành. Tha thứ cho những gì nên được tha thứ và chống lại những gì nên chống lại. Chúng ta hãy học cách tự bảo vệ mình và đối mặt với nó một cách dũng cảm.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2020, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Bao Văn Tịnh","avatar":""},{"name":"Thi Thi","avatar":""},{"name":"Lý Cảm","avatar":""},{"name":"Tô Thanh","avatar":""},{"name":"Trang Thù Lăng","avatar":""},{"name":"Vương Tiểu Vỹ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324336);
