INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-dam-de-yeu', 'Can Đảm Để Yêu', 'Sister''s Palpitate With Excitement', 'https://phimimg.com/upload/vod/20240828-1/33fcf51ecf2e0599909ead7eaba27ca9.jpg', 'https://phimimg.com/upload/vod/20240828-1/edb601dbc82a826b6bba1ec6cf878db7.jpg', '<p>Bộ phim kể về câu chuyện của cô gái lãng phí Tô Di Văn vô tình gặp được người bạn trai thanh mai trúc mã từ bé Bành Hy Triết, rồi họ dấn thân vào một câu chuyện tình lãng mạn ngọt ngào và cháy bỏng khi bạn cùng phòng của Bành Hy Triết muốn mượn nhà của anh để ở với bạn gái.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 6, 2020, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Minyu Song","avatar":""},{"name":"Xinxuan Chen","avatar":""},{"name":"Xu Yue","avatar":""},{"name":"Liu Yun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324336);
