INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ba-huyen-thoai', 'Bộ Ba Huyền Thoại', 'Trident', 'https://phimimg.com/upload/vod/20240828-1/62ce8150f909c755b3266d42182fd5a6.jpg', 'https://phimimg.com/upload/vod/20240828-1/9cab9b066954a1397cb10410043543be.jpg', '<p>Bộ Ba Huyền Thoại - Trident kể về ba cảnh sát Thôi Thiết Quân, Từ Quốc Trụ, Phan Giang Hải được giới cảnh sát đặt biệt danh là “ Bộ ba huyền thoại”. Trong một lần rút lui, họ bắt gặp một vụ án rửa tiền. Tội phạm rửa tiền bất chấp các thủ đoạn để thao túng. Đối diện với hình thức phạm tội mới, cả ba đã dùng các biện pháp truyền thống để đối phó, thể hiện bản lĩnh của mình. Đối phương dùng đủ mọi cách ly gián, khiến quan hệ của “ Bộ ba huyền thoại” có lúc tưởng như sắp tan vỡ. Nhưng với tinh thần trách nhiệm cao, họ đã đồng tâm hiệp lực, phá giải thành công vụ án.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 7, 2020, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"陳建斌","avatar":""},{"name":"Dong Yong","avatar":""},{"name":"Hao Ping","avatar":""},{"name":"He Dujuan","avatar":""},{"name":"Hu Ke","avatar":""},{"name":"王驍","avatar":""},{"name":"Hou Yansong","avatar":""},{"name":"Tao Hong","avatar":""},{"name":"Rong Fei","avatar":""},{"name":"Chen Jian","avatar":""},{"name":"Geng Yizhan","avatar":""},{"name":"Ma Wenbo","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324336);
