INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-le-anh-khong-the-yeu-em', 'Có Lẽ Anh Không Thể Yêu Em', 'In Time With You', 'https://phimimg.com/upload/vod/20240827-1/aed96d9aa48f36b3fc38f12b6b08afe6.jpg', 'https://phimimg.com/upload/vod/20240827-1/6dcf7c3912ca388247ec6af3997f83d9.jpg', '<p>Ở tuổi 30, Pim đã đạt được sự cân bằng về công việc và cuộc sống. Pon là bạn thân nhất của Pim, người luôn sát cánh bên cô, sẵn sàng cho cô một bờ vai để khóc. Tất cả những người xung quanh đều nghĩ họ là cặp đôi hoàn hảo, nhưng Pim vẫn chỉ coi Pon là bạn. Trải qua nhiều thất bại trong tình yêu, liệu Pim có nhận ra tình yêu đích thực của mình đang ở rất gần?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Arak Amornsupasiri","avatar":""},{"name":"Monchanok Saengchaipiangpen","avatar":""},{"name":"Nachjaree Horvejkul","avatar":""},{"name":"วชิรวิชญ์ ชีวอารี","avatar":""},{"name":"Jack Su","avatar":""},{"name":"Noon Daran Thitakawin","avatar":""},{"name":"Warapun Nguitragool","avatar":""},{"name":"Catherine Geena Meads","avatar":""},{"name":"Nualprang Trichit","avatar":""},{"name":"ชินวุฒ อินทรคูสิน","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324336);
