INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-vuong-bat-diet', 'Quân Vương Bất Diệt', 'The King: Eternal Monarch', 'https://phimimg.com/upload/vod/20240118-1/cd969d0b570fcc37b412ccee000acc6d.jpg', 'https://phimimg.com/upload/vod/20240118-1/351b8d4fd45426740e4f7e7b711dcdc9.jpg', '<p>Cánh cổng kì bí đưa vị đế vương Đại Hàn Đế quốc thời hiện đại đến một thế giới song song. Ở thế giới ấy, anh gặp cô nàng thanh tra cảnh sát đầy nhiệt huyết.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 5, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Min Ho","avatar":""},{"name":"Kim Go Eun","avatar":""},{"name":"Woo Do Hwan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324336);
