INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-hoang-chi-than', 'Thị Hoang Chi Thần', 'God Of Deception', 'https://phimimg.com/upload/vod/20240820-1/9e8474adc203a99a1c63e68d6a7dc9e3.jpg', 'https://phimimg.com/upload/vod/20240820-1/af44a1e9692270f9c3cb41fe3ae8e1cf.jpg', '<p>Sau khi nguồn năng lượng của thế giới cạn kiệt, con người đã cho xây dựng một thành phố lớn - thành phố Faith. Học sinh trung học thành phố Faith là Ô Minh Lộ vì nói dối quá nhiều lần bị &quot;hệ thống&quot; của thành phố nhận định là kẻ ác, cũng gặp phải sự tấn công của những &quot;nghiệp chướng&quot; tà ác. Thành phố Faith phái người giám sát nói dối Liên Ân đén trợ giúp Ô Minh Lộ &quot;uốn nắn&quot; tật xấu. Sau khi gặp nhau, hai người bị cuốn vào tầng tầng cơn lốc, những bí mật không thể cho ai biết đang từ từ bị vạch trần.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"瞳音","avatar":""},{"name":"Zhen Wang","avatar":""},{"name":"叮当","avatar":""},{"name":"Ye Zhiqiu","avatar":""},{"name":"閻麼麼","avatar":""},{"name":"李蘭陵","avatar":""},{"name":"Chang Rongshan","avatar":""},{"name":"Chen Siyu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324336);
