INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-gia-tai-chinh', 'Chuyên Gia Tài Chính', 'The Banker', 'https://phimimg.com/upload/vod/20231023-1/8b08421934d3f892f77d8c73cb5c0c65.jpg', 'https://phimimg.com/upload/vod/20231023-1/5d7b9e9908ee3626224dca808358f9b9.jpg', '<p>The Banker dựa vào câu chuyện có thật ở nước Mỹ những năm 60s, khi kế hoạch làm ăn giữa 2 người da màu - Bernard Garrett và Joe Morris muốn tạo dựng một ngân hàng của riêng. Tuy tham vọng táo bạo, nhưng đó cũng là bước tiến quan trọng của cả Bernard hay Joe nói riêng, hay nhằm chứng minh tiếng nói của xã hội người da màu đang sống tại đất Mỹ. Cả 2 đã thuê một anh chàng Mỹ trắng tên Matt Steiner để làm người đại diện cho kế hoạch làm ăn lớn này. Tất nhiên lúc bấy giờ chẳng có nhà đầu tư nào chịu bắt tay với người da màu cả, và lúc này Matt mới cần để &quot;ra tay&quot;, còn Bernard và Joe tuy sẽ giả vờ làm đầy tớ cho Matt nhưng qua đó họ tính toán rất kĩ về thị trường, tiền tệ, chính phủ liên bang,...</p>', 'Full', 1, 'single', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Anthony Mackie","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Nia Long","avatar":""},{"name":"Jessie T. Usher","avatar":""},{"name":"Colm Meaney","avatar":""},{"name":"Paul Ben-Victor","avatar":""},{"name":"James DuMont","avatar":""},{"name":"Taylor Black","avatar":""},{"name":"Gregory Alan Williams","avatar":""},{"name":"Bill Kelly","avatar":""},{"name":"Jaylon Gordon","avatar":""},{"name":"Michael Harney","avatar":""},{"name":"David Maldonado","avatar":""},{"name":"Craig Welzbacher","avatar":""},{"name":"Chris Gann","avatar":""},{"name":"Daniel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324336);
