INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-gia-tai-chinh', 'Chuyên Gia Tài Chính', 'The Banker', 'chuyên gia tài chính the banker anthony mackie samuel l. jackson nicholas hoult nia long jessie t. usher colm meaney paul ben-victor james dumont taylor black gregory alan williams bill kelly jaylon gordon michael harney david maldonado craig welzbacher chris gann daniel ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-thanh-tu-kham', 'Thanh Thanh Tử Khâm', 'Qing Qing Zi Jin', 'https://phimimg.com/upload/vod/20240815-1/f77ac4915131d004c4a5a889a3e23625.jpg', 'https://phimimg.com/upload/vod/20240815-1/59ea6e69a65e0bcc9398651c61a4d231.jpg', '<p>Trong thời kỳ Càn Phù của nhà Đường, học trò nghèo Lạc Thu Trì quyết chí trở thành một nhà thơ lớn. Thông qua cuộc thi Thi Từ, Thu Trì đã vào được thư viện Trúc Tụ học hành. Sau khi Lạc Thu Trì vào trường, có bất đồng quan điểm về phong cách làm thơ với trò có thành tích đứng đầu thư viện là Phó Viễn Chi. Cuối cùng, Lạc Thu Trì đã giành chiến thắng với &quot;Lệnh Hoa Bay&quot;. Từ đó tạo nên một phong cách thơ mới theo hướng giản dị. Thư viện Trúc Tụ là nơi nuôi dưỡng, đào tạo tài năng thi nhân trẻ, gặp gỡ những anh tài khác và cả ý trung nhân của Lạc Thu Trì. Tại nơi này, Lạc Thu Trì và hội học trò cùng nhau vượt qua những khó khăn vui buồn, cùng nhau trưởng thành, và có một câu chuyện tình lãng mạn.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phạm Thế Kỹ","avatar":""},{"name":"Lữ Tiểu Vũ","avatar":""},{"name":"Vũ Đình Nhi","avatar":""},{"name":"Tạ Bân Bân","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324336);
