INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhu-y-phuong-phi', 'Như Ý Phương Phi', 'The Blooms At Ruyi Pavilion', 'https://phimimg.com/upload/vod/20240814-1/c108fc0fbfd0a9d71bc71727670af909.jpg', 'https://phimimg.com/upload/vod/20240814-1/e648d9fba657ab05d18cc40efafa187b.jpg', '<p>Nhị tiểu thư Phó Dung bỗng dưng có năng lực nhìn thấy tương lai qua giấc mơ sau một cơn bạo bệnh.

Sau khi có năng lực Phó Dung đã biết trước được việc bản thân mình sắp tới sẽ gặp tai họa và một trong số đó chính là bị gả cho Túc Vương Từ Tấn. Chưa dừng ở mức phải lấy một tên mà mình không hề có tình cảm, nàng còn sẽ bị tuẫn táng (tục chôn người sống theo người chết) cùng hắn.

Không để cho số phận đưa đẩy mình, Phó Dung quyết thay đổi nó bằng cách trốn tránh quyết không gả cho Từ Tấn. Và rồi nàng lại không ngờ rằng Từ Tấn cũng có năng lực nhìn thấy được tương lai qua giấc mơ giống như nàng, dù biết trước kết cục nhưng hắn vẫn truy tìm Phó Dung với mong muốn được bù đắp cho nàng một tình yêu đúng nghĩa.</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"鞠婧禕","avatar":""},{"name":"Zhang Zhehan","avatar":""},{"name":"Liu Yichang","avatar":""},{"name":"Wang Youshuo","avatar":""},{"name":"Xu Jia Qi","avatar":""},{"name":"Jiang Shan","avatar":""},{"name":"王奕婷","avatar":""},{"name":"Yang Gen","avatar":""},{"name":"Song Xinran","avatar":""},{"name":"Gong Beibi","avatar":""},{"name":"斕曦","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324336);
