INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-sinh-xinh-dep', 'Thư Sinh Xinh Đẹp', 'In A Class of Her Own', 'https://phimimg.com/upload/vod/20240814-1/0b5aadbd5744ffb6443cb0a8cb7c71c0.jpg', 'https://phimimg.com/upload/vod/20240814-1/d74bc3aa86103cf2da24af582ed54253.jpg', '<p>Thư Sinh Xinh Đẹp là bộ phim kể về Tuyết Văn Hi xuất thân nghèo nàn, quyết định nữ cải nam trang chép sách để kiếm sống. Nhưng vô tình cô gặp phải con trai của thừa tướng Vân Quốc là Phong Thừa Tuấn, về sau Phong Thừa Tuấn giúp đỡ mới có thể bước vào học đường, Tuyết Vân Hi yên tâm học tập, sức hấp dẫn từ nhân cách mạnh mẽ của nàng đã giúp Vũ Lạc Huyên ngỗ ngược tìm lại được tôn nghiêm của mình.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"鞠婧禕","avatar":""},{"name":"Song Weilong","avatar":""},{"name":"畢雯珺","avatar":""},{"name":"王瑞昌","avatar":""},{"name":"Chen Yilong","avatar":""},{"name":"Zhu Shengyi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324336);
