INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-dung-gap-anh-ay', 'Xin Đừng Gặp Anh Ấy', 'Please Don''t Date Him', 'https://phimimg.com/upload/vod/20240815-1/6a1b277d0d1bb23eac665f4f7ad68909.jpg', 'https://phimimg.com/upload/vod/20240815-1/9aa8643ac64c789eb68693362c5fb80d.jpg', '<p>Xin Đừng Gặp Anh Ấy kể về Seo Ji Seong muốn yêu nhưng cũng muốn tránh những lựa chọn sai lầm. Để tạo ra cuộc sống tình yêu hoàn hảo, cô ấy tạo ra một chương trình trí tuệ nhân tạo có tên Jo Sang Shin. Seo Ji Sung là lập trình viên của nhóm phát triển thiết bị gia dụng thông minh AI. Một ngày nọ, cô vô tình phát triển một chương trình AI có tên Cho Sang Shin, chương trình này sẽ xác định những con người rác rưởi, và cô sử dụng nó để cứu những người đang gặp khó khăn trong mối quan hệ. Jung Kook Hee là một lính cứu hỏa không sử dụng mạng xã hội. Anh ấy là người duy nhất mà Jo Sang Shin không thể phân tích được.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"송하윤","avatar":""},{"name":"이준영","avatar":""},{"name":"윤보미","avatar":""},{"name":"공민정","avatar":""},{"name":"주우재","avatar":""},{"name":"Nam Min-woo","avatar":""},{"name":"Kim Gi-ri","avatar":""},{"name":"이시훈","avatar":""},{"name":"Park Han-sol","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324336);
