INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-dam-moc', 'Cú Đấm Móc', 'Hook', 'https://phimimg.com/upload/vod/20240811-1/b4160778c8bfa955e3046c661ee11105.jpg', 'https://phimimg.com/upload/vod/20240811-1/7acb5f94248d36dcfd5ac541e7d26d52.jpg', '<p>Bất chấp sự ganh đua của cha mình, hai sinh viên đại học đã kết bạn tại một phòng tập đấm bốc khi họ giải quyết những rắc rối trong gia đình, chuyện tình cảm và khủng hoảng cá nhân.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 4, 2020, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jidapa Siribunchawan","avatar":""},{"name":"Peemapol Panichtamrong","avatar":""},{"name":"พีรวิชญ์ อรรถชิตสถาพร","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324336);
