INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pham-nhan-tu-tien-phan-1', 'Phàm Nhân Tu Tiên (Phần 1)', 'A Record of a Mortal''s Journey to Immortality (Season 1)', 'https://phimimg.com/upload/vod/20240809-1/89de2a05f1812cc7bf25bf85c46106b8.jpg', 'https://phimimg.com/upload/vod/20240809-1/014973a758de9bf3749c1229c465f418.jpg', '<p>Hàn Lập vốn là một thiếu niên sống trong sơn thôn, tư chất bình thường lại gặp vô vàn cơ duyên để bước đi trên con đường tu tiên. Hàn Lập từng bước khẳng định mình trong hàng ngũ tiên nhân. Mối tình gian truân của Hàn Lập và hồng nhan tri kỷ của chàng cuối cùng liệu có cái kết hoàn mỹ? Những thử thách nào đang chờ đợi bọn họ?</p>', 'Hoàn Tất (21/21)', 21, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"錢文靑","avatar":""},{"name":"宋伊人","avatar":""},{"name":"李詩萌","avatar":""},{"name":"徐佳琦","avatar":""},{"name":"Yang Mo","avatar":""},{"name":"谷江山","avatar":""},{"name":"喬詩語","avatar":""},{"name":"Fuzheng Zhang","avatar":""},{"name":"Liangwei Hu","avatar":""},{"name":"Rui Liu","avatar":""},{"name":"He Ba","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324336);
