INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-phat-ma-nu-ngoai-truyen', 'Bạch Phát Ma Nữ Ngoại Truyện', 'The Wolf Witch', 'https://phimimg.com/upload/vod/20240804-1/74336dfdde395fed4cc1d3b81932fd96.jpg', 'https://phimimg.com/upload/vod/20231013-1/7fde4558587da16293a02caafd1f875f.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Kể câu chuyện về những năm cuối cùng của Trùng Trấn trong triều đại nhà Minh, do nữ quỷ tóc trắng Lian Nei lãnh đạo, gây ra một cơn bão đẫm máu trên sông hồ, và hợp nhất với Ninja Ji của Dongying Jia He để thành lập &quot;Phái Hehuan&quot;, trong một thời gian tất cả các giáo phái ở khắp mọi nơi đều do phe Hehuan đứng đầu, và giáo phái tử tế Minh Môn đang ở trong xu hướng &quot;thiện và ác&quot;, phạm tội ác và chia rẽ một bên. Jinyiwei Chang&#39;an được lệnh điều tra hành tung của mụ phù thủy tóc trắng, nhưng phát hiện ra rằng sự thật phức tạp hơn nhiều so với tưởng tượng....</span></p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Huang Yi","avatar":""},{"name":"Shi Junzhe","avatar":""},{"name":"Yuan Zhiying","avatar":""},{"name":"Liu Shuo","avatar":""},{"name":"Du Yuming","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324336);
