INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-y-diem-the', 'Manh Y Điềm Thê', 'Dr. Cutie', 'https://phimimg.com/upload/vod/20240804-1/733320d5f6a2959858dc67929edd81a4.jpg', 'https://phimimg.com/upload/vod/20240804-1/24c6006e6b4df0f48e3d22339017edba.jpg', '<p>Để trả thù Điền Thất vào cung điện cải trang thành đàn ông. Nhờ khả năng đặc biệt của mình, cô được Hoàng đế sủng ái và trở thành thái giám riêng của ông. Khi Tian Qi và Hoàng đế dành thời gian bên nhau, Hoàng đế phát hiện ra cô là một cô gái. Thì ra Điền Thất là con gái của Bộ trưởng Kỷ Thanh Vân, tên là Kỷ Thiếu. Bảy năm trước, Ji Qingyun bị các quan tham nhũng gài bẫy và gia đình anh bị kết án tử hình. Chỉ có con gái của ông, Ji Shao sống sót. Hoàng đế yêu Ji Shao nên quyết định phong cô làm Hoàng hậu. Tuy nhiên, Ji Shao, người đang bị gánh nặng bởi hành trình trả thù, bắt đầu nảy sinh những tình cảm phức tạp và đau đớn với Hoàng đế.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sun Qian","avatar":""},{"name":"黃俊捷","avatar":""},{"name":"Zha Jie","avatar":""},{"name":"Hong Shan Shan","avatar":""},{"name":"劉哲琿","avatar":""},{"name":"Tong Zhang","avatar":""},{"name":"Mou Fengbin","avatar":""},{"name":"Dong Kefei","avatar":""},{"name":"Yang Di","avatar":""},{"name":"Guo Zi Yu","avatar":""},{"name":"Yang Yitong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324336);
