INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-hau', 'Chàng Hậu', 'Mr Queen', 'https://phimimg.com/upload/vod/20240731-1/23bd0dfa7f983cfe4a5bf8001684f393.jpg', 'https://phimimg.com/upload/vod/20240731-1/6794436af2a0f5e6f9e2626ceb37e640.jpg', '<p>Jang Bong Hwan, một đầu bếp tài năng sống ở thời hiện đại, vô tình đi xuyên không trở về quá khứ do một tai nạn bất ngờ và bị mắc kẹt trong cơ thể của Hoàng hậu Kim So Yong. Hàng loạt những câu chuyện bi hài từ đây bắt đầu.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shin Hye-sun","avatar":""},{"name":"Kim Jung-hyun","avatar":""},{"name":"Bae Jong-ok","avatar":""},{"name":"Kim Tae-woo","avatar":""},{"name":"Seol In-a","avatar":""},{"name":"Na In-woo","avatar":""},{"name":"Cha Chung-hwa","avatar":""},{"name":"Chae Seo-eun","avatar":""},{"name":"Kim In-kwon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324336);
