INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-diet-vong-phan-2', 'Biệt Đội Diệt Vong (Phần 2)', 'Doom Patrol (Season 2)', 'https://phimimg.com/upload/vod/20240729-1/89ef935ba3812f5a1abd8290b9b45f38.jpg', 'https://phimimg.com/upload/vod/20240729-1/536e9b646b34fad7f83ac5e3ade5f2ee.jpg', '<p>Doom Patrol là loạt phim truyền hình web của Mỹ được tạo bởi Jeremy Carver cho DC Universe. Dựa trên nhóm siêu anh hùng cùng tên của DC Comics, bộ truyện có Jane, Rita Farr, Vic Stone, Larry Trainor, Cliff Steele, và Chief là thành viên của Doom Patrol. Lấy bối cảnh năm 2019, nhóm Doom Patrol - bao gồm Robotman, Negative Man, Elasti-Woman, Crazy Jane cùng thành viên mới Cyborg dưới sự dẫn dắt của Dr. Niles Caulder - nhận nhiệm vụ bảo vệ thế giới khỏi kẻ thù nguy hiểm tên là Mr. Nobody.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 6, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Diane Guerrero","avatar":""},{"name":"April Bowlby","avatar":""},{"name":"Joivan Wade","avatar":""},{"name":"Skye Roberts","avatar":""},{"name":"Riley Shanahan","avatar":""},{"name":"Matthew Zuk","avatar":""},{"name":"Matt Bomer","avatar":""},{"name":"Brendan Fraser","avatar":""},{"name":"Michelle Gomez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324336);
