INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-tu-nam-ca-the-song-of-glory', 'Cẩm Tú Nam Ca - The Song of Glory', 'The Song of Glory', 'https://phimimg.com/upload/vod/20240729-1/b5592905fd4099699cab341ae6d3185e.jpg', 'https://phimimg.com/upload/vod/20240729-1/cdd30ed912490c107a358e19da5eaa15.jpg', '<p>Giám quốc Lưu Nghĩa Khang (Tần Hạo) vì vây cánh chưa mạnh nên quyết định bước ra chốn giang hồ để thay đổi thời cuộc, nhờ đó quen biết và gặp gỡ vị nữ hiệp Thẩm Ly Ca. Lưu Nghĩa Khang và Ly Ca cùng nhau liên thủ chống lại Sỹ Tộc Lục Gia, sau khi cùng nhau trải qua bao biến cố và hiểm nguy hai người dần dần nảy sinh tình cảm.</p>', 'Hoàn Tất (53/53)', 53, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"李沁","avatar":""},{"name":"秦昊","avatar":""},{"name":"Jason Koo","avatar":""},{"name":"Qi Ji","avatar":""},{"name":"Guan Xueying","avatar":""},{"name":"張兆輝","avatar":""},{"name":"Deng Ying","avatar":""},{"name":"Yameng Zhang","avatar":""},{"name":"田曦薇","avatar":""},{"name":"Chen Qianduo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324336);
