INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-toc-mai-khong-phai-hai-duong-hong', 'Bên Tóc Mai Không Phải Hải Đường Hồng', 'Winter Begonia', 'https://phimimg.com/upload/vod/20240729-1/d5d5a1e5d197320130adcfcefc4db6aa.jpg', 'https://phimimg.com/upload/vod/20240729-1/d4fcf0d32227e6dcc386f510fe5c47fd.jpg', '<p>Là một bộ phim truyền hình Trung Quốc của đạo diễn Vu Chính. Bộ phim được làm lại từ bộ tiểu thuyết Trung Quốc nổi tiếng cùng tên lấy bổi cảnh thời kỳ chiến tranh Trung Quốc chống Nhật Bản . Phim có sự góp mặt của nhiều diễn viên nổi tiếng như Huỳnh Hiểu Minh, Doãn Chính, Xa Thi Mạn,…

Lấy bối cảnh Bắc Đình (Trung Quốc) vào những năm 1930 lúc cuộc chiến giữa Trung Quốc và Nhật Bản đang trong giai đoạn căng thẳng. Bên tóc mai không phải hải đường hồng là một câu chuyện tình vừa ngọt ngào vừa đau khổ lại vừa đắng cay của một thương nhân yêu nước Trình Phượng Đài (Huỳnh Hiểu Minh đóng) với chàng đào kép tài năng Thương Tế Nhị (Doãn Chính). Hai người đàn ông những tưởng là hai đường thẳng song song, hai thế giới đối lập không liên quan gì với nhau, ấy vậy mà cuối cùng họ lại sát cánh bên nhau, vì mục tiêu chống giặc ngoại xâm, hy sinh cho Tổ quốc.</p>', 'Hoàn Tất (49/49)', 49, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"黃曉明","avatar":""},{"name":"尹正","avatar":""},{"name":"Charmaine Sheh","avatar":""},{"name":"米熱","avatar":""},{"name":"Liu Min","avatar":""},{"name":"李澤鋒","avatar":""},{"name":"檀兮爾","avatar":""},{"name":"金士傑","avatar":""},{"name":"唐曾","avatar":""},{"name":"汪汐潮","avatar":""},{"name":"Li Chun''ai","avatar":""},{"name":"Anna Fang","avatar":""},{"name":"Huang Shengyi","avatar":""},{"name":"Du Chun","avatar":""},{"name":"白冰","avatar":""},{"name":"Yixi Zhang","avatar":""},{"name":"He Ruixian","avatar":""},{"name":"Chi Shuai","avatar":""},{"name":"王茂蕾","avatar":""},{"name":"Hei Zi","avatar":""},{"name":"Ma Su","avatar":""},{"name":"湯晶媚","avatar":""},{"name":"Gao Yuer","avatar":""},{"name":"陳都靈","avatar":""},{"name":"Huang Xing Yuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324336);
