INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meo-von-chuot-phan-3', 'Mèo Vờn Chuột (Phần 3)', 'Killing Eve (Season 3)', 'https://phimimg.com/upload/vod/20240729-1/cc52514702736edec6419b93d80afbcb.jpg', 'https://phimimg.com/upload/vod/20240729-1/7337500ab75daeab9f230585aee27f97.jpg', '<p>Sau khi bị Villanelle bắn trọng thương, Eve chật vật tìm cách ổn định lại cuộc sống của mình. Villanelle cũng cố quên đi mọi chuyện, cho đến khi một kẻ thù cũ xuất hiện. Dù đã cố gắng đường ai nấy đi, nhưng số phận lại một lần nữa khiến cả hai gặp lại nhau.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sandra Oh","avatar":""},{"name":"Jodie Comer","avatar":""},{"name":"Fiona Shaw","avatar":""},{"name":"Kim Bodnia","avatar":""},{"name":"Camille Cottin","avatar":""},{"name":"Robert Gilbert","avatar":""},{"name":"Anjana Vasan","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324336);
