INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-duong-con-nuoi', 'Bố Đường Con Nuôi', 'Sugar Daddy vs Sugar Baby', 'https://phimimg.com/upload/vod/20240724-1/044fcf71c719817e76c3c815fc615f6d.jpg', 'https://phimimg.com/upload/vod/20240724-1/406bf6480e66b70da32d1251edbabe8b.jpg', '<p>Thân phận hai sugar baby trong thế giới bí ẩn của “bố đường” với những hợp đồng tình-tiền bạc triệu, bí kíp &quot;nuôi con&quot; của các quý ông và nghệ thuật bóc phốt tinh vi của các quý bà.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 15, 2020, 'Vietsub', 'FullHD', 'Quốc Gia Khác', 0, '[{"name":"Thùy Trâm","avatar":""},{"name":"Quyên Qui","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324336);
