INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-nguoi-thu-nghiem-phan-7', '100 Người Thử Nghiệm (Phần 7)', 'The 100 (Season 7)', 'https://phimimg.com/upload/vod/20240616-1/24fe679ffbe64145c557c14509f103cc.jpg', 'https://phimimg.com/upload/vod/20240616-1/b166336361aef29873617befb6b8e79c.jpg', '<p>Sau khi đến một hành tinh mới, các anh hùng của chúng ta đã tìm thấy một nơi mà họ hy vọng có thể thử lại. Clarke và Bellamy dẫn đầu một nhóm xuống thế giới bí ẩn này để bắt đầu lại, nhưng không phải mọi thứ trên Sanctum đều hoàn hảo như người ta tưởng. Bất chấp quyết tâm làm tốt hơn, những mối đe dọa cả hữu hình và vô hình một lần nữa buộc họ phải chiến đấu vì mạng sống và tương lai của nhân loại.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2020, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Eliza Taylor","avatar":""},{"name":"Bob Morley","avatar":""},{"name":"Lindsey Morgan","avatar":""},{"name":"Marie Avgeropoulos","avatar":""},{"name":"Richard Harmon","avatar":""},{"name":"Tasya Teles","avatar":""},{"name":"Shannon Kook","avatar":""},{"name":"Chuku Modu","avatar":""},{"name":"JR Bourne","avatar":""},{"name":"Shelby Flannery","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324336);
