INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luu-ly-my-nhan-sat', 'Lưu Ly Mỹ Nhân Sát', 'Love And Redemption', 'https://phimimg.com/upload/vod/20240609-1/bb0c6baf151a315cbf03d5ea748e6edc.jpg', 'https://phimimg.com/upload/vod/20240609-1/f8e58037126dd8a19a2939d2617fe1f6.jpg', '<p>Lưu Ly là bộ phim tiên hiệp cổ trang chuyển thể từ tiểu thuyết cùng tên của tác giả Thập Tứ Lang với sự tham gia của cặp đôi Viên Băng Nghiên - Thành Nghị. Câu chuyện xoay quanh Toàn Cơ - Tư Phượng và mối lương duyên 10 kiếp nhiều khổ ải của 2 nhân vật.</p>', 'Hoàn Tất (59/59)', 59, 'series', 'completed', 5, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"ChengYi","avatar":""},{"name":"YuanBingYan","avatar":""},{"name":"Liu Xueyi","avatar":""},{"name":"Zhang Yuxi","avatar":""},{"name":"Bai Shu","avatar":""},{"name":"Hou Mengyao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324336);
