INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-nan-nhan-phan-1', 'Trò Chơi Nạn Nhân (Phần 1)', 'The Victims'' Game (Season 1)', 'https://phimimg.com/upload/vod/20240622-1/8c4d063317db8aefe94de8fce6ee1776.jpg', 'https://phimimg.com/upload/vod/20240622-1/903589254494ba7fa573e2b08a191a1f.jpg', '<p>Trò Chơi Nạn Nhân là câu chuyện phát hiện cô con gái vốn không thân thiết với mình dính dáng đến những vụ giết người bí ẩn, vị thanh tra pháp y mắc hội chứng Asperger mạo hiểm tất cả để tìm ra lời giải.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2020, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"張孝全","avatar":""},{"name":"許瑋甯","avatar":""},{"name":"Wang Shih-Sian","avatar":""},{"name":"Tarcy Su","avatar":""},{"name":"Dean Fujioka","avatar":""},{"name":"李沐","avatar":""},{"name":"Terrance Lau","avatar":""},{"name":"Tsai-Hsing Chang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324336);
