INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ngay-tuoi-dep', 'Những Ngày Tươi Đẹp', 'All the Bright Places', 'https://phimimg.com/upload/vod/20231117-1/1ad50eff50c39860618ddd7ee7afbcdb.jpg', 'https://phimimg.com/upload/vod/20231117-1/525bc63b24bc72fd37f450a327dd18e3.jpg', '<p>Sau khi gặp nhau, hai người phải vật lộn với những vết sẹo về tình cảm và thể xác trong quá khứ. Họ phát hiện ra rằng ngay cả những khoảnh khắc nhỏ nhất cũng có thể có ý nghĩa.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elle Fanning","avatar":""},{"name":"Justice Smith","avatar":""},{"name":"Alexandra Shipp","avatar":""},{"name":"Kelli O''Hara","avatar":""},{"name":"Lamar Johnson","avatar":""},{"name":"Virginia Gardner","avatar":""},{"name":"Felix Mallard","avatar":""},{"name":"Sofia Hasmik","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Chris Grace","avatar":""},{"name":"John Ivers","avatar":""},{"name":"Sharon Ivers","avatar":""},{"name":"Isabella Fay","avatar":""},{"name":"Nicole Forester","avatar":""},{"name":"Sara Katrenich","avatar":""},{"name":"Alex Hayd","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324336);
