INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-ngay-tuoi-dep', 'Những Ngày Tươi Đẹp', 'All the Bright Places', 'những ngày tươi đẹp all the bright places elle fanning justice smith alexandra shipp kelli o''hara lamar johnson virginia gardner felix mallard sofia hasmik keegan-michael key luke wilson chris grace john ivers sharon ivers isabella fay nicole forester sara katrenich alex hayd ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuc-no-hoa-cuc-cung', 'Cục Nợ Hóa Cục Cưng', 'Pawn', 'https://phimimg.com/upload/vod/20231211-1/2addb6aae6996229bfffb34dbece9918.jpg', 'https://phimimg.com/upload/vod/20231211-1/69c319c268c93c075693d316b23035ac.jpg', '<p>Cục Nợ Hóa Cục Cưng là câu chuyện về một gia đình “kì lạ” lấy bối cảnh vào năm 1993 ở Incheon. Du-seok và Jong-bae là hai gã chuyên đòi nợ thuê có máu mặt. Để uy hiếp một con nợ, cả hai đã giữ Seung-yi - một bé gái 9 tuổi làm vật thế chấp cho số nợ của mẹ cô bé. Tuy nhiên, mẹ của Seung-yi lại bị trục xuất, và hai ông chú đành nhận trách nhiệm trông chừng Seung-yi đến khi cô bé được một gia đình giàu có và tử tế nhận nuôi. Khi phát hiện ra Seung-yi nhỏ bé bị bán đi làm công cho một bà chủ vô trách nhiệm, Du-seok và Jong-bae đã tìm đến để chuộc lại cô. Mặc dù Seung-yi vốn là &quot;cục nợ&quot; Du-seok và Jong-bae không hề mong muốn, cô bé dần trở thành cục cưng yêu quý và cả 3 sống bên nhau như một gia đình.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Dong-il Sung","avatar":""},{"name":"Hee-won Kim","avatar":""},{"name":"Ha Ji-Won","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324336);
