INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-amami-oshima', 'Đảo Amami Oshima', 'Amami Oshima Island', 'https://phimimg.com/upload/vod/20240616-1/74cac3ddf1f1ab281663a1821e0fe8ee.jpg', 'https://phimimg.com/upload/vod/20240616-1/cf7784372928b6777bee09cc5902597b.jpg', '<p>Amami Oshima nằm ở Biển Đông, khu vực giữa Kyushu và Okinawa . Với khí hậu ấm áp tương tự như đảo Okinawa, những bãi biển cát trắng, rạn san hô tuyệt đẹp và nước biển trong vắt, hòn đảo này là một trong những địa điểm lặn với ống thở và lặn với bình dưỡng khí được nhiều người yêu thích nhất của Nhật Bản.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324336);
