INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-ma-vuong-phan-1', 'Học Viện Ma Vương (Phần 1)', 'The Misfit Of Demon King Academy (Season 1)', 'https://phimimg.com/upload/vod/20240611-1/201d1314cff4f83e4c06eaf5eb52a196.jpg', 'https://phimimg.com/upload/vod/20240611-1/62c2fa26e0f3003831a9394e69d6998e.jpg', '<p>Mặc dù có khát khao hủy diệt, nhưng đôi lúc quỷ vương cũng phải đắn đo quyết định chứ nhỉ? Câu chuyện kể về ma vương Anoth tái sinh với hi vọng có một cuộc sống yên bình hơn nhưng cuối cùng, yên bình đâu không thấy... lại bị lọt đến trường học, rồi phải học cùng con cháu trong lâu đài cổ 2000 năm sau. Nhưng với phép thuật thời đại mới, không ai có thể xác định được sức mạnh thực sự của Anoth là bao nhiêu cả.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"楠木ともり","avatar":""},{"name":"夏吉ゆうこ","avatar":""},{"name":"梅原裕一郎","avatar":""},{"name":"寺島拓篤","avatar":""},{"name":"稗田寧々","avatar":""},{"name":"渡部紗弓","avatar":""},{"name":"久野美咲","avatar":""},{"name":"羽多野渉","avatar":""},{"name":"阿澄佳奈","avatar":""},{"name":"小山力也","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324336);
