INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anne-toc-do-phan-3', 'Anne Tóc Đỏ (Phần 3)', 'Anne with an E (Season 3)', 'https://phimimg.com/upload/vod/20240607-1/4d355bde3a0cd0d2dc1e4b357df0c203.jpg', 'https://phimimg.com/upload/vod/20240607-1/6268bcc0ec7737e35e7e40c6addadef7.jpg', '<p>Cuộc phiêu lưu của một cô gái mồ côi trẻ sống vào cuối thế kỷ 19. Theo Anne khi cô học cách điều hướng cuộc sống mới của mình trên đảo Hoàng tử Edward, trong tác phẩm mới này về tiểu thuyết kinh điển của L.M Montgomery.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Amybeth Mcnulty","avatar":""},{"name":"Geraldine James","avatar":""},{"name":"Lucas Jade Zumann","avatar":""},{"name":"Jonathan Holmes","avatar":""},{"name":"Christian Martyn","avatar":""},{"name":"Joanna Douglas","avatar":""},{"name":"R.h. Thomson","avatar":""},{"name":"Dalila Bela","avatar":""},{"name":"Corrine Koslo","avatar":""},{"name":"Aymeric Jett Montaz","avatar":""},{"name":"Helen Johns","avatar":""},{"name":"Kyla Matthews","avatar":""},{"name":"Lia Pappas-Kemps","avatar":""},{"name":"Jacob Ursomarzo","avatar":""},{"name":"Dalmar Abuzeid","avatar":""},{"name":"Miranda M","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324336);
