INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nien-thu', 'Niên Thú', 'NIAN', 'https://phimimg.com/upload/vod/20240604-1/4d5b5b2dc8eeef5f83ac357a116d67c6.jpg', 'https://phimimg.com/upload/vod/20240604-1/567c4a356f536273cb601dc7c252d30b.jpg', '<p>Hương vị ngày tết ở Hồ gia trang dần trở lên nhạt nhòa, nóng lạnh bất thường. La Xuyên là một thiếu niên múa Lân có tính cách sôi nổi, mơ ước phát triển nghệ thuật múa lân lên một tầm cao mới. Tuy nhiên, cậu thường chữa lợn lành thành lợn què và trong mắt thôn trưởng Hồ Trưởng Lễ thì cậu là một “phần tử nguy hiểm”. Niên Thú Tiểu Ngũ tình cờ giáng xuống trần gian, lấy đi bảo vật gia truyền – đầu lân. La Xuyên đi tìm đầu lân, Chuột Tiên hạ phàm bắt Niên Thú, hai người quen biết nhau, sau đó dần dần phát hiện ra Niên Thú không hề đáng sợ chút nào. Thế nhưng, vì quá lo lắng cho thôn làng nên Hồ Trưởng Lễ đã bị Phệ Linh Yêu mê hoặc, mất hết lí trí, và đã bày ra một âm mưu nhằm vào Niên Thú…</p>', 'Full', 1, 'single', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Chuang","avatar":""},{"name":"Jiang Peng","avatar":""},{"name":"Lu Yan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324336);
