INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-vo-lua', 'Người Vợ Lửa', 'Lady''s Vendetta', 'https://phimimg.com/upload/vod/20240602-1/dc3445154790b8f5c5cc01ba4a9c7ab4.jpg', 'https://phimimg.com/upload/vod/20240602-1/7602f4dde84d10c7e329c9c3e7d1e9dd.jpg', '<p>Người Vợ Lửa - Lady&#39;s Vendetta kể về Kingchan - cô bé bị bỏ rơi dưới gốc cây Chan Poh và đã được ông trưởng làng Sanit nhận nuôi. Vì mâu thuẫn gia đình, Sriprapai, con gái ông Sanit và nhân tình của cô ta quyết định đưa Kingchan vào cung điện Waradul. Sau khi vào cung điện, Kingchan đã gặp Rungwigrai - con trai của ngài Issaresgunthorn Waradul và người vợ cả, cậu đang được mẹ kế của mình là Sriprapai chăm sóc.Rungwigrai ngay lập tức đem lòng yêu thương Kingchan nhưng cô lại yêu Klao, một tên người hầu ở trong điện. Thậm chí cả hai còn nguyện ước sẽ mãi mãi yêu và ở bên nhau. Cô đã thực sự oán hận Ringwigrai vì đã cưỡng hiếp cô. Vì vậy, cô đã quyết định bỏ trốn cùng với Klao. Biết tin, Rungwigrai đã sai thuộc hạ của mình truy đuổi và hành hung Klao cho đến chết. Lúc này, nỗi căm hận trong lòng Kingchan lên đến đỉnh điểm.Kingchan quyết định quay trở lại cung điện Waradul, kết hôn với Rungwigrai để tìm cơ hội trả thù tất cả những kẻ đã làm tổn thương cô.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 9, 2020, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Amina Kun","avatar":""},{"name":"Kalida Kalampan","avatar":""},{"name":"Niridon Pomsuwan","avatar":""},{"name":"Sornram Thepphithat","avatar":""},{"name":"Tharaket Pesuksai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324336);
