INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-hon-nhan', 'Thế Giới Hôn Nhân', 'The World Of The Married', 'https://phimimg.com/upload/vod/20240521-1/3a415b9da61ebc3aff4f44b844d16080.jpg', 'https://phimimg.com/upload/vod/20240521-1/7732bf52fdbb78ebba1c58cd49f2580e.jpg', '<p>Bộ phim xoay quanh Ji Sun-Woo - một bác sĩ y khoa gia đình. Cô kết hôn với Lee Tae-O và có một con trai. Mọi người nhìn cô với ánh mắt đầy ngưỡng mộ vì dường như có tất cả mọi thứ mà người phụ nữ nào cũng mơ ước: một sự nghiệp thành công và một gia đình hạnh phúc. Nhưng hiện thực đắng cay muôn phần, Sun Woo bị chồng và những người thân yêu phản bội.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Hae Joon","avatar":""},{"name":"Kim Young Min","avatar":""},{"name":"Kim Hee Ae","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324336);
