INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('greenland-tham-hoa-thien-thach', 'Greenland: Thảm Họa Thiên Thạch', 'Greenland', 'https://phimimg.com/upload/vod/20231103-1/595adfb43a19255d6c1cc0bfd0a38286.jpg', 'https://phimimg.com/upload/vod/20231103-1/041ba4cdae662f27a3bfbb715efc7fe5.jpg', '<p>Trước thảm họa thiên thạch liên tiếp rơi xuống Trái đất và phá hủy tất cả mọi thứ nơi nó đi qua, John Garrity quyết tâm đưa vợ Allison, cùng con trai Nathan tìm đường trốn đến nơi trú ẩn an toàn - Greenland - hy vọng sống sót duy nhất của tất cả trước khi quá muộn. Mặt khác, họ phải cạnh tranh với những con người cũng đang tìm cách sinh tồn bằng mọi giá.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Morena Baccarin","avatar":""},{"name":"David Denman","avatar":""},{"name":"Hope Davis","avatar":""},{"name":"Roger Dale Floyd","avatar":""},{"name":"Scott Glenn","avatar":""},{"name":"Andrew Bachelor","avatar":""},{"name":"Merrin Dungey","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Gary Weeks","avatar":""},{"name":"Tracey Bonner","avatar":""},{"name":"Joshua Mikel","avatar":""},{"name":"Cate Jones","avatar":""},{"name":"Mike Gassaway","avatar":""},{"name":"Anissa Matlock","avatar":""},{"name":"Randall Archer","avatar":""},{"name":"Scott Poythress","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324336);
