INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-than-thuong-vo', 'Tinh Thần Thượng Võ', 'Justice High', 'https://phimimg.com/upload/vod/20240507-1/e8c28b709760365f3508b3de133fbd70.jpg', 'https://phimimg.com/upload/vod/20240507-1/e116bab6886deec1f2dbd5c0f847f1e2.jpg', '<p>Hôm nay là ngày đầu tiên Chae-young chính trực chuyển đến trường sau khi bị một kẻ bắt nạt đánh bại. Bất chấp lời cảnh báo của người cha, cô lại cứu bạn cùng lớp Jong-gu khỏi những kẻ bắt nạt. Bị thu hút bởi cô ấy, Jong-gu hỏi làm thế nào để trở nên mạnh mẽ như cô ấy.</p>', 'Full', 1, 'single', 'completed', 5, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jeong Da-eun","avatar":""},{"name":"Oh Seung-hoon","avatar":""},{"name":"Son Woo-hyeon","avatar":""},{"name":"Yoo Hyun-jong","avatar":""},{"name":"Jung Eui-wook","avatar":""},{"name":"Kim Tae-yoon","avatar":""},{"name":"Kang Jeong-won","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324336);
