INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-dep-dich-thuc', 'Vẻ Đẹp Đích Thực', 'True Beauty', 'https://phimimg.com/upload/vod/20240502-1/814fcd3d185340ea870b8f69c60cfa4a.jpg', 'https://phimimg.com/upload/vod/20240502-1/54c6065838ae6ff4bab415aa60dbe697.jpg', '<p>Vẻ Đẹp Đích Thực xoay quanh nhân vật chính là Im Joo Kyung. Cô là một nữ sinh có ngoại hình tầm thường và luôn mặc cảm về khuôn mặt mình. Tuy nhiên kể từ khám phá ra năng khiếu trang điểm của bản thân, Joo Kyung lột xác thành một hotgirl xinh đẹp và nổi tiếng trên MXH. Kéo theo muôn vàn rắc rối bi hài khi cô vừa phải tìm cách che giấu khuôn mặt thật, vừa phải giữ được hình tượng lung linh trước mọi người. Cùng lúc đó, 2 chàng trai “đẹp hơn hoa” lại vướng vào lưới tình với Joo Kyun. Một bên là Lee Suho, con trai của diễn viên điện ảnh nổi tiếng nhưng lại che giấu mình dưới vỏ bọc nam sinh gương mẫu ở trường. Bên còn lại là Han Seo Joon, một anh chàng người mẫu cá tính, táo bạo.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Moon Ga-young","avatar":""},{"name":"Cha Eun-woo","avatar":""},{"name":"Hwang In-yeop","avatar":""},{"name":"Park You-na","avatar":""},{"name":"Lim Se-mi","avatar":""},{"name":"Park Ho-san","avatar":""},{"name":"Jang Hye-jin","avatar":""},{"name":"Oh Eui-sik","avatar":""},{"name":"Kim Min-ki","avatar":""},{"name":"Kang Min-ah","avatar":""},{"name":"Lee Woo-je","avatar":""},{"name":"Yoon Seo-ah","avatar":""},{"name":"Jeon Hye-won","avatar":""},{"name":"Yeo Joo-ha","avatar":""},{"name":"Lee Il-jun","avatar":""},{"name":"Lee Joo-Ahn","avatar":""},{"name":"Lee Sang-jin","avatar":""},{"name":"Kim Hyun-Ji","avatar":""},{"name":"Han Yi Young","avatar":""},{"name":"Jeong J","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324336);
