INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mashimaro-phan-3', 'Mashimaro (Phần 3)', 'Mashimaro (Season 3)', 'https://phimimg.com/upload/vod/20240308-1/8bcc84d8e3517ed2e291fe6038c0be9e.jpg', 'https://phimimg.com/upload/vod/20240308-1/9bda616510cf280c07df3f876b4495b2.jpg', '<p>Mashimaro bắt đầu “dấn thân” vào cuộc sống nơi công sở với nhiều trải nghiệm mới. Môi trường mới sẽ phát sinh nhiều tình huống khó đỡ, Mashimaro và các bạn đồng nghiệp sẽ giải quyết như thế nào đây?</p>', 'Hoàn Tất (70/70)', 70, 'hoathinh', 'completed', 7, 2020, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324336);
