INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyet-thuong-trong-hoa', 'Nguyệt Thượng Trọng Hỏa', 'And The Winner Is Love', 'https://phimimg.com/upload/vod/20240302-1/4317b335a8ce0585f312548dd7ca9162.jpg', 'https://phimimg.com/upload/vod/20240302-1/58324d69a1de127df41c4a025d581ca8.jpg', '<p>Nguyệt Thượng Trọng Hỏa kể về con gái của cung chủ đời trước Trọng Diệp - thiếu cung chủ Trọng Tuyết Chi (Trần Ngọc Kỳ đóng) vừa bước chân vào giang hồ, ở đại hội anh hùng Phụng Thiên kết bạn với cốc chủ Nguyệt Thượng Cốc là Thượng Quan Thấu (La Vân Hi đóng) Bởi vì Liên thần cửu thức - báu vật trấn cung của Trọng Hoả Cung bị trộm, Trọng Tuyết Chi bị trục xuất khỏi cung, trên đường nhiều lần bị ám sát, may mắn được Thượng Quan Thấu chăm sóc...</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 11, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"La Vân Hi","avatar":""},{"name":"Trần Ngọc Kỳ","avatar":""},{"name":"Trâu Đình Uy","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324336);
