INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiet-huyet-dong-hanh', 'Nhiệt Huyết Đồng Hành', 'Forward Forever', 'https://phimimg.com/upload/vod/20240302-1/c01cd4054408b26910f8ecc1c6defa10.jpg', 'https://phimimg.com/upload/vod/20240302-1/2c0a8320c68c438402df67c364b796fa.jpg', '<p>Nội dung phim xoay quanh hành trình đưa đất nước thoát khỏi thời kỳ loạn lạc của hai thiếu niên tài giỏi, thông minh là Lợi Minh và A Dịch. Dù có xuất thân khác xa nhau, nhưng cả hai đều chung chí hướng, trong khi bối lạc gia Lợi Minh là lãnh đạo xuất sắc của tổ chức bí mật Diễm Thế Phiên thì thường dân A Dịch là chàng trai giữ vị trí quan trọng không thể thay của tổ chức. Cùng nhau hợp tác và hành động, cả hai tạo nên những màn đấu trí căng thẳng và hấp dẫn.</p>', 'Hoàn Tất (58/58)', 58, 'series', 'completed', 8, 2020, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Dịch Dương Thiên Tỉ","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324337);
