INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('date-a-live-ngoai-truyen-hen-thach-dau-tokisaki-kurumi', 'Date A Live, Ngoại Truyện Hẹn Thách Đấu Tokisaki Kurumi', 'Date A Bullet', 'https://phimimg.com/upload/vod/20240302-1/25d0f334cfbad3c51ab6c23876f5d416.jpg', 'https://phimimg.com/upload/vod/20240302-1/28f5f5b95aecf25ee306504b6b81f473.jpg', '<p>Những cô gái tinh linh xuất hiện từ thế giới bên kia và mang theo thảm họa đến thế giới thực. Tinh linh thế hệ thứ 3 mang mật danh Kyozo Tokizaki, sử dụng thiên sứ hùng mạnh Zaphkiel (người thao túng thời gian), những hành động, mục đích của họ đều là điều bí ẩn. Một ngày kia, đột nhiên, những cô gái bay về một góc của thế giới bên kia, những tinh linh đã tiêu tan tại thế giới - nơi trỗi dậy thành chiến trường của bán tinh linh, họ mở rộng chiến trường thi đấu, biến những điều ước của mình thành hiện thực.</p>', 'Hoàn Tất (2/2)', 2, 'hoathinh', 'completed', 16, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324337);
