INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chico-bon-bon-chu-khi-va-that-lung-do-nghe-phan-4', 'Chico Bon Bon: Chú Khỉ Và Thắt Lưng Đồ Nghề (Phần 4)', 'Chico Bon Bon: Monkey With A Tool Belt (Season 4)', 'https://phimimg.com/upload/vod/20240229-1/5a8acfd70638f57a076bbbe12dd9959e.jpg', 'https://phimimg.com/upload/vod/20240229-1/855a5f81b9e107ddc825f34fc8bd48f9.jpg', '<p>Được trang bị nhiều công cụ và sự thông minh về mặt kỹ thuật, chú khỉ thợ cơ khí Chico Bon Bon và Đội Sửa chữa giúp người dân Blunderburg giải quyết mọi vấn đề.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robbie Daymond","avatar":""},{"name":"Dayci Brookshire","avatar":""},{"name":"Anthony Tedesco","avatar":""},{"name":"Andy Abbott","avatar":""},{"name":"Roberta Lemons","avatar":""},{"name":"Cole Seaver","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
