INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loan-the-dinh-tan-kiem', 'Loạn Thế Định Tần Kiếm', 'The Emperor''s Sword', 'https://phimimg.com/upload/vod/20240228-1/1613cfc848fcce4a0bb2c8165ea59cdf.jpg', 'https://phimimg.com/upload/vod/20240228-1/9664cf79435df03872445c3a26c2caf2.jpg', '<p>Lấy bối cảnh năm 221 trước công nguyên, nội dung phim xoay quanh những sự kiện đáng chú ý thời nhà Tần. Sau khi xưng bá Trung Nguyên, Thủy Hoàng Đế bắt đầu xây dựng đế chế vững mạnh, duy trì vương triều thiên thu ngàn đời. Sau đó, ông cho người đúc A Phòng Định Tần kiếm và Quan Đài Định Tần kiếm, và đem mỗi thứ đi một nơi. Nhưng để từ khi Tần Thủy Hoàng băng hà, loạn thần Triệu Cao ấp ủ kế hoạch lật ngôi, điều khiển triều chính.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Mu Fengbin","avatar":""},{"name":"Yang Qiyu","avatar":""},{"name":"Qin Chuming","avatar":""},{"name":"Xu Zhangchao","avatar":""},{"name":"Shi Xiaofei","avatar":""},{"name":"Ruoyao Pan","avatar":""},{"name":"Qihang Zhao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324337);
