INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-cung-an-toi-nhe', 'Chúng Ta Cùng Ăn Tối Nhé?', 'Dinner Mate', 'https://phimimg.com/upload/vod/20240229-1/60f4a550f8cbececcc29143a96ddecdb.jpg', 'https://phimimg.com/upload/vod/20240229-1/1286f69524e7643ee2281f1e51313986.jpg', '<p>Chuyển thể từ bộ truyện tranh nổi tiếng! Đã đến lúc tạm biệt đời FA rồi~ Nam thần không già Song Seunghun mời bạn cùng ăn tối đấy! Hoàn toàn không có lý do từ chối! Seo Jihye của \Hạ Cánh Nơi Anh\ ký tên góp mặt đầu tiên, Son Naeun của Apink, diễn viên nổi tiếng Lee Jihoon bất ngờ tham gia biểu diễn~ Cùng bạn ăn uống, yêu đương, đi đến đỉnh cao của cuộc sống~</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Seung Heon","avatar":""},{"name":"Ji-hye Seo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324337);
