INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-toi-cua-midas', 'Bầy Tôi Của Midas', 'The Minions Of Midas', 'https://phimimg.com/upload/vod/20240229-1/825705b4ffd7de1c8d295481fe1e33a4.jpg', 'https://phimimg.com/upload/vod/20240229-1/8307755b9226437ebf95bfdc1de77085.jpg', '<p>Một nhà xuất bản triệu phú nhận được thư tống tiền – quyết định của anh có thể định đoạt sống chết. Dựa trên truyện của Jack London nhưng lấy bối cảnh ở Madrid hiện đại.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2020, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Luis Tosar","avatar":""},{"name":"Marta Belmonte","avatar":""},{"name":"Guillermo Toledo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324337);
