INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-bao-chung', 'Thiếu Niên Bao Chửng', 'Legend Of Young Justice Bao', 'https://phimimg.com/upload/vod/20240228-1/92e9ac33c773185d816a8fbc0858b6d9.jpg', 'https://phimimg.com/upload/vod/20240228-1/07bad77d2f2d39ab5c3465bac22a1dd3.jpg', '<p>Bao Đại Nương bị vu oan vào một vụ án. Bao Chửng cố gắng giải oan cho mẹ mình nhưng nó đưa ra ánh sáng một vụ thảm sát liên quan đến cô dâu ma. Trên đường đến thủ đô, Bao Chửng vào nhà trọ Vô Cực , nơi anh ta sử dụng trí thông minh của mình để khám phá những bí ẩn trong khu rừng tinh linh máu. Cuối cùng, Ngôi làng linh hồn dường như được kết nối với một âm mưu lớn trong cung điện.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 19, 2020, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Bành Nghệ Bác","avatar":""},{"name":"Hạ Chí Viễn","avatar":""},{"name":"Lương Gia Nhân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
