INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-chau-thien-khong-thanh-2', 'Cửu Châu Thiên Không Thành 2', 'Novoland: The Castle In The Sky 2', 'https://phimimg.com/upload/vod/20240228-1/4f9daede22027de3ccfc224024cf6d13.jpg', 'https://phimimg.com/upload/vod/20240228-1/c415464bc4e909a3f82a4a9ce05fe537.jpg', '<p>Cửu Châu Thiên Không Thành 2 cũng kể về câu chuyện tình yêu của Phong Như Triệt do Vương Ngọc Văn đảm nhận là con gái duy nhất của Thiên Dật, Phục Linh và Tuyết Cảnh Không do Từ Chính Khê thủ vai là con trai của Lan Châu. Tuyết Cảnh Không là một người đàn ông giỏi tiết chế tình cảm, luôn luôn nhẹ nhàng, lạnh lùng, khó gần. Còn Phong Như Triệt là một cô gái lớn lên ở một nơi hoang vu và có một cuộc sống gai góc, bụi bặm, tinh nghịch nhưng đến khi Như Triệt gặp Cảnh Không, cô đã trở thành một cô gái nhút nhát, nữ tính hơn.Cảnh Không và Như Triệt đã cùng nhau trải qua bao sóng gió, gian nan, liệu cặp đôi này sẽ đi về đâu? Mọi người hãy cùng theo dõi những diễn biến của bộ phim Cửu Châu Thiên Không Thành 2 nhé.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 6, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Đại Văn Văn","avatar":""},{"name":"Lý Mộc Thần","avatar":""},{"name":"Sài Cách","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324337);
