INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-nhu-an-banh-phan-4', 'Dễ Như Ăn Bánh! (Phần 4)', 'Nailed It! (Season 4)', 'https://phimimg.com/upload/vod/20240228-1/7e0310ae8da1d7f1c8467be9b3170558.jpg', 'https://phimimg.com/upload/vod/20240228-1/754a19057264ffb559d62fbf2c90881d.jpg', '<p>Dễ như ăn bánh! mùa mới mang đến những chiếc bánh tệ mới và vài điều chưa từng có tiền lệ, từ các nhóc tì trong bếp đến trò vui với nitơ lỏng. Có vấn đề gì được chứ?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Nicole Byer","avatar":""},{"name":"Jacques Torres","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324337);
