INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chieu-tro-nguyen-thuy', 'Chiêu Trò Nguyên Thủy', 'Leh Bunpakarn', 'https://phimimg.com/upload/vod/20240228-1/0be6026e59c7427ef5e3133d480a11f1.jpg', 'https://phimimg.com/upload/vod/20240228-1/14682fba2e9558716feaba7b532c8d2d.jpg', '<p>Lấy bối cảnh hiện đại đan xen quá khứ, Plerngfah và Tuanai sống ở thời hiện đại nhưng họ luôn nhớ về bản thân 1500 năm trước. Plerngfah - chàng phóng viên và Tuanai - cô giáo xinh đẹp và hai người yêu nhau từ kiếp trước. Mọi chuyện bắt đầu từ cái chết của Khun Utaiyothin - một người lính bị cô gái yêu đơn phương vì hiểu lầm nên hận. Khi Khun chết thì vợ anh – Duangkae - đang mang thai. Với lời ước hẹn của hai vợ chồng rằng Tình yêu là sự gắn kết sẽ đưa linh hồn hai ta gặp lại nhau đã dẫn lối để họ tìm được nhau ở thời hiện đại.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 8, 2020, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"James Jirayu Tangsrisuk","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324337);
