INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-tuong', 'Hồi Tưởng', 'Flashback', 'https://phimimg.com/upload/vod/20240228-1/832434ee098f4b1414b41d3269c6994d.jpg', 'https://phimimg.com/upload/vod/20240228-1/94d120e1523c3a23aba5386d32c75ed1.jpg', '<p>Sau một cuộc gặp gỡ tình cờ với một người đàn ông lạ mặt, Fred (OBrien đóng) bỗng có những hồi tưởng liên tục về quãng thời gian học trung học. Anh dần sáng tỏ về một bí ẩn bấy lâu nay về một cô gái mất tích, một loại thuốc có tên là Mercury, và một sinh vật đáng sợ đã theo anh đến tận khi trưởng thành.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dylan O''Brien","avatar":""},{"name":"Hannah Gross","avatar":""},{"name":"Emory Cohen","avatar":""},{"name":"Keir Gilchrist","avatar":""},{"name":"Maika Monroe","avatar":""},{"name":"Liisa Repo-Martell","avatar":""},{"name":"Amanda Brugel","avatar":""},{"name":"Alan C. Peterson","avatar":""},{"name":"Aaron Poole","avatar":""},{"name":"Maika Harper","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324337);
