INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-vuong-trieu-con-son-tang-kiem', 'Kiếm Vương Triều: Côn Sơn Tàng Kiếm', 'Sword Dynasty: The Treasure Of Sword', 'https://phimimg.com/upload/vod/20240228-1/ebd9e0b56a9b83d462233fa28b868a6a.jpg', 'https://phimimg.com/upload/vod/20240228-1/68b1ed3d64ef7f0b55a45d15405de396.jpg', '<p>Kiếm Vương Triều: Côn Sơn Tàng Kiếm - Sword Dynasty: The Treasure Of Sword xảy ra sau trận Ba Sơn, Dạ Sách Lãnh ở lại bên Hằng Vương luôn nghe ngóng tin tức của đồng môn, chờ thời cơ giết Hằng Vương báo thù. Giang hồ đưa tin Vân Lai Trấn có giấu kiếm quý trên núi, Hằng Vương sai Trần Huyền và Sách Lãnh đến thăm dò. Vân Lai trấn xuất hiện yêu quái, Dạ Sách Lãnh cứu được Quý Thần. Là ông chủ Hà và Vân Sam sư tỷ lừa các nhân sĩ đến tìm kiếm để mượn máu họ luyện công. Để báo thù cho Quý Thần và Vân Sam, Sách Lãnh đã giết ông chủ Hà. Trần Huyền biết mục đích của Sách Lãnh là báo thù, theo cô ấy về bên Hằng Vương</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Yi-Tong","avatar":""},{"name":"Zhao Yuan Yuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
