INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sa-mac-chet', 'Sa Mạc Chết', 'DustWalker', 'https://phimimg.com/upload/vod/20240228-1/fa551cdc6617710f21c1cbe9ac0ef2bb.jpg', 'https://phimimg.com/upload/vod/20240228-1/b76927953f26a07673bba1ccc3576f6d.jpg', '<p>Sau một vụ rơi tàu bay đầy bí ẩn, một loài ký sinh trùng ngoài hành tinh bất ngờ tấn công cư dân của một thị trấn nhỏ nằm cô lập giữa sa mạc. Chúng chiếm lấy não của nạn nhân, biến họ trở thành những sinh vật điên loạn và khát máu. Không còn cách nào khác, những cư dân khỏe mạnh còn lại của thị trấn phải chiến đấu để bảo vệ chính mình. Tuy nhiên, họ dần nhận ra rằng mối nguy hiểm không chỉ đến từ lũ ký sinh trùng, mà còn liên quan đến sự xuất hiện của một loài quái vật to lớn hơn</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324337);
