INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-cua-song-ci', 'Hành Trình Của Song Ci', 'Legal Medical Expert Song Ci', 'https://phimimg.com/upload/vod/20240228-1/1aa0008dda806e9850c0d4195bf33498.jpg', 'https://phimimg.com/upload/vod/20240228-1/801b12c67a6fa750a5c7133475f15824.jpg', '<p>Hành Trình Của Song Ci - Legal Medical Expert Song Ci kể về hành trình đi tìm sự thật về 26 cái chết. Song Ci và nữ trợ lý Yu Mo đã quyết tâm bắt tay vào điều tra sự thật. Song Ci đã tham khảo ý kiến giáo viên của mình Geng Zhinian. Thật bất ngờ, 26 xác chết bốc cháy một cách tự nhiên ngay ngày hôm đó. Song Ci nghĩ rằng đây là một âm mưu khủng bố hóa học có tên gọi là Giáo phái Boxun. Để xâm nhập được giáo phái này và tìm ra sự thật, Song Ci và các đồng đội phải tạo nên một màn kịch để kẻ đứng đầu buộc phải lộ mặt.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yu Zhen","avatar":""},{"name":"Pan Chang Jiang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
