INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kalashnikov', 'Kalashnikov', 'Kalashnikov', 'https://phimimg.com/upload/vod/20240220-1/411faefc93e9148ebb987456338d42e4.jpg', 'https://phimimg.com/upload/vod/20240220-1/c34aa9a79359a11a448104bf1c54e9bb.jpg', '<p>Bị thương như một tài xế xe tăng vào năm 1941 trong WWII, Kalashnikov nhìn thấy súng máy Liên Xô mới nhất thất bại. Vì anh ấy cũng là một nhà phát minh, anh ấy bắt đầu tìm kiếm những cải tiến và năm 1947 kết thúc với súng trường tấn công AK-47.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub', 'HD', 'Nga', 0, '[]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324337);
