INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-giai-tri-2020', 'Vua Giải Trí', 'The Lord Of Amusement', 'https://phimimg.com/upload/vod/20240220-1/b2e0321e3688d1df1b30af2726f3aff2.jpg', 'https://phimimg.com/upload/vod/20240220-1/bf424fa17c11063061cda0061a9247de.jpg', '<p>Dương Thiên Hoa lần đầu tiên đến Hồng Kông, anh đã nhờ vả dựa dẫm người dì làm việc tại hộp đêm và đã trở thành người phục vụ bàn. Trong hộp đêm, giám đốc Xương Thúc và anh Pháo là hai người đứng đầu đầu có tiếng trong thiên hạ .Giang hồ đồn đại về rất nhiều câu chuyện có liên quan đến anh Pháo, Thiên Hoa đã coi anh Pháo như là thần tượng của mình. Anh Pháo vẫn luôn yêu cô vũ nữ Kỳ Kỳ, nhưng Kỳ Kỳ không thể chịu nổi sự nóng nảy thô bạo của anh Pháo và cuối cùng cô đã lựa chọn rời đi. Khi anh Pháo tinh thần bị tổn thương, Xương Thúc đã bày trò để trục xuất anh pháo ra khỏi hộp đêm,toàn bộ hộp rơi vào tay của Xương Thúc. Anh pháo sau khi rời đi, Xương Thúc đã có ý hại Thiên Hoa, Thiên Hoa đã rơi vào bẫy của Xương Thúc, cuối cùng bị lừa nợ Xương Thúc một khoản tiền lớn</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Nick Cheung","avatar":""},{"name":"Francis NG","avatar":""},{"name":"Sherming Yiu","avatar":""},{"name":"Choi","avatar":""},{"name":"Elle","avatar":""},{"name":"Ng Man Tat","avatar":""},{"name":"Uncle Tat","avatar":""},{"name":"Elvina Kong","avatar":""},{"name":"CeliaSie","avatar":""},{"name":"lik-chi lee","avatar":""},{"name":"Bobby Yip","avatar":""},{"name":"Gabriel Harrison","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324337);
