INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quang-thoi-gian-tuoi-dep', 'Quãng Thời Gian Tươi Đẹp', 'Magic Hour', 'https://phimimg.com/upload/vod/20240215-1/3d4c05a98ef92debc730c5fd62031b2b.jpg', 'https://phimimg.com/upload/vod/20240215-1/bc12f7dc8c82e3ab319b59bedfe66ea8.jpg', '<p>Dĩ Đồng vốn tưởng rằng mình rất kiên cường, cô luôn ương bướng cãi lại mẹ nhưng lại cúi đầu trước tình yêu. Không có được tình thương của mẹ, cô trông chờ tất cả vào tình yêu nhưng trớ trêu thay, tình yêu cũng bỏ rơi cô ấy còn mẹ cô vẫn ở nhà nấu cơm chờ cô về. Chính vào lúc cô chạy trốn tất cả trở về lại chỉ gặp được thi thể lãnh lẽo của mẹ. Dĩ Đồng quyết định sẽ đối diện với những tiếc nuối, cô dùng viên thuốc thời gian mà mẹ để lại, thay mẹ mình hoàn thành những điều còn dang dở.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 2020, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Wu Nian Xuan","avatar":""},{"name":"Beatrice Fang","avatar":""},{"name":"Vera Yen","avatar":""},{"name":"Chen Yan Yun","avatar":""},{"name":"Zhang Guangchen","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324337);
