INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-khong-nghien-mua-sam', 'Tôi Không Nghiện Mua Sắm', 'Rebirth Of Shopping Addict', 'https://phimimg.com/upload/vod/20240215-1/c387ab3092943b889125ba9a00e83aab.jpg', 'https://phimimg.com/upload/vod/20240215-1/339d7f83768046cf2b5dcf4710c01808.jpg', '<p>Tôi Không Nghiện Mua Sắm - Rebirth of Shopping Addict kể về một tiểu thư nghiện mua sắm tên là Cao Dương. Nhưng vì phá sản và bố mình biến mất, cô đành phải chuyển vào nhà của Nghiêm Lệ, em trai của người yêu bố cô, Nghiêm Yên Nhiên. Cô bắt đầu làm việc cho cửa hàng Nhật Nguyệt để kiếm thêm thu nhập. Tranh giành cửa hàng đại lý độc quyền của nhãn hiệu nổi tiếng thế giới C.K.K, Nghiêm Lệ và Lí Minh Triệt bắt đầu trận chiến doanh thu trong ba tháng. Cao Dương cũng bị kéo vào cuộc đua giữa hình thức mua bán điện tử và những cửa hàng truyền thống. Cô luôn cổ vũ và khích lệ mọi người với tính cách lạc quan. Điều đó đã khiến Vương Tiểu Tái, người đã từng khinh thường cô, trở thành một người bạn tốt.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 11, 2020, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Mạnh Tử Nghĩa","avatar":""},{"name":"Lộ Thần","avatar":""},{"name":"Lý Sân","avatar":""},{"name":"Vương Dương Minh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324337);
