INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-ket-noi-re-dive', 'Công Chúa Kết Nối! Re: Dive', 'Re: Dive', 'https://phimimg.com/upload/vod/20240215-1/887db61768e727fe43f2b5d887042272.jpg', 'https://phimimg.com/upload/vod/20240215-1/975b9cf5c68edf030c05b293e2a44360.jpg', '<p>Yuki, một cậu bé bị mất trí nhớ ở một góc của lục địa Astria tỉnh dậy. Kokkoro, một hướng dẫn viên nhỏ chăm sóc Yuki. Pecoline, một nữ kiếm sĩ xinh đẹp với 1 chiếc bụng luôn đói khát. Cal của một cô gái ma thuật với chiếc tai mèo cool ngầu. Được số mệnh dẫn lối, họ đặt tên cho tổ chức mà họ thành lập ra với tên gọi Hội sành ăn. Cuộc phiêu lưu của Yuki và những cô gái sắp bắt đầu!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324337);
