INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-day-phan-11', 'Mặt Dày (Phần 11)', 'Shameless (Season 11)', 'https://phimimg.com/upload/vod/20240215-1/f59931238723f5114d8ac529d7a25431.jpg', 'https://phimimg.com/upload/vod/20240215-1/2088c43835197f5d2018adef2b8c45e8.jpg', '<p>Khi Frank đối mặt với cái chết của chính mình và mối quan hệ gia đình trong những năm cuối đời do rượu và ma túy gây ra, Lip phải vật lộn với viễn cảnh trở thành tộc trưởng mới của gia đình. Cặp vợ chồng mới cưới Ian và Mickey đang tìm hiểu các quy tắc và trách nhiệm khi ở trong một mối quan hệ đã cam kết trong khi Deb chấp nhận cá tính riêng và vai trò làm mẹ đơn thân của mình. Carl tìm thấy một nghề nghiệp mới không chắc chắn là thực thi pháp luật. Kevin và V đấu tranh để quyết định xem cuộc sống khó khăn ở South Side có đáng để đấu tranh hay không.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"William H. Macy","avatar":""},{"name":"Jeremy Allen White","avatar":""},{"name":"Cameron Monaghan","avatar":""},{"name":"Noel Fisher","avatar":""},{"name":"Emma Kenney","avatar":""},{"name":"Ethan Cutkosky","avatar":""},{"name":"Christian Isaiah","avatar":""},{"name":"Shanola Hampton","avatar":""},{"name":"Steve Howey","avatar":""},{"name":"Kate Miner","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324337);
