INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-tham-gian-bat-tri', 'Hiệp Thám Giản Bất Tri', 'Ancient Detective', 'https://phimimg.com/upload/vod/20240215-1/d137c2fee786686f462bcb10a5887536.jpg', 'https://phimimg.com/upload/vod/20240215-1/cad7920946da5bc793f3d6fa3cc90cc1.jpg', '<p>Hiệp Thám Giản Bất Tri - Ancient Detective kể về thám tử trẻ thông minh, tài giỏi nhưng bị mất trí nhớ Giản Bất Tri - người bắt đầu nhiệm vụ tìm kiếm sự thật và vạch mặt kẻ giết cha mình. Trên hành trình không ngừng cố gắng thu thập manh mối từ khắp nơi, Giản Bất Tri tìm thấy cho mình tình yêu và tình bạn - những người cùng chí hướng, cùng làm việc với anh để giải quyết các vụ án bí ẩn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vu Tế Vĩ","avatar":""},{"name":"Vương Nhược San","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324337);
