INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phai-cuoi-roi-moi-yeu', 'Phải Cưới Rồi Mới Yêu', 'Begin Again', 'https://phimimg.com/upload/vod/20240215-1/6979c47d8334b9211dac9de2873def2e.jpg', 'https://phimimg.com/upload/vod/20240215-1/4fbbc3c53e9ed562d2bba990f0300c9e.jpg', '<p>Là dự án truyền hình lên sóng đài Hồ Nam trong thời gian sắp tới. Bộ phim mang một motif quen thuộc: cưới trước yêu sau. Bộ phim có sự tham gia của những gương mặt trẻ nhưng tài năng của làng diễn viên Hoa ngữ như Châu Vũ Đồng, Cung Tuấn, Kim Trạch, Ngô Mạn Tư,…</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Châu Vũ Đồng","avatar":""},{"name":"Cung Tuấn","avatar":""},{"name":"Kim Trạch","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324337);
