INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-hon-hikaru-no-go', 'Kỳ Hồn (Hikaru No Go)', 'Hikaru No Go', 'https://phimimg.com/upload/vod/20240209-1/e3f04b4b62f048f1da0e1053580684b4.jpg', 'https://phimimg.com/upload/vod/20240209-1/241e7362e1aaee4a027907f20e87bbec.jpg', '<p>Thời Quang một cậu bé học sinh lớp sáu vì muốn kiếm tiền tiêu vặt nên tới nhà ông nội tìm báu vật, tình cờ cậu phát hiện ra một bàn cờ cổ. Trong khoảnh khắc chạm vào bàn cờ, linh hồn của Chử Doanh, một kỳ thủ giỏi nhất Nam Lương, ở trong bàn cờ nhập vào cơ thể Thời Quang. Chử Doanh xem cờ vây như sinh mạng của mình. Dưới sự ảnh hưởng của Chử Doanh, Thời Quang cũng dần thấy hứng thú đối với cờ vây.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 17, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hồ Tiên Hú","avatar":""},{"name":"Trương Siêu","avatar":""},{"name":"Hách Phú Thân","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '[]', 1784690324337);
