INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-di-biet-tai-truong-hoc-phep-thuat-phan-khach-vieng-tham', 'Kẻ Dị Biệt Tại Trường Học Phép Thuật:  Phần Khách Viếng Thăm', 'Mahouka Koukou No Rettousei: Raihousha-hen', 'https://phimimg.com/upload/vod/20240209-1/c579d9c0d3f1388c372bb5face033451.jpg', 'https://phimimg.com/upload/vod/20240209-1/ea1171a79d9ad7d2a679e4d45c85e533.jpg', '<p>Sau sự kiện Halloween Rực lửa, cả thế giới rúng động trước sự xuất hiện của một pháp sư cấp chiến lược mới. Để tìm ra danh tính của người này, quân đội Hoa Kỳ (USNA) đã gửi pháp sư mạnh mẽ nhất của họ, đội trưởng đội Stars - Angie Sirius tới Nhật Bản dưới thân phận du học sinh Angelina Kudou Shields. Cùng lúc đó, nhiều thi thể được tìm thấy rải rác khắp Tokyo trong tình trạng bị rút sạch máu, khiến chúng được cho là tác phẩm của ma cà rồng. Tatsuya sẽ làm thế nào để tìm ra thủ phạm thực sự của vụ án Ma cà rồng cũng như đối phó với cô bạn mới quen Angelina - Angie Sirius kia?</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 17, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324337);
