INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-thoi-den-bi-mat-mo-chi-long-linh', 'Ma Thổi Đèn: Bí Mật Mộ Chi Long Lĩnh', 'Dragon Labyrinth', 'https://phimimg.com/upload/vod/20240220-1/a18c415a66f1e2e902a2e10fe7e4af44.jpg', 'https://phimimg.com/upload/vod/20240220-1/4dd0a468d972613bcdbd1fd5de292adf.jpg', '<p>Ma Thổi Đèn: Bí Mật Mộ Chi Long Lĩnh - Dragon Labyrinth dựa theo loạt tiểu thuyết Ma Thổi Đèn. Tương truyền một căn hầm bí mật ở Long Lĩnh, Thiểm Tây khai quật phát hiện một lọai văn tự Long Cốt lạ. Tuyết Lị Dương đến điều tra thì gặp bọn người của Hồ Bát Nhất, bốn người họ vào khu mộ âm hồn để tìm hiểu ngọn ngành. Hồ Bát Nhất tìm hỏi về việc cái bớt đỏ, Tuyết Lị Dương nói ra câu chuyện về tiếng kêu chim chá hộc năm đó.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kang Ning","avatar":""},{"name":"Lin Yu Shen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324337);
