INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-mai-em-co-con-yeu-anh', 'Ngày Mai Em Có Còn Yêu Anh', 'I Remember', 'https://phimimg.com/upload/vod/20240220-1/a6a01b43907d7508a04ab8d2a215a859.jpg', 'https://phimimg.com/upload/vod/20240220-1/be101c869f4af7b795ec2a02d7e27fda.jpg', '<p>Phải chăng trong cuộc đời, ai cũng có một người không thể yêu được? Khi chàng nhân viên IT mờ nhạt Phí Lực (Lý Hồng Kỳ thủ vai) gặp được cô gái Triệu Hi Mạn tỏa sáng lấp lánh (Dương Dĩnh thủ vai), anh đã tìm được lý do buộc mình phải mạo hiểm. Mỗi một loại lãng mạn hữu hạn trên thế gian, đều được tạo nên từ nỗi khổ tâm của người yêu thầm. Khi ngày mai đến, liệu em có còn nhớ sự rung động và tình yêu thuần khiết đó? Nếu anh may mắn đợi được em, mình hãy cùng nhau đi ngắm cực quang nhé...</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Angelababy","avatar":""},{"name":"Hong-Chi Lee","avatar":""},{"name":"Esther","avatar":""},{"name":"Denny Huang","avatar":""},{"name":"刘蔚森","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324337);
