INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-lego-star-wars-holiday-special', 'The Lego Star Wars Holiday Special', 'The Lego Star Wars Holiday Special', 'https://phimimg.com/upload/vod/20240220-1/7f804dbc41022bff1c759233c31ea2a8.jpg', 'https://phimimg.com/upload/vod/20240220-1/42ec9292dc93a6c0ba58bbf911cc3697.jpg', '<p>Rey rời khỏi những người bạn của mình để chuẩn bị cho cuộc sống trong ngày khi cô đặt ra một cuộc phiêu lưu để đạt được một kiến thức sâu sắc hơn về lực lượng. Tại một ngôi đền bí ẩn, cô ấy đang lao vào một cuộc phiêu lưu dòng thời gian chéo. Cô ấy sẽ làm cho nó trở lại trong thời gian cuộc sống?</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324337);
