INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-ly-cua-spenser', 'Công Lý Của Spenser', 'Spenser Confidential', 'https://phimimg.com/upload/vod/20240220-1/a91e9038f58ca1328397ec5f8d6c8841.jpg', 'https://phimimg.com/upload/vod/20240220-1/35db46bc3b79514a262d11325d7a4278.jpg', '<p>Cựu cảnh sát vừa ra tù Spenser bắt tay cùng Hawk – một võ sĩ ôm mộng lớn – nhằm lật tẩy âm mưu hiểm độc liên quan đến cái chết của hai sĩ quan cảnh sát ở Boston.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Winston Duke","avatar":""},{"name":"Alan Arkin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324337);
