INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-ly-dam-but', 'Hồ Ly Dâm Bụt', 'Fox In Fuso', 'https://phimimg.com/upload/vod/20240219-1/2a6900a315f1b357b03cdb4cfc2c009c.jpg', 'https://phimimg.com/upload/vod/20240219-1/31ec02f9bbb26b07c7c8497ac1165b04.jpg', '<p>Hồ Ly Dâm Bụt - Fox In Fuso kể về bông Bảo Liên Đăng - một báu vật quý giá, nhưng vô tình bị thất lạc trong nhân gian. Sau đó, 3 chị em hồ ly được phái xuống trần gian để tìm kiếm bông sen vàng này. Cả ba đều bị thương, rơi xuống trần và đầu thai kiếp khác, được một người phụ nữ quyền lực nuôi dưỡng và chỉ dạy. Khi trưởng thành, cả 3 đều bị quên hết đi ký ức của mình, đồng thời chỉ là công cụ lợi dụng để tìm kiếm bông sen. Khi 3 chị em lấy được Bảo Liên cho chủ nhân của mình thì họ chợt nhận ra bà ta đang muốn dùng nó để thống trị tất cả. Liệu 3 chị em phải làm gì để ngăn chặn điều này?</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ma Si Chao","avatar":""},{"name":"Sun Ya Li","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
