INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ho-ly-dam-but', 'Hồ Ly Dâm Bụt', 'Fox In Fuso', 'hồ ly dâm bụt fox in fuso ma si chao sun ya li ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oi-troi-oi-chuyen-phieu-luu-day-thu-vi', 'Ối Trời Ơi! Chuyến Phiêu Lưu Đầy ''Thú'' Vị', 'Ooops! The Adventure Continues', 'https://phimimg.com/upload/vod/20240219-1/15e9d47577d036130033e997f60e4e13.jpg', 'https://phimimg.com/upload/vod/20240219-1/29b37098c442e8d83326a5f1f22f3570.jpg', '<p>Bộ phim hoạt hình siêu thú vị về cuộc phiêu lưu của các bạn trẻ: Noah, Finny, Leah và đồng bọn. Chuyến tàu của Noah, cùng hai người bạn thân là Finny và Leah bị trôi dạt trên biển khơi, lượng thức ăn dần cạn kiệt, hoà bình giữa động vật ăn cỏ và động vật ăn thịt dần trở nên mong manh và dễ dàng tan vỡ hơn bất cứ lúc nào hết. Sau hàng loạt những sự kiện không may xảy ra, Leah cùng đồng bọn, và cả người bạn mới của mình là Jelly vô tình bị cuốn đến một hòn đảo xa xôi. Trong khi đó, Finny tỉnh dậy và thấy mình đã bị lạc trong một thuộc địa kì lạ. Trước những bất ngờ kỳ thú cùng hàng loạt những thử thách ập đến: thuỷ triều, núi lửa và những chấn động kinh hoàng, liệu Finny có thể hoàn thành chuyến phiêu lưu đầy ‘thú’ vị của mình, cứu bạn và trở về đoạn tụ với gia đình không? Bộ phim hứa hẹn sẽ mang đến một chuyến phiêu lưu đầy ‘thú’ vị, tiếng cười sảng khoái và hàng loạt điều kỳ thú cho các bé cùng gia đình vào dịp đầu năm mới này.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Ireland', 0, '[{"name":"Max Carolan","avatar":""},{"name":"Dermot Magennis","avatar":""},{"name":"Ava Connolly","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324337);
INSERT OR IGNORE INTO movie_categories (movie_slug, category_slug) VALUES ('oi-troi-oi-chuyen-phieu-luu-day-thu-vi', 'gia-dinh');
