INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('oi-troi-oi-chuyen-phieu-luu-day-thu-vi', 'Ối Trời Ơi! Chuyến Phiêu Lưu Đầy ''Thú'' Vị', 'Ooops! The Adventure Continues', 'ối trời ơi! chuyến phiêu lưu đầy ''thú'' vị ooops! the adventure continues max carolan dermot magennis ava connolly ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shadow-in-the-cloud', 'Shadow In The Cloud', 'Shadow In The Cloud', 'https://phimimg.com/upload/vod/20240219-1/47025b8daf2a89e3d24beb40380ae5a4.jpg', 'https://phimimg.com/upload/vod/20240219-1/e8b0416a50e11343a873ad9c12a84dab.jpg', '<p>Một phi công WWII nữ đi du lịch với các tài liệu bí mật hàng đầu trên một pháo đài bay B-17 gặp phải một sự hiện diện xấu xa trên tàu.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324337);
