INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tren-bau-troi', 'Trên Bầu Trời', 'Over The Sky', 'https://phimimg.com/upload/vod/20240219-1/f357d88d78dfeb2b367c93aeff59f021.jpg', 'https://phimimg.com/upload/vod/20240219-1/df5228141a06b319eef968a8fd3eae2c.jpg', '<p>Mio là một nữ sinh trung học lẳng lơ. Cô cùng người bạn thời thơ ấu Arata và người bạn thân nhất Madoka dành những ngày sau giờ học ở Ikebukuro để đi chơi. Một ngày nọ, Madoka nói với Mio rằng cô ấy yêu Arata, và Mio nhận ra rằng cô ấy cũng yêu Arata. Nhưng cô ấy sợ mối quan hệ của họ tan vỡ và dối trá, nói rằng cô ấy sẽ giúp họ. Mio cố tình tỏ ra lạnh lùng với Arata, và họ đánh nhau. Cô quyết định giải quyết mọi việc với Arata, nhưng lại gặp tai nạn xe hơi trên đường đến gặp anh. Cô thức dậy trong một thế giới bí ẩn. Đó là Ikebukuro mà cô ấy biết, nhưng có gì đó khác ...</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Honoka Matsumoto","avatar":""},{"name":"Toshiki Seto","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Yui Ogura","avatar":""},{"name":"Koichi Yamadera","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324337);
