INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mang-hoang-ky-than-hon-kiem', 'Mãng Hoang Kỷ: Thần Hồn Kiếm', 'The Legend Of Jade Sword', 'https://phimimg.com/upload/vod/20240219-1/0282ee404f5486c112aaa125a97d27ed.jpg', 'https://phimimg.com/upload/vod/20240219-1/2f9037ce2a30aa072eaba83dfaed72cc.jpg', '<p>Vô Gian thần vương tàn sát chúng sinh bị Nữ Oa phong ấn, Kỷ Thị phụng mệnh bảo vệ phong ấn, hậu duệ thần vương luôn tìm cách giải trừ phong ấn cho thần vương. Kỷ Nhất Xuyên làm quen được kiếm sĩ thần hồn Lan Chính Đạo, đồng thời được truyền lại tu vi cả đời, còn biết được âm mưu của hậu duệ thần vương. Kỷ Nhất Xuyên hiểu được vì bình yên của thiên hạ, đã cùng đồng bạn trở về thế giới Nữ Oa, đánh một trận chiến kinh hồn động phách với thế lực tà ác.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jiang Qi Lin","avatar":""},{"name":"Tang Jing Mei","avatar":""},{"name":"Owodog","avatar":""},{"name":"Hao-Chuan Chuang","avatar":""},{"name":"Chen Meng Yao","avatar":""},{"name":"Zhou Yi Xuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324337);
