INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-xom-2020', 'Hàng Xóm', 'Best Friend', 'https://phimimg.com/upload/vod/20240219-1/4121d190a686d2dddad4b2545d16105b.jpg', 'https://phimimg.com/upload/vod/20240219-1/4108b835c11d8a44f6905e2b63d60c4e.jpg', '<p>Một đội nghe trộm do Yoo Dae Kwon (Jung Woo) đứng đầu nhận chỉ thị của chính phủ theo dõi ứng cử viên tổng thống Lee Ui Sik (Oh Dal Soo) và các thành viên gia đình của ông đang bị quản thúc sau khi hồi hương từ nước ngoài. Các thành viên của đội nghe trộm cải trang thành một gia đình, chuyển đến nhà bên cạnh Lee Ui Sik, giả làm hàng xóm và bắt đầu hoạt động giám sát. Sau đó, trong vô số nội dung nghe lén có vẻ bình thường, bí mật từ từ lộ ra. Yoo Dae Kwon dần bị tính cách của Lee Ui Sik chinh phục và quay sang ủng hộ ông, giúp Lee Ui Sik lật ngược tình thế bất lợi trong cuộc tổng tuyển cử.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Zheng Yu","avatar":""},{"name":"吳達洙","avatar":""},{"name":"Jin Xi Yuan","avatar":""},{"name":"Zheng Xi Tai","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324337);
