INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-huyen-vu', 'Chiến Huyền Vũ', 'Chivalrous', 'https://phimimg.com/upload/vod/20230928-1/91fc9926c8958eed166774bc858007e7.jpg', 'https://phimimg.com/upload/vod/20230928-1/b42513423f40b4f7feffb0aee4e21b6b.jpg', '<p>Huyền Vũ Lệnh vô cùng quý giá lưu lạc chốn giang hồ, bốn gia tộc 
lớn trong giới võ lâm đấu đá nhau như nước với lửa. Truyền nhân của 
chiến thần Mộ Tiểu Hào vì quen biết với Bạch Ngọc Kiều mà bị cuốn vào 
vòng xoáy của trận chiến, giải quyết ân oán của bốn gia tộc. Sau cùng 
quy ẩn giang hồ cùng Bạch Ngọc Kiều.
Yêu hận tình thù của truyền nhân chiến thần</p><p><br/></p><p><br/></p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yan Xi","avatar":""},{"name":"Derek Kwok","avatar":""},{"name":"Zima Yunyi","avatar":""},{"name":"Lo Meng","avatar":""},{"name":"Chen Zhihui","avatar":""},{"name":"Xue Zhao","avatar":""},{"name":"Liu Yan Kai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324337);
