INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meow-chang-trai-bi-an', 'Meow, Chàng Trai Bí Ẩn', 'Meow The Secret Boy (Phát Song Song HQ)', 'https://phimimg.com/upload/vod/20240126-1/b1eb0688d7b8b0236e3ea9ac4106fdda.jpg', 'https://phimimg.com/upload/vod/20240126-1/3aac1c31393c19e72696e4d825a32f79.jpg', '<p>Meow, Chàng Trai Bí Ẩn - Bom tấn truyền hình Hàn Quốc hài hước, đầy bất ngờ khi mèo cưng hóa bạn trai, được Viettel Media phát hành và phân phối độc quyền tại Việt Nam. Phát song song lúc 21h45 thứ 4,5 hàng tuần. Bộ phim là câu chuyện xoay quanh nhân vật chính Sol-A (Shin Ye-Eun) - một phụ nữ ở tuổi 20 - làm việc cho một công ty thiết kế đồ họa, là người rất hòa đồng và cô mơ ước trở thành một nghệ sĩ webcomic. Ngày nọ, Sol-A tình cờ mang về nhà một chú mèo và đặt tên là Hong-Zo (Kim Myung-Soo). Sol-A không biết rằng Hong-Zo không phải là một con mèo bình thường. Anh có khả năng biến thành người. Sống với chú mèo Hong-Zo, Sol-A dính vào những vụ án bất ngờ và hai người dần nảy sinh tình cảm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2020, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Shin Ye Eun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324337);
