INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ban-ky-quai-cua-toi', 'Người Bạn Kỳ Quái Của Tôi', 'My Strange Friend', 'https://phimimg.com/upload/vod/20240118-1/70ecdfbb81153fb8d60c45f9f89f867d.jpg', 'https://phimimg.com/upload/vod/20240118-1/1d1aac7e26e5b144418489567d1fdce7.jpg', '<p>Uất Dật Thần chỉ còn lại khả năng đọc thấu nội tâm, nên để tìm lại những khả năng bị đánh mất thì đã thâm nhập vào trong trường đại học Lâm Châu, không ngừng chiến đấu với những người có được siêu năng lực của mình. Trong quá trình cậu ấy tìm lại năng lực, Uất Dật Thần dần kết thân với mọi người trong trường Lâm Châu. Trong lúc điều tra thì phát hiện ra Tưởng Đẩu Đẩu ẩn giấu sức mạnh bí mật ở phía sau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Nhất Bác","avatar":""},{"name":"Zhang Yi Jie","avatar":""},{"name":"Lillian","avatar":""},{"name":"Molly","avatar":""},{"name":"Nan Zhang","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324337);
