INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-thu-thoat-e', 'Sở Thú Thoát Ế', 'Secret Zoo', 'https://phimimg.com/upload/vod/20240207-1/cddc4156aa420688b11a583705b52a91.jpg', 'https://phimimg.com/upload/vod/20240207-1/72e824d41e6facf7a2cb121181bb67b8.jpg', '<p>Để lập luật sư tại công ty luật, nơi anh ta là trợ lý thấp, Tae-soo (Ahn Jae-hong) được giao nhiệm vụ nản chí để giữ một sở thú thất bại trong ba tháng trong khi công ty vốn đã thực hiện một người mua. Điều đó không có nghĩa là kỳ công khi hóa ra cơ sở Công viên Dongsan đã bán được phần lớn các điểm tham quan chính của nó. Nhận thức được cuộc khủng hoảng thời gian tham gia vào việc cố gắng nhập thêm các sinh vật, Tae-soo cố gắng thực hiện nó bằng cách tuyển dụng nhân viên bộ xương còn lại để tạo dáng trong bộ đồ lông thú có thể dễ dàng thuyết phục nếu được xem từ khoảng cách xa nhất có thể.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324337);
