INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-than-luc', 'Phá Thần Lục', 'As God', 'https://phimimg.com/upload/vod/20240207-1/8b4efff2f9e86b315dd70f21e93fbc54.jpg', 'https://phimimg.com/upload/vod/20240207-1/e9f45ea354d034d3b6c1c2f8af40df63.jpg', '<p>Phá Thần Lục - As God kể về kỳ tài võ học Dương Liệt Quân, vị hôn thê Tôn Cẩn, và sư đệ Lê Thúc Văn đoàn tụ với nhau. Ba người thề sẽ phá tan mê trận Tiên hiệp, thế nhưng sau trận đại phá trận hình nhân lục giáp cung, một bí mật động trời dần dần được hé lộ, song hùng trong giới võ thuật nhất niệm thành Phật, nhất niệm thành ma, đại chiến cuối cùng sắp xảy ra!</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nan Sheng","avatar":""},{"name":"Wang Wen Jie","avatar":""},{"name":"Xie Miao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
