INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-chet-troi-day', 'Xác Chết Trỗi Dậy', 'Block Z', 'https://phimimg.com/upload/vod/20240207-1/09d808332f693736cb5e2134427afdb2.jpg', 'https://phimimg.com/upload/vod/20240207-1/356fa5cea77bb1d0b93bd73359501851.jpg', '<p>Một sinh viên dự bị đại học và những người bạn của cô chứng kiến một người có những triệu chứng của bệnh dại qua đời. Vấn đề nghiêm trọng hơn xảy ra khi tử thi kia đột ngột sống dậy và lây nhiễm cho những người xung quanh. Khuôn viên trường học giờ trở nên hỗn loạn vô cùng.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Julia Barretto","avatar":""},{"name":"Joshua Garcia","avatar":""},{"name":"Maris Racal","avatar":""},{"name":"Dimples Romana","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324337);
