INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soai-ca-khong-chiu-chet', 'Soái Ca Không Chịu Chết', 'Night Of The Undead', 'https://phimimg.com/upload/vod/20240207-1/d1be07f7b62dec7d6f9b82fcfac9b810.jpg', 'https://phimimg.com/upload/vod/20240207-1/74f71a27d43d8723c4dbb0d0f6ecc122.jpg', '<p>So-hee thích cuộc sống dường như hoàn hảo của cô như một người chồng mới cưới với người chồng dường như hoàn hảo. Vì quá hoàn hảo, cô ấy bắt đầu nghi ngờ rằng chồng cô ấy dường như. Muốn một số câu trả lời, cô thuê một cơ quan thám tử tư để theo dõi anh ta xung quanh. PI trở lại với một báo cáo rằng chồng Man-gil là tất cả trên thị trấn, được tình cảm với mọi cô gái mà anh ta đi qua. Anh ấy đã kết hôn nhiều lần, và tất cả những người phụ nữ mà anh ấy đã kết hôn trước đây đều bị mất tích hoặc được tìm thấy đã chết. Man-Gil nhận ra rằng danh tính thực sự của ông đã được phát hiện và cố gắng gây hại cho SO-hee. Với sự giúp đỡ của bạn bè ở trường, Yang-Sun và Pi Jang, So-Hee quyết định giết chồng trước, nhưng anh ta sẽ không rơi vào bất kỳ bẫy nào của cô ấy rất dễ dàng - tối nay, cuộc đấu tay đôi với người đàn ông không thể phá vỡ bắt đầu .</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324337);
