INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-mon-don-giap-2020', 'Kỳ Môn Độn Giáp', 'Fantasy Magician', 'https://phimimg.com/upload/vod/20240205-1/e87fe7ec78e749004f959f045d8a1d12.jpg', 'https://phimimg.com/upload/vod/20240205-1/6ffbbe480f947d621f0afb58a8f998e0.jpg', '<p>Kỳ Môn Độn Giáp - Fantasy Magician kể về Chu Đồng, đầu mục sai dịch của thị trấn La Sát, mê mẩn nghiên cứu Vụ Ẩn Môn từ nhỏ, yên bình sống với ông Chu Nghĩa huyện lệnh của thị trấn La Sát. Không ngờ Gia Minh và Gia Hữu Vi hãm hại bố của Chu Đồng bị bắt giam. Chu Đồng tình cờ gặp thiên lão của Vụ Ẩn Môn bị thương nặng trong đường chạy trốn. May mắn, thiên lão giao “Giáp ”cho Chu Đồng khi hấp hối, Chu Đồng muốn cứu bố bằng lực lượng của “Giáp“, nhưng bố đã bị yêu nhân Tất Phương sát hại.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Peng","avatar":""},{"name":"Lin Yan Rou","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
