INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-bong-chuyen-phan-4-part-1', 'Thiếu Niên Bóng Chuyền !! Phần 4 Part 1', 'Haikyuu!! Fourth Season, Haikyuu!! S4 Part1, Haikyuu!! 4th Season', 'https://phimimg.com/upload/vod/20240118-1/7461aa3ff84b98c5a68b9c50514b037f.jpg', 'https://phimimg.com/upload/vod/20240118-1/6039a5b018b58aa1e10936fc2aec48bd.jpg', '<p>Thông báo về việc triệu tập trại huấn luyện thanh niên toàn Nhật Bản của Kageyama đến với câu lạc bộ bóng chuyền trường trung học Karasuno trước giải đấu quốc gia bất ngờ ập tới. Tsukishima cũng được triệu tập tới trại huấn luyện dành cho sinh viên năm nhất ở tỉnh Miyagi. Hinata, người nôn nóng với sự khác biệt khoảng cách với những người cũng là học sinh lớp một, cũng xông tới trại huấn luyện tuyển chọn học sinh lớp một của tỉnh Miyagi ...!? Trận đấu hướng tới giải đấu quốc gia của câu lạc bộ bóng chuyền trường trung học Hinata, Kageyama và Karasuno bắt đầu !!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 7, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324337);
