INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-danh-thue-2020', 'Lính Đánh Thuê', 'The Mercenary', 'https://phimimg.com/upload/vod/20240205-1/64d1b5147cfdec2b4a693a28c2394b65.jpg', 'https://phimimg.com/upload/vod/20240205-1/1554864bd53531417e04c7d4a7c005a8.jpg', '<p>Mercenary là chuỗi các phân cảnh hành động liên tiếp cho thấy những hoạt động của biệt đội lính đánh thuê của tư nhân ở Trung Phi và Iraq. Những người lính đánh thuê chiến đấu với du kích Châu Phi và những kẻ khủng bố có vũ trang. Lãnh đạo của biệt đội là Leclerc (Louis Mandylor) và chỉ huy phó là Maxx (Dominique Vandenberg), một cựu lính nước ngoài của Pháp.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dominiquie Vandenberg","avatar":""},{"name":"Louis Mandylor","avatar":""},{"name":"Carmen Argenziano","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
