INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-ho-son-truong-thien-su-ky-lan', 'Long Hổ Sơn Trương Thiên Sư: Kỳ Lân', 'Taoist Master: Kylin', 'https://phimimg.com/upload/vod/20240205-1/efb4997eb69276bb8eac7700cc048e0f.jpg', 'https://phimimg.com/upload/vod/20240205-1/ff1c148f25d32b111120d242c3774f77.jpg', '<p>Bộ phim Long Hổ Sơn Trương Thiên Sư: Kỳ Lân - Taoist Master: Kylin nói về một con quái vật bí ẩn đang giết chết dân làng bên dưới núi Yun Jing. Zhang Dao Ling đi ngang với học trò của mình và bắt gặp cái chết của một người dân trong làng. Anh cảm nhận được điều gì đó kỳ lạ trong làng và quyết định điều tra sự thật. Anh phát hiện ra rằng Thần Núi, Hỏa Kylin, có liên quan đến Ma Dược Sư. Bí mật mà họ đang che giấu với người khác là gì?</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Phàn Thiếu Hoàng","avatar":""},{"name":"Zhang Dong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
