INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyet-khong-khuat-phuc', 'Quyết Không Khuất Phục', 'Knockout', 'https://phimimg.com/upload/vod/20240228-1/2f3a53ae468d526909d0791116e6bda1.jpg', 'https://phimimg.com/upload/vod/20240228-1/54cf4f11191400d3588c53b331332279.jpg', '<p>Quyết Không Khuất Phục - Knockout là bộ phim xoay quanh vua quyền anh với danh hiệu Tử Thần bất bại Chu Thủy. Từng có sự nghiệp khiến nhiều người phải ngước nhìn, từng có một gia đình nhỏ hạnh phúc biết bao. Nhưng Chu Thủy kết thúc tất cả bằng chính sự vô tình của bản thân và cái kết cho anh ta là 5 năm tù giam... Tưởng chừng sau khi ra tù anh có thể bắt đầu lại từ đầu nhưng không, vợ anh đã không may qua đời, chỉ còn lại mỗi cô con gái đợi mình sau những năm tháng ăn năn. Bất hạnh lại ập đến khi con gái anh lại không may mắc phải bệnh bạch cầu cấp tính và thời gian bên con gái của anh cũng chẳng còn là bao. Để đem lại hy vọng và ý chí chiến thắng bệnh tật cho con gái, Chu Thủy đã quyết định trở lại với lôi đài quyền anh quen thuộc để cô bé thấy cha mình được làm vua quyền anh lần 2...</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Hàn Canh","avatar":""},{"name":"Trương Quân Ninh","avatar":""},{"name":"Quân Mai","avatar":""},{"name":"Thái Thư Linh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
