INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-canh-su-menh', 'Đặc Cảnh Sứ Mệnh', 'Swat Duty: City Crisis', 'https://phimimg.com/upload/vod/20240207-1/d74238f2cd79718cbeed68524a126ba8.jpg', 'https://phimimg.com/upload/vod/20240207-1/10bb692ee8eb0d5fa9e7ffdc6e54bb8e.jpg', '<p>Bộ phim Đặc Cảnh Sứ Mệnh - Swat Duty: City Crisis xoay quanh vụ khủng bố xảy ra tại trung tâm thành phó. Sau khi nhận được thông tin, cảnh sát ngay lập tức hành động và theo dõi sát theo hành tung của nhóm khủng bố và phát hiện ra rằng có nhiề vấn đề đằng sau đó. Trong lúc gỡ bom, cảnh sát Lương Thành nhận ra sự tương đồng giữa vụ án này và vụ cướp cách đây vài năm. Tuy nhiên, lần này chúng quay lại không chỉ là để cướp mà còn là màn trả thù có kế hoạch kỹ lưỡng từ trước. Liệu Lương Thành và đồng đội sẽ phải làm gì để tất cả được an toàn.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Xiao Jun","avatar":""},{"name":"Zhang Yong Da","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
