INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-muon-tiep-tuc-song', 'Tôi Muốn Tiếp Tục Sống', 'I Want To Go On Living', 'https://phimimg.com/upload/vod/20240205-1/7b4a0ecbd7e46d9b21d267ead6579d93.jpg', 'https://phimimg.com/upload/vod/20240205-1/029676e5793de2364725d6d9a10d3567.jpg', '<p>Bei Yan và Wen Zixiang lớn lên cùng nhau và được cho là một cặp. Tuy nhiên, Yin cần tiền cho bà ngoại đang bị bệnh nặng. Vì vậy, cô kết hôn với một người đàn ông khá giả ở Anh.

Cô phải điều hành nhà hàng cho chồng và chăm sóc đứa con gái bị tật nguyền Ye Fan của họ. Vậy mà người chồng bất lực lại thường xuyên bạo hành cô.

Sau đó, anh ta mất nhà hàng trong một canh bạc và biến mất. Yin trở về Hong Kong và kết hôn với luật sư nổi tiếng Gao Jun. Đúng lúc này, Wen xuất hiện trở lại. Fan đã yêu anh, nhưng Wen không thể quên được Yin. Đối mặt với yêu hận đan xen mãnh liệt này, bốn người này sẽ ra sao?</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sylvia Chang","avatar":""},{"name":"Emil Wakin Chau","avatar":""},{"name":"Anita Yuen","avatar":""},{"name":"Winston Chao","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324337);
