INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-toi-te', 'Kỳ Nghỉ Tồi Tệ', 'Becky', 'https://phimimg.com/upload/vod/20240205-1/1d35a41a2739d5b3ea2883eb28743db5.jpg', 'https://phimimg.com/upload/vod/20240205-1/1447f514f4b8d16ac90077a0031ec10f.jpg', '<p>Sau khi mất mẹ, Becky và cha cô đi du lịch đến ngôi nhà ven hồ của họ với cô bạn gái mới của bố cô và con trai của cô ấy. Becky cố gắng làm thân lại với cha cô trong chuyến đi này. Nhưng cuộc vui sớm trở nên tồi tệ khi những kẻ bị kết án đang trên đường chạy trốn, dẫn đầu bởi tên sát nhaatn Dominick tàn nhẫn, bất ngờ xâm nhập ngôi nhà.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lulu Wilson","avatar":""},{"name":"Kevin James","avatar":""},{"name":"Joel McHale","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324337);
