INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-tram-toa-tam-thien', 'Thanh Trâm Toả Tam Thiên', 'Love In The Kitchen', 'https://phimimg.com/upload/vod/20240205-1/0fc4f29ae08500b5e9bb64dfcadc9014.jpg', 'https://phimimg.com/upload/vod/20240205-1/e5c399f6fe9eab67aa7bc21469c35757.jpg', '<p>Mối tình oan gia cực kì ngọt ngào! Tam Thiên, thiếu gia họ Bạch giàu có say mê tay nghề của cô nàng đầu bếp nhà mình, nhưng cô đầu bếp xinh đẹp Thanh Trâm lại một lòng muốn rời khỏi Bạch phủ để theo đuổi ước mơ của bản thân. Tam Thiên sao có thể để cho Thanh Trâm rời Bạch phủ được. Thế là hai người cãi nhau không ít lần vì chuyện này, thậm chí có một lần, Tam Thiên trực tiếp cắn Thanh Trâm. Thực ra Bạch thiếu gia đã bị Thanh Trâm lôi cuốn từ lâu, và Thanh Trâm cũng thầm yêu thiếu gia sâu nặng. Thanh Trâm có thể thực hiện được ước mơ và cuối cùng hai người có đến được với nhau hay không?</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Since","avatar":""},{"name":"Xiong Su Yi","avatar":""},{"name":"Niu Ze Meng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324337);
