INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gen-y-the-series', 'GEN Y The Series', 'GEN Y The Series', 'https://phimimg.com/upload/vod/20240118-1/c46a87198ea6ce5756699027569c8926.jpg', 'https://phimimg.com/upload/vod/20240118-1/9aad51a0f1dab11cece7a0e864540f79.jpg', '<p>Sau khi chia tay với Pha, Wayu được người anh em tốt Mark hết lòng quan tâm. Một ngày nọ, Mark dự định theo đuổi Kit, nhân vật nổi tiếng, khó tiếp cận của trường y. Vào ngày đầu tiên khi Mark chuẩn bị thực hiện kế hoạch theo đuổi Kit, Pha muốn gặp Wayu. Hôm đó, Mark bị từ chối, Pha cũng không xuất hiện. Mark và Wayu chìm trong thất vọng, chán nản. Dần dần, Wayu bắt đầu chấp nhận cuộc sống không có Pha, đồng thời khích lệ Mark tìm Kit một lần nữa. Kit và Mark quyết định cho nhau thêm một cơ hội. Khi mọi việc đang suôn sẻ, Pha trở lại...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 16, 2020, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Bas Suradet Piniwat","avatar":""},{"name":"Kimmon Warodom Khemmonta","avatar":""},{"name":"Copter Panuwat Kerdthongtavee","avatar":""},{"name":"Dun Romchampa","avatar":""},{"name":"Bank Thoranin Manosudprasit","avatar":""},{"name":"Bonus Thanadech Deeseesuk","avatar":""},{"name":"Bank Thanathip Srithongsuk","avatar":""},{"name":"Pon Thanapon Aiemkumchai","avatar":""},{"name":"Kad Ploysupa","avatar":""},{"name":"Jet Jetsadakorn Bundit","avatar":""},{"name":"Bank","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324337);
