INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-mo-am', 'Thiếu Nữ Mờ Ám', 'Ugly Beauty', 'https://phimimg.com/upload/vod/20240128-1/1e5833e2a3d647b44b7659cce8fa829c.jpg', 'https://phimimg.com/upload/vod/20240128-1/5aecd4d3649d68da8e6200307cbba5cc.jpg', '<p>Cô bé Lọ Lem phiên bản hiện đại. Bạch Vũ Đồng do ngoại hình không đẹp nên cực kỳ tự ti. Vào sinh nhật 20 tuổi, cô đã ước trở nên xinh đẹp, cuối cùng ước nguyện đã thành hiện thực. Nhưng thời hạn trở nên xinh đẹp của cô chỉ có một tháng, cuối cùng cô chỉ có thể dùng dáng vẻ ban đầu đối diện với người mình yêu...</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Di Yi Shu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324337);
