INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-thanh', 'Đại Thánh', 'Monkey King', 'https://phimimg.com/upload/vod/20240128-1/0cce1909be2d6a8f710fdadf22fa6422.jpg', 'https://phimimg.com/upload/vod/20240128-1/b9fa37ecb0663ffeee288569e7d461dc.jpg', '<p>Giới thiệu: Tôn Ngộ Không trúng phải quỷ kế của lão quái Hoàng Mi, bị giam giữ đồng thời mất toàn bộ pháp lực. Lão quái Hoàng Mi xây dựng một đội quân hùng mạnh, thiết lập Đấu trường sinh tử, dùng bùn đất tạo ra Lục Nhĩ Mỹ Hầu để thay thế cho Tôn Ngộ Không thật. Tôn Ngộ Không bị áp bức rơi vào tuyệt vọng. Một kẻ quen chiến đấu đơn độc bị ép phải liên minh với các yêu quái để tự cứu mình. Sau hết thất bại này đến thất bại khác đã ngộ ra được ý nghĩa thực sự của hai chữ \Đại Thánh\.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liang Jie Li","avatar":""},{"name":"Cai Lu","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324337);
