INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-cay-uoc-nguyen', 'Giải Cứu Cây Ước Nguyện', 'The Wishmas Tree', 'https://phimimg.com/upload/vod/20240128-1/6d34d7b0cf0d78c9746a34c596b3bd23.jpg', 'https://phimimg.com/upload/vod/20240128-1/a107c8545bcc5773a3ab2df47aa03172.jpg', '<p>Kerry, một cô nàng thú túi nhận được một điều ước và cô đã ước rằng cô có thể có một cây Ước Nguyện màu trắng. Thế nhưng, cách mà cô ước lại hoá sai và tệ hại hơn, nó làm đóng băng toàn bộ thành phố Sanctuary City của cô, còn đe dọa cuộc sống của tất cả những người sống ở đó.</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Lồng Tiếng', 'HD', 'Úc', 0, '[{"name":"Miranda Tapsell","avatar":""},{"name":"Ross Noble","avatar":""},{"name":"Kate Murphy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324337);
