INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-soc-me-van', 'Hà Sóc Mê Vân', 'Hà Sóc Mê Vân', 'https://phimimg.com/upload/vod/20240128-1/8a6d39b0351d0563138da1d657a4d570.jpg', 'https://phimimg.com/upload/vod/20240128-1/b2f011a03370db133d5f9f36addf96fa.jpg', '<p>Khi màn đêm buông xuống, Tiết độ sứ U Châu Trương Bá Tĩnh hoảng loạn chạy trốn, nhưng không ngờ đằng sau có một thanh kiếm phi đến. Chuyện này đã làm kinh động toàn bộ triều đình. Hoàng thượng lệnh cho Bùi Chuẩn đến U Châu điều tra rõ ngọn ngành. Cùng lúc đó, tên què dắt ngựa nhận được giang hồ lệnh, mời Tô Yến Nam và Kính Nguyệt đến U Châu tìm một nữ nhân. Từ đây, mâu thuẫn giữa giang hồ và triều đình chính thức bắt đầu.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Mã Suất","avatar":""},{"name":"Từ Thư Oánh","avatar":""},{"name":"Lư Quán Đông","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324337);
