INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-troi-tu-than', 'Vùng Trời Tử Thần', 'Horizon Line', 'https://phimimg.com/upload/vod/20240128-1/4141ceb5f3201460f7bb2068fe7075eb.jpg', 'https://phimimg.com/upload/vod/20240128-1/b041acac430e74ee246509a061110651.jpg', '<p>Một cặp vợ chồng bay trên một chiếc máy bay nhỏ để theo học một đám cưới trên đảo nhiệt đới phải chiến đấu cho cuộc sống của họ sau khi phi công của họ bị đau tim.</p>', 'Full', 1, 'single', 'completed', 16, 2020, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324337);
