INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xich-ho-thu-sinh', 'Xích Hồ Thư Sinh', 'Soul Snatcher', 'https://phimimg.com/upload/vod/20240127-1/f4fc498f038039bac7a71fa65fe8410d.jpg', 'https://phimimg.com/upload/vod/20240127-1/257f3afcc5953508a95426ab71138c8e.jpg', '<p>Chàng thư sinh nghèo Vương Tử Tiến (Trần Lập Nông) đang trên đường vào kinh để dự thi thì bị tiểu yêu hồ hạ phàm để lấy đan Bạch Thập Tam (Lý Hiện) nhắm tới. Chỉ cần giết chết Vương Tử Tiến, lấy mất viên đan thì Bạch Thập Tam có thể trở thành hồ tiên. Nào ngờ trong quá trình lấy đan thì hai bên trở thành bạn tốt của nhau. Trải qua bao nhiêu kiếp nạn, cuối cùng Bạch Thập Tam sẽ lựa chọn ra sao?</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Hiện","avatar":""},{"name":"LEO","avatar":""},{"name":"Cáp Ni Khắc Tư","avatar":""},{"name":"Pei Kui Shan","avatar":""},{"name":"Jiang Chao","avatar":""},{"name":"MorniChang","avatar":""},{"name":"David Wang","avatar":""},{"name":"Steven Hao","avatar":""},{"name":"Tanny Tian","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
