INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-long-than-chuong-to-khat-nhi-2', 'Giáng Long Thần Chưởng Tô Khất Nhi 2', 'Master So Dragon Subduing Palms 2', 'https://phimimg.com/upload/vod/20240126-1/1f814bcf2ba3f9315f99d266391d7e58.jpg', 'https://phimimg.com/upload/vod/20240126-1/46bcca8e43aa509dd139bb60c0afa505.jpg', '<p>Phim Giáng Long Thần Chưởng Tô Khất Nhi 2 - Master So Dragon Subduing Palms 2 kể về hai quan tòa của huyện Lâm Giang hẻo lánh bị giết bởi một viên thắt cổ tự tử. Su Qi’er và Tie Qiaosan, Đội bảo vệ của Cung điện, đến huyện Lâm Giang để điều tra vụ việc. Vì không thể nhận được bất kỳ sự giúp đỡ nào, họ che giấu danh tính của mình và tham gia vào băng nhóm ăn xin để điều tra. Không muốn khuất phục trước nghịch cảnh và với niềm tin vào công lý, họ tiếp tục chiến đấu bằng trí thông minh và lòng dũng cảm chống lại những kẻ chủ mưu của vụ án.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Fengye Lin","avatar":""},{"name":"Pengfei Yue","avatar":""},{"name":"Xinyan Yu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
