INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-suong-truong-an', 'Quái Vật Sương Trường An', 'Chang''An Fog Monster', 'https://phimimg.com/upload/vod/20240126-1/29de947c042b47dfe924d718685b4636.jpg', 'https://phimimg.com/upload/vod/20240126-1/4dcac8894f9578a7eed3d8f6bc8b2f8d.jpg', '<p>Quái vật sương Trường An - ChangAn Fog Monster là bộ phim thuộc thể loại kinh dị, giật gân, giả tưởng, cổ trang của Trung Quốc. Tác phẩm do đạo diễn Lv Lei chịu trách nhiệm chỉ đạo, với sự tham gia của các diễn viên Luo Liqun, Cheng Qimeng, Li Borong, Hu Dongqing, Yang Ming, Wang Pan, Liu Yuetao và Ni Xuezeng. Thành phố Trường An đã bị nhấn chìm bởi một màn sương mù dày đặc một cách bất ngờ, và mọi người bắt đầu chạy trốn trong hoảng loạn. Kẻ xấu Xiao Cheng canh giữ hoàng tử yếu đuối và bị mắc kẹt với thường dân, chờ sương tan. Tuy nhiên, sương mù dày đặc đã không biến mất như mong đợi, những người đi vào màn sương mù dày đặc đó đã không bao giờ trở lại, những con quái vật kinh rợn trong sương mù dần lộ diện, Xiao Cheng đã chiến đấu quên mình để bảo vệ Trường An.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324337);
