INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-cua-nhung-giac-mo', 'Chiến Binh Của Những Giấc Mơ', 'Clouds', 'https://phimimg.com/upload/vod/20240123-1/a9b20d5149e1e1fa5f109d87cd479cac.jpg', 'https://phimimg.com/upload/vod/20240123-1/c37aea97b83d28cdae32ebd97a59a938.jpg', '<p>Nhạc sĩ trẻ Zach Sobiech phát hiện ra ung thư của mình đã lan rộng, khiến anh ta chỉ còn vài tháng để sống. Với thời gian giới hạn, anh theo giấc mơ của mình và tạo ra một album, không biết rằng sẽ sớm trở thành một hiện tượng âm nhạc virus.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324337);
