INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('juanqini-giang-sinh-toi-te', 'Juanqini: Giáng Sinh Tồi Tệ', 'An Unremarkable Christmas', 'https://phimimg.com/upload/vod/20240123-1/a108191430a9380de8c935cb999d8a13.jpg', 'https://phimimg.com/upload/vod/20240123-1/d21c46fa8c1d619f36947d90286dc974.jpg', '<p>Kế toán viên muốn làm ảo thuật gia mời sếp đến mừng Giáng sinh cùng gia đình – mà không biết rằng hắn là một trong những tội phạm bị truy nã gắt gao nhất Colombia.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Antonio Sanint","avatar":""},{"name":"Luis Eduardo Arango","avatar":""},{"name":"María Cecilia Sánchez","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324337);
