INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('josee-nang-tho-cua-toi', 'Josée, Nàng Thơ Của Tôi', 'Josée', 'https://phimimg.com/upload/vod/20240123-1/74ffbaf17c965605deab32cfa985ab69.jpg', 'https://phimimg.com/upload/vod/20240123-1/924d1072357c4d420f3bfeb0725580ab.jpg', '<p>Remake từ bộ phim điện ảnh Nhật Bản cùng tên. Trong một lần tình cờ, chàng trai Young Seok (Nam Joo Hyuk thủ vai) đã gặp gỡ và quen biết với cô gái tàn tật Jose. Cô thích đọc sách, thường xuyên tưởng tượng ra thế giới của riêng mình theo nội dung những cuốn sách đã đọc. Young Seok dần có tình cảm với Jose, đồng thời cũng dần bước vào cuộc sống của cô. Lần đầu tiên trong đời, Jose cảm nhận được sự rung động do tình yêu đem lại, vậy nhưng cô lại muốn từ chối mối tình này.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"南柱赫","avatar":""},{"name":"Han Ji Min","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324337);
