INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('le-hoi-cua-rifkin', 'Lễ Hội Của Rifkin', 'Rifkin''s Festival', 'https://phimimg.com/upload/vod/20240123-1/c4b03b371ac887072f6a4ba3584be673.jpg', 'https://phimimg.com/upload/vod/20240123-1/a92c98e58566a5e966cd703e69f23399.jpg', '<p>Rifkin’s Festival xoay quanh cặp vợ chồng người Mỹ đến Liên hoan phim San Sebastian và bị cuốn vào sự kỳ diệu của lễ hội, cùng vẻ đẹp và sự quyến rũ của Tây Ban Nha cũng như sự kỳ ảo của những bộ phim. Tôi chỉ đi bởi vì tôi không thể rũ bỏ mối nghi ngờ rằng cô ấy đã có chút cảm nắng tên đạo diễn phim nhảm nhí này! - Anh chồng nói.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Wallace Shawn","avatar":""},{"name":"Gina Gershon","avatar":""},{"name":"Louis Garrel","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324337);
