INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-chan-bang-than', 'Dấu Chân Băng Thần', 'FootPrint In The Snow', 'https://phimimg.com/upload/vod/20240123-1/306b78ffb8718c969878e80dbcc611ec.jpg', 'https://phimimg.com/upload/vod/20240123-1/9dce9a926c837fde42c021612c2031a5.jpg', '<p>Khúc côn cầu trên băng luôn là môn thể thao vua trong các kỳ thế vận hội mùa đông. Các quốc gia quyền lực băng tuyết như Nhật Bản, Hàn Quốc, Pháp, Áo, Thụy Sỹ, Đức, Na Uy, Mỹ, Canada ráo riết tập luyện để chuẩn bị cho Thế vận hội Olympic Bắc Kinh 2020. Khúc côn cầu trên băng là một môn thể thao đòi hỏi tốc độ nhanh, quả cảm và dũng mãnh. Không hỏi xuất thân, không phân biệt già trẻ, thứ khúc côn cầu mang lại cho con người là tốc độ siêu phàm, là nhiệt huyết trào dâng, là sự theo đuổi trong suốt cuộc đời, là niềm đam mê vượt trên sinh tử.Bộ phim tài liệu của NewTV sẽ giúp bạn hiểu hơn về bộ môn thể thao tuyệt vời này.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324337);
