INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-thien-linh-tien-tu', 'Địch Nhân Kiệt: Thiên Linh Tiên Tử', 'Di Ren Jie: Zhi Fei Tou Luo Cha', 'https://phimimg.com/upload/vod/20240126-1/3bd6929209dbfc7acbc7d4f65a7b9921.jpg', 'https://phimimg.com/upload/vod/20240126-1/27fc1db38390a4b77f3a7c3d79a6d37d.jpg', '<p>Sắp đến giờ làm lễ cầu phúc, trên trời xuất hiện một cái đầu bay khổng lồ, mọi người nhất thời hoảng sợ . Địch Nhân Kiệt bắt đầu vào cuộc điều tra.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Dương Cung Như","avatar":""},{"name":"La Lập Quần","avatar":""},{"name":"Lý Nhược Hi","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324337);
