INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-tac-dai-chien', 'Đạo Tặc Đại Chiến', 'The Hustle', 'https://phimimg.com/upload/vod/20240124-1/67a58071ee3f690e5224a82f411fcd49.jpg', 'https://phimimg.com/upload/vod/20240124-1/2ee7baa94922703353d7e455b9298c68.jpg', '<p>Bộ phim Đạo Tặc Đại Chiến - The Hustle kể về cậu chuyện của những kẻ lừa đảo chuyên nghiệp. Khi Niệm Niệm và Tiểu Phàm đã cướp các hợp đồng cho vay nặng lãi của Chủ tịch Ba keo kiệt. Kiệt Uy được lệnh phải bắt hai kẻ lừa đảo về. Nhưng anh ta không chỉ đã lấy trộm mười triệu đô la tiền mặt của Lão Ba anh còn định sẽ sử dụng tất cả trí thông minh của mình để lừa tiền cả hai bên. Tuy nhiên, không một bên nào trong số các bên liên quan sẵn sàng từ bỏ hợp đồng cho vay hoặc mười triệu đô la tiền mặt. Mỗi bên liên quan đều xảo quyệt và cố gắng che giấu những người khác bằng nhiều thủ đoạn lừa gạt, hy vọng thu được lợi nhuận từ tình huống này.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Tiểu Man","avatar":""},{"name":"Thiệu Tường","avatar":""},{"name":"Trần Ấu Phương","avatar":""},{"name":"A Hỉ","avatar":""},{"name":"Khâu Dật Phong","avatar":""},{"name":"Trương Minh Kiệt","avatar":""},{"name":"Vương Vi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324337);
