INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-la-toi', 'Yêu Là Tội', 'The Lovebirds', 'https://phimimg.com/upload/vod/20240124-1/3fa449b12f651a06e1470050fdc27c95.jpg', 'https://phimimg.com/upload/vod/20240124-1/244acad809228ef1816bfa4d9b8f7be4.jpg', '<p>Sắp đường ai nấy bước mà lại vô tình vướng vào vụ án mạng, cặp đôi buộc phải lao vào cuộc đua dữ dội nhằm tìm ra kẻ sát nhân và chứng minh cả hai vô tội.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Issa Rae","avatar":""},{"name":"Kumail Nanjiani","avatar":""},{"name":"Paul Sparks","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
