INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-phat-sang', 'Cây Phát Sáng', 'Magic Bag Full Of Wishes 11', 'https://phimimg.com/upload/vod/20240123-1/faf981736236ab3de4a311ed4557e49d.jpg', 'https://phimimg.com/upload/vod/20240123-1/be1557bd34bd560be7b2bdcb0f7f7026.jpg', '<p>Mi Le là chú tiểu hạnh phúc nhất trong Đền Xuedou - bởi vì cậu biết rằng cậu có thể biến giấc mơ của mọi người thành hiện thực! Khi người dân địa phương cầu nguyện tại ngôi đền của cậu - ngồi trên đỉnh những ngọn núi đẹp mà Mi Le gọi là nhà - cậu hành động với sự giúp đỡ của bạn mình, Lin, và một đội quân những chiếc túi tinh nghịch sống bí mật bên dưới ngôi đền. Cậu thậm chí còn kết bạn với một trong những chiếc túi, Buddy, người đi cùng Mi Le khắp mọi nơi. Mỗi tập phim, Mi Le vụng về, Lin cứng rắn và những chiếc túi lập dị hợp sức để thực hiện những giấc mơ thân yêu nhất của người dân thị trấn.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2020, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
