INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-vong-tu-dia-nguc', 'Tiếng Vọng Từ Địa Ngục', 'The Voices', 'https://phimimg.com/upload/vod/20240123-1/0a7287a0133e60d03c1313b068e84139.jpg', 'https://phimimg.com/upload/vod/20240123-1/8357177ca1ee6eda6bf26a4c60345196.jpg', '<p>Tiếng Vọng Từ Địa Ngục - The Voices xoay quanh câu chuyện kì bí xảy ra với Grace khi phải vật lộn với chứng bệnh tâm thần phân liệt hoang tưởng của chị gái vừa đối mặt với nhiều tình huống kinh dị và quái gở xảy ra trong căn nhà. Khi ranh giới giữa thực tế và giấc mơ bị xóa nhòa, cô phải làm gì khi không còn khả năng phân biệt thật - giả?</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Brendan Sexton III","avatar":""},{"name":"Amanda Markowitz","avatar":""},{"name":"Juliana Sada","avatar":""},{"name":"Lin Shaye","avatar":""},{"name":"Victoria Matlock","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324337);
