INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-bao-thanh-thien-nam-hiep-ky-an', 'Tân Bao Thanh Thiên: Nam Hiệp Kỳ Án', 'Justice Bao: The Myth Of Zhanzhao', 'https://phimimg.com/upload/vod/20240123-1/d9493d2222de1222e49472d3c99826bf.jpg', 'https://phimimg.com/upload/vod/20240123-1/69a64c5799e7d65098ddba256b901d19.jpg', '<p>Tân Bao Thanh Thiên: Nam Hiệp Kỳ Án - Justice Bao: The Myth Of Zhanzhao xoanh quanh Bao Chửng đại phá một kỳ án. Thời Bắc Tống trời có điềm lạ, mặt trăng màu tím, kẻ ác lấy danh nghĩa trăng tím gây án khắp nơi. Bao Chửng nhận lệnh điều tra tận gốc tổ chức đứng sau vụ trăng tím, phá liên tiếp từng tầng lớp của vụ án. Cuối cùng trăng tím biến mất, Bao Chửng và Triển Chiêu hợp sức giệt trừ tổ chức mặt trăng tím đó, trả lại thái bình cho thiên hạ.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Xin Zhe","avatar":""},{"name":"Victor Huang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
