INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-thuc-tai-kinh-hoang', 'Bẫy Thực Tại Kinh Hoàng', 'Antebellum', 'https://phimimg.com/upload/vod/20240123-1/7c99996059c3c3a2023dbe6878e37324.jpg', 'https://phimimg.com/upload/vod/20240123-1/3b53fd820b63309aed0e33e8e97ed5e5.jpg', '<p>Bẫy Thực Tại Kinh Hoàng - Antebellum là bộ phim đến từ nhà sản xuất của Get Out và US. Nữ nhà văn, diễn giả nổi tiếng và vô cùng thành công Veronica (Janelle Monáe) bị một thế lực bí ẩn kéo về kỷ nguyên Antebellum, thời kỳ tiền nội chiến kinh hoàng của quá khứ, khi những người Mỹ gốc Phi giống cô bị bắt làm nô lệ. Veronica buộc phải tìm mọi cách để sống sót, chiến đấu và giành lại cuộc sống vốn có của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Huston","avatar":""},{"name":"Janelle Monáe","avatar":""},{"name":"Jena Malone","avatar":""},{"name":"Kiersey Clemons","avatar":""},{"name":"Robert Aramayo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324337);
