INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-su-tru-yeu', 'Đại Sư Trừ Yêu', 'The Conqueror', 'https://phimimg.com/upload/vod/20240122-1/3e15175330de7ce388e89be97f2d1ebd.jpg', 'https://phimimg.com/upload/vod/20240122-1/1e0106ab490faf15e291aabfe132865d.jpg', '<p>Trấn nhỏ ở biên thùy nhiều lần bị yêu ma xâm phạm, Ngô Tịnh Tử gửi cáo thị trừ yêu, mời các thầy trừ yêu khắp nơi đến chi viện. A Thập, Mạnh Châu, đại sư huynh Bộ Uy Long mê đắm Mạnh Châu, và các thầy trừ yêu khác cùng đến động Vân Sạn. Trên đường đi, mọi người đã gặp vô số yêu quái cản trở, quá quan trảm tướng. Nhưng kết quả lại ngoài dự liệu...</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"史梓辰","avatar":""},{"name":"周婧（演员）","avatar":""},{"name":"Li Cen Yi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324337);
