INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-vua-dao-staten', 'Ông Vua Đảo Staten', 'The King Of Staten Island', 'https://phimimg.com/upload/vod/20240122-1/a84905f55ca23d9079e67434ba056d20.jpg', 'https://phimimg.com/upload/vod/20240122-1/16bc104859c6b5e5f39255e227c2f9f1.jpg', '<p>Scott đã là một trường hợp phát triển bị bắt vì cha lính cứu hỏa của ông đã chết. Anh ta dành nhiều ngày hút cỏ dại và mơ thấy là một nghệ sĩ xăm hình cho đến khi các sự kiện buộc anh ta vật lộn với sự đau buồn của mình và thực hiện những bước đầu tiên về phía trước trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324337);
