INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-tro-thanh-su-that', 'Giấc Mơ Trở Thành Sự Thật', 'Come True', 'https://phimimg.com/upload/vod/20240121-1/c9aaaf353b635d431d7d32c16ad4fcb5.jpg', 'https://phimimg.com/upload/vod/20240121-1/c238a14f4764675126c49d4411a146e7.jpg', '<p>Giấc Mơ Trở Thành Sự Thật - Come True (2020) là một bộ phim khoa học viễn tưởng pha lẫn yếu tố kinh dị của Mỹ do Anthony Scott Bus đạo diễn kiêm biên kịch. Bộ phim có sự tham gia của Landon Liboiron, Julia Sarah Stone, Skylar Radzion, Tiffany Helm, Tedra Rogers, Chantal Perron. Nội dung phim xoay quanh một thiếu niên bỏ trốn khi tham gia vào một nghiên cứu về giấc ngủ của con người. Giấc mộng đã trở thành nỗi ám ảnh kéo theo những cơn ác mộng khơi gợi nỗi sợ hãi sâu thẳm trong tâm trí của cô ấy. Nghiên cứu trở thành bài kiểm tra đáng sợ về sức mạnh không tưởng của những giấc mơ.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Julia Sarah Stone","avatar":""},{"name":"Landon Liboiron","avatar":""},{"name":"Tedra Rogers","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324337);
