INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bump-of-chicken-tour-2019-aurora-ark-tokyo-dome', 'BUMP OF CHICKEN TOUR 2019 Aurora Ark TOKYO DOME', 'BUMP OF CHICKEN TOUR 2019 Aurora Ark TOKYO DOME', 'https://phimimg.com/upload/vod/20240207-1/75a0470812e8ca28d1cb43e437acce20.jpg', 'https://phimimg.com/upload/vod/20240207-1/7a8254a2b7cdeb6ab5f0d252601f705e.jpg', '<p>Hiện tượng nhạc rock Bump of Chicken biểu diễn hết mình khi bước lên sân khấu trong buổi diễn cuối của chuyến lưu diễn Aurora Ark năm 2019 cực kỳ thành công của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"BUMP OF CHICKEN","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324337);
