INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-da-yeu-ban-than-cua-em', 'Anh Đã Yêu Bạn Thân Của Em', 'Another Me', 'https://phimimg.com/upload/vod/20240116-1/012b12b426557fc95b2e89d5fde3938f.jpg', 'https://phimimg.com/upload/vod/20240116-1/fa0ee73e601a60667e9e13183c93acb7.jpg', '<p>Chuyện xoay quanh đôi bạn thân từ nhỏ đến lớn là Lý An Sinh và Lâm Thất Nguyệt. Hai cô bạn luôn bên cạnh nhau như hình với bóng và duy trì một mối quan hệ tốt đẹp. Thế nhưng mọi việc bắt đầu phức tạp khi hai cô gái đến tuổi biết yêu và cùng thích chàng trai Tô Gia Minh. Bên ngoài An Sinh luôn giúp đỡ vun vén cho Thất Nguyệt và Gia Minh, nhưng trong lòng cô biết mình đã yêu Gia Minh. Còn Gia Minh, anh càng ngày càng bị vẻ cá tính của An Sinh thu hút. An Sinh muốn duy trì tình bạn bền đẹp nên cô quyết định giải thoát cho cả 3. An Sinh cùng A Phan là một ca sĩ quán bar lên thành phố lập nghiệp. Còn lại Thất Nguyệt và Gia Minh, 2 người vào 2 trường đại học khác nhau và bắt đầu yêu nhau. Đúng lúc này đôi tình nhân An Sinh và A Phan cũng kết thúc mối quan hệ. An Sinh quen biết với doanh nhân Hàn Đông, cô bắt đầu thay đổi công việc để bắt đầu cuộc sống mới. Sau khi tốt nghiệp đại học, Thất Nguyệt và Gia Minh dự định kết hôn nhưng Gia Minh kiếm cớ liên tục trì hoãn. Thất Nguyệt tìm đến nơi làm việc của Gia Minh thì cô đau đớn phát hiện Gia Minh và An Sinh đang yêu nhau…</p>', 'Hoàn Tất (53/53)', 53, 'series', 'completed', 12, 2020, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324337);
