INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-lung-quai-yeu', 'Truy Lùng Quái Yêu', 'Monster Hunter', 'https://phimimg.com/upload/vod/20240121-1/edf32af2b49b41e10934bb9dbb02af69.jpg', 'https://phimimg.com/upload/vod/20240121-1/e5555c33b4f009df051301474eb22c38.jpg', '<p>Một con quái vật lại xuất hiện trong thế giới con người và gây bao cảnh giết chóc. Tay săn quái vật siêu ngầu trên đường giải cứu thiếu nữ yếu đuối cùng hợp tác với một nữ minh tinh nổi tiếng và một chàng thiếu gia giàu có để chống lại con quỷ. Liệu những hành động này có xuất phát từ tình yêu?</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"A Tín","avatar":""},{"name":"Ma Li","avatar":""},{"name":"Wang Qun Shi","avatar":""},{"name":"You Yi Ze","avatar":""},{"name":"Cai Hua","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324337);
