INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hung-than-trang', 'Hung Thần Trắng', 'Great White', 'https://phimimg.com/upload/vod/20240121-1/a894fce43f586d27ace69e217e8d5068.jpg', 'https://phimimg.com/upload/vod/20240121-1/380d1e24ded7019bc72703f4cc56c920.jpg', '<p>Đấu tranh để giữ cho doanh nghiệp thủy phi cơ nhỏ của họ, Charlie, một nhà sinh vật học biển đã nghỉ hưu và người sống sót cá mập, bạn gái Kaz và người bạn Benny, rất vui mừng khi họ được vận hành bởi những người đi dạo cuồng, Joji và vợ, Michelle. Tuy nhiên, ngay khi Seafplane hạ cánh trên một bãi biển cát của Remote Hell, thảm họa và đội bóng phát hiện mình bị mắc kẹt trong một chiếc xuồng cứu sinh bơm hơi mỏng manh với nguồn cung hạn chế. Bây giờ, phi hành đoàn đáng tiếc trôi dạt vô vọng trong bóng tối, vùng biển sâu của đại dương rộng lớn, và họ không đơn độc: một con cá mập trắng tuyệt vời, lén lút đã nhặt được mùi hương của chúng, và nó sẽ dừng lại ở bất cứ điều gì để nuôi. Họ có thể thoát khỏi hàm mạnh mẽ của động vật ăn thịt đỉnh đại dương cuối cùng?</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Thuyết Minh', 'HD', 'Úc', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324337);
