INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-quy-rung-sau', 'Dạ Quỷ Rừng Sâu', 'The Widow (Vdova)', 'https://phimimg.com/upload/vod/20240104-1/ba53d03408eb7742726ed780f441c536.jpg', 'https://phimimg.com/upload/vod/20240104-1/14485b326c67c9b6b7ecbdee569c9536.jpg', '<p>Dạ quỷ rừng sâu - The Widow (2020) là bộ phim thuộc thể loại kinh dị, bí ẩn, giật gân của Nga. Tác phẩm do Ivan Minin chịu trách nhiệm chỉ đạo, với sự tham gia của các diễn viên Viktotiya Potemina, Anastasiya Gribova và Margarita Bychkova. Mở đầu phim là bối cảnh hơn 300 người biến mất trong các khu rừng xung quanh St.Petersburg mỗi năm. Một số được tìm thấy đã chết trong trạng thái khỏa thân. Một số khác đã không còn được tìm thấy. Điều này có liên quan đến các cuộc phỏng vấn với người địa phương, khi họ nói rằng cảm thấy có gì đó ở trong khu rừng, nơi mà họ gọi là The Lame Widow.</p>', 'Full', 1, 'single', 'completed', 17, 2020, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Viktotiya Potemina","avatar":""},{"name":"Anastasiya Gribova","avatar":""},{"name":"Margarita Bychkova","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324337);
