INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gieng-toa-long', 'Giếng Tỏa Long', 'The  Dragon Hunting Well', 'https://phimimg.com/upload/vod/20240104-1/5c682cad407b69d7404740d38519c2bc.jpg', 'https://phimimg.com/upload/vod/20240104-1/18a0f64f5a6cd694ce3394d0c5ac3e53.jpg', '<p>Nghiên cứu sinh ngành Y từ nước ngoài về đến thị trấn Mê Vụ để vận chuyển vật tư y tế phòng dịch bệnh, thế nhưng lại bị quái vật tấn công. Để bảo vệ người sống sót, anh chung tay với y bác sĩ giết chết quái vật thành công và tìm được cách chữa bệnh tốt nhất</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"孫耀威","avatar":""},{"name":"Peng Gao Chang","avatar":""},{"name":"Pei Chen Wei","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324337);
