INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-giay', 'Một Giây', 'One Second', 'https://phimimg.com/upload/vod/20240104-1/92094644ce88b502bbe8c44f8696fca0.jpg', 'https://phimimg.com/upload/vod/20240104-1/c01e20ea27b9c01bed899846db381238.jpg', '<p>Một Giây lấy bối cảnh thời cách mạng văn hóa Trung Quốc từ 1966-1976, nội dung kể về một tù nhân trốn trại tù cách mạng văn hóa và một cô gái trẻ nông thôn khi cả hai cùng tìm kiếm một cuốn phim bí ẩn. Người đàn ông tìm cuốn phim vì muốn tìm lại hình ảnh của cô con gái nhỏ yêu quý, còn cô gái trẻ tìm cuốn phim vì động cơ tuyệt vọng và hối lỗi...</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yi Zhang","avatar":""},{"name":"Haocun Liu","avatar":""},{"name":"Wei Fan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324338);
