INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-giay', 'Một Giây', 'One Second', 'một giây one second yi zhang haocun liu wei fan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-ca-sau', 'Đảo Cá Sấu', 'Crocodile Island', 'https://phimimg.com/upload/vod/20240104-1/0f862d3e8f0ca18ce0b893e9313ca888.jpg', 'https://phimimg.com/upload/vod/20240104-1/5a9d8c69d169b4343706afadfd9c2a5e.jpg', '<p>Đảo Cá Sấu - Crocodile Island là cuộc chiến sinh tồn của những người sống sót trên chuyến bay quốc tế gặp nạn trên hòn đảo không người ở Nam Thái Bình Dương, nơi một con cá sấu ăn thịt người khổng lồ sống. Lâm Hạo cùng những người khác buộc phải tìm được thiết bị liên lạc trên máy bay thế chiến thứ 2 mới có thể sống sót. Đứng trước sự sống và cái chết, có người vì tình thân, tình bạn, tình yêu mà dũng cảm đứng ra quyết chiến sinh tử với cá sấu khổng lồ.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"He Qi Wei","avatar":""},{"name":"Hu Xue Er","avatar":""},{"name":"Gallen Lo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324338);
