INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-cuoi', 'Lời Cuối', 'The Last Word', 'https://phimimg.com/upload/vod/20240116-1/9c2f62e9df387bf658ffb25c12828765.jpg', 'https://phimimg.com/upload/vod/20240116-1/109cbee00f1c01ccf25dfd591e8c9a07.jpg', '<p>Khi chồng đột ngột qua đời, một phụ nữ thắp lại khát vọng sống bằng cách trở thành người đọc điếu văn và đối diện khủng hoảng hiện sinh về cái chết, nỗi đau và tình yêu.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2020, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Anke Engelke","avatar":""},{"name":"Thorsten Merten","avatar":""},{"name":"Nina Gummich","avatar":""},{"name":"Johannes Zeiler","avatar":""},{"name":"Juri Winkler","avatar":""},{"name":"Gudrun Ritter","avatar":""},{"name":"Aaron Hilmer","avatar":""},{"name":"Claudia Geisler-Bading","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324338);
