INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-toi-ganh-doi', 'Mẹ Tôi Gánh Đội', 'Mother Gamer', 'https://phimimg.com/upload/vod/20240104-1/bf67bc5b4ee2747d880754c001116ad0.jpg', 'https://phimimg.com/upload/vod/20240104-1/5051c583fe6c751ae4bea207bb31254c.jpg', '<p>Mẹ Tôi Gánh Đội (Mother Gamer) là bộ phim tâm lý hài với câu chuyện của một người mẹ khi phát hiện cậu con trai của mình có niềm đam mê với môn thể thao điện tử và đang theo đuổi một giải đấu chuyên nghiệp. Thay vì bắt đầu một trận cãi nhau nảy lửa như “chuyện ở mọi nhà” thì người mẹ quyết định lập đội để tranh đấu cùng con trai mình hòng dẹp bỏ ý định theo đuổi con đường trở thành game thủ của con trai.</p>', 'Full', 1, 'single', 'completed', 19, 2020, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Piyada Akaraseni","avatar":""},{"name":"Lapat Ngamchaweng","avatar":""},{"name":"Thanabat Ngamkamolchai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324338);
