INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yen-xich-ha-truyen-tinh-me-lan-nhuoc-tu', 'Yên Xích Hà Truyện: Tình Mê Lan Nhược Tự', 'Yan Chixia Legend Lanruo Temple', 'https://phimimg.com/upload/vod/20240104-1/32b75b0ee1e293a2a0ee3a341db4be45.jpg', 'https://phimimg.com/upload/vod/20240104-1/cb2a0660864ea0e93b57ebd3a548e555.jpg', '<p>Yên Xích Hà dựa vào danh nghĩa thiên hạ đệ nhất pháp sư của cha mình cả ngày chẳng làm gì cả, nhưng lại vô tình lấy đi chuông Trấn Hồn - pháp khí bản mệnh của Thụ Yêu Lão Lão ở Lan Nhược Tự. Một vị pháp sư trẻ tuổi và Thụ Yêu Lão Lão mất đi pháp lực bắt đầu mối quan hệ tình cảm đầy phức tạp, cuối cùng Yên Xích Hà quyết tâm tu luyện và trở thành một đại sư bắt yêu.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lei Nuo Er","avatar":""},{"name":"Yu Tong","avatar":""},{"name":"Norman Chui","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324338);
