INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('max-va-toi', 'Max Và Tôi', 'Max And Me', 'https://phimimg.com/upload/vod/20240104-1/b62828df5af83f621c5bdad1ad6f3282.jpg', 'https://phimimg.com/upload/vod/20240104-1/7d18386bb154f8129e256d67a6fe1da7.jpg', '<p>Max và Tôi - Max and Me xoay quanh mối tình tuổi mới lớn đầy bất ngờ giữa người và một hồn ma. Câu chuyện kể về một chàng trai tuổi teen vụng về phải lòng cô gái bên cạnh. Nhưng sau này, anh phát hiện ra cô đã qua đời một năm trước vì bệnh xơ nang và anh ấy đang yêu... một hồn ma.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lily Bleu Andrew","avatar":""},{"name":"Matthew Erick White","avatar":""},{"name":"Melissa Ponzio","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324338);
