INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('david-attenborough-mot-cuoc-doi-tren-trai-dat', 'David Attenborough: Một Cuộc Đời Trên Trái Đất', 'David Attenborough: A Life On Our Planet', 'https://phimimg.com/upload/vod/20240104-1/6b1b5b99a29a0117db5204336e97a30c.jpg', 'https://phimimg.com/upload/vod/20240104-1/c9bba7a77d8257cdfbb933ea31f2c2d0.jpg', '<p>Phát thanh viên kể lại cuộc đời mình và cả lịch sử tiến hóa của sự sống trên Trái Đất. Qua đó, ông xót xa trước thiệt hại về thiên nhiên và phác họa viễn cảnh tương lai.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Attenborough","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324338);
