INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-vong-dia-oc', 'Ảo Vọng Địa Ốc', 'Rising High', 'https://phimimg.com/upload/vod/20240104-1/f7b6d682b1b4abc56a5fa43b81d7e5a2.jpg', 'https://phimimg.com/upload/vod/20240104-1/d6075fa91b79d247a87d6bda4270b8a4.jpg', '<p>Sẵn sàng làm giàu bằng mọi giá, chàng trai trẻ làm đảo lộn thị trường bất động sản Berlin với người bạn mờ ám, cho đến khi khoảng thời gian vui vẻ đe dọa hủy hoại tất cả.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"David Kross","avatar":""},{"name":"Frederick Lau","avatar":""},{"name":"Janina Uhse","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324338);
