INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ong-hoan-hao-va-co-nang-tam-duoc', 'Quý Ông Hoàn Hảo Và Cô Nàng Tạm Được', 'Perfect And Casual', 'https://phimimg.com/upload/vod/20240116-1/275557ede4ac51b15f0d63cb514c063a.jpg', 'https://phimimg.com/upload/vod/20240116-1/9df6b55da47fc43179bfc9466e78c573.jpg', '<p>Trương Tư Niên sinh ra trong một gia đình y khoa, là người đàn ông hoàn hảo trong mắt mọi người. Vân Thư là học sinh cuối cấp, gặp nhiều xui xẻo nhưng may mắn đã duy trì sự lạc quan trong một thời gian dài. Sau vài lần tình cờ gặp gỡ, cả hai đã đồng ý tiến tới hôn nhân theo hợp đồng. Thế nhưng, nhiều rắc rối nảy sinh khi họ bắt đầu có tình cảm thật với nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ngụy Triết Minh","avatar":""},{"name":"Từ Nhược Hàm","avatar":""},{"name":"Đại Vân Phàm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324338);
