INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-tinh-bao-hy', 'Cửu Tinh Báo Hỷ', 'Ninth Happiness', 'https://phimimg.com/upload/vod/20240103-1/c05c23b7d2b97dff0b249727c93963c6.jpg', 'https://phimimg.com/upload/vod/20240103-1/4daba717bfb5221217342a7006204d83.jpg', '<p>Là một trong những tác phẩm cuối cùng trong sự nghiệp của Trương Quốc Vinh, Ninth happiness mang đến cho khán giả sắc màu vui vẻ và hài hước, khác biệt cho với nhiều thước phim làm nên tên tuổi của anh. Phim ra mắt lần đầu tiên tại thị trường xứ cảng thơm vào năm 1998 và nhanh chóng tạo được tiếng vang. Nếu ai yêu thích phim Hong Kong nói chung và nam tài tử họ Trương nói riêng thì rõ ràng đây là thước phim rất đáng để theo dõi.Cửu Tinh Báo Hỷ thuộc thể loại cổ trang hài hước, do đạo diễn kỳ cựu Cao Chí Sâm đảm nhận vai trò chỉ đạo sản xuất và được biên kịch Đỗ Quốc Uy trực tiếp soạn thảo kịch bản</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Leslie Cheung","avatar":""},{"name":"Wu Qien Lien","avatar":""},{"name":"Jacklyn Wu","avatar":""},{"name":"Raymond Wong","avatar":""},{"name":"Gigi Lai","avatar":""},{"name":"Kenny Bee","avatar":""},{"name":"Jan To Chung","avatar":""},{"name":"Chun-to Chung","avatar":""},{"name":"Chun To Chung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324338);
