INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gauko-co-be-khung-long-phan-2', 'Gauko - Cô Bé Khủng Long (Phần 2)', 'Dino Girl Gauko (Season 2)', 'https://phimimg.com/upload/vod/20240112-1/22f558813dbd1927d71969277e250ade.jpg', 'https://phimimg.com/upload/vod/20240112-1/eda68134165cf8fbe3d1e1f3b4cdca10.jpg', '<p>Naoko và bạn bè tiếp tục những chuyến phiêu lưu lạ thường với người ngoài hành tinh, robot và cô bé khủng long Gauko. Thị trấn bình dị cũng xuất hiện nhiều điều kỳ quặc!</p>', 'Hoàn Tất (19/19)', 19, 'hoathinh', 'completed', 8, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Matsui Naoko","avatar":""},{"name":"Kamiya Hiroshi","avatar":""},{"name":"Ikura Kazue","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Kojiro Chie","avatar":""},{"name":"Mashiba Mari","avatar":""},{"name":"Shiraishi Ryoko","avatar":""},{"name":"Shibata Hidekatsu","avatar":""},{"name":"Miyazawa Tadashi","avatar":""},{"name":"Hattori Sonosuke","avatar":""},{"name":"Karen","avatar":""},{"name":"Toita Yui","avatar":""},{"name":"Konishi Izu","avatar":""},{"name":"Ozaki Eri","avatar":""},{"name":"Nakamura Risa","avatar":""},{"name":"Chujo Tomoyo","avatar":""},{"name":"Hijioka Takuro","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324338);
