INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-me-hai-mat', 'Người Mẹ Hai Mặt', 'Birthmother''s Betrayal', 'https://phimimg.com/upload/vod/20231231-1/af7869ceab54cb4d6a8b9eebbf9ec8a3.jpg', 'https://phimimg.com/upload/vod/20231231-1/ea68625803fc34f2f9b8b5bf5480307a.jpg', '<p>Amy là một bà mẹ đơn thân vốn rất chu đáo và kỹ tính. Nhưng chính sự bảo bọc thái quá đó đã khiến cô con gái nuôi Tara quyết định tìm gặp mẹ ruột. Kỳ lạ thay, mẹ ruột của cô bé một mặt hành xử rất nhã nhặn, mặt khác lại tỏ thái độ bất cần. Liệu Amy và Tara có tìm ra bí mật đằng sau cách hành xử quái lạ của con người bí ẩn này?</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tanya Clarke","avatar":""},{"name":"Aria Pullman","avatar":""},{"name":"Monica Rose Betz","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324338);
