INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sa-hai-chuc-long', 'Sa Hải Chúc Long', 'Guardian Of The Palace', 'https://phimimg.com/upload/vod/20231231-1/6ba89e0a44a63166cbb5068753e417d6.jpg', 'https://phimimg.com/upload/vod/20231231-1/3b3cc77c1035fef8f3fe889b524ffb8c.jpg', '<p>Bộ phim kể về thời kỳ hỗn chiến của quân phiệt, dịch bệnh ở thị trấn Hắc Thủy lan tràn, vì tìm kiếm bảo thạch Kim Nguyệt để chữa trị bệnh dịch mà Thiên Nhai, Vô Niệm, Cửu Nguyệt bước lên con đường tìm truy tìm kho báu. Quân phiệt Phùng Bội Xuyên lập kế theo đuôi với ý đồ chiếm bảo thạch làm của riêng, nhóm người Thiên Nhai đã trải qua thập tử nhất sinh, cuối cùng đánh bại Phùng Bội Xuyên, giành lại bảo thạch và cứu lấy dân chúng</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Bàng Ngỗ Mỗ","avatar":""},{"name":"Mark.DU","avatar":""},{"name":"Du Yi Heng","avatar":""},{"name":"He Yi Rong","avatar":""},{"name":"陳奕名","avatar":""},{"name":"Lu Qi Wei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324338);
