INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ngu', 'Đại Ngư', 'Giant Fish', 'https://phimimg.com/upload/vod/20231231-1/7a40c8d8b98f36508a7e051ef39acf6f.jpg', 'https://phimimg.com/upload/vod/20231231-1/87928bde386cfe40af35249fcceb437f.jpg', '<p>Đại Ngư - Giant Fish kể về anh chàng ngư dân Trần Tử Hào tình cờ gặp cô gái trẻ Tiểu Nghệ, hai người nảy sinh tình cảm với nhau. Song Tiểu Nghệ không phải người, cô là “người Quy Lê” có thể hóa thân thành “cá lớn”. Tử Hào dần nhận ra quả báo khi con người lạm dụng đánh bắt vô tội vạ, anh quyết định cảnh tỉnh ngư dân, ngăn chặn lạm sát.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Fu Meng Ni","avatar":""},{"name":"Mei Yang","avatar":""},{"name":"Tik Lung","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324338);
