INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('twogether-than-tuong-gap-fan', 'Twogether: Thần Tượng Gặp Fan', 'Twogether', 'https://phimimg.com/upload/vod/20240112-1/8df9a42eb367fb891bbc9fa174415f13.jpg', 'https://phimimg.com/upload/vod/20240112-1/c060af64f4c9ddfcbdb4bba4b9adf7f4.jpg', '<p>Cùng tham gia hành trình đáng nhớ xuyên châu Á, các ngôi sao Lee Seung Gi và Lưu Dĩ Hào trở thành đôi bạn thân khi họ kết nối với người hâm mộ và nền văn hóa địa phương.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Seung Gi","avatar":""},{"name":"Lưu Dĩ Hào","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324338);
