INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-mat-na-saber', 'Hiệp Sĩ Mặt Nạ Saber', 'Kamen Rider Saber', 'https://phimimg.com/upload/vod/20240112-1/64019d500ecadf461ad807ffcb558067.jpg', 'https://phimimg.com/upload/vod/20240112-1/d4266456042b82ea03054239038e4c0c.jpg', '<p>Thuở ngàn xưa có một cuốn sách quản lý mọi sự vật hiện tượng xảy ra trên Trái đất này. Những trang sách khắc đầy những truyền thuyết, cổ tích, sinh vật, khoa học và công nghệ. Khi nhân loại tiến hoá và nền văn minh phát triển, những trang sách được cập nhật liên tục. Bảo vệ cuốn sách ấy là các “Thánh Kiếm” và những “Kiếm sĩ được chọn”. Họ duy trì trạng thái cân bằng của thế giới. Tuy nhiên hàng ngàn năm trước, những kẻ muốn đánh cắp cuốn sách ấy đã xuất hiện. Một cuộc chiến dài hơi đã diễn ra, những trang sách bị xé toạc, rải rác khắp nơi trên thế giới. Cuốn sách đã biến mất. Thời gian trôi đến hiện tại, tiểu thuyết gia Kamiyama Touma luôn gặp một giấc mơ kỳ lạ. Trong đó, ở một không gian khác, một kiếm sĩ tranh đấu dữ dội với những quái vật trong cuốn sách, và luôn có một “cô bé bí ẩn” cầu xin giúp đỡ xuất hiện. Mỗi khi mơ thấy nó, Touma cảm thấy như mình quên một cái gì đó “quan trọng”, nhưng không biết đó là gì hay cô bé kia là ai? Giấc mơ hiện ra mà không bao giờ báo trước. Một ngày nọ, hiện tượng bất thường xảy ra. Một phần thành phố mất tích không lời giải thích. Đột nhiên người thân, bạn bè, người yêu biến mất ngay trước mắt nhau. Những phần thành phố mất tích xuất hiện tại một thế giới bí ẩn. “Anh là ai?”, “Đây là đâu?”, “Tôi sẽ trở về như thế nào?”... Những câu hỏi tuyệt vọng vang lên. Touma và cô nàng biên tập Mei Sudou vô tình vướng vào hiện tượng này. Thế giới ấy trông y hệt như giấc mơ của Touma! Ở đó cũng có những quái nhân bí ẩn xâm lược và phá huỷ thành phố! “Chắc chắn tôi sẽ đưa thành phố trở về thế giới của chúng ta!” Đột nhiên, một thanh kiếm rực lửa xuất hiện như thể đáp lại ý chí của Touma. Khoảnh khắc anh nhấc thanh kiếm lên, sức mạnh của hỏa long hòa vào người anh, giúp Kamiyama Touma trở thành “Viêm Kiếm Sĩ”.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 11, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ryo Aoki","avatar":""},{"name":"Rina Chinen","avatar":""},{"name":"Robin Furuya","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324338);
