INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-du-muc', 'Kẻ Du Mục', 'Nomadland', 'https://phimimg.com/upload/vod/20240102-1/feda571596b43932c0e429e737831220.jpg', 'https://phimimg.com/upload/vod/20240102-1/eb1d8328749e1cbf1e47d03a3a572436.jpg', '<p>Sau sự sụp đổ kinh tế của một thị trấn của một công ty ở nông thôn Nevada, dương xỉ (Frances McDORMAND) đóng gói xe van của cô và lên đường khám phá một cuộc sống bên ngoài xã hội thông thường như một món du mục hiện đại. Bộ phim truyện thứ ba từ Giám đốc Chloé Zhao, Nomadland có những người du mục thực sự Linda May, Swankie và Bob Wells với tư cách là những người cố vấn và đồng đội của Fern trong cuộc thám hiểm của mình thông qua cảnh quan rộng lớn của miền Tây Hoa Kỳ.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324338);
