INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-vuong', 'Dã Vương', 'Mountain King / Wild King', 'https://phimimg.com/upload/vod/20240102-1/4dd49384d9b8132f9d3fb80ed0cc9b58.jpg', 'https://phimimg.com/upload/vod/20240102-1/1867ecf7c03ce46089d79ed3c0735976.jpg', '<p>Dã Vương - Mountain King / Wild King kể về người đàn ông Sơn Khôi, một người vô cùng bí ẩn và đã sinh sống nhiều năm tại ngọn núi Thiên Mục, và anh có những người bạn là Tinh Tinh. Một hôm, anh vô tình cứu giúp được một cô bé là Không Nhi thoát khỏi sự truy sát đầy gắt gao bởi Cao Sơn Hùng. Ở ngọn núi này, Không Nhi đã được Sơn Khôi chăm sóc và cho tiếp xúc với nhiều thứ mới mẽ trong thiên nhiên và làm bạn với các tinh tinh. Tuy nhiên, Cao Sơn Hùng vẫn nuôi ý chí tìm kiếm và giết chết Không Nhi, hắn đã cử quân của mình đi tìm kiếm và Sơn Khôi đã nỗ lực bảo vệ cô bé.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lữ Thần Duyệt","avatar":""},{"name":"Lương Kiệt Lý","avatar":""},{"name":"Vương Lợi Đan","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324338);
