INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhu-dung-roi', 'Như Đúng Rồi', 'Like A Boss', 'https://phimimg.com/upload/vod/20240102-1/787f9f5ad10228b90c69d7669abfcacb.jpg', 'https://phimimg.com/upload/vod/20240102-1/081c00edd91751fb49a7e170eddac2fb.jpg', '<p>Đôi bạn thân nhất, Mia và Mel đang sống cuộc đời tuyệt nhất, điều hành công ty mỹ phẩm riêng cho đến khi một bà trùm nham hiểm của công ty làm đẹp âm mưu cướp công ty từ tay họ. Khi kế hoạch ranh ma của cô ả chia cách đôi bạn thân, Mia và Mel học được rằng gắn bó với nhau là cách duy nhất để lật ngược tình thế và giành lại công ty của họ. Ngành làm đẹp sắp trở nên xấu xí.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tiffany Haddish","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Salma Hayek","avatar":""},{"name":"Karan Soni","avatar":""},{"name":"Jacob Latimore","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324338);
