INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-ra-thoi-gian-deu-ghi-nho', 'Hóa Ra Thời Gian Đều Ghi Nhớ', 'Always Have Always Will', 'https://phimimg.com/upload/vod/20240110-1/9577ea4b6b236bd6ba9e5f98f537847f.jpg', 'https://phimimg.com/upload/vod/20240110-1/0d97f716bbd9bf5cbe8d473f2f21e37b.jpg', '<p>Năm đầu tiên trung học, Fang Li, nữ sinh đến từ một thị trấn nhỏ, vô tình trở thành bạn học của Lui Yan- nam sinh học giỏi nhất trường nhưng vô cùng lạnh lùng. Anh chàng chính là ác mộng của Fang Li suốt quãng thời gian trung học. Sau đó, họ lại gặp nhau ở đại học. Lúc này cả hai đã rất khác biệt nhưng giữa hai người vẫn tiếp tục đối đầu nhau và xen lẫn vào đó là những rung động đầu đời.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324338);
