INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bui-dam-hoang-da-tren-bang', 'Bụi Dặm Hoang Dã Trên Băng', 'Wild Bunch On Ice', 'https://phimimg.com/upload/vod/20240102-1/7c39332a6f39dfcd5962d640093cf706.jpg', 'https://phimimg.com/upload/vod/20240102-1/23ab62e594c2d913d26df88237e4819b.jpg', '<p>Chống lại tất cả các tỷ lệ cược, một nhóm nhỏ những đứa trẻ rag-tag bắt đầu cuộc hành trình thành lập một đội khúc côn cầu. Để trở thành một đội, trước tiên họ phải học cách làm việc cùng nhau và tin tưởng vào các khả năng của nhau để giành chiến thắng - cùng nhau, họ đang kiên trì trên lớp băng mỏng.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bryden Belmore","avatar":""},{"name":"Kyle Hazlehurst","avatar":""},{"name":"Nick Armstrong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324338);
