INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-tien-co-toi', 'Đồng Tiền Có Tội', 'Of Greed and Ants', 'https://phimimg.com/upload/vod/20240109-1/cc2407f728c1c3403c1f72c74f276b61.jpg', 'https://phimimg.com/upload/vod/20240109-1/5ee4637ae27ac03bc0779ebbd179bc55.jpg', '<p>Lấy bối cảnh Hồng Kông trong những năm 1970, thời điểm nền kinh tế bắt đầu khởi sắc và đây cũng là lúc thị trường chứng khoán trở thành chiến trường của lòng tham. Nhân vật chính trong phim là Vinh Mộc Đồng (Trương Triệu Huy), sau cái chết của cha mình, Đồng dần trở trở thành một con người đầy tham vọng. Với khao khát làm giàu, Đồng trở về quê hương Hồng Kông từ Thái Lan rồi từng bước thực hiện kế hoạch của mình. Người đầu tiên mà Đồng nhắm tới chính là thiếu gia Đường Hạo Phong (Huỳnh Trí Hiền).</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 11, 2020, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Diêu Tử Linh","avatar":""},{"name":"Tiêu Chính Nam","avatar":""},{"name":"Trương Triệu Huy","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324338);
