INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lanh-chua-cua-sigrdrifa', 'Lãnh Chúa Của Sigrdrifa', 'Senyoku No Sigrdrifa', 'https://phimimg.com/upload/vod/20240109-1/39db462a6ae6f9f2f0fbeb27674e4a58.jpg', 'https://phimimg.com/upload/vod/20240109-1/3816ef5c7548247b0a16b6b075a31097.jpg', '<p>Pillar bất ngờ xuất hiện trên trái đất và trở thành mối đe dọa cho mọi sự sống. Để chống lại những con quái vật như vậy, con người sau khi được Odin tặng cho một tiên nữ chiến tranh Valkyrie và một cỗ máy linh hồn người anh hùng, đã tuyên bố phản công. Bây giờ, đã đến lúc phản công, nhân loại. Ngày của trận chiến quyết định sắp tới - thời điểm của Ragnarok đã gần kề.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324338);
