INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-bim-sua-manh-me', 'Bố Bỉm Sữa Mạnh Mẽ', 'Super Pacifier', 'https://phimimg.com/upload/vod/20240126-1/c57231aecfeeb2e9a47563679249d1db.jpg', 'https://phimimg.com/upload/vod/20240126-1/5cf4d158e7ae900381f6d8c0a90bed28.jpg', '<p>Bố Bỉm Sữa Mạnh Mẽ - Super Pacifier kể về bộ đội đặc chủng Châu Dũng phạm phải sai lầm khiến cả đội hy sinh, từ đó dằn vặt khôn nguôi, suy sụp tinh thần. Ngày nọ, có hai đứa trẻ tìm đến trước cửa, thì ra là con của người đội trưởng đã mất. Châu Dũng bị ép thành bố bỉm sữa tạm thời, mà tên tội phạm ngày trước cũng từng bước tiếp cận Châu Dũng, giơ móng vuốt báo thù về phía bọn trẻ. Châu Dũng bị châm ngòi lửa giận trong lòng, quyết đấu một trận sống còn với tên tội phạm độc ác.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Fu Zi Ming","avatar":""},{"name":"Liu Geng Hong","avatar":""},{"name":"Pei Jia Xin","avatar":""},{"name":"Zhang Li Wei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324338);
