INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-tich-doc-coc-tan-nuong', 'Vân Tịch: Độc Cốc Tân Nương', 'Poison Valley Bride', 'https://phimimg.com/upload/vod/20231231-1/9931bae51172afc1b4f1a3382ab712bf.jpg', 'https://phimimg.com/upload/vod/20231231-1/fc2666283bb12d1b65ece020e2c84b5a.jpg', '<p>Độc phi thiên tài xông vào Dược Quỷ Cốc, giải trừ được cổ độc nghìn năm và so tài với tân nương không bao giờ già! Tần vương Long Phi Dạ và vương phi Hàn Vân Tịch tinh thông cách dùng độc cùng nhau phá giải muôn trùng khó khăn để xông được vào Quỷ Cốc. Ở đây họ đã phát hiện được truyền thuyết về “tân nương cổ độc”. Tân nương cổ độc lợi dụng cổ độc để hút máu người, gìn giữ tuổi xuân, chờ đợi tướng quân trở về cưới mình. Hàn Vân Tịch thi thố khả năng dùng độc với Tân nương cổ độc, bị dồn vào chỗ chết mới tìm được cách phá giải độc thuật, đập tan âm mưu!</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cheng Mu Xuan","avatar":""},{"name":"Yu Xuan Hong Hao","avatar":""},{"name":"Jiang Peng","avatar":""},{"name":"LiuYuZe","avatar":""},{"name":"胡红红","avatar":""},{"name":"Wang ruixue","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324338);
