INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('you-should-have-left', 'You Should Have Left', 'You Should Have Left', 'https://phimimg.com/upload/vod/20231230-1/dada919f612490d0ca4eb9414db178f0.jpg', 'https://phimimg.com/upload/vod/20231230-1/e6b50a8b66bfa926dd9ca552712ed297.jpg', '<p>Nhân viên ngân hàng trung niên căng thẳng và ghen tuông đã kết hôn với nữ diễn viên trẻ Susanna và họ có một cô con gái sáu tuổi, Ella. Theo là một người đàn ông ghét vì anh ta bị buộc tội trì hoãn người vợ đầu tiên, nhưng anh ta bị coi là không có tội. Ra khỏi màu xanh, họ quyết định đi du lịch vào kỳ nghỉ đến một ngôi nhà lớn, cô lập ở vùng nông thôn xứ Wales để giải quyết các vấn đề trong mối quan hệ của họ. Nhưng chẳng mấy chốc họ có những cơn ác mộng và Theo tin rằng điều gì đó xấu xa được giấu trong nhà.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324338);
