INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-am-sat-nguoc-thoi-gian', 'Vụ Ám Sát Ngược Thời Gian', 'Assassin 33 A.D.', 'https://phimimg.com/upload/vod/20231219-1/b1b138e4378acfbad13a4766c0218911.jpg', 'https://phimimg.com/upload/vod/20231219-1/3dfd8ed3af9d41d5caa4b697f1768092.jpg', '<p>Bộ phim Vụ Ám Sát Ngược Thời Gian - Assassin 33 A.D. kể về câu chuyện khi đang nghiên cứu, một nhóm thiên tài trẻ tuổi vô tình, tình cờ phát hiện ra một âm mưu khủng bố bí mật nhằm tạo ra cỗ máy thời gian để quay ngược thời gian và thay đổi lịch sử.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Donny Boaz","avatar":""},{"name":"Ilsa Levine","avatar":""},{"name":"Morgan Roberts","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324338);
