INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-due-than-sam', 'Hậu Duệ Thần Sấm', 'Mortal', 'https://phimimg.com/upload/vod/20231219-1/a6ed7f33ea74db9b7abd875531aac149.jpg', 'https://phimimg.com/upload/vod/20231219-1/6fede24b7410a5d7abf68ad7228a3d53.jpg', '<p>Hậu Duệ Thần Sấm là câu chuyện phiêu lưu giả tưởng về một chàng trai trẻ tên Eric (Nat Wolff), người phát hiện ra mình có sức mạnh giống như “Thần Sấm” trong thần thoại Na Uy cổ đại. Trong khi ẩn náu ở vùng hoang dã phía tây Na Uy, Eric vô tình giết chết một thiếu niên theo cách khó giải thích và không lâu sau cậu bị bắt. Trước khi bị thẩm vấn, anh gặp Christine, một nhà tâm lý học trẻ tuổi đang cố gắng tìm hiểu thực sự đã có điều gì xảy ra. Cô tin vào Eric và cảm thấy đồng cảm với anh. Ngay sau đó, đại sứ quán Mỹ xuất hiện, ông ta muốn dẫn độ Eric, nhưng Eric đã nhanh chóng chạy trốn cùng Christine. Trên đường chạy trốn, theo sau là những nhà chức trách của Na Uy và Mỹ theo đuổi, Eric cuối cùng đã phát hiện ra anh ta thực sự là ai, hay là cái gì đó mà trước nay anh luôn muốn biết….</p>', 'Full', 1, 'single', 'completed', 20, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nat Wolff","avatar":""},{"name":"Priyanka Bose","avatar":""},{"name":"Iben Akerlie","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324338);
