INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-vo-cam', 'Những Kẻ Vô Cảm', 'Don''t Look Back', 'https://phimimg.com/upload/vod/20231227-1/0ea3b71e5940cfd8e0e4d7f0de72886e.jpg', 'https://phimimg.com/upload/vod/20231227-1/6eb48f0e5b44ea637c2fb0f3c0692e68.jpg', '<p>Những Kẻ Vô Cảm - Dont Look Back xoay quanh cô gái trẻ tên Caitlin Kramer. Một ngày, cô và một số người đã vô tình chứng kiến vụ hành hung đến chết một người đàn ông trong công viên mà không dám làm gì. Sau sự việc, những nhân chứng của ngày hôm đó dần dần bị sát hại, Caitlin cũng trải qua những việc kì quái như thể họ đang phải trả giá cho sự vô cảm trước vụ bạo hành.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Kourtney Bell","avatar":""},{"name":"Skyler Hart","avatar":""},{"name":"Will Stout","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324338);
