INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-that-xa', 'Đi Thật Xa', 'Come Away', 'https://phimimg.com/upload/vod/20231219-1/97d69e10febf7e8183f895b7b469ceb8.jpg', 'https://phimimg.com/upload/vod/20231219-1/cdd3bf117ea06ad47409ccf3206890c9.jpg', '<p>Đi Thật Xa được xem là bộ phim tiền truyện của Alice in Wonderland và Peter Pan. Alice và Peter vốn là anh em với nhau và cả hai cũng như bao đứa trẻ bình thường khác trước khi trải qua bi kịch gia đình. Trong phim, Angelina Jolie sẽ thủ vai Rose – người mẹ của Peter và Alice, vô cùng suy sụp trước sự ra đi của người con cả nên buộc lòng hai anh em nhân vật chính phải lựa chọn hoặc là ở lại với gia đình, hoặc tiếp tục tham gia những cuộc phiêu lưu kỳ thú.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Angelina Jolie","avatar":""},{"name":"Gugu Mbatha-Raw","avatar":""},{"name":"Carter Thomas","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324338);
