INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-family', 'The Family', 'The Family', 'https://phimimg.com/upload/vod/20231215-1/8cff7bca998a90041181b15b10257404.jpg', 'https://phimimg.com/upload/vod/20231215-1/e2b53b86529e810fa3412c7fc5e28a6b.jpg', '<p>Cha của Kenji Yamamoto đã chết vì sử dụng một loại thuốc kích thích. Cuộc sống của anh rơi vào tuyệt vọng. Kenji sau đó tham gia một cuộc tội phạm. Ở đó, anh gặp ông chủ của Gang Hiroshi Shibasaki. Hiroshi vươn tới Kenji và họ đã phát triển một mối quan hệ như cha và con trai. Khi thời gian trôi qua, Kenji có gia đình riêng của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324338);
