INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhu-lai-than-chuong', 'Như Lai Thần Chưởng', 'Buddha Palm Technique', 'null', 'https://phimimg.com/upload/vod/20230909-1/7caf502f3f87ee67226a61532fb67cca.jpg', '<p>Jian Bei, một người đòi nợ khiêm tốn phải chăm sóc cho em gái mình đang mắc bệnh nan y. Để trả tiền điều trị cho cô, anh đồng ý trải qua một thủ tục độc đáo mang lại cho anh một khả năng gọi là Buddha Palm. Sức mạnh siêu phàm này giúp anh hoàn thành chuỗi ba thử nghiệm, mỗi thử nghiệm cung cấp một thành phần bí mật có thể chữa khỏi bệnh cho em gái anh. Liệu anh ta có thể hoàn thành những nhiệm vụ này và có được phương pháp chữa trị cho em gái mình?</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Collin Chou","avatar":""},{"name":"Wu Di-wen","avatar":""},{"name":"Tang Fei","avatar":""},{"name":"Wong Yat-fei","avatar":""},{"name":"Zhang Qiang","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324338);
