INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-dai-ngu', 'Hải Đại Ngư', 'Enormous Legendary Fish', 'https://phimimg.com/upload/vod/20231219-1/e4ed006d4901805b12848be8d2902df1.jpg', 'https://phimimg.com/upload/vod/20231219-1/80a8a5200673fddff10f9b0d870b695e.jpg', '<p>Ngư nữ A Ly của thôn Kỳ Ngư bị chọn để hiến tế làm tân nương Hải Thần, theo thuyền hoa ra tới hải đảo. Sau khi thành thân với Hải Thần, A Ly phát hiện phu quân Diệm Hải Thần là một người nửa thú, sau đó lại vào mật thất phát hiện bí mật tân nương trong quan tài băng. A Ly bơ vơ không nơi nương tựa, cả ngày ở bờ biển bầu bạn cùng một con cá vàng Hải Đại Ngư có thể biến thành người, thời gian lâu dần, hai người yêu nhau. Sau khi mang thai bị Diệm giam lại, Hải Đại Ngư cũng không có tung tích. Tỳ nữ Hải Phù Dung chủ động tới phòng giam cứu A Ly đi, không ngờ rằng, thứ chờ nàng là một âm mưu đã bày sẵn từ lâu...</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yuxi","avatar":""},{"name":"Han Dong","avatar":""},{"name":"Jia Zhengyu","avatar":""},{"name":"Xiao Xiangfei","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324338);
