INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-bong-chay', 'Thiếu Niên Bóng Chày', 'Tough Out', 'https://phimimg.com/upload/vod/20231219-1/fac4d7aa91ac8257c0a6d179ef10a4fc.jpg', 'https://phimimg.com/upload/vod/20231219-1/4669e7f63a3b0a87a38ad44045017e2f.jpg', '<p>Một nhóm thiếu niên đến từ các vùng khó khăn khắp đất nước, được chọn vào một câu lạc bộ bóng chày tình thương ở ngoại thành Bắc Kinh lập thành một đội bóng chày đặc biệt, đi theo huấn luyện viên 70 tuổi truyền kì \Sư Gia\ học đánh bóng chày bắt đầu từ con số 0. Mấy tháng sau, họ sẽ đại diện Trung Quốc bay đến nước Mỹ bước lên đấu trường bóng chày thiếu niên quốc tế, nhưng sân vận động và kí túc xá của câu lạc bộ lại đối mặt với nguy cơ bị phá dỡ.....Liệu các thiếu niên có thể vung gậy ngược chiều gió, thử thách vận mệnh của chính mình không?</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"马虎","avatar":""},{"name":"梁正双","avatar":""},{"name":"GuoZhongJian","avatar":""},{"name":"SunLingFeng","avatar":""},{"name":"ZhangJinXin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324338);
