INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-dau-tien-2020', 'Lần Đầu Tiên', 'Leaving Virginia', 'https://phimimg.com/upload/vod/20231214-1/e092d99badb09a17a13e259c67cec419.jpg', 'https://phimimg.com/upload/vod/20231214-1/f45d3c6832e93ae1f1bd83ff178bf5e4.jpg', '<p>Thanh niên nhà giàu đến từ HongKong, A Liệt và trai thẳng Thần Khí là anh em tốt của nhau. Vào ngày sinh nhật năm 18 tuổi của Thần Khí, A Liệt kiên quyết lôi bằng được người anh em này đi “bóc tem”. Thế là hai người tổ chức party rồi hẹn hò với một “đàn chị” thành thục trên mạng. Nhưng đêm “bóc tem” này đã xảy ra sự cố ngoài ý muốn…</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Wu Zhao Xuan","avatar":""},{"name":"Berry Wen i Kuo","avatar":""},{"name":"曾珮瑜","avatar":""},{"name":"GINA","avatar":""},{"name":"Gina","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324338);
