INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-sac-gia-nhan', 'Bản Sắc Gia Nhân', 'True Colours', 'https://phimimg.com/upload/vod/20231219-1/3c67a5e1db6af8894a4369ebd5cdd66c.jpg', 'https://phimimg.com/upload/vod/20231219-1/4529a1ed08ead7e6746b48bf271dd6d7.jpg', '<p>Đôi thanh mai trúc mã quen biết nhiều năm luôn “đối đầu với nhau” Lư Gia Gia và Niên Mạnh Vũ sau khi tốt nghiệp THPT cùng tới Thượng Hải học đại học y. Sau đó, Lư Gia Gia nhận ra tình cảm của mình và quyết định chia tay. Niên Mạnh Vũ bị cuốn hút bởi Tôn Hiểu Tuệ, cô bạn cùng trường có vẻ đẹp truyền thống. Khương Phong, anh bạn khóa trên học hộ của Lư Gia Gia, đem lòng yêu mến Lư Gia Gia. Niên Mạnh Vũ dần dần nhận ra tình cảm của mình dành cho Lư Gia Gia. Sự xuất hiện bất ngờ của bệnh SARS khiến ba người bắt đầu cuộc sống chung….</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wayne","avatar":""},{"name":"Li Ting Ting","avatar":""},{"name":"Ryan","avatar":""},{"name":"hsiaoyu","avatar":""},{"name":"Yu Kai Ning","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324338);
