INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-san-lung', 'Cuộc Săn Lùng', 'The Hunt', 'https://phimimg.com/upload/vod/20240111-1/e5ca11908917ed5ae8377b0a03cdbb05.jpg', 'https://phimimg.com/upload/vod/20240111-1/b54f1ad8e1c2862dfcde77acc17217b2.jpg', '<p>Mười hai người lạ thức dậy trong một khoảng trống. Họ không biết họ đang ở đâu, hoặc cách họ đến đó. Họ không biết họ đã được chọn - vì một mục đích rất cụ thể - cuộc săn lùng.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324338);
