INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ranh-gioi-my-nhan-ngu', 'Ranh Giới Mỹ Nhân Ngư', 'Mermaid Bound', 'https://phimimg.com/upload/vod/20231213-1/ab0c632f41f2836a2dee1bcd3f3f40d5.jpg', 'https://phimimg.com/upload/vod/20231213-1/ac35a487c44879d32032ad877fe913e2.jpg', '<p>Mười năm trước, Liễu Thập An và yêu quái cá Bạch Ngọc đều chết trong một trận quyết chiến. Liễu Mộng Bạch vì nguyên do này mà đến Tầm Giang để điều tra, và tình cờ gặp được yêu quái cá Bạch Thu Luyện. Hai người mến nhau từ lần gặp gỡ đầu tiên. Nhưng nội tình câu chuyện của mười năm trước gây ra cho hai người biết bao gian nan, kết cục của mối tình ngang trái của người và yêu sẽ như thế nào, mời các bạn đón xem.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yuxi","avatar":""},{"name":"ZhuZixiao","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324338);
