INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-thien-bong', 'Đại Thiên Bồng', 'Big Awning', 'https://phimimg.com/upload/vod/20231213-1/13cfa8421f799e2ab3c3f955d6340aa1.jpg', 'https://phimimg.com/upload/vod/20231213-1/4811e24e6077c238eb1e4cbb1fa85edb.jpg', '<p>Tôn Ngộ Không đại náo thiên cung , Thiên Bồng giao chiến nhưng cả 2 không phân thắng bại. Sau khi Tôn Ngộ Không bị áp chế dưới Ngũ Chỉ Sơn, Thiên Bồng Nguyên Soái nhận lệnh xuống hạ giới diệt trừ hậu họa. Ở nhân gian Thiên Bồng gặp Bảo Nhi và tộc trừ yêu của cô ấy. Bọn họ hợp thành một nhóm đi tìm Ngũ Chỉ Sơn . Trải qua những biến đổi bất ngờ, Thiên Bồng thiên biến vạn hóa. Trải qua kiếp nạn để giành lấy tình yêu, cuối cùng trở thành Đại Thiên Bồng</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Ngọc Hiên","avatar":""},{"name":"Ứng Hạo Minh","avatar":""},{"name":"Vương Nghệ Triết","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324338);
