INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-quy', 'Mẹ Quỷ', 'The Wretched', 'https://phimimg.com/upload/vod/20231213-1/50f46f529e66daa40f0e0cb017a4260c.jpg', 'https://phimimg.com/upload/vod/20231213-1/a1b92286cc762b43d1e5f0e98bf0a964.jpg', '<p>The Wretched kể về câu chuyện của Ben – một thiếu niên đang cố gắng vượt qua nỗi mất mát sau cuộc ly dị của bố mẹ mình. Trong kỳ nghỉ hè cùng bố, Ben chạm trán với một mụ phù thủy chuyên bắt cóc trẻ con, hiện đang rình rập gia đình cậu bằng vẻ ngoài của một cô hàng xóm hiền lành. Là người duy nhất nhận ra sự bất thường từ người phụ nữ ấy, làm thế nào để Ben có thể tìm ra cách chống lại quỷ dữ?</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Piper Curda","avatar":""},{"name":"Jamison Jones","avatar":""},{"name":"John-Paul Howard","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324338);
