INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-moc-lan-2020', 'Hoa Mộc Lan', 'HUAMULAN', 'https://phimimg.com/upload/vod/20231212-1/3b37b21e8e5dc37c2312607e25a5024e.jpg', 'https://phimimg.com/upload/vod/20231212-1/221503398f6ff0ae6da1575db8a4923e.jpg', '<p>Hoa Mộc Lan thay cha tòng quân. Cô đã phải vượt qua sự mọi sự bất tiện cùng cơ thể yếu đuối của mình, cố gắng gấp bội và rồi nhận được sự đánh giá cao của tướng quân Lý Nhung. Việc các huynh đệ lần lượt hy sinh trên chiến trường khiến Mộc Lan không thể chấp nhận. Cô mong sớm kết thúc chiến tranh. Khi cuộc chiến đi vào bế tắc, Mộc Lan đã táo bạo, thận trọng và mạnh dạn đưa ra những chiến lược mới giúp đội quân liên tiếp giành chiến thắng. Cuối cùng, Mộc Lan và Lý Nhung đã cùng phối hợp với nhau đánh tan quân thù.</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Chu Xuan","avatar":""},{"name":"CaesaR","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324338);
