INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tra-gia-cho-tinh-yeu', 'Trả Giá Cho Tình Yêu', 'Love Revenge', 'https://phimimg.com/upload/vod/20231219-1/c7c5483fe1d289a21bbb847301f09fd1.jpg', 'https://phimimg.com/upload/vod/20231219-1/a4149ed0e6f5dbaeed2c420def309303.jpg', '<p>Bộ phim Trả Giá Cho Tình Yêu (Love Revenge) nói về Arisa, một y tá xinh đẹp. Cô đã từng nghĩ cuộc đời cô may mắn như nàng Lọ Lem khi kết hôn với người đàn ông ấm áp như Aek Phum. Thế nhưng, vào ngày kỷ niệm 10 năm bên nhau, Aek Phum đã bỏ Arisa để chạy theo Kesirin giàu có và quyền lực. Sau đó, Arisa quen chàng trai trẻ Pongkul và dần tìm lại được niềm vui sau nhiều đau khổ, cho đến khi cô phát hiện mình mang thai.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 11, 2020, 'Lồng Tiếng', 'HD', 'Thái Lan', 0, '[{"name":"Nune Woranuch Bhirombhakdi","avatar":""},{"name":"Beam Kawee Tanjararak","avatar":""},{"name":"Joss Way-ar Sangngern","avatar":""},{"name":"Pat Napapa Thantrakul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324338);
