INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-mo', 'Kẻ Săn Mộ', 'Collectors', 'https://phimimg.com/upload/vod/20231212-1/8cadb3dfdbdc1d94bbd62f834beb213d.jpg', 'https://phimimg.com/upload/vod/20231212-1/8b8b4024a6d07c96eb0a96fdaab248de.jpg', '<p>Kẻ Săn Mộ - Collectors xoay quanh một nhóm đào mộ nổi tiếng trong giới. Kang Dong-Goo (Lee Je-Hoon) là một kẻ trộm mộ chuyên nghiệp, Johns (Jo Woo-Jin) là người chuyên vẽ tranh trên tường mộ cổ, còn Bandari (Lim Won-Hee) lại có biệt danh đào sĩ vì chuyên vạch ra các kế hoạch táo bạo nhằm đột nhập vào các đường mộ cổ trộm châu báu. Trong khi đó, Yoon (Shin Hye-Sun) là chuyên gia về nghệ thuật cổ đại. Cô đã đưa ra thỏa thuận hấp dẫn, nhưng ẩn chứa nhiều rủi ro cho Kang Dong-Goo. Và kế hoạch săn báu vật trong mộ được tiến hành.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Jo Woo-Jin","avatar":""},{"name":"Lee Je Hoon","avatar":""},{"name":"Im Won Hee","avatar":""},{"name":"Shin Hae Sun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324338);
