INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('train-to-busan-2-ban-dao-peninsula', 'Train To Busan 2: Bán Đảo Peninsula', 'Peninsula', 'https://phimimg.com/upload/vod/20231211-1/7b97d177d9b15eca49d8a833b8731e81.jpg', 'https://phimimg.com/upload/vod/20231211-1/c439eb73671827335abbe3c3182315a2.jpg', '<p>Ở phần trước, sau khi chuyến tàu đi tới Busan, virut zombie đã bùng nổ khắp nơi trong cả nước, Hàn Quốc biến thành vùng đất chết. Số ít những người sống sót cùng bước lên con thuyền cứu nạn cuối cùng. Quân nhân đã giải ngũ Jung Suk (Kang Dong Won thủ vai) và người nhà vừa lên thuyền đã phát hiện có zombie ẩn nấp. May mắn được Hồng Kông thu nhận, bắt đầu cuộc sống mới. Nhưng Jung Suk không chống lại được sự hấp dẫn của tiền tài, anh gia nhập một chuyến đi về nước để lấy một số tiền lớn. Sau khi quay lại Hàn Quốc, không ngờ lại phát hiện một nhóm người sống sót vẫn đang tranh đấu tìm đường sống, Jung Suk quyết định dẫn mọi ngươi chạy trốn. Cuối cùng, liệu họ có thành công rời khỏi bán đảo đầy zombie?</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kang Dong Won","avatar":""},{"name":"Lee Jung Hyon","avatar":""},{"name":"Quan Hai Xiao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324338);
