INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-thuoc-tri', 'Có Thuốc Trị', 'Are You OK', 'https://phimimg.com/upload/vod/20240104-1/c2d8229796a4882a6690c57cd07614e5.jpg', 'https://phimimg.com/upload/vod/20240104-1/abd0af1fbbb65c16d94784b1e40f2c2f.jpg', '<p>Triều đình công khai mời chào nhân sỹ bên ngoài (dị khách) rồi căn cứ vào tài năng của họ để sắp xếp những công việc riêng nhằm tạo ra một thế giới mới, xóa bỏ những lạc hậu, tiến đến một xã hội văn minh hơn. Tả Vân Khởi thân là thiếu chủ của bàng môn vì muốn cứu phụ thân đã cải trang thành dị khách để trà trộn vào triều đình nhưng lại bị một chuyên gia giám định nhìn thấu được thân phận. Hai người đấu trí đấu dũng, tạo ra những tình cảnh dở khóc dở cười, cuối cùng cũng có thể bắt tay hợp tác với nhau. Trong khi hai người kết hợp ngăn chặn một âm mưu khủng khiếp, họ phát hiện ra có các dị khách âm thầm thành lập một liên minh muốn lật đổ những người nắm quyền, thành lập một xã hội hòa bình mới. Tả Vân Khởi và nhóm người của anh ta buộc phải tham gia vào trận chiến.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2020, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324338);
