INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-dai-mac', 'Giang Hồ Đại Mạc', 'Desert Legend', 'https://phimimg.com/upload/vod/20231211-1/ed7f779bd3165900c95ebf5833a95722.jpg', 'https://phimimg.com/upload/vod/20231211-1/74d6d5fdcf1a995280f9eead1360e833.jpg', '<p>Giang Hồ Đại Mạc - Desert Legend kể về một thợ rèn nhỏ có một ước mơ giang hồ Lữ Tam Tư. Hắn gặp gỡ hiệp sĩ Bách Lý Vô Ưu, giúp hiệp sĩ áp giải Hà Thanh Anh tay sai của Tây Xưởng, nhưng Hà Thanh Anh nói với hắn cô là nghĩa sĩ bị Tây Xưởng hãm hại. Bách Lý Vô Ưu mới là tên chó săn phản bội nghĩa sĩ! Điều khả nghi ngày càng nhiều, ai nói đúng ai nói sai thì Lữ Tam Tư cần phải phán đoán. Lữ Tam Tư chưa bao giờ bước vào giang hồ, phát hiện ra rằng giang hồ này hoàn toàn khác với giang hồ mình tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lee Li-Chun","avatar":""},{"name":"Sun Qi Jun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324338);
