INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-song-song', 'Thế Giới Song Song', 'Double', 'https://phimimg.com/upload/vod/20231211-1/4cef8bc7d660637f933eba2a9e8e0f04.jpg', 'https://phimimg.com/upload/vod/20231211-1/ebc8ca9239cb0a45dd204c3eaeb77824.jpg', '<p>Thế Giới Song Song - Double là một bộ phim giả tưởng kể về Vương Duy, một chủ sở hữu tư nhân, cha của anh ấy là Vương Đức Trí, người tham gia đội thám hiểm khoa học đã mất tích nhiều năm, đột nhiên xuất hiện không hề già đi. Tuy nhiên, trí nhớ của anh ta bị rối loạn như thể anh ta đến từ một không gian khác. Anh kể cho Vương Duy về những gì đã xảy ra trong đội thám hiểm khoa học. Để tồn tại, họ đã phải chiến đấu.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ding Xihe","avatar":""},{"name":"Guo Xiaoming","avatar":""},{"name":"Li Kai","avatar":""},{"name":"Liu Di","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324338);
