INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-thien-sat-co-loan', 'Địch Nhân Kiệt: Thiên Sát Cô Loan', 'Detective Dee Solitary Skies Killer', 'https://phimimg.com/upload/vod/20231211-1/b4a98eca19a795512bb25fd60f366456.jpg', 'https://phimimg.com/upload/vod/20231211-1/44873391327c362afeb426b1d757c4d8.jpg', '<p>Địch Nhân Kiệt: Thiên Sát Cô Loan - Detective Dee Solitary Skies Killer kể về vụ án cô dâu đã giết 4 người liên tiếp trong buồng tân hôn, lao ra khỏi phòng và hét lên “đó không phải là tôi”, sau đó tự tử. Các khách mời đều đồng loạt chĩa mũi nhọn vào một thiếu nữ với dáng người yếu ớt, cho rằng cô mới là kẻ sát nhân thực sự ở hậu trường. Ngay cả bản thân cô gái cũng thừa nhận tội lỗi của mình. Liệu sự thật có được làm sáng tỏ? Khi cuộc điều tra tiếp tục, một kế hoạch đẫm máu kỳ quái dần dần lộ diện.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhao Rui Han","avatar":""},{"name":"Du Yi-Heng","avatar":""},{"name":"Shu Yang","avatar":""},{"name":"Zhao Wen Zhuo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324338);
