INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xong-len-phia-truoc', 'Xông Lên Phía Trước', 'Fast Forward', 'https://phimimg.com/upload/vod/20231211-1/ea2dc52f1092895c1a907bf886d06c11.jpg', 'https://phimimg.com/upload/vod/20231211-1/5537c8e4eaa64c6d672a6b7ada1397ec.jpg', '<p>Gao Shang, một tài xế xe cứu thương bình thường với ước mơ đua xe từ khi còn nhỏ, đã lái chiếc xe của chính mình và vô tình vướng vào một cuộc tranh chấp đua xe, điều này đã thay đổi hoàn toàn cuộc đời anh. Đứng trước ngã ba đường đời, chọn cuộc sống ổn định hay ước mơ? Gao Shang đang mất mát nhiều thứ, nhưng những gì Mengmeng nói trước khi chết khiến anh nhận ra tầm quan trọng của việc theo đuổi ước mơ. Và chính Mengmeng là động lực để anh ấy tiếp tục thực hiện ước mơ của mình. Cuộc sống thật ngắn ngủi. Chỉ có sống thật với chính mình và dũng cảm tiến về phía trước, bạn mới có thể sống trọn vẹn cuộc sống của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jia Bing","avatar":""},{"name":"Shi Shi","avatar":""},{"name":"Zhang Rui Han","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324338);
