INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-tay-hai-sung', 'Hai Tay Hai Súng', 'Guns Akimbo', 'https://phimimg.com/upload/vod/20231211-1/6589a1035be70e6b539fee1a32315f1f.jpg', 'https://phimimg.com/upload/vod/20231211-1/3415ff71ee5cb3469f3b2ba26fda5d63.jpg', '<p>Một băng đảng tổ chức cuộc thi sống còn, nơi những người xa lạ phải chiến đấu đến chết cho người xem trực tuyến. Miles (Daniel Radcliffe) một anh chàng bình thường đột nhiên thấy mình bị buộc phải chiến đấu với Nix (Samara Weaving) được vũ trang mạnh mẽ để cứu bạn gái cũ bị bắt cóc. Không chỉ vậy, hai khẩu súng còn bị khóa chặt vào tay của Miles, có súng như không, 2 khẩu súng gây cho Miles nhiều tình thế dở khóc dở cười.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Samara Weaving","avatar":""},{"name":"Natasha Liu Bordizzo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324338);
