INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lai-them-mot-giang-sinh', 'Lại Thêm Một Giáng Sinh', 'Just Another Christmas', 'https://phimimg.com/upload/vod/20231211-1/bb7f1f68e5304fad633fb3a0d9fc7ec7.jpg', 'https://phimimg.com/upload/vod/20231211-1/c11d5c476cd5b650ba52580e35b7f763.jpg', '<p>Mắc kẹt trong vòng lặp ngày Giáng Sinh bất tận, người đàn ông yêu gia đình, ghét kỳ nghỉ bắt đầu học được những bài học quý giá về điều quan trọng trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Leandro Hassum","avatar":""},{"name":"Elisa Pinheiro","avatar":""},{"name":"Danielle Winits","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324338);
