INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('son-trai-tieu-manh-chu', 'Sơn Trại Tiểu Manh Chủ', 'Fake Princess', 'https://phimimg.com/upload/vod/20231208-1/e0df72dd45985d2448fbc97b2edc0f3a.jpg', 'https://phimimg.com/upload/vod/20231208-1/34a3d52a7fe4c3d902caf0f15185ecaf.jpg', '<p>Cải biên dựa trên tiểu thuyết cùng tên của tác giả Thủy Sanh kí hợp đồng với website Trung Quốc, kể về câu chuyện Thường Lạc gả thay vào cung, cùng Lý Triệt an ủi đỡ đần lẫn nhau, Lý Triệt trông có vẻ thâm trầm ít nói, lạnh lùng ngạo mạn, nhưng tình cảm lại rất chung thủy. Chỉ si mê một mình Thường Lạc, cuối cùng nắm chặt lấy tay nhau.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 13, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Eleanor Lee","avatar":""},{"name":"Yiqin Zhao","avatar":""},{"name":"金澤","avatar":""},{"name":"Sun xue ning","avatar":""},{"name":"Chen Si Yu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324338);
