INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kairos', 'Kairos', 'Kairos', 'https://phimimg.com/upload/vod/20231203-1/61a2319112f3d07173e996af1998fc47.jpg', 'https://phimimg.com/upload/vod/20231203-1/ea7f77e1616fb7ca0bcedf708e736873.jpg', '<p>Kim Seo-Jin (Shin Sung-Rok) là một người đàn ông thành công trong cuộc sống của mình. Nhờ những nỗ lực cá nhận, anh ấy trở thành giám đốc điều hành trẻ nhất tại công ty của mình. Cuộc sống của anh thật hoàn hảo, với cô vợ chơi vĩ cầm xinh đẹp Kang Hyun-Chae (Nam Gyu-Ri) và một cô con gái. Cuộc sống tuyệt vời của anh dừng lại khi cô con gái nhỏ bị bắt cóc. Anh rơi sâu vào tuyệt vọng. Để thay đổi quá khứ, khi con gái bị bắt cóc, anh đã quay về quá khứ từ một tháng trước để liên lạc với Han Ae-Ri (Lee Se-Young).</p>', 'Hoàn tất (32/32)', 32, 'series', 'completed', 9, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Shin Sung Rok","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324338);
