INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dong-can-khon-niet-ban-than-thach', 'Vũ Động Càn Khôn Niết Bàn Thần Thạch', 'Nirvana Rebirth Of Chinchilla', 'https://phimimg.com/upload/vod/20231227-1/161a98a15587139b356a6842b3f531bb.jpg', 'https://phimimg.com/upload/vod/20231227-1/3d64ec67643c460d55a3967cb1b71754.jpg', '<p>Vũ Động Càn Khôn Niết Bàn Thần Thạch - Nirvana Rebirth Of Chinchilla kể về câu chuyện của người anh hùng trẻ tuổi Lin Dong, không hài lòng với việc cha con Lôi bắt nạt xúc phạm mình nên đã dũng cảm lao đến Hội nghị săn bắn thị trấn Qingyang. Lin Dong tình cờ lấy được chiếc bùa hộ mệnh bí ẩn của tổ tiên nên anh đã trở thành cao thủ võ thuật chỉ trong một đêm, trong khi giết chết Bộ tứ tại đại hội săn bắn, anh cũng bị các thế lực khác bí mật nhắm tới do bị rò rỉ thông tin bùa của tổ tiên.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Gao Wen Feng","avatar":""},{"name":"Wang Mo Xi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324339);
