INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('words-on-bathroom-walls', 'Words On Bathroom Walls', 'Words On Bathroom Walls', 'https://phimimg.com/upload/vod/20231209-1/c0f1c6a2d6d280ca2c8b2506bbe025d8.jpg', 'https://phimimg.com/upload/vod/20231209-1/83e2621e701e7ccbd675b2a12445a229.jpg', '<p>Câu chuyện về Adam dí dỏm và Introspective (Charlie Plummer), người dường như là người trẻ tuổi điển hình của bạn - một chút khó chịu với các hormone hoành hành và hào hứng về một tương lai theo đuổi ước mơ trở thành một đầu bếp. Bị trục xuất nửa chừng trong năm cuối cấp sau một sự cố trong lớp hóa học, Adam được chẩn đoán mắc bệnh tâm thần. Được gửi đến một học viện Công giáo để hoàn thành nhiệm kỳ của mình, Adam có rất ít hy vọng phù hợp và chỉ muốn giữ bí mật về bệnh tật cho đến khi anh ta có thể đăng ký vào trường ẩm thực. Nhưng khi anh gặp Maya thông minh thẳng thắn và mạnh mẽ (Taylor Russell), có một mối liên hệ lành mạnh và thoải mái ngay lập tức. Khi sự lãng mạn của họ sâu sắc, cô truyền cảm hứng cho anh ta để mở lòng và không được xác định bởi tình trạng của anh ta. Bây giờ, với tình yêu và sự hỗ trợ của bạn gái và gia đình của mình, Adam hy vọng lần đầu tiên anh ta có thể nhìn thấy ánh sáng và chiến thắng những thách thức nằm ở phía trước.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324339);
