INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-san-dem', 'Quái Vật Săn Đêm', 'Sputnik', 'https://phimimg.com/upload/vod/20231209-1/00b7b144eb6ea89b15af0083ef6f116b.jpg', 'https://phimimg.com/upload/vod/20231209-1/9f4dde1230bc81bcc5c979af5546ca74.jpg', '<p>Quái Vật Săn Đêm người sống sót đơn độc trong một sự cố tàu vũ trụ bí ẩn đã không trở về nhà một mình - ẩn trong cơ thể anh ta là một sinh vật nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Oksana Akinshina","avatar":""},{"name":"Fedor Bondarchuk","avatar":""},{"name":"Pyotr Fyodorov","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324339);
