INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-thien-nu-u-hon', 'Tân Thiện Nữ U Hồn', 'The Enchanting Phantom', 'https://phimimg.com/upload/vod/20231209-1/51821a160cb02287619a85d36cabc059.jpg', 'https://phimimg.com/upload/vod/20231209-1/d3618ba42a731647f74e2d38ab9298ad.jpg', '<p>Tân thiện nữ u hồn : Tình nhân gian bản 2020 do Trần Tinh Húc và Lý Khải Hinh đóng vai chính, đạo diễn của bộ phim là Lâm Trân Chiêu. Nội dung chính của phim kể về Ninh Thái Thần - Người chuyên đi thu hồi nợ tại các cửa tiệm, tuy là người yếu bóng vía nhưng bản chất của anh lại rất thật thà, chất phác. Một lần nọ khi đang đi thu nợ, anh chợt nhận ra mình không còn tiền và phải ngủ lại tại ngôi chùa Lan Nhược Tự - nơi nổi tiếng với nhiều vụ án mạng do ma quỷ gây ra.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Từ Thiếu Cường","avatar":""},{"name":"Nguyên Hoa","avatar":""},{"name":"Trần Tinh Húc","avatar":""},{"name":"Lý Khải Hinh","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324339);
