INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-ha-long-xa', 'Cửu Hà Long Xà', 'Prophesy Of Fire', 'https://phimimg.com/upload/vod/20231209-1/0c0714b1613ea1dca91a44ede4c06612.jpg', 'https://phimimg.com/upload/vod/20231209-1/f6404260e1fa59146b131bcf0fd65da9.jpg', '<p>Lời nguyền về Hỏa Thần lan rộng trong thành khiến lòng dân hoang mang. Thần trộm Tiền Bất Nhị, đạo tặc Trương Lập Tam và y tá Tô Diệp bị ép cuốn vào trong, bắt đầu tìm kiếm chân tướng sự việc. Trong quá trình tìm hiểu họ bị Ma Cổ Đạo truy giết, bất ngờ tìm được gợi ý để cứu người dân ở chỗ tiên cá. Họ phải chạy đua với thời gian, vén màn bí ẩn về tượng Hỏa Thần trong truyền thuyết…</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Bàng Ngỗ Mỗ","avatar":""},{"name":"Zheng Tuo Jiang","avatar":""},{"name":"Dai An Na","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324339);
