INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('banh-quy-thu-ganh-xiec-phep-thuat', 'Bánh Quy Thú: Gánh Xiếc Phép Thuật', 'Animal Crackers', 'https://phimimg.com/upload/vod/20231209-1/6764ca239e3d7386eb0d96638263836b.jpg', 'https://phimimg.com/upload/vod/20231209-1/d7ba9a8173d44bdae340381db41c4ca9.jpg', '<p>Bánh quy hình động vật đầy mê hoặc biến Owen thành bất kỳ dạng hình nào anh ăn! Nhưng để cứu gánh xiếc của gia đình, anh sẽ phải giữ chúng tránh xa người chú độc ác.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emily Blunt","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Ian McKellen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324339);
