INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ao-thuat-su', 'Đại Ảo Thuật Sư', 'The Great Illusionist', 'https://phimimg.com/upload/vod/20231209-1/8d3c234434a643987bbe25b9ac1f5baf.jpg', 'https://phimimg.com/upload/vod/20231209-1/620eefd532a08d54f9733492c6adf5d3.jpg', '<p>Đại Ảo Thuật Sư - The Great Illusionist kể về phép thuật truyền thống của Trung Quốc còn được gọi là kỹ thuật ảo ảnh. Trong thời kỳ Trung Hoa Dân Quốc, các vụ giết người hàng loạt đã diễn ra ở thành phố Bắc Hải. Luo Bin, một nhà ảo thuật, đã hỗ trợ Long Cong, một cảnh sát, điều tra các vụ án. Hai người này nhận thấy rằng hầu hết những người chết đều là ảo thuật gia sống ẩn danh và Michiko đã giết họ bằng kỹ thuật ảo ảnh đen tối đã bị thất truyền từ lâu.</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Guan Xiangyun","avatar":""},{"name":"Mengyan Liao","avatar":""},{"name":"Silvio Sun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324339);
