INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-dich-cua-toi-la-chinh-minh', 'Tình Địch Của Tôi Là Chính Mình', 'My Love Rival Is Myself', 'https://phimimg.com/upload/vod/20231207-1/c9213d3757e2174392a559295c330bdd.jpg', 'https://phimimg.com/upload/vod/20231207-1/7b226ae7b94d84ad0849b6d440eb1dbf.jpg', '<p>Bộ phim kể về Giang Nam Tuyết, sau một sự cố bất ngờ, cô bị hoán đổi thân xác với một người đàn ông khác, từ đó cuộc đời cô cũng rẽ sang một bước ngoặt hoàn toàn mới. Trong thân xác của một người đàn ông, cô đã gặp được tình yêu đời mình, liệu sau cùng cô có trở về được hình hài thật sự và tìm được hạnh phúc?</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 18, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ngô Hàn Vũ","avatar":""},{"name":"Tô Kỳ An","avatar":""},{"name":"Đàm Nghiêu Quân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324339);
