INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-than-chien-binh-1984', 'Nữ Thần Chiến Binh 1984', 'Wonder Woman 1984', 'https://phimimg.com/upload/vod/20231208-1/d19d277cd0cc49f15f069fba8b9afd83.jpg', 'https://phimimg.com/upload/vod/20231208-1/e571ef3df59f545959065d1c3b4bb42f.jpg', '<p>Năm 1984, sau khi cứu thế giới ở Wonder Woman (2017), Chiến binh Amazon bất tử, Công chúa Diana của themyscira, thấy mình đang cố gắng ở dưới radar, làm việc như một nhà khảo cổ học tại Bảo tàng Smithsonian. Với ký ức của phi công dũng cảm, Thuyền trưởng Steve Trevor, khắc trên tâm trí của cô, Diana Prince bị lôi kéo vào một âm mưu độc ác của tỷ lệ toàn cầu khi một viên đá quý citrine vàng trong suốt, vàng trong suốt, đánh bắt mắt của doanh nhân đói quyền lực, Maxwell Lord . Bây giờ, như một người bạn cũ thân yêu từ quá khứ sẽ vào bức tranh, và Barbara Minerva, đồng nghiệp của nhà bán lẻ không an toàn của Diana đã mang đến cho mong muốn, bất ngờ, lừa dối, tham lam và lời hứa sai lầm của Catapult Maxwell vào ánh đèn sân khấu. Ngày càng nhiều, các sự kiện cataclysmic đẩy thế giới đến bờ vực, và Diana dễ bị tổn thương về mặt cảm xúc phải giải quyết một tình huống khó xử độc ác. Người phụ nữ khổng lồ mạnh mẽ có thể cứu loài người một lần nữa?</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324339);
