INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tai-truong-trung-hoc', 'Thần Tại Trường Trung Học', 'The God of High School', 'https://phimimg.com/upload/vod/20231207-1/a9c8122245071974d08c70014193529a.jpg', 'https://phimimg.com/upload/vod/20231207-1/ce181b38edb7034bccf8ad2ede765856.jpg', '<p>Giải đấu Võ thuật mang tên The God of High School nơi tập trung các học sinh cấp ba. Người chiến thắng sẽ đạt được bất cứ mong muốn nào. Jin Mori, cậu học sinh trung học tự xưng là người mạnh nhất, được mời đến đó, cậu gặp gỡ những người cùng tham gia là Daewi Han và Mira Yoo. Cuộc chiến sống còn với những kẻ mạnh ở khắp các nơi bắt đầu.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324339);
