INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-phai-nang-meo-tinh', 'Yêu Phải Nàng Meo Tinh', 'Falling in Love With Cat', 'https://phimimg.com/upload/vod/20231207-1/b1e210d7f77dcc73ccf2b15e8d154343.jpg', 'https://phimimg.com/upload/vod/20231207-1/bb58ff57fa2cc8d86ff3dbc4e0bb5a5f.jpg', '<p>Bộ phim nói về Tống Tử, cô gái đến từ hành tinh mèo, đã xảy ra một câu chuyện tình yêu vừa nguy hiểm vừa lãng mạn ấm áp khi tìm kiếm ân nhân cứu mạng. Tống Tử tình cờ gặp ông chủ tiệm thú cưng, sau khi xảy ra một loạt sự kiện, hai người cuối cùng cũng bày tỏ lòng mình, lựa chọn nắm tay để ở bên nhau. Thế nhưng trở ngại lớn nhất vẫn còn ở phía sau...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vicky","avatar":""},{"name":"kevin Chu","avatar":""},{"name":"You Xian Chao","avatar":""},{"name":"Chen Shi Qi","avatar":""},{"name":"Mirrre","avatar":""},{"name":"Zhao Zhen Yu","avatar":""},{"name":"Wang Gang Gang","avatar":""},{"name":"Ziyou Li","avatar":""},{"name":"Martin","avatar":""},{"name":"Le Jing","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324339);
