INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-sieu-sao', 'Cuộc Chiến Siêu Sao', 'Theptida Khon Nok', 'https://phimimg.com/upload/vod/20231207-1/5f8ab63543864cb26c86d359856b777f.jpg', 'https://phimimg.com/upload/vod/20231207-1/10b1e8441abca2bc3e57046fdcfe6aa3.jpg', '<p>Bố qua đời, Plaiaor được mẹ nuôi dạy trở thành nghệ sĩ nhạc Luk Thung để trả thù Burapha, kẻ tình nghi trong vụ tai nạn của bố cô. Porkaew tài giỏi, tốt nghiệp từ nước ngoài về, dù có chất giọng hiếm có và đam mê nhạc Luk Thung nhưng phải chấp nhận bỏ lại đam mê để về điều hành công ty của bố. Và cuộc chiến không khoan nhượng giữa hai truyền nhân trong truyền thuyết của làng âm nhạc Luk Thung lại bắt đầu.</p>', 'Hoàn Tất (46/46)', 46, 'series', 'completed', 11, 2020, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"June Cholruedee Amornlak","avatar":""},{"name":"Baitoey R-Siam","avatar":""},{"name":"Iang Sittha Sapanuchart","avatar":""},{"name":"Kit Krit Amornchailerk","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324339);
