INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-toc', 'Quý Tộc', 'Noblesse', 'https://phimimg.com/upload/vod/20231207-1/bf89aec344c2e064163cfbf54b9592cf.jpg', 'https://phimimg.com/upload/vod/20231207-1/8a1df5367511dcaa2ca4e0a81c3ecaf5.jpg', '<p>Được đánh thức từ sau giấc ngủ 820 năm, Rigel là một vị thần hộ mệnh cao quý. Người quản gia trung thành Frankenstein, để bảo vệ Rigel đã đưa cậu vào một trường trung học về nghệ thuật do ông tự kinh doanh. Sau khi trải qua cuộc sống yên bình một thời gian, tổ chức kì bí Union dần trở thành mối đe dọa. Để bảo vệ mọi người, Rigel sẽ phải sử dụng sức mạnh tuyệt đối của mình ...</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 7, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324339);
