INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-dep-doi-tra', 'Sắc Đẹp Dối Trá', 'The Drama Queen', 'https://phimimg.com/upload/vod/20231210-1/4ea6db2c377245edd88992af5e611108.jpg', 'https://phimimg.com/upload/vod/20231210-1/25a9b85ef01c7aa83cdc506c6bd7ab02.jpg', '<p>Dương là một chàng cascadeur nhưng lại mang trong mình khát khao trở thành phụ nữ. Tình cờ chứng kiến một vụ giết người, Dương phải thay đổi nhân dạng để lẩn trốn. Và thế là... ước mơ trở thành sự thật. Không may, sau cuộc phẫu thuật chuyển giới, cha Dương lâm bệnh nặng, cô phải bất đắc dĩ tham gia thi hoa hậu để có tiền trả viện phí cho ông. Từ đó, rất nhiều tình huống nguy hiểm và bi hài xảy ra.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Hương Giang","avatar":""},{"name":"Puka","avatar":""},{"name":"Phát La","avatar":""},{"name":"Tuấn Trần","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324339);
