INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muc-tieu-so-mot', 'Mục Tiêu Số Một', 'Target Number One', 'https://phimimg.com/upload/vod/20231208-1/0954980af97560a9f47cbb9109fab2d2.jpg', 'https://phimimg.com/upload/vod/20231208-1/beedb6a791eb83b18f8917095e2daabb.jpg', '<p>Vị phóng viên quyết tâm cố gắng giải thoát người đàn ông bị giam trong nhà tù Thái Lan vì tội mà anh bị ép nhận – bởi những thủ phạm không ngờ tới. Dựa trên chuyện thật.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Antoine Olivier Pilon","avatar":""},{"name":"Josh Hartnett","avatar":""},{"name":"Stephen McHattie","avatar":""},{"name":"Don McKellar","avatar":""},{"name":"J.C. MacKenzie","avatar":""},{"name":"Amanda Crew","avatar":""},{"name":"Jim Gaffigan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324339);
