INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rocks', 'Rocks', 'Rocks', 'https://phimimg.com/upload/vod/20231208-1/54976b1300985d757a5ea93e96330de2.jpg', 'https://phimimg.com/upload/vod/20231208-1/a5c5372dcaa326cf4c6f58609fd9f907.jpg', '<p>Shola (Bukky Bakray), hoặc đá, như cô ấy đã biết, sống trong một hội đồng London căn hộ với em trai Emmanuel (dangelou Osei Kissiedu) và mẹ đơn thân của họ. Mẹ đang bận rộn và căng thẳng, để lại những tảng đá để dành tất cả thời gian rảnh của mình với những người bạn học. Một ngày nọ, cô trở về nhà để tìm cuộc sống của mình thay đổi triệt để: cô bất ngờ mình với một đứa trẻ để chăm sóc. Gavron có thể dễ dàng có thể lái những tảng đá thành sự xác định sai lầm, nhưng thay vào đó là một bức chân dung đáng kinh ngạc của khả năng phục hồi. Đá là Mercurial, bốc đồng và nhạy cảm sâu sắc - không phải là bất thường đối với tuổi, đôi khi cô ấy đưa ra quyết định tuyệt vọng, vì những gì nhìn vào cô ấy như lý do tốt. Khi người bạn thân nhất của cô Sumaya (Kosar Ali) cố gắng giúp đỡ, những tảng đá không biết cách chấp nhận nó, bị mù bởi hộ gia đình hai cha mẹ của Sumaya và sự thoải mái tương đối.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324339);
