INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chim-ung-phan-2', 'Chim Ưng (Phần 2)', 'Condor (Season 2)', 'https://phimimg.com/upload/vod/20231207-1/18ad86dea424202ff4dea6bd81f8fa26.jpg', 'https://phimimg.com/upload/vod/20231207-1/21c00a01c375df3d03cd36f1a6b7c0bd.jpg', '<p>Nhà phân tích trẻ tuổi của CIA Joe Turner đã thử thách chủ nghĩa lý tưởng của mình khi biết rằng CIA đã sử dụng một thuật toán do anh phát triển để theo dõi công dân Mỹ, dẫn tổ chức này đến một âm mưu khủng bố đe dọa tính mạng của hàng triệu người. Lấy cảm hứng từ bộ phim kinh dị chính trị năm 1975 của Sydney Pollack Three Days of the Condor.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 10, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Max Irons","avatar":""},{"name":"Kristen Hager","avatar":""},{"name":"Bob Balaban","avatar":""},{"name":"Eric Johnson","avatar":""},{"name":"Alexei Bondar","avatar":""},{"name":"Isidora Goreshter","avatar":""},{"name":"Jonathan Kells Phillips","avatar":""},{"name":"Toby Leonard Moore","avatar":""},{"name":"Sam McCarthy","avatar":""},{"name":"Constance Zimmer","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324339);
