INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-thi-nau-can', 'Cuộc Thi Nấu Cần', 'Cooked with Cannabis', 'https://phimimg.com/upload/vod/20231207-1/cb4f2ae66258bae3c6f705925677db72.jpg', 'https://phimimg.com/upload/vod/20231207-1/27b2b510f457d603c9454bd6bae0ea3e.jpg', '<p>Với món ăn từ cần sa được nâng tầm nhờ nghệ thuật dùng thảo mộc lá, chất pha chế THC và sốt CBD, các đầu bếp trổ tài đưa cả MC lẫn khách mời đặc biệt vào nỗi đê mê.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 12, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Kelis","avatar":""},{"name":"Leather Storrs","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324339);
