INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('emma', 'Emma.', 'Emma.', 'https://phimimg.com/upload/vod/20231208-1/30bb2ec80fab13e2882dc5470728439b.jpg', 'https://phimimg.com/upload/vod/20231208-1/f68f3127139771c937ad7dc17ec06436.jpg', '<p>Hài kịch yêu dấu của Jane Austen về việc tìm kiếm sự bình đẳng của bạn và kiếm được kết thúc có hậu của bạn, được coi trọng trong việc này. Đẹp trai, thông minh và giàu có, Emma Woodhouse là một con ong nữ hoàng bồn chồn mà không có đối thủ trong thị trấn nhỏ buồn ngủ của mình. Trong sự châm biếm lấp lánh của tầng lớp xã hội này và nỗi đau lớn lên, Emma phải phiêu lưu thông qua các trận đấu sai lầm và những sai lầm lãng mạn để tìm thấy tình yêu đã ở đó cùng.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324339);
