INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-ma-2', 'Cậu Bé Ma 2', 'Brahms: The Boy II', 'https://phimimg.com/upload/vod/20231208-1/1ce18a9541488a41d0d73ada66afc0cb.jpg', 'https://phimimg.com/upload/vod/20231208-1/b59f6ab343a81ec570a00f88f4a4d459.jpg', '<p>Một gia đình chuyển đến nhà mới. Mọi thứ có vẻ như rất ổn cho đến khi cậu con trai của họ tìm thấy một mô hình búp bê được chôn dưới đất. Cũng từ đây, nhiều chuyện kì lạ đã xảy ra, con búp bê dường như đã bị nguyền rủa và đang gieo rắc nỗi ám ảnh kinh hoàng cho tất cả mọi người.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Katie Holmes","avatar":""},{"name":"Christopher Convery","avatar":""},{"name":"Owain Yeoman","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324339);
