INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('i-shall-live-by-myself', 'I Shall Live by Myself', 'I Shall Live by Myself', 'https://phimimg.com/upload/vod/20231206-1/d5569381a0d57b4566158fed975aaf61.jpg', 'https://phimimg.com/upload/vod/20231206-1/5923f1b2f887db317242120a0803987a.jpg', '<p>Momoko là một người phụ nữ bảy mươi lăm tuổi và sống một mình. Cô sống ở Tokyo, nhưng không được sinh ra ở đó đã đến đó hơn năm mươi năm trước. Cô đã gặp một người đàn ông tốt, đã được đề xuất và chấp nhận. Cô sinh hai đứa con trước khi chồng chết. Cô ấy một mình một lần nữa cho đến khi tìm đường vào một thư viện một ngày. Cô sớm tìm thấy sự an ủi và đồng hành ...</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324339);
