INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-thu-oan-khuat', 'Dinh Thự Oan Khuất', 'Ghosts Of War', 'https://phimimg.com/upload/vod/20231206-1/39bb8971baaadca6cf2a598fcc403b19.jpg', 'https://phimimg.com/upload/vod/20231206-1/e0b505849ab71fa02b2511133b878ea3.jpg', '<p>Năm 1944, năm anh lính được giao nhiệm vụ canh giữ một dinh thự bỏ hoang. Khi họ đến nơi, nhóm lính trước vội vàng rời đi mà không để lại một lời giải thích nào. Thế rồi chuyện gì đến cũng đã đến, năm người lính nhận ra trong dinh thự rộng lớn đó không chỉ có bọn họ. Những hiện tượng kỳ quái ở đây khiến tinh thần của những người đàn ông mạnh mẽ dần đi xuống.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Brenton Thwaites","avatar":""},{"name":"Kyle Gallner","avatar":""},{"name":"Billy Zane","avatar":""},{"name":"Laila Banki","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324339);
