INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-asadas', 'The Asadas', 'The Asadas', 'https://phimimg.com/upload/vod/20231205-1/596d56b46f72368a3c016f52281fb457.jpg', 'https://phimimg.com/upload/vod/20231205-1/9b5be365d471af4305eb705316d9c509.jpg', '<p>Masashi là một nhiếp ảnh gia trẻ, người tạo thành một gia đình là anh trai và cha mẹ. Thảm họa tấn công Nhật Bản dưới dạng sóng thần và lò phản ứng hạt nhân sau đó là Meltdown và đất nước đang hỗn loạn. Anh ấy làm những gì đến với anh ấy một cách yêu thương. Anh ta tạo ra chân dung nhiếp ảnh của gia đình anh ấy.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324339);
