INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('come-play', 'Come Play', 'Come Play', 'https://phimimg.com/upload/vod/20231204-1/9679ab9d961ee5f62f30d0c92be1c1a2.jpg', 'https://phimimg.com/upload/vod/20231204-1/bc21176ed525843c29c05b58bddb26a8.jpg', '<p>Một con quái vật tên là Larry tuyên bố thông qua điện thoại thông minh và thiết bị di động. Phiên bản phim tính năng của bộ phim ngắn 2017.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324339);
