INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-vo-anh-nhe', 'Làm Vợ Anh Nhé', 'Marry Me Now', 'https://phimimg.com/upload/vod/20231204-1/d8725785e6e19ddcb30aca4671d09dca.jpg', 'https://phimimg.com/upload/vod/20231204-1/7bbdbf43a74915b542a4753f7cbb2354.jpg', '<p>Phim Làm Vợ Anh Nhé kể về nữ sinh viên y khoa Park Yoo Ha hiện đã hoàn thành khóa thực tập của mình. Cô nỗ lực trở thành bác sĩ vì cha mình. Ông đã tự nuội bốn đứa con, bỗng một ngày ông quyết định kết hôn với một người giàu có, bà chủ của một tòa nhà…Park Yoo-Ha (Han Ji-Hye) học tập chăm chỉ tại trường dược và đã kết thúc kỳ thực tập. Cô ấy luôn cố gắng trở thành bác sĩ vì bố cô ấy. Ông chăm sóc 4 người con và chị cả cô ấy cũng phải hi sinh cho gia đình. Cô không có hứng thú với bất kỳ ai. Đột nhiên, cha cô ấy kết hôn với một người phụ nữ giàu có. Ngược lại, Jung Eun-Tae (Lee Sang-Woo) là một bác sĩ và là tình nguyện viên y tế về dược ở nước ngoài, nhưng anh phải trở lại Hàn Quốc. Anh không thích kết hôn và có ước muốn được như bố của mình – một người tiên phong trong ngành dược.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 20, 2020, 'Lồng Tiếng', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Mi Hee","avatar":""},{"name":"Jang Sung Bum","avatar":""},{"name":"Yoo Dong Geun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324339);
