INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-nhi-khoa-tai-ba', 'Bác Sĩ Nhi Khoa Tài Ba', 'Healer Of Children', 'https://phimimg.com/upload/vod/20231204-1/9d7d4fe2bb59bfc792636fe31e30c784.jpg', 'https://phimimg.com/upload/vod/20231204-1/ece2c5f7b5fc9183941477d392b050ce.jpg', '<p>Bác sĩ nhi Đặng Tử Ngang, Tiêu Giai Nhân dưới sự dìu dắt của Giám đốc bệnh viện Cốc Lập Phong. Đặng Tử Ngang là một bác sĩ soái ca thuộc thế hệ phú nhị đại nhưng lại rất chuyên tâm và nghiêm túc theo đuổi nghề y, với mong muốn cứu chữa cho các bệnh nhân nhí. Trong quá trình công tác, bác sĩ Đặng Tử Ngang nảy sinh tình cảm với đồng nghiệp Tiêu Giai Nhân đến từ Vân Nam, cuối cùng hai người có một kết cục viên mãn.</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 14, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Vương Tử Văn","avatar":""},{"name":"Giả Thanh","avatar":""},{"name":"Vu Tiểu Vỹ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324339);
