INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chieu-tro-lua-gat', 'Chiêu Trò Lừa Gạt', 'Deceitful Love', 'https://phimimg.com/upload/vod/20231204-1/f0178051440f2ca21e75ab61a8383493.jpg', 'https://phimimg.com/upload/vod/20231204-1/af06b4612b65733ed58a0291df876cc0.jpg', '<p>Chiêu Trò Lừa Gạt - Deceitful Love phát song song với Thái Lan vào tối thứ 2, thứ 3 hàng tuần. Bộ phim đánh dấu sự tái hợp của cặp đôi siêu hot Bella Ranee và Pope Thanawat sau bom tấn Nhân Duyên Tiền Định (Ngược Dòng Thời Gian Để Yêu Anh). Phim xoay quanh Ramin, một luật sư sắc sảo và Pitcha, một cô gái xã hội tự tin hiện đại, là giám đốc điều hành của một công ty tổ chức. Họ là những người bạn thời thơ ấu gặp lại nhau khi Pitcha quyết định ly dị người chồng lừa dối của mình với sự giúp đỡ của Ramin.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 16, 2020, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Bella Ranee","avatar":""},{"name":"Pope Thanawat","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324339);
