INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-hoi-sinh', 'Chiến Binh Hồi Sinh', 'The Doorman', 'https://phimimg.com/upload/vod/20231205-1/0488d04de47f0546979fabd537aa353f.jpg', 'https://phimimg.com/upload/vod/20231205-1/36f72c53cc02a5c7a0a8dc61ce8d9b52.jpg', '<p>Chiến Binh Hồi Sinh - The Doorman kể về nữ quân nhân Ali. Sau khi không vượt qua được nỗi ám ảnh về vụ khủng bố khi cô còn thực hiện nhiệm vụ bảo vệ gia đình đại sứ Mỹ tại nước ngoài, Ali giải ngũ quay trở về New York sinh sống. Được người thân nhờ làm gác cửa tại một căn biệt thự chứa nhiều tài sản quý giá, Ali vô tình trở thành người bảo vệ nơi này trước kế hoạch tấn công được tính toán kỹ lưỡng của một nhóm khủng bố chuyên nghiệp.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean Reno","avatar":""},{"name":"Ruby Rose","avatar":""},{"name":"Louis Mandylor","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324339);
