INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('proximity', 'Proximity', 'Proximity', 'https://phimimg.com/upload/vod/20231204-1/6b253b7e44b4c3334baaf20f3d2a0ad0.jpg', 'https://phimimg.com/upload/vod/20231204-1/4c32f41ff0ea191d5487dbc715f9c2ca.jpg', '<p>Isaac Cypress hoạt động cho phòng thí nghiệm JPL của NASA như một nhà toán học / nhà khoa học. Anh ấy đang làm việc trong một dự án tự viết video, được khuyến khích bởi cố vấn của mình, khi một UFO hạ cánh kết tủa gần đó. Anh ta giật mình một thời gian ngắn sau đó để thấy một người ngoài hành tinh đằng sau anh ta. Điều cuối cùng anh nhớ lại đang bị kéo lên trời. Khi trở về nhà, anh biết rằng anh đã mất tích trong ba ngày. Đoạn phim video cho thấy anh ta đã bị bắt cóc bởi người ngoài hành tinh. Anh ta đăng nó trên internet, nhưng hầu như không ai tin rằng câu chuyện của mình. Anh ta bị ám ảnh bởi việc tìm kiếm bằng chứng, dẫn dắt anh ta trên một hành trình khám phá. Thông qua Internet, ông tìm kiếm những người khác có thể đã có những trải nghiệm tương tự và gặp Sara. Cô ấy cũng đang bị bắt cóc và mất ba ngày ký ức. Cả hai đều bị đau nhức trong vòng tay phải của họ. Isaac được tiếp cận bởi một người đàn ông tuyên bố viết một blog và muốn giúp anh ta nhận được nhiều sự tín nhiệm cho câu chuyện của mình. Nhưng anh ta thực sự là một đại lý của một cơ quan Ops đen muốn tìm hiểu thêm về người ngoài hành tinh và nơi ở của một người đàn ông Alaska, những người tuyên bố anh ta cũng bị bắt cóc. Isaac quản lý để thoát khỏi cơ sở tổ chức của họ ở Costa Rico và chạy trốn với Sara đến British Columbia.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324339);
