INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-ho-noi-viec-ho-lam', 'Điều Họ Nói, Việc Họ Làm', 'Love Affair(s)', 'https://phimimg.com/upload/vod/20231202-1/43638adf0cd5f00a1bf51199d2141b93.jpg', 'https://phimimg.com/upload/vod/20231202-1/0bb4a9666ca163d7209b236601d09d9b.jpg', '<p>Kỳ nghỉ ở vùng nông thôn Pháp. Daphne, đang mang thai ba tháng, thấy mình đơn độc để chào đón Maxime, em họ của bạn trai François. François phải vội vã đến Paris để chăm sóc cho một đồng nghiệp bị ốm. Trong bốn ngày, trong khi chờ đợi sự trở lại của anh ấy, Daphne và Maxime làm quen với nhau và chia sẻ những câu chuyện rất thân mật khiến họ xích lại gần nhau hơn...</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Camélia Jordana","avatar":""},{"name":"Niels Schneider","avatar":""},{"name":"Vincent Macaigne","avatar":""},{"name":"Émilie Dequenne","avatar":""},{"name":"Jenna Thiam","avatar":""},{"name":"Guillaume Gouix","avatar":""},{"name":"Julia Piaton","avatar":""},{"name":"Louis-Do de Lencquesaing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324339);
