INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoc-tich-2-lanh-huyet-cuong-yen', 'Tước Tích 2: Lãnh Huyết Cuồng Yến', 'L.O.R.D: Legend of Ravaging Dynasties 2', 'https://phimimg.com/upload/vod/20231202-1/3cea3663f0389d564f3cbef3b8601d22.jpg', 'https://phimimg.com/upload/vod/20231202-1/f00cf542e3486096578362eefe1e1694.jpg', '<p>Vì hoàn thành di nguyện Vương tước cấp 6 Tây Lưu Nhĩ, Ngân Trần Kỳ Linh, Thiên Thúc U Hoa quyết định cùng nhau đi giải cứu Vương tước Cát Nhĩ Già Mĩ Thập. Khi vượt qua trở ngại trùng trùng đến được nơi giam cầm, không may gặp phải đội hình sát thủ mạnh nhất của Bạch Ngân Tế Ti: U Minh, Đặc Lôi Á, Tất Lạp, một trận giao đấu chính diện không thể tránh khỏi, bí mật đen tối của đế quốc Ashland cũng dần dần hiện ra.</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Kris Wu","avatar":""},{"name":"Chen Xuedong","avatar":""},{"name":"William Chan Wai-Ting","avatar":""},{"name":"Amber Kuo","avatar":""},{"name":"Lin Yun","avatar":""},{"name":"Roy Wang","avatar":""},{"name":"Karry Wang","avatar":""},{"name":"Jackson Yee","avatar":""},{"name":"Wang Duo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324339);
