INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuoc-tich-2-lanh-huyet-cuong-yen', 'Tước Tích 2: Lãnh Huyết Cuồng Yến', 'L.O.R.D: Legend of Ravaging Dynasties 2', 'tước tích 2: lãnh huyết cuồng yến l.o.r.d: legend of ravaging dynasties 2 kris wu chen xuedong william chan wai-ting amber kuo lin yun roy wang karry wang jackson yee wang duo ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('another-round', 'Another Round', 'Another Round', 'https://phimimg.com/upload/vod/20231213-1/e3146e14aec3ab3646fc19621a0f0d38.jpg', 'https://phimimg.com/upload/vod/20231213-1/b05447d906a5a1cfc83ceeb65212aaf6.jpg', '<p>Có một lý thuyết rằng con người được sinh ra với một nửa mỗi mille quá ít. Rượu đó trong máu mở tâm đến thế giới bên ngoài, các vấn đề có vẻ nhỏ hơn và sáng tạo tăng lên. Chúng tôi biết rõ về nó; Sau ly rượu đầu tiên, cuộc trò chuyện nâng lên, các khả năng mở ra. Martin là một giáo viên trung học. Anh cảm thấy già và mệt mỏi. Học sinh và cha mẹ của họ muốn anh ta chấm dứt tăng mức trung bình của họ. Được khuyến khích bởi lý thuyết trên Mille, Martin và ba đồng nghiệp đã tự ném mình vào một thí nghiệm để duy trì tác động cồn liên tục trong cuộc sống hàng ngày. Nếu Churchill đã giành chiến thắng trong Thế chiến II trong một làn sương mù tinh thần dày đặc, những giọt mạnh có thể khiến họ và học sinh của họ là gì? Kết quả là tích cực ngay từ đầu. Lớp học của Martin đang ở một cách khác bây giờ, và dự án đang được thăng chức một nghiên cứu học tập thực sự với việc thu thập kết quả. Dần dần, nhưng chắc chắn, rượu làm cho bốn người bạn và môi trường xung quanh chúng nới lỏng. Các kết quả đang tăng lên, và họ thực sự bắt đầu cảm thấy cuộc sống. Khi các đối tượng đi vào trong, thí nghiệm tiến triển cho một số, và tắt theo dõi cho người khác. Nó trở nên rõ ràng hơn và rõ ràng hơn rằng rượu có thể tạo ra kết quả tuyệt vời trong lịch sử thế giới, nhưng tất cả táo bạo cũng có thể có hậu quả. Bộ phim được mô tả là một bộ phim truyền hình vui nhộn, cảm động và kích thích suy nghĩ về tình bạn, tự do - và rượu.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub', 'HD', 'Hà Lan', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324339);
