INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tra-thu-cua-thieu-nu', 'Sự Trả Thù Của Thiếu Nữ', 'Girl''s Revenge', 'https://phimimg.com/upload/vod/20231202-1/78bd63cbab71478db9b476a1391031ca.jpg', 'https://phimimg.com/upload/vod/20231202-1/5c9a70816b31564d965fa4be51240521.jpg', '<p>Tại một bữa tiệc sinh nhật, một video sex được quay mà không có sự đồng ý và Ren Li-cha chính là cô gái trong video. Đoạn clip được lan truyền trong giới học sinh và kết quả là Li-cha bị chế giễu và bắt nạt. Wu Yun-heng, một học sinh chuyển trường, đã đến bữa tiệc với Li-cha. Vì cô ấy không thể chịu đựng được Li-cha đã phải chịu đựng bao nhiêu&quot; cô quyết tâm tìm ra sự thật đằng sau vụ việc, chiến đấu vì người bạn thân nhất của mình. Tuy nhiên, khi cô tiến gần hơn đến sự thật, cô sắp phá vỡ sự yên bình ở trường.</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Yu-Ping Wang","avatar":""},{"name":"Yi-Ruei Chen","avatar":""},{"name":"Shiny Yao","avatar":""},{"name":"Chu-Ping Liu","avatar":""},{"name":"Mike Lin","avatar":""},{"name":"Edison Song","avatar":""},{"name":"Alex Shu-Yuan Ko","avatar":""},{"name":"Heaven Hai","avatar":""},{"name":"Tao Chuang Cheng","avatar":""},{"name":"Yi-Fan Hsu","avatar":""},{"name":"Teng-Hung Hsia","avatar":""},{"name":"Moon Lee","avatar":""},{"name":"Chang-Ying Hsieh","avatar":""},{"name":"Ying-Xuan Ge","avatar":""},{"name":"Jiun-Wen Ran","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324339);
