INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tham-dich-nhan-kiet', 'Thần Thám Địch Nhân Kiệt', 'Detective Di Renjie', 'https://phimimg.com/upload/vod/20231202-1/795d459b1a17dafa7f623019b6216479.jpg', 'https://phimimg.com/upload/vod/20231202-1/03affef9e696921bd9dd151ad3b2e167.jpg', '<p>Vào thời kỳ Võ Chu, tại thành Trường An ở Đế Kinh xảy ra những vụ án mạng vô cùng kỳ lạ. Bởi vì nguyên nhân cái chết còn rất mơ hồ, nên những lời đồn về bức Bích Họa Phi Thiên ở Trung Liệt Từ giết người ngày một nghiêm trọng hơn. Bách tính đồn rằng ông trời giáng điềm không lành khiến lòng người hoang mang. Sau đó Địch Nhân Kiệt và Thần võ quân – đô úy Tạ Dao Hoàn phụng mệnh cùng đi điều tra vụ án này. Cuối cùng, không những dập tắt lời đồn bắt được hung thủ thật sự, mà còn hóa giải được một ân oán kéo dài hơn 20 năm.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Du Yiheng","avatar":""},{"name":"Yang Shu","avatar":""},{"name":"Zhang Zixuan","avatar":""},{"name":"Zhang Zixuan","avatar":""},{"name":"Guo Mingyuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324339);
