INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-co-ua', 'Màu Cỏ Úa', 'The Blue Of Green Grass', 'https://phimimg.com/upload/vod/20231210-1/391ac7af66ccf28d6f05668f62849d5d.jpg', 'https://phimimg.com/upload/vod/20231210-1/160957964d1f7ac851eec0a223d2e33c.jpg', '<p>Màu Cỏ Úa là phim tài liệu âm nhạc với nhân vật chính là “gã du ca” nổi tiếng của Việt Nam – nhạc sĩ Trần Tiến, cùng sự xuất hiện của gia đình, bạn bè và nhiều giọng ca gắn bó với âm nhạc của ông.</p>', 'Full', 1, 'single', 'completed', 19, 2020, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Trần Tiến","avatar":""},{"name":"Trần Thu Hà","avatar":""},{"name":"Trần Hiếu","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324339);
