INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('persian-lessons', 'Persian Lessons', 'Persian Lessons', 'https://phimimg.com/upload/vod/20231201-1/69dc4fc1a1f9c38ad2bae6a6b368e953.jpg', 'https://phimimg.com/upload/vod/20231201-1/a2761724b15968e81647497eb5f87822.jpg', '<p>1942. Gilles, một người đàn ông trẻ Bỉ, bị SS bắt giữ cùng với những người Do Thái khác và được gửi đến một trại tập trung ở Đức. Anh ta tham gia thu hẹp bằng cách chửi thề với những người bảo vệ rằng anh ta không phải là người Do Thái, nhưng Ba Tư. Lời nói dối này tạm thời cứu anh ta, nhưng sau đó là Gilles được chỉ định một nhiệm vụ dường như không thể giải quyết được: Dạy Ba Tư cho Koch, Cán bộ phụ trách nhà bếp của trại, người mơ ước mở một nhà hàng ở Ba Tư (Iran) một khi chiến tranh kết thúc. Gilles thấy mình phải phát minh ra một ngôn ngữ mà anh ta không biết, từ bằng lời nói. Khi mối quan hệ bất thường giữa hai người đàn ông bắt đầu kích động sự ghen tuông và nghi ngờ, Gilles trở nên biết sâu sắc rằng một động thái sai lầm có thể khiến sự lừa đảo của anh ta.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Nahuel Pérez Biscayart","avatar":""},{"name":"Lars Eidinger","avatar":""},{"name":"Jonas Nay","avatar":""},{"name":"Leonie Benesch","avatar":""},{"name":"Alexander Beyer","avatar":""},{"name":"David Schütter","avatar":""},{"name":"Luisa-Céline Gaffron","avatar":""},{"name":"Andreas Hofer","avatar":""},{"name":"Giuseppe Schillaci","avatar":""},{"name":"Antonin Chalon","avatar":""},{"name":"Lola Bessis","avatar":""},{"name":"Mehdi Rahim-Silvioli","avatar":""},{"name":"Sofya Gershevich","avatar":""},{"name":"Nico Ehrenteit","avatar":""},{"name":"Gareth McGrego","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324339);
