INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-sieu-lay', 'Điệp Viên Siêu Lầy', 'My Spy', 'https://phimimg.com/upload/vod/20231201-1/08a02c85cb3fda6b914b8f1a22432fbd.jpg', 'https://phimimg.com/upload/vod/20231201-1/8f6587566727fee7ac9219b84f547a17.jpg', '<p>Jason Jones, hay còn gọi là JJ (Dave Bautista) – một điệp viên CIA dày dạn kinh nghiệm. Trong một lần thực địa, JJ bị cô bé 9 tuổi Sophie (Chloe Coleman) phát hiện và uy hiếp anh phải “gia sư” môn điệp viên cho mình nếu không muốn cả thế giới biết thân phận thực sự của anh. Mắc kẹt bên cô học trò lắm mưu nhiều mẹo, JJ dần phát hiện ra Sophie thực sự có tố chất và năng khiếu bẩm sinh cho việc trở thành điệp viên.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dave Bautista","avatar":""},{"name":"Chloe Coleman","avatar":""},{"name":"Parisa Fitz-Henley","avatar":""},{"name":"Kristen Schaal","avatar":""},{"name":"Greg Bryk","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Nicola Correia Damude","avatar":""},{"name":"Devere Rogers","avatar":""},{"name":"Noah Dalton Danby","avatar":""},{"name":"Vieslav Krystyan","avatar":""},{"name":"Basel Daoud","avatar":""},{"name":"Ali Hassan","avatar":""},{"name":"Olivia Dépatie","avatar":""},{"name":"Keller Viaene","avatar":""},{"name":"Laura Cilevitz","avatar":""},{"name":"Darrin Baker","avatar":""},{"name":"Chris","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324339);
