INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-my-grandmas-a-lesbian', 'So My Grandma''s a Lesbian!', 'So My Grandma''s a Lesbian!', 'https://phimimg.com/upload/vod/20231201-1/6226126cf4ce7dd122e141469dddc215.jpg', 'https://phimimg.com/upload/vod/20231201-1/c99cbbd4006246b1562d878289a4dbf9.jpg', '<p>Một luật sư trẻ đầy triển vọng nhìn thấy kế hoạch của cô ấy để kết hôn với một gia đình quan trọng và cực kỳ nguy hiểm khi bà cô quyết định kết hôn với bạn gái của cô ấy.</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Rosa María Sardà","avatar":""},{"name":"Verónica Forqué","avatar":""},{"name":"Ingrid García Jonsson","avatar":""},{"name":"David Verdaguer","avatar":""},{"name":"Candela Peña","avatar":""},{"name":"Mónica López","avatar":""},{"name":"Álex O''Dogherty","avatar":""},{"name":"Pol Monen","avatar":""},{"name":"Leander Vyvey","avatar":""},{"name":"Liz Lobato","avatar":""},{"name":"María Caballero","avatar":""},{"name":"Marta Martín","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324339);
