INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuyen-truong-rang-kiem-va-vien-kim-cuong-ma-thuat', 'Thuyền Trưởng Răng Kiếm và Viên Kim Cương Ma Thuật', 'Captain Sabertooth and the Magical Diamond', 'https://phimimg.com/upload/vod/20231201-1/a4eff51e5cdb8dd055e8dbce160fe5bf.jpg', 'https://phimimg.com/upload/vod/20231201-1/5bb81f904dd2a3ce7db49949c269ca3d.jpg', '<p>Truyền thuyết kể rằng giữa đại dương bao la có một viên Kim cương Ma thuật sở hữu khả năng ban điều ước mỗi dịp trăng tròn. Tên ma cà rồng Maga Kahn và nữ hoàng biến hình tà ác Sirima đều muốn chiếm lấy nó để thực hiện những âm mưu đen tối. Thế nhưng ngay trước ngày trăng tròn, viên Kim cương đã bị Marco lấy đi mất. Maga Kahn ngay lập tức ra lệnh cho đội quân khỉ hung hãn truy lùng tên trộm tí hon bằng mọi giá.
 Trong khi đó, Thuyền trưởng Răng Kiếm huyền thoại xứ Caribbean cũng đang trong quá trình truy lùng viên Kim cương Ma thuật. Gã tìm đến Pinky và Veronica tại làng Luna Bay để ép họ tham gia vào chuyến thám hiểm. Một lần nữa, cả hai lại được giương buồm cùng chiếc tàu The Black Lady và bắt đầu chuyến hải trình cam go nhưng cũng vô cùng hấp dẫn để tìm kiếm viên Kim cương màu nhiệm.</p>', 'Full', 1, 'hoathinh', 'completed', 23, 2020, 'Lồng Tiếng', 'HD', 'Na Uy', 0, '[{"name":"Kyrre Haugen Sydness","avatar":""},{"name":"Tobias Santelmann","avatar":""},{"name":"Trond Fausa Aurvåg","avatar":""},{"name":"Jon Øigarden","avatar":""},{"name":"Charlotte Frogner","avatar":""},{"name":"Leonard Valestrand Eike","avatar":""},{"name":"Siri Skjeggedal","avatar":""},{"name":"Bartek Kaminski","avatar":""},{"name":"Laila Goody","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324339);
