INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-ben-em', 'Mãi Bên Em', 'Endless', 'https://phimimg.com/upload/vod/20231201-1/7b02f7e63fc1dd78647a77ea96809d58.jpg', 'https://phimimg.com/upload/vod/20231201-1/1263995fa1b367345f343e3392c69d4c.jpg', '<p>Đang yêu say đắm thì một tai nạn thương tâm chia lìa Riley và Chris ở hai thế giới, Riley không thể vượt qua được mặc cảm tội lỗi, còn Chris thì không thể siêu thoát. Bằng một phép màu nhiệm, cả hai tìm được cách liên hệ với nhau. Một câu chuyện tình yêu vượt qua được giới hạn sống chết, để rồi họ, học được cách…buông tay.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexandra Shipp","avatar":""},{"name":"Nicholas Hamilton","avatar":""},{"name":"DeRon Horton","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Ian Tracey","avatar":""},{"name":"Catherine Lough Haggquist","avatar":""},{"name":"Zoë Belkin","avatar":""},{"name":"Eddie Ramos","avatar":""},{"name":"Patrick Gilmore","avatar":""},{"name":"Aaron Pearl","avatar":""},{"name":"Barbara Meier","avatar":""},{"name":"B. J. Harrison","avatar":""},{"name":"Dennis Cound","avatar":""},{"name":"Melanie Walden","avatar":""},{"name":"Alexa Barajas","avatar":""},{"name":"Bradley James","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324339);
