INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gieng-den', 'Giếng Đen', 'Kaali Khuhi', 'https://phimimg.com/upload/vod/20231130-1/4fa353f43256ca22176c4527688e6c97.jpg', 'https://phimimg.com/upload/vod/20231130-1/326ef84dce35871da84e668f6e388ccb.jpg', '<p>Khi một linh hồn không yên nghỉ nguyền rủa ngôi làng có tập tục giết bé gái sơ sinh, số phận của thị trấn nằm trong tay của một cô bé 10 tuổi.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Shabana Azmi","avatar":""},{"name":"Riva Arora","avatar":""},{"name":"Satyadeep Misra","avatar":""},{"name":"Sanjeeda Sheikh","avatar":""},{"name":"Leela Samson","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324339);
