INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-am-trong-mat-em', 'Thanh Âm Trong Mắt Em', 'Your Eyes Tell', 'https://phimimg.com/upload/vod/20231130-1/3f091051b361668db0fc41b5b16c3572.jpg', 'https://phimimg.com/upload/vod/20231130-1/03c8816901569100cce9a7bb2a9a6707.jpg', '<p>Thanh Âm trong Mắt Em – Kimi no Me ga Toikakete Iru (2020) Sau vụ tai nạn thương tâm, Akari mất đi cùng lúc cả thị giác lẫn gia đình, nhưng cô vẫn luôn lạc quan và nghị lực vượt qua cuộc sống khó khăn. Rui là một tội phạm hoàn lương, anh từng là một võ sĩ Kickboxing. Một lần hiểu lầm khiến 2 người quen biết nhau và dần nảy sinh tình cảm. Hai người dọn về sống chung và phụ giúp nhau trong cuộc sống. Tưởng chừng chuyện tình đẹp như mơ, trùng hợp vào ngày Akari xảy ra tai nạn cũng là ngày Rui đã làm chuyện xấu xa không thể nào tha thứ được. Chuyện gì đã xảy ra, liệu chuyện tình lãng mạn nhưng cũng đầy nước mắt của họ sẽ như thế nào?</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yuriko Yoshitaka","avatar":""},{"name":"Ryusei Yokohama","avatar":""},{"name":"Ryosei Tayama","avatar":""},{"name":"Kyosuke Yabe","avatar":""},{"name":"Toru Nomaguchi","avatar":""},{"name":"Eita Okuno","avatar":""},{"name":"Akane Sakanoue","avatar":""},{"name":"Yoshinori Okada","avatar":""},{"name":"Kanna Moriya","avatar":""},{"name":"Keita Machida","avatar":""},{"name":"Jun Fubuki","avatar":""},{"name":"Kaito Mifune","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324339);
