INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thanh-am-trong-mat-em', 'Thanh Âm Trong Mắt Em', 'Your Eyes Tell', 'thanh âm trong mắt em your eyes tell yuriko yoshitaka ryusei yokohama ryosei tayama kyosuke yabe toru nomaguchi eita okuno akane sakanoue yoshinori okada kanna moriya keita machida jun fubuki kaito mifune ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-dao-tau', 'Phi Vụ Đào Tẩu', 'Escape from Pretoria', 'https://phimimg.com/upload/vod/20231130-1/4cdf5d87fca6c8688a7d9817309d35c2.jpg', 'https://phimimg.com/upload/vod/20231130-1/9684f8fad6a1de8e992992a273dad306.jpg', '<p>Dựa trên câu chuyện có thật về cuộc đào tẩu thần kì khỏi nhà tù an ninh Pretoria (Nam Phi) của hai nhà hoạt động chính trị Tim Jerkins và Stephen Lee, bộ phim tái hiện chân thật và nghẹt thở kế hoạch vượt ngục phi thường và kịch tính. Nhờ vào óc quan sát tỉ mỉ, trí thông minh và sự khéo léo, họ đã tạo ra những chiếc chìa khóa gỗ vượt 10 cánh cửa thép và tìm lại tự do cho chính mình!</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Daniel Webber","avatar":""},{"name":"Ian Hart","avatar":""},{"name":"Mark Leonard Winter","avatar":""},{"name":"Nathan Page","avatar":""},{"name":"Grant Piro","avatar":""},{"name":"Len Firth","avatar":""},{"name":"Lliam Amor","avatar":""},{"name":"Adam Tuominen","avatar":""},{"name":"PJ Oaten","avatar":""},{"name":"Ratidzo Mambo","avatar":""},{"name":"Vuyo Loko","avatar":""},{"name":"Maris J. Caune","avatar":""},{"name":"Adam Ovadia","avatar":""},{"name":"Rory Walker","avatar":""},{"name":"Genevieve Mooy","avatar":""},{"name":"Jeanette Cronin","avatar":""},{"name":"Stephen Hunter","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324339);
