INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-chim-trong-nhip-dieu', 'Đắm Chìm Trong Nhịp Điệu', 'Feel the Beat', 'https://phimimg.com/upload/vod/20231130-1/ea55ed6804ee725c1eabee08f5a8fdc3.jpg', 'https://phimimg.com/upload/vod/20231130-1/ad048554420fb647fc8283a2978dac03.jpg', '<p>Sau khi thất bại ở buổi thử vai Broadway, một vũ công vị kỷ miễn cưỡng trở về quê nhà và đồng ý huấn luyện một nhóm những đứa trẻ lập dị để tham gia cuộc thi lớn.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Sofia Carson","avatar":""},{"name":"Wolfgang Novogratz","avatar":""},{"name":"Donna Lynne Champlin","avatar":""},{"name":"Enrico Colantoni","avatar":""},{"name":"Dennis Andres","avatar":""},{"name":"Rex Lee","avatar":""},{"name":"Brandon Kyle Goodman","avatar":""},{"name":"Eva Hauge","avatar":""},{"name":"Lidya Jewett","avatar":""},{"name":"Sadie Lapidus","avatar":""},{"name":"Johanna Colón","avatar":""},{"name":"Shaylee Mansfield","avatar":""},{"name":"Shiloh Nelson","avatar":""},{"name":"Justin Caruso Allan","avatar":""},{"name":"Carina Battrick","avatar":""},{"name":"Kai Zen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324339);
