INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-kiem-thuy-nhan', 'Tìm Kiếm Thuỷ Nhân', 'The Water Man', 'https://phimimg.com/upload/vod/20231130-1/173bc475bc4647e10c623954e8fe62de.jpg', 'https://phimimg.com/upload/vod/20231130-1/e3af6b82599e22e9bfa4c2c03cef7da2.jpg', '<p>Nhân vật chính trong phim là cậu bé Gunner (do Lonnie Chavis thủ vai), vì muốn cứu người mẹ ốm yếu của mình (do Dawson thủ vai) nên đã đi tìm một huyền thoại có tên Water Man. Gunner tin rằng một sinh vật nắm giữ bí mật để bất tử và bí mật đó sẽ cứu được mẹ của cậu.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Oyelowo","avatar":""},{"name":"Amiah Miller","avatar":""},{"name":"Lonnie Chavis","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Maria Bello","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Aaron Trainor","avatar":""},{"name":"Ted Rooney","avatar":""},{"name":"Jessica Oyelowo","avatar":""},{"name":"John Henry Whitaker","avatar":""},{"name":"Jennifer Lanier","avatar":""},{"name":"Colby Dahlstrom","avatar":""},{"name":"Adam Dunlap","avatar":""},{"name":"Josh Trerise","avatar":""},{"name":"Jack Lanning","avatar":""},{"name":"Brianne Huggins","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324339);
