INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('we-go-in-at-dawn', 'We Go in at Dawn', 'We Go in at Dawn', 'https://phimimg.com/upload/vod/20231130-1/1669b7193aaf83c5778340685e873dbe.jpg', 'https://phimimg.com/upload/vod/20231130-1/0271286e33114724f08090f2011973b5.jpg', '<p>Khi một người lập kế hoạch chiến tranh cao cấp bị bắt và được tổ chức tại một tù nhân chiến tranh Đức, một đội ngũ chuyên gia thực hiện sứ mệnh nguy hiểm khi cố gắng phá vỡ anh ta. Rắc rối là, anh ta không muốn được giải cứu.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Kelvin Fletcher","avatar":""},{"name":"Christos Lawton","avatar":""},{"name":"Audrey L''Ebrellec","avatar":""},{"name":"Samantha Coughlan","avatar":""},{"name":"Ryan Winsley","avatar":""},{"name":"Tim Berrington","avatar":""},{"name":"Nick Harris","avatar":""},{"name":"Guy Faulkner","avatar":""},{"name":"Antonio Bustorff","avatar":""},{"name":"Alastair Kirton","avatar":""},{"name":"Richard Touch","avatar":""},{"name":"Sammy Measom","avatar":""},{"name":"Nicholas Benjamin","avatar":""},{"name":"Patrick Capaloff-Fowler","avatar":""},{"name":"Tom Taplin","avatar":""},{"name":"E","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324339);
