INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-muoi-ba-3-ngay-sinh-tu', 'Chị Mười Ba: 3 Ngày Sinh Tử', 'Sister Thirteen', 'https://phimimg.com/upload/vod/20231207-1/b99977d37a5d580e5c4337fd526b7e26.jpg', 'https://phimimg.com/upload/vod/20231207-1/ba5254d3dd61c8734e300bc3368a4949.jpg', '<p>Kẽm Gai, đàn em cũ vừa ra tù của chị Mười Ba vướng vào một vụ giết người. Với thời hạn ba ngày, liệu chị Mười Ba có thể minh oan cho Kẽm Gai và cứu An Cư Nghĩa Đoàn khỏi mối đe doạ mới?</p>', 'Full', 1, 'single', 'completed', 17, 2020, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Thu Trang","avatar":""},{"name":"Tiến Luật","avatar":""},{"name":"Kiều Minh Tuấn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324339);
