INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-diep-van-thoi-khac-nguy-hiem', 'Thiếu Niên Diệp Vấn: Thời Khắc Nguy Hiểm', 'Ip Man: Crisis Time', 'https://phimimg.com/upload/vod/20231129-1/7c091104215441513f7bf07767da1d71.jpg', 'https://phimimg.com/upload/vod/20231129-1/d2e7fe84e1429c56b6a097503af5da1c.jpg', '<p>Hồi trẻ, Diệp Vấn đã tới Hồng Kông học tập. Khi đang tham gia cuộc thi diễn thuyết tiếng Anh ở trường, đột nhiên xảy ra vụ bắt cóc tống tiền, Diệp Vấn đã giao đấu với băng đảng xã hội đen. Âm mưu bắt cóc của tên trùm xã hội đen bị vạch trần, mối quan hệ của Diệp Vấn và hắn cũng được hé mở. Thiếu niên Diệp Vấn nên làm thế nào để giữ vững chính nghĩa trong lòng mình?</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhao Wenhao","avatar":""},{"name":"Mu Fengbin","avatar":""},{"name":"Li Hao-xuan","avatar":""},{"name":"Yuqing Shi","avatar":""},{"name":"Tong Xiaohu","avatar":""},{"name":"Jonathan Kos-Read","avatar":""},{"name":"Shao Xia","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324339);
