INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-vo-yeu', 'Giải Cứu Vợ Yêu', 'Khuda Haafiz', 'https://phimimg.com/upload/vod/20231129-1/cde6ac5ad0e5c9b162eb806738bef0ae.jpg', 'https://phimimg.com/upload/vod/20231129-1/d4b5b465fe126f4553e4a7d925d6b047.jpg', '<p>Giải Cứu Vợ Yêu kể về cuộc sống của một cặp vợ chồng mới cưới rơi vào nguy hiểm khi người vợ mất tích trong một hoàn cảnh bí ẩn.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Vidyut Jammwal","avatar":""},{"name":"Shivaleeka Oberoi","avatar":""},{"name":"Annu Kapoor","avatar":""},{"name":"Aahana Kumra","avatar":""},{"name":"Vipin Sharma","avatar":""},{"name":"Nawab Shah","avatar":""},{"name":"Gargi Patel","avatar":""},{"name":"Shahnawaz Pradhan","avatar":""},{"name":"Ikhlaq Khan","avatar":""},{"name":"Rio Kapadia","avatar":""},{"name":"Shiv Panditt","avatar":""},{"name":"Sougata Ghosh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324339);
