INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-khong-gian-2020', 'Quái Vật Không Gian', 'Alien Monster', 'null', 'https://phimimg.com/upload/vod/20231013-1/84ab547a29122014b703cee54b1fae17.jpg', '<p>Trong phim, nam diễn viên Lý Gia Băng do Tần Phong thủ vai là một sinh viên đại học, và Li Man do Yaoyao thủ vai, Nuo Yao do Yiyi thủ vai, Sun Shubo do Lu Yuan thủ vai và những người khác đã đi cắm trại phiêu lưu hoang dã, vô tình đột nhập vào căn cứ thử nghiệm với những sinh vật ngoài hành tinh, để thoát khỏi số phận trở thành vật chủ, cả nhóm đã tìm cách sống sót trong vùng hoang dã bí ẩn. Việc mở cánh cửa không-thời gian vô tình đưa những sinh vật thông minh ngoài hành tinh đến Trái đất, những con quái vật thoát khỏi tầm kiểm soát đã tàn sát con người, để ngăn chặn sự xâm lược quy mô lớn của quái vật, các đội chiến đấu được trang bị vũ khí công nghệ cao đã đi sâu vào các khu vực cách ly có nguy cơ cao để bẫy, và lúc này một người cắm trại đang lái xe đưa một nhóm thanh niên vào khu vực cấm, chờ đợi số phận của họ như một vật chủ.</p>', 'Full', 1, 'single', 'completed', 7, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Jiabing","avatar":""},{"name":"Li Man","avatar":""},{"name":"Mu Jianan","avatar":""},{"name":"Nuo Yao","avatar":""},{"name":"Zhou Yue","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324339);
