INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-hoc-duong-2020', 'Phù Thủy Học Đường', 'The Craft: Legacy', 'https://phimimg.com/upload/vod/20231028-1/529680865c2fe2cc6e578812c03a465a.jpg', 'https://phimimg.com/upload/vod/20231028-1/203ee34558ac877d49dbf791ac91c677.jpg', '<p>Một tác phẩm đến từ hãng phim kinh dị Blumhouse và được nhào nặn qua nhà sản xuất của siêu phẩm INVISIBLE MAN và SPLIT, phim xoay quanh 4 cô gái phù thủy đang dần khai phá những tiềm năng ma thuật mới.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cailee Spaeny","avatar":""},{"name":"Lovie Simone","avatar":""},{"name":"Gideon Adlon","avatar":""},{"name":"Zoey Luna","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"David Duchovny","avatar":""},{"name":"Nicholas Galitzine","avatar":""},{"name":"Julian Grey","avatar":""},{"name":"Charles Vandervaart","avatar":""},{"name":"Hannah Gordon","avatar":""},{"name":"Donald MacLean Jr.","avatar":""},{"name":"Fairuza Balk","avatar":""},{"name":"Chris Tomassetti","avatar":""},{"name":"Kris Siddiqi","avatar":""},{"name":"James Madge","avatar":""},{"name":"Victor Chiu","avatar":""},{"name":"Devin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324339);
