INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-gia-cua-sinh-mang', 'Cái Giá Của Sinh Mạng', 'Worth', 'https://phimimg.com/upload/vod/20231209-1/174fba3f41a79d3d8513f36c0cd31e85.jpg', 'https://phimimg.com/upload/vod/20231209-1/1de2c5e5a984dc0079943d463d79af9e.jpg', '<p>Sau cuộc tấn công khủng khiếp năm 2001 vào Trung tâm Thương mại Thế giới và Lầu năm góc, Quốc hội bổ nhiệm luật sư và Hòa giải trung gian nổi tiếng Kenneth Feinberg (Michael Keaton) để lãnh đạo Quỹ bồi thường nạn nhân 11 tháng 9. Được chỉ định phân bổ nguồn tài chính cho các nạn nhân của bi kịch, Feinberg và người đứng đầu hoạt động của công ty, Camille Biros (Amy Ryan), đối mặt với nhiệm vụ bất khả thi quyết định giá trị của một cuộc sống để giúp đỡ các gia đình bị tổn thất vô giá trị. Khi Feinberg khóa sừng với Charles Wolf (Stanley Tucci), một tổ chức cộng đồng thương tiếc về cái chết của vợ, sự hoài nghi ban đầu của anh ta chuyển sang lòng trắc ẩn khi anh ta bắt đầu học những chi phí thực sự của bi kịch.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324339);
