INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-chay-2020', 'Trốn Chạy', 'Run', 'https://phimimg.com/upload/vod/20231020-1/539d8078695ec0171e459fe1461ad94d.jpg', 'https://phimimg.com/upload/vod/20231020-1/45578f0b10600a9f0723b43981f339c1.jpg', '<p>Tuyệt tác từ đội ngũ biên kịch, sản xuất &amp; đạo diễn của SEARCHING. Liệt nửa người và mắc phải nhiều chứng bệnh mãn tính từ lúc lọt lòng, cuộc sống của Chloe đến tận năm 17 tuổi chỉ xoay quanh mẹ mình Diane và gần như bị cô lập với thế giới bên ngoài. Đến khi phát hiện ra bí mật khủng khiếp mẹ đang cố gắng che giấu, Chloe biết mình cần phải trốn chạy khỏi cái lồng vô hình đã giam giữ bản thân bấy lâu nay.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Paulson","avatar":""},{"name":"Kiera Allen","avatar":""},{"name":"Pat Healy","avatar":""},{"name":"Sara Sohn","avatar":""},{"name":"Erik Athavale","avatar":""},{"name":"B. J. Harrison","avatar":""},{"name":"Sharon Bajer","avatar":""},{"name":"Onalee Ames","avatar":""},{"name":"Joanne Rodriguez","avatar":""},{"name":"Ernie Foort","avatar":""},{"name":"Bradley Sawatzky","avatar":""},{"name":"Cory Wojcik","avatar":""},{"name":"Tony Revolori","avatar":""},{"name":"Carter Heintz","avatar":""},{"name":"Steve Pacaud","avatar":""},{"name":"Derek James Trapp","avatar":""},{"name":"Emma Jonnz","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324339);
