INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-am-anh-cua-mary-celeste', 'Nỗi Ám Ảnh Của Mary Celeste', 'Haunting of the Mary Celeste', 'https://phimimg.com/upload/vod/20231129-1/b010627c1772b39aabdfbabc7af8b7b5.jpg', 'https://phimimg.com/upload/vod/20231129-1/9a95d31dbf05e4ea352baa5528437f51.jpg', '<p>Rachel, một nhà nghiên cứu có liên quan, và nhóm của cô đã lên đường ra khơi để chứng minh rằng sự biến mất của một gia đình và thủy thủ đoàn khỏi một con tàu buôn là vì những lý do liên quan đến siêu nhiên. Giả thuyết của cô ấy rằng những người trên tàu Mary Celeste biến mất thành một &quot;khe nứt&quot; giữa các chiều không gian được chứng minh là đúng khi con thuyền bị hỏng và thủy thủ đoàn của cô ấy bắt đầu biến mất từng người một.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emily Swallow","avatar":""},{"name":"Ava Acres","avatar":""},{"name":"Richard Roundtree","avatar":""},{"name":"Dominic DeVore","avatar":""},{"name":"Alice Hunter","avatar":""},{"name":"Pierre Adele","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324339);
