INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoac-nguyen-giap-2020', 'Hoắc Nguyên Giáp', 'Huo Yuanjia', 'null', 'https://phimimg.com/upload/vod/20231130-1/1bd02f3713b1dc7780845032e51ec524.jpg', '<p>Phim mô tả câu chuyện về Huo YuanJia, võ sĩ Trung Quốc dựa vào tinh thần võ thuật của mình để bảo vệ phẩm giá của người Trung Quốc. Tại thời điểm cuối triều đại nhà Thanh, Trung Quốc phải đối mặt với những khó khăn và thách thức từ trong và ngoài nước.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tan Xu","avatar":""},{"name":"Cui Yongxuan","avatar":""},{"name":"Gu Huizi","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Cheng Qi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324339);
