INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-hon-ca', 'Trấn Hồn Ca', 'Monster Hunters', 'https://phimimg.com/upload/vod/20231130-1/65040445d01d492f8ccb4603fb726988.jpg', 'https://phimimg.com/upload/vod/20231130-1/074298aefb7e0c1b32c1f1fac55d4073.jpg', '<p>Xoay quanh hành trình trừ ma diệt yêu, mang lại cuộc sống bình yêu cho người dân của chàng trai trẻ Tiền Hữu Đạo. Câu chuyện bắt đầu từ núi Thái Ốc, yêu thú làm loạn, Lý Long không ngừng gây họa nhân gian, gieo nhiều căm phẫn. Lúc này, Thiên Huyền đại sư đã ra mặt, sử dụng toàn bộ khả năng của mình để phong ấn Lý Long. Nhiều năm sau, xuất hiện một loại bệnh lạ và không một thầy thuốc nào chữa được. Tiền Hữu Đạo tin rằng có một âm mưu lớn đằng sau mọi việc nên đã tìm cách điều tra. Sau đó, anh tình cờ gặp nữ pháp sự Điệp Y, 2 người cùng nhau hành trình trừ yêu.</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Leung Kar-yan","avatar":""},{"name":"Liu Lincheng","avatar":""},{"name":"Norman Chui Siu-Keung","avatar":""},{"name":"Peng Biyao","avatar":""},{"name":"Diana Dai","avatar":""},{"name":"Wu Shulin","avatar":""},{"name":"Han Mengwu","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324339);
