INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-thay-hai-huoc', 'Bậc Thầy Hài Hước', 'Crazy Old Father', 'https://phimimg.com/upload/vod/20231129-1/13fe92499dd15d3d9c4d700bceec213c.jpg', 'https://phimimg.com/upload/vod/20231129-1/3d37b7b5a1ed63b277f0d072ae86e654.jpg', '<p>Bậc Thầy Hài Hước - Crazy Old Father kể về Tiêu Lệ là một vận động viên đã nghỉ hưu, dẫn đầu đội bóng đá nữ trong làng để giành chiến thắng và giúp nhà trường thoát khỏi khó khăn dưới sự động viên của người cha. Bộ phim cho thấy các mối quan hệ cảm động giữa con người trong quá trình đấu tranh cho một cuộc sống tốt đẹp, và thể hiện ý tưởng rằng một cuộc sống tốt đẹp có thể đạt được thông qua sự chăm chỉ, một cách làm việc chân thành và tính tích cực.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yang Yi","avatar":""},{"name":"Pan Changjiang","avatar":""},{"name":"Nan Ji","avatar":""},{"name":"Zhang Li","avatar":""},{"name":"Jing Gangshan","avatar":""},{"name":"Gao Hailong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324339);
