INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-cung-cha-khac-me', 'Anh Em Cùng Cha Khác Mẹ', 'Half Brothers', 'https://phimimg.com/upload/vod/20231128-1/0a91f6dbb54b374512d976b5e14f3555.jpg', 'https://phimimg.com/upload/vod/20231128-1/ae7b722f9cca27f9b3727fb65a5eb2f6.jpg', '<p>Renato, một giám đốc điều hành hàng không người Mexico, bị sốc khi biết mình có một người anh cùng cha khác mẹ người Mỹ mà anh chưa từng biết, Asher có tinh thần tự do. Họ buộc phải cùng nhau trên chuyến hành trình lần theo con đường mà cha họ đã đi từ Mexico đến Mỹ.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"José Zúñiga","avatar":""},{"name":"Luis Gerardo Méndez","avatar":""},{"name":"Vincent Spano","avatar":""},{"name":"Alma Sisneros","avatar":""},{"name":"Shira Scott Astrof","avatar":""},{"name":"Connor Del Rio","avatar":""},{"name":"Howard Ferguson Jr.","avatar":""},{"name":"Hayes Hargrove","avatar":""},{"name":"Bianca Marroquín","avatar":""},{"name":"Catherine Haun","avatar":""},{"name":"Efrain Villa","avatar":""},{"name":"Beatrice Hernandez","avatar":""},{"name":"Jwaundace Candece","avatar":""},{"name":"Stephen R. Estler","avatar":""},{"name":"Juan Pablo E","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324339);
