INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-clouds-gather', 'The Clouds Gather', 'The Clouds Gather', 'https://phimimg.com/upload/vod/20231129-1/2ec14f75505f1aa679ed2a9fe4cce529.jpg', 'https://phimimg.com/upload/vod/20231129-1/b84fafed117c54b80c30b14f29cb4532.jpg', '<p>Yashiro là nhà lãnh đạo trẻ của Shinseikai và chủ tịch của Shinseikai Enterprise, nhưng giống như rất nhiều người đàn ông mạnh mẽ, anh ta dẫn đầu một cuộc sống đôi khi là một người lệch lạc và một kẻ ngốc. Doumeki Chikara đến làm việc như một vệ sĩ cho anh ta và, mặc dù Yashiro đã quyết định rằng anh ta sẽ không bao giờ đặt tay lên người đàn ông của mình, anh ta tìm thấy một thứ gì đó về Doumeki mà anh ta không thể cưỡng lại được ....</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Tarusuke Shingaki","avatar":""},{"name":"Wataru Hatano","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Yuki Ono","avatar":""},{"name":"Toru Okawa","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Akimitsu Takase","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Takuya Sato","avatar":""},{"name":"Takahiro Miyake","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324339);
