INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-quan-nac', 'Tướng Quân Nặc', 'Fall in Love With My King', 'https://phimimg.com/upload/vod/20231129-1/63a05fbba79d309dbb40937a4b87a0e7.jpg', 'https://phimimg.com/upload/vod/20231129-1/f0000abaac9e953c5c1505da3e862896.jpg', '<p>Thích khách tân nương chọc ghẹo tướng quân đẹp trai! Hách Liên nhận được chỉ thị gả cho tướng quân Mộ Dung chỉ để lấy trộm một thứ quan trọng nhất của tướng quân. Mà tướng quân Mộ Dung cũng phát hiện ra cô gái làm mình không giữ được hồn vía lại cứu thích khách trong quân doanh của mình đi, làm mình phải chịu một nỗi nhục nhã rất lớn! Lần này cuối cũng hắn cũng có cơ hội lật ngược. Hách Liên có vẻ ngoài mềm mại, lần này tướng quân phải làm thế nào để chiến thắng</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Pa Li","avatar":""},{"name":"Shag Deng","avatar":""},{"name":"LiZhiYing","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324339);
