INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-nang-trong-moi-chung-ta', 'Dị Năng - Trong Mỗi Chúng Ta', 'Freaks – You''re One of Us', 'https://phimimg.com/upload/vod/20231125-1/b3f4406be21f7629397110253aa3374c.jpg', 'https://phimimg.com/upload/vod/20231125-1/1bdd38f93bae4af3cded21731fd1b499.jpg', '<p>Được kẻ lang thang bí ẩn mách bảo, nữ đầu bếp nhu mì làm đồ chiên rán biết cô có siêu năng lực và đồng loại. Đồng thời cô cũng phát hiện âm mưu xấu xa có quy mô lớn.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Cornelia Gröschel","avatar":""},{"name":"Tim Oliver Schultz","avatar":""},{"name":"Wotan Wilke Möhring","avatar":""},{"name":"Nina Kunzendorf","avatar":""},{"name":"Frederic Linkemann","avatar":""},{"name":"Finnlay Berger","avatar":""},{"name":"Gisa Flake","avatar":""},{"name":"Ralph Herforth","avatar":""},{"name":"Thelma Buabeng","avatar":""},{"name":"Gesine Cukrowski","avatar":""},{"name":"Charlotte Banholzer","avatar":""},{"name":"Marcel Nazarov","avatar":""},{"name":"Stefan Mehren","avatar":""},{"name":"Eddy Shore","avatar":""},{"name":"Johann Fohl","avatar":""},{"name":"Dan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324340);
