INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-sau-canh-cua', 'Cậu Bé Sau Cánh Cửa', 'The Boy Behind The Door', 'https://phimimg.com/upload/vod/20231125-1/4feaf0e69a6a8b19a9248561692397bd.jpg', 'https://phimimg.com/upload/vod/20231125-1/b4880d37ac44e40686e06268bf82e1c0.jpg', '<p>Cậu Bé Sau Cánh Cửa - The Boy Behind The Door xoay quanh câu chuyện về cậu bé Bobby cùng với bạn mình là Kevin đã bị những người bí ẩn bắt cóc và đưa đến một ngôi nhà kỳ quái tại khu vực hoang dã. Sau đó bằng sự nỗ lực, Bobby đã nhanh chóng trốn thoát được ra khỏi đó, còn người bạn của mình thì vẫn bị mắc kẹt. Trong lúc chạy chưa được bao xa thì nghe tiếng kêu cứu thảm thiết của Kevin, Bobby đã nhận ra mình không thể bỏ cậu ấy ở lại được.</p>', 'Full', 1, 'single', 'completed', 8, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lonnie Chavis","avatar":""},{"name":"Ezra Dewey","avatar":""},{"name":"Kristin Bauer","avatar":""},{"name":"Scott Michael Foster","avatar":""},{"name":"Micah A. Hauptman","avatar":""},{"name":"Rich Ceraulo Ko","avatar":""},{"name":"Anna B. Shaffer","avatar":""},{"name":"Alfredo Tavares","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324340);
