INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('keo-ngot-cap-toc', 'Kẹo Ngọt Cấp Tốc', 'Sugar High', 'https://phimimg.com/upload/vod/20231125-1/74d516e1955634a9cd0af2e2cb88a616.jpg', 'https://phimimg.com/upload/vod/20231125-1/3724d5e8e86c6e1775d12ecd938adabd.jpg', '<p>Bản ăn theo đặc biệt của chương trình &quot;Bánh ngọt cấp tốc&quot; này có sự xuất hiện của các nghệ sĩ chế tác kẹo đường tài năng. Họ thi đấu để giành 10.000 USD qua hai vòng thi.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hunter March","avatar":""},{"name":"Jackie Sorkin","avatar":""},{"name":"Stéphane Tréand","avatar":""},{"name":"Rebecca DeAngelis","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324340);
