INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-100', 'Sói 100%', '100% Wolf', 'https://phimimg.com/upload/vod/20231125-1/4830546d27aa7a1f774e44ed3060fa37.jpg', 'https://phimimg.com/upload/vod/20231125-1/abba1f419b8fcee97ba5dc74a6dc0884.jpg', '<p>Phim là câu chuyện kể về Freddy Lupin - người thừa kế một gia đình sói quý tộc. Vào sinh nhật lần thứ 13 của mình, Freddy phải thực hiện nghi lễ trưởng thành và biến hình thành sói trước sự chứng kiến của các thành viên trong gia tộc. Thế nhưng, cậu lại biến thành một chú chó lông xù (Poodle). Trong lúc tuyệt vọng và nghĩ rằng cuộc đời đã chấm hết, Freddy bắt đầu một cuộc phiêu lưu mới đầy thú vị và vui nhộn; nhưng bất ngờ khám phá ra sự thật về cái chết bí ẩn của cha mình, rồi biết được một thợ săn người sói đang lên kế hoạch tiêu diệt tất cả gia đình và bạn bè cậu. Với vẻ ngoài nhỏ bé của một chú cún, liệu Freddy có ngăn chặn được âm mưu độc ác và chứng minh mình là sói 100%?</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2020, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Ilai Swindells","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"Samara Weaving","avatar":""},{"name":"Rhys Darby","avatar":""},{"name":"Jane Lynch","avatar":""},{"name":"Rupert Degas","avatar":""},{"name":"Magda Szubanski","avatar":""},{"name":"Akmal Saleh","avatar":""},{"name":"Sarah Rose Harper","avatar":""},{"name":"Michael Bourchier","avatar":""},{"name":"Kate Hall","avatar":""},{"name":"Adriane Daff","avatar":""},{"name":"Liam Graham","avatar":""},{"name":"Loren Gray","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324340);
