INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nga-quy-tieng-thet-dong-gio-hu', 'Ngạ Quỷ: Tiếng Thét Đồng Gió Hú', 'The Ghoul: Horror At The Howling Field', 'https://phimimg.com/upload/vod/20231125-1/403e1472a48d962570c96820452a5fe3.jpg', 'https://phimimg.com/upload/vod/20231125-1/b56a49ae7e2e2d913e8d959dee621037.jpg', '<p>Trung úy Satjathorn bất đắc dĩ phải nhận nhiệm vụ đi phá án tại ngôi làng TungMhaHon. Vụ án được đặc biệt quan tâm bởi có nhiều tình tiết bí hiểm, khó lý giải. Kuim – một anh nông dân người làng – tình nguyện hộ tống Satjathorn trong suốt chuyến điều tra bởi anh cũng muốn nhân cơ hội này trở về làng gặp người thương – Vhung. Ngôi làng vốn yên bình vào ban ngày lại trở nên vô cùng rùng rợn vào ban đêm. Hàng loạt tin đồn và sự kiện bất thường xảy ra với đội điều tra. Liệu cảnh sát Satjathorn có thể tìm ra sự thật và đưa tất cả thoát khỏi ngôi làng ma ám?</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Paitoon Pumrat","avatar":""},{"name":"Arthit Somnoi","avatar":""},{"name":"Apapat Suksawadchol","avatar":""},{"name":"Akom Preedakul","avatar":""},{"name":"Yuttana Puangklang","avatar":""},{"name":"Kittisuk Vechprasarn","avatar":""},{"name":"Chookiat Iamsook","avatar":""},{"name":"Chatchai Jamneankul","avatar":""},{"name":"Kittisak Wechprasan","avatar":""},{"name":"Samart Payakaroon","avatar":""},{"name":"Puang Kaewprasert","avatar":""},{"name":"Nhoi Chernyim","avatar":""},{"name":"Nakarin Gakhan","avatar":""},{"name":"Suchat Phutchant","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324340);
