INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nhau-mua-e', 'Yêu Nhau Mùa ''Ế''', 'Low Season', 'https://phimimg.com/upload/vod/20231125-1/68a0db880bb850600ba30ba05672ed3a.jpg', 'https://phimimg.com/upload/vod/20231125-1/9762869c4893beed55d2ea854b027065.jpg', '<p>Phim xoay quanh Lin, cô nàng có khả năng nhìn thấy ma quỷ. Sau khi chia tay bạn trai nam thần, cô cảm thấy mệt mỏi bởi chốn thành thị xô bồ nên quyết định… lên rừng ở ẩn. Xách ba lô đến một home stay vắng vẻ ở phía Bắc, Lin vô tình gặp gỡ chàng biên kịch gia trẻ tuổi Pud. Trải qua nhiều khoảnh khắc đáng nhớ, họ dần cảm mến nhau bất chấp sự đeo bám, phá phách của các oan hồn bản địa.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Mario Maurer","avatar":""},{"name":"Ploypailin Thangprapaporn","avatar":""},{"name":"Akarin Akaranitimaytharatt","avatar":""},{"name":"Kidakarn Chatkaewmanee","avatar":""},{"name":"Sakonrat Woraurai","avatar":""},{"name":"Morakot Liu","avatar":""},{"name":"Nakorn Silachai","avatar":""},{"name":"Supakorn Kitsuwon","avatar":""},{"name":"Sriphan Chunechomboon","avatar":""},{"name":"Nachat Juntapun","avatar":""},{"name":"Noppawan Limapirak","avatar":""},{"name":"Jirath Sriharojjanawatcharakorn","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324340);
