INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tru-niem-su', 'Tru Niệm Sư', 'Soul Hunter', 'null', 'https://phimimg.com/upload/vod/20231125-1/6c2e7fc17b92c3af7fffedcc28c5c380.jpg', '<p>Là hậu duệ danh giá của hành tinh “Huyễn Thành”, “Tru Niệm Sư” Dương Liệt Tuyết gánh trọng trách trên vai, nhưng vì mất trí nhớ, con đường Tru Niệm Sư rất không thuận lợi, sự xuất hiện của Hàn Giang Đông, khiến tình cảm và sự nghiệp của thiếu nữ ngây thơ Dương Liệt Tuyết nở rộ, lúc này, bà cố xuất hiện ngăn cản, chuyện cũ ngàn năm được phơi bày. Dương Liệt Tuyết có chấn hưng lại được danh tiếng của gia tộc, quay về hành tinh mẹ thành công hay không?</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lai Jing","avatar":""},{"name":"Sun Yijie","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324340);
