INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-end-of-the-storm', 'The End of the Storm', 'The End of the Storm', 'https://phimimg.com/upload/vod/20231125-1/9e5eaa990c889730bd7674608ac64ea8.jpg', 'https://phimimg.com/upload/vod/20231125-1/7408351fefabeece8d1eff693948d347.jpg', '<p>Với quyền truy cập chưa từng có vào Câu lạc bộ bóng đá Liverpool, kết thúc cơn bão là độ dài tính năng hấp dẫn trong câu chuyện của mùa giải 2019/20 Premier League.</p>', 'Full', 1, 'single', 'completed', 6, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jürgen Klopp","avatar":""},{"name":"Jordan Henderson","avatar":""},{"name":"Sadio Mané","avatar":""},{"name":"Roberto Firmino","avatar":""},{"name":"Alisson Becker","avatar":""},{"name":"Virgil van Dijk","avatar":""},{"name":"Trent Alexander-Arnold","avatar":""},{"name":"Kenny Dalglish","avatar":""},{"name":"Alex Oxlade-Chamberlain","avatar":""},{"name":"James Milner","avatar":""},{"name":"Adrián","avatar":""},{"name":"Fabinho","avatar":""},{"name":"Georginio Wijnaldum","avatar":""},{"name":"Naby Keïta","avatar":""},{"name":"Caoimhín Kelleher","avatar":""},{"name":"Simon Mignole","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324340);
