INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-thu-sao-hoa', 'Quái Thú Sao Hỏa', 'Cosmoball', 'https://phimimg.com/upload/vod/20231125-1/73eb9a3fea867662d32fe016ad044cf4.jpg', 'https://phimimg.com/upload/vod/20231125-1/e0a5d721a6048b976a9a29d7311e3776.jpg', '<p>Quái thú sao hỏa - Cosmoball : Bộ phim lấy bối cảnh tương lai, hậu khải huyền ở một thành phố tại trái đất, khi mà cuộc chiến tranh giữa các thiên hà đã làm cho nơi này trở thành khô cằn và đầy bệnh dịch. Để cứu lấy trái đất, thủ lĩnh của hội Nghiên cứu của hội đồng ngân hà đã tạo một con tàu khổng lồ với hình dáng của một cây hoa bồ công anh, bên trong là một sân vận động lớn, để tổ chức các giải đấu Cosmoball, để chuẩn bị cho cuộc chiến với kẻ tội phạm nguy hiểm nhất dải ngân hà. Và những vận động viên cuối cùng cũng sẽ là những người bảo vệ cho người dân trái đất khi chẳng may chiến tranh nổ ra. Số phận của trái đất cũng phụ thuộc vào cuộc chiến cuối cùng này</p>', 'Full', 1, 'single', 'completed', 16, 2020, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Evgeny Romantsov","avatar":""},{"name":"Victoria Agalakova","avatar":""},{"name":"Mariya Lisovaya","avatar":""},{"name":"Evgeny Mironov","avatar":""},{"name":"Ivan Ivanovich","avatar":""},{"name":"Elizaveta Taychenacheva","avatar":""},{"name":"Hristina Blokhina","avatar":""},{"name":"Valeriya Bukina","avatar":""},{"name":"Elena Yakovleva","avatar":""},{"name":"Mikhail Efremov","avatar":""},{"name":"Mikhail Stenin","avatar":""},{"name":"Dmitri Nazarov","avatar":""},{"name":"Soslan Fidarov","avatar":""},{"name":"Wolfgang Cerny","avatar":""},{"name":"Svetlana","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324340);
