INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hao-kiet-hoa-moc-lan', 'Nữ Hào Kiệt Hoa Mộc Lan', 'Mulan the Heroine', 'https://phimimg.com/upload/vod/20231125-1/69aa4541bc0da558eea43ca308612d55.jpg', 'https://phimimg.com/upload/vod/20231125-1/64d07eb3df0cad01aad3d6018230fee1.jpg', '<p>Trong triều đại Bắc Ngụy, Mulan gia nhập quân đội cho cha mình và trở về trong danh dự. Mười năm sau, Rouran lại phá biên giới, Mộc Lan kiên quyết trở lại chiến trường. Để cứu Tuoba, Mulan đã rơi vào tay kẻ thù. Trong tù, Mulan đã nhìn thấu những mánh khóe của Kunpeng. Kunpeng giết Khan và đổ tội cho Mulan. Mulan chiến đấu với Kunpeng để bảo vệ những người vô tội. Công chúa chỉ ra rằng kẻ sát nhân thực sự là Kunpeng. Kunpeng bị giết trong trận hỗn chiến. Sự hỗn loạn lắng xuống. Bộ phim tôn vinh hòa bình và hòa hợp dân tộc, đồng thời cho thấy Mulan, với tư cách là một phụ nữ, không bỏ rơi đồng bào, không bỏ tổ quốc và không ngừng nỗ lực vì phẩm chất xuất sắc và tình cảm gia đình.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Yongxi","avatar":""},{"name":"Jason Fu","avatar":""},{"name":"Liu Julin","avatar":""},{"name":"Yu Kaining","avatar":""},{"name":"Li Mingxuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324340);
