INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-painter-and-the-thief', 'The Painter and the Thief', 'The Painter and the Thief', 'https://phimimg.com/upload/vod/20231206-1/122218bf2d5bcf5e26decdea4d1edffa.jpg', 'https://phimimg.com/upload/vod/20231206-1/f4b4dd2432122a93b71f4e6612bbab22.jpg', '<p>Một nghệ sĩ kết bạn với kẻ trộm đã đánh cắp những bức tranh của mình. Cô trở thành đồng minh gần nhất của mình khi anh bị tổn thương nặng nề trong vụ tai nạn xe hơi và cần được chăm sóc toàn thời gian, ngay cả khi không tìm thấy bức tranh của cô. Nhưng sau đó các bảng chuyển sang.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324340);
