INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-quyen-2020', 'Nữ Quyền', 'The Glorias', 'https://phimimg.com/upload/vod/20231124-1/5bfdf70e708446b679822534ab3e500f.jpg', 'https://phimimg.com/upload/vod/20231124-1/820718024b54ce5fb434ef655f6d57ca.jpg', '<p>Câu chuyện về biểu tượng nữ quyền ảnh hưởng thời thơ ấu của Gloria Steinem đã ảnh hưởng lớn đến cuộc đời của cô với tư cách là một nhà văn, nhà hoạt động và nhà tổ chức cho quyền phụ nữ trên toàn thế giới.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julianne Moore","avatar":""},{"name":"Alicia Vikander","avatar":""},{"name":"Lulu Wilson","avatar":""},{"name":"Ryan Kiera Armstrong","avatar":""},{"name":"Timothy Hutton","avatar":""},{"name":"Janelle Monáe","avatar":""},{"name":"Enid Graham","avatar":""},{"name":"Bette Midler","avatar":""},{"name":"Gloria Steinem","avatar":""},{"name":"Peggy Sheffield","avatar":""},{"name":"Tom Proctor","avatar":""},{"name":"Korbi Dean","avatar":""},{"name":"Shalkh Sheeba","avatar":""},{"name":"Hasina Shalkh","avatar":""},{"name":"John Adden","avatar":""},{"name":"Farookh Shalkh","avatar":""},{"name":"Olivia Jordan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324340);
