INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-bong-chay', 'Cô Gái Bóng Chày', 'Baseball Girl', 'https://phimimg.com/upload/vod/20231124-1/2f5ea7ba7997a82069c68817d2813135.jpg', 'https://phimimg.com/upload/vod/20231124-1/cf5677d40a804fc93697fe1217ff7f7c.jpg', '<p>“Cô Gái Bóng Chày” là một bộ phim của đài tvN, kể về câu chuyện của một nữ sinh trung học phá bỏ thông lệ rằng nữ giới không thể trở thành cầu thủ bóng chày chuyên nghiệp để có thể thực hiện ước mơ của mình và trở thành nữ cầu thủ bóng chày chuyên nghiệp đầu tiên của Hàn Quốc.Trong phim, Kwak Dong Yeon vào vai nam chính, cùng lớn lên bên cạnh nữ chính, trở thành vận động viên bóng chày chuyên nghiệp từ sớm, vừa là bạn vừa là đối thủ cạnh tranh của nữ chính.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Joo-young","avatar":""},{"name":"Lee Jun-hyuk","avatar":""},{"name":"Yeom Hye-ran","avatar":""},{"name":"Song Young-gyu","avatar":""},{"name":"Kwak Dong-yeon","avatar":""},{"name":"Joo Hae-eun","avatar":""},{"name":"Yoo Jae-myung","avatar":""},{"name":"Jang Jun-whee","avatar":""},{"name":"Kim Min-seo","avatar":""},{"name":"Lee Sang-hee","avatar":""},{"name":"Lim Ho-jun","avatar":""},{"name":"Kim Jong-soo","avatar":""},{"name":"Lee Chae-eun","avatar":""},{"name":"Seo Jin-won","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324340);
