INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-thanh-am-khong-ghi-nho', 'Nếu Thanh Âm Không Ghi Nhớ', 'The End of Endless Love', 'https://phimimg.com/upload/vod/20231124-1/6a848eb6805c1586422749ea3258167f.jpg', 'https://phimimg.com/upload/vod/20231124-1/8873a3cefa29efa9ed86d8a563722294.jpg', '<p>Bộ phim kể về câu chuyện tình giữa chàng trai nhút nhát và cô gái mang chứng trầm cảm. Tân Đường có khả năng điều khiển âm thanh. Khi anh đang quét mộ cho cha mẹ, anh đã tình cờ gặp Cát Trạch, một cô gái đang lứa tuổi học sinh và có vẻ không mấy thân thiện với những hành vi của cô ở nghĩa trang. Đổi lại thì Cát Trạch cũng không hề ưa sự thờ ơ và lạnh Lùng của Tân Đường. Thông qua các tình tiết nhỏ nhặt, hai con người không nhìn thấy mặt của nhau cuối cùng lại có mối liên kết không thể phá vỡ.</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Ruonan","avatar":""},{"name":"Sun Chenjun","avatar":""},{"name":"Wang Yanlin","avatar":""},{"name":"Kevin Yan","avatar":""},{"name":"Zhang Dabao","avatar":""},{"name":"Guo Shutong","avatar":""},{"name":"Anson Shi","avatar":""},{"name":"Zuo Xiaoqing","avatar":""},{"name":"Sun Letian","avatar":""},{"name":"Zhang Yao","avatar":""},{"name":"Yunlai Xin","avatar":""},{"name":"Wang Jia Hui","avatar":""},{"name":"Lui Shuai","avatar":""},{"name":"Janice Wu","avatar":""},{"name":"Yu Wei Ni","avatar":""},{"name":"Vicky Li","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324340);
