INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-kien-chinh', 'Sự Kiện Chính', 'The Main Event', 'https://phimimg.com/upload/vod/20231124-1/bccea6337df04d60edfbe2cda1bf0ede.jpg', 'https://phimimg.com/upload/vod/20231124-1/ebf0bf883d0512c6c0ff9a9cb04953e2.jpg', '<p>Sử dụng sức mạnh đặc biệt từ chiếc mặt nạ ma thuật, cậu bé hâm mộ WWE gây bao náo loạn khi tham gia cuộc thi đấu vật và chạm trán một đối thủ đáng sợ.Sử dụng sức mạnh đặc biệt từ chiếc mặt nạ ma thuật, cậu bé hâm mộ WWE gây bao náo loạn khi tham gia cuộc thi đấu vật và chạm trán một đối thủ đáng sợ.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Seth Carr","avatar":""},{"name":"Tichina Arnold","avatar":""},{"name":"Adam Pally","avatar":""},{"name":"Ken Marino","avatar":""},{"name":"Mike Mizanin","avatar":""},{"name":"Momona Tamada","avatar":""},{"name":"Keith Lee","avatar":""},{"name":"Babatunde Łukasz Aiyegbusi","avatar":""},{"name":"Kofi Sarkodie-Mensah","avatar":""},{"name":"Stephen Farrelly","avatar":""},{"name":"Matt Polinsky","avatar":""},{"name":"Lucie Guest","avatar":""},{"name":"Lisa Durupt","avatar":""},{"name":"Donna Benedicto","avatar":""},{"name":"Paul Lazenby","avatar":""},{"name":"Bodhi Sabongui","avatar":""},{"name":"Dallas D","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324340);
