INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('not-cao', 'Nốt Cao', 'The High Note', 'https://phimimg.com/upload/vod/20231124-1/fb5e5c5eb4260ce9b015954df2d87e65.jpg', 'https://phimimg.com/upload/vod/20231124-1/5fde3ad54edd2ea982d58709190f9965.jpg', '<p>Lấy bối cảnh trong thế giới rực rỡ của nền âm nhạc LA, câu chuyện về Grace Davis, một siêu sao có tài năng và bản ngã đã đạt đến những đỉnh cao khó tin. Maggie là trợ lý cá nhân làm việc quá sức của Grace, người bế tắc với công việc lặt vặt nhưng vẫn nuôi ước mơ thời thơ ấu là trở thành nhà sản xuất âm nhạc. Khi người quản lý của Grace đưa ra cho cô ấy một lựa chọn có thể thay đổi sự nghiệp của cô ấy, Maggie và Grace đưa ra một kế hoạch có thể thay đổi cuộc sống của họ mãi mãi.</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Dakota Johnson","avatar":""},{"name":"Tracee Ellis Ross","avatar":""},{"name":"Kelvin Harrison Jr.","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Zoe Chao","avatar":""},{"name":"June Diane Raphael","avatar":""},{"name":"Eugene Cordero","avatar":""},{"name":"Marc Evan Jackson","avatar":""},{"name":"Eddie Izzard","avatar":""},{"name":"Ice Cube","avatar":""},{"name":"Jonathan Freeman","avatar":""},{"name":"Parvesh Cheena","avatar":""},{"name":"Bianca Lopez","avatar":""},{"name":"Neil Lane","avatar":""},{"name":"Tiffany Elle","avatar":""},{"name":"Danielle Barbosa","avatar":""},{"name":"Edras","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324