INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chen-thanh-cam-nhan-thien-duong-3-khuc-xuan-ca', 'Chén Thánh: Cảm Nhận Thiên Đường 3 - Khúc Xuân Ca', 'Fate/stay night Movie: Heaven''s Feel 3', 'https://phimimg.com/upload/vod/20231124-1/b504116bf66393ac61d1f1e1911a2d61.jpg', 'https://phimimg.com/upload/vod/20231124-1/9a3bca10c9fc8f577b1b2b4039f24044.jpg', '<p>Một cuộc chiến không có chỗ cho kẻ nhu nhược, một cuộc chiến mà kẻ chiến thắng chỉ có một. Một cuộc chiến mà phần thưởng đạt được sẽ là thánh vật có khả năng thực hiện mọi điều ước.
