INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tat-ca-vi-roona', 'Tất cả vì Roona', 'Rooting for Roona', 'https://phimimg.com/upload/vod/20231121-1/12bc232cabfcf6ab2af15b30f3840113.jpg', 'https://phimimg.com/upload/vod/20231121-1/e8f77ed81152b137ee7116c7ab7c6a04.jpg', '<p>Ở vùng quê Ấn Độ, đứa trẻ mắc chứng não úng thủy có cơ hội phẫu thuật và thay đổi cuộc đời khi ảnh của em lan truyền khắp nơi. Phim tài liệu này theo dấu hành trình ấy.</p>', 'Full', 1, 'single', 'completed', 17, 2020, 'Vietsub', 'HD', 'Ấn Độ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324340);
