INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-bang-hy-vong-co-hoi-song-lan-hai', 'Đóng băng hy vọng: Cơ hội sống lần hai', 'Hope Frozen: A Quest to Live Twice', 'https://phimimg.com/upload/vod/20231121-1/e6e7200418faaa11b4b16e34163a664d.jpg', 'https://phimimg.com/upload/vod/20231121-1/ff4a3cace262542ef370d11a7e48b884.jpg', '<p>Một nhà khoa học Phật giáo đến từ Bangkok quyết định bảo quản lạnh bộ não của con gái mình. Khi vụ bê bối xoay quanh gia đình, họ đấu tranh để đau buồn cho một đứa trẻ mà theo quan điểm của họ, bị treo lơ lửng giữa cái chết và sự thức tỉnh trong tương lai.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Nareerat Naovaratpong","avatar":""},{"name":"Sahatorn Naovaratpong","avatar":""},{"name":"Matrix Naovaratpong","avatar":""},{"name":"Max More","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324340);
