INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-tai-ban-tia', 'Thiên Tài Bắn Tỉa', 'Genius Sniper', 'null', 'https://phimimg.com/upload/vod/20231120-1/a74ead52f79635353efe5e9b5cff1ba0.jpg', '<p>Câu chuyện kể về năm thanh niên có ước mơ tham gia thi đấu game bắn tỉa quân sự. Trong cuộc sống hiện thực và trong các trận thi đấu game, nhờ sự đoàn kết, giúp đỡ lẫn nhau, họ đã bứt phá được những gian nan, trở ngại. Cuối cùng nhận được sự tôn trọng của mọi người, thực hiện được lý tưởng của mình.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yang Yi","avatar":""},{"name":"Wang Shuaibo","avatar":""},{"name":"Zhao Zhiyao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '[]', 1784690324340);
