INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-cong-can-man', 'Vũ Công Cần Mẫn', 'Work It', 'https://phimimg.com/upload/vod/20231120-1/42ee8173fe04c714730afe42296c1bb6.jpg', 'https://phimimg.com/upload/vod/20231120-1/f8bfa2a3c1912505ab367d3b91ef1600.jpg', '<p>Một học sinh cuối cấp ba thông minh nhưng hậu đậu thề sẽ vào được trường học của người cha quá cố bằng cách biến bản thân và một nhóm lập dị thành nhóm nhảy vô địch.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sabrina Carpenter","avatar":""},{"name":"Liza Koshy","avatar":""},{"name":"Keiynan Lonsdale","avatar":""},{"name":"Michelle Buteau","avatar":""},{"name":"Jordan Fisher","avatar":""},{"name":"Drew Ray Tanner","avatar":""},{"name":"Jayne Eastwood","avatar":""},{"name":"Naomi Snieckus","avatar":""},{"name":"Briana Andrade-Gomes","avatar":""},{"name":"Kalliane Bremault","avatar":""},{"name":"Bianca Asilo","avatar":""},{"name":"Neil Robles","avatar":""},{"name":"Nathaniel Scarlette","avatar":""},{"name":"Tyler Hutchings","avatar":""},{"name":"Indiana Mehta","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324340);
