INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('blackpink-thap-sang-bau-troi', 'Blackpink: Thắp Sáng Bầu Trời', 'Blackpink: Light Up the Sky', 'https://phimimg.com/upload/vod/20231120-1/6c7bb633d536922d9336df62b3a3d3bb.jpg', 'https://phimimg.com/upload/vod/20231120-1/7be1b9056915b0c2837d5eb2e31f1e4b.jpg', '<p>Phim tài liệu về BLACKPINK xoay quanh 4 năm hoạt động của các thành viên trong nhóm kể từ khi nhóm ra mắt vào năm 2016. Phim kể chi tiết lại những khó khăn, thử thách mà cả 4 thành viên đã trải qua trong khoảng thời gian còn làm thực tập sinh của YG Entertainment cho tới thời điểm bùng nổ trên toàn cầu. Phim cũng sẽ tiết lộ những bí mật chưa từng được bật mí trong suốt khoảng thời gian hoạt động của nhóm, những khoảnh khắc sau ánh đèn sân khấu và nhiều câu chuyện khác nữa.Ngoài ra, màn biểu diễn đi vào lịch sử của BLACKPINK tại festival âm nhạc Coachella hồi 2019 cũng được kể lại. BLACKPINK là nhóm nhạc nữ Hàn Quốc đầu tiên được mời tới trình diễn tại sự kiện âm nhạc hàng đầu nước Mỹ.</p>', 'Full', 1, 'single', 'completed', 17, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kim Jisoo","avatar":""},{"name":"Jennie Kim","avatar":""},{"name":"Roseanne Park","avatar":""},{"name":"Lisa","avatar":""},{"name":"Teddy Park","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324340);
