INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-rong-o-dung-tuyen', 'Tìm rồng ở Dũng Tuyền', 'Sanxingdui Glory Awakening 4', 'https://phimimg.com/upload/vod/20231203-1/a8f69addcd7ce679e0882725cc269ff6.jpg', 'https://phimimg.com/upload/vod/20231203-1/cbcbf37d4422cedf3074a02a84b5e0bf.jpg', '<p>Bộ phim kể về cuộc phiêu lưu của Vân Hạo, một học sinh thông minh sáng dạ. Qua chuyến viếng thăm Bảo tàng Tam Tinh Đôi, Vân Hạo gặp Cái Kỳ, một người máy cổ đại có mối liên hệ thần giao cách cảm với Vân Hạo; và Thiên Mã, một con ngựa nhỏ biết nói và bay. Bộ ba kỳ quặc này có một nhiệm vụ phải hoàn thành: cứu lấy tương lai của loài người. Nếu cậu thất bại, cả thế giới sẽ sụp đổ.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324340);
