INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-toa-sang', 'Cô gái tỏa sáng', 'The Shining Girl', 'https://phimimg.com/upload/vod/20231123-1/7c2f302e4d64b3f1bcf41488a3f3e29b.jpg', 'https://phimimg.com/upload/vod/20231123-1/8dd4d7ade036dbc0fb9572f234e0c41e.jpg', '<p>Lan Yu là một ngôi sao nổi tiếng nhưng kiêu ngạo. Một ngày nọ, anh vô tình gặp Yu Zai, một cô gái bình thường. Cảm động trước sự chính trực và tốt bụng của cô gái, Lan Yu quyết tâm thay đổi. Bằng sự chăm chỉ, anh đã lột xác từ một ngôi sao gây tranh cãi trở thành một diễn viên giỏi với nghị lực và sự cống hiến, được mọi người trong và ngoài ngành kính trọng. Đồng thời, anh nảy sinh tình cảm chân thành với Yu Zai.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Shangyu","avatar":""},{"name":"Li Mengying","avatar":""},{"name":"Essie Lin Chia","avatar":""},{"name":"Feng Jian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324340);
