INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-dissident', 'The Dissident', 'The Dissident', 'https://phimimg.com/upload/vod/20231201-1/05705781a23ed80fdf479b308cfabd6d.jpg', 'https://phimimg.com/upload/vod/20231201-1/0aae600a3015b7eecf89df3bc52090c3.jpg', '<p>Khi Washington Post Nhà báo Jamal Khashoggi biến mất ở Istanbul, vị hôn thê và những người bất đồng chính kiến của mình trên toàn thế giới cùng nhau manh mối để giết người và phơi bày toàn cầu che đậy</p>', 'Full', 1, 'single', 'completed', 23, 2020, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Jamal Khashoggi","avatar":""},{"name":"Omar Abdulaziz","avatar":""},{"name":"Prince Mohammed bin Salman al Saud","avatar":""},{"name":"İrfan Fidan","avatar":""},{"name":"Agnès Callamard","avatar":""},{"name":"Hatice Cengiz","avatar":""},{"name":"John O. Brennan","avatar":""},{"name":"Fahrettin Altun","avatar":""},{"name":"Anthony J. Ferrante","avatar":""},{"name":"Abdulhamit Gul","avatar":""},{"name":"Donald Trump","avatar":""},{"name":"Bob Corker","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324340);
