INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-dissident', 'The Dissident', 'The Dissident', 'the dissident the dissident jamal khashoggi omar abdulaziz prince mohammed bin salman al saud i̇rfan fidan agnès callamard hatice cengiz john o. brennan fahrettin altun anthony j. ferrante abdulhamit gul donald trump bob corker ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phap-y-tong-tu', 'Pháp Y Tống Từ', 'Forensic Medicine Song Ci', 'https://phimimg.com/upload/vod/20231120-1/3a344dbec844f3c0b967fc72b09964ba.jpg', 'https://phimimg.com/upload/vod/20231120-1/935cbe72de5af7ffd0f81e8d20ccf57c.jpg', '<p>Tống triều, Tống Từ đến huyện Trường Đinh nhậm chức, chuyên tâm nghiên cứu phương pháp khám nghiệm thi thể chỉ vì viết một quyển sách &quot;Rửa Oan Tập Lục&quot;. Bỗng một đêm, có một nam một nữ mất mạng khiến toàn huyện khiếp sợ. Sau khi Tống Từ biết lập tức tham gia điều tra, sau khi khám nghiệm thi thể Tống Từ phát hiện có điều kỳ lạ, đây không đơn giản là vụ án giết người. Đang lúc bế tắc, Tống Từ nghĩ đến nữ ba năm rồi chưa dám gặp là Đan Thanh, huyện Trường Đinh không có việc Đan Thanh không biết. Vì vậy, Tống Từ đích thân đi tìm những mối liên kết của hai vụ án mạng, cũng xin Đan Thanh giúp đỡ điều tra án. Trải qua nhiều phen thăm dò khám phá, rốt cuộc chân tướng cũng lộ ra...</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yu Zhen","avatar":""},{"name":"Mengyuan Xu","avatar":""},{"name":"Pan Changjiang","avatar":""},{"name":"Hu Haofan","avatar":""},{"name":"Zhou Zhonghe","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324340);
