INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anelka-hieu-lam', 'Anelka: Hiểu lầm', 'Anelka: Misunderstood', 'https://phimimg.com/upload/vod/20231120-1/accbd3493134ea7fc3803b6c884f5c63.jpg', 'https://phimimg.com/upload/vod/20231120-1/5ceb3a8ba39802b95ed445d8c01d6506.jpg', '<p>Không thể nhìn thấu, không ai sánh bằng hay cả hai? Cùng khám phá di sản gây tranh cãi của cầu thủ Pháp đình đám Nicolas Anelka qua phim tài liệu chuyên sâu này.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Nicolas Anelka","avatar":""},{"name":"Thierry Henry","avatar":""},{"name":"Omar Sy","avatar":""},{"name":"Arsène Wenger","avatar":""},{"name":"Didier Drogba","avatar":""},{"name":"Emmanuel Petit","avatar":""},{"name":"Patrick Vieira","avatar":""},{"name":"Patrice Evra","avatar":""},{"name":"William Gallas","avatar":""},{"name":"François Hollande","avatar":""},{"name":"Robert Pirès","avatar":""},{"name":"Michel Platini","avatar":""},{"name":"Paul Pogba","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324340);
