INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('given-khoi-day-dam-me-ban-dien-anh', 'GIVEN: Khơi Dậy Đam Mê (Bản Điện Ảnh)', 'Given The Movie', 'https://phimimg.com/upload/vod/20231120-1/1046c62e8e0b54338a67eedc696f16c4.jpg', 'https://phimimg.com/upload/vod/20231120-1/b446a9c7515ee357359cab13de45308c.jpg', '<p>Ban nhạc &quot;GIVEN&quot; — gồm Ritsuka Uenoyama, Mafuyu Satou, Haruki Nakayama và Akihiko Kaji — đã tiến đến buổi chiếu cuối cùng của Cuộc thi nghiệp dư Countdown-fes, trong đó họ sẽ được đánh giá về phần diễn trực tiếp của họ. Dù rất nhiệt tình nhưng họ lo lắng về việc chỉ có một bài hát gốc để biểu diễn. Mafuyu ấp ủ ý tưởng học thêm về âm nhạc để tạo ra những ca khúc mới, mang âm hưởng cảm xúc. Về vấn đề này, anh ấy bất ngờ nhận được sự giúp đỡ từ Ugetsu Murata, người tình không rời của Akihiko. Ugetsu đã không thành công khi cố gắng rời xa Akihiko, người mà bản thân bị giằng xé giữa tình cảm kéo dài trong quá khứ của mình và một quyết tâm không chắc chắn cho tương lai.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takuya Eguchi","avatar":""},{"name":"Masatomo Nakazawa","avatar":""},{"name":"Shogo Yano","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Shintaro Asanuma","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324340);
