INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-len-mach-dat', 'Hôn Lên Mạch Đất', 'Kiss the Ground', 'https://phimimg.com/upload/vod/20231120-1/6e066d8c33c0034f4cc7550e3e3c12fa.jpg', 'https://phimimg.com/upload/vod/20231120-1/a21f2ccedf93c4957e9c418798545e4a.jpg', '<p>Các chuyên gia khoa học và nhà hoạt động xã hội nổi tiếng giải mã những cách mà đất trên Trái Đất có thể là chìa khóa để chống lại biến đổi khí hậu và bảo tồn hành tinh.</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Woody Harrelson","avatar":""},{"name":"David Arquette","avatar":""},{"name":"Gisele Bündchen","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Jason Mraz","avatar":""},{"name":"Ian Somerhalder","avatar":""},{"name":"Patricia Arquette","avatar":""},{"name":"Tom Brady","avatar":""},{"name":"Stéphane Le Foll","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324340);
