INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhu-con-mua-roi-tren-mat-dat', 'Như cơn mưa rơi trên mặt đất', 'Love Like the Falling Rain', 'https://phimimg.com/upload/vod/20231120-1/bd910504be6d624bce055e817dd9839a.jpg', 'https://phimimg.com/upload/vod/20231120-1/9cf6aefa5a1c03286a810c0ac092e319.jpg', '<p>Sợ bị từ chối, một chàng trai trẻ chật vật chứng minh tình cảm của mình với cô bạn thân – người sớm phải lòng một chàng trai khác. Nhưng rồi một sự cố định mệnh xảy ra.</p>', 'Full', 1, 'single', 'completed', 17, 2020, 'Vietsub', 'HD', 'Indonesia', 0, '[{"name":"Jefri Nichol","avatar":""},{"name":"Aurora Ribero","avatar":""},{"name":"Axel Matthew Thomas","avatar":""},{"name":"Nadya Arina","avatar":""},{"name":"Karina Suwandi","avatar":""},{"name":"Rebecca Klopper","avatar":""},{"name":"Aida Nurmala","avatar":""},{"name":"Pascal Azhar","avatar":""},{"name":"Tina Astari","avatar":""},{"name":"Indra Aksa","avatar":""},{"name":"Harris Soedarto","avatar":""},{"name":"Jauhar Robert","avatar":""},{"name":"Gerald Abdullah","avatar":""},{"name":"Richard Oh","avatar":""},{"name":"Kelly Tandiono","avatar":""},{"name":"Faishal Tanjung","avatar":""},{"name":"Asyraf Jamal","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324340);
