INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhu-con-mua-roi-tren-mat-dat', 'Như cơn mưa rơi trên mặt đất', 'Love Like the Falling Rain', 'như cơn mưa rơi trên mặt đất love like the falling rain jefri nichol aurora ribero axel matthew thomas nadya arina karina suwandi rebecca klopper aida nurmala pascal azhar tina astari indra aksa harris soedarto jauhar robert gerald abdullah richard oh kelly tandiono faishal tanjung asyraf jamal ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-tro-thanh-sieu-anh-hung', 'Hành Trình Trở Thành Siêu Anh Hùng', 'How I Became a Superhero', 'https://phimimg.com/upload/vod/20231120-1/ea73c36035902e4e4d468a6e07fe4b04.jpg', 'https://phimimg.com/upload/vod/20231120-1/7244a7aef3fd84705728638ae5b6ed16.jpg', '<p>Bộ phim lấy bối cảnh Paris năm 2021, các siêu anh hùng hoà nhập vào xã hội. Trong thế giới này, nơi một số người có quyền lực và những người khác thì không, ai đó đã có thể thay đổi điều này. Bằng cách tổng hợp sức mạnh siêu nhiên nhiên trong máu của một siêu anh hùng, nó có thể điều chế thành một loại thuốc. &nbsp;Loại thuốc này có thể mang lại sức mạnh tương tự của siêu anh hùng cho ai ăn nó, nhưng chỉ có hiệu lực trong thời gian ngắn. Khi những sự cố liên tục tăng lên, Lts. Moreau và Schaltzmann được cử đi điều tra vụ việc. Cùng Monte Carlo và Callista, hai người thực sự cảnh giác và họ phát hiện ra nhiều điểm đáng nghi đằng sau chất gây nghiện. &nbsp;Loại thuốc được sử dụng rộng rãi cho nhiều mục đích khác nhau, chủ yếu là để làm tổn thương người khác hoặc để phạm tội. Những người bị bắt nạt trong nhiều năm là đối tượng mà những kẻ xấu nhắm tới, việc họ khao khát được chống trả những kẻ bắt nạt luôn mạnh mẽ hơn bao giờ hết.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Pio Marmaï","avatar":""},{"name":"Vimala Pons","avatar":""},{"name":"Benoît Poelvoorde","avatar":""},{"name":"Leïla Bekhti","avatar":""},{"name":"Swann Arlaud","avatar":""},{"name":"Gilles Cohen","avatar":""},{"name":"Léonie Souchaud","avatar":""},{"name":"Camille Japy","avatar":""},{"name":"Louis Peres","avatar":""},{"name":"Théo Christine","avatar":""},{"name":"Clovis Cornillac","avatar":""},{"name":"Rafaël Guez","avatar":""},{"name":"Cartman","avatar":""},{"name":"Cyril Gueï","avatar":""},{"name":"Valentin Du Peuty","avatar":""},{"name":"Vincent Haquin","avatar":""},{"name":"Mehdi Boudina","avatar":""},{"name":"Antoine","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324340);
