INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wife-of-a-spy', 'Wife of a Spy', 'Wife of a Spy', 'https://phimimg.com/upload/vod/20231116-1/555da8b8c2466692c9fd07f004aaf23a.jpg', 'https://phimimg.com/upload/vod/20231116-1/a167976a7e82dbbbea95a9acf655f45b.jpg', '<p>Một thương gia Nhật Bản để vợ về phía sau để đi du lịch đến Mãn Châu, nơi anh ta chứng kiến một hành động man rợ. Những hành động tiếp theo của ông gây ra sự hiểu lầm, ghen tuông và các vấn đề pháp lý cho vợ.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yu Aoi","avatar":""},{"name":"Issey Takahashi","avatar":""},{"name":"Masahiro Higashide","avatar":""},{"name":"Ryota Bando","avatar":""},{"name":"Yuri Tsunematsu","avatar":""},{"name":"Hyunri","avatar":""},{"name":"Takashi Sasano","avatar":""},{"name":"Sakichi Sato","avatar":""},{"name":"Chuck Johnson","avatar":""},{"name":"Maki Nishiyama","avatar":""},{"name":"Minosuke","avatar":""},{"name":"Nihi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324340);
