INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-tri-tham', 'Lỗ Trí Thâm', 'A Monk''s Madness', 'https://phimimg.com/upload/vod/20231120-1/5646d13ab673d5fce7b6c09b9224f0c0.jpg', 'https://phimimg.com/upload/vod/20231120-1/cd45c4c11bc878c964d31661219855e8.jpg', '<p>Vào thời Bắc Tống, Hoa Hòa Thượng Lỗ Trí Thâm ba đấm đánh chết Trấn Quan Tây, chạy đến Văn Thù Viện ở Ngũ Đài Sơn để thế phát làm tăng. Vì không kiểm soát được sát niệm, bị trưởng lão sắp xếp đến Đông Kinh Biện Lương tu đạo ở Tướng Quốc Tự. Trên đường đi, Lỗ trí Thâm gặp chuyện bất bình ra tay, nội tâm cũng day dứt vì sát nghiệt đã tạo, nhưng vì quan tặc cấu kết làm bao tội ác, cuối cùng dưới ngọn lửa phẫn nộ cầm thiền trượng đặt chân vào ma đạo.</p>', 'Full', 1, 'single', 'completed', 17, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jin Song","avatar":""},{"name":"Li Yanan","avatar":""},{"name":"Xin Xin","avatar":""},{"name":"Zheng Qian","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324340);
