INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thang-may-2020', 'Thang Máy', 'The Lift', 'https://phimimg.com/upload/vod/20230919-1/e6b7b83463b5a95bc7cad8dff7ecadd0.jpg', 'https://phimimg.com/upload/vod/20230919-1/5bdbb91057fd5fba1d98c2c46e2f2899.jpg', '<p><span style="font-family: ">Thang Máy là câu chuyện kỳ bí xảy ra với những cô gái trẻ khi đi Thang Máy một mình. Mọi chuyện bắt đầu khi Jina đột nhiên mất tích sau khi livestream trong thang máy. Sự cố này gây ra nỗi sợ hãi tâm lý trong tâm trí Trang đến mức cô bị ám ảnh không thể bước vào thang máy ở bất cứ đâu. Cho đến khi người bạn thứ hai - Ngọc - cũng mất tích khi đang livestream trong chính cái thang máy của khu bệnh viện cũ kỹ.</span></p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Yu Duong","avatar":""},{"name":"Thi Kieu Trinh Nguyen","avatar":""},{"name":"Mai Bích Trâm","avatar":""},{"name":"Xuân Hiệp","avatar":""},{"name":"Neko Bao Tien","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324340);
