INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-tre-hua-hen', 'Cô Gái Trẻ Hứa Hẹn', 'Promising Young Woman', 'https://phimimg.com/upload/vod/20231118-1/65b46249265e0d958472843dd50c1693.jpg', 'https://phimimg.com/upload/vod/20231118-1/ac0664db4f51a4b70b19a589d18376c8.jpg', '<p>Cô Gái Trẻ Hứa Hẹn xoay quanh cô gái trẻ Cassie với tương lai đầy hứa hẹn đang đón chờ. Nhưng mọi chuyện bỗng chốc tan tành khi Cassie bất ngờ gặp phải một tai nạn bí ẩn. Cô gái xinh đẹp, trẻ trung và cực kì thông minh này bắt đầu lên kế hoạch trả thù cuộc đời về đêm bằng những phương cách không ai tưởng tượng nổi.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Carey Mulligan","avatar":""},{"name":"Bo Burnham","avatar":""},{"name":"Alison Brie","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Jennifer Coolidge","avatar":""},{"name":"Laverne Cox","avatar":""},{"name":"​Christopher Lowell","avatar":""},{"name":"Molly Shannon","avatar":""},{"name":"Connie Britton","avatar":""},{"name":"Adam Brody","avatar":""},{"name":"Max Greenfield","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"Steve Monroe","avatar":""},{"name":"Sam Richardson","avatar":""},{"name":"Ray Nicholson","avatar":""},{"name":"Timothy E. Goodwi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324340);
