INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-long-dai-su-troc-yeu-bang', 'Giáng Long Đại Sư: Tróc Yêu Bảng', 'Dragon Hunter', 'null', 'https://phimimg.com/upload/vod/20231129-1/09569c1411c28fe59d5c14b469910e94.jpg', '<p>Bành Ngu Khư lại lần nữa tham gia siêu phẩm kỳ ảo hàng ma cao cấp! Tiểu thư sinh ngốc nghếch bị Bạch Long nhập thể, kết duyên với Tróc Yêu Sư hạng bét, một trận đại chiến bắt yêu quái sắp bắt đầu...</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Peng Yu Si","avatar":""},{"name":"Moe Jiang","avatar":""},{"name":"Mu Fengbin","avatar":""},{"name":"Hao Shaowen","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""},{"name":"Jiang Mengxuan","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324340);
