INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-chu', 'Bùa Chú', 'Spell', 'https://phimimg.com/upload/vod/20231116-1/90c1bcd4d25b1e47ded62c7c9dbdbe4a.jpg', 'https://phimimg.com/upload/vod/20231116-1/55f946ceee32a726391aeb03477771d9.jpg', '<p>Khi đang trên chuyến bay tới dự đám tang của cha mình ở vùng nông thôn Appalachia một cơn bão dữ dội đã khiến Marquis mất quyền điều khiển chiếc máy bay đang chở cả gia đình. Sau khi rơi xuống, anh nhanh chóng đánh thức những người bị thương, nhưng sau đó lại bị mắc kẹt trên gác mái của cô Eloise.Eloise tuyên bố rằng cô có thể giúp anh ấy khoẻ mạnh trở lại bằng một hình nộm mà cô ấy làm từ máu và da của anh. Không thể cầu cứu, Marquis cố gắng thoát khỏi ma thuật đen tối của người phụ nữ kỳ lạ để có thể cứu gia đình anh khỏi nghi lễ độc ác trước sự trỗi dậy của mặt trăng máu.</p>', 'Full', 1, 'single', 'completed', 21, 2020, 'Vietsub', 'HD', 'Nam Phi', 0, '[{"name":"Omari Hardwick","avatar":""},{"name":"Loretta Devine","avatar":""},{"name":"John Beasley","avatar":""},{"name":"Peter Butler","avatar":""},{"name":"Lorraine Burroughs","avatar":""},{"name":"André Jacobs","avatar":""},{"name":"Tumisho Masha","avatar":""},{"name":"Ri-Karlo Handy","avatar":""},{"name":"Hannah Gonera","avatar":""},{"name":"Kalifa Burton","avatar":""},{"name":"Steve Mululu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324340);
