INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-anh-van-tin', 'Vì Anh Vẫn Tin', 'I Still Believe', 'https://phimimg.com/upload/vod/20231116-1/3fa13dd17a4d48e0aa50a7e2d5838236.jpg', 'https://phimimg.com/upload/vod/20231116-1/0c264b47583dd3af37c419d9d4f2de75.jpg', '<p>Phim là bản tình ca ngọt ngào nhưng cũng thấm đượm nước mắt dựa trên cuốn hồi ký cùng tên của ca sĩ, nhạc sĩ người Mỹ Jeremy Camp. Phim kể về chính anh và Melissa Lynn Henning-Camp - người con gái mình yêu, người vợ và cũng là một trong những người có ảnh hưởng lớn nhất tới âm nhạc và cuộc đời của Jeremy từ lúc hai người gặp gỡ, kết hôn rồi đồng hành cùng nhau chiến đấu với căn bệnh ung thư đang dần cướp đi sinh mạng của Melissa.</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"K.J. Apa","avatar":""},{"name":"Britt Robertson","avatar":""},{"name":"Nathan Parsons","avatar":""},{"name":"Gary Sinise","avatar":""},{"name":"Shania Twain","avatar":""},{"name":"Reuben Dodd","avatar":""},{"name":"Nicolas Bechtel","avatar":""},{"name":"Melissa Roxburgh","avatar":""},{"name":"Terry Serpico","avatar":""},{"name":"Tanya Christiansen","avatar":""},{"name":"Cameron Arnett","avatar":""},{"name":"Abigail Cowen","avatar":""},{"name":"Rushi Birudala","avatar":""},{"name":"Anjelah Johnson-Reyes","avatar":""},{"name":"Mike McGill","avatar":""},{"name":"Sahjanan Nasser","avatar":""},{"name":"Al","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324340);
