INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('halloween-cua-hubie', 'Halloween Của Hubie', 'Hubie Halloween', 'https://phimimg.com/upload/vod/20231116-1/494f631e6b23c9684ef35fda4a1e3ef0.jpg', 'https://phimimg.com/upload/vod/20231116-1/43536f699ae4cd9d96754668d6d71943.jpg', '<p>Hubie không phải người được yêu thích nhất Salem, Massachusetts. Nhưng khi Halloween thực sự nhuốm màu ma quái, con người nhút nhát thiện lương đó quyết bảo vệ thị trấn.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Kevin James","avatar":""},{"name":"Julie Bowen","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Rob Schneider","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Tim Meadows","avatar":""},{"name":"Michael Chiklis","avatar":""},{"name":"June Squibb","avatar":""},{"name":"George Wallace","avatar":""},{"name":"Kenan Thompson","avatar":""},{"name":"Shaquille O''Neal","avatar":""},{"name":"Ben Stiller","avatar":""},{"name":"Jackie Sandler","avatar":""},{"name":"Karan Brar","avatar":""},{"name":"Noah Schnapp","avatar":""},{"name":"Sadie","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324340);
