INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-vu-kingsman-2020', 'Mật Vụ Kingsman', 'Hitman : Agent Jun', 'https://phimimg.com/upload/vod/20231002-1/a4f1fd0a506c5a62bcd6ca46a20c5788.jpg', 'https://phimimg.com/upload/vod/20231002-1/4080c04abee19d88a793375ea0efbc88.jpg', '<p>Bộ phim điện ảnh mới đến từ tài tử “Nấc thang lên thiên đường” kể lại hành trình “hoàn lương” dở khóc dở cười của một cựu mật vụ với niềm đam mê vẽ truyện tranh.Sát thủ vô cùng cực (tựa Anh: Hitman: Agent Jun) mở đầu bằng một ngày nắng đẹp. Một gia đình ba người đang lái xe qua đèo thì bị một chiếc xe tải đi ngược chiều do gã tài xế gà gật điều khiển đâm phải. Trong khoảnh khắc sinh tử, cậu con trai của gia đình bèn phát huy siêu năng lực, đỡ lấy chiếc xe và cứu lấy cả gia đình.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kwon Sang-woo","avatar":""},{"name":"Jung Joon-ho","avatar":""},{"name":"Hwang Woo-seul-hye","avatar":""},{"name":"Lee Yi-kyung","avatar":""},{"name":"Lee Ji-won","avatar":""},{"name":"Heo Sung-tae","avatar":""},{"name":"Jo Woon","avatar":""},{"name":"Heo Dong-won","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Lee Joong-ok","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324340);
