INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyet-sai-nguy-thanh', 'Huyết Sái Nguy Thành', 'Desperate Anger City', 'null', 'https://phimimg.com/upload/vod/20231128-1/f64cfabcb4ca7fd62938ad1426a8ceef.jpg', '<p>Tại thị trấn Whitehorse yên bình, những điều kỳ lạ đang xảy ra gần đây. Trong lúc đó, một nhóm người kỳ lạ và độc ác đã tập hợp trong khu rừng cằn cỗi ở ngoại ô thị trấn và họ thề sẽ rửa sạch thị trấn trong máu. Thị trấn bị bao phủ trong khí chết chóc và oxy. Mọi chuyện dường như đang hướng về người phụ nữ bí ẩn từ bên ngoài bảo vệ hậu duệ của anh hùng, Lý San Mỏng và Nhạc An Ngọc. Liệu các anh hùng có thể lật ngược tình thế cuộc chiến với sự giúp đỡ của Bian Buwen và Li San Thin? Liệu &amp;quot;Nuốt&amp;quot; hiện? Câu trả lời nằm trong tay Big Brother Innocent.</p>', 'Full', 1, 'single', 'completed', 19, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Daotie","avatar":""},{"name":"Mulligan Liu","avatar":""},{"name":"Wang Lina","avatar":""},{"name":"Hu Honghong","avatar":""},{"name":"Li Kuo","avatar":""},{"name":"Cheng Cheng","avatar":""},{"name":"Kai Shen","avatar":""},{"name":"Wang Meng","avatar":""},{"name":"Xu Zhangchao","avatar":""},{"name":"He Xie","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324340);
