INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bop-nghet', 'Bóp nghẹt', 'Choked: Paisa Bolta Hai', 'https://phimimg.com/upload/vod/20231117-1/330a79359afc77f79e60b4d261ffd2d7.jpg', 'https://phimimg.com/upload/vod/20231117-1/b70fc3c097777cd585ba4b87275ed59b.jpg', '<p>Khổ sở vì đống nợ của gã chồng thất nghiệp – và những giấc mơ tan vỡ – nữ nhân viên ngân hàng bỗng tìm được nguồn tiền mặt bí mật và dường như vô hạn ngay trong nhà mình.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Saiyami Kher","avatar":""},{"name":"Rajshri Deshpande","avatar":""},{"name":"Amruta Subhash","avatar":""},{"name":"Roshan Mathew","avatar":""},{"name":"Uday Nene","avatar":""},{"name":"Upendra Limaye","avatar":""},{"name":"Tawhid Rike Zaman","avatar":""},{"name":"Tushar Dalvi","avatar":""},{"name":"Milind Phatak","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324341);
