INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-the-cuong-lai', 'Không Thể Cưỡng Lại', 'Irresistible', 'https://phimimg.com/upload/vod/20231117-1/3cde013e65b2f560b0ae55d9ba913ac9.jpg', 'https://phimimg.com/upload/vod/20231117-1/3c4767c4e4398e59026db4a3f074716a.jpg', '<p>Một cố vấn chính trị biến cuộc tranh cử thị trưởng ở thị trấn nhỏ thành màn xiếc truyền thông hàng triệu đô la khi người ứng viên thân thiện thu hút sự chú ý của cả nước.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Carell","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Brent Sexton","avatar":""},{"name":"Mackenzie Davis","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Natasha Lyonne","avatar":""},{"name":"Bill Irwin","avatar":""},{"name":"C.J. Wilson","avatar":""},{"name":"Will Sasso","avatar":""},{"name":"Alan Aisenberg","avatar":""},{"name":"Kevin Maier","avatar":""},{"name":"Tom Key","avatar":""},{"name":"Matt Lewis","avatar":""},{"name":"Vince Pisani","avatar":""},{"name":"Kurt Yue","avatar":""},{"name":"Denise Moyé","avatar":""},{"name":"Andre Rodriguez II","avatar":""},{"name":"Neal Reddy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324341);
