INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('digimon-adventure-lan-tien-hoa-cuoi-cung-kizuna', 'Digimon Adventure: Lần Tiến Hóa Cuối Cùng Kizuna', 'Digimon Adventure: Last Evolution Kizuna', 'https://phimimg.com/upload/vod/20231117-1/172757a0d22c9848ce1c92a7e4d700d2.jpg', 'https://phimimg.com/upload/vod/20231117-1/1007abf318a5e3c49f3dcb34cb67b59a.jpg', '<p>Tài bây giờ đã là sinh viên đại học, sống một mình, chăm chỉ học hành, làm việc hàng ngày nhưng vẫn chưa quyết định được tương lai của mình. Trong khi đó, Matt và những người khác tiếp tục nghiên cứu các sự cố của Digimon và các hoạt động giúp đỡ mọi người cùng với đối tác Digimon của họ. Khi một hiện tượng chưa từng có xảy ra, DigiDestined phát hiện ra rằng khi họ lớn lên, mối quan hệ của họ với đối tác Digimon sẽ tiến gần đến điểm kết thúc. Khi đồng hồ đếm ngược kích hoạt trên Digivice, họ nhận ra rằng họ càng chiến đấu với đối tác Digimon của mình thì mối liên kết của họ càng tan vỡ nhanh hơn. Họ sẽ chiến đấu vì người khác và mất đi người bạn đời của mình? Thời điểm để lựa chọn và quyết định đang đến rất nhanh. Còn một thời gian ngắn trước khi “những đứa trẻ được chọn” trưởng thành. Đây là cuộc phiêu lưu cuối cùng của Tai và Agumon.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Natsuki Hanae","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Suzuko Mimori","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Mutsumi Tamura","avatar":""},{"name":"Hitomi Yoshida","avatar":""},{"name":"Junya Ikeda","avatar":""},{"name":"Chika Sakamoto","avatar":""},{"name":"Mayumi Yamaguchi","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Yuka Tokumitsu","avatar":""},{"name":"Junko Takeuchi","avatar":""},{"name":"Atori Shigematsu","avatar":""},{"name":"Kinoko Yamada","avatar":""},{"name":"Miwa Matsumoto","avatar":""},{"name":"F","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324341);
