INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('threads-our-tapestry-of-love', 'Threads - Our Tapestry Of Love', 'Threads - Our Tapestry Of Love', 'https://phimimg.com/upload/vod/20231117-1/17d6c36181f59323fd9d13c273a1c1ea.jpg', 'https://phimimg.com/upload/vod/20231117-1/b2cfa8ff5da747c73c6d1ae944e2e593.jpg', '<p>Takahashi Ren và Sonoda Aoi đều là trẻ em của những năm 1980 sinh năm 1989. Họ gặp nhau vào năm 2002 và biết về tình yêu và ham muốn ở tuổi trẻ đó xuyên qua nhau. Vì nó thường xảy ra ở độ tuổi đó, chúng đã đi theo những cách riêng biệt của họ chỉ để đoàn tụ ở độ tuổi hai mươi mốt. Số phận lặp lại chính nó. Họ ba mươi mốt tuổi và gặp lại nhau. Điều gì sẽ khác nhau ...</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masaki Suda","avatar":""},{"name":"Nana Komatsu","avatar":""},{"name":"Takumi Saitoh","avatar":""},{"name":"Nana Eikura","avatar":""},{"name":"Mizuki Yamamoto","avatar":""},{"name":"Mitsuko Baisho","avatar":""},{"name":"Mahiro Takasugi","avatar":""},{"name":"Fumika Baba","avatar":""},{"name":"Fumi Nikaido","avatar":""},{"name":"Ryo Narita","avatar":""},{"name":"Yutaka Matsushige","avatar":""},{"name":"Pistol Takehara","avatar":""},{"name":"Sayaka Yamaguchi","avatar":""},{"name":"Misaki Nakano","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324341);
