INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('slaxx', 'Slaxx', 'Slaxx', 'https://phimimg.com/upload/vod/20231116-1/c265c23eb5ba5e7f9c60a7820db95649.jpg', 'https://phimimg.com/upload/vod/20231116-1/d0b19414db07cd847a792ddf2fabc28e.jpg', '<p>Khi một cặp quần jean bị sở hữu bắt đầu giết nhân viên của một cửa hàng quần áo hợp thời trang, tùy thuộc vào Libby, một nhân viên bán hàng trẻ duy tâm, để ngăn chặn cơn thịnh nộ đẫm máu của nó.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Romane Denis","avatar":""},{"name":"Brett Donahue","avatar":""},{"name":"Sehar Bhojani","avatar":""},{"name":"Tianna Nori","avatar":""},{"name":"Jessica B. Hill","avatar":""},{"name":"Erica Anderson","avatar":""},{"name":"Hanneke Talbot","avatar":""},{"name":"Stephen Bogaert","avatar":""},{"name":"Jonathan Emond","avatar":""},{"name":"Elizabeth Neale","avatar":""},{"name":"Aris Tyros","avatar":""},{"name":"Pritha Mazumdar","avatar":""},{"name":"Jiyoti Aggarwal","avatar":""},{"name":"Arjita Bansal","avatar":""},{"name":"Anjali Cherukumilli","avatar":""},{"name":"Shveta Kumaresan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324341);
