INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-kungfu', 'Thành Phố Kungfu', 'The City of Kungfu', 'https://phimimg.com/upload/vod/20231115-1/e14d6ab6276507543c8b44891fb6a2ea.jpg', 'https://phimimg.com/upload/vod/20231115-1/acdfab01f5dc61871046cbf32b5c67e3.jpg', '<p>Lý Nhất bản tính lương thiện và Trần Hiểu từ bé đã sống trong khu phố cổ, trong một lần anh dũng cứu người thì gặp lại Vương Tây người bạn đã chuyển đi từ lâu. Vương Tây là một võ sĩ Muay Thái nên đã giải vây cho Lý Nhất thế là họ trở thành bạn bè. Vương Tây muốn trở về phố cổ phục hưng lại kungfu, điều này hoàn toàn đúng ý Lý Nhất. Tuy nhiên sau lưng Vương Tây lại là âm mưu vô cùng to lớn</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"He Xiang","avatar":""},{"name":"Leung Kar-yan","avatar":""},{"name":"Chi Ling Chiu","avatar":""},{"name":"Wu Guobao","avatar":""},{"name":"Zhengzheng Pei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324341);
