INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('deathstroke-ky-si-rong', 'Deathstroke: Kỵ Sĩ & Rồng', 'Deathstroke: Knights & Dragons - The Movie', 'https://phimimg.com/upload/vod/20231115-1/9a74894691e90423e60501a9b6b434c6.jpg', 'https://phimimg.com/upload/vod/20231115-1/fc5fa81a42a4f557e575bab52b08f132.jpg', '<p>Mười năm trước, Slade Wilson - hay còn gọi là siêu sát thủ được mệnh danh là Deathstroke - đã mắc phải một sai lầm bi thảm và vợ và con trai của hắn đã phải trả một cái giá khủng khiếp. Giờ đây, một thập kỷ sau, gia đình Wilson một lần nữa bị đe dọa bởi Jackal giết người và những kẻ khủng bố của H.IV.E. Deathstroke có thể chuộc lại tội lỗi trong quá khứ hay gia đình anh ta sẽ phải trả giá cuối cùng?</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Chiklis","avatar":""},{"name":"Sasha Alexander","avatar":""},{"name":"Chris Jai Alex","avatar":""},{"name":"Faye Mata","avatar":""},{"name":"Griffin Puatu","avatar":""},{"name":"Asher Bishop","avatar":""},{"name":"Imari Williams","avatar":""},{"name":"Colin Salmon","avatar":""},{"name":"Delbert Hunt","avatar":""},{"name":"Panta Mosleh","avatar":""},{"name":"Noshir Dalal","avatar":""},{"name":"Castulo Guerra","avatar":""},{"name":"Minae Noji","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324341);
