INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-dan', 'Quái Đản', 'Freaky', 'https://phimimg.com/upload/vod/20231115-1/60595e6140149d14de8ef5c52119480c.jpg', 'https://phimimg.com/upload/vod/20231115-1/a3231b2398f7826b154396b1771f74b3.jpg', '<p>Bộ phim có nội dung nói về một nữ sinh trung học đã hoán đổi thân xác với một tên giết người hàng loạt. Trong vòng 24 giờ, sự thay đổi này sẽ trở thành vĩnh viễn, liệu cô gái phải làm thế nào?</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vince Vaughn","avatar":""},{"name":"Kathryn Newton","avatar":""},{"name":"Celeste O''Connor","avatar":""},{"name":"Misha Osherovich","avatar":""},{"name":"Uriah Shelton","avatar":""},{"name":"Dana Drori","avatar":""},{"name":"Katie Finneran","avatar":""},{"name":"Melissa Collazo","avatar":""},{"name":"Alan Ruck","avatar":""},{"name":"Brooke Jaye Taylor","avatar":""},{"name":"Zack Shires","avatar":""},{"name":"Magnus Diehl","avatar":""},{"name":"Kelly Lamor Wilson","avatar":""},{"name":"Nicholas Stargel","avatar":""},{"name":"Mitchell Hoog","avatar":""},{"name":"Emily Holder","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324341);
