INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quai-dan', 'Quái Đản', 'Freaky', 'quái đản freaky vince vaughn kathryn newton celeste o''connor misha osherovich uriah shelton dana drori katie finneran melissa collazo alan ruck brooke jaye taylor zack shires magnus diehl kelly lamor wilson nicholas stargel mitchell hoog emily holder ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-lai-tien-tung', 'Bồng Lai Tiên Tung', 'Celestial Track Of Peng Lai', 'https://phimimg.com/upload/vod/20231113-1/889514d50e3d2ade6d215f57bd1e0872.jpg', 'https://phimimg.com/upload/vod/20231113-1/313360e15a264bb834e48747165c8ec4.jpg', '<p>Linh hồn bạch xà Ngân Đại tu luyện nhiều năm đã được Lữ Động Tân cứu thoát trong quá trình tránh nạn. Lòng tốt ban đầu dần dần phát triển thành tình yêu trong trái tim của Ngân Đại, nhưng cô lại là một con quỷ. Dù muốn thú nhận danh tính của cô với người yêu của .&nbsp;<br/>Nhưng em gái Thanh Y phản đối việc Ngân Đại và Động Tân bên cạnh nhau bèn hợp tác với sư huynh Thôi Minh để chia cắt hai người. Người bạn của Động Tân là Giai Nhân cũng tìm mọi cách để hãm hại anh chàng.<br/>Lữ Động Tân yêu Ngân Đại sâu sắc, không tin vào số mệnh an bài nên đã không khuất phục thiên mệnh, tìm lại cỏ linh hồn, trong động thuần thái dương luyện kiếm thuật tinh thần, canh giữ nửa bước, để Ngân Đại có thể hồi sinh.<br/>Chưa bao giờ nghĩ đến việc giải phóng phép thuật phong ấn Ngân Đại. Sau khi Ngân Đại được thả, Thôi Minh và Giải Nhân tìm cách hãm hại Động Tân. Bởi vì Lữ Động Tân nuốt nhầm thuật giả kim, Pian Pian đã chết dưới thanh kiếm của Lữ Động Tân với thanh kiếm.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Miles Wei","avatar":""},{"name":"Chen Jiawen","avatar":""},{"name":"Ding Huiyu","avatar":""},{"name":"Hong Shiya","avatar":""},{"name":"Zhu Haijun","avatar":""},{"name":"Jian Yuanxin","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324341);
