INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hoa-soi', 'Người Hóa Sói', 'Wolfwalkers', 'https://phimimg.com/upload/vod/20231113-1/0c99b51717c8895088c7059ef55748c7.jpg', 'https://phimimg.com/upload/vod/20231113-1/f51358849490018f99b4e70a58acd341.jpg', '<p>Cô bé thợ săn học việc du hành đến Ireland để giúp bố diệt sạch đàn sói cuối cùng. Nhưng mọi chuyện thay đổi khi cô kết bạn với một cô bé phóng khoáng đến từ một tộc người bí ẩn, được đồn là có thể hóa thành sói vào ban đêm.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Honor Kneafsey","avatar":""},{"name":"Eva Whittaker","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"Tommy Tiernan","avatar":""},{"name":"Maria Doyle Kennedy","avatar":""},{"name":"Jon Kenny","avatar":""},{"name":"John Morton","avatar":""},{"name":"Nora Twomey","avatar":""},{"name":"Oliver McGrath","avatar":""},{"name":"Paul Young","avatar":""},{"name":"Niamh Moyles","avatar":""},{"name":"Ben Andrews","avatar":""},{"name":"Jerome Burelbach","avatar":""},{"name":"Vince Drews","avatar":""},{"name":"Seamus Greene","avatar":""},{"name":"Gilbert Johnston","avatar":""},{"name":"Luke","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324341);
