INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-giay', 'Hổ Giấy', 'The Paper Tigers', 'https://phimimg.com/upload/vod/20231113-1/646103f12b9807516c2a602c5a748a74.jpg', 'https://phimimg.com/upload/vod/20231113-1/ef8334d2d6d8f8531d7aba3023689622.jpg', '<p>Hổ Giấy - The Paper Tigers là bộ phim xoay quanh câu chuyện về ba người võ sĩ vô cùng nổi tiếng và còn được gọi là &quot;Tam Hổ&quot;. Hiện tại, cả ba điều đã trở thành những người đàn ông trung niên, và mỗi cú đá, đấm đều có những sát thương lớn. Thế nhưng, một hôm người thầy của bọn họ đã bị sát hại một cách bí ẩn, cả ba đã từ bỏ hết công việc hiện tại và bắt đầu thực hiện một nhiệm vụ cuối mà người thầy đã để lại, còn lần theo những manh mối về những hận thù xưa để trả thù cho cái chết của ông.</p>', 'Full', 1, 'single', 'completed', 9, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alain Uy","avatar":""},{"name":"Ron Yuan","avatar":""},{"name":"Mykel Shannon Jenkins","avatar":""},{"name":"Yuji Okumoto","avatar":""},{"name":"Yoshi Sudarso","avatar":""},{"name":"Jae Suh Park","avatar":""},{"name":"Peter Sudarso","avatar":""},{"name":"Roger Yuan","avatar":""},{"name":"Matthew Page","avatar":""},{"name":"Gui DaSilva-Greene","avatar":""},{"name":"Annette Toutonghi","avatar":""},{"name":"Ray Hopper","avatar":""},{"name":"Joziah Lagonoy","avatar":""},{"name":"Andy Le","avatar":""},{"name":"Ken Quitugua","avatar":""},{"name":"Brian Le","avatar":""},{"name":"Phillip Dang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324341);
