INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('may-quay-canh-sat', 'Máy quay cảnh sát', 'Body Cam', 'https://phimimg.com/upload/vod/20231115-1/a4609471df67fd7ee073b84d7a48ce8d.jpg', 'https://phimimg.com/upload/vod/20231115-1/ea90f2d6bb7e5943210eda0f794a9b33.jpg', '<p>Sau cái chết rùng rợn của đồng nghiệp, viên cảnh sát điều tra vụ án phát hiện ra một thứ gì đó siêu nhiên đang nhắm vào cảnh sát trong đơn vị của cô.</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mary J. Blige","avatar":""},{"name":"Nat Wolff","avatar":""},{"name":"David Zayas","avatar":""},{"name":"Anika Noni Rose","avatar":""},{"name":"David Warshofsky","avatar":""},{"name":"Ian Casselberry","avatar":""},{"name":"Philip Fornah","avatar":""},{"name":"Lara Grice","avatar":""},{"name":"Demetrius Grosse","avatar":""},{"name":"Alfonzo Walker","avatar":""},{"name":"Jeff Pope","avatar":""},{"name":"Sylvia Grace Crim","avatar":""},{"name":"Lorrie Odom","avatar":""},{"name":"Naima Ramos-Chapman","avatar":""},{"name":"Renell Gibbs","avatar":""},{"name":"Altonio Jackson","avatar":""},{"name":"Jibrail","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324341);
