INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-vuong-trieu-chi-co-son-kiem-tang', 'Kiếm Vương Triều Chi Cô Sơn Kiếm Tàng', 'Sword Dynasty Fantasy Masterwork', 'https://phimimg.com/upload/vod/20231125-1/53159f285d985c8ac6742d94b8802927.jpg', 'https://phimimg.com/upload/vod/20231125-1/260862498d753b5f6b17b0facebaf3a0.jpg', '<p>Sau trận Ba Sơn, Dạ Sách Lãnh lưu lại bên Hằng Vương luôn tìm tin tức đồng môn, chờ thời cơ giết Hằng Vương báo thù. Giang hồ đưa tin Vân Lai trấn có giấu kiếm quý trên núi, Hằng Vương sai Trần Huyền và Sách Lãnh đến thăm dò. Vân Lai trấn xuất hiện yêu quái, Dạ Sách Lãnh cứu được Quý Thần. Là ông chủ Hà và Vân Sam sư tỉ lừa các nhân sĩ đến tìm kiếm để mượn máu họ luyện công. Để báo thù cho Quý Thần và Vân Sam, Sách Lãnh đã giết ông chủ Hà. Trần Huyền biết mục đích của Sách Lãnh là báo thù, theo cô ấy về bên Hằng Vương…</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yuanyuan Zhao","avatar":""},{"name":"Liu Yitong","avatar":""},{"name":"Zhang Mingming","avatar":""},{"name":"Tan Xinrou","avatar":""},{"name":"Lu Ye","avatar":""},{"name":"Gao Yi","avatar":""},{"name":"Xu Caixiang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324341);
