INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dot-kich-nga', 'Cuộc Đột Kích Nga', 'Russkiy Reyd', 'https://phimimg.com/upload/vod/20231113-1/3860af39d01704bf253f7c5f62b521eb.jpg', 'https://phimimg.com/upload/vod/20231113-1/0af91cfdf84cdf6ce49a64baa37f6bca.jpg', '<p>Nikita, một cựu đặc nhiệm Spetsnaz của Nga, được thuê để vô hiệu hóa lực lượng an ninh tư nhân lớn tại một nhà máy địa phương để người chủ mờ ám của anh ta có thể tống tiền chủ nhà máy kinh doanh. Nhưng Nikita và nhóm các máy bay chiến đấu được đào tạo chuyên sâu của anh ấy nhận được nhiều hơn những gì họ mặc cả khi hóa ra nhà máy thực sự thuộc sở hữu của một lãnh chúa nguy hiểm có liên hệ với quân đội Nga...</p>', 'Full', 1, 'single', 'completed', 20, 2020, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Ivan Kotik","avatar":""},{"name":"Alexandr Krasovsky","avatar":""},{"name":"Ilya Antonenko","avatar":""},{"name":"Vladimir Mineev","avatar":""},{"name":"Nikita Kologrivyi","avatar":""},{"name":"Sofya Ozerova","avatar":""},{"name":"Kirill Sarychev","avatar":""},{"name":"Dmitry Krivochurov","avatar":""},{"name":"Andrey Semenov","avatar":""},{"name":"Alexey Maximenkov","avatar":""},{"name":"Sergey Podolnyy","avatar":""},{"name":"Konstantin Ignatyev","avatar":""},{"name":"Vladimir Borovikov","avatar":""},{"name":"Khelga Filippova","avatar":""},{"name":"Natalya","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324341);
