INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-tai-nang', 'Thiếu Nữ Tài Năng', 'Power On Girl', 'https://phimimg.com/upload/vod/20231123-1/a12ea5b62e05b25f4b70e3eb369df23d.jpg', 'https://phimimg.com/upload/vod/20231123-1/4d719442fdc40c2a2f93a929e18a6d52.jpg', '<p>Câu chuyện kể về nhóm các cô gái tới Bắc Kinh lập nghiệp, thành lập nhóm nhạc nữ, cùng theo đuổi ước mơ, không ngừng trưởng thành. Họ quen nhau nhờ ước mơ, hiểu nhau nhờ những cố gắng nỗ lực, từ những rời rạc xa cách ban đầu dần dần đã ăn ý đoàn kết với nhau.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Mu Yun","avatar":""},{"name":"Liu Si Xian","avatar":""},{"name":"Liu Rui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324341);
