INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-dan-guong-mau', 'Công Dân Gương Mẫu', 'Model Citizen', 'https://phimimg.com/upload/vod/20231121-1/2a8533091ceb490c7f7a9d014e6fe14d.jpg', 'https://phimimg.com/upload/vod/20231121-1/9a86dfae0ff3f79da30346dc25804833.jpg', '<p>Lấy cảm hứng từ các sự kiện đời thực của người mẫu bị bắt cóc Chloe Aomme, MODEL CITIZEN kể câu chuyện về một người mẫu trẻ, bị bắt cóc và giam giữ bởi hai anh em sau một buổi chụp hình giả. Bị giam cầm trong một cabin xa xôi, Amanda sẽ làm bất cứ điều gì để về nhà với cô con gái nhỏ và phát triển một mối liên kết kỳ lạ với một trong những tù nhân của cô.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shawn Pyfrom","avatar":""},{"name":"Kevin Fonteyne","avatar":""},{"name":"Brytnee Ratledge","avatar":""},{"name":"Sandy Lopez","avatar":""},{"name":"Marie Wagenman","avatar":""},{"name":"Cassie Howarth","avatar":""},{"name":"Melissa Chambers","avatar":""},{"name":"Scott Takeda","avatar":""},{"name":"Jason Coviello","avatar":""},{"name":"Esodie Geiger","avatar":""},{"name":"Diane Villegas","avatar":""},{"name":"David Phyfer","avatar":""},{"name":"Hans Christopher","avatar":""},{"name":"Amber Lynn Ashley","avatar":""},{"name":"Emelie O''Hara","avatar":""},{"name":"Barney Fulle","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324341);
