INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-am', 'Tổ Ấm', 'The Nest', 'https://phimimg.com/upload/vod/20231111-1/548b3dec8a18c4ddee6f7d80345583dc.jpg', 'https://phimimg.com/upload/vod/20231111-1/5d1e1655d4f1245dfb1d8c411efdcba0.jpg', '<p>Tổ Ấm - The Nest xoay quanh cuộc sống của một doanh nhân tên Rory và gia đình của anh. Rory đưa vợ con từ Mỹ đến Anh để nắm bắt cơ hội mới, nhưng không không ngờ cuộc sống ở Anh đe dọa làm tan rã gia đình anh khi mỗi thành viên trong gia đình lao vào cách sống “tự hủy hoại”.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jude Law","avatar":""},{"name":"Carrie Coon","avatar":""},{"name":"Oona Roche","avatar":""},{"name":"Charlie Shotwell","avatar":""},{"name":"Tanya Allen","avatar":""},{"name":"Tattiawna Jones","avatar":""},{"name":"Marcus Cornwall","avatar":""},{"name":"Wendy Crewson","avatar":""},{"name":"Michael Culkin","avatar":""},{"name":"Adeel Akhtar","avatar":""},{"name":"Annabel Leventon","avatar":""},{"name":"Peter Hamilton Dyer","avatar":""},{"name":"Bamshad Abedi-Amin","avatar":""},{"name":"Oliver Gatz","avatar":""},{"name":"Christian Jenner","avatar":""},{"name":"Stuart McQuarrie","avatar":""},{"name":"An","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324341);
