INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-mua-tinh-dau', 'Cơn Mưa Tình Đầu', 'Classic Again', 'https://phimimg.com/upload/vod/20231111-1/6816e68d6141ef05879f1a2d51747809.jpg', 'https://phimimg.com/upload/vod/20231111-1/930735e76435c6377d923a02e1a440bd.jpg', '<p>Phim là sự đan xen của hai câu chuyện tình yêu cách nhau 3 thập kỷ. Bota và cô bạn thân Poppy cùng cảm nắng Non – một anh bạn cùng trường đại học. Hiểu tấm lòng của người bạn thân, Bota giấu đi cảm xúc thật của mình để cổ vũ Poppy đến với Non. Một ngày, Bota tình cờ tìm thấy chiếc hộp cũ chứa đầy những lá thư và kỷ niệm về mối tình đầu của mẹ. Những bức thư giữa mẹ cô, Dalah và một chàng trai nhà nghèo tên Kajorn khiến Bota nhận ra cảm xúc hiện tại của mình thật giống với câu chuyện tình dở dang của mẹ. Liệu cô có dũng cảm giữ lấy tình yêu của mình hay mối tình đầu của Bota cũng sẽ kết thúc đầy tiếc nuối?</p>', 'Full', 1, 'single', 'completed', 17, 2020, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Ranchrawee Uakoolwarawat","avatar":""},{"name":"Thitipoom Techa-apaikhun","avatar":""},{"name":"Sutthirak Subvijitra","avatar":""},{"name":"Chonnikan Netjui","avatar":""},{"name":"Samitpong Sakulpongchai","avatar":""},{"name":"Suriya Yaowasang","avatar":""},{"name":"Amm Siraprapa Sookdamrong","avatar":""},{"name":"Thitinan Khlangphet","avatar":""},{"name":"Rachan Supploy","avatar":""},{"name":"Noppawan Phetburee","avatar":""},{"name":"Nannapat Jariya","avatar":""},{"name":"Leelawadee Chiewkan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324341);
