INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-vo-sat-nhan', 'Người vợ sát nhân', 'Mrs. Serial Killer', 'https://phimimg.com/upload/vod/20231111-1/6e436ee4a6b01d52ebd4d02bfbfc74e2.jpg', 'https://phimimg.com/upload/vod/20231111-1/1d65d07a85a1a57559aeeeec0f15eebc.jpg', '<p>Khi một bác sĩ bị bỏ tù vì hàng loạt án mạng chấn động, người vợ trung trinh của anh bắt đầu gây ra tội ác y hệt để chứng minh anh vô tội.</p>', 'Full', 1, 'single', 'completed', 16, 2020, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Jacqueline Fernandez","avatar":""},{"name":"Manoj Bajpayee","avatar":""},{"name":"Mohit Raina","avatar":""},{"name":"Darshan Jariwala","avatar":""},{"name":"Zayn Marie Khan","avatar":""},{"name":"Chanda Joshi","avatar":""},{"name":"Deepak Arora","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324341);
