INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-vuc-chet-cuoc-san-duoi', 'Khu Vực Chết: Cuộc Săn Đuổi', 'Tribal: Get Out Alive', 'https://phimimg.com/upload/vod/20231111-1/e1cc0e37b57ec65413df89e2a9f063bf.jpg', 'https://phimimg.com/upload/vod/20231111-1/17b490b14c19495d29a3d1a3af0525fc.jpg', '<p>Quân nhân ưu tú Caitlin Ross nghỉ việc sau khi mắc chứng PTSD. Cùng với cựu thành viên trong nhóm và người bạn thân Brad Johnson, họ đã chọn ‘cuộc sống dễ dàng’ và hiện lãnh đạo một công ty bảo mật nhỏ. Công ty được thuê bởi triệu phú trẻ tuổi, rắc rối Richard Kenning để giải tỏa và đảm bảo đất đai và tài sản mà ông mới được thừa kế. Những tin đồn và câu chuyện xung quanh vùng đất và các tòa nhà bị bác bỏ cho đến khi mọi người bắt đầu biến mất và cả đội bị nhốt không lối thoát. Rõ ràng là họ đang bị săn đuổi và cuộc chạy đua giành lấy sự sống đang diễn ra.</p>', 'Full', 1, 'single', 'completed', 10, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Zara Phythian","avatar":""},{"name":"Ross O''Hennessy","avatar":""},{"name":"Rachel Warren","avatar":""},{"name":"Thomas Dodd","avatar":""},{"name":"Valerie Thomas","avatar":""},{"name":"Grayson James Matthews","avatar":""},{"name":"Mark Sears","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324341);
