INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khu-vuc-chet-cuoc-san-duoi', 'Khu Vực Chết: Cuộc Săn Đuổi', 'Tribal: Get Out Alive', 'khu vực chết: cuộc săn đuổi tribal: get out alive zara phythian ross o''hennessy rachel warren thomas dodd valerie thomas grayson james matthews mark sears ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-tram-buu-binh-bon-tau-den-bac-pha', 'Tám Trăm Bưu Binh Bôn Tẩu Đến Bắc Pha', 'Impasse Rescue', 'https://phimimg.com/upload/vod/20231111-1/0a8a528fc6186f83fb4d9e668d5fb84f.jpg', 'https://phimimg.com/upload/vod/20231111-1/9c656fc74e7764f6cf4186500e3ab3ce.jpg', '<p>Nội dung phim xoay quanh hành trình giải cứu tướng quân Lý Truy Phong trong thành Bắc Pha. Cầm binh hơn 30 năm và có không ít lần đại thắng, giúp Thần Châu mở rộng biên cương, Lý tướng quân luôn là chỗ dựa tinh thần lớn nhất của các binh sĩ trong mỗi trận đánh. Tuy nhiên, lần tấn công quân Sa Man khiến đội quân của ông thiệt hại nặng nề, bị vây bắt trong thành, tiến thoái lưỡng nan, chỉ chờ quân địch đến để liều mạng. Nhận được thông tin, tướng Hoàng Tự Tại không vội tiến quân giải cứu. Với lực lượng 5 nghìn kỵ binh và 20 nghìn bộ binh không thể nào đấu lại 100 ngàn quân Bắc Pha tinh nhuệ, Hoàng tướng quân tìm cách hoãn binh để tìm kế sách vẹn toàn nhất. Lúc này, con gái của Truy Phong rất tức giận vì quyết định của Tự Tại, nhưng cuối cùng cũng chịu hợp tác với anh. Cuối cùng, chỉ cần 800 hùng binh, Hoàng tướng quân đã có thể đánh tan thành Bắc Pha.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Li Zeyu","avatar":""},{"name":"Shao Xingying","avatar":""},{"name":"Li Tianya","avatar":""},{"name":"Kefa Cui","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324341);
