INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('babyteeth', 'Babyteeth', 'Babyteeth', 'https://phimimg.com/upload/vod/20231111-1/e6a90ece93a468560d44bfaad662da6e.jpg', 'https://phimimg.com/upload/vod/20231111-1/a5291aebd18bd35b4560a257059f2632.jpg', '<p>Khi thiếu niên Milla nghiêm trọng sẽ yêu điên cuồng với những người buôn bán ma túy nhỏ Moses, đó là cơn ác mộng tồi tệ nhất của cha mẹ cô. Nhưng như bàn chải đầu tiên của Milla với tình yêu mang đến cho cô một ham muốn mới cho cuộc sống, mọi thứ trở nên lộn xộn và đạo đức truyền thống đi ra ngoài cửa sổ. Milla sớm cho tất cả mọi người trong quỹ đạo của cô - cha mẹ của cô, Moses, một giáo viên âm nhạc nhạy cảm, một nghệ sĩ violin trẻ em vừa chớm nở, và một người hàng xóm mang thai trung thực - làm thế nào để sống như bạn không có gì để mất. Những gì có thể là một thảm họa cho gia đình Finlay thay vào đó dẫn đến buông tay và tìm kiếm ân sủng trong sự hỗn loạn rực rỡ của cuộc sống. Babyteeth vui vẻ khám phá những điều tốt đẹp như thế nào để chết và chúng ta sẽ đi bao xa vì tình yêu</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Eliza Scanlen","avatar":""},{"name":"Ben Mendelsohn","avatar":""},{"name":"Essie Davis","avatar":""},{"name":"Toby Wallace","avatar":""},{"name":"Andrea Demetriades","avatar":""},{"name":"Emily Barclay","avatar":""},{"name":"Charles Grounds","avatar":""},{"name":"Priscilla Doueihy","avatar":""},{"name":"Jack Yabsley","avatar":""},{"name":"Zack Grech","avatar":""},{"name":"Quentin Yung","avatar":""},{"name":"Renee Billing","avatar":""},{"name":"Georgina Symes","avatar":""},{"name":"Jaga Yap","avatar":""},{"name":"Michelle Lotters","avatar":""},{"name":"Eugene Gilfedder","avatar":""},{"name":"Tyrone Ma","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324341);
