INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-ban-ba-dao', 'Hội Bạn Bá Đạo', 'Sticky Toffee Pudding', 'https://phimimg.com/upload/vod/20231111-1/8a824d551343d58a05c4e30523491de0.jpg', 'https://phimimg.com/upload/vod/20231111-1/705460d96df112aebbae06eac5ca8edc.jpg', '<p>Sticky Toffee Pudding - Hội Bạn Bá Đạo: Bộ phim kể về thời cấp 3 tràn đầy những nhiệt huyết, thú vị, sai lầm và tình yêu của tuổi trẻ. Hội bạn của Shelby đã và đang trải qua năm cuối cấp 3 và họ sẽ trải qua một năm cuối thế nào? Có chuyện gì sẽ xảy ra.</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Samuel Nicholls","avatar":""},{"name":"Emma-Kate Barry","avatar":""},{"name":"Charlie Howard","avatar":""},{"name":"Genevieve Lewis","avatar":""},{"name":"Callum Henderson","avatar":""},{"name":"Sophie Mae","avatar":""},{"name":"Samuel G Caple","avatar":""},{"name":"Abi Watkinson","avatar":""},{"name":"Maddy Bowyer","avatar":""},{"name":"Cyril Cottrell","avatar":""},{"name":"Jane Deane","avatar":""},{"name":"Haydon Downing","avatar":""},{"name":"Sophia Earnshaw-Punnett","avatar":""},{"name":"India Howland","avatar":""},{"name":"Catherine Madden","avatar":""},{"name":"Will Pinhey","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324341);
