INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-tri-cua-nghe-thuat', 'Giá Trị Của Nghệ Thuật', 'The Last Vermeer', 'https://phimimg.com/upload/vod/20231111-1/0fe6c6680d0c7657462b134b7ea8d653.jpg', 'https://phimimg.com/upload/vod/20231111-1/fc9ddca1b22e86b89f1b0dfead1ea60f.jpg', '<p>Giá Trị Của Nghệ Thuật - The Last Vermeer (2019) lấy bối cảnh sau Thế chiến thứ 2 - một câu chuyện có thật bị lãng quên theo năm tháng - xoay quanh cuộc đời của người lính điều tra nghệ sĩ nổi tiếng người Hà Lan Han van Meegeren. Hắn ta bị buộc tội âm mưu thông đồng với Đức Quốc xã. Bất chấp việc thu thập bằng chứng, Piller ngày càng bị thuyết phục về sự vô tội của Han, anh cảm thấy mình ở trong tình thế nguy nan khó có thể chiến đấu để cứu lấy cuộc sống của người đàn ông đầy màu sắc với quá khứ bí ẩn.</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Guy Pearce","avatar":""},{"name":"Claes Bang","avatar":""},{"name":"Vicky Krieps","avatar":""},{"name":"Roland Møller","avatar":""},{"name":"August Diehl","avatar":""},{"name":"Karl Johnson","avatar":""},{"name":"Andrew Havill","avatar":""},{"name":"Paul Bentall","avatar":""},{"name":"Olivia Grant","avatar":""},{"name":"Adrian Scarborough","avatar":""},{"name":"Marie Bach Hansen","avatar":""},{"name":"Tom Mulheron","avatar":""},{"name":"Cameron Jack","avatar":""},{"name":"Susannah Doyle","avatar":""},{"name":"Richard Dillane","avatar":""},{"name":"Oliver Ryan","avatar":""},{"name":"Simon Paisley Day","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324341);
