INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-thuc-tinh', 'Quái Vật Thức Tỉnh', 'Alien Invasion', 'https://phimimg.com/upload/vod/20231110-1/acaad850dd3e17104e67dbb58e8cdb1c.jpg', 'https://phimimg.com/upload/vod/20231110-1/9af3a6e022500e2fa7bc331c8323ec3f.jpg', '<p>Thám tử tư Xu Siwei nhận được một công việc bí ẩn là tìm cha của khách hàng. Trong quá trình điều tra, anh vô tình rơi vào một vũ trụ song song và chạm trán với những con quái vật ở đó. Sau một cuộc hành trình ly kỳ, anh ta trốn thoát, nhưng những điều kỳ lạ bắt đầu liên tục xảy ra với anh ta. Để thoát khỏi những rắc rối, Xu Siwei quyết định tìm ra sự thật. Tuy nhiên, một âm mưu khoa học khổng lồ đang rình rập anh ta ...</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zheng Xitong","avatar":""},{"name":"Wang Yi Qi","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""},{"name":"Jackson Liu","avatar":""},{"name":"Song Xiang","avatar":""},{"name":"Zhang Na","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324341);
