INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-thua-o-magnolia', 'Giao thừa ở Magnolia', 'Midnight at the Magnolia', 'https://phimimg.com/upload/vod/20231110-1/c24df0e40fbd5c6da1b600ad5a8642dc.jpg', 'https://phimimg.com/upload/vod/20231110-1/bb408349727c51d2fccca973ef33ca09.jpg', '<p>Đôi bạn lâu năm kiêm phát thanh viên tại địa phương là Maggie và Jack giả làm cặp đôi trước gia đình và thính giả, hy vọng chương trình của họ được phát sóng rộng rãi.</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Natalie Hall","avatar":""},{"name":"Evan Williams","avatar":""},{"name":"Michael Gordin Shore","avatar":""},{"name":"Steve Cumyn","avatar":""},{"name":"Alison Brooks","avatar":""},{"name":"Hannah Gordon","avatar":""},{"name":"Susan Hamann","avatar":""},{"name":"Eldon Hunter","avatar":""},{"name":"Victoria Maria","avatar":""},{"name":"Olivier Renaud","avatar":""},{"name":"Matthew Stefiuk","avatar":""},{"name":"Dane O''Connor","avatar":""},{"name":"Sean Williams","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"}]', '[]', 1784690324341);
