INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-truong-quan-lot-cuoc-phieu-luu-tuong-tac', 'Đội Trưởng Quần Lót: Cuộc Phiêu Lưu Tương Tác', 'Captain Underpants: Epic Choice-o-rama', 'https://phimimg.com/upload/vod/20231120-1/b1a87d2e86611203646c483fb37807f2.jpg', 'https://phimimg.com/upload/vod/20231120-1/8bc2e946c1f818ad8844a657a56eb0f1.jpg', '<p>Trong tập phim tương tác đặc biệt này, Harold và George cần kỹ năng ra quyết định của bạn để ngăn Krupp phá tan ngôi nhà trên cây yêu dấu của họ.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nat Faxon","avatar":""},{"name":"Jay Gragnani","avatar":""},{"name":"Ramone Hamilton","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324341);
