INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-cuop-bi-an', 'Vụ Cướp Bí Ẩn', 'Magnesium', 'https://phimimg.com/upload/vod/20231109-1/47c8a1a2a17dd269251a60ceaf70306e.jpg', 'https://phimimg.com/upload/vod/20231109-1/7f78832b110fc2b430776298abea6a24.jpg', '<p>Vụ cướp bí ẩn - Magnesium là bộ phim thuộc thể loại tội phạm, chính kịch, viễn tây của Ba Lan. Tác phẩm do Maciej Bochniak chịu trách nhiệm chỉ đạo, với sự tham gia của các diễn viên Dawid Ogrodnik, Mateusz Kosciukiewicz và Maja Ostaszewska. Bộ phim lấy bối cảnh miền viễn tây, cảm hứng từ những người như Tarantino và Leone, vào những năm 1920 ở vùng biên giới giữa Ba Lan và Liên xô. Hai anh em sinh đôi đã lên kế hoạch cướp một gia đình thuộc Mafia vốn ở phe đối nghịch, một hình mẫu của sự trao quyền cho phụ nữ trong đó được điều hành bởi chị em gái.</p>', 'Full', 1, 'single', 'completed', 26, 2020, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Dawid Ogrodnik","avatar":""},{"name":"Mateusz Kościukiewicz","avatar":""},{"name":"Maja Ostaszewska","avatar":""},{"name":"Agata Kulesza","avatar":""},{"name":"Małgorzata Gorol","avatar":""},{"name":"Borys Szyc","avatar":""},{"name":"Andrzej Chyra","avatar":""},{"name":"Magdalena Boczarska","avatar":""},{"name":"Bartosz Bielenia","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324341);
