INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-sau-tu-than', 'Cá Sấu Tử Thần', 'Black Water: Abyss', 'https://phimimg.com/upload/vod/20231109-1/9c2c9c66f6f1fe709c5e722b98b64350.jpg', 'https://phimimg.com/upload/vod/20231109-1/546081bdd49032dce32a871a447b6bad.jpg', '<p>Một nhóm bạn gồm 5 người rủ nhau khám phá một hang động chưa ai biết đến trong một cánh rừng già ở Úc. Mọi người đều rất vui mừng khi là người đầu tiên phát hiện ra nhiều cảnh quan đẹp mắt trong hang, đặc biệt là một hồ nước cực trong xanh, mát lạnh. Tuy nhiên, mọi thứ bỗng nhiên hết vui khi mà họ phát hiện có một sinh vật nguy hiểm đang rình rập ở dưới nước và cơn bão ở bên ngoài khiến họ bị mắc kẹt, không thể ra ngoài. Có điều gì đang chờ đón nhóm bạn này ở phía trước?</p>', 'Full', 1, 'single', 'completed', 16, 2020, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Jessica McNamee","avatar":""},{"name":"Luke Mitchell","avatar":""},{"name":"Amali Golden","avatar":""},{"name":"Benjamin Hoetjes","avatar":""},{"name":"Anthony J. Sharpe","avatar":""},{"name":"Louis Toshio Okada","avatar":""},{"name":"Rumi Kikuchi","avatar":""},{"name":"Anna Kubat","avatar":""},{"name":"Nicole Collett","avatar":""},{"name":"Stu Kirk","avatar":""},{"name":"Troy Black","avatar":""},{"name":"Damien Blewett","avatar":""},{"name":"Isabella Sheehan","avatar":""},{"name":"Glenn Adams","avatar":""},{"name":"Myra Stoertzer","avatar":""},{"name":"J'' Ma","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324341);
