INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('driveways', 'Driveways', 'Driveways', 'https://phimimg.com/upload/vod/20231109-1/5b20b1818f5a85d1b35c480c1990a29c.jpg', 'https://phimimg.com/upload/vod/20231109-1/85e0f9447cb52cac3812828f1302ee4c.jpg', '<p>Một cậu bé cô đơn đi cùng với mẹ của mình trong một chuyến đi để dọn dẹp nhà của dì vào cuối, và cuối cùng tạo thành một tình bạn bất ngờ với người về hưu sống bên cạnh.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hong Chau","avatar":""},{"name":"Lucas Jaye","avatar":""},{"name":"Brian Dennehy","avatar":""},{"name":"Christine Ebersole","avatar":""},{"name":"Jerry Adler","avatar":""},{"name":"Robyn Payne","avatar":""},{"name":"Jeter Rivera","avatar":""},{"name":"Sophia DiStefano","avatar":""},{"name":"Jack Caleb","avatar":""},{"name":"James DiGiacomo","avatar":""},{"name":"Bill Buell","avatar":""},{"name":"Stan Carp","avatar":""},{"name":"Laurent Rejto","avatar":""},{"name":"Jennifer Delora","avatar":""},{"name":"Joe Felece","avatar":""},{"name":"Tyler Altomari","avatar":""},{"name":"Rosemary Howard","avatar":""},{"name":"Raymond Le","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324341);
