INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-than-bang-tru-yeu', 'Phong Thần Bảng Trừ Yêu', 'The Alluring Woman', 'null', 'https://phimimg.com/upload/vod/20231109-1/42f9512e7f276f08dc3d88e6a8bd12d1.jpg', '<p>Khương Tử Nha bắt được một con yêu hồ có chín đuôi trong rừng,mà gặp vua Trụ đang đi săn.Yêu hồ cầu cứu với vua Trụ ,vua Trụ thương xót cô ấy,thì ra lệnh Khương Tử Nha thả ra.Yêu hồ hóa thân Đát Kỷ vào cung báo ơn,khát khao cùng với vua Trụ bạch đầu giai lão.Không ngờ vua Trụ ái mộ Hoàng hoàng hậu hiền lành,Đát Kỷ rất ghen ghét.Đồng thời,Khương Tử Nha đã biết Đát Kỷ tức là yêu hồ có chín đuôi,vốn là muốn bắt yêu quái,không ngờ lại bị cô ấy hãm hại,mất lòng tin của vua Trụ.Bá Ấp Khảo và Hoàng hoàng hậu có mối tình tri âm, Đát Kỷ tìm được cơ hội phụ thân vào Hoàng hoàng hậu,làm cho vua Trụ hiểu lầm Hoàng hoàng hậu và Bá Ấp Khảo có ngoại tình.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhou Haodong","avatar":""},{"name":"Xu Ning","avatar":""},{"name":"Huang Yi Han","avatar":""},{"name":"Yang Kai Di","avatar":""},{"name":"Li Yan","avatar":""},{"name":"Yang Zong Zhe","avatar":""},{"name":"Li Chang Hong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324341);
