INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-sao-hy-vong-cua-amber', 'Ngôi Sao Hy Vọng Của Amber', 'All Together Now', 'https://phimimg.com/upload/vod/20231109-1/c535d6db15d5c545c4a24cdf5f6b46c9.jpg', 'https://phimimg.com/upload/vod/20231109-1/c9363b77b82f88d89b112355379649d8.jpg', '<p>Cô gái tuổi teen lạc quan, tài năng giấu kín bí mật lớn: Hiện cô vô gia cư và sống trên xe buýt. Khi bi kịch ập đến, liệu cô có học được cách nắm lấy bàn tay giúp đỡ?</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Auli''i Cravalho","avatar":""},{"name":"Rhenzy Feliz","avatar":""},{"name":"Justina Machado","avatar":""},{"name":"Judy Reyes","avatar":""},{"name":"Anthony Jacques","avatar":""},{"name":"Gerald Isaac Waters","avatar":""},{"name":"Taylor Richardson","avatar":""},{"name":"Fred Armisen","avatar":""},{"name":"Carol Burnett","avatar":""},{"name":"C.S. Lee","avatar":""},{"name":"Maria Park","avatar":""},{"name":"Eun-Chung Martha Han","avatar":""},{"name":"Jerzy Gwiazdowski","avatar":""},{"name":"Max Gail","avatar":""},{"name":"Darius Pierce","avatar":""},{"name":"Kurt Conroyd","avatar":""},{"name":"Li","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324341);
