INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-hoa-tien', 'Kẻ Săn Hỏa Tiễn', 'Rocket Hunter', 'https://phimimg.com/upload/vod/20231110-1/be8602a2b7d58a3d2bc8974cc886c967.jpg', 'https://phimimg.com/upload/vod/20231110-1/dafa8945f38d9eb662641dc2587e4514.jpg', '<p>Một phi công B-17 của Mỹ đã tình nguyện lái chiếc Messerschmitt 109 bay qua trung tâm nước Đức để cố gắng ngăn chặn người dân London khỏi bị khủng bố bởi tên lửa V-2 trong Thế chiến II. Phim mang đến câu chuyện về người phi công tuyệt vời này và anh trai của anh ta từ khi họ còn là những thiếu niên mơ ước được bay lên bầu trời cho đến những ngày đen tối của tháng 1 năm 1945.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sophie Adams","avatar":""},{"name":"Jezibell Anat","avatar":""},{"name":"Ronald Blanton","avatar":""},{"name":"Wayne Blanton","avatar":""},{"name":"Kayla Coppa","avatar":""},{"name":"Ryan Cruce","avatar":""},{"name":"Kelly Forbes","avatar":""},{"name":"Charlie Gabel","avatar":""},{"name":"Stephen Gilliam","avatar":""},{"name":"John H. Greene","avatar":""},{"name":"Barry W. Jerald Jr.","avatar":""},{"name":"Catherine Jerald","avatar":""},{"name":"Lin Laffitte","avatar":""},{"name":"Ethan McGee","avatar":""},{"name":"Brad Owens","avatar":""},{"name":"Corbin Rivers","avatar":""},{"name":"Eric E. Poe","avatar":""},{"name":"Jo","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324341);
