INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('one-night-in-miami', 'One Night in Miami...', 'One Night in Miami...', 'https://phimimg.com/upload/vod/20231110-1/d4045bde7624f3b7c393ff8b77a77f38.jpg', 'https://phimimg.com/upload/vod/20231110-1/5cdfe791d44c7ea08e5f850ab45663a3.jpg', '<p>Một tài khoản hư cấu của một đêm đáng kinh ngạc, nơi các biểu tượng Muhammad Ali, Malcolm X, Sam Cooke và Jim Brown đã tập hợp thảo luận về vai trò của họ trong phong trào dân quyền và biến động văn hóa của thập niên 60.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kingsley Ben-Adir","avatar":""},{"name":"Eli Goree","avatar":""},{"name":"Aldis Hodge","avatar":""},{"name":"Leslie Odom Jr.","avatar":""},{"name":"Joaquina Kalukango","avatar":""},{"name":"Nicolette Robinson","avatar":""},{"name":"Michael Imperioli","avatar":""},{"name":"Lawrence Gilliard Jr.","avatar":""},{"name":"Christian Magby","avatar":""},{"name":"Jeremy Pope","avatar":""},{"name":"Christopher Gorham","avatar":""},{"name":"Beau Bridges","avatar":""},{"name":"Lance Reddick","avatar":""},{"name":"Derek Roberts","avatar":""},{"name":"Emily Bridges","avatar":""},{"name":"Amon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324341);
