INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-bim-sua-cuc-manh', 'Bố Bỉm Sữa Cực Mạnh', 'Super Pacifier', 'https://phimimg.com/upload/vod/20231110-1/846af9de5e1a503ff44e8175fb9f018c.jpg', 'https://phimimg.com/upload/vod/20231110-1/1f03a898eefea596469ab21f2c04d747.jpg', '<p>Anh chàng mạnh mẽ trở thành bố bỉm sữa chiến đấu với tội phạm! Bộ đội đặc chủng Châu Dũng phạm phải sai lầm khiến cả đội hy sinh, từ đó dằn vặt khôn nguôi, suy sụp tinh thần. Ngày nọ, có hai đứa trẻ tìm đến trước cửa, thì ra là con của người đội trưởng đã mất. Châu Dũng bị ép thành bố bỉm sữa tạm thời, mà tên tội phạm ngày trước cũng từng bước tiếp cận Châu Dũng, giơ móng vuốt báo thù về phía bọn trẻ. Châu Dũng bị châm ngòi lửa giận trong lòng, quyết đấu một trận sống còn với tên tội phạm độc ác.</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Liu Geng-Hong","avatar":""},{"name":"Pei Jia Xin","avatar":""},{"name":"Chang Li-Wei","avatar":""},{"name":"Caesar Mao","avatar":""},{"name":"Wang Qing","avatar":""},{"name":"Wang Xiaolei","avatar":""},{"name":"Gao Xuanming","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324341);
