INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ludo-bon-cau-chuyen', 'Ludo: Bốn câu chuyện', 'Ludo', 'https://phimimg.com/upload/vod/20231110-1/1749c6de8c39b54408b94f9a69656110.jpg', 'https://phimimg.com/upload/vod/20231110-1/5ac154892554761da85077be2af19cd8.jpg', '<p>Từ sự tái xuất hiện của băng sex cho đến vali tiền phi nghĩa, bốn câu chuyện rất khác nhau lại chồng chéo bởi ý muốn của số phận, sự tình cờ, và một tên tội phạm lập dị.</p>', 'Full', 1, 'single', 'completed', 20, 2020, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Pankaj Tripathi","avatar":""},{"name":"Abhishek Bachchan","avatar":""},{"name":"Sanya Malhotra","avatar":""},{"name":"Aditya Roy Kapur","avatar":""},{"name":"Rajkummar Rao","avatar":""},{"name":"Fatima Sana Shaikh","avatar":""},{"name":"Rohit Saraf","avatar":""},{"name":"Pearle Maaney","avatar":""},{"name":"Inayat Verma","avatar":""},{"name":"Asha Negi","avatar":""},{"name":"Bhanu Uday","avatar":""},{"name":"Shalini Vatsa","avatar":""},{"name":"Ishtiyak Khan","avatar":""},{"name":"Anurag Basu","avatar":""},{"name":"Rahul Bagga","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324341);
