INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-dolittle-chuyen-phieu-luu-than-thoai', 'Bác Sĩ Dolittle: Chuyến Phiêu Lưu Thần Thoại', 'Dolittle', 'https://phimimg.com/upload/vod/20231110-1/5fb51f71d766133e391826b735fb61d2.jpg', 'https://phimimg.com/upload/vod/20231110-1/580a1a6347a8285a58f80b8271fd2860.jpg', '<p>Bộ phim kể về vị bác sĩ nổi tiếng Dolittle - người đàn ông có thể nói chuyện với động vật. Sau khi vợ mất, anh sống tách biệt với thế giới bên ngoài, chỉ đến khi nữ hoàng Anh bị bệnh, anh mới trở lại. Dolittle đã dấn thân trong hành trình phiêu lưu đầy nguy hiểm đến hòn đảo thần thoại để tìm ra phương thuốc chữa bệnh. Đồng hành cùng Dolittle là một học viên trẻ (Harry Collett từ phim Dunkirk) và nhóm động vật “ồn ào” gồm: anh khỉ đột hay lo lắng, cô vịt nhiệt tình nhưng ngốc ngếch, cặp đôi đà điểu hoài nghi hay cãi cùng chú gấu bắc cực lạc quan và một bác vẹt đầu đàn.</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Robert Downey Jr.","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Jessie Buckley","avatar":""},{"name":"Harry Collett","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Rami Malek","avatar":""},{"name":"John Cena","avatar":""},{"name":"Kumail Nanjiani","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Tom Holland","avatar":""},{"name":"Craig Robinson","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Selena Gomez","avatar":""},{"name":"Marion Cotillard","avatar":""},{"name":"Kasia Smu","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324341);
