INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jak-zosta-gwiazd', 'Jak zostać gwiazdą', 'Fierce', 'https://phimimg.com/upload/vod/20231110-1/dcfd9c58858ec581dbb410c62ee4aad6.jpg', 'https://phimimg.com/upload/vod/20231110-1/03c42cc9445407c30e1ed4138f858e76.jpg', '<p>Tài năng và niềm đam mê âm nhạc có thể đưa một người lên đỉnh cao. Tuy nhiên, trên đường đi sẽ có những cạm bẫy của giới showbiz.</p>', 'Full', 1, 'single', 'completed', 21, 2020, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Julia Kamińska","avatar":""},{"name":"Tomasz Karolak","avatar":""},{"name":"Adrian Majewski","avatar":""},{"name":"Maria Pakulnis","avatar":""},{"name":"Michal Piprowski","avatar":""},{"name":"Katarzyna Sawczuk","avatar":""},{"name":"Wojciech Solarz","avatar":""},{"name":"Anita Sokołowska","avatar":""},{"name":"Barbara Wypych","avatar":""},{"name":"Maciej Zakościelny","avatar":""},{"name":"Urszula Dudziak","avatar":""},{"name":"Krzysztof Ibisz","avatar":""},{"name":"Mariusz Bindula","avatar":""},{"name":"Sonia Bohosiewicz","avatar":""},{"name":"Aleksandra B","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324341);
