INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-am-cua-lang-thinh', 'Thanh Âm Của Lặng Thinh', 'Voice Of Silence', 'https://phimimg.com/upload/vod/20231109-1/66672db7d370a36ec8c7940f94d2a58d.jpg', 'https://phimimg.com/upload/vod/20231109-1/d69d604a284e89214bfd5e4862dad5d2.jpg', '<p>Thanh Âm Của Lặng Thinh xoay quanh hai người đàn ông Tae In (Yoo Ah In) và Chang Bok (Yoo Jae Myung) làm công việc dọn dẹp cho một tổ chức tội phạm. Cả hai vô tình bị cuốn vào một sự cố bất ngờ cùng một đứa trẻ bị bắt cóc. Suốt chiều dài bộ phim, một thanh niên không nói được, một người đàn ông trung niên ăn nói vô nghĩa như máy trả lời tự động và một đứa trẻ 11 tuổi bị bắt cóc đã tạo nên những tình huống hấp dẫn.</p>', 'Full', 1, 'single', 'completed', 25, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yoo Ah-in","avatar":""},{"name":"Yoo Jae-myung","avatar":""},{"name":"Moon Seung-ah","avatar":""},{"name":"Jo Ha-seok","avatar":""},{"name":"Kim Ja-young","avatar":""},{"name":"Kim Han-na","avatar":""},{"name":"Seo Dong-soo","avatar":""},{"name":"Lee Ga-eun","avatar":""},{"name":"Yoo Sung-joo","avatar":""},{"name":"Im Kang-sung","avatar":""},{"name":"Seung Hyung-bae","avatar":""},{"name":"Hong Seok-bin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324341);
