INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jackson-vo-gia', 'Jackson Vô Giá', 'Anything for Jackson', 'https://phimimg.com/upload/vod/20231109-1/2ccd00d234052b22c7ccfa8afe1cd9df.jpg', 'https://phimimg.com/upload/vod/20231109-1/8fba73f868b1e6bed70bc972ef9991bc.jpg', '<p>Phim là câu chuyện sau khi mất đi đứa cháu trai duy nhất của họ là Jackson trong một vụ tai nạn xe hơi, Audrey (Sheila McCarthy) cùng người chồng là bác sĩ Henry (Julian Richings) đã quá đau buồn. Họ quyết định bắt cóc một trong những bệnh nhân của Henry là người đang mang thai với ý định thực hiện một &quot;phép trừ tà ngược&quot;, đưa Jackson vào bên trong cô. Đứa trẻ của người bệnh nhân vẫn chưa chào đời. Tuy nhiên, Jackson không phải là hồn ma duy nhất mà cặp vợ chồng này mời vào nhà của họ. Đây là một cuộc chạy đua với thời gian để cặp vợ chồng, cũng như người phụ nữ mang thai, tìm cách thoát khỏi nỗi ám ảnh mà họ tự đặt ra</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Sheila McCarthy","avatar":""},{"name":"Julian Richings","avatar":""},{"name":"Konstantina Mantelos","avatar":""},{"name":"Josh Cruddas","avatar":""},{"name":"Yannick Bisson","avatar":""},{"name":"Lanette Ware","avatar":""},{"name":"Claire Cavalheiro","avatar":""},{"name":"Scott Cavalheiro","avatar":""},{"name":"Daxton William Lund","avatar":""},{"name":"Kaitlyn Leeb","avatar":""},{"name":"Rebecca LaMarche","avatar":""},{"name":"Jayne Eastwood","avatar":""},{"name":"Ai Barrett","avatar":""},{"name":"Marianne Sawchuk","avatar":""},{"name":"Mikaela Bisson","avatar":""},{"name":"Cal","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324341);
