INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('roma-qua-trinh-ghi-hinh', 'ROMA: QUÁ TRÌNH GHI HÌNH', 'ROAD TO ROMA', 'https://phimimg.com/upload/vod/20231109-1/4d50eba371437b2da58f36466910c2b6.jpg', 'https://phimimg.com/upload/vod/20231109-1/5c8b736593980ec2a6493ec260ef0e6e.jpg', '<p>Đạo diễn Alfonso Cuarón suy ngẫm về ký ức ấu thơ, dấu ấn của thời đại và cả những lựa chọn sáng tạo đã định hình nên &quot;ROMA&quot; – bộ phim từng mang về cho ông giải Oscar.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Alfonso Cuarón","avatar":""},{"name":"Eugenio Caballero","avatar":""},{"name":"Yalitza Aparicio","avatar":""},{"name":"Marina de Tavira","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324341);
