INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('samsam-anh-hung-nhi-tap-su', 'SamSam: Anh Hùng Nhí Tập Sự', 'SamSam', 'https://phimimg.com/upload/vod/20231109-1/d5cc04cf840a86e824aa4d259fbb4575.jpg', 'https://phimimg.com/upload/vod/20231109-1/449d716bb225952817be0cebf85f01c9.jpg', '<p>Nhóc tì siêu quậy Samsam có tất cả mọi thứ mà bao đứa trẻ trên hành tinh Sam đều mơ ước: bố mẹ là hai siêu anh hùng nổi tiếng, học tập ở một ngôi trường danh giá chuyên đào tạo các thế hệ siêu nhân tương lai, thậm chí Samsam còn có hẳn một đĩa bay riêng để vi vu khắp nơi khắp chốn. Thế nhưng, cậu bé lại không có chút siêu năng lực nào, hoàn toàn khác biệt với tất cả các thành viên trong gia đình cũng như bạn bè đồng trang lứa. Bố mẹ lo lắng, bè bạn trêu ghẹo, Samsam bắt đầu hành trình tới hành tinh Marth bí ẩn cùng người bạn mới Mega, quyết tâm tìm kiếm sức mạnh ẩn tiềm của bản thân mình.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2020, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Isaac Lobé-Lebel","avatar":""},{"name":"Lior Chabbat","avatar":""},{"name":"Jérémy Prévost","avatar":""},{"name":"Sébastien Desjours","avatar":""},{"name":"Léopold Vom Dorp","avatar":""},{"name":"Victoire Pauwels","avatar":""},{"name":"Léovanie Raud","avatar":""},{"name":"Laurent Maurel","avatar":""},{"name":"Marie-Eugénie Maréchal","avatar":""},{"name":"Philippe Spiteri","avatar":""},{"name":"Simon Brunner","avatar":""},{"name":"Françoise Pavy","avatar":""},{"name":"Magali Rosenzweig","avatar":""},{"name":"Julien Crampon","avatar":""},{"name":"David Macalu","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324341);
