INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-thousand-cuts', 'A Thousand Cuts', 'A Thousand Cuts', 'https://phimimg.com/upload/vod/20231109-1/2f3ce2739284920df6af9817c71da37f.jpg', 'https://phimimg.com/upload/vod/20231109-1/e2160d08ec8f4dd212b47561949bd509.jpg', '<p>Không nơi nào là sự xói mòn toàn diện trên toàn thế giới, được thúc đẩy bởi các chiến dịch biến mất phương tiện truyền thông xã hội, rõ ràng hơn rõ ràng so với chế độ độc đoán của Tổng thống Philippines Rodrigo Duter. Nhà báo Maria Ressa đặt các công cụ của báo chí miễn phí và tự do của cô ấy trên tuyến bảo vệ sự thật và dân chủ.</p>', 'Full', 1, 'single', 'completed', 16, 2020, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Maria Ressa","avatar":""},{"name":"Pia Ranada","avatar":""},{"name":"Amal Clooney","avatar":""},{"name":"Patricia Evangalista","avatar":""},{"name":"George Clooney","avatar":""},{"name":"Leni Robredo","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324341);
