INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-cua-angela-2', 'Giáng sinh của Angela 2', 'Angela''s Christmas 2', 'https://phimimg.com/upload/vod/20231108-1/b6494b92d11a87c549a29d300f330835.jpg', 'https://phimimg.com/upload/vod/20231108-1/f7f5b5c3f70366bad07da38d868eb5a9.jpg', '<p>Khi bố đang làm việc rất xa ở nước Úc, Angela quyết tâm tiến hành một kế hoạch – và một điều ước chân thành – để đoàn tụ gia đình mình vào dịp lễ.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lucy O''Connell","avatar":""},{"name":"Ruth Negga","avatar":""},{"name":"Moe Dunford","avatar":""},{"name":"Pat Kinevane","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Caitríona Balfe","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324341);
