INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-hiep-trung-quoc', 'Phi Hiệp Trung Quốc', 'Chinese Fighting Man', 'https://phimimg.com/upload/vod/20231108-1/9132a86e1a7a71356e89fdb9a8d13d8b.jpg', 'https://phimimg.com/upload/vod/20231108-1/ec6bcaa81c198d45d739a367f19618b9.jpg', '<p>Shipper Lý An Toàn vì muốn để dành đủ tiền phẫu thuật cho con gái, nên đã liều mình làm việc sáng thì giao hàng, tối về lại livestream bán hàng. Trong khoảng thời gian này thường xuyên xảy ra sự cố, hàng loạt chuyện khiến người ta cười ra nước mắt. Tuy phải chịu rất nhiều áp lực, nhưng vẫn không ngừng giúp đỡ những người xung quanh, con người giản dị chăm chỉ nên anh ấy đã thực hiện được ước mơ của mình.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Xu Juncong","avatar":""},{"name":"Li Qi","avatar":""},{"name":"Yuxi Chen","avatar":""},{"name":"Dong Hai","avatar":""},{"name":"黄鑫","avatar":""},{"name":"Zhao Peilin","avatar":""},{"name":"Xu Chunni","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324341);
