INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-doi-toi', 'Thay đổi tôi', 'Alter Me', 'https://phimimg.com/upload/vod/20231108-1/9fb4eb17051274bfd6e9d8b670577917.jpg', 'https://phimimg.com/upload/vod/20231108-1/c9c765dc3121514167c9ce6885cb96c3.jpg', '<p>Để kết nối tốt hơn với người khác và với cảm xúc của chính mình, một quản lý nhân sự tìm tới chàng trai bao đắt khách để được chỉ bảo, anh mau chóng mở cửa trái tim cô.</p>', 'Full', 1, 'single', 'completed', 19, 2020, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Enchong Dee","avatar":""},{"name":"Jasmine Curtis-Smith","avatar":""},{"name":"JC Santos","avatar":""},{"name":"Via Antonio","avatar":""},{"name":"Royce Cabrera","avatar":""},{"name":"Kate Alejandrino","avatar":""},{"name":"Victor Silayan","avatar":""},{"name":"Richard Quan","avatar":""},{"name":"Rhed Bustamante","avatar":""},{"name":"Lee Paguta","avatar":""},{"name":"Minnie Nato","avatar":""},{"name":"Marty Marcelo","avatar":""},{"name":"Barbara Ruaro","avatar":""},{"name":"Sunshine Teodoro","avatar":""},{"name":"Evelyn Mayores","avatar":""},{"name":"Dindo Arroyo","avatar":""},{"name":"Iana Bernarde","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324341);
