INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-pho-tau', 'Cuộc Chiến Phố Tàu', 'Wars in Chinatown', 'https://phimimg.com/upload/vod/20231108-1/1405980f2dc1526af9c9bc96aaf62f45.jpg', 'https://phimimg.com/upload/vod/20231108-1/b2210491e42738febceadb5a3c859489.jpg', '<p>Sư phụ Diệp Trác một mình chống lại thế lực đen tối, nhưng lại bất lực chứng kiến cái chết của vợ mình. Khi phát hiện tên thủ lĩnh của băng xã hội đen đã trốn ra nước ngoài điều trị vết thương, Diệp Trác liền đi đến nước đó, quyết một trận sinh tử với băng nhóm có tên &quot;Siêu võ sĩ&quot;. Trận huyết chiến nhuốm đỏ cả khu phố người Hoa.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wang Hong","avatar":""},{"name":"Li Binglei","avatar":""},{"name":"Zhao Wang","avatar":""},{"name":"Kaori Suzuki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324341);
