INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-da-bi-lua-cau-chuyen-that-ve-gioi-tranh-gia', 'Bạn đã bị lừa: Câu chuyện thật về giới tranh giả', 'Made You Look: A True Story About Fake Art', 'https://phimimg.com/upload/vod/20231108-1/0ac4a98dfd7469680da3698ffc709607.jpg', 'https://phimimg.com/upload/vod/20231108-1/0322bcf29ca16ff8a22da85558b50692.jpg', '<p>Ả bước vào phòng trưng bày ở New York với lô kiệt tác nghệ thuật vô danh. Từ đó, câu chuyện về lòng tham, ý chí và vụ lừa đảo giá trị lớn trong giới nghệ thuật bắt đầu.</p>', 'Full', 1, 'single', 'completed', 16, 2020, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Ann Freedman","avatar":""},{"name":"M.H. Miller","avatar":""},{"name":"Perry Amsellem","avatar":""},{"name":"Patricia Cohen","avatar":""},{"name":"Luke Nikas","avatar":""},{"name":"Eleanore De Sole","avatar":""},{"name":"Blake Gopnik","avatar":""},{"name":"Jack Flam","avatar":""},{"name":"Charles Schmerler","avatar":""},{"name":"Jeffrey Taylor","avatar":""},{"name":"Michael Schnayerson","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324341);
