INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-da-bi-lua-cau-chuyen-that-ve-gioi-tranh-gia', 'Bạn đã bị lừa: Câu chuyện thật về giới tranh giả', 'Made You Look: A True Story About Fake Art', 'bạn đã bị lừa: câu chuyện thật về giới tranh giả made you look: a true story about fake art ann freedman m.h. miller perry amsellem patricia cohen luke nikas eleanore de sole blake gopnik jack flam charles schmerler jeffrey taylor michael schnayerson ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mang-luoi-thu-ghet', 'Mạng Lưới Thù Ghét', 'The Hater', 'https://phimimg.com/upload/vod/20231108-1/dc17265e46cf6cc12036f2b26317b675.jpg', 'https://phimimg.com/upload/vod/20231108-1/372e892f4a88bd10b7e1a0e6e5ca796e.jpg', '<p>Tác phẩm điện ảnh Ba Lan khai thác nhiều vấn đề nóng hổi như phát ngôn kích động thù hận, tin giả, bạo lực mạng, xung đột sắc tộc… và khiến người xem phải suy ngẫm.
 Gã trai hai mặt kiếm tìm thành công trong thế giới đen tối của chiến thuật bôi nhọ trên mạng, nhưng những lời đả kích ảo sớm dẫn đến hậu quả tàn khốc ngoài đời thực.</p>', 'Full', 1, 'single', 'completed', 22, 2020, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Maciej Musiałowski","avatar":""},{"name":"Vanessa Aleksander","avatar":""},{"name":"Danuta Stenka","avatar":""},{"name":"Jacek Koman","avatar":""},{"name":"Agata Kulesza","avatar":""},{"name":"Maciej Stuhr","avatar":""},{"name":"Adam Gradowski","avatar":""},{"name":"Piotr Biedroń","avatar":""},{"name":"Jędrzej Wielecki","avatar":""},{"name":"Jan Hrynkiewicz","avatar":""},{"name":"Martynika Kosnica","avatar":""},{"name":"Wiktoria Filus","avatar":""},{"name":"Iga Krefft","avatar":""},{"name":"Viet Anh Doan","avatar":""},{"name":"Sebastian Szalaj","avatar":""},{"name":"Kacper Dykba","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324341);
