INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-moc-lan-vo-song', 'Hoa Mộc Lan Vô Song', 'Matchless Mulan', 'null', 'https://phimimg.com/upload/vod/20231108-1/99e02aaadb31da9feea1485f781fd353.jpg', '<p>Mộc Lan giỏi võ và có tài thao lược. Từ nhỏ, cô đã yêu thích võ thuật và sớm bộc lộ tố chất. Sau khi biết tin cha già bệnh yếu phải tiếp tục đi tòng quân, Mộc Lan quyết định cải trang nam nhi để thay cha đi đánh giặc. Nhờ bản lĩnh và tài năng, cô được phong chức và có nhiều chiến thắng vang dội. Tuy nhiên, cô lại bị Khôn Bằng hãm hại, cuộc đời thay đổi sang một trang mới.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hu Xue''er","avatar":""},{"name":"Jerry Wu","avatar":""},{"name":"Wei Wei","avatar":""},{"name":"Shang Tielong","avatar":""},{"name":"Chu Xiaolong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324341);
