INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-moc-lan-vo-song', 'Hoa Mộc Lan Vô Song', 'Matchless Mulan', 'hoa mộc lan vô song matchless mulan hu xue''er jerry wu wei wei shang tielong chu xiaolong ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-ke-chi-dai', 'Ô Kê, Chị Đại', 'Okay! Madam', 'https://phimimg.com/upload/vod/20231108-1/a01b37cf2d1e5bf9611402a3288792d9.jpg', 'https://phimimg.com/upload/vod/20231108-1/2aa1003d55ee58bea958d3764ca0b559.jpg', '<p>Phim xoay quanh chuyến du lịch vô cùng “nhớ đời” của cặp vợ chồng Mi-Young (Uhm Jung-Hwa) và Seok-Hwan (Park Sung-Woong). Cả hai đều là điệp viên kỳ cựu nhưng đã giải nghệ để làm những người lao động bình dân - vợ mở một quầy bánh quẩy, chồng thì sửa máy tính dạo. Một ngày nọ, Seok-Hwan trúng giải là một chuyến đi chơi miễn phí đến Hawaii. Tuy nhiên, thật xui xẻo khi chuyến bay ra nước ngoài đầu tiên của hai vợ chồng đã bị khủng bố khống chế.
 Lúc bấy giờ, bản năng anh hùng của Mi-Young - Seok-Hwan bỗng trỗi dậy, họ bắt đầu tìm cách giải cứu các hành khách đang bị khủng bố bắt làm con tin. Tuy nhiên, trong sự hỗn loạn của trận không tặc, Mi-Young gặp lại Cheol-Seung (Lee Sang-Yoon) - một đồng nghiệp trong quá khứ, cũng là mối đe dọa lớn nhất về thân phận đặc biệt của cô. Lo sợ bóng ma của ngày cũ sẽ quay về gây ảnh hưởng đến gia đình nhỏ, một mặt Mi-Young phải giải cứu chuyến bay khỏi sự tấn công của bọn khủng bố, một mặt phải nghĩ cách giải quyết dứt điểm quá khứ của chính mình.</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Uhm Jung-hwa","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Lee Sang-yun","avatar":""},{"name":"Bae Jung-nam","avatar":""},{"name":"Lee Sun-bin","avatar":""},{"name":"Jeong Su-bin","avatar":""},{"name":"Yu Ha-jun","avatar":""},{"name":"Park Ji-il","avatar":""},{"name":"Choi Jin-ho","avatar":""},{"name":"Kim Pub-lae","avatar":""},{"name":"Ju Seok-tae","avatar":""},{"name":"Kim Byeong-ok","avatar":""},{"name":"Kim Hye-eun","avatar":""},{"name":"Lim Hyun-sung","avatar":""},{"name":"Jeon Soo-kyung","avatar":""},{"name":"Park So-Ri","avatar":""},{"name":"Lee Si-won","avatar":""},{"name":"Song Chi-hoon","avatar":""},{"name":"Lee Jung-","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324341);
