INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-giai-cuu-rong-san-rong-vang', 'Biệt đội giải cứu rồng: Săn Rồng Vàng', 'Dragons: Rescue Riders: Hunt for the Golden Dragon', 'https://phimimg.com/upload/vod/20231108-1/d851e932bef317b2281f607d2f32f769.jpg', 'https://phimimg.com/upload/vod/20231108-1/80fcc6d68b691b20e8feea94e18e4c12.jpg', '<p>Cuộc săn tìm kho báu có một không hai trong đời đã đến với Biệt Đội Giải Cứu. Liệu đội có tìm được trứng rồng vàng quý giá và bảo vệ báu vật đó khỏi lũ hải tặc xấu xa?</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Noah Kaye Bentley","avatar":""},{"name":"Zach Callison","avatar":""},{"name":"Nicolas Cantu","avatar":""},{"name":"Skai Jackson","avatar":""},{"name":"Marsai Martin","avatar":""},{"name":"Andre Robinson","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Mary Elizabeth McGlynn","avatar":""},{"name":"Brennley Brown","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chương Trình Truyền Hình","slug":"chuong-trinh-truyen-hinh","id":"53182bd3a1423cefa5048d6e8709b0c6"}]', '[]', 1784690324341);
