INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-moc-lan-giai-cuu-dai-mac', 'Hoa Mộc Lan: Giải Cứu Đại Mạc', 'Mulan Legend', 'https://phimimg.com/upload/vod/20231108-1/a60fd29c8e7df218ead29fbc0fee29c6.jpg', 'https://phimimg.com/upload/vod/20231108-1/dd48b4894d60519f702958702e9734af.jpg', '<p>Hoa Mộc Lan: Giải Cứu Đại Mạc - Mulan Legend kể về nữ chiến thần tung hoành thành Vân Trung! Hoa Mộc Lan lập lời thề sinh tử, to gan dùng tử tù Mộ Dung Địch giải cứu công chúa. Hoa Mộc Lan và tiểu đội ám sát của mình đối mặt với truy sát, bị ép vào đường cùng, liệu số phận Mộc Lan và đồng đội sẽ đi đâu về đâu?</p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Dong","avatar":""},{"name":"Gu Shangwei","avatar":""},{"name":"Yuming Du","avatar":""},{"name":"Sun Jiaolong","avatar":""},{"name":"Xu Jiawei","avatar":""},{"name":"Long Yangyang","avatar":""},{"name":"Guan Aini","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324341);
