INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-bau-sieu-ngau', 'Mẹ Bầu Siêu Ngầu', 'More Than Family', 'https://phimimg.com/upload/vod/20231108-1/168dd0358de224f14d5f2a53ec6e5ba9.jpg', 'https://phimimg.com/upload/vod/20231108-1/b283a894988f51667ba4456aa24abd34.jpg', '<p>Khi To Il lên 5 tuổi, mẹ cô bé tái hôn và họ rời thành phố Daegu để bắt đầu sống ở Seoul. Giờ đây To Il đã là thiếu nữ 21 tuổi và đang là sinh viên đại học. Cô hẹn hò với một cậu trai 19 tuổi tên Ho Hoon (Shin Jae Hwi) mà cô đang làm gia sư cho. To Il mang bầu và mãi đến tháng thứ 5 cô mới bắt đầu nói chuyện này cho mẹ mình và bố dượng biết. Cô nàng quyết định sinh con và cưới Ho Hoon bất chấp sự phản đối của gia đình. Không có ai bên cạnh ủng hộ, To Il quyết định đi tìm bố ruột của mình để nhờ giúp đỡ. Liệu chuyện hành trình đi tìm bố của To Il có thuận lợi?</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Krystal Jung","avatar":""},{"name":"Jang Hye-jin","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"Shin Jae-hwi","avatar":""},{"name":"Lee Hae-yeong","avatar":""},{"name":"Kang Mal-geum","avatar":""},{"name":"Nam Moon-chul","avatar":""},{"name":"Jang Hat-sal","avatar":""},{"name":"Kim Joon Bum","avatar":""},{"name":"Kim Mi-hyang","avatar":""},{"name":"Lee Ju-won","avatar":""},{"name":"Shin Mi-yeong","avatar":""},{"name":"Lee Seung-chul","avatar":""},{"name":"Ahn Jae-Min","avatar":""},{"name":"Park So-eun","avatar":""},{"name":"Kim Neul-me","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324341);
