INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-quy-dai-duong', 'Trùng Quỷ Đại Dương', 'Sea Fever', 'https://phimimg.com/upload/vod/20231103-1/ed39be1cca799654a27d8c119b8410c4.jpg', 'https://phimimg.com/upload/vod/20231103-1/9958635f630ce36946580f9572bcfd32.jpg', '<p>Phim xoay quanh một tuần thực nghiệm ngoài khơi của nghiên cứu sinh hải dương học Siobhán trên một chuyến tàu đánh cá. Hiểm nguy bỗng ập tới bất ngờ khi một loài sinh vật biển bí ẩn bắt đầu tấn công con tàu, rồi các thủy thủ dần dần bị nhiễm bệnh lạ. Lênh đênh và cô độc giữa Đại Tây Dương sâu thẳm, làm cách nào để Siobhán tự cứu lấy chính mình và mọi người trước khi quá muộn?</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Hermione Corfield","avatar":""},{"name":"Ardalan Esmaili","avatar":""},{"name":"Olwen Fouéré","avatar":""},{"name":"Jack Hickey","avatar":""},{"name":"Elie Bouakaze","avatar":""},{"name":"Dougray Scott","avatar":""},{"name":"Connie Nielsen","avatar":""},{"name":"Dag Malmberg","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324341);
