INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('john-tung-tim-cach-lien-lac-nguoi-ngoai-hanh-tinh', 'John từng tìm cách liên lạc người ngoài hành tinh', 'John Was Trying to Contact Aliens', 'https://phimimg.com/upload/vod/20231103-1/11f1a537cd95162e652967b8acbf671e.jpg', 'https://phimimg.com/upload/vod/20231103-1/c931bf68ddefab838a8b3a2e1ef3c02f.jpg', '<p>Chuyên gia điện tử nơi thôn dã phát tín hiệu vô tuyến ra ngoài vũ trụ và tìm dấu hiệu của người ngoài hành tinh, nhưng có được kết nối quan trọng hơn ngay trên Trái đất.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Shepherd","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324341);
