INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-giac-mo', 'Thợ Săn Giấc Mơ', 'Dream Hunting', 'null', 'https://phimimg.com/upload/vod/20231103-1/21b549c76480622baafd8a45cfc597b2.jpg', '<p>Thợ Săn Giấc Mơ - Dream Hunting (2021) thuộc thể loại khoa học viễn tưởng, siêu nhiên, hài hước và hành động của điện ảnh Trung Quốc có thời lượng 90 phút. Lấy bối cảnh trong tương lai vào năm 2050, Lam Tiểu Vỹ một nhà nghiên cứu đã tìm ra kỹ thuật mới. Sử dụng một chiếc mũ đặc chế, sóng não của hai người khác nhau sẽ được liên kết và có sự kết nối giữa giấc mơ với đời thực. Để phá được vụ án đang gặp phải, Cảnh sát Từ đã tìm tới Tiểu Vỹ. Sau khi nghe sự việc của vụ án có liên quan tới sự hôn mê của mẹ, Tiểu Vỹ đồng ý Thu gọn</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Xiaoliang","avatar":""},{"name":"Mi Mi","avatar":""},{"name":"Huo Weimin","avatar":""},{"name":"Yuming Du","avatar":""},{"name":"Zhou Haodong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324341);
