INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-dai-cua-jackie', 'Võ Đài Của Jackie', 'Bruised', 'https://phimimg.com/upload/vod/20231103-1/1e34288724fd77ce438152f48ee789af.jpg', 'https://phimimg.com/upload/vod/20231103-1/08ceea2c6bd279ad37505309f22c4ad6.jpg', '<p>Nhiều năm sau trận thua mất mặt, một võ sĩ MMA chớp cơ hội cuối để chuộc lỗi khi đứa con trai nhỏ mà cô từ bỏ giờ xuất hiện trở lại trong đời cô.</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Halle Berry","avatar":""},{"name":"Adan Canto","avatar":""},{"name":"Sheila Atim","avatar":""},{"name":"Danny Boyd Jr.","avatar":""},{"name":"Adriane Lenox","avatar":""},{"name":"Shamier Anderson","avatar":""},{"name":"Stephen McKinley Henderson","avatar":""},{"name":"Valentina Shevchenko","avatar":""},{"name":"Lela Loren","avatar":""},{"name":"Nikolai Nikolaeff","avatar":""},{"name":"Denny Dillon","avatar":""},{"name":"Jacob Crespo","avatar":""},{"name":"Jennifer Dugwen Chieng","avatar":""},{"name":"Shawna Hamic","avatar":""},{"name":"Mark Cayne","avatar":""},{"name":"Julio A.","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324341);
