INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-chau-thien-khong-thanh-quay-nguoc-thoi-gian', 'Cửu Châu Thiên Không Thành: Quay Ngược Thời Gian', 'Novoland: The Castle in the Sky - Time Reversal', 'https://phimimg.com/upload/vod/20231103-1/94ee92715d901882bc3ffdc865488880.jpg', 'https://phimimg.com/upload/vod/20231103-1/c02e004252be5077eb88330bab369b86.jpg', '<p>Sau khi trận chiến ở Thiên Không Thành kết thúc, Vũ hoàng Phong Nhẫn phát động cuộc chiến tranh với Nhân tộc. Binh lính tiến đến thành Lương Châu, thấy rằng Nhân tộc bất lực không lật ngược được tình thế, nữ bá tước Phương Kỳ Vũ cố gắng sử dụng cỗ máy thời gian “Lưu Niên Chuyển” quay về quá khứ để giết chết Phong Nhẫn thời trẻ để nhằm xoay chuyển tình thế hiện tại.</p>', 'Full', 1, 'single', 'completed', 17, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Danni Chong","avatar":""},{"name":"Chai Ge","avatar":""},{"name":"Wang Yuwen","avatar":""},{"name":"Zhang Tang","avatar":""},{"name":"Liang Yolin","avatar":""},{"name":"Xie Bo","avatar":""},{"name":"Li Daikun","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324341);
