INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-xom-tot-bung', 'Hàng Xóm Tốt Bụng', 'Next Door Neighbor', 'https://phimimg.com/upload/vod/20231103-1/90196874f46f74c9d5498bbee1145503.jpg', 'https://phimimg.com/upload/vod/20231103-1/d65a713ce633be14a62865a020df589c.jpg', '<p>Lấy bối cảnh Hàn Quốc những năm 1980s, nội dung phim kể về một đội nghe trộm do Yoo Dae Kwon (Jung Woo) đứng đầu nhận chỉ thị của chính phủ theo dõi ứng cử viên tổng thống Lee Ui Sik (Oh Dal Soo) và các thành viên gia đình của ông đang bị quản thúc sau khi hồi hương từ nước ngoài. Các thành viên của đội nghe trộm cải trang thành một gia đình, chuyển đến nhà bên cạnh Lee Ui Sik, giả làm hàng xóm và bắt đầu hoạt động giám sát. Sau đó, trong vô số nội dung nghe lén có vẻ bình thường, bí mật từ từ lộ ra. Yoo Dae Kwon dần bị tính cách của Lee Ui Sik chinh phục và quay sang ủng hộ ông, giúp Lee Ui Sik lật ngược tình thế bất lợi trong cuộc tổng tuyển cử.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jung Woo","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Kim Hee-won","avatar":""},{"name":"Kim Byung-chul","avatar":""},{"name":"Lee Yu-bi","avatar":""},{"name":"Cho Hyun-chul","avatar":""},{"name":"Kim Sun-kyung","avatar":""},{"name":"Yeom Hye-ran","avatar":""},{"name":"Ji Seung-hyun","avatar":""},{"name":"Jung Hyeon-jun","avatar":""},{"name":"Jung Hee-tae","avatar":""},{"name":"Kim Ki-chun","avatar":""},{"name":"Kim Se-dong","avatar":""},{"name":"Kim Dong-gyu","avatar":""},{"name":"Han Seung-ju","avatar":""},{"name":"Park Chul-min","avatar":""},{"name":"Sim Yi-young","avatar":""},{"name":"Yoo Jeong-ho","avatar":""},{"name":"Hwang By","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324341);
