INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-he-tat-nguyen-tan-nhung-khong-phe', 'Trại hè tật nguyền: Tàn nhưng không phế', 'Crip Camp: A Disability Revolution', 'https://phimimg.com/upload/vod/20231102-1/20e73b6bd9dca376c65b33ddcb083209.jpg', 'https://phimimg.com/upload/vod/20231102-1/3f0c3d3494dca145fc0def5244e82dda.jpg', '<p>Một trại hè đột phá thôi thúc nhóm thanh thiếu niên khuyết tật tham gia gây dựng một phong trào, từ đó tạo ra con đường mới hướng tới sự bình đẳng lớn lao hơn nữa.</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Lebrecht","avatar":""},{"name":"Lionel Je''Woodyard","avatar":""},{"name":"Joseph O''Conor","avatar":""},{"name":"Ann Cupolo Freeman","avatar":""},{"name":"Denise Sherer Jacobson","avatar":""},{"name":"Larry Allison","avatar":""},{"name":"Judith Heumann","avatar":""},{"name":"Ellie Abrashkin","avatar":""},{"name":"Jean Malafronte","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324341);
