INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trai-he-tat-nguyen-tan-nhung-khong-phe', 'Trại hè tật nguyền: Tàn nhưng không phế', 'Crip Camp: A Disability Revolution', 'trại hè tật nguyền: tàn nhưng không phế crip camp: a disability revolution james lebrecht lionel je''woodyard joseph o''conor ann cupolo freeman denise sherer jacobson larry allison judith heumann ellie abrashkin jean malafronte ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-quai-vat-du-hoc-sinh', 'Học Viện Quái Vật: Du Học Sinh', 'Cranston Academy: Monster Zone', 'https://phimimg.com/upload/vod/20231101-1/99d05e52803737b744e9635745b34ec8.jpg', 'https://phimimg.com/upload/vod/20231101-1/c3676cd6a60b6a787eab4ed352757ab5.jpg', '<p>Phim xoay quanh câu chuyện về Danny Dawkins, một thần đồng trẻ tuổi nhưng chưa từng một lần được công nhận. Khi bất ngờ được nhận học bổng vào Học viện Cranston, một trường nội trú bí mật danh giá dành cho các thiên tài, Danny coi đó như một nơi mà trí thông minh của mình sẽ được công nhận và là nơi cuối cùng cậu có cơ hội nhập học. Tuy nhiên, cuộc sống trong một ngôi trường toàn thiên tài thật sự rất khắc nghiệt, nơi mà nếu bạn đạt 99% số điểm cũng coi như thất bại. Trong nhiệm vụ chứng minh trí thông minh của mình với các bạn trong trường, Danny đã vô tình mở ra một cánh cổng dẫn đến một chiều không gian khác và giải phóng một loạt quái vật vào trường - nhãn cầu bay khổng lồ, những con chó hai đầu và một chiếc xúc tu màu hồng nhầy nhụa,… Cùng với người bạn cùng phòng – Liz và một giáo sư nửa người nửa bướm có biệt danh là Mothman, Danny phải vượt qua những con quỷ của chiều không gian thứ 5 và những khả năng còn tiềm ẩn bên trong mình để cứu ngôi trường.&quot;</p>', 'Full', 1, 'hoathinh', 'completed', 21, 2020, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jamie Bell","avatar":""},{"name":"Ruby Rose","avatar":""},{"name":"Idzi Dulkiewicz","avatar":""},{"name":"Ellie Piercy","avatar":""},{"name":"Terry Mynott","avatar":""},{"name":"Ryan Samson","avatar":""},{"name":"Ellie Pierce","avatar":""},{"name":"Bianca Hendrickse","avatar":""},{"name":"Abigail Morgan","avatar":""},{"name":"Luke Kempner","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu",