INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-cuong-sat', 'Kẻ Cuồng Sát', 'Unhinged', 'https://phimimg.com/upload/vod/20231031-1/f725d7c72159e8eb1b3765e53623c081.jpg', 'https://phimimg.com/upload/vod/20231031-1/5797ee8b79f06b327fe8dfbd0bace20d.jpg', '<p>Rachel (Caren Pistorius thủ vai) là một người mẹ đơn thân đang phải đối mặt với nhiều những vấn đề trong cuộc sống. Không giữ được bình tĩnh trong một buổi sáng đột nhiên bị mất việc, cô vô tình nặng lời với một người đàn ông (Russell Crowe) trên chiếc xe chắn đường mình. Rachel không hề biết rằng gã đàn ông mà cô vô tình gây hấn chính là một kẻ có vấn đề về tâm lý, điên cuồng, tàn độc và sẵn sàng “dạy dỗ” người khác bằng những bài học chết người. Cô và những người thân yêu của mình liệu có toàn mạng trong cuộc rượt đuổi đó?</p>', 'Full', 1, 'single', 'completed', 11, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Russell Crowe","avatar":""},{"name":"Caren Pistorius","avatar":""},{"name":"Gabriel Bateman","avatar":""},{"name":"Jimmi Simpson","avatar":""},{"name":"Austin P. McKenzie","avatar":""},{"name":"Juliene Joyner","avatar":""},{"name":"Stephen Louis Grush","avatar":""},{"name":"Anne Leighton","avatar":""},{"name":"Michael Papajohn","avatar":""},{"name":"Lucy Faust","avatar":""},{"name":"Devyn A. Tyler","avatar":""},{"name":"Andrew Morgado","avatar":""},{"name":"Samantha Beaulieu","avatar":""},{"name":"Sylvia Grace Crim","avatar":""},{"name":"Gretchen Koerner","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324342);
