INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-cong-ly-bong-dem-cuoc-chien-apokolips', 'Liên Minh Công Lý Bóng Đêm: Cuộc Chiến Apokolips', 'Justice League Dark: Apokolips War', 'https://phimimg.com/upload/vod/20231030-1/135cca929048e195f564011824534b97.jpg', 'https://phimimg.com/upload/vod/20231030-1/bfe5bcbb0faae669cb7a7d8a2c5bce07.jpg', '<p>Trái đất bị tàn phá nặng nề sau cuộc chiến của bạo chúa Darkseid với Liên minh Công lý và gần như mọi siêu anh hùng đều bị tiêu diệt. Giờ đây, những siêu anh hùng còn lại - Justice League, Teen Titans, Suicide Squad sẽ phải tập hợp lại, lập chiến lược và tiến hành cuộc chiến với Darkseid để cứu lấy trái đất - Cuộc chiến chấm dứt mọi cuộc chiến.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Ryan","avatar":""},{"name":"Jerry O''Connell","avatar":""},{"name":"Taissa Farmiga","avatar":""},{"name":"Jason O''Mara","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Stuart Allan","avatar":""},{"name":"Rebecca Romijn","avatar":""},{"name":"Rainn Wilson","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Shemar Moore","avatar":""},{"name":"Christopher Gorham","avatar":""},{"name":"Ray Chase","avatar":""},{"name":"Camilla Luddington","avatar":""},{"name":"Hynden Walch","avatar":""},{"name":"Liam McIntyre","avatar":""},{"name":"Roger Cross","avatar":""},{"name":"John DiMa","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324342);
