INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lien-minh-cong-ly-bong-dem-cuoc-chien-apokolips', 'Liên Minh Công Lý Bóng Đêm: Cuộc Chiến Apokolips', 'Justice League Dark: Apokolips War', 'liên minh công lý bóng đêm: cuộc chiến apokolips justice league dark: apokolips war matt ryan jerry o''connell taissa farmiga jason o''mara rosario dawson stuart allan rebecca romijn rainn wilson tony todd shemar moore christopher gorham ray chase camilla luddington hynden walch liam mcintyre roger cross john dima ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-tich-quy-am', 'Tàn Tích Quỷ Ám', 'Relic', 'https://phimimg.com/upload/vod/20231026-1/2550844aa8525527a08411cc62727509.jpg', 'https://phimimg.com/upload/vod/20231026-1/14379d0f0163cf3f81541da974c8806a.jpg', '<p>Nội dung phim xoay quanh câu chuyện về ba người phụ nữ, thuộc ba thế hệ khác nhau bị cuốn vào vòng xoáy của những điều hắc ám, xấu xa trú ngụ trong ngôi nhà của mình. Nghe tin bà quả phụ Edna (Robyn Nevin) mất tích, cô con gái Kay (Emily Mortimer) và cháu gái Sam (Bella Heathcote) vội vã trở về căn nhà ờ vùng quê Melbourne để tìm kiếm. Không lâu sau đó, Edna đột ngột trở về như chưa từng có chuyện gì xảy ra. Ban đầu bà có vẻ ổn, cáu gắt khi bị đối xử như một người không bình thường nhưng rồi bà bắt đầu có những hành vi kỳ quặc và những điều quái gở, kì dị cứ liên tiếp xảy ra khiến cho căn nhà của ba người phụ nữ dần trở thành nỗi kinh hoàng. Kay buộc phải đối mặt với những quyết định khó khăn về tương lai của mẹ, đồng thời gặp rắc rối vì những cơn ác mộng và những âm thanh đáng sợ trên hành lang mỗi tối...</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Emily Mortimer","avatar":""},{"name":"Bella Heathcote","avatar":""},{"name":"Robyn Nevin","avatar":""},{"name":"Chris Bunton","avatar":""},{"name":"Steve Rodgers","avatar":""},{"name":"Catherine Glavicic","avatar":""},{"name":"Jeremy Stanford","avatar":""},{"name":"Christina O''Neill","avatar":""},{"name":"John Browning","avatar":""},{"name":"Robin Northover","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324342);
