INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-ava', 'Sát Thủ Ava', 'Ava', 'https://phimimg.com/upload/vod/20231026-1/f05660ffadebc342699ccd7d778de484.jpg', 'https://phimimg.com/upload/vod/20231026-1/3d83aaa356143c5b7f6bdbda4c1ac571.jpg', '<p>Ava là một sát thủ giết người làm việc cho một tổ chức hoạt động đen, đi khắp thế giới chuyên về các vụ truy sát nổi tiếng. Khi một nhiệm vụ gặp trục trặc nguy hiểm đến tính mạng, cô ấy buộc phải chiến đấu vì sự sống còn của chính mình.</p>', 'Full', 1, 'single', 'completed', 12, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jessica Chastain","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Common","avatar":""},{"name":"Colin Farrell","avatar":""},{"name":"Geena Davis","avatar":""},{"name":"Jess Weixler","avatar":""},{"name":"Ioan Gruffudd","avatar":""},{"name":"Diana Silvers","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Efka Kvaraciejus","avatar":""},{"name":"Christopher J. Domig","avatar":""},{"name":"Michel Muller","avatar":""},{"name":"Dieter Riesle","avatar":""},{"name":"Aramis Merlin","avatar":""},{"name":"Michael Guarnera","avatar":""},{"name":"Bruce-Robert Serafin","avatar":""},{"name":"Jeff","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324342);
