INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('josee-khi-nang-tho-yeu', 'Josee,  Khi Nàng Thơ Yêu', 'Josee, the Tiger and the Fish', 'https://phimimg.com/upload/vod/20231026-1/d82ccfbfd752820ad58345bfb75fd1c4.jpg', 'https://phimimg.com/upload/vod/20231026-1/3a77a570c9cc1aff39935a99c8b8be13.jpg', '<p>Phim xoay quanh cuộc gặp gỡ định mệnh giữa Josee, một cô gái 24 tuổi khuyết tật, sống cùng bà và vô cùng khép kín với cuộc sống bên ngoài. Josee đã luôn sống trong thế giới nhỏ của bản thân, cho tới một buổi tối định mệnh khi cô được cậu sinh viên Tsuneo cứu trong một tai nạn. Mới đầu, Josee còn vô cùng cảnh giác với sự xuất hiện của Tsuneo, tuy nhiên sau đó, khi cậu sinh viên chứng minh được sự chân thành của mình, Josee đã dần mở lòng để Tsuneo khám phá về thế giới bí mật của riêng cô. Về phần Tsuneo, sự xuất hiện của Josee chính là bước ngoặt trong cuộc sống tưởng chừng đã được “mặc định” sẵn từng bước của cậu.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Taishi Nakagawa","avatar":""},{"name":"Kaya Kiyohara","avatar":""},{"name":"Yume Miyamoto","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Lynn","avatar":""},{"name":"Chiemi Matsutera","avatar":""},{"name":"Kanji Obana","avatar":""},{"name":"Shintarou Moriyama","avatar":""},{"name":"Yuuya Uchida","avatar":""},{"name":"Jin Urayama","avatar":""},{"name":"Lily","avatar":""},{"name":"Masaki Terasoma","avatar":""},{"name":"Kengo Kawanishi","avatar":""},{"name":"Masaaki Ihara","avatar":""},{"name":"Madoka Kido","avatar":""},{"name":"Arisa Kori","avatar":""},{"name":"Shuhei Sakaguchi","avatar":""},{"name":"Ayu Shoji","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324342);
