INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('josee-khi-nang-tho-yeu', 'Josee,  Khi Nàng Thơ Yêu', 'Josee, the Tiger and the Fish', 'josee,  khi nàng thơ yêu josee, the tiger and the fish taishi nakagawa kaya kiyohara yume miyamoto kazuyuki okitsu lynn chiemi matsutera kanji obana shintarou moriyama yuuya uchida jin urayama lily masaki terasoma kengo kawanishi masaaki ihara madoka kido arisa kori shuhei sakaguchi ayu shoji ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-cua-scoobydoo', 'Cuộc Phiêu Lưu Của Scooby-Doo!', 'Scoob!', 'https://phimimg.com/upload/vod/20231026-1/43e0fc001077bc04570a9f7dd82e7c96.jpg', 'https://phimimg.com/upload/vod/20231026-1/279a31a10f2ffce72121b2956837bee5.jpg', '<p>Trong cuộc phiêu lưu vĩ đại nhất của Scooby-Doo, hãy xem câu chuyện chưa từng được kể về việc những người bạn suốt đời Scooby và Shaggy gặp nhau như thế nào và họ đã hợp tác với các thám tử trẻ Fred, Velma và Daphne để thành lập Mystery Inc. Các vụ án đã được giải quyết, Scooby và băng đảng phải đối mặt với bí ẩn lớn nhất, khó khăn nhất từ trước đến nay: một âm mưu xấu xa nhằm giải phóng con chó ma Cerberus trên thế giới. Khi họ chạy đua để ngăn chặn cuộc điều khiển chó toàn cầu này, nhóm băng đảng phát hiện ra rằng Scooby có một di sản bí mật và một số phận sử thi lớn hơn bất kỳ ai từng tưởng tượng.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amanda Seyfried","avatar":""},{"name":"Christina Hendricks","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Mckenna Grace","avatar":""},{"name":"Gina Rodriguez","avatar":""},{"name":"Justina Machado","avatar":""},{"name":"Zac Efron","avatar":""},{"name":"Ariana Greenblatt","avatar":""},{"name":"Will Forte","avatar":""},{"name":"Mark Wahlberg","avatar":""},{"name":"Iain Armitage","avatar":""},{"name":"Pierce Gagnon","avatar":""},{"name":"Henry Winkler","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Kiersey Clemons","avatar":""},{"name":"Ken Jeong","avatar":""},{"name":"Tracy Morga","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"