INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-cha', 'Người Cha', 'The Father', 'https://phimimg.com/upload/vod/20231025-1/6c87b1480472c91851ea963c9a2e18c5.jpg', 'https://phimimg.com/upload/vod/20231025-1/0c09ec18d8654a4bbccfd641fc420dab.jpg', '<p>Người Cha - The Father (2020) là bộ phim thể loại tâm lý do Florian Zeller đạo diễn, có sự góp mặt của các diễn viên Anthony Hopkins, Mark Gatiss, Olivia Colman, Olivia Williams, Rufus Sewell, Imogen Poots, Ayesha Dharker, Scott Mullins, Roman Zeller. xoay quanh câu chuyện về người cha già lớn tuổi, ông từ chối mọi sự giúp đỡ từ cô con gái thân yêu mặc cho tuổi tác không còn ít và đầu óc bắt đầu thiếu minh mẫn. Khi đang cố gắng hiểu rõ sự thay đổi của môi trường xung quanh mình, ông bắt đầu nảy sinh hoài nghi đối với những người thân yêu. Thậm chí nghi ngờ chính bản thân mình và cả trạng thái thực sự của ông.</p>', 'Full', 1, 'single', 'completed', 17, 2020, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Anthony Hopkins","avatar":""},{"name":"Olivia Colman","avatar":""},{"name":"Mark Gatiss","avatar":""},{"name":"Olivia Williams","avatar":""},{"name":"Imogen Poots","avatar":""},{"name":"Rufus Sewell","avatar":""},{"name":"Ayesha Dharker","avatar":""},{"name":"Roman Zeller","avatar":""},{"name":"Evie Wray","avatar":""},{"name":"Brian Rodger","avatar":""},{"name":"Romulus Stoicescu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324342);
