INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-ten-khac-sau-trong-tim-nguoi', 'Cái Tên Khắc Sâu Trong Tim Người', 'Your Name Engraved Herein', 'https://phimimg.com/upload/vod/20231022-1/9a6cc0e977d2cf63699c62892f6b38cc.jpg', 'https://phimimg.com/upload/vod/20231022-1/db393ed54638bfafe1aea2e9fbcd4f5e.jpg', '<p>Câu chuyện của Your Name Engraved Herein bắt đầu từ năm 1988. Sau khi Thiết Quân Luật kết thúc, lúc này hai nam sinh trường công giáo là A Hán (Trần Hạo Sâm) và Birdy (Tằng Kính Hoa) cùng nhau lẻn đi Đài Bắc vui chơi, và nhờ đó mà A Hán nhận ra mình đã thích Birdy. Cũng trong năm học này, trường lần đầu tiên quyết định cho nữ sinh nhập học, và Birdy đã nhân cơ hội này để làm quen một bạn nữ nhằm tránh A Hán. Cả hai dần dần rạn nứt, sau đó chia xa nhau tận 20 năm, và lại gặp nhau tại một đất nước xa lạ.</p>', 'Full', 1, 'single', 'completed', 15, 2020, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Edward Chen","avatar":""},{"name":"Jing-Hua Tseng","avatar":""},{"name":"Leon Dai","avatar":""},{"name":"Shih-Sian Wang","avatar":""},{"name":"Fabio Grangeon","avatar":""},{"name":"Barry Qu","avatar":""},{"name":"Stone Yang","avatar":""},{"name":"Lance Chiu","avatar":""},{"name":"Mimi Shao","avatar":""},{"name":"Hui-Min Lin","avatar":""},{"name":"Lotus Wang","avatar":""},{"name":"Cheng-Yang Wu","avatar":""},{"name":"Lenny Li","avatar":""},{"name":"David Chiu","avatar":""},{"name":"Chih-ju Lin","avatar":""},{"name":"Soda Voyu","avatar":""},{"name":"Honduras","avatar":""},{"name":"Yi-Ruei Chen","avatar":""},{"name":"Siu Wa Lung","avatar":""},{"name":"Tzu-Yen Chin","avatar":""},{"name":"Qu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324342);
