INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-cua-con-nguoi', 'Quái Vật Của Con Người', 'Monsters of Man', 'https://phimimg.com/upload/vod/20231023-1/6d3ac23370749ad9c2da6652cb38226d.jpg', 'https://phimimg.com/upload/vod/20231023-1/38e4fba5a79d56e5e3006a24ab6d4026.jpg', '<p>Một công ty chế tạo robot đang cạnh tranh để giành được một hợp đồng quân sự béo bở hợp tác với một đặc vụ CIA tham nhũng để tiến hành một cuộc thử nghiệm thực địa bất hợp pháp. Họ triển khai bốn robot nguyên mẫu được vũ khí hóa vào một trại bị nghi ngờ sản xuất ma túy ở Tam giác vàng, với giả định rằng họ sẽ giết những kẻ buôn lậu ma túy mà không ai có thể bỏ sót. Sáu bác sĩ đang thực hiện sứ mệnh nhân đạo chứng kiến cuộc tàn sát tàn bạo và trở thành mục tiêu hàng đầu.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Neal McDonough","avatar":""},{"name":"Brett Tutor","avatar":""},{"name":"Jose Rosete","avatar":""},{"name":"David Haverty","avatar":""},{"name":"Paul Haapaniemi","avatar":""},{"name":"Ryan Hough","avatar":""},{"name":"Ma Rynet","avatar":""},{"name":"Kayli Tran","avatar":""},{"name":"Jessica Blackmore","avatar":""},{"name":"Jordy Tulleners","avatar":""},{"name":"Tatjana Marjanovic","avatar":""},{"name":"David Samartin","avatar":""},{"name":"Trong Kam","avatar":""},{"name":"Taylor Leigh Edwards","avatar":""},{"name":"Conrad K. Pratt","avatar":""},{"name":"Ly Ty","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324342);
