INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-phu-thuy', 'Phù Thủy, Phù Thủy', 'Roald Dahl''s The Witches', 'https://phimimg.com/upload/vod/20231020-1/257c2762065e82f29eaafb9b32461696.jpg', 'https://phimimg.com/upload/vod/20231020-1/1760e45d60cb67ce96272c298f535ea4.jpg', '<p>Trong chuyến đi chơi cùng bà, một cậu bé 7 tuổi vô tình lọt vào hội nghị của các phù thủy và bị Phù Thủy Tối Thượng biến thành chuột bằng một loại thuốc đặc biệt. Đây cũng chính là chất độc ả định dùng để biến tất cả trẻ em thành loài gặm nhấm. Cùng với bà mình, cậu bé phải tìm mọi cách trở lại hình dạng thật và đánh bại âm mưu của binh đoàn Phù Thủy.</p>', 'Full', 1, 'single', 'completed', 21, 2020, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Jahzir Bruno","avatar":""},{"name":"Chris Rock","avatar":""},{"name":"Codie-Lei Eastick","avatar":""},{"name":"Kristin Chenoweth","avatar":""},{"name":"Charles Edwards","avatar":""},{"name":"Morgana Robinson","avatar":""},{"name":"Brian Bovell","avatar":""},{"name":"Josette Simon","avatar":""},{"name":"Eugenia Caruso","avatar":""},{"name":"Ana Maria Maskell","avatar":""},{"name":"Amber Flanagan","avatar":""},{"name":"Eurydice El-Etr","avatar":""},{"name":"Orla O''","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324342);
