INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('birds-of-prey-cuoc-lot-xac-huy-hoang-cua-harley-quinn', 'Birds of Prey: Cuộc Lột Xác Huy Hoàng Của Harley Quinn', 'Birds of Prey (and the Fantabulous Emancipation of One Harley Quinn)', 'https://phimimg.com/upload/vod/20231020-1/73e4382345ecc4fbcec59eedb7bd5b8b.jpg', 'https://phimimg.com/upload/vod/20231020-1/1ea00d7b733c563f3844fb30582b0f10.jpg', '<p>Cuộc Lột Xác Huy Hoàng của Harley Quinn sẽ tiếp nối những sự kiện xảy ra trong Suicide Squad, khi Harley Quinn không còn phụ thuộc vào Joker và đang tìm cách hoàn lương. Giữa một thành phố Gotham hỗn loạn sau sự biến mất của người hùng bóng đêm Gotham, cô bé Cassandra Cain (Ella Jay Basco) tìm thấy một viên kim cương vốn thuộc về gã ác nhân Black Mask và bị tên này bắt giữ. Khi đó, Harley Quinn đã tập hợp các nữ anh hùng để lên đường giải cứu Cassandra.</p>', 'Full', 1, 'single', 'completed', 14, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Margot Robbie","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"Jurnee Smollett","avatar":""},{"name":"Rosie Perez","avatar":""},{"name":"Chris Messina","avatar":""},{"name":"Ella Jay Basco","avatar":""},{"name":"Ali Wong","avatar":""},{"name":"Matthew Willig","avatar":""},{"name":"Dana Lee","avatar":""},{"name":"Steven Williams","avatar":""},{"name":"Robert Catrini","avatar":""},{"name":"Daniel Bernhardt","avatar":""},{"name":"François Chau","avatar":""},{"name":"Miyuki Matsunaga","avatar":""},{"name":"Anna Mikami","avatar":""},{"name":"Paul L","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324342);
