INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('birds-of-prey-cuoc-lot-xac-huy-hoang-cua-harley-quinn', 'Birds of Prey: Cuộc Lột Xác Huy Hoàng Của Harley Quinn', 'Birds of Prey (and the Fantabulous Emancipation of One Harley Quinn)', 'birds of prey: cuộc lột xác huy hoàng của harley quinn birds of prey (and the fantabulous emancipation of one harley quinn) margot robbie ewan mcgregor mary elizabeth winstead jurnee smollett rosie perez chris messina ella jay basco ali wong matthew willig dana lee steven williams robert catrini daniel bernhardt françois chau miyuki matsunaga anna mikami paul l ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-nhiem-mau', 'Cuộc Sống Nhiệm Màu', 'Soul', 'https://phimimg.com/upload/vod/20231019-1/9fdcaeb1e935ab83d0714e2a2d85b9d7.jpg', 'https://phimimg.com/upload/vod/20231019-1/a99fe7eeee785dcfa351bc6690f128cc.jpg', '<p>Điều gì khiến bạn là chính bạn? Cuối năm nay, hãng phim hoạt hình danh tiếng Pixar sẽ trình làng một tác phẩm mới mang tên SOUL – CUỘC SỐNG NHIỆM MÀU với nhân vật chính là Joe Gardner (Jamie Foxx lồng tiếng) một giáo viên dạy nhạc ở trường trung học. Anh vừa nhận được một cơ hội duy nhất trong đời khi có thể được tham gia chơi Jazz cho một ban nhạc nổi nhất thành phố. Nhưng một bước chân sai lầm đã đưa anh từ thành phố New York hoa lệ đến Cõi Trước – một nơi kỳ diệu mà ở đó các linh hồn được nhận tính cách, sở thích trước khi họ đi đến Trái Đất. Quyết tâm trở về cuộc đời của chính mình, Joe hợp tác với một linh hồn bất hảo mang tên 22 (lồng tiếng bởi Tina Fey) - người chưa bao giờ hiểu được sự hấp dẫn của cuộc sống loài người. Joe cố gắng hết mình để cho 22 thấy cuộc sống này nhiệm màu như thế nào, đồng thời anh ấy cũng khám phá ra câu trả lời quan trọng cho đời người.</p>', 'Full', 1, 'hoathinh', 'completed', 24, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jamie Foxx","avatar":""},{"name":"Tina Fey","avatar":""},{"name":"Graham Norton","avatar":""},{"name":"Rachel House","avatar":""},{"name":"Alice Braga","avatar":""},{"name":"Richard Ayoade","avatar":""},{"name":"Phylicia Rashād","avatar":""},{"name":"Donnell Rawlings","avatar":""},{"name":"Questlove","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"Cora Champommier","avatar":""},{"name":"Margo Hall","avatar":""},{"name":"Daveed Diggs","avatar":""},{"name":"Rhodessa Jones","avatar":""},{"name":"Wes Studi","avatar":""},{"name":"Sakina Jaffrey","avatar":""},{"name":"Fortune Feimster","avatar":""},{"name":"Calum Gr","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324342);
