INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-croods-ky-nguyen-moi', 'Gia Đình Croods: Kỷ Nguyên Mới', 'The Croods: A New Age', 'https://phimimg.com/upload/vod/20231018-1/1a31a09a46ec7d044523319738f35aa3.jpg', 'https://phimimg.com/upload/vod/20231018-1/691f7336d2eaa20f7dbff689959f7d76.jpg', '<p>Sinh tồn trong một thế giới tiền sử luôn rình rập hiểm nguy từ đủ loài quái thú hung dữ cho tới thảm họa ngày tận thế, Nhà Croods chưa từng một lần chùn bước. Nhưng giờ đây họ sẽ phải đối mặt với thử thách lớn nhất từ trước tới nay: chung sống với một gia đình khác. Để tìm kiếm một mái nhà an toàn hơn, Nhà Croods bắt đầu hành trình khám phá thế giới tiến tới những vùng đất xa xôi đầy tiềm năng. Một ngày nọ, họ tình cờ lạc vào một nơi yên bình có đầy đủ mọi tiện nghi hiện đại và biệt lập với tường vây bao quanh. Tưởng rằng mọi vấn đề trong cuộc sống sẽ được giải quyết thì Nhà Croods lại phải chấp nhận với sự thật rằng đã có một gia đình khác định cư ở đây đó chính là Nhà Bettermans.</p>', 'Full', 1, 'hoathinh', 'completed', 22, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Emma Stone","avatar":""},{"name":"Ryan Reynolds","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Cloris Leachman","avatar":""},{"name":"Clark Duke","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"Peter Dinklage","avatar":""},{"name":"Kelly Marie Tran","avatar":""},{"name":"Kailey Crawford","avatar":""},{"name":"Chris Sanders","avatar":""},{"name":"James Ryan","avatar":""},{"name":"Melissa Disney","avatar":""},{"name":"Joel Crawford","avatar":""},{"name":"Januel Mercado","avatar":""},{"name":"Ryan Naylor","avatar":""},{"name":"Artemis Pebdani","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324342);
