INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-croods-ky-nguyen-moi', 'Gia Đình Croods: Kỷ Nguyên Mới', 'The Croods: A New Age', 'gia đình croods: kỷ nguyên mới the croods: a new age nicolas cage emma stone ryan reynolds catherine keener cloris leachman clark duke leslie mann peter dinklage kelly marie tran kailey crawford chris sanders james ryan melissa disney joel crawford januel mercado ryan naylor artemis pebdani ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-rong-den-scorpion-bao-thu', 'Huyền Thoại Rồng Đen: Scorpion Báo Thù', 'Mortal Kombat Legends: Scorpion''s Revenge', 'https://phimimg.com/upload/vod/20231017-1/6ffeb06292fe469439c21bbbcaa63028.jpg', 'https://phimimg.com/upload/vod/20231017-1/5f05be1a8ead350af77ac0289fee7d07.jpg', '<p>Mortal Kombat là một tựa game chiến đấu và là trò chơi đầu tiên được phát hành vào năm 1992. Nó đã trở thành một thương hiệu về game chiến đấu đối kháng và bạo lực, đáng chú lý là chiêu cuối Fatality cho phép người chơi giết đối thủ một cách tàn bạo nhất. Scorpion là một trong những nhân vật đầu tiên cũng như là nhân vật nổi tiếng nhất. Anh chàng có câu chuyện bối cảnh bi thảm nhất trong nhượng quyền thương mại. Toàn bộ gia tộc của anh ta, bao gồm cả con trai Satoshi và vợ Harumi đã bị Quan Chi sát hại, người đã lừa Scorpion tin rằng Sub-Zero đã làm điều đó. Đó là một câu chuyện hấp dẫn với nhiều khúc ngoặt mà tất cả người hâm mộ Mortal Kombat đều thích được xem trên màn hình lớn.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Seitz","avatar":""},{"name":"Jordan Rodrigues","avatar":""},{"name":"Jennifer Carpenter","avatar":""},{"name":"Joel McHale","avatar":""},{"name":"Ike Amadi","avatar":""},{"name":"Steve Blum","avatar":""},{"name":"Artt Butler","avatar":""},{"name":"Darin De Paul","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Dave B. Mitchell","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"Fred Tatasciore","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324342);
