INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-chat-no', 'Thành Phố Chất Nổ', 'Blade Dancer', 'https://phimimg.com/upload/vod/20231014-1/82a528435b49b31e27a311bea570ddea.jpg', 'https://phimimg.com/upload/vod/20231014-1/f97fd2b8d1038526a091ef08ac56606c.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Lu Fei, một chuyên gia Interpol đã nghỉ hưu, đã gặp vị hôn thê Su Man vào đêm trước đám cưới của mình. Trong quá trình tìm kiếm, Luffy nhìn thấy Suman lên chuyến bay đến quốc gia Đông Nam Á A từ video giám sát sân bay, nhưng thông tin sân bay cho thấy người phụ nữ không được gọi là Suman. Luffy có nhiều nghi ngờ trong lòng, và truy tìm thủ đô của quốc gia Đông Nam Á A để theo đuổi sự thật. Lục Phi tìm thấy anh trai duy nhất của Tô Mẫn là Tô Thịnh và hỏi anh ta về nơi ở của Tô Mẫn. Su Sheng không biết rằng khi anh ta muốn trốn thoát, anh ta đã bị giết bởi một khẩu súng bắn tỉa ẩn trong bóng tối. Lu Fei, người trốn thoát, bí mật liên lạc với Juliet sở cảnh sát và biết rằng một tổ chức khủng bố quốc tế do Sorion lãnh đạo đã xuất hiện ở nước A. Su Sheng cũng không phải là anh trai của Su Man, mà là thành viên của một tổ chức khủng bố. Đồng thời, thủ đô của nước A bắt đầu thường xuyên xảy ra những sự cố về những người nổi tiếng bị giết, và toàn bộ thành phố bị bao phủ trong máu, Lục Phi không chỉ muốn giải quyết âm mưu, mà còn muốn tìm người mình yêu...</span></p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Longjun Li","avatar":""},{"name":"Qianru Zhang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":