INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-kyoto', 'Bí Mật Kyoto', 'Kyoto Confidential', 'null', 'https://phimimg.com/upload/vod/20231013-1/9454890b7ee2aa02ef8264385cf06db6.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Vào giữa triều đại nhà Minh, Zhang Sheng và Yuan Su đã bị trục xuất khỏi Yamen vì đồng nghiệp Cheng Yun của họ đánh chết tù nhân. Hầu Thành Vân bị giết, sương mù dày đặc, và bằng chứng chỉ ra giám đốc nhà tù Ge Lin và người đàn ông giàu có bí ẩn Shen Kang. Liệu cả hai có thể chống trả trong một tình huống tuyệt vọng bất chấp những nghi ngờ trước đó? Dưới sự thịnh vượng, những tội lỗi chưa biết đó cuối cùng sẽ &quot;nổi lên&quot;...</span></p>', 'Full', 1, 'single', 'completed', 13, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Song Chen","avatar":""},{"name":"Fan Yujun","avatar":""},{"name":"Xu Haiwei","avatar":""},{"name":"Guo Jun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324342);
