INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lop-tieu-hoc-2', 'Lớp Tiểu Học 2', 'Class Two is Open', 'null', 'https://phimimg.com/upload/vod/20231013-1/5b80f28a153d47d41b7014b59d0df8ea.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Vở kịch kể về câu chuyện của Zhang Letian, Fang Dazhuang và Huang Shanshan là ba học sinh tiểu học với những vấn đề khác nhau. Vì một loạt các vấn đề như gia đình, xã hội và tự chủ, họ không tìm kiếm sự thăng tiến và chiến đấu chống lại chính quyền. Thực hiện một loạt những điều hài hước nhưng kích thích tư duy. Giáo viên dạy và tuân theo các quy tắc và xây dựng một nền tảng để chúng được hiển thị trong các lĩnh vực mà họ quan tâm. Vở kịch cho thấy một số vấn đề nóng về xã hội như chính sách hai con hiện nay, vấn đề trẻ em bị bỏ lại phía sau, và sự so sánh giữa cha mẹ để thể hiện sự giàu có qua góc nhìn của trẻ em, và cuối cùng với sự nỗ lực chung của xã hội, cha mẹ và giáo viên, các vấn đề của trẻ em đã được giải quyết hiệu quả. Mục đích ban đầu của chúng tôi khi tạo ra bộ phim này là mang tính giải trí và giáo dục, để khán giả có thể cảm nhận được niềm vui, sự tức giận và nỗi buồn cùng một lúc, để cả xã hội có thể biết rằng giáo dục trẻ em là một vấn đề phổ biến trong xã hội.</span></p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Duan Junxu","avatar":""},{"name":"Yin Jingrui","avatar":""},{"name":"Jiao Jingyi","avatar":""},{"name":"Sun Yuanyuan","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324342);
