INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('son-tung-mtp-sky-tour-movie', 'Sơn Tùng M-TP: Sky Tour Movie', 'Sky Tour: The Movie', 'https://phimimg.com/upload/vod/20231012-1/7cc2f714c086f97e2c81381c09e509ce.jpg', 'https://phimimg.com/upload/vod/20231012-1/ac146177cf3043a3e7e9e11906f7ebd4.jpg', '<p>Hé lộ khâu chuẩn bị cho các buổi biểu diễn, bộ phim tài liệu giới thiệu về thần tượng nhạc pop Việt Nam Sơn Tùng M-TP và đam mê ẩn sau chuyến lưu diễn Sky Tour của anh.</p>', 'Full', 1, 'single', 'completed', 22, 2020, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Sơn Tùng M-TP","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324342);
