INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cua-gio', 'Bí Mật Của Gió', 'Secrets of the Wind', 'https://phimimg.com/upload/vod/20231011-1/277fd1e9366a59b70133124b2843aaec.jpg', 'https://phimimg.com/upload/vod/20231011-1/cc3c845eb9894b9cdbbd7ea4db73f762.jpg', '<p>Bí Mật Của Gió kể về cô nàng quái chiêu Linh khi cùng gia đình chuyển đến một ngôi nhà ma ám tại Đà Lạt, thành phố của sương mù bí ẩn và đầy lãng mạn. Bỗng nhiên Linh bắt buộc phải sống chung phòng với một hồn ma điển trai đến từ quá khứ. Từ những tình huống xung đột hài hước lúc ban đầu cả hai đã nảy sinh tình cảm và giúp nhau tìm ra được bí mật được chôn giấu suốt 45 năm.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Tran Quoc Anh","avatar":""},{"name":"Hoàng Yến Chibi","avatar":""},{"name":"Khả Ngân","avatar":""},{"name":"Vo Bang Thanh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324342);
