INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-quai-vat', 'Trái Tim Quái Vật', 'The Instrument Of Murder', 'https://phimimg.com/upload/vod/20231007-1/ff5ce643be0f508509423452dc583384.jpg', 'https://phimimg.com/upload/vod/20231007-1/9196a3060222a3c552503a9fce4358cd.jpg', '<p>Một vụ án hóc búa: một thanh niên bị giết chết bởi món đồ chơi trẻ em ở một khu chung cư cũ. Mọi nghi vấn đang đổ dồn vào Khánh, bà mẹ đơn thân. Nhưng đó chưa phải là tất cả, có nhiều hơn một nghi phạm.</p>', 'Full', 1, 'single', 'completed', 21, 2020, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Hứa Vĩ Văn","avatar":""},{"name":"Hoàng Thùy Linh","avatar":""},{"name":"B Trần","avatar":""},{"name":"Trịnh Thăng Bình","avatar":""},{"name":"Trung Dân","avatar":""},{"name":"Mỹ Uyên","avatar":""},{"name":"Hạnh Thúy","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324342);
