INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-phan-2', 'Chiến Binh (Phần 2)', 'Warrior (Season 2)', 'https://phimimg.com/upload/vod/20231003-1/99b83553c63d50e62b2671d8eb9bc5d0.jpg', 'https://phimimg.com/upload/vod/20231003-1/e789382619da5a3a80dc791b02868ef1.jpg', '<p>Warrior kể về Ah Sahm (Andrew Koji), một thần đồng võ thuật di cư từ Trung Quốc đến San Francisco. Sau chứng tỏ năng lực chiến đấu của mình, Ah Sahm trở thành một con gà đẻ trứng vàng cho Hope Wei, một trong những gia tộc mạnh nhất Trung Quốc – gia tộc Tongs (gia đình tội phạm có tổ chức của Trung Quốc).</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 22, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andrew Koji","avatar":""},{"name":"Olivia Cheng","avatar":""},{"name":"Jason Tobin","avatar":""},{"name":"Dianne Doan","avatar":""},{"name":"Kieran Bew","avatar":""},{"name":"Dean S. Jagger","avatar":""},{"name":"Tom Weston-Jones","avatar":""},{"name":"Hoon Lee","avatar":""},{"name":"Langley Kirkwood","avatar":""},{"name":"Miranda Raison","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324342);
