INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-minh-dao-mo', 'Liên Minh Đào Mộ', 'Collectors', 'https://phimimg.com/upload/vod/20231002-1/c1f89096e5200d81e0b8dce25c06937a.jpg', 'https://phimimg.com/upload/vod/20231002-1/3f992fcde670be5383ae4a3ddfe70df3.jpg', '<p>Kang Dong-goo (Lee Je Hoon) là một thiên tài săn mộ khi có thể tìm ra kho báu chỉ bằng cách ngửi mùi đất. Cùng với các đồng là đội là tiến sĩ Jones (Jo Woo Jin) - chuyên gia nghiên cứu tranh cổ mộ, và Sabdari (Lim Won Hee) - huyền thoại đào mộ, Kang Dong-goo lập thành một bộ ba hoàn hảo cùng thực hiện những phi vụ cướp mộ đầy nguy hiểm và ly kỳ. Tài năng của Dong-goo đã lọt vào tầm ngắm của Yoon Sae-hee (Shin Hae Sun) - người quản lý cấp cao của Viện trưng bày cổ vật. Cô đưa ra đề nghị hấp dẫn mời nhóm của Dong-goo hợp tác trong phi vụ tìm kiếm một kho báu thời cổ đại.</p>', 'Full', 1, 'single', 'completed', 19, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Je-hoon","avatar":""},{"name":"Jo Woo-jin","avatar":""},{"name":"Shin Hye-sun","avatar":""},{"name":"Im Won-hee","avatar":""},{"name":"Song Young-chang","avatar":""},{"name":"Ju Jin-mo","avatar":""},{"name":"Lee Sung-wook","avatar":""},{"name":"Park Se-wan","avatar":""},{"name":"Park Jin-woo","avatar":""},{"name":"Lee Jun-hyeok","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324342);
