INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-chien-lang', 'Biệt Đội Chiến Lang', 'Wolf Killing Action', 'https://phimimg.com/upload/vod/20230930-1/2c0553dcf30701ce6ebae5a11bc2cbdd.jpg', 'https://phimimg.com/upload/vod/20230930-1/1309816887c9e0c645ce467ae92f2a91.jpg', '<p>Wolf Killing Action là một bộ <a href="https://gphimtv.vncns.com/hanh-dong/" title="Hành động">phim hành động</a> kịch tính và gay cấn, xoay quanh câu chuyện về một đội điệp viên chuyên nghiệp được giao nhiệm vụ ngăn chặn một tổ chức <a href="https://gphimtv.vncns.com/toi-pham/" title="Tội phạm">tội phạm</a>
 nguy hiểm đang hoạt động trên toàn cầu. Đội Chiến Lang, gồm các thành 
viên tài năng và có kỹ năng chiến đấu đặc biệt, được tập hợp bởi một tổ 
chức chính phủ bí mật. Tổ chức này đã phát hiện ra rằng tổ chức tội phạm
 có tên &quot;Wolf&quot; đang lên kế hoạch thực hiện một cuộc tấn công khủng bố có
 quy mô lớn, có thể gây ra hậu quả khủng khiếp cho thế giới.</p>', 'Full', 1, 'single', 'completed', 21, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chen Xingxu","avatar":""},{"name":"Li Ruichao","avatar":""},{"name":"Li Xuezheng","avatar":""},{"name":"Pang Hao-Feng","avatar":""},{"name":"Zhao Yixin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324342);
