INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-quy-doi-dau', 'Ác Quỷ Đối Đầu', 'Deliver Us from Evil', 'https://phimimg.com/upload/vod/20230930-1/c90d8cf276d961f986e640f751a44e63.jpg', 'https://phimimg.com/upload/vod/20230930-1/c678ee4710934505e6ad83d0d344a409.jpg', '<p>In-nam (Hwang Jung Min) – một tay sát thủ đã giải nghệ và Yui (Park Jeong Min) gặp nhau tại Thái Lan để tìm kiếm đứa con gái bị bắt cóc mà In-nam chưa một lần gặp mặt. Cuộc chạy đua với thời gian này trở nên khó khăn hơn bao giờ hết khi cả hai phải đương đầu với sự bám đuổi gắt gao từ Ray (Lee Jung Jae). Tên “đồ tể” máu lạnh truy sát In-nam sau khi biết rằng anh trai mình đã bị giết hại, Ray quyết tâm đòi lại món nợ máu này bằng mọi giá.</p>', 'Full', 1, 'single', 'completed', 19, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Hwang Jung-min","avatar":""},{"name":"Lee Jung-jae","avatar":""},{"name":"Park Jeong-min","avatar":""},{"name":"Choi Hee-seo","avatar":""},{"name":"Oh Dae-hwan","avatar":""},{"name":"Park Myung-hoon","avatar":""},{"name":"Song Young-chang","avatar":""},{"name":"Lee Seo-hwan","avatar":""},{"name":"Vithaya Pansringarm","avatar":""},{"name":"Kim Min-sik","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324342);
