INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-xam-nhap', 'Kẻ Xâm Nhập', 'Intruder', 'https://phimimg.com/upload/vod/20230929-1/f96a2a909952f906980870c5b8d5bf33.jpg', 'https://phimimg.com/upload/vod/20230929-1/7bff29af3b4183c934b8d747a03c3ab8.jpg', '<p>Cứ ngỡ, gia đình Seo Jin sẽ lại hạnh phúc như xưa khi Yoo Jin – đứa em gái mất tích 25 năm bất ngờ trở về. Thế nhưng, Seo Jin dần nhận thấy người phụ nữ không mời mà đến này có chút bất thường. Nghi ngờ cô ta mạo danh em mình, anh quyết định lên kế hoạch nhằm bóc trần bộ mặt của “kẻ xâm nhập”.</p>', 'Full', 1, 'single', 'completed', 20, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Moo-yul","avatar":""},{"name":"Song Ji-hyo","avatar":""},{"name":"Ye Soo-jung","avatar":""},{"name":"Heo Joon-seok","avatar":""},{"name":"Lee Hae-woon","avatar":""},{"name":"Han Hye-ji","avatar":""},{"name":"Kim Seung-bee","avatar":""},{"name":"Yang Mal-bok","avatar":""},{"name":"Choi Young-woo","avatar":""},{"name":"Lim Sun-woo","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324342);
