INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-tinh-lenh-chi-loan-phach', 'Trần Tình Lệnh Chi Loạn Phách', 'Fatal Journey', 'https://phimimg.com/upload/vod/20230928-1/d673b86cc1664049e195c055e04ecfb3.jpg', 'https://phimimg.com/upload/vod/20230928-1/c308a1fa9b22e098d9bebccae2353249.jpg', '<p>Đây là một câu chuyện về Họ Niếp ở Thành Hà gặp phải nguy cơ Đường
 tế dao, anh trai Niếp minh quyết cùng với em trai Niếp Hoài Tang hy 
sinh vì người khác, sửa chữa Đường tế dao để giữ an toàn cho gia đình. 
Trong câu chuyện này, em trai Niếp Hoài Tang và anh trai Niếp minh Quyết
 Tay trong tay vượt qua nhiều khó khán, nhưng trong cuộc trình này, hai 
anh em nảy sinh nhiều xích mích với nhau, Niếp minh quyết đã đổ lỗi là 
Niếp Hoài Tang nhút nhát, Niếp Hoài Tang thì rằng Niếp minh quyết là độc
 tài và hung ác. Mặc dù có những mâu thuẫn, Niếp minh quyết đã giải cứu 
Niếp Hoài Tang gặp phải sự nguy hiểm, Niếp Hoài Tang thì không bao giờ 
rời khỏi anh trai , hai anh em bỏ sự hiểu lầm đến hiểu biết lẫn nhau từ 
từ. &nbsp;</p>', 'Full', 1, 'single', 'completed', 19, 2020, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ji Li","avatar":""},{"name":"Wang Yizhou","avatar":""},{"name":"Zhu Zanjin","avatar":""},{"name":"Xiang He","avatar":""},{"name":"He Xiang","avatar":""},{"name":"Lu Zhou","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324342);
