INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-minamata', 'Thảm Họa Minamata', 'Minamata', 'https://phimimg.com/upload/vod/20230926-1/aef02219ce97c28ad458cf10eb28046a.jpg', 'https://phimimg.com/upload/vod/20230926-1/54b7a529717cce744238d1695354e418.jpg', '<p>Phim được dựa trên sự kiện có thật về căn bệnh Minamata (được đặt theo tên thành phố biển bị ô nhiễm), một chứng rối loạn thần kinh do chất độc thủy ngân thải xuống vịnh Minamata và biển Shiranui của tỉnh Kumamoto, Nhật Bản bởi tập đoàn hóa chất Chisso. Hàng nghìn người dân địa phương tiêu thụ hải sản nhiễm thủy ngân xuất hiện các triệu chứng tê liệt, mất cảm giác và suy giảm chức năng cơ. Nghiêm trọng hơn là dẫn đến điên loạn, hôn mê và tử vong. Đây là thảm họa ô nhiễm công nghiệp kinh khủng nhất mà thế giới từng chứng kiến, và những ảnh hưởng của nó vẫn còn kéo dài cho đến ngày nay.</p>', 'Full', 1, 'single', 'completed', 20, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Minami","avatar":""},{"name":"Hiroyuki Sanada","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Jun Kunimura","avatar":""},{"name":"Ryo Kase","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Akiko Iwase","avatar":""},{"name":"Katherine Jenkins","avatar":""},{"name":"Lily Robinson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324342);
