INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-do', 'Bóng Ma Đỏ', 'The Red Ghost', 'https://phimimg.com/upload/vod/20230926-1/1ebac980035bf40b5b2567764fb7d4fd.jpg', 'https://phimimg.com/upload/vod/20230926-1/126162f376ea4b92ff1d0d5a8f22f880.jpg', '<p>Ngày 30 tháng 12 năm 1941. Tại Vyazma (&#39;vạc Vyazemsky&#39;) có một nhóm nhỏ lính Liên Xô, những người đang cố gắng tiếp cận đồng đội của họ sau khi thoát khỏi vòng vây của Đức Quốc xã. Trong phim họ bất ngờ bị cuốn vào cuộc chiến không cân sức với một đơn vị đặc biệt của Wehrmacht. Không ai trong số những người dũng cảm này sinh ra đã là anh hùng nhưng họ đã trở thành anh hùng. Và đã được giúp đỡ trong trận chiến của họ bởi Red Ghost. Thần thoại về bóng ma đỏ của bộ phim kể về một anh hùng đơn độc, từng người từng người một của Đức Quốc xã. Anh ta dường như có thể biến mất gần như một cách kỳ diệu vào các khu rừng và thậm chí trở lại từ cõi chết.</p>', 'Full', 1, 'single', 'completed', 22, 2020, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Aleksei Shevchenkov","avatar":""},{"name":"Vladimir Gostyukhin","avatar":""},{"name":"Yuriy Borisov","avatar":""},{"name":"Polina Chernyshova","avatar":""},{"name":"Wolfgang Cerny","avatar":""},{"name":"Mikhail Gorevoy","avatar":""},{"name":"Olga Stashkevich","avatar":""},{"name":"Pavel Abramenkov","avatar":""},{"name":"Vyacheslav Shikhaleev","avatar":""},{"name":"Oleg Vasilkov","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324342);
