INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dua-tre-cua-dong-ngo', 'Những Đứa Trẻ Của Đồng Ngô', 'Children of the Corn', 'https://phimimg.com/upload/vod/20230922-1/3a6e62a311981662333b7d9e023d4fcb.jpg', 'https://phimimg.com/upload/vod/20230922-1/3148676ef2da4ee30e96a49f607a068c.jpg', '<p>Một cô bé mười hai tuổi bị tâm thần ở một thị trấn nhỏ ở Nebraska chiêu mộ tất cả những đứa trẻ khác và nổi cơn thịnh nộ đẫm máu, giết chết những người lớn tham nhũng và bất kỳ ai chống lại cô. Một học sinh trung học thông minh không tuân theo kế hoạch là hy vọng sống sót duy nhất của thị trấn.</p>', 'Full', 1, 'single', 'completed', 18, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elena Kampouris","avatar":""},{"name":"Kate Moyer","avatar":""},{"name":"Callan Mulvey","avatar":""},{"name":"Bruce Spence","avatar":""},{"name":"Stephen Hunter","avatar":""},{"name":"Erika Heynatz","avatar":""},{"name":"Ashlee Juergens","avatar":""},{"name":"Sisi Stringer","avatar":""},{"name":"Orlando Schwerdt","avatar":""},{"name":"Anna Samson","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324342);
