INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-tro-ve-2020', 'Đường Trở Về', 'The Way Back', 'https://phimimg.com/upload/vod/20230919-1/7a03090d503f78d6d27ce6c4a4a83337.jpg', 'https://phimimg.com/upload/vod/20230919-1/5909302fd43f28138901ebdb6c885f1f.jpg', '<p><span style="font-family: ">Bộ phim kể về một cựu hiện tượng bóng rổ HS, đấu tranh với chứng nghiện rượu, được mời làm công việc huấn luyện tại trường cũ của mình. Khi đội bắt đầu chiến thắng, anh ta có thể có lý do để đối đầu với những con quỷ cũ của mình. Nhưng nó sẽ đủ để đặt anh ta trên con đường cứu chuộc?</span></p>', 'Full', 1, 'single', 'completed', 23, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Al Madrigal","avatar":""},{"name":"Michaela Watkins","avatar":""},{"name":"Janina Gavankar","avatar":""},{"name":"Glynn Turman","avatar":""},{"name":"Melvin Gregg","avatar":""},{"name":"Brandon Wilson","avatar":""},{"name":"Will Ropp","avatar":""},{"name":"Fernando Luis Vega","avatar":""},{"name":"Charles Lott","avatar":""},{"name":"Jr.","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324342);
