INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pokemon-the-movie-bi-mat-rung-ram', 'Pokémon the Movie: Bí Mật Rừng Rậm', 'Pokémon the Movie: Secrets of the Jungle', 'https://phimimg.com/upload/vod/20230918-1/01ae627f6cd7957b07e061ea1c27b593.jpg', 'https://phimimg.com/upload/vod/20230918-1/601ce71779a099fcc65b9020aa8baff9.jpg', '<p>Trong Rừng Okoya, Koko là một đứa trẻ hoang dã được Pokémon thần thoại Zarude nuôi dưỡng như một Pokémon. Koko đã lớn lên và không bao giờ nghi ngờ rằng mình là Pokémon mặc dù cậu ấy thực sự không thể sử dụng bất kỳ chiêu thức nào. Ash Ketchum và Pikachu gặp Koko và giúp anh bảo vệ Cây Đại thụ khỏi nhà khoa học quanh co Tiến sĩ Zed.</p>', 'Full', 1, 'hoathinh', 'completed', 24, 2020, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Rica Matsumoto","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Moka Kamishiraishi","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Shin-ichiro Miki","avatar":""},{"name":"Inuko Inuyama","avatar":""},{"name":"Kantarô Nakamura","avatar":""},{"name":"Shoko Nakagawa","avatar":""},{"name":"Koichi Yamadera","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324342);
