INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-moi-day-bien', 'Kẻ Săn Mồi Đáy Biển', 'Underwater', 'https://phimimg.com/upload/vod/20230917-1/ff3b3fc8f95d5698d26d38f9429a58a1.jpg', 'https://phimimg.com/upload/vod/20230917-1/f91f42a20e47cfd2ac726268a4355017.jpg', '<p><span style="font-family: ">Phim xoay quanh một nhóm kĩ sư dầu khí làm việc tại dàn khoan, trong một nhiêm vụ khắc phục sự cố tại chân của dàn khoan ở đáy biển, nhóm kĩ sư phát hiện tính mạng của bản thân bị đe doạ bởi một sinh vật bí ẩn. Sinh vật này là gì?</span></p>', 'Full', 1, 'single', 'completed', 24, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kristen Stewart","avatar":""},{"name":"Vincent Cassel","avatar":""},{"name":"Mamoudou Athie","avatar":""},{"name":"T.J. Miller","avatar":""},{"name":"John Gallagher Jr.","avatar":""},{"name":"Jessica Henwick","avatar":""},{"name":"Gunner Wright","avatar":""},{"name":"Fiona Rene","avatar":""},{"name":"Amanda Troop","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324342);
