INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-chung-vo-hinh', 'Bằng Chứng Vô Hình', 'Invisible Evidence', 'https://phimimg.com/upload/vod/20230917-1/92307c5e510e4df64e9854d6d29ae10b.jpg', 'https://phimimg.com/upload/vod/20230917-1/b110b71070da6e5c369b5463244242f0.jpg', '<p><span style="font-family: ">Sau khi bị thương trong một tai nạn ô tô, Thu - một cô gái mù đã đến trình báo cảnh sát về vụ việc mà cô tin rằng đã trở thành án mạng. Tuy nhiên, cô gặp không ít khó khăn để thuyết phục cảnh sát tin mình vì là người khiếm thị. Cùng lúc đó, Hải - một nhân chứng khác bất ngờ xuất hiện với lời khai mâu thuẫn với Thu về hiện trường vụ án. Trong khi cảnh sát còn đang đau đầu xác minh xem thông tin của ai là sự thật, tên sát nhân đã âm thầm theo dõi cả Thu và Hải để tìm cách thủ tiêu nhân chứng.</span></p>', 'Full', 1, 'single', 'completed', 21, 2020, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Phương Anh Đào","avatar":""},{"name":"Quang Tuấn","avatar":""},{"name":"Otis","avatar":""},{"name":"Ái Phương","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324342);
