INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sai-gon-trong-con-mua', 'Sài Gòn Trong Cơn Mưa', 'Sai Gon in the Rain', 'https://phimimg.com/upload/vod/20230917-1/d199b41a354efaf699a3e8050aa407a0.jpg', 'https://phimimg.com/upload/vod/20230917-1/b9127118757fb9f9de5f5bf3e14e1cac.jpg', '<p><span style="font-family: ">&#39;Sài Gòn Trong Cơn Mưa&#39; là câu chuyện về tình yêu &amp; ước mơ của những người trẻ tứ xứ tìm thấy nhau giữa Sài Gòn và rồi lạc mất nhau cũng ở giữa Sài Gòn. Còn bạn? Liệu đã gặp được ‘thanh xuân’ của mình dưới cơn mưa đầu mùa nào hay chưa?</span></p>', 'Full', 1, 'single', 'completed', 25, 2020, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Lương Anh Vũ","avatar":""},{"name":"Hồ Thu Anh","avatar":""},{"name":"Hồ Minh Ngọc","avatar":""},{"name":"Hồ Thành Trung","avatar":""},{"name":"Việt Linh","avatar":""},{"name":"Châu Thiên Kim","avatar":""},{"name":"Trương Thanh Long","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324342);
