INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('spongebob-bot-bien-dao-tau', 'SpongeBob: Bọt Biển Đào Tẩu', 'The SpongeBob Movie: Sponge on the Run', 'https://phimimg.com/upload/vod/20230917-1/960605814ea0847224472089e50c0da1.jpg', 'https://phimimg.com/upload/vod/20230917-1/9cd362027b10a3d4f47f42f3baa95b3d.jpg', '<p><span style="font-family: ">SpongeBob SquarePants, người bạn thân Patrick, và ngôi sao băng đảng Bikini Bottom trong bộ phim phiêu lưu hoành tráng nhất của họ! Khi chú ốc cưng Gary yêu quý của SpongeBob mất tích, một manh mối dẫn dắt SpongeBob và Patrick đến với Vua Poseidon quyền lực, người đã giam giữ Gary ở Thành phố Mất tích của Thành phố Atlantic. Trong nhiệm vụ cứu Gary, SpongeBob và những người bạn của mình hợp sức tạo nên một cuộc hành trình anh hùng và vui nhộn, nơi họ khám phá ra rằng không gì mạnh hơn sức mạnh của tình bạn.</span></p>', 'Full', 1, 'hoathinh', 'completed', 28, 2020, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Tom Kenny","avatar":""},{"name":"Bill Fagerbakke","avatar":""},{"name":"Rodger Bumpass","avatar":""},{"name":"Mr. Lawrence","avatar":""},{"name":"Keanu Reeves","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Carolyn Lawrence","avatar":""},{"name":"Matt Berry","avatar":""},{"name":"Jill Talley","avatar":""},{"name":"Mary Jo Catlett","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324342);
