INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-nao-ca-vang', 'Tôi Là Não Cá Vàng', 'Tôi Là Não Cá Vàng', 'https://phimimg.com/upload/vod/20230917-1/a0a626b5e19ac52e53e0a6c3b7a5f62a.jpg', 'https://phimimg.com/upload/vod/20230917-1/d5e3372cbc0d39d49ae2dbf9e4216425.jpg', '<p><span style="font-family: ">Kể về cô gái tên Huyền (Khánh Hiền), vốn là một nhà thiết kế thời trang tài năng nhưng lại mắc căn bệnh Alzheimer – dạng phổ biến nhất của hội chứng suy giảm trí nhớ, khiến cuộc sống của Huyền ngày càng gặp nhiều trở ngại, đỉnh điểm là khi cả người chồng tương lai (Tuấn Trần) cũng vì thế mà chia tay cô. Giữa những đau khổ và suy sụp, Huyền vô tình gặp được chàng nhiếp ảnh gia tên Thoại (La Thành) – người đã luôn bên cạnh, động viên và tỏ tình với Huyền ngay cả khi biết rõ căn bệnh của cô gái trẻ. Nhưng bi kịch lại lần nữa diễn ra khi chứng hay quên ấy ngày càng trở nặng.</span></p>', 'Full', 1, 'single', 'completed', 26, 2020, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Khánh Hiền","avatar":""},{"name":"Tuấn Trần","avatar":""},{"name":"La Thành","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324342);
