INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-khach', 'Kiếm Khách', 'The Swordsman', 'https://phimimg.com/upload/vod/20230916-1/c8bd2ef7b90a4dac29ab7ce8273a55e9.jpg', 'https://phimimg.com/upload/vod/20230916-1/4f369fe38e7c4f73f972d0d6fefc8e00.jpg', '<p><span style="font-family: ">Phóng tác một sự kiện có thật trong lịch sử Hàn Quốc, bộ phim lấy bối cảnh năm 1623 vào thời điểm khi Gwanghae, vị vua thứ 15 của Joseon, bị phế ngôi. Là cấm vệ quân và cũng là kiếm khách lừng lẫy nhất lúc bấy giờ, Tae-yul bắt buộc phải lẩn trốn và mai danh ẩn tích. Trong lúc đó, đất nước Joseon lâm vào cảnh loạn lạc và phải gánh chịu sự hà hiếp của nhà Thanh. Theo một yêu sách vô lý của sứ giả, con gái của Tae-yul là Tae-ok bị bắt làm cống phẩm cho nhà Thanh. Vì cứu con gái, Tae-yul đành phải một lần nữa rút kiếm và đối đầu với đội quân tinh nhuệ của tay sứ giả.</span></p>', 'Full', 1, 'single', 'completed', 26, 2020, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Hyuk","avatar":""},{"name":"Kim Hyun-soo","avatar":""},{"name":"Joe Taslim","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Jang Hyun-sung","avatar":""},{"name":"Lee Na-kyeong","avatar":""},{"name":"Lee Min-hyuk","avatar":""},{"name":"Choi Jin-ho","avatar":""},{"name":"Ji Seung-hyun","avatar":""},{"name":"Ji Geon-woo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324342);
