INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-truot-dai', 'Cú Trượt Dài', 'Spinning Out', 'null', 'https://phimimg.com/upload/vod/20230910-1/af517e691ba8b94a73d870217bb19a71.jpg', '<p>Kat Baker là một vận động viên trượt băng đơn cấp độ cao đang phát triển, người chuẩn bị quay lại giày trượt của mình sau một cú ngã thảm khốc. Khi Kat nắm bắt cơ hội tiếp tục sự nghiệp vận động viên trượt băng đôi với một chàng trai hư tài năng, cô có nguy cơ phơi bày một bí mật được giữ kín có thể làm sáng tỏ toàn bộ cuộc đời cô.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 35, 2020, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kaya Scodelario","avatar":""},{"name":"January Jones","avatar":""},{"name":"Willow Shields","avatar":""},{"name":"Evan Roderick","avatar":""},{"name":"Sarah Wright","avatar":""},{"name":"Svetlana Efremova","avatar":""},{"name":"Mitchell Edwards","avatar":""},{"name":"Will Kemp","avatar":""},{"name":"Kaitlyn Leeb","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324342);
