INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('aladdin', 'Aladdin', 'Aladdin', 'https://phimimg.com/uploads/movies/20260712/aladdin-thumb.webp', 'https://phimimg.com/uploads/movies/20260712/aladdin-poster.webp', '<p>Aladdin là một phiên bản live action đầy màu sắc sống động và không kém phần hồi hộp, được chuyển thể từ bộ phim hoạt hình kinh điển cả hãng phim Disney. Câu chuyện xoay quanh chàng hoàng tử khu ổ chuột Aladdin – một thanh niên trẻ tuổi dũng cảm và nàng công chúa Jasmine mạnh mẽ, đương nhiên phải kể đến thần đèn Genie – người nắm giữ chìa khóa thay đổi tương lại sau này của họ.</p>', 'Full', 1, 'single', 'completed', 70, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Mena Massoud","avatar":""},{"name":"Naomi Scott","avatar":""},{"name":"Marwan Kenzari","avatar":""},{"name":"Navid Negahban","avatar":""},{"name":"Nasim Pedrad","avatar":""},{"name":"Billy Magnussen","avatar":""},{"name":"Numan Acar","avatar":""},{"name":"Jordan A. Nash","avatar":""},{"name":"Taliyah Blair","avatar":""},{"name":"Aubrey Lin","avatar":""},{"name":"Amir Boutrous","avatar":""},{"name":"Omari Bernard","avatar":""},{"name":"Nathaniel Ellul","avatar":""},{"name":"Sebastien Torkia","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Αλαντιν","Aladdin 3D","알라딘","アラジン：2019","阿拉丁真人版","Аладин","Aladdin"]', 1784690324342);
