INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-boonie-doi-tham-hiem-phan-2', 'Gấu Boonie: Đội Thám Hiểm (Phần 2)', 'Boonie Bears: The Adventurers (Season 2)', 'https://phimimg.com/upload/vod/20260429-1/27538e6850ff4cc69f254ae8053c8247.jpg', 'https://phimimg.com/upload/vod/20260429-1/279a1073df1292c809ee3fdf2684d2b3.jpg', '<p>Sau thành công từ chuyến đi đầu tiên, đội thám hiểm tái ngộ trong một nhiệm vụ mới đầy cam go nhằm bảo vệ hệ sinh thái khỏi những tác động tiêu cực của con người và các thiết bị công nghệ hiện đại. Lần này, họ phải đối mặt với kẻ phản diện xảo quyệt hơn đang âm mưu xâm phạm vùng lõi của khu rừng. Bằng sự thông minh của Carly, sức mạnh của anh em gấu Boonie và kinh nghiệm của Vick, nhóm bạn không chỉ giải cứu thành công các loài sinh vật quý hiếm mà còn truyền đi thông điệp mạnh mẽ về việc chung tay gìn giữ hành tinh xanh.</p>', 'Tập 43', 52, 'hoathinh', 'ongoing', 53, 2019, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Wei","avatar":""},{"name":"Tan Xiao","avatar":""},{"name":"Zhang Bingjun","avatar":""},{"name":"Yingying Miu","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["熊出没：少年篇","森林保卫战","探险日记","Boonie Bears：The Adventurers","Boonie Bears：The Adventurers 2","Boonie Bears the Adventurers","熊出没之探险日记"]', 1784690324342);
