INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-nang-fangirl', 'Bí Mật Nàng Fangirl', 'Her Private Life', 'https://phimimg.com/upload/vod/20260622-1/91bda7d8a80f291603977f92c1106e02.jpg', 'https://phimimg.com/upload/vod/20260622-1/c8300af3e9d088c5a8a2b386fd83a28a.jpg', '<p>Bí Mật Nàng Fangirl (Her Private Life) là bộ phim câu chuyện về một người phụ trách phòng trưng bày kiêm người hâm mộ tên Sung Duk Mi (Park Min Young); ông chủ Ryan (Kim Jae Wook), người đã phải lòng cô ấy; và đối thủ của Sung Duk Mi, cũng là một thần tượng chủ sở hữu fansite – Cindy (Kim Bo Ra).</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 37, 2019, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Min-young","avatar":""},{"name":"Kim Jae-uck","avatar":""},{"name":"Ahn Bo-hyun","avatar":""},{"name":"Jung Jae-won","avatar":""},{"name":"Kim Bo-ra","avatar":""},{"name":"Park Jin-joo","avatar":""},{"name":"Kim Mi-kyeong","avatar":""},{"name":"Maeng Sang-hun","avatar":""},{"name":"Hong Geum-bi","avatar":""},{"name":"Kim Sun-young","avatar":""},{"name":"Seo Ye-hwa","avatar":""},{"name":"Jung Won-chang","avatar":""},{"name":"Im Ji-gyu","avatar":""},{"name":"Lee Il-hwa","avatar":""},{"name":"Park Myung-shin","avatar":""},{"name":"Amy Aleha","avatar":""},{"name":"Yang Hee-won","avatar":""},{"name":"Kim Mi-hye","avatar":""},{"name":"Noreen Jo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Her Private Life","عالمها الخاص","حياتها الخاصة","โลกอีกใบของยัยแฟนเกิร์ล","她的私生活","그녀의 사생활"]', 1784690324342);
