INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-co-bala', 'Quý Cô Bala', 'Miss Bala', 'https://phimimg.com/upload/vod/20260617-1/c071aaa8a1977aeea7d7c7958f6b25b1.jpg', 'https://phimimg.com/upload/vod/20260617-1/5f1b01f37d75f553ed21dc1fef8c5ba3.jpg', '<p>Sau cái chết của ba mẹ, Gloria (Gina Rodriguez) trở lại thành phố Tijuana cùng cô bạn thân Suzu. Trong lúc đang đi chơi tại một hộp đêm, cả hai vô tình chứng kiến cuộc xả súng tàn bạo của một băng đảng ma túy và đều bị chúng bắt giữ. Kẻ cầm đầu Lino yêu cầu Gloria phải góp sức trong việc tấn công một trụ sở của DEA (Lực lượng Chống Ma túy). Gloria vô tình kẹt giữa cuộc chiến đẫm máu giữa các băng nhóm Mexico. Tuy nhiên, cô nàng lại rơi vào tay phía Mỹ và buộc phải trở thành gián điệp để giúp họ bắt giữ Lino. Trở lại với băng đảng ma túy, Gloria trở thành người vận chuyển ma túy và tiền ra vào biên giới Mỹ – Mexico dựa vào vị thế cầu nối đặc biệt của vùng Tijuana.</p>', 'Full', 1, 'single', 'completed', 29, 2019, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Gina Rodriguez","avatar":""},{"name":"Ismael Cruz Cordova","avatar":""},{"name":"Aislinn Derbez","avatar":""},{"name":"Matt Lauria","avatar":""},{"name":"Damián Alcázar","avatar":""},{"name":"Ricardo Abarca","avatar":""},{"name":"Cristina Rodlo","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Thomas Dekker","avatar":""},{"name":"Barbarella Pardo","avatar":""},{"name":"Sebastián Cano","avatar":""},{"name":"Erick Delgadillo","avatar":""},{"name":"Mikhail Plata","avatar":""},{"name":"Jorge Humberto Millan Mardueño","avatar":""},{"name":"Job Sarmien","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Міс Бала","Miss Bala"]', 1784690324342);
