INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-loi-noi-doi-tai-hai-phan-2', 'Những Lời Nói Dối Tai Hại (Phần 2)', 'Big Little Lies (Season 2)', 'https://phimimg.com/upload/vod/20260616-1/c06b43627002a5de086995e5512f8956.jpg', 'https://phimimg.com/upload/vod/20260616-1/e0ae38562380bb02c4f7c904d537f564.jpg', '<p>Phim xoay quanh những bà mẹ xinh đẹp sống tại một khu dân cư khá giả. Những tưởng họ luôn có một cuộc sống hoàn hảo, nhưng ẩn bên trong họ cũng phải đối mặt với những vấn đề như bao người phụ nữ “bình dân” khác: bạo lực, chồng cũ, bạn mới, vợ mới của chồng, mẹ đơn thân, con chung, con riêng… Có lẽ vì vậy mà cuộc sống của của họ cần tới những lời nói dối nho nhỏ. Khi một lời nói dối nhỏ bỗng trở thành to, đó là khi lời nói dối trở nên nguy hiểm. Và mọi chuyện lại càng rắc rối hơn khi một vụ án mạng xảy ra...</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 28, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Reese Witherspoon","avatar":""},{"name":"Shailene Woodley","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Alexander Skarsgård","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"James Tupper","avatar":""},{"name":"Zoë Kravitz","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Iain Armitage","avatar":""},{"name":"Jeffrey Nordling","avatar":""},{"name":"Kathryn Newton","avatar":""},{"name":"Chloe Coleman","avatar":""},{"name":"Douglas Smith","avatar":""},{"name":"Cameron Crovetti","avatar":""},{"name":"Darby Camp","avatar":""},{"name":"Nicholas","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Böyük Kiçik Yalanlar","美丽心计","Pequeñas mentiras","Big Little Lies"]', 1784690324342);
