INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-vuong-trieu', 'Kiếm Vương Triều', 'Sword Dynasty', 'https://phimimg.com/upload/vod/20240116-1/7d3100421bdd7a3170d74e59536ad665.jpg', 'https://phimimg.com/upload/vod/20240116-1/e88712da3f213611696b45c11c376236.jpg', '<p>Từ sau khi liên tiếp tiêu diệt được 3 nước lớn là Hàn, Triệu, Ngụy, Vương triều Đại Tần đã bước vào thời kì thịnh thế chưa từng có. Những người tu hành cường đại có xuất thân không kém, ai cũng tự hào vì bản thân là người nước Tần. Chỉ có Đinh Ninh, chàng thiếu niên xuất thân bình thường nơi phố chợ kinh đô Trường Lăng của nước Tần, ngày nào cũng nghĩ phải làm sao để khiến Vương triều Đại Tần sụp đổ, phải làm sao để giết được Tần Hoàng đế đã tu hành đến cảnh giới thứ tám mà chưa có người nào mơ được đến kia.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 50, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Hiện","avatar":""},{"name":"Lý Nhất Đồng","avatar":""},{"name":"Liu Yi Jun","avatar":""},{"name":"Yao Di","avatar":""},{"name":"Yuanyuan Zhao","avatar":""},{"name":"Peter Ho","avatar":""},{"name":"Run-dong He","avatar":""},{"name":"Yun-tung Ho","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324342);
