INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-thien-tai-phan-3', 'Bác Sĩ Thiên Tài (Phần 3)', 'The Good Doctor (Season 3)', 'https://phimimg.com/upload/vod/20240116-1/591687e1f88afd6ac043664402fd6fd6.jpg', 'https://phimimg.com/upload/vod/20260104-1/dad3d329ca2ccd717d54a050421b8dd7.jpg', '<p>Shaun ra sức thúc đẩy một ca phẫu thuật tiệt căn nhằm cứu sống một bệnh nhân mới cưới. Ngoài ra, anh và bác sĩ Lever bắt đầu thử hẹn hò.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 19, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Freddie Highmore","avatar":""},{"name":"Antonia Thomas","avatar":""},{"name":"Nicholas Gonzalez","avatar":""},{"name":"Chuku Modu","avatar":""},{"name":"Beau Garrett","avatar":""},{"name":"Hill Harper","avatar":""},{"name":"Richard Schiff","avatar":""},{"name":"Will Yun Lee","avatar":""},{"name":"Fiona Gubelmann","avatar":""},{"name":"Christina Chang","avatar":""},{"name":"Paige Spara","avatar":""},{"name":"Jasika Nicole","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324342);
