INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-si-thien-tai-phan-3', 'Bác Sĩ Thiên Tài (Phần 3)', 'The Good Doctor (Season 3)', 'bác sĩ thiên tài (phần 3) the good doctor (season 3) freddie highmore antonia thomas nicholas gonzalez chuku modu beau garrett hill harper richard schiff will yun lee fiona gubelmann christina chang paige spara jasika nicole ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-hu-khong', 'Trở lại hư không', 'Back To Nowhere', 'https://phimimg.com/upload/vod/20260610-1/99609dfed4fc82a84950ded69c834dc9.jpg', 'https://phimimg.com/upload/vod/20260610-1/57c8d45098648579ec624aa5d6cc9ff7.jpg', '<p>Nữ sát thủ Bạch Dạ của Thập Giới Đường vì muốn báo thù cho mối huyết hải thâm thù từ vụ cả nhà bị sát hại khi còn nhỏ, đã bất chấp lệnh của sư phụ Doãn Cơ, tự ý ám sát Tể tướng Ứng Thời An. Tuy nhiên, Ứng Thời An đã giăng sẵn cạm bẫy chờ nàng sa lưới. Bạch Dạ bị thương ở mắt và rơi vào vòng vây, nhưng may mắn được vị công tử quý tộc Hoa Đô cứu giúp. Trong thời gian chăm sóc Bạch Dạ dưỡng thương, Hoa Đô và nàng dần nảy sinh tình cảm với nhau. Trong khi đó, Doãn Cơ liên tục ngăn cản Bạch Dạ báo thù, nhưng thực chất ông ta cũng đang che giấu một mục đích bí mật không thể tiết lộ. Sau khi đôi mắt của Bạch Dạ hồi phục, nàng và Hoa Đô chuẩn bị thành hôn. Thế nhưng đúng lúc ấy, nàng phát hiện Hoa Đô lại chính là con trai của Ứng Thời An. Vào ngày đại hôn, Ứng Thời An đích thân đến tham dự, còn Doãn Cơ cũng dẫn theo các sát thủ kéo đến. Một trận đại chiến trong hôn lễ sắp sửa bùng nổ.</p>', 'Full', 1, 'single', 'completed', 26, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ma Yujie","avatar":""},{"name":"Zhang Benyu","avatar":""},{"name":"He Congrui","avatar":""},{"name":"Huang Kaixiang","avatar":""},{"name":"Mao Fan","avatar":""},{"name":"Wei Jinsong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Back.to.Nowhere","剑归何处"]', 1784690324342);
