INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-thep-thiet-tham', 'Cảnh Sát Thép (Thiết Thám)', 'The Defected', 'https://phimimg.com/upload/vod/20260608-1/ace3f3d809204763a0392085898ac858.jpg', 'https://phimimg.com/upload/vod/20260608-1/9345be1c48c10652abd5724f99a0a6fe.jpg', '<p>Nội dung phim xoay quanh đội điều tra CID, cùng quá trình đưa những kẻ phạm tội quy án. Dưới sự chỉ đạo của nữ đốc sát Vạn Hi Hoa, một nữ tướng quyết đoán, chuyên nghiệp, đội cảnh ti gồm Giản Quốc Thự, Trình Vũ Sâm, Thượng Thăng và Vincent luôn cố gắng hoàn thành nhiệm vụ mọi lúc, mọi nơi. Tuy nhiên, Thượng Thăng lại đem lòng yêu mến cô gái xinh đẹp Dương Hiểu Di, con gái của một đại ca băng đảng xã hội đen. Phải bắt buộc lựa chọn giữa công việc và tình yêu, Thượng Thăng sẽ làm thế nào, liệu anh có thể vượt qua mọi chuyện để trở thành một cảnh sát hàng đầu.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 41, 2019, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Viên Vĩ Hào","avatar":""},{"name":"Huệ Anh Hồng","avatar":""},{"name":"Khương Hạo Văn","avatar":""},{"name":"Thái Tư Bối","avatar":""},{"name":"Hoàng Trí Hiền","avatar":""},{"name":"Dương Minh","avatar":""},{"name":"Vương Quân Hinh","avatar":""},{"name":"Đặng Bội Nghi","avatar":""},{"name":"Lương Liệt Duy","avatar":""},{"name":"Hứa Thiệu Hùng","avatar":""},{"name":"Ngô Đình Diệp","avatar":""},{"name":"Lâm Lợi","avatar":""},{"name":"Thạch Tu","avatar":""},{"name":"Trần Mẫn Chi","avatar":""},{"name":"Viên Văn Kiệt","avatar":""},{"name":"Tạ Đông Mẫn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["铁探","The Defected","鐵探"]', 1784690324342);
