INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-duyen-nguoi-yeu-tien-kiep', 'Nhân Duyên: Người Yêu Tiên Kiếp', 'Nhân Duyên: Người Yêu Tiên Kiếp', 'https://phimimg.com/upload/vod/20260605-1/6c942d4f8d68a42d9c50ee275f352144.jpg', 'https://phimimg.com/upload/vod/20260605-1/030b88b4d23600324216c5f5b068a164.jpg', '<p>Nhân Duyên: Người tình kiếp trước xoay quanh mối tình kéo dài nhiều kiếp giữa chàng trai si tình Trần Nhật và Quỳnh Mai, một cô gái xinh đẹp, dịu dàng. Chỉ vì không muốn quên đi mối tình dang dở với Mai từ kiếp trước, Trần Nhật đã quyết tâm chống lại luật luân hồi, tình nguyện ở bên Mai như một cái bóng vô hình bảo vệ cô khỏi những sóng gió cuộc đời. Rốt cuộc, mối tình kiếp trước này có vượt qua được mọi trở ngại để đến được với nhau không?</p>', 'Full', 1, 'single', 'completed', 39, 2019, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Lâm Vỹ Dạ","avatar":""},{"name":"Midu","avatar":""},{"name":"Le Huynh My Duyen","avatar":""},{"name":"Puka","avatar":""},{"name":"Thang Binh Trinh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Nhân Duyên: Người Yêu Tiên Kiếp"]', 1784690324342);
