INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ranh-gioi-ngay-dem', 'Ranh Giới Ngày Đêm', 'Day and Night', 'https://phimimg.com/upload/vod/20260604-1/deef420679097223d5374a74ed2fcd2b.jpg', 'https://phimimg.com/upload/vod/20260604-1/392c2bab346dbab2f8dea2044c3c27c8.jpg', '<p>Sau khi cha mình – một người tố giác sai phạm trong một tập đoàn lớn – tự sát, Koji Akashi trở về quê và phát hiện gia đình đang bị đẩy vào cảnh khốn cùng. Trong quá trình tìm kiếm sự thật đằng sau cái chết của cha, anh gặp Kitamura, chủ một trại trẻ mồ côi. Kitamura tuy bề ngoài hiền lành nhưng sẵn sàng phạm tội nếu điều đó giúp bảo vệ những đứa trẻ ở trại mồ côi. Dần dần, Koji bị cuốn vào vòng xoáy trả thù, công lý và tội ác.</p>', 'Full', 1, 'single', 'completed', 20, 2019, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shinnosuke Abe","avatar":""},{"name":"Masanobu Ando","avatar":""},{"name":"Kaya Kiyohara","avatar":""},{"name":"Tetsushi Tanaka","avatar":""},{"name":"Manami Konishi","avatar":""},{"name":"Reina Ikehata","avatar":""},{"name":"Shigeru Muroi","avatar":""},{"name":"Hiroyuki Watanabe","avatar":""},{"name":"Takashi Yamanaka","avatar":""},{"name":"Show Kasamatsu","avatar":""},{"name":"Ryo Fujimoto","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Day and Night","デイアンドナイト"]', 1784690324342);
