INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-ufo-phan-1', 'Truy Tìm UFO (Phần 1)', 'Project Blue Book (Season 1)', 'https://phimimg.com/upload/vod/20260526-1/f61f13abb78d1aa177d42912a4f0c2c5.jpg', 'https://phimimg.com/upload/vod/20260526-1/167e0b2495795962e3b4c3e5e95e5d52.jpg', '<p>Trong nhiều thập kỷ, Không quân Mỹ (USAF) đã giữ bản ghi chép tất cả các cuộc điều tra của họ về hoạt động ngoài Trái Đất trong một báo cáo tổng quát có tên mã là &quot;Dự án Sách Xanh&quot; (Project Blue Book). Hynek, nhà khoa học được Không quân Mỹ tuyển dụng để điều tra những lần nhìn thấy UFO và các hiện tượng liên quan. Mặc dù Hynek là một người hoài nghi UFO khi ông bắt đầu làm việc cho Không quân Mỹ, phần lớn những gì ông nghe và thấy qua nhiều năm làm dự án đã thách thức việc đưa ra những lời giải thích dễ dàng. Cuối cùng, kinh nghiệm đã biến ông thành một người có niềm tin cuồng nhiệt với những cuộc gặp gỡ UFO mà ông nghĩ có thể là sự tiếp xúc với cuộc sống ngoài hành tinh.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 33, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Aidan Gillen","avatar":""},{"name":"Michael Malarkey","avatar":""},{"name":"Laura Mennell","avatar":""},{"name":"Ksenia Solo","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Michael Harney","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Proyecto Blue Book","Проект «Синяя книга»","Project Blue Book"]', 1784690324342);
