INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nong-trai-chet-nguoi', 'Nông Trại Chết Người', 'The Farm', 'https://phimimg.com/upload/vod/20260522-1/221dc036f7edd66af9a13d1cfdf054ed.jpg', 'https://phimimg.com/upload/vod/20260522-1/1ccd54e285ff95d10f3cb4202307e1cd.jpg', '<p>Cặp đôi trẻ Nora và Alec đang trên đường trở về nhà sau một chuyến hành trình dài. Họ quyết định dừng chân nghỉ ngơi tại một thị trấn sa mạc, thế nhưng khi thức dậy vào sáng hôm sau, cả hai không còn ở trong căn phòng motel mà mình đã nhận trước đó. Ngay trong đêm, họ đã bị bắt cóc bởi một nhóm sát nhân điên cuồng đeo mặt nạ thú.&nbsp; Điều gì sẽ xảy ra nếu con người bị đối xử không khác gì gia súc chờ ngày xẻ thịt? Tại trang trại kinh hoàng này, ý tưởng dị hợm đó đã trở thành sự thật. Nora và Alec sớm nhận ra rằng họ không phải là những nạn nhân duy nhất bị nhốt trong chuồng, bị vỗ béo và ép ăn chỉ để chờ ngày bị tàn sát, mổ bụng và biến thành món ăn đặc sản cho những kẻ tra tấn biến thái. Đối với cặp đôi trẻ, một cuộc chiến khốc liệt để giành giật sự sống chính thức bắt đầu.</p>', 'Full', 1, 'single', 'completed', 19, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nora Yessayan","avatar":""},{"name":"Alec Gaylord","avatar":""},{"name":"Ken Volok","avatar":""},{"name":"Rob Tisdale","avatar":""},{"name":"Kelly Mis","avatar":""},{"name":"Jola Cora","avatar":""},{"name":"David Air","avatar":""},{"name":"Sandra Cruze","avatar":""},{"name":"Gael Carrion","avatar":""},{"name":"Julie Meghan Brown","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["مزرعه","The Farm"]', 1784690324342);
