INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-boonie-quay-ve-thoi-tien-su', 'Gấu Boonie: Quay Về Thời Tiền Sử', 'Boonie Bears: Blast into the Past', 'https://phimimg.com/upload/vod/20260429-1/f6dc49d367a269d6ded140aefb074026.jpg', 'https://phimimg.com/upload/vod/20260429-1/ca3a8c3de73b8a2e3ee9ac187ae54bd3.jpg', '<p>Khi đang tham quan một hang động cổ xưa, hai anh em gấu Briar, Bramble và tiều phu Vick bất ngờ bị đưa về thời tiền sử, nơi sinh sống của voi ma mút, hổ răng kiếm và vô số sinh vật kỳ lạ. Đối mặt với sự uy hiếp của bầy sói dữ, những nghi ngờ không ngừng từ người cổ đại, cùng các thiên tai tự nhiên bùng nổ diện rộng... một cuộc phiêu lưu ngoạn mục xoay quanh sự che chở và trưởng thành, tình yêu và lòng dũng cảm của nhóm bạn chính thức bắt đầu.</p>', 'Full', 1, 'hoathinh', 'completed', 23, 2019, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Wei","avatar":""},{"name":"Song Zuer","avatar":""},{"name":"Yingying Miu","avatar":""},{"name":"Tan Xiao","avatar":""},{"name":"Zhang Bingjun","avatar":""},{"name":"Angela Zhang","avatar":""},{"name":"Siqi Liu","avatar":""},{"name":"Pei Liu","avatar":""},{"name":"Yutian Meng","avatar":""},{"name":"周子瑜","avatar":""},{"name":"Joseph S. Lambert","avatar":""},{"name":"Siobhan Lumsden","avatar":""},{"name":"Nichalia Schwartz","avatar":""},{"name":"Nikki Stinson","avatar":""},{"name":"Chris Boike","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["熊出没6","熊出没大电影6","Boonie Bears: Blast Into The Past","Xiong chu mo yuan shi shi dai","熊出没：原始时代","熊出没6：原始时代","熊出没·原始时代","BONNIE BEAR AVENTURA EN LA 