INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-tinh-hon-nhan', 'Nội Tình Hôn Nhân', 'Till Death Do Us Part', 'https://phimimg.com/upload/vod/20260411-1/2350371e1398fb20024c81cc7ff47e87.jpg', 'https://phimimg.com/upload/vod/20260411-1/b30de4caeb0f40bf9e2b0ddb2798489f.jpg', '<p>Mã Thục Tương là doanh nhân chuyên sưu tầm đồ cổ và kinh doanh tác phẩm nghệ thuật. Nhân dịp kỷ niệm 20 năm ngày cưới với chồng là Tôn Dật, cô thuê nữ họa sĩ Hứa Hoặc Nhiên giúp cô vẽ một bức tranh, nhưng không ngờ trong quá trình phác họa, Tôn Dật và nữ họa sĩ lại nảy sinh tình cảm. Sau khi phát hiện chồng thay lòng, Thục Tương bèn tìm lại người em gái đã nhiều năm không liên lạc là Mã Thục Viên để hỗ trợ mình cứu vãn cuộc hôn nhân. Nhưng rồi sự tình lại ngày càng phức tạp hơn khi Thục Tương bắt đầu xiêu lòng trước bác sĩ Lâm Nhược Đức, người vốn yêu thầm cô từ lâu.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 29, 2019, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Tự Dao","avatar":""},{"name":"Viên Vĩ Hào","avatar":""},{"name":"La Trọng Khiêm","avatar":""},{"name":"Lý Giai Tâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Till Death Do Us Part","婚內情"]', 1784690324342);
