INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vao-ma-gioi-roi-day-irumakun-phan-1', 'Vào Ma Giới Rồi Đấy! Iruma-Kun (Phần 1)', 'Welcome To Demon School! Iruma-kun (Season 1)', 'vào ma giới rồi đấy! iruma-kun (phần 1) welcome to demon school! iruma-kun (season 1) ayumu murase ryohei kimura ayaka asai daisuke ono saori hayami takuya sato takaya kuroda mitsuki saiga yoshitaka yamaya nao toyama tetsuya kakihara kaede hondo gakuto kajiwara takuto yoshinaga genki okawa shunichi toki junko takeuchi shin iruma à l’école des démons डेमन स्कूल में आपका स्वागत है! इरुमा-कुन mairimashita! iruma-kun mairimashita! iruma-kun 2 mairimashita, iruma-kun mairimashita, iruma-kun 2 mairimashita! iruma-kun 3 魔入りました！入間くん４ 마계학교 이루마군 악마에 입문했습니다! 이루마 군 마계학교! 이루마군 iruma w szkole demonów อิรุมะคุงกับโรงเรียนปิศาจ welcome to demon-school, iruma-kun welcome to demon school, iruma-kun the demon, iruma-kun, came and enrolled! enrolled demon iruma! here comes the demon! iruma-kun welcome to demon school! iruma-kun 2 welcome to demon-school! iruma-kun 3 vào ma giới rồi đấy vào ma giới rồi đấy! iruma-kun vào ma giới rồi đấy iruma-kun 魔入りました！入間くん', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danny-go', 'Danny Go!', 'Danny Go!', 'https://phimimg.com/upload/vod/20260406-1/9ec2a74b05058fb3980e7f0419585bae.jpg', 'https://phimimg.com/upload/vod/20260406-1/decaafb54ae88cbc38c193d6ff2dc655.jpg', '<p>Sẵn sàng nhảy múa, ca hát và vui chơi? Cùng Danny Go và các bạn tham gia phiêu lưu vận động, hoạt động thư giãn đầu óc và những trò chơi học tập tương tác hấp dẫn dành cho trẻ.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 35, 2019, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Daniel Coleman","avatar":""},{"name":"Matthew Padgett","avatar":""},{"name":"Michael Finster","avatar":""},{"name":"Mindy Coleman","avatar":""},{"name":"Dominic Geralds","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Danny Go!"]', 1784690324342);
