INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-dao-cau-sinh-2-sat-co-sau-lung', 'Hoang Đảo Cầu Sinh 2: Sát Cơ Sau Lưng', 'Desert Island Survival 2: Behind The Murder (Stranded Deep 2: Murder In The Rear)', 'https://phimimg.com/upload/vod/20260320-1/16b33264c2be2588a1c5286a79cf55bd.jpg', 'https://phimimg.com/upload/vod/20260320-1/80aeb40f30e154598d3bc1c1d6854e19.jpg', '<p>Nhóm bạn gồm bốn người: Tô Cát, Tô Hân Nhiên, Hoa Gia Ý và Lý Trác cùng nhau ra khơi câu cá thì bất ngờ gặp sự cố, trôi dạt vào một hòn đảo hoang. Trong lúc cả bốn vừa phải tìm cách giải quyết vấn đề sinh tồn, vừa nỗ lực tìm đường rời đảo để trở về đất liền, họ vô tình chạm chán với băng nhóm của Bỉnh Cửu và Phì Anh – những kẻ đang lẩn trốn tội lỗi tại nơi này. Những tên tội phạm hung ác sẽ làm gì với họ? Liệu bốn người bọn họ có thể bình an trở về nhà hay không?</p>', 'Full', 1, 'single', 'completed', 17, 2019, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngụy Hiểu Đông","avatar":""},{"name":"Long Đức","avatar":""},{"name":"Lý Nam","avatar":""},{"name":"Khổng Tinh Tình","avatar":""},{"name":"Bồ Thịnh Nam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["荒岛求生2背后杀机"]', 1784690324342);
