INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('aspromonte-vung-dat-bi-lang-quen', 'Aspromonte: Vùng Đất Bị Lãng Quên', 'Aspromonte: Land of The Forgotten', 'https://phimimg.com/upload/vod/20260311-1/1f325552cf82f7280632c4b410565ea4.jpg', 'https://phimimg.com/upload/vod/20260311-1/b3deb85155ddeca9e9f4dbd4ca4a60ac.jpg', '<p>Năm 1951 tại Africo, ngôi làng nhỏ ở thung lũng phía nam Aspromonte, một phụ nữ qua đời khi sinh con vì không có con đường nào nối làng với bên ngoài, khiến bác sĩ không thể đến kịp. Bi kịch ấy đánh thức khát vọng đổi thay của người dân. Họ cùng nhau quyết tâm xây dựng lại con đường, như một cách giành lấy tương lai và thoát khỏi sự lãng quên giữa núi rừng cô lập.</p>', 'Full', 1, 'single', 'completed', 32, 2019, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Valeria Bruni Tedeschi","avatar":""},{"name":"Francesco Colella","avatar":""},{"name":"Marcello Fonte","avatar":""},{"name":"Marco Leonardi","avatar":""},{"name":"Sergio Rubini","avatar":""},{"name":"Elisabetta Gregoraci","avatar":""},{"name":"Romina Mondello","avatar":""},{"name":"Carlo Marrapodi","avatar":""},{"name":"Francesco Grillo","avatar":""},{"name":"Fabrizio Gifuni","avatar":""},{"name":"Fulvio Lucisano","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Aspromonte - La terra degli ultimi"]', 1784690324342);
