INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('aspromonte-vung-dat-bi-lang-quen', 'Aspromonte: Vùng Đất Bị Lãng Quên', 'Aspromonte: Land of The Forgotten', 'aspromonte: vùng đất bị lãng quên aspromonte: land of the forgotten valeria bruni tedeschi francesco colella marcello fonte marco leonardi sergio rubini elisabetta gregoraci romina mondello carlo marrapodi francesco grillo fabrizio gifuni fulvio lucisano aspromonte - la terra degli ultimi', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-nhan', 'Đồng Nhân', 'Copperman', 'https://phimimg.com/upload/vod/20260311-1/de3158bd1c54253f65297d9be92bfeec.jpg', 'https://phimimg.com/upload/vod/20260311-1/1afc9b71a0a6dde35dafb444ab5f99ad.jpg', '<p>Anselmo, chàng trai mang trí não của một đứa trẻ, sống lặng lẽ giữa những định kiến và xem thường. Khi tội ác bủa vây thị trấn, anh khoác lên mình thân phận Đồng Nhân - người hùng bí ẩn với bộ giáp đặc biệt do một thợ rèn chế tạo. Dưới lớp kim loại lạnh lẽo là trái tim trong trẻo và dũng cảm, sẵn sàng chống lại cái ác. Hành trình ấy không chỉ là cuộc chiến với tội phạm, mà còn là minh chứng rằng lòng thiện lương có thể tỏa sáng ở những tâm hồn thuần khiết nhất.</p>', 'Full', 1, 'single', 'completed', 24, 2019, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Luca Argentero","avatar":""},{"name":"Antonia Truppo","avatar":""},{"name":"Tommaso Ragno","avatar":""},{"name":"Galatea Ranzi","avatar":""},{"name":"Gianluca Gobbi","avatar":""},{"name":"Sebastian Dimulescu","avatar":""},{"name":"Angelica Bellucci","avatar":""},{"name":"Massimo Poggio","avatar":""},{"name":"Paolo Romano","avatar":""},{"name":"Gualtiero Burzi","avatar":""},{"name":"Luis Molteni","avatar":""},{"name":"Giulia Rebecca Urso","avatar":""},{"name":"Chiara Muscato","avatar":""},{"name":"Ewa Spadlo","avatar":""},{"name":"Francesco Marino","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Copperman - Um Herói Especial","Copperman - superbohater z miedzi","Мій тато - супергерой","Copperman"]', 1784690324342);
