INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dong-nhan', 'Đồng Nhân', 'Copperman', 'đồng nhân copperman luca argentero antonia truppo tommaso ragno galatea ranzi gianluca gobbi sebastian dimulescu angelica bellucci massimo poggio paolo romano gualtiero burzi luis molteni giulia rebecca urso chiara muscato ewa spadlo francesco marino copperman - um herói especial copperman - superbohater z miedzi мій тато - супергерой copperman', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-len-vi-sunny', 'Đứng Lên Vì Sunny', 'Standing Up for Sunny', 'https://phimimg.com/upload/vod/20260311-1/e76e7691f5e9194263e789f244ec7853.jpg', 'https://phimimg.com/upload/vod/20260311-1/38c31cd37c50ba1106310f8020101a30.jpg', '<p>Travis, một chàng trai sống khép kín và mắc bại não, bất ngờ rung động trước Sunny - nữ diễn viên hài đầy chân thành nhưng khiêm tốn. Tình cảm ấy thôi thúc anh bước ra khỏi vùng an toàn, đối diện với những mặc cảm và nỗi sợ của chính mình. Để chinh phục trái tim Sunny, Travis không chỉ cần dũng cảm thể hiện bản thân mà còn phải học cách tin vào giá trị của mình. Bộ phim là câu chuyện ấm áp về tình yêu, sự tự tin và hành trình vượt qua giới hạn để sống trọn vẹn.</p>', 'Full', 1, 'single', 'completed', 23, 2019, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"RJ Mitte","avatar":""},{"name":"Philippa Northeast","avatar":""},{"name":"Sam Reid","avatar":""},{"name":"Italia Hunt","avatar":""},{"name":"Ella Scott Lynch","avatar":""},{"name":"Radha Mitchell","avatar":""},{"name":"Barry Humphries","avatar":""},{"name":"Matt Nable","avatar":""},{"name":"Felix Williamson","avatar":""},{"name":"Sal Sharah","avatar":""},{"name":"Josh McConville","avatar":""},{"name":"Rachael Leahcar","avatar":""},{"name":"Megan Smart","avatar":""},{"name":"Facundo Hache Herrera","avatar":""},{"name":"Bronte Kellam-Pearson","avatar":""},{"name":"Kathleen O''","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Standing Up for Sunny"]', 1784690324343);
