INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-co-thap-nhi-cung', 'Thiên Cơ Thập Nhị Cung', 'The Mysterious World', 'https://phimimg.com/upload/vod/20260310-1/c33af07c4041a2c9eae17d33a729981b.jpg', 'https://phimimg.com/upload/vod/20260310-1/68b4b4ce577e1c9fa4bc0c1926c46669.jpg', '<p>Thẩm Hào, vì muốn minh oan cho cha và Thiên Cơ Thập Nhị Cung nên đã trà trộn vào Hình Luật Tư nhằm điều tra vụ án năm xưa, tại đây Thẩm Hào đã gặp được Vạn Quân Linh, công chúa đương triều, từ cặp đôi oan gia, cả hai đã dần bi thu hút bởi tính cách của nhau và bước lên con đường ái tình đầy chông gai và trắc trở cùng những vụ án bí ẩn kinh thiên động địa.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 21, 2019, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Văn Tác","avatar":""},{"name":"Hồ Ý Tuyền","avatar":""},{"name":"Trương Khiếu Ngang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tian Ji Shi Er Gong","天机十二宫"]', 1784690324343);
