INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-song-cuoc-doi-phan-1', 'Cơn Sóng Cuộc Đời (Phần 1)', 'Nazaré (Season 1)', 'https://phimimg.com/upload/vod/20260305-1/6868941d204812b87a61a9d7ebc92103.jpg', 'https://phimimg.com/upload/vod/20260305-1/9fe376dd74b12537a2b45bb8c547fbaf.jpg', '<p>Nazare là một cô gái trẻ quyết đoán và mạnh mẽ, làm việc chăm chỉ để tiết kiệm tiền cho ca phẫu thuật tốn kém của mẹ cô. Cô sẵn sàng làm tất cả mọi việc để cứu sống mẹ cô. Bạn trai và người yêu thời thơ ấu Toni luôn ở bên cạnh ủng hộ cô. Felix và vợ ông ta, Veronica, thuê Toni giết chết anh trai của Felix, ông Antonio Blanco, một ông trùm ngành gỗ địa phương, để Felix kế thừa chức vụ chủ tịch của công ty. Toni cho rằng ngôi nhà trong rừng của Blanco sẽ không có người, vì vậy anh ta thuyết phục Nazare đi cùng anh ta để trộm đồ, và cuối cùng cô đã bị camera giám sát bắt gặp. Trong vụ cướp và giữa đống lửa, Nazare đã cứu mạng Duarte Blanco. Duarte là người thừa kế giàu có nhưng chỉ đam mê rượu, gái, không quan tâm đến công việc kinh doanh của gia đình Blanco. Sự thân thiết ngày càng tăng giữa Nazare và Duarte trởthành phương châm hoàn hảo để Felix đưa ra lời đề nghị mà liệu Nazare có thể từ chối: phản bội Duarte để đổi lấy chi phí phẫu thuật cho mẹ cô.</p>', 'Hoàn Tất (70/70)', 70, 'series', 'completed', 37, 2019, 'Lồng Tiếng', 'FHD', 'Bồ Đào Nha', 0, '[{"name":"Pedro Luzindro","avatar":""},{"name":"João Maria Maneira","avatar":""},{"name":"Carolina Loureiro","avatar":""},{"name":"Afonso Pimentel","avatar":""},{"name":"José Mata","avatar":""},{"name":"Pedro Rovisco","avatar":""},{"name":"Inês Fouto","avatar":""},{"name":"Ana Lopes","avatar":""},{"name":"Tiago Teotónio Pereira","avatar":""},{"name":"Heitor Lourenço","avatar":""},{"name":"Manuela Couto","avatar":""},{"name":"David Henriques","avatar":""},{"name":"Pedro Rodil","avatar":""},{"name":"Luís Oliveira","avatar":""},{"name":"António Maria","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lua de Sal","Flor de Sal","Nazaré"]', 1784690324343);
